/** ASTANGA_DATA — очищено от вики-маркеров */
export const ASTANGA_DATA = [
  {
    sthana: "Сутрастхана",
    number: 1,
    lang: "sa",
    content: [
      { type: "heading", heading: "Аюскамия — о стремлении к долгой жизни" },
      { type: "text", text: "Глава 1 Сутрастханы Астанга-санграхи посвящена теме «о стремлении к долгой жизни». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "रागादिरोगाः सहजाः समूला येना ऽशुसर्वे जगतो ऽप्यपास्ताः तमेकवैद्यं शिरसा नमामि वैद्यागमज्ञांश्च पितामहादीन्", text: "rāgādirogāḥ sahajāḥ samūlā yenā 'śusarve jagato 'pyapāstāḥ tamekavaidyaṃ śirasā namāmi vaidyāgamajñāṃśca pitāmahādīn" },
      { type: "verse", number: "2", sanskrit: "अथात आयुष्कामीयं नामाध्यायं व्याख्यास्यामः इति ह स्मा आहुरात्रेयादयो महर्षयः", text: "athāta āyuṣkāmīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smā āhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "3", sanskrit: "आयुः कामयमानेन धर्मार्थसुखसाधनम् आयुर्वेदोपदेशेषु विधेयः परमादरः", text: "āyuḥ kāmayamānena dharmārthasukhasādhanam āyurvedopadeśeṣu vidheyaḥ paramādaraḥ" },
      { type: "verse", number: "4", sanskrit: "आयुर्वेदामृतं सार्वं ब्रह्मा सनातनम् ददौ दक्षाय सो ऽश्विभ्यां तौ शतक्रतवे ततः", text: "āyurvedāmṛtaṃ sārvaṃ brahmā sanātanam dadau dakṣāya so 'śvibhyāṃ tau śatakratave tataḥ" },
      { type: "verse", number: "5", sanskrit: "धर्मार्थकाममोक्षाणां विघ्नकारिभिरामयैः नरेषु पीड्यमानेषु पुरस्कृत्य पुनर्वसुम्", text: "dharmārthakāmamokṣāṇāṃ vighnakāribhirāmayaiḥ nareṣu pīḍyamāneṣu puraskṛtya punarvasum" },
      { type: "verse", number: "6", sanskrit: "धन्वन्तरिभरद्वाजनिमिकाश्यपकश्यपाः महर्धयो महात्मानस्तथा लम्बायनादयः", text: "dhanvantaribharadvājanimikāśyapakaśyapāḥ mahardhayo mahātmānastathā lambāyanādayaḥ" },
      { type: "verse", number: "7", sanskrit: "शतक्रतुमुपाजग्मुः शरण्यममरेश्वरम् तान्दृष्ट्वैव सहस्राक्षो निजगाद यथागमम्", text: "śatakratumupājagmuḥ śaraṇyamamareśvaram tāndṛṣṭvaiva sahasrākṣo nijagāda yathāgamam" },
      { type: "verse", number: "8", sanskrit: "आयुषः पालनं वेदमुपवेदमथर्वणः कायबालग्रहोर्ध्वाङ्गशल्यदंष्ट्राजरावृषैः", text: "āyuṣaḥ pālanaṃ vedamupavedamatharvaṇaḥ kāyabālagrahordhvāṅgaśalyadaṃṣṭrājarāvṛṣaiḥ" },
      { type: "verse", number: "9", sanskrit: "गतमष्टाङ्गतां पुण्यं बुबुधे यं पितामहः गृहीत्वा ते तमाम्रायं प्रकाश्य च परस्परम्", text: "gatamaṣṭāṅgatāṃ puṇyaṃ bubudhe yaṃ pitāmahaḥ gṛhītvā te tamāmrāyaṃ prakāśya ca parasparam" },
      { type: "verse", number: "10", sanskrit: "आययुर्मानुषं लोकं मुदिताः परमर्षयः स्थित्यर्थमायुर्वेदस्य ते ऽथ तन्त्राणि चक्रिरे", text: "āyayurmānuṣaṃ lokaṃ muditāḥ paramarṣayaḥ sthityarthamāyurvedasya te 'tha tantrāṇi cakrire" },
      { type: "verse", number: "11", sanskrit: "कृत्वा ऽग्निवेशहारीतभेडमाण्डव्यसुश्रुतान् करालादींश्च तच्छिष्यान् ग्राहयामासुरादृताः", text: "kṛtvā 'gniveśahārītabheḍamāṇḍavyasuśrutān karālādīṃśca tacchiṣyān grāhayāmāsurādṛtāḥ" },
      { type: "verse", number: "12", sanskrit: "स्वं स्वं तन्त्रं ततस्ते ऽपि चक्रुस्तानि कृतानि च गुरून् संश्रावयामासुः सर्षिसङ्घान्सुमेधसः", text: "svaṃ svaṃ tantraṃ tataste 'pi cakrustāni kṛtāni ca gurūn saṃśrāvayāmāsuḥ sarṣisaṅghānsumedhasaḥ" },
      { type: "verse", number: "13", sanskrit: "तैः प्रशस्तानि तान्येषां प्रतिष्ठां भुवि लेभिरे तेषामेकैकमव्यापि समस्तव्याधिसाधने", text: "taiḥ praśastāni tānyeṣāṃ pratiṣṭhāṃ bhuvi lebhire teṣāmekaikamavyāpi samastavyādhisādhane" },
      { type: "verse", number: "14", sanskrit: "प्रतितन्त्राभियोगे तु पुरुषायुषसंक्षयः भवत्यध्ययनेनैव यस्मात् प्रोक्तः पुनः पुनः", text: "pratitantrābhiyoge tu puruṣāyuṣasaṃkṣayaḥ bhavatyadhyayanenaiva yasmāt proktaḥ punaḥ punaḥ" },
      { type: "verse", number: "15", sanskrit: "तन्त्रकारैः स एव ऽर्थः क्वचित् क्श्चिद्विशेषतः ते ऽर्थप्रत्यायनपरा वचने यच्च नादृताः", text: "tantrakāraiḥ sa eva 'rthaḥ kvacit kścidviśeṣataḥ te 'rthapratyāyanaparā vacane yacca nādṛtāḥ" },
      { type: "verse", number: "16", sanskrit: "सर्वतन्त्राण्यतः प्रायः संहृत्या ऽष्टाङ्गसङ्ग्रहः अस्थानविस्तराक्षेपपुनरुक्तादिवर्जितः", text: "sarvatantrāṇyataḥ prāyaḥ saṃhṛtyā 'ṣṭāṅgasaṅgrahaḥ asthānavistarākṣepapunaruktādivarjitaḥ" },
      { type: "verse", number: "17", sanskrit: "हेतुलिङ्गौषधस्कन्धत्रयमात्रनिबन्धनः विनिगूढार्थतत्वानां प्रदेशानां प्रकाशकः", text: "hetuliṅgauṣadhaskandhatrayamātranibandhanaḥ vinigūḍhārthatatvānāṃ pradeśānāṃ prakāśakaḥ" },
      { type: "verse", number: "18", sanskrit: "स्वान्यतन्त्रविरोधानां भूयिष्ठं विनिवर्तकः युगानुरूपसन्दर्भो विभागेन करिष्यते", text: "svānyatantravirodhānāṃ bhūyiṣṭhaṃ vinivartakaḥ yugānurūpasandarbho vibhāgena kariṣyate" },
      { type: "verse", number: "19", sanskrit: "नित्योपयोगि दुर्बोधं सर्वाङ्गव्यापि भावतः सङ्गृहीतं विशेषेण यत्र कायचिकित्सितम्", text: "nityopayogi durbodhaṃ sarvāṅgavyāpi bhāvataḥ saṅgṛhītaṃ viśeṣeṇa yatra kāyacikitsitam" },
      { type: "verse", number: "20", sanskrit: "न मात्रामात्रमप्यत्र किच्चिदागमवर्जितम् ते ऽर्थाःस ग्रन्थबन्धश्च सङ्क्षेपाय क्रमो ऽन्यथा", text: "na mātrāmātramapyatra kiccidāgamavarjitam te 'rthāḥsa granthabandhaśca saṅkṣepāya kramo 'nyathā" },
      { type: "verse", number: "21", sanskrit: "वायुः पित्तं कफश्चेति त्रयो दोषाः समासतः प्रत्येकं ते त्रिधा वृद्धिक्षयसाम्यविभेदयः", text: "vāyuḥ pittaṃ kaphaśceti trayo doṣāḥ samāsataḥ pratyekaṃ te tridhā vṛddhikṣayasāmyavibhedayaḥ" },
      { type: "verse", number: "22", sanskrit: "उत्कृष्टमध्याल्पतया त्रिधा वृद्धिक्षयावपि विकृता ऽविकृता देहं घ्नन्ति ते वर्त्तयन्ति च", text: "utkṛṣṭamadhyālpatayā tridhā vṛddhikṣayāvapi vikṛtā 'vikṛtā dehaṃ ghnanti te varttayanti ca" },
      { type: "verse", number: "23", sanskrit: "ते व्यापिनो ऽपि हृन्नाभ्योरधोमध्योर्ध्वसंश्रयाः वयोहोरात्रिभुक्तानां ते ऽन्तमध्यादिगाः क्रमात्", text: "te vyāpino 'pi hṛnnābhyoradhomadhyordhvasaṃśrayāḥ vayohorātribhuktānāṃ te 'ntamadhyādigāḥ kramāt" },
      { type: "verse", number: "24", sanskrit: "तैर्भवेद्विषमस्तीक्ष्णो मन्दश्चाग्निः समैः समः कोष्ठः क्रूरो मृदुर्मध्यो मध्यः स्यात्तैः समैरपि", text: "tairbhavedviṣamastīkṣṇo mandaścāgniḥ samaiḥ samaḥ koṣṭhaḥ krūro mṛdurmadhyo madhyaḥ syāttaiḥ samairapi" },
      { type: "verse", number: "25", sanskrit: "शुक्रार्तवस्थैर्जन्मादौ विषेणेव विषक्रिमेः तैश्च तिस्रः प्रकृतयो हीनमध्योत्तमाः पृथक्", text: "śukrārtavasthairjanmādau viṣeṇeva viṣakrimeḥ taiśca tisraḥ prakṛtayo hīnamadhyottamāḥ pṛthak" },
      { type: "verse", number: "26", sanskrit: "समधातुः समस्तासु श्रेष्ठा निन्द्या द्विदोषजाः तत्र रूक्षो लघु शीतः खरः सूक्ष्मश्चलो ऽनिलः", text: "samadhātuḥ samastāsu śreṣṭhā nindyā dvidoṣajāḥ tatra rūkṣo laghu śītaḥ kharaḥ sūkṣmaścalo 'nilaḥ" },
      { type: "verse", number: "27", sanskrit: "पित्तं सस्नेहतीक्ष्णोष्णं लघु विस्रं सरं द्रवम् स्निग्धः शीतो गुरुर्मन्दः श्लक्ष्णो मृत्स्नः स्थिरः", text: "pittaṃ sasnehatīkṣṇoṣṇaṃ laghu visraṃ saraṃ dravam snigdhaḥ śīto gururmandaḥ ślakṣṇo mṛtsnaḥ sthiraḥ" },
      { type: "verse", number: "28", sanskrit: "संसर्गः सन्निपातश्च तद्वित्रिक्षयकोपतः तौ षोढा दशधा चोक्तावुत्कर्षादिविकल्पनात्", text: "saṃsargaḥ sannipātaśca tadvitrikṣayakopataḥ tau ṣoḍhā daśadhā coktāvutkarṣādivikalpanāt" },
      { type: "verse", number: "29", sanskrit: "रसासृङ्मांसमेदोस्थिमज्जशुक्राणि धातवः सप्त दूष्या मला मूत्रशकृत्स्वेदादयो ऽपि च", text: "rasāsṛṅmāṃsamedosthimajjaśukrāṇi dhātavaḥ sapta dūṣyā malā mūtraśakṛtsvedādayo 'pi ca" },
      { type: "verse", number: "30", sanskrit: "रसादिस्थेषु दोषेषु व्याधयः सम्भवन्ति ये तज्जानित्युपचारेण तानाहुर्घृतदाहवत्", text: "rasādistheṣu doṣeṣu vyādhayaḥ sambhavanti ye tajjānityupacāreṇa tānāhurghṛtadāhavat" },
      { type: "verse", number: "31", sanskrit: "प्रीणनं जीवनं लेपः स्नेहो धारणपूरणे गर्भोत्पादश्च कर्माणि धातूनां क्रमशो विदुः", text: "prīṇanaṃ jīvanaṃ lepaḥ sneho dhāraṇapūraṇe garbhotpādaśca karmāṇi dhātūnāṃ kramaśo viduḥ" },
      { type: "verse", number: "32", sanskrit: "शरीरं धारयन्त्येते धात्वाहारश्च सर्वदा वृद्धिः समानैः सर्वेषां विपरीतैर्विपर्ययः", text: "śarīraṃ dhārayantyete dhātvāhāraśca sarvadā vṛddhiḥ samānaiḥ sarveṣāṃ viparītairviparyayaḥ" },
      { type: "verse", number: "33", sanskrit: "रसाः स्वाद्वम्ललवणतिक्तोषणकषायकाः षड् द्रव्यमाश्रितास्ते च यथापूर्वं बलावहाः", text: "rasāḥ svādvamlalavaṇatiktoṣaṇakaṣāyakāḥ ṣaḍ dravyamāśritāste ca yathāpūrvaṃ balāvahāḥ" },
      { type: "verse", number: "34", sanskrit: "तत्राद्या मारुतं घ्नन्ति त्रयस्तिक्तादयः कफम् कषायतिक्तमधुराः पित्तमन्ये तु कुर्वते", text: "tatrādyā mārutaṃ ghnanti trayastiktādayaḥ kapham kaṣāyatiktamadhurāḥ pittamanye tu kurvate" },
      { type: "verse", number: "35", sanskrit: "शमनं कोपनं स्वस्थहितं द्रव्यमिति त्रिधा उष्णशीतगुणोत्कर्षात्तत्र वीर्यं द्विधा स्मृतम्", text: "śamanaṃ kopanaṃ svasthahitaṃ dravyamiti tridhā uṣṇaśītaguṇotkarṣāttatra vīryaṃ dvidhā smṛtam" },
      { type: "verse", number: "36", sanskrit: "त्रिधा विपाको द्रव्यस्य स्वाद्वम्लकटुकात्मकः गुरुमन्दहिमस्निग्धश्लक्ष्णसान्द्रमृदुस्थिराः", text: "tridhā vipāko dravyasya svādvamlakaṭukātmakaḥ gurumandahimasnigdhaślakṣṇasāndramṛdusthirāḥ" },
      { type: "verse", number: "37", sanskrit: "गुणाः ससूक्ष्मविशदा विंशतिः सविपर्ययाः इन्द्रियार्था व्यवायी च विकाषी चापरे गुणाः", text: "guṇāḥ sasūkṣmaviśadā viṃśatiḥ saviparyayāḥ indriyārthā vyavāyī ca vikāṣī cāpare guṇāḥ" },
      { type: "verse", number: "38", sanskrit: "व्यवायी देहमखिलं व्याप्य पाकाय कल्पते विकाषी विकषन् धातून् सन्धिबन्धान् विमुञ्चति", text: "vyavāyī dehamakhilaṃ vyāpya pākāya kalpate vikāṣī vikaṣan dhātūn sandhibandhān vimuñcati" },
      { type: "verse", number: "39", sanskrit: "सरतीक्ष्णप्रकर्षौ तु कैश्चित्तौ परिकीर्त्तितौ सत्त्वं रजस्तमश्चेति त्रयः प्रोक्ता महागुणाः", text: "saratīkṣṇaprakarṣau tu kaiścittau parikīrttitau sattvaṃ rajastamaśceti trayaḥ proktā mahāguṇāḥ" },
      { type: "verse", number: "40", sanskrit: "कालार्थकर्मणां योगो हीनमिथ्यातिमात्रकः सम्यग्योगश्च विज्ञेयो रोगारोग्यैककारणम्", text: "kālārthakarmaṇāṃ yogo hīnamithyātimātrakaḥ samyagyogaśca vijñeyo rogārogyaikakāraṇam" },
      { type: "verse", number: "41", sanskrit: "रोगस्तु दोषवैषम्यं दोषसाम्यमरोगता निजागन्तुविभागेन रोगाश्च द्विविधा मताः", text: "rogastu doṣavaiṣamyaṃ doṣasāmyamarogatā nijāgantuvibhāgena rogāśca dvividhā matāḥ" },
      { type: "verse", number: "42", sanskrit: "तेषां कायमनोभेदादधिष्ठानमपि द्विधा रजस्तमश्च मनसो द्वौ च दोषवुदाहृतौ", text: "teṣāṃ kāyamanobhedādadhiṣṭhānamapi dvidhā rajastamaśca manaso dvau ca doṣavudāhṛtau" },
      { type: "verse", number: "43", sanskrit: "दर्शनस्पर्शनप्रश्नैः परीक्षेत च रोगिणम् रोगं निदानप्राग्रूपलक्षणोपशयाप्तिभिः", text: "darśanasparśanapraśnaiḥ parīkṣeta ca rogiṇam rogaṃ nidānaprāgrūpalakṣaṇopaśayāptibhiḥ" },
      { type: "verse", number: "44", sanskrit: "भूमिदेहप्रभेदेन देशमाहुरिह द्विधा जाङ्गलं वातभूयिष्ठमानूपं तु कफोल्बणम्", text: "bhūmidehaprabhedena deśamāhuriha dvidhā jāṅgalaṃ vātabhūyiṣṭhamānūpaṃ tu kapholbaṇam" },
      { type: "verse", number: "45", sanskrit: "साधारणं सममलं त्रिधा भूदेशमादिशेत् क्षणादिव्यार्ध्यवस्था च कालो भैषज्ययोगकृत्", text: "sādhāraṇaṃ samamalaṃ tridhā bhūdeśamādiśet kṣaṇādivyārdhyavasthā ca kālo bhaiṣajyayogakṛt" },
      { type: "verse", number: "46", sanskrit: "शोधनं शमनं चेति समासादौषधं द्विधा शरीरजानां दोषाणां क्रमेण परमौषधम्", text: "śodhanaṃ śamanaṃ ceti samāsādauṣadhaṃ dvidhā śarīrajānāṃ doṣāṇāṃ krameṇa paramauṣadham" },
      { type: "verse", number: "47", sanskrit: "वस्तिर्विरेको वमनं तथा तैलं घृतं मधु धीधैर्यात्मादिविज्ञानं मनोदोषौषधं परम्", text: "vastirvireko vamanaṃ tathā tailaṃ ghṛtaṃ madhu dhīdhairyātmādivijñānaṃ manodoṣauṣadhaṃ param" },
      { type: "verse", number: "48", sanskrit: "तन्त्रस्यास्य परं चातो वक्ष्यते ऽध्यायसङ्ग्रहः आयुष्कामीयशिष्यार्थदिनर्तुव्याध्यसम्भवाः", text: "tantrasyāsya paraṃ cāto vakṣyate 'dhyāyasaṅgrahaḥ āyuṣkāmīyaśiṣyārthadinartuvyādhyasambhavāḥ" },
      { type: "verse", number: "49", sanskrit: "द्रवान्नज्ञानसंरक्षाविरुद्धान्नान्नपानिकाः मात्राशितौषधज्ञानश्रेष्ठशुध्यादिसङ्ग्रहाः", text: "dravānnajñānasaṃrakṣāviruddhānnānnapānikāḥ mātrāśitauṣadhajñānaśreṣṭhaśudhyādisaṅgrahāḥ" },
      { type: "verse", number: "50", sanskrit: "महाकषायविविधद्रव्यादिरसभेदकाः दोषादिज्ञानतद्भेदतत्क्रिया रोगभेषजम्", text: "mahākaṣāyavividhadravyādirasabhedakāḥ doṣādijñānatadbhedatatkriyā rogabheṣajam" },
      { type: "verse", number: "51", sanskrit: "व्द्यैषधस्नेहनस्वेदशुध्यास्थापननावनम् धूमगण्डूषदृक्सेकतृप्तियन्त्रजलौकसः", text: "vdyaiṣadhasnehanasvedaśudhyāsthāpananāvanam dhūmagaṇḍūṣadṛksekatṛptiyantrajalaukasaḥ" },
      { type: "verse", number: "52", sanskrit: "सिराविधिः शल्यविधिः शस्त्रक्षाराग्निकर्मकाः चत्वारिंशदिमे ऽध्यायः सूत्रम् शारीरमुच्यते", text: "sirāvidhiḥ śalyavidhiḥ śastrakṣārāgnikarmakāḥ catvāriṃśadime 'dhyāyaḥ sūtram śārīramucyate" },
      { type: "verse", number: "53", sanskrit: "पुत्रार्थगर्भावक्रान्तिचर्याव्यापच्छरीरजाः सिरामर्मप्रकृत्याख्या विकृताङ्गेहितामयाः", text: "putrārthagarbhāvakrānticaryāvyāpaccharīrajāḥ sirāmarmaprakṛtyākhyā vikṛtāṅgehitāmayāḥ" },
      { type: "verse", number: "54", sanskrit: "सदूता द्वादशाध्यायाः निदानं सार्वरौगिकम् ज्वरासृक्श्वासयक्ष्मादिमदाद्यर्शोतिसारिणाम्", text: "sadūtā dvādaśādhyāyāḥ nidānaṃ sārvaraugikam jvarāsṛkśvāsayakṣmādimadādyarśotisāriṇām" },
      { type: "verse", number: "55", sanskrit: "मूत्राघातप्रमेहाणां विद्रध्याद्युदरस्य च पाण्डुकुष्ठानिलार्त्तानां वातास्रस्य च षोडश", text: "mūtrāghātapramehāṇāṃ vidradhyādyudarasya ca pāṇḍukuṣṭhānilārttānāṃ vātāsrasya ca ṣoḍaśa" },
      { type: "verse", number: "56", sanskrit: "चिकित्साज्वरयोरस्रकासयोः श्वासयक्ष्मणोः वमौ मदात्यये ऽर्शस्सु विशि द्वौ द्वौ च मूत्रिते", text: "cikitsājvarayorasrakāsayoḥ śvāsayakṣmaṇoḥ vamau madātyaye 'rśassu viśi dvau dvau ca mūtrite" },
      { type: "verse", number: "57", sanskrit: "विद्रधौ गुल्मजठरपाण्डुशोफविसर्पिषु कुष्टश्वित्रानिलव्याधिवातास्रेषु चिकित्सितम्", text: "vidradhau gulmajaṭharapāṇḍuśophavisarpiṣu kuṣṭaśvitrānilavyādhivātāsreṣu cikitsitam" },
      { type: "verse", number: "58", sanskrit: "चतुर्विशतिरध्यायाः कल्पसिद्धिरतःपरम् कल्पो वमेर्विरेकस्य तत्सिद्धिर्बास्तिकल्पना", text: "caturviśatiradhyāyāḥ kalpasiddhirataḥparam kalpo vamervirekasya tatsiddhirbāstikalpanā" },
      { type: "verse", number: "59", sanskrit: "कल्पश्च सिद्धबस्तीनां सिद्धिर्बस्त्यनुवासयोः द्रव्यकल्पो ऽष्टमः स्थानमत उत्तरमुत्तरम्", text: "kalpaśca siddhabastīnāṃ siddhirbastyanuvāsayoḥ dravyakalpo 'ṣṭamaḥ sthānamata uttaramuttaram" },
      { type: "verse", number: "60", sanskrit: "बालोपचरणे व्याधिग्रहज्ञाननिषेधने स्नाने पृथग्ग्रहे भूते द्वावुन्मादे स्मृतिक्षये", text: "bālopacaraṇe vyādhigrahajñānaniṣedhane snāne pṛthaggrahe bhūte dvāvunmāde smṛtikṣaye" },
      { type: "verse", number: "61", sanskrit: "वर्त्मसन्धिगतौ द्वौ द्वौ दृक्तमोलिङ्गनाशिषु सर्वदृक्स्यन्ददृक्पाके कर्णनासामुखेषु च", text: "vartmasandhigatau dvau dvau dṛktamoliṅganāśiṣu sarvadṛksyandadṛkpāke karṇanāsāmukheṣu ca" },
      { type: "verse", number: "62", sanskrit: "मूर्ध्नि व्रणे तथा द्वौ द्वौ सद्योभङ्गे भगन्दरे ग्रन्थ्यादौ क्षुद्ररोगेषु गुह्यरोगे पृथग्द्वयम्", text: "mūrdhni vraṇe tathā dvau dvau sadyobhaṅge bhagandare granthyādau kṣudrarogeṣu guhyaroge pṛthagdvayam" },
      { type: "verse", number: "63", sanskrit: "विषे द्वौ भुजगे कीटे द्वौ च लूतासु मूषिके विषे विषोपयोगे च तथा ऽध्यायो रसायने", text: "viṣe dvau bhujage kīṭe dvau ca lūtāsu mūṣike viṣe viṣopayoge ca tathā 'dhyāyo rasāyane" },
      { type: "verse", number: "64", sanskrit: "वाजीकरणमुद्दिश्य पञ्चाशो ऽष्टाङ्गपूरणः पञ्चाशदध्यायशतं षड्भिः स्थानैः समीरितम्", text: "vājīkaraṇamuddiśya pañcāśo 'ṣṭāṅgapūraṇaḥ pañcāśadadhyāyaśataṃ ṣaḍbhiḥ sthānaiḥ samīritam" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 2,
    lang: "sa",
    content: [
      { type: "heading", heading: "Дина чарья — ежедневный режим здоровья" },
      { type: "text", text: "Глава 2 Сутрастханы Астанга-санграхи посвящена теме «ежедневный режим здоровья». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातः शिष्योपनयनीयमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ śiṣyopanayanīyamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "गुरुभक्तो ऽभियुक्तो ऽतियुक्तो धीस्मृतिपाटवैः ऋज्वास्यनासानयनस्तनुस्निग्धनखच्छविः", text: "gurubhakto 'bhiyukto 'tiyukto dhīsmṛtipāṭavaiḥ ṛjvāsyanāsānayanastanusnigdhanakhacchaviḥ" },
      { type: "verse", number: "3", sanskrit: "ब्रह्मचारी जितद्वन्द्वो धीरः सुचरितः स्थिरः षण्मासानुषितः शक्लो लज्जाशौचकुलान्वितः", text: "brahmacārī jitadvandvo dhīraḥ sucaritaḥ sthiraḥ ṣaṇmāsānuṣitaḥ śaklo lajjāśaucakulānvitaḥ" },
      { type: "verse", number: "4", sanskrit: "शिष्यो ऽध्याप्यो गतो यावदन्तं तन्त्रार्थकर्मणाम् ना ऽकालविद्युत्स्तनिते भूकम्पे राहुदर्शने", text: "śiṣyo 'dhyāpyo gato yāvadantaṃ tantrārthakarmaṇām nā 'kālavidyutstanite bhūkampe rāhudarśane" },
      { type: "verse", number: "5", sanskrit: "पञ्चदश्यामचन्द्रायां परोक्षे वा गुरोः पठेत् नातिच्छिन्नपदं नातिमन्दं नात्युच्चनीचकैः", text: "pañcadaśyāmacandrāyāṃ parokṣe vā guroḥ paṭhet nāticchinnapadaṃ nātimandaṃ nātyuccanīcakaiḥ" },
      { type: "verse", number: "6", sanskrit: "हीनान्यवेष आचार्यं पर्युपासीत राजवत् शयीत सुप्त एवास्मिन्नुत्तिष्ठेतास्य पूर्वतः", text: "hīnānyaveṣa ācāryaṃ paryupāsīta rājavat śayīta supta evāsminnuttiṣṭhetāsya pūrvataḥ" },
      { type: "verse", number: "7", sanskrit: "न ब्रूयात् केवलं नाम ना ऽसाध्वपि विनाटयेत् अभेद्यो ऽनुद्धतः स्तब्धः सूनृतः प्रियदर्शनः", text: "na brūyāt kevalaṃ nāma nā 'sādhvapi vināṭayet abhedyo 'nuddhataḥ stabdhaḥ sūnṛtaḥ priyadarśanaḥ" },
      { type: "verse", number: "8", sanskrit: "बहुश्रुतः कालवेदी ज्ञातग्रन्थो ऽर्थशास्त्रवित् अनाथान् रोगिणो यश्च पुत्रवत् समुपाचरेत्", text: "bahuśrutaḥ kālavedī jñātagrantho 'rthaśāstravit anāthān rogiṇo yaśca putravat samupācaret" },
      { type: "verse", number: "9", sanskrit: "गुरुणा समनुज्ञातः स भिषक्छब्दमश्नुते यस्तु केवलशास्त्रज्ञः कर्मस्वपरिनिष्ठितः", text: "guruṇā samanujñātaḥ sa bhiṣakchabdamaśnute yastu kevalaśāstrajñaḥ karmasvapariniṣṭhitaḥ" },
      { type: "verse", number: "10", sanskrit: "स मुह्यत्यातुरं प्राप्य प्राप्य भीरुरिवाहवम् यः पुनः कुरुते कर्म धार्ष्ट्याच्छास्त्रविवर्ज्जितः", text: "sa muhyatyāturaṃ prāpya prāpya bhīrurivāhavam yaḥ punaḥ kurute karma dhārṣṭyācchāstravivarjjitaḥ" },
      { type: "verse", number: "11", sanskrit: "स सत्सु गर्हामाप्नेति वधं चर्च्छति राजतः हेतौ लिङ्गे प्रशमने रोगाणामपुनर्भवे", text: "sa satsu garhāmāpneti vadhaṃ carcchati rājataḥ hetau liṅge praśamane rogāṇāmapunarbhave" },
      { type: "verse", number: "12", sanskrit: "ज्ञानं चतुर्विधं यस्य स राजार्हो भिषक्तमः शस्त्रं शास्त्राणि सलिलं गुणदोषप्रवृत्तये", text: "jñānaṃ caturvidhaṃ yasya sa rājārho bhiṣaktamaḥ śastraṃ śāstrāṇi salilaṃ guṇadoṣapravṛttaye" },
      { type: "verse", number: "13", sanskrit: "पात्रापेक्षीण्यतः प्रज्ञां बाहुश्रुत्येन बृंहयेत् प्रदीपभूतं शास्त्रं हि दर्शनं विपुला मतिः", text: "pātrāpekṣīṇyataḥ prajñāṃ bāhuśrutyena bṛṃhayet pradīpabhūtaṃ śāstraṃ hi darśanaṃ vipulā matiḥ" },
      { type: "verse", number: "14", sanskrit: "ताभ्यां भिषक् सुयुक्ताभ्यां चिकित्सन्नापराध्यति आहूत एव यो याति सुवेषः सुनिमित्ततः", text: "tābhyāṃ bhiṣak suyuktābhyāṃ cikitsannāparādhyati āhūta eva yo yāti suveṣaḥ sunimittataḥ" },
      { type: "verse", number: "15", sanskrit: "गत्वा ऽतुरार्थादन्यत्र न निधत्ते मनः क्वचित् व्याधीन् परीक्षते सम्यङ्निदानादिविशेषतः", text: "gatvā 'turārthādanyatra na nidhatte manaḥ kvacit vyādhīn parīkṣate samyaṅnidānādiviśeṣataḥ" },
      { type: "verse", number: "16", sanskrit: "ह्रेपणीयां च तद्वाअर्त्तां न प्रकाशयते बहिः सहसा न च तस्यापि क्रियाकालमहापयन्", text: "hrepaṇīyāṃ ca tadvāarttāṃ na prakāśayate bahiḥ sahasā na ca tasyāpi kriyākālamahāpayan" },
      { type: "verse", number: "17", sanskrit: "जानाति चोपचरितुं स वैद्यः सिद्धिमश्नुते नाददीता ऽमिषं स्त्रीभ्यस्तदध्यक्षे पराङ्मुखे", text: "jānāti copacarituṃ sa vaidyaḥ siddhimaśnute nādadītā 'miṣaṃ strībhyastadadhyakṣe parāṅmukhe" },
      { type: "verse", number: "18", sanskrit: "ताभिश्च रहसि स्थानं परिहासं च वर्जयेत् आर्त्तं च नृपसद्वैद्यैर्द्विष्टं तद्वेषिणं द्विषम्", text: "tābhiśca rahasi sthānaṃ parihāsaṃ ca varjayet ārttaṃ ca nṛpasadvaidyairdviṣṭaṃ tadveṣiṇaṃ dviṣam" },
      { type: "verse", number: "19", sanskrit: "चण्डं शोकातुरं भीरुं कृतघ्नं वैद्यमानिनम् हीनोपकरणं व्यग्रमविधेयं गतायुषम्", text: "caṇḍaṃ śokāturaṃ bhīruṃ kṛtaghnaṃ vaidyamāninam hīnopakaraṇaṃ vyagramavidheyaṃ gatāyuṣam" },
      { type: "verse", number: "20", sanskrit: "जिजीविषुर्व्याधितो ऽपि पूर्वोक्तगुणवर्जितान् क्रियाविक्रयिणो वैद्यान् मृत्योरग्रेसरा हि ते", text: "jijīviṣurvyādhito 'pi pūrvoktaguṇavarjitān kriyāvikrayiṇo vaidyān mṛtyoragresarā hi te" },
      { type: "verse", number: "21", sanskrit: "भिषग्द्रव्याण्युपस्थाता रोगी पादचतुष्टयम् चिकित्सितस्य निर्दिष्टं प्रत्येकं तच्चतुर्गुणम्", text: "bhiṣagdravyāṇyupasthātā rogī pādacatuṣṭayam cikitsitasya nirdiṣṭaṃ pratyekaṃ taccaturguṇam" },
      { type: "verse", number: "22", sanskrit: "दक्षस्तीर्थात्तशास्त्रार्थो दृष्टकर्मा शुचिर्भिषक् बहुकल्पं बहुगुणं सम्पन्नं योग्यमौषधम्", text: "dakṣastīrthāttaśāstrārtho dṛṣṭakarmā śucirbhiṣak bahukalpaṃ bahuguṇaṃ sampannaṃ yogyamauṣadham" },
      { type: "verse", number: "23", sanskrit: "अनुरक्तः शुचिर्दक्षो बुद्धिमान् परिचारकः आढ्यो रोगी भिषग्वश्यो ज्ञापकः सत्ववानपि", text: "anuraktaḥ śucirdakṣo buddhimān paricārakaḥ āḍhyo rogī bhiṣagvaśyo jñāpakaḥ satvavānapi" },
      { type: "verse", number: "24", sanskrit: "यद्वैद्ये विगुणे पादा गुणवन्तो ऽप्यनर्थकाः स पादहीनानप्यार्तान् गुणवान् यच्च यापयेत्", text: "yadvaidye viguṇe pādā guṇavanto 'pyanarthakāḥ sa pādahīnānapyārtān guṇavān yacca yāpayet" },
      { type: "verse", number: "25", sanskrit: "चिकित्सायास्तमेवातः प्रधानं कारणं विदुः साध्यो ऽसाध्य इति व्याधिर्द्विधा तौ तु पुनर्द्विधा", text: "cikitsāyāstamevātaḥ pradhānaṃ kāraṇaṃ viduḥ sādhyo 'sādhya iti vyādhirdvidhā tau tu punardvidhā" },
      { type: "verse", number: "26", sanskrit: "सुसाध्यः कृच्छ्रसाध्यश्च याप्यो यश्चानुपक्रमः सर्वौषधमे देहे यूनः पुंसो जितात्मनः", text: "susādhyaḥ kṛcchrasādhyaśca yāpyo yaścānupakramaḥ sarvauṣadhame dehe yūnaḥ puṃso jitātmanaḥ" },
      { type: "verse", number: "27", sanskrit: "अमर्मगो ऽल्पहेत्वग्ररूपरूपो ऽनुपद्रवः अतुल्यदूष्यदेशर्तुप्रकृतिः पादसम्पदि", text: "amarmago 'lpahetvagrarūparūpo 'nupadravaḥ atulyadūṣyadeśartuprakṛtiḥ pādasampadi" },
      { type: "verse", number: "28", sanskrit: "ग्रहेष्वनुगुणेष्वेकदोषमार्गो नवः सुखः सुखसाध्यः सुखोपायः कालेनाल्पेन साध्यते", text: "graheṣvanuguṇeṣvekadoṣamārgo navaḥ sukhaḥ sukhasādhyaḥ sukhopāyaḥ kālenālpena sādhyate" },
      { type: "verse", number: "29", sanskrit: "कृच्छ्रैरुपायैः कृच्छ्रस्तु महद्भिश्च चिरेण च असाध्यलिङ्गसङ्कीर्णस्तथा शस्त्रादिसाधनः", text: "kṛcchrairupāyaiḥ kṛcchrastu mahadbhiśca cireṇa ca asādhyaliṅgasaṅkīrṇastathā śastrādisādhanaḥ" },
      { type: "verse", number: "30", sanskrit: "शेषत्वादायुषः पथ्यैर्याप्यः प्रायो विपर्यये दत्वा ऽल्पं सुखमल्पेन हेतुना स प्रतन्यते", text: "śeṣatvādāyuṣaḥ pathyairyāpyaḥ prāyo viparyaye datvā 'lpaṃ sukhamalpena hetunā sa pratanyate" },
      { type: "verse", number: "31", sanskrit: "याति नाशेषतां रोगः कर्मणो नियतायुषः प्रपतन्निव विष्कम्भैर्धार्यते ऽत्रातुरो हितैः", text: "yāti nāśeṣatāṃ rogaḥ karmaṇo niyatāyuṣaḥ prapatanniva viṣkambhairdhāryate 'trāturo hitaiḥ" },
      { type: "verse", number: "32", sanskrit: "परो ऽसाध्यः क्रियाः सर्वाः प्रत्याख्येयो ऽतिवर्तते तस्मादुपेक्ष्य एवासौ स्थितो ऽत्यन्तविपर्यये", text: "paro 'sādhyaḥ kriyāḥ sarvāḥ pratyākhyeyo 'tivartate tasmādupekṣya evāsau sthito 'tyantaviparyaye" },
      { type: "verse", number: "33", sanskrit: "भ्रममोहारतिकरो दृष्टरिष्टो ऽक्षनाशनः व्याधीन् पुरा परीक्ष्यैवमारभेत ततः क्रियाम्", text: "bhramamohāratikaro dṛṣṭariṣṭo 'kṣanāśanaḥ vyādhīn purā parīkṣyaivamārabheta tataḥ kriyām" },
      { type: "verse", number: "34", sanskrit: "स्वार्थविद्यायशोहानिमन्यथा ध्रुवमाप्नुयात् साध्ययोरपि संयोगो बलिनोर्यात्यसाध्यताम्", text: "svārthavidyāyaśohānimanyathā dhruvamāpnuyāt sādhyayorapi saṃyogo balinoryātyasādhyatām" },
      { type: "verse", number: "35", sanskrit: "विद्यादसाध्यमेवातः साध्यासाध्यसमागमम् नासाध्यः साध्यतां याति साध्यो यातित्वसाध्यताम्", text: "vidyādasādhyamevātaḥ sādhyāsādhyasamāgamam nāsādhyaḥ sādhyatāṃ yāti sādhyo yātitvasādhyatām" },
      { type: "verse", number: "36", sanskrit: "पादापचाराद्दैवाच्च यान्त्यवस्थान्तरं गदाः वरमाशीविषविषं दीप्तमग्निमयो ऽपि वा", text: "pādāpacārāddaivācca yāntyavasthāntaraṃ gadāḥ varamāśīviṣaviṣaṃ dīptamagnimayo 'pi vā" },
      { type: "verse", number: "37", sanskrit: "उपयुञ्जीत न त्वार्त्तादामिषं कृपणाज्जनात् वरो भूतदया धर्म इत्यार्त्तेषु भिषग्वरः", text: "upayuñjīta na tvārttādāmiṣaṃ kṛpaṇājjanāt varo bhūtadayā dharma ityārtteṣu bhiṣagvaraḥ" },
      { type: "verse", number: "38", sanskrit: "वर्त्तते यस्तु सिद्धार्थः स सर्वमतिवर्त्तते", text: "varttate yastu siddhārthaḥ sa sarvamativarttate" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 3,
    lang: "sa",
    content: [
      { type: "heading", heading: "Риту чарья — сезонный режим поведения" },
      { type: "text", text: "Глава 3 Сутрастханы Астанга-санграхи посвящена теме «сезонный режим поведения». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो दिनचर्यां नामाध्यायं व्याख्यास्यामः इति ह स्मा ऽहुरात्रेयादयो महर्षयः", text: "athāto dinacaryāṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smā 'hurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "ब्राह्मे मुहूर्ते उत्तिष्ठेज्जीर्णाजीर्णं निरूपयन् रक्षार्थमायुषः स्वस्थो जातवेगः समुत्सृजेत्", text: "brāhme muhūrte uttiṣṭhejjīrṇājīrṇaṃ nirūpayan rakṣārthamāyuṣaḥ svastho jātavegaḥ samutsṛjet" },
      { type: "verse", number: "3", sanskrit: "उदङ्मुखो मूत्रशकृद्दक्षिणाभिमुखो निशि वाचं नियम्य प्रयतः संवीताङ्गो ऽवगुण्ठितः", text: "udaṅmukho mūtraśakṛddakṣiṇābhimukho niśi vācaṃ niyamya prayataḥ saṃvītāṅgo 'vaguṇṭhitaḥ" },
      { type: "verse", number: "4", sanskrit: "प्रवर्त्तयेत् प्रचलितं न तु यत्नादुदीरयेत् नामेध्यमार्गमृत्भस्मगोस्थानाकीर्णगोमये", text: "pravarttayet pracalitaṃ na tu yatnādudīrayet nāmedhyamārgamṛtbhasmagosthānākīrṇagomaye" },
      { type: "verse", number: "5", sanskrit: "पुरान्तिकाग्निवल्मीकरम्योत्कृष्टचितिद्रुमे न नारीपूज्यगोर्केन्दुवाय्वन्नाग्निजलं प्रति", text: "purāntikāgnivalmīkaramyotkṛṣṭacitidrume na nārīpūjyagorkenduvāyvannāgnijalaṃ prati" },
      { type: "verse", number: "6", sanskrit: "न चातिरस्कृत्य महीं भयाशक्त्योस्तु कामतः नवेगितो ऽन्यकार्यः स्यान्नाजित्वासाध्यमामयम्", text: "na cātiraskṛtya mahīṃ bhayāśaktyostu kāmataḥ navegito 'nyakāryaḥ syānnājitvāsādhyamāmayam" },
      { type: "verse", number: "7", sanskrit: "निःशल्यादुष्टमृत्पिण्डीपरिमृष्टमलायनः अभ्युद्धृताभिः शुचिभिरद्भिर्मृद्भिश्च योजयेत्", text: "niḥśalyāduṣṭamṛtpiṇḍīparimṛṣṭamalāyanaḥ abhyuddhṛtābhiḥ śucibhiradbhirmṛdbhiśca yojayet" },
      { type: "verse", number: "8", sanskrit: "लेपगन्धापहं शौचमनुत्पतिताबिन्दुभिः स्पृष्ट्वा धातून् मलानश्रुवसाकेशनखांश्युच्तान्", text: "lepagandhāpahaṃ śaucamanutpatitābindubhiḥ spṛṣṭvā dhātūn malānaśruvasākeśanakhāṃśyuctān" },
      { type: "verse", number: "9", sanskrit: "स्नात्वा भोक्तुमना भुक्त्वा सुप्त्वा क्षुत्वा सुरार्च्चने रथ्यामाक्रम्य चाचामेदुपविष्ट उदङ्मुखः", text: "snātvā bhoktumanā bhuktvā suptvā kṣutvā surārccane rathyāmākramya cācāmedupaviṣṭa udaṅmukhaḥ" },
      { type: "verse", number: "10", sanskrit: "प्राङ्मुखो वा विविक्तस्थो न बहिर्जानु नान्यदृक् अजल्पन्नुत्तरासङ्गी स्वच्छैरङ्गुष्ठमूलगैः", text: "prāṅmukho vā viviktastho na bahirjānu nānyadṛk ajalpannuttarāsaṅgī svacchairaṅguṣṭhamūlagaiḥ" },
      { type: "verse", number: "11", sanskrit: "नोद्धृतैर्नानतो नोर्ध्वं नाग्निपक्वैर्न्न पूतिभिः न फेनबुल्बुदक्षारैर्नैकहस्तार्पितैर्जलैः", text: "noddhṛtairnānato nordhvaṃ nāgnipakvairnna pūtibhiḥ na phenabulbudakṣārairnaikahastārpitairjalaiḥ" },
      { type: "verse", number: "12", sanskrit: "नाद्रैकपाणिर्न्नामेध्यहस्तपादो न शब्दवत् वटासनार्कखदिरकरञ्जकरवीरजम्", text: "nādraikapāṇirnnāmedhyahastapādo na śabdavat vaṭāsanārkakhadirakarañjakaravīrajam" },
      { type: "verse", number: "13", sanskrit: "सर्जारिमेदापामार्गमालतीककुभोद्भवम् कषायतिक्तकटुकं मूलमन्यदपीदृशम्", text: "sarjārimedāpāmārgamālatīkakubhodbhavam kaṣāyatiktakaṭukaṃ mūlamanyadapīdṛśam" },
      { type: "verse", number: "14", sanskrit: "विज्ञातवृक्षं क्षुण्णाग्रमृज्वग्रन्थि सुभूमिजम् कनीन्यग्रसमस्थौल्यं सुकूर्च्चं द्वादशाङ्गुलम्", text: "vijñātavṛkṣaṃ kṣuṇṇāgramṛjvagranthi subhūmijam kanīnyagrasamasthaulyaṃ sukūrccaṃ dvādaśāṅgulam" },
      { type: "verse", number: "15", sanskrit: "प्रातर्भुक्त्वा च यतवाग्भक्षयेद्दन्तधावनम् वाप्यत्रिवर्गत्रितयक्षौद्राक्तेन च घर्षयेत्", text: "prātarbhuktvā ca yatavāgbhakṣayeddantadhāvanam vāpyatrivargatritayakṣaudrāktena ca gharṣayet" },
      { type: "verse", number: "16", sanskrit: "शनैस्तेन ततो दन्तान् दन्तमांसान्यबाधयन् लिखेदनुसुखं जिह्वां जिह्वानिर्लेखनेन च", text: "śanaistena tato dantān dantamāṃsānyabādhayan likhedanusukhaṃ jihvāṃ jihvānirlekhanena ca" },
      { type: "verse", number: "17", sanskrit: "तथास्यमलवैरस्यगन्धा जिह्वास्यदन्तजाः रुचिवैशद्यलघुता न भवन्ति भवन्ति च", text: "tathāsyamalavairasyagandhā jihvāsyadantajāḥ rucivaiśadyalaghutā na bhavanti bhavanti ca" },
      { type: "verse", number: "18", sanskrit: "नाद्यादजीर्णवमथुश्वासकासज्वरार्दिती तृष्णास्यपाकहृन्नेत्रशिरःकर्णामयी च तत्", text: "nādyādajīrṇavamathuśvāsakāsajvarārditī tṛṣṇāsyapākahṛnnetraśiraḥkarṇāmayī ca tat" },
      { type: "verse", number: "19", sanskrit: "नैव श्लेष्मातकारिष्टबिभीतधवधन्वजान् बिल्ववञ्चुलनिर्गुण्डीशिग्रुतिल्वकतिन्दुकान्", text: "naiva śleṣmātakāriṣṭabibhītadhavadhanvajān bilvavañculanirguṇḍīśigrutilvakatindukān" },
      { type: "verse", number: "20", sanskrit: "कोविदारशमीपीलुपिप्पलेङ्गुदगुल्गुलून् पारिभद्रकमम्लीकामोचक्यौ शाल्मलीं शणम्", text: "kovidāraśamīpīlupippaleṅgudagulgulūn pāribhadrakamamlīkāmocakyau śālmalīṃ śaṇam" },
      { type: "verse", number: "21", sanskrit: "स्वाद्वम्ललवणं शुष्कं सुषिरं पूति पिच्छिलम् पालाशमासनं दन्तधावनं पादुके त्यजेत्", text: "svādvamlalavaṇaṃ śuṣkaṃ suṣiraṃ pūti picchilam pālāśamāsanaṃ dantadhāvanaṃ pāduke tyajet" },
      { type: "verse", number: "22", sanskrit: "दन्तान् पूर्वमधो घर्षेत् प्रातः सिञ्चेच्च लोचनं तोयपूर्णमुखो ग्रीष्मशरदोः शीतवारिणा", text: "dantān pūrvamadho gharṣet prātaḥ siñcecca locanaṃ toyapūrṇamukho grīṣmaśaradoḥ śītavāriṇā" },
      { type: "verse", number: "23", sanskrit: "प्रणम्य देवान् वृद्धांश्च मङ्गलाष्टशतं शुभम् शृण्वन् काञ्चनविन्यस्तं सर्पिः पश्येदनन्तरम्", text: "praṇamya devān vṛddhāṃśca maṅgalāṣṭaśataṃ śubham śṛṇvan kāñcanavinyastaṃ sarpiḥ paśyedanantaram" },
      { type: "verse", number: "24", sanskrit: "सौवीरमञ्जनं नित्यं हितमक्ष्णोस्ततो भजेत् लोचने तेन भवतो मनोज्ञे सूक्ष्मदर्शने", text: "sauvīramañjanaṃ nityaṃ hitamakṣṇostato bhajet locane tena bhavato manojñe sūkṣmadarśane" },
      { type: "verse", number: "25", sanskrit: "व्यक्तत्रिवर्णे विमले सुस्निग्धघनपक्ष्मणी चक्षुस्तेजोमयं तस्य विशेषात्च्छेलष्मतो भयम्", text: "vyaktatrivarṇe vimale susnigdhaghanapakṣmaṇī cakṣustejomayaṃ tasya viśeṣātcchelaṣmato bhayam" },
      { type: "verse", number: "26", sanskrit: "योजयेत्सप्तरात्रे ऽस्मात् स्रावणाथ रसाञ्जनम् अणुतैलं ततो नस्यं ततो गण्डूषधारणम्", text: "yojayetsaptarātre 'smāt srāvaṇātha rasāñjanam aṇutailaṃ tato nasyaṃ tato gaṇḍūṣadhāraṇam" },
      { type: "verse", number: "27", sanskrit: "घनोन्नतप्रसन्नत्वक्रकन्धग्रीवास्यवक्षसः सुगन्धिवदनाः स्निग्धनिस्वना विमलेन्द्रियाः", text: "ghanonnataprasannatvakrakandhagrīvāsyavakṣasaḥ sugandhivadanāḥ snigdhanisvanā vimalendriyāḥ" },
      { type: "verse", number: "28", sanskrit: "निर्वलीपलितव्यङ्गा भवेयुर्नस्यशीलिनः ओष्ठस्फुटनपारुष्यमुखशोषद्विजामयाः", text: "nirvalīpalitavyaṅgā bhaveyurnasyaśīlinaḥ oṣṭhasphuṭanapāruṣyamukhaśoṣadvijāmayāḥ" },
      { type: "verse", number: "29", sanskrit: "न स्युः स्वरोपघाताश्च स्नेहगण्डूषधारणात् खदिरक्षीरिवृक्षारिमेदाम्बुकवलग्रहः", text: "na syuḥ svaropaghātāśca snehagaṇḍūṣadhāraṇāt khadirakṣīrivṛkṣārimedāmbukavalagrahaḥ" },
      { type: "verse", number: "30", sanskrit: "अरोचकास्यवैरस्यमलपूतिप्रसेकजित् सुखोष्णोदकगण्डूषैर्जायते वक्त्रलाघवम्", text: "arocakāsyavairasyamalapūtiprasekajit sukhoṣṇodakagaṇḍūṣairjāyate vaktralāghavam" },
      { type: "verse", number: "31", sanskrit: "प्रायोगिकं ततो धूमं गन्धमाल्यादि चाचरेत् धूमादस्योर्ध्वजत्रूत्था न स्युर्वातकफामयाः", text: "prāyogikaṃ tato dhūmaṃ gandhamālyādi cācaret dhūmādasyordhvajatrūtthā na syurvātakaphāmayāḥ" },
      { type: "verse", number: "32", sanskrit: "अञ्जनोत्क्लेशितं नस्यैः कवलैर्नावनेरितम् धूमेन कवलोत्क्लिष्टं क्रमाद्वातकफं जयेत्", text: "añjanotkleśitaṃ nasyaiḥ kavalairnāvaneritam dhūmena kavalotkliṣṭaṃ kramādvātakaphaṃ jayet" },
      { type: "verse", number: "33", sanskrit: "गन्धमाल्यादिकं वृष्यमलक्ष्मीघ्नं प्रसाधनम् वासो न धारयेज्जीर्णं मलिनं रक्तमुल्बणम्", text: "gandhamālyādikaṃ vṛṣyamalakṣmīghnaṃ prasādhanam vāso na dhārayejjīrṇaṃ malinaṃ raktamulbaṇam" },
      { type: "verse", number: "34", sanskrit: "माल्यं न लम्बं न बहिर्न रक्तं जलजाद्दते नैव चान्येन विधृतं वस्त्रं पुष्पमुपानहौ", text: "mālyaṃ na lambaṃ na bahirna raktaṃ jalajāddate naiva cānyena vidhṛtaṃ vastraṃ puṣpamupānahau" },
      { type: "verse", number: "35", sanskrit: "रुचिवैशद्यसौगन्ध्यमिच्छन्वक्त्रेण धारयेत् जातीलवङ्गकर्पूरकङ्कोलकटुकैः सह", text: "rucivaiśadyasaugandhyamicchanvaktreṇa dhārayet jātīlavaṅgakarpūrakaṅkolakaṭukaiḥ saha" },
      { type: "verse", number: "36", sanskrit: "ताम्बूलीनां किसलयं हृद्यं पूगफलान्वितम् रक्तपित्तक्षतक्षीणरूक्षोत्कुपितचक्षुषाम्", text: "tāmbūlīnāṃ kisalayaṃ hṛdyaṃ pūgaphalānvitam raktapittakṣatakṣīṇarūkṣotkupitacakṣuṣām" },
      { type: "verse", number: "37", sanskrit: "विषमूर्च्छामदार्तानामपथ्यं शोषिणां च तत् पथ्यं सुप्तोत्थिते भुक्ते स्नाते वान्ते च मानवे", text: "viṣamūrcchāmadārtānāmapathyaṃ śoṣiṇāṃ ca tat pathyaṃ suptotthite bhukte snāte vānte ca mānave" },
      { type: "verse", number: "38", sanskrit: "द्विपत्रंएकं पूगं च सचूर्णखदिरं च तत् उत्तिष्ठेत ततोत्यर्थमर्थेष्वर्थानुबन्धिषु", text: "dvipatraṃekaṃ pūgaṃ ca sacūrṇakhadiraṃ ca tat uttiṣṭheta tatotyarthamartheṣvarthānubandhiṣu" },
      { type: "verse", number: "39", sanskrit: "निन्दितं दीर्घमप्यायुरसन्निहितसाधनम् कृषिं वाणिज्यां गोरक्षामुपायैर्गुणिनं नृपम्", text: "ninditaṃ dīrghamapyāyurasannihitasādhanam kṛṣiṃ vāṇijyāṃ gorakṣāmupāyairguṇinaṃ nṛpam" },
      { type: "verse", number: "40", sanskrit: "लोकद्वयाविरुद्धां च धनार्थी संश्रयेत् क्रियाम् मुक्तवेगश्च गमनस्वप्नाहारसभास्त्रियः", text: "lokadvayāviruddhāṃ ca dhanārthī saṃśrayet kriyām muktavegaśca gamanasvapnāhārasabhāstriyaḥ" },
      { type: "verse", number: "41", sanskrit: "पाणिना ऽलभ्य निष्क्रामेद्रत्नपूज्याज्यमङ्गलम् सातपत्रपदत्राणो विचरेद्युगमात्रद्दक्", text: "pāṇinā 'labhya niṣkrāmedratnapūjyājyamaṅgalam sātapatrapadatrāṇo vicaredyugamātraddak" },
      { type: "verse", number: "42", sanskrit: "निशि चात्ययिके कार्ये दण्डी मौली सहायवान् प्रावृत्य पर्यटेद्रात्रौ न प्रावृत्य शिरो ऽहनि", text: "niśi cātyayike kārye daṇḍī maulī sahāyavān prāvṛtya paryaṭedrātrau na prāvṛtya śiro 'hani" },
      { type: "verse", number: "43", sanskrit: "चैत्यपूज्यध्वजाशस्तच्चायाभस्मतुषाशुचीन् नाक्रामेच्छर्करालोष्टबलिस्नानभुवो न च", text: "caityapūjyadhvajāśastaccāyābhasmatuṣāśucīn nākrāmeccharkarāloṣṭabalisnānabhuvo na ca" },
      { type: "verse", number: "44", sanskrit: "मध्याह्ने सन्ध्ययो रात्रावर्धरात्रे चतुष्पथम् न सेवेत न शर्वर्यां वृक्षचैत्यं न चत्वरम्", text: "madhyāhne sandhyayo rātrāvardharātre catuṣpatham na seveta na śarvaryāṃ vṛkṣacaityaṃ na catvaram" },
      { type: "verse", number: "45", sanskrit: "सूनाटवीशून्यगृहश्मशानानि दिवा ऽपि न न हुंकुर्याच्छवं पूज्यं प्रशस्तान्मङ्गलानि च", text: "sūnāṭavīśūnyagṛhaśmaśānāni divā 'pi na na huṃkuryācchavaṃ pūjyaṃ praśastānmaṅgalāni ca" },
      { type: "verse", number: "46", sanskrit: "नापसव्यं परिक्रामेन्नेतराण्यनुदक्षिणम् चतुष्पथं नमस्कुर्यात् प्रज्ञातांश्च वनस्पतीन्", text: "nāpasavyaṃ parikrāmennetarāṇyanudakṣiṇam catuṣpathaṃ namaskuryāt prajñātāṃśca vanaspatīn" },
      { type: "verse", number: "47", sanskrit: "न व्यालव्याधिताशस्तैर्नादान्दक्षुत्पिपासितैः न च्छिन्नपुच्छैर्नैकाक्षैगापृष्ठेन च न व्रजेत्", text: "na vyālavyādhitāśastairnādāndakṣutpipāsitaiḥ na cchinnapucchairnaikākṣaigāpṛṣṭhena ca na vrajet" },
      { type: "verse", number: "48", sanskrit: "ना ऽतिप्रगे ऽतिसायं वा न नभोमध्यगे रवौ नासन्निहितपानीयो नातितूर्णं न सन्ततम्", text: "nā 'tiprage 'tisāyaṃ vā na nabhomadhyage ravau nāsannihitapānīyo nātitūrṇaṃ na santatam" },
      { type: "verse", number: "49", sanskrit: "न शत्रुणा नाविदितैर्नैको नाधार्मिकैः सह दद्याद्वर्त्मा ऽर्तवृद्धस्त्रीभारिचक्रद्विजन्मने", text: "na śatruṇā nāviditairnaiko nādhārmikaiḥ saha dadyādvartmā 'rtavṛddhastrībhāricakradvijanmane" },
      { type: "verse", number: "50", sanskrit: "स्रानभोजनपानानि वाहेभ्यो न आचरेत् पुरः नदीं तरेन्न बाहुभ्यां नाग्निस्कन्धमभिव्रजेत्", text: "srānabhojanapānāni vāhebhyo na ācaret puraḥ nadīṃ tarenna bāhubhyāṃ nāgniskandhamabhivrajet" },
      { type: "verse", number: "51", sanskrit: "ना ऽरोहोद्विषमं शैलं नावं संशयितां तरुम् निपातयेन्न लोष्टेन न फलेन फलं द्रुमात्", text: "nā 'rohodviṣamaṃ śailaṃ nāvaṃ saṃśayitāṃ tarum nipātayenna loṣṭena na phalena phalaṃ drumāt" },
      { type: "verse", number: "52", sanskrit: "न वार्यमाणः प्रविशेन्नाद्वारेण ना च आसने स्वयं तिष्ठेत् परगृहे युक्तनिंद्रं न बोधयेत्", text: "na vāryamāṇaḥ praviśennādvāreṇa nā ca āsane svayaṃ tiṣṭhet paragṛhe yuktaniṃdraṃ na bodhayet" },
      { type: "verse", number: "53", sanskrit: "न आचरेत् पाणिवाक्पादद्दङ्मेढ्रेदरचापलम् त्रिः पक्षस्य कचश्मश्रुनखरोमाणि वर्धयेत्", text: "na ācaret pāṇivākpādaddaṅmeḍhredaracāpalam triḥ pakṣasya kacaśmaśrunakharomāṇi vardhayet" },
      { type: "verse", number: "54", sanskrit: "न स्वहस्तेन दन्तैर्वा स्नानं चानु समाचरेत् अथ जातान्नपानेच्छो मारुतघ्नैः सुगन्धिभिः", text: "na svahastena dantairvā snānaṃ cānu samācaret atha jātānnapāneccho mārutaghnaiḥ sugandhibhiḥ" },
      { type: "verse", number: "55", sanskrit: "यथर्तुसंस्पर्शसुखैस्तैलैरभ्यङ्गमाचरेत् अभ्यङ्गो वातहा पुष्टिस्वप्नदार्ढ्यबृहत्वकृत्", text: "yathartusaṃsparśasukhaistailairabhyaṅgamācaret abhyaṅgo vātahā puṣṭisvapnadārḍhyabṛhatvakṛt" },
      { type: "verse", number: "56", sanskrit: "दग्धभग्नक्षतरुजाक्लमश्रमजरापहः रथाक्षचर्मघटवत् भवन्त्यभ्यङ्गतो गुणाः", text: "dagdhabhagnakṣatarujāklamaśramajarāpahaḥ rathākṣacarmaghaṭavat bhavantyabhyaṅgato guṇāḥ" },
      { type: "verse", number: "57", sanskrit: "स्पर्शने ऽभ्याधिको वायुःस्पर्शनं च त्वगाश्रयम् त्वच्यश्च परमभ्यङ्गो यस्मात्तं शीलयेदतः", text: "sparśane 'bhyādhiko vāyuḥsparśanaṃ ca tvagāśrayam tvacyaśca paramabhyaṅgo yasmāttaṃ śīlayedataḥ" },
      { type: "verse", number: "58", sanskrit: "शिरः श्रवणपादेषु तं विशेषेण शीलयेत् स केश्यः शीलितो मूर्ध्नि कपालेन्दिर्यतर्पणः", text: "śiraḥ śravaṇapādeṣu taṃ viśeṣeṇa śīlayet sa keśyaḥ śīlito mūrdhni kapālendiryatarpaṇaḥ" },
      { type: "verse", number: "59", sanskrit: "हनुमन्याशिरः कर्णशूलघ्नं कर्णपूरणम् पादाभ्यङ्गस्तु तत्स्थैर्यनिद्राद्दष्टि प्रसादकृत्", text: "hanumanyāśiraḥ karṇaśūlaghnaṃ karṇapūraṇam pādābhyaṅgastu tatsthairyanidrāddaṣṭi prasādakṛt" },
      { type: "verse", number: "60", sanskrit: "पादसुप्तिश्रमस्तम्भसङ्कोचस्फुटनप्रणुत् वर्ज्योभ्यङ्गः कफग्रस्तक्तसंशुद्ध्यजीर्णिभिः", text: "pādasuptiśramastambhasaṅkocasphuṭanapraṇut varjyobhyaṅgaḥ kaphagrastaktasaṃśuddhyajīrṇibhiḥ" },
      { type: "verse", number: "61", sanskrit: "शरीरायासजननं कर्म व्यायाम उच्यते लाघवं कर्मसामर्थ्यं दीप्तो ऽग्निर्मेदसः क्षयः", text: "śarīrāyāsajananaṃ karma vyāyāma ucyate lāghavaṃ karmasāmarthyaṃ dīpto 'gnirmedasaḥ kṣayaḥ" },
      { type: "verse", number: "62", sanskrit: "विभक्तघनगात्रत्वं व्यायामादुपजायते वातपित्तामयी बालो वृद्धो ऽजीर्णी च तं त्यजेत्", text: "vibhaktaghanagātratvaṃ vyāyāmādupajāyate vātapittāmayī bālo vṛddho 'jīrṇī ca taṃ tyajet" },
      { type: "verse", number: "63", sanskrit: "अर्द्धशक्त्यानिषेव्यस्तु बलिभिः स्निग्धभोजिभिः शीतकाले वसन्ते च मन्दमेव ततो ऽन्यदा", text: "arddhaśaktyāniṣevyastu balibhiḥ snigdhabhojibhiḥ śītakāle vasante ca mandameva tato 'nyadā" },
      { type: "verse", number: "64", sanskrit: "तं कृत्वा ऽनुसुखं देहं मर्द्दयेच्च समन्ततः तृष्णा क्षयः प्रतमको रक्तपित्तं श्रमः क्लमः", text: "taṃ kṛtvā 'nusukhaṃ dehaṃ marddayecca samantataḥ tṛṣṇā kṣayaḥ pratamako raktapittaṃ śramaḥ klamaḥ" },
      { type: "verse", number: "65", sanskrit: "अतिव्यायामतः कासो ज्वरश्च्छर्दिश्च जायते व्यायामजागराध्वस्त्रीहास्यभाष्यादि साहसं", text: "ativyāyāmataḥ kāso jvaraścchardiśca jāyate vyāyāmajāgarādhvastrīhāsyabhāṣyādi sāhasaṃ" },
      { type: "verse", number: "66", sanskrit: "गजं सिंह इव आकर्षन् भजन्नति विनश्यति उद्वर्त्तनं कफहरं मेदसः प्रविलायनम्", text: "gajaṃ siṃha iva ākarṣan bhajannati vinaśyati udvarttanaṃ kaphaharaṃ medasaḥ pravilāyanam" },
      { type: "verse", number: "67", sanskrit: "स्थिरीकरणमङ्गानां त्वक्प्रसादकरं परम् दीपनं वृष्यमायुष्यं स्नानमूर्जाबलप्रदम्", text: "sthirīkaraṇamaṅgānāṃ tvakprasādakaraṃ param dīpanaṃ vṛṣyamāyuṣyaṃ snānamūrjābalapradam" },
      { type: "verse", number: "68", sanskrit: "कण्डूमलश्रमस्वेदतन्द्रातृङ्दाहपाप्मजित् उष्णाम्बुना ऽधःकायस्य परिषेको बलावहः", text: "kaṇḍūmalaśramasvedatandrātṛṅdāhapāpmajit uṣṇāmbunā 'dhaḥkāyasya pariṣeko balāvahaḥ" },
      { type: "verse", number: "69", sanskrit: "तेनैव तूत्तमाङ्गस्य बलहृत् केशचक्षुषाम् ना ऽनाप्लुत्य शिरः स्नायान्न जले ऽल्पे न शीतले", text: "tenaiva tūttamāṅgasya balahṛt keśacakṣuṣām nā 'nāplutya śiraḥ snāyānna jale 'lpe na śītale" },
      { type: "verse", number: "70", sanskrit: "नोदकावतरणस्वप्नान् नग्नो न च आचरेत् पञ्चपिण्डाननुद्धृत्य न स्नायात् परवारिणि", text: "nodakāvataraṇasvapnān nagno na ca ācaret pañcapiṇḍānanuddhṛtya na snāyāt paravāriṇi" },
      { type: "verse", number: "71", sanskrit: "नात्मानमीक्षेत जले न तटस्थो जलाशयम् न प्रतिस्फालयेदम्बु पाणिना चरणेन वा", text: "nātmānamīkṣeta jale na taṭastho jalāśayam na pratisphālayedambu pāṇinā caraṇena vā" },
      { type: "verse", number: "72", sanskrit: "स्नात्वा न मृज्यात् गात्राणि धुनुयान्न शिरोरुहान् निवसीता ऽर्द्र एव आशु सोष्णीषे धौतवाससी", text: "snātvā na mṛjyāt gātrāṇi dhunuyānna śiroruhān nivasītā 'rdra eva āśu soṣṇīṣe dhautavāsasī" },
      { type: "verse", number: "73", sanskrit: "न त्वम्बरं पूर्वधृतं न च तैलवसे स्पृशेत् वासो ऽन्यदन्यच्छयने निर्गमे देवतार्च्चने", text: "na tvambaraṃ pūrvadhṛtaṃ na ca tailavase spṛśet vāso 'nyadanyacchayane nirgame devatārccane" },
      { type: "verse", number: "74", sanskrit: "स्नानमर्दितनेत्रास्यकर्णरोगातिसारिषु आध्मानपीनसाजीर्णभुक्तवत्सु च गर्हितम्", text: "snānamarditanetrāsyakarṇarogātisāriṣu ādhmānapīnasājīrṇabhuktavatsu ca garhitam" },
      { type: "verse", number: "75", sanskrit: "अन्नपानविधानेन भुञ्जीतान्नं विना ऽत्ययात् अभिनन्द्य प्रसन्नात्मा हुत्वा दत्वा च शक्तितः", text: "annapānavidhānena bhuñjītānnaṃ vinā 'tyayāt abhinandya prasannātmā hutvā datvā ca śaktitaḥ" },
      { type: "verse", number: "76", sanskrit: "पाकं सजलमेकान्ते यथासुखमितिश्रुवन् प्रयच्छेत्सर्वमुद्दिश्य पाचयेन्ना ऽन्नमात्मने", text: "pākaṃ sajalamekānte yathāsukhamitiśruvan prayacchetsarvamuddiśya pācayennā 'nnamātmane" },
      { type: "verse", number: "77", sanskrit: "ना ऽन्नमद्यान्मुमूर्षूणां मृतानां दुःखजीविनां स्त्रीजितक्लीबपतितक्रूरदुष्कृतकारिणां", text: "nā 'nnamadyānmumūrṣūṇāṃ mṛtānāṃ duḥkhajīvināṃ strījitaklībapatitakrūraduṣkṛtakāriṇāṃ" },
      { type: "verse", number: "78", sanskrit: "गणारिगणिकासत्रधूर्त्तान्नापणिकञ्च न नोत्सङ्गे भक्षयेत् भक्ष्यान् जलं नाञ्जलिना पिबेत्", text: "gaṇārigaṇikāsatradhūrttānnāpaṇikañca na notsaṅge bhakṣayet bhakṣyān jalaṃ nāñjalinā pibet" },
      { type: "verse", number: "79", sanskrit: "सर्वञ्च तिलसम्बद्धं ना ऽद्यादस्तमिते रवौ न भुक्तमात्र आस्येन्न निषिद्धं भजेत्सुखं", text: "sarvañca tilasambaddhaṃ nā 'dyādastamite ravau na bhuktamātra āsyenna niṣiddhaṃ bhajetsukhaṃ" },
      { type: "verse", number: "80", sanskrit: "धर्मोत्तराभिरर्थ्याभिः कथाभिस्त्रिगुणात्मभिः मध्यं दिनस्य गमयेदिष्टशिष्टसहायवान्", text: "dharmottarābhirarthyābhiḥ kathābhistriguṇātmabhiḥ madhyaṃ dinasya gamayediṣṭaśiṣṭasahāyavān" },
      { type: "verse", number: "81", sanskrit: "न लोकभूपविद्विष्टैर्न सङ्गच्छेत नास्तिकैः कलिवैररुचिर्न स्यात् धीरः सम्पद्विपत्तिषु", text: "na lokabhūpavidviṣṭairna saṅgaccheta nāstikaiḥ kalivairarucirna syāt dhīraḥ sampadvipattiṣu" },
      { type: "verse", number: "82", sanskrit: "श्रुतादन्यत्र सन्तुष्टस्तत्रैव च कुतूहली क्षान्तिमान् दक्षिणो दक्षः सुसमीक्षितकार्यकृत्", text: "śrutādanyatra santuṣṭastatraiva ca kutūhalī kṣāntimān dakṣiṇo dakṣaḥ susamīkṣitakāryakṛt" },
      { type: "verse", number: "83", sanskrit: "ह्रीमान् धीमान् महोत्साहः संविभागी प्रियातिथिः अक्षुद्रवृत्तिर्गम्भीरः साधुराश्रितवत्सलः", text: "hrīmān dhīmān mahotsāhaḥ saṃvibhāgī priyātithiḥ akṣudravṛttirgambhīraḥ sādhurāśritavatsalaḥ" },
      { type: "verse", number: "84", sanskrit: "दाता पितृभ्यः पिण्डस्य यष्टा होता कृपात्मकः अनुज्ञाता सुवार्तानां दीनानामनुकम्पकः", text: "dātā pitṛbhyaḥ piṇḍasya yaṣṭā hotā kṛpātmakaḥ anujñātā suvārtānāṃ dīnānāmanukampakaḥ" },
      { type: "verse", number: "85", sanskrit: "आश्वासकारी भीतानां क्रुद्धानामनुनायकः पूर्वाभिभाषी सुमुखः सुशीलः पूज्यपूजकः", text: "āśvāsakārī bhītānāṃ kruddhānāmanunāyakaḥ pūrvābhibhāṣī sumukhaḥ suśīlaḥ pūjyapūjakaḥ" },
      { type: "verse", number: "86", sanskrit: "वित्तबन्धुवयोविद्यावृत्तैः पूज्या यथोत्तरम् आत्मद्रुहममर्यादं मूढमुज्झितसत्पथम्", text: "vittabandhuvayovidyāvṛttaiḥ pūjyā yathottaram ātmadruhamamaryādaṃ mūḍhamujjhitasatpatham" },
      { type: "verse", number: "87", sanskrit: "सुतरामनुकम्पेत नरकार्चिष्मदिन्धनम् धर्म्यमर्थ्यं प्रियं तथ्यं मितं पथ्यं वदेद्वचः", text: "sutarāmanukampeta narakārciṣmadindhanam dharmyamarthyaṃ priyaṃ tathyaṃ mitaṃ pathyaṃ vadedvacaḥ" },
      { type: "verse", number: "88", sanskrit: "ना आत्मानमवजानीयान्न स्तूयान्न च पीडयेत् न हीनानवमन्येत् वृत्तार्थाङ्गबलश्रुतैः", text: "nā ātmānamavajānīyānna stūyānna ca pīḍayet na hīnānavamanyet vṛttārthāṅgabalaśrutaiḥ" },
      { type: "verse", number: "89", sanskrit: "ना ऽरुन्तुदः स्यान्न क्रूरो न तीक्ष्णो नो ऽपतापवान् हेतावीर्ष्येन्न तु फले पापं पापे ऽपि नाचरेत्", text: "nā 'runtudaḥ syānna krūro na tīkṣṇo no 'patāpavān hetāvīrṣyenna tu phale pāpaṃ pāpe 'pi nācaret" },
      { type: "verse", number: "90", sanskrit: "परस्य दण्डं नोद्यच्छेत् क्रुद्धो नैनं निपातयेत् अन्यत्रपुत्राच्छिष्याद्वा शासनार्हाद्धिताशयः", text: "parasya daṇḍaṃ nodyacchet kruddho nainaṃ nipātayet anyatraputrācchiṣyādvā śāsanārhāddhitāśayaḥ" },
      { type: "verse", number: "91", sanskrit: "नृत्यवादित्रगीतादि नोल्बणामाचरेत् क्रियाम् प्रसिद्धकेशवाग्वेषशमसान्त्वपरायणः", text: "nṛtyavāditragītādi nolbaṇāmācaret kriyām prasiddhakeśavāgveṣaśamasāntvaparāyaṇaḥ" },
      { type: "verse", number: "92", sanskrit: "ऊर्ध्वं नाभेः शरीरस्य स्पृशोन्ना ऽधरवाससा न कुर्यान्मिथुनीभूय शौचं प्रति विलम्बनम्", text: "ūrdhvaṃ nābheḥ śarīrasya spṛśonnā 'dharavāsasā na kuryānmithunībhūya śaucaṃ prati vilambanam" },
      { type: "verse", number: "93", sanskrit: "ना ऽसंवृतमुखो हास्यक्षवोत्गारविजृम्भणम् पाणिद्वयेन युगपत् कण्डूयेन्नात्मनः शिरः", text: "nā 'saṃvṛtamukho hāsyakṣavotgāravijṛmbhaṇam pāṇidvayena yugapat kaṇḍūyennātmanaḥ śiraḥ" },
      { type: "verse", number: "94", sanskrit: "वहेन्न भारं शिरसा युगपच्चाग्निवाहिणी नासिकां न विकुष्णीयाद्दशनान्न विघट्टयेत्", text: "vahenna bhāraṃ śirasā yugapaccāgnivāhiṇī nāsikāṃ na vikuṣṇīyāddaśanānna vighaṭṭayet" },
      { type: "verse", number: "95", sanskrit: "कुर्याद्विलेखनच्छेदभेदास्फोटनमर्दनम् पादं पादेन ना ऽक्रामेन्न कण्डूयेन्न शौचयेत्", text: "kuryādvilekhanacchedabhedāsphoṭanamardanam pādaṃ pādena nā 'krāmenna kaṇḍūyenna śaucayet" },
      { type: "verse", number: "96", sanskrit: "न कांस्यभाजने तौ च नोपविष्टः प्रसाधयेत् अभीक्ष्णं निर्मलान् दध्यान्नखपादमलाशयान्", text: "na kāṃsyabhājane tau ca nopaviṣṭaḥ prasādhayet abhīkṣṇaṃ nirmalān dadhyānnakhapādamalāśayān" },
      { type: "verse", number: "97", sanskrit: "ना ऽसमिद्धमुपासीत हुताशं नैव चाशुचिः ना ऽनुवातं न विवृतो न क्लान्तो ना ऽन्यमानसः", text: "nā 'samiddhamupāsīta hutāśaṃ naiva cāśuciḥ nā 'nuvātaṃ na vivṛto na klānto nā 'nyamānasaḥ" },
      { type: "verse", number: "98", sanskrit: "धमेन्ना ऽस्येन न स्कन्देन्ना ऽधः कुर्यान्न पादतः सततं न निरीक्षेत चलसूक्ष्माप्रियाणि च", text: "dhamennā 'syena na skandennā 'dhaḥ kuryānna pādataḥ satataṃ na nirīkṣeta calasūkṣmāpriyāṇi ca" },
      { type: "verse", number: "99", sanskrit: "नाप्रशस्तं न विण्मूत्रं न दर्पणममार्जितम् उद्यन्तमस्तमायान्तं तपन्तं प्रतिमागतम्", text: "nāpraśastaṃ na viṇmūtraṃ na darpaṇamamārjitam udyantamastamāyāntaṃ tapantaṃ pratimāgatam" },
      { type: "verse", number: "100", sanskrit: "उपरक्तं च भास्वन्तं वाससा वा तिरोहितम् ना ऽन्यदप्यतितेजस्वि न क्रुद्धभ्य गुरोर्मुखम्", text: "uparaktaṃ ca bhāsvantaṃ vāsasā vā tirohitam nā 'nyadapyatitejasvi na kruddhabhya gurormukham" },
      { type: "verse", number: "101", sanskrit: "स्त्रियं स्त्रवन्तीं नोदक्यां न नग्नां ना ऽन्यसङ्गताम् न पत्नीं भोजनस्वप्नक्षुतजृम्भादुरासने", text: "striyaṃ stravantīṃ nodakyāṃ na nagnāṃ nā 'nyasaṅgatām na patnīṃ bhojanasvapnakṣutajṛmbhādurāsane" },
      { type: "verse", number: "102", sanskrit: "शयीत नैकशयने न चाश्नीयास्तया सह तामनीर्ष्यंश्च गोपायेत् स्वैरिणीं नाधिवासयेत्", text: "śayīta naikaśayane na cāśnīyāstayā saha tāmanīrṣyaṃśca gopāyet svairiṇīṃ nādhivāsayet" },
      { type: "verse", number: "103", sanskrit: "नोच्छिष्टस्तारकाराहुतुहिनाशुदिवाकरान् पश्येन्न यायान्न पठेन्न स्वप्यान्न स्पृशेछिरः", text: "nocchiṣṭastārakārāhutuhināśudivākarān paśyenna yāyānna paṭhenna svapyānna spṛśechiraḥ" },
      { type: "verse", number: "104", sanskrit: "पाययन्तीं चरन्तीं वा नान्यस्मै गां निवेदयेत् अर्केन्दुपरिवेषोल्काशतक्रतुधनूंषि च", text: "pāyayantīṃ carantīṃ vā nānyasmai gāṃ nivedayet arkendupariveṣolkāśatakratudhanūṃṣi ca" },
      { type: "verse", number: "105", sanskrit: "नान्यद्देवार्चने कर्म कुर्याद्धावेन्न वर्षति तिथिं पक्षस्य न ब्रूयात् नक्षत्राणि न निर्दिशेत्", text: "nānyaddevārcane karma kuryāddhāvenna varṣati tithiṃ pakṣasya na brūyāt nakṣatrāṇi na nirdiśet" },
      { type: "verse", number: "106", sanskrit: "न आत्मनो जन्मलग्नर्क्षधनसारं गृहे मलम् प्रकाशयेन्नावमानं न च निःस्नेअतां प्रभोः", text: "na ātmano janmalagnarkṣadhanasāraṃ gṛhe malam prakāśayennāvamānaṃ na ca niḥsneatāṃ prabhoḥ" },
      { type: "verse", number: "107", sanskrit: "पुरोवातातपरजस्तुषारपरुषानिलान् अनृजुः क्षवथूद्रारकासस्वप्नान्नमैथुनम्", text: "purovātātaparajastuṣāraparuṣānilān anṛjuḥ kṣavathūdrārakāsasvapnānnamaithunam" },
      { type: "verse", number: "108", sanskrit: "सशब्दमलिनं हस्तभ्रूनेत्रोत्क्षेपवादिताम् कूलच्छायां सुरापानं व्यालदंष्ट्रिविषाणिनः", text: "saśabdamalinaṃ hastabhrūnetrotkṣepavāditām kūlacchāyāṃ surāpānaṃ vyāladaṃṣṭriviṣāṇinaḥ" },
      { type: "verse", number: "109", sanskrit: "हीनानार्यातिनिपुणसेवां विग्रहमुत्तमैः सन्ध्यास्वभ्यवहारस्त्रीस्वप्नाध्ययनचिन्तनम्", text: "hīnānāryātinipuṇasevāṃ vigrahamuttamaiḥ sandhyāsvabhyavahārastrīsvapnādhyayanacintanam" },
      { type: "verse", number: "110", sanskrit: "आरोग्यजीवितैश्वर्यविद्यासु स्थिरमानिताम् तोयाग्नि पूज्यमध्येन यानं धूमं शवाश्रयम्", text: "ārogyajīvitaiśvaryavidyāsu sthiramānitām toyāgni pūjyamadhyena yānaṃ dhūmaṃ śavāśrayam" },
      { type: "verse", number: "111", sanskrit: "मद्यातिसक्तिं विस्त्रंभस्वातन्त्र्ये स्त्रीषु च त्यजेत् नैकाहमप्यधिवसेद्वास्तु तच्छास्त्रगर्हितम्", text: "madyātisaktiṃ vistraṃbhasvātantrye strīṣu ca tyajet naikāhamapyadhivasedvāstu tacchāstragarhitam" },
      { type: "verse", number: "112", sanskrit: "न देशं व्याधिबहुलं नावैद्यं नाप्यनायकम् नाधर्मिजनभूयिष्ठं नोपसृष्टं न पर्वतम्", text: "na deśaṃ vyādhibahulaṃ nāvaidyaṃ nāpyanāyakam nādharmijanabhūyiṣṭhaṃ nopasṛṣṭaṃ na parvatam" },
      { type: "verse", number: "113", sanskrit: "वसेत् प्राज्याम्बुभैषज्यसमित् पुष्पतृणेन्धने सुभिक्षक्षेमरम्यान्ते पण्डितैर्मण्डिते पुरे", text: "vaset prājyāmbubhaiṣajyasamit puṣpatṛṇendhane subhikṣakṣemaramyānte paṇḍitairmaṇḍite pure" },
      { type: "verse", number: "114", sanskrit: "नरामराणां सिद्धानां शास्त्राणाञ्चाजुगुप्सकः आधारकस्त्रिवर्गस्य यथायोग्यं जनस्य च", text: "narāmarāṇāṃ siddhānāṃ śāstrāṇāñcājugupsakaḥ ādhārakastrivargasya yathāyogyaṃ janasya ca" },
      { type: "verse", number: "115", sanskrit: "दश कर्मपतान्रक्षन् जयन्नभ्यन्तरानरीन् हिंसास्तेयान्यथाकामं पैशुन्यं परुषानृतम्", text: "daśa karmapatānrakṣan jayannabhyantarānarīn hiṃsāsteyānyathākāmaṃ paiśunyaṃ paruṣānṛtam" },
      { type: "verse", number: "116", sanskrit: "संभिन्नलापं व्यापादमभिध्यां दृग्विपर्ययम् पापं कर्मेतिदशधा कायवाङ्मानसैस्त्ययेत्", text: "saṃbhinnalāpaṃ vyāpādamabhidhyāṃ dṛgviparyayam pāpaṃ karmetidaśadhā kāyavāṅmānasaistyayet" },
      { type: "verse", number: "117", sanskrit: "परोपघातक्रियया वर्जयेदार्जनं श्रियः अर्थानां धर्मलब्धानामदाता ऽपिह्यसम्भवात्", text: "paropaghātakriyayā varjayedārjanaṃ śriyaḥ arthānāṃ dharmalabdhānāmadātā 'pihyasambhavāt" },
      { type: "verse", number: "118", sanskrit: "स्वर्गापवर्गविभवानयत्नेनाधितिष्ठति सायं भुक्त्वा लघु हितं समाहितमनाः शुचिः", text: "svargāpavargavibhavānayatnenādhitiṣṭhati sāyaṃ bhuktvā laghu hitaṃ samāhitamanāḥ śuciḥ" },
      { type: "verse", number: "119", sanskrit: "शास्तारमनुसंस्मृत्य स्वचर्यां चाथ संविशेत् देशे शुचावनाकीर्णे द्वित्राप्तपरिचारकः", text: "śāstāramanusaṃsmṛtya svacaryāṃ cātha saṃviśet deśe śucāvanākīrṇe dvitrāptaparicārakaḥ" },
      { type: "verse", number: "120", sanskrit: "युक्तोपधानं स्वास्तीर्णं विस्तीर्णाविषमं सुखम् जानुतुल्यं मृदु शुभं सेवेत शयनासनम्", text: "yuktopadhānaṃ svāstīrṇaṃ vistīrṇāviṣamaṃ sukham jānutulyaṃ mṛdu śubhaṃ seveta śayanāsanam" },
      { type: "verse", number: "121", sanskrit: "प्राग्दक्षिणशिराः पादावकुर्वाणो गुरून् प्रति पूर्वापरदिशो भागे धर्ममेवानुचिन्तयन्", text: "prāgdakṣiṇaśirāḥ pādāvakurvāṇo gurūn prati pūrvāparadiśo bhāge dharmamevānucintayan" },
      { type: "verse", number: "122", sanskrit: "आददीत सदा देहादित्थं सारमसारतः बिभ्यत् प्रतिक्षणं मृत्योरयथातथचेष्टितात्", text: "ādadīta sadā dehāditthaṃ sāramasārataḥ bibhyat pratikṣaṇaṃ mṛtyorayathātathaceṣṭitāt" },
      { type: "verse", number: "123", sanskrit: "आरोग्यविभवप्रज्ञावयोधर्मक्रियावतः सुखमायुर्हितं चोक्तं विपरीतं विपर्यये", text: "ārogyavibhavaprajñāvayodharmakriyāvataḥ sukhamāyurhitaṃ coktaṃ viparītaṃ viparyaye" },
      { type: "verse", number: "124", sanskrit: "सर्वतेजोनिधानं हि नृप इत्युच्यते भुवि अदूषयन्मनस्तस्मात् भक्तिमांस्तमुपाचरेत्", text: "sarvatejonidhānaṃ hi nṛpa ityucyate bhuvi adūṣayanmanastasmāt bhaktimāṃstamupācaret" },
      { type: "verse", number: "125", sanskrit: "पर्यस्तिकोपाश्रयकोपहासविवादनिष्ठीवनजृम्भणानि सर्वाः प्रकृत्यभ्यधिकाश्च चेष्टास्तत्सन्निधाने परिवर्जयेत्तु", text: "paryastikopāśrayakopahāsavivādaniṣṭhīvanajṛmbhaṇāni sarvāḥ prakṛtyabhyadhikāśca ceṣṭāstatsannidhāne parivarjayettu" },
      { type: "verse", number: "126", sanskrit: "सत्वाद्यवस्था विविधाश्च तास्ताः सम्यक् समीक्ष्या आत्महितं विदध्यात् अन्यो ऽपि यः कश्चिदिहा ऽस्ति मार्गो हितोपदेशेषु भजेत तं च", text: "satvādyavasthā vividhāśca tāstāḥ samyak samīkṣyā ātmahitaṃ vidadhyāt anyo 'pi yaḥ kaścidihā 'sti mārgo hitopadeśeṣu bhajeta taṃ ca" },
      { type: "verse", number: "127", sanskrit: "इति चरितमुपेतः सर्वजीवोपजीव्यं प्रथितपृथुगुणौधो रक्षितो देवताभिः समधिकशतजीवी निर्वृतः पुण्यकर्मा व्रजति सुगतिनिम्नो देहभेदे ऽपि तुष्टिम्", text: "iti caritamupetaḥ sarvajīvopajīvyaṃ prathitapṛthuguṇaudho rakṣito devatābhiḥ samadhikaśatajīvī nirvṛtaḥ puṇyakarmā vrajati sugatinimno dehabhede 'pi tuṣṭim" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 4,
    lang: "sa",
    content: [
      { type: "heading", heading: "Рога-абхишаджития — врач и пациент" },
      { type: "text", text: "Глава 4 Сутрастханы Астанга-санграхи посвящена теме «врач и пациент». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथात ऋतुचर्यां व्याख्यास्यामः इति हस्माहुरात्रेयादयो महर्षयः", text: "athāta ṛtucaryāṃ vyākhyāsyāmaḥ iti hasmāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "कालो हि नाम भगवाननादिनिधनो यथोपचितकर्मानुसारी यदनुरोधादादित्यादयः खादयश्च महाभूतविशेषास्तथा तथा विपरिणमन्तो जन्मवतां जन्ममरणस्यर्तुरसवीर्यदोपदेहबलव्यापत्सं पदां च कारणत्वं पत्ययतां प्रतिपद्यन्ते", text: "kālo hi nāma bhagavānanādinidhano yathopacitakarmānusārī yadanurodhādādityādayaḥ khādayaśca mahābhūtaviśeṣāstathā tathā vipariṇamanto janmavatāṃ janmamaraṇasyarturasavīryadopadehabalavyāpatsaṃ padāṃ ca kāraṇatvaṃ patyayatāṃ pratipadyante" },
      { type: "verse", number: "3", sanskrit: "स मात्राकाष्ठाकलानाडिकामुहूर्तयामाहोरात्रपक्षमासर्त्वयनवर्षभेदेन द्वादशधा विभज्यते", text: "sa mātrākāṣṭhākalānāḍikāmuhūrtayāmāhorātrapakṣamāsartvayanavarṣabhedena dvādaśadhā vibhajyate" },
      { type: "verse", number: "4", sanskrit: "तत्राक्षिनिमेषो मान्त्रा ताः पञ्चदश काष्ठा तास्त्रिंशत् कला ताः सदशभागा विंशतिर्नाडिका नाडिकाद्वयं मुहूर्तश्च ते तुल्यरात्रिन्दिवे राशिभागे चत्वारः पादोना यामः तैश्चतुर्भिरहो रात्रिश्च पञ्चदशाहोरात्राः पक्षः पक्षद्वयं मासः स शुक्लान्तः तैर्मार्गशीर्षादिभिर्द्विसंख्यैः क्रमाद्धेमन्तशिशिरवसन्तग्रीष्मवर्षशरदाख्याः षडृतवो भवन्ति तेषु शिशिरादयस्त्रयो रवेरुदगयनमादानञ्च शेषा दक्षिणायनं विसर्गश्च तावादानविसर्गौ वर्षम्", text: "tatrākṣinimeṣo māntrā tāḥ pañcadaśa kāṣṭhā tāstriṃśat kalā tāḥ sadaśabhāgā viṃśatirnāḍikā nāḍikādvayaṃ muhūrtaśca te tulyarātrindive rāśibhāge catvāraḥ pādonā yāmaḥ taiścaturbhiraho rātriśca pañcadaśāhorātrāḥ pakṣaḥ pakṣadvayaṃ māsaḥ sa śuklāntaḥ tairmārgaśīrṣādibhirdvisaṃkhyaiḥ kramāddhemantaśiśiravasantagrīṣmavarṣaśaradākhyāḥ ṣaḍṛtavo bhavanti teṣu śiśirādayastrayo raverudagayanamādānañca śeṣā dakṣiṇāyanaṃ visargaśca tāvādānavisargau varṣam" },
      { type: "verse", number: "5", sanskrit: "तयोरादानमाग्नेयम् तस्मिन् खलु कालस्वभावमार्गपरिगृहीतो ऽत्यर्थोप्णगभस्तिजालमण्डलो ऽर्कस्तत्संपर्काद्वायवश्च तीव्ररूक्षाः सोमजं गुणमुपशोषयन्तो जगतः स्नेहमाददाना ऋतुक्रमेणो पजनितरौक्ष्या रूक्षान् रसांस्तिक्तकषायकटुकानभिप्रबलयन्तो नृणां दौर्बल्यमावहन्ति", text: "tayorādānamāgneyam tasmin khalu kālasvabhāvamārgaparigṛhīto 'tyarthopṇagabhastijālamaṇḍalo 'rkastatsaṃparkādvāyavaśca tīvrarūkṣāḥ somajaṃ guṇamupaśoṣayanto jagataḥ snehamādadānā ṛtukrameṇo pajanitaraukṣyā rūkṣān rasāṃstiktakaṣāyakaṭukānabhiprabalayanto nṛṇāṃ daurbalyamāvahanti" },
      { type: "verse", number: "6", sanskrit: "वसर्गस्तु सौम्यः तस्मिन्नपि कालमार्गमेघवातवर्षाभिहतप्रभावे दक्षिणायनगे ऽर्के शशिनि चाव्याहतबले शिशिराभिर्भाभिः शश्वदाप्यायमाने माहेन्द्रसलिल प्रशान्त सन्तापे जगत्यरूक्षा रसाः प्रवर्धन्ते ऽम्ललवणमधुरा यथाक्रमं बलं चोपचीयते नृणामिति", text: "vasargastu saumyaḥ tasminnapi kālamārgameghavātavarṣābhihataprabhāve dakṣiṇāyanage 'rke śaśini cāvyāhatabale śiśirābhirbhābhiḥ śaśvadāpyāyamāne māhendrasalila praśānta santāpe jagatyarūkṣā rasāḥ pravardhante 'mlalavaṇamadhurā yathākramaṃ balaṃ copacīyate nṛṇāmiti" },
      { type: "verse", number: "7", sanskrit: "भवति चात्र हेमन्ते शिशिरे चाग्र्यं विसर्गादानयोर्बलम् शरद्वसन्तयोर्मध्यं हीनं वर्षानिदाघयोः", text: "bhavati cātra hemante śiśire cāgryaṃ visargādānayorbalam śaradvasantayormadhyaṃ hīnaṃ varṣānidāghayoḥ" },
      { type: "verse", number: "8", sanskrit: "धूमधूम्ररजोमन्दास्तुषाराविलमण्डलाः दिगादित्या मरुच्छैत्यादुत्तरो रोमहर्षणः", text: "dhūmadhūmrarajomandāstuṣārāvilamaṇḍalāḥ digādityā marucchaityāduttaro romaharṣaṇaḥ" },
      { type: "verse", number: "9", sanskrit: "लोध्रप्रियङ्गुपुन्नागलवल्यः कुसुमोज्वलाः दृप्ता गजाजमहिषवाजिवायससूकराः", text: "lodhrapriyaṅgupunnāgalavalyaḥ kusumojvalāḥ dṛptā gajājamahiṣavājivāyasasūkarāḥ" },
      { type: "verse", number: "10", sanskrit: "हिमानीपटलच्छन्ना लीनमीनविहङ्गमाः नद्यः सबाष्पाः सोष्माणः कूपापश्च हिमागमे", text: "himānīpaṭalacchannā līnamīnavihaṅgamāḥ nadyaḥ sabāṣpāḥ soṣmāṇaḥ kūpāpaśca himāgame" },
      { type: "verse", number: "11", sanskrit: "देहोष्माणो विशन्तो ऽन्तः शीते शीतानिलाहताः जठरे पिण्डितोष्माणं प्रबलं कुर्वते ऽनलम्", text: "dehoṣmāṇo viśanto 'ntaḥ śīte śītānilāhatāḥ jaṭhare piṇḍitoṣmāṇaṃ prabalaṃ kurvate 'nalam" },
      { type: "verse", number: "12", sanskrit: "विसर्गे बलिनां प्रायः स्वभावादिगुरुक्षमम् बृंहणान्यन्नपानानि योजयेत्तस्य युक्तये", text: "visarge balināṃ prāyaḥ svabhāvādigurukṣamam bṛṃhaṇānyannapānāni yojayettasya yuktaye" },
      { type: "verse", number: "13", sanskrit: "अनिन्धनो ऽन्यथा सीदेदत्युदीर्णतया ऽथवा धातूनपि पचेदस्य ततस्तेषां क्षयान्मरुत्", text: "anindhano 'nyathā sīdedatyudīrṇatayā 'thavā dhātūnapi pacedasya tatasteṣāṃ kṣayānmarut" },
      { type: "verse", number: "14", sanskrit: "तेजः सहचरः कुप्येच्छीतः शीते विशेषतः अतो हिमे भजेत्स्निग्धान् स्वाद्वम्ललवणान्रसान्", text: "tejaḥ sahacaraḥ kupyecchītaḥ śīte viśeṣataḥ ato hime bhajetsnigdhān svādvamlalavaṇānrasān" },
      { type: "verse", number: "15", sanskrit: "बिलेशयौदकानूपप्रसहानां भृतानि च मांसानि गुडपिष्टोत्थमद्यान्यभिनवानि च", text: "bileśayaudakānūpaprasahānāṃ bhṛtāni ca māṃsāni guḍapiṣṭotthamadyānyabhinavāni ca" },
      { type: "verse", number: "16", sanskrit: "माषेक्षुक्षीरविकृतिवसातैलनवौदनान् व्यायामोद्वर्तनाभ्यङ्गस्वेदधूमाञ्जनातपान्", text: "māṣekṣukṣīravikṛtivasātailanavaudanān vyāyāmodvartanābhyaṅgasvedadhūmāñjanātapān" },
      { type: "verse", number: "17", sanskrit: "सुखोदकं शौचविधौ भूमिगर्भगृहाणि च साङ्गारयानां शय्यां च कुथकम्बलसंस्कृताम्", text: "sukhodakaṃ śaucavidhau bhūmigarbhagṛhāṇi ca sāṅgārayānāṃ śayyāṃ ca kuthakambalasaṃskṛtām" },
      { type: "verse", number: "18", sanskrit: "कुङ्कुमेनानुलिप्ताङ्गो गुरुणा ऽगरुणा ऽपि वा लघूष्णैः प्रावृतः स्वप्यात् काले धूपाधिवासितः", text: "kuṅkumenānuliptāṅgo guruṇā 'garuṇā 'pi vā laghūṣṇaiḥ prāvṛtaḥ svapyāt kāle dhūpādhivāsitaḥ" },
      { type: "verse", number: "19", sanskrit: "पीनाङ्गनाङ्गसंसङ्गनिवारितहिमानिलः शिशिरे शीतमधिकं मेघमाउतवर्षजम्", text: "pīnāṅganāṅgasaṃsaṅganivāritahimānilaḥ śiśire śītamadhikaṃ meghamāutavarṣajam" },
      { type: "verse", number: "20", sanskrit: "रौक्ष्यं च आदानजं तस्मात् कार्यः पूर्वो ऽधिकं विधिः वसन्ते दक्षिणो वायुराताम्रकिरणो रविः", text: "raukṣyaṃ ca ādānajaṃ tasmāt kāryaḥ pūrvo 'dhikaṃ vidhiḥ vasante dakṣiṇo vāyurātāmrakiraṇo raviḥ" },
      { type: "verse", number: "21", sanskrit: "नवप्रवालत्वक्पत्राः पादपाः ककुभो ऽमलाः किंशुकाशोकचूतादिवनराजिविराजिताः", text: "navapravālatvakpatrāḥ pādapāḥ kakubho 'malāḥ kiṃśukāśokacūtādivanarājivirājitāḥ" },
      { type: "verse", number: "22", sanskrit: "कोकिलालिकुलालापकलकोलाहलाकुलाः शिशिरे सञ्चितः श्लेष्मा दिनकृद्भाभिरीरितः", text: "kokilālikulālāpakalakolāhalākulāḥ śiśire sañcitaḥ śleṣmā dinakṛdbhābhirīritaḥ" },
      { type: "verse", number: "23", sanskrit: "तदा प्रबाधमानो ऽग्निं रोगान् प्रकुरुते बहून् अतो ऽस्मिंस्तीक्ष्णवमनधूमगण्डूषनावनम्", text: "tadā prabādhamāno 'gniṃ rogān prakurute bahūn ato 'smiṃstīkṣṇavamanadhūmagaṇḍūṣanāvanam" },
      { type: "verse", number: "24", sanskrit: "व्यायामोद्वर्त्तनक्षौद्रयवगोधूमजाङ्गलान् सेवेत सुहृदुद्यानयुवतीश्च मनोरमाः", text: "vyāyāmodvarttanakṣaudrayavagodhūmajāṅgalān seveta suhṛdudyānayuvatīśca manoramāḥ" },
      { type: "verse", number: "25", sanskrit: "स्नातः स्वलङ्कृतः स्रग्वी चन्दनागरुरूषितः विचित्रामत्रविन्यस्तान् सहकारोत्पलाङ्कितान्", text: "snātaḥ svalaṅkṛtaḥ sragvī candanāgarurūṣitaḥ vicitrāmatravinyastān sahakārotpalāṅkitān" },
      { type: "verse", number: "26", sanskrit: "निगदांश्च आसवारिष्टशीधुमार्द्वीकमाधवान् क्वथितं मुस्तशुण्ठ्यम्बु साराम्भः क्षौद्रवारि वा", text: "nigadāṃśca āsavāriṣṭaśīdhumārdvīkamādhavān kvathitaṃ mustaśuṇṭhyambu sārāmbhaḥ kṣaudravāri vā" },
      { type: "verse", number: "27", sanskrit: "गुरुशीतदिवास्वप्नस्निग्धाम्लमधुरांस्त्यजेत् ग्रीष्मे ऽतसीपुष्पनिभस्तीक्ष्णांशुर्दावदीपिताः", text: "guruśītadivāsvapnasnigdhāmlamadhurāṃstyajet grīṣme 'tasīpuṣpanibhastīkṣṇāṃśurdāvadīpitāḥ" },
      { type: "verse", number: "28", sanskrit: "दिशो ज्वलन्ति भूमिश्च मारुतो नैऋतः सुखः पवनातपसंस्वेदैर्जन्तवो ज्वरिता इव", text: "diśo jvalanti bhūmiśca māruto naiṛtaḥ sukhaḥ pavanātapasaṃsvedairjantavo jvaritā iva" },
      { type: "verse", number: "29", sanskrit: "तापार्ततुङ्गमातङ्गमहिषैः कलुषीकृताः दिवाकरकराङ्गारनिकरक्षपिताम्भसः", text: "tāpārtatuṅgamātaṅgamahiṣaiḥ kaluṣīkṛtāḥ divākarakarāṅgāranikarakṣapitāmbhasaḥ" },
      { type: "verse", number: "30", sanskrit: "प्रवृद्धरोधसो नद्यः च्छायाहीना महीरुहाः विशीर्णजीर्णपर्णाश्च शुष्कवल्कलताङ्किताः", text: "pravṛddharodhaso nadyaḥ cchāyāhīnā mahīruhāḥ viśīrṇajīrṇaparṇāśca śuṣkavalkalatāṅkitāḥ" },
      { type: "verse", number: "31", sanskrit: "आदत्ते जगतस्तेजस्तद आदित्यो भृशं यतः व्यायामातपकट्वम्ललवणोष्णं त्यजेदतः", text: "ādatte jagatastejastada ādityo bhṛśaṃ yataḥ vyāyāmātapakaṭvamlalavaṇoṣṇaṃ tyajedataḥ" },
      { type: "verse", number: "32", sanskrit: "मद्यं न सेव्यं स्वल्पं वा सेव्यं सुबहुवारि वा अन्यथा शोफशैथिल्यदाहमोहान् करोति तत्", text: "madyaṃ na sevyaṃ svalpaṃ vā sevyaṃ subahuvāri vā anyathā śophaśaithilyadāhamohān karoti tat" },
      { type: "verse", number: "33", sanskrit: "नवमृद्भाजनस्थानि हृद्यानि सुरभीणि च पानकानि समन्थानि सिताढ्यानि हिमानि च", text: "navamṛdbhājanasthāni hṛdyāni surabhīṇi ca pānakāni samanthāni sitāḍhyāni himāni ca" },
      { type: "verse", number: "34", sanskrit: "स्वादु शीतं द्रवं चान्नं जाङ्गलान्मृगपक्षिणः शालिक्षीरघृतद्राक्षानालिकेराम्बुशर्कराः", text: "svādu śītaṃ dravaṃ cānnaṃ jāṅgalānmṛgapakṣiṇaḥ śālikṣīraghṛtadrākṣānālikerāmbuśarkarāḥ" },
      { type: "verse", number: "35", sanskrit: "तालवृन्तानिलान् हारान् स्रजः सकमलोत्पलाः तन्वीर्मृणालवलयाः कान्ताश्चन्दनरूषिताः", text: "tālavṛntānilān hārān srajaḥ sakamalotpalāḥ tanvīrmṛṇālavalayāḥ kāntāścandanarūṣitāḥ" },
      { type: "verse", number: "36", sanskrit: "सरांसि वापिः सरितः काननानि हिमानि च सुरभीणि निषेवेत वासांसि सुलघूनि च", text: "sarāṃsi vāpiḥ saritaḥ kānanāni himāni ca surabhīṇi niṣeveta vāsāṃsi sulaghūni ca" },
      { type: "verse", number: "37", sanskrit: "निष्पतद्यन्त्रसलिले स्वप्याद्धारागृहे दिवा रात्रौ च आकाशतलके सुगन्धिकुसुमास्तृते", text: "niṣpatadyantrasalile svapyāddhārāgṛhe divā rātrau ca ākāśatalake sugandhikusumāstṛte" },
      { type: "verse", number: "38", sanskrit: "कर्पूरचन्दनार्द्राङ्गो विरलानङ्गसङ्गमः वर्षासु वारुणो वायुः सर्वसस्यसमुद्गमः", text: "karpūracandanārdrāṅgo viralānaṅgasaṅgamaḥ varṣāsu vāruṇo vāyuḥ sarvasasyasamudgamaḥ" },
      { type: "verse", number: "39", sanskrit: "भिन्नेन्द्रनीलनीलाभ्रवृन्दमन्दाविलं नभः दीर्घिकानववार्यौघमग्नसोपानपङ्क्तयः", text: "bhinnendranīlanīlābhravṛndamandāvilaṃ nabhaḥ dīrghikānavavāryaughamagnasopānapaṅktayaḥ" },
      { type: "verse", number: "40", sanskrit: "वारिधाराभृशाघातविकासितसरोरुहाः सरितः सागराकारा भूरव्यक्तजलस्थला", text: "vāridhārābhṛśāghātavikāsitasaroruhāḥ saritaḥ sāgarākārā bhūravyaktajalasthalā" },
      { type: "verse", number: "41", sanskrit: "मन्द्रस्तनितजीमूतशिखिदर्दुरनादिता इन्द्रगोपधनुःखण्डविद्युदुद्योतदीपिता", text: "mandrastanitajīmūtaśikhidarduranāditā indragopadhanuḥkhaṇḍavidyududyotadīpitā" },
      { type: "verse", number: "42", sanskrit: "परितः श्यामलतृणा सिलिन्ध्रकुटजोज्वला तदादानाबले देहे मन्दे ऽग्नौ बाधिते पुनः", text: "paritaḥ śyāmalatṛṇā silindhrakuṭajojvalā tadādānābale dehe mande 'gnau bādhite punaḥ" },
      { type: "verse", number: "43", sanskrit: "वृष्टिभूबाष्पतोयाम्लपाकदुष्टैश्चलादिभिः बस्तिकर्म निषेवेत कृतसंशोधनक्रमः", text: "vṛṣṭibhūbāṣpatoyāmlapākaduṣṭaiścalādibhiḥ bastikarma niṣeveta kṛtasaṃśodhanakramaḥ" },
      { type: "verse", number: "44", sanskrit: "पुराणाशालिगोधूमयवान् यूषरसैः कृतैः निगदं मदिरारिष्टमार्द्वीकं स्वल्पमम्बु वा", text: "purāṇāśāligodhūmayavān yūṣarasaiḥ kṛtaiḥ nigadaṃ madirāriṣṭamārdvīkaṃ svalpamambu vā" },
      { type: "verse", number: "45", sanskrit: "दिव्यं क्वथितकूपोत्थं चौण्डं सारसमेव वा वृष्टिवाताकुलेत्वन्हि भोजनं क्लेदवातजित्", text: "divyaṃ kvathitakūpotthaṃ cauṇḍaṃ sārasameva vā vṛṣṭivātākuletvanhi bhojanaṃ kledavātajit" },
      { type: "verse", number: "46", sanskrit: "परिशुष्कं लघुस्निग्धमुष्पाम्ललवणं भजेत् प्रायो ऽन्नपानं सक्षौद्रं संस्कृतं च घनोदये", text: "pariśuṣkaṃ laghusnigdhamuṣpāmlalavaṇaṃ bhajet prāyo 'nnapānaṃ sakṣaudraṃ saṃskṛtaṃ ca ghanodaye" },
      { type: "verse", number: "47", sanskrit: "असरीसृपभूबाष्पशीतमारुतशीकरम् साग्नियानं च भवनं निर्दंशमशकोन्दुरम्", text: "asarīsṛpabhūbāṣpaśītamārutaśīkaram sāgniyānaṃ ca bhavanaṃ nirdaṃśamaśakonduram" },
      { type: "verse", number: "48", sanskrit: "प्रघर्षोद्वर्तनस्नानधूमगन्धागरुप्रियः यायात् करेणुमुख्याभिश्चित्रस्रग्वस्त्रभूषितः", text: "pragharṣodvartanasnānadhūmagandhāgarupriyaḥ yāyāt kareṇumukhyābhiścitrasragvastrabhūṣitaḥ" },
      { type: "verse", number: "49", sanskrit: "नदीजलोदमन्थाहः स्वप्नातिद्रवमैथुनम् तुषारपादचरणव्यायामार्ककरांस्त्यजेत्", text: "nadījalodamanthāhaḥ svapnātidravamaithunam tuṣārapādacaraṇavyāyāmārkakarāṃstyajet" },
      { type: "verse", number: "50", sanskrit: "शरदि व्योम शुभ्राभ्रं किञ्चित् पङ्काङ्किता मही प्रकाशकाशसप्ताह्वकुमुदा शालिशालिनी", text: "śaradi vyoma śubhrābhraṃ kiñcit paṅkāṅkitā mahī prakāśakāśasaptāhvakumudā śāliśālinī" },
      { type: "verse", number: "51", sanskrit: "विक्षिप्ततीक्ष्णकिरणो मेघौघविगमाद्रविः बभ्रुवर्णो ऽतिविमलाः क्रौञ्चमालाकुला दिशः", text: "vikṣiptatīkṣṇakiraṇo meghaughavigamādraviḥ babhruvarṇo 'tivimalāḥ krauñcamālākulā diśaḥ" },
      { type: "verse", number: "52", sanskrit: "कमलान्तरसंलीनमीनहंसांसघट्टनैः तरङ्गभङ्गानि सरांसि विमलानि च", text: "kamalāntarasaṃlīnamīnahaṃsāṃsaghaṭṭanaiḥ taraṅgabhaṅgāni sarāṃsi vimalāni ca" },
      { type: "verse", number: "53", sanskrit: "वर्षाशीतोचिताङ्गानां सहसैवार्करश्मिभिः तप्तानां सञ्चितं पूर्वं तदा पित्तं प्रकुप्यति", text: "varṣāśītocitāṅgānāṃ sahasaivārkaraśmibhiḥ taptānāṃ sañcitaṃ pūrvaṃ tadā pittaṃ prakupyati" },
      { type: "verse", number: "54", sanskrit: "शस्तं तिक्तहविःपानं विरेको ऽस्रस्रुतिः सदा शीतं लघ्वन्नपानं च कषायस्वादुतिक्तकम्", text: "śastaṃ tiktahaviḥpānaṃ vireko 'srasrutiḥ sadā śītaṃ laghvannapānaṃ ca kaṣāyasvādutiktakam" },
      { type: "verse", number: "55", sanskrit: "शालिषष्टिकगोधूमयवमुद्गसितामधु पटोलामलकं द्राक्षा जाङ्गलं क्षुद्वतां भृशम्", text: "śāliṣaṣṭikagodhūmayavamudgasitāmadhu paṭolāmalakaṃ drākṣā jāṅgalaṃ kṣudvatāṃ bhṛśam" },
      { type: "verse", number: "56", sanskrit: "दिवा दिवाकरकरैर्निशाकरकरौर्नीशि सन्तप्तं ह्लादितं तोयमगस्त्येनाविषीकृतम्", text: "divā divākarakarairniśākarakaraurnīśi santaptaṃ hlāditaṃ toyamagastyenāviṣīkṛtam" },
      { type: "verse", number: "57", sanskrit: "निर्मलं शुचि कालेन पक्वं पाने ऽमृतोपमम् हंसौघपक्षविक्षेपभ्रमत्भ्रमरपङ्क्तिषु", text: "nirmalaṃ śuci kālena pakvaṃ pāne 'mṛtopamam haṃsaughapakṣavikṣepabhramatbhramarapaṅktiṣu" },
      { type: "verse", number: "58", sanskrit: "सुसरोरुहसेव्यासु सरसीषु प्लवेत च लघुशुद्धाम्बरः स्रग्वी शीतोशीरविलेपनः", text: "susaroruhasevyāsu sarasīṣu plaveta ca laghuśuddhāmbaraḥ sragvī śītośīravilepanaḥ" },
      { type: "verse", number: "59", sanskrit: "सेवेत चन्द्रकिरणान् प्रदोषे सौधमाश्रितः तृप्तिदध्यातपक्षारवसातैलपुरोनिलान्", text: "seveta candrakiraṇān pradoṣe saudhamāśritaḥ tṛptidadhyātapakṣāravasātailapuronilān" },
      { type: "verse", number: "60", sanskrit: "तीक्ष्णमद्यदिवास्वप्नतुषारांश्च विवर्जयेत् नित्यं सर्वरसाभ्यासः स्वस्वाधिक्यमृतावृतौ", text: "tīkṣṇamadyadivāsvapnatuṣārāṃśca vivarjayet nityaṃ sarvarasābhyāsaḥ svasvādhikyamṛtāvṛtau" },
      { type: "verse", number: "61", sanskrit: "र्त्वोरन्तादिसप्ताहावृतुसन्धिरिति स्मृतः तत्र पूर्वो विधिस्त्याज्यः सेवनीयो ऽपरः क्रमात्", text: "rtvorantādisaptāhāvṛtusandhiriti smṛtaḥ tatra pūrvo vidhistyājyaḥ sevanīyo 'paraḥ kramāt" },
      { type: "verse", number: "62", sanskrit: "असात्म्यजा हि रोगाः स्युः सहसा त्यागशीलनात् र्तुष्वेवंविधेष्वेष विधिः स्वास्थ्ये च देहिनां", text: "asātmyajā hi rogāḥ syuḥ sahasā tyāgaśīlanāt rtuṣvevaṃvidheṣveṣa vidhiḥ svāsthye ca dehināṃ" },
      { type: "verse", number: "63", sanskrit: "निर्दिश्यते ऽन्यरूपेषु विरुद्धाज्ञानिको विधिः मासराशिस्वरूपाख्यमृतोर्यल्लक्षणत्रयम्", text: "nirdiśyate 'nyarūpeṣu viruddhājñāniko vidhiḥ māsarāśisvarūpākhyamṛtoryallakṣaṇatrayam" },
      { type: "verse", number: "64", sanskrit: "यथोत्तरंभजेच्चर्यां तत्र तस्य बलादिति", text: "yathottaraṃbhajeccaryāṃ tatra tasya balāditi" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 5,
    lang: "sa",
    content: [
      { type: "heading", heading: "Доша сварупа — природа трёх дош" },
      { type: "text", text: "Глава 5 Сутрастханы Астанга-санграхи посвящена теме «природа трёх дош». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो रोगानुत्पादनीयं नामाध्ययं व्याख्यास्यामः इतिहस्माहुरात्रेयादयो महर्षयः", text: "athāto rogānutpādanīyaṃ nāmādhyayaṃ vyākhyāsyāmaḥ itihasmāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "वेगान् नधारयेद्वातविण्मूत्रक्षवतृट्क्षुधाम् निद्राकासश्रमश्वासजृम्भाश्रुच्छर्दिरेतसाम्", text: "vegān nadhārayedvātaviṇmūtrakṣavatṛṭkṣudhām nidrākāsaśramaśvāsajṛmbhāśrucchardiretasām" },
      { type: "verse", number: "3", sanskrit: "अधोवातस्य रोधेन गुल्मोदावर्तरुक्क्लमाः वातमूत्रशकृत्सङ्गद्दष्ट्यग्निवधहृद्गदाः", text: "adhovātasya rodhena gulmodāvartarukklamāḥ vātamūtraśakṛtsaṅgaddaṣṭyagnivadhahṛdgadāḥ" },
      { type: "verse", number: "4", sanskrit: "शकृतः पिण्डिकोद्वेष्टप्रतिश्यायशिरोरुजः ऊर्ध्ववायुः परीकर्तो हृदयस्योपरोधनम्", text: "śakṛtaḥ piṇḍikodveṣṭapratiśyāyaśirorujaḥ ūrdhvavāyuḥ parīkarto hṛdayasyoparodhanam" },
      { type: "verse", number: "5", sanskrit: "मुखेन विट्प्रवृत्तिश्च पूर्वोक्ताश्चामयाः स्मृताः अङ्गभङ्गाश्मरीबस्तिमेढ्रवंक्षणवेदनाः", text: "mukhena viṭpravṛttiśca pūrvoktāścāmayāḥ smṛtāḥ aṅgabhaṅgāśmarībastimeḍhravaṃkṣaṇavedanāḥ" },
      { type: "verse", number: "6", sanskrit: "मूत्रस्य रोधात् पूर्वे च प्रायो रोगाः तदौषधम् वर्त्यभ्यङ्गवगाहाश्च स्वेदनं बस्तिकर्म च", text: "mūtrasya rodhāt pūrve ca prāyo rogāḥ tadauṣadham vartyabhyaṅgavagāhāśca svedanaṃ bastikarma ca" },
      { type: "verse", number: "7", sanskrit: "अन्नपानं च विड्भेदि विड्रोधोत्थेषु यक्ष्मसु मूत्रजेषु तु पाने च प्राग्भक्तं शस्येत घृतम्", text: "annapānaṃ ca viḍbhedi viḍrodhottheṣu yakṣmasu mūtrajeṣu tu pāne ca prāgbhaktaṃ śasyeta ghṛtam" },
      { type: "verse", number: "8", sanskrit: "जीर्णान्तिकं चोत्तमया मात्रया योजनाद्वयम् अवपीडकमेतच्च संज्ञितं धारणात् पुनः", text: "jīrṇāntikaṃ cottamayā mātrayā yojanādvayam avapīḍakametacca saṃjñitaṃ dhāraṇāt punaḥ" },
      { type: "verse", number: "9", sanskrit: "उद्गारस्यारुचिः कम्पो विबन्धो हृदयोरसोः आध्मानकासहिध्माश्च हिध्मावत्तत्र भेषजम्", text: "udgārasyāruciḥ kampo vibandho hṛdayorasoḥ ādhmānakāsahidhmāśca hidhmāvattatra bheṣajam" },
      { type: "verse", number: "10", sanskrit: "शिरोर्तीन्द्रियदौर्बल्यमन्यास्तम्भार्दितं क्षुतेः तीक्ष्णधूमाञ्जनाघ्राणनावनार्कविलोकनैः", text: "śirortīndriyadaurbalyamanyāstambhārditaṃ kṣuteḥ tīkṣṇadhūmāñjanāghrāṇanāvanārkavilokanaiḥ" },
      { type: "verse", number: "11", sanskrit: "प्रवर्तयेत् क्षुतिं सक्तां स्वेदाभ्यङ्गौ च शीलयेत् योज्यं वातघ्नमन्नं च घृतं चौत्तरभक्तिकम्", text: "pravartayet kṣutiṃ saktāṃ svedābhyaṅgau ca śīlayet yojyaṃ vātaghnamannaṃ ca ghṛtaṃ cauttarabhaktikam" },
      { type: "verse", number: "12", sanskrit: "शोषाङ्गसादबधिर्यसम्मोहभ्रमहृद्गदाः तृप्णाया निग्रहात्तत्र शीतः सर्वो विधिर्हितः", text: "śoṣāṅgasādabadhiryasammohabhramahṛdgadāḥ tṛpṇāyā nigrahāttatra śītaḥ sarvo vidhirhitaḥ" },
      { type: "verse", number: "13", sanskrit: "अङ्गभङ्गारुचिग्लानिकार्श्यशूलभ्रमाः क्षुधः तत्र योज्यं लघु स्निग्धमुष्णमल्पं च भोजनम्", text: "aṅgabhaṅgāruciglānikārśyaśūlabhramāḥ kṣudhaḥ tatra yojyaṃ laghu snigdhamuṣṇamalpaṃ ca bhojanam" },
      { type: "verse", number: "14", sanskrit: "निद्राया मोहमूर्धाक्षिगौरवालस्यजृम्भिकाः अङ्गमर्दश्च तत्रेष्टः स्वप्नः संवाहनानि च", text: "nidrāyā mohamūrdhākṣigauravālasyajṛmbhikāḥ aṅgamardaśca tatreṣṭaḥ svapnaḥ saṃvāhanāni ca" },
      { type: "verse", number: "15", sanskrit: "कासस्य रोधात्तद्वृद्धिः श्वासारुचिहृदामयाः शोषो हिध्मा च कार्यो ऽत्र कासहा सुतरां विधिः", text: "kāsasya rodhāttadvṛddhiḥ śvāsārucihṛdāmayāḥ śoṣo hidhmā ca kāryo 'tra kāsahā sutarāṃ vidhiḥ" },
      { type: "verse", number: "16", sanskrit: "गुल्महृद्रोगसम्मोहाः श्रमश्वासाद्विधारितात् हितं विश्रमणं तत्र वातघ्नश्च क्रियाक्रमः", text: "gulmahṛdrogasammohāḥ śramaśvāsādvidhāritāt hitaṃ viśramaṇaṃ tatra vātaghnaśca kriyākramaḥ" },
      { type: "verse", number: "17", sanskrit: "जृम्भायाः क्षववद्रोगाः सर्वश्चानिलजिद्विधिः पीनसाक्षिशिरोहृद्रुङ्मन्यास्तम्भारुचिभ्रमाः", text: "jṛmbhāyāḥ kṣavavadrogāḥ sarvaścānilajidvidhiḥ pīnasākṣiśirohṛdruṅmanyāstambhārucibhramāḥ" },
      { type: "verse", number: "18", sanskrit: "सगुल्मा बाष्पतस्तत्र स्वप्नो मद्यं प्रियाः कथाः विसर्पकोठकुष्ठाक्षिकण्डूपाण्ड्वामयज्वराः", text: "sagulmā bāṣpatastatra svapno madyaṃ priyāḥ kathāḥ visarpakoṭhakuṣṭhākṣikaṇḍūpāṇḍvāmayajvarāḥ" },
      { type: "verse", number: "19", sanskrit: "सकासश्वसहृल्लासव्यङ्गश्वयथवो वमेः गण्डूषधूमानाहारं रुक्षं भुक्त्वा तदुद्वमः", text: "sakāsaśvasahṛllāsavyaṅgaśvayathavo vameḥ gaṇḍūṣadhūmānāhāraṃ rukṣaṃ bhuktvā tadudvamaḥ" },
      { type: "verse", number: "20", sanskrit: "व्यायामः स्रुतिरस्रस्य शस्तं चात्र विरेचनम् सक्षारलवणं तैलमभ्यङ्गार्थे च शस्यते", text: "vyāyāmaḥ srutirasrasya śastaṃ cātra virecanam sakṣāralavaṇaṃ tailamabhyaṅgārthe ca śasyate" },
      { type: "verse", number: "21", sanskrit: "शुक्रात्तत्स्रवणं गुह्यवेदनाश्वयथुज्वराः हृद्व्यथा मूत्रसङ्गाङ्गभङ्गवर्ध्माश्मषण्ढताः", text: "śukrāttatsravaṇaṃ guhyavedanāśvayathujvarāḥ hṛdvyathā mūtrasaṅgāṅgabhaṅgavardhmāśmaṣaṇḍhatāḥ" },
      { type: "verse", number: "22", sanskrit: "तास्रचूडसुराशलिबस्त्यभ्यङ्गावगाहनम् बस्तिशुद्धिकरैः सिद्धं भजेत् क्षीरं प्रियाः स्त्रियः", text: "tāsracūḍasurāśalibastyabhyaṅgāvagāhanam bastiśuddhikaraiḥ siddhaṃ bhajet kṣīraṃ priyāḥ striyaḥ" },
      { type: "verse", number: "23", sanskrit: "तत्र सेवेत सर्वं च वर्जयेद्वेगधारिणम् विड्वामिनं परिक्लिष्टं क्षीणं तृट्छूलपीडितम्", text: "tatra seveta sarvaṃ ca varjayedvegadhāriṇam viḍvāminaṃ parikliṣṭaṃ kṣīṇaṃ tṛṭchūlapīḍitam" },
      { type: "verse", number: "24", sanskrit: "रोगाः सर्वे ऽपि जायन्ते वेगोदीरणधारणैः निर्दिष्टं साधनं तत्र भूयिष्ठं ये तु तान् प्रति", text: "rogāḥ sarve 'pi jāyante vegodīraṇadhāraṇaiḥ nirdiṣṭaṃ sādhanaṃ tatra bhūyiṣṭhaṃ ye tu tān prati" },
      { type: "verse", number: "25", sanskrit: "ततश्चानेकधा प्रायः पवनो यत् प्रकुप्यति अन्नपानौषधं तस्य युञ्जीतातो ऽनुलोमनम्", text: "tataścānekadhā prāyaḥ pavano yat prakupyati annapānauṣadhaṃ tasya yuñjītāto 'nulomanam" },
      { type: "verse", number: "26", sanskrit: "क्रमादपामपि मणौ पङ्को ऽवश्यंभवत्यतः उत्तिष्ठेत यथाकालं मलानां शोधनं प्रति", text: "kramādapāmapi maṇau paṅko 'vaśyaṃbhavatyataḥ uttiṣṭheta yathākālaṃ malānāṃ śodhanaṃ prati" },
      { type: "verse", number: "27", sanskrit: "चयकाष्ठामुपारुह्य कुर्वते ते ह्युपेक्षिताः प्रायशः सुचिरेणापि भेषजद्वेषिणोगदान्", text: "cayakāṣṭhāmupāruhya kurvate te hyupekṣitāḥ prāyaśaḥ sucireṇāpi bheṣajadveṣiṇogadān" },
      { type: "verse", number: "28", sanskrit: "अतिस्थौल्याग्निसदनमेहकुष्ठहृतौजसः स्रोतोरोधाक्षविभ्रंशश्वासश्वयथुपाण्डुताः", text: "atisthaulyāgnisadanamehakuṣṭhahṛtaujasaḥ srotorodhākṣavibhraṃśaśvāsaśvayathupāṇḍutāḥ" },
      { type: "verse", number: "29", sanskrit: "आमोरुस्तम्भजठरकृच्छ्रालसकदण्डकान् च्छर्दिगण्डकृमिग्रन्थितन्द्रादुःस्वप्नदर्शनम्", text: "āmorustambhajaṭharakṛcchrālasakadaṇḍakān cchardigaṇḍakṛmigranthitandrāduḥsvapnadarśanam" },
      { type: "verse", number: "30", sanskrit: "कण्ठामयान् मूर्द्धरुजं प्रणाशं बुद्धिनिद्रयोः तेजोवर्णबलानां च तृप्यतो बृंहणैरपि", text: "kaṇṭhāmayān mūrddharujaṃ praṇāśaṃ buddhinidrayoḥ tejovarṇabalānāṃ ca tṛpyato bṛṃhaṇairapi" },
      { type: "verse", number: "31", sanskrit: "उचितैरपि चाहारैर्यस्मादस्य वहन्ति न दोषोपलिप्तवदना रसं रसवहाः सिराः", text: "ucitairapi cāhārairyasmādasya vahanti na doṣopaliptavadanā rasaṃ rasavahāḥ sirāḥ" },
      { type: "verse", number: "32", sanskrit: "वमनादीनतो युञ्ज्यात् स्वस्थस्थैव यथाविधि दोषाः कदाचित् कुप्यन्ति जिता लङ्घनपाचनैः", text: "vamanādīnato yuñjyāt svasthasthaiva yathāvidhi doṣāḥ kadācit kupyanti jitā laṅghanapācanaiḥ" },
      { type: "verse", number: "33", sanskrit: "ये तु संशोधनैः शुद्धा न तेषां पुनरुद्भवः यथाक्रमं यथायोगमत ऊर्ध्वं प्रयोजयेत्", text: "ye tu saṃśodhanaiḥ śuddhā na teṣāṃ punarudbhavaḥ yathākramaṃ yathāyogamata ūrdhvaṃ prayojayet" },
      { type: "verse", number: "34", sanskrit: "रसायनानि सिद्धानि वृष्ययोगांश्च कालवित् भेषजक्षपिते पथ्यमाहारैर्बृंहणं क्रमात्", text: "rasāyanāni siddhāni vṛṣyayogāṃśca kālavit bheṣajakṣapite pathyamāhārairbṛṃhaṇaṃ kramāt" },
      { type: "verse", number: "35", sanskrit: "शालिषष्टिकगोधूममांसक्षीरघृतादिभिः हृद्यदीपनभैषज्यसंयोगाद्रुचिपक्तिदैः", text: "śāliṣaṣṭikagodhūmamāṃsakṣīraghṛtādibhiḥ hṛdyadīpanabhaiṣajyasaṃyogādrucipaktidaiḥ" },
      { type: "verse", number: "36", sanskrit: "साभ्यङ्गोद्वर्तनस्नाननिरूहस्नेहबस्तिभिः तथा स लभते शर्म सर्वपावकपाटवम्", text: "sābhyaṅgodvartanasnānanirūhasnehabastibhiḥ tathā sa labhate śarma sarvapāvakapāṭavam" },
      { type: "verse", number: "37", sanskrit: "धीवर्णेन्द्रियवैमल्यं वृषतां दैर्घ्यमायुषः ये भूतविषवाय्वग्निक्षतभङ्गादिसम्भवाः", text: "dhīvarṇendriyavaimalyaṃ vṛṣatāṃ dairghyamāyuṣaḥ ye bhūtaviṣavāyvagnikṣatabhaṅgādisambhavāḥ" },
      { type: "verse", number: "58", sanskrit: "कामक्रोधभयाद्याश्च ते स्युरागन्तवो गदाः त्यागः प्रज्ञापराधानामिन्द्रियोपशमः स्मृतिः", text: "kāmakrodhabhayādyāśca te syurāgantavo gadāḥ tyāgaḥ prajñāparādhānāmindriyopaśamaḥ smṛtiḥ" },
      { type: "verse", number: "59", sanskrit: "देशकालात्मविज्ञानं सद्वृत्तस्यानुवर्तनम् अथर्वविहिता शान्तिः प्रतिकूलग्रहार्चनम्", text: "deśakālātmavijñānaṃ sadvṛttasyānuvartanam atharvavihitā śāntiḥ pratikūlagrahārcanam" },
      { type: "verse", number: "60", sanskrit: "भूताद्यस्यर्शनोपायो निर्दिष्टश्च पृथक् पृथक् अनुत्पत्यै समासेन विधिरेष प्रदर्शितः", text: "bhūtādyasyarśanopāyo nirdiṣṭaśca pṛthak pṛthak anutpatyai samāsena vidhireṣa pradarśitaḥ" },
      { type: "verse", number: "61", sanskrit: "निजागन्तुविकाराणामुत्पन्नानां च शान्तये", text: "nijāgantuvikārāṇāmutpannānāṃ ca śāntaye" },
      { type: "verse", number: "62", sanskrit: "शीतोद्भवं दोषचयं वसन्ते विशोधयन् ग्रीष्मजमभ्रकाले घनात्यये वार्षिकमाशु सम्यक् प्राप्नोति रोगानृतुजान् न जातु", text: "śītodbhavaṃ doṣacayaṃ vasante viśodhayan grīṣmajamabhrakāle ghanātyaye vārṣikamāśu samyak prāpnoti rogānṛtujān na jātu" },
      { type: "verse", number: "63", sanskrit: "नित्यं हिताहारविहारसेवी समीक्ष्यकारी विषयेष्वसक्तः दाता समः सत्यपरः क्षमावानाप्तोपसेवी च भवत्यरोगः", text: "nityaṃ hitāhāravihārasevī samīkṣyakārī viṣayeṣvasaktaḥ dātā samaḥ satyaparaḥ kṣamāvānāptopasevī ca bhavatyarogaḥ" },
      { type: "verse", number: "64", sanskrit: "अर्थेष्वलभ्येष्वकृतप्रयत्नं कृतादरं नित्यमपायवत्सु जितेन्द्रियं नानुपतान्ति रोगास्तत्कालयुक्तं यदि नास्ति दैवम्", text: "artheṣvalabhyeṣvakṛtaprayatnaṃ kṛtādaraṃ nityamapāyavatsu jitendriyaṃ nānupatānti rogāstatkālayuktaṃ yadi nāsti daivam" },
      { type: "verse", number: "65", sanskrit: "काले ऽनुकूलो विषया मनोज्ञा धर्म्याः क्रियाः कर्म सुखानुबन्धि सत्त्वं विधेयं विशदा च बुद्धिर्भवन्ति धीरस्य सदा सुखाय", text: "kāle 'nukūlo viṣayā manojñā dharmyāḥ kriyāḥ karma sukhānubandhi sattvaṃ vidheyaṃ viśadā ca buddhirbhavanti dhīrasya sadā sukhāya" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 6,
    lang: "sa",
    content: [
      { type: "heading", heading: "Дравья гуна — свойства веществ" },
      { type: "text", text: "Глава 6 Сутрастханы Астанга-санграхи посвящена теме «свойства веществ». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातोद्रवद्रव्यविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति हस्माहुरात्रेयादयो महर्षयः", text: "athātodravadravyavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti hasmāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "जीवनं तर्पणं हृद्यं ह्लादि बुद्धिप्रबोधनम् तन्वव्यक्तरसं मृष्टं शीतं शुच्यमृतोपमम्", text: "jīvanaṃ tarpaṇaṃ hṛdyaṃ hlādi buddhiprabodhanam tanvavyaktarasaṃ mṛṣṭaṃ śītaṃ śucyamṛtopamam" },
      { type: "verse", number: "3", sanskrit: "सूर्योध्दृतप्रमुक्तत्वाल्लघु वातकंफापहम् शैत्यजीवनसौम्यत्वैः पित्तरक्तविषार्तिजित्", text: "sūryodhdṛtapramuktatvāllaghu vātakaṃphāpaham śaityajīvanasaumyatvaiḥ pittaraktaviṣārtijit" },
      { type: "verse", number: "4", sanskrit: "गङ्गाम्बु नभसो भ्रष्टं त्वर्केन्दुमारुतैः हिताहितत्वे तत् भूयो देशकालावपेक्षते", text: "gaṅgāmbu nabhaso bhraṣṭaṃ tvarkendumārutaiḥ hitāhitatve tat bhūyo deśakālāvapekṣate" },
      { type: "verse", number: "5", sanskrit: "येनाभिवृष्टममलं शाल्यन्नं राजतस्थितम् अक्लिन्नमविवर्णं वा तत् पेयं गाङ्गमन्यथा", text: "yenābhivṛṣṭamamalaṃ śālyannaṃ rājatasthitam aklinnamavivarṇaṃ vā tat peyaṃ gāṅgamanyathā" },
      { type: "verse", number: "6", sanskrit: "सामुद्रं तन्न पातव्यं मासादाश्वयुजाद्विना खातधौतशिलापृष्ठवस्त्रादिभ्यश्च्युतं जलम्", text: "sāmudraṃ tanna pātavyaṃ māsādāśvayujādvinā khātadhautaśilāpṛṣṭhavastrādibhyaścyutaṃ jalam" },
      { type: "verse", number: "7", sanskrit: "हेममृन्मयपात्रस्थमविपन्नं सदा पिबेत् तदभावे च भूमिष्ठमान्तरिक्षानुकारि यत्", text: "hemamṛnmayapātrasthamavipannaṃ sadā pibet tadabhāve ca bhūmiṣṭhamāntarikṣānukāri yat" },
      { type: "verse", number: "8", sanskrit: "श्वेते कषायं तत्स्वादु कृष्णे तिक्तं च पाण्डुरे नीले कषायमधुरं देशे लवणमूषरे", text: "śvete kaṣāyaṃ tatsvādu kṛṣṇe tiktaṃ ca pāṇḍure nīle kaṣāyamadhuraṃ deśe lavaṇamūṣare" },
      { type: "verse", number: "9", sanskrit: "सक्षारं कपिले मिश्रं मिश्रे ऽथाम्बुगुणाधिके मधुरं लवणाम्लं तु भवेत्भूमिगुणाधिके", text: "sakṣāraṃ kapile miśraṃ miśre 'thāmbuguṇādhike madhuraṃ lavaṇāmlaṃ tu bhavetbhūmiguṇādhike" },
      { type: "verse", number: "10", sanskrit: "तेजोधिके तिक्तकटु कषायं पवनाधिके दिव्यानुकारि त्वव्यक्तरसत्वात् खगुणाधिके", text: "tejodhike tiktakaṭu kaṣāyaṃ pavanādhike divyānukāri tvavyaktarasatvāt khaguṇādhike" },
      { type: "verse", number: "11", sanskrit: "शुचिपृथ्वसितश्वेते देशे चार्कानिलाहतम् कौपसारसताटाकचौण्डप्रास्रवणौद्भिदम्", text: "śucipṛthvasitaśvete deśe cārkānilāhatam kaupasārasatāṭākacauṇḍaprāsravaṇaudbhidam" },
      { type: "verse", number: "12", sanskrit: "वापीनदीतोयमिति तत् पुनः स्मृतमष्टधा सक्षारं पित्तकृत् कौपं दीपनान्नातिवातलम्", text: "vāpīnadītoyamiti tat punaḥ smṛtamaṣṭadhā sakṣāraṃ pittakṛt kaupaṃ dīpanānnātivātalam" },
      { type: "verse", number: "13", sanskrit: "सारसं स्वादु लघु च ताटाकं गुरु वातलम् चौण्डं तु पित्तलं दोषहरं प्रास्रवणोदकम्", text: "sārasaṃ svādu laghu ca tāṭākaṃ guru vātalam cauṇḍaṃ tu pittalaṃ doṣaharaṃ prāsravaṇodakam" },
      { type: "verse", number: "14", sanskrit: "औद्भिदं स्वादु पित्तघ्नं स्वादु वापीजलं गघु नादेयं वातलं रूक्षं कटुकं च तदादिशेत्", text: "audbhidaṃ svādu pittaghnaṃ svādu vāpījalaṃ gaghu nādeyaṃ vātalaṃ rūkṣaṃ kaṭukaṃ ca tadādiśet" },
      { type: "verse", number: "15", sanskrit: "धन्वानूपमहीध्राणां सामीप्यात् गुरुलाघवम् पश्चिमोदधिगाः शीघ्रवहा याश्चामलोदकाः", text: "dhanvānūpamahīdhrāṇāṃ sāmīpyāt gurulāghavam paścimodadhigāḥ śīghravahā yāścāmalodakāḥ" },
      { type: "verse", number: "16", sanskrit: "पथ्याः समासात्ता नद्यो विपरीतास्ततो ऽन्यथा उपलास्फालनाक्षेपविच्छेदैः खेदितोदकाः", text: "pathyāḥ samāsāttā nadyo viparītāstato 'nyathā upalāsphālanākṣepavicchedaiḥ kheditodakāḥ" },
      { type: "verse", number: "17", sanskrit: "हिमवन्मलयोद्भूताः पथ्यास्ता एव च स्थिताः क्रिमिश्लीपदहृत्कण्ठशिरोरोगान् प्रकुर्वते", text: "himavanmalayodbhūtāḥ pathyāstā eva ca sthitāḥ krimiślīpadahṛtkaṇṭhaśirorogān prakurvate" },
      { type: "verse", number: "18", sanskrit: "प्राच्यावन्त्यपरान्तोत्था दुर्नामानि महेन्द्रजाः उदरश्लीपदातङ्कान् सह्यविन्ध्यभवाः पुनः", text: "prācyāvantyaparāntotthā durnāmāni mahendrajāḥ udaraślīpadātaṅkān sahyavindhyabhavāḥ punaḥ" },
      { type: "verse", number: "19", sanskrit: "कुष्ठपाण्डुशिरोरोगान् दोषघ्न्यः पारियात्रजाः बलपौरुषकारिण्यः सागराम्भस्त्रिदोषकृत्", text: "kuṣṭhapāṇḍuśirorogān doṣaghnyaḥ pāriyātrajāḥ balapauruṣakāriṇyaḥ sāgarāmbhastridoṣakṛt" },
      { type: "verse", number: "20", sanskrit: "कीटाहिमूत्रविट्कोथतृणजालोत्कराविलम् पङ्कपङ्कजशैवालहठपर्णादिसंस्तृतम्", text: "kīṭāhimūtraviṭkothatṛṇajālotkarāvilam paṅkapaṅkajaśaivālahaṭhaparṇādisaṃstṛtam" },
      { type: "verse", number: "21", sanskrit: "सूर्येन्दुपवनादृष्टं जुष्टं च क्षुद्रजन्तुभिः अभिवृष्टं विवर्णं च कलुषं स्थूलफेनिलम्", text: "sūryendupavanādṛṣṭaṃ juṣṭaṃ ca kṣudrajantubhiḥ abhivṛṣṭaṃ vivarṇaṃ ca kaluṣaṃ sthūlaphenilam" },
      { type: "verse", number: "22", sanskrit: "विरसं गन्धवत्तप्तं दन्तग्राह्यतिशैत्यतः अनार्तवं च यद्दिव्यमार्तवं प्रथमं च यत्", text: "virasaṃ gandhavattaptaṃ dantagrāhyatiśaityataḥ anārtavaṃ ca yaddivyamārtavaṃ prathamaṃ ca yat" },
      { type: "verse", number: "23", sanskrit: "लूतादितन्तुविण्मूत्रविषसंश्लेषदूषितम् तत् कुर्यात् स्नानपानाभ्यां तृष्णाध्मानोदरज्वरान्", text: "lūtāditantuviṇmūtraviṣasaṃśleṣadūṣitam tat kuryāt snānapānābhyāṃ tṛṣṇādhmānodarajvarān" },
      { type: "verse", number: "24", sanskrit: "कासाग्निसादाभिष्यन्दकण्डूगण्डादिकानतः तद्वर्जयेदभवे वा तोयस्यान्यस्य शस्यते", text: "kāsāgnisādābhiṣyandakaṇḍūgaṇḍādikānataḥ tadvarjayedabhave vā toyasyānyasya śasyate" },
      { type: "verse", number: "25", sanskrit: "घनवस्त्रपरिस्रावैः क्षुद्रजन्त्वभिरक्षणम् व्यापन्नस्यास्य तपनमग्न्यर्कायसपिण्डकैः", text: "ghanavastraparisrāvaiḥ kṣudrajantvabhirakṣaṇam vyāpannasyāsya tapanamagnyarkāyasapiṇḍakaiḥ" },
      { type: "verse", number: "26", sanskrit: "पर्णीमूलबिसग्रन्थिमुक्ताकतकशैवलैः वस्त्रगोमेदकाभ्यां वा कारयेत्तत्प्रसादनम्", text: "parṇīmūlabisagranthimuktākatakaśaivalaiḥ vastragomedakābhyāṃ vā kārayettatprasādanam" },
      { type: "verse", number: "27", sanskrit: "पाटलाकरवीरादिकुसुमैर्गन्धनाशनम् पानीयं न तु पानीयं पानीये ऽन्यप्रदेशजे", text: "pāṭalākaravīrādikusumairgandhanāśanam pānīyaṃ na tu pānīyaṃ pānīye 'nyapradeśaje" },
      { type: "verse", number: "28", sanskrit: "अजीर्णे क्वथितं चा आमे पक्वे जीर्णे ऽपि नेतरत् शीते विधिरयं तप्ते त्वजीर्णे शिशिरं त्यजेत्", text: "ajīrṇe kvathitaṃ cā āme pakve jīrṇe 'pi netarat śīte vidhirayaṃ tapte tvajīrṇe śiśiraṃ tyajet" },
      { type: "verse", number: "29", sanskrit: "पानीयं प्राणिनां प्राणा विश्वमेव च तन्मयम् अतो ऽत्यन्तनिषेधेन न क्वचिद्वारि वार्यते", text: "pānīyaṃ prāṇināṃ prāṇā viśvameva ca tanmayam ato 'tyantaniṣedhena na kvacidvāri vāryate" },
      { type: "verse", number: "30", sanskrit: "आस्यशोषाङ्गसादाद्या मृत्युर्वा तदलाभतः न हि तोयाद्विना वृत्तिः स्वस्थस्य व्याधितस्य वा", text: "āsyaśoṣāṅgasādādyā mṛtyurvā tadalābhataḥ na hi toyādvinā vṛttiḥ svasthasya vyādhitasya vā" },
      { type: "verse", number: "31", sanskrit: "केवलं सौषधं पक्वमाममुष्णं हितं च तत् समीक्ष्य मात्रया युक्तममृतं विषमन्यया", text: "kevalaṃ sauṣadhaṃ pakvamāmamuṣṇaṃ hitaṃ ca tat samīkṣya mātrayā yuktamamṛtaṃ viṣamanyayā" },
      { type: "verse", number: "32", sanskrit: "अतियोगेन सलिलं तृष्यतो ऽपि प्रयोजितम् प्रयाति श्लेष्मपित्तत्वं ज्वरितस्य विशेषतः", text: "atiyogena salilaṃ tṛṣyato 'pi prayojitam prayāti śleṣmapittatvaṃ jvaritasya viśeṣataḥ" },
      { type: "verse", number: "33", sanskrit: "वर्धयत्यामतृण्निद्रातन्द्राध्मानाङ्गगौरवम् कासाग्निसादहृल्लासप्रसेकश्वासपीनसान्", text: "vardhayatyāmatṛṇnidrātandrādhmānāṅgagauravam kāsāgnisādahṛllāsaprasekaśvāsapīnasān" },
      { type: "verse", number: "34", sanskrit: "पाके स्वादु हिमं वीर्ये तदुष्णमपि योजितम् तस्मादयोगपानेन लाघवान्न वियोजयेत्", text: "pāke svādu himaṃ vīrye taduṣṇamapi yojitam tasmādayogapānena lāghavānna viyojayet" },
      { type: "verse", number: "35", sanskrit: "आमविष्टब्धयोः कोष्णं निष्पिपासो ऽप्यपः पिबेत् यावत्यः क्लेदयन्त्यन्नमतिक्लेदो ऽग्निनाशनः", text: "āmaviṣṭabdhayoḥ koṣṇaṃ niṣpipāso 'pyapaḥ pibet yāvatyaḥ kledayantyannamatikledo 'gnināśanaḥ" },
      { type: "verse", number: "36", sanskrit: "विबद्धः कफवाताभ्यां मुक्तामाशयबन्धनः पच्यते क्षिप्रमाहारः कोष्णतोयद्रवीकृतः", text: "vibaddhaḥ kaphavātābhyāṃ muktāmāśayabandhanaḥ pacyate kṣipramāhāraḥ koṣṇatoyadravīkṛtaḥ" },
      { type: "verse", number: "37", sanskrit: "अनव्बस्थितदोषाग्नेर्व्याधिक्षीणबलस्य च नाल्पमप्याममुदकं हितं तद्धि त्रिदोषकृत्", text: "anavbasthitadoṣāgnervyādhikṣīṇabalasya ca nālpamapyāmamudakaṃ hitaṃ taddhi tridoṣakṛt" },
      { type: "verse", number: "38", sanskrit: "तेजसः प्रतिपक्षत्वान्मन्दाग्निर्वर्जयेज्जलम् सर्वमेव तथा स्यन्दप्लीहविद्रधिगुल्मिनः", text: "tejasaḥ pratipakṣatvānmandāgnirvarjayejjalam sarvameva tathā syandaplīhavidradhigulminaḥ" },
      { type: "verse", number: "39", sanskrit: "पाण्डूदरातिसारार्शोग्रहणीशोषशोफिनः काममल्पमशक्तौ तु पेयमौषधसंस्कृतम्", text: "pāṇḍūdarātisārārśograhaṇīśoṣaśophinaḥ kāmamalpamaśaktau tu peyamauṣadhasaṃskṛtam" },
      { type: "verse", number: "40", sanskrit: "ऋते शरन्निदाघाभ्यां पिबेत्स्वस्थो ऽपि चाल्पशः भक्तस्यादौ जलं पीतमग्निसादं कृशाङ्गताम्", text: "ṛte śarannidāghābhyāṃ pibetsvastho 'pi cālpaśaḥ bhaktasyādau jalaṃ pītamagnisādaṃ kṛśāṅgatām" },
      { type: "verse", number: "41", sanskrit: "अन्ते करोति स्थूलत्वमूर्ध्वं चामाशयात् कफम् मध्ये मध्याङ्गतां साम्यं धातूनां जरणं सुखम्", text: "ante karoti sthūlatvamūrdhvaṃ cāmāśayāt kapham madhye madhyāṅgatāṃ sāmyaṃ dhātūnāṃ jaraṇaṃ sukham" },
      { type: "verse", number: "42", sanskrit: "शीतं मदात्ययग्लानिमूर्छाछर्दिश्रमभ्रमान् तृष्णोष्णदाहपित्तासृग्विषाणि च निहन्ति तत्", text: "śītaṃ madātyayaglānimūrchāchardiśramabhramān tṛṣṇoṣṇadāhapittāsṛgviṣāṇi ca nihanti tat" },
      { type: "verse", number: "43", sanskrit: "क्षीणपादत्रिभागार्धं देशर्तुगुरुलाघवात् क्वथितं फेनरहितमवेगममलं हितम्", text: "kṣīṇapādatribhāgārdhaṃ deśartugurulāghavāt kvathitaṃ phenarahitamavegamamalaṃ hitam" },
      { type: "verse", number: "44", sanskrit: "हिध्माध्मानानिलश्लेष्मतृट्कासश्वासपीनसे पार्श्वशूलाममेदस्सु सद्यःशुद्धौ नवज्वरे", text: "hidhmādhmānānilaśleṣmatṛṭkāsaśvāsapīnase pārśvaśūlāmamedassu sadyaḥśuddhau navajvare" },
      { type: "verse", number: "45", sanskrit: "दीपनं पाचनं कण्ठ्यं लघु बस्तिविशोधनम् पाषाणरूप्यमृद्धेमजतुतापार्कतापितम्", text: "dīpanaṃ pācanaṃ kaṇṭhyaṃ laghu bastiviśodhanam pāṣāṇarūpyamṛddhemajatutāpārkatāpitam" },
      { type: "verse", number: "46", sanskrit: "पानीयमुष्णं शीतं वा त्रिदोषघ्नं तृडरितिजित् लघ्वरूक्षं क्लमघ्नञ्च तोयंक्वथितशीतलम्", text: "pānīyamuṣṇaṃ śītaṃ vā tridoṣaghnaṃ tṛḍaritijit laghvarūkṣaṃ klamaghnañca toyaṃkvathitaśītalam" },
      { type: "verse", number: "47", sanskrit: "संसर्गे पित्तकफयोः सन्निपाते च शस्यते तोयं वन्हिगुणभ्रष्टं पाके ऽम्लं सर्वदोषकृत्", text: "saṃsarge pittakaphayoḥ sannipāte ca śasyate toyaṃ vanhiguṇabhraṣṭaṃ pāke 'mlaṃ sarvadoṣakṛt" },
      { type: "verse", number: "48", sanskrit: "भवेत् पर्युषितं तच्च तोयं हिमकरोद्भवम् अतिशैत्यगुरुस्थैर्यङ्घातैः कफवातकृत्", text: "bhavet paryuṣitaṃ tacca toyaṃ himakarodbhavam atiśaityagurusthairyaṅghātaiḥ kaphavātakṛt" },
      { type: "verse", number: "49", sanskrit: "चन्द्रकान्तभवं रक्षोविषपित्तज्वरापहम् दृष्टिमेधावपुस्थैर्यकरं स्वादु हिमं लघु", text: "candrakāntabhavaṃ rakṣoviṣapittajvarāpaham dṛṣṭimedhāvapusthairyakaraṃ svādu himaṃ laghu" },
      { type: "verse", number: "50", sanskrit: "नालिकेरोदकं स्निग्धं स्वादु वृष्यं हिमं लघु तृष्णापित्तानिलहरं दीपनं बस्तिशोधनम् दिव्यं वारि वरं वर्षे नादेयमवरं इति तोयवर्गः", text: "nālikerodakaṃ snigdhaṃ svādu vṛṣyaṃ himaṃ laghu tṛṣṇāpittānilaharaṃ dīpanaṃ bastiśodhanam divyaṃ vāri varaṃ varṣe nādeyamavaraṃ iti toyavargaḥ" },
      { type: "verse", number: "51", sanskrit: "स्वादुपाकरसं स्निग्धमोजस्यं धातुवर्धनम् वातपित्तहरं वृष्यं श्लेष्मलं गुरु शीतलं", text: "svādupākarasaṃ snigdhamojasyaṃ dhātuvardhanam vātapittaharaṃ vṛṣyaṃ śleṣmalaṃ guru śītalaṃ" },
      { type: "verse", number: "52", sanskrit: "प्रायः पयः अत्र गव्यं तु जीवनीयं रसायनम् क्षतक्षीणहितं मेध्यं बल्यं स्तन्यकरं सरम्", text: "prāyaḥ payaḥ atra gavyaṃ tu jīvanīyaṃ rasāyanam kṣatakṣīṇahitaṃ medhyaṃ balyaṃ stanyakaraṃ saram" },
      { type: "verse", number: "53", sanskrit: "श्रमभ्रममदालक्ष्मीश्वासकासातितृट्क्षुधः जीर्णज्वरं मूत्रकृच्छ्रं रक्तपित्तं च नाशयेत्", text: "śramabhramamadālakṣmīśvāsakāsātitṛṭkṣudhaḥ jīrṇajvaraṃ mūtrakṛcchraṃ raktapittaṃ ca nāśayet" },
      { type: "verse", number: "54", sanskrit: "हितमत्यग्न्यनिद्रेभ्यो गरीयो माहिषं हिमम् अल्पाम्बुपानव्यायामकटुतिक्ताशनैर्लघु", text: "hitamatyagnyanidrebhyo garīyo māhiṣaṃ himam alpāmbupānavyāyāmakaṭutiktāśanairlaghu" },
      { type: "verse", number: "55", sanskrit: "आजं शोषज्वरश्वासरक्तपित्तातिसारजित् ईषद्रूक्षोष्णलवणमौष्ट्रकं दीपनं लघु", text: "ājaṃ śoṣajvaraśvāsaraktapittātisārajit īṣadrūkṣoṣṇalavaṇamauṣṭrakaṃ dīpanaṃ laghu" },
      { type: "verse", number: "56", sanskrit: "शस्तं वातकफानाहक्रिमिशोफोदरार्शसाम् मानुषं वातपित्तासृग्भिघाताक्षिरोगजित्", text: "śastaṃ vātakaphānāhakrimiśophodarārśasām mānuṣaṃ vātapittāsṛgbhighātākṣirogajit" },
      { type: "verse", number: "57", sanskrit: "तर्पणाश्च्योतनैर्नस्यैः अहृद्यं तूष्णमाविकम् वातव्याधिहरं हिध्माश्वासपित्तकफप्रदम्", text: "tarpaṇāścyotanairnasyaiḥ ahṛdyaṃ tūṣṇamāvikam vātavyādhiharaṃ hidhmāśvāsapittakaphapradam" },
      { type: "verse", number: "58", sanskrit: "हस्तिन्याः स्थैर्यकृत् बाढं उष्णं त्वैकशफं लघु शाखावातहरं साम्ललवणं जडताकरम्", text: "hastinyāḥ sthairyakṛt bāḍhaṃ uṣṇaṃ tvaikaśaphaṃ laghu śākhāvātaharaṃ sāmlalavaṇaṃ jaḍatākaram" },
      { type: "verse", number: "59", sanskrit: "पयो ऽभिष्यन्दि गुर्वामं युक्त्या शृतमतो ऽन्यथा भवेत् गरीयो ऽतिशृतं धारोष्णममृतोपमम्", text: "payo 'bhiṣyandi gurvāmaṃ yuktyā śṛtamato 'nyathā bhavet garīyo 'tiśṛtaṃ dhāroṣṇamamṛtopamam" },
      { type: "verse", number: "60", sanskrit: "पिण्याकाम्लाशिनीनां तु गुर्वभिष्यन्दि तत् भृशम् अचेष्टया च प्रादोषात् गरीयः स्मृतमौषसम्", text: "piṇyākāmlāśinīnāṃ tu gurvabhiṣyandi tat bhṛśam aceṣṭayā ca prādoṣāt garīyaḥ smṛtamauṣasam" },
      { type: "verse", number: "61", sanskrit: "व्याख्यातस्तेन लघिमा चेष्टावत्प्रकृतिष्वपि ह्रस्वेषु चातिदेहेभ्यो मांसेष्वप्येवमादिशेत्", text: "vyākhyātastena laghimā ceṣṭāvatprakṛtiṣvapi hrasveṣu cātidehebhyo māṃseṣvapyevamādiśet" },
      { type: "verse", number: "62", sanskrit: "अम्लपाकरसं ग्राहि गुरूष्णं दधि वातजित् मेदःशुक्रबलश्लेष्मपित्तरक्ताग्निशोफकृत्", text: "amlapākarasaṃ grāhi gurūṣṇaṃ dadhi vātajit medaḥśukrabalaśleṣmapittaraktāgniśophakṛt" },
      { type: "verse", number: "63", sanskrit: "रोचिष्णु शस्तमरुचौ शीतके विषमज्वरे पीनसे मूत्रकुछ्रे च रूक्षं तु ग्रहणीगदे", text: "rociṣṇu śastamarucau śītake viṣamajvare pīnase mūtrakuchre ca rūkṣaṃ tu grahaṇīgade" },
      { type: "verse", number: "64", sanskrit: "नैवाद्यान्निशि नैवोष्णं वसन्तोष्णशरत्सु न नामुद्गसूपं नाक्षौद्रं नाघृतं नासितोपलम् न चानामलकं नापि नित्यं नो मन्दमन्यथा ज्वरासृक्पित्तवीसर्पकुष्ठपाण्ड्वामयप्रदम् तक्रं लघु कषायाम्लं दीपनं कफवातजित् शोफोदरार्शोग्रहणीदोषमूत्रग्रहारुचीः", text: "naivādyānniśi naivoṣṇaṃ vasantoṣṇaśaratsu na nāmudgasūpaṃ nākṣaudraṃ nāghṛtaṃ nāsitopalam na cānāmalakaṃ nāpi nityaṃ no mandamanyathā jvarāsṛkpittavīsarpakuṣṭhapāṇḍvāmayapradam takraṃ laghu kaṣāyāmlaṃ dīpanaṃ kaphavātajit śophodarārśograhaṇīdoṣamūtragrahārucīḥ" },
      { type: "verse", number: "66", sanskrit: "गुल्मप्लीहघृतव्यापद्गरपाण्ड्वामयान् जयेत् तद्वन्मस्तु सरं स्रोतश्शोधि विष्टम्भजिल्लघु", text: "gulmaplīhaghṛtavyāpadgarapāṇḍvāmayān jayet tadvanmastu saraṃ srotaśśodhi viṣṭambhajillaghu" },
      { type: "verse", number: "67", sanskrit: "शीतं स्वादु कषायाम्लं नवनीतं नवोद्धृतं यक्ष्मार्शोर्द्दितपित्तासृग्वातजिद् ग्राहि दीपनम्", text: "śītaṃ svādu kaṣāyāmlaṃ navanītaṃ navoddhṛtaṃ yakṣmārśordditapittāsṛgvātajid grāhi dīpanam" },
      { type: "verse", number: "68", sanskrit: "क्षीरोद्भवं तु सङ्ग्राहि रक्तपित्ताक्षिरोगजित् शस्तं धीस्मृतिमेधाग्निबलायुःशुक्रचक्षुषाम्", text: "kṣīrodbhavaṃ tu saṅgrāhi raktapittākṣirogajit śastaṃ dhīsmṛtimedhāgnibalāyuḥśukracakṣuṣām" },
      { type: "verse", number: "69", sanskrit: "बालवृद्धप्रजाकान्तिसौकुमार्यस्वरार्थिनाम् क्षतक्षीणपरीसर्पशस्त्राग्निग्लपितात्मनाम्", text: "bālavṛddhaprajākāntisaukumāryasvarārthinām kṣatakṣīṇaparīsarpaśastrāgniglapitātmanām" },
      { type: "verse", number: "70", sanskrit: "वातपित्तविषोन्मादशोषालक्ष्मीज्वरापहम् स्नेहानामुत्तमं शीतं वयसः स्थापनं घृतम्", text: "vātapittaviṣonmādaśoṣālakṣmījvarāpaham snehānāmuttamaṃ śītaṃ vayasaḥ sthāpanaṃ ghṛtam" },
      { type: "verse", number: "71", sanskrit: "सहस्रवीर्यं विधिभिः शृतं कर्मसहस्रकृत् मदापस्मारमूर्छायशिरःकर्णाक्षियोनिजान्", text: "sahasravīryaṃ vidhibhiḥ śṛtaṃ karmasahasrakṛt madāpasmāramūrchāyaśiraḥkarṇākṣiyonijān" },
      { type: "verse", number: "72", sanskrit: "पुराणं जयति व्याधीन् व्रणशोधनरोपणम् पूर्वोक्तांश्चाधिकान् कुर्यात् गुणांस्तदमृतोपमम्", text: "purāṇaṃ jayati vyādhīn vraṇaśodhanaropaṇam pūrvoktāṃścādhikān kuryāt guṇāṃstadamṛtopamam" },
      { type: "verse", number: "73", sanskrit: "तद्वच्च घृतमण्डो ऽपि रुक्षस्तीक्ष्णस्तनुश्च सः कीलाटदधिकूचीकातक्रपिण्डकमोरटाः", text: "tadvacca ghṛtamaṇḍo 'pi rukṣastīkṣṇastanuśca saḥ kīlāṭadadhikūcīkātakrapiṇḍakamoraṭāḥ" },
      { type: "verse", number: "74", sanskrit: "सक्षीरशाकपीयूषा रोचना वह्निसादनाः शुक्रनिद्राकफकरा विष्टम्भिगुरुदोषलाः", text: "sakṣīraśākapīyūṣā rocanā vahnisādanāḥ śukranidrākaphakarā viṣṭambhigurudoṣalāḥ" },
      { type: "verse", number: "75", sanskrit: "विद्याद्दधिघृतादीनां गुणदोषान् यथा पयः गव्ये क्षीरघृते श्रेष्ठे निन्दिते चाविसम्भवे इति क्षीरवर्गः", text: "vidyāddadhighṛtādīnāṃ guṇadoṣān yathā payaḥ gavye kṣīraghṛte śreṣṭhe nindite cāvisambhave iti kṣīravargaḥ" },
      { type: "verse", number: "76", sanskrit: "इक्षोः सरो गुरुः स्निग्धो वृंहणः कफमूत्रकृत्", text: "ikṣoḥ saro guruḥ snigdho vṛṃhaṇaḥ kaphamūtrakṛt" },
      { type: "verse", number: "77", sanskrit: "वृष्यः शीतः पवनजित् भुक्ते वातप्रकोपनः रक्तपित्तप्रशमनः स्वादुपाकरसो रसः", text: "vṛṣyaḥ śītaḥ pavanajit bhukte vātaprakopanaḥ raktapittapraśamanaḥ svādupākaraso rasaḥ" },
      { type: "verse", number: "78", sanskrit: "सो ऽग्रे सलवणो दन्तपीडितः शर्करासमः मूलाग्रजन्तुजग्धादिपीडनान्मलसङ्करात्", text: "so 'gre salavaṇo dantapīḍitaḥ śarkarāsamaḥ mūlāgrajantujagdhādipīḍanānmalasaṅkarāt" },
      { type: "verse", number: "79", sanskrit: "किञ्चित् कालविधृत्या च विकृतिं याति यान्त्रिकः विदाही गुरु विष्टम्भी तेनासौतत्र पौण्ड्रकः शैत्यप्रसादमाधुर्याद्वरस्तमनुवांशिकः", text: "kiñcit kālavidhṛtyā ca vikṛtiṃ yāti yāntrikaḥ vidāhī guru viṣṭambhī tenāsautatra pauṇḍrakaḥ śaityaprasādamādhuryādvarastamanuvāṃśikaḥ" },
      { type: "verse", number: "80", sanskrit: "शातपर्वककान्तारनैपालाद्यास्ततः क्रमात् सक्षाराः सकषायाश्च सोष्णाः किञ्चिद्विदाहिनः", text: "śātaparvakakāntāranaipālādyāstataḥ kramāt sakṣārāḥ sakaṣāyāśca soṣṇāḥ kiñcidvidāhinaḥ" },
      { type: "verse", number: "81", sanskrit: "फाणितं गुर्वभिष्यन्दि चयकृन्मूत्रशोधनम् नातिश्लेष्मकरो धौतः सृष्टमूत्रशकृत् गुडः", text: "phāṇitaṃ gurvabhiṣyandi cayakṛnmūtraśodhanam nātiśleṣmakaro dhautaḥ sṛṣṭamūtraśakṛt guḍaḥ" },
      { type: "verse", number: "82", sanskrit: "प्रभूतक्रिमिमज्जासृङ्भेदोमांसकफो ऽपरः हृद्यः पुराणः पथ्यश्च नवः श्लेष्माग्निसादकृत्", text: "prabhūtakrimimajjāsṛṅbhedomāṃsakapho 'paraḥ hṛdyaḥ purāṇaḥ pathyaśca navaḥ śleṣmāgnisādakṛt" },
      { type: "verse", number: "83", sanskrit: "वृष्याः क्षीणक्षतहिता रक्तपित्तानिलापहाः मत्स्यण्डिकाखण्डसिताः क्रमेण गुणवत्तमाः", text: "vṛṣyāḥ kṣīṇakṣatahitā raktapittānilāpahāḥ matsyaṇḍikākhaṇḍasitāḥ krameṇa guṇavattamāḥ" },
      { type: "verse", number: "84", sanskrit: "तद्गुणा तिक्तमधुरा कषाया याषशर्करा त्रिदोषघ्नी सिता काशेषुदर्भच्छदसम्भवा", text: "tadguṇā tiktamadhurā kaṣāyā yāṣaśarkarā tridoṣaghnī sitā kāśeṣudarbhacchadasambhavā" },
      { type: "verse", number: "85", sanskrit: "दाहतृट्च्छर्दिमूर्च्छासृक्तिपत्तघ्नः सर्वशर्कराः शर्करेक्षुविकाराणां फाणितं च वरावरे", text: "dāhatṛṭcchardimūrcchāsṛktipattaghnaḥ sarvaśarkarāḥ śarkarekṣuvikārāṇāṃ phāṇitaṃ ca varāvare" },
      { type: "verse", number: "86", sanskrit: "चक्षुष्यं च्छेदि तृट्श्लेष्मविषहिध्मास्रपित्तनुत् कुष्ठमेहकृमिच्छर्दिश्वासकासातिसारजित्", text: "cakṣuṣyaṃ cchedi tṛṭśleṣmaviṣahidhmāsrapittanut kuṣṭhamehakṛmicchardiśvāsakāsātisārajit" },
      { type: "verse", number: "87", sanskrit: "व्रणशोधनसन्धानरोपणं वातलं मधु रूक्षं कषायमधुरम् तत्तुल्या मधुशर्करा", text: "vraṇaśodhanasandhānaropaṇaṃ vātalaṃ madhu rūkṣaṃ kaṣāyamadhuram tattulyā madhuśarkarā" },
      { type: "verse", number: "88", sanskrit: "उष्णमुष्णार्तमुष्णे च युक्तं चोष्णैर्निहन्ति तत् विषान्वयत्वेन विषपुष्पेभ्यो ऽपि यतो मधु", text: "uṣṇamuṣṇārtamuṣṇe ca yuktaṃ coṣṇairnihanti tat viṣānvayatvena viṣapuṣpebhyo 'pi yato madhu" },
      { type: "verse", number: "89", sanskrit: "कुर्वते ते स्वयं यच्च सविषा भ्रमरादयः प्रच्छर्दने निरूहे च मधूष्णं न निवार्यते", text: "kurvate te svayaṃ yacca saviṣā bhramarādayaḥ pracchardane nirūhe ca madhūṣṇaṃ na nivāryate" },
      { type: "verse", number: "90", sanskrit: "अलब्धपाकमाश्वेव तयोर्यस्मान्निवर्तते गुरुरूक्षकषायत्वाच्छैत्याच्चाल्पं हितं मधु", text: "alabdhapākamāśveva tayoryasmānnivartate gururūkṣakaṣāyatvācchaityāccālpaṃ hitaṃ madhu" },
      { type: "verse", number: "91", sanskrit: "न हि कष्टतमं किञ्चित्तदजीर्णाद्यतो नरम् उपक्रमविरोधित्वात् सद्यो हन्याद्यथा विषम्", text: "na hi kaṣṭatamaṃ kiñcittadajīrṇādyato naram upakramavirodhitvāt sadyo hanyādyathā viṣam" },
      { type: "verse", number: "92", sanskrit: "नानाद्रव्यात्मकत्वाच्च्च योगवाहि परं मधु वृष्ययोगैरतो युक्तं वृषतामनुवर्तते", text: "nānādravyātmakatvāccca yogavāhi paraṃ madhu vṛṣyayogairato yuktaṃ vṛṣatāmanuvartate" },
      { type: "verse", number: "93", sanskrit: "भ्रामरं पौष्पिकं क्षौद्रं माक्षिकं च यथोत्तरम् वरं जीर्णं च तेष्वन्त्ये द्वे एव ह्युपयोजयेत् इति इक्षु वर्गः", text: "bhrāmaraṃ pauṣpikaṃ kṣaudraṃ mākṣikaṃ ca yathottaram varaṃ jīrṇaṃ ca teṣvantye dve eva hyupayojayet iti ikṣu vargaḥ" },
      { type: "verse", number: "94", sanskrit: "तैलं स्वयोनिवत्तत्र मुख्यं तीक्ष्णं व्यवायि च त्वग्दोषकृदचक्षुष्यं सूक्ष्मोष्णं कफकृन्न च", text: "tailaṃ svayonivattatra mukhyaṃ tīkṣṇaṃ vyavāyi ca tvagdoṣakṛdacakṣuṣyaṃ sūkṣmoṣṇaṃ kaphakṛnna ca" },
      { type: "verse", number: "95", sanskrit: "कृशानां बृंहणायालं स्थूलानां कर्शनाय च बद्धविट्कं क्रिमिघ्नं च संस्कारात्सर्वरोगजित्", text: "kṛśānāṃ bṛṃhaṇāyālaṃ sthūlānāṃ karśanāya ca baddhaviṭkaṃ krimighnaṃ ca saṃskārātsarvarogajit" },
      { type: "verse", number: "96", sanskrit: "तैलप्रयोगादजरा निर्विकारा जितश्रमाः आसन्नतिबला युद्धे दैत्याधिपतयः पुरा", text: "tailaprayogādajarā nirvikārā jitaśramāḥ āsannatibalā yuddhe daityādhipatayaḥ purā" },
      { type: "verse", number: "97", sanskrit: "सतिक्तोषणमैरण्डं तैलं स्वादु सरं गुरु वर्ध्मगुल्मानिलकफानुदरं विषमज्वरम्", text: "satiktoṣaṇamairaṇḍaṃ tailaṃ svādu saraṃ guru vardhmagulmānilakaphānudaraṃ viṣamajvaram" },
      { type: "verse", number: "98", sanskrit: "रुक्छोफौ च कटीगुह्यकोष्ठपृष्ठाश्रयौ जयेत् तीक्ष्णोष्णं पिच्छिलं विस्रं रक्तैरण्डोद्भवं त्वति", text: "rukchophau ca kaṭīguhyakoṣṭhapṛṣṭhāśrayau jayet tīkṣṇoṣṇaṃ picchilaṃ visraṃ raktairaṇḍodbhavaṃ tvati" },
      { type: "verse", number: "99", sanskrit: "उमाकुसुम्भजं चोष्णं त्वग्दोषकफपित्तकृत् दन्तीमूलकरक्षोघ्नकरञ्जारिष्टशिग्रुजम्", text: "umākusumbhajaṃ coṣṇaṃ tvagdoṣakaphapittakṛt dantīmūlakarakṣoghnakarañjāriṣṭaśigrujam" },
      { type: "verse", number: "100", sanskrit: "सुवर्चलेड्गुदीपीलुशाङ्खिनीनीपसम्भवम् सरलागरुदेवाह्वशिंशपासारजन्म च", text: "suvarcaleḍgudīpīluśāṅkhinīnīpasambhavam saralāgarudevāhvaśiṃśapāsārajanma ca" },
      { type: "verse", number: "101", sanskrit: "तुवरारुष्करोत्थं च तीक्ष्णं कट्वस्रपित्तकृत् अर्शःकुष्ठक्रिमिश्लेष्मशुक्रमेदोनिलापहम्", text: "tuvarāruṣkarotthaṃ ca tīkṣṇaṃ kaṭvasrapittakṛt arśaḥkuṣṭhakrimiśleṣmaśukramedonilāpaham" },
      { type: "verse", number: "102", sanskrit: "करञ्जनिम्बजे तिक्ते नात्युष्णे तत्र निर्दिशेत् कषायतिक्तकटुकं सारलं व्रणणोधनम्", text: "karañjanimbaje tikte nātyuṣṇe tatra nirdiśet kaṣāyatiktakaṭukaṃ sāralaṃ vraṇaṇodhanam" },
      { type: "verse", number: "103", sanskrit: "भृशोष्णतीक्ष्णकटुके तुवरारुष्करोद्भवे विशेषात् क्रिमिकुष्ठघ्ने तथोर्ध्वाधोविरेचने", text: "bhṛśoṣṇatīkṣṇakaṭuke tuvarāruṣkarodbhave viśeṣāt krimikuṣṭhaghne tathordhvādhovirecane" },
      { type: "verse", number: "104", sanskrit: "अक्षातिमुक्तकाक्षोडनालिकेरमधूकजम् त्रपुसोर्वारुकूष्माण्डश्लेष्मातकप्रियालजम्", text: "akṣātimuktakākṣoḍanālikeramadhūkajam trapusorvārukūṣmāṇḍaśleṣmātakapriyālajam" },
      { type: "verse", number: "105", sanskrit: "वातपित्तहरं केश्यं श्लेष्मलं गुरु शीतलम् पित्तश्लेष्मप्रशमनं श्रीपर्णीकिंशुकोद्भवम्", text: "vātapittaharaṃ keśyaṃ śleṣmalaṃ guru śītalam pittaśleṣmapraśamanaṃ śrīparṇīkiṃśukodbhavam" },
      { type: "verse", number: "106", sanskrit: "तिलतैलं वरं तेषु कौसुम्भमवरं परम् वसा मज्जा च वातघ्नौ बलपित्तकफप्रदौ", text: "tilatailaṃ varaṃ teṣu kausumbhamavaraṃ param vasā majjā ca vātaghnau balapittakaphapradau" },
      { type: "verse", number: "107", sanskrit: "मांसानुगस्वरूपौ च विद्यान्मेदोपि ताविव बौलूकी सौकरी पाकहंसजा कुक्कुटोद्भवा", text: "māṃsānugasvarūpau ca vidyānmedopi tāviva baulūkī saukarī pākahaṃsajā kukkuṭodbhavā" },
      { type: "verse", number: "108", sanskrit: "वसा श्रेष्ठा स्ववर्गेषु कुम्भीरमहिषोद्भवा काकमद्गु वसा तद्वत् कारण्डोत्था च निन्दिता", text: "vasā śreṣṭhā svavargeṣu kumbhīramahiṣodbhavā kākamadgu vasā tadvat kāraṇḍotthā ca ninditā" },
      { type: "verse", number: "109", sanskrit: "दीपनं रोचनं मद्यं तीक्ष्णोक्ष्णं तुष्टिपुष्टिदम् सत्वादुतिक्तकटुकमम्लपाकरसं सरम्", text: "dīpanaṃ rocanaṃ madyaṃ tīkṣṇokṣṇaṃ tuṣṭipuṣṭidam satvādutiktakaṭukamamlapākarasaṃ saram" },
      { type: "verse", number: "110", sanskrit: "सकषायं स्वरारोग्यप्रतिभावर्णकृल्लघु नष्टनिद्रातिनिद्रेभ्यो हितं पित्तास्रदूषणम्", text: "sakaṣāyaṃ svarārogyapratibhāvarṇakṛllaghu naṣṭanidrātinidrebhyo hitaṃ pittāsradūṣaṇam" },
      { type: "verse", number: "111", sanskrit: "कृशस्थूलहितं रूक्षं सूक्ष्मं स्रोतोविशोधनम् वातश्लेष्महरं युक्त्या पीतं विषवदन्यथा", text: "kṛśasthūlahitaṃ rūkṣaṃ sūkṣmaṃ srotoviśodhanam vātaśleṣmaharaṃ yuktyā pītaṃ viṣavadanyathā" },
      { type: "verse", number: "112", sanskrit: "गुरु तद्दोषजननं नवं जीर्णमतो ऽन्यथा पेयं नोष्णोपचरेण न विरिक्तक्षुधातुरैः", text: "guru taddoṣajananaṃ navaṃ jīrṇamato 'nyathā peyaṃ noṣṇopacareṇa na viriktakṣudhāturaiḥ" },
      { type: "verse", number: "113", sanskrit: "नातितीक्ष्णमृदुस्वच्छघनं व्यापन्नमेव वा गुल्मोदरार्शोग्रहणीशोषहृत् स्नेहनी गुरुः", text: "nātitīkṣṇamṛdusvacchaghanaṃ vyāpannameva vā gulmodarārśograhaṇīśoṣahṛt snehanī guruḥ" },
      { type: "verse", number: "114", sanskrit: "सुरनिलघ्नी मेदोसृक्स्तन्यमूत्रकफावहा तद्गुणा वारुणी हृद्या लघुस्तीक्ष्णा निहन्ति च", text: "suranilaghnī medosṛkstanyamūtrakaphāvahā tadguṇā vāruṇī hṛdyā laghustīkṣṇā nihanti ca" },
      { type: "verse", number: "115", sanskrit: "शूलकासवमिश्वासविबन्धाध्मानपीनसान् शूलप्रवाहिकाटोपतृष्णाशोफार्शसां हितः", text: "śūlakāsavamiśvāsavibandhādhmānapīnasān śūlapravāhikāṭopatṛṣṇāśophārśasāṃ hitaḥ" },
      { type: "verse", number: "116", sanskrit: "जगलः पाचनो ग्राही रूक्षस्तद्वच्च मेदकः बक्कसो हृतसारत्वाद्विष्टम्भी दोषकोपनः", text: "jagalaḥ pācano grāhī rūkṣastadvacca medakaḥ bakkaso hṛtasāratvādviṣṭambhī doṣakopanaḥ" },
      { type: "verse", number: "117", sanskrit: "नातितीव्रमदा लघ्वी पथ्या बैभीतकी सुरा व्रणे पाण्ड्वामये कुष्ठे न चात्यर्थं विरुध्यते", text: "nātitīvramadā laghvī pathyā baibhītakī surā vraṇe pāṇḍvāmaye kuṣṭhe na cātyarthaṃ virudhyate" },
      { type: "verse", number: "118", sanskrit: "विष्टम्भिनी यवसुरा गुर्वी रूक्षा त्रिदोषला कौहली बृंहणी गुर्वी श्लेष्मलस्तु मधूलकः", text: "viṣṭambhinī yavasurā gurvī rūkṣā tridoṣalā kauhalī bṛṃhaṇī gurvī śleṣmalastu madhūlakaḥ" },
      { type: "verse", number: "119", sanskrit: "यथाद्रव्यगुणो ऽरिष्टः सर्वमद्यगुणाधिकः ग्रहणीपाण्डुकुष्ठार्शः शोषशोफोदरज्वरान्", text: "yathādravyaguṇo 'riṣṭaḥ sarvamadyaguṇādhikaḥ grahaṇīpāṇḍukuṣṭhārśaḥ śoṣaśophodarajvarān" },
      { type: "verse", number: "120", sanskrit: "हन्ति गुल्माक्रिमिफीहः कषायकटुवातलः मार्द्विकं लेखनं हृद्यं नात्युष्णं मधुरं सरम्", text: "hanti gulmākrimiphīhaḥ kaṣāyakaṭuvātalaḥ mārdvikaṃ lekhanaṃ hṛdyaṃ nātyuṣṇaṃ madhuraṃ saram" },
      { type: "verse", number: "121", sanskrit: "अल्पपित्तानिलं पाण्डुमेहार्शःक्रिमिनाशनम् अस्मादल्पान्तरगुणं खार्जूरं वातलं गुरु", text: "alpapittānilaṃ pāṇḍumehārśaḥkrimināśanam asmādalpāntaraguṇaṃ khārjūraṃ vātalaṃ guru" },
      { type: "verse", number: "122", sanskrit: "शार्करः सुरभिः त्वादुर्हृद्यो नातिमदो मघुः सृष्टमूत्रशकृद्वातो गौडस्तर्पणदीपनः", text: "śārkaraḥ surabhiḥ tvādurhṛdyo nātimado maghuḥ sṛṣṭamūtraśakṛdvāto gauḍastarpaṇadīpanaḥ" },
      { type: "verse", number: "123", sanskrit: "वातपित्तकरः शीधुः स्नेहश्लेष्मविकारहा मेदःशोफोदरार्शोघ्नस्तत्र पक्वरसो वरः", text: "vātapittakaraḥ śīdhuḥ snehaśleṣmavikārahā medaḥśophodarārśoghnastatra pakvaraso varaḥ" },
      { type: "verse", number: "124", sanskrit: "च्छेदि मध्वासवस्तीक्ष्णो मेहपीनसकासजित् सुरासवस्तीक्ष्णमदः स्वादुस्तीक्ष्णो ऽनिलापहः", text: "cchedi madhvāsavastīkṣṇo mehapīnasakāsajit surāsavastīkṣṇamadaḥ svādustīkṣṇo 'nilāpahaḥ" },
      { type: "verse", number: "125", sanskrit: "मैरेयो मधुरो हृष्यः सरः सन्तर्पणो गुरुः धातक्यभिषुतो जीर्णो रूक्षो रोचनदीपनः", text: "maireyo madhuro hṛṣyaḥ saraḥ santarpaṇo guruḥ dhātakyabhiṣuto jīrṇo rūkṣo rocanadīpanaḥ" },
      { type: "verse", number: "126", sanskrit: "द्राक्षासवो मधुसमः परमं स तु दीपनः मार्द्वीकसदृशः प्रोक्तो मृद्वीकेक्षुरसासवः", text: "drākṣāsavo madhusamaḥ paramaṃ sa tu dīpanaḥ mārdvīkasadṛśaḥ prokto mṛdvīkekṣurasāsavaḥ" },
      { type: "verse", number: "127", sanskrit: "समासादासवो हृद्यो वातलः सौषधानुगः द्राक्षेक्षुमाक्षिकं शालिरुत्तमा व्रीहिपञ्चमाः", text: "samāsādāsavo hṛdyo vātalaḥ sauṣadhānugaḥ drākṣekṣumākṣikaṃ śāliruttamā vrīhipañcamāḥ" },
      { type: "verse", number: "128", sanskrit: "मद्याकरा यत्तेभ्यो ऽन्यत्तन्मद्यप्रतिरूपकम् गुणैर्यथोद्बणैर्विद्यान्मद्यमाकरसङ्करात्", text: "madyākarā yattebhyo 'nyattanmadyapratirūpakam guṇairyathodbaṇairvidyānmadyamākarasaṅkarāt" },
      { type: "verse", number: "129", sanskrit: "रक्तपित्तकफोत्क्लेदि शुक्तं वातानुलोमनम् विदाहि भृशतीक्ष्णोक्ष्णं हृद्यं रुचिकरं सरम्", text: "raktapittakaphotkledi śuktaṃ vātānulomanam vidāhi bhṛśatīkṣṇokṣṇaṃ hṛdyaṃ rucikaraṃ saram" },
      { type: "verse", number: "130", sanskrit: "दीपनं शिशिरस्पर्शं पाण्डुदृक्कृमिनाशनम् गुडेक्षुमद्यमार्द्वीकशुक्तं लघु यथोत्तरम्", text: "dīpanaṃ śiśirasparśaṃ pāṇḍudṛkkṛmināśanam guḍekṣumadyamārdvīkaśuktaṃ laghu yathottaram" },
      { type: "verse", number: "131", sanskrit: "कन्दमूलफलाद्यांश्च तद्वद्विद्यात्तदासुतान् शाण्डाकी चा ऽसुतं चान्यत् कालाम्लं रोचनं लघु", text: "kandamūlaphalādyāṃśca tadvadvidyāttadāsutān śāṇḍākī cā 'sutaṃ cānyat kālāmlaṃ rocanaṃ laghu" },
      { type: "verse", number: "132", sanskrit: "धान्याम्लं भेदि तीक्ष्णोष्णं पित्तकृत् स्पर्शशीतलम् श्रमक्लमहरं रुच्यं दीपनं बस्तिशूलनुत्", text: "dhānyāmlaṃ bhedi tīkṣṇoṣṇaṃ pittakṛt sparśaśītalam śramaklamaharaṃ rucyaṃ dīpanaṃ bastiśūlanut" },
      { type: "verse", number: "133", sanskrit: "शस्तमास्थापने हृद्यं लघु वातकफापहम् एभिरेव गुणैर्युक्ते सौवीरकतुषोदके", text: "śastamāsthāpane hṛdyaṃ laghu vātakaphāpaham ebhireva guṇairyukte sauvīrakatuṣodake" },
      { type: "verse", number: "134", sanskrit: "क्रिमिहृद्रोगगुल्मार्शःपाण्डुरोगनिबर्हणे ते क्रमाद्वितुषैर्विद्यात्सतुषैश्च यवैः कृते इति मद्यवर्गः", text: "krimihṛdrogagulmārśaḥpāṇḍuroganibarhaṇe te kramādvituṣairvidyātsatuṣaiśca yavaiḥ kṛte iti madyavargaḥ" },
      { type: "verse", number: "135", sanskrit: "मूत्रं गोजाविमहिषीगजाश्वोष्ट्रखरोद्भवम् पित्तलं रूक्षतीक्ष्णोष्णं लवणानुरसं कटु", text: "mūtraṃ gojāvimahiṣīgajāśvoṣṭrakharodbhavam pittalaṃ rūkṣatīkṣṇoṣṇaṃ lavaṇānurasaṃ kaṭu" },
      { type: "verse", number: "136", sanskrit: "क्रिमिशोफोदरानाहशूलपाण्डुकफानिलान् गुल्मारुचिविषश्वित्रकुष्ठार्शांसि जयेल्लघु", text: "krimiśophodarānāhaśūlapāṇḍukaphānilān gulmāruciviṣaśvitrakuṣṭhārśāṃsi jayellaghu" },
      { type: "verse", number: "137", sanskrit: "विरेकास्थापनालेपस्वेदादिषु च पूजितम् दीपनं पाचनं भेदि तेषु गोमूत्रमुत्तमम्", text: "virekāsthāpanālepasvedādiṣu ca pūjitam dīpanaṃ pācanaṃ bhedi teṣu gomūtramuttamam" },
      { type: "verse", number: "138", sanskrit: "श्वासकासहरं च्छागं पूरणात् कर्णशूलजित् दद्यात् क्षारे किलासे च गजवाजिसमुद्भवम्", text: "śvāsakāsaharaṃ cchāgaṃ pūraṇāt karṇaśūlajit dadyāt kṣāre kilāse ca gajavājisamudbhavam" },
      { type: "verse", number: "139", sanskrit: "हन्त्युन्मादमपस्मारं क्रिमीन्मेहञ्च रासभम् कषायतिक्तमेतेषां हिध्माश्वासहरं शकृत्", text: "hantyunmādamapasmāraṃ krimīnmehañca rāsabham kaṣāyatiktameteṣāṃ hidhmāśvāsaharaṃ śakṛt" },
      { type: "verse", number: "140", sanskrit: "मार्गमोजःक्षयहरं वैष्किरं वातरोगनुत् प्रसहानामपस्मारमुन्मादञ्च नियच्छति", text: "mārgamojaḥkṣayaharaṃ vaiṣkiraṃ vātaroganut prasahānāmapasmāramunmādañca niyacchati" },
      { type: "verse", number: "141", sanskrit: "महामृगसमुद्भूतं कुष्ठहृज्जलचारिणाम् नेत्ररोगहरं पित्तं प्रवृद्धं च नियच्छति", text: "mahāmṛgasamudbhūtaṃ kuṣṭhahṛjjalacāriṇām netrarogaharaṃ pittaṃ pravṛddhaṃ ca niyacchati" },
      { type: "verse", number: "142", sanskrit: "पित्तं तिक्तं विषहरं रोचना कफवातजित् तिक्ता पाप्माहरामूत्रं मानुषं तु विषापहम्", text: "pittaṃ tiktaṃ viṣaharaṃ rocanā kaphavātajit tiktā pāpmāharāmūtraṃ mānuṣaṃ tu viṣāpaham" },
      { type: "verse", number: "143", sanskrit: "तोयक्षीरेक्षुतैलानां वर्गैर्मद्यस्य च क्रमात् इति द्रवैकदेशो ऽयं यथास्थूलमुदाहृतः", text: "toyakṣīrekṣutailānāṃ vargairmadyasya ca kramāt iti dravaikadeśo 'yaṃ yathāsthūlamudāhṛtaḥ" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 7,
    lang: "sa",
    content: [
      { type: "heading", heading: "Шадраса — шесть вкусов" },
      { type: "text", text: "Глава 7 Сутрастханы Астанга-санграхи посвящена теме «шесть вкусов». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथात अन्नस्वरूपविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāta annasvarūpavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "रक्तो महान् सकलमस्तूर्णकः शकुनाहृतः शारामुखो दीर्घशूको लोध्रशूकः सुगन्धिकः", text: "rakto mahān sakalamastūrṇakaḥ śakunāhṛtaḥ śārāmukho dīrghaśūko lodhraśūkaḥ sugandhikaḥ" },
      { type: "verse", number: "3", sanskrit: "पुण्ड्रः पाण्डुः पुण्डरीकः प्रमोदो गौरशारिवौ काञ्चनो महिषः शूको दूषकः कुसुमाण्डकः", text: "puṇḍraḥ pāṇḍuḥ puṇḍarīkaḥ pramodo gauraśārivau kāñcano mahiṣaḥ śūko dūṣakaḥ kusumāṇḍakaḥ" },
      { type: "verse", number: "4", sanskrit: "लाङ्गला लोहवालाख्याः कर्दमाः शीतभीरुकाः पतङ्गास्तपनीयाश्च ये चान्ये शालयः शुभाः", text: "lāṅgalā lohavālākhyāḥ kardamāḥ śītabhīrukāḥ pataṅgāstapanīyāśca ye cānye śālayaḥ śubhāḥ" },
      { type: "verse", number: "5", sanskrit: "स्वादुपाकरसाः स्निग्धा वृष्या बद्धाल्पवर्चसः कषायानुरसाः पथ्या लघवो मूत्रला हिमाः", text: "svādupākarasāḥ snigdhā vṛṣyā baddhālpavarcasaḥ kaṣāyānurasāḥ pathyā laghavo mūtralā himāḥ" },
      { type: "verse", number: "6", sanskrit: "शूकजेषु वरस्तत्र रक्तस्तृष्णात्रिदोषहा महांस्तं चानु कलमस्तं चाप्यनु ततः परे", text: "śūkajeṣu varastatra raktastṛṣṇātridoṣahā mahāṃstaṃ cānu kalamastaṃ cāpyanu tataḥ pare" },
      { type: "verse", number: "7", sanskrit: "यवका हायनाः पांसुवाप्यनैषधकादयः स्वादूष्णा गुरवः स्निग्धाः पाके ऽम्लाः श्लेष्मपित्तलाः", text: "yavakā hāyanāḥ pāṃsuvāpyanaiṣadhakādayaḥ svādūṣṇā guravaḥ snigdhāḥ pāke 'mlāḥ śleṣmapittalāḥ" },
      { type: "verse", number: "8", sanskrit: "सृष्टमूत्रपुरीषाश्च पूर्वं पूर्वं च निन्दिताः स्निग्धो ग्राही लघुः स्वादुस्त्रिदोषघ्नः स्थिरो हिमः", text: "sṛṣṭamūtrapurīṣāśca pūrvaṃ pūrvaṃ ca ninditāḥ snigdho grāhī laghuḥ svādustridoṣaghnaḥ sthiro himaḥ" },
      { type: "verse", number: "9", sanskrit: "षष्टिको व्रीहिषु श्रेष्ठो गौरश्चासितगौरतः ततः क्रमान्महाव्रीहिकृष्णव्रीहिजतूमुखाः", text: "ṣaṣṭiko vrīhiṣu śreṣṭho gauraścāsitagaurataḥ tataḥ kramānmahāvrīhikṛṣṇavrīhijatūmukhāḥ" },
      { type: "verse", number: "10", sanskrit: "कुक्कुटाण्डकलाबाक्षपारावतकसूकराः वरकोद्दालकोज्जालचीनशारददर्दुराः", text: "kukkuṭāṇḍakalābākṣapārāvatakasūkarāḥ varakoddālakojjālacīnaśāradadardurāḥ" },
      { type: "verse", number: "11", sanskrit: "गन्धनाः कुरुविन्दाश्च गुणैरल्पान्तराः स्मृताः स्वादुरम्लविपाको ऽन्यो व्रीहिः पित्तकरो गुरुः", text: "gandhanāḥ kuruvindāśca guṇairalpāntarāḥ smṛtāḥ svāduramlavipāko 'nyo vrīhiḥ pittakaro guruḥ" },
      { type: "verse", number: "12", sanskrit: "बहुमूत्रपुरीषोष्मा त्रिदोषस्त्वेव पाटलः कङ्गुकोद्रवजूर्णाह्वगदीवरुणपादिकाः", text: "bahumūtrapurīṣoṣmā tridoṣastveva pāṭalaḥ kaṅgukodravajūrṇāhvagadīvaruṇapādikāḥ" },
      { type: "verse", number: "13", sanskrit: "श्यामाकतोयश्यामाकहस्तिश्यामाकशिल्बिकाः शिशिरोद्दालनीवारवरूकबरकोत्कटाः", text: "śyāmākatoyaśyāmākahastiśyāmākaśilbikāḥ śiśiroddālanīvāravarūkabarakotkaṭāḥ" },
      { type: "verse", number: "14", sanskrit: "मधूलिकान्तनिर्गण्डीवेणुपर्णीप्रशान्तिकाः गवेथुकाण्डलौहित्यतोयपर्णीमुकुन्दराः", text: "madhūlikāntanirgaṇḍīveṇuparṇīpraśāntikāḥ gavethukāṇḍalauhityatoyaparṇīmukundarāḥ" },
      { type: "verse", number: "15", sanskrit: "कफपित्तहरा रूक्साः कषायमधुरा हिमाः वातला बद्धविण्मूत्रा लघवो लेखनात्मकाः", text: "kaphapittaharā rūksāḥ kaṣāyamadhurā himāḥ vātalā baddhaviṇmūtrā laghavo lekhanātmakāḥ" },
      { type: "verse", number: "16", sanskrit: "भग्नसन्धानकृत्तत्र प्रियङ्गुबृंहणी गुरुः कोरदूषः परं ग्राई स्पर्शे शीतो विषापहः", text: "bhagnasandhānakṛttatra priyaṅgubṛṃhaṇī guruḥ koradūṣaḥ paraṃ grāī sparśe śīto viṣāpahaḥ" },
      { type: "verse", number: "17", sanskrit: "उद्दालकस्तु वीर्योष्णो नीवारः श्लेष्मवर्धनः शीतवीर्या विशेषेण स्निग्धा वृष्या मधूलिका", text: "uddālakastu vīryoṣṇo nīvāraḥ śleṣmavardhanaḥ śītavīryā viśeṣeṇa snigdhā vṛṣyā madhūlikā" },
      { type: "verse", number: "18", sanskrit: "रूक्षः शीतो गुरुः स्वादुः सरो विड्वातकृद्यवः वृष्यः स्थैर्यकरो मूत्रमेदःपित्तकफान् जयेत्", text: "rūkṣaḥ śīto guruḥ svāduḥ saro viḍvātakṛdyavaḥ vṛṣyaḥ sthairyakaro mūtramedaḥpittakaphān jayet" },
      { type: "verse", number: "19", sanskrit: "पीनसश्वासकासोरुस्तम्भकण्ठत्वगामयान् गुणैर्न्यूनतरा ज्ञेया यवादनुयवाह्वयाः", text: "pīnasaśvāsakāsorustambhakaṇṭhatvagāmayān guṇairnyūnatarā jñeyā yavādanuyavāhvayāḥ" },
      { type: "verse", number: "20", sanskrit: "ऊष्णाः सरा वेणुयवाः कषाया वातपित्तलाः वृष्यः शीतो गुरुः स्निग्धो जीवनो वातपित्तहा", text: "ūṣṇāḥ sarā veṇuyavāḥ kaṣāyā vātapittalāḥ vṛṣyaḥ śīto guruḥ snigdho jīvano vātapittahā" },
      { type: "verse", number: "21", sanskrit: "सन्धानकरी मधुरो गोधूमः स्थैर्यकृत् सरः पथ्या नन्दीमुखी शीता कषाया मधुरा लघुः इति शूकधान्यवर्गः", text: "sandhānakarī madhuro godhūmaḥ sthairyakṛt saraḥ pathyā nandīmukhī śītā kaṣāyā madhurā laghuḥ iti śūkadhānyavargaḥ" },
      { type: "verse", number: "22", sanskrit: "शिम्बिजा मुद्गमङ्गल्यवनमुद्गमकुष्ठकाः मसूरकफलाढक्यश्चणकाश्चपृथग्विधाः", text: "śimbijā mudgamaṅgalyavanamudgamakuṣṭhakāḥ masūrakaphalāḍhakyaścaṇakāścapṛthagvidhāḥ" },
      { type: "verse", number: "23", sanskrit: "कषायस्वादुलघवो विबन्धाध्मानकारिणः रूक्षा बद्धमलाः शीता विपाके कटुका हिताः", text: "kaṣāyasvādulaghavo vibandhādhmānakāriṇaḥ rūkṣā baddhamalāḥ śītā vipāke kaṭukā hitāḥ" },
      { type: "verse", number: "24", sanskrit: "पित्तासृक्कफमेदस्सु सूपालेपादियोजनात् सूप्यानामुत्तमा मुद्गा लघीयांशो ऽल्पमारुताः", text: "pittāsṛkkaphamedassu sūpālepādiyojanāt sūpyānāmuttamā mudgā laghīyāṃśo 'lpamārutāḥ" },
      { type: "verse", number: "25", sanskrit: "हरितास्तेष्वपि वरा मकुष्ठाः क्रिमिकारिणः वर्ण्याः परं प्रलेपाद्यैर्मसूरा ग्राहिणो भृशम्", text: "haritāsteṣvapi varā makuṣṭhāḥ krimikāriṇaḥ varṇyāḥ paraṃ pralepādyairmasūrā grāhiṇo bhṛśam" },
      { type: "verse", number: "26", sanskrit: "राजमाषो गुरुर्भूरिशकृद्रूक्सो ऽतिवातलः कषायस्वादुरूक्षोष्णाः कुलत्था रक्तपित्तलाः", text: "rājamāṣo gururbhūriśakṛdrūkso 'tivātalaḥ kaṣāyasvādurūkṣoṣṇāḥ kulatthā raktapittalāḥ" },
      { type: "verse", number: "27", sanskrit: "पीनसश्वासकासार्शोहिध्मानाहकफानिलान् घ्नन्ति शुक्राश्मरीं शुक्रं दृष्टिं शोफं तथोदरम्", text: "pīnasaśvāsakāsārśohidhmānāhakaphānilān ghnanti śukrāśmarīṃ śukraṃ dṛṣṭiṃ śophaṃ tathodaram" },
      { type: "verse", number: "28", sanskrit: "ग्राहिणो लघवस्तीक्ष्णा विपाके ऽम्ला विदाहिनः निष्पावस्तु सरो रूक्षः कषायमधुरो गुरुः", text: "grāhiṇo laghavastīkṣṇā vipāke 'mlā vidāhinaḥ niṣpāvastu saro rūkṣaḥ kaṣāyamadhuro guruḥ" },
      { type: "verse", number: "29", sanskrit: "पाके ऽम्लो वातविष्टम्भी स्तन्यमूत्रास्रपित्तकृत् उष्णो विदाही दृक्च्छुक्रकफशोफविशापहः", text: "pāke 'mlo vātaviṣṭambhī stanyamūtrāsrapittakṛt uṣṇo vidāhī dṛkcchukrakaphaśophaviśāpahaḥ" },
      { type: "verse", number: "30", sanskrit: "माषः स्निग्धो बलश्लेष्ममलपित्तकरः सरः गुरूष्णो ऽनिलहा स्वादुः शुक्रवृद्धिविरेककृत्", text: "māṣaḥ snigdho balaśleṣmamalapittakaraḥ saraḥ gurūṣṇo 'nilahā svāduḥ śukravṛddhivirekakṛt" },
      { type: "verse", number: "31", sanskrit: "फलानि गुणवद्विद्यात् काकाण्डोलात्मगुप्तयोः कुशाम्रशिम्बी मधुरा वातपित्तहरा हिमा", text: "phalāni guṇavadvidyāt kākāṇḍolātmaguptayoḥ kuśāmraśimbī madhurā vātapittaharā himā" },
      { type: "verse", number: "32", sanskrit: "मधुराः शीतला गुर्व्यो बलघ्न्यो रूक्षणात्मिकाः स्नेहाढ्या बलिभिर्भोज्या विविधाः शिम्बिजातयः", text: "madhurāḥ śītalā gurvyo balaghnyo rūkṣaṇātmikāḥ snehāḍhyā balibhirbhojyā vividhāḥ śimbijātayaḥ" },
      { type: "verse", number: "33", sanskrit: "स्निग्धोष्णतिक्तकटुकः कषायमधुरस्तिलः मेध्यः केश्यो गुरुर्वर्ण्यः स्पर्शशीतो ऽनिलापहः", text: "snigdhoṣṇatiktakaṭukaḥ kaṣāyamadhurastilaḥ medhyaḥ keśyo gururvarṇyaḥ sparśaśīto 'nilāpahaḥ" },
      { type: "verse", number: "34", sanskrit: "अल्पमूत्रः कटुः पाके मेधाग्निकफपित्तकृत् कृष्णः प्रशस्तस्तमनु शुक्लस्तमनु चारुण", text: "alpamūtraḥ kaṭuḥ pāke medhāgnikaphapittakṛt kṛṣṇaḥ praśastastamanu śuklastamanu cāruṇa" },
      { type: "verse", number: "35", sanskrit: "स्निग्धोमा स्वादुतिक्तोष्णा कफपित्तकरी गुरुः दृक्च्छुक्रहृत् कटुः पाके तद्वत् बीजं कुसुम्भजम्", text: "snigdhomā svādutiktoṣṇā kaphapittakarī guruḥ dṛkcchukrahṛt kaṭuḥ pāke tadvat bījaṃ kusumbhajam" },
      { type: "verse", number: "36", sanskrit: "माषो ऽत्र सर्वेष्ववरो यवकः शूकजेषु च नवं धान्यमभिष्यन्दि सेक्यं केदारजं च यत्", text: "māṣo 'tra sarveṣvavaro yavakaḥ śūkajeṣu ca navaṃ dhānyamabhiṣyandi sekyaṃ kedārajaṃ ca yat" },
      { type: "verse", number: "37", sanskrit: "लघु वर्षोषितं दग्धभूमिजं स्थलसम्भवम् शीघ्रजन्म तथा सूप्यं निस्तुषं युक्तिभर्जितम् इति शिम्बिधान्यवर्गः", text: "laghu varṣoṣitaṃ dagdhabhūmijaṃ sthalasambhavam śīghrajanma tathā sūpyaṃ nistuṣaṃ yuktibharjitam iti śimbidhānyavargaḥ" },
      { type: "verse", number: "38", sanskrit: "मण्डपेयाविलेपीनामोदनस्य च लाघवम् यथापूर्वं शिवस्तत्र मण्डो वातानुलोमनः", text: "maṇḍapeyāvilepīnāmodanasya ca lāghavam yathāpūrvaṃ śivastatra maṇḍo vātānulomanaḥ" },
      { type: "verse", number: "39", sanskrit: "तृड्ग्लानिदोषशेषघ्नः पाचनो धातुसाम्यकृत् स्रोतोमार्दवकृत् स्वेदी सन्धुक्षयति चानलम्", text: "tṛḍglānidoṣaśeṣaghnaḥ pācano dhātusāmyakṛt srotomārdavakṛt svedī sandhukṣayati cānalam" },
      { type: "verse", number: "40", sanskrit: "क्षुत्तृष्णाग्लानिदौर्बल्यकुक्षिरोगज्वरापहा मलानुलोमनी पथ्या पेया दीपनपाचनी", text: "kṣuttṛṣṇāglānidaurbalyakukṣirogajvarāpahā malānulomanī pathyā peyā dīpanapācanī" },
      { type: "verse", number: "41", sanskrit: "विलेपी ग्राहिणी हृद्या तृष्णाघ्नी दीपनी हिता व्रणाक्षिरोगसंशुद्धदुर्बलस्नेहपायिताम्", text: "vilepī grāhiṇī hṛdyā tṛṣṇāghnī dīpanī hitā vraṇākṣirogasaṃśuddhadurbalasnehapāyitām" },
      { type: "verse", number: "42", sanskrit: "सुधौतः प्रस्रुतः स्विन्नस्त्यक्तोष्मा चौदनो लघुः यश्चाग्नेयौषधक्वाथसाधितो भृष्टतण्डुलः", text: "sudhautaḥ prasrutaḥ svinnastyaktoṣmā caudano laghuḥ yaścāgneyauṣadhakvāthasādhito bhṛṣṭataṇḍulaḥ" },
      { type: "verse", number: "43", sanskrit: "विपरीतो गुरुः क्षीरमांसाद्यैर्यश्च साधितः इति द्रव्यक्रियायोगमानाद्यैः सर्वमादिशेत्", text: "viparīto guruḥ kṣīramāṃsādyairyaśca sādhitaḥ iti dravyakriyāyogamānādyaiḥ sarvamādiśet" },
      { type: "verse", number: "44", sanskrit: "शुष्यतां व्याधिमुक्तानां शुद्धानां शुद्धिकाङ्क्षिणाम् कृशक्षामक्षतोरस्कक्षीणधात्विन्द्रियौजसाम्", text: "śuṣyatāṃ vyādhimuktānāṃ śuddhānāṃ śuddhikāṅkṣiṇām kṛśakṣāmakṣatoraskakṣīṇadhātvindriyaujasām" },
      { type: "verse", number: "45", sanskrit: "दृष्टिश्रवणवह्न्यायुर्बलवर्णस्वरार्थिनाम् भग्नाविश्लिष्टसन्धीनां व्रणिनां वातरोगिणाम्", text: "dṛṣṭiśravaṇavahnyāyurbalavarṇasvarārthinām bhagnāviśliṣṭasandhīnāṃ vraṇināṃ vātarogiṇām" },
      { type: "verse", number: "46", sanskrit: "हृद्यः पथ्यः परं वृष्यो बृंहणः प्रीणनो रसः मौद्गस्तु पथ्यः संशुद्धव्रणकण्ठाक्षिरोगिणाम्", text: "hṛdyaḥ pathyaḥ paraṃ vṛṣyo bṛṃhaṇaḥ prīṇano rasaḥ maudgastu pathyaḥ saṃśuddhavraṇakaṇṭhākṣirogiṇām" },
      { type: "verse", number: "47", sanskrit: "वातानुलोमी कौलत्थो गुल्मतूनिप्रतूनिजित् प्रभूताभ्यन्तरमलो माषसूपः परं स्मृतः", text: "vātānulomī kaulattho gulmatūnipratūnijit prabhūtābhyantaramalo māṣasūpaḥ paraṃ smṛtaḥ" },
      { type: "verse", number: "48", sanskrit: "खलकाम्बलिकौ हृद्यौ च्छेदिनौ स्वौषधानुगौ पिशितेन रसस्तत्र यूषो धान्यैः खलः फलैः", text: "khalakāmbalikau hṛdyau cchedinau svauṣadhānugau piśitena rasastatra yūṣo dhānyaiḥ khalaḥ phalaiḥ" },
      { type: "verse", number: "49", sanskrit: "मूलैश्च तिलकल्काम्लप्रायः काम्बलिकः स्मृतः ज्ञेयाः कृताकृतास्ते तु स्नेहादियुतवर्जिताः", text: "mūlaiśca tilakalkāmlaprāyaḥ kāmbalikaḥ smṛtaḥ jñeyāḥ kṛtākṛtāste tu snehādiyutavarjitāḥ" },
      { type: "verse", number: "50", sanskrit: "अल्पमांसादयः स्वच्छा दकलावणिकाः स्मृताः विद्याद्यूषे रसे सूपे शाके चैवोत्तरोत्तरम्", text: "alpamāṃsādayaḥ svacchā dakalāvaṇikāḥ smṛtāḥ vidyādyūṣe rase sūpe śāke caivottarottaram" },
      { type: "verse", number: "51", sanskrit: "गौरवं तनुसान्द्राम्लस्वादुष्वेषु पृथक् तथा तिलपिण्याकविकृतिः शुष्कशाकं विरूढकम्", text: "gauravaṃ tanusāndrāmlasvāduṣveṣu pṛthak tathā tilapiṇyākavikṛtiḥ śuṣkaśākaṃ virūḍhakam" },
      { type: "verse", number: "52", sanskrit: "चाण्डाकीवटकं दृघ्नं दोषलं ग्लपनं गुरु पर्पटा लघवो रुच्या लघीयान् क्षारपर्पटः", text: "cāṇḍākīvaṭakaṃ dṛghnaṃ doṣalaṃ glapanaṃ guru parpaṭā laghavo rucyā laghīyān kṣāraparpaṭaḥ" },
      { type: "verse", number: "53", sanskrit: "हृद्या वृष्या रुचिकरा गुरुवो रागषाडवाः प्रीणना भ्रमतृट्च्छरिदिमेदमूर्छाश्रमच्छिदः", text: "hṛdyā vṛṣyā rucikarā guruvo rāgaṣāḍavāḥ prīṇanā bhramatṛṭccharidimedamūrchāśramacchidaḥ" },
      { type: "verse", number: "54", sanskrit: "तृट्च्छर्दिश्रमनुन्मन्थः शीतः सद्योबलप्रदः प्रमेहक्षयकुष्ठानि न च स्युर्मन्थपायिनः", text: "tṛṭcchardiśramanunmanthaḥ śītaḥ sadyobalapradaḥ pramehakṣayakuṣṭhāni na ca syurmanthapāyinaḥ" },
      { type: "verse", number: "55", sanskrit: "रसाला बृंहणी वृष्या स्निग्धा बलय रुचिप्रदा श्रमक्षुत्तृट्क्लमहरं पानकं प्रीणनं गुरु", text: "rasālā bṛṃhaṇī vṛṣyā snigdhā balaya rucipradā śramakṣuttṛṭklamaharaṃ pānakaṃ prīṇanaṃ guru" },
      { type: "verse", number: "56", sanskrit: "विष्टम्भि मूत्रलं हृद्यं यथाद्रव्यगुणं च तत् लाजास्तृट्च्छर्द्यतीसारमेहमेदःकफच्छिदः", text: "viṣṭambhi mūtralaṃ hṛdyaṃ yathādravyaguṇaṃ ca tat lājāstṛṭcchardyatīsāramehamedaḥkaphacchidaḥ" },
      { type: "verse", number: "57", sanskrit: "कासपित्तोपशमना दीपना लघवो हिमाः पृथुका गुरवो बल्याः कफविष्टम्भकारिणः", text: "kāsapittopaśamanā dīpanā laghavo himāḥ pṛthukā guravo balyāḥ kaphaviṣṭambhakāriṇaḥ" },
      { type: "verse", number: "58", sanskrit: "धान विष्टम्भिनी रूक्षा तर्पणी लेखनी गुरुः कण्ठनेत्रमयक्षुत्तृट्श्रमछर्दिव्रणापहा", text: "dhāna viṣṭambhinī rūkṣā tarpaṇī lekhanī guruḥ kaṇṭhanetramayakṣuttṛṭśramachardivraṇāpahā" },
      { type: "verse", number: "59", sanskrit: "सक्तवो लघवः पानात् सद्य एव बलप्रदाः निचयात् कठिना गुर्वी प्रोक्ता पिण्डी मृदुर्लघुः", text: "saktavo laghavaḥ pānāt sadya eva balapradāḥ nicayāt kaṭhinā gurvī proktā piṇḍī mṛdurlaghuḥ" },
      { type: "verse", number: "60", sanskrit: "सक्तूनां द्रवतायोगाल्लघीयस्यवलेहिका शष्कुलीमोदकादीनां व्याख्यातैवं च कल्पना", text: "saktūnāṃ dravatāyogāllaghīyasyavalehikā śaṣkulīmodakādīnāṃ vyākhyātaivaṃ ca kalpanā" },
      { type: "verse", number: "61", sanskrit: "नोदकान्तरितान्न द्विर्न निशायां न केवलान् न भुक्त्वा न द्विजैश्छित्वा सक्तूनद्यान्न वा बहून्", text: "nodakāntaritānna dvirna niśāyāṃ na kevalān na bhuktvā na dvijaiśchitvā saktūnadyānna vā bahūn" },
      { type: "verse", number: "62", sanskrit: "कर्कन्धुबदरदीनां श्रमतृष्णाक्लमच्छिदः सक्तवो ऽम्लरसा हृद्या यथाद्रव्यगुणाश्च ते", text: "karkandhubadaradīnāṃ śramatṛṣṇāklamacchidaḥ saktavo 'mlarasā hṛdyā yathādravyaguṇāśca te" },
      { type: "verse", number: "63", sanskrit: "पिण्याको ग्लपनो रूक्षो विष्टम्भी दृष्टिदूषणः वेशवारो गुरुः स्निग्धो बलोपचयवर्धनः", text: "piṇyāko glapano rūkṣo viṣṭambhī dṛṣṭidūṣaṇaḥ veśavāro guruḥ snigdho balopacayavardhanaḥ" },
      { type: "verse", number: "64", sanskrit: "मुद्गदिजास्तु गुरवो यथाद्रव्यगुणानुगाः कुकूलकर्परभ्राष्टकन्द्वङ्गारविपाचितान् एकयोनीन् लघून्विद्यादपूपानुत्तरोत्तरम् इति कृतान्नवर्गः", text: "mudgadijāstu guravo yathādravyaguṇānugāḥ kukūlakarparabhrāṣṭakandvaṅgāravipācitān ekayonīn laghūnvidyādapūpānuttarottaram iti kṛtānnavargaḥ" },
      { type: "verse", number: "65", sanskrit: "हरिणैणकुरङ्गर्श्यगोकर्णमृगमातृकाः कालपुच्छकचारुष्कवरपोतशशोरणाः", text: "hariṇaiṇakuraṅgarśyagokarṇamṛgamātṛkāḥ kālapucchakacāruṣkavarapotaśaśoraṇāḥ" },
      { type: "verse", number: "66", sanskrit: "श्वदंष्ट्रामशरभकोहकारकशम्बराः करालकृतमालौ च पृषतश्च मृगाः स्मृताः", text: "śvadaṃṣṭrāmaśarabhakohakārakaśambarāḥ karālakṛtamālau ca pṛṣataśca mṛgāḥ smṛtāḥ" },
      { type: "verse", number: "67", sanskrit: "लाववातिकवर्तीररक्तवर्त्मककर्कराः कपिञ्जलोपचक्राख्यचकोररुरुबाहवः", text: "lāvavātikavartīraraktavartmakakarkarāḥ kapiñjalopacakrākhyacakorarurubāhavaḥ" },
      { type: "verse", number: "68", sanskrit: "वर्तको वर्तिका चेति तित्तिरिः क्रकरः शिखी तारचूडाख्यवरकगोनर्दगिरिवर्तिकाः", text: "vartako vartikā ceti tittiriḥ krakaraḥ śikhī tāracūḍākhyavarakagonardagirivartikāḥ" },
      { type: "verse", number: "69", sanskrit: "तथा शारपदेन्द्राह्ववारटाश्चेति विष्किराः शतपत्रो भृङ्गराजः कोयष्टी जीवजीवकः", text: "tathā śārapadendrāhvavāraṭāśceti viṣkirāḥ śatapatro bhṛṅgarājaḥ koyaṣṭī jīvajīvakaḥ" },
      { type: "verse", number: "70", sanskrit: "खञ्जरीटकहारीतदुर्नामारिकृशाग्रहाः लट्वा लडूषो वटहा रोक्ष्वेलो डिण्डिमाणवः", text: "khañjarīṭakahārītadurnāmārikṛśāgrahāḥ laṭvā laḍūṣo vaṭahā rokṣvelo ḍiṇḍimāṇavaḥ" },
      { type: "verse", number: "71", sanskrit: "जटी दुन्दुभिपार्कारलोहपृष्ठकुलिङ्गकाः शारिकाशुकशार्ङ्गाख्यचिरीटीककुयष्टिकाः", text: "jaṭī dundubhipārkāralohapṛṣṭhakuliṅgakāḥ śārikāśukaśārṅgākhyacirīṭīkakuyaṣṭikāḥ" },
      { type: "verse", number: "72", sanskrit: "मञ्जरीयकदात्यूहगोधापुत्रप्रियात्मजाः कलविङ्कः परभृतः कपोतो ऽङ्गारचूडकः", text: "mañjarīyakadātyūhagodhāputrapriyātmajāḥ kalaviṅkaḥ parabhṛtaḥ kapoto 'ṅgāracūḍakaḥ" },
      { type: "verse", number: "73", sanskrit: "पारावतः पाणविक इत्युक्ताः प्रतुदा द्विजाः श्वेतः श्यामश्चित्रपृष्ठः कालकः काकुली मृगः", text: "pārāvataḥ pāṇavika ityuktāḥ pratudā dvijāḥ śvetaḥ śyāmaścitrapṛṣṭhaḥ kālakaḥ kākulī mṛgaḥ" },
      { type: "verse", number: "74", sanskrit: "भेकचिल्लटकूचीका गोधाशल्यकशाण्डकाः वृषाहिकदलीश्वाविन्नकुलाद्या बिलेशयाः", text: "bhekacillaṭakūcīkā godhāśalyakaśāṇḍakāḥ vṛṣāhikadalīśvāvinnakulādyā bileśayāḥ" },
      { type: "verse", number: "75", sanskrit: "गोखराश्वतरोष्ट्राश्वद्वीपिसिंहर्क्षवानराः मार्जारमूषिकव्याघ्रवृकबभ्रुतरक्षवः", text: "gokharāśvataroṣṭrāśvadvīpisiṃharkṣavānarāḥ mārjāramūṣikavyāghravṛkababhrutarakṣavaḥ" },
      { type: "verse", number: "76", sanskrit: "लोपाकजम्बुकश्येनचाषोलूकश्ववायसाः शशघ्नीभासकुररगृध्रवेश्यकुलिङ्गकाः", text: "lopākajambukaśyenacāṣolūkaśvavāyasāḥ śaśaghnībhāsakuraragṛdhraveśyakuliṅgakāḥ" },
      { type: "verse", number: "77", sanskrit: "धूमिका मधुहा चेति प्रसहा मृगपक्षिणः महिषन्यङ्कुरोहीतवराहरुरुवारणाः", text: "dhūmikā madhuhā ceti prasahā mṛgapakṣiṇaḥ mahiṣanyaṅkurohītavarāharuruvāraṇāḥ" },
      { type: "verse", number: "78", sanskrit: "सृमरश्चमरः खड्गो गवयश्च महामृगाः हंससारसकादम्बबककारण्डवप्लवाः", text: "sṛmaraścamaraḥ khaḍgo gavayaśca mahāmṛgāḥ haṃsasārasakādambabakakāraṇḍavaplavāḥ" },
      { type: "verse", number: "79", sanskrit: "मृणालकण्ठचक्राह्वबलाका रक्तशीर्षकाः उत्क्रोशपुण्डरीकाक्षशरारीमणितुण्डकाः", text: "mṛṇālakaṇṭhacakrāhvabalākā raktaśīrṣakāḥ utkrośapuṇḍarīkākṣaśarārīmaṇituṇḍakāḥ" },
      { type: "verse", number: "80", sanskrit: "काकतुण्डघनारावमद्गुक्रौञ्चाम्बुकुक्कुटाः नद्यास्योमल्लिकाद्याश्च पक्षिणो जलचारिणः", text: "kākatuṇḍaghanārāvamadgukrauñcāmbukukkuṭāḥ nadyāsyomallikādyāśca pakṣiṇo jalacāriṇaḥ" },
      { type: "verse", number: "81", sanskrit: "मत्स्या रोहितपाठीनकूर्मकुम्भीरकर्कटाः शुक्तिशङ्खोद्रुशम्बूकशफरीवर्त्मिचन्द्रिकाः", text: "matsyā rohitapāṭhīnakūrmakumbhīrakarkaṭāḥ śuktiśaṅkhodruśambūkaśapharīvartmicandrikāḥ" },
      { type: "verse", number: "82", sanskrit: "बुलूकीनक्रमकरशिंशुमारतिमिङ्गलाः राजी चिलिचिमाद्यश्च मांसमित्याहुरष्टधा", text: "bulūkīnakramakaraśiṃśumāratimiṅgalāḥ rājī cilicimādyaśca māṃsamityāhuraṣṭadhā" },
      { type: "verse", number: "83", sanskrit: "योनिष्वजावी व्यामिश्रगोचरत्वादनिश्चिते आद्यान्त्या जाङ्गलानूपा मध्यौ साधारणौ स्मृतौ", text: "yoniṣvajāvī vyāmiśragocaratvādaniścite ādyāntyā jāṅgalānūpā madhyau sādhāraṇau smṛtau" },
      { type: "verse", number: "84", sanskrit: "विकीर्यादिक्रियायोगैर्भक्षणाद्विष्किरादयः तत्र बद्धमला रुच्या मांसानामुत्तमाः हिमाः", text: "vikīryādikriyāyogairbhakṣaṇādviṣkirādayaḥ tatra baddhamalā rucyā māṃsānāmuttamāḥ himāḥ" },
      { type: "verse", number: "85", sanskrit: "कषायस्वादुविशदा लघवो जाङ्गला हिताः पित्तोत्तरे वातमध्ये सन्निपाते कफानुगे", text: "kaṣāyasvāduviśadā laghavo jāṅgalā hitāḥ pittottare vātamadhye sannipāte kaphānuge" },
      { type: "verse", number: "86", sanskrit: "ताम्रो ऽत्र हरिणः कृष्णस्त्वेणो हृद्यस्त्रिदोषजित् लघीयान् षड्रसश्चासौ ग्राही रूक्षो हिमः शशः", text: "tāmro 'tra hariṇaḥ kṛṣṇastveṇo hṛdyastridoṣajit laghīyān ṣaḍrasaścāsau grāhī rūkṣo himaḥ śaśaḥ" },
      { type: "verse", number: "87", sanskrit: "कटुपाको ऽग्निकृत् पथ्यः सन्निपाते ऽनिलावरे तद्वल्लावो ऽप्यरूक्षस्तुं किञ्चिद्रूक्षः कपिञ्जलः", text: "kaṭupāko 'gnikṛt pathyaḥ sannipāte 'nilāvare tadvallāvo 'pyarūkṣastuṃ kiñcidrūkṣaḥ kapiñjalaḥ" },
      { type: "verse", number: "88", sanskrit: "पारावताः कपोताश्चृअ तद्वद्वन्याः सुपूजिताः ईषदुष्णगुरुस्निग्धा बृंहणा वर्तकादयः", text: "pārāvatāḥ kapotāścṛa tadvadvanyāḥ supūjitāḥ īṣaduṣṇagurusnigdhā bṛṃhaṇā vartakādayaḥ" },
      { type: "verse", number: "89", sanskrit: "तित्तिरिस्तेष्वपि वरो मेधाग्निबलशुक्रकृत् ग्राही वर्ण्यो ऽनिलोद्रिक्तसन्निपातहरः परम्", text: "tittiristeṣvapi varo medhāgnibalaśukrakṛt grāhī varṇyo 'nilodriktasannipātaharaḥ param" },
      { type: "verse", number: "90", sanskrit: "धन्वानूपविचारित्वात् स्निग्धोष्णगुरुबृंहणः नातिपथ्यः शिखी पथ्यः श्रोत्रस्वरवयोदृशाम्", text: "dhanvānūpavicāritvāt snigdhoṣṇagurubṛṃhaṇaḥ nātipathyaḥ śikhī pathyaḥ śrotrasvaravayodṛśām" },
      { type: "verse", number: "91", sanskrit: "तद्वच्च कुक्कुटो वृष्यो ग्राम्यस्तु श्लेष्मलो गुरुः मेधानलकरा हृद्याः करकराः सोपचक्रकाः", text: "tadvacca kukkuṭo vṛṣyo grāmyastu śleṣmalo guruḥ medhānalakarā hṛdyāḥ karakarāḥ sopacakrakāḥ" },
      { type: "verse", number: "92", sanskrit: "गुरुः सलवणः काणकपोतः सर्वदोषकृत् गुरूष्णस्निग्धमधुरा वर्गाश्चातो यथोत्तरम्", text: "guruḥ salavaṇaḥ kāṇakapotaḥ sarvadoṣakṛt gurūṣṇasnigdhamadhurā vargāścāto yathottaram" },
      { type: "verse", number: "93", sanskrit: "मूत्रशुक्रकृतो बल्या वातघ्नाः कफपित्तलाः शीता महामृगास्तेषु क्रव्यादाः प्रसहाः पुनः", text: "mūtraśukrakṛto balyā vātaghnāḥ kaphapittalāḥ śītā mahāmṛgāsteṣu kravyādāḥ prasahāḥ punaḥ" },
      { type: "verse", number: "94", sanskrit: "चक्षुष्याः सृष्टविण्मूत्रा मांसलाः कटुपाकिनः जीर्णार्शोग्रहणीदोषशोषार्तानां परं हिताः", text: "cakṣuṣyāḥ sṛṣṭaviṇmūtrā māṃsalāḥ kaṭupākinaḥ jīrṇārśograhaṇīdoṣaśoṣārtānāṃ paraṃ hitāḥ" },
      { type: "verse", number: "95", sanskrit: "गोधा नियछति विषं मूषिकः शुक्रवर्धनः शुष्ककासश्रमात्यग्निविषमज्वरपीनसान्", text: "godhā niyachati viṣaṃ mūṣikaḥ śukravardhanaḥ śuṣkakāsaśramātyagniviṣamajvarapīnasān" },
      { type: "verse", number: "96", sanskrit: "कार्श्यकेवलवातांश्च गोमांसं सन्नियच्छति चटकाः श्लेष्मलाः स्निग्धा वातघ्नाः शुक्रलाः परम्", text: "kārśyakevalavātāṃśca gomāṃsaṃ sanniyacchati caṭakāḥ śleṣmalāḥ snigdhā vātaghnāḥ śukralāḥ param" },
      { type: "verse", number: "97", sanskrit: "गुरूष्णो महिषः स्निग्धः स्वप्नदार्ढ्यबृहत्वकृत् तद्वद्वराहः श्रमहा रुचिशुक्रबलप्रदः", text: "gurūṣṇo mahiṣaḥ snigdhaḥ svapnadārḍhyabṛhatvakṛt tadvadvarāhaḥ śramahā ruciśukrabalapradaḥ" },
      { type: "verse", number: "98", sanskrit: "हंसः स्वरकरः पित्तरक्तजिन्मेदुरो हिमः कफपित्तकरा मत्स्याः परं पवननाशनाः", text: "haṃsaḥ svarakaraḥ pittaraktajinmeduro himaḥ kaphapittakarā matsyāḥ paraṃ pavananāśanāḥ" },
      { type: "verse", number: "99", sanskrit: "प्रतिस्रोतोविचारित्वादाकाशप्लवनेन च रोहितः प्रवरस्तेषां परं चिलिचिमो ऽवरः", text: "pratisrotovicāritvādākāśaplavanena ca rohitaḥ pravarasteṣāṃ paraṃ cilicimo 'varaḥ" },
      { type: "verse", number: "100", sanskrit: "अगोचरविचारित्वात् सर्वदोषकरो हि सः कुलीरः परमं वृष्यो बृंहणः प्रीणनो गुरुः", text: "agocaravicāritvāt sarvadoṣakaro hi saḥ kulīraḥ paramaṃ vṛṣyo bṛṃhaṇaḥ prīṇano guruḥ" },
      { type: "verse", number: "101", sanskrit: "नातिशीतगुरुस्निग्धं मांसमाजमदोषलम् शरीरधातुसामान्यादनभिष्यन्दि बृंहणम्", text: "nātiśītagurusnigdhaṃ māṃsamājamadoṣalam śarīradhātusāmānyādanabhiṣyandi bṛṃhaṇam" },
      { type: "verse", number: "102", sanskrit: "विपरीतमतो ज्ञेयमाविकं बृंहणं तु तत् अतिमेद्यं त्यजेन्मांसं हतं व्याधिविषोदकैः", text: "viparītamato jñeyamāvikaṃ bṛṃhaṇaṃ tu tat atimedyaṃ tyajenmāṃsaṃ hataṃ vyādhiviṣodakaiḥ" },
      { type: "verse", number: "103", sanskrit: "स्वयं मृतं धूमपूर्णमगोचरभृतं कृशम् सद्योहतं वयस्थं च शुद्धं सुरभि शस्यते", text: "svayaṃ mṛtaṃ dhūmapūrṇamagocarabhṛtaṃ kṛśam sadyohataṃ vayasthaṃ ca śuddhaṃ surabhi śasyate" },
      { type: "verse", number: "104", sanskrit: "एणः कुरङ्गो हरिणः शशो लावः कपिञ्जलः तित्तिरिः क्रकरो गोधा श्वाविड्गृध्रो मृगाधिपः", text: "eṇaḥ kuraṅgo hariṇaḥ śaśo lāvaḥ kapiñjalaḥ tittiriḥ krakaro godhā śvāviḍgṛdhro mṛgādhipaḥ" },
      { type: "verse", number: "105", sanskrit: "तथैव शारिका न्यङ्कुर्हंसो रोहितकच्छपौ वर्त्मी चाग्र्याः स्ववर्गेषु प्रवरास्तेष्वपि स्मृताः", text: "tathaiva śārikā nyaṅkurhaṃso rohitakacchapau vartmī cāgryāḥ svavargeṣu pravarāsteṣvapi smṛtāḥ" },
      { type: "verse", number: "106", sanskrit: "लावैणगोधाः सिंहाश्च निन्दितो गौः सदर्दुरः ऋश्यः काणकपोतश्च शेषमुक्तं यथायथम्", text: "lāvaiṇagodhāḥ siṃhāśca nindito gauḥ sadarduraḥ ṛśyaḥ kāṇakapotaśca śeṣamuktaṃ yathāyatham" },
      { type: "verse", number: "107", sanskrit: "गुरूण्यण्डानि बालानां कषायमधुरं पलम् वृद्धानां स्नायुभूयिष्ठमबल्यं गुरुदोषलम्", text: "gurūṇyaṇḍāni bālānāṃ kaṣāyamadhuraṃ palam vṛddhānāṃ snāyubhūyiṣṭhamabalyaṃ gurudoṣalam" },
      { type: "verse", number: "108", sanskrit: "पुंस्त्रियोः पूर्वपश्चार्धे गुरुणी गर्भिणी गुरुः लघुर्योषिच्चतुष्पात्सु विहङ्गेषु पुनः पुमान्", text: "puṃstriyoḥ pūrvapaścārdhe guruṇī garbhiṇī guruḥ laghuryoṣiccatuṣpātsu vihaṅgeṣu punaḥ pumān" },
      { type: "verse", number: "109", sanskrit: "शिरस्कन्धोरुपृष्ठस्य कट्याः सक्थ्योश्च गौरवम् तथामपक्वाशययोर्यथापूर्वं विनिर्दिशेत्", text: "śiraskandhorupṛṣṭhasya kaṭyāḥ sakthyośca gauravam tathāmapakvāśayayoryathāpūrvaṃ vinirdiśet" },
      { type: "verse", number: "110", sanskrit: "शोणितप्रभृतीनां च धातूनामुत्तरोत्तरम् मांसात् गरीयो बृषणमेढ्रवृक्कयकृत्गुदम् इति मांसवर्गः", text: "śoṇitaprabhṛtīnāṃ ca dhātūnāmuttarottaram māṃsāt garīyo bṛṣaṇameḍhravṛkkayakṛtgudam iti māṃsavargaḥ" },
      { type: "verse", number: "111", sanskrit: "शाकं पाठाशटीश्रूषासुनिषण्डसतीनजम् त्रिदोषघ्नं लघु ग्राहि सराजक्षववास्तुकम्", text: "śākaṃ pāṭhāśaṭīśrūṣāsuniṣaṇḍasatīnajam tridoṣaghnaṃ laghu grāhi sarājakṣavavāstukam" },
      { type: "verse", number: "112", sanskrit: "सुनिषण्डो ऽग्निकृद्वृष्यस्तेषु राजक्षवः परम् ग्रहण्यर्शोविकारघ्नो वर्च्चोभेदी तु वास्तुकः", text: "suniṣaṇḍo 'gnikṛdvṛṣyasteṣu rājakṣavaḥ param grahaṇyarśovikāraghno varccobhedī tu vāstukaḥ" },
      { type: "verse", number: "113", sanskrit: "हन्ति दोषत्रयं कुष्ठं वृष्या सोष्णा रसायनी काकमाची सरा स्वर्या चाङ्गेर्यम्ला ऽग्निदीपनी", text: "hanti doṣatrayaṃ kuṣṭhaṃ vṛṣyā soṣṇā rasāyanī kākamācī sarā svaryā cāṅgeryamlā 'gnidīpanī" },
      { type: "verse", number: "114", sanskrit: "ग्रहण्यर्शो ऽनिलश्लेष्महितोष्णा ग्राहिणी लघुः पटोलसप्तलारिष्टशार्ङ्गाष्ठावल्गुजामृताः", text: "grahaṇyarśo 'nilaśleṣmahitoṣṇā grāhiṇī laghuḥ paṭolasaptalāriṣṭaśārṅgāṣṭhāvalgujāmṛtāḥ" },
      { type: "verse", number: "115", sanskrit: "वेत्राग्रबृहतीवाशाकुन्तलीतिलपर्णिकाः मण्डूकपर्णीकर्क्कोटकारवेल्लकपर्पटाः", text: "vetrāgrabṛhatīvāśākuntalītilaparṇikāḥ maṇḍūkaparṇīkarkkoṭakāravellakaparpaṭāḥ" },
      { type: "verse", number: "116", sanskrit: "नाडीकलायगोजिह्वावार्त्ताकवनतिक्तकम् करीरं कूलकं नन्दी कुवेला शकुलादनी", text: "nāḍīkalāyagojihvāvārttākavanatiktakam karīraṃ kūlakaṃ nandī kuvelā śakulādanī" },
      { type: "verse", number: "117", sanskrit: "कठिल्लं केम्बुकं शीतं सकोशातककर्क्कशम् तिक्तं पाके कटु ग्राहि वातलं कफपित्तजित्", text: "kaṭhillaṃ kembukaṃ śītaṃ sakośātakakarkkaśam tiktaṃ pāke kaṭu grāhi vātalaṃ kaphapittajit" },
      { type: "verse", number: "118", sanskrit: "हृद्यं पटोलं क्रिमिनुत् स्वादुपाकं रुचिप्रदम् पित्तलं दीपन भेदि वातघ्नं बृहतीद्वयम्", text: "hṛdyaṃ paṭolaṃ kriminut svādupākaṃ rucipradam pittalaṃ dīpana bhedi vātaghnaṃ bṛhatīdvayam" },
      { type: "verse", number: "119", sanskrit: "वृषं तु वमिकासघ्नं रक्तपित्तहरं परम् कारवेल्लं सकटुकं दीपनं कफपित्तजित्", text: "vṛṣaṃ tu vamikāsaghnaṃ raktapittaharaṃ param kāravellaṃ sakaṭukaṃ dīpanaṃ kaphapittajit" },
      { type: "verse", number: "120", sanskrit: "वार्त्ताकं कटुतिक्तोष्णं मधुरं कफवातजित् सक्षारमग्निजननं हृद्यं रुच्यमपित्तलम्", text: "vārttākaṃ kaṭutiktoṣṇaṃ madhuraṃ kaphavātajit sakṣāramagnijananaṃ hṛdyaṃ rucyamapittalam" },
      { type: "verse", number: "121", sanskrit: "करीरमाध्मानकरं कषायं स्वादुतिक्तकम् कोशातकावल्गुजकौ भेदिनावग्निदीपनौ", text: "karīramādhmānakaraṃ kaṣāyaṃ svādutiktakam kośātakāvalgujakau bhedināvagnidīpanau" },
      { type: "verse", number: "122", sanskrit: "श्यामाशाल्मलिकाश्मर्यभञ्जकीर्णकयूथिकाः वृक्षादिनीक्षीरवृक्षबिम्बीतनिकवृक्षकाः", text: "śyāmāśālmalikāśmaryabhañjakīrṇakayūthikāḥ vṛkṣādinīkṣīravṛkṣabimbītanikavṛkṣakāḥ" },
      { type: "verse", number: "123", sanskrit: "लोध्रः शणः कच्छुदारः सशेलुर्वृषमुष्टिका भल्लातकः कोविदारः कमलोत्पलकिंशुकम्", text: "lodhraḥ śaṇaḥ kacchudāraḥ saśelurvṛṣamuṣṭikā bhallātakaḥ kovidāraḥ kamalotpalakiṃśukam" },
      { type: "verse", number: "124", sanskrit: "पटोलादिगुणं स्वादु कषायं पित्तजित् परम् बद्धमूत्रा सरा भञ्जी करीरं स्यादभीरुजम्", text: "paṭolādiguṇaṃ svādu kaṣāyaṃ pittajit param baddhamūtrā sarā bhañjī karīraṃ syādabhīrujam" },
      { type: "verse", number: "125", sanskrit: "सतिक्तं लघु चक्षुष्यं वृष्यं दोषत्रयप्रणुत् तण्डुलीयो हिमो रूक्षः स्वादुपाकरसो लघु", text: "satiktaṃ laghu cakṣuṣyaṃ vṛṣyaṃ doṣatrayapraṇut taṇḍulīyo himo rūkṣaḥ svādupākaraso laghu" },
      { type: "verse", number: "126", sanskrit: "मदपित्तविषास्रघ्नो मुञ्जातं वातपित्तजित् स्निग्धं शीतं गुरु स्वादु बृंहणं शुक्रकृत् परम्", text: "madapittaviṣāsraghno muñjātaṃ vātapittajit snigdhaṃ śītaṃ guru svādu bṛṃhaṇaṃ śukrakṛt param" },
      { type: "verse", number: "127", sanskrit: "पालक्या पिछिला गुर्व्वी श्लेष्मला भेदिनी हिमा मदघ्न्युपोदका चुञ्चुर्ग्राही तौ पूर्ववत्तथा", text: "pālakyā pichilā gurvvī śleṣmalā bhedinī himā madaghnyupodakā cuñcurgrāhī tau pūrvavattathā" },
      { type: "verse", number: "128", sanskrit: "विदारी वातपित्तघ्नी मूत्रला स्वादुशीतला जीवनी बृंहणी कण्ठ्या गुर्वीवृष्या रसायनी", text: "vidārī vātapittaghnī mūtralā svāduśītalā jīvanī bṛṃhaṇī kaṇṭhyā gurvīvṛṣyā rasāyanī" },
      { type: "verse", number: "129", sanskrit: "चक्षुष्या सर्वदोषघ्नी जीवन्ती मधुरा हिमा शाकानां प्रवरा न्यूना द्वितीया किञ्चिदेव तु", text: "cakṣuṣyā sarvadoṣaghnī jīvantī madhurā himā śākānāṃ pravarā nyūnā dvitīyā kiñcideva tu" },
      { type: "verse", number: "130", sanskrit: "वातपित्तहरा भण्डी पर्वणी पर्वपुष्पिका कूष्माण्डतुम्बकालिङ्गकर्कारूर्वारुतिण्डिशम्", text: "vātapittaharā bhaṇḍī parvaṇī parvapuṣpikā kūṣmāṇḍatumbakāliṅgakarkārūrvārutiṇḍiśam" },
      { type: "verse", number: "131", sanskrit: "तथा त्रपुसचीनाकचिर्भिटं कफवातकृत् भेदि विष्टम्भ्यभिष्यन्दि स्वादुपाकरसं गुरु", text: "tathā trapusacīnākacirbhiṭaṃ kaphavātakṛt bhedi viṣṭambhyabhiṣyandi svādupākarasaṃ guru" },
      { type: "verse", number: "132", sanskrit: "वल्लीफलानां प्रवरं कूष्माण्डं वातपित्तजित् बस्तिशुद्धिकरं वृषं त्रपुसं त्वतिमूत्रलम्", text: "vallīphalānāṃ pravaraṃ kūṣmāṇḍaṃ vātapittajit bastiśuddhikaraṃ vṛṣaṃ trapusaṃ tvatimūtralam" },
      { type: "verse", number: "133", sanskrit: "तुम्बं रूक्षतरं ग्राहि कालिङ्गोर्वारुचिर्भिटम् बालं पित्तहरं शीतं विद्यात् पक्वमतो ऽन्यथा", text: "tumbaṃ rūkṣataraṃ grāhi kāliṅgorvārucirbhiṭam bālaṃ pittaharaṃ śītaṃ vidyāt pakvamato 'nyathā" },
      { type: "verse", number: "134", sanskrit: "शीर्णवृन्तं तु सक्षारं पित्तलं कफवातजित् रोचनं दीपनं हृद्यमष्ठीलानाहनुल्लघु", text: "śīrṇavṛntaṃ tu sakṣāraṃ pittalaṃ kaphavātajit rocanaṃ dīpanaṃ hṛdyamaṣṭhīlānāhanullaghu" },
      { type: "verse", number: "135", sanskrit: "मृणालबिसशालूकशृङ्गाटककशेरुकाः नन्दीमाषककेलूटक्रौञ्चादनकलोड्यकम्", text: "mṛṇālabisaśālūkaśṛṅgāṭakakaśerukāḥ nandīmāṣakakelūṭakrauñcādanakaloḍyakam" },
      { type: "verse", number: "136", sanskrit: "सतरूढं कदम्बं च रूक्षं ग्राहि हिमं गुरु कलम्बुनालिकामाषकठिञ्जरकुतुम्बकम्", text: "satarūḍhaṃ kadambaṃ ca rūkṣaṃ grāhi himaṃ guru kalambunālikāmāṣakaṭhiñjarakutumbakam" },
      { type: "verse", number: "137", sanskrit: "चिल्लीलट्वाकनिष्पावकुरूटकगवेधुकाः यातुका सालकल्याणी श्रीपर्णी पीलुपर्णिका", text: "cillīlaṭvākaniṣpāvakurūṭakagavedhukāḥ yātukā sālakalyāṇī śrīparṇī pīluparṇikā" },
      { type: "verse", number: "138", sanskrit: "कुमारी जीवलोणीका यवशाकसुवर्चलाः कुष्माण्डनीलिनी स्वर्चा वृकधूमकलक्ष्मणा", text: "kumārī jīvaloṇīkā yavaśākasuvarcalāḥ kuṣmāṇḍanīlinī svarcā vṛkadhūmakalakṣmaṇā" },
      { type: "verse", number: "139", sanskrit: "आलूपानि च सर्वाणि तथा सूप्यानि लक्ष्मणा जीवन्तिकश्चुञ्चुपर्णीप्रपुन्नाटकुबेरकम्", text: "ālūpāni ca sarvāṇi tathā sūpyāni lakṣmaṇā jīvantikaścuñcuparṇīprapunnāṭakuberakam" },
      { type: "verse", number: "140", sanskrit: "स्वादु रूक्षं सलवणं वातश्लेष्मकरं गुरु शीतलं सृष्टविण्मूत्रं प्रायो विष्टभ्य जीर्यति", text: "svādu rūkṣaṃ salavaṇaṃ vātaśleṣmakaraṃ guru śītalaṃ sṛṣṭaviṇmūtraṃ prāyo viṣṭabhya jīryati" },
      { type: "verse", number: "141", sanskrit: "स्विन्नं निष्पीडितरसं स्नेहाढ्यं नातिदोषलम् लघुपत्रा तु या चिल्ली सा वास्तुकसमा मता", text: "svinnaṃ niṣpīḍitarasaṃ snehāḍhyaṃ nātidoṣalam laghupatrā tu yā cillī sā vāstukasamā matā" },
      { type: "verse", number: "142", sanskrit: "तक्कारी वरणं स्वादु सतिक्तं कफवातजित् वर्षाभ्वौ कालशाकं च सक्षारं कटुतिक्तकम्", text: "takkārī varaṇaṃ svādu satiktaṃ kaphavātajit varṣābhvau kālaśākaṃ ca sakṣāraṃ kaṭutiktakam" },
      { type: "verse", number: "143", sanskrit: "दीपनं भेदनं हन्ति गरशोफकफानिलान् दीपनाः कफवातघ्नाश्चिरिबिल्वाङ्कुराः सराः", text: "dīpanaṃ bhedanaṃ hanti garaśophakaphānilān dīpanāḥ kaphavātaghnāściribilvāṅkurāḥ sarāḥ" },
      { type: "verse", number: "144", sanskrit: "लघुरुष्णा सरा तिक्ता सोरुपूका च लाङ्गली वातलौ कटुतिक्ताम्लौ भेदिनौ तिलवेतसौ", text: "laghuruṣṇā sarā tiktā sorupūkā ca lāṅgalī vātalau kaṭutiktāmlau bhedinau tilavetasau" },
      { type: "verse", number: "145", sanskrit: "तद्वत् पञ्चाङ्गुलो वंशकरीरास्तु विदाहिनः वातपित्तकरा रूक्षाः कटुपाकाः कफापहाः", text: "tadvat pañcāṅgulo vaṃśakarīrāstu vidāhinaḥ vātapittakarā rūkṣāḥ kaṭupākāḥ kaphāpahāḥ" },
      { type: "verse", number: "146", sanskrit: "बिल्वरास्नाबलाशाकं वातघ्नमतिसारजित् वायुं वत्सादनी हन्यात् कफं गण्डीरचित्रकौ", text: "bilvarāsnābalāśākaṃ vātaghnamatisārajit vāyuṃ vatsādanī hanyāt kaphaṃ gaṇḍīracitrakau" },
      { type: "verse", number: "147", sanskrit: "पत्तूरो दीपनस्तिक्तः प्लीहार्शःकफवातजित् क्रिमिकासकफोत्क्लेदान् कासमर्दो जयेत् सरः", text: "pattūro dīpanastiktaḥ plīhārśaḥkaphavātajit krimikāsakaphotkledān kāsamardo jayet saraḥ" },
      { type: "verse", number: "148", sanskrit: "रूक्षोष्णमम्लं कौसुम्भं गुरु पित्तकरं सरम् सक्षारं मधुरं स्निग्धमुष्णं गुरु च सार्षपम्", text: "rūkṣoṣṇamamlaṃ kausumbhaṃ guru pittakaraṃ saram sakṣāraṃ madhuraṃ snigdhamuṣṇaṃ guru ca sārṣapam" },
      { type: "verse", number: "149", sanskrit: "शाकानामवरं बद्धविण्मूत्रं सर्वदोषकृत् यद्बालमव्यक्तरसं किंचित्क्षारं सतिक्तकम्", text: "śākānāmavaraṃ baddhaviṇmūtraṃ sarvadoṣakṛt yadbālamavyaktarasaṃ kiṃcitkṣāraṃ satiktakam" },
      { type: "verse", number: "150", sanskrit: "तन्मूलकं दोषहरं लघु सोष्णं नियच्छति गुल्मकासक्षयश्वासव्रणनेत्रगलामयान्", text: "tanmūlakaṃ doṣaharaṃ laghu soṣṇaṃ niyacchati gulmakāsakṣayaśvāsavraṇanetragalāmayān" },
      { type: "verse", number: "151", sanskrit: "स्वरग्निसादोदावर्तपीनसांश्च महत् पुनः गुरूष्णकटुकं स्वादुविपाकं सर्वदोषकृत्", text: "svaragnisādodāvartapīnasāṃśca mahat punaḥ gurūṣṇakaṭukaṃ svāduvipākaṃ sarvadoṣakṛt" },
      { type: "verse", number: "152", sanskrit: "गुर्वभिष्यन्दि च स्निग्धसिद्धं तदपि वातजित् वातश्लेष्महरं शुष्कं सर्वमामं तु दोषलम्", text: "gurvabhiṣyandi ca snigdhasiddhaṃ tadapi vātajit vātaśleṣmaharaṃ śuṣkaṃ sarvamāmaṃ tu doṣalam" },
      { type: "verse", number: "153", sanskrit: "कटूष्णो वातकफहा पिण्डालुः पित्तवर्धनः कुठेरशिग्रुसुरससुमुखासुरिभूस्तृणाः", text: "kaṭūṣṇo vātakaphahā piṇḍāluḥ pittavardhanaḥ kuṭheraśigrusurasasumukhāsuribhūstṛṇāḥ" },
      { type: "verse", number: "154", sanskrit: "धान्यतुम्बुरुशैलेययवानीशृङ्गिवेरकाः पर्णासो गृञ्जनो ऽजाजी जीरकं गजपिप्पली", text: "dhānyatumburuśaileyayavānīśṛṅgiverakāḥ parṇāso gṛñjano 'jājī jīrakaṃ gajapippalī" },
      { type: "verse", number: "155", sanskrit: "फणिर्जार्जकजम्बीरखराह्वाकालमालिकाः दीप्यकः क्षवकद्वीपिबस्तगन्धादि बद्धविट्", text: "phaṇirjārjakajambīrakharāhvākālamālikāḥ dīpyakaḥ kṣavakadvīpibastagandhādi baddhaviṭ" },
      { type: "verse", number: "156", sanskrit: "रसे पाके च कटुकं दोषोत्क्लेशकरं लघु विदाहि रूक्षतीक्ष्णोष्णं दृक्शुक्रक्रिमिनाशनम्", text: "rase pāke ca kaṭukaṃ doṣotkleśakaraṃ laghu vidāhi rūkṣatīkṣṇoṣṇaṃ dṛkśukrakrimināśanam" },
      { type: "verse", number: "157", sanskrit: "वर्गो हरितकाख्यो ऽयमुपदंशेषु युज्यते वासनो व्यञ्जनानां च हृद्यो दीपनरोचनः", text: "vargo haritakākhyo 'yamupadaṃśeṣu yujyate vāsano vyañjanānāṃ ca hṛdyo dīpanarocanaḥ" },
      { type: "verse", number: "158", sanskrit: "हिध्माकासविषश्वासपार्श्वरुक्पूतिगन्धहा सुरसः सुमुखः शोफगन्धहा धानका पुनः", text: "hidhmākāsaviṣaśvāsapārśvarukpūtigandhahā surasaḥ sumukhaḥ śophagandhahā dhānakā punaḥ" },
      { type: "verse", number: "159", sanskrit: "कषायतिक्तमधुरा मूत्रला न च पित्तकृत् खराह्वा बस्तिशूलघ्नी चित्रको दीपनः परम्", text: "kaṣāyatiktamadhurā mūtralā na ca pittakṛt kharāhvā bastiśūlaghnī citrako dīpanaḥ param" },
      { type: "verse", number: "160", sanskrit: "पत्रे सक्षारमधुरो मध्ये मधुरपिच्छिलः तीक्ष्णोष्णो लशुनः कन्दे कटुपाकरसः सरः", text: "patre sakṣāramadhuro madhye madhurapicchilaḥ tīkṣṇoṣṇo laśunaḥ kande kaṭupākarasaḥ saraḥ" },
      { type: "verse", number: "161", sanskrit: "हृद्यः केश्यो गुरुर्वृष्यः स्निग्धो रोचनदीपनः भग्नसन्धानकृत् बल्यो रक्तपित्तप्रदूषणः", text: "hṛdyaḥ keśyo gururvṛṣyaḥ snigdho rocanadīpanaḥ bhagnasandhānakṛt balyo raktapittapradūṣaṇaḥ" },
      { type: "verse", number: "162", sanskrit: "किलासकुष्ठगुल्मार्शोमेहक्रिमिकफानिलान् सहिध्मापीनसश्वासकासान् हन्ति रसायनम्", text: "kilāsakuṣṭhagulmārśomehakrimikaphānilān sahidhmāpīnasaśvāsakāsān hanti rasāyanam" },
      { type: "verse", number: "163", sanskrit: "पलाण्डुस्तद्गुणैर्न्यूनो विपाके मधुरस्तु सः कफं करोति नो पित्तं केवलानिलनाशनः", text: "palāṇḍustadguṇairnyūno vipāke madhurastu saḥ kaphaṃ karoti no pittaṃ kevalānilanāśanaḥ" },
      { type: "verse", number: "164", sanskrit: "दीपनः सूरणो रुच्यः कफघ्नो विशदो लघुः विशेषादर्शसां पथ्यो भूकन्दस्त्वतिदोषलः", text: "dīpanaḥ sūraṇo rucyaḥ kaphaghno viśado laghuḥ viśeṣādarśasāṃ pathyo bhūkandastvatidoṣalaḥ" },
      { type: "verse", number: "165", sanskrit: "पत्रे पुष्पे फले कन्दे च गुरुता क्रमात् वरा शाकेषु जीवन्ती सार्षपस्त्ववराः परम् इति शाकवर्गः", text: "patre puṣpe phale kande ca gurutā kramāt varā śākeṣu jīvantī sārṣapastvavarāḥ param iti śākavargaḥ" },
      { type: "verse", number: "166", sanskrit: "द्राक्षा फलोत्तमा वृष्या चक्षुष्या सृष्टमूत्रविट् स्वादुपाकरसा स्निग्धा सकषाया हिमा गुरुः", text: "drākṣā phalottamā vṛṣyā cakṣuṣyā sṛṣṭamūtraviṭ svādupākarasā snigdhā sakaṣāyā himā guruḥ" },
      { type: "verse", number: "167", sanskrit: "निहन्त्यनिलपित्तास्रतिक्तास्यत्वमदात्ययान् तृष्णाकासज्वरश्वासस्वरभेदक्षतक्षयान्", text: "nihantyanilapittāsratiktāsyatvamadātyayān tṛṣṇākāsajvaraśvāsasvarabhedakṣatakṣayān" },
      { type: "verse", number: "168", sanskrit: "उद्रिक्तपित्तान् जयति त्रिदोषान् स्वादु दाडिमम् पित्ताविरोधि नात्युष्णमम्लं वातकफापहम्", text: "udriktapittān jayati tridoṣān svādu dāḍimam pittāvirodhi nātyuṣṇamamlaṃ vātakaphāpaham" },
      { type: "verse", number: "169", sanskrit: "सर्वं हृद्यं लघु स्निग्धं ग्राहि रोचनदीपनम् मोचखर्जूरपनसनालिकेरपरूषकम्", text: "sarvaṃ hṛdyaṃ laghu snigdhaṃ grāhi rocanadīpanam mocakharjūrapanasanālikeraparūṣakam" },
      { type: "verse", number: "170", sanskrit: "आम्राततालकाश्मर्यराजादनमधूकजम् सौवीरबदराङ्कोलफल्गुश्लेष्मातकोद्भवम्", text: "āmrātatālakāśmaryarājādanamadhūkajam sauvīrabadarāṅkolaphalguśleṣmātakodbhavam" },
      { type: "verse", number: "171", sanskrit: "वातामाभिषुकाक्षोडमुकूलकनिकोचकम् ऊरुमाणं प्रियालं च बृंहणं गुरु शीतलम्", text: "vātāmābhiṣukākṣoḍamukūlakanikocakam ūrumāṇaṃ priyālaṃ ca bṛṃhaṇaṃ guru śītalam" },
      { type: "verse", number: "172", sanskrit: "दाहक्षतक्षयहरं रक्तपित्तप्रसादनम् स्वादुपाकरसां स्निग्धं विष्टम्भि कफशुक्रकृत्", text: "dāhakṣatakṣayaharaṃ raktapittaprasādanam svādupākarasāṃ snigdhaṃ viṣṭambhi kaphaśukrakṛt" },
      { type: "verse", number: "173", sanskrit: "नालिकेरं गुरु स्निग्धं पित्तघ्नं स्वादु शीतलम् बलमांसकरं हृद्यं बृंहणं बस्तिशोधनम्", text: "nālikeraṃ guru snigdhaṃ pittaghnaṃ svādu śītalam balamāṃsakaraṃ hṛdyaṃ bṛṃhaṇaṃ bastiśodhanam" },
      { type: "verse", number: "174", sanskrit: "मोचं स्वादुरसं प्रोक्तं कषायं नातिशीतलम् रक्तपित्तहरं वृष्यं रुच्यं श्लेष्मकरं गुरु", text: "mocaṃ svādurasaṃ proktaṃ kaṣāyaṃ nātiśītalam raktapittaharaṃ vṛṣyaṃ rucyaṃ śleṣmakaraṃ guru" },
      { type: "verse", number: "175", sanskrit: "स्निग्धं स्वादु कषायं च राजादनफलं गुरु फलं तु पित्तलं तालं सरं काश्मर्यजं हिमम्", text: "snigdhaṃ svādu kaṣāyaṃ ca rājādanaphalaṃ guru phalaṃ tu pittalaṃ tālaṃ saraṃ kāśmaryajaṃ himam" },
      { type: "verse", number: "176", sanskrit: "शकृन्मूत्रविबन्धघ्नं केश्यं मेध्यं रसायनम् मधूकजमहृद्यं तु बदरं सरणात्मकम्", text: "śakṛnmūtravibandhaghnaṃ keśyaṃ medhyaṃ rasāyanam madhūkajamahṛdyaṃ tu badaraṃ saraṇātmakam" },
      { type: "verse", number: "177", sanskrit: "वातामाद्युष्णवीर्यं तु कफपित्तकरं सरम् परं वातहरं स्निग्धमनुष्णं तु प्रियालजम्", text: "vātāmādyuṣṇavīryaṃ tu kaphapittakaraṃ saram paraṃ vātaharaṃ snigdhamanuṣṇaṃ tu priyālajam" },
      { type: "verse", number: "178", sanskrit: "प्रियालमज्जा मधुरो वृष्यः पित्तानिलापहः कोलमज्जा गुणैस्तद्वत्तृट्छर्दिःकासजिच्च सः", text: "priyālamajjā madhuro vṛṣyaḥ pittānilāpahaḥ kolamajjā guṇaistadvattṛṭchardiḥkāsajicca saḥ" },
      { type: "verse", number: "179", sanskrit: "तिन्दुकाश्मन्तकासीनफलिनीबिम्बितोदनम् टङ्काश्वकर्णबकुलगाङ्गेरुधवधन्वनम्", text: "tindukāśmantakāsīnaphalinībimbitodanam ṭaṅkāśvakarṇabakulagāṅgerudhavadhanvanam" },
      { type: "verse", number: "180", sanskrit: "श्वेतपाककपित्थानि सिञ्चतीभव्यजाम्बवम् क्षीरिवृक्षभवं बीजं पौष्करं कफपित्तजित्", text: "śvetapākakapitthāni siñcatībhavyajāmbavam kṣīrivṛkṣabhavaṃ bījaṃ pauṣkaraṃ kaphapittajit" },
      { type: "verse", number: "181", sanskrit: "कषायमधुरं रूक्षं शीतलं गुरु लेखनम् विबन्धाध्मानजननं स्तम्भनं वातकोपनम्", text: "kaṣāyamadhuraṃ rūkṣaṃ śītalaṃ guru lekhanam vibandhādhmānajananaṃ stambhanaṃ vātakopanam" },
      { type: "verse", number: "182", sanskrit: "कपित्थमामं कण्ठघ्नं कषायाम्लं त्रिदोषकृत् पक्वं रुच्यं कषायाम्लं स्वादु हिध्मावमिप्रणुत्", text: "kapitthamāmaṃ kaṇṭhaghnaṃ kaṣāyāmlaṃ tridoṣakṛt pakvaṃ rucyaṃ kaṣāyāmlaṃ svādu hidhmāvamipraṇut" },
      { type: "verse", number: "183", sanskrit: "दोषघ्नं षाडवारिष्टरागयुक्तिषु पूजितम् विषघ्नमुभयं ग्राहि कपित्थान्येवमादिशेत्", text: "doṣaghnaṃ ṣāḍavāriṣṭarāgayuktiṣu pūjitam viṣaghnamubhayaṃ grāhi kapitthānyevamādiśet" },
      { type: "verse", number: "184", sanskrit: "बृंहणं वातपित्तघ्नं स्निग्धं सिञ्चतिकाफलम् भव्यं विशदमम्लं च जाम्बवं त्वतिवातलम्", text: "bṛṃhaṇaṃ vātapittaghnaṃ snigdhaṃ siñcatikāphalam bhavyaṃ viśadamamlaṃ ca jāmbavaṃ tvativātalam" },
      { type: "verse", number: "185", sanskrit: "विष्टम्भकृदकण्ठ्यं च साम्लं तु क्षीरिवृक्षजम् पित्तश्लेष्मघ्नमम्लं च वातलं चाक्षकीफलम्", text: "viṣṭambhakṛdakaṇṭhyaṃ ca sāmlaṃ tu kṣīrivṛkṣajam pittaśleṣmaghnamamlaṃ ca vātalaṃ cākṣakīphalam" },
      { type: "verse", number: "186", sanskrit: "बालं कषायकट्वम्लं रूक्षं वातास्रपित्तकृत् संपूर्णमाम्रमम्लं तु रक्तपित्तकफप्रदम्", text: "bālaṃ kaṣāyakaṭvamlaṃ rūkṣaṃ vātāsrapittakṛt saṃpūrṇamāmramamlaṃ tu raktapittakaphapradam" },
      { type: "verse", number: "187", sanskrit: "स्वादु साम्लं गुरु स्निग्धं मारुतघ्नमपित्तलम् हृद्यं पर्यागतं श्लेष्ममांसशुक्रबलप्रदम्", text: "svādu sāmlaṃ guru snigdhaṃ mārutaghnamapittalam hṛdyaṃ paryāgataṃ śleṣmamāṃsaśukrabalapradam" },
      { type: "verse", number: "188", sanskrit: "सहकाररसो हृद्यः सुरभिस्निग्धरोचनः दीपनः पित्तवातघ्नः शुक्रशोणितशुद्धिकृत्", text: "sahakāraraso hṛdyaḥ surabhisnigdharocanaḥ dīpanaḥ pittavātaghnaḥ śukraśoṇitaśuddhikṛt" },
      { type: "verse", number: "189", sanskrit: "कषायं रोचनं हृद्यं वातलं लवलीफलम् गुर्वग्निसादकृद्विल्वं दोषलं पूतिमारुतम्", text: "kaṣāyaṃ rocanaṃ hṛdyaṃ vātalaṃ lavalīphalam gurvagnisādakṛdvilvaṃ doṣalaṃ pūtimārutam" },
      { type: "verse", number: "190", sanskrit: "पक्वं बालं पुनस्तीक्ष्णं पित्तलं लघु दीपनम् वातश्लेष्मघ्नमुष्णं च स्निग्धं ग्राह्युभयं परम्", text: "pakvaṃ bālaṃ punastīkṣṇaṃ pittalaṃ laghu dīpanam vātaśleṣmaghnamuṣṇaṃ ca snigdhaṃ grāhyubhayaṃ param" },
      { type: "verse", number: "191", sanskrit: "वृक्षाम्लं ग्राहि रूक्षोष्णं लघु दीपनरोचनम् वातश्लेष्महरं किञ्चिदूनं कोशाम्लम्जं ततः", text: "vṛkṣāmlaṃ grāhi rūkṣoṣṇaṃ laghu dīpanarocanam vātaśleṣmaharaṃ kiñcidūnaṃ kośāmlamjaṃ tataḥ" },
      { type: "verse", number: "192", sanskrit: "फलं करञ्जं विष्टम्भि पित्तश्लेष्माविरोधि च गुरुष्णमधुरं रूक्षं केशघ्नं च शमीफलम्", text: "phalaṃ karañjaṃ viṣṭambhi pittaśleṣmāvirodhi ca guruṣṇamadhuraṃ rūkṣaṃ keśaghnaṃ ca śamīphalam" },
      { type: "verse", number: "193", sanskrit: "कटुपाकरसं पीलु तीक्ष्णोष्णं भेदि पित्तलम् क्रिमिगुल्मोदरगरप्लीहार्शःकफवातजित्", text: "kaṭupākarasaṃ pīlu tīkṣṇoṣṇaṃ bhedi pittalam krimigulmodaragaraplīhārśaḥkaphavātajit" },
      { type: "verse", number: "194", sanskrit: "सतिक्तं स्वादु यत् पीलु नात्युष्णं तत्त्रिदोषजित् नीपं शताक्षिकं प्राचीनागरं तृणशूल्यजम्", text: "satiktaṃ svādu yat pīlu nātyuṣṇaṃ tattridoṣajit nīpaṃ śatākṣikaṃ prācīnāgaraṃ tṛṇaśūlyajam" },
      { type: "verse", number: "195", sanskrit: "अस्मादल्पान्तरगुणमैङ्गुदं सविकङ्कतम् त्वक्तिक्तकटुका स्निग्धा मातुलुङ्गस्य वातजित्", text: "asmādalpāntaraguṇamaiṅgudaṃ savikaṅkatam tvaktiktakaṭukā snigdhā mātuluṅgasya vātajit" },
      { type: "verse", number: "196", sanskrit: "बृंहणं मधुरं मांसं वातपित्तहरं गुरु लघु तत्केसरं कासश्वासहिध्मामदात्ययान्", text: "bṛṃhaṇaṃ madhuraṃ māṃsaṃ vātapittaharaṃ guru laghu tatkesaraṃ kāsaśvāsahidhmāmadātyayān" },
      { type: "verse", number: "197", sanskrit: "आस्यशोषानिलश्लेष्मविबन्धच्छर्द्यरोचकान् गुल्मोदरार्शःशूलानि मन्दाग्नित्वं च नाशयेत्", text: "āsyaśoṣānilaśleṣmavibandhacchardyarocakān gulmodarārśaḥśūlāni mandāgnitvaṃ ca nāśayet" },
      { type: "verse", number: "198", sanskrit: "भल्लातकस्य त्वङ्मांसं बृंहणं स्वादु शीतलम् तदस्थ्यग्निसमं मेध्यं कफवातहरं परम्", text: "bhallātakasya tvaṅmāṃsaṃ bṛṃhaṇaṃ svādu śītalam tadasthyagnisamaṃ medhyaṃ kaphavātaharaṃ param" },
      { type: "verse", number: "199", sanskrit: "स्वाद्वम्लं शीतमुष्णं च द्विधा पारावतं गुरु रुच्यमत्यग्निशमनं रुच्यं मधुरमारुकम्", text: "svādvamlaṃ śītamuṣṇaṃ ca dvidhā pārāvataṃ guru rucyamatyagniśamanaṃ rucyaṃ madhuramārukam" },
      { type: "verse", number: "200", sanskrit: "पक्वमाशु जरां याति नात्युष्णं गुरु दोषलम् द्राक्षापरूषकं चार्द्रमम्लं पित्तकफप्रदम्", text: "pakvamāśu jarāṃ yāti nātyuṣṇaṃ guru doṣalam drākṣāparūṣakaṃ cārdramamlaṃ pittakaphapradam" },
      { type: "verse", number: "201", sanskrit: "गुरूष्णवीर्यं वातघ्नं सरं सकरमर्दकम् तथाम्लं कोलकर्कन्धुलिकुचाम्रातकारुकम्", text: "gurūṣṇavīryaṃ vātaghnaṃ saraṃ sakaramardakam tathāmlaṃ kolakarkandhulikucāmrātakārukam" },
      { type: "verse", number: "202", sanskrit: "ऐरावतं दन्तशठं सत्रुदं मृगलण्डिकम् नातिपित्तकरं पक्वं शुष्कं च करमर्दकम्", text: "airāvataṃ dantaśaṭhaṃ satrudaṃ mṛgalaṇḍikam nātipittakaraṃ pakvaṃ śuṣkaṃ ca karamardakam" },
      { type: "verse", number: "203", sanskrit: "दीपनं भेदनंशुष्कमम्लिकाङ्कोलयोः फलम् तृष्णाश्रमक्लमच्छेदि लघ्विष्टं कफवातयोः", text: "dīpanaṃ bhedanaṃśuṣkamamlikāṅkolayoḥ phalam tṛṣṇāśramaklamacchedi laghviṣṭaṃ kaphavātayoḥ" },
      { type: "verse", number: "204", sanskrit: "फलानावरं तत्र लिकुचं सर्वदोषकृत् हिमानिलोष्णदुर्वातव्याललालादिदूषितम्", text: "phalānāvaraṃ tatra likucaṃ sarvadoṣakṛt himāniloṣṇadurvātavyālalālādidūṣitam" },
      { type: "verse", number: "205", sanskrit: "जन्तुजुष्टं जले मग्नमभूमिजमनार्तवम् अन्यधान्ययुतं हीनवीर्यं जीर्णतया ऽति च", text: "jantujuṣṭaṃ jale magnamabhūmijamanārtavam anyadhānyayutaṃ hīnavīryaṃ jīrṇatayā 'ti ca" },
      { type: "verse", number: "206", sanskrit: "धान्यं त्यजेत्तथा शाकं रूक्षसिद्धमकोमलम् असञ्जातरसं तद्वच्छुष्कं चान्यत्र मूलकात्", text: "dhānyaṃ tyajettathā śākaṃ rūkṣasiddhamakomalam asañjātarasaṃ tadvacchuṣkaṃ cānyatra mūlakāt" },
      { type: "verse", number: "207", sanskrit: "प्रायेण फलमप्येवं तथामं बिल्ववर्जितम् इति फलवर्गः शूकशिम्बिजपक्वान्नमांसशाकफलाश्रयैः", text: "prāyeṇa phalamapyevaṃ tathāmaṃ bilvavarjitam iti phalavargaḥ śūkaśimbijapakvānnamāṃsaśākaphalāśrayaiḥ" },
      { type: "verse", number: "208", sanskrit: "वर्गैरन्नैकदेशो ऽयं भूयिष्ठमुपयोगवान् निर्दिष्टो रसवीर्याद्यैर्थयथास्वं कर्मसाधने", text: "vargairannaikadeśo 'yaṃ bhūyiṣṭhamupayogavān nirdiṣṭo rasavīryādyairthayathāsvaṃ karmasādhane" },
      { type: "verse", number: "209", sanskrit: "न शक्यं विस्तरेणापि वक्तुं सर्वं तु सर्वथा हिताहितत्वे ऽप्येकान्तनियमो ऽस्मादनिश्चितः", text: "na śakyaṃ vistareṇāpi vaktuṃ sarvaṃ tu sarvathā hitāhitatve 'pyekāntaniyamo 'smādaniścitaḥ" },
      { type: "verse", number: "210", sanskrit: "मात्रायोगक्रियादेशकालावस्थादिभेदतः ततस्ततो यतो दृष्टास्ते ते भावास्तथा तथा", text: "mātrāyogakriyādeśakālāvasthādibhedataḥ tatastato yato dṛṣṭāste te bhāvāstathā tathā" },
      { type: "verse", number: "211", sanskrit: "मात्रया सेवितं मद्यं हन्ति रोगास्तदुद्भवान् निषेव्यमाणं तिलशो विषमप्यमृतायते", text: "mātrayā sevitaṃ madyaṃ hanti rogāstadudbhavān niṣevyamāṇaṃ tilaśo viṣamapyamṛtāyate" },
      { type: "verse", number: "212", sanskrit: "हीनातिमात्रमशनं मरुन्निचयकोपनम् भजतो विषरूपत्वं तुल्यांशे मधुसर्पिषी", text: "hīnātimātramaśanaṃ marunnicayakopanam bhajato viṣarūpatvaṃ tulyāṃśe madhusarpiṣī" },
      { type: "verse", number: "213", sanskrit: "क्षारो ऽम्लरससंयोगे मधुरीभवति क्षणात् उत्तुण्डक्यास्तिन्दुकेन तिक्तता मधुरायते", text: "kṣāro 'mlarasasaṃyoge madhurībhavati kṣaṇāt uttuṇḍakyāstindukena tiktatā madhurāyate" },
      { type: "verse", number: "214", sanskrit: "हिङ्गुगैरिकसिन्धूत्थं गन्धवर्णरसाधिकम् पूगताम्बूलशङ्खेभ्यो वर्णगन्धरसोद्भवः", text: "hiṅgugairikasindhūtthaṃ gandhavarṇarasādhikam pūgatāmbūlaśaṅkhebhyo varṇagandharasodbhavaḥ" },
      { type: "verse", number: "215", sanskrit: "कोद्रवो हन्त्यसृक्पित्तं करोत्येव विदाहिभिः कुष्ठं तत्कार्यपि तिलो हन्ति भल्लातकैः सह", text: "kodravo hantyasṛkpittaṃ karotyeva vidāhibhiḥ kuṣṭhaṃ tatkāryapi tilo hanti bhallātakaiḥ saha" },
      { type: "verse", number: "216", sanskrit: "गुडः कर्ताग्निसादस्य स हिनस्त्यभयादिभिः तृष्यत्यग्नेः समदनं सर्पिरप्युपदिश्यते", text: "guḍaḥ kartāgnisādasya sa hinastyabhayādibhiḥ tṛṣyatyagneḥ samadanaṃ sarpirapyupadiśyate" },
      { type: "verse", number: "217", sanskrit: "जीवनीयमपि क्षीरं विषलेशेन मृत्यवे तुल्ये अपि हतो ऽन्यो ऽन्यं विषे स्थावरजङ्गमे", text: "jīvanīyamapi kṣīraṃ viṣaleśena mṛtyave tulye api hato 'nyo 'nyaṃ viṣe sthāvarajaṅgame" },
      { type: "verse", number: "218", sanskrit: "सक्तवो वातला रूक्षाः पीतास्ते तर्पयन्ति तु विनापि चोपयोगेन मणिमन्त्रादि कार्यकृत्", text: "saktavo vātalā rūkṣāḥ pītāste tarpayanti tu vināpi copayogena maṇimantrādi kāryakṛt" },
      { type: "verse", number: "219", sanskrit: "आर्द्रकाज्जायते शुण्ठी संस्कारेण लघीयसी लघुभ्यो ऽपि हि सक्तुभ्यो गुरवः सिद्धापिण्डिकाः", text: "ārdrakājjāyate śuṇṭhī saṃskāreṇa laghīyasī laghubhyo 'pi hi saktubhyo guravaḥ siddhāpiṇḍikāḥ" },
      { type: "verse", number: "220", sanskrit: "भृष्टः क्षुण्णो ऽपि पृथुको रक्तशालेर्लघोर्गुरुः शालिः पिष्टो गरीयस्त्वं गोधूमादपि गच्छति", text: "bhṛṣṭaḥ kṣuṇṇo 'pi pṛthuko raktaśālerlaghorguruḥ śāliḥ piṣṭo garīyastvaṃ godhūmādapi gacchati" },
      { type: "verse", number: "221", sanskrit: "लघु पित्तहरा लाजा व्रीहितो गुरुपित्तलात् सङ्ग्राहिणो लघोर्मुद्गात् कुल्माषो भेदनो गुरुः", text: "laghu pittaharā lājā vrīhito gurupittalāt saṅgrāhiṇo laghormudgāt kulmāṣo bhedano guruḥ" },
      { type: "verse", number: "222", sanskrit: "आमं ग्राहितरं तक्रं नागरीकृतमार्द्रकम् गुडात्तोयाच्च सुतरां मूत्रलं गुरु पानकम्", text: "āmaṃ grāhitaraṃ takraṃ nāgarīkṛtamārdrakam guḍāttoyācca sutarāṃ mūtralaṃ guru pānakam" },
      { type: "verse", number: "223", sanskrit: "गरीयो गुडदध्युत्था रसाला चातिशुक्रला दण्डाभिमथनाद्दध्नो गुरुणश्चातिशोफदात्", text: "garīyo guḍadadhyutthā rasālā cātiśukralā daṇḍābhimathanāddadhno guruṇaścātiśophadāt" },
      { type: "verse", number: "224", sanskrit: "अनुद्धृतस्नेहमपि तक्रं शोफहरं लघु सर्पिः स्निग्धतरं हन्ति नार्दितं नवनीतवत्", text: "anuddhṛtasnehamapi takraṃ śophaharaṃ laghu sarpiḥ snigdhataraṃ hanti nārditaṃ navanītavat" },
      { type: "verse", number: "225", sanskrit: "चक्षुष्यो ऽपि हि गोधूमस्तैलपक्वस्तु दृष्टिहा मूलकं दोषजननं सिद्धं तु तददोषलम्", text: "cakṣuṣyo 'pi hi godhūmastailapakvastu dṛṣṭihā mūlakaṃ doṣajananaṃ siddhaṃ tu tadadoṣalam" },
      { type: "verse", number: "226", sanskrit: "उष्णं विषीभवत्येव विषघ्नमपि माक्षिकम् दुर्भाजनस्था द्राक्षाम्ला दोषला च प्रजायते", text: "uṣṇaṃ viṣībhavatyeva viṣaghnamapi mākṣikam durbhājanasthā drākṣāmlā doṣalā ca prajāyate" },
      { type: "verse", number: "227", sanskrit: "श्लक्ष्णशुष्कघनो लेपश्चन्दनस्यापि दाहकृत् त्वग्गतस्योष्मणो रोधाच्छीतकृत्त्वन्यथा ऽगुरोः", text: "ślakṣṇaśuṣkaghano lepaścandanasyāpi dāhakṛt tvaggatasyoṣmaṇo rodhācchītakṛttvanyathā 'guroḥ" },
      { type: "verse", number: "228", sanskrit: "मेध्यस्तिलः स्पर्शशीतो मेध्यं तैलं खलो हिमः तस्यैव श्लेष्मकारित्वं न तैलस्य खलस्य वा", text: "medhyastilaḥ sparśaśīto medhyaṃ tailaṃ khalo himaḥ tasyaiva śleṣmakāritvaṃ na tailasya khalasya vā" },
      { type: "verse", number: "229", sanskrit: "दध्नि श्वयथुकारित्वं न तक्रनवनीतयोः भूमिसात्म्यं दधिक्षीरकरीरं मरुवासिषु", text: "dadhni śvayathukāritvaṃ na takranavanītayoḥ bhūmisātmyaṃ dadhikṣīrakarīraṃ maruvāsiṣu" },
      { type: "verse", number: "230", sanskrit: "क्षारः प्राच्येषु मत्स्यास्तु सैन्धवेष्वश्मकेषु तु तैलाम्लः कन्दमूलानि मलये कोङ्कणे पुनः", text: "kṣāraḥ prācyeṣu matsyāstu saindhaveṣvaśmakeṣu tu tailāmlaḥ kandamūlāni malaye koṅkaṇe punaḥ" },
      { type: "verse", number: "231", sanskrit: "पेयामन्थ उदीच्येषु गोधूमो ऽवन्तिभूमिषु बाल्हीका बाल्हवाश्चीनाः शूलिका यवनाः शकाः", text: "peyāmantha udīcyeṣu godhūmo 'vantibhūmiṣu bālhīkā bālhavāścīnāḥ śūlikā yavanāḥ śakāḥ" },
      { type: "verse", number: "232", sanskrit: "मांसगोधूममार्द्वीकशस्त्रवैश्वानरोचिताः देहसात्म्यं घृतं क्षीरं मद्यं मासं च कस्यचित्", text: "māṃsagodhūmamārdvīkaśastravaiśvānarocitāḥ dehasātmyaṃ ghṛtaṃ kṣīraṃ madyaṃ māsaṃ ca kasyacit" },
      { type: "verse", number: "233", sanskrit: "पेया यूषो रसो ऽन्यस्य गोधूमो ऽन्यस्य शालयः अहितैरपि तेषां च तैरेवोपहितं हितम्", text: "peyā yūṣo raso 'nyasya godhūmo 'nyasya śālayaḥ ahitairapi teṣāṃ ca tairevopahitaṃ hitam" },
      { type: "verse", number: "234", sanskrit: "अन्नपानौषधं दोषमात्राकालाद्यपेक्षया सात्म्यं ह्याशु बलं धत्ते नातिदोषं च बह्वपि", text: "annapānauṣadhaṃ doṣamātrākālādyapekṣayā sātmyaṃ hyāśu balaṃ dhatte nātidoṣaṃ ca bahvapi" },
      { type: "verse", number: "235", sanskrit: "स्रंसनं सत् पयो गव्यं भवति ग्राहि कस्यचित् मन्दो ऽग्निर्भवति प्रायः कफवातोत्तरे हिमे", text: "sraṃsanaṃ sat payo gavyaṃ bhavati grāhi kasyacit mando 'gnirbhavati prāyaḥ kaphavātottare hime" },
      { type: "verse", number: "236", sanskrit: "विषघ्नेनापि पयसा देहे ऽहेर्वर्द्धते विषम् स्थूलस्थविरबालादौ वमनादि निषिध्यते", text: "viṣaghnenāpi payasā dehe 'hervarddhate viṣam sthūlasthavirabālādau vamanādi niṣidhyate" },
      { type: "verse", number: "237", sanskrit: "तक्रमामं कफं कोष्ठे हन्ति कण्ठे करोति तु वातहृत्त्वे ऽपि मृद्वीकाखर्जूरं कोष्ठवातकृत्", text: "takramāmaṃ kaphaṃ koṣṭhe hanti kaṇṭhe karoti tu vātahṛttve 'pi mṛdvīkākharjūraṃ koṣṭhavātakṛt" },
      { type: "verse", number: "238", sanskrit: "नातिपथ्यः शिखी पथ्यः श्रोत्रस्वरवयोदृशाम् दृष्टे स्पर्शहिमं द्रव्यं श्रोत्रस्योष्णं तु पूजितम्", text: "nātipathyaḥ śikhī pathyaḥ śrotrasvaravayodṛśām dṛṣṭe sparśahimaṃ dravyaṃ śrotrasyoṣṇaṃ tu pūjitam" },
      { type: "verse", number: "239", sanskrit: "पयः स्वादु सरं शीतं विपरीतं ततो दधि कालेन जायते तस्मात् क्षीरवच्च पुनर्घृतम्", text: "payaḥ svādu saraṃ śītaṃ viparītaṃ tato dadhi kālena jāyate tasmāt kṣīravacca punarghṛtam" },
      { type: "verse", number: "240", sanskrit: "पयो दधि च वातघ्नमजातं वातलं तु तत् तक्रं ग्राहि कषायाम्लमम्लमेव तु भेदनम्", text: "payo dadhi ca vātaghnamajātaṃ vātalaṃ tu tat takraṃ grāhi kaṣāyāmlamamlameva tu bhedanam" },
      { type: "verse", number: "241", sanskrit: "धातकीगुडतोयानि कारणं मद्यशुक्तयोः शीते न तु तदाद्यन्ते स्निग्धाम्ललवणा हिताः", text: "dhātakīguḍatoyāni kāraṇaṃ madyaśuktayoḥ śīte na tu tadādyante snigdhāmlalavaṇā hitāḥ" },
      { type: "verse", number: "242", sanskrit: "उदमन्थदिवास्वप्नौ ग्रीष्मादन्यत्र गर्हितौ समयोगे ऽपि घर्माद्या वातादिचयहेतवः", text: "udamanthadivāsvapnau grīṣmādanyatra garhitau samayoge 'pi gharmādyā vātādicayahetavaḥ" },
      { type: "verse", number: "243", sanskrit: "ऋतुष्वन्यो रसेष्वन्यो रौक्ष्ये स्नेहे बले क्रमः रसायनं काकमाची सद्यः पर्युषिता विषम्", text: "ṛtuṣvanyo raseṣvanyo raukṣye snehe bale kramaḥ rasāyanaṃ kākamācī sadyaḥ paryuṣitā viṣam" },
      { type: "verse", number: "244", sanskrit: "मूलकं दोसजिद्बालं विपरीतं तु कन्दवत् ज्वरे पेया कषायाश्च सर्पिः क्षीरं विरेचनम्", text: "mūlakaṃ dosajidbālaṃ viparītaṃ tu kandavat jvare peyā kaṣāyāśca sarpiḥ kṣīraṃ virecanam" },
      { type: "verse", number: "245", sanskrit: "षडहं षडहं युञ्ज्याद्वीक्ष्य दोषबलाबलम् छर्दिंहृद्रोगगुल्मार्ते वमनं च चिकित्सिते", text: "ṣaḍahaṃ ṣaḍahaṃ yuñjyādvīkṣya doṣabalābalam chardiṃhṛdrogagulmārte vamanaṃ ca cikitsite" },
      { type: "verse", number: "246", sanskrit: "निषिद्धमपि निर्दिष्टं बस्तिरर्शसकुष्ठिनोः ज्वरे तुल्यर्तुदोषत्वं प्रमेहे तुल्यदूष्यता", text: "niṣiddhamapi nirdiṣṭaṃ bastirarśasakuṣṭhinoḥ jvare tulyartudoṣatvaṃ pramehe tulyadūṣyatā" },
      { type: "verse", number: "247", sanskrit: "रक्तगुल्मे पुराणत्वं सुखसाध्यत्वहेतवः आश्च्योतनमभिष्यन्दे युञ्जीतोर्ध्वं दिनत्रयात्", text: "raktagulme purāṇatvaṃ sukhasādhyatvahetavaḥ āścyotanamabhiṣyande yuñjītordhvaṃ dinatrayāt" },
      { type: "verse", number: "248", sanskrit: "अञ्जनं पक्वदोषस्य प्रतिश्याये च नावनम् नातिप्रवृद्धे तिमिरे सिरामोक्षो विधीयते", text: "añjanaṃ pakvadoṣasya pratiśyāye ca nāvanam nātipravṛddhe timire sirāmokṣo vidhīyate" },
      { type: "verse", number: "249", sanskrit: "दुष्टास्रसम्भवे ऽपीष्टो नास्रपित्ते सिराव्यधः अपथ्यं पथ्यमप्यन्नं निशायां नेत्ररोगिणाम्", text: "duṣṭāsrasambhave 'pīṣṭo nāsrapitte sirāvyadhaḥ apathyaṃ pathyamapyannaṃ niśāyāṃ netrarogiṇām" },
      { type: "verse", number: "250", sanskrit: "अहिताः सक्तवः शुष्का हितास्ते तु प्रमेहिणः गुल्मिनः क्सीरदध्यादि हपुषाद्यैर्युतं हितम्", text: "ahitāḥ saktavaḥ śuṣkā hitāste tu pramehiṇaḥ gulminaḥ ksīradadhyādi hapuṣādyairyutaṃ hitam" },
      { type: "verse", number: "251", sanskrit: "वातलं वातकोपे ऽपि वर्षासु मधु शस्यते तदेव मद्यं मद्यस्य विषस्य तु विषान्तरम्", text: "vātalaṃ vātakope 'pi varṣāsu madhu śasyate tadeva madyaṃ madyasya viṣasya tu viṣāntaram" },
      { type: "verse", number: "252", sanskrit: "घृतमानूपदेशोत्थं हेमन्ते च बलाधिकम् आलस्यगौरवे रूपं वातजे ऽपि ज्वरे पुरः", text: "ghṛtamānūpadeśotthaṃ hemante ca balādhikam ālasyagaurave rūpaṃ vātaje 'pi jvare puraḥ" },
      { type: "verse", number: "253", sanskrit: "स्वेदैर्याति शमं दाहः प्रायो लशुनपानजः दिवास्वप्नाज्जरां याति भुक्तमन्येद्युरद्य न", text: "svedairyāti śamaṃ dāhaḥ prāyo laśunapānajaḥ divāsvapnājjarāṃ yāti bhuktamanyedyuradya na" },
      { type: "verse", number: "254", sanskrit: "कोष्ठे रुद्धो ऽग्निकृद्वायुर्मेदसार्शोभिरग्निहृत् दुष्पानं दुर्जरं सर्पिर्दीपनं च पयो ऽन्यथा", text: "koṣṭhe ruddho 'gnikṛdvāyurmedasārśobhiragnihṛt duṣpānaṃ durjaraṃ sarpirdīpanaṃ ca payo 'nyathā" },
      { type: "verse", number: "255", sanskrit: "सर्पादिशवकोथेभ्यो वृश्चिकानां समुद्भवः ते तैरेव पुनर्दष्टाः सद्यो जहति जीवितम्", text: "sarpādiśavakothebhyo vṛścikānāṃ samudbhavaḥ te taireva punardaṣṭāḥ sadyo jahati jīvitam" },
      { type: "verse", number: "256", sanskrit: "स्वयमेव विषं तीव्रं तान् पुनर्नातिबाधते सर्वाङ्गव्यापि तेषां च शुक्रवत् संसृतं विषम्", text: "svayameva viṣaṃ tīvraṃ tān punarnātibādhate sarvāṅgavyāpi teṣāṃ ca śukravat saṃsṛtaṃ viṣam" },
      { type: "verse", number: "257", sanskrit: "तन्मांसमुपयोगाय मांसवर्गे च पठ्यते छर्दिघ्नी मक्षिकाविट् च मक्षिकैव तु वामयेत्", text: "tanmāṃsamupayogāya māṃsavarge ca paṭhyate chardighnī makṣikāviṭ ca makṣikaiva tu vāmayet" },
      { type: "verse", number: "258", sanskrit: "कफे लङ्घनसाध्ये ऽपि कर्तरि ज्वरगुल्मयोः तुल्ये ऽपि देशकालादौ लङ्घनं न समं मतम्", text: "kaphe laṅghanasādhye 'pi kartari jvaragulmayoḥ tulye 'pi deśakālādau laṅghanaṃ na samaṃ matam" },
      { type: "verse", number: "259", sanskrit: "सर्वथा दोषजित्तक्रं ग्रहण्यां दोषकृद्व्रणे पीनसश्वासकासादौ सिद्धमेव प्रशस्यते", text: "sarvathā doṣajittakraṃ grahaṇyāṃ doṣakṛdvraṇe pīnasaśvāsakāsādau siddhameva praśasyate" },
      { type: "verse", number: "260", sanskrit: "इत्येते ऽन्ये च बहवः सूक्स्मा दुर्लभहेतुकाः धर्मा विचित्रा भावेषु किञ्चित्तेषां निदर्शितम्", text: "ityete 'nye ca bahavaḥ sūksmā durlabhahetukāḥ dharmā vicitrā bhāveṣu kiñcitteṣāṃ nidarśitam" },
      { type: "verse", number: "261", sanskrit: "दिशानया देशमपि स्वयमूहेत बुद्धिमान् न शास्त्रमात्रशरणो न चानालोचितागमः", text: "diśānayā deśamapi svayamūheta buddhimān na śāstramātraśaraṇo na cānālocitāgamaḥ" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 8,
    lang: "sa",
    content: [
      { type: "heading", heading: "Снеха видхи — применение масла" },
      { type: "text", text: "Глава 8 Сутрастханы Астанга-санграхи посвящена теме «применение масла». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो ऽन्नरक्षाविधिमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto 'nnarakṣāvidhimadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "ईश्वराणां वसुमतां विशेषेण तु भूभुजां प्रायेण मित्रेभ्यो ऽप्यमित्रा भूयांसो भवन्ति ततस्तत्प्रयुक्ताः समासन्नवर्तिनो ऽन्नपानादिषु विषं प्रयच्छन्ति स्त्रियश्च तत्प्राणिधिप्रयुक्ताः सौभाग्यलोभेन तस्माद्राजा कुलीनं स्निग्धमाप्तमास्तिकर्मायर्मायपरिग्रहं दक्षं दक्षिणं निभृतं शुचिमनुद्धतमनलसमव्यसनिनमनहङ्कृतमकोपनमसाहसिकं वाक्यार्थावबोधकुशलं निष्णातमष्टाङ्गे यथाम्रायमार्युवेदे सुविहितयोगक्षेमं सन्निहितागदादियोगं सात्म्यज्ञं च प्राणाचार्यं परिगृह्णीयात् तमर्थमानाभ्यां यथाकालं गुरुमिव शिषयः पितरमिव पुत्रः पूजयेत् प्रतिकूलमपि तद्वचः साम्प्रतं मतमिति प्रतिमन्येत न हि भद्रो ऽपि गजपतिर्निरङ्कुशः श्लाघनीयो जनस्य तस्मात्तदायत्तमाहारविहारं प्रति चात्मानं कुर्यात् उपात्तमपि खलु जीवितमुपायबलेन स्वयमधितिष्ठति", text: "īśvarāṇāṃ vasumatāṃ viśeṣeṇa tu bhūbhujāṃ prāyeṇa mitrebhyo 'pyamitrā bhūyāṃso bhavanti tatastatprayuktāḥ samāsannavartino 'nnapānādiṣu viṣaṃ prayacchanti striyaśca tatprāṇidhiprayuktāḥ saubhāgyalobhena tasmādrājā kulīnaṃ snigdhamāptamāstikarmāyarmāyaparigrahaṃ dakṣaṃ dakṣiṇaṃ nibhṛtaṃ śucimanuddhatamanalasamavyasaninamanahaṅkṛtamakopanamasāhasikaṃ vākyārthāvabodhakuśalaṃ niṣṇātamaṣṭāṅge yathāmrāyamāryuvede suvihitayogakṣemaṃ sannihitāgadādiyogaṃ sātmyajñaṃ ca prāṇācāryaṃ parigṛhṇīyāt tamarthamānābhyāṃ yathākālaṃ gurumiva śiṣayaḥ pitaramiva putraḥ pūjayet pratikūlamapi tadvacaḥ sāmprataṃ matamiti pratimanyeta na hi bhadro 'pi gajapatirniraṅkuśaḥ ślāghanīyo janasya tasmāttadāyattamāhāravihāraṃ prati cātmānaṃ kuryāt upāttamapi khalu jīvitamupāyabalena svayamadhitiṣṭhati" },
      { type: "verse", number: "3", sanskrit: "अपि च बहुपरिग्रहा नरपतयः सन्ति चाशुकारिणः शूलसन्यासादयः प्रतिक्षणं प्रत्यवेक्षणीयावस्थाश्च रोगिणो विशेषेण राजानः ते हि प्रमादपरिगता दुःखासहिष्णवश्च स्वयमप्यपथ्यरुचयः सन्निहिताहितप्रियवचनप्रायपरिचारकाश्च तस्माद्भिषजो राजा राजगृहासन्ने निवेशनं कारयेत् तथा हि सर्वोपकरणेषु नृपतिशरीरोपयोगिष्वपरोक्षवृत्तिर्भवति", text: "api ca bahuparigrahā narapatayaḥ santi cāśukāriṇaḥ śūlasanyāsādayaḥ pratikṣaṇaṃ pratyavekṣaṇīyāvasthāśca rogiṇo viśeṣeṇa rājānaḥ te hi pramādaparigatā duḥkhāsahiṣṇavaśca svayamapyapathyarucayaḥ sannihitāhitapriyavacanaprāyaparicārakāśca tasmādbhiṣajo rājā rājagṛhāsanne niveśanaṃ kārayet tathā hi sarvopakaraṇeṣu nṛpatiśarīropayogiṣvaparokṣavṛttirbhavati" },
      { type: "verse", number: "4", sanskrit: "स सम्यक्सम्पन्नमन्नं सुपरीक्षितं विशुद्धमग्न्यादिषु प्रागुपनीतं शिखिना दृष्टमभिप्रोक्षितं प्रोक्षाणैः पुरःस्थितो राजानं हस्तबद्धौषधिरत्नं भोजयेत्", text: "sa samyaksampannamannaṃ suparīkṣitaṃ viśuddhamagnyādiṣu prāgupanītaṃ śikhinā dṛṣṭamabhiprokṣitaṃ prokṣāṇaiḥ puraḥsthito rājānaṃ hastabaddhauṣadhiratnaṃ bhojayet" },
      { type: "verse", number: "5", sanskrit: "भुञ्जानस्य चास्य दुन्दुभीनगदप्रलिप्तान् वादयेत्", text: "bhuñjānasya cāsya dundubhīnagadapraliptān vādayet" },
      { type: "verse", number: "6", sanskrit: "तत्र सविषमन्नं स्राव्यमाणमविस्राव्यं भवति चिरेण पच्यते पक्वं च सद्यः पर्युषितमिव निरूष्म स्तब्धं च जायते यथास्ववर्णगन्धरसैर्व्यापद्यते प्रक्लिद्यते चन्द्रकाचितं च भवति", text: "tatra saviṣamannaṃ srāvyamāṇamavisrāvyaṃ bhavati cireṇa pacyate pakvaṃ ca sadyaḥ paryuṣitamiva nirūṣma stabdhaṃ ca jāyate yathāsvavarṇagandharasairvyāpadyate praklidyate candrakācitaṃ ca bhavati" },
      { type: "verse", number: "7", sanskrit: "व्यञ्जनानामाशु शुष्कत्वं भवति क्वाथः ध्यामता श्यामता हीनातिरिक्तविकृतानां चात्रच्छायानां दर्शनमदर्शनमेव वा फेनपटलसीमन्तोर्ध्वविविधराजितन्तुबुद्बुदप्रादुर्भावो विशेषेण लवणोल्बणेषु फेनमाला रसस्य मध्ये नीला राजिः पयसस्ताम्रा मद्यतोययोः काली दध्नः श्यावा तक्रस्य नीलपीता मस्तुनः कपोताभा धान्याम्लस्य कृष्णा द्रवौषधस्य कपिला घृतस्य कपिलाभा क्षौद्रस्य हरिता तैलस्यारुणा वसागन्धश्च", text: "vyañjanānāmāśu śuṣkatvaṃ bhavati kvāthaḥ dhyāmatā śyāmatā hīnātiriktavikṛtānāṃ cātracchāyānāṃ darśanamadarśanameva vā phenapaṭalasīmantordhvavividharājitantubudbudaprādurbhāvo viśeṣeṇa lavaṇolbaṇeṣu phenamālā rasasya madhye nīlā rājiḥ payasastāmrā madyatoyayoḥ kālī dadhnaḥ śyāvā takrasya nīlapītā mastunaḥ kapotābhā dhānyāmlasya kṛṣṇā dravauṣadhasya kapilā ghṛtasya kapilābhā kṣaudrasya haritā tailasyāruṇā vasāgandhaśca" },
      { type: "verse", number: "8", sanskrit: "फलानामामानां पाकः पक्वानां प्रकोथः दव्याणामार्द्राणां सहसा म्लानत्वमुत्पक्वभावः शुष्काणां श्यावता वैवर्ण्यं वा कठिनानां मृदुता मृदूनां कठिनत्वं माल्यस्य म्लानता गन्धनाशः स्फुटिताग्रत्वं आस्तरणप्रावरणानां ध्याममण्डलता तन्तुरोमपक्ष्मशातनं च लोहमणिमयानां पङ्कमलोपदेहः स्नेहरागगौरवप्रभावर्णस्पर्शनाशश्च", text: "phalānāmāmānāṃ pākaḥ pakvānāṃ prakothaḥ davyāṇāmārdrāṇāṃ sahasā mlānatvamutpakvabhāvaḥ śuṣkāṇāṃ śyāvatā vaivarṇyaṃ vā kaṭhinānāṃ mṛdutā mṛdūnāṃ kaṭhinatvaṃ mālyasya mlānatā gandhanāśaḥ sphuṭitāgratvaṃ āstaraṇaprāvaraṇānāṃ dhyāmamaṇḍalatā tanturomapakṣmaśātanaṃ ca lohamaṇimayānāṃ paṅkamalopadehaḥ sneharāgagauravaprabhāvarṇasparśanāśaśca" },
      { type: "verse", number: "9", sanskrit: "विषदस्तु स्वदोषशङ्कया त्रस्तो भीतः स्वेदवेपथुमान् शुष्कश्याववक्त्रः समन्तात् सोद्वेगं विलक्षो ऽभिवीक्षते यत्र चानेन विषं प्रयुक्तं तद्विशेषेण तथा स्रस्तोत्तरीयः स्तम्भकुड्यादिभिरात्मानमन्तर्धत्ते स्खलितगतिर्दीनो लज्जावानस्थानहासी पृष्टो ऽप्यसम्बन्धमुत्तरं ददाति नैववा विवक्षुर्मुह्यति अङ्गुलीः स्फोटयति ग्रीवामालभते शिरः कण्डूयति औष्ठौ परिलेढि जृम्भते भुवं विलिखति क्रियासु त्वरते विपरीतमाचरति स्वभूमौ च नावतिष्ठते", text: "viṣadastu svadoṣaśaṅkayā trasto bhītaḥ svedavepathumān śuṣkaśyāvavaktraḥ samantāt sodvegaṃ vilakṣo 'bhivīkṣate yatra cānena viṣaṃ prayuktaṃ tadviśeṣeṇa tathā srastottarīyaḥ stambhakuḍyādibhirātmānamantardhatte skhalitagatirdīno lajjāvānasthānahāsī pṛṣṭo 'pyasambandhamuttaraṃ dadāti naivavā vivakṣurmuhyati aṅgulīḥ sphoṭayati grīvāmālabhate śiraḥ kaṇḍūyati auṣṭhau parileḍhi jṛmbhate bhuvaṃ vilikhati kriyāsu tvarate viparītamācarati svabhūmau ca nāvatiṣṭhate" },
      { type: "verse", number: "10", sanskrit: "नृपाज्ञात्वरयापि केचिदपराधान्तराद्वा ऽनवस्थितसत्त्वाः समाचरन्त्येवम् तस्मादग्न्यादिप्वपि परीक्षेत वह्निस्तु सविषमन्नं प्राप्यैकावर्तो रूक्षमन्दार्चिरिन्द्रायुधवदनेकवर्णज्वालो भृशं चटचटायते कुणपगन्धी धूमश्चास्य मूर्च्छाप्रसेकरोमहर्षशिरोवेदनापीनसदृष्ट्याकुलतां जनयति", text: "nṛpājñātvarayāpi kecidaparādhāntarādvā 'navasthitasattvāḥ samācarantyevam tasmādagnyādipvapi parīkṣeta vahnistu saviṣamannaṃ prāpyaikāvarto rūkṣamandārcirindrāyudhavadanekavarṇajvālo bhṛśaṃ caṭacaṭāyate kuṇapagandhī dhūmaścāsya mūrcchāprasekaromaharṣaśirovedanāpīnasadṛṣṭyākulatāṃ janayati" },
      { type: "verse", number: "11", sanskrit: "तत्र नलदकुष्ठलामज्जकैः क्षौद्रद्रुतैर्नस्यमञ्जनं च कुर्यात् धूममेव वापामार्गविडङ्गबलाद्वयचित्रकमेषशृङ्गिपुष्पसुमनःक्षारकद्राक्षाघृतगुडकृतं पिबेत्", text: "tatra naladakuṣṭhalāmajjakaiḥ kṣaudradrutairnasyamañjanaṃ ca kuryāt dhūmameva vāpāmārgaviḍaṅgabalādvayacitrakameṣaśṛṅgipuṣpasumanaḥkṣārakadrākṣāghṛtaguḍakṛtaṃ pibet" },
      { type: "verse", number: "12", sanskrit: "स्नेहलवणयोगादपि चाग्निरित्थं स्यात् अतो वयोभिः परीक्षेत तत्र विषजुष्टाहाराभ्यवहारात्काकाः क्षामस्वरा भवन्ति मक्षिकाः सविषान्ने न निलीयन्ते निलीनाश्च व्यापद्यन्ते दृष्ट एव चास्मिंस्तु चकोरस्याक्षिणी विरज्येते कोकिलस्य स्वरो विकृतिमेति हंसस्य गतिः स्खलति कूजति भृङ्गराजः माद्यति क्रौञ्चः विरौति कृकवाकुः विक्रोशति शुकः शारिका च छर्दयति चामीकरः अन्यतो याति कारण्डवः म्रियते जीवञ्जीवको ग्लायति वा हृष्टरोमा भवति नकुलः शकृद्विस्र्जति वानरः रोदिति पृषतः हृष्यति मयूरः दर्शनादेव चास्य विषं मन्दतामुपैति", text: "snehalavaṇayogādapi cāgniritthaṃ syāt ato vayobhiḥ parīkṣeta tatra viṣajuṣṭāhārābhyavahārātkākāḥ kṣāmasvarā bhavanti makṣikāḥ saviṣānne na nilīyante nilīnāśca vyāpadyante dṛṣṭa eva cāsmiṃstu cakorasyākṣiṇī virajyete kokilasya svaro vikṛtimeti haṃsasya gatiḥ skhalati kūjati bhṛṅgarājaḥ mādyati krauñcaḥ virauti kṛkavākuḥ vikrośati śukaḥ śārikā ca chardayati cāmīkaraḥ anyato yāti kāraṇḍavaḥ mriyate jīvañjīvako glāyati vā hṛṣṭaromā bhavati nakulaḥ śakṛdvisrjati vānaraḥ roditi pṛṣataḥ hṛṣyati mayūraḥ darśanādeva cāsya viṣaṃ mandatāmupaiti" },
      { type: "verse", number: "13", sanskrit: "विषदूषितस्य पुनराहारस्योष्मा मयूरकण्ठाभो ऽभ्युदेति तद्वाष्पेणापि धूमवन्मूर्छादयः तेषां तद्वदेव साधनम् हस्तेन स्पृष्टमन्नं विषवद्दाहशोफस्वापनखशातान् करोति तस्य श्यामेन्द्रगोपसोमोत्पलैर्लेपः", text: "viṣadūṣitasya punarāhārasyoṣmā mayūrakaṇṭhābho 'bhyudeti tadvāṣpeṇāpi dhūmavanmūrchādayaḥ teṣāṃ tadvadeva sādhanam hastena spṛṣṭamannaṃ viṣavaddāhaśophasvāpanakhaśātān karoti tasya śyāmendragopasomotpalairlepaḥ" },
      { type: "verse", number: "14", sanskrit: "अभ्यवह्रियमाणं त्वोष्ठचिमिचिमान्तर्वक्त्रदाहजिह्वामूलगौरवहनुस्तम्भदन्तहर्षलालाः करोति रसापरिज्ञानं च तत्र धूमोक्तं दन्तकाष्ठोक्तं च कर्म आमाशयगतं स्वेदमदमूर्छछर्दिवैवर्ण्याध्मानरोमहर्षदाहारुचिदृष्टिहृदयोपरोधान् बिन्दुभिश्चाचयमङ्गानां करोति", text: "abhyavahriyamāṇaṃ tvoṣṭhacimicimāntarvaktradāhajihvāmūlagauravahanustambhadantaharṣalālāḥ karoti rasāparijñānaṃ ca tatra dhūmoktaṃ dantakāṣṭhoktaṃ ca karma āmāśayagataṃ svedamadamūrchachardivaivarṇyādhmānaromaharṣadāhārucidṛṣṭihṛdayoparodhān bindubhiścācayamaṅgānāṃ karoti" },
      { type: "verse", number: "15", sanskrit: "तत्र मदमफलालबुबिम्बीकोशातकीफलैर्दाधिमधुयुक्तमाशु वमनं दद्यात् निष्पावाम्बुभिर्वा ततः स्निग्धशरीरं विरेचयत् त्रिफलात्रिकटुनागपुष्पमधुकबर्हिणपर्णीबृहतीद्वयचूर्णं सिंहव्याघ्रवृकतरक्षुद्वीपिमार्जारसृगालमृगगोधानामन्यतमपित्तरससंयुक्तं सक्षौद्रं पानमेष जीवनो नामागदः परं सर्वविषौषधम् तस्मिन् जीर्णे श्यामाव्योषातिविषासिद्धेन पयसा घृतेन वोपस्तम्भितां मुद्गयूषेण किंचिल्लवणेन ससर्पिष्केण मृद्वोदनं भोजयेत् मधुकशिरीषचन्दनैश्चैनमालिम्पेत्", text: "tatra madamaphalālabubimbīkośātakīphalairdādhimadhuyuktamāśu vamanaṃ dadyāt niṣpāvāmbubhirvā tataḥ snigdhaśarīraṃ virecayat triphalātrikaṭunāgapuṣpamadhukabarhiṇaparṇībṛhatīdvayacūrṇaṃ siṃhavyāghravṛkatarakṣudvīpimārjārasṛgālamṛgagodhānāmanyatamapittarasasaṃyuktaṃ sakṣaudraṃ pānameṣa jīvano nāmāgadaḥ paraṃ sarvaviṣauṣadham tasmin jīrṇe śyāmāvyoṣātiviṣāsiddhena payasā ghṛtena vopastambhitāṃ mudgayūṣeṇa kiṃcillavaṇena sasarpiṣkeṇa mṛdvodanaṃ bhojayet madhukaśirīṣacandanaiścainamālimpet" },
      { type: "verse", number: "16", sanskrit: "पक्वाशयगतं तृड्दाहमूर्च्छातीसाराटोपतन्द्रेन्द्रियविकृतिबलभ्रंशकार्श्यपाण्डुत्वोदराणि जनयति तत्र नीलिनीफलयुक्तेन सर्पिषा विरेचनं समाक्षिकं च दूषीविषारिं दध्ना पाययेत् दन्तकाष्ठप्रयुक्ते तु विषे कूर्चकविशरणमौषधगन्धो रूक्षता तालुदन्तजिह्वोष्ठमांसशोफश्च तत्र प्रच्छाय धातकीपुष्पजाम्बवास्थिहरीतकीचूर्णैः सक्षौद्रैः सप्तच्छदकल्केन वा प्रतिसारणं कुर्यात् दाडिमकरमदर्भव्याम्रातककोलबदररसक्षौद्रयुक्तं गण्डूषम् अनेन जिह्वानिर्लेखनकवलगण्डूषा व्याख्याताः", text: "pakvāśayagataṃ tṛḍdāhamūrcchātīsārāṭopatandrendriyavikṛtibalabhraṃśakārśyapāṇḍutvodarāṇi janayati tatra nīlinīphalayuktena sarpiṣā virecanaṃ samākṣikaṃ ca dūṣīviṣāriṃ dadhnā pāyayet dantakāṣṭhaprayukte tu viṣe kūrcakaviśaraṇamauṣadhagandho rūkṣatā tāludantajihvoṣṭhamāṃsaśophaśca tatra pracchāya dhātakīpuṣpajāmbavāsthiharītakīcūrṇaiḥ sakṣaudraiḥ saptacchadakalkena vā pratisāraṇaṃ kuryāt dāḍimakaramadarbhavyāmrātakakolabadararasakṣaudrayuktaṃ gaṇḍūṣam anena jihvānirlekhanakavalagaṇḍūṣā vyākhyātāḥ" },
      { type: "verse", number: "17", sanskrit: "अञ्जनप्रयुक्ते ऽश्रुदूषिकोपदेहरागवेदनादृष्टिविभ्रमा भवन्त्यान्ध्यं च तत्र सर्पिष्पानं योज्यम् शृतेन पयसा सप्तकृत्वः पिप्पलीर्भावयेत् ततस्तत्कल्केन सर्पिर्विपक्वं नेत्रतर्पणम् कपित्थमेषशृङ्गीभल्लातकानां पुष्पैर्वरणनिर्यासेन वाञ्जनं बृहतीशिरीषबीजप्रपौण्डरीकनागबलाचूर्णं सप्तकृत्वो मधुना भावयेत् तच्च स्रोतो ऽञ्जनसुवर्णचूर्णयुक्तमञ्जनं देयम् नस्यधूमप्रयुक्ते शिरोरुक्काफास्रावः खेभ्यो रुधिरागमनमिन्द्रियवैकृतं च तत्रातिविषाश्वेताकाकमाचीमदयन्तिकाकल्के क्षीरसिद्धं सर्पिर्न्नस्ये पाने च विदध्यात् अभ्यङ्गप्रयुक्ते त्वग्दाहस्वेदपाकस्फोटावदरणानि तत्र शीताम्बुपरिषिक्तस्य चन्दनतगरोशीरकुष्ठवेणुपत्रिकामृतासोमवल्लीश्वेतापद्मकालेयकैरनुलेपनम् एतान्येव च सकपित्थरसगोमूत्राणि पानम् गिरिकर्णिकाश्वेतमूलप्रियङ्गुसारिवामधुकसर्पसुगन्धामृगोर्वारुकतकमूलानि शेलुक्वाथपिष्टानि प्रलेपः अनेनोद्वर्त्तनघर्षणपरिषेकानुलेपनभूषणयानशय्यास्तरणवस्त्रकवचपादुकोपानत्पादपीठा व्याख्याताः", text: "añjanaprayukte 'śrudūṣikopadeharāgavedanādṛṣṭivibhramā bhavantyāndhyaṃ ca tatra sarpiṣpānaṃ yojyam śṛtena payasā saptakṛtvaḥ pippalīrbhāvayet tatastatkalkena sarpirvipakvaṃ netratarpaṇam kapitthameṣaśṛṅgībhallātakānāṃ puṣpairvaraṇaniryāsena vāñjanaṃ bṛhatīśirīṣabījaprapauṇḍarīkanāgabalācūrṇaṃ saptakṛtvo madhunā bhāvayet tacca sroto 'ñjanasuvarṇacūrṇayuktamañjanaṃ deyam nasyadhūmaprayukte śirorukkāphāsrāvaḥ khebhyo rudhirāgamanamindriyavaikṛtaṃ ca tatrātiviṣāśvetākākamācīmadayantikākalke kṣīrasiddhaṃ sarpirnnasye pāne ca vidadhyāt abhyaṅgaprayukte tvagdāhasvedapākasphoṭāvadaraṇāni tatra śītāmbupariṣiktasya candanatagarośīrakuṣṭhaveṇupatrikāmṛtāsomavallīśvetāpadmakāleyakairanulepanam etānyeva ca sakapittharasagomūtrāṇi pānam girikarṇikāśvetamūlapriyaṅgusārivāmadhukasarpasugandhāmṛgorvārukatakamūlāni śelukvāthapiṣṭāni pralepaḥ anenodvarttanagharṣaṇapariṣekānulepanabhūṣaṇayānaśayyāstaraṇavastrakavacapādukopānatpādapīṭhā vyākhyātāḥ" },
      { type: "verse", number: "18", sanskrit: "विशेषतस्त्वाभरणकृते विकारे ऽश्वगन्धापामार्गकिणिहीखदिरशिरीषकल्कैर्गोपित्तयुक्तैः प्रदेहः पादपीठकृते श्लेष्मातकसर्पसुगन्धाम्रकल्को मधुयुक्तः छत्रप्रयुक्ते वेदनास्फोटानां क्षिप्रपाकानां पक्वजाम्बवप्रकाशानां प्रादुर्भावः तत्र मधुकपाटलाकशेरुकलोध्राञ्जनकुष्ठसर्पसुगन्धाखदिरशिरीषकल्कैः सर्वगात्रप्रदेहः अनेन चामरव्यजने व्याख्याते", text: "viśeṣatastvābharaṇakṛte vikāre 'śvagandhāpāmārgakiṇihīkhadiraśirīṣakalkairgopittayuktaiḥ pradehaḥ pādapīṭhakṛte śleṣmātakasarpasugandhāmrakalko madhuyuktaḥ chatraprayukte vedanāsphoṭānāṃ kṣiprapākānāṃ pakvajāmbavaprakāśānāṃ prādurbhāvaḥ tatra madhukapāṭalākaśerukalodhrāñjanakuṣṭhasarpasugandhākhadiraśirīṣakalkaiḥ sarvagātrapradehaḥ anena cāmaravyajane vyākhyāte" },
      { type: "verse", number: "19", sanskrit: "शिरो ऽभ्यङ्गप्रयुक्ते शिरोवेदना ग्रन्थिजन्म केशच्यवनं च तत्र श्यामापालिन्दीतण्डुलीयकचूर्ण घृतर्क्षपित्तैः सुभावितया कृष्णमृदा प्रलेपः गोमयमालतीमूषिककर्ण्यन्यतमरसो वागारधूमो वा श्लेष्मातकत्वक्पाटलाशिरीषमधुकहरिद्राद्वयैरजाक्षीरालोडितैः परिषेकः अनेन शिरःस्नानोदककङ्कतस्रगुष्णीषा व्याख्याताः", text: "śiro 'bhyaṅgaprayukte śirovedanā granthijanma keśacyavanaṃ ca tatra śyāmāpālindītaṇḍulīyakacūrṇa ghṛtarkṣapittaiḥ subhāvitayā kṛṣṇamṛdā pralepaḥ gomayamālatīmūṣikakarṇyanyatamaraso vāgāradhūmo vā śleṣmātakatvakpāṭalāśirīṣamadhukaharidrādvayairajākṣīrāloḍitaiḥ pariṣekaḥ anena śiraḥsnānodakakaṅkatasraguṣṇīṣā vyākhyātāḥ" },
      { type: "verse", number: "20", sanskrit: "कर्णपूरणप्रयुक्ते शोफशूलपाकाः श्रोत्रवैगुण्यं च तत्र बहुपत्रास्वरसो घृतक्षौद्रसंयुक्तः प्रतिपूरणं सोमवल्करसो वा सुशीतः मुखालेपप्रयुक्ते मुखश्यावता पद्मकण्टका भवन्त्यभ्यङ्गजाश्च विकाराः तत्र मधुकपयस्याबन्धुजीवभञ्जीपुनर्नवचन्दनैः सघृतैर्लेपो मधुसर्पिषी पानम् सविषपुष्पाघ्राणाच्छिरोव्यथा साश्रुनेत्रत्वं गन्धाज्ञानं च तत्रानन्तरोक्तो विधिर्बाष्पोदितश्चेति", text: "karṇapūraṇaprayukte śophaśūlapākāḥ śrotravaiguṇyaṃ ca tatra bahupatrāsvaraso ghṛtakṣaudrasaṃyuktaḥ pratipūraṇaṃ somavalkaraso vā suśītaḥ mukhālepaprayukte mukhaśyāvatā padmakaṇṭakā bhavantyabhyaṅgajāśca vikārāḥ tatra madhukapayasyābandhujīvabhañjīpunarnavacandanaiḥ saghṛtairlepo madhusarpiṣī pānam saviṣapuṣpāghrāṇācchirovyathā sāśrunetratvaṃ gandhājñānaṃ ca tatrānantarokto vidhirbāṣpoditaśceti" },
      { type: "verse", number: "21", sanskrit: "भवति चात्र फलमूलच्छदादीनां दद्यात्प्रक्षालनोदकम् भाजनव्यञ्जनानां च तथा कुर्यादतन्द्रितः", text: "bhavati cātra phalamūlacchadādīnāṃ dadyātprakṣālanodakam bhājanavyañjanānāṃ ca tathā kuryādatandritaḥ" },
      { type: "verse", number: "22", sanskrit: "घ्रेयाणि घ्रापयित्वा तु स्पृश्यान् संस्पृश्य तानपि प्रतीवापं ततो दत्वा प्रतीक्ष्यैवैकनाडिकाम्", text: "ghreyāṇi ghrāpayitvā tu spṛśyān saṃspṛśya tānapi pratīvāpaṃ tato datvā pratīkṣyaivaikanāḍikām" },
      { type: "verse", number: "23", sanskrit: "ततो विज्ञाय शुद्धिं च भाजनस्योदकस्य च आहारमुपयुञ्जीत यथावद्वसुधाधिपः", text: "tato vijñāya śuddhiṃ ca bhājanasyodakasya ca āhāramupayuñjīta yathāvadvasudhādhipaḥ" },
      { type: "verse", number: "24", sanskrit: "मन्दं तीक्ष्णविषाभ्यासाद्विषमुत्क्षीयते भृशम् तस्मात्तीक्ष्णविषं हस्ते बध्नीयात्कुशलो भिषक्", text: "mandaṃ tīkṣṇaviṣābhyāsādviṣamutkṣīyate bhṛśam tasmāttīkṣṇaviṣaṃ haste badhnīyātkuśalo bhiṣak" },
      { type: "verse", number: "25", sanskrit: "विषसंधारणं धन्यं रक्षोघ्नं प्रीतिवर्धनम् अपि च सापिधानघटीमूटफलकस्थापितौषधम्", text: "viṣasaṃdhāraṇaṃ dhanyaṃ rakṣoghnaṃ prītivardhanam api ca sāpidhānaghaṭīmūṭaphalakasthāpitauṣadham" },
      { type: "verse", number: "26", sanskrit: "प्रागुदीच्योर्दिशोर्गुप्तं भेषजागारमिष्यते उच्चैः प्रशस्तदिग्देशं बहुवातायनं महत्", text: "prāgudīcyordiśorguptaṃ bheṣajāgāramiṣyate uccaiḥ praśastadigdeśaṃ bahuvātāyanaṃ mahat" },
      { type: "verse", number: "27", sanskrit: "महानसं सुसंमृष्टं विश्वास्यजनसेवितम् सद्द्वास्स्थाधिष्ठितद्वारं कक्ष्यावत्सुवितानकम्", text: "mahānasaṃ susaṃmṛṣṭaṃ viśvāsyajanasevitam saddvāssthādhiṣṭhitadvāraṃ kakṣyāvatsuvitānakam" },
      { type: "verse", number: "28", sanskrit: "सुधौतदृठकुम्भादि परिशुद्धजलेन्धनम् स्वकर्मकुशला दक्षाः सूदास्तत्राप्रमादिनः", text: "sudhautadṛṭhakumbhādi pariśuddhajalendhanam svakarmakuśalā dakṣāḥ sūdāstatrāpramādinaḥ" },
      { type: "verse", number: "29", sanskrit: "क्ल्प्तकेशनखाः पित्र्या राज्ञः कृत्यैरसङ्गताः तेषामधिपतिर्विप्रः कुलजः सुपरीक्षितः", text: "kLptakeśanakhāḥ pitryā rājñaḥ kṛtyairasaṅgatāḥ teṣāmadhipatirvipraḥ kulajaḥ suparīkṣitaḥ" },
      { type: "verse", number: "30", sanskrit: "संविभक्तश्च भक्तश्च शुचिर्वैद्यवशूनुगः सर्वे ऽपि भूभृदासन्नाः शस्ताः सततमीदृशाः", text: "saṃvibhaktaśca bhaktaśca śucirvaidyavaśūnugaḥ sarve 'pi bhūbhṛdāsannāḥ śastāḥ satatamīdṛśāḥ" },
      { type: "verse", number: "31", sanskrit: "मिथो विग्रहसङ्घातरहिता भूभृते हिताः तान् वैद्यो गुणवानेको मनसा प्रतिजागृयात्", text: "mitho vigrahasaṅghātarahitā bhūbhṛte hitāḥ tān vaidyo guṇavāneko manasā pratijāgṛyāt" },
      { type: "verse", number: "32", sanskrit: "भूभृद्देहोपकरणसंरक्षणसमुद्यतः", text: "bhūbhṛddehopakaraṇasaṃrakṣaṇasamudyataḥ" },
      { type: "verse", number: "33", sanskrit: "अथाभ्यमित्रं व्रजतो जिगीषोर्वैद्यः सुसज्जौषधशस्त्रयन्त्रः तुङ्गध्वजाख्यातनिवासभूमिर्युद्धागतं योधजनं चिकित्सेत्", text: "athābhyamitraṃ vrajato jigīṣorvaidyaḥ susajjauṣadhaśastrayantraḥ tuṅgadhvajākhyātanivāsabhūmiryuddhāgataṃ yodhajanaṃ cikitset" },
      { type: "verse", number: "34", sanskrit: "पन्थानमुदकं छायां भक्तं यवसमिन्धनम् दूषयन्त्यरयो यस्मात्तान् विद्याच्छोधयेत च", text: "panthānamudakaṃ chāyāṃ bhaktaṃ yavasamindhanam dūṣayantyarayo yasmāttān vidyācchodhayeta ca" },
      { type: "verse", number: "35", sanskrit: "प्रस्थानं वा निवेशं वा नाविज्ञाय प्रयोजयेत् भूवारितृणकाष्ठाश्ममार्गोन्मार्गवनस्पतीन्", text: "prasthānaṃ vā niveśaṃ vā nāvijñāya prayojayet bhūvāritṛṇakāṣṭhāśmamārgonmārgavanaspatīn" },
      { type: "verse", number: "36", sanskrit: "विषेणोपहता भूमिः क्वचिद्दग्धेव लक्ष्यते प्रम्लानतृणगुल्मादिमृतकीटसरीसृपा", text: "viṣeṇopahatā bhūmiḥ kvaciddagdheva lakṣyate pramlānatṛṇagulmādimṛtakīṭasarīsṛpā" },
      { type: "verse", number: "37", sanskrit: "विशीर्यन्ते खुरनखा दाहकण्डूरुजान्विताः छर्दिर्मूर्छा ज्वरो मोहः शिरोदुःखं च जायते", text: "viśīryante khuranakhā dāhakaṇḍūrujānvitāḥ chardirmūrchā jvaro mohaḥ śiroduḥkhaṃ ca jāyate" },
      { type: "verse", number: "38", sanskrit: "तत्र सौभञ्जनान्मूलं सोमवल्लीमुशीरकम् मातुलुङ्गरसं हिङ्गुं पाययेद्दधिमात्रया", text: "tatra saubhañjanānmūlaṃ somavallīmuśīrakam mātuluṅgarasaṃ hiṅguṃ pāyayeddadhimātrayā" },
      { type: "verse", number: "39", sanskrit: "मूत्राण्यजाविहस्तिभ्यो मांसानि रुधिराणि च सर्वगन्धैः समं योज्य पचेत्पक्वे च निक्षिपेत्", text: "mūtrāṇyajāvihastibhyo māṃsāni rudhirāṇi ca sarvagandhaiḥ samaṃ yojya pacetpakve ca nikṣipet" },
      { type: "verse", number: "40", sanskrit: "सोमराजीं सुनन्दाख्यां सरलं गन्धनाकुलीम् चारटीं त्रायमाणां च प्रोक्षयेत्तेन तां भुवम्", text: "somarājīṃ sunandākhyāṃ saralaṃ gandhanākulīm cāraṭīṃ trāyamāṇāṃ ca prokṣayettena tāṃ bhuvam" },
      { type: "verse", number: "41", sanskrit: "सविषं विरसं तोयं कवोष्णं राजिभिश्चितम् फेनिलं गुरु विच्छिन्नं खगैरनाभिनन्दितम्", text: "saviṣaṃ virasaṃ toyaṃ kavoṣṇaṃ rājibhiścitam phenilaṃ guru vicchinnaṃ khagairanābhinanditam" },
      { type: "verse", number: "42", sanskrit: "मृताकुलितमत्स्यं च स्पर्शाद्रुक्शोफकण्डुमत् औदनः साधितस्तेन भुक्तमात्रो ऽपि दह्यते", text: "mṛtākulitamatsyaṃ ca sparśādrukśophakaṇḍumat audanaḥ sādhitastena bhuktamātro 'pi dahyate" },
      { type: "verse", number: "43", sanskrit: "विदग्धः पच्यते कृच्छ्रात्पक्वो मूर्छाज्वरप्रदः दर्शयेत्सर्वतो नीलपीतकर्बुरलोहितम्", text: "vidagdhaḥ pacyate kṛcchrātpakvo mūrchājvarapradaḥ darśayetsarvato nīlapītakarburalohitam" },
      { type: "verse", number: "44", sanskrit: "तत्र शिग्रेवादिमगदं भूमिदोषोदितं पिबेत् अजशृङ्गीं विशालाख्यां विषघ्नीमुत्तमारणीम्", text: "tatra śigrevādimagadaṃ bhūmidoṣoditaṃ pibet ajaśṛṅgīṃ viśālākhyāṃ viṣaghnīmuttamāraṇīm" },
      { type: "verse", number: "45", sanskrit: "फणिज्जकं प्रतिविषां दग्ध्वा तद्भस्म गालयेत् बहुशो गालितं तच्च पाचयेत्तत्र च क्षिपेत्", text: "phaṇijjakaṃ prativiṣāṃ dagdhvā tadbhasma gālayet bahuśo gālitaṃ tacca pācayettatra ca kṣipet" },
      { type: "verse", number: "46", sanskrit: "कल्कयित्वा प्रतीवापं सरलं रजनीद्वयम् एलामुदीच्यं मञ्जिष्ठां सुनन्दां बाकुचीअपि", text: "kalkayitvā pratīvāpaṃ saralaṃ rajanīdvayam elāmudīcyaṃ mañjiṣṭhāṃ sunandāṃ bākucīapi" },
      { type: "verse", number: "47", sanskrit: "पात्यन्ते बिन्दवस्तस्माद्यत्र तन्निर्विषीभवेत् पाटलापारिभद्राश्वकर्णशम्याकसिध्रकान्", text: "pātyante bindavastasmādyatra tannirviṣībhavet pāṭalāpāribhadrāśvakarṇaśamyākasidhrakān" },
      { type: "verse", number: "48", sanskrit: "कलशान्तर्गतान् दग्ध्वा प्रक्षिपेत्सविषे ऽम्भसि शीते घर्मो हिमश्चोष्णे मारुतो विषसंयुतः", text: "kalaśāntargatān dagdhvā prakṣipetsaviṣe 'mbhasi śīte gharmo himaścoṣṇe māruto viṣasaṃyutaḥ" },
      { type: "verse", number: "49", sanskrit: "भ्रममूर्छादिकारी च शिग्र्वादिस्तत्र चेष्यते देवदारुनतानन्तामधुकार्जुनगैरिकम्", text: "bhramamūrchādikārī ca śigrvādistatra ceṣyate devadārunatānantāmadhukārjunagairikam" },
      { type: "verse", number: "50", sanskrit: "वज्रकन्दं लतां लोध्नं विकिरेच्छ्लक्ष्णचूर्णितम् वृक्षाग्रेषु पताकासु दूष्येषु सुमहत्सु च", text: "vajrakandaṃ latāṃ lodhnaṃ vikirecchlakṣṇacūrṇitam vṛkṣāgreṣu patākāsu dūṣyeṣu sumahatsu ca" },
      { type: "verse", number: "51", sanskrit: "सर्वतश्चूर्णसंपर्कान्निर्विषो जायते ऽनिलः विकृता भवति छाया पादपे विषदूषिते", text: "sarvataścūrṇasaṃparkānnirviṣo jāyate 'nilaḥ vikṛtā bhavati chāyā pādape viṣadūṣite" },
      { type: "verse", number: "52", sanskrit: "निर्गन्धमतिगन्धं वा तत्पुष्पं हृच्छिरोरुजम् कुर्यात् फलपलशादि कण्डूपाकातिसारकृत्", text: "nirgandhamatigandhaṃ vā tatpuṣpaṃ hṛcchirorujam kuryāt phalapalaśādi kaṇḍūpākātisārakṛt" },
      { type: "verse", number: "53", sanskrit: "भूमिमुद्दिश्य यत्प्रोक्तं तत्सर्वं तत्र चेष्यते न च कन्यामविदितां संस्पृशेदपरीक्षिताम्", text: "bhūmimuddiśya yatproktaṃ tatsarvaṃ tatra ceṣyate na ca kanyāmaviditāṃ saṃspṛśedaparīkṣitām" },
      { type: "verse", number: "54", sanskrit: "विविधान् कुर्वते योगान् कुशलाः खलु मानवाः आजन्मविषसंयोगात् कन्या विषमयीकृता", text: "vividhān kurvate yogān kuśalāḥ khalu mānavāḥ ājanmaviṣasaṃyogāt kanyā viṣamayīkṛtā" },
      { type: "verse", number: "55", sanskrit: "स्पर्शोच्छ्वासादिभिर्हन्ति तस्यास्त्वेतत्परीक्षणम् तद्धस्तकेशसंस्पर्शान्म्लायते पुष्पपल्लवैः", text: "sparśocchvāsādibhirhanti tasyāstvetatparīkṣaṇam taddhastakeśasaṃsparśānmlāyate puṣpapallavaiḥ" },
      { type: "verse", number: "56", sanskrit: "शय्यायां मत्कुणैर्वस्त्रे यूकाभिः स्नानवारिणि जन्तुभिर्म्रियते ज्ञात्वा तामेवं दूरतस्त्यजेत्", text: "śayyāyāṃ matkuṇairvastre yūkābhiḥ snānavāriṇi jantubhirmriyate jñātvā tāmevaṃ dūratastyajet" },
      { type: "verse", number: "57", sanskrit: "नाप्रोक्षितं नाविदितं भिषजा नानवेक्षितम् नाप्राशितं च सूदाद्यैः किञ्चिदप्याहरेन्नृपः", text: "nāprokṣitaṃ nāviditaṃ bhiṣajā nānavekṣitam nāprāśitaṃ ca sūdādyaiḥ kiñcidapyāharennṛpaḥ" },
      { type: "verse", number: "58", sanskrit: "धन्यं सर्वार्थसिद्धाख्यं पापरक्षोविषापहम् परं चक्षुष्यमायुष्यं शत्रुघ्नं वक्ष्यते ऽञ्जनम्", text: "dhanyaṃ sarvārthasiddhākhyaṃ pāparakṣoviṣāpaham paraṃ cakṣuṣyamāyuṣyaṃ śatrughnaṃ vakṣyate 'ñjanam" },
      { type: "verse", number: "59", sanskrit: "अथ शुक्लपक्षे पुण्ये ऽहनि पुष्यपुनर्वसुहस्तचित्रामृगशिरःश्रवणरेवतीशतभिषक्प्राजापत्योत्तराणामन्यतमेन नक्षत्रेण योगमुपगते भगवत्यौषधिपतौ प्रशस्ते मुहूर्ते सिन्धुस्रोतःसमुत्थंस्निग्धं सप्रभं गन्धवर्णच्छदैर्नीलोत्पलाभमञ्जनमाहरेत् तस्याष्टौ भागाः कनकरजतोदुम्बराणामेकैको भागः तत्सर्वं मूषायां प्रक्षिप्य बलिमङ्गलपूर्वकमग्निमुपसामाधाय खदिरकदरधवस्यन्दनानामन्यतमदारुभिगोमयैर्वा प्रज्वालयेत् ततश्चार्यावलोकितेश्वरमार्यतारां ब्रह्मदक्षाश्विरुद्रेन्द्रदित्यसोमवरुणवैश्वानरवायुविष्णुजनकभरद्वाजधन्वन्तरिसुश्रुतभव्यसुकन्यास्कन्दश्च्यवनवैनतेयानन्यांश्च यथाविध्युक्तदेवताः सुमनो ऽक्षतलाजस्वस्तिकसंयावनिस्तुषयवसंस्कृतगुडघृतमिश्रपायसैरर्चयित्वावृद्धवैद्यब्रह्मणांश्च शुक्लवाससो महतीभिर्दक्षिणाभिः पूजयित्वा तस्मिन्नग्नौ तदञ्जनं ध्मातं ध्मातमावृत्य पृथक्पृथङ्निषेचयेत् गोशकृद्रसमूत्रघृतदधिक्षौद्रवसामज्जतैलमद्यसर्वगन्धाम्बुशर्करोदकेक्षुरसेषु तथा हरीतक्यामलकबिभीतककाश्मर्यमृद्वीकाशृङ्गाटककशेरुकोत्पलनलिनसौगन्धिकमृणालिकक्वाथेषु तथा लावकपिञ्जलैणशशहरिणकुलीररसेषु तथा मधुकचन्दनकालानुसार्यनलदपद्मकोशीरमञ्जिष्ठानन्तागैरिककुङ्कुमोदकेषु ततः शुक्ले वाससि बध्वा द्वादशरात्र मान्तरिक्षे ऽम्भासि वासयेत् ततश्छायायां विशोष्य स्फटिकमुक्ताप्रवालकालनुसार्याप्रतीवापं पुनरपि बलिमङ्गलपूर्वकमहतवाससा कन्यया दृषदि पेषयित्वासुवर्णरजतताम्रशङ्खशैलद्विरदरदनगवयशृङ्गवैडूर्यस्फटिकमेषशृङ्ग्यसनसारान्यतमघट्टितायामञ्जनिकायां निधापयेत् अथ पूर्ववत्पुनरपि कृतस्वस्त्ययनं सावित्रेण कर्मणा सर्ववित् द्विजन्मा विधिवत्तदभिसंस्कुर्यात् ततो गजस्कन्धमारोप्य पाण्डुरच्छत्रचामरबालव्यजनैरनुगतं तथा शङ्खदुन्दुभिस्वनैर्द्विजातिवरप्रयुक्तैश्च वेदवादमिश्रैः पुण्याहघोषैः कृतपुष्पोपहारं वैद्यगृहान्नायकगृहमनुप्रवेशयेत् अनन्तरं च तेन विदेहाधिपोपदिष्टेन सर्वार्थेषु सिद्धेनाञ्जनेन यथोक्तानामेवाञ्जनभाजनद्रव्याणामन्यतमया शलाकया गोब्राह्मणपूजापूर्वकं शुचिः सनियमो भूत्वा धारणीमिमां विद्यामधीयानः पूतः पूर्वमक्षि दक्षिणमञ्जयेत्", text: "atha śuklapakṣe puṇye 'hani puṣyapunarvasuhastacitrāmṛgaśiraḥśravaṇarevatīśatabhiṣakprājāpatyottarāṇāmanyatamena nakṣatreṇa yogamupagate bhagavatyauṣadhipatau praśaste muhūrte sindhusrotaḥsamutthaṃsnigdhaṃ saprabhaṃ gandhavarṇacchadairnīlotpalābhamañjanamāharet tasyāṣṭau bhāgāḥ kanakarajatodumbarāṇāmekaiko bhāgaḥ tatsarvaṃ mūṣāyāṃ prakṣipya balimaṅgalapūrvakamagnimupasāmādhāya khadirakadaradhavasyandanānāmanyatamadārubhigomayairvā prajvālayet tataścāryāvalokiteśvaramāryatārāṃ brahmadakṣāśvirudrendradityasomavaruṇavaiśvānaravāyuviṣṇujanakabharadvājadhanvantarisuśrutabhavyasukanyāskandaścyavanavainateyānanyāṃśca yathāvidhyuktadevatāḥ sumano 'kṣatalājasvastikasaṃyāvanistuṣayavasaṃskṛtaguḍaghṛtamiśrapāyasairarcayitvāvṛddhavaidyabrahmaṇāṃśca śuklavāsaso mahatībhirdakṣiṇābhiḥ pūjayitvā tasminnagnau tadañjanaṃ dhmātaṃ dhmātamāvṛtya pṛthakpṛthaṅniṣecayet gośakṛdrasamūtraghṛtadadhikṣaudravasāmajjatailamadyasarvagandhāmbuśarkarodakekṣuraseṣu tathā harītakyāmalakabibhītakakāśmaryamṛdvīkāśṛṅgāṭakakaśerukotpalanalinasaugandhikamṛṇālikakvātheṣu tathā lāvakapiñjalaiṇaśaśahariṇakulīraraseṣu tathā madhukacandanakālānusāryanaladapadmakośīramañjiṣṭhānantāgairikakuṅkumodakeṣu tataḥ śukle vāsasi badhvā dvādaśarātra māntarikṣe 'mbhāsi vāsayet tataśchāyāyāṃ viśoṣya sphaṭikamuktāpravālakālanusāryāpratīvāpaṃ punarapi balimaṅgalapūrvakamahatavāsasā kanyayā dṛṣadi peṣayitvāsuvarṇarajatatāmraśaṅkhaśailadviradaradanagavayaśṛṅgavaiḍūryasphaṭikameṣaśṛṅgyasanasārānyatamaghaṭṭitāyāmañjanikāyāṃ nidhāpayet atha pūrvavatpunarapi kṛtasvastyayanaṃ sāvitreṇa karmaṇā sarvavit dvijanmā vidhivattadabhisaṃskuryāt tato gajaskandhamāropya pāṇḍuracchatracāmarabālavyajanairanugataṃ tathā śaṅkhadundubhisvanairdvijātivaraprayuktaiśca vedavādamiśraiḥ puṇyāhaghoṣaiḥ kṛtapuṣpopahāraṃ vaidyagṛhānnāyakagṛhamanupraveśayet anantaraṃ ca tena videhādhipopadiṣṭena sarvārtheṣu siddhenāñjanena yathoktānāmevāñjanabhājanadravyāṇāmanyatamayā śalākayā gobrāhmaṇapūjāpūrvakaṃ śuciḥ saniyamo bhūtvā dhāraṇīmimāṃ vidyāmadhīyānaḥ pūtaḥ pūrvamakṣi dakṣiṇamañjayet" },
      { type: "verse", number: "60", sanskrit: "अथ मन्त्रः नमश्चक्षुःपरिशोधनराजाय तथागतायर्हते सम्यक्सम्बुद्धाय तद्यथा औं चक्षुः प्रज्ञाचक्षुर्ज्ञानचक्षुर्विज्ञानचक्षुर्विशोधय स्वाहा", text: "atha mantraḥ namaścakṣuḥpariśodhanarājāya tathāgatāyarhate samyaksambuddhāya tadyathā auṃ cakṣuḥ prajñācakṣurjñānacakṣurvijñānacakṣurviśodhaya svāhā" },
      { type: "verse", number: "61", sanskrit: "ततः परं च तामेव धारिणीमनुस्मरन् सायम्प्रातः पत्यहमेतत्परमं पवित्रमारोग्यकरमूर्जस्करं सर्वविषघ्नमञ्जनमश्विभ्यामिन्द्रस्य वृत्रवधाभ्युद्यतस्य प्राक्प्रकल्पितम् तस्मोदतद्राज्ञां राजमहामात्राणां च महीं विजगीषमाणानां च ब्राह्मणानां च वेदाध्ययनमन्यद्वा महच्छास्त्रमवगाहमानानां प्रसन्नमना भिषक्प्रकल्पयेदिति भवन्ति चात्र श्लोकाः", text: "tataḥ paraṃ ca tāmeva dhāriṇīmanusmaran sāyamprātaḥ patyahametatparamaṃ pavitramārogyakaramūrjaskaraṃ sarvaviṣaghnamañjanamaśvibhyāmindrasya vṛtravadhābhyudyatasya prākprakalpitam tasmodatadrājñāṃ rājamahāmātrāṇāṃ ca mahīṃ vijagīṣamāṇānāṃ ca brāhmaṇānāṃ ca vedādhyayanamanyadvā mahacchāstramavagāhamānānāṃ prasannamanā bhiṣakprakalpayediti bhavanti cātra ślokāḥ" },
      { type: "verse", number: "62", sanskrit: "अथ योगाः प्रवक्ष्यन्ते बृहस्पतिकृताः शिवाः यान् सेवमानो नृपतिः शत्रुभ्यो नैति पज्चताम्", text: "atha yogāḥ pravakṣyante bṛhaspatikṛtāḥ śivāḥ yān sevamāno nṛpatiḥ śatrubhyo naiti pajcatām" },
      { type: "verse", number: "63", sanskrit: "बिल्वाढकीयवक्षारपाटलीबाल्हिकोषणाः श्रीपर्णीसल्लकीयुक्ता निष्क्वाथः प्रोक्षणः परम्", text: "bilvāḍhakīyavakṣārapāṭalībālhikoṣaṇāḥ śrīparṇīsallakīyuktā niṣkvāthaḥ prokṣaṇaḥ param" },
      { type: "verse", number: "64", sanskrit: "सविषं प्रोक्षितं तेन सद्यो भवति निर्विसम् यवसेन्धनपानीयशस्त्रशय्यासनोदकम्", text: "saviṣaṃ prokṣitaṃ tena sadyo bhavati nirvisam yavasendhanapānīyaśastraśayyāsanodakam" },
      { type: "verse", number: "65", sanskrit: "कवचाभरणच्छत्रबालव्यजनवेश्म च शेलुपाटल्यतिविषाशिग्रुगोपीपुनर्नवम्", text: "kavacābharaṇacchatrabālavyajanaveśma ca śelupāṭalyativiṣāśigrugopīpunarnavam" },
      { type: "verse", number: "66", sanskrit: "समङ्गावृषमूलत्वक्कपित्थवृषशोणितम् सहदन्तशठं तद्वत् प्रोक्षणं विषनाशनम्", text: "samaṅgāvṛṣamūlatvakkapitthavṛṣaśoṇitam sahadantaśaṭhaṃ tadvat prokṣaṇaṃ viṣanāśanam" },
      { type: "verse", number: "67", sanskrit: "लाक्षाप्रियङ्गुमञ्जिष्ठासमङ्गालहरेणुकाः यष्ट्याह्वमधुसंयुक्ता बब्रुपित्तेन कल्किताः", text: "lākṣāpriyaṅgumañjiṣṭhāsamaṅgālahareṇukāḥ yaṣṭyāhvamadhusaṃyuktā babrupittena kalkitāḥ" },
      { type: "verse", number: "68", sanskrit: "निखनेद्गोविषाणस्थाः सप्तरात्रं महीतले ततः कृत्वा मणिं हेम्ना बद्धं हस्तेन धारयेत्", text: "nikhanedgoviṣāṇasthāḥ saptarātraṃ mahītale tataḥ kṛtvā maṇiṃ hemnā baddhaṃ hastena dhārayet" },
      { type: "verse", number: "69", sanskrit: "संस्पृष्टं सविषं तेन सद्यो भवति निर्विषम् मनोह्वालशमीपुष्पत्वङ्निशाश्वेतसर्षपाः", text: "saṃspṛṣṭaṃ saviṣaṃ tena sadyo bhavati nirviṣam manohvālaśamīpuṣpatvaṅniśāśvetasarṣapāḥ" },
      { type: "verse", number: "70", sanskrit: "कपित्थकुष्ठमञ्जिष्ठाः पित्तेन श्लक्ष्णकल्किताः शुनो गोःकपिलायाश्च सौम्याख्यो ऽयं वरो ऽगदः", text: "kapitthakuṣṭhamañjiṣṭhāḥ pittena ślakṣṇakalkitāḥ śuno goḥkapilāyāśca saumyākhyo 'yaṃ varo 'gadaḥ" },
      { type: "verse", number: "71", sanskrit: "विषजित्परमं कार्यो मणिरत्नं च पूर्ववत् मूषिकाजरुहा वापि हस्तबद्धा विषापहाः", text: "viṣajitparamaṃ kāryo maṇiratnaṃ ca pūrvavat mūṣikājaruhā vāpi hastabaddhā viṣāpahāḥ" },
      { type: "verse", number: "72", sanskrit: "हरेणुमांसीमञ्जिष्ठारजनीमधुकं मधु अक्षत्वक्सुरस्ं लाक्षा श्वपित्तं पूर्ववन्मणिः", text: "hareṇumāṃsīmañjiṣṭhārajanīmadhukaṃ madhu akṣatvaksurasṃ lākṣā śvapittaṃ pūrvavanmaṇiḥ" },
      { type: "verse", number: "73", sanskrit: "वादित्राणि पताकाश्च पिष्टैरोभिश्च लेखिताः श्रुत्वा दृष्ट्वा समाघ्राय सद्यो भवति निर्विषम्", text: "vāditrāṇi patākāśca piṣṭairobhiśca lekhitāḥ śrutvā dṛṣṭvā samāghrāya sadyo bhavati nirviṣam" },
      { type: "verse", number: "74", sanskrit: "त्र्यूषणं पञ्चलवणं मञ्जिष्ठां रजनीद्वयम् सूक्ष्मैलां त्रिवृतां पत्रं विडङ्गानीन्द्रवारुणीम्", text: "tryūṣaṇaṃ pañcalavaṇaṃ mañjiṣṭhāṃ rajanīdvayam sūkṣmailāṃ trivṛtāṃ patraṃ viḍaṅgānīndravāruṇīm" },
      { type: "verse", number: "75", sanskrit: "मधुकं चेति सक्षौद्रं गोविषाणे निधापयेत् तस्मादुष्णाम्बुना मात्रां प्राग्भक्तं विनियोजयेत्", text: "madhukaṃ ceti sakṣaudraṃ goviṣāṇe nidhāpayet tasmāduṣṇāmbunā mātrāṃ prāgbhaktaṃ viniyojayet" },
      { type: "verse", number: "76", sanskrit: "विषं भुक्तं जरां याति निर्विषे ऽपि न दोषकृत् जतुसर्जरसोशीरसर्षपा पत्रवालकैः", text: "viṣaṃ bhuktaṃ jarāṃ yāti nirviṣe 'pi na doṣakṛt jatusarjarasośīrasarṣapā patravālakaiḥ" },
      { type: "verse", number: "77", sanskrit: "सवेल्लारुष्करपुरैः कुसुमैरर्जुनस्य च धूपो वासगृहे हन्ति विषं स्थावरजङ्गमम्", text: "savellāruṣkarapuraiḥ kusumairarjunasya ca dhūpo vāsagṛhe hanti viṣaṃ sthāvarajaṅgamam" },
      { type: "verse", number: "78", sanskrit: "न तत्र कीटाः सविषा नोन्दुरा न सरीसृपाः न कृत्या कर्षणा(कार्मणा)द्याश्च धूपो ऽयं यत्र दह्यते", text: "na tatra kīṭāḥ saviṣā nondurā na sarīsṛpāḥ na kṛtyā karṣaṇā(kārmaṇā)dyāśca dhūpo 'yaṃ yatra dahyate" },
      { type: "verse", number: "79", sanskrit: "शिखिपिञ्छं बलाकास्थि सर्षपाश्चन्दनं घृतम् धूपो विषघ्नः शयनवसनासनगेहगः", text: "śikhipiñchaṃ balākāsthi sarṣapāścandanaṃ ghṛtam dhūpo viṣaghnaḥ śayanavasanāsanagehagaḥ" },
      { type: "verse", number: "80", sanskrit: "विशालाव्योषमञ्जिष्ठायष्टीलवणपञ्चकम् द्विनिशापत्रवेल्लैलात्रिवृच्चूर्णं समाक्षिकम्", text: "viśālāvyoṣamañjiṣṭhāyaṣṭīlavaṇapañcakam dviniśāpatravellailātrivṛccūrṇaṃ samākṣikam" },
      { type: "verse", number: "81", sanskrit: "गोशृङ्गे निहितं योज्यं स्नानीये ऽम्भसि भूपतेः पूर्वोकतत्र्यूषणादिं च स्नानीये ऽम्भसि योजयेत्", text: "gośṛṅge nihitaṃ yojyaṃ snānīye 'mbhasi bhūpateḥ pūrvokatatryūṣaṇādiṃ ca snānīye 'mbhasi yojayet" },
      { type: "verse", number: "82", sanskrit: "क्वाथो ऽथवार्ककुसुमश्वेतापामार्गसर्षपैः सदध्याज्यः कृतो युक्तैः कतकानाकुलीद्वयैः", text: "kvātho 'thavārkakusumaśvetāpāmārgasarṣapaiḥ sadadhyājyaḥ kṛto yuktaiḥ katakānākulīdvayaiḥ" },
      { type: "verse", number: "83", sanskrit: "कल्को वा चन्दनक्षीरिपलाशद्रुमवल्कलैः मूर्वैलावालुसुरसनाकुलीतण्डुलीयकैः", text: "kalko vā candanakṣīripalāśadrumavalkalaiḥ mūrvailāvālusurasanākulītaṇḍulīyakaiḥ" },
      { type: "verse", number: "84", sanskrit: "क्वाथः सर्वोदकार्थेषु काकमाचीयुतैर्हितः रोचनापत्ननैपालीकुङ्कुमैस्तिलकान् वहन्", text: "kvāthaḥ sarvodakārtheṣu kākamācīyutairhitaḥ rocanāpatnanaipālīkuṅkumaistilakān vahan" },
      { type: "verse", number: "85", sanskrit: "विषैर्न बाध्यते स्याच्च नारीनरनृपप्रियः चूर्णैर्हरिद्रामञ्जिष्ठाकिणिहीकणनिम्बजैः", text: "viṣairna bādhyate syācca nārīnaranṛpapriyaḥ cūrṇairharidrāmañjiṣṭhākiṇihīkaṇanimbajaiḥ" },
      { type: "verse", number: "86", sanskrit: "दिग्धं निर्विषतामेति गात्रमित्याह गौतमः नस्यपानाञ्जनालेपैर्युञ्ज्यात् सञ्जीवनात्मकान्", text: "digdhaṃ nirviṣatāmeti gātramityāha gautamaḥ nasyapānāñjanālepairyuñjyāt sañjīvanātmakān" },
      { type: "verse", number: "87", sanskrit: "अगदान् विषभुक्तस्य तीक्ष्णानि वमनानि च पिप्पलीमधुकक्षौद्रशर्करेक्षुरसैः सह", text: "agadān viṣabhuktasya tīkṣṇāni vamanāni ca pippalīmadhukakṣaudraśarkarekṣurasaiḥ saha" },
      { type: "verse", number: "88", sanskrit: "द्विनिशापत्रवेल्लैलात्रिवृच्चूर्णं समाक्षिकम् विरेचनं सिरामोक्षं प्राप्तं विस्रावणं यदि", text: "dviniśāpatravellailātrivṛccūrṇaṃ samākṣikam virecanaṃ sirāmokṣaṃ prāptaṃ visrāvaṇaṃ yadi" },
      { type: "verse", number: "89", sanskrit: "हृदयावरणं कार्यं प्रागेवामित्रमध्यतः पिबेद्घृतमजेयाख्यममृतं वाप्यभुक्तवान्", text: "hṛdayāvaraṇaṃ kāryaṃ prāgevāmitramadhyataḥ pibedghṛtamajeyākhyamamṛtaṃ vāpyabhuktavān" },
      { type: "verse", number: "90", sanskrit: "सर्पिः क्षौद्रं दधि क्षीरमन्ततः शीतलं जलम् सितामधुकपालिन्दीकल्कवन्मांसमिष्यते", text: "sarpiḥ kṣaudraṃ dadhi kṣīramantataḥ śītalaṃ jalam sitāmadhukapālindīkalkavanmāṃsamiṣyate" },
      { type: "verse", number: "91", sanskrit: "गोधाहरिणबभ्रूणां सकणाशुण्ठिपार्षतम् सनागरं सातिविषं शिखिनः ससितोपलम्", text: "godhāhariṇababhrūṇāṃ sakaṇāśuṇṭhipārṣatam sanāgaraṃ sātiviṣaṃ śikhinaḥ sasitopalam" },
      { type: "verse", number: "92", sanskrit: "सुशीताः सघृताश्चैषां यथास्वं कल्पिता रसाः विषपीताय दद्याच्च शुद्धायोर्ध्वमधस्तथा", text: "suśītāḥ saghṛtāścaiṣāṃ yathāsvaṃ kalpitā rasāḥ viṣapītāya dadyācca śuddhāyordhvamadhastathā" },
      { type: "verse", number: "93", sanskrit: "सूक्ष्मं ताम्ररजः काले सक्षौद्रं हृद्विशोधनम् शुद्धे हृदि ततः शाणं हेमचूर्णस्य दापयेत्", text: "sūkṣmaṃ tāmrarajaḥ kāle sakṣaudraṃ hṛdviśodhanam śuddhe hṛdi tataḥ śāṇaṃ hemacūrṇasya dāpayet" },
      { type: "verse", number: "94", sanskrit: "न सज्जते हेमपाङ्गे पद्मपत्रे ऽम्बुवद्विषम् जायते विपुलं चायुर्गरे ऽप्येष विधिः स्मृतः", text: "na sajjate hemapāṅge padmapatre 'mbuvadviṣam jāyate vipulaṃ cāyurgare 'pyeṣa vidhiḥ smṛtaḥ" },
      { type: "verse", number: "95", sanskrit: "इत्थं गरविषादिभ्यो रक्षेद्वैद्यो नरेश्चरम् स्यादुच्छेदस्तदुच्छेदात्प्रजानां सर्वकर्मणाम्", text: "itthaṃ garaviṣādibhyo rakṣedvaidyo nareścaram syāducchedastaducchedātprajānāṃ sarvakarmaṇām" },
      { type: "verse", number: "96", sanskrit: "आज्ञाधैर्यक्षमात्यागा मानुषत्वे ऽप्यमानुषाः यद्राज्ञः कर्मभिस्तस्मादाराध्यो ऽसावतीन्द्रियैः", text: "ājñādhairyakṣamātyāgā mānuṣatve 'pyamānuṣāḥ yadrājñaḥ karmabhistasmādārādhyo 'sāvatīndriyaiḥ" },
      { type: "verse", number: "97", sanskrit: "यत्र साक्षन्नृपस्तत्र विज्ञातः प्रविशोद्भिषक् न सम्मतो ऽप्यनुचितं यानस्थानासनं भजेत्", text: "yatra sākṣannṛpastatra vijñātaḥ praviśodbhiṣak na sammato 'pyanucitaṃ yānasthānāsanaṃ bhajet" },
      { type: "verse", number: "98", sanskrit: "उचिते पुरतो राज्ञस्तिष्ठेद्वाक्यं च नाक्षिपेत् अहीनकालं राजार्थं स्वार्थं प्रियहितैः सह", text: "ucite purato rājñastiṣṭhedvākyaṃ ca nākṣipet ahīnakālaṃ rājārthaṃ svārthaṃ priyahitaiḥ saha" },
      { type: "verse", number: "99", sanskrit: "देशे काले परार्थं च वदेद्धर्मार्थसंहितम् नानुशिष्यादपृच्छन्तं महदेतद्धि साहसम्", text: "deśe kāle parārthaṃ ca vadeddharmārthasaṃhitam nānuśiṣyādapṛcchantaṃ mahadetaddhi sāhasam" },
      { type: "verse", number: "100", sanskrit: "नाचरेदहितेनैनं मूलच्छेदकरं हि तत् अनुकूलं हितं वाच्यमहिताद्वारयेन्मिथः", text: "nācaredahitenainaṃ mūlacchedakaraṃ hi tat anukūlaṃ hitaṃ vācyamahitādvārayenmithaḥ" },
      { type: "verse", number: "101", sanskrit: "उदारैः सान्त्वयन् वाक्यैर्दोषश्चेत्तदुपेक्षया तूष्णीं वा प्रतिवाक्ये स्याद्वर्जयेद्वेष्यसङ्कथाम्", text: "udāraiḥ sāntvayan vākyairdoṣaścettadupekṣayā tūṣṇīṃ vā prativākye syādvarjayedveṣyasaṅkathām" },
      { type: "verse", number: "102", sanskrit: "विपश्चिदप्यचित्तज्ञो बालिशो ऽपि तु भाववित् अतिप्रियो ऽपि द्वेष्यो ऽपि यात्याशु विपरीतताम्", text: "vipaścidapyacittajño bāliśo 'pi tu bhāvavit atipriyo 'pi dveṣyo 'pi yātyāśu viparītatām" },
      { type: "verse", number: "103", sanskrit: "निवेद्य राज्ञे कुर्वीत कार्याणि सुलघून्यपि न यायान्न चिरं तिष्ठेत् कोशस्थानावरोधयोः", text: "nivedya rājñe kurvīta kāryāṇi sulaghūnyapi na yāyānna ciraṃ tiṣṭhet kośasthānāvarodhayoḥ" },
      { type: "verse", number: "104", sanskrit: "स्वल्पे ऽपि दर्शयेत्तुष्टिं लाभे ऽनुद्धतमानसः मिथः कथनमन्येन कौलीनं द्वन्द्ववादिताम्", text: "svalpe 'pi darśayettuṣṭiṃ lābhe 'nuddhatamānasaḥ mithaḥ kathanamanyena kaulīnaṃ dvandvavāditām" },
      { type: "verse", number: "105", sanskrit: "वस्त्रादि राज्ञा सदृशं राजलीलां च वर्जयेत् दत्तं यत्तु नृपेणव तद्धार्यं तुष्टिवृद्धये", text: "vastrādi rājñā sadṛśaṃ rājalīlāṃ ca varjayet dattaṃ yattu nṛpeṇava taddhāryaṃ tuṣṭivṛddhaye" },
      { type: "verse", number: "106", sanskrit: "हसितव्ये सिमतं कुर्यात् प्रभोरेवानुवृत्तितः उच्यमाने ऽवलम्बेत परमर्माणि मूकताम्", text: "hasitavye simataṃ kuryāt prabhorevānuvṛttitaḥ ucyamāne 'valambeta paramarmāṇi mūkatām" },
      { type: "verse", number: "107", sanskrit: "स्वमर्मणि तु बाधिर्यं धैर्यमाधुर्यसौष्ठवान् अत्यायासेन नात्मानं कुर्यादतिसमुच्छ्रितम्", text: "svamarmaṇi tu bādhiryaṃ dhairyamādhuryasauṣṭhavān atyāyāsena nātmānaṃ kuryādatisamucchritam" },
      { type: "verse", number: "108", sanskrit: "पातो यथा हि दुःखाय नोच्छ्रायः सुखकृत्तथा आसन्नसेवा नृपतेः क्रीडाशस्त्राहिपावकैः", text: "pāto yathā hi duḥkhāya nocchrāyaḥ sukhakṛttathā āsannasevā nṛpateḥ krīḍāśastrāhipāvakaiḥ" },
      { type: "verse", number: "109", sanskrit: "कौशलेनातिमहता विनीतैः सा निरुध्यते प्राप्य दुष्प्नापमैश्वर्यं बहुमानं च भूपतेः", text: "kauśalenātimahatā vinītaiḥ sā nirudhyate prāpya duṣpnāpamaiśvaryaṃ bahumānaṃ ca bhūpateḥ" },
      { type: "verse", number: "110", sanskrit: "यथोपभुञ्जीत चिरं तथा स्यादप्रमादवान् विदध्यात्परितः शय्यां रक्षामन्त्राभिमन्त्रिताम्", text: "yathopabhuñjīta ciraṃ tathā syādapramādavān vidadhyātparitaḥ śayyāṃ rakṣāmantrābhimantritām" },
      { type: "verse", number: "111", sanskrit: "रात्रौ सिद्धार्थकान् भूतिमक्षतैरन्वितां शुचिम् रक्षाशक्तिं तथोच्छीर्षे सयवाङ्कुरयावकाम्", text: "rātrau siddhārthakān bhūtimakṣatairanvitāṃ śucim rakṣāśaktiṃ tathocchīrṣe sayavāṅkurayāvakām" },
      { type: "verse", number: "112", sanskrit: "सदूर्वं पूर्णकलशं सपुष्पफलपल्लवम् उपहारं च सन्ध्यायां भुक्त्वा चान्ते निशासु च", text: "sadūrvaṃ pūrṇakalaśaṃ sapuṣpaphalapallavam upahāraṃ ca sandhyāyāṃ bhuktvā cānte niśāsu ca" },
      { type: "verse", number: "113", sanskrit: "एतत्स्वस्त्ययनं कर्म कर्तव्यं शुचिना शुचेः आयुस्यं पौष्टिकं भूतविषकार्मणपाप्मजित्", text: "etatsvastyayanaṃ karma kartavyaṃ śucinā śuceḥ āyusyaṃ pauṣṭikaṃ bhūtaviṣakārmaṇapāpmajit" },
      { type: "verse", number: "114", sanskrit: "सङ्क्षेप एष विषपालनसाधनाय प्रोक्तस्तु विस्तरविधिः पुनरुत्तरे तु आलोच्य सम्यगखिलं मतिपूर्वकारी युञ्जीत तं परिविकल्प्य विकारचिह्नम्", text: "saṅkṣepa eṣa viṣapālanasādhanāya proktastu vistaravidhiḥ punaruttare tu ālocya samyagakhilaṃ matipūrvakārī yuñjīta taṃ parivikalpya vikāracihnam" },
      { type: "verse", number: "115", sanskrit: "इति विषगररक्षोरक्षणायोपदेशं भजति नरपतिर्यो नित्यमेवाप्रमत्तः निजपररिपुवृन्दैरप्रधृष्यो महात्मा जनयति जनतायाः क्षेमयोगौ चिराय", text: "iti viṣagararakṣorakṣaṇāyopadeśaṃ bhajati narapatiryo nityamevāpramattaḥ nijapararipuvṛndairapradhṛṣyo mahātmā janayati janatāyāḥ kṣemayogau cirāya" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 9,
    lang: "sa",
    content: [
      { type: "heading", heading: "Свэда видхи — потогонная терапия" },
      { type: "text", text: "Глава 9 Сутрастханы Астанга-санграхи посвящена теме «потогонная терапия». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो विरुद्धान्नविज्ञानीयमध्यायं व्याख्यास्यामः इति हस्माहुरात्रेयादयो महर्षयः", text: "athāto viruddhānnavijñānīyamadhyāyaṃ vyākhyāsyāmaḥ iti hasmāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "ग्राम्यानूपौदकपिशितानि मधुगुडतिलपयोमाषमूलकबिसैर्विरूढधान्यैश्च नैकध्यमद्यात् विशेषतः पयसा मत्स्यान् उभयं ह्येतन्मधुररसविपाकित्वादभिष्यन्दि शीतोष्णवीर्यत्वात् परस्परं विरुद्धम् तेष्वपि विशेषेण चिलिचिमः स पुनः शकली लोहितनयनः सर्वतो लोहितराजिर्लोहितप्रभाकरः प्रायो भूमौ चरति सो ऽत्याभिष्यन्दितमत्वात् सुतरां व्याधीनुपजनयत्यामविषं च", text: "grāmyānūpaudakapiśitāni madhuguḍatilapayomāṣamūlakabisairvirūḍhadhānyaiśca naikadhyamadyāt viśeṣataḥ payasā matsyān ubhayaṃ hyetanmadhurarasavipākitvādabhiṣyandi śītoṣṇavīryatvāt parasparaṃ viruddham teṣvapi viśeṣeṇa cilicimaḥ sa punaḥ śakalī lohitanayanaḥ sarvato lohitarājirlohitaprabhākaraḥ prāyo bhūmau carati so 'tyābhiṣyanditamatvāt sutarāṃ vyādhīnupajanayatyāmaviṣaṃ ca" },
      { type: "verse", number: "3", sanskrit: "सर्वं चाम्लं पयसैकध्यं विरुद्धम् तत उत्तरं वा विरुद्धं फलञ्च कङ्गुवरकमकुष्ठवेल्लकुलत्थमाषनिष्पावाश्च नमूलकदिहरितं भक्षयित्वा पयः सेव्यं कुष्ठाबाधभयात् पौष्करं रौहिणीकं जातुकं वा शाकं सह मधुप्योभ्यां नाभ्यवहरेत् ताभ्यां च सह कपोतान् सर्षपतैलभृष्टान् तथा सर्षपतैलभृष्टानां मत्स्यबदराणां बदराणि श्वाविद्वराहमांसं चैकध्यं पित्तेनाममांसानि दध्ना कुक्कुटं पृषतं च कुसुम्भशाकेनैरौरभ्रं सौवीरकेण तिलशष्कुलीः क्षीरेण लवणं मूलकेन माषसूपं नवनीतेन शाकं उपोदकां मैरेयमार्द्वीकाभ्यां पीलूनि करीरैः बिसैर्विरूढकानि दध्ना माषसूपेन गुडेन मधुना घृतेन वा लकुचफलं दध्ना तक्रेण गुडेन वा काकमाचीं तामेव मत्स्यपचने शृङ्गिवेरपचने वा भाजने सिद्धामन्यत्र वा सिद्धां रात्रिमुषितां कांस्यभाजने दशरात्रोषितं सर्पिर्मद्यदधिमधुभल्लातकेषु चोष्णम्", text: "sarvaṃ cāmlaṃ payasaikadhyaṃ viruddham tata uttaraṃ vā viruddhaṃ phalañca kaṅguvarakamakuṣṭhavellakulatthamāṣaniṣpāvāśca namūlakadiharitaṃ bhakṣayitvā payaḥ sevyaṃ kuṣṭhābādhabhayāt pauṣkaraṃ rauhiṇīkaṃ jātukaṃ vā śākaṃ saha madhupyobhyāṃ nābhyavaharet tābhyāṃ ca saha kapotān sarṣapatailabhṛṣṭān tathā sarṣapatailabhṛṣṭānāṃ matsyabadarāṇāṃ badarāṇi śvāvidvarāhamāṃsaṃ caikadhyaṃ pittenāmamāṃsāni dadhnā kukkuṭaṃ pṛṣataṃ ca kusumbhaśākenairaurabhraṃ sauvīrakeṇa tilaśaṣkulīḥ kṣīreṇa lavaṇaṃ mūlakena māṣasūpaṃ navanītena śākaṃ upodakāṃ maireyamārdvīkābhyāṃ pīlūni karīraiḥ bisairvirūḍhakāni dadhnā māṣasūpena guḍena madhunā ghṛtena vā lakucaphalaṃ dadhnā takreṇa guḍena vā kākamācīṃ tāmeva matsyapacane śṛṅgiverapacane vā bhājane siddhāmanyatra vā siddhāṃ rātrimuṣitāṃ kāṃsyabhājane daśarātroṣitaṃ sarpirmadyadadhimadhubhallātakeṣu coṣṇam" },
      { type: "verse", number: "4", sanskrit: "तक्रसिद्धकाम्पिल्लको विरुद्धः अङ्गारशूल्यो भासः सुराकृसरापायसाश्चैकध्यं विरुद्धाः", text: "takrasiddhakāmpillako viruddhaḥ aṅgāraśūlyo bhāsaḥ surākṛsarāpāyasāścaikadhyaṃ viruddhāḥ" },
      { type: "verse", number: "5", sanskrit: "मधुसर्पिर्वसातैलोदकानि समधृतानि द्विशस्त्रिशः समस्तानि वा मधुघृते भिन्नांशे दिव्योदकानुपाने मधुपुष्करबीजं पद्मोत्तरिकाशाकं शार्करो मैरयो मधु च सहोपयुक्तं विरुद्धम् वातं चातिकोपयति हारिद्रकः सर्षपतैलभृष्टो विरुद्धः पित्तं चातिकोपयति पायसो मन्थानुपानो विरुद्धः श्लेष्माणं चातिकोपयति उपोदका तिलकल्कसिद्धा हेतुरतीसारस्य बलाका वारुण्या कुल्माषैश्च विरुध्दा सैव वराहवसया परिभृष्टा सद्यो व्यापादयति गोधालावंतित्तिरिमयूरकपिञ्जलाश्चैरण्डदार्वग्निसिद्धा एरण्डतैलसम्मूर्छिताः हारीतमांसं हारिद्रशूलकावसक्तं हारिद्राग्निप्लुष्टं च तदेव भस्मपांसुपरिध्वस्तं सक्षौद्रं च", text: "madhusarpirvasātailodakāni samadhṛtāni dviśastriśaḥ samastāni vā madhughṛte bhinnāṃśe divyodakānupāne madhupuṣkarabījaṃ padmottarikāśākaṃ śārkaro mairayo madhu ca sahopayuktaṃ viruddham vātaṃ cātikopayati hāridrakaḥ sarṣapatailabhṛṣṭo viruddhaḥ pittaṃ cātikopayati pāyaso manthānupāno viruddhaḥ śleṣmāṇaṃ cātikopayati upodakā tilakalkasiddhā heturatīsārasya balākā vāruṇyā kulmāṣaiśca virudhdā saiva varāhavasayā paribhṛṣṭā sadyo vyāpādayati godhālāvaṃtittirimayūrakapiñjalāścairaṇḍadārvagnisiddhā eraṇḍatailasammūrchitāḥ hārītamāṃsaṃ hāridraśūlakāvasaktaṃ hāridrāgnipluṣṭaṃ ca tadeva bhasmapāṃsuparidhvastaṃ sakṣaudraṃ ca" },
      { type: "verse", number: "6", sanskrit: "तथा मत्स्यनिस्तालितस्नेहसाधिताः पिप्पल्यः शीतोष्णं नवपुराणमामपक्वं च नैकमैकध्यमद्यात् सलिलावगाहः सहसोष्णाभितप्तस्य त्वग्दृष्ट्योरुपघाताय तृष्णाभिप्रवृद्धये च तथैव च पयःपानं रक्तपित्ताय शरीरेणायस्तस्य सहसाभ्यवहारः छर्दिषे गुल्माय वा वाचा त्वायस्तस्य स्वरसादाय इत्यन्नपानद्रव्यविरोधैकदेशो बाहुल्येनोपयोगी कथितः भेषजद्रव्याणां तु यथोपदेशमेव प्रयोगो न्याय्यतरः तद्विरोधः पुनरतिप्रसङ्गभयान्नोक्तः न च तद्विज्ञानमेकान्तभद्रकं", text: "tathā matsyanistālitasnehasādhitāḥ pippalyaḥ śītoṣṇaṃ navapurāṇamāmapakvaṃ ca naikamaikadhyamadyāt salilāvagāhaḥ sahasoṣṇābhitaptasya tvagdṛṣṭyorupaghātāya tṛṣṇābhipravṛddhaye ca tathaiva ca payaḥpānaṃ raktapittāya śarīreṇāyastasya sahasābhyavahāraḥ chardiṣe gulmāya vā vācā tvāyastasya svarasādāya ityannapānadravyavirodhaikadeśo bāhulyenopayogī kathitaḥ bheṣajadravyāṇāṃ tu yathopadeśameva prayogo nyāyyataraḥ tadvirodhaḥ punaratiprasaṅgabhayānnoktaḥ na ca tadvijñānamekāntabhadrakaṃ" },
      { type: "verse", number: "7", sanskrit: "अपिच उत्क्लेश्य दोषान्न हरेत् द्रव्यं यत्तत्समासतः विरुद्धं तद्धि धातूनां प्रत्यनीकतया स्थितम्", text: "apica utkleśya doṣānna haret dravyaṃ yattatsamāsataḥ viruddhaṃ taddhi dhātūnāṃ pratyanīkatayā sthitam" },
      { type: "verse", number: "8", sanskrit: "बलिनां मिथोगुणानां विषमतया समतयाप्युभयथापि संस्कारादिवशेन च भवति निसर्गादपि विरोधः", text: "balināṃ mithoguṇānāṃ viṣamatayā samatayāpyubhayathāpi saṃskārādivaśena ca bhavati nisargādapi virodhaḥ" },
      { type: "verse", number: "9", sanskrit: "क्षीरं कुलत्थैः पनसेन मत्स्यैस्तप्तं दधि क्षौद्रघृते समांशे वार्यूषरे रात्रिषु सक्तवश्च तोयान्तरास्ते यवकास्तथा च", text: "kṣīraṃ kulatthaiḥ panasena matsyaistaptaṃ dadhi kṣaudraghṛte samāṃśe vāryūṣare rātriṣu saktavaśca toyāntarāste yavakāstathā ca" },
      { type: "verse", number: "10", sanskrit: "कुशाग्रीयधियामेतदुदाहरणमात्रकम् उपनीतमलं विद्धान् सर्वत्र क्रमते यतः", text: "kuśāgrīyadhiyāmetadudāharaṇamātrakam upanītamalaṃ viddhān sarvatra kramate yataḥ" },
      { type: "verse", number: "11", sanskrit: "विस्फोटशोफमदविद्रधिगुल्मयक्ष्मतेजोबलस्मृतिमतीन्द्रियचित्तनाशान् कुर्याद्विरुद्धमशनं ज्वरमस्त्रपित्तमष्टौ गदांश्च महतो विषवच्च मृत्युम्", text: "visphoṭaśophamadavidradhigulmayakṣmatejobalasmṛtimatīndriyacittanāśān kuryādviruddhamaśanaṃ jvaramastrapittamaṣṭau gadāṃśca mahato viṣavacca mṛtyum" },
      { type: "verse", number: "12", sanskrit: "तेष्वाशु कुर्यात्संशुद्धिं शमं वा तद्विरोधिभिः द्रव्यैस्तैरेव वा पूर्वं शरीरस्याभिसंस्कृतिम्", text: "teṣvāśu kuryātsaṃśuddhiṃ śamaṃ vā tadvirodhibhiḥ dravyaistaireva vā pūrvaṃ śarīrasyābhisaṃskṛtim" },
      { type: "verse", number: "13", sanskrit: "व्यायामस्निग्धदीप्ताग्निवयस्थबलशालिनाम् विरोध्यपि न पीडायैसात्म्यमल्पं च भोजनम्", text: "vyāyāmasnigdhadīptāgnivayasthabalaśālinām virodhyapi na pīḍāyaisātmyamalpaṃ ca bhojanam" },
      { type: "verse", number: "14", sanskrit: "दोषादिवैपरीत्येन हरते रोगिणां रुजम् ऐकध्यं दधिदुग्धादियोजना न विरुध्यते", text: "doṣādivaiparītyena harate rogiṇāṃ rujam aikadhyaṃ dadhidugdhādiyojanā na virudhyate" },
      { type: "verse", number: "15", sanskrit: "योगादिभेदाद्यद्यद्वा पथ्यानामप्यपथ्यता तद्भेदान्तरतस्तद्वद्विरोधो ऽपि निवर्त्तते", text: "yogādibhedādyadyadvā pathyānāmapyapathyatā tadbhedāntaratastadvadvirodho 'pi nivarttate" },
      { type: "verse", number: "16", sanskrit: "पादांशेन त्यजेत्सात्म्यमहितं हितमाचरेत् एकान्तरं ततश्चोर्ध्वं द्व्यन्तरं त्र्यन्तरं तथा", text: "pādāṃśena tyajetsātmyamahitaṃ hitamācaret ekāntaraṃ tataścordhvaṃ dvyantaraṃ tryantaraṃ tathā" },
      { type: "verse", number: "17", sanskrit: "क्रमेणानेन सन्त्यक्ता दोषाः संवर्द्धिता गुणाः प्रभवन्ति न पीडायै प्राप्नुवन्ति स्थिरात्मताम्", text: "krameṇānena santyaktā doṣāḥ saṃvarddhitā guṇāḥ prabhavanti na pīḍāyai prāpnuvanti sthirātmatām" },
      { type: "verse", number: "18", sanskrit: "त्रितयं चतदुपस्तम्भनमाहारः स्वप्नो ऽब्रह्मचर्यं च एभिर्युक्तियुक्तैरुपस्तब्धमुपस्तम्भैः शरीरं बलवर्णोपचयोचितमनुवर्त्तते यावदायुःसंस्कारः तत्र आहार उक्तो वक्ष्यते च", text: "tritayaṃ catadupastambhanamāhāraḥ svapno 'brahmacaryaṃ ca ebhiryuktiyuktairupastabdhamupastambhaiḥ śarīraṃ balavarṇopacayocitamanuvarttate yāvadāyuḥsaṃskāraḥ tatra āhāra ukto vakṣyate ca" },
      { type: "verse", number: "19", sanskrit: "लोकादिसर्गप्रभवा तमोमूला तमोमयी बाहुल्यात्तमसो रात्रौ निद्रा प्रायेण जायते", text: "lokādisargaprabhavā tamomūlā tamomayī bāhulyāttamaso rātrau nidrā prāyeṇa jāyate" },
      { type: "verse", number: "20", sanskrit: "श्लेष्मावृतेषु स्रोतस्सु श्रमादुपरतेषु च इन्द्रियेषु स्वकर्मभ्यो निद्रा विशति देहिनम्", text: "śleṣmāvṛteṣu srotassu śramāduparateṣu ca indriyeṣu svakarmabhyo nidrā viśati dehinam" },
      { type: "verse", number: "21", sanskrit: "सर्वेन्द्रियव्युपरतौ मनो ऽनुपरतं यदा विषयेभ्यस्तदा स्वप्नं नानारूपं प्रपश्यति", text: "sarvendriyavyuparatau mano 'nuparataṃ yadā viṣayebhyastadā svapnaṃ nānārūpaṃ prapaśyati" },
      { type: "verse", number: "22", sanskrit: "निद्रायत्तं सुखं दुःखं पुष्टिः कार्श्यं बलाबलम् वृषता क्लीबता ज्ञानमज्ञानं जीवितं न च", text: "nidrāyattaṃ sukhaṃ duḥkhaṃ puṣṭiḥ kārśyaṃ balābalam vṛṣatā klībatā jñānamajñānaṃ jīvitaṃ na ca" },
      { type: "verse", number: "23", sanskrit: "अकाले ऽतिप्रसङ्गाच्च न च निद्रा निषेविता सुखयुषी पराकुर्यात् कालरात्रिरिवापरा", text: "akāle 'tiprasaṅgācca na ca nidrā niṣevitā sukhayuṣī parākuryāt kālarātririvāparā" },
      { type: "verse", number: "24", sanskrit: "सैव युक्ता पुनर्युङ्क्ते निद्रा देहं सुखायुषा योगाभियोगिनो बुद्धिर्निर्मला तपसा यथा", text: "saiva yuktā punaryuṅkte nidrā dehaṃ sukhāyuṣā yogābhiyogino buddhirnirmalā tapasā yathā" },
      { type: "verse", number: "25", sanskrit: "रात्रौ जागरणं रूक्षं स्निग्धं प्रस्वपनं दिवा अरूक्षमनभिष्यन्दि त्वासीनप्रचलायितम्", text: "rātrau jāgaraṇaṃ rūkṣaṃ snigdhaṃ prasvapanaṃ divā arūkṣamanabhiṣyandi tvāsīnapracalāyitam" },
      { type: "verse", number: "26", sanskrit: "ग्रीष्मे वायुचयादानरौक्ष्यरात्र्यल्पभावतः दिवास्वप्नो हितो ऽन्यस्मिन् कफपित्तकरो हि सः", text: "grīṣme vāyucayādānaraukṣyarātryalpabhāvataḥ divāsvapno hito 'nyasmin kaphapittakaro hi saḥ" },
      { type: "verse", number: "27", sanskrit: "मुक्त्वातिभाष्ययानाध्वमद्यस्त्रीभारकर्मभिः क्रोधशोकभयैः क्लान्तान् श्वासहिध्मातिसारिणः", text: "muktvātibhāṣyayānādhvamadyastrībhārakarmabhiḥ krodhaśokabhayaiḥ klāntān śvāsahidhmātisāriṇaḥ" },
      { type: "verse", number: "28", sanskrit: "वृद्धबालाबलक्षीणक्षततृट्च्छूलपीडितान् अजीर्ण्यभिहतोन्मत्तान् दिवास्वप्नोचितानपि धातुसाम्यं तथा ह्येषां श्लेष्मा चाङ्गानि पुष्यति", text: "vṛddhabālābalakṣīṇakṣatatṛṭcchūlapīḍitān ajīrṇyabhihatonmattān divāsvapnocitānapi dhātusāmyaṃ tathā hyeṣāṃ śleṣmā cāṅgāni puṣyati" },
      { type: "verse", number: "29", sanskrit: "बहुमेदःकफाः स्वप्युः स्नेहनित्याश्च नाहनि विषार्त्तः कण्ठरोगी च नैव जातु निशास्वपि", text: "bahumedaḥkaphāḥ svapyuḥ snehanityāśca nāhani viṣārttaḥ kaṇṭharogī ca naiva jātu niśāsvapi" },
      { type: "verse", number: "30", sanskrit: "हलीमकशिरोजाड्यस्तैमित्यगुरुगात्रताः ज्वरभ्रममतिभ्रंशस्रोतोरोधाग्निमन्दताः", text: "halīmakaśirojāḍyastaimityagurugātratāḥ jvarabhramamatibhraṃśasrotorodhāgnimandatāḥ" },
      { type: "verse", number: "31", sanskrit: "शोफारोचकहृल्लासपीनसार्द्धावभेदकाः कण्डूरूक्कोठपिटकाकासतन्द्रागलामयाः", text: "śophārocakahṛllāsapīnasārddhāvabhedakāḥ kaṇḍūrūkkoṭhapiṭakākāsatandrāgalāmayāḥ" },
      { type: "verse", number: "32", sanskrit: "विषवेगप्रवृत्तिश्च भवेदहितनिद्रया अपच्यमानो बाहुल्यात् स्रोतांस्यावृणुते कफः", text: "viṣavegapravṛttiśca bhavedahitanidrayā apacyamāno bāhulyāt srotāṃsyāvṛṇute kaphaḥ" },
      { type: "verse", number: "33", sanskrit: "ततः स्रोतस्सु रुद्धेषु जायते गात्रगौरवम् गुरुगात्रस्य चालस्यमालस्यादतिनिद्रता", text: "tataḥ srotassu ruddheṣu jāyate gātragauravam gurugātrasya cālasyamālasyādatinidratā" },
      { type: "verse", number: "34", sanskrit: "विरेकः कायशिरसोर्वमनं रक्तमोक्षणम् धूमः क्षूत्तृड्व्यथाहर्षशोकमैथुनभीक्रुधः", text: "virekaḥ kāyaśirasorvamanaṃ raktamokṣaṇam dhūmaḥ kṣūttṛḍvyathāharṣaśokamaithunabhīkrudhaḥ" },
      { type: "verse", number: "35", sanskrit: "चिन्तोत्कण्ठासुखा शय्यासत्वौदार्यं तमोजयः रूक्षान्नं चाहितां निद्रां वारयन्ति प्रसङ्गिनीम्", text: "cintotkaṇṭhāsukhā śayyāsatvaudāryaṃ tamojayaḥ rūkṣānnaṃ cāhitāṃ nidrāṃ vārayanti prasaṅginīm" },
      { type: "verse", number: "36", sanskrit: "एत एव च विज्ञेया निद्रानाशस्य हेतवः कालशीलक्षयो व्याधिर्वृद्धिश्चानिलपित्तयोः", text: "eta eva ca vijñeyā nidrānāśasya hetavaḥ kālaśīlakṣayo vyādhirvṛddhiścānilapittayoḥ" },
      { type: "verse", number: "37", sanskrit: "निद्रानाशादङ्गमर्द्दशिरोगौरवजृम्भिकाः जाड्यग्लानि भ्रमापक्तितन्द्रारोगाश्च वातजाः", text: "nidrānāśādaṅgamarddaśirogauravajṛmbhikāḥ jāḍyaglāni bhramāpaktitandrārogāśca vātajāḥ" },
      { type: "verse", number: "38", sanskrit: "कफो ऽल्पो वायुनोद्धूतो धमनीः सनिरुध्य तु कुर्यात्संज्ञापहां तन्द्रां दारुणां मोहकरिणीम्", text: "kapho 'lpo vāyunoddhūto dhamanīḥ sanirudhya tu kuryātsaṃjñāpahāṃ tandrāṃ dāruṇāṃ mohakariṇīm" },
      { type: "verse", number: "39", sanskrit: "उन्मीलितविनिर्भुग्ने परिवर्त्तिततारके भवतस्तत्र नयने स्रुते लुलितपक्ष्मणी", text: "unmīlitavinirbhugne parivarttitatārake bhavatastatra nayane srute lulitapakṣmaṇī" },
      { type: "verse", number: "40", sanskrit: "अर्द्धत्रिरात्रात्सा साध्या न सा साध्या ततः परम् यथाकालमतो निद्रां रात्रौ सेवेत सात्म्यतः", text: "arddhatrirātrātsā sādhyā na sā sādhyā tataḥ param yathākālamato nidrāṃ rātrau seveta sātmyataḥ" },
      { type: "verse", number: "41", sanskrit: "असात्म्याज्जागरादर्धं प्रातः स्वप्यादभुक्तवान् शीलयेन्मन्दनिद्रस्तु क्षीरमिक्षुरसं रसान्", text: "asātmyājjāgarādardhaṃ prātaḥ svapyādabhuktavān śīlayenmandanidrastu kṣīramikṣurasaṃ rasān" },
      { type: "verse", number: "42", sanskrit: "आनूपौदकमांसानां भक्ष्यान् गौडिकपैष्टिकान् शालीन्मद्यानि माषांश्च कीलाटान् माहिषं दधि", text: "ānūpaudakamāṃsānāṃ bhakṣyān gauḍikapaiṣṭikān śālīnmadyāni māṣāṃśca kīlāṭān māhiṣaṃ dadhi" },
      { type: "verse", number: "43", sanskrit: "अभ्यङ्गोद्वर्त्तनस्नानमूर्ध्दश्रवणपूरणम् चक्षुषस्तर्पणं लेपः शिरसो वदनस्य च", text: "abhyaṅgodvarttanasnānamūrdhdaśravaṇapūraṇam cakṣuṣastarpaṇaṃ lepaḥ śiraso vadanasya ca" },
      { type: "verse", number: "44", sanskrit: "प्रवाते सुरभौ देशे सुखां शय्यां यथोचिते संवाहनं स्पर्शसुखं चित्तज्ञैरनुजीविभिः", text: "pravāte surabhau deśe sukhāṃ śayyāṃ yathocite saṃvāhanaṃ sparśasukhaṃ cittajñairanujīvibhiḥ" },
      { type: "verse", number: "45", sanskrit: "सर्पिः क्षीरानुपानं च जीवनीयैः शृतं पिबेत् कान्ताबाहुलताश्लेषो निर्वृतिः कृतकृत्यता", text: "sarpiḥ kṣīrānupānaṃ ca jīvanīyaiḥ śṛtaṃ pibet kāntābāhulatāśleṣo nirvṛtiḥ kṛtakṛtyatā" },
      { type: "verse", number: "46", sanskrit: "मनो ऽनुकूला विषयाः कामं निद्रासुखप्रदाः ब्रह्मचर्यरतेर्ग्रम्यसुखनिस्पृहचेतसः", text: "mano 'nukūlā viṣayāḥ kāmaṃ nidrāsukhapradāḥ brahmacaryaratergramyasukhanispṛhacetasaḥ" },
      { type: "verse", number: "47", sanskrit: "निद्रा सन्तोषतृप्तस्य स्वं कालं नातिवर्त्तते एतान्येव च भूयिष्ठं निद्रालुः परिवर्जयेत्", text: "nidrā santoṣatṛptasya svaṃ kālaṃ nātivarttate etānyeva ca bhūyiṣṭhaṃ nidrāluḥ parivarjayet" },
      { type: "verse", number: "48", sanskrit: "कालस्वभावामयचित्तदेहखेदैः कफागन्तुतमोभवा च निद्रा बिभर्त्ति प्रथमा शरीरं पाप्मान्तगा व्याधिनिमित्तमन्याः", text: "kālasvabhāvāmayacittadehakhedaiḥ kaphāgantutamobhavā ca nidrā bibhartti prathamā śarīraṃ pāpmāntagā vyādhinimittamanyāḥ" },
      { type: "verse", number: "49", sanskrit: "ग्राम्यधर्मप्रवृत्तौ तु रजस्वलामनिष्टामनिष्टाचारामशस्तामतिस्थूलामतिकृशां गर्भिणीं सूतिकामनुत्तानां विकृताङ्गां गणिकामप्रजसं दुष्टयोनिमन्ययोनिमन्यस्त्रियं विशेषाच्च वयोवर्णवृद्धां सगोत्रां गुरुमित्रबन्धुभृत्यपत्नीं वर्णिनीं तथा चैत्यचत्वरचतुष्पथोपवनश्मशानाघातसलिलौषधद्विजगुरुसुरनृपालयेष्वहनि गोसर्गे मध्यन्दिने ऽर्द्धरात्रौ पर्वेष्वनङ्गे पिपासुरप्रणीतसङ्कल्पो वा न गच्छेत् न च विपरीतव्यवाये योजयेत् विशेषेण चातिव्यायतां गर्भिणीं नवप्रसूतामृतुमतीं संवृतयोनिं च मूर्द्धाभिघातं च परिहरेत् न च निषेकाभिमुखं शुक्रं धारयेदिति मनःशरिरस्थितिमात्रमेव व्यवायं सेवेत न तत्परः स्यादिति", text: "grāmyadharmapravṛttau tu rajasvalāmaniṣṭāmaniṣṭācārāmaśastāmatisthūlāmatikṛśāṃ garbhiṇīṃ sūtikāmanuttānāṃ vikṛtāṅgāṃ gaṇikāmaprajasaṃ duṣṭayonimanyayonimanyastriyaṃ viśeṣācca vayovarṇavṛddhāṃ sagotrāṃ gurumitrabandhubhṛtyapatnīṃ varṇinīṃ tathā caityacatvaracatuṣpathopavanaśmaśānāghātasalilauṣadhadvijagurusuranṛpālayeṣvahani gosarge madhyandine 'rddharātrau parveṣvanaṅge pipāsurapraṇītasaṅkalpo vā na gacchet na ca viparītavyavāye yojayet viśeṣeṇa cātivyāyatāṃ garbhiṇīṃ navaprasūtāmṛtumatīṃ saṃvṛtayoniṃ ca mūrddhābhighātaṃ ca pariharet na ca niṣekābhimukhaṃ śukraṃ dhārayediti manaḥśarirasthitimātrameva vyavāyaṃ seveta na tatparaḥ syāditi" },
      { type: "verse", number: "50", sanskrit: "भवति चात्र श्लोकः विस्रब्धहृष्टो रहसि तत्कामस्तरुणः पुमान् समस्थिताङ्गः सुरभिर्मुक्तमूत्रादिरव्यथः", text: "bhavati cātra ślokaḥ visrabdhahṛṣṭo rahasi tatkāmastaruṇaḥ pumān samasthitāṅgaḥ surabhirmuktamūtrādiravyathaḥ" },
      { type: "verse", number: "51", sanskrit: "नानाशितो नात्यशितो वृष्याणां तर्पितस्त्र्यहम् नारीं नारीर्गुणैर्युक्तां सहपूर्वगुणां व्रजेत्", text: "nānāśito nātyaśito vṛṣyāṇāṃ tarpitastryaham nārīṃ nārīrguṇairyuktāṃ sahapūrvaguṇāṃ vrajet" },
      { type: "verse", number: "52", sanskrit: "द्व्यहाद्वसन्ते तस्यान्ते पक्षात्तद्वत् घनोदये सेवेत कामतः कामं हेमन्ते शिशिरे बली स्नानाङ्गरागव्यजनेन्दुपादमांसासवक्षीररसान् रसालाम्", text: "dvyahādvasante tasyānte pakṣāttadvat ghanodaye seveta kāmataḥ kāmaṃ hemante śiśire balī snānāṅgarāgavyajanendupādamāṃsāsavakṣīrarasān rasālām" },
      { type: "verse", number: "53", sanskrit: "भक्ष्यान् सिताढ्यान् सलिलं सुशीतम् सेवेत निद्रां च रतान्ततान्तः", text: "bhakṣyān sitāḍhyān salilaṃ suśītam seveta nidrāṃ ca ratāntatāntaḥ" },
      { type: "verse", number: "54", sanskrit: "स्त्रीसंसर्गद्धि सद्यः स्यात् क्लीबता बलिनामपि एवं चाप्यायते शीघ्रं तेषां शुक्रं च धाम च", text: "strīsaṃsargaddhi sadyaḥ syāt klībatā balināmapi evaṃ cāpyāyate śīghraṃ teṣāṃ śukraṃ ca dhāma ca" },
      { type: "verse", number: "55", sanskrit: "दृष्ट्यायुरोजःशुक्रानां क्षयं मेढ्राश्रयान् गदान् वायोः कोपमधर्मं च मूढः प्राप्नोत्यतो ऽन्यथा", text: "dṛṣṭyāyurojaḥśukrānāṃ kṣayaṃ meḍhrāśrayān gadān vāyoḥ kopamadharmaṃ ca mūḍhaḥ prāpnotyato 'nyathā" },
      { type: "verse", number: "56", sanskrit: "उत्तानो वेगरोधी वा वृद्धिमेहाश्मशर्कराः तिमिरादिगदोत्पत्तिर्मूर्द्धाद्याहननाद्ध्रुवम्", text: "uttāno vegarodhī vā vṛddhimehāśmaśarkarāḥ timirādigadotpattirmūrddhādyāhananāddhruvam" },
      { type: "verse", number: "57", sanskrit: "भ्रमक्लमोरुदौर्बल्यबलधात्विन्द्रियक्षयः अपर्वमरणं च स्याद्विशेषेणातिमैथुनात्", text: "bhramaklamorudaurbalyabaladhātvindriyakṣayaḥ aparvamaraṇaṃ ca syādviśeṣeṇātimaithunāt" },
      { type: "verse", number: "58", sanskrit: "नचोनः षोडशाद्वर्षात् सप्ततेः परतो न अच् आयुष्कामो नरः स्त्रीभिः संयोगं गन्तुमर्हति", text: "naconaḥ ṣoḍaśādvarṣāt saptateḥ parato na ac āyuṣkāmo naraḥ strībhiḥ saṃyogaṃ gantumarhati" },
      { type: "verse", number: "59", sanskrit: "अतिबालो ह्यसंपूर्णसर्वधातुः स्त्रियं व्रजन् उपतप्यते सहसा तटाकमिव काजलम्", text: "atibālo hyasaṃpūrṇasarvadhātuḥ striyaṃ vrajan upatapyate sahasā taṭākamiva kājalam" },
      { type: "verse", number: "60", sanskrit: "शुष्कं रूक्षं यथा काष्ठं जन्तुजग्धं विजर्जरम् स्पृष्टमाशु विशीर्येत तथा वृद्धः स्त्रियं व्रजन्", text: "śuṣkaṃ rūkṣaṃ yathā kāṣṭhaṃ jantujagdhaṃ vijarjaram spṛṣṭamāśu viśīryeta tathā vṛddhaḥ striyaṃ vrajan" },
      { type: "verse", number: "61", sanskrit: "कायस्य तेजः परमं हि शुक्रमाहारसारदपि सारभूतम् जितात्मना तत् परिरक्षणीयं ततो वपुः सन्ततिरप्युदारा", text: "kāyasya tejaḥ paramaṃ hi śukramāhārasāradapi sārabhūtam jitātmanā tat parirakṣaṇīyaṃ tato vapuḥ santatirapyudārā" },
      { type: "verse", number: "62", sanskrit: "अप्रमत्तो भजेद्भावांस्तदात्वसुखसंज्ञकान् सुखोदर्केषु सज्जेत देहस्यैतदलं हितम्", text: "apramatto bhajedbhāvāṃstadātvasukhasaṃjñakān sukhodarkeṣu sajjeta dehasyaitadalaṃ hitam" },
      { type: "verse", number: "63", sanskrit: "प्रज्ञापराधो ऽसात्म्यार्थसंयोगः कालवैकृतम् हिते ऽपि रतमाहारे योजयन्त्यामयैर्नरम्", text: "prajñāparādho 'sātmyārthasaṃyogaḥ kālavaikṛtam hite 'pi ratamāhāre yojayantyāmayairnaram" },
      { type: "verse", number: "64", sanskrit: "नापथ्यसेविनं सद्यः प्रबाधन्ते तदा मलाः प्रकोपं प्रतिविघ्नान्ति भिन्नैर्दूष्यादिभिर्यदा", text: "nāpathyasevinaṃ sadyaḥ prabādhante tadā malāḥ prakopaṃ prativighnānti bhinnairdūṣyādibhiryadā" },
      { type: "verse", number: "65", sanskrit: "न च सर्वोपचारो ऽपि सर्वदा सर्वदोषकृत् न हि सर्वाण्यपथ्यानि तुल्यदोषाणि नैव च", text: "na ca sarvopacāro 'pi sarvadā sarvadoṣakṛt na hi sarvāṇyapathyāni tulyadoṣāṇi naiva ca" },
      { type: "verse", number: "66", sanskrit: "सर्वे तुल्यबला दोषा न सर्वाणि वपूंषि च व्याधिक्षमत्वे शक्तानि यतो ऽपथ्यं तदेव तु", text: "sarve tulyabalā doṣā na sarvāṇi vapūṃṣi ca vyādhikṣamatve śaktāni yato 'pathyaṃ tadeva tu" },
      { type: "verse", number: "67", sanskrit: "गच्छत्यपथ्यतमतां तुल्यदोषादिवर्द्धितम् त एव च पुनर्द्दोषा हेतुभिर्बहुभिश्चिताः", text: "gacchatyapathyatamatāṃ tulyadoṣādivarddhitam ta eva ca punarddoṣā hetubhirbahubhiścitāḥ" },
      { type: "verse", number: "68", sanskrit: "मिथो विरुद्धा बलिनो दीर्घकालानुबन्धिनः सर्वे समप्रकुपिताः प्राप्याल्पमपि कारणम्", text: "mitho viruddhā balino dīrghakālānubandhinaḥ sarve samaprakupitāḥ prāpyālpamapi kāraṇam" },
      { type: "verse", number: "69", sanskrit: "प्राणायतनमाश्रित्य गर्भीराः सर्वमार्गगाः देहे ऽहितोचिते ते स्युश्चिरादप्याशुकारिणः", text: "prāṇāyatanamāśritya garbhīrāḥ sarvamārgagāḥ dehe 'hitocite te syuścirādapyāśukāriṇaḥ" },
      { type: "verse", number: "70", sanskrit: "अहितान्यपि चान्येषामभ्यासादुपशेरते दोषाश्चैषां क्षयं यान्ति कर्मवातातपादिभिः", text: "ahitānyapi cānyeṣāmabhyāsādupaśerate doṣāścaiṣāṃ kṣayaṃ yānti karmavātātapādibhiḥ" },
      { type: "verse", number: "71", sanskrit: "भिन्नाहारवयः सात्म्यप्रकृतीनां समं भवेत् एको विकृतवाय्यादियुगपत्सेवनात् गदः", text: "bhinnāhāravayaḥ sātmyaprakṛtīnāṃ samaṃ bhavet eko vikṛtavāyyādiyugapatsevanāt gadaḥ" },
      { type: "verse", number: "72", sanskrit: "वातादीनां तु विकृतिर्विकृताद्ग्रहचारतः भौमान्तरिक्षदिव्येभ्य उत्पातेभ्यश्च जायते सम्भवः पुनरेतेषां कर्मणः सामुदायिकात्", text: "vātādīnāṃ tu vikṛtirvikṛtādgrahacārataḥ bhaumāntarikṣadivyebhya utpātebhyaśca jāyate sambhavaḥ punareteṣāṃ karmaṇaḥ sāmudāyikāt" },
      { type: "verse", number: "73", sanskrit: "दुष्टो वायुरभिष्यन्दी स्तिमितो ऽत्युष्णशीतलः कुण्डली भैरवरवः परुषो ऽनार्त्तवो बली", text: "duṣṭo vāyurabhiṣyandī stimito 'tyuṣṇaśītalaḥ kuṇḍalī bhairavaravaḥ paruṣo 'nārttavo balī" },
      { type: "verse", number: "74", sanskrit: "अन्योन्यव्याहतगतिः पांसुबाष्पविषान्वितः रसवर्णादिविकृतमपक्रान्तविहङ्गमम्", text: "anyonyavyāhatagatiḥ pāṃsubāṣpaviṣānvitaḥ rasavarṇādivikṛtamapakrāntavihaṅgamam" },
      { type: "verse", number: "75", sanskrit: "निन्दितप्रभवं तोयमुपक्षीणजलाशयम् मक्षिकामूषिकाव्यालबहूत्पातप्रदूषितः", text: "ninditaprabhavaṃ toyamupakṣīṇajalāśayam makṣikāmūṣikāvyālabahūtpātapradūṣitaḥ" },
      { type: "verse", number: "76", sanskrit: "देशो ऽपथ्यान्नबहुलो नष्टधर्ममहौषधिः कालश्च विपरीतो ऽतिहीनलिङ्गो यथायथम्", text: "deśo 'pathyānnabahulo naṣṭadharmamahauṣadhiḥ kālaśca viparīto 'tihīnaliṅgo yathāyatham" },
      { type: "verse", number: "77", sanskrit: "एते दुष्परिहारत्वादहितायोत्तरोत्तरम् येषामनियतं कर्म तस्मिन् काले सुदारुणे", text: "ete duṣparihāratvādahitāyottarottaram yeṣāmaniyataṃ karma tasmin kāle sudāruṇe" },
      { type: "verse", number: "78", sanskrit: "कर्म पञ्चविधं तेषां योज्यं तद्वद्रसायनम् शस्यते देहवृद्धिश्च भेषजैः पूर्वमुद्धृतैः", text: "karma pañcavidhaṃ teṣāṃ yojyaṃ tadvadrasāyanam śasyate dehavṛddhiśca bheṣajaiḥ pūrvamuddhṛtaiḥ" },
      { type: "verse", number: "79", sanskrit: "ब्रह्मचर्यं दया दानं सदाचाररतिः शमः सद्धर्मः सत्कथा पूजा देवर्षीणां जितात्मनाम्", text: "brahmacaryaṃ dayā dānaṃ sadācāraratiḥ śamaḥ saddharmaḥ satkathā pūjā devarṣīṇāṃ jitātmanām" },
      { type: "verse", number: "80", sanskrit: "देशानामविपन्नानां साधूनां च निषेवणम् दैवव्यपाश्रयं चेष्टं कर्म जीवितरक्षणम्", text: "deśānāmavipannānāṃ sādhūnāṃ ca niṣevaṇam daivavyapāśrayaṃ ceṣṭaṃ karma jīvitarakṣaṇam" },
      { type: "verse", number: "81", sanskrit: "हेमन्तादिषु कुर्वीत स्वं स्वं चाकालिकेष्वपि विधिं तच्छीलनं यस्माच्छीतादिद्वन्द्वकारितम्", text: "hemantādiṣu kurvīta svaṃ svaṃ cākālikeṣvapi vidhiṃ tacchīlanaṃ yasmācchītādidvandvakāritam" },
      { type: "verse", number: "82", sanskrit: "ऋतुचर्यादिशीतोष्णवृष्टिदोषप्रतिक्रिया अत एव च चर्यायां हेमन्तशिशिरे समे", text: "ṛtucaryādiśītoṣṇavṛṣṭidoṣapratikriyā ata eva ca caryāyāṃ hemantaśiśire same" },
      { type: "verse", number: "83", sanskrit: "सर्वप्राणभृतां नित्यमायुर्युक्तिमपेक्षते दैवे पुरुषकारे च स्थितं तस्य बलाबलम्", text: "sarvaprāṇabhṛtāṃ nityamāyuryuktimapekṣate daive puruṣakāre ca sthitaṃ tasya balābalam" },
      { type: "verse", number: "84", sanskrit: "अन्यजन्मकृत कर्म दैवं पौरुषमैहिकम् विद्यात्ते कर्मणी त्रेधा श्रेष्ठमध्यावरत्वतः", text: "anyajanmakṛta karma daivaṃ pauruṣamaihikam vidyātte karmaṇī tredhā śreṣṭhamadhyāvaratvataḥ" },
      { type: "verse", number: "85", sanskrit: "तयोरुदारयोर्युक्तिर्दीर्घस्य सुसुखस्य च नियतस्यायुषो हेतुर्विपरीतस्य चापरा", text: "tayorudārayoryuktirdīrghasya susukhasya ca niyatasyāyuṣo heturviparītasya cāparā" },
      { type: "verse", number: "86", sanskrit: "मध्या मध्यस्य मिश्रस्य सङ्कीर्णा श्रुणु चापरम् दैवं पुरुषकारेण दुर्बलं ह्युपहन्यते", text: "madhyā madhyasya miśrasya saṅkīrṇā śruṇu cāparam daivaṃ puruṣakāreṇa durbalaṃ hyupahanyate" },
      { type: "verse", number: "87", sanskrit: "तथा दैवेन बलिना पौरुषं कर्म दुर्बलम् दृष्ट्वा यदेके मन्यन्ते नियतं मानमायुषः", text: "tathā daivena balinā pauruṣaṃ karma durbalam dṛṣṭvā yadeke manyante niyataṃ mānamāyuṣaḥ" },
      { type: "verse", number: "88", sanskrit: "कर्म किञ्चित् क्वचित्काले विपाकनियतं महत् किञ्चिच्च कालनियतं प्रत्ययैः प्रतिबोध्यते", text: "karma kiñcit kvacitkāle vipākaniyataṃ mahat kiñcicca kālaniyataṃ pratyayaiḥ pratibodhyate" },
      { type: "verse", number: "89", sanskrit: "एवं च द्विविधो मृत्युः कालाकालविभेदतः उपदिष्टस्ततश्चैष हिताहितविधिक्रमः", text: "evaṃ ca dvividho mṛtyuḥ kālākālavibhedataḥ upadiṣṭastataścaiṣa hitāhitavidhikramaḥ" },
      { type: "verse", number: "90", sanskrit: "एकोत्तरं मृत्युशतं ब्रुवते वेदवादिनः तत्रैकः कालसंयुक्तः शेषास्त्वागन्तवः स्मृताः", text: "ekottaraṃ mṛtyuśataṃ bruvate vedavādinaḥ tatraikaḥ kālasaṃyuktaḥ śeṣāstvāgantavaḥ smṛtāḥ" },
      { type: "verse", number: "91", sanskrit: "श्येनादिना च यागेन भ्रातृव्यस्य तथा च तैः दीर्घश्रवससोमाद्यैर्विहितश्चात्मनो वधः", text: "śyenādinā ca yāgena bhrātṛvyasya tathā ca taiḥ dīrghaśravasasomādyairvihitaścātmano vadhaḥ" },
      { type: "verse", number: "92", sanskrit: "आयुष्कामस्य तत्प्राप्तिस्तथेष्ट्या मित्रविन्दया सर्वस्मादेव चात्मानं गोपयेदीदृशी स्मृतिः", text: "āyuṣkāmasya tatprāptistatheṣṭyā mitravindayā sarvasmādeva cātmānaṃ gopayedīdṛśī smṛtiḥ" },
      { type: "verse", number: "93", sanskrit: "तथा मरणमुद्दिष्टं सौगतानां चतुर्विधम् विषमापरिहारेण जायते नियतायुषाम्", text: "tathā maraṇamuddiṣṭaṃ saugatānāṃ caturvidham viṣamāparihāreṇa jāyate niyatāyuṣām" },
      { type: "verse", number: "94", sanskrit: "ध्रुवं रोगित्वमन्येषां मृत्युरेव त्वपर्वणि अकाण्डे शस्त्रघाताद्यैः प्रत्यक्षो मृत्युरन्यथा", text: "dhruvaṃ rogitvamanyeṣāṃ mṛtyureva tvaparvaṇi akāṇḍe śastraghātādyaiḥ pratyakṣo mṛtyuranyathā" },
      { type: "verse", number: "95", sanskrit: "उद्भ्रान्तचण्डमातङ्गतुरङ्गादिसमागमम् आरातिदुष्टवाय्वादिसाहसाहितभोजनम्", text: "udbhrāntacaṇḍamātaṅgaturaṅgādisamāgamam ārātiduṣṭavāyvādisāhasāhitabhojanam" },
      { type: "verse", number: "96", sanskrit: "वर्जयेदिति न ब्रूयुर्मुनयो दिव्यचक्षुषः दैवव्यपाश्रयादीश्च रसायनविधीस्तथा", text: "varjayediti na brūyurmunayo divyacakṣuṣaḥ daivavyapāśrayādīśca rasāyanavidhīstathā" },
      { type: "verse", number: "97", sanskrit: "न वा ते ऽपि यथाकाममायुषः स्थितिमाप्नुयुः अहिसिंहगजादिभ्यो विदुषां न भयं भवेत्", text: "na vā te 'pi yathākāmamāyuṣaḥ sthitimāpnuyuḥ ahisiṃhagajādibhyo viduṣāṃ na bhayaṃ bhavet" },
      { type: "verse", number: "98", sanskrit: "मिथ्याप्राकारदुर्गाणि मिथ्यामारणरक्षणम् आयुष्कामस्य मिथ्यैव परदारादिवर्जनम्", text: "mithyāprākāradurgāṇi mithyāmāraṇarakṣaṇam āyuṣkāmasya mithyaiva paradārādivarjanam" },
      { type: "verse", number: "99", sanskrit: "मन्त्रदेवतयाहूता नाचक्षीरन् महाहयः विषसुप्तप्रबुद्धस्था भावाभावौ तदायुषः", text: "mantradevatayāhūtā nācakṣīran mahāhayaḥ viṣasuptaprabuddhasthā bhāvābhāvau tadāyuṣaḥ" },
      { type: "verse", number: "100", sanskrit: "सन्यासरोहिणीकादिग्रस्तस्य सहसा भवेत् उपेक्षया न मरणं जीवितं वा चिकित्सया", text: "sanyāsarohiṇīkādigrastasya sahasā bhavet upekṣayā na maraṇaṃ jīvitaṃ vā cikitsayā" },
      { type: "verse", number: "101", sanskrit: "प्रत्यहं नृसहस्रस्य युद्वे ऽन्योन्यमभिघ्नतः साधुवृत्तस्य चातुल्या न भवेदायुषः स्थितिः", text: "pratyahaṃ nṛsahasrasya yudve 'nyonyamabhighnataḥ sādhuvṛttasya cātulyā na bhavedāyuṣaḥ sthitiḥ" },
      { type: "verse", number: "102", sanskrit: "नायुधैर्द्विषमिन्द्राद्या नौषधैरार्तमश्विनौ उपक्रमेरन्न भवेदकालमरणं यदि", text: "nāyudhairdviṣamindrādyā nauṣadhairārtamaśvinau upakrameranna bhavedakālamaraṇaṃ yadi" },
      { type: "verse", number: "103", sanskrit: "घटानामामपक्वानां पालनापरिपालनैः चिराल्पकालवर्त्तित्वं चित्रस्थानां च दृश्यते", text: "ghaṭānāmāmapakvānāṃ pālanāparipālanaiḥ cirālpakālavarttitvaṃ citrasthānāṃ ca dṛśyate" },
      { type: "verse", number: "104", sanskrit: "इत्यत्यन्तप्रसिद्धे ऽपि सिद्धे सर्वागमैरपि दृष्टे ऽप्यकालमरणे विचिकित्सेत्कथं बुधः", text: "ityatyantaprasiddhe 'pi siddhe sarvāgamairapi dṛṣṭe 'pyakālamaraṇe vicikitsetkathaṃ budhaḥ" },
      { type: "verse", number: "105", sanskrit: "गुणवद्भिषगादीनां सम्भवे सम्भवेत्तु यः मृत्युं तं कालजं प्राहुरितरं तद्विपर्यये", text: "guṇavadbhiṣagādīnāṃ sambhave sambhavettu yaḥ mṛtyuṃ taṃ kālajaṃ prāhuritaraṃ tadviparyaye" },
      { type: "verse", number: "106", sanskrit: "यथा रथो वाह्यमानो न्यायेन क्रमशः क्षयम् यायादात्मवतामायुस्तथान्येषां विपर्ययः", text: "yathā ratho vāhyamāno nyāyena kramaśaḥ kṣayam yāyādātmavatāmāyustathānyeṣāṃ viparyayaḥ" },
      { type: "verse", number: "107", sanskrit: "शुचितैलदशो दीपः कीटवाताद्यपीडितः दीप्तिमान् वर्त्तते सम्यक् यथैवास्नेहसङ्क्षयात्", text: "śucitailadaśo dīpaḥ kīṭavātādyapīḍitaḥ dīptimān varttate samyak yathaivāsnehasaṅkṣayāt" },
      { type: "verse", number: "108", sanskrit: "स एवातो यथा च स्याद्विपरीतो विपर्यये हिताहितोपचारेण तथैव पुरुषो ध्रुवम्", text: "sa evāto yathā ca syādviparīto viparyaye hitāhitopacāreṇa tathaiva puruṣo dhruvam" },
      { type: "verse", number: "109", sanskrit: "सर्वमन्यत् परित्यज्य शरीरं पालयेदतः तदभावे हि भावानां सर्वाभावः शरीरिणाम्", text: "sarvamanyat parityajya śarīraṃ pālayedataḥ tadabhāve hi bhāvānāṃ sarvābhāvaḥ śarīriṇām" },
      { type: "verse", number: "110", sanskrit: "नगरी नगरस्येव रथस्येव रथी तथा स्वशरीरस्य मेधावी कृत्येष्ववहितो भवेत्", text: "nagarī nagarasyeva rathasyeva rathī tathā svaśarīrasya medhāvī kṛtyeṣvavahito bhavet" },
      { type: "verse", number: "111", sanskrit: "आहारकल्पनाहेतून् स्वभावादीन् विशेषतः समीक्ष्य हितमश्नीयाद्देहो ह्याहारसम्भवः", text: "āhārakalpanāhetūn svabhāvādīn viśeṣataḥ samīkṣya hitamaśnīyāddeho hyāhārasambhavaḥ" },
      { type: "verse", number: "112", sanskrit: "भीलज्जायन्त्रणालोभहर्षशोकवशं गतः न जातु धारयेद्वेगांस्तद्धि सर्वापदास्पदम्", text: "bhīlajjāyantraṇālobhaharṣaśokavaśaṃ gataḥ na jātu dhārayedvegāṃstaddhi sarvāpadāspadam" },
      { type: "verse", number: "113", sanskrit: "हितमभ्यस्यतः पुंसो नाकाले कालदंष्ट्रया सञ्जायते परामर्शो बलोत्साहेन्द्रियायुषाम्", text: "hitamabhyasyataḥ puṃso nākāle kāladaṃṣṭrayā sañjāyate parāmarśo balotsāhendriyāyuṣām" },
      { type: "verse", number: "114", sanskrit: "अहितान्यपि सन्त्यज्य दोषमाप्याप्नुयाद्यदि तथाप्यानृण्यमायाति साधूनामात्मवानिति", text: "ahitānyapi santyajya doṣamāpyāpnuyādyadi tathāpyānṛṇyamāyāti sādhūnāmātmavāniti" },
      { type: "verse", number: "115", sanskrit: "यच्च रोगसमुत्थानं न शक्यमिह केनचित् परिवर्तुं न तत् प्राप्य शोचितव्यं मनीषिणा", text: "yacca rogasamutthānaṃ na śakyamiha kenacit parivartuṃ na tat prāpya śocitavyaṃ manīṣiṇā" },
      { type: "verse", number: "116", sanskrit: "हिताहारविहाराणां सदाचारनिषेविणाम् लोकद्वयव्यपेक्षाणां जीवितं ह्यमृतायते", text: "hitāhāravihārāṇāṃ sadācāraniṣeviṇām lokadvayavyapekṣāṇāṃ jīvitaṃ hyamṛtāyate" },
      { type: "verse", number: "117", sanskrit: "गृध्नुर्ग्राम्यसुखे वश्यः क्लेशानां हतसत्पथः मूढो जीवत्यनर्थाय दुर्गतिं परिबृंहयन्", text: "gṛdhnurgrāmyasukhe vaśyaḥ kleśānāṃ hatasatpathaḥ mūḍho jīvatyanarthāya durgatiṃ paribṛṃhayan" },
      { type: "verse", number: "118", sanskrit: "विदुषान्तश्शरीरस्थान्नित्यं सन्निहितानरीन् जित्वा वर्ज्यानि वर्ज्यानि चिरं जीवितुमिच्छता", text: "viduṣāntaśśarīrasthānnityaṃ sannihitānarīn jitvā varjyāni varjyāni ciraṃ jīvitumicchatā" },
      { type: "verse", number: "119", sanskrit: "तदात्वे चानुबन्धे वा तस्मात् कर्माशुभोदयम् स्मरन्नात्रेयवचसो न धीमान् कर्तुमर्हति", text: "tadātve cānubandhe vā tasmāt karmāśubhodayam smarannātreyavacaso na dhīmān kartumarhati" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 10,
    lang: "sa",
    content: [
      { type: "heading", heading: "Вамана видхи — терапия рвотой" },
      { type: "text", text: "Глава 10 Сутрастханы Астанга-санграхи посвящена теме «терапия рвотой». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो ऽन्नपानविधिमध्यायं व्याख्यास्यामः इतिहस्माहुरात्रेयादयो महर्षयः", text: "athāto 'nnapānavidhimadhyāyaṃ vyākhyāsyāmaḥ itihasmāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "विधिविहितमन्नपानमिष्टेन्द्रियार्थमायतनमायुषो ब्रुवते यदायत्तानि ह्योजस्तेजोधात्विन्द्रियबलतुष्टिपुष्टिप्रतिभारोग्यादीनि तदिन्धना चान्तराग्नेः स्थितिः अग्निमूलं च देहधारणमिति", text: "vidhivihitamannapānamiṣṭendriyārthamāyatanamāyuṣo bruvate yadāyattāni hyojastejodhātvindriyabalatuṣṭipuṣṭipratibhārogyādīni tadindhanā cāntarāgneḥ sthitiḥ agnimūlaṃ ca dehadhāraṇamiti" },
      { type: "verse", number: "3", sanskrit: "अथात्मवान् स्वभावसंयोगसंस्कारमात्रादेशकालोपयोगव्यवस्थाः सप्ताहारकल्पनाविशेषाणां स्वास्थ्यास्वास्थ्यफलानां हेतुभूताः समीक्ष्य हितमेव अनुरुध्येत तत्र स्वभावतो दिव्योदकरक्तशालिषष्टिकमुद्गैणलावादयो लघवः क्षीरेक्षुव्रीहिमाषानूपामिषादयो गुरव इति ते खल्वपि संयोगादिविशेषैरन्यथात्वं प्रतिपद्यन्ते", text: "athātmavān svabhāvasaṃyogasaṃskāramātrādeśakālopayogavyavasthāḥ saptāhārakalpanāviśeṣāṇāṃ svāsthyāsvāsthyaphalānāṃ hetubhūtāḥ samīkṣya hitameva anurudhyeta tatra svabhāvato divyodakaraktaśāliṣaṣṭikamudgaiṇalāvādayo laghavaḥ kṣīrekṣuvrīhimāṣānūpāmiṣādayo gurava iti te khalvapi saṃyogādiviśeṣairanyathātvaṃ pratipadyante" },
      { type: "verse", number: "4", sanskrit: "तत्र संयोगो नाम द्वयोर्बहूनां वाद्रव्याणां संहतीभावः स विशेषमारभते यन्नैकैकशो द्रव्याणि संस्कारस्तु तोयाग्निसन्निकर्षशौचमन्थनदेशकालभावनाभाजनादिभिरुपजन्यते मात्रा पुनः पिण्डपरिमाणतः समुदायेन प्रतिद्रव्यापेक्षया चाहारराशिः देशो द्रव्यस्योपयोक्तुश्चोत्पत्यवस्थाने तत्र पुनरुपयोक्तास्वस्थातुरत्वतः प्रकृतिभेदतश्च परीक्ष्यः", text: "tatra saṃyogo nāma dvayorbahūnāṃ vādravyāṇāṃ saṃhatībhāvaḥ sa viśeṣamārabhate yannaikaikaśo dravyāṇi saṃskārastu toyāgnisannikarṣaśaucamanthanadeśakālabhāvanābhājanādibhirupajanyate mātrā punaḥ piṇḍaparimāṇataḥ samudāyena pratidravyāpekṣayā cāhārarāśiḥ deśo dravyasyopayoktuścotpatyavasthāne tatra punarupayoktāsvasthāturatvataḥ prakṛtibhedataśca parīkṣyaḥ" },
      { type: "verse", number: "5", sanskrit: "कालस्तु ऋतुव्याध्यपेक्षो जीर्णाजीर्णलक्षणश्च अजीर्णे ऽपि पूर्वस्याहारस्यापरिणतो रस उत्तरेणोपसंसृज्यमानः सर्वान् दोषान् प्रकोपयत्याशु जीर्णे तु स्वस्थानस्थेषु दोषेषु वातानुलोम्यादुत्सृष्टेषु मूत्रपुरीषवेगेषु विशुद्धेषूद्गारहृदयस्रोतोमुखेषु विशदकरणे लघुनि शरीरे ऽग्नावुदीर्णे जाताया बुभुक्षायामभ्यवहृतमन्नमप्रदूषयद्दोषानायुर्बलवर्णानभिवर्द्धयति केवलमयमेव कालो भोजनस्य", text: "kālastu ṛtuvyādhyapekṣo jīrṇājīrṇalakṣaṇaśca ajīrṇe 'pi pūrvasyāhārasyāpariṇato rasa uttareṇopasaṃsṛjyamānaḥ sarvān doṣān prakopayatyāśu jīrṇe tu svasthānastheṣu doṣeṣu vātānulomyādutsṛṣṭeṣu mūtrapurīṣavegeṣu viśuddheṣūdgārahṛdayasrotomukheṣu viśadakaraṇe laghuni śarīre 'gnāvudīrṇe jātāyā bubhukṣāyāmabhyavahṛtamannamapradūṣayaddoṣānāyurbalavarṇānabhivarddhayati kevalamayameva kālo bhojanasya" },
      { type: "verse", number: "6", sanskrit: "अतीतकालं पुनस्तद्वातविष्टब्धं कृच्छ्राद्विपच्यते कर्शयत्यन्नरुचिं च पुनरुपहन्ति उपयोगव्यवस्था तु नास्नातो न दिग्वासा नैकवस्त्रधृक् न मलिनवसनो नाहुत्वा न जपित्वा नानिरूप्य देवताभ्यो न पितृभ्यो न दत्वाग्रमन्नमग्नये न गुरुभ्यो नातिथये नाभ्यागतेभ्यो न श्ववयःश्वपचेभ्यः प्रत्यवेक्ष्य चाश्रितोपाशितानपि तिरश्चो ऽपि स्वपरिगृहीतान् प्रशस्तदेशकालोपकरणयुक्तः स्रग्वी विभूषितः सुरन्धिरार्द्रपाणिपादः सुविशुद्धवदनो ऽभिमतसहायः केशमक्षिकाद्यनुपजुष्टमनिन्द्यमनिन्दन्ननिन्दितमपुनरुष्णीकृतं नात्युष्णमनुपदग्धं सुसिद्धमलोलो नासात्म्यं नाविदितं नाविदितागमं नातिसायं नातिप्रगे नाकाशे नातपे नान्धकारे नाधो वृक्षस्य न श्य्यास्थो नोन्नम्य प्रदेशिनीं न पात्रे भिन्ने नासंवृते न मलिने भावदूषिते वा न चासनस्थिते न हस्तस्थे न हस्ते प्राङ्मुखः सुमनाः शुचिभक्ताक्षुधितानुकूलजनोपहितं हितमन्नमश्रीयात् न पर्युषितमन्यत्र मांसोपदंशभक्ष्येभ्यः नाशेषमन्यत्र दधिमधुघृतसलिलसक्तुशुक्तपायसेभ्यो ऽपि च स्निग्धं लघूष्णमविलम्बित मनतिद्रुतमजल्पन्नहसंस्तन्मनाः समीक्ष्य सम्यगात्मानम्", text: "atītakālaṃ punastadvātaviṣṭabdhaṃ kṛcchrādvipacyate karśayatyannaruciṃ ca punarupahanti upayogavyavasthā tu nāsnāto na digvāsā naikavastradhṛk na malinavasano nāhutvā na japitvā nānirūpya devatābhyo na pitṛbhyo na datvāgramannamagnaye na gurubhyo nātithaye nābhyāgatebhyo na śvavayaḥśvapacebhyaḥ pratyavekṣya cāśritopāśitānapi tiraśco 'pi svaparigṛhītān praśastadeśakālopakaraṇayuktaḥ sragvī vibhūṣitaḥ surandhirārdrapāṇipādaḥ suviśuddhavadano 'bhimatasahāyaḥ keśamakṣikādyanupajuṣṭamanindyamanindannaninditamapunaruṣṇīkṛtaṃ nātyuṣṇamanupadagdhaṃ susiddhamalolo nāsātmyaṃ nāviditaṃ nāviditāgamaṃ nātisāyaṃ nātiprage nākāśe nātape nāndhakāre nādho vṛkṣasya na śyyāstho nonnamya pradeśinīṃ na pātre bhinne nāsaṃvṛte na maline bhāvadūṣite vā na cāsanasthite na hastasthe na haste prāṅmukhaḥ sumanāḥ śucibhaktākṣudhitānukūlajanopahitaṃ hitamannamaśrīyāt na paryuṣitamanyatra māṃsopadaṃśabhakṣyebhyaḥ nāśeṣamanyatra dadhimadhughṛtasalilasaktuśuktapāyasebhyo 'pi ca snigdhaṃ laghūṣṇamavilambita manatidrutamajalpannahasaṃstanmanāḥ samīkṣya samyagātmānam" },
      { type: "verse", number: "7", sanskrit: "स्निग्धलघूष्णानि हि वह्निमौदर्यमुदीरयन्ति कोष्ठं परिशोधयान्ति धातून्न विकुर्वते क्षिप्रं जरयन्ति अनिलमनुलोमयन्ति तथा स्निग्धं दृढीकरोतीन्द्रियाण्युपचिनोति शरीरमपचिनोति जरसं बलमभिवर्द्धयति वर्णप्रसादमभिनिर्वर्त्तयति लघु च पुनः स्वभावादिभिरन्नमप्रतिपीडयद्दोषानव्यथमानं परिणाममेति विपन्नमपि चाल्पदोषं भवति उष्णं च पुनर्जनयति रुचिमुपशोषयति श्लेष्माणम् विलम्बितं तु भुञ्जानो न तृप्तिमधिगच्छति बहु च भुङ्क्ते शीतीभवति चान्नजातं विषमपाकं च भवति अतिद्रुतं तु भुञ्जानस्य जल्पतो हस्तो ऽन्यमनसो वा भवेदुत्स्नेहनमवसादनं भोजनस्याप्रतिष्ठानं गुणदोषाविभावनं च", text: "snigdhalaghūṣṇāni hi vahnimaudaryamudīrayanti koṣṭhaṃ pariśodhayānti dhātūnna vikurvate kṣipraṃ jarayanti anilamanulomayanti tathā snigdhaṃ dṛḍhīkarotīndriyāṇyupacinoti śarīramapacinoti jarasaṃ balamabhivarddhayati varṇaprasādamabhinirvarttayati laghu ca punaḥ svabhāvādibhirannamapratipīḍayaddoṣānavyathamānaṃ pariṇāmameti vipannamapi cālpadoṣaṃ bhavati uṣṇaṃ ca punarjanayati rucimupaśoṣayati śleṣmāṇam vilambitaṃ tu bhuñjāno na tṛptimadhigacchati bahu ca bhuṅkte śītībhavati cānnajātaṃ viṣamapākaṃ ca bhavati atidrutaṃ tu bhuñjānasya jalpato hasto 'nyamanaso vā bhavedutsnehanamavasādanaṃ bhojanasyāpratiṣṭhānaṃ guṇadoṣāvibhāvanaṃ ca" },
      { type: "verse", number: "8", sanskrit: "समीक्ष्य सम्यगात्मानमिति ममेदं सात्म्यमिदमसात्म्यमिति नित्यमप्रमत्तः प्रत्यवेक्षेत तत्र सात्म्यं नाम सहात्मना भवत्यभ्यस्तं तदौचित्यादुपशेत इत्येके सात्म्यविपरीतमनुपशयादसात्म्यम् अन्ये पुनः प्रकृतिवयोदेशर्तुदोषव्याधिवशेन सात्म्यं बहुविधमिच्छन्ति ते ह्युपशयमात्रमङ्गीकृत्य विपरीतगुणमप्युपचारेण सात्म्यमाचक्षते तुल्यगुणं चानुपशयादसात्म्यम् सात्म्यं तु प्रवरावरमध्यविभागेन त्रिविधम् तत्र सर्वरसं प्रवरमेकरसमवरं मध्यं तु मध्यममेव तेषु प्रवरं समदोषस्योपदिशन्तीति इतरेषामपि क्रमेण सात्म्यमपि चाहितं पादेन वा विवर्जयेदित्युक्तं प्राक् तत्र यदाहारजातं समधातूननुवर्त्तयति विषमांश्च समीकरोति तत्समासतो हितम् विपरीतमहितम् तत् पुनर्मात्रायोगादिवैचित्र्यादनियतमपि यथोपदेशं यथाभूयिष्ठं च शीलयेत् परिहरेच्च", text: "samīkṣya samyagātmānamiti mamedaṃ sātmyamidamasātmyamiti nityamapramattaḥ pratyavekṣeta tatra sātmyaṃ nāma sahātmanā bhavatyabhyastaṃ tadaucityādupaśeta ityeke sātmyaviparītamanupaśayādasātmyam anye punaḥ prakṛtivayodeśartudoṣavyādhivaśena sātmyaṃ bahuvidhamicchanti te hyupaśayamātramaṅgīkṛtya viparītaguṇamapyupacāreṇa sātmyamācakṣate tulyaguṇaṃ cānupaśayādasātmyam sātmyaṃ tu pravarāvaramadhyavibhāgena trividham tatra sarvarasaṃ pravaramekarasamavaraṃ madhyaṃ tu madhyamameva teṣu pravaraṃ samadoṣasyopadiśantīti itareṣāmapi krameṇa sātmyamapi cāhitaṃ pādena vā vivarjayedityuktaṃ prāk tatra yadāhārajātaṃ samadhātūnanuvarttayati viṣamāṃśca samīkaroti tatsamāsato hitam viparītamahitam tat punarmātrāyogādivaicitryādaniyatamapi yathopadeśaṃ yathābhūyiṣṭhaṃ ca śīlayet pariharecca" },
      { type: "verse", number: "9", sanskrit: "तथा विशेषतः समशनमध्यशनममात्रशनं विषमाशनं च वर्जयेत् तत्र पथ्यापथ्येमकत्रभुक्तं समशनम् भुक्तस्योपरि भुक्तमध्यशनम् अमात्राशनं पुनः पृथगेवोपदेक्ष्यते अप्राप्तातीतकालं तु भुक्तं विषमाशनमिति भुञ्जानस्तु पेयायूषरसान् व्यञ्जनानि राजतेषु पात्रेषु निदध्यात् परिशुष्कप्रदिग्धानत्युष्णं च पयः सौवर्णेषु खलखट्वरकाम्बलिकान् कांस्येषु रागषाडवसट्टकान् वज्रवैडूर्य विचित्रेषु घृतमायसे पयः सुशीतं ताम्रमये पानीय पानकानि च मृद्धेमस्फटिककाचमयेषु औदनं च विस्तीर्णे मनोरमे स्थाने अन्यथा हि वर्णगन्धरसान्यत्वादहितं स्यात्", text: "tathā viśeṣataḥ samaśanamadhyaśanamamātraśanaṃ viṣamāśanaṃ ca varjayet tatra pathyāpathyemakatrabhuktaṃ samaśanam bhuktasyopari bhuktamadhyaśanam amātrāśanaṃ punaḥ pṛthagevopadekṣyate aprāptātītakālaṃ tu bhuktaṃ viṣamāśanamiti bhuñjānastu peyāyūṣarasān vyañjanāni rājateṣu pātreṣu nidadhyāt pariśuṣkapradigdhānatyuṣṇaṃ ca payaḥ sauvarṇeṣu khalakhaṭvarakāmbalikān kāṃsyeṣu rāgaṣāḍavasaṭṭakān vajravaiḍūrya vicitreṣu ghṛtamāyase payaḥ suśītaṃ tāmramaye pānīya pānakāni ca mṛddhemasphaṭikakācamayeṣu audanaṃ ca vistīrṇe manorame sthāne anyathā hi varṇagandharasānyatvādahitaṃ syāt" },
      { type: "verse", number: "10", sanskrit: "अपि च दक्षिणपार्श्वे भक्ष्यं स्थापयेत् सव्ये पेयं लेह्यं मुखोद्घर्षणपिण्डीं च मध्ये भोज्यमिति यथाग्निसात्म्यं तु प्राक् द्रवमुपशुष्कं वाश्नीयात् प्रागेव तु गुरुस्वादुस्निग्धं च मध्ये ऽम्ललवणम् अन्ते रूक्षं द्रवमितररसयुक्तं च तत्र मन्दाग्रेर्द्रवोष्णेन समुत्तेजितोष्मणो ऽन्यदुपयुक्तं सम्यक् पाकमेति", text: "api ca dakṣiṇapārśve bhakṣyaṃ sthāpayet savye peyaṃ lehyaṃ mukhodgharṣaṇapiṇḍīṃ ca madhye bhojyamiti yathāgnisātmyaṃ tu prāk dravamupaśuṣkaṃ vāśnīyāt prāgeva tu gurusvādusnigdhaṃ ca madhye 'mlalavaṇam ante rūkṣaṃ dravamitararasayuktaṃ ca tatra mandāgrerdravoṣṇena samuttejitoṣmaṇo 'nyadupayuktaṃ samyak pākameti" },
      { type: "verse", number: "11", sanskrit: "अनुपाने तु सलिलमेव श्रेष्ठं सर्वरसयोनित्वात्सर्वभूतसात्म्यत्वाज्जीवनादिगुणयोगाच्च तच्छीतं दधिमधुयवगोधूममद्यविशेषेषु सर्वेषु च विदाहिषु शरद् ग्रीष्मयोश्च उष्णं पिष्टमयेष्वन्येषु च दुर्जरेषु हेमन्ते च द्रवद्रव्यविज्ञानीयं चेक्षेत क्षीरं शालिषष्टिकयोः तथैवोपवासाध्वभाष्यस्त्रीव्यायामक्लान्तबालवृद्धेषु मांसरसः शोषादिषु वाते त्वम्लानि च पित्ते शर्करोदकम् त्रिफलोदकं तु सक्षौद्रं श्लेष्मणि प्राथश्चाक्षिगलरोगेषु मस्त्वेव वा दध्नि कूचिकाकीलाटयोश्च धान्याम्लं मस्तु तक्रं वा शाकावरान्नेषु मद्यं मांसेषु फलाम्लमम्बु वासवांश्च विविधान् विभज्य प्रयोजयेत् विशेषतस्तु मध्वासवान् ग्राम्येषु तीक्ष्णान् त्रिफलासवान् वन्येषु न्यग्रोधादिफलासवान् विष्किरेषु अर्कशेलुशिरीषकपित्थासवान् बिलेशयेषु दिग्धहतेषु च अम्लफलासवान् प्रसहेषु काशेक्षुपद्मबीजशृङ्गाटककशेरुकमृद्वीकाखदिरासवान् क्षौद्रयुक्तं वा शीतमुदकमुदश्चिद्वा महामृगेष्वौदकेषु च सुरां प्रतुदेषु तथा श्रमार्त्तेषु कृशेषु च मधूदकं स्थूलेषु मद्यं मद्यमांससात्म्येष्वल्पाग्निषु अपि च समासेनान्नविपरीतमविरोधि च", text: "anupāne tu salilameva śreṣṭhaṃ sarvarasayonitvātsarvabhūtasātmyatvājjīvanādiguṇayogācca tacchītaṃ dadhimadhuyavagodhūmamadyaviśeṣeṣu sarveṣu ca vidāhiṣu śarad grīṣmayośca uṣṇaṃ piṣṭamayeṣvanyeṣu ca durjareṣu hemante ca dravadravyavijñānīyaṃ cekṣeta kṣīraṃ śāliṣaṣṭikayoḥ tathaivopavāsādhvabhāṣyastrīvyāyāmaklāntabālavṛddheṣu māṃsarasaḥ śoṣādiṣu vāte tvamlāni ca pitte śarkarodakam triphalodakaṃ tu sakṣaudraṃ śleṣmaṇi prāthaścākṣigalarogeṣu mastveva vā dadhni kūcikākīlāṭayośca dhānyāmlaṃ mastu takraṃ vā śākāvarānneṣu madyaṃ māṃseṣu phalāmlamambu vāsavāṃśca vividhān vibhajya prayojayet viśeṣatastu madhvāsavān grāmyeṣu tīkṣṇān triphalāsavān vanyeṣu nyagrodhādiphalāsavān viṣkireṣu arkaśeluśirīṣakapitthāsavān bileśayeṣu digdhahateṣu ca amlaphalāsavān prasaheṣu kāśekṣupadmabījaśṛṅgāṭakakaśerukamṛdvīkākhadirāsavān kṣaudrayuktaṃ vā śītamudakamudaścidvā mahāmṛgeṣvaudakeṣu ca surāṃ pratudeṣu tathā śramārtteṣu kṛśeṣu ca madhūdakaṃ sthūleṣu madyaṃ madyamāṃsasātmyeṣvalpāgniṣu api ca samāsenānnaviparītamavirodhi ca" },
      { type: "verse", number: "12", sanskrit: "अनुपानं खलु तर्पयति प्रीणयत्यूर्जयति बृंहयति देहस्य पर्याप्तिमभिनिर्वर्तयति भुक्तमवसादयत्यन्नसङ्घातं भिनत्ति मार्दवमापादयति क्लेदयति सुखपरिणामितामाशुव्यवायितां चाहारस्योपजनयति वर्ज्यं तूर्ध्वजत्रुगदश्वासकासप्रसेकहिध्मास्वरभेदोरःक्षतिभिर्गीतभाष्यप्रसक्तैश्च तेषां हि प्रदूष्यामाशयमुरःकण्ठस्थितमाहारजं स्नेहमासाद्य तदभिष्यन्दाग्निसादच्छर्द्यादीनामयान् विदध्यात् पीत्वा च भाष्यगेयाध्वस्वप्नान्न शीलयेत् पानं च प्रक्लिन्नदेहमेदहण्ठाक्षिरोगव्रणिन इति", text: "anupānaṃ khalu tarpayati prīṇayatyūrjayati bṛṃhayati dehasya paryāptimabhinirvartayati bhuktamavasādayatyannasaṅghātaṃ bhinatti mārdavamāpādayati kledayati sukhapariṇāmitāmāśuvyavāyitāṃ cāhārasyopajanayati varjyaṃ tūrdhvajatrugadaśvāsakāsaprasekahidhmāsvarabhedoraḥkṣatibhirgītabhāṣyaprasaktaiśca teṣāṃ hi pradūṣyāmāśayamuraḥkaṇṭhasthitamāhārajaṃ snehamāsādya tadabhiṣyandāgnisādacchardyādīnāmayān vidadhyāt pītvā ca bhāṣyageyādhvasvapnānna śīlayet pānaṃ ca praklinnadehamedahaṇṭhākṣirogavraṇina iti" },
      { type: "verse", number: "13", sanskrit: "ततः पाणिगतमन्नमन्येनापनीय दन्तान्तरस्थं च शनैः शनैः शोधनेन विशोध्य लेपगन्धस्नेहापनोदमाचान्तो ऽङ्गुल्यग्रगलिताम्बुपरिषिक्तनेत्रस्ताम्बूलादिकृत वदनवैशद्यो धूमपानादिहृतोर्ध्वकफवेगः पदशतमात्रं गत्वा वामपार्श्वेन संविशेत् द्रवोत्तरभोजनस्तु शय्यां नातिसेवेत यानप्लवनवाहनाग्न्यातपांश्च भुक्तवान् वर्जयेत् आहारपरिणामकराः पुनरिमे भावाः तद्यथा ऊष्मा वायुः स्नेहः क्लेदः कालः समयोगश्च तत्रोष्मा पचति वायुरपकर्षति स्नेहो मार्दवं जनयति क्लैदः शैथिल्यमापादयति कालः सर्ववपुर्व्याप्तिमभिनिर्वर्त्तयति समयोगस्त्वेषामन्नपरिणामधातुसाम्यकरः सम्पद्यते समयोगस्य तु पुनः कारणान्युचितो हितश्च देहसंस्कारो ऽभ्यवहारश्चेष्टा शयनं सौमनस्यं च परिणमतस्त्वाहारस्य गुणाः शरीरगुणभावमापद्यन्ते यथास्वमविरुद्धाः विरुद्धास्तु विहताश्च विरोधिभिर्विहन्युः शरीरमिति भवन्ति चात्र", text: "tataḥ pāṇigatamannamanyenāpanīya dantāntarasthaṃ ca śanaiḥ śanaiḥ śodhanena viśodhya lepagandhasnehāpanodamācānto 'ṅgulyagragalitāmbupariṣiktanetrastāmbūlādikṛta vadanavaiśadyo dhūmapānādihṛtordhvakaphavegaḥ padaśatamātraṃ gatvā vāmapārśvena saṃviśet dravottarabhojanastu śayyāṃ nātiseveta yānaplavanavāhanāgnyātapāṃśca bhuktavān varjayet āhārapariṇāmakarāḥ punarime bhāvāḥ tadyathā ūṣmā vāyuḥ snehaḥ kledaḥ kālaḥ samayogaśca tatroṣmā pacati vāyurapakarṣati sneho mārdavaṃ janayati klaidaḥ śaithilyamāpādayati kālaḥ sarvavapurvyāptimabhinirvarttayati samayogastveṣāmannapariṇāmadhātusāmyakaraḥ sampadyate samayogasya tu punaḥ kāraṇānyucito hitaśca dehasaṃskāro 'bhyavahāraśceṣṭā śayanaṃ saumanasyaṃ ca pariṇamatastvāhārasya guṇāḥ śarīraguṇabhāvamāpadyante yathāsvamaviruddhāḥ viruddhāstu vihatāśca virodhibhirvihanyuḥ śarīramiti bhavanti cātra" },
      { type: "verse", number: "14", sanskrit: "औकुलाभ्योषपृथुकान् सुपिष्टकृततण्डुलान् न जातुभुक्तवानद्यान्मात्रयाद्यात्सुकाङ्क्षितः", text: "aukulābhyoṣapṛthukān supiṣṭakṛtataṇḍulān na jātubhuktavānadyānmātrayādyātsukāṅkṣitaḥ" },
      { type: "verse", number: "15", sanskrit: "शाकावरान्नकट्वम्लकषायलवणोत्कटम् त्यजेदेहरसासात्म्यं गुरु शुष्कं च भोजनम्", text: "śākāvarānnakaṭvamlakaṣāyalavaṇotkaṭam tyajedeharasāsātmyaṃ guru śuṣkaṃ ca bhojanam" },
      { type: "verse", number: "16", sanskrit: "वक्ष्यते यन्निदानादौ सर्वदोषप्रकोपणम् अत्यभिष्यन्दि विष्टम्भि विदाहि गुरु रूक्षणम्", text: "vakṣyate yannidānādau sarvadoṣaprakopaṇam atyabhiṣyandi viṣṭambhi vidāhi guru rūkṣaṇam" },
      { type: "verse", number: "17", sanskrit: "कीलाटदधिकूचीकामत्स्यशुष्काममूलकम् क्षारपिष्टविरूढाद्यं तत्समस्तं न शीलयेत्", text: "kīlāṭadadhikūcīkāmatsyaśuṣkāmamūlakam kṣārapiṣṭavirūḍhādyaṃ tatsamastaṃ na śīlayet" },
      { type: "verse", number: "18", sanskrit: "शीलयेच्छालिगोधूमयवषष्टिकजाङ्गलम् सुनिषण्णकजीवन्तीबालमूलकवास्तुकम्", text: "śīlayecchāligodhūmayavaṣaṣṭikajāṅgalam suniṣaṇṇakajīvantībālamūlakavāstukam" },
      { type: "verse", number: "19", sanskrit: "पथ्यामलकमृद्धीकापटोलीमुद्गशर्कराः घृतंदिव्योदकक्षीरक्षौद्रदाडिमसैन्धवम्", text: "pathyāmalakamṛddhīkāpaṭolīmudgaśarkarāḥ ghṛtaṃdivyodakakṣīrakṣaudradāḍimasaindhavam" },
      { type: "verse", number: "20", sanskrit: "त्रिफलां मधुसर्पिर्भ्यां निशि नेत्रबलाय च स्वास्थ्यानुवृत्तिकृद्यच्च रोगोच्छेदकरं च यत्", text: "triphalāṃ madhusarpirbhyāṃ niśi netrabalāya ca svāsthyānuvṛttikṛdyacca rogocchedakaraṃ ca yat" },
      { type: "verse", number: "21", sanskrit: "स्वभावमात्रायोगादिपरस्परविपर्ययैः भोजनानि विरुध्यन्ते तानि विद्वान् विवर्जयेत्", text: "svabhāvamātrāyogādiparasparaviparyayaiḥ bhojanāni virudhyante tāni vidvān vivarjayet" },
      { type: "verse", number: "22", sanskrit: "त्यागाद्विषमहेतूनां समानां चोपसेवनात् विषमा नानुबध्नन्ति जायन्ते धातवः समाः", text: "tyāgādviṣamahetūnāṃ samānāṃ copasevanāt viṣamā nānubadhnanti jāyante dhātavaḥ samāḥ" },
      { type: "verse", number: "23", sanskrit: "अन्नेन कुक्षेर्द्वावंशौ पानेनैकं प्रपूरयेत् आश्रयं पवनादीनां चतुर्थमवशेषयेत्", text: "annena kukṣerdvāvaṃśau pānenaikaṃ prapūrayet āśrayaṃ pavanādīnāṃ caturthamavaśeṣayet" },
      { type: "verse", number: "24", sanskrit: "मन्दानलबलारोग्यनृपेश्वरसुखात्मसु योज्यः क्रमो ऽयं सततं नावश्यमितरेषु च", text: "mandānalabalārogyanṛpeśvarasukhātmasu yojyaḥ kramo 'yaṃ satataṃ nāvaśyamitareṣu ca" },
      { type: "verse", number: "25", sanskrit: "करोति रूक्षं बलवर्णनाशं त्वग्रूक्षतां वातशकृन्निरोधम् स्निग्धं त्वतिश्लेष्मचयप्रसेक हृद्गौरवालस्यरुचिप्रणाशान्", text: "karoti rūkṣaṃ balavarṇanāśaṃ tvagrūkṣatāṃ vātaśakṛnnirodham snigdhaṃ tvatiśleṣmacayapraseka hṛdgauravālasyarucipraṇāśān" },
      { type: "verse", number: "26", sanskrit: "अत्युष्णमन्नं मददाहतृष्णाबलप्रणाशभ्रमरक्तपित्तम् शीतं तु सादारुचिवह्निसादहृल्लासविष्टम्भनरोमहर्षान्", text: "atyuṣṇamannaṃ madadāhatṛṣṇābalapraṇāśabhramaraktapittam śītaṃ tu sādārucivahnisādahṛllāsaviṣṭambhanaromaharṣān" },
      { type: "verse", number: "27", sanskrit: "अतिस्थिरं मूत्रशकृद्विबन्धमतृप्तिमव्याप्तिमशीघ्रपक्तिम् अतिद्रवं पीनसमेहकासस्यन्दान् करोत्यग्निबलं च हन्ति", text: "atisthiraṃ mūtraśakṛdvibandhamatṛptimavyāptimaśīghrapaktim atidravaṃ pīnasamehakāsasyandān karotyagnibalaṃ ca hanti" },
      { type: "verse", number: "28", sanskrit: "अतिमधुरमनलशमनं भुक्तमसात्म्यं न पुष्टये वपुषः अतिलवणमचक्षुष्यं तीक्ष्णात्यमलं जरा साक्षात्", text: "atimadhuramanalaśamanaṃ bhuktamasātmyaṃ na puṣṭaye vapuṣaḥ atilavaṇamacakṣuṣyaṃ tīkṣṇātyamalaṃ jarā sākṣāt" },
      { type: "verse", number: "29", sanskrit: "तनुमपि तनुजां रुजां त्वनाप्य व्रजति नरः स समाशतस्य पारम्", text: "tanumapi tanujāṃ rujāṃ tvanāpya vrajati naraḥ sa samāśatasya pāram" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 11,
    lang: "sa",
    content: [
      { type: "heading", heading: "Виречана видхи — слабительная терапия" },
      { type: "text", text: "Глава 11 Сутрастханы Астанга-санграхи посвящена теме «слабительная терапия». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो मात्राशितीयं नामाध्यायं व्याख्यास्यामः इति हस्माहुरात्त्रेयादयो महर्षयः", text: "athāto mātrāśitīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti hasmāhurāttreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "मात्राशी स्यात् मात्रा पुनरग्निबलाहारद्रव्यापेक्षिणी कुक्षेरप्रतिपीडनमाहारेण हृदयस्यासंरोधः पार्श्वयोरविपाटनमनतिगौरवमुदरस्य प्रीणनमिन्द्रियाणां क्षुत्पिपासोपरतिः स्थानासनशयनगमनोच्छ्वासप्रश्वासभाष्यसङ्कथासु सुखानुवृत्तिः सायं प्रातश्च सुखेन परिणमनं बलवर्णोपचयकरत्वं चेति मात्राया लक्षणम्", text: "mātrāśī syāt mātrā punaragnibalāhāradravyāpekṣiṇī kukṣerapratipīḍanamāhāreṇa hṛdayasyāsaṃrodhaḥ pārśvayoravipāṭanamanatigauravamudarasya prīṇanamindriyāṇāṃ kṣutpipāsoparatiḥ sthānāsanaśayanagamanocchvāsapraśvāsabhāṣyasaṅkathāsu sukhānuvṛttiḥ sāyaṃ prātaśca sukhena pariṇamanaṃ balavarṇopacayakaratvaṃ ceti mātrāyā lakṣaṇam" },
      { type: "verse", number: "3", sanskrit: "त्रिभागसौहित्यमर्द्धसौहित्यं वा गुरूणामुपदिश्यते लघूनामपि नातिसौहित्यम् अनिलानलगुणबहुलानि हि लघूनि तुल्यगुणत्वादग्निसन्धुक्षणान्यविधिना चाल्पदोषाणि इतराणि तु पृथिवीसलिलगुणबहुलान्यसामान्याद्विपरीतान्यन्यत्र व्यायामाग्निबलात् अमात्रा पुनरशनस्य हीनताधिक्यं च तत्र हीनमात्रमशनं बलवर्णोपचयमनोबुद्धीन्द्रियोपघातकरं विबन्धकृदवृष्यमनौजस्यं सारविध्मापनमलक्ष्मीजननमशीतेश्च वातविकाराणामायतनम् अतिमात्रं पुनः सर्वदोषप्रकोपनमाहुः तेन हि प्रपीड्यमाना वातादयो युगपत्प्रकुपिताः कुक्ष्यैकदेशस्थास्तदेवापरिपक्वमाविश्य विष्टम्भयन्तो ऽलसकमभिनिर्वर्तयन्ति सहसा वाधरोत्तराभ्यां मार्गाभ्यां प्रत्त्यावयन्तो विषूचिकाम्", text: "tribhāgasauhityamarddhasauhityaṃ vā gurūṇāmupadiśyate laghūnāmapi nātisauhityam anilānalaguṇabahulāni hi laghūni tulyaguṇatvādagnisandhukṣaṇānyavidhinā cālpadoṣāṇi itarāṇi tu pṛthivīsalilaguṇabahulānyasāmānyādviparītānyanyatra vyāyāmāgnibalāt amātrā punaraśanasya hīnatādhikyaṃ ca tatra hīnamātramaśanaṃ balavarṇopacayamanobuddhīndriyopaghātakaraṃ vibandhakṛdavṛṣyamanaujasyaṃ sāravidhmāpanamalakṣmījananamaśīteśca vātavikārāṇāmāyatanam atimātraṃ punaḥ sarvadoṣaprakopanamāhuḥ tena hi prapīḍyamānā vātādayo yugapatprakupitāḥ kukṣyaikadeśasthāstadevāparipakvamāviśya viṣṭambhayanto 'lasakamabhinirvartayanti sahasā vādharottarābhyāṃ mārgābhyāṃ prattyāvayanto viṣūcikām" },
      { type: "verse", number: "4", sanskrit: "अपि च प्रयाति नोर्ध्वं नाधस्तादाहारो न च पच्यते आमाशये ऽलसीभूतस्तेन सो ऽलसकः स्मृतः", text: "api ca prayāti nordhvaṃ nādhastādāhāro na ca pacyate āmāśaye 'lasībhūtastena so 'lasakaḥ smṛtaḥ" },
      { type: "verse", number: "5", sanskrit: "विविधैर्वेदनोद्भेदैर्वाय्वादिभृशकोपतः सूचीभिरिव गात्राणि विध्यतीति विषूचिका", text: "vividhairvedanodbhedairvāyvādibhṛśakopataḥ sūcībhiriva gātrāṇi vidhyatīti viṣūcikā" },
      { type: "verse", number: "6", sanskrit: "तत्र वातः शूलानाहाङ्गमर्दमुखशोषप्रलापकम्पमूर्च्छभ्रमजृम्भोद्वेष्टनाक्षिप्रवेशशिरोहृदयातिरुक्सिरा कुञ्चनस्तम्भनानि करोति पित्तं पुनर्ज्वरातिसारान्तर्दाहवैवर्ण्यतृष्णामदभ्रमप्रलयानि श्लेष्मा तु छर्द्यरोचकप्रसेकाङ्गसादाविपाकशीतज्वरगात्रगौरवाणि विशेषतस्तु दुर्बलस्याल्पवह्नेर्बहुश्लेष्मणोवातमूत्रपुरीषवेगविधारिणो ऽन्नपानमनिलप्रपीडितं श्लेष्मणाविबद्धमार्गमलसत्वादबहिर्मुखीभवत् छर्द्यतीसारवर्ज्यानि यथोक्तानि शूलादीन्युपजनयत्यतिमात्राणि सो ऽलसः अतिमात्रदुष्टास्तु दोषाः शरीरं दण्डवत् स्तम्भयन्ति ततस्तमलसकमसाध्यं ब्रुवते", text: "tatra vātaḥ śūlānāhāṅgamardamukhaśoṣapralāpakampamūrcchabhramajṛmbhodveṣṭanākṣipraveśaśirohṛdayātiruksirā kuñcanastambhanāni karoti pittaṃ punarjvarātisārāntardāhavaivarṇyatṛṣṇāmadabhramapralayāni śleṣmā tu chardyarocakaprasekāṅgasādāvipākaśītajvaragātragauravāṇi viśeṣatastu durbalasyālpavahnerbahuśleṣmaṇovātamūtrapurīṣavegavidhāriṇo 'nnapānamanilaprapīḍitaṃ śleṣmaṇāvibaddhamārgamalasatvādabahirmukhībhavat chardyatīsāravarjyāni yathoktāni śūlādīnyupajanayatyatimātrāṇi so 'lasaḥ atimātraduṣṭāstu doṣāḥ śarīraṃ daṇḍavat stambhayanti tatastamalasakamasādhyaṃ bruvate" },
      { type: "verse", number: "7", sanskrit: "विरुद्धाध्यशनाजीर्णशीलिनः पुनरामदोषमामविषमामनन्ति विषसदृशलिङ्गत्वात् तत्परमसाध्यानाम् अशुकारितया विरुद्धोपक्रमत्वाच्च न च केवलं मात्रयैव कृत्स्नमाहारफलमवाप्तुं शक्यं स्वभावादीनां भिन्नफलत्वात्", text: "viruddhādhyaśanājīrṇaśīlinaḥ punarāmadoṣamāmaviṣamāmananti viṣasadṛśaliṅgatvāt tatparamasādhyānām aśukāritayā viruddhopakramatvācca na ca kevalaṃ mātrayaiva kṛtsnamāhāraphalamavāptuṃ śakyaṃ svabhāvādīnāṃ bhinnaphalatvāt" },
      { type: "verse", number: "8", sanskrit: "तथा हि गुरुरूक्षशुष्कशीतद्विष्टविष्टम्भिविदाअह्यशुचिविरुद्धात्यम्बुपानद्रवमकाले काले वा कामक्रोधलोभेर्ष्याद्व्रीशोकोद्वेगभयक्षुदुपतप्तेन वा यदन्नपानमुपयुज्यते तदप्याममेव प्रदूषयति", text: "tathā hi gururūkṣaśuṣkaśītadviṣṭaviṣṭambhividāahyaśuciviruddhātyambupānadravamakāle kāle vā kāmakrodhalobherṣyādvrīśokodvegabhayakṣudupataptena vā yadannapānamupayujyate tadapyāmameva pradūṣayati" },
      { type: "verse", number: "9", sanskrit: "तत्र साध्यमानं दुष्टमलसीभूतमुल्लिखेत् पाययित्वा सलवणमुष्णं वारि तथात्वच्छर्दयन्तमतिलीनदोषं कृष्णानागदन्तीकल्कयुक्तं पाययेत् मदनफलकषायं वा पिप्पलीसिद्धार्थकल्कयुक्तम् दन्तीमागधिकावचूर्णितं वा कोशातकीरसम् अवस्थापेक्षी वा वमनकल्पोक्तानि तीक्ष्णवमनानि ततः स्वेदवर्त्तिप्रणिधानाभ्यामुपाचरेत्", text: "tatra sādhyamānaṃ duṣṭamalasībhūtamullikhet pāyayitvā salavaṇamuṣṇaṃ vāri tathātvacchardayantamatilīnadoṣaṃ kṛṣṇānāgadantīkalkayuktaṃ pāyayet madanaphalakaṣāyaṃ vā pippalīsiddhārthakalkayuktam dantīmāgadhikāvacūrṇitaṃ vā kośātakīrasam avasthāpekṣī vā vamanakalpoktāni tīkṣṇavamanāni tataḥ svedavarttipraṇidhānābhyāmupācaret" },
      { type: "verse", number: "10", sanskrit: "अपि च सद्यः सम्यग्विशुद्धस्य शाम्यन्ति तदुपद्रवाः शूले निरन्नकोष्ठे ऽद्भिः कोष्णाभिश्चूर्णिताः पिबेत्", text: "api ca sadyaḥ samyagviśuddhasya śāmyanti tadupadravāḥ śūle nirannakoṣṭhe 'dbhiḥ koṣṇābhiścūrṇitāḥ pibet" },
      { type: "verse", number: "11", sanskrit: "हिङ्गुप्रतिविषाव्योषसौवर्चलवचाभयाः अथवा पिप्पलीमूलं त्रिवृतादारुसैन्धवम्", text: "hiṅguprativiṣāvyoṣasauvarcalavacābhayāḥ athavā pippalīmūlaṃ trivṛtādārusaindhavam" },
      { type: "verse", number: "12", sanskrit: "शुण्ठीः सक्षीरलवणपिप्पलीमरिचानि च पाठाम्लवेतसक्षारयवानीपौष्कराणि वा", text: "śuṇṭhīḥ sakṣīralavaṇapippalīmaricāni ca pāṭhāmlavetasakṣārayavānīpauṣkarāṇi vā" },
      { type: "verse", number: "13", sanskrit: "द्विरुत्तरं हिङ्गुवचाग्निकुष्ठ सुवर्चिकाक्षारबिडाजमोजम् शूलोदरानाहविषूचिकार्शोहृद्रोगगुल्मोर्ध्वसमीरणघ्नम्", text: "dviruttaraṃ hiṅguvacāgnikuṣṭha suvarcikākṣārabiḍājamojam śūlodarānāhaviṣūcikārśohṛdrogagulmordhvasamīraṇaghnam" },
      { type: "verse", number: "14", sanskrit: "मुस्ताजमोजपूजीकवचाशुण्ठ्यग्निधान्यकैः सवालकशठीबिल्वैः क्वाथं तृट्च्छूलवान् पिबेत्", text: "mustājamojapūjīkavacāśuṇṭhyagnidhānyakaiḥ savālakaśaṭhībilvaiḥ kvāthaṃ tṛṭcchūlavān pibet" },
      { type: "verse", number: "15", sanskrit: "रास्नाकट्फलषङ्ग्रन्थाबृहतीद्वयजोङ्गकैः गुग्गुल्वतिविषाकुष्ठपत्रत्र्याघ्रनखाम्बुदैः कुर्याच्छुष्कैः समूत्रैर्वा लेपोद्वर्त्तनधूपनम्", text: "rāsnākaṭphalaṣaṅgranthābṛhatīdvayajoṅgakaiḥ guggulvativiṣākuṣṭhapatratryāghranakhāmbudaiḥ kuryācchuṣkaiḥ samūtrairvā lepodvarttanadhūpanam" },
      { type: "verse", number: "16", sanskrit: "सरुक्चानद्धमुदरमम्लपिष्टैः प्रलेपयेत् दारुहैमवतीकुष्ठशताह्वाहिङ्गुसैन्धवैः", text: "sarukcānaddhamudaramamlapiṣṭaiḥ pralepayet dāruhaimavatīkuṣṭhaśatāhvāhiṅgusaindhavaiḥ" },
      { type: "verse", number: "17", sanskrit: "यवचूर्णश्च सक्षारतक्रः कोष्ठार्तिजित् परम् योजयेत्सैन्धवान्तैश्च वर्तिं विण्मूत्रसङ्ग्रहे", text: "yavacūrṇaśca sakṣāratakraḥ koṣṭhārtijit param yojayetsaindhavāntaiśca vartiṃ viṇmūtrasaṅgrahe" },
      { type: "verse", number: "18", sanskrit: "नाम्यमानानि चाङ्गानि भृशं स्विन्नानि वेष्टयेत् विषूच्यामतिवृद्धायां पार्ष्ण्योर्दाहः प्रशस्यते", text: "nāmyamānāni cāṅgāni bhṛśaṃ svinnāni veṣṭayet viṣūcyāmativṛddhāyāṃ pārṣṇyordāhaḥ praśasyate" },
      { type: "verse", number: "19", sanskrit: "द्विक्षारजीर्णपिण्याककुष्ठारुष्करचित्रकैः सशुक्तसैन्धवैस्तैलं पक्वमभ्यञ्जने हितम्", text: "dvikṣārajīrṇapiṇyākakuṣṭhāruṣkaracitrakaiḥ saśuktasaindhavaistailaṃ pakvamabhyañjane hitam" },
      { type: "verse", number: "20", sanskrit: "सुच्छर्दितविरिक्तस्य गात्रायामे ऽतिदारुणे भल्लातकमधूच्छिष्टजीर्णपिण्याकनागरैः घृततैलं पचेत्साम्लैस्तच्च खल्लीघ्नमुत्तमम्", text: "succharditaviriktasya gātrāyāme 'tidāruṇe bhallātakamadhūcchiṣṭajīrṇapiṇyākanāgaraiḥ ghṛtatailaṃ pacetsāmlaistacca khallīghnamuttamam" },
      { type: "verse", number: "21", sanskrit: "त्वक्पत्ररास्नागरुशिग्रुकुष्ठैरम्लप्रपिष्टैः सवचाशताह्वैः उद्वर्त्तनं खल्लिविषूचिकाघ्नं तैलं विपक्वं च तदर्थकारि", text: "tvakpatrarāsnāgaruśigrukuṣṭhairamlaprapiṣṭaiḥ savacāśatāhvaiḥ udvarttanaṃ khalliviṣūcikāghnaṃ tailaṃ vipakvaṃ ca tadarthakāri" },
      { type: "verse", number: "22", sanskrit: "तदहश्चोपवास्यैनं विरिक्तवदुपाचरेत् सामान्येनेति सिद्धोक्ता विषूच्यलसकक्रिया", text: "tadahaścopavāsyainaṃ viriktavadupācaret sāmānyeneti siddhoktā viṣūcyalasakakriyā" },
      { type: "verse", number: "23", sanskrit: "आमदोषेषु त्वन्नकाले जीर्णाहारं दोषोपलिप्तामाशयं स्तिमितगुरुकोष्ठमनन्नाभिलाषिणमभिसमीक्ष्य पाययेद्दोषशेषपाचनार्थमौषधं वह्निसन्धुक्षणार्थं च अजीर्णाहारं पुनर्न पाययेत् यत आमदोषदुर्बलो ह्यग्निर्युगपदामदोषमौषधमाहारजातं चाशक्तः पक्तुम्", text: "āmadoṣeṣu tvannakāle jīrṇāhāraṃ doṣopaliptāmāśayaṃ stimitagurukoṣṭhamanannābhilāṣiṇamabhisamīkṣya pāyayeddoṣaśeṣapācanārthamauṣadhaṃ vahnisandhukṣaṇārthaṃ ca ajīrṇāhāraṃ punarna pāyayet yata āmadoṣadurbalo hyagniryugapadāmadoṣamauṣadhamāhārajātaṃ cāśaktaḥ paktum" },
      { type: "verse", number: "24", sanskrit: "अपि चैषा विभ्रमो ऽतिबलत्वादुपरतानलबलमातुरं सहसैवातिपातत्येत् आमदोषजानां पुनर्विकाराणामपतर्पणेनैवोपशमो भवति", text: "api caiṣā vibhramo 'tibalatvāduparatānalabalamāturaṃ sahasaivātipātatyet āmadoṣajānāṃ punarvikārāṇāmapatarpaṇenaivopaśamo bhavati" },
      { type: "verse", number: "25", sanskrit: "तत्तु त्रिविधम् लङ्घनं लङ्घनपाचनमवसेचनं च तत्र लङ्घनमल्पदोषाणाम् तेन ह्यनिलानलवृध्या वातातपपरीत इवाल्पः सलिलाशयो ऽल्पदोषः प्रशोषमापद्यते लङ्घनपाचनाभ्यां मध्यदोषे वातातपाभ्यां पांसुभस्मावकिरणैरिव चानतिमहान् सलिलाशयः बहुदोषाणां पुनर्दोषावसेचनमेव कार्यम् न ह्यस्राविते पल्वलोदकौघे शाल्यादिपुष्टिर्भवति", text: "tattu trividham laṅghanaṃ laṅghanapācanamavasecanaṃ ca tatra laṅghanamalpadoṣāṇām tena hyanilānalavṛdhyā vātātapaparīta ivālpaḥ salilāśayo 'lpadoṣaḥ praśoṣamāpadyate laṅghanapācanābhyāṃ madhyadoṣe vātātapābhyāṃ pāṃsubhasmāvakiraṇairiva cānatimahān salilāśayaḥ bahudoṣāṇāṃ punardoṣāvasecanameva kāryam na hyasrāvite palvalodakaughe śālyādipuṣṭirbhavati" },
      { type: "verse", number: "26", sanskrit: "तस्मात्सन्तर्पणनिमित्तानां नान्तरेणापतर्पणमस्ति शान्तिः अपतर्पणनिमित्तानां च नान्तरेण सन्तर्पणमिति एवमन्येषामपि व्याधीनां यथास्वं निदानविपरीतमौषधमेवावचारयेत् सति त्वनुबन्धे निदानविपरीतमपास्य व्याधिविपरीतमेव तदर्थकारि वा विमुक्तामदोषस्य पुनः परिपक्वामदोषशेषस्य दीप्ते चाग्नावभ्यङ्गास्थापनानुवासनं विविधस्नेहपानं च युक्त्या प्रयोज्यम् प्रसमीक्ष्य दोषौषधादीनामवस्थान्तराणि भवन्ति चात्र", text: "tasmātsantarpaṇanimittānāṃ nāntareṇāpatarpaṇamasti śāntiḥ apatarpaṇanimittānāṃ ca nāntareṇa santarpaṇamiti evamanyeṣāmapi vyādhīnāṃ yathāsvaṃ nidānaviparītamauṣadhamevāvacārayet sati tvanubandhe nidānaviparītamapāsya vyādhiviparītameva tadarthakāri vā vimuktāmadoṣasya punaḥ paripakvāmadoṣaśeṣasya dīpte cāgnāvabhyaṅgāsthāpanānuvāsanaṃ vividhasnehapānaṃ ca yuktyā prayojyam prasamīkṣya doṣauṣadhādīnāmavasthāntarāṇi bhavanti cātra" },
      { type: "verse", number: "27", sanskrit: "यः श्यावदन्तौष्ठनखो ऽल्पसंज्ञः छर्द्यर्दितो ऽन्तर्गतताम्रनेत्रः क्षामस्वरः स्रस्तसमस्तसन्धिर्यायान्नरो ऽसौ पुनरागमाय", text: "yaḥ śyāvadantauṣṭhanakho 'lpasaṃjñaḥ chardyardito 'ntargatatāmranetraḥ kṣāmasvaraḥ srastasamastasandhiryāyānnaro 'sau punarāgamāya" },
      { type: "verse", number: "28", sanskrit: "व्योषं करञ्जस्य फलं हरिद्रे मूलं समावाप्य च मातुलुङ्ग्याः छयाविशुष्का गुलिकाः कृतास्ता हन्युर्विषूचीं नयनाञ्जनेन", text: "vyoṣaṃ karañjasya phalaṃ haridre mūlaṃ samāvāpya ca mātuluṅgyāḥ chayāviśuṣkā gulikāḥ kṛtāstā hanyurviṣūcīṃ nayanāñjanena" },
      { type: "verse", number: "29", sanskrit: "शिरीषनक्ताह्वफणिज्जबीजत्रायन्त्यपामाअर्गफलैश्च वर्त्तिः बस्तस्य मूत्रेण विषूचिकाघ्नी प्रलेपधूपाञ्जननस्ययोगैः", text: "śirīṣanaktāhvaphaṇijjabījatrāyantyapāmāargaphalaiśca varttiḥ bastasya mūtreṇa viṣūcikāghnī pralepadhūpāñjananasyayogaiḥ" },
      { type: "verse", number: "30", sanskrit: "अजीर्णं च कफादामं विष्टब्धमनिलाद्भवेत् विदग्धं पित्तकोपेन त्रिप्रकारमिति स्मृतम्", text: "ajīrṇaṃ ca kaphādāmaṃ viṣṭabdhamanilādbhavet vidagdhaṃ pittakopena triprakāramiti smṛtam" },
      { type: "verse", number: "31", sanskrit: "तत्रामे गुरुतोत्क्लेदः शोफो गण्डाक्षिकूटयोः उद्गारश्च यथाभुक्तमविदग्धः प्रवर्त्तते", text: "tatrāme gurutotkledaḥ śopho gaṇḍākṣikūṭayoḥ udgāraśca yathābhuktamavidagdhaḥ pravarttate" },
      { type: "verse", number: "32", sanskrit: "विष्टब्धे शूलमाध्मानं विविधा वातवेदनाः मलवाताप्रवृत्तिश्च स्तम्भो मोहो ऽङ्गपीडनम्", text: "viṣṭabdhe śūlamādhmānaṃ vividhā vātavedanāḥ malavātāpravṛttiśca stambho moho 'ṅgapīḍanam" },
      { type: "verse", number: "33", sanskrit: "विदग्धे भ्रमतृण्मूर्छाः पित्तच्च विविधा रुजाः उद्गारश्च साधूमाम्लः स्वेदो दाहश्च जायते", text: "vidagdhe bhramatṛṇmūrchāḥ pittacca vividhā rujāḥ udgāraśca sādhūmāmlaḥ svedo dāhaśca jāyate" },
      { type: "verse", number: "34", sanskrit: "लङ्घनं कार्यमामे तु विष्टब्धे स्वेदनं भृशम् विदग्धे वमनं यद्वा यथावस्थं हितं भवेत्", text: "laṅghanaṃ kāryamāme tu viṣṭabdhe svedanaṃ bhṛśam vidagdhe vamanaṃ yadvā yathāvasthaṃ hitaṃ bhavet" },
      { type: "verse", number: "35", sanskrit: "रगीयसो भवेल्लीनादामादेव विलम्बिका कफवातानुविद्धामलिङ्गा तत्समसाधना", text: "ragīyaso bhavellīnādāmādeva vilambikā kaphavātānuviddhāmaliṅgā tatsamasādhanā" },
      { type: "verse", number: "36", sanskrit: "रसशेषे ऽन्नविद्वेषो हृदयाशुद्धिगौरवे तत्राभुक्त्वा दिवस्वप्यात् क्षुद्वानद्याल्लघुप्रति", text: "rasaśeṣe 'nnavidveṣo hṛdayāśuddhigaurave tatrābhuktvā divasvapyāt kṣudvānadyāllaghuprati" },
      { type: "verse", number: "37", sanskrit: "यामैश्चतुर्भिर्द्वाभ्यां च भोज्यभैषज्ययोः समे पाको ऽग्नौयुक्तयोर्द्राक्च तीक्ष्णे मन्दे पुनश्चिरात्", text: "yāmaiścaturbhirdvābhyāṃ ca bhojyabhaiṣajyayoḥ same pāko 'gnauyuktayordrākca tīkṣṇe mande punaścirāt" },
      { type: "verse", number: "38", sanskrit: "सभक्तमौषधं तस्मान्मन्दाग्नेरवचारयेत् पूर्वाह्णे भोजनं सात्म्यं लघु दीपनबृंहणम्", text: "sabhaktamauṣadhaṃ tasmānmandāgneravacārayet pūrvāhṇe bhojanaṃ sātmyaṃ laghu dīpanabṛṃhaṇam" },
      { type: "verse", number: "39", sanskrit: "प्रातराशे त्वजीर्णे ऽपि सायमाशो न दुष्यति अजीर्णे सायमाशे तु प्रातराशो हि दुष्यति", text: "prātarāśe tvajīrṇe 'pi sāyamāśo na duṣyati ajīrṇe sāyamāśe tu prātarāśo hi duṣyati" },
      { type: "verse", number: "40", sanskrit: "दिवा प्रबोध्यते ऽर्केण हृदयं पुण्डरीकवत् तस्मिन्विबुद्धे स्रोतांसि स्फुटत्वं यान्ति सर्वशः", text: "divā prabodhyate 'rkeṇa hṛdayaṃ puṇḍarīkavat tasminvibuddhe srotāṃsi sphuṭatvaṃ yānti sarvaśaḥ" },
      { type: "verse", number: "41", sanskrit: "व्यायामाच्च विचाराच्च विक्षिप्तत्वाच्च चेतसः न क्लेदमुपगच्छन्ति दिवा तेनास्य धातवः", text: "vyāyāmācca vicārācca vikṣiptatvācca cetasaḥ na kledamupagacchanti divā tenāsya dhātavaḥ" },
      { type: "verse", number: "42", sanskrit: "अक्लिन्नेष्वन्नमासिक्तमत्यन्तेन न दुष्यति अविदग्धेष्विव पयस्स्वन्यत्संमिश्रितं पयः", text: "aklinneṣvannamāsiktamatyantena na duṣyati avidagdheṣviva payassvanyatsaṃmiśritaṃ payaḥ" },
      { type: "verse", number: "43", sanskrit: "रात्रौ तु हृदये म्लाने संवृतेष्वयनेषु च यान्ति कोष्ठे परिक्लेदं संवृते सर्वधातवः", text: "rātrau tu hṛdaye mlāne saṃvṛteṣvayaneṣu ca yānti koṣṭhe parikledaṃ saṃvṛte sarvadhātavaḥ" },
      { type: "verse", number: "44", sanskrit: "क्लिन्नेष्वन्यदपक्वेषु तेष्वासिक्तं प्रदुष्यति विदग्धेषु पयस्स्वन्यात् पयस्तप्तेष्विवापितम् नैशे तस्मादजीर्णे ऽन्ने नान्यद्भुञ्जीत भोजनम्", text: "klinneṣvanyadapakveṣu teṣvāsiktaṃ praduṣyati vidagdheṣu payassvanyāt payastapteṣvivāpitam naiśe tasmādajīrṇe 'nne nānyadbhuñjīta bhojanam" },
      { type: "verse", number: "45", sanskrit: "उद्गारशुद्धिरुत्साहो वेगोत्सर्गो यथोचितः लघुता क्षुत्पिपास च जीर्णाहारस्य लक्षणम्", text: "udgāraśuddhirutsāho vegotsargo yathocitaḥ laghutā kṣutpipāsa ca jīrṇāhārasya lakṣaṇam" },
      { type: "verse", number: "46", sanskrit: "प्रायः प्रज्ञापराधेन रोगग्रामः प्रजायते नृणामशनलुब्धानां विशेषेण विषूचिका", text: "prāyaḥ prajñāparādhena rogagrāmaḥ prajāyate nṛṇāmaśanalubdhānāṃ viśeṣeṇa viṣūcikā" },
      { type: "verse", number: "47", sanskrit: "दोषोपनद्धं यदि लीनमन्नं पित्तोल्बणरयावृणुयान्न वह्निम् जायेत दुष्टा तु ततो बुधुक्षा या मन्दबुद्धीन् विषवन्निहन्ति", text: "doṣopanaddhaṃ yadi līnamannaṃ pittolbaṇarayāvṛṇuyānna vahnim jāyeta duṣṭā tu tato budhukṣā yā mandabuddhīn viṣavannihanti" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 12,
    lang: "sa",
    content: [
      { type: "heading", heading: "Насья видхи — назальная терапия" },
      { type: "text", text: "Глава 12 Сутрастханы Астанга-санграхи посвящена теме «назальная терапия». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो द्विविधौषधविज्ञानीयमध्यायं व्याख्यास्यामः इति हस्माहुरात्रेयादयो महर्षयः", text: "athāto dvividhauṣadhavijñānīyamadhyāyaṃ vyākhyāsyāmaḥ iti hasmāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "द्विविधमौषधमूर्जस्करं रोगघ्नं च उभयमपि चोभयात्मकम् बाहुल्येन तु निर्देशः तत्रोर्जस्करं द्विविधं रसायनं वाजीकरणं च रोगघ्नमपि द्विविधम् रोगस्य प्रशमनमपुनर्भवकरं च पुनश्च द्विविधम् द्रव्यमद्रव्यम् च तत्र द्रव्यम् त्रिविधम् भौममौद्भिदं जङ्गममिति तेषु वक्ष्यमाणं हेमादि लवणान्तं प्रायेण भौमम् औद्भिदं पुनर्वनस्पतिवानस्पत्यवीरुदौषधिभेदेन चतुर्विधं भवति तत्र फलिनो वनस्पतिः पुष्पफलवान् वानस्पत्यः वल्लीगुल्मवीरुत् फलपाकान्ताश्चौषध्य इति जङ्गमोद्भवं मधुघृतादि जङ्गमद्रव्यमाहुः", text: "dvividhamauṣadhamūrjaskaraṃ rogaghnaṃ ca ubhayamapi cobhayātmakam bāhulyena tu nirdeśaḥ tatrorjaskaraṃ dvividhaṃ rasāyanaṃ vājīkaraṇaṃ ca rogaghnamapi dvividham rogasya praśamanamapunarbhavakaraṃ ca punaśca dvividham dravyamadravyam ca tatra dravyam trividham bhaumamaudbhidaṃ jaṅgamamiti teṣu vakṣyamāṇaṃ hemādi lavaṇāntaṃ prāyeṇa bhaumam audbhidaṃ punarvanaspativānaspatyavīrudauṣadhibhedena caturvidhaṃ bhavati tatra phalino vanaspatiḥ puṣpaphalavān vānaspatyaḥ vallīgulmavīrut phalapākāntāścauṣadhya iti jaṅgamodbhavaṃ madhughṛtādi jaṅgamadravyamāhuḥ" },
      { type: "verse", number: "3", sanskrit: "अद्रव्यं पुनरुपवासानिलातपच्छायामन्त्रसान्त्वदानभयोत्त्राससङ्क्षोभणहर्षणभर्त्सनहसनस्वप्नजागरण संवाहनादीनि पुनरपि च त्रिविधं दैवव्यपाश्रयं युक्तिव्यपाश्रयं सत्वावजयश्चेति तत्र दैवव्यपाश्रयं मन्त्रौषधिमणिमङ्गलबल्युपहारहोमनियमप्रायश्चित्तो पवासस्वस्त्ययनप्रणिधानगमनादि युक्तिव्यपाश्रयमाहारौषधयोजनादि सत्वावजयः पुनरहितान्मनोनिग्रहः पुनरपि च त्रिविधम् अपकर्षणं प्रकृतिविघातो निदानत्यागश्च", text: "adravyaṃ punarupavāsānilātapacchāyāmantrasāntvadānabhayottrāsasaṅkṣobhaṇaharṣaṇabhartsanahasanasvapnajāgaraṇa saṃvāhanādīni punarapi ca trividhaṃ daivavyapāśrayaṃ yuktivyapāśrayaṃ satvāvajayaśceti tatra daivavyapāśrayaṃ mantrauṣadhimaṇimaṅgalabalyupahārahomaniyamaprāyaścitto pavāsasvastyayanapraṇidhānagamanādi yuktivyapāśrayamāhārauṣadhayojanādi satvāvajayaḥ punarahitānmanonigrahaḥ punarapi ca trividham apakarṣaṇaṃ prakṛtivighāto nidānatyāgaśca" },
      { type: "verse", number: "4", sanskrit: "ते पुनरपकर्षणादयो द्विविधाः बाह्याभ्यन्तरभेदेन तत्र बाह्यमपकर्षणं ग्रन्थ्यर्बुदोपपक्ष्मक्रिमिशल्यादिषु शस्त्रहस्तयन्त्रादिभिः आभ्यन्तरं पुनर्वमनविरेचनादिभिः प्रकृतिविघातः संशमनम् तत् बाह्यमभ्यङ्गस्वेदप्रदेहपरिषेकोपमर्दनादि आभ्यन्तरं यदन्तरमनुप्रविश्याविक्षोभयद्दोषान् शमयति निदानत्यागो यथादोषं शीतोष्णशनव्यायामादीनां वर्जनं स्निग्धरुक्षाद्यनभ्यवहारश्च तत्र शस्त्रादिसाध्ये भेषजमनुक्रमते न तु भेषजसाध्ये शस्त्रादि", text: "te punarapakarṣaṇādayo dvividhāḥ bāhyābhyantarabhedena tatra bāhyamapakarṣaṇaṃ granthyarbudopapakṣmakrimiśalyādiṣu śastrahastayantrādibhiḥ ābhyantaraṃ punarvamanavirecanādibhiḥ prakṛtivighātaḥ saṃśamanam tat bāhyamabhyaṅgasvedapradehapariṣekopamardanādi ābhyantaraṃ yadantaramanupraviśyāvikṣobhayaddoṣān śamayati nidānatyāgo yathādoṣaṃ śītoṣṇaśanavyāyāmādīnāṃ varjanaṃ snigdharukṣādyanabhyavahāraśca tatra śastrādisādhye bheṣajamanukramate na tu bheṣajasādhye śastrādi" },
      { type: "verse", number: "5", sanskrit: "पुनरपि त्रिविधं हेतुविपरीतं व्याधिविपरीतमुभयार्थकारि च तत्र हेतुविपरीतं गुरुस्निग्धशीतादिजे व्याधौ लघुरूक्षोष्णादि तथेतरस्मिन्नितरत् व्याधिविपरीतम् द्वौ मूलोपक्रमौ लङ्घनबृंहणे पञ्च कर्माणि वमनादीनि सधूमधूपाञ्जनादीनि च तथा विम्लापनोपनाहनपाटनादीनि", text: "punarapi trividhaṃ hetuviparītaṃ vyādhiviparītamubhayārthakāri ca tatra hetuviparītaṃ gurusnigdhaśītādije vyādhau laghurūkṣoṣṇādi tathetarasminnitarat vyādhiviparītam dvau mūlopakramau laṅghanabṛṃhaṇe pañca karmāṇi vamanādīni sadhūmadhūpāñjanādīni ca tathā vimlāpanopanāhanapāṭanādīni" },
      { type: "verse", number: "6", sanskrit: "यच्च दोषशमनत्वे सत्यपि ज्वरे विशेषतो हितं मुस्ता पर्पटकं यवाग्वश्च प्रमेहे रजनी यवान्नं चेत्यादि रक्तपित्ते चोर्ध्वागे विरेचनमधोगे वमनम् उभयार्थकारि पुनर्दैवव्यपाश्रयमौषधम् तथा छर्द्यां छर्दनमतिसारे विरेचनं मदात्ययेमद्यपानं तुत्थदग्धे ऽग्निप्रतपनं पित्ते ऽन्तर्न्निगूढे विमार्गगे वा स्वेदः कट्वम्ललवणतीक्ष्णोष्णाभ्यवहारश्च बहिः प्रवर्त्तनाय स्वमार्गापादनाय च श्लेष्मणि चान्तर्निगूढे स्तब्धे बहिः शीतोपचारस्तत्पीडितस्योष्मणो ऽन्तःप्रवेशेन कफो विलयतामुपयाति एवंविधं ह्यविपरीतमेव सत् भेषजं हेतुव्याधिविपरीतमर्थं करोति", text: "yacca doṣaśamanatve satyapi jvare viśeṣato hitaṃ mustā parpaṭakaṃ yavāgvaśca pramehe rajanī yavānnaṃ cetyādi raktapitte cordhvāge virecanamadhoge vamanam ubhayārthakāri punardaivavyapāśrayamauṣadham tathā chardyāṃ chardanamatisāre virecanaṃ madātyayemadyapānaṃ tutthadagdhe 'gnipratapanaṃ pitte 'ntarnnigūḍhe vimārgage vā svedaḥ kaṭvamlalavaṇatīkṣṇoṣṇābhyavahāraśca bahiḥ pravarttanāya svamārgāpādanāya ca śleṣmaṇi cāntarnigūḍhe stabdhe bahiḥ śītopacārastatpīḍitasyoṣmaṇo 'ntaḥpraveśena kapho vilayatāmupayāti evaṃvidhaṃ hyaviparītameva sat bheṣajaṃ hetuvyādhiviparītamarthaṃ karoti" },
      { type: "verse", number: "7", sanskrit: "अनौषधं पुनर्द्विविधं बाधनमनुबाधनं च तत्र सद्यः प्राणहरं बाधनम् कालान्तरेणानुबाधनमिति परं चातो रसवीर्यादिभेदेन यथास्थूलमौषधैकदेश उपदिश्यते", text: "anauṣadhaṃ punardvividhaṃ bādhanamanubādhanaṃ ca tatra sadyaḥ prāṇaharaṃ bādhanam kālāntareṇānubādhanamiti paraṃ cāto rasavīryādibhedena yathāsthūlamauṣadhaikadeśa upadiśyate" },
      { type: "verse", number: "8", sanskrit: "सुवर्णं बृंहणं स्निग्धं मधुरं रसपाकयोः विषदोषहरं शीतं सकषायं रसायनम्", text: "suvarṇaṃ bṛṃhaṇaṃ snigdhaṃ madhuraṃ rasapākayoḥ viṣadoṣaharaṃ śītaṃ sakaṣāyaṃ rasāyanam" },
      { type: "verse", number: "9", sanskrit: "रूप्यं स्निग्धं कषायाम्ल विपाके मधुरं रसम् वयसः स्थापनं शीतं लेखनं वातपित्तजित्", text: "rūpyaṃ snigdhaṃ kaṣāyāmla vipāke madhuraṃ rasam vayasaḥ sthāpanaṃ śītaṃ lekhanaṃ vātapittajit" },
      { type: "verse", number: "10", sanskrit: "ताम्रं सतिक्तमधुरं कषायं लेखनं लघु कटुपाकरसं शीतं रोषणं कफपित्तजित्", text: "tāmraṃ satiktamadhuraṃ kaṣāyaṃ lekhanaṃ laghu kaṭupākarasaṃ śītaṃ roṣaṇaṃ kaphapittajit" },
      { type: "verse", number: "11", sanskrit: "कस्यं कषायानुरसं विशदं लेखन लघु दृष्टिप्रसादनं रूक्षं तिक्तं पित्तकफापहम्", text: "kasyaṃ kaṣāyānurasaṃ viśadaṃ lekhana laghu dṛṣṭiprasādanaṃ rūkṣaṃ tiktaṃ pittakaphāpaham" },
      { type: "verse", number: "12", sanskrit: "सतिक्तलवणं भेदि पाण्डुत्वकृमिवातनुत् लेखनं पित्तलं किञ्चित् त्रपु सीसं च तद्गुणम्", text: "satiktalavaṇaṃ bhedi pāṇḍutvakṛmivātanut lekhanaṃ pittalaṃ kiñcit trapu sīsaṃ ca tadguṇam" },
      { type: "verse", number: "13", sanskrit: "चक्षुष्यं कृष्णलोहं तु कषायं स्वादुतिक्तकम् लेखनं वातलं शीतं कृमिकुष्ठकफप्रणुत्", text: "cakṣuṣyaṃ kṛṣṇalohaṃ tu kaṣāyaṃ svādutiktakam lekhanaṃ vātalaṃ śītaṃ kṛmikuṣṭhakaphapraṇut" },
      { type: "verse", number: "14", sanskrit: "गात्रशैथिल्यपालित्यपाण्डुघ्नं शोषशोफजित् तद्वत्तीक्ष्णं विशेषेण तद्विकाषि सुदुर्जरम्", text: "gātraśaithilyapālityapāṇḍughnaṃ śoṣaśophajit tadvattīkṣṇaṃ viśeṣeṇa tadvikāṣi sudurjaram" },
      { type: "verse", number: "15", sanskrit: "पद्मरागमहानीलपुष्परागविदूरकाः मुक्ताविद्रुमवज्रेन्द्रवैडूर्यस्फटिकादिकम्", text: "padmarāgamahānīlapuṣparāgavidūrakāḥ muktāvidrumavajrendravaiḍūryasphaṭikādikam" },
      { type: "verse", number: "16", sanskrit: "मणिरत्नं सरं शीतं कषायं स्वादुलेखनम् चक्षुष्यं धारणात्तत्तु पाप्मालक्ष्मीविषापहम्", text: "maṇiratnaṃ saraṃ śītaṃ kaṣāyaṃ svādulekhanam cakṣuṣyaṃ dhāraṇāttattu pāpmālakṣmīviṣāpaham" },
      { type: "verse", number: "17", sanskrit: "धन्यमायुष्यमोजस्यं हर्षोत्साहकरं शिवम् सक्षार उष्णवीर्यश्च काचो दृष्टिकृदञ्जनात्", text: "dhanyamāyuṣyamojasyaṃ harṣotsāhakaraṃ śivam sakṣāra uṣṇavīryaśca kāco dṛṣṭikṛdañjanāt" },
      { type: "verse", number: "18", sanskrit: "शङ्खोदधिमलौ शीतौ कषायावतिलेखनौ तुत्थकं कटु सक्षारं कषायं विषदं लघु", text: "śaṅkhodadhimalau śītau kaṣāyāvatilekhanau tutthakaṃ kaṭu sakṣāraṃ kaṣāyaṃ viṣadaṃ laghu" },
      { type: "verse", number: "19", sanskrit: "लेखनं भेदि चक्षुष्यं कण्डूकृमिविषापहम् विशदो गैरिकः स्निग्धः कषायमधुरो हिमः", text: "lekhanaṃ bhedi cakṣuṣyaṃ kaṇḍūkṛmiviṣāpaham viśado gairikaḥ snigdhaḥ kaṣāyamadhuro himaḥ" },
      { type: "verse", number: "20", sanskrit: "कफघ्नी तिक्तकटुका मनोह्वा लेखनी सरा स्निग्धं कषायकटुकं हरितालं विषप्रणुत्", text: "kaphaghnī tiktakaṭukā manohvā lekhanī sarā snigdhaṃ kaṣāyakaṭukaṃ haritālaṃ viṣapraṇut" },
      { type: "verse", number: "21", sanskrit: "कषायं मधुरं शीतं लेखनं स्निग्धमञ्जनम् रक्तपित्तविषच्छर्दिहिध्माघ्नं दृक्प्रसादनम्", text: "kaṣāyaṃ madhuraṃ śītaṃ lekhanaṃ snigdhamañjanam raktapittaviṣacchardihidhmāghnaṃ dṛkprasādanam" },
      { type: "verse", number: "22", sanskrit: "स्रोतो ऽञ्जनं वरं तत्र ततः सौवीरकाञ्जनम् कफघ्नं तित्तकटुकं छेदि सोष्णं रसाञ्जनम्", text: "sroto 'ñjanaṃ varaṃ tatra tataḥ sauvīrakāñjanam kaphaghnaṃ tittakaṭukaṃ chedi soṣṇaṃ rasāñjanam" },
      { type: "verse", number: "23", sanskrit: "स्वादु हिध्माप्रशमनं कासमेहक्षयापहम् कफघ्नमुष्णं कटुकं शिलाजतु रसायनम्", text: "svādu hidhmāpraśamanaṃ kāsamehakṣayāpaham kaphaghnamuṣṇaṃ kaṭukaṃ śilājatu rasāyanam" },
      { type: "verse", number: "24", sanskrit: "तिक्तं च छेदनं योगवाहित्वात्सर्वरोगजित् विशेषात् कृछ्रमेहार्शःपाण्डुशोफकफापहम्", text: "tiktaṃ ca chedanaṃ yogavāhitvātsarvarogajit viśeṣāt kṛchramehārśaḥpāṇḍuśophakaphāpaham" },
      { type: "verse", number: "25", sanskrit: "कषाया मधुरा रूक्षा कासघ्नी वंशरोचना तुगाक्षीरी क्षयश्वासकासघ्नी मधुरा हिमा", text: "kaṣāyā madhurā rūkṣā kāsaghnī vaṃśarocanā tugākṣīrī kṣayaśvāsakāsaghnī madhurā himā" },
      { type: "verse", number: "26", sanskrit: "विष्यन्दि लवणं सर्वं सूक्ष्मं सृष्टमलं विदुः वातघ्नं पाकि तीक्ष्णोष्णं रोचनं कफपित्तकृत्", text: "viṣyandi lavaṇaṃ sarvaṃ sūkṣmaṃ sṛṣṭamalaṃ viduḥ vātaghnaṃ pāki tīkṣṇoṣṇaṃ rocanaṃ kaphapittakṛt" },
      { type: "verse", number: "27", sanskrit: "सैधन्वं तत्र सस्वादु वृष्यं हृद्यं त्रिदोषनुत् लघ्वनुष्णं दृशः पथ्यमविदाह्यग्निदीपनम्", text: "saidhanvaṃ tatra sasvādu vṛṣyaṃ hṛdyaṃ tridoṣanut laghvanuṣṇaṃ dṛśaḥ pathyamavidāhyagnidīpanam" },
      { type: "verse", number: "28", sanskrit: "लघु सौवर्चलं हृद्यं सुगन्ध्युद्गारशोधनम् कटुपाकं विबन्धघ्नं दीपनीयं रुचिप्रदम्", text: "laghu sauvarcalaṃ hṛdyaṃ sugandhyudgāraśodhanam kaṭupākaṃ vibandhaghnaṃ dīpanīyaṃ rucipradam" },
      { type: "verse", number: "29", sanskrit: "ऊर्ध्वाधःकफवातानुलोमनं दीपनं विडम् विबन्धानाहविष्टम्भशूलगौरवनाशनम्", text: "ūrdhvādhaḥkaphavātānulomanaṃ dīpanaṃ viḍam vibandhānāhaviṣṭambhaśūlagauravanāśanam" },
      { type: "verse", number: "30", sanskrit: "विपाके स्वादु सामुद्रं गुरु श्लेष्मविवर्धनम् सतिक्तकटुकक्षारं तीक्ष्णमुत्क्लेदि चौद्भिदम्", text: "vipāke svādu sāmudraṃ guru śleṣmavivardhanam satiktakaṭukakṣāraṃ tīkṣṇamutkledi caudbhidam" },
      { type: "verse", number: "31", sanskrit: "कृष्णे सौवर्चलगुणा लवणे गन्धवर्जिताः रोमकं लघु पांसूत्थं सक्षारं श्लेष्मलं गुरु", text: "kṛṣṇe sauvarcalaguṇā lavaṇe gandhavarjitāḥ romakaṃ laghu pāṃsūtthaṃ sakṣāraṃ śleṣmalaṃ guru" },
      { type: "verse", number: "32", sanskrit: "लवणानां प्रयोगे तु सैन्धवादीन् प्रयोजयेत् गुल्महृत् ग्रहणीपाण्डुप्लीहानाहगलामयान्", text: "lavaṇānāṃ prayoge tu saindhavādīn prayojayet gulmahṛt grahaṇīpāṇḍuplīhānāhagalāmayān" },
      { type: "verse", number: "33", sanskrit: "श्वासार्शःकफवातांश्च शमयेद्यवशूकजः स्वर्जिका तद्गुणान्न्यूना क्षारेण तु ततो ऽधिका", text: "śvāsārśaḥkaphavātāṃśca śamayedyavaśūkajaḥ svarjikā tadguṇānnyūnā kṣāreṇa tu tato 'dhikā" },
      { type: "verse", number: "34", sanskrit: "क्षारः सर्वश्च परमं तीक्ष्णोष्णः कृमिजिल्लघुः पित्तासृग्दूषणः पाकी छेद्यहृद्यो विदारणः अपथ्यः कटुलावण्याच्शुक्रौजःकेशचक्षुषाम्", text: "kṣāraḥ sarvaśca paramaṃ tīkṣṇoṣṇaḥ kṛmijillaghuḥ pittāsṛgdūṣaṇaḥ pākī chedyahṛdyo vidāraṇaḥ apathyaḥ kaṭulāvaṇyācśukraujaḥkeśacakṣuṣām" },
      { type: "verse", number: "35", sanskrit: "कषाया मधुरा पाके रूक्षा विलवणा लघुः दीपनी पाचनी मेध्या वयसः स्थापनी परम्", text: "kaṣāyā madhurā pāke rūkṣā vilavaṇā laghuḥ dīpanī pācanī medhyā vayasaḥ sthāpanī param" },
      { type: "verse", number: "36", sanskrit: "उष्णवीर्या सरायुष्या बुद्धीन्द्रियबलप्रदा कुष्ठवैवर्ण्यवैस्वर्यपुराणविषमज्वरान्", text: "uṣṇavīryā sarāyuṣyā buddhīndriyabalapradā kuṣṭhavaivarṇyavaisvaryapurāṇaviṣamajvarān" },
      { type: "verse", number: "37", sanskrit: "शिरो ऽक्षिपाण्डुहृद्रोगकामलाग्रहणीगदान् सशोषशोफातीसारमेहमोहवमिक्रिमीन्", text: "śiro 'kṣipāṇḍuhṛdrogakāmalāgrahaṇīgadān saśoṣaśophātīsāramehamohavamikrimīn" },
      { type: "verse", number: "38", sanskrit: "श्वासकासप्रसेकार्शःप्लीहानाहगरोदरम् विबन्धं स्रोतसां गुल्ममूरुस्तम्भमरोचकम्", text: "śvāsakāsaprasekārśaḥplīhānāhagarodaram vibandhaṃ srotasāṃ gulmamūrustambhamarocakam" },
      { type: "verse", number: "39", sanskrit: "हरीतकी जयेद्व्याधींस्ताअंस्तांश्चकफवातजान् तद्वदामलकं शीतं माधुर्यात् पित्तजित् परम्", text: "harītakī jayedvyādhīṃstāaṃstāṃścakaphavātajān tadvadāmalakaṃ śītaṃ mādhuryāt pittajit param" },
      { type: "verse", number: "40", sanskrit: "कफं कटुविपाकित्वादम्लत्वान्मारुतं जयेत् परं च कण्ठ्यं चक्षुष्यं हृद्यं दाहज्वरापहम्", text: "kaphaṃ kaṭuvipākitvādamlatvānmārutaṃ jayet paraṃ ca kaṇṭhyaṃ cakṣuṣyaṃ hṛdyaṃ dāhajvarāpaham" },
      { type: "verse", number: "41", sanskrit: "अक्षं तु तद्गुणान्न्यूनं कषायमधुरं हिमम् कासश्वासगलश्लेष्मपित्तशुक्रहरं लघु", text: "akṣaṃ tu tadguṇānnyūnaṃ kaṣāyamadhuraṃ himam kāsaśvāsagalaśleṣmapittaśukraharaṃ laghu" },
      { type: "verse", number: "42", sanskrit: "परं केश्यस्तु तन्मज्जा शुक्रघ्नं च ततो ऽञ्जनम् इय रसायनवरा त्रिफलाक्ष्यामयापहा रोपणी त्वग्गदक्लेदमेदोमेहकफास्रजित्", text: "paraṃ keśyastu tanmajjā śukraghnaṃ ca tato 'ñjanam iya rasāyanavarā triphalākṣyāmayāpahā ropaṇī tvaggadakledamedomehakaphāsrajit" },
      { type: "verse", number: "43", sanskrit: "सकेसरं चतुर्जातं त्वक्पत्रैलं त्रिजातकम् पित्तप्रकोपि तीष्णोष्णं रूक्षं रोचनदीपनम्", text: "sakesaraṃ caturjātaṃ tvakpatrailaṃ trijātakam pittaprakopi tīṣṇoṣṇaṃ rūkṣaṃ rocanadīpanam" },
      { type: "verse", number: "44", sanskrit: "रसे पाके च कटुकं कफघ्नं मरिचं लघु श्लेष्मला स्वादु शीतार्द्रा गुर्वीं स्निग्धा च पिप्पली", text: "rase pāke ca kaṭukaṃ kaphaghnaṃ maricaṃ laghu śleṣmalā svādu śītārdrā gurvīṃ snigdhā ca pippalī" },
      { type: "verse", number: "45", sanskrit: "सा शुष्का विपरीतातःस्निग्धा वृष्या रसे कटुः स्वादुपाकानिलश्लेष्मश्वासकासापहा सरा", text: "sā śuṣkā viparītātaḥsnigdhā vṛṣyā rase kaṭuḥ svādupākānilaśleṣmaśvāsakāsāpahā sarā" },
      { type: "verse", number: "46", sanskrit: "न तामत्युपयुञ्जीत रसायनविधिं विना नागरं दीपनं वृष्यं ग्राहि हृद्यं विबन्धनुत्", text: "na tāmatyupayuñjīta rasāyanavidhiṃ vinā nāgaraṃ dīpanaṃ vṛṣyaṃ grāhi hṛdyaṃ vibandhanut" },
      { type: "verse", number: "47", sanskrit: "रुच्य लघु स्वादुपाकं स्निग्धोष्णं कफवातजित् तद्वदार्द्रकमेतच्च त्रयं त्रिकटुकं जयेत्", text: "rucya laghu svādupākaṃ snigdhoṣṇaṃ kaphavātajit tadvadārdrakametacca trayaṃ trikaṭukaṃ jayet" },
      { type: "verse", number: "48", sanskrit: "स्थौल्याग्निसदनश्वासकासश्लीपदपीनसान् चविका पिप्पलीमूलं मरिचाल्पान्तरं गुणैः", text: "sthaulyāgnisadanaśvāsakāsaślīpadapīnasān cavikā pippalīmūlaṃ maricālpāntaraṃ guṇaiḥ" },
      { type: "verse", number: "49", sanskrit: "चित्रको ऽग्निसमः पाके शोफार्शःकृमिकुष्ठहा पञ्चकोलकमेतच्च मरिचेन विना स्मृतम् गुल्मप्लीहोदरानाहशूलघ्नं दीपनं परम्", text: "citrako 'gnisamaḥ pāke śophārśaḥkṛmikuṣṭhahā pañcakolakametacca maricena vinā smṛtam gulmaplīhodarānāhaśūlaghnaṃ dīpanaṃ param" },
      { type: "verse", number: "50", sanskrit: "बिल्वकाश्मर्यतर्कारीपाटलाटुण्टुकैर्महत् जयेत् कषायं तिक्तोष्णं पञ्चमूलं कफानिलौ", text: "bilvakāśmaryatarkārīpāṭalāṭuṇṭukairmahat jayet kaṣāyaṃ tiktoṣṇaṃ pañcamūlaṃ kaphānilau" },
      { type: "verse", number: "51", sanskrit: "ह्रस्वं बृहत्यंशुमतीद्वयगोक्षुरकैः स्मृतम् स्वादुपाकरसं नातिशीतोष्णं सर्वदोषजित्", text: "hrasvaṃ bṛhatyaṃśumatīdvayagokṣurakaiḥ smṛtam svādupākarasaṃ nātiśītoṣṇaṃ sarvadoṣajit" },
      { type: "verse", number: "52", sanskrit: "बलापुनर्नवैरण्डशूर्पपर्णीद्वयेन च मध्यमं कफवातघ्नं नातिपित्तकरं लघु", text: "balāpunarnavairaṇḍaśūrpaparṇīdvayena ca madhyamaṃ kaphavātaghnaṃ nātipittakaraṃ laghu" },
      { type: "verse", number: "53", sanskrit: "अभीरुवीराजीवन्तीजीवकर्षभकैः स्मृतम् जीवनाख्यं तु चक्षुष्यं वृष्यं पित्तानिलापहम्", text: "abhīruvīrājīvantījīvakarṣabhakaiḥ smṛtam jīvanākhyaṃ tu cakṣuṣyaṃ vṛṣyaṃ pittānilāpaham" },
      { type: "verse", number: "54", sanskrit: "तृणाख्यं शरदर्भेक्षुशालिकाशैस्तु पित्तजित् अजशृङ्गी हरिद्रा च विदारीशारिवामृताः", text: "tṛṇākhyaṃ śaradarbhekṣuśālikāśaistu pittajit ajaśṛṅgī haridrā ca vidārīśārivāmṛtāḥ" },
      { type: "verse", number: "55", sanskrit: "बल्याख्यं कण्टकाख्यं तु श्वदंष्ट्राभीरुसैर्यकैः सहिस्त्राकरमर्दीकैस्सर्वदोषहरे च ते", text: "balyākhyaṃ kaṇṭakākhyaṃ tu śvadaṃṣṭrābhīrusairyakaiḥ sahistrākaramardīkaissarvadoṣahare ca te" },
      { type: "verse", number: "56", sanskrit: "कारवीकुञ्चिवाजाजीकवरीधान्यतुम्बरु अन्नगन्धहरं रुच्यं दीपनं कफवातजित्", text: "kāravīkuñcivājājīkavarīdhānyatumbaru annagandhaharaṃ rucyaṃ dīpanaṃ kaphavātajit" },
      { type: "verse", number: "57", sanskrit: "वाष्पिका कटुतिक्तोष्णा कृमिश्लेष्महरा परम् शूलाटोपहरा रुच्या दीप्यकः कोष्ठशूलजित्", text: "vāṣpikā kaṭutiktoṣṇā kṛmiśleṣmaharā param śūlāṭopaharā rucyā dīpyakaḥ koṣṭhaśūlajit" },
      { type: "verse", number: "58", sanskrit: "अहृद्याः सर्षपाः स्निग्धा बाष्पिकावच्च कीर्त्तिताः हिङ्गु वातकफानाहशूलघ्नं पित्तकोपनम्", text: "ahṛdyāḥ sarṣapāḥ snigdhā bāṣpikāvacca kīrttitāḥ hiṅgu vātakaphānāhaśūlaghnaṃ pittakopanam" },
      { type: "verse", number: "59", sanskrit: "कटुपाकरसं रुच्यं दीपनं पाचनं लघु पित्तास्रकोपि तच्चैव श्रेष्ठं बोष्काणदेशजम्", text: "kaṭupākarasaṃ rucyaṃ dīpanaṃ pācanaṃ laghu pittāsrakopi taccaiva śreṣṭhaṃ boṣkāṇadeśajam" },
      { type: "verse", number: "60", sanskrit: "ततो न्यूनगुणं त्वन्यद्द्रव्यव्यञ्जनधूपनम् शताह्वाकुष्ठतगरसुरदारुहरेणवः", text: "tato nyūnaguṇaṃ tvanyaddravyavyañjanadhūpanam śatāhvākuṣṭhatagarasuradāruhareṇavaḥ" },
      { type: "verse", number: "61", sanskrit: "एलैलवालुसरलत्वग्व्याघ्रनखचोरकाः लघूष्णाः कटुकाः पाके कफवातनिबर्हणाः", text: "elailavālusaralatvagvyāghranakhacorakāḥ laghūṣṇāḥ kaṭukāḥ pāke kaphavātanibarhaṇāḥ" },
      { type: "verse", number: "62", sanskrit: "सैर्यकस्तिक्तमधुरः स्निग्धोष्णः कफवातजित् बस्तिमूत्रविबन्धघ्नो वृष्यो गोक्षुरको हिमः", text: "sairyakastiktamadhuraḥ snigdhoṣṇaḥ kaphavātajit bastimūtravibandhaghno vṛṣyo gokṣurako himaḥ" },
      { type: "verse", number: "63", sanskrit: "पाचनं कफपित्तघ्नं तिक्तं शीतं विषाद्वयम् कफघ्नं तिक्तकटुकं मुस्तं संग्राहि पाचनम्", text: "pācanaṃ kaphapittaghnaṃ tiktaṃ śītaṃ viṣādvayam kaphaghnaṃ tiktakaṭukaṃ mustaṃ saṃgrāhi pācanam" },
      { type: "verse", number: "64", sanskrit: "तिक्तामृता त्रिदोषघ्नी ग्राहिण्युष्णा रसायनी दीपनी ज्वरतृड्दाहकामलावातरक्तनुत्", text: "tiktāmṛtā tridoṣaghnī grāhiṇyuṣṇā rasāyanī dīpanī jvaratṛḍdāhakāmalāvātaraktanut" },
      { type: "verse", number: "65", sanskrit: "तिक्तशीतौ ज्वरहरौ लघू भूनिम्बपर्पटौ निम्बस्तिक्तो हिमः कुष्ठकृमिपित्तकफापहः", text: "tiktaśītau jvaraharau laghū bhūnimbaparpaṭau nimbastikto himaḥ kuṣṭhakṛmipittakaphāpahaḥ" },
      { type: "verse", number: "66", sanskrit: "महानिम्बः परं ग्राही कषायो रूक्षशीतलः गुग्गुलुः पिच्छिलः स्पर्शे विशदो ऽभ्यवहारतः", text: "mahānimbaḥ paraṃ grāhī kaṣāyo rūkṣaśītalaḥ gugguluḥ picchilaḥ sparśe viśado 'bhyavahārataḥ" },
      { type: "verse", number: "67", sanskrit: "सस्वादु सकटुस्तिक्तः सकषायो रसायनम् व्रण्यः स्वर्यः कटुः पाके रुक्षः सूक्ष्मो ऽग्निदीपनः", text: "sasvādu sakaṭustiktaḥ sakaṣāyo rasāyanam vraṇyaḥ svaryaḥ kaṭuḥ pāke rukṣaḥ sūkṣmo 'gnidīpanaḥ" },
      { type: "verse", number: "68", sanskrit: "क्लेदमेदोनिलश्लेष्मगण्डमेहापचीक्रिमीन् पिटकाग्रन्थिशोफांश्च हन्त्युष्णः स्रंसनो लघुः", text: "kledamedonilaśleṣmagaṇḍamehāpacīkrimīn piṭakāgranthiśophāṃśca hantyuṣṇaḥ sraṃsano laghuḥ" },
      { type: "verse", number: "69", sanskrit: "शङ्खपुष्पी सरा तिक्ता मेध्या कृमिविषापहा कटुतिक्तोष्णमगरु स्निग्धं वातकफापहम्", text: "śaṅkhapuṣpī sarā tiktā medhyā kṛmiviṣāpahā kaṭutiktoṣṇamagaru snigdhaṃ vātakaphāpaham" },
      { type: "verse", number: "70", sanskrit: "पित्तास्रविषतृड्दाहक्लमघ्नं गुरु रूक्षणम् सर्वं सतिक्तमधुरं चन्दनं शिशिरं परम्", text: "pittāsraviṣatṛḍdāhaklamaghnaṃ guru rūkṣaṇam sarvaṃ satiktamadhuraṃ candanaṃ śiśiraṃ param" },
      { type: "verse", number: "71", sanskrit: "लघु रक्तं तथोशीरं वालकं पाचनं च तत् ज्वरातिसारवमथुरक्तपित्तक्षतापहम्", text: "laghu raktaṃ tathośīraṃ vālakaṃ pācanaṃ ca tat jvarātisāravamathuraktapittakṣatāpaham" },
      { type: "verse", number: "72", sanskrit: "मधुकं रक्तपित्तघ्नं व्रणशोधनरोपणम् गुरु स्वादु हिमं वृष्यं चक्षुष्य्ं स्वरवर्णकृत्", text: "madhukaṃ raktapittaghnaṃ vraṇaśodhanaropaṇam guru svādu himaṃ vṛṣyaṃ cakṣuṣyṃ svaravarṇakṛt" },
      { type: "verse", number: "73", sanskrit: "कटुतिक्ते निशे कुष्ठमेहपित्तकफापहे प्रलेपाज्जयतः कण्डूं शोफं दुष्टव्रणं विषम्", text: "kaṭutikte niśe kuṣṭhamehapittakaphāpahe pralepājjayataḥ kaṇḍūṃ śophaṃ duṣṭavraṇaṃ viṣam" },
      { type: "verse", number: "74", sanskrit: "प्रपौण्डरीकं चक्षुष्यं शिशिरं व्रणरोपणम् कषायतिक्तमधुरं रक्तपित्तप्रसादनम्", text: "prapauṇḍarīkaṃ cakṣuṣyaṃ śiśiraṃ vraṇaropaṇam kaṣāyatiktamadhuraṃ raktapittaprasādanam" },
      { type: "verse", number: "75", sanskrit: "बलात्रयं स्वादु वृष्यं स्निग्धं शीतं बलप्रदम् तत्र नागबला बल्या क्षतक्षीणहिता गुरुः", text: "balātrayaṃ svādu vṛṣyaṃ snigdhaṃ śītaṃ balapradam tatra nāgabalā balyā kṣatakṣīṇahitā guruḥ" },
      { type: "verse", number: "76", sanskrit: "ताम्बुलं कटु सक्षारं रुच्यमुष्णं कफप्रणुत् भेदि सम्मोहकृत् पूगं कषायं स्वादु रोचनम्", text: "tāmbulaṃ kaṭu sakṣāraṃ rucyamuṣṇaṃ kaphapraṇut bhedi sammohakṛt pūgaṃ kaṣāyaṃ svādu rocanam" },
      { type: "verse", number: "77", sanskrit: "जातिपत्री कटुफलं कङ्कोलकलवङ्गकम् लघु तृष्णापहं हृद्यं वक्त्रदौर्गन्ध्यनाशनम्", text: "jātipatrī kaṭuphalaṃ kaṅkolakalavaṅgakam laghu tṛṣṇāpahaṃ hṛdyaṃ vaktradaurgandhyanāśanam" },
      { type: "verse", number: "78", sanskrit: "सस्वादुतिक्तस्तृष्णाघ्नः कर्पूरश्च्छेदनो हिमः लताकस्तूरिका तद्वन्मुखशोषहरा परम्", text: "sasvādutiktastṛṣṇāghnaḥ karpūraścchedano himaḥ latākastūrikā tadvanmukhaśoṣaharā param" },
      { type: "verse", number: "79", sanskrit: "कषायमधुरं शीतं पद्मं पित्तकफास्रजित् तद्वत् बकुलपुन्नागकुमुदोत्पलपाटलम्", text: "kaṣāyamadhuraṃ śītaṃ padmaṃ pittakaphāsrajit tadvat bakulapunnāgakumudotpalapāṭalam" },
      { type: "verse", number: "80", sanskrit: "सचम्पकं ततो न्यूनं गुणैः कोरण्डकिंशुकम् मालतीमल्लिकापुष्पं तिक्तं जयति मारुतम्", text: "sacampakaṃ tato nyūnaṃ guṇaiḥ koraṇḍakiṃśukam mālatīmallikāpuṣpaṃ tiktaṃ jayati mārutam" },
      { type: "verse", number: "81", sanskrit: "विषपित्तकफान्नगं सिन्दुवारं च तद्गुणम् कफघ्नं कैतकं तिक्तं शैरीषं विषहारि च", text: "viṣapittakaphānnagaṃ sinduvāraṃ ca tadguṇam kaphaghnaṃ kaitakaṃ tiktaṃ śairīṣaṃ viṣahāri ca" },
      { type: "verse", number: "82", sanskrit: "वातलं पुष्पमागस्त्यं कषायं कफपित्तजित् चातुर्थिकज्वरहरं नावनेनोपयोजितम्", text: "vātalaṃ puṣpamāgastyaṃ kaṣāyaṃ kaphapittajit cāturthikajvaraharaṃ nāvanenopayojitam" },
      { type: "verse", number: "83", sanskrit: "बन्धूकं श्लेष्मलं ग्राहि तद्वदेव च यूथिका कफघ्नमुष्णवीर्यं च कुङ्कुमं व्रणशोधनम् अवल्वेडकजं बीजं कटिवातकफप्रणुत्", text: "bandhūkaṃ śleṣmalaṃ grāhi tadvadeva ca yūthikā kaphaghnamuṣṇavīryaṃ ca kuṅkumaṃ vraṇaśodhanam avalveḍakajaṃ bījaṃ kaṭivātakaphapraṇut" },
      { type: "verse", number: "84", sanskrit: "आस्या वर्णश्लेष्ममेदःसौकुमार्यकृदन्यथा अतो ऽध्वाग्निबलांयूषि कुर्याच्चङ्क्रमणं सुखम्", text: "āsyā varṇaśleṣmamedaḥsaukumāryakṛdanyathā ato 'dhvāgnibalāṃyūṣi kuryāccaṅkramaṇaṃ sukham" },
      { type: "verse", number: "85", sanskrit: "मारुतस्यानुलोम्यं च खुडस्तम्भश्रमापहम् अन्वर्थसंज्ञं पादत्रं बलदृक्शुक्रवर्द्धनम्", text: "mārutasyānulomyaṃ ca khuḍastambhaśramāpaham anvarthasaṃjñaṃ pādatraṃ baladṛkśukravarddhanam" },
      { type: "verse", number: "86", sanskrit: "वर्ण्यं नेत्रहितं छत्रं वातवर्षातपापहम् प्रवातो रौक्ष्यवैवर्ण्यस्तम्भकृद्दाहतृड्भ्रमान्", text: "varṇyaṃ netrahitaṃ chatraṃ vātavarṣātapāpaham pravāto raukṣyavaivarṇyastambhakṛddāhatṛḍbhramān" },
      { type: "verse", number: "87", sanskrit: "श्रमाग्निमूर्च्छाश्च जयेदप्रवातस्त्वतो ऽन्यथा प्राग्वायुरुष्णो ऽभिष्यन्दी त्वग्दोषार्शोविषक्रिमीन्", text: "śramāgnimūrcchāśca jayedapravātastvato 'nyathā prāgvāyuruṣṇo 'bhiṣyandī tvagdoṣārśoviṣakrimīn" },
      { type: "verse", number: "88", sanskrit: "सन्निपातज्वरं श्वासमामं वायुं च कोपयेत् पश्चिमः शिशिरो हन्ति मूर्च्छां दाहं तृषं विषम्", text: "sannipātajvaraṃ śvāsamāmaṃ vāyuṃ ca kopayet paścimaḥ śiśiro hanti mūrcchāṃ dāhaṃ tṛṣaṃ viṣam" },
      { type: "verse", number: "89", sanskrit: "दक्षिणो मारुतः श्रेष्ठो नेत्र्यो ऽङ्गबलवर्द्धनः रक्तपित्तप्रशमनो न च वातप्रकोपनः", text: "dakṣiṇo mārutaḥ śreṣṭho netryo 'ṅgabalavarddhanaḥ raktapittapraśamano na ca vātaprakopanaḥ" },
      { type: "verse", number: "90", sanskrit: "उत्तरो मारुतः स्निग्धो मृदुर्मधुर एव च कषायानुरसः शीतो दोषाणामप्रकोपनः", text: "uttaro mārutaḥ snigdho mṛdurmadhura eva ca kaṣāyānurasaḥ śīto doṣāṇāmaprakopanaḥ" },
      { type: "verse", number: "91", sanskrit: "आतपो भ्रमतृट्स्वेददाहमूर्च्छाविवर्णताः कुर्यात् पित्तास्रवह्नींश्च छाया चैतानपोहति तमः कषायकटुकं ज्योत्स्ना मधुरशीतला", text: "ātapo bhramatṛṭsvedadāhamūrcchāvivarṇatāḥ kuryāt pittāsravahnīṃśca chāyā caitānapohati tamaḥ kaṣāyakaṭukaṃ jyotsnā madhuraśītalā" },
      { type: "verse", number: "92", sanskrit: "भवति चात्र रसादिभेदैरिति भेषजाना दिङ्मात्रमुक्तं न यतो ऽस्ति किञ्चित् अनौषधं द्रव्यमिहावबोधो रूपस्य तेषां वनगोचरेभ्यः", text: "bhavati cātra rasādibhedairiti bheṣajānā diṅmātramuktaṃ na yato 'sti kiñcit anauṣadhaṃ dravyamihāvabodho rūpasya teṣāṃ vanagocarebhyaḥ" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 13,
    lang: "sa",
    content: [
      { type: "heading", heading: "Дхумапана видхи — ингаляционная терапия" },
      { type: "text", text: "Глава 13 Сутрастханы Астанга-санграхи посвящена теме «ингаляционная терапия». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो ऽग्र्यसङ्ग्रहणीयमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto 'gryasaṅgrahaṇīyamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "श्रेष्ठमुदकमाश्वासनस्तम्भनक्लेदनानाम् स्नानं सुरा च श्रमहराणाम् क्षीरं जीवनीयानाम् मांसं बृंहणीयानाम् रसः प्रीणनानाम् लवणमन्नद्रव्यरुचिकराणाम् तिन्दुकमन्नद्रव्यारुचिकराणाम् अम्लं हृद्यानाम् कुक्कुटो बल्यानाम् तैलं वातश्लेष्मप्रशमनानाम् सर्पिर्वातपित्तप्रशमनानाम् मधु श्लेष्मपित्तप्रशमनानाम् स्वेदो मार्दवकराणाम् व्यायामः स्थैर्यकराणाम् क्षारः पुंस्त्वोपघातिनाम् आमं कपित्थमकण्ठ्यानाम् आविकं सर्पिरहृद्यानाम् महिषीक्षीरं स्वप्नजननानाम् मन्दकं दध्यभिष्यन्दकराणाम् इक्षुर्मूत्रजननानाम् यवाः पुरीषजननानाम् जाम्बवं वातजननानाम् कुलत्थो ऽम्लपित्तजननानाम् माषाः शष्कुल्यो ऽविक्षीरं च पित्तश्लेष्मजननानाम् दुरालभा पित्तश्लेष्मोपशोषणानाम् उपवासो ज्वरहराणां वृषो रक्तपित्तप्रशमनानाम् कण्टकारिका कासघ्नानाम् लाक्षा सद्यःक्षतघ्नानाम् नागबलाभ्यासः क्षतक्षयघ्नानाम् पुष्करमूलं हिध्माश्वासकासपार्श्वशूलारुचिहराणाम् अजापयः शोषघ्नस्तन्यकररक्तसङ्ग्रहणप्रशमनानाम् मृद्भृष्टलोष्टप्रसादः छर्दितृष्णातियोगप्रशमनानाम् अरुष्करश्चित्रकमूलं च शुष्कार्शःप्रशमनानाम् कुटजो रक्तर्शःप्रशमनानाम् लाजाश्छर्दिघ्नानाम् यावशूकः स्रंसनीयपाचनीयार्शोघ्नानाम् तक्राभ्यासो ऽर्शःश्वयथुग्रहणीदोषघृतव्यापत्प्रशमनानाम् क्रव्यान्मांसाभ्यासो ऽर्शःशोषग्रहणीदोषघ्नानाम् मुस्तं सङ्ग्रहणीयदीपनीयपाचनीयानाम् अतिविषा सङ्ग्रहणीयपाचनीयसर्वदोषहराणाम् बिल्वं सङ्ग्रहणीयदीपनीयवातकफप्रशमनानाम् उदीच्यं निर्वापणदीपनीयछर्द्यतीसारहराणाम् कट्वङ्गं सङ्ग्रहणीयदीपनीयानाम् कुटजत्वक् श्लेष्मपित्तरक्तसङ्ग्रहणीयोपशोषणीयानाम् उत्पलकुमुदकिञ्जल्को ऽनन्ता च सङ्ग्रहणीयरक्तपित्तप्रशमनानाम् काश्मर्यफलं रक्तसङ्ग्रहणीयरक्तपित्तप्रशमनानाम् गन्धप्रियङ्गुः शोणितपित्तातियोगप्रशमनानाम् पृश्निपर्णी रक्तसङ्ग्रहणीयदीपनीयपाचनीयवातहरवृष्याणाम् सालपर्णी वृष्यसर्वदोषहराणाम् बला सङ्ग्रहणीयबल्यवातहराणाम् पिप्पलीमूलं दीपनीयपाचनीयानाहहराणाम् चित्रकमूलं दीपनीयपाचनीयगुदशोफशूलहराणाम् गोक्षुरको मूत्रकृच्छ्रानिलहराणाम् हरिद्रा प्रमेहहराणाम् रक्तावसेको विद्रधिविसर्पपिटकागण्डमालापहराणाम् एरण्डतैलाभ्यासो वर्ध्मगुल्मानिलशूलहराणाम् लशुनो गुल्मानिलहराणाम् हिङ्गुनिर्यासःश्छेदनीयपाचनीयानुलोमिकवातकफप्रशमनानाम् अम्लवेतसो भेदनीयदीपनीयानुलोमिकवातकफप्रशमनानाम् उष्ट्रीक्षीरमुदरश्वयथुघ्नानाम् अयोरजः पाण्डुरोगघ्नानाम् खदिरः कुष्ठघ्नानाम् विडङ्गः कृमिघ्नानाम् रास्ना वातहराणाम् एरण्डमूलं वृष्यवातहराणाम् गुग्गुलुर्मेदोनिलहराणाम् अमृता सङ्ग्रहणीयदीपनीयवातश्लेष्मशोणितविबन्धप्रशमनानाम् मदनफलं वमनास्थापनानुवासनोपयोगिनाम् त्रिवृत्सुखविरेचनानाम् चतुरङ्गुलो मृदुविरेचनानाम् स्नुक्पयस्तीक्ष्णविरेचनानाम् प्रत्यक्पुष्पी शिरोविरेचनानाम् त्रिफलातिमिरघ्नानाम् गुग्गुलुर्व्रण्यानाम् शिरीषो विषघ्नानाम् आमलकं वयस्थापनानाम् हरीतकी पथ्यानाम् क्षीरघृताभ्यासो रसायनानाम् समघृतसक्तुप्राशाभ्यासो वृष्योदावर्तहराणाम् सङ्कल्पो नक्ररेतश्च वृष्याणाम्", text: "śreṣṭhamudakamāśvāsanastambhanakledanānām snānaṃ surā ca śramaharāṇām kṣīraṃ jīvanīyānām māṃsaṃ bṛṃhaṇīyānām rasaḥ prīṇanānām lavaṇamannadravyarucikarāṇām tindukamannadravyārucikarāṇām amlaṃ hṛdyānām kukkuṭo balyānām tailaṃ vātaśleṣmapraśamanānām sarpirvātapittapraśamanānām madhu śleṣmapittapraśamanānām svedo mārdavakarāṇām vyāyāmaḥ sthairyakarāṇām kṣāraḥ puṃstvopaghātinām āmaṃ kapitthamakaṇṭhyānām āvikaṃ sarpirahṛdyānām mahiṣīkṣīraṃ svapnajananānām mandakaṃ dadhyabhiṣyandakarāṇām ikṣurmūtrajananānām yavāḥ purīṣajananānām jāmbavaṃ vātajananānām kulattho 'mlapittajananānām māṣāḥ śaṣkulyo 'vikṣīraṃ ca pittaśleṣmajananānām durālabhā pittaśleṣmopaśoṣaṇānām upavāso jvaraharāṇāṃ vṛṣo raktapittapraśamanānām kaṇṭakārikā kāsaghnānām lākṣā sadyaḥkṣataghnānām nāgabalābhyāsaḥ kṣatakṣayaghnānām puṣkaramūlaṃ hidhmāśvāsakāsapārśvaśūlāruciharāṇām ajāpayaḥ śoṣaghnastanyakararaktasaṅgrahaṇapraśamanānām mṛdbhṛṣṭaloṣṭaprasādaḥ charditṛṣṇātiyogapraśamanānām aruṣkaraścitrakamūlaṃ ca śuṣkārśaḥpraśamanānām kuṭajo raktarśaḥpraśamanānām lājāśchardighnānām yāvaśūkaḥ sraṃsanīyapācanīyārśoghnānām takrābhyāso 'rśaḥśvayathugrahaṇīdoṣaghṛtavyāpatpraśamanānām kravyānmāṃsābhyāso 'rśaḥśoṣagrahaṇīdoṣaghnānām mustaṃ saṅgrahaṇīyadīpanīyapācanīyānām ativiṣā saṅgrahaṇīyapācanīyasarvadoṣaharāṇām bilvaṃ saṅgrahaṇīyadīpanīyavātakaphapraśamanānām udīcyaṃ nirvāpaṇadīpanīyachardyatīsāraharāṇām kaṭvaṅgaṃ saṅgrahaṇīyadīpanīyānām kuṭajatvak śleṣmapittaraktasaṅgrahaṇīyopaśoṣaṇīyānām utpalakumudakiñjalko 'nantā ca saṅgrahaṇīyaraktapittapraśamanānām kāśmaryaphalaṃ raktasaṅgrahaṇīyaraktapittapraśamanānām gandhapriyaṅguḥ śoṇitapittātiyogapraśamanānām pṛśniparṇī raktasaṅgrahaṇīyadīpanīyapācanīyavātaharavṛṣyāṇām sālaparṇī vṛṣyasarvadoṣaharāṇām balā saṅgrahaṇīyabalyavātaharāṇām pippalīmūlaṃ dīpanīyapācanīyānāhaharāṇām citrakamūlaṃ dīpanīyapācanīyagudaśophaśūlaharāṇām gokṣurako mūtrakṛcchrānilaharāṇām haridrā pramehaharāṇām raktāvaseko vidradhivisarpapiṭakāgaṇḍamālāpaharāṇām eraṇḍatailābhyāso vardhmagulmānilaśūlaharāṇām laśuno gulmānilaharāṇām hiṅguniryāsaḥśchedanīyapācanīyānulomikavātakaphapraśamanānām amlavetaso bhedanīyadīpanīyānulomikavātakaphapraśamanānām uṣṭrīkṣīramudaraśvayathughnānām ayorajaḥ pāṇḍurogaghnānām khadiraḥ kuṣṭhaghnānām viḍaṅgaḥ kṛmighnānām rāsnā vātaharāṇām eraṇḍamūlaṃ vṛṣyavātaharāṇām guggulurmedonilaharāṇām amṛtā saṅgrahaṇīyadīpanīyavātaśleṣmaśoṇitavibandhapraśamanānām madanaphalaṃ vamanāsthāpanānuvāsanopayoginām trivṛtsukhavirecanānām caturaṅgulo mṛduvirecanānām snukpayastīkṣṇavirecanānām pratyakpuṣpī śirovirecanānām triphalātimiraghnānām guggulurvraṇyānām śirīṣo viṣaghnānām āmalakaṃ vayasthāpanānām harītakī pathyānām kṣīraghṛtābhyāso rasāyanānām samaghṛtasaktuprāśābhyāso vṛṣyodāvartaharāṇām saṅkalpo nakraretaśca vṛṣyāṇām" },
      { type: "verse", number: "3", sanskrit: "दौर्मनस्यमवृष्याणाम् तैलगण्डूषाभयासो दन्तबलरुचिकराणाम् चन्दनोदुम्बरं दाहनिर्वापणलेपनानाम् रास्नागरुणी शीतापनयनप्रलेपनानाम् लामज्जकोशीरे दाहत्वग्दोषस्वेदापनयनप्रलेपनानाम् कुष्ठं वातहराभ्यङ्गोपनाहोपयोगिनाम् मधुकं चक्षुष्यवृष्यकेश्यकण्ठ्यबल्यविरेचनीयरोपणीयानाम् अजीर्णाशनं ग्रहणीदूषणानाम् विरुद्धवीर्याशनं निन्दितव्याधिकराणाम् गुरुभोजनं दुर्विपाकानाम् अतिमात्राशनमामदोषहेतूनाम् यथाग्न्यभ्यवहारो ऽग्निसन्धुक्षणानाम् यथासात्म्यमाहारविहारौ सेव्यानाम् एकासनशयनभोजनं सुखनाशकराणाम् विषमाशनमग्निवैषम्यकराणाम् काले भोजनमारोग्यकराणाम् सुदर्शनमन्नं श्रद्धाजननानाम् वेगधारणमनारोग्यकराणाम् तृप्तिराहारगुणानाम् अनशनमायुषो ह्रासकराणाम् प्रमिताशनं गवेधुकान्नं च कर्शनीयानाम् उद्दालकान्नं रूक्षणीयानाम् मद्यं सौमनस्यजननानाम् मद्याक्षेपो धीधृतिस्मृतिहराणाम् स्त्रीष्वतिप्रसङ्गः शोषकराणाम् शुक्रवेगविनिग्रहः षाण्ढ्यकराणाम् पादाभ्यामुद्वर्तनमन्नश्रद्धाजननानाम् सूनादर्शनमन्नाश्रद्धाजननानाम्", text: "daurmanasyamavṛṣyāṇām tailagaṇḍūṣābhayāso dantabalarucikarāṇām candanodumbaraṃ dāhanirvāpaṇalepanānām rāsnāgaruṇī śītāpanayanapralepanānām lāmajjakośīre dāhatvagdoṣasvedāpanayanapralepanānām kuṣṭhaṃ vātaharābhyaṅgopanāhopayoginām madhukaṃ cakṣuṣyavṛṣyakeśyakaṇṭhyabalyavirecanīyaropaṇīyānām ajīrṇāśanaṃ grahaṇīdūṣaṇānām viruddhavīryāśanaṃ ninditavyādhikarāṇām gurubhojanaṃ durvipākānām atimātrāśanamāmadoṣahetūnām yathāgnyabhyavahāro 'gnisandhukṣaṇānām yathāsātmyamāhāravihārau sevyānām ekāsanaśayanabhojanaṃ sukhanāśakarāṇām viṣamāśanamagnivaiṣamyakarāṇām kāle bhojanamārogyakarāṇām sudarśanamannaṃ śraddhājananānām vegadhāraṇamanārogyakarāṇām tṛptirāhāraguṇānām anaśanamāyuṣo hrāsakarāṇām pramitāśanaṃ gavedhukānnaṃ ca karśanīyānām uddālakānnaṃ rūkṣaṇīyānām madyaṃ saumanasyajananānām madyākṣepo dhīdhṛtismṛtiharāṇām strīṣvatiprasaṅgaḥ śoṣakarāṇām śukravegavinigrahaḥ ṣāṇḍhyakarāṇām pādābhyāmudvartanamannaśraddhājananānām sūnādarśanamannāśraddhājananānām" },
      { type: "verse", number: "4", sanskrit: "मिथ्यायोगो व्याधिमुखानाम् रजस्वलागमनमलक्ष्मीमुखानाम् ब्रह्मचर्यमायुष्याणम् परदारगमनमनायुष्याणाम् अयथाप्राणमारम्भः प्राणोपरोधिनाम् विषादो रोगवर्द्धनानाम् हर्षः प्रीणनानाम् शोकः शोषणानाम् आश्वासो बलकराणाम् निर्वृतिः पुष्टिकराणाम् पुष्टिः स्वप्नकराणाम् स्वप्नः तन्द्रीकराणाम् सर्वरसाभ्यासो बलकराणाम् एकरसाभ्यासो दौर्बल्यारोचकान्यतमदोषप्रकोपकराणाम् गर्भशल्यमाहार्याणाम् अग्निरामस्तम्भशीतशूलोद्वेष्टकप्रशमनानाम् अजीर्णमुद्धार्याणाम् बालो मृदुभेषजार्हाणाम् वृद्धो याप्यानाम् गर्भिणी तीक्ष्णौषधव्यवायव्यायामवर्जनीयानाम् सौमनस्यं गर्भधारणानाम् असौमनस्यं दुःखजनानाम् सन्निपातो दुश्चिकित्स्यानाम् आमविषमचिकित्स्यानाम् ज्वरः शीघ्ररोगाणाम् कुष्ठं दीर्घरोगाणाम् राजयक्ष्मा रोगसमूहानाम् प्रमेहो ऽनुषङ्गिणाम् जलौकसो ऽनुशस्त्राणाम् बस्तिर्यन्त्राणाम् हिमवानौषधभूमीनाम् सोम औषधीनाम् मरुभूमिरारोग्यदेशानाम् आनूपभूमिरहितदेशानाम् निर्देशकारित्वमातुरगुणानाम् अनिर्देशकारित्वमरिष्टानाम् भिषक्चिकित्साङ्गानाम् सिद्धिर्वैद्याङ्गानाम् नास्तिको वर्ज्यानाम् लौल्यं क्लेशकराणाम् आत्मवत्तोपकारिणाम् शास्त्रसहितस्तर्कः साधकानाम् दृष्टकर्मता निस्संशयकराणाम् असमर्थता भयंकराणाम् तद्विद्यसम्भाषा बुद्धिवर्द्धनानाम् आचार्यः शास्त्राधिगमहेतूनाम् आयुर्वेदो ऽमृतानाम् सद्वैद्यद्वेषः प्राणत्यागहेतूनाम् सद्वचनमनुष्ठेयानाम् वायुः प्राणसंज्ञाप्रदानहेतूनाम् सर्वसन्यासः सुखानामिति तत्रोदकाग्निमृद्भृष्टलोष्टप्रसादतक्राभ्यासरक्तावसेकैरण्डतैलाभ्यासोष्ट्रीक्षीरमदनफलमद्याक्षेपैकरसगर्भिणीनामेकैकस्मात् समुदायाच्च निर्द्धारणम् पुष्करमूलादीनां तु समुदायादेवेति", text: "mithyāyogo vyādhimukhānām rajasvalāgamanamalakṣmīmukhānām brahmacaryamāyuṣyāṇam paradāragamanamanāyuṣyāṇām ayathāprāṇamārambhaḥ prāṇoparodhinām viṣādo rogavarddhanānām harṣaḥ prīṇanānām śokaḥ śoṣaṇānām āśvāso balakarāṇām nirvṛtiḥ puṣṭikarāṇām puṣṭiḥ svapnakarāṇām svapnaḥ tandrīkarāṇām sarvarasābhyāso balakarāṇām ekarasābhyāso daurbalyārocakānyatamadoṣaprakopakarāṇām garbhaśalyamāhāryāṇām agnirāmastambhaśītaśūlodveṣṭakapraśamanānām ajīrṇamuddhāryāṇām bālo mṛdubheṣajārhāṇām vṛddho yāpyānām garbhiṇī tīkṣṇauṣadhavyavāyavyāyāmavarjanīyānām saumanasyaṃ garbhadhāraṇānām asaumanasyaṃ duḥkhajanānām sannipāto duścikitsyānām āmaviṣamacikitsyānām jvaraḥ śīghrarogāṇām kuṣṭhaṃ dīrgharogāṇām rājayakṣmā rogasamūhānām prameho 'nuṣaṅgiṇām jalaukaso 'nuśastrāṇām bastiryantrāṇām himavānauṣadhabhūmīnām soma auṣadhīnām marubhūmirārogyadeśānām ānūpabhūmirahitadeśānām nirdeśakāritvamāturaguṇānām anirdeśakāritvamariṣṭānām bhiṣakcikitsāṅgānām siddhirvaidyāṅgānām nāstiko varjyānām laulyaṃ kleśakarāṇām ātmavattopakāriṇām śāstrasahitastarkaḥ sādhakānām dṛṣṭakarmatā nissaṃśayakarāṇām asamarthatā bhayaṃkarāṇām tadvidyasambhāṣā buddhivarddhanānām ācāryaḥ śāstrādhigamahetūnām āyurvedo 'mṛtānām sadvaidyadveṣaḥ prāṇatyāgahetūnām sadvacanamanuṣṭheyānām vāyuḥ prāṇasaṃjñāpradānahetūnām sarvasanyāsaḥ sukhānāmiti tatrodakāgnimṛdbhṛṣṭaloṣṭaprasādatakrābhyāsaraktāvasekairaṇḍatailābhyāsoṣṭrīkṣīramadanaphalamadyākṣepaikarasagarbhiṇīnāmekaikasmāt samudāyācca nirddhāraṇam puṣkaramūlādīnāṃ tu samudāyādeveti" },
      { type: "verse", number: "5", sanskrit: "भवति चात्र अग्र्याणां शतमुद्दिष्टं पञ्च पञ्चाशदुत्तरम् अलमेतद्विजानीयाद्धिताहितविनिश्चये", text: "bhavati cātra agryāṇāṃ śatamuddiṣṭaṃ pañca pañcāśaduttaram alametadvijānīyāddhitāhitaviniścaye" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 14,
    lang: "sa",
    content: [
      { type: "heading", heading: "Гандуша видхи — полоскание рта" },
      { type: "text", text: "Глава 14 Сутрастханы Астанга-санграхи посвящена теме «полоскание рта». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथ शोधनादिगणसङ्ग्रहमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "atha śodhanādigaṇasaṅgrahamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "मदननीमूतकेक्ष्वाकुकोशातकीद्वयफलपुष्पपत्राणि कुटजकरञ्जत्रपुससर्षपपिप्पलीविडङ्गैलाप्रत्यक्पुष्पीहरेणुपृथ्वीकाकुस्तुम्बरुप्रपुन्नाटानां फलानि शारदानि च हस्तिपर्ण्याः कोविदारकर्बुदारारिष्टश्वगन्धानीपविदुलबिल्वबिम्बीबन्धुजीवकश्वेताशणपुष्पीसदापुष्पीवचाचित्राचित्रकमृगेन्द्रवारुणीसुषवीचतुरङ्गुलस्वादु कण्टकपाठापाटलीशार्ङ्गेष्टामधुकमूर्वासप्तपर्णसोमवल्कद्वीपिशिग्रुसुमनस्सौमनस्यायवानीवृश्चीवपुनर्नवामहा सहाक्षुद्रसहेक्षुकाण्डकालक्तपिप्पलीमूलचविकानलदोशीरह्रीबेरमूलानि शाल्मलीशेलुकाभद्रपण्यैरावण्यावर्त्तक्युपोदकोद्दालधन्वनरसाञ्जनराजादनोपचित्रागोपशृङ्गाटिकापिच्छाः प्रियङ्गुपूष्पम् तालीसपत्रम् हरिद्राशृङ्गवेरकन्दौ मधुयष्टीदारुहरिद्रासासौ तगरगुडूचीमधुफणितक्षीरक्षारलवणानि चेति वमनोपयोगीनि", text: "madananīmūtakekṣvākukośātakīdvayaphalapuṣpapatrāṇi kuṭajakarañjatrapusasarṣapapippalīviḍaṅgailāpratyakpuṣpīhareṇupṛthvīkākustumbaruprapunnāṭānāṃ phalāni śāradāni ca hastiparṇyāḥ kovidārakarbudārāriṣṭaśvagandhānīpavidulabilvabimbībandhujīvakaśvetāśaṇapuṣpīsadāpuṣpīvacācitrācitrakamṛgendravāruṇīsuṣavīcaturaṅgulasvādu kaṇṭakapāṭhāpāṭalīśārṅgeṣṭāmadhukamūrvāsaptaparṇasomavalkadvīpiśigrusumanassaumanasyāyavānīvṛścīvapunarnavāmahā sahākṣudrasahekṣukāṇḍakālaktapippalīmūlacavikānaladośīrahrīberamūlāni śālmalīśelukābhadrapaṇyairāvaṇyāvarttakyupodakoddāladhanvanarasāñjanarājādanopacitrāgopaśṛṅgāṭikāpicchāḥ priyaṅgupūṣpam tālīsapatram haridrāśṛṅgaverakandau madhuyaṣṭīdāruharidrāsāsau tagaraguḍūcīmadhuphaṇitakṣīrakṣāralavaṇāni ceti vamanopayogīni" },
      { type: "verse", number: "3", sanskrit: "त्रिवृच्छामादन्तीद्रवन्तीशङ्खिनीसप्तलाजगन्धाजशृङ्गीवचागवाक्षीछगलान्त्रीसुवर्णक्षीरीचित्रककिणिहीह्रस्वपञ्चमूलवृश्चीवपुनर्नवापलङ्कषावास्तुकशाकसालमूलानि तिल्वकरम्यककाम्पिल्यकपाटलीत्वच त्रिफलापीलुप्रियालकुवलबदरकर्कन्धुकाश्मर्यपरूषकद्राक्षानीलिनीक्लीतनकोदकीर्याविडङ्गपूगपञ्चाङ्गुलफलानि चतुरङ्गुलफलपत्राणि पूतीकस्य त्वक्फलपत्राणि महावृक्षसप्तच्छदज्योतिष्मतीक्षीराणि क्षीरमद्यमस्तुतक्रधान्याम्लमूत्राणि चेति विरेचनोपयोगीनि", text: "trivṛcchāmādantīdravantīśaṅkhinīsaptalājagandhājaśṛṅgīvacāgavākṣīchagalāntrīsuvarṇakṣīrīcitrakakiṇihīhrasvapañcamūlavṛścīvapunarnavāpalaṅkaṣāvāstukaśākasālamūlāni tilvakaramyakakāmpilyakapāṭalītvaca triphalāpīlupriyālakuvalabadarakarkandhukāśmaryaparūṣakadrākṣānīlinīklītanakodakīryāviḍaṅgapūgapañcāṅgulaphalāni caturaṅgulaphalapatrāṇi pūtīkasya tvakphalapatrāṇi mahāvṛkṣasaptacchadajyotiṣmatīkṣīrāṇi kṣīramadyamastutakradhānyāmlamūtrāṇi ceti virecanopayogīni" },
      { type: "verse", number: "4", sanskrit: "कोशातकीदेवदालीसप्तलाकारवोल्लिकास्वरसमर्कक्षीरमुष्णोदकं चेत्युभयात्मकानि बस्तिषु तु तेषु तेष्ववस्थान्तरेषुयान्युपयुज्यन्ते द्रव्याणि तान्यसङ्ख्येयत्वान्नोपदिश्यन्ते रसस्कन्धेभ्य एव यथादोषं यथावस्थं च विभजेत् सर्वेषु तु प्रायो मदनकुटज जीमूतकेक्ष्वाकुकोशातकीद्वयत्रपुंसासिद्धार्थकशताह्वाफलानि बलादशमूलैरण्डत्रिवृद्वचायष्ट्याह्वकुष्ठरास्नापुनर्नवकत्तृणमूलानि सरलदेवदारुहपुषाहिङ्गुरसाञ्जनव्योषपत्रैलामृतायवकोलकुलत्थगुडलवणमस्तुधान्याम्लमूत्रस्नेहक्षीरक्षौद्राणि चेति निरूहोपयोगीनि", text: "kośātakīdevadālīsaptalākāravollikāsvarasamarkakṣīramuṣṇodakaṃ cetyubhayātmakāni bastiṣu tu teṣu teṣvavasthāntareṣuyānyupayujyante dravyāṇi tānyasaṅkhyeyatvānnopadiśyante rasaskandhebhya eva yathādoṣaṃ yathāvasthaṃ ca vibhajet sarveṣu tu prāyo madanakuṭaja jīmūtakekṣvākukośātakīdvayatrapuṃsāsiddhārthakaśatāhvāphalāni balādaśamūlairaṇḍatrivṛdvacāyaṣṭyāhvakuṣṭharāsnāpunarnavakattṛṇamūlāni saraladevadāruhapuṣāhiṅgurasāñjanavyoṣapatrailāmṛtāyavakolakulatthaguḍalavaṇamastudhānyāmlamūtrasnehakṣīrakṣaudrāṇi ceti nirūhopayogīni" },
      { type: "verse", number: "5", sanskrit: "अपामार्गविडङ्गमरिचपिप्पलीशिरीषविल्वाजाज्यजमोजवार्ताकपृथ्वीकैलाहरेणुफलानि तालीसतमालतर्कारीहरितकवर्गपत्राणि सर्षपाफलपत्राणि शिग्रुफलपत्रत्वचः हरिद्रामूलकलशुननागरकन्दपत्राणि अतिविषाकन्दाः कुष्ठवचाभार्ङ्गीश्वेताकिणिहीनागदन्तीज्योतिष्मतीगवाक्षीवयस्थावृश्चिकालीबम्बीकरञ्जमूलानि अर्कालर्कपुष्पमूलानि लोध्रमदनसप्तपर्णनिम्बपीलुबीजानि मुरुङ्गीमातुलुङ्गीलवङ्गपुष्पाणि अगरुसुरदारुसरलसल्लकीजिङ्गिण्यसनरसाञ्जनहिङ्गुलाक्षानिर्यासाः तमालसालतालमधूकदार्वीसाराः तेजस्विनीमेषशृङ्गीवराङ्गेङ्गुदीबृहतीद्वयचोचत्वचः राजादनमज्जक्षौद्रलवणानि मद्यानि गवादिशकृद्रसमूत्रपित्तान्येवंविधानि चेन्द्रियोपशयान्यन्यान्यपि तथा स्नेहाः क्षीरं रक्तं मांसरसो धान्यरसस्तोयमिति शिरोविरेचनोपयोगीनि", text: "apāmārgaviḍaṅgamaricapippalīśirīṣavilvājājyajamojavārtākapṛthvīkailāhareṇuphalāni tālīsatamālatarkārīharitakavargapatrāṇi sarṣapāphalapatrāṇi śigruphalapatratvacaḥ haridrāmūlakalaśunanāgarakandapatrāṇi ativiṣākandāḥ kuṣṭhavacābhārṅgīśvetākiṇihīnāgadantījyotiṣmatīgavākṣīvayasthāvṛścikālībambīkarañjamūlāni arkālarkapuṣpamūlāni lodhramadanasaptaparṇanimbapīlubījāni muruṅgīmātuluṅgīlavaṅgapuṣpāṇi agarusuradārusaralasallakījiṅgiṇyasanarasāñjanahiṅgulākṣāniryāsāḥ tamālasālatālamadhūkadārvīsārāḥ tejasvinīmeṣaśṛṅgīvarāṅgeṅgudībṛhatīdvayacocatvacaḥ rājādanamajjakṣaudralavaṇāni madyāni gavādiśakṛdrasamūtrapittānyevaṃvidhāni cendriyopaśayānyanyānyapi tathā snehāḥ kṣīraṃ raktaṃ māṃsaraso dhānyarasastoyamiti śirovirecanopayogīni" },
      { type: "verse", number: "6", sanskrit: "मधुकपद्मकमञ्जिष्ठाशारिवामुस्तापुन्नागनागकेसरैलवालुकसुवर्णत्वक्तमालपृथ्वीकाहरेणुलाक्षाशतपुष्पासल्लकीशर्करामदनकमरुबकन्यग्रोधोदुम्बराश्वत्थप्लक्षलोध्रत्वक् पद्मोत्पलानि सर्वगन्धद्रव्याणि च कुष्ठतगरवर्ज्यानि प्रायोगिकधूमोपयोगीनि अगरुगुग्गुलुसल्लकीशैलेयकनलदह्रीबेरहरेणूशीरमुस्ताध्यामकवराङ्गश्रीवेष्टकस्थौणेयकपरिपेलवैलवालुककुन्दुरुकसर्जरसयष्ट्याह्वफलसारस्नेहमधूच्छिष्टबिल्वफलमज्जयवतिलमाषकुङ्कुमानि मेदोमज्जवसासर्पीषि च स्नैहिकधूमोपयोगीनि शिरोविरेचनद्रव्याणि गन्धद्रव्याणि च तीक्ष्णानि मनोह्वा हरितालं चेति तीक्ष्णधूमोपयोगीनि", text: "madhukapadmakamañjiṣṭhāśārivāmustāpunnāganāgakesarailavālukasuvarṇatvaktamālapṛthvīkāhareṇulākṣāśatapuṣpāsallakīśarkarāmadanakamarubakanyagrodhodumbarāśvatthaplakṣalodhratvak padmotpalāni sarvagandhadravyāṇi ca kuṣṭhatagaravarjyāni prāyogikadhūmopayogīni agaruguggulusallakīśaileyakanaladahrīberahareṇūśīramustādhyāmakavarāṅgaśrīveṣṭakasthauṇeyakaparipelavailavālukakundurukasarjarasayaṣṭyāhvaphalasārasnehamadhūcchiṣṭabilvaphalamajjayavatilamāṣakuṅkumāni medomajjavasāsarpīṣi ca snaihikadhūmopayogīni śirovirecanadravyāṇi gandhadravyāṇi ca tīkṣṇāni manohvā haritālaṃ ceti tīkṣṇadhūmopayogīni" },
      { type: "verse", number: "7", sanskrit: "भद्रदारुकुष्ठतगरवरुणबलातिबलार्तगलकच्छुराह्लादिनीकुबेराक्षीवत्सादिन्यर्कालर्ककतकभार्ङ्गीकार्पासीवृश्चिकालीपत्तूरप्रभृतीनि विदार्यादिगणो वीरतरादि स्तृणाख्यवर्ज्यानि षट् पञ्चमूलानि चेति वातशमनानि दूर्वानन्तामोचरसमञ्जिष्ठापरिपेलवकालाकालीयककदलीकन्दलीपयस्यात्मगुप्तानालिकेरखर्ज्जूरद्राक्षाविदारीबदरीबलानागबलानागपुष्पशतावरीशीत पाक्योदनपाकीतृणशूल्यांशुमतीद्वयारिष्टकारिष्टाटरूषकेत्कटर्प्रियङ्गुधातकीधवधवधन्वनस्यन्दनखदिरकदरप्रियालतालसालसर्जतिनिशाश्वकर्णगुन्द्रावानीरपद्मापद्मकपद्मबीजमृणालकुमुदनलिनसौगन्धिकपुण्डरीकशतपत्रशैवालकल्हारोत्पलकाकोल्युत्पलिकाशलूकशृङ्गाटककशेरुकक्रौञ्चादनप्रभृतीनि अन्यानि च शीतवीर्याणि सारिवादिः पद्मकादिः पटोलाअदिर्न्यग्रोधादिर्दाहहरो महाकषायस्तृणपञ्चमूलं चेति पित्तशमनानि शीतशिवशतपुष्पासरलसुरदारुरास्नेङ्गु दीसातलासुमनःकाकादनीलाङ्गलिकाहस्तिकर्णमुञ्जातलामज्जकप्रभृतीन्यन्यानि च रूक्षोष्णवीर्याण्यारग्वधादिरसनादिरर्कादिः सुरसादिर्मुष्ककादिर्वत्सकादिर्मुस्तादिः शीतघ्नश्च महाकषायो वल्लीकण्टकपञ्चमूले च श्लेष्मशमनानीति", text: "bhadradārukuṣṭhatagaravaruṇabalātibalārtagalakacchurāhlādinīkuberākṣīvatsādinyarkālarkakatakabhārṅgīkārpāsīvṛścikālīpattūraprabhṛtīni vidāryādigaṇo vīratarādi stṛṇākhyavarjyāni ṣaṭ pañcamūlāni ceti vātaśamanāni dūrvānantāmocarasamañjiṣṭhāparipelavakālākālīyakakadalīkandalīpayasyātmaguptānālikerakharjjūradrākṣāvidārībadarībalānāgabalānāgapuṣpaśatāvarīśīta pākyodanapākītṛṇaśūlyāṃśumatīdvayāriṣṭakāriṣṭāṭarūṣaketkaṭarpriyaṅgudhātakīdhavadhavadhanvanasyandanakhadirakadarapriyālatālasālasarjatiniśāśvakarṇagundrāvānīrapadmāpadmakapadmabījamṛṇālakumudanalinasaugandhikapuṇḍarīkaśatapatraśaivālakalhārotpalakākolyutpalikāśalūkaśṛṅgāṭakakaśerukakrauñcādanaprabhṛtīni anyāni ca śītavīryāṇi sārivādiḥ padmakādiḥ paṭolāadirnyagrodhādirdāhaharo mahākaṣāyastṛṇapañcamūlaṃ ceti pittaśamanāni śītaśivaśatapuṣpāsaralasuradārurāsneṅgu dīsātalāsumanaḥkākādanīlāṅgalikāhastikarṇamuñjātalāmajjakaprabhṛtīnyanyāni ca rūkṣoṣṇavīryāṇyāragvadhādirasanādirarkādiḥ surasādirmuṣkakādirvatsakādirmustādiḥ śītaghnaśca mahākaṣāyo vallīkaṇṭakapañcamūle ca śleṣmaśamanānīti" },
      { type: "verse", number: "8", sanskrit: "भवति चात्र समीक्ष्य दोषदूष्यादीनमी वर्गाः सुयोजिताः सर्वामयजयायालं जायन्ते नियतात्मनाम्", text: "bhavati cātra samīkṣya doṣadūṣyādīnamī vargāḥ suyojitāḥ sarvāmayajayāyālaṃ jāyante niyatātmanām" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 15,
    lang: "sa",
    content: [
      { type: "heading", heading: "Каватха видхи — лечение горла" },
      { type: "text", text: "Глава 15 Сутрастханы Астанга-санграхи посвящена теме «лечение горла». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो महाकषायसङ्ग्रहमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto mahākaṣāyasaṅgrahamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "आनन्त्यादौषधानामामयानां चानन्ता एव कषायाः ये तु सुतरामुपयोगवन्तः प्रकर्षवर्तिनो वा ते जीवनीयादिसंज्ञाः प्रत्येकं दशकषायसंयोगात् पञ्चचत्वारिंशन्महाकषाया वक्ष्यन्ते तत्प्रतिपत्यर्थमेव मन्दबुद्धीनाम् बुद्धिमतामुदाहरणामात्रप्रदर्शनार्थम् शक्यं हि बुद्धिमद्भिः स्वादुशीतस्निग्धादीन् जीवन्त्यादिषु साधारणान् गुणानालोच्य क्षीरेक्षुद्राक्षाक्षोडविदारीकन्दादिष्वपि तद्गुणेषु जीवनीयादित्वमवधारयितुम् यथोक्तानुसरणमेव तु श्रेयो मन्दबुद्धेरिति व्यस्ताश्च ते चत्वारि पञ्चाशदधिकानि तदभिधानान्येव यद्यपि तानि तान्येव द्रव्याणीति द्रव्यसङ्करः कषायेषु तथापि न संज्ञाविरोधः एकस्यापि बहुकार्यनिर्वर्तनात् तत्र लवणवर्ज्या रसाः कल्पनायां कषाया इत्युचयन्ते तद्योनित्वात् लवणस्य यतो निर्यासादिकल्पनानामसम्भवः पृथगुपयोगोपकाररहितत्वाच्च नैरथक्यमिति", text: "ānantyādauṣadhānāmāmayānāṃ cānantā eva kaṣāyāḥ ye tu sutarāmupayogavantaḥ prakarṣavartino vā te jīvanīyādisaṃjñāḥ pratyekaṃ daśakaṣāyasaṃyogāt pañcacatvāriṃśanmahākaṣāyā vakṣyante tatpratipatyarthameva mandabuddhīnām buddhimatāmudāharaṇāmātrapradarśanārtham śakyaṃ hi buddhimadbhiḥ svāduśītasnigdhādīn jīvantyādiṣu sādhāraṇān guṇānālocya kṣīrekṣudrākṣākṣoḍavidārīkandādiṣvapi tadguṇeṣu jīvanīyāditvamavadhārayitum yathoktānusaraṇameva tu śreyo mandabuddheriti vyastāśca te catvāri pañcāśadadhikāni tadabhidhānānyeva yadyapi tāni tānyeva dravyāṇīti dravyasaṅkaraḥ kaṣāyeṣu tathāpi na saṃjñāvirodhaḥ ekasyāpi bahukāryanirvartanāt tatra lavaṇavarjyā rasāḥ kalpanāyāṃ kaṣāyā ityucayante tadyonitvāt lavaṇasya yato niryāsādikalpanānāmasambhavaḥ pṛthagupayogopakārarahitatvācca nairathakyamiti" },
      { type: "verse", number: "3", sanskrit: "भवति चात्र जीवन्तीकाकोल्यौ द्वे मेदे मुद्गमाषपर्ण्यौ च ऋषभकजीवकमधुकं चेति गणो जीवनीयाख्यः", text: "bhavati cātra jīvantīkākolyau dve mede mudgamāṣaparṇyau ca ṛṣabhakajīvakamadhukaṃ ceti gaṇo jīvanīyākhyaḥ" },
      { type: "verse", number: "4", sanskrit: "वाट्या बला पयस्याकाकोल्याविक्षुवाजिगन्धे च क्षीरिणिराजक्षवके भारद्वाजी च बृंहणीयो ऽयम्", text: "vāṭyā balā payasyākākolyāvikṣuvājigandhe ca kṣīriṇirājakṣavake bhāradvājī ca bṛṃhaṇīyo 'yam" },
      { type: "verse", number: "5", sanskrit: "हैमवती चिरिबिल्वं मुस्ता कुष्ठं वचा हरिद्रे च चित्रककटुकातिविषा वर्गोयं लेखनीयाख्यः", text: "haimavatī ciribilvaṃ mustā kuṣṭhaṃ vacā haridre ca citrakakaṭukātiviṣā vargoyaṃ lekhanīyākhyaḥ" },
      { type: "verse", number: "6", sanskrit: "अर्कैरण्डौ चित्रा चित्रकचिरिबिल्वशङ्खिनीसरला हेमक्षीरी कटुका वह्निमुखी भेदनीयो ऽयम्", text: "arkairaṇḍau citrā citrakaciribilvaśaṅkhinīsaralā hemakṣīrī kaṭukā vahnimukhī bhedanīyo 'yam" },
      { type: "verse", number: "7", sanskrit: "मधुमधुकपृश्निपर्णीकट्फललोध्रप्रियङ्गुधातक्यः अम्बष्ठकी समङ्गा मोचरसश्चेति सन्धानः", text: "madhumadhukapṛśniparṇīkaṭphalalodhrapriyaṅgudhātakyaḥ ambaṣṭhakī samaṅgā mocarasaśceti sandhānaḥ" },
      { type: "verse", number: "8", sanskrit: "हिङ्गुमरिचाम्लवेतस दीप्यकभल्लातकास्थिसंयोगात् वर्गः सपञ्चकोलो निर्दिष्टो दीपनीयो ऽयम्", text: "hiṅgumaricāmlavetasa dīpyakabhallātakāsthisaṃyogāt vargaḥ sapañcakolo nirdiṣṭo dīpanīyo 'yam" },
      { type: "verse", number: "9", sanskrit: "ऐन्द्र्यतिरसा पयस्या ऋष्यप्रोक्ता स्थिरा बलातिबला इति बल्यो दशको ऽयं हयगन्धा रोहिणी ऋषभः", text: "aindryatirasā payasyā ṛṣyaproktā sthirā balātibalā iti balyo daśako 'yaṃ hayagandhā rohiṇī ṛṣabhaḥ" },
      { type: "verse", number: "10", sanskrit: "चन्दनतुङ्गपयस्या सितालतामधुकपद्मकोशरिम् वर्ण्यो गणोयमुदितो मञ्जिष्ठासारिवासहितः", text: "candanatuṅgapayasyā sitālatāmadhukapadmakośarim varṇyo gaṇoyamudito mañjiṣṭhāsārivāsahitaḥ" },
      { type: "verse", number: "11", sanskrit: "हंसपदीबृहतीद्वयमृद्वीकासारिवेक्षुमूलानि कैडर्यमधुककृष्णाः सविदार्यः कण्ठजननानि", text: "haṃsapadībṛhatīdvayamṛdvīkāsārivekṣumūlāni kaiḍaryamadhukakṛṣṇāḥ savidāryaḥ kaṇṭhajananāni" },
      { type: "verse", number: "12", sanskrit: "वृक्षाम्लबदरदाडिमकुवलाम्राम्रातालिकुचकरमर्दम् हृद्यं समातुलुङ्गाम्लवेतसं विद्धि वर्गमिमम्", text: "vṛkṣāmlabadaradāḍimakuvalāmrāmrātālikucakaramardam hṛdyaṃ samātuluṅgāmlavetasaṃ viddhi vargamimam" },
      { type: "verse", number: "13", sanskrit: "नागरचविकाचित्रकविडङ्गमूर्वामृतावचामुस्ताः सहपिप्पलीपटोलास्तृप्तिघ्नो ऽयं गणः प्रथितः", text: "nāgaracavikācitrakaviḍaṅgamūrvāmṛtāvacāmustāḥ sahapippalīpaṭolāstṛptighno 'yaṃ gaṇaḥ prathitaḥ" },
      { type: "verse", number: "14", sanskrit: "कुटजफलबिल्वचित्रकमहौषधप्रतिविषावचाचविकाः धन्वयवासं पथ्या दारुहरिद्रागणो ऽयमर्शोघ्नः", text: "kuṭajaphalabilvacitrakamahauṣadhaprativiṣāvacācavikāḥ dhanvayavāsaṃ pathyā dāruharidrāgaṇo 'yamarśoghnaḥ" },
      { type: "verse", number: "15", sanskrit: "खदिरामलकारुष्करनिशाभयासप्तपर्णकरवीराः कुष्ठाघ्नाश्चतुङ्गुलविडङ्गजातिप्रवालाश्च", text: "khadirāmalakāruṣkaraniśābhayāsaptaparṇakaravīrāḥ kuṣṭhāghnāścatuṅgulaviḍaṅgajātipravālāśca" },
      { type: "verse", number: "16", sanskrit: "नलदकृतमालचन्दनसर्षपघननिम्बकुटजमधुकानि कण्डूं दारुहरिद्रासनक्तमालानि निघ्नन्ति", text: "naladakṛtamālacandanasarṣapaghananimbakuṭajamadhukāni kaṇḍūṃ dāruharidrāsanaktamālāni nighnanti" },
      { type: "verse", number: "17", sanskrit: "अक्षीवमरिचकेबुकविडङ्गगण्डीरकिणिहिनिर्गुण्ड्यः घ्नन्ति क्रिमीन् श्वदंष्ट्राविषाखुपर्ण्यस्तथा न चिरात्", text: "akṣīvamaricakebukaviḍaṅgagaṇḍīrakiṇihinirguṇḍyaḥ ghnanti krimīn śvadaṃṣṭrāviṣākhuparṇyastathā na cirāt" },
      { type: "verse", number: "18", sanskrit: "मञ्जिष्ठाश्लेष्मातकरजनीसुवहाशिरीषपालिन्द्यः सैलाचन्दनकत्काः ससिन्दुवारा विषं घ्नन्ति", text: "mañjiṣṭhāśleṣmātakarajanīsuvahāśirīṣapālindyaḥ sailācandanakatkāḥ sasinduvārā viṣaṃ ghnanti" },
      { type: "verse", number: "19", sanskrit: "शालिकुशकाशषष्टिकवीरणदर्भेक्षुवालिकेक्षूणाम् तद्वद् गुन्द्रोत्कटयोर्मूलमलं स्तन्यजननाय", text: "śālikuśakāśaṣaṣṭikavīraṇadarbhekṣuvālikekṣūṇām tadvad gundrotkaṭayormūlamalaṃ stanyajananāya" },
      { type: "verse", number: "20", sanskrit: "पाठानागरसुरतरुघनामृतासारिवेन्द्रयवमूर्वाः कटुकाकिराततिक्तं वर्गो ऽयं स्तन्यशुद्धिकरः", text: "pāṭhānāgarasuratarughanāmṛtāsārivendrayavamūrvāḥ kaṭukākirātatiktaṃ vargo 'yaṃ stanyaśuddhikaraḥ" },
      { type: "verse", number: "21", sanskrit: "मेदाकाकोलीद्वयवृक्षरुहाजीवकर्षभकुलिङ्गाः शुक्रजननो गणो ऽयं सह जटिलाशूर्पपर्णीभिः", text: "medākākolīdvayavṛkṣaruhājīvakarṣabhakuliṅgāḥ śukrajanano gaṇo 'yaṃ saha jaṭilāśūrpaparṇībhiḥ" },
      { type: "verse", number: "22", sanskrit: "कुष्ठैलवालुककट्फलकाण्डेक्ष्विक्ष्वब्धिफेनकोशीरैः वसुकेक्षुरकैः शुक्रं शुध्येत् सकदम्बनिर्यासैः", text: "kuṣṭhailavālukakaṭphalakāṇḍekṣvikṣvabdhiphenakośīraiḥ vasukekṣurakaiḥ śukraṃ śudhyet sakadambaniryāsaiḥ" },
      { type: "verse", number: "23", sanskrit: "द्राक्षाकाकोलीद्वय मधुपर्णीमधुकजीवकविदार्यः स्नेहोपगाः समेदा जीवन्तीशालिपर्णीकाः", text: "drākṣākākolīdvaya madhuparṇīmadhukajīvakavidāryaḥ snehopagāḥ samedā jīvantīśāliparṇīkāḥ" },
      { type: "verse", number: "24", sanskrit: "सौभञ्जनकपुनर्नववृश्चीवकुलत्थमाषबदराणि स्वेदोपगानि विद्यात् सयवतिलार्कोरुपूगानि", text: "saubhañjanakapunarnavavṛścīvakulatthamāṣabadarāṇi svedopagāni vidyāt sayavatilārkorupūgāni" },
      { type: "verse", number: "25", sanskrit: "लाजाम्रबदरदाडिमयवषष्टिकमातुलुङ्गसेव्यानि जम्ब्वाम्रपल्लवानि च वमिनिग्रहणानि मृत्सा च", text: "lājāmrabadaradāḍimayavaṣaṣṭikamātuluṅgasevyāni jambvāmrapallavāni ca vaminigrahaṇāni mṛtsā ca" },
      { type: "verse", number: "26", sanskrit: "नागरधन्वयवासकवालकपर्पटकचन्दनगुडूच्यः भूनिम्बघनपटोली कुस्तुम्बर्यस्तृषं घ्नन्ति", text: "nāgaradhanvayavāsakavālakaparpaṭakacandanaguḍūcyaḥ bhūnimbaghanapaṭolī kustumbaryastṛṣaṃ ghnanti" },
      { type: "verse", number: "27", sanskrit: "बृहतीद्वयवृक्षरुहापुष्करमूलाभयाकणाशृङ्ग्यः हिध्मां निघ्नन्ति शटी दुरालभा बदरबीजं च", text: "bṛhatīdvayavṛkṣaruhāpuṣkaramūlābhayākaṇāśṛṅgyaḥ hidhmāṃ nighnanti śaṭī durālabhā badarabījaṃ ca" },
      { type: "verse", number: "28", sanskrit: "शामानन्ता पद्मा कट्वङ्गः पद्मकेसरं लोध्रम् धातकिकुसुमसमङ्गामोचरसाम्रास्थि विड्ग्रहणम्", text: "śāmānantā padmā kaṭvaṅgaḥ padmakesaraṃ lodhram dhātakikusumasamaṅgāmocarasāmrāsthi viḍgrahaṇam" },
      { type: "verse", number: "29", sanskrit: "जम्बूसल्लकिमधुकं नीलोत्पलकच्छुरातिलश्र्याह्वम् भृष्टा च मृत् पयस्या सशाल्मली विड्विरजनानि", text: "jambūsallakimadhukaṃ nīlotpalakacchurātilaśryāhvam bhṛṣṭā ca mṛt payasyā saśālmalī viḍvirajanāni" },
      { type: "verse", number: "30", sanskrit: "जम्ब्वाम्रोदुम्बरवटकपीतनप्लक्षपिप्पलाश्मन्तम् भल्लातसोमवल्कं मूत्रग्रहणाय् निर्दिष्टम्", text: "jambvāmrodumbaravaṭakapītanaplakṣapippalāśmantam bhallātasomavalkaṃ mūtragrahaṇāy nirdiṣṭam" },
      { type: "verse", number: "31", sanskrit: "कमलनलिनकुमुद मधुकसौगन्धिकधातकीलताकुसुमम् मूत्रं नयति विरागं सोत्पलशतपत्रपुण्डरीकं च", text: "kamalanalinakumuda madhukasaugandhikadhātakīlatākusumam mūtraṃ nayati virāgaṃ sotpalaśatapatrapuṇḍarīkaṃ ca" },
      { type: "verse", number: "32", sanskrit: "वृक्षादनीश्वदंष्ट्रादर्भेत्कटवसुकवशिरकुशकाशाः मूत्रं विरेचयेयुर्गुन्द्रा पाषाणभेदश्च", text: "vṛkṣādanīśvadaṃṣṭrādarbhetkaṭavasukavaśirakuśakāśāḥ mūtraṃ virecayeyurgundrā pāṣāṇabhedaśca" },
      { type: "verse", number: "33", sanskrit: "द्राक्षामलकपुनर्नबवृश्चीवदुरालभाभयाकृष्णाः कासं घ्नन्ति सशृङ्गी तामलकी कण्टकारी च", text: "drākṣāmalakapunarnabavṛścīvadurālabhābhayākṛṣṇāḥ kāsaṃ ghnanti saśṛṅgī tāmalakī kaṇṭakārī ca" },
      { type: "verse", number: "34", sanskrit: "चण्डाम्लवेतसशटी तामलकीसुरसहिङ्गुजीवन्त्यः पुष्करमूलैलागुरुवर्गो ऽयं श्वासशमनाय", text: "caṇḍāmlavetasaśaṭī tāmalakīsurasahiṅgujīvantyaḥ puṣkaramūlailāguruvargo 'yaṃ śvāsaśamanāya" },
      { type: "verse", number: "35", sanskrit: "द्राक्षापीलुपरूषकमञ्जिष्ठासारिवामृतापाठाः त्रिफला चेति गणो ऽयं ज्वरस्य शमनाय् निर्दिष्टः", text: "drākṣāpīluparūṣakamañjiṣṭhāsārivāmṛtāpāṭhāḥ triphalā ceti gaṇo 'yaṃ jvarasya śamanāy nirdiṣṭaḥ" },
      { type: "verse", number: "36", sanskrit: "दाडिमफल्गुपरूषकप्रियालयवषष्टिकेक्षुबदराणि श्रमनाशनानि विद्याद् द्राक्षाखर्ज्जूरसहितानि", text: "dāḍimaphalguparūṣakapriyālayavaṣaṣṭikekṣubadarāṇi śramanāśanāni vidyād drākṣākharjjūrasahitāni" },
      { type: "verse", number: "37", sanskrit: "पद्मकलाजोशीरं मधुकोत्पलसारिवासितोदीच्यम् काश्मर्यफलं चन्दनमेष गणो दाहहा प्रोक्तः", text: "padmakalājośīraṃ madhukotpalasārivāsitodīcyam kāśmaryaphalaṃ candanameṣa gaṇo dāhahā proktaḥ" },
      { type: "verse", number: "38", sanskrit: "नतनागरागुरुवचाधान्यकभूतीकपिप्पलीव्याघ्रयः शीतं शमयन्त्यचिरात् स्योनाकः साग्निमन्थश्च", text: "natanāgarāguruvacādhānyakabhūtīkapippalīvyāghrayaḥ śītaṃ śamayantyacirāt syonākaḥ sāgnimanthaśca" },
      { type: "verse", number: "39", sanskrit: "तिन्दुकप्रियालवीजकसप्तच्छदखदिरकदरबदराणि अरिमेदवाजिकर्णौ ककुभश्चोदर्दशमनानि", text: "tindukapriyālavījakasaptacchadakhadirakadarabadarāṇi arimedavājikarṇau kakubhaścodardaśamanāni" },
      { type: "verse", number: "40", sanskrit: "काकोल्येला सेव्यं निदिग्धिके शालिपृश्निपर्ण्यौ च घ्नन्त्यङ्गमर्दमचिराचन्दनमधुकोरुबूकं च", text: "kākolyelā sevyaṃ nidigdhike śālipṛśniparṇyau ca ghnantyaṅgamardamacirācandanamadhukorubūkaṃ ca" },
      { type: "verse", number: "41", sanskrit: "दीप्यकमरिचाजाजीगण्डीरं साजगन्धमथ शूलम् शमयति सपञ्चकोलं शोफं दशमूलमाद्यं च", text: "dīpyakamaricājājīgaṇḍīraṃ sājagandhamatha śūlam śamayati sapañcakolaṃ śophaṃ daśamūlamādyaṃ ca" },
      { type: "verse", number: "42", sanskrit: "मधुमधुकलाजगैरिकफलिनीमोचरसमृत्कपालानि संस्थापयन्ति रुधिरं रुधिरं च सशर्करं लोध्रम्", text: "madhumadhukalājagairikaphalinīmocarasamṛtkapālāni saṃsthāpayanti rudhiraṃ rudhiraṃ ca saśarkaraṃ lodhram" },
      { type: "verse", number: "43", sanskrit: "शैलैलवालुकट्फलमोचरसाशोकपद्मकशिरीषम् स्थापयति वेदनामथ सहतुङ्गकदम्बविदुलं च", text: "śailailavālukaṭphalamocarasāśokapadmakaśirīṣam sthāpayati vedanāmatha sahatuṅgakadambavidulaṃ ca" },
      { type: "verse", number: "44", sanskrit: "कैडर्यहिङ्गुचोरकपलङ्कषाशोकरोहिणिवयस्थाः पूत्यरिमेदो जटिलागोलोमिवचाश्च संज्ञादाः", text: "kaiḍaryahiṅgucorakapalaṅkaṣāśokarohiṇivayasthāḥ pūtyarimedo jaṭilāgolomivacāśca saṃjñādāḥ" },
      { type: "verse", number: "45", sanskrit: "ऐन्द्री दूर्वामोघाविष्वक्सेना व्यथा शिवारिष्टा ब्राह्मी सवाट्यपुष्पी शतवीर्या स्थापयेद् गर्भम्", text: "aindrī dūrvāmoghāviṣvaksenā vyathā śivāriṣṭā brāhmī savāṭyapuṣpī śatavīryā sthāpayed garbham" },
      { type: "verse", number: "46", sanskrit: "अमृता पथ्या धात्री जीवन्ती श्रेयसी स्थिरायुक्ता मण्डूकपर्ण्यतिरसा स्थापयति पुनर्नवा च वयः", text: "amṛtā pathyā dhātrī jīvantī śreyasī sthirāyuktā maṇḍūkaparṇyatirasā sthāpayati punarnavā ca vayaḥ" },
      { type: "verse", number: "47", sanskrit: "इति नानाविधव्याधिविघातार्थमुदाहृताः योगा रोगातुरवशात् कल्पयेत्तान् यथायथम्", text: "iti nānāvidhavyādhivighātārthamudāhṛtāḥ yogā rogāturavaśāt kalpayettān yathāyatham" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 16,
    lang: "sa",
    content: [
      { type: "heading", heading: "Карна видхи — лечение ушей" },
      { type: "text", text: "Глава 16 Сутрастханы Астанга-санграхи посвящена теме «лечение ушей». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो विविधद्रव्यगणसङ्ग्रहमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vividhadravyagaṇasaṅgrahamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "विदारिपञ्चाड्गुलवृश्चिकालीवृश्चीवदेवाह्वयशूर्पपर्ण्यः कण्डूकरी जीवनह्रस्वसंज्ञे द्वे पञ्चके गोपसुता त्रिपादी", text: "vidāripañcāḍgulavṛścikālīvṛścīvadevāhvayaśūrpaparṇyaḥ kaṇḍūkarī jīvanahrasvasaṃjñe dve pañcake gopasutā tripādī" },
      { type: "verse", number: "3", sanskrit: "विदार्यादिरयं हृद्यो बृंहणो वातपित्तहा शोषगुल्माङ्गमर्दोर्ध्वश्वासकासहरो गणः", text: "vidāryādirayaṃ hṛdyo bṛṃhaṇo vātapittahā śoṣagulmāṅgamardordhvaśvāsakāsaharo gaṇaḥ" },
      { type: "verse", number: "4", sanskrit: "सारिवोशीरकाश्मर्यमधूकशिशिरद्वयम् यष्टीपरूषकं हन्ति दाहपित्तास्रतृड्ज्वरान्", text: "sārivośīrakāśmaryamadhūkaśiśiradvayam yaṣṭīparūṣakaṃ hanti dāhapittāsratṛḍjvarān" },
      { type: "verse", number: "5", sanskrit: "पद्मकपुण्ड्रौ वृद्धितुगर्ध्यः शृङ्ग्यमृता दश जीवनसंज्ञाः स्तन्यकरा घ्नन्तीरणपित्तं प्रीणनबृंहणजीवनवृष्याः", text: "padmakapuṇḍrau vṛddhitugardhyaḥ śṛṅgyamṛtā daśa jīvanasaṃjñāḥ stanyakarā ghnantīraṇapittaṃ prīṇanabṛṃhaṇajīvanavṛṣyāḥ" },
      { type: "verse", number: "6", sanskrit: "परूषकं वरा द्राक्षा कट्फलं कतकात् फलम् राजाह्वं दाडिमं शाकं तृण्मूत्रामयवातजित् अञ्जनं फलिनी मांसी पद्मोत्पलरसाञ्जनम् सैलामधुकनागाह्वं विषान्तर्दाहपित्तनुत्", text: "parūṣakaṃ varā drākṣā kaṭphalaṃ katakāt phalam rājāhvaṃ dāḍimaṃ śākaṃ tṛṇmūtrāmayavātajit añjanaṃ phalinī māṃsī padmotpalarasāñjanam sailāmadhukanāgāhvaṃ viṣāntardāhapittanut" },
      { type: "verse", number: "7", sanskrit: "पटोलकटुरोहिणीचन्दनं मधुस्रवगुडूचिपाठान्वितम् निहन्ति कफपित्तकुष्ठज्वरान् विषं वमिमरोचकं कामलाम्", text: "paṭolakaṭurohiṇīcandanaṃ madhusravaguḍūcipāṭhānvitam nihanti kaphapittakuṣṭhajvarān viṣaṃ vamimarocakaṃ kāmalām" },
      { type: "verse", number: "8", sanskrit: "गुडूचीपद्मकारिष्टधानका रक्तचन्दनम् पित्तश्लेष्मज्वरच्छर्दिदाहतृष्णाघ्नमग्निकृत्", text: "guḍūcīpadmakāriṣṭadhānakā raktacandanam pittaśleṣmajvaracchardidāhatṛṣṇāghnamagnikṛt" },
      { type: "verse", number: "9", sanskrit: "आरग्वधेन्द्रयवपाटलिकाकतिक्तानिम्बामृतामधुरसास्रुववृक्षपाठाः भूनिम्बसैर्यकपटोलकरञ्जयुग्मसप्तच्छदाग्निसुषवीफलबाणघोण्टाः", text: "āragvadhendrayavapāṭalikākatiktānimbāmṛtāmadhurasāsruvavṛkṣapāṭhāḥ bhūnimbasairyakapaṭolakarañjayugmasaptacchadāgnisuṣavīphalabāṇaghoṇṭāḥ" },
      { type: "verse", number: "10", sanskrit: "आरग्वधादिर्जयति छर्दिकुष्ठविषज्वरान् कफं कण्डूं प्रमेहं च दुष्टव्रणविशोधनः", text: "āragvadhādirjayati chardikuṣṭhaviṣajvarān kaphaṃ kaṇḍūṃ pramehaṃ ca duṣṭavraṇaviśodhanaḥ" },
      { type: "verse", number: "11", sanskrit: "असनतिनिशभूर्जश्वेतवाहप्रकीर्याः खदिरकदरभण्डीशिंशपामेषशृङ्ग्यः त्रिहिमनतपलाशाजोङ्गकः शाकसालौ धवकबुककलिङ्गच्छागकर्णाश्वकर्णाः", text: "asanatiniśabhūrjaśvetavāhaprakīryāḥ khadirakadarabhaṇḍīśiṃśapāmeṣaśṛṅgyaḥ trihimanatapalāśājoṅgakaḥ śākasālau dhavakabukakaliṅgacchāgakarṇāśvakarṇāḥ" },
      { type: "verse", number: "12", sanskrit: "असनादिर्विजयते श्वित्रकुष्ठकफक्रिमीन् पाण्डुरोगं प्रमेहं च मेदोदोषनिबर्हणः", text: "asanādirvijayate śvitrakuṣṭhakaphakrimīn pāṇḍurogaṃ pramehaṃ ca medodoṣanibarhaṇaḥ" },
      { type: "verse", number: "13", sanskrit: "वरणसैर्यकयुग्मशतावरीदहनमोरटबिल्वविषाणिकाः द्विबृहतीद्विकरञ्जजयाद्वयं बहलपल्लवदर्भरुजाकराः", text: "varaṇasairyakayugmaśatāvarīdahanamoraṭabilvaviṣāṇikāḥ dvibṛhatīdvikarañjajayādvayaṃ bahalapallavadarbharujākarāḥ" },
      { type: "verse", number: "14", sanskrit: "वरणादिः कफं मेदो मन्दाग्नित्वं नियच्छति आढ्यवातं शिरश्शूलं गुल्मं चान्तः सविद्रधिम्", text: "varaṇādiḥ kaphaṃ medo mandāgnitvaṃ niyacchati āḍhyavātaṃ śiraśśūlaṃ gulmaṃ cāntaḥ savidradhim" },
      { type: "verse", number: "15", sanskrit: "ऊषकस्तुत्थकं हिङ्गुकासीसद्वयसैन्धवम् सशिलाजतु कृच्छ्राश्मगुल्ममेदः कफापहम्", text: "ūṣakastutthakaṃ hiṅgukāsīsadvayasaindhavam saśilājatu kṛcchrāśmagulmamedaḥ kaphāpaham" },
      { type: "verse", number: "16", sanskrit: "भवन्ति चात्र वीरतरारणिकौ नगगुच्छौ मोरटटुण्टुकसैर्यकयुग्मम् मुस्तकमञ्जरिकर्कशपार्था मूत्रविरेककरो दशकश्च", text: "bhavanti cātra vīratarāraṇikau nagagucchau moraṭaṭuṇṭukasairyakayugmam mustakamañjarikarkaśapārthā mūtravirekakaro daśakaśca" },
      { type: "verse", number: "17", sanskrit: "वर्गो वीरतराद्यो ऽयं हन्ति वातकृतान् गदान् अश्मरीशर्करामूत्रकृच्छ्राघातरुजापहः", text: "vargo vīratarādyo 'yaṃ hanti vātakṛtān gadān aśmarīśarkarāmūtrakṛcchrāghātarujāpahaḥ" },
      { type: "verse", number: "18", sanskrit: "लोध्रशाबरकलोध्रपलाशाजिङ्गिणीसरलकट्फलयुक्ताः कुत्सिताम्बकदलीगतशोकाः सेलवालुपरिपेलवमोचाः", text: "lodhraśābarakalodhrapalāśājiṅgiṇīsaralakaṭphalayuktāḥ kutsitāmbakadalīgataśokāḥ selavāluparipelavamocāḥ" },
      { type: "verse", number: "19", sanskrit: "एष लोध्रादिको नाम मेदःकफहरोगणः योनिदोषहरः स्तम्भी वर्ण्यो विषविनाशनः", text: "eṣa lodhrādiko nāma medaḥkaphaharogaṇaḥ yonidoṣaharaḥ stambhī varṇyo viṣavināśanaḥ" },
      { type: "verse", number: "20", sanskrit: "अर्कालर्कौ नागदन्ती विशल्या भार्ङ्गी रास्ना वृश्चिकाली प्रकीर्या प्रत्यक्पुष्पी पीततैलोदकीर्याः श्वेतायुग्मं तापसानां च वृक्षः", text: "arkālarkau nāgadantī viśalyā bhārṅgī rāsnā vṛścikālī prakīryā pratyakpuṣpī pītatailodakīryāḥ śvetāyugmaṃ tāpasānāṃ ca vṛkṣaḥ" },
      { type: "verse", number: "21", sanskrit: "अयमर्कादिको वर्गः कफमेदोविषापहः कृमिकुष्ठप्रशमनो विशेषात् व्रणशोधनः", text: "ayamarkādiko vargaḥ kaphamedoviṣāpahaḥ kṛmikuṣṭhapraśamano viśeṣāt vraṇaśodhanaḥ" },
      { type: "verse", number: "22", sanskrit: "सुरसयुगफणिज्जं कालमाला विडङ्गं खरबुकवृषकर्णीकट्फलं कासमर्दः क्षवकसरसिभार्ङ्गीकार्मुकाः काकमाची कुलहलविषमुष्टी भूस्तृणो भूतकेशी", text: "surasayugaphaṇijjaṃ kālamālā viḍaṅgaṃ kharabukavṛṣakarṇīkaṭphalaṃ kāsamardaḥ kṣavakasarasibhārṅgīkārmukāḥ kākamācī kulahalaviṣamuṣṭī bhūstṛṇo bhūtakeśī" },
      { type: "verse", number: "23", sanskrit: "सुरसादिर्गणः श्लेष्ममेदःक्रिमिनिषूदनः प्रतिश्यायारुचिश्वासकासघ्नो व्रणशोधनः", text: "surasādirgaṇaḥ śleṣmamedaḥkriminiṣūdanaḥ pratiśyāyāruciśvāsakāsaghno vraṇaśodhanaḥ" },
      { type: "verse", number: "24", sanskrit: "मुष्ककस्नुग्वराद्वीपीपलाशधवशिंशपाः गुल्ममेहाश्मरीपाण्डुमेदो ऽर्शःकफशुक्रजित्", text: "muṣkakasnugvarādvīpīpalāśadhavaśiṃśapāḥ gulmamehāśmarīpāṇḍumedo 'rśaḥkaphaśukrajit" },
      { type: "verse", number: "25", sanskrit: "वत्सको मधुरसा त्रुटिर्वचा दीर्घवृन्तफलवेल्लसर्षपाः रोहिणीस्थपनिहिंगुभार्ङ्गयः शूलघाति दशकं घुणप्रिया", text: "vatsako madhurasā truṭirvacā dīrghavṛntaphalavellasarṣapāḥ rohiṇīsthapanihiṃgubhārṅgayaḥ śūlaghāti daśakaṃ ghuṇapriyā" },
      { type: "verse", number: "26", sanskrit: "वत्सकाद्यो ऽनिलश्लेष्ममेदो ऽरोचकपीनसान् शूलार्शोज्वरगुल्मांश्च हन्ति दीपनपाचनः", text: "vatsakādyo 'nilaśleṣmamedo 'rocakapīnasān śūlārśojvaragulmāṃśca hanti dīpanapācanaḥ" },
      { type: "verse", number: "27", sanskrit: "वचाजलददेवाह्वनागरातिविषाभयाः हरिद्राद्वययष्ट्याह्वकलशीकुटजोद्भवाः", text: "vacājaladadevāhvanāgarātiviṣābhayāḥ haridrādvayayaṣṭyāhvakalaśīkuṭajodbhavāḥ" },
      { type: "verse", number: "28", sanskrit: "वचाहरिद्रादिगणावामातीसारनाशनौ मेदःकफाढ्यपवनस्तन्यदोषनिबर्हणौ", text: "vacāharidrādigaṇāvāmātīsāranāśanau medaḥkaphāḍhyapavanastanyadoṣanibarhaṇau" },
      { type: "verse", number: "29", sanskrit: "प्रियङ्गुपुष्पाञ्जनयुग्मपद्माः पद्माद्रजो योजनवल्यनन्ता सालद्रुमो मोचरसः समङ्गा पुन्नागशीतं मदनीयहेतुः", text: "priyaṅgupuṣpāñjanayugmapadmāḥ padmādrajo yojanavalyanantā sāladrumo mocarasaḥ samaṅgā punnāgaśītaṃ madanīyahetuḥ" },
      { type: "verse", number: "30", sanskrit: "अम्बष्ठामधुकनमस्करीनन्दीवृक्षपलाशकच्छुराः लोध्रं घातकिविल्वपेशिका वटवङ्गः कमलोद्भवं रजः", text: "ambaṣṭhāmadhukanamaskarīnandīvṛkṣapalāśakacchurāḥ lodhraṃ ghātakivilvapeśikā vaṭavaṅgaḥ kamalodbhavaṃ rajaḥ" },
      { type: "verse", number: "31", sanskrit: "गणौ प्रियङ्ग्वम्बष्ठादी पक्वतीसारनाशनौ सन्धानीयौ हितौ पित्ते व्रणानामपि रोपणौ", text: "gaṇau priyaṅgvambaṣṭhādī pakvatīsāranāśanau sandhānīyau hitau pitte vraṇānāmapi ropaṇau" },
      { type: "verse", number: "32", sanskrit: "मुस्तावचाग्निद्विनिशाद्वितिक्ताभल्लातपाठात्रिफलाविषाख्याः कुष्ठं त्रुटी हैमवती च योनिस्तन्यामयघ्ना मलपाचनाश्च", text: "mustāvacāgnidviniśādvitiktābhallātapāṭhātriphalāviṣākhyāḥ kuṣṭhaṃ truṭī haimavatī ca yonistanyāmayaghnā malapācanāśca" },
      { type: "verse", number: "33", sanskrit: "न्यग्रोधपिप्पलसदाफललोध्रयुग्मजम्बूद्वयार्जुनकपीतनसोमवल्काः प्लक्षास्रवञ्जुलप्रियालपलाशनन्दीकोलीकदम्बविरलामधुकं मधूकम्", text: "nyagrodhapippalasadāphalalodhrayugmajambūdvayārjunakapītanasomavalkāḥ plakṣāsravañjulapriyālapalāśanandīkolīkadambaviralāmadhukaṃ madhūkam" },
      { type: "verse", number: "34", sanskrit: "न्यग्रोधादिर्गणो व्रण्यः सङ्ग्राही भग्नसाधनः मेदःपित्तास्रतृड्दाहयोनिरोगनिबर्हणः", text: "nyagrodhādirgaṇo vraṇyaḥ saṅgrāhī bhagnasādhanaḥ medaḥpittāsratṛḍdāhayoniroganibarhaṇaḥ" },
      { type: "verse", number: "35", sanskrit: "एलायुग्मतुरुष्ककुष्ठफलिनीमांसीजलध्यामकस्पृक्काचोरकचोचपत्रतगरस्थौणेयजातीरसाः शुक्तिव्याघ्रनखौ सुराह्वमगरुःश्रीवासकःकुङ्कुमं चण्डागुग्गुलुदेवधूपखपुराःपुन्नागनागाह्वयम्", text: "elāyugmaturuṣkakuṣṭhaphalinīmāṃsījaladhyāmakaspṛkkācorakacocapatratagarasthauṇeyajātīrasāḥ śuktivyāghranakhau surāhvamagaruḥśrīvāsakaḥkuṅkumaṃ caṇḍāgugguludevadhūpakhapurāḥpunnāganāgāhvayam" },
      { type: "verse", number: "36", sanskrit: "एलादिको वातकफौ विषं च विनियच्छति वर्णप्रसादनः कण्डूपिटकाकोठनाशनः", text: "elādiko vātakaphau viṣaṃ ca viniyacchati varṇaprasādanaḥ kaṇḍūpiṭakākoṭhanāśanaḥ" },
      { type: "verse", number: "37", sanskrit: "श्यामादन्तीद्रवन्तीक्रमुककुठरणाशङ्खिनीचर्मसाह्वास्वर्णक्षीरिगवाक्षीशिखरिरजनिका छिन्नरोहा करञ्जः बस्तान्त्री व्याधिघातो बहलबहुरसस्तीक्ष्णवृक्षात् फलानि श्यामाद्यो हन्ति गुल्मं विषमरुचिकफौ हृद्रुजं मूत्रकृछ्रम्", text: "śyāmādantīdravantīkramukakuṭharaṇāśaṅkhinīcarmasāhvāsvarṇakṣīrigavākṣīśikharirajanikā chinnarohā karañjaḥ bastāntrī vyādhighāto bahalabahurasastīkṣṇavṛkṣāt phalāni śyāmādyo hanti gulmaṃ viṣamarucikaphau hṛdrujaṃ mūtrakṛchram" },
      { type: "verse", number: "38", sanskrit: "पिप्पलीपिप्पलीमूलचव्यचित्रकशृङ्गवेरमरिचहस्तिपिप्पलीहरेणुकैलाजमोजेन्द्रयवपाठाजीरकसर्षपमहानिम्बफल्गुहिङ्गुभार्ङ्गीवचामुस्तामधुरसातिविषाविडङ्गानि कटुरोहिणी चेति", text: "pippalīpippalīmūlacavyacitrakaśṛṅgaveramaricahastipippalīhareṇukailājamojendrayavapāṭhājīrakasarṣapamahānimbaphalguhiṅgubhārṅgīvacāmustāmadhurasātiviṣāviḍaṅgāni kaṭurohiṇī ceti" },
      { type: "verse", number: "39", sanskrit: "पिप्पल्यादिः कफहरः प्रतिश्यायानिलारुचीः निहन्याद्दीपनो गुल्मशूलघ्नश्चामपाचनः", text: "pippalyādiḥ kaphaharaḥ pratiśyāyānilārucīḥ nihanyāddīpano gulmaśūlaghnaścāmapācanaḥ" },
      { type: "verse", number: "40", sanskrit: "पञ्चविंशीतरित्युक्ता वर्गास्तेषु त्वलाभतः युञ्ज्यात्तद्विधमन्यच्च द्रव्यं जह्यादयौगिकम्", text: "pañcaviṃśītarityuktā vargāsteṣu tvalābhataḥ yuñjyāttadvidhamanyacca dravyaṃ jahyādayaugikam" },
      { type: "verse", number: "41", sanskrit: "एते वर्गा दोषदूष्याद्यपेक्ष्य कल्कक्वाथस्नेहलेहादियुक्ताः पाने नस्ये ऽन्वासने ऽन्तर्बहिर्वा लेपाभ्यङ्गैर्घ्नन्ति रोगान् सुकृछ्रान्", text: "ete vargā doṣadūṣyādyapekṣya kalkakvāthasnehalehādiyuktāḥ pāne nasye 'nvāsane 'ntarbahirvā lepābhyaṅgairghnanti rogān sukṛchrān" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 17,
    lang: "sa",
    content: [
      { type: "heading", heading: "Нетра видхи — лечение глаз" },
      { type: "text", text: "Глава 17 Сутрастханы Астанга-санграхи посвящена теме «лечение глаз». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो द्रव्यादिविज्ञानीयमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto dravyādivijñānīyamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "इह हि द्रव्यं पञ्चमहाभूतात्मकम् तस्याधिष्ठानं पृथिवी योनिरुदकं खानिलानलसमवायान्निर्वृत्तिविशेषौ उत्कर्षेण तु व्यपदेशः तस्माद्भूतसमवायसम्भवान्नैकरसं द्रव्यम् ततश्च नैकदोषा व्याधयः", text: "iha hi dravyaṃ pañcamahābhūtātmakam tasyādhiṣṭhānaṃ pṛthivī yonirudakaṃ khānilānalasamavāyānnirvṛttiviśeṣau utkarṣeṇa tu vyapadeśaḥ tasmādbhūtasamavāyasambhavānnaikarasaṃ dravyam tataśca naikadoṣā vyādhayaḥ" },
      { type: "verse", number: "3", sanskrit: "तत्र व्यक्तो रसः अनुरसस्तु रसेनाभिभूतत्वादव्यक्तो व्यक्तो वा किञ्चिदन्ते रसस्य तु छेदनोपशमने द्वे कर्मणी हिताहितौ प्रभावौ तदाश्रयेषु च द्रव्यसंज्ञकेषु पृथिव्यादिषु गुणाः प्रकृतिविकृतिविचारदेशकालवशाद्गुर्वादयो रसेषु साहचर्यादुपचर्यन्ते", text: "tatra vyakto rasaḥ anurasastu rasenābhibhūtatvādavyakto vyakto vā kiñcidante rasasya tu chedanopaśamane dve karmaṇī hitāhitau prabhāvau tadāśrayeṣu ca dravyasaṃjñakeṣu pṛthivyādiṣu guṇāḥ prakṛtivikṛtivicāradeśakālavaśādgurvādayo raseṣu sāhacaryādupacaryante" },
      { type: "verse", number: "4", sanskrit: "तत्र द्रव्यं गुरुकठिनविशदमन्दसान्द्रस्थूलस्थिरगन्धगुणबहुलं पार्थिवं उपचयगौरवसङ्घातस्थैर्यकरम्", text: "tatra dravyaṃ gurukaṭhinaviśadamandasāndrasthūlasthiragandhaguṇabahulaṃ pārthivaṃ upacayagauravasaṅghātasthairyakaram" },
      { type: "verse", number: "5", sanskrit: "द्रवस्निग्धशीतगुरुमन्दसान्द्रसरमृदुपिच्छिलरसगुणबहुलमौदकं उपक्लेदस्नेहबन्धविष्यन्दमार्दवप्रह्लादकरम्", text: "dravasnigdhaśītagurumandasāndrasaramṛdupicchilarasaguṇabahulamaudakaṃ upakledasnehabandhaviṣyandamārdavaprahlādakaram" },
      { type: "verse", number: "6", sanskrit: "तीक्ष्णोष्णरूक्षसूक्ष्मलघुविशदरूपगुणबहुलमाग्नेयं दाहपाकप्रकाशप्रभावर्णकरम्", text: "tīkṣṇoṣṇarūkṣasūkṣmalaghuviśadarūpaguṇabahulamāgneyaṃ dāhapākaprakāśaprabhāvarṇakaram" },
      { type: "verse", number: "7", sanskrit: "रूक्षसूक्ष्मलघुविशदविकाषिव्यवायिशीतखरस्पर्शगुणबहुलं वाय्व्यं रौक्ष्यलाघववैशद्यग्लानिविचारकरम्", text: "rūkṣasūkṣmalaghuviśadavikāṣivyavāyiśītakharasparśaguṇabahulaṃ vāyvyaṃ raukṣyalāghavavaiśadyaglānivicārakaram" },
      { type: "verse", number: "8", sanskrit: "सूक्ष्मलघुविशदश्लक्ष्णव्यवायिविविक्तशब्दगुणबहुलमाकाशात्मकं सौषिर्यलाघवकरम्", text: "sūkṣmalaghuviśadaślakṣṇavyavāyiviviktaśabdaguṇabahulamākāśātmakaṃ sauṣiryalāghavakaram" },
      { type: "verse", number: "9", sanskrit: "इत्थं च नानौषधभूतं जगति किञ्चिद् द्रव्यमस्ति विविधार्थप्रयोगवशात्", text: "itthaṃ ca nānauṣadhabhūtaṃ jagati kiñcid dravyamasti vividhārthaprayogavaśāt" },
      { type: "verse", number: "10", sanskrit: "तत्राग्निमारुतात्मकं प्रायेणोर्ध्वभागिकम् तयोर्हिलाघवादूर्ध्वगतित्वाच्चाग्नेः प्लवनत्वाच्च मारुतस्य", text: "tatrāgnimārutātmakaṃ prāyeṇordhvabhāgikam tayorhilāghavādūrdhvagatitvāccāgneḥ plavanatvācca mārutasya" },
      { type: "verse", number: "11", sanskrit: "भूम्यौदकात्मकं तु प्रायेणाधोभागिकम् तयोर्हि गौरवानिम्नगत्वाच्च तोयस्य", text: "bhūmyaudakātmakaṃ tu prāyeṇādhobhāgikam tayorhi gauravānimnagatvācca toyasya" },
      { type: "verse", number: "12", sanskrit: "व्यामिश्रात्मकमुभयतोभागम्", text: "vyāmiśrātmakamubhayatobhāgam" },
      { type: "verse", number: "13", sanskrit: "शमनं तु दोषविपरीतगुणमुक्तं प्राक् तत्सङ्करे च यतो बाहुल्येन कार्यकर्तृत्वं भवति यदेवाधिकं तदेव तत्कार्यकरमिति व्यपदेशः तथानिलात्मकं ग्राहि अनलात्मकं दीपनपाचनम् उभयात्मकं लेखनम् भूम्युदकात्मकं बृंहणम्", text: "śamanaṃ tu doṣaviparītaguṇamuktaṃ prāk tatsaṅkare ca yato bāhulyena kāryakartṛtvaṃ bhavati yadevādhikaṃ tadeva tatkāryakaramiti vyapadeśaḥ tathānilātmakaṃ grāhi analātmakaṃ dīpanapācanam ubhayātmakaṃ lekhanam bhūmyudakātmakaṃ bṛṃhaṇam" },
      { type: "verse", number: "14", sanskrit: "तत्र कट्वम्ललवणा वीर्येण यथोत्तरमुष्णाः तिक्तकषायमधुराः शीताः", text: "tatra kaṭvamlalavaṇā vīryeṇa yathottaramuṣṇāḥ tiktakaṣāyamadhurāḥ śītāḥ" },
      { type: "verse", number: "15", sanskrit: "तिक्तकटुकषाया रूक्षा बद्धविण्मूत्रमारुताः लवणाम्लमधूराःस्निग्धाःसृष्टविण्मूत्रमारुताः", text: "tiktakaṭukaṣāyā rūkṣā baddhaviṇmūtramārutāḥ lavaṇāmlamadhūrāḥsnigdhāḥsṛṣṭaviṇmūtramārutāḥ" },
      { type: "verse", number: "16", sanskrit: "लवणकषायमधुरा गुरवः तद्वदम्लकटुकतिक्ता लघवः अन्ये पुनर्गुरुलघुस्निग्धरूक्षसाधारणं लवणमिच्छन्ति", text: "lavaṇakaṣāyamadhurā guravaḥ tadvadamlakaṭukatiktā laghavaḥ anye punargurulaghusnigdharūkṣasādhāraṇaṃ lavaṇamicchanti" },
      { type: "verse", number: "17", sanskrit: "वीर्यं तु केचिद् गुरुलघुस्निग्धरूक्षतीक्ष्णमन्दशीतोष्णभेदेनाष्टविधमाहुः अपरे पुनः पठन्ति", text: "vīryaṃ tu kecid gurulaghusnigdharūkṣatīkṣṇamandaśītoṣṇabhedenāṣṭavidhamāhuḥ apare punaḥ paṭhanti" },
      { type: "verse", number: "18", sanskrit: "वीर्यं द्रव्यस्य तद्ज्ञेयं यद्योगात् क्रियते क्रिया नावीर्यं कुरुते किञ्चित् सर्वा वीर्यकृता हि सा", text: "vīryaṃ dravyasya tadjñeyaṃ yadyogāt kriyate kriyā nāvīryaṃ kurute kiñcit sarvā vīryakṛtā hi sā" },
      { type: "verse", number: "19", sanskrit: "तैरपि चैवमतिप्रकृष्टशक्तियुक्तानामशेषौधगुणसारभूतानामष्टानामेव गुर्वादीनां वीर्यसंज्ञा विशिष्टाम्नायविहितापि लौकिकीति समुद्भाव्यते तथा हि तया रसविपाकगुणान्तरविजयिनो भूयांसश्च वरिष्ठाश्च गुणाः सङ्गृहीताः विशेषवृत्या च तत्र तत्र द्रव्यस्वरूपकथने व्यवहारः प्रवृत्तितो भवति अत एव सर्वातिशायी द्रव्यस्वभावः प्रभाव इत्याम्नातः सत्यपि च क्रियानिर्वर्त्तनसामान्ये तद्विपरीता रसादयो वीर्याख्यया प्रभावसंज्ञया वा न परामृश्यन्ते", text: "tairapi caivamatiprakṛṣṭaśaktiyuktānāmaśeṣaudhaguṇasārabhūtānāmaṣṭānāmeva gurvādīnāṃ vīryasaṃjñā viśiṣṭāmnāyavihitāpi laukikīti samudbhāvyate tathā hi tayā rasavipākaguṇāntaravijayino bhūyāṃsaśca variṣṭhāśca guṇāḥ saṅgṛhītāḥ viśeṣavṛtyā ca tatra tatra dravyasvarūpakathane vyavahāraḥ pravṛttito bhavati ata eva sarvātiśāyī dravyasvabhāvaḥ prabhāva ityāmnātaḥ satyapi ca kriyānirvarttanasāmānye tadviparītā rasādayo vīryākhyayā prabhāvasaṃjñayā vā na parāmṛśyante" },
      { type: "verse", number: "20", sanskrit: "अन्ये तु गुर्वादीनामग्नीषोमात्मकत्वादादानविसर्गविभाअगेन कालस्य चोष्णशीतात्मकत्वाद् द्विविधमेवामनन्ति एवं चाहुः", text: "anye tu gurvādīnāmagnīṣomātmakatvādādānavisargavibhāagena kālasya coṣṇaśītātmakatvād dvividhamevāmananti evaṃ cāhuḥ" },
      { type: "verse", number: "21", sanskrit: "नानात्मकमपि द्रव्यमग्नीषोमौ महाबलौ व्यक्ताव्यक्तं जगदिव नातिक्रामति जातुचित्", text: "nānātmakamapi dravyamagnīṣomau mahābalau vyaktāvyaktaṃ jagadiva nātikrāmati jātucit" },
      { type: "verse", number: "22", sanskrit: "तत्रोष्णं दहनपचनस्वेदनविलयनानिलकफशमनानि करोति", text: "tatroṣṇaṃ dahanapacanasvedanavilayanānilakaphaśamanāni karoti" },
      { type: "verse", number: "23", sanskrit: "शीतं ह्लादनस्तम्भनजीवनरक्तपित्तप्रसादनादीनि", text: "śītaṃ hlādanastambhanajīvanaraktapittaprasādanādīni" },
      { type: "verse", number: "24", sanskrit: "इति वीर्यमुक्तं विपाकस्तूच्यते विपाकस्तु प्रायः स्वादुः स्वादुलवणयोरम्लो ऽम्लस्य कटुरितरेषाम् रसैरसौ तुल्यफलः", text: "iti vīryamuktaṃ vipākastūcyate vipākastu prāyaḥ svāduḥ svādulavaṇayoramlo 'mlasya kaṭuritareṣām rasairasau tulyaphalaḥ" },
      { type: "verse", number: "25", sanskrit: "द्रव्यगुणविशेषेण चास्याल्पमध्यभूयस्त्वमुपलक्षयेत्", text: "dravyaguṇaviśeṣeṇa cāsyālpamadhyabhūyastvamupalakṣayet" },
      { type: "verse", number: "26", sanskrit: "पराशरस्तु पठति पाकास्त्रयो रसानामम्लो ऽम्लं पच्यते कटुः कटुकम् चत्वारो ऽन्ये मधुरं सङ्कीर्णरसास्तु सङ्कीर्णम्", text: "parāśarastu paṭhati pākāstrayo rasānāmamlo 'mlaṃ pacyate kaṭuḥ kaṭukam catvāro 'nye madhuraṃ saṅkīrṇarasāstu saṅkīrṇam" },
      { type: "verse", number: "27", sanskrit: "कटुतिक्तकषायाणां कटुको येषां विपाक इति पक्षः तेषां पित्तविघाते तिक्तकषायौ कथं भवतः", text: "kaṭutiktakaṣāyāṇāṃ kaṭuko yeṣāṃ vipāka iti pakṣaḥ teṣāṃ pittavighāte tiktakaṣāyau kathaṃ bhavataḥ" },
      { type: "verse", number: "28", sanskrit: "तत्र यन्मधुरं रसविपाकयोः शीतवीर्यं च द्रव्यं यच्चाम्लं तयोरुष्णवीर्यं च यद्वा कटुकं तेषां यथास्वं रसेभ्यः प्रायो गुणान् दोषकोपशमनत्वं च विद्यात् तद्यथा क्षीरमदिरामरिचादीनाम्", text: "tatra yanmadhuraṃ rasavipākayoḥ śītavīryaṃ ca dravyaṃ yaccāmlaṃ tayoruṣṇavīryaṃ ca yadvā kaṭukaṃ teṣāṃ yathāsvaṃ rasebhyaḥ prāyo guṇān doṣakopaśamanatvaṃ ca vidyāt tadyathā kṣīramadirāmaricādīnām" },
      { type: "verse", number: "29", sanskrit: "रसादिसङ्करेण त्वन्यथात्वम् यथा मधु मधुरं श्लेष्माणं शमयति कटुविपाकतया सकषायत्वाद्रौक्ष्याच्च वातं जनयति शीतवीर्यत्वाच्च तथा यवो ऽपि आनूपौदकपिशितं शीतमपि पित्तं करोत्युष्णवीर्यत्वात् तथा तैलं कटुविपाकतया च विपाकत एव बद्धविण्मूत्रम् अम्लं काञ्जिकं कफं जयति रूक्षोष्णत्वात् कपित्थं तु रौक्ष्यात् पित्तं तु शीतवीर्यत्वात् आमलकं पित्तं शीतवीर्यत्वात् स्वादुपाकतया च कफं रौक्ष्याल्लाघवाच्च शैत्यरौक्ष्यलाघवैस्तु न वातम् लवणं सैन्धवं स्वादुपाकतया पित्तं जयति लाघवात् कफं जयति कटुकापि शुण्ठी स्नेहौष्ण्यस्वादुपाकैर्वातं क्षपयति पिप्पली च लशुनो ऽपि स्नेहौष्ण्यगौरवैः पलाण्डुश्च स तु स्नेहगौरवाभ्यां जनयति श्लेष्माणम् वृद्धं च मूलकं स्वादुपाकतया स्निग्धानि तिक्तानि व्याघ्रीविशल्यार्कागरूण्युष्णवीर्यत्वात् पित्तं जनयन्ति कषायतिक्तं महत् पञ्चमूलं वातं जयति न तु पित्तं उष्णवीर्यत्वात् कषायश्च कुलत्थो ऽम्लपाकतया चेत्येतन्निदर्शनमात्रमुक्तम्", text: "rasādisaṅkareṇa tvanyathātvam yathā madhu madhuraṃ śleṣmāṇaṃ śamayati kaṭuvipākatayā sakaṣāyatvādraukṣyācca vātaṃ janayati śītavīryatvācca tathā yavo 'pi ānūpaudakapiśitaṃ śītamapi pittaṃ karotyuṣṇavīryatvāt tathā tailaṃ kaṭuvipākatayā ca vipākata eva baddhaviṇmūtram amlaṃ kāñjikaṃ kaphaṃ jayati rūkṣoṣṇatvāt kapitthaṃ tu raukṣyāt pittaṃ tu śītavīryatvāt āmalakaṃ pittaṃ śītavīryatvāt svādupākatayā ca kaphaṃ raukṣyāllāghavācca śaityaraukṣyalāghavaistu na vātam lavaṇaṃ saindhavaṃ svādupākatayā pittaṃ jayati lāghavāt kaphaṃ jayati kaṭukāpi śuṇṭhī snehauṣṇyasvādupākairvātaṃ kṣapayati pippalī ca laśuno 'pi snehauṣṇyagauravaiḥ palāṇḍuśca sa tu snehagauravābhyāṃ janayati śleṣmāṇam vṛddhaṃ ca mūlakaṃ svādupākatayā snigdhāni tiktāni vyāghrīviśalyārkāgarūṇyuṣṇavīryatvāt pittaṃ janayanti kaṣāyatiktaṃ mahat pañcamūlaṃ vātaṃ jayati na tu pittaṃ uṣṇavīryatvāt kaṣāyaśca kulattho 'mlapākatayā cetyetannidarśanamātramuktam" },
      { type: "verse", number: "30", sanskrit: "तस्मात् किञ्चिद्रसेन कुरुते कर्म पाकेन चापरम् द्रव्यं गुणेन वीर्येण प्रभावेणैव किञ्चन", text: "tasmāt kiñcidrasena kurute karma pākena cāparam dravyaṃ guṇena vīryeṇa prabhāveṇaiva kiñcana" },
      { type: "verse", number: "31", sanskrit: "यदद् द्रव्ये रसादीनां बलवत्त्वेन वर्तते अभिभूयेतरांस्तत्तत् कारणत्त्वं प्रपद्यते", text: "yadad dravye rasādīnāṃ balavattvena vartate abhibhūyetarāṃstattat kāraṇattvaṃ prapadyate" },
      { type: "verse", number: "32", sanskrit: "विरुद्धगुणसंयोगे भूयसाल्पं हि जीयते", text: "viruddhaguṇasaṃyoge bhūyasālpaṃ hi jīyate" },
      { type: "verse", number: "33", sanskrit: "रसं विपाकस्तौ वीर्यं प्रभावस्तान्यपोहति बलसाम्ये रसादीनामिति नैसर्गिकं बलम्", text: "rasaṃ vipākastau vīryaṃ prabhāvastānyapohati balasāmye rasādīnāmiti naisargikaṃ balam" },
      { type: "verse", number: "34", sanskrit: "विरुद्धा अपि चान्योन्यं रसाद्याः कार्यसाधने नावश्यं स्युर्विघाताय गुणदोषा मिथो यथा", text: "viruddhā api cānyonyaṃ rasādyāḥ kāryasādhane nāvaśyaṃ syurvighātāya guṇadoṣā mitho yathā" },
      { type: "verse", number: "35", sanskrit: "रसवीर्यप्रभृतयो भूतोत्कर्षापकर्षतः एकरूपा विरूपा वा द्रव्यं समधिशेरते", text: "rasavīryaprabhṛtayo bhūtotkarṣāpakarṣataḥ ekarūpā virūpā vā dravyaṃ samadhiśerate" },
      { type: "verse", number: "36", sanskrit: "माधुर्यशैत्यपैच्छिल्यस्नेहगौरवमन्दताः सह वृत्त्या स्थिताः क्षीरे नत्वानूपौदकामिषे", text: "mādhuryaśaityapaicchilyasnehagauravamandatāḥ saha vṛttyā sthitāḥ kṣīre natvānūpaudakāmiṣe" },
      { type: "verse", number: "37", sanskrit: "गुणा द्रव्येषु ये चोक्तास्त एव तनुदोषयोः स्थितिवृद्धिक्षयास्तस्मात्तेषां हि द्रव्यहेतुकाः", text: "guṇā dravyeṣu ye coktāsta eva tanudoṣayoḥ sthitivṛddhikṣayāstasmātteṣāṃ hi dravyahetukāḥ" },
      { type: "verse", number: "38", sanskrit: "रसं विद्यान्निपातेन तेनाधिवसनेन च वीर्यं विपाकं द्रव्याणां कर्मणः परिनिष्ठया", text: "rasaṃ vidyānnipātena tenādhivasanena ca vīryaṃ vipākaṃ dravyāṇāṃ karmaṇaḥ pariniṣṭhayā" },
      { type: "verse", number: "39", sanskrit: "मधुरस्कन्धनिर्दिष्टघृततैलगुडादिषु गुणास्वादादीभेदेन रसषट्कं न युज्यते", text: "madhuraskandhanirdiṣṭaghṛtatailaguḍādiṣu guṇāsvādādībhedena rasaṣaṭkaṃ na yujyate" },
      { type: "verse", number: "40", sanskrit: "अस्तु भेदादसङ्ख्यत्वमैक्यं वास्वादलक्षणात् भूतोत्कर्षापकर्षेण भेदो यो ऽल्पेन कल्प्यते", text: "astu bhedādasaṅkhyatvamaikyaṃ vāsvādalakṣaṇāt bhūtotkarṣāpakarṣeṇa bhedo yo 'lpena kalpyate" },
      { type: "verse", number: "41", sanskrit: "सङ्कीर्णत्वात् फले चासौ तुल्यत्वान्न विवक्ष्यते गुर्वादीनां विशेषे ऽपि स्वजातेरनतिक्रमात्", text: "saṅkīrṇatvāt phale cāsau tulyatvānna vivakṣyate gurvādīnāṃ viśeṣe 'pi svajāteranatikramāt" },
      { type: "verse", number: "42", sanskrit: "सङ्ख्याभेदो यथा नास्ति रसानामपि स क्रमः दृष्टं मुखोपलेपादि यत्सर्वेषु घृतादिषु", text: "saṅkhyābhedo yathā nāsti rasānāmapi sa kramaḥ dṛṣṭaṃ mukhopalepādi yatsarveṣu ghṛtādiṣu" },
      { type: "verse", number: "43", sanskrit: "न च तद्दाडिमाद्येषु षडेवातो रसाः स्मृताः आनन्त्यैकत्वयोश्च स्यान्न विचित्रार्थतन्त्रणम्", text: "na ca taddāḍimādyeṣu ṣaḍevāto rasāḥ smṛtāḥ ānantyaikatvayośca syānna vicitrārthatantraṇam" },
      { type: "verse", number: "44", sanskrit: "गुर्वाअंद्या वीर्यमुच्यन्ते शक्तिमन्तो ऽन्यथागुणाः परसामर्थ्यहीनत्वात् गुणा एवेतरे गुणाः", text: "gurvāaṃdyā vīryamucyante śaktimanto 'nyathāguṇāḥ parasāmarthyahīnatvāt guṇā evetare guṇāḥ" },
      { type: "verse", number: "45", sanskrit: "यथारसं जगुः पाकान् षट् केचित्तदसाम्प्रतम् यत्स्वादुर्व्रीहिरम्लत्वं न चाम्लमपि दाडिमम्", text: "yathārasaṃ jaguḥ pākān ṣaṭ kecittadasāmpratam yatsvādurvrīhiramlatvaṃ na cāmlamapi dāḍimam" },
      { type: "verse", number: "46", sanskrit: "याति तैलं च कटुतां कटुकापि न पिप्पली यथारसत्वे पाकानां न स्यादेवं विपर्ययः", text: "yāti tailaṃ ca kaṭutāṃ kaṭukāpi na pippalī yathārasatve pākānāṃ na syādevaṃ viparyayaḥ" },
      { type: "verse", number: "47", sanskrit: "यस्मादृद्ष्टो यवः स्यादुर्गुरुरप्यनिलप्रदः दीपनं शीतमप्याज्यं वसोष्णाप्यग्निसादिनी", text: "yasmādṛdṣṭo yavaḥ syādurgururapyanilapradaḥ dīpanaṃ śītamapyājyaṃ vasoṣṇāpyagnisādinī" },
      { type: "verse", number: "48", sanskrit: "कटुपाको ऽपि पित्तघ्नो मुद्गो माषस्तु पित्तलः स्वादुपाको ऽपि चलकृत् स्निग्धोष्णं गुरु फाणितम्", text: "kaṭupāko 'pi pittaghno mudgo māṣastu pittalaḥ svādupāko 'pi calakṛt snigdhoṣṇaṃ guru phāṇitam" },
      { type: "verse", number: "49", sanskrit: "रसः स्वादुर्यथा चैतत्तथान्येष्वपि दृश्यते वातलं कफपित्तघ्नमम्लमप्याक्षकीफलम्", text: "rasaḥ svāduryathā caitattathānyeṣvapi dṛśyate vātalaṃ kaphapittaghnamamlamapyākṣakīphalam" },
      { type: "verse", number: "50", sanskrit: "कुरुते दधि गुर्वेव वह्निं पारावतं न तु कपित्थं दाडिमं साम्लं ग्राहि नामलकीफलम्", text: "kurute dadhi gurveva vahniṃ pārāvataṃ na tu kapitthaṃ dāḍimaṃ sāmlaṃ grāhi nāmalakīphalam" },
      { type: "verse", number: "51", sanskrit: "कषाया ग्राहिणी शीता धातकी न हरीतकी अप्रधानाः पृथक् तस्माद्रसाद्याः संश्रितास्तुते", text: "kaṣāyā grāhiṇī śītā dhātakī na harītakī apradhānāḥ pṛthak tasmādrasādyāḥ saṃśritāstute" },
      { type: "verse", number: "52", sanskrit: "प्रभावश्च यतो द्रव्ये द्रव्यं श्रेष्ठमतो मतम् रसादिसाम्ये यत् कर्म विशिष्टं तत् प्रभावजम्", text: "prabhāvaśca yato dravye dravyaṃ śreṣṭhamato matam rasādisāmye yat karma viśiṣṭaṃ tat prabhāvajam" },
      { type: "verse", number: "53", sanskrit: "दन्ती रसाद्यैस्तुल्यापि चित्रकस्य विरेचनी मधुकस्य च मृद्वीका घृतं क्षीरस्य दीपनम्", text: "dantī rasādyaistulyāpi citrakasya virecanī madhukasya ca mṛdvīkā ghṛtaṃ kṣīrasya dīpanam" },
      { type: "verse", number: "54", sanskrit: "कटुपाकरसस्निग्धगुरुत्वैः कफवातजित् लशुनो वातकफकृन्न तु तैरेव यद्गुणैः", text: "kaṭupākarasasnigdhagurutvaiḥ kaphavātajit laśuno vātakaphakṛnna tu taireva yadguṇaiḥ" },
      { type: "verse", number: "55", sanskrit: "मिथो विरुद्धान् वातादीन् लोहिताद्या जयन्ति यत् कुर्वन्ति यवकाद्याश्च तत्प्रभावविजृम्भितम्", text: "mitho viruddhān vātādīn lohitādyā jayanti yat kurvanti yavakādyāśca tatprabhāvavijṛmbhitam" },
      { type: "verse", number: "56", sanskrit: "शिरीषादिर्विषं हन्ति स्वप्नाद्यं तद्विवृद्धये मणिमन्त्रौषधीनां च यत् कर्मविविधात्मकम्", text: "śirīṣādirviṣaṃ hanti svapnādyaṃ tadvivṛddhaye maṇimantrauṣadhīnāṃ ca yat karmavividhātmakam" },
      { type: "verse", number: "57", sanskrit: "शल्याहरणपुञ्जन्मरक्षायुर्द्धीवशादिकम् दर्शनाद्यैरपि विषं यन्नियच्छति चागदः", text: "śalyāharaṇapuñjanmarakṣāyurddhīvaśādikam darśanādyairapi viṣaṃ yanniyacchati cāgadaḥ" },
      { type: "verse", number: "58", sanskrit: "विरेचयति यद् वृष्यमाशु शुक्रं करोति वा ऊर्ध्वाधोभागिकं यच्च द्रव्यं यच्छमनादि च", text: "virecayati yad vṛṣyamāśu śukraṃ karoti vā ūrdhvādhobhāgikaṃ yacca dravyaṃ yacchamanādi ca" },
      { type: "verse", number: "59", sanskrit: "मात्रादि प्राप्य तत्तच्च यत् प्रपञ्चेन वर्णितम् तच्च प्रभावजं सर्वमतो ऽचिन्त्यः स उच्यते", text: "mātrādi prāpya tattacca yat prapañcena varṇitam tacca prabhāvajaṃ sarvamato 'cintyaḥ sa ucyate" },
      { type: "verse", number: "60", sanskrit: "रसेन वीर्येण गुणैश्च कर्म द्रव्यं विपाकेन च यद्विदध्यात् सद्यो ऽन्यथा तत् कुरुते प्रभावाद्धेतोरतस्तत्र न गोचरो ऽस्ति", text: "rasena vīryeṇa guṇaiśca karma dravyaṃ vipākena ca yadvidadhyāt sadyo 'nyathā tat kurute prabhāvāddhetoratastatra na gocaro 'sti" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 18,
    lang: "sa",
    content: [
      { type: "heading", heading: "Расаяна видхи — омолаживающая терапия" },
      { type: "text", text: "Глава 18 Сутрастханы Астанга-санграхи посвящена теме «омолаживающая терапия». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो रसभेदीयमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto rasabhedīyamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "रसः खल्वाप्यः प्रागव्यक्तश्च स षडृतुकत्वात् कालस्य महाभूतगुणैरूनातिरिक्तैः संसृष्टो विषमं विदग्धः षोढा पृथग्विपरिणमते मधुरादिभेदेन", text: "rasaḥ khalvāpyaḥ prāgavyaktaśca sa ṣaḍṛtukatvāt kālasya mahābhūtaguṇairūnātiriktaiḥ saṃsṛṣṭo viṣamaṃ vidagdhaḥ ṣoḍhā pṛthagvipariṇamate madhurādibhedena" },
      { type: "verse", number: "3", sanskrit: "तत्र भूजलयोर्बाहुल्यान्मधुरो रसः भूतेजसोरम्लः जलतेजसोर्लवणः वाय्वाकाशयोस्तिक्तः वायुतेजसोः कटुकः वायूर्व्योः कषायः", text: "tatra bhūjalayorbāhulyānmadhuro rasaḥ bhūtejasoramlaḥ jalatejasorlavaṇaḥ vāyvākāśayostiktaḥ vāyutejasoḥ kaṭukaḥ vāyūrvyoḥ kaṣāyaḥ" },
      { type: "verse", number: "4", sanskrit: "तेषां स्वादुरास्वाद्यमानो मुखमुपलिम्पतीन्द्रियाणि प्रसादयति देहं प्रह्लादयति षट्पदपिपीलिकादीनामपीष्टतमः अम्लस्तु जिह्वामुद्वेजयत्युरःकण्ठं विदहति मुखं स्रावयत्यक्षिभ्रुवं सङ्कोचयति दशनान् हर्षयति रोमाणि च लवणो मुखं विष्यन्दयति कण्ठकपोलं विदहति अन्नं प्ररोचयति तिक्तो विशदयति वदनं विशोधयति कण्ठं प्रतिहन्ति रसनाम् कटुको भृशमुद्वेजयति जिह्वाग्रं चिमिचिमायति कण्ठकपोलं स्रावयति मुखाक्षिनासिकं विदहति देहम् कषायस्तु जडयति जिह्वां बध्नाति कण्ठं पीडयति हृदयम्", text: "teṣāṃ svādurāsvādyamāno mukhamupalimpatīndriyāṇi prasādayati dehaṃ prahlādayati ṣaṭpadapipīlikādīnāmapīṣṭatamaḥ amlastu jihvāmudvejayatyuraḥkaṇṭhaṃ vidahati mukhaṃ srāvayatyakṣibhruvaṃ saṅkocayati daśanān harṣayati romāṇi ca lavaṇo mukhaṃ viṣyandayati kaṇṭhakapolaṃ vidahati annaṃ prarocayati tikto viśadayati vadanaṃ viśodhayati kaṇṭhaṃ pratihanti rasanām kaṭuko bhṛśamudvejayati jihvāgraṃ cimicimāyati kaṇṭhakapolaṃ srāvayati mukhākṣināsikaṃ vidahati deham kaṣāyastu jaḍayati jihvāṃ badhnāti kaṇṭhaṃ pīḍayati hṛdayam" },
      { type: "verse", number: "5", sanskrit: "तत्र मधुरो रसो जन्मप्रभृतिसात्म्यात् सर्वधातुविवर्धनः आयुष्यो बालवृद्धक्षतक्षीणबलवर्णेन्द्रियत्वक्केशकण्ठहितः प्रीणनो बृंहणो जीवनस्तर्पणः स्थैर्यसन्धानः स्तन्यकरो वातपित्तविषदाहमूर्छातृष्णाप्रशमनः स्निग्धः शीतो मृदुर्गुरुश्च", text: "tatra madhuro raso janmaprabhṛtisātmyāt sarvadhātuvivardhanaḥ āyuṣyo bālavṛddhakṣatakṣīṇabalavarṇendriyatvakkeśakaṇṭhahitaḥ prīṇano bṛṃhaṇo jīvanastarpaṇaḥ sthairyasandhānaḥ stanyakaro vātapittaviṣadāhamūrchātṛṣṇāpraśamanaḥ snigdhaḥ śīto mṛdurguruśca" },
      { type: "verse", number: "6", sanskrit: "एवंगुणो ऽपि स सदात्युपयुज्यमानः स्थौल्याग्निसादगुरुतालसकातिन्द्रियाः श्वासप्रमेहगलरोगाविसंज्ञतास्यमाधुर्यलोचनगलार्बुदगण्डमालाः", text: "evaṃguṇo 'pi sa sadātyupayujyamānaḥ sthaulyāgnisādagurutālasakātindriyāḥ śvāsapramehagalarogāvisaṃjñatāsyamādhuryalocanagalārbudagaṇḍamālāḥ" },
      { type: "verse", number: "7", sanskrit: "छर्द्युदर्दमूर्द्धरुक्कासपीनसक्रिमीन् श्लीपदज्वरोदरष्ठीवनानि चावहेत्", text: "chardyudardamūrddharukkāsapīnasakrimīn ślīpadajvarodaraṣṭhīvanāni cāvahet" },
      { type: "verse", number: "8", sanskrit: "अम्लो ऽनिलनिबर्हणो ऽनुलोमनः कोष्ठविदाही रक्तपित्तकृदुष्णवीर्यः शीतस्पर्शोबोधयतीन्द्रियाणि रोचनः पाचनो दीपनो बृंहणस्तर्पणः प्रीणनः क्लेदनो व्यवायी लघुः स्निग्धो हृद्यश्च", text: "amlo 'nilanibarhaṇo 'nulomanaḥ koṣṭhavidāhī raktapittakṛduṣṇavīryaḥ śītasparśobodhayatīndriyāṇi rocanaḥ pācano dīpano bṛṃhaṇastarpaṇaḥ prīṇanaḥ kledano vyavāyī laghuḥ snigdho hṛdyaśca" },
      { type: "verse", number: "9", sanskrit: "जनयति शिथिलत्वं सेवितः सोतिदेहे कफविलयनकण्डूपाण्डुतादृग्विघातान् क्षतविहितविसर्पं रक्तपित्तं पिपासां श्वयथुमपि कृशानां तैजसत्वात् भ्रमं च", text: "janayati śithilatvaṃ sevitaḥ sotidehe kaphavilayanakaṇḍūpāṇḍutādṛgvighātān kṣatavihitavisarpaṃ raktapittaṃ pipāsāṃ śvayathumapi kṛśānāṃ taijasatvāt bhramaṃ ca" },
      { type: "verse", number: "10", sanskrit: "लवणः स्तम्भबन्धसङ्घातविध्मापनः सर्वरसप्रत्यनीको दीपनो रोचनः पाचनः क्लेदनः शोषणः स्नेहनः स्वेदनो भेदनः छेदनः सरो व्यवायी विकाषी हरति पवनं विष्यन्दयति कफं विशोधयति स्रोतांसि नातिगुरुः स्निग्धतीक्ष्णोष्णश्च", text: "lavaṇaḥ stambhabandhasaṅghātavidhmāpanaḥ sarvarasapratyanīko dīpano rocanaḥ pācanaḥ kledanaḥ śoṣaṇaḥ snehanaḥ svedano bhedanaḥ chedanaḥ saro vyavāyī vikāṣī harati pavanaṃ viṣyandayati kaphaṃ viśodhayati srotāṃsi nātiguruḥ snigdhatīkṣṇoṣṇaśca" },
      { type: "verse", number: "11", sanskrit: "खलतिपलिततृष्णातापमूर्च्छाविसर्पश्वयथुकिटिभकोष्ठाक्षेपरोधास्रपित्तम् क्षतविषमदवृद्धिं वातरक्तं करोति क्षपयति बलभोजः सोति वा सेवनेन", text: "khalatipalitatṛṣṇātāpamūrcchāvisarpaśvayathukiṭibhakoṣṭhākṣeparodhāsrapittam kṣataviṣamadavṛddhiṃ vātaraktaṃ karoti kṣapayati balabhojaḥ soti vā sevanena" },
      { type: "verse", number: "12", sanskrit: "तिक्तः स्वयमरोचिष्णुररुचिविषकृमिमूर्च्छोत्क्लेदज्वरदाहतृटकुष्ठकण्डूहरः क्लेदमेदोवसामज्जविण्मूत्रपित्तश्लेष्मोपशोषणो दीपनः पाचनो लेखनः स्तन्यकण्ठविशोधनो मेध्यो नातिरूक्षः शीतो लघुश्च", text: "tiktaḥ svayamarociṣṇuraruciviṣakṛmimūrcchotkledajvaradāhatṛṭakuṣṭhakaṇḍūharaḥ kledamedovasāmajjaviṇmūtrapittaśleṣmopaśoṣaṇo dīpanaḥ pācano lekhanaḥ stanyakaṇṭhaviśodhano medhyo nātirūkṣaḥ śīto laghuśca" },
      { type: "verse", number: "13", sanskrit: "धातुबलक्षयमूर्च्छाग्लानिभ्रमवातरोगपरुषत्वम् खरविशदरौक्ष्यभावैः सोति समासेवितःकुर्यात्", text: "dhātubalakṣayamūrcchāglānibhramavātarogaparuṣatvam kharaviśadaraukṣyabhāvaiḥ soti samāsevitaḥkuryāt" },
      { type: "verse", number: "14", sanskrit: "कटुको ऽलसकश्वयथूदर्दस्थौल्याभिष्यन्दकृमिवक्त्ररोगविषकुष्ठकण्डूप्रसाधनो व्रणावसादनः स्नेह क्लेदशोषणो रोचनः पाचनो दीपनो लेखनः शोधनः शोषयत्यन्नं स्फुटयतीन्द्रियाणि भिनत्ति शोणितसंघातं छिन्नत्ति बन्धान् विवृणोति स्रोतांसि क्षपयति श्लेष्माणं लघुरूक्षतीक्ष्णोष्णश्च", text: "kaṭuko 'lasakaśvayathūdardasthaulyābhiṣyandakṛmivaktrarogaviṣakuṣṭhakaṇḍūprasādhano vraṇāvasādanaḥ sneha kledaśoṣaṇo rocanaḥ pācano dīpano lekhanaḥ śodhanaḥ śoṣayatyannaṃ sphuṭayatīndriyāṇi bhinatti śoṇitasaṃghātaṃ chinnatti bandhān vivṛṇoti srotāṃsi kṣapayati śleṣmāṇaṃ laghurūkṣatīkṣṇoṣṇaśca" },
      { type: "verse", number: "15", sanskrit: "कुरुते ऽतिनिषोवितः स तृष्णामदमूर्च्छावमिमोहदेहसादान् बलशुक्रगलोपशोषकम्पभ्रमतापग्लपनातिकर्शनानि", text: "kurute 'tiniṣovitaḥ sa tṛṣṇāmadamūrcchāvamimohadehasādān balaśukragalopaśoṣakampabhramatāpaglapanātikarśanāni" },
      { type: "verse", number: "16", sanskrit: "करचरणपार्श्वपृष्ठप्रभृतिष्वनिलस्यकोपमतितीव्रम् सङ्काचतोदभेदैर्वाव्यग्निगुणाधिकत्वेन", text: "karacaraṇapārśvapṛṣṭhaprabhṛtiṣvanilasyakopamatitīvram saṅkācatodabhedairvāvyagniguṇādhikatvena" },
      { type: "verse", number: "17", sanskrit: "कषायो बलासं सपित्तं सरक्तं निहन्त्याशु बध्नाति वर्चोतिरूक्षः गुरुस्त्वक्सवर्णत्वकृत् क्लेदशोषी हिमः प्रीणनो रोपणो लेखनश्च", text: "kaṣāyo balāsaṃ sapittaṃ saraktaṃ nihantyāśu badhnāti varcotirūkṣaḥ gurustvaksavarṇatvakṛt kledaśoṣī himaḥ prīṇano ropaṇo lekhanaśca" },
      { type: "verse", number: "18", sanskrit: "अत्यभ्यासात् सो ऽपि शुक्रोपरोधं तृष्णाध्मानस्तम्भविष्टम्भकार्श्यम् स्रोतोबन्धं वातविण्मूत्रसङ्गं पक्षाघाताक्षेपकादींश्च कुर्यात्", text: "atyabhyāsāt so 'pi śukroparodhaṃ tṛṣṇādhmānastambhaviṣṭambhakārśyam srotobandhaṃ vātaviṇmūtrasaṅgaṃ pakṣāghātākṣepakādīṃśca kuryāt" },
      { type: "verse", number: "19", sanskrit: "अथ मधुरस्कन्धो घृतमधुतैलक्षीरमेदोमज्जेक्षुविकृतिद्राक्षाक्षोडखर्जूरमोचचोचपनससिञ्चतिकाप्रियालराजादनखर्यूरीतालमस्तककाश्मर्यमधूकपरूषकतामलकीवीराविदारीशतावरीतुगाक्षीरीजीवकर्षभक्षीरशुक्लामधूलिकात्मगुप्ताबलातिबलाविश्वदेवासहदेवासालपर्णीमुद्गपर्णीपृश्निपर्णीमषपर्णीमहासहाक्षुद्रसहाऋद्धिवृद्धिश्रावणीच्छत्रातिच्छत्रर्श्यर्पोक्ताश्व गन्धाश्वदंष्ट्रामृणालिकापुष्करबीजशृङ्गाटककशेरुकतककनकबिम्बीप्रपौण्डरीकप्रभृतीनि जीवनीयो गणस्तृणपञ्चमूलं च", text: "atha madhuraskandho ghṛtamadhutailakṣīramedomajjekṣuvikṛtidrākṣākṣoḍakharjūramocacocapanasasiñcatikāpriyālarājādanakharyūrītālamastakakāśmaryamadhūkaparūṣakatāmalakīvīrāvidārīśatāvarītugākṣīrījīvakarṣabhakṣīraśuklāmadhūlikātmaguptābalātibalāviśvadevāsahadevāsālaparṇīmudgaparṇīpṛśniparṇīmaṣaparṇīmahāsahākṣudrasahāṛddhivṛddhiśrāvaṇīcchatrāticchatrarśyarpoktāśva gandhāśvadaṃṣṭrāmṛṇālikāpuṣkarabījaśṛṅgāṭakakaśerukatakakanakabimbīprapauṇḍarīkaprabhṛtīni jīvanīyo gaṇastṛṇapañcamūlaṃ ca" },
      { type: "verse", number: "20", sanskrit: "अम्लद्रव्यस्कन्धो दाडिमामलकाम्राम्रातककोशाम्रमातुलुङ्गवृक्षाम्लाम्लीकाम्लेवतसकुवललकुचपारावतभव्यकरमर्दधवधन्वनकोलबदरैरावतकपित्थदन्तशठप्राचीनामलकनारङ्गतिलकण्टकरूप्यदधिमस्तुतक्रधान्याम्लमद्यशुक्तप्रभृतीनि", text: "amladravyaskandho dāḍimāmalakāmrāmrātakakośāmramātuluṅgavṛkṣāmlāmlīkāmlevatasakuvalalakucapārāvatabhavyakaramardadhavadhanvanakolabadarairāvatakapitthadantaśaṭhaprācīnāmalakanāraṅgatilakaṇṭakarūpyadadhimastutakradhānyāmlamadyaśuktaprabhṛtīni" },
      { type: "verse", number: "21", sanskrit: "लवणद्रव्यस्कन्धः सैन्धवादीनि क्षारान्तानि त्रपुसीसप्रभृतीनि", text: "lavaṇadravyaskandhaḥ saindhavādīni kṣārāntāni trapusīsaprabhṛtīni" },
      { type: "verse", number: "22", sanskrit: "तिक्तद्रव्यस्कन्धो ऽगरुतगरोशीरवालकचन्दननलदकृतमालनक्तमालापामार्गहरिद्राद्वयमुस्तमूर्वामदनफलाजशृङ्गीत्रायमाणाकटुकाकिराततिक्तककरवीरविशालासुषव्यतिविषायवासकज्योतिष्मतीपाठाविकङ्कतार्ककाकमाचीवचावरणवत्सकवैजयन्तीवेतससप्तपर्णसोमवल्कसुमनःकांस्यलोहप्रभृतीनि पटोलादिश्च शाकवर्गः", text: "tiktadravyaskandho 'garutagarośīravālakacandananaladakṛtamālanaktamālāpāmārgaharidrādvayamustamūrvāmadanaphalājaśṛṅgītrāyamāṇākaṭukākirātatiktakakaravīraviśālāsuṣavyativiṣāyavāsakajyotiṣmatīpāṭhāvikaṅkatārkakākamācīvacāvaraṇavatsakavaijayantīvetasasaptaparṇasomavalkasumanaḥkāṃsyalohaprabhṛtīni paṭolādiśca śākavargaḥ" },
      { type: "verse", number: "23", sanskrit: "कटुकद्रव्यस्कन्धो मरिचहिङ्गुतेजोवतीहस्तिपिप्पलीविडङ्गभल्लातकास्थिमूलकसर्षपलशुनपलाण्डुकरञ्जमनश्शिलालदेवदारुकुष्ठैलासुरसचोरकहरेणुकामूत्रपित्तप्रभृतीनि कुठेरादिश्च हरितवर्गः पञ्चकोलं च", text: "kaṭukadravyaskandho maricahiṅgutejovatīhastipippalīviḍaṅgabhallātakāsthimūlakasarṣapalaśunapalāṇḍukarañjamanaśśilāladevadārukuṣṭhailāsurasacorakahareṇukāmūtrapittaprabhṛtīni kuṭherādiśca haritavargaḥ pañcakolaṃ ca" },
      { type: "verse", number: "24", sanskrit: "कषायद्रव्यस्कन्धो हरीतकीप्रियङ्ग्वनन्ताक्षौद्रलोध्रकट्फलधवधन्वनधात्रीफलधातकीपुष्पपद्मापद्मकपद्मपुष्पनागकेसरकुमुकोत्पलतुङ्गतिन्दुककदम्बोदुम्बरजम्ब्वाम्रप्लक्षवटबिभीतकविकङ्कतजम्ब्वाम्रास्थ्यामकपित्थाश्वत्थमोचरससमङ्गासोमवल्कसप्तपर्णस्यन्दनासनसल्लकीसालतालप्रियालैलावास्तुकपरिपेलवजिङ्गिणीबदरीखदिरकदरारिमेदकाशकशेरुकवंशाश्मन्तकाशोकशिरीषशिंशपापलाशशमशिणशङ्खनाभिमेषशृङ्गीतरुणखर्ज्जूरस्फूर्ज्जकभूर्ज्जार्जुनाजकर्णवरणप्रियालमुक्ताञ्जनैगरिकबिसमृणालप्रभृतीनि", text: "kaṣāyadravyaskandho harītakīpriyaṅgvanantākṣaudralodhrakaṭphaladhavadhanvanadhātrīphaladhātakīpuṣpapadmāpadmakapadmapuṣpanāgakesarakumukotpalatuṅgatindukakadambodumbarajambvāmraplakṣavaṭabibhītakavikaṅkatajambvāmrāsthyāmakapitthāśvatthamocarasasamaṅgāsomavalkasaptaparṇasyandanāsanasallakīsālatālapriyālailāvāstukaparipelavajiṅgiṇībadarīkhadirakadarārimedakāśakaśerukavaṃśāśmantakāśokaśirīṣaśiṃśapāpalāśaśamaśiṇaśaṅkhanābhimeṣaśṛṅgītaruṇakharjjūrasphūrjjakabhūrjjārjunājakarṇavaraṇapriyālamuktāñjanaigarikabisamṛṇālaprabhṛtīni" },
      { type: "verse", number: "25", sanskrit: "तत्र प्रायो मधुरं श्लेष्मलमन्यत्र पुराणशालियवगोधूममुद्गमधुशर्कराजाङ्गलमांसात् प्रायो ऽम्लं पित्तलमन्यत्र दाडिमामलकात् प्रायोलवणमचक्षुष्यमन्यत्र सैन्धवात् प्रायस्तिक्तकटुकं वातलमवृष्यं चान्यत्रामृतापटोलीनागरपिप्पलीलशुनात् प्रायः कषायं शीतं स्तम्भनं चान्यत्र हरीतक्याः", text: "tatra prāyo madhuraṃ śleṣmalamanyatra purāṇaśāliyavagodhūmamudgamadhuśarkarājāṅgalamāṃsāt prāyo 'mlaṃ pittalamanyatra dāḍimāmalakāt prāyolavaṇamacakṣuṣyamanyatra saindhavāt prāyastiktakaṭukaṃ vātalamavṛṣyaṃ cānyatrāmṛtāpaṭolīnāgarapippalīlaśunāt prāyaḥ kaṣāyaṃ śītaṃ stambhanaṃ cānyatra harītakyāḥ" },
      { type: "verse", number: "26", sanskrit: "इति यथास्थूलं नित्योपयोगिनां प्रधानतमानां चोपसङ्ग्रहः", text: "iti yathāsthūlaṃ nityopayogināṃ pradhānatamānāṃ copasaṅgrahaḥ" },
      { type: "verse", number: "27", sanskrit: "घृतामलकसिन्धूत्थपटोलीनागराभयाः श्रेष्ठा यथास्वं स्कन्धेषु रसदेशस्तु वक्ष्यते", text: "ghṛtāmalakasindhūtthapaṭolīnāgarābhayāḥ śreṣṭhā yathāsvaṃ skandheṣu rasadeśastu vakṣyate" },
      { type: "verse", number: "28", sanskrit: "अथ यः शिशिरपवनधरणीधरविविधवनगहननदीतटाकपल्वलोदपानकमलकुमुदकुवलयावकीर्णोरम्यः स्थिरस्निग्धभूमिर्भूरिहरिततृणो ऽतिदूरविस्तृतप्रतानप्रवालोपसंच्छन्नपादपः सस्यसरीसृपखगबहुलः श्लेष्मपित्तप्रायो गुर्वौषधिसलिलः श्लीपदगलरोगापाचींज्वराद्यामयोपद्रुतजनपदः सो ऽनूपो मधुररसयोनिः", text: "atha yaḥ śiśirapavanadharaṇīdharavividhavanagahananadītaṭākapalvalodapānakamalakumudakuvalayāvakīrṇoramyaḥ sthirasnigdhabhūmirbhūriharitatṛṇo 'tidūravistṛtapratānapravālopasaṃcchannapādapaḥ sasyasarīsṛpakhagabahulaḥ śleṣmapittaprāyo gurvauṣadhisalilaḥ ślīpadagalarogāpācīṃjvarādyāmayopadrutajanapadaḥ so 'nūpo madhurarasayoniḥ" },
      { type: "verse", number: "29", sanskrit: "यस्तु विषमविपुलसिकतास्थलबहुलो ऽतिदूरावगाढविरससलिलः क्लेशसहारोगशरीरदीर्घायुःप्रायो जनपदो ऽनूपरीतश्च स जाङ्गलः कटुकरसयोनिः अत एव चानूपसाधारणो जाङ्गलसाधारणश्च विकल्प्यः तयोराद्यो लवणाम्लयोर्योनिरितरश्चेतरयोः संयोगास्त्वेषां सप्तपञ्चाशद्भवन्ति भवन्ति चात्र", text: "yastu viṣamavipulasikatāsthalabahulo 'tidūrāvagāḍhavirasasalilaḥ kleśasahārogaśarīradīrghāyuḥprāyo janapado 'nūparītaśca sa jāṅgalaḥ kaṭukarasayoniḥ ata eva cānūpasādhāraṇo jāṅgalasādhāraṇaśca vikalpyaḥ tayorādyo lavaṇāmlayoryoniritaraścetarayoḥ saṃyogāstveṣāṃ saptapañcāśadbhavanti bhavanti cātra" },
      { type: "verse", number: "30", sanskrit: "स्वादुर्द्विकेषु पञ्चाम्लश्चतुरो लवणस्त्रयम् द्वौ तिक्तः कटुकश्चैकं याति पञ्चदशैव ते", text: "svādurdvikeṣu pañcāmlaścaturo lavaṇastrayam dvau tiktaḥ kaṭukaścaikaṃ yāti pañcadaśaiva te" },
      { type: "verse", number: "31", sanskrit: "त्रिकेषु मधुरः साम्लश्चतुरो लवणान्वितः त्रीन्युक्तस्तिक्तकेन द्वौ कटुनैकं निषेवते", text: "trikeṣu madhuraḥ sāmlaścaturo lavaṇānvitaḥ trīnyuktastiktakena dvau kaṭunaikaṃ niṣevate" },
      { type: "verse", number: "32", sanskrit: "स्वादुर्दशैवमम्लः षट् संयोगान् पूर्ववत्क्रिया लवणस्त्रीन् भजत्येकं तिक्त एवं तु विंशतिः", text: "svādurdaśaivamamlaḥ ṣaṭ saṃyogān pūrvavatkriyā lavaṇastrīn bhajatyekaṃ tikta evaṃ tu viṃśatiḥ" },
      { type: "verse", number: "33", sanskrit: "स्वादुश्चाम्लश्चतुष्केषु षट् त्रयं लवणानुगः एकं तिक्तयुतो याति दशैव मधुरो रसः", text: "svāduścāmlaścatuṣkeṣu ṣaṭ trayaṃ lavaṇānugaḥ ekaṃ tiktayuto yāti daśaiva madhuro rasaḥ" },
      { type: "verse", number: "34", sanskrit: "चत्वारो ऽम्लः पटुश्चैकं भेदाः पञ्चदशेति च एकैकस्य परित्यागात् संयोगाः पञ्चके च षट्", text: "catvāro 'mlaḥ paṭuścaikaṃ bhedāḥ pañcadaśeti ca ekaikasya parityāgāt saṃyogāḥ pañcake ca ṣaṭ" },
      { type: "verse", number: "35", sanskrit: "एकश्च षड्रसः षट् च पृथगेवं त्रिषष्टिधा ते रसानुरसतो रसभेदास्तारतम्यपरिकल्पनया च सम्भवन्ति गणनां समतीता दोषभेषजवशादुपयोज्याः", text: "ekaśca ṣaḍrasaḥ ṣaṭ ca pṛthagevaṃ triṣaṣṭidhā te rasānurasato rasabhedāstāratamyaparikalpanayā ca sambhavanti gaṇanāṃ samatītā doṣabheṣajavaśādupayojyāḥ" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 19,
    lang: "sa",
    content: [
      { type: "heading", heading: "Вришья видхи — афродизиакальная терапия" },
      { type: "text", text: "Глава 19 Сутрастханы Астанга-санграхи посвящена теме «афродизиакальная терапия». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो दोषादिविज्ञानीयमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः दोषधातुमलमूलो हि देहः तस्मात्तेषां लक्षणमुपदेक्ष्यामः तमुच्छ्वासनिश्वासोत्साहप्रस्पन्दनेन्द्रियपाटववेगप्रवर्तनादिभिर्वायुरनुगृह्णाति पक्त्यूष्माभिलाषक्षुत्पिपासाप्रभाप्रसाददर्शनमेधाशौर्यमार्दवादिभिः पित्तम् स्थैर्यस्नेहसन्धिबन्धवृषताक्षमाधीधृतिबलालौल्यादिभिः श्लेष्मा", text: "athāto doṣādivijñānīyamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ doṣadhātumalamūlo hi dehaḥ tasmātteṣāṃ lakṣaṇamupadekṣyāmaḥ tamucchvāsaniśvāsotsāhapraspandanendriyapāṭavavegapravartanādibhirvāyuranugṛhṇāti paktyūṣmābhilāṣakṣutpipāsāprabhāprasādadarśanamedhāśauryamārdavādibhiḥ pittam sthairyasnehasandhibandhavṛṣatākṣamādhīdhṛtibalālaulyādibhiḥ śleṣmā" },
      { type: "verse", number: "2", sanskrit: "तुष्टिप्रीणनरक्तपुष्टिभिस्तु रसः जीवनवर्णप्रसादनमांसपोषणैरसृक् देहलेपमलमेदःपुष्टिभिर्मांसम् नेत्रगात्रस्निग्धतास्नेहदार्ढ्यास्थिपुष्टिभिर्मेदः देहोर्ध्वताधारणमज्जपोषणाभ्यामस्थि स्नेहबलास्थिपूरणशुक्रपुष्टिभिर्मज्जा हर्षबलगर्भोत्पादनैः शुक्रम् अवष्टम्भानिलानलधारणैः शकृत् अन्नक्लेदनिर्वाहणेन मूत्रम् क्लेदत्वक्स्नेहरोमधारणैः स्वेद इति", text: "tuṣṭiprīṇanaraktapuṣṭibhistu rasaḥ jīvanavarṇaprasādanamāṃsapoṣaṇairasṛk dehalepamalamedaḥpuṣṭibhirmāṃsam netragātrasnigdhatāsnehadārḍhyāsthipuṣṭibhirmedaḥ dehordhvatādhāraṇamajjapoṣaṇābhyāmasthi snehabalāsthipūraṇaśukrapuṣṭibhirmajjā harṣabalagarbhotpādanaiḥ śukram avaṣṭambhānilānaladhāraṇaiḥ śakṛt annakledanirvāhaṇena mūtram kledatvaksneharomadhāraṇaiḥ sveda iti" },
      { type: "verse", number: "3", sanskrit: "कार्श्यकार्ष्ण्यगात्रकम्पस्फुरणोष्णकामितासंज्ञानिद्रानाशबलेन्द्रियोपघातास्थिशूलमज्जाशोषमलसङ्गाध्मानाटोपमोहदैन्यभयशोकप्रलापादिभिर्वृद्धो वायुः पीडयति पीतत्वग्ग्लानीन्द्रियदौर्बल्यौजोविस्रंसशीताभिलाषदाहतिक्तास्यतातृण्मूर्च्छाल्पनिद्रताक्रोधादिभिः पित्तम् श्वैत्यशैत्यस्थौल्यालस्यगौरवाङ्गसादस्रोतःपिधानमूर्च्छातन्द्रानिद्राश्वासकासप्रसेकहृल्लासाग्निसादसन्धिविश्लेषादिभिः श्लेष्मा", text: "kārśyakārṣṇyagātrakampasphuraṇoṣṇakāmitāsaṃjñānidrānāśabalendriyopaghātāsthiśūlamajjāśoṣamalasaṅgādhmānāṭopamohadainyabhayaśokapralāpādibhirvṛddho vāyuḥ pīḍayati pītatvagglānīndriyadaurbalyaujovisraṃsaśītābhilāṣadāhatiktāsyatātṛṇmūrcchālpanidratākrodhādibhiḥ pittam śvaityaśaityasthaulyālasyagauravāṅgasādasrotaḥpidhānamūrcchātandrānidrāśvāsakāsaprasekahṛllāsāgnisādasandhiviśleṣādibhiḥ śleṣmā" },
      { type: "verse", number: "4", sanskrit: "प्रसेकारोचकास्यवैरस्यहृल्लासस्रोतोरोधस्वादुद्वेषाङ्गमर्दादिभिरन्यैश्च श्लेष्मविकारप्रायैः रसः कुष्ठविसर्पपिटकासृग्दराक्षिमुखमेढ्रगुददाहगुल्मविद्रधिप्लीहव्यङ्गकामलाग्निनाशतमःप्रवेशरक्ताङ्गनेत्रतावातरक्तपित्तादिभिरन्यैश्च पित्तविकारप्रायैरसृक् गलगण्ड गण्डमालार्बुदग्रन्थितालुजिह्वाकण्ठरोगस्फिग्गलौष्ठबाहूदरोरुजङ्घागौरववृद्धिभिः श्लेष्मरक्तविकारप्रायैश्च मांसम् प्रमेहपूर्वरूपैः स्थौल्योपद्रवैश्चान्यैरपि श्लेष्मरक्तमांसविकारप्रायैर्मेदः अध्यस्थिभिरधिदन्तैश्चास्थि नेत्राङ्गरक्तगौरवैः पर्वसु च स्थूलमूलारुर्भिर्मज्जा अतिस्त्रीकामताशुक्राश्मरीसम्भवाभ्यां शुक्राधिक्यम् कुक्षिशूलाटोपगौरवैः शकृदाधिक्यम् बस्तितोदाध्मानैर्मूत्राधिक्यम् कण्डूदौर्गन्ध्यैः स्वेदः अन्ये ऽपि च दूषिकादिमला बाहुल्यद्रवताकण्डूगौरवैः", text: "prasekārocakāsyavairasyahṛllāsasrotorodhasvādudveṣāṅgamardādibhiranyaiśca śleṣmavikāraprāyaiḥ rasaḥ kuṣṭhavisarpapiṭakāsṛgdarākṣimukhameḍhragudadāhagulmavidradhiplīhavyaṅgakāmalāgnināśatamaḥpraveśaraktāṅganetratāvātaraktapittādibhiranyaiśca pittavikāraprāyairasṛk galagaṇḍa gaṇḍamālārbudagranthitālujihvākaṇṭharogasphiggalauṣṭhabāhūdarorujaṅghāgauravavṛddhibhiḥ śleṣmaraktavikāraprāyaiśca māṃsam pramehapūrvarūpaiḥ sthaulyopadravaiścānyairapi śleṣmaraktamāṃsavikāraprāyairmedaḥ adhyasthibhiradhidantaiścāsthi netrāṅgaraktagauravaiḥ parvasu ca sthūlamūlārurbhirmajjā atistrīkāmatāśukrāśmarīsambhavābhyāṃ śukrādhikyam kukṣiśūlāṭopagauravaiḥ śakṛdādhikyam bastitodādhmānairmūtrādhikyam kaṇḍūdaurgandhyaiḥ svedaḥ anye 'pi ca dūṣikādimalā bāhulyadravatākaṇḍūgauravaiḥ" },
      { type: "verse", number: "5", sanskrit: "प्रसेकारुचिहृल्लाससंज्ञामोहाल्पवाक्चेष्टताप्रहषाङ्गसादाग्निवैषम्यादिभिः क्षीणो वायुः पीडयति स्तम्भशैत्यानियततोदारोचकाविपाकाङ्गपारुष्यकम्पगौरवनखनयनशौक्ल्यादिभिः पित्तम् भ्रमोद्वेष्टनानिद्राङ्गमर्दपरिप्लोषतोददवदाहस्फोटनवेपनधूमायनसन्धिशैथिल्यहृदयद्रवश्लेष्माशयशून्यतादिभिः श्लेष्मा", text: "prasekārucihṛllāsasaṃjñāmohālpavākceṣṭatāprahaṣāṅgasādāgnivaiṣamyādibhiḥ kṣīṇo vāyuḥ pīḍayati stambhaśaityāniyatatodārocakāvipākāṅgapāruṣyakampagauravanakhanayanaśauklyādibhiḥ pittam bhramodveṣṭanānidrāṅgamardapariploṣatodadavadāhasphoṭanavepanadhūmāyanasandhiśaithilyahṛdayadravaśleṣmāśayaśūnyatādibhiḥ śleṣmā" },
      { type: "verse", number: "6", sanskrit: "शब्दासहत्वहृदयद्रवकम्पशोषशूलशून्यतास्पन्दनघट्टनैरल्पयापि च चेष्टया श्रमतर्षाभ्यां रसः त्वग्रौक्ष्याम्लशीताभिलाषसिराशैथिल्यैरसृक् स्फिग्गण्डादिशुष्कतातोदरौक्ष्याक्षग्लानिसन्धिस्फोटनधमनीशैथिल्यैर्मांसम् प्लीहवृद्धिकटीस्वापसन्धिशून्यताङ्गरौक्ष्यकार्श्यश्रमशोषमेदुरमांसाभिलाषैर्मांसक्षयोक्तैश्च मेदः दन्तनखरोमकेशशातनरौक्ष्यपारुष्यसन्धिशैथिल्यास्थितोदास्थिबद्धमांसाभिलाषैरस्थि अस्थिसौषिर्यनिस्तोददौर्बल्यभ्रमतमोदर्शनैर्मज्जा श्रमदौर्बल्यास्यशोषतिमिरदर्शनाङ्गमर्दपाण्डुतासदनक्लैब्यमुष्कतोदमेढ्रधूमायनैश्चिराच्च निषेकेण सरक्तनिषेकेण वा शुक्रम् सशब्दस्य वायोः कुक्षौ तिर्यगूर्ध्वं च भ्रमणेनान्त्रवेष्टनेन पार्श्वहृदयपीडनेनाल्पतया च शकृत् बस्तिनिस्तोदमुखशोषकृछ्राल्पविवर्णमूत्रतादिभिः सरुधिरमूत्रतया वा मूत्रम् स्तब्धरोमकूपतारोमच्यवनत्वक्परिपाटनस्वापपारुष्यस्वेदनाशैः स्वेदः", text: "śabdāsahatvahṛdayadravakampaśoṣaśūlaśūnyatāspandanaghaṭṭanairalpayāpi ca ceṣṭayā śramatarṣābhyāṃ rasaḥ tvagraukṣyāmlaśītābhilāṣasirāśaithilyairasṛk sphiggaṇḍādiśuṣkatātodaraukṣyākṣaglānisandhisphoṭanadhamanīśaithilyairmāṃsam plīhavṛddhikaṭīsvāpasandhiśūnyatāṅgaraukṣyakārśyaśramaśoṣameduramāṃsābhilāṣairmāṃsakṣayoktaiśca medaḥ dantanakharomakeśaśātanaraukṣyapāruṣyasandhiśaithilyāsthitodāsthibaddhamāṃsābhilāṣairasthi asthisauṣiryanistodadaurbalyabhramatamodarśanairmajjā śramadaurbalyāsyaśoṣatimiradarśanāṅgamardapāṇḍutāsadanaklaibyamuṣkatodameḍhradhūmāyanaiścirācca niṣekeṇa saraktaniṣekeṇa vā śukram saśabdasya vāyoḥ kukṣau tiryagūrdhvaṃ ca bhramaṇenāntraveṣṭanena pārśvahṛdayapīḍanenālpatayā ca śakṛt bastinistodamukhaśoṣakṛchrālpavivarṇamūtratādibhiḥ sarudhiramūtratayā vā mūtram stabdharomakūpatāromacyavanatvakparipāṭanasvāpapāruṣyasvedanāśaiḥ svedaḥ" },
      { type: "verse", number: "7", sanskrit: "अन्ये ऽपि च मला यथायथं मलायनं शोषशून्यत्वलाघवैः विपरीतगुणक्षयवृद्धिभ्यां च वृद्धिक्षयावुपलक्षयेत् मलानां त्वतिसङ्गोत्सर्गाभ्यां च वृद्धिक्षयौ वृद्धेस्तु मलानां क्षयः पीडयति सुतरामनौचित्यात्", text: "anye 'pi ca malā yathāyathaṃ malāyanaṃ śoṣaśūnyatvalāghavaiḥ viparītaguṇakṣayavṛddhibhyāṃ ca vṛddhikṣayāvupalakṣayet malānāṃ tvatisaṅgotsargābhyāṃ ca vṛddhikṣayau vṛddhestu malānāṃ kṣayaḥ pīḍayati sutarāmanaucityāt" },
      { type: "verse", number: "8", sanskrit: "तत्रास्थनि स्थितो वायुरसृक्स्वेदयोः पित्तम् शेषेषु श्लेष्मा तस्मादेकवृद्धिक्षयकारणत्वमेषाम् न त्वेवमस्थिवाय्वोः सर्वैव हि वृद्धिः प्रायो ऽतिसन्तर्पणनिमित्तत्वाच्छ्लेष्मणानुगता तद्विपर्ययाच्च क्षयो वायुना तस्माल्लङ्घनबृंहणाभ्यां वृद्धिक्षयजान् विकारानुपचरेत् पवने तु बृंहणलङ्घनाभ्याम् सर्वत्र च द्रव्यगुणकर्मविपर्ययतुल्यभावेनाविरुद्धेन", text: "tatrāsthani sthito vāyurasṛksvedayoḥ pittam śeṣeṣu śleṣmā tasmādekavṛddhikṣayakāraṇatvameṣām na tvevamasthivāyvoḥ sarvaiva hi vṛddhiḥ prāyo 'tisantarpaṇanimittatvācchleṣmaṇānugatā tadviparyayācca kṣayo vāyunā tasmāllaṅghanabṛṃhaṇābhyāṃ vṛddhikṣayajān vikārānupacaret pavane tu bṛṃhaṇalaṅghanābhyām sarvatra ca dravyaguṇakarmaviparyayatulyabhāvenāviruddhena" },
      { type: "verse", number: "9", sanskrit: "धातवः खलु शारीराः समानैः समानगुणभूयिष्ठैर्वाहारविहारैरभ्यस्यमानैर्वृद्धिमाप्नुवन्ति ह्रासं तु विपरीतैर्विपरीतगुणभूयिष्ठर्वा तथा हि देहधातवो ये गुरवस्ते गुरुभिरैक्यकारितयोपचीयन्ते लघवस्तु लघुभिस्तद्विपरीतैस्तु पृथक्त्वकारिभिरपचीयन्ते तस्मादन्येभ्यो द्रव्येभ्यो ऽपि सुतरां रक्तमाप्याय्यते रक्तेन मांसं मांसेन मेदो मेदसास्थि तरुणास्थ्ना मज्जा मज्ञा शुक्रं शुक्रेणामगर्मेण गर्भः यत्र त्वेवं लक्षणेन सामान्येन सामान्यवतामाहारविहाराणामसान्निध्यं स्यात् सन्निहितानां चाभ्यवहरणमशक्यं विरुद्धत्वाद् घृणित्वादरुचेरन्यस्माद्वा कारणान्तरात् तत्र समानगुणभूयिष्ठानामन्यप्रकृतीनामाहारविहाराणामभ्यवहारः श्रेयान्", text: "dhātavaḥ khalu śārīrāḥ samānaiḥ samānaguṇabhūyiṣṭhairvāhāravihārairabhyasyamānairvṛddhimāpnuvanti hrāsaṃ tu viparītairviparītaguṇabhūyiṣṭharvā tathā hi dehadhātavo ye guravaste gurubhiraikyakāritayopacīyante laghavastu laghubhistadviparītaistu pṛthaktvakāribhirapacīyante tasmādanyebhyo dravyebhyo 'pi sutarāṃ raktamāpyāyyate raktena māṃsaṃ māṃsena medo medasāsthi taruṇāsthnā majjā majñā śukraṃ śukreṇāmagarmeṇa garbhaḥ yatra tvevaṃ lakṣaṇena sāmānyena sāmānyavatāmāhāravihārāṇāmasānnidhyaṃ syāt sannihitānāṃ cābhyavaharaṇamaśakyaṃ viruddhatvād ghṛṇitvādaruceranyasmādvā kāraṇāntarāt tatra samānaguṇabhūyiṣṭhānāmanyaprakṛtīnāmāhāravihārāṇāmabhyavahāraḥ śreyān" },
      { type: "verse", number: "10", sanskrit: "तद्यथा शुक्रक्षये क्षीरसर्पिषोरुपयोगो मधुरस्निग्धशीतानामपरेषां च द्रव्याणाम् कर्मापि यद्यस्य धातोः समानक्रियतया वृद्धिकरं तस्य तस्य वृद्धिमभिलषता तत्तदासेव्यम् तथैव चतुल्यक्रियतया ह्रासकरं तदर्थिनेति अपि च विशेषतो रक्तवृद्धिजान् रक्तनिर्हरणप्रसादनकायविरेचनेन मांसवृद्धिजान् संशोधनशस्त्रक्षाराग्निकर्मभिः मेदोजान् स्थौल्यकार्श्यक्रियाक्रमेण रसक्षयजान् मांसरसमद्यक्षीरैः अस्थिक्षयजान् बस्तिभिस्तिक्तोपहितैः क्सीरबस्तिभिश्च शकृद्वृद्धिजानतीसारविधानेन शकृत्क्षयजान्यवमाषकुल्माषाजमेषमध्यादिभिः मूत्रवृद्धिक्षयजान् मेहकृछ्रचिकित्सया स्वेदक्षयजानभ्यङ्गव्यायाममद्यस्वप्ननिवातशरणस्वेदैरिति भवति चात्र", text: "tadyathā śukrakṣaye kṣīrasarpiṣorupayogo madhurasnigdhaśītānāmapareṣāṃ ca dravyāṇām karmāpi yadyasya dhātoḥ samānakriyatayā vṛddhikaraṃ tasya tasya vṛddhimabhilaṣatā tattadāsevyam tathaiva catulyakriyatayā hrāsakaraṃ tadarthineti api ca viśeṣato raktavṛddhijān raktanirharaṇaprasādanakāyavirecanena māṃsavṛddhijān saṃśodhanaśastrakṣārāgnikarmabhiḥ medojān sthaulyakārśyakriyākrameṇa rasakṣayajān māṃsarasamadyakṣīraiḥ asthikṣayajān bastibhistiktopahitaiḥ ksīrabastibhiśca śakṛdvṛddhijānatīsāravidhānena śakṛtkṣayajānyavamāṣakulmāṣājameṣamadhyādibhiḥ mūtravṛddhikṣayajān mehakṛchracikitsayā svedakṣayajānabhyaṅgavyāyāmamadyasvapnanivātaśaraṇasvedairiti bhavati cātra" },
      { type: "verse", number: "11", sanskrit: "ये पाचकांशा धातुस्थास्तेषां मान्द्यातितैक्ष्ण्यतः वृद्धिः क्षयश्च धातूनां जायते शृणु चापरम्", text: "ye pācakāṃśā dhātusthāsteṣāṃ māndyātitaikṣṇyataḥ vṛddhiḥ kṣayaśca dhātūnāṃ jāyate śṛṇu cāparam" },
      { type: "verse", number: "12", sanskrit: "पारम्पर्ये ऽपि दावाग्नेस्तत्तत् प्राप्येन्धनं शिखा वृद्धिक्षयौ यथा याति तद्वद्धातुपरम्परा", text: "pāramparye 'pi dāvāgnestattat prāpyendhanaṃ śikhā vṛddhikṣayau yathā yāti tadvaddhātuparamparā" },
      { type: "verse", number: "13", sanskrit: "द्रव्यं तुल्यं विशिष्टं हि स्वं स्वं वृध्द्यै क्षयाय च प्रत्यात्मबीजनियतं भृशमाशु प्रजायते", text: "dravyaṃ tulyaṃ viśiṣṭaṃ hi svaṃ svaṃ vṛdhdyai kṣayāya ca pratyātmabījaniyataṃ bhṛśamāśu prajāyate" },
      { type: "verse", number: "14", sanskrit: "पूर्वो धातुः परं कुर्यात् वृद्धः क्षीणश्च तद्विधम् दोषा दुष्टा रसैर्धातून् दूषयन्त्युभये मलान्", text: "pūrvo dhātuḥ paraṃ kuryāt vṛddhaḥ kṣīṇaśca tadvidham doṣā duṣṭā rasairdhātūn dūṣayantyubhaye malān" },
      { type: "verse", number: "15", sanskrit: "अधो द्वे सप्त शिरसि खानि स्वेदवहानि च मला मलायनानि स्युर्यथास्वं तेष्वतो गदाः", text: "adho dve sapta śirasi khāni svedavahāni ca malā malāyanāni syuryathāsvaṃ teṣvato gadāḥ" },
      { type: "verse", number: "16", sanskrit: "वक्ष्यन्ते वातजास्तत्र निदाने वातरौगिके पित्तं त्वचि स्थितं कुर्याद्विस्फोटकमसूरिकाः", text: "vakṣyante vātajāstatra nidāne vātaraugike pittaṃ tvaci sthitaṃ kuryādvisphoṭakamasūrikāḥ" },
      { type: "verse", number: "17", sanskrit: "रक्ते विसर्पं दाहं च मांसे मांस्पाककोथनम् सदाहान्मेदसि ग्रन्थीन् स्वेदात्युद्वमनं तृषम्", text: "rakte visarpaṃ dāhaṃ ca māṃse māṃspākakothanam sadāhānmedasi granthīn svedātyudvamanaṃ tṛṣam" },
      { type: "verse", number: "18", sanskrit: "अस्थ्नि दाहं भृशं मज्ञि हारिद्रनखनेत्रताम् पूतिपीतावभासं च शुक्रं शुक्रसमाश्रितम्", text: "asthni dāhaṃ bhṛśaṃ majñi hāridranakhanetratām pūtipītāvabhāsaṃ ca śukraṃ śukrasamāśritam" },
      { type: "verse", number: "19", sanskrit: "सिरागतं क्रोधनतां प्रलापं स्नावगं तृषम् कोष्ठगं मदतृड्दाहान् व्यापिनो ऽन्यांश्चयक्ष्मणः", text: "sirāgataṃ krodhanatāṃ pralāpaṃ snāvagaṃ tṛṣam koṣṭhagaṃ madatṛḍdāhān vyāpino 'nyāṃścayakṣmaṇaḥ" },
      { type: "verse", number: "20", sanskrit: "श्लेष्मा त्वचि स्थितः कुर्यात् स्तम्भं श्वेतावभासताम् पाण्डूवामयं शोणितगो मांससंस्थो ऽर्बुदापचीः", text: "śleṣmā tvaci sthitaḥ kuryāt stambhaṃ śvetāvabhāsatām pāṇḍūvāmayaṃ śoṇitago māṃsasaṃstho 'rbudāpacīḥ" },
      { type: "verse", number: "21", sanskrit: "आर्द्रचर्मावनद्धाभगात्रतां चातिगौरवम् मेदोगः स्थूलतां मेहमस्थ्नां स्तब्धत्वमस्थिगः", text: "ārdracarmāvanaddhābhagātratāṃ cātigauravam medogaḥ sthūlatāṃ mehamasthnāṃ stabdhatvamasthigaḥ" },
      { type: "verse", number: "22", sanskrit: "मज्जगः शुक्लनेत्रत्वं शुक्रस्थः शुक्रसञ्चयम् विबन्धं गौरवं चाति सिरास्थः स्तब्धगात्रताम्", text: "majjagaḥ śuklanetratvaṃ śukrasthaḥ śukrasañcayam vibandhaṃ gauravaṃ cāti sirāsthaḥ stabdhagātratām" },
      { type: "verse", number: "23", sanskrit: "स्नायुगः सन्धिशूलत्वं कोष्ठगो जठरोन्नतिम् अरोचकाविपाकौ च तांस्तांश्च कफसम्भवान्", text: "snāyugaḥ sandhiśūlatvaṃ koṣṭhago jaṭharonnatim arocakāvipākau ca tāṃstāṃśca kaphasambhavān" },
      { type: "verse", number: "24", sanskrit: "विण्मूत्रयोः साश्रययोस्तत्र तत्रोपदेक्ष्यते उपतापोपघातौ तु स्वाश्रयेन्द्रियगा मलाः", text: "viṇmūtrayoḥ sāśrayayostatra tatropadekṣyate upatāpopaghātau tu svāśrayendriyagā malāḥ" },
      { type: "verse", number: "25", sanskrit: "व्यायामादूष्मणस्तैक्ष्ण्यादहिताचरणादपि कोष्ठाच्छाखास्थिमर्माणि द्रुतत्वान्मारुतस्य च", text: "vyāyāmādūṣmaṇastaikṣṇyādahitācaraṇādapi koṣṭhācchākhāsthimarmāṇi drutatvānmārutasya ca" },
      { type: "verse", number: "26", sanskrit: "दोषा यान्ति तथा तेभ्यः स्रोतोमुखविशोधनात् वृध्याभिष्यन्दनात्पाकात्कोष्ठं वायोश्च निग्रहात्", text: "doṣā yānti tathā tebhyaḥ srotomukhaviśodhanāt vṛdhyābhiṣyandanātpākātkoṣṭhaṃ vāyośca nigrahāt" },
      { type: "verse", number: "27", sanskrit: "तत्रस्थाश्च विलम्बेरन् भूयो हेतुप्रतीक्षिणः ते कालादिबलं लब्ध्वा कुप्यन्त्यन्याश्रयेष्वपि", text: "tatrasthāśca vilamberan bhūyo hetupratīkṣiṇaḥ te kālādibalaṃ labdhvā kupyantyanyāśrayeṣvapi" },
      { type: "verse", number: "28", sanskrit: "तत्रान्यस्थानसंस्थेषु तदीयामबलेषु तु कुर्याच्चिकित्सां स्वामेव बलेनान्याभिभाविषु", text: "tatrānyasthānasaṃstheṣu tadīyāmabaleṣu tu kuryāccikitsāṃ svāmeva balenānyābhibhāviṣu" },
      { type: "verse", number: "29", sanskrit: "आगन्तुं शमयेद्दोषं स्थानिनं प्रतिकृत्य वा तेजो यत्सर्वधातूनामोजस्तत् परमुच्यते मृदु सोमात्मकं शुद्धं रक्तमीषत्सपीतकम्", text: "āgantuṃ śamayeddoṣaṃ sthāninaṃ pratikṛtya vā tejo yatsarvadhātūnāmojastat paramucyate mṛdu somātmakaṃ śuddhaṃ raktamīṣatsapītakam" },
      { type: "verse", number: "30", sanskrit: "यत्सारमादौ गर्भस्य यच्च गर्भरसाद्रसः संवर्तमानं हृदयं समाश्रयति यत्पुरा", text: "yatsāramādau garbhasya yacca garbharasādrasaḥ saṃvartamānaṃ hṛdayaṃ samāśrayati yatpurā" },
      { type: "verse", number: "31", sanskrit: "यच्छरीररसः स्नेहः प्राणो यत्र प्रतिष्ठितः यस्यानाशान्ननाशो ऽस्ति प्रीणिता येन देहिनः", text: "yaccharīrarasaḥ snehaḥ prāṇo yatra pratiṣṭhitaḥ yasyānāśānnanāśo 'sti prīṇitā yena dehinaḥ" },
      { type: "verse", number: "32", sanskrit: "हृदयस्थमपि व्यापि तत् परं जीवितास्पदम् औजः क्षीयत कोपक्षुद्ध्यानशोकश्रमादिभिः", text: "hṛdayasthamapi vyāpi tat paraṃ jīvitāspadam aujaḥ kṣīyata kopakṣuddhyānaśokaśramādibhiḥ" },
      { type: "verse", number: "33", sanskrit: "बिभेति दुर्बलो ऽभीक्ष्णं ध्यायति व्यथितेन्द्रियः दुश्च्छायो दुर्मना रूक्षो भवेत् क्षामश्च तत्क्षये", text: "bibheti durbalo 'bhīkṣṇaṃ dhyāyati vyathitendriyaḥ duścchāyo durmanā rūkṣo bhavet kṣāmaśca tatkṣaye" },
      { type: "verse", number: "34", sanskrit: "जीवनीयौषधक्षीररसाद्यास्तत्र भेषजम् औजोवृद्धौ हि देहस्य तुष्टिपुष्टिबलोदयः", text: "jīvanīyauṣadhakṣīrarasādyāstatra bheṣajam aujovṛddhau hi dehasya tuṣṭipuṣṭibalodayaḥ" },
      { type: "verse", number: "35", sanskrit: "यदन्नं द्वेष्टि यदपि प्रार्थयेताविरोधि तु तत्तत्यजन् समश्नंश्च तौ तौ वृद्धिक्षयौ जयेत्", text: "yadannaṃ dveṣṭi yadapi prārthayetāvirodhi tu tattatyajan samaśnaṃśca tau tau vṛddhikṣayau jayet" },
      { type: "verse", number: "36", sanskrit: "कुर्वते ऽभिरुचिं दोषा विपरीतसमानयोः वृद्धाः क्षीणाश्च भूयिष्ठं लक्षयन्त्यबुधा न तत्", text: "kurvate 'bhiruciṃ doṣā viparītasamānayoḥ vṛddhāḥ kṣīṇāśca bhūyiṣṭhaṃ lakṣayantyabudhā na tat" },
      { type: "verse", number: "37", sanskrit: "यथाबलं यथास्वं च दोषा वृद्धा वितन्वते रूपाणि जहति क्षीणाः समाः स्वं कर्म कुर्वते", text: "yathābalaṃ yathāsvaṃ ca doṣā vṛddhā vitanvate rūpāṇi jahati kṣīṇāḥ samāḥ svaṃ karma kurvate" },
      { type: "verse", number: "38", sanskrit: "य एव देहस्य समा विवृध्यै त एव दोषा विषमा वधाय यस्मादतस्ते हितचर्ययैव क्षयाद्विवृद्धेरिव रक्षणीयाः", text: "ya eva dehasya samā vivṛdhyai ta eva doṣā viṣamā vadhāya yasmādataste hitacaryayaiva kṣayādvivṛddheriva rakṣaṇīyāḥ" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 20,
    lang: "sa",
    content: [
      { type: "heading", heading: "Анна-пана видхи — правила питания и питья" },
      { type: "text", text: "Глава 20 Сутрастханы Астанга-санграхи посвящена теме «правила питания и питья». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो दोषभेदीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः वाय्वाकाशधातुभ्यां वायुः आग्नेयं पित्तम् अम्भःपृथिवीभ्यां श्लेष्मा तत्र पक्वाशयः कटिः सक्थिनी पादावस्थि श्रोत्रं स्पर्शनं च वातस्थानानि अत्र च पक्वाशयो विशेषेण नाभिरामाशयः स्वेदो लसीका रुधिरं चक्षुः स्पर्शनं च पित्तस्थानानि अत्र नाभिर्विशेषेण उरः कण्ठः शिरः क्लोम पर्वाण्यामाशयो रसो मेदो घ्राणं रसनं च श्लेष्मस्थानानि अत्राप्युरो विशेषेण इत्थमधोमध्योर्ध्वसन्निवेशिना दोषत्रयेण शरीरमगारमिव स्थूणात्रितयेन स्थिरीकृतम् अतश्च दोषा देहस्य स्थिरीकरणात् स्थूणा इत्युच्यन्ते धारणाद्धातवः मलिनीकरणादाहारमलत्वाच्च मलाः दूषणस्वभावाद्दोषा इति", text: "athāto doṣabhedīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ vāyvākāśadhātubhyāṃ vāyuḥ āgneyaṃ pittam ambhaḥpṛthivībhyāṃ śleṣmā tatra pakvāśayaḥ kaṭiḥ sakthinī pādāvasthi śrotraṃ sparśanaṃ ca vātasthānāni atra ca pakvāśayo viśeṣeṇa nābhirāmāśayaḥ svedo lasīkā rudhiraṃ cakṣuḥ sparśanaṃ ca pittasthānāni atra nābhirviśeṣeṇa uraḥ kaṇṭhaḥ śiraḥ kloma parvāṇyāmāśayo raso medo ghrāṇaṃ rasanaṃ ca śleṣmasthānāni atrāpyuro viśeṣeṇa itthamadhomadhyordhvasanniveśinā doṣatrayeṇa śarīramagāramiva sthūṇātritayena sthirīkṛtam ataśca doṣā dehasya sthirīkaraṇāt sthūṇā ityucyante dhāraṇāddhātavaḥ malinīkaraṇādāhāramalatvācca malāḥ dūṣaṇasvabhāvāddoṣā iti" },
      { type: "verse", number: "2", sanskrit: "त एते प्रत्येकं पञ्चधा भिद्यन्ते तद्यथा प्राणोदानव्यानसमानापानभेदैर्वायुः तत्र प्राणो मूर्द्धन्यवस्थितः कण्ठोरश्चरो बुद्धीन्द्रियहृदयमनोधमनीधारणष्ठीवनक्षवथूद्गारप्रश्वासोच्छ्वासान्नप्रवेशादिक्रियः उदान उरस्यवस्थितः कण्ठनासिकानाभिचरो वाक्प्रवृत्तिप्रयत्नोर्जाबलवर्णस्रोतःप्रीणनधीधृतिस्मृतिमनोबोधनादिक्रियः व्यानो हृद्यवस्थितः कृत्स्नदेहचरः शीघ्रतरगतिः गतिप्रसारणाकुञ्चनोत्क्षेपावक्षेपनिभेषोन्मेषजृम्भणान्नास्वादनस्रोतोविशोधनस्वेदासृक्स्रावणादिक्रियो योनौ च शुक्रप्रतिपादनो विभज्य चान्नस्य किट्टात् सारं तेन क्रमशो धातूंस्तर्पयति समानो ऽन्तरग्निसमीपस्थस्तत्सन्धुक्षणः पक्वामाशयदोषमलशुक्रार्तवाम्बुवहः स्रोतोविचारी तदवलम्बनान्नधारणपाचनविवेचनकिट्टाधोनयनादिक्रियः अपानस्त्वपानस्थितो बस्तिश्रोणिमेढ्रवृषणवङ्क्षणोरुचरोविण्मूत्रशुक्रार्तवगर्भनिष्क्रमणादिक्रिय इति", text: "ta ete pratyekaṃ pañcadhā bhidyante tadyathā prāṇodānavyānasamānāpānabhedairvāyuḥ tatra prāṇo mūrddhanyavasthitaḥ kaṇṭhoraścaro buddhīndriyahṛdayamanodhamanīdhāraṇaṣṭhīvanakṣavathūdgārapraśvāsocchvāsānnapraveśādikriyaḥ udāna urasyavasthitaḥ kaṇṭhanāsikānābhicaro vākpravṛttiprayatnorjābalavarṇasrotaḥprīṇanadhīdhṛtismṛtimanobodhanādikriyaḥ vyāno hṛdyavasthitaḥ kṛtsnadehacaraḥ śīghrataragatiḥ gatiprasāraṇākuñcanotkṣepāvakṣepanibheṣonmeṣajṛmbhaṇānnāsvādanasrotoviśodhanasvedāsṛksrāvaṇādikriyo yonau ca śukrapratipādano vibhajya cānnasya kiṭṭāt sāraṃ tena kramaśo dhātūṃstarpayati samāno 'ntaragnisamīpasthastatsandhukṣaṇaḥ pakvāmāśayadoṣamalaśukrārtavāmbuvahaḥ srotovicārī tadavalambanānnadhāraṇapācanavivecanakiṭṭādhonayanādikriyaḥ apānastvapānasthito bastiśroṇimeḍhravṛṣaṇavaṅkṣaṇorucaroviṇmūtraśukrārtavagarbhaniṣkramaṇādikriya iti" },
      { type: "verse", number: "3", sanskrit: "पाचकरञ्जकसाधकालोचकभ्राजकत्वभेदैः पित्तम् तत्र यदामाशयपक्वाशयमध्यस्थं पञ्चमहाभूतात्मकत्वे ऽपि तेजोगुणोत्कर्षात् क्षपितसोमगुणं ततश्च त्यक्तद्रवस्वभावं सहकारिकारणैर्वायुक्लेदादिभिरनुग्रहाद्दहनपचनादिक्रियया लब्धाग्निशब्दं पित्तमन्नं पचति सारकिट्टौ विभजति शेषाणि च पित्तस्थानानि तत्रस्थमेवानुगृह्णाति तत् पाचकमित्युच्यते आमाशयस्यं तु रसस्य रञ्जनाद्रञ्जकम् हृदयस्थं बुद्धिमेधाभिमानोत्साहैरभिप्रेतार्थसाधनात्साधकम् दृष्टिस्थं रूपालोचनादालोचकम् त्वक्स्थं त्वचो भ्राजनात् भ्राजकम् तदभ्यङ्गपरिषेकालेपादीन् पाचयति छायाश्च प्रकाशयति", text: "pācakarañjakasādhakālocakabhrājakatvabhedaiḥ pittam tatra yadāmāśayapakvāśayamadhyasthaṃ pañcamahābhūtātmakatve 'pi tejoguṇotkarṣāt kṣapitasomaguṇaṃ tataśca tyaktadravasvabhāvaṃ sahakārikāraṇairvāyukledādibhiranugrahāddahanapacanādikriyayā labdhāgniśabdaṃ pittamannaṃ pacati sārakiṭṭau vibhajati śeṣāṇi ca pittasthānāni tatrasthamevānugṛhṇāti tat pācakamityucyate āmāśayasyaṃ tu rasasya rañjanādrañjakam hṛdayasthaṃ buddhimedhābhimānotsāhairabhipretārthasādhanātsādhakam dṛṣṭisthaṃ rūpālocanādālocakam tvaksthaṃ tvaco bhrājanāt bhrājakam tadabhyaṅgapariṣekālepādīn pācayati chāyāśca prakāśayati" },
      { type: "verse", number: "4", sanskrit: "अवलम्बकक्लेदकबोधकतर्पकश्लेषकत्वभेदैः श्लेष्मा स तूरस्थः स्ववीर्येण त्रिकस्यान्नवीर्येण च सह हृदयस्य च शेषाणां च श्लेष्मस्थानानां तत्रस्थ एवोदककर्मणावलम्बनादवलम्बक इत्युच्यते आमाशयस्थितो ऽन्नसङ्घातस्य क्लेदनात् क्लेदकः रसनास्थः सम्यग्रसबोधनात् बोधकः शिरस्थश्चक्षुरादीन्द्रियतर्पणात् तर्पकः पर्वस्थो ऽस्थिसन्धिश्लेषणात् श्लेषक इति", text: "avalambakakledakabodhakatarpakaśleṣakatvabhedaiḥ śleṣmā sa tūrasthaḥ svavīryeṇa trikasyānnavīryeṇa ca saha hṛdayasya ca śeṣāṇāṃ ca śleṣmasthānānāṃ tatrastha evodakakarmaṇāvalambanādavalambaka ityucyate āmāśayasthito 'nnasaṅghātasya kledanāt kledakaḥ rasanāsthaḥ samyagrasabodhanāt bodhakaḥ śirasthaścakṣurādīndriyatarpaṇāt tarpakaḥ parvastho 'sthisandhiśleṣaṇāt śleṣaka iti" },
      { type: "verse", number: "5", sanskrit: "एवममीषु स्थानेषु भूयिष्ठमविकृताः सकलशरीरव्यापिनो ऽपि वातपित्तश्लेष्माणो वर्तन्ते तेषां वृद्धिहेतुर्वक्ष्यते निदानेषु सामान्यतश्च वृद्धिक्षयलक्षणमुक्तं पूर्वाध्याये वृद्धिर्हि द्वेधा चयप्रकोपभेदेन तत्रोष्णगुणोपहिता रुक्षादयो वायोः सञ्चयमापादयन्ति शीतगुणोपहिताः प्रकोपमुष्णगुणोपहिताः स्निग्धादयः प्रशमम् शीतगुणोपहितास्तीक्ष्णादयः पित्तस्य चयमुष्णगुणोपहिताः कोपं शीतगुणोपहिता मन्दादयः प्रशमम् शीतगुणोपहिताः स्निग्धादयः कफस्य चयमुष्णगुणोपहिताः कोपं तथा तु रूक्षादयः प्रशमम्", text: "evamamīṣu sthāneṣu bhūyiṣṭhamavikṛtāḥ sakalaśarīravyāpino 'pi vātapittaśleṣmāṇo vartante teṣāṃ vṛddhiheturvakṣyate nidāneṣu sāmānyataśca vṛddhikṣayalakṣaṇamuktaṃ pūrvādhyāye vṛddhirhi dvedhā cayaprakopabhedena tatroṣṇaguṇopahitā rukṣādayo vāyoḥ sañcayamāpādayanti śītaguṇopahitāḥ prakopamuṣṇaguṇopahitāḥ snigdhādayaḥ praśamam śītaguṇopahitāstīkṣṇādayaḥ pittasya cayamuṣṇaguṇopahitāḥ kopaṃ śītaguṇopahitā mandādayaḥ praśamam śītaguṇopahitāḥ snigdhādayaḥ kaphasya cayamuṣṇaguṇopahitāḥ kopaṃ tathā tu rūkṣādayaḥ praśamam" },
      { type: "verse", number: "6", sanskrit: "चयो वृद्धिः स्वधाम्न्येव प्रद्वेषो वृद्धिहेतुषु विपरीतगुणेच्छा च कोपस्तून्मार्गगामिता", text: "cayo vṛddhiḥ svadhāmnyeva pradveṣo vṛddhihetuṣu viparītaguṇecchā ca kopastūnmārgagāmitā" },
      { type: "verse", number: "7", sanskrit: "लिङ्गानां दर्शनं स्वेषामस्वास्थ्यं रोगसम्भवः स्वस्थानस्थस्य समता विकारासम्भवः शमः", text: "liṅgānāṃ darśanaṃ sveṣāmasvāsthyaṃ rogasambhavaḥ svasthānasthasya samatā vikārāsambhavaḥ śamaḥ" },
      { type: "verse", number: "8", sanskrit: "देहे ऽक्रुद्धो ऽनिलवशात् कृत्स्ने ऽर्द्धे ऽवयवे ऽपि वा दोषो विकारं कुरुते खे वर्षमिव तोयदः", text: "dehe 'kruddho 'nilavaśāt kṛtsne 'rddhe 'vayave 'pi vā doṣo vikāraṃ kurute khe varṣamiva toyadaḥ" },
      { type: "verse", number: "9", sanskrit: "अथ प्रकुपिता वातादयो नानाविधैर्विकारैः शरीरमुपतपन्ति आविष्कृततमास्तु वायोरशीतिर्विकाराः तद्यथा नखभेदो विपादिका पादशूलं पादभ्रंशः सुप्तपादता वातखुडता गुल्फग्रहः पिण्डिकोद्वेष्टनं गृद्ध्रसी जानुभेदो जानुविश्लेषः ऊरुसाद ऊरुस्तम्भः पङ्गुत्वं गुदभ्रंशो गुदार्तिर्वृषणाक्षेपो मेढ्रस्तम्भो वङ्क्षणानाहः श्रेणिभेदो विङ्भेद उदावर्तः खञ्जत्वं कुब्जत्वं वामनत्वं त्रिकग्रहः पृष्ठग्रहः पार्श्वावमर्द उदरावेष्टो हृन्मोहो हृद्द्रवो वक्षोद्घर्षस्तथा वक्षोपरोधो वक्षस्तोदो बाहुशोषस्तथा ग्रीवास्तम्भो मन्यास्तम्भः कण्ठोद्ध्वंसो हनुस्तम्भस्ताल्वोष्ठभेदो दन्तभेदो दन्तशैथिल्यं मूकत्वं वाक्सङ्गः प्रलापः कषायाम्यता मुखशोषो रसाज्ञत्वं घ्राणनाशः कर्णशूलमशब्दश्रुतिरुच्चैःश्रुतिर्बाधिर्यं वर्त्मस्तम्भो वर्त्मसङ्कोचस्तिमिरमक्षिशूलमक्षिव्युदासो भ्रूव्युदासः शङ्खभेदो ललाटभेदः शिरोरुक्केशभूमिस्फुटनमर्दितमेकाङ्गरोगः सर्वाङ्गरोग आक्षेपको दण्डकः श्रमो भ्रमो वेपथुर्जृम्भा ग्लानिर्विषादो रौक्ष्यं पारुष्यं श्यावारुणाभासत्वमस्वप्नो ऽनवस्थितचित्तता च", text: "atha prakupitā vātādayo nānāvidhairvikāraiḥ śarīramupatapanti āviṣkṛtatamāstu vāyoraśītirvikārāḥ tadyathā nakhabhedo vipādikā pādaśūlaṃ pādabhraṃśaḥ suptapādatā vātakhuḍatā gulphagrahaḥ piṇḍikodveṣṭanaṃ gṛddhrasī jānubhedo jānuviśleṣaḥ ūrusāda ūrustambhaḥ paṅgutvaṃ gudabhraṃśo gudārtirvṛṣaṇākṣepo meḍhrastambho vaṅkṣaṇānāhaḥ śreṇibhedo viṅbheda udāvartaḥ khañjatvaṃ kubjatvaṃ vāmanatvaṃ trikagrahaḥ pṛṣṭhagrahaḥ pārśvāvamarda udarāveṣṭo hṛnmoho hṛddravo vakṣodgharṣastathā vakṣoparodho vakṣastodo bāhuśoṣastathā grīvāstambho manyāstambhaḥ kaṇṭhoddhvaṃso hanustambhastālvoṣṭhabhedo dantabhedo dantaśaithilyaṃ mūkatvaṃ vāksaṅgaḥ pralāpaḥ kaṣāyāmyatā mukhaśoṣo rasājñatvaṃ ghrāṇanāśaḥ karṇaśūlamaśabdaśrutiruccaiḥśrutirbādhiryaṃ vartmastambho vartmasaṅkocastimiramakṣiśūlamakṣivyudāso bhrūvyudāsaḥ śaṅkhabhedo lalāṭabhedaḥ śirorukkeśabhūmisphuṭanamarditamekāṅgarogaḥ sarvāṅgaroga ākṣepako daṇḍakaḥ śramo bhramo vepathurjṛmbhā glānirviṣādo raukṣyaṃ pāruṣyaṃ śyāvāruṇābhāsatvamasvapno 'navasthitacittatā ca" },
      { type: "verse", number: "10", sanskrit: "पित्तविकाराः पुनरोषः प्लोषो दवो दवथुर्विदाहो ऽन्तर्दाहस्त्वग्दाहो ऽंसदाहो धूमको ऽम्लक ऊष्माधिक्यमतिस्वेदो ऽङ्गगन्धो ऽवयवसदनं शोणितक्लेदो मांसक्लेदस्त्वङ्मांसावदरणं चर्मदरणं रक्तकोठो रक्तविस्फोटो रक्तमण्डलानि रक्तपित्तं हरितत्वं हारिद्रत्वं नीलिका कक्ष्या कामला तिक्तास्यता लोहितगन्धास्यता पूतिमुखत्वं तृष्णाधिक्यमतृप्तिरास्यपाको गलपाको ऽक्षिपाकः पायुपाको मेढ्रपाको जीवादानं तमःप्रवेशो हरितहारिद्रनेत्रमूत्रशकृत्त्वं च", text: "pittavikārāḥ punaroṣaḥ ploṣo davo davathurvidāho 'ntardāhastvagdāho 'ṃsadāho dhūmako 'mlaka ūṣmādhikyamatisvedo 'ṅgagandho 'vayavasadanaṃ śoṇitakledo māṃsakledastvaṅmāṃsāvadaraṇaṃ carmadaraṇaṃ raktakoṭho raktavisphoṭo raktamaṇḍalāni raktapittaṃ haritatvaṃ hāridratvaṃ nīlikā kakṣyā kāmalā tiktāsyatā lohitagandhāsyatā pūtimukhatvaṃ tṛṣṇādhikyamatṛptirāsyapāko galapāko 'kṣipākaḥ pāyupāko meḍhrapāko jīvādānaṃ tamaḥpraveśo haritahāridranetramūtraśakṛttvaṃ ca" },
      { type: "verse", number: "11", sanskrit: "श्लेष्मविकारास्तु तृप्तिस्तन्द्रा निद्राधिक्यं स्तैमित्यं गुरुगात्रतालस्यं मुखमाधुर्यं प्रसेकः श्लेष्मोद्गिरणं मलाधिक्यं बलासो हृदयोपलेपः कण्ठोपलेपो धमनीप्रतिचयो गलगण्डो ऽतिस्थौल्यं शीताग्नित्वमुदर्दः श्वेतावभासता श्वेतनेत्रमूत्रशकृत्त्वं च", text: "śleṣmavikārāstu tṛptistandrā nidrādhikyaṃ staimityaṃ gurugātratālasyaṃ mukhamādhuryaṃ prasekaḥ śleṣmodgiraṇaṃ malādhikyaṃ balāso hṛdayopalepaḥ kaṇṭhopalepo dhamanīpraticayo galagaṇḍo 'tisthaulyaṃ śītāgnitvamudardaḥ śvetāvabhāsatā śvetanetramūtraśakṛttvaṃ ca" },
      { type: "verse", number: "12", sanskrit: "तत्र सर्वाङ्गीणस्तीव्रः सन्तापो दाहः स्वेदारतिमानोषः प्रादेशिकः स्वेदरहितो ऽग्न्यर्चिषेव दाहः प्लोषः मुखोष्ठतालुषु दाहो दवः चक्षुरादीन्द्रियेषु दाहो दवथुः पाणिपादांसमूलेषु विविधः सन्तापो विदाहः कोष्ठे दाहो ऽन्तर्दाहः शिरोग्रीवाकण्ठतालुषु धूमायनं धूमकः सान्तर्दाहहृदयशूलोद्गारो ऽम्लकः शोणितस्य कृष्णतादौर्गन्ध्यतनुत्वानि क्लेदः मांसस्य तु कृष्णता दैर्गन्ध्यं च बाह्यत्वक्संहतिश्चर्मकोथः कोष्ठगौरवादाहारास्पृहा तृप्तिः अन्ये पुनराहुरन्नानभिनन्दता तृप्तिरिव तृप्तिररोचकः निद्रार्त्तस्येव विषयाग्रहणं तन्द्रा स्तैमित्यं तु प्रमीलक इत्यन्यैः पठितम् उपलेप इवोपलेपः तदतिशयः प्रतिचयो ऽतिपूरणम् अग्नेरतिमन्दता शैल्यम् उरसो ऽभिष्यन्द उदर्दः केषाञ्चिच्छीतवेपथुरुदर्दः अन्ये पुनराहुः", text: "tatra sarvāṅgīṇastīvraḥ santāpo dāhaḥ svedāratimānoṣaḥ prādeśikaḥ svedarahito 'gnyarciṣeva dāhaḥ ploṣaḥ mukhoṣṭhatāluṣu dāho davaḥ cakṣurādīndriyeṣu dāho davathuḥ pāṇipādāṃsamūleṣu vividhaḥ santāpo vidāhaḥ koṣṭhe dāho 'ntardāhaḥ śirogrīvākaṇṭhatāluṣu dhūmāyanaṃ dhūmakaḥ sāntardāhahṛdayaśūlodgāro 'mlakaḥ śoṇitasya kṛṣṇatādaurgandhyatanutvāni kledaḥ māṃsasya tu kṛṣṇatā dairgandhyaṃ ca bāhyatvaksaṃhatiścarmakothaḥ koṣṭhagauravādāhārāspṛhā tṛptiḥ anye punarāhurannānabhinandatā tṛptiriva tṛptirarocakaḥ nidrārttasyeva viṣayāgrahaṇaṃ tandrā staimityaṃ tu pramīlaka ityanyaiḥ paṭhitam upalepa ivopalepaḥ tadatiśayaḥ praticayo 'tipūraṇam agneratimandatā śailyam uraso 'bhiṣyanda udardaḥ keṣāñcicchītavepathurudardaḥ anye punarāhuḥ" },
      { type: "verse", number: "13", sanskrit: "शीतपानीयसंस्पर्शाच्छीतकाले विशेषतः सरागकण्डूः शोफः स्यादुदर्दः स कफोद्भव इति", text: "śītapānīyasaṃsparśācchītakāle viśeṣataḥ sarāgakaṇḍūḥ śophaḥ syādudardaḥ sa kaphodbhava iti" },
      { type: "verse", number: "14", sanskrit: "महाविकारास्तु यथास्वमेवोपदेक्ष्यन्ते क्षुद्रविकाराः पुनर्यदेवाङ्गमाविशन्ति तदुपपदमेव नाम लभन्ते यथा नखशङ्खललाटभेदाः सान्तर्दाहकण्ठहृदयोपलेपादयः तेषां हि तथैव स्वरूपमुपदिष्टं भवति", text: "mahāvikārāstu yathāsvamevopadekṣyante kṣudravikārāḥ punaryadevāṅgamāviśanti tadupapadameva nāma labhante yathā nakhaśaṅkhalalāṭabhedāḥ sāntardāhakaṇṭhahṛdayopalepādayaḥ teṣāṃ hi tathaiva svarūpamupadiṣṭaṃ bhavati" },
      { type: "verse", number: "15", sanskrit: "सर्वेषु तेषु तेष्वनुक्तेषु चान्येष्वसङ्ख्येयत्वाद्विकारेष्विमान्येव दोषाणामात्मलिङ्गानि सकलशरीरव्यापीन्यव्यभिवारीणि च तथा कर्माण्युपक्रमश्च तत्रात्मलिङ्गान्यायुष्कामीये निर्दिष्टानि", text: "sarveṣu teṣu teṣvanukteṣu cānyeṣvasaṅkhyeyatvādvikāreṣvimānyeva doṣāṇāmātmaliṅgāni sakalaśarīravyāpīnyavyabhivārīṇi ca tathā karmāṇyupakramaśca tatrātmaliṅgānyāyuṣkāmīye nirdiṣṭāni" },
      { type: "verse", number: "16", sanskrit: "कर्माणि तु वायोः स्रंसव्याससङ्गसाधेदतोदहर्षतर्षवर्त्ताङ्गमर्दकम्पव्यथवेष्टभङ्गशूलशोषस्वापपारुष्यसौषिर्यसङ्कोचस्पन्दनानि कषायरसत्वं श्यावारुणवर्णता च पित्तस्य दाहोष्मपाकस्वेदक्लेदकोथस्रावरागाः कट्वम्लरसत्वं शुक्लारुणवर्ज्यवर्णता च श्लेष्मणः कण्डूस्थैर्यगौरवोपदेहस्नेहशैत्यबन्धचिरकारित्वानि मधुरलवणरसत्वं श्वेतवर्णता चेति", text: "karmāṇi tu vāyoḥ sraṃsavyāsasaṅgasādhedatodaharṣatarṣavarttāṅgamardakampavyathaveṣṭabhaṅgaśūlaśoṣasvāpapāruṣyasauṣiryasaṅkocaspandanāni kaṣāyarasatvaṃ śyāvāruṇavarṇatā ca pittasya dāhoṣmapākasvedakledakothasrāvarāgāḥ kaṭvamlarasatvaṃ śuklāruṇavarjyavarṇatā ca śleṣmaṇaḥ kaṇḍūsthairyagauravopadehasnehaśaityabandhacirakāritvāni madhuralavaṇarasatvaṃ śvetavarṇatā ceti" },
      { type: "verse", number: "17", sanskrit: "कपिलबलस्त्वेषां स्वलक्षणानि रसतो निर्दिदेश कट्वम्ललवणं पित्तं स्वाद्वम्ललवणः कफः कषायतिक्तकटुको वायुर्दृष्टो ऽनुमानतः", text: "kapilabalastveṣāṃ svalakṣaṇāni rasato nirdideśa kaṭvamlalavaṇaṃ pittaṃ svādvamlalavaṇaḥ kaphaḥ kaṣāyatiktakaṭuko vāyurdṛṣṭo 'numānataḥ" },
      { type: "verse", number: "18", sanskrit: "सुश्रुतः पुनः पठति पित्तं विद्ग्धमम्लतामुपैति श्लेष्मा लवणताम् तदेवमेतानि वाय्वादिरूपकर्माण्यवहितः सम्यगुपलक्षयेदागमप्रत्यक्षानुमानैः अनन्तरं च देशकालमात्रादीन् प्रमाणीकृत्याश्वेवोपक्रमेतेति भवन्ति चात्र", text: "suśrutaḥ punaḥ paṭhati pittaṃ vidgdhamamlatāmupaiti śleṣmā lavaṇatām tadevametāni vāyvādirūpakarmāṇyavahitaḥ samyagupalakṣayedāgamapratyakṣānumānaiḥ anantaraṃ ca deśakālamātrādīn pramāṇīkṛtyāśvevopakrameteti bhavanti cātra" },
      { type: "verse", number: "19", sanskrit: "वक्ष्यन्ते ऽतः परं दोषा वृद्धिक्षयविभेदतः पृथक् त्रीन् विद्धि संसर्गस्त्रिधा तत्र तु तान्नव", text: "vakṣyante 'taḥ paraṃ doṣā vṛddhikṣayavibhedataḥ pṛthak trīn viddhi saṃsargastridhā tatra tu tānnava" },
      { type: "verse", number: "20", sanskrit: "त्रीनेव समया वृद्ध्या षडेकस्यातिशायने त्रयोदश समस्तेषु षड् द्व्येकातिशयेन तु", text: "trīneva samayā vṛddhyā ṣaḍekasyātiśāyane trayodaśa samasteṣu ṣaḍ dvyekātiśayena tu" },
      { type: "verse", number: "21", sanskrit: "एकं तुल्याधिकैः षट् च तारतम्यविकल्पनात् पञ्चविंशतिरित्येवं वृद्धैः क्षीणैश्च तावतः", text: "ekaṃ tulyādhikaiḥ ṣaṭ ca tāratamyavikalpanāt pañcaviṃśatirityevaṃ vṛddhaiḥ kṣīṇaiśca tāvataḥ" },
      { type: "verse", number: "22", sanskrit: "एकैकवृद्धिसमताक्षयैः षट् ते पुनश्च षट् एकक्षयद्वन्द्ववृद्ध्या सविपर्यययापि ते", text: "ekaikavṛddhisamatākṣayaiḥ ṣaṭ te punaśca ṣaṭ ekakṣayadvandvavṛddhyā saviparyayayāpi te" },
      { type: "verse", number: "23", sanskrit: "भेदा द्विषाष्टिर्निर्दिष्टास्त्रिषष्टिः स्वाथ्यकारणम् रोग्यवस्थासु युगपद् वृद्धिसाम्यक्षयानुगम्", text: "bhedā dviṣāṣṭirnirdiṣṭāstriṣaṣṭiḥ svāthyakāraṇam rogyavasthāsu yugapad vṛddhisāmyakṣayānugam" },
      { type: "verse", number: "24", sanskrit: "षट्कं हि दुर्बोधतरं विकारैरुपदेक्ष्यते प्रकृतिस्थं यदा पित्तं वृद्धो वायुः कफक्षये स्थानादादाय गात्रेषु यत्र यत्र विसर्पति", text: "ṣaṭkaṃ hi durbodhataraṃ vikārairupadekṣyate prakṛtisthaṃ yadā pittaṃ vṛddho vāyuḥ kaphakṣaye sthānādādāya gātreṣu yatra yatra visarpati" },
      { type: "verse", number: "25", sanskrit: "तदा भेदश्च दाहश्च तत्र तत्रानवस्थितौ गात्रोद्देशे तथा स्यातां बलहानिपरिश्रमौ", text: "tadā bhedaśca dāhaśca tatra tatrānavasthitau gātroddeśe tathā syātāṃ balahānipariśramau" },
      { type: "verse", number: "26", sanskrit: "प्रकुतिस्थं कफं क्षीणे पित्ते वायुर्यदा बली कर्षेत् कुर्यात् तदा शूलं सशैत्यस्तम्भगौरवम्", text: "prakutisthaṃ kaphaṃ kṣīṇe pitte vāyuryadā balī karṣet kuryāt tadā śūlaṃ saśaityastambhagauravam" },
      { type: "verse", number: "27", sanskrit: "प्रकृतिस्थं यदा वातं पित्तं वृद्धं कफक्षये संरुणद्धि तदा दाहः शूलं चास्योपजायते", text: "prakṛtisthaṃ yadā vātaṃ pittaṃ vṛddhaṃ kaphakṣaye saṃruṇaddhi tadā dāhaḥ śūlaṃ cāsyopajāyate" },
      { type: "verse", number: "28", sanskrit: "प्रकृतिस्थं कफं वृद्धं पित्तं वायुक्षये यदा सन्निरुन्ध्यात्तदा कुर्यात् सतन्द्रागौरव ज्वरम्", text: "prakṛtisthaṃ kaphaṃ vṛddhaṃ pittaṃ vāyukṣaye yadā sannirundhyāttadā kuryāt satandrāgaurava jvaram" },
      { type: "verse", number: "29", sanskrit: "प्रकृतिस्थं यदा वायुं वृद्धः पित्तक्षये कफः सन्निरुन्ध्यात्तदा कुर्याच्छीतकं गौरवं ज्वरम्", text: "prakṛtisthaṃ yadā vāyuṃ vṛddhaḥ pittakṣaye kaphaḥ sannirundhyāttadā kuryācchītakaṃ gauravaṃ jvaram" },
      { type: "verse", number: "30", sanskrit: "प्रकृतिस्थं यदा पित्तं वृद्धः श्लेष्मानिलक्षये सन्निरुन्ध्यात्तदा कुर्यान्मन्दाग्नित्वं शिरोग्रहम्", text: "prakṛtisthaṃ yadā pittaṃ vṛddhaḥ śleṣmānilakṣaye sannirundhyāttadā kuryānmandāgnitvaṃ śirograham" },
      { type: "verse", number: "31", sanskrit: "निद्रातन्द्रोपलेपांश्च हृद्रोगं गात्रगौरवम् ष्ठीवनं पित्तकफयोर्नखादीनां च पीतताम्", text: "nidrātandropalepāṃśca hṛdrogaṃ gātragauravam ṣṭhīvanaṃ pittakaphayornakhādīnāṃ ca pītatām" },
      { type: "verse", number: "32", sanskrit: "ये दोषवृद्धिक्षययोर्विकाराः कीर्तिताः पृथक् शेषेष्वपि तु तानेव कल्पयेत्तद्यथायथम्", text: "ye doṣavṛddhikṣayayorvikārāḥ kīrtitāḥ pṛthak śeṣeṣvapi tu tāneva kalpayettadyathāyatham" },
      { type: "verse", number: "33", sanskrit: "संसर्गाद्रसरुधिरादिभिस्तथैषां दोषाणां क्षयसमताविवृद्धिभेदैः आनन्त्यं तरतमयोगतश्च यातान् जानीयादवहितमानसो यथास्वम्", text: "saṃsargādrasarudhirādibhistathaiṣāṃ doṣāṇāṃ kṣayasamatāvivṛddhibhedaiḥ ānantyaṃ taratamayogataśca yātān jānīyādavahitamānaso yathāsvam" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 21,
    lang: "sa",
    content: [
      { type: "heading", heading: "Матра видхи — правила дозирования" },
      { type: "text", text: "Глава 21 Сутрастханы Астанга-санграхи посвящена теме «правила дозирования». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो दोषोपक्रमणीयमध्यायं व्याख्यास्याम इति हस्माहुरात्रेयो महर्षयः वातस्योपक्रमः स्नेहः स्वेदो मृदूनि स्निग्धोष्णमधुराम्ललवणानि संशोधनान्यभ्यवहार्याणि चाभ्यङ्गपूर्वमुपनाहनोपवेष्टनोन्मर्दनपरिषेकावगाहसंवाहन पीडनानि वित्रासनविध्मापनविस्मरणानि सुरासवविधानं स्नेहाश्चानेकयोनयो दीपनीयपाचनीयवातहरविरेचनीयद्रव्योपहितास्तथा शतपाकसहस्रपाकाः सर्वशः प्रयोगार्था बस्तयो बस्तिनियमो विशेषतस्तैलं मांसरसो ऽनुवासनानि सुखशीलता स्त्रीसम्पर्कवर्ज्यश्च हैमन्तो विधिः", text: "athāto doṣopakramaṇīyamadhyāyaṃ vyākhyāsyāma iti hasmāhurātreyo maharṣayaḥ vātasyopakramaḥ snehaḥ svedo mṛdūni snigdhoṣṇamadhurāmlalavaṇāni saṃśodhanānyabhyavahāryāṇi cābhyaṅgapūrvamupanāhanopaveṣṭanonmardanapariṣekāvagāhasaṃvāhana pīḍanāni vitrāsanavidhmāpanavismaraṇāni surāsavavidhānaṃ snehāścānekayonayo dīpanīyapācanīyavātaharavirecanīyadravyopahitāstathā śatapākasahasrapākāḥ sarvaśaḥ prayogārthā bastayo bastiniyamo viśeṣatastailaṃ māṃsaraso 'nuvāsanāni sukhaśīlatā strīsamparkavarjyaśca haimanto vidhiḥ" },
      { type: "verse", number: "2", sanskrit: "पित्तस्य सर्पिष्पानं सर्पिषा स्नेहनमधोदोषहरणं मधुरतिक्तकषायाणामौषधाभ्यवहार्याणामुपयोगो मृदुसुरभिशीतहृद्यानां गन्धानामुपसेवा परमशिशिरसुरभिसलिलमज्जनम् मनो ऽनुकूलसंस्पर्शसुखानां मुक्तामणिवैडूर्याश्मगर्भशङ्खशिलापद्मरागचन्द्रकान्तकान्ततरतरलावलीनां भ्रमरत्रासितसहस्रपत्रासितोत्पल कदलीदलनवमालिकाकुन्दमल्लिकादिविविधवर्णप्रसूनविरचितानां स्रजां च धारणमुरसा क्षणे क्षणे चाग्र्यचन्दनप्रियङ्गुकालेयकमृणालकर्पूरसुगन्धिशीतस्वच्छगन्धवारिभिः सकमलकुमुदकुवलयैर्भूमितलकवाटवातायनहर्म्यभित्तीनामभिप्रोक्षणम् श्रुतिसुखमृदुमधुरमनो ऽनुगानां गीतवादित्राणामभ्युदयानां च श्रवणम् अयन्त्रणैः समानविषयवेषचरितैरुत्सवोत्सवतरान्योन्यदर्शनैः सुहृद्भिः सहासनम् अनृतवचनविरहस्वभावसुरभितरवदनकुड्मलानां नातिस्पष्टाभिधायिनामनुपचारमधुरकोमलोल्लापानां प्रियाणामपत्यकानां सदयमाश्लेषः निर्दयं च तनुतरमृदुसुरभिनिवसनाभिर्मल्लिकामुकुलानुकारिमुक्ताफलप्रायालङ्काराभिः सहचरीनिनादसञ्जल्पोपजनितौत्सुक्यकलहंसानुनादितनूपुररशनाकलापशिञ्जितानुगमनसम्मुग्धमुग्धस्निग्धमृदुवचनाभिर्निजजघननिबिडकुचयुगलालङ्कारभारोद्वहनश्रमश्वसनकम्पितमध्यमुकुलितलोचनोत्पलाभिः किञ्चिद्विगलितनवयौवनाभिः प्रियङ्गसङ्गमात्रातिमात्रसुखास्वादविस्रंस्यमानांशुकैककालोपजातव्रीडावैलक्ष्यप्रगल्भतावैक्लव्यहर्षविषादविस्मयस्मितकोपप्रसादसाध्वसस्रस्तस्विन्नसर्वाङ्गद्रवीकृतहिमाङ्गरागाभिः समस्तदेहहृदयप्रह्लादकारिणीभिर्विलासवतीभिश्चतुरङ्गमिवानङ्गबलमङ्गैस्तनुभिरपि समुद्वहन्तीभिरङ्गनाभिराश्लेषः सकलरजनीकरकरनिकरावकीर्णशिशिरतराणि भवनतलसलिलपुलिनानि अतिसितसिकतोपास्तृततलमनोककाययन्त्रप्रवृत्तीवमलसलिलधारं धारागृहम् सागरानुकारितोयाशयोपतीरसुनिविष्टकुसुमितबहुविटपपृथुतुङ्गविविधतरतटरुहतरुनिवहबहलच्छायोपसञ्छन्नं घवलरक्तनीलनीरजरजोव्याप्तसमस्तजलविपुलसिकतिलतलोपकल्पितं दोलायमानगणतिथपृथुदृतिकलशसरणकरकस्रवदुदकप्रवाहाहितमृत्सौरभभूतलैकदेशं प्रलम्बमानाम्रजम्बूकदम्बविदुलनिचुलादिकिसलयमञ्जरीस्तबकप्रत्युप्तपटालिकं मुहुर्मुहुः पुरुषप्रयत्नप्रेरितघटमुखोद्गीर्णोशीरचन्दनानुविद्धावलग्नपतितशेष मुक्ताफलायमानजललवमुछ्रायविस्तारवदनिषिद्धदूरविस्तृतशीतवातप्रवेशमत्यर्थसन्तताम्बुशीतशीकराभिषेकप्रतिहतसन्तापदाहमोहश्रमक्लमपिपासमतिशयप्राप्तरामणीयकं हिमाचलस्पर्द्धिशैत्यमम्बुधरकाललीलाविडम्बि कायमानम् प्रफुल्लपद्मोत्पलपुण्डरीकसौगन्धिककोकनदशतपत्रपरागरागानुरञ्जितजलचरविहगगणकलनिनदरम्या दीर्घिकाः मधुपानलोभनिलीयमानालिकुलचलितलताप्रताननिपतितविविधकुसुमनिचयशयनरचनासव्यापारमृदुपवनान्युपवनानि विशेषतस्तु घृतं पयो विरेचनानि सौम्याः सर्वे भावाः दिवास्वप्नवर्ज्यश्च ग्रैष्मो विधिः", text: "pittasya sarpiṣpānaṃ sarpiṣā snehanamadhodoṣaharaṇaṃ madhuratiktakaṣāyāṇāmauṣadhābhyavahāryāṇāmupayogo mṛdusurabhiśītahṛdyānāṃ gandhānāmupasevā paramaśiśirasurabhisalilamajjanam mano 'nukūlasaṃsparśasukhānāṃ muktāmaṇivaiḍūryāśmagarbhaśaṅkhaśilāpadmarāgacandrakāntakāntatarataralāvalīnāṃ bhramaratrāsitasahasrapatrāsitotpala kadalīdalanavamālikākundamallikādivividhavarṇaprasūnaviracitānāṃ srajāṃ ca dhāraṇamurasā kṣaṇe kṣaṇe cāgryacandanapriyaṅgukāleyakamṛṇālakarpūrasugandhiśītasvacchagandhavāribhiḥ sakamalakumudakuvalayairbhūmitalakavāṭavātāyanaharmyabhittīnāmabhiprokṣaṇam śrutisukhamṛdumadhuramano 'nugānāṃ gītavāditrāṇāmabhyudayānāṃ ca śravaṇam ayantraṇaiḥ samānaviṣayaveṣacaritairutsavotsavatarānyonyadarśanaiḥ suhṛdbhiḥ sahāsanam anṛtavacanavirahasvabhāvasurabhitaravadanakuḍmalānāṃ nātispaṣṭābhidhāyināmanupacāramadhurakomalollāpānāṃ priyāṇāmapatyakānāṃ sadayamāśleṣaḥ nirdayaṃ ca tanutaramṛdusurabhinivasanābhirmallikāmukulānukārimuktāphalaprāyālaṅkārābhiḥ sahacarīninādasañjalpopajanitautsukyakalahaṃsānunāditanūpuraraśanākalāpaśiñjitānugamanasammugdhamugdhasnigdhamṛduvacanābhirnijajaghananibiḍakucayugalālaṅkārabhārodvahanaśramaśvasanakampitamadhyamukulitalocanotpalābhiḥ kiñcidvigalitanavayauvanābhiḥ priyaṅgasaṅgamātrātimātrasukhāsvādavisraṃsyamānāṃśukaikakālopajātavrīḍāvailakṣyapragalbhatāvaiklavyaharṣaviṣādavismayasmitakopaprasādasādhvasasrastasvinnasarvāṅgadravīkṛtahimāṅgarāgābhiḥ samastadehahṛdayaprahlādakāriṇībhirvilāsavatībhiścaturaṅgamivānaṅgabalamaṅgaistanubhirapi samudvahantībhiraṅganābhirāśleṣaḥ sakalarajanīkarakaranikarāvakīrṇaśiśiratarāṇi bhavanatalasalilapulināni atisitasikatopāstṛtatalamanokakāyayantrapravṛttīvamalasaliladhāraṃ dhārāgṛham sāgarānukāritoyāśayopatīrasuniviṣṭakusumitabahuviṭapapṛthutuṅgavividhatarataṭaruhatarunivahabahalacchāyopasañchannaṃ ghavalaraktanīlanīrajarajovyāptasamastajalavipulasikatilatalopakalpitaṃ dolāyamānagaṇatithapṛthudṛtikalaśasaraṇakarakasravadudakapravāhāhitamṛtsaurabhabhūtalaikadeśaṃ pralambamānāmrajambūkadambavidulaniculādikisalayamañjarīstabakapratyuptapaṭālikaṃ muhurmuhuḥ puruṣaprayatnapreritaghaṭamukhodgīrṇośīracandanānuviddhāvalagnapatitaśeṣa muktāphalāyamānajalalavamuchrāyavistāravadaniṣiddhadūravistṛtaśītavātapraveśamatyarthasantatāmbuśītaśīkarābhiṣekapratihatasantāpadāhamohaśramaklamapipāsamatiśayaprāptarāmaṇīyakaṃ himācalasparddhiśaityamambudharakālalīlāviḍambi kāyamānam praphullapadmotpalapuṇḍarīkasaugandhikakokanadaśatapatraparāgarāgānurañjitajalacaravihagagaṇakalaninadaramyā dīrghikāḥ madhupānalobhanilīyamānālikulacalitalatāpratānanipatitavividhakusumanicayaśayanaracanāsavyāpāramṛdupavanānyupavanāni viśeṣatastu ghṛtaṃ payo virecanāni saumyāḥ sarve bhāvāḥ divāsvapnavarjyaśca graiṣmo vidhiḥ" },
      { type: "verse", number: "3", sanskrit: "श्लेष्मणः पुनर्विधिविहितानि तीक्ष्णानि संशोधनानि रूक्षप्रायाण्यभ्यवहार्याणि कटुतिक्तकषायोपहितानि तीक्ष्णानि दीर्घकालस्थितानि हृद्यानि मद्यानि धावनलङ्घनप्लवनजागरणानियुद्धयुद्धव्यवायव्यायामरूक्षोन्मर्दनस्नानोच्छादनानि विशेषतः क्षौद्रं यूषो वमनानि सर्वशश्चोपवासः सधूमगण्डूषः सुखप्रतिषेधः सुखार्थमेव वासन्तिको विधिरिति भवन्ति चात्र", text: "śleṣmaṇaḥ punarvidhivihitāni tīkṣṇāni saṃśodhanāni rūkṣaprāyāṇyabhyavahāryāṇi kaṭutiktakaṣāyopahitāni tīkṣṇāni dīrghakālasthitāni hṛdyāni madyāni dhāvanalaṅghanaplavanajāgaraṇāniyuddhayuddhavyavāyavyāyāmarūkṣonmardanasnānocchādanāni viśeṣataḥ kṣaudraṃ yūṣo vamanāni sarvaśaścopavāsaḥ sadhūmagaṇḍūṣaḥ sukhapratiṣedhaḥ sukhārthameva vāsantiko vidhiriti bhavanti cātra" },
      { type: "verse", number: "4", sanskrit: "उपक्रमः पृथग्दोषान् यो ऽयमुद्दिश्य कीर्तितः संसर्गसन्निपातेषु तं यथास्वं विकल्पयेत्", text: "upakramaḥ pṛthagdoṣān yo 'yamuddiśya kīrtitaḥ saṃsargasannipāteṣu taṃ yathāsvaṃ vikalpayet" },
      { type: "verse", number: "5", sanskrit: "ग्रैष्मः प्रायो मरुत्पित्ते वासन्तः कफमारुते मरुतो योगवाहित्वात् कफपित्ते तु शारदः", text: "graiṣmaḥ prāyo marutpitte vāsantaḥ kaphamārute maruto yogavāhitvāt kaphapitte tu śāradaḥ" },
      { type: "verse", number: "6", sanskrit: "योज्याः पट्वम्लमधुरा वायौ क्रुद्धे रसाःक्रमात् पित्ते पित्तस्ततः स्वादुः कषायश्च रसो हितः", text: "yojyāḥ paṭvamlamadhurā vāyau kruddhe rasāḥkramāt pitte pittastataḥ svāduḥ kaṣāyaśca raso hitaḥ" },
      { type: "verse", number: "7", sanskrit: "कटुकः प्राक् ततस्तिक्तः कषायो ऽन्ते कफामये", text: "kaṭukaḥ prāk tatastiktaḥ kaṣāyo 'nte kaphāmaye" },
      { type: "verse", number: "8", sanskrit: "चयप्रकोपप्रशमा वायोर्ग्रीष्मादिषु त्रिषु वर्षादिषु तु पित्तस्य श्लेष्मणेः शिशिरादिषु", text: "cayaprakopapraśamā vāyorgrīṣmādiṣu triṣu varṣādiṣu tu pittasya śleṣmaṇeḥ śiśirādiṣu" },
      { type: "verse", number: "9", sanskrit: "चीयते लघुरूक्षाभिरोषधीभिः समीरणः तद्विधस्तद्विधे देहे कालस्यौष्ण्यान्न कुप्यति", text: "cīyate laghurūkṣābhiroṣadhībhiḥ samīraṇaḥ tadvidhastadvidhe dehe kālasyauṣṇyānna kupyati" },
      { type: "verse", number: "10", sanskrit: "अद्भिरम्लविपाकाभिरोषधीभिश्च तादृशम् पित्तं याति चयं कोपं न तु कालस्य शैत्यतः", text: "adbhiramlavipākābhiroṣadhībhiśca tādṛśam pittaṃ yāti cayaṃ kopaṃ na tu kālasya śaityataḥ" },
      { type: "verse", number: "11", sanskrit: "चीयते स्निग्धशीताभिरुदकौषधिभिः कफः तुल्ये ऽपि काले देहे च स्कन्नत्वान्न प्रकुप्यति", text: "cīyate snigdhaśītābhirudakauṣadhibhiḥ kaphaḥ tulye 'pi kāle dehe ca skannatvānna prakupyati" },
      { type: "verse", number: "12", sanskrit: "इति कालस्वभावो ऽयम् आहारादिवशात् पुनः चयादीन् यान्ति सद्यो ऽपि दोषाः काले ऽपि वा न तु", text: "iti kālasvabhāvo 'yam āhārādivaśāt punaḥ cayādīn yānti sadyo 'pi doṣāḥ kāle 'pi vā na tu" },
      { type: "verse", number: "13", sanskrit: "व्याप्नोति सहसा देहमापादतलमस्तकम् निवर्तते तु कुपितो मलो ऽल्पाल्पं जलौघवत्", text: "vyāpnoti sahasā dehamāpādatalamastakam nivartate tu kupito malo 'lpālpaṃ jalaughavat" },
      { type: "verse", number: "14", sanskrit: "चय एव जयेद्दोषं कुपितं त्वविरोधयन् सर्वकोपे बलीयांसं शेषदोषाविरोधतः", text: "caya eva jayeddoṣaṃ kupitaṃ tvavirodhayan sarvakope balīyāṃsaṃ śeṣadoṣāvirodhataḥ" },
      { type: "verse", number: "15", sanskrit: "क्रमान्मरुत्पित्तकफान् सर्वत्र सदृशे बले वातादीनां यथापूर्वं यतः स्वाभाविकं बलम्", text: "kramānmarutpittakaphān sarvatra sadṛśe bale vātādīnāṃ yathāpūrvaṃ yataḥ svābhāvikaṃ balam" },
      { type: "verse", number: "16", sanskrit: "ऊचे पराशरो ऽप्यर्थममुमेव प्रमाणयन् यथोपन्यासतः प्राप्तमादौ दोषभिषग्जितम्", text: "ūce parāśaro 'pyarthamamumeva pramāṇayan yathopanyāsataḥ prāptamādau doṣabhiṣagjitam" },
      { type: "verse", number: "17", sanskrit: "नेतृभङ्गेन दृष्टो हि समं सैन्यपराजयः", text: "netṛbhaṅgena dṛṣṭo hi samaṃ sainyaparājayaḥ" },
      { type: "verse", number: "18", sanskrit: "स्थानतः केचिदिच्छन्ति प्राक् तावच्छ्लेष्मणो वधम् शिरस्युरसि कण्ठे च प्रलिप्ते ऽन्नरुचिः कुतः", text: "sthānataḥ kecidicchanti prāk tāvacchleṣmaṇo vadham śirasyurasi kaṇṭhe ca pralipte 'nnaruciḥ kutaḥ" },
      { type: "verse", number: "19", sanskrit: "तदभावे कथं भोज्यपानद्रव्यावचारणम् असत्यभ्यवहारे च कुतो दोषविनिग्रहः", text: "tadabhāve kathaṃ bhojyapānadravyāvacāraṇam asatyabhyavahāre ca kuto doṣavinigrahaḥ" },
      { type: "verse", number: "20", sanskrit: "तस्मादादौ कफो घात्यः कायद्वारार्गलो हि सः मध्यस्थायि यतः पित्तमाशुकारि च चिन्त्यते", text: "tasmādādau kapho ghātyaḥ kāyadvārārgalo hi saḥ madhyasthāyi yataḥ pittamāśukāri ca cintyate" },
      { type: "verse", number: "21", sanskrit: "अतो वातसखस्यास्य कुर्यात्तदनु निग्रहम् अत एव च पित्तादिःकफान्तो ऽन्यैःक्रमःस्मृतः", text: "ato vātasakhasyāsya kuryāttadanu nigraham ata eva ca pittādiḥkaphānto 'nyaiḥkramaḥsmṛtaḥ" },
      { type: "verse", number: "22", sanskrit: "सुश्रुतश्च न सर्वत्र मतमेतत् ब्रवीति तु जयेज्ज्वरे ऽतिसारेच क्रमात् पित्तकफानिलान्", text: "suśrutaśca na sarvatra matametat bravīti tu jayejjvare 'tisāreca kramāt pittakaphānilān" },
      { type: "verse", number: "23", sanskrit: "प्रायेण तापात्मतया ज्वरे तेजो विशिष्यते विशश्च सरणं पित्तात्तथा च मृदुकोष्ठता", text: "prāyeṇa tāpātmatayā jvare tejo viśiṣyate viśaśca saraṇaṃ pittāttathā ca mṛdukoṣṭhatā" },
      { type: "verse", number: "24", sanskrit: "तस्यचानुबलःश्लेष्मा गौरवापक्तिजाड्यकृत् वायुश्च वर्द्धते ऽवश्यं यात्स्वहस्सु तयोःक्षये", text: "tasyacānubalaḥśleṣmā gauravāpaktijāḍyakṛt vāyuśca varddhate 'vaśyaṃ yātsvahassu tayoḥkṣaye" },
      { type: "verse", number: "25", sanskrit: "ज्वरातिसारयोस्तस्मादेष दोषजये क्रमः", text: "jvarātisārayostasmādeṣa doṣajaye kramaḥ" },
      { type: "verse", number: "26", sanskrit: "कफपित्तानिलानन्ये क्रमादाहुस्तयोरपि यस्मादामाशयोत्क्लेशात् भूयिष्ठं तत्समुद्भवः", text: "kaphapittānilānanye kramādāhustayorapi yasmādāmāśayotkleśāt bhūyiṣṭhaṃ tatsamudbhavaḥ" },
      { type: "verse", number: "27", sanskrit: "क्रमेणाद्येन तत्रापि प्रवृद्धान् स्वाश्रये स्थितान् स्वाश्रयेषु प्रदुष्टानां स्थितैव ह्याशुकारिता", text: "krameṇādyena tatrāpi pravṛddhān svāśraye sthitān svāśrayeṣu praduṣṭānāṃ sthitaiva hyāśukāritā" },
      { type: "verse", number: "28", sanskrit: "विज्ञाय कर्मभिः स्वैः स्वैर्दोषोद्रेकं यथाबलम् भेषजं योजयेत्तत्तत् तन्त्रीकुर्यान्न तु क्रमम्", text: "vijñāya karmabhiḥ svaiḥ svairdoṣodrekaṃ yathābalam bheṣajaṃ yojayettattat tantrīkuryānna tu kramam" },
      { type: "verse", number: "29", sanskrit: "प्रयोगः शमयेद् व्याधिं योन्यमन्यमुदीरयेत् नासौ विशुद्धः शुद्धस्तु शमयेद्यो न कोपयेत्", text: "prayogaḥ śamayed vyādhiṃ yonyamanyamudīrayet nāsau viśuddhaḥ śuddhastu śamayedyo na kopayet" },
      { type: "verse", number: "30", sanskrit: "क्रुद्धं मलमलं जेतुं नाल्पभावादुभावपि दोषा दोषात्मकत्वाच्च न समे ऽपि परस्परम्", text: "kruddhaṃ malamalaṃ jetuṃ nālpabhāvādubhāvapi doṣā doṣātmakatvācca na same 'pi parasparam" },
      { type: "verse", number: "31", sanskrit: "शीतद्रवाम्ललवणकट्वादिगुणतुल्यता दृष्टा मिथश्च दोषेषु नातोन्योन्यं जयन्ति ते", text: "śītadravāmlalavaṇakaṭvādiguṇatulyatā dṛṣṭā mithaśca doṣeṣu nātonyonyaṃ jayanti te" },
      { type: "verse", number: "32", sanskrit: "आरम्भकं विरोधे ऽपि मिथो यद्यत् गुणत्रयम् विश्वस्य दृष्टं युगपद्व्याधेर्दोषत्रयं तथा", text: "ārambhakaṃ virodhe 'pi mitho yadyat guṇatrayam viśvasya dṛṣṭaṃ yugapadvyādherdoṣatrayaṃ tathā" },
      { type: "verse", number: "33", sanskrit: "वायुरामान्वयः सार्तिराध्मानकृदसञ्चरः दुर्गन्धमसितं पित्तं कटुकं बहलं गुरु", text: "vāyurāmānvayaḥ sārtirādhmānakṛdasañcaraḥ durgandhamasitaṃ pittaṃ kaṭukaṃ bahalaṃ guru" },
      { type: "verse", number: "34", sanskrit: "आविलस्तन्तुमांस्त्यानः प्रलेपी पिच्छिलः कफः विपर्यये तु पक्वत्वं तथा ताम्रं समेचकम्", text: "āvilastantumāṃstyānaḥ pralepī picchilaḥ kaphaḥ viparyaye tu pakvatvaṃ tathā tāmraṃ samecakam" },
      { type: "verse", number: "35", sanskrit: "पीतञ्च पित्तमच्छञ्च श्लेष्माच्छः पिण्डितो ऽथवा विशदश्च सफेनश्च धवलो मधुरो रसे", text: "pītañca pittamacchañca śleṣmācchaḥ piṇḍito 'thavā viśadaśca saphenaśca dhavalo madhuro rase" },
      { type: "verse", number: "36", sanskrit: "ऊष्मणो ऽल्पबलत्वेन धातुमाद्यमपाचितम् दुष्टमामाशयगतं रसमामं प्रचक्षते", text: "ūṣmaṇo 'lpabalatvena dhātumādyamapācitam duṣṭamāmāśayagataṃ rasamāmaṃ pracakṣate" },
      { type: "verse", number: "37", sanskrit: "अन्ये दोषेभ्य एवातिदुष्टेभ्यो ऽन्योन्यमूर्च्छनात् कोद्रवेभ्यो विषस्येव वदन्त्यामस्य सम्भवम्", text: "anye doṣebhya evātiduṣṭebhyo 'nyonyamūrcchanāt kodravebhyo viṣasyeva vadantyāmasya sambhavam" },
      { type: "verse", number: "38", sanskrit: "आमेन तेन सम्पृक्ता दोषा दूष्याश्च दूषिताः समा इत्युपदिश्यन्ते ये च रोगास्तदुद्भवाः", text: "āmena tena sampṛktā doṣā dūṣyāśca dūṣitāḥ samā ityupadiśyante ye ca rogāstadudbhavāḥ" },
      { type: "verse", number: "39", sanskrit: "सर्वदेहप्रविसृतान् सामान् दोषान् न निर्हरेत् लीनान् धातुष्वनुत्क्लिष्टान् फलादामाद्रसानिव", text: "sarvadehapravisṛtān sāmān doṣān na nirharet līnān dhātuṣvanutkliṣṭān phalādāmādrasāniva" },
      { type: "verse", number: "40", sanskrit: "आश्नयस्य हि नाशाय ते स्युर्दुर्निर्हरत्वतः पाचनैर्दीपनैःस्रेहैस्तान् स्वेदैश्चपरिष्कृतान्", text: "āśnayasya hi nāśāya te syurdurnirharatvataḥ pācanairdīpanaiḥsrehaistān svedaiścapariṣkṛtān" },
      { type: "verse", number: "41", sanskrit: "शोधयेच्छोधनैः काले यथासन्नं यथाबलम् हन्त्याशुयुक्तं वक्त्रेण द्रव्यमामाशयान्मलान्", text: "śodhayecchodhanaiḥ kāle yathāsannaṃ yathābalam hantyāśuyuktaṃ vaktreṇa dravyamāmāśayānmalān" },
      { type: "verse", number: "42", sanskrit: "घ्राणेन चोर्ध्वजत्रूत्थान् पक्वाधानात् गुदेन तु उत्क्लिष्टानध ऊर्ध्वं वा न चामान् वहतः स्वयम्", text: "ghrāṇena cordhvajatrūtthān pakvādhānāt gudena tu utkliṣṭānadha ūrdhvaṃ vā na cāmān vahataḥ svayam" },
      { type: "verse", number: "43", sanskrit: "धारयेदौषधैर्दोषान् विधृतास्ते हि कुर्वते रोगानुत्पादनिर्दिष्ठानतिस्थौल्यादिकान् गदान्", text: "dhārayedauṣadhairdoṣān vidhṛtāste hi kurvate rogānutpādanirdiṣṭhānatisthaulyādikān gadān" },
      { type: "verse", number: "44", sanskrit: "प्रवृत्तान् प्रागतो दोषानुपेक्षेत हिताशिनः विबद्धान् पाचनैस्तैस्तैः पाचयन् निर्हरेत वा", text: "pravṛttān prāgato doṣānupekṣeta hitāśinaḥ vibaddhān pācanaistaistaiḥ pācayan nirhareta vā" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 22,
    lang: "sa",
    content: [
      { type: "heading", heading: "Вастья видхи — клизменная терапия" },
      { type: "text", text: "Глава 22 Сутрастханы Астанга-санграхи посвящена теме «клизменная терапия». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो रोगभेदीयमध्यायं व्याख्यास्यामः इति हस्माहुरात्रेयादयो महर्षयः सप्तविधाः खलु रोगा भवन्ति सहगर्भजातपीडाकालप्रभावस्वभावजाः ते तु पृथग्द्विविधाः तत्र सहजाः शुक्रार्तवदोषान्वयाः कुष्ठार्शोमेहादयः पितृजा मातृजाश्च गर्भजा जनन्यभिवारात् कौब्जपाङ्गुल्यपैग्गल्यकिलासादयो ऽन्नरसजा दौहृदविमाननजाश्च जातजाः स्वापचारात् सन्तर्पणजा अपतर्पणजाश्च पीडाकृताः क्षतभङ्गप्रहारक्रोधशोकभयादयः शारीरमानसाश्च कालजाः शीतादिकृता ज्वरादयो व्यापन्नजा असंरक्षणजाश्च प्रभावजा देवगुरूल्लङ्घनशापार्थवणादिकृता ज्वरादयः पिशाचादयश्च स्वभावजाः क्षुत्पिपासाज्वरादयः कालजा अकालजाश्च तत्र कालजा रक्सणकृताः अरक्षणजा अकालजाः त एते समासतः पुनर्द्विविधा भवन्ति प्रत्युत्पन्नकर्मजाः पूर्वकर्मजाश्च तत्र रोगोत्पत्तिं प्रति प्रत्युत्पन्नं कर्म यदनेनैव शरीरेण दृष्टमदृष्टञ्चोद्दिश्याप्तोपदिष्टानां विहितानां प्रतिषिद्धानामननुष्ठानमनुष्ठानं वा जन्मान्तरातीतेन तु पूर्वम् तत्तु पुनर्दैवाख्यमुक्तञ्च नियतानियतभेदेन प्राक् तस्माद् दृष्टहेतवः प्रत्युत्पन्नकर्मजाः विपरीता दैवजन्मानः अल्पनिदाना महारुजाश्चोभयात्मकाः", text: "athāto rogabhedīyamadhyāyaṃ vyākhyāsyāmaḥ iti hasmāhurātreyādayo maharṣayaḥ saptavidhāḥ khalu rogā bhavanti sahagarbhajātapīḍākālaprabhāvasvabhāvajāḥ te tu pṛthagdvividhāḥ tatra sahajāḥ śukrārtavadoṣānvayāḥ kuṣṭhārśomehādayaḥ pitṛjā mātṛjāśca garbhajā jananyabhivārāt kaubjapāṅgulyapaiggalyakilāsādayo 'nnarasajā dauhṛdavimānanajāśca jātajāḥ svāpacārāt santarpaṇajā apatarpaṇajāśca pīḍākṛtāḥ kṣatabhaṅgaprahārakrodhaśokabhayādayaḥ śārīramānasāśca kālajāḥ śītādikṛtā jvarādayo vyāpannajā asaṃrakṣaṇajāśca prabhāvajā devagurūllaṅghanaśāpārthavaṇādikṛtā jvarādayaḥ piśācādayaśca svabhāvajāḥ kṣutpipāsājvarādayaḥ kālajā akālajāśca tatra kālajā raksaṇakṛtāḥ arakṣaṇajā akālajāḥ ta ete samāsataḥ punardvividhā bhavanti pratyutpannakarmajāḥ pūrvakarmajāśca tatra rogotpattiṃ prati pratyutpannaṃ karma yadanenaiva śarīreṇa dṛṣṭamadṛṣṭañcoddiśyāptopadiṣṭānāṃ vihitānāṃ pratiṣiddhānāmananuṣṭhānamanuṣṭhānaṃ vā janmāntarātītena tu pūrvam tattu punardaivākhyamuktañca niyatāniyatabhedena prāk tasmād dṛṣṭahetavaḥ pratyutpannakarmajāḥ viparītā daivajanmānaḥ alpanidānā mahārujāścobhayātmakāḥ" },
      { type: "verse", number: "2", sanskrit: "तत्र यथास्वं प्रतिपक्षशीलनात् पूर्वेषां रोगाणामुपशमः सत्येव विपक्षशीलने ऽनिष्टकर्मक्षयात् दैविकानाम् दोषकर्मक्षयादन्येषाम् अन्ये पुनः प्रत्युत्पन्नं कर्म परकृतमपि वर्णयन्ति तच्च पराभिसंस्कारमाचक्षते एवञ्चाहुः यदि स्वयं कृतादेवकर्मणः कार्यानिर्वृत्तिः स्यात् न दृष्टपुरुषान्तरकृतात् किमिति विद्वानपि पराचरितयोरुपकारापकारयोः सुखदुःखानुरोधात्तोषरोषौ प्रतिकर्तव्यचित्तं वा प्रतिपद्यते एवमेते व्याधयो द्विविधाः सन्तः त्रिविधा जायन्ते ततश्च दोषवन्तो भूयः सप्तविधाः", text: "tatra yathāsvaṃ pratipakṣaśīlanāt pūrveṣāṃ rogāṇāmupaśamaḥ satyeva vipakṣaśīlane 'niṣṭakarmakṣayāt daivikānām doṣakarmakṣayādanyeṣām anye punaḥ pratyutpannaṃ karma parakṛtamapi varṇayanti tacca parābhisaṃskāramācakṣate evañcāhuḥ yadi svayaṃ kṛtādevakarmaṇaḥ kāryānirvṛttiḥ syāt na dṛṣṭapuruṣāntarakṛtāt kimiti vidvānapi parācaritayorupakārāpakārayoḥ sukhaduḥkhānurodhāttoṣaroṣau pratikartavyacittaṃ vā pratipadyate evamete vyādhayo dvividhāḥ santaḥ trividhā jāyante tataśca doṣavanto bhūyaḥ saptavidhāḥ" },
      { type: "verse", number: "3", sanskrit: "सकलो ऽपि चायं रोगसमूहः प्रतिकारवानायुर्वेदविहितमुपदेशमपेक्षते यस्मान्नियतहेतुको ऽप्यामयः सम्यक् भिषगादेशानुष्ठानादुपात्तायुस्संस्कारापरिक्षये जातोपि वा सह्यवेदनतां प्रतिपद्यते अनुपक्रम्यमाणस्तु सर्व एव प्रायशो भिनत्यकण्डे स्वयमपि च दैवान्निदानाल्पतया वा निवर्तमानष्षोडशगुणसमुदित क्रियोपलम्भादाशुतरमपरिक्लिष्टस्य चापगच्छति अनियतफलदायिनि तु दैवे हिताभ्यासरतस्या ऽवकाशमेव न लभते व्याधिः तस्मान्न कस्याञ्चिदवस्थायामात्मवान् हिताहितयोः तुल्यदर्शी स्यात् त्रिविधाश्च पुनर्व्याधयो मृदुमध्याधिमात्रभेदेन तत्राल्पलक्षणा मृदवो मध्यलक्षणा मध्याः सम्पूर्णलक्षणास्त्वधिमात्राः ते पुनः सुखसाध्यादिविशेषेण चतुर्विधाः प्रागुपदिष्टाः सुबहुशो ऽपिच भिद्यमाना व्याधयो निजागन्तुतां न व्यभिचरन्ति", text: "sakalo 'pi cāyaṃ rogasamūhaḥ pratikāravānāyurvedavihitamupadeśamapekṣate yasmānniyatahetuko 'pyāmayaḥ samyak bhiṣagādeśānuṣṭhānādupāttāyussaṃskārāparikṣaye jātopi vā sahyavedanatāṃ pratipadyate anupakramyamāṇastu sarva eva prāyaśo bhinatyakaṇḍe svayamapi ca daivānnidānālpatayā vā nivartamānaṣṣoḍaśaguṇasamudita kriyopalambhādāśutaramaparikliṣṭasya cāpagacchati aniyataphaladāyini tu daive hitābhyāsaratasyā 'vakāśameva na labhate vyādhiḥ tasmānna kasyāñcidavasthāyāmātmavān hitāhitayoḥ tulyadarśī syāt trividhāśca punarvyādhayo mṛdumadhyādhimātrabhedena tatrālpalakṣaṇā mṛdavo madhyalakṣaṇā madhyāḥ sampūrṇalakṣaṇāstvadhimātrāḥ te punaḥ sukhasādhyādiviśeṣeṇa caturvidhāḥ prāgupadiṣṭāḥ subahuśo 'pica bhidyamānā vyādhayo nijāgantutāṃ na vyabhicaranti" },
      { type: "verse", number: "4", sanskrit: "तत्र निजास्तु दोषोत्थाः तेषु पूर्वं वातादयो वैषम्यमापद्यन्ते ततो व्यथाभिनिर्वर्तते बाह्यहेतुजास्त्वागन्तवः तेषु प्राहरेण व्यथा पूर्वमुपजायते ततो दोषवैषम्यम् दोषवैषम्येणैव च बहुरूपा रुगनुबध्यते प्रवर्द्धते च एवञ्च कृत्वा न दोषव्यतिरेकेण रोगानुबन्धः केवलं पौर्वापर्ये विशेषः तस्मादेकाकारा एवरोगा रुक्सामान्यात् असङ्ख्यभेदा वा प्रत्येकं समुत्थानस्थानसंस्थानवर्णनामवेदनाप्रभावो पक्वमविशेषात् यथास्थूलं यथास्वमेवोपदेक्ष्यन्ते असङ्ख्येयत्वाच्च दोषलिङ्गैरेव रोगानुपक्रमं च विभजेत्", text: "tatra nijāstu doṣotthāḥ teṣu pūrvaṃ vātādayo vaiṣamyamāpadyante tato vyathābhinirvartate bāhyahetujāstvāgantavaḥ teṣu prāhareṇa vyathā pūrvamupajāyate tato doṣavaiṣamyam doṣavaiṣamyeṇaiva ca bahurūpā ruganubadhyate pravarddhate ca evañca kṛtvā na doṣavyatirekeṇa rogānubandhaḥ kevalaṃ paurvāparye viśeṣaḥ tasmādekākārā evarogā ruksāmānyāt asaṅkhyabhedā vā pratyekaṃ samutthānasthānasaṃsthānavarṇanāmavedanāprabhāvo pakvamaviśeṣāt yathāsthūlaṃ yathāsvamevopadekṣyante asaṅkhyeyatvācca doṣaliṅgaireva rogānupakramaṃ ca vibhajet" },
      { type: "verse", number: "5", sanskrit: "दोषा एव हि सर्वरोगककारणम् यथैव शकुनिः सर्वतः परिपतन् दिवसं स्वां च्छायां नातिवर्तते यथा वा कृत्स्नं विकारजातं वैश्वरूप्येण व्यवस्ह्तितं गुणत्रयमप्यतिरिच्य न वर्तते तथैवेदमपि कृत्स्नं विकारजातं दोषत्रयमिति यथा च विद्युद्वर्षादयो नभसि भवन्ति न त्ववश्यं निमित्ततस्त्ववश्यमपि तरङ्गबुद्बुदादयश्चाम्भसि तथा दोषेषु रोगाः", text: "doṣā eva hi sarvarogakakāraṇam yathaiva śakuniḥ sarvataḥ paripatan divasaṃ svāṃ cchāyāṃ nātivartate yathā vā kṛtsnaṃ vikārajātaṃ vaiśvarūpyeṇa vyavashtitaṃ guṇatrayamapyatiricya na vartate tathaivedamapi kṛtsnaṃ vikārajātaṃ doṣatrayamiti yathā ca vidyudvarṣādayo nabhasi bhavanti na tvavaśyaṃ nimittatastvavaśyamapi taraṅgabudbudādayaścāmbhasi tathā doṣeṣu rogāḥ" },
      { type: "verse", number: "6", sanskrit: "त्रिविधन्तु निमित्तमेषामसात्म्येन्द्रियार्थसंयोगः पज्ञापराधाः परिणामश्च ते पुनः प्रत्येकमतियोगायोगमिथ्यायोगभेदात् त्रिधा भिद्यन्ते तत्र यथास्वं चक्षुरादीन्द्रियाणां रूपादिभिरर्थैरतिसंसर्गो ऽतियोगः अल्पशो नैव वा संसर्गस्त्वयोगः सूक्ष्मातिदूरान्तिकस्थातिभास्वत्भरवाप्रियविकृतादिदशनम् द्विष्टात्युच्चपरुषभीषणादिश्रवणम् पूत्यमेध्यातितीक्ष्णोग्रप्रतिकूलाद्याघ्राणम् स्वभावादिभिराहारकल्पनाविशेषायतनैरपथ्यानां रसानामभ्यवहारः तथा स्नानादीनां शीतोष्णादीनाञ्च स्पृश्यानामयथावदुपसेवनमशुचिभूताभिघातविषवातादिसंस्पर्शश्च भिथ्यायोगः", text: "trividhantu nimittameṣāmasātmyendriyārthasaṃyogaḥ pajñāparādhāḥ pariṇāmaśca te punaḥ pratyekamatiyogāyogamithyāyogabhedāt tridhā bhidyante tatra yathāsvaṃ cakṣurādīndriyāṇāṃ rūpādibhirarthairatisaṃsargo 'tiyogaḥ alpaśo naiva vā saṃsargastvayogaḥ sūkṣmātidūrāntikasthātibhāsvatbharavāpriyavikṛtādidaśanam dviṣṭātyuccaparuṣabhīṣaṇādiśravaṇam pūtyamedhyātitīkṣṇograpratikūlādyāghrāṇam svabhāvādibhirāhārakalpanāviśeṣāyatanairapathyānāṃ rasānāmabhyavahāraḥ tathā snānādīnāṃ śītoṣṇādīnāñca spṛśyānāmayathāvadupasevanamaśucibhūtābhighātaviṣavātādisaṃsparśaśca bhithyāyogaḥ" },
      { type: "verse", number: "7", sanskrit: "कायवाङ्मनोभेदेन तु त्रिविधमप्यहितं कर्म प्रज्ञापराधः तत्र कायादिकर्मणो ऽतिप्रवृत्तिरतियोगः अल्पशो नैव वा प्रवृत्तिरयोगः वेगोदीरणधारणविषमाङ्गेचष्टनस्खलनकण्डूयनप्रहारप्राणायामादि तथा क्षुत्पिपासार्धभुक्तभाषणादि भयशे केर्ष्यामात्सर्यादि दशविधं चाकुशलं कर्म यथास्वं मिथ्यायोगः परिणामः काल उच्यते सो ऽपि शीतोष्णवर्षभेदात्त्रिधा तत्रालितिमात्रस्वलक्षणः कालो ऽतियोगः हीनस्वलक्षणस्त्वयोगः विपरीतो मिथ्यायोगः त एते ऽतियोगादयः सामान्यतो ऽनुपशयलक्षणाः सर्वो वा प्रज्ञापराध एवायं यदेषामविवर्जनम् अर्थकर्मकालाः पुनःसम्यग्योगेनोपशयात् भूयिष्ठं स्वास्थ्यहेतवः तत्रापि रसवर्ज्या विषया यथायथमिन्द्रियं बाधन्ते ऽनुगृह्णन्ति च शेषा रसकर्मकालास्तु सर्वं देहं अपि च", text: "kāyavāṅmanobhedena tu trividhamapyahitaṃ karma prajñāparādhaḥ tatra kāyādikarmaṇo 'tipravṛttiratiyogaḥ alpaśo naiva vā pravṛttirayogaḥ vegodīraṇadhāraṇaviṣamāṅgecaṣṭanaskhalanakaṇḍūyanaprahāraprāṇāyāmādi tathā kṣutpipāsārdhabhuktabhāṣaṇādi bhayaśe kerṣyāmātsaryādi daśavidhaṃ cākuśalaṃ karma yathāsvaṃ mithyāyogaḥ pariṇāmaḥ kāla ucyate so 'pi śītoṣṇavarṣabhedāttridhā tatrālitimātrasvalakṣaṇaḥ kālo 'tiyogaḥ hīnasvalakṣaṇastvayogaḥ viparīto mithyāyogaḥ ta ete 'tiyogādayaḥ sāmānyato 'nupaśayalakṣaṇāḥ sarvo vā prajñāparādha evāyaṃ yadeṣāmavivarjanam arthakarmakālāḥ punaḥsamyagyogenopaśayāt bhūyiṣṭhaṃ svāsthyahetavaḥ tatrāpi rasavarjyā viṣayā yathāyathamindriyaṃ bādhante 'nugṛhṇanti ca śeṣā rasakarmakālāstu sarvaṃ dehaṃ api ca" },
      { type: "verse", number: "8", sanskrit: "सर्वभावानां भावाभावौ नान्तरेण योगातियोगादीन् व्यवस्येत् सर्वेषां पुनर्विकाराणां निदानदोषदूष्याविशेषेभ्यो भावाभावविशेषा भवन्ति यदा ह्येते त्रयो निदानादिविशेषात् नान्योन्यमनुबध्नन्तीषद्वानुबध्नन्त्यबला वा न तदामिनिर्वर्त्तन्ते व्याधर्याश्चरा द्वाभिनिर्वर्त्तन्ते तनवो वा भवन्त्यसम्पूर्णलिङ्गा वा विपर्यये तु विपरीताः", text: "sarvabhāvānāṃ bhāvābhāvau nāntareṇa yogātiyogādīn vyavasyet sarveṣāṃ punarvikārāṇāṃ nidānadoṣadūṣyāviśeṣebhyo bhāvābhāvaviśeṣā bhavanti yadā hyete trayo nidānādiviśeṣāt nānyonyamanubadhnantīṣadvānubadhnantyabalā vā na tadāminirvarttante vyādharyāścarā dvābhinirvarttante tanavo vā bhavantyasampūrṇaliṅgā vā viparyaye tu viparītāḥ" },
      { type: "verse", number: "9", sanskrit: "त्रयश्च रोगाणां मार्गा बाह्यमध्याभ्यन्तराः तत्र बाह्यो रक्तादिधातवस्त्वक् च स पुनः शाखाख्यः तदाश्रयाः गण्डपिटकालज्यपचीचर्मकीलार्बुदाधिमांसमशव्यङ्गादयो बहिर्भागाश्च शोफार्शोगुल्मवीसर्पविद्रध्यादयः मध्यो मूर्द्धहृदयबस्त्यादीनि मर्माण्यस्थिसन्धयः तत्रोपनिवद्धाश्च स्नायुसिराकण्डरादयः तदाश्रयाः पक्षवधग्रहापतानकार्दितराजयक्ष्मास्थिसन्धिशूलगुदभ्रंशादयो मूर्द्धादिरोगाश्च आभ्यन्तरो महास्रोतः शरीरमध्यं महानिम्नमामपक्वाशयाश्रयः कोष्ठो ऽन्तरिति पर्यायाः तदाश्रया ज्वरातीसारछर्द्यलसकविषूचिकाश्वासकासहिध्मानाहोदरप्लीहादयो ऽन्तर्भागाश्च विसर्पशोफार्शोविद्रधिगुल्मादयः", text: "trayaśca rogāṇāṃ mārgā bāhyamadhyābhyantarāḥ tatra bāhyo raktādidhātavastvak ca sa punaḥ śākhākhyaḥ tadāśrayāḥ gaṇḍapiṭakālajyapacīcarmakīlārbudādhimāṃsamaśavyaṅgādayo bahirbhāgāśca śophārśogulmavīsarpavidradhyādayaḥ madhyo mūrddhahṛdayabastyādīni marmāṇyasthisandhayaḥ tatropanivaddhāśca snāyusirākaṇḍarādayaḥ tadāśrayāḥ pakṣavadhagrahāpatānakārditarājayakṣmāsthisandhiśūlagudabhraṃśādayo mūrddhādirogāśca ābhyantaro mahāsrotaḥ śarīramadhyaṃ mahānimnamāmapakvāśayāśrayaḥ koṣṭho 'ntariti paryāyāḥ tadāśrayā jvarātīsārachardyalasakaviṣūcikāśvāsakāsahidhmānāhodaraplīhādayo 'ntarbhāgāśca visarpaśophārśovidradhigulmādayaḥ" },
      { type: "verse", number: "10", sanskrit: "ते च रोगाः स्वप्रधाना भवन्त्यन्यपरिवारा वा क्रमादनुबन्ध्यनुबन्धाख्याः तत्राद्याः स्वतन्त्राः स्पष्टाकृतयो यथास्वं समुत्थानोपशयाश्च इतरे तु तद्विपरीताः तद्वच्च दोषा अपि तत्रान्यपरिवारा व्याधयो द्विविधाः पुरोगामिनोनुगामिनश्च तेष्वाद्याः पूर्वरूपसंज्ञाः उपद्रवास्त्वितरे तान्यथायथमेव वक्ष्यमाणानुपलक्षयेत् प्रधानप्रशमे च प्रशमो भवति तेषामनुपशाम्यतो वा पश्चात्तानुपक्रमेत् त्वरितं वा बलवन्तमुपद्रवं प्रधानाविरोधेन स हि पीडाकरतरो भवति व्याधिपरिक्लिष्टदेहत्वात् प्रमेहपिटकादिवत् तथान्यः प्रधान एव रोगो ऽन्यस्य प्रधानस्य हेतुः भवति यथा ज्वरो रक्तपित्तस्य रक्तपित्तं वा ज्वरस्य तौ श्वासस्य प्लीहा जठरस्य तच्छ्वयथोः अर्शांसि गुल्मोदरातीसारग्रहणीनां प्रतिश्यायः कासज्वरयोः तौ क्षयस्य क्षयः शोषस्य एकश्चापचारो निमित्तमेकस्य व्याधेः बहूनां च तथा बहवः तद्वदेकं लिङ्गम् एवमेव प्रशमे ऽभ्युपायः तथा स एवान्यस्य प्रकोपे तस्मात्तानवहितः सम्यगागमादिभिः परीक्षेत", text: "te ca rogāḥ svapradhānā bhavantyanyaparivārā vā kramādanubandhyanubandhākhyāḥ tatrādyāḥ svatantrāḥ spaṣṭākṛtayo yathāsvaṃ samutthānopaśayāśca itare tu tadviparītāḥ tadvacca doṣā api tatrānyaparivārā vyādhayo dvividhāḥ purogāminonugāminaśca teṣvādyāḥ pūrvarūpasaṃjñāḥ upadravāstvitare tānyathāyathameva vakṣyamāṇānupalakṣayet pradhānapraśame ca praśamo bhavati teṣāmanupaśāmyato vā paścāttānupakramet tvaritaṃ vā balavantamupadravaṃ pradhānāvirodhena sa hi pīḍākarataro bhavati vyādhiparikliṣṭadehatvāt pramehapiṭakādivat tathānyaḥ pradhāna eva rogo 'nyasya pradhānasya hetuḥ bhavati yathā jvaro raktapittasya raktapittaṃ vā jvarasya tau śvāsasya plīhā jaṭharasya tacchvayathoḥ arśāṃsi gulmodarātīsāragrahaṇīnāṃ pratiśyāyaḥ kāsajvarayoḥ tau kṣayasya kṣayaḥ śoṣasya ekaścāpacāro nimittamekasya vyādheḥ bahūnāṃ ca tathā bahavaḥ tadvadekaṃ liṅgam evameva praśame 'bhyupāyaḥ tathā sa evānyasya prakope tasmāttānavahitaḥ samyagāgamādibhiḥ parīkṣeta" },
      { type: "verse", number: "11", sanskrit: "तत्रागमतो रोगमेवमेवं प्रकोपणमेवं योनिमेवमधिष्ठानमेवमात्मानमेवं देवनमेवं रूपशब्दगन्धरसस्पर्शमेवं पूर्वरूपमेवमुपद्रवमेवं वृद्धिस्थानक्षयान्वितमेवमुदर्कमेवं नामानम् तस्मिन्नियं प्रतीकारस्य प्रवृत्तिः अन्यथा निवृत्तिः प्रत्यक्षतस्त्वातुरस्य यथास्वमिन्द्रियैर्वर्णसंस्थानप्रमाणोपचयछायाविण्मूत्र छर्दिताधिक्यमान्त्रकूजनमङ्गुल्यादिषुसन्धिषु स्फुटनं देहशकृद्वर्णादिगन्धं सुप्तशीतोष्णस्तम्भनसंस्पन्दश्लक्ष्णखरस्पर्शञ्च प्रकृतिविकृतियुक्तमास्यरसन्तु प्रश्नेन तथा सुच्छर्दनदुच्छर्दनत्वं मृदुक्रूरकोष्ठतां स्वप्नदर्शनमभिप्रायं जन्मामयप्रवृत्तिनक्षत्रद्विष्टेष्टसुखदुःखानि च तथा वयः प्रत्यक्षेण च अनुमानतस्तु यूकापसर्पणेन शरीरवैरस्यम् मक्षिकोपसर्पणेन शरीरमाधुर्यम् तथाग्निं जरणशक्त्या बलं व्यायामशक्त्या गूढलिङ्गं व्याधिमुपशयानुपशयतः दोषप्रमाणमपचारविशेषेणायुषः क्षयं रिष्टैः प्रकृति सत्वसारसात्म्यबलाननुशीलनेनेति भवति चात्र", text: "tatrāgamato rogamevamevaṃ prakopaṇamevaṃ yonimevamadhiṣṭhānamevamātmānamevaṃ devanamevaṃ rūpaśabdagandharasasparśamevaṃ pūrvarūpamevamupadravamevaṃ vṛddhisthānakṣayānvitamevamudarkamevaṃ nāmānam tasminniyaṃ pratīkārasya pravṛttiḥ anyathā nivṛttiḥ pratyakṣatastvāturasya yathāsvamindriyairvarṇasaṃsthānapramāṇopacayachāyāviṇmūtra charditādhikyamāntrakūjanamaṅgulyādiṣusandhiṣu sphuṭanaṃ dehaśakṛdvarṇādigandhaṃ suptaśītoṣṇastambhanasaṃspandaślakṣṇakharasparśañca prakṛtivikṛtiyuktamāsyarasantu praśnena tathā succhardanaducchardanatvaṃ mṛdukrūrakoṣṭhatāṃ svapnadarśanamabhiprāyaṃ janmāmayapravṛttinakṣatradviṣṭeṣṭasukhaduḥkhāni ca tathā vayaḥ pratyakṣeṇa ca anumānatastu yūkāpasarpaṇena śarīravairasyam makṣikopasarpaṇena śarīramādhuryam tathāgniṃ jaraṇaśaktyā balaṃ vyāyāmaśaktyā gūḍhaliṅgaṃ vyādhimupaśayānupaśayataḥ doṣapramāṇamapacāraviśeṣeṇāyuṣaḥ kṣayaṃ riṣṭaiḥ prakṛti satvasārasātmyabalānanuśīlaneneti bhavati cātra" },
      { type: "verse", number: "12", sanskrit: "ज्ञानबुद्धिप्रदीपेन यो नाविशति योगिवत् आतुरस्यान्तरात्मानं न स गोरांश्चिकित्सति", text: "jñānabuddhipradīpena yo nāviśati yogivat āturasyāntarātmānaṃ na sa gorāṃścikitsati" },
      { type: "verse", number: "13", sanskrit: "द्वाविमौ व्याधितौ व्याधिस्वरूपस्याप्रकाशकौ तद्यथैको गुरुव्याधिः सत्वदेहबलाश्रयात्", text: "dvāvimau vyādhitau vyādhisvarūpasyāprakāśakau tadyathaiko guruvyādhiḥ satvadehabalāśrayāt" },
      { type: "verse", number: "14", sanskrit: "लघुव्याधिवदाभाति लघुव्याधिरतोन्यथा बाह्यावयवमात्रेण तयोर्मुह्यति बालिशः", text: "laghuvyādhivadābhāti laghuvyādhiratonyathā bāhyāvayavamātreṇa tayormuhyati bāliśaḥ" },
      { type: "verse", number: "15", sanskrit: "ततोल्पमल्पवीर्यं वा विपरीतमतो ऽथवा पथ्यंविपर्यये युञ्जन् प्राणान् मुष्णाति रोगिणाम्", text: "tatolpamalpavīryaṃ vā viparītamato 'thavā pathyaṃviparyaye yuñjan prāṇān muṣṇāti rogiṇām" },
      { type: "verse", number: "16", sanskrit: "ज्ञानांशेन न हि ज्ञानं कृत्स्ने ज्ञेये प्रवर्तते बुभुत्सेत भिषक् तस्मात् तत्वं तन्त्रानुशीलनात्", text: "jñānāṃśena na hi jñānaṃ kṛtsne jñeye pravartate bubhutseta bhiṣak tasmāt tatvaṃ tantrānuśīlanāt" },
      { type: "verse", number: "17", sanskrit: "अभियुक्तस्तु सततं सर्वमालोच्य सर्वथा न जातु स्खलति प्राज्ञो विषमेपि क्रियापथे", text: "abhiyuktastu satataṃ sarvamālocya sarvathā na jātu skhalati prājño viṣamepi kriyāpathe" },
      { type: "verse", number: "18", sanskrit: "आगन्तुरन्वेति निजं विकारं निजस्तथागन्तुमतिप्रवृद्धः तत्रानुबन्धं प्रकृतिञ्च सम्यक् ज्ञात्वा ततः कर्म समारभेत", text: "āganturanveti nijaṃ vikāraṃ nijastathāgantumatipravṛddhaḥ tatrānubandhaṃ prakṛtiñca samyak jñātvā tataḥ karma samārabheta" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 23,
    lang: "sa",
    content: [
      { type: "heading", heading: "Сиро виречана — очищение головы" },
      { type: "text", text: "Глава 23 Сутрастханы Астанга-санграхи посвящена теме «очищение головы». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो भेषजावचरणीयमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bheṣajāvacaraṇīyamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "भेषजमवचारयन् प्रागेव तावदेवमातुरं परीक्षेत कस्मिन्नयं देशे जातः संवृद्धो व्याधितो वा कस्मिंश्च देशे मनुष्याणामिदमाहारजातमिदं विहारजातमेतावत् बलमेवांविधं सत्वमेवंविधं सात्म्ममियं भक्तिरिमे व्याधयो हितमिदमहितमिदमिति प्राग्ग्रहणेन केन वा निदानविशेषेणास्यकुपितो दोषः दोषस्य ह्येकस्यापि बहवः प्रकोपे हेतवः तस्माद्यथास्वलक्षणैः कर्मभिश्च बुध्वा भिषक्दोषमेवमवगमयेत् तद्यथा किमाहारेण कुपितो वायुः किं विहारेण तथा रूक्षेण लघुना शिशिरेण वा साहसेन वेगरोधेन वा भयेन शोकेन वेति ततश्च तत्प्रतिपक्षमौषधं प्रयुज्यमानमाशु सिद्धये सम्पद्यते तत्र मधुराम्ललवणा रसाः कटुतिक्तकषायाश्चेतरेतरप्रतिपक्षाः तदनन्तरञ्चोपलभेत मृदुमध्यातिमात्रविकल्पनया कथं निदानमासेवितम् एकरूपस्यापि हि हेतोः मृद्वादिविभागेन पृथक् समवेतानाञ्च दोषाणामंशांशबलविकल्पविशेषात् व्याधेर्बलाबलविशेषः तत्रानेकदोषात्मकेषु व्याधिष्वनेकरसेषु च भेषजेषु रसदोषप्रभावमेकैकशो ऽभिसमीक्ष्य व्याधिभेषजप्रभावतत्वं व्यवस्येत नत्वेवं सर्वत्र", text: "bheṣajamavacārayan prāgeva tāvadevamāturaṃ parīkṣeta kasminnayaṃ deśe jātaḥ saṃvṛddho vyādhito vā kasmiṃśca deśe manuṣyāṇāmidamāhārajātamidaṃ vihārajātametāvat balamevāṃvidhaṃ satvamevaṃvidhaṃ sātmmamiyaṃ bhaktirime vyādhayo hitamidamahitamidamiti prāggrahaṇena kena vā nidānaviśeṣeṇāsyakupito doṣaḥ doṣasya hyekasyāpi bahavaḥ prakope hetavaḥ tasmādyathāsvalakṣaṇaiḥ karmabhiśca budhvā bhiṣakdoṣamevamavagamayet tadyathā kimāhāreṇa kupito vāyuḥ kiṃ vihāreṇa tathā rūkṣeṇa laghunā śiśireṇa vā sāhasena vegarodhena vā bhayena śokena veti tataśca tatpratipakṣamauṣadhaṃ prayujyamānamāśu siddhaye sampadyate tatra madhurāmlalavaṇā rasāḥ kaṭutiktakaṣāyāścetaretarapratipakṣāḥ tadanantarañcopalabheta mṛdumadhyātimātravikalpanayā kathaṃ nidānamāsevitam ekarūpasyāpi hi hetoḥ mṛdvādivibhāgena pṛthak samavetānāñca doṣāṇāmaṃśāṃśabalavikalpaviśeṣāt vyādherbalābalaviśeṣaḥ tatrānekadoṣātmakeṣu vyādhiṣvanekaraseṣu ca bheṣajeṣu rasadoṣaprabhāvamekaikaśo 'bhisamīkṣya vyādhibheṣajaprabhāvatatvaṃ vyavasyeta natvevaṃ sarvatra" },
      { type: "verse", number: "3", sanskrit: "न हि विषमविकृतिसमवेतानां नानात्मकानां परस्परेणोपगृहीतानामुपहतानाञ्चान्यैश्च विकल्पनैर्विकल्पितानामवयवप्रभावानुमानेन समुदायप्रभावतत्वमध्यवसितुं शक्यम् तथाविधे हि समुदाये समुदायप्रभावमेवोपलभ्य व्याध्यौषधप्रभावतत्वमवगच्छेत् तथा कस्य धामाधिष्ठाय व्याधिरयमवस्ह्तित इति निरूपयेत् प्रविसृतो हि दोषः स्वमेव स्थानमातङ्कायाधितिष्ठन् मूर्द्धादीन् वा दुस्तरो भवति ततश्च स्थानविशेषेण भेषजविशेषः पर्येषितव्यः", text: "na hi viṣamavikṛtisamavetānāṃ nānātmakānāṃ paraspareṇopagṛhītānāmupahatānāñcānyaiśca vikalpanairvikalpitānāmavayavaprabhāvānumānena samudāyaprabhāvatatvamadhyavasituṃ śakyam tathāvidhe hi samudāye samudāyaprabhāvamevopalabhya vyādhyauṣadhaprabhāvatatvamavagacchet tathā kasya dhāmādhiṣṭhāya vyādhirayamavashtita iti nirūpayet pravisṛto hi doṣaḥ svameva sthānamātaṅkāyādhitiṣṭhan mūrddhādīn vā dustaro bhavati tataśca sthānaviśeṣeṇa bheṣajaviśeṣaḥ paryeṣitavyaḥ" },
      { type: "verse", number: "4", sanskrit: "ततश्चैवमालोचयेत् कस्यायमौषधस्य व्याधिरातुरो वा योग्यः कियतो वा दोषानुरूपो हि भैषज्यवीर्यप्रमाणविकल्पो व्याधिव्याधितबलापेक्षो भवति", text: "tataścaivamālocayet kasyāyamauṣadhasya vyādhirāturo vā yogyaḥ kiyato vā doṣānurūpo hi bhaiṣajyavīryapramāṇavikalpo vyādhivyādhitabalāpekṣo bhavati" },
      { type: "verse", number: "5", sanskrit: "सहसातिबलानि संशोधनौषधान्याग्नेयवायव्यान्यतिसौम्यान्यतिमात्राणि वा तथाग्निक्षारशस्त्रकर्माण्यल्पसत्वमातुरमल्पबलं वातिपाययेयुः संशमनानि तु व्याधिबलादधिकानि तमुपशमय्य व्याधिं व्याधिक्षपितदेहे शीघ्रमन्यमावहन्ति शरीरबलाधिकानि ग्लानिमूर्च्छामदमोहबलक्षयान् अग्निबलादधिकानि ग्लानिमग्निसादश्च", text: "sahasātibalāni saṃśodhanauṣadhānyāgneyavāyavyānyatisaumyānyatimātrāṇi vā tathāgnikṣāraśastrakarmāṇyalpasatvamāturamalpabalaṃ vātipāyayeyuḥ saṃśamanāni tu vyādhibalādadhikāni tamupaśamayya vyādhiṃ vyādhikṣapitadehe śīghramanyamāvahanti śarīrabalādhikāni glānimūrcchāmadamohabalakṣayān agnibalādadhikāni glānimagnisādaśca" },
      { type: "verse", number: "6", sanskrit: "अपि च अतिस्थूलो ऽतिकृशो दुर्बलो दुर्बद्धमांसशोणितास्थ्यंगावयवो ऽल्पाग्निरल्पाहारो ऽसात्म्याहारोपचितः साररहितो वा व्याधिबलमेव तावदसमर्थसोढुम् किं पुनस्तथाविधो भेषजमेवंवेगम् तस्मात्तादृशमविषादकरैर्मृदुसुखैरुत्तरोत्तरगुरुभिरविभ्रमैश्चोपाचरेदौषधैर्विशेषादबलाः ताह्यनवस्थितमृदुविक्लवहृदयाः प्रायःसुकुमाराः परायत्ताश्च ततो ऽपि विशेषेण शिशवः तथा बलवति व्याध्यातुरे ऽल्पबलमल्पं वा भेषजमकिञ्चित्करं भूय एव दोषमुत्क्लेश्य व्याधिमुदीरयेत्", text: "api ca atisthūlo 'tikṛśo durbalo durbaddhamāṃsaśoṇitāsthyaṃgāvayavo 'lpāgniralpāhāro 'sātmyāhāropacitaḥ sārarahito vā vyādhibalameva tāvadasamarthasoḍhum kiṃ punastathāvidho bheṣajamevaṃvegam tasmāttādṛśamaviṣādakarairmṛdusukhairuttarottaragurubhiravibhramaiścopācaredauṣadhairviśeṣādabalāḥ tāhyanavasthitamṛduviklavahṛdayāḥ prāyaḥsukumārāḥ parāyattāśca tato 'pi viśeṣeṇa śiśavaḥ tathā balavati vyādhyāture 'lpabalamalpaṃ vā bheṣajamakiñcitkaraṃ bhūya eva doṣamutkleśya vyādhimudīrayet" },
      { type: "verse", number: "7", sanskrit: "योग्यमपि चौषधमेवं परीक्षेत इदमेवंरसवीर्यविपाकमेवंगुणमेवंद्रव्यमेवंकर्मैवंप्रभावमस्मिन् देशे जातमस्मिन्नृतावेवंगृहीतमेवंनिहितमेवंविहितमेवंनिषिद्धमेवमुपसस्कृतमेवंसंयुक्तमेवंयुक्तमनया मात्रयैवंविधस्य पुरुषस्यैवंविधे काल एतावन्तं दोषमपकर्षत्युपशमयति वा अन्यदपि चैवंविधं भेषजमभूत् तन्मानेन वा विशेषेण प्रयुक्तमिदमकरोत् सूक्ष्माणि हि दोषौषधदूष्यदेशकालबलानलाहाररससात्म्यसत्वप्रकृतिवयसामवस्थान्तराणि यान्यनालोचितानि निहन्युरातुरम् आलोच्यमानानि तु विपुलबुद्धिमपि चिकित्सकमाकुलीकुर्युः किं पुनरल्पबुद्धिम् तस्मादभीक्ष्णशः शास्त्रार्थकर्मानुशीलनेन संस्कुर्वीत यज्ञाम् अपि च सन्ति व्याधयो ये शास्त्र उत्सर्गापवादैरुपक्रमं प्रति निर्दिष्टाः तत्र प्राज्ञ एव दोषादिगुरुलाघवेन सम्यगध्यवस्येदन्यतरनिष्ठायाम्", text: "yogyamapi cauṣadhamevaṃ parīkṣeta idamevaṃrasavīryavipākamevaṃguṇamevaṃdravyamevaṃkarmaivaṃprabhāvamasmin deśe jātamasminnṛtāvevaṃgṛhītamevaṃnihitamevaṃvihitamevaṃniṣiddhamevamupasaskṛtamevaṃsaṃyuktamevaṃyuktamanayā mātrayaivaṃvidhasya puruṣasyaivaṃvidhe kāla etāvantaṃ doṣamapakarṣatyupaśamayati vā anyadapi caivaṃvidhaṃ bheṣajamabhūt tanmānena vā viśeṣeṇa prayuktamidamakarot sūkṣmāṇi hi doṣauṣadhadūṣyadeśakālabalānalāhārarasasātmyasatvaprakṛtivayasāmavasthāntarāṇi yānyanālocitāni nihanyurāturam ālocyamānāni tu vipulabuddhimapi cikitsakamākulīkuryuḥ kiṃ punaralpabuddhim tasmādabhīkṣṇaśaḥ śāstrārthakarmānuśīlanena saṃskurvīta yajñām api ca santi vyādhayo ye śāstra utsargāpavādairupakramaṃ prati nirdiṣṭāḥ tatra prājña eva doṣādigurulāghavena samyagadhyavasyedanyataraniṣṭhāyām" },
      { type: "verse", number: "8", sanskrit: "कालश्च भेषजस्य योग्यतामादधाति स क्षणलवमुहूर्तादिभेदेनातुरावस्थया च द्विधोक्तः प्रागपि च शीतोष्णवर्षलक्षणस्त्रिविधः कालः तत्र शीतोष्णयोर्वृष्टिशीतयोश्चान्तरे साधारणौ वसन्तजलदात्यायु ग्रीष्मवर्षकालयोस्तु प्रारम्भो वृष्टेः प्रावृडिति विकल्प्यते तेषु साधारणेष्वहस्सु वमनादीनां प्रवृत्तिर्न्निवृत्तिरितरेष्वयोगातियोगभयात् साधारणा हि मन्दशीतोष्णवर्षतया सुखत्वात् भवन्त्यविकल्पकाः शरीरौषधानाम् विपरीतास्त्वितरे", text: "kālaśca bheṣajasya yogyatāmādadhāti sa kṣaṇalavamuhūrtādibhedenāturāvasthayā ca dvidhoktaḥ prāgapi ca śītoṣṇavarṣalakṣaṇastrividhaḥ kālaḥ tatra śītoṣṇayorvṛṣṭiśītayoścāntare sādhāraṇau vasantajaladātyāyu grīṣmavarṣakālayostu prārambho vṛṣṭeḥ prāvṛḍiti vikalpyate teṣu sādhāraṇeṣvahassu vamanādīnāṃ pravṛttirnnivṛttiritareṣvayogātiyogabhayāt sādhāraṇā hi mandaśītoṣṇavarṣatayā sukhatvāt bhavantyavikalpakāḥ śarīrauṣadhānām viparītāstvitare" },
      { type: "verse", number: "9", sanskrit: "तथा हि शीतकाले ऽतिमात्रशीतोपहितत्वाच्छरीरमत्यर्थशीतवातविष्टब्धमतिस्तब्धबहुगुरुदोषं भवति तदनु प्राप्तञ्च भेषजं संशोधनार्थमुष्णस्वभावमपि शीतोपहतत्वान्मन्दवीर्यतां गतमयोगाय जायते शरीरञ्च वातप्रायोपद्रवाय तद्वद्वर्षास्वपि समन्तादतिघनेन बहलेन घनसम्पातेनावतते नभसि उपरुद्धतेजःयसरेषु दिनकरकरेषु जलपटलोत्प्लावनोद्दामकर्दमायां भूमावत्यर्थोपक्लिन्नमवसन्नानलबलमादानदुर्बलं शरीरं भवति", text: "tathā hi śītakāle 'timātraśītopahitatvāccharīramatyarthaśītavātaviṣṭabdhamatistabdhabahugurudoṣaṃ bhavati tadanu prāptañca bheṣajaṃ saṃśodhanārthamuṣṇasvabhāvamapi śītopahatatvānmandavīryatāṃ gatamayogāya jāyate śarīrañca vātaprāyopadravāya tadvadvarṣāsvapi samantādatighanena bahalena ghanasampātenāvatate nabhasi uparuddhatejaḥyasareṣu dinakarakareṣu jalapaṭalotplāvanoddāmakardamāyāṃ bhūmāvatyarthopaklinnamavasannānalabalamādānadurbalaṃ śarīraṃ bhavati" },
      { type: "verse", number: "10", sanskrit: "औषधग्रामस्तु जलदोदरप्रततप्रमुक्तधारावपातसम्भृताम्बुनिवहोपप्लावितमूलजालसारविटपो बहलकोमलपल्लवोपचितस्कन्धशाखः पुनरिव बालतामुपगतो ऽल्पवीर्यो भवति अपरिसंस्थिततया च क्षितिमलप्नायाभिरम्लविपाकाभिः खगमृगसरीसृपादिशवधातुमूत्रपुरीषसंस्पृष्टाभिरद्भिः सलिलशिशिरशीकरानुविद्धशिशिरपवनसम्पृक्तेन च धाराधरोष्मणा कोमलत्वादपरिणतस्यास्य सुतरां विदाहो जन्यते ततश्चासावपथ्यतामुपगतो ध्रुवमयोगाय प्रथमसंगृहीतमपिचौषधं तोयदतोयानुगतमारुतोपहते जगतीति", text: "auṣadhagrāmastu jaladodarapratatapramuktadhārāvapātasambhṛtāmbunivahopaplāvitamūlajālasāraviṭapo bahalakomalapallavopacitaskandhaśākhaḥ punariva bālatāmupagato 'lpavīryo bhavati aparisaṃsthitatayā ca kṣitimalapnāyābhiramlavipākābhiḥ khagamṛgasarīsṛpādiśavadhātumūtrapurīṣasaṃspṛṣṭābhiradbhiḥ salilaśiśiraśīkarānuviddhaśiśirapavanasampṛktena ca dhārādharoṣmaṇā komalatvādapariṇatasyāsya sutarāṃ vidāho janyate tataścāsāvapathyatāmupagato dhruvamayogāya prathamasaṃgṛhītamapicauṣadhaṃ toyadatoyānugatamārutopahate jagatīti" },
      { type: "verse", number: "11", sanskrit: "ग्रीष्मे पुनरादानोपहतत्वाच्छरीरमुष्णरूक्षवातातपाध्मातमतिस्विन्नमतिशिथिलमतियलीनदोषं भवति भेषजं पुनरनुष्णमपि तपनकरनिपातादुष्णतीक्ष्णतामुपगतमतियोगायोपकल्पते शरीरञ्च पिपासाभ्रमक्लमोपद्रवाय तस्मात्साधारणेष्वेव तदन्तरालेषु वमनादीनि योजयेन्नचेदात्ययिको व्याधिः आत्ययिके तु कृत्रिमगुणोपधानेन यथर्तुगुणविपरीतेन संयोगसंस्कारप्रमाणविकल्पैश्चोपपाद्यौषधमेवावहितो ऽवचारयेत्", text: "grīṣme punarādānopahatatvāccharīramuṣṇarūkṣavātātapādhmātamatisvinnamatiśithilamatiyalīnadoṣaṃ bhavati bheṣajaṃ punaranuṣṇamapi tapanakaranipātāduṣṇatīkṣṇatāmupagatamatiyogāyopakalpate śarīrañca pipāsābhramaklamopadravāya tasmātsādhāraṇeṣveva tadantarāleṣu vamanādīni yojayennacedātyayiko vyādhiḥ ātyayike tu kṛtrimaguṇopadhānena yathartuguṇaviparītena saṃyogasaṃskārapramāṇavikalpaiścopapādyauṣadhamevāvahito 'vacārayet" },
      { type: "verse", number: "12", sanskrit: "आतुरावस्थासु तु कलाः कालसंज्ञाः तद्यथास्यामवस्थायामस्यौषधस्य कालो ऽकालो वा नह्यप्राप्तातीतकालमौषधं यौगिकं भवति तस्यत्वेकादशधावचारणम् तद्यथा अभक्तं प्राग्भक्तं मध्यभक्तमधोभक्तं सभक्तमन्तरभक्तं सामुद्गं मुहुर्मुहुः सग्रासं ग्रासान्तरा निशि च", text: "āturāvasthāsu tu kalāḥ kālasaṃjñāḥ tadyathāsyāmavasthāyāmasyauṣadhasya kālo 'kālo vā nahyaprāptātītakālamauṣadhaṃ yaugikaṃ bhavati tasyatvekādaśadhāvacāraṇam tadyathā abhaktaṃ prāgbhaktaṃ madhyabhaktamadhobhaktaṃ sabhaktamantarabhaktaṃ sāmudgaṃ muhurmuhuḥ sagrāsaṃ grāsāntarā niśi ca" },
      { type: "verse", number: "13", sanskrit: "तत्राभक्तं नाम केवलमेवौषधं निरन्नोपयोगादतिवीर्यम् कफोद्रेकविमुक्तामाशयस्रोताः प्रातर्बलवानुपयुञ्जीत इतरस्तु प्राग्भक्तादिकमन्नसंसर्गेण हितं नातिग्लानिकरं भवति", text: "tatrābhaktaṃ nāma kevalamevauṣadhaṃ nirannopayogādativīryam kaphodrekavimuktāmāśayasrotāḥ prātarbalavānupayuñjīta itarastu prāgbhaktādikamannasaṃsargeṇa hitaṃ nātiglānikaraṃ bhavati" },
      { type: "verse", number: "14", sanskrit: "प्राग्भक्तं नाम यदनन्तरभक्तम् तदपानानिलविकृतावधः कायस्य च बलाधानार्थं तद्गतेषु च व्याधिषु प्रशमनाय कृशीकरणार्थञ्च योज्यम्", text: "prāgbhaktaṃ nāma yadanantarabhaktam tadapānānilavikṛtāvadhaḥ kāyasya ca balādhānārthaṃ tadgateṣu ca vyādhiṣu praśamanāya kṛśīkaraṇārthañca yojyam" },
      { type: "verse", number: "15", sanskrit: "मध्यभक्तं मध्ये भक्तस्य तत् समानानिलविकृतौ कोष्ठगतेषु च व्याधिषु पैत्तिकेषु च", text: "madhyabhaktaṃ madhye bhaktasya tat samānānilavikṛtau koṣṭhagateṣu ca vyādhiṣu paittikeṣu ca" },
      { type: "verse", number: "16", sanskrit: "अधोभक्तं भक्तादनन्तरम् तत्तुव्यानविकृतौ प्रातराशान्तमुदानविकृतौ पुनः सायमाशान्तम् पूर्वकायस्य च बलाधानार्थं तद्गतेषु व्याधिषु च श्लैष्मिकेषु च प्रशमाय स्थूलीकरणार्थञ्च", text: "adhobhaktaṃ bhaktādanantaram tattuvyānavikṛtau prātarāśāntamudānavikṛtau punaḥ sāyamāśāntam pūrvakāyasya ca balādhānārthaṃ tadgateṣu vyādhiṣu ca ślaiṣmikeṣu ca praśamāya sthūlīkaraṇārthañca" },
      { type: "verse", number: "17", sanskrit: "सभक्तं यदन्नेन समं साधितं पश्चाद्वा समालोडितम् तत् बालेषु सुकुमारेष्वौषधद्वेषिष्वरुचौ सर्वाङ्गगेषु च रोगेषु", text: "sabhaktaṃ yadannena samaṃ sādhitaṃ paścādvā samāloḍitam tat bāleṣu sukumāreṣvauṣadhadveṣiṣvarucau sarvāṅgageṣu ca rogeṣu" },
      { type: "verse", number: "18", sanskrit: "अन्तराभक्तं यत् पूर्वाह्णे भक्ते जीर्णे मध्याह्ने भेषजमुपयुज्यते तस्मिंश्च जीर्णे पुनरपराह्णे भोजनम् एतेन रात्रिर्व्याख्याता तद्दीप्ताग्नेर्व्यानजेष्वामयेषु", text: "antarābhaktaṃ yat pūrvāhṇe bhakte jīrṇe madhyāhne bheṣajamupayujyate tasmiṃśca jīrṇe punaraparāhṇe bhojanam etena rātrirvyākhyātā taddīptāgnervyānajeṣvāmayeṣu" },
      { type: "verse", number: "19", sanskrit: "सामुद्गं यदादावन्ते च भुक्तस्य तत्तु लघ्वल्पान्नयुक्तं पाचनावलेहचूर्णादि हिध्मायां कम्पाक्षेपयोरूर्ध्वाधस्संश्रये च दोषे", text: "sāmudgaṃ yadādāvante ca bhuktasya tattu laghvalpānnayuktaṃ pācanāvalehacūrṇādi hidhmāyāṃ kampākṣepayorūrdhvādhassaṃśraye ca doṣe" },
      { type: "verse", number: "20", sanskrit: "मुहुर्मुहुस्तु पुनःपुनर्भुक्ते यदभुक्ते वा तच्छवासकासहिध्मातृट्छर्दिषु विषनिमित्तेषु च विकारेषु", text: "muhurmuhustu punaḥpunarbhukte yadabhukte vā tacchavāsakāsahidhmātṛṭchardiṣu viṣanimitteṣu ca vikāreṣu" },
      { type: "verse", number: "21", sanskrit: "सग्रासं यत् ग्राससम्पृक्तम् ग्रासान्तरं यत् ग्रासयोर्ग्रासयोर्मध्ये द्वयमप्येतत् प्राणानिलविकृतौ तथा सग्रासं चूर्णलेहवटकादिकमग्निदीपनं वाजीकरणानि चोपयुञ्जीत ग्रासान्तरं हृद्रोगे वमनं धूमञ्च जत्रूर्ध्वामयेषु निशायाम्", text: "sagrāsaṃ yat grāsasampṛktam grāsāntaraṃ yat grāsayorgrāsayormadhye dvayamapyetat prāṇānilavikṛtau tathā sagrāsaṃ cūrṇalehavaṭakādikamagnidīpanaṃ vājīkaraṇāni copayuñjīta grāsāntaraṃ hṛdroge vamanaṃ dhūmañca jatrūrdhvāmayeṣu niśāyām" },
      { type: "verse", number: "22", sanskrit: "तत्राद्ये काले तृषितः पीतशीताम्बुरजीर्णी क्षुधितः क्षामश्च भेषजं वर्जयेत् शेषेषु वाहृद्यमसात्म्यमतितीक्ष्णोष्णोग्रगन्धं भूरिमात्रञ्चेति भवति चात्र श्लोकः", text: "tatrādye kāle tṛṣitaḥ pītaśītāmburajīrṇī kṣudhitaḥ kṣāmaśca bheṣajaṃ varjayet śeṣeṣu vāhṛdyamasātmyamatitīkṣṇoṣṇogragandhaṃ bhūrimātrañceti bhavati cātra ślokaḥ" },
      { type: "verse", number: "23", sanskrit: "रोगमादौ परीक्षेत तदनन्तरमौषधम् ततः कर्म भिषक् पश्चात् ज्ञानपूर्वं समाचरेत्", text: "rogamādau parīkṣeta tadanantaramauṣadham tataḥ karma bhiṣak paścāt jñānapūrvaṃ samācaret" },
      { type: "verse", number: "24", sanskrit: "निवृत्तो ऽपि पुनर्व्याधिरल्पेनायाति हेतुना देहे मार्गीकृते दोषैः शेषः सूक्ष्म इवानलः", text: "nivṛtto 'pi punarvyādhiralpenāyāti hetunā dehe mārgīkṛte doṣaiḥ śeṣaḥ sūkṣma ivānalaḥ" },
      { type: "verse", number: "25", sanskrit: "तस्मात्तमनुबध्नीयात् प्रयोगेणानपायिना सिद्धानामपि योगानां पूर्वेषां दार्ढ्यमावहन्", text: "tasmāttamanubadhnīyāt prayogeṇānapāyinā siddhānāmapi yogānāṃ pūrveṣāṃ dārḍhyamāvahan" },
      { type: "verse", number: "26", sanskrit: "सातत्यात्स्वाद्वभावाद्वा पथ्यं द्वेष्यत्वमागतम् कल्पनाविधिभिस्तैस्तैः प्रियत्वं गमयेत् पुनः", text: "sātatyātsvādvabhāvādvā pathyaṃ dveṣyatvamāgatam kalpanāvidhibhistaistaiḥ priyatvaṃ gamayet punaḥ" },
      { type: "verse", number: "27", sanskrit: "मनसोर्थानुकूल्येन तुष्टिरूर्जा रुचिर्बलम् सुखोपभोगता च स्यात् व्याधेश्चातः परिक्षयः", text: "manasorthānukūlyena tuṣṭirūrjā rucirbalam sukhopabhogatā ca syāt vyādheścātaḥ parikṣayaḥ" },
      { type: "verse", number: "28", sanskrit: "लौल्याद्दोषक्षयाद्व्याधिवैषम्येण च या रुचिः तासु पथ्योपचारज्ञो योगेनाद्यं विकल्पयेत्", text: "laulyāddoṣakṣayādvyādhivaiṣamyeṇa ca yā ruciḥ tāsu pathyopacārajño yogenādyaṃ vikalpayet" },
      { type: "verse", number: "29", sanskrit: "शीतोष्णवर्षानिचितं चैत्रश्रावणकार्तिके क्रमात् साधारणे श्लेष्मवातपित्तं हरेद्द्रुतम्", text: "śītoṣṇavarṣānicitaṃ caitraśrāvaṇakārtike kramāt sādhāraṇe śleṣmavātapittaṃ hareddrutam" },
      { type: "verse", number: "30", sanskrit: "प्रावृट्शरद्वसन्तानां मासेष्वेतेषु वा हरेत् साधारणेषु विधिना त्रिमासान्तरितान्मलान्", text: "prāvṛṭśaradvasantānāṃ māseṣveteṣu vā haret sādhāraṇeṣu vidhinā trimāsāntaritānmalān" },
      { type: "verse", number: "31", sanskrit: "कृस्वा शीतोष्णवृष्टीनां प्रतीकारं यथायथम् प्रयोजयेत् क्रियां प्राप्तां क्रियाकालं न हापयेत्", text: "kṛsvā śītoṣṇavṛṣṭīnāṃ pratīkāraṃ yathāyatham prayojayet kriyāṃ prāptāṃ kriyākālaṃ na hāpayet" },
      { type: "verse", number: "32", sanskrit: "सप्ताहेन गुणालाभे क्रितामन्यां प्रयोजयेत् पूर्वस्यां शान्तवेगायां न क्रियासङ्करो हितः गुणे ऽल्पेपि तु तामेव विशेषोत्कर्षलब्धये", text: "saptāhena guṇālābhe kritāmanyāṃ prayojayet pūrvasyāṃ śāntavegāyāṃ na kriyāsaṅkaro hitaḥ guṇe 'lpepi tu tāmeva viśeṣotkarṣalabdhaye" },
      { type: "verse", number: "33", sanskrit: "भेषजं नृपतेर्हृद्यमल्पमल्पात्ययं शुचिः शुद्धागमं बहुगुणं बहुकृत्वः प्रयोजितम्", text: "bheṣajaṃ nṛpaterhṛdyamalpamalpātyayaṃ śuciḥ śuddhāgamaṃ bahuguṇaṃ bahukṛtvaḥ prayojitam" },
      { type: "verse", number: "34", sanskrit: "अनन्यकार्यो ऽवहितः तथा तन्मन्त्रिसम्मतः आस्वादितं परिचरैःस्वयञ्चानुप्रयोजयेत्", text: "ananyakāryo 'vahitaḥ tathā tanmantrisammataḥ āsvāditaṃ paricaraiḥsvayañcānuprayojayet" },
      { type: "verse", number: "35", sanskrit: "उचितो यस्य यो देशस्तज्जं तस्यौषधं हितम् देशे ऽन्यत्रापि वसतस्तत्तुल्यगुणजन्म च", text: "ucito yasya yo deśastajjaṃ tasyauṣadhaṃ hitam deśe 'nyatrāpi vasatastattulyaguṇajanma ca" },
      { type: "verse", number: "36", sanskrit: "वीर्यवद्भावितं सम्यक् स्वरसैरसकृल्लघु रसगन्धादिसम्पन्नं काले जीर्णे च मात्रया एकाग्रमनसा युक्तं भषज्यममृतायते", text: "vīryavadbhāvitaṃ samyak svarasairasakṛllaghu rasagandhādisampannaṃ kāle jīrṇe ca mātrayā ekāgramanasā yuktaṃ bhaṣajyamamṛtāyate" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 24,
    lang: "sa",
    content: [
      { type: "heading", heading: "Лепа видхи — нанесение паст" },
      { type: "text", text: "Глава 24 Сутрастханы Астанга-санграхи посвящена теме «нанесение паст». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो द्विविधोपक्रमणीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto dvividhopakramaṇīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "उपक्रम्यस्य हि द्वित्वाद् द्विधैवोपक्रमो मतः एकस्सन्तर्पणस्तत्र द्वितीयश्चापतर्पणः बृंहणो लङ्घनश्चेति तत्पर्यायावुदाहृतौ", text: "upakramyasya hi dvitvād dvidhaivopakramo mataḥ ekassantarpaṇastatra dvitīyaścāpatarpaṇaḥ bṛṃhaṇo laṅghanaśceti tatparyāyāvudāhṛtau" },
      { type: "verse", number: "3", sanskrit: "बृंहणं यत् बृहत्वाय लङ्घनं लाघवाय यत् देहस्यं भवतः प्रायो भौमापमितरच्च ते", text: "bṛṃhaṇaṃ yat bṛhatvāya laṅghanaṃ lāghavāya yat dehasyaṃ bhavataḥ prāyo bhaumāpamitaracca te" },
      { type: "verse", number: "4", sanskrit: "स्नेहनं रूक्षणं कर्म स्वेदनं स्तम्भनञ्च यत् भूतानां तदपि द्वैध्यात् द्वितयं नातिवर्तते", text: "snehanaṃ rūkṣaṇaṃ karma svedanaṃ stambhanañca yat bhūtānāṃ tadapi dvaidhyāt dvitayaṃ nātivartate" },
      { type: "verse", number: "5", sanskrit: "शोधनं शमनञ्चेति द्विधा तत्रापि लङ्घनम् यदीरयेत् बहिर्दोषान् पञ्चधा शोधनञ्च तत्", text: "śodhanaṃ śamanañceti dvidhā tatrāpi laṅghanam yadīrayet bahirdoṣān pañcadhā śodhanañca tat" },
      { type: "verse", number: "6", sanskrit: "निरूहो वमनं कायशिरोरेको ऽस्रविस्रुतिः न शोधयति यद्दोषान् समान्नोदीरयत्यपि", text: "nirūho vamanaṃ kāyaśiroreko 'sravisrutiḥ na śodhayati yaddoṣān samānnodīrayatyapi" },
      { type: "verse", number: "7", sanskrit: "समीकरोति विषमान् शमनं तच्च सप्तधा पाचनं दीपनं क्षुत्तृड्व्यायामातपमारुताः बृंहणं शमनन्त्वेव वायोः पित्तानिलस्य च", text: "samīkaroti viṣamān śamanaṃ tacca saptadhā pācanaṃ dīpanaṃ kṣuttṛḍvyāyāmātapamārutāḥ bṛṃhaṇaṃ śamanantveva vāyoḥ pittānilasya ca" },
      { type: "verse", number: "8", sanskrit: "बृंहयेद् व्याधिभैषज्यमद्यस्त्रीशोककर्शितान् भाराध्वोरःक्षतक्षीणरूक्षदुर्बलवातलान्", text: "bṛṃhayed vyādhibhaiṣajyamadyastrīśokakarśitān bhārādhvoraḥkṣatakṣīṇarūkṣadurbalavātalān" },
      { type: "verse", number: "9", sanskrit: "गर्भिणीसूतिकाबालवृद्धान् ग्रीष्मे ऽपरानप्पि मांसक्षीरसितासर्पिर्मधुरस्निग्धबस्तिभिः", text: "garbhiṇīsūtikābālavṛddhān grīṣme 'parānappi māṃsakṣīrasitāsarpirmadhurasnigdhabastibhiḥ" },
      { type: "verse", number: "10", sanskrit: "स्वप्नशय्यासुखाभ्यङ्गस्नाननिर्वृतिहर्षणैः मेहामदोषातिस्निग्धज्वरोरुस्तम्भकुष्ठिनः विसर्पविद्रधिप्लीहशिरःकण्ठाक्षिरोगिणः", text: "svapnaśayyāsukhābhyaṅgasnānanirvṛtiharṣaṇaiḥ mehāmadoṣātisnigdhajvarorustambhakuṣṭhinaḥ visarpavidradhiplīhaśiraḥkaṇṭhākṣirogiṇaḥ" },
      { type: "verse", number: "11", sanskrit: "स्थूलांश्च लङ्घयेन्नित्यं शिशिरे त्वपरानपि तत्र संशोधनैः स्थौल्यबलपित्तकफाधिकान् आमदोषज्वरच्छर्दिरतीसारहृदामयैः", text: "sthūlāṃśca laṅghayennityaṃ śiśire tvaparānapi tatra saṃśodhanaiḥ sthaulyabalapittakaphādhikān āmadoṣajvaracchardiratīsārahṛdāmayaiḥ" },
      { type: "verse", number: "12", sanskrit: "विबन्धगौरवोद्गारहृल्लासादिभिरातुरान् मध्यस्थौल्यादिकान् प्रायः पूर्वं पाचनदीपनैः", text: "vibandhagauravodgārahṛllāsādibhirāturān madhyasthaulyādikān prāyaḥ pūrvaṃ pācanadīpanaiḥ" },
      { type: "verse", number: "13", sanskrit: "एभिरेवमयैरार्तान् हीनस्थौल्यबलादिकान् क्षुत्तृष्णानिग्रहैर्दोषैस्त्वार्तान्मध्यबलैर्दृढान्", text: "ebhirevamayairārtān hīnasthaulyabalādikān kṣuttṛṣṇānigrahairdoṣaistvārtānmadhyabalairdṛḍhān" },
      { type: "verse", number: "14", sanskrit: "समीरणातपायासैः किमुताल्पबलैर्नरान् न बृंहयेल्लङ्घनीयान् बृंह्यांस्तु मृदु लङ्घयेत् युक्त्या वा देशकालादिबलतस्तानुपाचरेत्", text: "samīraṇātapāyāsaiḥ kimutālpabalairnarān na bṛṃhayellaṅghanīyān bṛṃhyāṃstu mṛdu laṅghayet yuktyā vā deśakālādibalatastānupācaret" },
      { type: "verse", number: "15", sanskrit: "बृंहिते स्यात् बलं पुष्टिस्तत्साध्यामयसंङ्क्षयः विमलेन्द्रियता सर्गो मलानां लाघवं रुचिः", text: "bṛṃhite syāt balaṃ puṣṭistatsādhyāmayasaṃṅkṣayaḥ vimalendriyatā sargo malānāṃ lāghavaṃ ruciḥ" },
      { type: "verse", number: "16", sanskrit: "क्षुत्तृट्सहोदयश्शुद्धहृदयोद्गारकण्ठता व्याधिमार्दवमुत्साहस्तन्द्रानाशश्च लङ्घते", text: "kṣuttṛṭsahodayaśśuddhahṛdayodgārakaṇṭhatā vyādhimārdavamutsāhastandrānāśaśca laṅghate" },
      { type: "verse", number: "17", sanskrit: "अनपेक्षितमात्रादिसेविते कुरुतस्तु ते अतिस्थौल्यातिकार्श्यादीन् वक्ष्यन्ते ते च सौषधाः रूपं तैरेव च ज्ञेयमतिबृंहितलङ्घते", text: "anapekṣitamātrādisevite kurutastu te atisthaulyātikārśyādīn vakṣyante te ca sauṣadhāḥ rūpaṃ taireva ca jñeyamatibṛṃhitalaṅghate" },
      { type: "verse", number: "18", sanskrit: "तत्र शोधनमुद्दिश्य स्थौल्याद्याः प्रगुदाहृताः गुर्वादिवृद्धसंलीनश्लेष्ममिश्रो ऽन्नजो रसः", text: "tatra śodhanamuddiśya sthaulyādyāḥ pragudāhṛtāḥ gurvādivṛddhasaṃlīnaśleṣmamiśro 'nnajo rasaḥ" },
      { type: "verse", number: "19", sanskrit: "आम एव श्लथीकुर्वन् धातून् स्ह्तौल्यमुपानयेत् अतिस्थौल्यादतिक्षुत्तृट्प्रस्वेदश्वासनिद्रताः", text: "āma eva ślathīkurvan dhātūn shtaulyamupānayet atisthaulyādatikṣuttṛṭprasvedaśvāsanidratāḥ" },
      { type: "verse", number: "20", sanskrit: "आयासाक्षमता जाड्यमल्पायुर्बलवेगता दौर्गन्ध्यं गद्गदत्वञ्च भवेन्मेदोतिपुष्टितः", text: "āyāsākṣamatā jāḍyamalpāyurbalavegatā daurgandhyaṃ gadgadatvañca bhavenmedotipuṣṭitaḥ" },
      { type: "verse", number: "21", sanskrit: "स्रोतस्तु मेदोरुद्धेषु वायुः कोष्ठे विशेषतः चरन् प्रज्वलयत्यग्निं क्षुत्तृषौ स्तस्ततो ऽधिकम्", text: "srotastu medoruddheṣu vāyuḥ koṣṭhe viśeṣataḥ caran prajvalayatyagniṃ kṣuttṛṣau stastato 'dhikam" },
      { type: "verse", number: "22", sanskrit: "स्थूलं कोटरवद्वृद्धौ दहतो ऽग्न्यनिलौ च तम् स्वेदवाहिसिरामूलभावाद्विष्यन्दनादपि मेदसः श्लेष्मयोगाच्च भवति स्वेदभूरिता", text: "sthūlaṃ koṭaravadvṛddhau dahato 'gnyanilau ca tam svedavāhisirāmūlabhāvādviṣyandanādapi medasaḥ śleṣmayogācca bhavati svedabhūritā" },
      { type: "verse", number: "23", sanskrit: "कोष्ठ एव विपक्वे ऽस्य संरुद्धस्रोतसो रसे सर्वत्रालब्धवृत्तित्वात् प्रयो मेदः प्रचीयते", text: "koṣṭha eva vipakve 'sya saṃruddhasrotaso rase sarvatrālabdhavṛttitvāt prayo medaḥ pracīyate" },
      { type: "verse", number: "24", sanskrit: "तच्छेषो ऽल्परसो ऽल्पत्वान्नालं रक्तादिपुष्टये तुल्येपि वाय्वादिचये प्राक्चितं चीयतेतराम् मेदस्तेनासमस्तेन धातूनां विदधाति तत्", text: "taccheṣo 'lparaso 'lpatvānnālaṃ raktādipuṣṭaye tulyepi vāyvādicaye prākcitaṃ cīyatetarām medastenāsamastena dhātūnāṃ vidadhāti tat" },
      { type: "verse", number: "25", sanskrit: "श्वासादीनचिराच्चान्यान् ज्वरोदरभगन्दरान् मेहोरुस्तम्भपिटकाविद्रधिप्रभृतीन् गदान्", text: "śvāsādīnacirāccānyān jvarodarabhagandarān mehorustambhapiṭakāvidradhiprabhṛtīn gadān" },
      { type: "verse", number: "26", sanskrit: "अयथोपचयोत्साहश्चलस्फिगुदरस्तनः अतिस्थूलः स्मृतो योज्यं तत्रान्नं मारुतापहम्", text: "ayathopacayotsāhaścalasphigudarastanaḥ atisthūlaḥ smṛto yojyaṃ tatrānnaṃ mārutāpaham" },
      { type: "verse", number: "27", sanskrit: "श्लेष्ममेदोहरं यच्च कुलत्था यवका यवाः जूर्णश्यामाकमुद्गाद्याः पाने ऽरिष्टं मधूदकम्", text: "śleṣmamedoharaṃ yacca kulatthā yavakā yavāḥ jūrṇaśyāmākamudgādyāḥ pāne 'riṣṭaṃ madhūdakam" },
      { type: "verse", number: "28", sanskrit: "मस्तु तक्रं च तीक्ष्णोष्णं रूक्षं छेदि च भेषजम् चिन्ताव्यवायव्यायामशोधनास्वपनं भजेत्", text: "mastu takraṃ ca tīkṣṇoṣṇaṃ rūkṣaṃ chedi ca bheṣajam cintāvyavāyavyāyāmaśodhanāsvapanaṃ bhajet" },
      { type: "verse", number: "29", sanskrit: "देहापेक्षी तथा रूक्षं स्नानमुद्वर्तनादि च मधुना त्रिफलां लिह्यात् गुडूचीमभयां घनम् रसाञ्जनस्य महतः पञ्चमूलस्य गुग्गुलोः", text: "dehāpekṣī tathā rūkṣaṃ snānamudvartanādi ca madhunā triphalāṃ lihyāt guḍūcīmabhayāṃ ghanam rasāñjanasya mahataḥ pañcamūlasya gugguloḥ" },
      { type: "verse", number: "30", sanskrit: "शिलाह्वस्य प्रयोगश्च साग्निमन्थरसो हितः विडङ्गं नागरं क्षारः काललोहरजो मधु", text: "śilāhvasya prayogaśca sāgnimantharaso hitaḥ viḍaṅgaṃ nāgaraṃ kṣāraḥ kālaloharajo madhu" },
      { type: "verse", number: "31", sanskrit: "यवामलकचूर्णं च योगो ऽतिस्थौल्यदोषजित् मदनं त्रिफला मुस्ता सप्ताह्वारिष्टवत्सकम्", text: "yavāmalakacūrṇaṃ ca yogo 'tisthaulyadoṣajit madanaṃ triphalā mustā saptāhvāriṣṭavatsakam" },
      { type: "verse", number: "32", sanskrit: "सपाठारग्वधं पीतमतिबृंहणरोगजित् तद्वद्वत्सकशम्याकदेवदारुनिशाद्वयम्", text: "sapāṭhāragvadhaṃ pītamatibṛṃhaṇarogajit tadvadvatsakaśamyākadevadāruniśādvayam" },
      { type: "verse", number: "33", sanskrit: "समुस्तपाठाखदिरत्रिफलानिम्बगोक्षुरम् मदनादीनि चालेपः स्ननादिष्वपि योजयेत्", text: "samustapāṭhākhadiratriphalānimbagokṣuram madanādīni cālepaḥ snanādiṣvapi yojayet" },
      { type: "verse", number: "34", sanskrit: "हिङ्गुगोमेदकव्योषकुष्ठक्रौञ्चास्थिगोक्षुरम् एलावृक्षकषड्ग्रन्थाखराश्वोपलभेदकम्", text: "hiṅgugomedakavyoṣakuṣṭhakrauñcāsthigokṣuram elāvṛkṣakaṣaḍgranthākharāśvopalabhedakam" },
      { type: "verse", number: "35", sanskrit: "तक्रेण दधिमण्डेन पीतं कोलरसेन वा मूत्रकृछ्रं कृमीन् मेहं स्थूलतां च व्यपोहति", text: "takreṇa dadhimaṇḍena pītaṃ kolarasena vā mūtrakṛchraṃ kṛmīn mehaṃ sthūlatāṃ ca vyapohati" },
      { type: "verse", number: "36", sanskrit: "कृमिघ्नत्रिफलं तैलसक्तुत्र्यूषणदीप्यकैः लोहोदकाप्लुतो मन्थः शस्तो बृंहणरोगिणाम्", text: "kṛmighnatriphalaṃ tailasaktutryūṣaṇadīpyakaiḥ lohodakāpluto manthaḥ śasto bṛṃhaṇarogiṇām" },
      { type: "verse", number: "37", sanskrit: "व्योषकट्वीवराशिग्रुविडङ्गातिविषास्थिराः हिङ्गुसौचर्चलाजाजीयवानीधान्यचित्रकाः", text: "vyoṣakaṭvīvarāśigruviḍaṅgātiviṣāsthirāḥ hiṅgusaucarcalājājīyavānīdhānyacitrakāḥ" },
      { type: "verse", number: "38", sanskrit: "निशे बृहत्यौ हपुषा पाठा मूलं च केम्बुकात् एषां चूर्णं मधु घृतं तैलं च सदृशांशकम्", text: "niśe bṛhatyau hapuṣā pāṭhā mūlaṃ ca kembukāt eṣāṃ cūrṇaṃ madhu ghṛtaṃ tailaṃ ca sadṛśāṃśakam" },
      { type: "verse", number: "39", sanskrit: "सक्तुभिः षोडशगुणैर्युक्तं पीतं निहन्ति तत् अतिस्थौल्यादिकान् सर्वान् रोगानन्यांश्च तद्विधान् हृद्रोगकामलाश्वित्रश्वासकासगलग्रहान्", text: "saktubhiḥ ṣoḍaśaguṇairyuktaṃ pītaṃ nihanti tat atisthaulyādikān sarvān rogānanyāṃśca tadvidhān hṛdrogakāmalāśvitraśvāsakāsagalagrahān" },
      { type: "verse", number: "40", sanskrit: "बुद्धिमेधास्मृतिकरं सन्नस्याग्नेश्च दीपनम् योज्यं तथा यथाव्याधि स्वेदासृक्स्रावणान्यपि", text: "buddhimedhāsmṛtikaraṃ sannasyāgneśca dīpanam yojyaṃ tathā yathāvyādhi svedāsṛksrāvaṇānyapi" },
      { type: "verse", number: "41", sanskrit: "अतिकार्श्यं भ्रमः कासस्तृष्णाधिक्यमरोचकः स्नेहाग्निनिद्रादृक्श्रोत्रशुक्रौजःक्षुत्स्वरक्षयः", text: "atikārśyaṃ bhramaḥ kāsastṛṣṇādhikyamarocakaḥ snehāgninidrādṛkśrotraśukraujaḥkṣutsvarakṣayaḥ" },
      { type: "verse", number: "42", sanskrit: "बस्तिहृन्मूर्द्धजङ्घोरुत्रिकपार्श्वरुजा ज्वरः प्रलापोर्ध्वानिलग्लानिः छर्द्दिः पर्वास्थिभेदनम्", text: "bastihṛnmūrddhajaṅghorutrikapārśvarujā jvaraḥ pralāpordhvānilaglāniḥ charddiḥ parvāsthibhedanam" },
      { type: "verse", number: "43", sanskrit: "वर्चोमूत्रग्रहाद्याश्च जायन्ते ऽतिविलङ्घनात् अतिकार्श्येन नायासवर्षशीतोष्णतृट्क्षुधः", text: "varcomūtragrahādyāśca jāyante 'tivilaṅghanāt atikārśyena nāyāsavarṣaśītoṣṇatṛṭkṣudhaḥ" },
      { type: "verse", number: "44", sanskrit: "तृप्तिव्याध्यौषधमनान् सहते ऽल्पबलत्वतः श्वासकासक्षयप्लीहगुल्मार्शोवह्निमन्दताः", text: "tṛptivyādhyauṣadhamanān sahate 'lpabalatvataḥ śvāsakāsakṣayaplīhagulmārśovahnimandatāḥ" },
      { type: "verse", number: "45", sanskrit: "कृशं प्रायश्च धावन्ति रक्तपित्तानिलामयाः कार्श्यमेव वरं स्थौल्यान्न हि स्थूलस्य भेषजम् बृंहणं लङ्घनं नालमतिमेदो ऽग्निवातजित्", text: "kṛśaṃ prāyaśca dhāvanti raktapittānilāmayāḥ kārśyameva varaṃ sthaulyānna hi sthūlasya bheṣajam bṛṃhaṇaṃ laṅghanaṃ nālamatimedo 'gnivātajit" },
      { type: "verse", number: "46", sanskrit: "मधुरस्निग्धसौहित्यैर्यत् सौख्येन च नश्यति क्रशिमा स्थविमात्यन्तविपरीतनिषेवणैः", text: "madhurasnigdhasauhityairyat saukhyena ca naśyati kraśimā sthavimātyantaviparītaniṣevaṇaiḥ" },
      { type: "verse", number: "47", sanskrit: "शुष्कस्फिगुदरग्रीवाः स्थूलपर्वा सिराततः उच्यते ऽतिकृशस्तत्नप्रागुक्तो बृंहणो विधिः", text: "śuṣkasphigudaragrīvāḥ sthūlaparvā sirātataḥ ucyate 'tikṛśastatnaprāgukto bṛṃhaṇo vidhiḥ" },
      { type: "verse", number: "48", sanskrit: "अश्वगन्धाविदार्याद्या वृष्याश्चौषधयो हिताः अचिन्तया हर्षणेन ध्रुवं सन्तर्पणेन च", text: "aśvagandhāvidāryādyā vṛṣyāścauṣadhayo hitāḥ acintayā harṣaṇena dhruvaṃ santarpaṇena ca" },
      { type: "verse", number: "49", sanskrit: "स्वप्नप्रसङ्गाच्च कृशो वराह इव पुष्यति लङ्घनोत्थेषु रोगेषु शेषेष्वप्युपकल्पयेत् यत्तदात्वे समर्थं स्याद्यच्चाभ्यासेन पुष्टये", text: "svapnaprasaṅgācca kṛśo varāha iva puṣyati laṅghanottheṣu rogeṣu śeṣeṣvapyupakalpayet yattadātve samarthaṃ syādyaccābhyāsena puṣṭaye" },
      { type: "verse", number: "50", sanskrit: "सद्यः क्षीणो यतः सद्यो बृंहणेनोपचीयते चिरं क्रमेण च क्षीणस्तदभ्यासेन तत्र च", text: "sadyaḥ kṣīṇo yataḥ sadyo bṛṃhaṇenopacīyate ciraṃ krameṇa ca kṣīṇastadabhyāsena tatra ca" },
      { type: "verse", number: "51", sanskrit: "बृंहणं देहमात्राग्निबलादीन् वीक्ष्य योजयेत् न हि मांससमं किञ्चिदन्यद्देहबृहत्त्वकृत् मांसादमांसं मांसेन सम्भृतत्वाद्विशेषतः", text: "bṛṃhaṇaṃ dehamātrāgnibalādīn vīkṣya yojayet na hi māṃsasamaṃ kiñcidanyaddehabṛhattvakṛt māṃsādamāṃsaṃ māṃsena sambhṛtatvādviśeṣataḥ" },
      { type: "verse", number: "52", sanskrit: "क्रव्यान्मांसरसांस्तस्माद्दकलावणिकान् लघून् वेशवारीकृतैस्तद्वज्जाङ्गलैश्च कृताकृतान् रसांस्तथा च क्षीरादीन् तर्पणांस्तर्पणान् पुनः", text: "kravyānmāṃsarasāṃstasmāddakalāvaṇikān laghūn veśavārīkṛtaistadvajjāṅgalaiśca kṛtākṛtān rasāṃstathā ca kṣīrādīn tarpaṇāṃstarpaṇān punaḥ" },
      { type: "verse", number: "53", sanskrit: "युञ्ज्यात् कृशानां ज्वरिणां कासिनां मूत्रकृच्छ्रिणाम् तृष्यतामूध्ववातानां मूढमारुतवर्चसाम्", text: "yuñjyāt kṛśānāṃ jvariṇāṃ kāsināṃ mūtrakṛcchriṇām tṛṣyatāmūdhvavātānāṃ mūḍhamārutavarcasām" },
      { type: "verse", number: "54", sanskrit: "समैः कृष्णासितातैलक्षौद्राद्यैद्र्व्यंशतर्पणैः मन्थस्तद्वत् सिताक्षौद्रमदिरासक्तुयोजितः", text: "samaiḥ kṛṣṇāsitātailakṣaudrādyaidrvyaṃśatarpaṇaiḥ manthastadvat sitākṣaudramadirāsaktuyojitaḥ" },
      { type: "verse", number: "55", sanskrit: "फाणितं सक्तवः सर्पिर्दधिमण्डो ऽम्लकाञ्जिकम् तर्पणं मूत्रकृच्छ्रघ्नमुदावर्त्तहरं परम्", text: "phāṇitaṃ saktavaḥ sarpirdadhimaṇḍo 'mlakāñjikam tarpaṇaṃ mūtrakṛcchraghnamudāvarttaharaṃ param" },
      { type: "verse", number: "56", sanskrit: "मन्थः खर्जूरमृद्वीकावृक्षाम्लाम्लीकदाडिमैः परूषकैः सामलकैः सद्यस्तृष्णादिरोगजित्", text: "manthaḥ kharjūramṛdvīkāvṛkṣāmlāmlīkadāḍimaiḥ parūṣakaiḥ sāmalakaiḥ sadyastṛṣṇādirogajit" },
      { type: "verse", number: "57", sanskrit: "स्वादुरम्लो जलकृतः सस्नेहो रूक्ष एव वा सद्यः सन्तर्पणो मन्थः स्थैर्यवर्णबलप्रदः", text: "svāduramlo jalakṛtaḥ sasneho rūkṣa eva vā sadyaḥ santarpaṇo manthaḥ sthairyavarṇabalapradaḥ" },
      { type: "verse", number: "58", sanskrit: "गुरु चातर्पणं स्थूले विपरीतं हितं कृशे यवगोधूममुभयोस्तद्योग्याहितकल्पनम्", text: "guru cātarpaṇaṃ sthūle viparītaṃ hitaṃ kṛśe yavagodhūmamubhayostadyogyāhitakalpanam" },
      { type: "verse", number: "59", sanskrit: "स्यौल्यकार्श्ये प्रकृत्यापि स्यातां तत्राप्ययं विधिः सततं व्याधिततया सदा योज्यो विभज्य च", text: "syaulyakārśye prakṛtyāpi syātāṃ tatrāpyayaṃ vidhiḥ satataṃ vyādhitatayā sadā yojyo vibhajya ca" },
      { type: "verse", number: "60", sanskrit: "मात्रादियुक्ते सेवेत यस्तु लङ्घनबृंहणे समधात्वग्निदेहो ऽसौ समस्ंहननो भवेत्", text: "mātrādiyukte seveta yastu laṅghanabṛṃhaṇe samadhātvagnideho 'sau samasṃhanano bhavet" },
      { type: "verse", number: "61", sanskrit: "दृढेन्द्रियबलत्वाच्च न द्वन्द्वैरभिभूयते दोषगत्यातिरिच्यन्ते ग्राहिभेद्यादिभेदतः उपक्रमा न तु द्वित्वाद्भिन्ना अपि गदा इव", text: "dṛḍhendriyabalatvācca na dvandvairabhibhūyate doṣagatyātiricyante grāhibhedyādibhedataḥ upakramā na tu dvitvādbhinnā api gadā iva" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 25,
    lang: "sa",
    content: [
      { type: "heading", heading: "Вьяяма видхи — правила упражнений" },
      { type: "text", text: "Глава 25 Сутрастханы Астанга-санграхи посвящена теме «правила упражнений». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातः स्नेहविधिमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ snehavidhimadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "स्नेहादिषूपयोगाय तद्व्यापच्छमनाय च कुर्यात् प्रागेव तद्योगिद्रव्यसम्भारसङ्ग्रहम्", text: "snehādiṣūpayogāya tadvyāpacchamanāya ca kuryāt prāgeva tadyogidravyasambhārasaṅgraham" },
      { type: "verse", number: "3", sanskrit: "गुरुशीतसरस्निग्धमन्दसूक्ष्ममृदुद्रवम् औषधं स्नेहनं प्रायो विपरीतं विरूक्षणम्", text: "guruśītasarasnigdhamandasūkṣmamṛdudravam auṣadhaṃ snehanaṃ prāyo viparītaṃ virūkṣaṇam" },
      { type: "verse", number: "4", sanskrit: "सर्पिर्मज्जा वसा तैलं स्नेहेषु प्रवरं मतम् तत्रापि चोत्तमं सर्पिः संस्कारस्यानुवर्तनात्", text: "sarpirmajjā vasā tailaṃ sneheṣu pravaraṃ matam tatrāpi cottamaṃ sarpiḥ saṃskārasyānuvartanāt" },
      { type: "verse", number: "5", sanskrit: "माधुर्यादविदाहित्वाज्जन्माद्येव च शीलनात् पित्तघ्नास्ते यथापूर्वमितरघ्ना यथोत्तरम्", text: "mādhuryādavidāhitvājjanmādyeva ca śīlanāt pittaghnāste yathāpūrvamitaraghnā yathottaram" },
      { type: "verse", number: "6", sanskrit: "घृतात्तैलं गुरु वसा तैलान्मज्जा ततो ऽपि च द्वाध्यां त्रिभिश्चतुर्भिस्तैर्यमकस्त्रिवृतो महान्", text: "ghṛtāttailaṃ guru vasā tailānmajjā tato 'pi ca dvādhyāṃ tribhiścaturbhistairyamakastrivṛto mahān" },
      { type: "verse", number: "7", sanskrit: "स्नेहाशया दधिक्षीरं मांसास्थिफलदारु च स्वेद्यसंशोध्यमद्यस्त्रीव्यायामासक्तचिन्तकाः वृद्धबालावलकृशा रूक्षाः क्षीणास्ररेतसः", text: "snehāśayā dadhikṣīraṃ māṃsāsthiphaladāru ca svedyasaṃśodhyamadyastrīvyāyāmāsaktacintakāḥ vṛddhabālāvalakṛśā rūkṣāḥ kṣīṇāsraretasaḥ" },
      { type: "verse", number: "8", sanskrit: "वातार्तस्यन्दतिमिरदारुणप्रतिबोधिनः स्नेह्याः न त्वतिमन्दाग्नितीक्ष्णाग्निस्थूलदुर्बलाः ऊरुस्तम्भातिसारामगलरोगगरोदरैः", text: "vātārtasyandatimiradāruṇapratibodhinaḥ snehyāḥ na tvatimandāgnitīkṣṇāgnisthūladurbalāḥ ūrustambhātisārāmagalarogagarodaraiḥ" },
      { type: "verse", number: "9", sanskrit: "मूर्छार्छद्यरुचिश्लेष्मतृष्णामद्यैश्च पीडिताः अपप्रसूता युक्ते च नस्ये बस्तौ विरेचने", text: "mūrchārchadyaruciśleṣmatṛṣṇāmadyaiśca pīḍitāḥ apaprasūtā yukte ca nasye bastau virecane" },
      { type: "verse", number: "10", sanskrit: "तत्र धीस्मृतिमेधाग्निकाङ्क्षिणां शस्यते घृतम् ग्रन्थिनाडीकृमिश्लेष्ममेदोमारुतरोगिषु", text: "tatra dhīsmṛtimedhāgnikāṅkṣiṇāṃ śasyate ghṛtam granthināḍīkṛmiśleṣmamedomārutarogiṣu" },
      { type: "verse", number: "11", sanskrit: "तैलं लाघवदार्ढ्यार्थिक्रूरकोष्ठेषु देहिषु वातातपाध्वभारस्त्रीव्यायामक्षीणधातुषु", text: "tailaṃ lāghavadārḍhyārthikrūrakoṣṭheṣu dehiṣu vātātapādhvabhārastrīvyāyāmakṣīṇadhātuṣu" },
      { type: "verse", number: "12", sanskrit: "रूक्षक्लेशक्षमात्यग्निवातावृतपथेषु च शेषौ वसा तु सन्ध्यस्थिमर्मकोष्ठरुजासु च", text: "rūkṣakleśakṣamātyagnivātāvṛtapatheṣu ca śeṣau vasā tu sandhyasthimarmakoṣṭharujāsu ca" },
      { type: "verse", number: "13", sanskrit: "तथादग्धाहतभ्रष्टयोनिकर्णाशिरोरुजि तैलं प्रावृषि वर्षान्ते सर्पिरन्यौ तु माधवे सर्वं सर्वस्य च स्नेहं युञ्ज्यात् भास्वति निर्मले", text: "tathādagdhāhatabhraṣṭayonikarṇāśiroruji tailaṃ prāvṛṣi varṣānte sarpiranyau tu mādhave sarvaṃ sarvasya ca snehaṃ yuñjyāt bhāsvati nirmale" },
      { type: "verse", number: "14", sanskrit: "ऋतौ साधारणे दोषसाम्ये ऽनिलकफे कफे दिवा निश्यनिले पित्ते संसर्गे पित्तवत्यपि", text: "ṛtau sādhāraṇe doṣasāmye 'nilakaphe kaphe divā niśyanile pitte saṃsarge pittavatyapi" },
      { type: "verse", number: "15", sanskrit: "त्वरमाणे तु शीते ऽपि दिवा तैलं च योजयेत् उष्णे ऽपि रात्रौ सर्पिश्च दोषादीन्वीक्ष्य चान्यथा", text: "tvaramāṇe tu śīte 'pi divā tailaṃ ca yojayet uṣṇe 'pi rātrau sarpiśca doṣādīnvīkṣya cānyathā" },
      { type: "verse", number: "16", sanskrit: "निश्यश्नुते वातकफाद्रोगानहनि पित्ततः युक्यावचारयेत् स्नेहं भक्ष्याद्यन्नेन बस्तिभिः नस्याभ्यञ्जनगण्डूषमूर्धकर्णाक्षितर्पणैः", text: "niśyaśnute vātakaphādrogānahani pittataḥ yukyāvacārayet snehaṃ bhakṣyādyannena bastibhiḥ nasyābhyañjanagaṇḍūṣamūrdhakarṇākṣitarpaṇaiḥ" },
      { type: "verse", number: "17", sanskrit: "रसभेदैककत्वाभ्यां चतुष्षष्टिर्विचारणाः स्नेहस्यान्याभिभूतत्वादल्पत्वाच्च क्रमात्स्मृताः", text: "rasabhedaikakatvābhyāṃ catuṣṣaṣṭirvicāraṇāḥ snehasyānyābhibhūtatvādalpatvācca kramātsmṛtāḥ" },
      { type: "verse", number: "18", sanskrit: "यथोक्तहेत्वभावाच्च नाच्छपेयो विचारणा स्नेहस्य कल्पः स श्रेष्ठः स्नेहकर्माशुसाधनात्", text: "yathoktahetvabhāvācca nācchapeyo vicāraṇā snehasya kalpaḥ sa śreṣṭhaḥ snehakarmāśusādhanāt" },
      { type: "verse", number: "19", sanskrit: "द्वाभ्यां चतुर्भिरष्टाभिर्यामैर्जीर्यन्ति याः क्रमात् ह्रस्वमध्योत्तमा मात्रास्तास्ताभ्यश्च ह्रासीयसीम्", text: "dvābhyāṃ caturbhiraṣṭābhiryāmairjīryanti yāḥ kramāt hrasvamadhyottamā mātrāstāstābhyaśca hrāsīyasīm" },
      { type: "verse", number: "20", sanskrit: "कल्पयेद्वीक्ष्य दोषादीन् प्रागेव तु ह्रसीयसीम् अज्ञातकोष्ठे हि बहुः कुर्याज्जीवितसंशयम्", text: "kalpayedvīkṣya doṣādīn prāgeva tu hrasīyasīm ajñātakoṣṭhe hi bahuḥ kuryājjīvitasaṃśayam" },
      { type: "verse", number: "21", sanskrit: "तत्र दुर्बलमन्दाग्निबालवृद्धसुखात्मकैः अपथ्यरिक्तकोष्ठत्वज्वरातीसारकासिभिः", text: "tatra durbalamandāgnibālavṛddhasukhātmakaiḥ apathyariktakoṣṭhatvajvarātīsārakāsibhiḥ" },
      { type: "verse", number: "22", sanskrit: "ह्रस्वा पेया सुखा सा हि परिहारे ऽनुवर्तते चिराच्च बल्या न रुजे व्यापन्नापि प्रकल्पते", text: "hrasvā peyā sukhā sā hi parihāre 'nuvartate cirācca balyā na ruje vyāpannāpi prakalpate" },
      { type: "verse", number: "23", sanskrit: "मेहोरुःपिटकाकुष्ठवातशोणितपीडितैः मध्यमा मृदुकोष्ठैश्च स्नेहनी स्यात्सुखेन सा", text: "mehoruḥpiṭakākuṣṭhavātaśoṇitapīḍitaiḥ madhyamā mṛdukoṣṭhaiśca snehanī syātsukhena sā" },
      { type: "verse", number: "24", sanskrit: "न बलक्षपणी मन्दविभ्रंशा शुद्धये ऽप्यलम् महादोहानलबलक्षुत्तृट्क्लेशसहिष्णुभिः गुल्मोदावर्तवीसर्पदंशाभिपीडितैः", text: "na balakṣapaṇī mandavibhraṃśā śuddhaye 'pyalam mahādohānalabalakṣuttṛṭkleśasahiṣṇubhiḥ gulmodāvartavīsarpadaṃśābhipīḍitaiḥ" },
      { type: "verse", number: "25", sanskrit: "उन्मत्तैः कृच्छ्रमूत्रैश्च महती शीघ्रमेव सा सर्वमार्गानुसारेण जयेद् व्याधीन् सुयोजिता", text: "unmattaiḥ kṛcchramūtraiśca mahatī śīghrameva sā sarvamārgānusāreṇa jayed vyādhīn suyojitā" },
      { type: "verse", number: "26", sanskrit: "ह्यस्तेन जीर्ण एवान्ने स्नेहोच्छः शुद्धये बहुः शमनः क्षुद्वयो ऽनन्नो मध्यमात्रश्च शस्यते", text: "hyastena jīrṇa evānne snehocchaḥ śuddhaye bahuḥ śamanaḥ kṣudvayo 'nanno madhyamātraśca śasyate" },
      { type: "verse", number: "27", sanskrit: "बृंहणो रसमद्याद्यैः सभक्तो ऽल्पो हितः स च बालवृद्धपिपासाअर्तस्नेहद्विण्मद्यशीलिषु", text: "bṛṃhaṇo rasamadyādyaiḥ sabhakto 'lpo hitaḥ sa ca bālavṛddhapipāsāartasnehadviṇmadyaśīliṣu" },
      { type: "verse", number: "28", sanskrit: "स्त्रीस्नेहनित्यमन्दाग्निसुखितक्लेशभीरुषु मृदुकोष्ठाल्पदोषेषु काले चोष्णे कृशेषु च", text: "strīsnehanityamandāgnisukhitakleśabhīruṣu mṛdukoṣṭhālpadoṣeṣu kāle coṣṇe kṛśeṣu ca" },
      { type: "verse", number: "29", sanskrit: "स्नेहः प्राग्भोजनात् कुर्यादूरुजङ्घाकटीबलम् वेगानुलोम्यमारोग्यमधःकायगदक्षयम्", text: "snehaḥ prāgbhojanāt kuryādūrujaṅghākaṭībalam vegānulomyamārogyamadhaḥkāyagadakṣayam" },
      { type: "verse", number: "30", sanskrit: "मध्ये बृहत्त्वाग्निबलस्थिरताकुक्षिरुक्शमान् इन्द्रियस्थिरतामूर्ध्वमूर्ध्वजत्रुगदक्षयम्", text: "madhye bṛhattvāgnibalasthiratākukṣirukśamān indriyasthiratāmūrdhvamūrdhvajatrugadakṣayam" },
      { type: "verse", number: "31", sanskrit: "वाते सलवणं सर्पिः पित्ते केवलमिष्यते वैद्यो दद्यात् बहुकफे क्षारत्रिकटुकान्वितम्", text: "vāte salavaṇaṃ sarpiḥ pitte kevalamiṣyate vaidyo dadyāt bahukaphe kṣāratrikaṭukānvitam" },
      { type: "verse", number: "32", sanskrit: "वार्युष्णमच्छे ऽनुपिबेत्स्नेहे तत्सुखपक्तये आस्योपलेपशुद्ध्यै च तौवरारुष्करे न तु", text: "vāryuṣṇamacche 'nupibetsnehe tatsukhapaktaye āsyopalepaśuddhyai ca tauvarāruṣkare na tu" },
      { type: "verse", number: "33", sanskrit: "उष्णोपचारः स्नेहे स्यादुष्णो ह्युष्णैर्विरुध्यते ततो गुरुप्रावरणो निवातशयनस्थितः जरणान्तं प्रतीक्षेत तृष्यन्नुष्णाल्पवारिपः", text: "uṣṇopacāraḥ snehe syāduṣṇo hyuṣṇairvirudhyate tato guruprāvaraṇo nivātaśayanasthitaḥ jaraṇāntaṃ pratīkṣeta tṛṣyannuṣṇālpavāripaḥ" },
      { type: "verse", number: "34", sanskrit: "शिरोरुग्भ्रमनिष्ठीवमूर्च्छासादारतिक्लमैः जानीयाद् भेषजं जीर्यज्जीर्णं तच्छान्तिलाघावात्", text: "śirorugbhramaniṣṭhīvamūrcchāsādāratiklamaiḥ jānīyād bheṣajaṃ jīryajjīrṇaṃ tacchāntilāghāvāt" },
      { type: "verse", number: "35", sanskrit: "अनुलोमनिलस्वास्थ्यक्षुत्तृष्णोद्गारशुद्धिभिः जीर्णाजीर्णविशङ्कायां पुनरुष्णोदकं पिबेत् तेनोद्गारविशुद्धिः स्तात्ततश्च लघुता रुचिः", text: "anulomanilasvāsthyakṣuttṛṣṇodgāraśuddhibhiḥ jīrṇājīrṇaviśaṅkāyāṃ punaruṣṇodakaṃ pibet tenodgāraviśuddhiḥ stāttataśca laghutā ruciḥ" },
      { type: "verse", number: "36", sanskrit: "भोज्यो ऽन्नं मात्रया पास्यन् श्वःपिबन् पीतवानपि द्रवोष्णमनभिष्यन्दि नातिस्निग्धमसङ्करम्", text: "bhojyo 'nnaṃ mātrayā pāsyan śvaḥpiban pītavānapi dravoṣṇamanabhiṣyandi nātisnigdhamasaṅkaram" },
      { type: "verse", number: "37", sanskrit: "उष्णोदकोपचारी स्यात् ब्रह्मचारी क्षपाशयः व्यायामवेगसंरोधशोकवर्षहिमातपान्", text: "uṣṇodakopacārī syāt brahmacārī kṣapāśayaḥ vyāyāmavegasaṃrodhaśokavarṣahimātapān" },
      { type: "verse", number: "38", sanskrit: "प्रवातयानयानाध्वभाष्यात्यासनसंस्थितीः नीचात्युच्चोपधानाहस्स्वप्नधूमरजांसि च", text: "pravātayānayānādhvabhāṣyātyāsanasaṃsthitīḥ nīcātyuccopadhānāhassvapnadhūmarajāṃsi ca" },
      { type: "verse", number: "39", sanskrit: "यान्यहानि पिबेत्तानि तावन्त्यन्यान्यपि त्यजेत् सर्वकर्मस्वयं प्रायो व्याधिक्षीणेषु च क्रमः", text: "yānyahāni pibettāni tāvantyanyānyapi tyajet sarvakarmasvayaṃ prāyo vyādhikṣīṇeṣu ca kramaḥ" },
      { type: "verse", number: "40", sanskrit: "उपचारस्तु शमने कार्यः स्नेहे विरिक्तवत् स्नेहस्य पानात् पूर्वं च दातव्यं मृदुभेषजम् उत्तेजनं हुताशस्य कोष्ठलाघवकारि च", text: "upacārastu śamane kāryaḥ snehe viriktavat snehasya pānāt pūrvaṃ ca dātavyaṃ mṛdubheṣajam uttejanaṃ hutāśasya koṣṭhalāghavakāri ca" },
      { type: "verse", number: "41", sanskrit: "त्र्यहमच्छं मृदौ कोष्ठे क्रूरे सप्तदिनं पिबेत् सम्यक्स्निग्धो ऽथवायावदतःसात्मीभवेत् परम्", text: "tryahamacchaṃ mṛdau koṣṭhe krūre saptadinaṃ pibet samyaksnigdho 'thavāyāvadataḥsātmībhavet param" },
      { type: "verse", number: "42", sanskrit: "सात्मीभूतो हि कुरुते न मलानामुदीरणम् अतियोगेन वा व्याधीन् यथाम्ब्बोधोतियोजनात्", text: "sātmībhūto hi kurute na malānāmudīraṇam atiyogena vā vyādhīn yathāmbbodhotiyojanāt" },
      { type: "verse", number: "43", sanskrit: "विहत्य सेतुं मृत्कोष्ठात् स्रवति क्षपयन् मृदम् स्नेहो ऽप्यग्निं तथा हत्वा स्रवति क्षपयंस्तनुम्", text: "vihatya setuṃ mṛtkoṣṭhāt sravati kṣapayan mṛdam sneho 'pyagniṃ tathā hatvā sravati kṣapayaṃstanum" },
      { type: "verse", number: "44", sanskrit: "वातानुलोम्यं दीप्तो ऽग्निर्वर्चः स्निग्धमसंहतम् मृदुस्निग्धाङ्गताग्लानिःस्नेहोद्वेगो ऽथलाघवम्", text: "vātānulomyaṃ dīpto 'gnirvarcaḥ snigdhamasaṃhatam mṛdusnigdhāṅgatāglāniḥsnehodvego 'thalāghavam" },
      { type: "verse", number: "45", sanskrit: "विमलेन्द्रियता सम्यक् स्निग्धे रूक्षे विपर्ययः पाण्ड्वामयाग्गसदनघ्राणवक्त्रगुदस्रवाः गुददाहारुचिश्छर्दिमूर्छातृष्णाप्रवाहिकाः", text: "vimalendriyatā samyak snigdhe rūkṣe viparyayaḥ pāṇḍvāmayāggasadanaghrāṇavaktragudasravāḥ gudadāhāruciśchardimūrchātṛṣṇāpravāhikāḥ" },
      { type: "verse", number: "46", sanskrit: "शुक्तोद्गारभ्रमश्वासकासाः स्नेहातिसेवनात् अमात्रयाहितो ऽकाले मिथ्याहारविहारतः स्नेहः करोति शोफार्शस्तन्द्रानिद्राविसंज्ञताः", text: "śuktodgārabhramaśvāsakāsāḥ snehātisevanāt amātrayāhito 'kāle mithyāhāravihārataḥ snehaḥ karoti śophārśastandrānidrāvisaṃjñatāḥ" },
      { type: "verse", number: "47", sanskrit: "कण्डूकुष्ठज्वरोत्क्लेशशूलानाहबलक्षयान् जठरेन्द्रियदौर्बल्यजाड्यामस्तम्भवाग्ग्रहान्", text: "kaṇḍūkuṣṭhajvarotkleśaśūlānāhabalakṣayān jaṭharendriyadaurbalyajāḍyāmastambhavāggrahān" },
      { type: "verse", number: "48", sanskrit: "तांस्तान् स्वदोषहेतूत्थान् पाण्ड्वादींश्चातियोजनात् क्षुत्तृष्णोक्लेखनस्वेदरूक्षपानान्नभेषजम् तक्रारिष्टखलोद्दालयवश्यामाककोद्रवाः", text: "tāṃstān svadoṣahetūtthān pāṇḍvādīṃścātiyojanāt kṣuttṛṣṇoklekhanasvedarūkṣapānānnabheṣajam takrāriṣṭakhaloddālayavaśyāmākakodravāḥ" },
      { type: "verse", number: "49", sanskrit: "पिप्पलीत्रिफलाक्षौद्रपथ्यागोमूत्रगुग्गुलु यथास्वं प्रतिरोगं च स्नेहव्यापदि साधनम्", text: "pippalītriphalākṣaudrapathyāgomūtraguggulu yathāsvaṃ pratirogaṃ ca snehavyāpadi sādhanam" },
      { type: "verse", number: "50", sanskrit: "विरूक्षणे लङ्घनवत् कृतातिकृतलक्षणम् स्नेहेन पैत्तिकस्याग्निर्यदा तीव्रतरीकृतः स्नेहमाशु जरां नीत्वा पुनरोजो ऽभितश्चरन्", text: "virūkṣaṇe laṅghanavat kṛtātikṛtalakṣaṇam snehena paittikasyāgniryadā tīvratarīkṛtaḥ snehamāśu jarāṃ nītvā punarojo 'bhitaścaran" },
      { type: "verse", number: "51", sanskrit: "उदीरयेत् सोपसर्गां पिपासामस्य बाधिकाम् सो ऽसूंस्त्यजेद्यद्युदकं न पिबेदाशु शीतलम्", text: "udīrayet sopasargāṃ pipāsāmasya bādhikām so 'sūṃstyajedyadyudakaṃ na pibedāśu śītalam" },
      { type: "verse", number: "52", sanskrit: "शीतसेकावगाहान् वा तत्तृष्णापीडितो भजेत् स्नेहाग्निना दह्यमानः स्वविषेणेव पन्नगः", text: "śītasekāvagāhān vā tattṛṣṇāpīḍito bhajet snehāgninā dahyamānaḥ svaviṣeṇeva pannagaḥ" },
      { type: "verse", number: "53", sanskrit: "अजीर्णे बलवत्या तु शीतैर्दिह्याच्छिरोमुखम् छर्दयेत्तदशान्तौ च पीत्वा शीतोदकं पुनः", text: "ajīrṇe balavatyā tu śītairdihyācchiromukham chardayettadaśāntau ca pītvā śītodakaṃ punaḥ" },
      { type: "verse", number: "54", sanskrit: "रूक्षान्नमुल्लिखेद्भुक्त्वा तादृश्यां तु कफानिले समदोषश्च निःशेषं स्नेहमुष्णाम्बुनोद्धरेत्", text: "rūkṣānnamullikhedbhuktvā tādṛśyāṃ tu kaphānile samadoṣaśca niḥśeṣaṃ snehamuṣṇāmbunoddharet" },
      { type: "verse", number: "55", sanskrit: "ततो दोषादिबलतः पूर्वोक्तं च विधिं श्रयेत् न सर्पिः केवलं पित्ते पेयं सामे विशेषतः सर्वं ह्यनुव्रजेद्देहं हत्वा संज्ञां च मारयेत्", text: "tato doṣādibalataḥ pūrvoktaṃ ca vidhiṃ śrayet na sarpiḥ kevalaṃ pitte peyaṃ sāme viśeṣataḥ sarvaṃ hyanuvrajeddehaṃ hatvā saṃjñāṃ ca mārayet" },
      { type: "verse", number: "56", sanskrit: "स्निग्धद्रवोष्णधन्वोत्थरसभुक्स्वेदमाचरेत् स्निग्धस्त्र्यहं स्थितः कुर्याद्विरेकं वमनं पुनः", text: "snigdhadravoṣṇadhanvottharasabhuksvedamācaret snigdhastryahaṃ sthitaḥ kuryādvirekaṃ vamanaṃ punaḥ" },
      { type: "verse", number: "57", sanskrit: "एकाहं दिनमन्यच्च कफमुत्क्लेश्य तत्करैः तिलमाषदधिक्षीरगुडमत्स्यरसादिभिः", text: "ekāhaṃ dinamanyacca kaphamutkleśya tatkaraiḥ tilamāṣadadhikṣīraguḍamatsyarasādibhiḥ" },
      { type: "verse", number: "58", sanskrit: "मासला मेदुरा भूरिश्लेष्माणो विषमाग्नयः स्नेहोचिताश्च ये स्नेह्यास्तान् पूर्वं रूक्षयेत्ततः", text: "māsalā medurā bhūriśleṣmāṇo viṣamāgnayaḥ snehocitāśca ye snehyāstān pūrvaṃ rūkṣayettataḥ" },
      { type: "verse", number: "59", sanskrit: "संस्नेह्य शोधयेदेवं स्नेहव्यापन्न जायते अलं मलानीरयितुं स्नेहश्चासात्म्यतां गतः", text: "saṃsnehya śodhayedevaṃ snehavyāpanna jāyate alaṃ malānīrayituṃ snehaścāsātmyatāṃ gataḥ" },
      { type: "verse", number: "60", sanskrit: "बालवृद्धादिषु स्नेहपरिहारासहिष्णुषु योगानिमाननुद्वेगान् सद्यःस्नेहान् प्रयोजयेत्", text: "bālavṛddhādiṣu snehaparihārāsahiṣṇuṣu yogānimānanudvegān sadyaḥsnehān prayojayet" },
      { type: "verse", number: "61", sanskrit: "प्रभूतमांसनिष्क्वाथान् जाङ्गलानूपजान् रसान् स्नेहभृष्टेषु वा तेषु यवागूं नातिसंहताम्", text: "prabhūtamāṃsaniṣkvāthān jāṅgalānūpajān rasān snehabhṛṣṭeṣu vā teṣu yavāgūṃ nātisaṃhatām" },
      { type: "verse", number: "62", sanskrit: "तिलचूर्णं च सस्नेहं फाणितं कृसरां तथा तिलकाम्बलिकं भूरिस्नेहं सर्पिष्मतीमपि", text: "tilacūrṇaṃ ca sasnehaṃ phāṇitaṃ kṛsarāṃ tathā tilakāmbalikaṃ bhūrisnehaṃ sarpiṣmatīmapi" },
      { type: "verse", number: "63", sanskrit: "पेयां सुखोष्णा क्षैरेयीं पात्रे वा ससिताघृते सर्पिर्लवणयुक्तं वा सद्योदुग्धं तथा पयः", text: "peyāṃ sukhoṣṇā kṣaireyīṃ pātre vā sasitāghṛte sarpirlavaṇayuktaṃ vā sadyodugdhaṃ tathā payaḥ" },
      { type: "verse", number: "64", sanskrit: "पेयां च पञ्चप्रसृतां स्नेहैस्तण्डुलपञ्चमैः पायसं माषमिश्रं च बहुस्नेहसमूयुतम् तैलशुण्ठीगुडरसं जीर्णे मांसरसाशिनः", text: "peyāṃ ca pañcaprasṛtāṃ snehaistaṇḍulapañcamaiḥ pāyasaṃ māṣamiśraṃ ca bahusnehasamūyutam tailaśuṇṭhīguḍarasaṃ jīrṇe māṃsarasāśinaḥ" },
      { type: "verse", number: "65", sanskrit: "स्नेहं वैकं सुराच्छेन दध्नो वा सगुडं सरम् वसां वराहजां सर्पिः पिप्पलीं लवणं तिलान्", text: "snehaṃ vaikaṃ surācchena dadhno vā saguḍaṃ saram vasāṃ varāhajāṃ sarpiḥ pippalīṃ lavaṇaṃ tilān" },
      { type: "verse", number: "66", sanskrit: "पिप्पलीं लवणं स्नेहांश्चतुरो दधिमस्तुकम् दध्ना सिद्धं व्योषगर्भं धात्रीद्राक्षारसे घृतम्", text: "pippalīṃ lavaṇaṃ snehāṃścaturo dadhimastukam dadhnā siddhaṃ vyoṣagarbhaṃ dhātrīdrākṣārase ghṛtam" },
      { type: "verse", number: "67", sanskrit: "यवकोलकुलत्थाम्बुक्षारक्षीरसुरादधि घृतं च सिद्धं तुल्यांशं सद्यःस्नेहनमुत्तमम्", text: "yavakolakulatthāmbukṣārakṣīrasurādadhi ghṛtaṃ ca siddhaṃ tulyāṃśaṃ sadyaḥsnehanamuttamam" },
      { type: "verse", number: "68", sanskrit: "सिद्धांश्च चतुरः स्नेहान् बदरत्रिफलारसैः योनिशुक्रामयहरान् सद्यःस्नेहान् प्रयोजयेत्", text: "siddhāṃśca caturaḥ snehān badaratriphalārasaiḥ yoniśukrāmayaharān sadyaḥsnehān prayojayet" },
      { type: "verse", number: "69", sanskrit: "लवणोपहिताः स्नेहाः स्नेहयन्त्यचिरान्नरम् तद्धि विष्यन्द्यरूक्षं च सूक्ष्ममुष्णं व्यवायि च", text: "lavaṇopahitāḥ snehāḥ snehayantyacirānnaram taddhi viṣyandyarūkṣaṃ ca sūkṣmamuṣṇaṃ vyavāyi ca" },
      { type: "verse", number: "70", sanskrit: "गुडानूपामिषक्षीरतिलमाषसुरादधि कुष्टशोफप्रमेहेषु स्नेहार्थं न प्रकल्पयेत्", text: "guḍānūpāmiṣakṣīratilamāṣasurādadhi kuṣṭaśophaprameheṣu snehārthaṃ na prakalpayet" },
      { type: "verse", number: "71", sanskrit: "त्रिफलापिप्पलीपथ्यागुग्गुल्वादिविपाचितान् स्नेहान्यथास्वमेतेषां योजयेदविकारिणः", text: "triphalāpippalīpathyāguggulvādivipācitān snehānyathāsvameteṣāṃ yojayedavikāriṇaḥ" },
      { type: "verse", number: "72", sanskrit: "क्षीणानां त्वामयैरग्निदेहसन्धुक्षणक्षमान् दीप्तान्तराग्निः परिशुद्धकोष्ठः प्रत्यग्रधातुर्बलवर्णयुक्तः दृढेन्द्रियो मन्दजरः शतायुः स्नेहोपसेवी पुरुषः प्रदिष्टः", text: "kṣīṇānāṃ tvāmayairagnidehasandhukṣaṇakṣamān dīptāntarāgniḥ pariśuddhakoṣṭhaḥ pratyagradhāturbalavarṇayuktaḥ dṛḍhendriyo mandajaraḥ śatāyuḥ snehopasevī puruṣaḥ pradiṣṭaḥ" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 26,
    lang: "sa",
    content: [
      { type: "heading", heading: "Нидра видхи — правила сна" },
      { type: "text", text: "Глава 26 Сутрастханы Астанга-санграхи посвящена теме «правила сна». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातः स्वेदविधिं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ svedavidhiṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "चतुर्विधो ऽग्निस्वेदो भवति तापोपनाहद्रवोष्मभेदेन तत्र तापस्वेदः पाणिकांस्यफालवालुकावस्त्रघटिकादिभिः साक्षादग्निना च प्रयोक्तव्यः", text: "caturvidho 'gnisvedo bhavati tāpopanāhadravoṣmabhedena tatra tāpasvedaḥ pāṇikāṃsyaphālavālukāvastraghaṭikādibhiḥ sākṣādagninā ca prayoktavyaḥ" },
      { type: "verse", number: "3", sanskrit: "उपनाहस्वेदस्तु सर्वगन्धधान्यसर्षपकिण्ववचादेवदारुरास्नैरण्डमूलमधुकशताह्वासुराकिट्टादिवातहरद्रव्यचूर्णैर्यवगोधूमशकलैरानूपासृक्पित्तशिरःपादामिषवेशवारैश्च तथा श्लेष्मसंसृष्टे वायौ सुरसादिभिः पित्तसंसृष्टे च पद्मकादिभिः पृथक् सहितैर्वा क्षीरशुक्तधान्याम्ललवणमस्तुप्रगाढैः सुस्निग्धैः सुखोष्णैः साल्वलाभिधानैस्तैर्बहुशः प्रदिह्योष्णवीर्यापूतिसृदुरोमचर्मभिस्तदभावे घनवातहरपत्राविककौशेयैरुपनद्धमङ्गमहस्थितं विदाहपरिहारार्थं निशि मुञ्चेत् दिवा निशि बद्धम् दोषकालवलवशेन वा", text: "upanāhasvedastu sarvagandhadhānyasarṣapakiṇvavacādevadārurāsnairaṇḍamūlamadhukaśatāhvāsurākiṭṭādivātaharadravyacūrṇairyavagodhūmaśakalairānūpāsṛkpittaśiraḥpādāmiṣaveśavāraiśca tathā śleṣmasaṃsṛṣṭe vāyau surasādibhiḥ pittasaṃsṛṣṭe ca padmakādibhiḥ pṛthak sahitairvā kṣīraśuktadhānyāmlalavaṇamastupragāḍhaiḥ susnigdhaiḥ sukhoṣṇaiḥ sālvalābhidhānaistairbahuśaḥ pradihyoṣṇavīryāpūtisṛduromacarmabhistadabhāve ghanavātaharapatrāvikakauśeyairupanaddhamaṅgamahasthitaṃ vidāhaparihārārthaṃ niśi muñcet divā niśi baddham doṣakālavalavaśena vā" },
      { type: "verse", number: "4", sanskrit: "द्रवस्वेदस्तु द्विविधिः परिषेको ऽवगाहश्च तत्र शिग्रुवरणाम्रातकमूलकसर्षपसुरसार्जकवासावंशाश्मन्तकाशोकशिरीषार्ककरञ्जैरण्डमालतीपत्रभङ्गपूतीकदशमूलादिवातहरैर्द्रव्यैर्मस्तुसलिलसुराक्षीरशुक्तादिभिः क्वथितैः पूर्वोक्तैश्च यथादोषं पृथक् सहितैर्वा कुम्भीर्वर्षलिकाः प्रणालीर्वा पूरयित्वा वातहरसिद्धस्नेहाभ्यक्तमनभ्यक्तं वोपविष्टं किलिञ्जे वा शयानमेकाङ्गे सर्वाङ्गे वा वस्त्रावच्छन्ने परिषेचयेत् तैरेवाद्भिः पूर्णे महति कटाहे कुण्डे द्रोण्यांवावगाहयेत्", text: "dravasvedastu dvividhiḥ pariṣeko 'vagāhaśca tatra śigruvaraṇāmrātakamūlakasarṣapasurasārjakavāsāvaṃśāśmantakāśokaśirīṣārkakarañjairaṇḍamālatīpatrabhaṅgapūtīkadaśamūlādivātaharairdravyairmastusalilasurākṣīraśuktādibhiḥ kvathitaiḥ pūrvoktaiśca yathādoṣaṃ pṛthak sahitairvā kumbhīrvarṣalikāḥ praṇālīrvā pūrayitvā vātaharasiddhasnehābhyaktamanabhyaktaṃ vopaviṣṭaṃ kiliñje vā śayānamekāṅge sarvāṅge vā vastrāvacchanne pariṣecayet tairevādbhiḥ pūrṇe mahati kaṭāhe kuṇḍe droṇyāṃvāvagāhayet" },
      { type: "verse", number: "5", sanskrit: "ऊष्मस्वेदः पुनरष्टधा भिद्यते पिण्डः संस्तरो नाडी घनाश्म कुम्भी कूपः कुटी जेन्ताकश्च तत्र मृत्कपालपाषाणलोष्टलोहपिण्डानग्निवर्णान् सन्दंशेन गृहीत्वाम्भस्यम्ले वा निमज्जयेत् तैरार्द्रावकिवस्त्रेण वेष्टितैः श्लेष्ममेदोभूयिष्ठं सरुजमङ्गं ग्रन्थिमद्वा स्वेदयेत् पांसुसिकतागवादिपुरीषधान्यबुसपुलाकपललैर्वाम्लोत्क्वथितैः पूर्ववद्वेष्टितैः गवादिशकृतार्द्रेण पिण्डीकृतेनोपनाहद्रव्योत्कारिकाकृसरमांसपिण्डैर्वा वातरोगेष्विति पिण्डस्वेदः स एव सङ्कराख्यः", text: "ūṣmasvedaḥ punaraṣṭadhā bhidyate piṇḍaḥ saṃstaro nāḍī ghanāśma kumbhī kūpaḥ kuṭī jentākaśca tatra mṛtkapālapāṣāṇaloṣṭalohapiṇḍānagnivarṇān sandaṃśena gṛhītvāmbhasyamle vā nimajjayet tairārdrāvakivastreṇa veṣṭitaiḥ śleṣmamedobhūyiṣṭhaṃ sarujamaṅgaṃ granthimadvā svedayet pāṃsusikatāgavādipurīṣadhānyabusapulākapalalairvāmlotkvathitaiḥ pūrvavadveṣṭitaiḥ gavādiśakṛtārdreṇa piṇḍīkṛtenopanāhadravyotkārikākṛsaramāṃsapiṇḍairvā vātarogeṣviti piṇḍasvedaḥ sa eva saṅkarākhyaḥ" },
      { type: "verse", number: "6", sanskrit: "यथार्हस्वेदद्रव्याणि पिहितमुखायामुखायां सम्यगुपस्वेद्य निवातशरणशयनस्थे किलिञ्जे प्रस्तीर्याविककौशेयवातहरपत्रान्यतमोत्तरप्रच्छदे रौरवाजिनप्रावारादिभिः स्ववच्छन्नं स्वेदयेदिति संस्तरस्वेदः", text: "yathārhasvedadravyāṇi pihitamukhāyāmukhāyāṃ samyagupasvedya nivātaśaraṇaśayanasthe kiliñje prastīryāvikakauśeyavātaharapatrānyatamottarapracchade rauravājinaprāvārādibhiḥ svavacchannaṃ svedayediti saṃstarasvedaḥ" },
      { type: "verse", number: "7", sanskrit: "पूर्ववदेवोपस्वेद्योखामुखे ऽन्यामुख नाडीमूलच्छिद्रप्रमाणपार्श्वच्छिद्रामुपसन्धायावलिप्य च पार्श्वच्छिद्रस्थया नाड्या शरोषिकावंशदलकिलिञ्जकरञ्जपत्रान्यतमकृतया गजाग्रहस्तसंस्थानया व्यामदीर्घयाध्यर्द्धव्यामदीर्घया वा स्वायामचतुर्भागाष्टभागपरिणाहमूलाग्रस्रोतसा सर्वतोवातहरपत्रसंवृतछिद्रया द्विस्त्रिर्वा विनमितया सुखोपविष्टस्य स्वभ्यक्तप्रावृतेङ्गे बाष्पमुपहरेत् बाष्पो ह्यनृजुगामी विहतचण्डवेगस्त्वचमविदहन् सुखं स्वेदयतीति नाडीस्वेदः", text: "pūrvavadevopasvedyokhāmukhe 'nyāmukha nāḍīmūlacchidrapramāṇapārśvacchidrāmupasandhāyāvalipya ca pārśvacchidrasthayā nāḍyā śaroṣikāvaṃśadalakiliñjakarañjapatrānyatamakṛtayā gajāgrahastasaṃsthānayā vyāmadīrghayādhyarddhavyāmadīrghayā vā svāyāmacaturbhāgāṣṭabhāgapariṇāhamūlāgrasrotasā sarvatovātaharapatrasaṃvṛtachidrayā dvistrirvā vinamitayā sukhopaviṣṭasya svabhyaktaprāvṛteṅge bāṣpamupaharet bāṣpo hyanṛjugāmī vihatacaṇḍavegastvacamavidahan sukhaṃ svedayatīti nāḍīsvedaḥ" },
      { type: "verse", number: "8", sanskrit: "पुरुषायाममात्रमधिकं वा घनं समं च शिलातलं भूप्रदेशं वा वातहरदारुदीप्तेनाग्निना सर्वतस्तापयित्वाग्निमपोह्योष्णोदकाम्लादिभिरभ्युक्ष्य यथोक्तप्रच्छदे संस्तरवत्स्वेदयेदिति घानाश्मस्वेदः", text: "puruṣāyāmamātramadhikaṃ vā ghanaṃ samaṃ ca śilātalaṃ bhūpradeśaṃ vā vātaharadārudīptenāgninā sarvatastāpayitvāgnimapohyoṣṇodakāmlādibhirabhyukṣya yathoktapracchade saṃstaravatsvedayediti ghānāśmasvedaḥ" },
      { type: "verse", number: "9", sanskrit: "पूर्ववत् स्वेदद्रव्याणि कुम्भ्यामुत्क्वाथ्याश्लिष्योपविष्टस्तद्वदूष्माणं गृह्णीयात् भूमौ वा तां निखाय तदूर्ध्वमासनं शयनं वा नातिघनप्रच्छदं परितः प्रलम्बमानकुथाकम्बलगोणिकं निधाय तत्रस्थस्योष्माणं गृह्णतः कुम्भ्यामग्निवर्णानयोगुडानुपलांश्च शनैर्निमज्जयेदिति कुम्भीस्वेदः", text: "pūrvavat svedadravyāṇi kumbhyāmutkvāthyāśliṣyopaviṣṭastadvadūṣmāṇaṃ gṛhṇīyāt bhūmau vā tāṃ nikhāya tadūrdhvamāsanaṃ śayanaṃ vā nātighanapracchadaṃ paritaḥ pralambamānakuthākambalagoṇikaṃ nidhāya tatrasthasyoṣmāṇaṃ gṛhṇataḥ kumbhyāmagnivarṇānayoguḍānupalāṃśca śanairnimajjayediti kumbhīsvedaḥ" },
      { type: "verse", number: "10", sanskrit: "शयनस्याधोविस्तारद्विगुणखाते कूपे वातहरदारुकरीषान्यतरपूर्णदग्घे विगतधूमे स्वास्तीर्णशयनस्थं स्वेदयेदिति कूपस्वेदः", text: "śayanasyādhovistāradviguṇakhāte kūpe vātaharadārukarīṣānyatarapūrṇadagghe vigatadhūme svāstīrṇaśayanasthaṃ svedayediti kūpasvedaḥ" },
      { type: "verse", number: "11", sanskrit: "कुटीं नात्युच्चविस्तारां वृत्तामच्छिद्रामुपनाहकल्कघनप्रदिग्धकुड्यां सर्वतोविधूमप्रदीप्तखदिराङ्गारपूर्णहसन्तिकासमूहपरिवृतां विधाय तन्मध्ये च शय्यां तत्रस्थं स्वेदयेदिति कुटीस्वेदः", text: "kuṭīṃ nātyuccavistārāṃ vṛttāmacchidrāmupanāhakalkaghanapradigdhakuḍyāṃ sarvatovidhūmapradīptakhadirāṅgārapūrṇahasantikāsamūhaparivṛtāṃ vidhāya tanmadhye ca śayyāṃ tatrasthaṃ svedayediti kuṭīsvedaḥ" },
      { type: "verse", number: "12", sanskrit: "अथ जेन्ताकं चिकीर्षुर्भूमिं परीक्षेत पूर्वस्यामुत्तरस्यां वा दिशि गुणवति प्रशस्तभूमिभागे देशे कृष्णमृत्तिके वा सुवर्णवर्णमृत्तिके परिघापुष्करिण्यादीनां जलाशयानामन्यतमस्य कूले दक्षिणे पश्चिमे वा सुतीर्थे समसुविभक्तभूमिभागे सप्ताष्टौ वारत्नीरपक्रम्योदकात् प्राङ्मुखमुदङ्मुखं वाभिमुखतीर्थं कूटागारं कारयेत् उत्सेधविस्तारतः परमरत्नयः षोडश समन्तात्सुवृत्तं मृत्कर्मसंपन्नमनेकवातायनम् अस्य च कूटागारस्यान्तः समन्ततो भित्तिमरत्निविस्तारोच्छ्रायां पिण्डिकां कारयेदाकवाटात् मध्ये चास्य कूटागारस्य किष्कुमुक्तं द्विपुरुषप्रमाणं मृन्मयं कन्दुसंस्थानंबहुसूक्ष्मच्छिद्रमङ्गारकोष्ठकस्तम्भं सापिधानं कारयेत् तं च खादिराणामश्वकर्णानां वा काष्ठानां पूरयित्वा दीपयेत् स यदा जानीयात्साधुदग्धानि काष्ठानि विगतधूमान्यवतप्तं सर्वमग्निना तदग्निगृहं स्वेदयोग्येन चोष्मणा युक्तमिति तत्रैनं वातहराभ्यङ्गाभ्यक्तगात्रं वस्त्रावच्छन्नं प्रवेशयेत् अनुशिष्यात्सौम्य प्रविश कल्याणायारोग्याय च प्रविश्य चैनां पिण्डिकामारुह्य षार्श्वापरपार्श्वाभ्यां यथासुखं शयीथाः न च त्वरयास्वेदमूर्छापरीतेनापि पिण्डिकैषा विमोक्तव्याप्राणोच्छ्वासात् भ्रश्यमानो ह्यतः पिण्डिकावकाशाद् द्वारमनधिगच्छन् स्वेदमूर्च्छा परीततया सद्यः प्राणान् जह्याः तस्मात् पिण्डिकामेनां न कथञ्चन मुञ्चेथाः त्वं यदा जानीया विगताभिष्यन्दमात्मानं सम्यक् प्रस्रुतस्वेदपिच्छं सर्वस्रोतो विमुक्तं लघुभूतमपगतविबन्धस्तम्भसुप्तिवेदनाग रवमिति ततः पिण्डिकानुसारेण द्वारं प्रपद्येथाः निष्क्रम्य च चक्षुषोः परिपालनार्थमतिस्विन्नो ऽपि न सहसा शीतोदकमनुप्रविशेथाः सम्यक् स्विन्नस्त्वपगतसन्तापक्लमो मुहूर्तात् सुखोष्णेन वारिणा यथान्यायं परिषिक्तो ऽश्नीयादिति जेन्ताकस्वेदः", text: "atha jentākaṃ cikīrṣurbhūmiṃ parīkṣeta pūrvasyāmuttarasyāṃ vā diśi guṇavati praśastabhūmibhāge deśe kṛṣṇamṛttike vā suvarṇavarṇamṛttike parighāpuṣkariṇyādīnāṃ jalāśayānāmanyatamasya kūle dakṣiṇe paścime vā sutīrthe samasuvibhaktabhūmibhāge saptāṣṭau vāratnīrapakramyodakāt prāṅmukhamudaṅmukhaṃ vābhimukhatīrthaṃ kūṭāgāraṃ kārayet utsedhavistārataḥ paramaratnayaḥ ṣoḍaśa samantātsuvṛttaṃ mṛtkarmasaṃpannamanekavātāyanam asya ca kūṭāgārasyāntaḥ samantato bhittimaratnivistārocchrāyāṃ piṇḍikāṃ kārayedākavāṭāt madhye cāsya kūṭāgārasya kiṣkumuktaṃ dvipuruṣapramāṇaṃ mṛnmayaṃ kandusaṃsthānaṃbahusūkṣmacchidramaṅgārakoṣṭhakastambhaṃ sāpidhānaṃ kārayet taṃ ca khādirāṇāmaśvakarṇānāṃ vā kāṣṭhānāṃ pūrayitvā dīpayet sa yadā jānīyātsādhudagdhāni kāṣṭhāni vigatadhūmānyavataptaṃ sarvamagninā tadagnigṛhaṃ svedayogyena coṣmaṇā yuktamiti tatrainaṃ vātaharābhyaṅgābhyaktagātraṃ vastrāvacchannaṃ praveśayet anuśiṣyātsaumya praviśa kalyāṇāyārogyāya ca praviśya caināṃ piṇḍikāmāruhya ṣārśvāparapārśvābhyāṃ yathāsukhaṃ śayīthāḥ na ca tvarayāsvedamūrchāparītenāpi piṇḍikaiṣā vimoktavyāprāṇocchvāsāt bhraśyamāno hyataḥ piṇḍikāvakāśād dvāramanadhigacchan svedamūrcchā parītatayā sadyaḥ prāṇān jahyāḥ tasmāt piṇḍikāmenāṃ na kathañcana muñcethāḥ tvaṃ yadā jānīyā vigatābhiṣyandamātmānaṃ samyak prasrutasvedapicchaṃ sarvasroto vimuktaṃ laghubhūtamapagatavibandhastambhasuptivedanāga ravamiti tataḥ piṇḍikānusāreṇa dvāraṃ prapadyethāḥ niṣkramya ca cakṣuṣoḥ paripālanārthamatisvinno 'pi na sahasā śītodakamanupraviśethāḥ samyak svinnastvapagatasantāpaklamo muhūrtāt sukhoṣṇena vāriṇā yathānyāyaṃ pariṣikto 'śnīyāditi jentākasvedaḥ" },
      { type: "verse", number: "13", sanskrit: "तेषां विशेषतस्तापोष्मस्वेदौ कफे प्रयोजयेत् उपनाहमनिले किञ्चित् पित्तसंसृष्टे ऽन्यतरस्मिन् द्रवमिति", text: "teṣāṃ viśeṣatastāpoṣmasvedau kaphe prayojayet upanāhamanile kiñcit pittasaṃsṛṣṭe 'nyatarasmin dravamiti" },
      { type: "verse", number: "14", sanskrit: "अनाग्नेयं पुनर्मेदःकफावृते वायौ निवातसदनगुरुप्रावरणबहुमद्यपानव्यायामक्षुदातपनियुद्धाध्वभारभरणामर्षभयैः उपनाहं च पित्तान्वये पूर्वोक्तेनैव विधिनाग्निरहितमिति भवति चात्र", text: "anāgneyaṃ punarmedaḥkaphāvṛte vāyau nivātasadanaguruprāvaraṇabahumadyapānavyāyāmakṣudātapaniyuddhādhvabhārabharaṇāmarṣabhayaiḥ upanāhaṃ ca pittānvaye pūrvoktenaiva vidhināgnirahitamiti bhavati cātra" },
      { type: "verse", number: "15", sanskrit: "निवाते ऽन्तर्बहिःस्निग्धो जीर्णान्नः स्वेदमाचरेत् व्याधिव्याधितदेशर्त्तुवशान्मध्यवरावरम्", text: "nivāte 'ntarbahiḥsnigdho jīrṇānnaḥ svedamācaret vyādhivyādhitadeśarttuvaśānmadhyavarāvaram" },
      { type: "verse", number: "16", sanskrit: "कफार्तो रूक्षणं रूक्षो रूक्षस्निग्धं कफानिले आमाशयगते वायौ कफे पक्वाशयाश्रिते", text: "kaphārto rūkṣaṇaṃ rūkṣo rūkṣasnigdhaṃ kaphānile āmāśayagate vāyau kaphe pakvāśayāśrite" },
      { type: "verse", number: "17", sanskrit: "रूक्षपूर्वं तथा स्नेहपूर्वं स्थानानुरोधतः अल्पं वङ्क्षणयोः स्वल्पं दृङ्भुष्कहृदये न वा", text: "rūkṣapūrvaṃ tathā snehapūrvaṃ sthānānurodhataḥ alpaṃ vaṅkṣaṇayoḥ svalpaṃ dṛṅbhuṣkahṛdaye na vā" },
      { type: "verse", number: "18", sanskrit: "पद्मोत्पलादिभिः सक्तुपिण्ड्या वाच्छाद्य चक्षुषी शीतैर्मुक्तावलीपद्मकुमुदोत्पलभाजनैः", text: "padmotpalādibhiḥ saktupiṇḍyā vācchādya cakṣuṣī śītairmuktāvalīpadmakumudotpalabhājanaiḥ" },
      { type: "verse", number: "19", sanskrit: "मुहुः करैश्च तोयर्द्रैः स्विद्यते हृदयं स्पृशेत् शीतशूलक्षये स्विन्नो जाते ऽङ्गानां च मार्दवे स्याच्छनैर्मृदितः स्नातस्ततः स्नेहविधिं भजेत्", text: "muhuḥ karaiśca toyardraiḥ svidyate hṛdayaṃ spṛśet śītaśūlakṣaye svinno jāte 'ṅgānāṃ ca mārdave syācchanairmṛditaḥ snātastataḥ snehavidhiṃ bhajet" },
      { type: "verse", number: "20", sanskrit: "पित्तास्रकोपतृण्मूर्च्छास्वराङ्गसदनभ्रमाः सन्धिपीडाज्वरश्यावरक्तमण्डलदर्शनम्", text: "pittāsrakopatṛṇmūrcchāsvarāṅgasadanabhramāḥ sandhipīḍājvaraśyāvaraktamaṇḍaladarśanam" },
      { type: "verse", number: "21", sanskrit: "स्वेदातियोगाच्छर्दिश्च तत्र स्तम्भनमौषधम् विषक्षाराग्न्यतीसारछर्दिमेहातुरेषु च", text: "svedātiyogācchardiśca tatra stambhanamauṣadham viṣakṣārāgnyatīsārachardimehātureṣu ca" },
      { type: "verse", number: "22", sanskrit: "स्वेदनं गुरु तीक्ष्णोष्णं प्रायः स्तम्भनमन्यथा द्रवस्थिरसरस्निग्धरूक्षसूक्ष्मं च भेषजम्", text: "svedanaṃ guru tīkṣṇoṣṇaṃ prāyaḥ stambhanamanyathā dravasthirasarasnigdharūkṣasūkṣmaṃ ca bheṣajam" },
      { type: "verse", number: "23", sanskrit: "स्वेदनं स्तम्भनं श्लक्ष्णरूक्षसूक्ष्मसरद्रवम् प्रायस्तिक्तं कषायं च मधुरं च समासतः", text: "svedanaṃ stambhanaṃ ślakṣṇarūkṣasūkṣmasaradravam prāyastiktaṃ kaṣāyaṃ ca madhuraṃ ca samāsataḥ" },
      { type: "verse", number: "24", sanskrit: "स्तम्मितः स्यात् बले लब्धे यथोक्तामयसङ्क्षयात् स्तम्भत्वक्स्नायुसङ्कोचकम्पहृद्वाग्घनुग्रहैः", text: "stammitaḥ syāt bale labdhe yathoktāmayasaṅkṣayāt stambhatvaksnāyusaṅkocakampahṛdvāgghanugrahaiḥ" },
      { type: "verse", number: "25", sanskrit: "पादौष्ठत्वक्करैः श्यावैरतिस्तम्भितमादिशेत् न स्वेदयेदतिस्थूलरूक्षदुर्बलमूर्च्छतान् स्तम्भनीयक्षतक्षीणाक्षाममद्यविकारिणः", text: "pādauṣṭhatvakkaraiḥ śyāvairatistambhitamādiśet na svedayedatisthūlarūkṣadurbalamūrcchatān stambhanīyakṣatakṣīṇākṣāmamadyavikāriṇaḥ" },
      { type: "verse", number: "26", sanskrit: "तिमिरोदरवीसर्पकुष्ठशोषाढ्यरोगिणः पीतदुग्धदधिस्नेहमधून् कृतविरेचनान्", text: "timirodaravīsarpakuṣṭhaśoṣāḍhyarogiṇaḥ pītadugdhadadhisnehamadhūn kṛtavirecanān" },
      { type: "verse", number: "27", sanskrit: "भ्रष्टदग्धगुदग्लानिक्रोधशोकभयार्दितान् क्षुत्तृष्णाकमलापाण्डुमेहिनः पित्तपीडितान्", text: "bhraṣṭadagdhagudaglānikrodhaśokabhayārditān kṣuttṛṣṇākamalāpāṇḍumehinaḥ pittapīḍitān" },
      { type: "verse", number: "28", sanskrit: "गर्भिणीं पुष्पितां सूतां मृदु वात्ययिके गदे श्वासकासप्रतिश्यायहिध्माध्मानविबन्धिषु स्वरभेदानिलव्याधिपक्षाघातापतानके", text: "garbhiṇīṃ puṣpitāṃ sūtāṃ mṛdu vātyayike gade śvāsakāsapratiśyāyahidhmādhmānavibandhiṣu svarabhedānilavyādhipakṣāghātāpatānake" },
      { type: "verse", number: "29", sanskrit: "अङ्गमर्दकटीपार्श्वपृष्ठकुक्षिहनुग्रहे महत्त्वे मुष्कयोः खल्यामायांमे वातकण्टके", text: "aṅgamardakaṭīpārśvapṛṣṭhakukṣihanugrahe mahattve muṣkayoḥ khalyāmāyāṃme vātakaṇṭake" },
      { type: "verse", number: "30", sanskrit: "मूत्रक्र्च्छ्रार्बुदग्रन्थिशुक्राघाताढ्यमारुते वेपथुश्वयथुस्वापस्तम्भजृम्भाङ्गगौरवे", text: "mūtrakrcchrārbudagranthiśukrāghātāḍhyamārute vepathuśvayathusvāpastambhajṛmbhāṅgagaurave" },
      { type: "verse", number: "31", sanskrit: "कर्णमन्याशिरःकोष्ठजङ्घापादोरुरुक्षु च स्वेदं यथायथं कुर्यात्तदौषधविभागतः", text: "karṇamanyāśiraḥkoṣṭhajaṅghāpādorurukṣu ca svedaṃ yathāyathaṃ kuryāttadauṣadhavibhāgataḥ" },
      { type: "verse", number: "32", sanskrit: "स्विन्नो ऽन्नं पथ्यमश्नीयाद्दोषरोगानुरोधतः तदहः स्विन्नसर्वाङ्गो व्यायामं सुतरां त्यजेत्", text: "svinno 'nnaṃ pathyamaśnīyāddoṣarogānurodhataḥ tadahaḥ svinnasarvāṅgo vyāyāmaṃ sutarāṃ tyajet" },
      { type: "verse", number: "33", sanskrit: "अग्नेर्दीप्तिं मार्दवं त्वक्प्रसादं भक्तश्रद्धां स्रोतसां निर्मलत्वम् कुर्यात् स्वेदो जाड्यतन्द्रापहारं स्तब्धान् सन्धींश्चेष्टयत्याशु चास्य", text: "agnerdīptiṃ mārdavaṃ tvakprasādaṃ bhaktaśraddhāṃ srotasāṃ nirmalatvam kuryāt svedo jāḍyatandrāpahāraṃ stabdhān sandhīṃśceṣṭayatyāśu cāsya" },
      { type: "verse", number: "34", sanskrit: "स्नेहक्लिन्नाः कोष्ठगा धातुगा वा स्रोतोलीना ये च शाखास्थिसंस्थाः दोषाः स्वेदैस्ते द्रवीकृत्य कोष्ठं नीताः सम्यक् शुद्धिभिर्निर्ह्रियन्ते", text: "snehaklinnāḥ koṣṭhagā dhātugā vā srotolīnā ye ca śākhāsthisaṃsthāḥ doṣāḥ svedaiste dravīkṛtya koṣṭhaṃ nītāḥ samyak śuddhibhirnirhriyante" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 27,
    lang: "sa",
    content: [
      { type: "heading", heading: "Садврита — правильное поведение" },
      { type: "text", text: "Глава 27 Сутрастханы Астанга-санграхи посвящена теме «правильное поведение». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो वमनविरेचनविधिं नामाध्ययं व्याख्यास्यामः इति हस्माहुरात्रेयादयो महर्षयः", text: "athāto vamanavirecanavidhiṃ nāmādhyayaṃ vyākhyāsyāmaḥ iti hasmāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "दोषहरणमूर्ध्वभागं वमनाख्यमधोभागं विरेचनाख्यमुभयं वा मलविरेचनाद्विरेचनमित्युच्यते", text: "doṣaharaṇamūrdhvabhāgaṃ vamanākhyamadhobhāgaṃ virecanākhyamubhayaṃ vā malavirecanādvirecanamityucyate" },
      { type: "verse", number: "3", sanskrit: "तत्रोष्णतीक्ष्णसूक्ष्मव्यवायिविकाषीण्यौषधानि स्ववीर्येण हृदयमुपेत्य सौक्ष्म्यात् व्यवायित्वाच्च धमनीरनुसृत्य स्नेहेन मृदूकृते ऽन्तश्शरीरे स्वेदोष्मणार्द्रदारुवद्विष्यण्णे स्थूलाणुस्रोतेभ्यः सकलमपि दोषसङ्घातमौष्ण्यात् पुनर्विष्यन्दयन्ति तैक्ष्ण्याद्विकाषित्वाच्च विच्छिन्दयन्ति स विष्यण्णविच्छिन्नो दोषसङ्घातः पारिप्लवः स्नेहाक्तभाजनस्थ इवोदकाञ्जलिरसज्जन्ननुप्नसरणभावादामाशयमनुगम्य उदानप्रणुन्नः अग्निवाय्वात्मकत्वात् ऊर्ध्वभागप्रभावाच्चौषधस्योर्ध्वं प्रवर्तते स्लिलपृथिव्यात्मकत्वादधोभागप्रभावाच्च औषधस्याधः उभयतश्चोभयगुणात्मकत्वादुभयभागप्रभावाच्च", text: "tatroṣṇatīkṣṇasūkṣmavyavāyivikāṣīṇyauṣadhāni svavīryeṇa hṛdayamupetya saukṣmyāt vyavāyitvācca dhamanīranusṛtya snehena mṛdūkṛte 'ntaśśarīre svedoṣmaṇārdradāruvadviṣyaṇṇe sthūlāṇusrotebhyaḥ sakalamapi doṣasaṅghātamauṣṇyāt punarviṣyandayanti taikṣṇyādvikāṣitvācca vicchindayanti sa viṣyaṇṇavicchinno doṣasaṅghātaḥ pāriplavaḥ snehāktabhājanastha ivodakāñjalirasajjannanupnasaraṇabhāvādāmāśayamanugamya udānapraṇunnaḥ agnivāyvātmakatvāt ūrdhvabhāgaprabhāvāccauṣadhasyordhvaṃ pravartate slilapṛthivyātmakatvādadhobhāgaprabhāvācca auṣadhasyādhaḥ ubhayataścobhayaguṇātmakatvādubhayabhāgaprabhāvācca" },
      { type: "verse", number: "4", sanskrit: "तत्रोत्कृष्टे श्लेष्मणि पित्तसंसृष्टे वा तत्स्थानगते वा पित्ते अनिले वा श्लेष्मोत्तरे च वमनमाचरेत् पित्ते तु विरेकं श्लेष्मसंसृष्टे वा तत्स्थानगते वा श्लेष्मणीति", text: "tatrotkṛṣṭe śleṣmaṇi pittasaṃsṛṣṭe vā tatsthānagate vā pitte anile vā śleṣmottare ca vamanamācaret pitte tu virekaṃ śleṣmasaṃsṛṣṭe vā tatsthānagate vā śleṣmaṇīti" },
      { type: "verse", number: "5", sanskrit: "तत्र वमनसाध्या विषपीतदष्टदिग्धविद्धविरुद्धाजीर्णान्ननवज्वरराजयक्ष्मातीसाराधोरक्तपित्तविषूचिकालसकाविपाकारोचकापचिग्रन्थ्यर्बुदश्लीपदमेदोगदगरोन्मादापस्मारश्वासकासहृल्लासवीसर्पप्रमेहकुष्ठपाण्डुवर्त्ममुखघ्राणकपालरोगकर्णरोधशोफस्तन्यदोषादयो दोषभेदीयोक्ताश्च श्लेष्मव्याधयो विशेषेण एते हि परं वमनेन नाशमुपयान्ति सलिलापगमनेनानिष्पन्नशाल्यादिवत्", text: "tatra vamanasādhyā viṣapītadaṣṭadigdhaviddhaviruddhājīrṇānnanavajvararājayakṣmātīsārādhoraktapittaviṣūcikālasakāvipākārocakāpacigranthyarbudaślīpadamedogadagaronmādāpasmāraśvāsakāsahṛllāsavīsarpapramehakuṣṭhapāṇḍuvartmamukhaghrāṇakapālarogakarṇarodhaśophastanyadoṣādayo doṣabhedīyoktāśca śleṣmavyādhayo viśeṣeṇa ete hi paraṃ vamanena nāśamupayānti salilāpagamanenāniṣpannaśālyādivat" },
      { type: "verse", number: "6", sanskrit: "अवाम्यास्तु गर्भिणीसुकुमारान्यकार्यव्यग्ररूक्षरूक्षाशनप्रायातिदीप्ताग्निभाराध्वकर्मनित्यक्लान्तक्षतक्षीणातिस्थूलकृशवृद्धबालदुर्बलश्रमभयशोकक्रोधमदमूर्छाक्षुत्पिपासार्त्तोपवासव्यवायव्यायामाध्ययनचिन्ताप्रसक्तच्छर्दिरूर्ध्वरक्तपित्तवातास्थापितानुवासितसंवृतकोष्ठदुश्छर्दितहृद्रोगोदावर्तमूत्राघातगुल्मप्लीहोदराष्ठीलार्शःस्वरोपघाततिमिरभ्रमानिलार्तार्दिताक्षेपकाक्षिणिरःशङ्खकर्णपार्श्वशूलिनो ऽनास्थापितकृमिणकोष्ठ इति अन्यत्रामगरीवषविरुद्धाभ्यवहोरभ्यः शीघ्रकारित्वादेषाम् तत्र गर्भिण्या गर्भव्यापदामगर्भभ्रंशाच्च दारुणरोगप्राप्तिः स्यात् सुकुमारस्य हृदयविकर्षणादूर्ध्वमधो वा रुधिरप्रवृत्तिः अन्यकार्यव्यग्रस्यौषधं न प्रवर्तते कृच्छ्रेण वा प्रवर्तमानमयोगदोषान् कुर्यात् रूक्षस्य वायुरङ्गग्रहणम् रूक्षाशनप्रायस्यं वायुना क्षपितदेहत्वाद् बलक्षयः स्यात् तथातिदीप्ताग्नेरग्निबलेन भाराध्वकर्मनित्ययानक्लान्तानां चायासेन क्षतस्य भूयःक्षणनाद्रक्तातिप्रवृत्तिः क्षीणादीनामौषधबलाक्षमत्वाद्देहबलोपरोधो ऽन्तःक्षतभयं च प्रसक्तच्छर्द्यूर्ध्वरक्तपित्तयोरुदान उत्क्षिप्य प्राणान् हरेद्रक्तं चातिप्रवर्तयेत् ऊर्ध्ववातास्थापितानुवासितानामूर्ध्वं वातातिप्रवृत्तिः संवृतकोष्ठस्य दुश्छर्दितस्य वातिमात्रप्रवाहणादन्तः कोष्ठसमुत्क्लिष्टैर्दोषैर्विसर्पस्तम्भजाड्यवैचित्यानि मरणं वा हृद्रोगिणो हृदयोपरोधः उदावर्तादिभिरार्तानामर्दितादिभिश्च यथायथमामयप्रवृद्धिर्मरणं वा कृमिणकोष्ठस्यास्थापनेनाधःपूर्वमनिर्हृतैः कृमिभिरतिबहुत्वादशेषानिस्सरणेन हृदयमतिकर्षद्भिश्छर्दिषो ऽतिप्रवृत्तिः स्यात्", text: "avāmyāstu garbhiṇīsukumārānyakāryavyagrarūkṣarūkṣāśanaprāyātidīptāgnibhārādhvakarmanityaklāntakṣatakṣīṇātisthūlakṛśavṛddhabāladurbalaśramabhayaśokakrodhamadamūrchākṣutpipāsārttopavāsavyavāyavyāyāmādhyayanacintāprasaktacchardirūrdhvaraktapittavātāsthāpitānuvāsitasaṃvṛtakoṣṭhaduścharditahṛdrogodāvartamūtrāghātagulmaplīhodarāṣṭhīlārśaḥsvaropaghātatimirabhramānilārtārditākṣepakākṣiṇiraḥśaṅkhakarṇapārśvaśūlino 'nāsthāpitakṛmiṇakoṣṭha iti anyatrāmagarīvaṣaviruddhābhyavahorabhyaḥ śīghrakāritvādeṣām tatra garbhiṇyā garbhavyāpadāmagarbhabhraṃśācca dāruṇarogaprāptiḥ syāt sukumārasya hṛdayavikarṣaṇādūrdhvamadho vā rudhirapravṛttiḥ anyakāryavyagrasyauṣadhaṃ na pravartate kṛcchreṇa vā pravartamānamayogadoṣān kuryāt rūkṣasya vāyuraṅgagrahaṇam rūkṣāśanaprāyasyaṃ vāyunā kṣapitadehatvād balakṣayaḥ syāt tathātidīptāgneragnibalena bhārādhvakarmanityayānaklāntānāṃ cāyāsena kṣatasya bhūyaḥkṣaṇanādraktātipravṛttiḥ kṣīṇādīnāmauṣadhabalākṣamatvāddehabaloparodho 'ntaḥkṣatabhayaṃ ca prasaktacchardyūrdhvaraktapittayorudāna utkṣipya prāṇān haredraktaṃ cātipravartayet ūrdhvavātāsthāpitānuvāsitānāmūrdhvaṃ vātātipravṛttiḥ saṃvṛtakoṣṭhasya duścharditasya vātimātrapravāhaṇādantaḥ koṣṭhasamutkliṣṭairdoṣairvisarpastambhajāḍyavaicityāni maraṇaṃ vā hṛdrogiṇo hṛdayoparodhaḥ udāvartādibhirārtānāmarditādibhiśca yathāyathamāmayapravṛddhirmaraṇaṃ vā kṛmiṇakoṣṭhasyāsthāpanenādhaḥpūrvamanirhṛtaiḥ kṛmibhiratibahutvādaśeṣānissaraṇena hṛdayamatikarṣadbhiśchardiṣo 'tipravṛttiḥ syāt" },
      { type: "verse", number: "7", sanskrit: "गर्भिण्यादिचिन्ताप्रसक्तान्ताश्चात्र धूमान्तैः प्रायः सर्वकर्मभिर्वक्ष्यमाणः परिहर्तव्याः अजीर्णी तु सर्वैरेव च वमनवर्ज्जैरामदोषभयात् नवज्वरस्य दोषस्तम्भभयादिति", text: "garbhiṇyādicintāprasaktāntāścātra dhūmāntaiḥ prāyaḥ sarvakarmabhirvakṣyamāṇaḥ parihartavyāḥ ajīrṇī tu sarvaireva ca vamanavarjjairāmadoṣabhayāt navajvarasya doṣastambhabhayāditi" },
      { type: "verse", number: "8", sanskrit: "अथ विरेचनसाध्या जीर्णज्वरोर्ध्वरक्तपित्तगुल्मविद्रधिप्लीहार्शोभगन्दरोदरकृमिणकोष्ठमूत्राघातरेतोयोनिदोषवातशोणितहलीमकव्यङ्गतिमिरकाचाभिष्यन्दाक्षिपाकक्षाराग्निदग्धकुष्टव्रणशिरःपक्वाशयशूलोदावर्तविबन्धच्छर्दिविस्फोटादयो वाम्योक्ताश्च विषूचिकादयो दोषभेदीयोक्ताश्च पित्तव्याधयः विशेषेणैते हि परं विरेचनेन नाशमुपयान्त्यग्न्यपनयनेनाग्निगृहतापवत्", text: "atha virecanasādhyā jīrṇajvarordhvaraktapittagulmavidradhiplīhārśobhagandarodarakṛmiṇakoṣṭhamūtrāghātaretoyonidoṣavātaśoṇitahalīmakavyaṅgatimirakācābhiṣyandākṣipākakṣārāgnidagdhakuṣṭavraṇaśiraḥpakvāśayaśūlodāvartavibandhacchardivisphoṭādayo vāmyoktāśca viṣūcikādayo doṣabhedīyoktāśca pittavyādhayaḥ viśeṣeṇaite hi paraṃ virecanena nāśamupayāntyagnyapanayanenāgnigṛhatāpavat" },
      { type: "verse", number: "9", sanskrit: "अविरेच्याः पुनर्नवज्वरातिसार्यधोरक्तपित्तक्षतगुदलङ्घतरात्रिजागरितास्थापिताल्पाग्निराजयक्ष्ममदात्ययार्ताध्मातसशल्याभिहततिस्निग्धरूक्षक्रूरकोष्ठाः तत्र नवज्वरस्याविपक्वान् दोषान्न निर्हरेत् वातमेव च कोपयेत् अतीसार्यधोरक्तपित्तयोरतिप्रवृत्त्या हन्यात् क्षतगुदस्य गुदे प्राणोपरोधकरीं राजयक्ष्मार्तस्य क्षीणधातुतया मलबलत्त्वम् तदभावाद्देहनाशः स्यात् मदात्ययार्तस्य मद्यक्षीणे देहे वायुः प्राणोपरोधाय आध्मातस्य पुरीषाशये निचितो वायुर्विसर्पन् सहसा तीव्रतरमाध्मानं मरणं वा जनयेत् सशल्याभिहतयोः क्षते वायुराश्रितो जीवितं हिंस्यात् अतिस्निग्धस्यातियोगो भवेत् क्रूरकोष्ठस्यौषधोद्धता दोषा ह्यप्रवर्तमाना हृदयशूलपर्वभेदानाहच्छर्दिमूर्च्छाक्लमान् जनयित्वा प्राणान् हन्युः गर्भिण्यादीनां पूर्वोक्तदोषः स्यात्", text: "avirecyāḥ punarnavajvarātisāryadhoraktapittakṣatagudalaṅghatarātrijāgaritāsthāpitālpāgnirājayakṣmamadātyayārtādhmātasaśalyābhihatatisnigdharūkṣakrūrakoṣṭhāḥ tatra navajvarasyāvipakvān doṣānna nirharet vātameva ca kopayet atīsāryadhoraktapittayoratipravṛttyā hanyāt kṣatagudasya gude prāṇoparodhakarīṃ rājayakṣmārtasya kṣīṇadhātutayā malabalattvam tadabhāvāddehanāśaḥ syāt madātyayārtasya madyakṣīṇe dehe vāyuḥ prāṇoparodhāya ādhmātasya purīṣāśaye nicito vāyurvisarpan sahasā tīvrataramādhmānaṃ maraṇaṃ vā janayet saśalyābhihatayoḥ kṣate vāyurāśrito jīvitaṃ hiṃsyāt atisnigdhasyātiyogo bhavet krūrakoṣṭhasyauṣadhoddhatā doṣā hyapravartamānā hṛdayaśūlaparvabhedānāhacchardimūrcchāklamān janayitvā prāṇān hanyuḥ garbhiṇyādīnāṃ pūrvoktadoṣaḥ syāt" },
      { type: "verse", number: "10", sanskrit: "अथ साधारणे काले सम्यक्स्निग्धस्विन्नमनुपहतमानसंश्वः च्छर्दयितव्यमिति ग्राम्यानूपौदकशृतमांसरसक्षीरदधिमाषतिलपललशाकादिभिर्द्रवप्रायैः समुत्क्लेशितश्लेष्माणं सुखोषितं जीर्णाहारं पूर्वाह्णे स्नातानुलिप्तं स्रग्विणमहतवाससं देवताग्निद्विजगुरुवृद्धवैद्यानर्चितवन्तं कृतहोमबलिमङ्गलप्रायश्चित्तस्वस्तिवचनं जानुसमसंस्तृतसोपधानोपाश्रयासनोपविष्टं निरन्नभीषत्स्निग्धं वा यवागू मण्डेन घृतमात्रां पीतवन्तं भीरुकृशबालवृद्धसुकुमारान् वा दोषानुरोधेनाकण्ठं पीतक्षीरतक्रयूषेक्षुमांसरसमद्यतुषोदकयवागूमण्डान्यतमं नक्षत्रतिथिकरणमुहूर्तोदये प्रशस्ते यथाव्याधिदोषदूष्यादिविहितामौषधमात्रां मधुसैन्धवयुक्तां सुखोष्णां ब्राह्मणप्रयुक्ताभिराशीर्भिराभिमन्त्रितां पुनश्च", text: "atha sādhāraṇe kāle samyaksnigdhasvinnamanupahatamānasaṃśvaḥ cchardayitavyamiti grāmyānūpaudakaśṛtamāṃsarasakṣīradadhimāṣatilapalalaśākādibhirdravaprāyaiḥ samutkleśitaśleṣmāṇaṃ sukhoṣitaṃ jīrṇāhāraṃ pūrvāhṇe snātānuliptaṃ sragviṇamahatavāsasaṃ devatāgnidvijaguruvṛddhavaidyānarcitavantaṃ kṛtahomabalimaṅgalaprāyaścittasvastivacanaṃ jānusamasaṃstṛtasopadhānopāśrayāsanopaviṣṭaṃ nirannabhīṣatsnigdhaṃ vā yavāgū maṇḍena ghṛtamātrāṃ pītavantaṃ bhīrukṛśabālavṛddhasukumārān vā doṣānurodhenākaṇṭhaṃ pītakṣīratakrayūṣekṣumāṃsarasamadyatuṣodakayavāgūmaṇḍānyatamaṃ nakṣatratithikaraṇamuhūrtodaye praśaste yathāvyādhidoṣadūṣyādivihitāmauṣadhamātrāṃ madhusaindhavayuktāṃ sukhoṣṇāṃ brāhmaṇaprayuktābhirāśīrbhirābhimantritāṃ punaśca" },
      { type: "verse", number: "11", sanskrit: "ब्रह्मदक्षाश्विरुद्रेन्द्रभूचन्द्रार्कानिलानलाः ऋषयः सौषधिग्रामा भूतसङ्घाश्च पान्तु वः", text: "brahmadakṣāśvirudrendrabhūcandrārkānilānalāḥ ṛṣayaḥ sauṣadhigrāmā bhūtasaṅghāśca pāntu vaḥ" },
      { type: "verse", number: "12", sanskrit: "रसायनीमवर्षीणाममराणाभिवामृतम् सुधेवोत्तमनागानां भैषज्यभिदमस्तु ते", text: "rasāyanīmavarṣīṇāmamarāṇābhivāmṛtam sudhevottamanāgānāṃ bhaiṣajyabhidamastu te" },
      { type: "verse", number: "13", sanskrit: "औम् नामो भगवते भैषज्यगुरवे वैडूर्यप्रभराजाय तथागतायार्हते सम्यक्सम्बुद्धाय तद्यथा औम् भैषज्ये भैषज्ये महाभैषज्ये भैषज्यसमुद्गते स्वाहा इत्येवमभिमन्त्र्योदग्मुखः प्राङ्मुखमातुरं पाययेत्", text: "aum nāmo bhagavate bhaiṣajyagurave vaiḍūryaprabharājāya tathāgatāyārhate samyaksambuddhāya tadyathā aum bhaiṣajye bhaiṣajye mahābhaiṣajye bhaiṣajyasamudgate svāhā ityevamabhimantryodagmukhaḥ prāṅmukhamāturaṃ pāyayet" },
      { type: "verse", number: "14", sanskrit: "ततः पीतवानूरुन्यस्तभुजो वमनानुगतमानसोग्नितप्तैः पाणिभिरुपतप्यमानो मुहूर्तमनुपालयेत् स यदा जानीयात् स्वेदप्रादुर्भावेन दोषं प्रविलयमापद्यमानं रोमहर्षेण च स्थानेभ्यः प्रविचलितं कुक्ष्याध्मानेन च कुक्षिमनुसृतं च क्रमात् हृदयोपमर्दहृल्लासास्यसंस्रवणैश्चोर्ध्वमभिमुखीभूतम् अथ समुपस्थितानेकप्रतिग्राहः पार्श्वललाटोपग्रहणे नाभिप्रपीडने पृष्ठप्रतिलोमोन्मर्दने च प्रवृत्ताव्यपत्रपणीयपुरुषो विवृतोष्ठतालुकण्ठो नातिमहता व्यायामेन वेगानुदीरयन् नाप्रवृत्तान् न प्रवर्त्तयन् प्रवृत्तांश्चानुप्रवर्तयन् सुपरिलिखितनखाभ्यामङ्गुलीभ्यामुत्पलकुमुदैरण्डनालैर्वा कण्ठमभिमृशन् वमेत् नात्युन्नतो नात्ववनतो न पार्श्वापवृत्तो वा तत्रात्युन्नतस्य पृष्ठहृदयपीडा भवति अत्यवनतस्य शिरःकोष्ठपीडा पार्श्वापवृत्तस्य पार्श्वकोष्ठहृदयोर्ध्वजत्रुपीडेति", text: "tataḥ pītavānūrunyastabhujo vamanānugatamānasognitaptaiḥ pāṇibhirupatapyamāno muhūrtamanupālayet sa yadā jānīyāt svedaprādurbhāvena doṣaṃ pravilayamāpadyamānaṃ romaharṣeṇa ca sthānebhyaḥ pravicalitaṃ kukṣyādhmānena ca kukṣimanusṛtaṃ ca kramāt hṛdayopamardahṛllāsāsyasaṃsravaṇaiścordhvamabhimukhībhūtam atha samupasthitānekapratigrāhaḥ pārśvalalāṭopagrahaṇe nābhiprapīḍane pṛṣṭhapratilomonmardane ca pravṛttāvyapatrapaṇīyapuruṣo vivṛtoṣṭhatālukaṇṭho nātimahatā vyāyāmena vegānudīrayan nāpravṛttān na pravarttayan pravṛttāṃścānupravartayan suparilikhitanakhābhyāmaṅgulībhyāmutpalakumudairaṇḍanālairvā kaṇṭhamabhimṛśan vamet nātyunnato nātvavanato na pārśvāpavṛtto vā tatrātyunnatasya pṛṣṭhahṛdayapīḍā bhavati atyavanatasya śiraḥkoṣṭhapīḍā pārśvāpavṛttasya pārśvakoṣṭhahṛdayordhvajatrupīḍeti" },
      { type: "verse", number: "15", sanskrit: "एवं कटुतीक्ष्णोष्णैः कफे छर्दयेत् स्वादुभिः पित्तयुक्ते अम्लैः सस्नेहैरनिलसंसृष्टे यावत् कफच्छेदः केवलमौषधप्रवृत्तिः पित्तदर्शनं वा", text: "evaṃ kaṭutīkṣṇoṣṇaiḥ kaphe chardayet svādubhiḥ pittayukte amlaiḥ sasnehairanilasaṃsṛṣṭe yāvat kaphacchedaḥ kevalamauṣadhapravṛttiḥ pittadarśanaṃ vā" },
      { type: "verse", number: "16", sanskrit: "हीनवेगस्तु पिप्पल्यामलकसर्षपकल्कलवणोष्णोदकैः पुनःपुनः प्रवर्तयेत् प्रभूतवमनासहिष्णुर्द्व्यहं त्र्यहं वा विश्रम्य असात्म्यबीभत्सदुर्दर्शदुर्गन्धानि वमनानि विदध्यात् विपरीतानि तु विरेचनानि सर्वेषु च वमनेषु सैन्धवं मधु च विदध्यात्कफविलयनविच्छेदनार्थम् वेगांश्चास्य प्रतिग्राहगतानावेक्षेत", text: "hīnavegastu pippalyāmalakasarṣapakalkalavaṇoṣṇodakaiḥ punaḥpunaḥ pravartayet prabhūtavamanāsahiṣṇurdvyahaṃ tryahaṃ vā viśramya asātmyabībhatsadurdarśadurgandhāni vamanāni vidadhyāt viparītāni tu virecanāni sarveṣu ca vamaneṣu saindhavaṃ madhu ca vidadhyātkaphavilayanavicchedanārtham vegāṃścāsya pratigrāhagatānāvekṣeta" },
      { type: "verse", number: "17", sanskrit: "तत्राप्रवृत्तिः केवलस्य वा भेषजस्य प्रवृत्तिर्विबन्धो वा वेगानामयोगलक्षणम् ततश्चारोचकगौरवाध्मानकण्डूस्फोटकोठालस्यशूलप्रतिश्यायलोमहर्षप्रसेकशोफशीतज्वरादयः", text: "tatrāpravṛttiḥ kevalasya vā bheṣajasya pravṛttirvibandho vā vegānāmayogalakṣaṇam tataścārocakagauravādhmānakaṇḍūsphoṭakoṭhālasyaśūlapratiśyāyalomaharṣaprasekaśophaśītajvarādayaḥ" },
      { type: "verse", number: "18", sanskrit: "योगलक्षणं पुनः काले क्रमात् कफपित्तानिलप्रवृत्तिर्नातिमहती व्यथा स्वयं चावस्थानं ततश्च स्वस्थता मनःप्रसादः स्वरविशुद्धिररोचकादिवैपरीत्यं च", text: "yogalakṣaṇaṃ punaḥ kāle kramāt kaphapittānilapravṛttirnātimahatī vyathā svayaṃ cāvasthānaṃ tataśca svasthatā manaḥprasādaḥ svaraviśuddhirarocakādivaiparītyaṃ ca" },
      { type: "verse", number: "19", sanskrit: "अतियोगे तु फेनिलरक्तचन्द्रिकोद्गमनम् ततश्च क्षामतास्वरक्षयदाहकण्ठशोषभ्रममोहोन्मादमूर्च्छाशिरःशून्यताहृद्धूमायनगात्रशूलसुप्तितृष्णोर्ध्वानिलप्रकोपकर्णशूलार्द्दितवाक्सङ्गहनुसंहननजिह्वाप्रवेशनिर्गमाक्षिव्यावृत्तिविसंज्ञतानिद्राबलाग्निहानयो भवन्ति जीवशोणितप्रवृत्त्या मरणं वा एषां सिद्धिषु साधनं वक्ष्यते", text: "atiyoge tu phenilaraktacandrikodgamanam tataśca kṣāmatāsvarakṣayadāhakaṇṭhaśoṣabhramamohonmādamūrcchāśiraḥśūnyatāhṛddhūmāyanagātraśūlasuptitṛṣṇordhvānilaprakopakarṇaśūlārdditavāksaṅgahanusaṃhananajihvāpraveśanirgamākṣivyāvṛttivisaṃjñatānidrābalāgnihānayo bhavanti jīvaśoṇitapravṛttyā maraṇaṃ vā eṣāṃ siddhiṣu sādhanaṃ vakṣyate" },
      { type: "verse", number: "20", sanskrit: "योगेन तु खल्वेनं छर्दितवन्तं सुविशोधितपाणिपादमुखं मुहूर्तमाश्वास्य धूमत्रयस्यान्यतमं सामर्थ्यतः पाययित्वा पुनरुपस्पृष्टोदकं सम्मानितसुरभिताम्बूलं निवातागारशय्यास्थितं स्नेहोक्तेनाचारविधिनानुशिष्यात्", text: "yogena tu khalvenaṃ charditavantaṃ suviśodhitapāṇipādamukhaṃ muhūrtamāśvāsya dhūmatrayasyānyatamaṃ sāmarthyataḥ pāyayitvā punarupaspṛṣṭodakaṃ sammānitasurabhitāmbūlaṃ nivātāgāraśayyāsthitaṃ snehoktenācāravidhinānuśiṣyāt" },
      { type: "verse", number: "21", sanskrit: "ततोग्निबलमवेक्ष्य क्षुधं च सायाह्ने अपरे वाह्नि सुखोदकपरिषिक्तः पुराणानां रक्तशालितण्डुलानां सुसिद्धमन्नमस्नेहलवणकटुकमल्पस्नेहलवणकटुकं वा द्रवप्रायमुष्णोदकानुप्रायं सायं प्रातरुपभुञ्जानो विधिमिममवेक्षेत पेयादीनाम्", text: "tatognibalamavekṣya kṣudhaṃ ca sāyāhne apare vāhni sukhodakapariṣiktaḥ purāṇānāṃ raktaśālitaṇḍulānāṃ susiddhamannamasnehalavaṇakaṭukamalpasnehalavaṇakaṭukaṃ vā dravaprāyamuṣṇodakānuprāyaṃ sāyaṃ prātarupabhuñjāno vidhimimamavekṣeta peyādīnām" },
      { type: "verse", number: "22", sanskrit: "पेयां विलेपीमकृतं कृतं च यूषं रसं त्रीनुभयं तथैकम् क्रमेण सेवेत नरो ऽन्नकालान् प्रधानमध्यावरशुद्धिशुद्धः", text: "peyāṃ vilepīmakṛtaṃ kṛtaṃ ca yūṣaṃ rasaṃ trīnubhayaṃ tathaikam krameṇa seveta naro 'nnakālān pradhānamadhyāvaraśuddhiśuddhaḥ" },
      { type: "verse", number: "23", sanskrit: "यथाणुरग्निस्तृणगोमयाद्यैः सन्धुक्ष्यमाणो भवति क्रमेण महान् स्थिरः सर्वपचस्तथैव शुद्धस्य पेयादिभिरन्तराग्निः", text: "yathāṇuragnistṛṇagomayādyaiḥ sandhukṣyamāṇo bhavati krameṇa mahān sthiraḥ sarvapacastathaiva śuddhasya peyādibhirantarāgniḥ" },
      { type: "verse", number: "24", sanskrit: "जघन्यमध्यप्रवरे तु वेगाश्चत्वार इष्टा वमने षडष्टौ दशैव ते द्वित्रिगुणा विरेके प्रस्थस्तथास्याद् द्विचतुर्गुणश्च", text: "jaghanyamadhyapravare tu vegāścatvāra iṣṭā vamane ṣaḍaṣṭau daśaiva te dvitriguṇā vireke prasthastathāsyād dvicaturguṇaśca" },
      { type: "verse", number: "25", sanskrit: "पित्तावसानं वमनं विरेकादर्द्धं कफान्तं च विरेकमाहुः द्वित्रान् सविट्कानपनीय वेगान् मेयं विरेके वमने तु पीतम् इति", text: "pittāvasānaṃ vamanaṃ virekādarddhaṃ kaphāntaṃ ca virekamāhuḥ dvitrān saviṭkānapanīya vegān meyaṃ vireke vamane tu pītam iti" },
      { type: "verse", number: "26", sanskrit: "अथ वमितवन्तं पुनरेवं स्नेहस्वेदाभ्यामुपपाद्यश्वो विरेचयितव्य इति सुजरमश्लेष्मलं स्निग्धं फलाम्लमुष्णमुष्णोदकानुपानं जाङ्गलरसौदनं भोजयेत् ततः सुखोषितं पूर्वोक्तेन विधिनातीते श्लेष्मकाले निरन्नं विभज्य कोष्ठं यथार्हौषधमात्रां पाययेत् न त्वकृतवमनमन्यत्रातिक्रूरकोष्ठात्", text: "atha vamitavantaṃ punarevaṃ snehasvedābhyāmupapādyaśvo virecayitavya iti sujaramaśleṣmalaṃ snigdhaṃ phalāmlamuṣṇamuṣṇodakānupānaṃ jāṅgalarasaudanaṃ bhojayet tataḥ sukhoṣitaṃ pūrvoktena vidhinātīte śleṣmakāle nirannaṃ vibhajya koṣṭhaṃ yathārhauṣadhamātrāṃ pāyayet na tvakṛtavamanamanyatrātikrūrakoṣṭhāt" },
      { type: "verse", number: "27", sanskrit: "अकृतवमनस्य हि श्लेष्मणोपहतमौषधमूर्ध्वं प्रवर्तते उरसि वावरुद्धमवतिष्ठते ततो नालं विरेकाय सम्यग्विरिक्तस्यापि चाधःस्रस्तः श्लेष्मा ग्रहणीं छादयित्वा गौरवमापादयति प्रवाहिकां वा न त्वेष दोषो ऽतुक्रूरकोष्ठस्य वाय्वात्मकत्वात्", text: "akṛtavamanasya hi śleṣmaṇopahatamauṣadhamūrdhvaṃ pravartate urasi vāvaruddhamavatiṣṭhate tato nālaṃ virekāya samyagviriktasyāpi cādhaḥsrastaḥ śleṣmā grahaṇīṃ chādayitvā gauravamāpādayati pravāhikāṃ vā na tveṣa doṣo 'tukrūrakoṣṭhasya vāyvātmakatvāt" },
      { type: "verse", number: "28", sanskrit: "श्लेष्मकाले त्वकृतवमनोक्तदोषाः शूलाध्मानगौरवाणि वा कृत्वा छर्दिक्षीणे श्लेष्मण्यपराह्णे रात्रौ वा विरेचयेत् तेनान्नावृतमपि तुल्यम् छर्द्रिं च पुनस्तज्जनयति अविरिक्तस्य तु श्लेष्मकाले च वमनं निरन्नं योज्यम् तथोर्ध्वं सुखेन निर्हरणात्", text: "śleṣmakāle tvakṛtavamanoktadoṣāḥ śūlādhmānagauravāṇi vā kṛtvā chardikṣīṇe śleṣmaṇyaparāhṇe rātrau vā virecayet tenānnāvṛtamapi tulyam chardriṃ ca punastajjanayati aviriktasya tu śleṣmakāle ca vamanaṃ nirannaṃ yojyam tathordhvaṃ sukhena nirharaṇāt" },
      { type: "verse", number: "29", sanskrit: "कोष्ठस्तु त्रिविधो भवति मृदुः क्रूरो मध्यमश्च तत्र बहुपित्तो मृदुः स विरिच्यते क्षीरेक्षुरसाम्लतक्रमस्तुगुडकृसरसर्पिर्नवमद्योष्णोदकपीलुद्राक्षापूगफलादिभिरपि बहुवातः क्रूरः स दुर्विरेच्यस्त्रिफलातिल्वकत्रिवृन्नीलिनीफलादिभिरपि बहुश्लेष्मासमदोषश्च मध्यः स साधारणः ये च स्निह्यन्त्यच्छपानेन प्रायशः त्रिसप्तपञ्चरात्रैरिति", text: "koṣṭhastu trividho bhavati mṛduḥ krūro madhyamaśca tatra bahupitto mṛduḥ sa viricyate kṣīrekṣurasāmlatakramastuguḍakṛsarasarpirnavamadyoṣṇodakapīludrākṣāpūgaphalādibhirapi bahuvātaḥ krūraḥ sa durvirecyastriphalātilvakatrivṛnnīlinīphalādibhirapi bahuśleṣmāsamadoṣaśca madhyaḥ sa sādhāraṇaḥ ye ca snihyantyacchapānena prāyaśaḥ trisaptapañcarātrairiti" },
      { type: "verse", number: "30", sanskrit: "तत्र कषायमधुरद्रव्यैः पित्ते विरेचनम् मूत्रकटूष्णैः कफे स्निग्धोष्णलवणैर्वाते पीतमात्र एव चौषधे छर्दिविघाताय शीताम्बुना मुखमस्य सहसा सिञ्चेत् ततश्चोष्णोदकेन सो ऽन्तर्मुखं विशोध्यार्द्रसुरभिमृन्मातुलुङ्गजम्बीरसुमनःसौगन्धिकादिहृद्यगन्धानुपजिघ्रेत् निवातसुखशय्यास्थितश्चाविबन्धार्थमल्पाल्पमुष्णोदकमनुकण्ठयंस्तन्मना वेगान्न धारयन् ईरयमाणाश्च शय्यासन्ने प्रतिग्राहे ऽशीतस्पृग्विरिच्येत यथा च वमने स्वेदप्रसेकौषधकफपित्तानिलाः क्रमेण प्रवर्तन्ते तथा विरेचने वातमूत्रपुरीषपित्तकफाः पुनश्चान्ते वायुः दोषाणां हि देहे तथा सन्निवेशान्मार्गवैपरीत्याच्च शोधनयोरिति", text: "tatra kaṣāyamadhuradravyaiḥ pitte virecanam mūtrakaṭūṣṇaiḥ kaphe snigdhoṣṇalavaṇairvāte pītamātra eva cauṣadhe chardivighātāya śītāmbunā mukhamasya sahasā siñcet tataścoṣṇodakena so 'ntarmukhaṃ viśodhyārdrasurabhimṛnmātuluṅgajambīrasumanaḥsaugandhikādihṛdyagandhānupajighret nivātasukhaśayyāsthitaścāvibandhārthamalpālpamuṣṇodakamanukaṇṭhayaṃstanmanā vegānna dhārayan īrayamāṇāśca śayyāsanne pratigrāhe 'śītaspṛgviricyeta yathā ca vamane svedaprasekauṣadhakaphapittānilāḥ krameṇa pravartante tathā virecane vātamūtrapurīṣapittakaphāḥ punaścānte vāyuḥ doṣāṇāṃ hi dehe tathā sanniveśānmārgavaiparītyācca śodhanayoriti" },
      { type: "verse", number: "31", sanskrit: "अप्रवृत्तौ तु भेषजोत्तेजनार्थमुष्णोदकं पाययेत् पाणितापैश्च जठरं स्वेदयेत् प्रवृत्ते च दीप्ताग्नेः स्निग्धवपुषा बहुदोषस्याल्पदोषे नैव वा प्रवृत्ते ऽल्पदोषस्यापि जीर्णभैषज्यस्याहःशेषं बलं चापेक्ष्य भूयो मात्रां विदध्यात् न त्वजीर्णौषधस्यातियोगभयात्", text: "apravṛttau tu bheṣajottejanārthamuṣṇodakaṃ pāyayet pāṇitāpaiśca jaṭharaṃ svedayet pravṛtte ca dīptāgneḥ snigdhavapuṣā bahudoṣasyālpadoṣe naiva vā pravṛtte 'lpadoṣasyāpi jīrṇabhaiṣajyasyāhaḥśeṣaṃ balaṃ cāpekṣya bhūyo mātrāṃ vidadhyāt na tvajīrṇauṣadhasyātiyogabhayāt" },
      { type: "verse", number: "32", sanskrit: "तदहर्वा भुक्तवतो ऽन्येद्युरदृढस्नेहं वा दशरात्रादूर्ध्वमुपस्कृतदेहमवहितो भूयः पाययेत्", text: "tadaharvā bhuktavato 'nyedyuradṛḍhasnehaṃ vā daśarātrādūrdhvamupaskṛtadehamavahito bhūyaḥ pāyayet" },
      { type: "verse", number: "33", sanskrit: "ह्रीभयलोभैश्च वेगाघातशीलाः प्रायशः स्त्रियो राजसमीपस्था वणिजश्च भवन्ति तस्मादेते वेगधारणप्रवृद्धवातत्वात्सदातुरा दुर्विरेच्याश्च तान् सुस्निग्धान् शोधयेत्", text: "hrībhayalobhaiśca vegāghātaśīlāḥ prāyaśaḥ striyo rājasamīpasthā vaṇijaśca bhavanti tasmādete vegadhāraṇapravṛddhavātatvātsadāturā durvirecyāśca tān susnigdhān śodhayet" },
      { type: "verse", number: "34", sanskrit: "अन्यानपि चाकालनिर्हारविहाराहारान् ततश्चैषां सदातुरत्वादल्पो ऽप्यामयो दुःसाध्यो भवति तेषां पुनः क्रियाविधिः स्नेहव्यापत्सिद्धावुपदेक्ष्यते", text: "anyānapi cākālanirhāravihārāhārān tataścaiṣāṃ sadāturatvādalpo 'pyāmayo duḥsādhyo bhavati teṣāṃ punaḥ kriyāvidhiḥ snehavyāpatsiddhāvupadekṣyate" },
      { type: "verse", number: "35", sanskrit: "तत्रासम्यग्विरेकात् कुक्षिहृदयाविशुद्धिराध्मानमरुचिः प्रसेकः कफपित्तोत्क्लेशछर्दिभ्रमाः कण्डू पिटका विदाहो गौरवमग्निसादस्तन्द्रा स्तैमित्यं प्रतिश्यायो वातविण्मूत्रसङ्गश्च सम्यग्विरेकात् व्याध्युपशमो यथोक्तविपर्ययश्च अतिविरेकात्तु केवलं दोषरहितमुदकं रक्तं वा मेदोमांसधावनोपमं कृष्णं वा प्रवर्तते परिकर्तिका हृदयोद्वेष्टनं गुदनिस्सरणं नयनप्रवेशः पिपीलिकासञ्चार इवाङ्गे वमनातियोगतुल्यता च", text: "tatrāsamyagvirekāt kukṣihṛdayāviśuddhirādhmānamaruciḥ prasekaḥ kaphapittotkleśachardibhramāḥ kaṇḍū piṭakā vidāho gauravamagnisādastandrā staimityaṃ pratiśyāyo vātaviṇmūtrasaṅgaśca samyagvirekāt vyādhyupaśamo yathoktaviparyayaśca ativirekāttu kevalaṃ doṣarahitamudakaṃ raktaṃ vā medomāṃsadhāvanopamaṃ kṛṣṇaṃ vā pravartate parikartikā hṛdayodveṣṭanaṃ gudanissaraṇaṃ nayanapraveśaḥ pipīlikāsañcāra ivāṅge vamanātiyogatulyatā ca" },
      { type: "verse", number: "36", sanskrit: "सम्यग्विरिक्तं चैनं वमनोक्तेन धूमवर्ज्येन विधिनोपपादयेत् अथ वमितवानिव क्रमेणान्नान्युपयुञ्जानः प्रकृतिभोजनमागच्छेदिति भवति चात्र", text: "samyagviriktaṃ cainaṃ vamanoktena dhūmavarjyena vidhinopapādayet atha vamitavāniva krameṇānnānyupayuñjānaḥ prakṛtibhojanamāgacchediti bhavati cātra" },
      { type: "verse", number: "37", sanskrit: "जीर्णे ऽन्ने वमनं योज्यं कफे जीर्णे विरेचनम् मन्दवह्निमस्ंशुद्धमक्षामं दोषदुर्बलम्", text: "jīrṇe 'nne vamanaṃ yojyaṃ kaphe jīrṇe virecanam mandavahnimasṃśuddhamakṣāmaṃ doṣadurbalam" },
      { type: "verse", number: "38", sanskrit: "अदृष्टजीर्णलिङ्गं च लङ्घयेत् पीतभेषजम् स्नेहस्वेदौषधोत्क्लेशसङ्गैरिति न बाध्यते", text: "adṛṣṭajīrṇaliṅgaṃ ca laṅghayet pītabheṣajam snehasvedauṣadhotkleśasaṅgairiti na bādhyate" },
      { type: "verse", number: "39", sanskrit: "संशोधनास्रविस्रावस्नेहयोजनलङ्घनैः यात्यग्निर्मन्दतां तस्मात् क्रमं पेयादिमाचरेत्", text: "saṃśodhanāsravisrāvasnehayojanalaṅghanaiḥ yātyagnirmandatāṃ tasmāt kramaṃ peyādimācaret" },
      { type: "verse", number: "40", sanskrit: "स्रुताल्पपित्तश्लेष्माणं मद्यपं वातपैत्तिकम् पेयां न पाययेत्तेषां तर्पणादिक्रमो हितः", text: "srutālpapittaśleṣmāṇaṃ madyapaṃ vātapaittikam peyāṃ na pāyayetteṣāṃ tarpaṇādikramo hitaḥ" },
      { type: "verse", number: "41", sanskrit: "अपक्वं वमनं दोषान् पच्यमानं विरेचनम् निर्हरेद्वमनस्यातः पाकं न प्रतिपालयेत्", text: "apakvaṃ vamanaṃ doṣān pacyamānaṃ virecanam nirharedvamanasyātaḥ pākaṃ na pratipālayet" },
      { type: "verse", number: "42", sanskrit: "ऊर्ध्वाधोरेचनं युक्तं वैपरीत्येन जायते यदा तदा छर्दयतः सिञ्चेदुष्णेन वारिणा पादौ शीतेन चोर्ध्वाङ्गं विपरीतं विरेचने", text: "ūrdhvādhorecanaṃ yuktaṃ vaiparītyena jāyate yadā tadā chardayataḥ siñceduṣṇena vāriṇā pādau śītena cordhvāṅgaṃ viparītaṃ virecane" },
      { type: "verse", number: "43", sanskrit: "दुर्बलो बहुदोषश्च दोषपाकेन यः स्वयम् विरिच्यते भेदनीयैर्भोज्यैस्तमुपपादयेत्", text: "durbalo bahudoṣaśca doṣapākena yaḥ svayam viricyate bhedanīyairbhojyaistamupapādayet" },
      { type: "verse", number: "44", sanskrit: "दुर्बलः शोधितः पूर्वमल्पदोषः कृशो नरः अपरिज्ञातकोष्ठश्च पिबेन्मृद्वल्पमौषधम् वरं तदसकृत् पीतमन्यथा संशयावहम्", text: "durbalaḥ śodhitaḥ pūrvamalpadoṣaḥ kṛśo naraḥ aparijñātakoṣṭhaśca pibenmṛdvalpamauṣadham varaṃ tadasakṛt pītamanyathā saṃśayāvaham" },
      { type: "verse", number: "45", sanskrit: "हरेद् बहूंश्चलान् दोषानल्पानल्पान् पुनःपुनः दुर्बलस्य मृदुद्रव्यैरल्पान् संशमये त्तुतान् क्लेशयन्ति चिरं ते हि हन्युर्वैनमनिर्हृताः", text: "hared bahūṃścalān doṣānalpānalpān punaḥpunaḥ durbalasya mṛdudravyairalpān saṃśamaye ttutān kleśayanti ciraṃ te hi hanyurvainamanirhṛtāḥ" },
      { type: "verse", number: "46", sanskrit: "मन्दाग्निं क्रूरकोष्ठं च सक्षारलवणैर्घृतैः सन्धुक्षिताग्निं विजितकफवातं च शोधयेत्", text: "mandāgniṃ krūrakoṣṭhaṃ ca sakṣāralavaṇairghṛtaiḥ sandhukṣitāgniṃ vijitakaphavātaṃ ca śodhayet" },
      { type: "verse", number: "47", sanskrit: "रूक्षबह्वनिलक्रूरकोष्ठव्यायामशीलिनाम् दीप्ताग्नीनां च भैषज्यमविरेच्यैव जीर्यति", text: "rūkṣabahvanilakrūrakoṣṭhavyāyāmaśīlinām dīptāgnīnāṃ ca bhaiṣajyamavirecyaiva jīryati" },
      { type: "verse", number: "48", sanskrit: "तेभ्यो बस्तिं पुरो दद्यात्ततः स्निग्धं विरेचनम् शकृन्निर्हृत्य वा किञ्चित्तीक्ष्णाभिः फलवर्त्तिभिः प्रवृत्तं हि मलं सिग्धो विरेको निर्हरेत्सुखम्", text: "tebhyo bastiṃ puro dadyāttataḥ snigdhaṃ virecanam śakṛnnirhṛtya vā kiñcittīkṣṇābhiḥ phalavarttibhiḥ pravṛttaṃ hi malaṃ sigdho vireko nirharetsukham" },
      { type: "verse", number: "49", sanskrit: "विषाभिघातपिटकाकुष्ठशोफविसर्पिणः कामलापाण्डुमेहार्तान् नातिस्निग्धान् विशोधयेत्", text: "viṣābhighātapiṭakākuṣṭhaśophavisarpiṇaḥ kāmalāpāṇḍumehārtān nātisnigdhān viśodhayet" },
      { type: "verse", number: "50", sanskrit: "सर्वान् स्नेहविरेकैश्च रूक्षैस्तु स्नेहभावितान्", text: "sarvān snehavirekaiśca rūkṣaistu snehabhāvitān" },
      { type: "verse", number: "51", sanskrit: "कर्मणां वमनादीनां पुनरप्यन्तरे ऽन्तरे स्नेहस्वेदौ प्रयुञ्जीत स्नेहमन्ते बलाय च", text: "karmaṇāṃ vamanādīnāṃ punarapyantare 'ntare snehasvedau prayuñjīta snehamante balāya ca" },
      { type: "verse", number: "52", sanskrit: "ऊषादिभिर्यथोत्क्लेश्य ह्रियते वाससो मलः तथैव वपुषः स्नेहस्वेदमाषतिलादिभिः", text: "ūṣādibhiryathotkleśya hriyate vāsaso malaḥ tathaiva vapuṣaḥ snehasvedamāṣatilādibhiḥ" },
      { type: "verse", number: "53", sanskrit: "स्नेहस्वेदावनभ्यस्य कुर्यात्संशोधनं तु यः दारुशुष्कमिवानामे शरीरं तस्य दीर्यते", text: "snehasvedāvanabhyasya kuryātsaṃśodhanaṃ tu yaḥ dāruśuṣkamivānāme śarīraṃ tasya dīryate" },
      { type: "verse", number: "54", sanskrit: "सुखं क्षिप्रं महावेगमसक्तं यत् प्रवर्तते नातिग्लानिकरं नापि हृदि पायौ च रुक्करम्", text: "sukhaṃ kṣipraṃ mahāvegamasaktaṃ yat pravartate nātiglānikaraṃ nāpi hṛdi pāyau ca rukkaram" },
      { type: "verse", number: "55", sanskrit: "अन्तराशयगं क्लिन्नं कृत्स्नं दोषं निरस्यति विरेचनं निरूहं वा तत्तीक्ष्णमिति निर्दिशेत्", text: "antarāśayagaṃ klinnaṃ kṛtsnaṃ doṣaṃ nirasyati virecanaṃ nirūhaṃ vā tattīkṣṇamiti nirdiśet" },
      { type: "verse", number: "56", sanskrit: "जलाग्निकीटैरस्पृष्टं देशकालगुणान्वितम् नवं मात्राधिकं किञ्चित् तुल्यवीर्यैः सुभावितम्", text: "jalāgnikīṭairaspṛṣṭaṃ deśakālaguṇānvitam navaṃ mātrādhikaṃ kiñcit tulyavīryaiḥ subhāvitam" },
      { type: "verse", number: "57", sanskrit: "स्नेहस्वेदोपपन्नस्य तीक्ष्णत्वं याति भेषजम् अतो विपर्यये मन्दं मन्दतां च प्रपद्यते", text: "snehasvedopapannasya tīkṣṇatvaṃ yāti bheṣajam ato viparyaye mandaṃ mandatāṃ ca prapadyate" },
      { type: "verse", number: "58", sanskrit: "तीक्ष्णो मध्यो मृदुर्व्याधिः सर्वमध्याल्पलक्षणः बलापेक्षं हितं तेषु तीक्ष्णं मध्यं मृदु क्रमात्", text: "tīkṣṇo madhyo mṛdurvyādhiḥ sarvamadhyālpalakṣaṇaḥ balāpekṣaṃ hitaṃ teṣu tīkṣṇaṃ madhyaṃ mṛdu kramāt" },
      { type: "verse", number: "59", sanskrit: "अप्रवर्त्य मलान् द्रव्यं सात्मीभूतं हि जीर्यति वमनं वा विरेकं वा तस्मात्सात्म्यं न योजयेत्", text: "apravartya malān dravyaṃ sātmībhūtaṃ hi jīryati vamanaṃ vā virekaṃ vā tasmātsātmyaṃ na yojayet" },
      { type: "verse", number: "60", sanskrit: "विभ्रंशो विषवत्सम्यग्योगो यस्यामृतोपमः काले ऽवश्यं प्रयोज्यं च यस्माद्यत्नेन तत् पिबेत्", text: "vibhraṃśo viṣavatsamyagyogo yasyāmṛtopamaḥ kāle 'vaśyaṃ prayojyaṃ ca yasmādyatnena tat pibet" },
      { type: "verse", number: "61", sanskrit: "बुद्धिप्रसादं बलमिन्द्रियाणां धातुस्ह्तिरत्वं ज्वलनस्य दीप्तिम् चिराच्च पाकं वयसः करोति संशोधनं सम्यगुपास्यमानम्", text: "buddhiprasādaṃ balamindriyāṇāṃ dhātushtiratvaṃ jvalanasya dīptim cirācca pākaṃ vayasaḥ karoti saṃśodhanaṃ samyagupāsyamānam" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 28,
    lang: "sa",
    content: [
      { type: "heading", heading: "Индрия видхи — уход за чувствами" },
      { type: "text", text: "Глава 28 Сутрастханы Астанга-санграхи посвящена теме «уход за чувствами». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो बस्तिविधिं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bastividhiṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "बस्तिरनिलप्रधानेषु दोषेषु प्रयुज्यते बस्तिना दीयते बस्तिं वा पूर्वमन्वेत्यतो बस्तिः", text: "bastiranilapradhāneṣu doṣeṣu prayujyate bastinā dīyate bastiṃ vā pūrvamanvetyato bastiḥ" },
      { type: "verse", number: "3", sanskrit: "स च सर्वोपक्रमाणां प्रधानतमः शीघ्रं बृंहणादिकारित्वाद्विकृतानिलोच्छेदित्वाच्च", text: "sa ca sarvopakramāṇāṃ pradhānatamaḥ śīghraṃ bṛṃhaṇādikāritvādvikṛtāniloccheditvācca" },
      { type: "verse", number: "4", sanskrit: "अनिलो हि दोषाणां नेता सर्वशरीरचेष्टैककारणम् पञ्चात्मतया अङ्गप्रत्यङ्गव्यापी विधाता विविधबाह्याध्यात्मिकभावानां सर्गस्थितिप्रलयानां हेतुः मार्गत्रयजानामपि रोगाणामिति", text: "anilo hi doṣāṇāṃ netā sarvaśarīraceṣṭaikakāraṇam pañcātmatayā aṅgapratyaṅgavyāpī vidhātā vividhabāhyādhyātmikabhāvānāṃ sargasthitipralayānāṃ hetuḥ mārgatrayajānāmapi rogāṇāmiti" },
      { type: "verse", number: "5", sanskrit: "सुखत्वादेव च बस्तिर्बालवृद्धकृशस्थूलक्षीणधात्विन्द्रियेषु च स्त्रीषु चानिलोपसर्गादप्रजासु कृच्छ्रप्रजासुचोपदिश्यते तथाग्निबलवर्णमेधास्वरायुःसुखप्रदो वयःस्थापनः पङ्गूरुस्तम्भभग्नसङ्कुचितानिलाध्मानशूलारोचकोदावर्तपरिकर्तिकादिषु हित इति", text: "sukhatvādeva ca bastirbālavṛddhakṛśasthūlakṣīṇadhātvindriyeṣu ca strīṣu cānilopasargādaprajāsu kṛcchraprajāsucopadiśyate tathāgnibalavarṇamedhāsvarāyuḥsukhaprado vayaḥsthāpanaḥ paṅgūrustambhabhagnasaṅkucitānilādhmānaśūlārocakodāvartaparikartikādiṣu hita iti" },
      { type: "verse", number: "6", sanskrit: "स तु बस्तिस्त्रिविधः आस्थापनमनुवासनमुत्तरबस्तिश्च तत्रास्थापनं दोषदूष्याद्यनुसारेण नानाद्रव्यसंयोगादिनिर्वृत्तम् तस्य भेदाः उत्क्लेशनं संशोधनं संशमनं लेखनं बृंहणं वाजीकरणं पिच्छाबस्तिर्माधुतैलिकमित्यादयः माधुतैलिकस्य पर्यायाः यापनो युक्तरथो दोषहरः स्निग्धबसतिरिति तेषां नामभिरेव स्वरूपमाख्यातम्", text: "sa tu bastistrividhaḥ āsthāpanamanuvāsanamuttarabastiśca tatrāsthāpanaṃ doṣadūṣyādyanusāreṇa nānādravyasaṃyogādinirvṛttam tasya bhedāḥ utkleśanaṃ saṃśodhanaṃ saṃśamanaṃ lekhanaṃ bṛṃhaṇaṃ vājīkaraṇaṃ picchābastirmādhutailikamityādayaḥ mādhutailikasya paryāyāḥ yāpano yuktaratho doṣaharaḥ snigdhabasatiriti teṣāṃ nāmabhireva svarūpamākhyātam" },
      { type: "verse", number: "7", sanskrit: "तद्वयःस्थापनाद्दोषस्थापनाद्वास्थापनमित्युच्यते शरीरारोहणाद्दोषनिर्हरणादचिन्त्यप्रभावतया यस्मिन्नूहासम्भवान्निरूह इति", text: "tadvayaḥsthāpanāddoṣasthāpanādvāsthāpanamityucyate śarīrārohaṇāddoṣanirharaṇādacintyaprabhāvatayā yasminnūhāsambhavānnirūha iti" },
      { type: "verse", number: "8", sanskrit: "अनुवासनं यथार्हौषधसिद्धः स्नेहनार्थः स्नेहः स्नेहविधौ स चतुर्धाभिहितः तस्य भेदो मात्राबस्तिः स पेयस्नेहह्रस्वमात्रातुल्यः", text: "anuvāsanaṃ yathārhauṣadhasiddhaḥ snehanārthaḥ snehaḥ snehavidhau sa caturdhābhihitaḥ tasya bhedo mātrābastiḥ sa peyasnehahrasvamātrātulyaḥ" },
      { type: "verse", number: "9", sanskrit: "सेव्यः सदा च माधुतैलिकवत् बालवृद्धाध्वभारयानव्यायामचिन्तास्त्रीनित्यस्त्रीनृपेश्वरसुकुमारदुर्बलानिलभग्नाल्पाग्निभिर्निष्परिहारतया सुखो बल्यो वर्ण्यः सृष्टमलो दोषघ्नश्च तथापि तौ नाजीर्णे योज्यौ न च दिवास्वप्नः सेव्यः यतश्च सो ऽन्नमनुवसन्नपि न दुष्यत्यनुवासरमपि वा दीयत इत्यनुवासनम्", text: "sevyaḥ sadā ca mādhutailikavat bālavṛddhādhvabhārayānavyāyāmacintāstrīnityastrīnṛpeśvarasukumāradurbalānilabhagnālpāgnibhirniṣparihāratayā sukho balyo varṇyaḥ sṛṣṭamalo doṣaghnaśca tathāpi tau nājīrṇe yojyau na ca divāsvapnaḥ sevyaḥ yataśca so 'nnamanuvasannapi na duṣyatyanuvāsaramapi vā dīyata ityanuvāsanam" },
      { type: "verse", number: "10", sanskrit: "उत्तरबस्तिरपि स्नेहोनुवासनवच्छोधनं निरूहवदपि केचिदाहुः स निरूहादुत्तरमुत्तरेण वा मार्गेण दीयत इत्युत्तरबस्तिः", text: "uttarabastirapi snehonuvāsanavacchodhanaṃ nirūhavadapi kecidāhuḥ sa nirūhāduttaramuttareṇa vā mārgeṇa dīyata ityuttarabastiḥ" },
      { type: "verse", number: "11", sanskrit: "तत्रास्थाप्या गुल्मप्लीहानाहशूलशुद्धातीसारजीर्णज्वरप्रतिश्यायाढ्यरोगहृदयकुक्षिपार्श्वग्रहपर्वाभितापपार्श्वयोनिशूलाङ्गसुप्तिशोषकम्पगौरवातिलाघवान्त्रकूजनवातवर्चोमूत्रशुक्रसङ्गाश्मरीशर्करावृद्धिशुक्रार्तवस्तन्यनाशरजःक्षयोन्मादरेतोदोषक्रिमिणकोष्ठविषमाग्निसशब्दाल्पाल्पोग्रगन्धोत्थानादयो दोषभेदीयोक्ताश्च वातव्याधयो विशेषेणैते हि परं बस्तिना नाशमुपयान्ति मूलच्छेदेन वृक्षवत्", text: "tatrāsthāpyā gulmaplīhānāhaśūlaśuddhātīsārajīrṇajvarapratiśyāyāḍhyarogahṛdayakukṣipārśvagrahaparvābhitāpapārśvayoniśūlāṅgasuptiśoṣakampagauravātilāghavāntrakūjanavātavarcomūtraśukrasaṅgāśmarīśarkarāvṛddhiśukrārtavastanyanāśarajaḥkṣayonmādaretodoṣakrimiṇakoṣṭhaviṣamāgnisaśabdālpālpogragandhotthānādayo doṣabhedīyoktāśca vātavyādhayo viśeṣeṇaite hi paraṃ bastinā nāśamupayānti mūlacchedena vṛkṣavat" },
      { type: "verse", number: "12", sanskrit: "अनास्थाप्यास्त्वतिस्निग्धोत्क्लिष्टदोषक्षतोरस्कातिकृशा निरन्नाः कृतवमनविरेचननस्यप्रसक्तच्छर्दिनिष्ठीविकाकासश्वासहिक्कार्शोबद्धच्छिद्रदकादेराध्मानालसकविषूचिकामातीसारारोचकाल्पाग्निगुदशोफकुष्ठमधुमेहार्ताः गर्भिणी चाप्रवृत्ताष्टममासा तत्रातिस्निग्धोत्क्लिष्टदोषयोर्दोषानुक्लेश्योदरं मूर्च्छां श्वयथुं वा निरूहो जनयेत् क्षतोरस्कस्यातिकृशस्य च क्षोभमापन्नः शरीरमाशु पीडयेत् अनिरन्नस्य वक्ष्यते कृतवमनविरेकयोस्तु रिक्तं देहं क्षतं क्षार इव दहेत् स्नेहबस्तिस्तु सद्यो ऽग्निमवसाद्य श्लेष्मामयाय स्यात्", text: "anāsthāpyāstvatisnigdhotkliṣṭadoṣakṣatoraskātikṛśā nirannāḥ kṛtavamanavirecananasyaprasaktacchardiniṣṭhīvikākāsaśvāsahikkārśobaddhacchidradakāderādhmānālasakaviṣūcikāmātīsārārocakālpāgnigudaśophakuṣṭhamadhumehārtāḥ garbhiṇī cāpravṛttāṣṭamamāsā tatrātisnigdhotkliṣṭadoṣayordoṣānukleśyodaraṃ mūrcchāṃ śvayathuṃ vā nirūho janayet kṣatoraskasyātikṛśasya ca kṣobhamāpannaḥ śarīramāśu pīḍayet anirannasya vakṣyate kṛtavamanavirekayostu riktaṃ dehaṃ kṣataṃ kṣāra iva dahet snehabastistu sadyo 'gnimavasādya śleṣmāmayāya syāt" },
      { type: "verse", number: "13", sanskrit: "कृतनस्यस्याम्यविभ्रंशं विऋव्तोध्वस्रोतस्तया कुर्यात् अनुवासनं तु दोषोत्क्लेशम् प्रसक्तच्छर्द्यादीनां वायुर्निरूहमूर्ध्वं नयेत् अनुवासनं च अर्शसस्यावृतमार्गत्वादनागच्छन्बस्तिः प्राणान् हिंस्यात् स्नेहः पुनरर्शांस्यभिष्यन्द्याध्मानाय स्यात् बद्धोदराद्याध्मानान्तानां भृशतरमाध्मानान्मृत्युः अलसकार्तादीनां चामदोषात् अरोचकार्तादीनां यथास्वमामयवृद्धिः गर्भिण्याः पूर्वोक्तो दोषः", text: "kṛtanasyasyāmyavibhraṃśaṃ viṛvtodhvasrotastayā kuryāt anuvāsanaṃ tu doṣotkleśam prasaktacchardyādīnāṃ vāyurnirūhamūrdhvaṃ nayet anuvāsanaṃ ca arśasasyāvṛtamārgatvādanāgacchanbastiḥ prāṇān hiṃsyāt snehaḥ punararśāṃsyabhiṣyandyādhmānāya syāt baddhodarādyādhmānāntānāṃ bhṛśataramādhmānānmṛtyuḥ alasakārtādīnāṃ cāmadoṣāt arocakārtādīnāṃ yathāsvamāmayavṛddhiḥ garbhiṇyāḥ pūrvokto doṣaḥ" },
      { type: "verse", number: "14", sanskrit: "य एवास्थाप्यास्त एवानुवास्याः रूक्सातिदीप्ताग्रयः केवलानिलार्ताश्च विशेषेण एते परमनुवास नेनाप्याय्यन्ते मूलसेकेन वृक्षवत् य एवानास्थाप्यास्त एवाननुवास्याः तथा निरन्ननवज्वरपाण्डुरोगकामलाप्रमेहप्रतिश्यायप्लीहकफोदराढ्यवातवर्चोभेदार्तपीतविषगरपित्तकफाभिष्यन्दगुरुकोष्ठातिस्थूलश्लीपदगलगण्डापचीक्रिमिणकोष्ठाः तत्रातिस्निग्धादीनां यथास्वमुक्ताः पृथग्दोषाः अपि च", text: "ya evāsthāpyāsta evānuvāsyāḥ rūksātidīptāgrayaḥ kevalānilārtāśca viśeṣeṇa ete paramanuvāsa nenāpyāyyante mūlasekena vṛkṣavat ya evānāsthāpyāsta evānanuvāsyāḥ tathā nirannanavajvarapāṇḍurogakāmalāpramehapratiśyāyaplīhakaphodarāḍhyavātavarcobhedārtapītaviṣagarapittakaphābhiṣyandagurukoṣṭhātisthūlaślīpadagalagaṇḍāpacīkrimiṇakoṣṭhāḥ tatrātisnigdhādīnāṃ yathāsvamuktāḥ pṛthagdoṣāḥ api ca" },
      { type: "verse", number: "15", sanskrit: "अभुक्ते रिक्तकोष्ठस्य प्रयुक्तमनुवासनम् सरदूरगसूक्ष्मत्वैः क्षिप्रमूर्ध्वं प्रपद्यते", text: "abhukte riktakoṣṭhasya prayuktamanuvāsanam saradūragasūkṣmatvaiḥ kṣipramūrdhvaṃ prapadyate" },
      { type: "verse", number: "16", sanskrit: "तेन वायोर्जयो न स्याद्वातस्थाने ह्यतिष्ठता कायाग्नेराशु नाशश्च विशेषादनिवर्तनात्", text: "tena vāyorjayo na syādvātasthāne hyatiṣṭhatā kāyāgnerāśu nāśaśca viśeṣādanivartanāt" },
      { type: "verse", number: "17", sanskrit: "स्नेहःसद्योशिताहाररुद्धे त्वामाशये ऽनिलम् पक्वस्थं हन्ति पक्वस्थश्च्यवते चान्नपाकतः", text: "snehaḥsadyośitāhāraruddhe tvāmāśaye 'nilam pakvasthaṃ hanti pakvasthaścyavate cānnapākataḥ" },
      { type: "verse", number: "18", sanskrit: "निरूहश्च समीरश्च तीक्ष्णवेगावुभावपि तावन्नमूर्च्छितौ तीक्ष्णावधो ऽन्नेन सहागतौ", text: "nirūhaśca samīraśca tīkṣṇavegāvubhāvapi tāvannamūrcchitau tīkṣṇāvadho 'nnena sahāgatau" },
      { type: "verse", number: "19", sanskrit: "ऊर्ध्वं वा शकृता सार्द्धं संस्थितौ कोष्ठ एव वा समलाहारविष्टब्धौ हरेतामाशु जीवितम्", text: "ūrdhvaṃ vā śakṛtā sārddhaṃ saṃsthitau koṣṭha eva vā samalāhāraviṣṭabdhau haretāmāśu jīvitam" },
      { type: "verse", number: "20", sanskrit: "भुक्तवाननुवास्यो ऽस्मान्न निरूह्यस्तु भुक्तवान् पाण्डुरोगार्तादीनां दोषानुत्क्लेश्य स्नेहबस्तिरुदरं जनयेत् प्रैश्यायादिमतां भूय एव दोषं वर्धयेत्", text: "bhuktavānanuvāsyo 'smānna nirūhyastu bhuktavān pāṇḍurogārtādīnāṃ doṣānutkleśya snehabastirudaraṃ janayet praiśyāyādimatāṃ bhūya eva doṣaṃ vardhayet" },
      { type: "verse", number: "21", sanskrit: "तयोस्तु नेत्रं सुवर्णादिधातुमणिशङ्खशृङ्गदन्तास्थिवेणुनलखदिरकदरतिनिशतिन्दुकादिदारुसारमयमृज्वककशं गोपुच्छाकृतिगुलिकामुखमूनवर्षवार्षिकसप्तद्वादशषोडशवर्षाणां विंशतिप्रभृतिषु च क्रमात् पञ्चषट्सप्ताष्टनवद्वादशाङ्गुलप्रमाणम् मूले ऽग्रे चातुराङ्गुष्ठकनिष्ठिकापरिणाहमर्धाग्गुलात् प्रभृत्यर्धाङ्गुलप्रवृद्धत्र्यङ्गुलपर्यन्तप्रवेशमूलच्छिद्रम् वनमुद्गमुद्गमाषकलायक्लिन्नकलायर्ककन्धुवाह्यग्रच्छिद्रम् मूलछिद्रप्रमाणाङ्गुलैरग्रे यथास्वं सन्निविष्टकर्णिकं कर्णिकान्तःप्रतिबद्धसूत्रान्तर्गृहीताग्रपिधानघनचैलवर्ति मूले द्व्यङ्गुलान्तराले कर्णिकाद्वयं कारयेत् वर्षान्तरेषु च वयोबलशरीराण्यवेक्ष्य नेत्रप्रमाणमुत्कर्षयेत्", text: "tayostu netraṃ suvarṇādidhātumaṇiśaṅkhaśṛṅgadantāsthiveṇunalakhadirakadaratiniśatindukādidārusāramayamṛjvakakaśaṃ gopucchākṛtigulikāmukhamūnavarṣavārṣikasaptadvādaśaṣoḍaśavarṣāṇāṃ viṃśatiprabhṛtiṣu ca kramāt pañcaṣaṭsaptāṣṭanavadvādaśāṅgulapramāṇam mūle 'gre cāturāṅguṣṭhakaniṣṭhikāpariṇāhamardhāggulāt prabhṛtyardhāṅgulapravṛddhatryaṅgulaparyantapraveśamūlacchidram vanamudgamudgamāṣakalāyaklinnakalāyarkakandhuvāhyagracchidram mūlachidrapramāṇāṅgulairagre yathāsvaṃ sanniviṣṭakarṇikaṃ karṇikāntaḥpratibaddhasūtrāntargṛhītāgrapidhānaghanacailavarti mūle dvyaṅgulāntarāle karṇikādvayaṃ kārayet varṣāntareṣu ca vayobalaśarīrāṇyavekṣya netrapramāṇamutkarṣayet" },
      { type: "verse", number: "22", sanskrit: "ततोजाविवराहहरिणगोमहिषान्यतमजं स्नेहमुद्गविमृदितं विगतच्छिद्रसिराग्रन्थिस्कन्धं नातिवर्तुलं मृदु दृढं कषायरक्तं सुखसंस्थाप्यौषधप्रमाण न्युब्जं विवृताननं निवेश्य बस्तिं कर्णकयोर्दृढेन सूत्रेण घनं समं च बध्वा परिवर्त्त्य पुनश्चान्यद्वस्तिमुखबन्धनार्थं सूत्रमुपधायानुगुप्तं निधापयेत्", text: "tatojāvivarāhahariṇagomahiṣānyatamajaṃ snehamudgavimṛditaṃ vigatacchidrasirāgranthiskandhaṃ nātivartulaṃ mṛdu dṛḍhaṃ kaṣāyaraktaṃ sukhasaṃsthāpyauṣadhapramāṇa nyubjaṃ vivṛtānanaṃ niveśya bastiṃ karṇakayordṛḍhena sūtreṇa ghanaṃ samaṃ ca badhvā parivarttya punaścānyadvastimukhabandhanārthaṃ sūtramupadhāyānuguptaṃ nidhāpayet" },
      { type: "verse", number: "23", sanskrit: "बस्त्यभावे प्लवनीच्छागलाङ्कपादमधूच्छिष्टोपदिग्धघनसूक्ष्मतान्तवान्यतमं निवेशयेत्", text: "bastyabhāve plavanīcchāgalāṅkapādamadhūcchiṣṭopadigdhaghanasūkṣmatāntavānyatamaṃ niveśayet" },
      { type: "verse", number: "24", sanskrit: "आस्थापनमात्रा तु प्रथमे वर्षे प्रकुञ्चः ततः परं प्रतिवर्षं प्रकुञ्चमभिवर्धयेदाषट्प्रसृतात् ततश्चोर्ध्वं प्रसृताभिवृद्धिः प्राप्तानतीताष्टादशसप्ततेस्तु द्वादश प्रसृताः परं चातो दशैव अन्ये पुनर्द्वादशप्रसृतस्याप्यष्टाविच्छन्ति", text: "āsthāpanamātrā tu prathame varṣe prakuñcaḥ tataḥ paraṃ prativarṣaṃ prakuñcamabhivardhayedāṣaṭprasṛtāt tataścordhvaṃ prasṛtābhivṛddhiḥ prāptānatītāṣṭādaśasaptatestu dvādaśa prasṛtāḥ paraṃ cāto daśaiva anye punardvādaśaprasṛtasyāpyaṣṭāvicchanti" },
      { type: "verse", number: "25", sanskrit: "यथास्वमास्थापनमात्रा पादहीना माधुतैलिके प्रयोज्या अनुवासने स्वेवमेवास्थापनस्य पाद इति", text: "yathāsvamāsthāpanamātrā pādahīnā mādhutailike prayojyā anuvāsane svevamevāsthāpanasya pāda iti" },
      { type: "verse", number: "26", sanskrit: "अथास्थापनीयमातुरं स्नेहस्वेदोपपन्नं कृतवमनविरेकमासेवितपेयादिसंसर्गक्रममुपजातबलमनुवासनार्हं पूर्वमेवानुवासयेत् शीतवसन्तयोर्दिवा अन्यथा रात्राववेक्ष्य वा दोषादीन् अन्यथा हि स्हेहोक्तामयप्रादुर्भावः", text: "athāsthāpanīyamāturaṃ snehasvedopapannaṃ kṛtavamanavirekamāsevitapeyādisaṃsargakramamupajātabalamanuvāsanārhaṃ pūrvamevānuvāsayet śītavasantayordivā anyathā rātrāvavekṣya vā doṣādīn anyathā hi shehoktāmayaprādurbhāvaḥ" },
      { type: "verse", number: "27", sanskrit: "धन्वन्तरीयाः पुनराहः न रात्रौ प्रणयेद्बस्तिं स्नेहोत्क्लेशो हि रात्रिजः अह्नि स्थानस्थिते दोषे वह्नौचन्नरसान्विते", text: "dhanvantarīyāḥ punarāhaḥ na rātrau praṇayedbastiṃ snehotkleśo hi rātrijaḥ ahni sthānasthite doṣe vahnaucannarasānvite" },
      { type: "verse", number: "28", sanskrit: "स्फुटस्रोतोमुखं देहं स्नेहो यत् परिसर्पति अल्पपित्तकफं रूक्षं भृशं वातरुजार्दितम्", text: "sphuṭasrotomukhaṃ dehaṃ sneho yat parisarpati alpapittakaphaṃ rūkṣaṃ bhṛśaṃ vātarujārditam" },
      { type: "verse", number: "29", sanskrit: "भुक्तं जीर्णाशनं कामं रात्रावप्यनुवासयेत् केवलानिलनिपीडितं त्वशुद्धमप्यनिरूपितबलं चाप्यनुवासयेदात्ययिकत्वात् व्याधेः तस्य विधिर्वमनादधिकतरं कृतमङ्गलमनुसुखमभ्यक्तमुष्णाम्बुस्नातं युक्तस्नेहमुचितात् पादहीनं द्रवपूर्वं लघूष्णं सानुपानमशनमशितवन्तं कृतचङ्क्रमणमुत्सृष्टविण्मूत्रमशनार्द्रहस्तमशङ्कनीयपरिचारकं निवाते वेश्मनि प्रतत शयने नात्युच्छ्रिते स्वास्तृते ईषदुन्नमितपाददेशे वामपाश्वन प्राक्शिरसं संवेशयेत् अतिस्निग्धाशिनो ह्युभयमार्गसंसर्गात् स्नेहो मदमूर्च्छाग्निसादहृल्लासान् जनयति रूक्षाशिनो विष्टम्भं बलवर्णहानिं वा अल्पमात्रद्रवाशिनो विसृष्टविण्मूत्रस्य चानावृतेन तदावृतात् व्यापदम् चिरमशितवतो विदाहाभिमुखभक्तस्य ज्वरं कुर्यात् यतश्च वामपार्श्वाश्रयाणि वह्निग्रहणीगुदवलामुखानि तानि तत्पार्श्वशायिनो निम्नानि भवन्त्यतस्तदौषधमस्खलितमाप्नोति प्रवेशनिर्गमाविति संविष्टं चैनमृजुस्थितदेहं स्वबाहूपधानं प्रसारितवामसक्थिमाकुञ्चितेतरं तस्यैव चोपरिप्रसारितदाक्षणबाहुं कारयेत्", text: "bhuktaṃ jīrṇāśanaṃ kāmaṃ rātrāvapyanuvāsayet kevalānilanipīḍitaṃ tvaśuddhamapyanirūpitabalaṃ cāpyanuvāsayedātyayikatvāt vyādheḥ tasya vidhirvamanādadhikataraṃ kṛtamaṅgalamanusukhamabhyaktamuṣṇāmbusnātaṃ yuktasnehamucitāt pādahīnaṃ dravapūrvaṃ laghūṣṇaṃ sānupānamaśanamaśitavantaṃ kṛtacaṅkramaṇamutsṛṣṭaviṇmūtramaśanārdrahastamaśaṅkanīyaparicārakaṃ nivāte veśmani pratata śayane nātyucchrite svāstṛte īṣadunnamitapādadeśe vāmapāśvana prākśirasaṃ saṃveśayet atisnigdhāśino hyubhayamārgasaṃsargāt sneho madamūrcchāgnisādahṛllāsān janayati rūkṣāśino viṣṭambhaṃ balavarṇahāniṃ vā alpamātradravāśino visṛṣṭaviṇmūtrasya cānāvṛtena tadāvṛtāt vyāpadam ciramaśitavato vidāhābhimukhabhaktasya jvaraṃ kuryāt yataśca vāmapārśvāśrayāṇi vahnigrahaṇīgudavalāmukhāni tāni tatpārśvaśāyino nimnāni bhavantyatastadauṣadhamaskhalitamāpnoti praveśanirgamāviti saṃviṣṭaṃ cainamṛjusthitadehaṃ svabāhūpadhānaṃ prasāritavāmasakthimākuñcitetaraṃ tasyaiva copariprasāritadākṣaṇabāhuṃ kārayet" },
      { type: "verse", number: "30", sanskrit: "पूर्वमेव तु वैद्यो वर्त्त्या सुपिहिताग्रच्छिद्रं नेत्रं भाजनस्योपरि कृत्वा दक्षिणपादाङ्गुष्ठाङ्गुलीभ्यां कर्णिकाया उपरिष्टान्निष्पीड्याविबन्धाय शताह्वासैन्धवचूर्णावचूर्णितं प्रगेव नेत्रस्पर्शात् पूर्ववदाभिमन्त्रितं यथार्हं यथार्हौषधाविपक्व सुखोष्णं बस्तौ स्नेहमासिच्यावलीकोच्छ्वासं निस्सारितवातबुद्बुदमौषधान्ते सूत्रेण द्विस्त्रिर्वा बस्तिमुखमावेष्ट्य दक्षिणपाणौ नेत्रमुपरिधाय तिष्ठेत् ततो घृताभ्यक्ते पायौ वामहस्तप्रदेशिन्याभ्यक्तप्रवेशप्रदेशमपनीतवर्त्युत्तानवामहस्ताङ्गुष्ठोदरपिहिताग्रं मध्यमाप्रदेशिन्युपगृहीतकर्णिकमृज्वनुपृष्ठवंशमनुसुखमेकमना लाघवेन निष्कम्पमद्रुतमविलम्बितं नेत्रमाकर्णिकं प्रवेशयेत् आतुरो ऽपि तदनुलोमयन्नवलम्बेत ततश्च वैद्यो बस्तिमुखं दक्षिणहस्ताङ्गुष्ठप्रदोशिनीभ्याममुञ्चन्नेत्रमचालयन् हस्तद्वयेनोत्तानेनैकग्रहणेनैवानिलाधिष्ठानभूतं किञ्चिदवशेषयन् शनैश्शनैरवेगमनुपीडयेत् अन्यथा हि व्यापदो भवन्ति ताः ससाधनाः सिद्धिषु वक्ष्यन्ते", text: "pūrvameva tu vaidyo varttyā supihitāgracchidraṃ netraṃ bhājanasyopari kṛtvā dakṣiṇapādāṅguṣṭhāṅgulībhyāṃ karṇikāyā upariṣṭānniṣpīḍyāvibandhāya śatāhvāsaindhavacūrṇāvacūrṇitaṃ prageva netrasparśāt pūrvavadābhimantritaṃ yathārhaṃ yathārhauṣadhāvipakva sukhoṣṇaṃ bastau snehamāsicyāvalīkocchvāsaṃ nissāritavātabudbudamauṣadhānte sūtreṇa dvistrirvā bastimukhamāveṣṭya dakṣiṇapāṇau netramuparidhāya tiṣṭhet tato ghṛtābhyakte pāyau vāmahastapradeśinyābhyaktapraveśapradeśamapanītavartyuttānavāmahastāṅguṣṭhodarapihitāgraṃ madhyamāpradeśinyupagṛhītakarṇikamṛjvanupṛṣṭhavaṃśamanusukhamekamanā lāghavena niṣkampamadrutamavilambitaṃ netramākarṇikaṃ praveśayet āturo 'pi tadanulomayannavalambeta tataśca vaidyo bastimukhaṃ dakṣiṇahastāṅguṣṭhapradośinībhyāmamuñcannetramacālayan hastadvayenottānenaikagrahaṇenaivānilādhiṣṭhānabhūtaṃ kiñcidavaśeṣayan śanaiśśanairavegamanupīḍayet anyathā hi vyāpado bhavanti tāḥ sasādhanāḥ siddhiṣu vakṣyante" },
      { type: "verse", number: "31", sanskrit: "अन्ये तु त्रिंशन्मात्राः पीडनकालमाहुः न च बस्तौ दीयमाने क्षवकासहासजृम्भास्पन्दनान्याचरेत् विण्मूत्रानिलवेगे तु नेत्रमाकृष्य वेगान्ते शेषं प्रणयेत् अन्ते चोत्तानस्य स्थिजौ पाणितलेन त्रिचतुरो वारांस्ताडयेत् तथा तत्पार्ष्णिभ्याम् पादतश्च शय्यां त्रिरुत्क्षिपेत् सोपधानस्य च प्रसारितसर्वाङ्गस्य पार्ष्णिके मुष्टिना हन्यात् तथा पार्ष्ण्यङ्गुलिपादतलपिण्डिकाः सरुजं चाङ्गं स्नेहेन प्रतिलोमं वाक्शतमात्रं शनैर्विमृद्नीयात् एवमाशु स्नेहो न निवर्तते समनुगच्छति चासमन्तात्सिराः ततः परं तु स्नेहोक्तमाचार्मनुवर्तते", text: "anye tu triṃśanmātrāḥ pīḍanakālamāhuḥ na ca bastau dīyamāne kṣavakāsahāsajṛmbhāspandanānyācaret viṇmūtrānilavege tu netramākṛṣya vegānte śeṣaṃ praṇayet ante cottānasya sthijau pāṇitalena tricaturo vārāṃstāḍayet tathā tatpārṣṇibhyām pādataśca śayyāṃ trirutkṣipet sopadhānasya ca prasāritasarvāṅgasya pārṣṇike muṣṭinā hanyāt tathā pārṣṇyaṅgulipādatalapiṇḍikāḥ sarujaṃ cāṅgaṃ snehena pratilomaṃ vākśatamātraṃ śanairvimṛdnīyāt evamāśu sneho na nivartate samanugacchati cāsamantātsirāḥ tataḥ paraṃ tu snehoktamācārmanuvartate" },
      { type: "verse", number: "32", sanskrit: "दीप्तानिं च सायं लघ्वन्नं भोजयेत् नैव चानागतस्नेहं द्वितीये ऽहनि न च तमनुवासयेत् आगमनकालस्तु परो यामत्रयम् ततः परमनागच्छन्तमहोरात्रमुपेक्षेत तदाप्यनिवर्तमाने फलवर्तिभिर्लवणारनालप्रायैर्वा तीक्ष्णबस्तिभिः शोधयेत् स्नेहव्यापत्सिद्धिं चावेक्षेत अतिरौक्ष्यादनागच्छन्नचेज्जाड्याद्युपद्रवाय् स्यात् तथाप्युपेक्ष्यः शीघ्रनिवृत्ते तु विना मलेन केवले स्नेह स्नेहमन्यं पुनर्योजयेत् न ह्यसावतिष्ठन् कार्यकरो भवति सुखोषितं चैनं तथाकृतवमनविरेकास्थापनान्यतमं प्रायः शुण्ठीधान्यक्वाथमितरच्चोष्णोदकं वा स्नेहशेषजरणाय वातकफोपशान्तये च पाययेत्", text: "dīptāniṃ ca sāyaṃ laghvannaṃ bhojayet naiva cānāgatasnehaṃ dvitīye 'hani na ca tamanuvāsayet āgamanakālastu paro yāmatrayam tataḥ paramanāgacchantamahorātramupekṣeta tadāpyanivartamāne phalavartibhirlavaṇāranālaprāyairvā tīkṣṇabastibhiḥ śodhayet snehavyāpatsiddhiṃ cāvekṣeta atiraukṣyādanāgacchannacejjāḍyādyupadravāy syāt tathāpyupekṣyaḥ śīghranivṛtte tu vinā malena kevale sneha snehamanyaṃ punaryojayet na hyasāvatiṣṭhan kāryakaro bhavati sukhoṣitaṃ cainaṃ tathākṛtavamanavirekāsthāpanānyatamaṃ prāyaḥ śuṇṭhīdhānyakvāthamitaraccoṣṇodakaṃ vā snehaśeṣajaraṇāya vātakaphopaśāntaye ca pāyayet" },
      { type: "verse", number: "33", sanskrit: "ततो ऽन्नकाले यथोक्तमन्नमश्नीयात् न चानुवासितं पेयां पाययेत् सा हि सस्नेहकोष्ठमेनमभिष्यन्दयति पुनश्च तृतीये ऽहन्यनुवासयेत् पञ्चमे वा यदा वा स्नेहपक्तिः स्यादतश्च दाप्ताग्निरूक्षवातोल्बणव्यायामनित्यान् प्रत्यहम् एवममुना क्रमेण दोषाद्यनुसारतस्त्रिचतुरैः स्नेहबस्तिभिरुपस्निग्धं शोधनेनास्थापनेन स्रोतोविशुद्ध्यर्थमास्थापयेत् वाताधिक्यादस्निग्धं तु स्नेहनेन", text: "tato 'nnakāle yathoktamannamaśnīyāt na cānuvāsitaṃ peyāṃ pāyayet sā hi sasnehakoṣṭhamenamabhiṣyandayati punaśca tṛtīye 'hanyanuvāsayet pañcame vā yadā vā snehapaktiḥ syādataśca dāptāgnirūkṣavātolbaṇavyāyāmanityān pratyaham evamamunā krameṇa doṣādyanusāratastricaturaiḥ snehabastibhirupasnigdhaṃ śodhanenāsthāpanena srotoviśuddhyarthamāsthāpayet vātādhikyādasnigdhaṃ tu snehanena" },
      { type: "verse", number: "34", sanskrit: "अथैनं तृतीये पञ्चमे वाहनि किञ्चिदावृत्ते माध्याह्ने कृतमङ्गलस्वस्त्ययनमभ्यक्तदेहं स्वेदितमुत्सृष्टमलमनाशितं नातिक्षुधितमवेक्ष्यातुरमार्यावलोकितं नाथमार्यतारामात्मभुवं धातारमश्विनाविन्द्रमात्रेयं सप्तर्षीन् काशिराजं विदेहपतिप्रभृतीनग्निवेशादींश्च तन्त्रकारान् दीपगन्धफलबलिधूर्पैर्यज्ञ इव प्रकल्पितभागान् कृत्वौषधीवृद्धवैद्यद्विजातींश्च संपूज्य तद्विद्यसहितो दोषौषधादिबलेन यथार्हमुपकल्पयेद्वस्तिम्", text: "athainaṃ tṛtīye pañcame vāhani kiñcidāvṛtte mādhyāhne kṛtamaṅgalasvastyayanamabhyaktadehaṃ sveditamutsṛṣṭamalamanāśitaṃ nātikṣudhitamavekṣyāturamāryāvalokitaṃ nāthamāryatārāmātmabhuvaṃ dhātāramaśvināvindramātreyaṃ saptarṣīn kāśirājaṃ videhapatiprabhṛtīnagniveśādīṃśca tantrakārān dīpagandhaphalabalidhūrpairyajña iva prakalpitabhāgān kṛtvauṣadhīvṛddhavaidyadvijātīṃśca saṃpūjya tadvidyasahito doṣauṣadhādibalena yathārhamupakalpayedvastim" },
      { type: "verse", number: "35", sanskrit: "तत्र विंशतिमात्राणि पलान्यौषधानां मदनफलाष्टकं च क्वाथकल्पेन विपचेत् क्वाथाच्चतुर्थांशां स्नेहमनिले षष्ठांशं पित्ते स्वस्थवृत्ते चाष्टमांशं तु कफे सर्वस्य चाष्टमांशं कल्कस्य स्याद्यावता नात्यच्छसान्द्रता भेवेत् गुडस्य पलं युक्त्या मधुसैन्धवे यथायोग्यं च शेषाणि कल्पयेत्", text: "tatra viṃśatimātrāṇi palānyauṣadhānāṃ madanaphalāṣṭakaṃ ca kvāthakalpena vipacet kvāthāccaturthāṃśāṃ snehamanile ṣaṣṭhāṃśaṃ pitte svasthavṛtte cāṣṭamāṃśaṃ tu kaphe sarvasya cāṣṭamāṃśaṃ kalkasya syādyāvatā nātyacchasāndratā bhevet guḍasya palaṃ yuktyā madhusaindhave yathāyogyaṃ ca śeṣāṇi kalpayet" },
      { type: "verse", number: "36", sanskrit: "सर्वाणि चैकध्यमुष्णोदककुम्भीबाष्पाभितप्तानि खजमथितानि बस्तौ प्रक्षिप्यानुवासनवन्निरूहं प्रणयेत् नात्युष्णशीतं नातिमृदुतीक्ष्णं नातिस्निग्धरूक्षं नातितनुसान्द्रं न हीनातिमात्रं नालवणातिलवणं नात्यम्लं च तत्र बाष्पमात्रानुतापादौषधस्य विदाहो न भवति खजप्रमथनात्तु क्वाथस्नेहादयः सम्यक् सम्प्रयुक्ताः सम्यगेव योगमारभन्ते अन्यथा पुनः क्वाथादीनामुल्बणोन्यतमं यथास्वं दोषमीरयेत् अत्युष्णादीनां तु पृथग्व्यापदः साधनानि च सिद्धिषूत्तरकालमुपदेक्ष्यन्ते", text: "sarvāṇi caikadhyamuṣṇodakakumbhībāṣpābhitaptāni khajamathitāni bastau prakṣipyānuvāsanavannirūhaṃ praṇayet nātyuṣṇaśītaṃ nātimṛdutīkṣṇaṃ nātisnigdharūkṣaṃ nātitanusāndraṃ na hīnātimātraṃ nālavaṇātilavaṇaṃ nātyamlaṃ ca tatra bāṣpamātrānutāpādauṣadhasya vidāho na bhavati khajapramathanāttu kvāthasnehādayaḥ samyak samprayuktāḥ samyageva yogamārabhante anyathā punaḥ kvāthādīnāmulbaṇonyatamaṃ yathāsvaṃ doṣamīrayet atyuṣṇādīnāṃ tu pṛthagvyāpadaḥ sādhanāni ca siddhiṣūttarakālamupadekṣyante" },
      { type: "verse", number: "37", sanskrit: "अपि च तिर्यक्प्रणीते हि न याति धारा गुदे व्रणः स्याच्चलिते च नेत्रे दत्तः शनैर्नाशयमेति बस्तिः कण्ठं प्रधावेदतिपीडितस्तु", text: "api ca tiryakpraṇīte hi na yāti dhārā gude vraṇaḥ syāccalite ca netre dattaḥ śanairnāśayameti bastiḥ kaṇṭhaṃ pradhāvedatipīḍitastu" },
      { type: "verse", number: "38", sanskrit: "स्तम्भं विधत्ते ऽतिमृदुर्हिमश्च तप्ताम्लतीक्ष्णो भ्रमदाहमोहान् स्निग्धो ऽतिजाड्यं पवनं तु रूक्षस्तन्वल्पमात्रालवणस्त्वयोगम्", text: "stambhaṃ vidhatte 'timṛdurhimaśca taptāmlatīkṣṇo bhramadāhamohān snigdho 'tijāḍyaṃ pavanaṃ tu rūkṣastanvalpamātrālavaṇastvayogam" },
      { type: "verse", number: "39", sanskrit: "करोति मात्राभ्यधिको ऽतियोगं क्षोभ तु सान्द्रः सुचिरेण चैति दाहातिसारौ लवणो ऽति कुर्यात्तस्मात्सुयुक्तं सममेव दह्यात्", text: "karoti mātrābhyadhiko 'tiyogaṃ kṣobha tu sāndraḥ sucireṇa caiti dāhātisārau lavaṇo 'ti kuryāttasmātsuyuktaṃ samameva dahyāt" },
      { type: "verse", number: "40", sanskrit: "मात्रां त्रिपलिकां कुर्यात् स्नेहमाक्षिकयोः पृथक् कर्षार्धं माणिमन्थस्य स्वस्थे कल्कपलद्वयम्", text: "mātrāṃ tripalikāṃ kuryāt snehamākṣikayoḥ pṛthak karṣārdhaṃ māṇimanthasya svasthe kalkapaladvayam" },
      { type: "verse", number: "41", sanskrit: "सर्वद्रवाणां शेषाणां पलानि दश कल्पयेत् माक्षिकं लवणं स्नेहं कल्कं क्वाथमिति क्रमात्", text: "sarvadravāṇāṃ śeṣāṇāṃ palāni daśa kalpayet mākṣikaṃ lavaṇaṃ snehaṃ kalkaṃ kvāthamiti kramāt" },
      { type: "verse", number: "42", sanskrit: "आवपेत निरूहाणामेष संयोजने विधिः", text: "āvapeta nirūhāṇāmeṣa saṃyojane vidhiḥ" },
      { type: "verse", number: "43", sanskrit: "दत्तमात्रे तूत्तानः सोपधानो निरूहवीर्येण देहव्याप्तये तन्मनास्थिष्ठेत् उदीर्णवेगश्चोत्कुटिको विसृजेत् आगमनकालस्तु परो मुहूर्तः तदा ह्यनागच्छन्नाशु मृत्यवे स्यात् अतस्तत्रानुलोमिकं स्नेहक्षारमूत्राम्लं स्निग्धतीक्ष्णोष्णमन्यं प्रयोजयेत् फलवर्तिस्वेदभयोत्त्रासादींश्च बस्तिव्यापत्सिद्धिं चावेक्षेत", text: "dattamātre tūttānaḥ sopadhāno nirūhavīryeṇa dehavyāptaye tanmanāsthiṣṭhet udīrṇavegaścotkuṭiko visṛjet āgamanakālastu paro muhūrtaḥ tadā hyanāgacchannāśu mṛtyave syāt atastatrānulomikaṃ snehakṣāramūtrāmlaṃ snigdhatīkṣṇoṣṇamanyaṃ prayojayet phalavartisvedabhayottrāsādīṃśca bastivyāpatsiddhiṃ cāvekṣeta" },
      { type: "verse", number: "44", sanskrit: "स्वयं निवृत्ते तु पूर्ववद् द्वितीयं तृतीयं चतुर्थं च दद्याद्यावद्वा सुनिरूढः स्यात्", text: "svayaṃ nivṛtte tu pūrvavad dvitīyaṃ tṛtīyaṃ caturthaṃ ca dadyādyāvadvā sunirūḍhaḥ syāt" },
      { type: "verse", number: "45", sanskrit: "तत्राद्यो ऽनिलं स्वमार्गादपकर्षति द्वितीयः पित्तम् तृतीयः श्लेष्माणमिति", text: "tatrādyo 'nilaṃ svamārgādapakarṣati dvitīyaḥ pittam tṛtīyaḥ śleṣmāṇamiti" },
      { type: "verse", number: "46", sanskrit: "तस्य हीनसम्यगतियोगास्तु विरिक्तवत् सम्यङ्निरूढं तु कोष्णसलिलावसिक्तं तनुना जाङ्गलरसेन भोजयेत् स्नाताशितस्यास्य चला दोषशेषाः स्वस्थानमाश्रयन्ते", text: "tasya hīnasamyagatiyogāstu viriktavat samyaṅnirūḍhaṃ tu koṣṇasalilāvasiktaṃ tanunā jāṅgalarasena bhojayet snātāśitasyāsya calā doṣaśeṣāḥ svasthānamāśrayante" },
      { type: "verse", number: "47", sanskrit: "ततः पुनर्वातार्तमातुरं बृंहणीयमन्यं वा तद्विधमशितानन्तरं सायं वा पुनरल्पलघ्वशितं यथास्वमलिलादिषु दशमूलादिसाधितेन तैलेनानुवासयेत् तस्य हीनसम्यगतियोगाः स्नेहपीतवत्", text: "tataḥ punarvātārtamāturaṃ bṛṃhaṇīyamanyaṃ vā tadvidhamaśitānantaraṃ sāyaṃ vā punaralpalaghvaśitaṃ yathāsvamalilādiṣu daśamūlādisādhitena tailenānuvāsayet tasya hīnasamyagatiyogāḥ snehapītavat" },
      { type: "verse", number: "48", sanskrit: "विशेषस्तु सम्यगनुवासिते किञ्चित्कालं स्थित्वा स्नेहः सपुरीषोनिलानुगतः प्रवर्तत इति भवति चात्र", text: "viśeṣastu samyaganuvāsite kiñcitkālaṃ sthitvā snehaḥ sapurīṣonilānugataḥ pravartata iti bhavati cātra" },
      { type: "verse", number: "49", sanskrit: "एवं कफे स्नेहबस्तिमेकं त्रीन् वा प्रयोजयेत् प्ञ्च वा सप्त वा पित्ते नवैकादश वानिले", text: "evaṃ kaphe snehabastimekaṃ trīn vā prayojayet pñca vā sapta vā pitte navaikādaśa vānile" },
      { type: "verse", number: "50", sanskrit: "पुनस्ततोप्ययुग्मांस्तु पुनरास्थापनं ततः कफपित्तानिलेष्वन्नं यूषक्षीररसैः क्रमात्", text: "punastatopyayugmāṃstu punarāsthāpanaṃ tataḥ kaphapittānileṣvannaṃ yūṣakṣīrarasaiḥ kramāt" },
      { type: "verse", number: "51", sanskrit: "वातघ्नौषधनिष्क्वाथत्रिवृतासैन्धवैर्युतः बस्तिरेको ऽनिले स्निग्धः स्वाद्वम्लोष्णो रसान्वितः", text: "vātaghnauṣadhaniṣkvāthatrivṛtāsaindhavairyutaḥ bastireko 'nile snigdhaḥ svādvamloṣṇo rasānvitaḥ" },
      { type: "verse", number: "52", sanskrit: "ग्यग्रोधादिगणक्वाथपद्मकादिसितायुतौ पित्ते स्वादुहिमौ साज्यक्षीरेक्षुरसमाक्षिकौ", text: "gyagrodhādigaṇakvāthapadmakādisitāyutau pitte svāduhimau sājyakṣīrekṣurasamākṣikau" },
      { type: "verse", number: "53", sanskrit: "आरग्वधादिनिष्क्वाथवत्सकादियुतास्त्रयः रूक्षाः सक्षौद्रगोमूत्रास्तीक्ष्णोष्णकटुकाः कफे", text: "āragvadhādiniṣkvāthavatsakādiyutāstrayaḥ rūkṣāḥ sakṣaudragomūtrāstīkṣṇoṣṇakaṭukāḥ kaphe" },
      { type: "verse", number: "54", sanskrit: "त्रयश्च सन्निपाते ऽपि दोषान् घ्नन्ति यतः क्रमात् नाचार्यचरकस्यातो बस्तिस्त्रिभ्यः परं मतः न हि दोषश्चतुर्थो ऽस्ति पुनर्दीयेत यं प्रति", text: "trayaśca sannipāte 'pi doṣān ghnanti yataḥ kramāt nācāryacarakasyāto bastistribhyaḥ paraṃ mataḥ na hi doṣaścaturtho 'sti punardīyeta yaṃ prati" },
      { type: "verse", number: "55", sanskrit: "उत्क्लेशनं शुद्धिकरं दोषाणां शमनं क्रमात् त्रिधैव कल्पयेद्बस्तिमित्यन्ये ऽपि प्रचक्षते दोषौषधादिबलतः सर्वमेतत् प्रमाणयेत्", text: "utkleśanaṃ śuddhikaraṃ doṣāṇāṃ śamanaṃ kramāt tridhaiva kalpayedbastimityanye 'pi pracakṣate doṣauṣadhādibalataḥ sarvametat pramāṇayet" },
      { type: "verse", number: "56", sanskrit: "सम्यङ्निरूढलिङ्गं तु नासंभाव्य निवर्तयेत्", text: "samyaṅnirūḍhaliṅgaṃ tu nāsaṃbhāvya nivartayet" },
      { type: "verse", number: "57", sanskrit: "प्राक्स्नेह एकः पञ्चान्ते द्वादशास्थापनानि च सान्वासनानि कर्मैवं बस्तयस्त्रिंशदीरिताः", text: "prāksneha ekaḥ pañcānte dvādaśāsthāpanāni ca sānvāsanāni karmaivaṃ bastayastriṃśadīritāḥ" },
      { type: "verse", number: "58", sanskrit: "कालः पञ्चदशैकोत्र प्राक्स्नेहो ऽन्ते त्रयस्तथा", text: "kālaḥ pañcadaśaikotra prāksneho 'nte trayastathā" },
      { type: "verse", number: "59", sanskrit: "षट् पञ्च बस्त्यन्तारताः योगोष्टौ बस्तयो ऽत्र तु त्रयो निरूहाः स्नेहाश्च स्नेहावाद्यन्तयोरुमौ", text: "ṣaṭ pañca bastyantāratāḥ yogoṣṭau bastayo 'tra tu trayo nirūhāḥ snehāśca snehāvādyantayorumau" },
      { type: "verse", number: "60", sanskrit: "स्नेहबस्तिं निरूहं वा नैकमेवातिशीलयेत् उत्क्लेशाग्निवधौ स्नेहान्निरूहान्मरुतो भयम्", text: "snehabastiṃ nirūhaṃ vā naikamevātiśīlayet utkleśāgnivadhau snehānnirūhānmaruto bhayam" },
      { type: "verse", number: "61", sanskrit: "तस्मान्निरूढः स्नेह्यः स्यान्निरूह्यश्चानुवासितः स्नेहशोधनयुक्त्यैवं बस्तिकर्म त्रिदोषजित्", text: "tasmānnirūḍhaḥ snehyaḥ syānnirūhyaścānuvāsitaḥ snehaśodhanayuktyaivaṃ bastikarma tridoṣajit" },
      { type: "verse", number: "62", sanskrit: "अष्टादशाष्टादशकान् बस्तीनां यो निषेवते विधिना ना यथोक्तेन स भवेदजरो ऽरुजः", text: "aṣṭādaśāṣṭādaśakān bastīnāṃ yo niṣevate vidhinā nā yathoktena sa bhavedajaro 'rujaḥ" },
      { type: "verse", number: "63", sanskrit: "सहस्रायुः श्रुतधरो वीतपाप्मामरप्रभः वाजिस्यदो नागबलः स्थिरबुद्धीन्द्रियानलः", text: "sahasrāyuḥ śrutadharo vītapāpmāmaraprabhaḥ vājisyado nāgabalaḥ sthirabuddhīndriyānalaḥ" },
      { type: "verse", number: "64", sanskrit: "बस्तौ रोगेषु नारीणां योनिगर्भाशयेषु च द्वित्रास्थापनशुद्धेभ्यो विदध्याद्वस्तिमुत्तरम्", text: "bastau rogeṣu nārīṇāṃ yonigarbhāśayeṣu ca dvitrāsthāpanaśuddhebhyo vidadhyādvastimuttaram" },
      { type: "verse", number: "65", sanskrit: "आतुराङ्गुलमानेन तन्नेत्रं द्वादशाङ्गुलम् वृत्तं गोपुच्छवन्मूलमध्ययोः कृतकर्णिकम्", text: "āturāṅgulamānena tannetraṃ dvādaśāṅgulam vṛttaṃ gopucchavanmūlamadhyayoḥ kṛtakarṇikam" },
      { type: "verse", number: "66", sanskrit: "सिद्धार्थकर्पवेशाग्रं श्लक्ष्णं हेमादिसम्भवम् कुन्दाश्वमारसुमनःपुष्पवृन्तोपमं दृढम्", text: "siddhārthakarpaveśāgraṃ ślakṣṇaṃ hemādisambhavam kundāśvamārasumanaḥpuṣpavṛntopamaṃ dṛḍham" },
      { type: "verse", number: "67", sanskrit: "तस्य बस्तिर्मृदुलघुर्मात्रा शुक्तिर्विकल्प्य वा", text: "tasya bastirmṛdulaghurmātrā śuktirvikalpya vā" },
      { type: "verse", number: "68", sanskrit: "अथ स्नाताशितस्यास्य स्नेहब्स्तिविधानतः ऋजोः सुखोपविष्टस्य पीठे जानुसमे मृदौ", text: "atha snātāśitasyāsya snehabstividhānataḥ ṛjoḥ sukhopaviṣṭasya pīṭhe jānusame mṛdau" },
      { type: "verse", number: "69", sanskrit: "हृष्टे मेढ्रे स्थिते चर्ज्जु शनैः स्रोतोविशुद्धये मालतीपुष्पवृन्ताग्रपरिणाहां घनामृजुम्", text: "hṛṣṭe meḍhre sthite carjju śanaiḥ srotoviśuddhaye mālatīpuṣpavṛntāgrapariṇāhāṃ ghanāmṛjum" },
      { type: "verse", number: "70", sanskrit: "श्लक्ष्णां शलाकां प्रणयेत्तया शुद्धे ऽनुसीवनीम् आमेहनान्तं नेत्रं च निष्कम्पं गुदवत्ततः", text: "ślakṣṇāṃ śalākāṃ praṇayettayā śuddhe 'nusīvanīm āmehanāntaṃ netraṃ ca niṣkampaṃ gudavattataḥ" },
      { type: "verse", number: "71", sanskrit: "पीडिते ऽनुगते स्नेहे स्नेहबस्तिक्रमो हितः बस्तीननेन विधिना दद्यात् त्रींश्चतुरो ऽपि वा", text: "pīḍite 'nugate snehe snehabastikramo hitaḥ bastīnanena vidhinā dadyāt trīṃścaturo 'pi vā" },
      { type: "verse", number: "72", sanskrit: "अनुवासनवच्छेषं सर्वमेवास्य चिन्तयेत्", text: "anuvāsanavaccheṣaṃ sarvamevāsya cintayet" },
      { type: "verse", number: "73", sanskrit: "स्त्रीणामार्तवकाले तु योनिर्गृह्णात्यपावृतेः विदधीत तदा तस्मादनृतावपि चात्यये", text: "strīṇāmārtavakāle tu yonirgṛhṇātyapāvṛteḥ vidadhīta tadā tasmādanṛtāvapi cātyaye" },
      { type: "verse", number: "74", sanskrit: "योनिविभ्रंशशूलेषु योनिव्यापद्यसृग्दरे", text: "yonivibhraṃśaśūleṣu yonivyāpadyasṛgdare" },
      { type: "verse", number: "75", sanskrit: "नेत्रं दशाङ्गुलं मुद्गप्रवेशं चतुरङ्गुलम् अपत्यमार्गे योज्यं स्याद्द्व्यङ्गुलं मूत्रवर्त्मनि", text: "netraṃ daśāṅgulaṃ mudgapraveśaṃ caturaṅgulam apatyamārge yojyaṃ syāddvyaṅgulaṃ mūtravartmani" },
      { type: "verse", number: "76", sanskrit: "मूत्रकृच्छ्रविकारेषु बालानां शुक्तिरेव तु", text: "mūtrakṛcchravikāreṣu bālānāṃ śuktireva tu" },
      { type: "verse", number: "77", sanskrit: "उत्तानायाः शयानायाः सम्यक् सङ्कोच्य सक्थिनी ऊर्ध्वजान्वास्त्रिचतुरानहोरात्रेण योजयेत्", text: "uttānāyāḥ śayānāyāḥ samyak saṅkocya sakthinī ūrdhvajānvāstricaturānahorātreṇa yojayet" },
      { type: "verse", number: "78", sanskrit: "बस्तींस्त्रिरामत्रेवं तु स्नेहमात्रां विवर्धयेत् त्र्यहमेवं च विश्रम्य प्रणिदध्यात् पुनस्त्र्यहम्", text: "bastīṃstrirāmatrevaṃ tu snehamātrāṃ vivardhayet tryahamevaṃ ca viśramya praṇidadhyāt punastryaham" },
      { type: "verse", number: "79", sanskrit: "पक्साद्विरेको वमिते ततः पक्षान्निरूहणम् सद्यो निरूढश्चान्वास्यः सप्तरात्राद्विरोचितः", text: "paksādvireko vamite tataḥ pakṣānnirūhaṇam sadyo nirūḍhaścānvāsyaḥ saptarātrādvirocitaḥ" },
      { type: "verse", number: "80", sanskrit: "यथा कुसुम्भादियुतात्तोयाद्रागं हरेत् पटः तथा द्रवीकृताद्देहाद्बस्तिर्निर्हरते मलान्", text: "yathā kusumbhādiyutāttoyādrāgaṃ haret paṭaḥ tathā dravīkṛtāddehādbastirnirharate malān" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 29,
    lang: "sa",
    content: [
      { type: "heading", heading: "Агни видхи — поддержание Агни" },
      { type: "text", text: "Глава 29 Сутрастханы Астанга-санграхи посвящена теме «поддержание Агни». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो नस्यविधिर्नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto nasyavidhirnāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "नासायां प्रणीयमानमौषधं नस्यम् नावनं नस्तःकर्मेति च संज्ञां लभते नासा हि शिरसो द्वारम् तत्रावसेचितमौषधं स्रोतःशृङ्गाटकं प्राप्य व्याप्य च मूर्धानं नेत्रश्रोत्रकण्ठादिसिरामुखानि च मुञ्जादिषीकामिवासक्तामूर्ध्वजत्रुगतां वैकारिकीमशेषामाशु दोषसंहतिमुत्तमाङ्गादपकर्षति", text: "nāsāyāṃ praṇīyamānamauṣadhaṃ nasyam nāvanaṃ nastaḥkarmeti ca saṃjñāṃ labhate nāsā hi śiraso dvāram tatrāvasecitamauṣadhaṃ srotaḥśṛṅgāṭakaṃ prāpya vyāpya ca mūrdhānaṃ netraśrotrakaṇṭhādisirāmukhāni ca muñjādiṣīkāmivāsaktāmūrdhvajatrugatāṃ vaikārikīmaśeṣāmāśu doṣasaṃhatimuttamāṅgādapakarṣati" },
      { type: "verse", number: "3", sanskrit: "तत्तु त्रिविधं विरेचनं बृंहणं शमनं च तेषां विरेचनं जत्रूर्ध्वगौरवशोफोपदेहकण्डूस्तम्भाभिष्यन्दपाकप्रसेकवैरस्यारोचकस्वरभेदक्रिमिप्रतिश्यायापस्मारगन्धाज्ञानग्रन्थ्यर्बुददद्रुकोठादिषु श्लेष्मजेषु तीक्ष्णेन स्नेहेन शिरोविरेचनद्रव्यैर्वा सिद्धेन तेषां वा क्वाथचूर्णस्वरसैस्तैरेव वा यथार्हद्रवश्लक्ष्णकल्कितालोडितैर्मधुसैन्धवासवपित्तमूत्रैर्यथास्वं चोपदिष्टैर्योज्यम्", text: "tattu trividhaṃ virecanaṃ bṛṃhaṇaṃ śamanaṃ ca teṣāṃ virecanaṃ jatrūrdhvagauravaśophopadehakaṇḍūstambhābhiṣyandapākaprasekavairasyārocakasvarabhedakrimipratiśyāyāpasmāragandhājñānagranthyarbudadadrukoṭhādiṣu śleṣmajeṣu tīkṣṇena snehena śirovirecanadravyairvā siddhena teṣāṃ vā kvāthacūrṇasvarasaistaireva vā yathārhadravaślakṣṇakalkitāloḍitairmadhusaindhavāsavapittamūtrairyathāsvaṃ copadiṣṭairyojyam" },
      { type: "verse", number: "4", sanskrit: "तत्र भीतक्लीबकृशसुकुमारेषु स्नेहः गलरोगसन्निपातज्वरातिनिद्रामनोविकारक्रिमिविषाभिपन्नाभिष्यण्णसर्पदष्टविसंज्ञेषु शोषाः तेष्वेव भूयसि दोषे शीघ्रकारिणि च चूर्णः स हि निहितो नासाग्र आवेगकरतरो भवति", text: "tatra bhītaklībakṛśasukumāreṣu snehaḥ galarogasannipātajvarātinidrāmanovikārakrimiviṣābhipannābhiṣyaṇṇasarpadaṣṭavisaṃjñeṣu śoṣāḥ teṣveva bhūyasi doṣe śīghrakāriṇi ca cūrṇaḥ sa hi nihito nāsāgra āvegakarataro bhavati" },
      { type: "verse", number: "5", sanskrit: "बृंहणं सूर्यावर्तार्धावभेदकक्रिमिशिरोरोगाक्षिसङ्कोचस्पन्दतिमिरकृच्छ्रावबोधदन्तकर्णशूलनादनासामुखशोषवाक्यसङ्गस्वरोपघातमन्यारोगापतानकापबाहुकनिद्रानाशादिष्वनिलोत्थेषु स्निग्धमधुरद्रव्यैस्तत्सिद्धैर्यथायथं चोपदिष्टैः स्नेहैर्निर्यासैर्धन्वमांसरसरक्तैश्च", text: "bṛṃhaṇaṃ sūryāvartārdhāvabhedakakrimiśirorogākṣisaṅkocaspandatimirakṛcchrāvabodhadantakarṇaśūlanādanāsāmukhaśoṣavākyasaṅgasvaropaghātamanyārogāpatānakāpabāhukanidrānāśādiṣvanilottheṣu snigdhamadhuradravyaistatsiddhairyathāyathaṃ copadiṣṭaiḥ snehairniryāsairdhanvamāṃsarasaraktaiśca" },
      { type: "verse", number: "6", sanskrit: "शमनमकालवलीपलितखलतिदारुणकरक्तराजीव्यङ्गनीलिकारक्तपित्तादिषु यथास्वमुपदिष्टैः स्नेहैर्भेषजस्वरसादिभिः क्षीरोदकाभ्यां वा समदोषे वाणुतैलेनेति", text: "śamanamakālavalīpalitakhalatidāruṇakaraktarājīvyaṅganīlikāraktapittādiṣu yathāsvamupadiṣṭaiḥ snehairbheṣajasvarasādibhiḥ kṣīrodakābhyāṃ vā samadoṣe vāṇutaileneti" },
      { type: "verse", number: "7", sanskrit: "तत्र स्नेहो मात्राभेदाद् द्विधा मर्शः प्रतिमर्शश्च विरेचनः शमनो वा नासया प्रणीयमानः कल्को ऽवपीडसंज्ञो विरेचनचूर्णस्तु प्रधमनाख्यः परिशेषं तु नावनमवपीडकसंज्ञम् कल्कीकृतादौषधादवपीडितः स्रुतो रसो ऽवपीड इत्यपरेषाम् तत्र पुनस्तीक्ष्णे वैशेषिकी शिरोविरेचनसंज्ञा तथान्ये सर्वमेव विरेचनं नस्यमित्याहुः सद्यः श्लेष्मविरेचनसामान्यात्", text: "tatra sneho mātrābhedād dvidhā marśaḥ pratimarśaśca virecanaḥ śamano vā nāsayā praṇīyamānaḥ kalko 'vapīḍasaṃjño virecanacūrṇastu pradhamanākhyaḥ pariśeṣaṃ tu nāvanamavapīḍakasaṃjñam kalkīkṛtādauṣadhādavapīḍitaḥ sruto raso 'vapīḍa ityapareṣām tatra punastīkṣṇe vaiśeṣikī śirovirecanasaṃjñā tathānye sarvameva virecanaṃ nasyamityāhuḥ sadyaḥ śleṣmavirecanasāmānyāt" },
      { type: "verse", number: "8", sanskrit: "अथाणुतैलस्य विधानमुच्यते अणुतैलविधानं तु मञ्जिष्ठामधुकप्रपौण्डरीकजीवकर्षभककाकोलीद्वयपयस्यासारिवानन्तानीलोत्पलाञ्जनरास्नाविडङ्गतण्डुलमधुपर्णीश्रावणीमेदाकाकनासासरलसालभद्रदारुचन्दनः सुपिष्टैरष्टगुणं षड्गुणेन पयसा तैलं पचेत् घृतं वा पित्तोल्बणेषु दोषेषु", text: "athāṇutailasya vidhānamucyate aṇutailavidhānaṃ tu mañjiṣṭhāmadhukaprapauṇḍarīkajīvakarṣabhakakākolīdvayapayasyāsārivānantānīlotpalāñjanarāsnāviḍaṅgataṇḍulamadhuparṇīśrāvaṇīmedākākanāsāsaralasālabhadradārucandanaḥ supiṣṭairaṣṭaguṇaṃ ṣaḍguṇena payasā tailaṃ pacet ghṛtaṃ vā pittolbaṇeṣu doṣeṣu" },
      { type: "verse", number: "9", sanskrit: "अथवा चन्दनागरुपत्रदार्वीत्वङ्मधुकबलाद्वयबिल्वोत्पलपद्मकेसरप्रपौण्डरीकविडङ्गोशीरह्रीबेरवन्यत्वङ्मुस्तासारिबाबृहतीद्वयांशुमतीद्वयजीवन्तीदेवदारुसुरभिशतावरीः शतगुणे दिव्ये ऽम्भसि दशभागावशिष्टं क्वाथयेत् ततस्तस्य क्वाथस्य दशमांशेन समांशं तैलं साधयेत् दशमे चात्र पाके तैलतुल्यमाजमपि पयो दद्यात् एतदप्यणुतैलं पूर्वस्माद्विशेषेणेन्द्रियदार्ढ्यकरं केश्यं त्वच्यं कण्ठ्यं प्रीणनं बृंहणं दोषत्रयघ्नं च", text: "athavā candanāgarupatradārvītvaṅmadhukabalādvayabilvotpalapadmakesaraprapauṇḍarīkaviḍaṅgośīrahrīberavanyatvaṅmustāsāribābṛhatīdvayāṃśumatīdvayajīvantīdevadārusurabhiśatāvarīḥ śataguṇe divye 'mbhasi daśabhāgāvaśiṣṭaṃ kvāthayet tatastasya kvāthasya daśamāṃśena samāṃśaṃ tailaṃ sādhayet daśame cātra pāke tailatulyamājamapi payo dadyāt etadapyaṇutailaṃ pūrvasmādviśeṣeṇendriyadārḍhyakaraṃ keśyaṃ tvacyaṃ kaṇṭhyaṃ prīṇanaṃ bṛṃhaṇaṃ doṣatrayaghnaṃ ca" },
      { type: "verse", number: "10", sanskrit: "अनस्यार्हास्तु भुक्तभक्तस्नेहमद्यगरतोयपीतपातुकामशिरः स्नातस्नातुकामसिरादिव्यधस्रुतरक्तमूत्रितोच्चारिताभिहतकृतवमनविरेकबस्तिकर्मगर्भिणीसूतिकानवप्रतिश्यायश्वासकासिनो ऽनार्तवदुर्दिनेष्वपि तत्र भुक्तभक्तस्य नस्येरितो दोष ऊर्ध्वस्रोतांस्यावृत्य छर्दिश्वासकासप्रतिश्यायान् जनयेत् स्नेहादिपीतपातुकामानामक्षिनासास्यस्यन्दोपहतितिमिरशिरोरोगान् शिरःस्नातस्य शिरो ऽक्षिकर्णशूलकण्ठरोगपीनसहनुमन्यास्तम्भार्दितशिरःकम्पान् स्नातुकामस्य मूर्धस्तैमित्यजाड्यारुचिपीनसान् स्रुतरक्तस्य क्षामतामरुचिमग्निसादं च मूत्रितोच्चारितयोर्भृशतरं वेगधारणजान् विकारान् अभिहतस्य तीव्रतरां रुजम् कृतवमनादीनां श्वासकासस्वरेन्द्रियहानिशिरोगौरवकण्डूकृमिदोषान् गर्भिण्या भक्तद्वेषज्वरमूर्च्छार्धावभेदकाः स्युरपत्यं च व्यङ्गं विकलेन्द्रियमुन्मादापस्मारयुक्तं वा सूतिकायाः स्रुतरक्तोक्तान् दोषान् नवप्रतिश्यायस्य स्रोतोरोधाद्दुष्टप्रतिश्यायकेशशातकृमिकण्डूविचर्चिकाः श्वासकासिनोर्व्याधिवृद्धिः अकाले दुर्दिने सहसैव शैत्याच्छिरोरुग्वेपथुस्तैमित्यतालुनेत्रकण्डूपाकमन्यास्तम्भकण्ठरोगप्रतिश्यायारूषिकाः", text: "anasyārhāstu bhuktabhaktasnehamadyagaratoyapītapātukāmaśiraḥ snātasnātukāmasirādivyadhasrutaraktamūtritoccāritābhihatakṛtavamanavirekabastikarmagarbhiṇīsūtikānavapratiśyāyaśvāsakāsino 'nārtavadurdineṣvapi tatra bhuktabhaktasya nasyerito doṣa ūrdhvasrotāṃsyāvṛtya chardiśvāsakāsapratiśyāyān janayet snehādipītapātukāmānāmakṣināsāsyasyandopahatitimiraśirorogān śiraḥsnātasya śiro 'kṣikarṇaśūlakaṇṭharogapīnasahanumanyāstambhārditaśiraḥkampān snātukāmasya mūrdhastaimityajāḍyārucipīnasān srutaraktasya kṣāmatāmarucimagnisādaṃ ca mūtritoccāritayorbhṛśataraṃ vegadhāraṇajān vikārān abhihatasya tīvratarāṃ rujam kṛtavamanādīnāṃ śvāsakāsasvarendriyahāniśirogauravakaṇḍūkṛmidoṣān garbhiṇyā bhaktadveṣajvaramūrcchārdhāvabhedakāḥ syurapatyaṃ ca vyaṅgaṃ vikalendriyamunmādāpasmārayuktaṃ vā sūtikāyāḥ srutaraktoktān doṣān navapratiśyāyasya srotorodhādduṣṭapratiśyāyakeśaśātakṛmikaṇḍūvicarcikāḥ śvāsakāsinorvyādhivṛddhiḥ akāle durdine sahasaiva śaityācchirorugvepathustaimityatālunetrakaṇḍūpākamanyāstambhakaṇṭharogapratiśyāyārūṣikāḥ" },
      { type: "verse", number: "11", sanskrit: "तेषु यथास्वमायतनं दोषोद्रेकं चापेक्ष्य स्नेहस्वेदशोरोवक्त्रलेपसेकतीक्ष्णावपीडधूमगण्डूषादीनाचरेत् विशेषेण तु गर्भिणी रूक्षे नस्यकर्मणि वर्षाभूकाकोलीकपिकच्छुभिः शृतं पयः पिबेत् बलाविदार्यंशुमतीमेदाभिर्वा एभिरेव च शृतं हविः वातहरसिद्धश्च स्नेहः शिरोबस्तौ कर्णपूरणे च योज्यः सर्वं च बृंहणमन्नपानम् भुक्तभक्तादिष्वपि चात्ययिकव्याध्यातुरमपेक्षेत", text: "teṣu yathāsvamāyatanaṃ doṣodrekaṃ cāpekṣya snehasvedaśorovaktralepasekatīkṣṇāvapīḍadhūmagaṇḍūṣādīnācaret viśeṣeṇa tu garbhiṇī rūkṣe nasyakarmaṇi varṣābhūkākolīkapikacchubhiḥ śṛtaṃ payaḥ pibet balāvidāryaṃśumatīmedābhirvā ebhireva ca śṛtaṃ haviḥ vātaharasiddhaśca snehaḥ śirobastau karṇapūraṇe ca yojyaḥ sarvaṃ ca bṛṃhaṇamannapānam bhuktabhaktādiṣvapi cātyayikavyādhyāturamapekṣeta" },
      { type: "verse", number: "12", sanskrit: "मर्शप्रमाणं तु प्रदेशिन्यङ्गुलीपर्वद्वयान्निमग्नेद्धृताद्यावत् पतति स बिन्दुः अमी दशाष्टौ षड्बिन्दव उत्तममध्यमकनीयस्यो मात्राः क्वाथादीनामष्टौ षट् चत्वारः प्रधमनस्य तु षडङ्गुलद्विमुखया नाड्यामुखानिलेरितस्याकण्ठगतेर्दोषानुरोधतश्च पुनःपुनर्योजनमिति", text: "marśapramāṇaṃ tu pradeśinyaṅgulīparvadvayānnimagneddhṛtādyāvat patati sa binduḥ amī daśāṣṭau ṣaḍbindava uttamamadhyamakanīyasyo mātrāḥ kvāthādīnāmaṣṭau ṣaṭ catvāraḥ pradhamanasya tu ṣaḍaṅguladvimukhayā nāḍyāmukhānileritasyākaṇṭhagaterdoṣānurodhataśca punaḥpunaryojanamiti" },
      { type: "verse", number: "13", sanskrit: "अथ नस्यार्हं नरमव्याहतवेगं धौतान्तर्बहिर्मुखं स्निग्धस्विन्नशिरसं नातिक्षुधितं प्रायोगिकधूमपानविशुद्धस्रोतसं स्वास्तीर्णनिवातशयनस्थुत्तानशीर्षमीषदुन्नतपादं प्रसारितकरचरणं जत्रूर्ध्वं पाणितापेन पुनः पुनः स्वेदयेत् ततः कनकरजतताम्रान्यतमशुक्तिस्थितं प्रदेयमौषधत्रिभागमुष्णाम्बुप्रतप्तं किञ्चित् प्रलम्बितशिरसो वामहस्ताङ्गुष्ठकनिष्ठिकाभ्यामाक्रम्य नयनप्रच्छादनं चतुर्गुणं वासो मध्यमया नासाग्रमुन्नमय्य प्रदेशिन्यनामिकाभ्यां चैकैकं नासापुटं पर्यायेण पिधायेतरस्मिन् नासास्रोतसि दक्षिणहस्तेन प्रनाड्या पिचुना वानवच्छिन्नमासिञ्चेत्", text: "atha nasyārhaṃ naramavyāhatavegaṃ dhautāntarbahirmukhaṃ snigdhasvinnaśirasaṃ nātikṣudhitaṃ prāyogikadhūmapānaviśuddhasrotasaṃ svāstīrṇanivātaśayanasthuttānaśīrṣamīṣadunnatapādaṃ prasāritakaracaraṇaṃ jatrūrdhvaṃ pāṇitāpena punaḥ punaḥ svedayet tataḥ kanakarajatatāmrānyatamaśuktisthitaṃ pradeyamauṣadhatribhāgamuṣṇāmbuprataptaṃ kiñcit pralambitaśiraso vāmahastāṅguṣṭhakaniṣṭhikābhyāmākramya nayanapracchādanaṃ caturguṇaṃ vāso madhyamayā nāsāgramunnamayya pradeśinyanāmikābhyāṃ caikaikaṃ nāsāpuṭaṃ paryāyeṇa pidhāyetarasmin nāsāsrotasi dakṣiṇahastena pranāḍyā picunā vānavacchinnamāsiñcet" },
      { type: "verse", number: "14", sanskrit: "वातपित्तकफामयेषु क्रमेणापराह्णमध्याह्नपूर्वाह्णेषु लालास्रावसुप्तप्रलापदन्तकटकटायनक्रथनकृच्छ्रोन्मीलनपूतिमुखकर्णनादतृष्णार्दितशिरोरोगश्वासकासोन्निद्रेषु रात्रौ स्वस्थवृत्ते तु शीते मध्याह्ने शरद्वसन्तयोः प्राह्णे ग्रीष्मे ऽपराह्णे वर्षास्वादित्यदर्शने पञ्चकर्माण्याचरतो बस्तिकर्मोत्तरकालमेव", text: "vātapittakaphāmayeṣu krameṇāparāhṇamadhyāhnapūrvāhṇeṣu lālāsrāvasuptapralāpadantakaṭakaṭāyanakrathanakṛcchronmīlanapūtimukhakarṇanādatṛṣṇārditaśirorogaśvāsakāsonnidreṣu rātrau svasthavṛtte tu śīte madhyāhne śaradvasantayoḥ prāhṇe grīṣme 'parāhṇe varṣāsvādityadarśane pañcakarmāṇyācarato bastikarmottarakālameva" },
      { type: "verse", number: "15", sanskrit: "न च हीनाधिकं सकृदेव सर्वमत्युष्णशीतमत्युन्नतावनतशिरसे सङ्कुचितगात्रावयवाय देयम् तत्र हीनं दोषमुत्क्लेश्य न निर्हरेत् गौरवारुचिकासप्रसेकपीनसच्छर्दिकण्ठरोगान् कुर्यात् अधिकमतियोगदोषान् सकृदेव सर्वं दत्तमुत्स्नेहनशिरोरोगप्रतिश्यायघ्राणक्लेदानुच्छ्वासोपरोधं च अत्युष्णं दाहपाकज्वररक्तागमशिरोरुग्दृष्टिदौर्बल्यमूर्च्छाभ्रमान् अतिशीतं हीनदोषान् अत्युन्नतशिरसो ऽपि सम्यक्शिरो ऽप्रतिपद्यमानं तानेव अत्यवनतशिरसो ऽतिदूरगमनान्मूर्छाजाड्यकण्डूदाहज्वरान् सङ्कुचितगात्रस्य सम्यग्धमनीरव्याप्नुवद्दोषोत्क्लेशं वेदनां स्तम्भं वा यदि च नस्ये दीयमाने भेषजवेगादसात्म्यतया वा मूर्च्छा स्यात् ततः शिरोवर्जं शीताम्भसा सिञ्चेत् न च नस्ये निषिच्यमाने कोपहास्यव्याहारस्पन्दनोच्छिङ्खनान्याचरेत् तथा हि शिरोरुक्प्रतिश्यायकासतिमिरखलतिपलितव्यङ्गतिलकालकमुखदूषिकाणां सम्भवः", text: "na ca hīnādhikaṃ sakṛdeva sarvamatyuṣṇaśītamatyunnatāvanataśirase saṅkucitagātrāvayavāya deyam tatra hīnaṃ doṣamutkleśya na nirharet gauravārucikāsaprasekapīnasacchardikaṇṭharogān kuryāt adhikamatiyogadoṣān sakṛdeva sarvaṃ dattamutsnehanaśirorogapratiśyāyaghrāṇakledānucchvāsoparodhaṃ ca atyuṣṇaṃ dāhapākajvararaktāgamaśirorugdṛṣṭidaurbalyamūrcchābhramān atiśītaṃ hīnadoṣān atyunnataśiraso 'pi samyakśiro 'pratipadyamānaṃ tāneva atyavanataśiraso 'tidūragamanānmūrchājāḍyakaṇḍūdāhajvarān saṅkucitagātrasya samyagdhamanīravyāpnuvaddoṣotkleśaṃ vedanāṃ stambhaṃ vā yadi ca nasye dīyamāne bheṣajavegādasātmyatayā vā mūrcchā syāt tataḥ śirovarjaṃ śītāmbhasā siñcet na ca nasye niṣicyamāne kopahāsyavyāhāraspandanocchiṅkhanānyācaret tathā hi śirorukpratiśyāyakāsatimirakhalatipalitavyaṅgatilakālakamukhadūṣikāṇāṃ sambhavaḥ" },
      { type: "verse", number: "16", sanskrit: "दत्तमात्रे तु नस्ये कर्णललाटकेशभूमिगण्डमन्यास्कन्धपाणिपादतलान्यनुसुखं मर्दयेत् शनैश्चोच्छिङ्खेत् अनभ्यवहरंश्च वामदक्षिणपार्श्वयोरौषधं निष्ठीवेत् सकफं हि तदभ्यवहृतमग्निमवसादयेत् दोषं च संवर्धयेत् एकपार्श्वनिष्ठीवनेन सर्वाः सिरा भेषजेन सम्यग्व्याप्यन्ते पुनः पुनश्चैनं स्वेदयेदाभेषजदर्शनान्नोछिङ्खेन्निष्ठीवेच्चाततश्चैवमेव द्वितीयमंशमनुषेचयेत्तथा तृतीयं दोषादिबलेन वा विरेचने त्ववपीडे दोषबलमपेक्ष्य पश्चात् स्नेहमनुषेचयेत् निवृत्तनस्यं चैवमुन्निद्रमुत्तानं वाक्शतमात्रं शाययेत् ततः पुनरप्युत्क्लिष्टदोषशेषोपशान्तये वैरेचनिकं यथार्हं वा धूमं पाययित्वोष्णोदकगण्डूषान् धारयेत् अथास्य स्नेहोक्तमाचारमादिशेत् अतिद्रवपानं च वर्जयेत् पुनश्च तृतीये ऽहनि नस्यमवसेचयेत् हिध्मास्वरोपघातमन्यास्तम्भापतानकेषु शिरसि चानिलार्त्याद्यभिभूते प्रत्यहं सायंप्रातरुभयकालं वा अनेन विधिना पञ्च सप्त नव वा दिनानि दद्यादासम्यग्योगाद्वा", text: "dattamātre tu nasye karṇalalāṭakeśabhūmigaṇḍamanyāskandhapāṇipādatalānyanusukhaṃ mardayet śanaiścocchiṅkhet anabhyavaharaṃśca vāmadakṣiṇapārśvayorauṣadhaṃ niṣṭhīvet sakaphaṃ hi tadabhyavahṛtamagnimavasādayet doṣaṃ ca saṃvardhayet ekapārśvaniṣṭhīvanena sarvāḥ sirā bheṣajena samyagvyāpyante punaḥ punaścainaṃ svedayedābheṣajadarśanānnochiṅkhenniṣṭhīveccātataścaivameva dvitīyamaṃśamanuṣecayettathā tṛtīyaṃ doṣādibalena vā virecane tvavapīḍe doṣabalamapekṣya paścāt snehamanuṣecayet nivṛttanasyaṃ caivamunnidramuttānaṃ vākśatamātraṃ śāyayet tataḥ punarapyutkliṣṭadoṣaśeṣopaśāntaye vairecanikaṃ yathārhaṃ vā dhūmaṃ pāyayitvoṣṇodakagaṇḍūṣān dhārayet athāsya snehoktamācāramādiśet atidravapānaṃ ca varjayet punaśca tṛtīye 'hani nasyamavasecayet hidhmāsvaropaghātamanyāstambhāpatānakeṣu śirasi cānilārtyādyabhibhūte pratyahaṃ sāyaṃprātarubhayakālaṃ vā anena vidhinā pañca sapta nava vā dināni dadyādāsamyagyogādvā" },
      { type: "verse", number: "17", sanskrit: "तत्र सम्यक्स्निग्धे मूर्धनि विरिक्ते वा सुखोच्छ्वासनिश्वासक्षवथुस्वप्नप्रबोधशिरोवदनेन्द्रियविशुद्धयो भवन्ति यथोक्तव्याध्युपशमश्च अयोगातियोगयोस्तु यथास्वं वातकफविकारास्तान्यथास्वमेव साधयेत् अन्यांश्च पूर्वोक्तान् विकारान्", text: "tatra samyaksnigdhe mūrdhani virikte vā sukhocchvāsaniśvāsakṣavathusvapnaprabodhaśirovadanendriyaviśuddhayo bhavanti yathoktavyādhyupaśamaśca ayogātiyogayostu yathāsvaṃ vātakaphavikārāstānyathāsvameva sādhayet anyāṃśca pūrvoktān vikārān" },
      { type: "verse", number: "18", sanskrit: "प्रतिमर्शस्तु क्षामक्षततृष्णामुखशोषवृद्धबालभीरुसुकुमारेष्वप्यकालवर्षदुर्दिनेष्वपि च योज्यः न तु दुष्टप्रतिश्यायबहुदोषक्रिमिणशिरोमद्यपीतदुर्बलश्रोत्रेषु एषां ह्युदीर्णदोषत्वात् तावता दोषोत्क्लेशो भवति तस्य पञ्चदश कालास्तेषां च गुणाः प्रातर्दत्ते भुक्तवतश्चान्ते स्रोतोविशुद्धिः शिरोलाघवं मनःप्रसादश्च भवति विण्मूत्रशिरोभ्यङ्गाञ्जनकवलान्ते दृष्टिप्रसादः दन्तधावनान्ते दन्तदृढता सौगन्ध्यं च अध्वव्यायामव्यवायान्ते श्रमक्लमस्वेदस्तम्भनाशः दिवास्वप्नान्ते निद्राशेषगौरवप्रणाशो मनःप्रसादश्च अतिहसितान्ते ऽनिलप्रशमः छर्दितान्ते स्रोतोलीनश्लेष्मव्यपोहः दिनान्ते स्रोतोविशुद्धिः सुखनिद्राप्रबोधश्च भवति भवति चात्र", text: "pratimarśastu kṣāmakṣatatṛṣṇāmukhaśoṣavṛddhabālabhīrusukumāreṣvapyakālavarṣadurdineṣvapi ca yojyaḥ na tu duṣṭapratiśyāyabahudoṣakrimiṇaśiromadyapītadurbalaśrotreṣu eṣāṃ hyudīrṇadoṣatvāt tāvatā doṣotkleśo bhavati tasya pañcadaśa kālāsteṣāṃ ca guṇāḥ prātardatte bhuktavataścānte srotoviśuddhiḥ śirolāghavaṃ manaḥprasādaśca bhavati viṇmūtraśirobhyaṅgāñjanakavalānte dṛṣṭiprasādaḥ dantadhāvanānte dantadṛḍhatā saugandhyaṃ ca adhvavyāyāmavyavāyānte śramaklamasvedastambhanāśaḥ divāsvapnānte nidrāśeṣagauravapraṇāśo manaḥprasādaśca atihasitānte 'nilapraśamaḥ charditānte srotolīnaśleṣmavyapohaḥ dinānte srotoviśuddhiḥ sukhanidrāprabodhaśca bhavati bhavati cātra" },
      { type: "verse", number: "19", sanskrit: "प्रमाणं प्रतिमर्शस्य बिन्दुद्वितयमिष्यते बिन्दुर्वा येन चोत्क्लेशो नानुत्क्लिष्टस्य जायते", text: "pramāṇaṃ pratimarśasya bindudvitayamiṣyate bindurvā yena cotkleśo nānutkliṣṭasya jāyate" },
      { type: "verse", number: "20", sanskrit: "निष्ठ्यूते यत्र वा स्नेहो न साक्षादुपलक्ष्यते न नस्यमूनसप्ताबदे नातीताशीतिवत्सरे", text: "niṣṭhyūte yatra vā sneho na sākṣādupalakṣyate na nasyamūnasaptābade nātītāśītivatsare" },
      { type: "verse", number: "21", sanskrit: "न चोनाष्टादशे धूमः कवलो नोनपञ्चमे न शुद्धिरूनदशमे न चातिक्रान्तसप्ततौ", text: "na conāṣṭādaśe dhūmaḥ kavalo nonapañcame na śuddhirūnadaśame na cātikrāntasaptatau" },
      { type: "verse", number: "22", sanskrit: "आजन्ममरणं शस्तः प्रतिमर्शस्तु बस्तिवत् मर्शवच्च गुणान् कुर्यात् स हि नित्योपसेवनात्", text: "ājanmamaraṇaṃ śastaḥ pratimarśastu bastivat marśavacca guṇān kuryāt sa hi nityopasevanāt" },
      { type: "verse", number: "23", sanskrit: "न चात्र यन्त्रणा नापि व्यापद्भ्यो मर्शवद्भयम् तैलमेव च नस्यार्थे नित्याभ्यासेन शस्यते शिरसः श्लेष्मधामत्वात् स्नेहाः स्वस्थस्य नेतरे", text: "na cātra yantraṇā nāpi vyāpadbhyo marśavadbhayam tailameva ca nasyārthe nityābhyāsena śasyate śirasaḥ śleṣmadhāmatvāt snehāḥ svasthasya netare" },
      { type: "verse", number: "24", sanskrit: "आशुकृच्चिरकारित्वं गुणोत्कृष्ताव्कृष्टता मर्शे च प्रतिमर्शे च न विशेषो भवेद्यदि को मर्शं सपरीहारं सापदं च भजेत्ततः", text: "āśukṛccirakāritvaṃ guṇotkṛṣtāvkṛṣṭatā marśe ca pratimarśe ca na viśeṣo bhavedyadi ko marśaṃ saparīhāraṃ sāpadaṃ ca bhajettataḥ" },
      { type: "verse", number: "25", sanskrit: "अच्छपानविचाराख्यौ कुटीवातातपस्थिती अन्वासमात्राबस्ती च तद्वदेव च निर्दिशेत्", text: "acchapānavicārākhyau kuṭīvātātapasthitī anvāsamātrābastī ca tadvadeva ca nirdiśet" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 30,
    lang: "sa",
    content: [
      { type: "heading", heading: "Дхату самья — баланс тканей" },
      { type: "text", text: "Глава 30 Сутрастханы Астанга-санграхи посвящена теме «баланс тканей». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो धूमपानविधिं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto dhūmapānavidhiṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "धूमो हि शिरो ऽक्षिकर्णशूलाभिष्यन्दगौरवार्धावभेदकपीनसकासश्वासास्यवैरस्यप्रसेकवैस्वर्यपूतिघ्राणमुखहिध्मागलरोगदन्तशूलदौर्बल्यारुचिहनुमन्याग्रहक्रिमिकण्डूपाण्डुत्वक्वेशदोषक्षवथुनाशबाहुल्यतन्द्रातिनिद्राक्रथनादिजत्रूर्ध्वगतवातकफव्याधिप्रशमाय प्रयुज्यते तथा शिरःकपालेन्द्रियमनोबृंहणप्रसादनाय च", text: "dhūmo hi śiro 'kṣikarṇaśūlābhiṣyandagauravārdhāvabhedakapīnasakāsaśvāsāsyavairasyaprasekavaisvaryapūtighrāṇamukhahidhmāgalarogadantaśūladaurbalyārucihanumanyāgrahakrimikaṇḍūpāṇḍutvakveśadoṣakṣavathunāśabāhulyatandrātinidrākrathanādijatrūrdhvagatavātakaphavyādhipraśamāya prayujyate tathā śiraḥkapālendriyamanobṛṃhaṇaprasādanāya ca" },
      { type: "verse", number: "3", sanskrit: "शीतद्रव्यनिर्वृत्तो ऽप्यग्निसंयोगादुष्णतया पित्तरक्तविरुद्धः स त्रिविधो भवति शमनो बृंहणः शोधनश्च तथा कासघ्नो वामनो व्रणधूपनश्च तत्र शनमः प्रायोगिको मध्यम इति पर्यायः बृंहणः स्नेहनो मृदुरिति शोधनो विरेचनस्तीक्ष्ण इति च", text: "śītadravyanirvṛtto 'pyagnisaṃyogāduṣṇatayā pittaraktaviruddhaḥ sa trividho bhavati śamano bṛṃhaṇaḥ śodhanaśca tathā kāsaghno vāmano vraṇadhūpanaśca tatra śanamaḥ prāyogiko madhyama iti paryāyaḥ bṛṃhaṇaḥ snehano mṛduriti śodhano virecanastīkṣṇa iti ca" },
      { type: "verse", number: "4", sanskrit: "अधूमार्हास्तु विरिक्तदत्तबस्तिरात्रिजागरिताभिहतशिरोमधुदधिदुग्धमद्यस्नेहयवागूविषपयःपीतमत्स्याशितपाण्डुरोगप्रमेहोदराध्मानोर्ध्ववाततिमिररोहिणिकारक्तपित्तिनो ऽत्युष्णो ऽन्येपि च एषां हि भ्रमज्वरशिरो ऽभितापेन्द्रियोपघाततालुशोषपाकधूमायनच्छर्दिमूर्छारक्तपित्तार्दितानि मृत्युं वा धूमो जनयति अतिमात्रश्चान्येषामपि", text: "adhūmārhāstu viriktadattabastirātrijāgaritābhihataśiromadhudadhidugdhamadyasnehayavāgūviṣapayaḥpītamatsyāśitapāṇḍurogapramehodarādhmānordhvavātatimirarohiṇikāraktapittino 'tyuṣṇo 'nyepi ca eṣāṃ hi bhramajvaraśiro 'bhitāpendriyopaghātatāluśoṣapākadhūmāyanacchardimūrchāraktapittārditāni mṛtyuṃ vā dhūmo janayati atimātraścānyeṣāmapi" },
      { type: "verse", number: "5", sanskrit: "तत्र वातकफान्यतरसंसृष्टं पित्तमुपलक्ष्य यथास्वं सर्पिःकषायपाननस्यास्यालेपनाञ्जनपरिषेकान् स्निग्धरूक्षशीतान् प्रयुञ्जीत एतेन सर्वधूमोपघातप्रतिकारा व्याख्याताः", text: "tatra vātakaphānyatarasaṃsṛṣṭaṃ pittamupalakṣya yathāsvaṃ sarpiḥkaṣāyapānanasyāsyālepanāñjanapariṣekān snigdharūkṣaśītān prayuñjīta etena sarvadhūmopaghātapratikārā vyākhyātāḥ" },
      { type: "verse", number: "6", sanskrit: "विशेषतस्तु सर्वस्रोतोगते धूमे भवन्त्यूषाध्माननेत्ररोगश्वासकासपीनसाङ्गस्वरसादाम्लकाः तत्र घृतक्षीरेक्षुरसद्राक्षाशर्करोपयोगस्तद्विधैरेव वमनम् कटुतिक्तैरपि च नस्यगण्डूषाः", text: "viśeṣatastu sarvasrotogate dhūme bhavantyūṣādhmānanetrarogaśvāsakāsapīnasāṅgasvarasādāmlakāḥ tatra ghṛtakṣīrekṣurasadrākṣāśarkaropayogastadvidhaireva vamanam kaṭutiktairapi ca nasyagaṇḍūṣāḥ" },
      { type: "verse", number: "7", sanskrit: "पानकालास्त्वष्टौ प्रायोगिकस्य निशामूत्रशकृद्दन्तधाचनस्वेदनस्याहारशस्त्रकर्मान्ताः एकादश मृदोः क्षुतव्यवायहसितचिरासितजृम्भितमूत्रशकृद्दन्तधावनतर्पणपुटपाकशस्त्रकर्मान्ताः पञ्च तीक्ष्णस्य नस्याञ्जनछर्दितस्नानाहस्स्वप्नान्ताः एषु हि कालेषु वातकफोत्क्लेशो भवति", text: "pānakālāstvaṣṭau prāyogikasya niśāmūtraśakṛddantadhācanasvedanasyāhāraśastrakarmāntāḥ ekādaśa mṛdoḥ kṣutavyavāyahasitacirāsitajṛmbhitamūtraśakṛddantadhāvanatarpaṇapuṭapākaśastrakarmāntāḥ pañca tīkṣṇasya nasyāñjanacharditasnānāhassvapnāntāḥ eṣu hi kāleṣu vātakaphotkleśo bhavati" },
      { type: "verse", number: "8", sanskrit: "नेत्रं तु बस्तिनेत्रद्रव्यभवं गोपुच्छाकारमग्रमूलयोः कनिष्ठिकाङ्गुष्ठपरिणाहं राजमाषवाहिधूमवर्तिप्रवेशाच्छिद्रमृजु त्रिकोशं श्लक्ष्णं शिथिलशलाकागर्भं शमनादिषु क्रमादातुराङ्गुलमानेन चत्वारिंशद्द्वात्रिंशच्चतुर्विंशत्यङ्गुलं कुर्यात् कासघ्ने वमने च दशाङ्गुलम् व्रणधूपनार्थे ऽष्टाङ्गुलम् कलायपरिमण्डलं कुलत्थवाहि स्रोत इति एवं हि धूमो दूरात् प्रवृत्तो नेत्रस्य पर्वच्छेदादूर्ध्वं तनुतया च शनैः श्लिष्यन्नबाधको भवति", text: "netraṃ tu bastinetradravyabhavaṃ gopucchākāramagramūlayoḥ kaniṣṭhikāṅguṣṭhapariṇāhaṃ rājamāṣavāhidhūmavartipraveśācchidramṛju trikośaṃ ślakṣṇaṃ śithilaśalākāgarbhaṃ śamanādiṣu kramādāturāṅgulamānena catvāriṃśaddvātriṃśaccaturviṃśatyaṅgulaṃ kuryāt kāsaghne vamane ca daśāṅgulam vraṇadhūpanārthe 'ṣṭāṅgulam kalāyaparimaṇḍalaṃ kulatthavāhi srota iti evaṃ hi dhūmo dūrāt pravṛtto netrasya parvacchedādūrdhvaṃ tanutayā ca śanaiḥ śliṣyannabādhako bhavati" },
      { type: "verse", number: "9", sanskrit: "कासघ्नादिषु तु नेत्राभावे नलवंशैरण्डादीनामन्यतमा नाडीं योजयेत्", text: "kāsaghnādiṣu tu netrābhāve nalavaṃśairaṇḍādīnāmanyatamā nāḍīṃ yojayet" },
      { type: "verse", number: "10", sanskrit: "यथास्वं च धूमद्रव्याणां कल्केन श्लक्ष्णेनाक्षमात्रेण द्वादशाङ्गुलामिषीकामम्भस्यहोरात्रोषितां कृत्वा लेपयेत् तत्र च नवाङ्गुलगर्भां पञ्चप्रलेपामङ्गुष्ठस्थूलां यवमध्यां छायाशुष्कां वर्तिं कृत्वा विगतेषीकां च स्नेहाक्तामङ्गारेषु प्रदीप्य नेत्रमूलच्छिद्रे च निधाय यथार्हं पानायोपनयेत्", text: "yathāsvaṃ ca dhūmadravyāṇāṃ kalkena ślakṣṇenākṣamātreṇa dvādaśāṅgulāmiṣīkāmambhasyahorātroṣitāṃ kṛtvā lepayet tatra ca navāṅgulagarbhāṃ pañcapralepāmaṅguṣṭhasthūlāṃ yavamadhyāṃ chāyāśuṣkāṃ vartiṃ kṛtvā vigateṣīkāṃ ca snehāktāmaṅgāreṣu pradīpya netramūlacchidre ca nidhāya yathārhaṃ pānāyopanayet" },
      { type: "verse", number: "11", sanskrit: "अथ धूमार्हः सुमना ऋजूपविष्टः प्राक्कृतोच्छ्वासनिश्वासो विवृतौष्ठदशनो नेत्रग्रनिविष्टदृष्टिः पर्यायेणैकैकं नासापुटं पिधायेतरेणाक्षिप्य मुखेनोत्सृजेत् मुखेन तु मुखेनैव न नासया दृग्विघातभयात्", text: "atha dhūmārhaḥ sumanā ṛjūpaviṣṭaḥ prākkṛtocchvāsaniśvāso vivṛtauṣṭhadaśano netragraniviṣṭadṛṣṭiḥ paryāyeṇaikaikaṃ nāsāpuṭaṃ pidhāyetareṇākṣipya mukhenotsṛjet mukhena tu mukhenaiva na nāsayā dṛgvighātabhayāt" },
      { type: "verse", number: "12", sanskrit: "तत्र प्रायोगिकं द्वौ द्वौ त्रींस्त्रीन् वापानां स्त्रींश्च पर्यायान् कण्ठादूर्ध्वमुत्क्लिष्टे दोषे पूर्वं नासया ततो मुखेन कण्ठे तु पूर्वमास्येन परं चाहोरात्रस्य द्विः पिबेत्", text: "tatra prāyogikaṃ dvau dvau trīṃstrīn vāpānāṃ strīṃśca paryāyān kaṇṭhādūrdhvamutkliṣṭe doṣe pūrvaṃ nāsayā tato mukhena kaṇṭhe tu pūrvamāsyena paraṃ cāhorātrasya dviḥ pibet" },
      { type: "verse", number: "13", sanskrit: "स्नेहिकं त्रींस्त्रींश्चतुरश्चतुरो वापानान् यावद्बास्रप्रवृत्तिस्तथा सकृदहोरात्रस्य", text: "snehikaṃ trīṃstrīṃścaturaścaturo vāpānān yāvadbāsrapravṛttistathā sakṛdahorātrasya" },
      { type: "verse", number: "14", sanskrit: "तीक्ष्णं नासाभ्यामेव चतुरश्चतुरश्चापानान् यावद्वा स्रोतोलाघवम् तथा त्रिश्चतुर्वाहोरात्रस्य तत्राक्षेपविसर्गावापानमित्याहुः", text: "tīkṣṇaṃ nāsābhyāmeva caturaścaturaścāpānān yāvadvā srotolāghavam tathā triścaturvāhorātrasya tatrākṣepavisargāvāpānamityāhuḥ" },
      { type: "verse", number: "15", sanskrit: "कासघ्नं तु चूर्णं गुटिकां वा निर्धूमदीप्तस्थिराङ्गारपूर्णे सुसस्थिते शरावे प्रक्षिप्यान्येन मूर्ध्नि प्रवृत्तच्छिद्रेण शरावेणापिधाय निधाय च तत्स्रोतसि नेत्रं कृत्वा मुखेनैव धूमं पिबेत् उरःप्राप्तं च मुखेनैवोद्वमेत् प्रशान्ते च धूमे पुनः क्षिपेत् पिबेच्चादोषशुद्धेर्लाघवाद्वा", text: "kāsaghnaṃ tu cūrṇaṃ guṭikāṃ vā nirdhūmadīptasthirāṅgārapūrṇe susasthite śarāve prakṣipyānyena mūrdhni pravṛttacchidreṇa śarāveṇāpidhāya nidhāya ca tatsrotasi netraṃ kṛtvā mukhenaiva dhūmaṃ pibet uraḥprāptaṃ ca mukhenaivodvamet praśānte ca dhūme punaḥ kṣipet pibeccādoṣaśuddherlāghavādvā" },
      { type: "verse", number: "16", sanskrit: "तद्वद्वामनमपि कृसरामनतिघनां पीत्वा पिबेत् तद्वच्च व्रणमपि धूपयेद्वैशद्याय क्लेदवेदनोपशमनाय च", text: "tadvadvāmanamapi kṛsarāmanatighanāṃ pītvā pibet tadvacca vraṇamapi dhūpayedvaiśadyāya kledavedanopaśamanāya ca" },
      { type: "verse", number: "17", sanskrit: "धूमस्यायोगे दोषोत्क्लेशाद्रोगवृद्धिः अतियोगे प्रागुक्तमिति भवति चात्र", text: "dhūmasyāyoge doṣotkleśādrogavṛddhiḥ atiyoge prāguktamiti bhavati cātra" },
      { type: "verse", number: "18", sanskrit: "हृत्कण्ठेन्द्रियसंशुद्धिः शिरसो लाघवं शमः यथेरितानां रोगाणां सम्यक्पीतस्य लक्षणम्", text: "hṛtkaṇṭhendriyasaṃśuddhiḥ śiraso lāghavaṃ śamaḥ yatheritānāṃ rogāṇāṃ samyakpītasya lakṣaṇam" },
      { type: "verse", number: "19", sanskrit: "शमनो वातकफयोः संसर्गे स्वस्थकर्मणि बृंहणो मारुते शस्तो धूमः संशोधनः कफे", text: "śamano vātakaphayoḥ saṃsarge svasthakarmaṇi bṛṃhaṇo mārute śasto dhūmaḥ saṃśodhanaḥ kaphe" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 31,
    lang: "sa",
    content: [
      { type: "heading", heading: "Мала нирудха — задержка выделений" },
      { type: "text", text: "Глава 31 Сутрастханы Астанга-санграхи посвящена теме «задержка выделений». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो गण्डूषादिविधिमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto gaṇḍūṣādividhimadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "चतुर्विधो भवति गण्डूषः स्नैहिकः शमनः शोधनो रोपणश्च तेषामाद्यास्त्रयः क्रमेण वातपित्तकफामयघ्नाः रोपणस्त्वास्यव्रणघ्नः शमनः स्तम्भनः प्रसादनो निर्वापण इति पर्यायाः", text: "caturvidho bhavati gaṇḍūṣaḥ snaihikaḥ śamanaḥ śodhano ropaṇaśca teṣāmādyāstrayaḥ krameṇa vātapittakaphāmayaghnāḥ ropaṇastvāsyavraṇaghnaḥ śamanaḥ stambhanaḥ prasādano nirvāpaṇa iti paryāyāḥ" },
      { type: "verse", number: "3", sanskrit: "तत्र स्वाद्वम्ललवणोष्णैरौषधैः सिद्धो युक्तो वा नात्युष्णः स्नेहो मांसरसस्तिलकल्कोदकं क्षीरं वा स्नैहिकः तिक्तकषायमधुरशीतैः पटोलारिष्टजम्ब्वाम्रमालतीपल्लवोत्पलमधुकक्वाथासितोदकक्षौद्रक्षीरेक्षुरस घृतादिभिः शमनः कट्वम्ललवणोष्णैः शिरोविरेचनद्रव्यैः शुक्तमद्यधान्याम्लमूत्रान्यतमकल्कितालोडितैः शोधनः रोपणस्तु कषायमधुरशीतैर्यथास्वं चोपदिष्टैः", text: "tatra svādvamlalavaṇoṣṇairauṣadhaiḥ siddho yukto vā nātyuṣṇaḥ sneho māṃsarasastilakalkodakaṃ kṣīraṃ vā snaihikaḥ tiktakaṣāyamadhuraśītaiḥ paṭolāriṣṭajambvāmramālatīpallavotpalamadhukakvāthāsitodakakṣaudrakṣīrekṣurasa ghṛtādibhiḥ śamanaḥ kaṭvamlalavaṇoṣṇaiḥ śirovirecanadravyaiḥ śuktamadyadhānyāmlamūtrānyatamakalkitāloḍitaiḥ śodhanaḥ ropaṇastu kaṣāyamadhuraśītairyathāsvaṃ copadiṣṭaiḥ" },
      { type: "verse", number: "4", sanskrit: "अपि च दन्तहर्षे दन्तचाले मुखरोगे च वातिके सुखोष्णमथवा शीतं तिलकल्कोदकं हितम्", text: "api ca dantaharṣe dantacāle mukharoge ca vātike sukhoṣṇamathavā śītaṃ tilakalkodakaṃ hitam" },
      { type: "verse", number: "5", sanskrit: "गण्डूषधारणे नित्यं तैलं मांसरसो ऽथवा ऊषादाहान्विते पाके क्षते चागन्तुसम्भवे", text: "gaṇḍūṣadhāraṇe nityaṃ tailaṃ māṃsaraso 'thavā ūṣādāhānvite pāke kṣate cāgantusambhave" },
      { type: "verse", number: "6", sanskrit: "विषे क्षाराग्निदग्धे च सर्पिर्धार्यं पयो ऽथवा वैशद्यं जनयत्यास्ये सन्दधाति मुखे व्रणान्", text: "viṣe kṣārāgnidagdhe ca sarpirdhāryaṃ payo 'thavā vaiśadyaṃ janayatyāsye sandadhāti mukhe vraṇān" },
      { type: "verse", number: "7", sanskrit: "दाहतृष्णाप्रामनं मधुगण्डूषधारणम् धान्याम्लमास्यवैरस्यमलदौर्गन्ध्यनाश्नम्", text: "dāhatṛṣṇāprāmanaṃ madhugaṇḍūṣadhāraṇam dhānyāmlamāsyavairasyamaladaurgandhyanāśnam" },
      { type: "verse", number: "8", sanskrit: "तदेवालवणं शीतं मुखशोषहरं परम् आशु क्षाराम्बुगण्डूषो भिनत्ति श्लेष्मणश्चयम्", text: "tadevālavaṇaṃ śītaṃ mukhaśoṣaharaṃ param āśu kṣārāmbugaṇḍūṣo bhinatti śleṣmaṇaścayam" },
      { type: "verse", number: "9", sanskrit: "अथ निवाते सातपे सुखोपविष्टस्तन्मनाः स्विन्नमृदितगलकपोलललाटदेशो वरमध्यावरां क्रमाद्वक्त्रार्धत्रिभागचतुर्भागपूरणीं द्रवमात्रां कल्कं वा कोलप्रमाणं किञ्चिदुन्नमितास्यो ऽनभ्यवहरन् धारयेत् कवले तु पर्यायेण कपोलौ कण्ठं च सञ्चारयेत् अयमेव च कवलगण्डूषयोर्विशेषः", text: "atha nivāte sātape sukhopaviṣṭastanmanāḥ svinnamṛditagalakapolalalāṭadeśo varamadhyāvarāṃ kramādvaktrārdhatribhāgacaturbhāgapūraṇīṃ dravamātrāṃ kalkaṃ vā kolapramāṇaṃ kiñcidunnamitāsyo 'nabhyavaharan dhārayet kavale tu paryāyeṇa kapolau kaṇṭhaṃ ca sañcārayet ayameva ca kavalagaṇḍūṣayorviśeṣaḥ" },
      { type: "verse", number: "10", sanskrit: "मुखे सञ्चार्यते या तु सा मात्रा कवलः स्मृतः असञ्चारा तु या मात्रा स गण्डूषः प्रकीर्तितः", text: "mukhe sañcāryate yā tu sā mātrā kavalaḥ smṛtaḥ asañcārā tu yā mātrā sa gaṇḍūṣaḥ prakīrtitaḥ" },
      { type: "verse", number: "11", sanskrit: "पुनश्च स्वेदमर्दनान्याचरेत् एवमुत्क्लिष्टः कफो वक्त्रं प्रतिपद्यते तावच्च धार्यो यावत् कफपूर्णकपोलता स्रवद्घ्राणनेत्रता भेषजस्य वानुपहतिः कफेन एवं त्रीन् पञ्च सप्त वा गण्डूषान् धारयेत् यावद्वा सम्यग्धूमपीतलिङ्गोत्पत्तिः तस्य स्वास्थ्येन योगं जाड्यरसाज्ञानारुचिप्रसेकोपलेपैरयोगं मुखशोषपाकक्लमारुचिहृदयद्रवस्वरसादकर्णनादैरतियोगमुपलक्षयेत् तेषां यथास्वं प्रतिकुर्वीत", text: "punaśca svedamardanānyācaret evamutkliṣṭaḥ kapho vaktraṃ pratipadyate tāvacca dhāryo yāvat kaphapūrṇakapolatā sravadghrāṇanetratā bheṣajasya vānupahatiḥ kaphena evaṃ trīn pañca sapta vā gaṇḍūṣān dhārayet yāvadvā samyagdhūmapītaliṅgotpattiḥ tasya svāsthyena yogaṃ jāḍyarasājñānāruciprasekopalepairayogaṃ mukhaśoṣapākaklamārucihṛdayadravasvarasādakarṇanādairatiyogamupalakṣayet teṣāṃ yathāsvaṃ pratikurvīta" },
      { type: "verse", number: "12", sanskrit: "प्रतिसारणं तु त्रिविधम् गण्डूषोदितानां द्रव्याणाम् रसक्रिया कल्कश्चूर्णश्च तदभिष्यन्दाधिमन्थगलशुण्डिकादिषु युक्त्या प्रयोज्यम् अतिप्रतिसारणादूषाप्लोषदाहक्लेदशोषादयो भवन्ति", text: "pratisāraṇaṃ tu trividham gaṇḍūṣoditānāṃ dravyāṇām rasakriyā kalkaścūrṇaśca tadabhiṣyandādhimanthagalaśuṇḍikādiṣu yuktyā prayojyam atipratisāraṇādūṣāploṣadāhakledaśoṣādayo bhavanti" },
      { type: "verse", number: "13", sanskrit: "मुखालेपो ऽपि त्रिविधो दोषघ्नो विषघ्नो वर्ण्यश्च त्रिप्रमाणश्चतुर्भागत्रिभागार्धाङ्गुलोत्सेधः न चालिप्तमुखो ऽतिभाष्यहास्यक्रोधशोकरोदनखादनाग्न्यातपदिवास्वप्नान् सेवेत कण्डूत्वक्शोषपीनसदृष्ट्युपघातभयात् न च शुष्यन्नुपेक्षितव्यः शुष्को हि छविं दूषयति तमार्दयित्वापनयेत् आलेपान्ते च मुखमभ्यज्यात्", text: "mukhālepo 'pi trividho doṣaghno viṣaghno varṇyaśca tripramāṇaścaturbhāgatribhāgārdhāṅgulotsedhaḥ na cāliptamukho 'tibhāṣyahāsyakrodhaśokarodanakhādanāgnyātapadivāsvapnān seveta kaṇḍūtvakśoṣapīnasadṛṣṭyupaghātabhayāt na ca śuṣyannupekṣitavyaḥ śuṣko hi chaviṃ dūṣayati tamārdayitvāpanayet ālepānte ca mukhamabhyajyāt" },
      { type: "verse", number: "14", sanskrit: "न तु योज्यो रात्रिजागरितानीर्णदत्तनस्यारुचिहनुग्रहप्रतिश्यायिनाम् सम्यक्प्रयुक्तश्चाकालवलीपलिततिमिरव्यङ्गतिलकादीन् प्रशमयति स्वस्थस्य तु दृष्टिबलं पुण्ड्द्रीककान्तवक्त्रतां च करोति", text: "na tu yojyo rātrijāgaritānīrṇadattanasyārucihanugrahapratiśyāyinām samyakprayuktaścākālavalīpalitatimiravyaṅgatilakādīn praśamayati svasthasya tu dṛṣṭibalaṃ puṇḍdrīkakāntavaktratāṃ ca karoti" },
      { type: "verse", number: "15", sanskrit: "मूर्धतैलं पुनश्चतुर्धा भिद्यते अभ्यङ्गः परिषेकः पिचुर्बस्तिरिति यथोत्तरं ते बलिनः तेष्वभ्यङ्गादयः प्रसिद्धस्वरूपाः", text: "mūrdhatailaṃ punaścaturdhā bhidyate abhyaṅgaḥ pariṣekaḥ picurbastiriti yathottaraṃ te balinaḥ teṣvabhyaṅgādayaḥ prasiddhasvarūpāḥ" },
      { type: "verse", number: "16", sanskrit: "शिरोबस्तिविधिस्तु बस्तिं सुमृदितं द्विमुखं शिरःप्रमाणमाकर्णप्रवेशं द्वादशाङ्गुलविस्तारं कुर्यात् अथ शुद्धतनोः सायं रात्रौ वा स्वभ्यक्तस्विन्नस्य जानुसमसोपाश्रयासनोपविष्टस्य केशान्ते श्लक्ष्णं त्र्यङ्गुलं सुसूक्ष्मेण माषपिष्टेन सद्यः सुखाम्बुमृदितेनोभयतः प्रदिग्धं वस्त्रपट्टं बध्नीयात् ततस्तस्योपरि सन्धाय बस्तिमाकर्णं बस्तिमूलं च दृढमवलीकं समञ्चैलवेणिकया बध्वा पुनर्माषपिष्टेनापरिस्रावि कृत्वा यथाव्याधिदोषदूष्यहितं सिद्धमन्यतमं स्नेहं सुसुखोष्णमासेचयेद्यावत् केशभूमेरुपर्यङ्गुलम् तावच्च धार्यो यावत् कर्णमुखनासास्रुतिर्वेदनोपशमो वा भवति विशेषतो वातजेषु विकारेषु दशमात्रासहस्राणि पित्तरक्तजेष्वष्टौ षट् कफजेषु सहस्रमरोगकर्मणि ततो ऽपनीते स्नेहे विमुच्य बस्तिं शिरसः स्कन्धग्रीवापृष्ठललाटादीन्यनुसुखं मर्दयेत् उष्णाम्बुना स्नातं यथार्हं भोजयेत् स्नेहोक्तं चास्याचारमादिशेत् एवं त्रीणि पञ्च सप्त वा दिनानि योजयेदिति भवति चात्र", text: "śirobastividhistu bastiṃ sumṛditaṃ dvimukhaṃ śiraḥpramāṇamākarṇapraveśaṃ dvādaśāṅgulavistāraṃ kuryāt atha śuddhatanoḥ sāyaṃ rātrau vā svabhyaktasvinnasya jānusamasopāśrayāsanopaviṣṭasya keśānte ślakṣṇaṃ tryaṅgulaṃ susūkṣmeṇa māṣapiṣṭena sadyaḥ sukhāmbumṛditenobhayataḥ pradigdhaṃ vastrapaṭṭaṃ badhnīyāt tatastasyopari sandhāya bastimākarṇaṃ bastimūlaṃ ca dṛḍhamavalīkaṃ samañcailaveṇikayā badhvā punarmāṣapiṣṭenāparisrāvi kṛtvā yathāvyādhidoṣadūṣyahitaṃ siddhamanyatamaṃ snehaṃ susukhoṣṇamāsecayedyāvat keśabhūmeruparyaṅgulam tāvacca dhāryo yāvat karṇamukhanāsāsrutirvedanopaśamo vā bhavati viśeṣato vātajeṣu vikāreṣu daśamātrāsahasrāṇi pittaraktajeṣvaṣṭau ṣaṭ kaphajeṣu sahasramarogakarmaṇi tato 'panīte snehe vimucya bastiṃ śirasaḥ skandhagrīvāpṛṣṭhalalāṭādīnyanusukhaṃ mardayet uṣṇāmbunā snātaṃ yathārhaṃ bhojayet snehoktaṃ cāsyācāramādiśet evaṃ trīṇi pañca sapta vā dināni yojayediti bhavati cātra" },
      { type: "verse", number: "17", sanskrit: "तत्राभ्यङ्गः प्रयोक्तव्यो रौक्ष्यकण्डूमलादिषु अरूंषिकाशिरस्तोददाहपाकव्रणेषु तु", text: "tatrābhyaṅgaḥ prayoktavyo raukṣyakaṇḍūmalādiṣu arūṃṣikāśirastodadāhapākavraṇeṣu tu" },
      { type: "verse", number: "18", sanskrit: "परिषेकः पिचुः केशशातस्फुटनधूपने नेत्रस्तम्भे च बस्तिस्तु प्रसुप्त्यर्दितजागरे नासास्यशोषे तिमिरे शिरोरोगे च दारुणे", text: "pariṣekaḥ picuḥ keśaśātasphuṭanadhūpane netrastambhe ca bastistu prasuptyarditajāgare nāsāsyaśoṣe timire śiroroge ca dāruṇe" },
      { type: "verse", number: "19", sanskrit: "कचशतनसितत्वपिञ्जरत्वं परिपुटनं शिरसः समीररोगान् जयति जनयतीन्द्रियप्रसादं स्वरहनुमूर्धबलं च मूर्धतैलम्", text: "kacaśatanasitatvapiñjaratvaṃ paripuṭanaṃ śirasaḥ samīrarogān jayati janayatīndriyaprasādaṃ svarahanumūrdhabalaṃ ca mūrdhatailam" },
      { type: "verse", number: "20", sanskrit: "धारयेत् पूरणं कर्णे कर्णमूलं विमर्दयन् रुजः स्यान्मार्दवं यावन्मात्राशतमवेदने", text: "dhārayet pūraṇaṃ karṇe karṇamūlaṃ vimardayan rujaḥ syānmārdavaṃ yāvanmātrāśatamavedane" },
      { type: "verse", number: "21", sanskrit: "यावत् पर्येति हस्ताग्रं दक्षिणं जानुमण्डलम् निमेषोन्मेषकालेन समं मात्रा तु सा स्मृता", text: "yāvat paryeti hastāgraṃ dakṣiṇaṃ jānumaṇḍalam nimeṣonmeṣakālena samaṃ mātrā tu sā smṛtā" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 32,
    lang: "sa",
    content: [
      { type: "heading", heading: "Вишеша чикитса — специфическое лечение" },
      { type: "text", text: "Глава 32 Сутрастханы Астанга-санграхи посвящена теме «специфическое лечение». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथात आश्च्योतनाञ्जनविधिमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāta āścyotanāñjanavidhimadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "आश्च्योतनं सर्वाक्षिरोगेष्वाद्य उपक्रमः नानाद्रव्यकल्पनया च रागाश्रुघर्षरुग्दाहतोदभेदपाकशोफकण्डूघ्नम् अव्यकेतेस्वेवंगुणमेव पक्ष्मपरिहारेणाक्षिकेशालेपनम् तञ्च पुनर्बिडालकसंज्ञम्", text: "āścyotanaṃ sarvākṣirogeṣvādya upakramaḥ nānādravyakalpanayā ca rāgāśrugharṣarugdāhatodabhedapākaśophakaṇḍūghnam avyaketesvevaṃguṇameva pakṣmaparihāreṇākṣikeśālepanam tañca punarbiḍālakasaṃjñam" },
      { type: "verse", number: "3", sanskrit: "तयोरकालो रात्रिः कालस्तु सर्वमहर्वेदनोत्पत्तिर्वा निवातशरणशयनस्थस्य विशोध्य नेत्रमपाङ्गे भाजनं कृत्वा वामहस्तेनोन्मील्य दक्षिणहस्तेन शुक्त्यवसक्तया पिचुवर्त्या दशद्वादशाष्टौ वा बिन्दून् कनीनकदेशे द्व्यङ्गुलादवसेचयेत् एवमस्य न बिन्दुपातेनाक्षिताडनाद्रागादयो जायन्ते आश्च्योतितं च मृदुना चैलेन शोधयेत् अन्येन चोष्णाम्बुप्लुतेन वातकफयोः स्वेदयेत् आश्च्योतनं च तयोः कोष्णम् सुशीतं पित्तरक्तविषेषु तत्तु नात्यर्थं तीक्ष्णमुष्णं शीतं प्रभूतमूनमपरिस्रावितं वा योजयेत् अतितीक्ष्णमुष्णं वा दाहरागपाकदृष्टिदौर्बल्यानि करोति अतिशीतं स्तम्भाश्रुघर्षनिस्तोदान् अतिमात्रं कषायवर्त्मतासङ्कोचस्फुरणोन्मीलनप्रवातासहत्वघर्षान् ऊनप्रमाणं न रोगशान्तिम् अपरिस्रुतमश्रुघर्षवेदनाः", text: "tayorakālo rātriḥ kālastu sarvamaharvedanotpattirvā nivātaśaraṇaśayanasthasya viśodhya netramapāṅge bhājanaṃ kṛtvā vāmahastenonmīlya dakṣiṇahastena śuktyavasaktayā picuvartyā daśadvādaśāṣṭau vā bindūn kanīnakadeśe dvyaṅgulādavasecayet evamasya na bindupātenākṣitāḍanādrāgādayo jāyante āścyotitaṃ ca mṛdunā cailena śodhayet anyena coṣṇāmbuplutena vātakaphayoḥ svedayet āścyotanaṃ ca tayoḥ koṣṇam suśītaṃ pittaraktaviṣeṣu tattu nātyarthaṃ tīkṣṇamuṣṇaṃ śītaṃ prabhūtamūnamaparisrāvitaṃ vā yojayet atitīkṣṇamuṣṇaṃ vā dāharāgapākadṛṣṭidaurbalyāni karoti atiśītaṃ stambhāśrugharṣanistodān atimātraṃ kaṣāyavartmatāsaṅkocasphuraṇonmīlanapravātāsahatvagharṣān ūnapramāṇaṃ na rogaśāntim aparisrutamaśrugharṣavedanāḥ" },
      { type: "verse", number: "4", sanskrit: "नेत्रे च प्रणिहितमौषधं कोशसन्धिसिराशृङ्गाटकघ्राणास्यस्रोतांसि गत्वोर्ध्वं प्रवृत्तमपवर्तयति दोषम्", text: "netre ca praṇihitamauṣadhaṃ kośasandhisirāśṛṅgāṭakaghrāṇāsyasrotāṃsi gatvordhvaṃ pravṛttamapavartayati doṣam" },
      { type: "verse", number: "5", sanskrit: "यदा चाश्च्योतनेन पित्तश्लेष्मशोणितोत्थेषु नयनामयेषु संशोधनैर्विशुद्धस्य दूषिकाघनत्वपैच्छिल्यकण्डूद्रेकश्वयथुम्लानतारागविच्छएदैः पक्वलिङ्गमुपलक्षितं भवति तदा नेत्रमात्राश्रये व्याधावञ्जनं प्रयोज्यम् न दोषवेगोदये न चानिर्हृतदोषे तत्र हि दोषोत्क्लेशेन रागादिवृद्धिः अक्षिपाकतिमिरोत्पत्तिश्च", text: "yadā cāścyotanena pittaśleṣmaśoṇitottheṣu nayanāmayeṣu saṃśodhanairviśuddhasya dūṣikāghanatvapaicchilyakaṇḍūdrekaśvayathumlānatārāgavicchaedaiḥ pakvaliṅgamupalakṣitaṃ bhavati tadā netramātrāśraye vyādhāvañjanaṃ prayojyam na doṣavegodaye na cānirhṛtadoṣe tatra hi doṣotkleśena rāgādivṛddhiḥ akṣipākatimirotpattiśca" },
      { type: "verse", number: "6", sanskrit: "तत्तु लेखनं रोपणं स्नेहनं प्रसादनमिति चतुर्विधं भवति तत्राम्लादिभी रसैः पञ्चभिः शुक्लार्मादिषु लेखनम्", text: "tattu lekhanaṃ ropaṇaṃ snehanaṃ prasādanamiti caturvidhaṃ bhavati tatrāmlādibhī rasaiḥ pañcabhiḥ śuklārmādiṣu lekhanam" },
      { type: "verse", number: "7", sanskrit: "तिक्तकषायैः सस्नेहैरभिष्यन्देषु रोपणम्", text: "tiktakaṣāyaiḥ sasnehairabhiṣyandeṣu ropaṇam" },
      { type: "verse", number: "8", sanskrit: "सर्पादिवसादिभिर्वाततिमिरादिषु स्नेहनम्", text: "sarpādivasādibhirvātatimirādiṣu snehanam" },
      { type: "verse", number: "9", sanskrit: "स्वादुशीतैः सस्नेहैरभिष्यन्दान्ते सूर्योपरागाशनिविद्युत्सम्पातभूतांपिशाचात्यद्भुतदर्शनाद्युपहतायां दृष्टौ स्वस्थवृत्ते च प्रसादनम्", text: "svāduśītaiḥ sasnehairabhiṣyandānte sūryoparāgāśanividyutsampātabhūtāṃpiśācātyadbhutadarśanādyupahatāyāṃ dṛṣṭau svasthavṛtte ca prasādanam" },
      { type: "verse", number: "10", sanskrit: "प्रसादन एव चूर्णस्तीक्ष्णाञ्जनाभिसन्तप्ते चक्षुषि प्रयुज्यमानः प्रत्यञ्जनसंज्ञां लभते षड्विधं वा प्रतिरसभेदादञ्जनम् द्विविधमेव वा तीक्ष्णं मृदु च", text: "prasādana eva cūrṇastīkṣṇāñjanābhisantapte cakṣuṣi prayujyamānaḥ pratyañjanasaṃjñāṃ labhate ṣaḍvidhaṃ vā pratirasabhedādañjanam dvividhameva vā tīkṣṇaṃ mṛdu ca" },
      { type: "verse", number: "11", sanskrit: "कल्पना तु त्रिविधा पिण्डो रसक्रिया चूर्णश्च यथापूर्वं ते बलिनस्तस्मात् प्रबलमध्याबलेष्वामयेषुक्रमात्तान् प्रयोजयेत् तत्र पिण्डो हरेणुमात्रस्तीक्ष्णस्य रसक्रिया विडङ्गमात्रा तद्द्विगुणा मृदोः चूर्णो द्विशलाकः मृदोस्त्रिशलाकः", text: "kalpanā tu trividhā piṇḍo rasakriyā cūrṇaśca yathāpūrvaṃ te balinastasmāt prabalamadhyābaleṣvāmayeṣukramāttān prayojayet tatra piṇḍo hareṇumātrastīkṣṇasya rasakriyā viḍaṅgamātrā taddviguṇā mṛdoḥ cūrṇo dviśalākaḥ mṛdostriśalākaḥ" },
      { type: "verse", number: "12", sanskrit: "पात्रे तु कुर्यात् सौवर्णे मधुरम् राजते ऽम्लम् मेषशृङ्गमये लवणम् कांस्ये तिक्तम् वैदूर्यमये ऽश्ममये वा कटुकम् ताम्रमय आयसे वा कषायम् नलप्लक्षपद्मस्फटिकशङ्खाद्यन्यतमे शीतम् एवमव्यापन्नगुणं भवति वर्तिघर्षणार्था च शिलातिश्लक्ष्णा निम्नमध्यानुद्गारिणी पञ्चाङ्गुलायता त्र्यङ्गुलविस्तीर्णा", text: "pātre tu kuryāt sauvarṇe madhuram rājate 'mlam meṣaśṛṅgamaye lavaṇam kāṃsye tiktam vaidūryamaye 'śmamaye vā kaṭukam tāmramaya āyase vā kaṣāyam nalaplakṣapadmasphaṭikaśaṅkhādyanyatame śītam evamavyāpannaguṇaṃ bhavati vartigharṣaṇārthā ca śilātiślakṣṇā nimnamadhyānudgāriṇī pañcāṅgulāyatā tryaṅgulavistīrṇā" },
      { type: "verse", number: "13", sanskrit: "शलाकाः पञ्च कनकरजतताम्रलोहोद्भवा अङ्गुली च तत्राद्ये प्रसादने ऽञ्जने स्नेहने च मध्या लेखने अन्त्ये रोपणे मृदुत्वादङ्गुल्यत्र प्रधानतमा अतः सरुजे ऽक्ष्णि सैव प्रयोज्या शेषा दशाङ्गुला राजमाषस्थूलाः सुश्लक्ष्णास्तनुमध्या मुखयोर्मुकुलाकाराः कलायपरिमण्डलाश्च", text: "śalākāḥ pañca kanakarajatatāmralohodbhavā aṅgulī ca tatrādye prasādane 'ñjane snehane ca madhyā lekhane antye ropaṇe mṛdutvādaṅgulyatra pradhānatamā ataḥ saruje 'kṣṇi saiva prayojyā śeṣā daśāṅgulā rājamāṣasthūlāḥ suślakṣṇāstanumadhyā mukhayormukulākārāḥ kalāyaparimaṇḍalāśca" },
      { type: "verse", number: "14", sanskrit: "अथाञ्जनं नातिशीतोष्णाभ्रवातायां वेलायामुभयकालं च योज्यम् तथा सततं नैव वा", text: "athāñjanaṃ nātiśītoṣṇābhravātāyāṃ velāyāmubhayakālaṃ ca yojyam tathā satataṃ naiva vā" },
      { type: "verse", number: "15", sanskrit: "सरुजे चाक्ष्णि प्राक् पश्चादितरस्मिन् अन्यथाञ्जनोद्वेगसङ्कुचिते ऽन्तः सम्यगौषधं नानुप्रविशेत् ततैवमतिशीतादिषु च यथास्वं दोषोत्क्लेशाद्विकारपरिवृद्धिः", text: "saruje cākṣṇi prāk paścāditarasmin anyathāñjanodvegasaṅkucite 'ntaḥ samyagauṣadhaṃ nānupraviśet tataivamatiśītādiṣu ca yathāsvaṃ doṣotkleśādvikāraparivṛddhiḥ" },
      { type: "verse", number: "16", sanskrit: "न च योज्यं क्रुद्धभीतशङ्कितशोकितश्रान्ताशितमात्रविरिक्तधूममद्यपीतदत्तनस्यरात्रिजागरितवेगितरुदितपिपासित ज्वरितच्छर्दितार्ततान्तनेत्राभिहतशिरोरुजार्तशिरःस्नातानुदितादित्येषु एष्वञ्जनादूष्मोर्ध्वगः संरम्भाश्रुवेदनाविलत्वोषारागदूषिकानिस्तोदकृछ्रोन्मीलनश्वयथुशुक्रतिमिरादीन् जनयेत्", text: "na ca yojyaṃ kruddhabhītaśaṅkitaśokitaśrāntāśitamātraviriktadhūmamadyapītadattanasyarātrijāgaritavegitaruditapipāsita jvaritaccharditārtatāntanetrābhihataśirorujārtaśiraḥsnātānuditādityeṣu eṣvañjanādūṣmordhvagaḥ saṃrambhāśruvedanāvilatvoṣārāgadūṣikānistodakṛchronmīlanaśvayathuśukratimirādīn janayet" },
      { type: "verse", number: "17", sanskrit: "अथ समसुखोपविष्टस्योपविष्टो वामांगुष्ठेन वर्त्मोत्तरमुत्क्षिप्य कृष्णभागस्याधःकनीनकादपाङ्गं यावदञ्जनं नयेदनल्पमप्रभूतमनतितक्ष्णिमनच्छमसान्द्रमकर्कशमद्रुतमविलम्बितमतिर्यग्दृष्ट्यकम्पितमघट्टितमनात्रान्तं च चूर्णे तु गतागतं कुर्यात् अन्यथा हि रागाश्रुशुक्राद्युत्पत्तिः ततो ऽञ्जनानुगमनायानुन्मीलयन् शनैश्शनैरन्तश्चक्षुः सञ्चारयेत् एवमक्ष्यनुगच्छति वर्त्मनी किञ्चिच्चालयेत् न तु सहसोन्मेषणनिष्पीडनप्रक्षालनानि कुर्यात् बाष्पोत्क्लिष्टदोषस्तम्भभयात् अपि च", text: "atha samasukhopaviṣṭasyopaviṣṭo vāmāṃguṣṭhena vartmottaramutkṣipya kṛṣṇabhāgasyādhaḥkanīnakādapāṅgaṃ yāvadañjanaṃ nayedanalpamaprabhūtamanatitakṣṇimanacchamasāndramakarkaśamadrutamavilambitamatiryagdṛṣṭyakampitamaghaṭṭitamanātrāntaṃ ca cūrṇe tu gatāgataṃ kuryāt anyathā hi rāgāśruśukrādyutpattiḥ tato 'ñjanānugamanāyānunmīlayan śanaiśśanairantaścakṣuḥ sañcārayet evamakṣyanugacchati vartmanī kiñciccālayet na tu sahasonmeṣaṇaniṣpīḍanaprakṣālanāni kuryāt bāṣpotkliṣṭadoṣastambhabhayāt api ca" },
      { type: "verse", number: "18", sanskrit: "अपेतौषधसंरम्भं निर्वृतं नयनं यदा व्याधिदोषर्तुयोग्याभिरद्भिः प्रक्षालयेत्तदा", text: "apetauṣadhasaṃrambhaṃ nirvṛtaṃ nayanaṃ yadā vyādhidoṣartuyogyābhiradbhiḥ prakṣālayettadā" },
      { type: "verse", number: "19", sanskrit: "सचैलेनाथ नयनं सव्याङ्गुष्ठेन दक्षिणम् ऊर्ध्ववर्त्मनि सङ्गृह्य शनैः शोध्यं समन्ततः", text: "sacailenātha nayanaṃ savyāṅguṣṭhena dakṣiṇam ūrdhvavartmani saṅgṛhya śanaiḥ śodhyaṃ samantataḥ" },
      { type: "verse", number: "20", sanskrit: "दक्षिणाङ्गुष्ठकेनैवं शोध्यं सव्यं च लोचनम् वर्त्मप्रप्ताञ्जनाद्दोषो रोगान् कुर्यादतो ऽन्यथा", text: "dakṣiṇāṅguṣṭhakenaivaṃ śodhyaṃ savyaṃ ca locanam vartmapraptāñjanāddoṣo rogān kuryādato 'nyathā" },
      { type: "verse", number: "21", sanskrit: "तीक्ष्णाञ्जनान्ते चैनं धूमं पाययेत् यस्याञ्जिते कण्डूजाड्योपदेहाः स्युः तस्य तीक्ष्णमञ्जनं धूमं वा पुनरवचारयेत् एतदेव दुर्विरिक्ताक्षिलक्षणं साधनं च अतिविरेकात् सन्तापनिस्तोदशूलस्तम्भघर्षाश्रुदारुणप्रतिबोधकषायवर्त्मताशिरोरुग्दृष्टिदौर्बल्यानि तत्र शीतमाश्च्योतनं प्रत्यञ्जनं वा सम्यग्विरेकाद्यथास्वमामयोपशमः सुखोन्मीलननिमीलनवातातपसहत्वानि चेति भवति चात्र रोपणादिष्वपि तथा योगादीननुचिन्तयेत् दोषोदयानुसारेण प्रतिकुर्वीत तेषु च", text: "tīkṣṇāñjanānte cainaṃ dhūmaṃ pāyayet yasyāñjite kaṇḍūjāḍyopadehāḥ syuḥ tasya tīkṣṇamañjanaṃ dhūmaṃ vā punaravacārayet etadeva durviriktākṣilakṣaṇaṃ sādhanaṃ ca ativirekāt santāpanistodaśūlastambhagharṣāśrudāruṇapratibodhakaṣāyavartmatāśirorugdṛṣṭidaurbalyāni tatra śītamāścyotanaṃ pratyañjanaṃ vā samyagvirekādyathāsvamāmayopaśamaḥ sukhonmīlananimīlanavātātapasahatvāni ceti bhavati cātra ropaṇādiṣvapi tathā yogādīnanucintayet doṣodayānusāreṇa pratikurvīta teṣu ca" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 33,
    lang: "sa",
    content: [
      { type: "heading", heading: "Шалья удхарана — удаление инородных тел" },
      { type: "text", text: "Глава 33 Сутрастханы Астанга-санграхи посвящена теме «удаление инородных тел». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातस्तर्पणपुटपाकविधिं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātastarpaṇapuṭapākavidhiṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "यन्नयनं परिताम्यति परिसुष्कं रूक्षं स्तब्धं जिह्मं निम्नमाविलमवनद्धं शीर्णपक्ष्म तथा कृच्छ्रोन्मीलसिरोत्पातसिराहर्षर्जुनशुष्कतिमिराभिष्यन्दाधिमन्थान्यतोवातवातपर्ययशुष्काल्पशोफादिरोगातुरमपगतरागाश्रुदूषिकावेदनं तत्र तर्पणं योजयेत् न त्वशान्तोपद्रवे ऽक्ष्णि नातिशीतोष्णवर्षदुर्दिने न नस्यानर्हेषु च तद्वत् पुटपाकमपि", text: "yannayanaṃ paritāmyati parisuṣkaṃ rūkṣaṃ stabdhaṃ jihmaṃ nimnamāvilamavanaddhaṃ śīrṇapakṣma tathā kṛcchronmīlasirotpātasirāharṣarjunaśuṣkatimirābhiṣyandādhimanthānyatovātavātaparyayaśuṣkālpaśophādirogāturamapagatarāgāśrudūṣikāvedanaṃ tatra tarpaṇaṃ yojayet na tvaśāntopadrave 'kṣṇi nātiśītoṣṇavarṣadurdine na nasyānarheṣu ca tadvat puṭapākamapi" },
      { type: "verse", number: "3", sanskrit: "अथ दिवसस्याष्टमे भागे गते शेषे वा निवातातपरयोधूमे कृतनीलपीतान्यतरयवनिके वेश्मनि जीर्णभक्तस्य सुखशयनगतस्य उत्तानस्य मृदितमाषपिष्टकल्केन नेत्रकोशाद् बहिर्द्व्यङ्गुलोच्छ्रायाधारौ परिमण्डलावसम्बादौ समावपरिस्राविणौ कृत्वा तत्रोष्णोदकप्रविलीनं निमीलिते नेत्रे यथास्वौषधविपक्वं क्षीरं सर्पिः सर्पिर्मण्डं वावसेचयेत् यावन्निमग्नान्यक्षिपक्ष्माणि भ्रूरोमाणि च ततः शनैरस्योन्मेषमाचरतो मात्रां गणयेत् वर्त्मजेषु विकारेषु शतं सन्धिजेषु त्रीणि शुक्लजेषु पञ्च कृष्णजेषु सप्त दृष्टिजेष्वष्टौ सहस्रमधिमन्थेषु प्रतिदोषं तु वाते सहस्रं पित्ते षट् शतानि कफे पञ्च स्वस्थकर्मणि च", text: "atha divasasyāṣṭame bhāge gate śeṣe vā nivātātaparayodhūme kṛtanīlapītānyatarayavanike veśmani jīrṇabhaktasya sukhaśayanagatasya uttānasya mṛditamāṣapiṣṭakalkena netrakośād bahirdvyaṅgulocchrāyādhārau parimaṇḍalāvasambādau samāvaparisrāviṇau kṛtvā tatroṣṇodakapravilīnaṃ nimīlite netre yathāsvauṣadhavipakvaṃ kṣīraṃ sarpiḥ sarpirmaṇḍaṃ vāvasecayet yāvannimagnānyakṣipakṣmāṇi bhrūromāṇi ca tataḥ śanairasyonmeṣamācarato mātrāṃ gaṇayet vartmajeṣu vikāreṣu śataṃ sandhijeṣu trīṇi śuklajeṣu pañca kṛṣṇajeṣu sapta dṛṣṭijeṣvaṣṭau sahasramadhimantheṣu pratidoṣaṃ tu vāte sahasraṃ pitte ṣaṭ śatāni kaphe pañca svasthakarmaṇi ca" },
      { type: "verse", number: "4", sanskrit: "ततो ऽस्यापाङ्गदेशे शलाकया द्वारं कृत्वा स्नेहं भाजने स्रावयेत् आधारौ चापनीय यवकल्केनाक्षिकोशौ प्रमृज्य स्नेहेरितकफोपशान्तये यथार्हं धूमं पाययेत् सुखोदकप्रक्षालितमुखं चैनं यथाव्याधि भोजयेत् आतपाकाशभास्वद्दर्शनानि च परिहरेत्", text: "tato 'syāpāṅgadeśe śalākayā dvāraṃ kṛtvā snehaṃ bhājane srāvayet ādhārau cāpanīya yavakalkenākṣikośau pramṛjya sneheritakaphopaśāntaye yathārhaṃ dhūmaṃ pāyayet sukhodakaprakṣālitamukhaṃ cainaṃ yathāvyādhi bhojayet ātapākāśabhāsvaddarśanāni ca pariharet" },
      { type: "verse", number: "5", sanskrit: "अनेन विधिना प्रत्यहं वायावेकान्तरं रक्तपित्तयोद्र्व्यन्तरं कफे स्वस्थे च यथादोषोत्कर्षं संसर्गसन्निपातयोः एवमेकाहं त्र्यहं पञ्चाहं वा कुर्यादातृप्तेर्वा तृप्तातृप्तातितृप्तलिङ्गानि तु क्रमात् स्वास्थ्यवातकफविकारैरादिशेत्", text: "anena vidhinā pratyahaṃ vāyāvekāntaraṃ raktapittayodrvyantaraṃ kaphe svasthe ca yathādoṣotkarṣaṃ saṃsargasannipātayoḥ evamekāhaṃ tryahaṃ pañcāhaṃ vā kuryādātṛptervā tṛptātṛptātitṛptaliṅgāni tu kramāt svāsthyavātakaphavikārairādiśet" },
      { type: "verse", number: "6", sanskrit: "यदा तु सम्यग्योगप्राप्तं तर्पणं भवति तदा तद्विधेष्वेव रोगेषु पुटपाकं विदध्यात् स त्रिविधः स्नेहनो लेखनः प्रसादनश्च", text: "yadā tu samyagyogaprāptaṃ tarpaṇaṃ bhavati tadā tadvidheṣveva rogeṣu puṭapākaṃ vidadhyāt sa trividhaḥ snehano lekhanaḥ prasādanaśca" },
      { type: "verse", number: "7", sanskrit: "तत्र स्नेहनमानूपसाधारणमांसमेदोमज्जवसाभिः तथा स्वादुद्रव्यैश्च क्षीरपिष्टै रूक्षे ऽक्ष्णि प्रयोजयेत्", text: "tatra snehanamānūpasādhāraṇamāṃsamedomajjavasābhiḥ tathā svādudravyaiśca kṣīrapiṣṭai rūkṣe 'kṣṇi prayojayet" },
      { type: "verse", number: "8", sanskrit: "लेखनं जाङ्गलमृगपक्षिमांसयकृद्भिर्मुक्ताप्रवालशङ्खताम्रायस्समुद्रफेनकासीसस्रोतोजसैन्धवादिभिश्च लेखनद्रव्यैर्दधिमस्तुमधुपिष्टैः स्निग्धे", text: "lekhanaṃ jāṅgalamṛgapakṣimāṃsayakṛdbhirmuktāpravālaśaṅkhatāmrāyassamudraphenakāsīsasrotojasaindhavādibhiśca lekhanadravyairdadhimastumadhupiṣṭaiḥ snigdhe" },
      { type: "verse", number: "9", sanskrit: "प्रसादनीयं तु जाङ्गलमृगपक्षियकृद्धृदयमज्जवसाभिर्मधुरद्रव्यैश्च स्त्रीस्तन्यक्षीराज्यपिष्टैः स तु वातपित्तरक्तदृष्टिदौर्बल्यव्रणनाशनः कफविरुद्धः", text: "prasādanīyaṃ tu jāṅgalamṛgapakṣiyakṛddhṛdayamajjavasābhirmadhuradravyaiśca strīstanyakṣīrājyapiṣṭaiḥ sa tu vātapittaraktadṛṣṭidaurbalyavraṇanāśanaḥ kaphaviruddhaḥ" },
      { type: "verse", number: "10", sanskrit: "अथ बिल्वमात्रं वेशवारीकृतं मांसपिण्डं तन्मात्रेणैवौषधपिण्डेन संसृज्यैरण्डवटोत्पलपत्रैः स्नेहनादिषु क्रमाद्वेष्टयित्वा कुशमुञ्जसूत्रान्यतमेन बध्नीयात् मृत्प्रलेपनं चात्र द्व्यङ्गुलोत्सेधं कृत्वा धवधन्वमधूकन्यग्रोधकाश्मर्यराजादनार्जुननक्तमालपाटलीना मन्यतमैः काष्ठैः शकृता वा गोमहिषयोः पचेत् अग्निवर्णं चैनमपनीय विगतमृत्सूत्रपत्रं कृत्वा वस्त्रेण पीडयेत् तेन रसेन सायं तर्पणवत् पूरयेन्नेत्रे धारयेच्च स्नेहने शतद्वयं मात्राणां लेखने शतं प्रसादने त्रीणि शतानि", text: "atha bilvamātraṃ veśavārīkṛtaṃ māṃsapiṇḍaṃ tanmātreṇaivauṣadhapiṇḍena saṃsṛjyairaṇḍavaṭotpalapatraiḥ snehanādiṣu kramādveṣṭayitvā kuśamuñjasūtrānyatamena badhnīyāt mṛtpralepanaṃ cātra dvyaṅgulotsedhaṃ kṛtvā dhavadhanvamadhūkanyagrodhakāśmaryarājādanārjunanaktamālapāṭalīnā manyatamaiḥ kāṣṭhaiḥ śakṛtā vā gomahiṣayoḥ pacet agnivarṇaṃ cainamapanīya vigatamṛtsūtrapatraṃ kṛtvā vastreṇa pīḍayet tena rasena sāyaṃ tarpaṇavat pūrayennetre dhārayecca snehane śatadvayaṃ mātrāṇāṃ lekhane śataṃ prasādane trīṇi śatāni" },
      { type: "verse", number: "11", sanskrit: "तप्रणवदेव धूमपानं प्रसादनवर्ज्यम् सुखोष्णौ च पूर्वौ शीतः प्रसादनः पुटपाकस्त्वेकाहं द्व्यहं त्र्यहं वा योज्यः द्विगुणश्च तर्पणपुटपाकयोः परिहारः बद्धाक्षैश्च मालतीमल्लिकाकुसुमैर्निवसेत् तथा पक्वातिसारे ऽपि पुटपाकस्यायमेव विधिरिति भवति चात्र श्लोकः", text: "tapraṇavadeva dhūmapānaṃ prasādanavarjyam sukhoṣṇau ca pūrvau śītaḥ prasādanaḥ puṭapākastvekāhaṃ dvyahaṃ tryahaṃ vā yojyaḥ dviguṇaśca tarpaṇapuṭapākayoḥ parihāraḥ baddhākṣaiśca mālatīmallikākusumairnivaset tathā pakvātisāre 'pi puṭapākasyāyameva vidhiriti bhavati cātra ślokaḥ" },
      { type: "verse", number: "12", sanskrit: "सेके ऽञ्जने तर्पणे च पुटपाके च ये गदाः जायेरन् विधिविभ्रंशाद्यथास्वं तान् प्रसाधयेत्", text: "seke 'ñjane tarpaṇe ca puṭapāke ca ye gadāḥ jāyeran vidhivibhraṃśādyathāsvaṃ tān prasādhayet" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 34,
    lang: "sa",
    content: [
      { type: "heading", heading: "Врана паришека — промывание ран" },
      { type: "text", text: "Глава 34 Сутрастханы Астанга-санграхи посвящена теме «промывание ран». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो यन्त्रशस्त्रविधिं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto yantraśastravidhiṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "मनःशरीराबाधकराणि शल्यानि तेषां नानाविधानां शल्यानां नानादेशनिविष्टानामाहरणे ऽभ्युपायो यन्त्राण्यर्शोभगन्दरादिषु शस्त्रक्षाराग्न्यवचारणे शेषाङ्गरक्षणे च तथा बस्तिप्रणयनादौ शृङ्गालाबुघटिकादयो जाम्बवौष्ठादीनि अन्यान्यपि चानेकरूपाण्यनेककर्माणि स्वस्थातुरोपकरणानि अतः कर्मवशात्तेषामियत्तावधारणमशक्यम्", text: "manaḥśarīrābādhakarāṇi śalyāni teṣāṃ nānāvidhānāṃ śalyānāṃ nānādeśaniviṣṭānāmāharaṇe 'bhyupāyo yantrāṇyarśobhagandarādiṣu śastrakṣārāgnyavacāraṇe śeṣāṅgarakṣaṇe ca tathā bastipraṇayanādau śṛṅgālābughaṭikādayo jāmbavauṣṭhādīni anyānyapi cānekarūpāṇyanekakarmāṇi svasthāturopakaraṇāni ataḥ karmavaśātteṣāmiyattāvadhāraṇamaśakyam" },
      { type: "verse", number: "3", sanskrit: "अन्ये पुनरेकोत्तरं यन्त्रशतमित्याचक्षते इह पुनः समासतः षोढा निर्दिश्यन्ते तद्यथा स्वस्तिकसन्दंशतालनाडीशलाकाख्यान्यनुयन्त्राणि च", text: "anye punarekottaraṃ yantraśatamityācakṣate iha punaḥ samāsataḥ ṣoḍhā nirdiśyante tadyathā svastikasandaṃśatālanāḍīśalākākhyānyanuyantrāṇi ca" },
      { type: "verse", number: "4", sanskrit: "तत्र स्वस्तिकयन्त्राणि कङ्कसिंहगृध्रकुररादिविविधव्यालमुखान्याकारानुगताभिधानानि प्रायशो लौहान्यष्टादशाङ्गुलानि मसूराकारप्रान्तैः कण्ठे कीलैरवबद्धानि मूले ऽङ्कुशवदावृत्तवारङ्गाण्यस्थिविनष्टशल्योद्धरणार्थानि तेषां सिंहव्याघ्रभुजङ्गमकरादिमुखानि दृश्यवारङ्गेषु शल्येषु प्रयोजयेत् इतरेषु तु यथायोगं व्रणाकारानुरोधेन कङ्ककाककुररादिमुखानि", text: "tatra svastikayantrāṇi kaṅkasiṃhagṛdhrakurarādivividhavyālamukhānyākārānugatābhidhānāni prāyaśo lauhānyaṣṭādaśāṅgulāni masūrākāraprāntaiḥ kaṇṭhe kīlairavabaddhāni mūle 'ṅkuśavadāvṛttavāraṅgāṇyasthivinaṣṭaśalyoddharaṇārthāni teṣāṃ siṃhavyāghrabhujaṅgamakarādimukhāni dṛśyavāraṅgeṣu śalyeṣu prayojayet itareṣu tu yathāyogaṃ vraṇākārānurodhena kaṅkakākakurarādimukhāni" },
      { type: "verse", number: "5", sanskrit: "सनिबन्धनो निर्निबन्धनश्च षोडशाङ्गुलौ सन्दंशौ द्वौ भवतः तौ त्वङ्मांससिरास्नायुगतशल्योद्धरणार्थमुपदिश्येते तथान्यः सन्दंशः षडङ्गुलो ऽर्धाङ्गुलविस्तृतो वक्रद्विबाहुरङ्गुष्ठाङ्गुलिप्रान्तसमागमाकृतिः सूक्ष्मशल्याक्षिपक्ष्मव्रणाधिमांसाहरणे", text: "sanibandhano nirnibandhanaśca ṣoḍaśāṅgulau sandaṃśau dvau bhavataḥ tau tvaṅmāṃsasirāsnāyugataśalyoddharaṇārthamupadiśyete tathānyaḥ sandaṃśaḥ ṣaḍaṅgulo 'rdhāṅgulavistṛto vakradvibāhuraṅguṣṭhāṅguliprāntasamāgamākṛtiḥ sūkṣmaśalyākṣipakṣmavraṇādhimāṃsāharaṇe" },
      { type: "verse", number: "6", sanskrit: "तद्वच्च मुचुटी सा तु सूक्ष्मदन्तर्जुर्द्विभुजा मूले रुचकनद्धा वलयपीडनात् छिन्नार्मशेषगम्भीरव्रणाधिमांसाहरणे", text: "tadvacca mucuṭī sā tu sūkṣmadantarjurdvibhujā mūle rucakanaddhā valayapīḍanāt chinnārmaśeṣagambhīravraṇādhimāṃsāharaṇe" },
      { type: "verse", number: "7", sanskrit: "तालयन्त्रे अपि द्वे द्वादशाङ्गुले मत्स्यगलतालकवदेकतालकद्वितालके कर्णनाडीशल्याहरणार्थे", text: "tālayantre api dve dvādaśāṅgule matsyagalatālakavadekatālakadvitālake karṇanāḍīśalyāharaṇārthe" },
      { type: "verse", number: "8", sanskrit: "नाडीयन्त्राणि सुषिराण्यनेकप्रकाराण्यनेकप्रयोजनान्येनकतोमुखान्येकतोमुखानि च भवन्ति स्रोतोगतशल्यदर्शनार्थमाहरणार्थं क्रियासौकर्यार्थमाचूषणार्थं चेति तानि स्रोतोद्वारपरिणाहानि तथायोगप्रदीर्घाणि च कुर्यात्", text: "nāḍīyantrāṇi suṣirāṇyanekaprakārāṇyanekaprayojanānyenakatomukhānyekatomukhāni ca bhavanti srotogataśalyadarśanārthamāharaṇārthaṃ kriyāsaukaryārthamācūṣaṇārthaṃ ceti tāni srotodvārapariṇāhāni tathāyogapradīrghāṇi ca kuryāt" },
      { type: "verse", number: "9", sanskrit: "कण्ठशल्यदर्शनार्थं नाडीं दशाङ्गुलायतां पञ्चाङ्गुलपरिणाहां द्विकर्णस्य तु वारङ्गस्य सङ्ग्रहार्थं त्रिच्छिद्रमुखां नाडीं तत्प्रमाणतः कुर्यात् तथा चतुष्कर्णस्य पञ्चच्छिद्रमुखाम् शल्यनिर्घातिनीं तु पद्मकर्णिकाकारशीर्षां द्वादशाङ्गुलां त्र्यङ्गुलसुषिराम्", text: "kaṇṭhaśalyadarśanārthaṃ nāḍīṃ daśāṅgulāyatāṃ pañcāṅgulapariṇāhāṃ dvikarṇasya tu vāraṅgasya saṅgrahārthaṃ tricchidramukhāṃ nāḍīṃ tatpramāṇataḥ kuryāt tathā catuṣkarṇasya pañcacchidramukhām śalyanirghātinīṃ tu padmakarṇikākāraśīrṣāṃ dvādaśāṅgulāṃ tryaṅgulasuṣirām" },
      { type: "verse", number: "10", sanskrit: "आर्शोयन्त्रं त्रिविधम् ताम्रायोहैमं दान्तं शार्ङ्गं वार्क्षं वा गोस्तनाकारं चतुरङ्गुलायतं हस्ततलायतमेकं पञ्चाङ्गुलानि परिणाहेन पुंसां षङ्गुलानि स्त्रीणाम् द्विच्छिद्रं दर्शनार्थमेकच्छिद्रं कर्मणि तथा हि सुखेन दर्शनं शस्त्रक्षाराग्न्यनतिक्रमश्च छिद्रं तु त्र्यङ्गुलायतमङ्गुष्ठोदरविस्तारम् यदङ्गुलमवशिष्टं तस्याधो ऽर्धाङ्गुलमुपरि तथार्धाङ्गुलोच्छ्रितोद्वृत्तकर्णिकम् तृतीयं तु तादृशमेव शम्याख्यं पार्श्वच्छिद्ररहितं पीडनार्थम् भगन्दरे तु छिद्रादूर्ध्वमोष्ठमपनीय कुर्वीत तद्वच्च घ्राणार्शो ऽर्बुदयन्त्रं नाड्याकारं द्व्यङ्गुलायतमेकच्छिद्रं प्रदेशिनीपरीणाहम्", text: "ārśoyantraṃ trividham tāmrāyohaimaṃ dāntaṃ śārṅgaṃ vārkṣaṃ vā gostanākāraṃ caturaṅgulāyataṃ hastatalāyatamekaṃ pañcāṅgulāni pariṇāhena puṃsāṃ ṣaṅgulāni strīṇām dvicchidraṃ darśanārthamekacchidraṃ karmaṇi tathā hi sukhena darśanaṃ śastrakṣārāgnyanatikramaśca chidraṃ tu tryaṅgulāyatamaṅguṣṭhodaravistāram yadaṅgulamavaśiṣṭaṃ tasyādho 'rdhāṅgulamupari tathārdhāṅgulocchritodvṛttakarṇikam tṛtīyaṃ tu tādṛśameva śamyākhyaṃ pārśvacchidrarahitaṃ pīḍanārtham bhagandare tu chidrādūrdhvamoṣṭhamapanīya kurvīta tadvacca ghrāṇārśo 'rbudayantraṃ nāḍyākāraṃ dvyaṅgulāyatamekacchidraṃ pradeśinīparīṇāham" },
      { type: "verse", number: "11", sanskrit: "तथाङ्गुलीत्राणकमङ्गुलीप्रवेशितं किञ्चित्स्थूलवृत्तौष्ठमूर्ध्वाधश्छिद्रं गोस्तनाकृति चतुरङ्गुलं दान्तं शार्ङ्गं वार्क्षं वा तद्दृढेन सूत्रेण मणिबन्धप्रतिबद्धमास्यविस्रावणे योज्यम्", text: "tathāṅgulītrāṇakamaṅgulīpraveśitaṃ kiñcitsthūlavṛttauṣṭhamūrdhvādhaśchidraṃ gostanākṛti caturaṅgulaṃ dāntaṃ śārṅgaṃ vārkṣaṃ vā taddṛḍhena sūtreṇa maṇibandhapratibaddhamāsyavisrāvaṇe yojyam" },
      { type: "verse", number: "12", sanskrit: "योनिव्रणदर्शने यन्त्रं षोडशाङ्गुलम् मध्ये सुषिरं चतुर्भित्तं चतुश्शलाकं सञ्चारिण्यामुद्रयोर्ध्वं निबद्धमुत्पलमुकुलवक्त्रं मूले शलाकाक्रमणादूर्ध्वविकासि च नाडीव्रणप्रक्षालनाभ्यञ्जनयन्त्रे षडङ्गुले बस्तियन्त्राकारे मुखतो ऽकर्णिके मूलमुखयोरङ्गुष्ठकलायप्रवेशस्रोतसी दकोदरे नाडीमुभयतोद्वारां पिच्छनाडीं वा युञ्ज्यात् स्नेहबस्त्युत्तरबस्तिप्रधमनधूममूत्रवृद्धिनिरुद्धमणिप्रभृतिषु यथास्वमेव यन्त्राण्युक्तानि", text: "yonivraṇadarśane yantraṃ ṣoḍaśāṅgulam madhye suṣiraṃ caturbhittaṃ catuśśalākaṃ sañcāriṇyāmudrayordhvaṃ nibaddhamutpalamukulavaktraṃ mūle śalākākramaṇādūrdhvavikāsi ca nāḍīvraṇaprakṣālanābhyañjanayantre ṣaḍaṅgule bastiyantrākāre mukhato 'karṇike mūlamukhayoraṅguṣṭhakalāyapraveśasrotasī dakodare nāḍīmubhayatodvārāṃ picchanāḍīṃ vā yuñjyāt snehabastyuttarabastipradhamanadhūmamūtravṛddhiniruddhamaṇiprabhṛtiṣu yathāsvameva yantrāṇyuktāni" },
      { type: "verse", number: "13", sanskrit: "शृङ्गं तु ह्रस्वमध्यदीर्घमष्टादशद्वादशाङ्गुलायतं त्र्यङ्गुलप्रवेशमुखमग्रे सर्षपोपलच्छिद्रं तनुचर्मनद्धं चूचुकाकारमुखं च तद्वातविषरक्ताम्बुदुष्टस्तन्यचूषणार्थम् श्लेष्मरक्ताचूषणार्थस्त्वलाबुः स द्वादशाङ्गुलदीर्घो ऽष्टादशाङ्गुलपरिणाहस्त्रिचतुरङ्गुलवृत्तसमुच्छ्रितमुखः परिवेष्टितदीप्तकुशबल्वजपिचुगर्भश्च प्रयोज्यः तद्वदेव च मानकर्माभ्यां घटी सा तु गुल्मोन्नमनविलयनार्थं च", text: "śṛṅgaṃ tu hrasvamadhyadīrghamaṣṭādaśadvādaśāṅgulāyataṃ tryaṅgulapraveśamukhamagre sarṣapopalacchidraṃ tanucarmanaddhaṃ cūcukākāramukhaṃ ca tadvātaviṣaraktāmbuduṣṭastanyacūṣaṇārtham śleṣmaraktācūṣaṇārthastvalābuḥ sa dvādaśāṅguladīrgho 'ṣṭādaśāṅgulapariṇāhastricaturaṅgulavṛttasamucchritamukhaḥ pariveṣṭitadīptakuśabalvajapicugarbhaśca prayojyaḥ tadvadeva ca mānakarmābhyāṃ ghaṭī sā tu gulmonnamanavilayanārthaṃ ca" },
      { type: "verse", number: "14", sanskrit: "शलाकायन्त्राण्यपि नानाकृतीनि नानार्थानि यथायोगं दैर्घ्यपरिणाहानि च भवन्ति तेषामेषणकर्मणी द्वे गण्डूपदमुखे स्रोतोगतशल्याहरणार्थे ऽष्टाङ्गुलनवाङ्गुले द्वे मसूरदलमुखे षट् शङ्कवः तेषां व्यूहनक्रियौ द्वादशषोडशाङ्गुलौ द्वावहिफणामुखौ तथा चालनार्थे दशद्वादशाङ्गुलौ शरपुङ्खमुखौ आहरणार्थे बडिशमुखौ तथा गर्भशङ्कुः शङ्कुतुल्यो ऽष्टादशाङ्गुलः प्रणताग्रो मूडगर्भाहरणे तथा सर्पफणावदेवाग्रवक्रं तदाख्यमश्मर्याहरणार्थम् तथा दन्तनिर्घातनं चतुरङ्गुलं शरपुङ्खमुखं स्थूलवृत्तप्रान्तम्", text: "śalākāyantrāṇyapi nānākṛtīni nānārthāni yathāyogaṃ dairghyapariṇāhāni ca bhavanti teṣāmeṣaṇakarmaṇī dve gaṇḍūpadamukhe srotogataśalyāharaṇārthe 'ṣṭāṅgulanavāṅgule dve masūradalamukhe ṣaṭ śaṅkavaḥ teṣāṃ vyūhanakriyau dvādaśaṣoḍaśāṅgulau dvāvahiphaṇāmukhau tathā cālanārthe daśadvādaśāṅgulau śarapuṅkhamukhau āharaṇārthe baḍiśamukhau tathā garbhaśaṅkuḥ śaṅkutulyo 'ṣṭādaśāṅgulaḥ praṇatāgro mūḍagarbhāharaṇe tathā sarpaphaṇāvadevāgravakraṃ tadākhyamaśmaryāharaṇārtham tathā dantanirghātanaṃ caturaṅgulaṃ śarapuṅkhamukhaṃ sthūlavṛttaprāntam" },
      { type: "verse", number: "15", sanskrit: "षट् कार्पासकृतोष्णीषाणि विविधव्रणक्लेदक्षारप्रमार्जनक्रियासु तेषामपि दूरासन्नघ्राणव्रणोपयोगिनी षट् सप्ताङ्गुले द्वे पायौ दशद्वादशाङ्गुले कर्णशोधनं स्रुवमुखमश्वत्थपत्राग्रम् तथा क्षाराग्निकर्मार्थे जाम्बवोष्ठानि द्वादशाष्टाङ्गुलानि क्रमाद्व्यङ्गुलाङ्गुलार्द्धाङ्गुलफलानि", text: "ṣaṭ kārpāsakṛtoṣṇīṣāṇi vividhavraṇakledakṣārapramārjanakriyāsu teṣāmapi dūrāsannaghrāṇavraṇopayoginī ṣaṭ saptāṅgule dve pāyau daśadvādaśāṅgule karṇaśodhanaṃ sruvamukhamaśvatthapatrāgram tathā kṣārāgnikarmārthe jāmbavoṣṭhāni dvādaśāṣṭāṅgulāni kramādvyaṅgulāṅgulārddhāṅgulaphalāni" },
      { type: "verse", number: "16", sanskrit: "शलाकाश्च स्थूलसूक्ष्मदीर्घह्रस्वमध्याः आन्त्रवृद्धौ त्वर्धेन्दुवक्रा मध्योर्ध्वनिर्गतशलाकाः दहने नासार्शो ऽर्बुदयोः कोलास्थिदलमात्रमुखा वेल्लितौष्ठा क्षारविषौषधप्रणिधानाय च दर्व्यस्तिस्रो ऽष्टाङ्गुला दर्व्याकाराः कनिष्ठिकानामिकामध्यमाङ्गुलिनखपरिमाणनिम्नमुखास्तथाञ्जलिसंस्थानाः उत्तरबस्त्यञ्जनादिषु यथायथमेवोपदिष्टानि", text: "śalākāśca sthūlasūkṣmadīrghahrasvamadhyāḥ āntravṛddhau tvardhenduvakrā madhyordhvanirgataśalākāḥ dahane nāsārśo 'rbudayoḥ kolāsthidalamātramukhā vellitauṣṭhā kṣāraviṣauṣadhapraṇidhānāya ca darvyastisro 'ṣṭāṅgulā darvyākārāḥ kaniṣṭhikānāmikāmadhyamāṅgulinakhaparimāṇanimnamukhāstathāñjalisaṃsthānāḥ uttarabastyañjanādiṣu yathāyathamevopadiṣṭāni" },
      { type: "verse", number: "17", sanskrit: "अनुयन्त्राण्ययस्कान्तरज्जुचर्मान्त्रवस्त्राश्ममुद्गरपाणिपादतलाङ्गुलिजिह्वादन्तमुखशाखानखबालाश्वकालपाकहर्षभयानि", text: "anuyantrāṇyayaskāntarajjucarmāntravastrāśmamudgarapāṇipādatalāṅgulijihvādantamukhaśākhānakhabālāśvakālapākaharṣabhayāni" },
      { type: "verse", number: "18", sanskrit: "एतानि देहे सर्वस्मिन् देहस्यावयवे ऽपि वा सन्धौ कोष्ठधमन्यां च यथायोगं प्रयोजयेत्", text: "etāni dehe sarvasmin dehasyāvayave 'pi vā sandhau koṣṭhadhamanyāṃ ca yathāyogaṃ prayojayet" },
      { type: "verse", number: "19", sanskrit: "यन्त्रकर्माणि तु निर्घातनपूरणबन्धनव्यूहनपरिवर्तनचालनविवरणपीडनमार्गशोधनविकर्षणाहरणव्यथनोन्नमनविनमनभञ्जनोन्मथनाचूषणैषणदारणौजूकरणप्रक्षालनप्रधमनाञ्जनप्रमार्जनानि बाहुल्येनचतुर्विंशतिर्भवन्ति", text: "yantrakarmāṇi tu nirghātanapūraṇabandhanavyūhanaparivartanacālanavivaraṇapīḍanamārgaśodhanavikarṣaṇāharaṇavyathanonnamanavinamanabhañjanonmathanācūṣaṇaiṣaṇadāraṇaujūkaraṇaprakṣālanapradhamanāñjanapramārjanāni bāhulyenacaturviṃśatirbhavanti" },
      { type: "verse", number: "20", sanskrit: "विवर्तते साध्ववगाहते च ग्राह्यं गृहीत्वोद्धरते च यस्मात् यन्त्रेष्वतः कङ्कमुखं प्रधानं स्थानेषु सर्वेष्वधिकारि यच्च", text: "vivartate sādhvavagāhate ca grāhyaṃ gṛhītvoddharate ca yasmāt yantreṣvataḥ kaṅkamukhaṃ pradhānaṃ sthāneṣu sarveṣvadhikāri yacca" },
      { type: "verse", number: "21", sanskrit: "शस्त्राणि तु षड्विंशतिर्भवन्ति तद्यथा दन्तलेखनमण्डलाग्रवृद्धिपत्रोत्पलपत्राध्यर्धधारमुद्रिकाकर्तरीसर्पवक्त्रकरपत्रकुशापत्राटीमुखान्तर्मुखशरारीमुखत्रिकूर्चकुठारिकाव्रीहिमुखशलाकावेतसपत्राराकर्णव्यधनसूचीसूचीकूर्चखजैषिणीबडिशनखशस्त्राणि चेति प्रायश्च तानि षडङ्गुलानि सुध्मातावर्तितायोघटितान्युत्पलपत्रनीलानि सुग्रहाणि सुरूपाणि सुधाराणि सुसमाहितमुखाग्राण्यकरालानि प्रत्येकं च प्रायो द्वित्राणि स्वप्रमाणार्धचतुर्थभागफलानि तानि व्याधिदेशवशात् प्रयुञ्जीत तेषां नामभिरेवाकृतयः प्रायेण यन्त्रवद्व्याख्याताः", text: "śastrāṇi tu ṣaḍviṃśatirbhavanti tadyathā dantalekhanamaṇḍalāgravṛddhipatrotpalapatrādhyardhadhāramudrikākartarīsarpavaktrakarapatrakuśāpatrāṭīmukhāntarmukhaśarārīmukhatrikūrcakuṭhārikāvrīhimukhaśalākāvetasapatrārākarṇavyadhanasūcīsūcīkūrcakhajaiṣiṇībaḍiśanakhaśastrāṇi ceti prāyaśca tāni ṣaḍaṅgulāni sudhmātāvartitāyoghaṭitānyutpalapatranīlāni sugrahāṇi surūpāṇi sudhārāṇi susamāhitamukhāgrāṇyakarālāni pratyekaṃ ca prāyo dvitrāṇi svapramāṇārdhacaturthabhāgaphalāni tāni vyādhideśavaśāt prayuñjīta teṣāṃ nāmabhirevākṛtayaḥ prāyeṇa yantravadvyākhyātāḥ" },
      { type: "verse", number: "22", sanskrit: "तत्र त्रयमाद्यं लेखने वृद्धिपत्रादीनि त्रीणि पाटने चत्वारि भेदने मण्डलाग्रादीन्यष्टौ छेदने कुशपत्रादीनि पञ्च प्रच्छाने कुठारिकादीनि षट् व्यधने तेषामाराव्रीहिमुखे भेदने छेदने च सूच्यः सीवने सूचीकूर्चः कुट्टने खजो मथने एषिण्येषणे भेदने च बडिशो ग्रहणे नखशस्त्रमुद्धरणे छेद्यभेद्यलेख्यप्रच्छानेषु च इति द्वादशाविधे शस्त्रकर्मण्युपयोगः", text: "tatra trayamādyaṃ lekhane vṛddhipatrādīni trīṇi pāṭane catvāri bhedane maṇḍalāgrādīnyaṣṭau chedane kuśapatrādīni pañca pracchāne kuṭhārikādīni ṣaṭ vyadhane teṣāmārāvrīhimukhe bhedane chedane ca sūcyaḥ sīvane sūcīkūrcaḥ kuṭṭane khajo mathane eṣiṇyeṣaṇe bhedane ca baḍiśo grahaṇe nakhaśastramuddharaṇe chedyabhedyalekhyapracchāneṣu ca iti dvādaśāvidhe śastrakarmaṇyupayogaḥ" },
      { type: "verse", number: "23", sanskrit: "विशेषतस्तु दन्तलेखनं सुप्रबन्धवच्चतुरस्रमेकधारं दन्तशर्करालेखने मण्डलाग्रं प्रदेशिन्यन्तर्नखविस्तृतफलं तल्लेखनच्छेदनयोर्वर्त्मरोगोत्सन्नदन्तमांसदुर्निविष्टव्रणगलशुण्डिकादिषु प्रयोज्यम्", text: "viśeṣatastu dantalekhanaṃ suprabandhavaccaturasramekadhāraṃ dantaśarkarālekhane maṇḍalāgraṃ pradeśinyantarnakhavistṛtaphalaṃ tallekhanacchedanayorvartmarogotsannadantamāṃsadurniviṣṭavraṇagalaśuṇḍikādiṣu prayojyam" },
      { type: "verse", number: "24", sanskrit: "वृद्धिपत्रं क्षुराकारं तत्तून्नते गम्भीरे वा श्वयथावृजुसूच्यग्रमिष्टम् विपरीते तु पृष्ठतो ऽवनतधारम्", text: "vṛddhipatraṃ kṣurākāraṃ tattūnnate gambhīre vā śvayathāvṛjusūcyagramiṣṭam viparīte tu pṛṣṭhato 'vanatadhāram" },
      { type: "verse", number: "25", sanskrit: "अङ्गुलिशस्त्रकं मुद्रिकानिर्गतमुखं वृद्धिपत्रमण्डलाग्राध्यर्धधारान्यतमतुल्यार्धाङ्गुलायतधारं प्रदेशिनीप्रथमपर्वप्रमाणार्पणवृत्तमुद्रिकं दृढसूत्रप्रतिबन्धं कण्ठरोगेषु प्रयुज्यते", text: "aṅguliśastrakaṃ mudrikānirgatamukhaṃ vṛddhipatramaṇḍalāgrādhyardhadhārānyatamatulyārdhāṅgulāyatadhāraṃ pradeśinīprathamaparvapramāṇārpaṇavṛttamudrikaṃ dṛḍhasūtrapratibandhaṃ kaṇṭharogeṣu prayujyate" },
      { type: "verse", number: "26", sanskrit: "कर्तरी त्रिभागपाशा व्रणस्नायुकेशसूत्रच्छेदनार्था सर्पवक्त्रं वक्रमर्धाङ्गुलफलं घ्राणकर्णार्शो ऽर्बुदच्छेदनार्थम् करपत्रं दशाङ्गुलं द्व्यङ्गुलविस्तारं सूक्ष्मदन्तं खरधारं सुत्सरुनिबद्धमस्थिच्छेदनार्थम् कुशपत्राटीमुखे द्व्यङ्गुलफले अन्तर्मुखमर्धचन्द्राकारमध्यर्धाङ्गुलफलम्", text: "kartarī tribhāgapāśā vraṇasnāyukeśasūtracchedanārthā sarpavaktraṃ vakramardhāṅgulaphalaṃ ghrāṇakarṇārśo 'rbudacchedanārtham karapatraṃ daśāṅgulaṃ dvyaṅgulavistāraṃ sūkṣmadantaṃ kharadhāraṃ sutsarunibaddhamasthicchedanārtham kuśapatrāṭīmukhe dvyaṅgulaphale antarmukhamardhacandrākāramadhyardhāṅgulaphalam" },
      { type: "verse", number: "27", sanskrit: "कुठारिका पृथुदण्डा गोदन्ताकारा अर्धाङ्गुलफलास्थ्याश्रितसिराव्यधार्था व्रीहिमुखमध्यर्धाङ्गुलफलं मांसलप्रदेशसिराव्यधार्थं वर्ध्मोदरगुल्मविद्रध्यादिव्यधनभेदनार्थं च शलाकोभयतोमुखी कुरबकमुकुलाग्रा ताम्रमयी लिङ्गनाशव्यधनार्था", text: "kuṭhārikā pṛthudaṇḍā godantākārā ardhāṅgulaphalāsthyāśritasirāvyadhārthā vrīhimukhamadhyardhāṅgulaphalaṃ māṃsalapradeśasirāvyadhārthaṃ vardhmodaragulmavidradhyādivyadhanabhedanārthaṃ ca śalākobhayatomukhī kurabakamukulāgrā tāmramayī liṅganāśavyadhanārthā" },
      { type: "verse", number: "28", sanskrit: "आरा चतुरस्रार्धाङ्गुलवृत्तमुखा तावत्प्रवेशा बहलकर्णपालीव्यथार्था पक्वामशोफसन्देहभेदनार्था च कर्णव्यधनं त्र्यङ्गुलायतमङ्गुलसुषिरं घनं यूथिकामुकुलाग्रम्", text: "ārā caturasrārdhāṅgulavṛttamukhā tāvatpraveśā bahalakarṇapālīvyathārthā pakvāmaśophasandehabhedanārthā ca karṇavyadhanaṃ tryaṅgulāyatamaṅgulasuṣiraṃ ghanaṃ yūthikāmukulāgram" },
      { type: "verse", number: "29", sanskrit: "सूच्यस्तिस्रो वृत्ता निगूढदृढपाशाः तत्र मांसलेष्ववकाशेषु त्र्यङ्गुला त्र्यस्रा सन्ध्यस्थिव्रणेष्वल्पमांसेषु च द्व्यङ्गुला वृत्ता पक्वामाशययोर्मर्मसु च सार्धद्व्यङ्गुला धनुर्वक्रा व्रीहिमुखा च", text: "sūcyastisro vṛttā nigūḍhadṛḍhapāśāḥ tatra māṃsaleṣvavakāśeṣu tryaṅgulā tryasrā sandhyasthivraṇeṣvalpamāṃseṣu ca dvyaṅgulā vṛttā pakvāmāśayayormarmasu ca sārdhadvyaṅgulā dhanurvakrā vrīhimukhā ca" },
      { type: "verse", number: "30", sanskrit: "सूचीकूर्चो वृत्तैकमूलो ऽग्रे सुनिबद्धसप्ताष्टसूचिकः कुष्टश्वित्रव्यङ्गेन्द्रलुप्तसुप्तादिषु खजस्त्वर्धाङ्गुलायताष्टकण्टकमुखस्ताम्रो लौहो वा नासाभ्यन्तरगतशोणितमोक्षणार्थः एषण्या द्वे सुश्लक्ष्णस्पर्शे तयोरेकाष्टाङ्गुला गतिकोथशल्यस्राववत्सु व्रणेषु सुषिरान्वेषणे अन्या सूचीसंस्थाना क्षाराक्तसूत्रप्रतिबद्धा नाडीनां भगन्दरगतीनां च भेदने बडिशो ऽत्यवनतमुखः सूचीतीक्ष्णाग्रो ग्रहणे गलशुण्डिकार्मादेः नखशस्त्रमष्टाङ्गुलमेकतो ऽश्वकर्णमुखमन्यतो वत्सदन्तमुखं सूक्ष्मशल्योद् वृतौ", text: "sūcīkūrco vṛttaikamūlo 'gre sunibaddhasaptāṣṭasūcikaḥ kuṣṭaśvitravyaṅgendraluptasuptādiṣu khajastvardhāṅgulāyatāṣṭakaṇṭakamukhastāmro lauho vā nāsābhyantaragataśoṇitamokṣaṇārthaḥ eṣaṇyā dve suślakṣṇasparśe tayorekāṣṭāṅgulā gatikothaśalyasrāvavatsu vraṇeṣu suṣirānveṣaṇe anyā sūcīsaṃsthānā kṣārāktasūtrapratibaddhā nāḍīnāṃ bhagandaragatīnāṃ ca bhedane baḍiśo 'tyavanatamukhaḥ sūcītīkṣṇāgro grahaṇe galaśuṇḍikārmādeḥ nakhaśastramaṣṭāṅgulamekato 'śvakarṇamukhamanyato vatsadantamukhaṃ sūkṣmaśalyod vṛtau" },
      { type: "verse", number: "31", sanskrit: "अणुशस्त्राणि तु जलौकःक्षाराग्निसूर्यकान्तकाचस्फटिककुरुचिन्दनखशाकशोफालिकादिखरपत्रसमुद्रफेनशुष्कगोमयादीनि स्वबुद्ध्या च विकल्प्य विविधानि यन्त्रशस्त्राणि तत्कर्माणि चोपकल्पयेत् हस्त एव चात्र प्रधानतमस्तदधीनत्वाद्यन्त्रशस्त्राणाम्", text: "aṇuśastrāṇi tu jalaukaḥkṣārāgnisūryakāntakācasphaṭikakurucindanakhaśākaśophālikādikharapatrasamudraphenaśuṣkagomayādīni svabuddhyā ca vikalpya vividhāni yantraśastrāṇi tatkarmāṇi copakalpayet hasta eva cātra pradhānatamastadadhīnatvādyantraśastrāṇām" },
      { type: "verse", number: "32", sanskrit: "तत्र दीर्घह्रस्वस्थूलतनुवक्रविषमग्राह्यग्राहिशिथिलता इत्यष्टौ यन्त्रदोषाः अत्राद्याः पञ्च कुण्ठखण्डखरधाराश्चेत्यष्टावेव शस्त्रदोषाः अन्यत्र करपत्रात्", text: "tatra dīrghahrasvasthūlatanuvakraviṣamagrāhyagrāhiśithilatā ityaṣṭau yantradoṣāḥ atrādyāḥ pañca kuṇṭhakhaṇḍakharadhārāścetyaṣṭāveva śastradoṣāḥ anyatra karapatrāt" },
      { type: "verse", number: "33", sanskrit: "तत्र क्षारेण पायितं शस्त्रं शरशल्यास्थिच्छेदनेषु उदकेन मांसच्छेदनेषु तैलेन पाटनभेदनेषु सिराव्यधस्नायुच्छेदनेषु च प्रयुञ्जीत", text: "tatra kṣāreṇa pāyitaṃ śastraṃ śaraśalyāsthicchedaneṣu udakena māṃsacchedaneṣu tailena pāṭanabhedaneṣu sirāvyadhasnāyucchedaneṣu ca prayuñjīta" },
      { type: "verse", number: "34", sanskrit: "धारा पुनः छेदनानां मासूरी लेखनानामर्धमासूरी व्यधनानां विस्रावणानां च कैशिकी", text: "dhārā punaḥ chedanānāṃ māsūrī lekhanānāmardhamāsūrī vyadhanānāṃ visrāvaṇānāṃ ca kaiśikī" },
      { type: "verse", number: "35", sanskrit: "तेषां छेदनभेदनलेखनानि वृन्तसाधारणे भागे प्रदेशिनीमध्यमाङ्गुष्ठैः सुसमाहितो गृह्णीयात् वृन्ताग्रे विस्रावणानि प्रदेशिन्यङ्गुष्ठाङ्गुलीभ्याम् हस्ततलप्रच्छादितवृन्ताग्रं व्रीहिमुखं मुखे मूलेष्वाहरणार्थानि पाशस्योपरि मध्ये लघुसन्दंशं कर्तरीं च शेषाण्यपि यथायोगं क्रियासौकर्येण", text: "teṣāṃ chedanabhedanalekhanāni vṛntasādhāraṇe bhāge pradeśinīmadhyamāṅguṣṭhaiḥ susamāhito gṛhṇīyāt vṛntāgre visrāvaṇāni pradeśinyaṅguṣṭhāṅgulībhyām hastatalapracchāditavṛntāgraṃ vrīhimukhaṃ mukhe mūleṣvāharaṇārthāni pāśasyopari madhye laghusandaṃśaṃ kartarīṃ ca śeṣāṇyapi yathāyogaṃ kriyāsaukaryeṇa" },
      { type: "verse", number: "36", sanskrit: "निशातनी तु तेषां सुश्लक्ष्णा शिला माषमुद्गप्रभा धारासंस्थापनं च शाल्मलीफलकम्", text: "niśātanī tu teṣāṃ suślakṣṇā śilā māṣamudgaprabhā dhārāsaṃsthāpanaṃ ca śālmalīphalakam" },
      { type: "verse", number: "37", sanskrit: "न चाधिगतशास्त्रोप्यकृतयोग्यः सुबहुशो वाप्यदृष्टकर्मा शस्त्रकर्माणि प्रवर्त्तेत सिरास्नायुमर्मादिव्याप्तत्वाद्देहस्य तस्मात् सरोमचर्मपुष्पफलालाबुत्रपुसोदकपङ्कपूर्णदृतिबस्तिवर्ध्ममांसपेशिकोत्पलनालादिषु यथार्हमाहरणादियोग्यां कुर्यात् तथा घटपार्श्वस्रोतस्यम्भोभिः पूर्णेन नेत्रेण बस्तिपीडनयोग्याम् मृदुमांसखण्डेष्वग्निक्षारावचरणयोग्याम् पुस्तमयपुरुषाङ्गप्रत्यङ्गेषु बन्धनयोग्याम् अपि च", text: "na cādhigataśāstropyakṛtayogyaḥ subahuśo vāpyadṛṣṭakarmā śastrakarmāṇi pravartteta sirāsnāyumarmādivyāptatvāddehasya tasmāt saromacarmapuṣpaphalālābutrapusodakapaṅkapūrṇadṛtibastivardhmamāṃsapeśikotpalanālādiṣu yathārhamāharaṇādiyogyāṃ kuryāt tathā ghaṭapārśvasrotasyambhobhiḥ pūrṇena netreṇa bastipīḍAnayogyām mṛdumāṃsakhaṇḍeṣvagnikṣārāvacaraṇayogyām pustamayapuruṣāṅgapratyaṅgeṣu bandhanayogyām api ca" },
      { type: "verse", number: "38", sanskrit: "युक्तकारी भिषग् बुभूषुः पुरुषं संपूर्णगात्रमविषहतमदीर्घव्याधिपीडितं निष्कृष्टदृष्टान्त्रमावहन्त्यामापगायां मुञ्जबल्बजवेष्टितं पञ्जरस्थमप्रकाशे देशे कोथयेत् तं सम्यक्प्रकुथितं चोद्घृत्यायतदेहं कृत्वोशीरवेणुकूर्चादीनामन्यतमेन शनैश्शनैरवघृष्य त्वगादीन् सर्वानेव बाह्याभ्यन्तरानङ्गसिरास्नाय्वादीनवयवानाचार्योपदर्शितेनागमेन चक्षुषा च लक्षयेत्", text: "yuktakārī bhiṣag bubhūṣuḥ puruṣaṃ saṃpūrṇagātramaviṣahatamadīrghavyādhipīḍitaṃ niṣkṛṣṭadṛṣṭāntramāvahantyāmāpagāyāṃ muñjabalbajaveṣṭitaṃ pañjarasthamaprakāśe deśe kothayet taṃ samyakprakuthitaṃ codghṛtyāyatadehaṃ kṛtvośīraveṇukūrcādīnāmanyatamena śanaiśśanairavaghṛṣya tvagādīn sarvāneva bāhyābhyantarānaṅgasirāsnāyvādīnavayavānācāryopadarśitenāgamena cakṣuṣā ca lakṣayet" },
      { type: "verse", number: "39", sanskrit: "इति शास्त्रेण यद्दृष्टं दृष्टं प्रत्यक्षतश्च यत् समागतं तदुभयं भूयो ज्ञानं विवर्धयेत्", text: "iti śāstreṇa yaddṛṣṭaṃ dṛṣṭaṃ pratyakṣataśca yat samāgataṃ tadubhayaṃ bhūyo jñānaṃ vivardhayet" },
      { type: "verse", number: "40", sanskrit: "स्यान्नवाङ्गुलविस्तारः सुघनो द्वादशाङ्गुलः क्षौमपत्रोर्णकौशेयदुकूलमृदुचर्मजः", text: "syānnavāṅgulavistāraḥ sughano dvādaśāṅgulaḥ kṣaumapatrorṇakauśeyadukūlamṛducarmajaḥ" },
      { type: "verse", number: "41", sanskrit: "विन्यस्तपाशः सुस्यूतः सान्तरोर्णास्थशस्त्रकः शलाकापिहितास्यश्च शस्त्रकोशः सुसञ्चयः", text: "vinyastapāśaḥ susyūtaḥ sāntarorṇāsthaśastrakaḥ śalākāpihitāsyaśca śastrakośaḥ susañcayaḥ" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 35,
    lang: "sa",
    content: [
      { type: "heading", heading: "Двивранья — двойственность ран" },
      { type: "text", text: "Глава 35 Сутрастханы Астанга-санграхи посвящена теме «двойственность ран». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो जलौकोविधिं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto jalaukovidhiṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "नृपाढ्यभीरुसुकुमारबालस्थविरनारीणामसृग्विस्रावणाय जलौकसो योजयेत्", text: "nṛpāḍhyabhīrusukumārabālasthaviranārīṇāmasṛgvisrāvaṇāya jalaukaso yojayet" },
      { type: "verse", number: "3", sanskrit: "तास्तु द्विविधाः सविषा निर्विषाश्च तत्र दुष्टाम्बुसर्पमण्डूकमत्स्यादिशवकोथमूत्रपुरीषजा रक्तश्वेतातिकृष्णतनुस्थूलचपलपिच्छिलाः स्थूलमध्यरोमशाः शक्रायुधवद्विचित्रोर्ध्वराजीचिता वा सविषाः तद्दंशाद्दाहशोफपाककण्डूपिटकाविसर्पज्वरमूर्छश्वित्रोत्पत्तिः तत्र विषपित्तरक्तहरां क्रियां कुर्वीत पद्मोत्पलसौगन्धिकादिसुगन्धिविमलविपुलसलिलशैवालजाः शैवालश्यावा नीलोर्ध्वराजयो वृत्ताश्च निर्विषाः", text: "tāstu dvividhāḥ saviṣā nirviṣāśca tatra duṣṭāmbusarpamaṇḍūkamatsyādiśavakothamūtrapurīṣajā raktaśvetātikṛṣṇatanusthūlacapalapicchilāḥ sthūlamadhyaromaśāḥ śakrāyudhavadvicitrordhvarājīcitā vā saviṣāḥ taddaṃśāddāhaśophapākakaṇḍūpiṭakāvisarpajvaramūrchaśvitrotpattiḥ tatra viṣapittaraktaharāṃ kriyāṃ kurvīta padmotpalasaugandhikādisugandhivimalavipulasalilaśaivālajāḥ śaivālaśyāvā nīlordhvarājayo vṛttāśca nirviṣāḥ" },
      { type: "verse", number: "4", sanskrit: "सर्वासां च परं प्रमाणमष्टादशाङ्गुलानि तत्र चतुष्पञ्चषडङ्गुला नृषु योजयेत् गजवाजिष्वपराः तासु सुकुमारास्तनुत्वचो ऽल्पशिरस्का बृहदधरकायाश्च स्त्रियः विपरीताः पुमांसो ऽर्धचन्द्राकृतिपुरोवृत्ताश्च तत्र बहुदोषेषु चिरोत्थितेषु चामयेषु पुमांसो योजयितव्याः स्त्रियो विपरीतेषु जलौकसस्त्वार्द्रचर्माह्युपायैर्गृहीत्वा सुरभिपङ्कगर्भे नवे घटे स्थापयेत् शृङ्गाटककशेरुकशालूकशैवालमृणालवल्लूरमृत्स्नापुष्करबीजचूर्णं स्वादुशीतं स्वच्छं च तोयमन्नपानार्थे ताभ्यो दद्यात् लालादिकोथपरिहारार्थमेवं च त्र्यहात् त्र्यहादूर्ध्वं पूर्वमन्नपानमपनीयान्यद्दद्यात् पञ्चाहाच्च तद्विध एव घटान्तरे ताः सञ्चारयेत् तासां तु दुष्टशोणितासम्यग्वमनात् प्रततपातनाच्च मूर्च्छा भवति तासामम्भोभिः पूर्णभाजनस्थानामचेष्टयाहारानभिलाषेण च ज्ञात्वा ता विवर्जयेत् इतरास्तु हरिद्रासर्षपकल्काम्भसि मुक्तपुरीषा अवन्तिसोमे तक्रे वा पुनराश्वासिता जले सुखोपविष्टस्य संविष्टस्य वा मृद्गोमयचूर्णाभ्यामनुसुखं विरूक्ष्य दंशदेशं योजयेत् अलगन्तीषु क्षीरघृतनवनीतरुधिरान्यतमबिन्दून् न्यसेत् प्रच्छेद्वा अश्वखुरवच्च वक्त्रं निवेश्योन्नतस्कन्धा दशन्ति यदा च शिशुवच्छ्वसन्त्यो शिरःस्पन्दोर्मिवेगैः पिबन्ति तदार्द्रवाससावच्छादयेत् सेचयेच्चाम्भसाल्पाल्पम् यथा च हंसः क्षीरोदकात् क्षीरमादत्ते तद्वदुत्क्लिष्टे रक्ते जलौकाः प्राग् दुष्टमसृक् यदा च तद्दंशे तोदः कण्डूर्वा तदा शुद्धरक्तरक्षणार्थमपनयेत् लौल्याच्च दंशममुञ्चन्त्याः क्षौद्रं लवणचूर्णं वा मुखे दद्यात्", text: "sarvāsāṃ ca paraṃ pramāṇamaṣṭādaśāṅgulāni tatra catuṣpañcaṣaḍaṅgulā nṛṣu yojayet gajavājiṣvaparāḥ tāsu sukumārāstanutvaco 'lpaśiraskā bṛhadadharakāyāśca striyaḥ viparītāḥ pumāṃso 'rdhacandrākṛtipurovṛttāśca tatra bahudoṣeṣu cirotthiteṣu cāmayeṣu pumāṃso yojayitavyāḥ striyo viparīteṣu jalaukasastvārdracarmāhyupāyairgṛhītvā surabhipaṅkagarbhe nave ghaṭe sthāpayet śṛṅgāṭakakaśerukaśālūkaśaivālamṛṇālavallūramṛtsnāpuṣkarabījacūrṇaṃ svāduśītaṃ svacchaṃ ca toyamannapānārthe tābhyo dadyāt lālādikothaparihārārthamevaṃ ca tryahāt tryahādūrdhvaṃ pūrvamannapānamapanīyānyaddadyāt pañcāhācca tadvidha eva ghaṭāntare tāḥ sañcārayet tāsāṃ tu duṣṭaśoṇitāsamyagvamanāt pratatapātanācca mūrcchā bhavati tāsāmambhobhiḥ pūrṇabhājanasthānāmaceṣṭayāhārānabhilāṣeṇa ca jñātvā tā vivarjayet itarāstu haridrāsarṣapakalkāmbhasi muktapurīṣā avantisome takre vā punarāśvāsitā jale sukhopaviṣṭasya saṃviṣṭasya vā mṛdgomayacūrṇābhyāmanusukhaṃ virūkṣya daṃśadeśaṃ yojayet alagantīṣu kṣīraghṛtanavanītarudhirānyatamabindūn nyaset pracchedvā aśvakhuravacca vaktraṃ niveśyonnataskandhā daśanti yadā ca śiśuvacchvasantyo śiraḥspandormivegaiḥ pibanti tadārdravāsasāvacchādayet secayeccāmbhasālpālpam yathā ca haṃsaḥ kṣīrodakāt kṣīramādatte tadvadutkliṣṭe rakte jalaukāḥ prāg duṣṭamasṛk yadā ca taddaṃśe todaḥ kaṇḍūrvā tadā śuddharaktarakṣaṇārthamapanayet laulyācca daṃśamamuñcantyāḥ kṣaudraṃ lavaṇacūrṇaṃ vā mukhe dadyāt" },
      { type: "verse", number: "5", sanskrit: "पतितां तु तण्डुलकण्डनोपदिग्धगात्रां तैललवणाभ्यक्तमुखीं आपुच्छादामुखमनुलोमं शनैः पीडयन् सम्यग्वामयेत् ततः पूर्ववत् सन्निदध्यात् सप्तरात्रं च ताः पुनर्न पातयेत् अशुद्धे तु रक्ते मधुना गुडेन वा दंशात् किञ्चिदवघट्टयन् स्रावयेत् स्रुतरक्तस्य च सद्यो दंशं शीताभिरद्भिः प्रक्षाल्य सर्पिःपिचुनावगुण्ठयेत् स्थितरक्तं चोत्क्लिष्टशोणितशेषप्रसादनाय कषायमधुरशिशिरैः सघृतैः प्रदेहैः प्रदिह्यात्", text: "patitāṃ tu taṇḍulakaṇḍanopadigdhagātrāṃ tailalavaṇābhyaktamukhīṃ āpucchādāmukhamanulomaṃ śanaiḥ pīḍayan samyagvāmayet tataḥ pūrvavat sannidadhyāt saptarātraṃ ca tāḥ punarna pātayet aśuddhe tu rakte madhunā guḍena vā daṃśāt kiñcidavaghaṭṭayan srāvayet srutaraktasya ca sadyo daṃśaṃ śītābhiradbhiḥ prakṣālya sarpiḥpicunāvaguṇṭhayet sthitaraktaṃ cotkliṣṭaśoṇitaśeṣaprasādanāya kaṣāyamadhuraśiśiraiḥ saghṛtaiḥ pradehaiḥ pradihyāt" },
      { type: "verse", number: "6", sanskrit: "तत्र योगादीन् सिराव्यधवदुपलक्षयेत् प्रतिकुर्वीत च दुष्टरक्तापगमात् श्वयथुशैथिल्यं दाहरागशूलोपशमश्च रक्तपित्तेन दुष्टमलाबुघटिकाभ्यां न निर्हरेदग्निसंयोगाद्वातकफाभ्यां च दुष्टं निर्हरेत् तथा कफेन न शृङ्गेण स्कन्नत्वात् वातपित्ताभ्यां तु दुष्टं निर्हरेत् अथ प्रच्छाद्याङ्गं तनुवस्त्रपटलावनद्धप्रान्तेन शृङ्गेणाचूषेत् तथा प्रदीप्तापिचुगर्भाभ्यामलाबुघटिकाभ्यामिति भवन्ति चात्र श्लोकाः", text: "tatra yogādīn sirāvyadhavadupalakṣayet pratikurvīta ca duṣṭaraktāpagamāt śvayathuśaithilyaṃ dāharāgaśūlopaśamaśca raktapittena duṣṭamalābughaṭikābhyāṃ na nirharedagnisaṃyogādvātakaphābhyāṃ ca duṣṭaṃ nirharet tathā kaphena na śṛṅgeṇa skannatvāt vātapittābhyāṃ tu duṣṭaṃ nirharet atha pracchādyāṅgaṃ tanuvastrapaṭalāvanaddhaprāntena śṛṅgeṇācūṣet tathā pradīptāpicugarbhābhyāmalābughaṭikābhyāmiti bhavanti cātra ślokāḥ" },
      { type: "verse", number: "7", sanskrit: "गात्रं बध्वोपरिदृढं रज्ज्वा पट्टेन वा समम् स्नायुसन्ध्यस्थिमर्माणि त्यजन्प्रच्छानमाचरेत्", text: "gātraṃ badhvoparidṛḍhaṃ rajjvā paṭṭena vā samam snāyusandhyasthimarmāṇi tyajanpracchānamācaret" },
      { type: "verse", number: "8", sanskrit: "अधोदेशप्रविसृतैः पदैरुपरिगामिभिः न गाढघनतिर्यग्भिर्न पदे पदमाच्रेत्", text: "adhodeśapravisṛtaiḥ padairuparigāmibhiḥ na gāḍhaghanatiryagbhirna pade padamācret" },
      { type: "verse", number: "9", sanskrit: "प्रच्छानेनैकदेशस्थं सुप्तं शृङ्गादिभिर्हरेत् ग्रथितं तु जलौकोभिरसृग्व्यापि सिराव्यधैः", text: "pracchānenaikadeśasthaṃ suptaṃ śṛṅgādibhirharet grathitaṃ tu jalaukobhirasṛgvyāpi sirāvyadhaiḥ" },
      { type: "verse", number: "10", sanskrit: "प्रच्छानं पिण्डिते वास्यादवगाढे जलौकसः त्वक्स्थे ऽलाबुघटीशृङ्गं सिरैव व्यापके ऽसृजि वातादिधाम वा शृङ्गजलौको ऽलाबुभिः क्रमात्", text: "pracchānaṃ piṇḍite vāsyādavagāḍhe jalaukasaḥ tvaksthe 'lābughaṭīśṛṅgaṃ siraiva vyāpake 'sṛji vātādidhāma vā śṛṅgajalauko 'lābubhiḥ kramāt" },
      { type: "verse", number: "11", sanskrit: "स्रुतासृजः प्रदेहाद्यः शीतैः स्याद्वायुकोपतः सतोदकण्डूः शोफस्तं सर्पिषोष्णेन सेचयेत्", text: "srutāsṛjaḥ pradehādyaḥ śītaiḥ syādvāyukopataḥ satodakaṇḍūḥ śophastaṃ sarpiṣoṣṇena secayet" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 36,
    lang: "sa",
    content: [
      { type: "heading", heading: "Агни карма — прижигание" },
      { type: "text", text: "Глава 36 Сутрастханы Астанга-санграхи посвящена теме «прижигание». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातः सिराव्यधविधिं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ sirāvyadhavidhiṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "बहवो हि रक्तावसेचनोपायाः प्रागभिहितास्तेषामन्येषां च विरेकादीनामुपक्रमाणां तत्साध्येष्वामयेषु सिराव्यधः प्रधानम् अमुना हि ते समूलाः शोषमायान्ति केदारसेतुभेदेन शाल्यादय इव तथा च", text: "bahavo hi raktāvasecanopāyāḥ prāgabhihitāsteṣāmanyeṣāṃ ca virekādīnāmupakramāṇāṃ tatsādhyeṣvāmayeṣu sirāvyadhaḥ pradhānam amunā hi te samūlāḥ śoṣamāyānti kedārasetubhedena śālyādaya iva tathā ca" },
      { type: "verse", number: "3", sanskrit: "सिराव्यधश्चिकित्सार्धं संपूर्णं वा चिकित्सितम् शल्यतन्त्रे स्मृतो यद्वद्बस्तिः कायचिकित्सिते", text: "sirāvyadhaścikitsārdhaṃ saṃpūrṇaṃ vā cikitsitam śalyatantre smṛto yadvadbastiḥ kāyacikitsite" },
      { type: "verse", number: "4", sanskrit: "यथा रक्तमधिष्ठानं विकाराणां विकारिणाम् अन्यन्न हि तथा दूष्यं कर्मेदं प्रथमं ततः", text: "yathā raktamadhiṣṭhānaṃ vikārāṇāṃ vikāriṇām anyanna hi tathā dūṣyaṃ karmedaṃ prathamaṃ tataḥ" },
      { type: "verse", number: "5", sanskrit: "तत्राम्बु शारीरमाहारसारभूतं रसाख्यमविकृतमविकृतेन तेजसा रञ्जितमिन्द्रगोपाकारं च शशशोणितगुञ्जाफलालक्तपद्मसुवर्णवर्णं धौतं च विरज्यमानं मधुरमीषल्लवणं स्निग्धमसंहतमशीतोष्णं गुरु पित्तैकचयप्रकोपोपशमं सौम्याग्नेयं प्रकृत्या रक्तमाहुः तथा दोषम् दूष्यमिति केचित् उभयात्मकमन्ये", text: "tatrāmbu śārīramāhārasārabhūtaṃ rasākhyamavikṛtamavikṛtena tejasā rañjitamindragopākāraṃ ca śaśaśoṇitaguñjāphalālaktapadmasuvarṇavarṇaṃ dhautaṃ ca virajyamānaṃ madhuramīṣallavaṇaṃ snigdhamasaṃhatamaśītoṣṇaṃ guru pittaikacayaprakopopaśamaṃ saumyāgneyaṃ prakṛtyā raktamāhuḥ tathā doṣam dūṣyamiti kecit ubhayātmakamanye" },
      { type: "verse", number: "6", sanskrit: "तच्चैवंविधमेव विधिवदाहारविहाराभ्यासाद्विशुद्धं बलवर्णसुखायुषां योनिः इतरथा पुनः शरत्कालस्वभावादेव वा प्रदुष्टमभिष्यन्दाधिमन्थशुक्लार्मतिमिररक्तराजीशिरस्तोदभेददाहकण्डूकर्णरोगमुखपाकपूतिघ्राणास्योपदेहत्वगुल्मप्लीहविद्रधिवीसर्पज्वररक्तपित्तकुष्ठपिटकाश्लीपदोपदंशशङ्खशोफवातशोणितरक्तमेहक्षुद्ररोगाग्निस्वरनाशाङ्गगौरवसादारोचकाम्लोद्गारलवणास्यताक्रोधमोहस्वेदमदमूर्छायसन्यासकम्पतन्द्रादीनाम् ये च शीतोष्णस्निग्धरूक्षाद्यैः सर्वदोषप्रतिपक्षैः सम्यगप्युपक्रान्ताः साध्या अपि न सिध्यन्ति ते च रक्तप्रकोपजाः तस्मात्तेष्वत्युद्रिक्तरक्तविस्रावणाय यथास्वं सिरां विध्येत्", text: "taccaivaṃvidhameva vidhivadāhāravihārābhyāsādviśuddhaṃ balavarṇasukhāyuṣāṃ yoniḥ itarathā punaḥ śaratkālasvabhāvādeva vā praduṣṭamabhiṣyandādhimanthaśuklārmatimiraraktarājīśirastodabhedadāhakaṇḍūkarṇarogamukhapākapūtighrāṇāsyopadehatvagulmaplīhavidradhivīsarpajvararaktapittakuṣṭhapiṭakāślīpadopadaṃśaśaṅkhaśophavātaśoṇitaraktamehakṣudrarogāgnisvaranāśāṅgagauravasādārocakāmlodgāralavaṇāsyatākrodhamohasvedamadamūrchāyasanyāsakampatandrādīnām ye ca śītoṣṇasnigdharūkṣādyaiḥ sarvadoṣapratipakṣaiḥ samyagapyupakrāntāḥ sādhyā api na sidhyanti te ca raktaprakopajāḥ tasmātteṣvatyudriktaraktavisrāvaṇāya yathāsvaṃ sirāṃ vidhyet" },
      { type: "verse", number: "7", sanskrit: "न तु स्नेहपीतकृतपञ्चकर्मान्यतमगर्भिणीसूतिकाजीर्णकामलाक्लीबोनषोडशातीतसप्ततिवर्षाभिघातातिस्रुतरक्तादुष्टरक्तास्निग्धातिस्निग्धास्विन्नाक्षेपकपक्षाघातातिसारच्छर्दिश्वासकासोदररक्तपित्तार्शःपाण्डुरोगसर्वाङ्गशोफपीडितानाम् न चाव्यधनीयाश्चायन्त्रितानुत्थिताः सिराः न तिर्यङ्न चातिशीतोष्णवर्षवाताभ्रेषु तत्र स्नेहपीतादिषु सम्यग्विद्धा अपि सिरा न स्रवन्त्यतिस्रवन्ति वा सम्यक्स्निग्धस्विन्नस्य पुनर्द्रवीभूता दोषाः शोणितमनुप्रविष्टाः सम्यक् प्रच्यवन्ते न त्वेष निषेधो विषसंसृष्टोपसर्गात्ययिकव्याधिषु प्रतिरोगं तु व्यधं प्रति विभागः", text: "na tu snehapītakṛtapañcakarmānyatamagarbhiṇīsūtikājīrṇakāmalāklībonaṣoḍaśātītasaptativarṣābhighātātisrutaraktāduṣṭaraktāsnigdhātisnigdhāsvinnākṣepakapakṣāghātātisāracchardiśvāsakāsodararaktapittārśaḥpāṇḍurogasarvāṅgaśophapīḍitānām na cāvyadhanīyāścāyantritānutthitāḥ sirāḥ na tiryaṅna cātiśītoṣṇavarṣavātābhreṣu tatra snehapītādiṣu samyagviddhā api sirā na sravantyatisravanti vā samyaksnigdhasvinnasya punardravībhūtā doṣāḥ śoṇitamanupraviṣṭāḥ samyak pracyavante na tveṣa niṣedho viṣasaṃsṛṣṭopasargātyayikavyādhiṣu pratirogaṃ tu vyadhaṃ prati vibhāgaḥ" },
      { type: "verse", number: "8", sanskrit: "शिरोनेत्ररोगेषु लालाट्यामुपनास्यामपाङ्ग्यां वा कर्णरोगेषु परितः कर्णौ नासारोगेषु नासाग्रे प्रतिश्याये तु नासाललाटस्थाः मुखरोगेषु जिह्वौष्ठहनुतालुगाः जत्रूर्ध्वग्रन्थिषु ग्रीवाकर्णशङ्खमूर्धगाः अपस्मारे हनुसन्धिमध्यगाः उन्मादेतूरो ऽपाङ्गललाटगाः विद्रधौ पार्श्वशूले च पार्श्वकक्षास्तनान्तरस्थाः चतुर्थके स्कन्धाधोगतामन्यतरपार्श्वाश्रयाम् तृतीयके ऽंसयोरन्तरे त्रिकसन्धिमध्यगताम् प्रवाहिकायां शूलिन्यां श्रोण्याः समन्तात् द्व्यङ्गुले निर्वृत्तोपदंशशुक्रव्यापत्सु मेढ्रे गलगण्डः ऊर्मूलसंश्रिताम् गृद्ध्रस्यां जानुसन्धेरुपर्यधो वा चतुरङ्गुले अपच्यामिन्द्रबस्तेरधस्तात् द्व्यङ्गुले क्रोष्टुकणीर्षे सक्थिवातरुजासु च गुल्फस्योपरिष्टाच्चतुरङ्गुले श्लीपदेषु यथास्वं वक्ष्यते दाहहर्षचिप्पवातशोणितवातकण्टकविदारिकापाददारीप्रभृतिषु पादरोगेषु क्षिप्रमर्मण उपरिष्टात् द्व्यङ्गुले एतेनेतरसक्थिबाहू व्याख्यातौ विशेषतस्तु वामभागाभ्यन्तरतो बाहुमध्ये प्लीहोदरे एवमेव दक्षिणे बाहौ यकृदाख्ये तथा कासश्वासयोरप्यादिशन्ति गृध्रस्यामिव विश्वाच्याम् बाहुशोषापबाहुकयोरप्येके अदृश्यमानासु त्वेतास्वतिवृद्धस्य व्याधेरन्यव्याध्युक्तानामपि यथासन्नं व्यधः", text: "śironetrarogeṣu lālāṭyāmupanāsyāmapāṅgyāṃ vā karṇarogeṣu paritaḥ karṇau nāsārogeṣu nāsāgre pratiśyāye tu nāsālalāṭasthāḥ mukharogeṣu jihvauṣṭhahanutālugāḥ jatrūrdhvagranthiṣu grīvākarṇaśaṅkhamūrdhagāḥ apasmāre hanusandhimadhyagāḥ unmādetūro 'pāṅgalalāṭagāḥ vidradhau pārśvaśūle ca pārśvakakṣāstanāntarasthāḥ caturthake skandhādhogatāmanyatarapārśvāśrayām tṛtīyake 'ṃsayorantare trikasandhimadhyagatām pravāhikāyāṃ śūlinyāṃ śroṇyāḥ samantāt dvyaṅgule nirvṛttopadaṃśaśukravyāpatsu meḍhre galagaṇḍaḥ ūrmūlasaṃśritām gṛddhrasyāṃ jānusandheruparyadho vā caturaṅgule apacyāmindrabasteradhastāt dvyaṅgule kroṣṭukaṇīrṣe sakthivātarujāsu ca gulphasyopariṣṭāccaturaṅgule ślīpadeṣu yathāsvaṃ vakṣyate dāhaharṣacippavātaśoṇitavātakaṇṭakavidārikāpādadārīprabhṛtiṣu pādarogeṣu kṣipramarmaṇa upariṣṭāt dvyaṅgule etenetarasakthibāhū vyākhyātau viśeṣatastu vāmabhāgābhyantarato bāhumadhye plīhodare evameva dakṣiṇe bāhau yakṛdākhye tathā kāsaśvāsayorapyādiśanti gṛdhrasyāmiva viśvācyām bāhuśoṣāpabāhukayorapyeke adṛśyamānāsu tvetāsvativṛddhasya vyādheranyavyādhyuktānāmapi yathāsannaṃ vyadhaḥ" },
      { type: "verse", number: "9", sanskrit: "प्रागेव चोपकल्पयेच्छयनासनोदकुम्भवस्त्रपट्टादि तथा यथालाभं च तगरैलाशीतशिवकुष्ठपाठाविडङ्गभद्रदारुत्रिकटुकागारधूमहरिद्रार्काङ्कुरनक्तमालचूर्णमसृक्स्रावणाय असृक् स्थापनाय च लोद्ध्रमधुकप्रियङ्गुपत्तङ्गगैरिकरसाञ्जनशाल्मलीशङ्खयवगोधूममाषचूर्णम् वटअश्वत्थाश्वकर्णपलाशबिभीतकसर्जार्जुनधन्वनधातकीसालसारारिमेदतिन्दुकत्वगङ्कुरनिर्यासश्रीवेष्टकमृत्कपालमृणालाञ्जनचूर्णम् क्षौममषीलाक्षासमुद्रफेनचूर्णं वा तथान्यच्चातिस्रुतरक्तव्यापत्प्रतीकारोपकरणम् सज्जोपकरणो हि विद्यो न मोहमाप्नेति", text: "prāgeva copakalpayecchayanāsanodakumbhavastrapaṭṭādi tathā yathālābhaṃ ca tagarailāśītaśivakuṣṭhapāṭhāviḍaṅgabhadradārutrikaṭukāgāradhūmaharidrārkāṅkuranaktamālacūrṇamasṛksrāvaṇāya asṛk sthāpanāya ca loddhramadhukapriyaṅgupattaṅgagairikarasāñjanaśālmalīśaṅkhayavagodhūmamāṣacūrṇam vaṭAaśvatthāśvakarṇapalāśabibhītakasarjārjunadhanvanadhātakīsālasārārimedatindukatvagaṅkuraniryāsaśrīveṣṭakamṛtkapālamṛṇālāñjanacūrṇam kṣaumamaṣīlākṣāsamudraphenacūrṇaṃ vā tathānyaccātisrutaraktavyāpatpratīkāropakaraṇam sajjopakaraṇo hi vidyo na mohamāpneti" },
      { type: "verse", number: "10", sanskrit: "अथ कृतस्वस्त्ययनमातुरं व्याधिबलसात्म्याद्यवेक्ष्य स्निग्धं जाङ्गलरसं यवागूं वा पाययित्वा मुहूर्तमात्रमाश्वासितं पूर्वाह्णे ऽपराह्वे वाङ्गारतापोष्णबाष्पान्यतरेण स्विन्नं जानूच्छ्रिते मृदावासने जानुनिहितकूर्परं समस्थितपादं प्रत्यादित्यमुपवेशयेत् केशान्ते च प्लोतचर्मवल्कलपट्टान्यतमेन बध्नीयात् ततश्चायतेन वस्त्राङ्गुष्ठगर्भेण मुष्टिद्वयेनातुरो यथास्वं मन्ये निपीडयेद्दन्तैश्च दन्तान् गण्डौ चाध्मापयेत् पुरुषश्चैनं पृष्ठत ऊर्ध्वस्थः वस्त्रकृकाटिकान्तरन्यस्तयन्वस्त्रं प्राणानबाधमानो यन्त्रयेदित्येषो ऽन्तर्मुखवर्ज्यानां सिराणां व्यधने यन्त्रविधिः ततश्चास्य वैद्यो ऽङ्गुष्ठविष्टब्धया मध्यमयाङ्गुल्या सिरां ताडयेत् उत्थिताञ्च स्पन्दमानां स्पर्शदां वाभिलक्ष्य वामहस्तेन कुठारिकामूर्ध्वदण्डां कृत्वा सिरामध्येन्यस्य लक्षयित्वा च तथैव च मध्यमयाङ्गुल्या ताडयेदङ्गुष्ठोदरेण वा पीडयेत् गूडबहलत्वक्प्रतिच्छन्नायामङ्गुष्ठपीडनादुन्नमनमुपलक्षयेत् उत्कसनेन क्रोधसंरम्भेण चापूर्यन्ते सिराः अङ्गुष्ठेन तु नासाग्रमुन्नमय्य व्रीहिमुखेनोपनासिकां विध्येत्", text: "atha kṛtasvastyayanamāturaṃ vyādhibalasātmyādyavekṣya snigdhaṃ jāṅgalarasaṃ yavāgūṃ vā pāyayitvā muhūrtamātramāśvāsitaṃ pūrvāhṇe 'parāhve vāṅgāratāpoṣṇabāṣpānyatareṇa svinnaṃ jānūcchrite mṛdāvāsane jānunihitakūrparaṃ samasthitapādaṃ pratyādityamupaveśayet keśānte ca plotacarmavalkalapaṭṭānyatamena badhnīyāt tataścāyatena vastrāṅguṣṭhagarbheṇa muṣṭidvayenāturo yathāsvaṃ manye nipīḍayeddantaiśca dantān gaṇḍau cādhmāpayet puruṣaścainaṃ pṛṣṭhata ūrdhvasthaḥ vastrakṛkāṭikāntaranyastayanvastraṃ prāṇānabādhamāno yantrayedityeṣo 'ntarmukhavarjyānāṃ sirāṇāṃ vyadhane yantravidhiḥ tataścāsya vaidyo 'ṅguṣṭhaviṣṭabdhayā madhyamayāṅgulyā sirāṃ tāḍayet utthitāñca spandamānāṃ sparśadāṃ vābhilakṣya vāmahastena kuṭhārikāmūrdhvadaṇḍāṃ kṛtvā sirāmadhyenyasya lakṣayitvā ca tathaiva ca madhyamayāṅgulyā tāḍayedaṅguṣṭhodareṇa vā pīḍayet gūḍabahalatvakpraticchannāyāmaṅguṣṭhapīḍanādunnamanamupalakṣayet utkasanena krodhasaṃrambheṇa cāpūryante sirāḥ aṅguṣṭhena tu nāsāgramunnamayya vrīhimukhenopanāsikāṃ vidhyet" },
      { type: "verse", number: "11", sanskrit: "उन्नमितविदष्टाग्रजिह्वस्याधो जिह्वायाः विवृतास्यस्य तालुनि दन्तमूले च ग्रीवासिरासु स्तनयोरुपरि यन्त्रयेत् उदरोरसोः प्रसारितोरस्कस्योन्नमितशिरसः बाहुभ्यामवलम्बमानस्य पार्श्वयोः उन्नतमेढ्रस्य मेढ्रे श्रोणिपृष्ठस्कन्धेषून्नमितपृष्ठस्यावाक्शिरस उपविष्टस्य विश्वाचीगृध्रस्योरनाकुञ्चिते कूर्परे जानुनि च सुखोपविष्टस्य गूढाङ्गुष्ठबद्धमुष्टेर्व्यधनीयप्रदेशस्योपरि चतुरङ्गुले प्लोताद्यन्यतमेन च बध्वा हस्तसिराम् एवमेकपादं सुसंस्थितं स्थापयित्वान्यपादमीषत्सङ्कुचितं तस्योपरि निधाय जानुसन्धेरधोहस्ताभ्यामागुल्फं निपीड्य पूर्ववद्बध्वा पादसिरां विध्येत् तत्र तत्र च तैस्तैरुपायैर्विकल्प्य यन्त्रयेत्", text: "unnamitavidaṣṭāgrajihvasyādho jihvāyāḥ vivṛtāsyasya tāluni dantamūle ca grīvāsirāsu stanayorupari yantrayet udarorasoḥ prasāritoraskasyonnamitaśirasaḥ bāhubhyāmavalambamānasya pārśvayoḥ unnatameḍhrasya meḍhre śroṇipṛṣṭhaskandheṣūnnamitapṛṣṭhasyāvākśirasa upaviṣṭasya viśvācīgṛdhrasyoranākuñcite kūrpare jānuni ca sukhopaviṣṭasya gūḍhāṅguṣṭhabaddhamuṣṭervyadhanīyapradeśasyopari caturaṅgule plotādyanyatamena ca badhvā hastasirām evamekapādaṃ susaṃsthitaṃ sthāpayitvānyapādamīṣatsaṅkucitaṃ tasyopari nidhāya jānusandheradhohastābhyāmāgulphaṃ nipīḍya pūrvavadbadhvā pādasirāṃ vidhyet tatra tatra ca taistairupāyairvikalpya yantrayet" },
      { type: "verse", number: "12", sanskrit: "तत्र मांसलेष्ववकाशेषु यवमात्रं व्रीहिमुखेन अतो ऽन्यथार्धयवमात्रं व्रीहिमात्रं वा अस्थ्नामुपरिकुठारिकयार्धयवमात्रम् सर्वत्र चानुत्तानावगाढमृज्वसङ्कीर्णं मर्माद्यनुपघातिसिरामध्ये शस्त्रमाशु पातयेत्", text: "tatra māṃsaleṣvavakāśeṣu yavamātraṃ vrīhimukhena ato 'nyathārdhayavamātraṃ vrīhimātraṃ vā asthnāmuparikuṭhārikayārdhayavamātram sarvatra cānuttānāvagāḍhamṛjvasaṅkīrṇaṃ marmādyanupaghātisirāmadhye śastramāśu pātayet" },
      { type: "verse", number: "13", sanskrit: "एकप्रहाराभिहता धारया या स्रवेदसृक् मुहूर्तरुद्धा तिष्ठेच्च सम्यग्विद्धेति तां विदुः", text: "ekaprahārābhihatā dhārayā yā sravedasṛk muhūrtaruddhā tiṣṭhecca samyagviddheti tāṃ viduḥ" },
      { type: "verse", number: "14", sanskrit: "अल्पकालं वहत्यल्पं दुर्विद्धा तैलचूर्णनैः सशब्दमतिविद्धा तु स्रवेद्दुःखेन धार्यते", text: "alpakālaṃ vahatyalpaṃ durviddhā tailacūrṇanaiḥ saśabdamatividdhā tu sravedduḥkhena dhāryate" },
      { type: "verse", number: "15", sanskrit: "सम्यग्विद्धानामपि च सिराणामवहनकारणानि मूर्छा भयं यन्त्रशैथिल्यमतिगाढत्वमत्याशितता क्षामत्वं कुण्ठशस्त्रव्यधो मूत्रितोच्चारितत्वं दुःस्विन्नता कफावृतव्रणद्वारता चेति अथाप्रवृत्तिकारणं यथास्वमुपलक्ष्य प्रतिकुर्यात् तगरादिचूर्णेन च तैललवणप्रगाढेन सिरामुखमवचूर्णयेत् पृष्ठमध्ये चातुरं पीडयेत् एवं साधु वहति सम्यक् प्रवृत्ते कफानिलोपशमनरक्ताविच्छेदनार्थष्मुणलवणतैलबिन्दुभिः सिरामुखं सिञ्चेत्", text: "samyagviddhānāmapi ca sirāṇāmavahanakāraṇāni mūrchā bhayaṃ yantraśaithilyamatigāḍhatvamatyāśitatā kṣāmatvaṃ kuṇṭhaśastravyadho mūtritoccāritatvaṃ duḥsvinnatā kaphāvṛtavraṇadvāratā ceti athāpravṛttikāraṇaṃ yathāsvamupalakṣya pratikuryāt tagarādicūrṇena ca tailalavaṇapragāḍhena sirāmukhamavacūrṇayet pṛṣṭhamadhye cāturaṃ pīḍayet evaṃ sādhu vahati samyak pravṛtte kaphānilopaśamanaraktāvicchedanārthaṣmuṇalavaṇatailabindubhiḥ sirāmukhaṃ siñcet" },
      { type: "verse", number: "16", sanskrit: "अग्रे स्रवति दुष्टास्रं कुसुम्भादिव पीतिका सम्यक्स्रुत्वा स्वयं तिष्ठेच्छुद्धं तदिति नाहरेत्", text: "agre sravati duṣṭāsraṃ kusumbhādiva pītikā samyaksrutvā svayaṃ tiṣṭhecchuddhaṃ taditi nāharet" },
      { type: "verse", number: "17", sanskrit: "यस्य तु स्रवति रक्ते मूर्छा जायते तस्य विमुच्य यन्त्रं शीतसलिलार्द्रपाणिस्पर्शेन व्यजनवायुना श्रोत्रसुखेन वचसा च समाश्वासयन्नुपशमय्य मूर्छां पुनः स्रावयेत् पुनर्मूर्छत्यपरेद्युस्त्र्यहे ऽपि वा परं तु रुधिरावसेचनप्रमाणं प्रस्थः अतो ऽन्यथा व्याधिदेहर्तुबलमपेक्षेत", text: "yasya tu sravati rakte mūrchā jāyate tasya vimucya yantraṃ śītasalilārdrapāṇisparśena vyajanavāyunā śrotrasukhena vacasā ca samāśvāsayannupaśamayya mūrchāṃ punaḥ srāvayet punarmūrchatyaparedyustryahe 'pi vā paraṃ tu rudhirāvasecanapramāṇaṃ prasthaḥ ato 'nyathā vyādhidehartubalamapekṣeta" },
      { type: "verse", number: "18", sanskrit: "तत्र फेनिलमरुणं श्यावमच्छं रूक्षमस्कन्दि कषायानुरसं लोहगन्धि वेगस्रावि शीतं च रक्तं वातात् गृहधूमाञ्जनोदककृष्णं पीतं हरितं विस्रं मत्स्यगन्धि कटुत्वान्मक्षिकानिष्टमौष्ण्यादस्कन्दि सचन्द्रकं गोमूत्राभं च पित्तात् कोविदारपुष्पगैरिकोदकापाण्डु शीतं स्निग्धं स्कन्दि घनं पिच्छिलं तन्तुमद् व्रणद्वारावसादि लवणरसं वसागन्धि च कफात् द्वन्द्वसङ्कीर्णं संसर्गात् कंसनीलमाविलं दुर्गन्धं च सन्निपातात् शुद्धमुक्तं प्राक् ततः स्रुतरक्तस्य व्यधमनुलोममङ्गुष्ठेनोपरुध्य शनैश्शनैर्यन्त्रमपनीयाश्वासयेत् सतैलं च प्लोतं सिरामुखे दत्वा बध्नीयात् संवेशयेच्चैनम्", text: "tatra phenilamaruṇaṃ śyāvamacchaṃ rūkṣamaskandi kaṣāyānurasaṃ lohagandhi vegasrāvi śītaṃ ca raktaṃ vātāt gṛhadhūmāñjanodakakṛṣṇaṃ pītaṃ haritaṃ visraṃ matsyagandhi kaṭutvānmakṣikāniṣṭamauṣṇyādaskandi sacandrakaṃ gomūtrābhaṃ ca pittāt kovidārapuṣpagairikodakāpāṇḍu śītaṃ snigdhaṃ skandi ghanaṃ picchilaṃ tantumad vraṇadvārāvasādi lavaṇarasaṃ vasāgandhi ca kaphāt dvandvasaṅkīrṇaṃ saṃsargāt kaṃsanīlamāvilaṃ durgandhaṃ ca sannipātāt śuddhamuktaṃ prāk tataḥ srutaraktasya vyadhamanulomamaṅguṣṭhenoparudhya śanaiśśanairyantramapanīyāśvāsayet satailaṃ ca plotaṃ sirāmukhe datvā badhnīyāt saṃveśayeccainam" },
      { type: "verse", number: "19", sanskrit: "अतिष्ठति तु रक्ते सिरामुखं सन्धातुं पूर्वोक्तैश्चूर्णैरवचूर्ण्याङ्गुल्यग्रेण पीडयेत् शाल्मल्युपोदकापिच्छां वा व्रणमुखे दत्वा गाढं बध्नीयात् मधूच्छिष्टप्रलिप्तं वा पट्टम् शीताम्बुनावसिञ्चेत् शीतमधुरकषायान्नपानसेकप्रदेहप्रवातवेश्मभिर्वा स्कन्दनायोपचरेत् पद्मकादिक्वाथं शर्करामधुमधुरं क्षीरमिक्षुरसमेणहरिणाजोरभ्रमहिषवराहाणामन्यतमस्य सिरां विध्वा रुधिरमामं घृतभृष्टं वा पानं दद्यात् तेनैव वा दर्भपादमृदितेनानुवासयेत् स्निग्धैश्च यूषरसैर्भोजयेत् व्यधादनन्तरं वा पुनस्तामेव सिरां विध्येत् सर्वथा चानवतिष्ठमाने पाचनाय क्षारं दद्यात् सङ्कोचयितुं वा सिरामुखं तप्तशलाकया दहेत् न च क्षणमप्युपेक्षेत क्षीणरक्तस्य हि वायुर्मर्माण्युपसङ्गृह्य मूर्छासंज्ञानाशाशिरःकम्पभ्रममन्यास्तम्भापतानकहनुभ्रंशहिध्मापाण्डुत्वबाधिर्यधातुक्षयाक्षेपकादीन् करोति मरणं वा", text: "atiṣṭhati tu rakte sirāmukhaṃ sandhātuṃ pūrvoktaiścūrṇairavacūrṇyāṅgulyagreṇa pīḍayet śālmalyupodakāpicchāṃ vā vraṇamukhe datvā gāḍhaṃ badhnīyāt madhūcchiṣṭapraliptaṃ vā paṭṭam śītāmbunāvasiñcet śītamadhurakaṣāyānnapānasekapradehapravātaveśmabhirvā skandanāyopacaret padmakādikvāthaṃ śarkarāmadhumadhuraṃ kṣīramikṣurasameṇahariṇājorabhramahiṣavarāhāṇāmanyatamasya sirāṃ vidhvā rudhiramāmaṃ ghṛtabhṛṣṭaṃ vā pānaṃ dadyāt tenaiva vā darbhapādamṛditenānuvāsayet snigdhaiśca yūṣarasairbhojayet vyadhādanantaraṃ vā punastāmeva sirāṃ vidhyet sarvathā cānavatiṣṭhamāne pācanāya kṣāraṃ dadyāt saṅkocayituṃ vā sirāmukhaṃ taptaśalākayā dahet na ca kṣaṇamapyupekṣeta kṣīṇaraktasya hi vāyurmarmāṇyupasaṅgṛhya mūrchāsaṃjñānāśāśiraḥkampabhramamanyāstambhāpatānakahanubhraṃśahidhmāpāṇḍutvabādhiryadhātukṣayākṣepakādīn karoti maraṇaṃ vā" },
      { type: "verse", number: "20", sanskrit: "प्राणः प्राणभृतां रक्तं तत्क्षयात् क्षीयते ऽनलः वर्धनं चानिलस्तस्माद्युक्त्या बृंहणमाचरेत्", text: "prāṇaḥ prāṇabhṛtāṃ raktaṃ tatkṣayāt kṣīyate 'nalaḥ vardhanaṃ cānilastasmādyuktyā bṛṃhaṇamācaret" },
      { type: "verse", number: "21", sanskrit: "अशुद्धं तु रक्तमपराह्णे ऽन्येद्युर्वा पुनः स्रावयेत् ततो ऽपि शेषं सर्वथा वाप्यविस्राव्यरक्तस्य शीतसेकप्रदेहविरेकोपवासस्निग्धमधुरान्नपानैः प्रसादयेत् मासमात्रं वा स्नेहादिभिरुपचर्य पुनर्विध्येत् दुर्व्यधातिव्यधकुटिततिर्यग्व्यधादेर्व्यधदोषाद्व्यापदो याः स्युस्ता यथास्वं साधयेदिति भवति चात्र", text: "aśuddhaṃ tu raktamaparāhṇe 'nyedyurvā punaḥ srāvayet tato 'pi śeṣaṃ sarvathā vāpyavisrāvyaraktasya śītasekapradehavirekopavāsasnigdhamadhurānnapānaiḥ prasādayet māsamātraṃ vā snehādibhirupacarya punarvidhyet durvyadhātivyadhakuṭitatiryagvyadhādervyadhadoṣādvyāpado yāḥ syustā yathāsvaṃ sādhayediti bhavati cātra" },
      { type: "verse", number: "22", sanskrit: "उन्मार्गगा यन्त्रनिपीडनेन स्वस्थानमायान्ति पुनर्न यावत् दोषाः प्रदुष्टा रुधिरं प्रपन्नास्तावद्धिताहारविहारभाक् स्यात्", text: "unmārgagā yantranipīḍanena svasthānamāyānti punarna yāvat doṣāḥ praduṣṭā rudhiraṃ prapannāstāvaddhitāhāravihārabhāk syāt" },
      { type: "verse", number: "23", sanskrit: "नात्युष्णशीतं लघु दीपनीयं रक्ते ऽपनीते हितमन्नपानम् तदा शरीरं ह्यनवस्थितासृगग्निर्विशेषादिति रक्षितव्यः", text: "nātyuṣṇaśītaṃ laghu dīpanīyaṃ rakte 'panīte hitamannapānam tadā śarīraṃ hyanavasthitāsṛgagnirviśeṣāditi rakṣitavyaḥ" },
      { type: "verse", number: "24", sanskrit: "प्रसन्नवर्णेन्द्रियमिन्द्रिथार्थानिच्छन्तमव्याहतपक्तृवेगम् सुखान्वितं पुष्टिबलोपपन्नं विशुद्धरक्तं पुरुषं वदन्ति", text: "prasannavarṇendriyamindrithārthānicchantamavyāhatapaktṛvegam sukhānvitaṃ puṣṭibalopapannaṃ viśuddharaktaṃ puruṣaṃ vadanti" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 37,
    lang: "sa",
    content: [
      { type: "heading", heading: "Кшара карма — щелочное лечение" },
      { type: "text", text: "Глава 37 Сутрастханы Астанга-санграхи посвящена теме «щелочное лечение». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातः शल्याहरणविधिं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ śalyāharaṇavidhiṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "त्रिविधा हि गतिः शल्यानामूर्ध्वमधस्तिर्यक् च सा पुनः प्रत्येकमृजुवक्रभेदेन द्विविधा", text: "trividhā hi gatiḥ śalyānāmūrdhvamadhastiryak ca sā punaḥ pratyekamṛjuvakrabhedena dvividhā" },
      { type: "verse", number: "3", sanskrit: "तत्र ध्यामं पिटकाचितं शोफवेदनावन्तं मुहुर्मुहुः शोणितास्राविणं बुद्बुदवदुद्गतं मृदुमांसं च व्रणं सशल्यं विद्यात्", text: "tatra dhyāmaṃ piṭakācitaṃ śophavedanāvantaṃ muhurmuhuḥ śoṇitāsrāviṇaṃ budbudavadudgataṃ mṛdumāṃsaṃ ca vraṇaṃ saśalyaṃ vidyāt" },
      { type: "verse", number: "4", sanskrit: "विशेषतस्तु त्वग्गते शल्ये विवर्णः शोफो भवत्यायतः कठिनश्च मांसगते शोफाभिवृद्धिः शल्यमार्गानुपसंरोहः पीडनासहिष्णुता चोषः पाकश्च", text: "viśeṣatastu tvaggate śalye vivarṇaḥ śopho bhavatyāyataḥ kaṭhinaśca māṃsagate śophābhivṛddhiḥ śalyamārgānupasaṃrohaḥ pīḍanāsahiṣṇutā coṣaḥ pākaśca" },
      { type: "verse", number: "5", sanskrit: "पेश्यन्तरस्थे शोफवर्ज्यं मांसप्राप्तवत् सिरागते सिराध्मान्ं शूलं च स्नावगते स्नावजालावक्षेपणं संरम्भश्चोग्ररुक्", text: "peśyantarasthe śophavarjyaṃ māṃsaprāptavat sirāgate sirādhmānṃ śūlaṃ ca snāvagate snāvajālāvakṣepaṇaṃ saṃrambhaścograruk" },
      { type: "verse", number: "6", sanskrit: "स्रोतोगते स्रोतसां स्वकर्मगुणहानिः धमनीस्थे सफेनं रक्तमीरयन्ननिलः सशब्दो निर्गच्छत्यङ्गपीडा हृल्लासश्च अस्थिगते विविधा वेदनाः शोफश्च", text: "srotogate srotasāṃ svakarmaguṇahāniḥ dhamanīsthe saphenaṃ raktamīrayannanilaḥ saśabdo nirgacchatyaṅgapīḍā hṛllāsaśca asthigate vividhā vedanāḥ śophaśca" },
      { type: "verse", number: "7", sanskrit: "सन्धिगते ऽस्थिवच्चेष्टोपरोधश्च अस्थिसन्धिगते ऽस्थिपूर्णता सङ्घर्षो बलवांश्च", text: "sandhigate 'sthivacceṣṭoparodhaśca asthisandhigate 'sthipūrṇatā saṅgharṣo balavāṃśca" },
      { type: "verse", number: "8", sanskrit: "कोष्ठगते त्वाटोपानाहौ मूत्रपुरीषाहारदर्शनानि च व्रणमुखाद्भवन्ति मर्मगते मर्मविद्धवत्", text: "koṣṭhagate tvāṭopānāhau mūtrapurīṣāhāradarśanāni ca vraṇamukhādbhavanti marmagate marmaviddhavat" },
      { type: "verse", number: "9", sanskrit: "यथायथं चोपदिष्टैः परिस्रावैस्त्वगादिषु शल्यमुपलक्षयेत् सूक्ष्मगतिषु शल्येष्वेतान्येव लक्षणान्यविस्पष्टानि भवन्ति", text: "yathāyathaṃ copadiṣṭaiḥ parisrāvaistvagādiṣu śalyamupalakṣayet sūkṣmagatiṣu śalyeṣvetānyeva lakṣaṇānyavispaṣṭāni bhavanti" },
      { type: "verse", number: "10", sanskrit: "शुद्धदेहानामनुलोमसन्निविष्टान्युपरुह्यन्ते दोषप्रकोपव्यवायव्यायामाभिघातेभ्यश्च प्रचलितानि पुनराबाधयन्ति", text: "śuddhadehānāmanulomasanniviṣṭānyuparuhyante doṣaprakopavyavāyavyāyāmābhighātebhyaśca pracalitāni punarābādhayanti" },
      { type: "verse", number: "11", sanskrit: "तत्र त्वक्प्रनष्टे स्निग्धस्विन्नायां मृन्माषयवगोधूमगोमयचूर्णमर्दितायां त्वचि यत्र संरम्भो वेदना वा भवति यत्र वा स्त्यानं सर्पिर्निहितमाशु विलीयते प्रलेपो वा शुष्यति तत्र शल्यं जानीयात् मांसप्रनष्टे स्नेहादिभिः क्रियाभिरातुरमुपपादयेत् कर्शितस्य च शिथिलीभूतमनवबद्धं क्षुभ्यमानं यत्र यत्र संरम्भं वेदनां वा जनयति तत्र शल्यम्", text: "tatra tvakpranaṣṭe snigdhasvinnāyāṃ mṛnmāṣayavagodhūmagomayacūrṇamarditāyāṃ tvaci yatra saṃrambho vedanā vā bhavati yatra vā styānaṃ sarpirnihitamāśu vilīyate pralepo vā śuṣyati tatra śalyaṃ jānīyāt māṃsapranaṣṭe snehādibhiḥ kriyābhirāturamupapādayet karśitasya ca śithilībhūtamanavabaddhaṃ kṣubhyamānaṃ yatra yatra saṃrambhaṃ vedanāṃ vā janayati tatra śalyam" },
      { type: "verse", number: "12", sanskrit: "एवं कोष्ठास्त्निपेशीविवरेष्वपि", text: "evaṃ koṣṭhāstnipeśīvivareṣvapi" },
      { type: "verse", number: "13", sanskrit: "सिरास्रोतोधमनीस्नावप्रणष्टे खण्डचक्रमश्वयुक्तं रथमारोप्यातुरं विषमे ऽध्वनि शीघ्रं नयेत् ततः संरम्भादिभिर्जानीयात्", text: "sirāsrotodhamanīsnāvapraṇaṣṭe khaṇḍacakramaśvayuktaṃ rathamāropyāturaṃ viṣame 'dhvani śīghraṃ nayet tataḥ saṃrambhādibhirjānīyāt" },
      { type: "verse", number: "14", sanskrit: "सन्धिप्रणष्टे स्नेहस्वेदोपपन्नं सन्धिं प्रसारणाकुञ्चनबन्धनपीडनैरुपाचरन् पूर्ववदवगच्छेत् अस्थिप्रणष्टे स्निग्धस्विन्नान्यस्थीनि बन्धनपीडनाभ्यां भृशमुपचरंस्तद्वदुपलक्षयेत्", text: "sandhipraṇaṣṭe snehasvedopapannaṃ sandhiṃ prasāraṇākuñcanabandhanapīḍanairupācaran pūrvavadavagacchet asthipraṇaṣṭe snigdhasvinnānyasthīni bandhanapīḍanābhyāṃ bhṛśamupacaraṃstadvadupalakṣayet" },
      { type: "verse", number: "15", sanskrit: "मर्मप्रणष्टे त्वनन्यभावान्मांसादिभ्यो मर्मणामुक्तं परीक्षणं भवति", text: "marmapraṇaṣṭe tvananyabhāvānmāṃsādibhyo marmaṇāmuktaṃ parīkṣaṇaṃ bhavati" },
      { type: "verse", number: "16", sanskrit: "सामान्यलक्षणं तूच्छ्रितहस्तिस्कन्धाश्वमाद्रुरोहणद्रुतयानलङ्घनप्लवनव्यायामैर्जम्भोद्गारकासक्षवथुष्ठीवनहसनप्राणायामैर्मलशुक्रोत्सर्गैर्वा यत्र संरम्भो वेदना वा भवति यत्र वा स्वल्पे ऽप्यायासे स्वापो गौरवं घट्टनं शोफो वा स्यात्तत्र शल्यमादिशेत्", text: "sāmānyalakṣaṇaṃ tūcchritahastiskandhāśvamādrurohaṇadrutayānalaṅghanaplavanavyāyāmairjambhodgārakāsakṣavathuṣṭhīvanahasanaprāṇāyāmairmalaśukrotsargairvā yatra saṃrambho vedanā vā bhavati yatra vā svalpe 'pyāyāse svāpo gauravaṃ ghaṭṭanaṃ śopho vā syāttatra śalyamādiśet" },
      { type: "verse", number: "17", sanskrit: "समासतश्चतुर्विधं शल्यं भवति वृत्तद्वित्रिचतुरस्रभेदेन तददृश्यमानं वृत्तसंस्थानादनुमिमीत", text: "samāsataścaturvidhaṃ śalyaṃ bhavati vṛttadvitricaturasrabhedena tadadṛśyamānaṃ vṛttasaṃsthānādanumimīta" },
      { type: "verse", number: "18", sanskrit: "सर्वशल्यानां महतामाहरणे द्वावेवोपायौ प्रतिलोमो ऽनुलोमश्च", text: "sarvaśalyānāṃ mahatāmāharaṇe dvāvevopāyau pratilomo 'nulomaśca" },
      { type: "verse", number: "19", sanskrit: "तत्र प्रतिलोममर्वाचीनमानयेदनुलोमं पराचीनम् तिर्यग्गतं यतः सुखाहार्यं भवति ततः छित्वापहरेत्", text: "tatra pratilomamarvācīnamānayedanulomaṃ parācīnam tiryaggataṃ yataḥ sukhāhāryaṃ bhavati tataḥ chitvāpaharet" },
      { type: "verse", number: "20", sanskrit: "प्रतिलोममनुत्तुण्डितं छेदनीयं पृथुमुखं च शल्यं निर्घातयेत् तथा कक्ष्यावङ्क्षणोरःपरशुकान्तरपतितानि", text: "pratilomamanuttuṇḍitaṃ chedanīyaṃ pṛthumukhaṃ ca śalyaṃ nirghātayet tathā kakṣyāvaṅkṣaṇoraḥparaśukāntarapatitāni" },
      { type: "verse", number: "21", sanskrit: "नैव चाहरेद्विशल्यघ्नं मर्मप्रणष्टं वाशोफवेदनं पाकविरहितम्", text: "naiva cāharedviśalyaghnaṃ marmapraṇaṣṭaṃ vāśophavedanaṃ pākavirahitam" },
      { type: "verse", number: "22", sanskrit: "अथ हस्तप्राप्यं शल्यं हस्तेनाहरेत् तदशक्यं यथायथं यन्त्रेण तथाप्यशक्यं शस्त्रेण विशस्य ततो निर्लोहितं व्रणं कृत्वाग्निघृतमधुप्रभृतिभिः स्वेदयित्वावदह्य तर्पयित्वा सर्पिर्मधुभ्यां बध्वाचारिकमादिशेत् सिरास्नावलग्नं शलाकाग्रेणाभिमोच्याहरेत् हृदये ऽभिवर्तमानं शल्यं शीतजलादिभिरुद्वेजितस्याहरेत् यथामार्गं दुराहरमन्यतो ऽप्येवमाहरेत्", text: "atha hastaprāpyaṃ śalyaṃ hastenāharet tadaśakyaṃ yathāyathaṃ yantreṇa tathāpyaśakyaṃ śastreṇa viśasya tato nirlohitaṃ vraṇaṃ kṛtvāgnighṛtamadhuprabhṛtibhiḥ svedayitvāvadahya tarpayitvā sarpirmadhubhyāṃ badhvācārikamādiśet sirāsnāvalagnaṃ śalākāgreṇābhimocyāharet hṛdaye 'bhivartamānaṃ śalyaṃ śītajalādibhirudvejitasyāharet yathāmārgaṃ durāharamanyato 'pyevamāharet" },
      { type: "verse", number: "23", sanskrit: "अस्थिविवरप्रणष्टमस्थिविदष्टं वावगृह्य पद्भ्यां पुरुषं यन्त्रेणापकर्षेत् अशक्यमेवं वा बलवद्भिः सुगृहीतस्य यन्त्रेण ग्राहयित्वा शल्यवारङ्गं प्रतिभुज्य वा धनुर्गुणैरेकतो बध्वान्यतश्च पञ्चाङ्ग्या सुसंयतस्याश्वस्य वक्त्रकटके बध्नीयात् अथैनमेवं कशया ताडयेद्यथोन्नमयञ्छिरो वेगेन शल्यमुद्धरति", text: "asthivivarapraṇaṣṭamasthividaṣṭaṃ vāvagṛhya padbhyāṃ puruṣaṃ yantreṇāpakarṣet aśakyamevaṃ vā balavadbhiḥ sugṛhītasya yantreṇa grāhayitvā śalyavāraṅgaṃ pratibhujya vā dhanurguṇairekato badhvānyataśca pañcāṅgyā susaṃyatasyāśvasya vaktrakaṭake badhnīyāt athainamevaṃ kaśayā tāḍayedyathonnamayañchiro vegena śalyamuddharati" },
      { type: "verse", number: "24", sanskrit: "दृढां वा वृक्षशाखामवनम्य तम्यां पूर्ववद् बध्वोद्धरेत्", text: "dṛḍhāṃ vā vṛkṣaśākhāmavanamya tamyāṃ pūrvavad badhvoddharet" },
      { type: "verse", number: "25", sanskrit: "दुर्बलवारङ्गं तु कुशाभिर्बध्वा श्वयथुग्रस्तवारङ्गमुत्पीड्य श्वयथुम्", text: "durbalavāraṅgaṃ tu kuśābhirbadhvā śvayathugrastavāraṅgamutpīḍya śvayathum" },
      { type: "verse", number: "26", sanskrit: "अदेशोत्तुण्डितमश्ममुद्गरप्रहारेण विचाल्य यथामार्गमेव", text: "adeśottuṇḍitamaśmamudgaraprahāreṇa vicālya yathāmārgameva" },
      { type: "verse", number: "27", sanskrit: "कर्णवत्तु यन्त्रेण विमृदितकर्णं कृत्वा नाडीयन्त्रेण व बहुमुखेन यथास्वमुपसङ्गृह्य शलाकायन्त्रेणान्येन वा पूर्ववदाहरेत् अनुलोममकर्णमनल्पव्रणमुखमयस्कान्तेन पक्वाशयगतं विरेचनेन", text: "karṇavattu yantreṇa vimṛditakarṇaṃ kṛtvā nāḍīyantreṇa va bahumukhena yathāsvamupasaṅgṛhya śalākāyantreṇānyena vā pūrvavadāharet anulomamakarṇamanalpavraṇamukhamayaskāntena pakvāśayagataṃ virecanena" },
      { type: "verse", number: "28", sanskrit: "वातविण्मूत्रगर्भसङ्गं प्रवाहणेन दुष्टवातविषस्तन्यादीन्यास्यविषाणचूषणेन", text: "vātaviṇmūtragarbhasaṅgaṃ pravāhaṇena duṣṭavātaviṣastanyādīnyāsyaviṣāṇacūṣaṇena" },
      { type: "verse", number: "29", sanskrit: "कण्ठस्रोतोगते तु शल्ये बिसं सक्तं सूत्रं कण्ठे प्रवेशयेत् अथ तद्गृहीतं विज्ञाय शल्यं सममेव सूत्रं बिसं चाक्षिपेत् बिसाभावे मृणाले ऽप्ययमेव विधिः जातुषे तु कण्ठसक्ते कण्ठे नाडीं प्रवेशयेत्तदा चाग्नितप्तां सूक्ष्ममुखीं शलाकामथ तां गृहीतशल्यां शीताभिरद्भिः परिषिच्य स्थिरीभूतामाहरेत् अजातुषे ऽप्येवमेव प्रतप्तां जतुमधूच्छिष्टान्यतरप्रदिग्धां शलाकाम् मत्स्यकण्टकमन्यद्वा तादृगस्थिशल्यं कण्ठलग्नं सूत्रेण सूत्रप्लोतेन वा वेष्टितयांगुल्यापहरेत् अथवा केशोण्डुकं दृढदीर्घसूत्रबद्धं द्रवोपहितं पाययेद्वामयेच्च वमतश्च शल्यैकदेशसक्तं सूत्रं सहसैवाक्षिपेत् मृदुना वा दन्तधावनकूर्च्चेनापहरेत् परतो वा प्रणुदेत् वालोण्डुके विलग्ने तद्वत् कण्टकम्", text: "kaṇṭhasrotogate tu śalye bisaṃ saktaṃ sūtraṃ kaṇṭhe praveśayet atha tadgṛhītaṃ vijñāya śalyaṃ samameva sūtraṃ bisaṃ cākṣipet bisābhāve mṛṇāle 'pyayameva vidhiḥ jātuṣe tu kaṇṭhasakte kaṇṭhe nāḍīṃ praveśayettadā cāgnitaptāṃ sūkṣmamukhīṃ śalākāmatha tāṃ gṛhītaśalyāṃ śītābhiradbhiḥ pariṣicya sthirībhūtāmāharet ajātuṣe 'pyevameva prataptāṃ jatumadhūcchiṣṭānyatarapradigdhāṃ śalākām matsyakaṇṭakamanyadvā tādṛgasthiśalyaṃ kaṇṭhalagnaṃ sūtreṇa sūtraplotena vā veṣṭitayāṃgulyāpaharet athavā keśoṇḍukaṃ dṛḍhadīrghasūtrabaddhaṃ dravopahitaṃ pāyayedvāmayecca vamataśca śalyaikadeśasaktaṃ sūtraṃ sahasaivākṣipet mṛdunā vā dantadhāvanakūrccenāpaharet parato vā praṇudet vāloṇḍuke vilagne tadvat kaṇṭakam" },
      { type: "verse", number: "30", sanskrit: "क्षतकण्ठश्च त्रिफलाचूर्णं मधुघृतसितोपेतमनुकण्ठयन् लिह्यात्", text: "kṣatakaṇṭhaśca triphalācūrṇaṃ madhughṛtasitopetamanukaṇṭhayan lihyāt" },
      { type: "verse", number: "31", sanskrit: "अपां पूर्णं पुरुषमवाक्चिरसमवपीडयेद्धुनुयाद्वामयेच्च भस्मराशौ वा निखन्यादामुखात् अन्यथा ह्युन्मार्गगामिभिरद्भिराध्मानकासश्वासपीनसेन्द्रियोपघातज्वरादयः श्लेष्मविकारा मृत्युश्च तत्र यथास्वं कफे प्रतिकुर्यात् ग्रासशल्यमम्बुना प्रवेशयेत् स्कन्धे वा मुष्टिनाभिहन्यात्", text: "apāṃ pūrṇaṃ puruṣamavākcirasamavapīḍayeddhunuyādvāmayecca bhasmarāśau vā nikhanyādāmukhāt anyathā hyunmārgagāmibhiradbhirādhmānakāsaśvāsapīnasendriyopaghātajvarādayaḥ śleṣmavikārā mṛtyuśca tatra yathāsvaṃ kaphe pratikuryāt grāsaśalyamambunā praveśayet skandhe vā muṣṭinābhihanyāt" },
      { type: "verse", number: "32", sanskrit: "तथा निर्भुज्य वर्त्म वर्त्मगतमपनीय चोष्णाम्बुबाष्पस्वेदं समधुमधुकक्वाथेन सर्पिषा च परिषेकं कुर्यात् स्वयमपि शल्यमश्रुक्षवथुकासोद्गारमूत्रपुरीषानिलैर्नयनादिभ्यो ऽङ्गावयवेभ्यः पतति", text: "tathā nirbhujya vartma vartmagatamapanīya coṣṇāmbubāṣpasvedaṃ samadhumadhukakvāthena sarpiṣā ca pariṣekaṃ kuryāt svayamapi śalyamaśrukṣavathukāsodgāramūtrapurīṣānilairnayanādibhyo 'ṅgāvayavebhyaḥ patati" },
      { type: "verse", number: "33", sanskrit: "कीटे कर्णस्रोतःप्रविष्टे तोदो गौरवं भरभरायमाणं च भवति स्पन्दमाने चाप्यधिकं वेदना तत्र सलवणेनाम्बुना मधुकयुक्तेन मद्येन वा सुखोष्णेन पूरणम् निर्गते च कीटे तदुत्सर्जनम् तत्रैव तु मृते पाककोथक्लेदा भवन्ति तेषु कर्णस्रावोक्तं कुर्यात् प्रतीनाहोक्तं च तोयपूर्णं कर्णं हस्तोन्मथितेन तैलाम्बुना पूरयेत् पार्श्वावनतं वा कृत्वा हस्तेनाहन्यान्नाड्या वा चूषयेत् भवन्ति चात्र श्लोकाः", text: "kīṭe karṇasrotaḥpraviṣṭe todo gauravaṃ bharabharāyamāṇaṃ ca bhavati spandamāne cāpyadhikaṃ vedanā tatra salavaṇenāmbunā madhukayuktena madyena vā sukhoṣṇena pūraṇam nirgate ca kīṭe tadutsarjanam tatraiva tu mṛte pākakothakledā bhavanti teṣu karṇasrāvoktaṃ kuryāt pratīnāhoktaṃ ca toyapūrṇaṃ karṇaṃ hastonmathitena tailāmbunā pūrayet pārśvāvanataṃ vā kṛtvā hastenāhanyānnāḍyā vā cūṣayet bhavanti cātra ślokāḥ" },
      { type: "verse", number: "34", sanskrit: "जाउषं हेमरूप्यादिधातुजं च चिरस्थितम् ऊष्मणा प्रायशः शल्यं देहजेन विलीयते", text: "jāuṣaṃ hemarūpyādidhātujaṃ ca cirasthitam ūṣmaṇā prāyaśaḥ śalyaṃ dehajena vilīyate" },
      { type: "verse", number: "35", sanskrit: "विषाणवेणुदार्वस्थिदन्तवालोपलानि तु शल्यानि न विशीर्यन्ते शरीरे मृन्मयानि च", text: "viṣāṇaveṇudārvasthidantavālopalāni tu śalyāni na viśīryante śarīre mṛnmayāni ca" },
      { type: "verse", number: "36", sanskrit: "विषाणवेण्वयस्तालदारुशल्यं चिरादपि प्रायो निर्भुज्यते तद्धि पचत्याशु पलासृजी", text: "viṣāṇaveṇvayastāladāruśalyaṃ cirādapi prāyo nirbhujyate taddhi pacatyāśu palāsṛjī" },
      { type: "verse", number: "37", sanskrit: "शल्ये मांसावगाढे चेत् स देशो न विदह्यते ततस्तं मर्दनस्वेदशुद्धिकर्शनबृंहणैः", text: "śalye māṃsāvagāḍhe cet sa deśo na vidahyate tatastaṃ mardanasvedaśuddhikarśanabṛṃhaṇaiḥ" },
      { type: "verse", number: "38", sanskrit: "तीक्ष्णोपनाहपानान्नघनशस्त्रपदाङ्कनैः पाचयित्वा हरेच्छल्यं पाटनैषणपीडनैः", text: "tīkṣṇopanāhapānānnaghanaśastrapadāṅkanaiḥ pācayitvā harecchalyaṃ pāṭanaiṣaṇapīḍanaiḥ" },
      { type: "verse", number: "39", sanskrit: "शल्यप्रदेशयन्त्राणामवेक्ष्य बहुरूपताम् तैस्तैरुपायैर्मतिमान् शल्यं विद्यात्तथाहरेत्", text: "śalyapradeśayantrāṇāmavekṣya bahurūpatām taistairupāyairmatimān śalyaṃ vidyāttathāharet" },
      { type: "verse", number: "40", sanskrit: "व्रणे प्रशान्ते प्रान्तेषु नातिस्पर्शासहिष्णुषु अल्पे शोफे च तापे च निःशल्यमिति निर्दिशेत्", text: "vraṇe praśānte prānteṣu nātisparśāsahiṣṇuṣu alpe śophe ca tāpe ca niḥśalyamiti nirdiśet" },
      { type: "verse", number: "41", sanskrit: "काय एव परं शल्यं निजदोषमलाविलः शल्ये शल्यं शराद्यं तु विशेषात्तेन चिन्त्यते", text: "kāya eva paraṃ śalyaṃ nijadoṣamalāvilaḥ śalye śalyaṃ śarādyaṃ tu viśeṣāttena cintyate" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 38,
    lang: "sa",
    content: [
      { type: "heading", heading: "Янтра видхи — хирургические инструменты" },
      { type: "text", text: "Глава 38 Сутрастханы Астанга-санграхи посвящена теме «хирургические инструменты». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातः शस्त्रकर्मविधिं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ śastrakarmavidhiṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "द्विविधे हि व्याधावुपायापेक्षे निज गागन्तौ वा भेषजविषयातीते शस्त्रकर्म प्रयुज्यते", text: "dvividhe hi vyādhāvupāyāpekṣe nija gāgantau vā bheṣajaviṣayātīte śastrakarma prayujyate" },
      { type: "verse", number: "3", sanskrit: "स चामयः प्रायेण श्वयथुपूर्वको भवत्यतः शोफावस्थस्यैव वातपित्तकफरक्तसंसर्गसन्निपातात्मकतामुपलक्ष्य पाकभयाद्यथास्वमुपवासलेपसेकासृङ्मोक्षकषायघृतपानशोधनानि प्रयुञ्जीत", text: "sa cāmayaḥ prāyeṇa śvayathupūrvako bhavatyataḥ śophāvasthasyaiva vātapittakapharaktasaṃsargasannipātātmakatāmupalakṣya pākabhayādyathāsvamupavāsalepasekāsṛṅmokṣakaṣāyaghṛtapānaśodhanāni prayuñjīta" },
      { type: "verse", number: "4", sanskrit: "तथाप्यनुपशाम्यति प्रविलयनम् अविलीयमाने चोपनाहनम्", text: "tathāpyanupaśāmyati pravilayanam avilīyamāne copanāhanam" },
      { type: "verse", number: "5", sanskrit: "तत्र शोफस्यामलक्षणमल्पता चाल्पोष्मरुजत्वं त्वक्सवर्णता स्थैर्यं च", text: "tatra śophasyāmalakṣaṇamalpatā cālpoṣmarujatvaṃ tvaksavarṇatā sthairyaṃ ca" },
      { type: "verse", number: "6", sanskrit: "पच्यमानस्तु विवर्णो बस्तिरिवाततः संरम्भशूलरागदाहोषारुचितृष्णाज्वरारतिस्पर्शासहत्वानिद्रतासमन्वितो विष्यन्दयति सर्पिः शोषयति प्रदेहं सर्षपकल्कोपलिप्त इव चिमिचिमायते पिपीलिकाभिरिव संसर्प्यते पीड्यत इव पाणिना घट्यत इवाङ्गुल्या ताड्यत इव दण्डेन तुद्यत इव सूचीभिर्भिद्यत इव शक्तिभिश्छिद्यत इव शस्त्रेण दश्यत इव वृश्चिकैर्दह्यत इवाग्निक्षाराभ्यां मथ्यत इवोमुल्केन", text: "pacyamānastu vivarṇo bastirivātataḥ saṃrambhaśūlarāgadāhoṣārucitṛṣṇājvarāratisparśāsahatvānidratāsamanvito viṣyandayati sarpiḥ śoṣayati pradehaṃ sarṣapakalkopalipta iva cimicimāyate pipīlikābhiriva saṃsarpyate pīḍyata iva pāṇinā ghaṭyata ivāṅgulyā tāḍyata iva daṇḍena tudyata iva sūcībhirbhidyata iva śaktibhiśchidyata iva śastreṇa daśyata iva vṛścikairdahyata ivāgnikṣārābhyāṃ mathyata ivomulkena" },
      { type: "verse", number: "7", sanskrit: "पक्वे तु गतवेगत्वं प्रम्लानता त्वक्शिथिलता वलीप्रादुर्भावः पाण्डुता मध्योन्नतताङ्गुल्यवपीडितमुक्ते प्रत्युन्नमनं बस्ताविवोदकस्य पूयस्य सञ्चरणं कण्डूः संरम्भशूलाद्युपशमश्च", text: "pakve tu gatavegatvaṃ pramlānatā tvakśithilatā valīprādurbhāvaḥ pāṇḍutā madhyonnatatāṅgulyavapīḍitamukte pratyunnamanaṃ bastāvivodakasya pūyasya sañcaraṇaṃ kaṇḍūḥ saṃrambhaśūlādyupaśamaśca" },
      { type: "verse", number: "8", sanskrit: "शूलं नर्ते ऽनिलाद्दाहः पिताच्छोफः कफोदयात् रागो रक्ताच्च पाकःस्यादतो दोषैः सशोणितैः", text: "śūlaṃ narte 'nilāddāhaḥ pitācchophaḥ kaphodayāt rāgo raktācca pākaḥsyādato doṣaiḥ saśoṇitaiḥ" },
      { type: "verse", number: "9", sanskrit: "पाके ऽतिवृत्ते सुषिरस्तनुत्वग्दोषभाक्षितः वलीभिराचितः श्यावः शीर्यमाण्तनूरुहः", text: "pāke 'tivṛtte suṣirastanutvagdoṣabhākṣitaḥ valībhirācitaḥ śyāvaḥ śīryamāṇtanūruhaḥ" },
      { type: "verse", number: "10", sanskrit: "कफजेषु तु शोफेषु केषुचित् गम्भीरत्वाद्रक्तमेव विपच्यते ततश्चास्पष्टं पक्वलिङ्गं भवति यत्र हि त्वक्सावर्ण्यं शीतशोफतल्परुजताश्मवच्च घनता न तत्र मोहमुपेयात् तं रक्तपाकमित्याचक्षते", text: "kaphajeṣu tu śopheṣu keṣucit gambhīratvādraktameva vipacyate tataścāspaṣṭaṃ pakvaliṅgaṃ bhavati yatra hi tvaksāvarṇyaṃ śītaśophatalparujatāśmavacca ghanatā na tatra mohamupeyāt taṃ raktapākamityācakṣate" },
      { type: "verse", number: "11", sanskrit: "अथैनं सम्यक्पक्वमवधार्य भीरुवृद्धबालदुर्बलक्लीबक्षीणगर्भिणीविषार्दितशस्त्रक्षामेषु पाकोद्धतदोषेषु च पिण्डितेषु सन्धिमर्माश्रितेष्वल्पेषु वा शोफेषु तीक्ष्णोष्णद्रव्यैर्दारणं कुर्वीत इतरेषु तु पाटनम्", text: "athainaṃ samyakpakvamavadhārya bhīruvṛddhabāladurbalaklībakṣīṇagarbhiṇīviṣārditaśastrakṣāmeṣu pākoddhatadoṣeṣu ca piṇḍiteṣu sandhimarmāśriteṣvalpeṣu vā śopheṣu tīkṣṇoṣṇadravyairdāraṇaṃ kurvīta itareṣu tu pāṭanam" },
      { type: "verse", number: "12", sanskrit: "आमपाटने सिरास्नायुव्यापादनं शोणितातिप्रवृत्तिर्वेदनातिवृद्धिरवदरणं क्षतविसर्पो वा स्यात् भवति चात्र", text: "āmapāṭane sirāsnāyuvyāpādanaṃ śoṇitātipravṛttirvedanātivṛddhiravadaraṇaṃ kṣatavisarpo vā syāt bhavati cātra" },
      { type: "verse", number: "13", sanskrit: "पिष्ठन् पक्वे पुनः पूयः सिरास्नाय्वसृङामिषम् विवृद्धो दहति क्षिप्रं तृणोलपमिवानलः", text: "piṣṭhan pakve punaḥ pūyaḥ sirāsnāyvasṛṅāmiṣam vivṛddho dahati kṣipraṃ tṛṇolapamivānalaḥ" },
      { type: "verse", number: "14", sanskrit: "यश्छिनत्त्यममज्ञानाद्यश्च पक्वमुपेक्षते श्वपचाविव विज्ञेयौ तावनिश्चितकारिणौ", text: "yaśchinattyamamajñānādyaśca pakvamupekṣate śvapacāviva vijñeyau tāvaniścitakāriṇau" },
      { type: "verse", number: "15", sanskrit: "प्राक् शस्त्राद्भोजयेदिष्टं तीक्ष्णं मद्यं च पाययेत् न मूर्छत्यन्नसंयोगान्मत्तः शस्त्रं न बुध्यते", text: "prāk śastrādbhojayediṣṭaṃ tīkṣṇaṃ madyaṃ ca pāyayet na mūrchatyannasaṃyogānmattaḥ śastraṃ na budhyate" },
      { type: "verse", number: "16", sanskrit: "अन्यत्र मूढगर्भोदराश्मरीमुखरोगेभ्यः अथोपहृतयन्त्रशस्त्रक्षाराग्निजाम्बवौष्ठपिचुप्लोतपत्रसूत्रचर्मपट्टमधुस्नेहकषायालेपकल्कसेकोदकुम्भशीतोष्णोदककटाहव्यजनादिव्रणोपयोगिसर्वोपकरणमाश्रितशयनीयमुपस्थितस्थिरस्नेहबलवदवलम्बकपुरुषमिष्टे ऽहनिमुहूर्ते च दध्यक्षतान्नपानरुक्मरत्नार्चितविप्रं प्रणतेष्टदेवतं कृतमङ्गलं भुक्तवन्तमातुरं प्राङ्मुखमुपवेश्य संवेश्य वा यन्त्रयित्वा प्रत्यङ्मुखो वैद्यो मर्मसिरास्नायुसन्ध्यस्थिधमनीः परिहरन्ननुलोमं शस्त्रं निदध्यादापूयदर्शनात् सकृदेवाहरेच्छस्त्रमाशु च", text: "anyatra mūḍhagarbhodarāśmarīmukharogebhyaḥ athopahṛtayantraśastrakṣārāgnijāmbavauṣṭhapicuplotapatrasūtracarmapaṭṭamadhusnehakaṣāyālepakalkasekodakumbhaśītoṣṇodakakaṭāhavyajanādivraṇopayogisarvopakaraṇamāśritaśayanīyamupasthitasthirasnehabalavadavalambakapuruṣamiṣṭe 'hanimuhūrte ca dadhyakṣatānnapānarukmaratnārcitavipraṃ praṇateṣṭadevataṃ kṛtamaṅgalaṃ bhuktavantamāturaṃ prāṅmukhamupaveśya saṃveśya vā yantrayitvā pratyaṅmukho vaidyo marmasirāsnāyusandhyasthidhamanīḥ pariharannanulomaṃ śastraṃ nidadhyādāpūyadarśanāt sakṛdevāharecchastramāśu ca" },
      { type: "verse", number: "17", sanskrit: "महत्स्वपि च पाकेषु द्व्यङ्गुलं शस्त्रपदमुक्तम् द्व्यङ्गुलान्तरं त्र्यङ्गुलान्तरं वाभिसमीक्ष्य विवृत्ते प्रदेशे वामप्रदेशिन्यैषित्वा नातिविवृत्ते गम्भीरमांसले चैषण्या विपरीते करीरादिनालेनातिसंवृते सूकरवालेन वा", text: "mahatsvapi ca pākeṣu dvyaṅgulaṃ śastrapadamuktam dvyaṅgulāntaraṃ tryaṅgulāntaraṃ vābhisamīkṣya vivṛtte pradeśe vāmapradeśinyaiṣitvā nātivivṛtte gambhīramāṃsale caiṣaṇyā viparīte karīrādinālenātisaṃvṛte sūkaravālena vā" },
      { type: "verse", number: "18", sanskrit: "यतो गतां गतिं विद्यादुत्सङ्गो यत्र यत्र च तत्र तत्र व्रणं कुर्यात् सुविभक्तं निराशयम् आयतं च विशालं च यथा दोषो न तिष्ठति", text: "yato gatāṃ gatiṃ vidyādutsaṅgo yatra yatra ca tatra tatra vraṇaṃ kuryāt suvibhaktaṃ nirāśayam āyataṃ ca viśālaṃ ca yathā doṣo na tiṣṭhati" },
      { type: "verse", number: "19", sanskrit: "शौर्यमाशुक्रिया तीक्ष्णं शस्त्रमस्वेदवेपथू असम्मोहश्च वैद्यस्य शस्त्रकर्मणि शस्यते", text: "śauryamāśukriyā tīkṣṇaṃ śastramasvedavepathū asammohaśca vaidyasya śastrakarmaṇi śasyate" },
      { type: "verse", number: "20", sanskrit: "तत्र भ्रूगण्डललाटाक्षिकूटौष्ठदन्तवेष्टमन्याकण्ठजत्रुकक्ष्याकुक्षिवङ्क्षणेषु तिर्यक्छेद इष्टः अन्यत्र तु सिरास्नायूपघातो ऽतिवेदना चिराद् व्रणसंरोहो मांसस्कन्दी च तिर्यक्छेदात् भवन्ति", text: "tatra bhrūgaṇḍalalāṭākṣikūṭauṣṭhadantaveṣṭamanyākaṇṭhajatrukakṣyākukṣivaṅkṣaṇeṣu tiryakcheda iṣṭaḥ anyatra tu sirāsnāyūpaghāto 'tivedanā cirād vraṇasaṃroho māṃsaskandī ca tiryakchedāt bhavanti" },
      { type: "verse", number: "21", sanskrit: "ततः शस्त्रमवचार्य शीताभिरद्भिरातुरमाश्वास्य समन्तात् प्रतिपीड्याङ्गुल्या व्रणमपि प्रक्षाल्य कषायेण व्रणात् प्लोतेनाम्भो ऽपनीय वेदनारक्षोघ्नैर्गुग्गुल्वगरुसर्जरसवचागौरसर्षपहिङ्गुलवणनिम्बपत्रैः सघृतैर्व्रणं धूपयित्वा यथास्वमौषधेन मधुघृततिलकल्कैश्च दिग्धां वतिं प्रणिधाय कल्केन पूरयित्वा नातिभृष्टयवसक्तुभिर्घृताक्तैर्भाजनान्ते ऽम्भसा दक्षिणाङ्गुलीभिः सुमृदितैरवच्छाद्य घनां कबलिकां दत्वा सव्यदक्षिणान्यतरपार्श्वे ऋजुमनाविद्धमसङ्कुचितं मृदुपट्टं निवेश्य बध्नीयात्", text: "tataḥ śastramavacārya śītābhiradbhirāturamāśvāsya samantāt pratipīḍyāṅgulyā vraṇamapi prakṣālya kaṣāyeṇa vraṇāt plotenāmbho 'panīya vedanārakṣoghnairguggulvagarusarjarasavacāgaurasarṣapahiṅgulavaṇanimbapatraiḥ saghṛtairvraṇaṃ dhūpayitvā yathāsvamauṣadhena madhughṛtatilakalkaiśca digdhāṃ vatiṃ praṇidhāya kalkena pūrayitvā nātibhṛṣṭayavasaktubhirghṛtāktairbhājanānte 'mbhasā dakṣiṇāṅgulībhiḥ sumṛditairavacchādya ghanāṃ kabalikāṃ datvā savyadakṣiṇānyatarapārśve ṛjumanāviddhamasaṅkucitaṃ mṛdupaṭṭaṃ niveśya badhnīyāt" },
      { type: "verse", number: "22", sanskrit: "वातश्लेष्मोद्भवांस्तत्र द्विस्त्रिर्वा वेष्टयेद् व्रणान् सकृदेव परिक्षिप्य पित्तरक्ताभिघातजान्", text: "vātaśleṣmodbhavāṃstatra dvistrirvā veṣṭayed vraṇān sakṛdeva parikṣipya pittaraktābhighātajān" },
      { type: "verse", number: "23", sanskrit: "शस्त्रक्षतरुजायां तु प्रततायां यष्टीमधुकसर्पिषोष्णेन व्रणं सिञ्चेत् उदकुम्भाच्चापो गृहीत्वा प्रोक्षयन् परितो विकीर्य पर्णशबर्यादिभिरस्य रक्षां कुर्याद्रक्षो ऽभिभवनिषेधार्थम् तेभ्यश्च बलिमुपहरेत् धारयेच्च शिरसा", text: "śastrakṣatarujāyāṃ tu pratatāyāṃ yaṣṭīmadhukasarpiṣoṣṇena vraṇaṃ siñcet udakumbhāccāpo gṛhītvā prokṣayan parito vikīrya parṇaśabaryādibhirasya rakṣāṃ kuryādrakṣo 'bhibhavaniṣedhārtham tebhyaśca balimupaharet dhārayecca śirasā" },
      { type: "verse", number: "24", sanskrit: "लक्ष्मीं गुहामतिगुहां जटिलां ब्रह्मचारिणीम् वचां छत्रामतिच्छत्रां दूर्वां सिद्धार्थकानपि", text: "lakṣmīṃ guhāmatiguhāṃ jaṭilāṃ brahmacāriṇīm vacāṃ chatrāmaticchatrāṃ dūrvāṃ siddhārthakānapi" },
      { type: "verse", number: "25", sanskrit: "गुग्गुल्वादिभिरेवं शयनासनादि द्विरह्नो धूपयेत् तथा स्नेहोक्तं दिनचर्योक्तं चाचारमनुवर्तेत", text: "guggulvādibhirevaṃ śayanāsanādi dvirahno dhūpayet tathā snehoktaṃ dinacaryoktaṃ cācāramanuvarteta" },
      { type: "verse", number: "26", sanskrit: "विशेषतश्च दिवास्वप्नाद् व्रणे शोफकण्डूरागरुक्पूयवृद्धिः", text: "viśeṣataśca divāsvapnād vraṇe śophakaṇḍūrāgarukpūyavṛddhiḥ" },
      { type: "verse", number: "27", sanskrit: "स्त्रीणां तु स्मृतिसंस्पर्शदर्शनैश्चलिते स्रुते शुक्रे व्यवायजान् दोषानसंसर्गे ऽप्यवाप्नुयात्", text: "strīṇāṃ tu smṛtisaṃsparśadarśanaiścalite srute śukre vyavāyajān doṣānasaṃsarge 'pyavāpnuyāt" },
      { type: "verse", number: "28", sanskrit: "भोजयेच्चैनं यथासात्म्यं समातीतशालिषष्टिकयवगोधूमान्यतमं मुद्गमसूराढकीसतीनयूषजाङ्गलरसोपेतं जीवन्तीसुनिषण्णकतण्डुलीयकवास्तुकवार्ताकपटोलकारवेल्लकबालमूलशशाकयुक्तं दाडिमामलकसैन्धवसहितं सर्पिःस्निग्धं लघ्वल्पमुष्णोदकोत्तरं च एवमस्य सम्यगशितं जरामुपैति अजीर्णादनिलादीनां विभ्रमो बलवाअन् भवेत् ततः शोफरुजापाक दाहानाहानवाप्नुयात्", text: "bhojayeccainaṃ yathāsātmyaṃ samātītaśāliṣaṣṭikayavagodhūmānyatamaṃ mudgamasūrāḍhakīsatīnayūṣajāṅgalarasopetaṃ jīvantīsuniṣaṇṇakataṇḍulīyakavāstukavārtākapaṭolakāravellakabālamūlaśaśākayuktaṃ dāḍimāmalakasaindhavasahitaṃ sarpiḥsnigdhaṃ laghvalpamuṣṇodakottaraṃ ca evamasya samyagaśitaṃ jarāmupaiti ajīrṇādanilādīnāṃ vibhramo balavāan bhavet tataḥ śopharujāpāka dāhānāhānavāpnuyāt" },
      { type: "verse", number: "29", sanskrit: "नवधान्यमाषकलायकुलत्थनिष्पावशिम्बीशीताम्बुमद्येक्षुक्षीरपिष्टतिलविकृतिशुष्कशाकपिशितहरितशाकाम्ललवणकटुकक्षारानूपामिषाणि वर्जयेत्", text: "navadhānyamāṣakalāyakulatthaniṣpāvaśimbīśītāmbumadyekṣukṣīrapiṣṭatilavikṛtiśuṣkaśākapiśitaharitaśākāmlalavaṇakaṭukakṣārānūpāmiṣāṇi varjayet" },
      { type: "verse", number: "30", sanskrit: "वर्गो ऽयं नवधान्यादिर्व्रणिनः सर्वदोषकृत् मद्यं तीक्ष्णोष्णरूक्षाम्लमाशुव्यापादयेद् व्रणम्", text: "vargo 'yaṃ navadhānyādirvraṇinaḥ sarvadoṣakṛt madyaṃ tīkṣṇoṣṇarūkṣāmlamāśuvyāpādayed vraṇam" },
      { type: "verse", number: "31", sanskrit: "बालोशीरैश्च वीज्येत नचैनं परिघट्टयेत् न तुदेन्नव कण्डूयेच्चेष्टमानश्च पालयेत्", text: "bālośīraiśca vījyeta nacainaṃ parighaṭṭayet na tudennava kaṇḍūyecceṣṭamānaśca pālayet" },
      { type: "verse", number: "32", sanskrit: "स्निग्धवृद्धद्विजातीनां कथाः शृण्वन्मनःप्रियाः आशावान् व्याधिमोक्षाय क्षिप्रं व्रणमपोहति", text: "snigdhavṛddhadvijātīnāṃ kathāḥ śṛṇvanmanaḥpriyāḥ āśāvān vyādhimokṣāya kṣipraṃ vraṇamapohati" },
      { type: "verse", number: "33", sanskrit: "पुनश्च तृतीये ऽहनि पक्षालनादि पूर्ववत् व्रणकर्म कुर्यात् द्वितीये दिवसे मोक्षणाद्विग्रथितो व्रणश्चिरादुपरोहत्युग्ररुजश्च भवति", text: "punaśca tṛtīye 'hani pakṣālanādi pūrvavat vraṇakarma kuryāt dvitīye divase mokṣaṇādvigrathito vraṇaścirāduparohatyugrarujaśca bhavati" },
      { type: "verse", number: "34", sanskrit: "न च विकेशिकामौषधं वातिस्निग्धरूक्षमतिश्लथमतिगाढमश्लक्ष्णं दुर्न्यस्तं वा दद्यात् अतिस्नेहात् क्लेदः अतिरौक्ष्यात् छेदो वेदना च अतिश्लथत्वादपरिशुद्धिः गाढतया संरम्भ अश्लक्ष्णत्वाद्दुर्न्यासाच्च व्रणवर्त्मोपघर्षणम्", text: "na ca vikeśikāmauṣadhaṃ vātisnigdharūkṣamatiślathamatigāḍhamaślakṣṇaṃ durnyastaṃ vā dadyāt atisnehāt kledaḥ atiraukṣyāt chedo vedanā ca atiślathatvādapariśuddhiḥ gāḍhatayā saṃrambha aślakṣṇatvāddurnyāsācca vraṇavartmopagharṣaṇam" },
      { type: "verse", number: "35", sanskrit: "अवश्यं साशये व्रणे विकेशिकां दद्यात् संपूतिमांसं सोत्सङ्गं सगतिं पूयगर्भिणम् व्रणं शोधयते शीघ्रं स्थिता ह्यन्तर्विकेशिका", text: "avaśyaṃ sāśaye vraṇe vikeśikāṃ dadyāt saṃpūtimāṃsaṃ sotsaṅgaṃ sagatiṃ pūyagarbhiṇam vraṇaṃ śodhayate śīghraṃ sthitā hyantarvikeśikā" },
      { type: "verse", number: "36", sanskrit: "व्यम्लं तु पाटितं शोफं पाचनैः समुपाचरेत् भोजनैरुपनाहैश्च नातिव्रणविरोधिभिः", text: "vyamlaṃ tu pāṭitaṃ śophaṃ pācanaiḥ samupācaret bhojanairupanāhaiśca nātivraṇavirodhibhiḥ" },
      { type: "verse", number: "37", sanskrit: "यस्तु सीव्यो व्रणस्तत्र चलास्थिशल्यपांसुतृणरोमशुष्करक्तादीनपोह्य विच्छिन्नप्रविलम्बितं मांसं सन्ध्यस्थीनि च यथास्थानं सम्यक् स्थापयित्वा स्थिते रक्ते यथार्हं सूच्योपहृतेन स्नायुसूत्रवालान्यतमेन सीव्येत् शणाश्मन्तकमूर्वातसीनां वा वल्कैः", text: "yastu sīvyo vraṇastatra calāsthiśalyapāṃsutṛṇaromaśuṣkaraktādīnapohya vicchinnapravilambitaṃ māṃsaṃ sandhyasthīni ca yathāsthānaṃ samyak sthāpayitvā sthite rakte yathārhaṃ sūcyopahṛtena snāyusūtravālānyatamena sīvyet śaṇāśmantakamūrvātasīnāṃ vā valkaiḥ" },
      { type: "verse", number: "38", sanskrit: "सीवनविकल्पास्तु समासेन चत्वारः तद्यथा गोष्फणिकातुन्नसीवनवेल्लितकरज्जुग्रन्थिबन्धनमिति तेषां नामभिरेवाकृतिविभागः प्रहारवशाच्चोपयोगः न चातिसन्निकृष्टां विप्रकृष्टामत्यल्पबहुग्राहिणीं वा सूचीं पातयेत् एवं सम्यक्स्यूतमवेक्ष्य मधुघृतयुक्तैरञ्जनमधुकनिम्बलोध्रप्रियङ्गुसल्लकीफलक्षौममषीचूर्णैरवकीर्य पूर्ववद् बन्धादि योजयेत्", text: "sīvanavikalpāstu samāsena catvāraḥ tadyathā goṣphaṇikātunnasīvanavellitakarajjugranthibandhanamiti teṣāṃ nāmabhirevākṛtivibhāgaḥ prahāravaśāccopayogaḥ na cātisannikṛṣṭāṃ viprakṛṣṭāmatyalpabahugrāhiṇīṃ vā sūcīṃ pātayet evaṃ samyaksyūtamavekṣya madhughṛtayuktairañjanamadhukanimbalodhrapriyaṅgusallakīphalakṣaumamaṣīcūrṇairavakīrya pūrvavad bandhādi yojayet" },
      { type: "verse", number: "39", sanskrit: "असीव्या वङ्क्षणवक्षःकक्षादिषु प्रचलेष्वल्पमांसेषु च वायुनिर्वामिणो ऽन्तर्लोहितशल्या विषाग्निक्षारकृताश्च व्रणाः", text: "asīvyā vaṅkṣaṇavakṣaḥkakṣādiṣu pracaleṣvalpamāṃseṣu ca vāyunirvāmiṇo 'ntarlohitaśalyā viṣāgnikṣārakṛtāśca vraṇāḥ" },
      { type: "verse", number: "40", sanskrit: "सीव्यास्तु मेदस्समुत्थिता भिन्नलिखिताः कफग्रन्थिरल्पपालिकः कर्णः सद्योव्रणाश्च शिरोललाटाक्षिकूटकर्णनासागण्डौष्ठकृकाटिकाबाहूदरस्फिक्पायुप्रजननमुष्कादिष्वचलेषु मांसवत्सु च प्रदेशेषु", text: "sīvyāstu medassamutthitā bhinnalikhitāḥ kaphagranthiralpapālikaḥ karṇaḥ sadyovraṇāśca śirolalāṭākṣikūṭakarṇanāsāgaṇḍauṣṭhakṛkāṭikābāhūdarasphikpāyuprajananamuṣkādiṣvacaleṣu māṃsavatsu ca pradeśeṣu" },
      { type: "verse", number: "41", sanskrit: "कोशदामोत्सङ्गस्वस्तिकानुवेल्लितमुत्तोलीमण्डलस्थविकायमकखट्वाचीनविबन्धवितानगोष्फणाः पञ्चाङ्गी चेति पञ्चदश बन्धविशेषाः तेषां नामभिरेवाकृतयः प्रायेण व्याख्याताः", text: "kośadāmotsaṅgasvastikānuvellitamuttolīmaṇḍalasthavikāyamakakhaṭvācīnavibandhavitānagoṣphaṇāḥ pañcāṅgī ceti pañcadaśa bandhaviśeṣāḥ teṣāṃ nāmabhirevākṛtayaḥ prāyeṇa vyākhyātāḥ" },
      { type: "verse", number: "42", sanskrit: "तत्र कोशमङ्गुलीपर्वसु विदध्यात् दाम सम्बाधे ऽङ्गे उत्सङ्गं विलम्बिनि स्वस्तिकं सन्धिकूर्चभ्रूस्तनान्तरकुक्ष्यक्षिकपोलकर्णेषु अनुवेल्लितं शाखासु मुत्तोलीं ग्रीवामेढ्रयोः मण्डलं वृत्ते ऽङ्गे स्थविकामङ्गुष्ठाङ्गुलिमेढ्राग्रमूत्रवृद्धिषु यमकं यमलव्रणयोः खट्वां हनुशङ्खगण्डेषु चीनमपाङ्गयोः विबन्धमुदरोरुपृष्ठेषु वितानं मूर्धादौ पृथुले ऽङ्गे गोष्फणं नासौष्ठचिबुकसन्धिषु पञ्चाङ्गीं जत्रूर्ध्वमिति यो यस्मिन् प्रदेशे सुनिविष्टो भवति तं तस्मिन् कुर्वीत न तु व्रणस्योपरि न चाबाधकरो यथा स्यात्", text: "tatra kośamaṅgulīparvasu vidadhyāt dāma sambādhe 'ṅge utsaṅgaṃ vilambini svastikaṃ sandhikūrcabhrūstanāntarakukṣyakṣikapolakarṇeṣu anuvellitaṃ śākhāsu muttolīṃ grīvāmeḍhrayoḥ maṇḍalaṃ vṛtte 'ṅge sthavikāmaṅguṣṭhāṅgulimeḍhrāgramūtravṛddhiṣu yamakaṃ yamalavraṇayoḥ khaṭvāṃ hanuśaṅkhagaṇḍeṣu cīnamapāṅgayoḥ vibandhamudarorupṛṣṭheṣu vitānaṃ mūrdhādau pṛthule 'ṅge goṣphaṇaṃ nāsauṣṭhacibukasandhiṣu pañcāṅgīṃ jatrūrdhvamiti yo yasmin pradeśe suniviṣṭo bhavati taṃ tasmin kurvīta na tu vraṇasyopari na cābādhakaro yathā syāt" },
      { type: "verse", number: "43", sanskrit: "बन्धस्त्विष्टो ऽनिले दुष्टे दुष्टे भग्ने व्रणेषु च तत्रान्त्ययोर्द्विधा बन्धः सव्यदक्षिणभेदतः", text: "bandhastviṣṭo 'nile duṣṭe duṣṭe bhagne vraṇeṣu ca tatrāntyayordvidhā bandhaḥ savyadakṣiṇabhedataḥ" },
      { type: "verse", number: "44", sanskrit: "त्रिविधस्त्वेव सर्वत्र गाढश्लथसमत्वतः कफवाते घनो गाढः पित्तरक्ते तनुः श्लथः", text: "trividhastveva sarvatra gāḍhaślathasamatvataḥ kaphavāte ghano gāḍhaḥ pittarakte tanuḥ ślathaḥ" },
      { type: "verse", number: "45", sanskrit: "वातपित्ते समो बन्धः कफपित्तव्रणेषु च तथा स्फिक्कक्ष्यावङ्क्षणोरुशिरस्सु गाढं बध्रीयात् शाखावदनकण्ठकर्णमेढ्रमुष्कपृष्ठपार्श्वोदरोरस्सु समम् अक्ष्णोः सन्धिषु च शिथिलम्", text: "vātapitte samo bandhaḥ kaphapittavraṇeṣu ca tathā sphikkakṣyāvaṅkṣaṇoruśirassu gāḍhaṃ badhrīyāt śākhāvadanakaṇṭhakarṇameḍhramuṣkapṛṣṭhapārśvodarorassu samam akṣṇoḥ sandhiṣu ca śithilam" },
      { type: "verse", number: "46", sanskrit: "वातश्लेष्मजेषु शिथिलस्थाने समम् समस्थाने गाढम् गाढस्थाने गाढतरम् तथा शीतवसन्तयोस्त्र्यहात् पित्तरक्तेषु तु गाढस्थाने समम् समास्थाने शिथिलम् शिथिलस्थाने नैव तथा शरद्ग्रीष्मयोः सायं प्रातश्च अबध्यमानः पुनर्दंशमशकतृणकाष्ठपांसुशीतवातातपादिसम्पर्काद्विविधोपद्रवोपद्रुतो दुष्टव्रणतामुपैति स्नेहश्चात्र न चिरं तिष्ठति भेषजमचिराच्छुष्यति कृच्छ्रेण रोहति रूढे च वैवर्ण्यं भवति अपि च", text: "vātaśleṣmajeṣu śithilasthāne samam samasthāne gāḍham gāḍhasthāne gāḍhataram tathā śītavasantayostryahāt pittarakteṣu tu gāḍhasthāne samam samāsthāne śithilam śithilasthāne naiva tathā śaradgrīṣmayoḥ sāyaṃ prātaśca abadhyamānaḥ punardaṃśamaśakatṛṇakāṣṭhapāṃsuśītavātātapādisamparkādvividhopadravopadruto duṣṭavraṇatāmupaiti snehaścātra na ciraṃ tiṣṭhati bheṣajamacirācchuṣyati kṛcchreṇa rohati rūḍhe ca vaivarṇyaṃ bhavati api ca" },
      { type: "verse", number: "47", sanskrit: "चूर्णतं मथितं भग्नं विश्लिष्टमथ पाटितम् अस्थिस्नायुसिराच्छिन्नमाशु बन्धेन रोहति", text: "cūrṇataṃ mathitaṃ bhagnaṃ viśliṣṭamatha pāṭitam asthisnāyusirācchinnamāśu bandhena rohati" },
      { type: "verse", number: "48", sanskrit: "उत्थानशयनाद्यासु सर्वेहासु न पीड्यते उद्वृत्तौष्ठः समुत्सन्नो विषमः कठिनो ऽतिरुक्", text: "utthānaśayanādyāsu sarvehāsu na pīḍyate udvṛttauṣṭhaḥ samutsanno viṣamaḥ kaṭhino 'tiruk" },
      { type: "verse", number: "49", sanskrit: "समो मृदुररुक् शीघ्रं व्रणः शुध्यति रोहति स्थिराणामल्पमांसानां रौक्ष्यादनुपरोहताम् प्रच्छाद्यमौषधं पत्रैर्यथादोषं यथर्तु च", text: "samo mṛduraruk śīghraṃ vraṇaḥ śudhyati rohati sthirāṇāmalpamāṃsānāṃ raukṣyādanuparohatām pracchādyamauṣadhaṃ patrairyathādoṣaṃ yathartu ca" },
      { type: "verse", number: "50", sanskrit: "अजीर्णातरुणाच्छिद्रैः समन्तात् सुनिवेशितैः धौतैरकर्कशैः क्षीरीभूर्जार्जुनकदम्बजैः", text: "ajīrṇātaruṇācchidraiḥ samantāt suniveśitaiḥ dhautairakarkaśaiḥ kṣīrībhūrjārjunakadambajaiḥ" },
      { type: "verse", number: "51", sanskrit: "कुष्ठिनामग्निदग्धानां पिटकामधुमेहिनाम् कर्णिकाश्चोन्दुरुविषे क्षारदग्धा विषान्विताः", text: "kuṣṭhināmagnidagdhānāṃ piṭakāmadhumehinām karṇikāśconduruviṣe kṣāradagdhā viṣānvitāḥ" },
      { type: "verse", number: "52", sanskrit: "मांसपाके न बद्धव्या गुदपाके च दारुणे शीर्यमाणाः सरुग्दाहाः शोफावस्थाविसर्पिणः", text: "māṃsapāke na baddhavyā gudapāke ca dāruṇe śīryamāṇāḥ sarugdāhāḥ śophāvasthāvisarpiṇaḥ" },
      { type: "verse", number: "53", sanskrit: "अरक्षया व्रणे यस्मिन् मक्षिका निक्षिपेत् क्रिमीन् ते भक्षयन्तः कुर्वन्ति रुजाशोफास्रसंस्रवान्", text: "arakṣayā vraṇe yasmin makṣikā nikṣipet krimīn te bhakṣayantaḥ kurvanti rujāśophāsrasaṃsravān" },
      { type: "verse", number: "54", sanskrit: "सुरसादिं प्रयुञ्जीत तत्र धावनपूरणे सप्तपर्णकरञ्जार्कनिम्बराजादनत्वचः", text: "surasādiṃ prayuñjīta tatra dhāvanapūraṇe saptaparṇakarañjārkanimbarājādanatvacaḥ" },
      { type: "verse", number: "55", sanskrit: "गोमूत्रकल्कितो लेपः सेकः क्षाराम्बुना हितः प्रच्छाद्य मांसपेश्या वा व्रणं तानाशु निर्हरेत्", text: "gomūtrakalkito lepaḥ sekaḥ kṣārāmbunā hitaḥ pracchādya māṃsapeśyā vā vraṇaṃ tānāśu nirharet" },
      { type: "verse", number: "56", sanskrit: "उत्पद्यमानासु च तासु तास्ववस्थासु दोषादीनपेक्ष्य यथास्वमुपक्रमैरुपक्रमेत्", text: "utpadyamānāsu ca tāsu tāsvavasthāsu doṣādīnapekṣya yathāsvamupakramairupakramet" },
      { type: "verse", number: "57", sanskrit: "न चैनं त्वरमाणः सान्तर्दोषमुपसंरोहयेत् स ह्यल्पेनाप्यवचारेणान्तरुत्सङ्गं कृत्वा भूयो विकुरुते तस्मात्सुशुद्धं रोपयेत्", text: "na cainaṃ tvaramāṇaḥ sāntardoṣamupasaṃrohayet sa hyalpenāpyavacāreṇāntarutsaṅgaṃ kṛtvā bhūyo vikurute tasmātsuśuddhaṃ ropayet" },
      { type: "verse", number: "58", sanskrit: "रूढे ऽप्यजीर्णव्यायामव्यवायादीन्विवर्जयेत् मासान् षट् सप्त वा नृऋणां विधिरेष प्रशस्यते", text: "rūḍhe 'pyajīrṇavyāyāmavyavāyādīnvivarjayet māsān ṣaṭ sapta vā nṛṛṇāṃ vidhireṣa praśasyate" },
      { type: "verse", number: "59", sanskrit: "इतीदं व्रणमाश्रित्य दिङ्मात्रमुपदर्शितम् उत्तरे विस्तरस्तस्य वक्ष्यते साधनं प्रति", text: "itīdaṃ vraṇamāśritya diṅmātramupadarśitam uttare vistarastasya vakṣyate sādhanaṃ prati" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 39,
    lang: "sa",
    content: [
      { type: "heading", heading: "Шастра видхи — хирургические операции" },
      { type: "text", text: "Глава 39 Сутрастханы Астанга-санграхи посвящена теме «хирургические операции». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातः क्षारपाकविधिमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ kṣārapākavidhimadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "क्षारो हि नानौषधसमवायनिर्वृत्तेः सर्वरसाधिष्ठानं कटुकलवणरसभूयिष्ठस्तीक्ष्णोष्णो दहनः पाचनो विदारणो विलायनः शोधनो रोपणः क्रिम्याममेदोविषापहः सर्वशस्त्रानुशस्त्राणां च वरिष्ठः छेदनभेदनपाटनलेखनकरणाद्यतश्च सम्बाधावकाशजेषु दुःखावचारणीयशस्त्रेषु नासार्शो ऽर्बुदादिषु शस्त्रेण चासिध्यस्तु दुष्टव्रणेषु बहुशः प्रकोपिषु प्रयुज्यते स द्विविधो बाह्याभ्यन्तरपरिमार्जनभेदेन", text: "kṣāro hi nānauṣadhasamavāyanirvṛtteḥ sarvarasādhiṣṭhānaṃ kaṭukalavaṇarasabhūyiṣṭhastīkṣṇoṣṇo dahanaḥ pācano vidāraṇo vilāyanaḥ śodhano ropaṇaḥ krimyāmamedoviṣāpahaḥ sarvaśastrānuśastrāṇāṃ ca variṣṭhaḥ chedanabhedanapāṭanalekhanakaraṇādyataśca sambādhāvakāśajeṣu duḥkhāvacāraṇīyaśastreṣu nāsārśo 'rbudādiṣu śastreṇa cāsidhyastu duṣṭavraṇeṣu bahuśaḥ prakopiṣu prayujyate sa dvividho bāhyābhyantaraparimārjanabhedena" },
      { type: "verse", number: "3", sanskrit: "तत्रार्शो ऽर्बुदभगन्दरग्रन्थिदुष्टव्रणनाडीचर्मकीलवर्त्ममुखरोगकुष्ठकिलासतिलकालकादिषु बहिः परिमार्जनेन अन्तःपरिमार्जनेन तु गुल्मगरोदराग्निसादमलसङ्गशूलानाहाश्मरीशर्करादिषु स यथास्वमेवोपदेक्ष्यते", text: "tatrārśo 'rbudabhagandaragranthiduṣṭavraṇanāḍīcarmakīlavartmamukharogakuṣṭhakilāsatilakālakādiṣu bahiḥ parimārjanena antaḥparimārjanena tu gulmagarodarāgnisādamalasaṅgaśūlānāhāśmarīśarkarādiṣu sa yathāsvamevopadekṣyate" },
      { type: "verse", number: "4", sanskrit: "न तूभयो ऽपि योज्यो भीरुदुर्बलक्षामवातपित्तार्दितज्वरातिसारपाण्डुशिरोहृदयरोगमेहाक्षिपाकतिमिरारोचकातुरकृतवमनविरेकर्तुमतीगर्भिण्युद्वृत्तफलयोनिसर्वाङ्गशूलविषमद्यपीतेषु मर्मसिरास्नायुसन्धितरुणास्थिसेवनीधमनीगलनाभिनखान्तरमुष्कशेफस्रोतस्स्वल्पमांसेषु च देशेष्वक्ष्णोश्चान्यत्र वर्त्मरोगात् तथा शीतोष्णवर्षदुर्दिनप्रवातेषु च", text: "na tūbhayo 'pi yojyo bhīrudurbalakṣāmavātapittārditajvarātisārapāṇḍuśirohṛdayarogamehākṣipākatimirārocakāturakṛtavamanavirekartumatīgarbhiṇyudvṛttaphalayonisarvāṅgaśūlaviṣamadyapīteṣu marmasirāsnāyusandhitaruṇāsthisevanīdhamanīgalanābhinakhāntaramuṣkaśephasrotassvalpamāṃseṣu ca deśeṣvakṣṇoścānyatra vartmarogāt tathā śītoṣṇavarṣadurdinapravāteṣu ca" },
      { type: "verse", number: "5", sanskrit: "अथ बहिः परिमार्जनस्त्रिविधो मध्यो मृदुस्तीक्ष्णश्च तस्य पाकविधिः शरदि शुचिरुपोषितः शुक्लवासाः प्रशस्ते ऽहनि प्रशस्तदेशजातं मध्यमवयसमनुपहतं महान्तं कालमुष्ककं सुरापललसुमनो ऽक्षतादिभिश्चतुर्दिशं बलिं कृत्वा प्रदक्षिणं चाभ्यर्च्यैनमधिवासयेत्", text: "atha bahiḥ parimārjanastrividho madhyo mṛdustīkṣṇaśca tasya pākavidhiḥ śaradi śucirupoṣitaḥ śuklavāsāḥ praśaste 'hani praśastadeśajātaṃ madhyamavayasamanupahataṃ mahāntaṃ kālamuṣkakaṃ surāpalalasumano 'kṣatādibhiścaturdiśaṃ baliṃ kṛtvā pradakṣiṇaṃ cābhyarcyainamadhivāsayet" },
      { type: "verse", number: "6", sanskrit: "दैवतेभ्यो नमस्तेभ्यो निवसन्तीह ये श्रिताः गन्तुमर्हन्त्यसङ्क्रुद्धास्त्यक्त्वेमं वासमव्ययम्", text: "daivatebhyo namastebhyo nivasantīha ye śritāḥ gantumarhantyasaṅkruddhāstyaktvemaṃ vāsamavyayam" },
      { type: "verse", number: "7", sanskrit: "भेषजार्थं ग्रहीष्यामि सर्वप्राणभृतामिमम् वृक्षं न लोभान्न क्रोधाद् ब्राह्मणार्थे विशेषतः", text: "bheṣajārthaṃ grahīṣyāmi sarvaprāṇabhṛtāmimam vṛkṣaṃ na lobhānna krodhād brāhmaṇārthe viśeṣataḥ" },
      { type: "verse", number: "8", sanskrit: "इति अथापरेद्युस्तत्र यद्यद्भुतं वैकृतं वा किञ्चिन्न पश्येत्ततो युगमात्रमारूढे सवितरि ब्राह्मणान् वाचयित्वा तं पादपं पूर्वाग्रमुत्तराग्रं वा पातयेत् एवं च पारिभद्रपलाशाश्वकर्णराजवृक्षमहावृक्षवृक्षकेन्द्रवृक्षास्फोतसप्तच्छदनक्तमालतिल्वककदलीबिभीतकाश्वमारकपूतीकचित्रकार्ककाकजङ्घापामार्गाग्निमन्थान् वसन्ते सङ्गृहीतांश्च यवान् सशूकनालांश्चतस्रश्च कोशातकीः सवान् समूलफलपत्रशाखान् खण्डशः कल्पयित्वा नातिशुष्कान् शिलातलस्थान् निवाते पृथङ् निचयीकृत्य मुष्ककनिचये च सुधाशर्कराः प्रक्षिप्य तिलकुन्तलैरादीपयेत् दग्ध्वा च शान्ते ऽग्नौ पृथक् सुधाशर्कराभस्म कृत्वेतरत् सर्वक्षारद्रोणमधिकमुष्ककं सलिलपलसहस्रेण गवादिमूत्रपलसहस्रेण चालोड्य महता वस्त्रेण परिस्रावयेत् यावदच्छो रक्तस्तीक्ष्णः पिच्छिलश्च जातस्तदा तं क्षारनिष्यन्दं गृहीत्वा भस्म विवर्जयेत् ततः स्नेहपाकविधिना पाचयेत् पच्यमाने च तस्मिंस्ताः सुधाभस्मशर्कराः क्षीरबकं शङ्खनाभिचायसे पात्रे ऽग्निवर्णान् कृत्वा तत्क्षाराच्छकुडवमात्रे निर्वाप्य तेनैव च सुश्लक्ष्णं पिष्ट्वा प्रतीवापं दद्यात् ततश्च सुतरां दर्व्यावघट्टयन् विपचेत् यावच्च सबाष्पैर्बुद्बुदैः समुत्तिष्ठेत् सान्द्रतया च दर्वीप्रलेपी स्यात्तदैनमवतार्यायोघटे यवरशौ सुगुप्तं स्थापयेत् एष मध्यमः क्षारः", text: "iti athāparedyustatra yadyadbhutaṃ vaikṛtaṃ vā kiñcinna paśyettato yugamātramārūḍhe savitari brāhmaṇān vācayitvā taṃ pādapaṃ pūrvāgramuttarāgraṃ vā pātayet evaṃ ca pāribhadrapalāśāśvakarṇarājavṛkṣamahāvṛkṣavṛkṣakendravṛkṣāsphotasaptacchadanaktamālatilvakakadalībibhītakāśvamārakapūtīkacitrakārkakākajaṅghāpāmārgāgnimanthān vasante saṅgṛhītāṃśca yavān saśūkanālāṃścatasraśca kośātakīḥ savān samūlaphalapatraśākhān khaṇḍaśaḥ kalpayitvā nātiśuṣkān śilātalasthān nivāte pṛthaṅ nicayīkṛtya muṣkakanicaye ca sudhāśarkarāḥ prakṣipya tilakuntalairādīpayet dagdhvā ca śānte 'gnau pṛthak sudhāśarkarābhasma kṛtvetarat sarvakṣāradroṇamadhikamuṣkakaṃ salilapalasahasreṇa gavādimūtrapalasahasreṇa cāloḍya mahatā vastreṇa parisrāvayet yāvadaccho raktastīkṣṇaḥ picchilaśca jātastadā taṃ kṣāraniṣyandaṃ gṛhītvā bhasma vivarjayet tataḥ snehapākavidhinā pācayet pacyamāne ca tasmiṃstāḥ sudhābhasmaśarkarāḥ kṣīrabakaṃ śaṅkhanābhicāyase pātre 'gnivarṇān kṛtvā tatkṣārācchakuḍavamātre nirvāpya tenaiva ca suślakṣṇaṃ piṣṭvā pratīvāpaṃ dadyāt tataśca sutarāṃ darvyāvaghaṭṭayan vipacet yāvacca sabāṣpairbudbudaiḥ samuttiṣṭhet sāndratayā ca darvīpralepī syāttadainamavatāryāyoghaṭe yavaraśau suguptaṃ sthāpayet eṣa madhyamaḥ kṣāraḥ" },
      { type: "verse", number: "9", sanskrit: "मृदौ शर्करादीन्निर्वाप्यापनयेन्न तु पिष्ट्वा क्षिपेत् तीक्ष्णे तु दन्तीचित्रकलाङ्गलिकापूतीकप्रवालतालपत्रीबिडस्वर्जिकाकनकक्षीरीहिङ्गुवचातिविषाः श्लक्ष्णचूर्णीकृता दग्धाश्च शङ्खशुक्तीः पूर्ववत् प्रतिवापं दद्यात् तांश्च व्याधिबलतः सप्तरात्रादूर्ध्वं प्रयुञ्जीत क्षीणबले तु बलाधानार्थं पुनः क्षारजलमावपेत् तत्रनातितीक्ष्णो नातिमृदुः श्वेतः श्लक्ष्णः शीघ्रः पिच्छिलः शिखरी सुखनिर्वाप्यो ऽल्परुगनभिष्यन्दी चेति दश क्षारस्य गुणाः दशैव च दोषाः तद्यथा अत्युष्णो ऽतिशीतो ऽतितीक्ष्णो ऽतिमृदुरतितनुरतिघनो ऽतिपिच्छिलोविसर्पी हीनौषधो हीनपाकश्चेति", text: "mṛdau śarkarādīnnirvāpyāpanayenna tu piṣṭvā kṣipet tīkṣṇe tu dantīcitrakalāṅgalikāpūtīkapravālatālapatrībiḍasvarjikākanakakṣīrīhiṅguvacātiviṣāḥ ślakṣṇacūrṇīkṛtā dagdhāśca śaṅkhaśuktīḥ pūrvavat prativāpaṃ dadyāt tāṃśca vyādhibalataḥ saptarātrādūrdhvaṃ prayuñjīta kṣīṇabale tu balādhānārthaṃ punaḥ kṣārajalamāvapet tatranātitīkṣṇo nātimṛduḥ śvetaḥ ślakṣṇaḥ śīghraḥ picchilaḥ śikharī sukhanirvāpyo 'lparuganabhiṣyandī ceti daśa kṣārasya guṇāḥ daśaiva ca doṣāḥ tadyathā atyuṣṇo 'tiśīto 'titīkṣṇo 'timṛduratitanuratighano 'tipicchilovisarpī hīnauṣadho hīnapākaśceti" },
      { type: "verse", number: "10", sanskrit: "तत्र क्षारकर्मण्युपहारेत् पिचुवर्तिशलाकादर्व्यञ्जलिकाघृतमधुशुक्ततुषोदकमस्तुक्षीरोदकशीतप्रदेहशयनासनादीनि अथ क्षारार्हस्योपविष्टस्य संविष्टस्य वाप्तपरिचारकगृहीतस्य व्याधिं छित्वावलिख्य प्रच्छाय वा पिचुप्लोतान्यतरावगुण्ठितया शलाकया क्षारं पातयेत् ततो मात्राशतमुपेक्षेत वर्त्मरोगे तु निर्भुज्य वर्त्मनी पिचुना मधूच्छिष्टेन वा कृष्णभागं प्रच्छाद्य पद्मपत्रतनुः क्षारलेपः घ्राणजेषु त्वर्शो ऽर्बुदेष्वादित्याभिमुखस्योन्नमय्य नासिकामुपेक्ष्याश्च पञ्चाशन्मात्राः तद्वच्छ्रोत्रजेषु गुदार्शस्सु पाणिना यन्त्रद्वारं पिधाय धारयेन्मात्राशतमेव ततः प्रमार्जनेन प्रमृज्य क्षारं सम्यग्दग्धमवेक्ष्य निर्वापयेत्सर्पिर्मधुभ्यां शुक्ततुषोदकमस्तुक्षीरादिभिश्च ततः परं शीतमधुरैः सघृतैः प्रदिह्यात् अभिष्यन्दीनि भोज्यानि भोज्यानि क्लेदनाय च स्थिरमूलत्वात्तु यदि क्षारदग्धं न विशीर्यते ततो धान्याम्लबीजमधुयष्टिकायुक्तैस्तिलैरालेपयेत्सुवर्णक्षीरीयुतैर्वा त्रिवृद्विडङ्गसारवद्भिर्वा मालतीवृषाङ्कोलनिम्बास्फोतपटोलीकरवीरपत्रक्वाथेन व्रणप्रक्षालनम् एषामेव च कल्कक्वाथे सिद्धं सर्पिस्तैलं वा रोपणम् नागपुष्पमञ्जिष्ठाचन्दनतिलपर्णिकासु वा यथाव्याधिदोषं च व्रणमुपक्रमेत् तिलाः सयष्टिमधुका रोपणे चास्य पूजिताः", text: "tatra kṣārakarmaṇyupahāret picuvartiśalākādarvyañjalikāghṛtamadhuśuktatuṣodakamastukṣīrodakaśītapradehaśayanāsanādīni atha kṣārārhasyopaviṣṭasya saṃviṣṭasya vāptaparicārakagṛhītasya vyādhiṃ chitvāvalikhya pracchāya vā picuplotānyatarāvaguṇṭhitayā śalākayā kṣāraṃ pātayet tato mātrāśatamupekṣeta vartmaroge tu nirbhujya vartmanī picunā madhūcchiṣṭena vā kṛṣṇabhāgaṃ pracchādya padmapatratanuḥ kṣāralepaḥ ghrāṇajeṣu tvarśo 'rbudeṣvādityābhimukhasyonnamayya nāsikāmupekṣyāśca pañcāśanmātrāḥ tadvacchrotrajeṣu gudārśassu pāṇinā yantradvāraṃ pidhāya dhārayenmātrāśatameva tataḥ pramārjanena pramṛjya kṣāraṃ samyagdagdhamavekṣya nirvāpayetsarpirmadhubhyāṃ śuktatuṣodakamastukṣīrādibhiśca tataḥ paraṃ śītamadhuraiḥ saghṛtaiḥ pradihyāt abhiṣyandīni bhojyāni bhojyāni kledanāya ca sthiramūlatvāttu yadi kṣāradagdhaṃ na viśīryate tato dhānyāmlabījamadhuyaṣṭikāyuktaistilairālepayetsuvarṇakṣīrīyutairvā trivṛdviḍaṅgasāravadbhirvā mālatīvṛṣāṅkolanimbāsphotapaṭolīkaravīrapatrakvāthena vraṇaprakṣālanam eṣāmeva ca kalkakvāthe siddhaṃ sarpistailaṃ vā ropaṇam nāgapuṣpamañjiṣṭhācandanatilaparṇikāsu vā yathāvyādhidoṣaṃ ca vraṇamupakramet tilāḥ sayaṣṭimadhukā ropaṇe cāsya pūjitāḥ" },
      { type: "verse", number: "11", sanskrit: "तत्र पक्वजाम्बवसङ्काशमवसन्नमीषद्यथास्वविकारोपशान्तौ च सम्यग्दग्धं भवति तद्विपर्ययेण तोदकण्डूजाड्यादिभिश्चदुर्दग्धम् तत्र पुनः पातयेत् ऊषादाहरागशोफज्वरपाकविसर्पशिरोरोगवातपित्तकोपैरतिदग्धम् अपि च नेत्रे ऽतियोगाद्वर्त्मनिर्भेदेनेन्द्रियभ्रंशः घ्राणे नासावंशतरुणास्थिदरणं सङ्कोचो गन्धाज्ञानं च तद्वच्छोत्रादिष्वपि च यथास्वं व्यापत् गुदे विण्मूत्ररोधो ऽतीसारः पुंस्त्वोपघातो गुदविदरणाच्च मृत्युर्वा सर्वदा वा शोफतोदवेदनास्रावाः शकृन्मूत्रवातविधारणाशक्तिर्वा तमतिप्रवृत्तमाशु पूर्वोक्तैरेव निर्वापणैः पुनःपुनर्निर्वापयेत् अतश्च दाह्यमतिप्रमाणं न सकृदेव दहेदिति भवति चात्र", text: "tatra pakvajāmbavasaṅkāśamavasannamīṣadyathāsvavikāropaśāntau ca samyagdagdhaṃ bhavati tadviparyayeṇa todakaṇḍūjāḍyādibhiścadurdagdham tatra punaḥ pātayet ūṣādāharāgaśophajvarapākavisarpaśirorogavātapittakopairatidagdham api ca netre 'tiyogādvartmanirbhedenendriyabhraṃśaḥ ghrāṇe nāsāvaṃśataruṇāsthidaraṇaṃ saṅkoco gandhājñānaṃ ca tadvacchotrādiṣvapi ca yathāsvaṃ vyāpat gude viṇmūtrarodho 'tīsāraḥ puṃstvopaghāto gudavidaraṇācca mṛtyurvā sarvadā vā śophatodavedanāsrāvāḥ śakṛnmūtravātavidhāraṇāśaktirvā tamatipravṛttamāśu pūrvoktaireva nirvāpaṇaiḥ punaḥpunarnirvāpayet ataśca dāhyamatipramāṇaṃ na sakṛdeva dahediti bhavati cātra" },
      { type: "verse", number: "12", sanskrit: "अम्लो हि शीतः स्पर्शेन क्षारस्तेनोपसंहितः यात्याशु स्वादुतां तमादम्लैर्निर्वापयेत्तराम्", text: "amlo hi śītaḥ sparśena kṣārastenopasaṃhitaḥ yātyāśu svādutāṃ tamādamlairnirvāpayettarām" },
      { type: "verse", number: "13", sanskrit: "ज्वरातिसारतृण्मोहमूर्छाहृद्वेदनार्तिभिः कक्षं दहत्यग्निरिव शरीरं क्षारविभ्रमः", text: "jvarātisāratṛṇmohamūrchāhṛdvedanārtibhiḥ kakṣaṃ dahatyagniriva śarīraṃ kṣāravibhramaḥ" },
      { type: "verse", number: "14", sanskrit: "पाययेतातियोगे ऽतस्तं शीघ्रं सघृतं दधि सगुडं वा दधिसरं तैलं वा ससितोपलम्", text: "pāyayetātiyoge 'tastaṃ śīghraṃ saghṛtaṃ dadhi saguḍaṃ vā dadhisaraṃ tailaṃ vā sasitopalam" },
      { type: "verse", number: "15", sanskrit: "धात्रीफलकपित्थाम्लदाडिमस्वरसे घृतम् द्विगुणे साधितं पानसेकैः क्षारातिरुग्धरम्", text: "dhātrīphalakapitthāmladāḍimasvarase ghṛtam dviguṇe sādhitaṃ pānasekaiḥ kṣārātirugdharam" },
      { type: "verse", number: "16", sanskrit: "दाडिमामलकाम्रातकपित्थकरमर्दकान् आम्राच्च मातुलुङ्गाच्च रसं मृद्वग्निना पचेत्", text: "dāḍimāmalakāmrātakapitthakaramardakān āmrācca mātuluṅgācca rasaṃ mṛdvagninā pacet" },
      { type: "verse", number: "17", sanskrit: "ततो ऽतिवृत्तक्षाराय दद्यान्मात्रां यथाबलम् क्षारो निवर्तते तेन प्रसादं त्वक् च गच्छति", text: "tato 'tivṛttakṣārāya dadyānmātrāṃ yathābalam kṣāro nivartate tena prasādaṃ tvak ca gacchati" },
      { type: "verse", number: "18", sanskrit: "शोणितातिप्रवृत्तौ तु बाह्यान्तः शिशिरो विधिः", text: "śoṇitātipravṛttau tu bāhyāntaḥ śiśiro vidhiḥ" },
    ],
  },
  {
    sthana: "Сутрастхана",
    number: 40,
    lang: "sa",
    content: [
      { type: "heading", heading: "Калпасиддхи — завершение Сутрастханы" },
      { type: "text", text: "Глава 40 Сутрастханы Астанга-санграхи посвящена теме «завершение Сутрастханы». Вагбхата-старший излагает её более подробно, чем в Аштанга-хридае." },
      { type: "verse", number: "1", sanskrit: "अथातो ऽग्निकर्मविधिमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto 'gnikarmavidhimadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अग्निः क्षारादपि गरीयानौषधशस्त्रक्षारैरसिद्धानां तद्दाहसिद्धेरपुनर्भवाच्च तत्राग्निकर्म त्वचि मांसे सिरास्नायुसन्ध्यस्थिषु च प्रयुज्यते तत्र मशतिलकालकचर्मकीलसरुक्स्तब्धप्रम्लानाङ्गाभिष्यन्दाधिमन्थशिरोभ्रूशङ्खललाटरुजार्दितेषु सूर्यकान्तपिप्पल्यजाशकृद्गोदन्तशरशलाकाभिस्त्वग्दाहो यथास्वमभिष्यन्दादिषु तु भ्रूशङ्खललाटदेशेषु ग्रन्थ्यर्बुदार्शोभगन्दरगण्डमालाश्लीपदान्त्रवृद्धिदुष्टव्रणगतिनाड्यवगाढपूयालसकेषु जाम्बवौष्ठसूचीशलाकाघृतगुडमधुमधूच्छिष्टतैलवसाहेमताम्रायोरूप्यकांस्यैर्मांसदाहः सिरास्नायुसन्ध्यस्थिच्छदेशोणितातिप्रवृत्तिदन्तनाडीश्लिष्टवर्त्मोपपक्ष्मलगणलिङ्गनाशासम्यग्व्यधेषु जाम्ववौष्ठसूचीशलाकामधुमधूच्छिष्टगुडस्नेहैः सिरादिदाहः", text: "agniḥ kṣārādapi garīyānauṣadhaśastrakṣārairasiddhānāṃ taddāhasiddherapunarbhavācca tatrāgnikarma tvaci māṃse sirāsnāyusandhyasthiṣu ca prayujyate tatra maśatilakālakacarmakīlasarukstabdhapramlānāṅgābhiṣyandādhimanthaśirobhrūśaṅkhalalāṭarujārditeṣu sūryakāntapippalyajāśakṛdgodantaśaraśalākābhistvagdāho yathāsvamabhiṣyandādiṣu tu bhrūśaṅkhalalāṭadeśeṣu granthyarbudārśobhagandaragaṇḍamālāślīpadāntravṛddhiduṣṭavraṇagatināḍyavagāḍhapūyālasakeṣu jāmbavauṣṭhasūcīśalākāghṛtaguḍamadhumadhūcchiṣṭatailavasāhematāmrāyorūpyakāṃsyairmāṃsadāhaḥ sirāsnāyusandhyasthicchadeśoṇitātipravṛttidantanāḍīśliṣṭavartmopapakṣmalagaṇaliṅganāśāsamyagvyadheṣu jāmvavauṣṭhasūcīśalākāmadhumadhūcchiṣṭAguḍasnehaiḥ sirādidāhaḥ" },
      { type: "verse", number: "3", sanskrit: "न तु दहेद्भिन्नकोष्ठमन्तश्शोणितमनुद्धृतशल्यमनेकव्रणपीडितमुष्णे च काले तथा क्षारानर्हं च आत्ययिके तु व्याधौ कृतोष्णप्रतीकारस्य पिच्छिलमन्नमशितवतो ऽग्निकर्म कुर्यात्", text: "na tu dahedbhinnakoṣṭhamantaśśoṇitamanuddhṛtaśalyamanekavraṇapīḍitamuṣṇe ca kāle tathā kṣārānarhaṃ ca ātyayike tu vyādhau kṛtoṣṇapratīkārasya picchilamannamaśitavato 'gnikarma kuryāt" },
      { type: "verse", number: "4", sanskrit: "अथ दाहार्हमातुरं कृतस्वस्त्ययनमुपहृतसर्वोपकरणं प्राक्शिरःसंविष्टमाप्तावलम्बितं कृत्वा वैद्यो निर्धूमबृहत्स्थिरदीप्तखदिरबदराद्यङ्गारैरयोघटनप्रकारेण भस्त्रानिलाध्मातैर्व्यजनेन चोर्ध्वानिर्गच्छज्ज्वालतयापादितापद्यमानभासुराग्निवर्णैर्जाम्बवौष्ठादिभिर्व्याधिप्रदेशवशाद्वलयार्धचन्दस्वस्तिकाष्टापदबिन्दुरेखाप्रतिसारणविकल्पेन मुहुर्मुहुर्हितोपहिताभिर्वाग्भिरद्भिश्चातुरमाश्वासयन् दहेदा सम्यग्दाहलिङ्गोत्पत्तेः उच्छूनसुषिरप्रलूनदन्तनाडीसजन्तुदुष्टव्रणेषु तु स्नेहमधूच्छिष्टमधुगुडेः पूरयित्वा दहेत् सम्यग्दग्धे च मधुसर्पिषी दद्याच्छीतस्निग्धाश्च प्रदेहान्", text: "atha dāhārhamāturaṃ kṛtasvastyayanamupahṛtasarvopakaraṇaṃ prākśiraḥsaṃviṣṭamāptāvalambitaṃ kṛtvā vaidyo nirdhūmabṛhatsthiradīptakhadirabadarādyaṅgārairayoghaṭanaprakāreṇa bhastrānilādhmātairvyajanena cordhvānirgacchajjvālatayāpāditāpadyamānabhāsurāgnivarṇairjāmbavauṣṭhādibhirvyādhipradeśavaśādvalayārdhacandasvastikāṣṭāpadabindurekhāpratisāraṇavikalpena muhurmuhurhitopahitābhirvāgbhiradbhiścāturamāśvāsayan dahedā samyagdāhaliṅgotpatteḥ ucchūnasuṣirapralūnadantanāḍīsajantuduṣṭavraṇeṣu tu snehamadhūcchiṣṭamadhuguḍeḥ pūrayitvā dahet samyagdagdhe ca madhusarpiṣī dadyācchītasnigdhāśca pradehān" },
      { type: "verse", number: "5", sanskrit: "सम्यग्दग्धलिङ्गं पुनस्सशब्दं दहनं दुर्गन्धित्वं त्वक्सङ्कोचश्च त्वग्दग्धे कपोतवर्णत्वमल्पशोफरुजता शुष्कसङ्कुचितव्रणता च मांसदग्धे कृष्णोन्नतव्रणत्वं स्थिते च रक्ते लसीकास्रुतिः सिरादग्धे कृष्णारुणकर्कशस्थिरव्रणता स्नाय्वादिदग्धे च दुर्दग्धातिदग्धयोस्तु प्रमाददग्धवल्लक्षणम् चिकित्सितं च", text: "samyagdagdhaliṅgaṃ punassaśabdaṃ dahanaṃ durgandhitvaṃ tvaksaṅkocaśca tvagdagdhe kapotavarṇatvamalpaśopharujatā śuṣkasaṅkucitavraṇatā ca māṃsadagdhe kṛṣṇonnatavraṇatvaṃ sthite ca rakte lasīkāsrutiḥ sirādagdhe kṛṣṇāruṇakarkaśasthiravraṇatā snāyvādidagdhe ca durdagdhātidagdhayostu pramādadagdhavallakṣaṇam cikitsitaṃ ca" },
      { type: "verse", number: "6", sanskrit: "प्रमाददग्धं पुनश्चतुर्विधं भवति तुत्थं दुर्दग्धं सम्यग्दग्धमतिदग्धं च तत्र यद्विवर्णमूष्यते ऽतिमात्रं तत्तुथम् यत्रोत्तिष्ठन्ति स्फोटास्तीव्रोषादाहरुज श्चिराच्चोपशाम्यन्ति तद्दुर्दग्धम् पक्वतालफलवर्णं समस्थितं पूर्वलक्षणयुक्तं च सम्यग्दग्धम् अतिदग्धे तूग्ररुजता धूमायनं मांसावलम्बनं सिरादिव्यापदो गम्भीरव्रणता ज्वरदाहतृण्मूर्छाच्छर्दयः शोणितातिप्रवृत्तिस्तन्निमित्ताश्चोपदवाः कृच्छ्रेण रोहणं रूढे च विवर्णतेति स्नेहदाहस्तु कष्टतरो भवति स हि स्नेहस्य सूक्ष्ममार्गानुसारित्वाद् दूरमनुप्रविशतीति भवति चात्र", text: "pramādadagdhaṃ punaścaturvidhaṃ bhavati tutthaṃ durdagdhaṃ samyagdagdhamatidagdhaṃ ca tatra yadvivarṇamūṣyate 'timātraṃ tattutham yatrottiṣṭhanti sphoṭāstīvroṣādāharuja ścirāccopaśāmyanti taddurdagdham pakvatālaphalavarṇaṃ samasthitaṃ pūrvalakṣaṇayuktaṃ ca samyagdagdham atidagdhe tūgrarujatā dhūmāyanaṃ māṃsāvalambanaṃ sirādivyāpado gambhīravraṇatā jvaradāhatṛṇmūrchācchardayaḥ śoṇitātipravṛttistannimittāścopadavāḥ kṛcchreṇa rohaṇaṃ rūḍhe ca vivarṇateti snehadāhastu kaṣṭataro bhavati sa hi snehasya sūkṣmamārgānusāritvād dūramanupraviśatīti bhavati cātra" },
      { type: "verse", number: "7", sanskrit: "तुत्थस्यग्निप्रतपनं कार्यमुष्णं च भेषजम् स्त्याने रक्ते हिमैर्नोष्मा निष्क्रामति यतो बहिः", text: "tutthasyagnipratapanaṃ kāryamuṣṇaṃ ca bheṣajam styāne rakte himairnoṣmā niṣkrāmati yato bahiḥ" },
      { type: "verse", number: "8", sanskrit: "वेदना वर्धते तेन रुधिरं च विदह्यते उष्णं निष्क्रामयत् कुर्यादूष्माणं मन्दतां रुजः", text: "vedanā vardhate tena rudhiraṃ ca vidahyate uṣṇaṃ niṣkrāmayat kuryādūṣmāṇaṃ mandatāṃ rujaḥ" },
      { type: "verse", number: "9", sanskrit: "शीतामुष्णां च दुर्दग्धे क्रियां कृत्वा ततः पुनः घृतालेपनसेकांस्तु शीतानेवावचारयेत्", text: "śītāmuṣṇāṃ ca durdagdhe kriyāṃ kṛtvā tataḥ punaḥ ghṛtālepanasekāṃstu śītānevāvacārayet" },
      { type: "verse", number: "10", sanskrit: "सम्यग्दग्धे तवक्षीरीप्लक्षचन्दनगैरिकैः सामृतैः सघृतैर्लेपः कल्कैर्वानूपमांसजैः", text: "samyagdagdhe tavakṣīrīplakṣacandanagairikaiḥ sāmṛtaiḥ saghṛtairlepaḥ kalkairvānūpamāṃsajaiḥ" },
      { type: "verse", number: "11", sanskrit: "शान्तोष्मणि परं कुर्यात् पित्तविद्रधिसाधनम् अतिदग्धे विशीर्णानिमांसान्युद् वृत्य शीतलाम्", text: "śāntoṣmaṇi paraṃ kuryāt pittavidradhisādhanam atidagdhe viśīrṇānimāṃsānyud vṛtya śītalām" },
      { type: "verse", number: "12", sanskrit: "क्रियां कुर्यात्ततः पश्चाच्छालितण्डुलकण्डनैः तिन्दुकीत्वक्कषायैर्वा पिष्टैः साज्यैः प्रेलेपयेत्", text: "kriyāṃ kuryāttataḥ paścācchālitaṇḍulakaṇḍanaiḥ tindukītvakkaṣāyairvā piṣṭaiḥ sājyaiḥ prelepayet" },
      { type: "verse", number: "13", sanskrit: "गुडूच्याश्छादयेत् पत्रैरथवौपोदकैर्व्रणम् भेषजं चास्य कुर्वीत सर्वं पित्तविसर्पवत्", text: "guḍūcyāśchādayet patrairathavaupodakairvraṇam bheṣajaṃ cāsya kurvīta sarvaṃ pittavisarpavat" },
      { type: "verse", number: "14", sanskrit: "स्नेहदग्धे भृशतरं रूक्षं तत्र तु योजयेत् शस्त्रक्षाराग्नयो यस्मान्मृत्योः परममायुधम् अप्रमत्तो भिषक् तस्मात्तान् सम्यगवचारयेत्", text: "snehadagdhe bhṛśataraṃ rūkṣaṃ tatra tu yojayet śastrakṣārāgnayo yasmānmṛtyoḥ paramamāyudham apramatto bhiṣak tasmāttān samyagavacārayet" },
      { type: "verse", number: "15", sanskrit: "इति तन्त्रस्य हृदयं सूत्रस्थानं समाप्यते अत्रार्थाः सूत्रिताः सूक्ष्माः प्रतन्यन्ते हि सर्वतः", text: "iti tantrasya hṛdayaṃ sūtrasthānaṃ samāpyate atrārthāḥ sūtritāḥ sūkṣmāḥ pratanyante hi sarvataḥ" },
    ],
  },
  {
    sthana: "Шарирастхана",
    number: 1,
    lang: "sa",
    content: [
      { type: "heading", heading: "Гарбхавакранти — о развитии эмбриона" },
      { type: "text", text: "Глава 1 Шарирастханы Астанга-санграхи — «Гарбхавакранти» — посвящена анатомическим и эмбриологическим аспектам: о развитии эмбриона." },
      { type: "verse", number: "1", sanskrit: "अथातः पुत्रकामीयमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ putrakāmīyamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अथ खलु पुमानेकविंशतिवर्षः कन्यामतुल्यगोत्रां तुल्याभिजनामसञ्चारिरोगकुलप्रसूतं रूपशीललक्षणसम्पन्नामनूनाविनष्टदन्तौष्ठकर्णनासानखकेशस्तनीं मृदुमरोगप्रकृतिमकपिलमपिङ्गलामहीनाधिकाङ्गीं द्वादशवर्षदेशीयाममरभुजगसरिदचलवृक्षपक्षिनक्षत्रान्त्यप्रेष्यभीषणकनामान्यनुद्वहन्तीमनघामनिन्द्यामनिन्द्येन विधिनोद्वहेत्", text: "atha khalu pumānekaviṃśativarṣaḥ kanyāmatulyagotrāṃ tulyābhijanāmasañcārirogakulaprasūtaṃ rūpaśīlalakṣaṇasampannāmanūnāvinaṣṭadantauṣṭhakarṇanāsānakhakeśastanīṃ mṛdumarogaprakṛtimakapilamapiṅgalāmahīnādhikāṅgīṃ dvādaśavarṣadeśīyāmamarabhujagasaridacalavṛkṣapakṣinakṣatrāntyapreṣyabhīṣaṇakanāmānyanudvahantīmanaghāmanindyāmanindyena vidhinodvahet" },
      { type: "verse", number: "3", sanskrit: "तस्यां षोडशवर्षायां पञ्चविंशतिवर्षः पुरुषः पुत्रार्थं प्रयतेत तदा हि तौ प्राप्तवीर्यौ वीर्यान्वितमपत्यं जनयतः ऊनपञ्चविंशतिवर्षेणोनषोडशवर्षायामाहितो गर्भः कुक्षिस्थ एव विनाशमाप्नुयादल्पायुर्बलारोग्यविभवो वा स्याद्विकलेन्द्रियो वा ऋतावाद्ये च रात्रित्रये तथा दुष्टे शुक्रार्तव इति", text: "tasyāṃ ṣoḍaśavarṣāyāṃ pañcaviṃśativarṣaḥ puruṣaḥ putrārthaṃ prayateta tadā hi tau prāptavīryau vīryānvitamapatyaṃ janayataḥ ūnapañcaviṃśativarṣeṇonaṣoḍaśavarṣāyāmāhito garbhaḥ kukṣistha eva vināśamāpnuyādalpāyurbalārogyavibhavo vā syādvikalendriyo vā ṛtāvādye ca rātritraye tathā duṣṭe śukrārtava iti" },
      { type: "verse", number: "4", sanskrit: "तत्राहारस्य सम्यक्परिणतस्य क्रमान्मज्जानमनुप्राप्तस्य सारः शुक्रसंज्ञां लभते तत्तु क्षीर इव सर्पिरिक्षुरस इव गुडः शरीरे शुक्रधरां कलामाश्रित्यास्रुतं सर्वाङ्गव्यापितया स्थितम् विशेषतश्च मज्जमुष्कस्तनेषु हर्षोदीरितं तु संघट्टनेन हृदयावेशात् पिण्डीभूतमङ्गादङ्गात् प्रवर्तते तत् सौम्यं स्निग्धं गुरु शुक्लं मधुगन्धि मधुरं पिच्छिलं बहु बहलं घृततैलक्षौद्रान्यतमवर्णं च शुक्रं गर्भाधानयोग्यं भवति", text: "tatrāhārasya samyakpariṇatasya kramānmajjānamanuprāptasya sāraḥ śukrasaṃjñāṃ labhate tattu kṣīra iva sarpirikṣurasa iva guḍaḥ śarīre śukradharāṃ kalāmāśrityāsrutaṃ sarvāṅgavyāpitayā sthitam viśeṣataśca majjamuṣkastaneṣu harṣodīritaṃ tu saṃghaṭṭanena hṛdayāveśāt piṇḍībhūtamaṅgādaṅgāt pravartate tat saumyaṃ snigdhaṃ guru śuklaṃ madhugandhi madhuraṃ picchilaṃ bahu bahalaṃ ghṛtatailakṣaudrānyatamavarṇaṃ ca śukraṃ garbhādhānayogyaṃ bhavati" },
      { type: "verse", number: "5", sanskrit: "तथा रक्तमेव च स्त्रीणां मासे मासे गर्भकोष्ठमनुप्राप्य त्र्यहं प्रवर्तमानमार्तवमित्याहुः अतिप्रसङ्गेनानृतावृतौ वा तदेवासृग्दरं प्रदरं व्यापदं च रक्तयोनिसंज्ञां लभते तत्साधने रक्तपित्तचिकित्सितं गुह्यरोगप्रतिषेधं चेक्षेत", text: "tathā raktameva ca strīṇāṃ māse māse garbhakoṣṭhamanuprāpya tryahaṃ pravartamānamārtavamityāhuḥ atiprasaṅgenānṛtāvṛtau vā tadevāsṛgdaraṃ pradaraṃ vyāpadaṃ ca raktayonisaṃjñāṃ labhate tatsādhane raktapittacikitsitaṃ guhyarogapratiṣedhaṃ cekṣeta" },
      { type: "verse", number: "6", sanskrit: "वातकफावृतमार्गाणां चाप्रवर्तमानं पित्तलैरुपाचरेत् तद्धि वर्द्धमानमन्तर्वर्तमानं सशुक्रमशुक्रं वा जीवरहितं वातलान्यासेवमानाया योषितो गर्भलिङ्गानि दर्शयद् गुल्मीभवति तत्र गुल्मचिकित्सितमीक्षेत", text: "vātakaphāvṛtamārgāṇāṃ cāpravartamānaṃ pittalairupācaret taddhi varddhamānamantarvartamānaṃ saśukramaśukraṃ vā jīvarahitaṃ vātalānyāsevamānāyā yoṣito garbhaliṅgāni darśayad gulmībhavati tatra gulmacikitsitamīkṣeta" },
      { type: "verse", number: "7", sanskrit: "कदाचिद्वा गर्भ इव वातोदरं भवति तद्वातोपशमनैरुपशाम्यति", text: "kadācidvā garbha iva vātodaraṃ bhavati tadvātopaśamanairupaśāmyati" },
      { type: "verse", number: "8", sanskrit: "तदेव कदाचिदार्तवं सौम्यैर्बृंहणात्मभिराहारविहारैः स्तम्भितमनुपद्रवमेवोदरं गर्भाधिष्ठितमिव वर्धयति येन तामगर्भां गर्भिणीमाहुर्मूढाः ततो विपरीतैर्यदृच्छया वा प्रवृत्ते रक्ते गर्भशरीरमपश्यन्तो भूतहृतमित्यज्ञा व्रुवते यस्मात्सम्भवत्योजसो ऽपहरणं रक्षोभिर्न तु शरीरापहरणमनिष्टत्वादशक्तेर्वा इच्छाशक्त्योर्हि प्रवृत्तेरुपलब्धिः न च दृश्यते कस्यचिदमानुषैर्देहापहारः", text: "tadeva kadācidārtavaṃ saumyairbṛṃhaṇātmabhirāhāravihāraiḥ stambhitamanupadravamevodaraṃ garbhādhiṣṭhitamiva vardhayati yena tāmagarbhāṃ garbhiṇīmāhurmūḍhāḥ tato viparītairyadṛcchayā vā pravṛtte rakte garbhaśarīramapaśyanto bhūtahṛtamityajñā vruvate yasmātsambhavatyojaso 'paharaṇaṃ rakṣobhirna tu śarīrāpaharaṇamaniṣṭatvādaśaktervā icchāśaktyorhi pravṛtterupalabdhiḥ na ca dṛśyate kasyacidamānuṣairdehāpahāraḥ" },
      { type: "verse", number: "9", sanskrit: "यदि च दृष्टमपि समुल्लङ्घ्य केचिदतिशक्तियुक्ता गर्भस्य शरीराक्षेपे प्रवर्तन्ते तदा कथमिव प्राप्तावसरास्तज्जननीमुपेक्षेरन्", text: "yadi ca dṛṣṭamapi samullaṅghya kecidatiśaktiyuktā garbhasya śarīrākṣepe pravartante tadā kathamiva prāptāvasarāstajjananīmupekṣeran" },
      { type: "verse", number: "10", sanskrit: "आर्तवं पुनश्शशरुधिरलाक्षारसोपमं धौतं च विरज्यमानं शुद्धमाहुः", text: "ārtavaṃ punaśśaśarudhiralākṣārasopamaṃ dhautaṃ ca virajyamānaṃ śuddhamāhuḥ" },
      { type: "verse", number: "11", sanskrit: "यथा च बालस्य जीर्णस्य वा तरोः पुष्पफलं पुष्पफलस्य वा तद्विधस्य गन्धो नोपलभ्यते तथैव नोनषोडशातीतसप्तीतवर्षस्य पुंसः शुक्ररोमादयो योषितश्चोनद्वादशातीतपञ्चाशद्वर्षाया रजस्तन्यादय इति", text: "yathā ca bālasya jīrṇasya vā taroḥ puṣpaphalaṃ puṣpaphalasya vā tadvidhasya gandho nopalabhyate tathaiva nonaṣoḍaśātītasaptītavarṣasya puṃsaḥ śukraromādayo yoṣitaśconadvādaśātītapañcāśadvarṣāyā rajastanyādaya iti" },
      { type: "verse", number: "12", sanskrit: "अथ शुद्धशुक्रार्तवमरोगं मिथो ऽनुरक्तं मिथुनमुपस्नेह्य विधिवत् संशोध्यास्थापनानुवासनाभ्यामुपाचरेत् विशेषतस्तु घृतक्षीरवद्भिर्मधुरौषधसंस्कारैः पुरुषम् तैलेन नारीं पित्तलैश्च मांसैः एवं हि समानगुणतया शुक्रार्तवमाप्यायते", text: "atha śuddhaśukrārtavamarogaṃ mitho 'nuraktaṃ mithunamupasnehya vidhivat saṃśodhyāsthāpanānuvāsanābhyāmupācaret viśeṣatastu ghṛtakṣīravadbhirmadhurauṣadhasaṃskāraiḥ puruṣam tailena nārīṃ pittalaiśca māṃsaiḥ evaṃ hi samānaguṇatayā śukrārtavamāpyāyate" },
      { type: "verse", number: "13", sanskrit: "वातपित्तश्लेष्मकुणपगन्धिग्रन्थिपूयक्षीणमूत्रपुरीषरेतांसि त्वबीजानि भवन्ति तत्र तनु रूक्षं फेनिलमरुणमल्पं विच्छिन्नं सरुजं चिराच्च निषिच्येत वातेन किञ्चित्पीतमपिच्छिलमानीलं वा दहदिव प्रवर्तते पित्तेन मज्जोपसंसृष्टं प्रभूतं विबद्धं चाम्भसि च किञ्चिन्मज्जति श्लेष्मणा कुणपगन्ध्यनल्पं रक्तेन ग्रन्थिभूतं वातश्लेष्मभ्याम् पूतिपूयनिभं पित्तश्लेष्मभ्याम् क्षीणं वातपित्ताभ्याम् तदुक्तं ससाधनं प्राक् मूत्रपुरीषगन्धि सन्निपातेन", text: "vātapittaśleṣmakuṇapagandhigranthipūyakṣīṇamūtrapurīṣaretāṃsi tvabījāni bhavanti tatra tanu rūkṣaṃ phenilamaruṇamalpaṃ vicchinnaṃ sarujaṃ cirācca niṣicyeta vātena kiñcitpītamapicchilamānīlaṃ vā dahadiva pravartate pittena majjopasaṃsṛṣṭaṃ prabhūtaṃ vibaddhaṃ cāmbhasi ca kiñcinmajjati śleṣmaṇā kuṇapagandhyanalpaṃ raktena granthibhūtaṃ vātaśleṣmabhyām pūtipūyanibhaṃ pittaśleṣmabhyām kṣīṇaṃ vātapittābhyām taduktaṃ sasādhanaṃ prāk mūtrapurīṣagandhi sannipātena" },
      { type: "verse", number: "14", sanskrit: "आर्तवमपि शुक्रवद्दोषैरुपसृष्टमबीजमेव तस्य लिङ्गं नाम च पूर्ववत् तेषु कुणपग्रन्थिपूयक्षीणरेतांसि कृच्छ्रसाध्यानि मूत्रपुरीषशुक्रातवं त्वसाध्यं कुणपग्रन्थिपूयार्तवं च तत्राद्यांस्त्रीन् शुक्रार्तवदोषान्यथास्वं दोषसाधनेन साधयेत् गुह्ययोनिरोगप्रतिषेधेन चोभयान्", text: "ārtavamapi śukravaddoṣairupasṛṣṭamabījameva tasya liṅgaṃ nāma ca pūrvavat teṣu kuṇapagranthipūyakṣīṇaretāṃsi kṛcchrasādhyāni mūtrapurīṣaśukrātavaṃ tvasādhyaṃ kuṇapagranthipūyārtavaṃ ca tatrādyāṃstrīn śukrārtavadoṣānyathāsvaṃ doṣasādhanena sādhayet guhyayonirogapratiṣedhena cobhayān" },
      { type: "verse", number: "15", sanskrit: "अपि च वातिके शुक्रदोषे वसुकसैन्धवफलाम्लसिद्धं यवक्षारप्रतीवापं सर्पिष्पानम् बिल्वविदारीसिद्धं क्षीरयुक्तमास्थापनम् मधुकभद्रदारुसिद्धं तैलमनुवासनम् क्षीरकुलीररससिद्धं तैलमुत्तरबस्तिः पैत्तिके काण्डेक्षुश्वदंष्ट्रागुडूचीसिद्धं मूर्वामधूकप्रतीवापं सर्पिष्पानम् त्रिवृच्चूर्णः सघृतो विरेकः पयस्याश्रीपर्णीसिद्धं क्षीरयुक्तमास्थापनम् मधुकमुद्गपर्णीसिद्धं तैलमनुवासनमुत्तरबस्तिश्च श्लैष्मिके पाषाणभेदाश्मन्तकामलकक्वाथसिद्धं पिप्पलीमधुकचूर्णप्रतीवापं सर्पिष्पानम् मदनफलकषायो वमनम् दन्तीविडङ्गचूर्णस्तैललीढो विरेकः राजवृक्षमदनफलकषायप्रगाढमास्थापनम् मधुकपिप्पलीसिद्धं तैलमनुवासनमुत्तरबस्तिश्च", text: "api ca vātike śukradoṣe vasukasaindhavaphalāmlasiddhaṃ yavakṣārapratīvāpaṃ sarpiṣpānam bilvavidārīsiddhaṃ kṣīrayuktamāsthāpanam madhukabhadradārusiddhaṃ tailamanuvāsanam kṣīrakulīrarasasiddhaṃ tailamuttarabastiḥ paittike kāṇḍekṣuśvadaṃṣṭrāguḍūcīsiddhaṃ mūrvāmadhūkapratīvāpaṃ sarpiṣpānam trivṛccūrṇaḥ saghṛto virekaḥ payasyāśrīparṇīsiddhaṃ kṣīrayuktamāsthāpanam madhukamudgaparṇīsiddhaṃ tailamanuvāsanamuttarabastiśca ślaiṣmike pāṣāṇabhedāśmantakāmalakakvāthasiddhaṃ pippalīmadhukacūrṇapratīvāpaṃ sarpiṣpānam madanaphalakaṣāyo vamanam dantīviḍaṅgacūrṇastailalīḍho virekaḥ rājavṛkṣamadanaphalakaṣāyapragāḍhamāsthāpanam madhukapippalīsiddhaṃ tailamanuvāsanamuttarabastiśca" },
      { type: "verse", number: "16", sanskrit: "वातजे पुष्पदोषे भार्ङ्गीमधुकभद्रदारुसिद्धं सर्पिष्पानम् काश्मर्यक्षुद्रसहासिद्धं वा क्षीरम् मधुकसृगालविन्नाकल्कं पयस्सर्पिस्सहितं प्रियङ्गुतिलकल्कं वा योनौ धारयेत् सरलमुद्गपर्णीकषायः प्रक्षालनम् पित्तजे काकोलीद्वयविदारीमूलक्वाथमुत्पलपद्मकक्वाथं मधूकपुष्पकाश्मर्यफलक्वाथं वा सशर्करं पिबेत् श्वेतचन्दक्वाथं वा सक्षौद्रम् धवधातकीकल्कं वा घृतेन वा मधुकमधुरसामृद्वीकाकल्कम् शम्याकगवाक्षीक्षीरं विरेकः चन्दनपयस्याकल्कं योनौ धारयेत् गौरिकारिष्टकषायः प्रक्षालनम् श्लैष्मिके कुटजकटुकाश्वगन्धाक्वाथं पिबेत् समाक्षिकं वा क्षीरिवृक्षप्रवालक्वाथमेतेषामेव वा चूर्णं मधुघृताभ्यां लिह्यात् मदनफलकषायेण वमनम् तत्कल्कमेव च योनौ धारयेत् लोध्रतिन्दुककषायः प्रक्षालनं बस्तमेषमूत्रं वा", text: "vātaje puṣpadoṣe bhārṅgīmadhukabhadradārusiddhaṃ sarpiṣpānam kāśmaryakṣudrasahāsiddhaṃ vā kṣīram madhukasṛgālavinnākalkaṃ payassarpissahitaṃ priyaṅgutilakalkaṃ vā yonau dhārayet saralamudgaparṇīkaṣāyaḥ prakṣālanam pittaje kākolīdvayavidārīmūlakvāthamutpalapadmakakvāthaṃ madhūkapuṣpakāśmaryaphalakvāthaṃ vā saśarkaraṃ pibet śvetacandakvāthaṃ vā sakṣaudram dhavadhātakīkalkaṃ vā ghṛtena vā madhukamadhurasāmṛdvīkākalkam śamyākagavākṣīkṣīraṃ virekaḥ candanapayasyākalkaṃ yonau dhārayet gaurikāriṣṭakaṣāyaḥ prakṣālanam ślaiṣmike kuṭajakaṭukāśvagandhākvāthaṃ pibet samākṣikaṃ vā kṣīrivṛkṣapravālakvāthameteṣāmeva vā cūrṇaṃ madhughṛtābhyāṃ lihyāt madanaphalakaṣāyeṇa vamanam tatkalkameva ca yonau dhārayet lodhratindukakaṣāyaḥ prakṣālanaṃ bastameṣamūtraṃ vā" },
      { type: "verse", number: "17", sanskrit: "कुणपरेतसि धातकीपुष्पखदिरार्जुनदाडिमैः सिद्धमसनादिभिर्वा सर्पिः पाययेत् ग्रन्थिरेतसि पाषाणाभिदा पलाशभस्मना वा पूयरेतसि परूषकादिन्यग्रोधादिभ्याम् मूत्रपुरीषरेतसि वायुनातिविकृते हिङ्गूशीरचित्रकैरथवा चित्रकवितुन्नकप्रियङ्गुहिङ्गुसमङ्गामृणालसिद्धमेलामोचचूर्णप्रतीवापम् तथा ग्रन्थ्यार्तवे पाठात्रिकण्टकवृक्षकक्वाथम् कुणपपूयार्तवे चन्दनक्वाथं पिबेत् त्रिफलाकल्कक्वाथौ चात्र धारणाचमने", text: "kuṇaparetasi dhātakīpuṣpakhadirārjunadāḍimaiḥ siddhamasanādibhirvā sarpiḥ pāyayet granthiretasi pāṣāṇābhidā palāśabhasmanā vā pūyaretasi parūṣakādinyagrodhādibhyām mūtrapurīṣaretasi vāyunātivikṛte hiṅgūśīracitrakairathavā citrakavitunnakapriyaṅguhiṅgusamaṅgāmṛṇālasiddhamelāmocacūrṇapratīvāpam tathā granthyārtave pāṭhātrikaṇṭakavṛkṣakakvātham kuṇapapūyārtave candanakvāthaṃ pibet triphalākalkakvāthau cātra dhāraṇācamane" },
      { type: "verse", number: "18", sanskrit: "सर्वेषु च शुक्रार्तवदोषेषु स्त्रीपुंसौ स्नेहादिकर्मभिर्विशेषेण चोत्तरबस्तिभिः पुनः पुनरुपाचरेत् यथास्वं च योनौ कल्कैः पिचुभिश्च इत्येवं विशुद्धशुक्रार्तवौ पूर्वोक्तं विधिमासेवेवाम्", text: "sarveṣu ca śukrārtavadoṣeṣu strīpuṃsau snehādikarmabhirviśeṣeṇa cottarabastibhiḥ punaḥ punarupācaret yathāsvaṃ ca yonau kalkaiḥ picubhiśca ityevaṃ viśuddhaśukrārtavau pūrvoktaṃ vidhimāsevevām" },
      { type: "verse", number: "19", sanskrit: "ऋतुस्तु दृष्टार्तवो द्वादशरात्रं भवति षोडशरात्रमित्यन्ये शुद्धयोनिगर्भाशयार्तवाया मासमपि केचित् तद्वददृष्टार्तवो ऽप्यस्तीत्यपरे", text: "ṛtustu dṛṣṭārtavo dvādaśarātraṃ bhavati ṣoḍaśarātramityanye śuddhayonigarbhāśayārtavāyā māsamapi kecit tadvadadṛṣṭārtavo 'pyastītyapare" },
      { type: "verse", number: "20", sanskrit: "क्षामप्रसन्नवदनां स्फुरच्छ्रोणिपयोधराम् स्रास्ताक्षिकुक्षिं पुंस्कामां विद्यादृतुमतीं स्त्रियम्", text: "kṣāmaprasannavadanāṃ sphuracchroṇipayodharām srāstākṣikukṣiṃ puṃskāmāṃ vidyādṛtumatīṃ striyam" },
      { type: "verse", number: "21", sanskrit: "पद्मं संकोचमायाति दिने ऽतीते यथा तथा ऋतावतीते योनिःस्याच्छुक्रंनातः प्रतीच्छति", text: "padmaṃ saṃkocamāyāti dine 'tīte yathā tathā ṛtāvatīte yoniḥsyācchukraṃnātaḥ pratīcchati" },
      { type: "verse", number: "22", sanskrit: "मसेनोपचितं रक्तं धमनीभ्यामृतौ पुनः ईषत्कृष्णं विगन्धं च वायुर्योनिमुखान्नुदेत्", text: "masenopacitaṃ raktaṃ dhamanībhyāmṛtau punaḥ īṣatkṛṣṇaṃ vigandhaṃ ca vāyuryonimukhānnudet" },
      { type: "verse", number: "23", sanskrit: "ततः पुष्पदर्शने प्रथमदिवसात् प्रभृति ब्रह्मचारिणी स्नानाद्यलङ्काररहिता दर्भसंस्तरशायिनी त्रिरात्रमासीत पर्णशरावकरतलान्यतमेन यावकं पयसा सिद्धमल्पं कर्शनार्थमश्नीयात् तीक्ष्णोष्णाम्ललवणानि च वर्जयेत्", text: "tataḥ puṣpadarśane prathamadivasāt prabhṛti brahmacāriṇī snānādyalaṅkārarahitā darbhasaṃstaraśāyinī trirātramāsīta parṇaśarāvakaratalānyatamena yāvakaṃ payasā siddhamalpaṃ karśanārthamaśnīyāt tīkṣṇoṣṇāmlalavaṇāni ca varjayet" },
      { type: "verse", number: "24", sanskrit: "चतुर्थे ऽहन्युद्वर्तिता शीतसलिलस्नातानुलिप्तालङ्कृताशुक्लमाल्याम्बरा कृतमङ्गलस्वस्त्ययनैवंविधमेव भर्तारं पश्येदनन्यमनाः तदा हि यादृशमेव पश्यति चिन्तयति वा तादृशं प्रसूत इति", text: "caturthe 'hanyudvartitā śītasalilasnātānuliptālaṅkṛtāśuklamālyāmbarā kṛtamaṅgalasvastyayanaivaṃvidhameva bhartāraṃ paśyedananyamanāḥ tadā hi yādṛśameva paśyati cintayati vā tādṛśaṃ prasūta iti" },
      { type: "verse", number: "25", sanskrit: "ततः स्नानात् पुनरपि गुणवत्पुत्रार्थी त्रिरात्रमुपेक्षेत पुष्पदर्शनात् सप्तरात्रम् अथाष्टम्यां दशम्यां द्वादश्यां वा रात्रौ पुत्रकामः संवसेत् पच्चम्यां सप्तम्यां नवम्यां वा दुहितृकामः तासूत्तरोत्तरमायुरारोग्यैश्वर्यसौभाग्यबलवर्णेन्द्रियसम्पदपत्यस्य भवति अतः परं तूत्तरोत्तरमेवायुरादीनां ह्रासः", text: "tataḥ snānāt punarapi guṇavatputrārthī trirātramupekṣeta puṣpadarśanāt saptarātram athāṣṭamyāṃ daśamyāṃ dvādaśyāṃ vā rātrau putrakāmaḥ saṃvaset paccamyāṃ saptamyāṃ navamyāṃ vā duhitṛkāmaḥ tāsūttarottaramāyurārogyaiśvaryasaubhāgyabalavarṇendriyasampadapatyasya bhavati ataḥ paraṃ tūttarottaramevāyurādīnāṃ hrāsaḥ" },
      { type: "verse", number: "26", sanskrit: "तत्र युग्मासु रात्रिष्वल्पीभवत्यार्तवमयुग्मास्वाप्याय्यते तस्मात्तासु क्रमात् पुत्रस्य दुहितुश्च जन्म अत एव चानुपरतार्तवदर्शनां पुत्रार्थी विप्रकृष्टेष्वप्यहस्सु नोपेयात् यदि त्वाहारानुरोधादयुग्मासु शुक्रस्याधिकता युग्मासु च न्यूनता स्यात्ततः पुमान् स्त्र्याकृतिर्दुर्बलो हीनाङ्गो वा जायते स्त्री च पुरुषाकृतिर्दुर्बला हीनाङ्गा वा एकादशीत्रयोदश्योस्तु नपुंसकं स्यात्", text: "tatra yugmāsu rātriṣvalpībhavatyārtavamayugmāsvāpyāyyate tasmāttāsu kramāt putrasya duhituśca janma ata eva cānuparatārtavadarśanāṃ putrārthī viprakṛṣṭeṣvapyahassu nopeyāt yadi tvāhārānurodhādayugmāsu śukrasyādhikatā yugmāsu ca nyūnatā syāttataḥ pumān stryākṛtirdurbalo hīnāṅgo vā jāyate strī ca puruṣākṛtirdurbalā hīnāṅgā vā ekādaśītrayodaśyostu napuṃsakaṃ syāt" },
      { type: "verse", number: "27", sanskrit: "अथोपाध्यायः पुत्रीयं विधानमाचरेत् शूद्रायास्तु मन्त्रवर्जितम् यादृशं च पुत्रमाशासीत तद्रूपवर्णचरितान् जनपदाननुचिन्तयेति स्त्री वाच्या तज्जनपदाहारविहारोपचारपरिच्छदांश्चानुविदघीत", text: "athopādhyāyaḥ putrīyaṃ vidhānamācaret śūdrāyāstu mantravarjitam yādṛśaṃ ca putramāśāsīta tadrūpavarṇacaritān janapadānanucintayeti strī vācyā tajjanapadāhāravihāropacāraparicchadāṃścānuvidaghīta" },
      { type: "verse", number: "28", sanskrit: "कर्मान्ते च पुमान् मासं ब्रह्मचारी सर्पिः क्षीराभ्या शाल्योदनमभिप्राश्य नात्याशितः सुखी स्रग्वी सुमनाः प्रीणिताङ्गः शुक्लनिवसनो मौहूर्तिकानुमते रात्रिभागे कल्याणानि चिन्तयानस्तदभिकामः स्वास्तीर्णं शयनं दक्षिणेन पादेन प्रागारोहेत् ताद्विधैव च प्रमदा कर्णिताङ्गी तैलमाषोत्तराहारा पूर्वं वामपादेन पुरुषस्य दक्षिणतः शय्यामधिरोहेत् तत्र मन्त्रं प्रयुञ्जीत आयुरसि सर्वतः प्रतिष्ठासि धाता त्वा दधातु विधाता त्वा दधातु ब्रह्मवर्चसा भवेति ब्रह्माबृहस्पतिर्विष्णुस्सोमस्सूर्यस्तथाश्विनौ भगो ऽथ मित्रावरुणौ वीरं दधतु मे सुतमिति", text: "karmānte ca pumān māsaṃ brahmacārī sarpiḥ kṣīrābhyā śālyodanamabhiprāśya nātyāśitaḥ sukhī sragvī sumanāḥ prīṇitāṅgaḥ śuklanivasano mauhūrtikānumate rātribhāge kalyāṇāni cintayānastadabhikāmaḥ svāstīrṇaṃ śayanaṃ dakṣiṇena pādena prāgārohet tādvidhaiva ca pramadā karṇitāṅgī tailamāṣottarāhārā pūrvaṃ vāmapādena puruṣasya dakṣiṇataḥ śayyāmadhirohet tatra mantraṃ prayuñjīta āyurasi sarvataḥ pratiṣṭhāsi dhātā tvā dadhātu vidhātā tvā dadhātu brahmavarcasā bhaveti brahmābṛhaspatirviṣṇussomassūryastathāśvinau bhago 'tha mitrāvaruṇau vīraṃ dadhatu me sutamiti" },
      { type: "verse", number: "29", sanskrit: "ततः परस्परं सामभिरभिसान्त्व्य सहर्षमनुकूलं संविशेताम् पर्याप्ते चैनां शीतोदकेन सहसा परिषिञ्चेत्", text: "tataḥ parasparaṃ sāmabhirabhisāntvya saharṣamanukūlaṃ saṃviśetām paryāpte caināṃ śītodakena sahasā pariṣiñcet" },
      { type: "verse", number: "30", sanskrit: "तत्रात्याशिता क्षुधिता पिपासिता भीता विमनाः शोकार्ता क्रुद्धातिमेदुरान्यकामा ऽव्यवायकामा वा न गर्भं धत्ते विगुणं वा तथा पुरुषो ऽपि न चासौअधस्तिष्ठेत् तथा हि स्त्रीचेष्टः पुमान् जायते पुंश्चेष्टा वा स्त्री न च न्युब्जां पार्श्वगतां वा सेवेत न्युब्जाया वातो बलवान् स योनिं पीडयति दक्षिणपार्श्वगतायाः श्लेष्मा पीडितश्च्युतः पिदधाति गर्भाशयम् वामपार्श्वगतायास्तद्वत् पित्तं विदहति रक्तशुक्रे तस्मादुत्ताना बीजं गृह्णीयात् तथा हि यथास्थानमेव तिष्ठन्ति दोषाः", text: "tatrātyāśitā kṣudhitā pipāsitā bhītā vimanāḥ śokārtā kruddhātimedurānyakāmā 'vyavāyakāmā vā na garbhaṃ dhatte viguṇaṃ vā tathā puruṣo 'pi na cāsauadhastiṣṭhet tathā hi strīceṣṭaḥ pumān jāyate puṃśceṣṭā vā strī na ca nyubjāṃ pārśvagatāṃ vā seveta nyubjāyā vāto balavān sa yoniṃ pīḍayati dakṣiṇapārśvagatāyāḥ śleṣmā pīḍitaścyutaḥ pidadhāti garbhāśayam vāmapārśvagatāyāstadvat pittaṃ vidahati raktaśukre tasmāduttānā bījaṃ gṛhṇīyāt tathā hi yathāsthānameva tiṣṭhanti doṣāḥ" },
      { type: "verse", number: "31", sanskrit: "लब्धगर्भां चैनां विदित्वा प्राग्व्यक्तीभावाद्गर्भस्य पुष्ये पुंसवनानि प्रयुञ्जीत द्वादशरात्रमित्यन्ये तत्रापि युग्मदिनेष्विति केचित् प्रत्यहमित्यपरे", text: "labdhagarbhāṃ caināṃ viditvā prāgvyaktībhāvādgarbhasya puṣye puṃsavanāni prayuñjīta dvādaśarātramityanye tatrāpi yugmadineṣviti kecit pratyahamityapare" },
      { type: "verse", number: "32", sanskrit: "तद्यथा लक्ष्मणावटशृङ्गसहदेवाविश्वदेवानामन्यतमं क्षीरे ऽभिषुत्य त्रींश्चतुरो वा बिन्दून् दक्षिणे नासापुटे स्वयमासिञ्चेत् पिचुना वामे तु दुहितृकामा न चैतान् निष्ठीवेत् तथा पुष्योद्घृतायाः श्वेतबृहत्या मूलकल्काद्रसं नावयेत् तद्वच्चोत्पलपत्रं कुमुदपत्र लक्ष्मणामूलं वटशृङ्गानि चाष्टौ च नावयेत्", text: "tadyathā lakṣmaṇāvaṭaśṛṅgasahadevāviśvadevānāmanyatamaṃ kṣīre 'bhiṣutya trīṃścaturo vā bindūn dakṣiṇe nāsāpuṭe svayamāsiñcet picunā vāme tu duhitṛkāmā na caitān niṣṭhīvet tathā puṣyodghṛtāyāḥ śvetabṛhatyā mūlakalkādrasaṃ nāvayet tadvaccotpalapatraṃ kumudapatra lakṣmaṇāmūlaṃ vaṭaśṛṅgāni cāṣṭau ca nāvayet" },
      { type: "verse", number: "33", sanskrit: "शुक्लमाल्याम्बरधरा च नारी पुष्योद्धृताया लक्ष्मणाया मूलकल्कमुदुम्बरमात्रं पयसा पिबेत् पुत्रस्योत्पादनाय स्थितये च तद्वद्गौरदण्डमपामार्गं जीवकर्षभकौ शङ्खषुष्पीमध्यदण्डां सहचरं नग्नजितमग्निजिव्यामष्टौ वा वटशृङ्गानि शालिपिष्टस्य च पच्यमानस्योष्माणमाघ्राय तद्रसं देहल्यां स्थिता पूर्ववन्नावयेत्", text: "śuklamālyāmbaradharā ca nārī puṣyoddhṛtāyā lakṣmaṇāyā mūlakalkamudumbaramātraṃ payasā pibet putrasyotpādanāya sthitaye ca tadvadgauradaṇḍamapāmārgaṃ jīvakarṣabhakau śaṅkhaṣuṣpīmadhyadaṇḍāṃ sahacaraṃ nagnajitamagnijivyāmaṣṭau vā vaṭaśṛṅgāni śālipiṣṭasya ca pacyamānasyoṣmāṇamāghrāya tadrasaṃ dehalyāṃ sthitā pūrvavannāvayet" },
      { type: "verse", number: "34", sanskrit: "यच्चान्यदपि ब्राह्मणा वृद्धस्त्रियो वा ब्रूयुस्तच्च कुर्यात् ततः प्रजास्थापनाख्या दशौषधीः शिरसा दक्षिणेन च पाणिना धारयेत् एताभिश्च सिद्धं पयो घृतं वा पिबेत् एताभिरेव पुष्ये पुष्ये स्नायात् सदा च समालभेत तथा सर्वासां जीवनीयानामौषधीनां सदोपयोगस्तैस्तैर्विधानैरिति गर्भस्थापनानि", text: "yaccānyadapi brāhmaṇā vṛddhastriyo vā brūyustacca kuryāt tataḥ prajāsthāpanākhyā daśauṣadhīḥ śirasā dakṣiṇena ca pāṇinā dhārayet etābhiśca siddhaṃ payo ghṛtaṃ vā pibet etābhireva puṣye puṣye snāyāt sadā ca samālabheta tathā sarvāsāṃ jīvanīyānāmauṣadhīnāṃ sadopayogastaistairvidhānairiti garbhasthāpanāni" },
      { type: "verse", number: "35", sanskrit: "सौम्याकृतिवचनोपचारचेष्टाश्च प्रियहितानुवर्तिनः परिचारकास्तथा भर्तेति पुनश्चैनां मासादुपेयात्", text: "saumyākṛtivacanopacāraceṣṭāśca priyahitānuvartinaḥ paricārakāstathā bharteti punaścaināṃ māsādupeyāt" },
      { type: "verse", number: "36", sanskrit: "तत्र शुक्रे शुक्ले घृतमण्डाभे वा गर्भस्य गौरत्वं तैलाभे कृष्णत्वं मध्वाभे श्यामत्वम् तथा क्षीरादिमधुराणामुपयोगान्मातुरुदकविहाराच्च गौरता तिलान्नविदाहिना कृष्णता व्यामिश्राणां श्यामता देशकुलानुवृत्तितश्च वर्णभेदः", text: "tatra śukre śukle ghṛtamaṇḍābhe vā garbhasya gauratvaṃ tailābhe kṛṣṇatvaṃ madhvābhe śyāmatvam tathā kṣīrādimadhurāṇāmupayogānmāturudakavihārācca gauratā tilānnavidāhinā kṛṣṇatā vyāmiśrāṇāṃ śyāmatā deśakulānuvṛttitaśca varṇabhedaḥ" },
      { type: "verse", number: "37", sanskrit: "तथा तेजोधातोरुदकाकाशधातुसम्पर्काद्गौरता भूवायुसम्पर्कात् कृष्णता सर्वधातुसाम्ये श्यामता", text: "tathā tejodhātorudakākāśadhātusamparkādgauratā bhūvāyusamparkāt kṛṣṇatā sarvadhātusāmye śyāmatā" },
      { type: "verse", number: "38", sanskrit: "सत्वविशेषकराणि पुनर्मातापितृसत्वादयो ऽन्तर्वत्न्याः श्रुतयश्चाभीक्ष्णं स्वोपचितं च कर्म भवति पूर्वाभ्यासश्चेति", text: "satvaviśeṣakarāṇi punarmātāpitṛsatvādayo 'ntarvatnyāḥ śrutayaścābhīkṣṇaṃ svopacitaṃ ca karma bhavati pūrvābhyāsaśceti" },
      { type: "verse", number: "39", sanskrit: "भवन्ति चात्र घृतक्षीरादिनित्यासु मुदितासु कफात्मसु आर्तवं तिष्ठत्ति चिरं विपरीतास्वतो ऽन्यथा", text: "bhavanti cātra ghṛtakṣīrādinityāsu muditāsu kaphātmasu ārtavaṃ tiṣṭhatti ciraṃ viparītāsvato 'nyathā" },
      { type: "verse", number: "40", sanskrit: "निपातादेव गृह्णाति रागं वासो यथा ऽमलम् ध्रुवं गर्भं तथा बीजं क्षेत्रं बीजमुपस्कृतम्", text: "nipātādeva gṛhṇāti rāgaṃ vāso yathā 'malam dhruvaṃ garbhaṃ tathā bījaṃ kṣetraṃ bījamupaskṛtam" },
      { type: "verse", number: "41", sanskrit: "अविरुद्धे ध्रुवं दैवे काले युक्तस्य कर्मणः सिद्धिः पुंसवनाद्यस्मात् पूर्वं व्यक्तेः प्रयोजयेत्", text: "aviruddhe dhruvaṃ daive kāle yuktasya karmaṇaḥ siddhiḥ puṃsavanādyasmāt pūrvaṃ vyakteḥ prayojayet" },
      { type: "verse", number: "42", sanskrit: "जाताश्चैवं रूपवन्तो मासत्त्वाश्चिरायुषः ऋणान्मोचयितारः स्युः सुपुत्राः पुत्रिणां मताः", text: "jātāścaivaṃ rūpavanto māsattvāścirāyuṣaḥ ṛṇānmocayitāraḥ syuḥ suputrāḥ putriṇāṃ matāḥ" },
      { type: "verse", number: "43", sanskrit: "देवताचारशौचादिरता सूते महागुणम् धावत्येवं चाचरितं प्राग्जन्माभ्यासयोगतः", text: "devatācāraśaucādiratā sūte mahāguṇam dhāvatyevaṃ cācaritaṃ prāgjanmābhyāsayogataḥ" },
      { type: "verse", number: "44", sanskrit: "योषितो ऽपि स्रवत्येव शुक्रं पुंसः समागमे गर्भस्य तन्न किञ्चित्तु करोतीति न चिन्त्यते", text: "yoṣito 'pi sravatyeva śukraṃ puṃsaḥ samāgame garbhasya tanna kiñcittu karotīti na cintyate" },
    ],
  },
  {
    sthana: "Шарирастхана",
    number: 2,
    lang: "sa",
    content: [
      { type: "heading", heading: "Гарбха вьяпат — патология плода" },
      { type: "text", text: "Глава 2 Шарирастханы Астанга-санграхи — «Гарбха вьяпат» — посвящена анатомическим и эмбриологическим аспектам: патология плода." },
      { type: "verse", number: "1", sanskrit: "अथातो गर्भावक्रान्तिं शारीरं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto garbhāvakrāntiṃ śārīraṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "गते पुराणे रजसि नवे ऽवस्थिते शुद्धे गर्भस्याशये मार्गे च बीजात्मना शुक्रमविकृतमविकृतेन वायुना प्रेरितमन्यैश्च महाभूतैरनुगतमार्तवेनाभिमूर्च्छितमन्वक्षमेव रागादिक्लेशवशानुवर्तिना स्वकर्मचोदितेन मनोजवेन जीवेनाभिसंसृष्टं गर्भाशयमुपयाति", text: "gate purāṇe rajasi nave 'vasthite śuddhe garbhasyāśaye mārge ca bījātmanā śukramavikṛtamavikṛtena vāyunā preritamanyaiśca mahābhūtairanugatamārtavenābhimūrcchitamanvakṣameva rāgādikleśavaśānuvartinā svakarmacoditena manojavena jīvenābhisaṃsṛṣṭaṃ garbhāśayamupayāti" },
      { type: "verse", number: "3", sanskrit: "कार्याणा च कारणानुविधायित्वात्तत्सभागतां प्रतिपद्यते तत एव च शुक्रस्य बाहुल्यात् पुमानार्तवस्य बाहुल्यात् स्त्री तयोः साम्येन नपुंसकम् शुक्रार्तवे ऽनिलेन खण्डशो भिन्ने यथाविभागमपत्यानामुत्पत्तिः विकृते वियोन्याकृतीनां च", text: "kāryāṇā ca kāraṇānuvidhāyitvāttatsabhāgatāṃ pratipadyate tata eva ca śukrasya bāhulyāt pumānārtavasya bāhulyāt strī tayoḥ sāmyena napuṃsakam śukrārtave 'nilena khaṇḍaśo bhinne yathāvibhāgamapatyānāmutpattiḥ vikṛte viyonyākṛtīnāṃ ca" },
      { type: "verse", number: "4", sanskrit: "अथ नार्याः सद्योगृहीतगर्भायाश्च लिङ्गं योन्या बीजग्रहणं तृप्तिर्गरिमा स्फुरणं शुक्रार्तवयोरनुबन्धश्च तथा प्रहर्षो हृल्लासस्तन्द्राङ्गसादः प्रसेको हृदयव्यथा ग्लानिः पिपासा च क्रमेण तु व्यक्तगर्भायाः कुक्षिमात्रगौरवं क्षामनेत्रस्वरता योनिरोमसंलुलनं निद्रा जृम्भणं मूर्च्छा छर्दिररुचिः पादशोफो ऽम्ले ऽभिलाषस्तेषु तेषु चोच्चावचेषु भावेष्विति", text: "atha nāryāḥ sadyogṛhītagarbhāyāśca liṅgaṃ yonyā bījagrahaṇaṃ tṛptirgarimā sphuraṇaṃ śukrārtavayoranubandhaśca tathā praharṣo hṛllāsastandrāṅgasādaḥ praseko hṛdayavyathā glāniḥ pipāsā ca krameṇa tu vyaktagarbhāyāḥ kukṣimātragauravaṃ kṣāmanetrasvaratā yoniromasaṃlulanaṃ nidrā jṛmbhaṇaṃ mūrcchā chardiraruciḥ pādaśopho 'mle 'bhilāṣasteṣu teṣu coccāvaceṣu bhāveṣviti" },
      { type: "verse", number: "5", sanskrit: "तस्याश्च रजोवाहिनां स्रोतसां वर्त्मान्युपरुध्यन्ते गर्भेण तस्मात्ततः परमार्तवं न दृश्यते ततस्तदधः प्रतिहतमपरमपरं चोपचीयमानमपरेत्याहुः जरायुरित्यन्ये स्थिते रक्ते रोमराजिः प्रादुर्भवति", text: "tasyāśca rajovāhināṃ srotasāṃ vartmānyuparudhyante garbheṇa tasmāttataḥ paramārtavaṃ na dṛśyate tatastadadhaḥ pratihatamaparamaparaṃ copacīyamānamaparetyāhuḥ jarāyurityanye sthite rakte romarājiḥ prādurbhavati" },
      { type: "verse", number: "6", sanskrit: "जरायुशेषं चोर्ध्वमसृक् प्रतिपद्यते तस्मात् पीनकपोलपयोधरता कृष्णौष्ठचूचुकत्वं च स्तनाश्रयमेव च कफोपरञ्जितं स्तन्यतामुपगतं प्रसूतायाः पूनराहाररसेनाप्यायते", text: "jarāyuśeṣaṃ cordhvamasṛk pratipadyate tasmāt pīnakapolapayodharatā kṛṣṇauṣṭhacūcukatvaṃ ca stanāśrayameva ca kaphoparañjitaṃ stanyatāmupagataṃ prasūtāyāḥ pūnarāhārarasenāpyāyate" },
      { type: "verse", number: "7", sanskrit: "तत्र प्रथमे मासे कललं जायते द्वितीये घनः पेश्यर्बुदं वा तेभ्यः क्रमात् पुंस्त्रीनपुंसकानि तृतीये पञ्चधा प्ररोहति तद्यथा सक्थिनी बाहू शिरश्च सक्थ्यादिप्ररोहैककालमेव च सर्वमङ्गावयवेन्द्रियाणि युगपत्सम्भवन्त्यन्यत्र जन्मोत्तरकालजेभ्यो दन्तादिभ्यः क्रमेण तु स्फुटीभवन्ति एषा प्रकृतिः विकृतिरतो ऽन्यथा", text: "tatra prathame māse kalalaṃ jāyate dvitīye ghanaḥ peśyarbudaṃ vā tebhyaḥ kramāt puṃstrīnapuṃsakāni tṛtīye pañcadhā prarohati tadyathā sakthinī bāhū śiraśca sakthyādiprarohaikakālameva ca sarvamaṅgāvayavendriyāṇi yugapatsambhavantyanyatra janmottarakālajebhyo dantādibhyaḥ krameṇa tu sphuṭībhavanti eṣā prakṛtiḥ vikṛtirato 'nyathā" },
      { type: "verse", number: "8", sanskrit: "यथास्वं च गर्भस्य पुंस्त्रीनपुंसकान्यतमलिङ्गानुरूपा भावा मनसि शरीरे च सन्तिष्ठन्ते वैशेषिकलिङ्गसङ्करे तु यतो भूयस्त्वं ततो ऽन्तरा भावाः", text: "yathāsvaṃ ca garbhasya puṃstrīnapuṃsakānyatamaliṅgānurūpā bhāvā manasi śarīre ca santiṣṭhante vaiśeṣikaliṅgasaṅkare tu yato bhūyastvaṃ tato 'ntarā bhāvāḥ" },
      { type: "verse", number: "9", sanskrit: "तद्यथा क्लैब्यं भीरुत्वमवैशारद्यं मोहो ऽनवस्थानमधोगुरुत्वमसंहननं शैथिल्यं मार्दवं गर्भाशयबीजभागस्तथायुक्ताश्चापरे स्त्रीकरा भावाः ततो विपरीताः पुंस्कराः सङ्कीर्णा नपुंसकराः", text: "tadyathā klaibyaṃ bhīrutvamavaiśāradyaṃ moho 'navasthānamadhogurutvamasaṃhananaṃ śaithilyaṃ mārdavaṃ garbhāśayabījabhāgastathāyuktāścāpare strīkarā bhāvāḥ tato viparītāḥ puṃskarāḥ saṅkīrṇā napuṃsakarāḥ" },
      { type: "verse", number: "10", sanskrit: "तदा चास्य वेदना प्रव्यक्ता भवति ततश्च तत्प्रभृति स्पन्दते ऽभिलाषं पञ्चेन्द्रियार्थेषु करोति", text: "tadā cāsya vedanā pravyaktā bhavati tataśca tatprabhṛti spandate 'bhilāṣaṃ pañcendriyārtheṣu karoti" },
      { type: "verse", number: "11", sanskrit: "मातृजं ह्यस्य हृदयं तद्रसहारिणीभिर्धर्मनीभिर्मातृहृदयेनाभिसम्बद्धं भवति तस्मात्तयोस्ताभिः श्रद्धा सम्पद्यते तथा च द्विहृदयां नारीं दौहृदिनीत्याचक्षते अन्ये तु पक्षत्रयात् प्रभृत्यापञ्चमान्मासाद्दौहृदकालमाहुः", text: "mātṛjaṃ hyasya hṛdayaṃ tadrasahāriṇībhirdharmanībhirmātṛhṛdayenābhisambaddhaṃ bhavati tasmāttayostābhiḥ śraddhā sampadyate tathā ca dvihṛdayāṃ nārīṃ dauhṛdinītyācakṣate anye tu pakṣatrayāt prabhṛtyāpañcamānmāsāddauhṛdakālamāhuḥ" },
      { type: "verse", number: "12", sanskrit: "प्रार्थनायां च तीव्रायां काममहितमप्यस्यै हितोपसंहितं दद्यात् दौहृदविमाननाद्धि वायुः प्रकुपितो ऽन्तश्शरीरमनुचरन् गर्भस्य विनाशं वैरूप्यं वा कुर्यात् लब्धदौहृदा तु वीर्यवन्तं चिरायुषं च पुत्रं प्रसूते", text: "prārthanāyāṃ ca tīvrāyāṃ kāmamahitamapyasyai hitopasaṃhitaṃ dadyāt dauhṛdavimānanāddhi vāyuḥ prakupito 'ntaśśarīramanucaran garbhasya vināśaṃ vairūpyaṃ vā kuryāt labdhadauhṛdā tu vīryavantaṃ cirāyuṣaṃ ca putraṃ prasūte" },
      { type: "verse", number: "13", sanskrit: "चतुर्थे ऽङ्गप्रत्यङ्गविभागः प्रव्यक्तो गर्भश्च स्थिरो भवति पञ्चमे मनः प्रतिबुद्धतरं भवति मांसशोणितोपचयश्च षष्ठे केशरोमनखास्थिस्नाय्वादीन्यभिव्यक्तानि बलवर्णोपचयश्च सप्तमे सर्वाङ्गसम्पूर्णता", text: "caturthe 'ṅgapratyaṅgavibhāgaḥ pravyakto garbhaśca sthiro bhavati pañcame manaḥ pratibuddhataraṃ bhavati māṃsaśoṇitopacayaśca ṣaṣṭhe keśaromanakhāsthisnāyvādīnyabhivyaktāni balavarṇopacayaśca saptame sarvāṅgasampūrṇatā" },
      { type: "verse", number: "14", sanskrit: "अष्टमे गर्भश्च मातृतो गर्भतश्च माता रसहारिणीभिर्वाहिनीभिर्मुहर्मुहुरोजः परस्परमाददाते तस्मात्तदा गर्भिणी मुहुर्मुदिता भवति मुहुर्ग्लाना तथा गर्भः एवं गर्भस्य जन्म व्यापत्तिमत्तदा भवति ओजसो ऽनवस्थितत्वात् तथा ह्यस्य निष्क्रमणोन्मुखस्य परिवर्तनादीन्यनुभवत एवौजसा वियोगः यद्यपि च किञ्चित्कालमस्योच्छ्वसनं स्यात्तच्छिन्नस्येवाङ्गस्यौजस्संस्कारानुवृत्तिकृतम् जनन्यास्तु स्थिरौजस्कतयैकदेशेन रसे सङ्क्रान्ते ग्लानिरेवेति", text: "aṣṭame garbhaśca mātṛto garbhataśca mātā rasahāriṇībhirvāhinībhirmuharmuhurojaḥ parasparamādadāte tasmāttadā garbhiṇī muhurmuditā bhavati muhurglānā tathā garbhaḥ evaṃ garbhasya janma vyāpattimattadā bhavati ojaso 'navasthitatvāt tathā hyasya niṣkramaṇonmukhasya parivartanādīnyanubhavata evaujasā viyogaḥ yadyapi ca kiñcitkālamasyocchvasanaṃ syāttacchinnasyevāṅgasyaujassaṃskārānuvṛttikṛtam jananyāstu sthiraujaskatayaikadeśena rase saṅkrānte glānireveti" },
      { type: "verse", number: "15", sanskrit: "अन्ये पुनराहुः नैरृतभागत्वात्तत्र गर्भस्य मरणम् तस्मात् प्रसवप्रतिषेधार्थं स्त्री स्नाता शुचिर्ब्रह्मचारिणी देवताराधनपरा स्यात् मांसौदनबालिं चात्र निर्वपेत् तस्मिन्नेकदिवसातिक्रान्ते ऽपि प्रसवकालमाहुरासंवत्सरात् अतः परं विकारी भवति", text: "anye punarāhuḥ nairṛtabhāgatvāttatra garbhasya maraṇam tasmāt prasavapratiṣedhārthaṃ strī snātā śucirbrahmacāriṇī devatārādhanaparā syāt māṃsaudanabāliṃ cātra nirvapet tasminnekadivasātikrānte 'pi prasavakālamāhurāsaṃvatsarāt ataḥ paraṃ vikārī bhavati" },
      { type: "verse", number: "16", sanskrit: "गर्भस्तु मातुः पृष्ठाभिमुखो ललाटे कृताञ्जलिः सङ्कुचिताङ्गो गर्भष्ठे दक्षिणपार्श्वमाश्रित्यावतिष्ठते पुमान् वामं स्त्री मध्यं नपुंसकम् तत्र स्थितश्च गर्भो मातरि स्वपन्त्यां प्रबुद्धायां प्रबुध्यते परतन्त्रवृत्तेश्च गर्भस्य निषेकात् प्रभृति गर्भाशयोपस्नेहोपस्वेदौ वर्तनम्", text: "garbhastu mātuḥ pṛṣṭhābhimukho lalāṭe kṛtāñjaliḥ saṅkucitāṅgo garbhaṣṭhe dakṣiṇapārśvamāśrityāvatiṣṭhate pumān vāmaṃ strī madhyaṃ napuṃsakam tatra sthitaśca garbho mātari svapantyāṃ prabuddhāyāṃ prabudhyate paratantravṛtteśca garbhasya niṣekāt prabhṛti garbhāśayopasnehopasvedau vartanam" },
      { type: "verse", number: "17", sanskrit: "ततो व्यक्तीभवदङ्गप्रत्यङ्गस्यास्य नाभ्यां प्रतिबद्धानाडी नाड्यामपरा तस्यां मातृहृदयम् ततो मातृहृदयादाहाररसो धमनीभिः स्यन्दमानो ऽपरामुपैति ततः क्रमान्नाभिम् ततश्च स पुनर्गर्भस्य पक्वाशये स्वकायाग्निना पच्यमानः प्रसादबाहुल्याद्धात्वादिपुष्टिकरः सम्पद्यते तथारोमकूपैरुपस्नेहो रस एव च पयोभूतः", text: "tato vyaktībhavadaṅgapratyaṅgasyāsya nābhyāṃ pratibaddhānāḍī nāḍyāmaparā tasyāṃ mātṛhṛdayam tato mātṛhṛdayādāhāraraso dhamanībhiḥ syandamāno 'parāmupaiti tataḥ kramānnābhim tataśca sa punargarbhasya pakvāśaye svakāyāgninā pacyamānaḥ prasādabāhulyāddhātvādipuṣṭikaraḥ sampadyate tathāromakūpairupasneho rasa eva ca payobhūtaḥ" },
      { type: "verse", number: "18", sanskrit: "अजातस्य साक्षादन्नपानाननुप्रवेशादमलत्वाच्च रसस्य गर्भस्य स्थूलमलासम्भवः एवं जठरस्थो गर्भो जन्मकाले तु प्रसूतिमारुतयोगात् परिवृत्यावाक्शिरा निष्क्रामत्यनु चापरा च्युता मातृहृदयात् एषा प्रकृतिः विकृतिरतो ऽन्यथा", text: "ajātasya sākṣādannapānānanupraveśādamalatvācca rasasya garbhasya sthūlamalāsambhavaḥ evaṃ jaṭharastho garbho janmakāle tu prasūtimārutayogāt parivṛtyāvākśirā niṣkrāmatyanu cāparā cyutā mātṛhṛdayāt eṣā prakṛtiḥ vikṛtirato 'nyathā" },
      { type: "verse", number: "19", sanskrit: "तत्र या दक्षिणं पादं पूर्वमभिसरति दक्षिणश्च बाहुर्बलवांस्तेन चेष्टते तत्स्तने च प्राक् पयो दृश्यते अभ्युन्नतदक्षिणकुक्षिः परिमण्डलगर्भा पुन्नामदर्शनस्पर्शनप्रश्नदौहृदाभिरता पुन्नामधेयांश्च स्वप्नान् पश्यति प्रसन्नमुखवर्णा तीक्ष्णक्षुदूर्ध्वरोमराजिः पुरुषानभिलाषिणी च सा पुत्रं प्रसूते तद्विपर्यये कन्यां सङ्करे च नपुंसकम् प्रश्नकाले नारी यल्लिङ्गमङ्गं बाह्यद्रव्यं वा परामृशति तल्लिङ्गमस्या गर्भमादिशेत्", text: "tatra yā dakṣiṇaṃ pādaṃ pūrvamabhisarati dakṣiṇaśca bāhurbalavāṃstena ceṣṭate tatstane ca prāk payo dṛśyate abhyunnatadakṣiṇakukṣiḥ parimaṇḍalagarbhā punnāmadarśanasparśanapraśnadauhṛdābhiratā punnāmadheyāṃśca svapnān paśyati prasannamukhavarṇā tīkṣṇakṣudūrdhvaromarājiḥ puruṣānabhilāṣiṇī ca sā putraṃ prasūte tadviparyaye kanyāṃ saṅkare ca napuṃsakam praśnakāle nārī yalliṅgamaṅgaṃ bāhyadravyaṃ vā parāmṛśati talliṅgamasyā garbhamādiśet" },
      { type: "verse", number: "20", sanskrit: "यदा तून्मार्गगो वातो गर्भस्य रसवाहीनि स्रोतांसि शोषयति तदा वातरोगी हीनाङ्गो वा जायते बहूनि वा वर्षाण्युदरे तिष्ठति", text: "yadā tūnmārgago vāto garbhasya rasavāhīni srotāṃsi śoṣayati tadā vātarogī hīnāṅgo vā jāyate bahūni vā varṣāṇyudare tiṣṭhati" },
      { type: "verse", number: "21", sanskrit: "यदा स्त्रीपुंसयोः सममेवार्थो निष्पद्यते बीजं वा तयोः समांशं संमुखं च यदा च बीजं भागे दुष्यति तदा द्विप्रकृतिर्द्विरेता नपुंसकं भवति", text: "yadā strīpuṃsayoḥ samamevārtho niṣpadyate bījaṃ vā tayoḥ samāṃśaṃ saṃmukhaṃ ca yadā ca bījaṃ bhāge duṣyati tadā dviprakṛtirdviretā napuṃsakaṃ bhavati" },
      { type: "verse", number: "22", sanskrit: "यदा स्त्री प्रथमं कृतार्था भवति ततः पुरुषेण पश्चाच्छुक्रमुत्सृष्टं हर्षानवस्थितचेतसः स्त्रिया वातो विगुणीकरोति पुंस्त्ववाहीनि स्रोतांसि चोपहन्ति तदा वातेन्द्रियं भवति तन्मैथुने वातमेवोत्सृजति", text: "yadā strī prathamaṃ kṛtārthā bhavati tataḥ puruṣeṇa paścācchukramutsṛṣṭaṃ harṣānavasthitacetasaḥ striyā vāto viguṇīkaroti puṃstvavāhīni srotāṃsi copahanti tadā vātendriyaṃ bhavati tanmaithune vātamevotsṛjati" },
      { type: "verse", number: "23", sanskrit: "यदा तु कार्त्स्न्येन नोपहन्ति अनुपघ्नन्नेव वा स्रोतोमुखं पिधत्ते तदा संस्कारवाह्यं भवति तत्र संस्कारो वाजीकरा बस्तयो ऽभ्यवहारश्चेतोहर्षणानि च तानि हि शुक्रे बलमादधानानि स्रोतांस्यस्याप्याययन्तीति", text: "yadā tu kārtsnyena nopahanti anupaghnanneva vā srotomukhaṃ pidhatte tadā saṃskāravāhyaṃ bhavati tatra saṃskāro vājīkarā bastayo 'bhyavahāraścetoharṣaṇāni ca tāni hi śukre balamādadhānāni srotāṃsyasyāpyāyayantīti" },
      { type: "verse", number: "24", sanskrit: "यदाल्पबीजो ऽल्पबलः पुमानुद्वेगः स्त्रीद्वेषयुक्तो ऽन्यकामो वा नार्या व्यवायप्रतिघातं करोति तद्विधा वा नारी पुंसः तदा आसेक्यं नाम भवति तच्शुक्रास्वादाद्ध्वजोच्छ्रायं लभते", text: "yadālpabījo 'lpabalaḥ pumānudvegaḥ strīdveṣayukto 'nyakāmo vā nāryā vyavāyapratighātaṃ karoti tadvidhā vā nārī puṃsaḥ tadā āsekyaṃ nāma bhavati tacśukrāsvādāddhvajocchrāyaṃ labhate" },
      { type: "verse", number: "25", sanskrit: "यदा पुनरुभावपि भवतः स्त्रीपुंसौ तद्विधौ तदा वक्रध्वजो भवति तस्य नैव ध्वजः स्तभ्यते", text: "yadā punarubhāvapi bhavataḥ strīpuṃsau tadvidhau tadā vakradhvajo bhavati tasya naiva dhvajaḥ stabhyate" },
      { type: "verse", number: "26", sanskrit: "यदा पूतियोन्याः स्त्रिया गर्भो भवति सौगन्धिकाख्यः स योनिध्वजगन्धेन बलं लभते", text: "yadā pūtiyonyāḥ striyā garbho bhavati saugandhikākhyaḥ sa yonidhvajagandhena balaṃ labhate" },
      { type: "verse", number: "27", sanskrit: "यदा त्वीर्ष्याभिभूतौ मन्दहर्षौ संसृज्येते तदेर्ष्यारतिसंज्ञम् तस्य परं मिथुनीभूतं दृष्ट्वा मैथुनप्रवृत्तिर्भवति", text: "yadā tvīrṣyābhibhūtau mandaharṣau saṃsṛjyete taderṣyāratisaṃjñam tasya paraṃ mithunībhūtaṃ dṛṣṭvā maithunapravṛttirbhavati" },
      { type: "verse", number: "28", sanskrit: "यदा पुरुषस्य गर्भस्य वाय्वग्निदोषाद् वृषणनाशस्तदा वातषण्डकाख्यं भवति एताः कर्मवैचित्र्यादष्टौ षण्डयोनयो ऽसङ्कीर्णाः कथिताः", text: "yadā puruṣasya garbhasya vāyvagnidoṣād vṛṣaṇanāśastadā vātaṣaṇḍakākhyaṃ bhavati etāḥ karmavaicitryādaṣṭau ṣaṇḍayonayo 'saṅkīrṇāḥ kathitāḥ" },
      { type: "verse", number: "29", sanskrit: "यदा तु स्त्रियाः शोणितगर्भाशयौ दोषाः किञ्चित् प्रदूषयन्ति तदा यो गर्भो भवति तस्य गर्भस्य यस्य यस्य मातृजस्यावयवस्य बीजे बीजांशे वा दोषः प्रकोपमापद्यते तं तमवयवं विकृतिराविशति", text: "yadā tu striyāḥ śoṇitagarbhāśayau doṣāḥ kiñcit pradūṣayanti tadā yo garbho bhavati tasya garbhasya yasya yasya mātṛjasyāvayavasya bīje bījāṃśe vā doṣaḥ prakopamāpadyate taṃ tamavayavaṃ vikṛtirāviśati" },
      { type: "verse", number: "30", sanskrit: "यदा ह्यस्याः शोणिताख्ये बीजे गर्भाशयस्थे निर्वर्तकं बीजं प्रदुष्यति तदा वन्ध्यां जनयति यदा तस्यावयवस्तदा पूतिप्रजाम् तस्या जातं जातं म्रियते", text: "yadā hyasyāḥ śoṇitākhye bīje garbhāśayasthe nirvartakaṃ bījaṃ praduṣyati tadā vandhyāṃ janayati yadā tasyāvayavastadā pūtiprajām tasyā jātaṃ jātaṃ mriyate" },
      { type: "verse", number: "31", sanskrit: "यदा पुनः सो ऽवयवः स्त्रीकराणां च शरीरसंश्रयाणामधोगुरुत्वादीनां निर्वर्तका ये बीजांशास्तेषामेकदेशः तदा स्त्र्याकृतिप्रायामस्त्रियं वार्तां नाम जनयति तां स्त्रीव्यापदमाचक्षते", text: "yadā punaḥ so 'vayavaḥ strīkarāṇāṃ ca śarīrasaṃśrayāṇāmadhogurutvādīnāṃ nirvartakā ye bījāṃśāsteṣāmekadeśaḥ tadā stryākṛtiprāyāmastriyaṃ vārtāṃ nāma janayati tāṃ strīvyāpadamācakṣate" },
      { type: "verse", number: "32", sanskrit: "एवमेव पुंसो यदा शुक्राख्ये बीजे बीजं प्रदुष्यतीत्यादि योजयेद्वन्ध्यं पूतिप्रजं तथा पुरुषाकृतिप्रायमपुरुषं तृणमुखिनं नाम जनयतीत्येतेन मातृजानां पितृजानां चावयवानां विकृतिर्व्याख्याता", text: "evameva puṃso yadā śukrākhye bīje bījaṃ praduṣyatītyādi yojayedvandhyaṃ pūtiprajaṃ tathā puruṣākṛtiprāyamapuruṣaṃ tṛṇamukhinaṃ nāma janayatītyetena mātṛjānāṃ pitṛjānāṃ cāvayavānāṃ vikṛtirvyākhyātā" },
      { type: "verse", number: "33", sanskrit: "अनेन सात्म्यजानां रसजानां सत्त्वजानां चावयवानां विकृतिर्व्याख्याता भवति यस्य यस्याङ्गावयवस्य बीजे बीजांशे वा उपतप्तिर्भवति तस्य तस्याङ्गावयवस्य विकृतिरुपजायते नोपजायते ऽनुतापात्", text: "anena sātmyajānāṃ rasajānāṃ sattvajānāṃ cāvayavānāṃ vikṛtirvyākhyātā bhavati yasya yasyāṅgāvayavasya bīje bījāṃśe vā upataptirbhavati tasya tasyāṅgāvayavasya vikṛtirupajāyate nopajāyate 'nutāpāt" },
      { type: "verse", number: "34", sanskrit: "यदा च लब्धगर्भा ऽन्वक्षमेव वातलान्यासेवते तदास्या वायुः प्रकुपितः शरीरमनुसर्पन् गर्भाशये ऽवतिष्ठमानो गर्भस्य जडबधिरमूकमिन्मिणगद्गदखञ्जकुब्जवामनहीनाङ्गाधिकाङ्गत्वान्यन्यं वा वातविकारं करोति तथा वायुवत् पित्तमपि खलतिपलितश्मश्रुहीनतात्वङ्नखकेशपैङ्गल्यादीनि श्लेष्मा तु कुष्ठकिलाससदन्तत्त्वादीनि त्रिवर्गो मिश्रान्विकारान्", text: "yadā ca labdhagarbhā 'nvakṣameva vātalānyāsevate tadāsyā vāyuḥ prakupitaḥ śarīramanusarpan garbhāśaye 'vatiṣṭhamāno garbhasya jaḍabadhiramūkaminmiṇagadgadakhañjakubjavāmanahīnāṅgādhikāṅgatvānyanyaṃ vā vātavikāraṃ karoti tathā vāyuvat pittamapi khalatipalitaśmaśruhīnatātvaṅnakhakeśapaiṅgalyādīni śleṣmā tu kuṣṭhakilāsasadantattvādīni trivargo miśrānvikārān" },
      { type: "verse", number: "35", sanskrit: "अपि च दृष्टिभागमप्रतिपन्नं तेजो जात्यन्धत्वम् तदेव वातानुगतं विकृतरूक्षारुणाक्षम् पित्तानुगतं पिङ्गाक्षम् श्लेष्मानुगतं शुक्लाक्षम् रक्तानुगतं रक्ताक्षमिति", text: "api ca dṛṣṭibhāgamapratipannaṃ tejo jātyandhatvam tadeva vātānugataṃ vikṛtarūkṣāruṇākṣam pittānugataṃ piṅgākṣam śleṣmānugataṃ śuklākṣam raktānugataṃ raktākṣamiti" },
      { type: "verse", number: "36", sanskrit: "गर्भसमानयोगक्षेमा हि गर्भिणी भवति तस्माद्विशेषतस्तां प्रियहिताभ्यां गर्भोपधातकरेभ्यो रक्षेत् यथा यथा च गर्भो वृद्धिमाप्नोति तथा तथा भाराहारानादानादाहाररसापहाराच्च स्त्रिया बलक्षयः तत्रेमे गर्भोपघातकराः तद्यथा व्यवायव्यायामकर्शनाभिघातातिमात्रसङ्क्षोभियानयानरात्रिजागरणदिवास्वप्नवेगविधारणाजीर्णातपाग्निकोधशोकभयोत्त्रासोपवासोत्कटकविषमकठिनासनश्वभ्रकूपप्रपाताप्रियावलोकनश्रवणादयः समासतः सर्वमतिगुरूष्णतीक्ष्णरूक्षमन्नपानं दारुणाश्च चेष्टाः", text: "garbhasamānayogakṣemā hi garbhiṇī bhavati tasmādviśeṣatastāṃ priyahitābhyāṃ garbhopadhātakarebhyo rakṣet yathā yathā ca garbho vṛddhimāpnoti tathā tathā bhārāhārānādānādāhārarasāpahārācca striyā balakṣayaḥ tatreme garbhopaghātakarāḥ tadyathā vyavāyavyāyāmakarśanābhighātātimātrasaṅkṣobhiyānayānarātrijāgaraṇadivāsvapnavegavidhāraṇājīrṇātapāgnikodhaśokabhayottrāsopavāsotkaṭakaviṣamakaṭhināsanaśvabhrakūpaprapātāpriyāvalokanaśravaṇādayaḥ samāsataḥ sarvamatigurūṣṇatīkṣṇarūkṣamannapānaṃ dāruṇāśca ceṣṭāḥ" },
      { type: "verse", number: "37", sanskrit: "तथा देवतारक्षो ऽनुपचयपरिरक्षणार्थं न रक्तानि वासासि धारयेन्न यानमधिरोहेन्न मद्यमांसमश्नीयात् यच्चान्यदपि वृद्धस्त्रियो ब्रूयुः प्रततोत्तानशायिन्याः पुनर्गर्भस्य नाभ्याश्रया नाडी कण्ठमनुवेष्ट्य व्यापत्तिं करोति विवृतशया नक्तचारिणी चोन्मत्तं जनयति कलहशीलापस्मारिणम् व्यवायशीला दुर्वपुषमह्रीकं स्त्रैणं वा शोकनित्या भीरुमपचितमल्पायुषं वा अभिध्यायिनी परोपतापिनमीर्ष्यालुं स्त्रैणं वा स्तेना त्वायासबहुलमभिद्रोहिणमकर्मशीलं वा अमर्षणा चण्डमौपधिकं वा स्वप्नशीला निद्रालुमबुधमल्पाग्निं वा मद्यनित्या तृष्णालुमल्पस्मृतिमनवस्थितं वा गोधामांसनित्याश्मरिणं शनैर्मेहिनं वा बराहमांसनित्या रक्ताक्षं क्रथनमतिपरुषरोमाणं वा मत्स्यमांसनित्या चिरनिमेषं स्तब्धाक्षं वा मधुरनित्या प्रमेहिणं मूकमतिस्थूलं वा अम्लनित्या रक्तपित्तिनं त्वगक्षिरोगिणं वा लवणनित्या शीघ्रवलीपलितं खलतिकं वा तिक्तनित्या शोषिणमबलमपचितं वा कटुकनित्या दुर्बलमल्पशुक्रमनपत्यं वा कषायनित्या श्याममानाहिनमुदावर्तिनं वा यच्च यच्च यस्य व्याधेर्निदानं तत्तदासेवमानान्तर्वत्नी स्त्री तत्तद्विकारबहुलमपत्यं जनयति एतेन पितृजा अपि शुक्रदोषा व्याख्याताः", text: "tathā devatārakṣo 'nupacayaparirakṣaṇārthaṃ na raktāni vāsāsi dhārayenna yānamadhirohenna madyamāṃsamaśnīyāt yaccānyadapi vṛddhastriyo brūyuḥ pratatottānaśāyinyāḥ punargarbhasya nābhyāśrayā nāḍī kaṇṭhamanuveṣṭya vyāpattiṃ karoti vivṛtaśayā naktacāriṇī conmattaṃ janayati kalahaśīlāpasmāriṇam vyavāyaśīlā durvapuṣamahrīkaṃ straiṇaṃ vā śokanityā bhīrumapacitamalpāyuṣaṃ vā abhidhyāyinī paropatāpinamīrṣyāluṃ straiṇaṃ vā stenā tvāyāsabahulamabhidrohiṇamakarmaśīlaṃ vā amarṣaṇā caṇḍamaupadhikaṃ vā svapnaśīlā nidrālumabudhamalpāgniṃ vā madyanityā tṛṣṇālumalpasmṛtimanavasthitaṃ vā godhāmāṃsanityāśmariṇaṃ śanairmehinaṃ vā barāhamāṃsanityā raktākṣaṃ krathanamatiparuṣaromāṇaṃ vā matsyamāṃsanityā ciranimeṣaṃ stabdhākṣaṃ vā madhuranityā pramehiṇaṃ mūkamatisthūlaṃ vā amlanityā raktapittinaṃ tvagakṣirogiṇaṃ vā lavaṇanityā śīghravalīpalitaṃ khalatikaṃ vā tiktanityā śoṣiṇamabalamapacitaṃ vā kaṭukanityā durbalamalpaśukramanapatyaṃ vā kaṣāyanityā śyāmamānāhinamudāvartinaṃ vā yacca yacca yasya vyādhernidānaṃ tattadāsevamānāntarvatnī strī tattadvikārabahulamapatyaṃ janayati etena pitṛjā api śukradoṣā vyākhyātāḥ" },
      { type: "verse", number: "38", sanskrit: "तस्मात् प्रजासम्पदमिच्छन्तौ साध्वात्मान्नसुपाचरेताम् विशेषेण नारी व्याधींश्चास्या मृदुमधुरशिशिरसुखैरौषधाहारविहारैरुपाचरेत् न चास्या वमनादीनि प्रयोजयेत् न रक्तावसेचनम् केवलं त्वष्टममासमुपादायास्थापामनुवासनं वा वमनादिसाध्येषु पुनर्विकारेषु मृदुभिस्तदर्थकारिभिर्वोपक्रमेत् पूर्णमिव तैलपात्रमसंक्षोभयद्गर्भिणीमुपाचरेदिति भवन्ति चात्र", text: "tasmāt prajāsampadamicchantau sādhvātmānnasupācaretām viśeṣeṇa nārī vyādhīṃścāsyā mṛdumadhuraśiśirasukhairauṣadhāhāravihārairupācaret na cāsyā vamanādīni prayojayet na raktāvasecanam kevalaṃ tvaṣṭamamāsamupādāyāsthāpāmanuvāsanaṃ vā vamanādisādhyeṣu punarvikāreṣu mṛdubhistadarthakāribhirvopakramet pūrṇamiva tailapātramasaṃkṣobhayadgarbhiṇīmupācarediti bhavanti cātra" },
      { type: "verse", number: "39", sanskrit: "इत्यनात्ययिके व्याधौ विधिरात्यीयके पुनः तीक्ष्णैरपि क्रियायोगैः स्त्रियं यत्नेन पालयेत्", text: "ityanātyayike vyādhau vidhirātyīyake punaḥ tīkṣṇairapi kriyāyogaiḥ striyaṃ yatnena pālayet" },
      { type: "verse", number: "40", sanskrit: "स्त्री हि मूलमपत्यानां स्त्री हि रक्षति रक्षिता सर्वाश्रमाणां प्रथमं गृहस्थत्वमनिन्दितम्", text: "strī hi mūlamapatyānāṃ strī hi rakṣati rakṣitā sarvāśramāṇāṃ prathamaṃ gṛhasthatvamaninditam" },
      { type: "verse", number: "41", sanskrit: "जरायुणा मुखे छन्ने कण्ठे च कफवेष्टिते वायोर्मार्गनिरोधाच्च न गर्भस्थः प्ररोदिति", text: "jarāyuṇā mukhe channe kaṇṭhe ca kaphaveṣṭite vāyormārganirodhācca na garbhasthaḥ praroditi" },
    ],
  },
  {
    sthana: "Шарирастхана",
    number: 3,
    lang: "sa",
    content: [
      { type: "heading", heading: "Шарира санкхья — анатомия тела" },
      { type: "text", text: "Глава 3 Шарирастханы Астанга-санграхи — «Шарира санкхья» — посвящена анатомическим и эмбриологическим аспектам: анатомия тела." },
      { type: "verse", number: "1", sanskrit: "अथातो गर्भोपचरणीयमध्यायं व्याख्यास्यामः इति हस्माहुरात्रेयादयो महर्षयः", text: "athāto garbhopacaraṇīyamadhyāyaṃ vyākhyāsyāmaḥ iti hasmāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "प्रथमे मासि गर्भिणी क्षीरमनुपसंस्कृतं मात्रावच्छीतं काले काले पिवेत् तस्मिन्नपि चाद्यं द्वादशरात्रं क्षीरोद्भवं सर्पिश्शालिपर्णीपलाशाभ्यां शृतं कनकरजतक्वथितं शीतोदकानुपानं पिबेत् स्वादु शीतं द्रवप्रायं सात्म्यं च सायंप्रातराहारयेत् न चाभ्यङ्गोद्वर्तनानि सेवेत यथोक्तानि च दोषकराणि परिहरेदापञ्चमान्मासाद्विशेषेण", text: "prathame māsi garbhiṇī kṣīramanupasaṃskṛtaṃ mātrāvacchītaṃ kāle kāle pivet tasminnapi cādyaṃ dvādaśarātraṃ kṣīrodbhavaṃ sarpiśśāliparṇīpalāśābhyāṃ śṛtaṃ kanakarajatakvathitaṃ śītodakānupānaṃ pibet svādu śītaṃ dravaprāyaṃ sātmyaṃ ca sāyaṃprātarāhārayet na cābhyaṅgodvartanāni seveta yathoktāni ca doṣakarāṇi pariharedāpañcamānmāsādviśeṣeṇa" },
      { type: "verse", number: "3", sanskrit: "द्वितीये मधुरौषधसिद्धं पयः पिबेत् तृतीये तदेव सर्पिर्मधुभ्याम् चतुर्थे ऽक्षमात्रनवनीतयुक्तम् पञ्चमे क्षीरसर्पिः षष्ठे तदेव मधुरौषधसिद्धम् सप्तमे च तस्मिंस्तु गर्भस्य केशोत्पत्त्या मातुर्विदाहो भवतीति स्त्रियो भाषन्ते नेति भगवानात्रेयः गर्भोत्पीडनात्तु दोषा हृदयं प्राप्य विदहन्ति ततः कण्डूर्जायते कण्ड्वा किक्किसम्", text: "dvitīye madhurauṣadhasiddhaṃ payaḥ pibet tṛtīye tadeva sarpirmadhubhyām caturthe 'kṣamātranavanītayuktam pañcame kṣīrasarpiḥ ṣaṣṭhe tadeva madhurauṣadhasiddham saptame ca tasmiṃstu garbhasya keśotpattyā māturvidāho bhavatīti striyo bhāṣante neti bhagavānātreyaḥ garbhotpīḍanāttu doṣā hṛdayaṃ prāpya vidahanti tataḥ kaṇḍūrjāyate kaṇḍvā kikkisam" },
      { type: "verse", number: "4", sanskrit: "तत्र कोलोदकेन नवनीतस्य मधुरौषधसिद्धस्य पाणितलमात्रमस्यै दद्यात् चन्दनमृणालकल्कैश्च स्तनोदरं मृद्नीयात् शिरीषधातकीसर्षपमधुकचूर्णैर्वा कुटजार्जकबीजमुस्ताहरिद्राकल्कैर्वा निम्बकोलसुरसमञ्जिष्ठाकल्कैर्वा शशहरिणपृषतरुधिरयुक्तया वा त्रिफलया करवीरकरञ्जपत्रकल्कसिद्धेन च तैलेनाभ्यङ्गः परिषेकः पुनर्मालतीमधुकसिद्धेनाम्भसा कण्डूयनं वर्जयेत् त्वग्भेदवैरूप्यपरिहारार्थं स्नानोद्वर्तनं च शीलयेत् मधुरं चाहारमल्पमल्पस्नेहलवणमल्पोदकानुपानं भुञ्जीत", text: "tatra kolodakena navanītasya madhurauṣadhasiddhasya pāṇitalamātramasyai dadyāt candanamṛṇālakalkaiśca stanodaraṃ mṛdnīyāt śirīṣadhātakīsarṣapamadhukacūrṇairvā kuṭajārjakabījamustāharidrākalkairvā nimbakolasurasamañjiṣṭhākalkairvā śaśahariṇapṛṣatarudhirayuktayā vā triphalayā karavīrakarañjapatrakalkasiddhena ca tailenābhyaṅgaḥ pariṣekaḥ punarmālatīmadhukasiddhenāmbhasā kaṇḍūyanaṃ varjayet tvagbhedavairūpyaparihārārthaṃ snānodvartanaṃ ca śīlayet madhuraṃ cāhāramalpamalpasnehalavaṇamalpodakānupānaṃ bhuñjīta" },
      { type: "verse", number: "5", sanskrit: "अष्टमे क्षीरयवागूं सर्पिष्मतीं पिबेत् नेति खण्डकाप्यः गर्भस्य पैङ्गल्याबाधभयात् अस्तु पैङ्गल्याबाधस्तथाप्येवं कुर्वीत नीरुजं बलवर्णसत्वसंहननसम्पदुपेतं ज्ञातीनामग्रगण्यमपत्यं जनयतीति भगवानात्रेयः", text: "aṣṭame kṣīrayavāgūṃ sarpiṣmatīṃ pibet neti khaṇḍakāpyaḥ garbhasya paiṅgalyābādhabhayāt astu paiṅgalyābādhastathāpyevaṃ kurvīta nīrujaṃ balavarṇasatvasaṃhananasampadupetaṃ jñātīnāmagragaṇyamapatyaṃ janayatīti bhagavānātreyaḥ" },
      { type: "verse", number: "6", sanskrit: "बदरोदकेन पललपयोदधिमस्तुतैललवणफलघृतमधुयुक्तेनास्थापयेत् पुराणविड्विशुध्यर्थं मधुकादिमधुरौषधसिद्धेन च तैलेनानुवासयेदनुलोमनाय वायोः अनुलोमे हि मारुते सा सुखमनुपद्रवा प्रसूते", text: "badarodakena palalapayodadhimastutailalavaṇaphalaghṛtamadhuyuktenāsthāpayet purāṇaviḍviśudhyarthaṃ madhukādimadhurauṣadhasiddhena ca tailenānuvāsayedanulomanāya vāyoḥ anulome hi mārute sā sukhamanupadravā prasūte" },
      { type: "verse", number: "7", sanskrit: "गर्भिणीं तु न्युब्जामास्थापयेदनुवासयेद्वा तथास्या विवृतमार्गतया सम्यगौषधमनुप्रविशति", text: "garbhiṇīṃ tu nyubjāmāsthāpayedanuvāsayedvā tathāsyā vivṛtamārgatayā samyagauṣadhamanupraviśati" },
      { type: "verse", number: "8", sanskrit: "तत ऊर्ध्वं स्निग्धाभिर्यवागूभिर्जाङ्गलरसैश्चोपाचरेदाप्रसवकालादिति भगवान् धन्वन्तरिः", text: "tata ūrdhvaṃ snigdhābhiryavāgūbhirjāṅgalarasaiścopācaredāprasavakālāditi bhagavān dhanvantariḥ" },
      { type: "verse", number: "9", sanskrit: "नवमे तु तत एवानुवासनतैलात् पिचुं योनौप्रणयेद्गर्भमार्गाशययोः स्नेहनार्थमिति अनेन प्रथममासादाराभ्य क्रमेण गर्भिण्याः प्रसवकाले गर्भधारिणीकुक्षिकटीपार्श्वपृष्ठं मृदु भवति वायुश्चानुलोमः सम्पद्यते मूत्रपुरीषं च प्रकृतिभूतं जरायुश्च मार्गं प्रतिपद्यते पुत्रं चेष्टं कल्यमायुष्मन्तं सुखिनं सुखेन काले बलवती प्रसूते", text: "navame tu tata evānuvāsanatailāt picuṃ yonaupraṇayedgarbhamārgāśayayoḥ snehanārthamiti anena prathamamāsādārābhya krameṇa garbhiṇyāḥ prasavakāle garbhadhāriṇīkukṣikaṭīpārśvapṛṣṭhaṃ mṛdu bhavati vāyuścānulomaḥ sampadyate mūtrapurīṣaṃ ca prakṛtibhūtaṃ jarāyuśca mārgaṃ pratipadyate putraṃ ceṣṭaṃ kalyamāyuṣmantaṃ sukhinaṃ sukhena kāle balavatī prasūte" },
      { type: "verse", number: "10", sanskrit: "बिल्वकार्पासीपफ्फणापाटलीपिचुमन्दाग्निमन्थमासीवर्धमानकपत्रभङ्गक्वाथेन शीतेन सर्वगन्धोदकेन वा गर्भिण्याः प्रत्यहं स्नानमुपदिशेत्", text: "bilvakārpāsīpaphphaṇāpāṭalīpicumandāgnimanthamāsīvardhamānakapatrabhaṅgakvāthena śītena sarvagandhodakena vā garbhiṇyāḥ pratyahaṃ snānamupadiśet" },
      { type: "verse", number: "11", sanskrit: "प्राक् चैवास्या नवमान्मासादपहृतास्थिशर्कराकपाले प्रशस्ते देशे वास्तुविद्याप्रशस्तं सर्वर्तुसुखमुपहृतसर्वोपकरणं सन्निहितज्वलनं प्राग्द्वारमुदग्द्वारं वा सूतिकागारं कारयेत्", text: "prāk caivāsyā navamānmāsādapahṛtāsthiśarkarākapāle praśaste deśe vāstuvidyāpraśastaṃ sarvartusukhamupahṛtasarvopakaraṇaṃ sannihitajvalanaṃ prāgdvāramudagdvāraṃ vā sūtikāgāraṃ kārayet" },
      { type: "verse", number: "12", sanskrit: "तत्रानुकूलेषु नक्षत्रादिषु पुण्याहशब्देन गोब्राह्मणवृद्धान् नत्वा आवर्तमाना प्रदक्षिणं प्रविश्य बहुशः प्रसूताभिरनुरक्ताभिरविषादाभिः क्लेशक्षमाभिः परिवृता स्वस्त्ययनपरानुलोमनैराहारविहारैरनुलोमितवातमूत्रपुरीषा प्रसवकालमुदीक्षेत स्वल्पे ऽपि च विण्मूत्रविबन्धे फलवर्तीः प्रणिदद्यात्", text: "tatrānukūleṣu nakṣatrādiṣu puṇyāhaśabdena gobrāhmaṇavṛddhān natvā āvartamānā pradakṣiṇaṃ praviśya bahuśaḥ prasūtābhiranuraktābhiraviṣādābhiḥ kleśakṣamābhiḥ parivṛtā svastyayanaparānulomanairāhāravihārairanulomitavātamūtrapurīṣā prasavakālamudīkṣeta svalpe 'pi ca viṇmūtravibandhe phalavartīḥ praṇidadyāt" },
      { type: "verse", number: "13", sanskrit: "तत्रासन्नप्रसवायाः क्लमो ग्लानिर्मुक्तबन्धने इवाक्षिणी निष्ठीविका मूत्रपुरीषबाहुल्यं शिथिलकुक्षिताधोगुरुत्वमन्नानभिलाषो वेदनोदरहृदयकटीबस्तिवङ्क्षणेषु तोदभेदशूलस्फुरणस्रवणानि च योन्यां भवन्ति तदनन्तरमावीनां प्रादुर्भावो गर्भोदकप्रवाहश्च", text: "tatrāsannaprasavāyāḥ klamo glānirmuktabandhane ivākṣiṇī niṣṭhīvikā mūtrapurīṣabāhulyaṃ śithilakukṣitādhogurutvamannānabhilāṣo vedanodarahṛdayakaṭībastivaṅkṣaṇeṣu todabhedaśūlasphuraṇasravaṇāni ca yonyāṃ bhavanti tadanantaramāvīnāṃ prādurbhāvo garbhodakapravāhaśca" },
      { type: "verse", number: "14", sanskrit: "अथैनामुपस्थितगर्भां कृतकौतुकमङ्गलां पुन्नामफलहस्तां स्वभ्यक्तामुष्णोदकपरिषिक्तां सघृतां यवागूं पाययेत् ततः सुरक्तार्षभचर्मप्रच्छदे मृदुनि भूमिशयने शयानामुत्तानामाभुग्नसक्थिपृष्ठामहतवाससो ऽशङ्कनीयाः प्रियदर्शनाः परिणतवयसः प्रजननकुशलाः प्रगल्भाः कृत्तनखाः स्त्रियः सूतिकां सूनृताभिर्वाणीभिराश्वासयन्त्यः पर्युपासीरन्", text: "athaināmupasthitagarbhāṃ kṛtakautukamaṅgalāṃ punnāmaphalahastāṃ svabhyaktāmuṣṇodakapariṣiktāṃ saghṛtāṃ yavāgūṃ pāyayet tataḥ suraktārṣabhacarmapracchade mṛduni bhūmiśayane śayānāmuttānāmābhugnasakthipṛṣṭhāmahatavāsaso 'śaṅkanīyāḥ priyadarśanāḥ pariṇatavayasaḥ prajananakuśalāḥ pragalbhāḥ kṛttanakhāḥ striyaḥ sūtikāṃ sūnṛtābhirvāṇībhirāśvāsayantyaḥ paryupāsīran" },
      { type: "verse", number: "15", sanskrit: "अथास्यै दद्यात् कुष्ठैलालाङ्गलीवचाचव्यचित्रकचिरिबिल्वचूर्णमुपाघ्रातुं मुहुर्मुहुः तथा भूर्जपत्रशिंशपासर्जरसान्यतमधूममन्तरान्तरा च पार्श्वपृष्ठकटीसक्थिदेशान् कोष्णेन तैलेनाभ्यज्यानुसुखमस्या मृद्नीयात्", text: "athāsyai dadyāt kuṣṭhailālāṅgalīvacācavyacitrakaciribilvacūrṇamupāghrātuṃ muhurmuhuḥ tathā bhūrjapatraśiṃśapāsarjarasānyatamadhūmamantarāntarā ca pārśvapṛṣṭhakaṭīsakthideśān koṣṇena tailenābhyajyānusukhamasyā mṛdnīyāt" },
      { type: "verse", number: "16", sanskrit: "एकमवाक् परिवर्तते गर्भः तस्य लक्षणम् विमुच्य हृदयमुदरमाविशति बस्तिशिरो ऽवगृह्णाति त्वरयन्त्येनामाव्यः न चेदेवं परिवर्तते ततो मुहुर्मुहुर्जृम्भणं चङ्क्रमणं च कारयितव्यानन्तरोक्तं विधिम्", text: "ekamavāk parivartate garbhaḥ tasya lakṣaṇam vimucya hṛdayamudaramāviśati bastiśiro 'vagṛhṇāti tvarayantyenāmāvyaḥ na cedevaṃ parivartate tato muhurmuhurjṛmbhaṇaṃ caṅkramaṇaṃ ca kārayitavyānantaroktaṃ vidhim" },
      { type: "verse", number: "17", sanskrit: "अन्ये तु मुसलेनोलूखलं धान्यपूर्णमाहननीयमित्याहुः तत्तु न सम्यक् दारुणव्यायामवर्जनं हि गर्भिण्याः सततमुपदिश्यते विशेषतश्च प्रसवकाले प्रचलितसर्वधातुदोषायाः सौकुमार्यत्वान्नार्या मुसलव्यायामेनेरितो वायुरन्तरं लब्ध्वा प्राणान् हिंस्यादिति", text: "anye tu musalenolūkhalaṃ dhānyapūrṇamāhananīyamityāhuḥ tattu na samyak dāruṇavyāyāmavarjanaṃ hi garbhiṇyāḥ satatamupadiśyate viśeṣataśca prasavakāle pracalitasarvadhātudoṣāyāḥ saukumāryatvānnāryā musalavyāyāmenerito vāyurantaraṃ labdhvā prāṇān hiṃsyāditi" },
      { type: "verse", number: "18", sanskrit: "अथ परिवृत्तगर्भां पर्यङ्कमेनामारोप्य कुशला स्त्री पादतो ऽस्या निषण्णाया योनिमनुलोममनुसुखमभ्यज्ज्य स्फिजौ पादाभ्यां पीडयेत् योनिं च पुनः पुनः प्रसाधयेत् ब्रूयाच्च सुभगे शनैश्शनैः प्रवाहयस्व सुप्रसन्नस्ते मुखवर्णः पुत्रं जनयिष्यतीति", text: "atha parivṛttagarbhāṃ paryaṅkamenāmāropya kuśalā strī pādato 'syā niṣaṇṇāyā yonimanulomamanusukhamabhyajjya sphijau pādābhyāṃ pīḍayet yoniṃ ca punaḥ punaḥ prasādhayet brūyācca subhage śanaiśśanaiḥ pravāhayasva suprasannaste mukhavarṇaḥ putraṃ janayiṣyatīti" },
      { type: "verse", number: "19", sanskrit: "अन्या तु वामकर्णे ऽस्या मन्त्रमिमं जपेत्", text: "anyā tu vāmakarṇe 'syā mantramimaṃ japet" },
      { type: "verse", number: "20", sanskrit: "क्षितिर्जलं वियत्तेजो वायुर्विष्णुः प्रजापतिः सगर्भां त्वां सदा पातु वैशल्यं वा दधात्वपि", text: "kṣitirjalaṃ viyattejo vāyurviṣṇuḥ prajāpatiḥ sagarbhāṃ tvāṃ sadā pātu vaiśalyaṃ vā dadhātvapi" },
      { type: "verse", number: "21", sanskrit: "प्रसूष्व त्वमविक्लिष्टमविक्लिष्टा शुभानने कार्तिकेयद्युतिं पुत्रं कार्तिकेयादिरक्षितमिति", text: "prasūṣva tvamavikliṣṭamavikliṣṭā śubhānane kārtikeyadyutiṃ putraṃ kārtikeyādirakṣitamiti" },
      { type: "verse", number: "22", sanskrit: "तथा--- इहामृतञ्च सोमश्च चित्रभानुश्च भामिनि उच्चैश्श्चवाश्च तुरगो मन्दिरे निवसन्तु ते", text: "tathā--- ihāmṛtañca somaśca citrabhānuśca bhāmini uccaiśścavāśca turago mandire nivasantu te" },
      { type: "verse", number: "23", sanskrit: "इदममृतमपां समुद्वृतं वै तव लघुगर्भमिमं प्रमुञ्चतु स्त्री तदनलपवनार्कवासवास्ते सह लवणाम्बुधरैर्दिशन्तु शान्तिमिति", text: "idamamṛtamapāṃ samudvṛtaṃ vai tava laghugarbhamimaṃ pramuñcatu strī tadanalapavanārkavāsavāste saha lavaṇāmbudharairdiśantu śāntimiti" },
      { type: "verse", number: "24", sanskrit: "तथा परा ऽनुशिष्यात् अनागतायां वेदनायां मा प्रवाहिष्ठाः अकालप्रवाहणं हि विण्मूत्रादिवेगानामिवोदीरणमनर्थकरमहितं च गर्भस्य श्वासकासशोषकुब्जतादिकारित्वात् तथा तेषामेव विधारणमिव वेदनायामप्रवाहणमुपघाताय ततो यथोक्तं कुरुष्व", text: "tathā parā 'nuśiṣyāt anāgatāyāṃ vedanāyāṃ mā pravāhiṣṭhāḥ akālapravāhaṇaṃ hi viṇmūtrādivegānāmivodīraṇamanarthakaramahitaṃ ca garbhasya śvāsakāsaśoṣakubjatādikāritvāt tathā teṣāmeva vidhāraṇamiva vedanāyāmapravāhaṇamupaghātāya tato yathoktaṃ kuruṣva" },
      { type: "verse", number: "25", sanskrit: "शनैश्शनैश्च पूर्वं प्रवाहिष्ठाः निर्गमे बाढं गर्भस्य योनिमुखप्रतिपत्तौ बाढतरमाप्रसवादिति तस्यास्तु प्रवाहमानायाः स्त्रियः शब्दं कुर्युः प्रजाता प्रजाता धन्यं धन्यं पुत्रमिति तथास्या हर्षेण प्राणा आप्यायन्ते", text: "śanaiśśanaiśca pūrvaṃ pravāhiṣṭhāḥ nirgame bāḍhaṃ garbhasya yonimukhapratipattau bāḍhataramāprasavāditi tasyāstu pravāhamānāyāḥ striyaḥ śabdaṃ kuryuḥ prajātā prajātā dhanyaṃ dhanyaṃ putramiti tathāsyā harṣeṇa prāṇā āpyāyante" },
      { type: "verse", number: "26", sanskrit: "गर्भसङ्गे तु योनिं धूपयेत् कृष्णसर्पनिर्मोकेन पिण्डीतकेन वा बध्नीयाच्च हिरण्यपुष्पीमूलं हस्तपादे धारयेच्च सुवर्चलां विशल्यां वा", text: "garbhasaṅge tu yoniṃ dhūpayet kṛṣṇasarpanirmokena piṇḍītakena vā badhnīyācca hiraṇyapuṣpīmūlaṃ hastapāde dhārayecca suvarcalāṃ viśalyāṃ vā" },
      { type: "verse", number: "27", sanskrit: "अथ प्रसूताया न चेदपरा पतति ततो दक्षिणेन पाणिना नाभेरुपरिष्टाद्बलवदुपपीड्य अन्येन पृष्ठत उपसङ्गृह्य विधुनुयात्", text: "atha prasūtāyā na cedaparā patati tato dakṣiṇena pāṇinā nābherupariṣṭādbalavadupapīḍya anyena pṛṣṭhata upasaṅgṛhya vidhunuyāt" },
      { type: "verse", number: "28", sanskrit: "पार्ष्ण्या वा श्रोणीमाकोटयेत् स्फिजौ वोपसंगृह्य सुपीडितं निपीडयेत् वेण्याङ्गुल्या वा केशवेष्टितया च कण्ठतालू परामृशेत्", text: "pārṣṇyā vā śroṇīmākoṭayet sphijau vopasaṃgṛhya supīḍitaṃ nipīḍayet veṇyāṅgulyā vā keśaveṣṭitayā ca kaṇṭhatālū parāmṛśet" },
      { type: "verse", number: "29", sanskrit: "भूर्जपत्रकाचमणिसर्पनिर्मोकैश्च योनिं धूपयेत् भूर्जगुग्गुलुभ्यां वा शालिमूलसिद्धेन वा सर्पिषा योनिमभ्यज्य कटुकालाबुजालिनीनिम्बसर्पनिर्मोकैर्धूपयेत् अनभ्यक्तां वा कटुतैलमिश्रैः कल्कीकृतैर्वा तैलाक्तैरालिम्पेत् गुडनागरकल्केन वा तदेव वा भक्षयेत् लाङ्गलीमूलकल्केन वा पाणिमुदरं चालिम्पेत् महावृक्षक्षीरं वा मूर्धन्यनुषेचयेत्", text: "bhūrjapatrakācamaṇisarpanirmokaiśca yoniṃ dhūpayet bhūrjaguggulubhyāṃ vā śālimūlasiddhena vā sarpiṣā yonimabhyajya kaṭukālābujālinīnimbasarpanirmokairdhūpayet anabhyaktāṃ vā kaṭutailamiśraiḥ kalkīkṛtairvā tailāktairālimpet guḍanāgarakalkena vā tadeva vā bhakṣayet lāṅgalīmūlakalkena vā pāṇimudaraṃ cālimpet mahāvṛkṣakṣīraṃ vā mūrdhanyanuṣecayet" },
      { type: "verse", number: "30", sanskrit: "कुष्ठतालीसकल्कं बिल्वबल्वजयूषमैरेयासवसुरामण्डान्यतमेन व्योषतीक्ष्णोष्णेन वाम्लेन कुलत्थरसेन मधुकपिप्पलीसम्पाकेन वा पाययेत् पिप्पल्येलाकोलविबिडचव्यचित्रकोपकुञ्चिकाकल्कं वा खरस्य वृषभस्य वा जीवतो दक्षिणं कर्णमुद्धृत्य बिल्वकुलत्थबल्वजयूषादीनामाप्लावनानामन्यतमे प्रक्षिप्य मुहूर्तस्थितमुद्धृत्य तदाप्लावनं पाययेत्", text: "kuṣṭhatālīsakalkaṃ bilvabalvajayūṣamaireyāsavasurāmaṇḍānyatamena vyoṣatīkṣṇoṣṇena vāmlena kulattharasena madhukapippalīsampākena vā pāyayet pippalyelākolavibiḍacavyacitrakopakuñcikākalkaṃ vā kharasya vṛṣabhasya vā jīvato dakṣiṇaṃ karṇamuddhṛtya bilvakulatthabalvajayūṣādīnāmāplāvanānāmanyatame prakṣipya muhūrtasthitamuddhṛtya tadāplāvanaṃ pāyayet" },
      { type: "verse", number: "31", sanskrit: "कुष्ठैलाकल्कं वा सुरया अर्कालर्ककषायं वा प्रजातां सुरोन्मिश्रम् कुष्ठलाङ्गलिकीमूलककल्कं वा मद्यमूत्रान्यतमेन वत्सकादिचूर्णं वा मद्येन शतपुष्पाकुष्ठमदनहिङ्गुसिद्धस्य च तैलस्य पिचुं ग्राहयेत् ततश्चैनामनुवासनकाले ऽनुवासयेत्", text: "kuṣṭhailākalkaṃ vā surayā arkālarkakaṣāyaṃ vā prajātāṃ suronmiśram kuṣṭhalāṅgalikīmūlakakalkaṃ vā madyamūtrānyatamena vatsakādicūrṇaṃ vā madyena śatapuṣpākuṣṭhamadanahiṅgusiddhasya ca tailasya picuṃ grāhayet tataścaināmanuvāsanakāle 'nuvāsayet" },
      { type: "verse", number: "32", sanskrit: "बिल्वबल्बजयूषाद्याप्लावनैश्च फलजीमूतकेक्ष्वाकुधामार्गवकुटजार्ककृतवेधनहस्तिपर्ण्यभीरूपहितैरास्थापयेत् सिद्धार्थककुष्ठलाङ्गलिकीमहावृक्षक्षीरमिश्रेण वा सुरामण्डेन शाल्मलीवृन्तानि वा स्विन्नान्यापोथ्य पञ्चमूलकषाये विमर्दयेत् तेन च पूतेन स्नेहवता फलादियुक्तेन", text: "bilvabalbajayūṣādyāplāvanaiśca phalajīmūtakekṣvākudhāmārgavakuṭajārkakṛtavedhanahastiparṇyabhīrūpahitairāsthāpayet siddhārthakakuṣṭhalāṅgalikīmahāvṛkṣakṣīramiśreṇa vā surāmaṇḍena śālmalīvṛntāni vā svinnānyāpothya pañcamūlakaṣāye vimardayet tena ca pūtena snehavatā phalādiyuktena" },
      { type: "verse", number: "33", sanskrit: "यथोक्तास्थापनद्रव्यसिद्धेन कटुतैलोत्तरबस्तिं दद्यात् शिग्रुसुमुखमरिचाजाजीचित्रककल्कक्षीरगोमूत्रसिद्धेन वा कटुतैलेनानुवासयेत् उमाशाल्मलीपिच्छया वा सघृतया योनिं पूरयित्वा विधुनुयात् स्निग्धेन वा कृत्तनखेन पाणिना नालानुसारतो ऽपहरेत्", text: "yathoktāsthāpanadravyasiddhena kaṭutailottarabastiṃ dadyāt śigrusumukhamaricājājīcitrakakalkakṣīragomūtrasiddhena vā kaṭutailenānuvāsayet umāśālmalīpicchayā vā saghṛtayā yoniṃ pūrayitvā vidhunuyāt snigdhena vā kṛttanakhena pāṇinā nālānusārato 'paharet" },
      { type: "verse", number: "34", sanskrit: "प्रजातायां चेद्बस्तिमूर्धोदरेषु शूलं मक्कलाख्यं स्यात्तत्र यवक्षारचूर्णं सर्पिषा सुखोष्णोदकेन वा पिबेत् वरणादिं वा सपञ्चकोलमेलाप्रतीवापम्", text: "prajātāyāṃ cedbastimūrdhodareṣu śūlaṃ makkalākhyaṃ syāttatra yavakṣāracūrṇaṃ sarpiṣā sukhoṣṇodakena vā pibet varaṇādiṃ vā sapañcakolamelāpratīvāpam" },
      { type: "verse", number: "35", sanskrit: "अथवा वीरतरादिमूषरादिप्रतीवापम् लवणचूर्णं वा वत्सकादिनिर्यूहेण वत्सकादिं वा मदिरया अंशुमतीद्वयक्वाथेन वा मरिचभद्रदारुकल्कम् भार्ङ्गीनागरदेवदारुकल्कं वोष्णाम्भसा पुराणगुडं वा त्रिकटुत्रिजातकधनिकाचूर्णसंसृष्टं भक्षयेत्", text: "athavā vīratarādimūṣarādipratīvāpam lavaṇacūrṇaṃ vā vatsakādiniryūheṇa vatsakādiṃ vā madirayā aṃśumatīdvayakvāthena vā maricabhadradārukalkam bhārṅgīnāgaradevadārukalkaṃ voṣṇāmbhasā purāṇaguḍaṃ vā trikaṭutrijātakadhanikācūrṇasaṃsṛṣṭaṃ bhakṣayet" },
      { type: "verse", number: "36", sanskrit: "तस्याश्चेत् स्वस्थानतो योनिर्भ्रश्येत् ततो यस्य कस्यचिच्छोणितेनाभ्यज्य योनिं यथास्थानं कुशला स्त्री निवेशयेत् निविष्टां चाशोकरोहिणीबर्हिषोशीरप्रियङ्गुदेवदारुकल्कविपक्वेन तैलेन बहुशः स्वेदयेत् पूरयेत् ब्रूयाच्च गच्छ सुभगे स्वस्थानमिति", text: "tasyāścet svasthānato yonirbhraśyet tato yasya kasyacicchoṇitenābhyajya yoniṃ yathāsthānaṃ kuśalā strī niveśayet niviṣṭāṃ cāśokarohiṇībarhiṣośīrapriyaṅgudevadārukalkavipakvena tailena bahuśaḥ svedayet pūrayet brūyācca gaccha subhage svasthānamiti" },
      { type: "verse", number: "37", sanskrit: "तद्वच्चान्यतमा स्त्री जातमात्रमेव बालं बालोपचरणीयेन विधिनोपपादयेत् तमुपदेक्ष्यते तूतारेषु अथ सूतिकां बलातैलेनाभ्यज्यात् बुभुक्षितां च पञ्चकोलचूर्णेन यवान्युपकुञ्चिकाचव्यचित्रकव्योषसैन्धवचूर्णेन वा युक्तामहःपरिणामिनीं यथासात्म्यं स्नेहमात्रां पाययेत् स्नेहायोग्यां वातहरौषधक्वाथं ह्रस्वपज्चमूलक्वाथं वा", text: "tadvaccānyatamā strī jātamātrameva bālaṃ bālopacaraṇīyena vidhinopapādayet tamupadekṣyate tūtāreṣu atha sūtikāṃ balātailenābhyajyāt bubhukṣitāṃ ca pañcakolacūrṇena yavānyupakuñcikācavyacitrakavyoṣasaindhavacūrṇena vā yuktāmahaḥpariṇāminīṃ yathāsātmyaṃ snehamātrāṃ pāyayet snehāyogyāṃ vātaharauṣadhakvāthaṃ hrasvapajcamūlakvāthaṃ vā" },
      { type: "verse", number: "38", sanskrit: "पीतवत्याश्च यमकेनाभ्यज्य वेष्टयेदुदरं वस्त्रेण तथा न वायुरुदरविकृतिमुत्पादयेदयेदनवकाशत्वात् जीएणे तु स्नेहे पूर्वैषधैरेव सिद्धां विदार्यादिगणक्वाथेन क्षीरेण वा यवागूं सुस्विन्नां द्रवां मात्रया पाययेत् प्राक् स्नेहयवागूपानाभ्यां चोभयकालमुष्णोदकेन परिषेचयेत्", text: "pītavatyāśca yamakenābhyajya veṣṭayedudaraṃ vastreṇa tathā na vāyurudaravikṛtimutpādayedayedanavakāśatvāt jīeṇe tu snehe pūrvaiṣadhaireva siddhāṃ vidāryādigaṇakvāthena kṣīreṇa vā yavāgūṃ susvinnāṃ dravāṃ mātrayā pāyayet prāk snehayavāgūpānābhyāṃ cobhayakālamuṣṇodakena pariṣecayet" },
      { type: "verse", number: "39", sanskrit: "एवं त्रिरात्रं पञ्चरात्रं सप्तरात्रं वानुपाल्य ततो यवकोलकुलत्थयूषेण लघुना चान्नपानेन द्वादशरात्रात् परं जाङ्गलरसादिभिश्च क्रमादाप्याययेदग्निबलादीन्यपेक्ष्य क्वथितशीतं च तोयं पाययेत् तथा जीवनीयबृंहणीयमधुरवातहरसिद्धैरभ्यङ्गोद्वर्तनपरिषेकावगाहैरन्नपानैश्च हृद्यैरुपाचरेत् एवं हि गर्भवृद्धिक्षपितशिथिलसर्वशरीरधातुप्रवाहणवेदनाक्लेदरक्तनिस्स्रुतिविशेषशून्यशरीराच्च पुअर्नवीभवति", text: "evaṃ trirātraṃ pañcarātraṃ saptarātraṃ vānupālya tato yavakolakulatthayūṣeṇa laghunā cānnapānena dvādaśarātrāt paraṃ jāṅgalarasādibhiśca kramādāpyāyayedagnibalādīnyapekṣya kvathitaśītaṃ ca toyaṃ pāyayet tathā jīvanīyabṛṃhaṇīyamadhuravātaharasiddhairabhyaṅgodvartanapariṣekāvagāhairannapānaiśca hṛdyairupācaret evaṃ hi garbhavṛddhikṣapitaśithilasarvaśarīradhātupravāhaṇavedanākledaraktanissrutiviśeṣaśūnyaśarīrācca puarnavībhavati" },
      { type: "verse", number: "40", sanskrit: "अत एव च सूतिकाया व्याधिः कृच्छ्रसाध्यो भवत्यसाध्यो वा तस्मात्तां यथोक्तेन विधिना प्रयत्नेनोपचरेत् एवं साध्यर्धमासमुपसंस्कृता क्रमेण विमुक्ताहारविहारयन्त्रणा विगतसूतिकाभिघाना स्यात् पुनरार्तवदर्शनादित्येके", text: "ata eva ca sūtikāyā vyādhiḥ kṛcchrasādhyo bhavatyasādhyo vā tasmāttāṃ yathoktena vidhinā prayatnenopacaret evaṃ sādhyardhamāsamupasaṃskṛtā krameṇa vimuktāhāravihārayantraṇā vigatasūtikābhighānā syāt punarārtavadarśanādityeke" },
      { type: "verse", number: "41", sanskrit: "इत्याद्यं मासमादाय यावद्गर्भक्षमा पुनः स्त्री स्यात्तावद्विधिः सर्वः सर्वथा साधु दर्शितः", text: "ityādyaṃ māsamādāya yāvadgarbhakṣamā punaḥ strī syāttāvadvidhiḥ sarvaḥ sarvathā sādhu darśitaḥ" },
    ],
  },
  {
    sthana: "Шарирастхана",
    number: 4,
    lang: "sa",
    content: [
      { type: "heading", heading: "Мармана шарира — жизненные точки марма" },
      { type: "text", text: "Глава 4 Шарирастханы Астанга-санграхи — «Мармана шарира» — посвящена анатомическим и эмбриологическим аспектам: жизненные точки марма." },
      { type: "verse", number: "1", sanskrit: "अथातो गर्भव्यापदं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto garbhavyāpadaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "स्त्री चेदापन्नगर्भा परिहार्याण्यासेवेत ततश्च यस्या बस्तिपार्श्वश्रोणियोनिमुखेषु शूलं पुष्पदर्शनं च स्यात् तां मृदुसुखशिशिरास्तरणशयनस्थामीषदवनतशिरसं शीतप्रदेहपरिषेकादिभिरुपाचरेत्", text: "strī cedāpannagarbhā parihāryāṇyāseveta tataśca yasyā bastipārśvaśroṇiyonimukheṣu śūlaṃ puṣpadarśanaṃ ca syāt tāṃ mṛdusukhaśiśirāstaraṇaśayanasthāmīṣadavanataśirasaṃ śītapradehapariṣekādibhirupācaret" },
      { type: "verse", number: "3", sanskrit: "तद्यथा सहस्रधौतेन सर्पिषाधोनाभेः सर्वतः प्रदिह्यात् मधुकसिद्धसर्पिषा सुशीतेन पिचुमाप्लाव्य योनिसमीपे स्थापयेत् गव्येन पयसा मधुकाम्बुना न्यग्रोधादिकषायेण वा परिषेचयेत् परिपीततत्स्वरसानि च तैलानि योनौ निधापयेत् तच्छृङ्गसिद्धस्य वा क्षीरसर्पिषः पिचुम्", text: "tadyathā sahasradhautena sarpiṣādhonābheḥ sarvataḥ pradihyāt madhukasiddhasarpiṣā suśītena picumāplāvya yonisamīpe sthāpayet gavyena payasā madhukāmbunā nyagrodhādikaṣāyeṇa vā pariṣecayet paripītatatsvarasāni ca tailāni yonau nidhāpayet tacchṛṅgasiddhasya vā kṣīrasarpiṣaḥ picum" },
      { type: "verse", number: "4", sanskrit: "अतिस्रवति तु रक्ते तत एवाक्षमात्रं प्राशयेत् केवलादेव वा क्षीरसर्पिषः पद्मोत्पलकुमुदकिञ्जल्कं च समधुशर्करं लेहयेत्", text: "atisravati tu rakte tata evākṣamātraṃ prāśayet kevalādeva vā kṣīrasarpiṣaḥ padmotpalakumudakiñjalkaṃ ca samadhuśarkaraṃ lehayet" },
      { type: "verse", number: "5", sanskrit: "धातकीगैरिकसर्जरसाञ्जनचूर्णं वा मधुना न्यग्रोधादित्वक्प्रवालकल्कं वा शशैणहरिणरुधिरं वा सक्षौद्रं पाययेत् ऋद्धिविदारीजीवन्तीर्वा पयसा नीलोत्पलसितापक्वलोष्टचन्दनादि वा तण्डुलशालूकोदुम्बरशलाटुन्यग्रोधशृङ्गानि वा आजेन पयसा", text: "dhātakīgairikasarjarasāñjanacūrṇaṃ vā madhunā nyagrodhāditvakpravālakalkaṃ vā śaśaiṇahariṇarudhiraṃ vā sakṣaudraṃ pāyayet ṛddhividārījīvantīrvā payasā nīlotpalasitāpakvaloṣṭacandanādi vā taṇḍulaśālūkodumbaraśalāṭunyagrodhaśṛṅgāni vā ājena payasā" },
      { type: "verse", number: "6", sanskrit: "कशेरुकमृणालकशृङ्गाटककाश्मर्यपरूषकद्राक्षासारिवाप्रपौण्डरीकानन्तोत्पलकदम्बबीजक्वाथेन वा शर्करामधुमधुरेण शालिचूर्णम् जीवनीयशृतं वा क्षीरम् बलातिबलाशालिषष्टिकेक्षुमूलकाकोलीशृतेन पयसा समधुशर्करेण रक्तशाल्योदनं सुशीतं भोजयेत् शीतवीर्यजाङ्गलरसेन वा रक्तपित्तक्रियाश्च शोधनवर्ज्याः प्रयुञ्जीत सौम्याश्च मनो ऽनुकूलाः कथाः", text: "kaśerukamṛṇālakaśṛṅgāṭakakāśmaryaparūṣakadrākṣāsārivāprapauṇḍarīkānantotpalakadambabījakvāthena vā śarkarāmadhumadhureṇa śālicūrṇam jīvanīyaśṛtaṃ vā kṣīram balātibalāśāliṣaṣṭikekṣumūlakākolīśṛtena payasā samadhuśarkareṇa raktaśālyodanaṃ suśītaṃ bhojayet śītavīryajāṅgalarasena vā raktapittakriyāśca śodhanavarjyāḥ prayuñjīta saumyāśca mano 'nukūlāḥ kathāḥ" },
      { type: "verse", number: "7", sanskrit: "अदृष्टशोणितां तु मधुकपयस्यासुरदारुभिः सिद्धं पयः पाययेत् ताम्रवल्यश्मन्तकशतावरीपयस्याभिर्वा विदार्यादिगणेन वा श्वदंष्ट्रास्वरसक्षीरसिद्धं वा सर्पिः पलाण्डुरससिद्धं वा सक्षौद्रम्", text: "adṛṣṭaśoṇitāṃ tu madhukapayasyāsuradārubhiḥ siddhaṃ payaḥ pāyayet tāmravalyaśmantakaśatāvarīpayasyābhirvā vidāryādigaṇena vā śvadaṃṣṭrāsvarasakṣīrasiddhaṃ vā sarpiḥ palāṇḍurasasiddhaṃ vā sakṣaudram" },
      { type: "verse", number: "8", sanskrit: "असम्पूर्णत्रिमासायास्तु पुष्पदर्शने गर्भः प्रायो न तिष्ठत्यसञ्जातसारत्वात्", text: "asampūrṇatrimāsāyāstu puṣpadarśane garbhaḥ prāyo na tiṣṭhatyasañjātasāratvāt" },
      { type: "verse", number: "9", sanskrit: "आमान्वये चोर्ध्वमपि विरुद्धोपक्रमत्वात् तत्र रूक्षशीतानि प्रयुञ्जीत", text: "āmānvaye cordhvamapi viruddhopakramatvāt tatra rūkṣaśītāni prayuñjīta" },
      { type: "verse", number: "10", sanskrit: "तद्यथा प्रागुपवासं ततो दुरालभामृतोशीरपर्पटकघनचन्दनातिविषाबलाकट्वङ्गधान्याकक्वाथपानम् तृणधान्यशालिषष्टिकपेयामशनं च मुद्गादियूषैः जिते त्वामे स्निग्धशीतानि पूर्ववत्", text: "tadyathā prāgupavāsaṃ tato durālabhāmṛtośīraparpaṭakaghanacandanātiviṣābalākaṭvaṅgadhānyākakvāthapānam tṛṇadhānyaśāliṣaṣṭikapeyāmaśanaṃ ca mudgādiyūṣaiḥ jite tvāme snigdhaśītāni pūrvavat" },
      { type: "verse", number: "11", sanskrit: "आमगर्भे तु पतिते मद्यानामन्यतमं सामर्थ्यतः पाययेत् गर्भकोष्ठविशुध्यर्थमार्तिविस्मरणार्थं च अमद्यपां पाचनीयद्रव्योपहिताभिः स्नेहलवणवर्ज्याभिः सतिलाभिरुद्दालकादियवागूभिरुपाचरेद्यावन्तो मासास्तावन्त्यहानीति", text: "āmagarbhe tu patite madyānāmanyatamaṃ sāmarthyataḥ pāyayet garbhakoṣṭhaviśudhyarthamārtivismaraṇārthaṃ ca amadyapāṃ pācanīyadravyopahitābhiḥ snehalavaṇavarjyābhiḥ satilābhiruddālakādiyavāgūbhirupācaredyāvanto māsāstāvantyahānīti" },
      { type: "verse", number: "12", sanskrit: "ततः प्रीणनैर्बलानुरक्षिभिरस्नेहैराहारैरादोषधातुक्लेदशुद्धेः आमगर्भशेषेण हि पुनःपुनरकुशलमनुषज्येत तस्मात्तीक्ष्णैरनवशेषयन्नुपाचरेत् ततः परं स्नेहपानैर्बस्तिभिराहारैश्च दीपनीयपाचनीयजीवनीयबृंहणीयमधुरवातहरैरिति", text: "tataḥ prīṇanairbalānurakṣibhirasnehairāhārairādoṣadhātukledaśuddheḥ āmagarbhaśeṣeṇa hi punaḥpunarakuśalamanuṣajyeta tasmāttīkṣṇairanavaśeṣayannupācaret tataḥ paraṃ snehapānairbastibhirāhāraiśca dīpanīyapācanīyajīvanīyabṛṃhaṇīyamadhuravātaharairiti" },
      { type: "verse", number: "13", sanskrit: "यस्याः पुनर्महति जातसारे गर्भे वर्ज्यानामवर्जनात् पुष्पदर्शनं स्यादन्यद्वा योनिस्रवणम् तस्यास्तन्निमित्तं वायुः प्रकुपितः पित्तश्लेष्माणौ परिगृह्य गर्भस्य रसवहां नाडीं प्रतिपीड्यावतिष्ठते ततो नाड्यां दोषैः कुल्यायामिव तृणपत्रादिभिः प्रतिच्छन्नायां रसस्यासम्यग्वहनाद्गर्भो वृद्धिमनाप्नुवन्नुपविशत्युपशुष्यति वा", text: "yasyāḥ punarmahati jātasāre garbhe varjyānāmavarjanāt puṣpadarśanaṃ syādanyadvā yonisravaṇam tasyāstannimittaṃ vāyuḥ prakupitaḥ pittaśleṣmāṇau parigṛhya garbhasya rasavahāṃ nāḍīṃ pratipīḍyāvatiṣṭhate tato nāḍyāṃ doṣaiḥ kulyāyāmiva tṛṇapatrādibhiḥ praticchannāyāṃ rasasyāsamyagvahanādgarbho vṛddhimanāpnuvannupaviśatyupaśuṣyati vā" },
      { type: "verse", number: "14", sanskrit: "तत्र यस्याः कादाचित्कार्तवपरिस्रावावल्पौ च दृश्येते सततं च गर्भः प्राप्तात्परिमाणादपरिहीयमान एव स्फुरति न च कुक्षिर्विवर्धते तमुपविष्टकमित्याचक्षते यदा तु प्रतिमासमार्तवं प्रत्यहं वा परिस्रवणं नात्यल्पं च तथा परिहीयमाणो गर्भश्चिरात् किञ्चित् स्पन्दते कुक्षिश्च वृद्धो ऽपि परिहीयते तदुपशुष्ककं नागोदरं च", text: "tatra yasyāḥ kādācitkārtavaparisrāvāvalpau ca dṛśyete satataṃ ca garbhaḥ prāptātparimāṇādaparihīyamāna eva sphurati na ca kukṣirvivardhate tamupaviṣṭakamityācakṣate yadā tu pratimāsamārtavaṃ pratyahaṃ vā parisravaṇaṃ nātyalpaṃ ca tathā parihīyamāṇo garbhaścirāt kiñcit spandate kukṣiśca vṛddho 'pi parihīyate tadupaśuṣkakaṃ nāgodaraṃ ca" },
      { type: "verse", number: "15", sanskrit: "तौ तु मातुराहारतेजसाल्पेनाप्याय्यमानौ यदा पुष्टौ स्यातां केशदशनादियुक्तौ तदा वर्षगणैरपि प्रमदा प्रसूयत एव", text: "tau tu māturāhāratejasālpenāpyāyyamānau yadā puṣṭau syātāṃ keśadaśanādiyuktau tadā varṣagaṇairapi pramadā prasūyata eva" },
      { type: "verse", number: "16", sanskrit: "तत्र वातेनोपविष्टकोपशुष्ककयोर्वायुः प्रतिहन्यते सशब्दं फेनिलं विच्छिन्नं शकृदुपवेश्यते मूत्रमुपरुध्यते कटीपृष्ठहृदयेषु वेदना जृम्भा निद्रानाशो ऽभीक्ष्णं प्रतिश्यायः शुष्ककासः सादः क्ष्वेडेते इव कर्णौ तुद्येते इव शङ्खौ पिपीलिकाभिरिव संसृज्यते शरीरं परिकृन्तन्निव वायुर्भ्रमति कुक्षौ तम इव प्रवेश्यते दुःखेनान्नस्य जरणमहरहः परिहानिः स्फुटितविवर्णपरुषत्वक्त्वं च भवति", text: "tatra vātenopaviṣṭakopaśuṣkakayorvāyuḥ pratihanyate saśabdaṃ phenilaṃ vicchinnaṃ śakṛdupaveśyate mūtramuparudhyate kaṭīpṛṣṭhahṛdayeṣu vedanā jṛmbhā nidrānāśo 'bhīkṣṇaṃ pratiśyāyaḥ śuṣkakāsaḥ sādaḥ kṣveḍete iva karṇau tudyete iva śaṅkhau pipīlikābhiriva saṃsṛjyate śarīraṃ parikṛntanniva vāyurbhramati kukṣau tama iva praveśyate duḥkhenānnasya jaraṇamaharahaḥ parihāniḥ sphuṭitavivarṇaparuṣatvaktvaṃ ca bhavati" },
      { type: "verse", number: "17", sanskrit: "पित्तेन ताम्रहरितमुपवेश्यते धूमको ऽम्लकश्छर्दिर्मूर्छा कुक्षिहृदयदाहः पीतरक्तगोमूत्राभनेत्रमूत्रनखत्वक्त्वं काली दुर्बला नित्यशूना च नारी भवति", text: "pittena tāmraharitamupaveśyate dhūmako 'mlakaśchardirmūrchā kukṣihṛdayadāhaḥ pītaraktagomūtrābhanetramūtranakhatvaktvaṃ kālī durbalā nityaśūnā ca nārī bhavati" },
      { type: "verse", number: "18", sanskrit: "श्लेष्मणा मधुरास्यत्वमुत्क्लेशः श्लेष्मोद्वमनं भक्तद्वेषः श्वेतहस्तपादनेत्रता कासः श्वासश्च", text: "śleṣmaṇā madhurāsyatvamutkleśaḥ śleṣmodvamanaṃ bhaktadveṣaḥ śvetahastapādanetratā kāsaḥ śvāsaśca" },
      { type: "verse", number: "19", sanskrit: "तयोर्जीवनीयबृंहणीयमधुरौषधसिद्धानां संपिषामुपयोगः तथा पयसां रसानामामगर्भाणां च गर्भवृद्धिकरः तथा सम्भोजनमेतैरेव च घृतादिभिः सुभिक्षाया अभीक्ष्णं यानवाहनापवर्जनबृंहणैरुपपादनम्", text: "tayorjīvanīyabṛṃhaṇīyamadhurauṣadhasiddhānāṃ saṃpiṣāmupayogaḥ tathā payasāṃ rasānāmāmagarbhāṇāṃ ca garbhavṛddhikaraḥ tathā sambhojanametaireva ca ghṛtādibhiḥ subhikṣāyā abhīkṣṇaṃ yānavāhanāpavarjanabṛṃhaṇairupapādanam" },
      { type: "verse", number: "20", sanskrit: "अथ विशेषेण वाते पूर्वमेव सैन्धबोपहितं क्षीरबस्तिं दत्वा शीतोदकस्नातां मृदु शाल्योदनं भोजयेत् ततो विदार्यादिगणसाधितेन संषिषानुवासयेत् निवातं च सेवेत पित्ते मधुकविदारीनिर्यूहसिद्धं पयः पिबेत् तिस्रः स्थूलकुक्कुटीर्निस्तुषमाषाढकं च क्षीरोदकेनोलूखले सङ्क्षुद्य तद्रसेन सर्पिषा च तित्तिरिकपिञ्जलान्यतररसं साघयित्वा पाययेदुपविष्टकविवर्धनार्थमुपशुष्ककबृंहणार्थं च अजासंपिषा क्षीरेण जीवनीयैश्च संस्कृतां यवागूं पिबेत्", text: "atha viśeṣeṇa vāte pūrvameva saindhabopahitaṃ kṣīrabastiṃ datvā śītodakasnātāṃ mṛdu śālyodanaṃ bhojayet tato vidāryādigaṇasādhitena saṃṣiṣānuvāsayet nivātaṃ ca seveta pitte madhukavidārīniryūhasiddhaṃ payaḥ pibet tisraḥ sthūlakukkuṭīrnistuṣamāṣāḍhakaṃ ca kṣīrodakenolūkhale saṅkṣudya tadrasena sarpiṣā ca tittirikapiñjalānyatararasaṃ sāghayitvā pāyayedupaviṣṭakavivardhanārthamupaśuṣkakabṛṃhaṇārthaṃ ca ajāsaṃpiṣā kṣīreṇa jīvanīyaiśca saṃskṛtāṃ yavāgūṃ pibet" },
      { type: "verse", number: "21", sanskrit: "पयस्याकाकोलीद्वयसुनिषण्णककल्केन पयसा च सर्पिर्विपाचयेत् तत् काल्यं क्षीरानुपानमुपयुञ्जीत आमगर्भरसेन चाश्नीयात् तानेव च तत्र भृष्टान् भक्षयेत् जलचरमांसानि च कफे त्वानूपौदकपिशितोपदंशामच्छसुरां त्रिरात्रं पञ्चरात्रं सप्तरात्रं वा पिबेत्", text: "payasyākākolīdvayasuniṣaṇṇakakalkena payasā ca sarpirvipācayet tat kālyaṃ kṣīrānupānamupayuñjīta āmagarbharasena cāśnīyāt tāneva ca tatra bhṛṣṭān bhakṣayet jalacaramāṃsāni ca kaphe tvānūpaudakapiśitopadaṃśāmacchasurāṃ trirātraṃ pañcarātraṃ saptarātraṃ vā pibet" },
      { type: "verse", number: "22", sanskrit: "तिलमुद्गमाषलवणाबिल्वपात्रैः पञ्चभिर्घृतपात्रं संयोज्य स्वनुगुप्तं निधापयेत् ततः प्रातः पिण्डं बिल्वमात्रं शृतशीतच्छागदुग्धानुपानं वाश्नीयात् अत्रैव वा बदरचूर्णपात्रमपि निदध्यात् एवमवृद्धौ तीक्ष्णैर्विरेचयेदपरापातनीयैश्च पातयेत्", text: "tilamudgamāṣalavaṇābilvapātraiḥ pañcabhirghṛtapātraṃ saṃyojya svanuguptaṃ nidhāpayet tataḥ prātaḥ piṇḍaṃ bilvamātraṃ śṛtaśītacchāgadugdhānupānaṃ vāśnīyāt atraiva vā badaracūrṇapātramapi nidadhyāt evamavṛddhau tīkṣṇairvirecayedaparāpātanīyaiśca pātayet" },
      { type: "verse", number: "23", sanskrit: "यस्याः पुनर्वातोपसृष्टस्रोतसि लीनो गर्भः प्रसुप्तो न स्पन्दते तं लीनमित्याहुः तत्र श्येनोत्क्रोशगोमत्स्यगोधाशिखिकुक्कुटतित्तिरीणामन्यतमस्य रसेन भूरिसर्पिष्केण माषयूषेण वा घृताढ्येन रक्तशाल्योदनं भोजयेत् सक्तून्वा तिलमाषबिल्वशलाटुयुक्तान् पयसा पाययेत् मेद्यमांसोपदंशं वा मार्द्वीकम् तैलेन चाभीक्ष्णमुदरवङ्क्षणोरुकटीपार्श्वपृष्ठान्यभ्यज्यात् मुहुर्मुहुश्चैनां हर्षयेत् पूर्वोक्तं चेक्षेत यस्याः पुनरुदावर्तविबन्धः स्यात्तां वातहरस्निग्धान्नपानैरुपाचरेत्", text: "yasyāḥ punarvātopasṛṣṭasrotasi līno garbhaḥ prasupto na spandate taṃ līnamityāhuḥ tatra śyenotkrośagomatsyagodhāśikhikukkuṭatittirīṇāmanyatamasya rasena bhūrisarpiṣkeṇa māṣayūṣeṇa vā ghṛtāḍhyena raktaśālyodanaṃ bhojayet saktūnvā tilamāṣabilvaśalāṭuyuktān payasā pāyayet medyamāṃsopadaṃśaṃ vā mārdvīkam tailena cābhīkṣṇamudaravaṅkṣaṇorukaṭīpārśvapṛṣṭhānyabhyajyāt muhurmuhuścaināṃ harṣayet pūrvoktaṃ cekṣeta yasyāḥ punarudāvartavibandhaḥ syāttāṃ vātaharasnigdhānnapānairupācaret" },
      { type: "verse", number: "24", sanskrit: "अष्टमे तु मासे मधुकसिद्धेन तैलेनानुवासयेत् तदसिद्धौ वीरणशालिकुशकाशेक्षुबालिकावेतसपरिव्याधमूलानां भूतीकानन्ताकाश्मर्यपरूषकमधूकमधुकमृद्वीकानां च पयसार्धोदकेनोद्गृह्य रसं तेन प्रियालबिभीतकमज्जतिलकल्कयुक्तेनेषल्लवणोष्णेन निरूहयेत् विगतविबन्धां च स्नाताशितां सायं तेनैव तैलेनानुवासयेत्", text: "aṣṭame tu māse madhukasiddhena tailenānuvāsayet tadasiddhau vīraṇaśālikuśakāśekṣubālikāvetasaparivyādhamūlānāṃ bhūtīkānantākāśmaryaparūṣakamadhūkamadhukamṛdvīkānāṃ ca payasārdhodakenodgṛhya rasaṃ tena priyālabibhītakamajjatilakalkayukteneṣallavaṇoṣṇena nirūhayet vigatavibandhāṃ ca snātāśitāṃ sāyaṃ tenaiva tailenānuvāsayet" },
      { type: "verse", number: "25", sanskrit: "उदावर्तो हि समुपेक्षितः सहसा सगर्भां गर्भिणीमतिपातयेत्", text: "udāvarto hi samupekṣitaḥ sahasā sagarbhāṃ garbhiṇīmatipātayet" },
      { type: "verse", number: "26", sanskrit: "यस्याः पुनरतिमात्रदोषोपचयाद्यथोक्तैर्वा व्यवायादिभिरन्यैर्वा व्याधिभिः पूर्वोपचितेन वा जनन्यपत्ययोः कर्मणा बन्धनान्मुच्यते गर्भः फलमिव वृन्तात् स मुक्तबन्धनो गर्भशय्यामतिक्रम्य यकृत्प्लीहान्त्रविवरैरवस्रंसमानः कोष्ठसङ्क्षोभमापादयति ततः कोष्ठसङ्क्षोभाद्वायुरपानो मूढः कुक्षिबस्तिपार्श्वोदरयोनिशूलानाहविण्मूत्रसङ्गानापाद्य गर्भं च्यावयति तरुणं शोणितभावेन सो ऽभिहितः प्राक्", text: "yasyāḥ punaratimātradoṣopacayādyathoktairvā vyavāyādibhiranyairvā vyādhibhiḥ pūrvopacitena vā jananyapatyayoḥ karmaṇā bandhanānmucyate garbhaḥ phalamiva vṛntāt sa muktabandhano garbhaśayyāmatikramya yakṛtplīhāntravivarairavasraṃsamānaḥ koṣṭhasaṅkṣobhamāpādayati tataḥ koṣṭhasaṅkṣobhādvāyurapāno mūḍhaḥ kukṣibastipārśvodarayoniśūlānāhaviṇmūtrasaṅgānāpādya garbhaṃ cyāvayati taruṇaṃ śoṇitabhāvena so 'bhihitaḥ prāk" },
      { type: "verse", number: "27", sanskrit: "विवृद्धे तु गर्भे स्तब्धं स्तिमितं शीतमश्मगर्भमिवोदरमाभाति शूलमधिकमुपजायते न च स्पन्दते गर्भो नाव्यः प्रादुर्भवन्ति न स्रवति योनिरक्षिणी चास्याः स्रंस्येते तथा भृशमरतिपरीता व्यथते ऽन्यथा चेष्टते ताम्यति भ्राम्यति रोदित्यहर्निशं न स्वपिति पूत्युच्छवासा कृच्छ्राच्छ्रवसित्यतिकष्टं प्राणिति जक्षितीत्येवंविधां स्त्रियं मृतगर्भां विद्यात्", text: "vivṛddhe tu garbhe stabdhaṃ stimitaṃ śītamaśmagarbhamivodaramābhāti śūlamadhikamupajāyate na ca spandate garbho nāvyaḥ prādurbhavanti na sravati yonirakṣiṇī cāsyāḥ sraṃsyete tathā bhṛśamaratiparītā vyathate 'nyathā ceṣṭate tāmyati bhrāmyati rodityaharniśaṃ na svapiti pūtyucchavāsā kṛcchrācchravasityatikaṣṭaṃ prāṇiti jakṣitītyevaṃvidhāṃ striyaṃ mṛtagarbhāṃ vidyāt" },
      { type: "verse", number: "28", sanskrit: "तं तु गर्भं कदाचिदसम्यगपत्यपथमनेकधा प्रतिपन्नं विगुणेनेव वायुना षीडितं मोहितं च मूढ गर्भमित्याहुः विगुणानिलप्रतिपीडनवैचित्र्यादसङ्ख्यगतिं च", text: "taṃ tu garbhaṃ kadācidasamyagapatyapathamanekadhā pratipannaṃ viguṇeneva vāyunā ṣīḍitaṃ mohitaṃ ca mūḍha garbhamityāhuḥ viguṇānilapratipīḍanavaicitryādasaṅkhyagatiṃ ca" },
      { type: "verse", number: "29", sanskrit: "समासतस्तु त्रिविधा ग....र्ध्व तिर्यङ् न्युब्जा च संस्थानानि षुनरष्टौ तान्यत्रैवोत्तरत्र वक्ष्यन्ते", text: "samāsatastu trividhā ga....rdhva tiryaṅ nyubjā ca saṃsthānāni ṣunaraṣṭau tānyatraivottaratra vakṣyante" },
      { type: "verse", number: "30", sanskrit: "तेषु संवेष्वपि विपरीतेन्द्रियार्थामाक्षेपयोनि भ्रंशसंवरणमक्कलश्वासभ्रमाभिपन्नां शीतगात्रां पूत्युद्गारां च वर्जयेत्", text: "teṣu saṃveṣvapi viparītendriyārthāmākṣepayoni bhraṃśasaṃvaraṇamakkalaśvāsabhramābhipannāṃ śītagātrāṃ pūtyudgārāṃ ca varjayet" },
      { type: "verse", number: "31", sanskrit: "न तु क्षणमप्युपेक्षेत गर्भशल्यम् तद्धि निरुच्छ्वासीकृत्याशु जननीं हन्यात्", text: "na tu kṣaṇamapyupekṣeta garbhaśalyam taddhi nirucchvāsīkṛtyāśu jananīṃ hanyāt" },
      { type: "verse", number: "32", sanskrit: "सचेतनश्च गर्भः शस्त्रेण विदार्यमाणो विषममङ्गानि विक्षिपेत्", text: "sacetanaśca garbhaḥ śastreṇa vidāryamāṇo viṣamamaṅgāni vikṣipet" },
      { type: "verse", number: "33", sanskrit: "तस्मात्तत्सङ्गे सूत्यः प्रयतेरन् पूर्वोक्तानि च मन्त्रौषधानि प्रयुञ्जीत त्रिविधस्तु सङ्गो भवति शिरस्यंसे जघने वा", text: "tasmāttatsaṅge sūtyaḥ prayateran pūrvoktāni ca mantrauṣadhāni prayuñjīta trividhastu saṅgo bhavati śirasyaṃse jaghane vā" },
      { type: "verse", number: "34", sanskrit: "मूढगर्भस्य तु जरायुपातनसामान्यं कर्मेत्येके मन्त्रादिकर्माथर्ववेदविहितमित्येके दृष्टकर्मणा शल्यहर्त्रा शल्याहरणमित्येके", text: "mūḍhagarbhasya tu jarāyupātanasāmānyaṃ karmetyeke mantrādikarmātharvavedavihitamityeke dṛṣṭakarmaṇā śalyahartrā śalyāharaṇamityeke" },
      { type: "verse", number: "35", sanskrit: "न त्वतः कष्टतममस्ति शस्त्रकर्म यतो योनियकृत्प्लीहान्त्रगर्भशयादीनां मध्ये ताननुपहिंसता स्पर्शवता शस्त्रमवचार्यमुत्कर्षणव्यावर्तमोत्कर्तच्छेदनभेदनपीडनर्जूकरणानि चैकेन पाणिना कार्याणि", text: "na tvataḥ kaṣṭatamamasti śastrakarma yato yoniyakṛtplīhāntragarbhaśayādīnāṃ madhye tānanupahiṃsatā sparśavatā śastramavacāryamutkarṣaṇavyāvartamotkartacchedanabhedanapīḍanarjūkaraṇāni caikena pāṇinā kāryāṇi" },
      { type: "verse", number: "36", sanskrit: "तस्मादीश्वरमापृच्छ्य परं च यत्नमास्थाय तद्विद्यसहितस्तमुपक्रमेत् अक्रियायां ध्रुवं मरणम् उपक्रमे संशयः तथोदराश्मरीप्रभृतीनपि", text: "tasmādīśvaramāpṛcchya paraṃ ca yatnamāsthāya tadvidyasahitastamupakramet akriyāyāṃ dhruvaṃ maraṇam upakrame saṃśayaḥ tathodarāśmarīprabhṛtīnapi" },
      { type: "verse", number: "37", sanskrit: "अथोत्तानाया व्याभुग्नसक्थ्या वस्त्रचुम्बलोन्नमितकटिप्रदेशायाश्च धन्वनागवृन्तिकाशाल्मलीपिच्छाघृतैरभ्यज्य हस्तं योनिं च गर्भमाहरेत्", text: "athottānāyā vyābhugnasakthyā vastracumbalonnamitakaṭipradeśāyāśca dhanvanāgavṛntikāśālmalīpicchāghṛtairabhyajya hastaṃ yoniṃ ca garbhamāharet" },
      { type: "verse", number: "38", sanskrit: "तत्र सक्थिभ्यामागतस्यानुलोममाञ्छनमेव एकसक्थिप्रपन्नस्येतरं सक्थिः प्रसार्य स्फिग्देशागतस्य स्फिग्देशं प्रतिषिध्योर्ध्वमुत्क्षिप्य सक्थिनी प्रसार्य तिर्यगागतस्य परिघस्येवापरार्धमुत्क्षिप्य पूर्वार्धमपत्यपथं प्रत्यार्जवमानीय पार्श्वापवृत्तशिरसो ऽसं प्रतिपीड्योर्ध्वमुत्क्षिप्य शिरोपत्यपथमानीय बाहुद्वयप्रपन्नस्योर्ध्वमुत्पीड्यासौ शिरोमूअमानीय", text: "tatra sakthibhyāmāgatasyānulomamāñchanameva ekasakthiprapannasyetaraṃ sakthiḥ prasārya sphigdeśāgatasya sphigdeśaṃ pratiṣidhyordhvamutkṣipya sakthinī prasārya tiryagāgatasya parighasyevāparārdhamutkṣipya pūrvārdhamapatyapathaṃ pratyārjavamānīya pārśvāpavṛttaśiraso 'saṃ pratipīḍyordhvamutkṣipya śiropatyapathamānīya bāhudvayaprapannasyordhvamutpīḍyāsau śiromūamānīya" },
      { type: "verse", number: "39", sanskrit: "यस्त्वाभुग्नमध्यः पाणिपादशिरोभिर्योनिं प्रतिपद्यते यश्चाभुग्न एवैकेन पादेन योनिं द्वितीयेन पायुम् तौ मूढौ हस्तेनाहर्तुमशक्याविति शस्त्रमवचारयेत्", text: "yastvābhugnamadhyaḥ pāṇipādaśirobhiryoniṃ pratipadyate yaścābhugna evaikena pādena yoniṃ dvitīyena pāyum tau mūḍhau hastenāhartumaśakyāviti śastramavacārayet" },
      { type: "verse", number: "40", sanskrit: "अथ स्त्रियमाश्वास्य मण्डलाग्रेणाङ्गुलिशस्त्रेण वा विदार्य शिरः कपालान्याहृत्य गर्भशङ्कुना गृहीत्वा चिबुके तालुन्युरसि कक्ष्यायां वापहरेत् अभिन्नशिरसं चाक्षिकूटे वा तथांससक्तस्यांसदेशे बाहुं छित्वा दृतेरिवाध्मातस्य वातपूर्णमुदरमवदार्य निरस्यान्त्राणि शिथिलीभूतमाहरेत् जघनसक्तस्य जघनकपालानि दारयित्वेति", text: "atha striyamāśvāsya maṇḍalāgreṇāṅguliśastreṇa vā vidārya śiraḥ kapālānyāhṛtya garbhaśaṅkunā gṛhītvā cibuke tālunyurasi kakṣyāyāṃ vāpaharet abhinnaśirasaṃ cākṣikūṭe vā tathāṃsasaktasyāṃsadeśe bāhuṃ chitvā dṛterivādhmātasya vātapūrṇamudaramavadārya nirasyāntrāṇi śithilībhūtamāharet jaghanasaktasya jaghanakapālāni dārayitveti" },
      { type: "verse", number: "41", sanskrit: "अपि च यद्यद्वायुवशादङ्गं सज्जेद्गर्भस्य खण्डशः तत्तच्छित्वा हरेत्सम्यग्रक्षन्नारीं च यत्नतः", text: "api ca yadyadvāyuvaśādaṅgaṃ sajjedgarbhasya khaṇḍaśaḥ tattacchitvā haretsamyagrakṣannārīṃ ca yatnataḥ" },
      { type: "verse", number: "42", sanskrit: "अथापतन्तीमपरां पातयेत् पूर्ववद्भिषक् एवं निर्हृतशल्यां तु सिञ्चेदुष्णेन वारिणा", text: "athāpatantīmaparāṃ pātayet pūrvavadbhiṣak evaṃ nirhṛtaśalyāṃ tu siñceduṣṇena vāriṇā" },
      { type: "verse", number: "43", sanskrit: "दद्यादभ्यक्तदेहायै योनौ स्नेहपिचुं ततः योनिर्मृदुर्भवेत्तेन शूलं चास्याः प्रशाम्यति", text: "dadyādabhyaktadehāyai yonau snehapicuṃ tataḥ yonirmṛdurbhavettena śūlaṃ cāsyāḥ praśāmyati" },
      { type: "verse", number: "44", sanskrit: "दीप्यकातिविषारास्नाहिङ्ग्वेलापञ्चकोलकात् चूर्णं स्नेहेन कल्कं वा क्वाथं वा पाययेत्ततः", text: "dīpyakātiviṣārāsnāhiṅgvelāpañcakolakāt cūrṇaṃ snehena kalkaṃ vā kvāthaṃ vā pāyayettataḥ" },
      { type: "verse", number: "45", sanskrit: "कटुकातिविषापाठाशाकत्वग्धिङ्गुतैजनीः तद्वच्च दोषस्यन्दार्थं वेदनोपशमाय च", text: "kaṭukātiviṣāpāṭhāśākatvagdhiṅgutaijanīḥ tadvacca doṣasyandārthaṃ vedanopaśamāya ca" },
      { type: "verse", number: "46", sanskrit: "त्रिरात्रमेवं सप्ताहं स्नेहमेव ततः पिबेत् सायं पिबेदरिष्टं च तथा सुकृतमासवम्", text: "trirātramevaṃ saptāhaṃ snehameva tataḥ pibet sāyaṃ pibedariṣṭaṃ ca tathā sukṛtamāsavam" },
      { type: "verse", number: "47", sanskrit: "शिरीषककुभक्वाथपिचून्योनौ च निक्षिपेत्", text: "śirīṣakakubhakvāthapicūnyonau ca nikṣipet" },
      { type: "verse", number: "48", sanskrit: "उपद्रवाश्च ये ऽन्ये स्युस्तान्यथास्वमुपाचरेत् पयो वातहरैः सिद्धं दशाहं भोजने हितम्", text: "upadravāśca ye 'nye syustānyathāsvamupācaret payo vātaharaiḥ siddhaṃ daśāhaṃ bhojane hitam" },
      { type: "verse", number: "49", sanskrit: "रसो दशाहं च परं लघुपथ्याल्पभोजना", text: "raso daśāhaṃ ca paraṃ laghupathyālpabhojanā" },
      { type: "verse", number: "50", sanskrit: "स्नेहाभ्यङ्गपरा स्नेहान बलातैलादिकान् भजेत् ऊर्ध्वं चतुर्भ्यो मासेभ्यः सा क्रमेण सुखानि च", text: "snehābhyaṅgaparā snehāna balātailādikān bhajet ūrdhvaṃ caturbhyo māsebhyaḥ sā krameṇa sukhāni ca" },
      { type: "verse", number: "51", sanskrit: "अथ बलातैलमुपदेक्ष्यामः बलामूलकषायस्य भागाः षट् तावन्त एव पयसो यवकोलकुलत्थदशमूलकषायस्य भागो भागश्चतुर्दशस्तैलस्य तत्सर्वमैकध्यं कृत्वा श्लक्ष्णपिष्टानि चावाप्य काकोलीक्षीरकाकोलीजीवकर्षभकमुद्गपर्णीमाषपर्णी मोदामहामेदाक्षीरशुक्लामधुकदेवदारुमञ्जिष्ठाचन्दनसारिवातगरकुष्ठशतावर्यश्वगन्धापुनर्नवाशतपुष्पावरापत्ररससरलशैलेयैलावचागरुकालानुसारीसैन्धवानि शनैर्मृद्वग्निना साधयित्वा सुभाजने ऽनुगुप्तं निदध्यादेष भगवतो धन्वन्तरेरभिमतस्तैलराजो राज्ञां राजमात्राणां सूतिकानां कृशानां शिशूनामतीतवयसां सुकुमाराणां शूलिनां महाग्रहगृहीतानां दीर्घरोगक्षपितवपुषां मर्मविद्धपतिताभिहतभग्नविश्लिष्टदेहानां दैवोपघाताभिशप्तमनोज्वरपरीतानां पाननावनाभ्यङ्गबस्तिषु प्रयोज्यः तेन बलपौरुषस्मृतिमतिमेधाग्निवीर्यौजांसि विवर्धन्ते पक्षाघाताक्षेपकार्दितादिविविधवातविकारगुल्महिक्काश्वासकासा निवर्तन्ते अहरहश्चोपयुज्यमाने षण्मासादान्त्रवृद्धिः प्रशाम्यति च वन्ध्या च पुत्रं गुणवन्तमिच्छया लभत इति भवन्ति चात्र", text: "atha balātailamupadekṣyāmaḥ balāmūlakaṣāyasya bhāgāḥ ṣaṭ tāvanta eva payaso yavakolakulatthadaśamūlakaṣāyasya bhāgo bhāgaścaturdaśastailasya tatsarvamaikadhyaṃ kṛtvā ślakṣṇapiṣṭāni cāvāpya kākolīkṣīrakākolījīvakarṣabhakamudgaparṇīmāṣaparṇī modāmahāmedākṣīraśuklāmadhukadevadārumañjiṣṭhācandanasārivātagarakuṣṭhaśatāvaryaśvagandhāpunarnavāśatapuṣpāvarāpatrarasasaralaśaileyailāvacāgarukālānusārīsaindhavāni śanairmṛdvagninā sādhayitvā subhājane 'nuguptaṃ nidadhyādeṣa bhagavato dhanvantarerabhimatastailarājo rājñāṃ rājamātrāṇāṃ sūtikānāṃ kṛśānāṃ śiśūnāmatītavayasāṃ sukumārāṇāṃ śūlināṃ mahāgrahagṛhītānāṃ dīrgharogakṣapitavapuṣāṃ marmaviddhapatitābhihatabhagnaviśliṣṭadehānāṃ daivopaghātābhiśaptamanojvaraparītānāṃ pānanāvanābhyaṅgabastiṣu prayojyaḥ tena balapauruṣasmṛtimatimedhāgnivīryaujāṃsi vivardhante pakṣāghātākṣepakārditādivividhavātavikāragulmahikkāśvāsakāsā nivartante aharahaścopayujyamāne ṣaṇmāsādāntravṛddhiḥ praśāmyati ca vandhyā ca putraṃ guṇavantamicchayā labhata iti bhavanti cātra" },
      { type: "verse", number: "52", sanskrit: "बस्तिद्वारे विपन्नायाः कुक्षिः प्रस्पन्दते यदि जन्मकाले ततः शीघ्रं पाटयित्वोद्धरेच्छिशुम्", text: "bastidvāre vipannāyāḥ kukṣiḥ praspandate yadi janmakāle tataḥ śīghraṃ pāṭayitvoddharecchiśum" },
      { type: "verse", number: "53", sanskrit: "मधुकं शाकबीजं च पयस्या सुरदारु च अश्मन्तकः कृष्णतिलास्ताम्रवल्ली शतावरी", text: "madhukaṃ śākabījaṃ ca payasyā suradāru ca aśmantakaḥ kṛṣṇatilāstāmravallī śatāvarī" },
      { type: "verse", number: "54", sanskrit: "वृक्षादनी पयस्या च लता चोत्पलसारिबा अनन्ता सारिवा रास्ना पद्मा च मधुयष्टिका", text: "vṛkṣādanī payasyā ca latā cotpalasāribā anantā sārivā rāsnā padmā ca madhuyaṣṭikā" },
      { type: "verse", number: "55", sanskrit: "बृहतीद्वयकाश्मर्यक्षीरिशृङ्गत्वचो घृतम् पृश्निपर्णी बला शिग्रुः श्वदंष्ट्रा मधुपर्णिका", text: "bṛhatīdvayakāśmaryakṣīriśṛṅgatvaco ghṛtam pṛśniparṇī balā śigruḥ śvadaṃṣṭrā madhuparṇikā" },
      { type: "verse", number: "56", sanskrit: "शृङ्गाटकं बिसं द्राक्षा कशेरुमधुकं बला सप्तैतान् पयसा योगानर्धश्लोकसमापनान्", text: "śṛṅgāṭakaṃ bisaṃ drākṣā kaśerumadhukaṃ balā saptaitān payasā yogānardhaślokasamāpanān" },
      { type: "verse", number: "57", sanskrit: "क्रमात् सप्तसु मासेषु गर्भे स्रवति योजयेत् कपित्थबिल्वबृहतीपटोलेक्षुनिदिग्धिकात्", text: "kramāt saptasu māseṣu garbhe sravati yojayet kapitthabilvabṛhatīpaṭolekṣunidigdhikāt" },
      { type: "verse", number: "58", sanskrit: "मूलैः शृतं प्रयुञ्जीत क्षीरं मासे तथाष्टमे नममे सारिवानन्तापयस्यामधुयष्टिभिः", text: "mūlaiḥ śṛtaṃ prayuñjīta kṣīraṃ māse tathāṣṭame namame sārivānantāpayasyāmadhuyaṣṭibhiḥ" },
      { type: "verse", number: "59", sanskrit: "योजयेद्दशमे मासि सिद्धं क्षीरं पयस्यया अथवा यष्टिमधुकनागरामरदारुभिः", text: "yojayeddaśame māsi siddhaṃ kṣīraṃ payasyayā athavā yaṣṭimadhukanāgarāmaradārubhiḥ" },
    ],
  },
  {
    sthana: "Шарирастхана",
    number: 5,
    lang: "sa",
    content: [
      { type: "heading", heading: "Прана айатана — обители жизни" },
      { type: "text", text: "Глава 5 Шарирастханы Астанга-санграхи — «Прана айатана» — посвящена анатомическим и эмбриологическим аспектам: обители жизни." },
      { type: "verse", number: "1", sanskrit: "अथातो ऽङ्गविभागं शारीरं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto 'ṅgavibhāgaṃ śārīraṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सकलमपि शरीरमङ्गमित्युच्यते तत्र पुनः षडङ्गं शिरोन्तराधिर्द्वौ बाहू सक्थिनी च नेत्रनाभिपाणिपादादीनि त्वस्य प्रत्यङ्गानि", text: "sakalamapi śarīramaṅgamityucyate tatra punaḥ ṣaḍaṅgaṃ śirontarādhirdvau bāhū sakthinī ca netranābhipāṇipādādīni tvasya pratyaṅgāni" },
      { type: "verse", number: "3", sanskrit: "महागुणमयेभ्यश्च खपवनतेजोजलभूम्याख्येभ्यो महाभूतेभ्यश्चेतनाधिष्ठितेभ्यो ऽभिनिर्वृत्तिरङ्गस्य", text: "mahāguṇamayebhyaśca khapavanatejojalabhūmyākhyebhyo mahābhūtebhyaścetanādhiṣṭhitebhyo 'bhinirvṛttiraṅgasya" },
      { type: "verse", number: "4", sanskrit: "भूतानामेव च दृष्टादृष्टविविधकर्मवशादनेकरूपात्सन्निवेशविशेषादाकृतिप्रमाणस्नेहदीप्तिस्वरादीनां सारूप्यमसारूप्यं वा सूक्ष्मस्थूलतारतम्यभेदभिन्नमतिबहुप्रकारं निष्पद्यते", text: "bhūtānāmeva ca dṛṣṭādṛṣṭavividhakarmavaśādanekarūpātsanniveśaviśeṣādākṛtipramāṇasnehadīptisvarādīnāṃ sārūpyamasārūpyaṃ vā sūkṣmasthūlatāratamyabhedabhinnamatibahuprakāraṃ niṣpadyate" },
      { type: "verse", number: "5", sanskrit: "तत्र सत्त्वबहुलमाकाशम् रजोबहुलो वायुः उभयबहुलो ऽग्निः सत्त्वतमोबहुलमम्बु तमोबहुला भूः तेषामप्रतिघातश्चलत्वमौष्ण्यं द्रवता काठिन्यमिति क्रमाल्लिङ्गानि विशेषतश्च श्रोत्रादिष्विन्द्रियेष्ववस्थानम् शब्दस्पर्शरूपरसगन्धैरेकैकप्रवृद्धैरन्वयः", text: "tatra sattvabahulamākāśam rajobahulo vāyuḥ ubhayabahulo 'gniḥ sattvatamobahulamambu tamobahulā bhūḥ teṣāmapratighātaścalatvamauṣṇyaṃ dravatā kāṭhinyamiti kramālliṅgāni viśeṣataśca śrotrādiṣvindriyeṣvavasthānam śabdasparśarūparasagandhairekaikapravṛddhairanvayaḥ" },
      { type: "verse", number: "6", sanskrit: "तत्राकाशजानि श्रोत्रं शब्दः सर्वस्रोतांसि विविक्ता च वायवीयानि स्पर्शनं स्पर्शः प्रश्वासोच्छ्वासादिपरिस्पन्दनानि लाघवं च आग्नेयानि दर्शनं रूपं पित्तमूष्मा पक्तिः सन्तापो मेधा वर्णो भास्तेजः शौर्यं च आम्भसानि रसनं रसः स्वेदक्लेदवसारसासृक्शुक्रमूत्रादिद्रवसमूहः शैत्यं स्नेहश्च पार्थिवानि घ्राणं गन्धः केशनखास्थ्यादिमूर्तसमूहो धैर्यं स्थैर्यं च", text: "tatrākāśajāni śrotraṃ śabdaḥ sarvasrotāṃsi viviktā ca vāyavīyāni sparśanaṃ sparśaḥ praśvāsocchvāsādiparispandanāni lāghavaṃ ca āgneyāni darśanaṃ rūpaṃ pittamūṣmā paktiḥ santāpo medhā varṇo bhāstejaḥ śauryaṃ ca āmbhasāni rasanaṃ rasaḥ svedakledavasārasāsṛkśukramūtrādidravasamūhaḥ śaityaṃ snehaśca pārthivāni ghrāṇaṃ gandhaḥ keśanakhāsthyādimūrtasamūho dhairyaṃ sthairyaṃ ca" },
      { type: "verse", number: "7", sanskrit: "तेषु मातृजानि मृदूनि त्वग्रक्तमांसमेदोमज्जनाभिहृदयामाशयगर्भशययकृत्प्लीहाक्लोमान्त्रगुदादीनि", text: "teṣu mātṛjāni mṛdūni tvagraktamāṃsamedomajjanābhihṛdayāmāśayagarbhaśayayakṛtplīhāklomāntragudādīni" },
      { type: "verse", number: "8", sanskrit: "षितृजानि स्थिराणि केशनखास्थिशुक्रसिरास्नाय्वादीनि", text: "ṣitṛjāni sthirāṇi keśanakhāsthiśukrasirāsnāyvādīni" },
      { type: "verse", number: "9", sanskrit: "आत्मजानि नानायोनिषूत्पत्तिर्मनश्चेतनेन्द्रियाणि प्राणापानौ धारणमाकृतिस्वरवर्णविशेषाः कामक्रोधलोभभयहर्षधर्मार्धमशीलतास्मृतिबुद्धीच्छाद्वेषप्रयत्नाहङ्कारसुखदुःखायुरात्मज्ञानानि च", text: "ātmajāni nānāyoniṣūtpattirmanaścetanendriyāṇi prāṇāpānau dhāraṇamākṛtisvaravarṇaviśeṣāḥ kāmakrodhalobhabhayaharṣadharmārdhamaśīlatāsmṛtibuddhīcchādveṣaprayatnāhaṅkārasukhaduḥkhāyurātmajñānāni ca" },
      { type: "verse", number: "10", sanskrit: "सात्म्यजान्यायुरारोग्यमनालस्यलोलुपत्वमिन्द्रियप्रसादस्वरवर्णौजःसम्पत्प्रशस्तता प्रहर्षभूयस्त्वं मेधाबलं च", text: "sātmyajānyāyurārogyamanālasyalolupatvamindriyaprasādasvaravarṇaujaḥsampatpraśastatā praharṣabhūyastvaṃ medhābalaṃ ca" },
      { type: "verse", number: "11", sanskrit: "रसजानि कृत्स्नस्य देहस्य सम्भवो वृत्तिर्वृद्धिस्तृप्तिरलौल्यं पुष्टिरुत्साहश्च", text: "rasajāni kṛtsnasya dehasya sambhavo vṛttirvṛddhistṛptiralaulyaṃ puṣṭirutsāhaśca" },
      { type: "verse", number: "12", sanskrit: "शुद्धसत्त्वजानि शौचमास्तिकत्वं कृत्ज्ञता दाक्षिण्यं व्यवसायः शौर्यं गाम्भीर्यं बुद्धिर्मेधा स्मृतिः शुक्लवर्त्मरुचिर्भाक्तिराभिषङ्गाभावस्तमोगुणविपर्ययश्च", text: "śuddhasattvajāni śaucamāstikatvaṃ kṛtjñatā dākṣiṇyaṃ vyavasāyaḥ śauryaṃ gāmbhīryaṃ buddhirmedhā smṛtiḥ śuklavartmarucirbhāktirābhiṣaṅgābhāvastamoguṇaviparyayaśca" },
      { type: "verse", number: "13", sanskrit: "राजसानि दुरुपचारता ऽनार्यं शौर्यं मात्सर्यममितभाषित्वमहङ्कारो लोलुपत्वं दम्भो मानः क्रोधो हर्षः कामश्च", text: "rājasāni durupacāratā 'nāryaṃ śauryaṃ mātsaryamamitabhāṣitvamahaṅkāro lolupatvaṃ dambho mānaḥ krodho harṣaḥ kāmaśca" },
      { type: "verse", number: "14", sanskrit: "तामसान्यज्ञानं विषादः प्रमादो निद्रालस्यं क्षुत्तृष्णा शोको मात्सर्यं विप्रतिपत्तिः परातिसन्धानं सत्त्वगुणवैपरीत्यं च", text: "tāmasānyajñānaṃ viṣādaḥ pramādo nidrālasyaṃ kṣuttṛṣṇā śoko mātsaryaṃ vipratipattiḥ parātisandhānaṃ sattvaguṇavaiparītyaṃ ca" },
      { type: "verse", number: "15", sanskrit: "तत्र सत्त्वं मनस्तस्योषप्लवो रजस्तमश्चेत्येवं भूतात्मकं देहमाहुः", text: "tatra sattvaṃ manastasyoṣaplavo rajastamaścetyevaṃ bhūtātmakaṃ dehamāhuḥ" },
      { type: "verse", number: "16", sanskrit: "तस्य पुनः प्रविभागः त्वचः कला दोषा धातवो मला बुद्धीन्द्रियाणि तदधिष्ठितानि कर्मेन्द्रियाण्यतीन्द्रियमाशयाः प्राणायतनानि कण्डराजालानि कूर्चारज्जवस्सीवन्यो ऽस्थिसङ्घाताःसीमन्ता अस्थीन्यस्थिसन्धयः स्नायूनि पेश्यस्सिराधमन्यस्स्रोतांस्यूष्माणो मर्माणि केशश्मश्नुलोमानि प्रकृतिविकृतिभेदाश्च तत्रासृजः पच्यमानस्य क्षीरस्येव सन्तानिकाः षट् त्वचो भवन्ति त्वक्प्रसादाद्रक्तस्य प्रसादः", text: "tasya punaḥ pravibhāgaḥ tvacaḥ kalā doṣā dhātavo malā buddhīndriyāṇi tadadhiṣṭhitāni karmendriyāṇyatīndriyamāśayāḥ prāṇāyatanāni kaṇḍarājālāni kūrcārajjavassīvanyo 'sthisaṅghātāḥsīmantā asthīnyasthisandhayaḥ snāyūni peśyassirādhamanyassrotāṃsyūṣmāṇo marmāṇi keśaśmaśnulomāni prakṛtivikṛtibhedāśca tatrāsṛjaḥ pacyamānasya kṣīrasyeva santānikāḥ ṣaṭ tvaco bhavanti tvakprasādādraktasya prasādaḥ" },
      { type: "verse", number: "17", sanskrit: "तासामुदकधरा चाद्या द्वितीया ऽसृग्धरा तृतीया सिध्मकिलासाधिष्ठाना चतुर्थी सर्वकुष्ठाधिष्ठाना पञ्चमी पुनरलजीविद्रध्यधिष्ठाना षष्ठी तु प्राणधरा यस्यां छिन्नायां ताम्यत्यन्धमिव च तमः प्रविशति यां चाधिष्ठायारूपंषि जायन्ते पर्वसु कृष्णरक्तानि स्थूलमूलानि दुश्चिकित्स्यतमानि", text: "tāsāmudakadharā cādyā dvitīyā 'sṛgdharā tṛtīyā sidhmakilāsādhiṣṭhānā caturthī sarvakuṣṭhādhiṣṭhānā pañcamī punaralajīvidradhyadhiṣṭhānā ṣaṣṭhī tu prāṇadharā yasyāṃ chinnāyāṃ tāmyatyandhamiva ca tamaḥ praviśati yāṃ cādhiṣṭhāyārūpaṃṣi jāyante parvasu kṛṣṇaraktāni sthūlamūlāni duścikitsyatamāni" },
      { type: "verse", number: "18", sanskrit: "अन्ये सप्त त्वचो वदन्ति तत्र प्रथमा भासिनी नाम या वर्णानामवभासिनी खादीनाञ्च षञ्चानां छायानां सा व्रीहेरष्टादशभागप्रमाणा द्वितीया लोहिनी नाम षोडशभागप्रमाणा तृतीया श्वेता नाम द्वादशभागप्रमाणा चतुर्थी ताम्रा नामाष्टभागप्रमाणा पञ्चमी वेदिनी नाम पञ्चभागप्रमाणा षष्ठी रोहिणी नाम व्रीहिप्रमाणा सप्तमी मांसधरा नाम व्रीहिद्वयप्रमाणा", text: "anye sapta tvaco vadanti tatra prathamā bhāsinī nāma yā varṇānāmavabhāsinī khādīnāñca ṣañcānāṃ chāyānāṃ sā vrīheraṣṭādaśabhāgapramāṇā dvitīyā lohinī nāma ṣoḍaśabhāgapramāṇā tṛtīyā śvetā nāma dvādaśabhāgapramāṇā caturthī tāmrā nāmāṣṭabhāgapramāṇā pañcamī vedinī nāma pañcabhāgapramāṇā ṣaṣṭhī rohiṇī nāma vrīhipramāṇā saptamī māṃsadharā nāma vrīhidvayapramāṇā" },
      { type: "verse", number: "19", sanskrit: "यस्तु धात्वाशयान्तरेषु क्लेदो ऽवतिष्ठते स यथास्वमूष्मभिर्विपक्वः स्नायुश्लेष्मजरायुच्छन्नः काष्ठ इव सारो धातुसारशेषो रसशेषोल्पत्वात् कलासंज्ञः ता धात्वाशयान्तरमर्यादाः सप्त कलाः", text: "yastu dhātvāśayāntareṣu kledo 'vatiṣṭhate sa yathāsvamūṣmabhirvipakvaḥ snāyuśleṣmajarāyucchannaḥ kāṣṭha iva sāro dhātusāraśeṣo rasaśeṣolpatvāt kalāsaṃjñaḥ tā dhātvāśayāntaramaryādāḥ sapta kalāḥ" },
      { type: "verse", number: "20", sanskrit: "तासां प्रथमा मांसधरा नाम यस्यां मांसे सिरास्नायुधमनीस्रोतसां भूमाविव पङ्कोदकेन बिसमृणालानां प्रतानानि भवन्ति", text: "tāsāṃ prathamā māṃsadharā nāma yasyāṃ māṃse sirāsnāyudhamanīsrotasāṃ bhūmāviva paṅkodakena bisamṛṇālānāṃ pratānāni bhavanti" },
      { type: "verse", number: "21", sanskrit: "द्वितीया रक्तधरा नाम मांसस्याभ्यन्तरतस्तस्यां शोणितं विशेषतश्च सिराप्लीहयकृत्सु भवति मांसाच्च क्षतात् क्षतजं वृक्षादिव क्षीरिणः क्षीरं प्रवर्तते", text: "dvitīyā raktadharā nāma māṃsasyābhyantaratastasyāṃ śoṇitaṃ viśeṣataśca sirāplīhayakṛtsu bhavati māṃsācca kṣatāt kṣatajaṃ vṛkṣādiva kṣīriṇaḥ kṣīraṃ pravartate" },
      { type: "verse", number: "22", sanskrit: "तृतीया मेदोधरा नाम मेदो हि तस्यामुदरे ऽण्वस्थिषु च सरक्तं भवति तदेव च शिरसि कपालप्रतिच्छन्नं मस्तिष्काख्यं मस्तुलुङ्गाख्यं च स्थूलास्थिषु च मज्जा चतुर्थी श्लेष्मधरा नाम तत्स्थेन हि श्लेष्मणा श्लेषिताः सर्वसन्धयो दृढा भवन्ति सोपाङ्गा इवाक्षाः पञ्चमी पुरीषधरा नाम सा ह्यत्रामपक्वाशयाश्रिता कोष्ठान्तरुण्डुकस्थं मलं विभजति", text: "tṛtīyā medodharā nāma medo hi tasyāmudare 'ṇvasthiṣu ca saraktaṃ bhavati tadeva ca śirasi kapālapraticchannaṃ mastiṣkākhyaṃ mastuluṅgākhyaṃ ca sthūlāsthiṣu ca majjā caturthī śleṣmadharā nāma tatsthena hi śleṣmaṇā śleṣitāḥ sarvasandhayo dṛḍhā bhavanti sopāṅgā ivākṣāḥ pañcamī purīṣadharā nāma sā hyatrāmapakvāśayāśritā koṣṭhāntaruṇḍukasthaṃ malaṃ vibhajati" },
      { type: "verse", number: "23", sanskrit: "षष्ठी पित्तधरा नाम पक्वामाशयमध्यस्था सा ह्यन्तरग्नेराधिष्ठानतयामाशयात् पक्वाशयोन्मुखमन्नं बलेन विधार्य पित्ततेजसा शोषयति पचति पक्वं च विमुञ्चति दोषाधिष्ठिता तु दौर्बल्यादाममेव ततो ऽसावन्नस्य ग्रहणात् पुनर्ग्रहणीसंज्ञा बलं च तस्याः पित्तमेवाग्न्यभिधानमतः साग्निनोपस्तब्धोपबृंहितैकयोगक्षेमा शरीरं वर्तयति", text: "ṣaṣṭhī pittadharā nāma pakvāmāśayamadhyasthā sā hyantaragnerādhiṣṭhānatayāmāśayāt pakvāśayonmukhamannaṃ balena vidhārya pittatejasā śoṣayati pacati pakvaṃ ca vimuñcati doṣādhiṣṭhitā tu daurbalyādāmameva tato 'sāvannasya grahaṇāt punargrahaṇīsaṃjñā balaṃ ca tasyāḥ pittamevāgnyabhidhānamataḥ sāgninopastabdhopabṛṃhitaikayogakṣemā śarīraṃ vartayati" },
      { type: "verse", number: "24", sanskrit: "सप्तमी शुक्रधरा नाम द्व्यङ्गुले दक्षिणे पार्ण्वे बस्तिद्वारस्याधो मूत्रमार्गमाश्रिता सकलशरीरव्यापिनी शुक्रं प्रवर्तयति", text: "saptamī śukradharā nāma dvyaṅgule dakṣiṇe pārṇve bastidvārasyādho mūtramārgamāśritā sakalaśarīravyāpinī śukraṃ pravartayati" },
      { type: "verse", number: "25", sanskrit: "दोषा धातवो मलाश्च प्रागुदिताः पञ्च बुद्धीन्द्रियाणि श्रोत्रं स्पर्शनं दर्शनं रसनं घ्राणं च तेषां सभागतया क्रमाद्विषयाः शब्दस्पर्शरूपरसगन्धाः पञ्चबुद्धीन्द्रियाधिष्ठानानि कर्णौ त्वगक्षिणी जिह्वा नासिके च", text: "doṣā dhātavo malāśca prāguditāḥ pañca buddhīndriyāṇi śrotraṃ sparśanaṃ darśanaṃ rasanaṃ ghrāṇaṃ ca teṣāṃ sabhāgatayā kramādviṣayāḥ śabdasparśarūparasagandhāḥ pañcabuddhīndriyādhiṣṭhānāni karṇau tvagakṣiṇī jihvā nāsike ca" },
      { type: "verse", number: "26", sanskrit: "पञ्च कर्मेन्दिर्याणि वाक्पायूपस्थपाणिपादसंज्ञकानि तान्यपि च वचनोत्सर्गहर्षादानगमनार्थानि", text: "pañca karmendiryāṇi vākpāyūpasthapāṇipādasaṃjñakāni tānyapi ca vacanotsargaharṣādānagamanārthāni" },
      { type: "verse", number: "27", sanskrit: "अतीन्द्रियं तु मनः सर्वार्थैरन्वयात् तद्योगेन पञ्चेन्द्रियाणामर्थप्रवृत्तेः बुद्धिकर्मेन्द्रियोभयात्मकत्वाच्च", text: "atīndriyaṃ tu manaḥ sarvārthairanvayāt tadyogena pañcendriyāṇāmarthapravṛtteḥ buddhikarmendriyobhayātmakatvācca" },
      { type: "verse", number: "28", sanskrit: "सप्ताशयः क्रमादसृक्कफामपित्तपक्ववायुमूत्राधाराः स्त्रीणां पित्तपक्वाशययोर्मध्ये गर्भाशयो ऽष्टमः तेषु सप्तसु प्रतिबद्धानि कोष्ठाङ्गानि हृदययकृत्प्लीहफुफ्फुसोण्डुकवृक्कान्त्रादीनि तत्र समानेनाध्मायमानस्य देहोष्मणा पच्यमानस्य शोणितस्याच्छतो जायते यकृत् प्लीहा च रक्तफेनात् फुफ्फुसम् रक्तकिट्टादुण्डुकः रक्तमेदःप्रसादाद् वृक्कौ रक्तमांसप्रसादादान्त्राणि तानि सार्धत्रिव्यामानि पुंसाम् त्रिव्यामानि स्रीणाम् रक्तस्यानिलयोगात् कालीयम् हृदयं पुनः श्लेष्मरक्तप्रसादात् सम्भवति पद्मकोशसङ्काशं सुषिरमधोमुखम् तद्विशेषेण चेतनायाः स्थानं सर्वभावानां च चेतनानुगतानाम् तस्य वामपार्ण्वे प्लीहा फुफ्फुसश्च दक्षिणतो यकृत् क्लोम च", text: "saptāśayaḥ kramādasṛkkaphāmapittapakvavāyumūtrādhārāḥ strīṇāṃ pittapakvāśayayormadhye garbhāśayo 'ṣṭamaḥ teṣu saptasu pratibaddhāni koṣṭhāṅgāni hṛdayayakṛtplīhaphuphphusoṇḍukavṛkkāntrādīni tatra samānenādhmāyamānasya dehoṣmaṇā pacyamānasya śoṇitasyācchato jāyate yakṛt plīhā ca raktaphenāt phuphphusam raktakiṭṭāduṇḍukaḥ raktamedaḥprasādād vṛkkau raktamāṃsaprasādādāntrāṇi tāni sārdhatrivyāmāni puṃsām trivyāmāni srīṇām raktasyānilayogāt kālīyam hṛdayaṃ punaḥ śleṣmaraktaprasādāt sambhavati padmakośasaṅkāśaṃ suṣiramadhomukham tadviśeṣeṇa cetanāyāḥ sthānaṃ sarvabhāvānāṃ ca cetanānugatānām tasya vāmapārṇve plīhā phuphphusaśca dakṣiṇato yakṛt kloma ca" },
      { type: "verse", number: "29", sanskrit: "तथा कफरक्तवाहिनां स्रोतसां महाभूतानां च प्रसादादिन्द्रियाणि तेष्वपि च नेत्रे श्लेष्मणः प्रसादाच्छुक्लमण्डलं तत् पितृजम् असृजः कृष्णमण्डलं तन्मातृजम् मध्ये दृष्टिमण्डलं तदुभयात्मकम्", text: "tathā kapharaktavāhināṃ srotasāṃ mahābhūtānāṃ ca prasādādindriyāṇi teṣvapi ca netre śleṣmaṇaḥ prasādācchuklamaṇḍalaṃ tat pitṛjam asṛjaḥ kṛṣṇamaṇḍalaṃ tanmātṛjam madhye dṛṣṭimaṇḍalaṃ tadubhayātmakam" },
      { type: "verse", number: "30", sanskrit: "पक्ष्मवत्मर्शुक्लकृष्णदृष्ट्याख्यानि पञ्च मण्डलानि तत्सन्धयश्चत्वारः द्वौ चापाङ्गकनीनयोः इति ते षट् षट् च पटलानि द्वे वर्त्मनी बाह्यं चाश्रितमग्न्यम्भसी द्वितीयं मांसं तृतीयं मेदश्चतुर्थमस्थि तेषां बहलता दृष्टेः पञ्चमांशेन", text: "pakṣmavatmarśuklakṛṣṇadṛṣṭyākhyāni pañca maṇḍalāni tatsandhayaścatvāraḥ dvau cāpāṅgakanīnayoḥ iti te ṣaṭ ṣaṭ ca paṭalāni dve vartmanī bāhyaṃ cāśritamagnyambhasī dvitīyaṃ māṃsaṃ tṛtīyaṃ medaścaturthamasthi teṣāṃ bahalatā dṛṣṭeḥ pañcamāṃśena" },
      { type: "verse", number: "31", sanskrit: "बन्धनगुणास्तु चत्वारः सिराकण्डरामेदःकफात्मकाः श्लेष्मा तु परं सर्वसन्धिबन्धनमित्युक्तं प्राक् नेत्राश्रितं तु तेजो बाह्यतेजसा स्वयोनिना योगाच्छस्त्रमिवाश्मना कर्मण्यं भवति अतियोगादुपहन्यते तच्च वैद्युतवद् बडवामुखवच्चाम्भोमध्यगमपि वीर्योत्कर्षात्तेजस्त्वं न जहाति मांसासृक्कफप्रसादात्तु जिह्वा जायते मांसासृक्कफमेदःप्रसादाद् वृषणाविति", text: "bandhanaguṇāstu catvāraḥ sirākaṇḍarāmedaḥkaphātmakāḥ śleṣmā tu paraṃ sarvasandhibandhanamityuktaṃ prāk netrāśritaṃ tu tejo bāhyatejasā svayoninā yogācchastramivāśmanā karmaṇyaṃ bhavati atiyogādupahanyate tacca vaidyutavad baḍavāmukhavaccāmbhomadhyagamapi vīryotkarṣāttejastvaṃ na jahāti māṃsāsṛkkaphaprasādāttu jihvā jāyate māṃsāsṛkkaphamedaḥprasādād vṛṣaṇāviti" },
      { type: "verse", number: "32", sanskrit: "दश प्राणायतनानि मूर्धा जिह्वाबन्धनं कण्ठो हृदयं नाभिर्बस्तिर्गुदः शुक्रमोजो रक्तं च तेषामाद्यानि सप्त पुनर्महामर्मसंज्ञानि", text: "daśa prāṇāyatanāni mūrdhā jihvābandhanaṃ kaṇṭho hṛdayaṃ nābhirbastirgudaḥ śukramojo raktaṃ ca teṣāmādyāni sapta punarmahāmarmasaṃjñāni" },
      { type: "verse", number: "33", sanskrit: "षोडश कण्डराः तासां द्वे द्वे करचरणेषु चतस्रः पृथग्ग्रीवापृष्ठयोः", text: "ṣoḍaśa kaṇḍarāḥ tāsāṃ dve dve karacaraṇeṣu catasraḥ pṛthaggrīvāpṛṣṭhayoḥ" },
      { type: "verse", number: "34", sanskrit: "षोडश जालानि तेषां मांससिरास्नाय्वस्थिजानि चत्वार्येकैकत्र गुल्फे मणिबन्धे च प्रस्परगवाक्षितानि तानि स्थितानि", text: "ṣoḍaśa jālāni teṣāṃ māṃsasirāsnāyvasthijāni catvāryekaikatra gulphe maṇibandhe ca prasparagavākṣitāni tāni sthitāni" },
      { type: "verse", number: "35", sanskrit: "षट् कूर्चा हस्तपादग्रीवामेढ्रेषु", text: "ṣaṭ kūrcā hastapādagrīvāmeḍhreṣu" },
      { type: "verse", number: "36", sanskrit: "चतस्रो मांसरज्जवः पृष्ठवंशमुभयतः पेशीनिबन्धनार्यं तासां द्वे बाह्ये द्वे चाभ्यन्तरस्थिते", text: "catasro māṃsarajjavaḥ pṛṣṭhavaṃśamubhayataḥ peśīnibandhanāryaṃ tāsāṃ dve bāhye dve cābhyantarasthite" },
      { type: "verse", number: "37", sanskrit: "सप्त सीवन्यः ताः पञ्च शिरसि जिह्वामेहनयोरेकैका परिहार्याश्च शस्त्रेण", text: "sapta sīvanyaḥ tāḥ pañca śirasi jihvāmehanayorekaikā parihāryāśca śastreṇa" },
      { type: "verse", number: "38", sanskrit: "चतुर्दशास्थिसङ्घाताः तेषामेकैको गुल्फजानुवङ्क्षणमणिबन्धकूर्परकक्ष्यासु त्रिकशिरसोश्च", text: "caturdaśāsthisaṅghātāḥ teṣāmekaiko gulphajānuvaṅkṣaṇamaṇibandhakūrparakakṣyāsu trikaśirasośca" },
      { type: "verse", number: "39", sanskrit: "तद्वत् सीमन्ताः ते तु पञ्च शिरसीत्यष्टादश", text: "tadvat sīmantāḥ te tu pañca śirasītyaṣṭādaśa" },
      { type: "verse", number: "40", sanskrit: "त्रीणि षष्ट्यधिकान्यस्थिशतानि तेषां च चत्वारिंशच्छतं शाखासु सविंशं शतमन्तराधौ शतमूर्ध्वमिति तत्रैकैकस्मिन् सक्थ्नि पञ्च पादनखाः प्रत्येकमङ्ग्ल्यां त्रीण्यस्थीनि तानि पञ्चदश पञ्चपादशलाकाः तत्प्रतिबन्धकमेकम् द्वे द्वे कूर्चगुल्फजङ्घास्वेकैकं पार्ष्णिजानूरुषु सर्वाणि च नखास्थ्यादीनि सक्थिवद् बाह्वोश्च", text: "trīṇi ṣaṣṭyadhikānyasthiśatāni teṣāṃ ca catvāriṃśacchataṃ śākhāsu saviṃśaṃ śatamantarādhau śatamūrdhvamiti tatraikaikasmin sakthni pañca pādanakhāḥ pratyekamaṅglyāṃ trīṇyasthīni tāni pañcadaśa pañcapādaśalākāḥ tatpratibandhakamekam dve dve kūrcagulphajaṅghāsvekaikaṃ pārṣṇijānūruṣu sarvāṇi ca nakhāsthyādīni sakthivad bāhvośca" },
      { type: "verse", number: "41", sanskrit: "चतुर्विंशतिः परशुकाः तावन्त्येव स्थालकान्यर्बुदानि च त्रिंशत् पृष्ठे अष्टावुरसि एकैकं भागे त्रिके नितम्बयोश्च द्वे तद्वदक्षकांसांसफलकेषु", text: "caturviṃśatiḥ paraśukāḥ tāvantyeva sthālakānyarbudāni ca triṃśat pṛṣṭhe aṣṭāvurasi ekaikaṃ bhāge trike nitambayośca dve tadvadakṣakāṃsāṃsaphalakeṣu" },
      { type: "verse", number: "42", sanskrit: "तथा गण्डक्र्णशङ्खेषु जत्रुतालुनोश्च त्रयोदश ग्रीवायाम् चत्वारि कण्ठनाड्याम् द्वे हनुबन्धने द्वात्रिंशद्दन्ताः तद्वदुलूखलानि च त्रीणि नासायां षट् शिरसि", text: "tathā gaṇḍakrṇaśaṅkheṣu jatrutālunośca trayodaśa grīvāyām catvāri kaṇṭhanāḍyām dve hanubandhane dvātriṃśaddantāḥ tadvadulūkhalāni ca trīṇi nāsāyāṃ ṣaṭ śirasi" },
      { type: "verse", number: "43", sanskrit: "तानि जानुनितम्बांसगण्डतालुशङ्खवङ्क्षणमध्यशिरस्सु कपालसंज्ञानि दशनास्तु रुचकाः घ्राणकर्णग्रीवाक्षिकोशेषु तरुणानि पाणिपादपार्श्वपृष्ठेषु वलयानि शेषाणि नलकानीति नामानुगताकृतीनि पञ्चविधान्यस्थीनि तेषु हि सिराभिः स्नायुभिश्च निबद्धानि मांसानि", text: "tāni jānunitambāṃsagaṇḍatāluśaṅkhavaṅkṣaṇamadhyaśirassu kapālasaṃjñāni daśanāstu rucakāḥ ghrāṇakarṇagrīvākṣikośeṣu taruṇāni pāṇipādapārśvapṛṣṭheṣu valayāni śeṣāṇi nalakānīti nāmānugatākṛtīni pañcavidhānyasthīni teṣu hi sirābhiḥ snāyubhiśca nibaddhāni māṃsāni" },
      { type: "verse", number: "44", sanskrit: "दशोत्तरं शतद्वयमस्थिसन्धीनाम् तेषामष्टषष्टिः शाखासु एकोनषष्टिरन्तराधौ त्र्यशीतिरूर्ध्वम् तत्रैकैकस्मिन् सक्थ्नि पादाङ्गुलौ प्रत्येकं त्रयः द्वावङ्गुष्ठे ते चतुर्दश एकैको गुल्फजानुवङ्क्षणेषु", text: "daśottaraṃ śatadvayamasthisandhīnām teṣāmaṣṭaṣaṣṭiḥ śākhāsu ekonaṣaṣṭirantarādhau tryaśītirūrdhvam tatraikaikasmin sakthni pādāṅgulau pratyekaṃ trayaḥ dvāvaṅguṣṭhe te caturdaśa ekaiko gulphajānuvaṅkṣaṇeṣu" },
      { type: "verse", number: "45", sanskrit: "त्रयः कटीकपालेषु चतुर्विंशतिः पृष्ठवंशे तद्वत् पार्श्वयोः अष्टावुरसि", text: "trayaḥ kaṭīkapāleṣu caturviṃśatiḥ pṛṣṭhavaṃśe tadvat pārśvayoḥ aṣṭāvurasi" },
      { type: "verse", number: "46", sanskrit: "अष्टौ ग्रीवायाम् त्रयः कण्ठनाड्याम् अष्टदश कण्ठनाडीनिबद्धा हृदययकृत्क्लोमनाडीषु द्वात्रिंशद्दन्तमूलेषु एकैकः काकलनासामूर्द्धसु द्वौ द्वौ गण्डकर्णशङ्खवर्त्मनेत्रहनुसन्धिषु द्वावुपरिष्टात् भ्रुवोः पञ्च शिरःकपालेषु", text: "aṣṭau grīvāyām trayaḥ kaṇṭhanāḍyām aṣṭadaśa kaṇṭhanāḍīnibaddhā hṛdayayakṛtklomanāḍīṣu dvātriṃśaddantamūleṣu ekaikaḥ kākalanāsāmūrddhasu dvau dvau gaṇḍakarṇaśaṅkhavartmanetrahanusandhiṣu dvāvupariṣṭāt bhruvoḥ pañca śiraḥkapāleṣu" },
      { type: "verse", number: "47", sanskrit: "ते ऽङ्गुलिगुल्फजानुमणिबन्धकूर्परेषु कोरसंज्ञाः कक्षावङ्क्षणदन्तमूलेषूलूखलसंज्ञाः अंसपीठगुदभगनितम्बेषु सामुद्गाः ग्रीवापृष्ठवंशयोः प्रतराः शिरःकटीकपालेषु तुन्नसेवनीसंज्ञाः हनूभयतो वायसतुण्डाः कण्ठनेत्रहृदययकृत्प्लीहक्लोमनाडीषु मण्डलसंज्ञाः श्रोत्रशृङ्गाटकेषु शङ्खावर्ताः इत्यस्थिसन्धयो ऽष्टविधाः", text: "te 'ṅguligulphajānumaṇibandhakūrpareṣu korasaṃjñāḥ kakṣāvaṅkṣaṇadantamūleṣūlūkhalasaṃjñāḥ aṃsapīṭhagudabhaganitambeṣu sāmudgāḥ grīvāpṛṣṭhavaṃśayoḥ pratarāḥ śiraḥkaṭīkapāleṣu tunnasevanīsaṃjñāḥ hanūbhayato vāyasatuṇḍāḥ kaṇṭhanetrahṛdayayakṛtplīhaklomanāḍīṣu maṇḍalasaṃjñāḥ śrotraśṛṅgāṭakeṣu śaṅkhāvartāḥ ityasthisandhayo 'ṣṭavidhāḥ" },
      { type: "verse", number: "48", sanskrit: "स्नायुपेशीसिराश्रितैस्तु सहस्रद्वयं न पुनः शस्त्रप्रणिधाने तेषु वाच्यमस्तीति पृथङ् नोच्यते", text: "snāyupeśīsirāśritaistu sahasradvayaṃ na punaḥ śastrapraṇidhāne teṣu vācyamastīti pṛthaṅ nocyate" },
      { type: "verse", number: "49", sanskrit: "नव स्नायुशतानि तेषां षट् शतानि शाखासु त्रिंशच्छतद्वयमन्तराधौ ऊर्ध्वं सप्ततिः तत्रैकैकस्मिन् सक्थ्नि पादाङ्गुल्यां प्रत्येकं षट् षट् तानि त्रिंशत् दश दश पादतलकूर्चगुल्फेषु त्रिंशज्जङ्घायाम् दश जानुनि चत्वारिंशदूरौ दश वङ्क्षणे", text: "nava snāyuśatāni teṣāṃ ṣaṭ śatāni śākhāsu triṃśacchatadvayamantarādhau ūrdhvaṃ saptatiḥ tatraikaikasmin sakthni pādāṅgulyāṃ pratyekaṃ ṣaṭ ṣaṭ tāni triṃśat daśa daśa pādatalakūrcagulpheṣu triṃśajjaṅghāyām daśa jānuni catvāriṃśadūrau daśa vaṅkṣaṇe" },
      { type: "verse", number: "50", sanskrit: "चत्वारिंशत् कट्याम् विंशतिर्मुष्कमेढ्रबस्त्यन्त्रेषु अशीतिः पृष्ठे षष्टिः प्रार्श्वयोः अष्टादशोरसि चत्वार्यक्षकयोः अष्टावंसयोः", text: "catvāriṃśat kaṭyām viṃśatirmuṣkameḍhrabastyantreṣu aśītiḥ pṛṣṭhe ṣaṣṭiḥ prārśvayoḥ aṣṭādaśorasi catvāryakṣakayoḥ aṣṭāvaṃsayoḥ" },
      { type: "verse", number: "51", sanskrit: "द्वे द्वे मन्यावटुनेत्रौष्ठतालुषु त्रिंशद् ग्रीवायाम् त्रीणि जत्रुणि चत्वारि हन्वोः पञ्च जिह्वायाम् द्वादशोत्तराधरेषु दन्तमांसेषु षण्मूर्धनि", text: "dve dve manyāvaṭunetrauṣṭhatāluṣu triṃśad grīvāyām trīṇi jatruṇi catvāri hanvoḥ pañca jihvāyām dvādaśottarādhareṣu dantamāṃseṣu ṣaṇmūrdhani" },
      { type: "verse", number: "52", sanskrit: "तत्र शाखासु सन्धिषु च प्रतानवन्ति महास्नावानि तु वृत्तानि तानि कण्डरासंज्ञानि बस्त्यामपक्वाशयान्त्रेषु सुषिराणि पार्श्वपृष्ठोरश्शिरस्सु पृथूनि", text: "tatra śākhāsu sandhiṣu ca pratānavanti mahāsnāvāni tu vṛttāni tāni kaṇḍarāsaṃjñāni bastyāmapakvāśayāntreṣu suṣirāṇi pārśvapṛṣṭhoraśśirassu pṛthūni" },
      { type: "verse", number: "53", sanskrit: "स्नावबन्धनैर्हि सन्धिषु सुबद्धा तनुर्नौरिव सम्यगीहते तस्मादस्थिसिरादिभ्यो ऽपि तानि यत्नतो रक्षेत् यश्च स्नावानि बाह्यान्यभ्यन्तराणि च सम्यग् जानाति स गूढमपि शल्यमाहर्तुं समर्थो भवति", text: "snāvabandhanairhi sandhiṣu subaddhā tanurnauriva samyagīhate tasmādasthisirādibhyo 'pi tāni yatnato rakṣet yaśca snāvāni bāhyānyabhyantarāṇi ca samyag jānāti sa gūḍhamapi śalyamāhartuṃ samartho bhavati" },
      { type: "verse", number: "54", sanskrit: "पञ्च पेशीशतानि तासां चत्वारि शतानि शाखासु षष्टिरन्तराधौ चत्वारिंशदूर्ध्वम् तत्रैकैकस्मिन् सक्थ्नि पादाङ्गुल्यां प्रत्येकं तिस्रः ताः पञ्चदश दश दश प्रपदे पादतले गुल्फे च तथा पादस्योपरि कूर्चे सन्निविष्टाः विंशतिर्जङ्घायाम् पञ्च जानुनि विंशतिरूरौ", text: "pañca peśīśatāni tāsāṃ catvāri śatāni śākhāsu ṣaṣṭirantarādhau catvāriṃśadūrdhvam tatraikaikasmin sakthni pādāṅgulyāṃ pratyekaṃ tisraḥ tāḥ pañcadaśa daśa daśa prapade pādatale gulphe ca tathā pādasyopari kūrce sanniviṣṭāḥ viṃśatirjaṅghāyām pañca jānuni viṃśatirūrau" },
      { type: "verse", number: "55", sanskrit: "एकैका मेढ्रसेवन्योः द्वे वृषणयोः दश स्फिजोः तिस्रो गुदे तास्तु वलीसंज्ञाः द्वे बस्तिशिरसि चतस्र उदरे नाभ्यामेका हृद्यामाशये च षट् यकृत्प्लीहोण्डुकेषु पृष्ठे पञ्चोर्ध्वसन्निविष्टाः दश दीर्घाः पार्श्वयोः दश वक्षसि तिस्रो ऽंसाक्षकोपरितः", text: "ekaikā meḍhrasevanyoḥ dve vṛṣaṇayoḥ daśa sphijoḥ tisro gude tāstu valīsaṃjñāḥ dve bastiśirasi catasra udare nābhyāmekā hṛdyāmāśaye ca ṣaṭ yakṛtplīhoṇḍukeṣu pṛṣṭhe pañcordhvasanniviṣṭāḥ daśa dīrghāḥ pārśvayoḥ daśa vakṣasi tisro 'ṃsākṣakoparitaḥ" },
      { type: "verse", number: "56", sanskrit: "दश ग्रीवायाम् अष्टौ गण्डयोः अष्टौ हन्वोः एकैका गलकाकलजिह्वामूर्धसु द्वे द्वे तालुललाटयोः नासौष्ठकर्णेषु च", text: "daśa grīvāyām aṣṭau gaṇḍayoḥ aṣṭau hanvoḥ ekaikā galakākalajihvāmūrdhasu dve dve tālulalāṭayoḥ nāsauṣṭhakarṇeṣu ca" },
      { type: "verse", number: "57", sanskrit: "स्त्रीणां तु विंशतिरधिका तत्र दश स्तनयोः तासां यौवने परिवृद्धिर्भवति दश योनौ तासामभ्यन्तराश्रिते द्वे मुखाश्रिते वृत्ते द्वे तिस्रो गर्भमार्गाश्रयाः यस्यां गर्भस्तिष्ठति योनिस्तु शङ्खनाभ्याकृतिस्त्र्यावर्ता तस्यास्तृतीय आवर्ते पित्तपक्वाशयान्तरे गर्भशय्या तस्यां शुक्रार्तवप्रवेशिन्यस्तिस्रः पेश्यः", text: "strīṇāṃ tu viṃśatiradhikā tatra daśa stanayoḥ tāsāṃ yauvane parivṛddhirbhavati daśa yonau tāsāmabhyantarāśrite dve mukhāśrite vṛtte dve tisro garbhamārgāśrayāḥ yasyāṃ garbhastiṣṭhati yonistu śaṅkhanābhyākṛtistryāvartā tasyāstṛtīya āvarte pittapakvāśayāntare garbhaśayyā tasyāṃ śukrārtavapraveśinyastisraḥ peśyaḥ" },
      { type: "verse", number: "58", sanskrit: "ताभिर्हि शरीरे तनुबहलस्थूलाणुपृथुवृत्तह्रस्वदीर्घस्थिरमृदुश्लक्ष्णकर्कशाभिः सन्ध्यस्थिसिरास्नावानि प्रच्छादितानि", text: "tābhirhi śarīre tanubahalasthūlāṇupṛthuvṛttahrasvadīrghasthiramṛduślakṣṇakarkaśābhiḥ sandhyasthisirāsnāvāni pracchāditāni" },
      { type: "verse", number: "59", sanskrit: "सिराधमनीमुखानां त्वणुशो विभज्यमानानामेकोनत्रिंशच्छतसहस्राणि नव च शतानि षट्पञ्चाशानि भवन्ति ताभिरिदं गवाक्षितं पिनद्धमाततं च", text: "sirādhamanīmukhānāṃ tvaṇuśo vibhajyamānānāmekonatriṃśacchatasahasrāṇi nava ca śatāni ṣaṭpañcāśāni bhavanti tābhiridaṃ gavākṣitaṃ pinaddhamātataṃ ca" },
      { type: "verse", number: "60", sanskrit: "तावन्ति च केशश्मश्रुलोमानि तासां हि मुखानि तत्प्रतिबद्धान्यतस्तानि ताभिराप्याय्यन्ते तैश्च ताः स्वेदमभिवहन्ति तथाभ्यङ्गलेपादिवीर्यं त्वचि विपक्वमन्तर्नयन्ति स्पर्शं च गृह्णन्ति", text: "tāvanti ca keśaśmaśrulomāni tāsāṃ hi mukhāni tatpratibaddhānyatastāni tābhirāpyāyyante taiśca tāḥ svedamabhivahanti tathābhyaṅgalepādivīryaṃ tvaci vipakvamantarnayanti sparśaṃ ca gṛhṇanti" },
      { type: "verse", number: "61", sanskrit: "स्रोतांसि पुनरसङ्ख्येयान्येव तथापि तु सिरादीनि यथास्थूलं यथोपयोगं चान्यत्रोपदेक्ष्यन्ते इत्येवं परिसङ्ख्याताः शरीरे मूर्तिमन्तः स्थिरा भावाः", text: "srotāṃsi punarasaṅkhyeyānyeva tathāpi tu sirādīni yathāsthūlaṃ yathopayogaṃ cānyatropadekṣyante ityevaṃ parisaṅkhyātāḥ śarīre mūrtimantaḥ sthirā bhāvāḥ" },
      { type: "verse", number: "62", sanskrit: "द्रवास्तु यत्तदतियोगेन च्यवमानं पुरीषमनुबध्नाति तथा मूत्रं रुधिरमन्यांश्चशरीरे धातून् यच्च सर्वशरीरगतं बाह्या त्वग्बिभर्ति यच्च त्वगन्तरे व्रणगतं लसीकाशब्दवाच्यम् यच्चोष्मानुबद्धं रोमकूपेभ्यो ऽभिनिष्पतत्स्वेदवाच्यम् तदुदकम्", text: "dravāstu yattadatiyogena cyavamānaṃ purīṣamanubadhnāti tathā mūtraṃ rudhiramanyāṃścaśarīre dhātūn yacca sarvaśarīragataṃ bāhyā tvagbibharti yacca tvagantare vraṇagataṃ lasīkāśabdavācyam yaccoṣmānubaddhaṃ romakūpebhyo 'bhiniṣpatatsvedavācyam tadudakam" },
      { type: "verse", number: "63", sanskrit: "तस्याद्यस्य चाहारसारस्य रसाख्यस्य रक्तस्य शकृतः श्लेष्मणः पित्तस्य मूत्रस्य वसायाः मेदसो मज्ञश्च स्वेन स्वेनाञ्जलिप्रमाणेन यथापूर्वमेकादिसङ्ख्याप्रवृद्धिः अर्द्धाञ्जलिः शुक्रस्य तावदेव मस्तिष्कमोजश्च स्त्रीणां रजसो ऽञ्जलयश्चत्वारः स्तन्यस्य द्वौ उभयमपि चैतद्रसप्रसादात्मकमिति", text: "tasyādyasya cāhārasārasya rasākhyasya raktasya śakṛtaḥ śleṣmaṇaḥ pittasya mūtrasya vasāyāḥ medaso majñaśca svena svenāñjalipramāṇena yathāpūrvamekādisaṅkhyāpravṛddhiḥ arddhāñjaliḥ śukrasya tāvadeva mastiṣkamojaśca strīṇāṃ rajaso 'ñjalayaścatvāraḥ stanyasya dvau ubhayamapi caitadrasaprasādātmakamiti" },
      { type: "verse", number: "64", sanskrit: "समधातोः परिमाणमिदम् अतो वृद्धिक्षयौ यथास्वं लक्षणैर्विभावयेदपराश्चापरिसङ्ख्यातान्मूर्तामूर्तान् भावान् तद्यथा मांसकर्णादिमलान् वायुबुद्धिस्मृत्यादीश्च", text: "samadhātoḥ parimāṇamidam ato vṛddhikṣayau yathāsvaṃ lakṣaṇairvibhāvayedaparāścāparisaṅkhyātānmūrtāmūrtān bhāvān tadyathā māṃsakarṇādimalān vāyubuddhismṛtyādīśca" },
      { type: "verse", number: "65", sanskrit: "धन्वन्तरीयाः पुनः पठन्ति विलक्षणानि हि शरीराणि नित्यमेव च चला दोषधातुमलाः तस्मादुदकादीनामपि समत्वं मांसादिवत् परिमाणतो निर्देष्टुमशक्यम् केवलं स्वास्थ्यमात्रेणानुमानतो लक्षयेदिति", text: "dhanvantarīyāḥ punaḥ paṭhanti vilakṣaṇāni hi śarīrāṇi nityameva ca calā doṣadhātumalāḥ tasmādudakādīnāmapi samatvaṃ māṃsādivat parimāṇato nirdeṣṭumaśakyam kevalaṃ svāsthyamātreṇānumānato lakṣayediti" },
      { type: "verse", number: "66", sanskrit: "सर्व एव त्ववयवाः परमाणुभेदेनाति सौक्ष्म्यादसङ्ख्येयतां यान्ति तेषां संयोगविभागे परमाणूनां कर्मप्रेरितो वायुः कारणम्", text: "sarva eva tvavayavāḥ paramāṇubhedenāti saukṣmyādasaṅkhyeyatāṃ yānti teṣāṃ saṃyogavibhāge paramāṇūnāṃ karmaprerito vāyuḥ kāraṇam" },
      { type: "verse", number: "67", sanskrit: "तदेतदङ्गमभेदेन भेदतश्च गृह्यमाणं बन्धाय मोक्षाय च भवतीति भवति चात्र", text: "tadetadaṅgamabhedena bhedataśca gṛhyamāṇaṃ bandhāya mokṣāya ca bhavatīti bhavati cātra" },
      { type: "verse", number: "68", sanskrit: "इति सर्वावयवशो यो जानाति कलेवरम् अहितेषु स मोहेन न कदाचित् प्रवर्तते", text: "iti sarvāvayavaśo yo jānāti kalevaram ahiteṣu sa mohena na kadācit pravartate" },
    ],
  },
  {
    sthana: "Шарирастхана",
    number: 6,
    lang: "sa",
    content: [
      { type: "heading", heading: "Шукра шония — семя и кровь" },
      { type: "text", text: "Глава 6 Шарирастханы Астанга-санграхи — «Шукра шония» — посвящена анатомическим и эмбриологическим аспектам: семя и кровь." },
      { type: "verse", number: "1", sanskrit: "अथातः सिराविभागमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ sirāvibhāgamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "दश मूलसिरा हृदयप्रतिबद्धाः सर्वाङ्गप्रत्यङ्गेष्वोजो नयन्ति तत्प्रतिबद्धा हि शरीरचेष्टाः तास्तुद्व्यङ्गुलमङ्गुलमर्धाङ्गुलं यवं यवार्धं च गत्वा द्रुमपत्रसेवनीप्रतानवद्भिद्यमानाः सप्तशतानि भवन्ति", text: "daśa mūlasirā hṛdayapratibaddhāḥ sarvāṅgapratyaṅgeṣvojo nayanti tatpratibaddhā hi śarīraceṣṭāḥ tāstudvyaṅgulamaṅgulamardhāṅgulaṃ yavaṃ yavārdhaṃ ca gatvā drumapatrasevanīpratānavadbhidyamānāḥ saptaśatāni bhavanti" },
      { type: "verse", number: "3", sanskrit: "तासां चतुःशती शाखासु तत्र षोडशाव्यधनीयाः षट्त्रिंशं शतमन्तराधौ तत्र द्वात्रिंशत् चतुष्षष्ट्यधिकं शतमूर्ध्वम् तत्रापि पञ्चाशत्", text: "tāsāṃ catuḥśatī śākhāsu tatra ṣoḍaśāvyadhanīyāḥ ṣaṭtriṃśaṃ śatamantarādhau tatra dvātriṃśat catuṣṣaṣṭyadhikaṃ śatamūrdhvam tatrāpi pañcāśat" },
      { type: "verse", number: "4", sanskrit: "तासामेकैकस्मिन् सक्थ्नि शतम् तत्र न विध्येज्जालन्धराम् तिस्रश्चाभयन्तरगताः", text: "tāsāmekaikasmin sakthni śatam tatra na vidhyejjālandharām tisraścābhayantaragatāḥ" },
      { type: "verse", number: "5", sanskrit: "द्वात्रिंशच्छ्रोण्या गुदमेढ्राश्रयाः तासां द्वे द्वे वङ्क्षणयोः कटीकतरुणयोश्चेत्यष्टौ शस्त्रतो रक्षेत् षोडश पार्श्वयोः तयोरूर्ध्वगामेकैकां पार्श्वसन्धिसंज्ञाम् चतुर्विंशतिः पृष्ठे तासां पृष्ठवंशमुभयतो द्वे द्वे ऊर्ध्वगामिन्यौ ताश्चतस्रः चतुर्विंशतिरुदरे तासां मेढ्रस्योपरि रोमराजीमुभयतो द्वे द्वे ता अपि चतस्रः चत्वारिंशद्वक्षसि तासां द्वे हृदये द्वे द्वे च स्तनमूलस्तनरोहितेषु एकैकापस्तम्भापालापेष्विति ताश्चतुर्दश", text: "dvātriṃśacchroṇyā gudameḍhrāśrayāḥ tāsāṃ dve dve vaṅkṣaṇayoḥ kaṭīkataruṇayoścetyaṣṭau śastrato rakṣet ṣoḍaśa pārśvayoḥ tayorūrdhvagāmekaikāṃ pārśvasandhisaṃjñām caturviṃśatiḥ pṛṣṭhe tāsāṃ pṛṣṭhavaṃśamubhayato dve dve ūrdhvagāminyau tāścatasraḥ caturviṃśatirudare tāsāṃ meḍhrasyopari romarājīmubhayato dve dve tā api catasraḥ catvāriṃśadvakṣasi tāsāṃ dve hṛdaye dve dve ca stanamūlastanarohiteṣu ekaikāpastambhāpālāpeṣviti tāścaturdaśa" },
      { type: "verse", number: "6", sanskrit: "चतुर्विंशतिर्ग्रीवायाम् तासां चतस्रो ऽष्टौ च मर्मसंज्ञाः द्वे कृकाटिकयोर्द्वे विधुरयोरिति षोडश शस्त्रेण न स्पृशेत् हन्वोः षोडश तासां सन्धिसम्बन्धिन्यौ द्वे षोडश जिह्वायाम् तासामधो द्वे रसवेदिन्यौ द्वे वाक्प्रवर्तिन्यौ ताश्चतस्रः चतुर्विंशतिर्नासायाम् तासां द्वे गन्धवेदिन्यौ तासामेव च तालुन्येकामिति तिस्रः षट्पञ्चाशन्नेत्रयोः तयोरुन्मेषनिमेषक्रिये द्वे द्वे द्वे चापाङ्गयोरिति षट् नासानेत्रगतास्तु ललाटे षष्टिः तासां केशान्तानुगताश्चतस्रो द्वे चावर्तयोरेका च स्थपन्यामिति सप्त कर्णयोः षोडश तासां शब्दवाहिन्यौ द्वे त एव च शङ्खयोस्तासां शङ्खसन्धिगते द्वे द्वादश मूर्धनि तासामुत्क्षेपयोर्द्वे सीमन्तेष्वेकैकामेकामधिपतावित्यष्टौ शस्त्रेण परिहरेत् तथा क्षुद्रिकाः कुटिलाः सङ्कीर्णा ग्रथिताः सन्धिषु चाशस्त्रकृत्याः", text: "caturviṃśatirgrīvāyām tāsāṃ catasro 'ṣṭau ca marmasaṃjñāḥ dve kṛkāṭikayordve vidhurayoriti ṣoḍaśa śastreṇa na spṛśet hanvoḥ ṣoḍaśa tāsāṃ sandhisambandhinyau dve ṣoḍaśa jihvāyām tāsāmadho dve rasavedinyau dve vākpravartinyau tāścatasraḥ caturviṃśatirnāsāyām tāsāṃ dve gandhavedinyau tāsāmeva ca tālunyekāmiti tisraḥ ṣaṭpañcāśannetrayoḥ tayorunmeṣanimeṣakriye dve dve dve cāpāṅgayoriti ṣaṭ nāsānetragatāstu lalāṭe ṣaṣṭiḥ tāsāṃ keśāntānugatāścatasro dve cāvartayorekā ca sthapanyāmiti sapta karṇayoḥ ṣoḍaśa tāsāṃ śabdavāhinyau dve ta eva ca śaṅkhayostāsāṃ śaṅkhasandhigate dve dvādaśa mūrdhani tāsāmutkṣepayordve sīmanteṣvekaikāmekāmadhipatāvityaṣṭau śastreṇa pariharet tathā kṣudrikāḥ kuṭilāḥ saṅkīrṇā grathitāḥ sandhiṣu cāśastrakṛtyāḥ" },
      { type: "verse", number: "7", sanskrit: "तासां यथास्वं तुर्यांशविभागेन पञ्चसप्तत्यधिकं शतमनिलरक्तं वहति एष विभागः पित्तश्लेष्मशुद्धरक्तेष्वपि स्थिता ह्येवं देहमनुगृह्णन्ति दोषाः व्यत्ययेन तु पीडयन्ति", text: "tāsāṃ yathāsvaṃ turyāṃśavibhāgena pañcasaptatyadhikaṃ śatamanilaraktaṃ vahati eṣa vibhāgaḥ pittaśleṣmaśuddharakteṣvapi sthitā hyevaṃ dehamanugṛhṇanti doṣāḥ vyatyayena tu pīḍayanti" },
      { type: "verse", number: "8", sanskrit: "तत्र श्यावारुणाः प्रस्पन्दिन्यः सूक्ष्माः क्षणपूर्णरिक्ता वातरक्तं वहन्ति नीलपीतासिताः स्पर्शोष्णाः क्षिप्रस्राविण्यः पित्तरक्तम् गौर्यः स्निग्धाः स्थिराः शीताः कण्डूमत्यः कफरक्तम् लक्षणसङ्करे संसर्गसन्निपातारक्तम् समा गूढाः स्निग्धा रोहिण्यः शुद्धरक्तमिति", text: "tatra śyāvāruṇāḥ praspandinyaḥ sūkṣmāḥ kṣaṇapūrṇariktā vātaraktaṃ vahanti nīlapītāsitāḥ sparśoṣṇāḥ kṣiprasrāviṇyaḥ pittaraktam gauryaḥ snigdhāḥ sthirāḥ śītāḥ kaṇḍūmatyaḥ kapharaktam lakṣaṇasaṅkare saṃsargasannipātāraktam samā gūḍhāḥ snigdhā rohiṇyaḥ śuddharaktamiti" },
      { type: "verse", number: "9", sanskrit: "धमन्यस्तु चतुर्विंशतिः ताभिः कायो ऽयमाराम इव जलहारिणीभिः केदार इव कुल्याभिरुपस्निह्यति ताभिश्च नाभिश्चक्रनाभिरारकैरिवावृता तस्या नाभ्यां विशेषेण प्राणा व्यवस्थिताः यतश्च सान्तरग्न्यधिष्ठानम्", text: "dhamanyastu caturviṃśatiḥ tābhiḥ kāyo 'yamārāma iva jalahāriṇībhiḥ kedāra iva kulyābhirupasnihyati tābhiśca nābhiścakranābhirārakairivāvṛtā tasyā nābhyāṃ viśeṣeṇa prāṇā vyavasthitāḥ yataśca sāntaragnyadhiṣṭhānam" },
      { type: "verse", number: "10", sanskrit: "तासां खलु धमनीनां दशोर्ध्वं प्रसृता दशाधश्चतस्रस्तिर्यक् ततस्ताभिर्यथास्वमङ्गावयवा धार्यन्ते आप्याय्यन्ते च", text: "tāsāṃ khalu dhamanīnāṃ daśordhvaṃ prasṛtā daśādhaścatasrastiryak tatastābhiryathāsvamaṅgāvayavā dhāryante āpyāyyante ca" },
      { type: "verse", number: "11", sanskrit: "तासामूर्ध्वगा हृदयमभिप्रपन्नाः प्रत्येकं त्रिधा जायन्ते ततस्त्रिंशतो मध्ये द्वे द्वे वातपित्तकफरक्तरसान् वहतः अष्टाभिः शब्दरूपरसगन्धा गृह्यन्ते द्वाभ्यां द्वाभ्यां भाषते घोषं करोति स्वपिति प्रतिबुध्यते च द्वे चाश्नु वहतः द्वे च स्तनाश्रिते नार्याः स्तन्यं नरस्य शुक्रम्", text: "tāsāmūrdhvagā hṛdayamabhiprapannāḥ pratyekaṃ tridhā jāyante tatastriṃśato madhye dve dve vātapittakapharaktarasān vahataḥ aṣṭābhiḥ śabdarūparasagandhā gṛhyante dvābhyāṃ dvābhyāṃ bhāṣate ghoṣaṃ karoti svapiti pratibudhyate ca dve cāśnu vahataḥ dve ca stanāśrite nāryāḥ stanyaṃ narasya śukram" },
      { type: "verse", number: "12", sanskrit: "अधोगमाः पक्वाशयस्था एवं त्रिधा जायन्ते तत्र दशाद्याः पूर्ववत् द्वे वहतो ऽन्नं मात्राश्रयेण द्वे तोयम् द्वे मूत्रम् द्वे शुक्रं वहतो द्वे च मुञ्चतः ते एव नारीणामार्तवम् द्वे वर्चोनिरसिन्यौ स्थूलान्त्रप्रतिबद्धे एवं द्वादश शेषास्त्वष्टौ धमन्यस्तिरश्चीनाः स्वेदमभितर्पयन्ति", text: "adhogamāḥ pakvāśayasthā evaṃ tridhā jāyante tatra daśādyāḥ pūrvavat dve vahato 'nnaṃ mātrāśrayeṇa dve toyam dve mūtram dve śukraṃ vahato dve ca muñcataḥ te eva nārīṇāmārtavam dve varconirasinyau sthūlāntrapratibaddhe evaṃ dvādaśa śeṣāstvaṣṭau dhamanyastiraścīnāḥ svedamabhitarpayanti" },
      { type: "verse", number: "13", sanskrit: "तिर्यग्गामिन्यश्चतस्रो भिद्यमानाः सुबहुधा भवन्तीत्युक्तं प्राक्", text: "tiryaggāminyaścatasro bhidyamānāḥ subahudhā bhavantītyuktaṃ prāk" },
      { type: "verse", number: "14", sanskrit: "स्रोतांसि पुंसां नव कर्णौ नेत्रे नासापुटौ मुखं पायुर्मूत्रपथो ऽन्यानि च त्रीणि स्त्रीणां स्तनौ रक्तपथश्च तथापराण्यन्तस्स्रोतांसि जीवितायतनानि त्रयोदश प्राणोदकान्नधातुमलानामयनानि", text: "srotāṃsi puṃsāṃ nava karṇau netre nāsāpuṭau mukhaṃ pāyurmūtrapatho 'nyāni ca trīṇi strīṇāṃ stanau raktapathaśca tathāparāṇyantassrotāṃsi jīvitāyatanāni trayodaśa prāṇodakānnadhātumalānāmayanāni" },
      { type: "verse", number: "15", sanskrit: "तत्र प्राणवाहिनां हृदयं मूलं महास्रोतश्च तानि धातुक्षयरौक्ष्यपिपासाक्षुद्व्यायामवेगधारणादिभिर्दुष्यन्ति ततो ऽतिसृष्टं प्रतिबद्धमल्पाल्पमभीक्ष्णं वा सशब्दशूलमुच्छ्वसनम् तत्र श्वासवत् साधनम्", text: "tatra prāṇavāhināṃ hṛdayaṃ mūlaṃ mahāsrotaśca tāni dhātukṣayaraukṣyapipāsākṣudvyāyāmavegadhāraṇādibhirduṣyanti tato 'tisṛṣṭaṃ pratibaddhamalpālpamabhīkṣṇaṃ vā saśabdaśūlamucchvasanam tatra śvāsavat sādhanam" },
      { type: "verse", number: "16", sanskrit: "उदकवाहिनां तलु मूलं क्लोम च तान्यामभयातिपानोष्ण शुष्कान्नकषायतृण्निग्रहादिभिर्दुष्यन्ति ततो ऽतितृष्णा मुखशोषः कर्णक्ष्वेडनं तमोदर्शनं च तत्र तृष्णोक्तमौषधम्", text: "udakavāhināṃ talu mūlaṃ kloma ca tānyāmabhayātipānoṣṇa śuṣkānnakaṣāyatṛṇnigrahādibhirduṣyanti tato 'titṛṣṇā mukhaśoṣaḥ karṇakṣveḍanaṃ tamodarśanaṃ ca tatra tṛṣṇoktamauṣadham" },
      { type: "verse", number: "17", sanskrit: "अन्नवाहिनामामाशयो मूलं वामपार्श्वं च तेषा दुष्टौ सर्वं मात्राशितीयोक्तमवगच्छेत्", text: "annavāhināmāmāśayo mūlaṃ vāmapārśvaṃ ca teṣā duṣṭau sarvaṃ mātrāśitīyoktamavagacchet" },
      { type: "verse", number: "18", sanskrit: "रसवाहिनां हृदयं मूलं दश धमन्यश्च रक्तवाहिनां यकृत् प्लीहा च मांसवाहिनां स्नावानि त्वक् च भेदोवाहिनां वृक्कौ मांसं च अस्थिवाहिना जघनं मेदश्च मज्जवाहिनां पर्वाण्यस्थीनि च शुक्रवाहिनां स्तनौ मुष्कौ मज्जा च मूत्रवाहिनां बस्तिर्वङ्क्षैणा च शकृद्वाहिनां पक्वाशयः स्थूलान्त्रं च स्वेदवाहिनां मेदो रोमकूपाश्च तेषां दूषणं विविधमहिताहारविहारमुपद्रवान् पृथक् पृथक् साधनं दोषादिविज्ञानीयाद्यथास्वं वृद्धिक्षयलक्षणेन लक्षयेत्", text: "rasavāhināṃ hṛdayaṃ mūlaṃ daśa dhamanyaśca raktavāhināṃ yakṛt plīhā ca māṃsavāhināṃ snāvāni tvak ca bhedovāhināṃ vṛkkau māṃsaṃ ca asthivāhinā jaghanaṃ medaśca majjavāhināṃ parvāṇyasthīni ca śukravāhināṃ stanau muṣkau majjā ca mūtravāhināṃ bastirvaṅkṣaiṇā ca śakṛdvāhināṃ pakvāśayaḥ sthūlāntraṃ ca svedavāhināṃ medo romakūpāśca teṣāṃ dūṣaṇaṃ vividhamahitāhāravihāramupadravān pṛthak pṛthak sādhanaṃ doṣādivijñānīyādyathāsvaṃ vṛddhikṣayalakṣaṇena lakṣayet" },
      { type: "verse", number: "19", sanskrit: "व्यधे तु स्रोतसां भ्रममोहकम्पप्रलापाध्मानशूलारुचितृट्छर्दिज्वरातिरुधिरस्रुतिमूत्रपुरीषरोधा मरणं च तस्मात्स्रोतोविद्धं प्रत्याख्यायोपाचरेत् उद्धृतशल्यं च सद्योव्रणविधानेन", text: "vyadhe tu srotasāṃ bhramamohakampapralāpādhmānaśūlārucitṛṭchardijvarātirudhirasrutimūtrapurīṣarodhā maraṇaṃ ca tasmātsrotoviddhaṃ pratyākhyāyopācaret uddhṛtaśalyaṃ ca sadyovraṇavidhānena" },
      { type: "verse", number: "20", sanskrit: "तत्र स्रोतसामेव विशेषाः सिराधमन्यः अन्ये त्वन्यत्वमिच्छन्ति सिराधमनीस्रोतसाम् केवलं परस्परसन्निकर्षात् सदृशकर्मत्वात् सौक्ष्म्याच्च विभक्तकर्मणामप्यविभाग इव लक्ष्यते", text: "tatra srotasāmeva viśeṣāḥ sirādhamanyaḥ anye tvanyatvamicchanti sirādhamanīsrotasām kevalaṃ parasparasannikarṣāt sadṛśakarmatvāt saukṣmyācca vibhaktakarmaṇāmapyavibhāga iva lakṣyate" },
      { type: "verse", number: "21", sanskrit: "अपरे पुनराहुः स्रोतांसि सिराधमन्यो रसवाहिन्यो नाड्यः पन्थानो ऽयनानि गार्गाः शरीरच्छिद्राणि संवृतासंवृतानि स्थानान्याशयाः क्षयानिकेताश्चेति शरीरे धात्ववकाशानां लक्ष्यालक्ष्याणां नामानीति", text: "apare punarāhuḥ srotāṃsi sirādhamanyo rasavāhinyo nāḍyaḥ panthāno 'yanāni gārgāḥ śarīracchidrāṇi saṃvṛtāsaṃvṛtāni sthānānyāśayāḥ kṣayāniketāśceti śarīre dhātvavakāśānāṃ lakṣyālakṣyāṇāṃ nāmānīti" },
      { type: "verse", number: "22", sanskrit: "ते चावकाशाः प्रकुपिताः स्थानस्थान्मार्गस्थांश्च धातून् प्रकोपयन्ति ते ऽपि कुपितास्तानि स्रोतांसि स्रोतांसि च स्रोतांसि धातवश्च धातून् तेषां सर्वेषामेव दूषयितारो दुष्टा दोषाः ते च प्रायशो दुष्यन्त्यग्निदोषात् तस्मात्तन्निमित्तान्यायुरारोग्यबलोपचयवर्णौजांसि तत्प्रतिबद्धान्येव च रञ्जकादीनि भूताग्नयो धात्वग्नयश्च तथान्नमपि तैनैव पक्वममृततां यात्यपक्वं च विषताम्", text: "te cāvakāśāḥ prakupitāḥ sthānasthānmārgasthāṃśca dhātūn prakopayanti te 'pi kupitāstāni srotāṃsi srotāṃsi ca srotāṃsi dhātavaśca dhātūn teṣāṃ sarveṣāmeva dūṣayitāro duṣṭā doṣāḥ te ca prāyaśo duṣyantyagnidoṣāt tasmāttannimittānyāyurārogyabalopacayavarṇaujāṃsi tatpratibaddhānyeva ca rañjakādīni bhūtāgnayo dhātvagnayaśca tathānnamapi tainaiva pakvamamṛtatāṃ yātyapakvaṃ ca viṣatām" },
      { type: "verse", number: "23", sanskrit: "तत्र पित्तविशेषः पाचकसंज्ञो ऽग्निरिति प्रागभिहितः अन्ये पुनराचक्षते दोषधातुमलसन्निपातजनितो ऽन्तरूष्मा यथानिर्दिष्टाधिष्ठानकर्माग्निरिति", text: "tatra pittaviśeṣaḥ pācakasaṃjño 'gniriti prāgabhihitaḥ anye punarācakṣate doṣadhātumalasannipātajanito 'ntarūṣmā yathānirdiṣṭādhiṣṭhānakarmāgniriti" },
      { type: "verse", number: "24", sanskrit: "स खलु विधिवदभ्यवहृतमन्नजातं प्राणेन वायुना कोष्ठमाकृष्टं द्रवैर्विभिन्नसङ्घातं स्नेहेन मृदूकृतमभिसन्धुक्षितः समानेनामाशयस्थं स्थालीस्थमिवाम्बुतण्डुलमग्निरन्तरग्निः पचति", text: "sa khalu vidhivadabhyavahṛtamannajātaṃ prāṇena vāyunā koṣṭhamākṛṣṭaṃ dravairvibhinnasaṅghātaṃ snehena mṛdūkṛtamabhisandhukṣitaḥ samānenāmāśayasthaṃ sthālīsthamivāmbutaṇḍulamagnirantaragniḥ pacati" },
      { type: "verse", number: "25", sanskrit: "तत्तु सर्वरसमपि पच्यमानमादौ मधुरीभूतं कफं फेनीभूतमुदीरयति ततो विदग्धमम्लीभूतमामाशयात् च्यवमानमच्छं पित्तम् प्राप्य च पक्वाशयं कटुकीभूतमनिलम्", text: "tattu sarvarasamapi pacyamānamādau madhurībhūtaṃ kaphaṃ phenībhūtamudīrayati tato vidagdhamamlībhūtamāmāśayāt cyavamānamacchaṃ pittam prāpya ca pakvāśayaṃ kaṭukībhūtamanilam" },
      { type: "verse", number: "26", sanskrit: "ततश्चैवं विक्लिन्न आहारे पञ्च पञ्चात्मका महाभूताग्नयो वायुना व्यस्तान् यथास्वं पञ्चैव भूतगुणानाहारस्थान् पचन्ति ते पक्वाः पुनर्यथास्वमेव देहाश्रितांश्च स्वविकारभूतान् भूतगुणानाप्याययन्ति", text: "tataścaivaṃ viklinna āhāre pañca pañcātmakā mahābhūtāgnayo vāyunā vyastān yathāsvaṃ pañcaiva bhūtaguṇānāhārasthān pacanti te pakvāḥ punaryathāsvameva dehāśritāṃśca svavikārabhūtān bhūtaguṇānāpyāyayanti" },
      { type: "verse", number: "27", sanskrit: "एवं च पक्वादाहाराद्विविधौषधगर्भादिव स्नेहादच्छः सारभूतो रसाख्यः किट्टाख्यश्च मलो ऽभिनिर्वर्तते ताभ्यां च सारमलाभ्यां तदात्मकानामेव शरीरगुणानां धात्वाख्यानां यथास्वं स्रोतांसि पारम्पर्येणाविच्छिन्नसन्तानमापूर्यन्ते स्रोतोभ्यश्च यथाविभागं यथायथमेव धातवः पुष्यन्ति उत्तरोत्तरानुप्रवेशे ऽपि च पूर्वेषां स्रोतसां यथाकालं सम्यगाहारोपयोगेन परिणामवताप्याय्यमानानां नापचयो भवति ततश्च धात्वाख्याः प्रसादमलाः स्वं स्वमेव मानमनुवर्तन्ते यथावयश्शरीरम्", text: "evaṃ ca pakvādāhārādvividhauṣadhagarbhādiva snehādacchaḥ sārabhūto rasākhyaḥ kiṭṭākhyaśca malo 'bhinirvartate tābhyāṃ ca sāramalābhyāṃ tadātmakānāmeva śarīraguṇānāṃ dhātvākhyānāṃ yathāsvaṃ srotāṃsi pāramparyeṇāvicchinnasantānamāpūryante srotobhyaśca yathāvibhāgaṃ yathāyathameva dhātavaḥ puṣyanti uttarottarānupraveśe 'pi ca pūrveṣāṃ srotasāṃ yathākālaṃ samyagāhāropayogena pariṇāmavatāpyāyyamānānāṃ nāpacayo bhavati tataśca dhātvākhyāḥ prasādamalāḥ svaṃ svameva mānamanuvartante yathāvayaśśarīram" },
      { type: "verse", number: "28", sanskrit: "तत्राहाररसो व्यानीवक्षिप्तो यथास्वं सप्तसु धात्वग्निषु क्रमात् पच्यमानः स्वात्मभावप्रच्युतिसमनन्तरमेव प्राप्तरक्तादिधातुसंज्ञकः कालवदस्खलितबलप्रमाणो देहमूर्जयित्वा धातून् धातुमलांच पुष्णाति", text: "tatrāhāraraso vyānīvakṣipto yathāsvaṃ saptasu dhātvagniṣu kramāt pacyamānaḥ svātmabhāvapracyutisamanantarameva prāptaraktādidhātusaṃjñakaḥ kālavadaskhalitabalapramāṇo dehamūrjayitvā dhātūn dhātumalāṃca puṣṇāti" },
      { type: "verse", number: "29", sanskrit: "अथान्नकिट्टमच्छं मूत्रं घनं शकृत् रसस्य सारो रक्तं मलः कफो लसीका च रक्तस्य सारो मांसं कण्डरास्सिराश्च मलः पित्तम् मांसस्य सारो मेदस्त्वचो वसा च किट्टं कर्णाक्षिनासिकास्यरोमकूपप्रजननमलाः मेदसः सारो ऽस्थिस्नायुसन्धयः किट्टं स्वेदः अस्थ्नः सारो मज्जा किट्टं केशरोमनखाः मज्ज्ञस्तु सारः शुक्रं मलोक्षिविट्त्वचां स्नेहः शुक्रस्य सारमोजः अत्यन्तशुद्धतयास्य मलाभावः अन्ये पुनरत एव तस्य नेच्छन्ति पाकम् अपरे पुनः शुक्रसारं गर्भमेवामनन्ति", text: "athānnakiṭṭamacchaṃ mūtraṃ ghanaṃ śakṛt rasasya sāro raktaṃ malaḥ kapho lasīkā ca raktasya sāro māṃsaṃ kaṇḍarāssirāśca malaḥ pittam māṃsasya sāro medastvaco vasā ca kiṭṭaṃ karṇākṣināsikāsyaromakūpaprajananamalāḥ medasaḥ sāro 'sthisnāyusandhayaḥ kiṭṭaṃ svedaḥ asthnaḥ sāro majjā kiṭṭaṃ keśaromanakhāḥ majjñastu sāraḥ śukraṃ malokṣiviṭtvacāṃ snehaḥ śukrasya sāramojaḥ atyantaśuddhatayāsya malābhāvaḥ anye punarata eva tasya necchanti pākam apare punaḥ śukrasāraṃ garbhamevāmananti" },
      { type: "verse", number: "30", sanskrit: "वायुः पुनरग्नेराहारस्य च बह्वल्पतया तस्मात्तस्मान्मूर्च्छनाविशेषादमूर्तः शब्दवानीषच्छब्दः प्रचुरो ऽल्पो वा पञ्चात्मा कोष्ठे प्रादुर्भवति एवं च कृत्वान्नमया एव देहे सर्वे भावाः तेनैव चेदमेवं चिरेण व्याप्तमन्तर्बहिः शरीरयन्त्रमनवरतप्रवाहेण स्वास्थ्यबलोपचययुक्तं यावत्कर्मोपादानं याप्यते अन्यथा त्वन्नरसोत्क्षेपणाद्विबद्धस्रोतसा वा यथावदनभिसन्धीयमानधातुप्रवाहमन्तरा व्यवच्छिद्यते व्याधिभाजनं वा भवति", text: "vāyuḥ punaragnerāhārasya ca bahvalpatayā tasmāttasmānmūrcchanāviśeṣādamūrtaḥ śabdavānīṣacchabdaḥ pracuro 'lpo vā pañcātmā koṣṭhe prādurbhavati evaṃ ca kṛtvānnamayā eva dehe sarve bhāvāḥ tenaiva cedamevaṃ cireṇa vyāptamantarbahiḥ śarīrayantramanavaratapravāheṇa svāsthyabalopacayayuktaṃ yāvatkarmopādānaṃ yāpyate anyathā tvannarasotkṣepaṇādvibaddhasrotasā vā yathāvadanabhisandhīyamānadhātupravāhamantarā vyavacchidyate vyādhibhājanaṃ vā bhavati" },
      { type: "verse", number: "31", sanskrit: "अन्ये तु वर्णयन्ति अभ्यवहृत्मात्रस्याहारस्य कण्ठनाडीप्रलुठितस्य महानिम्रमवतीर्णस्य यो य एवांशः कायाग्निनावलीढः पाकमुपनीयते तस्य तस्यैव प्रसादाख्यो रसलेशो ऽभिनिर्वृत्तिसमनन्तरं समं समस्तधातुषु संवृतासंवृतैः प्रविसृतो विवृतमुखेष्वासन्नेषु स्रोतस्सु भूयान् प्रथमतरं चान्वेति पर्यायेणेतरेष्वपि एवमन्नरस एव साक्षात्सर्वधातून् केनचिदेव कालभेदेन पुष्णाति न पुनर्धातवो धात्वन्तरतां स्वरूपोपमर्देन प्रतिपद्यन्त इति", text: "anye tu varṇayanti abhyavahṛtmātrasyāhārasya kaṇṭhanāḍīpraluṭhitasya mahānimramavatīrṇasya yo ya evāṃśaḥ kāyāgnināvalīḍhaḥ pākamupanīyate tasya tasyaiva prasādākhyo rasaleśo 'bhinirvṛttisamanantaraṃ samaṃ samastadhātuṣu saṃvṛtāsaṃvṛtaiḥ pravisṛto vivṛtamukheṣvāsanneṣu srotassu bhūyān prathamataraṃ cānveti paryāyeṇetareṣvapi evamannarasa eva sākṣātsarvadhātūn kenacideva kālabhedena puṣṇāti na punardhātavo dhātvantaratāṃ svarūpopamardena pratipadyanta iti" },
      { type: "verse", number: "32", sanskrit: "अग्निस्तु बलभेदेन चतुर्विधो भवति समो विषमस्तीक्ष्णो मन्द्श्च तत्र समो यः सम्यगेवोपयुक्तमन्नं सम्यक् पचति विषमो ऽसम्यगप्युपयुक्तं पचति सम्यगपि च न पचति तीक्ष्णो ऽसम्यगप्युपयुक्तमाशु पचति स एव वर्धमानो ऽत्यग्निर्भवति मन्दस्तु सम्यगप्युपयुक्तमुदरगौरवाध्मानविबन्धाटोपान्त्रकूजनमुखशोषवायुस्तम्भादीन्यामलिङ्गानि दर्शयित्वा चिरात् पचति बाह्येनापि च ज्वालाङ्गारात्मकेनाग्निना नैकाकारः सर्वदा पाको भवति किमुतान्तराश्रयेणोष्णात्मना समेनापि तस्मात्तं प्रयत्नतो रक्षेत् तत्र प्रवरेण सात्म्येन समं यथास्वमपरेणेतरान् क्रमशः सात्म्यमापाद्य प्रवरेण परिपालयेद्दोषोपक्रमणीयोक्तेन च वातादिसाधनेन ग्रहणीरोगविहितैश्चौषधव्यायामयोगैरिति भवति चात्र", text: "agnistu balabhedena caturvidho bhavati samo viṣamastīkṣṇo mandśca tatra samo yaḥ samyagevopayuktamannaṃ samyak pacati viṣamo 'samyagapyupayuktaṃ pacati samyagapi ca na pacati tīkṣṇo 'samyagapyupayuktamāśu pacati sa eva vardhamāno 'tyagnirbhavati mandastu samyagapyupayuktamudaragauravādhmānavibandhāṭopāntrakūjanamukhaśoṣavāyustambhādīnyāmaliṅgāni darśayitvā cirāt pacati bāhyenāpi ca jvālāṅgārātmakenāgninā naikākāraḥ sarvadā pāko bhavati kimutāntarāśrayeṇoṣṇātmanā samenāpi tasmāttaṃ prayatnato rakṣet tatra pravareṇa sātmyena samaṃ yathāsvamapareṇetarān kramaśaḥ sātmyamāpādya pravareṇa paripālayeddoṣopakramaṇīyoktena ca vātādisādhanena grahaṇīrogavihitaiścauṣadhavyāyāmayogairiti bhavati cātra" },
      { type: "verse", number: "33", sanskrit: "स्वधातुसमवर्णानि वृत्तस्थूलान्यणूनि च स्रोतांसि दीर्घाण्याकृत्या प्रतानसदृशानि च", text: "svadhātusamavarṇāni vṛttasthūlānyaṇūni ca srotāṃsi dīrghāṇyākṛtyā pratānasadṛśāni ca" },
      { type: "verse", number: "34", sanskrit: "आहारश्च विहारश्च यः स्याद्दोषगुणैः समः धातुभिर्विगुणो यश्च स्रोतसां स प्रदूषकः", text: "āhāraśca vihāraśca yaḥ syāddoṣaguṇaiḥ samaḥ dhātubhirviguṇo yaśca srotasāṃ sa pradūṣakaḥ" },
      { type: "verse", number: "35", sanskrit: "अतिप्रवृत्तिः सङ्गो वा सिराणां ग्रन्थयो ऽपि वा विमार्गतो वा गमनं स्रोतसां दुष्टिलक्षणम्", text: "atipravṛttiḥ saṅgo vā sirāṇāṃ granthayo 'pi vā vimārgato vā gamanaṃ srotasāṃ duṣṭilakṣaṇam" },
      { type: "verse", number: "36", sanskrit: "बिसानामिव सूक्ष्माणि दूरं विप्रसृतानि च द्वाराणि स्रोतसां देहे रसो यैरुपचीयते", text: "bisānāmiva sūkṣmāṇi dūraṃ viprasṛtāni ca dvārāṇi srotasāṃ dehe raso yairupacīyate" },
      { type: "verse", number: "37", sanskrit: "केचिदाहुरहोरात्रात् षडहादपरे परे मासात् प्रयाति शुक्रत्वमन्नं पाकक्रमादिभिः", text: "kecidāhurahorātrāt ṣaḍahādapare pare māsāt prayāti śukratvamannaṃ pākakramādibhiḥ" },
      { type: "verse", number: "38", sanskrit: "वृष्यादीनि प्रभावेण सद्यः शुक्रादि कुर्वते प्रायः करोत्यहोरात्रात् कर्मान्यदपि भेषजम्", text: "vṛṣyādīni prabhāveṇa sadyaḥ śukrādi kurvate prāyaḥ karotyahorātrāt karmānyadapi bheṣajam" },
      { type: "verse", number: "39", sanskrit: "कफः पित्तं मलः खेषु प्रस्वेदो नखरोम च स्नेहो ऽक्षित्वग्विशामोजो धातूनां क्रमशो मलाः", text: "kaphaḥ pittaṃ malaḥ kheṣu prasvedo nakharoma ca sneho 'kṣitvagviśāmojo dhātūnāṃ kramaśo malāḥ" },
      { type: "verse", number: "40", sanskrit: "समः समाने स्थानस्थे विषमो ऽग्निर्विमार्गगे पित्ताभिमूर्छिते तीक्ष्णो मन्दोस्मिन्कफपीडिते", text: "samaḥ samāne sthānasthe viṣamo 'gnirvimārgage pittābhimūrchite tīkṣṇo mandosminkaphapīḍite" },
      { type: "verse", number: "41", sanskrit: "शान्ते ऽग्नौ म्रियते युक्ते चिरं जीवत्यनामयः रोगी स्याद्विकृते तस्मात्तं प्रयत्नेन पालयेत्", text: "śānte 'gnau mriyate yukte ciraṃ jīvatyanāmayaḥ rogī syādvikṛte tasmāttaṃ prayatnena pālayet" },
    ],
  },
  {
    sthana: "Шарирастхана",
    number: 7,
    lang: "sa",
    content: [
      { type: "heading", heading: "Кала бхрута — время и рост плода" },
      { type: "text", text: "Глава 7 Шарирастханы Астанга-санграхи — «Кала бхрута» — посвящена анатомическим и эмбриологическим аспектам: время и рост плода." },
      { type: "verse", number: "1", sanskrit: "अथातो मर्मविभागं नामाध्यायं व्याख्यास्यामः इति ह स्महुरात्रेयादयो महर्षयः", text: "athāto marmavibhāgaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smahurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सप्तोत्तरं मर्मशतम् तत्र चतुश्चत्वारिंशच्छाखासु षड्विंशतिरन्तराधौ सप्तत्रिंशदूर्ध्वम्", text: "saptottaraṃ marmaśatam tatra catuścatvāriṃśacchākhāsu ṣaḍviṃśatirantarādhau saptatriṃśadūrdhvam" },
      { type: "verse", number: "3", sanskrit: "अथैकस्मिन् सक्थ्नि मध्यमाङ्गुलिमभितो मध्ये पादतलस्य तलहृदयं नाम मर्म तत्र विद्धस्य रुजया मरणम् अङ्गुष्ठाङ्गुल्योर्मध्ये क्षिप्रं तत्राक्षेपकेन मरणम् क्षिप्रस्योपरि द्व्यङ्गुल उभयतः कूर्चः तत्र पादस्य भ्रमणवेपने भवतः गुल्फसन्धेरधः कूर्चशिरः तत्र रुजाशोफौ पादजङ्घयोः सन्धाने गुल्फः तत्र रुक् स्तब्धसक्थिता षण्ढता वा पार्ष्णिप्रभृतिद्वादशभिरङ्गुलैर्जङ्घामध्ये इन्द्रबस्तिः तत्र शोणित्क्षयान्मरणम् जङ्घोर्वोः सन्धाने जानु तत्र खञ्जता", text: "athaikasmin sakthni madhyamāṅgulimabhito madhye pādatalasya talahṛdayaṃ nāma marma tatra viddhasya rujayā maraṇam aṅguṣṭhāṅgulyormadhye kṣipraṃ tatrākṣepakena maraṇam kṣiprasyopari dvyaṅgula ubhayataḥ kūrcaḥ tatra pādasya bhramaṇavepane bhavataḥ gulphasandheradhaḥ kūrcaśiraḥ tatra rujāśophau pādajaṅghayoḥ sandhāne gulphaḥ tatra ruk stabdhasakthitā ṣaṇḍhatā vā pārṣṇiprabhṛtidvādaśabhiraṅgulairjaṅghāmadhye indrabastiḥ tatra śoṇitkṣayānmaraṇam jaṅghorvoḥ sandhāne jānu tatra khañjatā" },
      { type: "verse", number: "4", sanskrit: "जानुनस्त्र्यङ्गुलादूर्ध्वमुभयत आणिः तत्र शोफाभिवृद्धिः स्तब्धसक्थिता च ऊरुमध्ये उर्वी तत्र रक्तक्षयात्सक्थिशोषः उर्व्यास्तूर्ध्वमधो वङ्क्षणसन्धेरूरुमूले लोहिताक्षम् तत्र रक्तक्षयात् पक्षाघातः वङ्क्षणवृषणमध्ये विटपम् तत्र षण्ढ्यमल्पशुक्रता वा सक्थिवद् बाह्वोः विशेषस्तु गुल्फो मणिबन्धः तथा जानु कूर्परम् तयोर्व्यधे कुणिता विटपवच्च कक्षाक्षमध्ये कक्षाधरः तत्र कुणित्वम्", text: "jānunastryaṅgulādūrdhvamubhayata āṇiḥ tatra śophābhivṛddhiḥ stabdhasakthitā ca ūrumadhye urvī tatra raktakṣayātsakthiśoṣaḥ urvyāstūrdhvamadho vaṅkṣaṇasandherūrumūle lohitākṣam tatra raktakṣayāt pakṣāghātaḥ vaṅkṣaṇavṛṣaṇamadhye viṭapam tatra ṣaṇḍhyamalpaśukratā vā sakthivad bāhvoḥ viśeṣastu gulpho maṇibandhaḥ tathā jānu kūrparam tayorvyadhe kuṇitā viṭapavacca kakṣākṣamadhye kakṣādharaḥ tatra kuṇitvam" },
      { type: "verse", number: "5", sanskrit: "वातवर्चोनिरसनः स्थूलान्त्रप्रतिबद्धो गुदः तत्र सद्योमरणम् अल्पमांसशोणितो ऽभ्यन्तरतः कट्याधनुर्वक्र एकद्वारो ऽधोमुखो बस्तिः तत्रापि सद्योमरणमश्मरीव्रणादृते तत्राप्युभयतो विद्धे न जीवति एकतो भिन्ने मूत्रस्रावी व्रणो भवति स तु यत्नेनोपक्रान्तो रोहति पक्वामाशयमध्ये नाभिः तत्रापि सद्योमरणम्", text: "vātavarconirasanaḥ sthūlāntrapratibaddho gudaḥ tatra sadyomaraṇam alpamāṃsaśoṇito 'bhyantarataḥ kaṭyādhanurvakra ekadvāro 'dhomukho bastiḥ tatrāpi sadyomaraṇamaśmarīvraṇādṛte tatrāpyubhayato viddhe na jīvati ekato bhinne mūtrasrāvī vraṇo bhavati sa tu yatnenopakrānto rohati pakvāmāśayamadhye nābhiḥ tatrāpi sadyomaraṇam" },
      { type: "verse", number: "6", sanskrit: "कोष्ठवक्षसोः स्तनयोश्च मध्ये सत्वरजस्तमोधिष्ठानमामाशयद्वारं हृदयं तत्रापि सद्योमरणम् स्तनयोरधस्ताद्व्द्यङ्गुलमुभयतः स्तनमूले तयोः कफपूर्णकोष्ठस्य मरणम् स्तनचूचुकयोरूर्ध्वं व्द्यङ्गुलमुभयतः स्तनरोहिते तयोः शोणितपूर्णकोष्ठस्य मरणम् उभयत्रोरसोर्नाड्यौ वातवहे अपस्तम्भौ तयोः शोणितपूर्णकोष्ठतया कासश्वासाभ्यां च मरणम् अंसकूटयोरधः पार्श्वयोरुपरिभागयोरपालापौ तयोः पूयत्वमापन्नेन रक्तेन मरणम्", text: "koṣṭhavakṣasoḥ stanayośca madhye satvarajastamodhiṣṭhānamāmāśayadvāraṃ hṛdayaṃ tatrāpi sadyomaraṇam stanayoradhastādvdyaṅgulamubhayataḥ stanamūle tayoḥ kaphapūrṇakoṣṭhasya maraṇam stanacūcukayorūrdhvaṃ vdyaṅgulamubhayataḥ stanarohite tayoḥ śoṇitapūrṇakoṣṭhasya maraṇam ubhayatrorasornāḍyau vātavahe apastambhau tayoḥ śoṇitapūrṇakoṣṭhatayā kāsaśvāsābhyāṃ ca maraṇam aṃsakūṭayoradhaḥ pārśvayoruparibhāgayorapālāpau tayoḥ pūyatvamāpannena raktena maraṇam" },
      { type: "verse", number: "7", sanskrit: "पृष्ठवंशमुभयतः प्रतिश्रोणीकर्णावस्थिनी कटीकतरुणे तयोः शोणितक्षयात् पाण्डुर्विवर्णो हीनरूपो म्रियते पार्श्वयोर्जघनबहिर्भागे पृष्ठवंशमुभयतः कुकुन्दरौ तयोः स्पर्शाज्ञानमधःकाये चेष्टानाशश्च श्रोणीकर्णयोरुपर्याशयच्छादनौ पार्श्वान्तरप्रतिबद्धौ नितम्बौ तयोरधःकाये शोफो दौर्बल्यं मरणं च अधः पार्श्वान्तरप्रतिबद्धौ जघनपार्श्वमध्ये तिर्यगूर्ध्वं च पार्श्वसन्धी तयोः शोणितपूर्णकोष्ठतया मरणम्", text: "pṛṣṭhavaṃśamubhayataḥ pratiśroṇīkarṇāvasthinī kaṭīkataruṇe tayoḥ śoṇitakṣayāt pāṇḍurvivarṇo hīnarūpo mriyate pārśvayorjaghanabahirbhāge pṛṣṭhavaṃśamubhayataḥ kukundarau tayoḥ sparśājñānamadhaḥkāye ceṣṭānāśaśca śroṇīkarṇayoruparyāśayacchādanau pārśvāntarapratibaddhau nitambau tayoradhaḥkāye śopho daurbalyaṃ maraṇaṃ ca adhaḥ pārśvāntarapratibaddhau jaghanapārśvamadhye tiryagūrdhvaṃ ca pārśvasandhī tayoḥ śoṇitapūrṇakoṣṭhatayā maraṇam" },
      { type: "verse", number: "8", sanskrit: "स्तनमूलयोरार्जवेनोभयतः पृष्ठवंशं बृहत्यौ तयोः शोणितातिप्रवृत्तिनिमित्तैरुपद्रवैर्मरणम् पृष्ठवंशमुभयतो बाहुमूलसम्बद्धे अंसफलके तयोर्बाहुस्वापशोषौ ग्रीवाबाहुशिरोमध्ये ऽसपीठस्कन्धबन्धनावंसौ तयोः स्तब्धबाहुता", text: "stanamūlayorārjavenobhayataḥ pṛṣṭhavaṃśaṃ bṛhatyau tayoḥ śoṇitātipravṛttinimittairupadravairmaraṇam pṛṣṭhavaṃśamubhayato bāhumūlasambaddhe aṃsaphalake tayorbāhusvāpaśoṣau grīvābāhuśiromadhye 'sapīṭhaskandhabandhanāvaṃsau tayoḥ stabdhabāhutā" },
      { type: "verse", number: "9", sanskrit: "कण्ठनाडीमुभयतश्चतस्रो धमन्यः तासां द्वे नीले द्वे मन्ये तासु मूकता स्वरवैकृत्यं रसाग्राहिता वा भवति ग्रीवायामुभयतः पृथक् चतस्रः सिरामातृकास्तासु सद्योमरणम् शिरोग्रीवयोः सन्धाने कुकाटिके तयोश्चलमूर्धता कर्णपृष्ठयोरधस्संश्रिते विधुरे तयोर्बाधिर्यम् घ्राणमार्गमुभयतः श्रोत्रमार्गप्रतिबद्धावभ्यन्तरतः फणौ तयोर्गन्धाज्ञानम् भ्रुवोः पुच्छान्तयोरधोक्ष्णोर्बाह्यतो ऽपाङ्गौ तयोरान्ध्यम् भ्रुवोः पुच्छान्तयोरुपर्यनुकर्णं ललाटे शङ्खौ तयोः सद्योमरणम् भ्रुवोरुपरि निम्नयोरावर्तौ तयोरान्ध्यम् दृष्ट्युपघातो वा", text: "kaṇṭhanāḍīmubhayataścatasro dhamanyaḥ tāsāṃ dve nīle dve manye tāsu mūkatā svaravaikṛtyaṃ rasāgrāhitā vā bhavati grīvāyāmubhayataḥ pṛthak catasraḥ sirāmātṛkāstāsu sadyomaraṇam śirogrīvayoḥ sandhāne kukāṭike tayoścalamūrdhatā karṇapṛṣṭhayoradhassaṃśrite vidhure tayorbādhiryam ghrāṇamārgamubhayataḥ śrotramārgapratibaddhāvabhyantarataḥ phaṇau tayorgandhājñānam bhruvoḥ pucchāntayoradhokṣṇorbāhyato 'pāṅgau tayorāndhyam bhruvoḥ pucchāntayoruparyanukarṇaṃ lalāṭe śaṅkhau tayoḥ sadyomaraṇam bhruvorupari nimnayorāvartau tayorāndhyam dṛṣṭyupaghāto vā" },
      { type: "verse", number: "10", sanskrit: "शङ्खयोरुपरि केशान्ते उत्क्षेपौ तयोः सशल्यः पाकात् पतितशल्यो वा जीवेन्नोद्धृतशल्यः भ्रुवोर्मध्ये स्थपनी तत्रोत्क्षेपवत् पञ्च सन्धयः शिरसि तिर्यगूर्ध्वं च सीमन्ता नाम तेषून्मादभ्रमचित्तनाशैर्मरणम् जिह्वाघ्राणाक्षिश्रोत्रतर्पणीनां सिराणां तालुनि सन्निपातः तासां मुखानि चत्वारि शृङ्गाटकसंज्ञानि तेषु सद्योमरणम् मस्तकाभ्यन्तर उपरिष्टात्सिरासन्धिसन्निपातो रोमावर्तः सो ऽधिपतिर्नाम तत्रापि सद्योमरणं भवतीति", text: "śaṅkhayorupari keśānte utkṣepau tayoḥ saśalyaḥ pākāt patitaśalyo vā jīvennoddhṛtaśalyaḥ bhruvormadhye sthapanī tatrotkṣepavat pañca sandhayaḥ śirasi tiryagūrdhvaṃ ca sīmantā nāma teṣūnmādabhramacittanāśairmaraṇam jihvāghrāṇākṣiśrotratarpaṇīnāṃ sirāṇāṃ tāluni sannipātaḥ tāsāṃ mukhāni catvāri śṛṅgāṭakasaṃjñāni teṣu sadyomaraṇam mastakābhyantara upariṣṭātsirāsandhisannipāto romāvartaḥ so 'dhipatirnāma tatrāpi sadyomaraṇaṃ bhavatīti" },
      { type: "verse", number: "11", sanskrit: "सामान्यलक्षणं पुनर्मर्मणां पीडिते रुजोत्पत्तिर्विषमं च स्पन्दनम् सामान्येनैव च", text: "sāmānyalakṣaṇaṃ punarmarmaṇāṃ pīḍite rujotpattirviṣamaṃ ca spandanam sāmānyenaiva ca" },
      { type: "verse", number: "12", sanskrit: "देहप्रसुप्तिर्गुरुता सम्मोहः शीतकामिताअ स्वेदो मूर्छा वमिः श्वासो मर्मविद्धस्य लक्षणम्", text: "dehaprasuptirgurutā sammohaḥ śītakāmitāa svedo mūrchā vamiḥ śvāso marmaviddhasya lakṣaṇam" },
      { type: "verse", number: "13", sanskrit: "अपि च मरणकारित्वान्मर्म तत् पुनर्मांससिरास्नावास्थिसन्धिसन्निपातः तेन तस्मिन् पीड्यमाने विशेषतः प्राणाबाधः बाहुल्येन तु निर्देशः तस्मान्मांसाद्याश्रयतो मर्माणि पञ्चधा भिद्यन्ते", text: "api ca maraṇakāritvānmarma tat punarmāṃsasirāsnāvāsthisandhisannipātaḥ tena tasmin pīḍyamāne viśeṣataḥ prāṇābādhaḥ bāhulyena tu nirdeśaḥ tasmānmāṃsādyāśrayato marmāṇi pañcadhā bhidyante" },
      { type: "verse", number: "14", sanskrit: "तद्यथा तलहृदयेन्द्रबस्तिगुदस्तनरोहितान्येकादश मांसमर्माणि उर्वीलोहिताख्यनाभिहृदयस्तनमूलापस्तम्भापालापपार्श्वसन्धिबृहतीनीलामन्यामातृकाफणापाङ्गस्थपनीशृङ्गाटकान्येकचत्वारिंशत् सिरामर्माणि क्षिप्रकूर्चकूर्चशिरोविटपकक्षाधराणि बस्त्यंसविधुरोत्क्षेपाः सप्तविंशतिः स्नावमर्माणि कटीकतरुणनितम्बांसफलकशङ्खास्त्वष्टावस्थिमर्माणि गुल्फमणिबन्धजानुकूर्परकुकुन्दरकृकाटिकावर्तसीमन्ताधिपतयो विंशतिः सन्धिमर्माणि", text: "tadyathā talahṛdayendrabastigudastanarohitānyekādaśa māṃsamarmāṇi urvīlohitākhyanābhihṛdayastanamūlāpastambhāpālāpapārśvasandhibṛhatīnīlāmanyāmātṛkāphaṇāpāṅgasthapanīśṛṅgāṭakānyekacatvāriṃśat sirāmarmāṇi kṣiprakūrcakūrcaśiroviṭapakakṣādharāṇi bastyaṃsavidhurotkṣepāḥ saptaviṃśatiḥ snāvamarmāṇi kaṭīkataruṇanitambāṃsaphalakaśaṅkhāstvaṣṭāvasthimarmāṇi gulphamaṇibandhajānukūrparakukundarakṛkāṭikāvartasīmantādhipatayo viṃśatiḥ sandhimarmāṇi" },
      { type: "verse", number: "15", sanskrit: "पुनश्च पञ्चधा गुदबस्तिनाभिहृदयमातृकाशङ्खशृङ्गाटकाधिपतय एकोनविंशतिः सद्यःप्राणहराण्याग्नेयत्वात्तेषां सप्तरात्राभ्यन्तरं कालः", text: "punaśca pañcadhā gudabastinābhihṛdayamātṛkāśaṅkhaśṛṅgāṭakādhipataya ekonaviṃśatiḥ sadyaḥprāṇaharāṇyāgneyatvātteṣāṃ saptarātrābhyantaraṃ kālaḥ" },
      { type: "verse", number: "16", sanskrit: "तलहृदयक्षिप्रेन्द्रबस्तिवक्षोमर्मकटीकतरुणनितम्बपार्श्वसन्धिबृहतीसीमन्तास्त्रयस्त्रिंशत् कालान्तरप्राणहराणि सौम्याग्नेयत्वात्तेषां पक्षाभ्यन्तरं कालः तेष्वपि तु क्षिप्राणि कदाचिदाशु", text: "talahṛdayakṣiprendrabastivakṣomarmakaṭīkataruṇanitambapārśvasandhibṛhatīsīmantāstrayastriṃśat kālāntaraprāṇaharāṇi saumyāgneyatvātteṣāṃ pakṣābhyantaraṃ kālaḥ teṣvapi tu kṣiprāṇi kadācidāśu" },
      { type: "verse", number: "17", sanskrit: "उत्क्षेपौ स्थपनी च त्रीणि विशल्यघ्नानि वायव्यत्वात् शल्यमुखावरुद्धो हि यावदत्र वायुस्तिष्ठति तावज्जीवति", text: "utkṣepau sthapanī ca trīṇi viśalyaghnāni vāyavyatvāt śalyamukhāvaruddho hi yāvadatra vāyustiṣṭhati tāvajjīvati" },
      { type: "verse", number: "18", sanskrit: "कूर्चजानुकूर्पराण्युर्वीलोहिताख्यविटपकक्षाधरकुकुन्दरांसफलकनीलामन्याकृकाटिकाविधुरफणापाङ्गावर्ताश्चतुश्चत्वारिंशद्वैकल्यकराणि सौम्यत्वात् सोमो हि स्थैर्यशैत्याभ्यां प्राणान् धारयति तान्यपि च कदाचिदभिहतानि मारयन्ति", text: "kūrcajānukūrparāṇyurvīlohitākhyaviṭapakakṣādharakukundarāṃsaphalakanīlāmanyākṛkāṭikāvidhuraphaṇāpāṅgāvartāścatuścatvāriṃśadvaikalyakarāṇi saumyatvāt somo hi sthairyaśaityābhyāṃ prāṇān dhārayati tānyapi ca kadācidabhihatāni mārayanti" },
      { type: "verse", number: "19", sanskrit: "कुर्चशिरोगुल्फमणिबन्धास्त्वष्टौ रुजाकराण्यग्निवायुसोमगुणबाहुल्यात् अग्निवायू हि विशेषेण रुजाकरौ सोमस्तु प्राणानवलम्बत इत्युक्तम्", text: "kurcaśirogulphamaṇibandhāstvaṣṭau rujākarāṇyagnivāyusomaguṇabāhulyāt agnivāyū hi viśeṣeṇa rujākarau somastu prāṇānavalambata ityuktam" },
      { type: "verse", number: "20", sanskrit: "अन्ये त्वाहुः मांसादीनां पञ्चानामपि विवृद्धानां समवायात् सद्यः प्राणहराणि एकैकहीनानामल्पानां च क्रमादितराणि स्वभावत एव च", text: "anye tvāhuḥ māṃsādīnāṃ pañcānāmapi vivṛddhānāṃ samavāyāt sadyaḥ prāṇaharāṇi ekaikahīnānāmalpānāṃ ca kramāditarāṇi svabhāvata eva ca" },
      { type: "verse", number: "21", sanskrit: "अन्ये वदन्ति प्रतिनियतकर्माणि चन्द्रसूर्यायस्कान्तोपलानामिवाम्बुवह्निकाललोहसंश्लेषाः तथा च छिन्नेषु बहुमर्मस्वपि पाणिपादेषु स्वभावत एव न मृत्युः", text: "anye vadanti pratiniyatakarmāṇi candrasūryāyaskāntopalānāmivāmbuvahnikālalohasaṃśleṣāḥ tathā ca chinneṣu bahumarmasvapi pāṇipādeṣu svabhāvata eva na mṛtyuḥ" },
      { type: "verse", number: "22", sanskrit: "अपरे पुनरत्रापि हेतुमाहुः पाणिपादच्छेदे हि सिराः सङ्कोचमायान्ति ततोल्पासृक्प्रवृत्तेर्जीवितम् मर्मव्यधे त्वतिरक्तस्रुतितो वायुवैकृतेन च मरणम् तस्मान्मर्माभिहतस्य तदङ्गमाशु सन्धिदेशाच्छेदनीयम् अतिहतानां तु मर्माणां यथास्वं पूर्वं पूर्वं च कर्म ईषदन्ते वा हतानामुत्तरोत्तरमेव", text: "apare punaratrāpi hetumāhuḥ pāṇipādacchede hi sirāḥ saṅkocamāyānti tatolpāsṛkpravṛtterjīvitam marmavyadhe tvatiraktasrutito vāyuvaikṛtena ca maraṇam tasmānmarmābhihatasya tadaṅgamāśu sandhideśācchedanīyam atihatānāṃ tu marmāṇāṃ yathāsvaṃ pūrvaṃ pūrvaṃ ca karma īṣadante vā hatānāmuttarottarameva" },
      { type: "verse", number: "23", sanskrit: "पुनश्च पञ्चधा भिद्यन्ते तद्यथा उर्व्यः कूर्चशिरांसि विटपे कक्षाधरे च द्वादश स्वाङ्गुलोन्मितानि गुल्फौ मणिबन्धौ स्तनमूले च षट् द्व्यङ्गुलानि जानुनी कूर्परे च चत्वारि त्र्यङ्गुलानि कूर्चा गुदो बस्तिर्नाभिर्हृदयं नीले मन्ये मातृकाः सीमन्ताः शृङ्गाटकानि चैकोनत्रिंशत् पाणितलसम्मितानि शेषाणि षट् पञ्चाशदङ्गुलदलप्रमाणानि अन्ये पुनराहुः ब्रीहिप्रमाणानि क्षिप्राणि कलायप्रमाणाः स्तनरोहितोत्क्षेपाः तथान्ये तिलप्रमाणान्यपि मर्माणीच्छन्ति भवन्ति चात्र", text: "punaśca pañcadhā bhidyante tadyathā urvyaḥ kūrcaśirāṃsi viṭape kakṣādhare ca dvādaśa svāṅgulonmitāni gulphau maṇibandhau stanamūle ca ṣaṭ dvyaṅgulāni jānunī kūrpare ca catvāri tryaṅgulāni kūrcā gudo bastirnābhirhṛdayaṃ nīle manye mātṛkāḥ sīmantāḥ śṛṅgāṭakāni caikonatriṃśat pāṇitalasammitāni śeṣāṇi ṣaṭ pañcāśadaṅguladalapramāṇāni anye punarāhuḥ brīhipramāṇāni kṣiprāṇi kalāyapramāṇāḥ stanarohitotkṣepāḥ tathānye tilapramāṇānyapi marmāṇīcchanti bhavanti cātra" },
      { type: "verse", number: "24", sanskrit: "मर्मव्याप्ते ऽपि देहे ऽस्मिन्नायुर्मर्माणि रक्षति आयुष्याण्येव सेवेत सदा तस्माद्विचक्षणः", text: "marmavyāpte 'pi dehe 'sminnāyurmarmāṇi rakṣati āyuṣyāṇyeva seveta sadā tasmādvicakṣaṇaḥ" },
      { type: "verse", number: "25", sanskrit: "मर्माभिघातः स्वल्पो ऽपि प्रायशो बाधतेतराम् रोगा मर्माश्रयास्तद्वत् प्रकान्ता यत्नतोपि च", text: "marmābhighātaḥ svalpo 'pi prāyaśo bādhatetarām rogā marmāśrayāstadvat prakāntā yatnatopi ca" },
      { type: "verse", number: "26", sanskrit: "विक्षिप्यते भृशं सीदन् शून्यो भ्रमति वेपते ऊर्ध्वं श्वसिति कृच्छ्रेण स्रस्तगात्रो मुहुर्मुहुः", text: "vikṣipyate bhṛśaṃ sīdan śūnyo bhramati vepate ūrdhvaṃ śvasiti kṛcchreṇa srastagātro muhurmuhuḥ" },
      { type: "verse", number: "27", sanskrit: "हृदयं दद्यते चास्य नैकस्थाने ऽवतिष्ठते मर्मोपघातान्मरणमेतैर्लिङ्गैः समश्नुते", text: "hṛdayaṃ dadyate cāsya naikasthāne 'vatiṣṭhate marmopaghātānmaraṇametairliṅgaiḥ samaśnute" },
      { type: "verse", number: "28", sanskrit: "अमर्मविद्धो ऽपि नरश्छेदभेदादिपीडितः अतिनिस्सृतरक्तश्च सद्यस्त्यजति जीवितम्", text: "amarmaviddho 'pi naraśchedabhedādipīḍitaḥ atinissṛtaraktaśca sadyastyajati jīvitam" },
      { type: "verse", number: "29", sanskrit: "अतो ऽन्यथा जीवति तु विद्धः शरशतैरपि", text: "ato 'nyathā jīvati tu viddhaḥ śaraśatairapi" },
      { type: "verse", number: "30", sanskrit: "पुण्यवान्नियतायुश्च न कथञ्चिन्न जीवति तस्मादा चरमोच्छ्वासाच्चिकित्सेदेव यत्नतः", text: "puṇyavānniyatāyuśca na kathañcinna jīvati tasmādā caramocchvāsāccikitsedeva yatnataḥ" },
      { type: "verse", number: "31", sanskrit: "तद्बन्धुमित्रानुमतः प्रत्याख्यायातुरं भिषक्", text: "tadbandhumitrānumataḥ pratyākhyāyāturaṃ bhiṣak" },
    ],
  },
  {
    sthana: "Шарирастхана",
    number: 8,
    lang: "sa",
    content: [
      { type: "heading", heading: "Джанма практика — роды и послеродовой период" },
      { type: "text", text: "Глава 8 Шарирастханы Астанга-санграхи — «Джанма практика» — посвящена анатомическим и эмбриологическим аспектам: роды и послеродовой период." },
      { type: "verse", number: "1", sanskrit: "अथातः प्रकृतिभेद्दीयं शारीरं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ prakṛtibheddīyaṃ śārīraṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सप्त प्रकृतयो दोषैः पृथक् संसर्गेण साम्येन च भवन्ति तत्र शुक्रार्तवगर्भाशयकालेषु मातुश्चाहारविहारयोरेको ऽनेको वा यो दोषो भवत्याधिक्येन तेनामरणाद्विषवल्यामिवोत्पद्यमानस्य कृमेर्विषेण सविषकृमेरिव वृश्चिकादेराशीविषस्येव वा स्वविषेण प्रकृतिर्जायते", text: "sapta prakṛtayo doṣaiḥ pṛthak saṃsargeṇa sāmyena ca bhavanti tatra śukrārtavagarbhāśayakāleṣu mātuścāhāravihārayoreko 'neko vā yo doṣo bhavatyādhikyena tenāmaraṇādviṣavalyāmivotpadyamānasya kṛmerviṣeṇa saviṣakṛmeriva vṛścikāderāśīviṣasyeva vā svaviṣeṇa prakṛtirjāyate" },
      { type: "verse", number: "3", sanskrit: "तस्मात्तन्मयतया शुक्रार्तवयोर्देहस्य भावितत्वात् प्राकृतत्वाच्च तावता तेन दोषेण न विहन्यते तद्गुणैरेव चास्यशरीरमुपस्क्रियते ततश्च तद्गुणप्रतिपक्षैः सहसा न बाध्यते तस्यां त्ववस्थायां विकृतिमति दोषे उल्बणेनैव गर्भः सम्भवति सम्भव एव विपद्यते विकृतो वा भवति", text: "tasmāttanmayatayā śukrārtavayordehasya bhāvitatvāt prākṛtatvācca tāvatā tena doṣeṇa na vihanyate tadguṇaireva cāsyaśarīramupaskriyate tataśca tadguṇapratipakṣaiḥ sahasā na bādhyate tasyāṃ tvavasthāyāṃ vikṛtimati doṣe ulbaṇenaiva garbhaḥ sambhavati sambhava eva vipadyate vikṛto vā bhavati" },
      { type: "verse", number: "4", sanskrit: "तथा च केचिदाहुः द्विविधा वातादयः प्राकृता वैकृताश्च तत्र प्राकृताः सप्तविधायाः प्रकृतेर्हेतुभूताः शरीरैकजन्मानः ते शरीरधारणाद्धातुसंज्ञाः दोषाख्यानां विकृतानां बीजभूताः मुमूर्षोः स्वरूपाच्चलन्ति सर्वेष्वपि च देहे सन्निहितेषु प्रकृतावुल्बणेन व्यपदेशः", text: "tathā ca kecidāhuḥ dvividhā vātādayaḥ prākṛtā vaikṛtāśca tatra prākṛtāḥ saptavidhāyāḥ prakṛterhetubhūtāḥ śarīraikajanmānaḥ te śarīradhāraṇāddhātusaṃjñāḥ doṣākhyānāṃ vikṛtānāṃ bījabhūtāḥ mumūrṣoḥ svarūpāccalanti sarveṣvapi ca dehe sannihiteṣu prakṛtāvulbaṇena vyapadeśaḥ" },
      { type: "verse", number: "5", sanskrit: "वैकृतास्तु गर्भादभिनिस्सृतस्याहाररसस्य मलाः सम्भवन्ति प्राकृतेष्ववरोहन्ति ते कालादिवशेन स्वप्नमाणवृद्धिक्षययोगाद्देहमनुगृह्णन्ति दूषयन्ति च तद्वदोजो ऽपि परं हृदयस्थमष्टबिन्दुप्रमाणमाधारः प्रासृतिकस्य रसात्मकस्यौजसः क्षयवृद्धिभाजः", text: "vaikṛtāstu garbhādabhinissṛtasyāhārarasasya malāḥ sambhavanti prākṛteṣvavarohanti te kālādivaśena svapnamāṇavṛddhikṣayayogāddehamanugṛhṇanti dūṣayanti ca tadvadojo 'pi paraṃ hṛdayasthamaṣṭabindupramāṇamādhāraḥ prāsṛtikasya rasātmakasyaujasaḥ kṣayavṛddhibhājaḥ" },
      { type: "verse", number: "6", sanskrit: "अथ स्वदोषगुणानुरोधाद्वातप्रकृतिस्तनुरूक्षस्तब्धाल्पाङ्गदन्तनखरोमनेत्रस्वरः शीतद्विडुद्वद्धपिण्डिकः सशब्दसन्धिगामी शीघ्रारम्भक्षोभग्रहणविस्मरणश्चलधृतिमतिगतिदृष्टिस्वभावसौहार्दस्तेनो ऽनार्यो मत्सर्यजितेन्द्रियः प्रियगान्धर्वेतिहासहासविलासकलहमृगयोद्यानयात्रः स्निग्धोष्णमधुराम्ललवणान्नपानकाङ्क्षोपशयश्च भवति", text: "atha svadoṣaguṇānurodhādvātaprakṛtistanurūkṣastabdhālpāṅgadantanakharomanetrasvaraḥ śītadviḍudvaddhapiṇḍikaḥ saśabdasandhigāmī śīghrārambhakṣobhagrahaṇavismaraṇaścaladhṛtimatigatidṛṣṭisvabhāvasauhārdasteno 'nāryo matsaryajitendriyaḥ priyagāndharvetihāsahāsavilāsakalahamṛgayodyānayātraḥ snigdhoṣṇamadhurāmlalavaṇānnapānakāṅkṣopaśayaśca bhavati" },
      { type: "verse", number: "7", sanskrit: "अपि च अल्पवित्तबलजीवितनिद्रः क्षामवाग्धमनिसन्ततगात्रः दुर्भगो ऽतिबहुभुग्बहुभाषी नास्तिकः स्फुटितकेशकराङ्घ्रिः", text: "api ca alpavittabalajīvitanidraḥ kṣāmavāgdhamanisantatagātraḥ durbhago 'tibahubhugbahubhāṣī nāstikaḥ sphuṭitakeśakarāṅghriḥ" },
      { type: "verse", number: "8", sanskrit: "किञ्चिदुन्मिषितदुर्मुखसुप्तस्त्रस्यति क्रथति खादति दन्तान् शुष्करूक्षविषमासु सरित्सु व्योम्नि शौलशिखरेषु च याति", text: "kiñcidunmiṣitadurmukhasuptastrasyati krathati khādati dantān śuṣkarūkṣaviṣamāsu saritsu vyomni śaulaśikhareṣu ca yāti" },
      { type: "verse", number: "9", sanskrit: "पित्तप्रकृतिरुष्णगौरगात्रस्ताम्रनखनयनजिह्वौष्ठपाणिपादतलः शिथिलसन्धिबन्धमांसः करभकपिलविरलमृदुकेशरोमा मध्यबलायुरल्पशुक्रव्यवायापत्यः शूरो ऽभिमानी शीघ्रवलीखलतिपलितपिप्लुव्यङ्गक्षुत्पिपासो मेधावी दुर्भगः स्वादुतिक्तकषायशीताभिलाषोपशयश्च भवति", text: "pittaprakṛtiruṣṇagauragātrastāmranakhanayanajihvauṣṭhapāṇipādatalaḥ śithilasandhibandhamāṃsaḥ karabhakapilaviralamṛdukeśaromā madhyabalāyuralpaśukravyavāyāpatyaḥ śūro 'bhimānī śīghravalīkhalatipalitapipluvyaṅgakṣutpipāso medhāvī durbhagaḥ svādutiktakaṣāyaśītābhilāṣopaśayaśca bhavati" },
      { type: "verse", number: "10", sanskrit: "अपि च दयितमाल्यविलेपनमण्डनः सुचरितः शुचिराश्रितवत्सलः विभवसाहसबुद्धिबलान्वितो भवति भीषु गतिर्द्विषतामपि", text: "api ca dayitamālyavilepanamaṇḍanaḥ sucaritaḥ śucirāśritavatsalaḥ vibhavasāhasabuddhibalānvito bhavati bhīṣu gatirdviṣatāmapi" },
      { type: "verse", number: "11", sanskrit: "घर्मद्वेषी स्वेदनः पूतिगन्धिर्भूर्युच्चारक्रोधपानाशनेर्ष्यः सुप्तः पश्येत् कर्णिकारान् पलाशान् दिग्दाहोल्काविद्युदर्कानलांश्च", text: "gharmadveṣī svedanaḥ pūtigandhirbhūryuccārakrodhapānāśanerṣyaḥ suptaḥ paśyet karṇikārān palāśān digdāholkāvidyudarkānalāṃśca" },
      { type: "verse", number: "12", sanskrit: "कफप्रकृतिस्तु दूर्वेन्दीवरशरकाण्डान्यतमवर्णः समसुविभक्तस्निग्धस्थिरसुकुमारश्लिष्टमांससन्धिबन्धः परिपूर्णचारुगात्रो महाललाटोरुबाहुर्व्यक्तसितासितप्रसन्नायतविशालपक्ष्मलाक्षः सिंहमृदङ्गघनघोषः क्षुत्पिपासोष्णसहिष्णुर्बह्वोजोबलशुक्रव्यवायापत्यश्चिरशोषमाल्यानुलेपनो दृढप्रच्छन्नवैरः पेशलः सत्यवादी स्मृतिमान् धृतिमानलोलुपो बाल्ये ऽप्यरोदनः कटुतिक्तकषायोष्णरूक्षेच्छोपशयश्च भवति", text: "kaphaprakṛtistu dūrvendīvaraśarakāṇḍānyatamavarṇaḥ samasuvibhaktasnigdhasthirasukumāraśliṣṭamāṃsasandhibandhaḥ paripūrṇacārugātro mahālalāṭorubāhurvyaktasitāsitaprasannāyataviśālapakṣmalākṣaḥ siṃhamṛdaṅgaghanaghoṣaḥ kṣutpipāsoṣṇasahiṣṇurbahvojobalaśukravyavāyāpatyaściraśoṣamālyānulepano dṛḍhapracchannavairaḥ peśalaḥ satyavādī smṛtimān dhṛtimānalolupo bālye 'pyarodanaḥ kaṭutiktakaṣāyoṣṇarūkṣecchopaśayaśca bhavati" },
      { type: "verse", number: "13", sanskrit: "अपि च अल्पव्याहारक्रोधपानाशनेहः प्राज्यायुर्वित्तो दीर्घदर्शी वदान्यः श्राद्धो गम्भीरः स्थूललक्षः क्षमावानार्यो निद्रालुर्दीर्धसूत्रः कृतज्ञः", text: "api ca alpavyāhārakrodhapānāśanehaḥ prājyāyurvitto dīrghadarśī vadānyaḥ śrāddho gambhīraḥ sthūlalakṣaḥ kṣamāvānāryo nidrālurdīrdhasūtraḥ kṛtajñaḥ" },
      { type: "verse", number: "14", sanskrit: "ऋजुर्विपश्चित्सुभगः सलज्जो भक्तो गुरूणां दृढसौहृदय्यः स्वप्ने सपद्मान् सविहङ्गमालांस्तोयाशयान् पश्यति तोयदांश्च", text: "ṛjurvipaścitsubhagaḥ salajjo bhakto gurūṇāṃ dṛḍhasauhṛdayyaḥ svapne sapadmān savihaṅgamālāṃstoyāśayān paśyati toyadāṃśca" },
      { type: "verse", number: "15", sanskrit: "उभयलक्षणसङ्करे तु संसर्गप्रकृतिः सर्वगुणसमुदितः समदोषप्रकृतिः तत्राद्यास्त्रयो नित्यातुराः दोषानुशयितप्रकृतित्वात् विशेषतश्च द्वन्द्वप्रकृतयः तेषु हि गुणमिश्रविकारकारिषु क्षुत्पिपासादिष्विवारोग्यव्यपदेशः तस्माद्विपरीतगुणेन विधिना दोषोपक्रमणीयोक्तेन तानुपाचरेत् समसर्वरसेन सात्म्येनान्त्यं यथर्तुविहितेन च", text: "ubhayalakṣaṇasaṅkare tu saṃsargaprakṛtiḥ sarvaguṇasamuditaḥ samadoṣaprakṛtiḥ tatrādyāstrayo nityāturāḥ doṣānuśayitaprakṛtitvāt viśeṣataśca dvandvaprakṛtayaḥ teṣu hi guṇamiśravikārakāriṣu kṣutpipāsādiṣvivārogyavyapadeśaḥ tasmādviparītaguṇena vidhinā doṣopakramaṇīyoktena tānupācaret samasarvarasena sātmyenāntyaṃ yathartuvihitena ca" },
      { type: "verse", number: "16", sanskrit: "दोषवच्च गुणैरपि सत्त्वादिभिः सप्त प्रकृतयो भवन्ति तास्तदभिनिर्वृत्तैरेव यथोक्तैः शौचादिभिर्जानीयात्", text: "doṣavacca guṇairapi sattvādibhiḥ sapta prakṛtayo bhavanti tāstadabhinirvṛttaireva yathoktaiḥ śaucādibhirjānīyāt" },
      { type: "verse", number: "17", sanskrit: "तथा पुनः सप्त प्रकृतयो जातिकुलदेशकालवयोबलप्रत्यात्मसंश्रयाः दृश्यन्ते हि पुरुषाणां जात्यादिनियतास्ते ते भावविशेषाः", text: "tathā punaḥ sapta prakṛtayo jātikuladeśakālavayobalapratyātmasaṃśrayāḥ dṛśyante hi puruṣāṇāṃ jātyādiniyatāste te bhāvaviśeṣāḥ" },
      { type: "verse", number: "18", sanskrit: "सत्त्वादीनां च तरतमयोगाच्छरीरविशेषेभ्यश्चान्योन्यानुविधायित्वाच्च भेदाश्रयमसङ्ख्येयं भवति शरीरमपि सत्त्वादीननुरुध्यते सत्त्वादयो ऽपि शरीरम्", text: "sattvādīnāṃ ca taratamayogāccharīraviśeṣebhyaścānyonyānuvidhāyitvācca bhedāśrayamasaṅkhyeyaṃ bhavati śarīramapi sattvādīnanurudhyate sattvādayo 'pi śarīram" },
      { type: "verse", number: "19", sanskrit: "सत्त्वाद्यसङ्ख्यभेदावेशाच्च रूपस्वरचरितानुकरणमप्यनूकशब्दवाच्यमसङ्ख्यभेदं भवति तदावेशस्त्वनन्तरजन्माभ्यासवासनया जन्यते तस्माद्देवमानुषतिर्यक्प्रेतनारकाणां तत्तद्विशेषाणां च यथायथमेवानूकं पुरुषस्यान्ववेक्षेत", text: "sattvādyasaṅkhyabhedāveśācca rūpasvaracaritānukaraṇamapyanūkaśabdavācyamasaṅkhyabhedaṃ bhavati tadāveśastvanantarajanmābhyāsavāsanayā janyate tasmāddevamānuṣatiryakpretanārakāṇāṃ tattadviśeṣāṇāṃ ca yathāyathamevānūkaṃ puruṣasyānvavekṣeta" },
      { type: "verse", number: "20", sanskrit: "वयस्त्रिविधं बालं मध्यं वृद्धं च तत्राषोडशाद्वर्षाद्बालम् आ षष्टेर्मध्यम् ततो वृद्धम् तेष्वपि स्तन्याहारोभयवृत्त्या बालं त्रिविधम् तस्मिन् देहप्रमाणवृद्धिः श्लेष्मोद्रेकश्च तेन बालस्य स्नेहमार्दवसौकुमार्याल्पक्रोधत्वसौभाग्यानि भवन्ति", text: "vayastrividhaṃ bālaṃ madhyaṃ vṛddhaṃ ca tatrāṣoḍaśādvarṣādbālam ā ṣaṣṭermadhyam tato vṛddham teṣvapi stanyāhārobhayavṛttyā bālaṃ trividham tasmin dehapramāṇavṛddhiḥ śleṣmodrekaśca tena bālasya snehamārdavasaukumāryālpakrodhatvasaubhāgyāni bhavanti" },
      { type: "verse", number: "21", sanskrit: "मध्यमपि त्रिविधं यौवनं सम्पूर्णत्वमपरिहानिश्च तस्मिन् पित्तोद्रेकः तेन दीप्ताग्निता प्रज्ञाधिक्यपरिपाकौ व्यवसायश्च तत्रात्रिंशतो यौवनमाचत्वारिंशतः सर्वधात्विन्द्रियबलवीर्यपौरुषस्मरणवचनविज्ञानप्रश्रयगुणसम्पूर्णत्वमतः परमपरिहानिः", text: "madhyamapi trividhaṃ yauvanaṃ sampūrṇatvamaparihāniśca tasmin pittodrekaḥ tena dīptāgnitā prajñādhikyaparipākau vyavasāyaśca tatrātriṃśato yauvanamācatvāriṃśataḥ sarvadhātvindriyabalavīryapauruṣasmaraṇavacanavijñānapraśrayaguṇasampūrṇatvamataḥ paramaparihāniḥ" },
      { type: "verse", number: "22", sanskrit: "वृद्धं तु शश्वत् क्षीयमाणधात्विन्द्रियादिगुणं वलीखलतिकासश्चसाग्निसादादिभिरभिभूयमानं जीर्णं भवनमिवाभिवृष्टमवसीदति तस्मिन्मारुतोद्रेकः तेन श्लथसारमांससन्ध्यस्थिता त्वक्पारुष्यमवनामः कायस्य वेपथुः कासः श्वासः श्लेष्मसिङ्घाणकोदीरणं धातुक्षयश्च", text: "vṛddhaṃ tu śaśvat kṣīyamāṇadhātvindriyādiguṇaṃ valīkhalatikāsaścasāgnisādādibhirabhibhūyamānaṃ jīrṇaṃ bhavanamivābhivṛṣṭamavasīdati tasminmārutodrekaḥ tena ślathasāramāṃsasandhyasthitā tvakpāruṣyamavanāmaḥ kāyasya vepathuḥ kāsaḥ śvāsaḥ śleṣmasiṅghāṇakodīraṇaṃ dhātukṣayaśca" },
      { type: "verse", number: "23", sanskrit: "अन्ये पुनराहः बाल्यं वृद्धिः प्रभा मेधां त्वक्शुक्राक्षिश्नुतीन्द्रियम् दशकेषु क्रमाद्व्येति मनस्सर्वेन्द्रियाणि च", text: "anye punarāhaḥ bālyaṃ vṛddhiḥ prabhā medhāṃ tvakśukrākṣiśnutīndriyam daśakeṣu kramādvyeti manassarvendriyāṇi ca" },
      { type: "verse", number: "24", sanskrit: "एवं वर्षतमायुषः प्रमाणमस्मिन् काले सन्ति पुनः कर्मविशेषादूनाधिकवर्षशतजीविनो मनुष्याः तेषां यथोक्तैः प्रकृतिविशेषैरायुषः प्रमाणमुपलभ्य वयस्त्रिधा विभजेत्", text: "evaṃ varṣatamāyuṣaḥ pramāṇamasmin kāle santi punaḥ karmaviśeṣādūnādhikavarṣaśatajīvino manuṣyāḥ teṣāṃ yathoktaiḥ prakṛtiviśeṣairāyuṣaḥ pramāṇamupalabhya vayastridhā vibhajet" },
      { type: "verse", number: "25", sanskrit: "अपि च वर्षं वर्षं क्षयं याति नृणां याते शते शते आयुषो ऽपुण्यबाहुल्याद्यदा यन्मानमिष्यते", text: "api ca varṣaṃ varṣaṃ kṣayaṃ yāti nṛṇāṃ yāte śate śate āyuṣo 'puṇyabāhulyādyadā yanmānamiṣyate" },
      { type: "verse", number: "26", sanskrit: "बलमपि त्रिविधं भवति सहजं कालकृतं युक्तिकृतं च तत्र सहजं देहसत्त्वयोः प्राकृतम् कालकृतमृतुविभागजं वयःकृतं च युक्तिकृतं पुनराहारविहारोत्थमूर्जस्करयोगजं च तद्वृद्धिकरास्त्विमे च भावा भवन्ति तद्यथा बलवत्पुरुषे देशे जन्म तद्विधे च काले सुखश्च कालयोगो बीजक्षेत्रगुणशरीराहारसत्त्वसम्पत्तयः स्वमावो यौवनं व्यायामो हर्षश्च", text: "balamapi trividhaṃ bhavati sahajaṃ kālakṛtaṃ yuktikṛtaṃ ca tatra sahajaṃ dehasattvayoḥ prākṛtam kālakṛtamṛtuvibhāgajaṃ vayaḥkṛtaṃ ca yuktikṛtaṃ punarāhāravihārotthamūrjaskarayogajaṃ ca tadvṛddhikarāstvime ca bhāvā bhavanti tadyathā balavatpuruṣe deśe janma tadvidhe ca kāle sukhaśca kālayogo bījakṣetraguṇaśarīrāhārasattvasampattayaḥ svamāvo yauvanaṃ vyāyāmo harṣaśca" },
      { type: "verse", number: "27", sanskrit: "तथा साराण्यष्टौ त्वग्रक्तमांसमेदो ऽस्थिमज्जशुक्रसत्वात्मकान्युत्तरोत्तरवराणि बलमानज्ञानार्थमुपदिश्यन्न्ते अपि च न मुह्येद्देहमात्रदर्शनादेव भिषगयमुपचयेन माहाशरीरत्वाद्वा बलवानयं कृशत्वादल्पशरीरत्वाद्वाल्पबल इति तच्चोभयमप्यन्यथा दृष्टं गजसिंहे", text: "tathā sārāṇyaṣṭau tvagraktamāṃsamedo 'sthimajjaśukrasatvātmakānyuttarottaravarāṇi balamānajñānārthamupadiśyannte api ca na muhyeddehamātradarśanādeva bhiṣagayamupacayena māhāśarīratvādvā balavānayaṃ kṛśatvādalpaśarīratvādvālpabala iti taccobhayamapyanyathā dṛṣṭaṃ gajasiṃhe" },
      { type: "verse", number: "28", sanskrit: "तत्र सर्वैः सारैरुपेतो भवत्यतिबलः परमगौरवयुक्तः क्लेशक्षमः सर्वारम्भेष्वात्मनि प्रत्याशावान् कल्याणाभिनिवेशी स्थिरशरीरः सुसमाहितगतिः सानुनादस्निग्धगम्भीरमहास्वरः सुखैश्वर्यवित्तोपभोग सम्मानभाङ्मन्दजरामयः प्रायस्तुल्यगुणविस्तीर्णापत्यो दीर्घायुश्च तद्विपरीतस्त्वसारः मध्यो मध्यगुणः", text: "tatra sarvaiḥ sārairupeto bhavatyatibalaḥ paramagauravayuktaḥ kleśakṣamaḥ sarvārambheṣvātmani pratyāśāvān kalyāṇābhiniveśī sthiraśarīraḥ susamāhitagatiḥ sānunādasnigdhagambhīramahāsvaraḥ sukhaiśvaryavittopabhoga sammānabhāṅmandajarāmayaḥ prāyastulyaguṇavistīrṇāpatyo dīrghāyuśca tadviparītastvasāraḥ madhyo madhyaguṇaḥ" },
      { type: "verse", number: "29", sanskrit: "प्रमाणं पुनः स्वाङ्गुलैः पादाङ्गुष्ठप्रदेशिन्यौ द्व्यङ्गुलायते तिस्रो ऽन्याः क्रमेणोत्तरोत्तरं पञ्चमभागहीनास्तन्नखहीना वा चतुरङ्गुलायताः पृथक् प्रपदपादतलपार्ष्णयः षट्पञ्चचतुरङ्गुलविस्तृताश्चतुर्दशैवायामेन पादश्चतुर्दशैव परिणाहेन तथा गुल्फौ जङ्घामध्यं च चतुरङ्गुलोत्सेधः पादः अष्टादशायामा जङ्घा ऊरुश्च चतुरङ्गुलं जानु त्रिंशदङ्गुलपरिणाह ऊरुः षडायामेन", text: "pramāṇaṃ punaḥ svāṅgulaiḥ pādāṅguṣṭhapradeśinyau dvyaṅgulāyate tisro 'nyāḥ krameṇottarottaraṃ pañcamabhāgahīnāstannakhahīnā vā caturaṅgulāyatāḥ pṛthak prapadapādatalapārṣṇayaḥ ṣaṭpañcacaturaṅgulavistṛtāścaturdaśaivāyāmena pādaścaturdaśaiva pariṇāhena tathā gulphau jaṅghāmadhyaṃ ca caturaṅgulotsedhaḥ pādaḥ aṣṭādaśāyāmā jaṅghā ūruśca caturaṅgulaṃ jānu triṃśadaṅgulapariṇāha ūruḥ ṣaḍāyāmena" },
      { type: "verse", number: "30", sanskrit: "मुष्क्कमेढ्रावष्टपञ्चपरिणाहौ षोडशविस्तारा कटी पञ्चाशत्परिणाहा दशाङ्गुलं बस्तिशिरः द्वादशाङ्गुलमुदरम् दशविस्तारे द्वादशायामे पार्श्वे द्वादशोत्सेधं त्रिकम् अष्टादशोत्सेधं पृष्ठम् द्वादशकं स्तनान्तरम् द्व्यङ्गुलं स्तनपर्यन्तम् चतुर्विंशत्यङ्गुलविशालं द्वादशोत्सेधमुरः द्व्यङ्गुलं हृदयम् अष्टकौ स्कन्धे कक्षे च षट्कावंसौ षोडशकौ प्रबाहू पञ्चदशकौ प्रपाणी द्वादशाङ्गुलौ पाणी तत्रापि पञ्चाङ्गुला मध्यमाङ्गुलिः ततो ऽर्धाङ्गुलहीने प्रदेशिन्यनामिके सार्धत्र्यङ्गुलौ कनिष्ठिकाङ्गुष्ठौ चतुरङ्गुलोत्सेधा द्वाविंशतिपरिणाहा शिरोधरा द्वादशोत्सेधं चतुर्विंशतिपरिणाहमाननम्", text: "muṣkkameḍhrāvaṣṭapañcapariṇāhau ṣoḍaśavistārā kaṭī pañcāśatpariṇāhā daśāṅgulaṃ bastiśiraḥ dvādaśāṅgulamudaram daśavistāre dvādaśāyāme pārśve dvādaśotsedhaṃ trikam aṣṭādaśotsedhaṃ pṛṣṭham dvādaśakaṃ stanāntaram dvyaṅgulaṃ stanaparyantam caturviṃśatyaṅgulaviśālaṃ dvādaśotsedhamuraḥ dvyaṅgulaṃ hṛdayam aṣṭakau skandhe kakṣe ca ṣaṭkāvaṃsau ṣoḍaśakau prabāhū pañcadaśakau prapāṇī dvādaśāṅgulau pāṇī tatrāpi pañcāṅgulā madhyamāṅguliḥ tato 'rdhāṅgulahīne pradeśinyanāmike sārdhatryaṅgulau kaniṣṭhikāṅguṣṭhau caturaṅgulotsedhā dvāviṃśatipariṇāhā śirodharā dvādaśotsedhaṃ caturviṃśatipariṇāhamānanam" },
      { type: "verse", number: "31", sanskrit: "पञ्चाङ्गुलमास्यम् चतुरङ्गुलं पृथक् चिबुकौष्ठनासादृष्ट्यन्तरकर्णललाटम् त्रिभागाङ्गुलविस्तारा नासापुटमर्यादा द्व्यङ्गुलायतमङ्गुष्ठोदरविस्तृतं नेत्रम् तत्र शुक्लात्तृतीयांशं कृष्णम् कृष्णान्नवमांशा मसूरदलमात्रा दृष्टिः षडङ्गुलोत्सेधं द्वात्रिंशत्परिणाहं शिर इति सर्वं पुनः शरीरमङ्गुलानि चतुरशीतिः तदायामविस्तारसमं सममुच्यते तत्र यथोक्तपरिमाणमिष्टमनिष्टं हीनमधिकं वा तथा ह्रस्वदीर्घगौरकृष्णरोमारोमस्थूलकृशं चेति", text: "pañcāṅgulamāsyam caturaṅgulaṃ pṛthak cibukauṣṭhanāsādṛṣṭyantarakarṇalalāṭam tribhāgāṅgulavistārā nāsāpuṭamaryādā dvyaṅgulāyatamaṅguṣṭhodaravistṛtaṃ netram tatra śuklāttṛtīyāṃśaṃ kṛṣṇam kṛṣṇānnavamāṃśā masūradalamātrā dṛṣṭiḥ ṣaḍaṅgulotsedhaṃ dvātriṃśatpariṇāhaṃ śira iti sarvaṃ punaḥ śarīramaṅgulāni caturaśītiḥ tadāyāmavistārasamaṃ samamucyate tatra yathoktaparimāṇamiṣṭamaniṣṭaṃ hīnamadhikaṃ vā tathā hrasvadīrghagaurakṛṣṇaromāromasthūlakṛśaṃ ceti" },
      { type: "verse", number: "32", sanskrit: "इष्टं पुनर्महाशरीरदर्शनवदनहनुस्तनाग्रपृष्ठस्वरमुपचितोरुस्थिक्कटीवक्षोग्रीवातालुकमुभयगुणपाणिपादचिबुककर्णललाटम् सूक्ष्मास्थिदन्तनखाङ्गुलिपर्वकेशम् दीर्घाङ्गुलिसक्थिबाहूच्छ्वासेक्षितनेत्रजिह्वम् विस्तीर्णास्याधरौष्ठजिह्वाललाटकर्णपठिवक्षो ऽल्पमेढ्रग्रीवाकेशम् स्निग्धत्वक्कचकरजनयनस्वनम् स्थिरेन्द्रियत्वङ्नखकेशपार्श्वम् गम्भीरनाभिसन्धिस्वरम् गूढजत्रुपृष्ठवंशदन्तमूलम् रक्तताल्वोष्ठनखनेत्रान्तमाताम्रजिह्वाहस्तपादतलम् कृष्णकेशभ्रूनेत्रपक्ष्मतारकम् शुक्लशुक्लमण्डलदशनचरितमुन्नतचित्तरकन्धललाटोदरमुखनखपादम् नीचैर्बद्धकर्णस्तननासाग्रचङ्क्रमणम् घनस्कन्धकन्धरादन्ताङ्गुलित्वक्सौहार्दम् तनुनखमध्यजिह्वम् वृत्तस्फिग्ग्रीवानखम् समपृष्ठदन्तललाटेक्षितम् तथानुपूर्ववृत्तावूरू दक्षिणावर्तनाभिः प्रकृष्टान्तरौस्तनौ भ्रुवौ च कूर्माकृतयो नखाः पादौ च र्ज्वास्यं नासावंशश्च अनुल्बणे हनू वेषश्च श्लक्ष्णं तालु जिह्वा च नातिस्थूलकृशावोष्ठौ देहबन्धश्च सस्पन्दं हृदयं शङ्खौ मन्ये च सोष्मतालुपादोदरं निश्वासश्च पृष्ठतो ऽवनतौ रोमशौ च कर्णौ ईषत्प्रलम्बिन्यौ भ्रुवौ वलिनं सुश्लिष्टसन्ध्यर्धचन्द्राकृतिललाटमातपत्रोपमं शिरः नैकमूला मृदवः केशाः दृढं गूढं सिरास्थिसन्धि प्रकृतियुक्तानि वातमूत्रपुरीषगुह्यानि हसितरुदितानि च चेष्टितानि तथा स्नातानुलिप्तमधःप्रसृतानुपूर्व्या शुष्यदिष्टं शरीरमिति भवति चात्र", text: "iṣṭaṃ punarmahāśarīradarśanavadanahanustanāgrapṛṣṭhasvaramupacitorusthikkaṭīvakṣogrīvātālukamubhayaguṇapāṇipādacibukakarṇalalāṭam sūkṣmāsthidantanakhāṅguliparvakeśam dīrghāṅgulisakthibāhūcchvāsekṣitanetrajihvam vistīrṇāsyādharauṣṭhajihvālalāṭakarṇapaṭhivakṣo 'lpameḍhragrīvākeśam snigdhatvakkacakarajanayanasvanam sthirendriyatvaṅnakhakeśapārśvam gambhīranābhisandhisvaram gūḍhajatrupṛṣṭhavaṃśadantamūlam raktatālvoṣṭhanakhanetrāntamātāmrajihvāhastapādatalam kṛṣṇakeśabhrūnetrapakṣmatārakam śuklaśuklamaṇḍaladaśanacaritamunnatacittarakandhalalāṭodaramukhanakhapādam nīcairbaddhakarṇastananāsāgracaṅkramaṇam ghanaskandhakandharādantāṅgulitvaksauhārdam tanunakhamadhyajihvam vṛttasphiggrīvānakham samapṛṣṭhadantalalāṭekṣitam tathānupūrvavṛttāvūrū dakṣiṇāvartanābhiḥ prakṛṣṭāntaraustanau bhruvau ca kūrmākṛtayo nakhāḥ pādau ca rjvāsyaṃ nāsāvaṃśaśca anulbaṇe hanū veṣaśca ślakṣṇaṃ tālu jihvā ca nātisthūlakṛśāvoṣṭhau dehabandhaśca saspandaṃ hṛdayaṃ śaṅkhau manye ca soṣmatālupādodaraṃ niśvāsaśca pṛṣṭhato 'vanatau romaśau ca karṇau īṣatpralambinyau bhruvau valinaṃ suśliṣṭasandhyardhacandrākṛtilalāṭamātapatropamaṃ śiraḥ naikamūlā mṛdavaḥ keśāḥ dṛḍhaṃ gūḍhaṃ sirāsthisandhi prakṛtiyuktāni vātamūtrapurīṣaguhyāni hasitaruditāni ca ceṣṭitāni tathā snātānuliptamadhaḥprasṛtānupūrvyā śuṣyadiṣṭaṃ śarīramiti bhavati cātra" },
      { type: "verse", number: "33", sanskrit: "उत्तरोत्तरसुक्षेत्रं गर्भीद्भवति नीरुजम् आयामज्ञानविज्ञानेर्वर्धमानं शनैश्शुभम्", text: "uttarottarasukṣetraṃ garbhīdbhavati nīrujam āyāmajñānavijñānervardhamānaṃ śanaiśśubham" },
      { type: "verse", number: "34", sanskrit: "इति सर्वगुणोपेते शरीरे शरदां शतम् आयुरैश्वर्यमिष्टाश्च सर्वे भावाः प्रतिष्ठिताः", text: "iti sarvaguṇopete śarīre śaradāṃ śatam āyuraiśvaryamiṣṭāśca sarve bhāvāḥ pratiṣṭhitāḥ" },
      { type: "verse", number: "35", sanskrit: "अनुत्सेकमदैन्यं च सुखं दुःखं च सेवते सत्ववांस्तभ्यमानस्तु राजसो नैव तामसः", text: "anutsekamadainyaṃ ca sukhaṃ duḥkhaṃ ca sevate satvavāṃstabhyamānastu rājaso naiva tāmasaḥ" },
      { type: "verse", number: "36", sanskrit: "दानशीलदयासत्यब्रह्मचर्यकृतज्ञताः रसायनानि मैत्री च पुण्यायुर्वृद्धिकृद्गणः", text: "dānaśīladayāsatyabrahmacaryakṛtajñatāḥ rasāyanāni maitrī ca puṇyāyurvṛddhikṛdgaṇaḥ" },
    ],
  },
  {
    sthana: "Шарирастхана",
    number: 9,
    lang: "sa",
    content: [
      { type: "heading", heading: "Стри джана — анатомия женщины" },
      { type: "text", text: "Глава 9 Шарирастханы Астанга-санграхи — «Стри джана» — посвящена анатомическим и эмбриологическим аспектам: анатомия женщины." },
      { type: "verse", number: "1", sanskrit: "अथातो विकृतिविज्ञानीयमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vikṛtivijñānīyamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "स्वस्थानामातुराणां वा पुरुषाणां देहान्तराभिलाषिणामौषधविषयमतीताः सकलशरीरव्यापिनो दोषा घना घना इव वर्षमायुषः क्षयं सूचयन्तो ऽकस्मात्स्वभावविपर्यासं जनयन्ति तत्समासतो रिष्टमित्याहुः", text: "svasthānāmāturāṇāṃ vā puruṣāṇāṃ dehāntarābhilāṣiṇāmauṣadhaviṣayamatītāḥ sakalaśarīravyāpino doṣā ghanā ghanā iva varṣamāyuṣaḥ kṣayaṃ sūcayanto 'kasmātsvabhāvaviparyāsaṃ janayanti tatsamāsato riṣṭamityāhuḥ" },
      { type: "verse", number: "3", sanskrit: "तत्र गौरः श्यामः कृष्णो गौरश्यामः कृष्णश्याम इति देहप्रकृतिवर्णाः तद्भेदाश्च पद्मगौरादयः नीलश्यामताम्रहारिद्रशुक्लादयस्तु विकृतयः तत्र प्रकृतिविकृतिवर्णौ युगपदङ्गे ऽङ्गैकदेशे वा मरणाय एतेन ग्लान्युपचयशोकहर्षरौक्ष्यस्नेहादयस्तथा प्रकृतिभेदीयोक्तानां महदुपचयसूक्ष्मदीर्घाणां सर्वेषां च दोषादिभागेन प्रतिनियतानां भावानाम्निमित्ततो ऽन्यथात्वमुक्तं भवति", text: "tatra gauraḥ śyāmaḥ kṛṣṇo gauraśyāmaḥ kṛṣṇaśyāma iti dehaprakṛtivarṇāḥ tadbhedāśca padmagaurādayaḥ nīlaśyāmatāmrahāridraśuklādayastu vikṛtayaḥ tatra prakṛtivikṛtivarṇau yugapadaṅge 'ṅgaikadeśe vā maraṇāya etena glānyupacayaśokaharṣaraukṣyasnehādayastathā prakṛtibhedīyoktānāṃ mahadupacayasūkṣmadīrghāṇāṃ sarveṣāṃ ca doṣādibhāgena pratiniyatānāṃ bhāvānāmnimittato 'nyathātvamuktaṃ bhavati" },
      { type: "verse", number: "4", sanskrit: "छायास्तु शरीरे पञ्च तत्र खादमलखङ्गाकाशनीलनिर्मला सस्नेहा सप्रभेव वातात् पांसुभस्मरूक्षा रजो ऽरुणा श्यावा निष्प्रभा स्वेदमलगन्धिः तेजसो हुतहुताशनविद्युत्तप्ततपनीयरक्ता दृष्टिसुखा अम्भसो वैडूर्येन्द्रनीलविमला घना सुस्निग्धा भुवो रुचिराभा घना स्थिरा स्निग्धा शुद्धा श्यामा श्वेता च तासां वायव्या विनाशाय क्लेशाय चातिमहते शेषास्तु सुखोदयाः", text: "chāyāstu śarīre pañca tatra khādamalakhaṅgākāśanīlanirmalā sasnehā saprabheva vātāt pāṃsubhasmarūkṣā rajo 'ruṇā śyāvā niṣprabhā svedamalagandhiḥ tejaso hutahutāśanavidyuttaptatapanīyaraktā dṛṣṭisukhā ambhaso vaiḍūryendranīlavimalā ghanā susnigdhā bhuvo rucirābhā ghanā sthirā snigdhā śuddhā śyāmā śvetā ca tāsāṃ vāyavyā vināśāya kleśāya cātimahate śeṣāstu sukhodayāḥ" },
      { type: "verse", number: "5", sanskrit: "सप्त प्रभा रक्ता पीता पाण्डुरा सितासिता श्यावा हरिता च ताः स्निग्धा विकासिन्यो ऽमलाः शुभाः विपरीतास्त्वशुभाः", text: "sapta prabhā raktā pītā pāṇḍurā sitāsitā śyāvā haritā ca tāḥ snigdhā vikāsinyo 'malāḥ śubhāḥ viparītāstvaśubhāḥ" },
      { type: "verse", number: "6", sanskrit: "तयोर्विशेषाः छायावर्णमाक्रामत्यासन्ना च लक्ष्यते पञ्चभूतात्मिका च प्रभा तु वर्णं प्रकाशयति विप्रकृष्टाल्लक्ष्यते तेजःप्रभवैव च", text: "tayorviśeṣāḥ chāyāvarṇamākrāmatyāsannā ca lakṣyate pañcabhūtātmikā ca prabhā tu varṇaṃ prakāśayati viprakṛṣṭāllakṣyate tejaḥprabhavaiva ca" },
      { type: "verse", number: "7", sanskrit: "यस्य दृष्टौ प्रतिच्छायामयी कुमारिका न दृश्यते स परासुः", text: "yasya dṛṣṭau praticchāyāmayī kumārikā na dṛśyate sa parāsuḥ" },
      { type: "verse", number: "8", sanskrit: "यस्यातपादर्शादिष्वकस्मात् प्रतिच्छाया छिन्ना भिन्ना हीनाधिकाकुला नष्टा जिह्मा ऽन्यथा वा विकृता वा दृश्यते यस्य ललाटं न स्विद्यति यस्य केशरोमाण्यनभ्यक्तान्यभ्यक्तवद् दृश्यन्ते नयने चातिप्रविष्टे निर्गते विस्तृते सङ्क्षिप्ते सङ्क्षिप्तभ्रुणी विनतभ्रुणी जिह्मो विषमे विभ्रान्तदर्शने हीनदर्शने नकुलाभे कपोताभे अलातवर्णे नीलादिविकृतवर्णे अतिचले स्तब्धस्रस्ते प्रस्रुते अत्युन्मिषिते अतिनिमिषिते लुलितपक्ष्मणी वा नासिका वातिविवृतातिसंवृता कुटिला स्फुटिता पिटकाचिता शुष्का वा स गतायुः", text: "yasyātapādarśādiṣvakasmāt praticchāyā chinnā bhinnā hīnādhikākulā naṣṭā jihmā 'nyathā vā vikṛtā vā dṛśyate yasya lalāṭaṃ na svidyati yasya keśaromāṇyanabhyaktānyabhyaktavad dṛśyante nayane cātipraviṣṭe nirgate vistṛte saṅkṣipte saṅkṣiptabhruṇī vinatabhruṇī jihmo viṣame vibhrāntadarśane hīnadarśane nakulābhe kapotābhe alātavarṇe nīlādivikṛtavarṇe aticale stabdhasraste prasrute atyunmiṣite atinimiṣite lulitapakṣmaṇī vā nāsikā vātivivṛtātisaṃvṛtā kuṭilā sphuṭitā piṭakācitā śuṣkā vā sa gatāyuḥ" },
      { type: "verse", number: "9", sanskrit: "यस्याधोधरौष्ठो यात्युत्तरौष्ठश्चोर्ध्वमुभौ वा पक्वजम्बूनीलौ दन्ता वातिरूक्षास्ताम्राः श्यामाः पङ्किताः पुष्पिताः सशर्करा वा सहसा वा पतन्ति जिह्वा वा जिह्मास्तब्धा सुप्तावलिप्ता गुर्वी श्यावा शूना शुष्का विसर्पिणी कण्टकाचितेव वा यस्य गण्डललाटहनुबन्धानि स्थानाच्च्युतानीव स्रस्तानि यस्य न धत्ते शिरः शिरोधरां पृष्ठं वा स्वभारम् हनू वा वृषणावतो विपर्ययो वा यस्य मूत्रमत्युष्णम् यस्य विषदोषाद्विना स्वेभ्यः सरोमकूपेभ्यो रक्तं प्रवर्तते यस्यानिमित्तमङ्गान्यतिलघून्यतिगुरूणि वा स्युः समुमूर्षुः", text: "yasyādhodharauṣṭho yātyuttarauṣṭhaścordhvamubhau vā pakvajambūnīlau dantā vātirūkṣāstāmrāḥ śyāmāḥ paṅkitāḥ puṣpitāḥ saśarkarā vā sahasā vā patanti jihvā vā jihmāstabdhā suptāvaliptā gurvī śyāvā śūnā śuṣkā visarpiṇī kaṇṭakāciteva vā yasya gaṇḍalalāṭahanubandhāni sthānāccyutānīva srastāni yasya na dhatte śiraḥ śirodharāṃ pṛṣṭhaṃ vā svabhāram hanū vā vṛṣaṇāvato viparyayo vā yasya mūtramatyuṣṇam yasya viṣadoṣādvinā svebhyaḥ saromakūpebhyo raktaṃ pravartate yasyānimittamaṅgānyatilaghūnyatigurūṇi vā syuḥ samumūrṣuḥ" },
      { type: "verse", number: "10", sanskrit: "यस्यैको ऽनेको वा स्वरो गद्गदो व्यक्तः क्षामो दीनो वा सहसा लक्ष्यते यो वा विवक्षुर्मुह्यति यस्या वा वदतो भृशमूर्ध्वमुरो रुजति यस्योच्छ्वासो ऽतिदीर्घो ऽतिह्रस्वः पूतिगन्धिः सुगन्धिर्वा यस्याङ्गुलय आयम्यमाना न स्फुटेयुः यस्यान्यो ऽन्यो ऽपि क्षुतगतमूत्रणादिषु स्वभावातीतः शब्दः यस्येष्टो ऽनिष्टो वा माल्यफलचन्दनकुणपादिगन्धो देहमुखमलव्रणवस्त्रादिषु यस्य शरीरं वैरस्यात्सौरस्याद्वात्यर्थं यूकामक्षिकादयस्त्यजन्ति भजन्ति वा यस्य सततोष्मस्वङ्गावयवेषु शौत्यं शीतेषु वा कुमुदोत्पलानुकार्यतिशैत्यमतिस्वेदो ऽतिस्तम्भो विगतमांसशोणितेष्विव च स्रंसः यस्य च योगोतियोगो वा शरीरे युगपन्महाभूतानां दृश्यते सर्वे ते कालपक्वा इति भवति चात्र", text: "yasyaiko 'neko vā svaro gadgado vyaktaḥ kṣāmo dīno vā sahasā lakṣyate yo vā vivakṣurmuhyati yasyā vā vadato bhṛśamūrdhvamuro rujati yasyocchvāso 'tidīrgho 'tihrasvaḥ pūtigandhiḥ sugandhirvā yasyāṅgulaya āyamyamānā na sphuṭeyuḥ yasyānyo 'nyo 'pi kṣutagatamūtraṇādiṣu svabhāvātītaḥ śabdaḥ yasyeṣṭo 'niṣṭo vā mālyaphalacandanakuṇapādigandho dehamukhamalavraṇavastrādiṣu yasya śarīraṃ vairasyātsaurasyādvātyarthaṃ yūkāmakṣikādayastyajanti bhajanti vā yasya satatoṣmasvaṅgāvayaveṣu śautyaṃ śīteṣu vā kumudotpalānukāryatiśaityamatisvedo 'tistambho vigatamāṃsaśoṇiteṣviva ca sraṃsaḥ yasya ca yogotiyogo vā śarīre yugapanmahābhūtānāṃ dṛśyate sarve te kālapakvā iti bhavati cātra" },
      { type: "verse", number: "11", sanskrit: "यस्यापूर्वास्सिरालेखा बालेन्द्वाकृतयो ऽपि वा ललाटे बस्तिशीर्षे वा षण्मासान्न स जीवति", text: "yasyāpūrvāssirālekhā bālendvākṛtayo 'pi vā lalāṭe bastiśīrṣe vā ṣaṇmāsānna sa jīvati" },
      { type: "verse", number: "12", sanskrit: "पद्मिनीपत्रवत्तोयं शरीरे यस्य देहिनः प्लवते प्लवमानस्य षण्मासं तस्य जीवितम्", text: "padminīpatravattoyaṃ śarīre yasya dehinaḥ plavate plavamānasya ṣaṇmāsaṃ tasya jīvitam" },
      { type: "verse", number: "13", sanskrit: "हरिताभाः सिरा यस्य रोमकूपाश्च संवृताः सो ऽम्लाभिलाषी पुरुषः पित्तान्मरणमश्नुते", text: "haritābhāḥ sirā yasya romakūpāśca saṃvṛtāḥ so 'mlābhilāṣī puruṣaḥ pittānmaraṇamaśnute" },
      { type: "verse", number: "14", sanskrit: "यस्य गोमयचूर्णाभं चूर्णं मूर्ध्नि मुखे ऽपि वा सस्नेहं मूर्ध्नि धूमो वा मासान्तं तस्य जीवितम्", text: "yasya gomayacūrṇābhaṃ cūrṇaṃ mūrdhni mukhe 'pi vā sasnehaṃ mūrdhni dhūmo vā māsāntaṃ tasya jīvitam" },
      { type: "verse", number: "15", sanskrit: "मूर्ध्नि भ्रुवोर्वा कुर्वन्ति सीमन्तावर्तका नवाः मृत्युं स्वस्थस्य षड्रात्रात्रिरात्रादातुरस्य तु", text: "mūrdhni bhruvorvā kurvanti sīmantāvartakā navāḥ mṛtyuṃ svasthasya ṣaḍrātrātrirātrādāturasya tu" },
      { type: "verse", number: "16", sanskrit: "यस्य स्नातानुलिप्तस्य पूर्वं शुष्यत्युरो भृशम् आर्द्रेषु सर्वगात्रेषु सो ऽर्धमासं न जीवति", text: "yasya snātānuliptasya pūrvaṃ śuṣyatyuro bhṛśam ārdreṣu sarvagātreṣu so 'rdhamāsaṃ na jīvati" },
      { type: "verse", number: "17", sanskrit: "उरस्यूष्मा भवेद्यस्य जठरे चातिशीतता भिन्नं पुरीषं तृष्णा च यथा प्रेतस्तथैव सः", text: "urasyūṣmā bhavedyasya jaṭhare cātiśītatā bhinnaṃ purīṣaṃ tṛṣṇā ca yathā pretastathaiva saḥ" },
      { type: "verse", number: "18", sanskrit: "मूत्रं पुरीषं निष्ठ्यूतं शुक्रं चाप्सु निमज्जति निष्ठ्यूतं बहुर्वर्णं वा यस्य मासात्स नश्यति", text: "mūtraṃ purīṣaṃ niṣṭhyūtaṃ śukraṃ cāpsu nimajjati niṣṭhyūtaṃ bahurvarṇaṃ vā yasya māsātsa naśyati" },
      { type: "verse", number: "19", sanskrit: "स्वरस्य दुर्बलीभावं हानिं वा बलवर्णयोः रोगवृद्धिमयुक्त्या च दृष्ट्वा मरणमादिशेत्", text: "svarasya durbalībhāvaṃ hāniṃ vā balavarṇayoḥ rogavṛddhimayuktyā ca dṛṣṭvā maraṇamādiśet" },
      { type: "verse", number: "20", sanskrit: "अपस्वरं भाषमाणं प्राप्तं मरणमात्मनः श्रोतारं चास्य शब्दस्य दूरतः परिवर्जयेत्", text: "apasvaraṃ bhāṣamāṇaṃ prāptaṃ maraṇamātmanaḥ śrotāraṃ cāsya śabdasya dūrataḥ parivarjayet" },
      { type: "verse", number: "21", sanskrit: "ऊर्ध्वश्वासं गतोष्माणं शूलोपहतवङ्क्षणम् शर्म चानधिगच्छन्तं बुद्धिमान् परिवर्जयेत्", text: "ūrdhvaśvāsaṃ gatoṣmāṇaṃ śūlopahatavaṅkṣaṇam śarma cānadhigacchantaṃ buddhimān parivarjayet" },
      { type: "verse", number: "22", sanskrit: "यो जातशीतपिटकः शीताङ्गो वा विदह्यते उष्णद्वेषी च शीतार्तः स प्रेताधिपगोचरः", text: "yo jātaśītapiṭakaḥ śītāṅgo vā vidahyate uṣṇadveṣī ca śītārtaḥ sa pretādhipagocaraḥ" },
      { type: "verse", number: "23", sanskrit: "यस्य रज्जुरिवच्छाया कण्ठे सक्तोपलक्ष्यते अवश्यं कृष्यते जन्तुः सो ऽचिराद्यमकिङ्करैः", text: "yasya rajjurivacchāyā kaṇṭhe saktopalakṣyate avaśyaṃ kṛṣyate jantuḥ so 'cirādyamakiṅkaraiḥ" },
    ],
  },
  {
    sthana: "Шарирастхана",
    number: 10,
    lang: "sa",
    content: [
      { type: "heading", heading: "Дхату санкхья — исчисление тканей" },
      { type: "text", text: "Глава 10 Шарирастханы Астанга-санграхи — «Дхату санкхья» — посвящена анатомическим и эмбриологическим аспектам: исчисление тканей." },
      { type: "verse", number: "1", sanskrit: "अथातो विकृतेहाविज्ञानीयमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vikṛtehāvijñānīyamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "घनीभूतमिवाकाशमाकाशमिव यो घनम् अमूर्तामिव मूर्तं च मूर्तं वामूर्तवत् स्थितम्", text: "ghanībhūtamivākāśamākāśamiva yo ghanam amūrtāmiva mūrtaṃ ca mūrtaṃ vāmūrtavat sthitam" },
      { type: "verse", number: "3", sanskrit: "तेजस्व्यतेजस्तद्वच्च शुक्लं कृष्णमसच्च सत् अनेत्ररोगश्चन्द्रं च बहुरूपमलाञ्छनम्", text: "tejasvyatejastadvacca śuklaṃ kṛṣṇamasacca sat anetrarogaścandraṃ ca bahurūpamalāñchanam" },
      { type: "verse", number: "4", sanskrit: "जाग्रद्रक्षांसि गन्धर्ववन् प्रेतानन्यांश्च तद्विधान् रूपं व्याकृति तद्वच्च यः पश्यति स नश्यति", text: "jāgradrakṣāṃsi gandharvavan pretānanyāṃśca tadvidhān rūpaṃ vyākṛti tadvacca yaḥ paśyati sa naśyati" },
      { type: "verse", number: "5", sanskrit: "सप्तर्षीणां समीपस्थां यो न पश्यत्यरुन्धतीम् ध्रुवमाकाशगङ्गां वा न स पश्यति तां समाम्", text: "saptarṣīṇāṃ samīpasthāṃ yo na paśyatyarundhatīm dhruvamākāśagaṅgāṃ vā na sa paśyati tāṃ samām" },
      { type: "verse", number: "6", sanskrit: "मेघतोयौघनिर्घोषवीणापणववेणुजान् शृणोत्यन्यांश्च यः शब्दानसतो न सतो ऽपि वा", text: "meghatoyaughanirghoṣavīṇāpaṇavaveṇujān śṛṇotyanyāṃśca yaḥ śabdānasato na sato 'pi vā" },
      { type: "verse", number: "7", sanskrit: "निष्पीड्य कर्णौ शृणुयान्न यो धुकधुकास्वनम् तद्वद्गन्धरसस्पर्शान्मन्यते यो विपर्ययात्", text: "niṣpīḍya karṇau śṛṇuyānna yo dhukadhukāsvanam tadvadgandharasasparśānmanyate yo viparyayāt" },
      { type: "verse", number: "8", sanskrit: "सर्वशो वा न यो यश्च दीपगन्धं न जिघ्रति विधिना यस्य दोषाय स्वास्थ्यायाविधिना रसाः", text: "sarvaśo vā na yo yaśca dīpagandhaṃ na jighrati vidhinā yasya doṣāya svāsthyāyāvidhinā rasāḥ" },
      { type: "verse", number: "9", sanskrit: "यः पांसुनेव कीर्णाङ्गो यो ऽङ्गे घातं न वेत्ति वा", text: "yaḥ pāṃsuneva kīrṇāṅgo yo 'ṅge ghātaṃ na vetti vā" },
      { type: "verse", number: "10", sanskrit: "अन्तरेण तपस्तीव्रं योगं वा विधिपूर्वकम् जानात्यतीन्द्रियं यश्च तेषां मरणमादिशेत्", text: "antareṇa tapastīvraṃ yogaṃ vā vidhipūrvakam jānātyatīndriyaṃ yaśca teṣāṃ maraṇamādiśet" },
      { type: "verse", number: "11", sanskrit: "जिह्वा श्यावा मुखं पूति सव्यमक्षि निमज्जति स्वगा वा मूर्ध्नि लीयन्ते यस्य तं परिवर्जयेत्", text: "jihvā śyāvā mukhaṃ pūti savyamakṣi nimajjati svagā vā mūrdhni līyante yasya taṃ parivarjayet" },
      { type: "verse", number: "12", sanskrit: "निकषन्निव यः पादौच्युतांसः परिसर्पति हीयते बलतः शश्वद्यो ऽन्नमश्नन् हितं बहु", text: "nikaṣanniva yaḥ pādaucyutāṃsaḥ parisarpati hīyate balataḥ śaśvadyo 'nnamaśnan hitaṃ bahu" },
      { type: "verse", number: "13", sanskrit: "योल्पाशी बहुविण्मूत्रो बह्वाशी चाल्पमूत्रविट् यो वाल्पाशी कफेनार्तो दीर्घं श्वसिति चेष्टते", text: "yolpāśī bahuviṇmūtro bahvāśī cālpamūtraviṭ yo vālpāśī kaphenārto dīrghaṃ śvasiti ceṣṭate" },
      { type: "verse", number: "14", sanskrit: "दीर्घमुच्छ्वस्य यो ह्रस्वं निश्वस्य परिताम्यति ह्रस्वं च यः प्रश्वसिति व्याविद्धं स्पन्दते भृशम्", text: "dīrghamucchvasya yo hrasvaṃ niśvasya paritāmyati hrasvaṃ ca yaḥ praśvasiti vyāviddhaṃ spandate bhṛśam" },
      { type: "verse", number: "15", sanskrit: "शिरो विक्षिपते कृच्छ्राद्योञ्चयित्वा प्रपाणिकौ यो ललाटात्स्स्रुतस्वेदः श्लथसन्धानबन्धनः", text: "śiro vikṣipate kṛcchrādyoñcayitvā prapāṇikau yo lalāṭātssrutasvedaḥ ślathasandhānabandhanaḥ" },
      { type: "verse", number: "16", sanskrit: "उत्थाप्यमानः सम्मुह्येद्यो बली दुर्बलो ऽपि वा उत्थान एव स्वपिति यः पादौ विकरोति च", text: "utthāpyamānaḥ sammuhyedyo balī durbalo 'pi vā utthāna eva svapiti yaḥ pādau vikaroti ca" },
      { type: "verse", number: "17", sanskrit: "शयनासनकुड्यादेः यो ऽसदेव जिघृक्षति अहास्यहासी सम्मुद्यन् यो लेढि दशनच्छदौ", text: "śayanāsanakuḍyādeḥ yo 'sadeva jighṛkṣati ahāsyahāsī sammudyan yo leḍhi daśanacchadau" },
      { type: "verse", number: "18", sanskrit: "उत्तरोष्ठं परिलिहन् फूत्कारांश्च करोति यः यमभिद्रवति छाया कृष्णा पीतारुणापि वा", text: "uttaroṣṭhaṃ parilihan phūtkārāṃśca karoti yaḥ yamabhidravati chāyā kṛṣṇā pītāruṇāpi vā" },
      { type: "verse", number: "19", sanskrit: "भिषग्भेषजपानान्नगुरुमित्राद्विषश्च ये वशगाः सर्व एवैते विज्ञेयाः समवर्तिनः", text: "bhiṣagbheṣajapānānnagurumitrādviṣaśca ye vaśagāḥ sarva evaite vijñeyāḥ samavartinaḥ" },
      { type: "verse", number: "20", sanskrit: "ग्रीवाललाटहृदयं यस्य स्विद्यति शीतलम् उष्णो ऽपरः प्रदेशश्च शरणं तस्य देवताः", text: "grīvālalāṭahṛdayaṃ yasya svidyati śītalam uṣṇo 'paraḥ pradeśaśca śaraṇaṃ tasya devatāḥ" },
      { type: "verse", number: "21", sanskrit: "यो ऽणुज्योतिरनेकाग्रो दुश्छायो दुर्मनाः सदा बलिं बलिभुजो यस्य प्रणीतं नोपभुञ्जते", text: "yo 'ṇujyotiranekāgro duśchāyo durmanāḥ sadā baliṃ balibhujo yasya praṇītaṃ nopabhuñjate" },
      { type: "verse", number: "22", sanskrit: "निर्निमित्तं च यो मेधां शोभामुपचयं श्रियम् प्राप्नोत्यतो वा विभ्रंशं स प्राप्नोति यमक्षयम्", text: "nirnimittaṃ ca yo medhāṃ śobhāmupacayaṃ śriyam prāpnotyato vā vibhraṃśaṃ sa prāpnoti yamakṣayam" },
      { type: "verse", number: "23", sanskrit: "गुणदोषमयी यस्य स्वस्थस्य व्याधितस्य वा यात्यन्यथात्वं प्रकृतिः षण्मासान्न् स जीवति", text: "guṇadoṣamayī yasya svasthasya vyādhitasya vā yātyanyathātvaṃ prakṛtiḥ ṣaṇmāsānn sa jīvati" },
      { type: "verse", number: "24", sanskrit: "भक्तिः शीलं स्मृतिस्त्यागो बुद्धिर्बलमहेतुकम् षडेतानि निवर्तन्ते षड्भिर्मासैर्मरिष्यतः", text: "bhaktiḥ śīlaṃ smṛtistyāgo buddhirbalamahetukam ṣaḍetāni nivartante ṣaḍbhirmāsairmariṣyataḥ" },
      { type: "verse", number: "25", sanskrit: "मत्तवद्गतिवाक्कम्पमोहा मासान्मरिष्यतः नश्यत्यजानन् षडहात् केशलुञ्चनवेदनाम्", text: "mattavadgativākkampamohā māsānmariṣyataḥ naśyatyajānan ṣaḍahāt keśaluñcanavedanām" },
      { type: "verse", number: "26", sanskrit: "न याति यस्य चाहारः कण्ठं कण्ठामयादृते प्रेष्याः प्रतीपतां यान्ति प्रेताकृतिरुदीर्यते", text: "na yāti yasya cāhāraḥ kaṇṭhaṃ kaṇṭhāmayādṛte preṣyāḥ pratīpatāṃ yānti pretākṛtirudīryate" },
      { type: "verse", number: "27", sanskrit: "यस्य निद्रा भवेन्नित्या नैव वा न स जीवति वक्त्रमापूर्यते ऽश्रूणां स्विद्यतश्चरणौ भृशम्", text: "yasya nidrā bhavennityā naiva vā na sa jīvati vaktramāpūryate 'śrūṇāṃ svidyataścaraṇau bhṛśam" },
      { type: "verse", number: "28", sanskrit: "चक्षुश्चाकुलतां याति यमराज्यं गमिष्यतः यैः पुरा रमते भावैररतिस्तैर्न जीवति", text: "cakṣuścākulatāṃ yāti yamarājyaṃ gamiṣyataḥ yaiḥ purā ramate bhāvairaratistairna jīvati" },
      { type: "verse", number: "29", sanskrit: "कथयेन्न च पृष्टो ऽपि दुःश्रवं मरणं भिषक् गतासोर्बन्धुमित्राणां न चेच्छेत्तं चिकित्सितुम्", text: "kathayenna ca pṛṣṭo 'pi duḥśravaṃ maraṇaṃ bhiṣak gatāsorbandhumitrāṇāṃ na cecchettaṃ cikitsitum" },
      { type: "verse", number: "30", sanskrit: "यमदूतपिशाचाद्यैर्यत् परासुरुपास्यते घ्नद्भिरौषधवीर्याणि तस्मात्तं परिवर्जयेत्", text: "yamadūtapiśācādyairyat parāsurupāsyate ghnadbhirauṣadhavīryāṇi tasmāttaṃ parivarjayet" },
      { type: "verse", number: "31", sanskrit: "अरिष्टं नास्ति मरणं दृष्टरिष्टं च जीवितम् अरिष्टे रिष्टविज्ञानं न च रिष्टे ऽप्यनैपुणात्", text: "ariṣṭaṃ nāsti maraṇaṃ dṛṣṭariṣṭaṃ ca jīvitam ariṣṭe riṣṭavijñānaṃ na ca riṣṭe 'pyanaipuṇāt" },
      { type: "verse", number: "32", sanskrit: "चरकस्येति वचनं सुश्रुतेन तु पठ्यते ध्रुवं हि रिष्टे मरणं ब्राह्मणैस्तत् किलामलैः", text: "carakasyeti vacanaṃ suśrutena tu paṭhyate dhruvaṃ hi riṣṭe maraṇaṃ brāhmaṇaistat kilāmalaiḥ" },
      { type: "verse", number: "33", sanskrit: "रसायनतपोदानतत्परैश्च निवार्यते कृष्णात्रेयो द्विधा रिष्टं स्थिरास्थिरविभेदतः", text: "rasāyanatapodānatatparaiśca nivāryate kṛṣṇātreyo dvidhā riṣṭaṃ sthirāsthiravibhedataḥ" },
      { type: "verse", number: "34", sanskrit: "दोषाणामपि बाहुल्याद्रिष्टाभासः समुद्भवेत् तद्दोषाणां शमे शाम्येत्स्थाय्यवश्यं तु मृत्यवे", text: "doṣāṇāmapi bāhulyādriṣṭābhāsaḥ samudbhavet taddoṣāṇāṃ śame śāmyetsthāyyavaśyaṃ tu mṛtyave" },
      { type: "verse", number: "35", sanskrit: "आयुर्वेदफलं कृत्स्नं यदायुर्ज्ञे प्रतिष्टितम् रिष्टज्ञानादृतस्तस्मात्सर्वदैव भवेद्भिषक्", text: "āyurvedaphalaṃ kṛtsnaṃ yadāyurjñe pratiṣṭitam riṣṭajñānādṛtastasmātsarvadaiva bhavedbhiṣak" },
    ],
  },
  {
    sthana: "Шарирастхана",
    number: 11,
    lang: "sa",
    content: [
      { type: "heading", heading: "Марма вивека — различение марм" },
      { type: "text", text: "Глава 11 Шарирастханы Астанга-санграхи — «Марма вивека» — посвящена анатомическим и эмбриологическим аспектам: различение марм." },
      { type: "verse", number: "1", sanskrit: "अथातो विकृतव्याधिविज्ञानीयमध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vikṛtavyādhivijñānīyamadhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सर्वैर्यथास्वं हेतुप्राग्रूपरूपैरतिमात्रैर्यस्य व्याधिरुत्पद्यते व्याधितस्य वा यस्याशु मुखे पिप्लुव्यङ्गलेखातिलकालकाः करजरदनेषु वा पुष्पाण्युदरे वा नानावर्णाः सिराः यस्य शुष्यतो नेत्रोपदेहो वर्त्मनासिकान्यतरश्वयथुर्वर्त्मस्रंसो वा यस्य क्षीणस्य क्षुत्तृष्णा वा हृद्यैर्बहुभिरप्यन्नपानैर्न शाम्यति यस्य सफेनमसृक् प्रसिच्यते कुक्षिशूलं च उरसो वा यस्य श्लेष्मा नीलपीतलोहितो बहुशश्च यस्य बलवान् ग्रीवावमर्दो जिह्वाशोषः कण्ठास्यगुदपाकश्च यस्यामाशयोत्था परिकर्तिकातितृष्णा शकृद्भेदश्च यस्य पक्वाशयोत्था परिकर्तिकातितृष्णातिमात्रश्च गुदग्रहः यस्यामपक्वाशयान्यतरमाश्रित्य संज्ञां च हत्वा वायुः कण्ठे घुर्घुरकं करोति यस्य क्षीणस्य तृष्णाभिवृद्धिर्हृदि शूलं च तथा हिध्मारक्तातिसारौ वाध्मानातीसारौ वा भृशं सतृष्णौ सपरासुरिति भवति चात्र", text: "sarvairyathāsvaṃ hetuprāgrūparūpairatimātrairyasya vyādhirutpadyate vyādhitasya vā yasyāśu mukhe pipluvyaṅgalekhātilakālakāḥ karajaradaneṣu vā puṣpāṇyudare vā nānāvarṇāḥ sirāḥ yasya śuṣyato netropadeho vartmanāsikānyataraśvayathurvartmasraṃso vā yasya kṣīṇasya kṣuttṛṣṇā vā hṛdyairbahubhirapyannapānairna śāmyati yasya saphenamasṛk prasicyate kukṣiśūlaṃ ca uraso vā yasya śleṣmā nīlapītalohito bahuśaśca yasya balavān grīvāvamardo jihvāśoṣaḥ kaṇṭhāsyagudapākaśca yasyāmāśayotthā parikartikātitṛṣṇā śakṛdbhedaśca yasya pakvāśayotthā parikartikātitṛṣṇātimātraśca gudagrahaḥ yasyāmapakvāśayānyataramāśritya saṃjñāṃ ca hatvā vāyuḥ kaṇṭhe ghurghurakaṃ karoti yasya kṣīṇasya tṛṣṇābhivṛddhirhṛdi śūlaṃ ca tathā hidhmāraktātisārau vādhmānātīsārau vā bhṛśaṃ satṛṣṇau saparāsuriti bhavati cātra" },
      { type: "verse", number: "3", sanskrit: "ज्वरो निहन्ति बलवान् गम्भीरो दैर्घरात्रिकः सप्रलापभ्रमश्वासः क्षीणं शूनं हतानलम्", text: "jvaro nihanti balavān gambhīro dairgharātrikaḥ sapralāpabhramaśvāsaḥ kṣīṇaṃ śūnaṃ hatānalam" },
      { type: "verse", number: "4", sanskrit: "अक्षामं सक्तवचनं रक्ताक्षं हृदि शूलिनम् सशुष्ककासःपूर्वाह्णे यो ऽपराह्णे ऽपि वा भवेत्", text: "akṣāmaṃ saktavacanaṃ raktākṣaṃ hṛdi śūlinam saśuṣkakāsaḥpūrvāhṇe yo 'parāhṇe 'pi vā bhavet" },
      { type: "verse", number: "5", sanskrit: "बलमांसविहीनस्य श्लेष्मकाससमन्वितः रक्तपित्तं भृशं रक्तं कृष्णमिन्द्रधनुष्प्रभम्", text: "balamāṃsavihīnasya śleṣmakāsasamanvitaḥ raktapittaṃ bhṛśaṃ raktaṃ kṛṣṇamindradhanuṣprabham" },
      { type: "verse", number: "6", sanskrit: "ताम्रहारिद्रहरितं रूपं रक्तं प्रदर्शयेत् रोमकूपप्रविसृतं कण्ठास्यहृदये सजत्", text: "tāmrahāridraharitaṃ rūpaṃ raktaṃ pradarśayet romakūpapravisṛtaṃ kaṇṭhāsyahṛdaye sajat" },
      { type: "verse", number: "7", sanskrit: "वाससो ऽरञ्जनं पूति वेगवच्चातिभूरि च वृद्धं पाण्डुज्वरच्छर्दिकासशोफातिसारिणम्", text: "vāsaso 'rañjanaṃ pūti vegavaccātibhūri ca vṛddhaṃ pāṇḍujvaracchardikāsaśophātisāriṇam" },
      { type: "verse", number: "8", sanskrit: "कासश्वासौ ज्वरच्छर्दितृष्णातीसारशोफिनम् यक्ष्मा पार्श्वरुजानाहरक्तच्छर्द्यं सतापितम्", text: "kāsaśvāsau jvaraccharditṛṣṇātīsāraśophinam yakṣmā pārśvarujānāharaktacchardyaṃ satāpitam" },
      { type: "verse", number: "9", sanskrit: "छर्दिर्वेगवती मूत्रशकृद्गन्धिः सचन्द्रिका सास्रविट्पूयरुक्कासश्वासवत्यनुषङ्गिणी", text: "chardirvegavatī mūtraśakṛdgandhiḥ sacandrikā sāsraviṭpūyarukkāsaśvāsavatyanuṣaṅgiṇī" },
      { type: "verse", number: "10", sanskrit: "तृष्णान्यरोगक्षपितं बहिर्जिह्वं विचेतनम् मदात्ययो ऽतिशीतार्तं क्षीणं तैलप्रभाननम्", text: "tṛṣṇānyarogakṣapitaṃ bahirjihvaṃ vicetanam madātyayo 'tiśītārtaṃ kṣīṇaṃ tailaprabhānanam" },
      { type: "verse", number: "11", sanskrit: "अर्शांसि पाणिपन्नाभिगुदमुष्कास्यशोफिनम् हृत्पार्श्वाङ्गरुजाच्छर्दिपायुपाकज्वरातुरम्", text: "arśāṃsi pāṇipannābhigudamuṣkāsyaśophinam hṛtpārśvāṅgarujācchardipāyupākajvarāturam" },
      { type: "verse", number: "12", sanskrit: "अतीसारो यकृत्पिण्डमांसधावनमेचकैः तुल्यस्तैलघृतक्षीरदधिमज्जवसासवैः", text: "atīsāro yakṛtpiṇḍamāṃsadhāvanamecakaiḥ tulyastailaghṛtakṣīradadhimajjavasāsavaiḥ" },
      { type: "verse", number: "13", sanskrit: "मस्तुलुङ्गमषीपूयवेशवाराम्बुमाक्षिकैः अतिरक्तासितस्निग्धपूत्यच्छघनवेदनः", text: "mastuluṅgamaṣīpūyaveśavārāmbumākṣikaiḥ atiraktāsitasnigdhapūtyacchaghanavedanaḥ" },
      { type: "verse", number: "14", sanskrit: "कर्बुरं प्रस्रवन् धतून् निष्पुरीषो ऽथवातिविट् तन्तुमान् मक्षिकाक्रान्तो राजीमांश्चन्द्रकैर्युतः", text: "karburaṃ prasravan dhatūn niṣpurīṣo 'thavātiviṭ tantumān makṣikākrānto rājīmāṃścandrakairyutaḥ" },
      { type: "verse", number: "15", sanskrit: "शीर्णपायुवलिं मुक्तनालं पर्वास्थिशूलिनम् स्रस्तपायुं बलक्षीणमन्नमेवोपवेशयेत्", text: "śīrṇapāyuvaliṃ muktanālaṃ parvāsthiśūlinam srastapāyuṃ balakṣīṇamannamevopaveśayet" },
      { type: "verse", number: "16", sanskrit: "सतृट्कासज्वरच्छर्दिदाहानाहप्रवाहिकः अश्मरी शूनवृषणं बद्धमूत्रं रुजार्दितम्", text: "satṛṭkāsajvaracchardidāhānāhapravāhikaḥ aśmarī śūnavṛṣaṇaṃ baddhamūtraṃ rujārditam" },
      { type: "verse", number: "17", sanskrit: "मेहस्तृड्दाहपिटकामांसकोथातिसारिणम् पिटका मर्महृत्पृष्ठस्तनांसगुदमूर्द्धगा", text: "mehastṛḍdāhapiṭakāmāṃsakothātisāriṇam piṭakā marmahṛtpṛṣṭhastanāṃsagudamūrddhagā" },
      { type: "verse", number: "18", sanskrit: "पर्वपादकरस्था वा मन्दोत्साहं प्रमेहिणम् सर्वं च मांससङ्कोथदाहतृष्णामदज्वरैः", text: "parvapādakarasthā vā mandotsāhaṃ pramehiṇam sarvaṃ ca māṃsasaṅkothadāhatṛṣṇāmadajvaraiḥ" },
      { type: "verse", number: "19", sanskrit: "विसर्पमर्मसंरोधहिध्माश्वासभ्रमक्लमैः गुल्मः पृथुपरीणाहो घनः कूर्म इवोन्नतः", text: "visarpamarmasaṃrodhahidhmāśvāsabhramaklamaiḥ gulmaḥ pṛthuparīṇāho ghanaḥ kūrma ivonnataḥ" },
      { type: "verse", number: "20", sanskrit: "सिरानद्धो ज्वरच्छर्दिहिध्माध्मानरुजान्वितः कासपीनसहृल्लासश्वासातीसारशोफवान्", text: "sirānaddho jvaracchardihidhmādhmānarujānvitaḥ kāsapīnasahṛllāsaśvāsātīsāraśophavān" },
      { type: "verse", number: "21", sanskrit: "विण्मूत्रसङ्ग्रहश्वासशोफहिध्माज्वरभ्रमैः मूर्च्छाछर्द्यतिसारैश्च जठरं हन्ति दुर्बलम्", text: "viṇmūtrasaṅgrahaśvāsaśophahidhmājvarabhramaiḥ mūrcchāchardyatisāraiśca jaṭharaṃ hanti durbalam" },
      { type: "verse", number: "22", sanskrit: "शूनाक्षं कुटिलोपस्थमुपक्लिन्नतनुत्वचम् विरेचनहृतानाहमानह्यन्तं पुनःपुनः", text: "śūnākṣaṃ kuṭilopasthamupaklinnatanutvacam virecanahṛtānāhamānahyantaṃ punaḥpunaḥ" },
      { type: "verse", number: "23", sanskrit: "पाण्डुरोगः श्वयथुमान् पीताक्षिनखदर्शनम् तन्द्रादाहारुचिच्छर्दिमूर्च्छाध्मानातिसारवान्", text: "pāṇḍurogaḥ śvayathumān pītākṣinakhadarśanam tandrādāhārucicchardimūrcchādhmānātisāravān" },
      { type: "verse", number: "24", sanskrit: "अनेकोपद्रवयुतः पादाभ्यां प्रसृतो नरम् नारीं शोफो मुखाद्धन्ति कुक्षिगुह्यादुभावपि", text: "anekopadravayutaḥ pādābhyāṃ prasṛto naram nārīṃ śopho mukhāddhanti kukṣiguhyādubhāvapi" },
      { type: "verse", number: "25", sanskrit: "राजीचितः स्रवंश्छर्दिज्वरश्वासातिसारिणम्", text: "rājīcitaḥ sravaṃśchardijvaraśvāsātisāriṇam" },
      { type: "verse", number: "26", sanskrit: "ज्वरातिसारौ शोफान्ते श्वयथुर्वा तयोः क्षये दुर्बलस्य विशेषेण जायन्ते ऽन्ताय देहिनः", text: "jvarātisārau śophānte śvayathurvā tayoḥ kṣaye durbalasya viśeṣeṇa jāyante 'ntāya dehinaḥ" },
      { type: "verse", number: "27", sanskrit: "श्वयथुर्यस्य पादस्थः परिस्रस्ते च पिण्डिके सीदतः सक्थिनी चैव तं भिषक् परिवर्जयेत्", text: "śvayathuryasya pādasthaḥ parisraste ca piṇḍike sīdataḥ sakthinī caiva taṃ bhiṣak parivarjayet" },
      { type: "verse", number: "28", sanskrit: "आननं हस्तपादं च विशेषाद्यस्य शुष्यतः शूयेते वा विना देहात्स मासाद्याति पञ्चताम्", text: "ānanaṃ hastapādaṃ ca viśeṣādyasya śuṣyataḥ śūyete vā vinā dehātsa māsādyāti pañcatām" },
      { type: "verse", number: "29", sanskrit: "उदरी यश्च शोफी वा स्वं न पश्यति मेहनम् यस्य वा जठरोन्नामात् परिधानं न तिष्ठति", text: "udarī yaśca śophī vā svaṃ na paśyati mehanam yasya vā jaṭharonnāmāt paridhānaṃ na tiṣṭhati" },
      { type: "verse", number: "30", sanskrit: "विसर्पः कासवैवर्ण्यज्वरमूर्छाङ्गभङ्गवान् भ्रमास्यशोफहृल्लासदेहसादातिसारवान्", text: "visarpaḥ kāsavaivarṇyajvaramūrchāṅgabhaṅgavān bhramāsyaśophahṛllāsadehasādātisāravān" },
      { type: "verse", number: "31", sanskrit: "कुष्ठं विशीर्यमाणाङ्गं रक्तनेत्रं हतस्वरम् मन्दाग्निं जन्तुभिर्जुष्टं हन्ति तृष्णातिसारिणम्", text: "kuṣṭhaṃ viśīryamāṇāṅgaṃ raktanetraṃ hatasvaram mandāgniṃ jantubhirjuṣṭaṃ hanti tṛṣṇātisāriṇam" },
      { type: "verse", number: "32", sanskrit: "वायुः सुप्तत्वचं भुग्नं कम्पशोफरुजातुरम्", text: "vāyuḥ suptatvacaṃ bhugnaṃ kampaśopharujāturam" },
      { type: "verse", number: "33", sanskrit: "वातास्रं मोहमूर्छायमदास्वप्नज्वरान्वितम् शिरोग्रहारुचिश्वाससङ्कोचस्फोटकोथवत्", text: "vātāsraṃ mohamūrchāyamadāsvapnajvarānvitam śirograhāruciśvāsasaṅkocasphoṭakothavat" },
      { type: "verse", number: "34", sanskrit: "शिरोरोगारुचिश्वासमोहविड्भेदतृड्भ्रमैः घ्नन्ति सर्वामयाः क्षीणस्वरधातुबलानलम्", text: "śirorogāruciśvāsamohaviḍbhedatṛḍbhramaiḥ ghnanti sarvāmayāḥ kṣīṇasvaradhātubalānalam" },
      { type: "verse", number: "35", sanskrit: "वातव्याधिरपस्मारी कुष्ठी रक्त्युदरी क्षयी गुल्मी मेही च तान् क्षीणान् विकारे ऽल्पे ऽपि वर्जयेत्", text: "vātavyādhirapasmārī kuṣṭhī raktyudarī kṣayī gulmī mehī ca tān kṣīṇān vikāre 'lpe 'pi varjayet" },
      { type: "verse", number: "36", sanskrit: "बलमांसक्षयस्तीव्रो रोगवृद्धिररोचकः यस्यातुरस्य लक्ष्यन्ते त्रीन् पक्षान्न स जीवति", text: "balamāṃsakṣayastīvro rogavṛddhirarocakaḥ yasyāturasya lakṣyante trīn pakṣānna sa jīvati" },
      { type: "verse", number: "37", sanskrit: "वाताष्ठीलातिसंवृद्धा तिष्ठन्ती दारुणा हृदि तृष्णयानुपरीतस्य सद्यो मुष्णाति जीवितम्", text: "vātāṣṭhīlātisaṃvṛddhā tiṣṭhantī dāruṇā hṛdi tṛṣṇayānuparītasya sadyo muṣṇāti jīvitam" },
      { type: "verse", number: "38", sanskrit: "शैथिल्यं पिण्डिके वायुर्नीत्वा नासां च जिह्मताम् क्षीणस्यायम्य मन्ये वा सद्यो मुष्णाति जीवितम्", text: "śaithilyaṃ piṇḍike vāyurnītvā nāsāṃ ca jihmatām kṣīṇasyāyamya manye vā sadyo muṣṇāti jīvitam" },
      { type: "verse", number: "39", sanskrit: "नाभीगुदान्तरं गत्वा वङ्क्षणौ वा समाश्रयन् गृहीत्वा पायुहृदये क्षीणदेहस्य वा बली", text: "nābhīgudāntaraṃ gatvā vaṅkṣaṇau vā samāśrayan gṛhītvā pāyuhṛdaye kṣīṇadehasya vā balī" },
      { type: "verse", number: "40", sanskrit: "मलान् वस्तिशिरोनाभिं विबध्य जनयन् रुजम् कुर्वन् वङ्क्षणयोः शूलं तृष्णां भिन्नपुरीषताम्", text: "malān vastiśironābhiṃ vibadhya janayan rujam kurvan vaṅkṣaṇayoḥ śūlaṃ tṛṣṇāṃ bhinnapurīṣatām" },
      { type: "verse", number: "41", sanskrit: "श्वासं वा जनयन् वायुर्गृहीत्वा गुदवङ्क्षणौ वितत्य पर्शुकाग्राणि गृहीत्वोरश्च मारुतः", text: "śvāsaṃ vā janayan vāyurgṛhītvā gudavaṅkṣaṇau vitatya parśukāgrāṇi gṛhītvoraśca mārutaḥ" },
      { type: "verse", number: "42", sanskrit: "स्तिमितस्यातताक्षस्य सद्यो मुष्णाति जीवितम्", text: "stimitasyātatākṣasya sadyo muṣṇāti jīvitam" },
      { type: "verse", number: "43", sanskrit: "सहसा ज्वरसन्तापस्तृष्णामूर्छाबलक्षयः विश्लेषणं च सन्धीनां मुमूर्षोरुपजायते", text: "sahasā jvarasantāpastṛṣṇāmūrchābalakṣayaḥ viśleṣaṇaṃ ca sandhīnāṃ mumūrṣorupajāyate" },
      { type: "verse", number: "44", sanskrit: "गोसर्गे वदनाद्यस्य स्वेदः प्रच्यवते भृशम् लेपज्वरोपतप्तस्य दुर्लभं तस्य जीवितम्", text: "gosarge vadanādyasya svedaḥ pracyavate bhṛśam lepajvaropataptasya durlabhaṃ tasya jīvitam" },
      { type: "verse", number: "45", sanskrit: "प्रवालगुलिकाभासा यस्य गात्रे मसूरिकाः उत्पद्याशु विनश्यन्ति न चिरात्स विनश्यति", text: "pravālagulikābhāsā yasya gātre masūrikāḥ utpadyāśu vinaśyanti na cirātsa vinaśyati" },
      { type: "verse", number: "46", sanskrit: "मसूरविदलप्रख्यास्तथा विदुमसन्निभाः अन्तर्वक्राः किणाभाश्च विस्फोटा देहनाशनाः", text: "masūravidalaprakhyāstathā vidumasannibhāḥ antarvakrāḥ kiṇābhāśca visphoṭā dehanāśanāḥ" },
      { type: "verse", number: "47", sanskrit: "कामलाक्ष्णोर्मुखं पूर्णं शङ्खयोर्मुक्तमांसता सन्त्रासश्चोष्णताङ्गे च यस्य तं परिवर्जयेत्", text: "kāmalākṣṇormukhaṃ pūrṇaṃ śaṅkhayormuktamāṃsatā santrāsaścoṣṇatāṅge ca yasya taṃ parivarjayet" },
      { type: "verse", number: "48", sanskrit: "अकस्मादनुधावच्च विघृष्टं त्वक्समाश्रयम् चन्दनोशीरमदिराकुणपध्वाङ्क्षगन्धयः", text: "akasmādanudhāvacca vighṛṣṭaṃ tvaksamāśrayam candanośīramadirākuṇapadhvāṅkṣagandhayaḥ" },
      { type: "verse", number: "49", sanskrit: "शैवालकुक्कुटशिखाकुङ्कुमालमषीप्रभाः अन्तर्दाहा निरूष्माणः प्राणनाशकरा व्रणाः", text: "śaivālakukkuṭaśikhākuṅkumālamaṣīprabhāḥ antardāhā nirūṣmāṇaḥ prāṇanāśakarā vraṇāḥ" },
      { type: "verse", number: "50", sanskrit: "यो वातजो न शूलाय स्यान्न दाहाय पित्तजः कफजो न च पूयाय मर्मजश्च रुजे न यः", text: "yo vātajo na śūlāya syānna dāhāya pittajaḥ kaphajo na ca pūyāya marmajaśca ruje na yaḥ" },
      { type: "verse", number: "51", sanskrit: "अचूर्णश्चूर्णकीर्णाभो यत्राकस्माच्च दृश्यते रूपं शक्तिध्वजादीनां सर्वांस्तान् वर्जयेद् व्रणान्", text: "acūrṇaścūrṇakīrṇābho yatrākasmācca dṛśyate rūpaṃ śaktidhvajādīnāṃ sarvāṃstān varjayed vraṇān" },
      { type: "verse", number: "52", sanskrit: "विण्मूत्रमारुतवहं कृमिणं च भगन्दरम्", text: "viṇmūtramārutavahaṃ kṛmiṇaṃ ca bhagandaram" },
      { type: "verse", number: "53", sanskrit: "घट्टयन् जानुना जानु पादावुयम्य पातयन् यो ऽपास्यति मुहुर्वक्त्रमातुरो न स जीवति", text: "ghaṭṭayan jānunā jānu pādāvuyamya pātayan yo 'pāsyati muhurvaktramāturo na sa jīvati" },
      { type: "verse", number: "54", sanskrit: "दन्तैश्छिन्दन् नखाग्राणि तैश्च केशांस्तृणानि वा भूमिं काष्ठेन विलिखन् लोष्टं लोष्टेन ताडयन्", text: "dantaiśchindan nakhāgrāṇi taiśca keśāṃstṛṇāni vā bhūmiṃ kāṣṭhena vilikhan loṣṭaṃ loṣṭena tāḍayan" },
      { type: "verse", number: "55", sanskrit: "हृष्टरोमा सान्द्रमूत्रः शुष्ककासी ज्वरी च यः मुहुर्हसन् मुहुः क्षवेडन् शय्यां पादेन हन्ति यः", text: "hṛṣṭaromā sāndramūtraḥ śuṣkakāsī jvarī ca yaḥ muhurhasan muhuḥ kṣaveḍan śayyāṃ pādena hanti yaḥ" },
      { type: "verse", number: "56", sanskrit: "मुहुश्छिद्राणि विमृशन्नातुरो न स जीवति", text: "muhuśchidrāṇi vimṛśannāturo na sa jīvati" },
      { type: "verse", number: "57", sanskrit: "ऊर्ध्वश्वासं गतोष्माणं शूलोपहतवङ्क्षणम् शर्म चानधिगच्छन्तं बुद्धिमान् परिवर्जयेत्", text: "ūrdhvaśvāsaṃ gatoṣmāṇaṃ śūlopahatavaṅkṣaṇam śarma cānadhigacchantaṃ buddhimān parivarjayet" },
      { type: "verse", number: "58", sanskrit: "विकारा यस्य वर्द्धन्ते प्रकृतिः परिहीयते सहसा सहसा तस्य मृत्युर्हरति जीवितम्", text: "vikārā yasya varddhante prakṛtiḥ parihīyate sahasā sahasā tasya mṛtyurharati jīvitam" },
      { type: "verse", number: "59", sanskrit: "यमुद्दिश्यातुरं वैद्यः सम्पादयितुमौषधम् यतमानो न शक्नोति दुर्लभं तस्य जीवितम्", text: "yamuddiśyāturaṃ vaidyaḥ sampādayitumauṣadham yatamāno na śaknoti durlabhaṃ tasya jīvitam" },
      { type: "verse", number: "60", sanskrit: "विज्ञातं बहुशः सिद्धं विधिवच्चावचारितम् न सिध्यत्यौषधं यस्य नास्ति तस्य चिकित्सितम्", text: "vijñātaṃ bahuśaḥ siddhaṃ vidhivaccāvacāritam na sidhyatyauṣadhaṃ yasya nāsti tasya cikitsitam" },
      { type: "verse", number: "61", sanskrit: "भवेद्यस्यौषधे ऽन्ने वा कल्प्यमाने विपर्ययः अकस्माद्वर्णगन्धादेः स्वस्थो ऽपि न स जीवति", text: "bhavedyasyauṣadhe 'nne vā kalpyamāne viparyayaḥ akasmādvarṇagandhādeḥ svastho 'pi na sa jīvati" },
      { type: "verse", number: "62", sanskrit: "निवाते सेन्धनं यस्य ज्योतिश्चाप्युपशाम्यति", text: "nivāte sendhanaṃ yasya jyotiścāpyupaśāmyati" },
      { type: "verse", number: "63", sanskrit: "आतुरस्य गृहे यस्य भिद्यन्ते वा पतन्ति वा अतिमात्रममत्राणि दुर्लभं तस्य जीवितम्", text: "āturasya gṛhe yasya bhidyante vā patanti vā atimātramamatrāṇi durlabhaṃ tasya jīvitam" },
      { type: "verse", number: "64", sanskrit: "यं नरं सहसा रोगो दुर्बलं परिमुञ्चति संशयप्राप्तमात्रेयो जीवितं तस्य मन्यते", text: "yaṃ naraṃ sahasā rogo durbalaṃ parimuñcati saṃśayaprāptamātreyo jīvitaṃ tasya manyate" },
    ],
  },
  {
    sthana: "Шарирастхана",
    number: 12,
    lang: "sa",
    content: [
      { type: "heading", heading: "Шарира самапти — завершение Шариrasthanы" },
      { type: "text", text: "Глава 12 Шарирастханы Астанга-санграхи — «Шарира самапти» — посвящена анатомическим и эмбриологическим аспектам: завершение Шариrasthanы." },
      { type: "verse", number: "1", sanskrit: "अथातो दूतादिविज्ञानीयमध्यायं व्याख्यास्यामः", text: "athāto dūtādivijñānīyamadhyāyaṃ vyākhyāsyāmaḥ" },
      { type: "verse", number: "2", sanskrit: "निर्दिष्टं रिष्टमातुराश्रयम् दूतस्यापि तु जातिवेषभाषाचेष्टितदेशकाला वैद्यस्य च तत्सङ्गमसङ्कल्पप्रस्थानप्रयाणप्रवेशा ग्रहचारो ऽपूर्वसम्भवः स्वप्नदर्शनानि च रोगिणः शुभाशुभं सूचयन्ति", text: "nirdiṣṭaṃ riṣṭamāturāśrayam dūtasyāpi tu jātiveṣabhāṣāceṣṭitadeśakālā vaidyasya ca tatsaṅgamasaṅkalpaprasthānaprayāṇapraveśā grahacāro 'pūrvasambhavaḥ svapnadarśanāni ca rogiṇaḥ śubhāśubhaṃ sūcayanti" },
      { type: "verse", number: "3", sanskrit: "तत्रातुराद्वर्णोत्तमो ऽन्याश्रमः पाषण्डः षण्डो मुण्डी जटिलः स्त्री व्याधितो ऽनेको ऽजीर्णविवर्णमलिनच्छिन्नार्द्रैकवसनः पङ्कतैलदिग्धो रक्तमाल्यानुलेपनो विकृताङ्गरूपकर्मा खरोष्ट्रमहिषवाहनो विक्लबः श्वसन् रुदन् निष्टुरामङ्गलाभिधायी दूरादाह्वयमानस्तृणलोष्टतुषाङ्गारभस्मतुषसीसास्थिकेशशिरोललाटनासिकास्यदन्तजिह्वाग्रीवानखानामिकाङ्गुलिस्तनजठरनाभिपृष्ठकटीमेहनजङ्घाकपालपललोपलमुसलशूर्पोपानन्मार्जनीशस्त्रवस्त्रान्तदशाकार्पासभग्नच्युतस्पृक्काष्ठयष्टीतुलारज्जुपाशचर्मवेणुरिक्तभाजनस्नेहभाजनधरः पादाभ्यां भुवं मुञ्चन् विलिखन् गृहीत्वा पक्वं फलप्रसारं वा तद्विधमन्यद्वा विकारतुल्यगुणे च देशे काले वा दूतो वैद्यमुपसर्पन्नशुभः", text: "tatrāturādvarṇottamo 'nyāśramaḥ pāṣaṇḍaḥ ṣaṇḍo muṇḍī jaṭilaḥ strī vyādhito 'neko 'jīrṇavivarṇamalinacchinnārdraikavasanaḥ paṅkatailadigdho raktamālyānulepano vikṛtāṅgarūpakarmā kharoṣṭramahiṣavāhano viklabaḥ śvasan rudan niṣṭurāmaṅgalābhidhāyī dūrādāhvayamānastṛṇaloṣṭatuṣāṅgārabhasmatuṣasīsāsthikeśaśirolalāṭanāsikāsyadantajihvāgrīvānakhānāmikāṅgulistanajaṭharanābhipṛṣṭhakaṭīmehanajaṅghākapālapalalopalamusalaśūrpopānanmārjanīśastravastrāntadaśākārpāsabhagnacyutaspṛkkāṣṭhayaṣṭītulārajjupāśacarmaveṇuriktabhājanasnehabhājanadharaḥ pādābhyāṃ bhuvaṃ muñcan vilikhan gṛhītvā pakvaṃ phalaprasāraṃ vā tadvidhamanyadvā vikāratulyaguṇe ca deśe kāle vā dūto vaidyamupasarpannaśubhaḥ" },
      { type: "verse", number: "4", sanskrit: "तद्यथा घृतोदकादिद्रवसमपि स्थमातिशीतस्तब्धः प्रत्युषसि श्लेष्मामये ऽशुभः पित्तामये तु शुभः तथा सेतुभङ्गे छर्दिमेहातिसारादिष्वशुभः सेतुबन्धे तु शुभः तथा मध्याह्नोभयसन्ध्यार्द्धरात्रिचतुर्थीषष्ठीनवमीपर्वदिनेषु ग्रहोपरागोत्पातदर्शनभ्रणीकृत्तिकार्द्राश्लेषामघामूलपूर्वासु चाशुभो यश्च वैद्यं सुप्तं नग्नं च भूमौ शयानमभ्यक्तं मुक्तकेशं दक्षिणाभिमुखं विक्लवं छिन्दन्तं भिन्दन्तमग्निपितृकार्यप्रवणमशस्तं चिन्तयन्तं कथयन्तं वोपतिष्ठति यो वा दिशं याम्यां प्रतिकृताञ्जलिर्विषमैकपादस्थः यस्मिन् व्याधिताश्रयं कथयति दूते भिषगशुभमिन्द्रियार्थमुपलक्षयेत् सङ्कल्पयेद्वा तं च नानुयायात् अतो ऽन्यथा पुनः करुणापेशलेन मनसा सौमनस्यवता मातापितृसमेनातुरस्यात्यन्तमारोग्यमाशसमानेन प्रयातव्यम्", text: "tadyathā ghṛtodakādidravasamapi sthamātiśītastabdhaḥ pratyuṣasi śleṣmāmaye 'śubhaḥ pittāmaye tu śubhaḥ tathā setubhaṅge chardimehātisārādiṣvaśubhaḥ setubandhe tu śubhaḥ tathā madhyāhnobhayasandhyārddharātricaturthīṣaṣṭhīnavamīparvadineṣu grahoparāgotpātadarśanabhraṇīkṛttikārdrāśleṣāmaghāmūlapūrvāsu cāśubho yaśca vaidyaṃ suptaṃ nagnaṃ ca bhūmau śayānamabhyaktaṃ muktakeśaṃ dakṣiṇābhimukhaṃ viklavaṃ chindantaṃ bhindantamagnipitṛkāryapravaṇamaśastaṃ cintayantaṃ kathayantaṃ vopatiṣṭhati yo vā diśaṃ yāmyāṃ pratikṛtāñjalirviṣamaikapādasthaḥ yasmin vyādhitāśrayaṃ kathayati dūte bhiṣagaśubhamindriyārthamupalakṣayet saṅkalpayedvā taṃ ca nānuyāyāt ato 'nyathā punaḥ karuṇāpeśalena manasā saumanasyavatā mātāpitṛsamenāturasyātyantamārogyamāśasamānena prayātavyam" },
      { type: "verse", number: "5", sanskrit: "प्रस्थानगमनप्रवेशेषु दधिमधुघृतलाजपुष्पाक्षतोदुम्बराश्वत्थमुक्तामणिछत्रदूर्वाङ्कुरादर्शकन्याध्वजस्यन्दनाष्टापदाक्षा नृपश्रीतरुर्भद्रपीठानि सस्यानि मत्स्या हया हंसचाषौ वृषः केसरी दक्षिणावर्तशङ्खाब्जसिद्धार्थकारोचनाः स्वस्तिकस्तोरणं कीचकावेणवो वरवधूर्मदसिक्तगण्डो गजस्तोयलम्बो ऽम्बुदः पूर्णकुम्भो हरिद्रात्रिरिन्द्रः फलान्यार्द्रमांसं सितं चामरं गौः सवत्साङ्गना पुत्रिणी मानुषं वर्धमानं सहस्रं भूमिरभ्युद्वृता सिद्धमन्नं वराहश्च तोयोत्थितास्त्रिणयनमधुसूदनस्कन्दपद्मासनाः लोकपालाः सुराः खं दिशो ऽग्निः सरांसि स्रवन्त्यः समुद्रा मखा मारुतो ज्योतिषं धर्मशास्त्राणि तीर्थानि काव्यं धर्मार्थकामामृतं वालखिल्यादयो वेदवाक्यं निधिः कौस्तुभः काञ्चनं मणिभद्रः सुमेरुः प्रियङ्गुः प्रदीपो वचामोदकौ दितिरदितिररुन्धती र्द्धिः सावित्र्युमाकाशगङ्गा शची देवसेना स्वधा शान्तिर्लक्ष्मीः सरस्वत्यपत्यं क्षमा स्वस्तिशब्दो वषट्कार औंकारपुण्याहधर्मक्रियाश्चैतदष्टोत्तरं मङ्गलानां शतं दर्शनात् स्पर्शनात् कीर्तनाच्चाशुभानि व्यपोह्यार्थसिद्धिं दिशन्त्युत्तमाम् अपि च", text: "prasthānagamanapraveśeṣu dadhimadhughṛtalājapuṣpākṣatodumbarāśvatthamuktāmaṇichatradūrvāṅkurādarśakanyādhvajasyandanāṣṭāpadākṣā nṛpaśrītarurbhadrapīṭhāni sasyāni matsyā hayā haṃsacāṣau vṛṣaḥ kesarī dakṣiṇāvartaśaṅkhābjasiddhārthakārocanāḥ svastikastoraṇaṃ kīcakāveṇavo varavadhūrmadasiktagaṇḍo gajastoyalambo 'mbudaḥ pūrṇakumbho haridrātririndraḥ phalānyārdramāṃsaṃ sitaṃ cāmaraṃ gauḥ savatsāṅganā putriṇī mānuṣaṃ vardhamānaṃ sahasraṃ bhūmirabhyudvṛtā siddhamannaṃ varāhaśca toyotthitāstriṇayanamadhusūdanaskandapadmāsanāḥ lokapālāḥ surāḥ khaṃ diśo 'gniḥ sarāṃsi sravantyaḥ samudrā makhā māruto jyotiṣaṃ dharmaśāstrāṇi tīrthāni kāvyaṃ dharmārthakāmāmṛtaṃ vālakhilyādayo vedavākyaṃ nidhiḥ kaustubhaḥ kāñcanaṃ maṇibhadraḥ sumeruḥ priyaṅguḥ pradīpo vacāmodakau ditiraditirarundhatī rddhiḥ sāvitryumākāśagaṅgā śacī devasenā svadhā śāntirlakṣmīḥ sarasvatyapatyaṃ kṣamā svastiśabdo vaṣaṭkāra auṃkārapuṇyāhadharmakriyāścaitadaṣṭottaraṃ maṅgalānāṃ śataṃ darśanāt sparśanāt kīrtanāccāśubhāni vyapohyārthasiddhiṃ diśantyuttamām api ca" },
      { type: "verse", number: "6", sanskrit: "पुन्नामानः पक्षिणो वामाः शिवाः शिवा श्यामा पिङ्गला कोकिलारला चुच्छुन्दरी सूकरी गृहगोधिकैकशफाश्च स्त्रीनामानो दक्षिणाः शिखी चणकश्येनगजाजकपयश्च प्रवेशे तु विपरीताः सर्वत्र च दक्षिणाद्वामगमनमिष्टं श्वसृगालयोः विपरीतं मृगविहङ्गयोः सर्वथापि दर्शनं भरद्वाजचाषभासनकुलानाम्", text: "punnāmānaḥ pakṣiṇo vāmāḥ śivāḥ śivā śyāmā piṅgalā kokilāralā cucchundarī sūkarī gṛhagodhikaikaśaphāśca strīnāmāno dakṣiṇāḥ śikhī caṇakaśyenagajājakapayaśca praveśe tu viparītāḥ sarvatra ca dakṣiṇādvāmagamanamiṣṭaṃ śvasṛgālayoḥ viparītaṃ mṛgavihaṅgayoḥ sarvathāpi darśanaṃ bharadvājacāṣabhāsanakulānām" },
      { type: "verse", number: "7", sanskrit: "शशसर्पाजाविगोधाजाविकसूकराणां तु कीर्तनमिष्टम् न दर्शनं विरुतं वा विपरीतमृक्षवानरयोः सर्पमपि त्वनिष्टं सरटकुक्कुटबिडालोलूकानाम् तथा ग्रन्थ्यर्बुदादिषु छेदशब्द इष्टो गुल्मोदरादिषु भेदशब्दो ऽतीसाररक्तपित्तादिषु रुद्धशब्दो ऽश्मर्युदरादिषु प्रवर्तनशब्द इति एवमन्ये ऽपि ध्वनयो योज्याः सर्वत्रैव च स्थिरस्थावरवर्द्धमानत्राताचलध्रुवक्षेमशिवादयः शब्दा धन्यवादित्रस्वराश्च श्रेष्ठाः", text: "śaśasarpājāvigodhājāvikasūkarāṇāṃ tu kīrtanamiṣṭam na darśanaṃ virutaṃ vā viparītamṛkṣavānarayoḥ sarpamapi tvaniṣṭaṃ saraṭakukkuṭabiḍālolūkānām tathā granthyarbudādiṣu chedaśabda iṣṭo gulmodarādiṣu bhedaśabdo 'tīsāraraktapittādiṣu ruddhaśabdo 'śmaryudarādiṣu pravartanaśabda iti evamanye 'pi dhvanayo yojyāḥ sarvatraiva ca sthirasthāvaravarddhamānatrātācaladhruvakṣemaśivādayaḥ śabdā dhanyavāditrasvarāśca śreṣṭhāḥ" },
      { type: "verse", number: "8", sanskrit: "क्षतहतपतिताक्रोशप्रहारच्छेदभेददाहहाहाप्रतिषेधादिशब्दाः चिकित्साप्रतिषेधाय", text: "kṣatahatapatitākrośaprahāracchedabhedadāhahāhāpratiṣedhādiśabdāḥ cikitsāpratiṣedhāya" },
      { type: "verse", number: "9", sanskrit: "दीप्तायां च दिशि क्रूराः पक्षिमृगध्वनयो वृक्षे वा रूक्षशुष्के सवल्लीकण्टके तद्विधे वा देशे", text: "dīptāyāṃ ca diśi krūrāḥ pakṣimṛgadhvanayo vṛkṣe vā rūkṣaśuṣke savallīkaṇṭake tadvidhe vā deśe" },
      { type: "verse", number: "10", sanskrit: "दर्शनं च तृणपललकाष्ठभारकर्परकलोष्टादीनां कण्टकोर्ध्वपादयानशयनासनादिभग्नोपस्कररिक्तकुम्भमद्यवसातैलतिलगर्भिणीश्चपाकव्यसनिमृतानां च प्रवेशे चातुरगृहात् पूर्वोक्तमाङ्गल्यनिर्गमः प्रविष्टस्य तु भिषजः न सत्कारो लाभतुष्टिस्तुतयश्चाशुभाः", text: "darśanaṃ ca tṛṇapalalakāṣṭhabhārakarparakaloṣṭādīnāṃ kaṇṭakordhvapādayānaśayanāsanādibhagnopaskarariktakumbhamadyavasātailatilagarbhiṇīścapākavyasanimṛtānāṃ ca praveśe cāturagṛhāt pūrvoktamāṅgalyanirgamaḥ praviṣṭasya tu bhiṣajaḥ na satkāro lābhatuṣṭistutayaścāśubhāḥ" },
      { type: "verse", number: "11", sanskrit: "आतुरस्य वक्रानुवक्ता ग्रहा गर्हितस्थानस्थाः केतुशनिराहुभिर्जन्मर्क्षाभिभवो गृहदारशयनासनवाहनमणिरत्नोपकरणेषु वा गर्हितलक्षणप्रादुर्भावश्चिकित्साप्रतिषेधाय", text: "āturasya vakrānuvaktā grahā garhitasthānasthāḥ ketuśanirāhubhirjanmarkṣābhibhavo gṛhadāraśayanāsanavāhanamaṇiratnopakaraṇeṣu vā garhitalakṣaṇaprādurbhāvaścikitsāpratiṣedhāya" },
      { type: "verse", number: "12", sanskrit: "स्वप्नस्तु स्वयमन्येन वा दृष्टः शुभाशुभहेतुः सप्तविधो दृष्टः श्रुतो ऽनुभूतः प्रार्थितः सङ्कल्पितो भाविको दोषजश्च तत्राद्यः पञ्चविधो ऽफलः तथा यथास्वप्रकृतिर्विस्मृतो दिवातिह्रस्वो ऽतिदोर्घो नातिशुप्तदृष्टश्च", text: "svapnastu svayamanyena vā dṛṣṭaḥ śubhāśubhahetuḥ saptavidho dṛṣṭaḥ śruto 'nubhūtaḥ prārthitaḥ saṅkalpito bhāviko doṣajaśca tatrādyaḥ pañcavidho 'phalaḥ tathā yathāsvaprakṛtirvismṛto divātihrasvo 'tidorgho nātiśuptadṛṣṭaśca" },
      { type: "verse", number: "13", sanskrit: "पूर्वरात्रे ऽल्पं चिराच्च फलं करोति गोसर्गे महत्सद्यश्च निद्रया च पुनरनुपहतः प्रतीपैर्वा वचोभिर्दानयमनियमादिभिर्वा", text: "pūrvarātre 'lpaṃ cirācca phalaṃ karoti gosarge mahatsadyaśca nidrayā ca punaranupahataḥ pratīpairvā vacobhirdānayamaniyamādibhirvā" },
      { type: "verse", number: "14", sanskrit: "तत्र यः प्रेतैः सह मद्यं पिबन् शुनाकृष्यते स हन्यते ज्वरेण यो लाक्षारक्ताभमम्बरं पश्यति यो वा रक्तदेहमाल्यवस्त्रो हसन्नार्या ह्रियते स रक्तपित्तेन यो याम्यां दिशं खरोष्ट्रमहिषवराहान्यतमेन स यक्ष्मणा यस्य कण्टकिनी लता वंशस्तालो वा हृदि जायते स गुल्मेन यस्य शिरसि स शिरोरोगेण वा शिरच्छेदनेन यस्य नग्नस्याज्यावसिक्तस्याग्निमनर्चिषं जुह्वतो जायन्ते पद्मान्युरसि स कुष्ठेन यश्चण्डालैः सह स्नेहं पिबति स प्रमेहेण यो मत्तः सो ऽपस्मारेण यश्चन्द्रसूर्ययोरुपरागं पश्यति तस्य नेत्ररोग उपजायते यस्तयोः पतनं तस्य नेत्रविनाशः", text: "tatra yaḥ pretaiḥ saha madyaṃ piban śunākṛṣyate sa hanyate jvareṇa yo lākṣāraktābhamambaraṃ paśyati yo vā raktadehamālyavastro hasannāryā hriyate sa raktapittena yo yāmyāṃ diśaṃ kharoṣṭramahiṣavarāhānyatamena sa yakṣmaṇā yasya kaṇṭakinī latā vaṃśastālo vā hṛdi jāyate sa gulmena yasya śirasi sa śirorogeṇa vā śiracchedanena yasya nagnasyājyāvasiktasyāgnimanarciṣaṃ juhvato jāyante padmānyurasi sa kuṣṭhena yaścaṇḍālaiḥ saha snehaṃ pibati sa prameheṇa yo mattaḥ so 'pasmāreṇa yaścandrasūryayoruparāgaṃ paśyati tasya netraroga upajāyate yastayoḥ patanaṃ tasya netravināśaḥ" },
      { type: "verse", number: "15", sanskrit: "यः शष्कुलीरपूरान्वाभ्यवहृत्य प्रतिबुद्धश्छर्दयति यस्य शिरसि लतादयो जायन्ते वयांसि च निलीयन्ते मौड्यं वा भवति यो गृध्रोत्लूककाकाद्यैः प्रेतपिशाचरक्षोद्रविडान्ध्रस्त्रीचण्डालाद्यैर्वा परिवार्यते दक्षिणाभिमुखं वा स्त्रिया नृत्यन्नाकृष्यते अन्तावसायिभिर्वा स्वयं वा दिग्वासा याति शून्याटवीं वा कपिरथेन प्रेतैः प्रव्रजितैर्वा परिष्वज्यते नग्नो वा रक्तां स्रजं धारयति पङ्कदिग्धो हसति नृत्यति वा वेत्रवंशकण्टकतृणगहने संसृज्यते पतति वा पांसूपधानायां भुवि वल्मीकभस्मश्मशानश्वभ्रायतनेषु पङ्ककूपकलुषोदकेषु वा मज्जति स्रोतसा वा ह्रियते रक्तकुसुमवनां भूमिं गुहामन्धकाराचितां पापकर्मालयं संबाधं जननीं वा प्रविशति मत्स्येन वा ग्रस्यते श्मश्रुकर्म च यो गात्रवृद्धिं विवाहं चानुभवति शैलप्रासादाग्रात्पतत्यारोहति वा यूपपुष्पाड्यशाल्मलीकोविदारकिंशुकपारिभद्रकान्यो वा पराजीयते बध्यते छर्दयति विरिच्यते हृष्यति लभते वा हिरण्यलोहलवणतैलपिण्याककार्पासानश्नाति पक्वान्नं पिबति मद्यं स्नेहं वाभ्यज्यति निर्भर्त्स्यते वा कुपितैः पितृभिः चन्द्रार्कतारादीपदेवतानेत्रदर्शनान्यनुपततो नश्यतो वा पश्यति वक्रं वा बाहुमङ्गं वा विभिद्यमानं पुरुषान् वा नग्नान् कषायवाससो ऽसौम्यान् दण्डपाशहस्तान् कृष्णान्रक्ताक्षान् स्त्रियं वा कृष्णशुक्लदर्शनां दीर्घकेशस्तनीं कालरात्रिरूपां ते व्याधिताः पञ्चतामाप्नुवन्ति स्वस्थास्तु जीवितसन्देहमिति भवन्ति चात्र", text: "yaḥ śaṣkulīrapūrānvābhyavahṛtya pratibuddhaśchardayati yasya śirasi latādayo jāyante vayāṃsi ca nilīyante mauḍyaṃ vā bhavati yo gṛdhrotlūkakākādyaiḥ pretapiśācarakṣodraviḍāndhrastrīcaṇḍālādyairvā parivāryate dakṣiṇābhimukhaṃ vā striyā nṛtyannākṛṣyate antāvasāyibhirvā svayaṃ vā digvāsā yāti śūnyāṭavīṃ vā kapirathena pretaiḥ pravrajitairvā pariṣvajyate nagno vā raktāṃ srajaṃ dhārayati paṅkadigdho hasati nṛtyati vā vetravaṃśakaṇṭakatṛṇagahane saṃsṛjyate patati vā pāṃsūpadhānāyāṃ bhuvi valmīkabhasmaśmaśānaśvabhrāyataneṣu paṅkakūpakaluṣodakeṣu vā majjati srotasā vā hriyate raktakusumavanāṃ bhūmiṃ guhāmandhakārācitāṃ pāpakarmālayaṃ saṃbādhaṃ jananīṃ vā praviśati matsyena vā grasyate śmaśrukarma ca yo gātravṛddhiṃ vivāhaṃ cānubhavati śailaprāsādāgrātpatatyārohati vā yūpapuṣpāḍyaśālmalīkovidārakiṃśukapāribhadrakānyo vā parājīyate badhyate chardayati viricyate hṛṣyati labhate vā hiraṇyalohalavaṇatailapiṇyākakārpāsānaśnāti pakvānnaṃ pibati madyaṃ snehaṃ vābhyajyati nirbhartsyate vā kupitaiḥ pitṛbhiḥ candrārkatārādīpadevatānetradarśanānyanupatato naśyato vā paśyati vakraṃ vā bāhumaṅgaṃ vā vibhidyamānaṃ puruṣān vā nagnān kaṣāyavāsaso 'saumyān daṇḍapāśahastān kṛṣṇānraktākṣān striyaṃ vā kṛṣṇaśukladarśanāṃ dīrghakeśastanīṃ kālarātrirūpāṃ te vyādhitāḥ pañcatāmāpnuvanti svasthāstu jīvitasandehamiti bhavanti cātra" },
      { type: "verse", number: "16", sanskrit: "मनोवहानां पूर्णत्वात् स्रोतसां प्रबलैर्मलैः दृश्यन्ते दारुणाः स्वप्ना विनाशाभिमुखात्मभिः", text: "manovahānāṃ pūrṇatvāt srotasāṃ prabalairmalaiḥ dṛśyante dāruṇāḥ svapnā vināśābhimukhātmabhiḥ" },
      { type: "verse", number: "17", sanskrit: "अकल्याणमपि स्वप्नं दृष्ट्वा तत्रैव यः पुनः पश्येत् सौम्यं शुभं तस्य शुभमेव फलं भवेत्", text: "akalyāṇamapi svapnaṃ dṛṣṭvā tatraiva yaḥ punaḥ paśyet saumyaṃ śubhaṃ tasya śubhameva phalaṃ bhavet" },
      { type: "verse", number: "18", sanskrit: "देवान् द्विजान् गोवृषभान् जीवतः सुहृदो नृपान् साधून्यशस्विनो वह्निमिद्धं स्वच्छान् जलाशयान्", text: "devān dvijān govṛṣabhān jīvataḥ suhṛdo nṛpān sādhūnyaśasvino vahnimiddhaṃ svacchān jalāśayān" },
      { type: "verse", number: "19", sanskrit: "कन्याः कुमारकान् गौरान् शुक्लवस्त्रान् सुतेजसः नराशनं दीप्ततनुं समन्ताद्रुधिरोक्षितम्", text: "kanyāḥ kumārakān gaurān śuklavastrān sutejasaḥ narāśanaṃ dīptatanuṃ samantādrudhirokṣitam" },
      { type: "verse", number: "20", sanskrit: "यः पश्येल्लभते यो वा छत्रादर्शविषामिषम् शुक्लाः सुमनसो वस्त्रममेध्यालेपनं फलम्", text: "yaḥ paśyellabhate yo vā chatrādarśaviṣāmiṣam śuklāḥ sumanaso vastramamedhyālepanaṃ phalam" },
      { type: "verse", number: "21", sanskrit: "शैलप्रासादसफलवृक्षसिंहनरद्विपान् आरोहेत् गो ऽश्वयानं च तरेन्नदह्रदोदधीन्", text: "śailaprāsādasaphalavṛkṣasiṃhanaradvipān ārohet go 'śvayānaṃ ca tarennadahradodadhīn" },
      { type: "verse", number: "22", sanskrit: "पूर्वोत्तरेण गमनमगम्यागमनं मृतिः सम्बाधान्निस्सृतिः स्पर्शास्तारकाचलभास्वताम्", text: "pūrvottareṇa gamanamagamyāgamanaṃ mṛtiḥ sambādhānnissṛtiḥ sparśāstārakācalabhāsvatām" },
      { type: "verse", number: "23", sanskrit: "रोदनं पतितोत्थानं द्विषतां चावमर्दनम् यस्य स्यादायुरारोग्यं वित्तं स बहुशो ऽश्नुते", text: "rodanaṃ patitotthānaṃ dviṣatāṃ cāvamardanam yasya syādāyurārogyaṃ vittaṃ sa bahuśo 'śnute" },
      { type: "verse", number: "24", sanskrit: "पितृदेवद्विजातीनां क्रुद्धभीतकृशात्मनाम् मलिनाम्बरपुष्पाणां दर्शनं न प्रशस्यते", text: "pitṛdevadvijātīnāṃ kruddhabhītakṛśātmanām malināmbarapuṣpāṇāṃ darśanaṃ na praśasyate" },
      { type: "verse", number: "25", sanskrit: "तेषामेव तु तुष्टानां शुद्धपुष्पाम्बरात्मनाम् दर्शनं शस्यते स्वप्ने तैश्च सम्भाषणं शुभम्", text: "teṣāmeva tu tuṣṭānāṃ śuddhapuṣpāmbarātmanām darśanaṃ śasyate svapne taiśca sambhāṣaṇaṃ śubham" },
      { type: "verse", number: "26", sanskrit: "दृष्ट्वा स्वप्नान् दारुणान् शोभनान् वा प्रातः स्नातः सर्षपानग्निवर्णान् हुत्वा सावित्र्या सर्पिषाक्तांस्तिलान्वा पूतः पापैर्मुच्यते व्याधिभिश्च", text: "dṛṣṭvā svapnān dāruṇān śobhanān vā prātaḥ snātaḥ sarṣapānagnivarṇān hutvā sāvitryā sarpiṣāktāṃstilānvā pūtaḥ pāpairmucyate vyādhibhiśca" },
      { type: "verse", number: "27", sanskrit: "मङ्गलाचारसम्पन्नपरिवारस्तथातुरः श्रद्दधानो ऽनुकूलश्च प्रभूतद्रव्यसङ्ग्रहः", text: "maṅgalācārasampannaparivārastathāturaḥ śraddadhāno 'nukūlaśca prabhūtadravyasaṅgrahaḥ" },
      { type: "verse", number: "28", sanskrit: "सत्त्वलक्षणसंयोगो भक्तिर्वैद्यद्विजातिषु चिकित्सायामनिर्वेदस्तदारोग्यस्य लक्षणम्", text: "sattvalakṣaṇasaṃyogo bhaktirvaidyadvijātiṣu cikitsāyāmanirvedastadārogyasya lakṣaṇam" },
      { type: "verse", number: "29", sanskrit: "इत्यत्र जन्ममरणं यतः सम्यगुदाहृतम् शरीरस्य ततः स्थानं शारीरमिदमुच्यते", text: "ityatra janmamaraṇaṃ yataḥ samyagudāhṛtam śarīrasya tataḥ sthānaṃ śārīramidamucyate" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 1,
    lang: "sa",
    content: [
      { type: "heading", heading: "Джвара нидана — лихорадка" },
      { type: "text", text: "Глава 1 Нидана стханы — диагностический раздел о лихорадка. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातः सर्वरोगनिदानं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ sarvaroganidānaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "इह कृतयुगे विगतरागद्वेषादिद्वन्द्वा जितलोभक्रोधश्रमक्लमालस्यभया निष्परिग्रहाः पुरुषा बभूवुः तेषां पुण्यबलेन पृथिव्यादीनां सर्वगुणसमुदायादचिन्त्यरस वीर्यादिसमुदितानि सस्यान्योषधयश्चासन् ते तानि जितेन्द्रियत्वात् काले मात्रया चोपयुञ्जानाः सत्यार्जवानृशंस्यादिगुणयोगाच्च सुरसदृशतेजसो रूपाकृतिप्रमाणप्रसादोपचयसंहननसत्त्वसारसम्पन्ना दीर्घायुषो नीरुजश्च बभूवुः", text: "iha kṛtayuge vigatarāgadveṣādidvandvā jitalobhakrodhaśramaklamālasyabhayā niṣparigrahāḥ puruṣā babhūvuḥ teṣāṃ puṇyabalena pṛthivyādīnāṃ sarvaguṇasamudāyādacintyarasa vīryādisamuditāni sasyānyoṣadhayaścāsan te tāni jitendriyatvāt kāle mātrayā copayuñjānāḥ satyārjavānṛśaṃsyādiguṇayogācca surasadṛśatejaso rūpākṛtipramāṇaprasādopacayasaṃhananasattvasārasampannā dīrghāyuṣo nīrujaśca babhūvuḥ" },
      { type: "verse", number: "3", sanskrit: "भ्रश्यन्ति तु कृतयुगे युगस्वभावात् क्रमेण परिहीयमाणसर्वगुणेषु पृथिव्यादिषु शरीरेषु च धर्मातिक्रमात् पुरुषेष्ववश्यम्भाविनो निरपेक्षरूक्षाभिरुपेक्षिता देवताभिर्ज्वरादयः प्रादुरभूवन्निति सर्वरोगाणां सामान्यतः सम्भवः", text: "bhraśyanti tu kṛtayuge yugasvabhāvāt krameṇa parihīyamāṇasarvaguṇeṣu pṛthivyādiṣu śarīreṣu ca dharmātikramāt puruṣeṣvavaśyambhāvino nirapekṣarūkṣābhirupekṣitā devatābhirjvarādayaḥ prādurabhūvanniti sarvarogāṇāṃ sāmānyataḥ sambhavaḥ" },
      { type: "verse", number: "4", sanskrit: "ज्वरस्तु स्थाणुशापात् प्राचेतसत्वमुपागतस्य प्रजापतेः क्रतौ भागमपरिकल्पयतस्तद्विनाशार्थं पूर्वजन्मावमानितया रुद्राण्या प्रेरितस्य पशुपतेर्दिव्यमब्दसहस्रं परिरक्षितवतः क्रोधमतिचिरकालसम्भृतो व्रतान्ते रोषाग्निः किङ्कररूपेण किल पिण्डितमूर्तिर्वीरभद्रनामा भस्मप्रहरणस्त्रिशिरोक्षिबाहुपादः पिङ्गललोचनो दर्ष्ट्री शङ्कुकर्णः कृष्णतनुरुत्तमाङ्गान्निश्चचार स देवीविनिर्मितया सह भद्रकाल्या प्रतिरोमकूपमभिनिःसृतैर्विविधविकृताकृतिभिरनन्तैर्भयानकवाक्यक्रियावपुर्भिरनुचरैः परिवृतश्चतुर्युगान्तकरकालाम्भोदसहस्रनिनदो ऽनुनादयन् रोदसी ज्वालागर्भेण परीतः कलकलारावेण महाभूतसम्प्लवकारिणा विधाय दानववधमश्वमेधाध्वरविध्वंसनं च प्राञ्जलिर्विज्ञापयामास शिवम् शिवीभूतो ऽसि देवदेव देवैः पितामहप्रभृतिभिर्जगतः पित्रा च धात्राभिष्टूयमानः सम्प्रत्यहं किं करवाणीति तं शूली क्रोधमादिदेश यस्मात् त्रिदशैरप्यजय्य मत्क्रोध व्रतविघ्नं चिकीर्षुदत्यसैन्यं दक्षो दक्षहव्यं च त्वया जीर्णमतो जगतो ऽस्य सस्थावरस्य ज्वरयिता ज्वरो भवान् भवतु त्वं हि सर्घरोगाणां प्रथमः प्रवरो जन्ममरणेषु तमोमयतया महामोहः प्राग्जन्मनो विस्मारयितापचारान्तरेषु चोष्मायमाणत्वात् सन्तापात्मा द्वयेष्वपि ध्रुवो ज्वरो भवेति सो ऽयमेवमुमापतिनानुगृहीतो नानानामभिः सर्वतो ऽनुभुवि विचरति तद्यथा पाकलो गजेष्वभितापो वाजिष्वलर्कः कक्कुरेष्विन्द्रमदो जलजेषु ज्योतिरोषधीषु चूर्णको धान्येष्वप्सु नीलिका भूमावूषरो मनुष्येषु ज्वर इति", text: "jvarastu sthāṇuśāpāt prācetasatvamupāgatasya prajāpateḥ kratau bhāgamaparikalpayatastadvināśārthaṃ pūrvajanmāvamānitayā rudrāṇyā preritasya paśupaterdivyamabdasahasraṃ parirakṣitavataḥ krodhamaticirakālasambhṛto vratānte roṣāgniḥ kiṅkararūpeṇa kila piṇḍitamūrtirvīrabhadranāmā bhasmapraharaṇastriśirokṣibāhupādaḥ piṅgalalocano darṣṭrī śaṅkukarṇaḥ kṛṣṇatanuruttamāṅgānniścacāra sa devīvinirmitayā saha bhadrakālyā pratiromakūpamabhiniḥsṛtairvividhavikṛtākṛtibhiranantairbhayānakavākyakriyāvapurbhiranucaraiḥ parivṛtaścaturyugāntakarakālāmbhodasahasraninado 'nunādayan rodasī jvālāgarbheṇa parītaḥ kalakalārāveṇa mahābhūtasamplavakāriṇā vidhāya dānavavadhamaśvamedhādhvaravidhvaṃsanaṃ ca prāñjalirvijñāpayāmāsa śivam śivībhūto 'si devadeva devaiḥ pitāmahaprabhṛtibhirjagataḥ pitrā ca dhātrābhiṣṭūyamānaḥ sampratyahaṃ kiṃ karavāṇīti taṃ śūlī krodhamādideśa yasmāt tridaśairapyajayya matkrodha vratavighnaṃ cikīrṣudatyasainyaṃ dakṣo dakṣahavyaṃ ca tvayā jīrṇamato jagato 'sya sasthāvarasya jvarayitā jvaro bhavān bhavatu tvaṃ hi sargharogāṇāṃ prathamaḥ pravaro janmamaraṇeṣu tamomayatayā mahāmohaḥ prāgjanmano vismārayitāpacārāntareṣu coṣmāyamāṇatvāt santāpātmā dvayeṣvapi dhruvo jvaro bhaveti so 'yamevamumāpatinānugṛhīto nānānāmabhiḥ sarvato 'nubhuvi vicarati tadyathā pākalo gajeṣvabhitāpo vājiṣvalarkaḥ kakkureṣvindramado jalajeṣu jyotiroṣadhīṣu cūrṇako dhānyeṣvapsu nīlikā bhūmāvūṣaro manuṣyeṣu jvara iti" },
      { type: "verse", number: "5", sanskrit: "तत्सहजाश्चारोचकाङ्गमर्दशिरोव्यथाभ्रमक्लमग्लानितृष्णासन्तापादयः तत्सन्तापाच्च रक्तपित्तम् तत्रैव च यज्ञे क्रोधभयाभिभूतानां परितो विद्रवतां लङ्घनप्लवनाद्यैर्देहविक्षोभणैर्गुल्मविद्रधिवृद्धिजठरादयो हविःप्राशान्मेहकुष्ठार्शःशोफातीसारादयो भयोत्त्रासशोकाशुचिसंस्पर्शैरुन्मादापस्मारग्रहादयो रोहिण्यतिप्रसङ्गाच्छेषदुहित्रसम्भोगकृताच्च प्रजापतिक्रोधान्नक्षत्रराजस्य राजयक्ष्मा तत्सहोद्भवाश्च कासश्वासादयः सो ऽपि हि न विना ज्वरेणानुबध्नातीति सकलो ऽपि रोगग्रामो ज्वरपूर्वको ज्वरशब्दवाच्यो वा", text: "tatsahajāścārocakāṅgamardaśirovyathābhramaklamaglānitṛṣṇāsantāpādayaḥ tatsantāpācca raktapittam tatraiva ca yajñe krodhabhayābhibhūtānāṃ parito vidravatāṃ laṅghanaplavanādyairdehavikṣobhaṇairgulmavidradhivṛddhijaṭharādayo haviḥprāśānmehakuṣṭhārśaḥśophātīsārādayo bhayottrāsaśokāśucisaṃsparśairunmādāpasmāragrahādayo rohiṇyatiprasaṅgāccheṣaduhitrasambhogakṛtācca prajāpatikrodhānnakṣatrarājasya rājayakṣmā tatsahodbhavāśca kāsaśvāsādayaḥ so 'pi hi na vinā jvareṇānubadhnātīti sakalo 'pi rogagrāmo jvarapūrvako jvaraśabdavācyo vā" },
      { type: "verse", number: "6", sanskrit: "ज्वरस्तमो विकार आतङ्कः पाप्मा गदो व्याधिराबाधो दुःखमामयो यक्ष्मा रोग इत्यनर्थान्तरम् तत्र रुजतीति रोगः तस्योपलब्धिर्निदानपूर्वरूपरूपोपशयसम्प्राप्तिभिः", text: "jvarastamo vikāra ātaṅkaḥ pāpmā gado vyādhirābādho duḥkhamāmayo yakṣmā roga ityanarthāntaram tatra rujatīti rogaḥ tasyopalabdhirnidānapūrvarūparūpopaśayasamprāptibhiḥ" },
      { type: "verse", number: "7", sanskrit: "तत्र निदानं वाय्वादिप्रकोपः तस्य पुनरहिताहारविहारसेवा निदानपर्यायास्तु हेतुर्निमित्तमायतनं कारकः कर्ता कारणं प्रत्ययः समुत्थानं मूलं योनिरिति", text: "tatra nidānaṃ vāyvādiprakopaḥ tasya punarahitāhāravihārasevā nidānaparyāyāstu heturnimittamāyatanaṃ kārakaḥ kartā kāraṇaṃ pratyayaḥ samutthānaṃ mūlaṃ yoniriti" },
      { type: "verse", number: "8", sanskrit: "पूर्वरूपं नाम येन भाविव्याधिविशेषो विज्ञायते न तु दोषविशेषः तद्ध्युत्पत्स्यमानस्य व्याधेरल्पत्वादव्यक्तं रूपम्", text: "pūrvarūpaṃ nāma yena bhāvivyādhiviśeṣo vijñāyate na tu doṣaviśeṣaḥ taddhyutpatsyamānasya vyādheralpatvādavyaktaṃ rūpam" },
      { type: "verse", number: "9", sanskrit: "स्पष्टं पुना रूपम् तस्य शब्दान्तराणि लिङ्गमाकृतिर्लक्षणं चिह्नं संस्थानं व्यञ्जनमिति", text: "spaṣṭaṃ punā rūpam tasya śabdāntarāṇi liṅgamākṛtirlakṣaṇaṃ cihnaṃ saṃsthānaṃ vyañjanamiti" },
      { type: "verse", number: "10", sanskrit: "उपशयो हेतुव्याधिविपरीतैर्विपरीतार्थकारिभिश्चचौषधाहारविहारैः सुखानुबन्धः स हि व्याधिसात्म्यसंज्ञः तद्विपरीतो ऽनुपशयः एतेन देशकालौ व्याख्यातौ", text: "upaśayo hetuvyādhiviparītairviparītārthakāribhiścacauṣadhāhāravihāraiḥ sukhānubandhaḥ sa hi vyādhisātmyasaṃjñaḥ tadviparīto 'nupaśayaḥ etena deśakālau vyākhyātau" },
      { type: "verse", number: "11", sanskrit: "सम्प्राप्तिः पुनरेवंदुष्टो दोषस्तेन चैवमारब्धो व्याधिस्तत्पर्याया जातिरागतिर्निर्वृत्तिर्निष्पत्तिरिति", text: "samprāptiḥ punarevaṃduṣṭo doṣastena caivamārabdho vyādhistatparyāyā jātirāgatirnirvṛttirniṣpattiriti" },
      { type: "verse", number: "12", sanskrit: "सा सङ्ख्याविकल्पप्राधान्यबलकालविशेषैर्भिद्यते तत्र सङ्ख्या तावदष्टौ ज्वरास्त्रिविधं रक्तपित्तं पञ्च कासा इति विकल्पः समवेतानां दोषाणामंशांशकल्पना प्राधान्यं व्याधिनामनुबन्ध्यानुबन्धकभेदात्तरतमयोगाद्वा दोषाणाम् बलाबलविशेषो हेत्वादिकार्त्स्न्यावयवविभावनया कालविशेषः पुनर्दोषाणामृत्वहोरात्र्याहारसमयनियतः प्रकोप इति एतावतैव समासतः कथितो निदानार्थः विस्तरेण तु यथास्वं प्रतिरोगमुपदेक्ष्यते", text: "sā saṅkhyāvikalpaprādhānyabalakālaviśeṣairbhidyate tatra saṅkhyā tāvadaṣṭau jvarāstrividhaṃ raktapittaṃ pañca kāsā iti vikalpaḥ samavetānāṃ doṣāṇāmaṃśāṃśakalpanā prādhānyaṃ vyādhināmanubandhyānubandhakabhedāttaratamayogādvā doṣāṇām balābalaviśeṣo hetvādikārtsnyāvayavavibhāvanayā kālaviśeṣaḥ punardoṣāṇāmṛtvahorātryāhārasamayaniyataḥ prakopa iti etāvataiva samāsataḥ kathito nidānārthaḥ vistareṇa tu yathāsvaṃ pratirogamupadekṣyate" },
      { type: "verse", number: "13", sanskrit: "अथ तिक्तकटुकषायरूक्षलघुशीतविष्टम्भिविरूढकतृणधान्यकलायचणककरीरतुम्बकालिङ्गचिर्भिटबिसशालूकजाम्बवतिन्दुकहीनशुष्कप्रमिततृषिताशनक्षुधिताम्बुपानासृक्क्षयविरेचनादिकर्मातियोगवेगविधारणोदीरणरात्रिजागरणप्रवातव्यवायज्यायामबलवद्युद्धनिग्रहातिखरचापकर्षणात्युच्चविषमलङ्घनाध्वाध्ययनधावनसलिलतरणाभिघातदम्यगोवाजिगजनिग्रहाश्मशिलालोहकाष्ठोत्क्षेपविक्षेपभ्रमणचालनगाढोच्छादनपराघातनादिसाहसभयशोकोत्कण्ठादिभिरतिसेवितैर्ग्रीष्मवर्षापराह्णापररात्राहारपरिणामान्तेषु च वायुः प्रकोपमापद्यते", text: "atha tiktakaṭukaṣāyarūkṣalaghuśītaviṣṭambhivirūḍhakatṛṇadhānyakalāyacaṇakakarīratumbakāliṅgacirbhiṭabisaśālūkajāmbavatindukahīnaśuṣkapramitatṛṣitāśanakṣudhitāmbupānāsṛkkṣayavirecanādikarmātiyogavegavidhāraṇodīraṇarātrijāgaraṇapravātavyavāyajyāyāmabalavadyuddhanigrahātikharacāpakarṣaṇātyuccaviṣamalaṅghanādhvādhyayanadhāvanasalilataraṇābhighātadamyagovājigajanigrahāśmaśilālohakāṣṭhotkṣepavikṣepabhramaṇacālanagāḍhocchādanaparāghātanādisāhasabhayaśokotkaṇṭhādibhiratisevitairgrīṣmavarṣāparāhṇāpararātrāhārapariṇāmānteṣu ca vāyuḥ prakopamāpadyate" },
      { type: "verse", number: "14", sanskrit: "कट्वम्ललवणक्षारोष्णतीक्ष्णविदाहिशुक्तशाण्डाकीमद्यमूत्रमस्तुदधिधान्याम्लतैलकुलत्थमाषनिष्पावतिलान्नकट्वरकुठेरकादिवर्गामाम्रातकाम्लीकापीलुभल्लातकास्थिलाङ्गलिकामरिचातपाग्निरजोधूमक्रोधेर्ष्याजीर्णमैथुनोपगमनादिभिर्वर्षाशरन्मध्यन्दिनार्धरात्राहारविदाहकालेषु च पित्तम्", text: "kaṭvamlalavaṇakṣāroṣṇatīkṣṇavidāhiśuktaśāṇḍākīmadyamūtramastudadhidhānyāmlatailakulatthamāṣaniṣpāvatilānnakaṭvarakuṭherakādivargāmāmrātakāmlīkāpīlubhallātakāsthilāṅgalikāmaricātapāgnirajodhūmakrodherṣyājīrṇamaithunopagamanādibhirvarṣāśaranmadhyandinārdharātrāhāravidāhakāleṣu ca pittam" },
      { type: "verse", number: "15", sanskrit: "मधुराम्ललवणस्निग्धगुरुशीतपिच्छिलाभिष्यन्दि नवान्नपिष्टपृथुकस्थूलभक्ष्यशष्कुल्यामक्षीरकीलाटमोरटकूचीकातक्रपिण्डकपीयुषेक्षुरसफाणितगुडानूपपिशितमोचखर्जूरभव्यनारिकेलनिशाम्बुपानात्यम्बुपानातिसन्तर्पणभुक्तमात्रदिवास्वप्नकालातिस्वप्नकायवाङ्मनो व्यापारानारम्भानुपधानशयनावश्यायहर्षच्छीर्दविघातविरेचनाद्ययोगादिभिः शिशिरवसन्तपूर्वाह्णप्रदोषभुक्तमात्रेषु च श्लेष्मा", text: "madhurāmlalavaṇasnigdhaguruśītapicchilābhiṣyandi navānnapiṣṭapṛthukasthūlabhakṣyaśaṣkulyāmakṣīrakīlāṭamoraṭakūcīkātakrapiṇḍakapīyuṣekṣurasaphāṇitaguḍānūpapiśitamocakharjūrabhavyanārikelaniśāmbupānātyambupānātisantarpaṇabhuktamātradivāsvapnakālātisvapnakāyavāṅmano vyāpārānārambhānupadhānaśayanāvaśyāyaharṣacchīrdavighātavirecanādyayogādibhiḥ śiśiravasantapūrvāhṇapradoṣabhuktamātreṣu ca śleṣmā" },
      { type: "verse", number: "16", sanskrit: "द्वयसंसर्गात् संसर्गः सर्वेषां तु मिश्रीभावात्तथाध्यशनसमशनविषमाशनविरुद्धाशनसङ्कीर्णाशनव्यापन्नाम्बुमद्यमन्दकदधियावकयवसुरापिण्याकाममूलकसर्षपशुष्कशाकवल्लूरकृशपिशितलकुचामफलमृत्तिकाभ्यवहारान्नपरिवर्तर्तुव्यापदसात्म्यौषधिगन्धाघ्राणविषपिटकाविषगराभ्यवहारानार्तवदुर्दिनग्रहपीडाग्रहावेशपुरोवातपर्वतोपश्लेषरसायनस्नेहस्वेदविरेचनादिमिथ्यायोगेभ्यः पापानां च कर्मणामभ्यासात् पूर्वकृतानां च परिणामात् स्त्रीणां विषमप्रसवात् प्रसूतानां च मिथ्योपचारात् सन्निपातः", text: "dvayasaṃsargāt saṃsargaḥ sarveṣāṃ tu miśrībhāvāttathādhyaśanasamaśanaviṣamāśanaviruddhāśanasaṅkīrṇāśanavyāpannāmbumadyamandakadadhiyāvakayavasurāpiṇyākāmamūlakasarṣapaśuṣkaśākavallūrakṛśapiśitalakucāmaphalamṛttikābhyavahārānnaparivartartuvyāpadasātmyauṣadhigandhāghrāṇaviṣapiṭAkāviṣagarābhyavahārānārtavadurdinagrahapīḍāgrahāveśapurovātaparvatopaśleṣarasāyanasnehasvedavirecanādimithyāyogebhyaḥ pāpānāṃ ca karmaṇāmabhyāsāt pūrvakṛtānāṃ ca pariṇāmāt strīṇāṃ viṣamaprasavāt prasūtānāṃ ca mithyopacārāt sannipātaḥ" },
      { type: "verse", number: "17", sanskrit: "इति सामान्यतः सर्वेषु रोगेषु दोषप्रकोपहेतुरुक्त इति भवन्ति चात्र", text: "iti sāmānyataḥ sarveṣu rogeṣu doṣaprakopaheturukta iti bhavanti cātra" },
      { type: "verse", number: "18", sanskrit: "प्रतिरोगमिति क्रुद्धा रोगाधिष्ठानगामिनीः रसायनीः प्रपद्याशु दोषा देहे विकुर्वते", text: "pratirogamiti kruddhā rogādhiṣṭhānagāminīḥ rasāyanīḥ prapadyāśu doṣā dehe vikurvate" },
      { type: "verse", number: "19", sanskrit: "आधानजन्मनिधनप्रत्यराख्यविपत्करे नक्षत्रे व्याधिरुत्पन्नः क्लेशाय मरणाय वा", text: "ādhānajanmanidhanapratyarākhyavipatkare nakṣatre vyādhirutpannaḥ kleśāya maraṇāya vā" },
      { type: "verse", number: "20", sanskrit: "ज्वरस्तु जातः षड्रात्रादश्विनीषु निवर्तते भरणीषु तु पञ्चाहात् सप्ताहात् कृत्तिकासु तु", text: "jvarastu jātaḥ ṣaḍrātrādaśvinīṣu nivartate bharaṇīṣu tu pañcāhāt saptāhāt kṛttikāsu tu" },
      { type: "verse", number: "21", sanskrit: "त्रिः सप्तरात्रादथवा रोहिण्यामष्टरात्रतः एकादशाद्वा दिवसान्मृगे षण्णवरात्रयोः", text: "triḥ saptarātrādathavā rohiṇyāmaṣṭarātrataḥ ekādaśādvā divasānmṛge ṣaṇṇavarātrayoḥ" },
      { type: "verse", number: "22", sanskrit: "पञ्चाहान्मृत्युरार्द्रायां त्रिपक्षे संशयो ऽथवा पुनर्वसौ प्रवृत्तस्तु ज्वरो ऽपैति त्रयोदशात्", text: "pañcāhānmṛtyurārdrāyāṃ tripakṣe saṃśayo 'thavā punarvasau pravṛttastu jvaro 'paiti trayodaśāt" },
      { type: "verse", number: "23", sanskrit: "दिवसात् सप्तविंशाद्वा द्व्यहात् सप्ताहतो ऽथवा पुष्ये श्लेषासु मरणं चिरेणापि मघासु तु", text: "divasāt saptaviṃśādvā dvyahāt saptāhato 'thavā puṣye śleṣāsu maraṇaṃ cireṇāpi maghāsu tu" },
      { type: "verse", number: "24", sanskrit: "अवश्यं स्वास्थ्यमाप्नोति द्वादशाहान्मृतो न चेत् फाल्गुन्योः पूर्वयोर्मृत्युरन्यथोश्च दिने ऽष्टमे", text: "avaśyaṃ svāsthyamāpnoti dvādaśāhānmṛto na cet phālgunyoḥ pūrvayormṛtyuranyathośca dine 'ṣṭame" },
      { type: "verse", number: "25", sanskrit: "नव्मे ऽग्न्येकविंशे वा ज्वरः सौम्यत्वमृच्छति हस्तेन सप्तमे शान्तिश्चित्रायामष्टमे ऽथवा", text: "navme 'gnyekaviṃśe vā jvaraḥ saumyatvamṛcchati hastena saptame śāntiścitrāyāmaṣṭame 'thavā" },
      { type: "verse", number: "26", sanskrit: "पुनश्चित्रागमे स्वातौ दशाहादथ वा त्रिभिः पक्षैर्मृत्युं विशाखासु द्वाविंशे ऽहनि निर्दिशेत्", text: "punaścitrāgame svātau daśāhādatha vā tribhiḥ pakṣairmṛtyuṃ viśākhāsu dvāviṃśe 'hani nirdiśet" },
      { type: "verse", number: "27", sanskrit: "नवमे ऽह्नि न चेच्छान्तिर्मैत्रे मृत्युस्ततः परम् ज्येष्ठायां पञ्चमे मृत्युरूर्ध्वं वा द्वादशात् सुखम्", text: "navame 'hni na cecchāntirmaitre mṛtyustataḥ param jyeṣṭhāyāṃ pañcame mṛtyurūrdhvaṃ vā dvādaśāt sukham" },
      { type: "verse", number: "28", sanskrit: "स्वास्थ्यं दशाहान्मूले तु त्रिसप्ताहे ऽथ वा गते पूर्वाषाढासु नवमे ततो ऽन्यासु तु मासतः", text: "svāsthyaṃ daśāhānmūle tu trisaptāhe 'tha vā gate pūrvāṣāḍhāsu navame tato 'nyāsu tu māsataḥ" },
      { type: "verse", number: "29", sanskrit: "अष्टाभिरथवा मासैर्नव्भिर्वा भवेच्छिवम् आज्येष्ठाहाद्धनिष्ठासु द्वादशाद्वारुणेषु तु", text: "aṣṭābhirathavā māsairnavbhirvā bhavecchivam ājyeṣṭhāhāddhaniṣṭhāsu dvādaśādvāruṇeṣu tu" },
      { type: "verse", number: "30", sanskrit: "षडहे द्वादशाहे वा मृत्युर्भाद्रपदासु तु उत्तरासु त्रिसप्ताहात् प्रशमो रेवतीषु च", text: "ṣaḍahe dvādaśāhe vā mṛtyurbhādrapadāsu tu uttarāsu trisaptāhāt praśamo revatīṣu ca" },
      { type: "verse", number: "31", sanskrit: "चतूरात्रे ऽष्टरात्रे वा क्षेममित्याह गौतमः", text: "catūrātre 'ṣṭarātre vā kṣemamityāha gautamaḥ" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 2,
    lang: "sa",
    content: [
      { type: "heading", heading: "Рактапитта нидана — кровотечения" },
      { type: "text", text: "Глава 2 Нидана стханы — диагностический раздел о кровотечения. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातो ज्वरनिदानं व्याख्यास्यामाः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto jvaranidānaṃ vyākhyāsyāmāḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अष्टाभिः कारणैर्ज्वरः सञ्जायते मनुष्याणां पृथग्दोषैः संसृष्टैः सन्निपतितैरागन्तुना च", text: "aṣṭābhiḥ kāraṇairjvaraḥ sañjāyate manuṣyāṇāṃ pṛthagdoṣaiḥ saṃsṛṣṭaiḥ sannipatitairāgantunā ca" },
      { type: "verse", number: "3", sanskrit: "तत्र यथोक्तैः प्रकोपणविशेषैः प्रकुपिता दोषाः प्रविश्यामाशयमूष्मणा मिश्रीभूयाममनुगम्य रसस्वेदवाहीनि स्रोतांसि पिधाय पित्तं तु द्रवत्वात्तप्तमिव जलमनलमुपहत्य सर्वे ऽपि च दोषाः पक्तारं स्वस्थानाद्बहिर्निरस्य सह तेन सकलमपि शरीरमभिसर्पन्तः तत्सम्पर्काल्लब्धबलेन स्वेनोष्मणा नितरां देहोष्माणमेधयन्तो ऽन्तस्स्रोतोमुखपिधानात् स्तम्भमादधाना बहिरपि स्वेदमपहरन्तः सर्वेन्द्रियाणि चोपतापयन्तो ज्वरमभिनिर्वर्तयन्ति", text: "tatra yathoktaiḥ prakopaṇaviśeṣaiḥ prakupitā doṣāḥ praviśyāmāśayamūṣmaṇā miśrībhūyāmamanugamya rasasvedavāhīni srotāṃsi pidhāya pittaṃ tu dravatvāttaptamiva jalamanalamupahatya sarve 'pi ca doṣāḥ paktāraṃ svasthānādbahirnirasya saha tena sakalamapi śarīramabhisarpantaḥ tatsamparkāllabdhabalena svenoṣmaṇā nitarāṃ dehoṣmāṇamedhayanto 'ntassrotomukhapidhānāt stambhamādadhānā bahirapi svedamapaharantaḥ sarvendriyāṇi copatāpayanto jvaramabhinirvartayanti" },
      { type: "verse", number: "4", sanskrit: "तस्येमानि पूर्वरूपाणि मुखवैरस्यमन्नानभिलाषो गुरुगात्रत्वमालस्यमल्पप्राणता गतिस्खलनं निद्राधिक्यमरतिरसूया हितोपदेशेषु प्रद्वेषो बालेषु मधुरेषु च भक्ष्येष्वम्ललवणकटुकाभिनन्दनमविपाके ऽङ्गमर्दश्चक्षुषोराकुलत्वं साश्रुता जृम्भा विनामः क्लमो रोमहर्षः शब्दानलाम्बुशीतवातच्छायातपेष्वकस्मादिच्छाद्वेषौ च तदनन्तरं व्यक्तीभावो ज्वरस्येति भवति चात्र", text: "tasyemāni pūrvarūpāṇi mukhavairasyamannānabhilāṣo gurugātratvamālasyamalpaprāṇatā gatiskhalanaṃ nidrādhikyamaratirasūyā hitopadeśeṣu pradveṣo bāleṣu madhureṣu ca bhakṣyeṣvamlalavaṇakaṭukābhinandanamavipāke 'ṅgamardaścakṣuṣorākulatvaṃ sāśrutā jṛmbhā vināmaḥ klamo romaharṣaḥ śabdānalāmbuśītavātacchāyātapeṣvakasmādicchādveṣau ca tadanantaraṃ vyaktībhāvo jvarasyeti bhavati cātra" },
      { type: "verse", number: "5", sanskrit: "आगमापगमक्षोभमृदुता वेदनोष्मणाम् वैषम्यं तत्र तत्राङ्गे तास्ताः स्युर्वेदनाश्चलाः", text: "āgamāpagamakṣobhamṛdutā vedanoṣmaṇām vaiṣamyaṃ tatra tatrāṅge tāstāḥ syurvedanāścalāḥ" },
      { type: "verse", number: "6", sanskrit: "पादयोः सुप्तता स्तम्भः पिण्डिकोद्वेष्टनं क्लमः विश्लेष इव सन्धीनां साद ऊर्वोः कटीग्रहः", text: "pādayoḥ suptatā stambhaḥ piṇḍikodveṣṭanaṃ klamaḥ viśleṣa iva sandhīnāṃ sāda ūrvoḥ kaṭīgrahaḥ" },
      { type: "verse", number: "7", sanskrit: "पृष्ठं क्षोदमिवाप्नोति निष्पीड्यत इवोदरम् भिद्यन्त इव चास्थीनि पार्श्वगानि विशेषतः", text: "pṛṣṭhaṃ kṣodamivāpnoti niṣpīḍyata ivodaram bhidyanta iva cāsthīni pārśvagāni viśeṣataḥ" },
      { type: "verse", number: "8", sanskrit: "हृदयस्य ग्रहस्तोदः प्राजनेनेव वक्षसः स्कन्धयोर्मथनं बाह्वोर्भेदः पीडनमंसयोः", text: "hṛdayasya grahastodaḥ prājaneneva vakṣasaḥ skandhayormathanaṃ bāhvorbhedaḥ pīḍanamaṃsayoḥ" },
      { type: "verse", number: "9", sanskrit: "अशक्तिर्भक्षणे हन्वोर्जृम्भणं कर्णयोः स्वनः निस्तोदःशङ्खयोर्मूर्ध्नि वेदना विरसास्यता", text: "aśaktirbhakṣaṇe hanvorjṛmbhaṇaṃ karṇayoḥ svanaḥ nistodaḥśaṅkhayormūrdhni vedanā virasāsyatā" },
      { type: "verse", number: "10", sanskrit: "कषायास्यत्वमथवा मलानामप्रवर्तनम् रूक्षारुणत्वगास्याक्षिनखमूत्रपुरीषता", text: "kaṣāyāsyatvamathavā malānāmapravartanam rūkṣāruṇatvagāsyākṣinakhamūtrapurīṣatā" },
      { type: "verse", number: "11", sanskrit: "प्रसेकारोचकाश्रद्धाविपाकास्वेदजागराः कण्ठौष्ठशोषस्तृट्शुष्कौ छर्दिकासौ विषादिता", text: "prasekārocakāśraddhāvipākāsvedajāgarāḥ kaṇṭhauṣṭhaśoṣastṛṭśuṣkau chardikāsau viṣāditā" },
      { type: "verse", number: "12", sanskrit: "हर्षो रोमाङ्गदन्तेषु वेपथुः क्षवथोर्ग्रहः भ्रमः प्रलापो घर्मेच्छा विनामश्चानिलज्वरे", text: "harṣo romāṅgadanteṣu vepathuḥ kṣavathorgrahaḥ bhramaḥ pralāpo gharmecchā vināmaścānilajvare" },
      { type: "verse", number: "13", sanskrit: "युगपद्व्याप्तिरङ्गानां प्रलापः कटुवक्त्रता नासास्यपाकः शीतेच्छा भ्रमो मूर्छा मदो ऽरतिः", text: "yugapadvyāptiraṅgānāṃ pralāpaḥ kaṭuvaktratā nāsāsyapākaḥ śītecchā bhramo mūrchā mado 'ratiḥ" },
      { type: "verse", number: "14", sanskrit: "विट्स्रंसः पित्तवमनं रक्तष्ठीवनमम्लकः रक्तकोठोद्गमः पीतहरितत्वं त्वगादिषु", text: "viṭsraṃsaḥ pittavamanaṃ raktaṣṭhīvanamamlakaḥ raktakoṭhodgamaḥ pītaharitatvaṃ tvagādiṣu" },
      { type: "verse", number: "15", sanskrit: "स्वेदो निश्वासवैगन्ध्यमतितृष्णा च पित्तजे", text: "svedo niśvāsavaigandhyamatitṛṣṇā ca pittaje" },
      { type: "verse", number: "16", sanskrit: "विशेषादरुचिर्जाड्यं स्रोतोरोधो ऽल्पवेगता प्रसेको मुखमाधुर्यं हृल्लेपश्वासपीनसाः", text: "viśeṣādarucirjāḍyaṃ srotorodho 'lpavegatā praseko mukhamādhuryaṃ hṛllepaśvāsapīnasāḥ" },
      { type: "verse", number: "17", sanskrit: "हृल्लासश्छर्दनं कासः स्तम्भः श्वैत्यं त्वगादिषु", text: "hṛllāsaśchardanaṃ kāsaḥ stambhaḥ śvaityaṃ tvagādiṣu" },
      { type: "verse", number: "18", sanskrit: "अङ्गेषु शीतपिटकास्तन्द्रोदर्दः कफोद्भवे", text: "aṅgeṣu śītapiṭakāstandrodardaḥ kaphodbhave" },
      { type: "verse", number: "19", sanskrit: "काले यथास्वं सर्वेषां प्रवृत्तिर्वृद्धिरेव वा निदानोक्तानुपशयो विपरीतोपशायिता", text: "kāle yathāsvaṃ sarveṣāṃ pravṛttirvṛddhireva vā nidānoktānupaśayo viparītopaśāyitā" },
      { type: "verse", number: "20", sanskrit: "यथास्वं लिङ्गसंसर्गे ज्वरः संसर्गजो ऽपि च", text: "yathāsvaṃ liṅgasaṃsarge jvaraḥ saṃsargajo 'pi ca" },
      { type: "verse", number: "21", sanskrit: "शिरो ऽर्तिमूर्छावमिदाहमोहकण्ठास्यशोषारतिपर्वभेदाः उन्निद्रतातृड्भ्रमरोमहर्षा जृम्भातिवाक्त्वं च चलात् सपित्तात्", text: "śiro 'rtimūrchāvamidāhamohakaṇṭhāsyaśoṣāratiparvabhedāḥ unnidratātṛḍbhramaromaharṣā jṛmbhātivāktvaṃ ca calāt sapittāt" },
      { type: "verse", number: "22", sanskrit: "तापहान्यरुचिपर्वशिरोरुक्पीनसश्वसनकासविबन्धाः शीतजाड्यतिमिरभ्रमतन्द्राः श्लेष्मवातजनितज्वरलिङ्गम्", text: "tāpahānyaruciparvaśirorukpīnasaśvasanakāsavibandhāḥ śītajāḍyatimirabhramatandrāḥ śleṣmavātajanitajvaraliṅgam" },
      { type: "verse", number: "23", sanskrit: "शीतस्तम्भस्वेददाहाव्यवस्था तृष्णा कासः श्लेष्मपित्तप्रवृत्तिः मोहस्तन्द्रा लिप्ततिक्तास्यता च ज्ञेयं रूपं श्लेष्मपित्तज्वरस्य", text: "śītastambhasvedadāhāvyavasthā tṛṣṇā kāsaḥ śleṣmapittapravṛttiḥ mohastandrā liptatiktāsyatā ca jñeyaṃ rūpaṃ śleṣmapittajvarasya" },
      { type: "verse", number: "24", sanskrit: "सर्वजो लक्षणैः सर्वैर्वाहो ऽत्र च मुहुर्मुहुः तद्वच्छीतं महानिद्रा दिवा जागरणं निशि", text: "sarvajo lakṣaṇaiḥ sarvairvāho 'tra ca muhurmuhuḥ tadvacchītaṃ mahānidrā divā jāgaraṇaṃ niśi" },
      { type: "verse", number: "25", sanskrit: "सदा वा नैव वा निद्रा मुहुः स्वेदो ऽति नैव वा गीतनर्तनहास्यादिविकृतेहाप्रवर्तनम्", text: "sadā vā naiva vā nidrā muhuḥ svedo 'ti naiva vā gītanartanahāsyādivikṛtehāpravartanam" },
      { type: "verse", number: "26", sanskrit: "सस्रुती कलुषे रक्ते भुग्ने लुलितपक्ष्मणी अक्षिणी पिण्डिकापार्श्वमूर्धपर्वास्थिरुग्भ्रमः", text: "sasrutī kaluṣe rakte bhugne lulitapakṣmaṇī akṣiṇī piṇḍikāpārśvamūrdhaparvāsthirugbhramaḥ" },
      { type: "verse", number: "27", sanskrit: "सत्वनौ सरुजौ कर्णौ कण्ठः शूकैरिवावृतः परिदग्धा खरा जिह्वा गुरुस्रस्ताङ्गसन्धिता", text: "satvanau sarujau karṇau kaṇṭhaḥ śūkairivāvṛtaḥ paridagdhā kharā jihvā gurusrastāṅgasandhitā" },
      { type: "verse", number: "28", sanskrit: "रक्तपित्तकफष्ठीवो लोलनं शिरसो ऽतितृट् कोठानां श्यावरक्तानां मण्डलानां च दर्शनम्", text: "raktapittakaphaṣṭhīvo lolanaṃ śiraso 'titṛṭ koṭhānāṃ śyāvaraktānāṃ maṇḍalānāṃ ca darśanam" },
      { type: "verse", number: "29", sanskrit: "हृद्व्यथा मलसंसर्ङ्गः प्रवृत्तिर्वाल्पशो ऽति वा स्निग्धास्यता बलभ्रंशः स्वरसादः प्रलापिता", text: "hṛdvyathā malasaṃsarṅgaḥ pravṛttirvālpaśo 'ti vā snigdhāsyatā balabhraṃśaḥ svarasādaḥ pralāpitā" },
      { type: "verse", number: "30", sanskrit: "दोषपाकश्चिरात्तन्द्रा प्रततं कण्ठकूजनम् सन्निपातमभिन्यासं तं ब्रूयाच्च हृतौजसम्", text: "doṣapākaścirāttandrā pratataṃ kaṇṭhakūjanam sannipātamabhinyāsaṃ taṃ brūyācca hṛtaujasam" },
      { type: "verse", number: "31", sanskrit: "वायुना कफरुद्धेन पित्तमन्तः प्रपीडितम् व्यवायित्वाच्च सौक्ष्म्याच्च बहिर्मर्गं प्रवर्तते", text: "vāyunā kapharuddhena pittamantaḥ prapīḍitam vyavāyitvācca saukṣmyācca bahirmargaṃ pravartate" },
      { type: "verse", number: "32", sanskrit: "तेन हारिद्रनेत्रत्वं सन्निपातोद्भवे ज्वरे दोषे विबद्धे नष्टे ऽग्नौ सर्वसम्पूर्णलक्षणः", text: "tena hāridranetratvaṃ sannipātodbhave jvare doṣe vibaddhe naṣṭe 'gnau sarvasampūrṇalakṣaṇaḥ" },
      { type: "verse", number: "33", sanskrit: "असाध्यः सो ऽन्यथा कृच्छ्रो भवेद्वैकल्यदो ऽपि वा", text: "asādhyaḥ so 'nyathā kṛcchro bhavedvaikalyado 'pi vā" },
      { type: "verse", number: "34", sanskrit: "अन्यच्च सन्निपातोत्थो यत्र पित्तं पृथक्स्थितम् त्वचि कोष्ठे ऽथवा दाहं विदधाति पुरो ऽनु वा", text: "anyacca sannipātottho yatra pittaṃ pṛthaksthitam tvaci koṣṭhe 'thavā dāhaṃ vidadhāti puro 'nu vā" },
      { type: "verse", number: "35", sanskrit: "तद्वद्वातकफौ शीतं दाहादिर्दुस्तरस्तयोः", text: "tadvadvātakaphau śītaṃ dāhādirdustarastayoḥ" },
      { type: "verse", number: "36", sanskrit: "शीतादौ तत्र पित्तेन कफे स्यन्दितशोषिते शीते शान्ते ऽम्लको मूर्च्छा मदस्तृष्णा च जायते", text: "śītādau tatra pittena kaphe syanditaśoṣite śīte śānte 'mlako mūrcchā madastṛṣṇā ca jāyate" },
      { type: "verse", number: "37", sanskrit: "दाहादौ पुनरन्ते स्युस्तन्द्राष्ठीववमिक्लमाः", text: "dāhādau punarante syustandrāṣṭhīvavamiklamāḥ" },
      { type: "verse", number: "38", sanskrit: "आगन्तुरभिघाताभिषङ्गशापाभिचारतः चतुर्धात्र क्षतच्छेददाहाद्यैरभिघातजः", text: "āganturabhighātābhiṣaṅgaśāpābhicārataḥ caturdhātra kṣatacchedadāhādyairabhighātajaḥ" },
      { type: "verse", number: "39", sanskrit: "श्रमाच्च तस्मिन् पवनः प्रायो रक्तं प्रदूषयन् सव्यथाशोफवैवर्ण्यं सरुजं कुरुते ज्वरम्", text: "śramācca tasmin pavanaḥ prāyo raktaṃ pradūṣayan savyathāśophavaivarṇyaṃ sarujaṃ kurute jvaram" },
      { type: "verse", number: "40", sanskrit: "ग्रहावेशौषधिविषक्रोधभीशोककामजः अभिषङ्गाद् ग्रहेणास्मिन्नकस्माद्धासरोदने", text: "grahāveśauṣadhiviṣakrodhabhīśokakāmajaḥ abhiṣaṅgād graheṇāsminnakasmāddhāsarodane" },
      { type: "verse", number: "41", sanskrit: "औषधीगन्धजे मूर्छा शिरोरुक् श्वयथुः क्षवः विषान्मूर्छातिसारास्यश्यावतादाहहृद्गदाः", text: "auṣadhīgandhaje mūrchā śiroruk śvayathuḥ kṣavaḥ viṣānmūrchātisārāsyaśyāvatādāhahṛdgadāḥ" },
      { type: "verse", number: "42", sanskrit: "क्रोधात् कम्पः शिरोरुक् च प्रलापो भयशोकजे कामान्मोहो ऽरुचिर्दाहोद्रीनिद्राधधृतिक्षयः", text: "krodhāt kampaḥ śiroruk ca pralāpo bhayaśokaje kāmānmoho 'rucirdāhodrīnidrādhadhṛtikṣayaḥ" },
      { type: "verse", number: "43", sanskrit: "ग्रहादौ सन्निपातस्य भयादौ मरुतस्त्रये कोपः क्रोधे तु पित्तस्य यौ तु शापाभिचारजौ सन्निपातज्वरौ घोरौ तावसह्यतमौ मतौ", text: "grahādau sannipātasya bhayādau marutastraye kopaḥ krodhe tu pittasya yau tu śāpābhicārajau sannipātajvarau ghorau tāvasahyatamau matau" },
      { type: "verse", number: "44", sanskrit: "तत्राभिचारिकैर्मन्त्रैर्हूयमानस्य तप्यते पूर्वं चेतस्ततो देहस्ततो विस्फोटतृड्भ्रमैः", text: "tatrābhicārikairmantrairhūyamānasya tapyate pūrvaṃ cetastato dehastato visphoṭatṛḍbhramaiḥ" },
      { type: "verse", number: "45", sanskrit: "सदाहमूर्छर्ग्रस्तस्य प्रत्यहं वर्धते ज्वरः इति ज्वरो ऽष्टधा दृष्टः समासाद्द्विविधस्तु सः", text: "sadāhamūrchargrastasya pratyahaṃ vardhate jvaraḥ iti jvaro 'ṣṭadhā dṛṣṭaḥ samāsāddvividhastu saḥ" },
      { type: "verse", number: "46", sanskrit: "शारीरो मानसःसौम्यस्तीक्ष्णो ऽन्तर्बहिराश्रयः प्राकृतो वैकृतःसाध्यो ऽसाध्यःसामो निरामकः", text: "śārīro mānasaḥsaumyastīkṣṇo 'ntarbahirāśrayaḥ prākṛto vaikṛtaḥsādhyo 'sādhyaḥsāmo nirāmakaḥ" },
      { type: "verse", number: "47", sanskrit: "पूर्वं शरीरे शारीरे तापो मनसि मानसे पवने योगवाहित्वाच्छीतं श्लेष्मयुते भवेत्", text: "pūrvaṃ śarīre śārīre tāpo manasi mānase pavane yogavāhitvācchītaṃ śleṣmayute bhavet" },
      { type: "verse", number: "48", sanskrit: "दाहः पित्तयुते मिश्रं मिश्रे अन्तः संश्रये पुनः ज्वरेधिकं विकाराः स्युरन्तःक्षोभो मलग्रहः", text: "dāhaḥ pittayute miśraṃ miśre antaḥ saṃśraye punaḥ jvaredhikaṃ vikārāḥ syurantaḥkṣobho malagrahaḥ" },
      { type: "verse", number: "49", sanskrit: "बहिरेव बहिर्वेगे तापो ऽपि च सुसाध्यता", text: "bahireva bahirvege tāpo 'pi ca susādhyatā" },
      { type: "verse", number: "50", sanskrit: "वर्षाशरद्वसन्तेषु वाताद्यैः प्राकृतः क्रमात् वैकृतो ऽन्यःसदुः साध्यः प्रायश्च प्राकृतो ऽनिलात्", text: "varṣāśaradvasanteṣu vātādyaiḥ prākṛtaḥ kramāt vaikṛto 'nyaḥsaduḥ sādhyaḥ prāyaśca prākṛto 'nilāt" },
      { type: "verse", number: "51", sanskrit: "एकमार्गक्रियारम्भव्यतिवृत्तेर्महात्ययात्", text: "ekamārgakriyārambhavyativṛttermahātyayāt" },
      { type: "verse", number: "52", sanskrit: "वर्षासु मारुतो दुष्टः पित्तश्लेष्मान्वितो ज्वरम् कुर्यात् पित्तं च शरदि तस्य चानुबलः कफः", text: "varṣāsu māruto duṣṭaḥ pittaśleṣmānvito jvaram kuryāt pittaṃ ca śaradi tasya cānubalaḥ kaphaḥ" },
      { type: "verse", number: "53", sanskrit: "तत्प्रकृत्या विसर्गाच्च तत्र नानशनाद्भयम् कफो वसन्ते तमपि बातपित्तं भवेदनु", text: "tatprakṛtyā visargācca tatra nānaśanādbhayam kapho vasante tamapi bātapittaṃ bhavedanu" },
      { type: "verse", number: "54", sanskrit: "बलवत्स्वल्पदोषेषु ज्वरः साध्यो ऽनुपद्रवः सर्वथा विकृतिज्ञाने प्रागसाध्य उदाहृतः", text: "balavatsvalpadoṣeṣu jvaraḥ sādhyo 'nupadravaḥ sarvathā vikṛtijñāne prāgasādhya udāhṛtaḥ" },
      { type: "verse", number: "55", sanskrit: "ज्वरोपद्रवतीक्ष्णत्वमग्लानिर्बहुमूत्रता न प्रवृत्तिर्न विड्जीर्णा न क्षुत्सामज्वराकृतिः", text: "jvaropadravatīkṣṇatvamaglānirbahumūtratā na pravṛttirna viḍjīrṇā na kṣutsāmajvarākṛtiḥ" },
      { type: "verse", number: "56", sanskrit: "ज्वरेगो ऽधिकं तृष्णा प्रलापः श्वसनं भ्रमः मलप्रवृत्तिरुत्क्लेशः पच्यमानस्य लक्षणम्", text: "jvarego 'dhikaṃ tṛṣṇā pralāpaḥ śvasanaṃ bhramaḥ malapravṛttirutkleśaḥ pacyamānasya lakṣaṇam" },
      { type: "verse", number: "57", sanskrit: "जीर्णतामविपर्यासात् सप्तरात्रं च लङ्घनात्", text: "jīrṇatāmaviparyāsāt saptarātraṃ ca laṅghanāt" },
      { type: "verse", number: "58", sanskrit: "ज्वरः पञ्चविधः प्रोक्तो मलकालबलाबलात् प्रायः स सन्निपातेन भूयसा त्वपदिश्यते", text: "jvaraḥ pañcavidhaḥ prokto malakālabalābalāt prāyaḥ sa sannipātena bhūyasā tvapadiśyate" },
      { type: "verse", number: "59", sanskrit: "सन्ततः सततो ऽन्येद्युस्तृतीयकचतुर्थकौ", text: "santataḥ satato 'nyedyustṛtīyakacaturthakau" },
      { type: "verse", number: "60", sanskrit: "धातुमूत्रशकृद्वाहिस्रोतसां व्यापिनो मलाः तापयन्तस्तनुं सर्वां तुल्यदूष्यादिवर्धिताः", text: "dhātumūtraśakṛdvāhisrotasāṃ vyāpino malāḥ tāpayantastanuṃ sarvāṃ tulyadūṣyādivardhitāḥ" },
      { type: "verse", number: "61", sanskrit: "बलिनो गुरवः स्तब्धा विशेषेण रसाश्रिताः सन्ततं निष्प्रतिद्वन्दा ज्वरं कुर्युः सुदुस्सहम्", text: "balino guravaḥ stabdhā viśeṣeṇa rasāśritāḥ santataṃ niṣpratidvandā jvaraṃ kuryuḥ sudussaham" },
      { type: "verse", number: "62", sanskrit: "मलाञ्ज्वरोष्मा धातून् वा स शीघ्रं क्षपयस्ततः सर्वाकारं रसादीनां शुध्याशुध्यापि वा क्रमात्", text: "malāñjvaroṣmā dhātūn vā sa śīghraṃ kṣapayastataḥ sarvākāraṃ rasādīnāṃ śudhyāśudhyāpi vā kramāt" },
      { type: "verse", number: "63", sanskrit: "वातपित्तकफेः सप्त दश द्वादशवासरान् प्रायो ऽनुयाति मर्यादां मोक्षाय च वधाय च", text: "vātapittakapheḥ sapta daśa dvādaśavāsarān prāyo 'nuyāti maryādāṃ mokṣāya ca vadhāya ca" },
      { type: "verse", number: "64", sanskrit: "इत्यग्निवेशस्य मतं हारीतस्य पुनः स्मृतिः", text: "ityagniveśasya mataṃ hārītasya punaḥ smṛtiḥ" },
      { type: "verse", number: "65", sanskrit: "द्विगुणा सप्तमी यावन्नवम्येकादशी तथा एषा त्रिदोषमर्यादा मोक्षाय च वधाय च", text: "dviguṇā saptamī yāvannavamyekādaśī tathā eṣā tridoṣamaryādā mokṣāya ca vadhāya ca" },
      { type: "verse", number: "66", sanskrit: "शुध्यशुद्धौ ज्वरः कालं दीर्घमप्यनुवर्तते", text: "śudhyaśuddhau jvaraḥ kālaṃ dīrghamapyanuvartate" },
      { type: "verse", number: "67", sanskrit: "कृशानां व्याधिमुक्तानां मिथ्याहारादिसेविनाम् अल्पो ऽपि दोषो दूष्यादेर्लब्ध्वान्यतमतो बलम्", text: "kṛśānāṃ vyādhimuktānāṃ mithyāhārādisevinām alpo 'pi doṣo dūṣyāderlabdhvānyatamato balam" },
      { type: "verse", number: "68", sanskrit: "सप्रत्यनीको विषमं कुर्याद्वृद्धिक्षयान्वितः", text: "sapratyanīko viṣamaṃ kuryādvṛddhikṣayānvitaḥ" },
      { type: "verse", number: "69", sanskrit: "सूक्ष्मसूक्ष्मतरास्येषु दूरदूरतरेषु च दोषो रक्तादिमार्गेषु शनैरल्पश्चिरेण यत्", text: "sūkṣmasūkṣmatarāsyeṣu dūradūratareṣu ca doṣo raktādimārgeṣu śanairalpaścireṇa yat" },
      { type: "verse", number: "70", sanskrit: "याति देहं च नाशेषं भूयिष्ठं भेषजे ऽपि च क्रमो ऽयं तेन विच्छिन्नसन्तापो लक्ष्यते ज्वरः", text: "yāti dehaṃ ca nāśeṣaṃ bhūyiṣṭhaṃ bheṣaje 'pi ca kramo 'yaṃ tena vicchinnasantāpo lakṣyate jvaraḥ" },
      { type: "verse", number: "71", sanskrit: "विषमो विषमारम्भक्रियाकालो ऽनुषङ्गवान्", text: "viṣamo viṣamārambhakriyākālo 'nuṣaṅgavān" },
      { type: "verse", number: "72", sanskrit: "यथोत्तरं मन्दगतिर्मन्दशक्तिर्यथा यथा कालेनाप्नोति सदृशान् स रसादींस्तथा तथा", text: "yathottaraṃ mandagatirmandaśaktiryathā yathā kālenāpnoti sadṛśān sa rasādīṃstathā tathā" },
      { type: "verse", number: "73", sanskrit: "दोषो ज्वरयति क्रुद्धश्चिराच्चिरतरेण च", text: "doṣo jvarayati kruddhaścirācciratareṇa ca" },
      { type: "verse", number: "74", sanskrit: "भूमौ स्थितं जलैः सिक्तं कालमेव प्रतीक्षते अङ्कुराय यथा बीजं दोषबीजं रुजे तथा", text: "bhūmau sthitaṃ jalaiḥ siktaṃ kālameva pratīkṣate aṅkurāya yathā bījaṃ doṣabījaṃ ruje tathā" },
      { type: "verse", number: "75", sanskrit: "वेगं कृत्वा विषं यद्वदाशये लीयते ऽबलम् कुप्यत्याप्तबलं भूयः काले दोषविषं तथा", text: "vegaṃ kṛtvā viṣaṃ yadvadāśaye līyate 'balam kupyatyāptabalaṃ bhūyaḥ kāle doṣaviṣaṃ tathā" },
      { type: "verse", number: "76", sanskrit: "एवं ज्वराः प्रवर्तन्ते विषमाः सततादयः", text: "evaṃ jvarāḥ pravartante viṣamāḥ satatādayaḥ" },
      { type: "verse", number: "77", sanskrit: "दोषः प्रवर्तते तेषां स्वे काले ज्वरयन् बली निवर्तते पुनश्चैष प्रत्यनीकबलाबलः", text: "doṣaḥ pravartate teṣāṃ sve kāle jvarayan balī nivartate punaścaiṣa pratyanīkabalābalaḥ" },
      { type: "verse", number: "78", sanskrit: "क्षीणे दोषे ज्वरः सूक्ष्मो रसादिष्वेव लीयते लीनत्वात् कार्श्यवैवर्ण्यजाड्यादीनादधाति सः", text: "kṣīṇe doṣe jvaraḥ sūkṣmo rasādiṣveva līyate līnatvāt kārśyavaivarṇyajāḍyādīnādadhāti saḥ" },
      { type: "verse", number: "79", sanskrit: "अतिलीनो ऽतिमन्दत्वात् भवत्यह्नि न पञ्चमे", text: "atilīno 'timandatvāt bhavatyahni na pañcame" },
      { type: "verse", number: "80", sanskrit: "दोषो रक्ताश्रयः प्रायः करोति सततं ज्वरम्", text: "doṣo raktāśrayaḥ prāyaḥ karoti satataṃ jvaram" },
      { type: "verse", number: "81", sanskrit: "अहोरात्रस्य स द्विः स्यात्सकृदन्येद्युराश्रितः", text: "ahorātrasya sa dviḥ syātsakṛdanyedyurāśritaḥ" },
      { type: "verse", number: "82", sanskrit: "तस्मिन्मांसवहा नाडीर्मेदोनाडीस्तृतीयके ग्राही पित्तानिलान्मूर्ध्नस्त्रिकस्य कफपित्ततः", text: "tasminmāṃsavahā nāḍīrmedonāḍīstṛtīyake grāhī pittānilānmūrdhnastrikasya kaphapittataḥ" },
      { type: "verse", number: "83", sanskrit: "स पृष्ठस्यानिलकफात् स चैकाहान्तरः स्मृतः", text: "sa pṛṣṭhasyānilakaphāt sa caikāhāntaraḥ smṛtaḥ" },
      { type: "verse", number: "84", sanskrit: "चतुर्थको मले मेदोमज्जास्थ्यन्यतमस्थिते मज्जस्थ एवेत्यपरे प्रभावं स तु दर्शयेत्", text: "caturthako male medomajjāsthyanyatamasthite majjastha evetyapare prabhāvaṃ sa tu darśayet" },
      { type: "verse", number: "85", sanskrit: "द्विधा कफेन जङ्घाभ्यां प्रथमं शिरसो ऽनिलात् गम्भीरधातुचारित्वात् सनिपातेन सम्भवात्", text: "dvidhā kaphena jaṅghābhyāṃ prathamaṃ śiraso 'nilāt gambhīradhātucāritvāt sanipātena sambhavāt" },
      { type: "verse", number: "86", sanskrit: "तुल्योच्छ्रायाच्च दोषाणां दुश्चिकित्स्यश्चतुर्थकः", text: "tulyocchrāyācca doṣāṇāṃ duścikitsyaścaturthakaḥ" },
      { type: "verse", number: "87", sanskrit: "अस्थिमज्जोमयगते चतुर्थकविपर्ययः त्रिधा द्व्यहं ज्वरयति दिनमेकं तु मुञ्चति", text: "asthimajjomayagate caturthakaviparyayaḥ tridhā dvyahaṃ jvarayati dinamekaṃ tu muñcati" },
      { type: "verse", number: "88", sanskrit: "बलाबलेन दोषाणामन्नचेष्टादिजन्मना ज्वरः स्यान्मनसस्तद्वत्कर्मणश्च तदा तदा", text: "balābalena doṣāṇāmannaceṣṭādijanmanā jvaraḥ syānmanasastadvatkarmaṇaśca tadā tadā" },
      { type: "verse", number: "89", sanskrit: "उत्क्लेशो गौरवं दैन्यं भङ्गो ऽङ्गानां विजृम्भणम् अरोचको वमिः सादः सर्वस्मिन् रसगे ज्वरे", text: "utkleśo gauravaṃ dainyaṃ bhaṅgo 'ṅgānāṃ vijṛmbhaṇam arocako vamiḥ sādaḥ sarvasmin rasage jvare" },
      { type: "verse", number: "90", sanskrit: "रक्तनिष्ठीवनं तृष्णा रक्तोष्णपिटकोद्गमः दाहरागभ्रममदप्रलापा रक्तसंश्रिते", text: "raktaniṣṭhīvanaṃ tṛṣṇā raktoṣṇapiṭakodgamaḥ dāharāgabhramamadapralāpā raktasaṃśrite" },
      { type: "verse", number: "91", sanskrit: "तृड् ग्लानिः सृष्टवर्चस्त्वमन्तर्दाहो भ्रमस्तमः दौर्गन्ध्यं गात्रविक्षेपो मांसस्थे मेदसि स्थिते", text: "tṛḍ glāniḥ sṛṣṭavarcastvamantardāho bhramastamaḥ daurgandhyaṃ gātravikṣepo māṃsasthe medasi sthite" },
      { type: "verse", number: "92", sanskrit: "स्वेदो ऽतितृष्णा वमनं स्वगन्धस्यासहिष्णुता प्रलापो ग्लानिररुचिरस्थिस्थे त्वस्थिभेदनम्", text: "svedo 'titṛṣṇā vamanaṃ svagandhasyāsahiṣṇutā pralāpo glānirarucirasthisthe tvasthibhedanam" },
      { type: "verse", number: "93", sanskrit: "दोषप्रवृत्तिरूर्ध्वाधः श्वासाङ्गक्षेपकूजनम् अन्तर्दाहो बहिःशैत्यं श्वासो हिध्मा च मज्जगे", text: "doṣapravṛttirūrdhvādhaḥ śvāsāṅgakṣepakūjanam antardāho bahiḥśaityaṃ śvāso hidhmā ca majjage" },
      { type: "verse", number: "94", sanskrit: "तमसो दर्शनं मर्मच्छेदनं स्तब्धमेढ्रता शुक्रप्रवृत्तिर्मृत्युश्च जायते शुक्रसंश्रये", text: "tamaso darśanaṃ marmacchedanaṃ stabdhameḍhratā śukrapravṛttirmṛtyuśca jāyate śukrasaṃśraye" },
      { type: "verse", number: "95", sanskrit: "उत्तरोत्तरदुस्साध्याः पञ्चात्रान्त्यौ तु वर्जयेत् प्रलिम्पन्निव गात्राणि श्लेष्मणा गौरवेण च", text: "uttarottaradussādhyāḥ pañcātrāntyau tu varjayet pralimpanniva gātrāṇi śleṣmaṇā gauraveṇa ca" },
      { type: "verse", number: "96", sanskrit: "मन्दज्वरः प्रलेपस्तु सशीतः स्यात्प्रलेपकः नित्यं मन्दज्वरो रूक्षः शीतः कृच्छ्रेण सिध्यति", text: "mandajvaraḥ pralepastu saśītaḥ syātpralepakaḥ nityaṃ mandajvaro rūkṣaḥ śītaḥ kṛcchreṇa sidhyati" },
      { type: "verse", number: "97", sanskrit: "स्तब्धाङ्गः श्लेष्मभूयिष्ठो भवेद्वातबलासकः हरिद्राभेकवर्णाभस्तद्वर्णं यः प्रमेहति", text: "stabdhāṅgaḥ śleṣmabhūyiṣṭho bhavedvātabalāsakaḥ haridrābhekavarṇābhastadvarṇaṃ yaḥ pramehati" },
      { type: "verse", number: "98", sanskrit: "स वै हारिद्रको नाम ज्वरभेदो ऽन्तकः स्मृतः कफवातौ समौ यस्य हीनपित्तस्य देहिनः", text: "sa vai hāridrako nāma jvarabhedo 'ntakaḥ smṛtaḥ kaphavātau samau yasya hīnapittasya dehinaḥ" },
      { type: "verse", number: "99", sanskrit: "तीक्ष्णो वा यदि वा मन्दो जायते रात्रिकोज्वरः दिवाकरापीतबले व्यायामाच्च विशोषिते", text: "tīkṣṇo vā yadi vā mando jāyate rātrikojvaraḥ divākarāpītabale vyāyāmācca viśoṣite" },
      { type: "verse", number: "100", sanskrit: "शरीरे नियतं वाताज्ज्वरः स्यात् पूर्वरात्रिकः आमाशये यदा दुष्टे श्लेष्मपित्ते व्यवस्थिते", text: "śarīre niyataṃ vātājjvaraḥ syāt pūrvarātrikaḥ āmāśaye yadā duṣṭe śleṣmapitte vyavasthite" },
      { type: "verse", number: "101", sanskrit: "तदार्धं शीतलं देहे स्वर्धज्चोष्णं प्रजायते काये पित्तं यदा दुष्टं श्लेष्मा चान्ते व्यवस्थितः", text: "tadārdhaṃ śītalaṃ dehe svardhajcoṣṇaṃ prajāyate kāye pittaṃ yadā duṣṭaṃ śleṣmā cānte vyavasthitaḥ" },
      { type: "verse", number: "102", sanskrit: "उष्णत्वं तेन देहस्य शीतत्वं करपादयोः", text: "uṣṇatvaṃ tena dehasya śītatvaṃ karapādayoḥ" },
      { type: "verse", number: "103", sanskrit: "धातून् प्रक्षोभयन् दोषो मोक्षकाले विलीयते ततो नरः श्वसन् स्विद्यन् कूजन् वमति चेष्टते", text: "dhātūn prakṣobhayan doṣo mokṣakāle vilīyate tato naraḥ śvasan svidyan kūjan vamati ceṣṭate" },
      { type: "verse", number: "104", sanskrit: "वेपते प्रलपत्युष्णैः शीतैश्चाङ्गैर्हतप्रभः विसंज्ञो ज्वरवेगार्तः सक्रोध इव वीक्षते", text: "vepate pralapatyuṣṇaiḥ śītaiścāṅgairhataprabhaḥ visaṃjño jvaravegārtaḥ sakrodha iva vīkṣate" },
      { type: "verse", number: "105", sanskrit: "सदोषशब्दञ्च शकृद् द्रवं सृजति वेगवत्", text: "sadoṣaśabdañca śakṛd dravaṃ sṛjati vegavat" },
      { type: "verse", number: "106", sanskrit: "देहो लघुर्व्यपगतक्लमममोहतापः पाको मुखे करणसौष्ठवमव्यथत्वम् स्वेदः क्षवः प्रकृतियोगि मनो ऽन्नलिप्सा कण्डूश्च मूर्ध्नि विगतज्वरलक्षणानि", text: "deho laghurvyapagataklamamamohatāpaḥ pāko mukhe karaṇasauṣṭhavamavyathatvam svedaḥ kṣavaḥ prakṛtiyogi mano 'nnalipsā kaṇḍūśca mūrdhni vigatajvaralakṣaṇāni" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 3,
    lang: "sa",
    content: [
      { type: "heading", heading: "Шоша нидана — туберкулёз" },
      { type: "text", text: "Глава 3 Нидана стханы — диагностический раздел о туберкулёз. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातो रक्तपित्तकासनिदानं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto raktapittakāsanidānaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "भृशोष्णतीक्ष्णकट्वम्ललवणातिविदाहिभिः कोद्रवोद्दालकैश्चान्नैस्तद्युक्तैरतिसेवितैः", text: "bhṛśoṣṇatīkṣṇakaṭvamlalavaṇātividāhibhiḥ kodravoddālakaiścānnaistadyuktairatisevitaiḥ" },
      { type: "verse", number: "3", sanskrit: "कुपितं पित्तलैः पित्तं द्रवं रक्तं च मूर्छिते ते मिथस्तुल्यरूपत्वमागम्य व्याप्नुतस्तनुम्", text: "kupitaṃ pittalaiḥ pittaṃ dravaṃ raktaṃ ca mūrchite te mithastulyarūpatvamāgamya vyāpnutastanum" },
      { type: "verse", number: "4", sanskrit: "पित्तं रक्तस्य विकृतेः संसर्गाद् दूषणादपि गन्धवर्णानुवृत्तेश्च रक्तेन व्यपदिश्यते", text: "pittaṃ raktasya vikṛteḥ saṃsargād dūṣaṇādapi gandhavarṇānuvṛtteśca raktena vyapadiśyate" },
      { type: "verse", number: "5", sanskrit: "प्रभवत्यसृजः स्थानात् प्लीहतो यकृतश्च तत्", text: "prabhavatyasṛjaḥ sthānāt plīhato yakṛtaśca tat" },
      { type: "verse", number: "6", sanskrit: "शिरोगुरुत्वमरुचिः शीतेच्छा धूमको ऽम्लकः छर्दिश्छर्दितबैभत्स्यं कासश्वासौ भ्रमः क्लमः", text: "śirogurutvamaruciḥ śītecchā dhūmako 'mlakaḥ chardiścharditabaibhatsyaṃ kāsaśvāsau bhramaḥ klamaḥ" },
      { type: "verse", number: "7", sanskrit: "लोहलोहितमत्स्यामगन्धास्यत्वं स्वरक्षयः रक्तहारिद्रहरितवर्णता नयनादिषु", text: "lohalohitamatsyāmagandhāsyatvaṃ svarakṣayaḥ raktahāridraharitavarṇatā nayanādiṣu" },
      { type: "verse", number: "8", sanskrit: "नीललोहितपीतानां वर्णानामविवेचनम् स्वप्ने तद्वर्णदर्शित्वं भवत्यस्मिन् भविष्यति", text: "nīlalohitapītānāṃ varṇānāmavivecanam svapne tadvarṇadarśitvaṃ bhavatyasmin bhaviṣyati" },
      { type: "verse", number: "9", sanskrit: "ऊर्ध्वं नासाक्षिकर्णास्यैर्मेढ्रयोनिगुदैरधः कुपितं रोमकूपैश्च समस्तैस्तत् प्रवर्तते", text: "ūrdhvaṃ nāsākṣikarṇāsyairmeḍhrayonigudairadhaḥ kupitaṃ romakūpaiśca samastaistat pravartate" },
      { type: "verse", number: "10", sanskrit: "ऊर्ध्वं साध्यं कफाद्यस्मात्तद्विरेचनसाधनम् बह्वौषधं च पित्तस्य विरेको हि वरौषधम्", text: "ūrdhvaṃ sādhyaṃ kaphādyasmāttadvirecanasādhanam bahvauṣadhaṃ ca pittasya vireko hi varauṣadham" },
      { type: "verse", number: "11", sanskrit: "अनुबन्धी कफो यश्च तत्र तस्यापि शुद्धिकृत् कषायाः स्वादवो ऽप्यस्य विशुद्धश्लेष्मणो हिताः", text: "anubandhī kapho yaśca tatra tasyāpi śuddhikṛt kaṣāyāḥ svādavo 'pyasya viśuddhaśleṣmaṇo hitāḥ" },
      { type: "verse", number: "12", sanskrit: "किमु तिक्ताः कषाया वा ये निसर्गात् कफापहाः", text: "kimu tiktāḥ kaṣāyā vā ye nisargāt kaphāpahāḥ" },
      { type: "verse", number: "13", sanskrit: "अधो याप्यं चलाद्यस्मात्तत् प्रच्छर्दनसाधनम् स्वल्पौषधं च पित्तस्य वमनं न वरौषधम्", text: "adho yāpyaṃ calādyasmāttat pracchardanasādhanam svalpauṣadhaṃ ca pittasya vamanaṃ na varauṣadham" },
      { type: "verse", number: "14", sanskrit: "अनुबन्धी चलो यश्च शान्तयेपि न तस्य तत् कषायाश्च हितास्तस्य मधुरा एव केवलम्", text: "anubandhī calo yaśca śāntayepi na tasya tat kaṣāyāśca hitāstasya madhurā eva kevalam" },
      { type: "verse", number: "15", sanskrit: "कफमारुतसंसृष्टमसाध्यमुभयायनम् अशक्यप्रातिलोम्यत्वादभावादौषधस्य च", text: "kaphamārutasaṃsṛṣṭamasādhyamubhayāyanam aśakyaprātilomyatvādabhāvādauṣadhasya ca" },
      { type: "verse", number: "16", sanskrit: "न हि संशोधनं किञ्चिदस्त्यस्य प्रतिलोमनम् शोधनं प्रतिलोमं च रक्तपित्ते भिषग्जितम्", text: "na hi saṃśodhanaṃ kiñcidastyasya pratilomanam śodhanaṃ pratilomaṃ ca raktapitte bhiṣagjitam" },
      { type: "verse", number: "17", sanskrit: "एवमेवोपशमनं सर्वशो नास्य विद्यते संसृष्टेषु हि दोषेषु सर्वजिच्छमनं हितम्", text: "evamevopaśamanaṃ sarvaśo nāsya vidyate saṃsṛṣṭeṣu hi doṣeṣu sarvajicchamanaṃ hitam" },
      { type: "verse", number: "18", sanskrit: "तत्र दोषानुगमनं सिरास्र एव लक्षयेत् उपद्रवांश्च विकृतिज्ञानतः तेषु चाधिकम्", text: "tatra doṣānugamanaṃ sirāsra eva lakṣayet upadravāṃśca vikṛtijñānataḥ teṣu cādhikam" },
      { type: "verse", number: "19", sanskrit: "आशुकारी यतः कासस्तमेवातः प्रवक्ष्यते", text: "āśukārī yataḥ kāsastamevātaḥ pravakṣyate" },
      { type: "verse", number: "20", sanskrit: "पञ्च कासाः वातपित्तश्लेष्मक्षतक्षयैः क्षयायोपेक्षिताः सर्वे बलिनश्चोत्तरोत्तरम्", text: "pañca kāsāḥ vātapittaśleṣmakṣatakṣayaiḥ kṣayāyopekṣitāḥ sarve balinaścottarottaram" },
      { type: "verse", number: "21", sanskrit: "तेषां भविष्यतां रूपं कण्ठे कण्डूररोचकः शूकपूर्णाभकण्ठत्वमस्वास्थ्यं हृदयस्य च", text: "teṣāṃ bhaviṣyatāṃ rūpaṃ kaṇṭhe kaṇḍūrarocakaḥ śūkapūrṇābhakaṇṭhatvamasvāsthyaṃ hṛdayasya ca" },
      { type: "verse", number: "22", sanskrit: "कषायविज्जलासात्म्यकट्वम्ललवणोषणैः रूक्षशीतगुरुस्निग्धोत्क्लेदिपर्युषिताशनैः", text: "kaṣāyavijjalāsātmyakaṭvamlalavaṇoṣaṇaiḥ rūkṣaśītagurusnigdhotklediparyuṣitāśanaiḥ" },
      { type: "verse", number: "23", sanskrit: "धारणोदीरणायासरात्र्यहःस्वप्नजागरैः अन्यैश्च तद्विधैर्धातुक्षयावरणकारिभिः", text: "dhāraṇodīraṇāyāsarātryahaḥsvapnajāgaraiḥ anyaiśca tadvidhairdhātukṣayāvaraṇakāribhiḥ" },
      { type: "verse", number: "24", sanskrit: "क्रुद्धः प्रतिहतो ऽपाने यदापानः प्रपद्यते ऊर्ध्वं रसस्य स स्थाने तिष्ठन्नुरसि पीड्यते", text: "kruddhaḥ pratihato 'pāne yadāpānaḥ prapadyate ūrdhvaṃ rasasya sa sthāne tiṣṭhannurasi pīḍyate" },
      { type: "verse", number: "25", sanskrit: "उदानेन संजस्तत्र कण्ठे चानुप्रपूर्य च वाहिनीर्गलमूर्धस्थास्ततो ऽङ्गान्युत्क्षिपन्निव", text: "udānena saṃjastatra kaṇṭhe cānuprapūrya ca vāhinīrgalamūrdhasthāstato 'ṅgānyutkṣipanniva" },
      { type: "verse", number: "26", sanskrit: "क्षिपन्निवाक्षिणी पृष्ठमुरःपार्श्वे च पीडयन् विवृतत्वान्मुखेनैति भिन्नकांस्योपमध्वनिः", text: "kṣipannivākṣiṇī pṛṣṭhamuraḥpārśve ca pīḍayan vivṛtatvānmukhenaiti bhinnakāṃsyopamadhvaniḥ" },
      { type: "verse", number: "27", sanskrit: "यस्मात्तस्मात्स वर्णैजोबलमांसक्षयावहः", text: "yasmāttasmātsa varṇaijobalamāṃsakṣayāvahaḥ" },
      { type: "verse", number: "28", sanskrit: "हेतुभेदात् प्रतीघातभेदो वायोः संरहसः यद्रुजाशब्दवैषम्यं कासानां जायते ततः", text: "hetubhedāt pratīghātabhedo vāyoḥ saṃrahasaḥ yadrujāśabdavaiṣamyaṃ kāsānāṃ jāyate tataḥ" },
      { type: "verse", number: "29", sanskrit: "कुपितो वातलैर्वायुः शुष्कोरःकण्ठवक्त्रताम् हृत्पार्श्वोरःशिरःशूलं मोहक्षोभस्वरक्षयान्", text: "kupito vātalairvāyuḥ śuṣkoraḥkaṇṭhavaktratām hṛtpārśvoraḥśiraḥśūlaṃ mohakṣobhasvarakṣayān" },
      { type: "verse", number: "30", sanskrit: "करोति शुष्ककासं च महावेगरुजास्वनम् सो ऽङ्गहर्षी कफं शुष्कं कृच्छ्रान्मुक्त्वाल्पतां व्रजेत्", text: "karoti śuṣkakāsaṃ ca mahāvegarujāsvanam so 'ṅgaharṣī kaphaṃ śuṣkaṃ kṛcchrānmuktvālpatāṃ vrajet" },
      { type: "verse", number: "31", sanskrit: "पित्तात् पीताक्षिकफता तिक्तास्यत्वं ज्वरो भ्रमः पित्तासृग्वमनं तृष्णा वैस्वर्यं धूमको मदः", text: "pittāt pītākṣikaphatā tiktāsyatvaṃ jvaro bhramaḥ pittāsṛgvamanaṃ tṛṣṇā vaisvaryaṃ dhūmako madaḥ" },
      { type: "verse", number: "32", sanskrit: "प्रततं कासवेगेन ज्योतिषामिव दर्शनम् कफादुरो ऽल्परुङ्मूर्धहृदयं स्तिमितं गुरु", text: "pratataṃ kāsavegena jyotiṣāmiva darśanam kaphāduro 'lparuṅmūrdhahṛdayaṃ stimitaṃ guru" },
      { type: "verse", number: "33", sanskrit: "कण्ठोपलेपः सदनं पीनसच्छर्द्यरोचकाः रोमहर्षो घनस्निग्धश्वेतश्लेष्मप्रवर्तनम्", text: "kaṇṭhopalepaḥ sadanaṃ pīnasacchardyarocakāḥ romaharṣo ghanasnigdhaśvetaśleṣmapravartanam" },
      { type: "verse", number: "34", sanskrit: "युद्धाद्यैः साहसैस्तैस्तैः सेवितैरयथाबलम् उरस्यन्तःक्षते वायुः पित्तेनानुगतो बली", text: "yuddhādyaiḥ sāhasaistaistaiḥ sevitairayathābalam urasyantaḥkṣate vāyuḥ pittenānugato balī" },
      { type: "verse", number: "35", sanskrit: "कुपितः कुरुते कासं कफं तेन सशोणितम् पीतं श्यावं च शुष्कं च ग्रथितं कुथितं बहु", text: "kupitaḥ kurute kāsaṃ kaphaṃ tena saśoṇitam pītaṃ śyāvaṃ ca śuṣkaṃ ca grathitaṃ kuthitaṃ bahu" },
      { type: "verse", number: "36", sanskrit: "ष्ठीवेत् कण्ठेन रुजता विभीन्नेनेव चोरसा सूचीभिरिव तीक्ष्णाभिस्तुद्यमानेन शूलिना", text: "ṣṭhīvet kaṇṭhena rujatā vibhīnneneva corasā sūcībhiriva tīkṣṇābhistudyamānena śūlinā" },
      { type: "verse", number: "37", sanskrit: "पर्वभेदज्वरश्वासतृष्णावैस्वर्यकम्पवान् पारावत इवाकूजन् पार्श्वशूली ततो ऽस्य च", text: "parvabhedajvaraśvāsatṛṣṇāvaisvaryakampavān pārāvata ivākūjan pārśvaśūlī tato 'sya ca" },
      { type: "verse", number: "38", sanskrit: "क्रमाद्वीर्यं रुचिः पक्तिर्बलं वर्णश्च हीयते पक्षीणस्य सासृङ्मूत्रत्वं स्याच्च पृष्ठकटीग्रहः", text: "kramādvīryaṃ ruciḥ paktirbalaṃ varṇaśca hīyate pakṣīṇasya sāsṛṅmūtratvaṃ syācca pṛṣṭhakaṭīgrahaḥ" },
      { type: "verse", number: "39", sanskrit: "वायुप्रधानाः कुपिता धातवो राजयक्ष्मिणः कुर्वन्ति यक्ष्मायतनैः कासं ष्ठीवेत् कफं ततः", text: "vāyupradhānāḥ kupitā dhātavo rājayakṣmiṇaḥ kurvanti yakṣmāyatanaiḥ kāsaṃ ṣṭhīvet kaphaṃ tataḥ" },
      { type: "verse", number: "40", sanskrit: "पूतिपूतोपमं पीतं विस्रं हरितलोहितम् लुप्येत इव पार्श्वे च हृदयं पततीव च", text: "pūtipūtopamaṃ pītaṃ visraṃ haritalohitam lupyeta iva pārśve ca hṛdayaṃ patatīva ca" },
      { type: "verse", number: "41", sanskrit: "अकस्मादुष्णशीतेच्छा बह्वाशित्वं बलक्षयः स्निग्धप्रसनवक्त्रत्वं श्रीमद्दशननेत्रता", text: "akasmāduṣṇaśītecchā bahvāśitvaṃ balakṣayaḥ snigdhaprasanavaktratvaṃ śrīmaddaśananetratā" },
      { type: "verse", number: "42", sanskrit: "ततो ऽस्यक्षयरूपाणि सर्वाण्याविर्भवन्ति च", text: "tato 'syakṣayarūpāṇi sarvāṇyāvirbhavanti ca" },
      { type: "verse", number: "43", sanskrit: "इत्येष क्षयजः कासः क्षीणानां देहनाशनः याप्यो वा बलिनां तद्वत् क्षतजो ऽभिनवौ तु तौ", text: "ityeṣa kṣayajaḥ kāsaḥ kṣīṇānāṃ dehanāśanaḥ yāpyo vā balināṃ tadvat kṣatajo 'bhinavau tu tau" },
      { type: "verse", number: "44", sanskrit: "सिध्येतामपि सानाथ्यात् साध्या दोषैः पृथक् त्रयः मिश्रा याप्या द्वयात्सर्वे जरसा स्थविरस्य च", text: "sidhyetāmapi sānāthyāt sādhyā doṣaiḥ pṛthak trayaḥ miśrā yāpyā dvayātsarve jarasā sthavirasya ca" },
      { type: "verse", number: "45", sanskrit: "कासाच्छ्वासक्षयछर्दिस्वरसादादयो गदाः भवन्त्युपेक्षया यस्मात्तस्मात्तं त्वरया जयेत्", text: "kāsācchvāsakṣayachardisvarasādādayo gadāḥ bhavantyupekṣayā yasmāttasmāttaṃ tvarayā jayet" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 4,
    lang: "sa",
    content: [
      { type: "heading", heading: "Гулма нидана — абдоминальные массы" },
      { type: "text", text: "Глава 4 Нидана стханы — диагностический раздел о абдоминальные массы. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातः श्वासहिध्मानिदानं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ śvāsahidhmānidānaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "कासवृध्या भवेच्छ्रूवासः पूर्वैर्वा दोषकोपनैः आमातिसारवमथुविषपाण्डुज्वरैरपि", text: "kāsavṛdhyā bhavecchrūvāsaḥ pūrvairvā doṣakopanaiḥ āmātisāravamathuviṣapāṇḍujvarairapi" },
      { type: "verse", number: "3", sanskrit: "रजोधूमानिलैर्मर्मघातादतिहिमाम्बुना क्षुद्रकस्तमकश्छिन्नो महानूर्ध्वश्च पञ्चमः", text: "rajodhūmānilairmarmaghātādatihimāmbunā kṣudrakastamakaśchinno mahānūrdhvaśca pañcamaḥ" },
      { type: "verse", number: "4", sanskrit: "कफोपरुद्धगमनः पवनो विष्वगास्थितः प्राणोदकान्नवाहीनि दुष्टः स्रोतांसि दूषयन्", text: "kaphoparuddhagamanaḥ pavano viṣvagāsthitaḥ prāṇodakānnavāhīni duṣṭaḥ srotāṃsi dūṣayan" },
      { type: "verse", number: "5", sanskrit: "उरस्थः कुरुते श्वासमामाशयसमुद्भवम्", text: "urasthaḥ kurute śvāsamāmāśayasamudbhavam" },
      { type: "verse", number: "6", sanskrit: "प्राग्रूपं तस्य हृत्पार्श्वशूलं प्राणविलोमता आनाहः शङ्खभेदश्च तत्रायासातिभोजनैः", text: "prāgrūpaṃ tasya hṛtpārśvaśūlaṃ prāṇavilomatā ānāhaḥ śaṅkhabhedaśca tatrāyāsātibhojanaiḥ" },
      { type: "verse", number: "7", sanskrit: "प्रेरितः प्रेरयेत् क्षुद्रं स्वयंसंशमनं मरुत्", text: "preritaḥ prerayet kṣudraṃ svayaṃsaṃśamanaṃ marut" },
      { type: "verse", number: "8", sanskrit: "प्रतिलोमं सिरा गच्छन्नुदीर्य पवनः कफम् परिगृह्य शिरोग्रीवमुरःपार्श्वे च पीडयन्", text: "pratilomaṃ sirā gacchannudīrya pavanaḥ kapham parigṛhya śirogrīvamuraḥpārśve ca pīḍayan" },
      { type: "verse", number: "9", sanskrit: "कासं घुर्घुरकं मोहमरुचिं पीनसं तृषम् करोति तीव्रवेगं च श्वासं प्राणोपतापिनम्", text: "kāsaṃ ghurghurakaṃ mohamaruciṃ pīnasaṃ tṛṣam karoti tīvravegaṃ ca śvāsaṃ prāṇopatāpinam" },
      { type: "verse", number: "10", sanskrit: "प्रताम्येत्तस्य वेगेन निष्ठ्यूतान्ते क्षणं सुखी कृच्छ्राच्छयानः श्वसिति निष्ण्णः स्वास्थ्यमृच्छति", text: "pratāmyettasya vegena niṣṭhyūtānte kṣaṇaṃ sukhī kṛcchrācchayānaḥ śvasiti niṣṇṇaḥ svāsthyamṛcchati" },
      { type: "verse", number: "11", sanskrit: "उच्छ्रिताक्षो ललाटेन स्विद्यता भृशमर्तिमान् विशुष्कास्यो मुहुः श्वासी काङ्क्षत्युष्णं सवेपथुः", text: "ucchritākṣo lalāṭena svidyatā bhṛśamartimān viśuṣkāsyo muhuḥ śvāsī kāṅkṣatyuṣṇaṃ savepathuḥ" },
      { type: "verse", number: "12", sanskrit: "मेघाम्बुशीतप्राग्वातैः श्लेष्मलैश्च विवर्धते स याप्यस्तमकः साध्यो नवो वा बलिनो भवेत्", text: "meghāmbuśītaprāgvātaiḥ śleṣmalaiśca vivardhate sa yāpyastamakaḥ sādhyo navo vā balino bhavet" },
      { type: "verse", number: "13", sanskrit: "ज्वरमूर्छायुतः शीतैः शाम्येत् प्रतमकस्तु सः", text: "jvaramūrchāyutaḥ śītaiḥ śāmyet pratamakastu saḥ" },
      { type: "verse", number: "14", sanskrit: "छिन्नाच्छ्वसिति विच्छिन्नं मर्मच्छेदरुजार्दितः सस्वेदमूर्छः सानाहो बस्तिदाहनिरोधवान्", text: "chinnācchvasiti vicchinnaṃ marmacchedarujārditaḥ sasvedamūrchaḥ sānāho bastidāhanirodhavān" },
      { type: "verse", number: "15", sanskrit: "अधोदृग्विप्लुताक्षश्च मुह्यन् रक्तैकलोचनः शुष्कास्यः प्रलपन्दीनो नष्टच्छायो विचेतनः", text: "adhodṛgviplutākṣaśca muhyan raktaikalocanaḥ śuṣkāsyaḥ pralapandīno naṣṭacchāyo vicetanaḥ" },
      { type: "verse", number: "16", sanskrit: "महता महता दीनो नादेन श्वसिति क्रथन् उद्धूयमानः संरब्धो मत्तर्षभ इवानिशम्", text: "mahatā mahatā dīno nādena śvasiti krathan uddhūyamānaḥ saṃrabdho mattarṣabha ivāniśam" },
      { type: "verse", number: "17", sanskrit: "प्रणष्टज्ञानविज्ञानो विभ्रान्तनयनाननः वक्षः समाक्षिपन् बद्धमूत्रवर्चा विशीर्णवाक्", text: "praṇaṣṭajñānavijñāno vibhrāntanayanānanaḥ vakṣaḥ samākṣipan baddhamūtravarcā viśīrṇavāk" },
      { type: "verse", number: "18", sanskrit: "शुष्ककण्ठो मुहुर्मुह्यन् कर्णशङ्खशिरो ऽतिरुक्", text: "śuṣkakaṇṭho muhurmuhyan karṇaśaṅkhaśiro 'tiruk" },
      { type: "verse", number: "19", sanskrit: "दीर्घमूर्ध्वं श्वसित्यूर्ध्वान्न च प्रत्याहरत्यधः श्लेष्मावृतमुखस्रोताः क्रुद्धगन्धवहार्दितः", text: "dīrghamūrdhvaṃ śvasityūrdhvānna ca pratyāharatyadhaḥ śleṣmāvṛtamukhasrotāḥ kruddhagandhavahārditaḥ" },
      { type: "verse", number: "20", sanskrit: "मर्मसु छिद्यमानेषु परिदेवी निरुद्धवाक्", text: "marmasu chidyamāneṣu paridevī niruddhavāk" },
      { type: "verse", number: "21", sanskrit: "एते सिध्येयुरव्यक्ता व्यक्ताः प्राणहरा ध्रुवम्", text: "ete sidhyeyuravyaktā vyaktāḥ prāṇaharā dhruvam" },
      { type: "verse", number: "22", sanskrit: "श्वासैकहेतुप्राग्रूपसङ्ख्याग्रकृतिसंश्रयाः हिध्मा भक्तोद्भवा क्षुद्रा यमला महतीति च", text: "śvāsaikahetuprāgrūpasaṅkhyāgrakṛtisaṃśrayāḥ hidhmā bhaktodbhavā kṣudrā yamalā mahatīti ca" },
      { type: "verse", number: "23", sanskrit: "गम्भीरा च मरुत्तत्र त्वरयायुक्तिसेवितैः रूक्षतीक्ष्णखरासात्म्यैरन्नपानैः प्रपीडितः", text: "gambhīrā ca maruttatra tvarayāyuktisevitaiḥ rūkṣatīkṣṇakharāsātmyairannapānaiḥ prapīḍitaḥ" },
      { type: "verse", number: "24", sanskrit: "करोति हिध्मामरुजां मन्दशब्दां क्षवानुगाम् शमं सात्म्यान्नपानेन या प्रयाति च सान्नजा", text: "karoti hidhmāmarujāṃ mandaśabdāṃ kṣavānugām śamaṃ sātmyānnapānena yā prayāti ca sānnajā" },
      { type: "verse", number: "25", sanskrit: "आयासात् पवनः क्रुद्धः क्षुद्रां हिध्मां प्रवर्तयेत् जत्रुमूलप्रविसृतामल्पवेगां मृदुं च सा", text: "āyāsāt pavanaḥ kruddhaḥ kṣudrāṃ hidhmāṃ pravartayet jatrumūlapravisṛtāmalpavegāṃ mṛduṃ ca sā" },
      { type: "verse", number: "26", sanskrit: "वृद्धिमायास्यतो याति भुक्तमात्रे च मार्दवम्", text: "vṛddhimāyāsyato yāti bhuktamātre ca mārdavam" },
      { type: "verse", number: "27", sanskrit: "चिरेण यमलैर्वेगैराहारे या प्रवर्तते परिणामोन्मुखे वृद्धिं परिणामे च गच्छति", text: "cireṇa yamalairvegairāhāre yā pravartate pariṇāmonmukhe vṛddhiṃ pariṇāme ca gacchati" },
      { type: "verse", number: "28", sanskrit: "कम्पयन्ती शिरोग्रीवामाध्मातस्यातितृष्यतः प्रलापच्छर्द्यतीसारनेत्रविप्लुतिजृम्भिणः", text: "kampayantī śirogrīvāmādhmātasyātitṛṣyataḥ pralāpacchardyatīsāranetraviplutijṛmbhiṇaḥ" },
      { type: "verse", number: "29", sanskrit: "यमला वेगिनी हिध्मा परिणामवती च सा", text: "yamalā veginī hidhmā pariṇāmavatī ca sā" },
      { type: "verse", number: "30", sanskrit: "ध्वस्तभ्रूशङ्खयुग्मस्य सास्रविप्लुतचक्षुषः स्तम्भयन्ती तनुं वाचं स्मृतिं संज्ञां च मुष्णती", text: "dhvastabhrūśaṅkhayugmasya sāsraviplutacakṣuṣaḥ stambhayantī tanuṃ vācaṃ smṛtiṃ saṃjñāṃ ca muṣṇatī" },
      { type: "verse", number: "31", sanskrit: "रुन्धती मार्गमन्नस्य कुर्वती मर्मघट्टनम् पृष्ठतो नमनं शोषं महाहिध्मा प्रवर्तते", text: "rundhatī mārgamannasya kurvatī marmaghaṭṭanam pṛṣṭhato namanaṃ śoṣaṃ mahāhidhmā pravartate" },
      { type: "verse", number: "32", sanskrit: "महामूला महाशब्दा महावेगा महाबला षक्वाशयाद्वा नाभेर्वा पूर्ववद्या प्रवर्तते", text: "mahāmūlā mahāśabdā mahāvegā mahābalā ṣakvāśayādvā nābhervā pūrvavadyā pravartate" },
      { type: "verse", number: "33", sanskrit: "तद्रूपा सा मुहुः कुर्यात् जृम्भामङ्गप्रसारणम् गम्भीरेणानुनादने गम्भीरा तासु साधयेत् आद्ये द्वे वर्जयेदन्त्ये सर्वलिङ्गां च वेगिनीम्", text: "tadrūpā sā muhuḥ kuryāt jṛmbhāmaṅgaprasāraṇam gambhīreṇānunādane gambhīrā tāsu sādhayet ādye dve varjayedantye sarvaliṅgāṃ ca veginīm" },
      { type: "verse", number: "34", sanskrit: "सर्वाश्च सञ्चितामस्य स्थविरस्य व्यवायिनः व्याधिभिः क्षीणदेहस्य भक्तच्छेदक्षतस्य वा", text: "sarvāśca sañcitāmasya sthavirasya vyavāyinaḥ vyādhibhiḥ kṣīṇadehasya bhaktacchedakṣatasya vā" },
      { type: "verse", number: "35", sanskrit: "सर्वे ऽपि रोगा नाशाय नत्वेवं शीघ्रकारिणः हिध्माश्वासौ यथा तौ हि मृत्युकाले कृतालयौ", text: "sarve 'pi rogā nāśāya natvevaṃ śīghrakāriṇaḥ hidhmāśvāsau yathā tau hi mṛtyukāle kṛtālayau" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 5,
    lang: "sa",
    content: [
      { type: "heading", heading: "Удара нидана — болезни живота" },
      { type: "text", text: "Глава 5 Нидана стханы — диагностический раздел о болезни живота. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातो राजयक्ष्मादिनिदानं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto rājayakṣmādinidānaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अनेकरोगानुगतो बहुरोगपुरोगमः राजयक्ष्मा क्षयः शोषो रोगराडिति च स्मृतः", text: "anekarogānugato bahurogapurogamaḥ rājayakṣmā kṣayaḥ śoṣo rogarāḍiti ca smṛtaḥ" },
      { type: "verse", number: "3", sanskrit: "नक्षत्राणां द्विजानां च राज्ञो ऽभूद्यदयं पुरा यच्च राजा च यक्ष्मा च राजयक्ष्मा ततो मतः", text: "nakṣatrāṇāṃ dvijānāṃ ca rājño 'bhūdyadayaṃ purā yacca rājā ca yakṣmā ca rājayakṣmā tato mataḥ" },
      { type: "verse", number: "4", sanskrit: "देहौषधक्षयकृतेः क्षयस्तत्सम्भवाच्च सः रसादिशोषणाच्छोषो रोगराट् तेषु राजनात्", text: "dehauṣadhakṣayakṛteḥ kṣayastatsambhavācca saḥ rasādiśoṣaṇācchoṣo rogarāṭ teṣu rājanāt" },
      { type: "verse", number: "5", sanskrit: "साहसं वेगसंरोधः शुक्रौजःस्नेहसङ्क्षयः अन्नपानविधित्यागश्चत्वारस्तस्य हेतवः", text: "sāhasaṃ vegasaṃrodhaḥ śukraujaḥsnehasaṅkṣayaḥ annapānavidhityāgaścatvārastasya hetavaḥ" },
      { type: "verse", number: "6", sanskrit: "तैरुदीर्णो ऽनिलः पित्तं कफं चोदीर्य सर्वतः शरीरसन्धीनाविश्य तान् सिराश्च प्रपीडयन्", text: "tairudīrṇo 'nilaḥ pittaṃ kaphaṃ codīrya sarvataḥ śarīrasandhīnāviśya tān sirāśca prapīḍayan" },
      { type: "verse", number: "7", sanskrit: "मुखानि स्रोतसां रुध्वा तथैवातिविवृत्य वा सर्पन्नूर्ध्वमधस्तिर्यग्यथास्वं जनयेत् गदान्", text: "mukhāni srotasāṃ rudhvā tathaivātivivṛtya vā sarpannūrdhvamadhastiryagyathāsvaṃ janayet gadān" },
      { type: "verse", number: "8", sanskrit: "रूपं भविष्यतस्तस्य प्रतिश्यायो भृशं क्षवः प्रसेको मुखमाधुर्य्ंअ सदनं वह्निदेहयोः", text: "rūpaṃ bhaviṣyatastasya pratiśyāyo bhṛśaṃ kṣavaḥ praseko mukhamādhuryṃa sadanaṃ vahnidehayoḥ" },
      { type: "verse", number: "9", sanskrit: "स्थाल्यमत्रान्नपानादौ शुचावप्यशुचीक्षणम् मक्षिकातृणकेशादिपातः प्रायो ऽन्नपानयोः", text: "sthālyamatrānnapānādau śucāvapyaśucīkṣaṇam makṣikātṛṇakeśādipātaḥ prāyo 'nnapānayoḥ" },
      { type: "verse", number: "10", sanskrit: "हृल्लासश्छर्दिररुचिरश्नतो ऽपि बलक्षयः पाण्योरवेक्षा पादस्य शोफो ऽक्ष्णोरतिशुक्लता", text: "hṛllāsaśchardiraruciraśnato 'pi balakṣayaḥ pāṇyoravekṣā pādasya śopho 'kṣṇoratiśuklatā" },
      { type: "verse", number: "11", sanskrit: "बाह्वोः प्रमाणजिज्ञासा काये बैभत्स्यदर्शनम् स्त्रीमद्यमांसप्रियता घृणित्वं मूर्धगुण्ठनम्", text: "bāhvoḥ pramāṇajijñāsā kāye baibhatsyadarśanam strīmadyamāṃsapriyatā ghṛṇitvaṃ mūrdhaguṇṭhanam" },
      { type: "verse", number: "12", sanskrit: "नखकेशातिवृद्धिश्च स्वप्ने चाभिभवो भवेत् पतङ्गकृकलासाहिकपिश्वापदपक्षिभिः", text: "nakhakeśātivṛddhiśca svapne cābhibhavo bhavet pataṅgakṛkalāsāhikapiśvāpadapakṣibhiḥ" },
      { type: "verse", number: "13", sanskrit: "केशास्थितुषभस्मादिराशौ समधिरोहणम् शून्यानां ग्रामदेशानां दर्शनं शुष्यतो ऽम्भसः", text: "keśāsthituṣabhasmādirāśau samadhirohaṇam śūnyānāṃ grāmadeśānāṃ darśanaṃ śuṣyato 'mbhasaḥ" },
      { type: "verse", number: "14", sanskrit: "ज्योतिर्गिरीणां पततां ज्वलतां च महीरुहाम्", text: "jyotirgirīṇāṃ patatāṃ jvalatāṃ ca mahīruhām" },
      { type: "verse", number: "15", sanskrit: "पीनसश्वासकासांसमूर्धस्वररुजो ऽरुचिः ऊर्ध्वं विट्स्रंससंशोषावधश्छरिदिस्तु कोष्ठगे", text: "pīnasaśvāsakāsāṃsamūrdhasvararujo 'ruciḥ ūrdhvaṃ viṭsraṃsasaṃśoṣāvadhaścharidistu koṣṭhage" },
      { type: "verse", number: "16", sanskrit: "तिर्यक्स्थे पार्श्वरुक्दोषे सन्धिगे भवति ज्वरः रूपाण्येकादशैतानि जायन्ते राजयक्ष्मिणः", text: "tiryaksthe pārśvarukdoṣe sandhige bhavati jvaraḥ rūpāṇyekādaśaitāni jāyante rājayakṣmiṇaḥ" },
      { type: "verse", number: "17", sanskrit: "तेषामुपद्रवान् विद्यात् कण्ठोद्ध्वंसमुरोरुजम् जृम्भाङ्गमर्दनिष्ठीववह्निसादास्यपूतिताः", text: "teṣāmupadravān vidyāt kaṇṭhoddhvaṃsamurorujam jṛmbhāṅgamardaniṣṭhīvavahnisādāsyapūtitāḥ" },
      { type: "verse", number: "18", sanskrit: "तत्र वाताच्छिरःपार्श्वशूलमंसाङ्गमर्दनम् कण्ठोद्ध्वंसः स्वरभ्रंशः पित्तात् पादास्यपाणिषु", text: "tatra vātācchiraḥpārśvaśūlamaṃsāṅgamardanam kaṇṭhoddhvaṃsaḥ svarabhraṃśaḥ pittāt pādāsyapāṇiṣu" },
      { type: "verse", number: "19", sanskrit: "दाहोतिसारो ऽसृक्छर्दिर्मुखगन्धो ज्वरो मदः कफादरोचकश्छर्दिः कासो मूर्धाङ्गगौरवम्", text: "dāhotisāro 'sṛkchardirmukhagandho jvaro madaḥ kaphādarocakaśchardiḥ kāso mūrdhāṅgagauravam" },
      { type: "verse", number: "20", sanskrit: "प्रसेकः पीनसः श्वासः स्वरसादो ऽल्पवह्निता", text: "prasekaḥ pīnasaḥ śvāsaḥ svarasādo 'lpavahnitā" },
      { type: "verse", number: "21", sanskrit: "दोषैर्मन्दानलत्वेन सोपलेपैः कफोल्बणैः स्रोतोमुखेषु रुद्धेषु धातूष्मस्वल्पकेषु च", text: "doṣairmandānalatvena sopalepaiḥ kapholbaṇaiḥ srotomukheṣu ruddheṣu dhātūṣmasvalpakeṣu ca" },
      { type: "verse", number: "22", sanskrit: "विदह्यमानः स्वस्थाने रसस्तांस्तानुपद्रवान् कुर्यादगच्छन् मांसादीनसृक् चोर्ध्वं प्रधावति", text: "vidahyamānaḥ svasthāne rasastāṃstānupadravān kuryādagacchan māṃsādīnasṛk cordhvaṃ pradhāvati" },
      { type: "verse", number: "23", sanskrit: "पच्यते कोष्ठ एवान्नमन्नपक्त्रैव चास्य यत् प्रायो ऽस्मान्मलतां यातं नैवालं धातुपुष्टये", text: "pacyate koṣṭha evānnamannapaktraiva cāsya yat prāyo 'smānmalatāṃ yātaṃ naivālaṃ dhātupuṣṭaye" },
      { type: "verse", number: "24", sanskrit: "रसो ऽप्यस्य न रक्ताय मांसाय कुत एव तु अवष्टब्धः स शकृता केवलं वर्तते क्षयी", text: "raso 'pyasya na raktāya māṃsāya kuta eva tu avaṣṭabdhaḥ sa śakṛtā kevalaṃ vartate kṣayī" },
      { type: "verse", number: "25", sanskrit: "लिङ्गेष्वल्पेष्वपि क्षीणं व्याध्यौषधबलाक्षमम् वर्जयेत् साधयेदेव सर्वेष्वपि ततो ऽन्यथा", text: "liṅgeṣvalpeṣvapi kṣīṇaṃ vyādhyauṣadhabalākṣamam varjayet sādhayedeva sarveṣvapi tato 'nyathā" },
      { type: "verse", number: "26", sanskrit: "दोषैर्व्यस्तैः समस्तैश्च क्षयात् षष्ठश्च मेदसा स्वरसादो भवेत्तत्र क्षामो रूक्षश्चलः स्वरः", text: "doṣairvyastaiḥ samastaiśca kṣayāt ṣaṣṭhaśca medasā svarasādo bhavettatra kṣāmo rūkṣaścalaḥ svaraḥ" },
      { type: "verse", number: "27", sanskrit: "शूकपूर्णाभकण्ठत्वं स्निग्धोष्णोपशयो ऽनिलात् पित्तात्तालुगले दाहः शोष उक्तावसूयनम्", text: "śūkapūrṇābhakaṇṭhatvaṃ snigdhoṣṇopaśayo 'nilāt pittāttālugale dāhaḥ śoṣa uktāvasūyanam" },
      { type: "verse", number: "28", sanskrit: "लिम्पन्निव कफात् कण्ठं मन्दः खुरखुरायते स्वरो विबद्धः सर्वैस्तु सर्वलिङ्गः क्षयात् कषेत्", text: "limpanniva kaphāt kaṇṭhaṃ mandaḥ khurakhurāyate svaro vibaddhaḥ sarvaistu sarvaliṅgaḥ kṣayāt kaṣet" },
      { type: "verse", number: "29", sanskrit: "धूमायतीव चात्यर्थं मेदसा श्लेष्मलक्षणः कृच्छ्रलक्ष्याक्षरश्चात्र सर्वैरन्त्यं च वर्जयेत्", text: "dhūmāyatīva cātyarthaṃ medasā śleṣmalakṣaṇaḥ kṛcchralakṣyākṣaraścātra sarvairantyaṃ ca varjayet" },
      { type: "verse", number: "30", sanskrit: "अरोचको भवेद्दोषैर्जिह्वाहृदयसंश्रयैः सन्निपातेन मनसः सन्तापेन च पञ्चमः", text: "arocako bhaveddoṣairjihvāhṛdayasaṃśrayaiḥ sannipātena manasaḥ santāpena ca pañcamaḥ" },
      { type: "verse", number: "31", sanskrit: "कषायतिक्तमधुरं वातादिषु मुखं क्रमात् सर्वोत्थे विरसं शोकक्रोधादिषु यथामलम्", text: "kaṣāyatiktamadhuraṃ vātādiṣu mukhaṃ kramāt sarvotthe virasaṃ śokakrodhādiṣu yathāmalam" },
      { type: "verse", number: "32", sanskrit: "छर्दिर्दोषैः पृथक् सर्वैर्द्विष्टैरर्थैश्च पञ्चमी उदानो विकृतो दोषान् यूसर्वास्वर्प्ध्वमस्यति", text: "chardirdoṣaiḥ pṛthak sarvairdviṣṭairarthaiśca pañcamī udāno vikṛto doṣān yūsarvāsvarpdhvamasyati" },
      { type: "verse", number: "33", sanskrit: "तासूत्क्लेशास्यलावण्यप्रसेकारुचयो ऽग्रगाः नाभिं पृष्ठं रुजन् वायुः पार्श्वेचाहारमुत्क्षिपेत्", text: "tāsūtkleśāsyalāvaṇyaprasekārucayo 'gragāḥ nābhiṃ pṛṣṭhaṃ rujan vāyuḥ pārśvecāhāramutkṣipet" },
      { type: "verse", number: "34", sanskrit: "ततो विच्छिन्नमल्पाल्पं कषायं फेनिलं वमेत् शब्दोद्गारयुतं कृष्णमच्छं कृच्छ्रेण वेगवत्", text: "tato vicchinnamalpālpaṃ kaṣāyaṃ phenilaṃ vamet śabdodgārayutaṃ kṛṣṇamacchaṃ kṛcchreṇa vegavat" },
      { type: "verse", number: "35", sanskrit: "कासास्यशोषहृन्मूर्धस्वरपीडाक्लमान्वितः पित्तात् क्षारोदकनिभं धूम्रं हरितपीतकम्", text: "kāsāsyaśoṣahṛnmūrdhasvarapīḍāklamānvitaḥ pittāt kṣārodakanibhaṃ dhūmraṃ haritapītakam" },
      { type: "verse", number: "36", sanskrit: "सासृगम्लं कटूष्णं च तृण्मूर्छादाहतापवान् कफात् स्निग्धं घनं श्वेतं श्लेष्मतन्तुगवाक्षितम्", text: "sāsṛgamlaṃ kaṭūṣṇaṃ ca tṛṇmūrchādāhatāpavān kaphāt snigdhaṃ ghanaṃ śvetaṃ śleṣmatantugavākṣitam" },
      { type: "verse", number: "37", sanskrit: "मधुरं लवणं भूरिप्रसक्तं लोमहर्षणम् मुखश्वयथुमाधुर्यतन्द्राहृल्लासकासवान्", text: "madhuraṃ lavaṇaṃ bhūriprasaktaṃ lomaharṣaṇam mukhaśvayathumādhuryatandrāhṛllāsakāsavān" },
      { type: "verse", number: "38", sanskrit: "सर्वलिङ्गा मलैः सर्वै रिष्टोक्ता याच तां त्यजेत् पूत्यमेध्याशुचिद्विष्टदर्शनश्रवणादिभिः", text: "sarvaliṅgā malaiḥ sarvai riṣṭoktā yāca tāṃ tyajet pūtyamedhyāśucidviṣṭadarśanaśravaṇādibhiḥ" },
      { type: "verse", number: "39", sanskrit: "तप्ते चित्ते हृदि क्लिष्टे छर्दिर्द्विष्टार्थयोगजा", text: "tapte citte hṛdi kliṣṭe chardirdviṣṭārthayogajā" },
      { type: "verse", number: "40", sanskrit: "वातादीनेव विमृशेत् कृमितृष्णामदौहृदे शूलवेपथुहृल्लासैर्विशेषात् कृमिजां वदेत्", text: "vātādīneva vimṛśet kṛmitṛṣṇāmadauhṛde śūlavepathuhṛllāsairviśeṣāt kṛmijāṃ vadet" },
      { type: "verse", number: "41", sanskrit: "कृमिहृद्रोगलिग्गैश्च स्मृताः पञ्च तु हृद्गदाः तेषां गुल्मनिदानोक्तैः समुत्थानैश्च सम्भवः", text: "kṛmihṛdrogaliggaiśca smṛtāḥ pañca tu hṛdgadāḥ teṣāṃ gulmanidānoktaiḥ samutthānaiśca sambhavaḥ" },
      { type: "verse", number: "42", sanskrit: "वातेन शूल्यते ऽत्यर्थं तुद्येते स्फुटतीव च भिद्यते शुष्यति स्तब्धं हृदयं शून्यता द्रवः", text: "vātena śūlyate 'tyarthaṃ tudyete sphuṭatīva ca bhidyate śuṣyati stabdhaṃ hṛdayaṃ śūnyatā dravaḥ" },
      { type: "verse", number: "43", sanskrit: "अकस्माद्दीनता शोको भयं शब्दासहिष्णुता वेपथुर्वेष्टनं मोहः श्वासरोधो ऽल्पनिद्रता", text: "akasmāddīnatā śoko bhayaṃ śabdāsahiṣṇutā vepathurveṣṭanaṃ mohaḥ śvāsarodho 'lpanidratā" },
      { type: "verse", number: "44", sanskrit: "पित्तात्तृष्णा भ्रमो मूर्च्छा स्वेदो ऽम्लकःक्लमः छर्दनं चाम्लपित्तस्य धूमकः पीतता ज्वरः", text: "pittāttṛṣṇā bhramo mūrcchā svedo 'mlakaḥklamaḥ chardanaṃ cāmlapittasya dhūmakaḥ pītatā jvaraḥ" },
      { type: "verse", number: "45", sanskrit: "श्लेष्मणा हृदयं स्तब्धं भारि कंसाश्मगर्भवत् कासाग्निसादनिष्ठीवनिद्रालस्यारुचिज्वराः", text: "śleṣmaṇā hṛdayaṃ stabdhaṃ bhāri kaṃsāśmagarbhavat kāsāgnisādaniṣṭhīvanidrālasyārucijvarāḥ" },
      { type: "verse", number: "46", sanskrit: "सर्वलिङ्गस्त्रिभिर्दोषैः कृमिभिः श्यावनेत्रता तमःप्रवेशो हृल्लासः शोषः कण्डूः कफस्रुतिः", text: "sarvaliṅgastribhirdoṣaiḥ kṛmibhiḥ śyāvanetratā tamaḥpraveśo hṛllāsaḥ śoṣaḥ kaṇḍūḥ kaphasrutiḥ" },
      { type: "verse", number: "47", sanskrit: "हृदयं प्रततञ्चात्र क्रकचेनेव दार्यते चिकित्सेदामयं घोरं तं शीघ्रं शीघ्रकारिणम्", text: "hṛdayaṃ pratatañcātra krakaceneva dāryate cikitsedāmayaṃ ghoraṃ taṃ śīghraṃ śīghrakāriṇam" },
      { type: "verse", number: "48", sanskrit: "वातात् पित्तात् कफात् तृष्णा सन्निपाताद्रसक्षयात् षष्ठी स्यादुपसर्गाच्च वातपित्ते तु कारणम्", text: "vātāt pittāt kaphāt tṛṣṇā sannipātādrasakṣayāt ṣaṣṭhī syādupasargācca vātapitte tu kāraṇam" },
      { type: "verse", number: "49", sanskrit: "सर्वासु तत्प्रकोपो हि सौम्यधातुप्रशोषणात् सर्वदेहभ्रमोत्कम्पतापतृट्दाहमोहकृत्", text: "sarvāsu tatprakopo hi saumyadhātupraśoṣaṇāt sarvadehabhramotkampatāpatṛṭdāhamohakṛt" },
      { type: "verse", number: "50", sanskrit: "जिह्वामूलगलक्लोमतालुतोयवहाः सिराः संशोष्य तृष्णा जायन्ते तासां सामान्यलक्षणम्", text: "jihvāmūlagalaklomatālutoyavahāḥ sirāḥ saṃśoṣya tṛṣṇā jāyante tāsāṃ sāmānyalakṣaṇam" },
      { type: "verse", number: "51", sanskrit: "मुखशोषो जलातृप्तिरन्नद्वेषः स्वरक्षयः कण्ठौष्ठजिह्वाकार्कश्यं जिह्वानिष्क्रमणं क्लमः", text: "mukhaśoṣo jalātṛptirannadveṣaḥ svarakṣayaḥ kaṇṭhauṣṭhajihvākārkaśyaṃ jihvāniṣkramaṇaṃ klamaḥ" },
      { type: "verse", number: "52", sanskrit: "प्रलापश्चित्तविभ्रंशस्तृड्ग्रहोक्तास्तथामयाः", text: "pralāpaścittavibhraṃśastṛḍgrahoktāstathāmayāḥ" },
      { type: "verse", number: "53", sanskrit: "मारुतात् क्षामता दैन्यं शङ्खतोदः शिरोभ्रमः गन्धाज्ञानास्यवैरस्यश्रुतिनिद्राबलक्षयाः", text: "mārutāt kṣāmatā dainyaṃ śaṅkhatodaḥ śirobhramaḥ gandhājñānāsyavairasyaśrutinidrābalakṣayāḥ" },
      { type: "verse", number: "54", sanskrit: "शीताम्बुपानाद्वृद्धिश्च पित्तान्मूर्छास्यतिक्तता रक्तेक्षणत्वं प्रततं शोषो दाहो ऽतिधूमकः", text: "śītāmbupānādvṛddhiśca pittānmūrchāsyatiktatā raktekṣaṇatvaṃ pratataṃ śoṣo dāho 'tidhūmakaḥ" },
      { type: "verse", number: "55", sanskrit: "कफो रुणद्धि कुपितस्तोयवाहिषु मारुतम् स्रोतस्सु सकफस्तेन पङ्कवच्छोष्यते ततः", text: "kapho ruṇaddhi kupitastoyavāhiṣu mārutam srotassu sakaphastena paṅkavacchoṣyate tataḥ" },
      { type: "verse", number: "56", sanskrit: "शूकैरिवाचितः कण्ठो निद्रा मधुरवक्त्रता आध्मानं शिरसो जाड्यं स्तैमित्यच्छर्द्यरोचकाः आलस्यमविपाकश्च सर्वैः स्यात् सर्वलक्षणा", text: "śūkairivācitaḥ kaṇṭho nidrā madhuravaktratā ādhmānaṃ śiraso jāḍyaṃ staimityacchardyarocakāḥ ālasyamavipākaśca sarvaiḥ syāt sarvalakṣaṇā" },
      { type: "verse", number: "57", sanskrit: "आमोद्भवा च भक्तस्य संरोधाद्वातपित्तजा उष्णक्लान्तस्य सहसा शीताम्भो भजतस्तृषम्", text: "āmodbhavā ca bhaktasya saṃrodhādvātapittajā uṣṇaklāntasya sahasā śītāmbho bhajatastṛṣam" },
      { type: "verse", number: "58", sanskrit: "ऊष्मा रुद्धो गतः कोष्ठं यां कुर्यात् पित्तजैव सा या च पानातिपानोत्था तीक्ष्णाग्रेःस्नेहजा च या", text: "ūṣmā ruddho gataḥ koṣṭhaṃ yāṃ kuryāt pittajaiva sā yā ca pānātipānotthā tīkṣṇāgreḥsnehajā ca yā" },
      { type: "verse", number: "59", sanskrit: "स्निग्धगुर्वम्ललवणभोजनेन कफोद्भवा तृष्णा रसक्षयोक्तेन लक्षणेन क्षयात्मिका", text: "snigdhagurvamlalavaṇabhojanena kaphodbhavā tṛṣṇā rasakṣayoktena lakṣaṇena kṣayātmikā" },
      { type: "verse", number: "60", sanskrit: "शोषमेहज्वराद्यन्यदीर्घरोगोपसर्गतः या तृष्णा जायते तीव्रा सोपसर्गात्मिका स्मृता", text: "śoṣamehajvarādyanyadīrgharogopasargataḥ yā tṛṣṇā jāyate tīvrā sopasargātmikā smṛtā" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 6,
    lang: "sa",
    content: [
      { type: "heading", heading: "Прамеха нидана — диабет" },
      { type: "text", text: "Глава 6 Нидана стханы — диагностический раздел о диабет. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातो मदात्ययनिदानं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto madātyayanidānaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "तीक्ष्णोक्ष्णरूक्षसूक्ष्माम्लं व्यवाय्याशुकरं लघु विकाशि विशदं मद्यमोजसो ऽस्माद्विपर्ययः", text: "tīkṣṇokṣṇarūkṣasūkṣmāmlaṃ vyavāyyāśukaraṃ laghu vikāśi viśadaṃ madyamojaso 'smādviparyayaḥ" },
      { type: "verse", number: "3", sanskrit: "तीक्ष्णादयो विषे ऽप्युक्ताश्चित्तोपप्लाविनो गुणाः जीवितान्ताय जायन्ते विषे तूत्कर्षवृत्तितः", text: "tīkṣṇādayo viṣe 'pyuktāścittopaplāvino guṇāḥ jīvitāntāya jāyante viṣe tūtkarṣavṛttitaḥ" },
      { type: "verse", number: "4", sanskrit: "तीक्ष्णादिभिर्गुणैर्मद्यं मन्दादीनोजसो गुणान् दशभिर्दश सङ्क्षोभ्य चेतो नयति विक्रियाम्", text: "tīkṣṇādibhirguṇairmadyaṃ mandādīnojaso guṇān daśabhirdaśa saṅkṣobhya ceto nayati vikriyām" },
      { type: "verse", number: "5", sanskrit: "आद्ये मदे द्वितीये तु प्रमादायतने स्थितः दुर्विकल्पहतो मूढः सुखमित्यवबुध्यते", text: "ādye made dvitīye tu pramādāyatane sthitaḥ durvikalpahato mūḍhaḥ sukhamityavabudhyate" },
      { type: "verse", number: "6", sanskrit: "मध्यमोत्तमयोः सन्धिं प्राप्य राजसतामसः निरङ्कुश इव व्यालो न किञ्चिन्नाचरेज्जडः", text: "madhyamottamayoḥ sandhiṃ prāpya rājasatāmasaḥ niraṅkuśa iva vyālo na kiñcinnācarejjaḍaḥ" },
      { type: "verse", number: "7", sanskrit: "इयं भूमिरवद्यानां दौश्शील्यस्येदमास्पदम् एको ऽयं बहुमार्गाया दुर्गतेर्देशिकः परम्", text: "iyaṃ bhūmiravadyānāṃ dauśśīlyasyedamāspadam eko 'yaṃ bahumārgāyā durgaterdeśikaḥ param" },
      { type: "verse", number: "8", sanskrit: "निश्चेष्टः शववच्छेते तृतीये तु मदे स्थितः मरणादपि पापात्मा गतः पापतरां दशाम्", text: "niśceṣṭaḥ śavavacchete tṛtīye tu made sthitaḥ maraṇādapi pāpātmā gataḥ pāpatarāṃ daśām" },
      { type: "verse", number: "9", sanskrit: "धर्माधर्मं सुखं दुःखमर्थानर्थ हिताहितम् यदासक्तो न जानाति कथं तच्छीलयेद्बुधः", text: "dharmādharmaṃ sukhaṃ duḥkhamarthānartha hitāhitam yadāsakto na jānāti kathaṃ tacchīlayedbudhaḥ" },
      { type: "verse", number: "10", sanskrit: "मद्ये मोहो भयं शोकः क्रोधो मृत्युश्च संश्रिताः सोन्मादमदमूर्च्छायाः सापस्मारापतानकाः", text: "madye moho bhayaṃ śokaḥ krodho mṛtyuśca saṃśritāḥ sonmādamadamūrcchāyāḥ sāpasmārāpatānakāḥ" },
      { type: "verse", number: "11", sanskrit: "यत्रैकः स्मृतिविभ्रंशस्तत्र सर्वमसाधु यत् अयुक्तियुक्तमन्नं हि व्याधये मरणाय वा मद्यं त्रिवर्गधीधैर्यलज्जादेरपि नाशनम्", text: "yatraikaḥ smṛtivibhraṃśastatra sarvamasādhu yat ayuktiyuktamannaṃ hi vyādhaye maraṇāya vā madyaṃ trivargadhīdhairyalajjāderapi nāśanam" },
      { type: "verse", number: "12", sanskrit: "नातिमाद्यन्ति बलिनः कृताहारा महाशनाः स्निग्धाः सत्ववयोयुक्ता मद्यनित्यास्तदन्वयाः मेदःकफाधिका मन्दवातपित्ता दृढाग्नयः", text: "nātimādyanti balinaḥ kṛtāhārā mahāśanāḥ snigdhāḥ satvavayoyuktā madyanityāstadanvayāḥ medaḥkaphādhikā mandavātapittā dṛḍhāgnayaḥ" },
      { type: "verse", number: "13", sanskrit: "विपर्यये ऽतिमाद्यन्ति विस्रब्धाः कुपिताश्च ये मद्येन चाम्लरूक्षेण साजीर्णे बहुनाति च", text: "viparyaye 'timādyanti visrabdhāḥ kupitāśca ye madyena cāmlarūkṣeṇa sājīrṇe bahunāti ca" },
      { type: "verse", number: "14", sanskrit: "वातात् पित्तात् कफात् सर्वैश्चत्वारः स्युर्मदात्ययाः सर्वे ऽपि सर्वैर्जायन्ते व्यपदेशस्तु भूयसा", text: "vātāt pittāt kaphāt sarvaiścatvāraḥ syurmadātyayāḥ sarve 'pi sarvairjāyante vyapadeśastu bhūyasā" },
      { type: "verse", number: "15", sanskrit: "सामान्यं लक्षणं तेषां प्रमोहो हृदयव्यथा विड्भेदः सततं तृष्णा सौम्याग्नेयो ज्वरो ऽरुचिः", text: "sāmānyaṃ lakṣaṇaṃ teṣāṃ pramoho hṛdayavyathā viḍbhedaḥ satataṃ tṛṣṇā saumyāgneyo jvaro 'ruciḥ" },
      { type: "verse", number: "16", sanskrit: "शिरःपार्श्वास्थिरुक्कम्पो मर्मभेदस्त्रिकग्रहः उरोविबन्धस्तिमिरं कासश्वासप्रजागराः", text: "śiraḥpārśvāsthirukkampo marmabhedastrikagrahaḥ urovibandhastimiraṃ kāsaśvāsaprajāgarāḥ" },
      { type: "verse", number: "17", sanskrit: "स्वेदो ऽतिमात्रं विष्टम्भः श्वयथुश्चित्तविभ्रमः प्रलापश्छर्दिरुत्क्लेशो भ्रमो दुःस्वप्नदर्शनम्", text: "svedo 'timātraṃ viṣṭambhaḥ śvayathuścittavibhramaḥ pralāpaśchardirutkleśo bhramo duḥsvapnadarśanam" },
      { type: "verse", number: "18", sanskrit: "विशेषाज्जागरश्वासकम्पमूर्धरुजो ऽनिलात् स्वप्ने भ्रमत्युत्पतति प्रेतैश्च सह भाषते", text: "viśeṣājjāgaraśvāsakampamūrdharujo 'nilāt svapne bhramatyutpatati pretaiśca saha bhāṣate" },
      { type: "verse", number: "19", sanskrit: "पित्ताद्दाहज्वरस्वेदमोहातीसारतृड्भ्रमाः देहो हरितहारिद्रो रक्तनेत्रकपोलता श्लेष्मणा छर्दिहृल्लासनिद्रोदर्दाङ्गगौरवम्", text: "pittāddāhajvarasvedamohātīsāratṛḍbhramāḥ deho haritahāridro raktanetrakapolatā śleṣmaṇā chardihṛllāsanidrodardāṅgagauravam" },
      { type: "verse", number: "20", sanskrit: "सर्वजे सर्वलिङ्गत्वम् मुक्त्वा मद्यं पिबेत्तु यः सहसानुचितं चान्यत्तस्य ध्वंसकविक्षयौ", text: "sarvaje sarvaliṅgatvam muktvā madyaṃ pibettu yaḥ sahasānucitaṃ cānyattasya dhvaṃsakavikṣayau" },
      { type: "verse", number: "21", sanskrit: "भवेतां मारुतात् कष्टौ दुर्बलस्य विशेषतः ध्वंसके श्लेष्मनिष्ठीवः कण्ठशोषो ऽतिनिद्रता", text: "bhavetāṃ mārutāt kaṣṭau durbalasya viśeṣataḥ dhvaṃsake śleṣmaniṣṭhīvaḥ kaṇṭhaśoṣo 'tinidratā" },
      { type: "verse", number: "22", sanskrit: "शब्दासहत्वं तन्द्रा च विक्षये ऽङ्गशिरो ऽतिरुक् हृत्कण्ठरोधः सम्मोहः कासस्तृष्णा वमिर्ज्वरः", text: "śabdāsahatvaṃ tandrā ca vikṣaye 'ṅgaśiro 'tiruk hṛtkaṇṭharodhaḥ sammohaḥ kāsastṛṣṇā vamirjvaraḥ" },
      { type: "verse", number: "23", sanskrit: "निवृत्तो यस्तु मद्येभ्यो जितात्मा बुद्धिपूर्वकृत् विकारैः स्पूश्यते जातु न स शारीरमानसैः", text: "nivṛtto yastu madyebhyo jitātmā buddhipūrvakṛt vikāraiḥ spūśyate jātu na sa śārīramānasaiḥ" },
      { type: "verse", number: "24", sanskrit: "रजोमोहाहिताहारपरस्य स्युस्त्रयो गदाः रसासृक्चेतनावाहिस्रोतोरोधसमुद्भवाः मदमूर्च्छायसन्यासा यथोत्तरबलोत्तराः", text: "rajomohāhitāhāraparasya syustrayo gadāḥ rasāsṛkcetanāvāhisrotorodhasamudbhavāḥ madamūrcchāyasanyāsā yathottarabalottarāḥ" },
      { type: "verse", number: "25", sanskrit: "मदो ऽत्र दोषैः सर्वैश्च रक्तमद्यविषैरपि सक्तानल्पद्रुताभाषश्चलस्खलितचेष्टितः", text: "mado 'tra doṣaiḥ sarvaiśca raktamadyaviṣairapi saktānalpadrutābhāṣaścalaskhalitaceṣṭitaḥ" },
      { type: "verse", number: "26", sanskrit: "रूक्षश्यावारुणतनुर्मदे वातोद्भवे भवेत् पित्तेन क्रोधनो रक्तपीताभः कलहप्रियः", text: "rūkṣaśyāvāruṇatanurmade vātodbhave bhavet pittena krodhano raktapītābhaḥ kalahapriyaḥ" },
      { type: "verse", number: "27", sanskrit: "स्वल्पसम्बद्धवाक् पाण्डुः कफाद् ध्यानपरो ऽलसः सर्वात्मा सन्निपातेन रक्तात् स्तब्धाङ्गदृष्टिता", text: "svalpasambaddhavāk pāṇḍuḥ kaphād dhyānaparo 'lasaḥ sarvātmā sannipātena raktāt stabdhāṅgadṛṣṭitā" },
      { type: "verse", number: "28", sanskrit: "पित्तलिङ्गं च मद्येन विकृतेहास्वराङ्गता विषात्कम्पो ऽतिनिद्रा च सर्वेभ्यो ऽभ्यधिकश्च सः लक्षयेल्लक्षणोत्कर्षाद्वातादीन् शोणितादिषु", text: "pittaliṅgaṃ ca madyena vikṛtehāsvarāṅgatā viṣātkampo 'tinidrā ca sarvebhyo 'bhyadhikaśca saḥ lakṣayellakṣaṇotkarṣādvātādīn śoṇitādiṣu" },
      { type: "verse", number: "29", sanskrit: "अरुणं नीलकृष्णं वा खं पश्यन् प्रविशेत्तमः शीघ्रं च प्रतिबुध्येत हृत्पीडा वेपथुर्भ्रमः", text: "aruṇaṃ nīlakṛṣṇaṃ vā khaṃ paśyan praviśettamaḥ śīghraṃ ca pratibudhyeta hṛtpīḍā vepathurbhramaḥ" },
      { type: "verse", number: "30", sanskrit: "कार्श्यं श्यावारुणा छाया मूर्च्छाये मारुतात्मके पित्तेन रक्तं पीतं वा नभः पश्यन् विशेत्तमः", text: "kārśyaṃ śyāvāruṇā chāyā mūrcchāye mārutātmake pittena raktaṃ pītaṃ vā nabhaḥ paśyan viśettamaḥ" },
      { type: "verse", number: "31", sanskrit: "विबुध्येत च सस्वेदो दाहतृट्तापपीडितः भिन्नविण्नीलपीताभो रक्तपीताकुलेक्षणः", text: "vibudhyeta ca sasvedo dāhatṛṭtāpapīḍitaḥ bhinnaviṇnīlapītābho raktapītākulekṣaṇaḥ" },
      { type: "verse", number: "32", sanskrit: "कफेन मेघसङ्क्शाशं पश्यन्नाकाशमाविशेत् तमश्चिराच्च बुध्येत सहृल्लासप्रसेकवान्", text: "kaphena meghasaṅkśāśaṃ paśyannākāśamāviśet tamaścirācca budhyeta sahṛllāsaprasekavān" },
      { type: "verse", number: "33", sanskrit: "गुरुभिः स्तमितैरङ्गैरार्द्रचर्मावनद्धवत् सर्वाकृतिस्त्रिभिर्दोषैरपस्मार इवापरः पातयत्याशु निश्चेष्टं विना बीभत्सचेष्टितैः", text: "gurubhiḥ stamitairaṅgairārdracarmāvanaddhavat sarvākṛtistribhirdoṣairapasmāra ivāparaḥ pātayatyāśu niśceṣṭaṃ vinā bībhatsaceṣṭitaiḥ" },
      { type: "verse", number: "34", sanskrit: "दोषेषु मदमूर्च्छायाः कृतवेगेषु देहिनाम् स्वयमेवोपशाम्यन्ति सन्न्यासो नौषधैर्विना", text: "doṣeṣu madamūrcchāyāḥ kṛtavegeṣu dehinām svayamevopaśāmyanti sannyāso nauṣadhairvinā" },
      { type: "verse", number: "35", sanskrit: "वाग्देहमनसां चेष्टामाक्षिप्यातिबला मलाः सन्न्यासं सन्निपतिताः प्राणायतनसंश्रयाः", text: "vāgdehamanasāṃ ceṣṭāmākṣipyātibalā malāḥ sannyāsaṃ sannipatitāḥ prāṇāyatanasaṃśrayāḥ" },
      { type: "verse", number: "36", sanskrit: "कुर्वन्ति तेन पुरुषः काष्ठभूतो मृतोपमः म्रियेत शीघ्रं शीघ्रं चेच्चिकित्सा न प्रयुज्यते", text: "kurvanti tena puruṣaḥ kāṣṭhabhūto mṛtopamaḥ mriyeta śīghraṃ śīghraṃ ceccikitsā na prayujyate" },
      { type: "verse", number: "37", sanskrit: "अगाधे ग्राहबहुले सलिलौघ इवातटे सन्न्यासे विनिमज्जन्तं नरमाशु निवर्तयेत्", text: "agādhe grāhabahule salilaugha ivātaṭe sannyāse vinimajjantaṃ naramāśu nivartayet" },
      { type: "verse", number: "38", sanskrit: "मदमानरोषतोषप्रभृतिभिररिभिर्निजैः परिष्वङ्गः युक्तायुक्तं च समं युक्तिवियुक्तेन मद्येन", text: "madamānaroṣatoṣaprabhṛtibhiraribhirnijaiḥ pariṣvaṅgaḥ yuktāyuktaṃ ca samaṃ yuktiviyuktena madyena" },
      { type: "verse", number: "39", sanskrit: "बलकालदेशसात्म्यप्रकृतिसहायामयवयांसि प्रविभज्य तदनुरूपं यदि पिबति ततः पिबत्यमृतम्", text: "balakāladeśasātmyaprakṛtisahāyāmayavayāṃsi pravibhajya tadanurūpaṃ yadi pibati tataḥ pibatyamṛtam" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 7,
    lang: "sa",
    content: [
      { type: "heading", heading: "Куштха нидана — кожные болезни" },
      { type: "text", text: "Глава 7 Нидана стханы — диагностический раздел о кожные болезни. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातो ऽर्शसां निदानं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto 'rśasāṃ nidānaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अरिवद्विशसन्तीत्यर्शांसि तानि पुनर्बहुप्रकाराणि सुबहूपद्रवाणि च पायुमेढ्रादिसंश्रया मांसकीलाः समासतस्तु द्विविधान्यर्शांसि सहजानि जन्मोत्तरकालजानि च पुनश्च द्विविधानि शुष्काण्यार्द्राणि च सर्वेषां पुनरधिष्टानं मेदो मांसं त्वक् च स्थूलान्त्रप्रतिबद्धो ऽर्धपञ्चाङ्गुलो हि गुदः तस्मिन् पूर्व मुक्ता वलीसंज्ञास्तिस्रः पेश्यो ऽध्यर्धाङ्गुलाः ताः प्रवाहिणी विसर्जनी संवरणी च रोमान्तादध्यर्धयवं गुदौष्ठमाहुः प्रथमा तु गुदौष्ठादङ्गुलमात्रो", text: "arivadviśasantītyarśāṃsi tāni punarbahuprakārāṇi subahūpadravāṇi ca pāyumeḍhrādisaṃśrayā māṃsakīlāḥ samāsatastu dvividhānyarśāṃsi sahajāni janmottarakālajāni ca punaśca dvividhāni śuṣkāṇyārdrāṇi ca sarveṣāṃ punaradhiṣṭānaṃ medo māṃsaṃ tvak ca sthūlāntrapratibaddho 'rdhapañcāṅgulo hi gudaḥ tasmin pūrva muktā valīsaṃjñāstisraḥ peśyo 'dhyardhāṅgulāḥ tāḥ pravāhiṇī visarjanī saṃvaraṇī ca romāntādadhyardhayavaṃ gudauṣṭhamāhuḥ prathamā tu gudauṣṭhādaṅgulamātro" },
      { type: "verse", number: "3", sanskrit: "तत्र सहजानां गुदवलीबीजोपतप्तिरायतनम् तस्या द्विविधो हेतुः मातापित्रोरपचारो दैवं च ताभ्यां सन्निपातप्रकोपः तस्मात्तान्यसाध्यानि एतेन कुलजाः सर्वे विकारा व्याख्याताः", text: "tatra sahajānāṃ gudavalībījopataptirāyatanam tasyā dvividho hetuḥ mātāpitrorapacāro daivaṃ ca tābhyāṃ sannipātaprakopaḥ tasmāttānyasādhyāni etena kulajāḥ sarve vikārā vyākhyātāḥ" },
      { type: "verse", number: "4", sanskrit: "विशेषतस्तु सहजानि दुर्दर्शनपरुषपाण्डूपचितदारुणान्यन्तर्मुखानि बहूपद्रवोपद्रुतानि भवति", text: "viśeṣatastu sahajāni durdarśanaparuṣapāṇḍūpacitadāruṇānyantarmukhāni bahūpadravopadrutāni bhavati" },
      { type: "verse", number: "5", sanskrit: "अथेतराणि षड्विधानि पृथग्दोषैः संसृष्टैः सन्निपतितैः शोणितेन च तत्र वातश्लेष्मोत्तराणि शुष्काणि रक्तपित्तोत्तराण्यार्द्राणि", text: "athetarāṇi ṣaḍvidhāni pṛthagdoṣaiḥ saṃsṛṣṭaiḥ sannipatitaiḥ śoṇitena ca tatra vātaśleṣmottarāṇi śuṣkāṇi raktapittottarāṇyārdrāṇi" },
      { type: "verse", number: "6", sanskrit: "दोषप्रकोपहेतुस्तु प्रागुक्तः स यदा मलोपचयमादधाति पुनश्चोत्कटकविषमकठिनासनसेवनादुद्भ्रान्तयानोष्ट्रादिप्रयाणादतिव्यवायद्बास्तिनेत्रासम्यक्प्रणिधानादिना गुदक्षणनादभीक्ष्णं शीताम्बुसंस्पर्शाच्चैललोष्टतृणादिसङ्घर्षात् प्रततातिप्रवाहणाद्वातमूत्रपुरीषवेगोदीरणधारणात् स्त्रीणां चमगर्भभ्रंशाद्गर्भोत्पीडनाद्विषमप्रसूतेरेवंविधश्चापरः कुपितो वायुरपानस्तं मलमुपचितमधोगतमासाद्य गुदवलीष्वाधत्ते ततस्तास्वभिष्यण्णास्वर्शांसि सम्भवन्ति", text: "doṣaprakopahetustu prāguktaḥ sa yadā malopacayamādadhāti punaścotkaṭakaviṣamakaṭhināsanasevanādudbhrāntayānoṣṭrādiprayāṇādativyavāyadbāstinetrāsamyakpraṇidhānādinā gudakṣaṇanādabhīkṣṇaṃ śītāmbusaṃsparśāccailaloṣṭatṛṇādisaṅgharṣāt pratatātipravāhaṇādvātamūtrapurīṣavegodīraṇadhāraṇāt strīṇāṃ camagarbhabhraṃśādgarbhotpīḍanādviṣamaprasūterevaṃvidhaścāparaḥ kupito vāyurapānastaṃ malamupacitamadhogatamāsādya gudavalīṣvādhatte tatastāsvabhiṣyaṇṇāsvarśāṃsi sambhavanti" },
      { type: "verse", number: "7", sanskrit: "तेषां पूर्वरूपाणि कृच्छ्रात् पक्तिरान्त्रकूजनमुद्गारबाहुल्यमम्लको ऽन्नाश्रद्धाविष्टम्भोश्मगर्भाभनाभित्वमाटोपो ऽधस्तात् कृच्छ्रेण सशब्दस्य च वायोः प्रवृत्तिर्बहुमूत्रत्वमल्पपुरीषता गुदपरिकर्तनं सक्थिरदनमक्ष्णोः श्वयथुरविमलेन्द्रियत्वमालस्यं तन्द्रा कार्श्यं दौर्बल्यमाशङ्का ग्रहणीदोषशोफोदरपाण्डुरोगगुल्मेषु जातेषु चैतानि लिङ्गानि प्रव्यक्ततराणि भवन्ति", text: "teṣāṃ pūrvarūpāṇi kṛcchrāt paktirāntrakūjanamudgārabāhulyamamlako 'nnāśraddhāviṣṭambhośmagarbhābhanābhitvamāṭopo 'dhastāt kṛcchreṇa saśabdasya ca vāyoḥ pravṛttirbahumūtratvamalpapurīṣatā gudaparikartanaṃ sakthiradanamakṣṇoḥ śvayathuravimalendriyatvamālasyaṃ tandrā kārśyaṃ daurbalyamāśaṅkā grahaṇīdoṣaśophodarapāṇḍurogagulmeṣu jāteṣu caitāni liṅgāni pravyaktatarāṇi bhavanti" },
      { type: "verse", number: "8", sanskrit: "तैः खल्वधोमार्गोपरोधाद्वायुरपानो निवर्तमानः समानव्यानोदानप्राणान् पित्तश्लेष्माणौ च प्रकोपयन्नन लमुपमृद्नाति", text: "taiḥ khalvadhomārgoparodhādvāyurapāno nivartamānaḥ samānavyānodānaprāṇān pittaśleṣmāṇau ca prakopayannana lamupamṛdnāti" },
      { type: "verse", number: "9", sanskrit: "अथ सर्व एवार्शसो भवत्यतिकृशो विवर्णः क्षामो दीनः प्रचुरविबद्धवातमूत्रपुरीषो ऽश्मरीशर्करावाननियतविबद्धमुक्तामपक्वभिन्नशुष्कवर्चास्तथान्तराश्वेतपाण्डुहरितपीतरक्तारुणतनुसान्द्रीपच्छिलोपवेशी नाभिवङ्क्षणोद्देशप्रचुरपरिकर्तिकान्वितः सगुदशूलप्रवाहिकाप्रहर्षप्रमोहो ऽल्पशुक्रप्रजो ऽल्पभुक् सिरासन्ततगात्रः क्रोधनो दुरुपचारः क्रोधनो दुरुपचारः कासश्वासपीनसतृष्णारोचकपाणिपादवदनाक्षिकूटश्चयथुक्षवथुवेपथुवमथुपरीतस्तैमिरिकः शिरःशूली क्षामभिन्नस्वरः कर्णरोगी सज्वरः साङ्गमर्दः सर्वपर्वास्थिशूलो ऽन्तरान्तरा हृदयकुक्षिपार्श्वपृष्ठबस्तित्रिकग्रहोपतप्तः प्रध्यानपरः परमलसश्च", text: "atha sarva evārśaso bhavatyatikṛśo vivarṇaḥ kṣāmo dīnaḥ pracuravibaddhavātamūtrapurīṣo 'śmarīśarkarāvānaniyatavibaddhamuktāmapakvabhinnaśuṣkavarcāstathāntarāśvetapāṇḍuharitapītaraktāruṇatanusāndrīpacchilopaveśī nābhivaṅkṣaṇoddeśapracuraparikartikānvitaḥ sagudaśūlapravāhikāpraharṣapramoho 'lpaśukraprajo 'lpabhuk sirāsantatagātraḥ krodhano durupacāraḥ krodhano durupacāraḥ kāsaśvāsapīnasatṛṣṇārocakapāṇipādavadanākṣikūṭaścayathukṣavathuvepathuvamathuparītastaimirikaḥ śiraḥśūlī kṣāmabhinnasvaraḥ karṇarogī sajvaraḥ sāṅgamardaḥ sarvaparvāsthiśūlo 'ntarāntarā hṛdayakukṣipārśvapṛṣṭhabastitrikagrahopataptaḥ pradhyānaparaḥ paramalasaśca" },
      { type: "verse", number: "10", sanskrit: "तत्र वातोल्बणानि शुष्कम्लानकठिनपरुषरूक्षश्यावारुणानि तीक्ष्णस्फुटितमुखानि विषममध्यानि कदम्ब पुष्पतुण्डिकेरीकर्कन्धुसिद्धार्थविम्बीखर्जूरफलप्रमाणानि वक्राणि मिथो विसदृशानि कटीपार्श्वादिष्वधिकवेदनानि सशूलोदावर्तकराणि गुल्माष्ठीलाप्लीहोदराणि चास्य तन्निमित्तान्येव कृष्णत्वङ्नखनयनवदनमलाश्च भवन्ति", text: "tatra vātolbaṇāni śuṣkamlānakaṭhinaparuṣarūkṣaśyāvāruṇāni tīkṣṇasphuṭitamukhāni viṣamamadhyāni kadamba puṣpatuṇḍikerīkarkandhusiddhārthavimbīkharjūraphalapramāṇāni vakrāṇi mitho visadṛśāni kaṭīpārśvādiṣvadhikavedanāni saśūlodāvartakarāṇi gulmāṣṭhīlāplīhodarāṇi cāsya tannimittānyeva kṛṣṇatvaṅnakhanayanavadanamalāśca bhavanti" },
      { type: "verse", number: "11", sanskrit: "पित्तोल्बणानि नीलाग्राणि रक्तपीतकृष्णानि मृदुशिथिलानि स्पर्शासहानि विस्रगन्धीनि तनूनि तनुरक्तस्रावीणि दाहपाकवन्ति ज्वरमोहारुचिकराणि यकृत्प्रकाशानि शुकजिह्वाजलौकावक्त्रसदृशानि यवमध्यानि प्रक्लिन्नानि भिन्नपीतवर्चांसि हारिद्रत्वङ्नखादिकराणि च", text: "pittolbaṇāni nīlāgrāṇi raktapītakṛṣṇāni mṛduśithilāni sparśāsahāni visragandhīni tanūni tanuraktasrāvīṇi dāhapākavanti jvaramohārucikarāṇi yakṛtprakāśāni śukajihvājalaukāvaktrasadṛśāni yavamadhyāni praklinnāni bhinnapītavarcāṃsi hāridratvaṅnakhādikarāṇi ca" },
      { type: "verse", number: "12", sanskrit: "श्लेष्मोल्बणानि महामूलानि स्थिरस्निग्धपाण्डुवृत्तोपचितानि गुरुस्तब्धश्लक्ष्णपिच्छिलानि सुप्तसुप्तानि स्पर्शक्षमाणि करीरपनसास्थिगोस्तनाकाराण्यतिमात्रोत्थानप्रवाहिकावङ्क्षणानाहनाभिपरिकर्तिकाहृल्लासप्रसके कासश्वासपीनसारुचिच्छर्दिकृछ्रमूत्रप्रमेहशीतज्वरशोफशिरोगौरवेन्द्रियोपलेपाग्निमार्दवक्लैब्यामविकारप्रबलानि न भिद्यन्ते न स्रवन्ति कण्डूबहुलानि सश्लेष्मवसाप्रकाशातिमलोपवेशीनि शुक्लत्वङ्नखादि कराणिच लक्षणसङ्करात् संसर्गसन्निपातजानि विभजेत्", text: "śleṣmolbaṇāni mahāmūlāni sthirasnigdhapāṇḍuvṛttopacitāni gurustabdhaślakṣṇapicchilāni suptasuptāni sparśakṣamāṇi karīrapanasāsthigostanākārāṇyatimātrotthānapravāhikāvaṅkṣaṇānāhanābhiparikartikāhṛllāsaprasake kāsaśvāsapīnasārucicchardikṛchramūtrapramehaśītajvaraśophaśirogauravendriyopalepāgnimārdavaklaibyāmavikāraprabalāni na bhidyante na sravanti kaṇḍūbahulāni saśleṣmavasāprakāśātimalopaveśīni śuklatvaṅnakhādi karāṇica lakṣaṇasaṅkarāt saṃsargasannipātajāni vibhajet" },
      { type: "verse", number: "13", sanskrit: "रक्तोल्बणानि तु वटप्ररोहविद्रुमकाकनन्दिकाफलाभानि पित्तलक्षणानि च तथा गाढपुरीषप्रतिपीडितान्यत्यर्थं दुष्टमुष्णमसृक् सहसा विसृजन्ति तस्यातिप्रवृत्तौ रक्तक्षयोपद्रवा भवन्तीति भवति चात्र श्लोकः", text: "raktolbaṇāni tu vaṭaprarohavidrumakākanandikāphalābhāni pittalakṣaṇāni ca tathā gāḍhapurīṣapratipīḍitānyatyarthaṃ duṣṭamuṣṇamasṛk sahasā visṛjanti tasyātipravṛttau raktakṣayopadravā bhavantīti bhavati cātra ślokaḥ" },
      { type: "verse", number: "14", sanskrit: "मुद्गकोद्रवजूर्णाह्वकरीरचणकादिभिः रूक्षैः सङ्ग्राहिभिर्वायुः स्वे स्थाने कुपितो बली", text: "mudgakodravajūrṇāhvakarīracaṇakādibhiḥ rūkṣaiḥ saṅgrāhibhirvāyuḥ sve sthāne kupito balī" },
      { type: "verse", number: "15", sanskrit: "अधोवहानि स्रोतांसि संस्रुध्याधः प्रशोषयन् पुरीषं वातविण्मूत्रसङ्गं कुर्वीत दारुणम्", text: "adhovahāni srotāṃsi saṃsrudhyādhaḥ praśoṣayan purīṣaṃ vātaviṇmūtrasaṅgaṃ kurvīta dāruṇam" },
      { type: "verse", number: "16", sanskrit: "तेन तीव्ररुजा कोष्ठपृष्ठहृत्पार्श्वगा भवेत् आध्मानमुदरावेष्टो हृल्लासः परिकर्तनम्", text: "tena tīvrarujā koṣṭhapṛṣṭhahṛtpārśvagā bhavet ādhmānamudarāveṣṭo hṛllāsaḥ parikartanam" },
      { type: "verse", number: "17", sanskrit: "बस्तौ च सुतरां शूलं गण्डे श्वयथुसम्भवः पवनस्योर्ध्वगामित्वं ततश्छर्द्यरुचिज्वराः", text: "bastau ca sutarāṃ śūlaṃ gaṇḍe śvayathusambhavaḥ pavanasyordhvagāmitvaṃ tataśchardyarucijvarāḥ" },
      { type: "verse", number: "18", sanskrit: "हृद्रोगग्रहणीदोषमूत्रसङ्गप्रवाहिकाः बाधिर्यतिमिरश्वासशिरोरुक्कासपीनसाः", text: "hṛdrogagrahaṇīdoṣamūtrasaṅgapravāhikāḥ bādhiryatimiraśvāsaśirorukkāsapīnasāḥ" },
      { type: "verse", number: "19", sanskrit: "मनोविकारस्तृष्णास्रपित्तगुल्मोदरादयः ते ते च वातजा रोगा जायन्ते भृशदारुणाः", text: "manovikārastṛṣṇāsrapittagulmodarādayaḥ te te ca vātajā rogā jāyante bhṛśadāruṇāḥ" },
      { type: "verse", number: "20", sanskrit: "दुर्नाम्नामित्युदावर्तः परमो ऽयमुपद्रवः वाताभिभूतकोष्ठानां तैर्विनापि स जायते", text: "durnāmnāmityudāvartaḥ paramo 'yamupadravaḥ vātābhibhūtakoṣṭhānāṃ tairvināpi sa jāyate" },
      { type: "verse", number: "21", sanskrit: "सहजानि त्रिदोषाणि यानि चाभ्यन्तरे बलौ स्थितानि तान्यसाध्यनि याप्यन्तेग्निबलादिभिः", text: "sahajāni tridoṣāṇi yāni cābhyantare balau sthitāni tānyasādhyani yāpyantegnibalādibhiḥ" },
      { type: "verse", number: "22", sanskrit: "द्वन्द्वजानि द्वितीयायां बलौ यान्याश्रितानि च कृच्छ्रसाध्यानि तान्याहुः परिसंवत्सराणि च", text: "dvandvajāni dvitīyāyāṃ balau yānyāśritāni ca kṛcchrasādhyāni tānyāhuḥ parisaṃvatsarāṇi ca" },
      { type: "verse", number: "23", sanskrit: "बाह्यायां तु बलौ जातान्येकदोषोल्बणानि च अर्शांसि सुखसाध्यानि नचिरोत्पतितानि च", text: "bāhyāyāṃ tu balau jātānyekadoṣolbaṇāni ca arśāṃsi sukhasādhyāni nacirotpatitāni ca" },
      { type: "verse", number: "24", sanskrit: "मेढ्रादिष्वपि वक्ष्यन्ते यथास्वं नाभिजानि तु गण्डूपदास्यरूपाणि पिच्छिलानि मृदूनि च", text: "meḍhrādiṣvapi vakṣyante yathāsvaṃ nābhijāni tu gaṇḍūpadāsyarūpāṇi picchilāni mṛdūni ca" },
      { type: "verse", number: "25", sanskrit: "व्यानो गृहीत्वा श्लेष्माणं करोत्यर्शस्त्वचो बहिः कीलोपमं स्थिरखरं चर्मकीलं तु तं विदुः", text: "vyāno gṛhītvā śleṣmāṇaṃ karotyarśastvaco bahiḥ kīlopamaṃ sthirakharaṃ carmakīlaṃ tu taṃ viduḥ" },
      { type: "verse", number: "26", sanskrit: "वातेन तोदपारुष्यं पित्तादसितरक्तता श्लेष्मणा स्निग्धता तस्य ग्रथितत्वं सवर्णता", text: "vātena todapāruṣyaṃ pittādasitaraktatā śleṣmaṇā snigdhatā tasya grathitatvaṃ savarṇatā" },
      { type: "verse", number: "27", sanskrit: "अर्शसां प्रशमे यत्नमाशु कुर्वीत बुद्धिमान् तान्याशु हि गुदं बध्वा कुर्युर्बद्धगुदोदरम्", text: "arśasāṃ praśame yatnamāśu kurvīta buddhimān tānyāśu hi gudaṃ badhvā kuryurbaddhagudodaram" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 8,
    lang: "sa",
    content: [
      { type: "heading", heading: "Аршас нидана — геморрой" },
      { type: "text", text: "Глава 8 Нидана стханы — диагностический раздел о геморрой. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातो ऽतीसारग्रहणीदोषनिदानं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto 'tīsāragrahaṇīdoṣanidānaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अतीसारः स सुतरां जायते ऽत्यम्बुपानतः", text: "atīsāraḥ sa sutarāṃ jāyate 'tyambupānataḥ" },
      { type: "verse", number: "3", sanskrit: "कृशशुष्कामिषासात्म्यतिलपिष्टविरूढकः मद्यरूक्षातिमात्रान्नैरर्शोभिः स्नेहविभ्रमात्", text: "kṛśaśuṣkāmiṣāsātmyatilapiṣṭavirūḍhakaḥ madyarūkṣātimātrānnairarśobhiḥ snehavibhramāt" },
      { type: "verse", number: "4", sanskrit: "कृमिभ्यो वेगरोधाच्च तद्विधैः कुपितो ऽनिलः विस्रंसयत्यधोब्धातुं हत्वा तेनैव चानलम्", text: "kṛmibhyo vegarodhācca tadvidhaiḥ kupito 'nilaḥ visraṃsayatyadhobdhātuṃ hatvā tenaiva cānalam" },
      { type: "verse", number: "5", sanskrit: "व्यापद्यानुशकृत् कोष्ठं पुरीषं द्रवतां नयन् प्रकल्पते ऽतिसाराय लक्षणं तस्य भाविनः", text: "vyāpadyānuśakṛt koṣṭhaṃ purīṣaṃ dravatāṃ nayan prakalpate 'tisārāya lakṣaṇaṃ tasya bhāvinaḥ" },
      { type: "verse", number: "6", sanskrit: "तोदो हृद्गुदकोष्ठेषु गात्रसादो मलग्रहः आध्यानमविपाकश्च तत्र वातेन विज्जलम्", text: "todo hṛdgudakoṣṭheṣu gātrasādo malagrahaḥ ādhyānamavipākaśca tatra vātena vijjalam" },
      { type: "verse", number: "7", sanskrit: "अल्पाल्पं शब्दशूलाढ्यं विबद्धमुपवेश्यते रूक्षं सफेनमच्छं च ग्रथितं वा मुहुर्मुहुः", text: "alpālpaṃ śabdaśūlāḍhyaṃ vibaddhamupaveśyate rūkṣaṃ saphenamacchaṃ ca grathitaṃ vā muhurmuhuḥ" },
      { type: "verse", number: "8", sanskrit: "तथा दग्धगुडाभासं सपिच्छापरिकर्तिकम् शुष्कास्यो भ्रष्टपायुश्च हृष्टरोमा विनिष्टनन्", text: "tathā dagdhaguḍābhāsaṃ sapicchāparikartikam śuṣkāsyo bhraṣṭapāyuśca hṛṣṭaromā viniṣṭanan" },
      { type: "verse", number: "9", sanskrit: "पित्तेन पीतमसितं हारिद्रं शाद्वलप्रभम् सरक्तमतिदुर्गन्धं तृण्मूर्च्छास्वेददाहवान्", text: "pittena pītamasitaṃ hāridraṃ śādvalaprabham saraktamatidurgandhaṃ tṛṇmūrcchāsvedadāhavān" },
      { type: "verse", number: "10", sanskrit: "सशूलः पायुसन्तापपाकवान् श्लेष्मणा घनम् पिच्छिलं तन्तुमच्छ्वेतं स्निग्धमामं कफान्वितम्", text: "saśūlaḥ pāyusantāpapākavān śleṣmaṇā ghanam picchilaṃ tantumacchvetaṃ snigdhamāmaṃ kaphānvitam" },
      { type: "verse", number: "11", sanskrit: "अभीक्ष्णं गुरु दुर्गन्धं विबद्धमनुबद्धरुक् निद्रालुरलसो ऽन्नद्विडल्पाल्पं सप्रवाहिकम्", text: "abhīkṣṇaṃ guru durgandhaṃ vibaddhamanubaddharuk nidrāluralaso 'nnadviḍalpālpaṃ sapravāhikam" },
      { type: "verse", number: "12", sanskrit: "सरोमहर्षः सोत्क्लेशो गुरुबस्तिगुदोदरः कृते ऽप्यकृतसंज्ञश्च सर्वात्मा सर्वलक्षणः", text: "saromaharṣaḥ sotkleśo gurubastigudodaraḥ kṛte 'pyakṛtasaṃjñaśca sarvātmā sarvalakṣaṇaḥ" },
      { type: "verse", number: "13", sanskrit: "भयेन क्षोभिते चित्ते सपित्तो द्रावयेच्छकृत् वायुस्ततो ऽतिसार्येत क्षिप्रमुष्णं द्रवं प्लवम्", text: "bhayena kṣobhite citte sapitto drāvayecchakṛt vāyustato 'tisāryeta kṣipramuṣṇaṃ dravaṃ plavam" },
      { type: "verse", number: "14", sanskrit: "वातपित्तसमं लिङ्गैराहुस्तद्वच्च शोकतः अतीसारः समासेन द्वेधा सामो निरामकः", text: "vātapittasamaṃ liṅgairāhustadvacca śokataḥ atīsāraḥ samāsena dvedhā sāmo nirāmakaḥ" },
      { type: "verse", number: "15", sanskrit: "सासृङ्निरस्रस्तत्राद्ये गौरवादप्सु मज्जति शकृद्दुर्गन्धमाटोपविष्टम्भार्तिप्रसेकिनः", text: "sāsṛṅnirasrastatrādye gauravādapsu majjati śakṛddurgandhamāṭopaviṣṭambhārtiprasekinaḥ" },
      { type: "verse", number: "16", sanskrit: "विपरीतो निरामस्तु कफात् पक्वो ऽपि मज्जति", text: "viparīto nirāmastu kaphāt pakvo 'pi majjati" },
      { type: "verse", number: "17", sanskrit: "अतीसारेषु यो नातियत्नवान् ग्रहणीगदः तस्य स्यादग्निविध्वंसकरैरन्यस्य सेवितैः", text: "atīsāreṣu yo nātiyatnavān grahaṇīgadaḥ tasya syādagnividhvaṃsakarairanyasya sevitaiḥ" },
      { type: "verse", number: "18", sanskrit: "सामं शकृनिरामं वा जीर्णे येनातिसार्यते सो ऽतिसारो ऽतिसरणादाशुकारी स्वभावतः", text: "sāmaṃ śakṛnirāmaṃ vā jīrṇe yenātisāryate so 'tisāro 'tisaraṇādāśukārī svabhāvataḥ" },
      { type: "verse", number: "19", sanskrit: "सामं सान्नमजीर्णे ऽन्ने जीर्णे पक्वं तु नैव वा अकस्माद्वा मुहुर्बद्धमकस्माच्छिथिलं मुहुः", text: "sāmaṃ sānnamajīrṇe 'nne jīrṇe pakvaṃ tu naiva vā akasmādvā muhurbaddhamakasmācchithilaṃ muhuḥ" },
      { type: "verse", number: "20", sanskrit: "चिरकृद्ग्रहणीदोषः सञ्चयाच्चोपवेशयेत्", text: "cirakṛdgrahaṇīdoṣaḥ sañcayāccopaveśayet" },
      { type: "verse", number: "21", sanskrit: "स चतुर्धा पृथग्दोषैः सन्निपाताच्च जायते प्राग्रूपं तस्य सदनं चिरात् पचनमम्लकः", text: "sa caturdhā pṛthagdoṣaiḥ sannipātācca jāyate prāgrūpaṃ tasya sadanaṃ cirāt pacanamamlakaḥ" },
      { type: "verse", number: "22", sanskrit: "प्रसेको वक्त्रवैरस्यमरुचिस्तृट् क्लमो भ्रमः आनद्धोदरता छर्दिःकर्णक्ष्वेडान्त्रकूजनम्", text: "praseko vaktravairasyamarucistṛṭ klamo bhramaḥ ānaddhodaratā chardiḥkarṇakṣveḍāntrakūjanam" },
      { type: "verse", number: "23", sanskrit: "सामान्यलक्षणं कार्श्यं धूमकस्तमको ज्वरः मूर्छा शिरोरुग्विष्टम्भः श्वयथुः करपादयोः", text: "sāmānyalakṣaṇaṃ kārśyaṃ dhūmakastamako jvaraḥ mūrchā śirorugviṣṭambhaḥ śvayathuḥ karapādayoḥ" },
      { type: "verse", number: "24", sanskrit: "तत्रानिलात्तालुशोषस्तिमिरं कर्णयोः स्वनः पार्श्वोरुवङ्क्षणग्रीवारुजाभीक्ष्णं विषूचिका", text: "tatrānilāttāluśoṣastimiraṃ karṇayoḥ svanaḥ pārśvoruvaṅkṣaṇagrīvārujābhīkṣṇaṃ viṣūcikā" },
      { type: "verse", number: "25", sanskrit: "रसेषु गृद्धिः सर्वेषु क्षुत्तृष्णा परिकर्तिका जीर्णे जीर्यति चाध्मानं भुक्ते स्वास्थ्यं समश्नुते", text: "raseṣu gṛddhiḥ sarveṣu kṣuttṛṣṇā parikartikā jīrṇe jīryati cādhmānaṃ bhukte svāsthyaṃ samaśnute" },
      { type: "verse", number: "26", sanskrit: "वातहृद्रोगगुल्मार्शः प्लीहपाण्डुत्वशाङ्कितः चिराद्दुःखं द्रवं शुष्कः तन्वामं शब्दफेनवत्", text: "vātahṛdrogagulmārśaḥ plīhapāṇḍutvaśāṅkitaḥ cirādduḥkhaṃ dravaṃ śuṣkaḥ tanvāmaṃ śabdaphenavat" },
      { type: "verse", number: "27", sanskrit: "पुनःपुनः सृजेद्वर्चः पायुरुक्श्वासकासवान् पित्तेन नीलं पीताभं पीताभः सृजति द्रवम्", text: "punaḥpunaḥ sṛjedvarcaḥ pāyurukśvāsakāsavān pittena nīlaṃ pītābhaṃ pītābhaḥ sṛjati dravam" },
      { type: "verse", number: "28", sanskrit: "पूत्यम्लोद्गारहृत्कण्ठदाहारुचितृडर्दितः श्लेष्मणा पच्यते दुःखमन्नं छर्दिररोचकः", text: "pūtyamlodgārahṛtkaṇṭhadāhārucitṛḍarditaḥ śleṣmaṇā pacyate duḥkhamannaṃ chardirarocakaḥ" },
      { type: "verse", number: "29", sanskrit: "आस्योपदेहनिष्ठीवकासहृल्लासपीनसाः हृदयं मन्यते स्त्यानमुदरं स्तिमितं गुरु", text: "āsyopadehaniṣṭhīvakāsahṛllāsapīnasāḥ hṛdayaṃ manyate styānamudaraṃ stimitaṃ guru" },
      { type: "verse", number: "30", sanskrit: "उद्गारो दुष्टमधुरः सदनं स्त्रीष्वहर्षणम् भिन्नामश्लेष्मसंसृष्टगुरुवर्चःप्रवर्तनम्", text: "udgāro duṣṭamadhuraḥ sadanaṃ strīṣvaharṣaṇam bhinnāmaśleṣmasaṃsṛṣṭaguruvarcaḥpravartanam" },
      { type: "verse", number: "31", sanskrit: "अकृशस्यापि दौर्बल्यं सर्वजे सर्वसङ्करः", text: "akṛśasyāpi daurbalyaṃ sarvaje sarvasaṅkaraḥ" },
      { type: "verse", number: "32", sanskrit: "सिराविभागे ये चोक्ता विषमाद्यास्त्रयो ऽग्नयः ते ऽपि स्युर्ग्रहणीदोषाः समस्तु स्वास्थ्यकारणम्", text: "sirāvibhāge ye coktā viṣamādyāstrayo 'gnayaḥ te 'pi syurgrahaṇīdoṣāḥ samastu svāsthyakāraṇam" },
      { type: "verse", number: "33", sanskrit: "वातव्याध्यश्मरीकुष्ठमेहोदरभगन्दराः अर्शासि ग्रहणीत्यष्टौ महारोगाः सुदुस्तराः", text: "vātavyādhyaśmarīkuṣṭhamehodarabhagandarāḥ arśāsi grahaṇītyaṣṭau mahārogāḥ sudustarāḥ" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 9,
    lang: "sa",
    content: [
      { type: "heading", heading: "Видрадхи нидана — абсцессы" },
      { type: "text", text: "Глава 9 Нидана стханы — диагностический раздел о абсцессы. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातो मूत्रघातनिदानं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto mūtraghātanidānaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "विंशतिर्मूत्राघाता भवन्ति तद्यथा वातपित्तकफसन्निपातकृच्छ्राणि वातपित्तश्लेष्मशुक्राश्मर्यः वातबस्त्यष्ठीलाकुण्डलिकामूत्रातीतजठरोत्सङ्गग्रन्थिशुक्रविड्विघातोष्णवातमूत्रक्षयावसादाश्चेति", text: "viṃśatirmūtrāghātā bhavanti tadyathā vātapittakaphasannipātakṛcchrāṇi vātapittaśleṣmaśukrāśmaryaḥ vātabastyaṣṭhīlākuṇḍalikāmūtrātītajaṭharotsaṅgagranthiśukraviḍvighātoṣṇavātamūtrakṣayāvasādāśceti" },
      { type: "verse", number: "3", sanskrit: "तत्र वातबस्त्यादयो नव वातोल्बणाः ततो द्वौ वातपित्तोल्बणौ अन्त्यः कफपित्तोल्बणः", text: "tatra vātabastyādayo nava vātolbaṇāḥ tato dvau vātapittolbaṇau antyaḥ kaphapittolbaṇaḥ" },
      { type: "verse", number: "4", sanskrit: "सर्वेषां पुनर्मूत्ररोगाणामधिष्ठानं बस्तिः स मर्मस्वभिहितः प्राक् स चाधोमुखो ऽपि मूत्रवहासु नाडिषु सूक्ष्ममुखसहस्रनिष्यन्देन मूत्राख्येनाविरतं नवो घट इवाप्सु निमग्नमुखोपि पार्श्वेभ्यो ऽम्भसापूर्यते तैरेव च स्रोतोभिर्वातादयो ऽपि दुष्टाः प्रविश्य बस्तिं यथास्वमाघातान् प्रमेहांश्च जनयन्ति", text: "sarveṣāṃ punarmūtrarogāṇāmadhiṣṭhānaṃ bastiḥ sa marmasvabhihitaḥ prāk sa cādhomukho 'pi mūtravahāsu nāḍiṣu sūkṣmamukhasahasraniṣyandena mūtrākhyenāvirataṃ navo ghaṭa ivāpsu nimagnamukhopi pārśvebhyo 'mbhasāpūryate taireva ca srotobhirvātādayo 'pi duṣṭāḥ praviśya bastiṃ yathāsvamāghātān pramehāṃśca janayanti" },
      { type: "verse", number: "5", sanskrit: "तत्राल्पशो मुहुर्मुहुर्बस्तिमेढ्रवङ्क्षणेषु तीव्रशूलः कृच्छ्रान्मूत्रयति वातकृच्छ्रे सदाहं सरुजं रक्तं पीतं कृष्णं वा पित्तकृच्छ्रे बस्तिमेढ्रयोर्गौरवं शोफो मूत्रं च सपिच्छं मेहति कफकृच्छ्रे सर्वलक्षणसन्निपातेन सन्निपातकृच्छ्रे स च कृच्छ्रतमः", text: "tatrālpaśo muhurmuhurbastimeḍhravaṅkṣaṇeṣu tīvraśūlaḥ kṛcchrānmūtrayati vātakṛcchre sadāhaṃ sarujaṃ raktaṃ pītaṃ kṛṣṇaṃ vā pittakṛcchre bastimeḍhrayorgauravaṃ śopho mūtraṃ ca sapicchaṃ mehati kaphakṛcchre sarvalakṣaṇasannipātena sannipātakṛcchre sa ca kṛcchratamaḥ" },
      { type: "verse", number: "6", sanskrit: "यदा तु वायुर्बस्तिमुखमावृत्य सपित्तं सकफं सशुक्रं वा मूत्रं परिशोषयति तदा क्रमेण गोरिव पित्ताद्रोचना मणिकस्येव स्वच्छादपि जलात् पङ्कस्तद्वदश्मर्यभिनिर्वर्तते सर्वा च सा श्लेष्माश्रया अथास्याः पूर्वरूपाणि ज्वरो बस्त्याध्मानमरुचिर्मूत्रकृच्छ्रं बस्तिशिरोमुष्कशेफसां देवना बस्तगन्धित्वं मूत्रस्येति", text: "yadā tu vāyurbastimukhamāvṛtya sapittaṃ sakaphaṃ saśukraṃ vā mūtraṃ pariśoṣayati tadā krameṇa goriva pittādrocanā maṇikasyeva svacchādapi jalāt paṅkastadvadaśmaryabhinirvartate sarvā ca sā śleṣmāśrayā athāsyāḥ pūrvarūpāṇi jvaro bastyādhmānamarucirmūtrakṛcchraṃ bastiśiromuṣkaśephasāṃ devanā bastagandhitvaṃ mūtrasyeti" },
      { type: "verse", number: "7", sanskrit: "सामान्यलिङ्गानि तु नाभिबस्तिमेवनीषु मेहतस्तया मार्गनिरोधने वेदना मूत्रधारासङ्गस्तद्व्यपाये च गोमेदकप्रकाशमनाविलमसितं सुसुखं मूत्रं विसृजति तत्सङ्क्षोभणाच्च सरुधिरम् धावनलङ्घनादिभिश्चास्य विविधा वेदना भवन्ति यथैव च पक्वाशयात् स्रस्तेन शकृताधिष्ठिते बस्तौ मूत्रं न प्रवर्तते तहाश्मर्यापि", text: "sāmānyaliṅgāni tu nābhibastimevanīṣu mehatastayā mārganirodhane vedanā mūtradhārāsaṅgastadvyapāye ca gomedakaprakāśamanāvilamasitaṃ susukhaṃ mūtraṃ visṛjati tatsaṅkṣobhaṇācca sarudhiram dhāvanalaṅghanādibhiścāsya vividhā vedanā bhavanti yathaiva ca pakvāśayāt srastena śakṛtādhiṣṭhite bastau mūtraṃ na pravartate tahāśmaryāpi" },
      { type: "verse", number: "8", sanskrit: "तत्र वायुना बस्तिसेवनीमेहनेषु तीव्रवेदनार्दितो दन्तान् खादति नाभिं प्रपीडयति मेढ्रं मृद्नाति मुहुर्मुहुर्वेपथुमान् कृच्छ्रात्सवातं शकृद्विमुञ्चति विशीर्णधारं च मूत्रयत्यश्मरी चास्य श्यावा परुषा विषमा कदम्बपुष्पवत् कण्टकाचिता भवति पित्तेन पच्यमान इव दह्यते बस्तिः अश्मरी च रक्ता पीतावभासा कृष्णा भल्लातकास्थिसंस्थाना श्लेष्मणा भिद्यते निस्तुद्यत इव गुरुः शीतश्च बस्तिरश्मरी च श्वेता महती कुक्कुटाण्डप्रतिमा मधुवर्णा वा भवति प्रायेणैतास्तिस्रो ऽश्मर्यो बालानां जायन्ते तेषामेव चाल्पबस्तित्वादल्पमांसोपचयत्वाच्च सुखग्रहणाहरणा भवन्ति", text: "tatra vāyunā bastisevanīmehaneṣu tīvravedanārdito dantān khādati nābhiṃ prapīḍayati meḍhraṃ mṛdnāti muhurmuhurvepathumān kṛcchrātsavātaṃ śakṛdvimuñcati viśīrṇadhāraṃ ca mūtrayatyaśmarī cāsya śyāvā paruṣā viṣamā kadambapuṣpavat kaṇṭakācitā bhavati pittena pacyamāna iva dahyate bastiḥ aśmarī ca raktā pītāvabhāsā kṛṣṇā bhallātakāsthisaṃsthānā śleṣmaṇā bhidyate nistudyata iva guruḥ śītaśca bastiraśmarī ca śvetā mahatī kukkuṭāṇḍapratimā madhuvarṇā vā bhavati prāyeṇaitāstisro 'śmaryo bālānāṃ jāyante teṣāmeva cālpabastitvādalpamāṃsopacayatvācca sukhagrahaṇāharaṇā bhavanti" },
      { type: "verse", number: "9", sanskrit: "महतां तु शुक्राश्मरी शुक्रनिमित्ता भवति मैथुनविघाताच्छुक्रमुपस्थितमनिरस्यमानं विमार्गगमनिलो विगृह्य वृषणयोरन्तरे संहरति संहृत्योपशोषयति ततः शुष्कमश्मरी भवति सा शुक्रमार्गमावृणोति मूत्रकृच्छ्रं बस्तिवेदनां वृषणयोश्च श्वयथुमापादयति उत्पन्नमात्रायां च शुक्रं निरेति प्रपीडितमात्रे च तस्मिन्नेवावकाशे विलीयत इति", text: "mahatāṃ tu śukrāśmarī śukranimittā bhavati maithunavighātācchukramupasthitamanirasyamānaṃ vimārgagamanilo vigṛhya vṛṣaṇayorantare saṃharati saṃhṛtyopaśoṣayati tataḥ śuṣkamaśmarī bhavati sā śukramārgamāvṛṇoti mūtrakṛcchraṃ bastivedanāṃ vṛṣaṇayośca śvayathumāpādayati utpannamātrāyāṃ ca śukraṃ nireti prapīḍitamātre ca tasminnevāvakāśe vilīyata iti" },
      { type: "verse", number: "10", sanskrit: "अश्मर्येव तु वायुनाअणुशो विभिन्ना शर्करेत्युच्यते अनुलोमे च मारुते सा सिकतेव मूत्रेण सह च्यवते", text: "aśmaryeva tu vāyunāaṇuśo vibhinnā śarkaretyucyate anulome ca mārute sā sikateva mūtreṇa saha cyavate" },
      { type: "verse", number: "11", sanskrit: "वायुस्तु मूत्रवेगरोधाद्बस्तिमुखमावृणोति ततो मूत्रसङ्गं वेदनां कण्डूं च करोति कदाचिच्च बस्तिं स्वस्थानात् प्रच्याव्य गर्भमिवोद्वृत्तं स्थूलं परिप्लुतं च कुरुते तत्र शूलस्पन्दनदाहोद्वेष्टनानि बिन्दुशश्च मूत्रस्रवणम् पीडिते च बस्तौ धारया प्रवृत्तिरयं द्विविधो ऽपि वातबस्तिः कृच्छ्रसाध्यः तयोरपि द्वितीयो ऽनिलप्रबलः कृच्छ्रसाध्यतरः", text: "vāyustu mūtravegarodhādbastimukhamāvṛṇoti tato mūtrasaṅgaṃ vedanāṃ kaṇḍūṃ ca karoti kadācicca bastiṃ svasthānāt pracyāvya garbhamivodvṛttaṃ sthūlaṃ pariplutaṃ ca kurute tatra śūlaspandanadāhodveṣṭanāni binduśaśca mūtrasravaṇam pīḍite ca bastau dhārayā pravṛttirayaṃ dvividho 'pi vātabastiḥ kṛcchrasādhyaḥ tayorapi dvitīyo 'nilaprabalaḥ kṛcchrasādhyataraḥ" },
      { type: "verse", number: "12", sanskrit: "बस्तिविण्मार्गान्तरे वायुर्घनोन्नतं तीव्ररुजमचलमष्ठीलाभं ग्रन्थिं करोति तेनानिलविण्मूत्रसङ्गो भवत्याध्मानं च सा वाताष्ठीला विगुणो वायुः बस्तौ कुण्डलीभूतस्तीव्रशूलस्तम्भगौरवान्वितो मूत्रमाविध्याल्पशो वा प्रवर्तयन् भ्रमति सा वातकुण्डलिका मूत्रमतिवेलं विधार्य विमुच्यमानं न प्रवर्तते वाहमानस्य तु कृच्छ्रादल्पं प्रवर्तते तन्मूत्रातीतम्", text: "bastiviṇmārgāntare vāyurghanonnataṃ tīvrarujamacalamaṣṭhīlābhaṃ granthiṃ karoti tenānilaviṇmūtrasaṅgo bhavatyādhmānaṃ ca sā vātāṣṭhīlā viguṇo vāyuḥ bastau kuṇḍalībhūtastīvraśūlastambhagauravānvito mūtramāvidhyālpaśo vā pravartayan bhramati sā vātakuṇḍalikā mūtramativelaṃ vidhārya vimucyamānaṃ na pravartate vāhamānasya tu kṛcchrādalpaṃ pravartate tanmūtrātītam" },
      { type: "verse", number: "13", sanskrit: "मूत्ररोधादपानो वायुर्नाभेरधस्तात्तीव्ररुजमाध्मानं मलसङ्गं च कुर्वन्नुदरमभिपूरयेत् तन्मूत्रजठरम् मारुतेनाक्षिप्तं छिद्रवैगुण्येन वा मूत्रयतो मूत्रमल्पं बस्तौ नाले मणौ वा स्थित्वा तच्छेषगुरुमेढ्रस्य सरुजमरुजं वा शनैः स्रवेत् स मूत्रोत्सङ्गः बस्तिद्वारे ऽल्पो वृत्तः शीघ्रसम्भवो ऽश्मरीतुल्यलिङ्गो मूत्रग्रन्थिः", text: "mūtrarodhādapāno vāyurnābheradhastāttīvrarujamādhmānaṃ malasaṅgaṃ ca kurvannudaramabhipūrayet tanmūtrajaṭharam mārutenākṣiptaṃ chidravaiguṇyena vā mūtrayato mūtramalpaṃ bastau nāle maṇau vā sthitvā taccheṣagurumeḍhrasya sarujamarujaṃ vā śanaiḥ sravet sa mūtrotsaṅgaḥ bastidvāre 'lpo vṛttaḥ śīghrasambhavo 'śmarītulyaliṅgo mūtragranthiḥ" },
      { type: "verse", number: "14", sanskrit: "मूत्रितस्य व्यवायगमनाद्वातोद्धतं स्वस्थानाच्च्युतं शुक्रं मेहतो मूत्रस्य प्राक् पश्चाद्वा भस्मोदकसङ्काशं प्रवर्तते तन्मूत्रशुक्रम् वायुना पीडितं शकृन्मूत्रस्रोतः प्रपद्यते ततो विट्गन्धि विट्संसृष्टं च कृच्छान्मूत्रयति स विड्विघातः अत्यध्वातपोष्णभोजनादिभिः पित्तं प्रवृद्धमनिलेरितं बस्तिमेढ्रगुददाहं कुर्वद्धरितहारिद्रक्तं सरक्तं वा मूत्रं कृछ्रात् प्रवर्तयेत् स तूष्णवातः वातपित्तं बस्तिमाश्रित्य मूत्रं सशूलदाहं क्षपयति स मूत्रक्षयः पित्तं श्लेष्मोभयमपि वा वातेन बस्तौ संहन्यते ततो मूत्रं सदाहं सरक्तं पीतं श्वेतं सान्द्रं कृच्छ्रप्रवृत्ति शुष्कं च शङ्खरोचनान्यतरचूर्णवर्णं सर्ववर्णयुक्तं वा भवति स मूत्रावसादः", text: "mūtritasya vyavāyagamanādvātoddhataṃ svasthānāccyutaṃ śukraṃ mehato mūtrasya prāk paścādvā bhasmodakasaṅkāśaṃ pravartate tanmūtraśukram vāyunā pīḍitaṃ śakṛnmūtrasrotaḥ prapadyate tato viṭgandhi viṭsaṃsṛṣṭaṃ ca kṛcchānmūtrayati sa viḍvighātaḥ atyadhvātapoṣṇabhojanādibhiḥ pittaṃ pravṛddhamanileritaṃ bastimeḍhragudadāhaṃ kurvaddharitahāridraktaṃ saraktaṃ vā mūtraṃ kṛchrāt pravartayet sa tūṣṇavātaḥ vātapittaṃ bastimāśritya mūtraṃ saśūladāhaṃ kṣapayati sa mūtrakṣayaḥ pittaṃ śleṣmobhayamapi vā vātena bastau saṃhanyate tato mūtraṃ sadāhaṃ saraktaṃ pītaṃ śvetaṃ sāndraṃ kṛcchrapravṛtti śuṣkaṃ ca śaṅkharocanānyataracūrṇavarṇaṃ sarvavarṇayuktaṃ vā bhavati sa mūtrāvasādaḥ" },
      { type: "verse", number: "15", sanskrit: "इति विस्तरतः प्रोक्ता रोगा मूत्राप्रवृत्तिजाः निदानलक्षणैरूर्ध्वं वक्ष्यन्ते ऽतिप्रवृत्तिजाः", text: "iti vistarataḥ proktā rogā mūtrāpravṛttijāḥ nidānalakṣaṇairūrdhvaṃ vakṣyante 'tipravṛttijāḥ" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 10,
    lang: "sa",
    content: [
      { type: "heading", heading: "Вата вьядхи нидана — болезни Ваты" },
      { type: "text", text: "Глава 10 Нидана стханы — диагностический раздел о болезни Ваты. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातः प्रमेहनिदानं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ pramehanidānaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "विंशतिः प्रमेहा भवन्ति तद्यथा कफादुदकेक्षुसान्द्रसुरापिष्टशुक्रसिकताशीतशनैर्लालाप्रमेहाः दश पित्तात् क्षारकालनीलहारिद्रमाञ्जिष्ठशोणितमेहाः षट् वाताद्वसामज्जहस्तिमधुमेहाश्चत्वार इति", text: "viṃśatiḥ pramehā bhavanti tadyathā kaphādudakekṣusāndrasurāpiṣṭaśukrasikatāśītaśanairlālāpramehāḥ daśa pittāt kṣārakālanīlahāridramāñjiṣṭhaśoṇitamehāḥ ṣaṭ vātādvasāmajjahastimadhumehāścatvāra iti" },
      { type: "verse", number: "3", sanskrit: "तेषां यत्किञ्चिदाहारविहारजातं श्लेष्ममेदोमूत्रजननं स हेतुः तत्र वातपित्तमेदःक्लेदमांसशुक्ररसैरन्वितो बस्तिगतः श्लेष्मा प्रमेहान् जनयति तैः कफशोणिताभ्यां च युक्तं पित्तम् तैर्वसालसीकामज्जौजोभिश्च वायुः", text: "teṣāṃ yatkiñcidāhāravihārajātaṃ śleṣmamedomūtrajananaṃ sa hetuḥ tatra vātapittamedaḥkledamāṃsaśukrarasairanvito bastigataḥ śleṣmā pramehān janayati taiḥ kaphaśoṇitābhyāṃ ca yuktaṃ pittam tairvasālasīkāmajjaujobhiśca vāyuḥ" },
      { type: "verse", number: "4", sanskrit: "त्रयाणामपि दोषाणां श्लेष्मा प्रमेहेषु प्राक् प्रकोपमापद्यते श्लेष्माधिष्ठानत्वान्मूत्रस्य तद्वृद्धेर्मेद एव च तेन प्रथमं दूष्यते ऽत्यन्तसभागत्वात् तदनन्तरं देहक्लेदादयः ततः श्लेष्मादिक्षये पित्तं प्रबलीभवच्छोणितमपि दूषयति तत्क्षये ऽपि वायुर्वसादीन् धातून् शरीरस्य परमसारभूतान् बस्तिमाकृष्य मूत्रेण सह विसृजति", text: "trayāṇāmapi doṣāṇāṃ śleṣmā prameheṣu prāk prakopamāpadyate śleṣmādhiṣṭhānatvānmūtrasya tadvṛddhermeda eva ca tena prathamaṃ dūṣyate 'tyantasabhāgatvāt tadanantaraṃ dehakledādayaḥ tataḥ śleṣmādikṣaye pittaṃ prabalībhavacchoṇitamapi dūṣayati tatkṣaye 'pi vāyurvasādīn dhātūn śarīrasya paramasārabhūtān bastimākṛṣya mūtreṇa saha visṛjati" },
      { type: "verse", number: "5", sanskrit: "तस्मात् कफपित्तवातजाः क्रमेण साध्ययाप्यासाध्याः तथा पित्तजाः संसृष्टदोषमेदःस्थानत्वाद्विरुद्धोपक्रमत्वाच्च वातजः पुनः क्षीणेषु धातुषु महात्ययतया विरुद्धोपक्रमत्वाच्च मेदसि तु नातिदुष्टे पित्तजा अपि साध्यतां गच्छेयुः", text: "tasmāt kaphapittavātajāḥ krameṇa sādhyayāpyāsādhyāḥ tathā pittajāḥ saṃsṛṣṭadoṣamedaḥsthānatvādviruddhopakramatvācca vātajaḥ punaḥ kṣīṇeṣu dhātuṣu mahātyayatayā viruddhopakramatvācca medasi tu nātiduṣṭe pittajā api sādhyatāṃ gaccheyuḥ" },
      { type: "verse", number: "6", sanskrit: "धातुसम्पर्कात् पुनः सर्वमेहेषु मूत्रमाविलं भूरि च भवति दोषाणां दूष्याणां चोत्कृष्टापकृष्टसंयोगेन मूत्रवर्णरसस्पर्शगन्धविशेषाद्वर्णानामिव शुक्लकृष्णादीनां शबलकल्माषादयः प्रमेहाणां प्रभेदा भवन्ति", text: "dhātusamparkāt punaḥ sarvameheṣu mūtramāvilaṃ bhūri ca bhavati doṣāṇāṃ dūṣyāṇāṃ cotkṛṣṭāpakṛṣṭasaṃyogena mūtravarṇarasasparśagandhaviśeṣādvarṇānāmiva śuklakṛṣṇādīnāṃ śabalakalmāṣādayaḥ pramehāṇāṃ prabhedā bhavanti" },
      { type: "verse", number: "7", sanskrit: "तेषां पूर्वरूपाण्यतिवृद्धिर्नखादीनां जटिलीभावश्च केशानां माधुर्यमास्यस्य तालुकण्ठशोषः पिपासा मलाधिक्यं बहिःकाये कायछिद्रेषु च शीतेच्छा स्नेहः स्वेदः सुप्तता चाङ्गेषु पाणिपाददाहोतिमाधुर्यात् पिपीलिकोपसर्पणं विस्रगन्धता च मूत्रशरीरयोः शुक्लता च मूत्रे श्वासनिद्रातन्द्रालस्यप्रकर्षश्च", text: "teṣāṃ pūrvarūpāṇyativṛddhirnakhādīnāṃ jaṭilībhāvaśca keśānāṃ mādhuryamāsyasya tālukaṇṭhaśoṣaḥ pipāsā malādhikyaṃ bahiḥkāye kāyachidreṣu ca śītecchā snehaḥ svedaḥ suptatā cāṅgeṣu pāṇipādadāhotimādhuryāt pipīlikopasarpaṇaṃ visragandhatā ca mūtraśarīrayoḥ śuklatā ca mūtre śvāsanidrātandrālasyaprakarṣaśca" },
      { type: "verse", number: "8", sanskrit: "तत्र शीतं श्वेतमगन्धमच्छमुदकमिवोदकमेही मेहति इक्षुरसमिवातिमधुरं शीतमीषत्पिच्छिलाविलामिक्षुमेही पर्युषितं सान्द्रीभवत् सान्द्रमेही सुरातुल्यमुपरि प्रसन्नमधःसान्द्रं सुरामेही हृष्टरोमा पिष्टमिव सान्द्रं सितं च पिष्टमेही शुक्राभं शुक्रमिश्रं वा शुक्रमेही सरुजं ससिकतं सिकतामेही प्रायो मधुरमतिशीतं शीतमेही मन्दंमन्दं शनैःशनैः शनैर्मेही पिच्छिलं तन्तुबद्धमिव लालामेही वर्णगन्धरसस्पर्शैः स्रुतक्षारोपमं क्षारमेही उष्णं मषीकालं कालमेही सफेनमच्छमम्लं चाषपत्रनीलं नीलमेही कटुकं सदाहं हरिद्रायुक्तमिव हारिद्रमेही विस्रं मञ्जिष्ठोदकवर्णमिव मञ्जिष्ठामेही विस्रमुष्णं सलवणं शोणितसङ्काशं शोणितमेही वसामिश्रं वसां वा वसामेही मज्जमिश्रं मज्जानं वा मज्जमेही सलसीकं मधुरमवेगं लसीकयैव च विबद्धमनुबद्धमजस्रं मत्त इव हस्ती स्रवति हस्तिमेही", text: "tatra śītaṃ śvetamagandhamacchamudakamivodakamehī mehati ikṣurasamivātimadhuraṃ śītamīṣatpicchilāvilāmikṣumehī paryuṣitaṃ sāndrībhavat sāndramehī surātulyamupari prasannamadhaḥsāndraṃ surāmehī hṛṣṭaromā piṣṭamiva sāndraṃ sitaṃ ca piṣṭamehī śukrābhaṃ śukramiśraṃ vā śukramehī sarujaṃ sasikataṃ sikatāmehī prāyo madhuramatiśītaṃ śītamehī mandaṃmandaṃ śanaiḥśanaiḥ śanairmehī picchilaṃ tantubaddhamiva lālāmehī varṇagandharasasparśaiḥ srutakṣāropamaṃ kṣāramehī uṣṇaṃ maṣīkālaṃ kālamehī saphenamacchamamlaṃ cāṣapatranīlaṃ nīlamehī kaṭukaṃ sadāhaṃ haridrāyuktamiva hāridramehī visraṃ mañjiṣṭhodakavarṇamiva mañjiṣṭhāmehī visramuṣṇaṃ salavaṇaṃ śoṇitasaṅkāśaṃ śoṇitamehī vasāmiśraṃ vasāṃ vā vasāmehī majjamiśraṃ majjānaṃ vā majjamehī salasīkaṃ madhuramavegaṃ lasīkayaiva ca vibaddhamanubaddhamajasraṃ matta iva hastī sravati hastimehī" },
      { type: "verse", number: "9", sanskrit: "औजः स्निग्धमधुरं तद्रौक्ष्याद्वायुः कषायत्वेनोपसृजति तेन कषायमधुरानुयातं मध्विव मेहति मधुमेही स तु द्विधा कैश्चिदिष्यते धातुक्षयेणानिलकोपाद्दोषावरणेन वा तदावृतो हि वायुराहारप्रसादमादाय मुहुर्मुहुरनिमित्तं दोषलिङ्गानि वृद्धिक्षयौ चाविर्भावयन् कृच्छ्रसाध्यं मधुमेहं प्रवर्तयति सर्व एव चोपेक्ष्यमाणा मधुमेहत्वमायान्ति तस्मात्सर्वे ऽपि मधुमेहशब्देनोच्यन्ते यतः सर्वेष्वपि प्राङ्मधिविव मधुरं मेहति मधुररसश्चास्य देहो भवतीति", text: "aujaḥ snigdhamadhuraṃ tadraukṣyādvāyuḥ kaṣāyatvenopasṛjati tena kaṣāyamadhurānuyātaṃ madhviva mehati madhumehī sa tu dvidhā kaiścidiṣyate dhātukṣayeṇānilakopāddoṣāvaraṇena vā tadāvṛto hi vāyurāhāraprasādamādāya muhurmuhuranimittaṃ doṣaliṅgāni vṛddhikṣayau cāvirbhāvayan kṛcchrasādhyaṃ madhumehaṃ pravartayati sarva eva copekṣyamāṇā madhumehatvamāyānti tasmātsarve 'pi madhumehaśabdenocyante yataḥ sarveṣvapi prāṅmadhiviva madhuraṃ mehati madhurarasaścāsya deho bhavatīti" },
      { type: "verse", number: "10", sanskrit: "तत्र प्रतिश्यायः शरीरशैथिल्यमरोचकाविपाकौ प्रसेकच्छर्दिर्निद्रा कासश्च श्लेष्मजानामुपद्रवा भवन्ति वृषणावदरणं बस्तिर्मेढ्रतोदो ऽम्लकः पिपासा ज्वरो दाहो मूर्च्छातीसारः पाण्डुरोगश्च पित्तजानाम् हृद्ग्रहो लौल्यमनिद्रता कम्पः शूलं बद्धपुरीषत्वं शोषः कासः श्वासश्च वातजानाम्", text: "tatra pratiśyāyaḥ śarīraśaithilyamarocakāvipākau prasekacchardirnidrā kāsaśca śleṣmajānāmupadravā bhavanti vṛṣaṇāvadaraṇaṃ bastirmeḍhratodo 'mlakaḥ pipāsā jvaro dāho mūrcchātīsāraḥ pāṇḍurogaśca pittajānām hṛdgraho laulyamanidratā kampaḥ śūlaṃ baddhapurīṣatvaṃ śoṣaḥ kāsaḥ śvāsaśca vātajānām" },
      { type: "verse", number: "11", sanskrit: "अथैवमस्य मेदःक्लेदादिभिरभिष्यण्णदहेस्य दोषैरनुगतधातोः प्रमेहाभिवृद्धौ मांसलेष्ववकाशेषु सन्धिमर्मसु च प्रदेशविशेषाश्रयत्वात् प्राणापहारिण्यो भूयः कष्टतमोपद्रवा दश पिटका जायन्ते सुतरां चाधःकाये तदभिमुखा हि प्रमेहिणां दोषाः तद्यथा शराविका कच्छपिका जालिनी पुत्रिणी विदारिका सर्षपिका मसूरिकालजी विनता विद्रधिश्च", text: "athaivamasya medaḥkledādibhirabhiṣyaṇṇadahesya doṣairanugatadhātoḥ pramehābhivṛddhau māṃsaleṣvavakāśeṣu sandhimarmasu ca pradeśaviśeṣāśrayatvāt prāṇāpahāriṇyo bhūyaḥ kaṣṭatamopadravā daśa piṭakā jāyante sutarāṃ cādhaḥkāye tadabhimukhā hi pramehiṇāṃ doṣāḥ tadyathā śarāvikā kacchapikā jālinī putriṇī vidārikā sarṣapikā masūrikālajī vinatā vidradhiśca" },
      { type: "verse", number: "12", sanskrit: "तत्र श्यावा क्लेदवेदनायुक्ता निम्नमध्योन्नतौष्ठा शरावसंस्थानप्रमाणा शराविका महामूलावगाढार्तितोदा श्लक्ष्णा कच्छपपृष्ठनिभा कच्छपिका महाशयार्तितोदा स्तब्धा स्निग्धस्राविणी सूक्ष्मच्छिद्रा मांससिराजालावृता जालिनी महती पिटकाभिरल्पाभिराचिता पुत्रिणी कंठिना विदारीकन्दवद्वृत्ता विदारिका शीघ्रपाका महावेदना सर्षपाकृतिप्रमाणा तद्विधाभिश्च पिटकाभिश्चिता सर्षपिका मसूराकार प्रमाणा मसूरिका त्वचमुत्थान एव दहन्ती स्फोटैरावृता विसर्पन्ती रक्ता कृष्णातितृण्मोहज्वरकरी दाहभूयिष्ठातिकष्टा चालजी महती नीलावगाढरुजाक्लेदा पृष्ठोदरान्यतराधिष्ठाना विनता विनता विद्रधिस्तु वक्ष्यते पृथगेव", text: "tatra śyāvā kledavedanāyuktā nimnamadhyonnatauṣṭhā śarāvasaṃsthānapramāṇā śarāvikā mahāmūlāvagāḍhārtitodā ślakṣṇā kacchapapṛṣṭhanibhā kacchapikā mahāśayārtitodā stabdhā snigdhasrāviṇī sūkṣmacchidrā māṃsasirājālāvṛtā jālinī mahatī piṭakābhiralpābhirācitā putriṇī kaṃṭhinā vidārīkandavadvṛttā vidārikā śīghrapākā mahāvedanā sarṣapākṛtipramāṇā tadvidhābhiśca piṭakābhiścitā sarṣapikā masūrākāra pramāṇā masūrikā tvacamutthāna eva dahantī sphoṭairāvṛtā visarpantī raktā kṛṣṇātitṛṇmohajvarakarī dāhabhūyiṣṭhātikaṣṭā cālajī mahatī nīlāvagāḍharujākledā pṛṣṭhodarānyatarādhiṣṭhānā vinatā vinatā vidradhistu vakṣyate pṛthageva" },
      { type: "verse", number: "13", sanskrit: "तासामाद्याः पञ्चातिबलश्लेष्ममेदःसम्भवेन मूलव्याध्येकरूपत्वात्तद्वृद्धिकारितया दुःसहाः न त्वितराः पित्तोल्बणतयाल्पकफमेदोभावात् प्रमेहवशाच्च पिटकासु यथास्वं दोषोद्रेको भवतीति भवति चात्र श्लोकः", text: "tāsāmādyāḥ pañcātibalaśleṣmamedaḥsambhavena mūlavyādhyekarūpatvāttadvṛddhikāritayā duḥsahāḥ na tvitarāḥ pittolbaṇatayālpakaphamedobhāvāt pramehavaśācca piṭakāsu yathāsvaṃ doṣodreko bhavatīti bhavati cātra ślokaḥ" },
      { type: "verse", number: "14", sanskrit: "प्रमेहेण विनाप्येता जायन्ते दुष्टमेदसः तावच्च नोपलक्ष्यन्ते यावद्वस्तुपरिग्रहः", text: "prameheṇa vināpyetā jāyante duṣṭamedasaḥ tāvacca nopalakṣyante yāvadvastuparigrahaḥ" },
      { type: "verse", number: "15", sanskrit: "हारिद्रवर्णं रक्तं वा मेहप्राग्रूपवर्जितम् यो मूत्रयेन्न तं मेहं रक्तपित्तं तु तं विदुः", text: "hāridravarṇaṃ raktaṃ vā mehaprāgrūpavarjitam yo mūtrayenna taṃ mehaṃ raktapittaṃ tu taṃ viduḥ" },
      { type: "verse", number: "16", sanskrit: "दृष्ट्वा प्रमेहं मधुरं सपिच्छं मधूपमं स्यात् द्विविधो विचारः सम्पूरणाच्छ्रलेष्मसमुद्भवः स्यात् क्षीणेषु दोषोष्वनिलात्मको वा", text: "dṛṣṭvā pramehaṃ madhuraṃ sapicchaṃ madhūpamaṃ syāt dvividho vicāraḥ sampūraṇācchraleṣmasamudbhavaḥ syāt kṣīṇeṣu doṣoṣvanilātmako vā" },
      { type: "verse", number: "17", sanskrit: "सपूर्वरूपाः कफपित्तमेहाः क्रमेण ये वातकृताश्च मेहाः साध्या न ते पित्तकृतास्तु याप्याः साध्यास्तु मेदो यदि नातिदुष्टम्", text: "sapūrvarūpāḥ kaphapittamehāḥ krameṇa ye vātakṛtāśca mehāḥ sādhyā na te pittakṛtāstu yāpyāḥ sādhyāstu medo yadi nātiduṣṭam" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 11,
    lang: "sa",
    content: [
      { type: "heading", heading: "Камила нидана — желтуха" },
      { type: "text", text: "Глава 11 Нидана стханы — диагностический раздел о желтуха. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातो विद्रधिवृद्धिगुल्मनिदानं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vidradhivṛddhigulmanidānaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "भुक्तैः षर्युषितास्युष्णरूक्षशुष्कविदाहिभिः जिह्मशय्याविचेष्टाभिस्तैस्तैश्चासृक्प्रदूषणैः", text: "bhuktaiḥ ṣaryuṣitāsyuṣṇarūkṣaśuṣkavidāhibhiḥ jihmaśayyāviceṣṭābhistaistaiścāsṛkpradūṣaṇaiḥ" },
      { type: "verse", number: "3", sanskrit: "दुष्टत्वङ्मांसमेदोस्थिस्नावासृक्कण्डराश्रयः यः शोफो बहिरन्तर्वा महामूलो महारुजः", text: "duṣṭatvaṅmāṃsamedosthisnāvāsṛkkaṇḍarāśrayaḥ yaḥ śopho bahirantarvā mahāmūlo mahārujaḥ" },
      { type: "verse", number: "4", sanskrit: "वृत्तः स्यादायतो यो वा स्मृतः षोढा स विद्रधिः दोषैः पृथक् समुदितैः शोणितेन क्षतेन च", text: "vṛttaḥ syādāyato yo vā smṛtaḥ ṣoḍhā sa vidradhiḥ doṣaiḥ pṛthak samuditaiḥ śoṇitena kṣatena ca" },
      { type: "verse", number: "5", sanskrit: "बाह्यो ऽत्र तत्र तत्राङ्गे दारुणो ग्रथितोन्नतः आन्तरो दारुणतरो गम्भीरो गुल्मवद्घनः", text: "bāhyo 'tra tatra tatrāṅge dāruṇo grathitonnataḥ āntaro dāruṇataro gambhīro gulmavadghanaḥ" },
      { type: "verse", number: "6", sanskrit: "वल्मीकवत् समुच्छ्रायी शीघ्रघात्यग्निशस्त्रवत् नाभिबस्तियकृत्प्लीहक्लोमहृत्कुक्षिवङ्क्षणे", text: "valmīkavat samucchrāyī śīghraghātyagniśastravat nābhibastiyakṛtplīhaklomahṛtkukṣivaṅkṣaṇe" },
      { type: "verse", number: "7", sanskrit: "स्याद्वृक्कयोरपाने वा वातात्तत्रातितीव्ररुक् श्यावारुणश्चिरोत्थानपाको विषमसंस्थितिः", text: "syādvṛkkayorapāne vā vātāttatrātitīvraruk śyāvāruṇaścirotthānapāko viṣamasaṃsthitiḥ" },
      { type: "verse", number: "8", sanskrit: "व्यधच्छेदभ्रमानाहस्पन्दसर्पणशब्दवान् रक्तताम्रासितः पित्तात्तृण्मोहज्वरदाहवान्", text: "vyadhacchedabhramānāhaspandasarpaṇaśabdavān raktatāmrāsitaḥ pittāttṛṇmohajvaradāhavān" },
      { type: "verse", number: "9", sanskrit: "क्षिप्रोत्थानप्रपाकश्च पाण्डुः कण्डूयुतः कफात् सोत्क्लेशशीतकस्तम्भजृम्भारोचकगौरवः", text: "kṣiprotthānaprapākaśca pāṇḍuḥ kaṇḍūyutaḥ kaphāt sotkleśaśītakastambhajṛmbhārocakagauravaḥ" },
      { type: "verse", number: "10", sanskrit: "चिरोत्थानविदाहशच् सङ्कीर्णः सन्निपाततः सामर्थ्याच्चात्र विभजेद्बाह्याभ्यन्तरलक्षणम्", text: "cirotthānavidāhaśac saṅkīrṇaḥ sannipātataḥ sāmarthyāccātra vibhajedbāhyābhyantaralakṣaṇam" },
      { type: "verse", number: "11", sanskrit: "कृष्णस्फोटावृतः श्यावस्तीव्रदाहरुजाज्वरः पित्तलिङ्गो ऽसृजा बाह्यः स्त्रीणामेव तथान्तरः", text: "kṛṣṇasphoṭāvṛtaḥ śyāvastīvradāharujājvaraḥ pittaliṅgo 'sṛjā bāhyaḥ strīṇāmeva tathāntaraḥ" },
      { type: "verse", number: "12", sanskrit: "शस्त्राद्यैरभिघातेन क्षते वापथ्यकारिणः क्षतोष्मा वायुविक्षिप्तः सरक्तं पित्तमीरयन्", text: "śastrādyairabhighātena kṣate vāpathyakāriṇaḥ kṣatoṣmā vāyuvikṣiptaḥ saraktaṃ pittamīrayan" },
      { type: "verse", number: "13", sanskrit: "पित्तासृग्लक्षणं कुर्याद्विद्रधिं भूर्यपद्रवम् तेषूपद्रवभेदश्च स्मृतो ऽधिष्ठानभेदतः", text: "pittāsṛglakṣaṇaṃ kuryādvidradhiṃ bhūryapadravam teṣūpadravabhedaśca smṛto 'dhiṣṭhānabhedataḥ" },
      { type: "verse", number: "14", sanskrit: "नाभ्यां हिध्मा भवेद्बस्तौ मूत्रं कृच्छ्रेण पूति च श्वासो यकृति रोधस्तु प्लीहन्युच्छूवासस्यतृट्पुनः", text: "nābhyāṃ hidhmā bhavedbastau mūtraṃ kṛcchreṇa pūti ca śvāso yakṛti rodhastu plīhanyucchūvāsasyatṛṭpunaḥ" },
      { type: "verse", number: "15", sanskrit: "गलग्रहश्च क्लोम्नि स्यात् सर्वाङ्गप्रग्रहो हृदि प्रमेहस्तमकः कासो हृदयोद्धटनं व्यथा", text: "galagrahaśca klomni syāt sarvāṅgapragraho hṛdi pramehastamakaḥ kāso hṛdayoddhaṭanaṃ vyathā" },
      { type: "verse", number: "16", sanskrit: "कुक्षिपार्श्वान्तरांसार्तिः कुक्षावाटोपजन्म च सक्थ्नोर्ग्रहो वङ्क्षणयोर्वृक्कयोः कटिपृष्ठयोः", text: "kukṣipārśvāntarāṃsārtiḥ kukṣāvāṭopajanma ca sakthnorgraho vaṅkṣaṇayorvṛkkayoḥ kaṭipṛṣṭhayoḥ" },
      { type: "verse", number: "17", sanskrit: "पार्श्वयोश्च व्यथा पायौ पवनस्य निरोधनम् आमपक्वविदग्धत्वं तेषां शोफवदादिशेत्", text: "pārśvayośca vyathā pāyau pavanasya nirodhanam āmapakvavidagdhatvaṃ teṣāṃ śophavadādiśet" },
      { type: "verse", number: "18", sanskrit: "नाभेरूर्ध्वं मुखात् पक्वाः प्रस्रवन्त्यधरे गुदात् गुदास्यान्नाभिजो विद्याद्दोषं क्लेदाच्च विद्रधौ", text: "nābherūrdhvaṃ mukhāt pakvāḥ prasravantyadhare gudāt gudāsyānnābhijo vidyāddoṣaṃ kledācca vidradhau" },
      { type: "verse", number: "19", sanskrit: "यथास्वं व्रणवत्तत्र विवर्ज्यः सन्निपातजः पक्वो हृन्नाभिबस्तिस्थो भिन्नो ऽन्तर्बहिरेव वा", text: "yathāsvaṃ vraṇavattatra vivarjyaḥ sannipātajaḥ pakvo hṛnnābhibastistho bhinno 'ntarbahireva vā" },
      { type: "verse", number: "20", sanskrit: "पक्वश्चान्तःस्रवन् वक्त्रात् क्षीणस्योपद्रवान्वितः", text: "pakvaścāntaḥsravan vaktrāt kṣīṇasyopadravānvitaḥ" },
      { type: "verse", number: "21", sanskrit: "एवमेव स्तनसिरा विवृताः प्राप्य योषिताम् सूतानां गर्भिणीनां वा सम्भवेच्छ्रवयथुर्घनः", text: "evameva stanasirā vivṛtāḥ prāpya yoṣitām sūtānāṃ garbhiṇīnāṃ vā sambhavecchravayathurghanaḥ" },
      { type: "verse", number: "22", sanskrit: "नाडीनां सूक्ष्मवक्त्रत्वात् कन्यानां तु न जायते", text: "nāḍīnāṃ sūkṣmavaktratvāt kanyānāṃ tu na jāyate" },
      { type: "verse", number: "23", sanskrit: "क्रुद्धो रुद्धगतिर्वायुः शोफशूलकरश्चरन् मुष्कौ वङ्क्षणतः प्राप्य फलकोशाभिवाहिनीः", text: "kruddho ruddhagatirvāyuḥ śophaśūlakaraścaran muṣkau vaṅkṣaṇataḥ prāpya phalakośābhivāhinīḥ" },
      { type: "verse", number: "24", sanskrit: "प्रपीड्य धमनीर्वृद्धिं करोति फलकोशयोः दोषास्रमेदोमूत्रान्त्रैः स वृद्धिः सप्तधा गदः", text: "prapīḍya dhamanīrvṛddhiṃ karoti phalakośayoḥ doṣāsramedomūtrāntraiḥ sa vṛddhiḥ saptadhā gadaḥ" },
      { type: "verse", number: "25", sanskrit: "मूत्रान्त्रजावप्यनिलाद्धेतुभेदस्तु केवलम् वातपूर्णदृतिस्पर्शो रूक्षो वातादहेतुरुक्", text: "mūtrāntrajāvapyanilāddhetubhedastu kevalam vātapūrṇadṛtisparśo rūkṣo vātādaheturuk" },
      { type: "verse", number: "26", sanskrit: "पक्वोदुम्बरसङ्काशः पित्ताद्दाहोष्मपाकवान् कफाच्छीतो गुरुः स्निग्धः पण्डूमान्कठिनोल्परुक्", text: "pakvodumbarasaṅkāśaḥ pittāddāhoṣmapākavān kaphācchīto guruḥ snigdhaḥ paṇḍūmānkaṭhinolparuk" },
      { type: "verse", number: "27", sanskrit: "कृष्णस्फोटावृतः पित्तवृद्धिलिङ्गश्च रक्ततः कफवन्मेदसा वृद्धिर्मृदुस्तालफलोपमः", text: "kṛṣṇasphoṭāvṛtaḥ pittavṛddhiliṅgaśca raktataḥ kaphavanmedasā vṛddhirmṛdustālaphalopamaḥ" },
      { type: "verse", number: "28", sanskrit: "मूत्रधारणशीलस्य मूत्रजः स तु गच्छतः अम्भोभिः पूर्णदृतिवत्क्षोभं याति सरुङ्मृदुः", text: "mūtradhāraṇaśīlasya mūtrajaḥ sa tu gacchataḥ ambhobhiḥ pūrṇadṛtivatkṣobhaṃ yāti saruṅmṛduḥ" },
      { type: "verse", number: "29", sanskrit: "मूत्रकृच्छ्रमधः स्याच्च वलयः फलकोशयोः वातकोपिभिराहारैः शीततोयावगाहनैः", text: "mūtrakṛcchramadhaḥ syācca valayaḥ phalakośayoḥ vātakopibhirāhāraiḥ śītatoyāvagāhanaiḥ" },
      { type: "verse", number: "30", sanskrit: "धारणेरणभाराध्वंविषमाङ्गप्रवव्र्तनैः क्षोभणैः क्षुभितो ऽन्यैश्च क्षुद्रान्त्रावयवं यदा", text: "dhāraṇeraṇabhārādhvaṃviṣamāṅgapravavrtanaiḥ kṣobhaṇaiḥ kṣubhito 'nyaiśca kṣudrāntrāvayavaṃ yadā" },
      { type: "verse", number: "31", sanskrit: "पवनो विगुणीकृत्य स्वनिवेशादधो नयेत् कुर्याद्वङ्क्षणसन्धिस्थो ग्रन्थ्याभं श्वयथुं तदा", text: "pavano viguṇīkṛtya svaniveśādadho nayet kuryādvaṅkṣaṇasandhistho granthyābhaṃ śvayathuṃ tadā" },
      { type: "verse", number: "32", sanskrit: "उपेक्षमाणस्य च मुष्कवृद्धिमाध्मानरुक्स्तम्भवतीं स वायुः प्रपीडितो ऽन्तः स्वनवान् प्रयाति प्रध्मापयन्नोति पुनश्च मुक्तः", text: "upekṣamāṇasya ca muṣkavṛddhimādhmānarukstambhavatīṃ sa vāyuḥ prapīḍito 'ntaḥ svanavān prayāti pradhmāpayannoti punaśca muktaḥ" },
      { type: "verse", number: "33", sanskrit: "आन्त्रवृद्धिरसाध्यो ऽयं वातवृद्धिसमाकृतिः रूक्षकृष्णारुणसिरातन्तुजालगवाक्षितः", text: "āntravṛddhirasādhyo 'yaṃ vātavṛddhisamākṛtiḥ rūkṣakṛṣṇāruṇasirātantujālagavākṣitaḥ" },
      { type: "verse", number: "34", sanskrit: "गुल्मो ऽष्टधा पृथग्दोषैः संसृष्टैर्निचयं गतैः आर्तवस्य च दोषेण नारीणां जायते ऽष्टमः", text: "gulmo 'ṣṭadhā pṛthagdoṣaiḥ saṃsṛṣṭairnicayaṃ gataiḥ ārtavasya ca doṣeṇa nārīṇāṃ jāyate 'ṣṭamaḥ" },
      { type: "verse", number: "35", sanskrit: "अथ यो ज्वरातिसारादिभिर्वमनादिभिर्वा कर्मभिः कर्शितो वातलान्याहारयत्याहाराभिलाषी वा शीतमुदकं पिबत्यन्नपानानन्तरं वा लङ्घनप्लवनव्यवाययानयानादीन् देहविक्षोभिणः सेवते ऽनुदीर्णां वा छिर्दिमुदीरयत्युदीर्णान् वा वातादीन् निश्वासोच्छ्वासौ वा निगृह्णात्यस्नेहपूर्वं वा वमनविरेचने करोति तथा शोधित एव वातिविदाहिनो ऽभिष्यन्दिनो वा निषेवते तस्य यथास्वं वातप्रधानाः कुपिता दोषाः पृथक् संसृष्टाः समस्ताः सरक्ता वा महास्रोतो ऽनुप्रविश्यावृत्योर्ध्वमधश्च मार्गमवश्यं शूलमुपजनयन्तो गुल्ममभिनिर्वर्तयन्ति यतश्च तस्मिन् शूलविद्ध इव व्यथते तीव्रवेदनार्दितः कृच्छ्रोच्छ्वासस्तस्माच्छूलमित्युच्यते", text: "atha yo jvarātisārādibhirvamanādibhirvā karmabhiḥ karśito vātalānyāhārayatyāhārābhilāṣī vā śītamudakaṃ pibatyannapānānantaraṃ vā laṅghanaplavanavyavāyayānayānādīn dehavikṣobhiṇaḥ sevate 'nudīrṇāṃ vā chirdimudīrayatyudīrṇān vā vātādīn niśvāsocchvāsau vā nigṛhṇātyasnehapūrvaṃ vā vamanavirecane karoti tathā śodhita eva vātividāhino 'bhiṣyandino vā niṣevate tasya yathāsvaṃ vātapradhānāḥ kupitā doṣāḥ pṛthak saṃsṛṣṭāḥ samastāḥ saraktā vā mahāsroto 'nupraviśyāvṛtyordhvamadhaśca mārgamavaśyaṃ śūlamupajanayanto gulmamabhinirvartayanti yataśca tasmin śūlaviddha iva vyathate tīvravedanārditaḥ kṛcchrocchvāsastasmācchūlamityucyate" },
      { type: "verse", number: "36", sanskrit: "तत्रातिकर्शनात् कफपित्ताभ्यां वा मार्गनिरोधाल्लब्धाश्रयो वायुरुत्प्लुतो रौक्ष्यात् कठिनीभूतः स्वाश्रये स्वतन्त्रः परतन्त्रो वा पित्तश्लेष्माश्रये स्पर्शोपलभ्यः पिण्डितत्वादमूर्तो ऽपि मूर्ततामिवोपगतो ग्रन्थिरूपेणावतिष्ठमानो गुल्मसंज्ञां लभते तस्य पञ्च स्थानानि बस्तिर्नाभिः पार्श्वे हृदयं च अथास्य पूर्वरूपाणि सदनमग्निशरीरयोररुचिः सौहित्यासहिष्णुता कुक्षिशूलमाध्मानमुद्गिरणं बहुशो विदग्धे ऽन्ने छर्दिराटोपो मलस्य प्रादुर्भावो ऽप्रवृत्तिश्च", text: "tatrātikarśanāt kaphapittābhyāṃ vā mārganirodhāllabdhāśrayo vāyurutpluto raukṣyāt kaṭhinībhūtaḥ svāśraye svatantraḥ paratantro vā pittaśleṣmāśraye sparśopalabhyaḥ piṇḍitatvādamūrto 'pi mūrtatāmivopagato granthirūpeṇāvatiṣṭhamāno gulmasaṃjñāṃ labhate tasya pañca sthānāni bastirnābhiḥ pārśve hṛdayaṃ ca athāsya pūrvarūpāṇi sadanamagniśarīrayoraruciḥ sauhityāsahiṣṇutā kukṣiśūlamādhmānamudgiraṇaṃ bahuśo vidagdhe 'nne chardirāṭopo malasya prādurbhāvo 'pravṛttiśca" },
      { type: "verse", number: "37", sanskrit: "तत्र वातात् सूच्येव च शङ्कुनेव च व्यधो मन्याशिरःशङ्खशूलज्वराङ्गमर्दप्लीहाटोपान्त्रकूजोदावर्तोच्छ्वासोपरोधमुखशोषस्तब्धगात्रताः वायुकालेषूपद्रववृद्धिर्विषमाग्निता कृष्णारुणपरुषत्वङ्नखादित्वं गुल्मश्चास्य चलत्वाद्वायोरनियतस्थानसंस्थानोदयप्रलयाल्पमहारुजः पिपीलिकापरिगत इव तोदस्फुरणबहुलो विस्ताअरयतीव स्वदेशे चर्म कदाचित् कदाचित्सङ्कोचयतीव हर्षयति रोमाणि वेदनातिप्रवृत्तौ तु सर्वस्मिन्नपि देहे प्रायो बस्त्याश्रयश्च भवति", text: "tatra vātāt sūcyeva ca śaṅkuneva ca vyadho manyāśiraḥśaṅkhaśūlajvarāṅgamardaplīhāṭopāntrakūjodāvartocchvāsoparodhamukhaśoṣastabdhagātratāḥ vāyukāleṣūpadravavṛddhirviṣamāgnitā kṛṣṇāruṇaparuṣatvaṅnakhāditvaṃ gulmaścāsya calatvādvāyoraniyatasthānasaṃsthānodayapralayālpamahārujaḥ pipīlikāparigata iva todasphuraṇabahulo vistāarayatīva svadeśe carma kadācit kadācitsaṅkocayatīva harṣayati romāṇi vedanātipravṛttau tu sarvasminnapi dehe prāyo bastyāśrayaśca bhavati" },
      { type: "verse", number: "38", sanskrit: "पित्ताद्दाहो धूमको ऽम्लकस्तृष्णा ज्वरः स्वेदो विड्भेदो मूर्च्छा शीतोपशयता हरितहारिद्रत्वगादित्वं गुल्मश्चास्य तप्तायःपिण्ड इव तमवकाशं दहति दूयते धूमायत ऊष्मायते शिथिल इव व्रण इवास्पर्शसहो निर्लोमा प्रायो नाभ्याश्रयश्च", text: "pittāddāho dhūmako 'mlakastṛṣṇā jvaraḥ svedo viḍbhedo mūrcchā śītopaśayatā haritahāridratvagāditvaṃ gulmaścāsya taptāyaḥpiṇḍa iva tamavakāśaṃ dahati dūyate dhūmāyata ūṣmāyate śithila iva vraṇa ivāsparśasaho nirlomā prāyo nābhyāśrayaśca" },
      { type: "verse", number: "39", sanskrit: "कफात् स्तैमित्यमरोचकाविपाकौ हृदयोपलेपः शीतज्वरस्तृप्तिः सदनं कासो हृल्लासः पीनसोनिद्रालस्यं नखादिशुक्लता गुल्मश्च सुप्तस्थिरगुरुकठिनो ऽवगाढो ऽल्परुक् प्रायो हृत्पार्श्वाश्रयश्च संसृष्टलिङ्गः संसर्गात् स त्रिविधः सर्वलिङ्गनिचये निचयगुल्मः सो ऽसाध्यः", text: "kaphāt staimityamarocakāvipākau hṛdayopalepaḥ śītajvarastṛptiḥ sadanaṃ kāso hṛllāsaḥ pīnasonidrālasyaṃ nakhādiśuklatā gulmaśca suptasthiragurukaṭhino 'vagāḍho 'lparuk prāyo hṛtpārśvāśrayaśca saṃsṛṣṭaliṅgaḥ saṃsargāt sa trividhaḥ sarvaliṅganicaye nicayagulmaḥ so 'sādhyaḥ" },
      { type: "verse", number: "40", sanskrit: "रक्तगुल्मस्तु गर्भकोष्ठार्तवागमनवैशेष्यात् पारतन्त्र्यादवैशारद्यादुपचारानुरोधाच्च स्त्रिया एव भवति", text: "raktagulmastu garbhakoṣṭhārtavāgamanavaiśeṣyāt pāratantryādavaiśāradyādupacārānurodhācca striyā eva bhavati" },
      { type: "verse", number: "41", sanskrit: "तत्र यदासावृतुमती नवप्रसूता योनिरोगिणी वा वातलान्यासेवेत तदास्या वायुः प्रकुपितो योन्या मुखमनुप्रविश्यार्तवमपरुणद्धि तदुपरुध्यमानं मासे मासे कुक्षिमभिनिर्वर्तयति गर्भलिङ्गानि च हृल्लासतन्द्राङ्गसाददौहृदस्तन्यदर्शनादीनि वायुसंसर्गात् पुनः पित्तैकप्रकोपतया च वातपित्तगुल्मरूपाणि क्रमाच्छूलस्तम्भदाहातीसारादीनि गर्भाशये च सुतरां शूलं तया योन्या दौर्गन्ध्यमास्रावं च करोति गुल्मश्च न गर्भ इवाङ्गैः पिण्डित इव तु चिरेण सशूलं स्पन्दते गुल्म एव वर्द्धते न कुक्षिः", text: "tatra yadāsāvṛtumatī navaprasūtā yonirogiṇī vā vātalānyāseveta tadāsyā vāyuḥ prakupito yonyā mukhamanupraviśyārtavamaparuṇaddhi taduparudhyamānaṃ māse māse kukṣimabhinirvartayati garbhaliṅgāni ca hṛllāsatandrāṅgasādadauhṛdastanyadarśanādīni vāyusaṃsargāt punaḥ pittaikaprakopatayā ca vātapittagulmarūpāṇi kramācchūlastambhadāhātīsārādīni garbhāśaye ca sutarāṃ śūlaṃ tayā yonyā daurgandhyamāsrāvaṃ ca karoti gulmaśca na garbha ivāṅgaiḥ piṇḍita iva tu cireṇa saśūlaṃ spandate gulma eva varddhate na kukṣiḥ" },
      { type: "verse", number: "42", sanskrit: "स्वदोषाधिष्ठानश्च सर्वो भवति गुल्मः तस्माच्च्चिरेण नैव वा पाकमेति भृशदुष्टरक्ताश्रयत्त्वात्तु विद्रधिः शीघ्रपाको भवतीति भवति चात्र", text: "svadoṣādhiṣṭhānaśca sarvo bhavati gulmaḥ tasmācccireṇa naiva vā pākameti bhṛśaduṣṭaraktāśrayattvāttu vidradhiḥ śīghrapāko bhavatīti bhavati cātra" },
      { type: "verse", number: "43", sanskrit: "गुल्मे ऽन्तराश्रये बस्तिकुक्षिहृत्प्लीहवेदनाः अग्निवर्णबलभ्रंशो वेगानां चाप्रवर्तनम्", text: "gulme 'ntarāśraye bastikukṣihṛtplīhavedanāḥ agnivarṇabalabhraṃśo vegānāṃ cāpravartanam" },
      { type: "verse", number: "44", sanskrit: "अतो विपर्ययो बाह्ये कोष्ठाङ्गेषु तु नातिरुक् वैवर्ण्यमवकाशस्य बहिरुन्नतताधिकम्", text: "ato viparyayo bāhye koṣṭhāṅgeṣu tu nātiruk vaivarṇyamavakāśasya bahirunnatatādhikam" },
      { type: "verse", number: "45", sanskrit: "साटोपमत्युग्ररुजमाध्मानमुदरे भृशम् ऊर्ध्वाधोवातरोधेन तमानाहं प्रचक्षते", text: "sāṭopamatyugrarujamādhmānamudare bhṛśam ūrdhvādhovātarodhena tamānāhaṃ pracakṣate" },
      { type: "verse", number: "46", sanskrit: "घनो ऽष्ठीलोपमो ग्रन्थिरष्ठीलोर्ध्वं समुन्नतः आनाहलिङ्गस्तिर्यक् तु प्रत्यष्ठीला तदाकृतिः", text: "ghano 'ṣṭhīlopamo granthiraṣṭhīlordhvaṃ samunnataḥ ānāhaliṅgastiryak tu pratyaṣṭhīlā tadākṛtiḥ" },
      { type: "verse", number: "47", sanskrit: "पक्वाशयात् गुदोपस्थं वायुस्तीव्ररुजश्चरन् तूनी प्रतूनी तु भवेत्स एवातो विपर्यये", text: "pakvāśayāt gudopasthaṃ vāyustīvrarujaścaran tūnī pratūnī tu bhavetsa evāto viparyaye" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 12,
    lang: "sa",
    content: [
      { type: "heading", heading: "Плиха нидана — болезни селезёнки" },
      { type: "text", text: "Глава 12 Нидана стханы — диагностический раздел о болезни селезёнки. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथात उदरनिदानं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāta udaranidānaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "रोगाः सर्वे ऽपि मन्दे ऽग्नौ सुतरामुदराणि तु अजीर्णान्मलिनैश्चान्नैर्जायन्ते मलसञ्चयात्", text: "rogāḥ sarve 'pi mande 'gnau sutarāmudarāṇi tu ajīrṇānmalinaiścānnairjāyante malasañcayāt" },
      { type: "verse", number: "3", sanskrit: "ऊर्ध्वाधो धातवो रुध्वा वाहिनीरम्बुवाहिनीः प्राणाग्न्यपानान् सन्दूष्य कुर्युस्त्वङ्मांससन्धिगाः", text: "ūrdhvādho dhātavo rudhvā vāhinīrambuvāhinīḥ prāṇāgnyapānān sandūṣya kuryustvaṅmāṃsasandhigāḥ" },
      { type: "verse", number: "4", sanskrit: "आध्माप्य कुक्षिमुदरम् अष्टधा तच्च भिद्यते", text: "ādhmāpya kukṣimudaram aṣṭadhā tacca bhidyate" },
      { type: "verse", number: "5", sanskrit: "पृथग्दोषैः समस्तैश्च प्लीहबद्धक्षतोदकैः तेनार्ताः शुष्कताल्वोष्ठाः शूनपादकरोदराः", text: "pṛthagdoṣaiḥ samastaiśca plīhabaddhakṣatodakaiḥ tenārtāḥ śuṣkatālvoṣṭhāḥ śūnapādakarodarāḥ" },
      { type: "verse", number: "6", sanskrit: "नष्टचेष्टाबलाहाराः कृशाः प्रध्मातकुक्षयः स्युः प्रेतरूपाः पुरुषा भाविनस्तस्य लक्षणम्", text: "naṣṭaceṣṭābalāhārāḥ kṛśāḥ pradhmātakukṣayaḥ syuḥ pretarūpāḥ puruṣā bhāvinastasya lakṣaṇam" },
      { type: "verse", number: "7", sanskrit: "क्षुन्नाशो ऽन्नं चिरात्सर्वं सविदाहं च पच्यते जीर्णाजीर्णं न जानाति सौहित्यं सहते न च", text: "kṣunnāśo 'nnaṃ cirātsarvaṃ savidāhaṃ ca pacyate jīrṇājīrṇaṃ na jānāti sauhityaṃ sahate na ca" },
      { type: "verse", number: "8", sanskrit: "क्षीयते बलतः शश्वच्छ्वसित्यल्पे ऽपि चेष्टिते वृद्धिर्विशो ऽप्रवृत्तिश्च किञ्चिच्छोफश्च पादयोः", text: "kṣīyate balataḥ śaśvacchvasityalpe 'pi ceṣṭite vṛddhirviśo 'pravṛttiśca kiñcicchophaśca pādayoḥ" },
      { type: "verse", number: "9", sanskrit: "रुग्बस्तिसन्धौ ततता लघ्वल्पाभोजनैरपि राजीजन्म वलीनाशो जठरे जठरेषु तु", text: "rugbastisandhau tatatā laghvalpābhojanairapi rājījanma valīnāśo jaṭhare jaṭhareṣu tu" },
      { type: "verse", number: "10", sanskrit: "सर्वेषु तन्द्रा सदनं मलसङ्गो ऽल्पवह्निता दाहः श्वयथुराध्मानमन्ते सलिलसम्भवः", text: "sarveṣu tandrā sadanaṃ malasaṅgo 'lpavahnitā dāhaḥ śvayathurādhmānamante salilasambhavaḥ" },
      { type: "verse", number: "11", sanskrit: "सर्वं त्वतोयमरुणमशोफं नातिभारिकम् गवाक्षितं सिराजालः सदा गुडुगुडायते", text: "sarvaṃ tvatoyamaruṇamaśophaṃ nātibhārikam gavākṣitaṃ sirājālaḥ sadā guḍuguḍāyate" },
      { type: "verse", number: "12", sanskrit: "नाभिमन्त्रं च विष्टभ्य वेगं कृत्वा प्रणश्यति मारुतो हृत्कटीनाभिपायुवङ्क्षणवेदनः", text: "nābhimantraṃ ca viṣṭabhya vegaṃ kṛtvā praṇaśyati māruto hṛtkaṭīnābhipāyuvaṅkṣaṇavedanaḥ" },
      { type: "verse", number: "13", sanskrit: "सशब्दो निश्चरेद्वायुर्विड् बद्धा मूत्र्मल्पकम् नातिमन्दो ऽनलो लौल्यं न च स्याद्विरसं मुखम्", text: "saśabdo niścaredvāyurviḍ baddhā mūtrmalpakam nātimando 'nalo laulyaṃ na ca syādvirasaṃ mukham" },
      { type: "verse", number: "14", sanskrit: "तत्र वातोदरे शोफः पाणिपान्मुष्कसन्धिषु कुक्षिपार्श्वोदरकटीपृष्ठरुक् पर्वभेदनम्", text: "tatra vātodare śophaḥ pāṇipānmuṣkasandhiṣu kukṣipārśvodarakaṭīpṛṣṭharuk parvabhedanam" },
      { type: "verse", number: "15", sanskrit: "शुष्ककासो ऽङ्गमर्दो ऽधोगुरुता मलसङ्ग्रहः श्यावारुणत्वगादित्वमकस्माद्ध्रासवृद्धिमत्", text: "śuṣkakāso 'ṅgamardo 'dhogurutā malasaṅgrahaḥ śyāvāruṇatvagāditvamakasmāddhrāsavṛddhimat" },
      { type: "verse", number: "16", sanskrit: "सतोदभेदमुदरं तनुकृष्णसिराततम् आध्मातदृतिवच्छब्दमाहंतं प्रकरोति च", text: "satodabhedamudaraṃ tanukṛṣṇasirātatam ādhmātadṛtivacchabdamāhaṃtaṃ prakaroti ca" },
      { type: "verse", number: "17", sanskrit: "वायुश्चात्र सरुक्शब्दो विचरेत्सर्वतोगतिः पित्तोदरे ज्वरो मूर्च्छा दाहस्तृट् कटुकास्यता", text: "vāyuścātra sarukśabdo vicaretsarvatogatiḥ pittodare jvaro mūrcchā dāhastṛṭ kaṭukāsyatā" },
      { type: "verse", number: "18", sanskrit: "भ्रमो ऽतिसारः पीतत्वं त्वगादावुदरं हरित् पीतताम्रसिरानद्धं सस्वेदं सोष्म दह्यते", text: "bhramo 'tisāraḥ pītatvaṃ tvagādāvudaraṃ harit pītatāmrasirānaddhaṃ sasvedaṃ soṣma dahyate" },
      { type: "verse", number: "19", sanskrit: "धूमायति मृदुस्पर्शं क्षिप्रपाकं प्रदूयते श्लेष्मोदरे ऽङ्गसदनं स्वापः श्वयथुगौरवम्", text: "dhūmāyati mṛdusparśaṃ kṣiprapākaṃ pradūyate śleṣmodare 'ṅgasadanaṃ svāpaḥ śvayathugauravam" },
      { type: "verse", number: "20", sanskrit: "निद्रोत्क्लेशारुचिश्वासकासशुक्लत्वगादिता उदरं स्तिमितं स्निग्धं शुक्लराजीततं महत्", text: "nidrotkleśāruciśvāsakāsaśuklatvagāditā udaraṃ stimitaṃ snigdhaṃ śuklarājītataṃ mahat" },
      { type: "verse", number: "21", sanskrit: "चिराभिवृद्धि कठिनं शीतस्पर्शं गुरु स्थिरम् त्रिदोषकोपनैस्तैस्तैःस्त्रीदत्तैश्च रजोमलैः", text: "cirābhivṛddhi kaṭhinaṃ śītasparśaṃ guru sthiram tridoṣakopanaistaistaiḥstrīdattaiśca rajomalaiḥ" },
      { type: "verse", number: "22", sanskrit: "गरदूषीविषाद्यैश्च सरक्ताः सञ्चिता मलाः कोष्ठं प्राप्य विकुर्वाणाः शोफमूर्च्छाभ्रमान्वितम्", text: "garadūṣīviṣādyaiśca saraktāḥ sañcitā malāḥ koṣṭhaṃ prāpya vikurvāṇāḥ śophamūrcchābhramānvitam" },
      { type: "verse", number: "23", sanskrit: "कुर्युस्त्रिलिङ्गमुदरं शीघ्रपाकं सुदारुणम् बाधते तच्च सुतरां शीतवाताभ्रदर्शने", text: "kuryustriliṅgamudaraṃ śīghrapākaṃ sudāruṇam bādhate tacca sutarāṃ śītavātābhradarśane" },
      { type: "verse", number: "24", sanskrit: "अत्याशितस्य सङ्क्षोभाद्यानयानादिचेष्टितैः अतिव्यवायभाराध्वगमनव्याधिकर्शनैः", text: "atyāśitasya saṅkṣobhādyānayānādiceṣṭitaiḥ ativyavāyabhārādhvagamanavyādhikarśanaiḥ" },
      { type: "verse", number: "25", sanskrit: "वामपार्श्वाश्रितः प्लीहा च्युतः स्थानाद्विवर्द्धते शोणितं वा रसादिभ्यो विवृद्धं तं विवर्द्धयेत्", text: "vāmapārśvāśritaḥ plīhā cyutaḥ sthānādvivarddhate śoṇitaṃ vā rasādibhyo vivṛddhaṃ taṃ vivarddhayet" },
      { type: "verse", number: "26", sanskrit: "सो ऽष्ठीलेवातिकठिनः प्रोन्नतः कूर्मपृष्ठवत् क्रमेण वर्धमानश्च कुक्षावुदरमावहेत्", text: "so 'ṣṭhīlevātikaṭhinaḥ pronnataḥ kūrmapṛṣṭhavat krameṇa vardhamānaśca kukṣāvudaramāvahet" },
      { type: "verse", number: "27", sanskrit: "श्वासकासपिपासास्यवैरस्याध्मानरुग्ज्वरैः पाण्डुत्वमूर्च्छाच्छर्दीभिर्दाहमोहैश्च संयुतम्", text: "śvāsakāsapipāsāsyavairasyādhmānarugjvaraiḥ pāṇḍutvamūrcchācchardībhirdāhamohaiśca saṃyutam" },
      { type: "verse", number: "28", sanskrit: "अरुणाभं विवर्णं वा नीलहारिद्रराजिमत् उदावर्तरुजानाहैर्मोहतृड्दहनज्वरैः", text: "aruṇābhaṃ vivarṇaṃ vā nīlahāridrarājimat udāvartarujānāhairmohatṛḍdahanajvaraiḥ" },
      { type: "verse", number: "29", sanskrit: "गौरवारुचिकाठिन्यैर्विद्यात्तत्र मलान् क्रमात् प्लीहवद्दक्षिणात् पार्श्वात् कुर्याद्यकृदपि च्युतम्", text: "gauravārucikāṭhinyairvidyāttatra malān kramāt plīhavaddakṣiṇāt pārśvāt kuryādyakṛdapi cyutam" },
      { type: "verse", number: "30", sanskrit: "पक्ष्मवालैः सहान्नेन भुक्तैर्बद्धायने गुदे दुर्नामभिरुदावर्तैरन्नैर्वान्त्रोपलेपिभिः", text: "pakṣmavālaiḥ sahānnena bhuktairbaddhāyane gude durnāmabhirudāvartairannairvāntropalepibhiḥ" },
      { type: "verse", number: "31", sanskrit: "वर्चः पित्तकफान् रुध्वा करोति कुपितो ऽनिलः अपानो जठरं तेन स्युर्दाहज्वरतृट्क्षवाः", text: "varcaḥ pittakaphān rudhvā karoti kupito 'nilaḥ apāno jaṭharaṃ tena syurdāhajvaratṛṭkṣavāḥ" },
      { type: "verse", number: "32", sanskrit: "कासश्वासोरुसदनं शिरोहृन्नाभिपायुरुक् मलसङ्गो ऽरुचिच्छर्दिरुदरं मूढमारुतम्", text: "kāsaśvāsorusadanaṃ śirohṛnnābhipāyuruk malasaṅgo 'rucicchardirudaraṃ mūḍhamārutam" },
      { type: "verse", number: "33", sanskrit: "स्थिरं नीलारुणसिराराजीनद्धमराजि वा नाभेरुपरि च प्रायो गोपुच्छाकृति जायते", text: "sthiraṃ nīlāruṇasirārājīnaddhamarāji vā nābherupari ca prāyo gopucchākṛti jāyate" },
      { type: "verse", number: "34", sanskrit: "अस्थ्यादिशल्यैः सान्नैश्च भुक्तैरत्यशनेन वा भिद्यते पच्यते चान्त्रं तच्छिद्रैश्च स्रवन् बहिः", text: "asthyādiśalyaiḥ sānnaiśca bhuktairatyaśanena vā bhidyate pacyate cāntraṃ tacchidraiśca sravan bahiḥ" },
      { type: "verse", number: "35", sanskrit: "आम एव गुदादेति ततोल्पाल्पं सविड्रसः तुल्यः कुणपगन्धेन पिच्छिलः पीतलोहितः", text: "āma eva gudādeti tatolpālpaṃ saviḍrasaḥ tulyaḥ kuṇapagandhena picchilaḥ pītalohitaḥ" },
      { type: "verse", number: "36", sanskrit: "शेषश्चापूर्य जठरं जठरं घोरमावहेत् वर्धते तदधोनाभेराशु चैति जलात्मताम्", text: "śeṣaścāpūrya jaṭharaṃ jaṭharaṃ ghoramāvahet vardhate tadadhonābherāśu caiti jalātmatām" },
      { type: "verse", number: "37", sanskrit: "उद्रिक्तदोषरूपं च व्याप्तं च श्वासतृट्भ्रमैः छिद्रोदरमिदं प्राहुः परिस्रावीति चापरे", text: "udriktadoṣarūpaṃ ca vyāptaṃ ca śvāsatṛṭbhramaiḥ chidrodaramidaṃ prāhuḥ parisrāvīti cāpare" },
      { type: "verse", number: "38", sanskrit: "प्रवृत्तस्नेहपानादेः सहसामाम्बुपायिनः अत्यम्बुपानान्मन्दाग्रेः क्षीणस्यातिकृशस्य वा", text: "pravṛttasnehapānādeḥ sahasāmāmbupāyinaḥ atyambupānānmandāgreḥ kṣīṇasyātikṛśasya vā" },
      { type: "verse", number: "39", sanskrit: "रुध्वाम्बुमार्गाननिलः कफश्च जलमूर्च्छितः वर्द्धयेतां तदेवाम्बु तत्स्थानादुदराश्रितौ", text: "rudhvāmbumārgānanilaḥ kaphaśca jalamūrcchitaḥ varddhayetāṃ tadevāmbu tatsthānādudarāśritau" },
      { type: "verse", number: "40", sanskrit: "ततः स्यादुदरं तृष्णागुदस्रुतिरुजान्वितम् कासश्वासारुचियुतं नावणसिराततम्", text: "tataḥ syādudaraṃ tṛṣṇāgudasrutirujānvitam kāsaśvāsāruciyutaṃ nāvaṇasirātatam" },
      { type: "verse", number: "41", sanskrit: "तोयपूर्णदृतिस्पर्शशब्दप्रक्षोभवेपथु दकोदरं महत् स्निग्धं स्थिरमावृत्तनाभि तत्", text: "toyapūrṇadṛtisparśaśabdaprakṣobhavepathu dakodaraṃ mahat snigdhaṃ sthiramāvṛttanābhi tat" },
      { type: "verse", number: "42", sanskrit: "उपेक्षया च सर्वेषु दोषाः स्वस्थानतश्च्युताः पाकाद्द्रवा द्रवीकुर्युः सन्धिस्रोतोमुखान्यपि", text: "upekṣayā ca sarveṣu doṣāḥ svasthānataścyutāḥ pākāddravā dravīkuryuḥ sandhisrotomukhānyapi" },
      { type: "verse", number: "43", sanskrit: "स्वेदश्च बाह्यस्रोतस्सु विहतस्तिर्यगास्थितः तदेवोदकमाप्याय्य पिच्छां कुर्यात्तदा भवेत्", text: "svedaśca bāhyasrotassu vihatastiryagāsthitaḥ tadevodakamāpyāyya picchāṃ kuryāttadā bhavet" },
      { type: "verse", number: "44", sanskrit: "गुरूदरं स्थिरं वृत्तमाहतं च न शब्दवत् मृदु व्यपेतराजीकं नाभ्यां स्पृष्टं च सर्पति", text: "gurūdaraṃ sthiraṃ vṛttamāhataṃ ca na śabdavat mṛdu vyapetarājīkaṃ nābhyāṃ spṛṣṭaṃ ca sarpati" },
      { type: "verse", number: "45", sanskrit: "तदनूदकजन्मास्मिन् कुक्षिवृद्धिस्ततो ऽधिकम् सिरान्तर्द्धानमुदकजठरोक्तं च लक्षणम्", text: "tadanūdakajanmāsmin kukṣivṛddhistato 'dhikam sirāntarddhānamudakajaṭharoktaṃ ca lakṣaṇam" },
      { type: "verse", number: "46", sanskrit: "वातपित्तकफप्लीहसन्निपातदकोदरम् कृच्छ्रं यथोत्तरं पक्षात् परं प्रायो ऽपरे हतः", text: "vātapittakaphaplīhasannipātadakodaram kṛcchraṃ yathottaraṃ pakṣāt paraṃ prāyo 'pare hataḥ" },
      { type: "verse", number: "47", sanskrit: "सर्वं च जातसलिलं रिष्ठोक्तोपद्रवान्वितम् जन्मनैवोदरं सर्वं प्रायः कृच्छ्रतमं मतम्", text: "sarvaṃ ca jātasalilaṃ riṣṭhoktopadravānvitam janmanaivodaraṃ sarvaṃ prāyaḥ kṛcchratamaṃ matam" },
      { type: "verse", number: "48", sanskrit: "बलिनस्तदजाताम्बु यत्नसाध्यं नवोत्थितम्", text: "balinastadajātāmbu yatnasādhyaṃ navotthitam" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 13,
    lang: "sa",
    content: [
      { type: "heading", heading: "Шваса каса нидана — одышка и кашель" },
      { type: "text", text: "Глава 13 Нидана стханы — диагностический раздел о одышка и кашель. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातः पाण्डुशोफविसर्पनिदानं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ pāṇḍuśophavisarpanidānaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "पित्तप्रधानाः कुपिता यथोक्तैः कोपनैर्मलाः तत्रानिलेन बलिना क्षिप्तं पित्तं हृदि स्थितम्", text: "pittapradhānāḥ kupitā yathoktaiḥ kopanairmalāḥ tatrānilena balinā kṣiptaṃ pittaṃ hṛdi sthitam" },
      { type: "verse", number: "3", sanskrit: "धमनीलेन सम्प्राप्य व्याप्नुवत्सकलां तनुम् श्लेष्मत्वग्रक्तमांसानि प्रदूष्यान्तरमाश्रितम्", text: "dhamanīlena samprāpya vyāpnuvatsakalāṃ tanum śleṣmatvagraktamāṃsāni pradūṣyāntaramāśritam" },
      { type: "verse", number: "4", sanskrit: "त्वङ्मांसयोस्तत् कुरुते त्वचि वर्णान्पृथग्विधान् पाण्डुहारिद्रहरितान् पाण्डुत्वं तेषु चाधिकम्", text: "tvaṅmāṃsayostat kurute tvaci varṇānpṛthagvidhān pāṇḍuhāridraharitān pāṇḍutvaṃ teṣu cādhikam" },
      { type: "verse", number: "5", sanskrit: "यतो ऽतः पाण्डुरित्युक्तः स रोगः तेन गौरवम् धातूनां स्याच्च शैथिल्यमोजसश्च गुणक्षयः", text: "yato 'taḥ pāṇḍurityuktaḥ sa rogaḥ tena gauravam dhātūnāṃ syācca śaithilyamojasaśca guṇakṣayaḥ" },
      { type: "verse", number: "6", sanskrit: "ततो ऽल्परक्तमेदस्को निःसारः स्याच्छ्लथेन्द्रियः मृद्यमानैरिवाङ्गैर्ना द्रवता हृदयेन च", text: "tato 'lparaktamedasko niḥsāraḥ syācchlathendriyaḥ mṛdyamānairivāṅgairnā dravatā hṛdayena ca" },
      { type: "verse", number: "7", sanskrit: "शूनाक्षिकूटवदनः कोपनः ष्ठीवनोल्पवाक् अन्नद्विट्शिशिरद्वेषी शीर्णरोमा हतानलः", text: "śūnākṣikūṭavadanaḥ kopanaḥ ṣṭhīvanolpavāk annadviṭśiśiradveṣī śīrṇaromā hatānalaḥ" },
      { type: "verse", number: "8", sanskrit: "सन्नसक्थी ज्वरी श्वासी कर्णक्ष्वेडी श्रमी भ्रमी स पञ्चधा पृथग्दोषैः समस्तैर्मृत्तिकादनात्", text: "sannasakthī jvarī śvāsī karṇakṣveḍī śramī bhramī sa pañcadhā pṛthagdoṣaiḥ samastairmṛttikādanāt" },
      { type: "verse", number: "9", sanskrit: "प्राग्रूपमस्य हृदयस्पन्दनं रूक्षता त्वचि अरुचिः पीतमूत्रत्वं स्वेदाभावो ऽल्पवाह्निता", text: "prāgrūpamasya hṛdayaspandanaṃ rūkṣatā tvaci aruciḥ pītamūtratvaṃ svedābhāvo 'lpavāhnitā" },
      { type: "verse", number: "10", sanskrit: "सादः श्रमो ऽनिलात्तत्र गात्ररुक्तोदकम्पनम् कृष्णरूक्षारुणसिरानखविण्मूत्रनेत्रता", text: "sādaḥ śramo 'nilāttatra gātraruktodakampanam kṛṣṇarūkṣāruṇasirānakhaviṇmūtranetratā" },
      { type: "verse", number: "11", sanskrit: "शोफानाहास्यवैरस्यविट्शोषाः पार्श्वमूर्धरुक् पित्ताद्धरितपीताभसिरादित्वं ज्वरस्तमः", text: "śophānāhāsyavairasyaviṭśoṣāḥ pārśvamūrdharuk pittāddharitapītābhasirāditvaṃ jvarastamaḥ" },
      { type: "verse", number: "12", sanskrit: "तृट्स्वेदमूर्च्छा शीतेच्छा दौर्गन्ध्यं कटुवक्त्रता वर्चोभेदो ऽम्लको दाहः कफाच्छुक्लसिरादिता", text: "tṛṭsvedamūrcchā śītecchā daurgandhyaṃ kaṭuvaktratā varcobhedo 'mlako dāhaḥ kaphācchuklasirāditā" },
      { type: "verse", number: "13", sanskrit: "तन्द्रा लवणवक्त्रत्वं रोमहर्षः स्वरक्षयः कासश्छर्दिश्च निचयान्मिश्रलिङ्गो ऽतिदुस्सहः", text: "tandrā lavaṇavaktratvaṃ romaharṣaḥ svarakṣayaḥ kāsaśchardiśca nicayānmiśraliṅgo 'tidussahaḥ" },
      { type: "verse", number: "14", sanskrit: "मृत् कषायानिलं पित्तमूषरा मधुरा कफम् दूषयित्वा रसादींश्च रौक्ष्याद्भुक्तं विरूक्ष्य च", text: "mṛt kaṣāyānilaṃ pittamūṣarā madhurā kapham dūṣayitvā rasādīṃśca raukṣyādbhuktaṃ virūkṣya ca" },
      { type: "verse", number: "15", sanskrit: "स्रोतांस्यपक्वैवापूर्य कुर्याद्रुध्वा च पूर्ववत् पाण्डुरोगं ततः शूननाभिपादास्यमेहनः", text: "srotāṃsyapakvaivāpūrya kuryādrudhvā ca pūrvavat pāṇḍurogaṃ tataḥ śūnanābhipādāsyamehanaḥ" },
      { type: "verse", number: "16", sanskrit: "पुरीषं कृमिवन्मुञ्चेद्भिन्नं सासृक्कफं नरः यः पाण्डुरोगी सेवेत पित्तलं तस्य कामलाम्", text: "purīṣaṃ kṛmivanmuñcedbhinnaṃ sāsṛkkaphaṃ naraḥ yaḥ pāṇḍurogī seveta pittalaṃ tasya kāmalām" },
      { type: "verse", number: "17", sanskrit: "कोष्ठशाखाश्रयं पित्तं दग्ध्वासृङ्मांसमावहेत् हारिद्रनेत्रमूत्रत्वङ्नखवक्त्रशकृत्तया", text: "koṣṭhaśākhāśrayaṃ pittaṃ dagdhvāsṛṅmāṃsamāvahet hāridranetramūtratvaṅnakhavaktraśakṛttayā" },
      { type: "verse", number: "18", sanskrit: "दाहाविपाकतृष्णावान् भेकाभो दुर्बलेन्द्रियः भवेत् पित्तोल्बणस्यासौ पाण्डुरोगादृते ऽपि च", text: "dāhāvipākatṛṣṇāvān bhekābho durbalendriyaḥ bhavet pittolbaṇasyāsau pāṇḍurogādṛte 'pi ca" },
      { type: "verse", number: "19", sanskrit: "उपेक्षया च शोफाढ्या सा कृछ्रा कुम्भकामला हरितश्यावपीतत्वं पाण्डुरोगे यदा भवेत्", text: "upekṣayā ca śophāḍhyā sā kṛchrā kumbhakāmalā haritaśyāvapītatvaṃ pāṇḍuroge yadā bhavet" },
      { type: "verse", number: "20", sanskrit: "वातपित्ताद्भ्रमस्तृष्णा स्त्रीष्वहर्षो मृदुज्वरः तन्द्राबलानलभ्रंशो लोढरं तं हलीमकम्", text: "vātapittādbhramastṛṣṇā strīṣvaharṣo mṛdujvaraḥ tandrābalānalabhraṃśo loḍharaṃ taṃ halīmakam" },
      { type: "verse", number: "21", sanskrit: "अलसं चेति शंसन्ति तेषां पूर्वमुपद्रवाः शोफप्रधानाः कथिताः स एवातो निगद्यते", text: "alasaṃ ceti śaṃsanti teṣāṃ pūrvamupadravāḥ śophapradhānāḥ kathitāḥ sa evāto nigadyate" },
      { type: "verse", number: "22", sanskrit: "पित्तरक्तकफान् वायुर्दुष्टो दुष्टान् बहिःसिराः नीत्वा रुद्धगतिस्तैर्हि कुर्यात् त्वङ्मांससंश्रयम्", text: "pittaraktakaphān vāyurduṣṭo duṣṭān bahiḥsirāḥ nītvā ruddhagatistairhi kuryāt tvaṅmāṃsasaṃśrayam" },
      { type: "verse", number: "23", sanskrit: "उत्सेधं संहतं शोफं तमाहुर्निचयादतः सर्वम् हेतुविशेषैस्तु रूपभेदान्नवात्मकम्", text: "utsedhaṃ saṃhataṃ śophaṃ tamāhurnicayādataḥ sarvam hetuviśeṣaistu rūpabhedānnavātmakam" },
      { type: "verse", number: "24", sanskrit: "दोषैः पृथग्द्वयैः सर्वैरभिघाताद्विषादपि द्विधा वा निजमागन्तुं सर्वाङ्गैकाङ्गजं च तम्", text: "doṣaiḥ pṛthagdvayaiḥ sarvairabhighātādviṣādapi dvidhā vā nijamāgantuṃ sarvāṅgaikāṅgajaṃ ca tam" },
      { type: "verse", number: "25", sanskrit: "पृथून्नतग्रथितताविशेषैश्च त्रिधा विदुः सामान्यहेतुः शोफानां दोषजानां विशेषतः", text: "pṛthūnnatagrathitatāviśeṣaiśca tridhā viduḥ sāmānyahetuḥ śophānāṃ doṣajānāṃ viśeṣataḥ" },
      { type: "verse", number: "26", sanskrit: "व्याधिकर्मोपवासादिक्षीणस्य भजतो द्रुतम् अतिमात्रमथान्यस्य गुर्वम्लस्निग्धशीतलम् लवणक्षारतीक्ष्णोष्णशाकाम्बुस्वप्नजागरम्", text: "vyādhikarmopavāsādikṣīṇasya bhajato drutam atimātramathānyasya gurvamlasnigdhaśītalam lavaṇakṣāratīkṣṇoṣṇaśākāmbusvapnajāgaram" },
      { type: "verse", number: "27", sanskrit: "मृद्ग्राम्यमांसवल्लूरमजीर्णश्रममैथुनम् पदातेर्मार्गगमनं यानेन क्षोभिणापि वा", text: "mṛdgrāmyamāṃsavallūramajīrṇaśramamaithunam padātermārgagamanaṃ yānena kṣobhiṇāpi vā" },
      { type: "verse", number: "28", sanskrit: "श्वासकासातिसारार्शोजठरप्रदरज्वराः विषूच्यलसकच्छर्दिगर्भवीसर्पपाण्डवः", text: "śvāsakāsātisārārśojaṭharapradarajvarāḥ viṣūcyalasakacchardigarbhavīsarpapāṇḍavaḥ" },
      { type: "verse", number: "29", sanskrit: "अन्ये च मिथ्योपक्रान्तास्तैर्दोषा वक्षसि स्थिताः ऊर्ध्वं शोफमधो बस्तौ मध्ये कुर्वन्ति मध्यगाः", text: "anye ca mithyopakrāntāstairdoṣā vakṣasi sthitāḥ ūrdhvaṃ śophamadho bastau madhye kurvanti madhyagāḥ" },
      { type: "verse", number: "30", sanskrit: "सर्वाङ्गाः सर्वगतं प्रत्यङ्गेषु तदाश्रयाः तत्पूर्वरूपं दवथुः सिरायामो ऽङ्गगौरवम्", text: "sarvāṅgāḥ sarvagataṃ pratyaṅgeṣu tadāśrayāḥ tatpūrvarūpaṃ davathuḥ sirāyāmo 'ṅgagauravam" },
      { type: "verse", number: "31", sanskrit: "वाताच्छोफश्चलो रूक्षः खररोमारुणासितः सङ्कोचस्पन्दहर्षार्तितोदभेदप्रसुप्तिमान्", text: "vātācchophaścalo rūkṣaḥ khararomāruṇāsitaḥ saṅkocaspandaharṣārtitodabhedaprasuptimān" },
      { type: "verse", number: "32", sanskrit: "क्षिप्रोत्थानशमः शीघ्रमुन्नमेत् पीडितस्तनुः स्निग्धोष्णमर्दनैः शाम्येद्रात्रावल्पो दिवा महान्", text: "kṣiprotthānaśamaḥ śīghramunnamet pīḍitastanuḥ snigdhoṣṇamardanaiḥ śāmyedrātrāvalpo divā mahān" },
      { type: "verse", number: "33", sanskrit: "त्वक्च सर्षपलिप्तेव तस्मिंश्चिमिचिमायते पीतरक्तासिताभासः पित्तादाताम्ररोमकृत्", text: "tvakca sarṣapalipteva tasmiṃścimicimāyate pītaraktāsitābhāsaḥ pittādātāmraromakṛt" },
      { type: "verse", number: "34", sanskrit: "शीघ्रानुसारप्रशमो मध्ये प्राग्जायते तनोः सतृड्दाहज्वरस्वेददवक्लेदमदभ्रमः", text: "śīghrānusārapraśamo madhye prāgjāyate tanoḥ satṛḍdāhajvarasvedadavakledamadabhramaḥ" },
      { type: "verse", number: "35", sanskrit: "शीताभिलाषी विड्भेदी गन्धी स्पर्शासहो मृदुः कण्डूमान् पाण्डुरोमत्वक्कठिनः शीतलो गुरुः", text: "śītābhilāṣī viḍbhedī gandhī sparśāsaho mṛduḥ kaṇḍūmān pāṇḍuromatvakkaṭhinaḥ śītalo guruḥ" },
      { type: "verse", number: "36", sanskrit: "स्निग्धः श्लक्ष्णः स्थिर स्त्यानो निद्राच्छर्द्यग्निसादकृत् आक्रान्तो नोन्नमेत् कृच्छ्रशमजन्मा निशाबलः", text: "snigdhaḥ ślakṣṇaḥ sthira styāno nidrācchardyagnisādakṛt ākrānto nonnamet kṛcchraśamajanmā niśābalaḥ" },
      { type: "verse", number: "37", sanskrit: "स्रवेन्नासृक् चिरात् पिच्छां कुशशस्त्रादिविक्षतः स्पर्शोष्णकाङ्क्षी च कफाद्यथास्वं द्वन्द्वजास्त्रयः", text: "sravennāsṛk cirāt picchāṃ kuśaśastrādivikṣataḥ sparśoṣṇakāṅkṣī ca kaphādyathāsvaṃ dvandvajāstrayaḥ" },
      { type: "verse", number: "38", sanskrit: "सङ्कराद्धेतुलिङ्गानां निचयान्निचयात्मकः अभिघातेन शस्त्रादिच्छेदभेदक्षतादिभिः", text: "saṅkarāddhetuliṅgānāṃ nicayānnicayātmakaḥ abhighātena śastrādicchedabhedakṣatādibhiḥ" },
      { type: "verse", number: "39", sanskrit: "हिमानिलोदध्यनिलैर्भल्लातकपिकच्छुजैः रसैश्शूकैश्चसंस्पर्शाच्छ्रवयथुः स्याद्विसर्पवान्", text: "himānilodadhyanilairbhallātakapikacchujaiḥ rasaiśśūkaiścasaṃsparśācchravayathuḥ syādvisarpavān" },
      { type: "verse", number: "40", sanskrit: "भृशोष्मा लोहिताभासः प्रायशः पित्तलक्षणः", text: "bhṛśoṣmā lohitābhāsaḥ prāyaśaḥ pittalakṣaṇaḥ" },
      { type: "verse", number: "41", sanskrit: "विषजः सविषप्राणिपरिसर्पणमूत्रणात् दंष्ट्रादन्तनखापातादविषप्राणिनामपि", text: "viṣajaḥ saviṣaprāṇiparisarpaṇamūtraṇāt daṃṣṭrādantanakhāpātādaviṣaprāṇināmapi" },
      { type: "verse", number: "42", sanskrit: "विण्मूत्रशुक्रोपहतमलवद्वस्त्रसङ्करात् विषवृक्षानिलस्पर्शाद्गरयोगावचूर्णनात्", text: "viṇmūtraśukropahatamalavadvastrasaṅkarāt viṣavṛkṣānilasparśādgarayogāvacūrṇanāt" },
      { type: "verse", number: "43", sanskrit: "मृदुश्चलो ऽवलम्बी च शीघ्रदाहरुजाकरः नवो ऽनुपद्रवः शोफः साध्यो ऽसाध्यः पुरेरितः", text: "mṛduścalo 'valambī ca śīghradāharujākaraḥ navo 'nupadravaḥ śophaḥ sādhyo 'sādhyaḥ pureritaḥ" },
      { type: "verse", number: "44", sanskrit: "स्याद्विसर्पो ऽभिघातान्तैर्दोषैर्दूष्यैश्च शोफवत् त्र्यधिष्ठानं च तं प्राहुर्बाह्यान्तरुभयाश्रयात्", text: "syādvisarpo 'bhighātāntairdoṣairdūṣyaiśca śophavat tryadhiṣṭhānaṃ ca taṃ prāhurbāhyāntarubhayāśrayāt" },
      { type: "verse", number: "45", sanskrit: "यथोत्तरं च दुःसाध्यास्तत्र दोषा यथायथम् प्रकोपणैः प्रकुपिता विशेषेण विदाहिभिः", text: "yathottaraṃ ca duḥsādhyāstatra doṣā yathāyatham prakopaṇaiḥ prakupitā viśeṣeṇa vidāhibhiḥ" },
      { type: "verse", number: "46", sanskrit: "देहे शीघ्रं विसर्पन्ति ते ऽन्तरन्तःस्थिता बहिः बहिःस्था द्वितये द्विस्थाः विद्यात्तत्रान्तराश्रयम्", text: "dehe śīghraṃ visarpanti te 'ntarantaḥsthitā bahiḥ bahiḥsthā dvitaye dvisthāḥ vidyāttatrāntarāśrayam" },
      { type: "verse", number: "47", sanskrit: "मर्मोपतापात्सम्मोहादयनानां विघट्टनात् तृष्णातियोगाद्वेगानां विषमं च प्रवर्तनात्", text: "marmopatāpātsammohādayanānāṃ vighaṭṭanāt tṛṣṇātiyogādvegānāṃ viṣamaṃ ca pravartanāt" },
      { type: "verse", number: "48", sanskrit: "आशु चाग्निबलभ्रंशादतो बाह्यं विपर्ययात् तत्र वातात् परीसर्पो वातज्वरसमव्यथः", text: "āśu cāgnibalabhraṃśādato bāhyaṃ viparyayāt tatra vātāt parīsarpo vātajvarasamavyathaḥ" },
      { type: "verse", number: "49", sanskrit: "शोफस्फुरणनिस्तोदभेदायामार्तिहर्षवान् पित्ताद्द्रुतगतिः पित्तज्वरलिङ्गो ऽतिलोहितः", text: "śophasphuraṇanistodabhedāyāmārtiharṣavān pittāddrutagatiḥ pittajvaraliṅgo 'tilohitaḥ" },
      { type: "verse", number: "50", sanskrit: "कफात्कण्डूयुतः स्निग्धः कफज्वरसमानरुक् स्वदोषलिङ्गैश्चीयन्ते सर्वे स्फोटैरुपेक्षिताः", text: "kaphātkaṇḍūyutaḥ snigdhaḥ kaphajvarasamānaruk svadoṣaliṅgaiścīyante sarve sphoṭairupekṣitāḥ" },
      { type: "verse", number: "51", sanskrit: "ते पक्वभिन्नाः स्वं स्वं च बिभ्रति व्रणलक्षणम् वातपित्ताज्ज्वरच्छर्दिमूर्छातीसारतृड्भ्रमैः", text: "te pakvabhinnāḥ svaṃ svaṃ ca bibhrati vraṇalakṣaṇam vātapittājjvaracchardimūrchātīsāratṛḍbhramaiḥ" },
      { type: "verse", number: "52", sanskrit: "अस्तिभेदाग्निसदनतमकारोचकैर्युतः करोति सर्वमङ्गं च दीप्ताङ्गारावकीर्णवत्", text: "astibhedāgnisadanatamakārocakairyutaḥ karoti sarvamaṅgaṃ ca dīptāṅgārāvakīrṇavat" },
      { type: "verse", number: "53", sanskrit: "यं यं देशं विसर्पश्च विसर्पति भवेत्स सः शान्ताङ्गारासितो नीलो रक्तो वाशु च चीयते", text: "yaṃ yaṃ deśaṃ visarpaśca visarpati bhavetsa saḥ śāntāṅgārāsito nīlo rakto vāśu ca cīyate" },
      { type: "verse", number: "54", sanskrit: "अग्निदग्ध इव स्फोटैः शीघ्रगत्वाद्द्रुतञ्च सः मर्मानुसारी वीसर्पः स्याद्वातो ऽतिबलस्ततः", text: "agnidagdha iva sphoṭaiḥ śīghragatvāddrutañca saḥ marmānusārī vīsarpaḥ syādvāto 'tibalastataḥ" },
      { type: "verse", number: "55", sanskrit: "व्यथेताङ्गं हरेत्संज्ञां निद्रां च श्वासमीरयेत् हिध्मां च स गतो ऽवस्थामीदृशीं लभते न ना", text: "vyathetāṅgaṃ haretsaṃjñāṃ nidrāṃ ca śvāsamīrayet hidhmāṃ ca sa gato 'vasthāmīdṛśīṃ labhate na nā" },
      { type: "verse", number: "56", sanskrit: "क्वचिच्छर्मारतिग्रस्तो भूमिशय्यासनादिषु चेष्टमानस्ततः क्लिष्टो मनोदेहश्रमोद्भवाम्", text: "kvaciccharmāratigrasto bhūmiśayyāsanādiṣu ceṣṭamānastataḥ kliṣṭo manodehaśramodbhavām" },
      { type: "verse", number: "57", sanskrit: "दुष्प्रबोधो ऽश्नुते निद्रां सो ऽग्निवीसर्प उच्यते", text: "duṣprabodho 'śnute nidrāṃ so 'gnivīsarpa ucyate" },
      { type: "verse", number: "58", sanskrit: "कफेन रुद्धः पवनो भित्वा तं बहुधा कफम् रक्तं वा वृद्धरक्तस्य त्वक्सिरास्नावमांसगम्", text: "kaphena ruddhaḥ pavano bhitvā taṃ bahudhā kapham raktaṃ vā vṛddharaktasya tvaksirāsnāvamāṃsagam" },
      { type: "verse", number: "59", sanskrit: "दूषयित्वा च दीर्घाणुवृत्तस्थूलखरात्मनाम् ग्रन्थीनां कुरुते मालां रक्तानां तीव्ररुग्ज्वराम्", text: "dūṣayitvā ca dīrghāṇuvṛttasthūlakharātmanām granthīnāṃ kurute mālāṃ raktānāṃ tīvrarugjvarām" },
      { type: "verse", number: "60", sanskrit: "श्वासकासातिसारास्यशोषहिध्मावमिभ्रमैः मोहवैवर्ण्यमूर्च्छाङ्गभङ्गाग्निसदनैर्युताम्", text: "śvāsakāsātisārāsyaśoṣahidhmāvamibhramaiḥ mohavaivarṇyamūrcchāṅgabhaṅgāgnisadanairyutām" },
      { type: "verse", number: "61", sanskrit: "इत्ययं ग्रन्थिवीसर्पः कफमारुतकोपजः", text: "ityayaṃ granthivīsarpaḥ kaphamārutakopajaḥ" },
      { type: "verse", number: "62", sanskrit: "कफपित्तात् ज्वरः स्तम्भो तन्द्रानिद्राशिरोरुजः अङ्गावसादविक्षेपप्रलापारोचकभ्रमाः", text: "kaphapittāt jvaraḥ stambho tandrānidrāśirorujaḥ aṅgāvasādavikṣepapralāpārocakabhramāḥ" },
      { type: "verse", number: "63", sanskrit: "मूर्छाग्निहानिर्भेदो ऽस्थ्नां पिपासेन्द्रियगौरवम् आमोपवेशनं लेपः स्रोतसां स च सर्पति", text: "mūrchāgnihānirbhedo 'sthnāṃ pipāsendriyagauravam āmopaveśanaṃ lepaḥ srotasāṃ sa ca sarpati" },
      { type: "verse", number: "64", sanskrit: "प्रायेणामाशये गृह्णन्नेकदेशञ्च नातिरुक् पिटकैरवकीर्णो ऽतिपीतलोहितपाण्डुरैः", text: "prāyeṇāmāśaye gṛhṇannekadeśañca nātiruk piṭakairavakīrṇo 'tipītalohitapāṇḍuraiḥ" },
      { type: "verse", number: "65", sanskrit: "मेचकाभो ऽसितःस्निग्धो मलिनःशोफवान् गुरुः गम्भीरपाकः प्राज्योष्मा स्पृष्टः क्लिन्नो ऽवदीर्याते", text: "mecakābho 'sitaḥsnigdho malinaḥśophavān guruḥ gambhīrapākaḥ prājyoṣmā spṛṣṭaḥ klinno 'vadīryāte" },
      { type: "verse", number: "66", sanskrit: "पङ्कवच्छीर्णमांसश्च स्पष्टस्नायुसिरागणः शवगन्धी च वीसर्पः कर्दमाख्यमुशन्ति तम्", text: "paṅkavacchīrṇamāṃsaśca spaṣṭasnāyusirāgaṇaḥ śavagandhī ca vīsarpaḥ kardamākhyamuśanti tam" },
      { type: "verse", number: "67", sanskrit: "सर्वजो लक्षणैः सर्वैः सर्वधात्वभिदर्पणः बाह्यहेतोः क्षतात् क्रुद्धः सरक्तं पित्तमीरयन्", text: "sarvajo lakṣaṇaiḥ sarvaiḥ sarvadhātvabhidarpaṇaḥ bāhyahetoḥ kṣatāt kruddhaḥ saraktaṃ pittamīrayan" },
      { type: "verse", number: "68", sanskrit: "विसर्पं मारुतः कुर्यात् कुलत्थसदृशैश्चितम् स्फोटैः शोफज्वररुजादाहाढ्यं श्यावलोहितम्", text: "visarpaṃ mārutaḥ kuryāt kulatthasadṛśaiścitam sphoṭaiḥ śophajvararujādāhāḍhyaṃ śyāvalohitam" },
      { type: "verse", number: "69", sanskrit: "असाध्यौ क्षतसर्वोत्थौ सर्वे चाक्रान्तमर्मकाः", text: "asādhyau kṣatasarvotthau sarve cākrāntamarmakāḥ" },
      { type: "verse", number: "70", sanskrit: "शीर्णस्नायुसिरामांसाः प्रक्लिन्नाः शवगन्धयः", text: "śīrṇasnāyusirāmāṃsāḥ praklinnāḥ śavagandhayaḥ" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 14,
    lang: "sa",
    content: [
      { type: "heading", heading: "Хикка нидана — икота" },
      { type: "text", text: "Глава 14 Нидана стханы — диагностический раздел о икота. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातः कुष्ठश्वित्रकृमिनिदानं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ kuṣṭhaśvitrakṛminidānaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "मिथ्याहारविहारेण विशेषेण विरोधिना साधुनिन्दावधान्यस्वहरणाद्यैश्च सेवितैः", text: "mithyāhāravihāreṇa viśeṣeṇa virodhinā sādhunindāvadhānyasvaharaṇādyaiśca sevitaiḥ" },
      { type: "verse", number: "3", sanskrit: "पाप्मभिः कर्मभिः सद्यः प्राक्तनैर्वेरिता मलाः सिराः प्रपद्य तिर्यग्गास्त्वग्लसीकासृगामिषम्", text: "pāpmabhiḥ karmabhiḥ sadyaḥ prāktanairveritā malāḥ sirāḥ prapadya tiryaggāstvaglasīkāsṛgāmiṣam" },
      { type: "verse", number: "4", sanskrit: "दूषयन्तः श्लथीकृत्य निश्चरन्तस्ततो बहिः त्वचः कुर्वन्ति वैवर्ण्यं दुष्टाः कुष्ठमुशन्ति तत्", text: "dūṣayantaḥ ślathīkṛtya niścarantastato bahiḥ tvacaḥ kurvanti vaivarṇyaṃ duṣṭāḥ kuṣṭhamuśanti tat" },
      { type: "verse", number: "5", sanskrit: "कालेनोपेक्षितं यस्मात् सर्वं कुष्णाति तद्वपुः प्रपद्य धातून्व्याप्यान्तः सर्वान्सङ्क्लेद्यचावहेत्", text: "kālenopekṣitaṃ yasmāt sarvaṃ kuṣṇāti tadvapuḥ prapadya dhātūnvyāpyāntaḥ sarvānsaṅkledyacāvahet" },
      { type: "verse", number: "6", sanskrit: "सस्वेदक्लेदसङ्कोथान् कृमीन् सूक्ष्मान् सुदारुणान् लोमत्वक्स्नायुधमनीतरुणास्थीनि यैः क्रमात्", text: "sasvedakledasaṅkothān kṛmīn sūkṣmān sudāruṇān lomatvaksnāyudhamanītaruṇāsthīni yaiḥ kramāt" },
      { type: "verse", number: "7", sanskrit: "भक्षयेत् श्वित्रमस्माच्च कुष्ठबाह्यमुदाहृतम् कुष्ठानि सप्तधा दोषैः पृथङ्मिश्रैः समागतैः", text: "bhakṣayet śvitramasmācca kuṣṭhabāhyamudāhṛtam kuṣṭhāni saptadhā doṣaiḥ pṛthaṅmiśraiḥ samāgataiḥ" },
      { type: "verse", number: "8", sanskrit: "सर्वेष्वपि त्रिदोषेषु व्यपदेशो ऽधिकत्वतः वातेन कुष्ठं कापालं पित्तादौदुम्बरं कफात्", text: "sarveṣvapi tridoṣeṣu vyapadeśo 'dhikatvataḥ vātena kuṣṭhaṃ kāpālaṃ pittādaudumbaraṃ kaphāt" },
      { type: "verse", number: "9", sanskrit: "मण्डलाख्यं विचर्ची च ऋष्याख्यं वातापित्तजम् चर्मैककुष्ठकिटिभसिध्मालसविपादिकाः", text: "maṇḍalākhyaṃ vicarcī ca ṛṣyākhyaṃ vātāpittajam carmaikakuṣṭhakiṭibhasidhmālasavipādikāḥ" },
      { type: "verse", number: "10", sanskrit: "वातश्लेष्मोद्भवाः श्लेष्मपित्ताद्दद्रुशतारुषी पुण्डरीकं सविस्फोटं पामा चर्मदलं तथा", text: "vātaśleṣmodbhavāḥ śleṣmapittāddadruśatāruṣī puṇḍarīkaṃ savisphoṭaṃ pāmā carmadalaṃ tathā" },
      { type: "verse", number: "11", sanskrit: "सर्वैः स्यात् काकणं पूर्वं त्रिकं दद्रु सकाकणम् पुण्डरीकर्ष्यजिह्वे च महाकुष्ठानि सप्त तु", text: "sarvaiḥ syāt kākaṇaṃ pūrvaṃ trikaṃ dadru sakākaṇam puṇḍarīkarṣyajihve ca mahākuṣṭhāni sapta tu" },
      { type: "verse", number: "12", sanskrit: "अतिश्लक्ष्णखरस्पर्शस्वेदास्वेदविवर्णताः दाहः कण्डूस्त्वचि स्वापस्तोदः कोठोन्नतिःश्रमः", text: "atiślakṣṇakharasparśasvedāsvedavivarṇatāḥ dāhaḥ kaṇḍūstvaci svāpastodaḥ koṭhonnatiḥśramaḥ" },
      { type: "verse", number: "13", sanskrit: "व्रणानामधिकं शूलं शीघ्नोत्पत्तिश्चिरस्थितिः रूढानामपि रूक्षत्वं निमित्ते ऽल्पे ऽपि कोथनम्", text: "vraṇānāmadhikaṃ śūlaṃ śīghnotpattiścirasthitiḥ rūḍhānāmapi rūkṣatvaṃ nimitte 'lpe 'pi kothanam" },
      { type: "verse", number: "14", sanskrit: "रोमहर्षो ऽसृजः कार्ष्ण्यं कुष्ठलक्षणमग्रजम् कृष्णारुणकपालाभं रूक्षं सुप्तं खरं तनु", text: "romaharṣo 'sṛjaḥ kārṣṇyaṃ kuṣṭhalakṣaṇamagrajam kṛṣṇāruṇakapālābhaṃ rūkṣaṃ suptaṃ kharaṃ tanu" },
      { type: "verse", number: "15", sanskrit: "विस्तृतासमपर्यन्तं हृषितैर्लोमभिश्चितम् तोदाढ्यमल्पकण्डूकं कापालं शीघ्रसर्पि च", text: "vistṛtāsamaparyantaṃ hṛṣitairlomabhiścitam todāḍhyamalpakaṇḍūkaṃ kāpālaṃ śīghrasarpi ca" },
      { type: "verse", number: "16", sanskrit: "पक्वोदुम्बरताम्रत्वग्रोमगौरसिराचितम् बहलं बहुलक्लेदं रक्तं दाहरुजाकरम्", text: "pakvodumbaratāmratvagromagaurasirācitam bahalaṃ bahulakledaṃ raktaṃ dāharujākaram" },
      { type: "verse", number: "17", sanskrit: "आशूत्थानावदरणकृमि विद्यादुदुम्बरम्", text: "āśūtthānāvadaraṇakṛmi vidyādudumbaram" },
      { type: "verse", number: "18", sanskrit: "स्थिरं स्त्यानं गुरु स्निग्धं श्वेतरक्तमनाशुगम् अन्योन्यासक्तमुत्सन्नं बहुकण्डूस्रुतिक्रिमि", text: "sthiraṃ styānaṃ guru snigdhaṃ śvetaraktamanāśugam anyonyāsaktamutsannaṃ bahukaṇḍūsrutikrimi" },
      { type: "verse", number: "19", sanskrit: "श्लक्ष्णपीताभपर्यन्तं मण्डलं परिमण्डलम् सकण्डूपिटका श्यावा लसीकाढ्या विचर्चिका", text: "ślakṣṇapītābhaparyantaṃ maṇḍalaṃ parimaṇḍalam sakaṇḍūpiṭakā śyāvā lasīkāḍhyā vicarcikā" },
      { type: "verse", number: "20", sanskrit: "परुषं तनुरक्तान्तमन्तःश्यावं समुन्नतम् सतोददाहरुक्क्लेदं कर्कशैः पिटकैश्चितम्", text: "paruṣaṃ tanuraktāntamantaḥśyāvaṃ samunnatam satodadāharukkledaṃ karkaśaiḥ piṭakaiścitam" },
      { type: "verse", number: "21", sanskrit: "ऋष्यजिह्वाकृति प्रोक्तमृष्यजिह्वं बहुक्रिमि हस्तिचर्मखरस्पर्शं चमकाख्यं महाश्रयम्", text: "ṛṣyajihvākṛti proktamṛṣyajihvaṃ bahukrimi hasticarmakharasparśaṃ camakākhyaṃ mahāśrayam" },
      { type: "verse", number: "22", sanskrit: "अस्वेदं मत्स्यशकलसन्निभं किटिभं पुनः रूक्षं किणखरस्पर्शं कण्डूमत् परुषासितम्", text: "asvedaṃ matsyaśakalasannibhaṃ kiṭibhaṃ punaḥ rūkṣaṃ kiṇakharasparśaṃ kaṇḍūmat paruṣāsitam" },
      { type: "verse", number: "23", sanskrit: "सिध्म रूक्षं बहिःस्निग्धमन्तर्घृष्टं रजः किरेत् श्लक्ष्णस्पर्शं तनुश्वेतताम्रं दौग्धिकपुष्पवत्", text: "sidhma rūkṣaṃ bahiḥsnigdhamantarghṛṣṭaṃ rajaḥ kiret ślakṣṇasparśaṃ tanuśvetatāmraṃ daugdhikapuṣpavat" },
      { type: "verse", number: "24", sanskrit: "प्रायेण चोर्ध्वकाये स्याद्गण्डैः कण्डूयुतैश्चितम् रक्तैरलसकं पाणिपाददार्यो विपादिकाः", text: "prāyeṇa cordhvakāye syādgaṇḍaiḥ kaṇḍūyutaiścitam raktairalasakaṃ pāṇipādadāryo vipādikāḥ" },
      { type: "verse", number: "25", sanskrit: "तीव्रार्त्यो मन्दकण्ड्वश्च सरागपिटकाचिताः दीर्घप्रताना दूर्वावदतसीकुसुमच्छविः", text: "tīvrārtyo mandakaṇḍvaśca sarāgapiṭakācitāḥ dīrghapratānā dūrvāvadatasīkusumacchaviḥ" },
      { type: "verse", number: "26", sanskrit: "उत्सन्नमण्डला दद्रुः कण्डूमत्यनुषङ्गिणी स्थूलमूलं सदाहार्ति रक्तश्यावं बहुव्रणम्", text: "utsannamaṇḍalā dadruḥ kaṇḍūmatyanuṣaṅgiṇī sthūlamūlaṃ sadāhārti raktaśyāvaṃ bahuvraṇam" },
      { type: "verse", number: "27", sanskrit: "शतारुः क्लेदजन्त्वाढ्यं प्रायशः पर्वजन्म च रक्तान्तमन्तरापाण्डुकण्डुदाहरुजान्वितम्", text: "śatāruḥ kledajantvāḍhyaṃ prāyaśaḥ parvajanma ca raktāntamantarāpāṇḍukaṇḍudāharujānvitam" },
      { type: "verse", number: "28", sanskrit: "सोत्सेधमाचितं रक्तैः पद्मपत्रमिवांशुभिः घनभूरिलसीकासृक्प्रायमाशु विभेदि च", text: "sotsedhamācitaṃ raktaiḥ padmapatramivāṃśubhiḥ ghanabhūrilasīkāsṛkprāyamāśu vibhedi ca" },
      { type: "verse", number: "29", sanskrit: "पुण्डरीकम् तनुत्वग्भिश्चितं स्फोटैः सितारुणैः विस्फोटं पिटकाः पामाकण्डूक्लेदरुजाधिकाः", text: "puṇḍarīkam tanutvagbhiścitaṃ sphoṭaiḥ sitāruṇaiḥ visphoṭaṃ piṭakāḥ pāmākaṇḍūkledarujādhikāḥ" },
      { type: "verse", number: "30", sanskrit: "सूक्ष्माः श्यावारुणा बहूव्यः प्रायः स्फिक्पाणिकूर्परे सस्फोटमस्पर्शसहं कण्डूषातोददाहवत्", text: "sūkṣmāḥ śyāvāruṇā bahūvyaḥ prāyaḥ sphikpāṇikūrpare sasphoṭamasparśasahaṃ kaṇḍūṣātodadāhavat" },
      { type: "verse", number: "31", sanskrit: "रक्तं दलच्चर्मदलं काकणं तीव्रदाहरुक् पूर्वं रक्तं च कृष्णं च काकणन्तीफलोपमम्", text: "raktaṃ dalaccarmadalaṃ kākaṇaṃ tīvradāharuk pūrvaṃ raktaṃ ca kṛṣṇaṃ ca kākaṇantīphalopamam" },
      { type: "verse", number: "32", sanskrit: "कुष्ठलिङ्गैर्युतं सर्वैर्नैकवर्णं ततो भवेत् दोषभेदीयविहितैरादिशेल्लिङ्गकर्मभिः", text: "kuṣṭhaliṅgairyutaṃ sarvairnaikavarṇaṃ tato bhavet doṣabhedīyavihitairādiśelliṅgakarmabhiḥ" },
      { type: "verse", number: "33", sanskrit: "कुष्ठेषु दोषोल्बणतां सर्वदोषोल्बणं त्यजेत् रिष्ठोक्तं यच्च यच्चास्थिमज्जशुक्रसमाश्रयम्", text: "kuṣṭheṣu doṣolbaṇatāṃ sarvadoṣolbaṇaṃ tyajet riṣṭhoktaṃ yacca yaccāsthimajjaśukrasamāśrayam" },
      { type: "verse", number: "34", sanskrit: "याप्यं मेदोगतं कृच्छ्रं पित्तद्वन्द्वास्रमांसगम् अकृच्छ्रं कफवाताढ्यं त्वक्स्थमेकमलं च यत्", text: "yāpyaṃ medogataṃ kṛcchraṃ pittadvandvāsramāṃsagam akṛcchraṃ kaphavātāḍhyaṃ tvaksthamekamalaṃ ca yat" },
      { type: "verse", number: "35", sanskrit: "तत्र त्वचि स्थिते कुष्ठे तोदवैवर्ण्यरूक्षताः स्वेदस्वापश्वयथवः शोणिते पिशिते पुनः", text: "tatra tvaci sthite kuṣṭhe todavaivarṇyarūkṣatāḥ svedasvāpaśvayathavaḥ śoṇite piśite punaḥ" },
      { type: "verse", number: "36", sanskrit: "पाणिपादाश्रिताः स्फोटाः क्लेदः सन्धिषु चाधिकम् कौण्यं गतिक्षयो ऽङ्गानां दलनं स्याच्च मेदसि", text: "pāṇipādāśritāḥ sphoṭāḥ kledaḥ sandhiṣu cādhikam kauṇyaṃ gatikṣayo 'ṅgānāṃ dalanaṃ syācca medasi" },
      { type: "verse", number: "37", sanskrit: "नासाभङ्गो ऽस्थिमज्जस्थे नेत्ररागः स्वरक्षयः क्षते च कृमयः शुक्रे स्वदारापत्यबाधनम्", text: "nāsābhaṅgo 'sthimajjasthe netrarāgaḥ svarakṣayaḥ kṣate ca kṛmayaḥ śukre svadārāpatyabādhanam" },
      { type: "verse", number: "38", sanskrit: "यथापूर्वं च सर्वाणि स्युर्लिङ्गान्यसृगादिषु कुष्ठैकसम्भवं श्वित्रं किलासं चारुणं च तत्", text: "yathāpūrvaṃ ca sarvāṇi syurliṅgānyasṛgādiṣu kuṣṭhaikasambhavaṃ śvitraṃ kilāsaṃ cāruṇaṃ ca tat" },
      { type: "verse", number: "39", sanskrit: "निर्दिष्टमपरिस्रावि त्रिधातूद्भवसंश्रयम्", text: "nirdiṣṭamaparisrāvi tridhātūdbhavasaṃśrayam" },
      { type: "verse", number: "40", sanskrit: "वाताद्रूक्षारुणं पित्तात्ताम्रं कमलपत्रवत् सदाहं रोमविध्वंसि कफाच्छ्वेतं घनं गुरु", text: "vātādrūkṣāruṇaṃ pittāttāmraṃ kamalapatravat sadāhaṃ romavidhvaṃsi kaphācchvetaṃ ghanaṃ guru" },
      { type: "verse", number: "41", sanskrit: "सकण्डु च क्रमाद्रक्तमांसमेदस्सु चादिशेत् वर्णेनैवेदृगुभयं कृच्छ्रं तच्चोत्तरोत्तरम्", text: "sakaṇḍu ca kramādraktamāṃsamedassu cādiśet varṇenaivedṛgubhayaṃ kṛcchraṃ taccottarottaram" },
      { type: "verse", number: "42", sanskrit: "अशुक्लरोमाबहुलमसंसृष्टं मिथो नवम् अनग्निदग्धजं साध्यं श्वित्रं वर्ज्यमतो ऽन्यथा", text: "aśuklaromābahulamasaṃsṛṣṭaṃ mitho navam anagnidagdhajaṃ sādhyaṃ śvitraṃ varjyamato 'nyathā" },
      { type: "verse", number: "43", sanskrit: "गुह्यपाणितलौष्ठेषु जातमप्यचिरन्तनम् स्पर्शैकाहारशय्यादिसेवनात् प्रायशो गदाः", text: "guhyapāṇitalauṣṭheṣu jātamapyacirantanam sparśaikāhāraśayyādisevanāt prāyaśo gadāḥ" },
      { type: "verse", number: "44", sanskrit: "सर्वे सञ्चारिणो नेत्रत्वग्विकारा विशेषतः कृमयस्तु द्विधा प्रोक्ता बाह्याभ्यन्तरभेदतः", text: "sarve sañcāriṇo netratvagvikārā viśeṣataḥ kṛmayastu dvidhā proktā bāhyābhyantarabhedataḥ" },
      { type: "verse", number: "45", sanskrit: "बहिर्मलकफासृग्विड्जन्मभेदाच्चतुर्विधाः नामतो विंशतिविधा बाह्यास्तत्रामृजोद्भवाः", text: "bahirmalakaphāsṛgviḍjanmabhedāccaturvidhāḥ nāmato viṃśatividhā bāhyāstatrāmṛjodbhavāḥ" },
      { type: "verse", number: "46", sanskrit: "तिलप्रमाणसंस्थानवर्णाः केशाम्बराश्रयाः बहुपादाश्च सूक्ष्माश्च यूका लिक्षाश्च नामतः", text: "tilapramāṇasaṃsthānavarṇāḥ keśāmbarāśrayāḥ bahupādāśca sūkṣmāśca yūkā likṣāśca nāmataḥ" },
      { type: "verse", number: "47", sanskrit: "द्विधा ते कोठपिटकाकण्डूगण्डान् प्रकुर्वते कुष्ठैकहेतवो ऽन्तर्जाः श्लेष्मजास्तेषु चाधिकम्", text: "dvidhā te koṭhapiṭakākaṇḍūgaṇḍān prakurvate kuṣṭhaikahetavo 'ntarjāḥ śleṣmajāsteṣu cādhikam" },
      { type: "verse", number: "48", sanskrit: "मधुरान्नगुडक्षीरदधिसक्तुनवोदनैः शकृज्जा बहुविड्धान्यपर्णशाकौकुलादिभिः", text: "madhurānnaguḍakṣīradadhisaktunavodanaiḥ śakṛjjā bahuviḍdhānyaparṇaśākaukulādibhiḥ" },
      { type: "verse", number: "49", sanskrit: "कफादामाशये जाता वृद्धाः सर्पन्ति सर्वतः पृथुव्रद्ध्ननिभाः केचित् केचित् गण्डूपदोपमाः", text: "kaphādāmāśaye jātā vṛddhāḥ sarpanti sarvataḥ pṛthuvraddhnanibhāḥ kecit kecit gaṇḍūpadopamāḥ" },
      { type: "verse", number: "50", sanskrit: "रूढधान्याङ्कुराकारास्तनुदीर्घास्तथाणवः श्वेतास्ताम्रावभासाश्च नामतः सप्तधा तु ते", text: "rūḍhadhānyāṅkurākārāstanudīrghāstathāṇavaḥ śvetāstāmrāvabhāsāśca nāmataḥ saptadhā tu te" },
      { type: "verse", number: "51", sanskrit: "अन्त्रादा उदरावेष्टा हृदयादा महारुहाः चुरवो दर्भकुसुमाः सुगन्धास्ते तु कुर्वते", text: "antrādā udarāveṣṭā hṛdayādā mahāruhāḥ curavo darbhakusumāḥ sugandhāste tu kurvate" },
      { type: "verse", number: "52", sanskrit: "हृल्लासमास्यस्रवणमविपाकमरोचकम् मूर्छाच्छर्दिज्वरानाहकार्श्यक्षवथुपीनसान्", text: "hṛllāsamāsyasravaṇamavipākamarocakam mūrchācchardijvarānāhakārśyakṣavathupīnasān" },
      { type: "verse", number: "53", sanskrit: "रक्तवाहिसिरास्थाना रक्तजा जन्तवो ऽणवः अपादा वृत्तताम्राश्च सौक्ष्म्यात् केचिददर्शनाः", text: "raktavāhisirāsthānā raktajā jantavo 'ṇavaḥ apādā vṛttatāmrāśca saukṣmyāt kecidadarśanāḥ" },
      { type: "verse", number: "54", sanskrit: "केशादा लोमविध्वंसा लोमद्वीपा उदुम्बराः षट् ते कुष्ठैककर्माणः सहसौरसमातरः", text: "keśādā lomavidhvaṃsā lomadvīpā udumbarāḥ ṣaṭ te kuṣṭhaikakarmāṇaḥ sahasaurasamātaraḥ" },
      { type: "verse", number: "55", sanskrit: "पक्वाशये पुरीषोत्था जायन्ते ऽधोविसर्पिणः वृद्धास्ते स्युर्भवेयुश्च ते यदामाशयोन्मुखाः", text: "pakvāśaye purīṣotthā jāyante 'dhovisarpiṇaḥ vṛddhāste syurbhaveyuśca te yadāmāśayonmukhāḥ" },
      { type: "verse", number: "56", sanskrit: "तदास्योद्गारनिश्वासा विड्गन्धानुविधायिनः पृथुवृत्ततनुस्थूलाः श्यावपीतसितासिताः", text: "tadāsyodgāraniśvāsā viḍgandhānuvidhāyinaḥ pṛthuvṛttatanusthūlāḥ śyāvapītasitāsitāḥ" },
      { type: "verse", number: "57", sanskrit: "ते पञ्च नाम्ना कृमयः ककेरुकमकेरुकाः सौसुरादाः सलूनाख्या लेलिहा जनयन्ति च", text: "te pañca nāmnā kṛmayaḥ kakerukamakerukāḥ sausurādāḥ salūnākhyā lelihā janayanti ca" },
      { type: "verse", number: "58", sanskrit: "विड्भेदशूलविष्टम्भकार्श्यपारुष्यपाण्डुताः रोमहर्षाग्निसदनगुदकण्डूर्विनिर्गमात्", text: "viḍbhedaśūlaviṣṭambhakārśyapāruṣyapāṇḍutāḥ romaharṣāgnisadanagudakaṇḍūrvinirgamāt" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 15,
    lang: "sa",
    content: [
      { type: "heading", heading: "Тришна нидана — жажда" },
      { type: "text", text: "Глава 15 Нидана стханы — диагностический раздел о жажда. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातो वातव्याधिनिदानं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vātavyādhinidānaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सर्वार्थानर्थकरणे विश्वस्यास्यैककारणम् अदुष्टदुष्टः पवनः शरीरस्य विशेषतः", text: "sarvārthānarthakaraṇe viśvasyāsyaikakāraṇam aduṣṭaduṣṭaḥ pavanaḥ śarīrasya viśeṣataḥ" },
      { type: "verse", number: "3", sanskrit: "स विश्वकर्मा विश्वात्मा विश्वरूपः प्रजापतिः स्रष्टा धाता विभुर्विष्णुः संहर्ता मृत्युरन्तकः", text: "sa viśvakarmā viśvātmā viśvarūpaḥ prajāpatiḥ sraṣṭā dhātā vibhurviṣṇuḥ saṃhartā mṛtyurantakaḥ" },
      { type: "verse", number: "4", sanskrit: "तददुष्टौ प्रयत्नेन यतितव्यमतः सदा तस्योक्तं दोषविज्ञाने कर्म प्राकृतवैकृतम्", text: "tadaduṣṭau prayatnena yatitavyamataḥ sadā tasyoktaṃ doṣavijñāne karma prākṛtavaikṛtam" },
      { type: "verse", number: "5", sanskrit: "समासाद्व्यासतो दोषभेदीये नाम धाम च प्रत्येकं पञ्चधा चारो व्यापारश्चेह वैकृतम्", text: "samāsādvyāsato doṣabhedīye nāma dhāma ca pratyekaṃ pañcadhā cāro vyāpāraśceha vaikṛtam" },
      { type: "verse", number: "6", sanskrit: "तस्योच्यते विभागेन सनिदानं सलक्षणम् असङ्ख्यमपि सङ्ख्यायै यदशीत्या पुरेरितम्", text: "tasyocyate vibhāgena sanidānaṃ salakṣaṇam asaṅkhyamapi saṅkhyāyai yadaśītyā pureritam" },
      { type: "verse", number: "7", sanskrit: "धातुक्षयकरैर्वायुः कुप्यत्यतिनिषोवितैः चरन् स्रोतःसु रिक्तेषु भृशं तान्येव पूरयन्", text: "dhātukṣayakarairvāyuḥ kupyatyatiniṣovitaiḥ caran srotaḥsu rikteṣu bhṛśaṃ tānyeva pūrayan" },
      { type: "verse", number: "8", sanskrit: "तेभ्यो ऽन्यदोषपूर्णेभ्यः प्राप्य वावरणं बली तत्र पक्वाशयं क्रुद्धः शूलानाहान्त्रकुजनम्", text: "tebhyo 'nyadoṣapūrṇebhyaḥ prāpya vāvaraṇaṃ balī tatra pakvāśayaṃ kruddhaḥ śūlānāhāntrakujanam" },
      { type: "verse", number: "9", sanskrit: "मलरोधाश्मवर्ध्मार्शस्त्रिकपृष्ठकटीग्रहम् करोत्यधरकाये च तांस्तान् कृच्छ्रानुपद्रवान्", text: "malarodhāśmavardhmārśastrikapṛṣṭhakaṭīgraham karotyadharakāye ca tāṃstān kṛcchrānupadravān" },
      { type: "verse", number: "10", sanskrit: "आमाशये तृड्वमथुश्वासकासविषूचिकाः कण्ठोपरोधमुद्गारान् व्याधीनूर्ध्वं च नाभितः", text: "āmāśaye tṛḍvamathuśvāsakāsaviṣūcikāḥ kaṇṭhoparodhamudgārān vyādhīnūrdhvaṃ ca nābhitaḥ" },
      { type: "verse", number: "11", sanskrit: "श्रोत्रादिष्विन्द्रियवधं त्वचि स्फुटनरूक्षते रक्ते तीव्रां रुजां स्वापं तापं रागं विवर्णताम्", text: "śrotrādiṣvindriyavadhaṃ tvaci sphuṭanarūkṣate rakte tīvrāṃ rujāṃ svāpaṃ tāpaṃ rāgaṃ vivarṇatām" },
      { type: "verse", number: "12", sanskrit: "अरुंष्यन्नस्य विष्टम्भमरुचिं कृशतां भ्रमम् मांसमेदोगतो ग्रन्थींस्तोदाढ्यान् कर्कशान् भ्रमम्", text: "aruṃṣyannasya viṣṭambhamaruciṃ kṛśatāṃ bhramam māṃsamedogato granthīṃstodāḍhyān karkaśān bhramam" },
      { type: "verse", number: "13", sanskrit: "गुर्वङ्गं चातिरुक् स्तब्धं मुष्टिदण्डहतोपमम् अस्थिस्थः सक्थिसन्ध्यस्थिशूलं तीव्रं बलक्षयम्", text: "gurvaṅgaṃ cātiruk stabdhaṃ muṣṭidaṇḍahatopamam asthisthaḥ sakthisandhyasthiśūlaṃ tīvraṃ balakṣayam" },
      { type: "verse", number: "14", sanskrit: "मज्जस्थो ऽस्थिषु सौषिर्यमस्वप्नं सन्ततं रुजम् शुक्रस्य शीघ्रमुत्सर्गं सङ्गं विकृतिमेव वा", text: "majjastho 'sthiṣu sauṣiryamasvapnaṃ santataṃ rujam śukrasya śīghramutsargaṃ saṅgaṃ vikṛtimeva vā" },
      { type: "verse", number: "15", sanskrit: "तद्वद्गर्भस्य शुक्रस्थः सिरास्वाध्मानरिक्तते तत्स्थः स्नावस्थितः कुर्यात्गृध्रस्यायामकुब्जताः", text: "tadvadgarbhasya śukrasthaḥ sirāsvādhmānariktate tatsthaḥ snāvasthitaḥ kuryātgṛdhrasyāyāmakubjatāḥ" },
      { type: "verse", number: "16", sanskrit: "वातपूर्णदृतिस्पर्शं शोफं सन्धिगतो ऽनिलः प्रसारणाकुञ्चनयोः प्रवृत्तिं च सवेदनाम्", text: "vātapūrṇadṛtisparśaṃ śophaṃ sandhigato 'nilaḥ prasāraṇākuñcanayoḥ pravṛttiṃ ca savedanām" },
      { type: "verse", number: "17", sanskrit: "सर्वाङ्गसंश्रयस्तोदभेदस्फुरणभञ्जनम् स्तम्भनाक्षेपणस्वापसन्ध्याकुञ्चनकम्पनम्", text: "sarvāṅgasaṃśrayastodabhedasphuraṇabhañjanam stambhanākṣepaṇasvāpasandhyākuñcanakampanam" },
      { type: "verse", number: "18", sanskrit: "यदा तु धमनीः सर्वाः क्रुद्धो ऽभ्येति मुहुर्मुहुः तदाङ्गमाक्षिपत्येष व्याधिराक्षेपकः स्मृतः", text: "yadā tu dhamanīḥ sarvāḥ kruddho 'bhyeti muhurmuhuḥ tadāṅgamākṣipatyeṣa vyādhirākṣepakaḥ smṛtaḥ" },
      { type: "verse", number: "19", sanskrit: "अधःप्रतिहतो वायुर्व्रजन्नूर्ध्वं हृदाश्रिताः नाडीः प्रविश्य हृदयं शिरः शङ्खौ च पीडयन्", text: "adhaḥpratihato vāyurvrajannūrdhvaṃ hṛdāśritāḥ nāḍīḥ praviśya hṛdayaṃ śiraḥ śaṅkhau ca pīḍayan" },
      { type: "verse", number: "20", sanskrit: "आक्षिपेत् परितो गात्रं धनुर्वच्चास्य नामयेत् कृच्छ्रादुच्छ्वसिति स्तब्धस्रस्तमीलितदृक् ततः", text: "ākṣipet parito gātraṃ dhanurvaccāsya nāmayet kṛcchrāducchvasiti stabdhasrastamīlitadṛk tataḥ" },
      { type: "verse", number: "21", sanskrit: "कपोत इव कूजेच्च निस्संज्ञः सो ऽपतन्त्रकः", text: "kapota iva kūjecca nissaṃjñaḥ so 'patantrakaḥ" },
      { type: "verse", number: "22", sanskrit: "स एव चापतानाख्यो मुक्ते तु मरुता हृदि अश्नुवीत मुहुः स्वास्थ्यं मुहुरस्वास्थ्यमावृते", text: "sa eva cāpatānākhyo mukte tu marutā hṛdi aśnuvīta muhuḥ svāsthyaṃ muhurasvāsthyamāvṛte" },
      { type: "verse", number: "23", sanskrit: "गर्भपातसमुत्पन्नः शोणितातिस्रवोत्थितः अभिघातसमुत्थश्च दुश्चिकित्स्यतमो हि सः", text: "garbhapātasamutpannaḥ śoṇitātisravotthitaḥ abhighātasamutthaśca duścikitsyatamo hi saḥ" },
      { type: "verse", number: "24", sanskrit: "मन्ये संस्तभ्य वातो ऽन्तरायच्छन् धमनीर्यदा व्याप्नोति सकलं देहं जत्रुरायम्यते तदा", text: "manye saṃstabhya vāto 'ntarāyacchan dhamanīryadā vyāpnoti sakalaṃ dehaṃ jatrurāyamyate tadā" },
      { type: "verse", number: "25", sanskrit: "अन्तर्धनुरिवाङ्गं च वेगैः स्तम्भं च नेत्रयोः करोति जृम्भां दशनं दशनानां कफोद्वमम्", text: "antardhanurivāṅgaṃ ca vegaiḥ stambhaṃ ca netrayoḥ karoti jṛmbhāṃ daśanaṃ daśanānāṃ kaphodvamam" },
      { type: "verse", number: "26", sanskrit: "पार्श्वयोर्वेदनां वाक्यहनुपृष्ठशिरोग्रहत् अन्तरायाम इत्येष बाह्यायामश्च तद्विधः", text: "pārśvayorvedanāṃ vākyahanupṛṣṭhaśirograhat antarāyāma ityeṣa bāhyāyāmaśca tadvidhaḥ" },
      { type: "verse", number: "27", sanskrit: "देहस्यबहिरायामात् पृष्ठतो ह्रियते शिरः उरश्चेत्क्षिप्यते तत्र कन्धरा चावमृद्यते", text: "dehasyabahirāyāmāt pṛṣṭhato hriyate śiraḥ uraścetkṣipyate tatra kandharā cāvamṛdyate" },
      { type: "verse", number: "28", sanskrit: "दन्तेष्वास्ये च वैवर्ण्यं प्रस्वेदः स्तब्धगात्रता बाह्यायामं धनुष्कम्पं ब्रुवते वेगिनं च तम्", text: "danteṣvāsye ca vaivarṇyaṃ prasvedaḥ stabdhagātratā bāhyāyāmaṃ dhanuṣkampaṃ bruvate veginaṃ ca tam" },
      { type: "verse", number: "29", sanskrit: "व्रणं मर्माश्रितं प्राप्य समीरणसमीरणात् व्यायच्छन्ति तनुं दोषाः सर्वामापादमस्तकम्", text: "vraṇaṃ marmāśritaṃ prāpya samīraṇasamīraṇāt vyāyacchanti tanuṃ doṣāḥ sarvāmāpādamastakam" },
      { type: "verse", number: "30", sanskrit: "तृष्यतः पाण्डुगात्रस्य व्रणायामः स वर्जितः गते वेगे भवेत् स्वास्थ्यं सर्वेष्वाक्षेपकेषु तु", text: "tṛṣyataḥ pāṇḍugātrasya vraṇāyāmaḥ sa varjitaḥ gate vege bhavet svāsthyaṃ sarveṣvākṣepakeṣu tu" },
      { type: "verse", number: "31", sanskrit: "जिह्वातिलेखनाच्छुष्कभक्षणादभिघाततः कुपितो हनुमूलस्थः स्रंसयित्वानिलो हनू", text: "jihvātilekhanācchuṣkabhakṣaṇādabhighātataḥ kupito hanumūlasthaḥ sraṃsayitvānilo hanū" },
      { type: "verse", number: "32", sanskrit: "करोति विवृतास्यत्वमथवा संवृतास्यताम् हनुस्रंसः स तेन स्यात् कृच्छ्राच्चर्वणभाषणम्", text: "karoti vivṛtāsyatvamathavā saṃvṛtāsyatām hanusraṃsaḥ sa tena syāt kṛcchrāccarvaṇabhāṣaṇam" },
      { type: "verse", number: "33", sanskrit: "वाग्वाहिनीसिरासंस्थो जिह्वां स्तम्भयते ऽनिलः जिह्वास्तम्भः स तेनान्नपानवाक्येष्वनीशता", text: "vāgvāhinīsirāsaṃstho jihvāṃ stambhayate 'nilaḥ jihvāstambhaḥ sa tenānnapānavākyeṣvanīśatā" },
      { type: "verse", number: "34", sanskrit: "शिरसा भारभरणादतिहास्यप्रभाषणात् उत्त्रासवक्रक्षवथुखरकार्मुककर्षणात्", text: "śirasā bhārabharaṇādatihāsyaprabhāṣaṇāt uttrāsavakrakṣavathukharakārmukakarṣaṇāt" },
      { type: "verse", number: "35", sanskrit: "विषमादुपधानाच्च कठिनानां च चर्वणात् वायुर्विवृद्धस्तैस्तैश्च वातलैरूर्ध्वमास्थितः", text: "viṣamādupadhānācca kaṭhinānāṃ ca carvaṇāt vāyurvivṛddhastaistaiśca vātalairūrdhvamāsthitaḥ" },
      { type: "verse", number: "36", sanskrit: "वक्रीकरोति वक्त्रार्धमुक्तं हसितमीक्षितम् ततो ऽस्य कम्पते मुर्धा वाक्सङ्गः स्तब्धनेत्रता", text: "vakrīkaroti vaktrārdhamuktaṃ hasitamīkṣitam tato 'sya kampate murdhā vāksaṅgaḥ stabdhanetratā" },
      { type: "verse", number: "37", sanskrit: "दन्तचालः स्वरभ्रंशः श्रुतिहानिः क्षवग्रहः गन्धाज्ञानं स्मृतेर्मोषस्त्रासः सुप्तस्य जायते", text: "dantacālaḥ svarabhraṃśaḥ śrutihāniḥ kṣavagrahaḥ gandhājñānaṃ smṛtermoṣastrāsaḥ suptasya jāyate" },
      { type: "verse", number: "38", sanskrit: "निष्ठीवः पार्श्वतो यायादेकस्याक्ष्णोर्निमीलनम् जत्रोरूर्धवं रुजास्तीव्राः शरीरार्धे ऽधरे ऽपि वा", text: "niṣṭhīvaḥ pārśvato yāyādekasyākṣṇornimīlanam jatrorūrdhavaṃ rujāstīvrāḥ śarīrārdhe 'dhare 'pi vā" },
      { type: "verse", number: "39", sanskrit: "तमाहुरर्दितं केचिदेकायाममथापरे रक्तमाश्रित्य पवनः कुर्यान्मूर्धधराः सिराः", text: "tamāhurarditaṃ kecidekāyāmamathāpare raktamāśritya pavanaḥ kuryānmūrdhadharāḥ sirāḥ" },
      { type: "verse", number: "40", sanskrit: "रूक्षाः सवेदनाः कृष्णाः सो ऽसाध्यः स्यात् सिराग्रहः गृहीत्वार्धं तनोर्वायुः सिराः स्नायूर्विशोष्य च", text: "rūkṣāḥ savedanāḥ kṛṣṇāḥ so 'sādhyaḥ syāt sirāgrahaḥ gṛhītvārdhaṃ tanorvāyuḥ sirāḥ snāyūrviśoṣya ca" },
      { type: "verse", number: "41", sanskrit: "पक्षमन्यतरं हन्ति सन्धिबन्धान् विमोक्षयन् कृत्स्नो ऽर्धकायस्तस्य स्यादकर्मण्यो विचेतनः", text: "pakṣamanyataraṃ hanti sandhibandhān vimokṣayan kṛtsno 'rdhakāyastasya syādakarmaṇyo vicetanaḥ" },
      { type: "verse", number: "42", sanskrit: "एकाङ्गरोगं तं केचिदन्ये पक्षवधं विदुः सर्वाङ्गरोगं तद्वच्च सर्वकायाश्रिते ऽनिले", text: "ekāṅgarogaṃ taṃ kecidanye pakṣavadhaṃ viduḥ sarvāṅgarogaṃ tadvacca sarvakāyāśrite 'nile" },
      { type: "verse", number: "43", sanskrit: "शुद्धवातहतः पक्षः कृच्छ्रसाध्यतमो मतः कृच्छ्रस्त्वन्येन संसृष्टो विवर्ज्यः क्षतहेतुकः", text: "śuddhavātahataḥ pakṣaḥ kṛcchrasādhyatamo mataḥ kṛcchrastvanyena saṃsṛṣṭo vivarjyaḥ kṣatahetukaḥ" },
      { type: "verse", number: "44", sanskrit: "आमबद्धायनः कुर्यात् संस्तभ्याङ्गं कफान्वितः असाध्यं हतसर्वेहं दण्डवद्दण्डकं मरुत्", text: "āmabaddhāyanaḥ kuryāt saṃstabhyāṅgaṃ kaphānvitaḥ asādhyaṃ hatasarvehaṃ daṇḍavaddaṇḍakaṃ marut" },
      { type: "verse", number: "45", sanskrit: "अंसमूलस्थितो वायुः सिराः सङ्कोच्य तत्रगाः बाहुप्रस्पन्दितहरं जनयत्यपवाहुकम्", text: "aṃsamūlasthito vāyuḥ sirāḥ saṅkocya tatragāḥ bāhupraspanditaharaṃ janayatyapavāhukam" },
      { type: "verse", number: "46", sanskrit: "तलं प्रत्यङ्गुलीनां या कण्डरा बाहुपृष्ठतः बाहुचेष्टापहरणी विश्वाची नाम सा स्मृता", text: "talaṃ pratyaṅgulīnāṃ yā kaṇḍarā bāhupṛṣṭhataḥ bāhuceṣṭāpaharaṇī viśvācī nāma sā smṛtā" },
      { type: "verse", number: "47", sanskrit: "वायुःकट्यां स्थितः सक्थ्नः कण्डरामाक्षिपेद्यदा तदा खञ्जो भवेज्जन्तुः पङ्गुः सक्थ्नोर्द्वयोरपि", text: "vāyuḥkaṭyāṃ sthitaḥ sakthnaḥ kaṇḍarāmākṣipedyadā tadā khañjo bhavejjantuḥ paṅguḥ sakthnordvayorapi" },
      { type: "verse", number: "48", sanskrit: "कम्पते गमनारम्भे खञ्जन्निव च याति यः कलायखञ्जं तं विद्यान्मुक्तसन्धिप्रबन्धनम्", text: "kampate gamanārambhe khañjanniva ca yāti yaḥ kalāyakhañjaṃ taṃ vidyānmuktasandhiprabandhanam" },
      { type: "verse", number: "49", sanskrit: "शीतोष्णद्रवसंशुष्कगुरुस्निग्धैर्निषेवितैः जीर्णाजीर्णे तथायाससङ्क्षोभस्वप्नजागरैः", text: "śītoṣṇadravasaṃśuṣkagurusnigdhairniṣevitaiḥ jīrṇājīrṇe tathāyāsasaṅkṣobhasvapnajāgaraiḥ" },
      { type: "verse", number: "50", sanskrit: "सश्लेष्ममेदःपवनमाममत्यर्थसञ्चितम् अभिभूयेतरं दोषमुरू चेत् प्रतिपद्यते", text: "saśleṣmamedaḥpavanamāmamatyarthasañcitam abhibhūyetaraṃ doṣamurū cet pratipadyate" },
      { type: "verse", number: "51", sanskrit: "सक्थ्यास्थना प्रपूर्यान्तः श्लेष्मणा स्तिमितेन तत् तदा स्तभ्नाति तेनोरू स्तब्धौ शीतावचेतनौ", text: "sakthyāsthanā prapūryāntaḥ śleṣmaṇā stimitena tat tadā stabhnāti tenorū stabdhau śītāvacetanau" },
      { type: "verse", number: "52", sanskrit: "परकीयाविव गुरू स्यातामतिभृशव्यथौ ध्यानाङ्गमर्दस्तैमित्यतन्द्राच्छर्द्यरुचिज्वरैः", text: "parakīyāviva gurū syātāmatibhṛśavyathau dhyānāṅgamardastaimityatandrācchardyarucijvaraiḥ" },
      { type: "verse", number: "53", sanskrit: "संयुतः पादसदनकृच्छ्रोद्धरणसुप्तिभिः तमूरुस्तम्भमित्याहुराढ्यवातमथापरे", text: "saṃyutaḥ pādasadanakṛcchroddharaṇasuptibhiḥ tamūrustambhamityāhurāḍhyavātamathāpare" },
      { type: "verse", number: "54", sanskrit: "वातशोणितजः शोफो जानुमध्ये महारुजः ज्ञेयः क्रोष्टुकणीर्षस्तु स्थूलः क्रोष्टुकशीर्षवत्", text: "vātaśoṇitajaḥ śopho jānumadhye mahārujaḥ jñeyaḥ kroṣṭukaṇīrṣastu sthūlaḥ kroṣṭukaśīrṣavat" },
      { type: "verse", number: "55", sanskrit: "रुक् पादे विषमन्यस्ते श्रमाद्वा जायते यदा वातेन गुल्फमाश्रित्य तमाहुर्वातकण्टकम्", text: "ruk pāde viṣamanyaste śramādvā jāyate yadā vātena gulphamāśritya tamāhurvātakaṇṭakam" },
      { type: "verse", number: "56", sanskrit: "पार्ष्णि प्रत्यङ्गुलीनां या कण्डरा मारुतार्दिता सक्थ्युत्क्षेपं निगृह्णाति गृध्रसीं तां प्रचक्षते", text: "pārṣṇi pratyaṅgulīnāṃ yā kaṇḍarā mārutārditā sakthyutkṣepaṃ nigṛhṇāti gṛdhrasīṃ tāṃ pracakṣate" },
      { type: "verse", number: "57", sanskrit: "विश्वाची गृद्ध्रसी चोक्ता खल्ली तीव्ररुजान्विता हृष्येते चरणौ यस्य भ्वेतां च प्रसुप्तवत्", text: "viśvācī gṛddhrasī coktā khallī tīvrarujānvitā hṛṣyete caraṇau yasya bhvetāṃ ca prasuptavat" },
      { type: "verse", number: "58", sanskrit: "पादहर्षः स विज्ञेयः कफमारुतकोपजः पादयोः कुरुते दाहं पित्तासृकसहितो ऽनिलः", text: "pādaharṣaḥ sa vijñeyaḥ kaphamārutakopajaḥ pādayoḥ kurute dāhaṃ pittāsṛkasahito 'nilaḥ" },
      { type: "verse", number: "59", sanskrit: "विशेषतश्चङ्क्रमिते पाददाहं तमादिशेत्", text: "viśeṣataścaṅkramite pādadāhaṃ tamādiśet" },
    ],
  },
  {
    sthana: "Нидана стхана",
    number: 16,
    lang: "sa",
    content: [
      { type: "heading", heading: "Нидана самапти — завершение Нидана стханы" },
      { type: "text", text: "Глава 16 Нидана стханы — диагностический раздел о завершение Нидана стханы. Астанга-санграха дополняет диагностику Чараки и Мадхавакары практическими критериями." },
      { type: "verse", number: "1", sanskrit: "अथातो वातशोणितनिदानं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vātaśoṇitanidānaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "विदाह्यन्नं विरुद्धं च तत्तच्चासृक्प्रदूषणम् भजतां विधिहीनं च स्वप्नजागरमैथुनम्", text: "vidāhyannaṃ viruddhaṃ ca tattaccāsṛkpradūṣaṇam bhajatāṃ vidhihīnaṃ ca svapnajāgaramaithunam" },
      { type: "verse", number: "3", sanskrit: "प्रायेण सुकुमारणामचङ्क्रमणशीलिनाम् अभिघातादशुद्धेश्च नृणामसृजि दूषिते", text: "prāyeṇa sukumāraṇāmacaṅkramaṇaśīlinām abhighātādaśuddheśca nṛṇāmasṛji dūṣite" },
      { type: "verse", number: "4", sanskrit: "वातलैः शीतलैर्वायुर्वृद्धः क्रुद्धो विमार्गगः तादृशेनासृजा रुद्धः प्राक्तदेव प्रदूषयेत्", text: "vātalaiḥ śītalairvāyurvṛddhaḥ kruddho vimārgagaḥ tādṛśenāsṛjā ruddhaḥ prāktadeva pradūṣayet" },
      { type: "verse", number: "5", sanskrit: "आढ्यरोगं खुडं वातबलासं वातशोणितम् तदाहुर्नामभिस्तच्च पूर्वं पादौ प्रधावति", text: "āḍhyarogaṃ khuḍaṃ vātabalāsaṃ vātaśoṇitam tadāhurnāmabhistacca pūrvaṃ pādau pradhāvati" },
      { type: "verse", number: "6", sanskrit: "विशेषाद्यानयानाद्यैः प्रलम्बौ तस्य लक्षणम् भविष्यतः कुष्ठसमं तथा सादः श्लथाङ्गता", text: "viśeṣādyānayānādyaiḥ pralambau tasya lakṣaṇam bhaviṣyataḥ kuṣṭhasamaṃ tathā sādaḥ ślathāṅgatā" },
      { type: "verse", number: "7", sanskrit: "जानुजङ्घोरुकट्यंसहस्तपादाङ्गसन्धिषु कण्डूस्फुरणनिस्तोदभेदगौरवसुप्तताः", text: "jānujaṅghorukaṭyaṃsahastapādāṅgasandhiṣu kaṇḍūsphuraṇanistodabhedagauravasuptatāḥ" },
      { type: "verse", number: "8", sanskrit: "भूत्वा भूत्वा प्रणश्यन्ति मुहुराविर्भवन्ति च पादयोर्मूलमास्थाय कदाचिद्धस्तयोरपि", text: "bhūtvā bhūtvā praṇaśyanti muhurāvirbhavanti ca pādayormūlamāsthāya kadāciddhastayorapi" },
      { type: "verse", number: "9", sanskrit: "आखोरिव विषं क्रुद्धं कृत्स्नं देहं प्रधावति त्वङ्मांसाश्रयमुत्तानं तत् पूर्वं जायते ततः", text: "ākhoriva viṣaṃ kruddhaṃ kṛtsnaṃ dehaṃ pradhāvati tvaṅmāṃsāśrayamuttānaṃ tat pūrvaṃ jāyate tataḥ" },
      { type: "verse", number: "10", sanskrit: "कालान्तरेण गम्भीरं सर्वान् धातूनाभिद्रवत् कण्ड्वादिसंयुतोत्ताने त्वक् ताम्रश्यावलोहिता", text: "kālāntareṇa gambhīraṃ sarvān dhātūnābhidravat kaṇḍvādisaṃyutottāne tvak tāmraśyāvalohitā" },
      { type: "verse", number: "11", sanskrit: "सायामा भृशदाहोषा गम्भीरे ऽधिकपूर्वरुक् श्वयथुर्ग्रथितः पाकी सन्ध्यस्थिमज्जसु", text: "sāyāmā bhṛśadāhoṣā gambhīre 'dhikapūrvaruk śvayathurgrathitaḥ pākī sandhyasthimajjasu" },
      { type: "verse", number: "12", sanskrit: "भिन्दन्निव चरत्यन्तर्वक्रीकुवश्च वेगवान् करोति खञ्जं पङ्गुं वा शरीरे सर्वतश्चरन्", text: "bhindanniva caratyantarvakrīkuvaśca vegavān karoti khañjaṃ paṅguṃ vā śarīre sarvataścaran" },
      { type: "verse", number: "13", sanskrit: "वाते ऽधिके ऽधिकं तत्र शूलस्फुरणतोदनम् शोफस्य रौक्ष्यकृष्णत्वश्यावतावृद्धिहानयः", text: "vāte 'dhike 'dhikaṃ tatra śūlasphuraṇatodanam śophasya raukṣyakṛṣṇatvaśyāvatāvṛddhihānayaḥ" },
      { type: "verse", number: "14", sanskrit: "धमन्यङ्गुलिसन्धीनां सङ्कोचो ऽङ्गग्रहो ऽतिरुक् शीतद्वेषानुपशयौ स्तम्भवेपथुसुप्तयः", text: "dhamanyaṅgulisandhīnāṃ saṅkoco 'ṅgagraho 'tiruk śītadveṣānupaśayau stambhavepathusuptayaḥ" },
      { type: "verse", number: "15", sanskrit: "रक्ते शोफो ऽतिरुक् तोदस्ताम्रश्चिमिचिमायते स्निग्धरूक्षैः शमं नैति कण्डूक्लेदसमन्वितः", text: "rakte śopho 'tiruk todastāmraścimicimāyate snigdharūkṣaiḥ śamaṃ naiti kaṇḍūkledasamanvitaḥ" },
      { type: "verse", number: "16", sanskrit: "पित्ते विदाहःसम्मोहः स्वेदो मूर्छा मदः सतृट् स्पर्शाक्षमत्वं रुग्रागः शोफः पाको भृशोष्मता", text: "pitte vidāhaḥsammohaḥ svedo mūrchā madaḥ satṛṭ sparśākṣamatvaṃ rugrāgaḥ śophaḥ pāko bhṛśoṣmatā" },
      { type: "verse", number: "17", sanskrit: "कफे स्तैमित्यगुरुतासुप्तिस्निग्धत्वशीतताः कण्डूर्मन्दा च रुग्द्वन्द्वसर्वलिङ्गं च सङ्करे", text: "kaphe staimityagurutāsuptisnigdhatvaśītatāḥ kaṇḍūrmandā ca rugdvandvasarvaliṅgaṃ ca saṅkare" },
      { type: "verse", number: "18", sanskrit: "एकदोषानुगं साध्यं नवं याप्यं द्विदोषजम् त्रिदोषजं त्यजेत् स्रावि स्तब्धमर्बुदकारि च", text: "ekadoṣānugaṃ sādhyaṃ navaṃ yāpyaṃ dvidoṣajam tridoṣajaṃ tyajet srāvi stabdhamarbudakāri ca" },
      { type: "verse", number: "19", sanskrit: "रक्तमार्गं निहन्त्याशु शाखासन्धिषु मारुतः निविश्यान्योन्यमावार्य वेदनाभिर्हरत्यसून्", text: "raktamārgaṃ nihantyāśu śākhāsandhiṣu mārutaḥ niviśyānyonyamāvārya vedanābhirharatyasūn" },
      { type: "verse", number: "20", sanskrit: "वायौ पञ्चात्मके प्राणो रौक्ष्यव्यायामलङ्घनैः अत्याहाराभिघाताध्ववेगोदीरणधारणैः", text: "vāyau pañcātmake prāṇo raukṣyavyāyāmalaṅghanaiḥ atyāhārābhighātādhvavegodīraṇadhāraṇaiḥ" },
      { type: "verse", number: "21", sanskrit: "कुपितश्चक्षुरादीनामुपघातं प्रवर्तयेत् पीनसार्दिततृट्कासश्वासादींश्चामयान्बहून्", text: "kupitaścakṣurādīnāmupaghātaṃ pravartayet pīnasārditatṛṭkāsaśvāsādīṃścāmayānbahūn" },
      { type: "verse", number: "22", sanskrit: "उदानः क्षवथूद्गारच्छर्दिनिद्राविधारणैः गुरुभारातिरुदितहास्याद्यैर्विकृतो गदान्", text: "udānaḥ kṣavathūdgāracchardinidrāvidhāraṇaiḥ gurubhārātiruditahāsyādyairvikṛto gadān" },
      { type: "verse", number: "23", sanskrit: "कण्ठरोधमनोभ्रंशच्छर्द्यरोचकपनिसान् कुर्याच्च गलगण्डादीन्तांतान्जत्रूर्ध्वसंश्रयान्", text: "kaṇṭharodhamanobhraṃśacchardyarocakapanisān kuryācca galagaṇḍādīntāṃtānjatrūrdhvasaṃśrayān" },
      { type: "verse", number: "24", sanskrit: "व्यानो ऽतिगमनस्थानक्रीडाविषमचेष्टितैः विरोधिरूक्षभीहर्षविषादाद्यैश्च दूषितः", text: "vyāno 'tigamanasthānakrīḍāviṣamaceṣṭitaiḥ virodhirūkṣabhīharṣaviṣādādyaiśca dūṣitaḥ" },
      { type: "verse", number: "25", sanskrit: "पुंस्त्वोत्साहबलभ्रंशशोफचित्तोत्प्लवज्वरान् सर्वाङ्गरोगनिस्तोदरोमहर्षाङ्गसुप्तताः", text: "puṃstvotsāhabalabhraṃśaśophacittotplavajvarān sarvāṅgaroganistodaromaharṣāṅgasuptatāḥ" },
      { type: "verse", number: "26", sanskrit: "कुष्ठं विसर्पमन्यांश्च कुर्यात्सर्वाङ्गगान् गदान् समानो विषमाजीर्णशीतसङ्कीर्णभोजनैः", text: "kuṣṭhaṃ visarpamanyāṃśca kuryātsarvāṅgagān gadān samāno viṣamājīrṇaśītasaṅkīrṇabhojanaiḥ" },
      { type: "verse", number: "27", sanskrit: "करोत्यकालशयनजागराद्यैश्च दूषितः शूलगुल्मग्रहण्यादीन् पक्वामाश्यजान् गदान्", text: "karotyakālaśayanajāgarādyaiśca dūṣitaḥ śūlagulmagrahaṇyādīn pakvāmāśyajān gadān" },
      { type: "verse", number: "28", sanskrit: "अपानो रूक्षगुर्वन्नवेगाघातातिवाहनैः यानयानासनस्थानचङ्क्रमैश्चातिसेवितैः", text: "apāno rūkṣagurvannavegāghātātivāhanaiḥ yānayānāsanasthānacaṅkramaiścātisevitaiḥ" },
      { type: "verse", number: "29", sanskrit: "कुपितः कुरुते रोगान्कृच्छ्रान्पक्वाशयाश्रयान् मूत्रशुक्रप्रदोषार्शोगुदभ्रंशादिकान् बहून्", text: "kupitaḥ kurute rogānkṛcchrānpakvāśayāśrayān mūtraśukrapradoṣārśogudabhraṃśādikān bahūn" },
      { type: "verse", number: "30", sanskrit: "सर्वं च मारुतं सामं तन्द्रास्तैमित्यगौरवैः स्निग्धत्वारोचकालस्यशैत्यशोफाग्निहानिभिः", text: "sarvaṃ ca mārutaṃ sāmaṃ tandrāstaimityagauravaiḥ snigdhatvārocakālasyaśaityaśophāgnihānibhiḥ" },
      { type: "verse", number: "31", sanskrit: "कटुरूक्षाभिलाषेण तद्विधोपशयेन च युक्तं विद्यान्निरामं तु तन्द्रादीनां विपर्ययात्", text: "kaṭurūkṣābhilāṣeṇa tadvidhopaśayena ca yuktaṃ vidyānnirāmaṃ tu tandrādīnāṃ viparyayāt" },
      { type: "verse", number: "32", sanskrit: "वायोरावरणं चातो बहुभेदं प्रवक्ष्यते लिङ्गं पित्तावृते दाहस्तृष्णा शूलं भ्रमस्तमः", text: "vāyorāvaraṇaṃ cāto bahubhedaṃ pravakṣyate liṅgaṃ pittāvṛte dāhastṛṣṇā śūlaṃ bhramastamaḥ" },
      { type: "verse", number: "33", sanskrit: "कटुकोष्णाम्ललवणैर्विदाहः शीतकमता शैत्यगौरवशूलानि कट्वाद्युपशयो ऽधिकम्", text: "kaṭukoṣṇāmlalavaṇairvidāhaḥ śītakamatā śaityagauravaśūlāni kaṭvādyupaśayo 'dhikam" },
      { type: "verse", number: "34", sanskrit: "लङ्घनायासरूक्षोष्णकामता च कफावृते रक्तावृते सदाहार्तिस्त्वङ्मांसान्तरजा भृशम्", text: "laṅghanāyāsarūkṣoṣṇakāmatā ca kaphāvṛte raktāvṛte sadāhārtistvaṅmāṃsāntarajā bhṛśam" },
      { type: "verse", number: "35", sanskrit: "भवेच्च रागी श्वयथुर्जायन्ते मण्डलानि च मांसेन कठिनः शोफो विवर्णः पिटकास्तथा", text: "bhavecca rāgī śvayathurjāyante maṇḍalāni ca māṃsena kaṭhinaḥ śopho vivarṇaḥ piṭakāstathā" },
      { type: "verse", number: "36", sanskrit: "हर्षः पिपीलिकानां च सञ्चार इव जायते चलः स्निग्धो मृदुः शीतः शोफो गात्रेष्वरोचकः", text: "harṣaḥ pipīlikānāṃ ca sañcāra iva jāyate calaḥ snigdho mṛduḥ śītaḥ śopho gātreṣvarocakaḥ" },
      { type: "verse", number: "37", sanskrit: "आढ्यवात इति ज्ञेयः स कृच्छ्रो मेदसावृते स्पर्शमस्थ्यावृते ऽत्युष्णं पीडनं चाभिनन्दति", text: "āḍhyavāta iti jñeyaḥ sa kṛcchro medasāvṛte sparśamasthyāvṛte 'tyuṣṇaṃ pīḍanaṃ cābhinandati" },
      { type: "verse", number: "38", sanskrit: "सूच्येव तुद्यते ऽत्यर्थमङ्गं सीदति शूल्यते मज्जावृते विनमनं जृम्भणं परिवेष्टनम्", text: "sūcyeva tudyate 'tyarthamaṅgaṃ sīdati śūlyate majjāvṛte vinamanaṃ jṛmbhaṇaṃ pariveṣṭanam" },
      { type: "verse", number: "39", sanskrit: "शूलं च पीड्यमाने च पाणिभ्यां लभते सुखम् शुक्रावृते ऽतिवेगो वा न वा निष्फलतापि वा", text: "śūlaṃ ca pīḍyamāne ca pāṇibhyāṃ labhate sukham śukrāvṛte 'tivego vā na vā niṣphalatāpi vā" },
      { type: "verse", number: "40", sanskrit: "भुक्ते कुक्षौ रुजा जीर्णे शाम्यत्यन्नावृते ऽनिले मूत्राप्रवृत्तिराध्मानं बस्तेर्मूत्रावृते भवेत्", text: "bhukte kukṣau rujā jīrṇe śāmyatyannāvṛte 'nile mūtrāpravṛttirādhmānaṃ bastermūtrāvṛte bhavet" },
      { type: "verse", number: "41", sanskrit: "विडावृते विबन्धो ऽधः स्वे स्थाने परिकृन्तति", text: "viḍāvṛte vibandho 'dhaḥ sve sthāne parikṛntati" },
      { type: "verse", number: "42", sanskrit: "व्रजत्याशु जरां स्नेहो भुक्ते चानह्यते नरः शकृत्पीडितमन्नेन दुःखं शुष्कं चिरात्सृजेत्", text: "vrajatyāśu jarāṃ sneho bhukte cānahyate naraḥ śakṛtpīḍitamannena duḥkhaṃ śuṣkaṃ cirātsṛjet" },
      { type: "verse", number: "43", sanskrit: "सर्वधात्वावृते वायौ श्रोणिवङ्क्षणपृष्ठरुक् विलोमो मारुतो ऽस्वास्थ्यं हृदयं पीड्यते ऽतिच", text: "sarvadhātvāvṛte vāyau śroṇivaṅkṣaṇapṛṣṭharuk vilomo māruto 'svāsthyaṃ hṛdayaṃ pīḍyate 'tica" },
      { type: "verse", number: "44", sanskrit: "भ्रमो मूर्छा रुजा दाहः पित्तेन प्राण आवृते विदग्धे ऽन्ने च वमनमुदाने विभ्रमादयः", text: "bhramo mūrchā rujā dāhaḥ pittena prāṇa āvṛte vidagdhe 'nne ca vamanamudāne vibhramādayaḥ" },
      { type: "verse", number: "45", sanskrit: "दाहो ऽन्तरूर्जाभ्रंशश्च दाहो व्याने तु सर्वगः क्लमो ऽङ्गचेष्टासङ्गश्च सन्तापः सहवेदनः", text: "dāho 'ntarūrjābhraṃśaśca dāho vyāne tu sarvagaḥ klamo 'ṅgaceṣṭāsaṅgaśca santāpaḥ sahavedanaḥ" },
      { type: "verse", number: "46", sanskrit: "समान उष्मोपहतिरतिस्वेदो ऽरतिः सतृट् दाहश्च स्यादपाने तु मले हारिद्रवर्णता", text: "samāna uṣmopahatiratisvedo 'ratiḥ satṛṭ dāhaśca syādapāne tu male hāridravarṇatā" },
      { type: "verse", number: "47", sanskrit: "रुजो ऽतिवृद्धिस्तापश्च योनिमेहनपायुषु", text: "rujo 'tivṛddhistāpaśca yonimehanapāyuṣu" },
      { type: "verse", number: "48", sanskrit: "श्लेष्मणा त्वावऋते प्राणे सादस्तन्द्रारुचिर्वमिः ष्ठीवनक्षवथूद्गारनिश्वासोच्छ्वाससङ्ग्रहः", text: "śleṣmaṇā tvāvaṛte prāṇe sādastandrārucirvamiḥ ṣṭhīvanakṣavathūdgāraniśvāsocchvāsasaṅgrahaḥ" },
      { type: "verse", number: "49", sanskrit: "उदाने गुरुगात्रत्वमरुचिर्वाक्स्वरग्रहः बलवर्णप्रणाशश्च व्याने पर्वास्थिवाग्ग्रहः", text: "udāne gurugātratvamarucirvāksvaragrahaḥ balavarṇapraṇāśaśca vyāne parvāsthivāggrahaḥ" },
      { type: "verse", number: "50", sanskrit: "गुरुताङ्गेषु सर्वेषु स्खलितं च गतौ भृशम् समाने ऽतिहिमाङ्गत्वमस्वेदो मन्दवह्निता", text: "gurutāṅgeṣu sarveṣu skhalitaṃ ca gatau bhṛśam samāne 'tihimāṅgatvamasvedo mandavahnitā" },
      { type: "verse", number: "51", sanskrit: "अपाने सकफं मूत्रशकृतोः स्यात् प्रवर्तनम् इति द्वाविंशतिविधं वायोरावरणं विदुः", text: "apāne sakaphaṃ mūtraśakṛtoḥ syāt pravartanam iti dvāviṃśatividhaṃ vāyorāvaraṇaṃ viduḥ" },
      { type: "verse", number: "52", sanskrit: "प्राणादयस्तथान्योन्यमावृण्वन्ति यथाक्रमम् सर्वेपि विंशतिविधं विद्यादावरणं च तत्", text: "prāṇādayastathānyonyamāvṛṇvanti yathākramam sarvepi viṃśatividhaṃ vidyādāvaraṇaṃ ca tat" },
      { type: "verse", number: "53", sanskrit: "निश्वासोच्छ्ववाससंरोधःप्रतिश्यायःशिरोग्रहः हृद्रोगो मुखशोषश्च प्राणेनोदान आवृते", text: "niśvāsocchvavāsasaṃrodhaḥpratiśyāyaḥśirograhaḥ hṛdrogo mukhaśoṣaśca prāṇenodāna āvṛte" },
      { type: "verse", number: "54", sanskrit: "उदानेनावृते प्राणे वर्णौजोबलसङ्क्षयः दिशानया च विभजेत् सर्वमावरणं भिषक्", text: "udānenāvṛte prāṇe varṇaujobalasaṅkṣayaḥ diśānayā ca vibhajet sarvamāvaraṇaṃ bhiṣak" },
      { type: "verse", number: "55", sanskrit: "स्थानान्यवेक्ष्य वातानां वृद्धिं हानिं च कर्मणाम् प्राणादीनां च पञ्चानां मिश्रमावरणं मिथः", text: "sthānānyavekṣya vātānāṃ vṛddhiṃ hāniṃ ca karmaṇām prāṇādīnāṃ ca pañcānāṃ miśramāvaraṇaṃ mithaḥ" },
      { type: "verse", number: "56", sanskrit: "पित्तादिभिर्द्वादशभिर्मिश्राणां मिश्रितैश्च तैः मिश्रैः पित्तादिभिस्तद्वन्मिश्रणाभिरनेकधा", text: "pittādibhirdvādaśabhirmiśrāṇāṃ miśritaiśca taiḥ miśraiḥ pittādibhistadvanmiśraṇābhiranekadhā" },
      { type: "verse", number: "57", sanskrit: "तारतम्यविकल्पाच्च यात्यावृतिरसङ्ख्यताम् तां लक्षयेदवहितो यथास्वं लक्षणोदयात्", text: "tāratamyavikalpācca yātyāvṛtirasaṅkhyatām tāṃ lakṣayedavahito yathāsvaṃ lakṣaṇodayāt" },
      { type: "verse", number: "58", sanskrit: "शनैश्शनैश्चोपशयाद् गूढामपि मुहुर्मुहुः विशेषाज्जीवितं प्राण उदानो बलमुच्यते", text: "śanaiśśanaiścopaśayād gūḍhāmapi muhurmuhuḥ viśeṣājjīvitaṃ prāṇa udāno balamucyate" },
      { type: "verse", number: "59", sanskrit: "स्यात्तयोः पीडनाद्धानिरायुषश्च बलस्य च", text: "syāttayoḥ pīḍanāddhānirāyuṣaśca balasya ca" },
      { type: "verse", number: "60", sanskrit: "आवृता वायवो ऽज्ञाता ज्ञाता वा वत्सरं स्थिताः प्रयत्नेनापि दुःसाध्या भवेयुर्वानुपक्रमाः", text: "āvṛtā vāyavo 'jñātā jñātā vā vatsaraṃ sthitāḥ prayatnenāpi duḥsādhyā bhaveyurvānupakramāḥ" },
      { type: "verse", number: "61", sanskrit: "विद्रधिप्लीहहृद्रोगगुल्माग्निसदनादयः भवन्त्युपद्रवास्तेषामावृतानामुपेक्षणात्", text: "vidradhiplīhahṛdrogagulmāgnisadanādayaḥ bhavantyupadravāsteṣāmāvṛtānāmupekṣaṇāt" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 1,
    lang: "sa",
    content: [
      { type: "heading", heading: "Джвара чикитса — лечение лихорадок" },
      { type: "text", text: "Глава 1 Чикитса стханы — лечебный раздел о лечение лихорадок. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो ज्वरचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto jvaracikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "आमाशयस्थो हत्वाग्निं सामो मार्गान् पिधाय यत् विदधाति ज्वरं दोषस्तस्मात् कुर्वीत लङ्घनम्", text: "āmāśayastho hatvāgniṃ sāmo mārgān pidhāya yat vidadhāti jvaraṃ doṣastasmāt kurvīta laṅghanam" },
      { type: "verse", number: "3", sanskrit: "प्राग्रूपेषु ज्वरादौ वा बलं यत्नेन पालयन् बलाधिष्ठानमारोग्यमारोग्यार्थः क्रियाक्रमः", text: "prāgrūpeṣu jvarādau vā balaṃ yatnena pālayan balādhiṣṭhānamārogyamārogyārthaḥ kriyākramaḥ" },
      { type: "verse", number: "4", sanskrit: "लङ्घनैः क्षपिते दोषे दीप्ते ऽग्नौ लाघवे सति स्वास्थ्यं क्षुत्तृङ् रुचिः पक्तिर्बलेमाजश्च जायते", text: "laṅghanaiḥ kṣapite doṣe dīpte 'gnau lāghave sati svāsthyaṃ kṣuttṛṅ ruciḥ paktirbalemājaśca jāyate" },
      { type: "verse", number: "5", sanskrit: "तत्रोत्कृष्टे समुत्क्लिष्टे कफप्राये चले मले सहृल्लासप्रसेकान्नद्वेषकासविषूचिके", text: "tatrotkṛṣṭe samutkliṣṭe kaphaprāye cale male sahṛllāsaprasekānnadveṣakāsaviṣūcike" },
      { type: "verse", number: "6", sanskrit: "सद्योभुक्तस्य सञ्जाते ज्वरे सामे विशेषतः वमनं वमनार्हस्य शस्तं कुर्यात्तदन्यथा", text: "sadyobhuktasya sañjāte jvare sāme viśeṣataḥ vamanaṃ vamanārhasya śastaṃ kuryāttadanyathā" },
      { type: "verse", number: "7", sanskrit: "श्वासातीसारसन्मोहहृद्रोगविषमज्वरान्", text: "śvāsātīsārasanmohahṛdrogaviṣamajvarān" },
      { type: "verse", number: "8", sanskrit: "पिप्पलीभिर्युतां गालां कलिङ्गैर्मधुकेन वा पीत्वोष्णतोयेन वमेन्मध्बम्बु लवणाम्बु वा", text: "pippalībhiryutāṃ gālāṃ kaliṅgairmadhukena vā pītvoṣṇatoyena vamenmadhbambu lavaṇāmbu vā" },
      { type: "verse", number: "9", sanskrit: "पटोलनिम्बकर्कोटवेत्रपत्रजलानि वा पेयां मण्डं रसं चेक्षोर्मद्यं कल्पोदितानि वा", text: "paṭolanimbakarkoṭavetrapatrajalāni vā peyāṃ maṇḍaṃ rasaṃ cekṣormadyaṃ kalpoditāni vā" },
      { type: "verse", number: "10", sanskrit: "वमनानि प्रयुञ्जीत बलकालविभागवित् कृते ऽकृते वा वमने ज्वरी कुर्याद्विशोषणम्", text: "vamanāni prayuñjīta balakālavibhāgavit kṛte 'kṛte vā vamane jvarī kuryādviśoṣaṇam" },
      { type: "verse", number: "11", sanskrit: "दोषाणां समुदीर्णानां पाचनाय शमाय च आमेन भस्मनेवाग्नौ छन्ने ऽन्नं न विपच्यते", text: "doṣāṇāṃ samudīrṇānāṃ pācanāya śamāya ca āmena bhasmanevāgnau channe 'nnaṃ na vipacyate" },
      { type: "verse", number: "12", sanskrit: "तस्मादादोषपचनाज्ज्वरितानुपवासयेत् तृष्णगल्पाल्पमुष्णाम्बु पिबेद्वातकफज्वरे", text: "tasmādādoṣapacanājjvaritānupavāsayet tṛṣṇagalpālpamuṣṇāmbu pibedvātakaphajvare" },
      { type: "verse", number: "13", sanskrit: "तत् कफं विलयं नीत्वा तृष्णामाशु निवर्तयेत् उदीर्य चाग्निं स्रोतांसि मृदूकृत्य विशोधयेत्", text: "tat kaphaṃ vilayaṃ nītvā tṛṣṇāmāśu nivartayet udīrya cāgniṃ srotāṃsi mṛdūkṛtya viśodhayet" },
      { type: "verse", number: "14", sanskrit: "लीनपित्तानिलस्वेदशकृन्मूत्रानुलोमनम् निद्राजाङ्यारुचिहरं प्राणानामवलम्बनम्", text: "līnapittānilasvedaśakṛnmūtrānulomanam nidrājāṅyāruciharaṃ prāṇānāmavalambanam" },
      { type: "verse", number: "15", sanskrit: "विपरीतमतः शीतं दोषसङ्घातवर्धनम्", text: "viparītamataḥ śītaṃ doṣasaṅghātavardhanam" },
      { type: "verse", number: "16", sanskrit: "उष्णमेवंगुणत्वे ऽपि युञ्ज्यान्नैकान्तपित्तले उद्रिक्तपित्ते दवथुदाहमोहातिसारिणि", text: "uṣṇamevaṃguṇatve 'pi yuñjyānnaikāntapittale udriktapitte davathudāhamohātisāriṇi" },
      { type: "verse", number: "17", sanskrit: "विषमद्योत्थिते ग्रीष्मे क्षतक्षीणे ऽस्रपित्तिनि घनचन्दनशुण्ठ्यम्बुपर्पटोशीरसाधितम्", text: "viṣamadyotthite grīṣme kṣatakṣīṇe 'srapittini ghanacandanaśuṇṭhyambuparpaṭośīrasādhitam" },
      { type: "verse", number: "18", sanskrit: "शीतं तेभ्यो हितं तोयं पाचनं तृड्ज्वरापहम् ऊष्मा पित्तादृते नास्ति ज्वरो नास्त्यूष्मणा विना", text: "śītaṃ tebhyo hitaṃ toyaṃ pācanaṃ tṛḍjvarāpaham ūṣmā pittādṛte nāsti jvaro nāstyūṣmaṇā vinā" },
      { type: "verse", number: "19", sanskrit: "तस्मात् पित्तविरुद्धानि त्यजेत् पित्ताधिके ऽधिकम् स्नानाभ्यङ्गप्रदेहांश्च परिशेषं च लङ्घनम्", text: "tasmāt pittaviruddhāni tyajet pittādhike 'dhikam snānābhyaṅgapradehāṃśca pariśeṣaṃ ca laṅghanam" },
      { type: "verse", number: "20", sanskrit: "अजीर्ण इव शूलघ्नं सामे तीव्ररुजि ज्वरे न पिबेदौषधं तद्धि भूय एवाममावहेत्", text: "ajīrṇa iva śūlaghnaṃ sāme tīvraruji jvare na pibedauṣadhaṃ taddhi bhūya evāmamāvahet" },
      { type: "verse", number: "21", sanskrit: "आमाभिभूतकोष्ठस्य क्सीरं विषमहेरिव सोदर्दपीनसश्वासे जङ्घापर्वास्थिशूलिनि वातश्लेष्मात्मके स्वेदः प्रशस्तः स प्रवर्तयेत्", text: "āmābhibhūtakoṣṭhasya ksīraṃ viṣamaheriva sodardapīnasaśvāse jaṅghāparvāsthiśūlini vātaśleṣmātmake svedaḥ praśastaḥ sa pravartayet" },
      { type: "verse", number: "22", sanskrit: "स्वेदमूत्रशकृद्वातान् कुर्यादग्नेश्च पाटवम् स्नेहोक्तमाचारविधिं सर्वतश्चानुपालयेत्", text: "svedamūtraśakṛdvātān kuryādagneśca pāṭavam snehoktamācāravidhiṃ sarvataścānupālayet" },
      { type: "verse", number: "23", sanskrit: "लङ्घनं स्वेदनं कालो यवाग्वस्तिक्तको रसः मलानां पाचनानि स्युर्यथावस्थं क्रमेण वा", text: "laṅghanaṃ svedanaṃ kālo yavāgvastiktako rasaḥ malānāṃ pācanāni syuryathāvasthaṃ krameṇa vā" },
      { type: "verse", number: "24", sanskrit: "शुद्धवातक्षयागन्तुजीर्णज्वरिषु लङ्घनम् नेष्यते तेषु हि हितं शमनं यन्न कर्शनम्", text: "śuddhavātakṣayāgantujīrṇajvariṣu laṅghanam neṣyate teṣu hi hitaṃ śamanaṃ yanna karśanam" },
      { type: "verse", number: "25", sanskrit: "तत्रसामज्वराकृत्या जानीयादविशोषितम् द्विधिधोपक्रमज्ञानमवेक्षेत च लङ्घने", text: "tatrasāmajvarākṛtyā jānīyādaviśoṣitam dvidhidhopakramajñānamavekṣeta ca laṅghane" },
      { type: "verse", number: "26", sanskrit: "युक्तं लङ्घितलिग्गैस्तु तं पेयाभिरुपाचरेत् यथास्वौषधसिद्धाभिर्मण्डपूर्वाभिरादितः", text: "yuktaṃ laṅghitaliggaistu taṃ peyābhirupācaret yathāsvauṣadhasiddhābhirmaṇḍapūrvābhirāditaḥ" },
      { type: "verse", number: "27", sanskrit: "षडहं वा मृदुत्वं वा ज्वरो यावदवाप्नुयात् तस्याग्निर्दीप्यते ताभिः समिद्भिरिव पावकः", text: "ṣaḍahaṃ vā mṛdutvaṃ vā jvaro yāvadavāpnuyāt tasyāgnirdīpyate tābhiḥ samidbhiriva pāvakaḥ" },
      { type: "verse", number: "28", sanskrit: "ताश्च भेषजसंयोगाल्लघुत्वाच्चाग्निदीपनाः वातमूत्रपुरीषाणां दोषाणां चानुलोमकाः", text: "tāśca bheṣajasaṃyogāllaghutvāccāgnidīpanāḥ vātamūtrapurīṣāṇāṃ doṣāṇāṃ cānulomakāḥ" },
      { type: "verse", number: "29", sanskrit: "स्वेदनाय द्रवोष्णत्वान्मृदुत्वात्तृट्प्रशान्तये आहारभावात् प्राणाय सरत्वाल्लाघवाय च", text: "svedanāya dravoṣṇatvānmṛdutvāttṛṭpraśāntaye āhārabhāvāt prāṇāya saratvāllāghavāya ca" },
      { type: "verse", number: "30", sanskrit: "ज्वरघ्ना ज्वरसात्म्यत्वात् तस्मात् पेयाभिरादितः उपक्रमेज्ज्वरान् सर्वानृते मद्यसमुत्थितात्", text: "jvaraghnā jvarasātmyatvāt tasmāt peyābhirāditaḥ upakramejjvarān sarvānṛte madyasamutthitāt" },
      { type: "verse", number: "31", sanskrit: "प्राग्लाजपेयां सुजरां सशुण्ठीधान्यपिप्पलीम् ससैन्धवां तथाम्लार्थी तां पिबेत् सहदाडिमाम्", text: "prāglājapeyāṃ sujarāṃ saśuṇṭhīdhānyapippalīm sasaindhavāṃ tathāmlārthī tāṃ pibet sahadāḍimām" },
      { type: "verse", number: "32", sanskrit: "सृष्टविड्बहुपित्तो वा सशुण्ठीमाक्षिकां हिमाम् बस्तिपार्श्वशिरःशूली व्याघ्रीगोक्षुरसाधिताम्", text: "sṛṣṭaviḍbahupitto vā saśuṇṭhīmākṣikāṃ himām bastipārśvaśiraḥśūlī vyāghrīgokṣurasādhitām" },
      { type: "verse", number: "33", sanskrit: "पृश्नि पर्णीबलाबिल्वनागरोत्पलधान्यकैः सिद्धां ज्वरातिसार्यम्लां पेयां दीपनपाचनीम्", text: "pṛśni parṇībalābilvanāgarotpaladhānyakaiḥ siddhāṃ jvarātisāryamlāṃ peyāṃ dīpanapācanīm" },
      { type: "verse", number: "34", sanskrit: "ह्रस्वेनपञ्चमूलेन हिक्कारुक्श्वासकासवान् पञ्चमूलेन महता कफार्तो यवसाधिताम्", text: "hrasvenapañcamūlena hikkārukśvāsakāsavān pañcamūlena mahatā kaphārto yavasādhitām" },
      { type: "verse", number: "35", sanskrit: "विबद्धवर्चाः सयवां पिप्पल्यामलकैः कृताम् यवागूं सर्पिषा भृष्टां मलदोषानुलोमनीम्", text: "vibaddhavarcāḥ sayavāṃ pippalyāmalakaiḥ kṛtām yavāgūṃ sarpiṣā bhṛṣṭāṃ maladoṣānulomanīm" },
      { type: "verse", number: "36", sanskrit: "चविकापिप्पलीमूलद्राक्षामलकनागरैः कोष्ठे विबद्धे सरुजि पिबेत्तु परिकर्तिनि", text: "cavikāpippalīmūladrākṣāmalakanāgaraiḥ koṣṭhe vibaddhe saruji pibettu parikartini" },
      { type: "verse", number: "37", sanskrit: "कोलवृक्षाम्लकलशीधावनीश्रीफलैः कृताम् अस्वेदनिद्रस्तृष्णार्तः सितामलकनागरैः", text: "kolavṛkṣāmlakalaśīdhāvanīśrīphalaiḥ kṛtām asvedanidrastṛṣṇārtaḥ sitāmalakanāgaraiḥ" },
      { type: "verse", number: "38", sanskrit: "सिताबदरमृद्वीकासारिवामुस्तचन्दनैः तृष्णाच्छर्दिपरीदाहज्वरघ्नीं क्षौद्रसंयुताम्", text: "sitābadaramṛdvīkāsārivāmustacandanaiḥ tṛṣṇācchardiparīdāhajvaraghnīṃ kṣaudrasaṃyutām" },
      { type: "verse", number: "39", sanskrit: "कुर्यात् पेयौषधैरेव रसयूषादिकानपि मद्योद्भवे मद्यनित्ये पित्तस्थानगते कफे", text: "kuryāt peyauṣadhaireva rasayūṣādikānapi madyodbhave madyanitye pittasthānagate kaphe" },
      { type: "verse", number: "40", sanskrit: "ग्रीष्मे तयोर्वाधिकयोस्तृट्छर्दिदाहपीडिते ऊर्ध्वं प्रवृत्ते रक्ते च पेयां नेच्छन्ति तेषु तु", text: "grīṣme tayorvādhikayostṛṭchardidāhapīḍite ūrdhvaṃ pravṛtte rakte ca peyāṃ necchanti teṣu tu" },
      { type: "verse", number: "41", sanskrit: "द्राक्षादाडिमकाश्मर्यपथ्या पीलुपरूषकैः समधूकैः सबदरैः सक्षौद्रान् ससितोपलान्", text: "drākṣādāḍimakāśmaryapathyā pīluparūṣakaiḥ samadhūkaiḥ sabadaraiḥ sakṣaudrān sasitopalān" },
      { type: "verse", number: "42", sanskrit: "ज्वरघ्नैस्तोयमृदितैरद्भिर्वा लाजतर्पणान् पिबेत् सुसूक्ष्मरजसस्ततो जीर्णे तु तर्पणे", text: "jvaraghnaistoyamṛditairadbhirvā lājatarpaṇān pibet susūkṣmarajasastato jīrṇe tu tarpaṇe" },
      { type: "verse", number: "43", sanskrit: "यवाग्वां वौदनं क्षुद्वानश्नीयाद्भृष्टतण्डुलम् दकलावणिकैर्यूषैः रसैर्वा मुद्गलावजैः", text: "yavāgvāṃ vaudanaṃ kṣudvānaśnīyādbhṛṣṭataṇḍulam dakalāvaṇikairyūṣaiḥ rasairvā mudgalāvajaiḥ" },
      { type: "verse", number: "44", sanskrit: "इत्ययं षडहो नेयो बलं दोषं च रक्षता ततः पक्वेषु दोषेषु लङ्घनाद्यैः प्रशस्यते", text: "ityayaṃ ṣaḍaho neyo balaṃ doṣaṃ ca rakṣatā tataḥ pakveṣu doṣeṣu laṅghanādyaiḥ praśasyate" },
      { type: "verse", number: "45", sanskrit: "कषायो दोषशेषस्य पाचनः शमनो ऽथवा तिक्तः पित्ते विशेषेण प्रयोज्यः कटुकः कफे", text: "kaṣāyo doṣaśeṣasya pācanaḥ śamano 'thavā tiktaḥ pitte viśeṣeṇa prayojyaḥ kaṭukaḥ kaphe" },
      { type: "verse", number: "46", sanskrit: "पित्तश्लेष्महरत्वे ऽपि कषायः स न शस्यते नवज्वरे मलस्तम्भात् कषायो विषमज्वरान्", text: "pittaśleṣmaharatve 'pi kaṣāyaḥ sa na śasyate navajvare malastambhāt kaṣāyo viṣamajvarān" },
      { type: "verse", number: "47", sanskrit: "कुरुते ऽरुचिहृल्लासहिध्माध्मानादिकानपि न च्यवन्ते न पच्यन्ते कषायस्तम्भिता मलाः", text: "kurute 'rucihṛllāsahidhmādhmānādikānapi na cyavante na pacyante kaṣāyastambhitā malāḥ" },
      { type: "verse", number: "48", sanskrit: "तिर्यग्गता विमार्गा वा वर्धयन्त्यपि च ज्वरम् बद्धामकफवातत्वाच्छूलानाहादिकानपि", text: "tiryaggatā vimārgā vā vardhayantyapi ca jvaram baddhāmakaphavātatvācchūlānāhādikānapi" },
      { type: "verse", number: "49", sanskrit: "सप्ताहादौषधं केंचिदाहुरन्ये दशाहतः केचिल्लघ्वन्नभुक्तस्य योज्यमामोल्बणे न तु", text: "saptāhādauṣadhaṃ keṃcidāhuranye daśāhataḥ kecillaghvannabhuktasya yojyamāmolbaṇe na tu" },
      { type: "verse", number: "50", sanskrit: "तीव्रज्वरपरीतस्य दोषवेगोदये यतः दोषे ऽथवातिनिचिते तन्द्रास्तैमित्यकारिणि", text: "tīvrajvaraparītasya doṣavegodaye yataḥ doṣe 'thavātinicite tandrāstaimityakāriṇi" },
      { type: "verse", number: "51", sanskrit: "अपच्यमानं भैषज्यं भूयो ज्वलयति ज्वरम् यदा ज्वरो मृदुर्देहो लघुः प्रचलिता मलाः", text: "apacyamānaṃ bhaiṣajyaṃ bhūyo jvalayati jvaram yadā jvaro mṛdurdeho laghuḥ pracalitā malāḥ" },
      { type: "verse", number: "52", sanskrit: "अचिरज्वरितस्यापि योजयेद्भेषजं तदा मुस्तया पर्पटं युक्तं शुण्ठ्या दुस्पर्शयापि वा", text: "acirajvaritasyāpi yojayedbheṣajaṃ tadā mustayā parpaṭaṃ yuktaṃ śuṇṭhyā dusparśayāpi vā" },
      { type: "verse", number: "53", sanskrit: "पाक्यं शीतकषायं वा पाठोशीरं सवालकम् पिबेत्तद्वच्च भूनिम्बगुडूचीमुस्तनागरम्", text: "pākyaṃ śītakaṣāyaṃ vā pāṭhośīraṃ savālakam pibettadvacca bhūnimbaguḍūcīmustanāgaram" },
      { type: "verse", number: "54", sanskrit: "यथायोगमिमे योज्याः कषाया दोषपाचनाः ज्वरारोचकतृष्णास्यवैरस्यापक्तिनाशनाः", text: "yathāyogamime yojyāḥ kaṣāyā doṣapācanāḥ jvarārocakatṛṣṇāsyavairasyāpaktināśanāḥ" },
      { type: "verse", number: "55", sanskrit: "पाठेन्द्रयवभूनिम्बमुस्तपर्पटकामृताः जयन्त्याममतीसारं ज्वरं च समहौषधाः", text: "pāṭhendrayavabhūnimbamustaparpaṭakāmṛtāḥ jayantyāmamatīsāraṃ jvaraṃ ca samahauṣadhāḥ" },
      { type: "verse", number: "56", sanskrit: "दुरालभामृतामुस्तानागरं वातजे ज्वरे अथवा पिप्पलीमूलगुडूचीविश्वभेषजम्", text: "durālabhāmṛtāmustānāgaraṃ vātaje jvare athavā pippalīmūlaguḍūcīviśvabheṣajam" },
      { type: "verse", number: "57", sanskrit: "कनीयः पञ्चमूलं च पित्ते क्षौद्रसमन्विताः कलिङ्गमुस्तकटुका मुस्तापर्पटकं तथा", text: "kanīyaḥ pañcamūlaṃ ca pitte kṣaudrasamanvitāḥ kaliṅgamustakaṭukā mustāparpaṭakaṃ tathā" },
      { type: "verse", number: "58", sanskrit: "सधन्वयासभूनिम्बं वत्सकाद्यो गणः कफे अथवा वृषगाङ्गेयी शृङ्गेवरदुरालभाः", text: "sadhanvayāsabhūnimbaṃ vatsakādyo gaṇaḥ kaphe athavā vṛṣagāṅgeyī śṛṅgevaradurālabhāḥ" },
      { type: "verse", number: "59", sanskrit: "रुग्विबन्धानिलश्लेष्मयुक्ते दीपनपाचनम् अभयापिप्पलीमूलशम्याककटुकाघनम्", text: "rugvibandhānilaśleṣmayukte dīpanapācanam abhayāpippalīmūlaśamyākakaṭukāghanam" },
      { type: "verse", number: "60", sanskrit: "कलिङ्गकाः पटोलस्य पत्रं कटुकरोहिणी पटोलं सारिवा मुस्ता पाठा कटुकरोहिणी", text: "kaliṅgakāḥ paṭolasya patraṃ kaṭukarohiṇī paṭolaṃ sārivā mustā pāṭhā kaṭukarohiṇī" },
      { type: "verse", number: "61", sanskrit: "पटोलनिम्बत्रिफलामृद्वीकामुस्तवत्सकाः किराततिक्तममृता चन्दनां विश्वभेषजम्", text: "paṭolanimbatriphalāmṛdvīkāmustavatsakāḥ kirātatiktamamṛtā candanāṃ viśvabheṣajam" },
      { type: "verse", number: "62", sanskrit: "धात्री मुस्तामृताक्षौद्रमर्धश्लोकसमापनाः पञ्चैते सन्ततादीनां पञ्चानां शमना मताः", text: "dhātrī mustāmṛtākṣaudramardhaślokasamāpanāḥ pañcaite santatādīnāṃ pañcānāṃ śamanā matāḥ" },
      { type: "verse", number: "63", sanskrit: "पटोलेन्द्रयवारिष्टभद्रमुस्तामृताद्वयम् सारिवाद्वितयं पाठा त्रायन्ती कटुरोहिणी", text: "paṭolendrayavāriṣṭabhadramustāmṛtādvayam sārivādvitayaṃ pāṭhā trāyantī kaṭurohiṇī" },
      { type: "verse", number: "64", sanskrit: "पटोलारिष्टमृद्वीकाशम्याकत्रिफलावृषम् चन्दनोशीरधान्याब्दगुडूचीविश्वभेषजम्", text: "paṭolāriṣṭamṛdvīkāśamyākatriphalāvṛṣam candanośīradhānyābdaguḍūcīviśvabheṣajam" },
      { type: "verse", number: "65", sanskrit: "देवदारुस्थिराशुण्ठीवासाधात्रीहरीतकीः पञ्च पञ्च ज्वरान् घ्नन्ति योगा मधुसितोत्कटाः", text: "devadārusthirāśuṇṭhīvāsādhātrīharītakīḥ pañca pañca jvarān ghnanti yogā madhusitotkaṭāḥ" },
      { type: "verse", number: "66", sanskrit: "सगुडाः सारिवाद्राक्षाशताह्वाकणरेणुकाः काश्मर्यसारिवाद्राक्षात्रायमाणामृतागुडाः", text: "saguḍāḥ sārivādrākṣāśatāhvākaṇareṇukāḥ kāśmaryasārivādrākṣātrāyamāṇāmṛtāguḍāḥ" },
      { type: "verse", number: "67", sanskrit: "शतपुष्पावचाकुष्ठदेवदारुहरेणुकाः शर्करामधुसंयुक्ताः समांसीमुस्तधान्यकाः", text: "śatapuṣpāvacākuṣṭhadevadāruhareṇukāḥ śarkarāmadhusaṃyuktāḥ samāṃsīmustadhānyakāḥ" },
      { type: "verse", number: "68", sanskrit: "कृष्णापुनर्नवाद्राक्षाशताह्वागुडसारिवाः शालिपर्णीबलाद्राक्षासारिवाच्छिन्नसम्भवाः", text: "kṛṣṇāpunarnavādrākṣāśatāhvāguḍasārivāḥ śāliparṇībalādrākṣāsārivācchinnasambhavāḥ" },
      { type: "verse", number: "69", sanskrit: "आरग्वधो बला रास्ना काश्मर्यं मधुकं गुडः शतावरीच्छिन्नरुहास्वरसो वा गुडान्वितः", text: "āragvadho balā rāsnā kāśmaryaṃ madhukaṃ guḍaḥ śatāvarīcchinnaruhāsvaraso vā guḍānvitaḥ" },
      { type: "verse", number: "70", sanskrit: "सकृष्णाजीरकसितानागरश्चामृतारसः वातज्वरं जयन्यूशु केवलो वामृतारसः", text: "sakṛṣṇājīrakasitānāgaraścāmṛtārasaḥ vātajvaraṃ jayanyūśu kevalo vāmṛtārasaḥ" },
      { type: "verse", number: "71", sanskrit: "भार्ङ्गीसरलगाङ्गेयीदारुकुष्ठैलवालुकम् कोष्णं घृतगुडोपेतं पिबेद्वा वातजे ज्वरे", text: "bhārṅgīsaralagāṅgeyīdārukuṣṭhailavālukam koṣṇaṃ ghṛtaguḍopetaṃ pibedvā vātaje jvare" },
      { type: "verse", number: "72", sanskrit: "पटोलादिगुडूच्यादी सूत्रोक्तौ पित्तजे ज्वरे अञ्जनादिः सकाश्मर्यः सारिवादिः सशर्करः", text: "paṭolādiguḍūcyādī sūtroktau pittaje jvare añjanādiḥ sakāśmaryaḥ sārivādiḥ saśarkaraḥ" },
      { type: "verse", number: "73", sanskrit: "सितामधुककाश्मर्यशीतोशारिपरूषकम् गुडूचीसारिवालोद्ध्रकमलोत्पलशर्कराः", text: "sitāmadhukakāśmaryaśītośāriparūṣakam guḍūcīsārivāloddhrakamalotpalaśarkarāḥ" },
      { type: "verse", number: "74", sanskrit: "द्राक्षाभयातिक्तघनशम्याकफलपर्पटम् श्यामापर्पटदुःस्पर्शातिक्तातिक्तसितावृषाः", text: "drākṣābhayātiktaghanaśamyākaphalaparpaṭam śyāmāparpaṭaduḥsparśātiktātiktasitāvṛṣāḥ" },
      { type: "verse", number: "75", sanskrit: "शर्करातिक्तकटुकात्रायमाणाबिभीतकम् गुडूच्यामलकैर्युक्तः केवलो वापि पर्पटः", text: "śarkarātiktakaṭukātrāyamāṇābibhītakam guḍūcyāmalakairyuktaḥ kevalo vāpi parpaṭaḥ" },
      { type: "verse", number: "76", sanskrit: "कषायो वा हिमस्तिक्ताद्राक्षामधुकनिम्बजः पित्तज्वरघ्नी कटुका श्लक्ष्णापिष्टा सशर्करा", text: "kaṣāyo vā himastiktādrākṣāmadhukanimbajaḥ pittajvaraghnī kaṭukā ślakṣṇāpiṣṭā saśarkarā" },
      { type: "verse", number: "77", sanskrit: "कफजे ऽतिविषोशीरपटोलमरिचक्षपाः समूर्वेन्द्रयवद्वीपिकुष्ठनिम्बवचागुडाः", text: "kaphaje 'tiviṣośīrapaṭolamaricakṣapāḥ samūrvendrayavadvīpikuṣṭhanimbavacāguḍāḥ" },
      { type: "verse", number: "78", sanskrit: "सप्तच्छदामृतानिम्बस्फूर्जातं माक्षिकान्वितम् निशात्रिकटुकं तिक्तानागपुष्पकलिङ्गकाः", text: "saptacchadāmṛtānimbasphūrjātaṃ mākṣikānvitam niśātrikaṭukaṃ tiktānāgapuṣpakaliṅgakāḥ" },
      { type: "verse", number: "79", sanskrit: "सारिवातिविषाकुष्ठदुःस्पर्शामुस्तगुग्गुलुः परूषं त्रिफला तिक्ता बीजं वृषकजं घनम्", text: "sārivātiviṣākuṣṭhaduḥsparśāmustagugguluḥ parūṣaṃ triphalā tiktā bījaṃ vṛṣakajaṃ ghanam" },
      { type: "verse", number: "80", sanskrit: "नागरत्रिफलामुस्तामूर्वापाठाः समाक्षिकाः संसर्गसन्निपातेषु मिश्रानेतान् विकल्पयेत्", text: "nāgaratriphalāmustāmūrvāpāṭhāḥ samākṣikāḥ saṃsargasannipāteṣu miśrānetān vikalpayet" },
      { type: "verse", number: "81", sanskrit: "गोकण्टकबलादर्भाः ससिता वातपित्तजे द्राक्षामलकभूनिम्बाः सगुडूचीशठीगुडाः", text: "gokaṇṭakabalādarbhāḥ sasitā vātapittaje drākṣāmalakabhūnimbāḥ saguḍūcīśaṭhīguḍāḥ" },
      { type: "verse", number: "82", sanskrit: "त्रायन्ती सारिवाद्राक्षा काश्मर्यच्छिन्नजागुडाः द्राक्षामसूरत्रायन्तीगुडूचीसारिवाबलाः", text: "trāyantī sārivādrākṣā kāśmaryacchinnajāguḍāḥ drākṣāmasūratrāyantīguḍūcīsārivābalāḥ" },
      { type: "verse", number: "83", sanskrit: "द्राक्षामधूकमधुकलोद्ध्रकाश्मर्यसारिवाः मुस्तामलकद्द्रीबेरपद्मकेसरपद्मकम्", text: "drākṣāmadhūkamadhukaloddhrakāśmaryasārivāḥ mustāmalakaddrīberapadmakesarapadmakam" },
      { type: "verse", number: "84", sanskrit: "मृणालचन्दनोशीरनीलोत्पलपरूषकम् फाण्टो हिमो वा द्राक्षादिर्जातीकुसुमवासितः", text: "mṛṇālacandanośīranīlotpalaparūṣakam phāṇṭo himo vā drākṣādirjātīkusumavāsitaḥ" },
      { type: "verse", number: "85", sanskrit: "युक्तो मधुसितालाजैर्जयत्यनिलपित्तजम् ज्वरं मदात्ययं छर्दि मूर्छां दाहं श्रमं भ्रमम् ऊर्ध्वगं रक्तपित्तं च पिपासां कामलामपि", text: "yukto madhusitālājairjayatyanilapittajam jvaraṃ madātyayaṃ chardi mūrchāṃ dāhaṃ śramaṃ bhramam ūrdhvagaṃ raktapittaṃ ca pipāsāṃ kāmalāmapi" },
      { type: "verse", number: "86", sanskrit: "कफवाते वचातिक्तापाठारग्वधवत्सकाः", text: "kaphavāte vacātiktāpāṭhāragvadhavatsakāḥ" },
      { type: "verse", number: "87", sanskrit: "पिप्पलीचूर्णयुक्तो वा क्वाथश्छिन्नोद्भवोद्भवः व्याघ्रीशुण्ठ्यमृताक्वाथः पिप्पलीचूर्णसंयुतः", text: "pippalīcūrṇayukto vā kvāthaśchinnodbhavodbhavaḥ vyāghrīśuṇṭhyamṛtākvāthaḥ pippalīcūrṇasaṃyutaḥ" },
      { type: "verse", number: "88", sanskrit: "वातश्लेष्मज्वरश्वासकासपीनसशूलजित् पथ्या कुस्तुम्बरीमुस्ताशुण्ठीकत्तृणपर्पटम्", text: "vātaśleṣmajvaraśvāsakāsapīnasaśūlajit pathyā kustumbarīmustāśuṇṭhīkattṛṇaparpaṭam" },
      { type: "verse", number: "89", sanskrit: "सकट्फलवचाभार्ङ्गीदेवाह्वं मधुहिङ्गुमत् कफवातज्वरष्ठीवकुक्षिहृत्पार्श्ववेदनाः", text: "sakaṭphalavacābhārṅgīdevāhvaṃ madhuhiṅgumat kaphavātajvaraṣṭhīvakukṣihṛtpārśvavedanāḥ" },
      { type: "verse", number: "90", sanskrit: "कण्ठामयास्यश्वयथुकासश्वासान्नियच्छति", text: "kaṇṭhāmayāsyaśvayathukāsaśvāsānniyacchati" },
      { type: "verse", number: "91", sanskrit: "आरग्वधादिः सक्षौद्रः कफपित्तज्वरं जयेत् तथा तिक्तावृषोशीरत्रायन्तीत्रिफलामृताः पटोलातिविषानिम्बमूर्वाधन्वयवासाकाः", text: "āragvadhādiḥ sakṣaudraḥ kaphapittajvaraṃ jayet tathā tiktāvṛṣośīratrāyantītriphalāmṛtāḥ paṭolātiviṣānimbamūrvādhanvayavāsākāḥ" },
      { type: "verse", number: "92", sanskrit: "वृषपुष्पच्छदरसः शर्करामाक्षिकान्वितः पित्तश्लेष्मज्वरं हन्ति सासृक्पित्तं सकामलम्", text: "vṛṣapuṣpacchadarasaḥ śarkarāmākṣikānvitaḥ pittaśleṣmajvaraṃ hanti sāsṛkpittaṃ sakāmalam" },
      { type: "verse", number: "93", sanskrit: "अनन्ताविश्वभैषज्यकटुकातोयतोयदाः ज्वरतृड्भ्रमसम्मोहधूमकाम्लकनाशनाः", text: "anantāviśvabhaiṣajyakaṭukātoyatoyadāḥ jvaratṛḍbhramasammohadhūmakāmlakanāśanāḥ" },
      { type: "verse", number: "94", sanskrit: "सन्निपातज्वरे व्याघ्नीदेवदारुनिशाद्वयम् पटोलपत्रनिम्बत्वक् त्रिफलाकटुकायुतम्", text: "sannipātajvare vyāghnīdevadāruniśādvayam paṭolapatranimbatvak triphalākaṭukāyutam" },
      { type: "verse", number: "95", sanskrit: "मुस्तापर्पटकं पथ्या मृद्वीका कटुरोहिणी त्रायन्तीकणतन्मूलद्राक्षापथ्यामधूलिकाः", text: "mustāparpaṭakaṃ pathyā mṛdvīkā kaṭurohiṇī trāyantīkaṇatanmūladrākṣāpathyāmadhūlikāḥ" },
      { type: "verse", number: "96", sanskrit: "त्रिफलोशीरषड्ग्रन्थायष्टीमधुबलाघनाः नागरं पौष्करं मूलं गुडूची कण्टकारिका", text: "triphalośīraṣaḍgranthāyaṣṭīmadhubalāghanāḥ nāgaraṃ pauṣkaraṃ mūlaṃ guḍūcī kaṇṭakārikā" },
      { type: "verse", number: "97", sanskrit: "सकासश्वासपार्श्वार्तौ वातश्लेष्मोत्तरे ज्वरे मधूकपुष्पमृद्वीका त्रायमाणा परूषकम्", text: "sakāsaśvāsapārśvārtau vātaśleṣmottare jvare madhūkapuṣpamṛdvīkā trāyamāṇā parūṣakam" },
      { type: "verse", number: "98", sanskrit: "सोशीरतिक्तात्रिफलाकाश्मर्यं कल्पयेद्धिमम् कषायं तं पिबन् काले ज्वरान् सर्वानपोहति", text: "sośīratiktātriphalākāśmaryaṃ kalpayeddhimam kaṣāyaṃ taṃ piban kāle jvarān sarvānapohati" },
      { type: "verse", number: "99", sanskrit: "जात्यामलकमुस्तानि तद्वद्धन्वयवासकम् बद्धविट् कटुकाद्राक्षात्रायन्तीत्रिफलागुडान्", text: "jātyāmalakamustāni tadvaddhanvayavāsakam baddhaviṭ kaṭukādrākṣātrāyantītriphalāguḍān" },
      { type: "verse", number: "100", sanskrit: "जीर्णौषधो ऽन्नं पेयाद्यमाचरेच्छ्लेष्मवान्न तु पेया कफं वर्धयति पङ्कं पांसुषु वृष्टिवत्", text: "jīrṇauṣadho 'nnaṃ peyādyamācarecchleṣmavānna tu peyā kaphaṃ vardhayati paṅkaṃ pāṃsuṣu vṛṣṭivat" },
      { type: "verse", number: "101", sanskrit: "श्लेष्माभिष्यण्णदेहानामतः प्रागपि योजयेत् यूषान् कुलत्थचणककलायादिकृतान् लघून् रूक्षांस्तिक्तरसोपेतान् हृद्यान् रुचिकरान् पटून्", text: "śleṣmābhiṣyaṇṇadehānāmataḥ prāgapi yojayet yūṣān kulatthacaṇakakalāyādikṛtān laghūn rūkṣāṃstiktarasopetān hṛdyān rucikarān paṭūn" },
      { type: "verse", number: "102", sanskrit: "रक्ताद्याः शालयो जीर्णाः षष्टिकाश्च ज्वरे हिताः श्लेष्मोत्तरे वीततुषास्तथा वाट्यकृता यवाः", text: "raktādyāḥ śālayo jīrṇāḥ ṣaṣṭikāśca jvare hitāḥ śleṣmottare vītatuṣāstathā vāṭyakṛtā yavāḥ" },
      { type: "verse", number: "103", sanskrit: "ओदनस्तैः स्रुतो द्विस्त्रिः प्रयोक्तव्यो यथायथम् दोषदूष्यादिबलतो ज्वरघ्नक्वाथसाधितः", text: "odanastaiḥ sruto dvistriḥ prayoktavyo yathāyatham doṣadūṣyādibalato jvaraghnakvāthasādhitaḥ" },
      { type: "verse", number: "104", sanskrit: "मुद्गाद्यैर्लघुभिर्यूषाः कुलत्थैश्च ज्वरापहाः कारवेल्लककर्कोटबालमूलकपर्पटैः वार्ताकनिम्बकुसुमपटोलफलपल्लवैः", text: "mudgādyairlaghubhiryūṣāḥ kulatthaiśca jvarāpahāḥ kāravellakakarkoṭabālamūlakaparpaṭaiḥ vārtākanimbakusumapaṭolaphalapallavaiḥ" },
      { type: "verse", number: "105", sanskrit: "अत्यन्तलघुभिर्मांसैर्जाङ्गलैश्च हिता रसाः व्याघ्रीपरूषतर्कारीद्राक्षामलकदाडिमैः", text: "atyantalaghubhirmāṃsairjāṅgalaiśca hitā rasāḥ vyāghrīparūṣatarkārīdrākṣāmalakadāḍimaiḥ" },
      { type: "verse", number: "106", sanskrit: "संस्कृताः पिप्पलीशुण्ठीधान्यजीरकसैन्धवैः सितामधुभ्यां प्रायेण संयुता वा कृताकृताः", text: "saṃskṛtāḥ pippalīśuṇṭhīdhānyajīrakasaindhavaiḥ sitāmadhubhyāṃ prāyeṇa saṃyutā vā kṛtākṛtāḥ" },
      { type: "verse", number: "107", sanskrit: "अनम्लतक्रसिद्धानि रुच्यानि व्यञ्जनानि च अच्छान्यनलसम्पन्नान्यनुपाने ऽपि योजयेत् तानि क्वथितशीतं च वारि मद्यं च सात्म्यतः", text: "anamlatakrasiddhāni rucyāni vyañjanāni ca acchānyanalasampannānyanupāne 'pi yojayet tāni kvathitaśītaṃ ca vāri madyaṃ ca sātmyataḥ" },
      { type: "verse", number: "108", sanskrit: "कषायपानपथ्यान्नैर्दशाह इति लङ्घते सर्पिर्दद्यात् कफे मन्दे वातपित्तोत्तरे ज्वरे पक्वेषु दोषेष्वमृतं तद्विषोपममन्यथा", text: "kaṣāyapānapathyānnairdaśāha iti laṅghate sarpirdadyāt kaphe mande vātapittottare jvare pakveṣu doṣeṣvamṛtaṃ tadviṣopamamanyathā" },
      { type: "verse", number: "109", sanskrit: "दशाहे स्यादतीते ऽपि ज्वरोपद्रववृद्धिकृत् लङ्घनादिक्रमं तत्र कुर्यादा कफसङ्क्षयात्", text: "daśāhe syādatīte 'pi jvaropadravavṛddhikṛt laṅghanādikramaṃ tatra kuryādā kaphasaṅkṣayāt" },
      { type: "verse", number: "110", sanskrit: "सज्वरं ज्वरमुक्तं वा दिनान्ते भोजयेल्लघु श्लेष्मक्षयविवृद्धोष्मा बलवाननलस्तदा", text: "sajvaraṃ jvaramuktaṃ vā dinānte bhojayellaghu śleṣmakṣayavivṛddhoṣmā balavānanalastadā" },
      { type: "verse", number: "111", sanskrit: "यथोचिते ऽथवा काले दोषसात्म्यानुरोधतः प्रागल्पवह्निर्भुञ्जानो न ह्यजीर्णेन पीड्यते", text: "yathocite 'thavā kāle doṣasātmyānurodhataḥ prāgalpavahnirbhuñjāno na hyajīrṇena pīḍyate" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 2,
    lang: "sa",
    content: [
      { type: "heading", heading: "Рактапитта чикитса — лечение кровотечений" },
      { type: "text", text: "Глава 2 Чикитса стханы — лечебный раздел о лечение кровотечений. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो जीर्णज्वरचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto jīrṇajvaracikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "देहधात्वबलत्वेन ज्वरो जीर्णो ऽनुवर्तते", text: "dehadhātvabalatvena jvaro jīrṇo 'nuvartate" },
      { type: "verse", number: "3", sanskrit: "रूक्षं हि तेजो ज्वरकृत्तेजसा रूक्षितस्य च वमनस्वेदकालाम्बुकषायलघुभोजनैः", text: "rūkṣaṃ hi tejo jvarakṛttejasā rūkṣitasya ca vamanasvedakālāmbukaṣāyalaghubhojanaiḥ" },
      { type: "verse", number: "4", sanskrit: "यः स्यादतिबलो धातुः सहचारी सदागतिः तस्य संशमनं सर्पिर्दीप्तस्येवाम्बु वेश्मनः", text: "yaḥ syādatibalo dhātuḥ sahacārī sadāgatiḥ tasya saṃśamanaṃ sarpirdīptasyevāmbu veśmanaḥ" },
      { type: "verse", number: "5", sanskrit: "वातपित्तजितामग्न्यं संस्कारमनुरुध्यते सुतरां तद्ध्यतो दद्याद्यथास्वौषधसाधितम्", text: "vātapittajitāmagnyaṃ saṃskāramanurudhyate sutarāṃ taddhyato dadyādyathāsvauṣadhasādhitam" },
      { type: "verse", number: "6", sanskrit: "विपरीतं ज्वरोष्माणं जयेत् पित्तं च शैत्यतः स्नेहाद्वातं घृतं तुल्यं योगसंस्कारतः कफम्", text: "viparītaṃ jvaroṣmāṇaṃ jayet pittaṃ ca śaityataḥ snehādvātaṃ ghṛtaṃ tulyaṃ yogasaṃskārataḥ kapham" },
      { type: "verse", number: "7", sanskrit: "पूर्वे कषायाः सघृताः सर्वे योज्या यथामलम् त्रिफलापिचुमन्दत्वङ्मधुकं बृहतीद्वयम् समसूरदलं क्वाथः सघृतो ज्वरकासहा", text: "pūrve kaṣāyāḥ saghṛtāḥ sarve yojyā yathāmalam triphalāpicumandatvaṅmadhukaṃ bṛhatīdvayam samasūradalaṃ kvāthaḥ saghṛto jvarakāsahā" },
      { type: "verse", number: "8", sanskrit: "निदिग्धिकातामलफीत्रायमाणाकलिङ्गकैः कृष्णांशुमत्यतिविषाकटुकासेव्यचन्दनैः", text: "nidigdhikātāmalaphītrāyamāṇākaliṅgakaiḥ kṛṣṇāṃśumatyativiṣākaṭukāsevyacandanaiḥ" },
      { type: "verse", number: "9", sanskrit: "धात्रीबिल्वघनद्राक्षासारिवाभिश्च साधितम् हन्ति सद्यो घृतं जीर्णज्वरं कासं हलीमकम् अरुचिं विषमं वह्निं यक्ष्माणं च नवोत्थितम्", text: "dhātrībilvaghanadrākṣāsārivābhiśca sādhitam hanti sadyo ghṛtaṃ jīrṇajvaraṃ kāsaṃ halīmakam aruciṃ viṣamaṃ vahniṃ yakṣmāṇaṃ ca navotthitam" },
      { type: "verse", number: "10", sanskrit: "वासागुडूचीत्रिफलात्रायमाणायवासकात् क्वाथे क्षीरे च विपचेत् ज्वरघ्नं कल्कितैर्घृतम् पिप्पलीमुस्तमृद्वीकाचन्दनोत्पलनागैरः", text: "vāsāguḍūcītriphalātrāyamāṇāyavāsakāt kvāthe kṣīre ca vipacet jvaraghnaṃ kalkitairghṛtam pippalīmustamṛdvīkācandanotpalanāgairaḥ" },
      { type: "verse", number: "11", sanskrit: "बलादुरालभामुस्तात्रायतीनिम्बपर्पटम् पञ्चमूलद्वयं यच्च क्वाथयित्वा घृतं पचेत् सक्षीरं कल्कितैर्द्राक्षामेदामलकपौष्करैः", text: "balādurālabhāmustātrāyatīnimbaparpaṭam pañcamūladvayaṃ yacca kvāthayitvā ghṛtaṃ pacet sakṣīraṃ kalkitairdrākṣāmedāmalakapauṣkaraiḥ" },
      { type: "verse", number: "12", sanskrit: "शठीतामलकीयुक्तैस्तच्च ज्वरहरं परम् क्षयकासशिरःपार्श्वहृच्छूलांसाभितापनुत्", text: "śaṭhītāmalakīyuktaistacca jvaraharaṃ param kṣayakāsaśiraḥpārśvahṛcchūlāṃsābhitāpanut" },
      { type: "verse", number: "13", sanskrit: "कुलत्थकोलत्रिफलादशमूलयवान् पचेत् द्विपलान् सलिलद्रोणे पूते पिष्ट्वाक्सकान् क्षिपेत्", text: "kulatthakolatriphalādaśamūlayavān pacet dvipalān saliladroṇe pūte piṣṭvāksakān kṣipet" },
      { type: "verse", number: "14", sanskrit: "पञ्चकोलकसप्ताह्ववयस्थानिम्बतुम्बुरून् शठीपुष्करमूलार्कमूलप्रतिविषावचाः", text: "pañcakolakasaptāhvavayasthānimbatumburūn śaṭhīpuṣkaramūlārkamūlaprativiṣāvacāḥ" },
      { type: "verse", number: "15", sanskrit: "किराततिक्तकं मुस्तं कर्कटाख्यां दुरालभाम् नक्तमालमुभे पाठे कटुकाशिग्रुतेजनीः", text: "kirātatiktakaṃ mustaṃ karkaṭākhyāṃ durālabhām naktamālamubhe pāṭhe kaṭukāśigrutejanīḥ" },
      { type: "verse", number: "16", sanskrit: "सोमवल्कद्विरजनीकण्टकीकण्टकारिकाः पटोलहिङ्गुगोजिह्वाकेबुकं मदनाज्झटा", text: "somavalkadvirajanīkaṇṭakīkaṇṭakārikāḥ paṭolahiṅgugojihvākebukaṃ madanājjhaṭā" },
      { type: "verse", number: "17", sanskrit: "लवणानि पलांशानि क्षारानर्धपलोन्मितान् प्रस्थं चाज्यस्य तत्सिद्धं दीपनं कफवातजित्", text: "lavaṇāni palāṃśāni kṣārānardhapalonmitān prasthaṃ cājyasya tatsiddhaṃ dīpanaṃ kaphavātajit" },
      { type: "verse", number: "18", sanskrit: "हृत्प्लीहग्रहणीगुल्मकासश्वासार्शसां हितम् दीर्घज्वराभिभूतानां ज्वरिणाममृतोपमम्", text: "hṛtplīhagrahaṇīgulmakāsaśvāsārśasāṃ hitam dīrghajvarābhibhūtānāṃ jvariṇāmamṛtopamam" },
      { type: "verse", number: "19", sanskrit: "मञ्जिष्ठातिविषापथ्यावचानागररोहिणीः देवदारु हरिद्रां च द्रोणे ऽपां पालिकान् पचेत् क्वाथे ऽस्मिन् साधयेत् पिष्टैर्घृतप्रस्थं पिचून्मितैः", text: "mañjiṣṭhātiviṣāpathyāvacānāgararohiṇīḥ devadāru haridrāṃ ca droṇe 'pāṃ pālikān pacet kvāthe 'smin sādhayet piṣṭairghṛtaprasthaṃ picūnmitaiḥ" },
      { type: "verse", number: "20", sanskrit: "शृङ्गवेरकणाहिङ्गुद्विक्षारपटुपञ्चकैः तत्कफावृतसर्वोत्थज्वरिणाममृतोपमम्", text: "śṛṅgaverakaṇāhiṅgudvikṣārapaṭupañcakaiḥ tatkaphāvṛtasarvotthajvariṇāmamṛtopamam" },
      { type: "verse", number: "21", sanskrit: "वर्ध्महिध्मारुचिश्वासकासपाण्डुविकारिणाम् गलग्रह (ग्रन्थि) प्रमेहार्शः प्लीहापस्मारशोफिनाम् उदावर्तपरीतानां मन्दाग्निकृमिकोष्ठिनाम्", text: "vardhmahidhmāruciśvāsakāsapāṇḍuvikāriṇām galagraha (granthi) pramehārśaḥ plīhāpasmāraśophinām udāvartaparītānāṃ mandāgnikṛmikoṣṭhinām" },
      { type: "verse", number: "22", sanskrit: "गुडूच्या रसकल्काभ्यां त्रिफलाया वृषस्य च मृद्वीकाया बलायाश्च सिद्धाः स्नेहा ज्वरच्छिदः", text: "guḍūcyā rasakalkābhyāṃ triphalāyā vṛṣasya ca mṛdvīkāyā balāyāśca siddhāḥ snehā jvaracchidaḥ" },
      { type: "verse", number: "23", sanskrit: "जीर्णे घृते च भुञ्जीत मुदुमांसरसौदनम् बलं ह्यलं दोषहरं परं तच्च बलप्रदम्", text: "jīrṇe ghṛte ca bhuñjīta mudumāṃsarasaudanam balaṃ hyalaṃ doṣaharaṃ paraṃ tacca balapradam" },
      { type: "verse", number: "24", sanskrit: "कफपित्तहरा मुद्गकारवेल्लादिजा रसाः प्रायेण तस्मान्न हिता जीर्णे वातोत्तरे ज्वरे शूलोदावर्तविष्टम्भजनना ज्वरवर्धनाः", text: "kaphapittaharā mudgakāravellādijā rasāḥ prāyeṇa tasmānna hitā jīrṇe vātottare jvare śūlodāvartaviṣṭambhajananā jvaravardhanāḥ" },
      { type: "verse", number: "25", sanskrit: "न शाम्यत्येवमपि चेज्ज्वरः कुर्वीत शोधनम् शोधनार्हस्य वमनं प्रागुक्तं तस्य योजयेत् आमाशयगते दोषे बलिनः पालयन् बलम्", text: "na śāmyatyevamapi cejjvaraḥ kurvīta śodhanam śodhanārhasya vamanaṃ prāguktaṃ tasya yojayet āmāśayagate doṣe balinaḥ pālayan balam" },
      { type: "verse", number: "26", sanskrit: "सन्तर्पणोत्थे वमनं पिप्पलीलवणाम्बुना शर्करामाक्षिकाम्भोभिर्दाहतृष्णोल्बणे ज्वरे", text: "santarpaṇotthe vamanaṃ pippalīlavaṇāmbunā śarkarāmākṣikāmbhobhirdāhatṛṣṇolbaṇe jvare" },
      { type: "verse", number: "27", sanskrit: "पक्वे तु शिथिले दोषे ज्वरे वा विषमद्यजे मोदकं त्रिफलाश्यामात्रिवृत्पिप्पलिकेसरैः", text: "pakve tu śithile doṣe jvare vā viṣamadyaje modakaṃ triphalāśyāmātrivṛtpippalikesaraiḥ" },
      { type: "verse", number: "28", sanskrit: "ससितामधुभिर्दद्याद्व्योषाद्यं वा विरेचनम् द्राक्षाधात्रीरसं तद्वत्सद्राक्षां वा हरीतकीम् रसमामलकानां वा घृतभृष्टं ज्वरापहम्", text: "sasitāmadhubhirdadyādvyoṣādyaṃ vā virecanam drākṣādhātrīrasaṃ tadvatsadrākṣāṃ vā harītakīm rasamāmalakānāṃ vā ghṛtabhṛṣṭaṃ jvarāpaham" },
      { type: "verse", number: "29", sanskrit: "लिह्याद्वा त्रिवृतश्चूर्णं कृष्णात्रिफलयोस्तथा सर्पिर्मधुभ्यां त्रिफलां पिबेद्राक्सारसेन वा", text: "lihyādvā trivṛtaścūrṇaṃ kṛṣṇātriphalayostathā sarpirmadhubhyāṃ triphalāṃ pibedrāksārasena vā" },
      { type: "verse", number: "30", sanskrit: "आरग्वधं वा पयसा मृद्वीकानां रसेन वा त्रिफलां त्रायमाणां वा पयसा ज्वरितः पिबेत्", text: "āragvadhaṃ vā payasā mṛdvīkānāṃ rasena vā triphalāṃ trāyamāṇāṃ vā payasā jvaritaḥ pibet" },
      { type: "verse", number: "31", sanskrit: "सघृतं त्रिफलाक्वाथं सर्पिषा वा विना शृतम् पयो ऽनुपानमुष्णं वा मृद्वीकास्वरसं पिबेत् विरिक्तानां च संसर्गी मण्डपूर्वा यथाक्रमम्", text: "saghṛtaṃ triphalākvāthaṃ sarpiṣā vā vinā śṛtam payo 'nupānamuṣṇaṃ vā mṛdvīkāsvarasaṃ pibet viriktānāṃ ca saṃsargī maṇḍapūrvā yathākramam" },
      { type: "verse", number: "32", sanskrit: "च्यवमानं ज्वरोत्क्लिष्टमुपेक्षेत मलं सदा पक्वो ऽपि हि विकुर्वीत दोषः कोष्ठे कृतास्पदः", text: "cyavamānaṃ jvarotkliṣṭamupekṣeta malaṃ sadā pakvo 'pi hi vikurvīta doṣaḥ koṣṭhe kṛtāspadaḥ" },
      { type: "verse", number: "33", sanskrit: "अतिप्रवर्तमानं वा पाचयन् सङ्ग्रहं नयेत्", text: "atipravartamānaṃ vā pācayan saṅgrahaṃ nayet" },
      { type: "verse", number: "34", sanskrit: "आमसङ्ग्रहणे दोषा दोषोपक्रम ईरिताः", text: "āmasaṅgrahaṇe doṣā doṣopakrama īritāḥ" },
      { type: "verse", number: "35", sanskrit: "पाययेद्दोषहरणं मोहादामज्वरे तु यः प्रसुप्तं कृष्णसर्पं स कराग्रेण परामृशेत्", text: "pāyayeddoṣaharaṇaṃ mohādāmajvare tu yaḥ prasuptaṃ kṛṣṇasarpaṃ sa karāgreṇa parāmṛśet" },
      { type: "verse", number: "36", sanskrit: "ज्वरक्षीणस्य न हितं वमनं न विरेचनम् कामं तु पयसा तस्य निरूहैर्वा हरेन्मलान्", text: "jvarakṣīṇasya na hitaṃ vamanaṃ na virecanam kāmaṃ tu payasā tasya nirūhairvā harenmalān" },
      { type: "verse", number: "37", sanskrit: "क्षीरोचितस्य प्रक्षीणश्लेष्मणो दाहतृङ्वतः क्षीरं पित्तानिलार्तस्य पथ्यमप्यतिसारिणः", text: "kṣīrocitasya prakṣīṇaśleṣmaṇo dāhatṛṅvataḥ kṣīraṃ pittānilārtasya pathyamapyatisāriṇaḥ" },
      { type: "verse", number: "38", sanskrit: "तद्वपुर्लंघनोत्तप्तं प्लुष्टं वनमिवाग्निना दिव्याम्बु जीवयेत्तस्य ज्वरं चाशु नियच्छति", text: "tadvapurlaṃghanottaptaṃ pluṣṭaṃ vanamivāgninā divyāmbu jīvayettasya jvaraṃ cāśu niyacchati" },
      { type: "verse", number: "39", sanskrit: "संस्कृतं शीतमुष्णं वा तस्माद्धारोष्णमेव वा विभज्य काले युञ्जीत ज्वरिणं हन्त्यतो ऽन्यथा", text: "saṃskṛtaṃ śītamuṣṇaṃ vā tasmāddhāroṣṇameva vā vibhajya kāle yuñjīta jvariṇaṃ hantyato 'nyathā" },
      { type: "verse", number: "40", sanskrit: "पयः सशुण्ठीखर्जूरमृद्वीकाशर्कराघृतम् शृतशीतं मधुयुतं तृड्दाहज्वरनाशनम्", text: "payaḥ saśuṇṭhīkharjūramṛdvīkāśarkarāghṛtam śṛtaśītaṃ madhuyutaṃ tṛḍdāhajvaranāśanam" },
      { type: "verse", number: "41", sanskrit: "तद्वद्द्राक्षाबलायष्टीसारिबाकणचन्दनैः चतुर्गुणेनाम्भसा वा पिप्पल्या वा शृतं पिबेत्", text: "tadvaddrākṣābalāyaṣṭīsāribākaṇacandanaiḥ caturguṇenāmbhasā vā pippalyā vā śṛtaṃ pibet" },
      { type: "verse", number: "42", sanskrit: "कासाच्छ्वासाच्छिरश्शूलान् पार्श्वशूलाच्चिरज्वरात् मुच्यते ज्वरितः पीत्वा पञ्चमूलीशृतं पयः", text: "kāsācchvāsācchiraśśūlān pārśvaśūlāccirajvarāt mucyate jvaritaḥ pītvā pañcamūlīśṛtaṃ payaḥ" },
      { type: "verse", number: "43", sanskrit: "शृतमरेण्डमूलेन बालविल्वेन वा ज्वरात् धारोष्णं वा पयः पीत्वा विबद्धानिलवर्चसः सरक्तपिच्छातिसृतेः सतृट्शूलप्रवाहिकात्", text: "śṛtamareṇḍamūlena bālavilvena vā jvarāt dhāroṣṇaṃ vā payaḥ pītvā vibaddhānilavarcasaḥ saraktapicchātisṛteḥ satṛṭśūlapravāhikāt" },
      { type: "verse", number: "44", sanskrit: "सिद्धं शुण्ठीबलाव्याघ्नीगोकण्टकगुडैः पयः शोफमूत्रशकृद्वातविबन्धज्वरकासजित्", text: "siddhaṃ śuṇṭhībalāvyāghnīgokaṇṭakaguḍaiḥ payaḥ śophamūtraśakṛdvātavibandhajvarakāsajit" },
      { type: "verse", number: "45", sanskrit: "वृश्चीवबिल्ववर्षाभूसाधितं ज्वरशोफनुत् शिंशिपासारसिद्धं च क्षीरमाशु ज्वरापहम्", text: "vṛścīvabilvavarṣābhūsādhitaṃ jvaraśophanut śiṃśipāsārasiddhaṃ ca kṣīramāśu jvarāpaham" },
      { type: "verse", number: "46", sanskrit: "निरूहस्तु बलं वह्निं विज्वरत्वं मुदं रुचिम् दोषे युक्तः करोत्याशु पक्वे पक्वाशयं गते", text: "nirūhastu balaṃ vahniṃ vijvaratvaṃ mudaṃ rucim doṣe yuktaḥ karotyāśu pakve pakvāśayaṃ gate" },
      { type: "verse", number: "47", sanskrit: "पित्तं वा कफपित्तं वा पक्वाशयगतं हरेत् स्रंसनं त्रीनपि मलान् बस्तिः पक्वाशयाश्रयान्", text: "pittaṃ vā kaphapittaṃ vā pakvāśayagataṃ haret sraṃsanaṃ trīnapi malān bastiḥ pakvāśayāśrayān" },
      { type: "verse", number: "48", sanskrit: "प्रक्षीणकफपित्तस्य त्रिकपृष्ठकटीग्रहे दीप्ताग्नेर्बद्धशकृतः प्रयुञ्जीतानुवासनम्", text: "prakṣīṇakaphapittasya trikapṛṣṭhakaṭīgrahe dīptāgnerbaddhaśakṛtaḥ prayuñjītānuvāsanam" },
      { type: "verse", number: "49", sanskrit: "पटोलनिम्बच्छदनकटुकाचतुरङ्गुलैः स्थिराबलागोक्षुरकमदनोशीरवालकैः", text: "paṭolanimbacchadanakaṭukācaturaṅgulaiḥ sthirābalāgokṣurakamadanośīravālakaiḥ" },
      { type: "verse", number: "50", sanskrit: "पयस्यर्धोदके क्वाथं क्षीरशेषं विमिश्रितम् कल्कितैर्मुस्तमदनकृष्णामधुकवत्सकैः बस्तिं मधुघृताभ्यां च पीडयेज्ज्वरनाशनम्", text: "payasyardhodake kvāthaṃ kṣīraśeṣaṃ vimiśritam kalkitairmustamadanakṛṣṇāmadhukavatsakaiḥ bastiṃ madhughṛtābhyāṃ ca pīḍayejjvaranāśanam" },
      { type: "verse", number: "51", sanskrit: "चतस्रः पर्णिनीर्यष्टीफलोशीरनृपद्रुमान् क्वाथयेत् कल्कयेद्यष्टीशताह्वाफलिनीफलम् मुस्तं च बस्तिः सगुडक्षौद्रसर्पिर्ज्वरापहः", text: "catasraḥ parṇinīryaṣṭīphalośīranṛpadrumān kvāthayet kalkayedyaṣṭīśatāhvāphalinīphalam mustaṃ ca bastiḥ saguḍakṣaudrasarpirjvarāpahaḥ" },
      { type: "verse", number: "52", sanskrit: "त्रायमाणामृतायष्टीमदनांशुमतीद्वयैः सबलाचन्दनवृषैर्जाङ्गलैश्च मृगद्विजैः", text: "trāyamāṇāmṛtāyaṣṭīmadanāṃśumatīdvayaiḥ sabalācandanavṛṣairjāṅgalaiśca mṛgadvijaiḥ" },
      { type: "verse", number: "53", sanskrit: "क्वाथे कृते क्षिपेत् पिष्ट्वा फलयष्टीकणाघनम् स सद्यो ज्वरहा बस्तिः साज्यक्षौद्रो ऽल्पसैन्धवः", text: "kvāthe kṛte kṣipet piṣṭvā phalayaṣṭīkaṇāghanam sa sadyo jvarahā bastiḥ sājyakṣaudro 'lpasaindhavaḥ" },
      { type: "verse", number: "54", sanskrit: "आम्रादीनां त्वचं शङ्खं चन्दनं मधुकोत्पलम् स्वर्णगौरिकमाञ्जिष्ठामृणालाञ्जनपद्मकम्", text: "āmrādīnāṃ tvacaṃ śaṅkhaṃ candanaṃ madhukotpalam svarṇagaurikamāñjiṣṭhāmṛṇālāñjanapadmakam" },
      { type: "verse", number: "55", sanskrit: "क्षीरेण कल्कितं बस्तिं शीतं समधुशर्करम् दाहज्वरहरं दद्यात्सिद्धं तैश्चानुवासनम्", text: "kṣīreṇa kalkitaṃ bastiṃ śītaṃ samadhuśarkaram dāhajvaraharaṃ dadyātsiddhaṃ taiścānuvāsanam" },
      { type: "verse", number: "56", sanskrit: "जीवन्तीं मदनं मेदां पिप्पलीं मधुकं वचाम् ऋद्धिं रास्नां बिल्वं शतपुष्पां शतावरीम्", text: "jīvantīṃ madanaṃ medāṃ pippalīṃ madhukaṃ vacām ṛddhiṃ rāsnāṃ bilvaṃ śatapuṣpāṃ śatāvarīm" },
      { type: "verse", number: "57", sanskrit: "पिष्ट्वा क्षीरं जलं सर्पिस्तैलं चैकत्र साधितम् ज्वरे ऽनुवासनं कुर्यात्तथा स्नेहं यथामलम्", text: "piṣṭvā kṣīraṃ jalaṃ sarpistailaṃ caikatra sādhitam jvare 'nuvāsanaṃ kuryāttathā snehaṃ yathāmalam" },
      { type: "verse", number: "58", sanskrit: "चन्दनागरुकाश्मर्यपटोलमदनोत्पलैः पटोलारिष्टमदनगुडूचीमधुकैरपि ये च सिद्धिषु वक्ष्यन्ते बस्तयो ज्वरनाशनाः", text: "candanāgarukāśmaryapaṭolamadanotpalaiḥ paṭolāriṣṭamadanaguḍūcīmadhukairapi ye ca siddhiṣu vakṣyante bastayo jvaranāśanāḥ" },
      { type: "verse", number: "59", sanskrit: "शिरोरुग्गौरवश्लेष्महरमिन्द्रियबोधनम् जीर्णज्वरे रुचिकरं दद्यान्नस्यं विरेचनम् स्नैहिकं शून्यशिरसो दाहार्ते पित्तनाशनम्", text: "śiroruggauravaśleṣmaharamindriyabodhanam jīrṇajvare rucikaraṃ dadyānnasyaṃ virecanam snaihikaṃ śūnyaśiraso dāhārte pittanāśanam" },
      { type: "verse", number: "60", sanskrit: "धूमगण्डूषकवलान् यथादोषं च कल्पयेत् प्रतिश्यायास्यवैरस्यशिरः कण्ठामयापहान्", text: "dhūmagaṇḍūṣakavalān yathādoṣaṃ ca kalpayet pratiśyāyāsyavairasyaśiraḥ kaṇṭhāmayāpahān" },
      { type: "verse", number: "61", sanskrit: "अरुचौ मातुलुङ्गस्य केसरं साज्यसैन्धवम् धात्रीद्राक्षासितानां वा कल्कमास्येन धारयेत्", text: "arucau mātuluṅgasya kesaraṃ sājyasaindhavam dhātrīdrākṣāsitānāṃ vā kalkamāsyena dhārayet" },
      { type: "verse", number: "62", sanskrit: "यथोपशयसंस्पर्शान् शीतोष्णद्रव्यकल्पितान् अभ्यङ्गालेपसेकादीन् ज्वरे जीर्णे त्वगाश्रिते कुर्यादञ्जनधूपांश्च तथैवागन्तुजे ऽपि तान्", text: "yathopaśayasaṃsparśān śītoṣṇadravyakalpitān abhyaṅgālepasekādīn jvare jīrṇe tvagāśrite kuryādañjanadhūpāṃśca tathaivāgantuje 'pi tān" },
      { type: "verse", number: "63", sanskrit: "दाहे सहस्रधौतेन सर्पिषाभ्यङ्गमाचरेत्", text: "dāhe sahasradhautena sarpiṣābhyaṅgamācaret" },
      { type: "verse", number: "64", sanskrit: "सूत्रोक्तैश्च गणैस्तैस्तैर्मधुराम्लकषायकैः दूर्वादिभिर्वा पित्तघ्नैः शोधनादिगणोदितैः", text: "sūtroktaiśca gaṇaistaistairmadhurāmlakaṣāyakaiḥ dūrvādibhirvā pittaghnaiḥ śodhanādigaṇoditaiḥ" },
      { type: "verse", number: "65", sanskrit: "शीतवीर्यैर्हिमस्पर्शैः क्वाथकल्कीकृतैः पचेत् तैलं सक्षीरमभ्यङ्गात्सद्यो दाहज्वरापहम्", text: "śītavīryairhimasparśaiḥ kvāthakalkīkṛtaiḥ pacet tailaṃ sakṣīramabhyaṅgātsadyo dāhajvarāpaham" },
      { type: "verse", number: "66", sanskrit: "चन्दनं मधुकं काला द्राक्षा मधुरसा निशा तत्सिद्धं पूर्ववत्तैलं दाहज्वरहरं परम्", text: "candanaṃ madhukaṃ kālā drākṣā madhurasā niśā tatsiddhaṃ pūrvavattailaṃ dāhajvaraharaṃ param" },
      { type: "verse", number: "67", sanskrit: "शिरो गात्रं च तैरेव नातिपिष्टैः प्रलेपयेत् तत्क्वाथेन परीषेकमवगाहं च योजयेत् तथारनालसलिलक्षीरशुक्तघृतादिभिः", text: "śiro gātraṃ ca taireva nātipiṣṭaiḥ pralepayet tatkvāthena parīṣekamavagāhaṃ ca yojayet tathāranālasalilakṣīraśuktaghṛtādibhiḥ" },
      { type: "verse", number: "68", sanskrit: "कपित्थमातुलुङ्गाम्लविदारीलोध्रदाडिमैः बदरीपल्लवोत्थेन फेनेनारिष्टकस्य वा", text: "kapitthamātuluṅgāmlavidārīlodhradāḍimaiḥ badarīpallavotthena phenenāriṣṭakasya vā" },
      { type: "verse", number: "69", sanskrit: "कर्पूरपद्मकोशीरकालीयाम्बुकुचन्दनैः तुङ्गप्रियङ्गुशैवालकमलोत्पलकर्दमैः", text: "karpūrapadmakośīrakālīyāmbukucandanaiḥ tuṅgapriyaṅguśaivālakamalotpalakardamaiḥ" },
      { type: "verse", number: "70", sanskrit: "वेत्राग्रलोध्रपुण्ड्राह्वैरारनालेन कल्कितैः लेपा व्यस्तैः समस्तैर्वा दाहघ्ना वर्णकारिणः", text: "vetrāgralodhrapuṇḍrāhvairāranālena kalkitaiḥ lepā vyastaiḥ samastairvā dāhaghnā varṇakāriṇaḥ" },
      { type: "verse", number: "71", sanskrit: "धात्रीत्वक्पत्रनलदशङ्खव्याघ्रनखोत्पलैः चन्दनाञ्जनमुस्तैश्च सवृक्षाम्लाम्लवेतसैः", text: "dhātrītvakpatranaladaśaṅkhavyāghranakhotpalaiḥ candanāñjanamustaiśca savṛkṣāmlāmlavetasaiḥ" },
      { type: "verse", number: "72", sanskrit: "सजीवकैः समधुकैः सपलाशैः सदाडिमैः बीजपूररसक्षौद्रशुक्तयुक्तैः प्रलेपितैः", text: "sajīvakaiḥ samadhukaiḥ sapalāśaiḥ sadāḍimaiḥ bījapūrarasakṣaudraśuktayuktaiḥ pralepitaiḥ" },
      { type: "verse", number: "73", sanskrit: "शिरस्यङ्गे च तृट्छर्दिदाहमोहशिरोरुजः नश्यन्ति गण्डाः पिटकाः प्रलापश्च ज्वरार्तिजः", text: "śirasyaṅge ca tṛṭchardidāhamohaśirorujaḥ naśyanti gaṇḍāḥ piṭakāḥ pralāpaśca jvarārtijaḥ" },
      { type: "verse", number: "74", sanskrit: "गौरामलककल्कश्च साम्लः साज्यश्च तद्गुणः मधूकमधुकोदीच्यनीलोत्पलमधूलिकाः", text: "gaurāmalakakalkaśca sāmlaḥ sājyaśca tadguṇaḥ madhūkamadhukodīcyanīlotpalamadhūlikāḥ" },
      { type: "verse", number: "75", sanskrit: "जयन्ति मधुसर्पिर्भ्यां लीढा दाहज्वरभ्रमान् कासासृक्पित्तवीसर्पश्वासहिध्मावमीरपि", text: "jayanti madhusarpirbhyāṃ līḍhā dāhajvarabhramān kāsāsṛkpittavīsarpaśvāsahidhmāvamīrapi" },
      { type: "verse", number: "76", sanskrit: "वाम्यं च वामयेदाशु शीतेन मधुवारिणा यो वर्णितः पित्तहरो दोषोपक्रमणे क्रमः तं च शीलयतः शीघ्रं सदाहो नश्यति ज्वरः", text: "vāmyaṃ ca vāmayedāśu śītena madhuvāriṇā yo varṇitaḥ pittaharo doṣopakramaṇe kramaḥ taṃ ca śīlayataḥ śīghraṃ sadāho naśyati jvaraḥ" },
      { type: "verse", number: "77", sanskrit: "वल्लकीमधुरं गीतं चन्द्रिका हर्म्यमस्तकम् हरन्ति दाहं हाराश्च हरिचन्दनशीतलाः", text: "vallakīmadhuraṃ gītaṃ candrikā harmyamastakam haranti dāhaṃ hārāśca haricandanaśītalāḥ" },
      { type: "verse", number: "78", sanskrit: "दाहं मन्दानिलोद्धूताः कुल्याः सलिलमालिनः चलत्प्रवालाङ्गुलिभिस्तर्जयन्ति महाद्रुमाः", text: "dāhaṃ mandāniloddhūtāḥ kulyāḥ salilamālinaḥ calatpravālāṅgulibhistarjayanti mahādrumāḥ" },
      { type: "verse", number: "79", sanskrit: "वाचः शिशूनामव्यक्ता योषितो मदनातुराः दाहं निर्भत्सयन्त्याशु सज्जनानां च सूनृताः", text: "vācaḥ śiśūnāmavyaktā yoṣito madanāturāḥ dāhaṃ nirbhatsayantyāśu sajjanānāṃ ca sūnṛtāḥ" },
      { type: "verse", number: "80", sanskrit: "रुचिभेदानुरोधेन नानाशक्तिसमन्वितः दाहशीतज्वरहरः कान्ताकान्ताङ्गसङ्गमः दाहशीतव्युपशमे तास्ततो ऽपनयेत् पुनः", text: "rucibhedānurodhena nānāśaktisamanvitaḥ dāhaśītajvaraharaḥ kāntākāntāṅgasaṅgamaḥ dāhaśītavyupaśame tāstato 'panayet punaḥ" },
      { type: "verse", number: "81", sanskrit: "वीर्योष्णैरुष्णसंस्पर्शैस्तगरागरुकुङ्कुमैः कुष्ठस्थौणेयशैलेयसरलामरदारुभिः", text: "vīryoṣṇairuṣṇasaṃsparśaistagarāgarukuṅkumaiḥ kuṣṭhasthauṇeyaśaileyasaralāmaradārubhiḥ" },
      { type: "verse", number: "82", sanskrit: "नखरास्नापुरवचाचण्डलौद्वयचोरकैः पृथ्वीकाशिग्रुसुरसहिंस्राध्यामकसर्षपैः", text: "nakharāsnāpuravacācaṇḍalaudvayacorakaiḥ pṛthvīkāśigrusurasahiṃsrādhyāmakasarṣapaiḥ" },
      { type: "verse", number: "83", sanskrit: "दशमूलमृतैरण्डद्वयपत्तूररोहिषैः तमालपत्रपूतीकसल्लकीधान्यदीप्यकैः", text: "daśamūlamṛtairaṇḍadvayapattūrarohiṣaiḥ tamālapatrapūtīkasallakīdhānyadīpyakaiḥ" },
      { type: "verse", number: "84", sanskrit: "मिसिमाषकुलत्थाग्निप्रकीर्यानाकुलीद्वयैः अन्यैश्च तद्विधैर्द्रव्यैः शीते तैलं ज्वरे पचेत्", text: "misimāṣakulatthāgniprakīryānākulīdvayaiḥ anyaiśca tadvidhairdravyaiḥ śīte tailaṃ jvare pacet" },
      { type: "verse", number: "85", sanskrit: "क्वथितैः कल्फितैर्युक्तैः सुरासौवीरकादिभिः तेनाभ्यज्यात् सुखोष्णेन तैः सुपिष्टैश्च लेपयेत्", text: "kvathitaiḥ kalphitairyuktaiḥ surāsauvīrakādibhiḥ tenābhyajyāt sukhoṣṇena taiḥ supiṣṭaiśca lepayet" },
      { type: "verse", number: "86", sanskrit: "कवोष्णैस्तैः परीषेकमवगाहं च योजयेत् केवलैरपि तद्वच्च शुक्तगोमूत्रमस्तुभिः", text: "kavoṣṇaistaiḥ parīṣekamavagāhaṃ ca yojayet kevalairapi tadvacca śuktagomūtramastubhiḥ" },
      { type: "verse", number: "87", sanskrit: "कुङ्कुमागरुकस्तूरीनखैलासुरदारुभिः शैलेयचण्डात्वङ्मुस्तरास्नाकपिवचामयैः", text: "kuṅkumāgarukastūrīnakhailāsuradārubhiḥ śaileyacaṇḍātvaṅmustarāsnākapivacāmayaiḥ" },
      { type: "verse", number: "88", sanskrit: "पृथक् प्रदेहाः सर्वैर्वा शीतघ्ना दृढकल्किताः यवचूर्णं घृताभ्यक्तं पचेत् क्षीरे चतुर्गुणे", text: "pṛthak pradehāḥ sarvairvā śītaghnā dṛḍhakalkitāḥ yavacūrṇaṃ ghṛtābhyaktaṃ pacet kṣīre caturguṇe" },
      { type: "verse", number: "89", sanskrit: "दर्वीप्रलेपनं लेपं ज्वरार्तस्य प्रयोजयेत् आरग्वधादिवर्गं च पानाभ्यञ्जनलेपने", text: "darvīpralepanaṃ lepaṃ jvarārtasya prayojayet āragvadhādivargaṃ ca pānābhyañjanalepane" },
      { type: "verse", number: "90", sanskrit: "धूपानगरुजान्ये च वक्ष्यन्ते विषमज्वरे अग्न्यनग्निकृतान् स्वेदान् स्वेदि भेषजभोजनम्", text: "dhūpānagarujānye ca vakṣyante viṣamajvare agnyanagnikṛtān svedān svedi bheṣajabhojanam" },
      { type: "verse", number: "91", sanskrit: "संसर्गबलयोगे च वातश्लेष्मनिबर्हणम् गर्भभूवेश्मशयनं कुथकम्बलरल्लकान्", text: "saṃsargabalayoge ca vātaśleṣmanibarhaṇam garbhabhūveśmaśayanaṃ kuthakambalarallakān" },
      { type: "verse", number: "92", sanskrit: "निर्धूमदीप्तैरङ्गारैर्हसन्तीश्च हसन्तिकाः मद्यं सत्र्यूषणं तक्रं कुलत्थव्रीहिकोद्रवान्", text: "nirdhūmadīptairaṅgārairhasantīśca hasantikāḥ madyaṃ satryūṣaṇaṃ takraṃ kulatthavrīhikodravān" },
      { type: "verse", number: "93", sanskrit: "संशीलयेद्वेपथुमान् यच्चान्यदपि पित्तलम् अजाज्याः सगुडं कल्कं सगुडं वामृतारसम्", text: "saṃśīlayedvepathumān yaccānyadapi pittalam ajājyāḥ saguḍaṃ kalkaṃ saguḍaṃ vāmṛtārasam" },
      { type: "verse", number: "94", sanskrit: "रसं वार्ताकफलजं पिबेद्वा मधुसंयुतम् मधुकागरुकौन्तीनां कल्को व्याघ्रनखस्य च", text: "rasaṃ vārtākaphalajaṃ pibedvā madhusaṃyutam madhukāgarukauntīnāṃ kalko vyāghranakhasya ca" },
      { type: "verse", number: "95", sanskrit: "मद्येन पीतः सक्षौद्रस्तीव्रशीतज्वरापहः दयिताः स्तनशालिन्यः पीना विभ्रमभूषणाः", text: "madyena pītaḥ sakṣaudrastīvraśītajvarāpahaḥ dayitāḥ stanaśālinyaḥ pīnā vibhramabhūṣaṇāḥ" },
      { type: "verse", number: "96", sanskrit: "यौवनासवमत्ताश्च तमालिङ्गेयुरङ्गनाः वीतशीतं च विज्ञाय तास्ततो ऽपनयेत् पुनः", text: "yauvanāsavamattāśca tamāliṅgeyuraṅganāḥ vītaśītaṃ ca vijñāya tāstato 'panayet punaḥ" },
      { type: "verse", number: "97", sanskrit: "आनाहे कालवित् कुर्यात् क्रियामलसकोदिताम् पिप्पलीपिप्पलीमूलयवानीचित्रसाधिताम्", text: "ānāhe kālavit kuryāt kriyāmalasakoditām pippalīpippalīmūlayavānīcitrasādhitām" },
      { type: "verse", number: "98", sanskrit: "यवागूं पाययेच्चैनमनिलस्यानुलोमनीम् सोपद्रवो ऽपि चेदेवं ज्वरः शीतो न शाम्यति", text: "yavāgūṃ pāyayeccainamanilasyānulomanīm sopadravo 'pi cedevaṃ jvaraḥ śīto na śāmyati" },
      { type: "verse", number: "99", sanskrit: "अत्युदीर्णे ऽनिलकफे स्वस्थाने पित्तधाम्नि वा तक्रानुपानं त्रपुसं भक्षयित्वानलं भजेत्", text: "atyudīrṇe 'nilakaphe svasthāne pittadhāmni vā takrānupānaṃ trapusaṃ bhakṣayitvānalaṃ bhajet" },
      { type: "verse", number: "100", sanskrit: "आ स्स्वेदसम्भवात्तिष्ठेत् प्रावृतस्तद्वदातपे ततो विमृदितस्नातो युक्ताशी स्याद्गते ज्वरो", text: "ā ssvedasambhavāttiṣṭhet prāvṛtastadvadātape tato vimṛditasnāto yuktāśī syādgate jvaro" },
      { type: "verse", number: "101", sanskrit: "शमं तौ पित्तवृध्यैव प्रपद्येते स्वधाम च निवर्तते ततः शीघ्रं वातश्लेष्मोद्भवो ज्वरः", text: "śamaṃ tau pittavṛdhyaiva prapadyete svadhāma ca nivartate tataḥ śīghraṃ vātaśleṣmodbhavo jvaraḥ" },
      { type: "verse", number: "102", sanskrit: "स्वर्ज्जिकाकुष्ठमञ्जिष्ठालाक्षामूर्वानिशौषधैः सतक्रं साधितं तैलमभ्यङ्गाद्दाहशीतजित्", text: "svarjjikākuṣṭhamañjiṣṭhālākṣāmūrvāniśauṣadhaiḥ satakraṃ sādhitaṃ tailamabhyaṅgāddāhaśītajit" },
      { type: "verse", number: "103", sanskrit: "वमनैश्च विरेकैश्च बस्तिभिश्च यथाक्रमम् ज्वरानुपचरेद्धीमान् कफपित्तानिलोद्भवान्", text: "vamanaiśca virekaiśca bastibhiśca yathākramam jvarānupacareddhīmān kaphapittānilodbhavān" },
      { type: "verse", number: "104", sanskrit: "संसृष्टैः सन्निपतितैरेकानेकोल्बणैः समैः ज्वरान् दोषक्रमापेक्षी यथोक्तैरौषधैर्जयेत्", text: "saṃsṛṣṭaiḥ sannipatitairekānekolbaṇaiḥ samaiḥ jvarān doṣakramāpekṣī yathoktairauṣadhairjayet" },
      { type: "verse", number: "105", sanskrit: "वर्धनेनैकदोसस्य क्षपणेनोच्छ्रितस्य वा कफस्थानानुपूर्व्या वा सन्निपातज्वरं जयेत्", text: "vardhanenaikadosasya kṣapaṇenocchritasya vā kaphasthānānupūrvyā vā sannipātajvaraṃ jayet" },
      { type: "verse", number: "106", sanskrit: "निद्रानिवारणोपायः सन्यासाभिहितो हितः सन्निपाते विशेषेण दारुणो ऽयमुपद्रवः", text: "nidrānivāraṇopāyaḥ sanyāsābhihito hitaḥ sannipāte viśeṣeṇa dāruṇo 'yamupadravaḥ" },
      { type: "verse", number: "107", sanskrit: "सन्निपातज्वरस्यान्ते कर्णमूले सुदारुणः शोफः सञ्जायते तेन कश्चिदेव विमुच्यते", text: "sannipātajvarasyānte karṇamūle sudāruṇaḥ śophaḥ sañjāyate tena kaścideva vimucyate" },
      { type: "verse", number: "108", sanskrit: "रक्तावसेचनैः शीघ्रं सर्पिष्पानैश्च तं जयेत् प्रदेहैः कफपित्तघ्नैर्नावनैः कवलग्रहैः", text: "raktāvasecanaiḥ śīghraṃ sarpiṣpānaiśca taṃ jayet pradehaiḥ kaphapittaghnairnāvanaiḥ kavalagrahaiḥ" },
      { type: "verse", number: "109", sanskrit: "शीतोष्णस्निग्धरूक्षाद्यैर्ज्वरो यस्य न शाम्यति शाखानुसारी तस्याशु मुञ्चेद्बाह्वाःक्रमात्सिराम्", text: "śītoṣṇasnigdharūkṣādyairjvaro yasya na śāmyati śākhānusārī tasyāśu muñcedbāhvāḥkramātsirām" },
      { type: "verse", number: "110", sanskrit: "अयमेव विधिः कार्यो विषमे ऽपि यथायथम् ज्वरे विभज्य वातादीन्यश्चानन्तरमुच्यते", text: "ayameva vidhiḥ kāryo viṣame 'pi yathāyatham jvare vibhajya vātādīnyaścānantaramucyate" },
      { type: "verse", number: "111", sanskrit: "पटोलकटुकामुस्ताप्राणदामधुकैः कृताः त्रिचतुष्पञ्चशः क्वाथा विषमज्वरनाशनाः", text: "paṭolakaṭukāmustāprāṇadāmadhukaiḥ kṛtāḥ tricatuṣpañcaśaḥ kvāthā viṣamajvaranāśanāḥ" },
      { type: "verse", number: "112", sanskrit: "योजयेत्त्रिफलां पथ्या गुडूचीं पिप्पलीं पृथक् तैस्तैर्विधानैः सगुडं भल्लातकमथापि वा", text: "yojayettriphalāṃ pathyā guḍūcīṃ pippalīṃ pṛthak taistairvidhānaiḥ saguḍaṃ bhallātakamathāpi vā" },
      { type: "verse", number: "113", sanskrit: "लङ्घनं बृंहणं वापि ज्वरागमनवासरे प्रातः सतैलं लशुनं प्राग्भक्तं वा तथा घृतम्", text: "laṅghanaṃ bṛṃhaṇaṃ vāpi jvarāgamanavāsare prātaḥ satailaṃ laśunaṃ prāgbhaktaṃ vā tathā ghṛtam" },
      { type: "verse", number: "114", sanskrit: "जीर्णं तद्वद्दधि पयस्तक्रं सर्पिश्च षट्पलम् कल्याणकं पञ्चगव्यं तिक्ताख्यं वृषसाधितम्", text: "jīrṇaṃ tadvaddadhi payastakraṃ sarpiśca ṣaṭpalam kalyāṇakaṃ pañcagavyaṃ tiktākhyaṃ vṛṣasādhitam" },
      { type: "verse", number: "115", sanskrit: "पञ्चगव्यस्य महतो विधिना पञ्चमाहिषम् पञ्चाजं चतुरौष्ट्रं च सिद्धं सिद्धं घृतं तथा", text: "pañcagavyasya mahato vidhinā pañcamāhiṣam pañcājaṃ caturauṣṭraṃ ca siddhaṃ siddhaṃ ghṛtaṃ tathā" },
      { type: "verse", number: "116", sanskrit: "कटुरोहिणिमञ्जिष्ठावृषग्रन्थिकचित्रकैः पाठास्वगुप्ताद्विनिशैः पञ्चगव्यस्य पञ्चसु", text: "kaṭurohiṇimañjiṣṭhāvṛṣagranthikacitrakaiḥ pāṭhāsvaguptādviniśaiḥ pañcagavyasya pañcasu" },
      { type: "verse", number: "117", sanskrit: "प्रस्थेषु संयुतैः सेव्यं विषमज्वरजित् परम् वाक्स्वरस्मृतिमेधाग्निबलारोग्यवृषत्वकृत्", text: "prastheṣu saṃyutaiḥ sevyaṃ viṣamajvarajit param vāksvarasmṛtimedhāgnibalārogyavṛṣatvakṛt" },
      { type: "verse", number: "118", sanskrit: "कोलाग्निमन्थत्रिफलाक्वाथे दध्ना घृतं पचेत् तिल्वकावापमेतच्च विषमज्वरनाशनम्", text: "kolāgnimanthatriphalākvāthe dadhnā ghṛtaṃ pacet tilvakāvāpametacca viṣamajvaranāśanam" },
      { type: "verse", number: "119", sanskrit: "शृतक्षीरघृतक्षौद्रसिताकृष्णाः स्वजाहताः विषमज्वरहृद्रोगक्षतकासक्षयापहाः", text: "śṛtakṣīraghṛtakṣaudrasitākṛṣṇāḥ svajāhatāḥ viṣamajvarahṛdrogakṣatakāsakṣayāpahāḥ" },
      { type: "verse", number: "120", sanskrit: "सुरां तीक्ष्णं च यन्मद्य्ंअ शिखितित्तिरिदक्षजम् मांसं मेध्योष्णवीर्यं च सहान्नेन प्रकामतः", text: "surāṃ tīkṣṇaṃ ca yanmadyṃa śikhitittiridakṣajam māṃsaṃ medhyoṣṇavīryaṃ ca sahānnena prakāmataḥ" },
      { type: "verse", number: "121", sanskrit: "सेवित्वा तदहः स्वप्यादथवा पुनरुल्लिखेत् सर्पिषो महतीं मात्रां पीत्वा वा छर्दयेत् पुनः", text: "sevitvā tadahaḥ svapyādathavā punarullikhet sarpiṣo mahatīṃ mātrāṃ pītvā vā chardayet punaḥ" },
      { type: "verse", number: "122", sanskrit: "नीलिनीमजगन्धां च त्रिवृतां कटुरोहिणीम् पिबेज्ज्वरस्यागमने स्नेहस्वेदोपपादितः", text: "nīlinīmajagandhāṃ ca trivṛtāṃ kaṭurohiṇīm pibejjvarasyāgamane snehasvedopapāditaḥ" },
      { type: "verse", number: "123", sanskrit: "आस्थापनं वा तदहर्दद्यात्स्विन्नस्य यापनम् पयसा वृपदंशस्य शकृद्वा तदहः पिबेत्", text: "āsthāpanaṃ vā tadahardadyātsvinnasya yāpanam payasā vṛpadaṃśasya śakṛdvā tadahaḥ pibet" },
      { type: "verse", number: "124", sanskrit: "मस्तुना वा वृषशकृत् सुरया वाथ सैन्धवम् मनोह्वा सैन्धवं कृष्णा तैलेन नयनाञ्जनम्", text: "mastunā vā vṛṣaśakṛt surayā vātha saindhavam manohvā saindhavaṃ kṛṣṇā tailena nayanāñjanam" },
      { type: "verse", number: "125", sanskrit: "योज्या हिङ्गुसमा व्याघ्रीवसा नस्ये ससैन्धवा पुराणसर्पिः संहस्य वसा तद्वत् ससैन्धवा", text: "yojyā hiṅgusamā vyāghrīvasā nasye sasaindhavā purāṇasarpiḥ saṃhasya vasā tadvat sasaindhavā" },
      { type: "verse", number: "126", sanskrit: "पलङ्कषा निम्बपत्रं वचा कुष्ठं हरीतकी सर्षपाः सयवाः सर्पिर्धूपो विड्वा बिडालजा", text: "palaṅkaṣā nimbapatraṃ vacā kuṣṭhaṃ harītakī sarṣapāḥ sayavāḥ sarpirdhūpo viḍvā biḍālajā" },
      { type: "verse", number: "127", sanskrit: "पुरध्यामवचासर्जनिम्बार्कागरुदारुभिः धूपो ज्वरेषु सर्वेषु कार्यो ऽयमपराजितः", text: "puradhyāmavacāsarjanimbārkāgarudārubhiḥ dhūpo jvareṣu sarveṣu kāryo 'yamaparājitaḥ" },
      { type: "verse", number: "128", sanskrit: "सहदेवावचाभद्रानाकुलीभिःप्रयोजयेत् धूपनोद्वर्तनालेपान् सर्वज्वरनिबर्हणान्", text: "sahadevāvacābhadrānākulībhiḥprayojayet dhūpanodvartanālepān sarvajvaranibarhaṇān" },
      { type: "verse", number: "129", sanskrit: "धूमनस्याञ्जनोत्तासा ये चोक्ताश्चित्तवैकृते दवाश्रयं च भैषज्यं ज्वरान् सर्वानपोहति विशेषाद्विषमान् प्रायस्ते ह्यागन्त्वनुबन्धजाः", text: "dhūmanasyāñjanottāsā ye coktāścittavaikṛte davāśrayaṃ ca bhaiṣajyaṃ jvarān sarvānapohati viśeṣādviṣamān prāyaste hyāgantvanubandhajāḥ" },
      { type: "verse", number: "130", sanskrit: "यथास्वं च सिरां विध्येदशान्तौ विषमज्वरे", text: "yathāsvaṃ ca sirāṃ vidhyedaśāntau viṣamajvare" },
      { type: "verse", number: "131", sanskrit: "रससंस्थे तु सर्वस्मिन् कुर्याद्वमनलङ्घने सेकसंशमनालेपरक्तमोक्षानसृक्स्थिते", text: "rasasaṃsthe tu sarvasmin kuryādvamanalaṅghane sekasaṃśamanāleparaktamokṣānasṛksthite" },
      { type: "verse", number: "132", sanskrit: "तीक्ष्णान् विरेकान् मांसस्थे मेदोघ्नं मेदसि स्थिते अस्थिस्थे वातशमनमभ्यङ्गस्वेदमर्दनम् ज्वरे वातार्तिशमनं विशेषाद्बस्तिकर्म च", text: "tīkṣṇān virekān māṃsasthe medoghnaṃ medasi sthite asthisthe vātaśamanamabhyaṅgasvedamardanam jvare vātārtiśamanaṃ viśeṣādbastikarma ca" },
      { type: "verse", number: "133", sanskrit: "केवलानिलवीसर्पविस्फोटाभिहतज्वरे सर्पिष्पानहिमालेपसेकमांसरसाशनम्", text: "kevalānilavīsarpavisphoṭābhihatajvare sarpiṣpānahimālepasekamāṃsarasāśanam" },
      { type: "verse", number: "134", sanskrit: "कुर्याद्यथास्वमुक्तं च रक्तमोक्षादिसाधनम् ग्रहोत्थे भूतविद्योक्तं मणिमन्त्रादिसाधनम् औषधीगन्धजे पित्तशमनं विषजिद्रिषे", text: "kuryādyathāsvamuktaṃ ca raktamokṣādisādhanam grahotthe bhūtavidyoktaṃ maṇimantrādisādhanam auṣadhīgandhaje pittaśamanaṃ viṣajidriṣe" },
      { type: "verse", number: "135", sanskrit: "इष्टैरर्थैर्मनोज्ञैश्च यथादोसशमेन च हिताहितविवेकैश्च ज्वरं क्रोधादिजं जयेत्", text: "iṣṭairarthairmanojñaiśca yathādosaśamena ca hitāhitavivekaiśca jvaraṃ krodhādijaṃ jayet" },
      { type: "verse", number: "136", sanskrit: "क्रोधजो याति कामेन शान्तिं क्रोधेन कामजः भयशोकोद्भवौ ताभ्यां भीशोकाभ्यां तथेतरौ शापाथर्वणमन्त्रोत्थे विधिर्दैवव्यपाश्रयः", text: "krodhajo yāti kāmena śāntiṃ krodhena kāmajaḥ bhayaśokodbhavau tābhyāṃ bhīśokābhyāṃ tathetarau śāpātharvaṇamantrotthe vidhirdaivavyapāśrayaḥ" },
      { type: "verse", number: "137", sanskrit: "ते ज्वराः केवलाःपूर्व व्याप्यन्ते ऽनन्तरं मलैः तस्माद्दोषानुसारेण तेष्वाहारादि कल्पयेत् न हि ज्वरो ऽनुबध्नाति मारुताद्यैर्विनाकृतः", text: "te jvarāḥ kevalāḥpūrva vyāpyante 'nantaraṃ malaiḥ tasmāddoṣānusāreṇa teṣvāhārādi kalpayet na hi jvaro 'nubadhnāti mārutādyairvinākṛtaḥ" },
      { type: "verse", number: "138", sanskrit: "कथास्त्रिवर्गसंयुक्ता रुङ्निद्रादिविनोदिनीः शस्ता विचित्राः शृणुयान्न प्रेतव्याधिताश्रयाः", text: "kathāstrivargasaṃyuktā ruṅnidrādivinodinīḥ śastā vicitrāḥ śṛṇuyānna pretavyādhitāśrayāḥ" },
      { type: "verse", number: "139", sanskrit: "ज्वरकालस्मृतिं चास्य हारिभिर्विषयैर्हरेत् त्यजेदाबललाभाच्च व्यायामस्नानमैथुनम्", text: "jvarakālasmṛtiṃ cāsya hāribhirviṣayairharet tyajedābalalābhācca vyāyāmasnānamaithunam" },
      { type: "verse", number: "140", sanskrit: "गुर्वसात्म्यं विदाह्यन्नं यच्चान्यज्ज्वरकारणम् न विज्वरो ऽपि सहसा सर्वान्नीनो भवेत् तथा", text: "gurvasātmyaṃ vidāhyannaṃ yaccānyajjvarakāraṇam na vijvaro 'pi sahasā sarvānnīno bhavet tathā" },
      { type: "verse", number: "141", sanskrit: "सद्यः प्राणहरो यस्मात्तस्मात्तस्य विशेषतः तस्यां तस्यामवस्थायां कुर्यात्तत्तधिषग्जितम्", text: "sadyaḥ prāṇaharo yasmāttasmāttasya viśeṣataḥ tasyāṃ tasyāmavasthāyāṃ kuryāttattadhiṣagjitam" },
      { type: "verse", number: "142", sanskrit: "मनोभिरामा विषया वचनं ह्लादि दक्षिणम् करुणार्द्रं मनः शुद्धं सर्वज्वरनिषूदनम्", text: "manobhirāmā viṣayā vacanaṃ hlādi dakṣiṇam karuṇārdraṃ manaḥ śuddhaṃ sarvajvaraniṣūdanam" },
      { type: "verse", number: "143", sanskrit: "मातरं पितरं देवान् वैद्यान् विप्रान् हरं हरिम् पूजयेच्छीलयेद्दानदमसत्यदयार्जवान् धारयेच्च सदा मन्त्रमणिरत्नमहौषधीः", text: "mātaraṃ pitaraṃ devān vaidyān viprān haraṃ harim pūjayecchīlayeddānadamasatyadayārjavān dhārayecca sadā mantramaṇiratnamahauṣadhīḥ" },
      { type: "verse", number: "144", sanskrit: "आर्यावलोकितं पर्णशबरीमपराजिताम् प्रणमेदार्यतारां च सर्वज्वरनिवृत्तये", text: "āryāvalokitaṃ parṇaśabarīmaparājitām praṇamedāryatārāṃ ca sarvajvaranivṛttaye" },
      { type: "verse", number: "145", sanskrit: "जपंस्तथा गतोष्णीषं सर्वव्याधिचिकित्सितम् आगन्तुदोषसहजैः सर्वरोगैर्विमुच्यते", text: "japaṃstathā gatoṣṇīṣaṃ sarvavyādhicikitsitam āgantudoṣasahajaiḥ sarvarogairvimucyate" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 3,
    lang: "sa",
    content: [
      { type: "heading", heading: "Шоша чикитса — лечение туберкулёза" },
      { type: "text", text: "Глава 3 Чикитса стханы — лечебный раздел о лечение туберкулёза. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो रक्तपित्तचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto raktapittacikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "ऊर्ध्वगं बलिनो ऽवेगमेकदोषानुगं नवम् रक्तपित्तं सुखे काले साधयेन्निरुपद्रवम्", text: "ūrdhvagaṃ balino 'vegamekadoṣānugaṃ navam raktapittaṃ sukhe kāle sādhayennirupadravam" },
      { type: "verse", number: "3", sanskrit: "अधोगं यापयेद्रक्तं यच्च दोषद्वयानुगम् शान्तं शान्तं पुनः कुप्यन्मार्गान्मार्गान्तरञ्च यत्", text: "adhogaṃ yāpayedraktaṃ yacca doṣadvayānugam śāntaṃ śāntaṃ punaḥ kupyanmārgānmārgāntarañca yat" },
      { type: "verse", number: "4", sanskrit: "अतिप्रवृत्तं मन्दाग्नोस्त्रिदोषं द्विपथं त्यजेत् ज्ञात्वा निदानमयनं मलावनुबलौ बलम्", text: "atipravṛttaṃ mandāgnostridoṣaṃ dvipathaṃ tyajet jñātvā nidānamayanaṃ malāvanubalau balam" },
      { type: "verse", number: "5", sanskrit: "देशकालाद्यवस्थां च रक्तपित्ते प्रयोजयेत् लङ्घनं बृंहणं चादौ शोधनं शमनं तथा", text: "deśakālādyavasthāṃ ca raktapitte prayojayet laṅghanaṃ bṛṃhaṇaṃ cādau śodhanaṃ śamanaṃ tathā" },
      { type: "verse", number: "6", sanskrit: "सन्तर्पणोत्थं बलिनो बहुदोषस्य साधयेत् ऊर्ध्वभागं विरेकेण वमनेन त्वधोगतम् शमनैर्बृंहणैश्चान्यल्लङ्घ्यबृंह्यानवेक्ष्य च", text: "santarpaṇotthaṃ balino bahudoṣasya sādhayet ūrdhvabhāgaṃ virekeṇa vamanena tvadhogatam śamanairbṛṃhaṇaiścānyallaṅghyabṛṃhyānavekṣya ca" },
      { type: "verse", number: "7", sanskrit: "ऊर्ध्वं प्रवृत्ते शमनौ रसौ तिक्तकषायकौ उपवासश्च निःशुण्ठीषडङ्गोदकपायिनः", text: "ūrdhvaṃ pravṛtte śamanau rasau tiktakaṣāyakau upavāsaśca niḥśuṇṭhīṣaḍaṅgodakapāyinaḥ" },
      { type: "verse", number: "8", sanskrit: "अधोगे रक्तपित्ते तु बृंहणो मधुरो रसः ऊर्ध्वगे तर्पणं योज्यं पेया पूर्वमधोगते", text: "adhoge raktapitte tu bṛṃhaṇo madhuro rasaḥ ūrdhvage tarpaṇaṃ yojyaṃ peyā pūrvamadhogate" },
      { type: "verse", number: "9", sanskrit: "अश्नतो बलिनो ऽशुद्धं न धार्यं तद्धि रोगकृत् धारयेदन्यथा शीघ्रमग्निवच्छीघ्रकारि तत्", text: "aśnato balino 'śuddhaṃ na dhāryaṃ taddhi rogakṛt dhārayedanyathā śīghramagnivacchīghrakāri tat" },
      { type: "verse", number: "10", sanskrit: "त्रिवृतात्रिफलाधात्रीत्रायन्त्यारग्वधाभयाः गवाक्षीक्षुरसक्षीरद्राक्षाक्षौद्रसितोत्कटाः यथास्वं कल्पविहिता विरेकार्थं प्रयोजयेत्", text: "trivṛtātriphalādhātrītrāyantyāragvadhābhayāḥ gavākṣīkṣurasakṣīradrākṣākṣaudrasitotkaṭāḥ yathāsvaṃ kalpavihitā virekārthaṃ prayojayet" },
      { type: "verse", number: "11", sanskrit: "त्रिवृच्छ्यामाकषायेण कल्केन च सशर्करम् साधयेद्विधिवल्लेहं लिह्यात् पाणितलं ततः", text: "trivṛcchyāmākaṣāyeṇa kalkena ca saśarkaram sādhayedvidhivallehaṃ lihyāt pāṇitalaṃ tataḥ" },
      { type: "verse", number: "12", sanskrit: "त्रिफला त्रिवृता श्यामा पिप्पली शर्करा मधु मोदकः सन्निपातोर्ध्वरक्तपित्तज्वरापहः", text: "triphalā trivṛtā śyāmā pippalī śarkarā madhu modakaḥ sannipātordhvaraktapittajvarāpahaḥ" },
      { type: "verse", number: "13", sanskrit: "त्रिवृत्समसिता तद्वत् पिप्पलीपादसंयुता वमनं फलसंयुक्तं तर्पणं ससितामधु", text: "trivṛtsamasitā tadvat pippalīpādasaṃyutā vamanaṃ phalasaṃyuktaṃ tarpaṇaṃ sasitāmadhu" },
      { type: "verse", number: "14", sanskrit: "ससितं वा जलं क्षौद्रयुक्तं वा मधुकोदकम् फलेन्द्रयवगाङ्गेयीमधुकं वा समाक्षिकम्", text: "sasitaṃ vā jalaṃ kṣaudrayuktaṃ vā madhukodakam phalendrayavagāṅgeyīmadhukaṃ vā samākṣikam" },
      { type: "verse", number: "15", sanskrit: "क्षीरं वा रसमिक्षोर्वा शुद्धस्यानन्तरो विधिः यथास्वं मन्थपेयादिः प्रयोज्यो रक्षता बलम्", text: "kṣīraṃ vā rasamikṣorvā śuddhasyānantaro vidhiḥ yathāsvaṃ manthapeyādiḥ prayojyo rakṣatā balam" },
      { type: "verse", number: "16", sanskrit: "मन्थो ज्वरोक्तो द्राक्षादिः पित्तघ्नैर्वा फलः कृतः मधुखर्जूरमृद्वीकापरूषकसिताम्भसा", text: "mantho jvarokto drākṣādiḥ pittaghnairvā phalaḥ kṛtaḥ madhukharjūramṛdvīkāparūṣakasitāmbhasā" },
      { type: "verse", number: "17", sanskrit: "मन्थो वा पञ्चसारेण सघृतैर्लाजसक्तुभिः दाडिमामलकाम्लो वा मन्दाग्न्यम्लाभिलाषिणः", text: "mantho vā pañcasāreṇa saghṛtairlājasaktubhiḥ dāḍimāmalakāmlo vā mandāgnyamlābhilāṣiṇaḥ" },
      { type: "verse", number: "18", sanskrit: "कमलोत्पलकिञ्जल्कपृश्निपर्णीप्रियङ्गुकाः उशीरं शाबरं लोध्रं शृङ्गवेरं कुचन्दनम्", text: "kamalotpalakiñjalkapṛśniparṇīpriyaṅgukāḥ uśīraṃ śābaraṃ lodhraṃ śṛṅgaveraṃ kucandanam" },
      { type: "verse", number: "19", sanskrit: "ह्रीबेरं धातकीपुस्पं बिल्वमध्यं दुरालभा अर्धार्धैर्विहिताः पेया वक्ष्यन्ते पादयौगिकाः", text: "hrīberaṃ dhātakīpuspaṃ bilvamadhyaṃ durālabhā ardhārdhairvihitāḥ peyā vakṣyante pādayaugikāḥ" },
      { type: "verse", number: "20", sanskrit: "भूनिम्बसेव्यजलदाश्चन्दनाम्बुप्रियङ्गवः शालिपर्ण्या युता मुद्गाः पृश्निपर्ण्या मसूरकाः", text: "bhūnimbasevyajaladāścandanāmbupriyaṅgavaḥ śāliparṇyā yutā mudgāḥ pṛśniparṇyā masūrakāḥ" },
      { type: "verse", number: "21", sanskrit: "तुवर्यो वातिबलया बलया वा हरेणवः तत्कषाये हिताः पेया मांसपेयास्तथा रसाः", text: "tuvaryo vātibalayā balayā vā hareṇavaḥ tatkaṣāye hitāḥ peyā māṃsapeyāstathā rasāḥ" },
      { type: "verse", number: "22", sanskrit: "अनम्लाः किञ्चिदम्ला वा सघृतक्षौद्रशर्कराः शूकशिम्बीभवं धान्यं शाकं मांसं च शस्यते", text: "anamlāḥ kiñcidamlā vā saghṛtakṣaudraśarkarāḥ śūkaśimbībhavaṃ dhānyaṃ śākaṃ māṃsaṃ ca śasyate" },
      { type: "verse", number: "23", sanskrit: "अन्नस्वरूपविज्ञाने यदुक्तं लघु शीतलम् पूर्वोक्तमम्बु पानीयं पञ्चमूलेन वा शृतम्", text: "annasvarūpavijñāne yaduktaṃ laghu śītalam pūrvoktamambu pānīyaṃ pañcamūlena vā śṛtam" },
      { type: "verse", number: "24", sanskrit: "लघुना शृतशीतं वा मध्वम्भो वा फलाम्बु वा पद्मकाद्यञ्जनादिं च सारिवादिं च कल्पयेत्", text: "laghunā śṛtaśītaṃ vā madhvambho vā phalāmbu vā padmakādyañjanādiṃ ca sārivādiṃ ca kalpayet" },
      { type: "verse", number: "25", sanskrit: "अन्नपाने गणं तद्वद्दशकं दाहनाशनम् कफानुगे यूषशाकं मारुतानुगते रसः", text: "annapāne gaṇaṃ tadvaddaśakaṃ dāhanāśanam kaphānuge yūṣaśākaṃ mārutānugate rasaḥ" },
      { type: "verse", number: "26", sanskrit: "अभीरोरङ्कुरैर्लावाः सहमुद्गाः पटोलजैः मकुष्ठाधन्वयासोत्थैरस्रपित्ते परं मताः", text: "abhīroraṅkurairlāvāḥ sahamudgāḥ paṭolajaiḥ makuṣṭhādhanvayāsotthairasrapitte paraṃ matāḥ" },
      { type: "verse", number: "27", sanskrit: "शशः सवास्तुकः शस्तो विबन्धे तित्तिरिः पुनः उदुम्बरस्य निर्यूहे साधितो मारुते ऽधिके", text: "śaśaḥ savāstukaḥ śasto vibandhe tittiriḥ punaḥ udumbarasya niryūhe sādhito mārute 'dhike" },
      { type: "verse", number: "28", sanskrit: "प्लक्षस्य बर्हिणस्तद्वन्न्यग्रोधस्य च कुक्कुटः बिसोत्पलमृणालानां वर्तकक्रकरौ हितौ", text: "plakṣasya barhiṇastadvannyagrodhasya ca kukkuṭaḥ bisotpalamṛṇālānāṃ vartakakrakarau hitau" },
      { type: "verse", number: "29", sanskrit: "वर्तिकाम्भोजनालानामश्वत्थस्य कपिञ्जलः यत्किञ्चिद्रक्तपित्तस्य निदानं तच्च वर्जयेत्", text: "vartikāmbhojanālānāmaśvatthasya kapiñjalaḥ yatkiñcidraktapittasya nidānaṃ tacca varjayet" },
      { type: "verse", number: "30", sanskrit: "वासारसेन फलिनीमृल्लोध्राञ्जनमाक्षिकम् पित्तासृक् शमयेत् पीतं निर्यासो वाटरूषकात्", text: "vāsārasena phalinīmṛllodhrāñjanamākṣikam pittāsṛk śamayet pītaṃ niryāso vāṭarūṣakāt" },
      { type: "verse", number: "31", sanskrit: "शर्करामधुसंयुक्तः केवलो वा शृतो ऽपि वा वृषः सद्यो जयत्यस्रं स ह्यस्य परमौषधम्", text: "śarkarāmadhusaṃyuktaḥ kevalo vā śṛto 'pi vā vṛṣaḥ sadyo jayatyasraṃ sa hyasya paramauṣadham" },
      { type: "verse", number: "32", sanskrit: "वासारसेन भूनिम्बकटुकाशर्कराः पिबेत् तेनैव वा क्षौद्रयुतं पद्मकेसरपद्मकम्", text: "vāsārasena bhūnimbakaṭukāśarkarāḥ pibet tenaiva vā kṣaudrayutaṃ padmakesarapadmakam" },
      { type: "verse", number: "33", sanskrit: "सलोध्रनागकुसुमशाड्वलोत्पलवास्तुकम् लिह्याद्वा मधुसर्पिर्भ्यां गवाश्वशकृतो रसम्", text: "salodhranāgakusumaśāḍvalotpalavāstukam lihyādvā madhusarpirbhyāṃ gavāśvaśakṛto rasam" },
      { type: "verse", number: "34", sanskrit: "पथ्यारजन्यहिंस्रा वा पलाण्डुं तद्वदेव वा फलिनीलोध्रखदिरशाल्मकोविदारजम्", text: "pathyārajanyahiṃsrā vā palāṇḍuṃ tadvadeva vā phalinīlodhrakhadiraśālmakovidārajam" },
      { type: "verse", number: "35", sanskrit: "शिरीषशेलुककुभीसिन्दुवारातिमुक्तजम् पलाशयूथिकाशिग्रुमधूकासनजन्म च", text: "śirīṣaśelukakubhīsinduvārātimuktajam palāśayūthikāśigrumadhūkāsanajanma ca" },
      { type: "verse", number: "36", sanskrit: "मधुना चूर्णितं पुष्पमेकत्र पृथगेव वा पुष्पैरेभिर्विपक्वं च सक्षौद्रं माहिषं घृतम्", text: "madhunā cūrṇitaṃ puṣpamekatra pṛthageva vā puṣpairebhirvipakvaṃ ca sakṣaudraṃ māhiṣaṃ ghṛtam" },
      { type: "verse", number: "37", sanskrit: "लिह्यात् क्षौद्रेण पथ्यां वा किञ्जल्कं कमलस्य वा लाजाः शृङ्गाटकं मुस्तं खर्जूरं कृष्णमृत्तिकाम्", text: "lihyāt kṣaudreṇa pathyāṃ vā kiñjalkaṃ kamalasya vā lājāḥ śṛṅgāṭakaṃ mustaṃ kharjūraṃ kṛṣṇamṛttikām" },
      { type: "verse", number: "38", sanskrit: "क्षीरिवृक्षाङ्कुरान् द्राक्षां तवक्षीरीं सितोपलाम् गैरिकं मधुकं लोध्रं शङ्खं शम्बूकमञ्जनम्", text: "kṣīrivṛkṣāṅkurān drākṣāṃ tavakṣīrīṃ sitopalām gairikaṃ madhukaṃ lodhraṃ śaṅkhaṃ śambūkamañjanam" },
      { type: "verse", number: "39", sanskrit: "तण्डूलीयकमूलं वा बीजं वा वास्तुकोद्भवम् पटोलमालतीनिम्बचन्दनद्वयपद्मकम्", text: "taṇḍūlīyakamūlaṃ vā bījaṃ vā vāstukodbhavam paṭolamālatīnimbacandanadvayapadmakam" },
      { type: "verse", number: "40", sanskrit: "लोध्रो वृषस्तण्डुलीयः कृष्णा मृन्मदयन्तिका शतावरी गोपकन्याकाकोल्यौ मधुयष्टिका", text: "lodhro vṛṣastaṇḍulīyaḥ kṛṣṇā mṛnmadayantikā śatāvarī gopakanyākākolyau madhuyaṣṭikā" },
      { type: "verse", number: "41", sanskrit: "रक्तपित्तहराः क्वाथास्त्रयः समधुशर्कराः सक्षौद्रं ग्रथिते रक्ते लिह्यात् पारावताच्छकृत्", text: "raktapittaharāḥ kvāthāstrayaḥ samadhuśarkarāḥ sakṣaudraṃ grathite rakte lihyāt pārāvatācchakṛt" },
      { type: "verse", number: "42", sanskrit: "अतिनिस्रुतरक्तो वा क्षौद्रेण रुधिरं पिबेत् जाङ्गलं भक्षयेद्वाजं मासं पित्तयुतं यकृत्", text: "atinisrutarakto vā kṣaudreṇa rudhiraṃ pibet jāṅgalaṃ bhakṣayedvājaṃ māsaṃ pittayutaṃ yakṛt" },
      { type: "verse", number: "43", sanskrit: "लोध्रकालीयकोशीरफलिनीशङ्खगैरिकम् पटोलपत्रं दुस्पर्शा समङ्गा सारिवालता", text: "lodhrakālīyakośīraphalinīśaṅkhagairikam paṭolapatraṃ dusparśā samaṅgā sārivālatā" },
      { type: "verse", number: "44", sanskrit: "त्वग्जम्बुवेतसाश्वत्थहयाह्वोदुम्बरार्जुनात् किराततिक्तक्रमुकमुस्तकट्फलपद्मकम्", text: "tvagjambuvetasāśvatthahayāhvodumbarārjunāt kirātatiktakramukamustakaṭphalapadmakam" },
      { type: "verse", number: "45", sanskrit: "प्रपौण्डरीकद्द्रीबेरकमलोत्पलपर्पटम् चन्दनेन पृथग्युक्तं समस्तं वा सशर्करम्", text: "prapauṇḍarīkaddrīberakamalotpalaparpaṭam candanena pṛthagyuktaṃ samastaṃ vā saśarkaram" },
      { type: "verse", number: "46", sanskrit: "फाण्टीकृतं शृतं शीतं चूर्णं वा तण्डुलाम्भसा पीतमाशु जयत्यस्रं तृड्दाहतमकानपि", text: "phāṇṭīkṛtaṃ śṛtaṃ śītaṃ cūrṇaṃ vā taṇḍulāmbhasā pītamāśu jayatyasraṃ tṛḍdāhatamakānapi" },
      { type: "verse", number: "47", sanskrit: "चन्दनोशीरजलदलाजमुद्गकणायवैः बलाजले पर्युषितैः कषायो रक्तपित्तहा", text: "candanośīrajaladalājamudgakaṇāyavaiḥ balājale paryuṣitaiḥ kaṣāyo raktapittahā" },
      { type: "verse", number: "48", sanskrit: "प्रसादश्चन्दनाम्भोजसेव्यमृद्भृष्टलोष्टजः सुशीतः ससिताक्षौद्रः शोणितातिप्रवृत्तिजित्", text: "prasādaścandanāmbhojasevyamṛdbhṛṣṭaloṣṭajaḥ suśītaḥ sasitākṣaudraḥ śoṇitātipravṛttijit" },
      { type: "verse", number: "49", sanskrit: "तद्वदच्छः सितालोध्रमधुकोशीरचन्दनात् मृच्छ्यामासारिवामुस्ताधातकीयष्टिकान्वितात्", text: "tadvadacchaḥ sitālodhramadhukośīracandanāt mṛcchyāmāsārivāmustādhātakīyaṣṭikānvitāt" },
      { type: "verse", number: "50", sanskrit: "वैडूर्यमुक्तामृच्छङ्खगैरिकामलकोदकम् मधूदकं रसं चेक्षोः पिबेन् जयति शोणितम्", text: "vaiḍūryamuktāmṛcchaṅkhagairikāmalakodakam madhūdakaṃ rasaṃ cekṣoḥ piben jayati śoṇitam" },
      { type: "verse", number: "51", sanskrit: "आपोथ्य वा नवे कुम्भे प्लावयेदिक्षुगण्डिकाः स्थितं तत् गुप्तमाकाशे रात्रिं प्रातः स्रुतं जलम्", text: "āpothya vā nave kumbhe plāvayedikṣugaṇḍikāḥ sthitaṃ tat guptamākāśe rātriṃ prātaḥ srutaṃ jalam" },
      { type: "verse", number: "52", sanskrit: "मधुमद्विकचाम्भोजकृतोत्तंसं च तद्गुणम् त्रपुसीमूलकल्कं वा सक्षौद्रं तण्डुलाम्बुना", text: "madhumadvikacāmbhojakṛtottaṃsaṃ ca tadguṇam trapusīmūlakalkaṃ vā sakṣaudraṃ taṇḍulāmbunā" },
      { type: "verse", number: "53", sanskrit: "पिबेत् करञ्जबीजं वा तेनक्षौद्रसितायुतम् लोध्रचन्दनयष्ट्याह्वं तेन यष्ट्याह्वमेव वा", text: "pibet karañjabījaṃ vā tenakṣaudrasitāyutam lodhracandanayaṣṭyāhvaṃ tena yaṣṭyāhvameva vā" },
      { type: "verse", number: "54", sanskrit: "नीलोत्पलं सिता यष्टी मधुकं पद्मकेसरम् छिन्नोद्भवा च शीतो ऽयं कषायो रक्तपित्तजित्", text: "nīlotpalaṃ sitā yaṣṭī madhukaṃ padmakesaram chinnodbhavā ca śīto 'yaṃ kaṣāyo raktapittajit" },
      { type: "verse", number: "55", sanskrit: "ये च पित्तज्वरे प्रोक्ताः कषायास्तांश्च योजयेत् कषायैर्विविधैरेभिर्दोप्ते ऽग्नौ विजिते कफे", text: "ye ca pittajvare proktāḥ kaṣāyāstāṃśca yojayet kaṣāyairvividhairebhirdopte 'gnau vijite kaphe" },
      { type: "verse", number: "56", sanskrit: "रक्तपित्तं न चेच्छाम्येत्तत्र वातोल्बणे पयः युञ्ज्याज्छागं शृतं तद्वत् गव्यं पञ्चगुणे ऽम्भसि", text: "raktapittaṃ na cecchāmyettatra vātolbaṇe payaḥ yuñjyājchāgaṃ śṛtaṃ tadvat gavyaṃ pañcaguṇe 'mbhasi" },
      { type: "verse", number: "57", sanskrit: "पञ्चमूलेन लघुना शृतं वा ससितामधु जीवकर्षभकद्राक्षाबलागोक्षुरनागरैः", text: "pañcamūlena laghunā śṛtaṃ vā sasitāmadhu jīvakarṣabhakadrākṣābalāgokṣuranāgaraiḥ" },
      { type: "verse", number: "58", sanskrit: "पृथक् पृथक् शृतं शीतं सघृतं सितयाथवा क्षीरेण वमनीपुष्पं मधुकं मधुशर्कराम्", text: "pṛthak pṛthak śṛtaṃ śītaṃ saghṛtaṃ sitayāthavā kṣīreṇa vamanīpuṣpaṃ madhukaṃ madhuśarkarām" },
      { type: "verse", number: "59", sanskrit: "गोकण्टकाभीरुशृतं पर्णिनीभिस्तथा पयः हन्त्याशु रक्तं सरुजं विशेषान्मूत्रमार्गगम्", text: "gokaṇṭakābhīruśṛtaṃ parṇinībhistathā payaḥ hantyāśu raktaṃ sarujaṃ viśeṣānmūtramārgagam" },
      { type: "verse", number: "60", sanskrit: "विण्मार्गगे विशेषेण हितं मोचरसेन तु वटप्ररोहैः शुङ्गैर्वा शुण्ठ्युदीच्योत्पलैरपि", text: "viṇmārgage viśeṣeṇa hitaṃ mocarasena tu vaṭaprarohaiḥ śuṅgairvā śuṇṭhyudīcyotpalairapi" },
      { type: "verse", number: "61", sanskrit: "रक्तातिसारदुर्नामचिकित्सां चात्र कल्पयेत् पीत्वा कषायान् पयसा भुञ्जीत पयसैव तु कषाययोगैरेभिर्वा विपक्वं पाययेत् घृतम्", text: "raktātisāradurnāmacikitsāṃ cātra kalpayet pītvā kaṣāyān payasā bhuñjīta payasaiva tu kaṣāyayogairebhirvā vipakvaṃ pāyayet ghṛtam" },
      { type: "verse", number: "62", sanskrit: "समूलमस्तकं क्षुण्णं वृषमष्टगुणे ऽम्भसि पक्त्वाष्टांशावशेषेण घृतं तेन विपाचयेत्", text: "samūlamastakaṃ kṣuṇṇaṃ vṛṣamaṣṭaguṇe 'mbhasi paktvāṣṭāṃśāvaśeṣeṇa ghṛtaṃ tena vipācayet" },
      { type: "verse", number: "63", sanskrit: "तत्पुष्पगर्भं तच्छीतं सक्षौद्रं पित्तशोणितम् पित्तगुल्मज्वरश्वासकासहृद्रोगकामलाः", text: "tatpuṣpagarbhaṃ tacchītaṃ sakṣaudraṃ pittaśoṇitam pittagulmajvaraśvāsakāsahṛdrogakāmalāḥ" },
      { type: "verse", number: "64", sanskrit: "तिमिरभ्रमवीसर्पस्वरसादांश्च नाशयेत् पलाशवृन्तस्वरसे तद्गर्भं च घृतं पचेत्", text: "timirabhramavīsarpasvarasādāṃśca nāśayet palāśavṛntasvarase tadgarbhaṃ ca ghṛtaṃ pacet" },
      { type: "verse", number: "65", sanskrit: "सक्षौद्रं तच्च रक्तघ्नं तद्वद्वत्सकसाधितम् लोध्रोत्पलसमङ्गाभिस्तथैव त्रायमाणया", text: "sakṣaudraṃ tacca raktaghnaṃ tadvadvatsakasādhitam lodhrotpalasamaṅgābhistathaiva trāyamāṇayā" },
      { type: "verse", number: "66", sanskrit: "लाजगोधूममधुकसिताचूर्णं पयोद्रवम् घृतेनोत्करिकां कृत्वा खादेत् पित्तास्रवारिणीम्", text: "lājagodhūmamadhukasitācūrṇaṃ payodravam ghṛtenotkarikāṃ kṛtvā khādet pittāsravāriṇīm" },
      { type: "verse", number: "67", sanskrit: "रक्ते सपिच्छे सकफे ग्राथिते कण्ठमार्गगे लिह्यान्माक्षिकसर्पिर्भ्यां क्षारमुत्पलनालजम्", text: "rakte sapicche sakaphe grāthite kaṇṭhamārgage lihyānmākṣikasarpirbhyāṃ kṣāramutpalanālajam" },
      { type: "verse", number: "68", sanskrit: "मृणालाम्भोजकिञ्जम्ल्कश्यामासनमधूकजम् तद्वत् पृथक् पृथक् क्षारं घृतं क्षीरेण साधयेत्", text: "mṛṇālāmbhojakiñjamlkaśyāmāsanamadhūkajam tadvat pṛthak pṛthak kṣāraṃ ghṛtaṃ kṣīreṇa sādhayet" },
      { type: "verse", number: "69", sanskrit: "पिष्टैरभीरुकाकोलीमेदावृक्षाम्लदाडिमैः फलपूरकमूलेन विदार्या मधुकेन च", text: "piṣṭairabhīrukākolīmedāvṛkṣāmladāḍimaiḥ phalapūrakamūlena vidāryā madhukena ca" },
      { type: "verse", number: "70", sanskrit: "तद्विबन्धज्वरानाहशूलकासास्रपित्तजित् पञ्चभिः पञ्चमूलैश्च सिद्धमाद्यैस्तदर्थकृत्", text: "tadvibandhajvarānāhaśūlakāsāsrapittajit pañcabhiḥ pañcamūlaiśca siddhamādyaistadarthakṛt" },
      { type: "verse", number: "71", sanskrit: "गुदागमे विशेषेण शोणिते बस्तिरिष्यते मधुकाञ्जनमाञ्जिष्ठामृणालोत्पलगैरिकैः", text: "gudāgame viśeṣeṇa śoṇite bastiriṣyate madhukāñjanamāñjiṣṭhāmṛṇālotpalagairikaiḥ" },
      { type: "verse", number: "72", sanskrit: "सुवर्णलोध्रकालीयसमङ्गाम्बुजचन्दनैः सौगन्धिकसिताशङ्खैः पिष्टैर्मधुघृतान्वितैः", text: "suvarṇalodhrakālīyasamaṅgāmbujacandanaiḥ saugandhikasitāśaṅkhaiḥ piṣṭairmadhughṛtānvitaiḥ" },
      { type: "verse", number: "73", sanskrit: "क्षीरेणास्थापयेदेनं स्नातं च शिशिराम्भसा क्षीरेणैवाशयेच्छालीस्ततो मधुकसर्पिषा", text: "kṣīreṇāsthāpayedenaṃ snātaṃ ca śiśirāmbhasā kṣīreṇaivāśayecchālīstato madhukasarpiṣā" },
      { type: "verse", number: "74", sanskrit: "काले ऽनुवासयेदेवमतिसारे ऽपि दुस्तरे जीर्णे ऽसृक्प्रबले कुर्याद्विरेके चातियोगिनि", text: "kāle 'nuvāsayedevamatisāre 'pi dustare jīrṇe 'sṛkprabale kuryādvireke cātiyogini" },
      { type: "verse", number: "75", sanskrit: "विदार्यादिगणेनेष्टं शृतं वास्थापने पयः सक्षौद्रशर्करासर्पिः सर्पिश्चैवानुवासने", text: "vidāryādigaṇeneṣṭaṃ śṛtaṃ vāsthāpane payaḥ sakṣaudraśarkarāsarpiḥ sarpiścaivānuvāsane" },
      { type: "verse", number: "76", sanskrit: "मूत्राशयस्थं शमयेद्रक्तमुत्तरबस्तिभिः ईदृशैरेव तद्वच्च प्रदरे ऽपि विधिः स्मृतः", text: "mūtrāśayasthaṃ śamayedraktamuttarabastibhiḥ īdṛśaireva tadvacca pradare 'pi vidhiḥ smṛtaḥ" },
      { type: "verse", number: "77", sanskrit: "छेदभेदादिभिश्चातिप्रवृत्ते शुद्धशोणिते विशेषात् प्रदरस्योक्तं योनिरोगेषु चैषधम्", text: "chedabhedādibhiścātipravṛtte śuddhaśoṇite viśeṣāt pradarasyoktaṃ yonirogeṣu caiṣadham" },
      { type: "verse", number: "78", sanskrit: "घ्राणगे रुधिरे शुद्धे नावनं चानुषेचयेत् कषाययोगान् पूर्वेक्तान् क्षीरेक्ष्वादिरसाप्लुतान्", text: "ghrāṇage rudhire śuddhe nāvanaṃ cānuṣecayet kaṣāyayogān pūrvektān kṣīrekṣvādirasāplutān" },
      { type: "verse", number: "79", sanskrit: "क्षीरादीन् ससितं तोयं केवलं वा हितं जलम् रसो दाडिमपुष्पाणामाम्रास्थ्नः शाड्वलस्य च", text: "kṣīrādīn sasitaṃ toyaṃ kevalaṃ vā hitaṃ jalam raso dāḍimapuṣpāṇāmāmrāsthnaḥ śāḍvalasya ca" },
      { type: "verse", number: "80", sanskrit: "कल्पयेच्छीतवर्गं च प्रदेहाभ्यञ्जनादिषु यच्च पित्तज्वरे प्रोक्तं बहिरन्तश्च भेषजम् रक्तपित्ते हितं तच्च क्षतक्षीणे हितं च यत्", text: "kalpayecchītavargaṃ ca pradehābhyañjanādiṣu yacca pittajvare proktaṃ bahirantaśca bheṣajam raktapitte hitaṃ tacca kṣatakṣīṇe hitaṃ ca yat" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 4,
    lang: "sa",
    content: [
      { type: "heading", heading: "Гулма чикитса — лечение абдоминальных масс" },
      { type: "text", text: "Глава 4 Чикитса стханы — лечебный раздел о лечение абдоминальных масс. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातः कासचिकित्सितं व्याख्यास्यामः इति हस्माहुरात्रेयादयो महर्षयः", text: "athātaḥ kāsacikitsitaṃ vyākhyāsyāmaḥ iti hasmāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "केवलानिलजं कासं स्नेहैरादावुपाचरेत् वातघ्नसिद्धैः स्निग्धैश्च पेयायूषरसादिभिः", text: "kevalānilajaṃ kāsaṃ snehairādāvupācaret vātaghnasiddhaiḥ snigdhaiśca peyāyūṣarasādibhiḥ" },
      { type: "verse", number: "3", sanskrit: "लेहैर्धूमैस्ततहाभ्यङ्गस्वेदसेकावगाहनैः बस्तिभिर्बद्धविड्वातं सपित्तं त्वौर्ध्वभक्तिकैः", text: "lehairdhūmaistatahābhyaṅgasvedasekāvagāhanaiḥ bastibhirbaddhaviḍvātaṃ sapittaṃ tvaurdhvabhaktikaiḥ" },
      { type: "verse", number: "4", sanskrit: "गुडूचीकण्टकारीभ्यां पृथक् त्रिंशत्पलाद्रसे प्रस्थः सिद्धो घृताद्वातकासनुद्वह्निदीपनः", text: "guḍūcīkaṇṭakārībhyāṃ pṛthak triṃśatpalādrase prasthaḥ siddho ghṛtādvātakāsanudvahnidīpanaḥ" },
      { type: "verse", number: "5", sanskrit: "क्षाररास्नावचाहिङ्गुपाठायष्ट्याह्वधान्यकैः द्विशाणैः सर्पिषः प्रस्थं पञ्चकोलयुतैः पचेत्", text: "kṣārarāsnāvacāhiṅgupāṭhāyaṣṭyāhvadhānyakaiḥ dviśāṇaiḥ sarpiṣaḥ prasthaṃ pañcakolayutaiḥ pacet" },
      { type: "verse", number: "6", sanskrit: "दशमूलस्य निर्यूहे पीतं मण्डानुपायिना सकासश्वासहृत्पार्श्वग्रहणीरोगगुल्मनुत्", text: "daśamūlasya niryūhe pītaṃ maṇḍānupāyinā sakāsaśvāsahṛtpārśvagrahaṇīrogagulmanut" },
      { type: "verse", number: "7", sanskrit: "काश्मर्यत्रिफलाव्योषशठीद्राक्षापरूषकम् द्वे पाठे देवदार्वृद्धिस्वगुप्ताग्निकगोक्षुरम्", text: "kāśmaryatriphalāvyoṣaśaṭhīdrākṣāparūṣakam dve pāṭhe devadārvṛddhisvaguptāgnikagokṣuram" },
      { type: "verse", number: "8", sanskrit: "व्याघ्नीतामलकीमेदाकाकनासाशतावरीः विदारी च घृतप्रस्थः कर्षांशैस्तैर्विपाचितः", text: "vyāghnītāmalakīmedākākanāsāśatāvarīḥ vidārī ca ghṛtaprasthaḥ karṣāṃśaistairvipācitaḥ" },
      { type: "verse", number: "9", sanskrit: "क्षीरेण च जयत्याशु ज्वरकासहलीमकान् गुल्मारुचियकृत्प्लीहशिरोहृत्पार्श्ववेदनाः", text: "kṣīreṇa ca jayatyāśu jvarakāsahalīmakān gulmāruciyakṛtplīhaśirohṛtpārśvavedanāḥ" },
      { type: "verse", number: "10", sanskrit: "कामलार्शोनिलाष्ठीलाक्षतशोफक्षयांश्च सः द्रोणे ऽपां साधयेद्रास्नादशमूलशतावरीः पलोन्मिता द्विकुडवं कुलत्थं बदरं यवम्", text: "kāmalārśonilāṣṭhīlākṣataśophakṣayāṃśca saḥ droṇe 'pāṃ sādhayedrāsnādaśamūlaśatāvarīḥ palonmitā dvikuḍavaṃ kulatthaṃ badaraṃ yavam" },
      { type: "verse", number: "11", sanskrit: "तुलार्धं चाजमांसस्य तेन साध्यं घृताढकम् समक्षीरं पलांशैश्च जीवनीयैः समीक्ष्य तत्", text: "tulārdhaṃ cājamāṃsasya tena sādhyaṃ ghṛtāḍhakam samakṣīraṃ palāṃśaiśca jīvanīyaiḥ samīkṣya tat" },
      { type: "verse", number: "12", sanskrit: "प्रयुक्तं वातरोगेषु पाननावनबस्तिभिः पञ्चकासान् शिरःकम्पं योनिवङ्क्षणवेदनाम् सर्वाङ्गैकाङ्गरोगांश्च सप्लीहोर्ध्वानिलान् जयेत्", text: "prayuktaṃ vātarogeṣu pānanāvanabastibhiḥ pañcakāsān śiraḥkampaṃ yonivaṅkṣaṇavedanām sarvāṅgaikāṅgarogāṃśca saplīhordhvānilān jayet" },
      { type: "verse", number: "13", sanskrit: "विदार्यादिगणक्वाथकल्कसिद्धं च कासजित् अशोकबीजक्षवकजन्तुघ्नाञ्जनपद्मकैः", text: "vidāryādigaṇakvāthakalkasiddhaṃ ca kāsajit aśokabījakṣavakajantughnāñjanapadmakaiḥ" },
      { type: "verse", number: "14", sanskrit: "सबिडैश्च घृतं सिद्धं तच्चूर्णं वा घृताप्लुतम् लिह्यात् पयश्चानुपिबेदाजं कासाभिपीडितः", text: "sabiḍaiśca ghṛtaṃ siddhaṃ taccūrṇaṃ vā ghṛtāplutam lihyāt payaścānupibedājaṃ kāsābhipīḍitaḥ" },
      { type: "verse", number: "15", sanskrit: "विडङ्गं नागरं रास्नां पिप्पली हिङ्गु सैन्धवम् भाङ्गर्क्षीरश्च तच्चूर्णं पिबेद्वा घृतमात्रया सकफे ऽनिलजे कासे श्वासहिध्माहताग्निषु", text: "viḍaṅgaṃ nāgaraṃ rāsnāṃ pippalī hiṅgu saindhavam bhāṅgarkṣīraśca taccūrṇaṃ pibedvā ghṛtamātrayā sakaphe 'nilaje kāse śvāsahidhmāhatāgniṣu" },
      { type: "verse", number: "16", sanskrit: "दुरालभां शृङ्गवेरं शठीं रास्नां सितोपलाम् लिह्यात् कर्कटशृङ्गीं च कासे तैलेन वातजे", text: "durālabhāṃ śṛṅgaveraṃ śaṭhīṃ rāsnāṃ sitopalām lihyāt karkaṭaśṛṅgīṃ ca kāse tailena vātaje" },
      { type: "verse", number: "17", sanskrit: "दुस्पर्शां पिप्पलीं मुस्तं भार्ङ्गीं कर्कटकीं शठीम् पुराणगुडतैलाभ्यां चूर्णितान्यवलेहयेत्", text: "dusparśāṃ pippalīṃ mustaṃ bhārṅgīṃ karkaṭakīṃ śaṭhīm purāṇaguḍatailābhyāṃ cūrṇitānyavalehayet" },
      { type: "verse", number: "18", sanskrit: "तद्वत् सकृष्णां शुण्ठीं च सभार्ङ्गीं तद्वदेव च पिबेत् कृष्णां च कोष्णेन सलिलेन ससैन्धवाम्", text: "tadvat sakṛṣṇāṃ śuṇṭhīṃ ca sabhārṅgīṃ tadvadeva ca pibet kṛṣṇāṃ ca koṣṇena salilena sasaindhavām" },
      { type: "verse", number: "19", sanskrit: "मुस्तुना ससितां शुण्ठीं दध्ना वा कणरेणुकाः पिबेत् बदरमज्ञो वा मदिरादधिमस्तुभिः अथवा पिप्पलीकल्कं घृतभृष्टं ससैन्धवम्", text: "mustunā sasitāṃ śuṇṭhīṃ dadhnā vā kaṇareṇukāḥ pibet badaramajño vā madirādadhimastubhiḥ athavā pippalīkalkaṃ ghṛtabhṛṣṭaṃ sasaindhavam" },
      { type: "verse", number: "20", sanskrit: "कासी सपीनसो धूमं स्नैहिकं विधिना पिबेत् हिध्माश्वासोक्तधूमांश्च क्षीरमांसरसाशनः", text: "kāsī sapīnaso dhūmaṃ snaihikaṃ vidhinā pibet hidhmāśvāsoktadhūmāṃśca kṣīramāṃsarasāśanaḥ" },
      { type: "verse", number: "21", sanskrit: "ग्राम्यानूपौदकैः शालियवगोधूमषष्टिकान् रसैर्माषात्मगुप्तानां यूषैर्वा भोजयेद्धितान्", text: "grāmyānūpaudakaiḥ śāliyavagodhūmaṣaṣṭikān rasairmāṣātmaguptānāṃ yūṣairvā bhojayeddhitān" },
      { type: "verse", number: "22", sanskrit: "यवानीपिप्पलीबिल्वमध्यनागरचित्रकैः रास्नाजाजीपृथक्पर्णीपलाशशाठिपौष्करैः", text: "yavānīpippalībilvamadhyanāgaracitrakaiḥ rāsnājājīpṛthakparṇīpalāśaśāṭhipauṣkaraiḥ" },
      { type: "verse", number: "23", sanskrit: "सिद्धां स्निग्धाम्ललवणां पेयामनिलजे पिबेत् कटीहृत्पार्श्वकोष्ठार्तिश्वासहिध्माप्रणाशिनीम्", text: "siddhāṃ snigdhāmlalavaṇāṃ peyāmanilaje pibet kaṭīhṛtpārśvakoṣṭhārtiśvāsahidhmāpraṇāśinīm" },
      { type: "verse", number: "24", sanskrit: "दशमूलरसे तद्वत् पञ्चकोलगुडान्विताम् पिबेत् समतिलां पेयां क्षैरेयीं वा ससैन्धवाम् मात्स्यकौक्कुटवाराहैर्मांसैर्वा साज्यसैन्धवाम्", text: "daśamūlarase tadvat pañcakolaguḍānvitām pibet samatilāṃ peyāṃ kṣaireyīṃ vā sasaindhavām mātsyakaukkuṭavārāhairmāṃsairvā sājyasaindhavām" },
      { type: "verse", number: "25", sanskrit: "वास्तुको वायसीशाकं कासघ्नः सुनिषण्णकः कण्टकार्याः फलं पत्रं बालं शुष्कं च मूलकम्", text: "vāstuko vāyasīśākaṃ kāsaghnaḥ suniṣaṇṇakaḥ kaṇṭakāryāḥ phalaṃ patraṃ bālaṃ śuṣkaṃ ca mūlakam" },
      { type: "verse", number: "26", sanskrit: "स्नेहास्तैलादयो भक्ष्याः क्षीरेक्षुरसगौडिकाः दधिमस्त्वारनालाम्लफलाम्बुमदिराः पिबेत्", text: "snehāstailādayo bhakṣyāḥ kṣīrekṣurasagauḍikāḥ dadhimastvāranālāmlaphalāmbumadirāḥ pibet" },
      { type: "verse", number: "27", sanskrit: "पित्तकासे तु सकफे वमनं सर्पिषा हितम् तथा मदनकाश्मर्यमधुकक्वथितैर्जलैः फलयष्ट्याह्वकल्कैर्वा विदारीक्षुरसाप्लुतैः", text: "pittakāse tu sakaphe vamanaṃ sarpiṣā hitam tathā madanakāśmaryamadhukakvathitairjalaiḥ phalayaṣṭyāhvakalkairvā vidārīkṣurasāplutaiḥ" },
      { type: "verse", number: "28", sanskrit: "पित्तकासे तनुकफे त्रिवृतां मधुरैर्युताम् युञ्ज्याद्विरेकाय युतां घनश्लेष्मणि तिक्तकैः", text: "pittakāse tanukaphe trivṛtāṃ madhurairyutām yuñjyādvirekāya yutāṃ ghanaśleṣmaṇi tiktakaiḥ" },
      { type: "verse", number: "29", sanskrit: "हृतदोषो हिमं स्निग्धं स्वादु संसर्जनं भजेत् घने कफे तु शिशिरं रूक्षं तिक्तोपसंहितम्", text: "hṛtadoṣo himaṃ snigdhaṃ svādu saṃsarjanaṃ bhajet ghane kaphe tu śiśiraṃ rūkṣaṃ tiktopasaṃhitam" },
      { type: "verse", number: "30", sanskrit: "पिप्पलीमुस्तयष्ट्याह्वद्राक्षामूर्वामहौषधम् लाकामृताफलद्राक्षात्वक्क्षीरीपिप्पलीसिताः", text: "pippalīmustayaṣṭyāhvadrākṣāmūrvāmahauṣadham lākāmṛtāphaladrākṣātvakkṣīrīpippalīsitāḥ" },
      { type: "verse", number: "31", sanskrit: "दुस्पर्शाकर्कटीशुण्ठीशठीद्राक्षासिताबलाः निदिग्धिकामूलफलं वटबीजं रसाञ्जनम्", text: "dusparśākarkaṭīśuṇṭhīśaṭhīdrākṣāsitābalāḥ nidigdhikāmūlaphalaṃ vaṭabījaṃ rasāñjanam" },
      { type: "verse", number: "32", sanskrit: "खर्जूरं पिप्पली वांशी श्वदंष्ट्रा चेति पञ्च ते घृतक्षौद्रयुता लेहाः श्लोकार्धैः पित्तकासिनाम् पयो ऽनुपानां शृङ्गीं वा लिह्यात्साज्यसितामधु", text: "kharjūraṃ pippalī vāṃśī śvadaṃṣṭrā ceti pañca te ghṛtakṣaudrayutā lehāḥ ślokārdhaiḥ pittakāsinām payo 'nupānāṃ śṛṅgīṃ vā lihyātsājyasitāmadhu" },
      { type: "verse", number: "33", sanskrit: "लेहः पैत्ते सिताधात्रीक्षौद्रद्राक्षाहिमोत्पलैः सकफे साब्दमरिचः सघृतः सानिले हितः", text: "lehaḥ paitte sitādhātrīkṣaudradrākṣāhimotpalaiḥ sakaphe sābdamaricaḥ saghṛtaḥ sānile hitaḥ" },
      { type: "verse", number: "34", sanskrit: "मृद्वीकार्धशतं त्रिंशत् पिप्पलीः शर्करापलम् लेहयेन्मधुना गोर्वा क्षीरपस्य शकृद्रसम्", text: "mṛdvīkārdhaśataṃ triṃśat pippalīḥ śarkarāpalam lehayenmadhunā gorvā kṣīrapasya śakṛdrasam" },
      { type: "verse", number: "35", sanskrit: "त्वगेलाव्योषमृद्वीकापिप्पलीमूलपौष्करैः लाजमुस्तशठीरास्नाधात्रीफलबिभीतकैः शर्कराक्षौद्रसर्पिर्भिर्लेहो हृद्रोगकासहा", text: "tvagelāvyoṣamṛdvīkāpippalīmūlapauṣkaraiḥ lājamustaśaṭhīrāsnādhātrīphalabibhītakaiḥ śarkarākṣaudrasarpirbhirleho hṛdrogakāsahā" },
      { type: "verse", number: "36", sanskrit: "पिप्पल्यामलकद्राक्षालाजलाक्षासितोपलाः सञ्चूर्ण्य पक्त्वा पयसा लिह्यात् क्षौद्राष्टभागिकाः", text: "pippalyāmalakadrākṣālājalākṣāsitopalāḥ sañcūrṇya paktvā payasā lihyāt kṣaudrāṣṭabhāgikāḥ" },
      { type: "verse", number: "37", sanskrit: "विदारीक्षुमृणालानां रसान् क्षीरं सितोपलाम् पिबेत् क्षौद्रेण संयोज्य पित्तकासमपोहति", text: "vidārīkṣumṛṇālānāṃ rasān kṣīraṃ sitopalām pibet kṣaudreṇa saṃyojya pittakāsamapohati" },
      { type: "verse", number: "38", sanskrit: "मधुरैर्जाङ्गलरसैर्यवश्यामाककोद्रवाः मुद्गादियूषैः शाकैश्च तिक्तकैर्मात्रया हिताः", text: "madhurairjāṅgalarasairyavaśyāmākakodravāḥ mudgādiyūṣaiḥ śākaiśca tiktakairmātrayā hitāḥ" },
      { type: "verse", number: "39", sanskrit: "घनश्लेष्मणि लेहाश्च तिक्तका मधुसंयुताः शालयः स्युस्तनुकफे षष्टिकाश्च रसादिभिः शर्कराम्भो ऽनुपानार्थं द्राक्षेक्षुस्वरसः पयः", text: "ghanaśleṣmaṇi lehāśca tiktakā madhusaṃyutāḥ śālayaḥ syustanukaphe ṣaṣṭikāśca rasādibhiḥ śarkarāmbho 'nupānārthaṃ drākṣekṣusvarasaḥ payaḥ" },
      { type: "verse", number: "40", sanskrit: "काकोलीबृहतीमेदाद्वयैः सवृषनागरैः पित्तकासे रसक्षीरपेयायूषान् प्रकल्पयेत्", text: "kākolībṛhatīmedādvayaiḥ savṛṣanāgaraiḥ pittakāse rasakṣīrapeyāyūṣān prakalpayet" },
      { type: "verse", number: "41", sanskrit: "द्राक्षां कणां पञ्चमूलं तृणाख्यं च पचेज्जले तेन क्षीरं शृतं शीतं पिबेत् समधुशर्करम्", text: "drākṣāṃ kaṇāṃ pañcamūlaṃ tṛṇākhyaṃ ca pacejjale tena kṣīraṃ śṛtaṃ śītaṃ pibet samadhuśarkaram" },
      { type: "verse", number: "42", sanskrit: "साधितां तेन पेयां वा सुशीतां मधुनान्विताम् शठीद्द्रीबेरबृहतीशर्कराविश्वभेषजम् पिष्ट्वा रसं पिबेत् पूतं वस्त्रेण घृतमूर्छितम्", text: "sādhitāṃ tena peyāṃ vā suśītāṃ madhunānvitām śaṭhīddrīberabṛhatīśarkarāviśvabheṣajam piṣṭvā rasaṃ pibet pūtaṃ vastreṇa ghṛtamūrchitam" },
      { type: "verse", number: "43", sanskrit: "महिष्यजावीगोक्षीरधात्रीफलरसैः समैः सर्पिः सिद्धं पिबेत् तद्वन्मधुरेण गणेन वा", text: "mahiṣyajāvīgokṣīradhātrīphalarasaiḥ samaiḥ sarpiḥ siddhaṃ pibet tadvanmadhureṇa gaṇena vā" },
      { type: "verse", number: "44", sanskrit: "क्वाथीकृतेनेक्षुरसे क्षीरयुक्तेन साधितम् सशर्करं पिबेत् प्रातर्लिह्याद्वा माक्षिकान्वितम्", text: "kvāthīkṛtenekṣurase kṣīrayuktena sādhitam saśarkaraṃ pibet prātarlihyādvā mākṣikānvitam" },
      { type: "verse", number: "45", sanskrit: "क्षीरिवृक्षाड्कुरक्वाथे पक्वं क्षीरसमं घृतम् पाययेत् पित्तकासार्तं मधुना वावलेहयेत्", text: "kṣīrivṛkṣāḍkurakvāthe pakvaṃ kṣīrasamaṃ ghṛtam pāyayet pittakāsārtaṃ madhunā vāvalehayet" },
      { type: "verse", number: "46", sanskrit: "मेदां विदारीं काकोलीं स्वयंगुप्ताफलं बलाम् शर्करां जीवकं मुद्गमाषपर्ण्यौ दुरालभाम्", text: "medāṃ vidārīṃ kākolīṃ svayaṃguptāphalaṃ balām śarkarāṃ jīvakaṃ mudgamāṣaparṇyau durālabhām" },
      { type: "verse", number: "47", sanskrit: "कल्कीकृत्य पचेत् सर्पिः क्षीरेणाष्टगुणेन तत् पानभोजनलेहेषु प्रयुक्तं पित्तकासजित्", text: "kalkīkṛtya pacet sarpiḥ kṣīreṇāṣṭaguṇena tat pānabhojanaleheṣu prayuktaṃ pittakāsajit" },
      { type: "verse", number: "48", sanskrit: "लिह्याद्वा चूर्णमेतेषां कषायमथवा पिबेत् कफकासी पिबेदादौ सुरकाष्ठात् प्रदीपितात्", text: "lihyādvā cūrṇameteṣāṃ kaṣāyamathavā pibet kaphakāsī pibedādau surakāṣṭhāt pradīpitāt" },
      { type: "verse", number: "49", sanskrit: "स्नेहं परिस्रुतं व्योषयवक्षारावचूर्णितम् स्निग्धं विरेचयेदूर्ध्वमधो मूर्ध्नि च युक्तितः", text: "snehaṃ parisrutaṃ vyoṣayavakṣārāvacūrṇitam snigdhaṃ virecayedūrdhvamadho mūrdhni ca yuktitaḥ" },
      { type: "verse", number: "50", sanskrit: "तीक्ष्णैर्विरेकैर्बलिनं संसर्गीं चास्य योजयेत् यवमुद्गकुलत्थान्नैरुष्णरूक्षैः कटूत्कटैः", text: "tīkṣṇairvirekairbalinaṃ saṃsargīṃ cāsya yojayet yavamudgakulatthānnairuṣṇarūkṣaiḥ kaṭūtkaṭaiḥ" },
      { type: "verse", number: "51", sanskrit: "कासमर्दकवार्ताकव्याघ्नीक्षारकणान्वितैः धान्वबैलरसैःस्नेहौस्तिलसर्षपनिम्बजैः", text: "kāsamardakavārtākavyāghnīkṣārakaṇānvitaiḥ dhānvabailarasaiḥsnehaustilasarṣapanimbajaiḥ" },
      { type: "verse", number: "52", sanskrit: "दशमूलाम्बु घर्माम्बु मद्य मध्वम्बु वा पिबेत् मूलैः पौष्करशम्याकपटोलैरन्वितं निशाम्", text: "daśamūlāmbu gharmāmbu madya madhvambu vā pibet mūlaiḥ pauṣkaraśamyākapaṭolairanvitaṃ niśām" },
      { type: "verse", number: "53", sanskrit: "पिबेद्वारि सहक्षौद्रं कालेष्वन्नस्य वा त्रिषु पिप्पलीपिप्पलीमूलं शृङ्गवेरं बिभीतकम्", text: "pibedvāri sahakṣaudraṃ kāleṣvannasya vā triṣu pippalīpippalīmūlaṃ śṛṅgaveraṃ bibhītakam" },
      { type: "verse", number: "54", sanskrit: "देवदार्वभया मुस्तं पिप्पलीविश्वभेषजम् गुडूची पिप्पलीभाङ्र्गीशृङ्गीकर्कटकस्य च", text: "devadārvabhayā mustaṃ pippalīviśvabheṣajam guḍūcī pippalībhāṅrgīśṛṅgīkarkaṭakasya ca" },
      { type: "verse", number: "55", sanskrit: "व्योषदारुचिडङ्गानि त्रिफलाशर्कराबलाः निदिग्धिकाया मूलत्वङ्मरिचैः सह योजिता", text: "vyoṣadāruciḍaṅgāni triphalāśarkarābalāḥ nidigdhikāyā mūlatvaṅmaricaiḥ saha yojitā" },
      { type: "verse", number: "56", sanskrit: "शिखिकुक्कुटपिञ्छानां मषी क्षारो यवोद्भवः विशाला पिप्पलीमूलं त्रिवृता च मधुद्रवाः", text: "śikhikukkuṭapiñchānāṃ maṣī kṣāro yavodbhavaḥ viśālā pippalīmūlaṃ trivṛtā ca madhudravāḥ" },
      { type: "verse", number: "57", sanskrit: "कफकासहरा लेहाः सप्त श्लोकार्धयोजिताः मधुना मरिचं लिह्यान्मधुनैव च जोङ्गकम्", text: "kaphakāsaharā lehāḥ sapta ślokārdhayojitāḥ madhunā maricaṃ lihyānmadhunaiva ca joṅgakam" },
      { type: "verse", number: "58", sanskrit: "पृथग्रसांश्च मधुना व्याघ्रीवार्ताकभृङ्गजान् कासघ्नस्याश्वशकृतः सुरसस्यासितस्य च", text: "pṛthagrasāṃśca madhunā vyāghrīvārtākabhṛṅgajān kāsaghnasyāśvaśakṛtaḥ surasasyāsitasya ca" },
      { type: "verse", number: "59", sanskrit: "देवदारुशठीरास्नाकर्कटाख्यादुरालभाः पिप्पली नागरं मुस्तं पथ्याधात्रीसितोपलाः", text: "devadāruśaṭhīrāsnākarkaṭākhyādurālabhāḥ pippalī nāgaraṃ mustaṃ pathyādhātrīsitopalāḥ" },
      { type: "verse", number: "60", sanskrit: "मधुतैलयुतावेतौ लेहौ वातानुगे कफे विडङ्गं सैन्धवं हिङ्गु कुष्ठं व्योषं मनःशिलाम्", text: "madhutailayutāvetau lehau vātānuge kaphe viḍaṅgaṃ saindhavaṃ hiṅgu kuṣṭhaṃ vyoṣaṃ manaḥśilām" },
      { type: "verse", number: "61", sanskrit: "कासे श्वासे च हिध्मायां लिह्यात् क्षौद्रघृताप्लुतम् गुडक्षारोषणकणादाडिमं श्वासकासजित् क्रमात्पलद्वयार्धाक्षकर्षार्धाक्षपलोन्मितम्", text: "kāse śvāse ca hidhmāyāṃ lihyāt kṣaudraghṛtāplutam guḍakṣāroṣaṇakaṇādāḍimaṃ śvāsakāsajit kramātpaladvayārdhākṣakarṣārdhākṣapalonmitam" },
      { type: "verse", number: "62", sanskrit: "द्वे पले दाडिमादष्टौ गुडाद्व्योषात् पलत्रयम् रोचनं दीपनं स्वर्यं पीनसश्वासकासजित्", text: "dve pale dāḍimādaṣṭAu guḍādvyoṣāt palatrayam rocanaṃ dīpanaṃ svaryaṃ pīnasaśvāsakāsajit" },
      { type: "verse", number: "63", sanskrit: "पाठाशुण्ठीशठीमूर्वागवाक्षीपिप्पलीघनम् पिष्ट्वा घर्माम्बुना हिङ्गुसैन्धवाभ्यां युतं पिबेत् तद्वन्मुस्ताशठीशुण्ठीनागरातिविषभयाः", text: "pāṭhāśuṇṭhīśaṭhīmūrvāgavākṣīpippalīghanam piṣṭvā gharmāmbunā hiṅgusaindhavābhyāṃ yutaṃ pibet tadvanmustāśaṭhīśuṇṭhīnāgarātiviṣabhayāḥ" },
      { type: "verse", number: "64", sanskrit: "पिबेज्ज्वरोक्तं पथ्यादि सशृङ्गीकं च पाचनम् अथवा दीप्यकत्रिवृद्विशालाघनपौष्करम्", text: "pibejjvaroktaṃ pathyādi saśṛṅgīkaṃ ca pācanam athavā dīpyakatrivṛdviśālāghanapauṣkaram" },
      { type: "verse", number: "65", sanskrit: "सकणं क्वथितं मूत्रे कफकासी जले ऽपि वा तैलभृष्टं च वैदेहीकल्काक्षं ससितोपलम्", text: "sakaṇaṃ kvathitaṃ mūtre kaphakāsī jale 'pi vā tailabhṛṣṭaṃ ca vaidehīkalkākṣaṃ sasitopalam" },
      { type: "verse", number: "66", sanskrit: "पाययेत् कफकासघ्नं कुलत्थसलिलाप्लुतम् सौवर्चलाभयाधात्रीपिप्पलीक्षारनागरम्", text: "pāyayet kaphakāsaghnaṃ kulatthasalilāplutam sauvarcalābhayādhātrīpippalīkṣāranāgaram" },
      { type: "verse", number: "67", sanskrit: "चूर्णितं सर्पिषा वातकफकासहरं पिबेत् दशमूलाढके प्रस्थं घृतस्याक्षसमैः पचेत्", text: "cūrṇitaṃ sarpiṣā vātakaphakāsaharaṃ pibet daśamūlāḍhake prasthaṃ ghṛtasyākṣasamaiḥ pacet" },
      { type: "verse", number: "68", sanskrit: "पुष्कराह्वशठीविल्वसुरसव्योषहिङ्गुभिः पेयानुपानं तत् सर्ववातश्लेष्मामयापहम्", text: "puṣkarāhvaśaṭhīvilvasurasavyoṣahiṅgubhiḥ peyānupānaṃ tat sarvavātaśleṣmāmayāpaham" },
      { type: "verse", number: "69", sanskrit: "निर्गुण्डीपत्रनिर्याससाधितं कासजिद्घृतम् घृतं रसे विडङ्गानां व्योषगर्भं च साधितम्", text: "nirguṇḍīpatraniryāsasādhitaṃ kāsajidghṛtam ghṛtaṃ rase viḍaṅgānāṃ vyoṣagarbhaṃ ca sādhitam" },
      { type: "verse", number: "70", sanskrit: "पुनर्नव्सिताटिकासुरसकासमर्दामृता पटोलबृहतीफणिज्जकरसैः पयःसंयुतैः घृतं त्रिकटुना च सिद्धमुपयुज्य सञ्जायते न कासविषमज्वरक्षयगुदाङ्कुरेभ्यो भयम्", text: "punarnavsitāṭikāsurasakāsamardāmṛtā paṭolabṛhatīphaṇijjakarasaiḥ payaḥsaṃyutaiḥ ghṛtaṃ trikaṭunā ca siddhamupayujya sañjāyate na kāsaviṣamajvarakṣayagudāṅkurebhyo bhayam" },
      { type: "verse", number: "71", sanskrit: "समूलफलपत्रायाः कण्टकार्या रसाढके घृतप्रस्थं बलाव्योषविडङ्गशठिदाडिमैः", text: "samūlaphalapatrāyāḥ kaṇṭakāryā rasāḍhake ghṛtaprasthaṃ balāvyoṣaviḍaṅgaśaṭhidāḍimaiḥ" },
      { type: "verse", number: "72", sanskrit: "सौवर्चलयवक्षारमूलामलकपौष्करैः वृश्चीवबृहतीपथ्यायवानीचित्रकर्धिभिः", text: "sauvarcalayavakṣāramūlāmalakapauṣkaraiḥ vṛścīvabṛhatīpathyāyavānīcitrakardhibhiḥ" },
      { type: "verse", number: "73", sanskrit: "मृद्वीकाचव्यवर्षाभूदुरालम्भाम्लवेतसैः शृङ्गीतामलकीभार्ङ्गीरास्नागोक्षुरकैः पचेत्", text: "mṛdvīkācavyavarṣābhūdurālambhāmlavetasaiḥ śṛṅgītāmalakībhārṅgīrāsnāgokṣurakaiḥ pacet" },
      { type: "verse", number: "74", sanskrit: "कल्कैस्तत् सर्वकासेषु श्वासहिध्मासु चेष्यते", text: "kalkaistat sarvakāseṣu śvāsahidhmāsu ceṣyate" },
      { type: "verse", number: "75", sanskrit: "कण्टकार्यास्तुलां क्षुण्णां पक्त्वा द्रोणे ऽम्भसः पचेत् तेनाढकेन क्वाथस्य घृतप्रस्यं पिचून्मितैः", text: "kaṇṭakāryāstulāṃ kṣuṇṇāṃ paktvā droṇe 'mbhasaḥ pacet tenāḍhakena kvāthasya ghṛtaprasyaṃ picūnmitaiḥ" },
      { type: "verse", number: "76", sanskrit: "रास्नादुस्पर्शषङ्ग्रन्थापिप्पलीद्वयचित्रकैः सौवर्चलयवक्षारकृष्णामूलैश्च तज्जयेत्", text: "rāsnādusparśaṣaṅgranthāpippalīdvayacitrakaiḥ sauvarcalayavakṣārakṛṣṇāmūlaiśca tajjayet" },
      { type: "verse", number: "77", sanskrit: "कासश्वासकफष्ठीवहिध्मारोचकपीनसान् पचेद्व्याघ्नीतुलां क्षुण्णां वहे ऽपामाढकस्थिते", text: "kāsaśvāsakaphaṣṭhīvahidhmārocakapīnasān pacedvyāghnītulāṃ kṣuṇṇāṃ vahe 'pāmāḍhakasthite" },
      { type: "verse", number: "78", sanskrit: "क्षिपेत् पूते तु सञ्चूर्ण्य व्योषरास्नामृताग्निकान् शृङ्गीर्भार्ङ्गीघनग्रन्थिधन्वयासान् पलार्धकान्", text: "kṣipet pūte tu sañcūrṇya vyoṣarāsnāmṛtāgnikān śṛṅgīrbhārṅgīghanagranthidhanvayāsān palārdhakān" },
      { type: "verse", number: "79", sanskrit: "सर्पिषः षोडशपलं चत्वारिंशत्पलानि च मत्स्यण्डिकायाः शुद्धायाः पुनश्च तदधिश्रयेत्", text: "sarpiṣaḥ ṣoḍaśapalaṃ catvāriṃśatpalāni ca matsyaṇḍikāyāḥ śuddhāyāḥ punaśca tadadhiśrayet" },
      { type: "verse", number: "80", sanskrit: "दर्वीलेपिनि शीते च पृथक् द्विकुडवं क्षिपेत् पिप्पलीनां तवक्षीर्या माक्षिकस्यानवस्य च", text: "darvīlepini śīte ca pṛthak dvikuḍavaṃ kṣipet pippalīnāṃ tavakṣīryā mākṣikasyānavasya ca" },
      { type: "verse", number: "81", sanskrit: "लेहो ऽयं गुल्महृद्रोगदुर्नामश्वासकासजित् त्रिफलापिप्पलीपाठासारिवाबृहतीद्वयम् मरिचं पद्मकं मुस्तमुशीरं चाक्षसम्मितम्", text: "leho 'yaṃ gulmahṛdrogadurnāmaśvāsakāsajit triphalāpippalīpāṭhāsārivābṛhatīdvayam maricaṃ padmakaṃ mustamuśīraṃ cākṣasammitam" },
      { type: "verse", number: "82", sanskrit: "पक्त्वा जलाढके पादशेषे क्षीरपलाष्टकम् दत्वा गुडस्य च पलं पचेदादर्विलेपनात्", text: "paktvā jalāḍhake pādaśeṣe kṣīrapalāṣṭakam datvā guḍasya ca palaṃ pacedādarvilepanāt" },
      { type: "verse", number: "83", sanskrit: "लेहः कफोल्बणं कासं सर्वमेव नियच्छति साधितं क्षीरमेभिर्वा तिलक्षौद्रयुतं पिबेत्", text: "lehaḥ kapholbaṇaṃ kāsaṃ sarvameva niyacchati sādhitaṃ kṣīramebhirvā tilakṣaudrayutaṃ pibet" },
      { type: "verse", number: "84", sanskrit: "शमनं च पिबेद्धूमं शोधनं बहले कफे", text: "śamanaṃ ca pibeddhūmaṃ śodhanaṃ bahale kaphe" },
      { type: "verse", number: "85", sanskrit: "मनःशिलालमधुकमांसीमुस्ते ऽङ्गुदीत्वचः धूमं कासघ्नविधिना पीत्वा क्षीरं पिबेदनु", text: "manaḥśilālamadhukamāṃsīmuste 'ṅgudītvacaḥ dhūmaṃ kāsaghnavidhinā pītvā kṣīraṃ pibedanu" },
      { type: "verse", number: "86", sanskrit: "निष्ठ्यूतान्ते गुडयुतं कोष्णं धूमो निहन्ति सः वातश्लेष्मोत्तरान् कासानचिरेण चिरन्तनान्", text: "niṣṭhyūtānte guḍayutaṃ koṣṇaṃ dhūmo nihanti saḥ vātaśleṣmottarān kāsānacireṇa cirantanān" },
      { type: "verse", number: "87", sanskrit: "प्रपौण्डरीकं मधुकं शार्ङ्गेष्टालं मनःशिलाम् मरिचं पिप्पलीं द्राक्षामेलां सुरसमञ्जरीम्", text: "prapauṇḍarīkaṃ madhukaṃ śārṅgeṣṭālaṃ manaḥśilām maricaṃ pippalīṃ drākṣāmelāṃ surasamañjarīm" },
      { type: "verse", number: "88", sanskrit: "कृत्वा वर्तिं पिबेद्धूमं क्षौमचैलानुवर्तिनी घृताक्तामनु च क्षीरं पिबेत् तद्वत् गुडाम्बु वा", text: "kṛtvā vartiṃ pibeddhūmaṃ kṣaumacailānuvartinī ghṛtāktāmanu ca kṣīraṃ pibet tadvat guḍāmbu vā" },
      { type: "verse", number: "89", sanskrit: "नेपालीतालमरिचलाक्षाञ्जनकुटन्नटैः उशीररोहिषफलद्रामिलीवंशलेखनैः", text: "nepālītālamaricalākṣāñjanakuṭannaṭaiḥ uśīrarohiṣaphaladrāmilīvaṃśalekhanaiḥ" },
      { type: "verse", number: "90", sanskrit: "पूर्वकल्पेन धूमो ऽयं सानुपानो विधीयते कार्पासास्थ्यश्वगन्धा च धूमः कासविनाशनः कोशातकीफलान्मध्यैः पिबेद्वा समनःशिलैः", text: "pūrvakalpena dhūmo 'yaṃ sānupāno vidhīyate kārpāsāsthyaśvagandhā ca dhūmaḥ kāsavināśanaḥ kośātakīphalānmadhyaiḥ pibedvā samanaḥśilaiḥ" },
      { type: "verse", number: "91", sanskrit: "तमकः कफकासे तु स्याच्चेत् पित्तानुबन्धजः पित्तकासक्रियां तत्र यथावस्थं प्रयोजयत्", text: "tamakaḥ kaphakāse tu syāccet pittānubandhajaḥ pittakāsakriyāṃ tatra yathāvasthaṃ prayojayat" },
      { type: "verse", number: "92", sanskrit: "कफानुबन्धे पवने कुर्यात् कफहरां क्रियाम् पित्तानुबम्धयोर्वातकफयोः पित्तनाशिनीम्", text: "kaphānubandhe pavane kuryāt kaphaharāṃ kriyām pittānubamdhayorvātakaphayoḥ pittanāśinīm" },
      { type: "verse", number: "93", sanskrit: "वातश्लेष्मात्मके शुष्के स्निग्धमार्द्रे विरूक्षणम् कासे कर्म सपित्ते तु कफजे तिक्तसंयुतम्", text: "vātaśleṣmātmake śuṣke snigdhamārdre virūkṣaṇam kāse karma sapitte tu kaphaje tiktasaṃyutam" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 5,
    lang: "sa",
    content: [
      { type: "heading", heading: "Удара чикитса — лечение болезней живота" },
      { type: "text", text: "Глава 5 Чикитса стханы — лечебный раздел о лечение болезней живота. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातः क्षतक्षयकासचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ kṣatakṣayakāsacikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "उरस्यन्तःक्षते सद्यो लाक्षां क्षौद्रयुतां पिबेत् क्षीरणे शालीन् जीर्णे ऽद्यात् क्षीरेणैव सशर्करान्", text: "urasyantaḥkṣate sadyo lākṣāṃ kṣaudrayutāṃ pibet kṣīraṇe śālīn jīrṇe 'dyāt kṣīreṇaiva saśarkarān" },
      { type: "verse", number: "3", sanskrit: "पार्श्वबस्तिसरुक्चाल्पपित्ताग्निस्तां सुरायुताम् भिन्नविट् तु समुस्तातिविषापाठां सवत्सकाम्", text: "pārśvabastisarukcālpapittāgnistāṃ surāyutām bhinnaviṭ tu samustātiviṣāpāṭhāṃ savatsakām" },
      { type: "verse", number: "4", sanskrit: "लाक्षां सर्पिर्मधूच्छिष्टं जीवनीयगणं सिताम् त्वक्क्षीरीं समितं क्षीरे पक्त्वा दीप्तानलः पिबेत्", text: "lākṣāṃ sarpirmadhūcchiṣṭaṃ jīvanīyagaṇaṃ sitām tvakkṣīrīṃ samitaṃ kṣīre paktvā dīptānalaḥ pibet" },
      { type: "verse", number: "5", sanskrit: "इक्ष्वालिकाबिसग्रन्थिपद्मकेसरचन्द्रनैः शृतं पयो मधुयुतं सन्धानार्थं पिबेत् क्षती", text: "ikṣvālikābisagranthipadmakesaracandranaiḥ śṛtaṃ payo madhuyutaṃ sandhānārthaṃ pibet kṣatī" },
      { type: "verse", number: "6", sanskrit: "यवानां चूर्णमामानां क्षीरसिद्धं घृतान्वितम् ज्वरदाहे सिताक्षौद्रसक्तून् वा पयसा पिबेत्", text: "yavānāṃ cūrṇamāmānāṃ kṣīrasiddhaṃ ghṛtānvitam jvaradāhe sitākṣaudrasaktūn vā payasā pibet" },
      { type: "verse", number: "7", sanskrit: "कासवांस्तु पिबेत्सर्पिर्मधुरौषधसाधितम् गुडोदकं वा क्वथितं सक्षौद्रमरिचं हिमम्", text: "kāsavāṃstu pibetsarpirmadhurauṣadhasādhitam guḍodakaṃ vā kvathitaṃ sakṣaudramaricaṃ himam" },
      { type: "verse", number: "8", sanskrit: "चूर्णमामलकानां वा क्षीरे पक्वं घृतान्वितम् रसायनविधानेन पिप्पलीर्वा प्रयोजयेत्", text: "cūrṇamāmalakānāṃ vā kṣīre pakvaṃ ghṛtānvitam rasāyanavidhānena pippalīrvā prayojayet" },
      { type: "verse", number: "9", sanskrit: "कासी पर्वास्थिशूली च लिह्यात्सघृतमाक्षिकाः मधूकमधुकद्राक्षात्वक्क्षीरीपिप्पलीबलाः", text: "kāsī parvāsthiśūlī ca lihyātsaghṛtamākṣikāḥ madhūkamadhukadrākṣātvakkṣīrīpippalībalāḥ" },
      { type: "verse", number: "10", sanskrit: "त्रिजातमर्धकर्षांशं पिप्पल्यर्धपलं सिता द्राक्षा मधूकं खर्जूरं पलांशं श्लक्ष्णचूर्णितम्", text: "trijātamardhakarṣāṃśaṃ pippalyardhapalaṃ sitā drākṣā madhūkaṃ kharjūraṃ palāṃśaṃ ślakṣṇacūrṇitam" },
      { type: "verse", number: "11", sanskrit: "मधुना गुटिका घ्नन्ति ता वृष्याः पित्तशोणितम् कासश्वासारुचिच्छार्दिमूर्छाहिध्मामदभ्रमान्", text: "madhunā guṭikā ghnanti tā vṛṣyāḥ pittaśoṇitam kāsaśvāsārucicchārdimūrchāhidhmāmadabhramān" },
      { type: "verse", number: "12", sanskrit: "क्षतक्षयस्वरभ्रंशप्लीहशोषाढ्यमारुतान् रक्तनिष्ठीवहृत्पार्श्वरुक्पिपासाज्वरानपि", text: "kṣatakṣayasvarabhraṃśaplīhaśoṣāḍhyamārutān raktaniṣṭhīvahṛtpārśvarukpipāsājvarānapi" },
      { type: "verse", number: "13", sanskrit: "रक्ते ऽतिवृद्धे च्छागं वा जाङ्गलं वा पिबेदसृक् वर्षाभूशर्करारक्तशालितण्डुलजं रजः", text: "rakte 'tivṛddhe cchāgaṃ vā jāṅgalaṃ vā pibedasṛk varṣābhūśarkarāraktaśālitaṇḍulajaṃ rajaḥ" },
      { type: "verse", number: "14", sanskrit: "रक्तष्ठीवी पिबेत् सिद्धं द्राक्षारसपयोघृतैः मधूकमधुकक्षीरसिद्धं वा तण्डुलीयकम्", text: "raktaṣṭhīvī pibet siddhaṃ drākṣārasapayoghṛtaiḥ madhūkamadhukakṣīrasiddhaṃ vā taṇḍulīyakam" },
      { type: "verse", number: "15", sanskrit: "यथास्वं मार्गविसृते रक्ते कुर्याच्च भेषजम् पिप्पलीमधुकं पिष्टं कार्षिकं ससितोपलम्", text: "yathāsvaṃ mārgavisṛte rakte kuryācca bheṣajam pippalīmadhukaṃ piṣṭaṃ kārṣikaṃ sasitopalam" },
      { type: "verse", number: "16", sanskrit: "प्रास्थिकं गव्यमाजं च क्षीरमिक्षुरसं तथा यवगोधूममृद्वीकाचूर्णमामलकाद्रसः", text: "prāsthikaṃ gavyamājaṃ ca kṣīramikṣurasaṃ tathā yavagodhūmamṛdvīkācūrṇamāmalakādrasaḥ" },
      { type: "verse", number: "17", sanskrit: "तैलं च प्रसृतांशानि तत् सर्वं मृदुनाग्निना पचेल्लेहो घृतक्षौद्रयुतः स क्षतकासनुत्", text: "tailaṃ ca prasṛtāṃśāni tat sarvaṃ mṛdunāgninā pacelleho ghṛtakṣaudrayutaḥ sa kṣatakāsanut" },
      { type: "verse", number: "18", sanskrit: "श्वासहृद्रोगकासघ्नो हितो वृद्धाल्परेतसाम् मूढवातस्त्वजामेदः सुराभृष्टं ससैन्धवम्", text: "śvāsahṛdrogakāsaghno hito vṛddhālparetasām mūḍhavātastvajāmedaḥ surābhṛṣṭaṃ sasaindhavam" },
      { type: "verse", number: "19", sanskrit: "क्षामः क्षीणः क्षतोरस्को मन्दनिद्रो ऽग्निदीप्तिमान् शतक्षीरसरेणाद्यात् सघृतक्षौद्रशर्करम्", text: "kṣāmaḥ kṣīṇaḥ kṣatorasko mandanidro 'gnidīptimān śatakṣīrasareṇādyāt saghṛtakṣaudraśarkaram" },
      { type: "verse", number: "20", sanskrit: "शर्करायवगोधूमं जीवकर्षभकौ मधु घृतक्षीरानुपानं वा लिह्यात् क्षीणः क्षती कृशः", text: "śarkarāyavagodhūmaṃ jīvakarṣabhakau madhu ghṛtakṣīrānupānaṃ vā lihyāt kṣīṇaḥ kṣatī kṛśaḥ" },
      { type: "verse", number: "21", sanskrit: "क्रव्यात्पिशितनिर्यूहं घृतभृष्टं पिबेच्च सः पिप्पलीक्षौद्रसंयुक्तं मांसशोणितवर्धनम्", text: "kravyātpiśitaniryūhaṃ ghṛtabhṛṣṭaṃ pibecca saḥ pippalīkṣaudrasaṃyuktaṃ māṃsaśoṇitavardhanam" },
      { type: "verse", number: "22", sanskrit: "न्यग्रोधोदुम्बराश्वत्थप्लक्षसालप्रियङ्गुभिः तालमस्तकजम्वूत्वक्प्रियालैश्च सपद्मकैः", text: "nyagrodhodumbarāśvatthaplakṣasālapriyaṅgubhiḥ tālamastakajamvūtvakpriyālaiśca sapadmakaiḥ" },
      { type: "verse", number: "23", sanskrit: "साश्वकर्णैः शृतात् क्षीरादद्याज्जातेन सर्पिषा शाल्योदनं क्षतोरस्कः क्षीणशुक्रबलेन्द्रियः", text: "sāśvakarṇaiḥ śṛtāt kṣīrādadyājjātena sarpiṣā śālyodanaṃ kṣatoraskaḥ kṣīṇaśukrabalendriyaḥ" },
      { type: "verse", number: "24", sanskrit: "वातपित्तार्दिते ऽभ्यङ्गो गात्रभेदे घृतैर्मतः तैलैश्चानिलरोगघ्नैः पीडिते मातरिश्वना", text: "vātapittārdite 'bhyaṅgo gātrabhede ghṛtairmataḥ tailaiścānilarogaghnaiḥ pīḍite mātariśvanā" },
      { type: "verse", number: "25", sanskrit: "हृत्पार्श्वार्तिषु पानं स्यात् जीवनीयस्य सर्पिषः कुर्याद्वा वातरोगघ्नं पित्तरक्तविरोधि यत्", text: "hṛtpārśvārtiṣu pānaṃ syāt jīvanīyasya sarpiṣaḥ kuryādvā vātarogaghnaṃ pittaraktavirodhi yat" },
      { type: "verse", number: "26", sanskrit: "यष्ट्याह्वनागबलयोः क्वाथे क्षीरसमं घृतम् पयस्यापिप्पलीवांशीकल्कसिद्धं क्षते हितम्", text: "yaṣṭyāhvanāgabalayoḥ kvāthe kṣīrasamaṃ ghṛtam payasyāpippalīvāṃśīkalkasiddhaṃ kṣate hitam" },
      { type: "verse", number: "27", sanskrit: "घृतं वाष्टगुणे क्षीरे कोललाक्षरसान्वितम् कल्कैः कट्वङ्गदार्वीत्वग्वत्सकत्वक्दलैर्घृतम्", text: "ghṛtaṃ vāṣṭaguṇe kṣīre kolalākṣarasānvitam kalkaiḥ kaṭvaṅgadārvītvagvatsakatvakdalairghṛtam" },
      { type: "verse", number: "28", sanskrit: "जीवनीयो गणः शुण्ठी वरी वीरापुनर्नवौ बलाभार्ङ्गीस्वगुप्तर्धिशठीतामलकीकणाः", text: "jīvanīyo gaṇaḥ śuṇṭhī varī vīrāpunarnavau balābhārṅgīsvaguptardhiśaṭhītāmalakīkaṇāḥ" },
      { type: "verse", number: "29", sanskrit: "शृङ्गाटकं पयस्या च पञ्चमूलं च यल्लधु द्राक्षाक्षोडादि च फलं मधुरस्निग्धबृंहणम्", text: "śṛṅgāṭakaṃ payasyā ca pañcamūlaṃ ca yalladhu drākṣākṣoḍādi ca phalaṃ madhurasnigdhabṛṃhaṇam" },
      { type: "verse", number: "30", sanskrit: "तैः पचेत् सर्पिषः प्रस्थं कार्षांशैः श्लक्ष्णकल्कितैः क्षीरधात्रीविदारीक्षुच्छागमांसरसान्वितम्", text: "taiḥ pacet sarpiṣaḥ prasthaṃ kārṣāṃśaiḥ ślakṣṇakalkitaiḥ kṣīradhātrīvidārīkṣucchāgamāṃsarasānvitam" },
      { type: "verse", number: "31", sanskrit: "प्रस्थार्धं मधुनः शीते शर्करार्धतुलारजः पलार्धिकं च मरिचत्वगेलापत्रकेसरम्", text: "prasthārdhaṃ madhunaḥ śīte śarkarārdhatulārajaḥ palārdhikaṃ ca maricatvagelāpatrakesaram" },
      { type: "verse", number: "32", sanskrit: "विनीय चूर्णितं तस्माल्लिह्मान्मात्रां यथानलम् अमृतप्राशमित्येतन्नराणाममृतं घृतम्", text: "vinīya cūrṇitaṃ tasmāllihmānmātrāṃ yathānalam amṛtaprāśamityetannarāṇāmamṛtaṃ ghṛtam" },
      { type: "verse", number: "33", sanskrit: "सुधामृतरसं प्राश्यं क्षीरमांसरसाशिना नष्टशुक्रक्षतक्षीणदुर्बलव्याधिकर्शितान्", text: "sudhāmṛtarasaṃ prāśyaṃ kṣīramāṃsarasāśinā naṣṭaśukrakṣatakṣīṇadurbalavyādhikarśitān" },
      { type: "verse", number: "34", sanskrit: "स्त्रीप्रसक्तान् कृशान् वर्णस्वरहीनांश्च बृंहयेत् कासहिध्माज्वरश्वासदाहतृष्णास्रपित्तनुत् पुत्रदं छर्दिमूर्छाहृद्योनिमूत्रामयापहम्", text: "strīprasaktān kṛśān varṇasvarahīnāṃśca bṛṃhayet kāsahidhmājvaraśvāsadāhatṛṣṇāsrapittanut putradaṃ chardimūrchāhṛdyonimūtrāmayāpaham" },
      { type: "verse", number: "35", sanskrit: "श्वदंष्ट्रोशीरमञ्जिष्ठाबलाकाश्मर्यकत्तृणम् दर्भमूलं पृथक्पर्णीं पलाशर्षभकौ स्थिराम्", text: "śvadaṃṣṭrośīramañjiṣṭhābalākāśmaryakattṛṇam darbhamūlaṃ pṛthakparṇīṃ palāśarṣabhakau sthirām" },
      { type: "verse", number: "36", sanskrit: "पालिकानि पचेत्तेषां रसे क्षीरचतुर्गुणे कल्कैः स्वगुप्ताजीवन्तीमेदर्षभकजीवकैः", text: "pālikāni pacetteṣāṃ rase kṣīracaturguṇe kalkaiḥ svaguptājīvantīmedarṣabhakajīvakaiḥ" },
      { type: "verse", number: "37", sanskrit: "शतावर्यृद्धिमृद्वीकाशर्कराश्रावणीबिसैः प्रस्थः सिद्धो घृताद्वातपित्तहृद्रोगशूलनुत्", text: "śatāvaryṛddhimṛdvīkāśarkarāśrāvaṇībisaiḥ prasthaḥ siddho ghṛtādvātapittahṛdrogaśūlanut" },
      { type: "verse", number: "38", sanskrit: "मूत्रकृच्छ्रप्रमेहार्शः कासशोषक्षयापहः धनुःस्त्रीमद्यभाराध्वखिन्नानां बलमांसदः", text: "mūtrakṛcchrapramehārśaḥ kāsaśoṣakṣayāpahaḥ dhanuḥstrīmadyabhārādhvakhinnānāṃ balamāṃsadaḥ" },
      { type: "verse", number: "39", sanskrit: "मधुकाष्टपलद्राक्षाप्रस्थक्वाथे पचेद् घृतम् पिप्पल्यष्टपले कल्के प्रस्थं सिद्धे च शीतले", text: "madhukāṣṭapaladrākṣāprasthakvāthe paced ghṛtam pippalyaṣṭapale kalke prasthaṃ siddhe ca śītale" },
      { type: "verse", number: "40", sanskrit: "पृथगष्टपलं क्षौद्रशर्कराभ्यां च मिश्रयेत् समसक्तु क्षतक्षीणरक्तगुल्मेषु तद्धितम्", text: "pṛthagaṣṭapalaṃ kṣaudraśarkarābhyāṃ ca miśrayet samasaktu kṣatakṣīṇaraktagulmeṣu taddhitam" },
      { type: "verse", number: "41", sanskrit: "धात्रीफलविदारीक्षुजीवनीयरसात् घृतात् गव्याजयोश्च पयसोः प्रस्थं प्रस्थं विपाचयेत्", text: "dhātrīphalavidārīkṣujīvanīyarasāt ghṛtāt gavyājayośca payasoḥ prasthaṃ prasthaṃ vipācayet" },
      { type: "verse", number: "42", sanskrit: "सिद्धशीते सिताक्षौद्रद्विप्रस्थं विनयेत्ततः यक्ष्मापस्मारपित्तासृक्कासमेहक्षयापहम् वयःस्थापनमायुष्यं मांसशुक्रबलप्रदम्", text: "siddhaśīte sitākṣaudradviprasthaṃ vinayettataḥ yakṣmāpasmārapittāsṛkkāsamehakṣayāpaham vayaḥsthāpanamāyuṣyaṃ māṃsaśukrabalapradam" },
      { type: "verse", number: "43", sanskrit: "घृतं तु पित्ते ऽभ्यधिके लिह्याद्व्यते ऽधिके पिबेत् लीढं निर्वापयेत् पित्तमल्पत्वाद्धन्ति नानलम् आक्रामत्यनिलं पीतमूष्माणं निरुणाद्धि च", text: "ghṛtaṃ tu pitte 'bhyadhike lihyādvyate 'dhike pibet līḍhaṃ nirvāpayet pittamalpatvāddhanti nānalam ākrāmatyanilaṃ pītamūṣmāṇaṃ niruṇāddhi ca" },
      { type: "verse", number: "44", sanskrit: "क्षामक्षीणकृशाङ्गानामेतान्येव घृतानि तु त्वक्क्षीरीपिप्पलीलाजचूर्णैः स्त्यानानि योजयेत्", text: "kṣāmakṣīṇakṛśāṅgānāmetānyeva ghṛtāni tu tvakkṣīrīpippalīlājacūrṇaiḥ styānāni yojayet" },
      { type: "verse", number: "45", sanskrit: "सर्पिर्गुडान् समध्वंशान् कृत्वा दद्यात् पयोनु च रेतोवीर्यं बलं पुष्टिं तैराशुतरमाप्नुयात्", text: "sarpirguḍān samadhvaṃśān kṛtvā dadyāt payonu ca retovīryaṃ balaṃ puṣṭiṃ tairāśutaramāpnuyāt" },
      { type: "verse", number: "46", sanskrit: "बला विदारी ह्रस्वं च पञ्चमूलं पुनर्नवम् पञ्चानां क्षीरिवृक्षाणां शुङ्गा मुष्ट्यंशकास्तथा", text: "balā vidārī hrasvaṃ ca pañcamūlaṃ punarnavam pañcānāṃ kṣīrivṛkṣāṇāṃ śuṅgā muṣṭyaṃśakāstathā" },
      { type: "verse", number: "47", sanskrit: "एषां कषाये द्विक्षीरे विदार्याजरसांशके जीवनीयैः पचेत् पिष्टैरक्षमात्रिर्घृताढकम्", text: "eṣāṃ kaṣāye dvikṣīre vidāryājarasāṃśake jīvanīyaiḥ pacet piṣṭairakṣamātrirghṛtāḍhakam" },
      { type: "verse", number: "48", sanskrit: "सितापलानि पूते च शीते द्वात्रिंशदावपेत् गोधूमपिप्पलीवांशीचूर्णं शृङ्गाटकस्य च", text: "sitāpalāni pūte ca śīte dvātriṃśadāvapet godhūmapippalīvāṃśīcūrṇaṃ śṛṅgāṭakasya ca" },
      { type: "verse", number: "49", sanskrit: "समाक्षिकं कौडविकं तत्सर्वं खजमूर्च्छितम् स्त्यानं सर्पिर्गुडान् कृत्वा भूर्जपत्रेण वेष्टयेत्", text: "samākṣikaṃ kauḍavikaṃ tatsarvaṃ khajamūrcchitam styānaṃ sarpirguḍān kṛtvā bhūrjapatreṇa veṣṭayet" },
      { type: "verse", number: "50", sanskrit: "तान् जग्ध्वा पालिकान् क्षीरं मद्यंत्वनुपिबेत् कफे शोषे कासे क्षते क्षीणे श्रमस्त्रीभारकर्शिते", text: "tān jagdhvā pālikān kṣīraṃ madyaṃtvanupibet kaphe śoṣe kāse kṣate kṣīṇe śramastrībhārakarśite" },
      { type: "verse", number: "51", sanskrit: "रक्तनिष्ठीवने तापे पीनसे चोरसि स्थिते शस्ताः पार्श्वशिरःशूले भेदे च स्वरवर्णयोः", text: "raktaniṣṭhīvane tāpe pīnase corasi sthite śastāḥ pārśvaśiraḥśūle bhede ca svaravarṇayoḥ" },
      { type: "verse", number: "52", sanskrit: "सर्शकराशृते क्षीरघृततैलाढकत्रये चूर्णीकृताः क्षिपेत् पक्वसान्द्रे दशपलाः पृथक्", text: "sarśakarāśṛte kṣīraghṛtatailāḍhakatraye cūrṇīkṛtāḥ kṣipet pakvasāndre daśapalāḥ pṛthak" },
      { type: "verse", number: "53", sanskrit: "द्राक्षात्मगुप्तावर्षाभूसमङ्गाभीरुपिप्पलीः तद्वद्विदार्यामलके प्रस्थार्धं विश्वभेषजम्", text: "drākṣātmaguptāvarṣābhūsamaṅgābhīrupippalīḥ tadvadvidāryāmalake prasthārdhaṃ viśvabheṣajam" },
      { type: "verse", number: "54", sanskrit: "क्षामः क्षीणः क्षतः शुष्यंस्तान्खादेत् पालिकैर्गुडैः तथा सद्यो रसादीनां वृध्या पुष्टिं समश्नुते", text: "kṣāmaḥ kṣīṇaḥ kṣataḥ śuṣyaṃstānkhādet pālikairguḍaiḥ tathā sadyo rasādīnāṃ vṛdhyā puṣṭiṃ samaśnute" },
      { type: "verse", number: "55", sanskrit: "गोक्षीरार्धाढकं सर्पिः प्रस्थमिक्षुरसाढकम् रसाद्विदार्याः कुडवं रसात् प्रस्थं च तैत्तिरात्", text: "gokṣīrārdhāḍhakaṃ sarpiḥ prasthamikṣurasāḍhakam rasādvidāryāḥ kuḍavaṃ rasāt prasthaṃ ca taittirāt" },
      { type: "verse", number: "56", sanskrit: "दद्यात् सिध्यति तस्मिंस्तु पिष्टानिक्षुरसैरिमान् मधूकषुष्पं कुडवं कुडवं च प्रियालतः", text: "dadyāt sidhyati tasmiṃstu piṣṭānikṣurasairimān madhūkaṣuṣpaṃ kuḍavaṃ kuḍavaṃ ca priyālataḥ" },
      { type: "verse", number: "57", sanskrit: "पलद्वयं तवक्षीर्याः खर्जूराणि च विंशतिः पृथग्विभीतकान्मज्ञः पिप्पल्याश्च चतुर्थिकाम्", text: "paladvayaṃ tavakṣīryāḥ kharjūrāṇi ca viṃśatiḥ pṛthagvibhītakānmajñaḥ pippalyāśca caturthikām" },
      { type: "verse", number: "58", sanskrit: "त्रिंशत्पलानि खण्डाच्च मधुकात् पाणिमानिकाम् तथार्धपलिकान्यत्र जीवनीयानि दापयेत्", text: "triṃśatpalāni khaṇḍācca madhukāt pāṇimānikām tathārdhapalikānyatra jīvanīyāni dāpayet" },
      { type: "verse", number: "59", sanskrit: "सिद्धे द्विकुडवं क्षौद्राच्छीते दत्वा च मोदकान् कारयेन्मरिचाजाजीपलचूर्णावचूर्णितान्", text: "siddhe dvikuḍavaṃ kṣaudrācchīte datvā ca modakān kārayenmaricājājīpalacūrṇāvacūrṇitān" },
      { type: "verse", number: "60", sanskrit: "वातासृक्पित्तरोगेषु क्षतकासक्षयेषु च क्षीणौजःस्वरशुक्रेषु योनिदोषेषु संस्रवे मृतप्रजासु वन्ध्यासु हितं गर्भस्य च स्रुतौ", text: "vātāsṛkpittarogeṣu kṣatakāsakṣayeṣu ca kṣīṇaujaḥsvaraśukreṣu yonidoṣeṣu saṃsrave mṛtaprajāsu vandhyāsu hitaṃ garbhasya ca srutau" },
      { type: "verse", number: "61", sanskrit: "वीतत्वगास्थिकूष्माण्डतुलां स्विन्नां पुनः पचेत्", text: "vītatvagāsthikūṣmāṇḍatulāṃ svinnāṃ punaḥ pacet" },
      { type: "verse", number: "62", sanskrit: "घट्टयन् सर्पिषः प्रस्थे क्षौद्रवर्णे ऽत्र च क्षिपेत् स्वण्डाच्छतं कणाशुण्ठ्योर्द्विपलं जीरकादपि", text: "ghaṭṭayan sarpiṣaḥ prasthe kṣaudravarṇe 'tra ca kṣipet svaṇḍācchataṃ kaṇāśuṇṭhyordvipalaṃ jīrakādapi" },
      { type: "verse", number: "63", sanskrit: "त्रिजातधान्यमरिचं पृथगर्धपलांशकम् अवतारितशीते च दत्वा क्षौद्रं घृतार्धिकम्", text: "trijātadhānyamaricaṃ pṛthagardhapalāṃśakam avatāritaśīte ca datvā kṣaudraṃ ghṛtārdhikam" },
      { type: "verse", number: "64", sanskrit: "स्वजेनामथ्य च स्थाप्यं तन्निहन्त्युपयोजितम् कासहिध्माज्वरश्वासरक्तपित्तक्षतक्षयान्", text: "svajenāmathya ca sthāpyaṃ tannihantyupayojitam kāsahidhmājvaraśvāsaraktapittakṣatakṣayān" },
      { type: "verse", number: "65", sanskrit: "उरःसन्धानजननं मेधास्मृतिबलप्रदम् अश्विभ्यांन्निर्मितं हृद्यं कूष्माण्डकरसायनम्", text: "uraḥsandhānajananaṃ medhāsmṛtibalapradam aśvibhyāṃnnirmitaṃ hṛdyaṃ kūṣmāṇḍakarasāyanam" },
      { type: "verse", number: "66", sanskrit: "पिवेन्नागबलामूलस्यार्धकर्षाभिवर्धितम् पलं क्षीरयुतं मासं क्षीरवृत्तिरनन्नभुक्", text: "pivennāgabalāmūlasyārdhakarṣābhivardhitam palaṃ kṣīrayutaṃ māsaṃ kṣīravṛttiranannabhuk" },
      { type: "verse", number: "67", sanskrit: "एष प्रयोगः पुष्ट्यायुर्बलवर्णकरः परम् मण्डूकपर्ण्याः कल्पो ऽयं यष्ट्या वित्तौषधस्य च", text: "eṣa prayogaḥ puṣṭyāyurbalavarṇakaraḥ param maṇḍūkaparṇyāḥ kalpo 'yaṃ yaṣṭyā vittauṣadhasya ca" },
      { type: "verse", number: "68", sanskrit: "पादशेषं जलद्रोणे पचेन्नागबलातुलाम् तेन क्वाथेन तुल्यांशं घृतं क्षीरं च साधयेत्", text: "pādaśeṣaṃ jaladroṇe pacennāgabalātulām tena kvāthena tulyāṃśaṃ ghṛtaṃ kṣīraṃ ca sādhayet" },
      { type: "verse", number: "69", sanskrit: "पलार्धिकैश्चातिबलाबलायष्टीपुनर्नवैः प्रपौण्डरीककाश्मर्यप्रियालकपिकच्छुभिः", text: "palārdhikaiścātibalābalāyaṣṭīpunarnavaiḥ prapauṇḍarīkakāśmaryapriyālakapikacchubhiḥ" },
      { type: "verse", number: "70", sanskrit: "अश्वगन्धासिताभीरुमेदायुग्मत्रिकण्टकैः काकोलीक्षीरकाकोलीक्षीरशुक्लाद्विजीरकैः", text: "aśvagandhāsitābhīrumedāyugmatrikaṇṭakaiḥ kākolīkṣīrakākolīkṣīraśuklādvijīrakaiḥ" },
      { type: "verse", number: "71", sanskrit: "मृणालबिसखर्जूरशृङ्गाटककशेरुकैः एतन्नागबलासर्पिः पित्तरक्तं क्षतक्षयम्", text: "mṛṇālabisakharjūraśṛṅgāṭakakaśerukaiḥ etannāgabalāsarpiḥ pittaraktaṃ kṣatakṣayam" },
      { type: "verse", number: "72", sanskrit: "जयेत्तृड्भ्रमदाहांश्च बलपुष्टिकरं परम् वर्ण्यमायुष्यमोजस्यं वलीपलितनाशनम् उपयुज्य तु षण्मासाद् वृद्धो ऽपि तरुणायते", text: "jayettṛḍbhramadāhāṃśca balapuṣṭikaraṃ param varṇyamāyuṣyamojasyaṃ valīpalitanāśanam upayujya tu ṣaṇmāsād vṛddho 'pi taruṇāyate" },
      { type: "verse", number: "73", sanskrit: "शर्करा पिप्पलीचूर्णैः सर्पिषा माक्षिकेण च संयुतं वा शृतं क्षीरं पिबेत् कासज्वरापहम्", text: "śarkarā pippalīcūrṇaiḥ sarpiṣā mākṣikeṇa ca saṃyutaṃ vā śṛtaṃ kṣīraṃ pibet kāsajvarāpaham" },
      { type: "verse", number: "74", sanskrit: "फलाम्लं सर्पिषा भृष्टं विदारीक्षुरसे कृतम् स्त्रीषु क्षीणः पिबेद्यूषं जीवनं बृंहणं परम्", text: "phalāmlaṃ sarpiṣā bhṛṣṭaṃ vidārīkṣurase kṛtam strīṣu kṣīṇaḥ pibedyūṣaṃ jīvanaṃ bṛṃhaṇaṃ param" },
      { type: "verse", number: "75", sanskrit: "सक्तूनां वस्त्रपूतानां मन्थं क्षौद्रघृतावितम् यवान्नसात्म्यो दीप्ताग्निः क्षतक्षीणः पिबेन्नरः", text: "saktūnāṃ vastrapūtānāṃ manthaṃ kṣaudraghṛtāvitam yavānnasātmyo dīptāgniḥ kṣatakṣīṇaḥ pibennaraḥ" },
      { type: "verse", number: "76", sanskrit: "जीवनीयोपसिद्धं वा जाङ्गलं घृतभर्जितम् रसं प्रयोजयेत् क्षीणे व्यञ्जनार्थं सशर्करम्", text: "jīvanīyopasiddhaṃ vā jāṅgalaṃ ghṛtabharjitam rasaṃ prayojayet kṣīṇe vyañjanārthaṃ saśarkaram" },
      { type: "verse", number: "77", sanskrit: "गोमहिष्यश्वनागाजैः क्षीरैर्मांससैस्तथा यवान्नं भोजयेद्यूषैः फलाम्लैर्वा घृताप्लुतैः", text: "gomahiṣyaśvanāgājaiḥ kṣīrairmāṃsasaistathā yavānnaṃ bhojayedyūṣaiḥ phalāmlairvā ghṛtāplutaiḥ" },
      { type: "verse", number: "78", sanskrit: "दीप्ते ऽग्नौ विधिरेष स्यान्मन्दे दीपनपाचनः यक्ष्मोक्तः क्षतिनां शस्तो ग्राही शकृति तु द्रवे", text: "dīpte 'gnau vidhireṣa syānmande dīpanapācanaḥ yakṣmoktaḥ kṣatināṃ śasto grāhī śakṛti tu drave" },
      { type: "verse", number: "79", sanskrit: "दशमूलं स्वयंगुप्तां शंखपुष्पीं शठीं बलाम् हस्तिपिप्पल्यपामार्गपिप्पलीमूलचित्रकान्", text: "daśamūlaṃ svayaṃguptāṃ śaṃkhapuṣpīṃ śaṭhīṃ balām hastipippalyapāmārgapippalīmūlacitrakān" },
      { type: "verse", number: "80", sanskrit: "भार्ङ्गी पुष्करमूलं च द्विपलांशान्यवाढकम् हरीतकीशतं चैकं जलपञ्चाढके पचेत्", text: "bhārṅgī puṣkaramūlaṃ ca dvipalāṃśānyavāḍhakam harītakīśataṃ caikaṃ jalapañcāḍhake pacet" },
      { type: "verse", number: "81", sanskrit: "यवस्वेदे कषायं तं पूतं तच्चाभयाशतम् पचेद्गुडतुलां दत्वा कुडवं च पृथग्घृतात्", text: "yavasvede kaṣāyaṃ taṃ pūtaṃ taccābhayāśatam pacedguḍatulāṃ datvā kuḍavaṃ ca pṛthagghṛtāt" },
      { type: "verse", number: "82", sanskrit: "तैलात् सपिप्पलीचूर्णात् सिद्धशीते च माक्षिकात् लेहाद्द्वे चाभये नित्यमतः खादेद्रसायनात्", text: "tailāt sapippalīcūrṇāt siddhaśīte ca mākṣikāt lehāddve cābhaye nityamataḥ khādedrasāyanāt" },
      { type: "verse", number: "83", sanskrit: "तद्वलीपलितं हन्याद्वर्णायुर्बलवर्धनम् पञ्चकासान् क्षयं श्वासं सहिध्मं विषमज्वरम्", text: "tadvalīpalitaṃ hanyādvarṇāyurbalavardhanam pañcakāsān kṣayaṃ śvāsaṃ sahidhmaṃ viṣamajvaram" },
      { type: "verse", number: "84", sanskrit: "मेहगुल्मग्रहण्यर्शोहृद्रोगरुचिपीनसान् अगस्त्यविहितं धन्यमिदं श्रेष्ठं रसायनम्", text: "mehagulmagrahaṇyarśohṛdrogarucipīnasān agastyavihitaṃ dhanyamidaṃ śreṣṭhaṃ rasāyanam" },
      { type: "verse", number: "85", sanskrit: "दशमूलं बलां मूर्वां हरिद्रे पिप्पलीद्वयम् पाठाश्वगन्धापामार्गस्वगुप्तातिविषामृताः", text: "daśamūlaṃ balāṃ mūrvāṃ haridre pippalīdvayam pāṭhāśvagandhāpāmārgasvaguptātiviṣāmṛtāḥ" },
      { type: "verse", number: "86", sanskrit: "बालबिल्वं त्रिवृद्दन्तीमूलं पत्रं च चित्रकात् पयस्यां कुटजं हिंस्रां पुष्पं सारं च बीजकात्", text: "bālabilvaṃ trivṛddantīmūlaṃ patraṃ ca citrakāt payasyāṃ kuṭajaṃ hiṃsrāṃ puṣpaṃ sāraṃ ca bījakāt" },
      { type: "verse", number: "87", sanskrit: "बोलस्थविरभल्लातविकङ्कतशतावरीः पूतीकरञ्जशम्याकचन्द्रलेखासहाचरम्", text: "bolasthavirabhallātavikaṅkataśatāvarīḥ pūtīkarañjaśamyākacandralekhāsahācaram" },
      { type: "verse", number: "88", sanskrit: "सौभाञ्जनकनिम्बत्वगिक्षुरं च पलांशकम् पथ्यासहस्रं सशतं यवानां चाढकद्वयम्", text: "saubhāñjanakanimbatvagikṣuraṃ ca palāṃśakam pathyāsahasraṃ saśataṃ yavānāṃ cāḍhakadvayam" },
      { type: "verse", number: "89", sanskrit: "पचेदष्टगुणे तोये यवस्वेदे ऽवतारयेत् पूते क्षिपेत् सपथ्ये च तत्र जीर्णगुडात्तुलाम्", text: "pacedaṣṭaguṇe toye yavasvede 'vatārayet pūte kṣipet sapathye ca tatra jīrṇaguḍāttulām" },
      { type: "verse", number: "90", sanskrit: "तैलाज्यधात्रीरसतः प्रस्थं प्रस्थं ततः पुनः अधिश्रयेन्मृदावग्नौ दर्वीलेपे ऽवतार्य च", text: "tailājyadhātrīrasataḥ prasthaṃ prasthaṃ tataḥ punaḥ adhiśrayenmṛdāvagnau darvīlepe 'vatārya ca" },
      { type: "verse", number: "91", sanskrit: "शीते प्रस्थद्वयं क्षौद्रात् पिप्पलीकुडवं क्षिपेत् चूर्णीकृतात्त्रिजाताच्च त्रिपलं निखनेत्ततः", text: "śīte prasthadvayaṃ kṣaudrāt pippalīkuḍavaṃ kṣipet cūrṇīkṛtāttrijātācca tripalaṃ nikhanettataḥ" },
      { type: "verse", number: "92", sanskrit: "धान्ये पुराणकुम्भस्थं मासं खादेच्च पूर्ववत् रसायनं वसिष्ठोक्तमेतत् पूर्वगुणाधिकम् स्वस्थानां निष्परीहारं सर्वर्तुषु च शस्यते", text: "dhānye purāṇakumbhasthaṃ māsaṃ khādecca pūrvavat rasāyanaṃ vasiṣṭhoktametat pūrvaguṇādhikam svasthānāṃ niṣparīhāraṃ sarvartuṣu ca śasyate" },
      { type: "verse", number: "93", sanskrit: "पालिकं सैन्धवं शुण्ठी द्वे च सौवर्चलात् पले कुडवांशानि वृक्षाम्लं दाडिमं पत्रमार्जकात्", text: "pālikaṃ saindhavaṃ śuṇṭhī dve ca sauvarcalāt pale kuḍavāṃśāni vṛkṣāmlaṃ dāḍimaṃ patramārjakāt" },
      { type: "verse", number: "94", sanskrit: "एकैका मरिचाजाज्योर्धान्यकाद्वे चतुर्थिके शर्करायाः पलान्यत्र दश द्वे च प्रदापयेत्", text: "ekaikā maricājājyordhānyakādve caturthike śarkarāyāḥ palānyatra daśa dve ca pradāpayet" },
      { type: "verse", number: "95", sanskrit: "कृत्वा चूर्णमतो मात्रामन्नपानेषु दापयेत् रुच्यं तद्दीपनं बल्यं पार्श्वार्तिश्वासकासनुत्", text: "kṛtvā cūrṇamato mātrāmannapāneṣu dāpayet rucyaṃ taddīpanaṃ balyaṃ pārśvārtiśvāsakāsanut" },
      { type: "verse", number: "96", sanskrit: "एकां षोडशिकां धान्याद् द्वे द्वे चाजाजिदीप्यकात् ताभ्यां दाडिमवृक्षाम्ले द्विर्द्विस्सौवर्चलात् पले", text: "ekāṃ ṣoḍaśikāṃ dhānyād dve dve cājājidīpyakāt tābhyāṃ dāḍimavṛkṣāmle dvirdvissauvarcalāt pale" },
      { type: "verse", number: "97", sanskrit: "शुण्ठ्याः कर्षं दधित्थस्य मध्यात् पञ्चपलानि च तच्चूण षोडशपलैः शर्कराया विमिश्रयेत्", text: "śuṇṭhyāḥ karṣaṃ dadhitthasya madhyāt pañcapalāni ca taccūṇa ṣoḍaśapalaiḥ śarkarāyā vimiśrayet" },
      { type: "verse", number: "98", sanskrit: "षाडवोयं प्रदेयः स्यादन्नपानेषु पूर्ववत् विधिश्च यक्ष्मपित्तास्रविहितः शस्यते क्षते", text: "ṣāḍavoyaṃ pradeyaḥ syādannapāneṣu pūrvavat vidhiśca yakṣmapittāsravihitaḥ śasyate kṣate" },
      { type: "verse", number: "99", sanskrit: "निवृत्ते क्षतदोषे तु कफे वृद्ध उरः शिरः दाल्येते कासिनो यस्य स ना धूमानिमान्पिबेत्", text: "nivṛtte kṣatadoṣe tu kaphe vṛddha uraḥ śiraḥ dālyete kāsino yasya sa nā dhūmānimānpibet" },
      { type: "verse", number: "100", sanskrit: "द्विमेदाद्विबलायष्टीकल्कैः क्षौमे सुभाविते वर्तिं कृत्वा पिबेद्धूमं जीवनीयघृतानुपः", text: "dvimedādvibalāyaṣṭīkalkaiḥ kṣaume subhāvite vartiṃ kṛtvā pibeddhūmaṃ jīvanīyaghṛtānupaḥ" },
      { type: "verse", number: "101", sanskrit: "मनःशिला बला साजगन्धा त्वक्क्षीरिनागरैः तद्वदेवानुपानं तु शर्करेक्षुगुडोदकम्", text: "manaḥśilā balā sājagandhā tvakkṣīrināgaraiḥ tadvadevānupānaṃ tu śarkarekṣuguḍodakam" },
      { type: "verse", number: "102", sanskrit: "पिष्ट्वा मनःशिलां तुल्यामार्द्रया वटशुङ्गया ससर्पिष्कं पिबेद्धूमं तित्तिरिप्रतिभोजनः", text: "piṣṭvā manaḥśilāṃ tulyāmārdrayā vaṭaśuṅgayā sasarpiṣkaṃ pibeddhūmaṃ tittiripratibhojanaḥ" },
      { type: "verse", number: "103", sanskrit: "क्षयजे बृंहणं पूर्वं कुर्यादग्नेश्च वर्धनम् बहुदोषाय सस्नेहं मृदु दद्याद्विरेचनम्", text: "kṣayaje bṛṃhaṇaṃ pūrvaṃ kuryādagneśca vardhanam bahudoṣāya sasnehaṃ mṛdu dadyādvirecanam" },
      { type: "verse", number: "104", sanskrit: "शम्याकेन त्रिवृतया मृद्वीकारसयुक्तया तिल्वकस्य कषायेण विदारीस्वरसेन च सर्पिः सिद्धं पिबेद्युक्त्या क्षीणदेहो विशोधनम्", text: "śamyākena trivṛtayā mṛdvīkārasayuktayā tilvakasya kaṣāyeṇa vidārīsvarasena ca sarpiḥ siddhaṃ pibedyuktyā kṣīṇadeho viśodhanam" },
      { type: "verse", number: "105", sanskrit: "पित्ते कफे धातुषु च क्षीणेषु क्षयकासवान् घृतं कर्कटकीक्षीरद्विबलासाधितं पिबेत्", text: "pitte kaphe dhātuṣu ca kṣīṇeṣu kṣayakāsavān ghṛtaṃ karkaṭakīkṣīradvibalāsādhitaṃ pibet" },
      { type: "verse", number: "106", sanskrit: "विदारीभिः कदम्बैर्वा तालसस्यैश्च साधितम् घृतं पयश्च मूत्रस्य वैवर्ण्ये कृच्छ्रनिर्गमे", text: "vidārībhiḥ kadambairvā tālasasyaiśca sādhitam ghṛtaṃ payaśca mūtrasya vaivarṇye kṛcchranirgame" },
      { type: "verse", number: "107", sanskrit: "शूने सवेदने मेढ्रे पायौ सश्रोणिवङ्क्षणे घृतमण्डेन लघुनानुवास्यो मिश्रकेण वा", text: "śūne savedane meḍhre pāyau saśroṇivaṅkṣaṇe ghṛtamaṇḍena laghunānuvāsyo miśrakeṇa vā" },
      { type: "verse", number: "108", sanskrit: "जाङ्गलैः प्रतिभुक्तस्य वर्तकाद्या बिलेशयाः क्रमशः प्रसहास्तद्वत् प्रयोज्याः पिशिताशिनः", text: "jāṅgalaiḥ pratibhuktasya vartakādyā bileśayāḥ kramaśaḥ prasahāstadvat prayojyāḥ piśitāśinaḥ" },
      { type: "verse", number: "109", sanskrit: "औष्ण्यात् प्रमाथिभावाच्च स्रोतोभ्यश्च्यावयन्ति ते कफं शुद्धैश्च तैः पुष्टिं कुर्यात् सम्यग्वहन् रसः", text: "auṣṇyāt pramāthibhāvācca srotobhyaścyāvayanti te kaphaṃ śuddhaiśca taiḥ puṣṭiṃ kuryāt samyagvahan rasaḥ" },
      { type: "verse", number: "110", sanskrit: "चविकात्रिफलाभार्ङ्गीदशमूलैः सचित्रकैः कुलत्थपिप्पलीमूलपाठाकोलयवैर्जले", text: "cavikātriphalābhārṅgīdaśamūlaiḥ sacitrakaiḥ kulatthapippalīmūlapāṭhākolayavairjale" },
      { type: "verse", number: "111", sanskrit: "शृतैर्नागरदुस्पर्शापिप्पलीशठिपौष्करैः पिष्टैः कर्कटशृङ्ग्या च समैः सर्पिर्विपाचयेत्", text: "śṛtairnāgaradusparśāpippalīśaṭhipauṣkaraiḥ piṣṭaiḥ karkaṭaśṛṅgyā ca samaiḥ sarpirvipācayet" },
      { type: "verse", number: "112", sanskrit: "सिद्धे ऽस्मिंश्चूर्णितौ क्षारौ द्वौ पञ्च लवणानि च दत्वा युक्त्या पिबेन्मात्रां क्षयकासनिपीडितः", text: "siddhe 'smiṃścūrṇitau kṣārau dvau pañca lavaṇāni ca datvā yuktyā pibenmātrāṃ kṣayakāsanipīḍitaḥ" },
      { type: "verse", number: "113", sanskrit: "कासमर्दाभयामुस्तापाठाकट्फलनागरैः पिप्पल्या कटुरोहिण्या काश्मर्या सुरसेन च", text: "kāsamardābhayāmustāpāṭhākaṭphalanāgaraiḥ pippalyā kaṭurohiṇyā kāśmaryā surasena ca" },
      { type: "verse", number: "114", sanskrit: "अक्षमात्रैर्घृतप्रस्थं क्षीरद्राक्षारसाढके पचेच्छोषज्वरप्लीहसर्वकासहरं शिवम्", text: "akṣamātrairghṛtaprasthaṃ kṣīradrākṣārasāḍhake pacecchoṣajvaraplīhasarvakāsaharaṃ śivam" },
      { type: "verse", number: "115", sanskrit: "वृषव्याघ्रीगुडूचीनां पत्रमूलफलाङ्कुरात् रसकल्कैर्घृतं पक्वं हन्ति कासज्वरारुचीः", text: "vṛṣavyāghrīguḍūcīnāṃ patramūlaphalāṅkurāt rasakalkairghṛtaṃ pakvaṃ hanti kāsajvarārucīḥ" },
      { type: "verse", number: "116", sanskrit: "द्विगुणे दाडिमरसे सिद्धं वा व्योषसंयुतम् पिबेदुपरिभक्तस्य यवक्षारयुतं नरः", text: "dviguṇe dāḍimarase siddhaṃ vā vyoṣasaṃyutam pibeduparibhaktasya yavakṣārayutaṃ naraḥ" },
      { type: "verse", number: "117", sanskrit: "पिप्पलीनुडसिद्धं वा छागक्षीरयुतं घृतम् एतान्यग्निविवृध्यर्थं सर्पीषि क्षयकासिनाम् स्युर्दोषबद्धकण्ठोरःस्रोतसां च विशुद्धये", text: "pippalīnuḍasiddhaṃ vā chāgakṣīrayutaṃ ghṛtam etānyagnivivṛdhyarthaṃ sarpīṣi kṣayakāsinām syurdoṣabaddhakaṇṭhoraḥsrotasāṃ ca viśuddhaye" },
      { type: "verse", number: "118", sanskrit: "श्वाविदां सूचयो दग्धाः सघृतक्षौद्रशर्कराः श्वासकासहरा बर्हिपादौ वा क्षौद्रसर्पिषा", text: "śvāvidāṃ sūcayo dagdhāḥ saghṛtakṣaudraśarkarāḥ śvāsakāsaharā barhipādau vā kṣaudrasarpiṣā" },
      { type: "verse", number: "119", sanskrit: "एरण्डपत्रक्षारं वा व्योषतैलगुडान्वितम् लेहयेत् क्षारमेवं वा सुरसैरण्डपत्रजम्", text: "eraṇḍapatrakṣāraṃ vā vyoṣatailaguḍānvitam lehayet kṣāramevaṃ vā surasairaṇḍapatrajam" },
      { type: "verse", number: "120", sanskrit: "लिह्यात्त्र्यूषणचूर्णं वा पुराणगुडसर्पिषा चित्रकत्रिफलाजाजी कर्कटाख्या कटुत्रिकम् द्राक्षां च क्षौद्रसर्पिर्भ्यां लिह्यादद्याद्गुडेन वा", text: "lihyāttryūṣaṇacūrṇaṃ vā purāṇaguḍasarpiṣā citrakatriphalājājī karkaṭākhyā kaṭutrikam drākṣāṃ ca kṣaudrasarpirbhyāṃ lihyādadyādguḍena vā" },
      { type: "verse", number: "121", sanskrit: "पाठामधुकजीवन्तीत्वक्क्षीरीत्रिफलाघनम् शठीद्विबृहतीद्राक्षापिप्पल्येलावितुन्नकम्", text: "pāṭhāmadhukajīvantītvakkṣīrītriphalāghanam śaṭhīdvibṛhatīdrākṣāpippalyelāvitunnakam" },
      { type: "verse", number: "122", sanskrit: "सारिवापुष्करजटाकर्कटाख्यारसाञ्जनम् पुनर्नवालोहरजस्त्रायमाणायवानिका", text: "sārivāpuṣkarajaṭākarkaṭākhyārasāñjanam punarnavāloharajastrāyamāṇāyavānikā" },
      { type: "verse", number: "123", sanskrit: "ऋद्धिस्तामलकी भार्ङ्गी विडङ्गं धन्वयासकम् क्षारचित्रकचव्याम्लवेतसव्योषदारु च सर्वकासान् जयेल्लीढं तच्चूर्णं मधुसर्पिषा", text: "ṛddhistāmalakī bhārṅgī viḍaṅgaṃ dhanvayāsakam kṣāracitrakacavyāmlavetasavyoṣadāru ca sarvakāsān jayellīḍhaṃ taccūrṇaṃ madhusarpiṣā" },
      { type: "verse", number: "124", sanskrit: "पद्मकं त्रिफला व्योषं विडङ्गं देवदारु च बलारास्ना च तच्चूर्णं समस्तसमशर्करम्", text: "padmakaṃ triphalā vyoṣaṃ viḍaṅgaṃ devadāru ca balārāsnā ca taccūrṇaṃ samastasamaśarkaram" },
      { type: "verse", number: "125", sanskrit: "स्वादेन्मधुघृताभ्यां वा लिह्यात् कासहरं परम् तद्वन्मारिचचूर्णं वा सघृतक्षौद्रशर्करम्", text: "svādenmadhughṛtābhyāṃ vā lihyāt kāsaharaṃ param tadvanmāricacūrṇaṃ vā saghṛtakṣaudraśarkaram" },
      { type: "verse", number: "126", sanskrit: "पथ्याशुण्ठीघनगुदैर्गुटिकां धारयेन्मुखे सर्वेषु कासश्वासेषु केवलं वा बिभीतकम्", text: "pathyāśuṇṭhīghanagudairguṭikāṃ dhārayenmukhe sarveṣu kāsaśvāseṣu kevalaṃ vā bibhītakam" },
      { type: "verse", number: "127", sanskrit: "कल्के तिल्वकपत्राणां घृतभृष्टे सशर्करे पेयोत्कार्यथवा च्छर्दितृट्कासामातिसारजित्", text: "kalke tilvakapatrāṇāṃ ghṛtabhṛṣṭe saśarkare peyotkāryathavā ccharditṛṭkāsāmātisārajit" },
      { type: "verse", number: "128", sanskrit: "गौरसर्षपगण्डीरविडङ्गव्योषचित्रकान् साभयान् साधयेत्तोये यवागूस्तेन चाम्भसा", text: "gaurasarṣapagaṇḍīraviḍaṅgavyoṣacitrakān sābhayān sādhayettoye yavāgūstena cāmbhasā" },
      { type: "verse", number: "129", sanskrit: "ससर्पिर्लवणा कासे हिध्माश्वासे सपीनसे पाण्ड्वामये क्षये शोफे कर्णशूले च शस्यते", text: "sasarpirlavaṇā kāse hidhmāśvāse sapīnase pāṇḍvāmaye kṣaye śophe karṇaśūle ca śasyate" },
      { type: "verse", number: "130", sanskrit: "कण्टकारीरसे सिद्धो मुद्गयूषः सुसंस्कृतः सगौरामलकः साम्लः सर्वकासभिषग्जितम्", text: "kaṇṭakārīrase siddho mudgayūṣaḥ susaṃskṛtaḥ sagaurāmalakaḥ sāmlaḥ sarvakāsabhiṣagjitam" },
      { type: "verse", number: "131", sanskrit: "वातघ्नौषधनिःक्वाथे क्षीरं यूषान् रसानपि वैष्किरान् प्रातुदान् बैलान् दापयेत् क्षयकासिने", text: "vātaghnauṣadhaniḥkvāthe kṣīraṃ yūṣān rasānapi vaiṣkirān prātudān bailān dāpayet kṣayakāsine" },
      { type: "verse", number: "132", sanskrit: "क्षतकासे च ये धूमाः सानुपाना निदर्शिताः क्षयकासे ऽपि ते योज्या वक्ष्यते यच्च यक्ष्मणि", text: "kṣatakāse ca ye dhūmāḥ sānupānā nidarśitāḥ kṣayakāse 'pi te yojyā vakṣyate yacca yakṣmaṇi" },
      { type: "verse", number: "133", sanskrit: "बृंहणं दीपनं चाग्नेः स्रोतसां च विशोधनम् व्यत्यासात् क्षयकासिभ्यो बल्यं सर्वं प्रशस्यते", text: "bṛṃhaṇaṃ dīpanaṃ cāgneḥ srotasāṃ ca viśodhanam vyatyāsāt kṣayakāsibhyo balyaṃ sarvaṃ praśasyate" },
      { type: "verse", number: "134", sanskrit: "सन्निपातोद्भवो घोरः क्षयकासो यतस्ततः यथादोषबलं तस्य सन्निपातहितं हितम्", text: "sannipātodbhavo ghoraḥ kṣayakāso yatastataḥ yathādoṣabalaṃ tasya sannipātahitaṃ hitam" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 6,
    lang: "sa",
    content: [
      { type: "heading", heading: "Прамеха чикитса — лечение диабета" },
      { type: "text", text: "Глава 6 Чикитса стханы — лечебный раздел о лечение диабета. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातः श्वासहिध्माचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ śvāsahidhmācikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "श्वासहिध्मा यतस्तुल्यहेत्वाद्याः साधनं ततः तुल्यमेव तदार्तं च पूर्वं स्वेदैरुपाचरेत्", text: "śvāsahidhmā yatastulyahetvādyāḥ sādhanaṃ tataḥ tulyameva tadārtaṃ ca pūrvaṃ svedairupācaret" },
      { type: "verse", number: "3", sanskrit: "स्निग्धैर्लवणतैलाक्तं स्रोतस्सु ग्रथितः कफः तैर्लीनो ऽपि विलीनोस्य कोष्ठं प्राप्तः सुनिर्हरः", text: "snigdhairlavaṇatailāktaṃ srotassu grathitaḥ kaphaḥ tairlīno 'pi vilīnosya koṣṭhaṃ prāptaḥ sunirharaḥ" },
      { type: "verse", number: "4", sanskrit: "भवेत् खेषु मृदुत्वं च मारुते चानुलोमता स्विन्नं च भोजयेदन्नं स्निग्धमानूपजै रसैः", text: "bhavet kheṣu mṛdutvaṃ ca mārute cānulomatā svinnaṃ ca bhojayedannaṃ snigdhamānūpajai rasaiḥ" },
      { type: "verse", number: "5", sanskrit: "दध्युत्तरेण वा दद्यात्ततो ऽस्मै वमनं मृदु विशेषात् कासवमथुहृद्ग्रहस्वरसादिने", text: "dadhyuttareṇa vā dadyāttato 'smai vamanaṃ mṛdu viśeṣāt kāsavamathuhṛdgrahasvarasādine" },
      { type: "verse", number: "6", sanskrit: "पिप्पलीसैन्धवक्षौद्रयुक्तं वाताविरोधि यत् निर्हृते सुखमाप्रोति सकफे दुष्टविग्रहे", text: "pippalīsaindhavakṣaudrayuktaṃ vātāvirodhi yat nirhṛte sukhamāproti sakaphe duṣṭavigrahe" },
      { type: "verse", number: "7", sanskrit: "स्रोतःसु च विशुद्धेषु चरत्यविहतो ऽनिलः ध्मानोदावर्ततमके मातुलुङ्गाम्लवेतसैः", text: "srotaḥsu ca viśuddheṣu caratyavihato 'nilaḥ dhmānodāvartatamake mātuluṅgāmlavetasaiḥ" },
      { type: "verse", number: "8", sanskrit: "हिङ्गुपीलुबिडयुक्तमन्नं स्यादनुलोमनम् ससैधवं फलाम्लं वा कोष्णं दद्याद्विरेचनम्", text: "hiṅgupīlubiḍayuktamannaṃ syādanulomanam sasaidhavaṃ phalāmlaṃ vā koṣṇaṃ dadyādvirecanam" },
      { type: "verse", number: "9", sanskrit: "एते हि कफसंरुद्धगतिप्राणप्रकोपजाः तस्मात्तन्मार्गशुध्यर्थमूर्ध्वाधः शोधनं हितम्", text: "ete hi kaphasaṃruddhagatiprāṇaprakopajāḥ tasmāttanmārgaśudhyarthamūrdhvādhaḥ śodhanaṃ hitam" },
      { type: "verse", number: "10", sanskrit: "उदीर्यते भृशतरं मार्गरोधाद्वहज्जलम् यथा तथानिलस्तस्य मार्गमस्माद्विशोधयेत्", text: "udīryate bhṛśataraṃ mārgarodhādvahajjalam yathā tathānilastasya mārgamasmādviśodhayet" },
      { type: "verse", number: "11", sanskrit: "अशान्तौ कृतसंशुद्धेर्धूमैर्लीनं मलं हरेत् हरिद्रापत्रमेरण्मूलं लाक्षां मनःशिलाम्", text: "aśāntau kṛtasaṃśuddherdhūmairlīnaṃ malaṃ haret haridrāpatrameraṇmūlaṃ lākṣāṃ manaḥśilām" },
      { type: "verse", number: "12", sanskrit: "सदेवदार्वलं मांसीं पिष्ट्वा वर्तिं प्रकल्पयेत् तां घृताक्तां पिबेद्धूमं यवान् वा घृतसंयुतान्", text: "sadevadārvalaṃ māṃsīṃ piṣṭvā vartiṃ prakalpayet tāṃ ghṛtāktāṃ pibeddhūmaṃ yavān vā ghṛtasaṃyutān" },
      { type: "verse", number: "13", sanskrit: "मधूच्छिष्टं सर्जरसं घृतं वा गुरुवागुरु चन्दनंवाजशृङ्गं वा बालान्वा स्नाव वा गवाम्", text: "madhūcchiṣṭaṃ sarjarasaṃ ghṛtaṃ vā guruvāguru candanaṃvājaśṛṅgaṃ vā bālānvā snāva vā gavām" },
      { type: "verse", number: "14", sanskrit: "ऋष्यगोधकुरङ्गैणचर्मशृङ्गखुराणि वा गुग्गुलुं वा मनोह्वां वा सालनिर्यासमेव वा", text: "ṛṣyagodhakuraṅgaiṇacarmaśṛṅgakhurāṇi vā gugguluṃ vā manohvāṃ vā sālaniryāsameva vā" },
      { type: "verse", number: "15", sanskrit: "सल्लकीं गुग्गुलुं लोहं पद्मकं च घृताप्लुतम्", text: "sallakīṃ gugguluṃ lohaṃ padmakaṃ ca ghṛtāplutam" },
      { type: "verse", number: "16", sanskrit: "अवश्यं स्वेदनीयानामस्वेद्यानामपि क्षणम् स्वेदयेत् ससिताक्षीरसुखोष्णस्नेहसेचनैः", text: "avaśyaṃ svedanīyānāmasvedyānāmapi kṣaṇam svedayet sasitākṣīrasukhoṣṇasnehasecanaiḥ" },
      { type: "verse", number: "17", sanskrit: "उत्कारिकोपनाहैश्च स्वेदाध्यायोक्तभेषजैः उरः कण्ठं च मृदुभिः सामे त्वामविधिं चरेत्", text: "utkārikopanāhaiśca svedādhyāyoktabheṣajaiḥ uraḥ kaṇṭhaṃ ca mṛdubhiḥ sāme tvāmavidhiṃ caret" },
      { type: "verse", number: "18", sanskrit: "अतियोगोद्धतं वातं दृष्ट्वा पवननाशनैः स्निग्धै रसाद्यैर्नात्युष्णैरभ्यङ्गैश्च शमं नयेत्", text: "atiyogoddhataṃ vātaṃ dṛṣṭvā pavananāśanaiḥ snigdhai rasādyairnātyuṣṇairabhyaṅgaiśca śamaṃ nayet" },
      { type: "verse", number: "19", sanskrit: "अनुत्क्लिष्टकफास्विन्नदुर्बलानां हि शोधनात् वायुर्लब्धास्पदो मर्म संशोष्याशु हरेदसून्", text: "anutkliṣṭakaphāsvinnadurbalānāṃ hi śodhanāt vāyurlabdhāspado marma saṃśoṣyāśu haredasūn" },
      { type: "verse", number: "20", sanskrit: "कषायलेहस्नेहाद्यैस्तेषां संशमयेदतः क्षीणक्षतातिसारासृक्पित्तदाहानुबन्धजान्", text: "kaṣāyalehasnehādyaisteṣāṃ saṃśamayedataḥ kṣīṇakṣatātisārāsṛkpittadāhānubandhajān" },
      { type: "verse", number: "21", sanskrit: "मधुरस्निग्धशीताद्यैर्हिध्माश्वासानुपाचरेत् कुलत्थदशमूलानां क्वाथे स्युर्जाङ्गला रसाः यूषाश्च शिग्रुवार्ताककासघ्नवृषमूलकैः", text: "madhurasnigdhaśītādyairhidhmāśvāsānupācaret kulatthadaśamūlānāṃ kvāthe syurjāṅgalā rasāḥ yūṣāśca śigruvārtākakāsaghnavṛṣamūlakaiḥ" },
      { type: "verse", number: "22", sanskrit: "पल्लवैर्निम्बकुलकबृहतीमातुलुङ्गजैः व्याघ्रीदुरालभाशृङ्गीबिल्वमध्यत्रिकण्टकैः", text: "pallavairnimbakulakabṛhatīmātuluṅgajaiḥ vyāghrīdurālabhāśṛṅgībilvamadhyatrikaṇṭakaiḥ" },
      { type: "verse", number: "23", sanskrit: "सामृताग्निकुलत्थैश्च यूषः स्यात् क्वथितैर्जलै तद्वद्रास्नाबृहत्यादिबलामुद्गैः सचित्रकैः", text: "sāmṛtāgnikulatthaiśca yūṣaḥ syāt kvathitairjalai tadvadrāsnābṛhatyādibalāmudgaiḥ sacitrakaiḥ" },
      { type: "verse", number: "24", sanskrit: "पेया च चित्रकाजाजीशृङ्गीसौवर्चलैर्हिता दशमूलेन वा कासश्वासहिध्मारुजापहा", text: "peyā ca citrakājājīśṛṅgīsauvarcalairhitā daśamūlena vā kāsaśvāsahidhmārujāpahā" },
      { type: "verse", number: "25", sanskrit: "दशमूलशठीरास्नाभार्ङ्गीबिल्वर्धिपौष्करैः कुलीरशृङ्गीचपलातामलक्यमृतौषधैः", text: "daśamūlaśaṭhīrāsnābhārṅgībilvardhipauṣkaraiḥ kulīraśṛṅgīcapalātāmalakyamṛtauṣadhaiḥ" },
      { type: "verse", number: "26", sanskrit: "पिबेत् कषायं जीर्णे ऽस्मिन् पेयां तैरेवसाधिताम् शालिषष्टिकगोधूमयवमुद्गकुलत्थभुक्", text: "pibet kaṣāyaṃ jīrṇe 'smin peyāṃ tairevasādhitām śāliṣaṣṭikagodhūmayavamudgakulatthabhuk" },
      { type: "verse", number: "27", sanskrit: "कासहृद्ग्रहपार्श्वार्तिहिध्माश्वासप्रशान्तये सक्तून्वार्काङ्कुरक्षीरभावितानां समाक्षिकान् यवानां दशमूलादिनिःक्वाथलुलितान् पिबेत्", text: "kāsahṛdgrahapārśvārtihidhmāśvāsapraśāntaye saktūnvārkāṅkurakṣīrabhāvitānāṃ samākṣikān yavānāṃ daśamūlādiniḥkvāthalulitān pibet" },
      { type: "verse", number: "28", sanskrit: "अन्ने च योजयेत् क्षारहिङ्वाज्यबिडदाडिमान् सपौष्करशठीव्योषमातुलुङ्गाम्लवेतसान्", text: "anne ca yojayet kṣārahiṅvājyabiḍadāḍimān sapauṣkaraśaṭhīvyoṣamātuluṅgāmlavetasān" },
      { type: "verse", number: "29", sanskrit: "दशमूलस्य वा क्वाथमथवा देवदारुणः पिबेद्वा वारुणीमण्डं हिध्माश्वासी पिपासितः", text: "daśamūlasya vā kvāthamathavā devadāruṇaḥ pibedvā vāruṇīmaṇḍaṃ hidhmāśvāsī pipāsitaḥ" },
      { type: "verse", number: "30", sanskrit: "पिप्पलीपिप्पलीमूलपथ्याजन्तुघ्नचित्रकैः कल्कितैर्लेपिते रूढे निक्षिपेत् घृतभाजने", text: "pippalīpippalīmūlapathyājantughnacitrakaiḥ kalkitairlepite rūḍhe nikṣipet ghṛtabhājane" },
      { type: "verse", number: "31", sanskrit: "तक्रं मासस्थितं तद्धि दीपनं श्वासकासजित् पाठां मधुरसां दारु सरलं च निशि स्थितम्", text: "takraṃ māsasthitaṃ taddhi dīpanaṃ śvāsakāsajit pāṭhāṃ madhurasāṃ dāru saralaṃ ca niśi sthitam" },
      { type: "verse", number: "32", sanskrit: "सुरामण्डे ऽल्पलवणं पिबेत् प्रसृतसम्मितम् शिरीषकुन्दकदलीकुसुमं पिप्पलीयुतम्", text: "surāmaṇḍe 'lpalavaṇaṃ pibet prasṛtasammitam śirīṣakundakadalīkusumaṃ pippalīyutam" },
      { type: "verse", number: "33", sanskrit: "तण्डुलाम्बुप्लुतं हिध्माश्वासकासहरं परम् आरनालेन पिष्ट्वा वा मातुलुङ्गरसान्वितान्", text: "taṇḍulāmbuplutaṃ hidhmāśvāsakāsaharaṃ param āranālena piṣṭvā vā mātuluṅgarasānvitān" },
      { type: "verse", number: "34", sanskrit: "हिङ्गुसौवर्चलकणाकोलमुद्गान् जलेन वा कोष्णेन भार्ङ्गीं शुण्ठीं च क्षारं वा मरिचान्वितम्", text: "hiṅgusauvarcalakaṇākolamudgān jalena vā koṣṇena bhārṅgīṃ śuṇṭhīṃ ca kṣāraṃ vā maricānvitam" },
      { type: "verse", number: "35", sanskrit: "स्वक्वाथपिष्टां लुलितां बाष्पिकां पाययेत वा स्वरसं सप्तपर्णस्य पुष्पाणां वा शिरीषतः", text: "svakvāthapiṣṭāṃ lulitāṃ bāṣpikāṃ pāyayeta vā svarasaṃ saptaparṇasya puṣpāṇāṃ vā śirīṣataḥ" },
      { type: "verse", number: "36", sanskrit: "हिध्वाश्वासे मधुकणायुक्तं पित्तकफानुगे उत्कारिका तुगाकृष्णामधूलीगुडनागरैः", text: "hidhvāśvāse madhukaṇāyuktaṃ pittakaphānuge utkārikā tugākṛṣṇāmadhūlīguḍanāgaraiḥ" },
      { type: "verse", number: "37", sanskrit: "पित्तानुबन्धे योक्तव्या पवने त्वनुबन्धिनि श्वाविट्छशामिषकणाघृतशल्यकशोणितैः", text: "pittānubandhe yoktavyā pavane tvanubandhini śvāviṭchaśāmiṣakaṇāghṛtaśalyakaśoṇitaiḥ" },
      { type: "verse", number: "38", sanskrit: "सुवर्चलारसव्योषसर्पिर्भिः सहितं पयः अनुशाल्योदनं पेयं वातपित्ते ऽनुबन्धिनि", text: "suvarcalārasavyoṣasarpirbhiḥ sahitaṃ payaḥ anuśālyodanaṃ peyaṃ vātapitte 'nubandhini" },
      { type: "verse", number: "39", sanskrit: "चतुर्गुणाम्बुसिद्धं वा छागं सगुडनागरम् पिप्पलीमूलमधुकगुडगोश्वशकृद्रसान् हिध्माभिष्यन्दकासघ्नान् लिह्यान्मधुघृतान्वितान्", text: "caturguṇāmbusiddhaṃ vā chāgaṃ saguḍanāgaram pippalīmūlamadhukaguḍagośvaśakṛdrasān hidhmābhiṣyandakāsaghnān lihyānmadhughṛtānvitān" },
      { type: "verse", number: "40", sanskrit: "गोगजाश्ववराहोष्ट्रखरमेषाजविड्रसान्", text: "gogajāśvavarāhoṣṭrakharameṣājaviḍrasān" },
      { type: "verse", number: "41", sanskrit: "समध्वैकैकशो लिह्याद्बहुश्लेष्माथवा पिबेत् चतुष्पाच्चर्मरोमस्थिखुरशृङ्गोद्भवां मषीम्", text: "samadhvaikaikaśo lihyādbahuśleṣmāthavā pibet catuṣpāccarmaromasthikhuraśṛṅgodbhavāṃ maṣīm" },
      { type: "verse", number: "42", sanskrit: "तथैव वाजिगन्धाया लिह्याच्छ्वासी कफोल्बणः क्षारं वा त्रिफलापाठाबृहतीफलमूलजम्", text: "tathaiva vājigandhāyā lihyācchvāsī kapholbaṇaḥ kṣāraṃ vā triphalāpāṭhābṛhatīphalamūlajam" },
      { type: "verse", number: "43", sanskrit: "मुक्ताप्रवालवैडूर्यशङ्खसौगन्धिकाञ्जनम् मसारगल्लस्फटिककाचैलालवणद्वयम्", text: "muktāpravālavaiḍūryaśaṅkhasaugandhikāñjanam masāragallasphaṭikakācailālavaṇadvayam" },
      { type: "verse", number: "44", sanskrit: "अपामार्गफलं ताम्रमयो रूप्यं शणात् फलम् ज्योतीरसेन तल्लिह्यादयो वैकं मधुद्रवम्", text: "apāmārgaphalaṃ tāmramayo rūpyaṃ śaṇāt phalam jyotīrasena tallihyādayo vaikaṃ madhudravam" },
      { type: "verse", number: "45", sanskrit: "शठीपौष्करधात्रीर्वा पौष्करं वा कणान्वितम् गैरिकाञ्जनकृष्णा वा स्वरसं वा कपित्थजम्", text: "śaṭhīpauṣkaradhātrīrvā pauṣkaraṃ vā kaṇānvitam gairikāñjanakṛṣṇā vā svarasaṃ vā kapitthajam" },
      { type: "verse", number: "46", sanskrit: "रसेन वा कपित्थस्य धात्रीसैन्धवपिप्पलीः घृतक्षौद्रेण वा पथ्या विडङ्गोषणपिप्पलीः", text: "rasena vā kapitthasya dhātrīsaindhavapippalīḥ ghṛtakṣaudreṇa vā pathyā viḍaṅgoṣaṇapippalīḥ" },
      { type: "verse", number: "47", sanskrit: "लिह्याद्वा पिप्पलीद्राक्षापथ्याशृङ्गीदुरालभाः घृतमाक्षिकतैलैर्वा त्र्यूषणं क्षारसंयुतम् पिप्पलीक्षौद्रयुक्तौ वा रसौ धात्रीकपित्थयोः", text: "lihyādvā pippalīdrākṣāpathyāśṛṅgīdurālabhāḥ ghṛtamākṣikatailairvā tryūṣaṇaṃ kṣārasaṃyutam pippalīkṣaudrayuktau vā rasau dhātrīkapitthayoḥ" },
      { type: "verse", number: "48", sanskrit: "सितोपलात्वामलकी द्राक्षा गोश्वशकृद्रसम् कोललाजमधुद्राक्षापिप्पलीनागराणि वा", text: "sitopalātvāmalakī drākṣā gośvaśakṛdrasam kolalājamadhudrākṣāpippalīnāgarāṇi vā" },
      { type: "verse", number: "49", sanskrit: "गुडतैलनिशाद्राक्षाकणारास्नोषणानि वा पिबेद्रसाम्बुमद्याद्यैर्लेहौषधरजांसि वा", text: "guḍatailaniśādrākṣākaṇārāsnoṣaṇāni vā pibedrasāmbumadyādyairlehauṣadharajāṃsi vā" },
      { type: "verse", number: "50", sanskrit: "जीवन्तीमुस्तसुरसत्वगेलाद्वयपौष्करम् चण्डातामलकीलोहभार्ङ्गीनागरवालकम्", text: "jīvantīmustasurasatvagelādvayapauṣkaram caṇḍātāmalakīlohabhārṅgīnāgaravālakam" },
      { type: "verse", number: "51", sanskrit: "कर्कटाख्याशठीकृष्णानागकेसरचोरकम् उपयुक्तं यथाकामं चूर्णं द्विगुणशर्करम्", text: "karkaṭākhyāśaṭhīkṛṣṇānāgakesaracorakam upayuktaṃ yathākāmaṃ cūrṇaṃ dviguṇaśarkaram" },
      { type: "verse", number: "52", sanskrit: "पार्श्वरुग्ज्वरकासघ्नं हिध्माश्वासहरं परम् जीवन्ती चोरकः शृङ्गी पौष्करं सुरसः शठी", text: "pārśvarugjvarakāsaghnaṃ hidhmāśvāsaharaṃ param jīvantī corakaḥ śṛṅgī pauṣkaraṃ surasaḥ śaṭhī" },
      { type: "verse", number: "53", sanskrit: "पिप्पलीत्वग्बिडक्षारशुण्ठीहिङ्वम्लवेतसम् एलातामलकीभार्ङ्गीवृक्षाम्लं चेति चूर्णितम्", text: "pippalītvagbiḍakṣāraśuṇṭhīhiṅvamlavetasam elātāmalakībhārṅgīvṛkṣāmlaṃ ceti cūrṇitam" },
      { type: "verse", number: "54", sanskrit: "रसेन मातुलुङ्गस्य मद्येन हविषाथवा लीढं प्रयुक्तमन्ने वा केवलं चोपयोजितम्", text: "rasena mātuluṅgasya madyena haviṣāthavā līḍhaṃ prayuktamanne vā kevalaṃ copayojitam" },
      { type: "verse", number: "55", sanskrit: "हिध्माश्वासविबन्धार्शःकासहृत्पार्श्वशूलनुत् शठीतामलकीभार्ङ्गीचण्डावालकपौष्करम्", text: "hidhmāśvāsavibandhārśaḥkāsahṛtpārśvaśūlanut śaṭhītāmalakībhārṅgīcaṇḍāvālakapauṣkaram" },
      { type: "verse", number: "56", sanskrit: "शर्कराष्टगुणं चूर्णं हिध्माश्वासहरं परम् तुल्यं गुडं नागरं च भक्षयेन्नावयेत वा", text: "śarkarāṣṭaguṇaṃ cūrṇaṃ hidhmāśvāsaharaṃ param tulyaṃ guḍaṃ nāgaraṃ ca bhakṣayennāvayeta vā" },
      { type: "verse", number: "57", sanskrit: "लशुनस्य पलाण्डोर्वा मूलं गृञ्जनकस्य वा चन्दनाद्वा रसं दद्यान्नारीक्षीरेण नावनम्", text: "laśunasya palāṇḍorvā mūlaṃ gṛñjanakasya vā candanādvā rasaṃ dadyānnārīkṣīreṇa nāvanam" },
      { type: "verse", number: "58", sanskrit: "सशर्करां पिप्पली वा मधुकं वा मधुद्रवम् स्तन्येन मक्षिकाविष्ठामलक्तकरसेन वा", text: "saśarkarāṃ pippalī vā madhukaṃ vā madhudravam stanyena makṣikāviṣṭhāmalaktakarasena vā" },
      { type: "verse", number: "59", sanskrit: "ससैन्धवं घृताच्छं वा सिद्धं स्तन्येन वा घृतम् कल्कितैर्मधुरद्रव्यैस्तत् पिबेन्नावयेत वा", text: "sasaindhavaṃ ghṛtācchaṃ vā siddhaṃ stanyena vā ghṛtam kalkitairmadhuradravyaistat pibennāvayeta vā" },
      { type: "verse", number: "60", sanskrit: "सकृदुष्णं सकृच्छीतं व्यत्यासात् ससितं मधु तद्वत् पयस्तहासिद्धमधोभागौषधैर्घृतम्", text: "sakṛduṣṇaṃ sakṛcchītaṃ vyatyāsāt sasitaṃ madhu tadvat payastahāsiddhamadhobhāgauṣadhairghṛtam" },
      { type: "verse", number: "61", sanskrit: "कणासौवर्चलक्षारवयस्थाहिड्गुचोरकैः सकायस्थैर्घृतं मस्तु दशमूलरसे पचेत्", text: "kaṇāsauvarcalakṣāravayasthāhiḍgucorakaiḥ sakāyasthairghṛtaṃ mastu daśamūlarase pacet" },
      { type: "verse", number: "62", sanskrit: "तत् पिबेज्जीवनीयैर्वा लिह्यात् समधु साधितम् तेजोवत्यभया कुष्ठं पिप्पली कटुरोहिणी", text: "tat pibejjīvanīyairvā lihyāt samadhu sādhitam tejovatyabhayā kuṣṭhaṃ pippalī kaṭurohiṇī" },
      { type: "verse", number: "63", sanskrit: "पूकीकं पौष्करं मूलं पलाशश्चित्रकः शठी पटुद्वयं तामलकी जीवन्ती बैल्वपेशिका", text: "pūkīkaṃ pauṣkaraṃ mūlaṃ palāśaścitrakaḥ śaṭhī paṭudvayaṃ tāmalakī jīvantī bailvapeśikā" },
      { type: "verse", number: "64", sanskrit: "वचापत्रं च तालीसं कर्षांशैस्तैर्विंपाचयेत् हिङ्गुपादैर्घृतप्रस्थं पीतमाशु निहन्ति तत्", text: "vacāpatraṃ ca tālīsaṃ karṣāṃśaistairviṃpācayet hiṅgupādairghṛtaprasthaṃ pītamāśu nihanti tat" },
      { type: "verse", number: "65", sanskrit: "श्वासानिलार्शोग्रहणीहिध्माहृत्पार्श्ववेदनाः सिद्धं वा पुरमञ्जिष्ठालाक्षासर्जरसैः पिबेत्", text: "śvāsānilārśograhaṇīhidhmāhṛtpārśvavedanāḥ siddhaṃ vā puramañjiṣṭhālākṣāsarjarasaiḥ pibet" },
      { type: "verse", number: "66", sanskrit: "सपद्मकमनोह्वालैर्घृतप्रस्थं पिचून्मितैः वत्सकादिप्रतीवापं सिद्धं वा प्रथमे गणे", text: "sapadmakamanohvālairghṛtaprasthaṃ picūnmitaiḥ vatsakādipratīvāpaṃ siddhaṃ vā prathame gaṇe" },
      { type: "verse", number: "67", sanskrit: "सपञ्चलवणं सर्पिः श्वासकासानपोहति हिंस्राविडङ्गपूतीकत्रिकटुत्रिफलाग्निकैः", text: "sapañcalavaṇaṃ sarpiḥ śvāsakāsānapohati hiṃsrāviḍaṅgapūtīkatrikaṭutriphalāgnikaiḥ" },
      { type: "verse", number: "68", sanskrit: "कोलमात्रैर्घृतप्रस्थं पाचयेत् सलिलाढके क्षीरप्रस्थद्वयोपेतं तत् कासश्वासपीनसान्", text: "kolamātrairghṛtaprasthaṃ pācayet salilāḍhake kṣīraprasthadvayopetaṃ tat kāsaśvāsapīnasān" },
      { type: "verse", number: "69", sanskrit: "अर्शांस्यरोचकं गुल्मं क्षयं हिध्मां च नाशयेत् सैन्धवार्धांशयुक्तं वा पुराणं पाययेद्घृतम् धान्वन्तरं वृषघृतं दाधिकं त्र्यूषणादि वा", text: "arśāṃsyarocakaṃ gulmaṃ kṣayaṃ hidhmāṃ ca nāśayet saindhavārdhāṃśayuktaṃ vā purāṇaṃ pāyayedghṛtam dhānvantaraṃ vṛṣaghṛtaṃ dādhikaṃ tryūṣaṇādi vā" },
      { type: "verse", number: "70", sanskrit: "शीताम्बुसेकः सहसा त्रासविक्षेपभीशुचः हर्षेर्ष्योच्छ्वासरोधाश्च हितं कीटैश्च दंशनम्", text: "śītāmbusekaḥ sahasā trāsavikṣepabhīśucaḥ harṣerṣyocchvāsarodhāśca hitaṃ kīṭaiśca daṃśanam" },
      { type: "verse", number: "71", sanskrit: "यत् किञ्चित् कफवातघ्नमुष्णं वातानुलोमनम् तत् सेव्यं प्रायशो यच्च सुतरां मारुतापहम्", text: "yat kiñcit kaphavātaghnamuṣṇaṃ vātānulomanam tat sevyaṃ prāyaśo yacca sutarāṃ mārutāpaham" },
      { type: "verse", number: "72", sanskrit: "वातकृद्वा कफहरं कफकृद्वानिलापहम् कार्यं नैकान्तिकं ताभ्यां प्रायः श्रेयो ऽनिलापहम्", text: "vātakṛdvā kaphaharaṃ kaphakṛdvānilāpaham kāryaṃ naikāntikaṃ tābhyāṃ prāyaḥ śreyo 'nilāpaham" },
      { type: "verse", number: "73", sanskrit: "सर्वेषां बृंहणे ह्यल्पः शक्यश्च प्रायशो भवेत् नात्यर्थं शमने ऽपायो भृशोशक्यश्च कर्शने", text: "sarveṣāṃ bṛṃhaṇe hyalpaḥ śakyaśca prāyaśo bhavet nātyarthaṃ śamane 'pāyo bhṛśośakyaśca karśane" },
      { type: "verse", number: "74", sanskrit: "शमनैर्बृंहणैश्चातो भूयिष्ठं तानुपाचरेत् कासश्वासक्षयच्छर्दिहिध्माश्चान्योन्यभेषजैः", text: "śamanairbṛṃhaṇaiścāto bhūyiṣṭhaṃ tānupācaret kāsaśvāsakṣayacchardihidhmāścānyonyabheṣajaiḥ" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 7,
    lang: "sa",
    content: [
      { type: "heading", heading: "Куштха чикитса — лечение кожных болезней" },
      { type: "text", text: "Глава 7 Чикитса стханы — лечебный раздел о лечение кожных болезней. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो राजयक्ष्मचिकित्सितं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto rājayakṣmacikitsitaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "बलिनो बहुदोषस्य स्निग्धस्विन्नस्य शोधनम् ऊर्ध्वाधो यक्ष्मिणः कुर्यात् सस्नेहं यन्न कर्शनम्", text: "balino bahudoṣasya snigdhasvinnasya śodhanam ūrdhvādho yakṣmiṇaḥ kuryāt sasnehaṃ yanna karśanam" },
      { type: "verse", number: "3", sanskrit: "पयसा फलयुक्तेन मधुरेण रसेन वा सर्पिष्मत्या यवाग्वा वा वमनद्रव्यसिद्धया", text: "payasā phalayuktena madhureṇa rasena vā sarpiṣmatyā yavāgvā vā vamanadravyasiddhayā" },
      { type: "verse", number: "4", sanskrit: "वमेद्विरेचनं दद्यात्त्रिवृच्श्यामानृपद्रुमान् शर्करामधुसर्पिर्भिः पयसा तर्पणेन वा द्राक्षाविदारीकाश्मर्यमांसानां वा रसैर्युतान्", text: "vamedvirecanaṃ dadyāttrivṛcśyāmānṛpadrumān śarkarāmadhusarpirbhiḥ payasā tarpaṇena vā drākṣāvidārīkāśmaryamāṃsānāṃ vā rasairyutān" },
      { type: "verse", number: "5", sanskrit: "शुद्धकोष्ठस्य युञ्जीत विधिं बृंहणदीपनम् हृद्यानि चान्नपानानि वातघ्नानि लघूनि च", text: "śuddhakoṣṭhasya yuñjīta vidhiṃ bṛṃhaṇadīpanam hṛdyāni cānnapānāni vātaghnāni laghūni ca" },
      { type: "verse", number: "6", sanskrit: "शालिषष्टिकगोधूमयवमुद्गं समास्थितम् लघुमच्युतवीर्यं च सुजरं बलकृच्च यत्", text: "śāliṣaṣṭikagodhūmayavamudgaṃ samāsthitam laghumacyutavīryaṃ ca sujaraṃ balakṛcca yat" },
      { type: "verse", number: "7", sanskrit: "आजं क्षीरं घृतं मांसं क्रव्यान्मांसं च शोषजित् काकोलूकवृकद्वीपिगवाश्वनकुलोरगम्", text: "ājaṃ kṣīraṃ ghṛtaṃ māṃsaṃ kravyānmāṃsaṃ ca śoṣajit kākolūkavṛkadvīpigavāśvanakuloragam" },
      { type: "verse", number: "8", sanskrit: "गृध्रभासखरोष्ट्रं च हितं छद्मोपसंहितम् ज्ञातं जुगुप्सितं तद्धि छर्दिषे न बलौजसे", text: "gṛdhrabhāsakharoṣṭraṃ ca hitaṃ chadmopasaṃhitam jñātaṃ jugupsitaṃ taddhi chardiṣe na balaujase" },
      { type: "verse", number: "9", sanskrit: "मृगाद्याः पित्तकफयोः पवने प्रसहादयः वेशवारीकृताः पथ्या रसादिषु च कल्पिताः", text: "mṛgādyāḥ pittakaphayoḥ pavane prasahādayaḥ veśavārīkṛtāḥ pathyā rasādiṣu ca kalpitāḥ" },
      { type: "verse", number: "10", sanskrit: "भृष्टाः सर्षपतैलेन सर्पिषा वा यथायथम् रसिका मृदवः स्निग्धाः पटुद्रव्याभिसंस्कृताः", text: "bhṛṣṭāḥ sarṣapatailena sarpiṣā vā yathāyatham rasikā mṛdavaḥ snigdhāḥ paṭudravyābhisaṃskṛtāḥ" },
      { type: "verse", number: "11", sanskrit: "हिता मौद्गककौलत्थास्तद्वद्यूषाश्च साधिताः सपिप्पलीकं सयवं सकुलत्थं सनागरम्", text: "hitā maudgakakaulatthāstadvadyūṣāśca sādhitāḥ sapippalīkaṃ sayavaṃ sakulatthaṃ sanāgaram" },
      { type: "verse", number: "12", sanskrit: "सदाडिमं सामलकं स्निग्धमाजं रसं पिबेत् तेन षड्विनिवर्तन्ते विकाराः पीनसादयः", text: "sadāḍimaṃ sāmalakaṃ snigdhamājaṃ rasaṃ pibet tena ṣaḍvinivartante vikārāḥ pīnasādayaḥ" },
      { type: "verse", number: "13", sanskrit: "कोलदाडिमनिर्यासपिष्टयास्थिविहीनया द्राक्षया स्वच्छधान्याम्बुप्लुतालोडितकल्कया", text: "koladāḍimaniryāsapiṣṭayāsthivihīnayā drākṣayā svacchadhānyāmbuplutāloḍitakalkayā" },
      { type: "verse", number: "14", sanskrit: "कार्यः सौवर्चलव्योषपत्रैलादीप्यकान्वितः समाक्षिकः सकर्पूरः सलवङ्कः सकेसरः", text: "kāryaḥ sauvarcalavyoṣapatrailādīpyakānvitaḥ samākṣikaḥ sakarpūraḥ salavaṅkaḥ sakesaraḥ" },
      { type: "verse", number: "15", sanskrit: "चन्द्रकान्तो यथार्थाख्यः शोषहाग्निरुचिप्रदः शुक्ताम्लधात्रीस्वरसैर्द्राक्षायाः कल्कितं पलम्", text: "candrakānto yathārthākhyaḥ śoṣahāgnirucipradaḥ śuktāmladhātrīsvarasairdrākṣāyāḥ kalkitaṃ palam" },
      { type: "verse", number: "16", sanskrit: "गुडषट्पलसंयुक्तं युक्तं श्लक्ष्णैश्च कार्षिकैः वृक्षाम्लधान्यद्रमिलीराजिकादाडिमोषणैः", text: "guḍaṣaṭpalasaṃyuktaṃ yuktaṃ ślakṣṇaiśca kārṣikaiḥ vṛkṣāmladhānyadramilīrājikādāḍimoṣaṇaiḥ" },
      { type: "verse", number: "17", sanskrit: "पलेन नागपुष्पस्य किञ्चित् सौवर्चलेन च ससेव्यपत्रत्वक्तोयः सुरसारसमूर्छितः", text: "palena nāgapuṣpasya kiñcit sauvarcalena ca sasevyapatratvaktoyaḥ surasārasamūrchitaḥ" },
      { type: "verse", number: "18", sanskrit: "भूरिभूस्तृणको रागः कण्ठ्यो रुच्यः समाक्षिकः पिबेच्च सुतरां मद्यं जीर्णं स्रोतोविशोधनम्", text: "bhūribhūstṛṇako rāgaḥ kaṇṭhyo rucyaḥ samākṣikaḥ pibecca sutarāṃ madyaṃ jīrṇaṃ srotoviśodhanam" },
      { type: "verse", number: "19", sanskrit: "पित्तादिषु विशेषेण मध्वरिष्टाच्छवारुणीः सिद्धं वा पञ्चमूलेन तामलक्याथवा जलम्", text: "pittādiṣu viśeṣeṇa madhvariṣṭācchavāruṇīḥ siddhaṃ vā pañcamūlena tāmalakyāthavā jalam" },
      { type: "verse", number: "20", sanskrit: "पर्णिनीभिश्चतसृभिर्धान्यनागरकेण वा कल्पयेच्चानुकूलोस्य तेनान्नं शुचि यत्नवान्", text: "parṇinībhiścatasṛbhirdhānyanāgarakeṇa vā kalpayeccānukūlosya tenānnaṃ śuci yatnavān" },
      { type: "verse", number: "21", sanskrit: "दशमूलेन पयसा सिद्धं मांसरसेन वा बलागर्भं घृतं योज्यं क्रव्यामांसरसेन वा", text: "daśamūlena payasā siddhaṃ māṃsarasena vā balāgarbhaṃ ghṛtaṃ yojyaṃ kravyāmāṃsarasena vā" },
      { type: "verse", number: "22", sanskrit: "सक्षौद्रं पयसा सिद्धं सर्पिर्दशगुणेन वा जीवन्तीं मधुकं द्राक्षां फलानि कुटजस्य च", text: "sakṣaudraṃ payasā siddhaṃ sarpirdaśaguṇena vā jīvantīṃ madhukaṃ drākṣāṃ phalāni kuṭajasya ca" },
      { type: "verse", number: "23", sanskrit: "पुष्कराह्वं शठीं कृष्णां व्याघ्रीं गोक्षुरकं बलाम् नीलित्पलं तामलकीं त्रायमाणां दुरालभाम् कल्कीकृत्य घृतं पक्वं रोगराजहरं परम्", text: "puṣkarāhvaṃ śaṭhīṃ kṛṣṇāṃ vyāghrīṃ gokṣurakaṃ balām nīlitpalaṃ tāmalakīṃ trāyamāṇāṃ durālabhām kalkīkṛtya ghṛtaṃ pakvaṃ rogarājaharaṃ param" },
      { type: "verse", number: "24", sanskrit: "दुरालभां गोक्षुरकं चतस्त्रः पर्णिनीर्बलाम् भागान् पलोन्मितान् कृत्वा पलं पर्पटकस्य च", text: "durālabhāṃ gokṣurakaṃ catastraḥ parṇinīrbalām bhāgān palonmitān kṛtvā palaṃ parpaṭakasya ca" },
      { type: "verse", number: "25", sanskrit: "पचेद्दशगुणे तोये दशभागावशेषिते पूते तस्मिन् घृतप्रस्थं क्षीरद्विगुणितं पचेत्", text: "paceddaśaguṇe toye daśabhāgāvaśeṣite pūte tasmin ghṛtaprasthaṃ kṣīradviguṇitaṃ pacet" },
      { type: "verse", number: "26", sanskrit: "गर्भं दत्वा शठीकृष्णाभूनिम्बोत्पलसारिवाः त्रायन्तीं पौष्करं मूलं सहपत्रफलां फलम्", text: "garbhaṃ datvā śaṭhīkṛṣṇābhūnimbotpalasārivāḥ trāyantīṃ pauṣkaraṃ mūlaṃ sahapatraphalāṃ phalam" },
      { type: "verse", number: "27", sanskrit: "कुटजाच्च जयेत्तद्धि शिरःपार्श्वांसवेदनाम् तृष्णां छर्दिमतीसारं कासदाहभ्रमज्वरान्", text: "kuṭajācca jayettaddhi śiraḥpārśvāṃsavedanām tṛṣṇāṃ chardimatīsāraṃ kāsadāhabhramajvarān" },
      { type: "verse", number: "28", sanskrit: "घृतं खर्जूरमृद्वीकामधुकैः सपरूसकैः सपिप्पलीकं वैस्वर्यकासश्वासज्वरापहम्", text: "ghṛtaṃ kharjūramṛdvīkāmadhukaiḥ saparūsakaiḥ sapippalīkaṃ vaisvaryakāsaśvāsajvarāpaham" },
      { type: "verse", number: "29", sanskrit: "दशमूलशृतात् क्षीरात् सर्पिर्यदुदियान्नवम् सपिप्पलीकं सक्षौद्रं तत् परं स्वरबोधनम्", text: "daśamūlaśṛtāt kṣīrāt sarpiryadudiyānnavam sapippalīkaṃ sakṣaudraṃ tat paraṃ svarabodhanam" },
      { type: "verse", number: "30", sanskrit: "शिरःपार्श्वासशूलघ्नं कासश्वासज्वरापहम् पञ्चभिः पञ्चमूलैर्वा शृताद्यदुदियात् घृतम्", text: "śiraḥpārśvāsaśūlaghnaṃ kāsaśvāsajvarāpaham pañcabhiḥ pañcamūlairvā śṛtādyadudiyāt ghṛtam" },
      { type: "verse", number: "31", sanskrit: "पञ्चानां पञ्चमूलानां रसे क्षीरचतुर्गुणे सिद्धं सर्पिर्जयत्येतद्यक्ष्मणः सप्तकं बलम्", text: "pañcānāṃ pañcamūlānāṃ rase kṣīracaturguṇe siddhaṃ sarpirjayatyetadyakṣmaṇaḥ saptakaṃ balam" },
      { type: "verse", number: "32", sanskrit: "पञ्चकोलयवक्षारषट्पलेन पचेत् घृतम् प्रस्थोन्मितं तुल्यपयः स्रोतसां तद्विशोधनम्", text: "pañcakolayavakṣāraṣaṭpalena pacet ghṛtam prasthonmitaṃ tulyapayaḥ srotasāṃ tadviśodhanam" },
      { type: "verse", number: "33", sanskrit: "गुल्मज्वरोदरप्लीहग्रहणीपाण्डुपीनसान् कासश्वासाग्निसदनश्वयथूर्ध्वानिलान् जयेत्", text: "gulmajvarodaraplīhagrahaṇīpāṇḍupīnasān kāsaśvāsāgnisadanaśvayathūrdhvānilān jayet" },
      { type: "verse", number: "34", sanskrit: "रास्नाबलागोक्षुरकस्थिरावर्षाभुवारिणि जीवन्तीपिप्पलीगर्भं सक्षीरं शोषजिद्घृतम् अश्वगन्धाशृतात् क्षीरात् घृतं च ससितापयः", text: "rāsnābalāgokṣurakasthirāvarṣābhuvāriṇi jīvantīpippalīgarbhaṃ sakṣīraṃ śoṣajidghṛtam aśvagandhāśṛtāt kṣīrāt ghṛtaṃ ca sasitāpayaḥ" },
      { type: "verse", number: "35", sanskrit: "साधारणामिषतुलां तोयद्रोणद्वये पचेत् तेनाष्टभागशेषेण जीवनीयैः पलोन्मितैः", text: "sādhāraṇāmiṣatulāṃ toyadroṇadvaye pacet tenāṣṭabhāgaśeṣeṇa jīvanīyaiḥ palonmitaiḥ" },
      { type: "verse", number: "36", sanskrit: "साधयेत् सर्पिषः प्रस्थं वातपित्तामयापहम् मांससर्पिरिदं पीतं युक्तं मांसरसेन वा कासश्वासस्वरभ्रंशशोषहृत्पार्श्वशूलजित्", text: "sādhayet sarpiṣaḥ prasthaṃ vātapittāmayāpaham māṃsasarpiridaṃ pītaṃ yuktaṃ māṃsarasena vā kāsaśvāsasvarabhraṃśaśoṣahṛtpārśvaśūlajit" },
      { type: "verse", number: "37", sanskrit: "यष्टीबलागुडूच्यल्पपञ्चमूलतुलां पचेत् शूर्पे ऽपामष्टभागस्थे तत्र पात्रं पचेत् घृतात्", text: "yaṣṭībalāguḍūcyalpapañcamūlatulāṃ pacet śūrpe 'pāmaṣṭabhāgasthe tatra pātraṃ pacet ghṛtāt" },
      { type: "verse", number: "38", sanskrit: "धात्रीविदारीक्षुरसत्रिपात्रे पयसो ऽर्मणे सुपिष्टैर्जीवनीयैश्च पाराशरमिदं घृतम् ससैन्यं राजयक्ष्माणमुन्मूलयति शीलितम्", text: "dhātrīvidārīkṣurasatripātre payaso 'rmaṇe supiṣṭairjīvanīyaiśca pārāśaramidaṃ ghṛtam sasainyaṃ rājayakṣmāṇamunmūlayati śīlitam" },
      { type: "verse", number: "39", sanskrit: "मूर्वाहरिद्राखदिरक्वाथं सर्पिः शकृद्रसम् गोगजाजाविहयजं पयस्तुल्यान् दश द्रवान्", text: "mūrvāharidrākhadirakvāthaṃ sarpiḥ śakṛdrasam gogajājāvihayajaṃ payastulyān daśa dravān" },
      { type: "verse", number: "40", sanskrit: "स्वादुस्कन्धं त्रिकटुकं कल्कितं देवदारु च पचेत्तच्चाशु शोषघ्नं तद्वद्वासावरीघृतम्", text: "svāduskandhaṃ trikaṭukaṃ kalkitaṃ devadāru ca pacettaccāśu śoṣaghnaṃ tadvadvāsāvarīghṛtam" },
      { type: "verse", number: "41", sanskrit: "द्विपञ्चमूलवरणयवबिल्वपुनर्नवाः करञ्जबोलस्थविरकुलस्थबदराग्निकाः", text: "dvipañcamūlavaraṇayavabilvapunarnavāḥ karañjabolasthavirakulasthabadarāgnikāḥ" },
      { type: "verse", number: "42", sanskrit: "गर्भं दत्वा स्नुहीक्षीरं शुकाख्याचव्यसैन्धवम् हरीतकीं च तच्छोषशोफमेहोदरापहम्", text: "garbhaṃ datvā snuhīkṣīraṃ śukākhyācavyasaindhavam harītakīṃ ca tacchoṣaśophamehodarāpaham" },
      { type: "verse", number: "43", sanskrit: "यवाग्वा वा पिबेन्मात्रां लिह्याद्वा मधुनान्विताम् सिद्धानां सर्पिषामेषां दद्यादन्नेन वा सह", text: "yavāgvā vā pibenmātrāṃ lihyādvā madhunānvitām siddhānāṃ sarpiṣāmeṣāṃ dadyādannena vā saha" },
      { type: "verse", number: "44", sanskrit: "एलाजमोदत्रिफलासौराष्ट्रीव्योषचित्रकान् सारानरिष्टगायत्रीसालबीजकसम्भवान्", text: "elājamodatriphalāsaurāṣṭrīvyoṣacitrakān sārānariṣṭagāyatrīsālabījakasambhavān" },
      { type: "verse", number: "45", sanskrit: "भल्लातकं विडङ्गं च पृथगष्टपलोन्मितम् सलिले षोडशगुणे षोडशांशस्थितं पचेत्", text: "bhallātakaṃ viḍaṅgaṃ ca pṛthagaṣṭapalonmitam salile ṣoḍaśaguṇe ṣoḍaśāṃśasthitaṃ pacet" },
      { type: "verse", number: "46", sanskrit: "पुनस्तेन घृतप्रस्थं सिद्धे चास्मिन् पलानि षट् तवक्षीर्याः क्षिपेत्त्रिंशत् सिताया द्विगुणं मधु", text: "punastena ghṛtaprasthaṃ siddhe cāsmin palāni ṣaṭ tavakṣīryāḥ kṣipettriṃśat sitāyā dviguṇaṃ madhu" },
      { type: "verse", number: "47", sanskrit: "घृतात्त्रिजातात्त्रिपलं ततो लीढं खजाहतम् पयोनुपानं तत् प्राह्णे रसायनमयन्त्रणम्", text: "ghṛtāttrijātāttripalaṃ tato līḍhaṃ khajāhatam payonupānaṃ tat prāhṇe rasāyanamayantraṇam" },
      { type: "verse", number: "48", sanskrit: "मेध्यं चक्षुष्यमायुष्यं दीपनं हन्ति चाचिरात् मेहगुल्मक्षयव्याधिपाण्डुरोगभगन्दरान् ये च सर्पिर्गुडाः प्रोक्ताः क्षते योज्याः क्षये ऽपि ते", text: "medhyaṃ cakṣuṣyamāyuṣyaṃ dīpanaṃ hanti cācirāt mehagulmakṣayavyādhipāṇḍurogabhagandarān ye ca sarpirguḍāḥ proktāḥ kṣate yojyāḥ kṣaye 'pi te" },
      { type: "verse", number: "49", sanskrit: "खर्जूरपिप्पलीद्राक्षापथ्याशृङ्गीदुरालभाः त्रिफलापिप्पलीमुस्ताशृङ्गाटगुडशर्कराः", text: "kharjūrapippalīdrākṣāpathyāśṛṅgīdurālabhāḥ triphalāpippalīmustāśṛṅgāṭaguḍaśarkarāḥ" },
      { type: "verse", number: "50", sanskrit: "वीराशठीपुष्कराख्यासुरसाशर्करागुडाः नागरं चित्रको लाजाः पिप्पल्यामलकं गुडः", text: "vīrāśaṭhīpuṣkarākhyāsurasāśarkarāguḍāḥ nāgaraṃ citrako lājāḥ pippalyāmalakaṃ guḍaḥ" },
      { type: "verse", number: "51", sanskrit: "विडङ्गसारश्चविका त्र्यूषणं च विचूर्णितम् अर्धश्लोकैः स्मृता लेहाः पञ्चैते मधुसर्पिषा स्वर्याः कासक्षयश्वासपार्श्वरुक्कफनाशनः", text: "viḍaṅgasāraścavikā tryūṣaṇaṃ ca vicūrṇitam ardhaślokaiḥ smṛtā lehāḥ pañcaite madhusarpiṣā svaryāḥ kāsakṣayaśvāsapārśvarukkaphanāśanaḥ" },
      { type: "verse", number: "52", sanskrit: "त्वगेलापिप्पलीक्षीरीशर्करा द्विगुणाः क्रमात् चूर्णिता भक्षयेल्लिह्यात् पूर्ववद्वा तथागुणाः", text: "tvagelāpippalīkṣīrīśarkarā dviguṇāḥ kramāt cūrṇitā bhakṣayellihyāt pūrvavadvā tathāguṇāḥ" },
      { type: "verse", number: "53", sanskrit: "तिलमाषाश्वगन्धा वा माक्षिकाजघृतदुताः पूर्वोक्तेष्वेव रोगेषु वातप्रायेषु पूजिताः", text: "tilamāṣāśvagandhā vā mākṣikājaghṛtadutāḥ pūrvokteṣveva rogeṣu vātaprāyeṣu pūjitāḥ" },
      { type: "verse", number: "54", sanskrit: "स्वरसादचिकित्सितम् विशेषात् स्वरसादे ऽस्य नस्यधूमादि योजयेत् तत्रापि वातजे कोष्णं पिबेदौत्तरभक्तिकम्", text: "svarasādacikitsitam viśeṣāt svarasāde 'sya nasyadhūmādi yojayet tatrāpi vātaje koṣṇaṃ pibedauttarabhaktikam" },
      { type: "verse", number: "55", sanskrit: "कासमर्दकवार्ताकीमार्कवस्वरसैर्घृतम् साधितं कासजित् स्वर्यं सिद्धमार्तगलेन वा", text: "kāsamardakavārtākīmārkavasvarasairghṛtam sādhitaṃ kāsajit svaryaṃ siddhamārtagalena vā" },
      { type: "verse", number: "56", sanskrit: "बदरीपत्रकल्कं वा घृतभृष्टं ससैन्धवम् तैलं वा मधुकद्राक्षापिप्पलीकृमिनुत्फलैः", text: "badarīpatrakalkaṃ vā ghṛtabhṛṣṭaṃ sasaindhavam tailaṃ vā madhukadrākṣāpippalīkṛminutphalaiḥ" },
      { type: "verse", number: "57", sanskrit: "हंसपाद्याश्च मूलेन पक्वं नस्तो निषेचयेत् सुखोदकानुपानं च ससर्पिष्कं गुडौदनम् अश्नीयात् पायसं चैवं स्निग्धं स्वेदं च योजयेत्", text: "haṃsapādyāśca mūlena pakvaṃ nasto niṣecayet sukhodakānupānaṃ ca sasarpiṣkaṃ guḍaudanam aśnīyāt pāyasaṃ caivaṃ snigdhaṃ svedaṃ ca yojayet" },
      { type: "verse", number: "58", sanskrit: "पित्तोद्भवे पिबेत् सर्पिः शृतशीतपयोनुपः क्षीरिवृक्षाङ्कुरक्वाथकल्कसिद्धं समाक्षिकम्", text: "pittodbhave pibet sarpiḥ śṛtaśītapayonupaḥ kṣīrivṛkṣāṅkurakvāthakalkasiddhaṃ samākṣikam" },
      { type: "verse", number: "59", sanskrit: "अश्नीयाच्च ससर्पिष्कं यष्टीमधुकपायसम् बलाविदारिगन्धाभ्यां विदार्या मधुकेन च", text: "aśnīyācca sasarpiṣkaṃ yaṣṭīmadhukapāyasam balāvidārigandhābhyāṃ vidāryā madhukena ca" },
      { type: "verse", number: "60", sanskrit: "सिद्धं सलवणं सर्पिर्नस्यं स्वर्यमनुत्तमम् प्रपौण्डरीकं मधुकं पिप्पली बृहती बला", text: "siddhaṃ salavaṇaṃ sarpirnasyaṃ svaryamanuttamam prapauṇḍarīkaṃ madhukaṃ pippalī bṛhatī balā" },
      { type: "verse", number: "61", sanskrit: "साधितं क्षीरसर्पिश्च तत् स्वव्र्यं नावनं परम् लिह्यान्मधुरकाणां च चूर्णं मधुघृतान्वितम्", text: "sādhitaṃ kṣīrasarpiśca tat svavryaṃ nāvanaṃ param lihyānmadhurakāṇāṃ ca cūrṇaṃ madhughṛtānvitam" },
      { type: "verse", number: "62", sanskrit: "वरीं बलां पयस्यां वा काकोलीमधुके तथा एवमस्यानुपशमे ललाटे व्यधयेत् सिराम्", text: "varīṃ balāṃ payasyāṃ vā kākolīmadhuke tathā evamasyānupaśame lalāṭe vyadhayet sirām" },
      { type: "verse", number: "63", sanskrit: "पिबेत् कटूनि मूत्रेण कफजे रूक्षभोजनः कट्कफलामलकव्योषं लिह्यात्तैलमधुप्लुतम्", text: "pibet kaṭūni mūtreṇa kaphaje rūkṣabhojanaḥ kaṭkaphalāmalakavyoṣaṃ lihyāttailamadhuplutam" },
      { type: "verse", number: "64", sanskrit: "व्योषक्षाराग्निचविकाभार्ङ्गीपथ्यामधूनि वा यवैर्यवागूं यमके कणाधात्रीकृतां पिबेत् भुत्क्वाद्यात्पिप्पलीं शुण्ठीं तीक्ष्णं वा वमनं भजेत्", text: "vyoṣakṣārāgnicavikābhārṅgīpathyāmadhūni vā yavairyavāgūṃ yamake kaṇādhātrīkṛtāṃ pibet bhutkvādyātpippalīṃ śuṇṭhīṃ tīkṣṇaṃ vā vamanaṃ bhajet" },
      { type: "verse", number: "65", sanskrit: "शर्कराक्षौद्रमिश्राणि शृतानि मधुरैः सह पिबेत् पयांसि यस्योच्चैर्वदतो विहतः स्वरः", text: "śarkarākṣaudramiśrāṇi śṛtāni madhuraiḥ saha pibet payāṃsi yasyoccairvadato vihataḥ svaraḥ" },
      { type: "verse", number: "66", sanskrit: "अरोचकचिकित्सितम् विचित्रमन्नमरुचौ हितैरुपहितं हितम् बहिरन्तर्मृजां चित्तनिर्वाणं हृद्यमौषधम्", text: "arocakacikitsitam vicitramannamarucau hitairupahitaṃ hitam bahirantarmṛjāṃ cittanirvāṇaṃ hṛdyamauṣadham" },
      { type: "verse", number: "67", sanskrit: "द्वौ कालौ दन्तपवनं भक्षयेन्मुखधावनैः कषायैः क्षालयेदास्यं धूमं प्रायौगिकं पिबेत्", text: "dvau kālau dantapavanaṃ bhakṣayenmukhadhāvanaiḥ kaṣāyaiḥ kṣālayedāsyaṃ dhūmaṃ prāyaugikaṃ pibet" },
      { type: "verse", number: "68", sanskrit: "तालीसपत्रवटकाः सकर्पूरसितोपलाः शशाङ्ककिरणाख्याश्च भक्ष्या रुचिकराः परम्", text: "tālīsapatravaṭakāḥ sakarpūrasitopalāḥ śaśāṅkakiraṇākhyāśca bhakṣyā rucikarāḥ param" },
      { type: "verse", number: "69", sanskrit: "वातादरोचके तत्र पिबेच्चूर्णं प्रसन्नया हरेणुकृष्णाकृमिजिद्द्राक्षासैन्धवनागरात्", text: "vātādarocake tatra pibeccūrṇaṃ prasannayā hareṇukṛṣṇākṛmijiddrākṣāsaindhavanāgarāt" },
      { type: "verse", number: "70", sanskrit: "एलाभार्ङ्गीयवक्षारहिङ्गुयुक्ताद् घृतेन वा छर्दयेद्वा वचाम्भोभिः पित्ताच्च गुडवारिभिः", text: "elābhārṅgīyavakṣārahiṅguyuktād ghṛtena vā chardayedvā vacāmbhobhiḥ pittācca guḍavāribhiḥ" },
      { type: "verse", number: "71", sanskrit: "लिह्याद्वा शर्करासर्पिर्लवणोत्तममाक्षिकम् कफाद्वमेन्निम्बजलैर्दीप्यकारग्वधोदकम्", text: "lihyādvā śarkarāsarpirlavaṇottamamākṣikam kaphādvamennimbajalairdīpyakāragvadhodakam" },
      { type: "verse", number: "72", sanskrit: "पानं समध्वरिष्टाश्च तीक्ष्णाः समधुमाधवाः पिबेच्चूर्णं च पूर्वोक्तं हरेण्वाद्युष्णवारिणा", text: "pānaṃ samadhvariṣṭāśca tīkṣṇāḥ samadhumādhavāḥ pibeccūrṇaṃ ca pūrvoktaṃ hareṇvādyuṣṇavāriṇā" },
      { type: "verse", number: "73", sanskrit: "त्रिकटुत्रिफलारात्रीयवक्षारं मधुप्लुतम् प्रातराहारकाले च युञ्जीत मुखधावनम्", text: "trikaṭutriphalārātrīyavakṣāraṃ madhuplutam prātarāhārakāle ca yuñjīta mukhadhāvanam" },
      { type: "verse", number: "74", sanskrit: "बिडं सौवर्चलं कुष्ठमजाजी मरिचं सिता धात्र्येलापद्मकोशीरपिप्पलीचन्दनोत्पलम्", text: "biḍaṃ sauvarcalaṃ kuṣṭhamajājī maricaṃ sitā dhātryelāpadmakośīrapippalīcandanotpalam" },
      { type: "verse", number: "75", sanskrit: "लोध्रं तेजोवती पथ्या यवक्षारं कटुत्रयम् आर्द्रदाडिमनिर्यासः सजाजीसितशर्करः", text: "lodhraṃ tejovatī pathyā yavakṣāraṃ kaṭutrayam ārdradāḍimaniryāsaḥ sajājīsitaśarkaraḥ" },
      { type: "verse", number: "76", sanskrit: "सतैलमाक्षिका युक्ताश्चत्वारः कवलग्रहाः चतुरो ऽरोचकान् हन्युरेकदोषसमस्तजान्", text: "satailamākṣikā yuktāścatvāraḥ kavalagrahāḥ caturo 'rocakān hanyurekadoṣasamastajān" },
      { type: "verse", number: "77", sanskrit: "कारव्यजाजीमरिचद्राक्षवृक्षाम्लदाडिमम् सौवर्चलगुडक्षौद्रं सर्वारोचकनाशनम्", text: "kāravyajājīmaricadrākṣavṛkṣāmladāḍimam sauvarcalaguḍakṣaudraṃ sarvārocakanāśanam" },
      { type: "verse", number: "78", sanskrit: "एलात्वङ्नागकुसुमतीक्ष्णकृष्णामहौषधम् भागवृद्धं क्रमाच्चूर्णं निहन्ति समशर्करम्", text: "elātvaṅnāgakusumatīkṣṇakṛṣṇāmahauṣadham bhāgavṛddhaṃ kramāccūrṇaṃ nihanti samaśarkaram" },
      { type: "verse", number: "79", sanskrit: "प्रसेकारुचिहृत्पार्श्वकासश्वासगलामयान् यवानीतिन्तिणीकाम्लवेतसौषधदाडिमम्", text: "prasekārucihṛtpārśvakāsaśvāsagalāmayān yavānītintiṇīkāmlavetasauṣadhadāḍimam" },
      { type: "verse", number: "80", sanskrit: "कृत्वा कोलं च कर्षांशं सितायाश्च चतुष्पलम् धान्यसौवर्चलाजाजीवराङ्गं चार्धकार्षिकम्", text: "kṛtvā kolaṃ ca karṣāṃśaṃ sitāyāśca catuṣpalam dhānyasauvarcalājājīvarāṅgaṃ cārdhakārṣikam" },
      { type: "verse", number: "81", sanskrit: "पिप्पलीनां शतं चैकं द्वे शते मरिचस्य च चूर्णमेतत् परं रुच्यं हृद्यं ग्राहि हिनस्ति च विबन्धकासहृत्पार्श्वप्लीहार्शोग्रहणीगदान्", text: "pippalīnāṃ śataṃ caikaṃ dve śate maricasya ca cūrṇametat paraṃ rucyaṃ hṛdyaṃ grāhi hinasti ca vibandhakāsahṛtpārśvaplīhārśograhaṇīgadān" },
      { type: "verse", number: "82", sanskrit: "तालिसपत्रं मरिचं नागरं पिप्पली शुभा यथोत्तरं भागवृद्धास्त्वगेले चार्धभागिके", text: "tālisapatraṃ maricaṃ nāgaraṃ pippalī śubhā yathottaraṃ bhāgavṛddhāstvagele cārdhabhāgike" },
      { type: "verse", number: "83", sanskrit: "तद्रुच्यं दीपनं चूर्णं कणाष्टगुणशर्करम् कासश्वासारुचिच्छर्दिप्लीहहृत्पार्श्वशूलजित्", text: "tadrucyaṃ dīpanaṃ cūrṇaṃ kaṇāṣṭaguṇaśarkaram kāsaśvāsārucicchardiplīhahṛtpārśvaśūlajit" },
      { type: "verse", number: "84", sanskrit: "पाण्डुज्वरातिसारघ्नं मूढवातानुलोमनम् तालीसपत्रचविकामरिचानां पलं पलम्", text: "pāṇḍujvarātisāraghnaṃ mūḍhavātānulomanam tālīsapatracavikāmaricānāṃ palaṃ palam" },
      { type: "verse", number: "85", sanskrit: "कृष्णातन्मूलयोर्द्वे द्वे पले शुण्ठीपलत्रयम् चतुर्जातमुशीरं च कर्षांशं श्लक्ष्णचूर्णितम्", text: "kṛṣṇātanmūlayordve dve pale śuṇṭhīpalatrayam caturjātamuśīraṃ ca karṣāṃśaṃ ślakṣṇacūrṇitam" },
      { type: "verse", number: "86", sanskrit: "तत्र त्रिंशत् पलं दत्वा क्वथितादमलाद्गुडात् कुर्वीत मोदकानक्षसम्मितांस्ते ऽपि तद्गुणाः", text: "tatra triṃśat palaṃ datvā kvathitādamalādguḍāt kurvīta modakānakṣasammitāṃste 'pi tadguṇāḥ" },
      { type: "verse", number: "87", sanskrit: "प्रसेकचिकित्सितम् अर्कामृताक्षारजलेशर्वरीमुषितैर्यवैः प्रसेके कल्पितान् सक्तून् भक्ष्यांश्चाद्याद् बली वमेत्", text: "prasekacikitsitam arkāmṛtākṣārajaleśarvarīmuṣitairyavaiḥ praseke kalpitān saktūn bhakṣyāṃścādyād balī vamet" },
      { type: "verse", number: "88", sanskrit: "कटुतिक्तैस्तथा शूल्यं भक्षयेज्जाङ्गलं पलम् शुष्कांश्च भक्ष्यान् सुलघूंश्चणकादिरसानुपः", text: "kaṭutiktaistathā śūlyaṃ bhakṣayejjāṅgalaṃ palam śuṣkāṃśca bhakṣyān sulaghūṃścaṇakādirasānupaḥ" },
      { type: "verse", number: "89", sanskrit: "श्लेष्मणो ऽतिप्रसेकेन वायुः श्लेष्माणमस्यति कफप्रसेकं तं विद्यात् स्निग्धोष्णैरेव निर्जयेत्", text: "śleṣmaṇo 'tiprasekena vāyuḥ śleṣmāṇamasyati kaphaprasekaṃ taṃ vidyāt snigdhoṣṇaireva nirjayet" },
      { type: "verse", number: "90", sanskrit: "पीनसे ऽपि क्रममिमं वमथौ च प्रयोजयेत् विशेषात्पीनसे ऽभ्यङ्गान् स्नेहान् स्वेदांश्च शीलयेत्", text: "pīnase 'pi kramamimaṃ vamathau ca prayojayet viśeṣātpīnase 'bhyaṅgān snehān svedāṃśca śīlayet" },
      { type: "verse", number: "91", sanskrit: "स्निग्धानुत्कारिकापिण्डैः शिरःपार्श्वगलादिषु लवणाम्लकटूष्णांश्च रसान् स्नेहोपसंहितान्", text: "snigdhānutkārikāpiṇḍaiḥ śiraḥpārśvagalādiṣu lavaṇāmlakaṭūṣṇāṃśca rasān snehopasaṃhitān" },
      { type: "verse", number: "92", sanskrit: "शिरो ऽंसपार्श्वशूलेषु यथादोषविधिं चरेत् औदकानूपपिशितैरुपनाहाः सुसंस्कृताः", text: "śiro 'ṃsapārśvaśūleṣu yathādoṣavidhiṃ caret audakānūpapiśitairupanāhāḥ susaṃskṛtāḥ" },
      { type: "verse", number: "93", sanskrit: "शस्यन्ते सचतुस्नेहाः शिरःपार्श्वांसशूलिनाम् लेपश्च नतयष्ट्याह्वशताह्वाकुष्ठचन्दनैः", text: "śasyante sacatusnehāḥ śiraḥpārśvāṃsaśūlinām lepaśca natayaṣṭyāhvaśatāhvākuṣṭhacandanaiḥ" },
      { type: "verse", number: "94", sanskrit: "बलारास्नातिलाः सर्पिर्मधुकं नीलमुत्पलम् पलङ्कषा देवदारु चन्दनं मधुकं घृतम्", text: "balārāsnātilāḥ sarpirmadhukaṃ nīlamutpalam palaṅkaṣā devadāru candanaṃ madhukaṃ ghṛtam" },
      { type: "verse", number: "95", sanskrit: "कृष्णगन्धा बला वीरा विदारी सपुनर्नवा अभीरुयष्टीमधुकं पयस्या कत्तृणं घृतम्", text: "kṛṣṇagandhā balā vīrā vidārī sapunarnavā abhīruyaṣṭīmadhukaṃ payasyā kattṛṇaṃ ghṛtam" },
      { type: "verse", number: "96", sanskrit: "इत्यर्धयोगैश्चत्वारः प्रदेहाः परिकीर्तिताः शस्ताः संसृष्टदोषाणां शिरःपार्श्वासशूलिनाम्", text: "ityardhayogaiścatvāraḥ pradehāḥ parikīrtitāḥ śastāḥ saṃsṛṣṭadoṣāṇāṃ śiraḥpārśvāsaśūlinām" },
      { type: "verse", number: "97", sanskrit: "नावनं धूमपानानि स्नेहाश्चौत्तरभक्तिकाः तैलान्यभ्यङ्गयोगीनि बस्तिकर्म तथापरम् शृङ्गाद्यैर्वा यथादोषं दुष्टमेषां हरेदसृक् प्रदेहः सघृतैश्चेष्टः पद्मकोशीरचन्दनैः", text: "nāvanaṃ dhūmapānāni snehāścauttarabhaktikāḥ tailānyabhyaṅgayogīni bastikarma tathāparam śṛṅgādyairvā yathādoṣaṃ duṣṭameṣāṃ haredasṛk pradehaḥ saghṛtaiśceṣṭaḥ padmakośīracandanaiḥ" },
      { type: "verse", number: "98", sanskrit: "दूर्वामधुकमञ्जिष्ठाकेसरैर्वाघृताप्लुतैः चन्दनाद्येन तैलेन शतधौतेन सर्पिषा अभ्यङ्गः पयसासेकः शस्तश्चमधुकाम्बुना", text: "dūrvāmadhukamañjiṣṭhākesarairvāghṛtāplutaiḥ candanādyena tailena śatadhautena sarpiṣā abhyaṅgaḥ payasāsekaḥ śastaścamadhukāmbunā" },
      { type: "verse", number: "99", sanskrit: "प्रायेणोपहताग्नित्वात् सपिच्छमतिसार्यते तस्यातिसारग्रहणीविहितं हितमौषधम् सनागरानिन्द्रयवान् पाययेत्तण्डुलाम्बना", text: "prāyeṇopahatāgnitvāt sapicchamatisāryate tasyātisāragrahaṇīvihitaṃ hitamauṣadham sanāgarānindrayavān pāyayettaṇḍulāmbanā" },
      { type: "verse", number: "100", sanskrit: "जीर्णेषु तेषु पेयां च चाङ्गेरीतक्रदाडिमः पाठानिम्बयवानीनां चूर्णं तक्रेण वा पिबेत्", text: "jīrṇeṣu teṣu peyāṃ ca cāṅgerītakradāḍimaḥ pāṭhānimbayavānīnāṃ cūrṇaṃ takreṇa vā pibet" },
      { type: "verse", number: "101", sanskrit: "सुरया वाप्लुतां पाठां सनागरदुरालभाम् जम्ब्वाम्रबिल्वमध्यं वा सकपित्थं सनागरम्", text: "surayā vāplutāṃ pāṭhāṃ sanāgaradurālabhām jambvāmrabilvamadhyaṃ vā sakapitthaṃ sanāgaram" },
      { type: "verse", number: "102", sanskrit: "पेयामण्डेन योगैश्च पाठाद्यैः कारयेत् त्रिभिः ससूप्यधान्यान् सस्नेहान् साल्मान् सलवणान् खलान् वेतसार्जुनजम्बूनां मृणालीकृष्णगन्धयोः", text: "peyāmaṇḍena yogaiśca pāṭhādyaiḥ kārayet tribhiḥ sasūpyadhānyān sasnehān sālmān salavaṇān khalān vetasārjunajambūnāṃ mṛṇālīkṛṣṇagandhayoḥ" },
      { type: "verse", number: "103", sanskrit: "श्रापण्या मातुलुङ्गस्य धातक्या दाडिमस्य च चाङ्गेर्या मदयन्त्याश्च यूथिकायाश्च पल्लवैः", text: "śrāpaṇyā mātuluṅgasya dhātakyā dāḍimasya ca cāṅgeryā madayantyāśca yūthikāyāśca pallavaiḥ" },
      { type: "verse", number: "104", sanskrit: "कालविद्दुग्धिकायाश्च चुक्रिकायाश्च योजयेत् खलान्दधिसरोपेतान्ससर्पिष्कान्सदाडिमान् रोचनान् दीपनान् दद्यादतीसारहरान् परम्", text: "kālaviddugdhikāyāśca cukrikāyāśca yojayet khalāndadhisaropetānsasarpiṣkānsadāḍimān rocanān dīpanān dadyādatīsāraharān param" },
      { type: "verse", number: "105", sanskrit: "पुरीषं यत्नतो रक्षेच्छुष्यतो राजयक्ष्मिणः सर्वधातुक्षयार्तस्य बलं तस्य हि विड्बलम्", text: "purīṣaṃ yatnato rakṣecchuṣyato rājayakṣmiṇaḥ sarvadhātukṣayārtasya balaṃ tasya hi viḍbalam" },
      { type: "verse", number: "106", sanskrit: "ज्वरादिष्वपि कुर्वीत विकारेषु यथामयम् बह्वामयसमूहो हि यक्ष्मातः सो ऽतिदुःसहः", text: "jvarādiṣvapi kurvīta vikāreṣu yathāmayam bahvāmayasamūho hi yakṣmātaḥ so 'tiduḥsahaḥ" },
      { type: "verse", number: "107", sanskrit: "अजां वा पर्युपासीत षण्मासानुटजे वसन् तत्पयोमूत्रविड्वृत्तिपरिषेकप्रघर्षणः ताभिः परिवृतः स्वप्यात्तच्छकृद्रेणुसङ्करे", text: "ajāṃ vā paryupāsīta ṣaṇmāsānuṭaje vasan tatpayomūtraviḍvṛttipariṣekapragharṣaṇaḥ tābhiḥ parivṛtaḥ svapyāttacchakṛdreṇusaṅkare" },
      { type: "verse", number: "108", sanskrit: "एतद्रसायनं श्रेष्ठं रोगराजस्य नाशनम् अजाशकृद्रसक्षीरदधिमूत्रैः शृतं घृतम्", text: "etadrasāyanaṃ śreṣṭhaṃ rogarājasya nāśanam ajāśakṛdrasakṣīradadhimūtraiḥ śṛtaṃ ghṛtam" },
      { type: "verse", number: "109", sanskrit: "सपञ्चपटु पञ्चाजं क्षयी क्षीरानुपः पिबेत् मांसमेवाश्नतो युक्त्या मार्द्वीकं पिबतो ऽनु च", text: "sapañcapaṭu pañcājaṃ kṣayī kṣīrānupaḥ pibet māṃsamevāśnato yuktyā mārdvīkaṃ pibato 'nu ca" },
      { type: "verse", number: "110", sanskrit: "अविधारितवेगस्य लक्ष्मा न लभते ऽन्तरम् सुरां समण्डां मार्द्वीकमरिष्टान् शीधुमाधवान्", text: "avidhāritavegasya lakṣmā na labhate 'ntaram surāṃ samaṇḍāṃ mārdvīkamariṣṭān śīdhumādhavān" },
      { type: "verse", number: "111", sanskrit: "यथार्हमनुपानार्थं पिबेन्मांसानि भक्षयन् स्रोतोविबन्धमोक्षार्थं बलौजःपुष्टये च तत्", text: "yathārhamanupānārthaṃ pibenmāṃsāni bhakṣayan srotovibandhamokṣārthaṃ balaujaḥpuṣṭaye ca tat" },
      { type: "verse", number: "112", sanskrit: "स्नेहक्षीराम्बुकोष्ठेषु स्वभ्यक्तमवगाहयेत् उत्तीर्णं मिश्रकस्नेहैः पुनरक्तं सुखैः करैः मृद्नीयात् सुखमारीनं सुखं चोद्वर्तयेत् परम्", text: "snehakṣīrāmbukoṣṭheṣu svabhyaktamavagāhayet uttīrṇaṃ miśrakasnehaiḥ punaraktaṃ sukhaiḥ karaiḥ mṛdnīyāt sukhamārīnaṃ sukhaṃ codvartayet param" },
      { type: "verse", number: "113", sanskrit: "जीवन्तीं शतवीर्यां च विकसां सपुनर्नवाम् अश्वगन्धामपामार्गं तर्कारीं मधुकं बलम्", text: "jīvantīṃ śatavīryāṃ ca vikasāṃ sapunarnavām aśvagandhāmapāmārgaṃ tarkārīṃ madhukaṃ balam" },
      { type: "verse", number: "114", sanskrit: "विदारीं सर्षपान् कुष्ठं तण्डुलानतसीफलम् माषांस्तिलांश्च किण्वं च सर्वमेकत्र चूर्णयेत्", text: "vidārīṃ sarṣapān kuṣṭhaṃ taṇḍulānatasīphalam māṣāṃstilāṃśca kiṇvaṃ ca sarvamekatra cūrṇayet" },
      { type: "verse", number: "115", sanskrit: "यवचूर्णं त्रिगुणितं दध्ना युक्तं समाक्षिकम् एतदुद्वर्तनं कार्यं पुष्टिवर्णबलप्रदम्", text: "yavacūrṇaṃ triguṇitaṃ dadhnā yuktaṃ samākṣikam etadudvartanaṃ kāryaṃ puṣṭivarṇabalapradam" },
      { type: "verse", number: "116", sanskrit: "गौरसर्षपकल्केन स्नानीयौषधिभिश्च सः स्नायादृतुसुखैस्तोयैर्जीवनीयोपसाधितैः", text: "gaurasarṣapakalkena snānīyauṣadhibhiśca saḥ snāyādṛtusukhaistoyairjīvanīyopasādhitaiḥ" },
      { type: "verse", number: "117", sanskrit: "गन्धमाल्यादिकां भूषामलक्ष्मीनाशनीं भजेत् सुहृदां दर्शनं गीतवादित्रोत्सवसंश्रुतीः", text: "gandhamālyādikāṃ bhūṣāmalakṣmīnāśanīṃ bhajet suhṛdāṃ darśanaṃ gītavāditrotsavasaṃśrutīḥ" },
      { type: "verse", number: "118", sanskrit: "बस्तयः क्षीरसर्पींषि मद्यं मांसं सुशीलता दैवव्यपाश्रयं तद्वदथर्वोक्तं च पूजितम्", text: "bastayaḥ kṣīrasarpīṃṣi madyaṃ māṃsaṃ suśīlatā daivavyapāśrayaṃ tadvadatharvoktaṃ ca pūjitam" },
      { type: "verse", number: "119", sanskrit: "इष्ट्या यया च चन्द्रस्य राजयक्ष्मा पुरा जितः पुरोहितः प्रयुञ्जीत वेदोक्तां तां जितात्मनः इति सप्तमो ऽध्यायः", text: "iṣṭyā yayā ca candrasya rājayakṣmā purā jitaḥ purohitaḥ prayuñjīta vedoktāṃ tāṃ jitātmanaḥ iti saptamo 'dhyāyaḥ" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 8,
    lang: "sa",
    content: [
      { type: "heading", heading: "Аршас чикитса — лечение геморроя" },
      { type: "text", text: "Глава 8 Чикитса стханы — лечебный раздел о лечение геморроя. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातः छर्द्रिहृद्रोगतृष्णाचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ chardrihṛdrogatṛṣṇācikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "आमाशयोत्क्लेशभवाः प्रायश्छर्द्यो हितं ततः लङ्घनं प्रागृते वायोः वमनं तत्र योजयेत्", text: "āmāśayotkleśabhavāḥ prāyaśchardyo hitaṃ tataḥ laṅghanaṃ prāgṛte vāyoḥ vamanaṃ tatra yojayet" },
      { type: "verse", number: "3", sanskrit: "बलिनो बहुदोषस्य वमतः प्रततं बहु ततो विरेकं क्रमशो हृद्यं मद्यैः फलाम्बुभिः", text: "balino bahudoṣasya vamataḥ pratataṃ bahu tato virekaṃ kramaśo hṛdyaṃ madyaiḥ phalāmbubhiḥ" },
      { type: "verse", number: "4", sanskrit: "क्षीरैर्वा सह स ह्यूर्ध्वं गतं दोषं नयत्यधः शमनं चौषधं रूक्षदुर्बलस्य तदेव तु", text: "kṣīrairvā saha sa hyūrdhvaṃ gataṃ doṣaṃ nayatyadhaḥ śamanaṃ cauṣadhaṃ rūkṣadurbalasya tadeva tu" },
      { type: "verse", number: "5", sanskrit: "परिशुष्कं प्रियं सात्म्यमन्नं लघु च शस्यते उपवासस्तथा यूषा रसाः काम्बलिकाः खलाः", text: "pariśuṣkaṃ priyaṃ sātmyamannaṃ laghu ca śasyate upavāsastathā yūṣā rasāḥ kāmbalikāḥ khalāḥ" },
      { type: "verse", number: "6", sanskrit: "शाकानि लेहा भोज्यानि रागषाडवपानकाः भक्ष्याः शुष्का विचित्राश्च फलानि स्नानघर्षणम्", text: "śākāni lehā bhojyāni rāgaṣāḍavapānakāḥ bhakṣyāḥ śuṣkā vicitrāśca phalāni snānagharṣaṇam" },
      { type: "verse", number: "7", sanskrit: "गन्धाः सुगन्धयो गन्धफलपुष्पान्न पानजाः भुक्तमात्रस्य सहसा मुखे शीताम्बुसेचनम्", text: "gandhāḥ sugandhayo gandhaphalapuṣpānna pānajāḥ bhuktamātrasya sahasā mukhe śītāmbusecanam" },
      { type: "verse", number: "8", sanskrit: "हन्ति मारुतजां छार्दिं सर्पिः पीतं ससैन्धवम् किञ्चिदुष्णं विशेषेण सकासहृदयद्रवाम्", text: "hanti mārutajāṃ chārdiṃ sarpiḥ pītaṃ sasaindhavam kiñciduṣṇaṃ viśeṣeṇa sakāsahṛdayadravām" },
      { type: "verse", number: "9", sanskrit: "व्योषत्रिलवणाढ्यं वा सिद्धं वा दाडिमाम्बुना सशुण्ठीदधिधान्येन पीतं तुल्याम्बु वा पयः", text: "vyoṣatrilavaṇāḍhyaṃ vā siddhaṃ vā dāḍimāmbunā saśuṇṭhīdadhidhānyena pītaṃ tulyāmbu vā payaḥ" },
      { type: "verse", number: "10", sanskrit: "व्यक्तसैन्धवसर्पिर्वा फलाम्लो वैष्किरो रसः स्निग्धं च भोजनं शुण्ठीदधिदाडिमसाधितम् कोष्णं सलवणं चात्र हितं स्नेहविरेचनम्", text: "vyaktasaindhavasarpirvā phalāmlo vaiṣkiro rasaḥ snigdhaṃ ca bhojanaṃ śuṇṭhīdadhidāḍimasādhitam koṣṇaṃ salavaṇaṃ cātra hitaṃ snehavirecanam" },
      { type: "verse", number: "11", sanskrit: "पित्तजायां विरेकाथ द्राक्षेक्षुस्वरसैस्त्रिवृत् सर्पिर्वा तैल्वकं योज्यं वृद्धं च श्लेष्मधामगम्", text: "pittajāyāṃ virekātha drākṣekṣusvarasaistrivṛt sarpirvā tailvakaṃ yojyaṃ vṛddhaṃ ca śleṣmadhāmagam" },
      { type: "verse", number: "12", sanskrit: "ऊर्ध्वमेव हरेत् पित्तं स्वादुतिक्तैर्विशुद्धिमान् पिबेन्मन्थं यवागूं वा लाजैः समधुशर्करैः गुद्गजाङ्गलजैरद्याद्व्यञ्जनैः शालिषष्टिकम्", text: "ūrdhvameva haret pittaṃ svādutiktairviśuddhimān pibenmanthaṃ yavāgūṃ vā lājaiḥ samadhuśarkaraiḥ gudgajāṅgalajairadyādvyañjanaiḥ śāliṣaṣṭikam" },
      { type: "verse", number: "13", sanskrit: "मृद्भृष्टलोष्टप्रभवं सुशीतं सलिलं पिबेत् मुद्गोशीरकणाधान्यैः सह वा संस्थितं निशाम् द्राक्षारसं रसञ्चेक्षोर्गुडूच्यम्बु पयो ऽपि", text: "mṛdbhṛṣṭaloṣṭaprabhavaṃ suśītaṃ salilaṃ pibet mudgośīrakaṇādhānyaiḥ saha vā saṃsthitaṃ niśām drākṣārasaṃ rasañcekṣorguḍūcyambu payo 'pi" },
      { type: "verse", number: "14", sanskrit: "जम्ब्वाम्रपल्लवोशीरवटाश्वत्थाङ्कुरोद्भवः क्वाथः क्षौद्रयुतः पीतः शीतो वा विनियच्छति", text: "jambvāmrapallavośīravaṭāśvatthāṅkurodbhavaḥ kvāthaḥ kṣaudrayutaḥ pītaḥ śīto vā viniyacchati" },
      { type: "verse", number: "15", sanskrit: "छर्दिं ज्वरमतीसारं मूर्छां तृष्णां च दुर्जयाम् धात्रीरसेन शीतं वा पिबेन्मुद्गदलाम्बु वा", text: "chardiṃ jvaramatīsāraṃ mūrchāṃ tṛṣṇāṃ ca durjayām dhātrīrasena śītaṃ vā pibenmudgadalāmbu vā" },
      { type: "verse", number: "16", sanskrit: "कोलमज्जासितालाजमक्षिकाविट्कणाञ्जनम् कोलास्थिमज्जास्रोतोजलाजोत्पलरजांसि वा", text: "kolamajjāsitālājamakṣikāviṭkaṇāñjanam kolāsthimajjāsrotojalājotpalarajāṃsi vā" },
      { type: "verse", number: "17", sanskrit: "लिह्यात् क्षौद्रेण पथ्यां वा द्राक्षां वा बदराणि वा पिबेच्छीताम्बुना शालिस्वर्णगैरिकजं रजः पिष्टं वा चन्दनद्राक्षामांसीसेव्याम्बुगैरिकम्", text: "lihyāt kṣaudreṇa pathyāṃ vā drākṣāṃ vā badarāṇi vā pibecchītāmbunā śālisvarṇagairikajaṃ rajaḥ piṣṭaṃ vā candanadrākṣāmāṃsīsevyāmbugairikam" },
      { type: "verse", number: "18", sanskrit: "शालितण्डुलतोयेन पिबेद्वा ससितामधु मधूकमधुकद्राक्षाकमलामलकाम्बुदम्", text: "śālitaṇḍulatoyena pibedvā sasitāmadhu madhūkamadhukadrākṣākamalāmalakāmbudam" },
      { type: "verse", number: "19", sanskrit: "ससारिवापरूषाक्षं मूर्वां वा माक्षिकान्विताम् मधुकं सात्मगुप्तं वा शीतं धात्रीरसेन वा", text: "sasārivāparūṣākṣaṃ mūrvāṃ vā mākṣikānvitām madhukaṃ sātmaguptaṃ vā śītaṃ dhātrīrasena vā" },
      { type: "verse", number: "20", sanskrit: "कफजायां वमेन्निम्बकृष्णापिण्डीतसर्षपैः युक्तेन कोष्णतोयेन दुर्बलं चोपवासयेत्", text: "kaphajāyāṃ vamennimbakṛṣṇāpiṇḍītasarṣapaiḥ yuktena koṣṇatoyena durbalaṃ copavāsayet" },
      { type: "verse", number: "21", sanskrit: "आरग्वधादेर्निर्यूहं शीतं क्षौद्रयुतं पिबेत् त्रिफलाकणचव्याद्वा पेयां पत्रैः करञ्जजैः", text: "āragvadhāderniryūhaṃ śītaṃ kṣaudrayutaṃ pibet triphalākaṇacavyādvā peyāṃ patraiḥ karañjajaiḥ" },
      { type: "verse", number: "22", sanskrit: "मन्थान्यवैर्वा बहुशश्छर्दिघ्नौषधभावितैः कफघ्नमन्नं हृद्यं च रागाः सार्जकभूस्तृणाः", text: "manthānyavairvā bahuśaśchardighnauṣadhabhāvitaiḥ kaphaghnamannaṃ hṛdyaṃ ca rāgāḥ sārjakabhūstṛṇāḥ" },
      { type: "verse", number: "23", sanskrit: "लीढं मनश्शिलाकृष्णामरिचं बीजपूरकात् स्वरसेन कपित्थाच्च सक्षौद्रेण वमिं जयेत्", text: "līḍhaṃ manaśśilākṛṣṇāmaricaṃ bījapūrakāt svarasena kapitthācca sakṣaudreṇa vamiṃ jayet" },
      { type: "verse", number: "24", sanskrit: "समुस्तां मधुना शृङ्गीं कोलाम्लं वा सजाम्बवम् तद्वद्विडङ्गत्रिफलाकृमिघ्नपरिपेलवम्", text: "samustāṃ madhunā śṛṅgīṃ kolāmlaṃ vā sajāmbavam tadvadviḍaṅgatriphalākṛmighnaparipelavam" },
      { type: "verse", number: "25", sanskrit: "तद्वद्दुरालभां खादेत् कपित्थं त्र्यूषणेन वा अनुकूलोपचारेण याति द्विष्टार्थजा शमम्", text: "tadvaddurālabhāṃ khādet kapitthaṃ tryūṣaṇena vā anukūlopacāreṇa yāti dviṣṭārthajā śamam" },
      { type: "verse", number: "26", sanskrit: "कृमिजा कृमिहृद्रोगगदितैश्च भिषग्जितैः यथास्वं परिशिष्टाश्च तत्कृताश्च तथामयाः", text: "kṛmijā kṛmihṛdrogagaditaiśca bhiṣagjitaiḥ yathāsvaṃ pariśiṣṭāśca tatkṛtāśca tathāmayāḥ" },
      { type: "verse", number: "27", sanskrit: "त्वरमाणो जयेच्छर्दिं प्रसक्तामनुबन्धिनीम् कोष्ठाश्रयमहामर्मपीडाकरतरा हि सा", text: "tvaramāṇo jayecchardiṃ prasaktāmanubandhinīm koṣṭhāśrayamahāmarmapīḍākaratarā hi sā" },
      { type: "verse", number: "28", sanskrit: "नचान्नेन विना कायस्तन्मयो वर्तते ऽपि च धातुक्षयो ऽतिवमथौ समीरणसमीरणात्", text: "nacānnena vinā kāyastanmayo vartate 'pi ca dhātukṣayo 'tivamathau samīraṇasamīraṇāt" },
      { type: "verse", number: "29", sanskrit: "नियतं जायते तस्माद्द्रुतं तत्र प्रयोजयेत् प्रच्छर्दनातियोगोक्तं क्रमं स्तम्भनबृंहणम्", text: "niyataṃ jāyate tasmāddrutaṃ tatra prayojayet pracchardanātiyogoktaṃ kramaṃ stambhanabṛṃhaṇam" },
      { type: "verse", number: "30", sanskrit: "सर्पिर्गुडान् रसान् क्षीरं घृतं कल्याणजीवनम् धान्वन्तरं त्र्यूषणं वा दोषदेहानुरोधतः", text: "sarpirguḍān rasān kṣīraṃ ghṛtaṃ kalyāṇajīvanam dhānvantaraṃ tryūṣaṇaṃ vā doṣadehānurodhataḥ" },
      { type: "verse", number: "31", sanskrit: "हृद्रोगचिकित्सितम् हृद्रोगे वातजे तैलं मस्तुसौवीरतक्रवत् पिबेत् सुखोष्णं सबिडं गुल्मानाहार्तिजिच्च तत्", text: "hṛdrogacikitsitam hṛdroge vātaje tailaṃ mastusauvīratakravat pibet sukhoṣṇaṃ sabiḍaṃ gulmānāhārtijicca tat" },
      { type: "verse", number: "32", sanskrit: "तलं च लवणैः सिद्धं समूत्राम्लं तथागुणम् बिल्वं रास्नां यवान् कोलं देवदारु पुनर्नवम्", text: "talaṃ ca lavaṇaiḥ siddhaṃ samūtrāmlaṃ tathāguṇam bilvaṃ rāsnāṃ yavān kolaṃ devadāru punarnavam" },
      { type: "verse", number: "33", sanskrit: "कुलत्थान् पञ्चमूलं च पक्त्वा तस्मिन् जले पचेत् तैलं तन्नावने पाने बस्तौ च विनियोजयेत्", text: "kulatthān pañcamūlaṃ ca paktvā tasmin jale pacet tailaṃ tannāvane pāne bastau ca viniyojayet" },
      { type: "verse", number: "34", sanskrit: "शुण्ठीवयस्थालवणकायस्थाहिङ्गुपौष्करैः पथ्यया च शृतं पार्श्वहृद्रुजागुल्मजिद्घृतम्", text: "śuṇṭhīvayasthālavaṇakāyasthāhiṅgupauṣkaraiḥ pathyayā ca śṛtaṃ pārśvahṛdrujāgulmajidghṛtam" },
      { type: "verse", number: "35", sanskrit: "सौवर्चलस्य द्विपले पथ्यापञ्चाशदन्विते घृतस्य साधितः प्रस्था हृद्रोगश्वासगुल्मनुत्", text: "sauvarcalasya dvipale pathyāpañcāśadanvite ghṛtasya sādhitaḥ prasthā hṛdrogaśvāsagulmanut" },
      { type: "verse", number: "36", sanskrit: "दाडिमं कृष्णलवणं हिङ्गुशुण्ठ्यम्लवेतसम् अपतन्त्रकहृद्रोगश्वासघ्नं चूर्णमुत्तमम्", text: "dāḍimaṃ kṛṣṇalavaṇaṃ hiṅguśuṇṭhyamlavetasam apatantrakahṛdrogaśvāsaghnaṃ cūrṇamuttamam" },
      { type: "verse", number: "37", sanskrit: "पुष्कराह्वशठीशुण्ठीबीजपूरजटाभयाः पीताः कल्कीकृताः क्षारघृताम्ललवणैर्युताः विकर्तिकाशूलहरा क्वाथः कोष्णश्च तद्गुणः", text: "puṣkarāhvaśaṭhīśuṇṭhībījapūrajaṭābhayāḥ pītāḥ kalkīkṛtāḥ kṣāraghṛtāmlalavaṇairyutāḥ vikartikāśūlaharā kvāthaḥ koṣṇaśca tadguṇaḥ" },
      { type: "verse", number: "38", sanskrit: "यवानीलवणक्षारवचाजाज्यौषधैः कृतः सपीतदारुबीजाह्वपलाशशठिपौष्करैः", text: "yavānīlavaṇakṣāravacājājyauṣadhaiḥ kṛtaḥ sapītadārubījāhvapalāśaśaṭhipauṣkaraiḥ" },
      { type: "verse", number: "39", sanskrit: "पञ्चकोलशठीपथ्यागुडबीजाह्वपौष्करम् वारुणीकल्कितं भृष्टं यमके लवणान्वितम्", text: "pañcakolaśaṭhīpathyāguḍabījāhvapauṣkaram vāruṇīkalkitaṃ bhṛṣṭaṃ yamake lavaṇānvitam" },
      { type: "verse", number: "40", sanskrit: "हृत्पार्श्वयोनिशूलेषु खादेत् गुल्मोदरेषु च स्निग्धाश्चेह हिताः स्वेदाः संस्कृतानि घृतानि च", text: "hṛtpārśvayoniśūleṣu khādet gulmodareṣu ca snigdhāśceha hitāḥ svedāḥ saṃskṛtāni ghṛtāni ca" },
      { type: "verse", number: "41", sanskrit: "लघुना पञ्चमूलेन शुण्ठ्या वा साधितं जलम् वारुणीदधिमण्डं वा धान्याम्लं वा पिबेत्तृषि", text: "laghunā pañcamūlena śuṇṭhyā vā sādhitaṃ jalam vāruṇīdadhimaṇḍaṃ vā dhānyāmlaṃ vā pibettṛṣi" },
      { type: "verse", number: "42", sanskrit: "सायामस्तम्भशूलामे हृदि मारुतदूषिते क्रियषा सद्रवायामपमोहे तु हिता रसाः", text: "sāyāmastambhaśūlāme hṛdi mārutadūṣite kriyaṣā sadravāyāmapamohe tu hitā rasāḥ" },
      { type: "verse", number: "43", sanskrit: "स्नेहाढ्यास्तित्तिरिक्रौञ्चशिखिवर्तकदक्षजाः बलातैलं सहृद्रोगी पिबेद्वा सुकुमारकम्", text: "snehāḍhyāstittirikrauñcaśikhivartakadakṣajāḥ balātailaṃ sahṛdrogī pibedvā sukumārakam" },
      { type: "verse", number: "44", sanskrit: "यष्ट्याह्वशतपाकं वा महास्नेहं तथोत्तमम् रास्नाजीवकजीवन्तीबलाव्याघ्रीपुनर्नवैः", text: "yaṣṭyāhvaśatapākaṃ vā mahāsnehaṃ tathottamam rāsnājīvakajīvantībalāvyāghrīpunarnavaiḥ" },
      { type: "verse", number: "45", sanskrit: "भार्ङ्गीस्थिरावचाव्योषैर्महास्नेहं विपाचयेत् दधिपादं तथाम्लैश्च लाभतः स निषेवितः तर्पणो बृंहणो बल्यो वातहृद्रोगनाशनः", text: "bhārṅgīsthirāvacāvyoṣairmahāsnehaṃ vipācayet dadhipādaṃ tathāmlaiśca lābhataḥ sa niṣevitaḥ tarpaṇo bṛṃhaṇo balyo vātahṛdroganāśanaḥ" },
      { type: "verse", number: "46", sanskrit: "त्र्यूषणत्रिफलापाठमधूकं मधुकं चुटी पञ्चमूलं लघु बले मेदे ऋद्दिः शतावरी", text: "tryūṣaṇatriphalāpāṭhamadhūkaṃ madhukaṃ cuṭī pañcamūlaṃ laghu bale mede ṛddiḥ śatāvarī" },
      { type: "verse", number: "47", sanskrit: "कण्डूकरी तामलकी जीवकं चाक्षसंमितैः तैः पचेत् सर्पिषः प्रस्थं दध्नः प्रस्थेन माहिषात्", text: "kaṇḍūkarī tāmalakī jīvakaṃ cākṣasaṃmitaiḥ taiḥ pacet sarpiṣaḥ prasthaṃ dadhnaḥ prasthena māhiṣāt" },
      { type: "verse", number: "48", sanskrit: "युक्तं सिद्धं च मधुना तन्निहन्ति निषेवितम् हृत्पाण्डुग्रहणीदोषकासश्वासहलीमकान्", text: "yuktaṃ siddhaṃ ca madhunā tannihanti niṣevitam hṛtpāṇḍugrahaṇīdoṣakāsaśvāsahalīmakān" },
      { type: "verse", number: "49", sanskrit: "दीप्ते ऽग्नौ सद्रवायामे हृद्रोगे वातिके हितम् क्षीरं दधि गुडः सर्पिरौदकानूपमामिषम्", text: "dīpte 'gnau sadravāyāme hṛdroge vātike hitam kṣīraṃ dadhi guḍaḥ sarpiraudakānūpamāmiṣam" },
      { type: "verse", number: "50", sanskrit: "घृतान्येव च वर्ज्यानि ह्रद्रोगेषु चतुर्ष्वपि शेषेषु स्तम्भजाड्यामसंयुक्ते ऽपि च वातिके कफानुबन्धे तस्मिंस्तु रूक्षोष्णामाचरेत् क्रियाम्", text: "ghṛtānyeva ca varjyāni hradrogeṣu caturṣvapi śeṣeṣu stambhajāḍyāmasaṃyukte 'pi ca vātike kaphānubandhe tasmiṃstu rūkṣoṣṇāmācaret kriyām" },
      { type: "verse", number: "51", sanskrit: "पैत्ते द्राक्षेक्षुनिर्याससिताक्षाद्रपरूषकैः युक्तो विरेको हृद्यः स्यात् क्रमः शुद्धे च पित्तहा", text: "paitte drākṣekṣuniryāsasitākṣādraparūṣakaiḥ yukto vireko hṛdyaḥ syāt kramaḥ śuddhe ca pittahā" },
      { type: "verse", number: "52", sanskrit: "क्षतपित्तज्वरोक्तं च बाह्यान्तःपरिमार्जनम् कट्वीमधुककल्कं च पिबेत् ससितमम्भसा", text: "kṣatapittajvaroktaṃ ca bāhyāntaḥparimārjanam kaṭvīmadhukakalkaṃ ca pibet sasitamambhasā" },
      { type: "verse", number: "53", sanskrit: "श्रेयसीशर्कराद्राक्षाजीवकर्षभकोत्पलैः बलाखर्जूरकाकोलीमेदायुग्मैश्च साधितम्", text: "śreyasīśarkarādrākṣājīvakarṣabhakotpalaiḥ balākharjūrakākolīmedāyugmaiśca sādhitam" },
      { type: "verse", number: "54", sanskrit: "सक्षीरं माहिषं सर्पिः पित्तहृद्रोगनाशनम् प्रपौण्डरीकमधुकबिसग्रन्थिकशेरुकाः", text: "sakṣīraṃ māhiṣaṃ sarpiḥ pittahṛdroganāśanam prapauṇḍarīkamadhukabisagranthikaśerukāḥ" },
      { type: "verse", number: "55", sanskrit: "सशुण्ठीशैवलास्ताभिः सक्षीरं विपचेत् घृतम् शीतं समधु तच्चेष्टं स्वादुवर्गकृतं च यत् बस्तिं च दद्यात् सक्षौद्रं तैलं मधुकसाधितम्", text: "saśuṇṭhīśaivalāstābhiḥ sakṣīraṃ vipacet ghṛtam śītaṃ samadhu tacceṣṭaṃ svāduvargakṛtaṃ ca yat bastiṃ ca dadyāt sakṣaudraṃ tailaṃ madhukasādhitam" },
      { type: "verse", number: "56", sanskrit: "कफोद्भवे वमेत् स्विन्नः पिचुमन्दवचाम्भसा कुलत्थधन्वोत्थरसतीक्ष्णमद्ययवाशनः", text: "kaphodbhave vamet svinnaḥ picumandavacāmbhasā kulatthadhanvottharasatīkṣṇamadyayavāśanaḥ" },
      { type: "verse", number: "57", sanskrit: "पिबेच्चूर्णं वचाहिङ्गुलवणद्वयनागरात् सैला यवानककणा यवक्षारात् सुखाम्बुना", text: "pibeccūrṇaṃ vacāhiṅgulavaṇadvayanāgarāt sailā yavānakakaṇā yavakṣārāt sukhāmbunā" },
      { type: "verse", number: "58", sanskrit: "फलधान्याम्लकौलत्थयूषमूत्रासवैस्तथा पुष्कराह्वाभयाशुण्ठीशठीरास्नावचाकणात् क्वाथं तथाभयाशुण्ठीमाद्रीपीतद्रुकट्फलात्", text: "phaladhānyāmlakaulatthayūṣamūtrāsavaistathā puṣkarāhvābhayāśuṇṭhīśaṭhīrāsnāvacākaṇāt kvāthaṃ tathābhayāśuṇṭhīmādrīpītadrukaṭphalāt" },
      { type: "verse", number: "59", sanskrit: "क्वाथे रौहीतकाश्वत्थखदिरोदुम्बरार्जुने सपलाशवटे व्योषत्रिवृच्चूर्णान्विते कृतः", text: "kvāthe rauhītakāśvatthakhadirodumbarārjune sapalāśavaṭe vyoṣatrivṛccūrṇānvite kṛtaḥ" },
      { type: "verse", number: "60", sanskrit: "सुखोदकानुपानः स्याल्लेहः कफविकारहा श्लेष्मगुल्मोदिताज्यानि क्षारांश्च विविधान् पिबेत्", text: "sukhodakānupānaḥ syāllehaḥ kaphavikārahā śleṣmagulmoditājyāni kṣārāṃśca vividhān pibet" },
      { type: "verse", number: "61", sanskrit: "प्रयोजयेच्छिलाह्रं वा ब्राह्मं चात्र रसायनम् तथामलकलेहं वा प्राशं वागस्त्यनिर्मितम्", text: "prayojayecchilāhraṃ vā brāhmaṃ cātra rasāyanam tathāmalakalehaṃ vā prāśaṃ vāgastyanirmitam" },
      { type: "verse", number: "62", sanskrit: "स्याच्छूलं यस्य भुक्ते ऽति जीर्यत्यल्पं जरां गते शाम्येत् सकुष्ठकृमिजिल्लवणद्वयतिल्वकैः", text: "syācchūlaṃ yasya bhukte 'ti jīryatyalpaṃ jarāṃ gate śāmyet sakuṣṭhakṛmijillavaṇadvayatilvakaiḥ" },
      { type: "verse", number: "63", sanskrit: "सदेवदार्वतिविषैश्चूर्णमुष्णाम्बुना पिबेत् यस्य जीर्णे ऽधिकं स्नेहैः स विरेच्यः फलैःपुनः", text: "sadevadārvativiṣaiścūrṇamuṣṇāmbunā pibet yasya jīrṇe 'dhikaṃ snehaiḥ sa virecyaḥ phalaiḥpunaḥ" },
      { type: "verse", number: "64", sanskrit: "जीर्यत्यन्ने तथा मूलैस्तीक्ष्णैः शूले सदाधिके प्रायो ऽनिलो रुद्धगतिः कुप्यत्यामाशये यतः", text: "jīryatyanne tathā mūlaistīkṣṇaiḥ śūle sadādhike prāyo 'nilo ruddhagatiḥ kupyatyāmāśaye yataḥ" },
      { type: "verse", number: "65", sanskrit: "तस्यानुलोमनं कार्यं शुद्धिलङ्घनपाचनैः कृमिघ्नमौषधं सर्वं कृमिजे हृदयामये", text: "tasyānulomanaṃ kāryaṃ śuddhilaṅghanapācanaiḥ kṛmighnamauṣadhaṃ sarvaṃ kṛmije hṛdayāmaye" },
      { type: "verse", number: "66", sanskrit: "तृष्णाचिकित्सितम् तृष्णासु वातपित्तघ्नो विधिः प्रायेण शस्यते सर्वासु शीतो बाह्यान्तस्तथा शमनशोधनः", text: "tṛṣṇācikitsitam tṛṣṇāsu vātapittaghno vidhiḥ prāyeṇa śasyate sarvāsu śīto bāhyāntastathā śamanaśodhanaḥ" },
      { type: "verse", number: "67", sanskrit: "दिव्याम्बु शीतं सक्षौद्रं तद्वद्भौमं च तद्गुणम् निर्वापितं तप्तलोष्टकपालसिकतादिभिः", text: "divyāmbu śītaṃ sakṣaudraṃ tadvadbhaumaṃ ca tadguṇam nirvāpitaṃ taptaloṣṭakapālasikatādibhiḥ" },
      { type: "verse", number: "68", sanskrit: "सशर्करं वा क्वथितं पञ्चमूलेन वा जलम् दर्भपूर्वेण मन्थश्च प्रशस्तो लाजसक्तुभिः", text: "saśarkaraṃ vā kvathitaṃ pañcamūlena vā jalam darbhapūrveṇa manthaśca praśasto lājasaktubhiḥ" },
      { type: "verse", number: "69", sanskrit: "वाट्यश्चामयवैः शीतः शर्करामाक्षिकान्वितः यवागूः शालिभिस्तद्वत् कोद्रवैश्च चिरन्तनैः", text: "vāṭyaścāmayavaiḥ śītaḥ śarkarāmākṣikānvitaḥ yavāgūḥ śālibhistadvat kodravaiśca cirantanaiḥ" },
      { type: "verse", number: "70", sanskrit: "शीतेन शीतवीर्यैश्च द्रव्यैः सिद्धेन भोजनम् हिमाम्बुपरिषिक्तस्य पयसा ससितामधु", text: "śītena śītavīryaiśca dravyaiḥ siddhena bhojanam himāmbupariṣiktasya payasā sasitāmadhu" },
      { type: "verse", number: "71", sanskrit: "रसैश्चानम्ललवणैर्जाङ्गलैर्घृतभर्जितैः मुद्गादीनां तथा यूषैर्जीवनीयरसान्वितैः", text: "rasaiścānamlalavaṇairjāṅgalairghṛtabharjitaiḥ mudgādīnāṃ tathā yūṣairjīvanīyarasānvitaiḥ" },
      { type: "verse", number: "72", sanskrit: "नस्यं क्षीरघृतं सिद्धं शीतैरिक्षोस्तथा रसः नारीक्षीरेण वा घृष्टमुष्ट्रास्थि ससितं हितम्", text: "nasyaṃ kṣīraghṛtaṃ siddhaṃ śītairikṣostathā rasaḥ nārīkṣīreṇa vā ghṛṣṭamuṣṭrāsthi sasitaṃ hitam" },
      { type: "verse", number: "73", sanskrit: "निर्वापणाश्च गण्डूषाः सूत्रस्थानोदिता हिताः दाहज्वरोक्ता लेपाद्या निरीहत्वं मनोरतिः", text: "nirvāpaṇāśca gaṇḍūṣāḥ sūtrasthānoditā hitāḥ dāhajvaroktā lepādyā nirīhatvaṃ manoratiḥ" },
      { type: "verse", number: "74", sanskrit: "महासरिद्ध्रदादीनां दर्शनस्मरणादि च तृष्णायां पवनोत्थायां सगुडं दधि शस्यते रसाश्च बृंहणाः शीता विदार्यादिगणाम्बु च", text: "mahāsariddhradādīnāṃ darśanasmaraṇādi ca tṛṣṇāyāṃ pavanotthāyāṃ saguḍaṃ dadhi śasyate rasāśca bṛṃhaṇāḥ śītā vidāryādigaṇāmbu ca" },
      { type: "verse", number: "75", sanskrit: "पित्तजायां सितायुक्तः पक्वोदुम्बरजो रसः तत्क्वाथो वा हिमस्तद्वत्सारिवादिगणाम्बु वा", text: "pittajāyāṃ sitāyuktaḥ pakvodumbarajo rasaḥ tatkvātho vā himastadvatsārivādigaṇāmbu vā" },
      { type: "verse", number: "76", sanskrit: "तद्विधैश्च गणः शीतकषायान् ससितामधून् मधुरैरौषधैस्तद्वत् क्षीरिवृक्षैश्च कल्पितान्", text: "tadvidhaiśca gaṇaḥ śītakaṣāyān sasitāmadhūn madhurairauṣadhaistadvat kṣīrivṛkṣaiśca kalpitān" },
      { type: "verse", number: "77", sanskrit: "बीजपूरकमृद्वीकावटवेतसपल्लवान् मूलानि कुशकाशानां यष्ट्याह्वं च जले शृतम्", text: "bījapūrakamṛdvīkāvaṭavetasapallavān mūlāni kuśakāśānāṃ yaṣṭyāhvaṃ ca jale śṛtam" },
      { type: "verse", number: "78", sanskrit: "अपाकशर्कराच्छिन्नरुहालोद्ध्राञ्जनाम्बु वा कार्पसीफलकल्कं वा ससितक्षीरभोजनः", text: "apākaśarkarācchinnaruhāloddhrāñjanāmbu vā kārpasīphalakalkaṃ vā sasitakṣīrabhojanaḥ" },
      { type: "verse", number: "79", sanskrit: "ज्वरोदितं वा द्राक्षादिपञ्चसाराम्बु वा पिबेत्", text: "jvaroditaṃ vā drākṣādipañcasārāmbu vā pibet" },
      { type: "verse", number: "80", sanskrit: "कफोद्भवायां वमनं निम्बप्रसववारिणा बिल्वाढकीपञ्चकोलदर्भपञ्चकसाधितम्", text: "kaphodbhavāyāṃ vamanaṃ nimbaprasavavāriṇā bilvāḍhakīpañcakoladarbhapañcakasādhitam" },
      { type: "verse", number: "81", sanskrit: "जलं पिबेद्रजन्या वा सिद्धं सक्षौद्रशर्करम् मुद्गयूषं च सव्योषपटोलीनिम्बपल्लवम् यवान्नं तीक्ष्णकवलनस्यलेहांश्च शीलयेत्", text: "jalaṃ pibedrajanyā vā siddhaṃ sakṣaudraśarkaram mudgayūṣaṃ ca savyoṣapaṭolīnimbapallavam yavānnaṃ tīkṣṇakavalanasyalehāṃśca śīlayet" },
      { type: "verse", number: "82", sanskrit: "सर्वैरामाच्च तद्धन्त्री क्रियेष्टा वमनं तथा त्र्यूषणारुष्करवचाफलाम्लोष्णाम्बुमस्तुभिः", text: "sarvairāmācca taddhantrī kriyeṣṭā vamanaṃ tathā tryūṣaṇāruṣkaravacāphalāmloṣṇāmbumastubhiḥ" },
      { type: "verse", number: "83", sanskrit: "अन्नात्ययान्मण्डमुष्णं हिमं मन्थं च कालवित् तृषि श्रमान्मांसरसं मन्थं वा ससितं पिबेत्", text: "annātyayānmaṇḍamuṣṇaṃ himaṃ manthaṃ ca kālavit tṛṣi śramānmāṃsarasaṃ manthaṃ vā sasitaṃ pibet" },
      { type: "verse", number: "84", sanskrit: "आतपात् ससितं मन्थं यवकोलजसक्तुभिः सर्वाण्यङ्गानि लिम्पेच्च तिलपिण्याककाञ्जिकैः", text: "ātapāt sasitaṃ manthaṃ yavakolajasaktubhiḥ sarvāṇyaṅgāni limpecca tilapiṇyākakāñjikaiḥ" },
      { type: "verse", number: "85", sanskrit: "शीतस्नानाच्च मद्याम्बु पिबेत्तृड्वान् गुडाम्बु वा मद्यादर्धजलं मद्यं स्नातो ऽम्ललवणैर्युतम्", text: "śītasnānācca madyāmbu pibettṛḍvān guḍāmbu vā madyādardhajalaṃ madyaṃ snāto 'mlalavaṇairyutam" },
      { type: "verse", number: "86", sanskrit: "स्नेहतीक्ष्णतराग्निस्तु स्वभावशिशिरं जलम् स्नेहादुष्णाम्ब्वजीर्णात्तु जीर्णान्मण्डं पिपासितः", text: "snehatīkṣṇatarāgnistu svabhāvaśiśiraṃ jalam snehāduṣṇāmbvajīrṇāttu jīrṇānmaṇḍaṃ pipāsitaḥ" },
      { type: "verse", number: "87", sanskrit: "पिबेत् स्निग्धान्नतृषितो हिमस्पर्धि गुडोदकम् गुर्वाद्यन्नेन तृषितः पीत्वोष्णाम्बु तदुल्लिखेत्", text: "pibet snigdhānnatṛṣito himaspardhi guḍodakam gurvādyannena tṛṣitaḥ pītvoṣṇāmbu tadullikhet" },
      { type: "verse", number: "88", sanskrit: "क्षयजायां क्षयहितं सर्वं बृंहणमौषधम् कृशदुर्बलरूक्षाणां क्षीरं छागो रसो ऽथवा क्षीरं च सोर्ध्ववातायां क्षयकासहरैः शृतम्", text: "kṣayajāyāṃ kṣayahitaṃ sarvaṃ bṛṃhaṇamauṣadham kṛśadurbalarūkṣāṇāṃ kṣīraṃ chāgo raso 'thavā kṣīraṃ ca sordhvavātāyāṃ kṣayakāsaharaiḥ śṛtam" },
      { type: "verse", number: "89", sanskrit: "रोगोपसर्गजातायां धान्याम्बु ससिताम्धु पाने प्रशस्तं सर्वा च क्रिया रोगाद्यपेक्षया", text: "rogopasargajātāyāṃ dhānyāmbu sasitāmdhu pāne praśastaṃ sarvā ca kriyā rogādyapekṣayā" },
      { type: "verse", number: "90", sanskrit: "तृष्णक् पूर्वामयक्षीणो न लभेत जलं यदि मरणं दीर्घरोगं वा प्राप्नुयात् त्वरितं ततः", text: "tṛṣṇak pūrvāmayakṣīṇo na labheta jalaṃ yadi maraṇaṃ dīrgharogaṃ vā prāpnuyāt tvaritaṃ tataḥ" },
      { type: "verse", number: "91", sanskrit: "सात्म्यान्नपानभौषज्यैस्तृष्णां तस्य जयेत्पुरः तस्यां ज्जितायामन्यो ऽपि व्याधिः शक्यश्चिकित्सितुम्", text: "sātmyānnapānabhauṣajyaistṛṣṇāṃ tasya jayetpuraḥ tasyāṃ jjitāyāmanyo 'pi vyādhiḥ śakyaścikitsitum" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 9,
    lang: "sa",
    content: [
      { type: "heading", heading: "Видрадхи чикитса — лечение абсцессов" },
      { type: "text", text: "Глава 9 Чикитса стханы — лечебный раздел о лечение абсцессов. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो मदात्ययचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto madātyayacikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "यं दोषमधिकं पश्येत्तस्यादौ प्रतिकारयेत् कफस्थानानुपूर्व्या वा तुल्यदोषे मदात्यये पित्तमारुतपर्यन्तः प्रायेण हि मदात्ययः", text: "yaṃ doṣamadhikaṃ paśyettasyādau pratikārayet kaphasthānānupūrvyā vā tulyadoṣe madātyaye pittamārutaparyantaḥ prāyeṇa hi madātyayaḥ" },
      { type: "verse", number: "3", sanskrit: "हीनमिथ्यातिपीतेन यो व्याधिरुपजायते समपीतेन तेनैव स मद्येनोपशाम्यति", text: "hīnamithyātipītena yo vyādhirupajāyate samapītena tenaiva sa madyenopaśāmyati" },
      { type: "verse", number: "4", sanskrit: "मद्यस्य विषसादृश्याद्विषं तूत्कर्षवृत्तिभिः तीक्ष्णादिभिर्गुणैर्योगाद्विषान्तरमपेक्षते", text: "madyasya viṣasādṛśyādviṣaṃ tūtkarṣavṛttibhiḥ tīkṣṇādibhirguṇairyogādviṣāntaramapekṣate" },
      { type: "verse", number: "5", sanskrit: "तीक्ष्णोष्णेनातिमात्रेण पीतेनाम्लविदाहिना मद्येनान्नरसक्लेदो विदग्धः क्षारतां गतः", text: "tīkṣṇoṣṇenātimātreṇa pītenāmlavidāhinā madyenānnarasakledo vidagdhaḥ kṣāratāṃ gataḥ" },
      { type: "verse", number: "6", sanskrit: "यान् कुर्यान्मदतृण्मोहज्वरान्तर्दाहविभ्रमान् मद्योत्क्लिष्टेन दोषेण रुद्धः स्रोतस्सु मारुतः", text: "yān kuryānmadatṛṇmohajvarāntardāhavibhramān madyotkliṣṭena doṣeṇa ruddhaḥ srotassu mārutaḥ" },
      { type: "verse", number: "7", sanskrit: "सुतीव्रा देवना याश्च शिरस्यस्थिषु सन्धिषु जीर्णाममद्यदोषस्य प्रकाङ्क्षालाघवे सति यौगिकं विधिवद्युकं मद्यमेव निहन्ति तान्", text: "sutīvrā devanā yāśca śirasyasthiṣu sandhiṣu jīrṇāmamadyadoṣasya prakāṅkṣālāghave sati yaugikaṃ vidhivadyukaṃ madyameva nihanti tān" },
      { type: "verse", number: "8", sanskrit: "क्षारो हि याति माधुर्यं शीघ्रमम्लोपसंहितः मद्यमम्लेषु च श्रेष्ठं दोषविष्यन्दनादलम्", text: "kṣāro hi yāti mādhuryaṃ śīghramamlopasaṃhitaḥ madyamamleṣu ca śreṣṭhaṃ doṣaviṣyandanādalam" },
      { type: "verse", number: "9", sanskrit: "तीक्ष्णोष्णाद्यैः पुराप्रोक्तैर्दीपनाद्यैस्तथागुणैः सात्म्यत्वाच्च तदेवास्य धातुसाम्यकरं परम्", text: "tīkṣṇoṣṇādyaiḥ purāproktairdīpanādyaistathāguṇaiḥ sātmyatvācca tadevāsya dhātusāmyakaraṃ param" },
      { type: "verse", number: "10", sanskrit: "सप्ताहमष्टरात्रं वा कुर्यात् पानात्ययौषधम् जीर्यत्येतावता पानं कालेन विपथाश्रितम्", text: "saptāhamaṣṭarātraṃ vā kuryāt pānātyayauṣadham jīryatyetāvatā pānaṃ kālena vipathāśritam" },
      { type: "verse", number: "11", sanskrit: "परं ततो ऽनुबध्नाति यो रोगस्तस्य भेषजम् यथायथं प्रयुञ्जीत कृतपानात्ययौषधम्", text: "paraṃ tato 'nubadhnāti yo rogastasya bheṣajam yathāyathaṃ prayuñjīta kṛtapānātyayauṣadham" },
      { type: "verse", number: "12", sanskrit: "तत्र वातोल्बणे मद्यं दद्यात् पिष्टकृतं युतम् बीजपूरकवृक्षाम्लकोलदाडिमदीप्यकैः", text: "tatra vātolbaṇe madyaṃ dadyāt piṣṭakṛtaṃ yutam bījapūrakavṛkṣāmlakoladāḍimadīpyakaiḥ" },
      { type: "verse", number: "13", sanskrit: "यवानीहपुषाजाजीव्योषत्रिलवणार्द्रकैः शूल्यैर्मांसैर्हरितकैः स्नेहवद्भिश्च सक्तुभिः", text: "yavānīhapuṣājājīvyoṣatrilavaṇārdrakaiḥ śūlyairmāṃsairharitakaiḥ snehavadbhiśca saktubhiḥ" },
      { type: "verse", number: "14", sanskrit: "उष्णस्निग्धाम्ललवणा मेद्यमांसरसा हिताः आम्राम्रातकपेशीभिः संस्कृता रागषाडवाः", text: "uṣṇasnigdhāmlalavaṇā medyamāṃsarasā hitāḥ āmrāmrātakapeśībhiḥ saṃskṛtā rāgaṣāḍavāḥ" },
      { type: "verse", number: "15", sanskrit: "गोधूममाषविकृतीर्मृदुचित्रा मुखप्रियाः आर्दिकार्द्रककुल्माषशुक्तमांसादिगर्भिणीः", text: "godhūmamāṣavikṛtīrmṛducitrā mukhapriyāḥ ārdikārdrakakulmāṣaśuktamāṃsādigarbhiṇīḥ" },
      { type: "verse", number: "16", sanskrit: "सुरभिर्लवणा शीता निगदा वाच्छवारुणी स्वरसो दाडिमात् क्वाथः पञ्चमूलात् कनीयसः", text: "surabhirlavaṇā śītā nigadā vācchavāruṇī svaraso dāḍimāt kvāthaḥ pañcamūlāt kanīyasaḥ" },
      { type: "verse", number: "17", sanskrit: "शुण्ठीधान्यात्तथा मस्तु शुक्ताम्भोच्छाम्लकाञ्जिकम् अभ्यङ्गोद्वर्तनस्नानमुष्णं प्रावरणं घनम्", text: "śuṇṭhīdhānyāttathā mastu śuktāmbhocchāmlakāñjikam abhyaṅgodvartanasnānamuṣṇaṃ prāvaraṇaṃ ghanam" },
      { type: "verse", number: "18", sanskrit: "घनश्चागरुजो धूपः पङ्कश्चागरुकुङ्कुमात् कुचोरुश्रोणिशालिन्यो यौवनोष्णाङ्गयष्टयः हर्षेणालिङ्गने युक्ताः प्रियाः संवाहनेषु च", text: "ghanaścāgarujo dhūpaḥ paṅkaścāgarukuṅkumāt kucoruśroṇiśālinyo yauvanoṣṇāṅgayaṣṭayaḥ harṣeṇāliṅgane yuktāḥ priyāḥ saṃvāhaneṣu ca" },
      { type: "verse", number: "19", sanskrit: "पित्तोल्बणे बहुजलं शार्करं मधु वा युतम् रसैर्दाडिमखर्जूरभव्यद्राक्षापरूषजैः", text: "pittolbaṇe bahujalaṃ śārkaraṃ madhu vā yutam rasairdāḍimakharjūrabhavyadrākṣāparūṣajaiḥ" },
      { type: "verse", number: "20", sanskrit: "सुशीतं ससितासक्तु योज्यं तादृक् च पानकम् स्वादुवर्गकसायैर्वा युक्तं मद्यं समाक्षिकम्", text: "suśītaṃ sasitāsaktu yojyaṃ tādṛk ca pānakam svāduvargakasāyairvā yuktaṃ madyaṃ samākṣikam" },
      { type: "verse", number: "21", sanskrit: "शालिषष्टिकमश्नीयाच्छशाजैणकपिञ्जलैः सतीनमुद्गामलकपटोलीदाडिमैरपि", text: "śāliṣaṣṭikamaśnīyācchaśājaiṇakapiñjalaiḥ satīnamudgāmalakapaṭolīdāḍimairapi" },
      { type: "verse", number: "22", sanskrit: "कफपित्तं समुत्क्लिष्टमुल्लिखेत्तृड्विदाहवान् पीत्वाम्बु शीतं मद्यं वा भूरीक्षुरससंयुतम्", text: "kaphapittaṃ samutkliṣṭamullikhettṛḍvidāhavān pītvāmbu śītaṃ madyaṃ vā bhūrīkṣurasasaṃyutam" },
      { type: "verse", number: "23", sanskrit: "द्राक्षारसं वा संसर्गी तर्पणादिः परं हिताम् तथाग्निर्दीप्यते तस्य दोषशेषान्नपाचकः", text: "drākṣārasaṃ vā saṃsargī tarpaṇādiḥ paraṃ hitām tathāgnirdīpyate tasya doṣaśeṣānnapācakaḥ" },
      { type: "verse", number: "24", sanskrit: "कासे सरक्तनिष्ठीवे पार्श्वस्तनरुजासु च तृष्णायां सविदाहायां सोत्क्लेशे हृदयोरसि", text: "kāse saraktaniṣṭhīve pārśvastanarujāsu ca tṛṣṇāyāṃ savidāhāyāṃ sotkleśe hṛdayorasi" },
      { type: "verse", number: "25", sanskrit: "गुडूचीभद्रमुस्तानां पटोलस्याथवा रसम् सनागरं योजयेत तित्तिरिप्रतिभोजनम्", text: "guḍūcībhadramustānāṃ paṭolasyāthavā rasam sanāgaraṃ yojayeta tittiripratibhojanam" },
      { type: "verse", number: "26", sanskrit: "तृष्यते चातिबलवद्वातपित्ते समुद्धते दद्याद्द्राक्षारसं पानं शीतं दोषानुलोमनम्", text: "tṛṣyate cātibalavadvātapitte samuddhate dadyāddrākṣārasaṃ pānaṃ śītaṃ doṣānulomanam" },
      { type: "verse", number: "27", sanskrit: "जीर्णे ऽद्यान्मधुराम्लेन छागमांसरसेन च तृष्यल्पशः पिबेन्मद्यं मदं रक्षन् बहूदकम्", text: "jīrṇe 'dyānmadhurāmlena chāgamāṃsarasena ca tṛṣyalpaśaḥ pibenmadyaṃ madaṃ rakṣan bahūdakam" },
      { type: "verse", number: "28", sanskrit: "मुस्तदाडिमलाजाम्बु जलं वा पर्णिनीशृतम् पाटल्युत्पलकन्दैर्वा स्वभावादेव वा हिमम्", text: "mustadāḍimalājāmbu jalaṃ vā parṇinīśṛtam pāṭalyutpalakandairvā svabhāvādeva vā himam" },
      { type: "verse", number: "29", sanskrit: "मद्यातिपानादब्धातौ क्षीणे तेजसि चोद्धते यः शुष्कगलताल्वोष्ठो जिह्वां निष्कृष्य चेष्टते", text: "madyātipānādabdhātau kṣīṇe tejasi coddhate yaḥ śuṣkagalatālvoṣṭho jihvāṃ niṣkṛṣya ceṣṭate" },
      { type: "verse", number: "30", sanskrit: "पाययेत् कामतो ऽम्भस्तं निशीथपवनाहतम् कोलदाडिमवृक्षाम्लचुक्रीकाचुत्रिकारसः पञ्चाम्लको मुखालेपः सद्यस्तृष्णां नियच्छति", text: "pāyayet kāmato 'mbhastaṃ niśīthapavanāhatam koladāḍimavṛkṣāmlacukrīkācutrikārasaḥ pañcāmlako mukhālepaḥ sadyastṛṣṇāṃ niyacchati" },
      { type: "verse", number: "31", sanskrit: "त्वचं प्राप्तश्च पानोष्मा पित्तरक्ताभिमूर्छितः दाहं प्रकुरुते घोरं विह्वलो येन मुह्यति", text: "tvacaṃ prāptaśca pānoṣmā pittaraktābhimūrchitaḥ dāhaṃ prakurute ghoraṃ vihvalo yena muhyati" },
      { type: "verse", number: "32", sanskrit: "तृष्णादाहपरीतस्य तस्य दाहज्वरापहम् विधिं यथोक्तं युञ्जीत बाह्यान्तः परिमार्जनम्", text: "tṛṣṇādāhaparītasya tasya dāhajvarāpaham vidhiṃ yathoktaṃ yuñjīta bāhyāntaḥ parimārjanam" },
      { type: "verse", number: "33", sanskrit: "प्रभातमारुतोद्धूताः प्रालेयजलवर्षिणः स्मर्यमाणा अपि घ्नन्ति दाहं मलयपादपाः", text: "prabhātamārutoddhūtāḥ prāleyajalavarṣiṇaḥ smaryamāṇā api ghnanti dāhaṃ malayapādapāḥ" },
      { type: "verse", number: "34", sanskrit: "मुक्ताकलापाः शशिरश्मिशुभ्रा मृणालपद्मोत्पलपत्ररम्याः सेकावगाहाः सजला जलार्द्रा वाताः सुशीता मणयो महार्हाः", text: "muktākalāpāḥ śaśiraśmiśubhrā mṛṇālapadmotpalapatraramyāḥ sekāvagāhāḥ sajalā jalārdrā vātāḥ suśītā maṇayo mahārhāḥ" },
      { type: "verse", number: "35", sanskrit: "अलिञ्जराः पद्मपुटापिधानाः प्रवालवर्णा हिमवारिपूर्णाः परिस्रवन्तो दृतयो महान्तः पुत्राः प्रिया दर्पणमण्डलानि", text: "aliñjarāḥ padmapuṭāpidhānāḥ pravālavarṇā himavāripūrṇāḥ parisravanto dṛtayo mahāntaḥ putrāḥ priyā darpaṇamaṇḍalāni" },
      { type: "verse", number: "36", sanskrit: "नार्यश्च नेत्रोत्पलकर्णपूरा मध्यं वयः किञ्चिदिव स्पृशन्त्यः मनो ऽनुकूला हरिचन्दनार्द्रास्तृड्दाहमूर्च्छादवथून् जयन्ति", text: "nāryaśca netrotpalakarṇapūrā madhyaṃ vayaḥ kiñcidiva spṛśantyaḥ mano 'nukūlā haricandanārdrāstṛḍdāhamūrcchādavathūn jayanti" },
      { type: "verse", number: "37", sanskrit: "करेणुकाभिः परिवारितेन विक्षोभणं वारणयूथपेन आस्फालनं शीकरवर्षणं च सिन्धोः स्मरन् दाहतृषोरगम्यः", text: "kareṇukābhiḥ parivāritena vikṣobhaṇaṃ vāraṇayūthapena āsphālanaṃ śīkaravarṣaṇaṃ ca sindhoḥ smaran dāhatṛṣoragamyaḥ" },
      { type: "verse", number: "38", sanskrit: "सरिद्ध्रदानां हिमवद्दरीणां चन्द्रोदयानां कमलाकराणाम् मनोरमान्यापि कथाप्रवृत्ता दाहं च तृष्णां च निहन्ति सद्यः", text: "sariddhradānāṃ himavaddarīṇāṃ candrodayānāṃ kamalākarāṇām manoramānyāpi kathāpravṛttā dāhaṃ ca tṛṣṇāṃ ca nihanti sadyaḥ" },
      { type: "verse", number: "39", sanskrit: "लाजोत्पलोशीरकुचन्दनाम्बु शीताभिधानं मधुशर्कराढ्यम् मद्योद्भवां पित्तकृतां च तृष्णां सदाहशोषां विनिहन्ति पीतम्", text: "lājotpalośīrakucandanāmbu śītābhidhānaṃ madhuśarkarāḍhyam madyodbhavāṃ pittakṛtāṃ ca tṛṣṇāṃ sadāhaśoṣāṃ vinihanti pītam" },
      { type: "verse", number: "40", sanskrit: "प्रियङ्गुपत्रप्लवलोध्रसेव्यद्द्रीबेरकालेयकनागपुष्पैः शीताम्बुपिष्टैर्नवकर्परस्थैस्तृड्दाहहा सर्वशरीरलेपः", text: "priyaṅgupatraplavalodhrasevyaddrīberakāleyakanāgapuṣpaiḥ śītāmbupiṣṭairnavakarparasthaistṛḍdāhahā sarvaśarīralepaḥ" },
      { type: "verse", number: "41", sanskrit: "अशाम्यत्यथवा दाहे रसैस्तृप्तस्य जाङ्गलैः शाखाश्रयां यथान्यायं रोहिणीं व्यधयेत्सिराम्", text: "aśāmyatyathavā dāhe rasaistṛptasya jāṅgalaiḥ śākhāśrayāṃ yathānyāyaṃ rohiṇīṃ vyadhayetsirām" },
      { type: "verse", number: "42", sanskrit: "जल्लेखनोपवासाभ्यां विजयेत कफोल्बणं तृषितो ऽम्बु पिबेत् सिद्धं मुस्तया पर्पटेन वा", text: "jallekhanopavāsābhyāṃ vijayeta kapholbaṇaṃ tṛṣito 'mbu pibet siddhaṃ mustayā parpaṭena vā" },
      { type: "verse", number: "43", sanskrit: "स्थिराशुण्ठीबलोदीच्यदुस्पर्शान्यतमेन वा सिद्धमेतच्च सर्वेषु पानदोषेषु शस्यते", text: "sthirāśuṇṭhībalodīcyadusparśānyatamena vā siddhametacca sarveṣu pānadoṣeṣu śasyate" },
      { type: "verse", number: "44", sanskrit: "निरामं क्षुधितं काले पाययेत् बहुमाक्षिकम् शार्करं मधु वा जीर्णमरिष्टं सीधुमेव वा रूक्षतर्पणसंयुक्तं यवानीनागरान्वितम्", text: "nirāmaṃ kṣudhitaṃ kāle pāyayet bahumākṣikam śārkaraṃ madhu vā jīrṇamariṣṭaṃ sīdhumeva vā rūkṣatarpaṇasaṃyuktaṃ yavānīnāgarānvitam" },
      { type: "verse", number: "45", sanskrit: "यूषेण यवगोधूमं तनुनाल्पेन भोजयेत् उष्णाम्लकटुतिक्तेन कौलत्थेनाल्पसर्पिषा", text: "yūṣeṇa yavagodhūmaṃ tanunālpena bhojayet uṣṇāmlakaṭutiktena kaulatthenālpasarpiṣā" },
      { type: "verse", number: "46", sanskrit: "शुष्कमूलकजैश्छागै रसैर्वा धन्वचारिणाम् साम्लवेतसवृक्षाम्लपटोलीव्योषदाडिमैः", text: "śuṣkamūlakajaiśchāgai rasairvā dhanvacāriṇām sāmlavetasavṛkṣāmlapaṭolīvyoṣadāḍimaiḥ" },
      { type: "verse", number: "47", sanskrit: "प्रभूतशुण्ठीमरिचहरितार्द्रकपेशिकम् बीजपूररसाद्यम्लं भृष्टं नीरसवर्तितम्", text: "prabhūtaśuṇṭhīmaricaharitārdrakapeśikam bījapūrarasādyamlaṃ bhṛṣṭaṃ nīrasavartitam" },
      { type: "verse", number: "48", sanskrit: "करीरकरमर्दादिरोचिष्णुबहुसालनम् प्रव्यक्ताष्टाङ्गलवणं विकल्पितनिमर्दकम् यथाग्नि भक्षयन्मांसं माधवं निगदं पिबेत्", text: "karīrakaramardādirociṣṇubahusālanam pravyaktāṣṭāṅgalavaṇaṃ vikalpitanimardakam yathāgni bhakṣayanmāṃsaṃ mādhavaṃ nigadaṃ pibet" },
      { type: "verse", number: "49", sanskrit: "सितासौवर्चलाजाजीतिन्तिणीकाम्लवेतसम् त्वगेलामरिचार्धांशमष्टाङ्गलवणं हितम् स्रोतोविशुध्यग्निकरं कफप्राये मदात्यये", text: "sitāsauvarcalājājītintiṇīkāmlavetasam tvagelāmaricārdhāṃśamaṣṭāṅgalavaṇaṃ hitam srotoviśudhyagnikaraṃ kaphaprāye madātyaye" },
      { type: "verse", number: "50", sanskrit: "कटुस्कन्धयुतां श्वेतां मृद्वीकां निष्कुलीकृताम् रसेन मातुलुङ्गस्य कलकयेद्दाडिमस्य वा तया क्षौद्रयुतो रागाः कृतो रोचनदीपनः", text: "kaṭuskandhayutāṃ śvetāṃ mṛdvīkāṃ niṣkulīkṛtām rasena mātuluṅgasya kalakayeddāḍimasya vā tayā kṣaudrayuto rāgāḥ kṛto rocanadīpanaḥ" },
      { type: "verse", number: "51", sanskrit: "सौवर्चलैलामरिचदीप्यकाजाजि चोचवत् कार्व्याः कल्पयेदेवं शूक्तं मत्स्यण्डिकान्वितम्", text: "sauvarcalailāmaricadīpyakājāji cocavat kārvyāḥ kalpayedevaṃ śūktaṃ matsyaṇḍikānvitam" },
      { type: "verse", number: "52", sanskrit: "धान्यसौवर्चलाजाजीकारवीमरिचान्वितान् सगुडान् मधुयुक्तेन व्यक्ताम्लान् मरिचोत्कटान्", text: "dhānyasauvarcalājājīkāravīmaricānvitān saguḍān madhuyuktena vyaktāmlān maricotkaṭān" },
      { type: "verse", number: "53", sanskrit: "रूक्षोष्णोद्वर्तनोद्घर्षस्नानभोजनलङ्घनैः सकामाभिः सह स्त्रीभिर्युक्त्या जागरणेन च मदात्ययः कफप्रायः शीघ्रं समुपशाम्यति", text: "rūkṣoṣṇodvartanodgharṣasnānabhojanalaṅghanaiḥ sakāmābhiḥ saha strībhiryuktyā jāgaraṇena ca madātyayaḥ kaphaprāyaḥ śīghraṃ samupaśāmyati" },
      { type: "verse", number: "54", sanskrit: "यदिदं कर्म निर्दिष्टं पृथग्दोषबलं प्रति सन्निपाते दशविधे तच्छेषे ऽपि विकल्पयेत्", text: "yadidaṃ karma nirdiṣṭaṃ pṛthagdoṣabalaṃ prati sannipāte daśavidhe taccheṣe 'pi vikalpayet" },
      { type: "verse", number: "55", sanskrit: "त्वन्नागपुष्पमगधामरिचाजाजिधान्यकैः परूषकमधूकैलासुराह्वैश्च सितान्वितैः", text: "tvannāgapuṣpamagadhāmaricājājidhānyakaiḥ parūṣakamadhūkailāsurāhvaiśca sitānvitaiḥ" },
      { type: "verse", number: "56", sanskrit: "सकपित्थरसं हृद्यं पानकं शशिबोधितम् मदात्ययेषु सर्वेषु पेयं रुच्यग्निदीपनम्", text: "sakapittharasaṃ hṛdyaṃ pānakaṃ śaśibodhitam madātyayeṣu sarveṣu peyaṃ rucyagnidīpanam" },
      { type: "verse", number: "57", sanskrit: "तद्वद्दाडिममृद्वीकाकणाकाश्मर्यदारुभिः सबीजपूरकरसैर्बिडसौवर्चलान्वितम्", text: "tadvaddāḍimamṛdvīkākaṇākāśmaryadārubhiḥ sabījapūrakarasairbiḍasauvarcalānvitam" },
      { type: "verse", number: "58", sanskrit: "फलैर्वा विविधैरम्लैः सत्रिवृच्चूर्णशर्करम् कच्छुदाराङ्कुरद्राक्षावर्षाभूजीरकद्वयम्", text: "phalairvā vividhairamlaiḥ satrivṛccūrṇaśarkaram kacchudārāṅkuradrākṣāvarṣābhūjīrakadvayam" },
      { type: "verse", number: "59", sanskrit: "मधूकयष्टीत्वक्कृष्णाकेसरं श्लक्ष्णचूर्णितम् पिबेदालोड्य दुग्धेन सूक्ष्मतान्तवगालितम्", text: "madhūkayaṣṭītvakkṛṣṇākesaraṃ ślakṣṇacūrṇitam pibedāloḍya dugdhena sūkṣmatāntavagālitam" },
      { type: "verse", number: "60", sanskrit: "नाक्षोभ्य हि मनो मद्यं शरीरमविहन्य वा कुर्यान्मदात्ययं तस्मादिष्यते हर्षणी क्रिया", text: "nākṣobhya hi mano madyaṃ śarīramavihanya vā kuryānmadātyayaṃ tasmādiṣyate harṣaṇī kriyā" },
      { type: "verse", number: "61", sanskrit: "सेव्याः सर्वेन्द्रियसुखा धर्मकल्पद्रुमाङ्कुराः विषयातिशयाः पञ्च शराः कुसुमधन्वनः", text: "sevyāḥ sarvendriyasukhā dharmakalpadrumāṅkurāḥ viṣayātiśayāḥ pañca śarāḥ kusumadhanvanaḥ" },
      { type: "verse", number: "62", sanskrit: "संशुद्धिशमनाद्येषु मददोषः कृतेष्वपि न चेच्छाम्येत् कफे क्षीणे जाते दौर्बल्यलाघवे", text: "saṃśuddhiśamanādyeṣu madadoṣaḥ kṛteṣvapi na cecchāmyet kaphe kṣīṇe jāte daurbalyalāghave" },
      { type: "verse", number: "63", sanskrit: "तस्य मद्यविदग्धस्य वातपित्ताधिकस्य च ग्रीष्मोपतप्तस्य तरोर्यथा वर्षं तथा पयः", text: "tasya madyavidagdhasya vātapittādhikasya ca grīṣmopataptasya taroryathā varṣaṃ tathā payaḥ" },
      { type: "verse", number: "64", sanskrit: "मद्यक्षीणस्य हि क्षीरं क्षीणमाश्वेव पुष्यति ओजस्तुल्यं गुणैः सर्वैर्विपरीतं च मद्यतः", text: "madyakṣīṇasya hi kṣīraṃ kṣīṇamāśveva puṣyati ojastulyaṃ guṇaiḥ sarvairviparītaṃ ca madyataḥ" },
      { type: "verse", number: "65", sanskrit: "पयसा विहते रोगे बले जाते निवर्तयेत् क्षीरप्रयोगं मद्यं च क्रमेणाल्पाल्पमाचरेत्", text: "payasā vihate roge bale jāte nivartayet kṣīraprayogaṃ madyaṃ ca krameṇālpālpamācaret" },
      { type: "verse", number: "66", sanskrit: "न विक्षयध्वंसकोत्थैः स्पृश्येतोपद्रवैर्यथा तयोस्तु स्यात् घृतं क्षीरं बस्तयो बृंहणाः शिवाः अभ्यङ्गोद्वर्तनस्नानान्यन्नपानं च वातजित्", text: "na vikṣayadhvaṃsakotthaiḥ spṛśyetopadravairyathā tayostu syāt ghṛtaṃ kṣīraṃ bastayo bṛṃhaṇāḥ śivāḥ abhyaṅgodvartanasnānānyannapānaṃ ca vātajit" },
      { type: "verse", number: "67", sanskrit: "युक्तमद्यस्य मद्योत्थो न व्याधिरुपजायते अतो ऽस्य वक्ष्यते योगो यः सुखायैव केवलम्", text: "yuktamadyasya madyottho na vyādhirupajāyate ato 'sya vakṣyate yogo yaḥ sukhāyaiva kevalam" },
      { type: "verse", number: "68", sanskrit: "आश्विनं या महत्तेजो बलं सारस्वतं च या दधात्यैन्द्रं च या वीर्यं प्रभावं वैष्णवं च या", text: "āśvinaṃ yā mahattejo balaṃ sārasvataṃ ca yā dadhātyaindraṃ ca yā vīryaṃ prabhāvaṃ vaiṣṇavaṃ ca yā" },
      { type: "verse", number: "69", sanskrit: "अस्त्रं मकरकेतोर्या पुरुषार्थो बलस्य या सौत्रामण्यां द्विजमुखे हुताशे हूयते च या", text: "astraṃ makaraketoryā puruṣārtho balasya yā sautrāmaṇyāṃ dvijamukhe hutāśe hūyate ca yā" },
      { type: "verse", number: "70", sanskrit: "या सर्वौसधिसम्पूर्णान्मथ्यमानात्सुरासुरैः महोदधेः समुद्भूता श्रीशशाङ्कामृतैः सह", text: "yā sarvausadhisampūrṇānmathyamānātsurāsuraiḥ mahodadheḥ samudbhūtā śrīśaśāṅkāmṛtaiḥ saha" },
      { type: "verse", number: "71", sanskrit: "मधुमाधवमैरेयसीधुगौडासवादिभिः मदशाक्तिमनुज्झन्ती या रूपैर्बहुभिः स्थिता", text: "madhumādhavamaireyasīdhugauḍāsavādibhiḥ madaśāktimanujjhantī yā rūpairbahubhiḥ sthitā" },
      { type: "verse", number: "72", sanskrit: "यामास्वाद्य विलासिन्यो यथार्थं नाम बिभ्रति कुलाङ्गनापि यां पीत्वा नयत्युद्धतमानसा", text: "yāmāsvādya vilāsinyo yathārthaṃ nāma bibhrati kulāṅganāpi yāṃ pītvā nayatyuddhatamānasā" },
      { type: "verse", number: "73", sanskrit: "अनङ्गालिङ्गितैरङ्गैः क्वापि चेतो मुनेरपि तरङ्गभङ्गभ्रुकुटीतर्जनैर्मानिनीमनः", text: "anaṅgāliṅgitairaṅgaiḥ kvāpi ceto munerapi taraṅgabhaṅgabhrukuṭītarjanairmāninīmanaḥ" },
      { type: "verse", number: "74", sanskrit: "एकं प्रसाद्य कुरुते या द्वयोरपि निर्वृतिम् यथाकामभटावाप्तिपरिहृष्टाप्सस्रोगणे", text: "ekaṃ prasādya kurute yā dvayorapi nirvṛtim yathākāmabhaṭāvāptiparihṛṣṭāpsasrogaṇe" },
      { type: "verse", number: "75", sanskrit: "तृणवत् पुरुषा युद्धे यामास्वाद्य जहत्यसून् यां शीलयित्वापि चिरं बहुधा बहुविग्रहाम्", text: "tṛṇavat puruṣā yuddhe yāmāsvādya jahatyasūn yāṃ śīlayitvāpi ciraṃ bahudhā bahuvigrahām" },
      { type: "verse", number: "76", sanskrit: "नित्यं हर्षातिवेगेन तत् पूर्वमिव सेवते शोकोद्वेगारतिभयैर्यां दृष्ट्वा नाभिभूयते", text: "nityaṃ harṣātivegena tat pūrvamiva sevate śokodvegāratibhayairyāṃ dṛṣṭvā nābhibhūyate" },
      { type: "verse", number: "77", sanskrit: "गोष्ठीमहोत्सवोद्यानं न यस्याः शोभते विना स्मृत्वा स्मृत्वा च बहुशो वियुक्तः शोचते यया", text: "goṣṭhīmahotsavodyānaṃ na yasyāḥ śobhate vinā smṛtvā smṛtvā ca bahuśo viyuktaḥ śocate yayā" },
      { type: "verse", number: "78", sanskrit: "अप्रसन्नापि या प्रीत्यै प्रसन्ना स्वर्ग एव या अपीन्द्रं मन्यते दुस्स्थं हृद्यस्थितया यया", text: "aprasannāpi yā prītyai prasannā svarga eva yā apīndraṃ manyate dussthaṃ hṛdyasthitayā yayā" },
      { type: "verse", number: "79", sanskrit: "अनिर्देश्यसुखास्वादा स्वसंवेद्यैव या परम् इति चित्रास्ववस्थासु प्रियामनुकरोति या", text: "anirdeśyasukhāsvādā svasaṃvedyaiva yā param iti citrāsvavasthāsu priyāmanukaroti yā" },
      { type: "verse", number: "80", sanskrit: "प्रियातिप्रियतां याति यत् प्रियस्य विशेषतः या प्रीतिर्या रतिर्वाग्या या पुष्टिरिति च स्तुता", text: "priyātipriyatāṃ yāti yat priyasya viśeṣataḥ yā prītiryā ratirvāgyā yā puṣṭiriti ca stutā" },
      { type: "verse", number: "81", sanskrit: "वेददानवगन्धर्वयक्षराक्षसमानुषैः पानप्रवृत्तौ सत्यां तु तां सुरां विधिना पिबेत्", text: "vedadānavagandharvayakṣarākṣasamānuṣaiḥ pānapravṛttau satyāṃ tu tāṃ surāṃ vidhinā pibet" },
      { type: "verse", number: "82", sanskrit: "सम्भवन्ति न ते रोगा मेदोनिलकफोद्भवाः विधियुक्तादृते मद्याद्ये न सिध्यन्ति दारुणाः", text: "sambhavanti na te rogā medonilakaphodbhavāḥ vidhiyuktādṛte madyādye na sidhyanti dāruṇāḥ" },
      { type: "verse", number: "83", sanskrit: "अस्ति देहस्य सावस्था यस्यां पानं निवार्यते अन्यत्र मद्यान्निगदाद्विविधौषधसम्भृतात्", text: "asti dehasya sāvasthā yasyāṃ pānaṃ nivāryate anyatra madyānnigadādvividhauṣadhasambhṛtāt" },
      { type: "verse", number: "84", sanskrit: "आनूपं जाङ्गलं मांसं विधिनाप्युपकल्पितम् मद्यं सहायमप्राप्य सम्यक् परिणमेत् कथम्", text: "ānūpaṃ jāṅgalaṃ māṃsaṃ vidhināpyupakalpitam madyaṃ sahāyamaprāpya samyak pariṇamet katham" },
      { type: "verse", number: "85", sanskrit: "सुतीक्ष्णमारुतव्याधिघातिनो लशुनस्य च मद्यमांसवियुक्तस्य प्रयोगे स्यात् कियान् गुणः", text: "sutīkṣṇamārutavyādhighātino laśunasya ca madyamāṃsaviyuktasya prayoge syāt kiyān guṇaḥ" },
      { type: "verse", number: "86", sanskrit: "निगूढशल्याहरणे शस्त्रक्षाराग्निकर्मणि पीतमद्यो विषहते सुखं वैद्यविकत्थनाम्", text: "nigūḍhaśalyāharaṇe śastrakṣārāgnikarmaṇi pītamadyo viṣahate sukhaṃ vaidyavikatthanām" },
      { type: "verse", number: "87", sanskrit: "अनलोत्तेजनं रुच्यं शोकश्रमविनाशनम् न चातः परमस्त्यन्यदारोग्यबलपुष्टिकृत्", text: "analottejanaṃ rucyaṃ śokaśramavināśanam na cātaḥ paramastyanyadārogyabalapuṣṭikṛt" },
      { type: "verse", number: "88", sanskrit: "रक्षता जीवितं तस्मात् पेयमात्मवता सदा आश्रितोपाश्रितहितं परमं धर्मसाधनम्", text: "rakṣatā jīvitaṃ tasmāt peyamātmavatā sadā āśritopāśritahitaṃ paramaṃ dharmasādhanam" },
      { type: "verse", number: "89", sanskrit: "स्रातः प्रणम्य सुरविप्रगुरून्यथास्वं वृत्तिं विधाय च समस्तपरिग्रहस्य आपानभूमिमथ गन्धजलाभिषिक्तामाहारमण्डपसमीपगतां श्रयेत", text: "srātaḥ praṇamya suravipragurūnyathāsvaṃ vṛttiṃ vidhāya ca samastaparigrahasya āpānabhūmimatha gandhajalābhiṣiktāmāhāramaṇḍapasamīpagatāṃ śrayeta" },
      { type: "verse", number: "90", sanskrit: "स्वास्तृते ऽथ शयने कमनीये मित्रभृत्यरमणीसमवेतः स्वं यशः कथकचारणसङ्घैरुद्धतं निशमयन्नतिलोकम्", text: "svāstṛte 'tha śayane kamanīye mitrabhṛtyaramaṇīsamavetaḥ svaṃ yaśaḥ kathakacāraṇasaṅghairuddhataṃ niśamayannatilokam" },
      { type: "verse", number: "91", sanskrit: "विलासिनीनां च विलासशोभि गीतं सनृत्तं कलतूर्यघोषैः काञ्चीकलापैश्चलकिङ्किणीकैः क्रीडाविहङ्गैश्च कृतानुनादम्", text: "vilāsinīnāṃ ca vilāsaśobhi gītaṃ sanṛttaṃ kalatūryaghoṣaiḥ kāñcīkalāpaiścalakiṅkiṇīkaiḥ krīḍāvihaṅgaiśca kṛtānunādam" },
      { type: "verse", number: "92", sanskrit: "मणिकनकसमुत्थैरावरेयैर्विचित्रैः सजलविविधभाक्तिक्षौमवस्त्रावृताङ्गैः अपि मुनिजनचित्तक्षोभसम्पादनीभिश्चकितहरिणलोलप्रेक्षणीभिः प्रैयाभिः", text: "maṇikanakasamutthairāvareyairvicitraiḥ sajalavividhabhāktikṣaumavastrāvṛtāṅgaiḥ api munijanacittakṣobhasampādanībhiścakitahariṇalolaprekṣaṇībhiḥ praiyābhiḥ" },
      { type: "verse", number: "93", sanskrit: "स्तननितम्बकृतादतिगौरवादलसमाकुलमीश्वरसंश्रयात् इति गतं दधतीभिरसंस्थितं तरुणचित्तविलोभनकार्मणम्", text: "stananitambakṛtādatigauravādalasamākulamīśvarasaṃśrayāt iti gataṃ dadhatībhirasaṃsthitaṃ taruṇacittavilobhanakārmaṇam" },
      { type: "verse", number: "94", sanskrit: "यौवनासवमत्ताभिर्विलासाधिष्ठितात्माभिः सञ्चार्यमाणं युगपत्तन्वङ्गीभिरितस्ततः", text: "yauvanāsavamattābhirvilāsādhiṣṭhitātmābhiḥ sañcāryamāṇaṃ yugapattanvaṅgībhiritastataḥ" },
      { type: "verse", number: "95", sanskrit: "तालवृन्तनलिनीदलानिलैः शीतलीकृतमतीव शीतलैः दर्शने ऽपि विदधद्वशानुगं स्वादितं किमुत चित्तजन्मनः", text: "tālavṛntanalinīdalānilaiḥ śītalīkṛtamatīva śītalaiḥ darśane 'pi vidadhadvaśānugaṃ svāditaṃ kimuta cittajanmanaḥ" },
      { type: "verse", number: "96", sanskrit: "चूतरसेन्दुमृगैः कृतवासं मल्लिकयोज्ज्वलया च सनाथम् स्फटिकशुक्तिगतं सतरङ्गं कान्तमनङ्गमिवोद्वहदङ्गम्", text: "cūtarasendumṛgaiḥ kṛtavāsaṃ mallikayojjvalayā ca sanātham sphaṭikaśuktigataṃ sataraṅgaṃ kāntamanaṅgamivodvahadaṅgam" },
      { type: "verse", number: "97", sanskrit: "तालीसाद्यं चूर्णमेलादिकं वा हृद्यं प्राश्य प्राग्वयस्स्थापनं वा तत्प्रार्थिभ्यो भूमिभागे सुमृष्टे तोयोन्मिश्रं दापयित्वा ततश्च", text: "tālīsādyaṃ cūrṇamelādikaṃ vā hṛdyaṃ prāśya prāgvayassthāpanaṃ vā tatprārthibhyo bhūmibhāge sumṛṣṭe toyonmiśraṃ dāpayitvā tataśca" },
      { type: "verse", number: "98", sanskrit: "धृतिमान् स्मृतिमान् नित्यमनूनाधिकमाचरन् उचितेनोपचारेण सर्वमेवोपलालयन्", text: "dhṛtimān smṛtimān nityamanūnādhikamācaran ucitenopacāreṇa sarvamevopalālayan" },
      { type: "verse", number: "99", sanskrit: "जितविकसितासितसरोजनयनसङ्क्रान्तिवार्धितश्रीकम् कान्तामुखमिव सौरभहृतमधुपगणं पिबेन्मद्यम्", text: "jitavikasitāsitasarojanayanasaṅkrāntivārdhitaśrīkam kāntāmukhamiva saurabhahṛtamadhupagaṇaṃ pibenmadyam" },
      { type: "verse", number: "100", sanskrit: "पीत्वैवं चषकत्रयं परिजनं सम्मान्य सर्वं ततो गत्वाहारभुवं पुरः सुभिषजो भुञ्जीत भूयो ऽत्र च मांसापूपघृतार्द्रकादिहरितैर्युक्तं ससौवर्चलैर्द्विस्त्रिर्वा चाल्पमेव वनितासंवल्गनार्थं पिबेत्", text: "pītvaivaṃ caṣakatrayaṃ parijanaṃ sammānya sarvaṃ tato gatvāhārabhuvaṃ puraḥ subhiṣajo bhuñjīta bhūyo 'tra ca māṃsāpūpaghṛtārdrakādiharitairyuktaṃ sasauvarcalairdvistrirvā cālpameva vanitāsaṃvalganārthaṃ pibet" },
      { type: "verse", number: "101", sanskrit: "रहसि दयितामङ्के कृत्वा भुजान्तरपीडनात् पुलकिततनुं जातस्वेदां सकम्पपयोधराम् यदि सरभसं सीधोर्वारं न पाययते कृती किमनुभवति क्लेशप्रायं तदा गृहतन्त्रताम्", text: "rahasi dayitāmaṅke kṛtvā bhujāntarapīḍanāt pulakitatanuṃ jātasvedāṃ sakampapayodharām yadi sarabhasaṃ sīdhorvāraṃ na pāyayate kṛtī kimanubhavati kleśaprāyaṃ tadā gṛhatantratām" },
      { type: "verse", number: "102", sanskrit: "वरतनुवक्त्रसङ्गतिसुगन्धितरं सरकं द्रुतमिव पद्मरागमणिमासवरूपधरम् भवति रतिश्रमेण च मदः पिबतो ऽल्पमपि क्षयमत ओजसः परिहरन् स शयीत परम्", text: "varatanuvaktrasaṅgatisugandhitaraṃ sarakaṃ drutamiva padmarāgamaṇimāsavarūpadharam bhavati ratiśrameṇa ca madaḥ pibato 'lpamapi kṣayamata ojasaḥ pariharan sa śayīta param" },
      { type: "verse", number: "103", sanskrit: "इत्थं युक्त्या पिबन्मद्यं न त्रिवर्गाद्विहीयते असारसंसारसुखं परमं चाधिगच्छति", text: "itthaṃ yuktyā pibanmadyaṃ na trivargādvihīyate asārasaṃsārasukhaṃ paramaṃ cādhigacchati" },
      { type: "verse", number: "104", sanskrit: "ऐश्वर्यस्योपभोगो ऽयं स्पृहणीयः सुरैरपि अन्यथा हि विपत्सु स्यात् पश्चात्तापेन्धनं धनम्", text: "aiśvaryasyopabhogo 'yaṃ spṛhaṇīyaḥ surairapi anyathā hi vipatsu syāt paścāttāpendhanaṃ dhanam" },
      { type: "verse", number: "105", sanskrit: "उपभोगेन रहितो भोगवानिति निन्द्यते निर्मितो ऽतिकदर्यो ऽयं विधिना निधिपालकः", text: "upabhogena rahito bhogavāniti nindyate nirmito 'tikadaryo 'yaṃ vidhinā nidhipālakaḥ" },
      { type: "verse", number: "106", sanskrit: "तस्माद्व्यवस्थया पानं पानस्य सततं हितम् जित्वाविषयलुब्धानामिन्द्रियाणां स्वतन्त्रताम्", text: "tasmādvyavasthayā pānaṃ pānasya satataṃ hitam jitvāviṣayalubdhānāmindriyāṇāṃ svatantratām" },
      { type: "verse", number: "107", sanskrit: "विधिर्वसुमतामेष भविष्यद्वसवस्तु ये यथोपपत्ति तैर्मद्यं पातव्यं मात्रया हितम्", text: "vidhirvasumatāmeṣa bhaviṣyadvasavastu ye yathopapatti tairmadyaṃ pātavyaṃ mātrayā hitam" },
      { type: "verse", number: "108", sanskrit: "यावद्दृष्टेर्न सम्भ्रान्तिर्यावन्न क्षोभ्यते मनः तावदेव विरन्तव्यं मद्यादात्मवता सदा", text: "yāvaddṛṣṭerna sambhrāntiryāvanna kṣobhyate manaḥ tāvadeva virantavyaṃ madyādātmavatā sadā" },
      { type: "verse", number: "109", sanskrit: "अभ्यङ्गोद्वर्तनस्नानवासधूपानुलेपनैः स्निग्धोष्णैर्भावितश्चान्नैः पानं वातोत्तरः पिबेत्", text: "abhyaṅgodvartanasnānavāsadhūpānulepanaiḥ snigdhoṣṇairbhāvitaścānnaiḥ pānaṃ vātottaraḥ pibet" },
      { type: "verse", number: "110", sanskrit: "शीतोपचारैर्विविधैर्माधुरस्निग्धशीतलैः पैत्तिको भावितश्चान्नैः पिबन्मद्य न सीदति", text: "śītopacārairvividhairmādhurasnigdhaśītalaiḥ paittiko bhāvitaścānnaiḥ pibanmadya na sīdati" },
      { type: "verse", number: "111", sanskrit: "उपचारैरशिशिरैर्यवगोधूमभुक् पिबेत् श्लैष्मिको धन्वजैर्मांसैर्मद्यं मारिचिकैः सह", text: "upacārairaśiśirairyavagodhūmabhuk pibet ślaiṣmiko dhanvajairmāṃsairmadyaṃ māricikaiḥ saha" },
      { type: "verse", number: "112", sanskrit: "तत्र वाते हितं मद्यं प्रायः पैष्टिकगौडिम पित्ते साम्भो मधु कफे मार्द्वीकारिष्टमाधवम्", text: "tatra vāte hitaṃ madyaṃ prāyaḥ paiṣṭikagauḍima pitte sāmbho madhu kaphe mārdvīkāriṣṭamādhavam" },
      { type: "verse", number: "113", sanskrit: "प्राक् पिबेछ्लैष्मिको मद्यं भुक्तस्योपरि पैत्तिकः वातिकस्तु पिबेन्मध्ये समदोषो यथेच्छति", text: "prāk pibechlaiṣmiko madyaṃ bhuktasyopari paittikaḥ vātikastu pibenmadhye samadoṣo yathecchati" },
      { type: "verse", number: "114", sanskrit: "मदेषु वातपित्तघ्नं प्रायो मूर्छासु चेष्यते सर्वत्रापि विशेषेण पित्तमेवोपलक्षयेत्", text: "madeṣu vātapittaghnaṃ prāyo mūrchāsu ceṣyate sarvatrāpi viśeṣeṇa pittamevopalakṣayet" },
      { type: "verse", number: "115", sanskrit: "शीताः प्रदेहा मणयः सेका व्यजनमारुताः सिताद्राक्षेक्षुखर्जूरकाश्मर्यस्वरसाः पयः", text: "śītāḥ pradehā maṇayaḥ sekā vyajanamārutāḥ sitādrākṣekṣukharjūrakāśmaryasvarasāḥ payaḥ" },
      { type: "verse", number: "116", sanskrit: "सिद्धा मधुरवर्गेण रसा यूषाः सदाडिमाः षष्टिकाः शालयो मुद्गा यवाः सर्पिश्च जीवनम्", text: "siddhā madhuravargeṇa rasā yūṣāḥ sadāḍimāḥ ṣaṣṭikāḥ śālayo mudgā yavāḥ sarpiśca jīvanam" },
      { type: "verse", number: "117", sanskrit: "कल्याणकं पञ्चगव्यं षट्पलं पयसाग्निकम् पिप्पल्यो वा शिलाह्वं वा रसायनविधानतः त्रिफला वा प्रयोक्तव्या सघृतक्षौद्रशर्करा", text: "kalyāṇakaṃ pañcagavyaṃ ṣaṭpalaṃ payasāgnikam pippalyo vā śilāhvaṃ vā rasāyanavidhānataḥ triphalā vā prayoktavyā saghṛtakṣaudraśarkarā" },
      { type: "verse", number: "118", sanskrit: "प्रसक्तवेगेषु हितं मुखनासावरोधनम् पिबेद्वा मानुषीक्षीरं तेन दद्याच्च नावनम्", text: "prasaktavegeṣu hitaṃ mukhanāsāvarodhanam pibedvā mānuṣīkṣīraṃ tena dadyācca nāvanam" },
      { type: "verse", number: "119", sanskrit: "मृणालबिसकृष्णा वा लिह्यात् क्षौद्रेण साभयाः दुरालभां वा मुस्तां वा शीतेन सलिलेन वा", text: "mṛṇālabisakṛṣṇā vā lihyāt kṣaudreṇa sābhayāḥ durālabhāṃ vā mustāṃ vā śītena salilena vā" },
      { type: "verse", number: "120", sanskrit: "पिबेन्मरिचकोलस्थिमज्जोशीराहिकेसरम् धात्रीफलरसे सिद्धं पथ्याक्वाथेन वा घृतम्", text: "pibenmaricakolasthimajjośīrāhikesaram dhātrīphalarase siddhaṃ pathyākvāthena vā ghṛtam" },
      { type: "verse", number: "121", sanskrit: "कुर्यात् क्रियां ज्वरोक्तां च यथादोषबलोदयम् पञ्च कर्माणि शस्तानि तथा रक्तावसेचनम्", text: "kuryāt kriyāṃ jvaroktāṃ ca yathādoṣabalodayam pañca karmāṇi śastāni tathā raktāvasecanam" },
      { type: "verse", number: "122", sanskrit: "सत्वस्यालम्बनं ज्ञानमगृद्धिर्विषयेषु च", text: "satvasyālambanaṃ jñānamagṛddhirviṣayeṣu ca" },
      { type: "verse", number: "123", sanskrit: "मदेष्वतिप्रवृद्धेषु मूर्छायेषु च योजयेत् तीक्ष्णं संन्यासविहितं विषघ्नं विषजेषु च", text: "madeṣvatipravṛddheṣu mūrchāyeṣu ca yojayet tīkṣṇaṃ saṃnyāsavihitaṃ viṣaghnaṃ viṣajeṣu ca" },
      { type: "verse", number: "124", sanskrit: "आशु प्रयोज्यं संन्यासे सुतीक्ष्णं नस्यमञ्जनम् धूमं प्रधमनं तोदः सूचीभिश्च नखान्तरे", text: "āśu prayojyaṃ saṃnyāse sutīkṣṇaṃ nasyamañjanam dhūmaṃ pradhamanaṃ todaḥ sūcībhiśca nakhāntare" },
      { type: "verse", number: "125", sanskrit: "केशानां लुञ्चनं दाहो दशनवृश्चिकैः कट्वम्लगालनं वक्त्रे कपिकच्छ्वावघर्षणम्", text: "keśānāṃ luñcanaṃ dāho daśanavṛścikaiḥ kaṭvamlagālanaṃ vaktre kapikacchvāvagharṣaṇam" },
      { type: "verse", number: "126", sanskrit: "उत्थितो लब्धसंज्ञश्च लशुनस्वरसं पिबेत् खादेत्सव्योषलवणं बीजपूरककेसरम् लघ्वन्नं कटुतीक्ष्णमद्यात् स्रोतोविशुद्धये", text: "utthito labdhasaṃjñaśca laśunasvarasaṃ pibet khādetsavyoṣalavaṇaṃ bījapūrakakesaram laghvannaṃ kaṭutīkṣṇamadyāt srotoviśuddhaye" },
      { type: "verse", number: "127", sanskrit: "विस्मापनैः संस्मरणः प्रियश्रवणदर्शनैः पटुभिर्गीतवादित्रशब्दैर्व्यायामशीलनैः", text: "vismāpanaiḥ saṃsmaraṇaḥ priyaśravaṇadarśanaiḥ paṭubhirgītavāditraśabdairvyāyāmaśīlanaiḥ" },
      { type: "verse", number: "128", sanskrit: "स्रंसनोल्लेखनैर्धूमैः शोणितस्यावसेचनैः उपाचरेत्तं प्रततमनुबन्धभयात् पुनः तस्य संरक्षितव्यं च मनः प्रलयहेतुतः", text: "sraṃsanollekhanairdhūmaiḥ śoṇitasyāvasecanaiḥ upācarettaṃ pratatamanubandhabhayāt punaḥ tasya saṃrakṣitavyaṃ ca manaḥ pralayahetutaḥ" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 10,
    lang: "sa",
    content: [
      { type: "heading", heading: "Вата вьядхи чикитса — лечение болезней Ваты" },
      { type: "text", text: "Глава 10 Чикитса стханы — лечебный раздел о лечение болезней Ваты. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो ऽर्शस चिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto 'rśasa cikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अथ खलु बलवन्तमर्शोभिरुपद्रुतं यथार्हस्नेहोपस्निग्धस्विन्नमनिलवेदनावृद्धिशमनार्थं स्निग्धमुष्णमल्पमन्नं द्रवप्रायं भुक्तवन्तं शुचिं कृतस्वस्त्ययनं भुक्तविण्मूत्रमव्यथं समे शुचौ विविक्ते देशे साधारणे व्यभ्रे काले शय्यायां समे फलके वा प्रत्यादित्यगुदमन्यस्योत्सङ्गे निषण्णपूर्वकायं उत्तानमुन्नतकटीदेशं यन्त्रणशाटकेन परिक्षिप्तग्रीवासक्थिसन्धिमलज्जार्हैराप्तपरिचारकैः सुपरिगृहीतं कृत्वा ततो ऽस्म घृताभ्यक्तगुदाय घृताभ्यक्तं यन्त्रमृज्वनुसुखं शनैः पायौ प्रणिदध्यात् प्रवाहणप्रविष्टं चार्शो ऽभिवीक्ष्यपिचुप्लोतकयोरन्यतरेणावगुण्ठितया शलाकयोत्पीड्य यथोक्तविधिनाग्निक्षाराभ्यामुपाचरेत् सम्यङ्निर्वापयेच्च", text: "atha khalu balavantamarśobhirupadrutaṃ yathārhasnehopasnigdhasvinnamanilavedanāvṛddhiśamanārthaṃ snigdhamuṣṇamalpamannaṃ dravaprāyaṃ bhuktavantaṃ śuciṃ kṛtasvastyayanaṃ bhuktaviṇmūtramavyathaṃ same śucau vivikte deśe sādhāraṇe vyabhre kāle śayyāyāṃ same phalake vā pratyādityagudamanyasyotsaṅge niṣaṇṇapūrvakāyaṃ uttānamunnatakaṭīdeśaṃ yantraṇaśāṭakena parikṣiptagrīvāsakthisandhimalajjārhairāptaparicārakaiḥ suparigṛhītaṃ kṛtvā tato 'sma ghṛtābhyaktagudāya ghṛtābhyaktaṃ yantramṛjvanusukhaṃ śanaiḥ pāyau praṇidadhyāt pravāhaṇapraviṣṭaṃ cārśo 'bhivīkṣyapicuplotakayoranyatareṇāvaguṇṭhitayā śalākayotpīḍya yathoktavidhināgnikṣārābhyāmupācaret samyaṅnirvāpayecca" },
      { type: "verse", number: "3", sanskrit: "महान्ति प्राणवतश्छित्वा दहेत् छत्राकाराण्यूर्ध्वविसृतानि क्षारसूत्रेण बध्वा", text: "mahānti prāṇavataśchitvā dahet chatrākārāṇyūrdhvavisṛtāni kṣārasūtreṇa badhvā" },
      { type: "verse", number: "4", sanskrit: "ततो यन्त्रमपनीयोत्थाप्यातुरं स्वभ्यक्तगुदजघनवङ्क्षणं यथाकालमुष्णोदककोष्ठे ऽवगाहयेत् ततो निवातमगारं प्रवेश्याचारिकमुपदिशेत्", text: "tato yantramapanīyotthāpyāturaṃ svabhyaktagudajaghanavaṅkṣaṇaṃ yathākālamuṣṇodakakoṣṭhe 'vagāhayet tato nivātamagāraṃ praveśyācārikamupadiśet" },
      { type: "verse", number: "5", sanskrit: "सावशेषं पुनर्दाहयेत् एवं सप्तरात्रात्सप्तरात्रादेकैकमुपक्रमेत् बहुषु तु प्राग्दक्षिणं ततो वामं वामात् पृष्ठाग्रजम् एकाहात्तु सर्वाणि दहतो ऽतियोगोक्तो देषः तत्र शुष्काण्यग्निना क्षारेण वा साधयेत् क्षारेणैव मृदुनार्द्राणि एष सर्वप्रदेशेष्वर्शसां दहनविकल्पः तृतीये तु गुदवलौ प्रत्याख्यायोपचरेन्न वेत्येके", text: "sāvaśeṣaṃ punardāhayet evaṃ saptarātrātsaptarātrādekaikamupakramet bahuṣu tu prāgdakṣiṇaṃ tato vāmaṃ vāmāt pṛṣṭhāgrajam ekāhāttu sarvāṇi dahato 'tiyogokto deṣaḥ tatra śuṣkāṇyagninā kṣāreṇa vā sādhayet kṣāreṇaiva mṛdunārdrāṇi eṣa sarvapradeśeṣvarśasāṃ dahanavikalpaḥ tṛtīye tu gudavalau pratyākhyāyopacarenna vetyeke" },
      { type: "verse", number: "6", sanskrit: "अथ सम्यग्दग्धे वातानुलोम्यमन्नाभिरुचिरग्नेर्दीप्तिर्लाघवमिन्द्रियप्रसादो यथोक्तोपद्रवनिवृत्तिर्बलवर्णोपपत्तिश्च असम्यग्दाहे तु क्षाराग्निकर्मणोर्विधिमीक्षेत्", text: "atha samyagdagdhe vātānulomyamannābhiruciragnerdīptirlāghavamindriyaprasādo yathoktopadravanivṛttirbalavarṇopapattiśca asamyagdāhe tu kṣārāgnikarmaṇorvidhimīkṣet" },
      { type: "verse", number: "7", sanskrit: "बस्तिवेदनायां कुष्ठशतपुष्पादेवदारुसुरभिपुनर्नवागरुकल्केन नाभेरधः सर्वमालिम्पेत् मूत्रपुरीषप्रतीघाते वरणालम्बुसैरण्डपुनर्नवाश्वदंष्ट्रासुरभीसुषवीकषायं सुखोष्णं स्वभ्यक्तपृष्ठकटीवङ्क्षणगुदस्य परिषेके ऽवाअहे वा योजयेत् क्षीरं सस्नेहं तैलमेव वा दग्धेषु चार्शःसु शकृच्छैथिल्यार्थं त्रिवृद्वास्तुकोपोदकाचुञ्ज्चुपर्णीशाकयुक्तमन्नमश्नीयात्", text: "bastivedanāyāṃ kuṣṭhaśatapuṣpādevadārusurabhipunarnavāgarukalkena nābheradhaḥ sarvamālimpet mūtrapurīṣapratīghāte varaṇālambusairaṇḍapunarnavāśvadaṃṣṭrāsurabhīsuṣavīkaṣāyaṃ sukhoṣṇaṃ svabhyaktapṛṣṭhakaṭīvaṅkṣaṇagudasya pariṣeke 'vāahe vā yojayet kṣīraṃ sasnehaṃ tailameva vā dagdheṣu cārśaḥsu śakṛcchaithilyārthaṃ trivṛdvāstukopodakācuñjcuparṇīśākayuktamannamaśnīyāt" },
      { type: "verse", number: "8", sanskrit: "अनिलानलरक्षणोत्तेजनार्थं देहपुष्टये च स्नेहादीन् सम्यगासेवेत् संशोधनाः प्रलेपाद्याः कषायास्तैलयुक्तयः व्रणाधिकारमालोच्य योक्तव्या हत्नामसु", text: "anilānalarakṣaṇottejanārthaṃ dehapuṣṭaye ca snehādīn samyagāsevet saṃśodhanāḥ pralepādyāḥ kaṣāyāstailayuktayaḥ vraṇādhikāramālocya yoktavyā hatnāmasu" },
      { type: "verse", number: "9", sanskrit: "अथानवचारणीयशस्त्रक्षाराग्नेर्वातकफोल्बणानि दोषसम्पूर्णत्वान्निर्गतानि सस्तम्भकण्डूशोफशूलानि क्षारचित्रककुष्ठबिल्वमूलकसिद्धेन तैलेन वा कृष्णाहिबिडालौष्ट्रजलौकःसूकरवसाभिर्वाभ्यज्य पिण्डेन स्वेदयेद्द्रवस्वेदेन वा धूपयेच्च सघृतशमीपत्रार्कमूलमानुषकेशाहिनिर्मोकबिडालचर्मभिः कुञ्जरवराहवृषशकृत्सक्तुसर्जरसैर्वा सुरसाबृहतीपिप्पल्यश्वगन्धाभिर्वा सघृताभिः अरिष्टशिग्रुपत्रकुलत्थवचाभिर्वा प्रदिह्याच्च स्नुहीक्षीरयुक्तेन हरिद्राचूर्णेन गोमूत्रपिष्टैर्वा कुक्कुटशकृन्निशापिप्पलीगुञ्जामूलैः गोपित्तपिष्टाभिर्वा दन्तीचित्रकसुवर्चिकाभिः सुधाक्षीरपिष्टैर्वा गुडकृष्णासैन्धवकुष्ठशिरीषबीजैः तद्वच्च गजास्थितुत्थभल्लातकलाङ्गलीकुलीरशृङ्गीवचाभयाहिंगुकुष्ठबिल्वशिग्रुमूलकबीजनिम्बाश्वमारपत्रपीलुमूलैः बस्तमूत्रपिष्टैर्वा सुधाकाण्डार्कक्षीरतुम्बप्रसवकरञ्जैः पिप्पल्यादिभिर्वानुवासनद्रव्यैः एभिर्हि प्रदिग्धान्य शार्ंसि दुष्टमसृक्सञ्चितं पिच्छां च विमुच्य प्रशाम्यन्ति एभिश्च तैलान्यभ्यङ्गार्थमुपकल्पयेत्", text: "athānavacāraṇīyaśastrakṣārāgnervātakapholbaṇāni doṣasampūrṇatvānnirgatāni sastambhakaṇḍūśophaśūlāni kṣāracitrakakuṣṭhabilvamūlakasiddhena tailena vā kṛṣṇāhibiḍālauṣṭrajalaukaḥsūkaravasābhirvābhyajya piṇḍena svedayeddravasvedena vā dhūpayecca saghṛtaśamīpatrārkamūlamānuṣakeśāhinirmokabiḍālacarmabhiḥ kuñjaravarāhavṛṣaśakṛtsaktusarjarasairvā surasābṛhatīpippalyaśvagandhābhirvā saghṛtābhiḥ ariṣṭaśigrupatrakulatthavacābhirvā pradihyācca snuhīkṣīrayuktena haridrācūrṇena gomūtrapiṣṭairvā kukkuṭaśakṛnniśāpippalīguñjāmūlaiḥ gopittapiṣṭābhirvā dantīcitrakasuvarcikābhiḥ sudhākṣīrapiṣṭairvā guḍakṛṣṇāsaindhavakuṣṭhaśirīṣabījaiḥ tadvacca gajāsthitutthabhallātakalāṅgalīkulīraśṛṅgīvacābhayāhiṃgukuṣṭhabilvaśigrumūlakabījanimbāśvamārapatrapīlumūlaiḥ bastamūtrapiṣṭairvā sudhākāṇḍārkakṣīratumbaprasavakarañjaiḥ pippalyādibhirvānuvāsanadravyaiḥ ebhirhi pradigdhānya śārṃsi duṣṭamasṛksañcitaṃ picchāṃ ca vimucya praśāmyanti ebhiśca tailānyabhyaṅgārthamupakalpayet" },
      { type: "verse", number: "10", sanskrit: "तथा कासीससैन्धवालपिप्पलीकुष्ठशुण्ठीविडङ्गविदारीलाङ्गलीकरवीरार्द्रकस्वर्णक्षीरीदन्तीचित्रकालर्कसूधापयोभिस्तैलं चतुर्गुणमूत्रविपक्वमप्रदूषयत् गुदमभ्यङ्गात् क्षारवदर्शांसि शातयति तैलाभ्यक्तं वा पायुप्रदेशं पक्वेष्टकाशकलैस्तीक्ष्णकोटिभिरग्निवर्णैर्महिषीमूत्रनिर्वापितैर्निष्पीडयन् द्विकालं सप्तदिनानि स्वेदयेत् अनन्तां च यथोक्तेनावगाहरेन ततो गते सप्तरात्रे पूतीकरञ्जपल्लवकल्केन ससैन्धवेन स्नुही पयसा वर्तिं कृत्वा नातिशुष्कां गुदे विदध्यात् कृतविण्मूत्रं चावगाहे स्थापयेत् प्रातः सायं चैष विधिः प्रत्यहमेकान्तरं वा यावत्त्रिरात्रम् ततो देवदालीक्षारहरीतकीः शीलयेत् एवमर्शांसि शीर्यन्ते", text: "tathā kāsīsasaindhavālapippalīkuṣṭhaśuṇṭhīviḍaṅgavidārīlāṅgalīkaravīrārdrakasvarṇakṣīrīdantīcitrakālarkasūdhāpayobhistailaṃ caturguṇamūtravipakvamapradūṣayat gudamabhyaṅgāt kṣāravadarśāṃsi śātayati tailābhyaktaṃ vā pāyupradeśaṃ pakveṣṭakāśakalaistīkṣṇakoṭibhiragnivarṇairmahiṣīmūtranirvāpitairniṣpīḍayan dvikālaṃ saptadināni svedayet anantāṃ ca yathoktenāvagāharena tato gate saptarātre pūtīkarañjapallavakalkena sasaindhavena snuhī payasā vartiṃ kṛtvā nātiśuṣkāṃ gude vidadhyāt kṛtaviṇmūtraṃ cāvagāhe sthāpayet prātaḥ sāyaṃ caiṣa vidhiḥ pratyahamekāntaraṃ vā yāvattrirātram tato devadālīkṣāraharītakīḥ śīlayet evamarśāṃsi śīryante" },
      { type: "verse", number: "11", sanskrit: "अथ हरीतकीपाकविधिः सजालमूलं जीमूतकमन्तर्धूमं दहेत् तस्यभस्मनोर्द्धाढकं गोमूत्रपात्रद्वयेनैकविंशतिकृत्वो गालयेत् ततस्तेन क्षारमूत्रेण कुटजचित्रकव्याधिघातचूर्णप्रसृतत्रयान्वितेन पथ्याशतद्वयमाघनीभावात् पचेत् अवतीर्णं च तमवलेहं व्योषरजःप्रसृतयुक्तं घृतभाविते भाजने निदध्यात् स लेहः सावलेहविजयाद्वयोपयोगमभ्यस्यमानो गुदजजठरजघनवङ्क्षणशूलगरानाहगुल्मपाण्डुरोगाश्मरीशर्कराश्वासकासान् नियच्छति सदा च पत्रभङ्गोदकेन कोष्णेनाम्बुना वा शौचमाचरेत् अप्रवर्तमानं च रुधिरमुच्छूनकठिनेष्वर्शःसु जलौकाभिः सूचीकूर्चेन वा प्रवर्तयेत्", text: "atha harītakīpākavidhiḥ sajālamūlaṃ jīmūtakamantardhūmaṃ dahet tasyabhasmanorddhāḍhakaṃ gomūtrapātradvayenaikaviṃśatikṛtvo gālayet tatastena kṣāramūtreṇa kuṭajacitrakavyādhighātacūrṇaprasṛtatrayānvitena pathyāśatadvayamāghanībhāvāt pacet avatīrṇaṃ ca tamavalehaṃ vyoṣarajaḥprasṛtayuktaṃ ghṛtabhāvite bhājane nidadhyāt sa lehaḥ sāvalehavijayādvayopayogamabhyasyamāno gudajajaṭharajaghanavaṅkṣaṇaśūlagarānāhagulmapāṇḍurogāśmarīśarkarāśvāsakāsān niyacchati sadā ca patrabhaṅgodakena koṣṇenāmbunā vā śaucamācaret apravartamānaṃ ca rudhiramucchūnakaṭhineṣvarśaḥsu jalaukābhiḥ sūcīkūrcena vā pravartayet" },
      { type: "verse", number: "12", sanskrit: "अग्निसादे गुदशोफशूलार्तौ च हिङ्ग्वर्धकर्षं सौवर्चलयवक्षारेन्द्रयवपिप्पलीनां पृथक् कर्षं मूर्वार्धपलं पाठापलं शुण्ठीद्विपलं चैकत्र चूर्णितमुष्णाम्बुसर्पिर्मद्याद्यैरुपयोज्यम् त्रिलवणादिचूर्णं वा हिङ्ग्वतिविषाकुष्ठस्वर्जिकाक्षारबिडलवणानि वा द्विगुणोत्तराणि प्रथोजयेत् प्राणदां वा तक्रानुपानं सगुडाम् प्रातः प्राग्भक्तं वा निरन्नो वा तक्रमहरहस्तस्मिन् जीर्णे तक्रे सायं तक्रपेयां ससैन्धवां पिबेत् तक्रेणैव वा लाजसक्तूनवलिह्यात् पीलूनि वा तक्रानुपानानि प्रातः पक्षं पक्षार्धं वा प्रयोजयेत् कटुकिकामूलकल्कं वा प्रातस्तक्रेण", text: "agnisāde gudaśophaśūlārtau ca hiṅgvardhakarṣaṃ sauvarcalayavakṣārendrayavapippalīnāṃ pṛthak karṣaṃ mūrvārdhapalaṃ pāṭhāpalaṃ śuṇṭhīdvipalaṃ caikatra cūrṇitamuṣṇāmbusarpirmadyādyairupayojyam trilavaṇādicūrṇaṃ vā hiṅgvativiṣākuṣṭhasvarjikākṣārabiḍalavaṇāni vā dviguṇottarāṇi prathojayet prāṇadāṃ vā takrānupānaṃ saguḍām prātaḥ prāgbhaktaṃ vā niranno vā takramaharahastasmin jīrṇe takre sāyaṃ takrapeyāṃ sasaindhavāṃ pibet takreṇaiva vā lājasaktūnavalihyāt pīlūni vā takrānupānāni prātaḥ pakṣaṃ pakṣārdhaṃ vā prayojayet kaṭukikāmūlakalkaṃ vā prātastakreṇa" },
      { type: "verse", number: "13", sanskrit: "शुण्ठीचित्रकपुनर्नवाक्वाथसिद्धं वा क्षीरम् गोमूत्रपरिस्रुते वा बहुकृत्वो जीमूतकक्षार उषिता हरीतकीः गोमूत्रार्धद्रोणसिद्धं वा क्षौद्रवदभयाशतम् वासिष्ठहरीतजीर्वा भल्लातकानि वा रसायनोपदेशेन पुनर्नवामलंबुसां वा शोफोक्तविधिना गुडार्द्रकं वा", text: "śuṇṭhīcitrakapunarnavākvāthasiddhaṃ vā kṣīram gomūtraparisrute vā bahukṛtvo jīmūtakakṣāra uṣitā harītakīḥ gomūtrārdhadroṇasiddhaṃ vā kṣaudravadabhayāśatam vāsiṣṭhaharītajīrvā bhallātakāni vā rasāyanopadeśena punarnavāmalaṃbusāṃ vā śophoktavidhinā guḍārdrakaṃ vā" },
      { type: "verse", number: "14", sanskrit: "सकुतुमन्थं वा भल्लातकचूर्णयुक्तं नातिलवणं तक्रेण तक्रेण वाषाढकार्तिकमार्गशीर्षाणां मासानामन्यतमस्मिन् पुष्ययोगे समुद्धृतं चित्रकमथवा मस्तुयूषक्षीरघृततैलाद्यन्यतमेन", text: "sakutumanthaṃ vā bhallātakacūrṇayuktaṃ nātilavaṇaṃ takreṇa takreṇa vāṣāḍhakārtikamārgaśīrṣāṇāṃ māsānāmanyatamasmin puṣyayoge samuddhṛtaṃ citrakamathavā mastuyūṣakṣīraghṛtatailādyanyatamena" },
      { type: "verse", number: "15", sanskrit: "चित्रकमूलक्वाथं वा लेहतां गतं समधुगुडं तक्राशी शीलयेत् कलशे वान्तश्चित्रकमूलत्वक्कल्कलिप्तशुष्के जातं दधि कालशेयं वा पानभोजनेषु एवं भार्ङ्ग्यास्फोतगुडूचीपञ्चकोलेषु तक्रकल्पः", text: "citrakamūlakvāthaṃ vā lehatāṃ gataṃ samadhuguḍaṃ takrāśī śīlayet kalaśe vāntaścitrakamūlatvakkalkaliptaśuṣke jātaṃ dadhi kālaśeyaṃ vā pānabhojaneṣu evaṃ bhārṅgyāsphotaguḍūcīpañcakoleṣu takrakalpaḥ" },
      { type: "verse", number: "16", sanskrit: "घृतघटे वा हपुषोपकुञ्चिकाधानकाजमोदाजाजीशठीकारवीयवानीचित्रकपिप्पलीद्वयपिप्पलीमूलचूर्णासुतं जातं तक्रम् तक्रमेव वातिमन्दवह्निः सप्ताहसस्नेहमम्लमनम्लं वा सान्नमनन्नं वा शीलयेत्", text: "ghṛtaghaṭe vā hapuṣopakuñcikādhānakājamodājājīśaṭhīkāravīyavānīcitrakapippalīdvayapippalīmūlacūrṇāsutaṃ jātaṃ takram takrameva vātimandavahniḥ saptāhasasnehamamlamanamlaṃ vā sānnamanannaṃ vā śīlayet" },
      { type: "verse", number: "17", sanskrit: "ततस्तक्रसिद्धानि क्रमशो ऽर्शोघ्नलघुदीपनीयद्रव्यधान्यपिशितशाकोपकल्पितानि पेयाअयूषरसव्यञ्जनानि तक्रं हि परमौषधमनिलकफार्तीनां विशेषाज्जठराश्रितानाम् तत्रापि विशेषेण दुर्नाम्राम् न हि तद्विहतान्यर्शांसि पुनः प्ररोहन्ति भूमावपि तन्निषिच्यमानमहरहः समूलमुच्छिनत्ति तृणजालमप्स्वपि च शैवालम् तद्विशोधितेषु पुनर्देहस्रोतःसूपचीयमानो ऽन्नरसः पुष्टिबलवर्णौजसामाशु वृद्धये सम्पद्यते", text: "tatastakrasiddhāni kramaśo 'rśoghnalaghudīpanīyadravyadhānyapiśitaśākopakalpitāni peyāayūṣarasavyañjanāni takraṃ hi paramauṣadhamanilakaphārtīnāṃ viśeṣājjaṭharāśritānām tatrāpi viśeṣeṇa durnāmrām na hi tadvihatānyarśāṃsi punaḥ prarohanti bhūmāvapi tanniṣicyamānamaharahaḥ samūlamucchinatti tṛṇajālamapsvapi ca śaivālam tadviśodhiteṣu punardehasrotaḥsūpacīyamāno 'nnarasaḥ puṣṭibalavarṇaujasāmāśu vṛddhaye sampadyate" },
      { type: "verse", number: "18", sanskrit: "मद्यपश्च सेवेत चव्यचित्रकाजाजीचूर्णानुविद्धं शीधुं गौडं वा सौवर्चलहपुषान्वितां वा सुराम्", text: "madyapaśca seveta cavyacitrakājājīcūrṇānuviddhaṃ śīdhuṃ gauḍaṃ vā sauvarcalahapuṣānvitāṃ vā surām" },
      { type: "verse", number: "19", sanskrit: "अभयापलाष्टकं द्विगुणामलकमिन्द्रवारुणीपलपञ्चकं च द्विगुणकपित्थमध्यं लोद्ध्रविडङ्गैलवालुकपिप्पलीमरिचानि द्विपलांशानि जर्जरितान्युदकभारे विपाच्य पादशेषं रसं पूतशीतं गुडतुलाद्वयेन धातकीपलाष्टकेन संयोज्य घृतभाजने ऽर्धमासस्थं प्रातरन्नकाले वोपयुञ्जीत अयमभयारिष्टो ऽर्शोग्रहणीपाण्डुहृद्रोगकामलायक्ष्मविषमज्वरप्लीहगुल्मोदरश्वयथुकुष्ठकृमिग्रन्थ्यर्बुदघ्नो ऽग्निरुचिवर्णकरश्च", text: "abhayāpalāṣṭakaṃ dviguṇāmalakamindravāruṇīpalapañcakaṃ ca dviguṇakapitthamadhyaṃ loddhraviḍaṅgailavālukapippalīmaricāni dvipalāṃśāni jarjaritānyudakabhāre vipācya pādaśeṣaṃ rasaṃ pūtaśītaṃ guḍatulādvayena dhātakīpalāṣṭakena saṃyojya ghṛtabhājane 'rdhamāsasthaṃ prātarannakāle vopayuñjīta ayamabhayāriṣṭo 'rśograhaṇīpāṇḍuhṛdrogakāmalāyakṣmaviṣamajvaraplīhagulmodaraśvayathukuṣṭhakṛmigranthyarbudaghno 'gnirucivarṇakaraśca" },
      { type: "verse", number: "20", sanskrit: "दन्तीचित्रकत्रिफलादशमूलानि पालिकान्युदकद्रोणे साधयित्वा पादशेषे पूतशीते तस्मिन् गुडतुलार्धं धातकीकुडवं च प्रक्षिप्य घृतभाजने मासमुषितो दन्त्यरिष्टः समानः पूर्वेण दुरालभायाः प्रस्थमभयामलकवृषपाठाचित्रकदन्तीमहौषधीनां प्रत्येकं द्विपलमम्भसां द्रोणे पूर्ववत् सिद्धं पूतशीतं शर्करातुलयोन्मिश्रं मधुघृतप्रियङ्गुपिप्पलीचविकाकल्कलिप्तेघृतकुम्भे पक्षं निधापयेत् अयं दुरालभारिष्टः समानः पूर्वेण", text: "dantīcitrakatriphalādaśamūlāni pālikānyudakadroṇe sādhayitvā pādaśeṣe pūtaśīte tasmin guḍatulārdhaṃ dhātakīkuḍavaṃ ca prakṣipya ghṛtabhājane māsamuṣito dantyariṣṭaḥ samānaḥ pūrveṇa durālabhāyāḥ prasthamabhayāmalakavṛṣapāṭhācitrakadantīmahauṣadhīnāṃ pratyekaṃ dvipalamambhasāṃ droṇe pūrvavat siddhaṃ pūtaśītaṃ śarkarātulayonmiśraṃ madhughṛtapriyaṅgupippalīcavikākalkalipteghṛtakumbhe pakṣaṃ nidhāpayet ayaṃ durālabhāriṣṭaḥ samānaḥ pūrveṇa" },
      { type: "verse", number: "21", sanskrit: "नवामलकपलशतं पिप्पलीनागपुष्पकुडवद्वयं पालिकानि चव्यचित्रकक्रमुकलोध्रपाठामरिचविडङ्गमञ्जिष्ठैलवालुकपिप्पलीमूलान्यर्धपलांशिकानि दार्वीशताह्वेन्द्राह्वासारिवाद्वयमुस्तकुष्ठान्यैकध्यं च जलद्रोणद्वये ऽर्धावशेषं साधयेत् स रसः पूतशीतः समद्राक्षास्वरसः सितापलशतद्वयेन क्षौद्रार्धप्रस्थेन पृथक् कार्षिकेण च त्वगेलालोध्रकुटन्नटाम्बुसेव्यक्रमुककेसरचूर्णेन युक्तो गुडशर्कराधूपिते घृतभाण्डे प्रक्षिप्य पक्षमुपेक्षितो ऽयमामलकारिष्टः समानः पूर्वेण अकालवलीपलितखलतिशमनश्च", text: "navāmalakapalaśataṃ pippalīnāgapuṣpakuḍavadvayaṃ pālikāni cavyacitrakakramukalodhrapāṭhāmaricaviḍaṅgamañjiṣṭhailavālukapippalīmūlānyardhapalāṃśikāni dārvīśatāhvendrāhvāsārivādvayamustakuṣṭhānyaikadhyaṃ ca jaladroṇadvaye 'rdhāvaśeṣaṃ sādhayet sa rasaḥ pūtaśītaḥ samadrākṣāsvarasaḥ sitāpalaśatadvayena kṣaudrārdhaprasthena pṛthak kārṣikeṇa ca tvagelālodhrakuṭannaṭāmbusevyakramukakesaracūrṇena yukto guḍaśarkarādhūpite ghṛtabhāṇḍe prakṣipya pakṣamupekṣito 'yamāmalakāriṣṭaḥ samānaḥ pūrveṇa akālavalīpalitakhalatiśamanaśca" },
      { type: "verse", number: "22", sanskrit: "गुग्गुलुपलचतुष्टयमामलकप्रस्थं धातकीप्रस्थमभयाशतमक्षशतञ्च गुडपलशतद्वयं पालिकानि पञ्चकोलाजमोजचतुर्जातककट्फलमुस्तमरिचानि दशपलिकानि च खण्डद्राक्षादाडिमानि सर्वमैकध्यमम्भसाप्लाव्यालोड्य च पुराणे जतुसृते द्रोणक्षमे भाजने निक्षिप्य स्थापयेत् गन्धवर्णरसोपपन्नं चासवमभिसमीक्ष्य तं कुम्भमिक्षुरसस्य पूरयेत् एष षण्मासस्थितो गुग्गुल्वासवः समानः पूर्वेण", text: "guggulupalacatuṣṭayamāmalakaprasthaṃ dhātakīprasthamabhayāśatamakṣaśatañca guḍapalaśatadvayaṃ pālikāni pañcakolājamojacaturjātakakaṭphalamustamaricāni daśapalikāni ca khaṇḍadrākṣādāḍimāni sarvamaikadhyamambhasāplāvyāloḍya ca purāṇe jatusṛte droṇakṣame bhājane nikṣipya sthāpayet gandhavarṇarasopapannaṃ cāsavamabhisamīkṣya taṃ kumbhamikṣurasasya pūrayet eṣa ṣaṇmāsasthito guggulvāsavaḥ samānaḥ pūrveṇa" },
      { type: "verse", number: "23", sanskrit: "अमद्यपो वा पिबेच्च शृतशीतमल्पमुदकं शृतं धान्यनागराभ्याम् लघुना पञ्चमूलेन वा पञ्चकोलकाजाजीकारवीगजशौण्डीबिल्वशलाटुपाठातुम्बुरुधान्यकैर्वा", text: "amadyapo vā pibecca śṛtaśītamalpamudakaṃ śṛtaṃ dhānyanāgarābhyām laghunā pañcamūlena vā pañcakolakājājīkāravīgajaśauṇḍībilvaśalāṭupāṭhātumburudhānyakairvā" },
      { type: "verse", number: "24", sanskrit: "एभिश्च फलाम्लान् यमकस्निग्धान् पेयायूषरसादीन् कुर्यात् एभिरेव घृतं साधयेत् पिबेद्वा मस्तु धान्याम्लं मधुशुक्तोदकं वा", text: "ebhiśca phalāmlān yamakasnigdhān peyāyūṣarasādīn kuryāt ebhireva ghṛtaṃ sādhayet pibedvā mastu dhānyāmlaṃ madhuśuktodakaṃ vā" },
      { type: "verse", number: "25", sanskrit: "पूतीकरञ्जत्वक्पलशतद्वयं शुष्कमुदकद्रोणे क्वाथयेत् पादशेषे च तस्मिन् पूतशीते गुडपलान्यशीतिं व्योषार्धपस्थचूर्णं च दत्वा यवपल्ले घृतकुम्भस्थं मासं निधापयेत् एतत् करञ्जशुक्रमभ्यस्यमानमलमनलजननमर्शोगुल्मानाहप्लीहगरोदरघ्नं च पीलुतुलां तुल्यगुडां मस्तुनस्तक्रस्य वा द्रोणे ऽभिषुणुयात् तत्र पालिकानामभयातिविषापाठामुस्तकटुकादेवदारुहिंस्राजीरकारुष्करचव्याजमोदैलाचित्रकगजपिप्पलीव्योषविडङ्गशताह्वाहरेणुचिरबिल्वत्वक्कुष्ठकुटजबीजत्रिवृत्पिप्पलीमूलोपकुञ्चिकानां चूर्णं क्षिप्त्वा पूर्ववन्निधापयेत् तदधिकगुणं पूर्वस्मात्", text: "pūtīkarañjatvakpalaśatadvayaṃ śuṣkamudakadroṇe kvāthayet pādaśeṣe ca tasmin pūtaśīte guḍapalānyaśītiṃ vyoṣārdhapasthacūrṇaṃ ca datvā yavapalle ghṛtakumbhasthaṃ māsaṃ nidhāpayet etat karañjaśukramabhyasyamānamalamanalajananamarśogulmānāhaplīhagarodaraghnaṃ ca pīlutulāṃ tulyaguḍāṃ mastunastakrasya vā droṇe 'bhiṣuṇuyāt tatra pālikānāmabhayātiviṣāpāṭhāmustakaṭukādevadāruhiṃsrājīrakāruṣkaracavyājamodailācitrakagajapippalīvyoṣaviḍaṅgaśatāhvāhareṇucirabilvatvakkuṣṭhakuṭajabījatrivṛtpippalīmūlopakuñcikānāṃ cūrṇaṃ kṣiptvā pūrvavannidhāpayet tadadhikaguṇaṃ pūrvasmāt" },
      { type: "verse", number: "26", sanskrit: "सुतक्षितानामिक्षुगण्डिकानां द्रोणमुदकद्रोणेन घृतभाविते भाजने ऽभिषुणुयात् आवपेच्चात्र जर्जरीकृता यवानीयवानककुस्तुम्बरीपृथवीकाः पृथक् कुडवांशास्तथा द्विपलोन्मितास्तेजोवतीपञ्चकोलकाजाजीजीरकद्वयकारवीः क्षौद्रकुडवं च प्रक्षिप्य ततो दशरात्रेण सञ्जातात् तस्मान्मात्रां सौवर्चलार्द्रकभूस्तृणैः सुरभीकृतां भुञ्जानः पिबेत् पुनः पुनश्चात्र पानीयं प्रक्षिपेदिक्षुगण्डिकादिकञ्च सम्भारम् तत् गण्डीराख्यं काञ्जिकं परं रुचिकरमग्निदीपनमर्शोग्रहणीविकारोदरगरकृमिगुल्ममदात्ययपाण्डुरोगघ्नम्", text: "sutakṣitānāmikṣugaṇḍikānāṃ droṇamudakadroṇena ghṛtabhāvite bhājane 'bhiṣuṇuyāt āvapeccātra jarjarīkṛtā yavānīyavānakakustumbarīpṛthavīkāḥ pṛthak kuḍavāṃśāstathā dvipalonmitāstejovatīpañcakolakājājījīrakadvayakāravīḥ kṣaudrakuḍavaṃ ca prakṣipya tato daśarātreṇa sañjātāt tasmānmātrāṃ sauvarcalārdrakabhūstṛṇaiḥ surabhīkṛtāṃ bhuñjānaḥ pibet punaḥ punaścātra pānīyaṃ prakṣipedikṣugaṇḍikādikañca sambhāram tat gaṇḍīrākhyaṃ kāñjikaṃ paraṃ rucikaramagnidīpanamarśograhaṇīvikārodaragarakṛmigulmamadātyayapāṇḍurogaghnam" },
      { type: "verse", number: "27", sanskrit: "रूक्षकोष्ठश्चार्शसो नागरक्षारकृष्णाजाजीधान्यकारवीगर्भं फलाम्लं सफाणितं सर्पिः पिबेत् गुल्मोक्तानि वा घृतानि किंशुकक्षारोदकेन वा विपक्वं व्योषगर्भम् पाठामरिचपञ्चकोलकक्षारयवानीकुस्तुम्बरुहरीतकीबिल्वविडङ्गसैन्धवगर्भं चतुर्गुणेन दध्ना विपक्वं सर्पिः प्रवाहिकागुदभ्रंशपिच्छास्रावानाहगुल्मपायुपार्श्ववङ्क्षणवेदनाग्रहणीदोषहृद्रोगमूत्रकृच्छ्रघ्नम्", text: "rūkṣakoṣṭhaścārśaso nāgarakṣārakṛṣṇājājīdhānyakāravīgarbhaṃ phalāmlaṃ saphāṇitaṃ sarpiḥ pibet gulmoktāni vā ghṛtāni kiṃśukakṣārodakena vā vipakvaṃ vyoṣagarbham pāṭhāmaricapañcakolakakṣārayavānīkustumbaruharītakībilvaviḍaṅgasaindhavagarbhaṃ caturguṇena dadhnā vipakvaṃ sarpiḥ pravāhikāgudabhraṃśapicchāsrāvānāhagulmapāyupārśvavaṅkṣaṇavedanāgrahaṇīdoṣahṛdrogamūtrakṛcchraghnam" },
      { type: "verse", number: "28", sanskrit: "पिप्पलीपाठानागरगोक्षुरकाणां त्रिपलिकानां निर्यूहे गण्डीरमरिचपञ्चकोलकान्यर्धपलिकानि कल्कीकृत्य षड्गुणेन दध्ना चत्वारिंशत् घृतपलानि तुल्यचाङ्गेरीरसानि पाचयेत् तत् सर्पिः समानं पूर्वेण शोफोदरवासकासहिध्माघ्नं च", text: "pippalīpāṭhānāgaragokṣurakāṇāṃ tripalikānāṃ niryūhe gaṇḍīramaricapañcakolakānyardhapalikāni kalkīkṛtya ṣaḍguṇena dadhnā catvāriṃśat ghṛtapalāni tulyacāṅgerīrasāni pācayet tat sarpiḥ samānaṃ pūrveṇa śophodaravāsakāsahidhmāghnaṃ ca" },
      { type: "verse", number: "29", sanskrit: "बद्धवर्चांसि चार्शांस्युदावर्तवदुपाचरेत् भिन्नवर्चांसि चार्शांस्यतीसारवत् अतिप्रवृत्तरक्तानि रक्तपित्तातिसारवत्", text: "baddhavarcāṃsi cārśāṃsyudāvartavadupācaret bhinnavarcāṃsi cārśāṃsyatīsāravat atipravṛttaraktāni raktapittātisāravat" },
      { type: "verse", number: "30", sanskrit: "अशुद्धं च कालबलापेक्षी स्रवद्रुधिरमुपेक्षेत उभौ च तत्रानुबध्येते श्लेष्मानिलो वा तत्र पित्तश्लेष्मोल्बणं पाचनदीपनद्रव्यैरुपेक्षया च संशोध्य शमयेत् पित्तानिलोल्बणमन्तर्बहिरूर्ध्वमधश्च यथाग्निस्नेहैः केवलपित्तोल्बणमुष्णकाले विशेषतश्च दुर्बलस्य स्तम्भनैः", text: "aśuddhaṃ ca kālabalāpekṣī sravadrudhiramupekṣeta ubhau ca tatrānubadhyete śleṣmānilo vā tatra pittaśleṣmolbaṇaṃ pācanadīpanadravyairupekṣayā ca saṃśodhya śamayet pittānilolbaṇamantarbahirūrdhvamadhaśca yathāgnisnehaiḥ kevalapittolbaṇamuṣṇakāle viśeṣataśca durbalasya stambhanaiḥ" },
      { type: "verse", number: "31", sanskrit: "अथ श्लेष्मोल्बणे कुटजत्वग्विश्वभेषजक्वाथं पिबेत् तण्डुलोदकेन वा कुटजत्वक्फलातिविषारसाञ्जनानि सक्षौद्राणि कुटजत्वक्पलशतमार्द्रं दिव्याम्बुना क्वाथयेत् मुक्तरसे च पूते तस्मिन् पालिकान् सुश्लक्ष्णपिष्टान् प्रियङ्गुसमङ्गामोचरसान् कुटजबीजत्रिपलं च प्रक्षिप्य मृद्वग्निना पुनः साधयेदादर्वीलेपात् अयमवलेहश्छागलीक्षीरेण पेयामण्डेन वा सहाजक्षीरभुजः प्रयुक्तो रक्तजान्यर्शांस्यतीसारं कफपित्तञ्चोर्ध्वमधो वा प्रवृत्तमपहरति कुटजत्वक्पलशतमुदकद्रोणे ऽष्टभागशेषं साधयेत् परिस्राव्य तदुदकं कल्कीकृतैर्व्योषरसाञ्जनमोचरसमुस्ताधातकीफलबिल्वशलाटुदाडिमशलाटुत्वक्समङ्गालोध्रद्वयैः पलांशैः पलैश्च कुटजत्वचो दशभिस्तथा विंशत्या घृतस्य गुडस्य च त्रिंशता संसृष्टमधिश्रयेत् अथावलेहतां गतमवतारितं सप्ताहमर्धमासं मासं वा धान्यमध्ये सुगुप्तं निहितमुपयुक्तमाशु सर्वार्शोग्रहणीदोषश्वासकासानपोहति", text: "atha śleṣmolbaṇe kuṭajatvagviśvabheṣajakvāthaṃ pibet taṇḍulodakena vā kuṭajatvakphalātiviṣārasāñjanāni sakṣaudrāṇi kuṭajatvakpalaśatamārdraṃ divyāmbunā kvāthayet muktarase ca pūte tasmin pālikān suślakṣṇapiṣṭān priyaṅgusamaṅgāmocarasān kuṭajabījatripalaṃ ca prakṣipya mṛdvagninā punaḥ sādhayedādarvīlepāt ayamavalehaśchāgalīkṣīreṇa peyāmaṇḍena vā sahājakṣīrabhujaḥ prayukto raktajānyarśāṃsyatīsāraṃ kaphapittañcordhvamadho vā pravṛttamapaharati kuṭajatvakpalaśatamudakadroṇe 'ṣṭabhāgaśeṣaṃ sādhayet parisrāvya tadudakaṃ kalkīkṛtairvyoṣarasāñjanamocarasamustādhātakīphalabilvaśalāṭudāḍimaśalāṭutvaksamaṅgālodhradvayaiḥ palāṃśaiḥ palaiśca kuṭajatvaco daśabhistathā viṃśatyā ghṛtasya guḍasya ca triṃśatā saṃsṛṣṭamadhiśrayet athāvalehatāṃ gatamavatāritaṃ saptāhamardhamāsaṃ māsaṃ vā dhānyamadhye suguptaṃ nihitamupayuktamāśu sarvārśograhaṇīdoṣaśvāsakāsānapohati" },
      { type: "verse", number: "32", sanskrit: "मोचरससमङ्गातिललोध्रचन्दननीलोत्पलानि वा छागपयसा पिबेत् शूले तु बिल्वयवानीनागररसाञ्जनदुरालभावत्सकबीजानामन्यतमेनापि युक्तं पाठाचूर्णं शृतेन कोष्णेनांभसा तक्रेण वा शूले रक्तातिप्रवृत्तौ च लोध्रधातकीकुटजत्वगिन्द्रयव केसरनीलोत्पलकल्कसिद्धं सर्पिर्दुग्धिकानिदिग्धिकाकल्कसिद्धं वा", text: "mocarasasamaṅgātilalodhracandananīlotpalāni vā chāgapayasā pibet śūle tu bilvayavānīnāgararasāñjanadurālabhāvatsakabījānāmanyatamenāpi yuktaṃ pāṭhācūrṇaṃ śṛtena koṣṇenāṃbhasā takreṇa vā śūle raktātipravṛttau ca lodhradhātakīkuṭajatvagindrayava kesaranīlotpalakalkasiddhaṃ sarpirdugdhikānidigdhikākalkasiddhaṃ vā" },
      { type: "verse", number: "33", sanskrit: "वातोल्बणे तु रक्ते बलातिबलाबिल्वत्रिफलाहस्तिपिप्पलीन्यग्रोधकरञ्जपत्रमधुकतिन्दुकोत्पलैः कार्षिकैर्घृतप्रस्थमजाक्षीरे दशगुणे पचेत् तत् परं रक्तार्शोघ्नम् पाठालोध्रह्रीबेरोत्पलचव्यचन्दनसमङ्गातिविषाबिल्वधातकीमधुकदेवदारुदार्वीत्वङ्मुस्तामांसीनागरयवक्षारचित्रककल्केन चाङ्गेरीस्वरसेन च साधितं सर्पिर्द्रोषत्रयघ्नमर्शो ऽतिसारप्रवाहिकाबस्त्यानाहगुदभ्रंशपिच्छास्रुतिग्रहणीपाण्ड्वामयज्वरमूत्रकृच्छ्रारोचकदुर्नामशूलेषु योज्यम् बलादार्व्यवाक्पुष्पीगोक्षुरकपृश्निपर्शीनामश्वत्थोदुम्बरन्यग्रोधप्लक्षबदरीवेतसप्रवालानां च द्विपलोन्मितानां कषायेण जीवन्तीकटुकापञ्चकोलेन्द्रयवदेवदारुशाल्मलीपुष्पवीराचन्दनाञ्जनकट्फलमुस्तश्यामास्थिरातिविषासमङ्गाव्याघ्नीमोचरसबिल्वकमलोत्पलकिञ्जल्कानां चार्धकर्षोन्मितानां कल्केन चाङ्गेरीसुनिषण्णकस्वरसप्रस्थाभ्यां च घृतप्रस्थं पाचयेत् तत् समानं पूर्वेण", text: "vātolbaṇe tu rakte balātibalābilvatriphalāhastipippalīnyagrodhakarañjapatramadhukatindukotpalaiḥ kārṣikairghṛtaprasthamajākṣīre daśaguṇe pacet tat paraṃ raktārśoghnam pāṭhālodhrahrīberotpalacavyacandanasamaṅgātiviṣābilvadhātakīmadhukadevadārudārvītvaṅmustāmāṃsīnāgarayavakṣāracitrakakalkena cāṅgerīsvarasena ca sādhitaṃ sarpirdroṣatrayaghnamarśo 'tisārapravāhikābastyānāhagudabhraṃśapicchāsrutigrahaṇīpāṇḍvāmayajvaramūtrakṛcchrārocakadurnāmaśūleṣu yojyam balādārvyavākpuṣpīgokṣurakapṛśniparśīnāmaśvatthodumbaranyagrodhaplakṣabadarīvetasapravālānāṃ ca dvipalonmitānāṃ kaṣāyeṇa jīvantīkaṭukāpañcakolendrayavadevadāruśālmalīpuṣpavīrācandanāñjanakaṭphalamustaśyāmāsthirātiviṣāsamaṅgāvyāghnīmocarasabilvakamalotpalakiñjalkānāṃ cārdhakarṣonmitānāṃ kalkena cāṅgerīsuniṣaṇṇakasvarasaprasthābhyāṃ ca ghṛtaprasthaṃ pācayet tat samānaṃ pūrveṇa" },
      { type: "verse", number: "34", sanskrit: "रक्तस्तम्भनाय च शीताभ्यङ्गप्रदेहसेकावगाहादीन् प्रयुञ्जीत तदशान्तौ यथोदितानि घृतानि कवोष्णान्यवपीडकयोजनया पाययेत् कवोष्णानेव च घृतैतलक्षीररसकानथवा स्निग्धोष्णैर्मांसरसैर्भोजयित्वा घृतमण्डेन कोष्णेनानुवासयेत् शीतवीर्यद्रव्यसिद्धेन वा यथास्वं स्नेहेन शाल्मलीपुष्पयवासकुशकाशमूलन्यग्रोधोदुम्बराश्वत्थशृङ्गान् द्विपलाशान् क्षीरप्रस्थेन त्रिगुणोदकेन साधयित्वा क्षीरावशेषमवतारयेत् स निर्यूहः शाल्मलीनिर्याससमङ्गाचन्दनोत्पलेन्द्रयवप्रियङ्गुपद्मकेसरकल्कगर्भो घृतक्षौद्रशर्करोपेतः पिच्छाबस्तिर्गुदभ्रंशप्रवाहिकारक्तस्रुतिज्वरघ्नः", text: "raktastambhanāya ca śītābhyaṅgapradehasekāvagāhādīn prayuñjīta tadaśāntau yathoditāni ghṛtāni kavoṣṇānyavapīḍakayojanayā pāyayet kavoṣṇāneva ca ghṛtaitalakṣīrarasakānathavā snigdhoṣṇairmāṃsarasairbhojayitvā ghṛtamaṇḍena koṣṇenānuvāsayet śītavīryadravyasiddhena vā yathāsvaṃ snehena śālmalīpuṣpayavāsakuśakāśamūlanyagrodhodumbarāśvatthaśṛṅgān dvipalāśān kṣīraprasthena triguṇodakena sādhayitvā kṣīrāvaśeṣamavatārayet sa niryūhaḥ śālmalīniryāsasamaṅgācandanotpalendrayavapriyaṅgupadmakesarakalkagarbho ghṛtakṣaudraśarkaropetaḥ picchābastirgudabhraṃśapravāhikāraktasrutijvaraghnaḥ" },
      { type: "verse", number: "35", sanskrit: "अपिच लाजैः पेया पीता चुक्रीकाकेसरोत्पलैः सिद्धा हन्त्याशु रक्तरोगं तथा बलापृश्निपर्णीभ्याम्", text: "apica lājaiḥ peyā pītā cukrīkākesarotpalaiḥ siddhā hantyāśu raktarogaṃ tathā balāpṛśniparṇībhyām" },
      { type: "verse", number: "36", sanskrit: "ह्रीबेरबिल्वनागरनिर्यूहे साधितां सनवनीताम् वृक्षाम्लदाडिमाम्लामम्लीकाम्लां सकोलाम्लाम्", text: "hrīberabilvanāgaraniryūhe sādhitāṃ sanavanītām vṛkṣāmladāḍimāmlāmamlīkāmlāṃ sakolāmlām" },
      { type: "verse", number: "37", sanskrit: "गृञ्जनकसुरससिद्धां दद्याद्यमकेन भर्जितां पेयाम् रक्तातिसारग्रहणीप्रवाहिकाशोफनिग्रहणीम्", text: "gṛñjanakasurasasiddhāṃ dadyādyamakena bharjitāṃ peyām raktātisāragrahaṇīpravāhikāśophanigrahaṇīm" },
      { type: "verse", number: "38", sanskrit: "काश्मर्यामलकानां सकच्छुराणां खलान् फलाम्लांश्च गृञ्जनकशाल्मलीनां दुग्धीकाचुक्रिकाणां च", text: "kāśmaryāmalakānāṃ sakacchurāṇāṃ khalān phalāmlāṃśca gṛñjanakaśālmalīnāṃ dugdhīkācukrikāṇāṃ ca" },
      { type: "verse", number: "39", sanskrit: "न्यग्रोधशृङ्गिकानां खलांस्तथा कोचिदारपुष्पाणाम् दध्नः सरेण सिद्धान् दद्याद्रक्ते प्रवृत्ते ऽति", text: "nyagrodhaśṛṅgikānāṃ khalāṃstathā kocidārapuṣpāṇām dadhnaḥ sareṇa siddhān dadyādrakte pravṛtte 'ti" },
      { type: "verse", number: "40", sanskrit: "सिद्धं पलाण्डुशाकं तक्रेणोपोदकां सबदरां च रुधिरस्रुतौ प्रदद्यान्मसूरसूपं सतक्राम्लम्", text: "siddhaṃ palāṇḍuśākaṃ takreṇopodakāṃ sabadarāṃ ca rudhirasrutau pradadyānmasūrasūpaṃ satakrāmlam" },
      { type: "verse", number: "41", sanskrit: "पयसा शृतेन यूषैः सतीनमुद्गाढकीमसूराणाम् भोजनमद्यादम्लैः शालिश्यामाककोद्रवजम्", text: "payasā śṛtena yūṣaiḥ satīnamudgāḍhakīmasūrāṇām bhojanamadyādamlaiḥ śāliśyāmākakodravajam" },
      { type: "verse", number: "42", sanskrit: "शशहरिणलावमांसैः सकपिञ्जलैणेयकैः सुसिद्धैश्च शालीनद्यान्मधुरैरम्लैरीषत्समरिचैर्वा", text: "śaśahariṇalāvamāṃsaiḥ sakapiñjalaiṇeyakaiḥ susiddhaiśca śālīnadyānmadhurairamlairīṣatsamaricairvā" },
      { type: "verse", number: "43", sanskrit: "दक्षशिखितित्तिरिरसौर्द्विककुल्लोपाकजैश्च मधुराम्लैः अद्याद्रसैरतिवहेष्वर्शःस्वनिलोल्बणशरीरः", text: "dakṣaśikhitittirirasaurdvikakullopākajaiśca madhurāmlaiḥ adyādrasairativaheṣvarśaḥsvanilolbaṇaśarīraḥ" },
      { type: "verse", number: "44", sanskrit: "छगलीपयः प्रयुक्तं निहन्तिरक्तं सवास्तुकरसश्च धन्वविहगमृगाणां रसो निरम्लः कदम्लो वा", text: "chagalīpayaḥ prayuktaṃ nihantiraktaṃ savāstukarasaśca dhanvavihagamṛgāṇāṃ raso niramlaḥ kadamlo vā" },
      { type: "verse", number: "45", sanskrit: "रसखलशाकयवागूघृतयुक्तः केवलो ऽथवा जयति रक्तमतिवर्तमानं वातं च पलाण्डुरुपयुक्तः छागान्तराधितरुणं सरुधिरमुपसाधितं बहुपलाण्डु", text: "rasakhalaśākayavāgūghṛtayuktaḥ kevalo 'thavā jayati raktamativartamānaṃ vātaṃ ca palāṇḍurupayuktaḥ chāgāntarādhitaruṇaṃ sarudhiramupasādhitaṃ bahupalāṇḍu" },
      { type: "verse", number: "46", sanskrit: "व्यत्यासान्मधुरामं विट्शोणितसङ्क्षये योज्यम् नवनीततिलाभ्यासात् केसरनवनीतशर्कराभ्यासात् दधिसरमथिताभ्यासात् गुदजाः शाम्यन्ति रक्तवहाः", text: "vyatyāsānmadhurāmaṃ viṭśoṇitasaṅkṣaye yojyam navanītatilābhyāsāt kesaranavanītaśarkarābhyāsāt dadhisaramathitābhyāsāt gudajāḥ śāmyanti raktavahāḥ" },
      { type: "verse", number: "47", sanskrit: "नवनीतघृतं छागं सपयोमांसं सषष्टिकः शालिः तरुणश्च सुरामण्डस्तरुणीव सुरा जयत्यस्रम्", text: "navanītaghṛtaṃ chāgaṃ sapayomāṃsaṃ saṣaṣṭikaḥ śāliḥ taruṇaśca surāmaṇḍastaruṇīva surā jayatyasram" },
      { type: "verse", number: "48", sanskrit: "प्रायेण वातबहुलान्यर्शांसि भवन्त्यतिस्रुते रक्ते दृष्टे ऽपि हि कफपित्ते तस्मादनिलो ऽधिकं जेयः", text: "prāyeṇa vātabahulānyarśāṃsi bhavantyatisrute rakte dṛṣṭe 'pi hi kaphapitte tasmādanilo 'dhikaṃ jeyaḥ" },
      { type: "verse", number: "49", sanskrit: "दृष्ट्वा शोणितपित्तं प्रबलं कफवातरूपमल्पं च शीताः क्रियाः प्रयोज्या यथेरिताः पित्तरोगेषु", text: "dṛṣṭvā śoṇitapittaṃ prabalaṃ kaphavātarūpamalpaṃ ca śītāḥ kriyāḥ prayojyā yatheritāḥ pittarogeṣu" },
      { type: "verse", number: "50", sanskrit: "उदावर्ते तु दोषविलयनाय शीतज्वरघ्नतैलाभ्यक्तस्विन्नस्य श्यामात्रिवृत्पिप्पलीनिकुम्भनीलिनीचूर्णं गोमूत्रपरिपीतं द्विगुणलवणगुडेन कराङ्गुष्ठाकारां वर्तिं कृत्वा घृताभ्यक्तगुदस्य गुदे वातविण्मूत्रानुलोमनार्थं निदध्यात् पिप्पलीमदनफलसर्षपागारधूमैर्वा समूत्रगुडैः तुम्बीकरघाटकणासिद्धार्थकसैन्धवजीमूतकैर्वा एतेषामेव वा चूर्णं नाड्या प्रधमेत् तद्विघाते त्वानुलोमिकौषधतैलमूत्राम्ललवणक्षारयुक्तं सुतीक्ष्णमास्थापनं दद्यात्", text: "udāvarte tu doṣavilayanāya śītajvaraghnatailābhyaktasvinnasya śyāmātrivṛtpippalīnikumbhanīlinīcūrṇaṃ gomūtraparipītaṃ dviguṇalavaṇaguḍena karāṅguṣṭhākārāṃ vartiṃ kṛtvā ghṛtābhyaktagudasya gude vātaviṇmūtrānulomanārthaṃ nidadhyāt pippalīmadanaphalasarṣapāgāradhūmairvā samūtraguḍaiḥ tumbīkaraghāṭakaṇāsiddhārthakasaindhavajīmūtakairvā eteṣāmeva vā cūrṇaṃ nāḍyā pradhamet tadvighāte tvānulomikauṣadhatailamūtrāmlalavaṇakṣārayuktaṃ sutīkṣṇamāsthāpanaṃ dadyāt" },
      { type: "verse", number: "51", sanskrit: "त्रिफलात्रिकटुत्रिलवणदन्तीचित्रकभल्लातकानि जर्जरितानि सस्नेहमूत्राणि शरावद्वयकोष्ठे मृत्प्रलिप्ते गोमयाग्निना विपचेत् स कल्याणकाख्यः क्षारः क्षीरमांसरसाशिना घृतेन पीतो ऽन्नपाने वा प्रणीतो ऽर्शोगुल्मपाण्डुहृद्रोगोदावर्तग्रहणीमूत्रविबन्धाश्मरीकृमिश्वयथुहिध्माश्वासकासशूलानाहप्लीहमेहापहः वैरेचनिकमूलफलानि सहिंस्रार्कमूलदशमूलगुडाद्वीपिद्विपुनर्नवानि सर्वैश्च तुल्यानि पञ्चलवणानि क्षारः पूर्ववत् कृतः काङ्कायनोक्तो ऽधिकगुणः पूर्वस्मात् हिङ्गुपाठात्र्यूषणत्रिफलाकटभीबिल्वमध्यायोरजः कटुकापञ्चकोलकमुस्तकुष्ठक्षारद्वयमुष्ककमधुकोग्रगन्धाविडङ्गमूर्वाजमोदेन्द्रयवगुडूचीदेवदारूणि कार्षिकाणिपृथक् पलांशानि पञ्चलवणान्यैकध्यमापोथ्य घृततैलकुडवेन दधिकुडवेन च संयोज्य कल्याणकविधिना दग्धो महाक्षारस्तत्तुल्यः सर्वगरविषनिबर्हणश्च प्राग्भक्तं वा वितरेत् घृतगुडयवक्षारान्", text: "triphalātrikaṭutrilavaṇadantīcitrakabhallātakāni jarjaritāni sasnehamūtrāṇi śarāvadvayakoṣṭhe mṛtpralipte gomayāgninā vipacet sa kalyāṇakākhyaḥ kṣāraḥ kṣīramāṃsarasāśinā ghṛtena pīto 'nnapāne vā praṇīto 'rśogulmapāṇḍuhṛdrogodāvartagrahaṇīmūtravibandhāśmarīkṛmiśvayathuhidhmāśvāsakāsaśūlānāhaplīhamehāpahaḥ vairecanikamūlaphalāni sahiṃsrārkamūladaśamūlaguḍādvīpidvipunarnavāni sarvaiśca tulyāni pañcalavaṇāni kṣāraḥ pūrvavat kṛtaḥ kāṅkāyanokto 'dhikaguṇaḥ pūrvasmāt hiṅgupāṭhātryūṣaṇatriphalākaṭabhībilvamadhyāyorajaḥ kaṭukāpañcakolakamustakuṣṭhakṣāradvayamuṣkakamadhukogragandhāviḍaṅgamūrvājamodendrayavaguḍūcīdevadārūṇi kārṣikāṇipṛthak palāṃśāni pañcalavaṇānyaikadhyamāpothya ghṛtatailakuḍavena dadhikuḍavena ca saṃyojya kalyāṇakavidhinā dagdho mahākṣārastattulyaḥ sarvagaraviṣanibarhaṇaśca prāgbhaktaṃ vā vitaret ghṛtaguḍayavakṣārān" },
      { type: "verse", number: "52", sanskrit: "दाडिमरसं वा सयवानीपाठामहौषधलवणगुडतक्रम् यमकस्नेहभृष्टान् वा सक्तुयुक्तान् करञ्जप्रसवान् दधिदाडिमाम्लबदरतिन्तिणीकमातुलुङ्गलवणसुरां यमकसंस्कृताम् त्रिवृद्दन्तीगुडचित्रकचाङ्गेरीबालमूलकलोणीकासुवर्चलोपोदकाचुञ्चुपर्णीवीरावास्तुकपल्लवांस्तथा दक्षशिखिश्वाविङ्गोधामार्जारोष्ट्रलोपाककूर्मशल्यकमांसान् मांसरसान् यवप्रायं चान्नं भोजनार्थे पानार्थे तु सपिप्पलीचूर्णं गौडमच्छसुरां सलवणानासवांश्च दीपनीयवातहरानारनालमस्तु वा संस्कृतम्", text: "dāḍimarasaṃ vā sayavānīpāṭhāmahauṣadhalavaṇaguḍatakram yamakasnehabhṛṣṭān vā saktuyuktān karañjaprasavān dadhidāḍimāmlabadaratintiṇīkamātuluṅgalavaṇasurāṃ yamakasaṃskṛtām trivṛddantīguḍacitrakacāṅgerībālamūlakaloṇīkāsuvarcalopodakācuñcuparṇīvīrāvāstukapallavāṃstathā dakṣaśikhiśvāviṅgodhāmārjāroṣṭralopākakūrmaśalyakamāṃsān māṃsarasān yavaprāyaṃ cānnaṃ bhojanārthe pānārthe tu sapippalīcūrṇaṃ gauḍamacchasurāṃ salavaṇānāsavāṃśca dīpanīyavātaharānāranālamastu vā saṃskṛtam" },
      { type: "verse", number: "53", sanskrit: "अनुबन्धे तु भूयो मदिरामस्तुमूत्रयुक्तं विरेकम् सपिप्पलीं वा घृतभृष्टां सगुडां हरीतकीं सकुम्भनिकुम्भां वा द्विविधोपक्रमणीयोदितान् वा तर्पणप्रयोगान् त्रिवृच्चूर्णं वा त्रिफलारसानुविद्धम् अभयामलकविडङ्गान् वा समत्रिवृतान् सगुडान् माणिभद्रकाख्यान् मिश्रकस्नेहं सुकुमारकं नीलिनीघृतं वा कल्पोदितानि वा विरेचनान्यवचारयेत् गुदाश्रये हि दोषे ऽपहृते व्याधयो ऽपि तज्जाः प्रशाम्यन्ति", text: "anubandhe tu bhūyo madirāmastumūtrayuktaṃ virekam sapippalīṃ vā ghṛtabhṛṣṭāṃ saguḍāṃ harītakīṃ sakumbhanikumbhāṃ vā dvividhopakramaṇīyoditān vā tarpaṇaprayogān trivṛccūrṇaṃ vā triphalārasānuviddham abhayāmalakaviḍaṅgān vā samatrivṛtān saguḍān māṇibhadrakākhyān miśrakasnehaṃ sukumārakaṃ nīlinīghṛtaṃ vā kalpoditāni vā virecanānyavacārayet gudāśraye hi doṣe 'pahṛte vyādhayo 'pi tajjāḥ praśāmyanti" },
      { type: "verse", number: "54", sanskrit: "रूक्षतया च विड्वातविब्न्धेन शूलोदावर्तसम्भवः तस्मात्तत्राशुतरं स्नेहनमनुवासनं विदध्यात् पिप्पलीमदनबिल्ववचामधुकशतपुष्पाशठीकुष्ठपुष्करमूलद्वीपिदेवदारुभिः श्लक्ष्णपिष्टैर्द्विगुणपयस्तैलं सिद्धमर्शोगुदभ्रंशयोनिशूलवङ्क्षणानाहगुदशोफोत्थानप्रवाहिकपिच्छास्रावोरुकटीपृष्ठदौर्बल्यवैवर्ण्यमूत्रकृच्छ्रनिषूदनं वातमूत्रशकृत्पित्तश्लेष्मानुलोमकरं च वातानुलोम्ये हि सति ध्रुवमनलो याति दीप्तिमर्शांसि चातः सङ्कोचमिति भवन्ति चात्र", text: "rūkṣatayā ca viḍvātavibndhena śūlodāvartasambhavaḥ tasmāttatrāśutaraṃ snehanamanuvāsanaṃ vidadhyāt pippalīmadanabilvavacāmadhukaśatapuṣpāśaṭhīkuṣṭhapuṣkaramūladvīpidevadārubhiḥ ślakṣṇapiṣṭairdviguṇapayastailaṃ siddhamarśogudabhraṃśayoniśūlavaṅkṣaṇānāhagudaśophotthānapravāhikapicchāsrāvorukaṭīpṛṣṭhadaurbalyavaivarṇyamūtrakṛcchraniṣūdanaṃ vātamūtraśakṛtpittaśleṣmānulomakaraṃ ca vātānulomye hi sati dhruvamanalo yāti dīptimarśāṃsi cātaḥ saṅkocamiti bhavanti cātra" },
      { type: "verse", number: "55", sanskrit: "अर्शांसि शस्त्रक्षाराग्निलेपाभ्यङ्गैरुपाचरेत् दृश्यान्यदृश्यानि पुनः सदान्तःपरिमार्जनैः", text: "arśāṃsi śastrakṣārāgnilepābhyaṅgairupācaret dṛśyānyadṛśyāni punaḥ sadāntaḥparimārjanaiḥ" },
      { type: "verse", number: "56", sanskrit: "अल्पकालोत्थितेष्वल्पलिङ्गदोषेषु चौषधम् नात्युच्छ्रितेषु मृदुषु क्षारो ऽस्रस्रुतिमत्सु च", text: "alpakālotthiteṣvalpaliṅgadoṣeṣu cauṣadham nātyucchriteṣu mṛduṣu kṣāro 'srasrutimatsu ca" },
      { type: "verse", number: "57", sanskrit: "उच्छ्रितेष्वल्पमूलेषु शस्तं शस्त्रं कुनामसु युक्तेषु स्थैर्यकाठिन्यकार्कश्यैः शस्त्रपावकौ", text: "ucchriteṣvalpamūleṣu śastaṃ śastraṃ kunāmasu yukteṣu sthairyakāṭhinyakārkaśyaiḥ śastrapāvakau" },
      { type: "verse", number: "58", sanskrit: "योज्यौ महत्सु वा क्षारः पाटयित्वा विकुट्य वा सूचीकूर्चेन तद्वच्च बडिशं तेषु शस्त्रकम्", text: "yojyau mahatsu vā kṣāraḥ pāṭayitvā vikuṭya vā sūcīkūrcena tadvacca baḍiśaṃ teṣu śastrakam" },
      { type: "verse", number: "59", sanskrit: "अतिस्थूलातिदीर्घे तु यन्त्रके मर्मघट्टनम् अणुच्छिद्रे महद्रूपमेकदेशे ऽवशिष्यते", text: "atisthūlātidīrghe tu yantrake marmaghaṭṭanam aṇucchidre mahadrūpamekadeśe 'vaśiṣyate" },
      { type: "verse", number: "60", sanskrit: "अतिच्छिद्रे ऽधिकं रूपादवतीर्णं प्रवाहणात् स्थूलान्त्रमति हिंस्याच्च यथोक्तं योजयेदतः", text: "aticchidre 'dhikaṃ rūpādavatīrṇaṃ pravāhaṇāt sthūlāntramati hiṃsyācca yathoktaṃ yojayedataḥ" },
      { type: "verse", number: "61", sanskrit: "शुष्केषु भल्लातकमग्र्यमुक्तं भैषज्यमार्द्रेषु तु वत्सकत्वक् सर्वेषु सर्वर्तुषु कालशेय मर्शःसु बल्यं च मलापहं च", text: "śuṣkeṣu bhallātakamagryamuktaṃ bhaiṣajyamārdreṣu tu vatsakatvak sarveṣu sarvartuṣu kālaśeya marśaḥsu balyaṃ ca malāpahaṃ ca" },
      { type: "verse", number: "62", sanskrit: "भित्त्वा विबन्धाननुलोमनाय यन्मारुतस्याग्निबलाय यच्च तदन्नपानौषधमर्शसेन सेव्यं विवर्ज्यं विपरीतमस्मात्", text: "bhittvā vibandhānanulomanāya yanmārutasyāgnibalāya yacca tadannapānauṣadhamarśasena sevyaṃ vivarjyaṃ viparītamasmāt" },
      { type: "verse", number: "63", sanskrit: "अर्शो ऽतिसारग्रहणीविकाराः प्रायेण चान्योन्यनिदानभूताः सन्ने ऽनले सन्ति न सन्ति दीप्ते रक्षेदतस्तेषु विशेषतो ऽग्निम्", text: "arśo 'tisāragrahaṇīvikārāḥ prāyeṇa cānyonyanidānabhūtāḥ sanne 'nale santi na santi dīpte rakṣedatasteṣu viśeṣato 'gnim" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 11,
    lang: "sa",
    content: [
      { type: "heading", heading: "Камила чикитса — лечение желтухи" },
      { type: "text", text: "Глава 11 Чикитса стханы — лечебный раздел о лечение желтухи. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो ऽतीसारचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto 'tīsāracikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "प्रायेणातिसारो ह्यग्निमुपहत्य प्रागामाधिष्ठानो भवति तस्मादनिलजमप्यामपाचनार्थमादौ लङ्घनेनोपक्रमेत तत्र शूलानाहप्रसेकार्तं लवणाम्बुनोष्णेन वामयेत् न तु सामे पूर्वं सङ्ग्राहि प्रयुञ्जीत विबद्धे वा मले स्तिमिताध्मातगुरुसरुजकोष्ठः प्राणदामुष्णाम्बुनोपयुञ्जीत सव्योष्णां वा धान्याम्लक्वथितां वा अन्यद्वा स्रंसनदीपनमौषधम्", text: "prāyeṇātisāro hyagnimupahatya prāgāmādhiṣṭhāno bhavati tasmādanilajamapyāmapācanārthamādau laṅghanenopakrameta tatra śūlānāhaprasekārtaṃ lavaṇāmbunoṣṇena vāmayet na tu sāme pūrvaṃ saṅgrāhi prayuñjīta vibaddhe vā male stimitādhmātagurusarujakoṣṭhaḥ prāṇadāmuṣṇāmbunopayuñjīta savyoṣṇāṃ vā dhānyāmlakvathitāṃ vā anyadvā sraṃsanadīpanamauṣadham" },
      { type: "verse", number: "3", sanskrit: "अपिच विशुद्धस्रोतसो ह्यस्य दोषशेषे प्रवाहिते सुखं सङ्ग्रहणं कर्तुं पाचनैः स्तम्भ्नेन वा", text: "apica viśuddhasrotaso hyasya doṣaśeṣe pravāhite sukhaṃ saṅgrahaṇaṃ kartuṃ pācanaiḥ stambhnena vā" },
      { type: "verse", number: "4", sanskrit: "मध्यदोषस्तु विशोषयन् मागधीनागरवचाभूतीकधनिकाहरीतकीनां क्वाथं पिबेत् जलजलदबिल्वपेशिकाशुण्ठीधान्यकानां वा उभयमपि चैतत् प्रमथ्याख्यम् वचादिवर्गं क्वथितं चूर्णितं वा तद्वद्वचाभयाविडङ्गपाठाशुण्ठीबिडलवणानि वा मुस्तपिप्पलीन्द्रयवपाठातेजोवतीर्वा विडङ्गाभयाकणलवणपञ्चकानि वा पिप्पलीन्द्रयवपाठाशुण्ठीर्वा सरक्ते तु प्रवृत्त आमे गजपिप्पलीं मधुशर्करामधुराम्", text: "madhyadoṣastu viśoṣayan māgadhīnāgaravacābhūtīkadhanikāharītakīnāṃ kvāthaṃ pibet jalajaladabilvapeśikāśuṇṭhīdhānyakānāṃ vā ubhayamapi caitat pramathyākhyam vacādivargaṃ kvathitaṃ cūrṇitaṃ vā tadvadvacābhayāviḍaṅgapāṭhāśuṇṭhībiḍalavaṇāni vā mustapippalīndrayavapāṭhātejovatīrvā viḍaṅgābhayākaṇalavaṇapañcakāni vā pippalīndrayavapāṭhāśuṇṭhīrvā sarakte tu pravṛtta āme gajapippalīṃ madhuśarkarāmadhurām" },
      { type: "verse", number: "5", sanskrit: "अल्पदोषं पुनरुपवासयेत् पानं त्वतिसारिणोम्बु वचातिविषाभ्यां क्वथितम् शुण्ठ्यतिविषाभ्यां मुस्तपर्पटकाभ्यां नागरधान्यकाभ्यां वा क्षुद्वतस्तु लघुपञ्चमूलपञ्चकोलहस्तिपिप्पलीबलाबिल्वपाठाहिङ्गुधान्यकजीरकशठीगन्धपलाशहपुषायवानीतिन्तिणीकदाडिमबिडसैन्धवैरन्नपानं यवाग्वादि कल्पयेत्", text: "alpadoṣaṃ punarupavāsayet pānaṃ tvatisāriṇombu vacātiviṣābhyāṃ kvathitam śuṇṭhyativiṣābhyāṃ mustaparpaṭakābhyāṃ nāgaradhānyakābhyāṃ vā kṣudvatastu laghupañcamūlapañcakolahastipippalībalābilvapāṭhāhiṅgudhānyakajīrakaśaṭhīgandhapalāśahapuṣāyavānītintiṇīkadāḍimabiḍasaindhavairannapānaṃ yavāgvādi kalpayet" },
      { type: "verse", number: "6", sanskrit: "बिल्वशलाटुहरीतकीपिप्पलीमूलैर्मूढवातस्य अंशुमतीद्वयबलाबिल्वशलाटुभिः पित्तोल्बणस्य पिबेच्च तृषितः पटपूतं तक्रम् मधुसुराधान्याम्लयवागूमण्डान्यतमं वा एष क्रमो ऽनिलकफघ्नो दीपनपाचनो रोचनः सङ्ग्राही बल्यश्च", text: "bilvaśalāṭuharītakīpippalīmūlairmūḍhavātasya aṃśumatīdvayabalābilvaśalāṭubhiḥ pittolbaṇasya pibecca tṛṣitaḥ paṭapūtaṃ takram madhusurādhānyāmlayavāgūmaṇḍānyatamaṃ vā eṣa kramo 'nilakaphaghno dīpanapācano rocanaḥ saṅgrāhī balyaśca" },
      { type: "verse", number: "7", sanskrit: "पक्वदोषो ऽपि तु यो ऽतिसार्यते बहुशो ऽनिलेन विबद्धं सपिच्छं सफेनं सशूलपरिकर्तिकं सरोमहर्षं निष्पुरीषं च तां प्रवाहिकां बिम्बिसीमिति चाचक्षते तत्रोदावर्तोपदिष्टांस्तेनैव विधिना संस्कृतांश्छागपिशितरसान् दद्यात्", text: "pakvadoṣo 'pi tu yo 'tisāryate bahuśo 'nilena vibaddhaṃ sapicchaṃ saphenaṃ saśūlaparikartikaṃ saromaharṣaṃ niṣpurīṣaṃ ca tāṃ pravāhikāṃ bimbisīmiti cācakṣate tatrodāvartopadiṣṭāṃstenaiva vidhinā saṃskṛtāṃśchāgapiśitarasān dadyāt" },
      { type: "verse", number: "8", sanskrit: "यूषांश्च वर्चःक्षये तृष्यतो यवमुद्गमाषतिलकृतान् समेन वा तिलबालबिल्वयोः कल्केन दधिसरस्नेहयुक्तं खलकम् चित्रकशृङ्गवेरपूतीकरञ्जबिल्वाजमोदैर्वा तक्रदाडिमतैलाढ्यं सैन्धवोपेतमजिताख्यम् शठीतिन्तिणीकबिडदाडिमक्षारपञ्चकोलमरिचत्रिफलाधातकीधनिकापाठाजमोदाजाजीजीरककपित्थजम्ब्वाम्रास्थिभिर्वा तुल्यभागैः षड्गुणबिल्वमध्यैर्गुडमुद्गरसस्नेहदधिसिद्धो ऽपराजिताख्यः खलको दीपनः पाचनो रुच्यो ग्राही बिम्बिसिनाशनः", text: "yūṣāṃśca varcaḥkṣaye tṛṣyato yavamudgamāṣatilakṛtān samena vā tilabālabilvayoḥ kalkena dadhisarasnehayuktaṃ khalakam citrakaśṛṅgaverapūtīkarañjabilvājamodairvā takradāḍimatailāḍhyaṃ saindhavopetamajitākhyam śaṭhītintiṇīkabiḍadāḍimakṣārapañcakolamaricatriphalādhātakīdhanikāpāṭhājamodājājījīrakakapitthajambvāmrāsthibhirvā tulyabhāgaiḥ ṣaḍguṇabilvamadhyairguḍamudgarasasnehadadhisiddho 'parājitākhyaḥ khalako dīpanaḥ pācano rucyo grāhī bimbisināśanaḥ" },
      { type: "verse", number: "9", sanskrit: "दधिसरं वा सगुडदाडिमं यमकभृष्टम् यमकभृष्टान् वा सशुण्ठीचूर्णान् सक्तून् माषान् वा सुसिद्धान् घृतमण्डोपसेच्नान् मरिचोपदंशान् छागमेषयोर्वान्तराधिरसं दाडिमाम्लं धान्यनागरोपेतं स्नेहविपक्वं व्यञ्जनं पानं च तद्वत् सुरां यमकस्निग्धां पिबेद्वा शुण्ठीबदरचूर्णं दधिघृततैलक्षौद्रफाणितोपेतम्", text: "dadhisaraṃ vā saguḍadāḍimaṃ yamakabhṛṣṭam yamakabhṛṣṭān vā saśuṇṭhīcūrṇān saktūn māṣān vā susiddhān ghṛtamaṇḍopasecnān maricopadaṃśān chāgameṣayorvāntarādhirasaṃ dāḍimāmlaṃ dhānyanāgaropetaṃ snehavipakvaṃ vyañjanaṃ pānaṃ ca tadvat surāṃ yamakasnigdhāṃ pibedvā śuṇṭhībadaracūrṇaṃ dadhighṛtatailakṣaudraphāṇitopetam" },
      { type: "verse", number: "10", sanskrit: "हिङ्गुदाडिममहौषधोपकुल्याचूर्णं वा घृतक्षीरोष्णाम्बुमद्यान्यतमेन लिह्याद्वा लोध्रबिल्वशलाटुगुडांस्त्रिकटुकोत्कटांस्तैलेन अश्वत्थवातपोतक्वाथसिद्धं वा शाल्योदनं घृततैलक्षौद्रयुक्तं दध्ना खजाहतदधिसरानुपानमश्नीयात्", text: "hiṅgudāḍimamahauṣadhopakulyācūrṇaṃ vā ghṛtakṣīroṣṇāmbumadyānyatamena lihyādvā lodhrabilvaśalāṭuguḍāṃstrikaṭukotkaṭāṃstailena aśvatthavātapotakvāthasiddhaṃ vā śālyodanaṃ ghṛtatailakṣaudrayuktaṃ dadhnā khajāhatadadhisarānupānamaśnīyāt" },
      { type: "verse", number: "11", sanskrit: "अपि च दीपनं रोचनं रुच्यं दधि वातहरं परम् बद्धविड्वा हरत्यस्मात् चिरोत्थामपि बिम्बिसीम्", text: "api ca dīpanaṃ rocanaṃ rucyaṃ dadhi vātaharaṃ param baddhaviḍvā haratyasmāt cirotthāmapi bimbisīm" },
      { type: "verse", number: "12", sanskrit: "तृष्णोल्बणस्तु सरक्तपिच्छोपवेशी पानान्नविरतो धारोष्णं क्षीरमाकाङ्क्षं पिबेत् शृतं वा गन्धर्वहस्तमूलेनाथवा बिल्वशलाटुभिः तदेव वाल्पतृष्णः सगुडतैलम् शृतेन वा पयसा मरिचकल्कं द्विगुणतिलकल्कयुक्तम् क्षीरेणैव वा पिप्पलीम् व्योषसिद्धेन वा पयसान्नानि भुञ्जीत", text: "tṛṣṇolbaṇastu saraktapicchopaveśī pānānnavirato dhāroṣṇaṃ kṣīramākāṅkṣaṃ pibet śṛtaṃ vā gandharvahastamūlenāthavā bilvaśalāṭubhiḥ tadeva vālpatṛṣṇaḥ saguḍatailam śṛtena vā payasā maricakalkaṃ dviguṇatilakalkayuktam kṣīreṇaiva vā pippalīm vyoṣasiddhena vā payasānnāni bhuñjīta" },
      { type: "verse", number: "13", sanskrit: "शूलाधिक्ये तु दशमूलक्वथितेन पयसा सक्षौद्रेणास्थापनं दद्यात् अथवा पिच्छाबस्तिमनुवासनं च वातघ्नं वा पित्तघ्नं वा", text: "śūlādhikye tu daśamūlakvathitena payasā sakṣaudreṇāsthāpanaṃ dadyāt athavā picchābastimanuvāsanaṃ ca vātaghnaṃ vā pittaghnaṃ vā" },
      { type: "verse", number: "14", sanskrit: "गुदभ्रंशे शूले चाम्लबदरचाङ्गेरीरसदधिक्षारनागरकल्केन शृतमम्लं सर्पिर्निराममातुरं पाययेत् मरिचपञ्चकोलाजाजीधनिकाबिडदाडिमगर्भं वा पूर्ववदम्लम् अनुवासयेद्वा दशमूलसिद्धेन स्नेहेन पिप्पल्यादिना वा", text: "gudabhraṃśe śūle cāmlabadaracāṅgerīrasadadhikṣāranāgarakalkena śṛtamamlaṃ sarpirnirāmamāturaṃ pāyayet maricapañcakolājājīdhanikābiḍadāḍimagarbhaṃ vā pūrvavadamlam anuvāsayedvā daśamūlasiddhena snehena pippalyādinā vā" },
      { type: "verse", number: "15", sanskrit: "गुदं चाभ्यङ्गपूर्वं स्वेदेन मृदुभूतं प्रवेशयेत् सच्छिद्रेण चास्य चर्मणा गोष्फणाबन्धं कुर्यात् मूषकमनान्त्रं कृत्वा महापञ्चमूलकषायं च क्षीरे विपचेत् तेन पयसा वातहरकल्कप्रतीवापं तैलं पाचयेत् तदभ्यञ्जनेन पानेन च सुकृच्छ्रमपि गुदभ्रंशं साधयति", text: "gudaṃ cābhyaṅgapūrvaṃ svedena mṛdubhūtaṃ praveśayet sacchidreṇa cāsya carmaṇā goṣphaṇābandhaṃ kuryāt mūṣakamanāntraṃ kṛtvā mahāpañcamūlakaṣāyaṃ ca kṣīre vipacet tena payasā vātaharakalkapratīvāpaṃ tailaṃ pācayet tadabhyañjanena pānena ca sukṛcchramapi gudabhraṃśaṃ sādhayati" },
      { type: "verse", number: "16", sanskrit: "पित्तातिसारमपि साममादौ तीक्ष्णवर्ज्यैरौषधैर्वातातिसारवत् पाचयेत् तृष्णायां ससारिवाभूनिम्बं ज्वरविहितमम्भः षडङ्गमवचारयेत् उपोषितस्य चान्नकाले ऽभीरुदृस्वपञ्चमूलबलाद्वयशूर्पर्ण्यादिमृदुमधुरतिक्तदीपनद्रव्यनिर्यूहयुज्क्तान् कालविन्मण्डपेयासक्तुयूषरसादीनीषदम्लाननम्लान् वा कवोष्णान् सुशीतान् वा सक्षौद्रान्", text: "pittātisāramapi sāmamādau tīkṣṇavarjyairauṣadhairvātātisāravat pācayet tṛṣṇāyāṃ sasārivābhūnimbaṃ jvaravihitamambhaḥ ṣaḍaṅgamavacārayet upoṣitasya cānnakāle 'bhīrudṛsvapañcamūlabalādvayaśūrparṇyādimṛdumadhuratiktadīpanadravyaniryūhayujktān kālavinmaṇḍapeyāsaktuyūṣarasādīnīṣadamlānanamlān vā kavoṣṇān suśītān vā sakṣaudrān" },
      { type: "verse", number: "17", sanskrit: "अनुबन्धे तु मूर्वातिविषेन्द्रयवहरिद्रारसाञ्जनानि क्वथितानि पिबेत् केवलं वा वृक्षकबीजम् पाठागुडूचीकटुकाकिराततिक्तानि वा हरिद्रादिगणं वा वत्सकबीजातिविषाबिल्वाम्बुमुस्तानि वा तण्डुलोदकेन वातिविषावृक्षकत्वक्फलानि सक्षौद्राणि चन्दनोशीरशुण्ठीलोध्रनीलोत्पलानि वा नागरोत्पलधातकीपुष्पदाडिमत्वचो वा कमलोत्पललोध्रमोचरससमङ्गातिलान् वा मधुकशृङ्गवेरदीर्घवृन्तत्वचो वा मधुयुक्तानि शर्करापद्मकेसरमुस्तापयस्याचन्दनानि वा शाल्मलीवृन्तकृतं वा शीतकषायं मधुमधुकोपेतम्", text: "anubandhe tu mūrvātiviṣendrayavaharidrārasāñjanāni kvathitāni pibet kevalaṃ vā vṛkṣakabījam pāṭhāguḍūcīkaṭukākirātatiktāni vā haridrādigaṇaṃ vā vatsakabījātiviṣābilvāmbumustāni vā taṇḍulodakena vātiviṣāvṛkṣakatvakphalāni sakṣaudrāṇi candanośīraśuṇṭhīlodhranīlotpalāni vā nāgarotpaladhātakīpuṣpadāḍimatvaco vā kamalotpalalodhramocarasasamaṅgātilān vā madhukaśṛṅgaveradīrghavṛntatvaco vā madhuyuktāni śarkarāpadmakesaramustāpayasyācandanāni vā śālmalīvṛntakṛtaṃ vā śītakaṣāyaṃ madhumadhukopetam" },
      { type: "verse", number: "18", sanskrit: "मधुकप्रियङ्गुकट्वङ्गत्वग्दाडिमाङ्कुरकल्केन वा दधियुतां यवागूं खलकं वा बिल्वकपित्थजम्ब्बाम्रास्थिभिर्वा मधुयुक्तान् वा लोध्राम्बष्ठाप्रियङ्ग्वादिगणान् क्वाथादिषु पृथक् कल्पितान् श्यामादिमहाकषायं वा", text: "madhukapriyaṅgukaṭvaṅgatvagdāḍimāṅkurakalkena vā dadhiyutāṃ yavāgūṃ khalakaṃ vā bilvakapitthajambbāmrāsthibhirvā madhuyuktān vā lodhrāmbaṣṭhāpriyaṅgvādigaṇān kvāthādiṣu pṛthak kalpitān śyāmādimahākaṣāyaṃ vā" },
      { type: "verse", number: "19", sanskrit: "शूलार्तस्तु रूक्षकोष्ठो घृतं सक्षारं पिबेत् क्षीरं वा बृहतीबलांशुमतीकच्छुरामूलसिद्धं मधुककट्वङ्गाजमोदशर्करावचूर्णितं सतैलक्षौद्रम् क्षीरमेव वा धारोष्णम्", text: "śūlārtastu rūkṣakoṣṭho ghṛtaṃ sakṣāraṃ pibet kṣīraṃ vā bṛhatībalāṃśumatīkacchurāmūlasiddhaṃ madhukakaṭvaṅgājamodaśarkarāvacūrṇitaṃ satailakṣaudram kṣīrameva vā dhāroṣṇam" },
      { type: "verse", number: "20", sanskrit: "बलवान् विबद्धमलो विरेकार्थं त्रिफलाचूर्णयुक्तं वा पलाशफलक्वाथसिद्धं वा पयः पीत्वा पय एव कवोष्णमनुपिबेत् एवमेव च त्रायमाणया शृतम् ततो निस्सृते शकृति पुराणे ऽतिसारः शान्तिमेति", text: "balavān vibaddhamalo virekārthaṃ triphalācūrṇayuktaṃ vā palāśaphalakvāthasiddhaṃ vā payaḥ pītvā paya eva kavoṣṇamanupibet evameva ca trāyamāṇayā śṛtam tato nissṛte śakṛti purāṇe 'tisāraḥ śāntimeti" },
      { type: "verse", number: "21", sanskrit: "स्रुतदोषस्य च संसर्जनकाले शूलं चेदनुवर्तेत ततो बिल्वमधुकशताह्वाद्वयगर्भं सक्षीरं तैलचतुर्गुणं सर्पिर्विपाच्यानुवासनं दद्यात् ततः सम्यक्कृतायामपि संसर्ग्यामतीसारानुबन्धे पिच्छाबस्तयो योज्याः शाल्मलीवृन्तान्यार्द्रदर्भैर्वेष्टयित्वा कृष्णमृदावलिप्य गोमयाग्निना स्वेदयेत् शुष्कायां मृदि स्विन्नानि ज्ञात्वा वृन्तान्युलूखले समापेथ्य तेषां मुष्टिसम्मितं पिण्डं क्षीरप्रस्थे विमर्दयेत् ततस्तेन पयसा पूतेन सघृततैलेन मधुमधुककल्कयुक्तेनास्थापयेत् प्रत्यागते च स्नातः पयसा कच्छुराशृतेन जाङ्गलरसैर्वाश्नीयात् एष पिच्छाबस्तिः पित्तरक्तातिसारग्रहणीगुल्मशोषज्वरान् विरेचनास्थापनातियोगं च शमयति", text: "srutadoṣasya ca saṃsarjanakāle śūlaṃ cedanuvarteta tato bilvamadhukaśatāhvādvayagarbhaṃ sakṣīraṃ tailacaturguṇaṃ sarpirvipācyānuvāsanaṃ dadyāt tataḥ samyakkṛtāyāmapi saṃsargyāmatīsārānubandhe picchābastayo yojyāḥ śālmalīvṛntānyārdradarbhairveṣṭayitvā kṛṣṇamṛdāvalipya gomayāgninā svedayet śuṣkāyāṃ mṛdi svinnāni jñātvā vṛntānyulūkhale samāpethya teṣāṃ muṣṭisammitaṃ piṇḍaṃ kṣīraprasthe vimardayet tatastena payasā pūtena saghṛtatailena madhumadhukakalkayuktenāsthāpayet pratyāgate ca snātaḥ payasā kacchurāśṛtena jāṅgalarasairvāśnīyāt eṣa picchābastiḥ pittaraktātisāragrahaṇīgulmaśoṣajvarān virecanāsthāpanātiyogaṃ ca śamayati" },
      { type: "verse", number: "22", sanskrit: "चिरोत्थितं त्वतीसारमवेदनं पक्वमप्यशाम्यन्तं पुटपाकैरुपाचरेत् अरलुकत्वक्कल्कं काश्मर्यपत्रप्रच्छन्नं पुटपाकविधिना पाचयेत् तद्रसं सुशीतं मधुयुतं पिबेत् वटादित्वक्प्ररोहकल्कमप्येवं कल्पयेत् अथवा तित्तिरिमपनीतान्त्रपिच्छं न्यग्रोधादेर्वल्कलस्य प्ररोहाणां वा कल्केन पूरयित्वा पूर्ववत् पुटपाकं कुर्यात् ततः तस्माद्रसमादाय सिताक्षौद्रयुक्तं पाययेत् अनेन सर्वे जाङ्गलसत्वा व्याख्याताः", text: "cirotthitaṃ tvatīsāramavedanaṃ pakvamapyaśāmyantaṃ puṭapākairupācaret aralukatvakkalkaṃ kāśmaryapatrapracchannaṃ puṭapākavidhinā pācayet tadrasaṃ suśītaṃ madhuyutaṃ pibet vaṭāditvakprarohakalkamapyevaṃ kalpayet athavā tittirimapanītāntrapicchaṃ nyagrodhādervalkalasya prarohāṇāṃ vā kalkena pūrayitvā pūrvavat puṭapākaṃ kuryāt tataḥ tasmādrasamādāya sitākṣaudrayuktaṃ pāyayet anena sarve jāṅgalasatvā vyākhyātāḥ" },
      { type: "verse", number: "23", sanskrit: "यस्तु पित्तातिसारी पित्तलान्यासेवेत तस्य पित्तमतिवृद्धं रक्तातिसारं तृड्दाहमोहज्वरशूलपायुपाकांश्च करोति तत्र क्षीरमाजं न्यग्रोधादिप्रसवशृतं सितामधुयुक्तमाहारे गुदप्रक्षालने च विदध्यात् तद्विधं वा सर्पिः सपयस्कं पिबेत् क्षीरोत्थं वा सर्पिः क्षीरानुपानं कपिञ्जलरसाशी क्षीराशी वा लिह्यात्", text: "yastu pittātisārī pittalānyāseveta tasya pittamativṛddhaṃ raktātisāraṃ tṛḍdāhamohajvaraśūlapāyupākāṃśca karoti tatra kṣīramājaṃ nyagrodhādiprasavaśṛtaṃ sitāmadhuyuktamāhāre gudaprakṣālane ca vidadhyāt tadvidhaṃ vā sarpiḥ sapayaskaṃ pibet kṣīrotthaṃ vā sarpiḥ kṣīrānupānaṃ kapiñjalarasāśī kṣīrāśī vā lihyāt" },
      { type: "verse", number: "24", sanskrit: "सल्लकीप्रियङ्गुतिनिशशाल्मलीप्लक्षत्वक्संसृष्टं सिद्धं वा सक्षौद्रं क्षीरं पिबेत् यष्टीलोध्रसारिवाभिर्वा शृतं समधुसितम् तद्वत् कृष्णतिलसमङ्गोत्पलयष्टीमधुभिः शशकपिञ्जलपारावततण्डुलीयकमुद्गकाश्मर्यबीजादिरसांश्च सेवेत घृतभृष्टं वा रक्तमाजं मार्गं वा पूर्वोक्तान् वा पुटपाकान् मधुककृष्णमृत्तिकाशङ्खकल्कं वा सरुधिरं पिबेत् तण्डुलोदकेन तेन वा समाक्षिकं फलिनीकल्कम् अथवा ससिताक्षौद्रं चन्दनम्", text: "sallakīpriyaṅgutiniśaśālmalīplakṣatvaksaṃsṛṣṭaṃ siddhaṃ vā sakṣaudraṃ kṣīraṃ pibet yaṣṭīlodhrasārivābhirvā śṛtaṃ samadhusitam tadvat kṛṣṇatilasamaṅgotpalayaṣṭīmadhubhiḥ śaśakapiñjalapārāvatataṇḍulīyakamudgakāśmaryabījādirasāṃśca seveta ghṛtabhṛṣṭaṃ vā raktamājaṃ mārgaṃ vā pūrvoktān vā puṭapākān madhukakṛṣṇamṛttikāśaṅkhakalkaṃ vā sarudhiraṃ pibet taṇḍulodakena tena vā samākṣikaṃ phalinīkalkam athavā sasitākṣaudraṃ candanam" },
      { type: "verse", number: "25", sanskrit: "एते हि प्रयोगाः तृष्णादिप्रशमना रक्तातियोगघ्नाश्च वातोत्तरस्तु शतावरीघृतं लिह्यात् सशर्करं वा नवनीतम् पिच्छिलस्वरससाधितं वा सर्पिः लाक्षापिप्पलीशृङ्गवेरकटुकेन्द्रयवदार्वीत्वग्भिर्घृतं सिद्धं पेयामण्डेन पीतमतीसारं त्रिदोषमपि वारयति", text: "ete hi prayogāḥ tṛṣṇādipraśamanā raktātiyogaghnāśca vātottarastu śatāvarīghṛtaṃ lihyāt saśarkaraṃ vā navanītam picchilasvarasasādhitaṃ vā sarpiḥ lākṣāpippalīśṛṅgaverakaṭukendrayavadārvītvagbhirghṛtaṃ siddhaṃ peyāmaṇḍena pītamatīsāraṃ tridoṣamapi vārayati" },
      { type: "verse", number: "26", sanskrit: "यदा पुनर्वायुना विट् बद्धं सशोणितमल्पाल्पं सफेनं कृच्छ्रादुपवेश्यते तदा पूर्वोक्तं पिच्छाबस्तिं दद्यात् मधुरौषधसिद्धेन च सर्पिषानुवासयेत् प्रायेण हि दुर्बलगुदा गुदाश्रयामयिनो भवन्ति विशेषतश्चिरकालातीसारिणः अतिसारातिप्रवृत्तौ स्वस्थानबलवृद्धो वायुः पित्तमनुबलमवाप्य दुर्जयतरो भवति तस्मात्तेषामभीक्ष्णमनुवासनं प्रयुञ्जीत गुददाहे पुनः पटोलमधुकमधूकक्षीरिवृक्षादिकषायेण सघृतशर्कराक्षौद्रेण क्षीरेण वा गुदं तदासन्नांश्च प्रदेशान् सिञ्चेत् शतधौतादिभिर्घृतैश्च पिचूनभ्यङ्गांश्च दद्यात् पटोलादीनामेव च कल्केन सघृतेन प्रदिह्यात् तच्चूर्णौर्धातकीलोध्रमाषचूर्णेन च पायुद्वारमवचूर्णयेत् एवमेव च शूले वातहरतैलप्रदेहैरुपाचरेत् यः पुनरेवमपि पित्तलान्यासेवेत स शीघ्रं गुदवलीषु पक्वासु व्यापद्यते", text: "yadā punarvāyunā viṭ baddhaṃ saśoṇitamalpālpaṃ saphenaṃ kṛcchrādupaveśyate tadā pūrvoktaṃ picchābastiṃ dadyāt madhurauṣadhasiddhena ca sarpiṣānuvāsayet prāyeṇa hi durbalagudā gudāśrayāmayino bhavanti viśeṣataścirakālātīsāriṇaḥ atisārātipravṛttau svasthānabalavṛddho vāyuḥ pittamanubalamavāpya durjayataro bhavati tasmātteṣāmabhīkṣṇamanuvāsanaṃ prayuñjīta gudadāhe punaḥ paṭolamadhukamadhūkakṣīrivṛkṣādikaṣāyeṇa saghṛtaśarkarākṣaudreṇa kṣīreṇa vā gudaṃ tadāsannāṃśca pradeśān siñcet śatadhautādibhirghṛtaiśca picūnabhyaṅgāṃśca dadyāt paṭolādīnāmeva ca kalkena saghṛtena pradihyāt taccūrṇaurdhātakīlodhramāṣacūrṇena ca pāyudvāramavacūrṇayet evameva ca śūle vātaharatailapradehairupācaret yaḥ punarevamapi pittalānyāseveta sa śīghraṃ gudavalīṣu pakvāsu vyāpadyate" },
      { type: "verse", number: "27", sanskrit: "श्लेष्मातीसारं तु प्रागेव नितरामामपाचनार्थं लङ्घनेन साधयेत् अनुबन्धे च पिबेत् कषायं मुस्ताभयाशुण्ठीबिल्वशलाटूनाम् वचाविडङ्गभूतीकधनिकादेवदारूणां वा पाठातिविषाकुष्ठचव्यकटुरोहिणीनां वा चित्रकपिप्पलीद्वयपिप्पलीमूलानां वा सुखाम्बुना वा हिङ्ग्वाद्यमलसकोक्तम् पथ्यासैन्धवशुण्ठीचूर्णं व लिह्याद्वा त्रिकटुचूर्णं क्षौद्रशर्करोपेतम् कपित्थं क्षौद्रेण वा कट्फलं वा पिप्पलीर्वा पूर्ववच्च सर्वं वातपित्तामरक्तसंसर्गमपेक्ष्य यथायथमुपकल्पयेत् सशूलप्रवाहिकस्य च निरामस्य वाते ऽधिके वचाबिल्वपिप्पलीकुष्ठशताह्वाकल्कयुक्तं सलवणं पिच्छाबस्तिमनुवासनं च कोष्णेन बिल्वतैलेन बहुशोवचादिगर्भेण वा तैलेनेति भवति चात्र", text: "śleṣmātīsāraṃ tu prāgeva nitarāmāmapācanārthaṃ laṅghanena sādhayet anubandhe ca pibet kaṣāyaṃ mustābhayāśuṇṭhībilvaśalāṭūnām vacāviḍaṅgabhūtīkadhanikādevadārūṇāṃ vā pāṭhātiviṣākuṣṭhacavyakaṭurohiṇīnāṃ vā citrakapippalīdvayapippalīmūlānāṃ vā sukhāmbunā vā hiṅgvādyamalasakoktam pathyāsaindhavaśuṇṭhīcūrṇaṃ va lihyādvā trikaṭucūrṇaṃ kṣaudraśarkaropetam kapitthaṃ kṣaudreṇa vā kaṭphalaṃ vā pippalīrvā pūrvavacca sarvaṃ vātapittāmaraktasaṃsargamapekṣya yathāyathamupakalpayet saśūlapravāhikasya ca nirāmasya vāte 'dhike vacābilvapippalīkuṣṭhaśatāhvākalkayuktaṃ salavaṇaṃ picchābastimanuvāsanaṃ ca koṣṇena bilvatailena bahuśovacādigarbheṇa vā taileneti bhavati cātra" },
      { type: "verse", number: "28", sanskrit: "स्वस्थाने मारुतो ऽवश्यं वर्धते कफसङ्क्षयात् स वृद्धः सहसा हन्यात्तस्मात्तं त्वरया जयेत्", text: "svasthāne māruto 'vaśyaṃ vardhate kaphasaṅkṣayāt sa vṛddhaḥ sahasā hanyāttasmāttaṃ tvarayā jayet" },
      { type: "verse", number: "29", sanskrit: "भीशोकाभ्यामपि मरुच्छीघ्रं कुप्यत्यतस्तयोः कार्या क्रिया वातहरा हर्षणाश्वासनानि च", text: "bhīśokābhyāmapi marucchīghraṃ kupyatyatastayoḥ kāryā kriyā vātaharā harṣaṇāśvāsanāni ca" },
      { type: "verse", number: "30", sanskrit: "यस्योच्चाराद्विना मूत्रं पवनो वा प्रवर्तते दीप्ताग्नेर्लघुकोष्ठस्य शान्तस्तस्योदरामयः", text: "yasyoccārādvinā mūtraṃ pavano vā pravartate dīptāgnerlaghukoṣṭhasya śāntastasyodarāmayaḥ" },
      { type: "verse", number: "31", sanskrit: "आमस्य पाको मलसङ्ग्रहो ऽनु न सङ्ग्रहे रुग्गुदनाभिजन्मा विलङ्घनैर्ग्राहिभिरीरणघ्नैः क्रमेण तैस्तैर्विधिभिर्विधेयः", text: "āmasya pāko malasaṅgraho 'nu na saṅgrahe ruggudanābhijanmā vilaṅghanairgrāhibhirīraṇaghnaiḥ krameṇa taistairvidhibhirvidheyaḥ" },
      { type: "verse", number: "32", sanskrit: "न रिक्तकोष्ठस्य पुरीषबन्धो न रूक्षकुक्षेः सुहितस्य चाति पित्तास्रतो ऽन्यत्र न चातिशीतैरत्युष्णतीक्ष्णैर्न कदाचिदेव", text: "na riktakoṣṭhasya purīṣabandho na rūkṣakukṣeḥ suhitasya cāti pittāsrato 'nyatra na cātiśītairatyuṣṇatīkṣṇairna kadācideva" },
      { type: "verse", number: "33", sanskrit: "खलरसदाधिका यमकदाडिमसारकृता दधि सगुडं पयो ऽसिततिलाश्च सुजर्जरिताः सलवणमारुतघ्नगणसाधिततैलमलं घृतमपि वा प्रवाहणकृतां विजयेत रुजाम्", text: "khalarasadādhikā yamakadāḍimasārakṛtā dadhi saguḍaṃ payo 'sitatilāśca sujarjaritāḥ salavaṇamārutaghnagaṇasādhitatailamalaṃ ghṛtamapi vā pravāhaṇakṛtāṃ vijayeta rujām" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 12,
    lang: "sa",
    content: [
      { type: "heading", heading: "Панду чикитса — лечение анемии" },
      { type: "text", text: "Глава 12 Чикитса стханы — лечебный раздел о лечение анемии. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो ग्रहणीदोषचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto grahaṇīdoṣacikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "ग्रहणीसमाश्रितं दोषमादावेव यथास्वमजीर्णानुसारतो मात्राशीतीयोक्तविधानेनोपक्रमेत अथातीसारविधिना च आमपाचनार्थं पिबेन्मुस्तातिविषाविश्वभेषजक्वाथम् तच्चूर्णं वा सुखोदकेन तेन वा शुण्ठीम् तद्वद्वचादिवर्गं ससैन्धवम् व्वारुणीमण्डेन वा गुल्मविध्युक्तं त्रिलवणादि चूर्णम्", text: "grahaṇīsamāśritaṃ doṣamādāveva yathāsvamajīrṇānusārato mātrāśītīyoktavidhānenopakrameta athātīsāravidhinā ca āmapācanārthaṃ pibenmustātiviṣāviśvabheṣajakvātham taccūrṇaṃ vā sukhodakena tena vā śuṇṭhīm tadvadvacādivargaṃ sasaindhavam vvāruṇīmaṇḍena vā gulmavidhyuktaṃ trilavaṇādi cūrṇam" },
      { type: "verse", number: "3", sanskrit: "सप्रवाहे वा वर्चसि चूर्णीकृतान् बिडलवणयुक्तान् बिल्वमध्यनागरचित्रकान् दाडिमाम्भसा सकफे वा अतिमात्र आमशूले ऽलसकोक्तं हिङ्ग्वादिमुष्णाम्भसा पिबेत् छर्दिशूलानाहानुग्रन्थिषु तु मरिचाजाजिसौवर्चलाभयाः सपित्तकफे चामे कटुकेन्द्रयवपाठापिप्पलीमूलवचाभयानागराणि क्वथितानि चूर्णितानि वा", text: "sapravāhe vā varcasi cūrṇīkṛtān biḍalavaṇayuktān bilvamadhyanāgaracitrakān dāḍimāmbhasā sakaphe vā atimātra āmaśūle 'lasakoktaṃ hiṅgvādimuṣṇāmbhasā pibet chardiśūlānāhānugranthiṣu tu maricājājisauvarcalābhayāḥ sapittakaphe cāme kaṭukendrayavapāṭhāpippalīmūlavacābhayānāgarāṇi kvathitāni cūrṇitāni vā" },
      { type: "verse", number: "4", sanskrit: "भोजनकाले च पञ्चकोलपरिगृहीतं पटुलघुदीपनीयं पेयादिकमुपकल्पयेत् पेयां वा नागरातिविषाभ्यां तक्रदाडिमवृक्षाम्लाम्लाम् पाने च तक्रमस्त्वार नालमदिरारिष्टानतीसारनिर्दिष्टं चाम्बु यवानीपथ्यामलकमरिचानि त्रिपलिकानि लवणपञ्चकं च पलांशकमेकतश्चूर्णयित्वा कंसे सद्योमथितस्यासुनुयात् ततो व्यक्ताम्लकटुकं जातं पिबेत् एष तक्रारिष्टः परमग्निदीपनो ऽर्शोगुल्मजठरश्वयथुकृमिप्रमेहहरः", text: "bhojanakāle ca pañcakolaparigṛhītaṃ paṭulaghudīpanīyaṃ peyādikamupakalpayet peyāṃ vā nāgarātiviṣābhyāṃ takradāḍimavṛkṣāmlāmlām pāne ca takramastvāra nālamadirāriṣṭānatīsāranirdiṣṭaṃ cāmbu yavānīpathyāmalakamaricāni tripalikāni lavaṇapañcakaṃ ca palāṃśakamekataścūrṇayitvā kaṃse sadyomathitasyāsunuyāt tato vyaktāmlakaṭukaṃ jātaṃ pibet eṣa takrāriṣṭaḥ paramagnidīpano 'rśogulmajaṭharaśvayathukṛmipramehaharaḥ" },
      { type: "verse", number: "5", sanskrit: "अपि च ग्रहणीदोषिणां तक्रं दीपनग्राहि लाघवात् पथ्यं मधुरपाकित्वान्न च पित्तप्रदूषणम्", text: "api ca grahaṇīdoṣiṇāṃ takraṃ dīpanagrāhi lāghavāt pathyaṃ madhurapākitvānna ca pittapradūṣaṇam" },
      { type: "verse", number: "6", sanskrit: "कषायोष्णविकाशित्वाद्भूक्षत्वाच्च कफे हितम् वाते स्वाद्वम्लसान्द्रत्वात् सद्यस्कमविदाहि तत्", text: "kaṣāyoṣṇavikāśitvādbhūkṣatvācca kaphe hitam vāte svādvamlasāndratvāt sadyaskamavidāhi tat" },
      { type: "verse", number: "7", sanskrit: "तस्मात्तक्रप्रयोगा ये जठराणां तथार्शसाम् विहिता ग्रहणीदोषे सर्वशस्तान् प्रयोजयेत्", text: "tasmāttakraprayogā ye jaṭharāṇāṃ tathārśasām vihitā grahaṇīdoṣe sarvaśastān prayojayet" },
      { type: "verse", number: "8", sanskrit: "दाडिमकपित्थवृक्षाम्लाम्लीकानां पृथक् पृथक् कुडवं लवणपञ्चककुडवं त्र्यूषणत्रिपलं शर्करापलाष्टकं चैकध्यं चूर्णितमन्नपाने प्रणीतमजीर्णारुचिश्वासकासप्लीहगुल्मग्रहणीहृत्पाण्डुरोगघ्नम् परिपक्वामं च मारुतग्रहणीरोगिणमग्निसन्धुक्षणार्थं सर्पिः पाययेत् द्विपञ्चमूलपञ्चकोलसरलसुरदारुसुरभिगजपिप्पलीशणबीजयवकोलकुलत्थान्मस्तुनारनालेन वा पाचयेत् तेन पादावशेषेण पञ्चलवणद्विक्षाराम्लबदरयुक्तं सर्पिर्विपक्वमथवा सैन्धवव्योषक्षारद्वयपञ्चमूलाभयारास्नाजाजीग्रन्थिकशठीविडङ्गगर्भमार्द्रकमातुलुङ्गकोलाम्लीकादाडिमस्वरसशुष्कमूलकक्वाथमस्तुतक्रशुक्तप्रसन्नासौवीरकतुषोदकारनालोपेतं परमग्निदीपनमग्निघृताख्यम्", text: "dāḍimakapitthavṛkṣāmlāmlīkānāṃ pṛthak pṛthak kuḍavaṃ lavaṇapañcakakuḍavaṃ tryūṣaṇatripalaṃ śarkarāpalāṣṭakaṃ caikadhyaṃ cūrṇitamannapāne praṇītamajīrṇāruciśvāsakāsaplīhagulmagrahaṇīhṛtpāṇḍurogaghnam paripakvāmaṃ ca mārutagrahaṇīrogiṇamagnisandhukṣaṇārthaṃ sarpiḥ pāyayet dvipañcamūlapañcakolasaralasuradārusurabhigajapippalīśaṇabījayavakolakulatthānmastunāranālena vā pācayet tena pādāvaśeṣeṇa pañcalavaṇadvikṣārāmlabadarayuktaṃ sarpirvipakvamathavā saindhavavyoṣakṣāradvayapañcamūlābhayārāsnājājīgranthikaśaṭhīviḍaṅgagarbhamārdrakamātuluṅgakolāmlīkādāḍimasvarasaśuṣkamūlakakvāthamastutakraśuktaprasannāsauvīrakatuṣodakāranālopetaṃ paramagnidīpanamagnighṛtākhyam" },
      { type: "verse", number: "9", sanskrit: "अथवा चव्यचित्रकपाठातेजोवतीपिप्पलीमूलानि कुडवोन्मितानि मुस्तद्विकुडवमास्फोतजातीनिम्बसप्तच्छदाश्वमारककर्कोटकपटोलपल्लवानां च मुष्टिं मुष्टिमन्तर्नखमुदकद्रोणे पक्त्वा पादावशेषमवतारयेत् अर्धपलोन्मितां चात्र कल्कितां दद्यादतिविषां कृष्णासारिवाभद्राश्च द्विपलांशं सैन्धवं बिडं यवक्षारं च मागधिकायाश्चतुष्पलं पात्रं च घृतस्य एतदगस्त्यनिर्मितमलमनलजननम्", text: "athavā cavyacitrakapāṭhātejovatīpippalīmūlāni kuḍavonmitāni mustadvikuḍavamāsphotajātīnimbasaptacchadāśvamārakakarkoṭakapaṭolapallavānāṃ ca muṣṭiṃ muṣṭimantarnakhamudakadroṇe paktvā pādāvaśeṣamavatārayet ardhapalonmitāṃ cātra kalkitāṃ dadyādativiṣāṃ kṛṣṇāsārivābhadrāśca dvipalāṃśaṃ saindhavaṃ biḍaṃ yavakṣāraṃ ca māgadhikāyāścatuṣpalaṃ pātraṃ ca ghṛtasya etadagastyanirmitamalamanalajananam" },
      { type: "verse", number: "10", sanskrit: "उद्दीपिते तु किञ्चिदनले विबद्धमलमास्थापयेत् ततो जिते मातरिश्वनि स्रस्तदोषमेरण्डतैलेन तिल्वकसर्पिषा वा क्षारवता मिश्रकस्नेहेन वा विरेचयेत् कृतसंसर्गक्रमं च बद्धवर्चसमनुवासयेद्वातहरदीपनीयाम्लद्रव्यसिद्धेन तैलेन ततः पुनरपि लघ्वन्नभोजनः सर्पिरेव यथाग्निबलमल्पशो ऽवचारयेत् अग्निघृतं च छर्दिविबन्धशूलश्वासकासिनः सबीजपूरकरसम् अभ्यङ्गार्थं च तैलमग्निघृतौषधैः साधयेत् अनिलकफसंसर्गे तु चूर्णमेषामौषधानामुष्णोदकेन पिबेत्", text: "uddīpite tu kiñcidanale vibaddhamalamāsthāpayet tato jite mātariśvani srastadoṣameraṇḍatailena tilvakasarpiṣā vā kṣāravatā miśrakasnehena vā virecayet kṛtasaṃsargakramaṃ ca baddhavarcasamanuvāsayedvātaharadīpanīyāmladravyasiddhena tailena tataḥ punarapi laghvannabhojanaḥ sarpireva yathāgnibalamalpaśo 'vacārayet agnighṛtaṃ ca chardivibandhaśūlaśvāsakāsinaḥ sabījapūrakarasam abhyaṅgārthaṃ ca tailamagnighṛtauṣadhaiḥ sādhayet anilakaphasaṃsarge tu cūrṇameṣāmauṣadhānāmuṣṇodakena pibet" },
      { type: "verse", number: "11", sanskrit: "पित्तदुष्टायां तु ग्रहण्यां स्वस्थानगतमुत्क्लिष्टं द्रवमनलीनर्वापणं पित्तमास्थापनेन वमनेन वा निर्हरेत् तिक्तलघुद्रव्यैश्च कृतसंसर्जनस्य दोषशेषशमनार्थं मधुनावलेह्यमुष्णाम्बुना वा पातुं प्रणयेत् मूर्वाकिरातततिक्तपर्पटकवचाचन्दनमुस्तत्रिकटुकत्रायमाणायवानीकलिङ्गत्वक्फलकटुरोहिणीदेवदारुदार्वीत्वक् पद्मकोशीरारिष्टपटोलपत्रातिविषासौराष्ट्रीत्वगेलामधु शिग्रुबीजचूर्णम् अयं हि ग्रहणीदोषशूलातिसारपाण्डुहृद्रोगगुल्मज्वरप्रमेहकामलामुखरोगारोचकनिबर्हणः", text: "pittaduṣṭāyāṃ tu grahaṇyāṃ svasthānagatamutkliṣṭaṃ dravamanalīnarvāpaṇaṃ pittamāsthāpanena vamanena vā nirharet tiktalaghudravyaiśca kṛtasaṃsarjanasya doṣaśeṣaśamanārthaṃ madhunāvalehyamuṣṇāmbunā vā pātuṃ praṇayet mūrvākirātatatiktaparpaṭakavacācandanamustatrikaṭukatrāyamāṇāyavānīkaliṅgatvakphalakaṭurohiṇīdevadārudārvītvak padmakośīrāriṣṭapaṭolapatrātiviṣāsaurāṣṭrītvagelāmadhu śigrubījacūrṇam ayaṃ hi grahaṇīdoṣaśūlātisārapāṇḍuhṛdrogagulmajvarapramehakāmalāmukharogārocakanibarhaṇaḥ" },
      { type: "verse", number: "12", sanskrit: "भूनिम्बत्रिकटुककटुकामुस्तेन्द्रयवाः समाश्चित्रकभागौ द्वौ कुटजत्वग्भागाश्च षोडश सर्वमेकत्र चूर्णितं सगुडशीतोदकं पीतं समानं पूर्वेण नागररसाञ्जनातिविषाधातकीघनपाठाकलिङ्गत्वग्बीजबिल्वकटुकाः सक्षौद्रास्तण्डुलाम्बुपीताः पित्तग्रहणीविकारं रक्तातिसारमर्शांसि सप्रवाहिकं गुदशूलं च व्यपोहन्ति ततश्चैवं शमितपित्तोद्रेकस्याग्नेः स्थिरीकरणाय सर्पिः पूर्वोक्तमूर्वादिक्वाथेन सारिवास्फोतसप्तपर्णाटरूषकेन्द्रयववीराभूनिम्बधान्यन्यग्रोधाश्वत्थोदुम्बरप्लक्षोपकुल्यानीलोत्पलगर्भसिद्धं पानाय प्रयुञ्जीत कुष्ठोक्तं वा तिक्तकम्", text: "bhūnimbatrikaṭukakaṭukāmustendrayavāḥ samāścitrakabhāgau dvau kuṭajatvagbhāgāśca ṣoḍaśa sarvamekatra cūrṇitaṃ saguḍaśītodakaṃ pītaṃ samānaṃ pūrveṇa nāgararasāñjanātiviṣādhātakīghanapāṭhākaliṅgatvagbījabilvakaṭukāḥ sakṣaudrāstaṇḍulāmbupītāḥ pittagrahaṇīvikāraṃ raktātisāramarśāṃsi sapravāhikaṃ gudaśūlaṃ ca vyapohanti tataścaivaṃ śamitapittodrekasyāgneḥ sthirīkaraṇāya sarpiḥ pūrvoktamūrvādikvāthena sārivāsphotasaptaparṇāṭarūṣakendrayavavīrābhūnimbadhānyanyagrodhāśvatthodumbaraplakṣopakulyānīlotpalagarbhasiddhaṃ pānāya prayuñjīta kuṣṭhoktaṃ vā tiktakam" },
      { type: "verse", number: "13", sanskrit: "श्लेष्मदुष्टायां पुनर्ग्रहण्यां मागधिकंसिद्धार्थकल्कतीक्ष्णेन मदनफलकषायेण पुनःपुनर्वामयेत् अब्धातुर्हि प्रवृद्धस्तेजो निर्वापयति ततः कृतपेयादिक्रमस्य लवणक्षाराम्लकटुकोत्कटैर्यथोक्तैरन्नपानौषधैरनलमुत्तेजयेत् मञ्जिष्ठाचित्रकारुष्करकृमिघ्नमधूकपुष्पाणि क्रमाद् द्विकुडवार्धाढकाढकार्धद्रोणद्रोणांशान्यपां द्रोणत्रये क्वाथयेत् द्रोणशेषश्च पूतशीतः स निर्यूहो मधुद्विप्रस्थवांश्चन्दनोशीरसूक्ष्मैलागरुरूषितं जतुसृतं घृतकुम्भमध्युषितो मासमासवः सर्वदोषघ्नो ऽग्निजननो बृंहणः शोषकुष्ठकिलासप्रमेहानाहगुल्मपाण्डुहृद्रोगजिच्च", text: "śleṣmaduṣṭāyāṃ punargrahaṇyāṃ māgadhikaṃsiddhārthakalkatīkṣṇena madanaphalakaṣāyeṇa punaḥpunarvāmayet abdhāturhi pravṛddhastejo nirvāpayati tataḥ kṛtapeyādikramasya lavaṇakṣārāmlakaṭukotkaṭairyathoktairannapānauṣadhairanalamuttejayet mañjiṣṭhācitrakāruṣkarakṛmighnamadhūkapuṣpāṇi kramād dvikuḍavārdhāḍhakāḍhakārdhadroṇadroṇāṃśānyapāṃ droṇatraye kvāthayet droṇaśeṣaśca pūtaśītaḥ sa niryūho madhudviprasthavāṃścandanośīrasūkṣmailāgarurūṣitaṃ jatusṛtaṃ ghṛtakumbhamadhyuṣito māsamāsavaḥ sarvadoṣaghno 'gnijanano bṛṃhaṇaḥ śoṣakuṣṭhakilāsapramehānāhagulmapāṇḍuhṛdrogajicca" },
      { type: "verse", number: "14", sanskrit: "मधूकपुष्पाणां स्वरसो ऽर्धावशेषक्वथितः क्षौद्रपादयुक्तः सर्वथा समानः पूर्वेण अनेन द्राक्षेक्षुकाश्मर्यफलस्वरसासवा व्याख्याताः", text: "madhūkapuṣpāṇāṃ svaraso 'rdhāvaśeṣakvathitaḥ kṣaudrapādayuktaḥ sarvathā samānaḥ pūrveṇa anena drākṣekṣukāśmaryaphalasvarasāsavā vyākhyātāḥ" },
      { type: "verse", number: "15", sanskrit: "दशमूलवीरारजनीत्रिफलाजीवकर्षभकाणां पृथक् पृथक् पञ्चपलान् भागानपां वहे पक्त्वा पादशेषे रसे शीतीभूते गुडतुलाद्वयं दद्यादर्धकुडवं च माक्षिकात्तत्प्रमाणांश्च चूर्णितान् मुस्तप्रियङ्गुमञ्जिष्ठामधुकविडङ्गप्लवशाबरलोध्रान् एषो ऽर्धमासस्थितो मूलासवो ऽयं समानः पूर्वेण महावृक्षकण्डचतुष्पलं द्विगुणार्ककाण्डं लवणत्रयत्रिपलं पक्ववार्ताककुडवं चित्रकमूलपलद्वयं चान्तर्धूमं दग्ध्वा वार्ताकरसेन गुटिकाः कुर्यात् ता भोजनोत्तरं भक्षिता ग्रहणी दुर्नामविषूचिकालसककासश्वासपीनसप्लीहपाण्डुश्वयथुमेहारोचकगुल्महराः", text: "daśamūlavīrārajanītriphalājīvakarṣabhakāṇāṃ pṛthak pṛthak pañcapalān bhāgānapāṃ vahe paktvā pādaśeṣe rase śītībhūte guḍatulādvayaṃ dadyādardhakuḍavaṃ ca mākṣikāttatpramāṇāṃśca cūrṇitān mustapriyaṅgumañjiṣṭhāmadhukaviḍaṅgaplavaśābaralodhrān eṣo 'rdhamāsasthito mūlāsavo 'yaṃ samānaḥ pūrveṇa mahāvṛkṣakaṇḍacatuṣpalaṃ dviguṇārkakāṇḍaṃ lavaṇatrayatripalaṃ pakvavārtākakuḍavaṃ citrakamūlapaladvayaṃ cāntardhūmaṃ dagdhvā vārtākarasena guṭikāḥ kuryāt tā bhojanottaraṃ bhakṣitā grahaṇī durnāmaviṣūcikālasakakāsaśvāsapīnasaplīhapāṇḍuśvayathumehārocakagulmaharāḥ" },
      { type: "verse", number: "16", sanskrit: "दशमूलार्कमूलदन्तीत्रिवृच्चित्रकास्फोतपाठारास्नास्नुहीकाण्डानां पृथग्दशपलान् भागान् कपालोदरे दग्ध्वा क्षारमुदकद्रोणैश्चतुर्भिः क्वाथयेत् पादावशेषं च पूतं पुनःपादावशेषमेव क्वथितावतारितं गुडपलशतोन्मिश्रमधिश्रयेत् घनीभवति च तस्मिन् सुश्लक्ष्णरजसां वृश्चिकालीद्वययावशूकानां त्रिंशत् पलान्यावपेत् त्रिंशदेव वचाभयाव्योषचित्रकाणाम् द्विपलं च पृथक् पृथक् हिङ्ग्वम्लवेतसयोः ततो ऽक्षमात्रा गुटिकाः कृत्वा यथाबलमुपयुक्ताः समानाः पूर्वाभिरधिका वा अर्शोविहितांश्च क्षारतक्रारिष्टान् घृतान्यन्नपानं च सेवेत षट्पलं भल्लातकघृतं धान्वतरं च सन्निपाते तु पञ्च कर्माणि कुर्याद्यथावस्थं वा ग्रहणीचिकित्सितमिति भवति चात्र", text: "daśamūlārkamūladantītrivṛccitrakāsphotapāṭhārāsnāsnuhīkāṇḍānāṃ pṛthagdaśapalān bhāgān kapālodare dagdhvā kṣāramudakadroṇaiścaturbhiḥ kvāthayet pādāvaśeṣaṃ ca pūtaṃ punaḥpādāvaśeṣameva kvathitāvatāritaṃ guḍapalaśatonmiśramadhiśrayet ghanībhavati ca tasmin suślakṣṇarajasāṃ vṛścikālīdvayayāvaśūkānāṃ triṃśat palānyāvapet triṃśadeva vacābhayāvyoṣacitrakāṇām dvipalaṃ ca pṛthak pṛthak hiṅgvamlavetasayoḥ tato 'kṣamātrā guṭikāḥ kṛtvā yathābalamupayuktāḥ samānāḥ pūrvābhiradhikā vā arśovihitāṃśca kṣāratakrāriṣṭān ghṛtānyannapānaṃ ca seveta ṣaṭpalaṃ bhallātakaghṛtaṃ dhānvataraṃ ca sannipāte tu pañca karmāṇi kuryādyathāvasthaṃ vā grahaṇīcikitsitamiti bhavati cātra" },
      { type: "verse", number: "17", sanskrit: "प्रसेके श्लैष्मिके ऽल्पाग्नेर्दीपनं रूक्षतिक्तकम् योज्यं कृशस्य व्यत्यासात् स्निग्धरूक्षं कफोदये", text: "praseke ślaiṣmike 'lpāgnerdīpanaṃ rūkṣatiktakam yojyaṃ kṛśasya vyatyāsāt snigdharūkṣaṃ kaphodaye" },
      { type: "verse", number: "18", sanskrit: "क्षीणक्षामशरीरस्य दीपनं स्नेहसंयुतम् दीपनं बहुपित्तस्य तिक्तं मधुरकैर्युतम्", text: "kṣīṇakṣāmaśarīrasya dīpanaṃ snehasaṃyutam dīpanaṃ bahupittasya tiktaṃ madhurakairyutam" },
      { type: "verse", number: "19", sanskrit: "स्नेहो ऽम्ललवणैर्युक्तो बहुवातस्य शस्यते स्नेहमेव परं विद्याद्दुर्बलानलदीपनम्", text: "sneho 'mlalavaṇairyukto bahuvātasya śasyate snehameva paraṃ vidyāddurbalānaladīpanam" },
      { type: "verse", number: "20", sanskrit: "नालं स्नेहसमिद्धस्य शमायान्नं सुगुर्वपि मलमामं कफे क्षीणे मन्दाग्निर्यो ऽतिसार्यते", text: "nālaṃ snehasamiddhasya śamāyānnaṃ sugurvapi malamāmaṃ kaphe kṣīṇe mandāgniryo 'tisāryate" },
      { type: "verse", number: "21", sanskrit: "स पिबेत् सर्पिषो मात्रां दीपनीयौषधैर्युताम् प्रसन्नो मार्गमापन्नः स्वं समानो ऽनिलस्तया अग्नेः समीपचारित्वादाशु प्रकुरुते बलम्", text: "sa pibet sarpiṣo mātrāṃ dīpanīyauṣadhairyutām prasanno mārgamāpannaḥ svaṃ samāno 'nilastayā agneḥ samīpacāritvādāśu prakurute balam" },
      { type: "verse", number: "22", sanskrit: "पुरीषं यस्तु कृच्छ्रेण कठिनत्वाद्विमुञ्चति स घृतं लवणैर्युक्तं नरो ऽन्नावग्रहं पिबेत्", text: "purīṣaṃ yastu kṛcchreṇa kaṭhinatvādvimuñcati sa ghṛtaṃ lavaṇairyuktaṃ naro 'nnāvagrahaṃ pibet" },
      { type: "verse", number: "23", sanskrit: "रौक्ष्यान्मन्दे ऽनले सर्पिस्तलं वा दीपनैः पिबेत् क्षारचूर्णासवारिष्टान् मन्दे स्नेहातिपानतः", text: "raukṣyānmande 'nale sarpistalaṃ vā dīpanaiḥ pibet kṣāracūrṇāsavāriṣṭān mande snehātipānataḥ" },
      { type: "verse", number: "24", sanskrit: "उदावर्तात्तु योक्तव्या निरूहस्नेहबस्तयः दोषातिवृध्या मन्दे ऽग्नौ संशुद्धो ऽन्नविधिं चरेत्", text: "udāvartāttu yoktavyā nirūhasnehabastayaḥ doṣātivṛdhyā mande 'gnau saṃśuddho 'nnavidhiṃ caret" },
      { type: "verse", number: "25", sanskrit: "व्याधिमुक्तस्य मन्दे ऽग्नौ सर्पिरेव तु दीपनम् अध्वोपवासक्षामत्वैर्यवाग्वा पाययेत् घृतम् अन्नावपीडितं बल्यं दीपनं बृंहणं च तत्", text: "vyādhimuktasya mande 'gnau sarpireva tu dīpanam adhvopavāsakṣāmatvairyavāgvā pāyayet ghṛtam annāvapīḍitaṃ balyaṃ dīpanaṃ bṛṃhaṇaṃ ca tat" },
      { type: "verse", number: "26", sanskrit: "दीर्घकालप्रसङ्गात्तु क्षामक्षीणकृशान् नरान् प्रसहानां रसैः साम्लैर्भोजयेत् पिशिताशिनाम्", text: "dīrghakālaprasaṅgāttu kṣāmakṣīṇakṛśān narān prasahānāṃ rasaiḥ sāmlairbhojayet piśitāśinām" },
      { type: "verse", number: "27", sanskrit: "लघूष्णकटुशोधित्वैर्दीपयन्त्याशु ते ऽनलम् मांसोपचितमांसत्वात् परं च बलवर्धनाः", text: "laghūṣṇakaṭuśodhitvairdīpayantyāśu te 'nalam māṃsopacitamāṃsatvāt paraṃ ca balavardhanāḥ" },
      { type: "verse", number: "28", sanskrit: "स्नेहासवसुरारिष्टचूर्णक्वाथहिताशनैः सम्यक् प्रयुक्तैर्देहस्य बलमग्नेश्च वर्धते", text: "snehāsavasurāriṣṭacūrṇakvāthahitāśanaiḥ samyak prayuktairdehasya balamagneśca vardhate" },
      { type: "verse", number: "29", sanskrit: "दीप्तो यथैव स्थास्नुश्च बाह्यो ऽग्निः सारदारुभिः सस्नेहैर्जायते तद्वदाहारैः कोष्ठगो ऽनलः", text: "dīpto yathaiva sthāsnuśca bāhyo 'gniḥ sāradārubhiḥ sasnehairjāyate tadvadāhāraiḥ koṣṭhago 'nalaḥ" },
      { type: "verse", number: "30", sanskrit: "नाभोजनेन कायाग्निर्दीप्यते नातिभोजनात् यथा निरिन्धनो वह्निरल्पो वातीन्धनावृतः", text: "nābhojanena kāyāgnirdīpyate nātibhojanāt yathā nirindhano vahniralpo vātīndhanāvṛtaḥ" },
      { type: "verse", number: "31", sanskrit: "यदा क्षीणे कफे पित्तं स्वे स्थाने पवनानुगम् प्रवृद्धं वर्धयत्यग्निं तदासौ सानिलो ऽनलः", text: "yadā kṣīṇe kaphe pittaṃ sve sthāne pavanānugam pravṛddhaṃ vardhayatyagniṃ tadāsau sānilo 'nalaḥ" },
      { type: "verse", number: "32", sanskrit: "पक्त्वान्नमाशु धातूंश्च सर्वानोजश्च सङ्क्षिपन् मारयेत् स्यात् स ना स्वस्थो भुक्ते जीर्णे तु ताम्यति तृट्कासदाहमूर्च्छाद्या व्याधयो ऽत्यग्निसम्भवाः", text: "paktvānnamāśu dhātūṃśca sarvānojaśca saṅkṣipan mārayet syāt sa nā svastho bhukte jīrṇe tu tāmyati tṛṭkāsadāhamūrcchādyā vyādhayo 'tyagnisambhavāḥ" },
      { type: "verse", number: "33", sanskrit: "तमत्यग्निं गुरुस्निग्धमन्दसान्द्रहिमस्थिरैः अन्नपानैर्नयेच्छान्तिं दीप्तमग्निमिवाम्बुभिः", text: "tamatyagniṃ gurusnigdhamandasāndrahimasthiraiḥ annapānairnayecchāntiṃ dīptamagnimivāmbubhiḥ" },
      { type: "verse", number: "34", sanskrit: "मुहुर्मुहुरजीणापि भोज्यान्यस्योपहारयेत् निरिन्धनो ऽन्तरं लब्ध्वा यथैनं न विपादयेत्", text: "muhurmuhurajīṇāpi bhojyānyasyopahārayet nirindhano 'ntaraṃ labdhvā yathainaṃ na vipādayet" },
      { type: "verse", number: "35", sanskrit: "कृसरां पायसं स्निग्धं पैष्टिकं गुडवैकृतम् अश्नीयादौदकानूपपिशितानि भृतानि च", text: "kṛsarāṃ pāyasaṃ snigdhaṃ paiṣṭikaṃ guḍavaikṛtam aśnīyādaudakānūpapiśitāni bhṛtāni ca" },
      { type: "verse", number: "36", sanskrit: "मत्स्यान् विशेषतः श्लक्ष्णान् स्थिरतोयचराश्च ये आविकं सुभृतं मांसमद्यादत्यग्निवारणम्", text: "matsyān viśeṣataḥ ślakṣṇān sthiratoyacarāśca ye āvikaṃ subhṛtaṃ māṃsamadyādatyagnivāraṇam" },
      { type: "verse", number: "37", sanskrit: "पयः सहमधूच्छिष्टं घृतं वा तृषितः पिबेत् गोधूमचूर्णं पयसा बहुसर्पिःप्लुतं पिबेत्", text: "payaḥ sahamadhūcchiṣṭaṃ ghṛtaṃ vā tṛṣitaḥ pibet godhūmacūrṇaṃ payasā bahusarpiḥplutaṃ pibet" },
      { type: "verse", number: "38", sanskrit: "आनूपरसयुक्तान् वा स्नेहांस्तैलविवर्जितान् श्यामात्रिवृद्विपक्वं वा पयो दद्याद्विरेचनम्", text: "ānūparasayuktān vā snehāṃstailavivarjitān śyāmātrivṛdvipakvaṃ vā payo dadyādvirecanam" },
      { type: "verse", number: "39", sanskrit: "असकृत् पित्तहरणं पयसा प्रतिभोजनम् यत्किञ्चिद्गुरु मेध्यं च श्लेष्मकारि च भोजनम् सर्वं तदत्यग्निहितं भुक्त्वा च स्वपनं दिवा", text: "asakṛt pittaharaṇaṃ payasā pratibhojanam yatkiñcidguru medhyaṃ ca śleṣmakāri ca bhojanam sarvaṃ tadatyagnihitaṃ bhuktvā ca svapanaṃ divā" },
      { type: "verse", number: "40", sanskrit: "आहारमग्निः पचति दोषानाहारवर्जितः धातून् क्षीणेषु दोषेषु जीवितं धातुसङ्क्षये", text: "āhāramagniḥ pacati doṣānāhāravarjitaḥ dhātūn kṣīṇeṣu doṣeṣu jīvitaṃ dhātusaṅkṣaye" },
      { type: "verse", number: "41", sanskrit: "अग्निमूलं बलं पुंसां बलमूलं हि जीवितम् एष सारश्चिकित्साया यदग्नेः परिरक्षणम्", text: "agnimūlaṃ balaṃ puṃsāṃ balamūlaṃ hi jīvitam eṣa sāraścikitsāyā yadagneḥ parirakṣaṇam" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 13,
    lang: "sa",
    content: [
      { type: "heading", heading: "Шваса чикитса — лечение одышки" },
      { type: "text", text: "Глава 13 Чикитса стханы — лечебный раздел о лечение одышки. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो मूत्राघातचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto mūtrāghātacikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "वातान्मूत्रकृच्छ्रे वातहरतैलाभ्यक्तगात्रस्याधोनाभेः सर्वमङ्गं पिण्डेन सेकावगाहैश्च वातघ्नैः कुम्भीस्वेदेन च स्वेदयेत्", text: "vātānmūtrakṛcchre vātaharatailābhyaktagātrasyādhonābheḥ sarvamaṅgaṃ piṇḍena sekāvagāhaiśca vātaghnaiḥ kumbhīsvedena ca svedayet" },
      { type: "verse", number: "3", sanskrit: "दशमूलबलैरण्डमूलपुनर्नवाशतावरीवृश्चीवपत्तूरपाषाणभेदककोलकुलत्थयवक्वाथेन तत्कल्केन च तैलं सर्पिः सूरकर्क्षवसालवणपञ्चकोपेतं सिद्धं पानाय दद्यात् एतान्येव चौषधान्यन्नपाने पिण्डोपनाहस्वेदयोश्च तैलफलस्नेहाम्लयुक्तानि कल्पयेत् प्रसन्नां च सौवर्चलाढ्यां पिबेत्", text: "daśamūlabalairaṇḍamūlapunarnavāśatāvarīvṛścīvapattūrapāṣāṇabhedakakolakulatthayavakvāthena tatkalkena ca tailaṃ sarpiḥ sūrakarkṣavasālavaṇapañcakopetaṃ siddhaṃ pānāya dadyāt etānyeva cauṣadhānyannapāne piṇḍopanāhasvedayośca tailaphalasnehāmlayuktāni kalpayet prasannāṃ ca sauvarcalāḍhyāṃ pibet" },
      { type: "verse", number: "4", sanskrit: "पित्तजे शीतसेकावगाहप्रदेहान् प्रयुञ्जीत तृणपञ्चमूलश्वदंष्ट्राभीरुविदारीकशेरुकक्वाथं शीतं समधु शर्करं पिबेत् तद्वच्च काण्डेक्षुरकमूलम् कमलोत्पलविदारीशृङ्गाटकानि द्राक्षारसेन वा त्रपुसकुसुम्भोर्वारुबीजवृषककुङ्कुमकल्कं सर्वमूत्राघातघ्नम् मधुकदार्व्युर्वारुबीजानि वा तण्डुलधावनेन समाक्षिकां वा दार्वीमामलकरसेन मृद्वीकाकल्कं वा पर्युषिताम्भसा", text: "pittaje śītasekāvagāhapradehān prayuñjīta tṛṇapañcamūlaśvadaṃṣṭrābhīruvidārīkaśerukakvāthaṃ śītaṃ samadhu śarkaraṃ pibet tadvacca kāṇḍekṣurakamūlam kamalotpalavidārīśṛṅgāṭakāni drākṣārasena vā trapusakusumbhorvārubījavṛṣakakuṅkumakalkaṃ sarvamūtrāghātaghnam madhukadārvyurvārubījāni vā taṇḍuladhāvanena samākṣikāṃ vā dārvīmāmalakarasena mṛdvīkākalkaṃ vā paryuṣitāmbhasā" },
      { type: "verse", number: "5", sanskrit: "कफजे यथास्वं स्वेदो वमनं कटुतीक्ष्णोष्णक्षारमन्नपानं यवान्नं तक्रं च पिबेच्च मद्येन सूक्ष्मैलामामलकरसेन वा मधुयुतां वा कदलीरसेन कैडर्यकरसेन वा शितिवारकबीजं वा तक्रेण प्रवालचूर्णं वा तण्डुलाम्बुना धवकुटजकरञ्जामृताकेबुकैलारग्वधसप्तच्छदक्वाथं वा शीतं सक्षौद्रम् तत्सिद्धां वा यवागूम् कण्टकारिकास्वरसं वा समाक्षिकम् व्योषैलागोक्षुरकसारसास्थीनि वा मधुमूत्रयुक्तानि पाटलीक्षारं वा बहुकृत्वः परिस्रुतं तैलयुक्तम् तिलपाटलीपारिभद्रयावशूकक्षारोदकानुविद्धां वा त्वगेलोषकचूर्णयुक्तां प्रसन्नाम् तिलादीनां वा पृथक् क्षारं गुडोपदंशमश्नीयात् तीक्ष्णोष्णद्रव्यसिद्धं च तैलं पानाभ्यङ्गार्थे", text: "kaphaje yathāsvaṃ svedo vamanaṃ kaṭutīkṣṇoṣṇakṣāramannapānaṃ yavānnaṃ takraṃ ca pibecca madyena sūkṣmailāmāmalakarasena vā madhuyutāṃ vā kadalīrasena kaiḍaryakarasena vā śitivārakabījaṃ vā takreṇa pravālacūrṇaṃ vā taṇḍulāmbunā dhavakuṭajakarañjāmṛtākebukailāragvadhasaptacchadakvāthaṃ vā śītaṃ sakṣaudram tatsiddhāṃ vā yavāgūm kaṇṭakārikāsvarasaṃ vā samākṣikam vyoṣailāgokṣurakasārasāsthīni vā madhumūtrayuktāni pāṭalīkṣāraṃ vā bahukṛtvaḥ parisrutaṃ tailayuktam tilapāṭalīpāribhadrayāvaśūkakṣārodakānuviddhāṃ vā tvageloṣakacūrṇayuktāṃ prasannām tilādīnāṃ vā pṛthak kṣāraṃ guḍopadaṃśamaśnīyāt tīkṣṇoṣṇadravyasiddhaṃ ca tailaṃ pānābhyaṅgārthe" },
      { type: "verse", number: "6", sanskrit: "सन्निपातात्मके वातादीनां स्थानानुपूर्व्या यथासन्नं प्रतिकुर्वीत यथोल्बणं वा सर्वेषु समस्थितेषु वा समसितं यवक्षारं भक्षयेत् अपि च", text: "sannipātātmake vātādīnāṃ sthānānupūrvyā yathāsannaṃ pratikurvīta yatholbaṇaṃ vā sarveṣu samasthiteṣu vā samasitaṃ yavakṣāraṃ bhakṣayet api ca" },
      { type: "verse", number: "7", sanskrit: "एलाश्मभेदकशिलाजतुपिप्पलीनां चूर्णानि तण्डुलजलालुलितानि पित्वा तद्वद्गुडेन सहितान्युपयुज्य मासमासन्नमृत्युरपि जीवति मूत्रकृच्छ्री", text: "elāśmabhedakaśilājatupippalīnāṃ cūrṇāni taṇḍulajalālulitāni pitvā tadvadguḍena sahitānyupayujya māsamāsannamṛtyurapi jīvati mūtrakṛcchrī" },
      { type: "verse", number: "8", sanskrit: "एलोपकुल्यामधुकाश्मभेदकौन्तीश्वदंष्ट्रावृषकोरुपूगैः क्वाथं पिबेच्छर्करयावगाढं कृच्छ्रे सदाहे सरुजे बिबन्धे", text: "elopakulyāmadhukāśmabhedakauntīśvadaṃṣṭrāvṛṣakorupūgaiḥ kvāthaṃ pibeccharkarayāvagāḍhaṃ kṛcchre sadāhe saruje bibandhe" },
      { type: "verse", number: "9", sanskrit: "हरीतकीगोक्षुरराजवृक्षपाषाणभिद्धन्वयवासकानाम् क्वाथं पिबेदश्मजतुप्रधानं सर्शकरे साश्मरिमूत्रकृच्छ्रे", text: "harītakīgokṣurarājavṛkṣapāṣāṇabhiddhanvayavāsakānām kvāthaṃ pibedaśmajatupradhānaṃ sarśakare sāśmarimūtrakṛcchre" },
      { type: "verse", number: "10", sanskrit: "अश्मर्यामचिरोत्थितायां वातबस्त्यादिषु च यथादोषमिदमेवाचरेत्", text: "aśmaryāmacirotthitāyāṃ vātabastyādiṣu ca yathādoṣamidamevācaret" },
      { type: "verse", number: "11", sanskrit: "पाषाणभेदकवसुकवसिराश्मन्तकशतावरीश्वदंष्ट्राबृहतीद्वयकपोतवङ्काबलातिबलाकच्छुरोशीरगुन्धुवृक्षादनीभल्लूकवरणयवकोलकुलत्थशाकफलकतकफलक्वाथे सर्पिरूषकादिप्रतीवापं विपाच्य पीतमाशु वाताश्मरीं भिनत्ति एभिरेव च द्रव्यैः कषायक्षारान्नपानानि कल्पयेत्", text: "pāṣāṇabhedakavasukavasirāśmantakaśatāvarīśvadaṃṣṭrābṛhatīdvayakapotavaṅkābalātibalākacchurośīragundhuvṛkṣādanībhallūkavaraṇayavakolakulatthaśākaphalakatakaphalakvāthe sarpirūṣakādipratīvāpaṃ vipācya pītamāśu vātāśmarīṃ bhinatti ebhireva ca dravyaiḥ kaṣāyakṣārānnapānāni kalpayet" },
      { type: "verse", number: "12", sanskrit: "सिंहीव्याघ्नीगोक्षुरकेक्षुरकोरुबूकमूलकल्को ऽमधुरेण दध्ना पीतः सप्गाहादश्मरीं भिनत्ति शिग्रुमूलकल्केन दधिलवणयमकसिद्धो यूषः", text: "siṃhīvyāghnīgokṣurakekṣurakorubūkamūlakalko 'madhureṇa dadhnā pītaḥ sapgāhādaśmarīṃ bhinatti śigrumūlakalkena dadhilavaṇayamakasiddho yūṣaḥ" },
      { type: "verse", number: "13", sanskrit: "वीरतरादिगुन्द्रेत्कटपत्तूरवाराहीपाठापाटलीशिरीषशालिमूलविदारीद्विपुनर्नवक्वाथे त्रपुसकुसुम्भैर्वारुकर्करुबीजमधुकशिलाजतुप्रतीवापं सर्पिर्विपाच्य पीतमाशु पित्ताश्मरीं भिनत्ति पूर्ववच्च कषायादीनेभिः कल्पयेत्", text: "vīratarādigundretkaṭapattūravārāhīpāṭhāpāṭalīśirīṣaśālimūlavidārīdvipunarnavakvāthe trapusakusumbhairvārukarkarubījamadhukaśilājatupratīvāpaṃ sarpirvipācya pītamāśu pittāśmarīṃ bhinatti pūrvavacca kaṣāyādīnebhiḥ kalpayet" },
      { type: "verse", number: "14", sanskrit: "वरणादिभद्रदार्वादिगुग्गुल्वेलाद्वयकुष्ठमरिचचित्रकमुस्तासुरसाह्वयैः कल्कीकृतैः साधितमूषकादिप्रतीवापं सर्पिः श्लेष्माश्मरीं भिनत्ति इति समानं पूर्वेण", text: "varaṇādibhadradārvādiguggulvelādvayakuṣṭhamaricacitrakamustāsurasāhvayaiḥ kalkīkṛtaiḥ sādhitamūṣakādipratīvāpaṃ sarpiḥ śleṣmāśmarīṃ bhinatti iti samānaṃ pūrveṇa" },
      { type: "verse", number: "15", sanskrit: "मस्तुना बहुशः पाटलीभस्म गालयित्वा भस्म विसर्जयेत् ततस्तन्मस्तु गृहीत्वा कुलत्थैः सह क्वाथयेत् तं क्वाथं गोक्षुरकमूलैलात्रपुसकुरण्टकबीजपाषाणभेदकचूर्णं क्षौद्रेण लीढ्वानुपिबेत् तथा शीघ्रमेवाश्मरी भिद्यते च्यवते च", text: "mastunā bahuśaḥ pāṭalībhasma gālayitvā bhasma visarjayet tatastanmastu gṛhītvā kulatthaiḥ saha kvāthayet taṃ kvāthaṃ gokṣurakamūlailātrapusakuraṇṭakabījapāṣāṇabhedakacūrṇaṃ kṣaudreṇa līḍhvānupibet tathā śīghramevāśmarī bhidyate cyavate ca" },
      { type: "verse", number: "16", sanskrit: "अश्मरीभेषजानां घृताक्तानामन्तर्धूमं दग्धानां क्षारं ग्राम्यपशुशकृत्क्षारं च गोमूत्रेण बहुकृत्वो गालयित्वा तमच्छमग्नौ साधयेत् घनीभवति च तस्मिंस्त्र्यूषणोषकादिचूर्णं दद्याद्दर्वीप्रलेपं चावतारयेत् एष क्षीराशिनः क्षारावलेहो ऽश्मरीं भिनत्ति पातयति च शर्कराम्", text: "aśmarībheṣajānāṃ ghṛtāktānāmantardhūmaṃ dagdhānāṃ kṣāraṃ grāmyapaśuśakṛtkṣāraṃ ca gomūtreṇa bahukṛtvo gālayitvā tamacchamagnau sādhayet ghanībhavati ca tasmiṃstryūṣaṇoṣakādicūrṇaṃ dadyāddarvīpralepaṃ cāvatārayet eṣa kṣīrāśinaḥ kṣārāvaleho 'śmarīṃ bhinatti pātayati ca śarkarām" },
      { type: "verse", number: "17", sanskrit: "तिलकदलीयवापामार्गपलाशक्षारो ऽविमूत्रेण पीतः समानः पूर्वेण केतकपत्रक्वाथेन हिङ्गुक्रौञ्चास्थिक्षारयुक्तः पाटलीकरवीरक्षारश्च क्रौञ्चोष्ट्रगर्दभास्थिश्वदंष्ट्राकदम्बमूलतालपत्रिकाजमोदनागरचूर्णश्च सुरामण्डोष्णोदकान्यतरप्रयुक्तः", text: "tilakadalīyavāpāmārgapalāśakṣāro 'vimūtreṇa pītaḥ samānaḥ pūrveṇa ketakapatrakvāthena hiṅgukrauñcāsthikṣārayuktaḥ pāṭalīkaravīrakṣāraśca krauñcoṣṭragardabhāsthiśvadaṃṣṭrākadambamūlatālapatrikājamodanāgaracūrṇaśca surāmaṇḍoṣṇodakānyataraprayuktaḥ" },
      { type: "verse", number: "18", sanskrit: "पिचुकाङ्कोलशाककतकेन्दीवरफलक्वाथश्च सुखोष्णो गुडयुक्तः नृत्यकुण्डकबीजचूर्णश्च समाक्षिको ऽविक्षीरयुक्तः", text: "picukāṅkolaśākakatakendīvaraphalakvāthaśca sukhoṣṇo guḍayuktaḥ nṛtyakuṇḍakabījacūrṇaśca samākṣiko 'vikṣīrayuktaḥ" },
      { type: "verse", number: "19", sanskrit: "कपोतवङ्कामूलं च सुरया तत्सिद्धं वा पयो ऽश्मरीवेदनार्तः पिबेत् सिद्धं वाभयास्थिभिः पुनर्नवेन वा", text: "kapotavaṅkāmūlaṃ ca surayā tatsiddhaṃ vā payo 'śmarīvedanārtaḥ pibet siddhaṃ vābhayāsthibhiḥ punarnavena vā" },
      { type: "verse", number: "20", sanskrit: "शेषेष्वेवं मूत्राघातेष्वत एव चिकित्सां विभजेत्", text: "śeṣeṣvevaṃ mūtrāghāteṣvata eva cikitsāṃ vibhajet" },
      { type: "verse", number: "21", sanskrit: "द्रस्वपञ्चमूलेन द्विगुणत्रिकण्टकेन साधितं तोयं पयो वा केवलं घृतमिश्रं वा पिबेत् सर्वमूत्राघातघ्नम्", text: "drasvapañcamūlena dviguṇatrikaṇṭakena sādhitaṃ toyaṃ payo vā kevalaṃ ghṛtamiśraṃ vā pibet sarvamūtrāghātaghnam" },
      { type: "verse", number: "22", sanskrit: "गोक्षुरककण्टकारिकाकृतां वा सफाणितां यवागूम् ताम्रचूडरससिद्धां वा वीरतरादिक्वाथेन वा तेन वा तद्भावितं शिलाजतु वाजिरासभान्यतरशकृद्रसं वा दुरालभास्वरसं वा ककुभकषायं वा मूर्वाभयामुस्तदेवदारुमधुककल्कं वा वारुणीक्षीरोष्णोदकान्यतमेन त्रिफलाकल्कं वा ससैन्धवं सुखाम्भसा केवलमेव वा बिभीतक बीजं सुरया विहगपिशितोपदंशं वा निगदमदिरामण्डं मार्द्वीकमासवान् वा विविधान् पिबेत् पीतमद्यश्च शीघ्रवेगेन वाजिना रथेन वा यायात् एवमश्मरी शर्करा चप्रच्यवते सर्वेषु च मूत्राघातेषु विशेषतो ऽश्मरीशर्करासु वीरतरादिः सर्वथा प्रयोज्यः तिल्वकघृतं च विरेकार्थम् बस्तिकर्म चाभीक्ष्णं विशेषेणोत्तरबस्तिः", text: "gokṣurakakaṇṭakārikākṛtāṃ vā saphāṇitāṃ yavāgūm tāmracūḍarasasiddhāṃ vā vīratarādikvāthena vā tena vā tadbhāvitaṃ śilājatu vājirāsabhānyataraśakṛdrasaṃ vā durālabhāsvarasaṃ vā kakubhakaṣāyaṃ vā mūrvābhayāmustadevadārumadhukakalkaṃ vā vāruṇīkṣīroṣṇodakānyatamena triphalākalkaṃ vā sasaindhavaṃ sukhāmbhasā kevalameva vā bibhītaka bījaṃ surayā vihagapiśitopadaṃśaṃ vā nigadamadirāmaṇḍaṃ mārdvīkamāsavān vā vividhān pibet pītamadyaśca śīghravegena vājinā rathena vā yāyāt evamaśmarī śarkarā capracyavate sarveṣu ca mūtrāghāteṣu viśeṣato 'śmarīśarkarāsu vīratarādiḥ sarvathā prayojyaḥ tilvakaghṛtaṃ ca virekārtham bastikarma cābhīkṣṇaṃ viśeṣeṇottarabastiḥ" },
      { type: "verse", number: "23", sanskrit: "तत्र श्यामादिरर्धार्धविहितो गोमूत्रसिद्धो निरूहः बिल्वादिमूलैश्च सुरासौवीरकादिसिद्धैस्तृणपञ्चमूलश्वदंष्ट्राशृतक्षीरवांश्च त्रपुसैर्वारुकशताह्वाबीजकर्षभकयवानीकल्कितः पीतदारुसिद्धं तैलमनुवासनम्", text: "tatra śyāmādirardhārdhavihito gomūtrasiddho nirūhaḥ bilvādimūlaiśca surāsauvīrakādisiddhaistṛṇapañcamūlaśvadaṃṣṭrāśṛtakṣīravāṃśca trapusairvārukaśatāhvābījakarṣabhakayavānīkalkitaḥ pītadārusiddhaṃ tailamanuvāsanam" },
      { type: "verse", number: "24", sanskrit: "शतावरीगोक्षुरकबृहतीद्वयपुनर्नवोशीरमधुकद्विसारिवाश्रेयसीलोध्रतृणपञ्चमूलकषाये क्षीरचतुर्गुणं बलावृक्षकखराह्वोपकुञ्चिकावत्सकत्रपुसोर्वारुबीजशितिवारकमधुकषड्ग्रन्थाशताह्वाश्मभेदमदनहपुषाकल्कगर्भं तैलमुत्तरबस्तिः तद्विशुद्धस्रोतसा च पुनः शुक्राश्मर्यां शुक्राशयशोधनार्थं बलत्थेन पुंसा वृष्याण मांसानां कुक्कुटमांसस्य च तृप्तेनानुकूलाः प्रकर्षेण प्रियाः प्रमदा यथाकालमासेव्या इति", text: "śatāvarīgokṣurakabṛhatīdvayapunarnavośīramadhukadvisārivāśreyasīlodhratṛṇapañcamūlakaṣāye kṣīracaturguṇaṃ balāvṛkṣakakharāhvopakuñcikāvatsakatrapusorvārubījaśitivārakamadhukaṣaḍgranthāśatāhvāśmabhedamadanahapuṣākalkagarbhaṃ tailamuttarabastiḥ tadviśuddhasrotasā ca punaḥ śukrāśmaryāṃ śukrāśayaśodhanārthaṃ balatthena puṃsā vṛṣyāṇa māṃsānāṃ kukkuṭamāṃsasya ca tṛptenānukūlāḥ prakarṣeṇa priyāḥ pramadā yathākālamāsevyā iti" },
      { type: "verse", number: "25", sanskrit: "क्रियाभिराभिः सिद्धाभिर्नचेच्छान्तिस्ततो भिषक् इति राजानमापृच्छ्य शस्त्रं साध्ववचारयेत्", text: "kriyābhirābhiḥ siddhābhirnacecchāntistato bhiṣak iti rājānamāpṛcchya śastraṃ sādhvavacārayet" },
      { type: "verse", number: "26", sanskrit: "अक्रियायां ध्रुवो मृत्युः क्रियायां संशयो भवेत् निश्चितस्यापि वैद्यस्य बहुशः सिद्धकर्मणः", text: "akriyāyāṃ dhruvo mṛtyuḥ kriyāyāṃ saṃśayo bhavet niścitasyāpi vaidyasya bahuśaḥ siddhakarmaṇaḥ" },
      { type: "verse", number: "27", sanskrit: "अथातुरमुपस्निग्धमपकृष्टदोषमीषत्कर्शितमभ्यक्त स्विन्नशरीरमभुक्तवन्तं कृतमङ्गलस्वस्तिवाचनमुपकल्पितसम्भारमाश्वास्य ततो बलवन्तमविक्लवमाजानुसमे फलके प्रागुपवेश्य पुरुषं तस्योत्सङ्गे सुनिषष्णपूर्वकायमुत्तानं वस्त्रचुंबलोपविष्टं सङ्कुचितजानुकूर्परमितरेण पुंसा सहबद्धं सूत्रैः शाटकेन वा ततो ऽस्यस्वभ्यक्तं नाभिप्रदेशं वामपार्श्वे विमृद्य मुष्टिनावपीडयेत् अधोनाभेर्यावदश्मर्यधः प्रतिपन्ना ततस्तैलाभ्यक्ते कृत्तनखे वामहस्तप्रदेशिनीमध्यमे पायौ प्रणिधायानुसेवन्यासाद्य च प्रयत्नबलाभ्यामश्मरीं मेढ्रगुदयोरन्तरमानीय निर्वलीकमनायतमविषमं च बस्तिं सन्निवेश्य भृशमुत्पीडयेदङ्गुलीभ्यां यावत् ग्रन्थिरिवोन्नतं शल्यं भवति ततः सेवन्याः सव्ये पार्श्वे सेवनीं यवमात्रं मुक्त्वा निदध्याच्छस्त्रमश्मरीप्रमाणेन दक्षिणतो वा क्रियासौकर्यहेतोरित्येके यथा न विभिद्यते विचूर्ण्यते वा तथा प्रयतेत तच्चूर्णमल्पमप्यवस्थितं पुनः परिवृद्धिमेति तस्मात् समग्रामग्रवक्रेणाददीत", text: "athāturamupasnigdhamapakṛṣṭadoṣamīṣatkarśitamabhyakta svinnaśarīramabhuktavantaṃ kṛtamaṅgalasvastivācanamupakalpitasambhāramāśvāsya tato balavantamaviklavamājānusame phalake prāgupaveśya puruṣaṃ tasyotsaṅge suniṣaṣṇapūrvakāyamuttānaṃ vastracuṃbalopaviṣṭaṃ saṅkucitajānukūrparamitareṇa puṃsā sahabaddhaṃ sūtraiḥ śāṭakena vā tato 'syasvabhyaktaṃ nābhipradeśaṃ vāmapārśve vimṛdya muṣṭināvapīḍayet adhonābheryāvadaśmaryadhaḥ pratipannā tatastailābhyakte kṛttanakhe vāmahastapradeśinīmadhyame pāyau praṇidhāyānusevanyāsādya ca prayatnabalābhyāmaśmarīṃ meḍhragudayorantaramānīya nirvalīkamanāyatamaviṣamaṃ ca bastiṃ sanniveśya bhṛśamutpīḍayedaṅgulībhyāṃ yāvat granthirivonnataṃ śalyaṃ bhavati tataḥ sevanyāḥ savye pārśve sevanīṃ yavamātraṃ muktvā nidadhyācchastramaśmarīpramāṇena dakṣiṇato vā kriyāsaukaryahetorityeke yathā na vibhidyate vicūrṇyate vā tathā prayateta taccūrṇamalpamapyavasthitaṃ punaḥ parivṛddhimeti tasmāt samagrāmagravakreṇādadīta" },
      { type: "verse", number: "28", sanskrit: "स्त्रीणां तु बस्तिः पार्श्वगतो गर्भाशयसन्निकृष्टः तस्मात्तासामुत्सङ्गवदधः शस्त्रं पातयेत् अतो ऽन्यथा खल्वासां मूत्रस्रावी व्रणो भवति पुरुषस्य च मूत्रप्रसेकक्षणनात् अश्मरीनिमित्तमेकतो भिन्नो बस्तिः सिध्यति क्रियाभ्यासाच्छास्त्रविहितच्छेदादीनष्पन्दपरिवृद्धत्वाच्च शल्यस्येति न तु द्विधा भिन्नबस्तिरश्मरीमानमपि", text: "strīṇāṃ tu bastiḥ pārśvagato garbhāśayasannikṛṣṭaḥ tasmāttāsāmutsaṅgavadadhaḥ śastraṃ pātayet ato 'nyathā khalvāsāṃ mūtrasrāvī vraṇo bhavati puruṣasya ca mūtraprasekakṣaṇanāt aśmarīnimittamekato bhinno bastiḥ sidhyati kriyābhyāsācchāstravihitacchedādīnaṣpandaparivṛddhatvācca śalyasyeti na tu dvidhā bhinnabastiraśmarīmānamapi" },
      { type: "verse", number: "29", sanskrit: "उद्धृतशल्यं तूष्णोदकद्रोण्यामवगाह्य स्वेदयेत् तथा बस्तिरसृजा नापूर्यते पूर्णे तु क्षीरिवृक्षकषायं पुष्पनेत्रेण विदध्यात् स हि तथा बस्तिगतमश्मरीचूर्णं रक्तं च निर्हरति मूत्रविशुद्ध्यर्थं च गुडसौहित्यं कारयेत्", text: "uddhṛtaśalyaṃ tūṣṇodakadroṇyāmavagāhya svedayet tathā bastirasṛjā nāpūryate pūrṇe tu kṣīrivṛkṣakaṣāyaṃ puṣpanetreṇa vidadhyāt sa hi tathā bastigatamaśmarīcūrṇaṃ raktaṃ ca nirharati mūtraviśuddhyarthaṃ ca guḍasauhityaṃ kārayet" },
      { type: "verse", number: "30", sanskrit: "उत्थाप्य चैनं मधुघृताभ्यक्तव्रणं मूत्रविशोधनद्रव्यसिद्धामुष्णां यवागूं सघृतां पाययेदुभयकालं त्रिरात्रम् त्रिरात्रादूर्ध्वं गुडप्रगाडेन पयसा मृदुमोदनमल्पं भोजयेदादशरात्रात् अत ऊर्ध्वं फलाम्लैर्जाङ्गलरसैः व्रणं च क्षीरिवृक्षकषायेण प्रक्षाल्य लोध्रमधुकमञ्जिष्ठाप्रपौण्डरीककल्केन लेपयेत् द्वादशरात्रं चैनमप्रमत्तः स्वेदयेत् एतेष्वेव च हरिद्रादियुक्तेषु तैलं विपक्वं व्रणाभ्यञ्जनम् सप्तरात्राच्च स्वमार्गमप्रतिपद्यमाने मूत्रे यथोक्तमग्निना व्रणं दहेत् स्वमार्गप्रतिपन्ने चोत्तरबस्त्यास्थापनानुवासनैर्मधुरप्रायैरुपाचरेत्", text: "utthāpya cainaṃ madhughṛtābhyaktavraṇaṃ mūtraviśodhanadravyasiddhāmuṣṇāṃ yavāgūṃ saghṛtāṃ pāyayedubhayakālaṃ trirātram trirātrādūrdhvaṃ guḍapragāḍena payasā mṛdumodanamalpaṃ bhojayedādaśarātrāt ata ūrdhvaṃ phalāmlairjāṅgalarasaiḥ vraṇaṃ ca kṣīrivṛkṣakaṣāyeṇa prakṣālya lodhramadhukamañjiṣṭhāprapauṇḍarīkakalkena lepayet dvādaśarātraṃ cainamapramattaḥ svedayet eteṣveva ca haridrādiyukteṣu tailaṃ vipakvaṃ vraṇābhyañjanam saptarātrācca svamārgamapratipadyamāne mūtre yathoktamagninā vraṇaṃ dahet svamārgapratipanne cottarabastyāsthāpanānuvāsanairmadhuraprāyairupācaret" },
      { type: "verse", number: "31", sanskrit: "यदृच्छया मूत्रमार्गप्रतिपन्नामन्तरासक्तां शुक्राश्मरीं शर्करां वा स्रोतसापहरेत् विदार्य वा नाडिं बडिशेनोद्धरेत् रूढव्रणश्च वर्षमङ्गनाश्च नगनागरथद्रुमात् नारोहेत् नाप्सु प्लवेत भुञ्जीत वा गुरूणि", text: "yadṛcchayā mūtramārgapratipannāmantarāsaktāṃ śukrāśmarīṃ śarkarāṃ vā srotasāpaharet vidārya vā nāḍiṃ baḍiśenoddharet rūḍhavraṇaśca varṣamaṅganāśca naganāgarathadrumāt nārohet nāpsu plaveta bhuñjīta vā gurūṇi" },
      { type: "verse", number: "32", sanskrit: "कर्मणि तु मूत्रवहशुक्रवहमुष्कस्रोतोमूत्रप्रसेकसेवनीयोनिगुदबस्तयो ऽष्टौ परिहर्तव्याः तत्र मूत्रवहच्छेदात् मूत्रपूर्णबस्तेर्मरणम् शुक्रवहच्छेदान्मरणं क्लैब्यं वा मुष्कस्रोतसोरुपघातात् ध्वजभङ्गः मूत्रप्रसेकच्छेदान्मूत्रस्रवणम् सेवनीयोनिच्छेदनाद्रुजाप्रादुर्भावः गुदबस्तिविद्धस्य सद्योमरणमुक्तं प्रागिति", text: "karmaṇi tu mūtravahaśukravahamuṣkasrotomūtraprasekasevanīyonigudabastayo 'ṣṭau parihartavyāḥ tatra mūtravahacchedāt mūtrapūrṇabastermaraṇam śukravahacchedānmaraṇaṃ klaibyaṃ vā muṣkasrotasorupaghātāt dhvajabhaṅgaḥ mūtraprasekacchedānmūtrasravaṇam sevanīyonicchedanādrujāprādurbhāvaḥ gudabastividdhasya sadyomaraṇamuktaṃ prāgiti" },
      { type: "verse", number: "33", sanskrit: "भवति चात्र मर्माण्यमून्यविज्ञाय स्रोतोजानि शरीरिणाम् शस्त्रपाणिर्ध्रुवं हन्ति साहसात् केवलो यथा इति", text: "bhavati cātra marmāṇyamūnyavijñāya srotojāni śarīriṇām śastrapāṇirdhruvaṃ hanti sāhasāt kevalo yathā iti" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 14,
    lang: "sa",
    content: [
      { type: "heading", heading: "Каса чикитса — лечение кашля" },
      { type: "text", text: "Глава 14 Чикитса стханы — лечебный раздел о лечение кашля. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातः प्रमेहचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ pramehacikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "प्रायेण हि प्रमेहिणो ऽभिष्यण्णदेहत्वादुपहताग्नेर्भक्ष्यादिपञ्चविधमप्यन्नमुपयुक्तं मूत्राय मेदसे च विपरिणमते तस्मादस्य तेजोधातुवृद्धये क्लेदमेदः प्रशमनाय च बलिनः संशोधनानि प्रयुञ्जीत दुर्बलस्य तु संशमनानि सर्वस्य च बद्धमूत्राण्यमेदस्कराण्यबृंहणान्यग्निदीपनानि बलजननानि चान्नपानानि बलं हि विधिनोपचितमशेषामयक्षयाय सम्प्रवर्तते", text: "prāyeṇa hi pramehiṇo 'bhiṣyaṇṇadehatvādupahatāgnerbhakṣyādipañcavidhamapyannamupayuktaṃ mūtrāya medase ca vipariṇamate tasmādasya tejodhātuvṛddhaye kledamedaḥ praśamanāya ca balinaḥ saṃśodhanāni prayuñjīta durbalasya tu saṃśamanāni sarvasya ca baddhamūtrāṇyamedaskarāṇyabṛṃhaṇānyagnidīpanāni balajananāni cānnapānāni balaṃ hi vidhinopacitamaśeṣāmayakṣayāya sampravartate" },
      { type: "verse", number: "3", sanskrit: "अथ संशोधनार्हं प्रमेहिणमादवेव बिभीतकसर्षपेङ्गुदीकरञ्जनिम्बनिकुम्भान्यतमतैलेन त्रिकण्टकादिना वा यथास्वं सिद्धेन स्नेहेन प्रियङ्वादिशृतेन वा हविषा स्नेहयित्वा कल्पविहितैः प्रयोगैर्वामयेद्विरेचयेच्च", text: "atha saṃśodhanārhaṃ pramehiṇamādaveva bibhītakasarṣapeṅgudīkarañjanimbanikumbhānyatamatailena trikaṇṭakādinā vā yathāsvaṃ siddhena snehena priyaṅvādiśṛtena vā haviṣā snehayitvā kalpavihitaiḥ prayogairvāmayedvirecayecca" },
      { type: "verse", number: "4", sanskrit: "ततो जातबलं मुस्तामरदारुनागरप्रतिवापेन सुरसादिकषायेणास्थापयेत् पित्तोत्तरं तु न्यग्रोधादिकषायेण ततश्च जाङ्गलरसैः क्रमेण सन्तर्पयेत् अत्यपतर्पणेन हि प्रमेहिणो विशेषेण मूत्रकृच्छ्रबस्तिमेढ्रशूलगुल्मातिकार्श्यभ्रमादीनां सम्भवः ततो ऽनुबन्धरक्षणार्थं शमनार्हस्य च शमनान्यवचारयेत्", text: "tato jātabalaṃ mustāmaradārunāgaraprativāpena surasādikaṣāyeṇāsthāpayet pittottaraṃ tu nyagrodhādikaṣāyeṇa tataśca jāṅgalarasaiḥ krameṇa santarpayet atyapatarpaṇena hi pramehiṇo viśeṣeṇa mūtrakṛcchrabastimeḍhraśūlagulmātikārśyabhramādīnāṃ sambhavaḥ tato 'nubandharakṣaṇārthaṃ śamanārhasya ca śamanānyavacārayet" },
      { type: "verse", number: "5", sanskrit: "प्रातः सर्वप्रमेहेषु हरिद्रां मधुना युक्तामामलकरसेन पिबेत् अथवा सालसप्तपर्णकुटजकपित्थकम्पिल्लकबिभीतकरोहितककुसुमानि तच्चूर्णं वा क्षौद्रेण लिह्यात् हरीतकीचूर्णं वा पिबेद्वा त्रिफलामुस्तादेवदारुहरिद्राक्वाथम् असनचित्रकत्रिफलादार्वीकलिङ्गकानां वा सक्षौद्रम् तद्वद् गुडूच्या वा स्वरसमामलकानां वा", text: "prātaḥ sarvaprameheṣu haridrāṃ madhunā yuktāmāmalakarasena pibet athavā sālasaptaparṇakuṭajakapitthakampillakabibhītakarohitakakusumāni taccūrṇaṃ vā kṣaudreṇa lihyāt harītakīcūrṇaṃ vā pibedvā triphalāmustādevadāruharidrākvātham asanacitrakatriphalādārvīkaliṅgakānāṃ vā sakṣaudram tadvad guḍūcyā vā svarasamāmalakānāṃ vā" },
      { type: "verse", number: "6", sanskrit: "विशेषतस्तु कफमेहेषु कट्फलमुस्तालोध्राभयानां समाक्षिकं कषायम् तगरविडङ्गद्विहरिद्राणां वा चन्दनागरुकुष्ठदेवदारूणां वा पाठाग्निमन्थचविकात्रिफलानां वा पित्तप्रमेहेषु तु लोध्रसेव्यार्जुनचन्दनानाम् निम्बामृतामलकपटोलीनां वा शिरीषसर्जार्जुनकेसराणां वा फलिनीकमलोत्पलकिंशुकानां वा कुटजोत्पलकटङ्कटेरीणां वा", text: "viśeṣatastu kaphameheṣu kaṭphalamustālodhrābhayānāṃ samākṣikaṃ kaṣāyam tagaraviḍaṅgadviharidrāṇāṃ vā candanāgarukuṣṭhadevadārūṇāṃ vā pāṭhāgnimanthacavikātriphalānāṃ vā pittaprameheṣu tu lodhrasevyārjunacandanānām nimbāmṛtāmalakapaṭolīnāṃ vā śirīṣasarjārjunakesarāṇāṃ vā phalinīkamalotpalakiṃśukānāṃ vā kuṭajotpalakaṭaṅkaṭerīṇāṃ vā" },
      { type: "verse", number: "7", sanskrit: "तेष्वपि च विशेषेण पिबेदुदकमेहादिषु क्रमात् कषायं पारिजातस्य वैजयन्त्याः सप्तच्छदस्यारिष्टस्य निशायाः ककुभचन्दयोश्चित्रकस्य पाठाजोङ्गकयोः खदिरस्य त्रिफलारग्वधयोश्च मधुयुतम् पिबेच्च सिकतामेहे हिङ्गुप्रवालकैलालवणानि मद्येन मूत्रेण क्षारोदकेन वा क्षारमेहादिषु त्रिफलाया असनादेः न्यग्रोधादेः शम्याकस्य चन्दनमञ्जिष्ठयोः गुडूचीतिन्दुकास्थिकाश्मर्यखर्जूराणां च मधुयुक्तम् शोणितमेहे मदयन्तीपत्रकल्कं च सक्षौद्रं शीताम्बुना", text: "teṣvapi ca viśeṣeṇa pibedudakamehādiṣu kramāt kaṣāyaṃ pārijātasya vaijayantyāḥ saptacchadasyāriṣṭasya niśāyāḥ kakubhacandayościtrakasya pāṭhājoṅgakayoḥ khadirasya triphalāragvadhayośca madhuyutam pibecca sikatāmehe hiṅgupravālakailālavaṇāni madyena mūtreṇa kṣārodakena vā kṣāramehādiṣu triphalāyā asanādeḥ nyagrodhādeḥ śamyākasya candanamañjiṣṭhayoḥ guḍūcītindukāsthikāśmaryakharjūrāṇāṃ ca madhuyuktam śoṇitamehe madayantīpatrakalkaṃ ca sakṣaudraṃ śītāmbunā" },
      { type: "verse", number: "8", sanskrit: "वातयेष्वपि यापनार्थं कफपित्तोल्बणेषु पिबेत् कषायम् तत्र वसामेहे ऽग्निमन्थस्य मज्जमेहे ऽमृतचित्रकयोः कुष्ठकुटजपाठाकटुरोहिणीकल्कमिश्रम् हस्तमेहे हस्तिसूकरखरोष्ट्रास्थिक्षारम् मधुमेहे कदरखदिरपुरकषायम्", text: "vātayeṣvapi yāpanārthaṃ kaphapittolbaṇeṣu pibet kaṣāyam tatra vasāmehe 'gnimanthasya majjamehe 'mṛtacitrakayoḥ kuṣṭhakuṭajapāṭhākaṭurohiṇīkalkamiśram hastamehe hastisūkarakharoṣṭrāsthikṣāram madhumehe kadarakhadirapurakaṣāyam" },
      { type: "verse", number: "9", sanskrit: "कफानुगतेषु तु वसादिमेहेषु यथास्वकषायेण साधितानि तैलानि पित्तानुगतेषु च घृतानि यमकं वा प्रयुञ्जीत", text: "kaphānugateṣu tu vasādimeheṣu yathāsvakaṣāyeṇa sādhitāni tailāni pittānugateṣu ca ghṛtāni yamakaṃ vā prayuñjīta" },
      { type: "verse", number: "10", sanskrit: "एतेन शेषेष्वपि मेहेषु स्नेहविकल्प उक्तो वेदितव्यः", text: "etena śeṣeṣvapi meheṣu snehavikalpa ukto veditavyaḥ" },
      { type: "verse", number: "11", sanskrit: "तथा कषायसम्पृक्तैः स्नेहैः कफपित्तमूत्रमेदसामनिलस्य चोपशमो भवति", text: "tathā kaṣāyasampṛktaiḥ snehaiḥ kaphapittamūtramedasāmanilasya copaśamo bhavati" },
      { type: "verse", number: "12", sanskrit: "त्रिकण्टकातिविषाभल्लातकलोध्रवचापिचुमन्दघननिशाजमोदार्जुनाश्मन्तकपटोलसोमवल्कमञ्जिष्ठापद्मकचन्दनागरुभिश्च स्नेहो विपक्वः सर्वमेहघ्नः", text: "trikaṇṭakātiviṣābhallātakalodhravacāpicumandaghananiśājamodārjunāśmantakapaṭolasomavalkamañjiṣṭhāpadmakacandanāgarubhiśca sneho vipakvaḥ sarvamehaghnaḥ" },
      { type: "verse", number: "13", sanskrit: "दशमूलहरीतकीदेवदारुकरञ्जद्वयद्विवर्षाभूदन्तीभूकदम्बभल्लातकशठीपुष्करमूलार्कमूलस्नुहीमूलवरणमूलपिप्पलीमूलानि प्रत्येकशो दशपलोन्मितानि यवकोलकुलत्थप्रस्थत्रयं चाष्टगुणे ऽम्भसि साधयित्वा पादशेषं कषायमवतारयेत् तेन वचाविडङ्गकम्पिल्लकभल्लातकभार्ङ्गीरोहिषचविकापिप्पलीद्वयत्रिवृन्निचुलविश्वभेषजप्रतीवापं घृतप्रस्थं विपचेत् एतद्धान्वन्तरं सर्पिः सर्वमेहपिटकाकुष्ठविषशोफार्शोगुल्मविद्रधिप्लीहजठरश्वासकासवर्ध्मपाण्डुरोगवातशोणितोन्मादापस्मारहरम्", text: "daśamūlaharītakīdevadārukarañjadvayadvivarṣābhūdantībhūkadambabhallātakaśaṭhīpuṣkaramūlārkamūlasnuhīmūlavaraṇamūlapippalīmūlāni pratyekaśo daśapalonmitāni yavakolakulatthaprasthatrayaṃ cāṣṭaguṇe 'mbhasi sādhayitvā pādaśeṣaṃ kaṣāyamavatārayet tena vacāviḍaṅgakampillakabhallātakabhārṅgīrohiṣacavikāpippalīdvayatrivṛnniculaviśvabheṣajapratīvāpaṃ ghṛtaprasthaṃ vipacet etaddhānvantaraṃ sarpiḥ sarvamehapiṭakākuṣṭhaviṣaśophārśogulmavidradhiplīhajaṭharaśvāsakāsavardhmapāṇḍurogavātaśoṇitonmādāpasmāraharam" },
      { type: "verse", number: "14", sanskrit: "आहारं च यवविकृतिप्रायं मध्वामलकोपेतमाहारयेत् यथायथं प्रमेहघ्नौषधनिर्यूहैः सुबहुशो यवान् भावयित्वा सक्तुमन्थापूपधानालाजवाट्यादीन् विविधांश्च लघून् भक्ष्यानुपकल्पयेत् तद्वच्च गोधूमान् गवाश्वखरजठरस्थितैश्च यवैर्वंशयवैर्वा यवो हि बद्धमूत्रो मेदःपित्तकफहरः स्थैर्यकरश्च तथा शालिषष्टिकतृणधान्यानि मुद्गादयस्तिक्तानि शाकानि जाङ्गलानि च पिशितानि शूल्यानि परिशुष्काणि प्रदिग्धानि भृष्टचणकोपदंशानि विविधासवानुपानान्युपयुञ्जीत", text: "āhāraṃ ca yavavikṛtiprāyaṃ madhvāmalakopetamāhārayet yathāyathaṃ pramehaghnauṣadhaniryūhaiḥ subahuśo yavān bhāvayitvā saktumanthāpūpadhānālājavāṭyādīn vividhāṃśca laghūn bhakṣyānupakalpayet tadvacca godhūmān gavāśvakharajaṭharasthitaiśca yavairvaṃśayavairvā yavo hi baddhamūtro medaḥpittakaphaharaḥ sthairyakaraśca tathā śāliṣaṣṭikatṛṇadhānyāni mudgādayastiktāni śākāni jāṅgalāni ca piśitāni śūlyāni pariśuṣkāṇi pradigdhāni bhṛṣṭacaṇakopadaṃśāni vividhāsavānupānānyupayuñjīta" },
      { type: "verse", number: "15", sanskrit: "लोध्रमूर्वाशठीविडङ्गत्रिफलापुष्करमूलचातुर्जातकक्रमुकचविकायवानीश्यामाभार्ङ्गीद्विविशालाभूनिम्बतगरचित्रकपिप्पलीमूलकटुरोहिणीकुष्ठपाठेन्द्रयवातिविषाप्लवनखमरिचानि कर्षांशान्यपां कलशे ऽधिशृत्य तुर्यशेषे रसे पूते जतुशृतपुराणघृतभाजनस्थे ऽर्धभागेन मधु निधाय पक्षमुपेक्षितो ऽयं लोध्रासवः सर्वप्रमेहकुष्ठकिलासस्थौल्यारुचककृमिपाण्डुशोफार्शोग्रहणीदोषान्निहन्ति", text: "lodhramūrvāśaṭhīviḍaṅgatriphalāpuṣkaramūlacāturjātakakramukacavikāyavānīśyāmābhārṅgīdviviśālābhūnimbatagaracitrakapippalīmūlakaṭurohiṇīkuṣṭhapāṭhendrayavātiviṣāplavanakhamaricāni karṣāṃśānyapāṃ kalaśe 'dhiśṛtya turyaśeṣe rase pūte jatuśṛtapurāṇaghṛtabhājanasthe 'rdhabhāgena madhu nidhāya pakṣamupekṣito 'yaṃ lodhrāsavaḥ sarvapramehakuṣṭhakilāsasthaulyārucakakṛmipāṇḍuśophārśograhaṇīdoṣānnihanti" },
      { type: "verse", number: "16", sanskrit: "दशमूलदन्तीत्रिवृच्छ्यामाश्रेयसीचित्रकपुनर्नवसुधाधवैकैषिकागण्डीरगुडूचीनां पृथक् पञ्चविंशतिपलान् भागांस्त्रिफलाढकं च सलिलद्रोणैर्दशभिः पादशेषं निर्यूहमवतारयेत् तस्मिन् पूतशीते शुचिभाजनस्थे पुराणगुडतुलाद्वयं गोमूत्राढकमयोरजोर्धाढकं मागधिकाप्रस्थं कुटजार्जुनकुष्ठकृमिघ्नवचाचित्रकपलानि च द्वादश प्रतीवापं दत्वा मासं स्थापयेत् एष दशमूलारिष्टः समानः पूर्वेण", text: "daśamūladantītrivṛcchyāmāśreyasīcitrakapunarnavasudhādhavaikaiṣikāgaṇḍīraguḍūcīnāṃ pṛthak pañcaviṃśatipalān bhāgāṃstriphalāḍhakaṃ ca saliladroṇairdaśabhiḥ pādaśeṣaṃ niryūhamavatārayet tasmin pūtaśīte śucibhājanasthe purāṇaguḍatulādvayaṃ gomūtrāḍhakamayorajordhāḍhakaṃ māgadhikāprasthaṃ kuṭajārjunakuṣṭhakṛmighnavacācitrakapalāni ca dvādaśa pratīvāpaṃ datvā māsaṃ sthāpayet eṣa daśamūlāriṣṭaḥ samānaḥ pūrveṇa" },
      { type: "verse", number: "17", sanskrit: "असनादिद्रव्याणि पृथक् विंशतिपलान्यम्भसां घटाष्टकेन क्वाथयेत् चतुर्थस्थितं च परिस्रुतं सुशीतं गुडपलशतद्वयेन मध्वर्धाढकेन श्लक्ष्णपिष्टेन च पृथक् पलांशेन वत्सकादिना संयोज्य सक्षौद्रेण पिप्पलीचूर्णेनान्तःप्रलिप्ते जतुसृते घृतकुम्भे आवाप्य यवप्ल्ले निधापयेत् तत्र च तनूनि खदिराङ्गारप्रतप्तानि त्रींश्चतुरो वा मासानयं विवृतो लोहारिष्टः पूर्वस्मादधिकगुणः शीघुमधुमाधवानपि च निगदान् पिबेत्", text: "asanādidravyāṇi pṛthak viṃśatipalānyambhasāṃ ghaṭāṣṭakena kvāthayet caturthasthitaṃ ca parisrutaṃ suśītaṃ guḍapalaśatadvayena madhvardhāḍhakena ślakṣṇapiṣṭena ca pṛthak palāṃśena vatsakādinā saṃyojya sakṣaudreṇa pippalīcūrṇenāntaḥpralipte jatusṛte ghṛtakumbhe āvāpya yavaplle nidhāpayet tatra ca tanūni khadirāṅgāraprataptāni trīṃścaturo vā māsānayaṃ vivṛto lohāriṣṭaḥ pūrvasmādadhikaguṇaḥ śīghumadhumādhavānapi ca nigadān pibet" },
      { type: "verse", number: "18", sanskrit: "निवृत्तमद्यस्तु सारोदकं दर्भाम्भो मधुकपित्थतिन्दुकमरिचानुविद्धानि पानकानि रागषाडवांश्च सार्षपिकान्यनुपानानि च तद्विधानि उष्ट्राश्वतरखरपुरीषचूर्णानुविद्धं चास्मै दद्यादशनम्", text: "nivṛttamadyastu sārodakaṃ darbhāmbho madhukapitthatindukamaricānuviddhāni pānakāni rāgaṣāḍavāṃśca sārṣapikānyanupānāni ca tadvidhāni uṣṭrāśvatarakharapurīṣacūrṇānuviddhaṃ cāsmai dadyādaśanam" },
      { type: "verse", number: "19", sanskrit: "मुस्तामृतागण्डीरद्विहरिद्राद्विसारिवाद्विदर्भवर्षाभूत्रिकण्टकव्योषफल्गुरोहिषपल्लवश्यामासुरदारुकालाविडङ्गपाठाकम्पिल्लकभार्ङ्गीनिदिग्धिकादन्तीचित्रककटुकैरण्डमूलानि समांशान्यैकध्यं चूर्णयित्वा तच्चूर्णादयश्चूर्णं द्विगुणं श्लक्ष्णमावाप्य मद्यानुपानं मधुनावलिह्यात् पिबेद्वा सुखोदकेन त्रिफलाम्भसा वा तेन मेहप्लीहहलीमकपाण्डुरोगश्वयथुदुर्नामगुल्मोदराणि शीघ्रमुपशाम्यन्ति द्विविधोपक्रमणीयोक्तांश्चातिस्थौल्यादिगदयोगांश्च शीलयेत् प्रवृद्धमेदाः प्रगाढव्यायामोद्वर्तनस्नानविलेपनानि च रूक्षाभिरौषधीभिः", text: "mustāmṛtāgaṇḍīradviharidrādvisārivādvidarbhavarṣābhūtrikaṇṭakavyoṣaphalgurohiṣapallavaśyāmāsuradārukālāviḍaṅgapāṭhākampillakabhārṅgīnidigdhikādantīcitrakakaṭukairaṇḍamūlāni samāṃśānyaikadhyaṃ cūrṇayitvā taccūrṇādayaścūrṇaṃ dviguṇaṃ ślakṣṇamāvāpya madyānupānaṃ madhunāvalihyāt pibedvā sukhodakena triphalāmbhasā vā tena mehaplīhahalīmakapāṇḍurogaśvayathudurnāmagulmodarāṇi śīghramupaśāmyanti dvividhopakramaṇīyoktāṃścātisthaulyādigadayogāṃśca śīlayet pravṛddhamedāḥ pragāḍhavyāyāmodvartanasnānavilepanāni ca rūkṣābhirauṣadhībhiḥ" },
      { type: "verse", number: "20", sanskrit: "अधनस्तु छत्रपादत्रविरहितो मुनिवृत्तिर्योजनशतमधिकं वा गच्छेत् श्यामाकनीवारामतिन्दुककपित्थाश्मन्तकफलमूलाहारो वा मृगैः सह वसेत् गोभिर्वा सह तन्मूत्रशकृद्वृत्तिः परिभ्रमेत् तडागानि वा खनेत् कृशं त्वविरुद्धैर्बृंहयेत्", text: "adhanastu chatrapādatravirahito munivṛttiryojanaśatamadhikaṃ vā gacchet śyāmākanīvārāmatindukakapitthāśmantakaphalamūlāhāro vā mṛgaiḥ saha vaset gobhirvā saha tanmūtraśakṛdvṛttiḥ paribhramet taḍāgāni vā khanet kṛśaṃ tvaviruddhairbṛṃhayet" },
      { type: "verse", number: "21", sanskrit: "शराविकाद्यास्तु अपक्वाः शोफवदुपाचरेत् पक्वाश्च व्रणवत् पूर्वरूपेष्वेव तु तासां पाने वनस्पतिकषायं बस्तमूत्रं चोपदिशन्ति तीक्ष्णं च संशोधनं दुर्विरेच्या हि मेहिनो भवन्ति मेदोभिव्याप्तदेहत्वात् तैलं च व्रणरोपणार्थमेलादौ कुर्वीत आरग्वधादेः कषायमुद्वर्तने असनादेः परिषेचने वत्सकादेः पानभोजनेषु", text: "śarāvikādyāstu apakvāḥ śophavadupācaret pakvāśca vraṇavat pūrvarūpeṣveva tu tāsāṃ pāne vanaspatikaṣāyaṃ bastamūtraṃ copadiśanti tīkṣṇaṃ ca saṃśodhanaṃ durvirecyā hi mehino bhavanti medobhivyāptadehatvāt tailaṃ ca vraṇaropaṇārthamelādau kurvīta āragvadhādeḥ kaṣāyamudvartane asanādeḥ pariṣecane vatsakādeḥ pānabhojaneṣu" },
      { type: "verse", number: "22", sanskrit: "पाठाचित्रकशार्ङ्गेष्टाक्षुद्रवृहतीसारिवासोमवल्कसप्तपर्णारग्वधकुटजमूलचूर्णं मधुनालिह्यान्नवायसं वा असनादिवर्गस्य कषायं पादशेषं परिगृह्य परिस्राव्य च पुनः प्रियङ्ग्वामलकलोध्रदन्तीकृष्णायस्ताम्रचूर्णावापं दर्वीप्रलेपिनमवतारयेत् तं यथाबलमवलिह्यात् यथास्वं च प्रमेहघ्नौषधनिर्यूहैर्भावितशिलाजतुतुलोपयुक्ता सर्वमेहान् सपिटकानपकर्षतीति", text: "pāṭhācitrakaśārṅgeṣṭākṣudravṛhatīsārivāsomavalkasaptaparṇāragvadhakuṭajamūlacūrṇaṃ madhunālihyānnavāyasaṃ vā asanādivargasya kaṣāyaṃ pādaśeṣaṃ parigṛhya parisrāvya ca punaḥ priyaṅgvāmalakalodhradantīkṛṣṇāyastāmracūrṇāvāpaṃ darvīpralepinamavatārayet taṃ yathābalamavalihyāt yathāsvaṃ ca pramehaghnauṣadhaniryūhairbhāvitaśilājatutulopayuktā sarvamehān sapiṭakānapakarṣatīti" },
      { type: "verse", number: "23", sanskrit: "भवति चात्र मागधीमधुकं लेध्रं कुष्ठमेलाहरेणवः समङ्गा धातकीपुष्पं सारिवा रजनीद्वयम्", text: "bhavati cātra māgadhīmadhukaṃ ledhraṃ kuṣṭhamelāhareṇavaḥ samaṅgā dhātakīpuṣpaṃ sārivā rajanīdvayam" },
      { type: "verse", number: "24", sanskrit: "प्रियङ्गवः सर्जरसः पद्मकं पद्मकेसरम् मातुलुङ्गस्य पत्राणि मधूच्छिष्टं ससैन्धवम्", text: "priyaṅgavaḥ sarjarasaḥ padmakaṃ padmakesaram mātuluṅgasya patrāṇi madhūcchiṣṭaṃ sasaindhavam" },
      { type: "verse", number: "25", sanskrit: "तैस्तैलं सिद्धमभ्यङ्गाच्छोधयेद्रोपयेत च दुष्टारुःपिटकागण्डगण्डमालाभगन्दरान्", text: "taistailaṃ siddhamabhyaṅgācchodhayedropayeta ca duṣṭāruḥpiṭakāgaṇḍagaṇḍamālābhagandarān" },
      { type: "verse", number: "26", sanskrit: "पिटकाः साधयेच्छीघ्नं ता ह्यसून् घ्नन्ति मेहिनः अनुशेषानपि भिषग्यथाबलमुपद्रवान्", text: "piṭakāḥ sādhayecchīghnaṃ tā hyasūn ghnanti mehinaḥ anuśeṣānapi bhiṣagyathābalamupadravān" },
      { type: "verse", number: "27", sanskrit: "सर्वजत्वान्महामर्मसंश्रयादनुषङ्गतं सुबहूपद्रवत्वाच्च प्रमेहो दारुणे गदः", text: "sarvajatvānmahāmarmasaṃśrayādanuṣaṅgataṃ subahūpadravatvācca prameho dāruṇe gadaḥ" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 15,
    lang: "sa",
    content: [
      { type: "heading", heading: "Хикка чикитса — лечение икоты" },
      { type: "text", text: "Глава 15 Чикитса стханы — лечебный раздел о лечение икоты. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो विद्रधिवृद्धिचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vidradhivṛddhicikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सर्वमेव विद्रधिमामं शोफविधिना यथादोषमुपाचरेत् प्रततं च शोणितमपहरेत् पाकाभिमुखं चोपनाह्य पक्वं पाटयित्वा व्रणवच्चिकित्सेत्", text: "sarvameva vidradhimāmaṃ śophavidhinā yathādoṣamupācaret pratataṃ ca śoṇitamapaharet pākābhimukhaṃ copanāhya pakvaṃ pāṭayitvā vraṇavaccikitset" },
      { type: "verse", number: "3", sanskrit: "आभ्यन्तरे तु विद्रधौ वरणादिक्वाथमूषकादिप्रतीवापं पिबेत् आभ्यामेव च वर्गाभ्यां विरेचनद्रव्यैश्च पानाय् सर्पिः प्रकल्पयेत् आस्थापनमनुवासनं च मधुशिग्रुम् च पानभोजनलेपनेषु शिलाह्वयं वा कल्पविधानेनोपयुञ्जीत गुग्गुलुं वा यथादोषं च सर्वशो गुल्मवदुपक्रमेत्", text: "ābhyantare tu vidradhau varaṇādikvāthamūṣakādipratīvāpaṃ pibet ābhyāmeva ca vargābhyāṃ virecanadravyaiśca pānāy sarpiḥ prakalpayet āsthāpanamanuvāsanaṃ ca madhuśigrum ca pānabhojanalepaneṣu śilāhvayaṃ vā kalpavidhānenopayuñjīta gugguluṃ vā yathādoṣaṃ ca sarvaśo gulmavadupakramet" },
      { type: "verse", number: "4", sanskrit: "त्रिफलापिचुमन्दमधुककटुकापटोलानि शाणांशानि त्रिवृत्त्रायमाणयोः कर्षम् मसूरपलं चैकध्यमष्टगुणे ऽम्भसि साधयित्वा पूतं रसं घृतमूर्छितं पिबेत् तेन विद्रधिगुल्मज्वरदाहशूलतृष्णाहृद्रोगभ्रमारतिमूर्छारक्तपित्तकामलाकुष्ठविसर्पाः प्रशाम्यन्ति", text: "triphalāpicumandamadhukakaṭukāpaṭolāni śāṇāṃśāni trivṛttrāyamāṇayoḥ karṣam masūrapalaṃ caikadhyamaṣṭaguṇe 'mbhasi sādhayitvā pūtaṃ rasaṃ ghṛtamūrchitaṃ pibet tena vidradhigulmajvaradāhaśūlatṛṣṇāhṛdrogabhramāratimūrchāraktapittakāmalākuṣṭhavisarpāḥ praśāmyanti" },
      { type: "verse", number: "5", sanskrit: "त्रायमाणाप्रस्थक्वाथे मुस्तकटुकातामलकीत्रायमाणाचन्दनदुरालभाजीवन्तीवीरोत्पलैः पालिकैर्घृतप्रस्थं क्षीरामलकरसप्रस्थद्वयोपेतं विपक्वं समानं पूर्वेण", text: "trāyamāṇāprasthakvāthe mustakaṭukātāmalakītrāyamāṇācandanadurālabhājīvantīvīrotpalaiḥ pālikairghṛtaprasthaṃ kṣīrāmalakarasaprasthadvayopetaṃ vipakvaṃ samānaṃ pūrveṇa" },
      { type: "verse", number: "6", sanskrit: "द्राक्षामधूकखर्जूराभीरुविदारीपरूषकत्रिफलाक्वाथे क्षीरेक्षुधात्रीस्वरससमेतमभयागर्भं सर्पिर्विपाचयेत् तच्छीतं मधुशर्करापादयुक्तं समानं पूर्वेण भृशं च शृङ्गादिभिः शोणितमवसेचयेद्यथासन्नम् बाहुमध्ये वा सिरां व्यधेत् पच्यमानं च कोष्ठगतं बहिरुन्नतमुपनाहयेत्", text: "drākṣāmadhūkakharjūrābhīruvidārīparūṣakatriphalākvāthe kṣīrekṣudhātrīsvarasasametamabhayāgarbhaṃ sarpirvipācayet tacchītaṃ madhuśarkarāpādayuktaṃ samānaṃ pūrveṇa bhṛśaṃ ca śṛṅgādibhiḥ śoṇitamavasecayedyathāsannam bāhumadhye vā sirāṃ vyadhet pacyamānaṃ ca koṣṭhagataṃ bahirunnatamupanāhayet" },
      { type: "verse", number: "7", sanskrit: "तत्रैव च पिण्डिते शूले तत्पार्श्वपीडनेन लब्धसुप्तौ शस्त्रकर्मविधिनिर्दिष्टैश्च चिह्नैः पक्वमुपलक्ष्य भित्त्वा व्रणवत् साधयेत्", text: "tatraiva ca piṇḍite śūle tatpārśvapīḍanena labdhasuptau śastrakarmavidhinirdiṣṭaiśca cihnaiḥ pakvamupalakṣya bhittvā vraṇavat sādhayet" },
      { type: "verse", number: "8", sanskrit: "आभ्यन्तर एव च पक्वमूर्ध्वमधो वा प्रवृत्तं पूयमुपद्रवान् परिरक्षन् उपेक्षेत दशाहमात्रम्", text: "ābhyantara eva ca pakvamūrdhvamadho vā pravṛttaṃ pūyamupadravān parirakṣan upekṣeta daśāhamātram" },
      { type: "verse", number: "9", sanskrit: "असम्यग्वहति वा क्लेदे तन्निर्वाहणार्थमम्लसुरासवमैरेयोष्णोदकान्यतमेन वरणादिं मधुशिग्रुं वा पिबेत् तन्मूलैर्वा कृतां यवागूं यवकोलकुलत्थयूषेण चाश्नीयात् ऊर्ध्वं च दशाहात्तिल्वकघृतेन त्रायमाणा घृतेन वा यथाबलं शोधयेत्", text: "asamyagvahati vā klede tannirvāhaṇārthamamlasurāsavamaireyoṣṇodakānyatamena varaṇādiṃ madhuśigruṃ vā pibet tanmūlairvā kṛtāṃ yavāgūṃ yavakolakulatthayūṣeṇa cāśnīyāt ūrdhvaṃ ca daśāhāttilvakaghṛtena trāyamāṇā ghṛtena vā yathābalaṃ śodhayet" },
      { type: "verse", number: "10", sanskrit: "विशुद्धश्च तिक्तकमल्पमल्पं सर्पिर्मधुनोपेतमुपयुञ्जीत यथा च नोपैति पाकं तथा प्रयतितव्यम् शीघ्रविदाहित्वात्तस्य विद्रधिरिति संज्ञा पक्वे तु पुनर्दैविकी सिद्धिराशुकारितरश्च सर्वामयेभ्यो विद्रधिः सति च प्रमेहे प्रमेहचिकित्सितमीक्षेत", text: "viśuddhaśca tiktakamalpamalpaṃ sarpirmadhunopetamupayuñjīta yathā ca nopaiti pākaṃ tathā prayatitavyam śīghravidāhitvāttasya vidradhiriti saṃjñā pakve tu punardaivikī siddhirāśukāritaraśca sarvāmayebhyo vidradhiḥ sati ca pramehe pramehacikitsitamīkṣeta" },
      { type: "verse", number: "11", sanskrit: "स्तनविद्रधिमपि व्रणविधानेनोपचरेत् पच्यमानं यथेष्टभोजनेन पाचयेत् न पुनरुपनाहयेत् उपनद्धो हि स्तनो मृदुमांसतया शीघ्रमेव पक्वः सङ्कोथमवाप्यावदीर्येत पक्वं च स्तनविद्रधिं स्तन्यवाहिनीः सिराः सचूचुकं च कृष्णमण्डलं परिहरन् शस्त्रेणोपक्रमेत सर्वासु चामविदग्धपक्वव्रणावस्थासु स्तनं निर्दुहीत दन्तादिविद्रधीनामपि यथास्वमेव वक्ष्यते लक्षणं साधनं च इति विद्रधिचिकित्सा", text: "stanavidradhimapi vraṇavidhānenopacaret pacyamānaṃ yatheṣṭabhojanena pācayet na punarupanāhayet upanaddho hi stano mṛdumāṃsatayā śīghrameva pakvaḥ saṅkothamavāpyāvadīryeta pakvaṃ ca stanavidradhiṃ stanyavāhinīḥ sirāḥ sacūcukaṃ ca kṛṣṇamaṇḍalaṃ pariharan śastreṇopakrameta sarvāsu cāmavidagdhapakvavraṇāvasthāsu stanaṃ nirduhīta dantādividradhīnāmapi yathāsvameva vakṣyate lakṣaṇaṃ sādhanaṃ ca iti vidradhicikitsā" },
      { type: "verse", number: "12", sanskrit: "वृद्धौ तु मारुतजे त्रिवृता स्निग्धमातुरं स्विन्नं च मिश्रकसुकुमारकतिल्वकैरण्डकोशाम्रफलस्नेहानामन्यतमेन विरेचयेत् ततो ऽनिलघ्नक्वाथकल्कैर्निरूहयेत् निरूढं च मांसरसेनाशितं यष्टीमधुकतैलेनानुवासयेत् स्वेदप्रलेपोपनाहांश्च प्रयुञ्जीत पक्वं च भित्वा व्रणमिव चिकित्सेत्", text: "vṛddhau tu mārutaje trivṛtā snigdhamāturaṃ svinnaṃ ca miśrakasukumārakatilvakairaṇḍakośāmraphalasnehānāmanyatamena virecayet tato 'nilaghnakvāthakalkairnirūhayet nirūḍhaṃ ca māṃsarasenāśitaṃ yaṣṭīmadhukatailenānuvāsayet svedapralepopanāhāṃśca prayuñjīta pakvaṃ ca bhitvā vraṇamiva cikitset" },
      { type: "verse", number: "13", sanskrit: "पित्तवृद्धिं पित्तशोफवत् पक्वं च पित्तव्रणवत्", text: "pittavṛddhiṃ pittaśophavat pakvaṃ ca pittavraṇavat" },
      { type: "verse", number: "14", sanskrit: "कफवृद्धिमपि कफशोफवत् पिबेच्च पीतदारुकषायं मूत्रेण कफग्रन्थिवच्च सर्वं विम्लापनवर्ज्यमाचरेत् पक्वं च पाटितं श्लेष्मव्रणवत् रक्तजं पित्तवृद्धिवत् प्रततं चात्र रक्तमपहरेत्", text: "kaphavṛddhimapi kaphaśophavat pibecca pītadārukaṣāyaṃ mūtreṇa kaphagranthivacca sarvaṃ vimlāpanavarjyamācaret pakvaṃ ca pāṭitaṃ śleṣmavraṇavat raktajaṃ pittavṛddhivat pratataṃ cātra raktamapaharet" },
      { type: "verse", number: "15", sanskrit: "मेदोवृद्धिं गवादिकरीषतुषकिण्वसुरसादिभिरुष्णरूक्षैर्मूत्रयुक्तैः स्वेदयित्वा पुनस्तद्विधैरेव सुखोष्णैः सोत्सेधं लेपयेत् तद्वच्छिरोविरेकद्रव्यैर्वा स्विन्नं चैवं फलसेवनीं परिहरन् वृद्धिपत्रेण विदार्यापनीयमेदः कासीससैन्धवमाक्षिकैः प्रतिसार्य सीव्येत् ततः सुमनोग्रन्थिमनःशिलैलाभल्लातकैस्तैलमभ्यङ्गार्थं कुर्यात् आव्रणसन्धानाच्च स्नेहस्वेदौ", text: "medovṛddhiṃ gavādikarīṣatuṣakiṇvasurasādibhiruṣṇarūkṣairmūtrayuktaiḥ svedayitvā punastadvidhaireva sukhoṣṇaiḥ sotsedhaṃ lepayet tadvacchirovirekadravyairvā svinnaṃ caivaṃ phalasevanīṃ pariharan vṛddhipatreṇa vidāryāpanīyamedaḥ kāsīsasaindhavamākṣikaiḥ pratisārya sīvyet tataḥ sumanogranthimanaḥśilailābhallātakaistailamabhyaṅgārthaṃ kuryāt āvraṇasandhānācca snehasvedau" },
      { type: "verse", number: "16", sanskrit: "मूत्रवृद्धिं स्निग्धैः स्वेदयित्वा वस्त्रपट्टेन वेष्टयेत् ततो ऽधस्तात् सेवन्या दकोदरवद्व्रीहिमुखेन भित्वा नाड्या स्रावयेत् ततः स्थगिकाबन्धं कुर्यात् व्रणे च शोधनरोपणानि", text: "mūtravṛddhiṃ snigdhaiḥ svedayitvā vastrapaṭṭena veṣṭayet tato 'dhastāt sevanyā dakodaravadvrīhimukhena bhitvā nāḍyā srāvayet tataḥ sthagikābandhaṃ kuryāt vraṇe ca śodhanaropaṇāni" },
      { type: "verse", number: "17", sanskrit: "आन्त्रवृद्धिं फलकोशमसंप्राप्तं वातवृद्धिवदुपचरेत् पुनर्नवशतपलं दशपलानि च पृथक् दशमूलपयस्याश्वगन्धाशतावर्येरण्डमूलान्यपां वहे ऽष्टांशावशेषं साधयेत् पूतशीते च तस्मिन् निर्यूहे त्रिंशद्गुडपलान्येरण्डतैलप्रस्थं घृतद्विप्रस्थं क्षीरद्विप्रस्थं कल्कीकृतानि च द्विपलिकानि द्राक्षानागरपिप्पलीपिप्पलीमूलयवानीयवक्षारचित्रकमधुकसैन्धवान्यावाप्यैकध्यं विपचेत् एतत् सर्वयन्त्रणास्वपरिक्लेशेन मुकुमाराख्यं सुकुमाराणामीश्वराणां नारीणां क्षीणरेतसामप्रजानामल्पाग्नीनां विषमाग्नीनां च कामतोन्नपाने वा प्रयुक्तमलक्ष्मीघ्नं कान्तिकरं बल्यं बृंहणं वयस्थापनं वर्ध्मविद्रधिप्लीहगुल्मोदावर्तशोफोदरार्शोमेढ्रयोनिरोगेषु महावातव्याधिषु च परममौषधम् गन्धर्वहस्तमूलतुलां यवाढकं नागरार्धकुडवं च सलिलद्रोणे पादशेषं विपचेत् तेन द्विगुणक्षीरेणैरण्डतैलप्रस्थं साधयेत् कल्कपिष्टं चात्र दद्यात् पुनर्गन्धर्वहस्तमूलकुडवं शुण्ठीपलं च एतत् गन्धर्वहस्ततैलं तुल्यं पूर्वेण भवति चात्र", text: "āntravṛddhiṃ phalakośamasaṃprāptaṃ vātavṛddhivadupacaret punarnavaśatapalaṃ daśapalāni ca pṛthak daśamūlapayasyāśvagandhāśatāvaryeraṇḍamūlānyapāṃ vahe 'ṣṭāṃśāvaśeṣaṃ sādhayet pūtaśīte ca tasmin niryūhe triṃśadguḍapalānyeraṇḍatailaprasthaṃ ghṛtadviprasthaṃ kṣīradviprasthaṃ kalkīkṛtāni ca dvipalikāni drākṣānāgarapippalīpippalīmūlayavānīyavakṣāracitrakamadhukasaindhavānyāvāpyaikadhyaṃ vipacet etat sarvayantraṇāsvaparikleśena mukumārākhyaṃ sukumārāṇāmīśvarāṇāṃ nārīṇāṃ kṣīṇaretasāmaprajānāmalpāgnīnāṃ viṣamāgnīnāṃ ca kāmatonnapāne vā prayuktamalakṣmīghnaṃ kāntikaraṃ balyaṃ bṛṃhaṇaṃ vayasthāpanaṃ vardhmavidradhiplīhagulmodāvartaśophodarārśomeḍhrayonirogeṣu mahāvātavyādhiṣu ca paramamauṣadham gandharvahastamūlatulāṃ yavāḍhakaṃ nāgarārdhakuḍavaṃ ca saliladroṇe pādaśeṣaṃ vipacet tena dviguṇakṣīreṇairaṇḍatailaprasthaṃ sādhayet kalkapiṣṭaṃ cātra dadyāt punargandharvahastamūlakuḍavaṃ śuṇṭhīpalaṃ ca etat gandharvahastatailaṃ tulyaṃ pūrveṇa bhavati cātra" },
      { type: "verse", number: "18", sanskrit: "यायाद्वर्ध्म न चेच्छातिं स्नेहरेकानुवासनैः बस्तिकर्म पुरः कृत्वा वङ्क्षणस्थं ततो दहेत् अग्निना मार्गरोधार्थं मरुतो ऽर्धेन्दुवक्रया", text: "yāyādvardhma na cecchātiṃ sneharekānuvāsanaiḥ bastikarma puraḥ kṛtvā vaṅkṣaṇasthaṃ tato dahet agninā mārgarodhārthaṃ maruto 'rdhenduvakrayā" },
      { type: "verse", number: "19", sanskrit: "अङ्गुष्ठस्योपरि स्नाव पीतं तन्तुसमं च यत् उत्क्षिप्य सूच्या तत्तिर्यक् दहेच्छित्वा यतो गदः", text: "aṅguṣṭhasyopari snāva pītaṃ tantusamaṃ ca yat utkṣipya sūcyā tattiryak dahecchitvā yato gadaḥ" },
      { type: "verse", number: "20", sanskrit: "ततो ऽन्यपार्श्वे ऽन्ये त्वाहुर्दहेद्वानामिकाङ्गुलेः", text: "tato 'nyapārśve 'nye tvāhurdahedvānāmikāṅguleḥ" },
      { type: "verse", number: "21", sanskrit: "गुल्मे ऽन्यैर्वातकफजे प्लीह्नि चायं विधिः स्मृतः कनिष्ठिकानामिकयोर्विश्वभ्यां तु यतो गदः", text: "gulme 'nyairvātakaphaje plīhni cāyaṃ vidhiḥ smṛtaḥ kaniṣṭhikānāmikayorviśvabhyāṃ tu yato gadaḥ" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 16,
    lang: "sa",
    content: [
      { type: "heading", heading: "Вата ракта чикитса — лечение подагры" },
      { type: "text", text: "Глава 16 Чикитса стханы — лечебный раздел о лечение подагры. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो गुल्मचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto gulmacikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "गुल्मो हि वातादृते न सम्भवति तस्मात्तेषु सर्वेष्वपि प्रथमं स्नेहस्वेदौ वातहहरौ स्नेहोपसंहितं मृदु विरेचनं तद्विधांश्च बहुशो बस्तीनम्ललवणमधुरांश्च रसान् युक्त्यावचारयेत् मारुते हि विजिते ऽल्पेनापि यत्नेन शक्यो ऽन्यो ऽपि दोषो गुल्मेषु नियन्तुम्", text: "gulmo hi vātādṛte na sambhavati tasmātteṣu sarveṣvapi prathamaṃ snehasvedau vātahaharau snehopasaṃhitaṃ mṛdu virecanaṃ tadvidhāṃśca bahuśo bastīnamlalavaṇamadhurāṃśca rasān yuktyāvacārayet mārute hi vijite 'lpenāpi yatnena śakyo 'nyo 'pi doṣo gulmeṣu niyantum" },
      { type: "verse", number: "3", sanskrit: "अथ वातोत्तरे रूक्षं बद्धमरुच्छकृतमातुरं तीव्ररुजमानिलव्याधिविहितमन्यतम तैलं पाययेत् अथवा विडङ्गपञ्चकोलमरिचत्रिफलाधान्यकगर्भं सपयस्सर्पिर्विपक्वम् अनेनैव वा कल्केन दशमूलक्वाथोपहितम् राजयक्ष्मविहितं वा षट्पलम् हिङ्गुधानकाम्लवेतससौवर्चलैलाबिडशठीदाडिमयवक्षारत्रिकटुकाजगन्धाजमोदाजाजीपुष्करमूलवचाचित्रकसुरसैर्वा दधिस्ंयुक्तम्", text: "atha vātottare rūkṣaṃ baddhamarucchakṛtamāturaṃ tīvrarujamānilavyādhivihitamanyatama tailaṃ pāyayet athavā viḍaṅgapañcakolamaricatriphalādhānyakagarbhaṃ sapayassarpirvipakvam anenaiva vā kalkena daśamūlakvāthopahitam rājayakṣmavihitaṃ vā ṣaṭpalam hiṅgudhānakāmlavetasasauvarcalailābiḍaśaṭhīdāḍimayavakṣāratrikaṭukājagandhājamodājājīpuṣkaramūlavacācitrakasurasairvā dadhisṃyuktam" },
      { type: "verse", number: "4", sanskrit: "हपुषामरिचबाष्विकासैन्धवदीप्यकाजाजीपञ्चकोलकैः कोलमूलकदाडिमरसदधिक्षीरवत् सर्पिः सिद्धं सिद्धं शूलविबन्धहिध्माध्मानप्लीहहृद्रोगग्रहणीहतनामकृमिवर्ध्मपाण्डुक्षयश्वासकासयोनिरोगोदरज्वरारोचकेषु शुण्ठीपलं पिप्पलीपलमध्यर्धं धानकाकुडवं दाडिमद्विकुडवं घृतपलानि विंशतिः क्षीरं चैकध्यं विपचेत् एतत्सर्पिः समानं पूर्वेण", text: "hapuṣāmaricabāṣvikāsaindhavadīpyakājājīpañcakolakaiḥ kolamūlakadāḍimarasadadhikṣīravat sarpiḥ siddhaṃ siddhaṃ śūlavibandhahidhmādhmānaplīhahṛdrogagrahaṇīhatanāmakṛmivardhmapāṇḍukṣayaśvāsakāsayonirogodarajvarārocakeṣu śuṇṭhīpalaṃ pippalīpalamadhyardhaṃ dhānakākuḍavaṃ dāḍimadvikuḍavaṃ ghṛtapalāni viṃśatiḥ kṣīraṃ caikadhyaṃ vipacet etatsarpiḥ samānaṃ pūrveṇa" },
      { type: "verse", number: "5", sanskrit: "लशुनस्य विगतत्वचस्तुलां प्रत्येकं पञ्चपलिकं च महापञ्चमूलमष्टगुणे ऽम्भसि साधयेत् तेन क्वाथेन तदर्धांशैश्च पृथक् सुरादधिमस्तुधान्याम्लदाडिमरसैः यवानीदीप्यकाम्लवेतसहिङ्गुचविकासैन्धवत्र्यूषणत्रिफलामरदारुभिश्चार्धपलिकैः प्रस्थोन्मितं घृतं शृतं पीतं समानं पूर्वेण", text: "laśunasya vigatatvacastulāṃ pratyekaṃ pañcapalikaṃ ca mahāpañcamūlamaṣṭaguṇe 'mbhasi sādhayet tena kvāthena tadardhāṃśaiśca pṛthak surādadhimastudhānyāmladāḍimarasaiḥ yavānīdīpyakāmlavetasahiṅgucavikāsaindhavatryūṣaṇatriphalāmaradārubhiścārdhapalikaiḥ prasthonmitaṃ ghṛtaṃ śṛtaṃ pītaṃ samānaṃ pūrveṇa" },
      { type: "verse", number: "6", sanskrit: "वर्षाभूद्वयदशमूलाश्वगन्धासुषवीच्छिन्नरुहाभार्ङ्गीरास्नैरण्डबलाकालाशठीपुष्करमूलगन्धपलाशान् द्विपलांशान् प्रस्थं प्रस्थं च यवमाषकोलकुलत्थानां जलद्रोणे पादावशिष्टं विपचेत् तेन पृथक् समं मातुलुङ्गदाडिमाम्रातकरसशुक्ततुषोदकारनालं घृतप्रस्थं दध्याढकोपेतं वचाकारवीशताह्वाद्विक्षारत्रिलवणत्रिकटुकरास्नाकुम्भनिकुम्भयवानीयवानकहिंस्राम्लवेतसनीलिनीफलविडङ्गदाडिमहिङ्गुपाषाणभेदकोषकवृषकहपुषाभार्ङ्गीश्वदंष्ट्रात्रपुसैर्वारुबीजाजाजीसारिवोपकुञ्चिकाग्रन्थिककुस्तुम्बरीतुम्बुरुफलमूर्वाचित्रकसुरसागजपिप्पलीगर्भं साधयेत् दाधिकाख्यमेतत् सर्पिः समानं पूर्वेण मूत्रघातोन्मादापस्मारवातव्याधिहरं च पिबेद्वा व्योषषड्ग्रन्थाकृमिघ्नकटुकाचित्रकसौवर्चलाभयायवक्षारैर्दशांशक्षीरसंयुक्तं साधितं सर्पिः क्षीरायोग्याय च सुरामदिरामस्तुदधिसरदाडिमरसानामन्यतमं विदध्यात्", text: "varṣābhūdvayadaśamūlāśvagandhāsuṣavīcchinnaruhābhārṅgīrāsnairaṇḍabalākālāśaṭhīpuṣkaramūlagandhapalāśān dvipalāṃśān prasthaṃ prasthaṃ ca yavamāṣakolakulatthānāṃ jaladroṇe pādāvaśiṣṭaṃ vipacet tena pṛthak samaṃ mātuluṅgadāḍimāmrātakarasaśuktatuṣodakāranālaṃ ghṛtaprasthaṃ dadhyāḍhakopetaṃ vacākāravīśatāhvādvikṣāratrilavaṇatrikaṭukarāsnākumbhanikumbhayavānīyavānakahiṃsrāmlavetasanīlinīphalaviḍaṅgadāḍimahiṅgupāṣāṇabhedakoṣakavṛṣakahapuṣābhārṅgīśvadaṃṣṭrātrapusairvārubījājājīsārivopakuñcikāgranthikakustumbarītumburuphalamūrvācitrakasurasāgajapippalīgarbhaṃ sādhayet dādhikākhyametat sarpiḥ samānaṃ pūrveṇa mūtraghātonmādāpasmāravātavyādhiharaṃ ca pibedvā vyoṣaṣaḍgranthākṛmighnakaṭukācitrakasauvarcalābhayāyavakṣārairdaśāṃśakṣīrasaṃyuktaṃ sādhitaṃ sarpiḥ kṣīrāyogyāya ca surāmadirāmastudadhisaradāḍimarasānāmanyatamaṃ vidadhyāt" },
      { type: "verse", number: "7", sanskrit: "अभ्यङ्गपूर्वं चैनं सदा स्वेदयेत् स्नेहस्वेदौ हि सम्यक् प्रयुक्तौ स्रोतसां मार्दवमुपजनय्यानिलं जित्वा भित्वा च विबन्धमाशु गुल्ममपकर्षतः", text: "abhyaṅgapūrvaṃ cainaṃ sadā svedayet snehasvedau hi samyak prayuktau srotasāṃ mārdavamupajanayyānilaṃ jitvā bhitvā ca vibandhamāśu gulmamapakarṣataḥ" },
      { type: "verse", number: "8", sanskrit: "तत्र हृदयजे विशेषेण स्नेहपानमिच्छन्ति बस्तिजे बस्तिमुभयं नाभिपार्श्वाश्रये विबद्धानिलवर्चसश्च दीप्ताग्नेः स्निग्धोष्णानि बृंहणानि चान्नपानानि पुनःपुनश्च स्नेहपाननिरूहानुवासनानि कफपित्तानुरक्षिणायोज्यानि", text: "tatra hṛdayaje viśeṣeṇa snehapānamicchanti bastije bastimubhayaṃ nābhipārśvāśraye vibaddhānilavarcasaśca dīptāgneḥ snigdhoṣṇāni bṛṃhaṇāni cānnapānāni punaḥpunaśca snehapānanirūhānuvāsanāni kaphapittānurakṣiṇāyojyāni" },
      { type: "verse", number: "9", sanskrit: "अन्यथा कफो विवृद्धस्तन्द्रागौरवारुचिहृल्लासाग्निसादान् कुर्यात् तमुल्लिखेत् तत्कृतेषु च शूलानाहविबन्धेष्वनन्तरोक्तानां घृतानामौषधैश्चूर्णगुटिकाक्वाथान् कोलदाडिममातुलुङ्गसुरामण्डतक्रमस्तुधान्याम्लोष्णोदकानामन्यतमेन प्रकल्पयेत् अपि च", text: "anyathā kapho vivṛddhastandrāgauravārucihṛllāsāgnisādān kuryāt tamullikhet tatkṛteṣu ca śūlānāhavibandheṣvanantaroktānāṃ ghṛtānāmauṣadhaiścūrṇaguṭikākvāthān koladāḍimamātuluṅgasurāmaṇḍatakramastudhānyāmloṣṇodakānāmanyatamena prakalpayet api ca" },
      { type: "verse", number: "10", sanskrit: "त्रिलवणहपुषाजमोदाजगन्धावचाहिङ्गुपाठोपकुञ्चीशठीजीरकाजाजिकुस्तुम्बरीबाष्पिकाकारवीतुम्बुरुस्वर्जिका यावशूको जटापौष्करी दाडिमं तिन्तिणीकं विडङ्गानि भार्ङ्गी वरो वेतसाम्लो मिशिर्मरिचगजकणाभयापञ्चकोलानि कुम्भो निकुम्भो विशाला यवानी सुराह्वं च तत्सर्वमेकत्र चूर्णीकृतं बीजपूराद्रसेनासकृत् भावितं यः पिबेत् प्रातराहारकाले ऽथवा मासमात्रं हिताशी नरः सादरम् प्लुतमशिशिरवारिणा जीर्णमद्येन मूत्रेण तक्रेण कोलाम्भसा मस्तुना पेयया सर्पिषौष्ट्रेण दुग्धेन कौलत्थयूषेण वा क्षारनिश्च्योततोयेन वा दाडिमाद्वारसेनात्मवानेभिरेवौषधैः साधितं वा घृतं हृदयगुदकटीयकृत्प्लीहगुह्याश्रितं तस्य शूलं प्रणश्येत् तथा गुल्मविष्टम्भदुर्नामकृच्छ्रोदराध्मानहिध्माविबन्धाः सवर्ध्मारुचिश्वासकासाः प्रपक्तुं च शक्तो भवेत् पावकः प्राश्यमानानि पाषाणचूर्णान्यपि", text: "trilavaṇahapuṣājamodājagandhāvacāhiṅgupāṭhopakuñcīśaṭhījīrakājājikustumbarībāṣpikākāravītumburusvarjikā yāvaśūko jaṭāpauṣkarī dāḍimaṃ tintiṇīkaṃ viḍaṅgāni bhārṅgī varo vetasāmlo miśirmaricagajakaṇābhayāpañcakolāni kumbho nikumbho viśālā yavānī surāhvaṃ ca tatsarvamekatra cūrṇīkṛtaṃ bījapūrādrasenāsakṛt bhāvitaṃ yaḥ pibet prātarāhārakāle 'thavā māsamātraṃ hitāśī naraḥ sādaram plutamaśiśiravāriṇā jīrṇamadyena mūtreṇa takreṇa kolāmbhasā mastunā peyayā sarpiṣauṣṭreṇa dugdhena kaulatthayūṣeṇa vā kṣāraniścyotatoyena vā dāḍimādvārasenātmavānebhirevauṣadhaiḥ sādhitaṃ vā ghṛtaṃ hṛdayagudakaṭīyakṛtplīhaguhyāśritaṃ tasya śūlaṃ praṇaśyet tathā gulmaviṣṭambhadurnāmakṛcchrodarādhmānahidhmāvibandhāḥ savardhmāruciśvāsakāsāḥ prapaktuṃ ca śakto bhavet pāvakaḥ prāśyamānāni pāṣāṇacūrṇānyapi" },
      { type: "verse", number: "11", sanskrit: "अभयापलद्वयमम्लवेतसपलद्वयं पालिकान् वचाविश्वभेषजत्रिवृद्दन्तीचित्रकशठीपुष्करजटायावशूकान् कार्षिकान् मरिचाजाजीसैन्धवोपकुञ्चिकाशितिवारकयवानीधातकीपुष्पविडङ्गान् हिङ्गुत्रिकर्षं च चूर्णितं पूर्ववद्भावितं पीतं च समानं तेन", text: "abhayāpaladvayamamlavetasapaladvayaṃ pālikān vacāviśvabheṣajatrivṛddantīcitrakaśaṭhīpuṣkarajaṭāyāvaśūkān kārṣikān maricājājīsaindhavopakuñcikāśitivārakayavānīdhātakīpuṣpaviḍaṅgān hiṅgutrikarṣaṃ ca cūrṇitaṃ pūrvavadbhāvitaṃ pītaṃ ca samānaṃ tena" },
      { type: "verse", number: "12", sanskrit: "यवानीशतपुष्पानागकेसरवचामुस्तव्योषपाठागुग्गुलुत्रिवृतागजपिप्पलीतालीसैलापामार्गद्रवन्तीनिदिग्धिकामूलानां भागो भागश्चाम्लवेतसस्य तत्सूक्ष्मरजीकृतं मातुलुङ्गदाडिमबदररसशीधुसुरोष्णसलिलान्यतमेन पीतं शूलगुल्मवर्ध्मानाहोदरकोष्ठस्तैमित्यार्शोश्मरीमूत्रग्रहकटीपृष्ठग्रहोन्मादापस्मारस्कन्नशुक्रताग्निसादानपनयति", text: "yavānīśatapuṣpānāgakesaravacāmustavyoṣapāṭhāguggulutrivṛtāgajapippalītālīsailāpāmārgadravantīnidigdhikāmūlānāṃ bhāgo bhāgaścāmlavetasasya tatsūkṣmarajīkṛtaṃ mātuluṅgadāḍimabadararasaśīdhusuroṣṇasalilānyatamena pītaṃ śūlagulmavardhmānāhodarakoṣṭhastaimityārśośmarīmūtragrahakaṭīpṛṣṭhagrahonmādāpasmāraskannaśukratāgnisādānapanayati" },
      { type: "verse", number: "13", sanskrit: "तिलकुन्तलपलाशसर्षपयवनालमूलकबीजानामन्तर्धूमदग्धानां क्षारं गोजाविमहिषीखरहस्तिमूत्रैर्बहुकृत्वो गालयेत् ततस्तदच्छं शुण्ठीसैन्धवकुष्ठकृमिघ्नचूर्णप्रतीवापमधिशृत्य लेहीभूतमाददीत तत्तैलयुक्तं समानं पूर्वेण", text: "tilakuntalapalāśasarṣapayavanālamūlakabījānāmantardhūmadagdhānāṃ kṣāraṃ gojāvimahiṣīkharahastimūtrairbahukṛtvo gālayet tatastadacchaṃ śuṇṭhīsaindhavakuṣṭhakṛmighnacūrṇapratīvāpamadhiśṛtya lehībhūtamādadīta tattailayuktaṃ samānaṃ pūrveṇa" },
      { type: "verse", number: "14", sanskrit: "महौषधदेवदारुदन्तीत्रिवृत्पाठाक्षारद्वयत्रिफलोपकुञ्चिकाचविकाद्वीपिप्पलीद्वयपिप्पलीमूलसर्पसुगन्धा कुष्टकटुरोहिणीनामर्धपलिकान् भागान् पलं पलं च पञ्चानां लवणानामेकत्र चूर्णयित्वा दध्ना त्रिवृतेन चाप्लाव्य कलशोदरे ऽन्तर्धूमं पाचयेत् अग्निवर्णं च कलशमपनीय क्षारमाददीत एष क्षारागदो भेलविहितः समानः पूर्वेण सर्पमूषिकदष्टगरापस्मारोन्मादाश्मरीयोनिशुक्रदोषांश्च साधयति", text: "mahauṣadhadevadārudantītrivṛtpāṭhākṣāradvayatriphalopakuñcikācavikādvīpippalīdvayapippalīmūlasarpasugandhā kuṣṭakaṭurohiṇīnāmardhapalikān bhāgān palaṃ palaṃ ca pañcānāṃ lavaṇānāmekatra cūrṇayitvā dadhnā trivṛtena cāplāvya kalaśodare 'ntardhūmaṃ pācayet agnivarṇaṃ ca kalaśamapanīya kṣāramādadīta eṣa kṣārāgado bhelavihitaḥ samānaḥ pūrveṇa sarpamūṣikadaṣṭAgarāpasmāronmādāśmarīyoniśukradoṣāṃśca sādhayati" },
      { type: "verse", number: "15", sanskrit: "पित्तं च विवृद्धमन्तः सन्तापं जनयेत् तत्रैरण्डतैलं सपयस्कं विरेचनार्थं पिबेत् सकफस्तु वारुणीमण्डमिश्रम् अत्युद्रिक्तपित्तस्त्रिफलां त्रायमाणां वा क्षीरेण पिबेत् विरिक्तस्यापि सन्तापानुवृत्तौ रक्तमवसेचयेत्", text: "pittaṃ ca vivṛddhamantaḥ santāpaṃ janayet tatrairaṇḍatailaṃ sapayaskaṃ virecanārthaṃ pibet sakaphastu vāruṇīmaṇḍamiśram atyudriktapittastriphalāṃ trāyamāṇāṃ vā kṣīreṇa pibet viriktasyāpi santāpānuvṛttau raktamavasecayet" },
      { type: "verse", number: "16", sanskrit: "विड्विबन्धे चोदावर्तक्रमं कुर्यात् लुञ्चिततिलपलद्वयं शुण्ठ्यर्धपलं च पिष्टं गुडपलोपेतमुष्णेन पयसा पिबेत् तद्वातगुल्मोदावर्तयोनिशूलानपोहति तथाक्षीरशृतेन महापञ्चमूलेन शिलाह्वयम् लशुनं तु क्षीरसिद्धं पीत्वा गुल्मोदावर्तगृध्रसीहृद्रोगविद्रधिशोषविषमज्वरान् जयति", text: "viḍvibandhe codāvartakramaṃ kuryāt luñcitatilapaladvayaṃ śuṇṭhyardhapalaṃ ca piṣṭaṃ guḍapalopetamuṣṇena payasā pibet tadvātagulmodāvartayoniśūlānapohati tathākṣīraśṛtena mahāpañcamūlena śilāhvayam laśunaṃ tu kṣīrasiddhaṃ pītvā gulmodāvartagṛdhrasīhṛdrogavidradhiśoṣaviṣamajvarān jayati" },
      { type: "verse", number: "17", sanskrit: "बृहतीद्वयबिल्वगोक्षुरकैरण्डमातुलुङ्गीमूलपाषाणभेदक्वाथः सयावशूको गुल्मशूलहरः माषपर्णीमुद्गपर्णीसहदेवाद्द्रस्वपञ्चमूलैरण्डेक्षुवालिकानिर्यूहो यवक्षारोपेतः सर्वगुल्मकोष्ठशूलघ्नः देवदारुनागरैरण्डपुष्करमूलानां क्वाथः सर्वगुल्मशूलघ्नः पुष्करमूलदुरालभायवशुण्ठीनां वा तैलारनालमूत्रमदिरायावशूकाश्चैकत्र पीता गुल्मोदरानाहप्लीहहराः स्वेदांश्च विविधान् पुनःपुनर्योजयेत्", text: "bṛhatīdvayabilvagokṣurakairaṇḍamātuluṅgīmūlapāṣāṇabhedakvāthaḥ sayāvaśūko gulmaśūlaharaḥ māṣaparṇīmudgaparṇīsahadevāddrasvapañcamūlairaṇḍekṣuvālikāniryūho yavakṣāropetaḥ sarvagulmakoṣṭhaśūlaghnaḥ devadārunāgarairaṇḍapuṣkaramūlānāṃ kvāthaḥ sarvagulmaśūlaghnaḥ puṣkaramūladurālabhāyavaśuṇṭhīnāṃ vā tailāranālamūtramadirāyāvaśūkāścaikatra pītā gulmodarānāhaplīhaharāḥ svedāṃśca vividhān punaḥpunaryojayet" },
      { type: "verse", number: "18", sanskrit: "स्रंसनार्थी नीलिनीफलचूर्णयुक्तानि पूर्वोक्तानि हवींषि पिबेत् अथवा रामठस्यैको भागः सैन्धवस्य त्रयो नवैरण्डतैलस्य सप्तविंशतिर्लशुनस्वरसस्य तदैकध्यं कृत्वा पीतमुदरगरगुल्मवर्ध्मप्लीहशूलहरम् नीलिनीबलाव्याघ्नीकटुकाफलतालपत्रिकारास्नाकृमिघ्नानि पालिकान्यपामाढके साधयित्वाष्टभागावशिष्टमवतारयेत् तेन स्नुहीक्षीरपलप्रतीवापं दधिसमं सर्पिःप्रस्थं पचेत् तत्पेयामण्डेन सह रसाशिना नीलिनीघृतं पलमात्रया पीतं गुल्मप्लीहकुष्ठश्वित्रजठरव्यङ्गशोफज्वरपाण्डुरोगोन्मादापस्मारानपकर्षति दुर्विरेच्यो हि सर्व एव गुल्मी मारुताभिभूतकोष्ठत्वात् तस्मात्सुस्निग्धमेनं स्नेहविरेकैर्वा शोधयेत्", text: "sraṃsanārthī nīlinīphalacūrṇayuktāni pūrvoktāni havīṃṣi pibet athavā rāmaṭhasyaiko bhāgaḥ saindhavasya trayo navairaṇḍatailasya saptaviṃśatirlaśunasvarasasya tadaikadhyaṃ kṛtvā pītamudaragaragulmavardhmaplīhaśūlaharam nīlinībalāvyāghnīkaṭukāphalatālapatrikārāsnākṛmighnāni pālikānyapāmāḍhake sādhayitvāṣṭabhāgāvaśiṣṭamavatārayet tena snuhīkṣīrapalapratīvāpaṃ dadhisamaṃ sarpiḥprasthaṃ pacet tatpeyāmaṇḍena saha rasāśinā nīlinīghṛtaṃ palamātrayā pītaṃ gulmaplīhakuṣṭhaśvitrajaṭharavyaṅgaśophajvarapāṇḍurogonmādāpasmārānapakarṣati durvirecyo hi sarva eva gulmī mārutābhibhūtakoṣṭhatvāt tasmātsusnigdhamenaṃ snehavirekairvā śodhayet" },
      { type: "verse", number: "19", sanskrit: "पित्तगुल्मे तु स्निग्धोष्णेन जाते स्रंसनार्थं मधुना कम्पिल्लकमवलिह्यात् द्राक्षाभयारसं वा सगुडं पिबेत् कल्पोदितानि वा विरेचनानि प्रयुञ्जीत", text: "pittagulme tu snigdhoṣṇena jāte sraṃsanārthaṃ madhunā kampillakamavalihyāt drākṣābhayārasaṃ vā saguḍaṃ pibet kalpoditāni vā virecanāni prayuñjīta" },
      { type: "verse", number: "20", sanskrit: "रूक्षोष्णसमुद्भूते पुनः संशमनार्थं तिक्तकं वासाघृतं वा पिबेत् अथवा तृणपञ्चमूलक्वाथेन जीवनीयकल्केन च सिद्धं सर्पिः तथा न्यग्रोधादिगणेन तृणपञ्चमूलादिभिर्वा पृथक् साधितं क्षीरम्", text: "rūkṣoṣṇasamudbhūte punaḥ saṃśamanārthaṃ tiktakaṃ vāsāghṛtaṃ vā pibet athavā tṛṇapañcamūlakvāthena jīvanīyakalkena ca siddhaṃ sarpiḥ tathā nyagrodhādigaṇena tṛṇapañcamūlādibhirvā pṛthak sādhitaṃ kṣīram" },
      { type: "verse", number: "21", sanskrit: "रूक्षोष्णजे ऽपि चात्ययिके सामान्यतो वा समुत्पन्ने विद्रधिविहितानां त्रिफलादिक्वाथत्रायमाणाघृतद्राक्षाघृतानामन्यतमं पिबेत् क्षीरं वा त्रायमाणाशृतं कोष्णं पीत्वा क्षीरमेव सुखोष्णमनुपिबेत्", text: "rūkṣoṣṇaje 'pi cātyayike sāmānyato vā samutpanne vidradhivihitānāṃ triphalādikvāthatrāyamāṇāghṛtadrākṣāghṛtānāmanyatamaṃ pibet kṣīraṃ vā trāyamāṇāśṛtaṃ koṣṇaṃ pītvā kṣīrameva sukhoṣṇamanupibet" },
      { type: "verse", number: "22", sanskrit: "पक्वाशयस्थे वा गुल्मे क्षीरबस्तिभिः सतिक्तैः संशोधयेत् शीतद्रव्यसिद्धैश्च स्नेहैरभ्यञ्जयेत् मणिकनकरजतताम्रभाजनानि च शिशिरवारिपूर्णानि गुल्मदेशस्योपरि धारयेन्मुक्तावलीश्च सुशीताः एवमसिद्धौ विदाहपूर्वरूपेषु चासृक् स्रावयेत् स्रुतरक्तं च जाङ्गलरसैर्लब्धबलमर्तिशेषनाशाय पुनः सर्पिरभ्यासयेत्", text: "pakvāśayasthe vā gulme kṣīrabastibhiḥ satiktaiḥ saṃśodhayet śītadravyasiddhaiśca snehairabhyañjayet maṇikanakarajatatāmrabhājanāni ca śiśiravāripūrṇāni gulmadeśasyopari dhārayenmuktāvalīśca suśītāḥ evamasiddhau vidāhapūrvarūpeṣu cāsṛk srāvayet srutaraktaṃ ca jāṅgalarasairlabdhabalamartiśeṣanāśāya punaḥ sarpirabhyāsayet" },
      { type: "verse", number: "23", sanskrit: "विद्रधिवच्च विदह्यमानमुपनाहयेत् पर्यागतमाप तद्वदुपलक्ष्य तथैव सर्वथोपचरेत्", text: "vidradhivacca vidahyamānamupanāhayet paryāgatamāpa tadvadupalakṣya tathaiva sarvathopacaret" },
      { type: "verse", number: "24", sanskrit: "श्लेष्मगुल्मिनं प्रागेव विधिवद्वामयेदवाम्यमुपवासयेत् लङ्घितस्योष्णकटुतिक्तदीपनं संसर्गमाचरेत् तथा स्वेदान् वातगुल्मोक्तानि च घृतादीनि द्विगुणहिङ्गुक्षाराम्लवेतसानि", text: "śleṣmagulminaṃ prāgeva vidhivadvāmayedavāmyamupavāsayet laṅghitasyoṣṇakaṭutiktadīpanaṃ saṃsargamācaret tathā svedān vātagulmoktāni ca ghṛtādīni dviguṇahiṅgukṣārāmlavetasāni" },
      { type: "verse", number: "25", sanskrit: "दशमूलक्वाथे व्योषदाडिमहिङ्गुयवक्षारबिडसैन्धवयुक्तं सर्पिः सिद्धं श्लेष्मगुल्मघ्नम् भल्लातकपलद्वयं लघुपञ्चमूलं च पालिकमुदकाढके प्रस्थावशेषं पाचयेत् तस्मिन् क्षीरप्रस्थे च सर्पिःप्रस्थं हिङ्गुविडङ्गशठीबिडसैन्धवक्षाररास्नानागरपिप्पलीषड्ग्रन्थामधुकचित्रकैः काषिकैर्विपचेत् एतद् भल्लातकघृतं कफगुल्मप्लीहकासश्वासग्रहणीपाण्डुरोगघ्नम् षट्पलं वा द्विगुणक्षारं क्षीररहितं मस्तुदधिकाञ्जिकार्द्रकरसाढकद्वयोपेतं साधयित्वा प्रयुञ्जीत हिङ्गुहरीतकीपुष्करमूलशुण्ठीसैन्धवबिडश्यामायवक्षारतुम्बुरुचूर्णो यवक्वाथाप्लुतः सर्पिर्भृष्टो भक्षितः शूलगुल्मकाठि न्यघ्नः", text: "daśamūlakvāthe vyoṣadāḍimahiṅguyavakṣārabiḍasaindhavayuktaṃ sarpiḥ siddhaṃ śleṣmagulmaghnam bhallātakapaladvayaṃ laghupañcamūlaṃ ca pālikamudakāḍhake prasthāvaśeṣaṃ pācayet tasmin kṣīraprasthe ca sarpiḥprasthaṃ hiṅguviḍaṅgaśaṭhībiḍasaindhavakṣārarāsnānāgarapippalīṣaḍgranthāmadhukacitrakaiḥ kāṣikairvipacet etad bhallātakaghṛtaṃ kaphagulmaplīhakāsaśvāsagrahaṇīpāṇḍurogaghnam ṣaṭpalaṃ vā dviguṇakṣāraṃ kṣīrarahitaṃ mastudadhikāñjikārdrakarasāḍhakadvayopetaṃ sādhayitvā prayuñjīta hiṅguharītakīpuṣkaramūlaśuṇṭhīsaindhavabiḍaśyāmāyavakṣāratumburucūrṇo yavakvāthāplutaḥ sarpirbhṛṣṭo bhakṣitaḥ śūlagulmakāṭhi nyaghnaḥ" },
      { type: "verse", number: "26", sanskrit: "ततो ऽस्य सर्वमङ्गं गुल्मं च साध्मानं सविबन्धं कठिनमुन्नतं गूढमांसं स्थिरं महावस्तुं च बहुधा बहुशश्च स्वेदयेत् स्निग्धस्विन्नशरीरस्य शिथिलतां गते गुल्मे यथोक्तां घटिकां लागयेत् तया सङ्गृहीते च गुल्मे घटीमपनयेत् भिन्द्याद्वा", text: "tato 'sya sarvamaṅgaṃ gulmaṃ ca sādhmānaṃ savibandhaṃ kaṭhinamunnataṃ gūḍhamāṃsaṃ sthiraṃ mahāvastuṃ ca bahudhā bahuśaśca svedayet snigdhasvinnaśarīrasya śithilatāṃ gate gulme yathoktāṃ ghaṭikāṃ lāgayet tayā saṅgṛhīte ca gulme ghaṭīmapanayet bhindyādvā" },
      { type: "verse", number: "27", sanskrit: "ततो हृदयमान्त्रं च वर्जयन् गुल्मं विमार्गाजपदादर्शान्यतमेन वस्त्रान्तरितं प्रपीडयेत् प्रमृज्यात् ततः साल्वलादिभिः सुखोष्णैर्लेपयित्वा लोहपात्रैः स्वेदयेत् एवममुना क्रमेण स्थानादपसृते शिथिलीभूते च गुल्मे विरेकान् स्नेहवतो दाशमूलिकांश्च ब्स्तीन् विदध्यात् नीलिनीघृतमेनं द्विगुणप्रमाणं पाययेत् उदरोक्तानि च सर्पींषि", text: "tato hṛdayamāntraṃ ca varjayan gulmaṃ vimārgājapadādarśānyatamena vastrāntaritaṃ prapīḍayet pramṛjyāt tataḥ sālvalādibhiḥ sukhoṣṇairlepayitvā lohapātraiḥ svedayet evamamunā krameṇa sthānādapasṛte śithilībhūte ca gulme virekān snehavato dāśamūlikāṃśca bstīn vidadhyāt nīlinīghṛtamenaṃ dviguṇapramāṇaṃ pāyayet udaroktāni ca sarpīṃṣi" },
      { type: "verse", number: "28", sanskrit: "त्रिफलाकुम्भनिकुम्भदशमूलानां षोडशांशावशिष्टं क्वाथं घृतमेरण्डतैलं क्षीरं चैकतः साधयेत् अयं मिश्रकस्नेहः कफगुल्मवातविड्विबन्धोदावर्तप्लीहोदरयोनिशूलान्यपकर्षति", text: "triphalākumbhanikumbhadaśamūlānāṃ ṣoḍaśāṃśāvaśiṣṭaṃ kvāthaṃ ghṛtameraṇḍatailaṃ kṣīraṃ caikataḥ sādhayet ayaṃ miśrakasnehaḥ kaphagulmavātaviḍvibandhodāvartaplīhodarayoniśūlānyapakarṣati" },
      { type: "verse", number: "29", sanskrit: "पिप्पल्यामलकद्राक्षाश्यामाद्यैः पालिकैरेरण्डतैलहविषोः प्रस्थौ षड्गुणे पयसि पचेदयं मिश्रकस्नेहो गुल्मिनां स्रंसनो वृद्धिविद्रधिगुल्मवातव्याधिषु च परममृतम्", text: "pippalyāmalakadrākṣāśyāmādyaiḥ pālikaireraṇḍatailahaviṣoḥ prasthau ṣaḍguṇe payasi pacedayaṃ miśrakasneho gulmināṃ sraṃsano vṛddhividradhigulmavātavyādhiṣu ca paramamṛtam" },
      { type: "verse", number: "30", sanskrit: "दन्त्याः पलानि पञ्चविंशतिस्तावन्त्येव चित्रकस्य तावत्य एव हरीतक्यः सर्वमेकत्र सलिलकलशे ऽष्टांशावशिष्टं साधयित्वा पूते च तस्मिन् रसे ताश्च हरीतकीः पञ्चविंशतिं गुडपलानि तैलार्धकुडवं चूर्णीकृतं त्रिवृताकुडवमर्धपलोन्मितां मागाधिकां महौषधं च प्रक्षिपेत् ततो मृद्वग्निना लेहीभूते ऽवतारिते शीते च तैलसमं मधु कर्षांशं च चतुर्जातकचूर्णं मिश्रयेत् एता दन्तीहरीतक्यः सावलेहाः पञ्चविंशत्यहोभिर्भक्ष्यमाणा गुल्मार्शःश्वयथुकुष्ठकामलारोचकग्रहणीपाण्डुहृद्रोगोत्क्लेशप्लीहोदरविषमज्वरानपोहन्ति हृद्यं सुखं च विरेचनम्", text: "dantyāḥ palāni pañcaviṃśatistāvantyeva citrakasya tāvatya eva harītakyaḥ sarvamekatra salilakalaśe 'ṣṭāṃśāvaśiṣṭaṃ sādhayitvā pūte ca tasmin rase tāśca harītakīḥ pañcaviṃśatiṃ guḍapalāni tailārdhakuḍavaṃ cūrṇīkṛtaṃ trivṛtākuḍavamardhapalonmitāṃ māgādhikāṃ mahauṣadhaṃ ca prakṣipet tato mṛdvagninā lehībhūte 'vatārite śīte ca tailasamaṃ madhu karṣāṃśaṃ ca caturjātakacūrṇaṃ miśrayet etā dantīharītakyaḥ sāvalehāḥ pañcaviṃśatyahobhirbhakṣyamāṇā gulmārśaḥśvayathukuṣṭhakāmalārocakagrahaṇīpāṇḍuhṛdrogotkleśaplīhodaraviṣamajvarānapohanti hṛdyaṃ sukhaṃ ca virecanam" },
      { type: "verse", number: "31", sanskrit: "गुडाक्षीरभावितं वा त्रिवृताचूर्णं सर्पिर्मधुभ्यामवलिह्यात् गुग्गुलुं वा गोमूत्रेण पिबेत् तेन वा श्यामात्रिवृत्कुष्ठदन्तीगुग्गुलुक्षारहरीतकीः पीलुरसं वा समधुसर्पिर्लवणम्", text: "guḍākṣīrabhāvitaṃ vā trivṛtācūrṇaṃ sarpirmadhubhyāmavalihyāt gugguluṃ vā gomūtreṇa pibet tena vā śyāmātrivṛtkuṣṭhadantīguggulukṣāraharītakīḥ pīlurasaṃ vā samadhusarpirlavaṇam" },
      { type: "verse", number: "32", sanskrit: "मूत्रबस्तिक्षारांश्च तांस्तांस्तत्र तत्रोक्तान् क्षीररसस्निग्धाहारो द्व्यहमेकाहं वा विश्राम्य प्रयुञ्जीत क्षारो हि श्लेष्माणं स्निग्धस्थिरं मधुरमाशयात् छिन्दन् क्षरयति", text: "mūtrabastikṣārāṃśca tāṃstāṃstatra tatroktān kṣīrarasasnigdhāhāro dvyahamekāhaṃ vā viśrāmya prayuñjīta kṣāro hi śleṣmāṇaṃ snigdhasthiraṃ madhuramāśayāt chindan kṣarayati" },
      { type: "verse", number: "33", sanskrit: "कफरुद्धमार्गशुध्यर्थं विविधांश्च चूर्णलवणतक्रारिष्टासवानवचारयेत् पिप्पलीपिप्पलीमूलसैन्धवाजाजीचित्रकचूर्णयुक्तां च जीर्णसुराम् अपि च", text: "kapharuddhamārgaśudhyarthaṃ vividhāṃśca cūrṇalavaṇatakrāriṣṭāsavānavacārayet pippalīpippalīmūlasaindhavājājīcitrakacūrṇayuktāṃ ca jīrṇasurām api ca" },
      { type: "verse", number: "34", sanskrit: "वमनैर्लङ्घनैः स्वेदैः सर्पिष्पानौर्विरेचनैः बस्तिभिर्गुटिकाचूर्णक्षारारिष्टासवैरपि", text: "vamanairlaṅghanaiḥ svedaiḥ sarpiṣpānaurvirecanaiḥ bastibhirguṭikācūrṇakṣārāriṣṭāsavairapi" },
      { type: "verse", number: "35", sanskrit: "श्लैष्मिकः कृतमूलत्वाद्यदि गुल्मो न शाम्यति तस्य दाहं हृते रक्ते कुर्यादन्ते शरादिभिः", text: "ślaiṣmikaḥ kṛtamūlatvādyadi gulmo na śāmyati tasya dāhaṃ hṛte rakte kuryādante śarādibhiḥ" },
      { type: "verse", number: "36", sanskrit: "अथ वस्त्रान्तरितं सपर्यन्तं गुल्मनिचयं प्रदीप्तेन शरलोहाग्निमन्थतिन्दुककाष्ठानामन्यतमेन नाभिबस्तिहृदयान्त्ररोमराजीः परिहरन् नातिगाढं परामृशेत् ततः कषायस्वादुशीतैरग्निवेगमुपशमय्य वर्णोपक्रमं कुर्वीत", text: "atha vastrāntaritaṃ saparyantaṃ gulmanicayaṃ pradīptena śaralohāgnimanthatindukakāṣṭhānāmanyatamena nābhibastihṛdayāntraromarājīḥ pariharan nātigāḍhaṃ parāmṛśet tataḥ kaṣāyasvāduśītairagnivegamupaśamayya varṇopakramaṃ kurvīta" },
      { type: "verse", number: "37", sanskrit: "व्यामिश्रदोषे तु व्यामिश्रमिदमेव यथोक्तं विदध्यात्", text: "vyāmiśradoṣe tu vyāmiśramidameva yathoktaṃ vidadhyāt" },
      { type: "verse", number: "38", sanskrit: "रक्तगुल्मे पुनरतीतप्रसवकालाया योषितः स्नेहस्वेदपूर्वकं स्नेहविरेचनं वितरेत् पलाशक्षारोदकसिद्धं च यमकम् गुल्मभेदनाय तीक्ष्णोष्णं च विधिम्", text: "raktagulme punaratītaprasavakālāyā yoṣitaḥ snehasvedapūrvakaṃ snehavirecanaṃ vitaret palāśakṣārodakasiddhaṃ ca yamakam gulmabhedanāya tīkṣṇoṣṇaṃ ca vidhim" },
      { type: "verse", number: "39", sanskrit: "एवमभिद्यमाने योनौ योनिविरेचनार्थं क्षारेण महावृक्षक्षीरेण वा युक्तं पललम् ताभ्यां वा भावितान् कटुकमत्स्यांस्तत्पित्तभावितान् वा वराहपित्तभावितान् वा नक्तकानूर्ध्वाधोभागिकद्रव्यभावितान् वा सगुडक्षारं किण्वं वा बस्तिं च सक्षारक्षीरमूत्रं दाशमूलिकमुत्तरबस्तिं च योजयेत्", text: "evamabhidyamāne yonau yonivirecanārthaṃ kṣāreṇa mahāvṛkṣakṣīreṇa vā yuktaṃ palalam tābhyāṃ vā bhāvitān kaṭukamatsyāṃstatpittabhāvitān vā varāhapittabhāvitān vā naktakānūrdhvādhobhāgikadravyabhāvitān vā saguḍakṣāraṃ kiṇvaṃ vā bastiṃ ca sakṣārakṣīramūtraṃ dāśamūlikamuttarabastiṃ ca yojayet" },
      { type: "verse", number: "40", sanskrit: "प्रवृत्तं तु रक्तं रसौदनाशिन्या उपेक्षेत अतिप्रवृत्तं तु रक्तं रक्तपित्तोपक्रमेण साधयेत्", text: "pravṛttaṃ tu raktaṃ rasaudanāśinyā upekṣeta atipravṛttaṃ tu raktaṃ raktapittopakrameṇa sādhayet" },
      { type: "verse", number: "41", sanskrit: "सर्वेषु चान्नपानस्वरूपज्ञो गुल्मेष्वाहारमग्निबलापेक्षी प्रयुञ्जीत", text: "sarveṣu cānnapānasvarūpajño gulmeṣvāhāramagnibalāpekṣī prayuñjīta" },
      { type: "verse", number: "42", sanskrit: "आनाहादिष्वप्यामशुद्धवातोदावर्तानुरोधेन गुल्मवत् प्रतिकुर्यादिति भवति चात्र", text: "ānāhādiṣvapyāmaśuddhavātodāvartānurodhena gulmavat pratikuryāditi bhavati cātra" },
      { type: "verse", number: "43", sanskrit: "मन्दे ऽग्नौ वर्धते गुल्मः प्रदीप्ते तु प्रशाम्यति शमप्रकोपौ दोषाणां सर्वेषां यत्तदाश्रयौ", text: "mande 'gnau vardhate gulmaḥ pradīpte tu praśāmyati śamaprakopau doṣāṇāṃ sarveṣāṃ yattadāśrayau" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 17,
    lang: "sa",
    content: [
      { type: "heading", heading: "Амавата чикитса — лечение ревматоидного артрита" },
      { type: "text", text: "Глава 17 Чикитса стханы — лечебный раздел о лечение ревматоидного артрита. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथात् उदरचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāt udaracikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सर्वमेवोदरमतिमात्रदोषसञ्चयानुबन्धेन स्रोतोमुखनिरोधाद्व्याकुलानिलतया यत् प्रजायते तस्मादभीक्ष्णमुदरी विरेचनान्युपयुञ्जीत मूत्रक्षीरान्यतरयुक्तमेरण्डतैलमहरहर्मासमेकं द्वौ वा क्षीराहारो वा गव्यं वा माहिषं वा मूत्रम् उष्ट्रीक्षीरवृत्तिर्वा स्यात्", text: "sarvamevodaramatimātradoṣasañcayānubandhena srotomukhanirodhādvyākulānilatayā yat prajāyate tasmādabhīkṣṇamudarī virecanānyupayuñjīta mūtrakṣīrānyatarayuktameraṇḍatailamaharaharmāsamekaṃ dvau vā kṣīrāhāro vā gavyaṃ vā māhiṣaṃ vā mūtram uṣṭrīkṣīravṛttirvā syāt" },
      { type: "verse", number: "3", sanskrit: "शोफशूलानाहतृण्मूर्च्छापरीतो विशेषेण पयो ऽनुपानं गोमूत्रेण प्राणदां पिबेत् पिप्पलीसहस्रं वा स्नुहीक्षीरभावितं सेवेत तद्भावितेन वा कृष्णाभयाचूर्णेन कासरम् सैन्धवाजमोदयुक्तं वा नैम्बं तैलम् अथवार्द्रकरसानुविद्धम् सिद्धं वा", text: "śophaśūlānāhatṛṇmūrcchāparīto viśeṣeṇa payo 'nupānaṃ gomūtreṇa prāṇadāṃ pibet pippalīsahasraṃ vā snuhīkṣīrabhāvitaṃ seveta tadbhāvitena vā kṛṣṇābhayācūrṇena kāsaram saindhavājamodayuktaṃ vā naimbaṃ tailam athavārdrakarasānuviddham siddhaṃ vā" },
      { type: "verse", number: "4", sanskrit: "हरीतकीचूर्णप्रस्थयुक्तमाढकं घृतस्याङ्गारेष्वभिविलाप्य खजेनाभिमथ्य सुगुप्तं यवपल्ले मासं स्थापयेत् ततश्चोद् वृत्य परिस्राव्य हरीतकीक्वाथाम्लदधिप्रतीवापं विपाचयेत्", text: "harītakīcūrṇaprasthayuktamāḍhakaṃ ghṛtasyāṅgāreṣvabhivilāpya khajenābhimathya suguptaṃ yavapalle māsaṃ sthāpayet tataścod vṛtya parisrāvya harītakīkvāthāmladadhipratīvāpaṃ vipācayet" },
      { type: "verse", number: "5", sanskrit: "अथवा गव्ये पयसि महावृक्षक्षीरमावाप्य विपाच्य शीतीभूतमभिमथ्य तं नवनीतं महावृक्षक्षीरेणैव सह साधयेत्", text: "athavā gavye payasi mahāvṛkṣakṣīramāvāpya vipācya śītībhūtamabhimathya taṃ navanītaṃ mahāvṛkṣakṣīreṇaiva saha sādhayet" },
      { type: "verse", number: "6", sanskrit: "अथवा चविकाचित्रकदन्त्यतिविषाकुष्ठसारिवाविडङ्गत्रिफलाकटुरोहिणीद्विहरिद्राशाङ्खिनीत्रिवृद्दीप्यकानर्धकार्षिकान् राजवृक्षफलमज्जाद्विपलं महावृक्षक्षीरद्विपलं गोमूत्रक्षीरघृतत्रिकुडवं चैकध्यं पाचयेत् विद्रध्यष्ठीलानाहकुष्ठोन्मादापस्मारान्निघ्नन्ति", text: "athavā cavikācitrakadantyativiṣākuṣṭhasārivāviḍaṅgatriphalākaṭurohiṇīdviharidrāśāṅkhinītrivṛddīpyakānardhakārṣikān rājavṛkṣaphalamajjādvipalaṃ mahāvṛkṣakṣīradvipalaṃ gomūtrakṣīraghṛtatrikuḍavaṃ caikadhyaṃ pācayet vidradhyaṣṭhīlānāhakuṣṭhonmādāpasmārānnighnanti" },
      { type: "verse", number: "7", sanskrit: "यावशूकपञ्चकोलकषट्पलेन वा मस्तुदशमूलक्वाथाढकद्वयेन च सिद्धं सर्पिःप्रस्थं प्रयोजयेत्", text: "yāvaśūkapañcakolakaṣaṭpalena vā mastudaśamūlakvāthāḍhakadvayena ca siddhaṃ sarpiḥprasthaṃ prayojayet" },
      { type: "verse", number: "8", sanskrit: "यवकोलकुलत्थपञ्चमूलकषायेण वा सुरासौवीरकयुक्तं सर्पिः", text: "yavakolakulatthapañcamūlakaṣāyeṇa vā surāsauvīrakayuktaṃ sarpiḥ" },
      { type: "verse", number: "9", sanskrit: "सर्पिष्पानस्रस्ते च दोषे बलवान् विरेचनार्थं मूत्रासवारिष्टसुराः स्नुहीक्षीरयुक्ताः शीलयेत् विरेचनद्रव्यकषायं नागरदेवदारुप्रगाढम् त्रिलवणादिचूर्णं वा द्वित्रिगुणानुलोमनद्रव्यम्", text: "sarpiṣpānasraste ca doṣe balavān virecanārthaṃ mūtrāsavāriṣṭasurāḥ snuhīkṣīrayuktāḥ śīlayet virecanadravyakaṣāyaṃ nāgaradevadārupragāḍham trilavaṇādicūrṇaṃ vā dvitriguṇānulomanadravyam" },
      { type: "verse", number: "10", sanskrit: "पटोलमूलरजनीविडङ्गत्रिफलाः कर्षांशाः कम्पिल्लकनीलिनीफलत्रिवृतानां क्रमाद् द्वित्रिचतुर्भिः कर्षैर्युक्ताश्चूर्णयित्वा मूत्रेण पिबेत् जीर्णे च पेयामण्डपो रसाशी वा स्यात् ततः षड्रात्रं सव्योषेण पयसाश्नीयात् ततः सप्तमे ऽहनि पुनश्चूर्णं पिबेत् अनेन विधिना चूर्णमिदमुदराणि जातोदकान्यपि निबर्हयति गुल्मभेदनानि च प्रयुञ्जीत", text: "paṭolamūlarajanīviḍaṅgatriphalāḥ karṣāṃśāḥ kampillakanīlinīphalatrivṛtānāṃ kramād dvitricaturbhiḥ karṣairyuktāścūrṇayitvā mūtreṇa pibet jīrṇe ca peyāmaṇḍapo rasāśī vā syāt tataḥ ṣaḍrātraṃ savyoṣeṇa payasāśnīyāt tataḥ saptame 'hani punaścūrṇaṃ pibet anena vidhinā cūrṇamidamudarāṇi jātodakānyapi nibarhayati gulmabhedanāni ca prayuñjīta" },
      { type: "verse", number: "11", sanskrit: "वमनविरेचनशिरोविरेचनवत्सकादिवचाहरिद्रादिवर्गद्रव्याणि पृथक्पालिकानि सूक्ष्मकल्कीकृतानि लवणानि च वज्रवृक्षक्षीरप्रस्थं च प्रक्षिप्य मूत्रगणे मृद्वग्निना घट्टयन् पाचयेत् अविदग्धकल्कं च तत्सिद्धमवतार्य शीतीभूतमङ्गुष्ठमात्रां गुटिकां वर्तयित्वा यथाबलं त्रिचतुरो मासानुपयोजयेत् एषा मूत्रवर्तिर्महारोगश्वासकासपीनसप्रसेकश्वयथुगुल्मपाण्डुकृमिकोष्ठारोचकाविपाकोदावर्तेषु परममगदम्", text: "vamanavirecanaśirovirecanavatsakādivacāharidrādivargadravyāṇi pṛthakpālikāni sūkṣmakalkīkṛtāni lavaṇāni ca vajravṛkṣakṣīraprasthaṃ ca prakṣipya mūtragaṇe mṛdvagninā ghaṭṭayan pācayet avidagdhakalkaṃ ca tatsiddhamavatārya śītībhūtamaṅguṣṭhamātrāṃ guṭikāṃ vartayitvā yathābalaṃ tricaturo māsānupayojayet eṣā mūtravartirmahārogaśvāsakāsapīnasaprasekaśvayathugulmapāṇḍukṛmikoṣṭhārocakāvipākodāvarteṣu paramamagadam" },
      { type: "verse", number: "12", sanskrit: "कृतविरेचनश्च क्षामदेहो ऽन्तरान्तरा क्षीरमौष्ट्रकं गव्यमाजं वा व्योषयुक्तं शीलयेत् दोषशेषविजयाय च शीलयेच्चविकानागरं क्षीरेण पिष्टम् सुरदारुचित्रकं वा सुरङ्गां वा पुनर्नवं वा त्रिफलादन्तीरौहीतकनिर्यूहं वा व्योषक्षारोपेतं तत् स्नुहीक्षीरघृतयुक्तम्", text: "kṛtavirecanaśca kṣāmadeho 'ntarāntarā kṣīramauṣṭrakaṃ gavyamājaṃ vā vyoṣayuktaṃ śīlayet doṣaśeṣavijayāya ca śīlayeccavikānāgaraṃ kṣīreṇa piṣṭam suradārucitrakaṃ vā suraṅgāṃ vā punarnavaṃ vā triphalādantīrauhītakaniryūhaṃ vā vyoṣakṣāropetaṃ tat snuhīkṣīraghṛtayuktam" },
      { type: "verse", number: "13", sanskrit: "पुराणमन्नं तक्रमरिष्टांश्च तांस्तान् क्षीरं च दन्तीचित्रकविडङ्गचविकात्रिकटुकोपेतम् तुल्यार्द्रकरसं वा क्षीरं शीलयेत् पिप्पलीवर्धमानां वा सेवेत शिलाजतु वा क्षीराशी गुग्गुलुं वा पुनः पुनश्च स्नेहयेद्विरेचयेच्च आत्ययिकांस्तु स्नेहविरेकैरेवोपक्रमेत सलिलं तु वर्जयेत् आनाहोदावर्तयोर्यथास्वं प्रतिकुर्वीत", text: "purāṇamannaṃ takramariṣṭāṃśca tāṃstān kṣīraṃ ca dantīcitrakaviḍaṅgacavikātrikaṭukopetam tulyārdrakarasaṃ vā kṣīraṃ śīlayet pippalīvardhamānāṃ vā seveta śilājatu vā kṣīrāśī gugguluṃ vā punaḥ punaśca snehayedvirecayecca ātyayikāṃstu snehavirekairevopakrameta salilaṃ tu varjayet ānāhodāvartayoryathāsvaṃ pratikurvīta" },
      { type: "verse", number: "14", sanskrit: "वातकृतेषु पार्श्वशूलोपस्तम्भहृद्ग्रहेषु बिल्वक्षाराम्भसा तैलं पाचयेत् स्योनाकाग्निमन्थतिलकुन्तलकदल्यपामार्गान्यतमक्षारेण वा विपक्वं तैलम्", text: "vātakṛteṣu pārśvaśūlopastambhahṛdgraheṣu bilvakṣārāmbhasā tailaṃ pācayet syonākāgnimanthatilakuntalakadalyapāmārgānyatamakṣāreṇa vā vipakvaṃ tailam" },
      { type: "verse", number: "15", sanskrit: "कफे पित्ते वा वातेनावृते ताभ्यां वा वाते बलवान् वातगुल्मोक्तक्रमेणैरण्डतैलं पिबेत्", text: "kaphe pitte vā vātenāvṛte tābhyāṃ vā vāte balavān vātagulmoktakrameṇairaṇḍatailaṃ pibet" },
      { type: "verse", number: "16", sanskrit: "लिम्पेच्च जठरमुदरिणां शिग्रुपलाशार्काश्वकर्णगजपिप्पलीदेवदारुभिर्मूत्रपिष्टैः सुखोष्णैः वृश्चिकालीकुष्ठषड्ग्रन्थाद्विपुनर्नवधान्यनागरपञ्चमूलक्वाथैर्मूत्रैश्च परिषेचयेत् प्रततमेव च स्वेदयेत्", text: "limpecca jaṭharamudariṇāṃ śigrupalāśārkāśvakarṇagajapippalīdevadārubhirmūtrapiṣṭaiḥ sukhoṣṇaiḥ vṛścikālīkuṣṭhaṣaḍgranthādvipunarnavadhānyanāgarapañcamūlakvāthairmūtraiśca pariṣecayet pratatameva ca svedayet" },
      { type: "verse", number: "17", sanskrit: "विरिक्तस्य चास्य सदा म्लानमुदरं साल्वलादिभिरुपनद्धं घनेन वाससा वेष्टयेत् एवमेनमनवकाशो वायुर्न पुनराध्मापयति तथापि पुनः सुविरिक्तस्याध्माने ऽम्ललवणान् सुस्निग्धान् निरूहान् दद्यात् सोपस्तम्भे तु वायौ तीक्ष्णोष्णान्", text: "viriktasya cāsya sadā mlānamudaraṃ sālvalādibhirupanaddhaṃ ghanena vāsasā veṣṭayet evamenamanavakāśo vāyurna punarādhmāpayati tathāpi punaḥ suviriktasyādhmāne 'mlalavaṇān susnigdhān nirūhān dadyāt sopastambhe tu vāyau tīkṣṇoṣṇān" },
      { type: "verse", number: "18", sanskrit: "अथ वातोदरिणं विदार्यादिसिद्धेन सर्पिषोपस्नेह्य स्वेदिताङ्गं तिल्वकघृतेन बहुशो ऽनुलोमयेत् कृतायां च संसर्ग्यां बलार्थं क्षीरमवचारयेत् निवर्तयेच्च प्रागुत्क्लेशात् क्रमेण ततो यूषरसादिभिर्मन्दाम्ललवणैः समिद्धानलमुदावर्तिनं पुनः स्निग्धस्विन्नमास्थापयेद्विदार्यादिक्वाथेन चित्राफलतैलप्रगाढेन तीक्ष्णोष्णाधोभागिकद्रव्ययुक्तेन वा दाशमूलिकेन", text: "atha vātodariṇaṃ vidāryādisiddhena sarpiṣopasnehya sveditāṅgaṃ tilvakaghṛtena bahuśo 'nulomayet kṛtāyāṃ ca saṃsargyāṃ balārthaṃ kṣīramavacārayet nivartayecca prāgutkleśāt krameṇa tato yūṣarasādibhirmandāmlalavaṇaiḥ samiddhānalamudāvartinaṃ punaḥ snigdhasvinnamāsthāpayedvidāryādikvāthena citrāphalatailapragāḍhena tīkṣṇoṣṇādhobhāgikadravyayuktena vā dāśamūlikena" },
      { type: "verse", number: "19", sanskrit: "दीप्ताग्निं च बद्धमलमस्थिसन्धित्रिकपार्श्वादिशूलस्फुरणाक्षेपयुक्तं रूक्षमनुवासयेद्वातहराम्लसिद्धाभ्यां तिलोरुबूकतैलाभ्याम् भोजयेच्चैनं जाङ्गलरसेन विदार्यादिशृतेन वा पयसा", text: "dīptāgniṃ ca baddhamalamasthisandhitrikapārśvādiśūlasphuraṇākṣepayuktaṃ rūkṣamanuvāsayedvātaharāmlasiddhābhyāṃ tilorubūkatailābhyām bhojayeccainaṃ jāṅgalarasena vidāryādiśṛtena vā payasā" },
      { type: "verse", number: "20", sanskrit: "सरलमधुशिग्रुमूलकबीजस्नेहाश्च पानाभ्यञ्जनेन शूलघ्नाः स्वेदयेच्चाभीक्ष्णं जठरम्", text: "saralamadhuśigrumūlakabījasnehāśca pānābhyañjanena śūlaghnāḥ svedayeccābhīkṣṇaṃ jaṭharam" },
      { type: "verse", number: "21", sanskrit: "अविरेच्यस्य तु पयःसर्पिर्यूषरसबस्त्यभ्यङ्गसमभक्तौषधैः संशमयेत्", text: "avirecyasya tu payaḥsarpiryūṣarasabastyabhyaṅgasamabhaktauṣadhaiḥ saṃśamayet" },
      { type: "verse", number: "22", sanskrit: "पित्तोदरिणं मधुरविपक्वेन सर्पिषोपस्नेह्य श्यामात्रिवृत्त्रिफलाविपक्वेनानुलोम्यैनं मधुघृतसिताढ्येन न्यग्रोधादिनिर्यूहेणास्थापयेदनुवासयेच्च", text: "pittodariṇaṃ madhuravipakvena sarpiṣopasnehya śyāmātrivṛttriphalāvipakvenānulomyainaṃ madhughṛtasitāḍhyena nyagrodhādiniryūheṇāsthāpayedanuvāsayecca" },
      { type: "verse", number: "23", sanskrit: "दुर्बलं तु प्रागेवानुवास्य क्षीरबस्तिभिः शोधयेत्", text: "durbalaṃ tu prāgevānuvāsya kṣīrabastibhiḥ śodhayet" },
      { type: "verse", number: "24", sanskrit: "सञ्जातबलाग्निं च स्निग्धं पुनःक्षीरेण सत्रिवृत्ककेनोरुबूकशृतेन वा सातलात्रायमाणाभ्यां वारग्वन्धेन वा सश्लेष्मणि पित्ते समूत्रेण सवाते तिक्तघृतान्वितेन पयसा पुनःपुनर्विरेचयेत् बस्तिकर्म चाचरेत्", text: "sañjātabalāgniṃ ca snigdhaṃ punaḥkṣīreṇa satrivṛtkakenorubūkaśṛtena vā sātalātrāyamāṇābhyāṃ vāragvandhena vā saśleṣmaṇi pitte samūtreṇa savāte tiktaghṛtānvitena payasā punaḥpunarvirecayet bastikarma cācaret" },
      { type: "verse", number: "25", sanskrit: "एभिरेव क्षीरैर्विदार्यादिशृतेन वा भोजयेत् पायसेन चोपनाहयेदुदरम्", text: "ebhireva kṣīrairvidāryādiśṛtena vā bhojayet pāyasena copanāhayedudaram" },
      { type: "verse", number: "26", sanskrit: "श्लेष्मोदरिणं वत्सकादिसिद्धेन सर्पिषोपस्नेह्य स्नुहीक्षीरविपक्वेनानुलोम्य कटुक्षारयुक्तैः कफहरैराहारैः संसर्ज्य त्रिकटुमूत्रतैलप्रगाढेन मुष्ककादिक्वाथेनास्थापयेदनुवासयेच्च कुलत्थयूषेण व्योषवता क्षीरेण वा भोजयेत् स्त्यानकफोदरं क्षारमरिष्टांश्च तीक्ष्णान् पाययेत् सततं च स्वेदयेत् किण्वसर्षपमूलकबीजकल्कैर्जठरमुपनाहयेत्", text: "śleṣmodariṇaṃ vatsakādisiddhena sarpiṣopasnehya snuhīkṣīravipakvenānulomya kaṭukṣārayuktaiḥ kaphaharairāhāraiḥ saṃsarjya trikaṭumūtratailapragāḍhena muṣkakādikvāthenāsthāpayedanuvāsayecca kulatthayūṣeṇa vyoṣavatā kṣīreṇa vā bhojayet styānakaphodaraṃ kṣāramariṣṭāṃśca tīkṣṇān pāyayet satataṃ ca svedayet kiṇvasarṣapamūlakabījakalkairjaṭharamupanāhayet" },
      { type: "verse", number: "27", sanskrit: "सान्निपातिकमुदरं प्रत्याख्याय चिकित्सेत् सर्वमेवेत्येके सर्वस्य सर्वात्मकत्वात् कृच्छ्रतमत्वाच्च दोषोद्रेकतस्तु प्रतिकुर्वीत", text: "sānnipātikamudaraṃ pratyākhyāya cikitset sarvamevetyeke sarvasya sarvātmakatvāt kṛcchratamatvācca doṣodrekatastu pratikurvīta" },
      { type: "verse", number: "28", sanskrit: "सप्तलाशङ्खिनीनिर्याससिद्धेन च सर्पिषा विरेचयेन्मासमर्धमासं वा महावृक्षक्षीरमूत्रसिद्धेन वा", text: "saptalāśaṅkhinīniryāsasiddhena ca sarpiṣā virecayenmāsamardhamāsaṃ vā mahāvṛkṣakṣīramūtrasiddhena vā" },
      { type: "verse", number: "29", sanskrit: "अथावाजगन्धाजशृङ्गीदन्तीद्रवन्तीस्वादुकण्टकपुनर्नवाझरसीवृश्चिकालीमूषिकपर्णीमहासहाक्षुद्रसहावृक्षादिनीभार्ङ्गीगृध्रनखीतण्डुलीयकदाडिममातुलुङ्गमूलक्वाथेन मदनफलैलाकुष्ठकुटिलरास्नाकल्कगोमूत्रसंसृष्टेन सैन्धवलवणितेनस्निग्धेनास्थापयेत्", text: "athāvājagandhājaśṛṅgīdantīdravantīsvādukaṇṭakapunarnavājharasīvṛścikālīmūṣikaparṇīmahāsahākṣudrasahāvṛkṣādinībhārṅgīgṛdhranakhītaṇḍulīyakadāḍimamātuluṅgamūlakvāthena madanaphalailākuṣṭhakuṭilarāsnākalkagomūtrasaṃsṛṣṭena saindhavalavaṇitenasnigdhenāsthāpayet" },
      { type: "verse", number: "30", sanskrit: "तथा चानुपशाम्यति निचयात्मके सर्वत्र च जठरे ज्ञातीनाश्राव्य मद्येनाश्वमारकगुञ्जाकाकादनीमूलकल्कं पाययेत् पानभोजनेषु वा विषं निक्षिपेत् इक्षुगण्डिकां वा भक्षयेत् कृष्णसर्पेण दंशयित्वा वल्लीफलानि वा मूलकं वा", text: "tathā cānupaśāmyati nicayātmake sarvatra ca jaṭhare jñātīnāśrāvya madyenāśvamārakaguñjākākādanīmūlakalkaṃ pāyayet pānabhojaneṣu vā viṣaṃ nikṣipet ikṣugaṇḍikāṃ vā bhakṣayet kṛṣṇasarpeṇa daṃśayitvā vallīphalāni vā mūlakaṃ vā" },
      { type: "verse", number: "31", sanskrit: "एवं ह्यस्य दोषसङ्घातः स्थिरो लीन उन्मार्गगो विषेणाशु प्रमाथिना विभिन्नो बहिः प्रवर्तते तेनागदतां व्रजति भवान्तरं वा", text: "evaṃ hyasya doṣasaṅghātaḥ sthiro līna unmārgago viṣeṇāśu pramāthinā vibhinno bahiḥ pravartate tenāgadatāṃ vrajati bhavāntaraṃ vā" },
      { type: "verse", number: "32", sanskrit: "हृतदोषं च शीताम्बुपरिषिक्तं क्षीरयवागूं पाययेत् ततस्त्रिवृद्वास्तुकमण्डूकपर्णीकालशाकयवशाकानामन्य तमं स्वरससाधितमनम्ललवणस्नेहं स्विन्नास्स्विन्नमनन्नभुङ्मासमेकमश्नीयात् तत्स्वरसमेव च तृषितः पिबेत् ततः शाकैर्निर्हृते दोषे परतो दुर्बलाय कारभं क्षीरं प्रयुञ्जीत", text: "hṛtadoṣaṃ ca śītāmbupariṣiktaṃ kṣīrayavāgūṃ pāyayet tatastrivṛdvāstukamaṇḍūkaparṇīkālaśākayavaśākānāmanya tamaṃ svarasasādhitamanamlalavaṇasnehaṃ svinnāssvinnamanannabhuṅmāsamekamaśnīyāt tatsvarasameva ca tṛṣitaḥ pibet tataḥ śākairnirhṛte doṣe parato durbalāya kārabhaṃ kṣīraṃ prayuñjīta" },
      { type: "verse", number: "33", sanskrit: "प्लीहोदरे यथादोषमुपस्निग्धस्विन्नस्य दध्ना भुक्तवतो वामबाहौ सिरां विध्येत् रुधिरस्यन्दनार्थं च पाणिना प्लीहानं विमर्दयेत् पुनश्च स्नेहपीतं विशुद्धदेहं समुद्रशुक्तिक्षारं पयसा पाययेत् हिङ्गु सुवर्चिकां वा पलाशक्षारोदकेन वा यवक्षारम्", text: "plīhodare yathādoṣamupasnigdhasvinnasya dadhnā bhuktavato vāmabāhau sirāṃ vidhyet rudhirasyandanārthaṃ ca pāṇinā plīhānaṃ vimardayet punaśca snehapītaṃ viśuddhadehaṃ samudraśuktikṣāraṃ payasā pāyayet hiṅgu suvarcikāṃ vā palāśakṣārodakena vā yavakṣāram" },
      { type: "verse", number: "34", sanskrit: "पारिजातकेक्ष्वाक्वपामार्गक्षारं वा तैलसंसृष्टम् सौभञ्जनकनिर्यूहं वा पिप्पलीचित्रकसैन्धवचूर्णयुक्तम् अम्लस्रुतं वा बिडमागधिकाढ्यं पूतिकरञ्जक्षारम् अग्निसादे तु त्रिलवणादिं क्षारानरिष्टांश्च पिबेत् घृतं षट्पलं महाषट्पलं रोहीतकषट्पलं वा", text: "pārijātakekṣvākvapāmārgakṣāraṃ vā tailasaṃsṛṣṭam saubhañjanakaniryūhaṃ vā pippalīcitrakasaindhavacūrṇayuktam amlasrutaṃ vā biḍamāgadhikāḍhyaṃ pūtikarañjakṣāram agnisāde tu trilavaṇādiṃ kṣārānariṣṭāṃśca pibet ghṛtaṃ ṣaṭpalaṃ mahāṣaṭpalaṃ rohītakaṣaṭpalaṃ vā" },
      { type: "verse", number: "35", sanskrit: "रोहीतकत्वक्पलानि पञ्चविंशतिं कोलप्रस्थद्वयं च तोये क्वाथयेत् तेन क्वाथेन तथा पालिकैः पञ्चकोलकैस्तैः सर्वैश्च तुल्यया रोहीतकत्वचा कल्कीकृतैर्घृतप्रस्थं साधयेत् तत् परं प्लीहहितम्", text: "rohītakatvakpalāni pañcaviṃśatiṃ kolaprasthadvayaṃ ca toye kvāthayet tena kvāthena tathā pālikaiḥ pañcakolakaistaiḥ sarvaiśca tulyayā rohītakatvacā kalkīkṛtairghṛtaprasthaṃ sādhayet tat paraṃ plīhahitam" },
      { type: "verse", number: "36", sanskrit: "रोहीतकलताः खण्डशः कल्पिताः हरीतकीश्च तोये गोमूत्रे वा सप्तरात्रमासुनुयात् स रसः प्लीहगुल्मोदरकृमिमेहकामलार्शांसि साधयति एवमनुपशाम्यत्यप्राप्तपिच्छोदके वातकफोल्बणे गुल्मविधिनाग्निकर्म कुर्यात्", text: "rohītakalatāḥ khaṇḍaśaḥ kalpitāḥ harītakīśca toye gomūtre vā saptarātramāsunuyāt sa rasaḥ plīhagulmodarakṛmimehakāmalārśāṃsi sādhayati evamanupaśāmyatyaprāptapicchodake vātakapholbaṇe gulmavidhināgnikarma kuryāt" },
      { type: "verse", number: "37", sanskrit: "पित्तोल्बणे तु जीवनीयघृतक्षीरबस्तिविरेचनानि प्रयुञ्जीत पुनःपुनश्च रुधिरमवसेचयेत् यकृदाख्ये ऽप्ययमेव क्रियाविभागः", text: "pittolbaṇe tu jīvanīyaghṛtakṣīrabastivirecanāni prayuñjīta punaḥpunaśca rudhiramavasecayet yakṛdākhye 'pyayameva kriyāvibhāgaḥ" },
      { type: "verse", number: "38", sanskrit: "बद्धोदरे स्विन्नाय सतैललवणमूत्रं तीक्ष्णं निरूहमनुवासनं च दद्यात् स्रंसनानि चान्नान्युदावर्तहराणि च तीक्ष्णं च विरेचनं यच्च किञ्चिद्वातघ्नम्", text: "baddhodare svinnāya satailalavaṇamūtraṃ tīkṣṇaṃ nirūhamanuvāsanaṃ ca dadyāt sraṃsanāni cānnānyudāvartaharāṇi ca tīkṣṇaṃ ca virecanaṃ yacca kiñcidvātaghnam" },
      { type: "verse", number: "39", sanskrit: "छिद्रोदरे स्वेदवर्ज्यं कफोदरवदाचरेत् दकोदरेतु पूर्वमुदकदोषहरणार्थं रूक्षतीक्ष्णौषधान् समूत्रान्निर्यूहचूर्णक्षारान् कफघ्नानि दीपनीयानि चान्नपानानि योजयेत्", text: "chidrodare svedavarjyaṃ kaphodaravadācaret dakodaretu pūrvamudakadoṣaharaṇārthaṃ rūkṣatīkṣṇauṣadhān samūtrānniryūhacūrṇakṣārān kaphaghnāni dīpanīyāni cānnapānāni yojayet" },
      { type: "verse", number: "40", sanskrit: "एवमसिद्धौ बद्धच्छिद्रदकोदरेष्वश्मर्यामिव सुहृदां प्रकाश्य शस्त्रमवचारयेत् तत्र बद्धच्छिद्रोदरयोः स्निग्धस्विन्नस्याधो नाभेश्चतुरङ्गुलानि वामतो ऽपहायोदरं पाटयित्वा चतुरङ्गुलप्रमाणमान्त्राणि निष्कास्य निरीक्ष्य बद्धगुदोदरस्यान्त्रप्रतिरोधकरं बालं मलोपलेपमश्मानं चापहरेत् परिस्राविणि शल्यमुद्धृत्यान्त्रपरिस्रावं विशोध्य तच्छिद्रं मर्कोटकैर्दंशयेत् लग्नेषु च शिरस्सु कायमपनयेत् ततो मधुघृताभ्यामभ्यज्यान्त्राणि यथास्थानं स्थापयित्वा बाह्यं व्रणमुदरस्य सीव्येत् यष्टीमधुकमिश्रया च कृष्णमृदा व्रणमभिलिप्य बध्नीयात् अथ निवातमागारं प्रवेश्य क्षीरवृत्तिं स्नेहद्रोण्यां वासयेत्", text: "evamasiddhau baddhacchidradakodareṣvaśmaryāmiva suhṛdāṃ prakāśya śastramavacārayet tatra baddhacchidrodarayoḥ snigdhasvinnasyādho nābheścaturaṅgulāni vāmato 'pahāyodaraṃ pāṭayitvā caturaṅgulapramāṇamāntrāṇi niṣkāsya nirīkṣya baddhagudodarasyāntrapratirodhakaraṃ bālaṃ malopalepamaśmānaṃ cāpaharet parisrāviṇi śalyamuddhṛtyāntraparisrāvaṃ viśodhya tacchidraṃ markoṭakairdaṃśayet lagneṣu ca śirassu kāyamapanayet tato madhughṛtābhyāmabhyajyāntrāṇi yathāsthānaṃ sthāpayitvā bāhyaṃ vraṇamudarasya sīvyet yaṣṭīmadhukamiśrayā ca kṛṣṇamṛdā vraṇamabhilipya badhnīyāt atha nivātamāgāraṃ praveśya kṣīravṛttiṃ snehadroṇyāṃ vāsayet" },
      { type: "verse", number: "41", sanskrit: "दकोदरे सवषु च जातोदकेषु जठरेषु वातहरतैलाभ्यक्तस्योष्णोदकस्विन्नस्याप्तैः परिगृहीतस्याकक्ष्यातः पटवेष्टितोदरस्याधो नाभेर्वामतश्चतुरङ्गुलमपहाय व्रीहिमुखेनाङ्गुष्ठोदरमात्रमवगाढं विध्वा नाडीं निधाय दोषोदकमर्धमात्रमवसिञ्चेत् ततोनाडीमुद्धृत्य तैललवणेनाभ्यज्य व्रणं बन्धनेनोपचरेत्", text: "dakodare savaṣu ca jātodakeṣu jaṭhareṣu vātaharatailābhyaktasyoṣṇodakasvinnasyāptaiḥ parigṛhītasyākakṣyātaḥ paṭaveṣṭitodarasyādho nābhervāmataścaturaṅgulamapahāya vrīhimukhenāṅguṣṭhodaramātramavagāḍhaṃ vidhvā nāḍīṃ nidhāya doṣodakamardhamātramavasiñcet tatonāḍīmuddhṛtya tailalavaṇenābhyajya vraṇaṃ bandhanenopacaret" },
      { type: "verse", number: "42", sanskrit: "सहसा सर्वस्निम् विस्राविते तृष्णा ज्वरो ऽङ्गमर्दो ऽतीसारः श्वासः कासः पाददाहो वा जायते पूर्यते च सुतराम् अतस्तृतीयचतुर्थपञ्चमषष्ठाष्टमद्वादशषोडशरात्राणामन्यतममन्तरं कृत्वा दोषोदकमल्पशो विस्रावयेत् निस्रुते च दोषोदके विमृद्योदरमाविककौशेयचर्मणामन्यतरेण गाढतरं वेष्टयेत् तथा नाध्मापयति वायुः लङ्घयित्वा च यवागूमल्पस्नेहलवणां मात्रया पाययेत् ततः परं षण्मासान् क्षीरवृत्तिर्भवेत् ततो मासत्रयं क्षीरपेयां पिबेत् अन्यच्च मासत्रयमल्पलवणमल्पक्षीरं श्यामाकं कोरदूषं वा भुञ्जीतेति भवति चात्र", text: "sahasā sarvasnim visrāvite tṛṣṇā jvaro 'ṅgamardo 'tīsāraḥ śvāsaḥ kāsaḥ pādadāho vā jāyate pūryate ca sutarām atastṛtīyacaturthapañcamaṣaṣṭhāṣṭamadvādaśaṣoḍaśarātrāṇāmanyatamamantaraṃ kṛtvā doṣodakamalpaśo visrāvayet nisrute ca doṣodake vimṛdyodaramāvikakauśeyacarmaṇāmanyatareṇa gāḍhataraṃ veṣṭayet tathā nādhmāpayati vāyuḥ laṅghayitvā ca yavāgūmalpasnehalavaṇāṃ mātrayā pāyayet tataḥ paraṃ ṣaṇmāsān kṣīravṛttirbhavet tato māsatrayaṃ kṣīrapeyāṃ pibet anyacca māsatrayamalpalavaṇamalpakṣīraṃ śyāmākaṃ koradūṣaṃ vā bhuñjīteti bhavati cātra" },
      { type: "verse", number: "43", sanskrit: "प्रयतो वत्सरेणैवं विजयेत जलोदरम् वर्ज्येषु यन्त्रितो दिष्टे नात्यदिष्टे जितेन्द्रियः", text: "prayato vatsareṇaivaṃ vijayeta jalodaram varjyeṣu yantrito diṣṭe nātyadiṣṭe jitendriyaḥ" },
      { type: "verse", number: "44", sanskrit: "सर्वमेवोदरं प्रायो दोषसङ्घातजं यतः अतो वातादिशमनी क्रिया सर्वत्र शस्यते", text: "sarvamevodaraṃ prāyo doṣasaṅghātajaṃ yataḥ ato vātādiśamanī kriyā sarvatra śasyate" },
      { type: "verse", number: "45", sanskrit: "वह्निर्मन्दत्वमायाति दोषैः कुक्षौ प्रपूरिते तस्मात् भोज्यानि योज्यानि दीपनानि लघूनि च", text: "vahnirmandatvamāyāti doṣaiḥ kukṣau prapūrite tasmāt bhojyāni yojyāni dīpanāni laghūni ca" },
      { type: "verse", number: "46", sanskrit: "सपञ्चमूलान्यल्पाम्लपटुस्नेहकटूनि च भावितानां गवां मूत्रे षष्टिकानां च तण्डुलैः", text: "sapañcamūlānyalpāmlapaṭusnehakaṭūni ca bhāvitānāṃ gavāṃ mūtre ṣaṣṭikānāṃ ca taṇḍulaiḥ" },
      { type: "verse", number: "47", sanskrit: "यवागूं पयसा सिद्धां प्रकामं भोजयेन्नरम् पिबेदिक्षुरसं चानु जठराणां निवृत्तये", text: "yavāgūṃ payasā siddhāṃ prakāmaṃ bhojayennaram pibedikṣurasaṃ cānu jaṭharāṇāṃ nivṛttaye" },
      { type: "verse", number: "48", sanskrit: "स्वं स्वं स्थानं व्रजन्त्येषां वातपित्तकफास्तथा अत्यर्थोष्णाम्ललवणं रूक्षं ग्राहि हिमं गुरु", text: "svaṃ svaṃ sthānaṃ vrajantyeṣāṃ vātapittakaphāstathā atyarthoṣṇāmlalavaṇaṃ rūkṣaṃ grāhi himaṃ guru" },
      { type: "verse", number: "49", sanskrit: "गुडं तिलकृतं शाकं वारि पानावगाहयोः आयासाध्वदिवास्वप्नयानयानानि च त्यजेत्", text: "guḍaṃ tilakṛtaṃ śākaṃ vāri pānāvagāhayoḥ āyāsādhvadivāsvapnayānayānāni ca tyajet" },
      { type: "verse", number: "50", sanskrit: "नात्यच्छसान्द्रमधुरं पान तक्रं प्रशस्यते सकणालवणं वाते पित्ते सोषणशर्करम्", text: "nātyacchasāndramadhuraṃ pāna takraṃ praśasyate sakaṇālavaṇaṃ vāte pitte soṣaṇaśarkaram" },
      { type: "verse", number: "51", sanskrit: "यवनीसैन्धवाजाजीमधुव्योषैः कफोदरे त्र्यूषणक्षारलवणैः संयुक्तं निचयोदरे", text: "yavanīsaindhavājājīmadhuvyoṣaiḥ kaphodare tryūṣaṇakṣāralavaṇaiḥ saṃyuktaṃ nicayodare" },
      { type: "verse", number: "52", sanskrit: "मधुतैलवचाशुण्ठीशताह्वाकुष्ठसैन्धवैः प्लीह्नि बद्धे तु हपुषायवानीपट्वजाजिभिः", text: "madhutailavacāśuṇṭhīśatāhvākuṣṭhasaindhavaiḥ plīhni baddhe tu hapuṣāyavānīpaṭvajājibhiḥ" },
      { type: "verse", number: "53", sanskrit: "सकृष्णामाक्षिकं छिद्रे व्योषवत्सलिलोदरे गौरवारोचकानाहमन्दवह्न्यतिसारिणाम् तक्रं वातकफार्तानाममृतत्वाय कल्पते", text: "sakṛṣṇāmākṣikaṃ chidre vyoṣavatsalilodare gauravārocakānāhamandavahnyatisāriṇām takraṃ vātakaphārtānāmamṛtatvāya kalpate" },
      { type: "verse", number: "54", sanskrit: "प्रयोगाणां च सर्वेषामनु क्षीरं प्रयोजयेत् स्थैर्यकृत् सर्वधातूनां बल्यं दोषानुबन्धहृत् भेषजापचिताङ्गानां क्षीरमेवामृतायते", text: "prayogāṇāṃ ca sarveṣāmanu kṣīraṃ prayojayet sthairyakṛt sarvadhātūnāṃ balyaṃ doṣānubandhahṛt bheṣajāpacitāṅgānāṃ kṣīramevāmṛtāyate" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 18,
    lang: "sa",
    content: [
      { type: "heading", heading: "Унмада чикитса — лечение психоза" },
      { type: "text", text: "Глава 18 Чикитса стханы — лечебный раздел о лечение психоза. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातः पाण्डुरोगचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ pāṇḍurogacikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "पाण्ड्वामयिनमादौ कल्याणकपञ्चगव्यतिक्तकानामन्यतमं सर्पिः पाययेत् दाडिमसारतः कुडवं धान्यकार्धकुडवं पिप्पल्यष्टमिकां शुण्ठीचित्रकयोश्च पलं पलमेकतः कल्कीकृत्य तोयाढके विंशतिपलं घृतस्य सिद्धं हृत्पाण्डुरोगगुल्मप्लीहार्शःश्वासकासमूढवातवातकफार्तिहरमग्निदीपनं वन्ध्यानां सम्मतं दुःखप्रसविनीनां च", text: "pāṇḍvāmayinamādau kalyāṇakapañcagavyatiktakānāmanyatamaṃ sarpiḥ pāyayet dāḍimasārataḥ kuḍavaṃ dhānyakārdhakuḍavaṃ pippalyaṣṭamikāṃ śuṇṭhīcitrakayośca palaṃ palamekataḥ kalkīkṛtya toyāḍhake viṃśatipalaṃ ghṛtasya siddhaṃ hṛtpāṇḍurogagulmaplīhārśaḥśvāsakāsamūḍhavātavātakaphārtiharamagnidīpanaṃ vandhyānāṃ sammataṃ duḥkhaprasavinīnāṃ ca" },
      { type: "verse", number: "3", sanskrit: "दुरालभाचन्दनपटोलत्रायमाणागुडूचीकिराततिक्तरोहिणीघननिशाद्वयेन्द्रयवदेवदारुपर्पटकाजमोदैः कार्षिकैः क्षीराढके घृतप्रस्थं साधयेत् पाण्डुरोगकामलारक्तपित्तज्वरदाहासृग्दरविस्फोटश्वयथुभगन्दरार्णोघ्नम्", text: "durālabhācandanapaṭolatrāyamāṇāguḍūcīkirātatiktarohiṇīghananiśādvayendrayavadevadāruparpaṭakājamodaiḥ kārṣikaiḥ kṣīrāḍhake ghṛtaprasthaṃ sādhayet pāṇḍurogakāmalāraktapittajvaradāhāsṛgdaravisphoṭaśvayathubhagandarārṇoghnam" },
      { type: "verse", number: "4", sanskrit: "स्निग्धं चैनं तीक्ष्णिर्वामयेत् पुनश्च स्निग्धं मूत्रयुक्तं गव्यं माहिषं वार्धमासं पयः पाययेत् मागधिकाशृतं वा मूत्रसिद्धां वा त्रिफलाम् सप्ताहं मूत्रेण वा हरीतकीः कल्किताः स्वर्णक्षीरीभद्रद्रारुनागरश्यामात्रिवृन्मूलानि तेनैव वा क्वथितानि एभिर्वा शृतं पयः", text: "snigdhaṃ cainaṃ tīkṣṇirvāmayet punaśca snigdhaṃ mūtrayuktaṃ gavyaṃ māhiṣaṃ vārdhamāsaṃ payaḥ pāyayet māgadhikāśṛtaṃ vā mūtrasiddhāṃ vā triphalām saptāhaṃ mūtreṇa vā harītakīḥ kalkitāḥ svarṇakṣīrībhadradrārunāgaraśyāmātrivṛnmūlāni tenaiva vā kvathitāni ebhirvā śṛtaṃ payaḥ" },
      { type: "verse", number: "5", sanskrit: "वत्सकबीजविशालाकुष्ठकटुकादारुमुस्तानां समा भागाः मूर्वाभागद्वयमतिविषाभागार्धं च चूर्णितं सुखाम्बुना पीत्वा क्षौद्रमनुलिह्यात् एतत् पाण्डुकामलाज्व्रारुचिगुल्मानाहामवातरक्तपित्तकासश्वासानपोहति", text: "vatsakabījaviśālākuṣṭhakaṭukādārumustānāṃ samā bhāgāḥ mūrvābhāgadvayamativiṣābhāgārdhaṃ ca cūrṇitaṃ sukhāmbunā pītvā kṣaudramanulihyāt etat pāṇḍukāmalājvrārucigulmānāhāmavātaraktapittakāsaśvāsānapohati" },
      { type: "verse", number: "6", sanskrit: "त्रिकटुककालतिललोहैर्वा माक्षिकधातुतुल्यैर्माक्षिकेणवटकाव्योषकाग्निविडङ्गभागा नव नव चायसचूर्णभागा मधुघृताभ्यां तक्रेणोष्णोदकेन वोपयुक्ता हृत्पाण्डुरोगकामलाकुष्ठार्शःशोफोदरप्लीहमेहहराः", text: "trikaṭukakālatilalohairvā mākṣikadhātutulyairmākṣikeṇavaṭakāvyoṣakāgniviḍaṅgabhāgā nava nava cāyasacūrṇabhāgā madhughṛtābhyāṃ takreṇoṣṇodakena vopayuktā hṛtpāṇḍurogakāmalākuṣṭhārśaḥśophodaraplīhamehaharāḥ" },
      { type: "verse", number: "7", sanskrit: "माक्षिकधातुचविकादारुदार्वीत्वग्ग्रन्थिकान् त्रिफलादीनि च नव विचूर्ण्य चूर्णाद्द्विगुणं च सुश्लक्ष्णं पृथङ्मण्डूरं ततो गोमूत्रं सर्वतो ऽष्टगुणं पक्त्वा तस्मिंस्तत् क्षिपेत् अनन्तरं च वटकान् कुर्यात् ते तक्रानुपानमभ्यस्ताः परमौषधं पाण्ड्वामयिनां शोफार्शःकुष्ठकामलामेहप्लीहाढ्यवातकफार्तानां च", text: "mākṣikadhātucavikādārudārvītvaggranthikān triphalādīni ca nava vicūrṇya cūrṇāddviguṇaṃ ca suślakṣṇaṃ pṛthaṅmaṇḍūraṃ tato gomūtraṃ sarvato 'ṣṭaguṇaṃ paktvā tasmiṃstat kṣipet anantaraṃ ca vaṭakān kuryāt te takrānupānamabhyastāḥ paramauṣadhaṃ pāṇḍvāmayināṃ śophārśaḥkuṣṭhakāmalāmehaplīhāḍhyavātakaphārtānāṃ ca" },
      { type: "verse", number: "8", sanskrit: "शिलाजतुताप्यरूप्यायोमलाः पृथक् पञ्चपलिकास्त्रिफलादयश्च विगतघनाः पलांशाः श्लक्ष्णरजसः सितोपलापलाष्टकयुक्ताः क्षौद्रद्रुता योगराजः कुलत्थादियूषाशिना यथाग्न्यभ्यवहृतः समानः पूर्वेण यक्ष्मविषविषज्वरकासश्वासापस्मारहरश्च", text: "śilājatutāpyarūpyāyomalāḥ pṛthak pañcapalikāstriphalādayaśca vigataghanāḥ palāṃśāḥ ślakṣṇarajasaḥ sitopalāpalāṣṭakayuktāḥ kṣaudradrutā yogarājaḥ kulatthādiyūṣāśinā yathāgnyabhyavahṛtaḥ samānaḥ pūrveṇa yakṣmaviṣaviṣajvarakāsaśvāsāpasmāraharaśca" },
      { type: "verse", number: "9", sanskrit: "त्रिफलाकुटजफलघनपटोलपिचुमन्दमहौषधकषायैर्मासमर्धमासं वा भावितान्यष्टौ शिलाह्वयपलानि समसितान्युपकुल्यातुगाक्षीरीधात्रीफलकर्कटकशृङ्ग्यः पृथक् पलांशाः निदिग्धिकाफलमूलयोः पलं त्रिजातकत्रिकर्षं च क्षौद्रत्रिपलयुक्तान् वटकान् वर्तयेत् ते दाडिमाम्बुक्षीररससलिलसुरासवान्यतमानुपाना वज्राभिधाना वज्रमिवानन्तरोक्तान् रोगान् दारयन्ति हृद्रोगगलरोगगरोदरासृग्दरभगन्दरगुल्मवर्ध्मशुक्रमूत्रदोषांश्च", text: "triphalākuṭajaphalaghanapaṭolapicumandamahauṣadhakaṣāyairmāsamardhamāsaṃ vā bhāvitānyaṣṭau śilāhvayapalāni samasitānyupakulyātugākṣīrīdhātrīphalakarkaṭakaśṛṅgyaḥ pṛthak palāṃśāḥ nidigdhikāphalamūlayoḥ palaṃ trijātakatrikarṣaṃ ca kṣaudratripalayuktān vaṭakān vartayet te dāḍimāmbukṣīrarasasalilasurāsavānyatamānupānā vajrābhidhānā vajramivānantaroktān rogān dārayanti hṛdrogagalarogagarodarāsṛgdarabhagandaragulmavardhmaśukramūtradoṣāṃśca" },
      { type: "verse", number: "10", sanskrit: "द्राक्षापिप्पलीप्रस्थद्वयं शर्करार्धतुलां तवक्षीरीनागरमधुकानि च द्विपलिकानि चूर्णयित्वामलकरसद्रोणे प्रक्षिप्य मृद्वग्निना पचेत् लेहीभूते शीते च तस्मिन् मधुप्रस्थमावपेत् त्रिसुगन्धिकस्य कर्षत्रयं च चूर्णीकृत्य दर्व्या परिघट्य जातीपुष्पादिवासिते मृद्भाण्डे निदध्यात् अयं द्राक्षालेह उपयुज्यमानः पाण्ड्वामयहृद्रोगकामलाहलीमकज्वरगुल्मोदरशोफोदावर्तादीनपरानपि विरेकसाध्यान् व्याधीन् प्रसह्य वायुरिवाभ्राण्यपहरति", text: "drākṣāpippalīprasthadvayaṃ śarkarārdhatulāṃ tavakṣīrīnāgaramadhukāni ca dvipalikāni cūrṇayitvāmalakarasadroṇe prakṣipya mṛdvagninā pacet lehībhūte śīte ca tasmin madhuprasthamāvapet trisugandhikasya karṣatrayaṃ ca cūrṇīkṛtya darvyā parighaṭya jātīpuṣpādivāsite mṛdbhāṇḍe nidadhyāt ayaṃ drākṣāleha upayujyamānaḥ pāṇḍvāmayahṛdrogakāmalāhalīmakajvaragulmodaraśophodāvartādīnaparānapi virekasādhyān vyādhīn prasahya vāyurivābhrāṇyapaharati" },
      { type: "verse", number: "11", sanskrit: "भोजनं तु सात्म्यतः शालियवगोधूममुद्गजाङ्गलमांसानि पयो घृतं वृषपटोलवेतपर्पटशाकं द्राक्षादाडिमखर्जूरामलकरसानि पानमनुपञ्चमूलसिद्धं वारि वाताधिके घनद्रीबेरशुण्ठीसाधितं पित्तोत्तरे श्लेष्मण्यरिष्टसीधुमार्द्वीकासवाः सर्वत्र वा तक्रम्", text: "bhojanaṃ tu sātmyataḥ śāliyavagodhūmamudgajāṅgalamāṃsāni payo ghṛtaṃ vṛṣapaṭolavetaparpaṭaśākaṃ drākṣādāḍimakharjūrāmalakarasāni pānamanupañcamūlasiddhaṃ vāri vātādhike ghanadrīberaśuṇṭhīsādhitaṃ pittottare śleṣmaṇyariṣṭasīdhumārdvīkāsavāḥ sarvatra vā takram" },
      { type: "verse", number: "12", sanskrit: "बीजकसारप्रस्थम् वरायाः पलानि पञ्चविंशतिः पञ्च द्राक्षाया बलायाः सप्त जलद्रोणे पक्त्वा पादशेषं तेभ्यो रसमादाय पूतशीते ऽस्मिन् शर्करातुलां मधुप्रस्थं कर्षांशानि च चूर्णितानि व्योषव्याघ्रनखोशीरक्रमुकैलावालुककुष्ठमधुकानि निक्षिप्य घृतभाजने सर्वमैकध्यं यवपल्ले ग्रीष्मे दशरात्रं विंशतिरात्रं शीते स्थापयेत् अयं बीजकसारारिष्टः पाण्डुकामलामेहहृद्रोगवातशोणितविषमज्वरारोचककासश्वासान् निबर्हति", text: "bījakasāraprastham varāyāḥ palāni pañcaviṃśatiḥ pañca drākṣāyā balāyāḥ sapta jaladroṇe paktvā pādaśeṣaṃ tebhyo rasamādāya pūtaśīte 'smin śarkarātulāṃ madhuprasthaṃ karṣāṃśāni ca cūrṇitāni vyoṣavyāghranakhośīrakramukailāvālukakuṣṭhamadhukāni nikṣipya ghṛtabhājane sarvamaikadhyaṃ yavapalle grīṣme daśarātraṃ viṃśatirātraṃ śīte sthāpayet ayaṃ bījakasārāriṣṭaḥ pāṇḍukāmalāmehahṛdrogavātaśoṇitaviṣamajvarārocakakāsaśvāsān nibarhati" },
      { type: "verse", number: "13", sanskrit: "गण्डीरतरोः समूलपुष्पशाखस्य तुलामाहरेत् अर्धतुलां दशमूलस्य त्रिफलायाः पृथगर्धप्रस्थ कुटजत्वचश्च कुडवांशान् मुस्तारुष्करकृमिघ्नेन्द्रयवान् पालिकान् पाठादन्तीमधुरसारास्नाशठीचित्रकान् मृद्वीकार्धप्रस्थं च षोडशगुणे पादशेषमम्भसि विपाच्य रसमाददीत तं पूतशीतं सितोपलातुलाद्वयेन लोहचूर्णप्रस्थेन च युक्तं मागधिकार्धप्रस्थेन श्लक्ष्णपिष्टेन ग्रन्थिकपलेनार्धपलिकैश्च मरिचविडङ्गैलवालुकैः प्रलिप्ते घृतकुम्भे निधापयेत् मासमात्रं स्थितो ऽयं गण्डीरारिष्टो ऽधिकगुणः पूर्वस्मात् ग्रन्थ्यर्बुदकृमिहरश्च", text: "gaṇḍīrataroḥ samūlapuṣpaśākhasya tulāmāharet ardhatulāṃ daśamūlasya triphalāyāḥ pṛthagardhaprastha kuṭajatvacaśca kuḍavāṃśān mustāruṣkarakṛmighnendrayavān pālikān pāṭhādantīmadhurasārāsnāśaṭhīcitrakān mṛdvīkārdhaprasthaṃ ca ṣoḍaśaguṇe pādaśeṣamambhasi vipācya rasamādadīta taṃ pūtaśītaṃ sitopalātulādvayena lohacūrṇaprasthena ca yuktaṃ māgadhikārdhaprasthena ślakṣṇapiṣṭena granthikapalenārdhapalikaiśca maricaviḍaṅgailavālukaiḥ pralipte ghṛtakumbhe nidhāpayet māsamātraṃ sthito 'yaṃ gaṇḍīrāriṣṭo 'dhikaguṇaḥ pūrvasmāt granthyarbudakṛmiharaśca" },
      { type: "verse", number: "14", sanskrit: "अथवा चव्यकुष्ठचित्रकप्रलिप्ते भाजने मस्तुद्रोणं गुडतुलां पिप्पलीप्रस्थत्रयं त्रिफलाप्रस्थत्रयं विडङ्गप्रस्थत्रयं कुडवांशांश्च मरिचपरूषकद्राक्षाकाश्मर्यफलेन्द्रयवान् द्विपलिकानि च दन्तीचित्रकभल्लातकानि चूर्णितानि प्रक्षिपेत् ततो यवपल्लस्थं पक्षमुपेक्ष्य यथाबलं पिबेत् एष मस्त्वरिष्टः पाण्डुरोगमेहस्थौल्यमेदोर्शोग्रहणीप्लीहशोफोदरभगन्दरहरः परमं चाग्निदीपन इति", text: "athavā cavyakuṣṭhacitrakapralipte bhājane mastudroṇaṃ guḍatulāṃ pippalīprasthatrayaṃ triphalāprasthatrayaṃ viḍaṅgaprasthatrayaṃ kuḍavāṃśāṃśca maricaparūṣakadrākṣākāśmaryaphalendrayavān dvipalikāni ca dantīcitrakabhallātakāni cūrṇitāni prakṣipet tato yavapallasthaṃ pakṣamupekṣya yathābalaṃ pibet eṣa mastvariṣṭaḥ pāṇḍurogamehasthaulyamedorśograhaṇīplīhaśophodarabhagandaraharaḥ paramaṃ cāgnidīpana iti" },
      { type: "verse", number: "15", sanskrit: "भवति चात्र पाण्डुरोगप्रशान्त्यर्थं विहितं यच्चिकित्सितम् विकल्प्यमेतद्विदुषा पृथग्दोषबलं प्रति", text: "bhavati cātra pāṇḍurogapraśāntyarthaṃ vihitaṃ yaccikitsitam vikalpyametadviduṣā pṛthagdoṣabalaṃ prati" },
      { type: "verse", number: "16", sanskrit: "स्नेहप्रायं पवनजे तिक्तशीतं तु पत्तिके श्लैष्मिके कटुरूक्षोष्णं विमिश्रं सान्निपातिके", text: "snehaprāyaṃ pavanaje tiktaśītaṃ tu pattike ślaiṣmike kaṭurūkṣoṣṇaṃ vimiśraṃ sānnipātike" },
      { type: "verse", number: "17", sanskrit: "मृदं निर्घातयेत् कायात्तीक्ष्णैः संशोधनैः पुरः बलाधानानि सर्पींषि शुद्धे कोष्ठे तु योजयेत्", text: "mṛdaṃ nirghātayet kāyāttīkṣṇaiḥ saṃśodhanaiḥ puraḥ balādhānāni sarpīṃṣi śuddhe koṣṭhe tu yojayet" },
      { type: "verse", number: "18", sanskrit: "व्योषबिल्वद्विरजनीत्रिफलाद्विपुनर्नवम् मुस्तान्ययोरजः पाठा विडङ्गं देवदारु च", text: "vyoṣabilvadvirajanītriphalādvipunarnavam mustānyayorajaḥ pāṭhā viḍaṅgaṃ devadāru ca" },
      { type: "verse", number: "19", sanskrit: "वृश्चिकाली च भार्ङ्गी च सक्षीरैस्तैः शृतं घृतम् सर्वान् प्रशमयत्याशु विकारान् मृत्तिकाकृतान् तद्वत् केसरयष्ट्याह्वपिप्पलीक्षीरशाद्वलैः", text: "vṛścikālī ca bhārṅgī ca sakṣīraistaiḥ śṛtaṃ ghṛtam sarvān praśamayatyāśu vikārān mṛttikākṛtān tadvat kesarayaṣṭyāhvapippalīkṣīraśādvalaiḥ" },
      { type: "verse", number: "20", sanskrit: "मृद्द्वेषणाय तल्लौल्ये वितरेद्भावितां मृदम् विडङ्गेनातिविषया पाठया निम्बपल्लवैः", text: "mṛddveṣaṇāya tallaulye vitaredbhāvitāṃ mṛdam viḍaṅgenātiviṣayā pāṭhayā nimbapallavaiḥ" },
      { type: "verse", number: "21", sanskrit: "वार्ताकैः कटुरोहिण्या कौटजैर्मूर्वयाथवा मृद्भेदाभिन्नदोषानुगमाद्योज्यं च भेषजम्", text: "vārtākaiḥ kaṭurohiṇyā kauṭajairmūrvayāthavā mṛdbhedābhinnadoṣānugamādyojyaṃ ca bheṣajam" },
      { type: "verse", number: "22", sanskrit: "कामलायां तु पित्तघ्नं पाण्डुरोगाविरोधि यत् पथ्याशतरसे पथ्यावृन्तार्धशतकल्कितः प्रस्थः सिद्धो घृताद् गुल्मकामलापाण्डुरोगजित्", text: "kāmalāyāṃ tu pittaghnaṃ pāṇḍurogāvirodhi yat pathyāśatarase pathyāvṛntārdhaśatakalkitaḥ prasthaḥ siddho ghṛtād gulmakāmalāpāṇḍurogajit" },
      { type: "verse", number: "23", sanskrit: "दन्तीचतुष्पलरसे पिष्टैर्दन्तीशलाटुभिः घृतप्रस्थः शृतस्तद्वत् प्लीहाश्वयथुजिच्च सः", text: "dantīcatuṣpalarase piṣṭairdantīśalāṭubhiḥ ghṛtaprasthaḥ śṛtastadvat plīhāśvayathujicca saḥ" },
      { type: "verse", number: "24", sanskrit: "पुराणसर्पिषः प्रस्थो द्राक्षार्धप्रस्थसाधितः कामलागुल्मपाण्ड्वर्तिज्वरमेहोदरापहः", text: "purāṇasarpiṣaḥ prastho drākṣārdhaprasthasādhitaḥ kāmalāgulmapāṇḍvartijvaramehodarāpahaḥ" },
      { type: "verse", number: "25", sanskrit: "हरिद्रात्रिफलानिल्बबलामधुकसाधितम् सक्षीरं माहिषं सर्पिः कामलाहरमुत्तमम्", text: "haridrātriphalānilbabalāmadhukasādhitam sakṣīraṃ māhiṣaṃ sarpiḥ kāmalāharamuttamam" },
      { type: "verse", number: "26", sanskrit: "गोमूत्रे द्विगुणे दार्वीकल्कार्धपलसाधितः दार्वीपञ्चपलक्वाथे कल्के कालीयके परः", text: "gomūtre dviguṇe dārvīkalkārdhapalasādhitaḥ dārvīpañcapalakvāthe kalke kālīyake paraḥ" },
      { type: "verse", number: "27", sanskrit: "माहिषात्सर्पिषः प्रस्थः पूर्वः पूर्वे परः परे सिद्धं कालीयकक्वाथे सनिशं चोत्तरे हितम्", text: "māhiṣātsarpiṣaḥ prasthaḥ pūrvaḥ pūrve paraḥ pare siddhaṃ kālīyakakvāthe saniśaṃ cottare hitam" },
      { type: "verse", number: "28", sanskrit: "आरग्वधं रसेनेक्षोर्विदार्यामलकस्य वा सत्र्यूषणं बिल्वमात्रं पाययेत् कामलापहम्", text: "āragvadhaṃ rasenekṣorvidāryāmalakasya vā satryūṣaṇaṃ bilvamātraṃ pāyayet kāmalāpaham" },
      { type: "verse", number: "29", sanskrit: "पिबेन्निकुम्भकल्कं वा द्विगुडं शीतवारिणा कुम्भस्य चूर्णं सक्षौद्रं त्रैफलेन रसेन वा सशर्करां त्रिभाण्डीं वा गवाक्षीं वा प्रयोजयेत्", text: "pibennikumbhakalkaṃ vā dviguḍaṃ śītavāriṇā kumbhasya cūrṇaṃ sakṣaudraṃ traiphalena rasena vā saśarkarāṃ tribhāṇḍīṃ vā gavākṣīṃ vā prayojayet" },
      { type: "verse", number: "30", sanskrit: "त्रिफलाया गुडूच्या वा दार्व्या निम्बस्य वा रसम् प्रातः प्रातर्मधुयुतं कामलार्ताय योजयेत्", text: "triphalāyā guḍūcyā vā dārvyā nimbasya vā rasam prātaḥ prātarmadhuyutaṃ kāmalārtāya yojayet" },
      { type: "verse", number: "31", sanskrit: "तिलपिष्टनिभं यस्तु कामलावान् सृजेन्मलम् कफरुद्धपथं तस्य पित्तं कफहरैर्जयेत्", text: "tilapiṣṭanibhaṃ yastu kāmalāvān sṛjenmalam kapharuddhapathaṃ tasya pittaṃ kaphaharairjayet" },
      { type: "verse", number: "32", sanskrit: "रूक्षशीतगुरुस्वादुव्यायामचलनिग्रहैः कफसम्मूर्छितो वायुर्यदा पित्तं बहिः क्षिपेत्", text: "rūkṣaśītagurusvāduvyāyāmacalanigrahaiḥ kaphasammūrchito vāyuryadā pittaṃ bahiḥ kṣipet" },
      { type: "verse", number: "33", sanskrit: "हारिद्रनेत्रमूत्रत्वक्श्वेतवर्चास्तदा नरः भवेत्साटोपविष्टम्भो गुरुणा हृदयेन च", text: "hāridranetramūtratvakśvetavarcāstadā naraḥ bhavetsāṭopaviṣṭambho guruṇā hṛdayena ca" },
      { type: "verse", number: "34", sanskrit: "दौर्बल्याल्पाग्निपार्श्वार्तिहिध्माश्वासारुचिज्वरैः क्रमेणाल्पे ऽनुषज्येत पित्ते शाखासमाश्रिते", text: "daurbalyālpāgnipārśvārtihidhmāśvāsārucijvaraiḥ krameṇālpe 'nuṣajyeta pitte śākhāsamāśrite" },
      { type: "verse", number: "35", sanskrit: "रसैस्तं रूक्षकट्वम्लैः शिखितित्तिरिदक्षजैः शुष्कमूलकजैर्यूषैः कुलत्थोत्थैश्च भोजयेत्", text: "rasaistaṃ rūkṣakaṭvamlaiḥ śikhitittiridakṣajaiḥ śuṣkamūlakajairyūṣaiḥ kulatthotthaiśca bhojayet" },
      { type: "verse", number: "36", sanskrit: "भृशाम्लतीक्ष्णकटुकलव्णोष्णं च शस्यते सबीजपूरकरसं लिह्याद्व्योषं तथाशयम्", text: "bhṛśāmlatīkṣṇakaṭukalavṇoṣṇaṃ ca śasyate sabījapūrakarasaṃ lihyādvyoṣaṃ tathāśayam" },
      { type: "verse", number: "37", sanskrit: "स्वं पित्तमेति तेनास्य शकृदप्यनुरज्यते वायुश्च याति प्रशमं सहाटोपाद्युपद्रवैः निवृत्तोपद्रवस्यास्य कार्यः कामलिको विधिः", text: "svaṃ pittameti tenāsya śakṛdapyanurajyate vāyuśca yāti praśamaṃ sahāṭopādyupadravaiḥ nivṛttopadravasyāsya kāryaḥ kāmaliko vidhiḥ" },
      { type: "verse", number: "38", sanskrit: "गोमूत्रेण पिबेत् कुम्भकामलायां शिलाजतु मासं माक्षिकधातुं वा किट्टं वाथ हिरण्यजम्", text: "gomūtreṇa pibet kumbhakāmalāyāṃ śilājatu māsaṃ mākṣikadhātuṃ vā kiṭṭaṃ vātha hiraṇyajam" },
      { type: "verse", number: "39", sanskrit: "गुडूचीस्वरसक्षीरसाधितेन हलीमकी महिषीहविषा स्निग्धः पिबेद्धात्रीरसेन तु", text: "guḍūcīsvarasakṣīrasādhitena halīmakī mahiṣīhaviṣā snigdhaḥ pibeddhātrīrasena tu" },
      { type: "verse", number: "40", sanskrit: "त्रिवृतां तद्विरिक्तो ऽद्यात् स्वादु पित्तानिलापहम् द्राक्षालेहं च पूर्वोक्तं सर्पींषि मधुराणि च", text: "trivṛtāṃ tadvirikto 'dyāt svādu pittānilāpaham drākṣālehaṃ ca pūrvoktaṃ sarpīṃṣi madhurāṇi ca" },
      { type: "verse", number: "41", sanskrit: "यापनान् क्षीरबस्तींश्च शीलयेत्सानुवासनान् मार्द्वीकारिष्टयोगांश्च पिबेद्युक्त्याग्निवृद्धये", text: "yāpanān kṣīrabastīṃśca śīlayetsānuvāsanān mārdvīkāriṣṭayogāṃśca pibedyuktyāgnivṛddhaye" },
      { type: "verse", number: "42", sanskrit: "कासिकं चाभयालेहं पिप्पलीं मधुकं बलाम् पयसा च प्रयुञ्जीत यथादोषं यथाबलम् पाण्डुरोगेषु कुशलः शोफोक्तं च क्रियाक्रमम्", text: "kāsikaṃ cābhayālehaṃ pippalīṃ madhukaṃ balām payasā ca prayuñjīta yathādoṣaṃ yathābalam pāṇḍurogeṣu kuśalaḥ śophoktaṃ ca kriyākramam" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 19,
    lang: "sa",
    content: [
      { type: "heading", heading: "Апасмара чикитса — лечение эпилепсии" },
      { type: "text", text: "Глава 19 Чикитса стханы — лечебный раздел о лечение эпилепсии. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातः श्वयथुचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ śvayathucikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "श्वयथुषु दोषजेषु सर्वेषु सर्वसरेष्वामानुबद्धेषु लङ्घन पाचनशोधनान्यादौ योजयेत् स्नेहजेषु विरूक्षणान्यौषधानि विरूक्षणोत्थेषु स्नेहनानि तत्रामजेषु लङ्घितवतो लघ्वन्नमशितस्य भद्रदारुनागरमरिचप्रतिविषाविडङ्गेन्द्रयवानुष्णाम्बुना नागरदेवदारुपथ्यावर्षाभ्वो वा पञ्चकोलकाजाजीनिदिग्धिकामुस्तपाठारजनीर्वा मूत्रवर्तिं वा नवायसं वा गुरुभिन्नपुरीषस्तु तक्रं सव्योषसौवर्चलक्षौद्रम् गुडहरीतकीं वा शीलयेत्", text: "śvayathuṣu doṣajeṣu sarveṣu sarvasareṣvāmānubaddheṣu laṅghana pācanaśodhanānyādau yojayet snehajeṣu virūkṣaṇānyauṣadhāni virūkṣaṇottheṣu snehanāni tatrāmajeṣu laṅghitavato laghvannamaśitasya bhadradārunāgaramaricaprativiṣāviḍaṅgendrayavānuṣṇāmbunā nāgaradevadārupathyāvarṣābhvo vā pañcakolakājājīnidigdhikāmustapāṭhārajanīrvā mūtravartiṃ vā navāyasaṃ vā gurubhinnapurīṣastu takraṃ savyoṣasauvarcalakṣaudram guḍaharītakīṃ vā śīlayet" },
      { type: "verse", number: "3", sanskrit: "इतरस्त्रिवृत्त्र्यूषणकटुरोहिण्ययश्चूर्णानि त्रिफलाक्वाथेन व्योषयवक्षारायोरजांसि वा बिभीतककल्कं वा तण्डुलाम्बुना गुग्गुलुं वा गोमूत्रेण हरीतकीं वा तुल्यगुडां वा शुण्ठीं पुनर्नवकषायानुपानाम् आर्द्रकं वा तुल्यगुडमर्धपलाभिवृद्धं पञ्चपलप्रकर्षं प्रयुञ्जीत मासमयं प्रयोगः शोफशोषार्शः श्वासकासप्रसेकपीनसालसकाग्निसादगुल्मोदरप्रमेहपाण्डुकामलामनोविकारानपहरति आर्द्रकरसं वा शालिक्षीराहारः पिबेत्", text: "itarastrivṛttryūṣaṇakaṭurohiṇyayaścūrṇāni triphalākvāthena vyoṣayavakṣārāyorajāṃsi vā bibhītakakalkaṃ vā taṇḍulāmbunā gugguluṃ vā gomūtreṇa harītakīṃ vā tulyaguḍāṃ vā śuṇṭhīṃ punarnavakaṣāyānupānām ārdrakaṃ vā tulyaguḍamardhapalābhivṛddhaṃ pañcapalaprakarṣaṃ prayuñjīta māsamayaṃ prayogaḥ śophaśoṣārśaḥ śvāsakāsaprasekapīnasālasakāgnisādagulmodarapramehapāṇḍukāmalāmanovikārānapaharati ārdrakarasaṃ vā śālikṣīrāhāraḥ pibet" },
      { type: "verse", number: "4", sanskrit: "निवृत्तामदोषः शृतानि पयांसि सर्पींषि च त्रिकटुकैरण्डश्यामामूलैः सिद्धं क्षीरम् महौषधमुरुङ्गीमूलाभ्यां वा वर्षाभूमयूरकपञ्चकोलैर्वा कुम्भनिकुम्भव्योषाग्निकैर्वा करभीक्षीरवृत्तिर्वा स्यात् गोमूत्रं महषीमूत्रं वा सक्षीरं क्षीराशनः पिबेत्", text: "nivṛttāmadoṣaḥ śṛtāni payāṃsi sarpīṃṣi ca trikaṭukairaṇḍaśyāmāmūlaiḥ siddhaṃ kṣīram mahauṣadhamuruṅgīmūlābhyāṃ vā varṣābhūmayūrakapañcakolairvā kumbhanikumbhavyoṣāgnikairvā karabhīkṣīravṛttirvā syāt gomūtraṃ mahaṣīmūtraṃ vā sakṣīraṃ kṣīrāśanaḥ pibet" },
      { type: "verse", number: "5", sanskrit: "दाडिमयवानीयवानकधनिकापाठाम्लवेतसमरिचपञ्चकोलबिल्वफलयावशूकानक्षमात्रान् सलिलाढके विपाच्य तत्कषायेण घृतप्रस्थं साधयेच्छोफार्शोगुल्ममेहाग्निसादहरम् अर्शोविहितविधिना चित्रकदध्नो नवनीतमाददीत तच्चित्रकमूलगर्भं सचित्रककल्कतक्रसिद्धं समानं पूर्वेण", text: "dāḍimayavānīyavānakadhanikāpāṭhāmlavetasamaricapañcakolabilvaphalayāvaśūkānakṣamātrān salilāḍhake vipācya tatkaṣāyeṇa ghṛtaprasthaṃ sādhayecchophārśogulmamehāgnisādaharam arśovihitavidhinā citrakadadhno navanītamādadīta taccitrakamūlagarbhaṃ sacitrakakalkatakrasiddhaṃ samānaṃ pūrveṇa" },
      { type: "verse", number: "6", sanskrit: "यथादोषोच्छ्रयं च धान्वन्तरं कल्याणकं पञ्चगव्यं तिक्तं महातिक्तमुदरोक्तानि वा तिल्वकचतुर्थानि घृतानि पाययेत्", text: "yathādoṣocchrayaṃ ca dhānvantaraṃ kalyāṇakaṃ pañcagavyaṃ tiktaṃ mahātiktamudaroktāni vā tilvakacaturthāni ghṛtāni pāyayet" },
      { type: "verse", number: "7", sanskrit: "दशमूलक्वाथकंसे पथ्याशतं गुडतुलोन्मिश्रमाधिश्रयेत् लेहीभूते तत्र त्रिकटुकत्रिजातकयवक्षारचूर्णं प्रक्षिपेत् क्षौद्रार्धप्रस्थं च एता दशमूलहरीतक्यो ऽतिप्रवृद्धमपि श्वयथुमुदरारोचकाविपाकपाण्डुरोगगुल्ममेहश्वासकासकार्श्यामवाताम्लपित्तमूत्रशुक्रदोषांश्च निघ्नन्ति", text: "daśamūlakvāthakaṃse pathyāśataṃ guḍatulonmiśramādhiśrayet lehībhūte tatra trikaṭukatrijātakayavakṣāracūrṇaṃ prakṣipet kṣaudrārdhaprasthaṃ ca etā daśamūlaharītakyo 'tipravṛddhamapi śvayathumudarārocakāvipākapāṇḍurogagulmamehaśvāsakāsakārśyāmavātāmlapittamūtraśukradoṣāṃśca nighnanti" },
      { type: "verse", number: "8", sanskrit: "शठीपुष्करमूलकारवीचित्रकाजाजीजीवन्तीबिल्वमध्ययवक्षारवृक्षाम्लैर्दशमूलेन च परिगृहीतानि घृततैलभृष्टानि पेयादीन्यन्नान्यल्पस्नेहलवणान्युपकल्पयेत् स्पर्शसुखांश्चाभ्यङ्गप्रदेहसेकान्", text: "śaṭhīpuṣkaramūlakāravīcitrakājājījīvantībilvamadhyayavakṣāravṛkṣāmlairdaśamūlena ca parigṛhītāni ghṛtatailabhṛṣṭāni peyādīnyannānyalpasnehalavaṇānyupakalpayet sparśasukhāṃścābhyaṅgapradehasekān" },
      { type: "verse", number: "9", sanskrit: "शैलेयस्थौणेयकश्रीवेष्टकागरुदेवदारुहरेणुकाकुष्ठध्यामकपद्मकमांसीमागधिकावन्यधान्यतालीसपत्रकचतुर्जातकपलाशाम्बुदाम्बुप्रियङ्गुस्पृक्कानखैः श्लक्ष्णपिष्टैस्तैलमभ्यङ्गं पचेत् तैश्च प्रदेहं कुर्यात् सर्षपसौवर्चलसैन्धवशार्ङ्गेष्टाभिश्च केवलैर्वाक्षमज्जाभिः", text: "śaileyasthauṇeyakaśrīveṣṭakāgarudevadāruhareṇukākuṣṭhadhyāmakapadmakamāṃsīmāgadhikāvanyadhānyatālīsapatrakacaturjātakapalāśāmbudāmbupriyaṅguspṛkkānakhaiḥ ślakṣṇapiṣṭaistailamabhyaṅgaṃ pacet taiśca pradehaṃ kuryāt sarṣapasauvarcalasaindhavaśārṅgeṣṭābhiśca kevalairvākṣamajjābhiḥ" },
      { type: "verse", number: "10", sanskrit: "विशेषतश्चैकाङ्गजेषु पुनर्नवहिंस्राकोशातकीकरवीरकिंशुकातिविषर्धिवृद्धिमूषिकपर्णीहस्तिकर्णनलिकानाकुलीस्थूलकाकादनीसालत्रिफलादेवदारुलोध्रतालपर्णीदशपत्रिकाजयन्तीभिः प्रलेपः", text: "viśeṣataścaikāṅgajeṣu punarnavahiṃsrākośātakīkaravīrakiṃśukātiviṣardhivṛddhimūṣikaparṇīhastikarṇanalikānākulīsthūlakākādanīsālatriphalādevadārulodhratālaparṇīdaśapatrikājayantībhiḥ pralepaḥ" },
      { type: "verse", number: "11", sanskrit: "मूलकतोयेन कवोष्णेन वृक्षकार्कनक्तमालनिम्बवर्षाभूक्वाथेन वा स्नानम्", text: "mūlakatoyena kavoṣṇena vṛkṣakārkanaktamālanimbavarṣābhūkvāthena vā snānam" },
      { type: "verse", number: "12", sanskrit: "अथानिलजे श्वयथौ त्रिवृतमेरण्डतैलं वार्धमासं मासं वा पिबेत् एरण्डतैलमेव च विड्वातसङ्गे प्राग्भक्तं पयसा रसैर्वा वातहराभ्यङ्गस्वेदोपनाहांश्च कुर्यात् विशेषेण चैकाङ्गगे मातुलुङ्गाग्निमन्थशुण्ठी देवदारुहिंस्राप्रलेपः", text: "athānilaje śvayathau trivṛtameraṇḍatailaṃ vārdhamāsaṃ māsaṃ vā pibet eraṇḍatailameva ca viḍvātasaṅge prāgbhaktaṃ payasā rasairvā vātaharābhyaṅgasvedopanāhāṃśca kuryāt viśeṣeṇa caikāṅgage mātuluṅgāgnimanthaśuṇṭhī devadāruhiṃsrāpralepaḥ" },
      { type: "verse", number: "13", sanskrit: "पित्तजे न्यग्रोधादिसिद्धं सर्पिः पिबेत् तिक्तकं वा मूर्छारतितृड्दाहेषु क्षीरम् तदेव तु स्रंसनार्थी मूत्रयुक्तम् अभयामरदारुमधुककटुकादन्तीचन्दननिचुलपटोलमूर्वादार्वीत्रायमाणोपकुल्याविशालाक्वाथः ससर्पिरुपयुक्तः श्वयथुविषवीसर्पज्वरदाहपिपासान्तःसन्तापसन्निपातानुपशमयति घृतक्षीरक्षीरिवृक्षवेतसमञ्जिष्ठामृणालचन्दनादिभिः शीतवीर्यैः कल्पयेदभ्यङ्गादीन्", text: "pittaje nyagrodhādisiddhaṃ sarpiḥ pibet tiktakaṃ vā mūrchāratitṛḍdāheṣu kṣīram tadeva tu sraṃsanārthī mūtrayuktam abhayāmaradārumadhukakaṭukādantīcandananiculapaṭolamūrvādārvītrāyamāṇopakulyāviśālākvāthaḥ sasarpirupayuktaḥ śvayathuviṣavīsarpajvaradāhapipāsāntaḥsantāpasannipātānupaśamayati ghṛtakṣīrakṣīrivṛkṣavetasamañjiṣṭhāmṛṇālacandanādibhiḥ śītavīryaiḥ kalpayedabhyaṅgādīn" },
      { type: "verse", number: "14", sanskrit: "कफोत्थे त्वारग्वधादिसाधितं तैलं पिबेत् क्षारमूत्रतक्रासवारिष्टांश्च भल्लातकचित्रकव्योषविडङ्गबृहतीफलानि पृथक् प्रस्थांशान्यच्छधान्याम्लद्रोणे गोमयाग्निना त्रिभागशेषमवतारयेत् तत्पूतशीतं मस्तुकलशेन सितोपलातुलया च युक्तमग्निकमागधिकाकल्कलिप्ते दृढे भाण्डे समावाप्य वैहायसे सुगुप्तं स्थापयेत् ततो दशाहस्थितो ऽयमुपयुक्तो भल्लातकारिष्टः शोफोदरार्शोभगन्दरग्रहणीकृमिकुष्ठमेहकार्श्यकिक्कसान् सत्वरमपनयति", text: "kaphotthe tvāragvadhādisādhitaṃ tailaṃ pibet kṣāramūtratakrāsavāriṣṭāṃśca bhallātakacitrakavyoṣaviḍaṅgabṛhatīphalāni pṛthak prasthāṃśānyacchadhānyāmladroṇe gomayāgninā tribhāgaśeṣamavatārayet tatpūtaśītaṃ mastukalaśena sitopalātulayā ca yuktamagnikamāgadhikākalkalipte dṛḍhe bhāṇḍe samāvāpya vaihāyase suguptaṃ sthāpayet tato daśāhasthito 'yamupayukto bhallātakāriṣṭaḥ śophodarārśobhagandaragrahaṇīkṛmikuṣṭhamehakārśyakikkasān satvaramapanayati" },
      { type: "verse", number: "15", sanskrit: "त्रिफलामरिचद्राक्षापिप्पलीकाश्मर्यफलानां प्रत्येकं शतं गुडतुलामुदकद्रोणं च मधुलिप्तभाजनस्थं सप्ताहमुष्णे काले द्विसप्ताहं शीते धारयेत् अयमष्टशतरिष्टः समानः पूर्वेण पुराणपिण्याककृष्णाशिग्रुत्वगतसीसिकता मूत्रपिष्टाः सुखोष्णाः प्रलेपे दद्यात् एक्राङ्गगे तु कालासरलाजशृङ्ग्यजगन्धाश्वगन्धैकैषिकाः शुण्ठीकुलत्थतर्कारीकुष्ठार्जकचित्रकजलमूत्राणि स्नाने चण्डागरुणी विलेपने", text: "triphalāmaricadrākṣāpippalīkāśmaryaphalānāṃ pratyekaṃ śataṃ guḍatulāmudakadroṇaṃ ca madhuliptabhājanasthaṃ saptāhamuṣṇe kāle dvisaptāhaṃ śīte dhārayet ayamaṣṭaśatariṣṭaḥ samānaḥ pūrveṇa purāṇapiṇyākakṛṣṇāśigrutvagatasīsikatā mūtrapiṣṭāḥ sukhoṣṇāḥ pralepe dadyāt ekrāṅgage tu kālāsaralājaśṛṅgyajagandhāśvagandhaikaiṣikāḥ śuṇṭhīkulatthatarkārīkuṣṭhārjakacitrakajalamūtrāṇi snāne caṇḍāgaruṇī vilepane" },
      { type: "verse", number: "16", sanskrit: "संसर्गसन्निपातयोर्यथादोषोदयमिदमेव साधनम् एकदेशाश्रये च श्वयथौ यथासन्नं वमनादीनि रक्तावसेचनं च कुर्वीतेति भवति चात्र", text: "saṃsargasannipātayoryathādoṣodayamidameva sādhanam ekadeśāśraye ca śvayathau yathāsannaṃ vamanādīni raktāvasecanaṃ ca kurvīteti bhavati cātra" },
      { type: "verse", number: "17", sanskrit: "प्रायो ऽभिघातादनिलः सरक्तः शोफं सरागं प्रकरोति तत्र विसर्पनुन्मारुतरक्तनुच्च कार्यं विषघ्नं विषजे च कर्म", text: "prāyo 'bhighātādanilaḥ saraktaḥ śophaṃ sarāgaṃ prakaroti tatra visarpanunmārutaraktanucca kāryaṃ viṣaghnaṃ viṣaje ca karma" },
      { type: "verse", number: "18", sanskrit: "ग्राम्याब्जानूपं पिशितमबलं शुष्कशाकं तिलान्नं गौडं पिष्टान्नं दधिसलवणं पिच्छिलं मद्यमम्लम् धाना वल्लूरं समशनमथो गुर्वसात्म्यं विदाहि स्वप्नं चारात्रौ श्वयथुगदवान् वर्जयेन्मैथुनं च", text: "grāmyābjānūpaṃ piśitamabalaṃ śuṣkaśākaṃ tilānnaṃ gauḍaṃ piṣṭānnaṃ dadhisalavaṇaṃ picchilaṃ madyamamlam dhānā vallūraṃ samaśanamatho gurvasātmyaṃ vidāhi svapnaṃ cārātrau śvayathugadavān varjayenmaithunaṃ ca" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 20,
    lang: "sa",
    content: [
      { type: "heading", heading: "Муттра рога чикитса — лечение мочевых расстройств" },
      { type: "text", text: "Глава 20 Чикитса стханы — лечебный раздел о лечение мочевых расстройств. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो विसर्पचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto visarpacikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "पूर्वरूपेष्वेव सर्वविसर्पाणां लङ्घनं रूक्षणं सिरामोक्षणमुल्लेखनं विरेचनं च कुर्यात् न तु कदाचिदपि स्नेहनम्", text: "pūrvarūpeṣveva sarvavisarpāṇāṃ laṅghanaṃ rūkṣaṇaṃ sirāmokṣaṇamullekhanaṃ virecanaṃ ca kuryāt na tu kadācidapi snehanam" },
      { type: "verse", number: "3", sanskrit: "निरामेषु क्षीणकफेषु च शीतवीर्याणि सर्पींषि तिक्तकत्रायमाणाघृतादीनि पाने दद्यात् तत्र मदनेन्द्रयवपटोलपिचुमन्दमधुकेक्षुरसान् वमने ऽवचारयेत् द्राक्षात्रिवृत्त्रिफलात्रायमाणा विरेचने", text: "nirāmeṣu kṣīṇakapheṣu ca śītavīryāṇi sarpīṃṣi tiktakatrāyamāṇāghṛtādīni pāne dadyāt tatra madanendrayavapaṭolapicumandamadhukekṣurasān vamane 'vacārayet drākṣātrivṛttriphalātrāyamāṇā virecane" },
      { type: "verse", number: "4", sanskrit: "मुस्तदेवदारुकुष्ठशताह्वावाराहीधान्याककृष्णगन्धावंशार्तगलान् लेपसेकेष्वनिलजे ह्रस्ववढ्रवल्लीकण्टकपञ्चमूलानि च", text: "mustadevadārukuṣṭhaśatāhvāvārāhīdhānyākakṛṣṇagandhāvaṃśārtagalān lepasekeṣvanilaje hrasvavaḍhravallīkaṇṭakapañcamūlāni ca" },
      { type: "verse", number: "5", sanskrit: "पित्ते तु कमलोत्पलशैवालपङ्कदूर्वामृणालशृङ्गाटककशेरुकशर्कराद्रीबेरकुचन्दनमुक्तामणिगैरिकपयस्याप्रपौण्डरीकमधुकपद्मकघृतक्षीराणि न्यग्रोधादिं च", text: "pitte tu kamalotpalaśaivālapaṅkadūrvāmṛṇālaśṛṅgāṭakakaśerukaśarkarādrīberakucandanamuktāmaṇigairikapayasyāprapauṇḍarīkamadhukapadmakaghṛtakṣīrāṇi nyagrodhādiṃ ca" },
      { type: "verse", number: "6", sanskrit: "श्लेष्मण्यजगन्धाश्वगन्धासरलकालकैषिकागरुवोचरास्नावचाशीतशिवेन्द्रवल्लीगोमूत्राणि वरणादिं च संसर्गे यथादोषबलं विकल्पयेत्", text: "śleṣmaṇyajagandhāśvagandhāsaralakālakaiṣikāgaruvocarāsnāvacāśītaśivendravallīgomūtrāṇi varaṇādiṃ ca saṃsarge yathādoṣabalaṃ vikalpayet" },
      { type: "verse", number: "7", sanskrit: "तत्र कफस्थानाश्रिते सामे पित्तस्थानगते च रूक्षा विशीताः प्रलेपपरिषेकाः", text: "tatra kaphasthānāśrite sāme pittasthānagate ca rūkṣā viśītāḥ pralepapariṣekāḥ" },
      { type: "verse", number: "8", sanskrit: "पित्ते तनवः सुशीताः सघृता वस्त्रान्तरिताः क्षणे क्षणे चापनीयान्ये प्रयोज्याः", text: "pitte tanavaḥ suśītāḥ saghṛtā vastrāntaritāḥ kṣaṇe kṣaṇe cāpanīyānye prayojyāḥ" },
      { type: "verse", number: "9", sanskrit: "द्वन्द्वजेषु यथायथं दोषांश्चिकित्सेत् विशेषेणाग्निविसर्पे महातिक्तकं पिबेत् ग्रन्थिविसर्पे रक्तपित्तसंसर्गमवेक्ष्य प्राग्लङ्घनादीनि विरेचनान्तानि शमनानि च योजयेत् ततो वातश्लेष्महरं कर्म", text: "dvandvajeṣu yathāyathaṃ doṣāṃścikitset viśeṣeṇāgnivisarpe mahātiktakaṃ pibet granthivisarpe raktapittasaṃsargamavekṣya prāglaṅghanādīni virecanāntāni śamanāni ca yojayet tato vātaśleṣmaharaṃ karma" },
      { type: "verse", number: "10", sanskrit: "शूले च तदा स्निग्धाम्लोष्णाभिरुत्कारिकाभिर्ग्रन्थीनामुपनाहनम् वातकफविसर्पोक्तैश्च लेपस्तैरेव वा सिद्धेन तैलेन तोयेन वा परिषेकः लिम्पेद्वा शुष्कमूलकस्य कल्केन नक्तमालत्वचो वा बिभीतकेन वा विजयाक्षनागबलाग्निमन्थभूर्जग्रन्थिवंशपत्राणां वा", text: "śūle ca tadā snigdhāmloṣṇābhirutkārikābhirgranthīnāmupanāhanam vātakaphavisarpoktaiśca lepastaireva vā siddhena tailena toyena vā pariṣekaḥ limpedvā śuṣkamūlakasya kalkena naktamālatvaco vā bibhītakena vā vijayākṣanāgabalāgnimanthabhūrjagranthivaṃśapatrāṇāṃ vā" },
      { type: "verse", number: "11", sanskrit: "दन्तीचित्रकमूलत्वक्कासीसार्कस्नुहीक्षीरभल्लातकास्थिभिरुष्णैर्लेपः शिलामपि भिनत्ति दीर्घकालप्रसक्ते तु ग्रन्थौ त्रिफलां प्रयुञ्जीत मधुपिप्पलीर्वा मुस्तासक्तुभल्लातकानि वा सीघुमधुशर्करान् वा मातुलुङ्गरसानुविद्धां मदिरां वा गिरिजतुं वा गुल्मभेदनं वा तप्तलोहोपलादिपीडनं वा जत्रूर्ध्वगते तीक्ष्णधूमवमनानि च", text: "dantīcitrakamūlatvakkāsīsārkasnuhīkṣīrabhallātakāsthibhiruṣṇairlepaḥ śilāmapi bhinatti dīrghakālaprasakte tu granthau triphalāṃ prayuñjīta madhupippalīrvā mustāsaktubhallātakāni vā sīghumadhuśarkarān vā mātuluṅgarasānuviddhāṃ madirāṃ vā girijatuṃ vā gulmabhedanaṃ vā taptalohopalādipīḍanaṃ vā jatrūrdhvagate tīkṣṇadhūmavamanāni ca" },
      { type: "verse", number: "12", sanskrit: "तथाप्यभेदे क्षारेणाग्निना वा दहेत् पाटयित्वा वा शस्त्रेण परिशोधयेत् विदग्धं वा रक्तमपनीयापनीय पुनःपुनः स्वेदयेत् एवं पर्यायेण रक्तपित्ते वातश्लेष्मणि चोत्तिष्ठेत", text: "tathāpyabhede kṣāreṇāgninā vā dahet pāṭayitvā vā śastreṇa pariśodhayet vidagdhaṃ vā raktamapanīyāpanīya punaḥpunaḥ svedayet evaṃ paryāyeṇa raktapitte vātaśleṣmaṇi cottiṣṭheta" },
      { type: "verse", number: "13", sanskrit: "सर्वस्मिन् विसर्पे पर्यागते विदारिते च व्रणवत् तैलं च दार्वीविडङ्गकम्पिल्लकैः ग्रन्थिव्रणसाधनं साधयेत्", text: "sarvasmin visarpe paryāgate vidārite ca vraṇavat tailaṃ ca dārvīviḍaṅgakampillakaiḥ granthivraṇasādhanaṃ sādhayet" },
      { type: "verse", number: "14", sanskrit: "कर्दमके शीघ्रतरं सुतरां च वमनादीनि कृत्वा पुनर्जलौकोभिरसृगवसेचयेत् असृक्प्रक्लेदाद्धि त्वङ्मांससिरास्नावसङ्क्लेदो भवति पिबेच्च कषायं घनपटोलपिचुमन्दानाम् मुस्तोशीरामलकसारिवाणाम् चन्दनोत्पलयोः पटोलादिवर्गस्य वा घृतमिश्रं वा दार्वीत्वक्तिक्तापटोलयष्ट्याह्वारिष्टमसूरत्रिफलात्रायमाणानाम्", text: "kardamake śīghrataraṃ sutarāṃ ca vamanādīni kṛtvā punarjalaukobhirasṛgavasecayet asṛkprakledāddhi tvaṅmāṃsasirāsnāvasaṅkledo bhavati pibecca kaṣāyaṃ ghanapaṭolapicumandānām mustośīrāmalakasārivāṇām candanotpalayoḥ paṭolādivargasya vā ghṛtamiśraṃ vā dārvītvaktiktāpaṭolayaṣṭyāhvāriṣṭamasūratriphalātrāyamāṇānām" },
      { type: "verse", number: "15", sanskrit: "विरेकार्थं च त्रिवृच्चूर्णं सर्पिषा पयसा द्राक्षारसेन घर्माम्भसा वा पाययेत् त्रायमाणाशृतं पित्तोद्वृत्तो क्षीरमिति भवति चात्र", text: "virekārthaṃ ca trivṛccūrṇaṃ sarpiṣā payasā drākṣārasena gharmāmbhasā vā pāyayet trāyamāṇāśṛtaṃ pittodvṛtto kṣīramiti bhavati cātra" },
      { type: "verse", number: "16", sanskrit: "श्रेष्ठास्रस्रुतिरेवात्र विसर्पो ह्यसृगाश्रयः यच्च नासावसंसृष्टो रक्तपित्तेन जायते", text: "śreṣṭhāsrasrutirevātra visarpo hyasṛgāśrayaḥ yacca nāsāvasaṃsṛṣṭo raktapittena jāyate" },
      { type: "verse", number: "17", sanskrit: "न घृतं बहुदोषाय देयं यन्न विरेचनम् तेन दोषो ह्युपस्तब्धस्त्वग्रक्तपिशितं पचेत्", text: "na ghṛtaṃ bahudoṣāya deyaṃ yanna virecanam tena doṣo hyupastabdhastvagraktapiśitaṃ pacet" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 21,
    lang: "sa",
    content: [
      { type: "heading", heading: "Грахани чикитса — лечение мальабсорбции" },
      { type: "text", text: "Глава 21 Чикитса стханы — лечебный раздел о лечение мальабсорбции. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातः कुष्ठचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ kuṣṭhacikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "पूर्वरूपेष्वेव कुष्ठिनं स्नेहपानेनोपक्रमेत तत्र वातोत्तरे मेषशृङ्गीशार्ङ्गेष्टैरण्डगुडूचीद्विपञ्चमूलसिद्धं तैलं घृतं वा पानाभ्यङ्गयोर्विदध्यात्", text: "pūrvarūpeṣveva kuṣṭhinaṃ snehapānenopakrameta tatra vātottare meṣaśṛṅgīśārṅgeṣṭairaṇḍaguḍūcīdvipañcamūlasiddhaṃ tailaṃ ghṛtaṃ vā pānābhyaṅgayorvidadhyāt" },
      { type: "verse", number: "3", sanskrit: "पित्तोत्तरे धवाश्वकर्णककुभवचापुनर्नवपलाशपिचुमन्दमधुकलोध्रसमङ्गासिद्धं सर्पिः अथवा पटोलपिचुमन्ददार्वीदुरालभातिक्तरोहिणीपाठापर्पटकत्रायमाणानां पालिकान् भागान् जलाढकद्वये ऽष्टभागशेषं क्वाथयेत् तेन कार्षिकैश्चन्दनोपकुल्यामुस्तात्रायन्तीन्द्रयवभूनिम्बैः कल्कितैः सपिषो द्वादशपलं साधयेत् एतत्तिक्तकं सर्पिः कुष्ठविसर्पविस्फोटगण्डगण्डमालाश्वयथुपिटकारक्तपित्तदुर्नामवातशोणितकामलापाण्ड्वामयोन्माददाहतृड्भ्रमकण्डूकुष्ठनाडीगुल्ममदतिमिरव्यङ्गश्वित्रापस्मारभगन्धरोदरप्रदरज्वरगरविद्रधिग्रहणीहृद्रोगानपहरति", text: "pittottare dhavāśvakarṇakakubhavacāpunarnavapalāśapicumandamadhukalodhrasamaṅgāsiddhaṃ sarpiḥ athavā paṭolapicumandadārvīdurālabhātiktarohiṇīpāṭhāparpaṭakatrāyamāṇānāṃ pālikān bhāgān jalāḍhakadvaye 'ṣṭabhāgaśeṣaṃ kvāthayet tena kārṣikaiścandanopakulyāmustātrāyantīndrayavabhūnimbaiḥ kalkitaiḥ sapiṣo dvādaśapalaṃ sādhayet etattiktakaṃ sarpiḥ kuṣṭhavisarpavisphoṭagaṇḍagaṇḍamālāśvayathupiṭakāraktapittadurnāmavātaśoṇitakāmalāpāṇḍvāmayonmādadāhatṛḍbhramakaṇḍūkuṣṭhanāḍīgulmamadatimiravyaṅgaśvitrāpasmārabhagandharodarapradarajvaragaravidradhigrahaṇīhṛdrogānapaharati" },
      { type: "verse", number: "4", sanskrit: "सप्तच्छदकटुकातिविषाशम्याकपाठामुस्तत्रिफलोशीरपटोलपर्पटकपिप्पलीद्वयद्विरजनीद्विसारिवा चन्दनदुरालभापद्मकवचाशतावरीविशालाकुटजबीजवृषमूर्वागुडूचीभूनिम्बत्रायमाणामधुकगर्भं द्विगुणामलकरसमष्टगुणाम्बु सर्पिर्विपक्वं महातिक्तकाख्यं घृतमधिकगुणं पूर्वस्मात् गुग्गुलुपञ्चतिक्तं वा पिबेत्", text: "saptacchadakaṭukātiviṣāśamyākapāṭhāmustatriphalośīrapaṭolaparpaṭakapippalīdvayadvirajanīdvisārivā candanadurālabhāpadmakavacāśatāvarīviśālākuṭajabījavṛṣamūrvāguḍūcībhūnimbatrāyamāṇāmadhukagarbhaṃ dviguṇāmalakarasamaṣṭaguṇāmbu sarpirvipakvaṃ mahātiktakākhyaṃ ghṛtamadhikaguṇaṃ pūrvasmāt guggulupañcatiktaṃ vā pibet" },
      { type: "verse", number: "5", sanskrit: "कफोत्तरे सालप्रियालशम्याकारिष्टसप्तपर्णचित्रकमरिचवचाकुष्ठैः साधितम् अथवा बृहतीद्वयकाकमाचीशुकनासाक्वाथे मरिचविडङ्गशिग्रुजातीदेवदारुक्षवकहरिद्राभयाकल्केन वाजिमूत्रेण च सिद्धं सर्पिः", text: "kaphottare sālapriyālaśamyākāriṣṭasaptaparṇacitrakamaricavacākuṣṭhaiḥ sādhitam athavā bṛhatīdvayakākamācīśukanāsākvāthe maricaviḍaṅgaśigrujātīdevadārukṣavakaharidrābhayākalkena vājimūtreṇa ca siddhaṃ sarpiḥ" },
      { type: "verse", number: "6", sanskrit: "सर्वेषु च भल्लातकतुवरकसिद्धार्थकान्यतमतैलम् भल्लातकपथ्याकृमिघ्नसिद्धं वा हविः", text: "sarveṣu ca bhallātakatuvarakasiddhārthakānyatamatailam bhallātakapathyākṛmighnasiddhaṃ vā haviḥ" },
      { type: "verse", number: "7", sanskrit: "ततः स्निग्धस्य यथादोषं यथासन्नं च संशोधनानि प्रयुञ्जीत सिरां च बलापेक्षी विध्येदेकां द्वे तिस्रश्चतस्रः पञ्च वा अन्तरान्तरा च पुनःपुनः स्नेहं पिबेत् दुर्बलं हि शून्यकोष्ठं कुष्ठिनं वायुरभिभवति वमने त्वस्य मधुककुटजबीजनिम्बपटोलपल्लवानि विदध्यात् कुम्भनिकुम्भत्रिफला विरेचने माणिभद्रवटकांश्च", text: "tataḥ snigdhasya yathādoṣaṃ yathāsannaṃ ca saṃśodhanāni prayuñjīta sirāṃ ca balāpekṣī vidhyedekāṃ dve tisraścatasraḥ pañca vā antarāntarā ca punaḥpunaḥ snehaṃ pibet durbalaṃ hi śūnyakoṣṭhaṃ kuṣṭhinaṃ vāyurabhibhavati vamane tvasya madhukakuṭajabījanimbapaṭolapallavāni vidadhyāt kumbhanikumbhatriphalā virecane māṇibhadravaṭakāṃśca" },
      { type: "verse", number: "8", sanskrit: "पटोलविशालयोर्मूलं त्रिफला च पृथक् त्रिभागोनत्रिशाणाः कटुकात्रायमाणे शाणांशे शुण्ठ्यास्त्रिभागोनः शाणः तदेतत् पलमैकध्यं सलिले विपाच्य पाययेत् ऊर्ध्वाधोविरिक्तश्च जीर्णे जाङ्गलरसेनाश्नीयात् एवमेतत् षड्रात्रप्रयोगात् परं पित्तकफशोफकुष्ठदुष्टनाडीव्रणार्शोभगन्दरग्रहणीपाण्डुहलीमककामलाविषमज्वरहृद्बस्तिवेदनाघ्नम्", text: "paṭolaviśālayormūlaṃ triphalā ca pṛthak tribhāgonatriśāṇāḥ kaṭukātrāyamāṇe śāṇāṃśe śuṇṭhyāstribhāgonaḥ śāṇaḥ tadetat palamaikadhyaṃ salile vipācya pāyayet ūrdhvādhoviriktaśca jīrṇe jāṅgalarasenāśnīyāt evametat ṣaḍrātraprayogāt paraṃ pittakaphaśophakuṣṭhaduṣṭanāḍīvraṇārśobhagandaragrahaṇīpāṇḍuhalīmakakāmalāviṣamajvarahṛdbastivedanāghnam" },
      { type: "verse", number: "9", sanskrit: "उभयानुलोमनं वा ब्राह्मीस्वरससाधितं सर्पिः पिबेत् आवर्तकीतुलां सलिलार्मणे ऽष्टांशशिष्टां विपाच्य तेन निर्यूहेण तन्मूलैश्च घृतप्रस्थं साधयेत् ततो मात्रामेकाहान्तरं पिबेत् ऊर्ध्वाधो विरिच्यमानस्तृषितः शीतलवणमारनालं जीर्णस्नेहश्च तेनैव कोद्रवौदनमश्नीयात् अनेन कुष्ठश्वित्रापचीभगन्दरनाडीव्रणाखुविषाणि सिध्यन्ति मेध्यं चैतत् पुंसवनं च", text: "ubhayānulomanaṃ vā brāhmīsvarasasādhitaṃ sarpiḥ pibet āvartakītulāṃ salilārmaṇe 'ṣṭāṃśaśiṣṭāṃ vipācya tena niryūheṇa tanmūlaiśca ghṛtaprasthaṃ sādhayet tato mātrāmekāhāntaraṃ pibet ūrdhvādho viricyamānastṛṣitaḥ śītalavaṇamāranālaṃ jīrṇasnehaśca tenaiva kodravaudanamaśnīyāt anena kuṣṭhaśvitrāpacībhagandaranāḍīvraṇākhuviṣāṇi sidhyanti medhyaṃ caitat puṃsavanaṃ ca" },
      { type: "verse", number: "10", sanskrit: "दार्वीपटोलबृहतीसेव्यमदननिम्बकृतमालघनेन्द्रयवैः सस्नेहैरास्थापनम् एभिरेव च विपक्वः स्नेहो ऽनुवासनार्हस्यानुवासनम् दन्तीमरिचफणिज्जकार्द्रककरञ्जबीजपिप्पलीविडङ्गसैन्धवैरूर्ध्वजत्रुगते कुष्ठे कृमिषु च शिरोविरेकः सूत्रस्थानोक्तो वैरेचनिकधूमश्च", text: "dārvīpaṭolabṛhatīsevyamadananimbakṛtamālaghanendrayavaiḥ sasnehairāsthāpanam ebhireva ca vipakvaḥ sneho 'nuvāsanārhasyānuvāsanam dantīmaricaphaṇijjakārdrakakarañjabījapippalīviḍaṅgasaindhavairūrdhvajatrugate kuṣṭhe kṛmiṣu ca śirovirekaḥ sūtrasthānokto vairecanikadhūmaśca" },
      { type: "verse", number: "11", sanskrit: "ततः सर्वतो विशुद्धस्यान्तर्बहिः शमनानि प्रयुञ्जीत", text: "tataḥ sarvato viśuddhasyāntarbahiḥ śamanāni prayuñjīta" },
      { type: "verse", number: "12", sanskrit: "खदिरकदरतिनिशासनशिरीषशिंशपाशाकसर्जार्जुनजम्बूकरवीरधवामलकीमुष्ककाक्षिकबदरीवञ्जुलनिम्बकरञ्जकदम्बमधूकसारान् सार्द्रान् कृतमालनिचुलपटोलाङ्कोलबलाबिल्वकुटजकटभीपारिभद्रसहचरगृध्रनखीवरणवर्धमानार्कसौभञ्जनाटरूषकशतावरीश्वदंष्ट्राहिमाराश्वकर्णश्रीपर्णीस्वयंगुप्ताग्निमन्थेन्द्रवारुणीकाकोदुम्बरिकामेषशृङ्गीटुण्टुकगुडूचीवर्षाभूवायसीबृहतीद्वयरोहिणीमूर्वाशार्ङ्गष्टामूलानि च शकलयित्वा पृथक् त्रिंशत्पलिकानि सङ्क्षुद्य महति कटाहे ऽष्टगुणेनाम्भसा क्वाथयेत् अष्टभागशेषं निर्यूहमवतार्य परिस्राव्य च तस्मिन् सर्पिषः पलशतत्रयं विपचेदीषदवशेषकषाये च विदलीकृतारुष्करसहस्रत्रयमत्रावाप्य पुनः पाचयेद्विगतस्वरसान्यरुष्कराण्यपास्य तस्मिन् स्नेहे सुचूर्णितानि प्रक्षिपेत् व्याधिघातव्योषनाकुलीमार्कवार्ककाकादनीतगरकटुकाकुष्ठबिल्वहिङ्गुविडङ्गचित्रकातिविषामुस्तेन्द्रयवेन्द्रवारुणीरूप्य मललोहरजोलोहकान्तरसाञ्जनाभ्रशुकनासादेवदालीत्रिफलालाङ्गलिकीविशालाकुम्भनिकुम्भवचावाराहीमहाद्रुमकोशातकीप्रपुन्नाटसोमपर्णीनलिकाद्वयपटोलीजातीपल्लवताप्यकारवेल्लीकूलिकाकन्दकसप्तच्छदशार्ङ्गेष्टोत्पलसारिवागुग्गुलुशिलाजतुमूर्वाकुस्तुम्बरीजीवकद्वयपाठेन्द्रुरेखावज्रकन्दहरिद्राद्वयलवणपञ्चकानि प्रत्येकं त्रिपलिकानि शृङ्गीविषपलं चैकं ततो दर्व्या समन्तादाघट्य सुगुप्तं भूमौ धान्ये वा मासं निखनेत्", text: "khadirakadaratiniśāsanaśirīṣaśiṃśapāśākasarjārjunajambūkaravīradhavāmalakīmuṣkakākṣikabadarīvañjulanimbakarañjakadambamadhūkasārān sārdrān kṛtamālaniculapaṭolāṅkolabalābilvakuṭajakaṭabhīpāribhadrasahacaragṛdhranakhīvaraṇavardhamānārkasaubhañjanāṭarūṣakaśatāvarīśvadaṃṣṭrāhimārāśvakarṇaśrīparṇīsvayaṃguptāgnimanthendravāruṇīkākodumbarikāmeṣaśṛṅgīṭuṇṭukaguḍūcīvarṣābhūvāyasībṛhatīdvayarohiṇīmūrvāśārṅgaṣṭāmūlāni ca śakalayitvā pṛthak triṃśatpalikāni saṅkṣudya mahati kaṭāhe 'ṣṭaguṇenāmbhasā kvāthayet aṣṭabhāgaśeṣaṃ niryūhamavatārya parisrāvya ca tasmin sarpiṣaḥ palaśatatrayaṃ vipacedīṣadavaśeṣakaṣāye ca vidalīkṛtāruṣkarasahasratrayamatrāvāpya punaḥ pācayedvigatasvarasānyaruṣkarāṇyapāsya tasmin snehe sucūrṇitāni prakṣipet vyādhighātavyoṣanākulīmārkavārkakākādanītagarakaṭukākuṣṭhabilvahiṅguviḍaṅgacitrakātiviṣāmustendrayavendravāruṇīrūpya malaloharajolohakāntarasāñjanābhraśukanāsādevadālītriphalālāṅgalikīviśālākumbhanikumbhavacāvārāhīmahādrumakośātakīprapunnāṭasomaparṇīnalikādvayapaṭolījātīpallavatāpyakāravellīkūlikākandakasaptacchadaśārṅgeṣṭotpalasārivāgugguluśilājatumūrvākustumbarījīvakadvayapāṭhendrurekhāvajrakandaharidrādvayalavaṇapañcakāni pratyekaṃ tripalikāni śṛṅgīviṣapalaṃ caikaṃ tato darvyā samantādāghaṭya suguptaṃ bhūmau dhānye vā māsaṃ nikhanet" },
      { type: "verse", number: "13", sanskrit: "अथ कृतसंशुद्धिस्वस्त्ययनः कुष्ठी प्रातस्ततो मात्रामुपयुञ्जीत जीर्णे च यथेष्टमाहारं तेनास्य पूर्वमङ्गानि तुद्यन्ते भिद्यन्ते शूयन्ते स्फुरन्ति स्फुटन्ति च ततः सप्तरात्रात् पुनः स्वस्थीभवन्ति अपि च", text: "atha kṛtasaṃśuddhisvastyayanaḥ kuṣṭhī prātastato mātrāmupayuñjīta jīrṇe ca yatheṣṭamāhāraṃ tenāsya pūrvamaṅgāni tudyante bhidyante śūyante sphuranti sphuṭanti ca tataḥ saptarātrāt punaḥ svasthībhavanti api ca" },
      { type: "verse", number: "14", sanskrit: "योगराजमवलिह्य समस्तं संज्ञयैव कथितोत्तमशक्तिम् हन्ति कुष्ठमतिपातितगात्रं स्नायुजालपरिशेषमशेषम्", text: "yogarājamavalihya samastaṃ saṃjñayaiva kathitottamaśaktim hanti kuṣṭhamatipātitagātraṃ snāyujālapariśeṣamaśeṣam" },
      { type: "verse", number: "15", sanskrit: "श्वासाग्निसादारुचिकासयक्ष्मगुल्माढ्यवातग्रहणीप्रमेहान् शोफं कृमीन् पाण्डुगदं ज्वरांश्च निवर्तयत्येष रसायनाग्र्यः", text: "śvāsāgnisādārucikāsayakṣmagulmāḍhyavātagrahaṇīpramehān śophaṃ kṛmīn pāṇḍugadaṃ jvarāṃśca nivartayatyeṣa rasāyanāgryaḥ" },
      { type: "verse", number: "16", sanskrit: "त्रिफलादशमूलमूर्वामुस्तसप्तच्छददारुनिम्बत्वग्गवाक्षीचित्रकमञ्जिष्ठाव्योषचूर्णं नवगुणैः सक्तुभिर्युक्तं सक्षौद्रं शीलयेत्", text: "triphalādaśamūlamūrvāmustasaptacchadadārunimbatvaggavākṣīcitrakamañjiṣṭhāvyoṣacūrṇaṃ navaguṇaiḥ saktubhiryuktaṃ sakṣaudraṃ śīlayet" },
      { type: "verse", number: "17", sanskrit: "अथवा क्षुण्णान्यवान् निस्तुषान् रात्रौ गोमूत्रपर्युषितानहनि किलिञ्जे शोषयेदेवं सप्ताहं भावयेच्छोषयेच्च ततस्तान् सक्तून् कृत्वा भल्लातकप्रपुन्नाटावल्गुजचित्रकविडङ्गमुस्तचूर्णचतुर्भागयुक्तानसनादिकषायेण पाययेत्", text: "athavā kṣuṇṇānyavān nistuṣān rātrau gomūtraparyuṣitānahani kiliñje śoṣayedevaṃ saptāhaṃ bhāvayecchoṣayecca tatastān saktūn kṛtvā bhallātakaprapunnāṭāvalgujacitrakaviḍaṅgamustacūrṇacaturbhāgayuktānasanādikaṣāyeṇa pāyayet" },
      { type: "verse", number: "18", sanskrit: "एवमसनादिक्वाथपीतानामारग्वधादिकषायपीतान वा गोजीर्णकानां वा यवानां सक्तूनरुष्कराग्निमन्थचूर्णमिश्रान् खदिरासनसाररोहितकगुडूचीनामन्यतमस्य कषायेण दाडिमाम्लवेतसाम्लेन सैन्धवलवणेन सितामधुमधुरेणालोड्य पाययेत् एष सर्वमन्थकल्पः यावकांश्च भक्ष्यानपूपपूर्णकोशशष्कुली प्रभृतीन् कुर्यात् यववच्च गोधूमैः", text: "evamasanādikvāthapītānāmāragvadhādikaṣāyapītāna vā gojīrṇakānāṃ vā yavānāṃ saktūnaruṣkarāgnimanthacūrṇamiśrān khadirāsanasārarohitakaguḍūcīnāmanyatamasya kaṣāyeṇa dāḍimāmlavetasāmlena saindhavalavaṇena sitāmadhumadhureṇāloḍya pāyayet eṣa sarvamanthakalpaḥ yāvakāṃśca bhakṣyānapūpapūrṇakośaśaṣkulī prabhṛtīn kuryāt yavavacca godhūmaiḥ" },
      { type: "verse", number: "19", sanskrit: "सुरां कल्पयेत् पलाशक्षारभावितशालितण्डुलपिष्टेन क्षारोदकेनैव स्वेदितेन प्रियङ्गुगजपिप्पलीचित्रककेबुकैलावालुकपरिपेलवलोध्रमरिचविडङ्गचूर्णमिश्रेण नवे चैनां भाजने जतुसृते क्षौद्रपिप्पलीलिप्ते स्थापयेत् ततो गन्धरसोपपन्नां कुष्ठिने पातुं दद्यात्", text: "surāṃ kalpayet palāśakṣārabhāvitaśālitaṇḍulapiṣṭena kṣārodakenaiva sveditena priyaṅgugajapippalīcitrakakebukailāvālukaparipelavalodhramaricaviḍaṅgacūrṇamiśreṇa nave caināṃ bhājane jatusṛte kṣaudrapippalīlipte sthāpayet tato gandharasopapannāṃ kuṣṭhine pātuṃ dadyāt" },
      { type: "verse", number: "20", sanskrit: "खदिरशिंशपासारमुत्तमकारणीं ब्रह्मीं कोशवतीं च कषायकल्पेन विपचेत् तेन क्वाथेन तण्डुलान् भावयेत् पिष्टं च स्वेदयेत् अभिषुणुयाच्च पूर्ववत्", text: "khadiraśiṃśapāsāramuttamakāraṇīṃ brahmīṃ kośavatīṃ ca kaṣāyakalpena vipacet tena kvāthena taṇḍulān bhāvayet piṣṭaṃ ca svedayet abhiṣuṇuyācca pūrvavat" },
      { type: "verse", number: "21", sanskrit: "त्रिवृच्छ्यामाग्निमन्थसप्तलाकेबुकशङ्खिनीतिल्वकत्रिफलापलाशशिंशपानां रसमादाय पलाशद्रोण्यामभ्यासिचय खदिराङ्गारतप्तमयःपिण्डमेकविंशतिवारान्निर्वाप्य ततस्तं रसमासिच्य स्थाल्यां गोमयाग्निना साधयेत् सिध्यति चावपेत् पिप्पलीचूर्णस्य भागं द्वौ मधुनस्तावद्घृतस्य ततश्चतुर्भागावशिष्टे ऽवतीर्णे भूयो ऽग्नितप्तमयःपिण्डं तस्मिन् प्रक्षिपेत् प्रशान्तं च लोहपात्रे सुगुप्तं निदध्यात् इयमयस्कृतिः दुस्साधमपि कुष्ठं मेहं वा साधयति स्थूलं कर्शयति शोफमुपहन्ति सन्नमग्निमुद्धरति विशेषेण राजयक्ष्मिणामुपदिश्यते वर्षशतायुश्चैनामुपयुज्य पुरुषो भवति", text: "trivṛcchyāmāgnimanthasaptalākebukaśaṅkhinītilvakatriphalāpalāśaśiṃśapānāṃ rasamādāya palāśadroṇyāmabhyāsicaya khadirāṅgārataptamayaḥpiṇḍamekaviṃśativārānnirvāpya tatastaṃ rasamāsicya sthālyāṃ gomayāgninā sādhayet sidhyati cāvapet pippalīcūrṇasya bhāgaṃ dvau madhunastāvadghṛtasya tataścaturbhāgāvaśiṣṭe 'vatīrṇe bhūyo 'gnitaptamayaḥpiṇḍaṃ tasmin prakṣipet praśāntaṃ ca lohapātre suguptaṃ nidadhyāt iyamayaskṛtiḥ dussādhamapi kuṣṭhaṃ mehaṃ vā sādhayati sthūlaṃ karśayati śophamupahanti sannamagnimuddharati viśeṣeṇa rājayakṣmiṇāmupadiśyate varṣaśatāyuścaināmupayujya puruṣo bhavati" },
      { type: "verse", number: "22", sanskrit: "असनादिक्वाथमासिच्य पलाशद्रोण्यमयोघनैस्तप्तैः संयोज्य निर्वाप्य च कृतसंस्कारे कलशे प्रक्षिप्य वत्सकादिं प्रतिवाप्य क्षौद्रं च सुगुप्तं मासं निधायोपयुञ्जीत", text: "asanādikvāthamāsicya palāśadroṇyamayoghanaistaptaiḥ saṃyojya nirvāpya ca kṛtasaṃskāre kalaśe prakṣipya vatsakādiṃ prativāpya kṣaudraṃ ca suguptaṃ māsaṃ nidhāyopayuñjīta" },
      { type: "verse", number: "23", sanskrit: "एवं न्यग्रोधादिष्वारग्वधादिषु चायस्कृतिं विदध्यात् खदिरसुरदारुक्वाथप्रस्थं क्षौद्रप्रस्थं मत्स्यण्डिकाप्प्रस्थं लोहचूर्णार्धप्रस्थं त्रिफलाचतुर्जातकमरिचानि च कार्षिकाणि प्रक्षिप्यायसे भाण्डे मासस्थितं तदुपयोजयेत्", text: "evaṃ nyagrodhādiṣvāragvadhādiṣu cāyaskṛtiṃ vidadhyāt khadirasuradārukvāthaprasthaṃ kṣaudraprasthaṃ matsyaṇḍikāpprasthaṃ lohacūrṇārdhaprasthaṃ triphalācaturjātakamaricāni ca kārṣikāṇi prakṣipyāyase bhāṇḍe māsasthitaṃ tadupayojayet" },
      { type: "verse", number: "24", sanskrit: "रसायनप्रयोगेण च लोहतुलां तुवरकास्थीनि भल्लातकान्यलम्बुषामवल्गुजं गुग्गुलुमर्शोविहितविधानेन वा चित्रकमिति", text: "rasāyanaprayogeṇa ca lohatulāṃ tuvarakāsthīni bhallātakānyalambuṣāmavalgujaṃ guggulumarśovihitavidhānena vā citrakamiti" },
      { type: "verse", number: "25", sanskrit: "भवति चात्र किलासकुष्ठग्रहणीप्रमेहस्थूलत्वदुर्नामभगन्दरेषु पाण्डुत्वशूनत्वकफामयेषु मन्थादियोगान् विदधीत धीमान्", text: "bhavati cātra kilāsakuṣṭhagrahaṇīpramehasthūlatvadurnāmabhagandareṣu pāṇḍutvaśūnatvakaphāmayeṣu manthādiyogān vidadhīta dhīmān" },
      { type: "verse", number: "26", sanskrit: "शालयो यवगोधूमकोरदूषाः प्रियङ्गवः मुद्गा मसूरास्तुवरी तिक्तशाकानि जाङ्गलम्", text: "śālayo yavagodhūmakoradūṣāḥ priyaṅgavaḥ mudgā masūrāstuvarī tiktaśākāni jāṅgalam" },
      { type: "verse", number: "27", sanskrit: "त्रिफलारुष्करारिष्टक्षौद्रयोजितभावितम् धात्रीखदिरनिम्बाम्बुरसं मुद्गपटोलजम्", text: "triphalāruṣkarāriṣṭakṣaudrayojitabhāvitam dhātrīkhadiranimbāmburasaṃ mudgapaṭolajam" },
      { type: "verse", number: "28", sanskrit: "मद्यान्यौषधगर्भाणि मथितं चेन्दुराजिमत् अन्नपानं हितं कुष्ठे न त्वम्ललवणोषणम् दधिदुग्धगुडानूपतिलमाषांस्त्यजेत्तराम्", text: "madyānyauṣadhagarbhāṇi mathitaṃ cendurājimat annapānaṃ hitaṃ kuṣṭhe na tvamlalavaṇoṣaṇam dadhidugdhaguḍānūpatilamāṣāṃstyajettarām" },
      { type: "verse", number: "29", sanskrit: "तुलार्धं निम्बपञ्चाङ्ग्यास्तथा खदिरसारतः हरीतकीदलतुलां भल्लातकतुलां दश", text: "tulārdhaṃ nimbapañcāṅgyāstathā khadirasārataḥ harītakīdalatulāṃ bhallātakatulāṃ daśa" },
      { type: "verse", number: "30", sanskrit: "कृष्णाविडङ्गकुडवावैकध्यं विपचेज्जले कषायं तं परिस्राव्य निदध्यात्ताम्रभाजने", text: "kṛṣṇāviḍaṅgakuḍavāvaikadhyaṃ vipacejjale kaṣāyaṃ taṃ parisrāvya nidadhyāttāmrabhājane" },
      { type: "verse", number: "31", sanskrit: "षण्मासतः पिबेत् कुष्ठकृमिमेहैर्विमुच्यते निम्बारिष्ट इति ख्यातो वरुणेनैष निर्मितः", text: "ṣaṇmāsataḥ pibet kuṣṭhakṛmimehairvimucyate nimbāriṣṭa iti khyāto varuṇenaiṣa nirmitaḥ" },
      { type: "verse", number: "32", sanskrit: "विडङ्गसारामलकाभयानां पलं पलं त्रीणि पलानि कुम्भात् गुडस्य च द्वादश मासमेष जितात्मना हन्त्युपयुज्यमानः", text: "viḍaṅgasārāmalakābhayānāṃ palaṃ palaṃ trīṇi palāni kumbhāt guḍasya ca dvādaśa māsameṣa jitātmanā hantyupayujyamānaḥ" },
      { type: "verse", number: "33", sanskrit: "कुष्ठश्चित्रश्वासकासोदरार्शोमेहप्लीहग्रन्थिरुग्जन्तुगुल्मान् सिद्धं योगं प्राह यक्षो मुमुह्षोर्भिक्षोः प्राणान् माणिभद्रः किलेमम्", text: "kuṣṭhaścitraśvāsakāsodarārśomehaplīhagranthirugjantugulmān siddhaṃ yogaṃ prāha yakṣo mumuhṣorbhikṣoḥ prāṇān māṇibhadraḥ kilemam" },
      { type: "verse", number: "34", sanskrit: "कटुकापटोलमूलोत्तमावचानिम्बरात्रिमञ्जिष्ठानाम् संशीलितःकषायस्त्वगामयान् श्लेष्मपित्तबहुलान् हन्ति", text: "kaṭukāpaṭolamūlottamāvacānimbarātrimañjiṣṭhānām saṃśīlitaḥkaṣāyastvagāmayān śleṣmapittabahulān hanti" },
      { type: "verse", number: "35", sanskrit: "वातोत्तरांस्तु सर्पिर्विपाचितं क्वथितकल्कितैश्च कटुकाद्यैः खदिरारिष्टगुडूचीसुरतरुदार्वीश्च कल्पयेत् पृथगेवम्", text: "vātottarāṃstu sarpirvipācitaṃ kvathitakalkitaiśca kaṭukādyaiḥ khadirāriṣṭaguḍūcīsuratarudārvīśca kalpayet pṛthagevam" },
      { type: "verse", number: "36", sanskrit: "शीतः कषायः खदिरस्य पीतः सक्षौद्रतार्क्ष्यो हरति प्रसह्य त्वक्कण्ठरोगापचिगुल्ममेहान् बलाहकान् वायुरिव प्रचण्डः", text: "śītaḥ kaṣāyaḥ khadirasya pītaḥ sakṣaudratārkṣyo harati prasahya tvakkaṇṭharogāpacigulmamehān balāhakān vāyuriva pracaṇḍaḥ" },
      { type: "verse", number: "37", sanskrit: "सर्पिर्मधुभ्यां त्रिफलारसेन विडङ्गकल्केन च सम्प्रयुक्तः कुष्ठं कषायः खदिरस्य हन्ति तिष्ठन् कषायं मनसीव धर्मः", text: "sarpirmadhubhyāṃ triphalārasena viḍaṅgakalkena ca samprayuktaḥ kuṣṭhaṃ kaṣāyaḥ khadirasya hanti tiṣṭhan kaṣāyaṃ manasīva dharmaḥ" },
      { type: "verse", number: "38", sanskrit: "खदिरस्य लूनशिरसो मूले खातस्य मध्यमं मूलम् छित्वाधो ऽयःकुम्भं रससंग्रहणाय निदधीत", text: "khadirasya lūnaśiraso mūle khātasya madhyamaṃ mūlam chitvādho 'yaḥkumbhaṃ rasasaṃgrahaṇāya nidadhīta" },
      { type: "verse", number: "39", sanskrit: "लिप्तात् कृष्णमृदेन्धनैश्च निचितादादीपिताद्वह्निना तस्माद्यश्च्यवते रसः स सहितः क्षौद्राज्यधात्रीरसैः पीतः कुष्ठभगन्दरारुरपचीमेहास्रपाण्डून् जयेत् प्रस्थस्तस्य जरां च भोज्यमिह तु त्याज्यं च भल्लातवत्", text: "liptāt kṛṣṇamṛdendhanaiśca nicitādādīpitādvahninā tasmādyaścyavate rasaḥ sa sahitaḥ kṣaudrājyadhātrīrasaiḥ pītaḥ kuṣṭhabhagandarārurapacīmehāsrapāṇḍūn jayet prasthastasya jarāṃ ca bhojyamiha tu tyājyaṃ ca bhallātavat" },
      { type: "verse", number: "40", sanskrit: "योज्य खदिरवन्निम्बशिंशपारग्वधासनम् रोहतिकं सुराह्वं च धदिरोदकपायिनः", text: "yojya khadiravannimbaśiṃśapāragvadhāsanam rohatikaṃ surāhvaṃ ca dhadirodakapāyinaḥ" },
      { type: "verse", number: "41", sanskrit: "दार्वी रसाञ्जनं वा गोमूत्रेण प्रबाधते कुष्ठम् अभया प्रयोजिता वा मासं सव्योषगुडतैला", text: "dārvī rasāñjanaṃ vā gomūtreṇa prabādhate kuṣṭham abhayā prayojitā vā māsaṃ savyoṣaguḍatailā" },
      { type: "verse", number: "42", sanskrit: "दर्वीकलिङ्गकटुकातिविषाग्निपाठामूत्रेण सूक्ष्मरजसो धरणप्रमाणाः पीता जयन्ति गुदजोदरगुल्मकुष्ठकोष्ठानिलाढ्यपवनग्रहणीप्रमेहान्", text: "darvīkaliṅgakaṭukātiviṣāgnipāṭhāmūtreṇa sūkṣmarajaso dharaṇapramāṇāḥ pītā jayanti gudajodaragulmakuṣṭhakoṣṭhānilāḍhyapavanagrahaṇīpramehān" },
      { type: "verse", number: "43", sanskrit: "लाक्षादन्तीमधुरसवराद्वीपिपाठाविडङ्गप्रत्यक्पुष्पीत्रिकटुरजनीसप्तपर्णाटरूषम्", text: "lākṣādantīmadhurasavarādvīpipāṭhāviḍaṅgapratyakpuṣpītrikaṭurajanīsaptaparṇāṭarūṣam" },
      { type: "verse", number: "44", sanskrit: "रक्ता निम्बं सुरतरुकृतं पञ्चमूल्यौ च चूर्णं पीत्वा मासं जयति हितभुग्गव्यमूत्रेण कुष्ठम्", text: "raktā nimbaṃ suratarukṛtaṃ pañcamūlyau ca cūrṇaṃ pītvā māsaṃ jayati hitabhuggavyamūtreṇa kuṣṭham" },
      { type: "verse", number: "45", sanskrit: "दशपलमरिष्टपल्लवकुसुमजटात्वक्फलं यथाकालम् प्रयाहरेत् समस्तं कृतमालतरोश्च तत्तद्वत्", text: "daśapalamariṣṭapallavakusumajaṭātvakphalaṃ yathākālam prayāharet samastaṃ kṛtamālatarośca tattadvat" },
      { type: "verse", number: "46", sanskrit: "सञ्चूर्ण्यासनखदिरक्वाथेनाप्लाव्य शोषयेदनिले चित्रकघनभल्लातकगोक्षुरकमहौषधत्रिफलाः", text: "sañcūrṇyāsanakhadirakvāthenāplāvya śoṣayedanile citrakaghanabhallātakagokṣurakamahauṣadhatriphalāḥ" },
      { type: "verse", number: "47", sanskrit: "लोहविडङ्गावल्गुजसितोपलाः पलसमा रजीकृत्य सप्ताहमेकतस्तद्रसेन भृङ्ग्यास्ततो भाव्यम्", text: "lohaviḍaṅgāvalgujasitopalāḥ palasamā rajīkṛtya saptāhamekatastadrasena bhṛṅgyāstato bhāvyam" },
      { type: "verse", number: "48", sanskrit: "अथ पीतमक्षमात्रं घृतेन दुग्धेन कोष्णसलिलैर्वा अचिरात् करोति वह्निं मतिं स्मृतिं पाटवं मेधाम्", text: "atha pītamakṣamātraṃ ghṛtena dugdhena koṣṇasalilairvā acirāt karoti vahniṃ matiṃ smṛtiṃ pāṭavaṃ medhām" },
      { type: "verse", number: "49", sanskrit: "कृमिकुष्ठगण्डपाण्डुप्रमेहवक्त्रामयारुचिच्छर्दीः अपचीभगन्दरस्थौल्यदुष्टनाडीव्रणव्यङ्गान्", text: "kṛmikuṣṭhagaṇḍapāṇḍupramehavaktrāmayārucicchardīḥ apacībhagandarasthaulyaduṣṭanāḍīvraṇavyaṅgān" },
      { type: "verse", number: "50", sanskrit: "कफपित्तजान् विकारान् विशेषतः सुविषमान् निवर्तयति वर्षाद्विषगरकृत्या नित्याभ्यासेन खलतिपलितानि", text: "kaphapittajān vikārān viśeṣataḥ suviṣamān nivartayati varṣādviṣagarakṛtyā nityābhyāsena khalatipalitāni" },
      { type: "verse", number: "51", sanskrit: "त्रिकटूत्तमातिलारुष्कराज्यमाक्षिकसितोपलाविहिता गुटिका रसायनं स्यात् कुष्ठजिच्च विष्या च सप्तसमा", text: "trikaṭūttamātilāruṣkarājyamākṣikasitopalāvihitā guṭikā rasāyanaṃ syāt kuṣṭhajicca viṣyā ca saptasamā" },
      { type: "verse", number: "52", sanskrit: "चन्द्रशकलाग्निरजनीविडङ्गतुवरास्थ्यरुष्करत्रिफलाभिः वटका गुडांशक्लृप्ताः समस्तकुष्ठानि नाशयन्त्यभ्यस्ताः", text: "candraśakalāgnirajanīviḍaṅgatuvarāsthyaruṣkaratriphalābhiḥ vaṭakā guḍāṃśaklṛptāḥ samastakuṣṭhāni nāśayantyabhyastāḥ" },
      { type: "verse", number: "53", sanskrit: "विडङ्गभल्लातकबाकुचीनां सद्वीपिवाराहिहरीतकीनाम् सलाङ्गलीकृष्णतिकोपकुल्या गुडेन पिण्डी विनिहन्ति कुष्ठम्", text: "viḍaṅgabhallātakabākucīnāṃ sadvīpivārāhiharītakīnām salāṅgalīkṛṣṇatikopakulyā guḍena piṇḍī vinihanti kuṣṭham" },
      { type: "verse", number: "54", sanskrit: "पथ्याकलिङ्गकपलाशफलेन्दुराजीभल्लातकास्थिचतुरङ्गुलचित्रकार्कैः सावर्तकीकृमिहरैः क्रमवर्धितांशैः मूत्रेण तुल्यतुवरैर्वटका गदघ्नाः", text: "pathyākaliṅgakapalāśaphalendurājībhallātakāsthicaturaṅgulacitrakārkaiḥ sāvartakīkṛmiharaiḥ kramavardhitāṃśaiḥ mūtreṇa tulyatuvarairvaṭakā gadaghnāḥ" },
      { type: "verse", number: "55", sanskrit: "शशाङ्कलेखा सविडङ्गसारा सपिप्पलीका सहुताशमूला सायोमला सामलका सतैला कुष्ठानि कृच्छ्राणि निहन्ति लीढा", text: "śaśāṅkalekhā saviḍaṅgasārā sapippalīkā sahutāśamūlā sāyomalā sāmalakā satailā kuṣṭhāni kṛcchrāṇi nihanti līḍhā" },
      { type: "verse", number: "56", sanskrit: "भूनिम्बनिम्बत्रिफलापद्मकातिविषाकणाः मूर्वापटोलीद्विनिशापाठातिक्तेन्द्रवारुणीः", text: "bhūnimbanimbatriphalāpadmakātiviṣākaṇāḥ mūrvāpaṭolīdviniśāpāṭhātiktendravāruṇīḥ" },
      { type: "verse", number: "57", sanskrit: "सकलिङ्गवचास्तुल्या द्विगुणाश्च यथोत्तरम् लिह्याद्दन्तीत्रिवृद्ब्राह्मीश्चूर्णिता मधुसर्पिषा", text: "sakaliṅgavacāstulyā dviguṇāśca yathottaram lihyāddantītrivṛdbrāhmīścūrṇitā madhusarpiṣā" },
      { type: "verse", number: "58", sanskrit: "कुष्ठमेहप्रसुप्तीनां परमं स्यात्तदौषधम् वराकणाविडङ्गान् वा लिह्यात्तैलाज्यमाक्षिकैः", text: "kuṣṭhamehaprasuptīnāṃ paramaṃ syāttadauṣadham varākaṇāviḍaṅgān vā lihyāttailājyamākṣikaiḥ" },
      { type: "verse", number: "59", sanskrit: "खदिरशकलचूर्णं क्षौद्रसर्पिर्विमिश्रं सगिरिजतुविडङ्गं मात्रया सेवमानः लघुमितहितभोजी ब्रह्मचारी जितात्मा श्वयथुकिटिभकोठश्वित्रकुष्ठानि हन्यात्", text: "khadiraśakalacūrṇaṃ kṣaudrasarpirvimiśraṃ sagirijatuviḍaṅgaṃ mātrayā sevamānaḥ laghumitahitabhojī brahmacārī jitātmā śvayathukiṭibhakoṭhaśvitrakuṣṭhāni hanyāt" },
      { type: "verse", number: "60", sanskrit: "खदिरासनसारस्य तुलां द्रोणे ऽम्भसः क्षिपेत् अष्टमे ऽहनि तत्तोयं पचेदादर्विलेपनात्", text: "khadirāsanasārasya tulāṃ droṇe 'mbhasaḥ kṣipet aṣṭame 'hani tattoyaṃ pacedādarvilepanāt" },
      { type: "verse", number: "61", sanskrit: "त्रिफलार्धतुलाचूर्णं तत्पादेन तु बाकुचीम् तदर्धं द्वीपिनो मूलं तद्वद्ब्राह्मीं समार्कवाम्", text: "triphalārdhatulācūrṇaṃ tatpādena tu bākucīm tadardhaṃ dvīpino mūlaṃ tadvadbrāhmīṃ samārkavām" },
      { type: "verse", number: "62", sanskrit: "लोहक्रिमिघ्नद्विप्रस्थं क्षिप्त्वा तद्वटकीकृतम् कुष्ठमेहग्रहण्यर्शोभगन्दरिषु पूजितम्", text: "lohakrimighnadviprasthaṃ kṣiptvā tadvaṭakīkṛtam kuṣṭhamehagrahaṇyarśobhagandariṣu pūjitam" },
      { type: "verse", number: "63", sanskrit: "लाङ्गलीत्रिफलालोहचूर्णं दशपलं पृथक् गुटिकात्रिशतं षष्टिं कुर्याद्भृङ्गरसाप्लुतम्", text: "lāṅgalītriphalālohacūrṇaṃ daśapalaṃ pṛthak guṭikātriśataṃ ṣaṣṭiṃ kuryādbhṛṅgarasāplutam" },
      { type: "verse", number: "64", sanskrit: "छायाशुष्कां च तत्रार्धगुटिकां भक्षयेत् पुरः जीर्णे रसेन रूक्षेण पेयापूर्वं च भोजयेत्", text: "chāyāśuṣkāṃ ca tatrārdhaguṭikāṃ bhakṣayet puraḥ jīrṇe rasena rūkṣeṇa peyāpūrvaṃ ca bhojayet" },
      { type: "verse", number: "65", sanskrit: "यन्त्रितो ब्रह्मचर्याद्यैः क्रमेण गुटिकामपि खादेत् परस्तान्मासस्य भवेत् कामचरः क्रमात्", text: "yantrito brahmacaryādyaiḥ krameṇa guṭikāmapi khādet parastānmāsasya bhavet kāmacaraḥ kramāt" },
      { type: "verse", number: "66", sanskrit: "एवं सर्वाणि कुष्ठानि जयत्यतिबलान्यपि धीमेधास्मृतियुक्तश्च नीरुग्जीवेत् समाः शतम्", text: "evaṃ sarvāṇi kuṣṭhāni jayatyatibalānyapi dhīmedhāsmṛtiyuktaśca nīrugjīvet samāḥ śatam" },
      { type: "verse", number: "67", sanskrit: "वासामृतानिम्बवरापटोलव्याघ्रीकरञ्जोदककल्कपक्वम् सर्पिर्विंसर्पज्वरकामलास्रकुष्ठापहं वज्रकमामनन्ति", text: "vāsāmṛtānimbavarāpaṭolavyāghrīkarañjodakakalkapakvam sarpirviṃsarpajvarakāmalāsrakuṣṭhāpahaṃ vajrakamāmananti" },
      { type: "verse", number: "68", sanskrit: "त्रिफलात्रिकटुद्विकण्टकारीकटुकाकुम्भनिकुम्भराजवृक्षैः सवचातिविषाग्निकैः सपाठैः पिचुभागैर्नववज्रदुग्धमुष्ट्या", text: "triphalātrikaṭudvikaṇṭakārīkaṭukākumbhanikumbharājavṛkṣaiḥ savacātiviṣāgnikaiḥ sapāṭhaiḥ picubhāgairnavavajradugdhamuṣṭyā" },
      { type: "verse", number: "69", sanskrit: "पिष्टैः सिद्धं सर्पिषः प्रस्थमेभिः क्रूरे कोष्ठे स्नेहनं रेचनं च कुष्ठश्वित्रप्लीहवर्ध्माश्मगुल्मान् हन्यात् कृच्छ्रांस्तन्महावज्रकाख्यम्", text: "piṣṭaiḥ siddhaṃ sarpiṣaḥ prasthamebhiḥ krūre koṣṭhe snehanaṃ recanaṃ ca kuṣṭhaśvitraplīhavardhmāśmagulmān hanyāt kṛcchrāṃstanmahāvajrakākhyam" },
      { type: "verse", number: "70", sanskrit: "यतेर्लेलीतकवसा क्षौद्रजातीरसान्विता कुष्ठघ्नी समसर्पिर्वा सगायत्र्यसनोदका", text: "yaterlelītakavasā kṣaudrajātīrasānvitā kuṣṭhaghnī samasarpirvā sagāyatryasanodakā" },
      { type: "verse", number: "71", sanskrit: "मूत्रे विनीता त्रिफलारसे वा सिद्धा घृते वाम्भसि केवले वा रसायनं पथ्यभुजो हरिद्रा निहन्ति पाण्ड्वामयकुष्ठमेहान्", text: "mūtre vinītā triphalārase vā siddhā ghṛte vāmbhasi kevale vā rasāyanaṃ pathyabhujo haridrā nihanti pāṇḍvāmayakuṣṭhamehān" },
      { type: "verse", number: "72", sanskrit: "पिबेदमृतवल्या वा स्वरसं यन्त्रपीडितम् मेध्यं तत् कुष्ठमेहार्शश्छर्दिवातास्रनाशनम्", text: "pibedamṛtavalyā vā svarasaṃ yantrapīḍitam medhyaṃ tat kuṣṭhamehārśaśchardivātāsranāśanam" },
      { type: "verse", number: "73", sanskrit: "स्थिरकठिनमण्डलानां कुष्ठानां पोट्टलैर्हितः स्वेदः स्विन्नोत्सन्नं विलिखेत् कुष्ठं तीक्ष्णेन शस्त्रेण", text: "sthirakaṭhinamaṇḍalānāṃ kuṣṭhānāṃ poṭṭalairhitaḥ svedaḥ svinnotsannaṃ vilikhet kuṣṭhaṃ tīkṣṇena śastreṇa" },
      { type: "verse", number: "74", sanskrit: "रुधिरागमार्थमथवाशृङ्गालाबूभिरपहरेद्रक्तम् प्रच्छेदल्पं कुष्ठं निरेचयेद्वा जलौकोभिः", text: "rudhirāgamārthamathavāśṛṅgālābūbhirapaharedraktam pracchedalpaṃ kuṣṭhaṃ nirecayedvā jalaukobhiḥ" },
      { type: "verse", number: "75", sanskrit: "ये लेपाः कुष्ठानां युज्यन्ते निर्हृतास्रदोषाणाम् संशोधिताशयानां सद्यः सिद्धिर्भवति तेषाम्", text: "ye lepāḥ kuṣṭhānāṃ yujyante nirhṛtāsradoṣāṇām saṃśodhitāśayānāṃ sadyaḥ siddhirbhavati teṣām" },
      { type: "verse", number: "76", sanskrit: "येषु न शस्त्रं क्रमते स्पर्शेन्द्रियनाशनेषु कुष्ठेषु तेषु निपात्यः क्षारो रक्तं दोषं च विस्राव्य", text: "yeṣu na śastraṃ kramate sparśendriyanāśaneṣu kuṣṭheṣu teṣu nipātyaḥ kṣāro raktaṃ doṣaṃ ca visrāvya" },
      { type: "verse", number: "77", sanskrit: "लेपो ऽतिकठिनपरुषे सुप्ते कुष्ठे स्थिरे पुराणे च पीतागदस्य कार्यो विषैः समन्त्रागदैश्चानु", text: "lepo 'tikaṭhinaparuṣe supte kuṣṭhe sthire purāṇe ca pītāgadasya kāryo viṣaiḥ samantrāgadaiścānu" },
      { type: "verse", number: "78", sanskrit: "स्तब्धानि सुप्तसुप्तान्यस्वेदनकण्डुलानि कुष्ठानि कूर्चैर्दन्तीत्रिवृताकरवीरकरञ्जकुटजानाम्", text: "stabdhāni suptasuptānyasvedanakaṇḍulāni kuṣṭhāni kūrcairdantītrivṛtākaravīrakarañjakuṭajānām" },
      { type: "verse", number: "79", sanskrit: "जात्यर्कनिम्बजैर्वा पत्रैः शस्त्रैः समुद्रफेनेन घृष्टानि गोमयैर्वा ततः प्रदेहैः प्रदेह्यानि", text: "jātyarkanimbajairvā patraiḥ śastraiḥ samudraphenena ghṛṣṭāni gomayairvā tataḥ pradehaiḥ pradehyāni" },
      { type: "verse", number: "80", sanskrit: "आरग्वधः सैडगजः करञ्जो वासा गुडूची मदनं हरिद्रे श्र्याह्वः सुराह्वः खदिरो धवश्च निम्बो विडङ्गः करवीरकश्च", text: "āragvadhaḥ saiḍagajaḥ karañjo vāsā guḍūcī madanaṃ haridre śryāhvaḥ surāhvaḥ khadiro dhavaśca nimbo viḍaṅgaḥ karavīrakaśca" },
      { type: "verse", number: "81", sanskrit: "ग्रन्थिश्च भूर्जो लशुनः शिरीषः सलोमशो गुग्गुलुकृष्णगन्धे फणिज्जको वत्सकसप्तपर्णपीलूनि कुष्ठं सुमनःप्रवालाः", text: "granthiśca bhūrjo laśunaḥ śirīṣaḥ salomaśo guggulukṛṣṇagandhe phaṇijjako vatsakasaptaparṇapīlūni kuṣṭhaṃ sumanaḥpravālāḥ" },
      { type: "verse", number: "82", sanskrit: "वचाहरेणुस्त्रिवृता निकुम्भो भल्लातकं गैरिकमञ्जनं च मनःशिलाले गृहधूम एला कासीसलोध्रार्जुनमुस्तसर्जाः", text: "vacāhareṇustrivṛtā nikumbho bhallātakaṃ gairikamañjanaṃ ca manaḥśilāle gṛhadhūma elā kāsīsalodhrārjunamustasarjāḥ" },
      { type: "verse", number: "83", sanskrit: "इत्यर्धरूपैर्विहिताः षडेते गोपित्तपीताः पुनरेव पिष्टाः सिद्धाः परं सर्षपतैलयुक्ताश्चूर्णाः प्रदेहा बहुशाः प्रयोज्याः", text: "ityardharūpairvihitāḥ ṣaḍete gopittapītāḥ punareva piṣṭāḥ siddhāḥ paraṃ sarṣapatailayuktāścūrṇāḥ pradehā bahuśāḥ prayojyāḥ" },
      { type: "verse", number: "84", sanskrit: "कुष्ठानि कृच्छ्राणि नवं किलासं सुरेन्द्रलुप्तं किटिभं सदद्रुम् भगन्दरार्शांस्यपचीं सपामां हन्युः प्रयुक्तानचिरान्नराणाम्", text: "kuṣṭhāni kṛcchrāṇi navaṃ kilāsaṃ surendraluptaṃ kiṭibhaṃ sadadrum bhagandarārśāṃsyapacīṃ sapāmāṃ hanyuḥ prayuktānacirānnarāṇām" },
      { type: "verse", number: "85", sanskrit: "निम्बं हरिद्रे सुरसं पटोलं कुष्ठाश्वगन्धे सुरदारुशिग्रु ससर्षपं तुम्बुरुधान्यवन्यं चण्डां च चूर्णानि समानि कुर्यात्", text: "nimbaṃ haridre surasaṃ paṭolaṃ kuṣṭhāśvagandhe suradāruśigru sasarṣapaṃ tumburudhānyavanyaṃ caṇḍāṃ ca cūrṇāni samāni kuryāt" },
      { type: "verse", number: "86", sanskrit: "तैस्तक्रपिष्टैः प्रथमं शरीरं तैलाक्तमुद्वर्तयितुं यतेत तथास्य कण्डूःपिटकाः सकोठाः कुष्ठानि शोफाश्च शमं व्रजन्ति", text: "taistakrapiṣṭaiḥ prathamaṃ śarīraṃ tailāktamudvartayituṃ yateta tathāsya kaṇḍūḥpiṭakāḥ sakoṭhāḥ kuṣṭhāni śophāśca śamaṃ vrajanti" },
      { type: "verse", number: "87", sanskrit: "मुस्तामृतासङ्गकटङ्कटेरीकासीसकम्पिल्लककुष्ठलोध्राः गन्धोपलः सर्जरसं विडङ्गं मनःशिलाले करवीरकत्वक्", text: "mustāmṛtāsaṅgakaṭaṅkaṭerīkāsīsakampillakakuṣṭhalodhrāḥ gandhopalaḥ sarjarasaṃ viḍaṅgaṃ manaḥśilāle karavīrakatvak" },
      { type: "verse", number: "88", sanskrit: "तैलक्तगात्रस्य कृतानि चूर्णान्येतानि दद्यादवचूर्णनार्थम् दद्रुःसकण्डूः किटिभानि पामा विचर्चिका चेति तथा न सन्ति", text: "tailaktagātrasya kṛtāni cūrṇānyetāni dadyādavacūrṇanārtham dadruḥsakaṇḍūḥ kiṭibhāni pāmā vicarcikā ceti tathā na santi" },
      { type: "verse", number: "89", sanskrit: "काण्डे महावृक्षभवे निलीनः स्विन्नः कुकूले पुटपाकयुक्त्या विचर्चिकां सर्षपकल्कपिण्डो निहन्ति लज्जामिव रागवेगः", text: "kāṇḍe mahāvṛkṣabhave nilīnaḥ svinnaḥ kukūle puṭapākayuktyā vicarcikāṃ sarṣapakalkapiṇḍo nihanti lajjāmiva rāgavegaḥ" },
      { type: "verse", number: "90", sanskrit: "मनःशिलाले मरिचानि तैलमार्कं पयः कुष्ठहरः प्रदेहः तथा करञ्जप्रपुनाटबीजं कुष्ठान्वितं गोसलिलेन पिष्टम्", text: "manaḥśilāle maricāni tailamārkaṃ payaḥ kuṣṭhaharaḥ pradehaḥ tathā karañjaprapunāṭabījaṃ kuṣṭhānvitaṃ gosalilena piṣṭam" },
      { type: "verse", number: "91", sanskrit: "गुग्गुलुमरिचविडङ्गैः सर्षपकासीससर्जरसमुस्तैः श्रीवेष्टकालगन्धैर्मनःशिलाकुष्ठकम्पिल्लैः", text: "guggulumaricaviḍaṅgaiḥ sarṣapakāsīsasarjarasamustaiḥ śrīveṣṭakālagandhairmanaḥśilākuṣṭhakampillaiḥ" },
      { type: "verse", number: "92", sanskrit: "उभयहरिद्रासहितैश्चात्रिकतैलेन मिश्रितैरेभिः दिनकरकराभितप्तैः कुष्ठं घृष्टं च नष्टं च", text: "ubhayaharidrāsahitaiścātrikatailena miśritairebhiḥ dinakarakarābhitaptaiḥ kuṣṭhaṃ ghṛṣṭaṃ ca naṣṭaṃ ca" },
      { type: "verse", number: "93", sanskrit: "मरिचं तमालपत्रं कुष्ठं समनःशिलं सकासीसम् तैलेन युक्तमुषितं सप्ताहं भाजने ताम्रे", text: "maricaṃ tamālapatraṃ kuṣṭhaṃ samanaḥśilaṃ sakāsīsam tailena yuktamuṣitaṃ saptāhaṃ bhājane tāmre" },
      { type: "verse", number: "94", sanskrit: "तेनालिप्तं सिध्म सप्ताहात् घर्मसेविनो ऽपैति मासान्नवं किलासं स्नानेन विना विशुद्धस्य", text: "tenāliptaṃ sidhma saptāhāt gharmasevino 'paiti māsānnavaṃ kilāsaṃ snānena vinā viśuddhasya" },
      { type: "verse", number: "95", sanskrit: "मयूरकं जर्जरितं समूलं दग्ध्वा परिस्राव्य च सप्तकृत्वः तेनाम्भसा कङ्गुणिकोत्थतैलं सिद्धं परं सिध्मनिबर्हणाय", text: "mayūrakaṃ jarjaritaṃ samūlaṃ dagdhvā parisrāvya ca saptakṛtvaḥ tenāmbhasā kaṅguṇikotthatailaṃ siddhaṃ paraṃ sidhmanibarhaṇāya" },
      { type: "verse", number: "96", sanskrit: "जीवन्ती मञ्जिष्ठा दार्वी काम्पिल्लकं पयस्तुत्थम् एष घृततैलपाकः सिद्धः सिद्धे च सर्जरसः", text: "jīvantī mañjiṣṭhā dārvī kāmpillakaṃ payastuttham eṣa ghṛtatailapākaḥ siddhaḥ siddhe ca sarjarasaḥ" },
      { type: "verse", number: "97", sanskrit: "देयः समधूच्छिष्टो विपादिका तेन नश्यति ह्यक्ता चर्मैर्कुष्ठकिटिभं कुष्ठं शाम्यत्यलसकं च", text: "deyaḥ samadhūcchiṣṭo vipādikā tena naśyati hyaktā carmairkuṣṭhakiṭibhaṃ kuṣṭhaṃ śāmyatyalasakaṃ ca" },
      { type: "verse", number: "98", sanskrit: "सप्तपर्णकरञ्जार्कमालतीकरवीरजम् मूलं स्नुहीशिरीषाभ्यां चित्रकास्फोतयोरपि", text: "saptaparṇakarañjārkamālatīkaravīrajam mūlaṃ snuhīśirīṣābhyāṃ citrakāsphotayorapi" },
      { type: "verse", number: "99", sanskrit: "करञ्जबीजद्विनिशाव्योषैडगजसर्षपाः वरा वेल्लं च तैस्तैलं सगोमूत्रैर्विपाचितम्", text: "karañjabījadviniśāvyoṣaiḍagajasarṣapāḥ varā vellaṃ ca taistailaṃ sagomūtrairvipācitam" },
      { type: "verse", number: "100", sanskrit: "कुष्ठदुष्टव्रणग्रन्थिगण्डमालाभगन्दरान् विशेषाद्वातकफजान् हन्त्यभ्यङ्गेन वज्रकम्", text: "kuṣṭhaduṣṭavraṇagranthigaṇḍamālābhagandarān viśeṣādvātakaphajān hantyabhyaṅgena vajrakam" },
      { type: "verse", number: "101", sanskrit: "एरण्डतार्क्ष्यघननीपकदम्बभार्ङ्गीकम्पिल्लवेल्लफलिनीसुरवारुणीभिः निर्गुण्ड्यरुष्करसुराह्वसुवर्णदुग्धाश्रीवेष्टगुग्गुलुशिलाहरितालविश्वैः", text: "eraṇḍatārkṣyaghananīpakadambabhārṅgīkampillavellaphalinīsuravāruṇībhiḥ nirguṇḍyaruṣkarasurāhvasuvarṇadugdhāśrīveṣṭagugguluśilāharitālaviśvaiḥ" },
      { type: "verse", number: "102", sanskrit: "तुल्यस्नुगर्कदुग्धं सिद्धं तैलं स्मृतं महावज्रम् अतिशयितवज्रकगुणं श्वित्रार्शोग्रन्थिमालाघ्नम्", text: "tulyasnugarkadugdhaṃ siddhaṃ tailaṃ smṛtaṃ mahāvajram atiśayitavajrakaguṇaṃ śvitrārśogranthimālāghnam" },
      { type: "verse", number: "103", sanskrit: "कनकक्षीरी शैला भार्ङ्गी दन्त्याः फलानि मूलं च जातीप्रवालसर्षपलशुनविडङ्गं करञ्जत्वक्", text: "kanakakṣīrī śailā bhārṅgī dantyāḥ phalāni mūlaṃ ca jātīpravālasarṣapalaśunaviḍaṅgaṃ karañjatvak" },
      { type: "verse", number: "104", sanskrit: "सप्तच्छदार्कपल्लवमूलत्वङ्निम्बचित्रकास्फोतम् गुञ्जैरण्डकबृहतीमूलत्वक्सुरसार्जकफलानि", text: "saptacchadārkapallavamūlatvaṅnimbacitrakāsphotam guñjairaṇḍakabṛhatīmūlatvaksurasārjakaphalāni" },
      { type: "verse", number: "105", sanskrit: "कुष्ठं पाठा मुस्ता षड्ग्रन्थातुम्बुरुत्वचो मूर्वा एडगजकुटजशिग्रुत्र्यूषणभल्लातकक्षवकाः", text: "kuṣṭhaṃ pāṭhā mustā ṣaḍgranthātumburutvaco mūrvā eḍagajakuṭajaśigrutryūṣaṇabhallātakakṣavakāḥ" },
      { type: "verse", number: "106", sanskrit: "हरितालमवाक्पुष्पी तुत्थं कम्पिल्लको ऽमृतासङ्गः सौराष्ट्री कासीसं दार्वीत्वक् स्वर्जिकालवणम्", text: "haritālamavākpuṣpī tutthaṃ kampillako 'mṛtāsaṅgaḥ saurāṣṭrī kāsīsaṃ dārvītvak svarjikālavaṇam" },
      { type: "verse", number: "107", sanskrit: "एतैस्तैलं तैलं कटुतैलं वा चतुर्गुणे मूत्रे करवीरमूलपल्लवतोये च विपाचितं जयति", text: "etaistailaṃ tailaṃ kaṭutailaṃ vā caturguṇe mūtre karavīramūlapallavatoye ca vipācitaṃ jayati" },
      { type: "verse", number: "108", sanskrit: "कटुकालाबुन्यस्तं जित्याभ्यङ्गेन वातकफकुष्ठम् मण्डलदद्रूकोष्ठकृमिपामाविचर्चिकाः सुतराम्", text: "kaṭukālābunyastaṃ jityābhyaṅgena vātakaphakuṣṭham maṇḍaladadrūkoṣṭhakṛmipāmāvicarcikāḥ sutarām" },
      { type: "verse", number: "109", sanskrit: "सिक्थकतुत्थकगुग्गुलुसिन्दूररसाञ्जनैः कटुकतैलम् पामाकिटिभविचर्चिषु साधितमभ्यञ्जने श्रेष्ठम्", text: "sikthakatutthakaguggulusindūrarasāñjanaiḥ kaṭukatailam pāmākiṭibhavicarciṣu sādhitamabhyañjane śreṣṭham" },
      { type: "verse", number: "110", sanskrit: "शैलेयकम्पिल्लकपट्टिकाह्वसुराष्ट्रजासर्जरसोपलानि शिला च चूर्णो नवनीतयुक्तं कुष्ठे स्रवत्यभ्यधिकं प्रशस्तः", text: "śaileyakampillakapaṭṭikāhvasurāṣṭrajāsarjarasopalāni śilā ca cūrṇo navanītayuktaṃ kuṣṭhe sravatyabhyadhikaṃ praśastaḥ" },
      { type: "verse", number: "111", sanskrit: "एडगजकुष्ठसैन्धवसिद्धार्थविडङ्गकाञ्जिकैर्लिप्तम् कृमिपामासिध्मदद्रूमण्डलकुष्ठं शमं याति", text: "eḍagajakuṣṭhasaindhavasiddhārthaviḍaṅgakāñjikairliptam kṛmipāmāsidhmadadrūmaṇḍalakuṣṭhaṃ śamaṃ yāti" },
      { type: "verse", number: "112", sanskrit: "लाक्षाव्योषं प्रापुनाटं च बीजं सश्रीवेष्टाः कुष्ठसिद्धार्थकाश्च तक्रोन्मिश्रः स्याद्धरिद्रा च लेपो दद्रूषूक्तो मूलकोत्थं च बीजम्", text: "lākṣāvyoṣaṃ prāpunāṭaṃ ca bījaṃ saśrīveṣṭāḥ kuṣṭhasiddhārthakāśca takronmiśraḥ syāddharidrā ca lepo dadrūṣūkto mūlakotthaṃ ca bījam" },
      { type: "verse", number: "113", sanskrit: "दूर्वाभयासैन्धवचक्रमर्द कुष्ठेरकाः काञ्जिकतक्रपिष्टाः त्रिभिः प्रलेपैरपि बद्धमूलां दद्रूं च कण्डूं च विनाशयन्ति", text: "dūrvābhayāsaindhavacakramarda kuṣṭherakāḥ kāñjikatakrapiṣṭāḥ tribhiḥ pralepairapi baddhamūlāṃ dadrūṃ ca kaṇḍūṃ ca vināśayanti" },
      { type: "verse", number: "114", sanskrit: "मनःशिलात्वक्कुटजं सकुष्ठं सलोमशः सैडगजः करञ्जः ग्रन्थिश्च भौर्जः करवीरमूलं चूर्णानि साध्यानि तुषोदकेन", text: "manaḥśilātvakkuṭajaṃ sakuṣṭhaṃ salomaśaḥ saiḍagajaḥ karañjaḥ granthiśca bhaurjaḥ karavīramūlaṃ cūrṇāni sādhyāni tuṣodakena" },
      { type: "verse", number: "115", sanskrit: "पलाशनिर्दाहरसेन वापि कर्षोन्मितान्याढक सम्मितेन दर्वीप्रलेपं प्रवदन्ति लेपमेतत् परं कुष्ठनिषूदनाय", text: "palāśanirdāharasena vāpi karṣonmitānyāḍhaka sammitena darvīpralepaṃ pravadanti lepametat paraṃ kuṣṭhaniṣūdanāya" },
      { type: "verse", number: "116", sanskrit: "एलाचित्रकनिम्बवृषकं कुरुविन्दनागरार्कं च चूर्णीकृतमष्टाहं भावयितव्यं पलाशस्य", text: "elācitrakanimbavṛṣakaṃ kuruvindanāgarārkaṃ ca cūrṇīkṛtamaṣṭāhaṃ bhāvayitavyaṃ palāśasya" },
      { type: "verse", number: "117", sanskrit: "क्षारेण गवां मूत्रस्रुतेन तेनास्य मण्डलान्याशु भिद्यन्ते दीर्यन्ति च लिप्तान्यर्काभितप्तानि", text: "kṣāreṇa gavāṃ mūtrasrutena tenāsya maṇḍalānyāśu bhidyante dīryanti ca liptānyarkābhitaptāni" },
      { type: "verse", number: "118", sanskrit: "मांसी मरिचं लवणं रजनी तगरं सुधा गृहाद्धूमः मूत्रं पित्तं क्षारः पालाशः कुष्ठनुल्लेपः", text: "māṃsī maricaṃ lavaṇaṃ rajanī tagaraṃ sudhā gṛhāddhūmaḥ mūtraṃ pittaṃ kṣāraḥ pālāśaḥ kuṣṭhanullepaḥ" },
      { type: "verse", number: "119", sanskrit: "मुस्तं त्रिफला मदनं करञ्ज आरग्वधः कलिङ्गयवाः ससप्ताह्वकुष्ठफलिनीदार्व्यःसिद्धार्थकं स्नानम्", text: "mustaṃ triphalā madanaṃ karañja āragvadhaḥ kaliṅgayavāḥ sasaptāhvakuṣṭhaphalinīdārvyaḥsiddhārthakaṃ snānam" },
      { type: "verse", number: "120", sanskrit: "एष कषायो वमनं विरेचनं वर्णदस्तथोद्घर्षः त्वग्दोषकुष्ठशोफप्रबाधनः पाण्डुरोगघ्नः", text: "eṣa kaṣāyo vamanaṃ virecanaṃ varṇadastathodgharṣaḥ tvagdoṣakuṣṭhaśophaprabādhanaḥ pāṇḍurogaghnaḥ" },
      { type: "verse", number: "121", sanskrit: "करवीरनिम्बकुटजाच्छम्याकाच्चित्रकाच्च मूलानाम् मूत्रे दर्वीलेपः क्वाथो लेपेन कुष्ठघ्नः", text: "karavīranimbakuṭajācchamyākāccitrakācca mūlānām mūtre darvīlepaḥ kvātho lepena kuṣṭhaghnaḥ" },
      { type: "verse", number: "122", sanskrit: "श्वेतकरवीरमूलं कुटजकरञ्जात् फलं त्वचो दार्व्याः सुमनःप्रवालयुक्तो लेपः कुष्ठापहः सिद्धः", text: "śvetakaravīramūlaṃ kuṭajakarañjāt phalaṃ tvaco dārvyāḥ sumanaḥpravālayukto lepaḥ kuṣṭhāpahaḥ siddhaḥ" },
      { type: "verse", number: "123", sanskrit: "शैरीषी त्वक् पुष्पं कार्पास्या राजवृक्षपत्राणि पिष्टा च काकमाची चतुर्विधः कुष्ठहा लेपः", text: "śairīṣī tvak puṣpaṃ kārpāsyā rājavṛkṣapatrāṇi piṣṭā ca kākamācī caturvidhaḥ kuṣṭhahā lepaḥ" },
      { type: "verse", number: "124", sanskrit: "दार्वीरसाञ्जनस्य च निम्बपटोलस्य खदिरसारस्य आरग्वधवृक्षकयोस्त्रिफलायाः सप्तपर्णस्य", text: "dārvīrasāñjanasya ca nimbapaṭolasya khadirasārasya āragvadhavṛkṣakayostriphalāyāḥ saptaparṇasya" },
      { type: "verse", number: "125", sanskrit: "इति षट् कषाययोगाः कुष्ठघ्नाः सप्तमश्च तिनिशस्य स्नाने पाने च हितास्तथाष्टमश्चाश्वमारस्य", text: "iti ṣaṭ kaṣāyayogāḥ kuṣṭhaghnāḥ saptamaśca tiniśasya snāne pāne ca hitāstathāṣṭamaścāśvamārasya" },
      { type: "verse", number: "126", sanskrit: "आलेपनं प्रघर्षणमवचूर्णनमेत एव च कषायाः तैलघृतपाकयोगैश्चेष्यन्ते कुष्ठशान्त्यर्थम्", text: "ālepanaṃ pragharṣaṇamavacūrṇanameta eva ca kaṣāyāḥ tailaghṛtapākayogaiśceṣyante kuṣṭhaśāntyartham" },
      { type: "verse", number: "127", sanskrit: "सर्षपकरञ्जकोशातकानि तैलान्यथेङ्गुदीनां च कुष्ठेषु हितान्याहुस्तैलं श्रेष्ठं च खदिरसारस्य", text: "sarṣapakarañjakośātakāni tailānyatheṅgudīnāṃ ca kuṣṭheṣu hitānyāhustailaṃ śreṣṭhaṃ ca khadirasārasya" },
      { type: "verse", number: "128", sanskrit: "शीताः प्रदेहसेकास्तिक्तं सर्पिः सिराविरेकश्च विशरणदाहक्लेदे विस्फोटे चर्मदलने च", text: "śītāḥ pradehasekāstiktaṃ sarpiḥ sirāvirekaśca viśaraṇadāhaklede visphoṭe carmadalane ca" },
      { type: "verse", number: "129", sanskrit: "शीर्णनखरोममांसः कृमिमानन्नाम्भसी त्यजेत् कुष्ठी सध्योदुग्धं दुग्धं षण्मासान् कारभं भजेत्समधु", text: "śīrṇanakharomamāṃsaḥ kṛmimānannāmbhasī tyajet kuṣṭhī sadhyodugdhaṃ dugdhaṃ ṣaṇmāsān kārabhaṃ bhajetsamadhu" },
      { type: "verse", number: "130", sanskrit: "एडगजः सविडङ्गो मूलान्यारग्वधस्य कुष्ठानाम् उद्दालनं च दन्ता गोश्ववराहोष्ट्रदन्ताश्च", text: "eḍagajaḥ saviḍaṅgo mūlānyāragvadhasya kuṣṭhānām uddālanaṃ ca dantā gośvavarāhoṣṭradantāśca" },
      { type: "verse", number: "131", sanskrit: "रजनीद्वयं कृमिघ्नं प्रपुनाटं राजवृक्षमूलं च कुष्ठोत्पाटनमग्र्यं सपिप्पलीपाकलं योज्यम्", text: "rajanīdvayaṃ kṛmighnaṃ prapunāṭaṃ rājavṛkṣamūlaṃ ca kuṣṭhotpāṭanamagryaṃ sapippalīpākalaṃ yojyam" },
      { type: "verse", number: "132", sanskrit: "श्वित्राणां सविशेषं योक्तव्यं सर्वतो विशुद्धानाम् उत्सन्नेषु च लेपाः सवर्णकरणास्तथाभ्यङ्गाः", text: "śvitrāṇāṃ saviśeṣaṃ yoktavyaṃ sarvato viśuddhānām utsanneṣu ca lepāḥ savarṇakaraṇāstathābhyaṅgāḥ" },
      { type: "verse", number: "133", sanskrit: "पक्षात् पक्षात् छर्दनान्यभ्युपेयान्मासान्मासाच्छोधनं चाप्यधस्तात् शुद्धिर्मूर्ध्नःस्यात्त्रिरात्रात्त्रिरात्रात् षष्ठे षष्ठे मास्यसृङ्मोक्षणं च", text: "pakṣāt pakṣāt chardanānyabhyupeyānmāsānmāsācchodhanaṃ cāpyadhastāt śuddhirmūrdhnaḥsyāttrirātrāttrirātrāt ṣaṣṭhe ṣaṣṭhe māsyasṛṅmokṣaṇaṃ ca" },
      { type: "verse", number: "134", sanskrit: "यो दुर्वान्तो दुर्विरिक्तो ऽथवा स्यात् कुष्ठी दोषैरुद्धतैर्व्याप्यते ऽसौ निस्सन्देहं यात्यसाध्यत्वमेवं तस्मात् कृत्स्नान्निर्हरेदस्य दोषान्", text: "yo durvānto durvirikto 'thavā syāt kuṣṭhī doṣairuddhatairvyāpyate 'sau nissandehaṃ yātyasādhyatvamevaṃ tasmāt kṛtsnānnirharedasya doṣān" },
      { type: "verse", number: "135", sanskrit: "व्रतदमयमसेवात्यागशीलाभियोगो द्विजगुरुसुरपूजा सर्वसत्त्वेषु मैत्री जिनजिनसुतताराभास्कराराधनानि प्रकटितमलपापं कुष्ठमुन्मूलयन्ति", text: "vratadamayamasevātyāgaśīlābhiyogo dvijagurusurapūjā sarvasattveṣu maitrī jinajinasutatārābhāskarārādhanāni prakaṭitamalapāpaṃ kuṣṭhamunmūlayanti" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 22,
    lang: "sa",
    content: [
      { type: "heading", heading: "Атисара чикитса — лечение диареи" },
      { type: "text", text: "Глава 22 Чикитса стханы — лечебный раздел о лечение диареи. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातः श्वित्रकृमिचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ śvitrakṛmicikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "कुष्ठादपि बीभत्सं यच्छीघ्रतरं च यात्यसाध्यत्वम् श्वित्रमतस्तश्छान्त्यै यतेत दीप्ते यथा भवने", text: "kuṣṭhādapi bībhatsaṃ yacchīghrataraṃ ca yātyasādhyatvam śvitramatastaśchāntyai yateta dīpte yathā bhavane" },
      { type: "verse", number: "3", sanskrit: "मदयन्त्याः सवायस्याः सुरभ्यारग्वधस्य च शतं पलानां प्रत्येकं वरायास्त्वाढकत्रयम्", text: "madayantyāḥ savāyasyāḥ surabhyāragvadhasya ca śataṃ palānāṃ pratyekaṃ varāyāstvāḍhakatrayam" },
      { type: "verse", number: "4", sanskrit: "व्याघ्रीवह्निकपोतावत्सकखदिरार्कमूलदन्त्यैन्द्र्यः सनिशाद्वया दशपला क्वाथे ऽमीषां क्षिपेत् पिष्ट्वा", text: "vyāghrīvahnikapotāvatsakakhadirārkamūladantyaindryaḥ saniśādvayā daśapalā kvāthe 'mīṣāṃ kṣipet piṣṭvā" },
      { type: "verse", number: "5", sanskrit: "बीजं करञ्जेङ्गुदशिग्रुनिम्बान्नीलीं सनीलोत्पलचन्द्रलेखाम् श्यामां किरातं कटुकत्रयं च पञ्चाढकं तत्र च पञ्चगव्यात्", text: "bījaṃ karañjeṅgudaśigrunimbānnīlīṃ sanīlotpalacandralekhām śyāmāṃ kirātaṃ kaṭukatrayaṃ ca pañcāḍhakaṃ tatra ca pañcagavyāt" },
      { type: "verse", number: "6", sanskrit: "शमयत्यचिरेण घृतं मृदुहुतवहसाधितं महानीलम् न किलासमेव केवलमपचीकृमिकासकुष्ठमभ्यस्तम्", text: "śamayatyacireṇa ghṛtaṃ mṛduhutavahasādhitaṃ mahānīlam na kilāsameva kevalamapacīkṛmikāsakuṣṭhamabhyastam" },
      { type: "verse", number: "7", sanskrit: "उन्मादापस्मारावर्शोविद्रधिशिरोरोगान् गलगण्डगुल्मगण्डानर्बुदशोफप्रमेहगलरोगान्", text: "unmādāpasmārāvarśovidradhiśirorogān galagaṇḍagulmagaṇḍānarbudaśophapramehagalarogān" },
      { type: "verse", number: "8", sanskrit: "सविसर्पशोषपवनव्याधीन्विषमज्वरान् हन्यात्", text: "savisarpaśoṣapavanavyādhīnviṣamajvarān hanyāt" },
      { type: "verse", number: "9", sanskrit: "संशोधनं विशेषात् पीतस्नेहस्य योजयेदनु च श्वित्रे स्रंसनमग्र्यं मलयूरस इष्यते सगुडः", text: "saṃśodhanaṃ viśeṣāt pītasnehasya yojayedanu ca śvitre sraṃsanamagryaṃ malayūrasa iṣyate saguḍaḥ" },
      { type: "verse", number: "10", sanskrit: "तं पीत्वाभ्यक्ततनुर्यथाबलं सूर्यपादसन्तापम् सेवेत विरिक्तश्च त्र्यहं पिपासुः पिबेत् पेयाम्", text: "taṃ pītvābhyaktatanuryathābalaṃ sūryapādasantāpam seveta viriktaśca tryahaṃ pipāsuḥ pibet peyām" },
      { type: "verse", number: "11", sanskrit: "श्वित्रे ऽङ्गे ये स्फोटा जायन्ते कण्टकेन तान् भिन्द्यात् स्फोटेषु निस्सृतेषु प्रातः प्रातः पिबेत् पक्षम्", text: "śvitre 'ṅge ye sphoṭā jāyante kaṇṭakena tān bhindyāt sphoṭeṣu nissṛteṣu prātaḥ prātaḥ pibet pakṣam" },
      { type: "verse", number: "12", sanskrit: "मलयूमसनं प्रियङ्गुं शतपुष्पां चाम्भसा समुत्क्वाथ्य पालाशं वा क्षारं यथाबलं फाणितोपेतम्", text: "malayūmasanaṃ priyaṅguṃ śatapuṣpāṃ cāmbhasā samutkvāthya pālāśaṃ vā kṣāraṃ yathābalaṃ phāṇitopetam" },
      { type: "verse", number: "13", sanskrit: "वितुषावल्गुजबजाच्चूर्णं गोवारिभाविताद्वहुशः मूलक्वाहेन पिबेत् कलितरुकृतमालमदनफल्गूनाम्", text: "vituṣāvalgujabajāccūrṇaṃ govāribhāvitādvahuśaḥ mūlakvāhena pibet kalitarukṛtamālamadanaphalgūnām" },
      { type: "verse", number: "14", sanskrit: "पीते किलासी तिलतैलदिग्धो दिने दिने स्याद्रविपादसेवी जीर्णे च तक्राप्लुतकोद्रवाशी स्फोटोद्भवायैष विधिस्त्रिरात्रम्", text: "pīte kilāsī tilatailadigdho dine dine syādravipādasevī jīrṇe ca takrāplutakodravāśī sphoṭodbhavāyaiṣa vidhistrirātram" },
      { type: "verse", number: "15", sanskrit: "विध्वान्येद्युः स्फोटकान् कण्टकैस्तान् बस्ताम्भोभिर्घृष्टया शुक्तवर्त्या लिम्पेत् कामं लेपनाद्वेदनायां लेपो योज्यः शङ्खनाभिर्जलेन", text: "vidhvānyedyuḥ sphoṭakān kaṇṭakaistān bastāmbhobhirghṛṣṭayā śuktavartyā limpet kāmaṃ lepanādvedanāyāṃ lepo yojyaḥ śaṅkhanābhirjalena" },
      { type: "verse", number: "16", sanskrit: "व्योषसर्षपनिशागृहधूमैर्यावशूकपटुचित्रकयुक्तैः कोलतुल्यगुटिकार्धविषांशा श्वित्रकुष्ठशमनो वरलेपः", text: "vyoṣasarṣapaniśāgṛhadhūmairyāvaśūkapaṭucitrakayuktaiḥ kolatulyaguṭikārdhaviṣāṃśā śvitrakuṣṭhaśamano varalepaḥ" },
      { type: "verse", number: "17", sanskrit: "गव्यं मूत्रं चित्रकव्योषयुक्तं सर्पिःकुम्भे संस्थितं क्षौद्रमिश्रम् पक्षादूर्ध्वं श्वित्रणा पेयमेतत् कार्यं चास्मै कुष्ठदृष्टं विधानम्", text: "gavyaṃ mūtraṃ citrakavyoṣayuktaṃ sarpiḥkumbhe saṃsthitaṃ kṣaudramiśram pakṣādūrdhvaṃ śvitraṇā peyametat kāryaṃ cāsmai kuṣṭhadṛṣṭaṃ vidhānam" },
      { type: "verse", number: "18", sanskrit: "मार्कवमथवा खादेद् भृष्टं तैलेन लोहपात्रस्थम् बीजकशृतं च दुग्धं तदनुपिबेच्श्वित्रनाशाय", text: "mārkavamathavā khāded bhṛṣṭaṃ tailena lohapātrastham bījakaśṛtaṃ ca dugdhaṃ tadanupibecśvitranāśāya" },
      { type: "verse", number: "19", sanskrit: "पूतीकार्कव्याधिघातस्नुहीना मूत्रैः पिष्टाः पल्लवा जातिजाश्च घ्नन्त्यालेपाच्श्वित्रदुर्नामदद्रून् पामाकोठान् दुष्टनाडीव्रणांश्च", text: "pūtīkārkavyādhighātasnuhīnā mūtraiḥ piṣṭāḥ pallavā jātijāśca ghnantyālepācśvitradurnāmadadrūn pāmākoṭhān duṣṭanāḍīvraṇāṃśca" },
      { type: "verse", number: "20", sanskrit: "द्वैप्यं दग्धं चर्म मातङ्गजं वा श्वित्रे लेपस्तैलयुक्तो वरिष्ठः पूतीकीटो राजवृक्षोद्भवेन क्षारेणाक्तः श्वित्रमेको ऽपि हन्ति", text: "dvaipyaṃ dagdhaṃ carma mātaṅgajaṃ vā śvitre lepastailayukto variṣṭhaḥ pūtīkīṭo rājavṛkṣodbhavena kṣāreṇāktaḥ śvitrameko 'pi hanti" },
      { type: "verse", number: "21", sanskrit: "रात्रौ गोमूत्रे वासितान् जर्जराङ्गानह्निच्छायायां शोषयेत् स्फोटहेतून् एवं वारांस्त्रीन् भावयेच्श्लक्ष्णपिष्टैः स्नुह्याः क्षीरेण श्वित्रनाशाय लेपः", text: "rātrau gomūtre vāsitān jarjarāṅgānahnicchāyāyāṃ śoṣayet sphoṭahetūn evaṃ vārāṃstrīn bhāvayecślakṣṇapiṣṭaiḥ snuhyāḥ kṣīreṇa śvitranāśāya lepaḥ" },
      { type: "verse", number: "22", sanskrit: "अक्षतैलद्रुतालेपः कृष्णसर्पोद्भवामषी शिखिपित्तं तथा दग्धं द्रीबेरं वा तदाप्लुतम्", text: "akṣatailadrutālepaḥ kṛṣṇasarpodbhavāmaṣī śikhipittaṃ tathā dagdhaṃ drīberaṃ vā tadāplutam" },
      { type: "verse", number: "23", sanskrit: "उपोषितायान्नकालांस्त्रीन् श्वेतकृकवाकवे यष्ट्याह्वकुष्ठैडगजबीजचूर्णं घृतान्वितम्", text: "upoṣitāyānnakālāṃstrīn śvetakṛkavākave yaṣṭyāhvakuṣṭhaiḍagajabījacūrṇaṃ ghṛtānvitam" },
      { type: "verse", number: "24", sanskrit: "दद्यात्तस्य पुरीषेण श्वित्रमुद्दाल्य लेपयेत् मासं हन्त्याशु तच्श्वित्रं विशेषाद्गुह्यसंश्रयम्", text: "dadyāttasya purīṣeṇa śvitramuddālya lepayet māsaṃ hantyāśu tacśvitraṃ viśeṣādguhyasaṃśrayam" },
      { type: "verse", number: "25", sanskrit: "लेपः पटुवेल्लशिला कासीसं रोचना कनकपुष्पी गोपित्तयुक्तमथवा चपलाञ्जनयुग्मलोहरजः", text: "lepaḥ paṭuvellaśilā kāsīsaṃ rocanā kanakapuṣpī gopittayuktamathavā capalāñjanayugmaloharajaḥ" },
      { type: "verse", number: "26", sanskrit: "काकोदुम्बरिका वा सावल्गुजचित्रका सगोमूत्रा कदलीक्षारयुतं वा खरास्थि दग्धं सगोरुधिरम्", text: "kākodumbarikā vā sāvalgujacitrakā sagomūtrā kadalīkṣārayutaṃ vā kharāsthi dagdhaṃ sagorudhiram" },
      { type: "verse", number: "27", sanskrit: "नीलोत्पलं सकुष्ठं ससैन्धवं हस्तिमूत्रपिष्टं वा हस्तिमदाध्युषितो वा मालत्याः क्षारकक्षारः", text: "nīlotpalaṃ sakuṣṭhaṃ sasaindhavaṃ hastimūtrapiṣṭaṃ vā hastimadādhyuṣito vā mālatyāḥ kṣārakakṣāraḥ" },
      { type: "verse", number: "28", sanskrit: "सिद्धार्थकाबृहत्यौ करञ्जकोशातकीफलं गुञ्जा शुकनासा सगवाक्षी स्वर्णक्षीरीनिकुम्भश्च", text: "siddhārthakābṛhatyau karañjakośātakīphalaṃ guñjā śukanāsā sagavākṣī svarṇakṣīrīnikumbhaśca" },
      { type: "verse", number: "29", sanskrit: "लाङ्गलिकी हयमारस्तिल्वकभल्लातकाश्वमूत्री च मुस्ता स्नुही सहिंस्रा सुवर्णशकला फलोपेता", text: "lāṅgalikī hayamārastilvakabhallātakāśvamūtrī ca mustā snuhī sahiṃsrā suvarṇaśakalā phalopetā" },
      { type: "verse", number: "30", sanskrit: "मूलकबीजं व्योषं पीलुविडङ्गानि कर्णिकारश्च पिचुमन्दजातीकिसलयबाकुचिकातुत्थकुष्ठानि", text: "mūlakabījaṃ vyoṣaṃ pīluviḍaṅgāni karṇikāraśca picumandajātīkisalayabākucikātutthakuṣṭhāni" },
      { type: "verse", number: "31", sanskrit: "कटुरोहिणीमनोह्वात्रिफला च सुकल्किता गवां मृत्रे गजहयखरमूत्राणां पात्रत्रितयं स्नुगर्कदुग्धाभ्याम्", text: "kaṭurohiṇīmanohvātriphalā ca sukalkitā gavāṃ mṛtre gajahayakharamūtrāṇāṃ pātratritayaṃ snugarkadugdhābhyām" },
      { type: "verse", number: "32", sanskrit: "द्वौ कुडवाविह दद्यात् सर्षपतैलाच्च चातुर्थीम् दर्वीलेपं सिद्धा रसक्रिया मूत्रिका नाम", text: "dvau kuḍavāviha dadyāt sarṣapatailācca cāturthīm darvīlepaṃ siddhā rasakriyā mūtrikā nāma" },
      { type: "verse", number: "33", sanskrit: "श्वित्रं घृष्टं लिप्तं त्रीनालेपांस्तया न लङ्घयति मशतिलकचर्मकीलग्रन्थ्यर्बुदसर्वकुष्ठघ्नी", text: "śvitraṃ ghṛṣṭaṃ liptaṃ trīnālepāṃstayā na laṅghayati maśatilakacarmakīlagranthyarbudasarvakuṣṭhaghnī" },
      { type: "verse", number: "34", sanskrit: "कुडवो ऽवल्गुजबीजाद्धरितालचतुर्थभागसम्मिश्रः मूत्रेण गवां पिष्टः सवर्णकरणः परं श्वित्रे", text: "kuḍavo 'valgujabījāddharitālacaturthabhāgasammiśraḥ mūtreṇa gavāṃ piṣṭaḥ savarṇakaraṇaḥ paraṃ śvitre" },
      { type: "verse", number: "35", sanskrit: "क्षारे सुदग्धे गजलिण्डजे वा गजस्य मूत्रेण परिस्रुते च द्रोणप्रमाणे दशभागयुक्तं दत्वा पचेद्बीजमवल्गुजानाम्", text: "kṣāre sudagdhe gajaliṇḍaje vā gajasya mūtreṇa parisrute ca droṇapramāṇe daśabhāgayuktaṃ datvā pacedbījamavalgujānām" },
      { type: "verse", number: "36", sanskrit: "श्वित्रं जयेच्चिक्कणतां गतेन तेन प्रलिप्तं बहुशः प्रघृष्टम् कुष्ठं मशं वा तिलकालकं वा यद्वा व्रणे स्यादधिमांसजातम्", text: "śvitraṃ jayeccikkaṇatāṃ gatena tena praliptaṃ bahuśaḥ praghṛṣṭam kuṣṭhaṃ maśaṃ vā tilakālakaṃ vā yadvā vraṇe syādadhimāṃsajātam" },
      { type: "verse", number: "37", sanskrit: "भल्लातकद्वीपिसुधार्कमूलगुञ्जाफलत्र्यूषणशङ्खचूर्णम् तुत्थं सकुष्ठं लवणानि पञ्च क्षारद्वयं लाङ्गलिकां च पक्त्वा", text: "bhallātakadvīpisudhārkamūlaguñjāphalatryūṣaṇaśaṅkhacūrṇam tutthaṃ sakuṣṭhaṃ lavaṇāni pañca kṣāradvayaṃ lāṅgalikāṃ ca paktvā" },
      { type: "verse", number: "38", sanskrit: "स्नुगर्कदुग्धे तद्विदधीत लेपम् कुष्ठे किलासे तिलकालकेषु मशेषु दुर्नामसु चर्मकीले", text: "snugarkadugdhe tadvidadhīta lepam kuṣṭhe kilāse tilakālakeṣu maśeṣu durnāmasu carmakīle" },
      { type: "verse", number: "39", sanskrit: "शुध्या शोणितमोक्षैर्विरूक्षणैर्भक्षणैश्च सक्तूनाम् श्वित्रं कस्यचिदेव प्रशाम्यति क्षीणपापस्य", text: "śudhyā śoṇitamokṣairvirūkṣaṇairbhakṣaṇaiśca saktūnām śvitraṃ kasyacideva praśāmyati kṣīṇapāpasya" },
      { type: "verse", number: "40", sanskrit: "कृमिचिकित्सितम् स्निग्धस्विन्ने गुडक्षीरमत्स्याद्यैः कृमिणोदरे उत्क्लेशितक्रिमिकफे शर्बरीं तां सुखोषिते", text: "kṛmicikitsitam snigdhasvinne guḍakṣīramatsyādyaiḥ kṛmiṇodare utkleśitakrimikaphe śarbarīṃ tāṃ sukhoṣite" },
      { type: "verse", number: "41", sanskrit: "सुरसादिगणं मूत्रे क्वाथयित्वार्धवारिणि तं कषायं कणागालाकृमिजित्कल्कयोजितम् सतैलस्वर्जिकाक्षारं युञ्ज्याद्बस्तिं ततो ऽहनि", text: "surasādigaṇaṃ mūtre kvāthayitvārdhavāriṇi taṃ kaṣāyaṃ kaṇāgālākṛmijitkalkayojitam satailasvarjikākṣāraṃ yuñjyādbastiṃ tato 'hani" },
      { type: "verse", number: "42", sanskrit: "तस्मिन्नेव निरूढं तं पाययेत विरेचनम् त्रिवृत्कल्कं फलकणाकषायालोडितं ततः ऊर्ध्वाधःशोधिते कुर्यात् पञ्चकोलयुतं क्रमम्", text: "tasminneva nirūḍhaṃ taṃ pāyayeta virecanam trivṛtkalkaṃ phalakaṇākaṣāyāloḍitaṃ tataḥ ūrdhvādhaḥśodhite kuryāt pañcakolayutaṃ kramam" },
      { type: "verse", number: "43", sanskrit: "कटुतिक्तकषायाणां कषायैः परिषेचनम् काले विडङ्गतैलेन ततस्तमनुवासयेत्", text: "kaṭutiktakaṣāyāṇāṃ kaṣāyaiḥ pariṣecanam kāle viḍaṅgatailena tatastamanuvāsayet" },
      { type: "verse", number: "44", sanskrit: "शिरोरोगनिषेधोक्तमाचरेन्मूर्धगेष्वनु उद्रिक्ततिक्तकटुकमल्पस्नेहं च भोजनम्", text: "śiroroganiṣedhoktamācarenmūrdhageṣvanu udriktatiktakaṭukamalpasnehaṃ ca bhojanam" },
      { type: "verse", number: "45", sanskrit: "विडङ्गकृष्णामरिचपिप्पलीमूलशिग्रुभिः पिबेत् सस्वर्जिकाक्षारैर्यवागूं तक्रसाधिताम्", text: "viḍaṅgakṛṣṇāmaricapippalīmūlaśigrubhiḥ pibet sasvarjikākṣārairyavāgūṃ takrasādhitām" },
      { type: "verse", number: "46", sanskrit: "रसं शिरीषकिणिहीपारिभद्रककेम्बुकात् पलाशबीजपत्तूरपूतीकाद्वा पृथक् पिबेत् सक्षौद्रं सुरसादीन् वा लिह्यात् क्षौद्रयुतान् पृथक्", text: "rasaṃ śirīṣakiṇihīpāribhadrakakembukāt palāśabījapattūrapūtīkādvā pṛthak pibet sakṣaudraṃ surasādīn vā lihyāt kṣaudrayutān pṛthak" },
      { type: "verse", number: "47", sanskrit: "शतकृत्वो ऽश्वविट्चूर्णं विडङ्गक्वाथभावितम् कृमिमान्मधुना लिह्यात् भावितं वा वरारसैः शिरोगतेषु क्रिमिषु चूर्णं प्रधमनं च तत्", text: "śatakṛtvo 'śvaviṭcūrṇaṃ viḍaṅgakvāthabhāvitam kṛmimānmadhunā lihyāt bhāvitaṃ vā varārasaiḥ śirogateṣu krimiṣu cūrṇaṃ pradhamanaṃ ca tat" },
      { type: "verse", number: "48", sanskrit: "आखुकर्णीकिसलयैः सुपिष्टैः पिष्टमिश्रितैः पक्त्वा पूपलिकां खादेत् धान्याम्लं च पिबेदनु", text: "ākhukarṇīkisalayaiḥ supiṣṭaiḥ piṣṭamiśritaiḥ paktvā pūpalikāṃ khādet dhānyāmlaṃ ca pibedanu" },
      { type: "verse", number: "49", sanskrit: "सपञ्चकोललवणमसान्द्रं तक्रमेव वा नीपमार्कवनिर्गुण्डीपल्लवेष्वप्ययं विधिः", text: "sapañcakolalavaṇamasāndraṃ takrameva vā nīpamārkavanirguṇḍīpallaveṣvapyayaṃ vidhiḥ" },
      { type: "verse", number: "50", sanskrit: "विडङ्गचूर्णमिश्रैर्वा पिष्टैर्भक्ष्यान् प्रकल्पयेत् विडङ्गतण्डुलैर्युक्तमर्धांशैरातपे स्थितम्", text: "viḍaṅgacūrṇamiśrairvā piṣṭairbhakṣyān prakalpayet viḍaṅgataṇḍulairyuktamardhāṃśairātape sthitam" },
      { type: "verse", number: "51", sanskrit: "दिनमारुष्करं तैलं पाने बस्तौ च योजयेत् सुराह्वसरलस्नेहं पृथगेवं च कल्पयेत्", text: "dinamāruṣkaraṃ tailaṃ pāne bastau ca yojayet surāhvasaralasnehaṃ pṛthagevaṃ ca kalpayet" },
      { type: "verse", number: "52", sanskrit: "तिल्वकोद्दालकपले त्रिवृच्छ्यामे तदर्धतः दन्तीद्रवन्त्यावर्धेन तदर्धे चव्यचित्रकौ", text: "tilvakoddālakapale trivṛcchyāme tadardhataḥ dantīdravantyāvardhena tadardhe cavyacitrakau" },
      { type: "verse", number: "53", sanskrit: "पिष्ट्वा विडङ्गयूषेण तेन भावितपीडितात् तैलप्रस्थं तिलात्साध्यं क्रिमिघ्नद्विगुणे रसे तच्छोधनं पिबेत् काले विदध्याच्चानुवासनम्", text: "piṣṭvā viḍaṅgayūṣeṇa tena bhāvitapīḍitāt tailaprasthaṃ tilātsādhyaṃ krimighnadviguṇe rase tacchodhanaṃ pibet kāle vidadhyāccānuvāsanam" },
      { type: "verse", number: "54", sanskrit: "कोशातकीकरञ्जोमासर्षपस्नेहकल्पनम् कृत्वा तेनैव विधिना पाययेदुदरक्रिमिम्", text: "kośātakīkarañjomāsarṣapasnehakalpanam kṛtvā tenaiva vidhinā pāyayedudarakrimim" },
      { type: "verse", number: "55", sanskrit: "पुरीषजेषु सुतरां दद्याद्बस्तिविरेचने शिरोविरेकं वमनं शमनं कफजन्मसु", text: "purīṣajeṣu sutarāṃ dadyādbastivirecane śirovirekaṃ vamanaṃ śamanaṃ kaphajanmasu" },
      { type: "verse", number: "56", sanskrit: "रक्तजानां प्रतीकारं कुर्यात् कुष्ठचिकित्सितम् इन्द्रलुप्तविधिश्चात्र विधेयो रोमभोजिषु", text: "raktajānāṃ pratīkāraṃ kuryāt kuṣṭhacikitsitam indraluptavidhiścātra vidheyo romabhojiṣu" },
      { type: "verse", number: "57", sanskrit: "क्षीराणि मांसानि घृतं गुडं च दधीनि शाकानि च पर्णवन्ति समासतो ऽम्लान्मधुरान्रसांश्च क्रिमीन् जिघांसुः परिवर्जयेच्च", text: "kṣīrāṇi māṃsāni ghṛtaṃ guḍaṃ ca dadhīni śākāni ca parṇavanti samāsato 'mlānmadhurānrasāṃśca krimīn jighāṃsuḥ parivarjayecca" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 23,
    lang: "sa",
    content: [
      { type: "heading", heading: "Расаяна адхьяя — омоложение" },
      { type: "text", text: "Глава 23 Чикитса стханы — лечебный раздел о омоложение. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो वातव्याधिचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vātavyādhicikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सर्वेषु केवलानिलविकारेष्वन्तर्बहिः स्नेहस्वेदौ साल्वलेनोपनाहो निवातं स्थानं प्रावरणानि दशमूलक्वाथसिद्धा महास्नेहप्रगाढाः स्निग्धा दध्यम्ला नागरपिप्पलीतीक्ष्णा ग्राम्यानूपौदकशिरःपिशितरसाः पयांसि यूषाः प्रीणनानि चान्नानि तैरेव च मांसैर्महास्नेहसंसृष्टैस्तदक्तानामभीक्ष्णं पिण्डादिस्वेदाः", text: "sarveṣu kevalānilavikāreṣvantarbahiḥ snehasvedau sālvalenopanāho nivātaṃ sthānaṃ prāvaraṇāni daśamūlakvāthasiddhā mahāsnehapragāḍhāḥ snigdhā dadhyamlā nāgarapippalītīkṣṇā grāmyānūpaudakaśiraḥpiśitarasāḥ payāṃsi yūṣāḥ prīṇanāni cānnāni taireva ca māṃsairmahāsnehasaṃsṛṣṭaistadaktānāmabhīkṣṇaṃ piṇḍādisvedāḥ" },
      { type: "verse", number: "3", sanskrit: "अपि च कोलकुलत्थामरतरुयवमिसिमाषातसीवचाकुष्ठम् रास्नातैलफलानि च वातजिदुत्कारिकाम्लोष्णा", text: "api ca kolakulatthāmarataruyavamisimāṣātasīvacākuṣṭham rāsnātailaphalāni ca vātajidutkārikāmloṣṇā" },
      { type: "verse", number: "4", sanskrit: "बिडालनकुलोष्ट्रसृगालादिचर्मभिर्बन्धः स्निग्धा बस्तयो नावनानि च प्रयोज्यानि दोषोपक्रमणीयं चेक्षेत", text: "biḍālanakuloṣṭrasṛgālādicarmabhirbandhaḥ snigdhā bastayo nāvanāni ca prayojyāni doṣopakramaṇīyaṃ cekṣeta" },
      { type: "verse", number: "5", sanskrit: "स्निग्धस्विन्नस्य हि तोदभेदायामशूलादयो वातविकाराः शीघ्रमुपशाम्यन्ति स्नेहश्च धातून् पुष्णाति बलं च देहे जनयति तस्मात् पुनः पुनः स्नेहस्वेदौ शीलयेत् तन्मृदूकृते च कोष्ठे नावतिष्ठन्त्यनिलामयाः", text: "snigdhasvinnasya hi todabhedāyāmaśūlādayo vātavikārāḥ śīghramupaśāmyanti snehaśca dhātūn puṣṇāti balaṃ ca dehe janayati tasmāt punaḥ punaḥ snehasvedau śīlayet tanmṛdūkṛte ca koṣṭhe nāvatiṣṭhantyanilāmayāḥ" },
      { type: "verse", number: "6", sanskrit: "यदि तु सदोषत्वान्न निवर्तन्ते ततः सर्वशरीरगे ऽपि वायौ विशेषतः पक्वाशयाश्रिते मृदुस्नेहविरेचनं तिल्वकसर्पिः सातलाघृतमैरण्डतैलं वा क्षीरेण दद्यात् एवं हि विशुद्धस्रोतसो ऽनावृतः पवनो विचरन्नाशु शान्तिमेति", text: "yadi tu sadoṣatvānna nivartante tataḥ sarvaśarīrage 'pi vāyau viśeṣataḥ pakvāśayāśrite mṛdusnehavirecanaṃ tilvakasarpiḥ sātalāghṛtamairaṇḍatailaṃ vā kṣīreṇa dadyāt evaṃ hi viśuddhasrotaso 'nāvṛtaḥ pavano vicarannāśu śāntimeti" },
      { type: "verse", number: "7", sanskrit: "अपि च स्निग्धाम्ललवणोष्णाद्यैराहारैर्हि मलश्चितः स्रोतो बध्वानिलं रुन्ध्यात्तस्मात्तमनुलोमयेत्", text: "api ca snigdhāmlalavaṇoṣṇādyairāhārairhi malaścitaḥ sroto badhvānilaṃ rundhyāttasmāttamanulomayet" },
      { type: "verse", number: "8", sanskrit: "अथ दुर्बले विरेच्ये निरूहं पाचनीयदीपनीयद्रव्ययुक्तमेवंविधं च भोज्यम् भोज्ययुक्तं वा स्रंसनमवचारयेत् विशुद्धस्य च समिद्धे ऽग्रावसकृत् स्नेहस्वेदौ स्वाद्वम्ललवणं चान्नपानम् एवमप्यनिवृत्ताववपीडकस्नेहान् बस्तिकर्म च प्रयोजयेत्", text: "atha durbale virecye nirūhaṃ pācanīyadīpanīyadravyayuktamevaṃvidhaṃ ca bhojyam bhojyayuktaṃ vā sraṃsanamavacārayet viśuddhasya ca samiddhe 'grāvasakṛt snehasvedau svādvamlalavaṇaṃ cānnapānam evamapyanivṛttāvavapīḍakasnehān bastikarma ca prayojayet" },
      { type: "verse", number: "9", sanskrit: "आमाशयगते कृतवमनस्य षड्ढरणं चूर्णं परतश्च यथार्हं स्नेहादीन् नाभिदेशमाश्रिते बिल्वशलाटुभिः सिद्धान् मत्स्यान् अशेषकोष्ठाश्रिते पुनरर्शोग्रहणीविहितमाममलपाचनं क्षारोपयोगानन्तर्गुल्मोपक्रमं च प्रयुञ्जीत हृदयस्थे अंशुमत्या शृतं पयः", text: "āmāśayagate kṛtavamanasya ṣaḍḍharaṇaṃ cūrṇaṃ parataśca yathārhaṃ snehādīn nābhideśamāśrite bilvaśalāṭubhiḥ siddhān matsyān aśeṣakoṣṭhāśrite punararśograhaṇīvihitamāmamalapācanaṃ kṣāropayogānantargulmopakramaṃ ca prayuñjīta hṛdayasthe aṃśumatyā śṛtaṃ payaḥ" },
      { type: "verse", number: "10", sanskrit: "श्रोत्रादिगते शिरोगते च विशेषेण स्नैहिकं नस्यं धूमं शिरोबस्तिमर्दनालेपनान्यथास्वं च स्रोतसां प्रीणनम्", text: "śrotrādigate śirogate ca viśeṣeṇa snaihikaṃ nasyaṃ dhūmaṃ śirobastimardanālepanānyathāsvaṃ ca srotasāṃ prīṇanam" },
      { type: "verse", number: "11", sanskrit: "त्वचि स्थिते ऽभ्यङ्गस्वेदनिवातानि रक्ते शीतप्रदेहविरेकरक्तमोक्षाः मांसमेदसोर्विरेकास्थापनशमनानि अस्थिमज्ज्ञोरन्तर्बहिःस्नेहाः शुक्रप्राप्ते हर्षः शुक्रलं चान्नपानम् विबद्धे तु शुक्रे विरेचनम् ततो ऽनुबन्धे ऽनन्तरोक्तां क्रियां कुर्यात् पुत्रकामीयं चेक्षेत", text: "tvaci sthite 'bhyaṅgasvedanivātāni rakte śītapradehavirekaraktamokṣāḥ māṃsamedasorvirekāsthāpanaśamanāni asthimajjñorantarbahiḥsnehāḥ śukraprāpte harṣaḥ śukralaṃ cānnapānam vibaddhe tu śukre virecanam tato 'nubandhe 'nantaroktāṃ kriyāṃ kuryāt putrakāmīyaṃ cekṣeta" },
      { type: "verse", number: "12", sanskrit: "शुष्यति तु गर्भे बालेषु च यष्टीमधुककाश्मर्यफलसारिवाशर्कराशृतं पयो दद्यात् मांसादमांसरसांश्च बृंहणीयस्नेहयुक्तान्", text: "śuṣyati tu garbhe bāleṣu ca yaṣṭīmadhukakāśmaryaphalasārivāśarkarāśṛtaṃ payo dadyāt māṃsādamāṃsarasāṃśca bṛṃhaṇīyasnehayuktān" },
      { type: "verse", number: "13", sanskrit: "सिरास्नावसन्धिप्राप्ते ऽभ्यङ्गमर्दनस्वेदोपनाहबन्धाग्निकर्माणि सङ्कोचे माषसैन्धवसाधितं तैलमभ्यङ्गः स्वापे बहुशो रक्तावसेचनम् न त्वङ्गम्लानौ शोषभयात् स्रुतरक्तस्य तैललवणागारधूमैः प्रदेहः", text: "sirāsnāvasandhiprāpte 'bhyaṅgamardanasvedopanāhabandhāgnikarmāṇi saṅkoce māṣasaindhavasādhitaṃ tailamabhyaṅgaḥ svāpe bahuśo raktāvasecanam na tvaṅgamlānau śoṣabhayāt srutaraktasya tailalavaṇāgāradhūmaiḥ pradehaḥ" },
      { type: "verse", number: "14", sanskrit: "अथापतानकिनमस्रस्ताक्षमस्तब्धलाङ्गुलमवेदनमस्वेदनमप्रलापिनमखट्वाघातिनमबहिरायामिनं चोपक्रमेत", text: "athāpatānakinamasrastākṣamastabdhalāṅgulamavedanamasvedanamapralāpinamakhaṭvāghātinamabahirāyāminaṃ copakrameta" },
      { type: "verse", number: "15", sanskrit: "तत्र प्रागेव स्निग्धस्विन्नाङ्गं व्योषविडङ्गश्वेतमरिचैरन्यैश्च तीक्ष्णैः शिरोविरेचनैः स्रोतोविशुद्धये कृतनस्यमनन्तरं चैनं विदार्यादिक्वाथमांसरसक्षीरदधिविपक्वं सर्पिरच्छं पाययेत् तथा नातिमात्रमनिलः प्रसरति", text: "tatra prāgeva snigdhasvinnāṅgaṃ vyoṣaviḍaṅgaśvetamaricairanyaiśca tīkṣṇaiḥ śirovirecanaiḥ srotoviśuddhaye kṛtanasyamanantaraṃ cainaṃ vidāryādikvāthamāṃsarasakṣīradadhivipakvaṃ sarpiracchaṃ pāyayet tathā nātimātramanilaḥ prasarati" },
      { type: "verse", number: "16", sanskrit: "ततो भद्रदार्वादिवर्गं वातघ्नमाहृत्य सयवकोलकुलत्थं सानूपमांसं च निष्क्वाथ्य तत्कषायेणाम्लक्षीरवता मधुरवर्गप्रतीवापं महास्नेहं विपचेत् तमपतानकिनमभ्यङ्गपरिषेकावगाहपानभोजनानुवासननावनेषु विदध्यात्", text: "tato bhadradārvādivargaṃ vātaghnamāhṛtya sayavakolakulatthaṃ sānūpamāṃsaṃ ca niṣkvāthya tatkaṣāyeṇāmlakṣīravatā madhuravargapratīvāpaṃ mahāsnehaṃ vipacet tamapatānakinamabhyaṅgapariṣekāvagāhapānabhojanānuvāsananāvaneṣu vidadhyāt" },
      { type: "verse", number: "17", sanskrit: "बलीयसि च वाते सुखोष्णकरीषपूर्णे कूपे निखन्यादामुखम् तप्तायां वा रथकारचुल्यां शिलायां वा सुरापरिषिक्तायां शाययेत् पलालावच्छन्नम् स्वेदयेद्वा पिण्डेन मूलकोरुबूकस्फूर्जातकार्कसप्तलाशङ्खिनीस्वरससिद्धं वा तलमभ्यङ्गादिषु योज्यम् अभुक्तवता चैतत् पीतमम्लदधिमरिचवचायुक्तमाक्षेपकमपहन्ति", text: "balīyasi ca vāte sukhoṣṇakarīṣapūrṇe kūpe nikhanyādāmukham taptāyāṃ vā rathakāraculyāṃ śilāyāṃ vā surāpariṣiktāyāṃ śāyayet palālāvacchannam svedayedvā piṇḍena mūlakorubūkasphūrjātakārkasaptalāśaṅkhinīsvarasasiddhaṃ vā talamabhyaṅgādiṣu yojyam abhuktavatā caitat pītamamladadhimaricavacāyuktamākṣepakamapahanti" },
      { type: "verse", number: "18", sanskrit: "तिलपीडनोपकरणद्रव्याण्यल्पकालतैलपरिपीतान्यवक्षुद्य महति कटाहे पानीयेनाप्लाव्य क्वाथयेदास्नेहोपगमात् ततस्तत् स्नेहमम्भस उपरिष्टात् पाणिशरावयोरन्यतरेणादाय वातघ्नौषधदत्तप्रतीवापं स्नेहपाककल्पेन पचेत् एतदणुतैलं सर्ववातविकारहरम् अणुतैलद्रव्येभ्यो निषपद्यत इत्यणुतैलम्", text: "tilapīḍanopakaraṇadravyāṇyalpakālatailaparipītānyavakṣudya mahati kaṭāhe pānīyenāplāvya kvāthayedāsnehopagamāt tatastat snehamambhasa upariṣṭāt pāṇiśarāvayoranyatareṇādāya vātaghnauṣadhadattapratīvāpaṃ snehapākakalpena pacet etadaṇutailaṃ sarvavātavikāraharam aṇutailadravyebhyo niṣapadyata ityaṇutailam" },
      { type: "verse", number: "19", sanskrit: "वेगान्तरेषु च तीक्ष्णान्यवपीडानि प्रधमनानि वासकृद्दद्यात् तथास्य श्लेष्मापगमनेन श्वसनविमोक्षात् संज्ञा पुनः पुनर्नोपरुध्यते कुक्कुटकुलीरशिंशुमारवराहवसाः पाययेत् यवकोलकुलत्थमूलकदधिघृततैलसिद्धां च यवागूम् सर्वाकारं च गतवेगः स्नेहविरेचनास्थापनानुवासनानि सेवेत", text: "vegāntareṣu ca tīkṣṇānyavapīḍāni pradhamanāni vāsakṛddadyāt tathāsya śleṣmāpagamanena śvasanavimokṣāt saṃjñā punaḥ punarnoparudhyate kukkuṭakulīraśiṃśumāravarāhavasāḥ pāyayet yavakolakulatthamūlakadadhighṛtatailasiddhāṃ ca yavāgūm sarvākāraṃ ca gatavegaḥ snehavirecanāsthāpanānuvāsanāni seveta" },
      { type: "verse", number: "20", sanskrit: "त्रिवृदृन्तीसुवर्णक्षीरीशङ्खिनीविडङ्गत्रिफलानामक्षसमाः कल्काः बिल्वमात्रकं तिल्वकमूलानां त्रिफलारसदधिपात्रे द्वे घृतपात्रमकं सर्वमैकध्यं प्रतिसंसृज्य विपचेदेतत्तिल्वकसर्पिः स्नेहविरेचनमनिलरोगेषु तिल्वकविधिरेव चाशोकरम्यकयोर्द्रष्टव्यः शुद्धवातपतानकविधानमेतत् संसृष्टे यथासंसर्गम्", text: "trivṛdṛntīsuvarṇakṣīrīśaṅkhinīviḍaṅgatriphalānāmakṣasamāḥ kalkāḥ bilvamātrakaṃ tilvakamūlānāṃ triphalārasadadhipātre dve ghṛtapātramakaṃ sarvamaikadhyaṃ pratisaṃsṛjya vipacedetattilvakasarpiḥ snehavirecanamanilarogeṣu tilvakavidhireva cāśokaramyakayordraṣṭavyaḥ śuddhavātapatānakavidhānametat saṃsṛṣṭe yathāsaṃsargam" },
      { type: "verse", number: "21", sanskrit: "सकफे तु वाते तुल्बुरुफलाभयाहिङ्गुपुष्करमूललवणत्रयचूर्णं यवक्वाथेन कृत्पार्श्वार्तिहरं पिबेत् हिङ्गुनागरदाडिमाम्लवेतससौवर्चलचूर्णं वा मुस्तपिप्पलीनागरातिविषाबिभीतकभार्ङ्गीचूर्णं वा मद्येनोष्णाम्बुना वापतन्त्रककासहृद्रोगहरम् सौवर्चलाभयाव्योषसिद्धं सर्पिः रास्नाम्लवेतससैन्धववचाहरातकाकल्कश्च घृतभृष्टो भक्षितः", text: "sakaphe tu vāte tulburuphalābhayāhiṅgupuṣkaramūlalavaṇatrayacūrṇaṃ yavakvāthena kṛtpārśvārtiharaṃ pibet hiṅgunāgaradāḍimāmlavetasasauvarcalacūrṇaṃ vā mustapippalīnāgarātiviṣābibhītakabhārṅgīcūrṇaṃ vā madyenoṣṇāmbunā vāpatantrakakāsahṛdrogaharam sauvarcalābhayāvyoṣasiddhaṃ sarpiḥ rāsnāmlavetasasaindhavavacāharātakākalkaśca ghṛtabhṛṣṭo bhakṣitaḥ" },
      { type: "verse", number: "22", sanskrit: "शुण्ठीचित्रकभार्ङ्गीशुकनासानिचुलमहावल्लीबृहतीद्वयकाकमाचीपुनर्नवैरक्षमात्रैर्घृतप्रस्थं साधयेत् तत् पीतं परमपतन्त्रकश्वासहिध्माहृद्रोगघ्नम् पथ्याशतार्धकल्केन वा सौवर्चलपलद्वययुक्तं चतुर्गुणक्षीरं घृतप्रस्थं विपाचयेत् तदपतन्त्रकघ्नम् न चास्य शोधनार्थं बस्तयस्तीक्ष्णाः प्रयोक्तव्याः हृद्रोगचिकित्सितं चेक्षते", text: "śuṇṭhīcitrakabhārṅgīśukanāsāniculamahāvallībṛhatīdvayakākamācīpunarnavairakṣamātrairghṛtaprasthaṃ sādhayet tat pītaṃ paramapatantrakaśvāsahidhmāhṛdrogaghnam pathyāśatārdhakalkena vā sauvarcalapaladvayayuktaṃ caturguṇakṣīraṃ ghṛtaprasthaṃ vipācayet tadapatantrakaghnam na cāsya śodhanārthaṃ bastayastīkṣṇāḥ prayoktavyāḥ hṛdrogacikitsitaṃ cekṣate" },
      { type: "verse", number: "23", sanskrit: "अन्तर्बहिरायामावेकायामवत् साधयेत् तैलद्रोण्यां चात्र शयनम् अन्तरायामश्चैतयोर्घोरतरः अपि च", text: "antarbahirāyāmāvekāyāmavat sādhayet tailadroṇyāṃ cātra śayanam antarāyāmaścaitayorghorataraḥ api ca" },
      { type: "verse", number: "24", sanskrit: "विवर्णदन्तवदनः स्रस्ताङ्गो नष्टचेतनः प्रस्विद्यंश्च धनुष्कम्पी दशरात्रं न जीवति", text: "vivarṇadantavadanaḥ srastāṅgo naṣṭacetanaḥ prasvidyaṃśca dhanuṣkampī daśarātraṃ na jīvati" },
      { type: "verse", number: "25", sanskrit: "वेगेष्वतो ऽन्यथा जीवेन्मन्देषु विनतो जडः खञ्जः कुणिः पक्षहतः पङ्गुलो विकलोथवा", text: "vegeṣvato 'nyathā jīvenmandeṣu vinato jaḍaḥ khañjaḥ kuṇiḥ pakṣahataḥ paṅgulo vikalothavā" },
      { type: "verse", number: "26", sanskrit: "हनुस्तम्भमप्यर्दितवच्चिकित्सेत् स्वेदयित्वा च हनू स्तब्धौ स्रस्तौ स्वस्थानमानीय पाणिभ्यां पीडयेत् विवृतास्ये चिबुकं चोन्नामयेत् संवृतास्ये च नामयेत्", text: "hanustambhamapyarditavaccikitset svedayitvā ca hanū stabdhau srastau svasthānamānīya pāṇibhyāṃ pīḍayet vivṛtāsye cibukaṃ connāmayet saṃvṛtāsye ca nāmayet" },
      { type: "verse", number: "27", sanskrit: "जिह्वास्तम्भे सामान्योक्तो विधिरेकायामे च तथा महातृणपञ्चमूलविदार्यादिजीवनीयानि मेद्यमांसान्यौदककन्दांश्च द्विगुणोदके क्षीरशेषं निष्क्वाथ्य परिस्राव्य तैलप्रस्थेनोन्मिश्रं पुनरधिश्रयेत् क्षीरानुगमे चावतार्य शीतं मन्थयेत् ततः स्नेहमादाय पूर्ववद्विपचेत् एतत् क्षीरतैलं पानाभ्यङ्गादिषु विधेयम् तैलविहीनमिदमेव क्षीरघृतमक्षितर्पणम्", text: "jihvāstambhe sāmānyokto vidhirekāyāme ca tathā mahātṛṇapañcamūlavidāryādijīvanīyāni medyamāṃsānyaudakakandāṃśca dviguṇodake kṣīraśeṣaṃ niṣkvāthya parisrāvya tailaprasthenonmiśraṃ punaradhiśrayet kṣīrānugame cāvatārya śītaṃ manthayet tataḥ snehamādāya pūrvavadvipacet etat kṣīratailaṃ pānābhyaṅgādiṣu vidheyam tailavihīnamidameva kṣīraghṛtamakṣitarpaṇam" },
      { type: "verse", number: "28", sanskrit: "तिल्वकफलसिद्धक्षीरदध्ना च सह मांसरसान् कल्पयेत् यथोक्ताश्च यवागूः स्निग्धाश्च नस्यधूमकवलग्रहाः प्रयोज्याः कृष्णभूमिकेदारं रोहिणीकाष्ठैर्नातिशुष्कैर्दाहयेत् उपलिप्य च गोमयेन पुनः खदिरकाष्ठैर्दग्ध्वा तद्भस्मापनीय तत्र शीतीभूते तैलं निषेचयेत् उषितं च निशां खानयेत् तामनुगततैलां मृत्तिकामादाय पञ्चमूलेन सह क्वाथयेत् तमपि क्वाथं परिस्रुतमष्टगुणेन पयसा तैलावशेषं पाचयेत् एतदप्यणुतैलं नावनात् सर्ववातव्याधिहरम्", text: "tilvakaphalasiddhakṣīradadhnā ca saha māṃsarasān kalpayet yathoktāśca yavāgūḥ snigdhāśca nasyadhūmakavalagrahāḥ prayojyāḥ kṛṣṇabhūmikedāraṃ rohiṇīkāṣṭhairnātiśuṣkairdāhayet upalipya ca gomayena punaḥ khadirakāṣṭhairdagdhvā tadbhasmāpanīya tatra śītībhūte tailaṃ niṣecayet uṣitaṃ ca niśāṃ khānayet tāmanugatatailāṃ mṛttikāmādāya pañcamūlena saha kvāthayet tamapi kvāthaṃ parisrutamaṣṭaguṇena payasā tailāvaśeṣaṃ pācayet etadapyaṇutailaṃ nāvanāt sarvavātavyādhiharam" },
      { type: "verse", number: "29", sanskrit: "तद्वच्च पञ्चमूलकाष्ठैर्दग्ध्वा भस्मापनीय विदार्यादिसिद्धेन तैलेन शतशो निषिच्य पूर्ववन्मृदमादायोष्णोदकवति कटाहे ऽभ्यासिच्य तैलं पाणिना पिचुना वा गृहीत्वा वातहरौषधक्वाथमांसरसक्षीराम्लभागसहस्रेण सहस्रपाकं साधयेद्यावता कालेन शक्नुयात् पक्तुं प्रतिवापश्चात्र हैमवता दक्षिणापथगा चाश्वगन्धा वातघ्नानि च द्रव्याणि सिध्यति चास्मिन् शङ्खमाध्मापयेत् दुन्दुभीन् वादयेत् ब्राह्मणानध्यापयेत् भोजयेच्च छत्रं धारयेत् बालव्यजनैश्च वीजयेत् तत्सिद्धं नस्यपानाभ्यङ्गबस्तिषु प्रयुञ्जीत एतत्सहस्रपाकमनिवार्यवीर्यं तैलमेवं भागशतपक्वं शतपाकम् अभीक्ष्णं च स्वेदयेत् ततः स्निग्धस्विन्नस्य श्लक्ष्णस्य मृदुनश्चर्मणो वाससो वा चतुरङ्गुलविस्तृताभिः पट्टिकाभिर्वक्रीभूतप्रदेशानवगृह्णन् सर्वतो वेष्टयेत् बध्नीयात् निशि बध्वा दिवा मुञ्चेद्दिवा वा जिशि मोक्षान्ते चोत्कारिकाभिः सुस्निग्धाभिर्वातघ्नप्रक्लृप्ताभिः स्वेदयेत् अव्यथं च प्रतिलोमं प्रमार्जयन्नृजु कुर्वंश्च पुनर्बध्नीयात् एवं सप्तरात्रम् सशोफे तु वमनमाचरेत् सदाहरागे बलवतः सिराव्यधम् घृतक्षीरबस्तिसेकान् वातपित्तघ्नक्रियां च", text: "tadvacca pañcamūlakāṣṭhairdagdhvā bhasmāpanīya vidāryādisiddhena tailena śataśo niṣicya pūrvavanmṛdamādāyoṣṇodakavati kaṭāhe 'bhyāsicya tailaṃ pāṇinā picunā vā gṛhītvā vātaharauṣadhakvāthamāṃsarasakṣīrāmlabhāgasahasreṇa sahasrapākaṃ sādhayedyāvatā kālena śaknuyāt paktuṃ prativāpaścātra haimavatā dakṣiṇāpathagā cāśvagandhā vātaghnāni ca dravyāṇi sidhyati cāsmin śaṅkhamādhmāpayet dundubhīn vādayet brāhmaṇānadhyāpayet bhojayecca chatraṃ dhārayet bālavyajanaiśca vījayet tatsiddhaṃ nasyapānābhyaṅgabastiṣu prayuñjīta etatsahasrapākamanivāryavīryaṃ tailamevaṃ bhāgaśatapakvaṃ śatapākam abhīkṣṇaṃ ca svedayet tataḥ snigdhasvinnasya ślakṣṇasya mṛdunaścarmaṇo vāsaso vā caturaṅgulavistṛtābhiḥ paṭṭikābhirvakrībhūtapradeśānavagṛhṇan sarvato veṣṭayet badhnīyāt niśi badhvā divā muñceddivā vā jiśi mokṣānte cotkārikābhiḥ susnigdhābhirvātaghnapraklṛptābhiḥ svedayet avyathaṃ ca pratilomaṃ pramārjayannṛju kurvaṃśca punarbadhnīyāt evaṃ saptarātram saśophe tu vamanamācaret sadāharāge balavataḥ sirāvyadham ghṛtakṣīrabastisekān vātapittaghnakriyāṃ ca" },
      { type: "verse", number: "30", sanskrit: "एकाङ्गरोगिणमम्लानगात्रं स्नेहस्वेदोपपन्नं मृदुना संशोधनेन संशोध्यानुवास्यास्थाप्य चाक्षेपकविधानेनोपचरेत् विशेषतो बलातैलमनुवासनार्थे दोषसंसर्गे यथासंसर्गम् कुक्कुटीं वा रसायनविधानेनोपयुञ्जीत अपबाहुके नाचनमूर्ध्वभक्तं च निरामे स्नेहपानम् विश्वभीप्रभृतिषु पाददाहान्तेषु यथोक्तां सिरां विध्वा वातव्याधिवदुपाचरेत्", text: "ekāṅgarogiṇamamlānagātraṃ snehasvedopapannaṃ mṛdunā saṃśodhanena saṃśodhyānuvāsyāsthāpya cākṣepakavidhānenopacaret viśeṣato balātailamanuvāsanārthe doṣasaṃsarge yathāsaṃsargam kukkuṭīṃ vā rasāyanavidhānenopayuñjīta apabāhuke nācanamūrdhvabhaktaṃ ca nirāme snehapānam viśvabhīprabhṛtiṣu pādadāhānteṣu yathoktāṃ sirāṃ vidhvā vātavyādhivadupācaret" },
      { type: "verse", number: "31", sanskrit: "ऊरुस्तम्भे तु स्नेहासृक्स्राववमनाविरेचनबस्तिकर्माणि परिहरेत् आमश्लेष्मभ्यां सह तेषां विरोधात् ऊरुलीनानां वायुना स्तब्धानां च वमनादिभिरूर्ध्वं नेतुमम्भसामिव निम्नात् स्थलमशक्यत्वात् ततस्तत्र तु बहुशः शमनशोषणानि युक्त्यावेक्ष्य युञ्जीत रूक्षोपचारान् यवश्यामाककोद्रवोद्दालकमलवणमल्पतैलसिद्धं शाकं क्षारारिष्टमधूदकानि च शीलयेत्", text: "ūrustambhe tu snehāsṛksrāvavamanāvirecanabastikarmāṇi pariharet āmaśleṣmabhyāṃ saha teṣāṃ virodhāt ūrulīnānāṃ vāyunā stabdhānāṃ ca vamanādibhirūrdhvaṃ netumambhasāmiva nimnāt sthalamaśakyatvāt tatastatra tu bahuśaḥ śamanaśoṣaṇāni yuktyāvekṣya yuñjīta rūkṣopacārān yavaśyāmākakodravoddālakamalavaṇamalpatailasiddhaṃ śākaṃ kṣārāriṣṭamadhūdakāni ca śīlayet" },
      { type: "verse", number: "32", sanskrit: "स सैन्धवं वचादिं हरिद्रादिं वत्सकादिं वा षड्धरणं वा हरीतकीः पिप्पलीर्वा शार्ङ्गेष्टामदनदन्तीवत्सकं वा स्वादुकण्टकारग्वधदार्वीमरुबकपाठाकरञ्जकूलकचूर्णं वा सक्षौद्रं मस्तुना पिबेत् चित्रकदेवदारुकुष्ठपाठातिक्तकरोहिणीर्वा मधुना लिह्यात् त्रिफलापिप्पलीमुस्तचविकाकटुरोहिणीर्वा स्वेदांश्च रूक्षान् कुर्यात्", text: "sa saindhavaṃ vacādiṃ haridrādiṃ vatsakādiṃ vā ṣaḍdharaṇaṃ vā harītakīḥ pippalīrvā śārṅgeṣṭāmadanadantīvatsakaṃ vā svādukaṇṭakāragvadhadārvīmarubakapāṭhākarañjakūlakacūrṇaṃ vā sakṣaudraṃ mastunā pibet citrakadevadārukuṣṭhapāṭhātiktakarohiṇīrvā madhunā lihyāt triphalāpippalīmustacavikākaṭurohiṇīrvā svedāṃśca rūkṣān kuryāt" },
      { type: "verse", number: "33", sanskrit: "अत्यपतृप्तं तु रूक्षं क्षाममनिद्रं जाङ्गलरसैः शालिभिश्च तर्पयेत् सर्षपतैलं वा सरलकुष्ठश्रीवेष्टकसुरदारुनागकेसराजगन्धासिद्धं सक्षौद्रं पिबेत् ससैन्धवपलं शुण्ठीचित्रकपिप्पलीमूलानां पृथक् द्विपलं दश भल्लातकास्थीनि कल्कीकृत्यैकध्यमारनालाढकेन सह तैलप्रस्थं पचेत् तत्सर्ववातविकारेषु पथ्यं विशेषादूरुस्तम्भार्शोगृध्रसीघ्नमपत्यदं च बहिरपि श्लेष्मक्षपणाय क्षौद्रसर्षपकरञ्जफलवल्मीकमृद्गोमूत्रैरुष्णैर्लेपयेत् सौभाञ्जनतर्कारीद्वयसरलार्जुनकरञ्जाढकीगोक्षुरकैर्लेपोन्मर्दनसेकान् कुर्यात् व्यायामैश्च विविधर्मेदः क्षपयेत् स्थलान्युल्लङ्क्षयेत् प्रतिस्रोतः सरितमव्यालां तरेत् एवमूरुस्तम्भो हि शुष्केश्लेष्मणि प्रशाम्यतीति", text: "atyapatṛptaṃ tu rūkṣaṃ kṣāmamanidraṃ jāṅgalarasaiḥ śālibhiśca tarpayet sarṣapatailaṃ vā saralakuṣṭhaśrīveṣṭakasuradārunāgakesarājagandhāsiddhaṃ sakṣaudraṃ pibet sasaindhavapalaṃ śuṇṭhīcitrakapippalīmūlānāṃ pṛthak dvipalaṃ daśa bhallātakāsthīni kalkīkṛtyaikadhyamāranālāḍhakena saha tailaprasthaṃ pacet tatsarvavātavikāreṣu pathyaṃ viśeṣādūrustambhārśogṛdhrasīghnamapatyadaṃ ca bahirapi śleṣmakṣapaṇāya kṣaudrasarṣapakarañjaphalavalmīkamṛdgomūtrairuṣṇairlepayet saubhāñjanatarkārīdvayasaralārjunakarañjāḍhakīgokṣurakairleponmardanasekān kuryāt vyāyāmaiśca vividharmedaḥ kṣapayet sthalānyullaṅkṣayet pratisrotaḥ saritamavyālāṃ taret evamūrustambho hi śuṣkeśleṣmaṇi praśāmyatīti" },
      { type: "verse", number: "34", sanskrit: "भवति चात्र सहचरं सुरदारु सनागरं क्वथितमम्भसि तैलविमिश्रितम् पवनपीडितदेहगतिः पिबन् द्रुतविलम्बितगो भवतीच्छया", text: "bhavati cātra sahacaraṃ suradāru sanāgaraṃ kvathitamambhasi tailavimiśritam pavanapīḍitadehagatiḥ piban drutavilambitago bhavatīcchayā" },
      { type: "verse", number: "35", sanskrit: "रास्नामहौषधद्वीप्पिप्पलीशठिपौष्करम् पिष्ट्वा विपाचयेत्सर्पिर्वातरोगहरं परम्", text: "rāsnāmahauṣadhadvīppippalīśaṭhipauṣkaram piṣṭvā vipācayetsarpirvātarogaharaṃ param" },
      { type: "verse", number: "36", sanskrit: "निम्बामृतावृषपटोलनिदिग्धिकानां भागान् पृथग्दशपलान् विपचेद्घटे ऽपाम् अष्टांशशेषितरसेन पुनश्च तेन प्रस्थं घृतस्य विपचेत् पिचुभागकल्कैः", text: "nimbāmṛtāvṛṣapaṭolanidigdhikānāṃ bhāgān pṛthagdaśapalān vipacedghaṭe 'pām aṣṭāṃśaśeṣitarasena punaśca tena prasthaṃ ghṛtasya vipacet picubhāgakalkaiḥ" },
      { type: "verse", number: "37", sanskrit: "पाठाविडङ्गसुरदारुगजोपकुल्याद्विक्षारनागरनिशामिसिचव्यकुष्ठैः तेजोवतीमरिचवत्सकदीप्यकाग्निरोहिण्यरुष्करवचाकणमूलयुक्तैः", text: "pāṭhāviḍaṅgasuradārugajopakulyādvikṣāranāgaraniśāmisicavyakuṣṭhaiḥ tejovatīmaricavatsakadīpyakāgnirohiṇyaruṣkaravacākaṇamūlayuktaiḥ" },
      { type: "verse", number: "38", sanskrit: "मञ्जिष्ठयातिविषया विषया यवान्या संशुद्धगुग्गुलुपलैरपि पञ्चसङ्ख्यैः तत् सेवितं विधमति प्रबलं समीरं सन्ध्यस्थिमज्जगतमप्यथ कुष्ठमीदृक्", text: "mañjiṣṭhayātiviṣayā viṣayā yavānyā saṃśuddhaguggulupalairapi pañcasaṅkhyaiḥ tat sevitaṃ vidhamati prabalaṃ samīraṃ sandhyasthimajjagatamapyatha kuṣṭhamīdṛk" },
      { type: "verse", number: "39", sanskrit: "नाडीव्रणार्बुदभगन्दरगण्डमाला जत्रूर्ध्वसर्वगदगुल्मगुदोत्थमेहान् यक्ष्मारुचिश्वसनपीनसकासशोषहृत्पाण्डुरोगमदविद्रधिवातरक्तम्", text: "nāḍīvraṇārbudabhagandaragaṇḍamālā jatrūrdhvasarvagadagulmagudotthamehān yakṣmāruciśvasanapīnasakāsaśoṣahṛtpāṇḍurogamadavidradhivātaraktam" },
      { type: "verse", number: "40", sanskrit: "द्रोणे ऽम्भसः पचेद्भागान् दशमूलाच्चतुष्पलान् यवकोलकुलत्थानां भागैः प्रस्थोन्मितैः सह", text: "droṇe 'mbhasaḥ pacedbhāgān daśamūlāccatuṣpalān yavakolakulatthānāṃ bhāgaiḥ prasthonmitaiḥ saha" },
      { type: "verse", number: "41", sanskrit: "पादशेषे रसे पिष्टैर्जीवनीयैः सशर्करैः तद्वत्खर्जूरकाश्मर्यद्राक्षाबदरफल्गुभिः", text: "pādaśeṣe rase piṣṭairjīvanīyaiḥ saśarkaraiḥ tadvatkharjūrakāśmaryadrākṣābadaraphalgubhiḥ" },
      { type: "verse", number: "42", sanskrit: "सक्षीरैः सर्पिषः प्रस्थः सिद्धः केवलवातनुत् योज्यो निरत्ययः पाननस्याभ्यञ्जनबस्तिषु", text: "sakṣīraiḥ sarpiṣaḥ prasthaḥ siddhaḥ kevalavātanut yojyo niratyayaḥ pānanasyābhyañjanabastiṣu" },
      { type: "verse", number: "43", sanskrit: "बलाबिल्वशृते क्षीरे घृतमण्डं विपाचयेत् तस्य शुक्तिः प्रकुञ्चो वा नस्यं वाते शिरोगते", text: "balābilvaśṛte kṣīre ghṛtamaṇḍaṃ vipācayet tasya śuktiḥ prakuñco vā nasyaṃ vāte śirogate" },
      { type: "verse", number: "44", sanskrit: "तद्वत्सिद्धा वसा नक्रमत्स्यकूर्मबुलूकजा प्रत्यग्रा विधिनानेन नस्यपानेषु योजयेत्", text: "tadvatsiddhā vasā nakramatsyakūrmabulūkajā pratyagrā vidhinānena nasyapāneṣu yojayet" },
      { type: "verse", number: "45", sanskrit: "जीर्णं पिण्याकं पञ्चमूलं पृथक् च क्वाथं क्वाथाभ्यामेकतस्तैलमाभ्याम् क्षीरादष्टांशं पाचयेत्तेन पानाद्वाता नश्येयुः श्लेष्मयुक्ता विशेषात्", text: "jīrṇaṃ piṇyākaṃ pañcamūlaṃ pṛthak ca kvāthaṃ kvāthābhyāmekatastailamābhyām kṣīrādaṣṭāṃśaṃ pācayettena pānādvātā naśyeyuḥ śleṣmayuktā viśeṣāt" },
      { type: "verse", number: "46", sanskrit: "समूलशाखस्य सहाचरस्य तुलां समेतां दशमूलतश्च अभीरुमूलाच्च तुलार्धमेतदष्टांशशेषं विपचेद्वहे ऽपाम्", text: "samūlaśākhasya sahācarasya tulāṃ sametāṃ daśamūlataśca abhīrumūlācca tulārdhametadaṣṭāṃśaśeṣaṃ vipacedvahe 'pām" },
      { type: "verse", number: "47", sanskrit: "तत्र सेव्यनखकुष्ठहिमैलास्पृक्प्रियङ्गुनलिकाम्बुशिलाजैः लोहितानलदलोहसुराह्वैः कोपनामिशितुरुष्कनतैश्च", text: "tatra sevyanakhakuṣṭhahimailāspṛkpriyaṅgunalikāmbuśilājaiḥ lohitānaladalohasurāhvaiḥ kopanāmiśituruṣkanataiśca" },
      { type: "verse", number: "48", sanskrit: "तुल्यक्षीरं पालिकैस्तैलपात्रं सिद्धं कृच्छ्रान् शीलितं हन्ति वातान् कम्पाक्षेपस्तम्भशोषादियुक्तान् गुल्मोन्मादौ पीनसान्योनिरोगान्", text: "tulyakṣīraṃ pālikaistailapātraṃ siddhaṃ kṛcchrān śīlitaṃ hanti vātān kampākṣepastambhaśoṣādiyuktān gulmonmādau pīnasānyonirogān" },
      { type: "verse", number: "49", sanskrit: "केतकिमूलबलातिबलानां यद्बहलेन रसेन विपक्वम् तैलमनल्पतुषोदकयुक्तं मारुतमस्थिगतं तदपोहेत्", text: "ketakimūlabalātibalānāṃ yadbahalena rasena vipakvam tailamanalpatuṣodakayuktaṃ mārutamasthigataṃ tadapohet" },
      { type: "verse", number: "50", sanskrit: "तुलां लशुनकन्दस्य तुलार्धं जाङ्गलात् पलात् दशमूलाच्च विपचेद्भागान् पञ्चपलान् पृथक्", text: "tulāṃ laśunakandasya tulārdhaṃ jāṅgalāt palāt daśamūlācca vipacedbhāgān pañcapalān pṛthak" },
      { type: "verse", number: "51", sanskrit: "तोयार्मणेण पादस्थे समं तैलं पयो दधि तत्र दद्यात् पलांशांश्च रास्नामधुकजीवकान्", text: "toyārmaṇeṇa pādasthe samaṃ tailaṃ payo dadhi tatra dadyāt palāṃśāṃśca rāsnāmadhukajīvakān" },
      { type: "verse", number: "52", sanskrit: "मिशिस्थिरामहामेदाचपलातिविषाबलाः काकोली पौष्करं मूलमश्वगन्धां च साधितम्", text: "miśisthirāmahāmedācapalātiviṣābalāḥ kākolī pauṣkaraṃ mūlamaśvagandhāṃ ca sādhitam" },
      { type: "verse", number: "53", sanskrit: "तत्परं वातरोगघ्नं गुल्मानाहार्तिशूलनुत् भग्नजर्जरिताङ्गानां पथ्यमग्नेश्च दीपनम्", text: "tatparaṃ vātarogaghnaṃ gulmānāhārtiśūlanut bhagnajarjaritāṅgānāṃ pathyamagneśca dīpanam" },
      { type: "verse", number: "54", sanskrit: "समूलजालां विपचेत् प्रसारिणीं तुलोन्मितां पादधृते घटे ऽम्भसः पृथक् सतैलं दधि तत्समं क्षिपेत् समं च ताभ्यां विजयां ततः पचेत्", text: "samūlajālāṃ vipacet prasāriṇīṃ tulonmitāṃ pādadhṛte ghaṭe 'mbhasaḥ pṛthak satailaṃ dadhi tatsamaṃ kṣipet samaṃ ca tābhyāṃ vijayāṃ tataḥ pacet" },
      { type: "verse", number: "55", sanskrit: "प्रसारिणीजीवकसिन्धुजन्मयष्ट्याह्वरास्नाग्निकयावशूकैः सग्रन्थिकाख्यैर्द्विपलैः सुपिष्टैः भल्लातकानां दशकैस्त्रिभीश्च", text: "prasāriṇījīvakasindhujanmayaṣṭyāhvarāsnāgnikayāvaśūkaiḥ sagranthikākhyairdvipalaiḥ supiṣṭaiḥ bhallātakānāṃ daśakaistribhīśca" },
      { type: "verse", number: "56", sanskrit: "शुण्ठीपलत्रययुतैर्विनिहन्ति पाननस्यादिभिस्तदखिलान् मरुतो विकारान् कुष्ठप्रमेहहतनाममनोविकारश्वासास्थिभङ्गजठरक्रिमिबीजदोषान्", text: "śuṇṭhīpalatrayayutairvinihanti pānanasyādibhistadakhilān maruto vikārān kuṣṭhapramehahatanāmamanovikāraśvāsāsthibhaṅgajaṭharakrimibījadoṣān" },
      { type: "verse", number: "57", sanskrit: "पचेत् सहाचरतुलां जलद्रोणचतुष्टये द्रोणशेषे समक्षीरे तत्र तैलाढकं पचेत्", text: "pacet sahācaratulāṃ jaladroṇacatuṣṭaye droṇaśeṣe samakṣīre tatra tailāḍhakaṃ pacet" },
      { type: "verse", number: "58", sanskrit: "सहाचरस्य मूलानां कल्कितैर्दशाभिः पलैः अथवा नतषड्ग्रन्थास्थिराकुष्ठसुराह्वयात्", text: "sahācarasya mūlānāṃ kalkitairdaśābhiḥ palaiḥ athavā nataṣaḍgranthāsthirākuṣṭhasurāhvayāt" },
      { type: "verse", number: "59", sanskrit: "सैलानलदशौलेयशताह्वारक्तचन्दनात् सिद्धे ऽस्मिन् शर्कराचूर्णादष्टादशपलं क्षिपेत्", text: "sailānaladaśauleyaśatāhvāraktacandanāt siddhe 'smin śarkarācūrṇādaṣṭādaśapalaṃ kṣipet" },
      { type: "verse", number: "60", sanskrit: "भेडस्य संमतं तैलं तत् कृच्छ्राननिलामयान् वातकुण्डलिकोन्मादभूतापस्मारवर्ध्म च गुल्महृद्रोगदुर्नामयोनिरोगांश्च नाशयेत्", text: "bheḍasya saṃmataṃ tailaṃ tat kṛcchrānanilāmayān vātakuṇḍalikonmādabhūtāpasmāravardhma ca gulmahṛdrogadurnāmayonirogāṃśca nāśayet" },
      { type: "verse", number: "61", sanskrit: "श्वदंष्ट्रककषायस्य प्रस्थौ द्वौ पयसा समौ षट्पलं शृङ्गवेरस्य गुडस्य च पलाष्टकम् तैलप्रस्थं विपक्वं तद्दद्यात् सर्वानिलार्तिषु", text: "śvadaṃṣṭrakakaṣāyasya prasthau dvau payasā samau ṣaṭpalaṃ śṛṅgaverasya guḍasya ca palāṣṭakam tailaprasthaṃ vipakvaṃ taddadyāt sarvānilārtiṣu" },
      { type: "verse", number: "62", sanskrit: "बलाशतं छिन्नरुहापादं रास्नाष्टभागिकम् जलाढकशते पक्त्वा शतभागाथिते रसे", text: "balāśataṃ chinnaruhāpādaṃ rāsnāṣṭabhāgikam jalāḍhakaśate paktvā śatabhāgāthite rase" },
      { type: "verse", number: "63", sanskrit: "दधिमस्त्विक्षुनिर्यासशुक्तैस्तैलाढकं समैः पचेत्साजपयोर्धांशं कल्कैरेभिः पलोन्मितैः", text: "dadhimastvikṣuniryāsaśuktaistailāḍhakaṃ samaiḥ pacetsājapayordhāṃśaṃ kalkairebhiḥ palonmitaiḥ" },
      { type: "verse", number: "64", sanskrit: "शठीसरलदार्वेलामञ्जिष्ठागरुचन्दनैः पद्मकातिबलामुस्तासूप्यपर्णीहरेणुभिः", text: "śaṭhīsaraladārvelāmañjiṣṭhāgarucandanaiḥ padmakātibalāmustāsūpyaparṇīhareṇubhiḥ" },
      { type: "verse", number: "65", sanskrit: "यष्ठ्याह्वसुरसव्याघ्रनखर्षभकजीवकैः पलाशरसकस्तूरीनलिकाजातिकोशकैः", text: "yaṣṭhyāhvasurasavyāghranakharṣabhakajīvakaiḥ palāśarasakastūrīnalikājātikośakaiḥ" },
      { type: "verse", number: "66", sanskrit: "स्पृक्काकुङ्कुमशैलेयजातीकटुफलाम्बुभिः त्वक्कुन्दुरुककर्पूरतुरुष्कश्रीनिवासकैः", text: "spṛkkākuṅkumaśaileyajātīkaṭuphalāmbubhiḥ tvakkundurukakarpūraturuṣkaśrīnivāsakaiḥ" },
      { type: "verse", number: "67", sanskrit: "लवङ्गनखकंकोलकुष्ठमांसीप्रियङ्गुभिः स्थौणेयतगरध्यामवचामदनकप्लवैः", text: "lavaṅganakhakaṃkolakuṣṭhamāṃsīpriyaṅgubhiḥ sthauṇeyatagaradhyāmavacāmadanakaplavaiḥ" },
      { type: "verse", number: "68", sanskrit: "सनागकेसरैः सिद्धे दद्याच्चात्रावतारिते पत्रकल्कं ततः पूतं विधिना तत् प्रयोजितम्", text: "sanāgakesaraiḥ siddhe dadyāccātrāvatārite patrakalkaṃ tataḥ pūtaṃ vidhinā tat prayojitam" },
      { type: "verse", number: "69", sanskrit: "श्वासं कासं ज्वरं मूर्छां छर्दिं तृष्णां क्षतं क्षयम् प्लीहशोषावपस्मारमलक्ष्मीं च प्रणाशयेत् बलातैलमिदं श्रेष्ठं वातव्याधिविनाशनम्", text: "śvāsaṃ kāsaṃ jvaraṃ mūrchāṃ chardiṃ tṛṣṇāṃ kṣataṃ kṣayam plīhaśoṣāvapasmāramalakṣmīṃ ca praṇāśayet balātailamidaṃ śreṣṭhaṃ vātavyādhivināśanam" },
      { type: "verse", number: "70", sanskrit: "अमृतायास्तुलाः पञ्च पचेत्तोयवहद्वये पादशेषे समक्षीरं तैलस्य द्व्याढकं पचेत्", text: "amṛtāyāstulāḥ pañca pacettoyavahadvaye pādaśeṣe samakṣīraṃ tailasya dvyāḍhakaṃ pacet" },
      { type: "verse", number: "71", sanskrit: "एलामांसीनतोशीरसारिवाकुष्ठचन्दनैः शतपुष्पाबलामेदामहामेदर्धिजीवकैः", text: "elāmāṃsīnatośīrasārivākuṣṭhacandanaiḥ śatapuṣpābalāmedāmahāmedardhijīvakaiḥ" },
      { type: "verse", number: "72", sanskrit: "काकोलीक्षीरकाकोलीश्रावण्यतिबलानखैः महाश्रावणिजीवन्तीविदारीकपिकच्छुभिः", text: "kākolīkṣīrakākolīśrāvaṇyatibalānakhaiḥ mahāśrāvaṇijīvantīvidārīkapikacchubhiḥ" },
      { type: "verse", number: "73", sanskrit: "शतावरीतामलकीकर्कटाह्वाहरेणुभिः वचागोक्षुरकैरण्डारास्नाकालासहाचरैः", text: "śatāvarītāmalakīkarkaṭāhvāhareṇubhiḥ vacāgokṣurakairaṇḍārāsnākālāsahācaraiḥ" },
      { type: "verse", number: "74", sanskrit: "वीरामहैलर्षभकत्रिदशाह्वैश्च कार्षिकैः मञ्जिष्ठायास्त्रिकर्षेण मधुकाष्टपलेन च", text: "vīrāmahailarṣabhakatridaśāhvaiśca kārṣikaiḥ mañjiṣṭhāyāstrikarṣeṇa madhukāṣṭapalena ca" },
      { type: "verse", number: "75", sanskrit: "कल्कैस्तत्क्षीणवीर्याग्निबलसम्मूढचेतसः उन्मादारत्यपस्मारैरार्तांश्च प्रकृतिं नयेत्", text: "kalkaistatkṣīṇavīryāgnibalasammūḍhacetasaḥ unmādāratyapasmārairārtāṃśca prakṛtiṃ nayet" },
      { type: "verse", number: "76", sanskrit: "वातव्याधिहरं श्रेष्ठं तैलाग्र्यममृताह्वयम् रास्नासहस्रनिर्यूहे तैलद्रोणं विपाचयेत् गन्धैर्हैमवतैः पिष्टैरेलाद्यैश्चानिलार्तिनुत् एष कल्पो ऽश्वगन्धाया बलातिबलयोरपि", text: "vātavyādhiharaṃ śreṣṭhaṃ tailāgryamamṛtāhvayam rāsnāsahasraniryūhe tailadroṇaṃ vipācayet gandhairhaimavataiḥ piṣṭairelādyaiścānilārtinut eṣa kalpo 'śvagandhāyā balātibalayorapi" },
      { type: "verse", number: "77", sanskrit: "क्वाथकल्कपयोभिर्वा बलादीनां पृथक् पचेत् यवकोलकुलत्थानां मत्स्यानां शिग्रुबिल्वयोः", text: "kvāthakalkapayobhirvā balādīnāṃ pṛthak pacet yavakolakulatthānāṃ matsyānāṃ śigrubilvayoḥ" },
      { type: "verse", number: "78", sanskrit: "रसेन मूलकानां च तैलं दधिपयोन्वितम् साधयेत्तत् परं सर्वपवनव्याधिभेषजम्", text: "rasena mūlakānāṃ ca tailaṃ dadhipayonvitam sādhayettat paraṃ sarvapavanavyādhibheṣajam" },
      { type: "verse", number: "79", sanskrit: "यच्च शीतज्वरे तैलमगर्वाद्यमुदाहृतम् सहस्रशतशः पक्त्वा सिद्धं वातामयापहम्", text: "yacca śītajvare tailamagarvādyamudāhṛtam sahasraśataśaḥ paktvā siddhaṃ vātāmayāpaham" },
      { type: "verse", number: "80", sanskrit: "फलत्रिकस्य प्रस्थं स्यात् कुलत्थं कुडवद्वयम् कृष्णगन्धात्वगाढक्योः पृथक् पञ्चपलानि तु", text: "phalatrikasya prasthaṃ syāt kulatthaṃ kuḍavadvayam kṛṣṇagandhātvagāḍhakyoḥ pṛthak pañcapalāni tu" },
      { type: "verse", number: "81", sanskrit: "रास्नाचित्रकयोर्द्वे द्वे दशमूलात् पलं पलम् जलद्रोणे पचेत् पादशेषे प्रस्थोन्मितं पृथक्", text: "rāsnācitrakayordve dve daśamūlāt palaṃ palam jaladroṇe pacet pādaśeṣe prasthonmitaṃ pṛthak" },
      { type: "verse", number: "82", sanskrit: "सुरारनालदध्यम्लसौवीरकतुषोदकम् कोलदाडिमवृक्षाम्लरसं क्षीरं वसां नवाम्", text: "surāranāladadhyamlasauvīrakatuṣodakam koladāḍimavṛkṣāmlarasaṃ kṣīraṃ vasāṃ navām" },
      { type: "verse", number: "83", sanskrit: "मज्जानं तैलमाज्यं च जीवनीयपलानि षट् कल्कमेकत्र तत् सिद्धं सिद्धं शुद्धानिलामये", text: "majjānaṃ tailamājyaṃ ca jīvanīyapalāni ṣaṭ kalkamekatra tat siddhaṃ siddhaṃ śuddhānilāmaye" },
      { type: "verse", number: "84", sanskrit: "सिरापर्वास्थिगे वाते सर्वाङ्गैकाङ्गरोगिषु वेपनाक्षेपशूलेषु तमभ्यङ्गं प्रयोजयेत्", text: "sirāparvāsthige vāte sarvāṅgaikāṅgarogiṣu vepanākṣepaśūleṣu tamabhyaṅgaṃ prayojayet" },
      { type: "verse", number: "85", sanskrit: "आनूपजाङ्गलोत्थानामस्थीनि विपचेज्जले तत्स्नेहं दशमूलस्य कषायेण पुनः पचेत्", text: "ānūpajāṅgalotthānāmasthīni vipacejjale tatsnehaṃ daśamūlasya kaṣāyeṇa punaḥ pacet" },
      { type: "verse", number: "86", sanskrit: "जीवकर्षभकास्फोतविदारीकपिकच्छुभिः वातघ्नैर्दीपनीयैश्च कल्कैर्द्विक्षीरभागिकैः", text: "jīvakarṣabhakāsphotavidārīkapikacchubhiḥ vātaghnairdīpanīyaiśca kalkairdvikṣīrabhāgikaiḥ" },
      { type: "verse", number: "87", sanskrit: "सिरापर्वास्थिकोष्ठस्थं पानाद्यैर्हन्ति तच्चलम् क्षीणौजोमज्जशुक्राणामेतत् स्यादमृतोपमम्", text: "sirāparvāsthikoṣṭhasthaṃ pānādyairhanti taccalam kṣīṇaujomajjaśukrāṇāmetat syādamṛtopamam" },
      { type: "verse", number: "88", sanskrit: "पाने नस्ये ऽन्वासने ऽभ्यञ्जने च स्नेहाः काले सम्यगेते प्रयुक्ताः दुष्टान् वातानाशु शान्तिं नयेयुर्वन्ध्या नरीः पुत्रभाजश्च कुर्युः", text: "pāne nasye 'nvāsane 'bhyañjane ca snehāḥ kāle samyagete prayuktāḥ duṣṭān vātānāśu śāntiṃ nayeyurvandhyā narīḥ putrabhājaśca kuryuḥ" },
      { type: "verse", number: "89", sanskrit: "स्नेहस्वेदैर्द्रुतः श्लेष्मा यदा पक्वाशये स्थितः पित्तं वा दर्शयेद्रूपं बस्तिभिस्तं विनिर्जयेत्", text: "snehasvedairdrutaḥ śleṣmā yadā pakvāśaye sthitaḥ pittaṃ vā darśayedrūpaṃ bastibhistaṃ vinirjayet" },
    ],
  },
  {
    sthana: "Чикитса стхана",
    number: 24,
    lang: "sa",
    content: [
      { type: "heading", heading: "Чикитса самапти — завершение Чикитса стханы" },
      { type: "text", text: "Глава 24 Чикитса стханы — лечебный раздел о завершение Чикитса стханы. Вагбхата описывает лечение детально, с конкретными формулами и дозировками." },
      { type: "verse", number: "1", sanskrit: "अथातो वातशोणितचिकित्सितं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vātaśoṇitacikitsitaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "वातशोणितिनः स्निग्धस्य दाहरागरुक्तोदेषु जलौकोभिः कण्डूपतापस्वापचिमिचिमायनेषु शृङ्गतुम्बैर्दशाद्देशान्तरं सञ्चरत् सिरया प्रच्छानेन वा दुष्टमसृगसकृदल्पमवसेचयेत्", text: "vātaśoṇitinaḥ snigdhasya dāharāgaruktodeṣu jalaukobhiḥ kaṇḍūpatāpasvāpacimicimāyaneṣu śṛṅgatumbairdaśāddeśāntaraṃ sañcarat sirayā pracchānena vā duṣṭamasṛgasakṛdalpamavasecayet" },
      { type: "verse", number: "3", sanskrit: "असृक्क्षये हि गम्भीरशोफस्तम्भकम्पग्लानि सङ्गोचादयः स्युः सिराव्यधोक्ताश्च मूर्छादयः नैव च स्रावयेदङ्गग्लानौ रूक्षे वातोत्तरं च रक्तम् ततश्च पुनः स्नेहयुक्तानि रूक्षाणि वा विरेचनानि बस्तिकर्म चासकृत् प्रयोजयेत्", text: "asṛkkṣaye hi gambhīraśophastambhakampaglāni saṅgocādayaḥ syuḥ sirāvyadhoktāśca mūrchādayaḥ naiva ca srāvayedaṅgaglānau rūkṣe vātottaraṃ ca raktam tataśca punaḥ snehayuktāni rūkṣāṇi vā virecanāni bastikarma cāsakṛt prayojayet" },
      { type: "verse", number: "4", sanskrit: "अथ वातप्रबले पुराणघृतं पिबेच्छतावरीघृतं वा", text: "atha vātaprabale purāṇaghṛtaṃ pibecchatāvarīghṛtaṃ vā" },
      { type: "verse", number: "5", sanskrit: "दशमूलपुनर्नवद्वयैरण्डमुद्गपर्णीमाषपर्णीमहामेदाशतावरीरास्नावाक्पुष्पीशङ्खपुष्पीबलातिबला द्विपलांशाः पृथक् जलद्रोणे विपाचयेत् पादशेषे च तत्तुल्यानि पृथक् छागमांसामलकेक्षुरसघृतक्षीराणि संयोज्य कल्कं च पिप्पलीमरिचकाश्मर्यफलोत्पलद्विमेदाद्विश्रावणीवीरापुनर्नवनागरसमङ्गातुगाक्षीरीक्षीरकाकोलीद्राक्षाक्षोडपद्मबीजशृङ्गाटकनिकोचकभव्योरुमाणखर्जूरवाताममुञ्जाताभिषुकाणां पुनः पचेत् एतज्जीवनीयाख्यं सर्पिर्वातविकारान् विशेषतश्च पाण्डुरोगज्वरापस्मारभगन्दरश्वासकासहिध्मास्वरभेदपार्श्वशूलयकृत्प्लीहमूत्रसङ्गाश्मरीवात्तशोणितसर्वाङ्गैकाङ्गरोगानपहरति बल्यं वर्ण्यं वृष्यं चक्षुष्यं पुत्रदं च तैलसात्म्यो वा क्षीरसितोपेतं तैलं पिबेत्", text: "daśamūlapunarnavadvayairaṇḍamudgaparṇīmāṣaparṇīmahāmedāśatāvarīrāsnāvākpuṣpīśaṅkhapuṣpībalātibalā dvipalāṃśāḥ pṛthak jaladroṇe vipācayet pādaśeṣe ca tattulyāni pṛthak chāgamāṃsāmalakekṣurasaghṛtakṣīrāṇi saṃyojya kalkaṃ ca pippalīmaricakāśmaryaphalotpaladvimedādviśrāvaṇīvīrāpunarnavanāgarasamaṅgātugākṣīrīkṣīrakākolīdrākṣākṣoḍapadmabījaśṛṅgāṭakanikocakabhavyorumāṇakharjūravātāmamuñjātābhiṣukāṇāṃ punaḥ pacet etajjīvanīyākhyaṃ sarpirvātavikārān viśeṣataśca pāṇḍurogajvarāpasmārabhagandaraśvāsakāsahidhmāsvarabhedapārśvaśūlayakṛtplīhamūtrasaṅgāśmarīvāttaśoṇitasarvāṅgaikāṅgarogānapaharati balyaṃ varṇyaṃ vṛṣyaṃ cakṣuṣyaṃ putradaṃ ca tailasātmyo vā kṣīrasitopetaṃ tailaṃ pibet" },
      { type: "verse", number: "6", sanskrit: "अथवा शतावरीमयूरकक्षीरविदारीबलाद्वयतृणपञ्चमूलक्वाथे पद्मकादिगर्भं साधितम् बलातैलं वा वातव्याध्युक्तम् शतपाकं वा वातहरसिद्धेन पयसाम्लैर्वा स्पर्शसुखं परिषेकं कुर्वीत", text: "athavā śatāvarīmayūrakakṣīravidārībalādvayatṛṇapañcamūlakvāthe padmakādigarbhaṃ sādhitam balātailaṃ vā vātavyādhyuktam śatapākaṃ vā vātaharasiddhena payasāmlairvā sparśasukhaṃ pariṣekaṃ kurvīta" },
      { type: "verse", number: "7", sanskrit: "प्रत्येकशो यवगोधूमतिलमुद्गमाषेषु काकोलीजीवकर्षभकबलातिबलातिबलाशृगालविन्नामेषशृङ्गीप्रियालसितोपलासुरभिवचाकशेरुकल्कमिश्रेषूपनाहार्थं सर्पिस्तैलवसामज्जदुग्धसिद्धान् पञ्च पायसानुपकल्पयेत् स्नैहिकफलमज्जोत्कारिकां वा बिल्वपेशिकातगरदेवदारुसरलरास्नाहरेणुकुष्ठशतपुष्पाभिर्वा दधिमस्तुयुक्ताभिरुपनाहः", text: "pratyekaśo yavagodhūmatilamudgamāṣeṣu kākolījīvakarṣabhakabalātibalātibalāśṛgālavinnāmeṣaśṛṅgīpriyālasitopalāsurabhivacākaśerukalkamiśreṣūpanāhārthaṃ sarpistailavasāmajjadugdhasiddhān pañca pāyasānupakalpayet snaihikaphalamajjotkārikāṃ vā bilvapeśikātagaradevadārusaralarāsnāhareṇukuṣṭhaśatapuṣpābhirvā dadhimastuyuktābhirupanāhaḥ" },
      { type: "verse", number: "8", sanskrit: "यवमधुकैरण्डबीजपुनर्नवैर्धान्याम्बुपिष्टैः प्रलेपः मातुलुङ्गाम्लवेतससैन्धवघृतमिश्रं वा शिग्रुमूलम् सहचरजीवन्तीमूलं वा रास्नामधुकगुडूचीबलाद्वयजीवकर्षभकल्कक्षीरसिद्धं ससिक्थकं सर्पिरभ्यङ्गः", text: "yavamadhukairaṇḍabījapunarnavairdhānyāmbupiṣṭaiḥ pralepaḥ mātuluṅgāmlavetasasaindhavaghṛtamiśraṃ vā śigrumūlam sahacarajīvantīmūlaṃ vā rāsnāmadhukaguḍūcībalādvayajīvakarṣabhakalkakṣīrasiddhaṃ sasikthakaṃ sarpirabhyaṅgaḥ" },
      { type: "verse", number: "9", sanskrit: "पित्तप्रबले द्राक्षारेवतफलपयस्यामधुकचन्दनकाश्मर्यकषायं शर्करामधुमधुरं पाययेत् शतावरीपटोलत्रिफलागुडूचीकटुकाकषायं वा स्वादुतिक्तवर्गसिद्धं च सर्पिः क्षीरं च रास्नाभीरुदशमूलबलासिद्धं वा धारोष्णं वा विरेकार्थे त्रिवृच्चूर्णयुक्तं वा क्षीराहारो वा क्षीरेणैरण्डतैलं बहुशः पिबेत् अमृतारग्वधाटरूषककषायेण वा क्षीरबस्तीन् वा सघृतान् दद्यात्", text: "pittaprabale drākṣārevataphalapayasyāmadhukacandanakāśmaryakaṣāyaṃ śarkarāmadhumadhuraṃ pāyayet śatāvarīpaṭolatriphalāguḍūcīkaṭukākaṣāyaṃ vā svādutiktavargasiddhaṃ ca sarpiḥ kṣīraṃ ca rāsnābhīrudaśamūlabalāsiddhaṃ vā dhāroṣṇaṃ vā virekārthe trivṛccūrṇayuktaṃ vā kṣīrāhāro vā kṣīreṇairaṇḍatailaṃ bahuśaḥ pibet amṛtāragvadhāṭarūṣakakaṣāyeṇa vā kṣīrabastīn vā saghṛtān dadyāt" },
      { type: "verse", number: "10", sanskrit: "शीतैश्च चन्दनपद्मकबिसमृणालादिभिः शृतेन क्षीरेण परिषेकः क्षीरेक्षुरसमधुशर्करातण्डुलोदकेन वा द्राक्षामधुककाश्मर्ययुतेन वा धान्याम्लेन वा जीवनीयसिद्धेन वा सर्पिषा शतधौतेन वा", text: "śītaiśca candanapadmakabisamṛṇālādibhiḥ śṛtena kṣīreṇa pariṣekaḥ kṣīrekṣurasamadhuśarkarātaṇḍulodakena vā drākṣāmadhukakāśmaryayutena vā dhānyāmlena vā jīvanīyasiddhena vā sarpiṣā śatadhautena vā" },
      { type: "verse", number: "11", sanskrit: "मसूरोशीरप्रपौण्डरीकदार्वीमधुकमञ्जिष्ठाचन्दनोत्पलपद्मकैरकासक्तुभिः सघृतक्षीरशर्करैः प्रेदहे दाहरागरुग्विसर्पशोफहरः गोधूमचूर्णो वा छागक्षीरसंयुक्तो लेपः तिलाश्च पयसा पिष्टाः भृष्टाः कपाले पुनः पयसि प्रक्षिप्य निर्वापिताः", text: "masūrośīraprapauṇḍarīkadārvīmadhukamañjiṣṭhācandanotpalapadmakairakāsaktubhiḥ saghṛtakṣīraśarkaraiḥ predahe dāharāgarugvisarpaśophaharaḥ godhūmacūrṇo vā chāgakṣīrasaṃyukto lepaḥ tilāśca payasā piṣṭāḥ bhṛṣṭāḥ kapāle punaḥ payasi prakṣipya nirvāpitāḥ" },
      { type: "verse", number: "12", sanskrit: "रक्तप्रबले ऽप्येवं बहुशश्च शोणितमवसेचयेत्", text: "raktaprabale 'pyevaṃ bahuśaśca śoṇitamavasecayet" },
      { type: "verse", number: "13", sanskrit: "श्लेष्मप्रबले धात्रीनिशामुस्ताकषायं मधुमधुरपिबेत् त्रिफलाकषायं वा मधुकशृङ्गिवेराभयाकटुरोहिणीनिर्यूहं वा यथार्हस्नेहपीतं च मृदु वामयेद्विरूक्षयेच्च न चातिसेकलेपान् दद्यात्", text: "śleṣmaprabale dhātrīniśāmustākaṣāyaṃ madhumadhurapibet triphalākaṣāyaṃ vā madhukaśṛṅgiverābhayākaṭurohiṇīniryūhaṃ vā yathārhasnehapītaṃ ca mṛdu vāmayedvirūkṣayecca na cātisekalepān dadyāt" },
      { type: "verse", number: "14", sanskrit: "निम्बसर्षपाश्वगन्धाक्षारतिलैः कोष्णैर्लेपः वचागारधूमद्विनिशाकुष्ठशतपुष्पाभिर्वा पुनर्नवेन वा सघृतेन तिलसर्षपातसीयवचूर्णो वा श्लेष्मातककपित्थमधुशिग्रुमिश्रः क्षारमूत्रपिष्टः कटुकस्कन्धसिद्धैः क्षारोदकतैलमूत्रैः सेकः", text: "nimbasarṣapāśvagandhākṣāratilaiḥ koṣṇairlepaḥ vacāgāradhūmadviniśākuṣṭhaśatapuṣpābhirvā punarnavena vā saghṛtena tilasarṣapātasīyavacūrṇo vā śleṣmātakakapitthamadhuśigrumiśraḥ kṣāramūtrapiṣṭaḥ kaṭukaskandhasiddhaiḥ kṣārodakatailamūtraiḥ sekaḥ" },
      { type: "verse", number: "15", sanskrit: "संसर्गे मिश्रं यथोद्रेकं वा प्रतिकुर्यात् सर्वेषु च यथायथं गुडूचीं गुडहरीतकीं पिप्पलीवर्धमानं वा शीलयेद्बस्तिकर्म चाभीक्ष्णमिति भवति चात्र", text: "saṃsarge miśraṃ yathodrekaṃ vā pratikuryāt sarveṣu ca yathāyathaṃ guḍūcīṃ guḍaharītakīṃ pippalīvardhamānaṃ vā śīlayedbastikarma cābhīkṣṇamiti bhavati cātra" },
      { type: "verse", number: "16", sanskrit: "बाह्यमालेपनाभ्यङ्गपरिषेकावगाहनैः विरेकास्थापनस्नेहपानैरान्तरमाचरेत्", text: "bāhyamālepanābhyaṅgapariṣekāvagāhanaiḥ virekāsthāpanasnehapānairāntaramācaret" },
      { type: "verse", number: "17", sanskrit: "सर्पिस्तैलवसामज्जपानाभ्यञ्जनबस्तिभिः लेपोपनाहसेकैश्च कोष्णैर्वातोत्तरं जयेत्", text: "sarpistailavasāmajjapānābhyañjanabastibhiḥ lepopanāhasekaiśca koṣṇairvātottaraṃ jayet" },
      { type: "verse", number: "18", sanskrit: "विरेचनैर्घृतक्षीरपानसेचनबस्तिभिः पित्तरक्तोत्तरं वातरक्तं लेपैश्च शीतलैः", text: "virecanairghṛtakṣīrapānasecanabastibhiḥ pittaraktottaraṃ vātaraktaṃ lepaiśca śītalaiḥ" },
      { type: "verse", number: "19", sanskrit: "वमनं मृदु नात्यर्थं स्नेहसेकादिलङ्घनम् कोष्णा लेपाश्च शस्यन्ते वातरक्ते कफोत्तरे", text: "vamanaṃ mṛdu nātyarthaṃ snehasekādilaṅghanam koṣṇā lepāśca śasyante vātarakte kaphottare" },
      { type: "verse", number: "20", sanskrit: "वातश्लेष्मोत्तरे शीतैः प्रलिप्ते वातशोणिते विदाहशोफरुक्कण्डूविवृद्धिः स्तम्भनाद्भवेत्", text: "vātaśleṣmottare śītaiḥ pralipte vātaśoṇite vidāhaśopharukkaṇḍūvivṛddhiḥ stambhanādbhavet" },
      { type: "verse", number: "21", sanskrit: "पित्तरक्तोत्तरे वातरक्ते लेपादयो हिमाः उष्णैः प्लोषोषरुग्रागस्वेदावदरणोद्भवः", text: "pittaraktottare vātarakte lepādayo himāḥ uṣṇaiḥ ploṣoṣarugrāgasvedāvadaraṇodbhavaḥ" },
      { type: "verse", number: "22", sanskrit: "मधुयष्ट्याः पलशतात् कषाये पादशेषिते तैलाढकं समक्षीरं पचेत् कल्कैः पलोन्मितैः", text: "madhuyaṣṭyāḥ palaśatāt kaṣāye pādaśeṣite tailāḍhakaṃ samakṣīraṃ pacet kalkaiḥ palonmitaiḥ" },
      { type: "verse", number: "23", sanskrit: "शतपुष्पावरीमूर्वापयस्याभीरुचन्दनैः स्थिराहंसपदीमांसीद्विमेदामधुपर्णिभिः", text: "śatapuṣpāvarīmūrvāpayasyābhīrucandanaiḥ sthirāhaṃsapadīmāṃsīdvimedāmadhuparṇibhiḥ" },
      { type: "verse", number: "24", sanskrit: "काकोलीक्षीरकाकोलीतामलक्यर्धिपद्मकैः जीवन्तीजीवकर्षभत्वक्पत्रनखवालकैः", text: "kākolīkṣīrakākolītāmalakyardhipadmakaiḥ jīvantījīvakarṣabhatvakpatranakhavālakaiḥ" },
      { type: "verse", number: "25", sanskrit: "प्रपौण्डरीकमञ्जिष्ठासारिवैन्द्रीवितुन्नकैः चतुष्प्रयोगं वातासृक्पित्तदाहज्वरार्तिनुत्", text: "prapauṇḍarīkamañjiṣṭhāsārivaindrīvitunnakaiḥ catuṣprayogaṃ vātāsṛkpittadāhajvarārtinut" },
      { type: "verse", number: "26", sanskrit: "मधुयष्ट्याः पलं दत्वा तैलप्रस्थं चतुर्गुणे क्षीरे पचेच्छतं वारांस्तदेवं मधुकाच्छते", text: "madhuyaṣṭyāḥ palaṃ datvā tailaprasthaṃ caturguṇe kṣīre pacecchataṃ vārāṃstadevaṃ madhukācchate" },
      { type: "verse", number: "27", sanskrit: "सिद्धं योज्यं तृडुन्मादश्वासकासविसर्पिषु हृत्पाण्डुरोगवातासृक्पित्तादिषु च पूर्ववत्", text: "siddhaṃ yojyaṃ tṛḍunmādaśvāsakāsavisarpiṣu hṛtpāṇḍurogavātāsṛkpittādiṣu ca pūrvavat" },
      { type: "verse", number: "28", sanskrit: "कुपिते मार्गसंरोधान्मेदसो वा कफस्य वा अतिवृद्ध्यानिले शस्तं नादौ स्नेहनबृंहणम्", text: "kupite mārgasaṃrodhānmedaso vā kaphasya vā ativṛddhyānile śastaṃ nādau snehanabṛṃhaṇam" },
      { type: "verse", number: "29", sanskrit: "कृत्वा तत्राढ्यवातोक्तं वातशोणितिकं ततः भेषजं स्नेहनं कुर्याद्यच्च रक्तप्रसादनम्", text: "kṛtvā tatrāḍhyavātoktaṃ vātaśoṇitikaṃ tataḥ bheṣajaṃ snehanaṃ kuryādyacca raktaprasādanam" },
      { type: "verse", number: "30", sanskrit: "गम्भीरे रक्तमाक्रान्तं स्याच्चेद्वातेन वर्जयेत् रक्तपित्तातिवृध्या तु पाकमाशु निगच्छति", text: "gambhīre raktamākrāntaṃ syāccedvātena varjayet raktapittātivṛdhyā tu pākamāśu nigacchati" },
      { type: "verse", number: "31", sanskrit: "भिन्नं स्रवति तद्रक्तं विदग्धं पूयमेव वा तयोश्चिकित्सां व्रणवत् भेदशोधनरोपणीम्", text: "bhinnaṃ sravati tadraktaṃ vidagdhaṃ pūyameva vā tayościkitsāṃ vraṇavat bhedaśodhanaropaṇīm" },
      { type: "verse", number: "32", sanskrit: "कुर्यादुपद्रवाणां च तस्मात्तस्माच्चिकित्सितात् प्राणादिकोपे युगपद्यथोद्दिष्टं यथामयम् यथासन्नं च भैषज्यं विकल्प्यं स्याद्यथाबलम्", text: "kuryādupadravāṇāṃ ca tasmāttasmāccikitsitāt prāṇādikope yugapadyathoddiṣṭaṃ yathāmayam yathāsannaṃ ca bhaiṣajyaṃ vikalpyaṃ syādyathābalam" },
      { type: "verse", number: "33", sanskrit: "नीते निरामतां सामे स्वेदलङ्घनपाचनैः रूक्षैश्चालेपसेकाद्यैः कुर्यात् केवलवातनुत्", text: "nīte nirāmatāṃ sāme svedalaṅghanapācanaiḥ rūkṣaiścālepasekādyaiḥ kuryāt kevalavātanut" },
      { type: "verse", number: "34", sanskrit: "वायौ पित्तावृते शीतामुष्णां च बहुशः क्रियाम् व्यत्यासाद्योजयेत्सर्पिर्जीवनीयं च पाययेत्", text: "vāyau pittāvṛte śītāmuṣṇāṃ ca bahuśaḥ kriyām vyatyāsādyojayetsarpirjīvanīyaṃ ca pāyayet" },
      { type: "verse", number: "35", sanskrit: "धन्वमांसं यवः शालिर्विरेकः क्षीरवान्मृदुः सक्षीरा बस्तयः क्षीरं पञ्चमूलबलाशृतम्", text: "dhanvamāṃsaṃ yavaḥ śālirvirekaḥ kṣīravānmṛduḥ sakṣīrā bastayaḥ kṣīraṃ pañcamūlabalāśṛtam" },
      { type: "verse", number: "36", sanskrit: "काले ऽनुवासनं तैलैर्मधुरौषधसाधितैः यष्टीमधुबलातैलघृतक्षीरैश्च सेचनम् पञ्चमूलकषायेण वारिणा शीतलेन वा", text: "kāle 'nuvāsanaṃ tailairmadhurauṣadhasādhitaiḥ yaṣṭīmadhubalātailaghṛtakṣīraiśca secanam pañcamūlakaṣāyeṇa vāriṇā śītalena vā" },
      { type: "verse", number: "37", sanskrit: "कफावृते यवान्नानि जाङ्गला मृगपक्षिणः स्वेदास्तीक्ष्णा निरूहाश्च वमनं सविरेचनम्", text: "kaphāvṛte yavānnāni jāṅgalā mṛgapakṣiṇaḥ svedāstīkṣṇā nirūhāśca vamanaṃ savirecanam" },
      { type: "verse", number: "38", sanskrit: "पुराणसर्पिस्तैलं च तिलसर्षपजं हितम् संसृष्टे कफपित्ताभ्यां पित्तमादौ विनिर्जयेत्", text: "purāṇasarpistailaṃ ca tilasarṣapajaṃ hitam saṃsṛṣṭe kaphapittābhyāṃ pittamādau vinirjayet" },
      { type: "verse", number: "39", sanskrit: "कारयेद्रक्तसंसृष्टे वातशोणितिकीं क्रियाम् स्वेदाभ्यङ्गरसाः क्षीरं स्नेहो मांसावृते हितम्", text: "kārayedraktasaṃsṛṣṭe vātaśoṇitikīṃ kriyām svedābhyaṅgarasāḥ kṣīraṃ sneho māṃsāvṛte hitam" },
      { type: "verse", number: "40", sanskrit: "प्रमेहमेदोवातघ्नमाढ्यवाते भिषग्जितम् महास्नेहो ऽस्थिमज्जस्थे पूर्वोक्तं रेतसावृते", text: "pramehamedovātaghnamāḍhyavāte bhiṣagjitam mahāsneho 'sthimajjasthe pūrvoktaṃ retasāvṛte" },
      { type: "verse", number: "41", sanskrit: "अन्नावृते पाचनीयं वमनं दीपनं लघु मूत्रावृते मूत्रलानि स्वेदाश्चोत्तरबस्तयः एरण्डतैलं वर्चस्थे बस्तिस्नेहाश्च भेदिनः", text: "annāvṛte pācanīyaṃ vamanaṃ dīpanaṃ laghu mūtrāvṛte mūtralāni svedāścottarabastayaḥ eraṇḍatailaṃ varcasthe bastisnehāśca bhedinaḥ" },
      { type: "verse", number: "42", sanskrit: "कफपित्ताविरुद्धं यद्यच्च वातानुलोमनम् सर्वस्थानावृतेप्याशु तत्कार्यं मातरिश्वनि", text: "kaphapittāviruddhaṃ yadyacca vātānulomanam sarvasthānāvṛtepyāśu tatkāryaṃ mātariśvani" },
      { type: "verse", number: "43", sanskrit: "अनभिष्यन्दि च स्निग्धं स्रोतसां शुद्धिकारणम् यापना बस्तयः प्रायो मधुराः सानुवासनाः", text: "anabhiṣyandi ca snigdhaṃ srotasāṃ śuddhikāraṇam yāpanā bastayaḥ prāyo madhurāḥ sānuvāsanāḥ" },
      { type: "verse", number: "44", sanskrit: "प्रसमीक्ष्य बलाधिक्यं मृदु कार्यं विरेचनम् रसायनानां सर्वेषामुपयोगः प्रशस्यते", text: "prasamīkṣya balādhikyaṃ mṛdu kāryaṃ virecanam rasāyanānāṃ sarveṣāmupayogaḥ praśasyate" },
      { type: "verse", number: "45", sanskrit: "शिलाह्वस्य विशेषेण पयसा शुद्धगुग्गुलोः लेहो वा भार्गवस्तद्वदेकादशसिताशतः", text: "śilāhvasya viśeṣeṇa payasā śuddhagugguloḥ leho vā bhārgavastadvadekādaśasitāśataḥ" },
      { type: "verse", number: "46", sanskrit: "अपाने त्वावृते सर्वं दीपनं ग्राहि भेषजम् वातानुलोमनं कार्यं मूत्राशयविशोधनम्", text: "apāne tvāvṛte sarvaṃ dīpanaṃ grāhi bheṣajam vātānulomanaṃ kāryaṃ mūtrāśayaviśodhanam" },
      { type: "verse", number: "47", sanskrit: "इति सङ्क्षेपतः प्रोक्तमावृतानां चिकित्सितम् प्राणाद्यानां भिषक् कुर्याद्वितर्क्य स्वयमेव तत्", text: "iti saṅkṣepataḥ proktamāvṛtānāṃ cikitsitam prāṇādyānāṃ bhiṣak kuryādvitarkya svayameva tat" },
      { type: "verse", number: "48", sanskrit: "उदानं योजयेदूर्ध्वमपानं चानुलोमयेत् समानं शमयोद्विद्वांस्त्रिधा व्यानं च योजयेत्", text: "udānaṃ yojayedūrdhvamapānaṃ cānulomayet samānaṃ śamayodvidvāṃstridhā vyānaṃ ca yojayet" },
      { type: "verse", number: "49", sanskrit: "प्राणो रक्ष्यश्चतुर्भ्यो ऽपि तत्स्थितौ देहसंस्थितिः स्वं स्वं स्थानं नयेदेवं वृतान् वातान् विमार्गगान्", text: "prāṇo rakṣyaścaturbhyo 'pi tatsthitau dehasaṃsthitiḥ svaṃ svaṃ sthānaṃ nayedevaṃ vṛtān vātān vimārgagān" },
      { type: "verse", number: "50", sanskrit: "सर्वं चावरणं पित्तरक्तसंसर्गवर्जितम् रसायनविधानेन लघुनो हन्ति शीलितः", text: "sarvaṃ cāvaraṇaṃ pittaraktasaṃsargavarjitam rasāyanavidhānena laghuno hanti śīlitaḥ" },
      { type: "verse", number: "51", sanskrit: "पित्तावृते पित्तहरं मरुतश्चानुलोमनम् रक्तावृते ऽपि तद्वच्च खुडोक्तं यच्च भेषजम् पित्तरक्तानिलहितं विविधं च रसायनम्", text: "pittāvṛte pittaharaṃ marutaścānulomanam raktāvṛte 'pi tadvacca khuḍoktaṃ yacca bheṣajam pittaraktānilahitaṃ vividhaṃ ca rasāyanam" },
      { type: "verse", number: "52", sanskrit: "यथानिदानं निर्दिष्टमिति सम्यक्चिकित्सितम् आयुर्वेदफलं स्थानमेतत्सद्यो ऽर्तिनाशनात्", text: "yathānidānaṃ nirdiṣṭamiti samyakcikitsitam āyurvedaphalaṃ sthānametatsadyo 'rtināśanāt" },
      { type: "verse", number: "53", sanskrit: "चिकित्सितं हितं पथ्यं प्रायश्चित्तं भिषग्जितम् भेषजं शमनं शस्तं पर्यायैः स्मृतमौषधम् अष् चि.१६.१४: भेलविहित अष् चि.२३.६०: भेडस्य संमत", text: "cikitsitaṃ hitaṃ pathyaṃ prāyaścittaṃ bhiṣagjitam bheṣajaṃ śamanaṃ śastaṃ paryāyaiḥ smṛtamauṣadham Aṣ Ci.16.14: bhelavihita Aṣ Ci.23.60: bheḍasya saṃmata" },
    ],
  },
  {
    sthana: "Калпасиддхистхана",
    number: 1,
    lang: "sa",
    content: [
      { type: "heading", heading: "Мадана кальпа — рвотные препараты" },
      { type: "text", text: "Глава 1 Калпасиддхистханы посвящена рвотные препараты. Вагбхата систематизирует приготовление и применение очищающих средств." },
      { type: "verse", number: "1", sanskrit: "अथातो वमनकल्पं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vamanakalpaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "वमनद्रव्याणां मदनजीमूतकेक्ष्वाकुद्विकोशातकीकुटजफलानि श्रेष्ठानि तेष्वपि मदनफलम्", text: "vamanadravyāṇāṃ madanajīmūtakekṣvākudvikośātakīkuṭajaphalāni śreṣṭhāni teṣvapi madanaphalam" },
      { type: "verse", number: "3", sanskrit: "दोषदूष्यादिवशाच्चैषामेतत्कल्पनानां च प्राधान्यम्", text: "doṣadūṣyādivaśāccaiṣāmetatkalpanānāṃ ca prādhānyam" },
      { type: "verse", number: "4", sanskrit: "दोषादीनामेव चातिबह्ववस्थाभेदाद्वमनादिषु कल्पनानां व्यापदां साधनानां च यदसङ्ख्येयत्वमतो बुद्धिमतां विकल्पमार्गप्रदर्शनार्थमुदाहरणमात्रं कल्पसिद्धिस्थानमुपदेक्ष्यते", text: "doṣādīnāmeva cātibahvavasthābhedādvamanādiṣu kalpanānāṃ vyāpadāṃ sādhanānāṃ ca yadasaṅkhyeyatvamato buddhimatāṃ vikalpamārgapradarśanārthamudāharaṇamātraṃ kalpasiddhisthānamupadekṣyate" },
      { type: "verse", number: "5", sanskrit: "अथ वसन्तग्रीष्मयोरन्तरे प्रशस्ते ऽहनि मुहूर्ते च नातिहरितपाण्डूनि मदनफलान्यादाय तानि प्रमृज्य कुशमूटके बध्वा गोमयेनालिप्य यवबुसमाषशालिव्रीहिकुलत्थमुद्गान्यतमराशावष्टरात्रमुषितान्युद्धृत्यातपे शोषयेत् सुशुष्काणां पिप्पलीरुद् वृत्य दधिघृतमधुपललमृदिताः पुनः शोषयित्वा नवं कलशमरजस्कमाकण्ठं पूरयित्वा सुगुप्तं निधापयेत्", text: "atha vasantagrīṣmayorantare praśaste 'hani muhūrte ca nātiharitapāṇḍūni madanaphalānyādāya tāni pramṛjya kuśamūṭake badhvā gomayenālipya yavabusamāṣaśālivrīhikulatthamudgānyatamarāśāvaṣṭarātramuṣitānyuddhṛtyātape śoṣayet suśuṣkāṇāṃ pippalīrud vṛtya dadhighṛtamadhupalalamṛditāḥ punaḥ śoṣayitvā navaṃ kalaśamarajaskamākaṇṭhaṃ pūrayitvā suguptaṃ nidhāpayet" },
      { type: "verse", number: "6", sanskrit: "ततः प्रयोगकाले तासां फलपिप्पलीनामन्तर्नखमुष्टिं यावद्वा साधु मन्येत तावज्जर्जरीकृत्य यष्टीमधुककषाये कोविदारकच्छुदारनीपविदुलबिम्बीशणपुष्पीसदापुष्पीप्रत्यक्पुष्प्यन्यतमकषाये वा रात्रिमुषितं विमृदितं पूतं सूत्रोक्तविधिना पाययेत् श्लेष्मज्वरगुल्मप्रतिश्यायान्तर्विद्रधिषु विशेषेण पुनः पुनरापित्तागमनात् तेन साधु वमति", text: "tataḥ prayogakāle tāsāṃ phalapippalīnāmantarnakhamuṣṭiṃ yāvadvā sādhu manyeta tāvajjarjarīkṛtya yaṣṭīmadhukakaṣāye kovidārakacchudāranīpavidulabimbīśaṇapuṣpīsadāpuṣpīpratyakpuṣpyanyatamakaṣāye vā rātrimuṣitaṃ vimṛditaṃ pūtaṃ sūtroktavidhinā pāyayet śleṣmajvaragulmapratiśyāyāntarvidradhiṣu viśeṣeṇa punaḥ punarāpittāgamanāt tena sādhu vamati" },
      { type: "verse", number: "7", sanskrit: "फलपिप्पलीनां चूर्णं वा स्वक्वाथभावितं त्रिभागत्रिफलाचूर्णं कोविदारादिनिर्यूहेण बलवत्कफप्रसेकापच्यर्बुदग्रन्थिज्वरोदरारोचकेषु पिबेत्", text: "phalapippalīnāṃ cūrṇaṃ vā svakvāthabhāvitaṃ tribhāgatriphalācūrṇaṃ kovidārādiniryūheṇa balavatkaphaprasekāpacyarbudagranthijvarodarārocakeṣu pibet" },
      { type: "verse", number: "8", sanskrit: "फलमज्जचूर्णं वा जीमूतादिनिर्यूहेण पित्ते कफस्थानगते", text: "phalamajjacūrṇaṃ vā jīmūtādiniryūheṇa pitte kaphasthānagate" },
      { type: "verse", number: "9", sanskrit: "फलमज्जसिद्धं वा पयस्तस्मिन्नेव वा यवागूमधोभागे रक्तपित्ते हृद्दाहे च", text: "phalamajjasiddhaṃ vā payastasminneva vā yavāgūmadhobhāge raktapitte hṛddāhe ca" },
      { type: "verse", number: "10", sanskrit: "तस्य वा पयसः शीतस्य सन्तानिकाञ्जलिं पित्ते प्रकुपिते उरसि कण्ठे हृदये च तनुकफोपदिग्धे", text: "tasya vā payasaḥ śītasya santānikāñjaliṃ pitte prakupite urasi kaṇṭhe hṛdaye ca tanukaphopadigdhe" },
      { type: "verse", number: "11", sanskrit: "तज्जं वा दधि दध्युत्तरं वा कफच्छर्दिप्रसेकतमकेषु तस्माद्वा पयसो नवनीतमुत्पन्नं फलादिषट्कक्वाथसिद्धं कफाभिभूते ऽग्नौ शुष्यच्छरीरे च", text: "tajjaṃ vā dadhi dadhyuttaraṃ vā kaphacchardiprasekatamakeṣu tasmādvā payaso navanītamutpannaṃ phalādiṣaṭkakvāthasiddhaṃ kaphābhibhūte 'gnau śuṣyaccharīre ca" },
      { type: "verse", number: "12", sanskrit: "फलमज्जचूर्णमिश्रेण वारग्वधादि द्रव्याणां घोण्टनिम्बबाणवर्जानां ससोमवल्कपञ्चकोलकानामन्यतमस्य निर्यूहेण साधितं लेहमुपयुञ्जीत", text: "phalamajjacūrṇamiśreṇa vāragvadhādi dravyāṇāṃ ghoṇṭanimbabāṇavarjānāṃ sasomavalkapañcakolakānāmanyatamasya niryūheṇa sādhitaṃ lehamupayuñjīta" },
      { type: "verse", number: "13", sanskrit: "फलमज्जचूर्णमिश्रेण वा रेणुकैलाशताह्वाकुस्तुम्बुरुतगरकृष्ठत्वक्चोरकमरुबकागरुगुग्गुलुवालकश्रीवेष्टकपरिपेलवमांसीशैलेयस्थौणेयकसुरसारेवतपूत्यशोकरोहिणीनां द्वाविंशतेरन्यतमस्य कषायेण साधितामुत्कारिकां मोदकं वा भक्षयेत्", text: "phalamajjacūrṇamiśreṇa vā reṇukailāśatāhvākustumburutagarakṛṣṭhatvakcorakamarubakāgarugugguluvālakaśrīveṣṭakaparipelavamāṃsīśaileyasthauṇeyakasurasārevatapūtyaśokarohiṇīnāṃ dvāviṃśateranyatamasya kaṣāyeṇa sādhitāmutkārikāṃ modakaṃ vā bhakṣayet" },
      { type: "verse", number: "14", sanskrit: "फलपिप्पलीस्वरसकषायपरिपीतैर्वा तिलशालितण्डुलपिष्टैस्तत्कषायोपसृष्टैः सुरसादिद्रव्यान्यतमनिर्यूहोपसृष्टैर्वा शष्कुलीरपूपानन्यान् वा भक्ष्यान् साधयित्वा भक्षयेत्", text: "phalapippalīsvarasakaṣāyaparipītairvā tilaśālitaṇḍulapiṣṭaistatkaṣāyopasṛṣṭaiḥ surasādidravyānyatamaniryūhopasṛṣṭairvā śaṣkulīrapūpānanyān vā bhakṣyān sādhayitvā bhakṣayet" },
      { type: "verse", number: "15", sanskrit: "फलपिप्पलीनां वा भल्लातकविधिस्रुतं स्वरसमादर्वीप्रलेपात् पक्त्वा लेहयेत् अन्नपानेषु वा तं लेहमवचारयेत् तत्कषायैरेव चान्नपानानि कल्पयेत्", text: "phalapippalīnāṃ vā bhallātakavidhisrutaṃ svarasamādarvīpralepāt paktvā lehayet annapāneṣu vā taṃ lehamavacārayet tatkaṣāyaireva cānnapānāni kalpayet" },
      { type: "verse", number: "16", sanskrit: "फलमज्जक्वाथं वा वत्सकादिप्रतिवापं निम्बरूपिकान्यतरकषायोपसर्जनं सन्तर्पणोत्थसर्वश्लेष्मव्याधिहरम्", text: "phalamajjakvāthaṃ vā vatsakādiprativāpaṃ nimbarūpikānyatarakaṣāyopasarjanaṃ santarpaṇotthasarvaśleṣmavyādhiharam" },
      { type: "verse", number: "17", sanskrit: "फलपिप्पलीनां वा फलादिनिर्यूहेणैकविंशतिकृत्वः सुभावितानां कुसुमरजःसदृशेन चूर्णेनावचूर्णयेत् सरसि सरोरुहं बृहत्सायाह्ने तद्रात्रिमुषितं प्रभाते पुनरवचूर्णितमुद् वृत्य हरिद्राकृसराक्षरियवागूनामन्य तमं सैन्धवगुडफाणितोपेतमाकण्ठं पीतवानुपजिघ्रेत् सुकुमारः समुचितसुरभिर्गन्धसम्पदुत्क्लिष्टकफपित्तो भेषजद्वेषी च तथा हि सुखेन छर्दयति", text: "phalapippalīnāṃ vā phalādiniryūheṇaikaviṃśatikṛtvaḥ subhāvitānāṃ kusumarajaḥsadṛśena cūrṇenāvacūrṇayet sarasi saroruhaṃ bṛhatsāyāhne tadrātrimuṣitaṃ prabhāte punaravacūrṇitamud vṛtya haridrākṛsarākṣariyavāgūnāmanya tamaṃ saindhavaguḍaphāṇitopetamākaṇṭhaṃ pītavānupajighret sukumāraḥ samucitasurabhirgandhasampadutkliṣṭakaphapitto bheṣajadveṣī ca tathā hi sukhena chardayati" },
      { type: "verse", number: "18", sanskrit: "एतेन सर्वमाल्यगन्धप्रावरणपटा व्याख्याताः एवमेव च फलाभावे मदनपुष्पाणि शलटूनि च कल्पयेत् इति फलविधानमुक्तम्", text: "etena sarvamālyagandhaprāvaraṇapaṭā vyākhyātāḥ evameva ca phalābhāve madanapuṣpāṇi śalaṭūni ca kalpayet iti phalavidhānamuktam" },
      { type: "verse", number: "19", sanskrit: "एवं च जीमूतादीनपि कल्पयेत् विशेषतस्तु ज्वरश्वासहिध्मादिषु जीमूतकम्", text: "evaṃ ca jīmūtādīnapi kalpayet viśeṣatastu jvaraśvāsahidhmādiṣu jīmūtakam" },
      { type: "verse", number: "20", sanskrit: "तत्र पुष्पेषु क्षीरम् फलेषु क्षीरपेयाम् लोमशेषु सन्तानिकाम् निर्लोमकेषु दधि दध्युत्तरं वा हरितपाण्डुषु क्षीरं दध्यम्लं वा तत्कषायसंसृष्टां पर्यागतानां जीर्णानां जीमूतकफलानां शुष्काणां चूर्णं पयसा वातपित्ते पिबेत्", text: "tatra puṣpeṣu kṣīram phaleṣu kṣīrapeyām lomaśeṣu santānikām nirlomakeṣu dadhi dadhyuttaraṃ vā haritapāṇḍuṣu kṣīraṃ dadhyamlaṃ vā tatkaṣāyasaṃsṛṣṭāṃ paryāgatānāṃ jīrṇānāṃ jīmūtakaphalānāṃ śuṣkāṇāṃ cūrṇaṃ payasā vātapitte pibet" },
      { type: "verse", number: "21", sanskrit: "द्वित्राणि वापोथ्यारग्वधादीनां नवानामन्यतमस्य पटोल्या वा निर्यूहेणासुतानि मथित्वा पित्तश्लेष्मजे ज्वरे जीमूतचूर्णं कल्कं वा शीताम्बुना पित्तजे तदेवोष्णेन वातकफजे कफजे वा", text: "dvitrāṇi vāpothyāragvadhādīnāṃ navānāmanyatamasya paṭolyā vā niryūheṇāsutāni mathitvā pittaśleṣmaje jvare jīmūtacūrṇaṃ kalkaṃ vā śītāmbunā pittaje tadevoṣṇena vātakaphaje kaphaje vā" },
      { type: "verse", number: "22", sanskrit: "जीवकर्षभकेक्षुशतावरीणामन्यतमस्य स्वरसेन वातपित्तजे अथवा पूर्ववत् सिद्धं घृतम्", text: "jīvakarṣabhakekṣuśatāvarīṇāmanyatamasya svarasena vātapittaje athavā pūrvavat siddhaṃ ghṛtam" },
      { type: "verse", number: "23", sanskrit: "इक्ष्वाकुस्तु विशेषेण कासश्वासज्वरच्छर्दिविषश्लेष्मरोगेषूपयोज्यः तस्यापुष्पफलस्य प्रवालैः शृतं क्षीरमुद्रिक्तपित्ते कफज्वरे", text: "ikṣvākustu viśeṣeṇa kāsaśvāsajvaracchardiviṣaśleṣmarogeṣūpayojyaḥ tasyāpuṣpaphalasya pravālaiḥ śṛtaṃ kṣīramudriktapitte kaphajvare" },
      { type: "verse", number: "24", sanskrit: "पुष्पादिषु च सुतरां जीमूतवत् प्रयोगाः इक्ष्वाकुफलस्वरसं वा त्रिगुणक्षीरसाधितमुरस्थिते कफे पीनसे स्वरसादे वा वमनार्थी पिबेत् जीर्णे वा समुद्वृतबीजे क्षीरं प्रक्षिपेत् तत्र जातं दधि श्लेष्मकासश्वासच्छर्दिषु", text: "puṣpādiṣu ca sutarāṃ jīmūtavat prayogāḥ ikṣvākuphalasvarasaṃ vā triguṇakṣīrasādhitamurasthite kaphe pīnase svarasāde vā vamanārthī pibet jīrṇe vā samudvṛtabīje kṣīraṃ prakṣipet tatra jātaṃ dadhi śleṣmakāsaśvāsacchardiṣu" },
      { type: "verse", number: "25", sanskrit: "इक्ष्वाकुबीजानि वा छागक्षीरभावितानि विषगुल्मोदरगरगण्डग्रन्थ्यर्बुदश्लीपदेषु इक्ष्वाकुफलमध्यं वा मस्तुना कुष्ठविषपाण्ड्वामयेषु तद्विपक्वं वा तक्रं समधुसैन्धवम् तदेव वा मध्यं सगुडपललं भक्षयेत्", text: "ikṣvākubījāni vā chāgakṣīrabhāvitāni viṣagulmodaragaragaṇḍagranthyarbudaślīpadeṣu ikṣvākuphalamadhyaṃ vā mastunā kuṣṭhaviṣapāṇḍvāmayeṣu tadvipakvaṃ vā takraṃ samadhusaindhavam tadeva vā madhyaṃ saguḍapalalaṃ bhakṣayet" },
      { type: "verse", number: "26", sanskrit: "इक्ष्वाकुफलतैलं वा पिबेत् तत्फलस्वरसभावितैर्वा सक्तुभिर्मन्थं श्लेष्मज्वरकासकण्ठरोगारोचकेषु इक्ष्वाकुकल्कं वा मांसरसेन वातकफगुल्मप्रसक्तज्वरेषु", text: "ikṣvākuphalatailaṃ vā pibet tatphalasvarasabhāvitairvā saktubhirmanthaṃ śleṣmajvarakāsakaṇṭharogārocakeṣu ikṣvākukalkaṃ vā māṃsarasena vātakaphagulmaprasaktajvareṣu" },
      { type: "verse", number: "27", sanskrit: "बिल्वमूलद्विप्रस्थक्वाथेन वा तुम्बीबीजानि क्वाथयेत् ततस्तस्मिन् त्रिभागेन घृतम् घृतसमानि च पिष्ट्वा तुम्बीबीजानि तदर्धांशानि च प्रत्येकं जीमूतमहाजालिनीवत्सककृतवेधनानि क्वाथतुल्यमावपेत् त्रिकटुकम् पुनरधिश्रित्य लेहं साधयेत्तमवलिह्य प्रमथ्यामनुपिबेत्", text: "bilvamūladviprasthakvāthena vā tumbībījāni kvāthayet tatastasmin tribhāgena ghṛtam ghṛtasamāni ca piṣṭvā tumbībījāni tadardhāṃśāni ca pratyekaṃ jīmūtamahājālinīvatsakakṛtavedhanāni kvāthatulyamāvapet trikaṭukam punaradhiśritya lehaṃ sādhayettamavalihya pramathyāmanupibet" },
      { type: "verse", number: "28", sanskrit: "अयमेव च कल्पः काश्मर्यादिषु चतुर्षु महापञ्चमूलाङ्गेषु पृथक् पृथगुक्तो वेदितव्यः", text: "ayameva ca kalpaḥ kāśmaryādiṣu caturṣu mahāpañcamūlāṅgeṣu pṛthak pṛthagukto veditavyaḥ" },
      { type: "verse", number: "29", sanskrit: "धामार्गवो विशेषेण गरगुल्मोदरकासकफसञ्चयोत्थरोगेषु स्थिरेषु गुरुषु च श्लेष्माशयस्थे वातश्लेष्मणि च कण्ठाश्रये प्रकल्प्यः जीवनीयान्यतमचूर्णसंयुक्तान् समधुशर्करांस्तत्कषायैर्लेहान् पित्तोपसर्जने श्लेष्मणि विदध्यात्", text: "dhāmārgavo viśeṣeṇa garagulmodarakāsakaphasañcayottharogeṣu sthireṣu guruṣu ca śleṣmāśayasthe vātaśleṣmaṇi ca kaṇṭhāśraye prakalpyaḥ jīvanīyānyatamacūrṇasaṃyuktān samadhuśarkarāṃstatkaṣāyairlehān pittopasarjane śleṣmaṇi vidadhyāt" },
      { type: "verse", number: "30", sanskrit: "सुमनःसौमनस्यायनीहरिद्राचोरकहैमवतीमहासहाक्षुद्रसहावृश्चीवबिम्बीपुनर्नवकासमर्दान्यतमकषायेण वा धामार्गवफलमेकं द्वे वा मनोविकारेषु", text: "sumanaḥsaumanasyāyanīharidrācorakahaimavatīmahāsahākṣudrasahāvṛścīvabimbīpunarnavakāsamardānyatamakaṣāyeṇa vā dhāmārgavaphalamekaṃ dve vā manovikāreṣu" },
      { type: "verse", number: "31", sanskrit: "कृतवेधनमत्यर्थकटुतीक्ष्णोष्णं सुतरां गरोदरगुल्मप्लीहपाण्डुरोगश्वयथुषु कल्पयेत्", text: "kṛtavedhanamatyarthakaṭutīkṣṇoṣṇaṃ sutarāṃ garodaragulmaplīhapāṇḍurogaśvayathuṣu kalpayet" },
      { type: "verse", number: "32", sanskrit: "कुटजफलं पुनः सुकुमारेषूल्बणास्रपित्तकफेषु वातशोणितविसर्पज्वरकुष्ठादिषु च योजयेत् कुटजफलचूर्णान्यर्कक्षीरेण सप्ताहं भावयित्वा जीवककषायेण पिबेत् फलजीमूतकेक्ष्वाकुजीवन्तीमूलान्यतमकषायेण वा सर्षपमधूकलवणान्यतमाम्भसा वा कुटजफलचूर्णं कृसरया वा वमनाय कल्पयेदिति भवति चात्र", text: "kuṭajaphalaṃ punaḥ sukumāreṣūlbaṇāsrapittakapheṣu vātaśoṇitavisarpajvarakuṣṭhādiṣu ca yojayet kuṭajaphalacūrṇānyarkakṣīreṇa saptāhaṃ bhāvayitvā jīvakakaṣāyeṇa pibet phalajīmūtakekṣvākujīvantīmūlānyatamakaṣāyeṇa vā sarṣapamadhūkalavaṇānyatamāmbhasā vā kuṭajaphalacūrṇaṃ kṛsarayā vā vamanāya kalpayediti bhavati cātra" },
      { type: "verse", number: "33", sanskrit: "वमनानां दिगित्येषा सुतरामुपयोगिनाम् बीजेनानेन मतिमानन्यानपि च कल्पयेदिति", text: "vamanānāṃ digityeṣā sutarāmupayoginām bījenānena matimānanyānapi ca kalpayediti" },
    ],
  },
  {
    sthana: "Калпасиддхистхана",
    number: 2,
    lang: "sa",
    content: [
      { type: "heading", heading: "Тривридха кальпа — слабительные препараты" },
      { type: "text", text: "Глава 2 Калпасиддхистханы посвящена слабительные препараты. Вагбхата систематизирует приготовление и применение очищающих средств." },
      { type: "verse", number: "1", sanskrit: "अथातो विरेचनकल्पं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto virecanakalpaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "विरेचनद्रव्याणां मूलेषु त्रिवृत् त्वक्षु तिल्वकः क्षीरेषु स्नुही फलेषु हरीतकी प्रधानानि त्रिवृतायाः खलु द्विविधं मूलमरुणं श्यावं च तत्रारुणं कषायमधुरं विपाके कटुकं रूक्षं श्लेष्मपित्तहरं कल्पनांविशेषात् पुनः सर्वव्याधिप्रशमनम् सुखविरेचनत्वात् शिशुस्थविरसुकुमारमृदुकोष्ठेषु प्रशस्तं त्रिवृच्छब्दवाच्यं च", text: "virecanadravyāṇāṃ mūleṣu trivṛt tvakṣu tilvakaḥ kṣīreṣu snuhī phaleṣu harītakī pradhānāni trivṛtāyāḥ khalu dvividhaṃ mūlamaruṇaṃ śyāvaṃ ca tatrāruṇaṃ kaṣāyamadhuraṃ vipāke kaṭukaṃ rūkṣaṃ śleṣmapittaharaṃ kalpanāṃviśeṣāt punaḥ sarvavyādhipraśamanam sukhavirecanatvāt śiśusthavirasukumāramṛdukoṣṭheṣu praśastaṃ trivṛcchabdavācyaṃ ca" },
      { type: "verse", number: "3", sanskrit: "इतरदपि तस्मात् गुणैः किञ्चिदूनं तीक्ष्णं कण्ठहृदयकर्षणं मूर्छासम्मोहकृदाशु दोषहरत्वात् बहुदोषक्लेशक्षमक्रूरकोष्ठेषु प्रशस्तं श्यामाशब्दवाच्यं च", text: "itaradapi tasmāt guṇaiḥ kiñcidūnaṃ tīkṣṇaṃ kaṇṭhahṛdayakarṣaṇaṃ mūrchāsammohakṛdāśu doṣaharatvāt bahudoṣakleśakṣamakrūrakoṣṭheṣu praśastaṃ śyāmāśabdavācyaṃ ca" },
      { type: "verse", number: "4", sanskrit: "अथ तयोर्मूलमतिर्यग्विसृतं गम्भीरानुगतं श्लक्ष्णमाहरेत् ततस्त्वचं शोषयित्वा सम्यक् सुगुप्तं स्थापयेत्", text: "atha tayormūlamatiryagvisṛtaṃ gambhīrānugataṃ ślakṣṇamāharet tatastvacaṃ śoṣayitvā samyak suguptaṃ sthāpayet" },
      { type: "verse", number: "5", sanskrit: "तच्चूर्णं शुण्ठीसैन्धवयुक्तमम्लैर्मांसरसेन वा पिबेद्वातामयेषु क्षीरक्षौद्रद्राक्षेक्षुकाश्मर्यस्वरससर्पिःस्वादुद्रव्यक्वाथैः सशर्करं पित्तोत्थेषु मूत्रक्सौद्रद्राक्षारिष्टपीलुरसत्रिफलापञ्चकोलक्वाथैर्व्योषचूर्णानुविद्धं कफजेषु", text: "taccūrṇaṃ śuṇṭhīsaindhavayuktamamlairmāṃsarasena vā pibedvātāmayeṣu kṣīrakṣaudradrākṣekṣukāśmaryasvarasasarpiḥsvādudravyakvāthaiḥ saśarkaraṃ pittottheṣu mūtraksaudradrākṣāriṣṭapīlurasatriphalāpañcakolakvāthairvyoṣacūrṇānuviddhaṃ kaphajeṣu" },
      { type: "verse", number: "6", sanskrit: "एभिरेव च द्रव्यैर्यथास्वं घृतशर्कराद्राक्षेक्षुरसतुगाक्षीरीमधुराणि मातुलुङ्गदाडिमामलककोलकरमर्दकपित्थरसतक्राम्लानि सैन्धवलवणानि व्योषतीक्ष्णानि विविधवेशवारपरिपूरितानि सहकाररसत्रिजातनागकेसरकर्पूरसुरभीणि लेहगुटिकामोदकभक्ष्यभोज्यान्युपकल्पयेदिति भवति चात्र", text: "ebhireva ca dravyairyathāsvaṃ ghṛtaśarkarādrākṣekṣurasatugākṣīrīmadhurāṇi mātuluṅgadāḍimāmalakakolakaramardakapittharasatakrāmlāni saindhavalavaṇāni vyoṣatīkṣṇāni vividhaveśavāraparipūritāni sahakārarasatrijātanāgakesarakarpūrasurabhīṇi lehaguṭikāmodakabhakṣyabhojyānyupakalpayediti bhavati cātra" },
      { type: "verse", number: "7", sanskrit: "त्रिवृत्कल्ककषायेण साधितः ससितो हिमः मधुत्रिजातसंयुक्तो लेहो हृद्यं विरेचनम्", text: "trivṛtkalkakaṣāyeṇa sādhitaḥ sasito himaḥ madhutrijātasaṃyukto leho hṛdyaṃ virecanam" },
      { type: "verse", number: "8", sanskrit: "अजगन्धा तुगाक्सीरी विदारी शर्करा त्रिवृत् चूर्णितं मधुसर्पिर्भ्यां लीढ्वा साधु विरिच्यते सन्निपातज्वरस्तम्भपिपासादाहपीडितः", text: "ajagandhā tugāksīrī vidārī śarkarā trivṛt cūrṇitaṃ madhusarpirbhyāṃ līḍhvā sādhu viricyate sannipātajvarastambhapipāsādāhapīḍitaḥ" },
      { type: "verse", number: "9", sanskrit: "लिम्पेदन्तस्त्रिवृतया द्विधाकृत्वेक्षुगण्डिकाम् एकीकृत्य च तत्स्विन्नं पुटपाकेन भक्षयेत्", text: "limpedantastrivṛtayā dvidhākṛtvekṣugaṇḍikām ekīkṛtya ca tatsvinnaṃ puṭapākena bhakṣayet" },
      { type: "verse", number: "10", sanskrit: "त्वगेलाभ्यां समा नीली तैस्त्रिवृत्तश्च शर्करा चूर्णं फलरसक्षौद्रसक्तुभिस्तर्पणं पिबेत्", text: "tvagelābhyāṃ samā nīlī taistrivṛttaśca śarkarā cūrṇaṃ phalarasakṣaudrasaktubhistarpaṇaṃ pibet" },
      { type: "verse", number: "11", sanskrit: "वातपित्तकफोत्थेषु रोगेष्वल्पानलेषु च नरेषु सुकुमारेषु निरपायं विरेचनम्", text: "vātapittakaphottheṣu rogeṣvalpānaleṣu ca nareṣu sukumāreṣu nirapāyaṃ virecanam" },
      { type: "verse", number: "12", sanskrit: "विडङ्गतण्डुलवरायावशूककणास्त्रिवृत् सर्वतो ऽर्धेन तल्लीढं मध्वाज्येन गुडेन वा", text: "viḍaṅgataṇḍulavarāyāvaśūkakaṇāstrivṛt sarvato 'rdhena tallīḍhaṃ madhvājyena guḍena vā" },
      { type: "verse", number: "13", sanskrit: "गुल्मं प्लीहोदरं कासं हलीमकमरोचकम् कफवातकृतांश्चान्यान् परिमार्ष्टिगदान् बहून्", text: "gulmaṃ plīhodaraṃ kāsaṃ halīmakamarocakam kaphavātakṛtāṃścānyān parimārṣṭigadān bahūn" },
      { type: "verse", number: "14", sanskrit: "विडङ्गपिप्पलीमूलत्रिफलाधान्यचित्रकान् मरिचेन्द्रयवाजाजीपिप्पलीहस्तिपिप्पलीः", text: "viḍaṅgapippalīmūlatriphalādhānyacitrakān maricendrayavājājīpippalīhastipippalīḥ" },
      { type: "verse", number: "15", sanskrit: "दीप्यकं पञ्चलवणं चूर्णितं कार्षिकं पृथक् तिलतैलत्रिवृच्चूर्णभागौ चाष्टपलोन्मितौ", text: "dīpyakaṃ pañcalavaṇaṃ cūrṇitaṃ kārṣikaṃ pṛthak tilatailatrivṛccūrṇabhāgau cāṣṭapalonmitau" },
      { type: "verse", number: "16", sanskrit: "धात्रीफलरसप्रस्थांस्त्रीन् गुडार्धतुलान्वितान् पक्त्वा मृद्वग्निना खादेत्ततो मात्रामयन्त्रणः", text: "dhātrīphalarasaprasthāṃstrīn guḍārdhatulānvitān paktvā mṛdvagninā khādettato mātrāmayantraṇaḥ" },
      { type: "verse", number: "17", sanskrit: "कुष्ठार्शःकामलागुल्ममेहोदरभगन्दरान् ग्रहणीपाण्डुरोगांश्च हन्ति पुंसवनश्च सः", text: "kuṣṭhārśaḥkāmalāgulmamehodarabhagandarān grahaṇīpāṇḍurogāṃśca hanti puṃsavanaśca saḥ" },
      { type: "verse", number: "18", sanskrit: "गुडः कल्याणको नाम सर्वर्तुषु च यौगिकः व्योषत्रिजातकाम्भोदकृमिघ्नामलकैस्त्रिवृत्", text: "guḍaḥ kalyāṇako nāma sarvartuṣu ca yaugikaḥ vyoṣatrijātakāmbhodakṛmighnāmalakaistrivṛt" },
      { type: "verse", number: "19", sanskrit: "सर्वैः समा समसिता क्षौद्रेण गुटिकाः कृताः मूत्रकृच्छ्रज्वरच्छर्दिकासशोषभ्रमक्षये तापे पाण्ड्वामये ऽल्पेग्नौ शस्ताः सर्वविषेषु च", text: "sarvaiḥ samā samasitā kṣaudreṇa guṭikāḥ kṛtāḥ mūtrakṛcchrajvaracchardikāsaśoṣabhramakṣaye tāpe pāṇḍvāmaye 'lpegnau śastāḥ sarvaviṣeṣu ca" },
      { type: "verse", number: "20", sanskrit: "त्रिवृता कौटजं बीजं पिप्पली विश्वभेषजम् क्षौद्रद्राक्षारसोपेतं वर्षाकाले विरेचनम्", text: "trivṛtā kauṭajaṃ bījaṃ pippalī viśvabheṣajam kṣaudradrākṣārasopetaṃ varṣākāle virecanam" },
      { type: "verse", number: "21", sanskrit: "त्रिवृद्दुरालभामुस्ताशर्करोदीच्यचन्दनम् द्राक्षाम्बुना सयष्ट्याह्वसातलं जलदात्यये", text: "trivṛddurālabhāmustāśarkarodīcyacandanam drākṣāmbunā sayaṣṭyāhvasātalaṃ jaladātyaye" },
      { type: "verse", number: "22", sanskrit: "त्रिवृतां चित्रकं पाठामजाजीं सरलं वचाम् स्वर्णक्षीरीं च हेमन्ते चूर्णमुष्णाम्बुना पिबेत्", text: "trivṛtāṃ citrakaṃ pāṭhāmajājīṃ saralaṃ vacām svarṇakṣīrīṃ ca hemante cūrṇamuṣṇāmbunā pibet" },
      { type: "verse", number: "23", sanskrit: "त्रिवृता शर्करातुल्या ग्रीष्मकाले विरेचनम्", text: "trivṛtā śarkarātulyā grīṣmakāle virecanam" },
      { type: "verse", number: "24", sanskrit: "त्रिवृत्त्रायन्तिहपुषासातलाकटुरोहिणीः स्वर्णक्षीरीं च संचूर्ण्य गोमूत्रे भावयेत्त्र्यहम् एष सर्वर्तुको योगः स्निग्धानां मलदोषहृत्", text: "trivṛttrāyantihapuṣāsātalākaṭurohiṇīḥ svarṇakṣīrīṃ ca saṃcūrṇya gomūtre bhāvayettryaham eṣa sarvartuko yogaḥ snigdhānāṃ maladoṣahṛt" },
      { type: "verse", number: "25", sanskrit: "श्यामात्रिवृद्दुरालम्भाहास्तिपिप्पलिवत्सकम् नीलिनीकटुकामुस्ताश्रेष्ठायुक्तं सुचूर्णितम् रसाज्योष्णाम्बुभिः शस्तं रूक्षाणामपि सर्वदा", text: "śyāmātrivṛddurālambhāhāstipippalivatsakam nīlinīkaṭukāmustāśreṣṭhāyuktaṃ sucūrṇitam rasājyoṣṇāmbubhiḥ śastaṃ rūkṣāṇāmapi sarvadā" },
      { type: "verse", number: "26", sanskrit: "त्र्यूषणं त्रिफला हिङ्गु कार्षिकं त्रिवृतापलम् सौवर्चलार्धकर्षं च पलार्धं चाम्लवेतसात्", text: "tryūṣaṇaṃ triphalā hiṅgu kārṣikaṃ trivṛtāpalam sauvarcalārdhakarṣaṃ ca palārdhaṃ cāmlavetasāt" },
      { type: "verse", number: "27", sanskrit: "तच्चूर्णं शर्करातुल्यं मण्डेनाम्लेन वा पिबेत् गुल्मपार्श्वार्तिनुत् सिद्धं जीर्णे चास्मिन्रसौदनम्", text: "taccūrṇaṃ śarkarātulyaṃ maṇḍenāmlena vā pibet gulmapārśvārtinut siddhaṃ jīrṇe cāsminrasaudanam" },
      { type: "verse", number: "28", sanskrit: "त्रिवृतात्रिफलादन्तीसातलाव्योषसैन्धवैः प्रकल्प्य चूर्णं सप्ताहं भाव्यमामलकाद्रसे तद्योज्यं तर्पणे यूषे पिशिते रागयुक्तिषु", text: "trivṛtātriphalādantīsātalāvyoṣasaindhavaiḥ prakalpya cūrṇaṃ saptāhaṃ bhāvyamāmalakādrase tadyojyaṃ tarpaṇe yūṣe piśite rāgayuktiṣu" },
      { type: "verse", number: "29", sanskrit: "तुल्याम्लं त्रिवृताकल्कसिद्धं गुल्महरं घृतम् श्यामात्रिवृत्कषायेण सिद्धं सर्पिः पयो ऽपि वा", text: "tulyāmlaṃ trivṛtākalkasiddhaṃ gulmaharaṃ ghṛtam śyāmātrivṛtkaṣāyeṇa siddhaṃ sarpiḥ payo 'pi vā" },
      { type: "verse", number: "30", sanskrit: "त्रिवृन्मुष्टींस्तु सनखानष्टौ द्रोणे ऽम्भसः पचेत् पादशेषं कषायं तं पूतं गुडतुलायुतम्", text: "trivṛnmuṣṭīṃstu sanakhānaṣṭau droṇe 'mbhasaḥ pacet pādaśeṣaṃ kaṣāyaṃ taṃ pūtaṃ guḍatulāyutam" },
      { type: "verse", number: "31", sanskrit: "स्निग्धे स्थाप्यं घटे क्षौद्रपिप्पलीफलचित्रकैः लिप्ते मासे गते पीतं पाण्डुश्वयथुगुल्मजित्", text: "snigdhe sthāpyaṃ ghaṭe kṣaudrapippalīphalacitrakaiḥ lipte māse gate pītaṃ pāṇḍuśvayathugulmajit" },
      { type: "verse", number: "32", sanskrit: "सुरा वा त्रिवृतापादाकण्वा तत्क्वाथसंयुता यवैः श्यामात्रिवृत्क्वाथस्विन्नैः कुल्माषमम्भसा आसुतं षडहं पल्ले जातं सौवीरकं पिबेत्", text: "surā vā trivṛtāpādākaṇvā tatkvāthasaṃyutā yavaiḥ śyāmātrivṛtkvāthasvinnaiḥ kulmāṣamambhasā āsutaṃ ṣaḍahaṃ palle jātaṃ sauvīrakaṃ pibet" },
      { type: "verse", number: "33", sanskrit: "भृष्टान्वा सतुषान्शुष्कान्यवांस्तच्चूर्णसंयुतान् आसुतानम्भसा तद्वत् पिबेज्जातं तुषोदकम्", text: "bhṛṣṭānvā satuṣānśuṣkānyavāṃstaccūrṇasaṃyutān āsutānambhasā tadvat pibejjātaṃ tuṣodakam" },
      { type: "verse", number: "34", sanskrit: "ज्वरहृद्रोगवातासृगुदावर्तादिरोगिषु राजवृक्षो ऽधिकं पथ्यो मृदुर्मधुरशीतलः", text: "jvarahṛdrogavātāsṛgudāvartādirogiṣu rājavṛkṣo 'dhikaṃ pathyo mṛdurmadhuraśītalaḥ" },
      { type: "verse", number: "35", sanskrit: "बाले वृद्धे क्षते क्षीणे सुकुमारे च मानवे योज्यो मृद्वनपायित्वाद्विशेषाच्चतुरङ्गुलः", text: "bāle vṛddhe kṣate kṣīṇe sukumāre ca mānave yojyo mṛdvanapāyitvādviśeṣāccaturaṅgulaḥ" },
      { type: "verse", number: "36", sanskrit: "फलकाले परिणतं फलं तस्य समाहरेत् तेषां गुणवतां भारं सिकतासु विनिक्षिपेत्", text: "phalakāle pariṇataṃ phalaṃ tasya samāharet teṣāṃ guṇavatāṃ bhāraṃ sikatāsu vinikṣipet" },
      { type: "verse", number: "37", sanskrit: "सप्तरात्रात्समुद्धृत्य शोषयेदातपे ततः ततोमज्जानमुद्धृत्य शुचौ पात्रे निधापयेत्", text: "saptarātrātsamuddhṛtya śoṣayedātape tataḥ tatomajjānamuddhṛtya śucau pātre nidhāpayet" },
      { type: "verse", number: "38", sanskrit: "द्राक्षारसेन तं दद्याद्दाहोदावर्तपीडिते चतुर्वर्षे सुखं बाले यावद्द्वादशवार्षिके", text: "drākṣārasena taṃ dadyāddāhodāvartapīḍite caturvarṣe sukhaṃ bāle yāvaddvādaśavārṣike" },
      { type: "verse", number: "39", sanskrit: "चतुरङ्गुलमज्ञो वा कषायं पाययेद्धिमम् दधिमण्डसुरामण्डधात्रीफलरसैः पृथक् सौवीरकेण वा युक्तं कल्केन त्रैवृतेन वा", text: "caturaṅgulamajño vā kaṣāyaṃ pāyayeddhimam dadhimaṇḍasurāmaṇḍadhātrīphalarasaiḥ pṛthak sauvīrakeṇa vā yuktaṃ kalkena traivṛtena vā" },
      { type: "verse", number: "40", sanskrit: "चतुरङ्गुलसिद्धाद्वा क्षीराद्यदुदियात् घृतम् मज्जकल्केन धात्रीणां रसे तत्साधितं पिबेत्", text: "caturaṅgulasiddhādvā kṣīrādyadudiyāt ghṛtam majjakalkena dhātrīṇāṃ rase tatsādhitaṃ pibet" },
      { type: "verse", number: "41", sanskrit: "तदेव दशमूलस्य कुलत्थानां यवस्य च कषाये साधितं सापःकल्कैःश्यामादिभिः पिबेत्", text: "tadeva daśamūlasya kulatthānāṃ yavasya ca kaṣāye sādhitaṃ sāpaḥkalkaiḥśyāmādibhiḥ pibet" },
      { type: "verse", number: "42", sanskrit: "दन्तीकषाये तन्मज्ज्ञो गुडं जीर्णं च निक्षिपेत् तमरिष्टं स्थितं मासं पाययेत् पक्षमेव वा", text: "dantīkaṣāye tanmajjño guḍaṃ jīrṇaṃ ca nikṣipet tamariṣṭaṃ sthitaṃ māsaṃ pāyayet pakṣameva vā" },
      { type: "verse", number: "43", sanskrit: "त्वचं तिल्वकमूलस्य त्यक्ताभ्यन्तरवल्कलम् विशोष्य चूर्णयित्वा च द्वौ भागौ गालयेत्ततः", text: "tvacaṃ tilvakamūlasya tyaktābhyantaravalkalam viśoṣya cūrṇayitvā ca dvau bhāgau gālayettataḥ" },
      { type: "verse", number: "44", sanskrit: "लोध्रस्यैव कषायेण तृतीयं तेन भावयेत् कषाये दशमूलस्य तं भागं भावितं पुनः", text: "lodhrasyaiva kaṣāyeṇa tṛtīyaṃ tena bhāvayet kaṣāye daśamūlasya taṃ bhāgaṃ bhāvitaṃ punaḥ" },
      { type: "verse", number: "45", sanskrit: "शुष्कचूर्णं पुनः कृत्वा ततः पाणितलं पिबेत् मस्तुमूत्रसुरामण्डकोलधात्रीफलाम्बुभिः", text: "śuṣkacūrṇaṃ punaḥ kṛtvā tataḥ pāṇitalaṃ pibet mastumūtrasurāmaṇḍakoladhātrīphalāmbubhiḥ" },
      { type: "verse", number: "46", sanskrit: "मेषशृङ्ग्यभयाकृष्णाचित्रकैः क्वथिते जले मरुजाः सुनुयात्तच्चजातं सौवीरकं यदा भवेदञ्जलिनातस्य लोध्रकल्कं पिबेत्तदा", text: "meṣaśṛṅgyabhayākṛṣṇācitrakaiḥ kvathite jale marujāḥ sunuyāttaccajātaṃ sauvīrakaṃ yadā bhavedañjalinātasya lodhrakalkaṃ pibettadā" },
      { type: "verse", number: "47", sanskrit: "सुरां लोध्रकषायेण जातां पक्षस्थितां पिबेत् तिल्वकस्य कषायेण कल्केन च सशर्करः सघृतः साधितो लेहः स च श्रेष्ठं विरेचनम्", text: "surāṃ lodhrakaṣāyeṇa jātāṃ pakṣasthitāṃ pibet tilvakasya kaṣāyeṇa kalkena ca saśarkaraḥ saghṛtaḥ sādhito lehaḥ sa ca śreṣṭhaṃ virecanam" },
      { type: "verse", number: "48", sanskrit: "सुधा भिनत्ति दोषाणां महान्तमपि सञ्चयम् आश्वेव कष्टविभ्रंशा नैव तां कल्पयेदतः", text: "sudhā bhinatti doṣāṇāṃ mahāntamapi sañcayam āśveva kaṣṭavibhraṃśā naiva tāṃ kalpayedataḥ" },
      { type: "verse", number: "49", sanskrit: "मृदुकोष्ठे ऽबले बाले स्थविरे दीर्घरोगिणि कल्प्या गुल्मोदरगरत्वग्रोगमधुमेहिषु पाण्डौ दूषीविषे शोफे दोषविभ्रान्तचेतसि", text: "mṛdukoṣṭhe 'bale bāle sthavire dīrgharogiṇi kalpyā gulmodaragaratvagrogamadhumehiṣu pāṇḍau dūṣīviṣe śophe doṣavibhrāntacetasi" },
      { type: "verse", number: "50", sanskrit: "सा श्रेष्ठा कण्टकैस्तीक्ष्णैर्बहुभिश्च समाचिता द्विवर्षां वा त्रिवर्षां वा शिशिरान्ते विशेषतः", text: "sā śreṣṭhā kaṇṭakaistīkṣṇairbahubhiśca samācitā dvivarṣāṃ vā trivarṣāṃ vā śiśirānte viśeṣataḥ" },
      { type: "verse", number: "51", sanskrit: "तां पाटयित्वा शस्त्रेण क्षीरमुद्धारयेत्ततः बिल्वादीनां बृहत्योर्वा क्वाथेन सममेकशः", text: "tāṃ pāṭayitvā śastreṇa kṣīramuddhārayettataḥ bilvādīnāṃ bṛhatyorvā kvāthena samamekaśaḥ" },
      { type: "verse", number: "52", sanskrit: "मिश्रयित्वा सुधाक्षीरं ततो ऽङ्गारेषु शोषयेत् पिबेत् कृत्वा तु गुटिकां मस्तुमूत्रसुरादिभिः", text: "miśrayitvā sudhākṣīraṃ tato 'ṅgāreṣu śoṣayet pibet kṛtvā tu guṭikāṃ mastumūtrasurādibhiḥ" },
      { type: "verse", number: "53", sanskrit: "त्रिवृतादीन्नव वरां स्वर्णक्षीरीं ससातलाम् सप्ताहं स्नुक्पयःपीतान्रसेनाज्येन वा पिबेत् तद्वद्व्योषोत्तमाकुम्भनिकुम्भाग्नीन् गुडाम्बुना", text: "trivṛtādīnnava varāṃ svarṇakṣīrīṃ sasātalām saptāhaṃ snukpayaḥpītānrasenājyena vā pibet tadvadvyoṣottamākumbhanikumbhāgnīn guḍāmbunā" },
      { type: "verse", number: "54", sanskrit: "अद्यात्च्छ्यामात्रिवृत्क्वाथं स्नुक्क्षीरघृतफाणितैः कासारिरसयूषाद्यैर्युक्तं वा स्नुक्पयः पिबेत्", text: "adyātcchyāmātrivṛtkvāthaṃ snukkṣīraghṛtaphāṇitaiḥ kāsārirasayūṣādyairyuktaṃ vā snukpayaḥ pibet" },
      { type: "verse", number: "55", sanskrit: "निकुम्भकुम्भशम्याकशङ्खिनीसप्तलारजः रात्रौ मूत्रे दिवा घर्मे सप्ताहं स्थापयेदिति", text: "nikumbhakumbhaśamyākaśaṅkhinīsaptalārajaḥ rātrau mūtre divā gharme saptāhaṃ sthāpayediti" },
      { type: "verse", number: "56", sanskrit: "स्नुक्क्षीरे ऽपि ततस्तेन माल्यं वासो ऽवचूर्णितम् आजिघ्नन् प्रावृणानश्च मृदुकोष्ठो विरिच्यते", text: "snukkṣīre 'pi tatastena mālyaṃ vāso 'vacūrṇitam ājighnan prāvṛṇānaśca mṛdukoṣṭho viricyate" },
      { type: "verse", number: "57", sanskrit: "नातिशुष्कं फलं ग्राह्यं शङ्खिन्या निस्तुषीकृतम् सप्तलायास्तथा मूलं ते तु तीक्ष्णविकाषिणी श्लेष्मामयोदरगरश्वयथ्वादिषु कल्पयेत्", text: "nātiśuṣkaṃ phalaṃ grāhyaṃ śaṅkhinyā nistuṣīkṛtam saptalāyāstathā mūlaṃ te tu tīkṣṇavikāṣiṇī śleṣmāmayodaragaraśvayathvādiṣu kalpayet" },
      { type: "verse", number: "58", sanskrit: "अक्षमात्रं तयोः पिण्डं मदिरालवणान्वितम् हृद्रोगे वातकफजे तद्वद्गुल्मे ऽपि योजयेत्", text: "akṣamātraṃ tayoḥ piṇḍaṃ madirālavaṇānvitam hṛdroge vātakaphaje tadvadgulme 'pi yojayet" },
      { type: "verse", number: "59", sanskrit: "शङ्खिनीचूर्णभागौ द्वौ तिलकल्कस्य चापरः हरीतकीकषायेण ततैलं पीडितं पिबेत् अतसीसर्षपैरण्डकरञ्जेष्वप्ययं विधिः", text: "śaṅkhinīcūrṇabhāgau dvau tilakalkasya cāparaḥ harītakīkaṣāyeṇa tatailaṃ pīḍitaṃ pibet atasīsarṣapairaṇḍakarañjeṣvapyayaṃ vidhiḥ" },
      { type: "verse", number: "60", sanskrit: "दन्तिदन्तस्थिरस्थूलं मूलं दन्तीद्रवन्तिजम् आताम्रश्यावतीक्ष्णोष्णमाशुकारि विकाषि च", text: "dantidantasthirasthūlaṃ mūlaṃ dantīdravantijam ātāmraśyāvatīkṣṇoṣṇamāśukāri vikāṣi ca" },
      { type: "verse", number: "61", sanskrit: "गुरुप्रकोपिवातस्य पीतश्लेष्मविलायनम् तत्क्षौद्रपिप्पलीलिप्तं स्वेदयेन्मृत्कुशान्तरे शोषयेच्चातपे ऽग्न्यर्कौ हतो ह्यस्य विकाषिताम्", text: "guruprakopivātasya pītaśleṣmavilāyanam tatkṣaudrapippalīliptaṃ svedayenmṛtkuśāntare śoṣayeccātape 'gnyarkau hato hyasya vikāṣitām" },
      { type: "verse", number: "62", sanskrit: "तत् पिबेन्मस्तुमदिरातक्रपीलुरसासवैः अभिष्यण्णतनुर्गुल्मी प्रमेही जठरी गरी गोमृगाजरसैः पाण्डुः कृमिकोष्ठी भगन्दरी", text: "tat pibenmastumadirātakrapīlurasāsavaiḥ abhiṣyaṇṇatanurgulmī pramehī jaṭharī garī gomṛgājarasaiḥ pāṇḍuḥ kṛmikoṣṭhī bhagandarī" },
      { type: "verse", number: "63", sanskrit: "सिद्धं तत् क्वाथकल्काभ्यां दशमूलरसेन च विसर्पाविद्रध्यलजीकक्ष्यादाहान् जयेत् घृतम्", text: "siddhaṃ tat kvāthakalkābhyāṃ daśamūlarasena ca visarpāvidradhyalajīkakṣyādāhān jayet ghṛtam" },
      { type: "verse", number: "64", sanskrit: "तैलं तु गुल्ममेहार्शोविबन्धकफमारुतान् महास्नेहः शकृच्छुक्रवातसङ्गानिलव्यथाः", text: "tailaṃ tu gulmamehārśovibandhakaphamārutān mahāsnehaḥ śakṛcchukravātasaṅgānilavyathāḥ" },
      { type: "verse", number: "65", sanskrit: "दन्त्या रसे ऽजशृङ्ग्याश्च गुडक्षौद्रघृतान्वितः लेहः सिद्धो विरेकार्थे दाहसन्तापमेहनुत् वाततर्षे ज्वरे पैत्ते स्यात्स एवाजगन्धया", text: "dantyā rase 'jaśṛṅgyāśca guḍakṣaudraghṛtānvitaḥ lehaḥ siddho virekārthe dāhasantāpamehanut vātatarṣe jvare paitte syātsa evājagandhayā" },
      { type: "verse", number: "66", sanskrit: "दन्तीद्रवन्त्योर्मूलानि पचेद्धात्रीरसे ततः त्रीनंशान् फाणितात् द्वौ च भृष्टस्तैले घृते ऽथवा", text: "dantīdravantyormūlāni paceddhātrīrase tataḥ trīnaṃśān phāṇitāt dvau ca bhṛṣṭastaile ghṛte 'thavā" },
      { type: "verse", number: "67", sanskrit: "श्यामादिकल्कयुक्तो ऽयं लेहः सिद्धं विरेचनम् पथ्याक्षदशमूलानां तद्वल्लेहाः पृथग्रसैः", text: "śyāmādikalkayukto 'yaṃ lehaḥ siddhaṃ virecanam pathyākṣadaśamūlānāṃ tadvallehāḥ pṛthagrasaiḥ" },
      { type: "verse", number: "68", sanskrit: "तयोर्बिडसमं चूर्णं तद्रसेनैव भावितम् विबद्धविशि वातोत्थे गुल्मे चाम्लयुतं हितम् मुद्र्गादिसिद्धैस्तन्मूलैर्यूषादींश्च प्रकल्पयेत्", text: "tayorbiḍasamaṃ cūrṇaṃ tadrasenaiva bhāvitam vibaddhaviśi vātotthe gulme cāmlayutaṃ hitam mudrgādisiddhaistanmūlairyūṣādīṃśca prakalpayet" },
      { type: "verse", number: "69", sanskrit: "दन्तीद्रवन्तीमरिचस्वर्णक्षीरीयवासकम् सशुण्ठ्यग्निकपृथ्वीकं चूर्णितं सप्त वासरान्", text: "dantīdravantīmaricasvarṇakṣīrīyavāsakam saśuṇṭhyagnikapṛthvīkaṃ cūrṇitaṃ sapta vāsarān" },
      { type: "verse", number: "70", sanskrit: "मूत्रभावितमाज्येन विबेज्जीर्णे च तर्पणम् सर्वदा सर्वरोगेषु बाले वृद्धे च तद्धितम्", text: "mūtrabhāvitamājyena vibejjīrṇe ca tarpaṇam sarvadā sarvarogeṣu bāle vṛddhe ca taddhitam" },
      { type: "verse", number: "71", sanskrit: "दुर्भुक्ताजीर्णपांश्वार्तिर्गुल्मप्लीहोदरेषु च गण्डमालासु वाते च पाण्डुरोगे च शस्यते", text: "durbhuktājīrṇapāṃśvārtirgulmaplīhodareṣu ca gaṇḍamālāsu vāte ca pāṇḍuroge ca śasyate" },
      { type: "verse", number: "72", sanskrit: "गुडस्याष्टपले पथ्या विंशतिः स्यात् पल्ं पलम् दन्तीचित्रकयोः कर्षौ पिप्पलीत्रिवृतोर्दश", text: "guḍasyāṣṭapale pathyā viṃśatiḥ syāt palṃ palam dantīcitrakayoḥ karṣau pippalītrivṛtordaśa" },
      { type: "verse", number: "73", sanskrit: "प्रकल्प्य मोदकानेकं दशमे दशमे ऽहनि उष्णाम्भो ऽनुपिबन् खादेत्तान् सर्वान् विधिनामुना", text: "prakalpya modakānekaṃ daśame daśame 'hani uṣṇāmbho 'nupiban khādettān sarvān vidhināmunā" },
      { type: "verse", number: "74", sanskrit: "एते निष्परिहाराः स्युः सर्वव्याधिनिबर्हणाः विशेषाद्ग्रहणीपाण्डुकण्डूकोठार्शसां हिताः विरेचने मुख्यतमा नवैते त्रिवृतादयः", text: "ete niṣparihārāḥ syuḥ sarvavyādhinibarhaṇāḥ viśeṣādgrahaṇīpāṇḍukaṇḍūkoṭhārśasāṃ hitāḥ virecane mukhyatamā navaite trivṛtādayaḥ" },
      { type: "verse", number: "75", sanskrit: "हरीतकीमपि त्रिवृद्धिधानेनोपकल्पयेत् विशेषात् ग्रहणीशोफपाण्डुमेहोदरापहाम्", text: "harītakīmapi trivṛddhidhānenopakalpayet viśeṣāt grahaṇīśophapāṇḍumehodarāpahām" },
      { type: "verse", number: "76", sanskrit: "पिबेत् पथ्यां ससिन्धूत्थविडङ्गोषणनागराम् मूत्रेण वत्सकादेर्वा निर्यूहेण हरीतकीम्", text: "pibet pathyāṃ sasindhūtthaviḍaṅgoṣaṇanāgarām mūtreṇa vatsakādervā niryūheṇa harītakīm" },
      { type: "verse", number: "77", sanskrit: "पथ्यानागरचूर्णं वा संयुतं नीलिनीफलैः गुडेन भक्षयेत्तोयं कवोष्णं च पिबेदनु", text: "pathyānāgaracūrṇaṃ vā saṃyutaṃ nīlinīphalaiḥ guḍena bhakṣayettoyaṃ kavoṣṇaṃ ca pibedanu" },
      { type: "verse", number: "78", sanskrit: "पथ्यात्रिवृद्भ्यां गुटिकाः कार्या द्राक्षारसाप्लुताः माषप्रमाणास्ताः शुष्का लिह्याद्यक्ष्मी घृतद्रुताः पथ्यात्रिवृत्पटूष्णाम्बु सर्वत्रेष्टं विरेचनम्", text: "pathyātrivṛdbhyāṃ guṭikāḥ kāryā drākṣārasāplutāḥ māṣapramāṇāstāḥ śuṣkā lihyādyakṣmī ghṛtadrutāḥ pathyātrivṛtpaṭūṣṇāmbu sarvatreṣṭaṃ virecanam" },
      { type: "verse", number: "79", sanskrit: "स्नुक्क्षीरभाविते पथ्याचूर्णे कुर्वीत मोदकान् कोलास्थिमात्रान् शुष्कांश्च नवनीतेन लेहयेत् गुल्मोदरयकृत्प्लीहशूलानाहविबन्धिनः", text: "snukkṣīrabhāvite pathyācūrṇe kurvīta modakān kolāsthimātrān śuṣkāṃśca navanītena lehayet gulmodarayakṛtplīhaśūlānāhavibandhinaḥ" },
      { type: "verse", number: "80", sanskrit: "लिह्यादेरण्डतैलेन कुष्ठं त्रिकटुकान्वितम् सुखोदकं चानुपिबेत्सुखमेतद्विरेचनम्", text: "lihyāderaṇḍatailena kuṣṭhaṃ trikaṭukānvitam sukhodakaṃ cānupibetsukhametadvirecanam" },
      { type: "verse", number: "81", sanskrit: "अल्पस्यापि महार्थत्वं प्रभूतस्याल्पकर्मताम् कुर्यात् संश्लेषविश्लेषकालसंस्कारयुक्तिभिः", text: "alpasyāpi mahārthatvaṃ prabhūtasyālpakarmatām kuryāt saṃśleṣaviśleṣakālasaṃskārayuktibhiḥ" },
      { type: "verse", number: "82", sanskrit: "त्वक्केसराम्रातकदाडिमैलासितोपलामाक्षिकमातुगुङ्गैः मद्येन तस्तैश्च मनो ऽनुकूलैर्युक्तानि देयानि विरेचनानि", text: "tvakkesarāmrātakadāḍimailāsitopalāmākṣikamātuguṅgaiḥ madyena tastaiśca mano 'nukūlairyuktāni deyāni virecanāni" },
    ],
  },
  {
    sthana: "Калпасиддхистхана",
    number: 3,
    lang: "sa",
    content: [
      { type: "heading", heading: "Вамана видхи — протокол рвотной терапии" },
      { type: "text", text: "Глава 3 Калпасиддхистханы посвящена протокол рвотной терапии. Вагбхата систематизирует приготовление и применение очищающих средств." },
      { type: "verse", number: "1", sanskrit: "अथातो वमनविरेचनव्यापत्सिद्धिं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vamanavirecanavyāpatsiddhiṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अतिक्षुधितेनातिमृदुकोष्ठेनाल्पश्लेष्मणा दुर्वमेन हीनमात्रमतिमात्रं तीक्ष्णमतिशीतमजीर्णे वा पीतं वमनमधो गच्छति तत्रेप्सितानवाप्तिर्दोषोत्क्लेशश्च तं पुनराशु स्नेहयित्वा यौगिकैर्मात्राकालाद्यपेक्षं वामयेत् व्यापत्कराणि च पूर्वोक्तमतिक्रमं स्मरन् परिहरेत्", text: "atikṣudhitenātimṛdukoṣṭhenālpaśleṣmaṇā durvamena hīnamātramatimātraṃ tīkṣṇamatiśītamajīrṇe vā pītaṃ vamanamadho gacchati tatrepsitānavāptirdoṣotkleśaśca taṃ punarāśu snehayitvā yaugikairmātrākālādyapekṣaṃ vāmayet vyāpatkarāṇi ca pūrvoktamatikramaṃ smaran pariharet" },
      { type: "verse", number: "3", sanskrit: "अजीर्णिनः श्लेष्मवतो ऽत्युष्णतीक्ष्णलवणमतिमात्रमहृद्यं वा विरेचनमन्यद्वा भेषजमूर्ध्वं प्रवर्तते तत्र पूर्वोक्ता व्यापत्साधनं च तत ऊर्ध्वमप्युत्तिष्ठति हृद्यलेहवटकवर्ज्यमौषधं न तृतीयमवचारयेत्", text: "ajīrṇinaḥ śleṣmavato 'tyuṣṇatīkṣṇalavaṇamatimātramahṛdyaṃ vā virecanamanyadvā bheṣajamūrdhvaṃ pravartate tatra pūrvoktā vyāpatsādhanaṃ ca tata ūrdhvamapyuttiṣṭhati hṛdyalehavaṭakavarjyamauṣadhaṃ na tṛtīyamavacārayet" },
      { type: "verse", number: "4", sanskrit: "क्रूरकोष्ठस्यातितीक्ष्णाग्रेरल्पमल्पवीर्यं वा भेषजमूर्ध्वभागिकमधोभागिकं वा भक्तवदुपैति पाकम् तत्र समुदीर्णा दोषा यथाकालमनिर्ह्रियमाणा विभ्रमं कुर्वन्ति तं स्निग्धकोष्ठमनल्पममन्दं चौषधं पाययेत्", text: "krūrakoṣṭhasyātitīkṣṇāgreralpamalpavīryaṃ vā bheṣajamūrdhvabhāgikamadhobhāgikaṃ vā bhaktavadupaiti pākam tatra samudīrṇā doṣā yathākālamanirhriyamāṇā vibhramaṃ kurvanti taṃ snigdhakoṣṭhamanalpamamandaṃ cauṣadhaṃ pāyayet" },
      { type: "verse", number: "5", sanskrit: "कषायमल्पमप्रत्यग्रं रूक्षं वा भेषजमस्निग्धस्विन्नेन वा पीतं शीतोपचारेण वा स्तब्धं दोषविग्रथितमयोगी भवति तत्र वमने भूयो वामयेत् विरेचने स्निग्धस्विन्नं पुनर्विरेचयेत् उत्क्लिष्टभूरिदोषं वा तृतीये ऽहनि उभयोश्च संशोधनयोर्लवणतैलाभ्यक्तं पिण्डप्रस्तराभ्यां स्वेदयेत्", text: "kaṣāyamalpamapratyagraṃ rūkṣaṃ vā bheṣajamasnigdhasvinnena vā pītaṃ śītopacāreṇa vā stabdhaṃ doṣavigrathitamayogī bhavati tatra vamane bhūyo vāmayet virecane snigdhasvinnaṃ punarvirecayet utkliṣṭabhūridoṣaṃ vā tṛtīye 'hani ubhayośca saṃśodhanayorlavaṇatailābhyaktaṃ piṇḍaprastarābhyāṃ svedayet" },
      { type: "verse", number: "6", sanskrit: "स्निग्धस्विन्नस्य च वमनमकृत्वा विरेचनं पीतवतः सामस्य वा मृदु वा विरिक्तस्याधोभागेत्यर्थगुरुस्तब्धोदरता शूलो वातमूत्रपुरीषसङ्गश्च भवति तमप्ययोगिनं समूत्रैस्तीक्ष्णैरास्थाप्य जाङ्गलरसैश्च भोजयित्वा फलदारुपिप्पलीसिद्धेन तैलेनानुवास्य वातहरैश्च स्नेहैरुपस्नेह्य पुनस्तीक्ष्णैर्विरेचयेत्", text: "snigdhasvinnasya ca vamanamakṛtvā virecanaṃ pītavataḥ sāmasya vā mṛdu vā viriktasyādhobhāgetyarthagurustabdhodaratā śūlo vātamūtrapurīṣasaṅgaśca bhavati tamapyayoginaṃ samūtraistīkṣṇairāsthāpya jāṅgalarasaiśca bhojayitvā phaladārupippalīsiddhena tailenānuvāsya vātaharaiśca snehairupasnehya punastīkṣṇairvirecayet" },
      { type: "verse", number: "7", sanskrit: "कफोल्बणस्यातिस्निग्धस्य गुरुकोष्ठस्य मन्दाग्नेर्वा मृदुप्रणीतमौषधं भृशमुत्क्लेश्य दोषान् जाड्यतन्द्रादौर्बल्याङ्गसादान् जनयति तच्छीघ्रमुल्लिखेत् लङ्घनेन च सन्धुक्षिताग्निं पुनःस्निग्धं तीक्ष्णोष्णैर्विशोधयेत्", text: "kapholbaṇasyātisnigdhasya gurukoṣṭhasya mandāgnervā mṛdupraṇītamauṣadhaṃ bhṛśamutkleśya doṣān jāḍyatandrādaurbalyāṅgasādān janayati tacchīghramullikhet laṅghanena ca sandhukṣitāgniṃ punaḥsnigdhaṃ tīkṣṇoṣṇairviśodhayet" },
      { type: "verse", number: "8", sanskrit: "सशेषान्नाय वातश्लेष्मवते रूक्षाय सोदावर्ताय मन्दाग्नये वा शीतं रूक्षं वा दत्तमौषधं भृशमाध्मानं करोति तत्र मलसङ्गात् समुन्नह्यत्युदरमन्तःशूलं दृतिवत् पार्श्वयोरापूर्णता शिरःपृष्ठरुजा श्वासकासौ पायुबस्तिनिस्तोदश्च भवति तमुदावर्तानाहहराभ्यङ्गस्वेदवर्तिदीपनचूर्णबस्तिक्रियाभिरुपचरेत्", text: "saśeṣānnāya vātaśleṣmavate rūkṣāya sodāvartāya mandāgnaye vā śītaṃ rūkṣaṃ vā dattamauṣadhaṃ bhṛśamādhmānaṃ karoti tatra malasaṅgāt samunnahyatyudaramantaḥśūlaṃ dṛtivat pārśvayorāpūrṇatā śiraḥpṛṣṭharujā śvāsakāsau pāyubastinistodaśca bhavati tamudāvartānāhaharābhyaṅgasvedavartidīpanacūrṇabastikriyābhirupacaret" },
      { type: "verse", number: "9", sanskrit: "क्षामेणाल्पबलेन मृदुकोष्ठाग्निना रूक्षेणास्निग्धेन वा स्विन्नेन सामेन वा बलवदौषधमुपयुक्तं सपित्तमनिलं प्रदूष्य परिकर्तिकामापादयति तत्र नाभिबस्तिगुदमेढ्रे सदाहपरिकर्तनमनिलसङ्गो विष्टम्भश्च", text: "kṣāmeṇālpabalena mṛdukoṣṭhāgninā rūkṣeṇāsnigdhena vā svinnena sāmena vā balavadauṣadhamupayuktaṃ sapittamanilaṃ pradūṣya parikartikāmāpādayati tatra nābhibastigudameḍhre sadāhaparikartanamanilasaṅgo viṣṭambhaśca" },
      { type: "verse", number: "10", sanskrit: "तं कृष्णतिलमधुकमधुयुक्तैः पिच्छाबस्तिभिरास्थापयेत् क्षीरिवृक्षशृतक्षीरेण वा शीताम्बुपरिषिक्तं चैनं पयसा भुक्तवन्तं घृतमण्डेन यष्टीमधुकतैलेन वानुवासयेत् क्षामस्य च मधुरो बृंहणश्च सर्वो विधिरिष्टः", text: "taṃ kṛṣṇatilamadhukamadhuyuktaiḥ picchābastibhirāsthāpayet kṣīrivṛkṣaśṛtakṣīreṇa vā śītāmbupariṣiktaṃ cainaṃ payasā bhuktavantaṃ ghṛtamaṇḍena yaṣṭīmadhukatailena vānuvāsayet kṣāmasya ca madhuro bṛṃhaṇaśca sarvo vidhiriṣṭaḥ" },
      { type: "verse", number: "11", sanskrit: "सामे लङ्घनदीपनं च लघुरूक्षोष्णं चान्नपानम् निरामीभूते ऽनुबन्धे लघु क्षारम्लम् सवाते दधिसाराम्लं दाडिमत्वचा युक्तं भोजने पाने च प्रयुञ्जीत सदाडिमरसं च सर्पिः पिबेदुष्णाम्बुना वा तिलदेवदारुकल्कम्", text: "sāme laṅghanadīpanaṃ ca laghurūkṣoṣṇaṃ cānnapānam nirāmībhūte 'nubandhe laghu kṣāramlam savāte dadhisārāmlaṃ dāḍimatvacā yuktaṃ bhojane pāne ca prayuñjīta sadāḍimarasaṃ ca sarpiḥ pibeduṣṇāmbunā vā tiladevadārukalkam" },
      { type: "verse", number: "12", sanskrit: "क्रूरकोष्ठस्य बहुदोषस्याल्पमल्पगुणं मृदुस्निग्धं वा शोधनमवचारितमुत्क्लेश्य दोषान् न निर्हरति अल्पाल्पं च पित्तकफसंसृष्टं परिस्रवति विष्टम्भगौरवशोफकण्डूपाण्डुताङ्गसादगुल्मशूलानि चापादयति", text: "krūrakoṣṭhasya bahudoṣasyālpamalpaguṇaṃ mṛdusnigdhaṃ vā śodhanamavacāritamutkleśya doṣān na nirharati alpālpaṃ ca pittakaphasaṃsṛṣṭaṃ parisravati viṣṭambhagauravaśophakaṇḍūpāṇḍutāṅgasādagulmaśūlāni cāpādayati" },
      { type: "verse", number: "13", sanskrit: "तं तिनिशधवाश्च्वकर्णपलाशबलानिर्यूहैर्मधुयुक्तैरास्थापयेत् उपशान्तपरिस्रवं च पुनरुपस्निग्धं तीक्ष्णैः शोधयेत् शुद्धे च दीपनांश्चूर्णासवारिष्टादीन् योजयेत्", text: "taṃ tiniśadhavāścvakarṇapalāśabalāniryūhairmadhuyuktairāsthāpayet upaśāntaparisravaṃ ca punarupasnigdhaṃ tīkṣṇaiḥ śodhayet śuddhe ca dīpanāṃścūrṇāsavāriṣṭādīn yojayet" },
      { type: "verse", number: "14", sanskrit: "पीतौषधो यदा वेगमुदीरयति निगृह्णाति वा तदा प्रवाहिकास्य जायते तस्यां सदाहशूलं सपिच्छं श्वेतं कृष्णं रक्तं वा भृशं प्रवाहमाणः कफमुपविशति तं परिस्रवविधिनोपचरेत्", text: "pītauṣadho yadā vegamudīrayati nigṛhṇāti vā tadā pravāhikāsya jāyate tasyāṃ sadāhaśūlaṃ sapicchaṃ śvetaṃ kṛṣṇaṃ raktaṃ vā bhṛśaṃ pravāhamāṇaḥ kaphamupaviśati taṃ parisravavidhinopacaret" },
      { type: "verse", number: "15", sanskrit: "पीतौषधस्य भेषजोद्गारच्छर्द्यादीनां निग्रहाद्वातादयः कुपिता हृदयमुपसृत्य हृद्ग्रहं घोरमावहन्ति ततः प्रधानमर्मोपतापाद्वेदनाभिरत्यर्थमातुरः पीड्यते मोहहिध्माकासलालापार्श्वशूलयुतो वेपथुमान् नष्टसंज्ञो दन्तान् कटकटापयत्युद्वृत्ताक्षो जिह्वां खादति तं हृदयोपसरणमाहुः", text: "pītauṣadhasya bheṣajodgāracchardyādīnāṃ nigrahādvātādayaḥ kupitā hṛdayamupasṛtya hṛdgrahaṃ ghoramāvahanti tataḥ pradhānamarmopatāpādvedanābhiratyarthamāturaḥ pīḍyate mohahidhmākāsalālāpārśvaśūlayuto vepathumān naṣṭasaṃjño dantān kaṭakaṭāpayatyudvṛttākṣo jihvāṃ khādati taṃ hṛdayopasaraṇamāhuḥ" },
      { type: "verse", number: "16", sanskrit: "तस्मै भिषक् शीघ्रममुह्यन्नभ्यङ्गपूर्वं धान्यस्वेदेन परिस्वेद्य तीक्ष्णमवपीडं दद्यात् यष्टीमधुकमिश्रेण तण्डुलाम्बुना वमनम् कटुभिर्वा कफोत्तराय ततो दोषशेषं पाचनीयैः पाचयेद्यथादोषोच्छ्रयं च बस्तीन् वितरेत्", text: "tasmai bhiṣak śīghramamuhyannabhyaṅgapūrvaṃ dhānyasvedena parisvedya tīkṣṇamavapīḍaṃ dadyāt yaṣṭīmadhukamiśreṇa taṇḍulāmbunā vamanam kaṭubhirvā kaphottarāya tato doṣaśeṣaṃ pācanīyaiḥ pācayedyathādoṣocchrayaṃ ca bastīn vitaret" },
      { type: "verse", number: "17", sanskrit: "अस्निग्धस्विन्नेनाब्रह्मचरिणा वेगधारिणा मृदुकोष्ठेन सुकुमारेण वा रूक्षमौषधमतिमात्रं प्रयुक्तमतिविरेकाद्वायुं कोपयति तेन सर्वाङ्गप्रग्रहो भवति तस्य विशेषात् पार्श्वपृष्ठश्रोणिमन्याममसु शूलमूर्च्छाभ्रमकल्पस्तम्भो निस्तोदो भेद उद्वेष्टनं संज्ञानाशश्च स्यात् तमभ्यज्य धान्यैः स्वेदयित्वा यष्टीमधुकविपक्वेन तैलेनानुवासयेत् वातहरं चान्नपानम्", text: "asnigdhasvinnenābrahmacariṇā vegadhāriṇā mṛdukoṣṭhena sukumāreṇa vā rūkṣamauṣadhamatimātraṃ prayuktamativirekādvāyuṃ kopayati tena sarvāṅgapragraho bhavati tasya viśeṣāt pārśvapṛṣṭhaśroṇimanyāmamasu śūlamūrcchābhramakalpastambho nistodo bheda udveṣṭanaṃ saṃjñānāśaśca syāt tamabhyajya dhānyaiḥ svedayitvā yaṣṭīmadhukavipakvena tailenānuvāsayet vātaharaṃ cānnapānam" },
      { type: "verse", number: "18", sanskrit: "स्निग्धस्विन्नस्यातिमृदुकोष्ठस्य क्षुधितस्य वा तीक्ष्णमतिभूरि वा प्रयुक्तमौषधं सर्वशो निर्हृत्य मलान् धातूनपि द्रवीकृत्य विस्रावयेदतियोगेन तं शतधौतघृतेनाभ्यज्य कषायस्वादुशीतैः प्रदेहपरिषेकावगाहान्नपानैः शर्करामधुमद्भिश्च लहः स्तम्भयेत्", text: "snigdhasvinnasyātimṛdukoṣṭhasya kṣudhitasya vā tīkṣṇamatibhūri vā prayuktamauṣadhaṃ sarvaśo nirhṛtya malān dhātūnapi dravīkṛtya visrāvayedatiyogena taṃ śatadhautaghṛtenābhyajya kaṣāyasvāduśītaiḥ pradehapariṣekāvagāhānnapānaiḥ śarkarāmadhumadbhiśca lahaḥ stambhayet" },
      { type: "verse", number: "19", sanskrit: "चन्दनाञ्जनोशीरच्छागासृक्शीतोदकैर्लाजसक्तून् पाययेत् पिच्छाबस्तींश्चस्मै दद्यान्मधुरवर्गसिद्धं च क्षीरसर्पिः सर्पिर्मण्डो ऽनुवासनम् रक्तपित्तविधानं च कुर्यात्", text: "candanāñjanośīracchāgāsṛkśītodakairlājasaktūn pāyayet picchābastīṃścasmai dadyānmadhuravargasiddhaṃ ca kṣīrasarpiḥ sarpirmaṇḍo 'nuvāsanam raktapittavidhānaṃ ca kuryāt" },
      { type: "verse", number: "20", sanskrit: "विशेषेण वमनातियोगे सघृततसिताक्षौद्रं फलरसैर्मन्थं पिबेत् क्षीरिवृक्षशुङ्गसिद्धां वा समाक्षिकां पेयां क्षीरं वा संग्राहिद्रव्यसिद्धं च क्षीरं भोजने ऽवचारयेत्", text: "viśeṣeṇa vamanātiyoge saghṛtatasitākṣaudraṃ phalarasairmanthaṃ pibet kṣīrivṛkṣaśuṅgasiddhāṃ vā samākṣikāṃ peyāṃ kṣīraṃ vā saṃgrāhidravyasiddhaṃ ca kṣīraṃ bhojane 'vacārayet" },
      { type: "verse", number: "21", sanskrit: "सोद्गारायां च छर्द्यां धनिकामधूकमधुरसामुस्ताञ्जनानि मधुना लिह्यात् वाक्सङ्गे हनुसङ्गे ऽनिलार्तौ च घृतमांसरससिद्धामल्पतण्डुलां पेयां पिबेत् स्नेहस्वेदौ चावचारयेत्", text: "sodgārāyāṃ ca chardyāṃ dhanikāmadhūkamadhurasāmustāñjanāni madhunā lihyāt vāksaṅge hanusaṅge 'nilārtau ca ghṛtamāṃsarasasiddhāmalpataṇḍulāṃ peyāṃ pibet snehasvedau cāvacārayet" },
      { type: "verse", number: "22", sanskrit: "जिह्वाप्रवेशे स्निग्धाम्ललवणान् कवलगण्डूषान् हृद्यांश्चाजमांसरसान् पुरतश्चास्य फलान्यम्लानि खादयेत्", text: "jihvāpraveśe snigdhāmlalavaṇān kavalagaṇḍūṣān hṛdyāṃścājamāṃsarasān purataścāsya phalānyamlāni khādayet" },
      { type: "verse", number: "23", sanskrit: "निर्गतां तु जिह्वां तिलद्राक्षाकल्कलिप्तां व्योषलवणचूर्णप्रघृष्टां वा प्रवेशयेत् अक्षिणी व्यावृत्ते घृताभ्यक्ते पीडयेद्विसंज्ञं सामवेणुगीतशब्दान् श्रावयेत्", text: "nirgatāṃ tu jihvāṃ tiladrākṣākalkaliptāṃ vyoṣalavaṇacūrṇapraghṛṣṭāṃ vā praveśayet akṣiṇī vyāvṛtte ghṛtābhyakte pīḍayedvisaṃjñaṃ sāmaveṇugītaśabdān śrāvayet" },
      { type: "verse", number: "24", sanskrit: "विरेचनातियोगे तण्डुलाम्भसा मधुमिश्रेण वमेत् प्रियङ्वादिं च तण्डुलोदकेन पिबेद्रोध्ररसाञ्जनदाडिमत्वचो वा सोमवल्कलट्फलोत्पलसमङ्गापद्मकेसराणि वा क्षौद्रशर्करामधुकौडुम्बरत्वचो वा रक्तातिसारक्रियां च कुर्वीत", text: "virecanātiyoge taṇḍulāmbhasā madhumiśreṇa vamet priyaṅvādiṃ ca taṇḍulodakena pibedrodhrarasāñjanadāḍimatvaco vā somavalkalaṭphalotpalasamaṅgāpadmakesarāṇi vā kṣaudraśarkarāmadhukauḍumbaratvaco vā raktātisārakriyāṃ ca kurvīta" },
      { type: "verse", number: "25", sanskrit: "गुदं निःसृतमभ्यज्य स्वेदयित्वा कषायैश्चस्तम्भयित्वा प्रवेशयेत् पूर्ववच्च वाक्सङ्गादीन् साधयेत्", text: "gudaṃ niḥsṛtamabhyajya svedayitvā kaṣāyaiścastambhayitvā praveśayet pūrvavacca vāksaṅgādīn sādhayet" },
      { type: "verse", number: "26", sanskrit: "उभयत्र च जीवरक्तपित्तयोर्ज्ञानार्थं रक्ते शुक्लं पिचु प्लोतं वा क्षिपेत् तस्मिन्नावाने कोष्णाम्बुक्षालितशुद्धे जीवरक्तम् विवर्णे तु रक्तपित्तं विद्यात् अन्नं वा तद्विमिश्रं शुने काकाय वा दद्यात् तस्मिन् भुक्ते जीवं वदेदभुक्ते पित्तम्", text: "ubhayatra ca jīvaraktapittayorjñānārthaṃ rakte śuklaṃ picu plotaṃ vā kṣipet tasminnāvāne koṣṇāmbukṣālitaśuddhe jīvaraktam vivarṇe tu raktapittaṃ vidyāt annaṃ vā tadvimiśraṃ śune kākāya vā dadyāt tasmin bhukte jīvaṃ vadedabhukte pittam" },
      { type: "verse", number: "27", sanskrit: "आमरणाच्च तस्य तृण्मूर्छामदार्तस्य क्रियां पित्तघ्नीमतियोगोक्तां च कुर्यात् एणादिरुधिरं वातिस्रुतरक्तोक्तविधिना सक्षौद्रं शीघ्रमुपयुञ्जीत तद्धि सद्यो जीवमभिसन्दधाति श्यामाकाश्मर्यमधुकदूर्वोशीरैर्वा शृतं पयो घृतमण्डाञ्जनयुक्तं शीतं बस्तौ निषेचयेत्", text: "āmaraṇācca tasya tṛṇmūrchāmadārtasya kriyāṃ pittaghnīmatiyogoktāṃ ca kuryāt eṇādirudhiraṃ vātisrutaraktoktavidhinā sakṣaudraṃ śīghramupayuñjīta taddhi sadyo jīvamabhisandadhāti śyāmākāśmaryamadhukadūrvośīrairvā śṛtaṃ payo ghṛtamaṇḍāñjanayuktaṃ śītaṃ bastau niṣecayet" },
      { type: "verse", number: "28", sanskrit: "शेषेष्वपि चासम्यक्प्रयुक्तवमनविरेचनोपद्रवेषु यथामयं दोषादीनपेक्ष्य प्रतिकुर्याद्बस्तिव्यापत्सिद्धिं चेक्षेत", text: "śeṣeṣvapi cāsamyakprayuktavamanavirecanopadraveṣu yathāmayaṃ doṣādīnapekṣya pratikuryādbastivyāpatsiddhiṃ cekṣeta" },
      { type: "verse", number: "29", sanskrit: "एवमुभयतोभागे ऽपि शोधने यथावस्थमुत्तिष्ठेत या तु विरेचने परिकर्तिका तद्वमने कण्ठक्षणनम् यदधःपरिस्रवः स कफप्रसेको यदधःप्रवाहणं स शुष्कोद्गार इति भवति चात्र", text: "evamubhayatobhāge 'pi śodhane yathāvasthamuttiṣṭheta yā tu virecane parikartikā tadvamane kaṇṭhakṣaṇanam yadadhaḥparisravaḥ sa kaphapraseko yadadhaḥpravāhaṇaṃ sa śuṣkodgāra iti bhavati cātra" },
      { type: "verse", number: "30", sanskrit: "अतिमात्रमकाले ऽल्पं तुल्यवीयरभावितम् असम्यक्संस्कृतं जीर्णं व्यापद्येतौषधं ध्रुवम्", text: "atimātramakāle 'lpaṃ tulyavīyarabhāvitam asamyaksaṃskṛtaṃ jīrṇaṃ vyāpadyetauṣadhaṃ dhruvam" },
      { type: "verse", number: "31", sanskrit: "छर्दनं न तु दुश्छद दुर्विरेच्यं न रेचनम् पाययेदौषधं भूयस्तन्निहन्ति तथा हि तौ", text: "chardanaṃ na tu duśchada durvirecyaṃ na recanam pāyayedauṣadhaṃ bhūyastannihanti tathā hi tau" },
      { type: "verse", number: "32", sanskrit: "यस्योर्ध्वं कफसंसृष्टं पीतं यात्यानुलोमिकम् वमितं कवलैः शुद्धं लङ्घितं पाययेत्तु तम्", text: "yasyordhvaṃ kaphasaṃsṛṣṭaṃ pītaṃ yātyānulomikam vamitaṃ kavalaiḥ śuddhaṃ laṅghitaṃ pāyayettu tam" },
      { type: "verse", number: "33", sanskrit: "विबद्धे ऽल्पे चिराद्दोषे स्रवत्युष्णं पिबेज्जलम् तेनाध्मानं वमिस्तृष्णा विबन्धश्चाशु शाम्यति", text: "vibaddhe 'lpe cirāddoṣe sravatyuṣṇaṃ pibejjalam tenādhmānaṃ vamistṛṣṇā vibandhaścāśu śāmyati" },
      { type: "verse", number: "34", sanskrit: "भेषजं दोषरुद्धं चेन्नोध्व नाधः प्रवर्तते सोद्गारं साङ्गशूलं वा स्वेदं तत्रावचारयेत्", text: "bheṣajaṃ doṣaruddhaṃ cennodhva nādhaḥ pravartate sodgāraṃ sāṅgaśūlaṃ vā svedaṃ tatrāvacārayet" },
      { type: "verse", number: "35", sanskrit: "सम्पग्विरिक्तस्योद्गारे भेषजं क्षिप्रमुल्लिखेत् अजीर्णमप्रवृत्तौ तु सुशीतैः स्तम्भयेद्भिषक्", text: "sampagviriktasyodgāre bheṣajaṃ kṣipramullikhet ajīrṇamapravṛttau tu suśītaiḥ stambhayedbhiṣak" },
      { type: "verse", number: "36", sanskrit: "कदाचिच्छ्लेष्मणा रुद्धं तिष्ठत्युरसि भेषजम् क्षीणे श्लेष्मणि सायाह्ने रात्रौ वा तत् प्रवर्तते", text: "kadācicchleṣmaṇā ruddhaṃ tiṣṭhatyurasi bheṣajam kṣīṇe śleṣmaṇi sāyāhne rātrau vā tat pravartate" },
      { type: "verse", number: "37", sanskrit: "रुक्षानाहारयोर्जीर्णे तिष्ठत्यूर्ध्वं गते ऽपि वा वायुना भेषजे त्वन्यत् सस्नेहलवणं पिबेत्", text: "rukṣānāhārayorjīrṇe tiṣṭhatyūrdhvaṃ gate 'pi vā vāyunā bheṣaje tvanyat sasnehalavaṇaṃ pibet" },
      { type: "verse", number: "38", sanskrit: "तृण्मोहभ्रममूर्छाद्याः स्युर्जीर्यति च भेषजे पित्तघ्नं स्वादु शीतं च भेषजं तत्र शस्यते", text: "tṛṇmohabhramamūrchādyāḥ syurjīryati ca bheṣaje pittaghnaṃ svādu śītaṃ ca bheṣajaṃ tatra śasyate" },
      { type: "verse", number: "39", sanskrit: "लालाहृल्लासविष्टम्भरोमहर्षाः कफावृते भेषजं तत्र तीक्ष्णोष्णं कट्वादि कफनुद्धितम्", text: "lālāhṛllāsaviṣṭambharomaharṣāḥ kaphāvṛte bheṣajaṃ tatra tīkṣṇoṣṇaṃ kaṭvādi kaphanuddhitam" },
      { type: "verse", number: "40", sanskrit: "प्रतिकूला गतिः पाको ग्रथितत्वं सगौरवम् दोषोत्क्लेशो भृशाध्मानं परिकर्तः परिस्रवः", text: "pratikūlā gatiḥ pāko grathitatvaṃ sagauravam doṣotkleśo bhṛśādhmānaṃ parikartaḥ parisravaḥ" },
      { type: "verse", number: "41", sanskrit: "प्रवाहिका हृद्ग्रहणं सर्वगात्रपरिग्रहः सह धातुस्रवेणैता द्वादशोक्ताः ससाधनाः व्यापदो विधिविभ्रंशात् द्विविधे ऽपि विरेचने", text: "pravāhikā hṛdgrahaṇaṃ sarvagātraparigrahaḥ saha dhātusraveṇaitā dvādaśoktāḥ sasādhanāḥ vyāpado vidhivibhraṃśāt dvividhe 'pi virecane" },
      { type: "verse", number: "42", sanskrit: "उत्पद्यमानासु च तासु तासु व्यापत्सु संशोधनविभ्रमेण दिशानयैवाशु यतेत सिद्ध्यै ज्योतिर्हि शास्त्रं नयदुर्नयानाम्", text: "utpadyamānāsu ca tāsu tāsu vyāpatsu saṃśodhanavibhrameṇa diśānayaivāśu yateta siddhyai jyotirhi śāstraṃ nayadurnayānām" },
    ],
  },
  {
    sthana: "Калпасиддхистхана",
    number: 4,
    lang: "sa",
    content: [
      { type: "heading", heading: "Виречана видхи — протокол слабительной терапии" },
      { type: "text", text: "Глава 4 Калпасиддхистханы посвящена протокол слабительной терапии. Вагбхата систематизирует приготовление и применение очищающих средств." },
      { type: "verse", number: "1", sanskrit: "अथातो बस्तिकल्पं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bastikalpaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "बलां गुडूचीं त्रिफलां सरास्नां द्विपञ्चमूलं च पलोन्मितानि अष्टौ फलान्यर्धतुलां च मांसात् छागात् पचेदप्सु चतुर्थशेषम्", text: "balāṃ guḍūcīṃ triphalāṃ sarāsnāṃ dvipañcamūlaṃ ca palonmitāni aṣṭau phalānyardhatulāṃ ca māṃsāt chāgāt pacedapsu caturthaśeṣam" },
      { type: "verse", number: "3", sanskrit: "पूतो यवानीफलबिल्वकुष्ठवचाशताह्वाघनपिप्पलीनाम् कल्कैर्गुडक्षौद्रघृतः सतैलैर्युक्तः सुखोष्णो लवणान्वितश्च", text: "pūto yavānīphalabilvakuṣṭhavacāśatāhvāghanapippalīnām kalkairguḍakṣaudraghṛtaḥ satailairyuktaḥ sukhoṣṇo lavaṇānvitaśca" },
      { type: "verse", number: "4", sanskrit: "बस्तिः परं सर्वगदप्रमाथीस्वस्थे हितो जीवनबृंहणश्च बस्तौ च यस्मिन् पठितो न कल्कः सर्वत्र दद्यादमुमेव तत्र", text: "bastiḥ paraṃ sarvagadapramāthīsvasthe hito jīvanabṛṃhaṇaśca bastau ca yasmin paṭhito na kalkaḥ sarvatra dadyādamumeva tatra" },
      { type: "verse", number: "5", sanskrit: "द्विपञ्चमूलस्य रसो ऽम्लयुक्तः सच्छागमांसस्य सपूर्वपेष्यः त्रिस्नेहयुक्तः प्रवरो निरूहः सर्वानिलव्याधिहरः प्रदिष्टः", text: "dvipañcamūlasya raso 'mlayuktaḥ sacchāgamāṃsasya sapūrvapeṣyaḥ trisnehayuktaḥ pravaro nirūhaḥ sarvānilavyādhiharaḥ pradiṣṭaḥ" },
      { type: "verse", number: "6", sanskrit: "बलापटोलीलघुपञ्चमूलत्रायान्तकैरण्डयवात् सुसिद्धात् प्रस्थो रसाच्छागरसार्धयुक्तः साध्यः पुनः प्रस्थसमः स यावत्", text: "balāpaṭolīlaghupañcamūlatrāyāntakairaṇḍayavāt susiddhāt prastho rasācchāgarasārdhayuktaḥ sādhyaḥ punaḥ prasthasamaḥ sa yāvat" },
      { type: "verse", number: "7", sanskrit: "प्रियङ्गुकृष्णाघनकल्कयुक्तः सतैलसर्पिर्मधुसैन्धवश्च स्याद्दीपनो मांसबलप्रदश्च चक्षुर्बलं चोपदधाति सद्यः", text: "priyaṅgukṛṣṇāghanakalkayuktaḥ satailasarpirmadhusaindhavaśca syāddīpano māṃsabalapradaśca cakṣurbalaṃ copadadhāti sadyaḥ" },
      { type: "verse", number: "8", sanskrit: "एरण्डमूलात्त्रिपलं पलाशत्तथा पलांशं लघुपञ्चमूलम् रास्नाबलाछिन्नरुहाश्वगन्धापुनर्नवारग्वधदेवदारु", text: "eraṇḍamūlāttripalaṃ palāśattathā palāṃśaṃ laghupañcamūlam rāsnābalāchinnaruhāśvagandhāpunarnavāragvadhadevadāru" },
      { type: "verse", number: "9", sanskrit: "फलानि चाष्टौ सलिलाढकाभ्यां विपाचयेदष्टमशेषिते ऽस्मिन् वचाशताह्वाहपुषाप्रियङ्गुयष्टीकणावत्सकबीजमुस्तम्", text: "phalāni cāṣṭau salilāḍhakābhyāṃ vipācayedaṣṭamaśeṣite 'smin vacāśatāhvāhapuṣāpriyaṅguyaṣṭīkaṇāvatsakabījamustam" },
      { type: "verse", number: "10", sanskrit: "दद्यात् सुपिष्टं सहतार्क्ष्यशैलमक्षप्रमाणं लवणांशयुक्तम् समाक्षिकस्तैलयुतः समूत्रो बस्तिर्जयेल्लेखनदीपनो ऽसौ", text: "dadyāt supiṣṭaṃ sahatārkṣyaśailamakṣapramāṇaṃ lavaṇāṃśayuktam samākṣikastailayutaḥ samūtro bastirjayellekhanadīpano 'sau" },
      { type: "verse", number: "11", sanskrit: "जङ्घोरुपादत्रिकपृष्ठकोष्ठहृद्गुह्यशूलं गुरुतां विबन्धम् गुल्माश्मवर्ध्मग्रहणीगुदोत्थांस्तांस्तांश्च रोगान् कफवातजातान्", text: "jaṅghorupādatrikapṛṣṭhakoṣṭhahṛdguhyaśūlaṃ gurutāṃ vibandham gulmāśmavardhmagrahaṇīgudotthāṃstāṃstāṃśca rogān kaphavātajātān" },
      { type: "verse", number: "12", sanskrit: "चतुष्पले तैलघृतस्य भृष्टः छागाच्छतार्धो दधिदाडिमाम्लः रसः सपेष्यो बलवणमांसरेतोग्नितैमिर्यशिरोरुजीष्टः", text: "catuṣpale tailaghṛtasya bhṛṣṭaḥ chāgācchatārdho dadhidāḍimāmlaḥ rasaḥ sapeṣyo balavaṇamāṃsaretognitaimiryaśirorujīṣṭaḥ" },
      { type: "verse", number: "13", sanskrit: "यष्ट्याह्वयस्याष्टपलेन सिद्धं पयः शताह्वाफलपिप्पलीभिः युक्तं ससर्पिर्मधुवातरक्तविसर्पवैस्वर्यहितो निरूहः", text: "yaṣṭyāhvayasyāṣṭapalena siddhaṃ payaḥ śatāhvāphalapippalībhiḥ yuktaṃ sasarpirmadhuvātaraktavisarpavaisvaryahito nirūhaḥ" },
      { type: "verse", number: "14", sanskrit: "यष्ठ्याह्वलोध्राभयचन्दनैश्च शृतं पयो ऽग्र्यं कमलोत्पलैश्च सशर्कराक्षौद्रघृतं सुशीतं पित्तामयान् हन्ति सजीवनीयम्", text: "yaṣṭhyāhvalodhrābhayacandanaiśca śṛtaṃ payo 'gryaṃ kamalotpalaiśca saśarkarākṣaudraghṛtaṃ suśītaṃ pittāmayān hanti sajīvanīyam" },
      { type: "verse", number: "15", sanskrit: "गोपाङ्गनाचन्दनशीतपाकीद्राक्षर्धिकाश्मर्यमधूकसेव्यैः पयः शृतं श्रावणिमुद्गपर्णीबलास्वगुप्तामधुयष्टिकल्कैः", text: "gopāṅganācandanaśītapākīdrākṣardhikāśmaryamadhūkasevyaiḥ payaḥ śṛtaṃ śrāvaṇimudgaparṇībalāsvaguptāmadhuyaṣṭikalkaiḥ" },
      { type: "verse", number: "16", sanskrit: "गोधूमचूर्णैश्च पिचुप्रमाणैरिक्षोविदार्याश्च रसेन युक्तम् तैलेन यष्टीमधुसाधितेन सितोपलाक्षौद्रघृतैश्च शीतः", text: "godhūmacūrṇaiśca picupramāṇairikṣovidāryāśca rasena yuktam tailena yaṣṭīmadhusādhitena sitopalākṣaudraghṛtaiśca śītaḥ" },
      { type: "verse", number: "17", sanskrit: "बस्तिः प्रशस्तः ससमस्तदेहदाहे सशूले ऽवयवाश्रिते वा गुल्मातिसारभ्रममूत्रकृच्छ्रक्षीणे क्षतौजोबलसङ्क्षये च", text: "bastiḥ praśastaḥ sasamastadehadāhe saśūle 'vayavāśrite vā gulmātisārabhramamūtrakṛcchrakṣīṇe kṣataujobalasaṅkṣaye ca" },
      { type: "verse", number: "18", sanskrit: "कोशातकारग्वधदेवदारुमूर्वाश्वदंष्ट्राकुटजार्कपाठाः पक्त्वा कुलत्थान् बृहतीं च तोये रसस्य तस्य प्रसृता दश स्युः", text: "kośātakāragvadhadevadārumūrvāśvadaṃṣṭrākuṭajārkapāṭhāḥ paktvā kulatthān bṛhatīṃ ca toye rasasya tasya prasṛtā daśa syuḥ" },
      { type: "verse", number: "19", sanskrit: "तान् सर्षपैलामदनैः सकुष्ठैरक्षप्रमाणैः प्रसृतैश्च युक्तान् क्षौद्रस्य तैलस्य फलाह्वयस्य क्षारस्य तैलस्य च सार्षपस्य", text: "tān sarṣapailāmadanaiḥ sakuṣṭhairakṣapramāṇaiḥ prasṛtaiśca yuktān kṣaudrasya tailasya phalāhvayasya kṣārasya tailasya ca sārṣapasya" },
      { type: "verse", number: "20", sanskrit: "दद्यान्निरूहं कफरोगिताय मन्दाग्नये चाशनविद्विषे च", text: "dadyānnirūhaṃ kapharogitāya mandāgnaye cāśanavidviṣe ca" },
      { type: "verse", number: "21", sanskrit: "पुनर्नवैरण्डवृषाश्मभेदवृश्चीवभूतीकबलापलाशान् द्विपञ्चमूलं च पलांशकानि क्षुण्णानि धौतानि फलानि चाष्टौ", text: "punarnavairaṇḍavṛṣāśmabhedavṛścīvabhūtīkabalāpalāśān dvipañcamūlaṃ ca palāṃśakāni kṣuṇṇāni dhautāni phalāni cāṣṭau" },
      { type: "verse", number: "22", sanskrit: "बिल्वं यवाङ्कोलकुलत्थधान्यफानि च स्युः प्रसृतोन्मितानि पयो जलद्व्याढकसाधितं तत् क्षीरावशिष्टं शुचिवस्त्रपूतम्", text: "bilvaṃ yavāṅkolakulatthadhānyaphāni ca syuḥ prasṛtonmitāni payo jaladvyāḍhakasādhitaṃ tat kṣīrāvaśiṣṭaṃ śucivastrapūtam" },
      { type: "verse", number: "23", sanskrit: "वचाशताह्वामरदारुकुष्ठयष्ट्याह्वसिद्धार्थकपिप्पलीनाम् कल्कैर्यवान्या मदनैश्च युक्तं नात्युष्णशीतं गुडसैन्धवाक्तम्", text: "vacāśatāhvāmaradārukuṣṭhayaṣṭyāhvasiddhārthakapippalīnām kalkairyavānyā madanaiśca yuktaṃ nātyuṣṇaśītaṃ guḍasaindhavāktam" },
      { type: "verse", number: "24", sanskrit: "क्षौद्रस्य तैलस्य च सर्पिषश्च नवस्य युक्तं प्रसृतित्रयेण दद्यान्निरूहं विधिना विधिज्ञः ससर्वसंसर्गकृतामयघ्नः", text: "kṣaudrasya tailasya ca sarpiṣaśca navasya yuktaṃ prasṛtitrayeṇa dadyānnirūhaṃ vidhinā vidhijñaḥ sasarvasaṃsargakṛtāmayaghnaḥ" },
      { type: "verse", number: "25", sanskrit: "अर्धार्धविहितान् बस्तीनतश्चित्रान् प्रवक्ष्यते कोशातकीद्वयेक्ष्वाकुफलजीमूतवत्सकाः", text: "ardhārdhavihitān bastīnataścitrān pravakṣyate kośātakīdvayekṣvākuphalajīmūtavatsakāḥ" },
      { type: "verse", number: "26", sanskrit: "श्यामात्रिवृतयोर्मूलं तथा दन्तीद्रवन्तिजम् प्रकीर्या चोदकीर्या च क्षीरिणी नीलिनीफलम्", text: "śyāmātrivṛtayormūlaṃ tathā dantīdravantijam prakīryā codakīryā ca kṣīriṇī nīlinīphalam" },
      { type: "verse", number: "27", sanskrit: "सप्तपाशङ्खिनीलोध्रं फलं कम्पिल्लकस्य च स्वकल्कसैन्धवयुताः पक्वाशयविशोधनाः", text: "saptapāśaṅkhinīlodhraṃ phalaṃ kampillakasya ca svakalkasaindhavayutāḥ pakvāśayaviśodhanāḥ" },
      { type: "verse", number: "28", sanskrit: "घातकीपुष्पतर्कारीजीवन्तीमूलवत्सकाः प्रग्रहः खदिरः कुष्ठं शमी पिण्डीतको यवाः", text: "ghātakīpuṣpatarkārījīvantīmūlavatsakāḥ pragrahaḥ khadiraḥ kuṣṭhaṃ śamī piṇḍītako yavāḥ" },
      { type: "verse", number: "29", sanskrit: "प्रियङ्गुरर्कमूली च तरुणीजातियूथिकाः वटाद्याः किंशुकं लोध्रमिति सङ्ग्राहिका मताः", text: "priyaṅgurarkamūlī ca taruṇījātiyūthikāḥ vaṭādyāḥ kiṃśukaṃ lodhramiti saṅgrāhikā matāḥ" },
      { type: "verse", number: "30", sanskrit: "ग्राही प्रियङ्ग्वम्बष्ठादिक्वाथकल्कैः क्रमेण च ऊषकादिप्रतीवापो लेखनस्त्रिफलारसः मधुरक्वाथकल्केन सरसाज्येन बृंहणः", text: "grāhī priyaṅgvambaṣṭhādikvāthakalkaiḥ krameṇa ca ūṣakādipratīvāpo lekhanastriphalārasaḥ madhurakvāthakalkena sarasājyena bṛṃhaṇaḥ" },
      { type: "verse", number: "31", sanskrit: "बदर्यैरावणीशेलुशाल्मलीधन्वनाङ्कुराः समाक्षिकाः क्षीरयुताः सासृजः पिच्छिलाः स्मृताः", text: "badaryairāvaṇīśeluśālmalīdhanvanāṅkurāḥ samākṣikāḥ kṣīrayutāḥ sāsṛjaḥ picchilāḥ smṛtāḥ" },
      { type: "verse", number: "32", sanskrit: "कोलङ्कतककाण्डेक्षुदर्भपोटेक्षुपालिभिः दाहघ्नः सघृतक्षीरो द्वितीयश्चन्दनादिभिः", text: "kolaṅkatakakāṇḍekṣudarbhapoṭekṣupālibhiḥ dāhaghnaḥ saghṛtakṣīro dvitīyaścandanādibhiḥ" },
      { type: "verse", number: "33", sanskrit: "मुष्टिः शाल्मलिवृन्तानां क्षीरसिद्धो घृतान्वितः हितः प्रवाहणे तद्वद्वृन्तैः शाल्मलकस्य च", text: "muṣṭiḥ śālmalivṛntānāṃ kṣīrasiddho ghṛtānvitaḥ hitaḥ pravāhaṇe tadvadvṛntaiḥ śālmalakasya ca" },
      { type: "verse", number: "34", sanskrit: "कर्बुदाराढकीनीपविदुलैः क्षीरसाधितैः परिकर्ते तथा वृन्तैः श्रीपर्णीकोविदारजैः", text: "karbudārāḍhakīnīpavidulaiḥ kṣīrasādhitaiḥ parikarte tathā vṛntaiḥ śrīparṇīkovidārajaiḥ" },
      { type: "verse", number: "35", sanskrit: "परिस्रवे पयः सिद्धं सवृश्चीवपुनर्नवम् आखुकर्णिकया तद्वत्तण्डुलीयकयुक्तया", text: "parisrave payaḥ siddhaṃ savṛścīvapunarnavam ākhukarṇikayā tadvattaṇḍulīyakayuktayā" },
      { type: "verse", number: "36", sanskrit: "अश्वावरोहकः काकनासाराजकशेरुकाः सिद्धाः क्षीरे ऽतियोगे स्युः क्षौद्राञ्जनघृतैर्युताः न्यग्रोधाद्यैश्चतुर्भिश्च विधिनापरः", text: "aśvāvarohakaḥ kākanāsārājakaśerukāḥ siddhāḥ kṣīre 'tiyoge syuḥ kṣaudrāñjanaghṛtairyutāḥ nyagrodhādyaiścaturbhiśca vidhināparaḥ" },
      { type: "verse", number: "37", sanskrit: "बृहती क्षीरकाकोली पृश्निपर्णी शतावरी काश्मर्यबदरीमूर्वास्तथोशीरप्रियङ्गवः", text: "bṛhatī kṣīrakākolī pṛśniparṇī śatāvarī kāśmaryabadarīmūrvāstathośīrapriyaṅgavaḥ" },
      { type: "verse", number: "38", sanskrit: "जीवादाने शृतौ क्षीरे द्वौ घृताञ्जनसंयुतौ बस्ती प्रदेयौ भिषजा शीतौ समधुशकरौ गोव्यजामहिषीक्षीरैर्जीवनीययुतैरपि", text: "jīvādāne śṛtau kṣīre dvau ghṛtāñjanasaṃyutau bastī pradeyau bhiṣajā śītau samadhuśakarau govyajāmahiṣīkṣīrairjīvanīyayutairapi" },
      { type: "verse", number: "39", sanskrit: "शशैणदक्षमार्जारमहिषाव्यजशोणितैः सद्यस्कैर्मृदितैर्बस्तिर्जीवादाने प्रशस्यते", text: "śaśaiṇadakṣamārjāramahiṣāvyajaśoṇitaiḥ sadyaskairmṛditairbastirjīvādāne praśasyate" },
      { type: "verse", number: "40", sanskrit: "अथेमान् सुकुमाराणां निरूहान् स्नेहनान् मृदून् कर्मणा विप्लुतानां च वक्ष्यामि प्रसृतैः पृथक्", text: "athemān sukumārāṇāṃ nirūhān snehanān mṛdūn karmaṇā viplutānāṃ ca vakṣyāmi prasṛtaiḥ pṛthak" },
      { type: "verse", number: "41", sanskrit: "क्षीरात् द्वौ प्रसृतौ कार्यै मधुतैलघृतात्त्रयः खजेन मथितो बस्तिर्वातघ्नो बलवर्णकृत्", text: "kṣīrāt dvau prasṛtau kāryai madhutailaghṛtāttrayaḥ khajena mathito bastirvātaghno balavarṇakṛt" },
      { type: "verse", number: "42", sanskrit: "एकैकः प्रसृतस्तैलप्रसन्नाक्षौद्रसर्पिषाम् बिल्वादिमूलक्वाथात् द्वौ कौलत्थाद्द्वौ स वातजित्", text: "ekaikaḥ prasṛtastailaprasannākṣaudrasarpiṣām bilvādimūlakvāthāt dvau kaulatthāddvau sa vātajit" },
      { type: "verse", number: "43", sanskrit: "पटोलनिम्बपूतीकरास्नासप्तच्छदाम्भसः प्रसृतः पृथगाज्याच्च बस्तिः सर्षपकल्कवान् सपञ्चतिक्तो ऽभिष्यन्दकृमिकुष्ठप्रमेहहा", text: "paṭolanimbapūtīkarāsnāsaptacchadāmbhasaḥ prasṛtaḥ pṛthagājyācca bastiḥ sarṣapakalkavān sapañcatikto 'bhiṣyandakṛmikuṣṭhapramehahā" },
      { type: "verse", number: "44", sanskrit: "विडङ्गत्रिफलाशिग्रुफलमुस्ताखुकर्णिजात् कषायात् प्रसृताः पञ्च तैलादेको विमथ्य तान् निरूहः कृमिहा वेल्लपिप्पलीकल्कयोजीतः", text: "viḍaṅgatriphalāśigruphalamustākhukarṇijāt kaṣāyāt prasṛtāḥ pañca tailādeko vimathya tān nirūhaḥ kṛmihā vellapippalīkalkayojītaḥ" },
      { type: "verse", number: "45", sanskrit: "पयस्येक्षुस्थिरारास्नाविदारीक्षौद्रसर्पिषाम् एकैकः प्रसृतो बस्तिः कृष्णाकल्को वृषत्वकृत्", text: "payasyekṣusthirārāsnāvidārīkṣaudrasarpiṣām ekaikaḥ prasṛto bastiḥ kṛṣṇākalko vṛṣatvakṛt" },
      { type: "verse", number: "46", sanskrit: "चत्वारस्तैलगोमूत्रदधिमण्डाम्लकाञ्जिकात् प्रसृताः सर्षपैः पिष्टैर्विट्सङ्गानाहभेदनः", text: "catvārastailagomūtradadhimaṇḍāmlakāñjikāt prasṛtāḥ sarṣapaiḥ piṣṭairviṭsaṅgānāhabhedanaḥ" },
      { type: "verse", number: "47", sanskrit: "श्वदंष्ट्राश्मभिदेरण्डक्वाथतैलसुरासवात् प्रसृताः पञ्च चपलाकौन्तीयष्ट्याह्वकल्कवान् बस्तिः कवोष्णः साहाने मूत्रकृच्छ्रे वरो मतः", text: "śvadaṃṣṭrāśmabhideraṇḍakvāthatailasurāsavāt prasṛtāḥ pañca capalākauntīyaṣṭyāhvakalkavān bastiḥ kavoṣṇaḥ sāhāne mūtrakṛcchre varo mataḥ" },
      { type: "verse", number: "48", sanskrit: "मृदुबस्तिजडीभूते तीक्ष्णो ऽन्यो बस्तिरिष्यते तीक्ष्णैर्विकर्षिते स्निग्धो मधुरः शिशिरो मृदुः", text: "mṛdubastijaḍībhūte tīkṣṇo 'nyo bastiriṣyate tīkṣṇairvikarṣite snigdho madhuraḥ śiśiro mṛduḥ" },
      { type: "verse", number: "49", sanskrit: "तीक्ष्णत्वं मूत्रबिल्वाग्निलवणक्षारसर्षपैः प्राप्तकालं विधातव्यं क्षीराज्याद्यैस्तु मार्दवम्", text: "tīkṣṇatvaṃ mūtrabilvāgnilavaṇakṣārasarṣapaiḥ prāptakālaṃ vidhātavyaṃ kṣīrājyādyaistu mārdavam" },
      { type: "verse", number: "50", sanskrit: "बलकालदोषरोगप्रकृतीः प्रविभज्य योजितो बस्तिः स्वः स्वैरौषधवर्गैः स्वान् स्वान् रोगान् निवतयति", text: "balakāladoṣarogaprakṛtīḥ pravibhajya yojito bastiḥ svaḥ svairauṣadhavargaiḥ svān svān rogān nivatayati" },
      { type: "verse", number: "51", sanskrit: "उष्णार्तानां शीतान् शीतार्ताना तथा सुखोष्णांश्च तद्योग्यौषधयुक्तान् बस्तीन् सन्तर्क्य युञ्जीत", text: "uṣṇārtānāṃ śītān śītārtānā tathā sukhoṣṇāṃśca tadyogyauṣadhayuktān bastīn santarkya yuñjīta" },
      { type: "verse", number: "52", sanskrit: "बस्तीन्न बृंहणीयान् दद्याद्व्याधिषु विशोधनीयेषु मेदस्विनो विशोध्या ये च नराः कुष्ठमेहार्ताः", text: "bastīnna bṛṃhaṇīyān dadyādvyādhiṣu viśodhanīyeṣu medasvino viśodhyā ye ca narāḥ kuṣṭhamehārtāḥ" },
      { type: "verse", number: "53", sanskrit: "न क्षीणक्षतदुर्बलमूर्छितकृशशुष्कशुद्धदेहानाम् दद्याद्विशोधनीयान् दोषनिबद्धायुषो य च", text: "na kṣīṇakṣatadurbalamūrchitakṛśaśuṣkaśuddhadehānām dadyādviśodhanīyān doṣanibaddhāyuṣo ya ca" },
    ],
  },
  {
    sthana: "Калпасиддхистхана",
    number: 5,
    lang: "sa",
    content: [
      { type: "heading", heading: "Нируха кальпа — деококционные клизмы" },
      { type: "text", text: "Глава 5 Калпасиддхистханы посвящена деококционные клизмы. Вагбхата систематизирует приготовление и применение очищающих средств." },
      { type: "verse", number: "1", sanskrit: "अथातः सिद्धबस्तिकल्पं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः सिद्धबस्तीन् प्रयुञ्जीत सर्वदा सर्वदेहिनाम् निर्व्यापदो बहुफलान् बलपुष्टिकरान् सुखान्", text: "athātaḥ siddhabastikalpaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ siddhabastīn prayuñjīta sarvadā sarvadehinām nirvyāpado bahuphalān balapuṣṭikarān sukhān" },
      { type: "verse", number: "2", sanskrit: "मधुतैले समे कर्षः सन्धवात् द्विपचुर्मिसिः एरण्डमूलक्वाथेन निरूहो माधुतैलिकः रसायनं प्रमेहार्शः कृमिगुल्मान्त्रवृद्धिनुत्", text: "madhutaile same karṣaḥ sandhavāt dvipacurmisiḥ eraṇḍamūlakvāthena nirūho mādhutailikaḥ rasāyanaṃ pramehārśaḥ kṛmigulmāntravṛddhinut" },
      { type: "verse", number: "3", sanskrit: "सयष्टिमधुकश्चैष चक्षुष्यो रक्तपित्तजित् यापनो घनकल्केन मधुतैलरसाज्यवान्", text: "sayaṣṭimadhukaścaiṣa cakṣuṣyo raktapittajit yāpano ghanakalkena madhutailarasājyavān" },
      { type: "verse", number: "4", sanskrit: "पायुजानूरुवृषणबस्तिमेहनशूलजित् प्रसृतांशैर्घृतक्षौद्रवसातैलैः प्रक्ल्पयेत् यापनं सैन्धवार्धाक्षहपुषार्धपलान्वितम्", text: "pāyujānūruvṛṣaṇabastimehanaśūlajit prasṛtāṃśairghṛtakṣaudravasātailaiḥ praklpayet yāpanaṃ saindhavārdhākṣahapuṣārdhapalānvitam" },
      { type: "verse", number: "5", sanskrit: "एरण्डमूलनिष्क्वाथो मधुतैलं ससैधवम् एष युक्तरथो बस्तिः सवचापिप्पलीफलः", text: "eraṇḍamūlaniṣkvātho madhutailaṃ sasaidhavam eṣa yuktaratho bastiḥ savacāpippalīphalaḥ" },
      { type: "verse", number: "6", sanskrit: "सक्वाथो मधुषड्ग्रन्थाशताह्वाहिङ्गुसैन्धवः सुरदारु च रास्ना च बस्तिर्दोषहरः शिवः", text: "sakvātho madhuṣaḍgranthāśatāhvāhiṅgusaindhavaḥ suradāru ca rāsnā ca bastirdoṣaharaḥ śivaḥ" },
      { type: "verse", number: "7", sanskrit: "पञ्चमूलस्य निष्क्वाथस्तैलं मागधिका मधु ससैन्धवः समधुकः सिद्धबस्तिरिति स्मृतः", text: "pañcamūlasya niṣkvāthastailaṃ māgadhikā madhu sasaindhavaḥ samadhukaḥ siddhabastiriti smṛtaḥ" },
      { type: "verse", number: "8", sanskrit: "द्विपञ्चमूलत्रिफलाफलबिल्वानि पाचयेत् गोमूत्रे तेन पिष्टैश्च पाठातोयदवत्सकैः", text: "dvipañcamūlatriphalāphalabilvāni pācayet gomūtre tena piṣṭaiśca pāṭhātoyadavatsakaiḥ" },
      { type: "verse", number: "9", sanskrit: "सफलैः क्षौद्रतैलाभ्यां क्षारेण लवणेन च युक्तो बस्तिः कफव्याधिपाण्डुरोगविषूचिषु शुक्रानिलविबन्धेषु बस्त्याटोपे च पूजितः", text: "saphalaiḥ kṣaudratailābhyāṃ kṣāreṇa lavaṇena ca yukto bastiḥ kaphavyādhipāṇḍurogaviṣūciṣu śukrānilavibandheṣu bastyāṭope ca pūjitaḥ" },
      { type: "verse", number: "10", sanskrit: "मुस्तापाठामृतैरण्डबलारास्नापुनर्नवम् मञ्जिष्ठारग्वधोशीरत्रायमाणाक्षरोहिणीः", text: "mustāpāṭhāmṛtairaṇḍabalārāsnāpunarnavam mañjiṣṭhāragvadhośīratrāyamāṇākṣarohiṇīḥ" },
      { type: "verse", number: "11", sanskrit: "कनीयः पञ्चमूलं च पालिकं मदनाष्टकम् जलाढके पचेत्तच्च पादशेषं परिस्रुतम्", text: "kanīyaḥ pañcamūlaṃ ca pālikaṃ madanāṣṭakam jalāḍhake pacettacca pādaśeṣaṃ parisrutam" },
      { type: "verse", number: "12", sanskrit: "क्षीरद्विप्रस्थसंयुक्तं क्षीरशेषं पुनः पचेत् सपादजाङ्गलरसः ससर्पिर्मधुसैन्धवः", text: "kṣīradviprasthasaṃyuktaṃ kṣīraśeṣaṃ punaḥ pacet sapādajāṅgalarasaḥ sasarpirmadhusaindhavaḥ" },
      { type: "verse", number: "13", sanskrit: "पिष्टैर्यष्टीमिसिश्यामाकलिङ्गकरसाञ्जनैः बस्तिः सुखोष्णो मांसाग्निबलशुक्रविवर्धनः", text: "piṣṭairyaṣṭīmisiśyāmākaliṅgakarasāñjanaiḥ bastiḥ sukhoṣṇo māṃsāgnibalaśukravivardhanaḥ" },
      { type: "verse", number: "14", sanskrit: "वातासृङ्मोहमेहार्शोगुल्मविण्मूत्रसङ्ग्रहम् विषमज्वरवीसर्पवर्ध्माध्मानप्रवाहिकाः", text: "vātāsṛṅmohamehārśogulmaviṇmūtrasaṅgraham viṣamajvaravīsarpavardhmādhmānapravāhikāḥ" },
      { type: "verse", number: "15", sanskrit: "वङ्क्षणोरुकटीकुक्षिमन्याश्रोत्रशिरोरुजः हन्यादसृग्दरोन्मादशोफकासाश्मकुण्डलान् चक्षुष्यः पुत्रदो राजा यापनानां रसायनम्", text: "vaṅkṣaṇorukaṭīkukṣimanyāśrotraśirorujaḥ hanyādasṛgdaronmādaśophakāsāśmakuṇḍalān cakṣuṣyaḥ putrado rājā yāpanānāṃ rasāyanam" },
      { type: "verse", number: "16", sanskrit: "पृथक् पलांशं विपचेत् पञ्चमूलमगोक्षुरम् क्षीराढके चतुर्थस्थं पिष्टैर्यष्ट्यादिभिर्युतम्", text: "pṛthak palāṃśaṃ vipacet pañcamūlamagokṣuram kṣīrāḍhake caturthasthaṃ piṣṭairyaṣṭyādibhiryutam" },
      { type: "verse", number: "17", sanskrit: "क्षौद्रतैलाज्यसिन्धूत्थयुक्तं बस्तिः सुपूजितः विशेषाद्बालवृद्धस्त्रीसुकुमारसुखात्मनाम्", text: "kṣaudratailājyasindhūtthayuktaṃ bastiḥ supūjitaḥ viśeṣādbālavṛddhastrīsukumārasukhātmanām" },
      { type: "verse", number: "18", sanskrit: "तद्वत् सहाचरबलासारिवादर्भसाधितम् क्षीरं बस्तिस्तथाभीरुगुडूचीबृहतीद्वयैः सिद्धं पयो मागधिकायष्टीमधुककल्कवत्", text: "tadvat sahācarabalāsārivādarbhasādhitam kṣīraṃ bastistathābhīruguḍūcībṛhatīdvayaiḥ siddhaṃ payo māgadhikāyaṣṭīmadhukakalkavat" },
      { type: "verse", number: "19", sanskrit: "पञ्चमूलं बृहत्यादि प्रतिद्रव्यं पलोन्मितम् द्विपलं शालिगोधूमयवमाषं सयष्टिकम्", text: "pañcamūlaṃ bṛhatyādi pratidravyaṃ palonmitam dvipalaṃ śāligodhūmayavamāṣaṃ sayaṣṭikam" },
      { type: "verse", number: "20", sanskrit: "तैः सिद्धं छागलं क्षीरं कुक्कुटाण्डरसः सिता साज्यक्षौद्रद्विलवणस्तैर्बस्तिः शुक्रकृत्परम् कल्पो ऽयं शिखिगोनर्दमत्स्याद्यण्डरसेष्वपि", text: "taiḥ siddhaṃ chāgalaṃ kṣīraṃ kukkuṭāṇḍarasaḥ sitā sājyakṣaudradvilavaṇastairbastiḥ śukrakṛtparam kalpo 'yaṃ śikhigonardamatsyādyaṇḍaraseṣvapi" },
      { type: "verse", number: "21", sanskrit: "रसः कुलीरमांसस्य चटकाण्डरसान्वितः सशर्कराघृतमधुर्बस्तिर्वृष्यतमो मतः", text: "rasaḥ kulīramāṃsasya caṭakāṇḍarasānvitaḥ saśarkarāghṛtamadhurbastirvṛṣyatamo mataḥ" },
      { type: "verse", number: "22", sanskrit: "बस्तसूकरजैर्मुष्कैः कुलीरचटकामिषैः सिद्धं पयो बस्तशुक्रमुच्चटेक्षुरकं मधु", text: "bastasūkarajairmuṣkaiḥ kulīracaṭakāmiṣaiḥ siddhaṃ payo bastaśukramuccaṭekṣurakaṃ madhu" },
      { type: "verse", number: "23", sanskrit: "तैर्घृताढ्यो ऽल्पलवणो बस्तिर्वृष्यतमः परम् सिद्धेन पयसा भोज्यमात्मगुप्तोच्चटेक्षुरैः", text: "tairghṛtāḍhyo 'lpalavaṇo bastirvṛṣyatamaḥ param siddhena payasā bhojyamātmaguptoccaṭekṣuraiḥ" },
      { type: "verse", number: "24", sanskrit: "अतो दशदशाहेन यस्तु बस्तीन् निषेवते वाजीव पुष्टः सवृषो गच्छति प्रमदाशतम् एते माक्षिकसंयुक्ताः कुर्वन्त्यतिवृषं नरम्", text: "ato daśadaśāhena yastu bastīn niṣevate vājīva puṣṭaḥ savṛṣo gacchati pramadāśatam ete mākṣikasaṃyuktāḥ kurvantyativṛṣaṃ naram" },
      { type: "verse", number: "25", sanskrit: "नातियोगं न चायोगं स्ताम्भिनस्ते च कुर्वते", text: "nātiyogaṃ na cāyogaṃ stāmbhinaste ca kurvate" },
      { type: "verse", number: "26", sanskrit: "निरूहा लेखनाः प्रायो बृंहणाः स्नेहबस्तयः यापनेषूभयं तस्मान्नेष्टं तेष्वनुवासनम्", text: "nirūhā lekhanāḥ prāyo bṛṃhaṇāḥ snehabastayaḥ yāpaneṣūbhayaṃ tasmānneṣṭaṃ teṣvanuvāsanam" },
      { type: "verse", number: "27", sanskrit: "मृदुत्वान्न निवर्तन्ते यस्य त्वेते प्रयोजिताः समूत्रैर्बस्तिभिस्तीक्ष्णैरास्थाप्यः क्षिप्रमेव सः", text: "mṛdutvānna nivartante yasya tvete prayojitāḥ samūtrairbastibhistīkṣṇairāsthāpyaḥ kṣiprameva saḥ" },
      { type: "verse", number: "28", sanskrit: "शोफाग्निनाशपाण्डुत्वशूलार्शःपरिकर्तिकाः स्युर्ज्वराश्चातिसाराश्च यापनात्यर्थसेवनात्", text: "śophāgnināśapāṇḍutvaśūlārśaḥparikartikāḥ syurjvarāścātisārāśca yāpanātyarthasevanāt" },
      { type: "verse", number: "29", sanskrit: "अरिष्टक्षारशीध्वाद्यैस्तत्रेष्टा दीपनी क्रिया युक्त्या तस्मान्निषेवेत यापनान् न प्रसङ्गतः", text: "ariṣṭakṣāraśīdhvādyaistatreṣṭā dīpanī kriyā yuktyā tasmānniṣeveta yāpanān na prasaṅgataḥ" },
      { type: "verse", number: "30", sanskrit: "मृद्वल्पौषधसंयोगात् पादहीनप्रमाणतः अल्पकालोपयोगाच्च तेषु निष्परिहारता", text: "mṛdvalpauṣadhasaṃyogāt pādahīnapramāṇataḥ alpakālopayogācca teṣu niṣparihāratā" },
      { type: "verse", number: "31", sanskrit: "द्रव्येषु यापनीयेषु सिद्धान् स्नेहान् पृथक् पृथक् बस्तीन् सर्वेषु वा युञ्ज्यात् परिहारविवर्जितान्", text: "dravyeṣu yāpanīyeṣu siddhān snehān pṛthak pṛthak bastīn sarveṣu vā yuñjyāt parihāravivarjitān" },
      { type: "verse", number: "32", sanskrit: "सहाचराभीरुबलारास्नागोक्षुरकात् पृथक् तुलां जलद्रोणशते पचेत् द्रोणावशेषिते", text: "sahācarābhīrubalārāsnāgokṣurakāt pṛthak tulāṃ jaladroṇaśate pacet droṇāvaśeṣite" },
      { type: "verse", number: "33", sanskrit: "पूतशीते बिसद्राक्षातवक्षीरीनिदिग्धिकाः महासहाक्षुद्रसहायष्टीमधुमधूलिकाः", text: "pūtaśīte bisadrākṣātavakṣīrīnidigdhikāḥ mahāsahākṣudrasahāyaṣṭīmadhumadhūlikāḥ" },
      { type: "verse", number: "34", sanskrit: "जीवकर्षभकोदीच्यमृणालोत्पलचन्दनम् खर्जूरतालमज्जात्मगुप्तामलकीकणाः", text: "jīvakarṣabhakodīcyamṛṇālotpalacandanam kharjūratālamajjātmaguptāmalakīkaṇāḥ" },
      { type: "verse", number: "35", sanskrit: "पटोलमेदात्वक्पत्रशीतपाक्योदनाह्वयाः कल्कीकृत्य क्षिपेत्तस्मिन् पृथक् च प्रस्थसम्मितम्", text: "paṭolamedātvakpatraśītapākyodanāhvayāḥ kalkīkṛtya kṣipettasmin pṛthak ca prasthasammitam" },
      { type: "verse", number: "36", sanskrit: "रसं वराहमहिषबस्तमुष्कोद्भवं तथा शिखिकुक्कुटहंसाण्डसम्भवं तैलसर्पिषी", text: "rasaṃ varāhamahiṣabastamuṣkodbhavaṃ tathā śikhikukkuṭahaṃsāṇḍasambhavaṃ tailasarpiṣī" },
      { type: "verse", number: "37", sanskrit: "धात्रीविदारीस्वरसं गव्यक्षीराढकद्वयम् ब्रह्मभेरीमृदङ्गादिनिनादैः साधितं च तत्", text: "dhātrīvidārīsvarasaṃ gavyakṣīrāḍhakadvayam brahmabherīmṛdaṅgādininādaiḥ sādhitaṃ ca tat" },
      { type: "verse", number: "38", sanskrit: "सितच्छत्रत्रकृतच्छायं सितवस्त्रावगुण्ठितम् आरोपितं गजस्कन्धे पूजयित्वा वृषध्वजम्", text: "sitacchatratrakṛtacchāyaṃ sitavastrāvaguṇṭhitam āropitaṃ gajaskandhe pūjayitvā vṛṣadhvajam" },
      { type: "verse", number: "39", sanskrit: "कृत्वा स्वस्त्ययनं दद्यात् स्नेहबस्तिमयन्त्रणम् प्राप्तस्तेनातिवृषतां श्रमयेद्वनिताशतम्", text: "kṛtvā svastyayanaṃ dadyāt snehabastimayantraṇam prāptastenātivṛṣatāṃ śramayedvanitāśatam" },
      { type: "verse", number: "40", sanskrit: "निर्वलीपलितः कान्तश्चिरजीवी भवेत् स च नष्टशुक्रक्षतक्षीणविषमज्वरिणां हितः व्यापन्नार्तवशुक्राणां पुत्रदाता रसायनम्", text: "nirvalīpalitaḥ kāntaścirajīvī bhavet sa ca naṣṭaśukrakṣatakṣīṇaviṣamajvariṇāṃ hitaḥ vyāpannārtavaśukrāṇāṃ putradātā rasāyanam" },
      { type: "verse", number: "41", sanskrit: "एवं च बस्तयो ऽन्ये ऽपि कल्प्याः पाक्याश्च नैकशः शतं वारान् सहस्रं वा पाचयेत् सम्भवे सति", text: "evaṃ ca bastayo 'nye 'pi kalpyāḥ pākyāśca naikaśaḥ śataṃ vārān sahasraṃ vā pācayet sambhave sati" },
      { type: "verse", number: "42", sanskrit: "दोषघ्नाः सपरीहारा वक्ष्यन्ते स्नेहबस्तयः", text: "doṣaghnāḥ saparīhārā vakṣyante snehabastayaḥ" },
      { type: "verse", number: "43", sanskrit: "दशमूलं बलां रास्नामश्वगन्धां पुनर्नवाम् गुडूच्यैरण्डपूतीकभार्ङ्गीवृषकरोहिषम्", text: "daśamūlaṃ balāṃ rāsnāmaśvagandhāṃ punarnavām guḍūcyairaṇḍapūtīkabhārṅgīvṛṣakarohiṣam" },
      { type: "verse", number: "44", sanskrit: "शतावरीं सहचरं काकनासां पलांशकम् यवमाषातसीकोलकुलत्थान् प्रसृतोन्मितान्", text: "śatāvarīṃ sahacaraṃ kākanāsāṃ palāṃśakam yavamāṣātasīkolakulatthān prasṛtonmitān" },
      { type: "verse", number: "45", sanskrit: "वहे विपाच्य तोयस्य द्रोणशेषेण तेन च पचेत्तैलाढकं पेष्यैर्जीवनीयैः पलोन्मितैः", text: "vahe vipācya toyasya droṇaśeṣeṇa tena ca pacettailāḍhakaṃ peṣyairjīvanīyaiḥ palonmitaiḥ" },
      { type: "verse", number: "46", sanskrit: "अनुवासनमित्येतत् सर्ववातविकारनुत् अनूपानां वसा तद्वज्जीवनीयोपसाधिता", text: "anuvāsanamityetat sarvavātavikāranut anūpānāṃ vasā tadvajjīvanīyopasādhitā" },
      { type: "verse", number: "47", sanskrit: "शताह्वायवबिल्वाम्लैस्तैलं सिद्धं समीरणे सैन्धवेनाग्निव्रणेन तप्तं चानिलजिद्धृतम्", text: "śatāhvāyavabilvāmlaistailaṃ siddhaṃ samīraṇe saindhavenāgnivraṇena taptaṃ cānilajiddhṛtam" },
      { type: "verse", number: "48", sanskrit: "जीवन्तीं मदनं मेदां श्रावणीं मधुकं बलाम् शताह्वर्षभकौ कृष्णां काकनासां शतावरीम्", text: "jīvantīṃ madanaṃ medāṃ śrāvaṇīṃ madhukaṃ balām śatāhvarṣabhakau kṛṣṇāṃ kākanāsāṃ śatāvarīm" },
      { type: "verse", number: "49", sanskrit: "स्वगुप्तां क्षीरकाकोलीं कर्कटाख्यां शठीं वचाम् पिष्ट्वा तैलं घृतं क्षीरे साधयेत चतुर्गुणे", text: "svaguptāṃ kṣīrakākolīṃ karkaṭākhyāṃ śaṭhīṃ vacām piṣṭvā tailaṃ ghṛtaṃ kṣīre sādhayeta caturguṇe" },
      { type: "verse", number: "50", sanskrit: "बृंहणं वातपित्तघ्नं बलशुक्राग्निवर्धनम् रजःशुक्रामयहरं पुत्रीयं चानुव सनम्", text: "bṛṃhaṇaṃ vātapittaghnaṃ balaśukrāgnivardhanam rajaḥśukrāmayaharaṃ putrīyaṃ cānuva sanam" },
      { type: "verse", number: "51", sanskrit: "शिशिरस्पर्शवीर्यैश्च पिष्टैः क्षीरे चतुर्गुणे तैलपादं घृतं सिद्धं पित्तघ्नमनुवासनम्", text: "śiśirasparśavīryaiśca piṣṭaiḥ kṣīre caturguṇe tailapādaṃ ghṛtaṃ siddhaṃ pittaghnamanuvāsanam" },
      { type: "verse", number: "52", sanskrit: "सैन्धवं मदनं कुष्ठं शताह्वा निचुलो वचा द्रीबेरं मधुकं भार्ङ्गी देवदारुसकट्फलम्", text: "saindhavaṃ madanaṃ kuṣṭhaṃ śatāhvā niculo vacā drīberaṃ madhukaṃ bhārṅgī devadārusakaṭphalam" },
      { type: "verse", number: "53", sanskrit: "नागरं पुष्करं मेदा चविका चित्रकः शठी विडङ्गातिविषे श्यामा हरेणुर्नीलिनी स्थिरा", text: "nāgaraṃ puṣkaraṃ medā cavikā citrakaḥ śaṭhī viḍaṅgātiviṣe śyāmā hareṇurnīlinī sthirā" },
      { type: "verse", number: "54", sanskrit: "बिल्वाजमोदचपला दन्ती रास्ना च तैः स्मैः साध्यमेरण्डतैलं वा तैलं वा कफरोगनुत्", text: "bilvājamodacapalā dantī rāsnā ca taiḥ smaiḥ sādhyameraṇḍatailaṃ vā tailaṃ vā kapharoganut" },
      { type: "verse", number: "55", sanskrit: "वर्ध्मोदावर्तगुल्मार्शःप्लीहमेहाढ्यमारुतान् आनाहमश्मरीं चाशु हन्यात्तदनुवासनम्", text: "vardhmodāvartagulmārśaḥplīhamehāḍhyamārutān ānāhamaśmarīṃ cāśu hanyāttadanuvāsanam" },
      { type: "verse", number: "56", sanskrit: "साधितं पञ्चमूलेन तैलं बिल्वादिनाथवा अन्वासनं श्लेष्महरं द्रव्यैर्वा कफघातिभिः फलैरष्टगुणे चाम्ले सिद्धमन्वासनं कफे", text: "sādhitaṃ pañcamūlena tailaṃ bilvādināthavā anvāsanaṃ śleṣmaharaṃ dravyairvā kaphaghātibhiḥ phalairaṣṭaguṇe cāmle siddhamanvāsanaṃ kaphe" },
      { type: "verse", number: "57", sanskrit: "शूलानाहे तु तद्युक्तो निरूहः पटुमूत्रवान् पृच्छति स्म मुनिमित्यथ धीमानग्निवेश इह किन्तु फलानाम् बस्तिकर्मणि हितं सततं स्यात् तं पुनर्वसुरिति प्रशशास", text: "śūlānāhe tu tadyukto nirūhaḥ paṭumūtravān pṛcchati sma munimityatha dhīmānagniveśa iha kintu phalānām bastikarmaṇi hitaṃ satataṃ syāt taṃ punarvasuriti praśaśāsa" },
      { type: "verse", number: "58", sanskrit: "इह कुष्ठहिता गरागरी हितमिक्ष्वाकुफलं प्रमेहिणाम् कुटजस्य फलं हृदामये प्रवरं कोशफलं तु पाण्डुषु", text: "iha kuṣṭhahitā garāgarī hitamikṣvākuphalaṃ pramehiṇām kuṭajasya phalaṃ hṛdāmaye pravaraṃ kośaphalaṃ tu pāṇḍuṣu" },
      { type: "verse", number: "59", sanskrit: "उदरे कृतवेधनं हितं मदनं सर्वगदाविरोधि च मधुरं सकषायतिक्तकं तदरूक्षं सकटूष्णपिच्छिलम्", text: "udare kṛtavedhanaṃ hitaṃ madanaṃ sarvagadāvirodhi ca madhuraṃ sakaṣāyatiktakaṃ tadarūkṣaṃ sakaṭūṣṇapicchilam" },
      { type: "verse", number: "60", sanskrit: "कफपित्तहृदाशुकारि यन्निरपायं पवनानुलोमि च प्रवरं तदतः फलादिषु स्मृतमास्थापनयोजनास्विति", text: "kaphapittahṛdāśukāri yannirapāyaṃ pavanānulomi ca pravaraṃ tadataḥ phalādiṣu smṛtamāsthāpanayojanāsviti" },
      { type: "verse", number: "61", sanskrit: "अथ मुनिवृषभे निगद्य वाक्यं स्थितवति विज्ञपयाम्बभूव भूयः इदमतिगहनं सहान्यशिष्यैरवनिगतो ऽञ्जलिमग्रतो निधाय", text: "atha munivṛṣabhe nigadya vākyaṃ sthitavati vijñapayāmbabhūva bhūyaḥ idamatigahanaṃ sahānyaśiṣyairavanigato 'ñjalimagrato nidhāya" },
      { type: "verse", number: "62", sanskrit: "चित्रकर्मगुणकृद्गुरुणोक्तो बस्तिरूर्ध्वमथ चैति न नाभेः शीघ्नमापतति चानु स देहात् सर्वतः कथमपोहति दोषान्", text: "citrakarmaguṇakṛdguruṇokto bastirūrdhvamatha caiti na nābheḥ śīghnamāpatati cānu sa dehāt sarvataḥ kathamapohati doṣān" },
      { type: "verse", number: "63", sanskrit: "ऊचे गुरुस्तिमितमारुतवश्यमेतत् देहस्य यद्बहिरुपाश्रितमन्तरे वा दुष्टस्य तस्य जनयन्ननुलोमतां तु बस्तिर्हिनस्ति विषमानपि रोगपूगान्", text: "ūce gurustimitamārutavaśyametat dehasya yadbahirupāśritamantare vā duṣṭasya tasya janayannanulomatāṃ tu bastirhinasti viṣamānapi rogapūgān" },
      { type: "verse", number: "64", sanskrit: "शाखागताः कोष्ठगताश्च रोगा मर्मोर्ध्वसर्वावयवाङ्गजाश्च ये सन्ति तेषां न तु कश्चिदन्यो वायोः परं जन्मनि हेतुरस्ति", text: "śākhāgatāḥ koṣṭhagatāśca rogā marmordhvasarvāvayavāṅgajāśca ye santi teṣāṃ na tu kaścidanyo vāyoḥ paraṃ janmani heturasti" },
      { type: "verse", number: "65", sanskrit: "विट्श्लेष्मपित्तादिमलाचयानां विक्षेपसंहारकरो हि वायुः तस्यातिवृद्धस्य शमाय नान्यद्बस्तेः समं भेषजमस्ति यस्मात्", text: "viṭśleṣmapittādimalācayānāṃ vikṣepasaṃhārakaro hi vāyuḥ tasyātivṛddhasya śamāya nānyadbasteḥ samaṃ bheṣajamasti yasmāt" },
      { type: "verse", number: "66", sanskrit: "शाम्यन्ति यत्नेन जिते ऽनिले च तदीरिताः पित्तकफादयो ऽपि तस्माच्चिकित्सार्धमिति ब्रुवन्ति सर्वां चिकित्सामपि बस्तिमेके", text: "śāmyanti yatnena jite 'nile ca tadīritāḥ pittakaphādayo 'pi tasmāccikitsārdhamiti bruvanti sarvāṃ cikitsāmapi bastimeke" },
      { type: "verse", number: "67", sanskrit: "यच्च पक्वाशस्थो ऽपि दोषानापादमस्तकम् वीर्येण बस्तिरादत्ते खस्थो ऽर्को भूरसानिव", text: "yacca pakvāśastho 'pi doṣānāpādamastakam vīryeṇa bastirādatte khastho 'rko bhūrasāniva" },
      { type: "verse", number: "68", sanskrit: "यत्तत्रौषधवीर्यं हि तदपानेन वायुना पर्याप्तमचिरादेव समानः प्रतिपद्यते", text: "yattatrauṣadhavīryaṃ hi tadapānena vāyunā paryāptamacirādeva samānaḥ pratipadyate" },
      { type: "verse", number: "69", sanskrit: "समानाद्दुत्तरंचैवं व्यानाद्याः पवनाः क्रमात् ते तृप्ताः प्रकृतिं याताः शरीरानुग्रहे स्थिताः", text: "samānādduttaraṃcaivaṃ vyānādyāḥ pavanāḥ kramāt te tṛptāḥ prakṛtiṃ yātāḥ śarīrānugrahe sthitāḥ" },
      { type: "verse", number: "70", sanskrit: "प्रसह्य पित्तश्लेष्माणौ यथास्थानं निवेश्य च सन्तर्पयन्ति परितः स्वान् स्वान् भूतगुणांस्तनौ", text: "prasahya pittaśleṣmāṇau yathāsthānaṃ niveśya ca santarpayanti paritaḥ svān svān bhūtaguṇāṃstanau" },
      { type: "verse", number: "71", sanskrit: "व्यानस्तिर्यगपानो ऽधः प्राणश्चोर्ध्वं प्रकर्षति यथास्वमेव नाडीभिर्हारिणीभिरिवोदकम्", text: "vyānastiryagapāno 'dhaḥ prāṇaścordhvaṃ prakarṣati yathāsvameva nāḍībhirhāriṇībhirivodakam" },
      { type: "verse", number: "72", sanskrit: "एवं वातैः सिराभिश्च वपुर्बस्तिः सुयोजितः व्याप्नुवत् प्रसभं हन्ति सकृछ्रानपि यक्ष्मणः", text: "evaṃ vātaiḥ sirābhiśca vapurbastiḥ suyojitaḥ vyāpnuvat prasabhaṃ hanti sakṛchrānapi yakṣmaṇaḥ" },
      { type: "verse", number: "73", sanskrit: "बस्तिस्तस्मात् सर्वकर्मप्रधानं सर्वातङ्कान् हन्ति निःशेषतश्च स्रोतांस्यन्तः शोधयित्वा च कुर्यादोजस्तेजः शुक्रमेधाग्निकीप्तिम्", text: "bastistasmāt sarvakarmapradhānaṃ sarvātaṅkān hanti niḥśeṣataśca srotāṃsyantaḥ śodhayitvā ca kuryādojastejaḥ śukramedhāgnikīptim" },
    ],
  },
  {
    sthana: "Калпасиддхистхана",
    number: 6,
    lang: "sa",
    content: [
      { type: "heading", heading: "Ануваса кальпа — масляные клизмы" },
      { type: "text", text: "Глава 6 Калпасиддхистханы посвящена масляные клизмы. Вагбхата систематизирует приготовление и применение очищающих средств." },
      { type: "verse", number: "1", sanskrit: "अथातो बस्तिव्यापत्सिद्धिं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bastivyāpatsiddhiṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "विबन्धगौरवाध्मानशिरोरुग्वाहनोर्ध्वगाः कुक्षिशूलाङ्गरुग्घिध्माहृत्पीडाकर्तनस्रवाः अयोगादतियोगाच्च बस्तेः स्युः षट्षडापदः", text: "vibandhagauravādhmānaśirorugvāhanordhvagāḥ kukṣiśūlāṅgarugghidhmāhṛtpīḍākartanasravāḥ ayogādatiyogācca basteḥ syuḥ ṣaṭṣaḍāpadaḥ" },
      { type: "verse", number: "3", sanskrit: "अस्निग्धस्विन्नदेहस्य गुरुकोष्ठस्य योजितः शीतो ऽल्पस्नेहलवणद्रव्यमात्रो घनो ऽपि वा", text: "asnigdhasvinnadehasya gurukoṣṭhasya yojitaḥ śīto 'lpasnehalavaṇadravyamātro ghano 'pi vā" },
      { type: "verse", number: "4", sanskrit: "बस्तिः सङ्क्षोभ्य तं दोषं दुर्बलत्वादनिर्हरन् करोति वातविण्मूत्रविबन्धमतिदारुणम्", text: "bastiḥ saṅkṣobhya taṃ doṣaṃ durbalatvādanirharan karoti vātaviṇmūtravibandhamatidāruṇam" },
      { type: "verse", number: "5", sanskrit: "नाभिबस्तिरुनां दाहं हृल्लेपं श्वयथुं गुदे कण्डूं गण्डानि वैवर्ण्यमरतिं वह्निमार्दवम्", text: "nābhibastirunāṃ dāhaṃ hṛllepaṃ śvayathuṃ gude kaṇḍūṃ gaṇḍāni vaivarṇyamaratiṃ vahnimārdavam" },
      { type: "verse", number: "6", sanskrit: "क्वाथद्वयं प्राग्विहितं मध्येदोषे ऽतिसारिणि उष्णस्य तस्मादेकस्य तत्र पानं प्रशस्यते फलवर्त्यस्तथा स्वेदाः कालं ज्ञात्वा विरेचनम्", text: "kvāthadvayaṃ prāgvihitaṃ madhyedoṣe 'tisāriṇi uṣṇasya tasmādekasya tatra pānaṃ praśasyate phalavartyastathā svedāḥ kālaṃ jñātvā virecanam" },
      { type: "verse", number: "7", sanskrit: "बिल्वमूलत्रिवृद्दारुयवकोलकुलत्थवान् सुराविण्मूत्रवान् बस्तिः सप्राक्पेष्यस्तमानयेत्", text: "bilvamūlatrivṛddāruyavakolakulatthavān surāviṇmūtravān bastiḥ saprākpeṣyastamānayet" },
      { type: "verse", number: "8", sanskrit: "सशेषामे निरूहेण मृदुना दोष ईरितः मूर्छयत्यनिलं मार्गं रुणद्ध्यग्निं हिनस्ति च", text: "saśeṣāme nirūheṇa mṛdunā doṣa īritaḥ mūrchayatyanilaṃ mārgaṃ ruṇaddhyagniṃ hinasti ca" },
      { type: "verse", number: "9", sanskrit: "गौरवक्लमहृच्छूलदाहसम्मोहवेष्टनम् ततः कुर्यादुपचरेत्तं रूक्षस्वेदपाचनैः", text: "gauravaklamahṛcchūladāhasammohaveṣṭanam tataḥ kuryādupacarettaṃ rūkṣasvedapācanaiḥ" },
      { type: "verse", number: "10", sanskrit: "पिप्पलीकत्तृणोशीरदारुमूर्वाशृतं जलम् पिबेत् सौवर्चलोन्मिश्रं दीपनं हृद्विशोधनम्", text: "pippalīkattṛṇośīradārumūrvāśṛtaṃ jalam pibet sauvarcalonmiśraṃ dīpanaṃ hṛdviśodhanam" },
      { type: "verse", number: "11", sanskrit: "वचानागरशठ्यो वा दधिमण्डेन मूर्छिताः पेयाः प्रसन्नया वा स्युररिष्टेनासवेन वा", text: "vacānāgaraśaṭhyo vā dadhimaṇḍena mūrchitāḥ peyāḥ prasannayā vā syurariṣṭenāsavena vā" },
      { type: "verse", number: "12", sanskrit: "दारुत्रिकटुकं पथ्यां पलाशं चित्रकं शठीम् पिष्ट्वा कुष्ठं च मूत्रेण पिबेत् क्षारांश्च दीपनान् बस्तिमस्य विदद्ध्याच्च समूत्रं दाशमूलिकम्", text: "dārutrikaṭukaṃ pathyāṃ palāśaṃ citrakaṃ śaṭhīm piṣṭvā kuṣṭhaṃ ca mūtreṇa pibet kṣārāṃśca dīpanān bastimasya vidaddhyācca samūtraṃ dāśamūlikam" },
      { type: "verse", number: "13", sanskrit: "युक्तो ऽल्पवीर्यो दोषाढ्ये रूक्षे क्रूराशये ऽथवा बस्तिर्दोषावृतो रूद्धमार्गो रुन्ध्यात् समीरणम्", text: "yukto 'lpavīryo doṣāḍhye rūkṣe krūrāśaye 'thavā bastirdoṣāvṛto rūddhamārgo rundhyāt samīraṇam" },
      { type: "verse", number: "14", sanskrit: "सविमार्गो ऽनिलः कुर्यादाध्मानं मर्मपीडनम् विदाहं गुदकोष्ठस्य मुष्कवङ्क्षणवेदनाम् रूणद्धि हृदयं शूलैरितश्चेतश्च धावति", text: "savimārgo 'nilaḥ kuryādādhmānaṃ marmapīḍanam vidāhaṃ gudakoṣṭhasya muṣkavaṅkṣaṇavedanām rūṇaddhi hṛdayaṃ śūlairitaścetaśca dhāvati" },
      { type: "verse", number: "15", sanskrit: "स्वभ्यक्तस्विन्नगात्रस्य तत्र वर्तिं प्रयोजयेत् बिल्वादिश्च निरूहः स्यात् पीलुसर्षपमूत्रवान् सरलामरदारुभ्यां साधितं चानुवासनम्", text: "svabhyaktasvinnagātrasya tatra vartiṃ prayojayet bilvādiśca nirūhaḥ syāt pīlusarṣapamūtravān saralāmaradārubhyāṃ sādhitaṃ cānuvāsanam" },
      { type: "verse", number: "16", sanskrit: "बहुदोषे ऽबले क्रूरकोष्ठे बस्तिस्तनुर्मृदुः शीतो ऽल्पश्चावृतो दोषैः प्रतिहन्ति समीरणम्", text: "bahudoṣe 'bale krūrakoṣṭhe bastistanurmṛduḥ śīto 'lpaścāvṛto doṣaiḥ pratihanti samīraṇam" },
      { type: "verse", number: "17", sanskrit: "ऊर्ध्वं सो ऽनुसरन् देहं कुर्याद्वायुः शिरोरुजम् ग्रीवास्तम्भं प्रतिश्यायं बाधिर्यं दृष्टिविभ्रमम्", text: "ūrdhvaṃ so 'nusaran dehaṃ kuryādvāyuḥ śirorujam grīvāstambhaṃ pratiśyāyaṃ bādhiryaṃ dṛṣṭivibhramam" },
      { type: "verse", number: "18", sanskrit: "तमुष्णतैललवणप्रदिग्धं स्विन्नमर्दितम् तीक्ष्णैर्धूमैः प्रधमनैर्नस्यैरास्यविरेचनैः विरेकैर्बस्तिभिश्चाशु योज्येदानुलोमिकैः", text: "tamuṣṇatailalavaṇapradigdhaṃ svinnamarditam tīkṣṇairdhūmaiḥ pradhamanairnasyairāsyavirecanaiḥ virekairbastibhiścāśu yojyedānulomikaiḥ" },
      { type: "verse", number: "19", sanskrit: "स्निग्धस्विन्ने महादोषे बस्तिर्मृद्वल्पभेषजः उत्क्लेश्याल्पं हरेद्दोषं जनयेच्च प्रवाहिकाम्", text: "snigdhasvinne mahādoṣe bastirmṛdvalpabheṣajaḥ utkleśyālpaṃ hareddoṣaṃ janayecca pravāhikām" },
      { type: "verse", number: "20", sanskrit: "शोफं बस्तावपाने च सदनं चोरुजङ्क्षयोः विबद्धमारुतो जन्तुरभीक्ष्णं स प्रवाहते", text: "śophaṃ bastāvapāne ca sadanaṃ corujaṅkṣayoḥ vibaddhamāruto janturabhīkṣṇaṃ sa pravāhate" },
      { type: "verse", number: "21", sanskrit: "स्वेदाभ्यङ्गनिरूहांश्च शोधनीयानुलोमिकान् विदध्याल्लङ्क्षयित्वा च वृत्तिं तस्य विरिक्तवत्", text: "svedābhyaṅganirūhāṃśca śodhanīyānulomikān vidadhyāllaṅkṣayitvā ca vṛttiṃ tasya viriktavat" },
      { type: "verse", number: "22", sanskrit: "कुर्वतो वेगसंरोधं पीडितो वातिमात्रया अस्निग्धलवणोष्णो वा बस्तिरल्पो ऽल्पभेषजः", text: "kurvato vegasaṃrodhaṃ pīḍito vātimātrayā asnigdhalavaṇoṣṇo vā bastiralpo 'lpabheṣajaḥ" },
      { type: "verse", number: "23", sanskrit: "मृदुर्वा मारुतेनोर्ध्वं विक्षिप्तो मुखनासिकात् निरेति मूर्छाहृल्लासतृड्दाहादीन् प्रवर्तयन्", text: "mṛdurvā mārutenordhvaṃ vikṣipto mukhanāsikāt nireti mūrchāhṛllāsatṛḍdāhādīn pravartayan" },
      { type: "verse", number: "24", sanskrit: "मूर्छाविकारं दृष्ट्वास्य सिञ्चेच्छीताम्बुना मुखम् वीजेदाक्लमनाशाच्च प्राणायामं च कारयेत्", text: "mūrchāvikāraṃ dṛṣṭvāsya siñcecchītāmbunā mukham vījedāklamanāśācca prāṇāyāmaṃ ca kārayet" },
      { type: "verse", number: "25", sanskrit: "पृष्ठपार्श्वोदरं मृद्यात् करैरुष्णैरधोमुखम् केशेषूत्क्षिप्य धुन्वीत भाययेद्व्यालदंष्ट्रिभिः शस्त्रोल्कारजपुरुषैर्बस्तिरेति तथा ह्यधः", text: "pṛṣṭhapārśvodaraṃ mṛdyāt karairuṣṇairadhomukham keśeṣūtkṣipya dhunvīta bhāyayedvyāladaṃṣṭribhiḥ śastrolkārajapuruṣairbastireti tathā hyadhaḥ" },
      { type: "verse", number: "26", sanskrit: "पाणिवस्त्रैर्गलापीडं कुर्यान्न म्रियते यथा प्राणोदाननिरोधाद्धि सुप्रसिद्धतरायनः अपानः पवनो बस्तिं तमाश्वेवापकर्षति", text: "pāṇivastrairgalāpīḍaṃ kuryānna mriyate yathā prāṇodānanirodhāddhi suprasiddhatarāyanaḥ apānaḥ pavano bastiṃ tamāśvevāpakarṣati" },
      { type: "verse", number: "27", sanskrit: "कुष्ठक्रमुककल्कं च पाययेदम्लसंयुतम् औष्ण्यात्तैक्ष्ण्यात् सरत्वाच्च बस्तिंतसोस्यानुलोमयेत् गोमूत्रेण त्रिवृत्पथ्याकल्कं वाधोनुलोमनम्", text: "kuṣṭhakramukakalkaṃ ca pāyayedamlasaṃyutam auṣṇyāttaikṣṇyāt saratvācca bastiṃtasosyānulomayet gomūtreṇa trivṛtpathyākalkaṃ vādhonulomanam" },
      { type: "verse", number: "28", sanskrit: "पक्वाशयस्थिते स्विन्ने निरूहो दाशमूलिकः यवकोलकुलत्थैश्च विधेयो मूत्रसाधितैः", text: "pakvāśayasthite svinne nirūho dāśamūlikaḥ yavakolakulatthaiśca vidheyo mūtrasādhitaiḥ" },
      { type: "verse", number: "29", sanskrit: "बस्तिर्गोमूत्रसिद्धैर्वा सामृतावंशपल्लवैः पूतीकरञ्जत्वक्पत्रशठीदेवाह्वरोहिषैः सतैलगुडसिन्धूत्थो विरेकौषधकल्कवान्", text: "bastirgomūtrasiddhairvā sāmṛtāvaṃśapallavaiḥ pūtīkarañjatvakpatraśaṭhīdevāhvarohiṣaiḥ satailaguḍasindhūttho virekauṣadhakalkavān" },
      { type: "verse", number: "30", sanskrit: "बिल्वादिपञ्चमूलेन सिद्धो बस्तिरुरःस्थिते शिरस्थे नावनं धूमः प्रच्छाद्यं सर्षपैः शिरः", text: "bilvādipañcamūlena siddho bastiruraḥsthite śirasthe nāvanaṃ dhūmaḥ pracchādyaṃ sarṣapaiḥ śiraḥ" },
      { type: "verse", number: "31", sanskrit: "बस्तिरत्युष्णतीक्ष्णाम्लघनो ऽति स्वेदितस्य वा अल्पदोषे मृदौ कोष्ठे प्रयुक्तो वा पुनः पुनः", text: "bastiratyuṣṇatīkṣṇāmlaghano 'ti sveditasya vā alpadoṣe mṛdau koṣṭhe prayukto vā punaḥ punaḥ" },
      { type: "verse", number: "32", sanskrit: "अतियोगत्वमापन्नः कुक्षिशूलकरो भवेत् विरेचनातियोगेन स तुल्याकृतिसाधनः", text: "atiyogatvamāpannaḥ kukṣiśūlakaro bhavet virecanātiyogena sa tulyākṛtisādhanaḥ" },
      { type: "verse", number: "33", sanskrit: "पृश्निपर्णीं स्थिरां पद्मं काश्मर्यं मधुकोत्पले पिष्ट्वा द्राक्षां मधूकं च क्षीरे तण्डुलधावने", text: "pṛśniparṇīṃ sthirāṃ padmaṃ kāśmaryaṃ madhukotpale piṣṭvā drākṣāṃ madhūkaṃ ca kṣīre taṇḍuladhāvane" },
      { type: "verse", number: "34", sanskrit: "द्राक्षायाः पक्कलोष्टस्य प्रसादे मधुकस्य वा विनीय सघृतं बस्तिं युञ्ज्याद्दाहे ऽतियोगजे", text: "drākṣāyāḥ pakkaloṣṭasya prasāde madhukasya vā vinīya saghṛtaṃ bastiṃ yuñjyāddāhe 'tiyogaje" },
      { type: "verse", number: "35", sanskrit: "स्नेहस्वेदैरसम्पाद्य गुरुतीक्ष्णो ऽतिमात्रकः दुःस्थिताय प्रणिहितो बस्तिर्दुःशोधिताय वा", text: "snehasvedairasampādya gurutīkṣṇo 'timātrakaḥ duḥsthitāya praṇihito bastirduḥśodhitāya vā" },
      { type: "verse", number: "36", sanskrit: "अतिप्रवृत्तो मरुतं कोपयेत् स विमार्गगः करोत्यङ्गरुजां जृम्भां स्तम्भं भेदं च पर्वणाम्", text: "atipravṛtto marutaṃ kopayet sa vimārgagaḥ karotyaṅgarujāṃ jṛmbhāṃ stambhaṃ bhedaṃ ca parvaṇām" },
      { type: "verse", number: "37", sanskrit: "तं तैललवणाभ्यक्तं स्वेदितं प्रस्तरादिभिः बिल्वकोलयवैरण्डवषार्भूबृहतीद्वयःइ", text: "taṃ tailalavaṇābhyaktaṃ sveditaṃ prastarādibhiḥ bilvakolayavairaṇḍavaṣārbhūbṛhatīdvayaḥi" },
      { type: "verse", number: "38", sanskrit: "आस्थापयेत् ससिन्धूत्थैर्जाङ्गलैराशितं रसैः तैलेनानिलजिद्द्रव्यविपक्वेनानुवासयेत्", text: "āsthāpayet sasindhūtthairjāṅgalairāśitaṃ rasaiḥ tailenānilajiddravyavipakvenānuvāsayet" },
      { type: "verse", number: "39", sanskrit: "मृदुकोष्ठे ऽबले बस्तिरतितीक्ष्णो ऽतिनिर्हरन् कुर्याद्धिध्मां हितं तत्र हिध्माघ्नं बृंहणं च यत्", text: "mṛdukoṣṭhe 'bale bastiratitīkṣṇo 'tinirharan kuryāddhidhmāṃ hitaṃ tatra hidhmāghnaṃ bṛṃhaṇaṃ ca yat" },
      { type: "verse", number: "40", sanskrit: "बलाबृहत्यादिवराकाश्मर्यफलसैन्धवैः सप्रसन्नारनालाम्लैस्तैलं पक्त्वानुवासयेत्", text: "balābṛhatyādivarākāśmaryaphalasaindhavaiḥ saprasannāranālāmlaistailaṃ paktvānuvāsayet" },
      { type: "verse", number: "41", sanskrit: "उष्णाम्बुनाक्षं पिप्पल्या दद्याल्लवणसंयुतम् धूमलेहरसक्षीरस्वेदांश्चान्नं च वातजित्", text: "uṣṇāmbunākṣaṃ pippalyā dadyāllavaṇasaṃyutam dhūmaleharasakṣīrasvedāṃścānnaṃ ca vātajit" },
      { type: "verse", number: "42", sanskrit: "अतितीक्ष्णः सवातो वा न वा सम्यक्प्रपीडितः घट्टयेद्धृदयं बस्तिस्तत्र काशकुशोत्कटैः", text: "atitīkṣṇaḥ savāto vā na vā samyakprapīḍitaḥ ghaṭṭayeddhṛdayaṃ bastistatra kāśakuśotkaṭaiḥ" },
      { type: "verse", number: "43", sanskrit: "स्यात् साम्ललवणस्कन्धकरीरबदरीनलैः शृतैर्बस्तिर्हितः सिद्धो वातघ्नैश्चानुवासनम्", text: "syāt sāmlalavaṇaskandhakarīrabadarīnalaiḥ śṛtairbastirhitaḥ siddho vātaghnaiścānuvāsanam" },
      { type: "verse", number: "44", sanskrit: "मृदुकोष्ठाल्पदोषस्य रूक्षतीक्ष्णातिमात्रकः हृत्वा बस्तिर्मलाञ्छीघ्रं वातपित्ते प्रकोपयेत्", text: "mṛdukoṣṭhālpadoṣasya rūkṣatīkṣṇātimātrakaḥ hṛtvā bastirmalāñchīghraṃ vātapitte prakopayet" },
      { type: "verse", number: "45", sanskrit: "नाभिबस्तिगुदांस्ते हि कृन्ततो ऽस्य मुहुर्मुहुः विवर्णाल्पाल्पमुत्थानं बस्तिनिर्लेखनाद्भवेत्", text: "nābhibastigudāṃste hi kṛntato 'sya muhurmuhuḥ vivarṇālpālpamutthānaṃ bastinirlekhanādbhavet" },
      { type: "verse", number: "46", sanskrit: "स्वादुशीतौषधैस्तत्र पयस्येक्ष्वादिभिः शृतः यष्ठ्याह्वतिलकल्केन बस्तिःस्यात् क्षीरभोजिनः", text: "svāduśītauṣadhaistatra payasyekṣvādibhiḥ śṛtaḥ yaṣṭhyāhvatilakalkena bastiḥsyāt kṣīrabhojinaḥ" },
      { type: "verse", number: "47", sanskrit: "ससर्जरसयष्ट्याह्वं जिङ्गणीकर्दमाञ्जनम् विनीय दुग्धे बस्तिः स्याद्व्यक्ताम्लरसभोजिनः पिच्छिलश्च हितो बस्तिः स्नेहश्च मधुरैः शृतः", text: "sasarjarasayaṣṭyāhvaṃ jiṅgaṇīkardamāñjanam vinīya dugdhe bastiḥ syādvyaktāmlarasabhojinaḥ picchilaśca hito bastiḥ snehaśca madhuraiḥ śṛtaḥ" },
      { type: "verse", number: "48", sanskrit: "बस्तिःक्षाराम्लतीक्ष्णोष्णलवणः पैत्तिकस्य वा गुदं लिखन् दहन् क्षिण्वन् करोत्यस्रपरिस्रवम्", text: "bastiḥkṣārāmlatīkṣṇoṣṇalavaṇaḥ paittikasya vā gudaṃ likhan dahan kṣiṇvan karotyasraparisravam" },
      { type: "verse", number: "49", sanskrit: "स विदग्धं स्रवत्यस्रं वर्णैः पित्तं च भूरिभिः बहुशश्चातियोगेन मोहं गच्छति चासकृत्", text: "sa vidagdhaṃ sravatyasraṃ varṇaiḥ pittaṃ ca bhūribhiḥ bahuśaścātiyogena mohaṃ gacchati cāsakṛt" },
      { type: "verse", number: "50", sanskrit: "तत्रार्द्रैः शाल्मलीपत्रैः क्षुणैराजं पयः शृतम् पूतं घृतान्वितं बस्तिं दद्यादन्यांश्च पिच्छिलान्", text: "tatrārdraiḥ śālmalīpatraiḥ kṣuṇairājaṃ payaḥ śṛtam pūtaṃ ghṛtānvitaṃ bastiṃ dadyādanyāṃśca picchilān" },
      { type: "verse", number: "51", sanskrit: "वटादिपल्लवेष्वेवं कल्पो यवतिलेषु च सुवर्चलोपोदकयोः कच्छुदारे च शस्यते", text: "vaṭādipallaveṣvevaṃ kalpo yavatileṣu ca suvarcalopodakayoḥ kacchudāre ca śasyate" },
      { type: "verse", number: "52", sanskrit: "गुदे च शीतमधुरान् कुर्यात् सेकप्रलेपनान् रक्तपित्तातिसारघ्नी क्रिया चात्र प्रशस्यते", text: "gude ca śītamadhurān kuryāt sekapralepanān raktapittātisāraghnī kriyā cātra praśasyate" },
      { type: "verse", number: "53", sanskrit: "दाहादिषु त्रिवृत्कल्कं मृद्वीकावारिणा पिबेत् तद्धि पित्तशकृद्वातान् हत्वा दाहादिकान् जयेत्", text: "dāhādiṣu trivṛtkalkaṃ mṛdvīkāvāriṇā pibet taddhi pittaśakṛdvātān hatvā dāhādikān jayet" },
      { type: "verse", number: "54", sanskrit: "विशुद्धश्च पिबेच्छीतां यवागूं शर्करायुताम् युञ्ज्याद्वातिविरिक्तस्य क्षीणविट्कस्य भोजनम् माषयूषेण कुल्माषान् पानं दध्यथवा सुराम्", text: "viśuddhaśca pibecchītāṃ yavāgūṃ śarkarāyutām yuñjyādvātiviriktasya kṣīṇaviṭkasya bhojanam māṣayūṣeṇa kulmāṣān pānaṃ dadhyathavā surām" },
      { type: "verse", number: "55", sanskrit: "आमं यः कुणपं रुग्वानुपवेश्येत सारुचिः स घनातिविषाकुष्ठनतदारुवचाः पिबेत्", text: "āmaṃ yaḥ kuṇapaṃ rugvānupaveśyeta sāruciḥ sa ghanātiviṣākuṣṭhanatadāruvacāḥ pibet" },
      { type: "verse", number: "56", sanskrit: "शकृद्वातमसृक् पित्तं कफं वा यो ऽतिसार्यते पक्वं तत्र स्ववर्गीयो बस्तिः शेष्ठं भिषग्जितम्", text: "śakṛdvātamasṛk pittaṃ kaphaṃ vā yo 'tisāryate pakvaṃ tatra svavargīyo bastiḥ śeṣṭhaṃ bhiṣagjitam" },
      { type: "verse", number: "57", sanskrit: "षण्णामेषां द्विसंसर्गात्त्रिंशद्भेदा भवन्ति तु केवलैः सहषट्त्रिंशद्विद्यात् सोपद्रवांश्च तान्", text: "ṣaṇṇāmeṣāṃ dvisaṃsargāttriṃśadbhedā bhavanti tu kevalaiḥ sahaṣaṭtriṃśadvidyāt sopadravāṃśca tān" },
      { type: "verse", number: "58", sanskrit: "शूलप्रवाहिकाध्मानपरिकर्तारुचिज्वरान् तृण्मोहदाहमूर्छादींश्चैषां विद्यादुपद्रवान्", text: "śūlapravāhikādhmānaparikartārucijvarān tṛṇmohadāhamūrchādīṃścaiṣāṃ vidyādupadravān" },
      { type: "verse", number: "59", sanskrit: "तत्रामे ऽन्तरपानं तु कट्वम्ललवणैर्युतम् पाचनं शस्यते बस्तिरामे हि प्रतिषिध्यते", text: "tatrāme 'ntarapānaṃ tu kaṭvamlalavaṇairyutam pācanaṃ śasyate bastirāme hi pratiṣidhyate" },
      { type: "verse", number: "60", sanskrit: "वातघ्नग्राहिवर्गीयो बस्तिः शकृति शस्यते स्वाद्वम्लो व्यक्तलवणः स्नेहबस्तिः समीरणे", text: "vātaghnagrāhivargīyo bastiḥ śakṛti śasyate svādvamlo vyaktalavaṇaḥ snehabastiḥ samīraṇe" },
      { type: "verse", number: "61", sanskrit: "रक्ते रक्तेन पित्ते तु कषायस्वादुतिक्तकः सार्यमाणे कफे बस्तिः कषायकटुतिक्तकः", text: "rakte raktena pitte tu kaṣāyasvādutiktakaḥ sāryamāṇe kaphe bastiḥ kaṣāyakaṭutiktakaḥ" },
      { type: "verse", number: "62", sanskrit: "शकृता वायुना वामे तेन वर्चसि वानिले संसृष्टे ऽन्तरपानं स्यात् कट्वम्ललवणैर्युतम्", text: "śakṛtā vāyunā vāme tena varcasi vānile saṃsṛṣṭe 'ntarapānaṃ syāt kaṭvamlalavaṇairyutam" },
      { type: "verse", number: "63", sanskrit: "पित्तेनामे ऽसृजा तद्वत् तयोरामेन वा पुनः संसृष्टयोर्भवेत् पानं सकटुस्वादुतिक्तकम्", text: "pittenāme 'sṛjā tadvat tayorāmena vā punaḥ saṃsṛṣṭayorbhavet pānaṃ sakaṭusvādutiktakam" },
      { type: "verse", number: "64", sanskrit: "तथामे कफसंसृष्टे कषायकटुतिक्तकम् आमेन तु कफे युक्ते कषायलवणोषणम्", text: "tathāme kaphasaṃsṛṣṭe kaṣāyakaṭutiktakam āmena tu kaphe yukte kaṣāyalavaṇoṣaṇam" },
      { type: "verse", number: "65", sanskrit: "वातेन विशि पित्ते वा विट्पित्तास्रैस्तथानिले स्यात् कषायाम्लमधुरः संसृष्टे बस्तिरुत्तमः बस्तिर्वातेन रक्ते तु कार्यः स्वाद्वम्लतिक्तकः", text: "vātena viśi pitte vā viṭpittāsraistathānile syāt kaṣāyāmlamadhuraḥ saṃsṛṣṭe bastiruttamaḥ bastirvātena rakte tu kāryaḥ svādvamlatiktakaḥ" },
      { type: "verse", number: "66", sanskrit: "शकृच्छोणितयोः पित्तशकृतोरस्रपित्तयोः बस्तिरन्योन्यसंसर्गे कसायस्वादुतिक्तकः", text: "śakṛcchoṇitayoḥ pittaśakṛtorasrapittayoḥ bastiranyonyasaṃsarge kasāyasvādutiktakaḥ" },
      { type: "verse", number: "67", sanskrit: "कफेन विशि पित्ते वा कफे विट्पित्तयोः कटुतिक्तकषायः स्यात् संसृष्टे बस्तिरुत्तमः", text: "kaphena viśi pitte vā kaphe viṭpittayoḥ kaṭutiktakaṣāyaḥ syāt saṃsṛṣṭe bastiruttamaḥ" },
      { type: "verse", number: "68", sanskrit: "मधुरोषणतिक्तस्तु रक्ते कफविमूर्छिते मारुते कफसंसृष्टे कट्वम्ललवणो भवेत् स्याद्बस्तिः कटुतिक्ताम्लः संसृष्टे वायुना कफे", text: "madhuroṣaṇatiktastu rakte kaphavimūrchite mārute kaphasaṃsṛṣṭe kaṭvamlalavaṇo bhavet syādbastiḥ kaṭutiktāmlaḥ saṃsṛṣṭe vāyunā kaphe" },
      { type: "verse", number: "69", sanskrit: "त्रिचतुःपञ्चषड्योगानेवमेव विकल्पयेत् युक्तिश्चैषातिसारोक्ता सर्वरोगेष्वपि स्मृता", text: "tricatuḥpañcaṣaḍyogānevameva vikalpayet yuktiścaiṣātisāroktā sarvarogeṣvapi smṛtā" },
      { type: "verse", number: "70", sanskrit: "युगपत् षड्रसं षण्णां संसर्गे पाचनं भवेत् निरामाणां तु पञ्चानां बस्तिः षड्सिको हितः", text: "yugapat ṣaḍrasaṃ ṣaṇṇāṃ saṃsarge pācanaṃ bhavet nirāmāṇāṃ tu pañcānāṃ bastiḥ ṣaḍsiko hitaḥ" },
      { type: "verse", number: "71", sanskrit: "उदुम्बरशलाटूनि जम्ब्वाम्रोदुम्बरत्वचः शङ्खं सर्जरसं लाक्षां कत्तृणं च पलांशिकम्", text: "udumbaraśalāṭūni jambvāmrodumbaratvacaḥ śaṅkhaṃ sarjarasaṃ lākṣāṃ kattṛṇaṃ ca palāṃśikam" },
      { type: "verse", number: "72", sanskrit: "पिष्ट्वा तैः सर्पिषः प्रस्थं क्षीरद्विगुणितं पचेत् अतीसारेषु सर्वेषु पेयमेतद्यथाबलम्", text: "piṣṭvā taiḥ sarpiṣaḥ prasthaṃ kṣīradviguṇitaṃ pacet atīsāreṣu sarveṣu peyametadyathābalam" },
      { type: "verse", number: "73", sanskrit: "कच्छुराधातकीबिल्वसमङ्गारक्तमूलिभिः मसूराश्वत्थशुङ्गैश्च यवागूः स्याज्जले शृतैः", text: "kacchurādhātakībilvasamaṅgāraktamūlibhiḥ masūrāśvatthaśuṅgaiśca yavāgūḥ syājjale śṛtaiḥ" },
      { type: "verse", number: "74", sanskrit: "बालोदुम्बरकट्वङ्गसमग्गाप्लक्षपल्लवैः मसूरधातकीपुष्पबलाभिश्च तथा भवेत्", text: "bālodumbarakaṭvaṅgasamaggāplakṣapallavaiḥ masūradhātakīpuṣpabalābhiśca tathā bhavet" },
      { type: "verse", number: "75", sanskrit: "नानाप्रकारा जायन्ते व्यापदो बस्तिविभ्रमात् यथायथं यथावस्थं तासां कुर्वीत साधनम्", text: "nānāprakārā jāyante vyāpado bastivibhramāt yathāyathaṃ yathāvasthaṃ tāsāṃ kurvīta sādhanam" },
    ],
  },
  {
    sthana: "Калпасиддхистхана",
    number: 7,
    lang: "sa",
    content: [
      { type: "heading", heading: "Насья кальпа — назальные препараты" },
      { type: "text", text: "Глава 7 Калпасиддхистханы посвящена назальные препараты. Вагбхата систематизирует приготовление и применение очищающих средств." },
      { type: "verse", number: "1", sanskrit: "अथातः स्नेहादिव्यापत्सिद्धिं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ snehādivyāpatsiddhiṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "स्नेहबस्तौ मरुत्पित्तकफात्याशाविडावृते अभुक्ते शूनपाय्वामदत्ते ऽष्टौ व्यापदः स्मृताः", text: "snehabastau marutpittakaphātyāśāviḍāvṛte abhukte śūnapāyvāmadatte 'ṣṭau vyāpadaḥ smṛtāḥ" },
      { type: "verse", number: "3", sanskrit: "शीतो ऽल्पो वाधिके वाते पित्तेत्युष्णः कफे मृदुः अतिभुक्ते गुरुर्वर्चःसञ्चये ऽल्पबलस्तथा दत्तस्तैरावृतः स्नेहो नायात्यभिभवादपि", text: "śīto 'lpo vādhike vāte pittetyuṣṇaḥ kaphe mṛduḥ atibhukte gururvarcaḥsañcaye 'lpabalastathā dattastairāvṛtaḥ sneho nāyātyabhibhavādapi" },
      { type: "verse", number: "4", sanskrit: "स्तम्भोरुसदनाध्मानज्वरशूलाङ्गमर्दनैः पार्श्वरुग्वेष्टनैर्विद्याद्वायुना स्नेहमावृतम्", text: "stambhorusadanādhmānajvaraśūlāṅgamardanaiḥ pārśvarugveṣṭanairvidyādvāyunā snehamāvṛtam" },
      { type: "verse", number: "5", sanskrit: "स्निग्धाम्ललवणोष्णैस्तं रास्नापीतद्रुतैलिकैः सौवीरकसुराकोलकुलत्थयवसाधितैः", text: "snigdhāmlalavaṇoṣṇaistaṃ rāsnāpītadrutailikaiḥ sauvīrakasurākolakulatthayavasādhitaiḥ" },
      { type: "verse", number: "6", sanskrit: "निरूहैर्निर्हरेत् सम्यक् समूत्रैः पाञ्चमूलिकैः ताभ्यामेव च तैलाभ्यां सायं भुक्ते ऽनुवासयेत्", text: "nirūhairnirharet samyak samūtraiḥ pāñcamūlikaiḥ tābhyāmeva ca tailābhyāṃ sāyaṃ bhukte 'nuvāsayet" },
      { type: "verse", number: "7", sanskrit: "तृड्दाहरागसम्मोहवैवर्ण्यतमकज्वरैः विद्यात् पित्तावृतं स्वादुतिक्तैस्तं बस्तिभिर्हरेत्", text: "tṛḍdāharāgasammohavaivarṇyatamakajvaraiḥ vidyāt pittāvṛtaṃ svādutiktaistaṃ bastibhirharet" },
      { type: "verse", number: "8", sanskrit: "तन्द्राशीतज्वरालस्यप्रसेकारुचिगौरवैः समूर्छाग्लानिभिर्विद्याच्छ्लेष्मणा स्नेहमावृतम्", text: "tandrāśītajvarālasyaprasekārucigauravaiḥ samūrchāglānibhirvidyācchleṣmaṇā snehamāvṛtam" },
      { type: "verse", number: "9", sanskrit: "कषायतिक्तकटुकैः सुरामूत्रोपसाधितैः फलतैलयुतैः साम्लैर्बस्तिभिस्तं विनिर्हरेत्", text: "kaṣāyatiktakaṭukaiḥ surāmūtropasādhitaiḥ phalatailayutaiḥ sāmlairbastibhistaṃ vinirharet" },
      { type: "verse", number: "10", sanskrit: "छर्दिमूर्छारुचिग्लानिशूलनिद्राङ्गमर्दनैः आमलिङ्गैः सदाहैस्तं विद्यादत्यशनावृतम्", text: "chardimūrchāruciglāniśūlanidrāṅgamardanaiḥ āmaliṅgaiḥ sadāhaistaṃ vidyādatyaśanāvṛtam" },
      { type: "verse", number: "11", sanskrit: "कटूनां लवणानां च क्वाथैश्चूर्णैश्च पाचनम् मृदुर्विरेकः सर्वं च तत्रामविहितं हितम्", text: "kaṭūnāṃ lavaṇānāṃ ca kvāthaiścūrṇaiśca pācanam mṛdurvirekaḥ sarvaṃ ca tatrāmavihitaṃ hitam" },
      { type: "verse", number: "12", sanskrit: "विण्मूत्रानिलसङ्गार्तिगुरुत्वाध्मानहृद्ग्रहैः स्नेहं विडावृतं ज्ञात्वा स्नेहस्वेदैः सबस्तिभिः", text: "viṇmūtrānilasaṅgārtigurutvādhmānahṛdgrahaiḥ snehaṃ viḍāvṛtaṃ jñātvā snehasvedaiḥ sabastibhiḥ" },
      { type: "verse", number: "13", sanskrit: "श्यामाबिल्वादिसिद्धैश्च निरूहैः सानुवासनैः निर्हरेद्विधिना सम्यगुदावर्तहरेण च", text: "śyāmābilvādisiddhaiśca nirūhaiḥ sānuvāsanaiḥ nirharedvidhinā samyagudāvartahareṇa ca" },
      { type: "verse", number: "14", sanskrit: "अभुक्ते शूनपायोर्वा पेयामात्राशितस्य वा गुदे प्रणिहितः स्नेहो वेगाद्धावत्यनावृतः ऊर्ध्वकायं ततः कण्ठादूर्ध्वेभ्यः खेभ्य एत्यपि", text: "abhukte śūnapāyorvā peyāmātrāśitasya vā gude praṇihitaḥ sneho vegāddhāvatyanāvṛtaḥ ūrdhvakāyaṃ tataḥ kaṇṭhādūrdhvebhyaḥ khebhya etyapi" },
      { type: "verse", number: "15", sanskrit: "मूत्रश्यामात्रिवृत्सिद्धो यवकोलकुलत्थवान् तत्सिद्धतैलो देयः स्यान्निरूहः सानुवासनः", text: "mūtraśyāmātrivṛtsiddho yavakolakulatthavān tatsiddhatailo deyaḥ syānnirūhaḥ sānuvāsanaḥ" },
      { type: "verse", number: "16", sanskrit: "कण्ठादागच्छतः स्तम्भकण्ठग्रहविरेचनैः छर्दिघ्नीभिः क्रियाभिश्च तस्य कुर्यान्निवर्तनम्", text: "kaṇṭhādāgacchataḥ stambhakaṇṭhagrahavirecanaiḥ chardighnībhiḥ kriyābhiśca tasya kuryānnivartanam" },
      { type: "verse", number: "17", sanskrit: "नापक्वं प्रणयेत् स्नेहं गुदं स ह्युपलिम्पति ततः कुर्यात् सरुङ्मोहकण्डूशोफान् क्रियात्र च तीक्ष्णो बस्तिस्तथा तैलमर्कपत्ररसे शृतम्", text: "nāpakvaṃ praṇayet snehaṃ gudaṃ sa hyupalimpati tataḥ kuryāt saruṅmohakaṇḍūśophān kriyātra ca tīkṣṇo bastistathā tailamarkapatrarase śṛtam" },
      { type: "verse", number: "18", sanskrit: "ह्रस्वं दीर्घं तनु स्थूलं जीर्णं शिथिलबन्धनम् पार्श्वच्छिद्रं तथा वक्रमष्टौ नेत्राणि वर्जयेत्", text: "hrasvaṃ dīrghaṃ tanu sthūlaṃ jīrṇaṃ śithilabandhanam pārśvacchidraṃ tathā vakramaṣṭau netrāṇi varjayet" },
      { type: "verse", number: "19", sanskrit: "अप्राप्त्यतिगतिक्षोभकर्षणनस्रवाः गुडपीडा गतिर्जिह्मा तेषां दोषा यथाक्रमम्", text: "aprāptyatigatikṣobhakarṣaṇanasravāḥ guḍapīḍā gatirjihmā teṣāṃ doṣā yathākramam" },
      { type: "verse", number: "20", sanskrit: "मांसलस्निग्धविषमजालवत्स्थूलवातलः छिन्नः क्लिन्नश्च तानष्टौ बस्तीन् कर्मसु वर्जयेत्", text: "māṃsalasnigdhaviṣamajālavatsthūlavātalaḥ chinnaḥ klinnaśca tānaṣṭau bastīn karmasu varjayet" },
      { type: "verse", number: "21", sanskrit: "गतिवैषम्यदौर्गन्ध्यजिह्मत्वस्रुतिदुर्ग्रहाः फेनिलच्युत्यधार्यत्वं बस्तेः स्युर्बस्तिदोषतः", text: "gativaiṣamyadaurgandhyajihmatvasrutidurgrahāḥ phenilacyutyadhāryatvaṃ basteḥ syurbastidoṣataḥ" },
      { type: "verse", number: "22", sanskrit: "उच्चकैरत्यवाक्शीर्षं न्युब्जं सङ्कुचितं स्थितम् उत्तानं दक्षिणं पार्श्वं सप्त शय्याः परित्यजेत्", text: "uccakairatyavākśīrṣaṃ nyubjaṃ saṅkucitaṃ sthitam uttānaṃ dakṣiṇaṃ pārśvaṃ sapta śayyāḥ parityajet" },
      { type: "verse", number: "23", sanskrit: "मूत्राघातो ऽतिसम्प्राप्तिरप्राप्तिः साधुनागतिः आश्वागतिर्मरुत्कोपस्तृप्तिः पक्वाशयस्य च तद्दोषाः स्युर्विधातव्यं यथौपयिकमत्र च", text: "mūtrāghāto 'tisamprāptiraprāptiḥ sādhunāgatiḥ āśvāgatirmarutkopastṛptiḥ pakvāśayasya ca taddoṣāḥ syurvidhātavyaṃ yathaupayikamatra ca" },
      { type: "verse", number: "24", sanskrit: "सवातातिद्रुतोत्क्षिप्ततिर्यगुल्लुप्तकम्पिताः अतिमन्दकबाह्यातिवेगदोषाः प्रणेतृतः", text: "savātātidrutotkṣiptatiryagulluptakampitāḥ atimandakabāhyātivegadoṣāḥ praṇetṛtaḥ" },
      { type: "verse", number: "25", sanskrit: "अनुच्छ्रवास्य तु बद्धे वा दत्ते निःशेष एव वा प्रविश्य क्षुभितो वायुः शूलतोदकरो भवेत् तत्राभ्यङ्गो गुदे स्वेदो वातघ्नान्यशनानि च", text: "anucchravāsya tu baddhe vā datte niḥśeṣa eva vā praviśya kṣubhito vāyuḥ śūlatodakaro bhavet tatrābhyaṅgo gude svedo vātaghnānyaśanāni ca" },
      { type: "verse", number: "26", sanskrit: "द्रुतं प्रणीते निष्कृष्टे सहसोत्क्षिप्त एव वा स्यात् कटीगुदजङ्क्षोरुबस्तिस्तम्भार्तिभेदनम् भोजनं तत्र वातघ्नं स्वेदाभ्यङ्गाः सबस्तयः", text: "drutaṃ praṇīte niṣkṛṣṭe sahasotkṣipta eva vā syāt kaṭīgudajaṅkṣorubastistambhārtibhedanam bhojanaṃ tatra vātaghnaṃ svedābhyaṅgāḥ sabastayaḥ" },
      { type: "verse", number: "27", sanskrit: "तिर्यग्वल्यावृते द्वारे बद्धे वापि न गच्छति नेत्रे तदृजु निष्कृष्य संशोध्य च पुनर्नयेत्", text: "tiryagvalyāvṛte dvāre baddhe vāpi na gacchati netre tadṛju niṣkṛṣya saṃśodhya ca punarnayet" },
      { type: "verse", number: "28", sanskrit: "पीड्यमाने ऽन्तरामुक्ते गुदे प्रतिहतो ऽनिलः उरः शिरोरुजं सादमूर्वोश्च जनयेद्बली बस्तिःस्यात्तत्रबिल्वादिः फलश्यामादिमूत्रवान्", text: "pīḍyamāne 'ntarāmukte gude pratihato 'nilaḥ uraḥ śirorujaṃ sādamūrvośca janayedbalī bastiḥsyāttatrabilvādiḥ phalaśyāmādimūtravān" },
      { type: "verse", number: "29", sanskrit: "स्याद्दाहो दवथुः शोफः कम्पेनाभिहते गुदे कषायमधुराः शीताः सेकास्तत्र सबस्तयः", text: "syāddāho davathuḥ śophaḥ kampenābhihate gude kaṣāyamadhurāḥ śītāḥ sekāstatra sabastayaḥ" },
      { type: "verse", number: "30", sanskrit: "अतिमात्रप्रणीतेन नेत्रेण क्षणनाद्वलेः स्यात् सार्तिदाहनिस्तोदगुरुवर्चःप्रवर्तनम् तत्र सर्पिः पिचुः क्षीरं पिच्छाबस्तिश्च शस्यते", text: "atimātrapraṇītena netreṇa kṣaṇanādvaleḥ syāt sārtidāhanistodaguruvarcaḥpravartanam tatra sarpiḥ picuḥ kṣīraṃ picchābastiśca śasyate" },
      { type: "verse", number: "31", sanskrit: "न भावयति मन्दस्तु बाह्यश्चाशु निवर्तते स्नेहस्तत्र पुनः सम्यक् प्रणेयः सिद्धिमिच्छता", text: "na bhāvayati mandastu bāhyaścāśu nivartate snehastatra punaḥ samyak praṇeyaḥ siddhimicchatā" },
      { type: "verse", number: "32", sanskrit: "अतिप्रपीडितः कोष्ठे तिष्ठत्यायाति वा गलम् तत्र बस्तिर्विरेकश्च गलपीडादि कर्म च", text: "atiprapīḍitaḥ koṣṭhe tiṣṭhatyāyāti vā galam tatra bastirvirekaśca galapīḍādi karma ca" },
      { type: "verse", number: "33", sanskrit: "वमनाद्यैर्विशुद्धं च क्षामदेहबलानलम् यथाण्डं तरुणं पूर्णं तैलपात्रं यथा तथा भिषक् प्रयत्नतो रक्षेत् सर्वस्मादपचारतः", text: "vamanādyairviśuddhaṃ ca kṣāmadehabalānalam yathāṇḍaṃ taruṇaṃ pūrṇaṃ tailapātraṃ yathā tathā bhiṣak prayatnato rakṣet sarvasmādapacārataḥ" },
      { type: "verse", number: "34", sanskrit: "दद्यान्मधुरहृद्यानि ततो ऽम्ललवणौ रसौ स्वादुतिक्तौ ततो भूयः कषायकटुकौ ततः", text: "dadyānmadhurahṛdyāni tato 'mlalavaṇau rasau svādutiktau tato bhūyaḥ kaṣāyakaṭukau tataḥ" },
      { type: "verse", number: "35", sanskrit: "अन्योन्यप्रत्यनीकानां रसानां स्निग्धरूक्षयोः व्यत्यासादुपयोगेन क्रमात्तं प्रकृतिं नयेत् सर्वंसहः स्थिरबलो विज्ञेयः प्रकृतिं गतः", text: "anyonyapratyanīkānāṃ rasānāṃ snigdharūkṣayoḥ vyatyāsādupayogena kramāttaṃ prakṛtiṃ nayet sarvaṃsahaḥ sthirabalo vijñeyaḥ prakṛtiṃ gataḥ" },
      { type: "verse", number: "36", sanskrit: "अत्रान्तरे त्यजेदष्टौ भाष्यादीनि विशेषतः उच्चैर्भाष्याच्छिरोरोगतिमिरोरःस्वरव्यथाः", text: "atrāntare tyajedaṣṭau bhāṣyādīni viśeṣataḥ uccairbhāṣyācchirorogatimiroraḥsvaravyathāḥ" },
      { type: "verse", number: "37", sanskrit: "रक्तनिष्ठीवतमकज्वराद्यास्तत्र साधनम् अभ्यङ्गस्वेदनस्याधोभक्तस्नेहोपसेवनम् मौनं विधिर्वातहरो यथास्वं च विकारजित्", text: "raktaniṣṭhīvatamakajvarādyāstatra sādhanam abhyaṅgasvedanasyādhobhaktasnehopasevanam maunaṃ vidhirvātaharo yathāsvaṃ ca vikārajit" },
      { type: "verse", number: "38", sanskrit: "अत्यास्यायानयानाभ्यां सन्धिमूर्धत्रिकादिरुक् अतिचङ्क्रमणात् पादजङ्क्षोरुसदनादयः", text: "atyāsyāyānayānābhyāṃ sandhimūrdhatrikādiruk aticaṅkramaṇāt pādajaṅkṣorusadanādayaḥ" },
      { type: "verse", number: "39", sanskrit: "तेषां वातहरं सर्वं स्नेहस्वेदादि शस्यते अजीर्णभोजनादामविषच्छर्दिज्वरादयः", text: "teṣāṃ vātaharaṃ sarvaṃ snehasvedādi śasyate ajīrṇabhojanādāmaviṣacchardijvarādayaḥ" },
      { type: "verse", number: "40", sanskrit: "तत्र मात्राशितीयोक्तो विधेयो विधिरामहा अहितान्नाद्यथादोषं रोगाः स्युर्भेषजानि च", text: "tatra mātrāśitīyokto vidheyo vidhirāmahā ahitānnādyathādoṣaṃ rogāḥ syurbheṣajāni ca" },
      { type: "verse", number: "41", sanskrit: "हलीमकादयः प्रोक्ता दिवास्वप्नात् पुरा गदाः विदध्यात् कफजित्तेषु धूमरूक्षान्नलङ्क्षनम्", text: "halīmakādayaḥ proktā divāsvapnāt purā gadāḥ vidadhyāt kaphajitteṣu dhūmarūkṣānnalaṅkṣanam" },
      { type: "verse", number: "42", sanskrit: "व्यवायाज्जीवितभ्रंशस्तैस्तैरस्यानिलामयैः गुदो ऽवलुप्यत इव भ्रमतीव च चेतना", text: "vyavāyājjīvitabhraṃśastaistairasyānilāmayaiḥ gudo 'valupyata iva bhramatīva ca cetanā" },
      { type: "verse", number: "43", sanskrit: "मेढ्रं धूमायति मनस्तमसीव प्रवेश्यते जीवनीयशृतक्षीरसर्पिषोरुपसेवनम् आहारो बृंहणस्तत्र वृष्यास्ते ते च बस्तयः", text: "meḍhraṃ dhūmāyati manastamasīva praveśyate jīvanīyaśṛtakṣīrasarpiṣorupasevanam āhāro bṛṃhaṇastatra vṛṣyāste te ca bastayaḥ" },
      { type: "verse", number: "44", sanskrit: "वेगरोधोर्ध्ववातत्वात् प्रागुक्ता ये सदातुराः तेषां विबद्धे पवने सर्वदेहोपतापित्नि फलवर्तिं पुरा दद्यादथ बस्तिं चलापहम्", text: "vegarodhordhvavātatvāt prāguktā ye sadāturāḥ teṣāṃ vibaddhe pavane sarvadehopatāpitni phalavartiṃ purā dadyādatha bastiṃ calāpaham" },
      { type: "verse", number: "45", sanskrit: "निकुम्भकुम्भाग्न्युरुबूकधावनीपुनर्नवं दारु महच्च पञ्चकम् फलं च मूत्रे क्वथितं समस्तु तत् घृतं सतैलं लवणानि पञ्च च", text: "nikumbhakumbhāgnyurubūkadhāvanīpunarnavaṃ dāru mahacca pañcakam phalaṃ ca mūtre kvathitaṃ samastu tat ghṛtaṃ satailaṃ lavaṇāni pañca ca" },
      { type: "verse", number: "46", sanskrit: "निरूहितं धन्वरसेन भोजयेन्निकुम्भतैलेन ततो ऽनुवासयेत् बलां सरास्नां फलबिल्वचित्रकान् द्विपञ्चमूलं कृतमालकात् फलम्", text: "nirūhitaṃ dhanvarasena bhojayennikumbhatailena tato 'nuvāsayet balāṃ sarāsnāṃ phalabilvacitrakān dvipañcamūlaṃ kṛtamālakāt phalam" },
      { type: "verse", number: "47", sanskrit: "यवान् कुलत्थांश्च पचेज्जले रसः समुस्तपाठेन्द्रयवैश्च कल्कवान् सतैलसर्पिर्गुडसैन्धवो हितः सदातुराणां बलपुष्टिवर्णदः", text: "yavān kulatthāṃśca pacejjale rasaḥ samustapāṭhendrayavaiśca kalkavān satailasarpirguḍasaindhavo hitaḥ sadāturāṇāṃ balapuṣṭivarṇadaḥ" },
      { type: "verse", number: "48", sanskrit: "तथानुवास्यं मधुकेन साधितं फलेन बिल्वेन शताह्वयाथवा सजीवनीयस्तु रसो ऽनुवासने निरूहणे चालवणः शिशोर्हितः", text: "tathānuvāsyaṃ madhukena sādhitaṃ phalena bilvena śatāhvayāthavā sajīvanīyastu raso 'nuvāsane nirūhaṇe cālavaṇaḥ śiśorhitaḥ" },
      { type: "verse", number: "49", sanskrit: "निरूहबस्तेर्नैवान्यत् पथ्यं स्थविरबालयोः बलाङ्गवर्धनं शीघ्रमादृतो योजयेदतः", text: "nirūhabasternaivānyat pathyaṃ sthavirabālayoḥ balāṅgavardhanaṃ śīghramādṛto yojayedataḥ" },
    ],
  },
  {
    sthana: "Калпасиддхистхана",
    number: 8,
    lang: "sa",
    content: [
      { type: "heading", heading: "Снеха кальпа — масляные препараты" },
      { type: "text", text: "Глава 8 Калпасиддхистханы посвящена масляные препараты. Вагбхата систематизирует приготовление и применение очищающих средств." },
      { type: "verse", number: "1", sanskrit: "अथातो भेषजकल्पं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bheṣajakalpaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "जाङ्गले साधारणे वा देशे यथाकालं शिशिरातपपवनसलिलसेविते समे शुचौ प्रदक्षिणोदके श्मशानचैत्यदेवयजनागारसभाश्वभ्रारामवल्मीकोषरविरहिते कुशरोहिषास्तीर्णे स्निग्धकृष्णसुवर्णमधुरसुरभिमृत्तिके मृदावफालकृष्टेनुपहतेन्यैर्बल्वत्तरैर्द्रुमैर्भेषजानि प्रशस्यन्त इति सामान्यतो भूमिपरीक्षा", text: "jāṅgale sādhāraṇe vā deśe yathākālaṃ śiśirātapapavanasalilasevite same śucau pradakṣiṇodake śmaśānacaityadevayajanāgārasabhāśvabhrārāmavalmīkoṣaravirahite kuśarohiṣāstīrṇe snigdhakṛṣṇasuvarṇamadhurasurabhimṛttike mṛdāvaphālakṛṣṭenupahatenyairbalvattarairdrumairbheṣajāni praśasyanta iti sāmānyato bhūmiparīkṣā" },
      { type: "verse", number: "3", sanskrit: "विशेषतस्त्वश्मवती स्थिरा गुर्वी श्यामा कृष्णा स्थूलतृणवृक्षसस्यप्राया स्वगुणभूयिष्ठा स्निग्धा शीतलासन्नोदका स्निग्धतृणसस्यकोमलवृक्षप्राया शुक्लाचाम्बुगुणभूयिष्ठा नानावर्णलघ्वल्पपुष्पवती प्रविरलपाण्डुवृक्षप्ररोहाग्निगुणभूयिष्ठा रूक्षा रासभभस्मवर्णा रूक्षतनुकोटरवृक्षप्रायाल्परसप्ररोहानिलगुणभूयिष्ठा मृद्वी समा श्वभ्रवत्यव्यक्तरसजला महापर्वतवृक्षा श्यामा चाकाशगुणभूयिष्ठा तत्राम्बुपृथिवीगुणभूयिष्ठासु भूमिषु जातानि विरेचनानि बृंहणानि च शस्यन्ते अनलानिलाकाशगुणभूयिष्ठासु वमनानि सर्वगुणयुक्तासूभयतोभागानि आकाशगुणभूयिष्ठासु शमनानि एवं बलवत्तमानि भवन्ति", text: "viśeṣatastvaśmavatī sthirā gurvī śyāmā kṛṣṇā sthūlatṛṇavṛkṣasasyaprāyā svaguṇabhūyiṣṭhā snigdhā śītalāsannodakā snigdhatṛṇasasyakomalavṛkṣaprāyā śuklācāmbuguṇabhūyiṣṭhā nānāvarṇalaghvalpapuṣpavatī praviralapāṇḍuvṛkṣaprarohāgniguṇabhūyiṣṭhā rūkṣā rāsabhabhasmavarṇā rūkṣatanukoṭaravṛkṣaprāyālparasaprarohānilaguṇabhūyiṣṭhā mṛdvī samā śvabhravatyavyaktarasajalā mahāparvatavṛkṣā śyāmā cākāśaguṇabhūyiṣṭhā tatrāmbupṛthivīguṇabhūyiṣṭhāsu bhūmiṣu jātāni virecanāni bṛṃhaṇāni ca śasyante analānilākāśaguṇabhūyiṣṭhāsu vamanāni sarvaguṇayuktāsūbhayatobhāgāni ākāśaguṇabhūyiṣṭhāsu śamanāni evaṃ balavattamāni bhavanti" },
      { type: "verse", number: "4", sanskrit: "तत्र यानि कालजान्युपगतसम्पूर्णप्रमाणरसवीर्यगन्धानि कालातपाग्निसलिलपवनशस्त्रजन्तुभिरनुपहतगन्धवर्णरसस्पर्शप्रभावान्यवगाढमूलान्युदीच्यां दिशि स्थितानि तेषां शाखापलाशमचिरप्ररूढं वर्षावसन्तयोर्ग्राह्यम् ग्रीष्मे मूलानि शिशिरे वा शीर्णप्ररूढपर्णानाम् शरदि त्वक्कन्दक्षीराणि हेमन्ते साराणि यथर्तु पुष्पफलम्", text: "tatra yāni kālajānyupagatasampūrṇapramāṇarasavīryagandhāni kālātapāgnisalilapavanaśastrajantubhiranupahatagandhavarṇarasasparśaprabhāvānyavagāḍhamūlānyudīcyāṃ diśi sthitāni teṣāṃ śākhāpalāśamaciraprarūḍhaṃ varṣāvasantayorgrāhyam grīṣme mūlāni śiśire vā śīrṇaprarūḍhaparṇānām śaradi tvakkandakṣīrāṇi hemante sārāṇi yathartu puṣpaphalam" },
      { type: "verse", number: "5", sanskrit: "अन्ये पुनराहुः सौम्यान्यौषधानि सौम्येष्वृतुष्वाग्नेयान्याग्नेयेषु एवमव्यापन्नान्यापूर्णतररसवीर्याणि च भवन्ति", text: "anye punarāhuḥ saumyānyauṣadhāni saumyeṣvṛtuṣvāgneyānyāgneyeṣu evamavyāpannānyāpūrṇatararasavīryāṇi ca bhavanti" },
      { type: "verse", number: "6", sanskrit: "अथ मङ्गलाचारः कल्याणवृत्तः शुचिः शुक्लवासाः सम्पूज्य च देवतामश्विनौ गोब्राह्मणांश्च कृतोपवासः प्राङ्मुख उदङ्मुखो वा गृह्णीयात् गृहीत्वा चानुरूपगुणवद्भाजनसंस्थान्यगारेषु पूर्वोत्तरद्वारेषु निवातप्रवातैकदेशेषु नित्यपुष्पोपहारबलिकर्मवत्स्वग्निसलिलोपस्वेदधूमरजोमूषिकचतुष्पदामनभिगमनीयानि स्ववच्छन्नानि शिक्येष्वासज्य स्थापयेत्", text: "atha maṅgalācāraḥ kalyāṇavṛttaḥ śuciḥ śuklavāsāḥ sampūjya ca devatāmaśvinau gobrāhmaṇāṃśca kṛtopavāsaḥ prāṅmukha udaṅmukho vā gṛhṇīyāt gṛhītvā cānurūpaguṇavadbhājanasaṃsthānyagāreṣu pūrvottaradvāreṣu nivātapravātaikadeśeṣu nityapuṣpopahārabalikarmavatsvagnisalilopasvedadhūmarajomūṣikacatuṣpadāmanabhigamanīyāni svavacchannāni śikyeṣvāsajya sthāpayet" },
      { type: "verse", number: "7", sanskrit: "तानि सक्षीराण्युपकल्पयेत् तदसम्पत्तावनतिक्रान्तवत्सराणि पुराणानि तु पिप्पलीविडङ्गगुडमधुघृतानि", text: "tāni sakṣīrāṇyupakalpayet tadasampattāvanatikrāntavatsarāṇi purāṇāni tu pippalīviḍaṅgaguḍamadhughṛtāni" },
      { type: "verse", number: "8", sanskrit: "अपि च क्षीरं बाष्कयणं ग्राह्यं विण्मूत्रं तच्च नीरुजाम् वयोबलवतां धातुपिच्छशृङ्गखुरादिकम्", text: "api ca kṣīraṃ bāṣkayaṇaṃ grāhyaṃ viṇmūtraṃ tacca nīrujām vayobalavatāṃ dhātupicchaśṛṅgakhurādikam" },
      { type: "verse", number: "9", sanskrit: "पञ्चविधस्तु भेषजानां कषायकल्पः निर्यासः कल्को निर्यूहः शीतः फाण्टश्च ते यथापूर्वं बलिनः", text: "pañcavidhastu bheṣajānāṃ kaṣāyakalpaḥ niryāsaḥ kalko niryūhaḥ śītaḥ phāṇṭaśca te yathāpūrvaṃ balinaḥ" },
      { type: "verse", number: "10", sanskrit: "तत्र सद्यःसमुद्धृतप्रक्षालितक्षुण्णस्य तान्तवनिष्पीडितस्य स्वरसो निर्यासः उपलदशनादिपिष्टस्तु कल्कः शुष्कपिष्टः सूक्ष्मतान्तवपटच्युतश्चूर्णः तस्य समस्तद्रव्यापरित्यागादाप्लुतोपयोगाच्च कल्कादभेदः क्वाथो निर्यूहः", text: "tatra sadyaḥsamuddhṛtaprakṣālitakṣuṇṇasya tāntavaniṣpīḍitasya svaraso niryāsaḥ upaladaśanādipiṣṭastu kalkaḥ śuṣkapiṣṭaḥ sūkṣmatāntavapaṭacyutaścūrṇaḥ tasya samastadravyāparityāgādāplutopayogācca kalkādabhedaḥ kvātho niryūhaḥ" },
      { type: "verse", number: "11", sanskrit: "तत्र भेद्यान्यौषधान्यणुशो भेदयित्वा छेदयित्वा छेदयानि प्रक्षाल्योदकेन शुचौरूक्षायामधःप्रलिप्तायां ताम्रायोमृन्मयान्यतमायां स्थाल्यां समावाप्य बह्वल्पपानीयग्राहितामौषधानामाकलय्य यावता मुक्तरसता स्यात् तावदुदकमासेचयेच्छोषयेच्च अथाग्नावधिश्रित्य महत्यासने सुखोपविष्टः सर्वतः सततमवलोकयन् दर्व्यावघट्टयन् मृदुना परितः समुपगच्छतानलेन साधयेत् अवतार्य च परिस्रुतं यथार्हस्पर्शं प्रयुञ्जीत", text: "tatra bhedyānyauṣadhānyaṇuśo bhedayitvā chedayitvā chedayāni prakṣālyodakena śucaurūkṣāyāmadhaḥpraliptāyāṃ tāmrāyomṛnmayānyatamāyāṃ sthālyāṃ samāvāpya bahvalpapānīyagrāhitāmauṣadhānāmākalayya yāvatā muktarasatā syāt tāvadudakamāsecayecchoṣayecca athāgnāvadhiśritya mahatyāsane sukhopaviṣṭaḥ sarvataḥ satatamavalokayan darvyāvaghaṭṭayan mṛdunā paritaḥ samupagacchatānalena sādhayet avatārya ca parisrutaṃ yathārhasparśaṃ prayuñjīta" },
      { type: "verse", number: "12", sanskrit: "क्षीरादिसहितं च द्रव्यं न सम्यङ्मुक्तरसं भवतीति वारिक्वाथपूर्वकं क्षीराद्यैस्तदुपदेशे अनुपदग्धं क्वाथयेत्", text: "kṣīrādisahitaṃ ca dravyaṃ na samyaṅmuktarasaṃ bhavatīti vārikvāthapūrvakaṃ kṣīrādyaistadupadeśe anupadagdhaṃ kvāthayet" },
      { type: "verse", number: "13", sanskrit: "शीतसलिलाप्लुतस्तु निशापर्युषितपूतः शीतः उष्णाम्भसि क्षुण्णाभिषुतपूतः फाण्टः", text: "śītasalilāplutastu niśāparyuṣitapūtaḥ śītaḥ uṣṇāmbhasi kṣuṇṇābhiṣutapūtaḥ phāṇṭaḥ" },
      { type: "verse", number: "14", sanskrit: "तत्र सम्यग्रसवीर्यादीन्यौषधस्य समीक्ष्य व्याध्यातुरादिबलतश्च निर्यासादीनां कल्पनां मात्रां च संश्रयेत्", text: "tatra samyagrasavīryādīnyauṣadhasya samīkṣya vyādhyāturādibalataśca niryāsādīnāṃ kalpanāṃ mātrāṃ ca saṃśrayet" },
      { type: "verse", number: "15", sanskrit: "तथा च केचिदाहुः मात्राया न व्यवस्थास्ति व्याधिं कोष्ठं बलं वयः आलोच्य देशकालौ च योज्या तद्वच्च कल्पना", text: "tathā ca kecidāhuḥ mātrāyā na vyavasthāsti vyādhiṃ koṣṭhaṃ balaṃ vayaḥ ālocya deśakālau ca yojyā tadvacca kalpanā" },
      { type: "verse", number: "16", sanskrit: "इत्यलमेतदुपदिष्टं बुद्धिमतां ज्ञानप्रबोधाय यथा तु सर्वभिषजो विज्ञास्यन्ति तथोपदेक्ष्यते निर्यासस्य मध्यमा मात्रा चतुष्पलम् कल्कचूर्णयोः कर्षः पलत्रयं तदालोडने", text: "ityalametadupadiṣṭaṃ buddhimatāṃ jñānaprabodhāya yathā tu sarvabhiṣajo vijñāsyanti tathopadekṣyate niryāsasya madhyamā mātrā catuṣpalam kalkacūrṇayoḥ karṣaḥ palatrayaṃ tadāloḍane" },
      { type: "verse", number: "17", sanskrit: "निर्यूहे भेषजपलमुदकार्धप्रस्थे ऽधिश्रित्य पादशेषितमवतारयेत्", text: "niryūhe bheṣajapalamudakārdhaprasthe 'dhiśritya pādaśeṣitamavatārayet" },
      { type: "verse", number: "18", sanskrit: "शीतफाण्टयोरौषधपलं षट्चतुर्भिरम्बुपलैरासुतमिति", text: "śītaphāṇṭayorauṣadhapalaṃ ṣaṭcaturbhirambupalairāsutamiti" },
      { type: "verse", number: "19", sanskrit: "स्नेहपाके त्वनिर्दिष्टप्रमाणे समुदितस्य द्रवस्य पादेन स्नेहो योज्यस्तत्पादेन कल्कः", text: "snehapāke tvanirdiṣṭapramāṇe samuditasya dravasya pādena sneho yojyastatpādena kalkaḥ" },
      { type: "verse", number: "20", sanskrit: "अन्ये पुनः पठन्ति स्नेहपाके त्वमानोक्तौ चतुर्गुणविवर्धितम् कल्कस्नेहद्रवं योज्यमधीते शौनकः पुनः", text: "anye punaḥ paṭhanti snehapāke tvamānoktau caturguṇavivardhitam kalkasnehadravaṃ yojyamadhīte śaunakaḥ punaḥ" },
      { type: "verse", number: "21", sanskrit: "स्नेहे सिध्यति शुद्धाम्बुनिष्क्वाथस्वरसैः क्रमात् कल्कस्य योजयेदंशं चतुर्थं षष्ठमष्टमम्", text: "snehe sidhyati śuddhāmbuniṣkvāthasvarasaiḥ kramāt kalkasya yojayedaṃśaṃ caturthaṃ ṣaṣṭhamaṣṭamam" },
      { type: "verse", number: "22", sanskrit: "पञ्चप्रभृति तु द्रवं पृथक् स्नेहसममेवावपेत् अनिरूपितकल्पनं च भैषज्यं कल्कीकुर्यात् अथैकध्यं प्रतिसंसृज्याधिश्रित्य च निर्यूहवत्साधयेत्", text: "pañcaprabhṛti tu dravaṃ pṛthak snehasamamevāvapet anirūpitakalpanaṃ ca bhaiṣajyaṃ kalkīkuryāt athaikadhyaṃ pratisaṃsṛjyādhiśritya ca niryūhavatsādhayet" },
      { type: "verse", number: "23", sanskrit: "तत्र यदा विरमति शब्दः प्रसादमापद्यते स्नेहो यथास्वं वर्णगन्धरसोत्पत्तिर्भैषज्यमङ्गुलीभ्यां मृद्यमानमनतिमृद्वनतिदारुणमनङ्गुलिग्राहि च स्यात् स कालस्तस्यावतरणाय", text: "tatra yadā viramati śabdaḥ prasādamāpadyate sneho yathāsvaṃ varṇagandharasotpattirbhaiṣajyamaṅgulībhyāṃ mṛdyamānamanatimṛdvanatidāruṇamanaṅguligrāhi ca syāt sa kālastasyāvataraṇāya" },
      { type: "verse", number: "24", sanskrit: "अपि च घृतस्य फेनोपशमस्तैलस्य तु तदुद्भवः लेहस्य तन्तुमत्ताप्सु मज्जनं सरणं न च", text: "api ca ghṛtasya phenopaśamastailasya tu tadudbhavaḥ lehasya tantumattāpsu majjanaṃ saraṇaṃ na ca" },
      { type: "verse", number: "25", sanskrit: "अथावतार्य शीतीभूतमहतेन वाससा परिपूय शुचौ दृढे कलशे समासिच्यापिधानेन पिधाय शुक्लेन वस्त्रपट्टेनावच्छाद्य सूत्रेण सुबद्धं स्वनुगुप्तं शुचौ देशे सुस्थितं स्थापयेत्", text: "athāvatārya śītībhūtamahatena vāsasā paripūya śucau dṛḍhe kalaśe samāsicyāpidhānena pidhāya śuklena vastrapaṭṭenāvacchādya sūtreṇa subaddhaṃ svanuguptaṃ śucau deśe susthitaṃ sthāpayet" },
      { type: "verse", number: "26", sanskrit: "परिमाणं पुनः षड्वंश्यो मरीचिः ताः षट्सर्षपः ते ऽष्टौ तण्डुलः तौ धान्यमाषः तौ यवः अतः परं चतुर्गुणवृध्याण्डिकामाषकशाणकर्षपलकुडवप्रस्थाढकद्रोणवहाः कल्प्यन्ते धरणं तु पलस्य दशमो भागः माषकस्य पर्यायो हेमो धानकश्च शाणद्वयस्य पर्यायो द्रङ्क्षणः कोलो वटकश्र कर्षस्य सुवर्णमक्षं पिचुर्बिडालपदकं पाणितलं तिन्दुकं कवलग्रहः षोडशिका च कर्षद्वयस्य शुक्तिरष्टमिका च पलस्य मुष्टिः प्रकुञ्चश्चतुर्थिका बिल्वमाम्रं च पलद्वयस्य प्रसृतो ऽष्टमानं च कुडवस्याञ्जलिः कुडवद्वयस्य मानिका आढकस्य पात्रं कंसश्च द्रोणस्य नल्वणार्मणोन्मानघटकुम्भकलशाः द्रोणद्वयस्य शूर्पः तुला पुनः पलशतं तानि विंशतिर्भार इति भवति चात्र", text: "parimāṇaṃ punaḥ ṣaḍvaṃśyo marīciḥ tāḥ ṣaṭsarṣapaḥ te 'ṣṭau taṇḍulaḥ tau dhānyamāṣaḥ tau yavaḥ ataḥ paraṃ caturguṇavṛdhyāṇḍikāmāṣakaśāṇakarṣapalakuḍavaprasthāḍhakadroṇavahāḥ kalpyante dharaṇaṃ tu palasya daśamo bhāgaḥ māṣakasya paryāyo hemo dhānakaśca śāṇadvayasya paryāyo draṅkṣaṇaḥ kolo vaṭakaśra karṣasya suvarṇamakṣaṃ picurbiḍālapadakaṃ pāṇitalaṃ tindukaṃ kavalagrahaḥ ṣoḍaśikā ca karṣadvayasya śuktiraṣṭamikā ca palasya muṣṭiḥ prakuñcaścaturthikā bilvamāmraṃ ca paladvayasya prasṛto 'ṣṭamānaṃ ca kuḍavasyāñjaliḥ kuḍavadvayasya mānikā āḍhakasya pātraṃ kaṃsaśca droṇasya nalvaṇārmaṇonmānaghaṭakumbhakalaśāḥ droṇadvayasya śūrpaḥ tulā punaḥ palaśataṃ tāni viṃśatirbhāra iti bhavati cātra" },
      { type: "verse", number: "27", sanskrit: "शुष्कमेयेष्विदं मानं द्विगुणं तु द्रवार्द्रयोः", text: "śuṣkameyeṣvidaṃ mānaṃ dviguṇaṃ tu dravārdrayoḥ" },
      { type: "verse", number: "28", sanskrit: "पेषणालोडने वारि स्नेहपाके च निर्द्रवे", text: "peṣaṇāloḍane vāri snehapāke ca nirdrave" },
      { type: "verse", number: "29", sanskrit: "कल्पयेत्सदृशान् भागान् प्रमाणं यत्र नोदितम्", text: "kalpayetsadṛśān bhāgān pramāṇaṃ yatra noditam" },
      { type: "verse", number: "30", sanskrit: "अनिर्दिष्टाप्रसिद्धेषु मूलं ग्राह्यं त्वगादिषु", text: "anirdiṣṭāprasiddheṣu mūlaṃ grāhyaṃ tvagādiṣu" },
      { type: "verse", number: "31", sanskrit: "स्नेहपाकस्त्रिधा मन्दश्चिक्कणः खरचिक्कणः मन्दः कल्कसमे किट्टे चिक्कणो मदनोपमे", text: "snehapākastridhā mandaścikkaṇaḥ kharacikkaṇaḥ mandaḥ kalkasame kiṭṭe cikkaṇo madanopame" },
      { type: "verse", number: "32", sanskrit: "किञ्चित् सीदति कृष्णे च वर्त्यमाने तु पश्चिमः दग्धो ऽतौर्ध्वं निष्कार्यः स्यादामस्त्वग्निसादकृत् मृदुर्नस्ये खरो ऽभ्यङ्गे पाने बस्तौ च चिक्कणः", text: "kiñcit sīdati kṛṣṇe ca vartyamāne tu paścimaḥ dagdho 'taurdhvaṃ niṣkāryaḥ syādāmastvagnisādakṛt mṛdurnasye kharo 'bhyaṅge pāne bastau ca cikkaṇaḥ" },
      { type: "verse", number: "33", sanskrit: "हिमवद्विन्ध्यशैलाभ्यां प्रायो व्याप्ता वसुन्धरा सौम्यं पथ्यं च तत्राद्यमाग्नेयं वैन्ध्यमौषधम् परिभाषाः प्रवक्ष्यन्ते चिकित्सायां सुसंश्रिताः द्रव्याणि षोडशगुणे सलिले क्वाथयेत् भिषक् चतुर्थशेषः पूतस्तु कषायो ग्राह्य इष्यते अथ क्वाथ्येषु तेषूक्तं तोयादन्यत् द्रव भवेत् तच्चाम्बुवत् प्रयोक्तव्यं तत् षोडशगुणं ततः द्रवं यत्तत्र पठितं क्षीरं वा दधिमस्तु वा मूत्रं तक्रं सुरामण्डं यदि वाप्यम्लकाञ्जिकम् जलवत् षोडशगुणं तत् स्यात् पादावशेषितम् अनिर्दिष्टे प्रमाणे तु क्वाथ्यानां च द्रवस्य च कषायपाककल्पो ऽयं कृष्णात्रेयेण वर्णितः कर्तव्यं सति निर्देशे यथानिर्दिष्टमेव हि अस्यास्तु परिभाषायाः षडङ्गादावसम्भवात् तत्र प्रसिद्धिमाश्रित्य भेषजेषु जलेषु च तथा विधेया भागाः स्युर्व्याध्यादिसदृशा यथा तस्मादर्धपलं वापि कर्षन्नयमथापि वा द्रव्याणां स्यात् पलं वापि द्विप्रस्थमुदकस्य तु ततोधिकं वा कर्तव्यमूहापोहविशारदैः हीनं वापि ततः कार्यमेवं यूषे च पानके मांसौदनासवारिष्टपेयासु च वितर्कयेत् स्नेहादिसाधनायोक्तो निर्यूहो यत्र तत्र हि तत्रापि षोडशगुणः पक्षोयं परिगृह्यते द्रव्यं स्नेहसमं क्वाथ्यमत्र पक्षे प्रयुज्यते कषाय एव चेत्तत्र द्रवार्थं केवलो भवेत् तथान्यदपि तत्रोक्तं द्रवं क्षीरादिकं भवेत् ततोनुरूपं सङ्ख्याय द्रव्यं तोयेन साधयेत् द्रव्यं स्नेहसमं क्वाथ्यमन्यत्रापि द्रवे सति न तत्र युज्यते तस्मादनुरूपेण कल्पयेत् अन्येतु भिषजःप्राहुः क्वाथ्यान्यष्टगुणे ऽम्भसि क्वाथ्यं तु भवति स्नेहादत्र द्विगुणमौषधम् कषायेणैव चेत् साध्यः सत्यन्यस्मिन् द्रवे तथा साधयेदनुरूपेण केचिदेवं प्रचक्षते चतुर्गुणेन तोयेन क्वाथयेदौषधानि तु ऋषीणां सुश्रुतादीनां सर्वेषां मतमीदृशम् एतावांस्तु विशेषो ऽत्र शेषमात्रापि पूर्ववत् क्वाथ्यं तु भेषजं स्नेहादत्र पक्षे चतुर्गुणम् पलव्यपेक्षया द्रव्यादथ तोयं चतुर्गुणम् प्रस्थव्यपेक्षया द्रव्याद्यदा तोयं चतुर्गुणम् क्रियते द्विगुणं क्वाथ्यं ततः स्नेहात् प्रयुज्यते द्रवाणां द्विगुणं प्रस्थं शुष्कात् प्रस्थाद्यतो मतः प्रसिद्धिस्तु चिकित्सायां द्विधा हि भिषजामिह पलव्यपेक्सयाप्यस्ति तथा प्रस्थव्यपेक्षया सुश्रुतस्य तु यः पूर्वमुपन्यस्तश्चिरन्तनः पाठः पलव्यपेक्षायां ज्ञापकं तदुदाहृतम् इत्येवं त्रिविधः प्रोक्तः कषायग्रहणं प्रति एवमन्यत्र सर्वेषां कल्कात् स्नेहश्चतुर्गुणः चतुर्गुणं द्रवं स्नेहाद्यत्र यत् पठ्यते द्रवम् अनुक्ते तु द्रवे देयं जलमेव चतुर्गुणम् कल्ककल्पस्तु चरके कषायाणां न कीर्तितः स्नेहपाकविधिस्तूक्त एवं दृढबलेन तु चरको ऽर्धकृते शास्त्रे ब्रह्मभूयं गतो यतः कषायस्य तु पेयस्य यदि वा कल्कचूर्णयोः मात्रा दृढबलेनापि तत्रेति परिभाषिता चरकोक्तैर्मया वाक्यैरनुमानात् प्रसाधिता अनुक्तापि यथा मात्रा पञ्चाद्वक्ष्याम्यहं तथा एषां कषायकल्पानां प्रविभागो विधीयते कषायकल्पे त्रिविधे यश्चतुर्गुणितोदकः कषायकल्पः स्नेहेषु साध्येष्वेव समाश्रितः वैद्यैः प्रायेण न तथा यः षोडशगुणोदकः चतुर्गुणोदके पक्षे स्नेहाद्द्रव्यं चतुर्गुणम् अष्टाविंशं पलशतं क्वाथ्यद्रव्यस्य जायते स्नेहप्रस्थे विपक्तव्ये शुष्कं तच्च भवेद्यदि आर्द्रं चेदुद्धृतं सद्यस्ततः पलशतद्वयम् स्नेहप्रस्थे भवेत्साध्ये षट्पञ्चाशत् पलाधिकम् एवं बहुत्वात् द्रव्यस्य यश्चतुर्गुणितोदकः सकल्पो ऽभिमतस्तत्र स्नेहः स्याद्वीर्यवत्तरः सहस्रपाकाः स्नेहास्तु शतपाकाश्च कीर्तिताः सुभावितं स्वल्पमपि द्रव्यं तद्बहुकर्मकृत् तस्माद्बहुतरं द्रव्यं यत्र पक्षे प्रयुज्यते स्नेहपाकेषु सः श्रेयानित्येष तु मयाश्रितः स्नेहपाकविधावेव प्रयोगस्तस्य युज्यते पाचनाः शमनीयाश्च ये कषाया ज्वरादिषु उदीरिताः पुनस्तेषु कषायेषूपकल्प्यते चतुर्गुणादक पेयं कषायस्य पलं भवेत् तस्माद्द्रव्यपलं वैद्याः पाचनेषु प्रयुञ्जते मात्रां तु वैद्याः क्वाथस्य पाययन्ति चतुष्पलाम् क्रियमाणः प्रसिद्धो ऽयं पारम्पर्यागतो विधिः वाधितुं शक्यते नैव ज्ञापकं चात्र विद्यते पलं वत्सकबीजस्य श्रपयित्वा रसं पिबेत् आचार्यचरकेणैवमतिसारे तु भाषितम् पटोलाद्ये कषाये च क्वाथ्यद्रव्यपलं कृतम् चतुर्गुणेन तोयेन पचेद्द्रव्यपले सति चतुर्भागावशेषं तु पेयं क्वाथपलं भवेत् शास्त्रे कुष्ठे च मात्रा सा महती सम्प्रकाशिता चतुष्पला कषायस्य मात्रा या भिषजां मता पले चतुर्गुणजले सा मात्रा न प्रसिध्यति एवं सति च साध्यं स्याद्भेषजानां चतुष्पलम् चतुष्पलस्य द्रव्यस्य क्वथितस्य चतुर्गुणे तोये चतुर्थशेषस्य पेयः क्वाथश्चतुष्पलः भट्टारहरिचन्द्रेण खरणादे प्रकीर्तिता पातव्या षट्पला मात्रा तस्य द्रव्यपलानि षट् क्वाथानि संप्रयुज्यन्ते जलं द्रव्याच्चतुर्गुणम् पटोलाद्ये च तेनापि क्वाथ्यद्रव्यपलं कृतम् खरणादकृता मात्रा पेया तेनैव षट्पला परस्परविरुद्धं तत्तस्याप्येतत् प्रयुज्यते अप्रसिद्धो विधिश्चायं कषायस्य ज्वरादिषु न षट्पलानि क्वाथ्यन्ते न च तोयं चतुर्गुणम् चतुर्गुणोदका तस्मात् परिभाषा न युज्यते ज्वरादीनां कषायेषु स्नेहेष्वेव हि सा मता कृष्णात्रेयमुनिप्रोक्ता या षोडशगुणोदका ज्वरादिषु कषायाणां ग्रहणं क्रियते तया चतुर्गुणोदका यापि परिभाषोपदिश्यते तत्रापि हि विशेषो ऽयमन्यः कैश्चिदुपाश्रितः स्नेहेषु पलनिर्देशो येषु न विद्यते प्रस्थव्यपेक्षया चात्र सङ्ख्येयमुदकौषधम् पलव्यपेक्षया चापि समाचारो द्विधा अपि पूर्वं प्रस्थव्यपेक्षा या प्रोक्ता विज्ञापके सति द्रव्याणां पलनिर्देशो यत्रोक्तो मिश्रके तथा पलव्यपेक्षयैवात्र तोयमेवं चतुर्गुणम् प्रदेशान्तरनिर्देशाच्चरके ऽप्यनुमीयते कषायमात्रा पातव्या यद्यप्यपरिभाषिता स्वर्णक्षीर्यादिके योगे पाण्डुरोगचिकित्सिते पातव्या कथिता मात्रा गोमूत्रेण चतुष्पला रोहिणीकटुकादीनां पित्तगुल्मचिकित्सिते घृतं मुक्त्वा कषायस्य प्रोक्ता मात्रा चतुष्पला अतो ऽनुमानाच्चरके सिद्धा मात्रा चतुष्पला द्रव्याणां च पलं क्वाथ्यं पटोलाद्ये प्रकीर्तितम् पलं वत्सकबीजस्य निर्दिष्टं चातिसारिके तत् षोडशगुणे तोये यदि न क्वाथ्यते ततः चतुर्गुणोदके तोये पेयं क्वाथपलं भवेत् इत्येतत् षोडशगुणं तोयं यत्र प्रयुज्यते एषैव चरकस्यापि परिभाषानुमीयते पातव्येषु कषायेषु मुस्तपर्पटकादिषु विशेषः कथ्यते ऽन्यो ऽपि माने शुष्कद्रवाश्रये शुष्कद्रव्याश्रयं मानं निर्दिश्य यदुदाहृतम् द्रवेषु द्विगुणं मानं सद्यश्चैवोद्धृतेषु च द्विगुणं मानमित्येतदारभ्य कुडवादिति शुष्काणां च द्रवाणां च समं तु कुडवादधः तुलायामपि नैवेष्टा द्विगुणा मानकल्पना तुलापलशतं चैव तच्छ्रुष्कद्रवयोर्मतम् पलं चतुर्गुणं चेष्टं प्रसिद्धज्ञापकादिकम् सहाचरतुलायास्तु रसे तैलाढकं पचेत् यदुक्तं शतमेवात्र पलानां परिगृह्यते चतुःसुवर्णमेतच्च पलं नाष्टसुवर्णकम् द्रव्यस्य द्विगुणत्वे स्यात् पलमष्टसुवर्णकम् नैवाञ्जलौ न प्रसृते न पले न पलादधः द्रवाणामौषधानां हि द्विगुणं मानमिष्यते द्विगुणत्वे द्रवेषु स्यात् पलमष्टसुवणकम् तेनैषां द्विगुणत्वेन क्रियामार्गो विरुध्यते कुडवाद्यासु संज्ञासु द्रवाणां द्विगुणो विधिः विद्यते ज्ञापकं चात्र चरकाचार्यदर्शितम् स्पष्टार्थमेव पठितमिदं कुष्ठचिकित्सिते सलिलाढके ऽष्टभागे शेषे पूतो रसो ग्राह्यः ते च कषायाष्टपले चतुष्पलं सर्पिषश्च पक्तव्यम् यावत्स्यादष्टपलं शेषं पेयं ततः कोष्णमिति अष्टभागावशेषे तु पलानामष्टकद्वयम् पलस्य द्विगुणे माने क्रियमाणे न युज्यते द्विगुणे हि पले तत् स्यादेकमेव पलाष्टकम् चतुष्पलं च दातव्यं यत् प्रोक्तं सह सर्पिसा पलस्य द्विगुणे माने तदप्यष्टपलं भवेत् चतुःसुवर्णं हि पलं शुष्काणामिष्यते यतः द्विगुणत्वात् द्रवाणां हि तत् स्यादष्टसुवर्णकम् निरूहमात्रानिर्देश एवं सति च बाध्यते प्रसृतार्धं समारभ्य द्वादश प्रसृताः परम् एषा मात्रा द्विगुणिता द्विगुणे प्रसृते भवेत् निरूहमात्रा शास्त्रोक्ता द्वादशप्रसृतास्तथा चत्वारिंशत् पलानि स्युरष्टाभिरधिकानि च व्याध्यादिषु तु मध्येषु क्वाथस्याञ्जलिरिष्यते अत्र सुश्रुतनिदशे क्वाथो ऽयं द्विगुणो भवेत् स्वरसात् क्वथिताच्छीतात् कषायात् षट्पलं पिबेत् यदुक्तं खरणादेन तद्द्वादशपलं भवेत् पैत्तिके पठ्यते गुल्मे सर्पिषश्च चतुष्पलम् पिबेत् संमूर्छितं तेन गुल्मः शाम्यति पैत्तिकः चतुष्पलं घृतस्येदं मात्राप्यष्टपलं भवेत् स्वर्णक्षीर्यादिके योगे गोमूत्राञ्जलिरिष्यते अञ्जलेर्द्विगुणत्वाद्धि मात्रा साष्टपला भवेत् गौल्मिके त्रायमाणाद्ये घृते च परिपठ्यते रसस्यामलकेक्षूणां क्षीरस्य च घृतस्य च पलानि पृथगष्टाष्टौ कृत्वा सम्यग्विपाचयेत् अष्टौ प्रत्येकमेतानि स्युः षोडश पलानि तु तस्मादेवंप्रकारेषु निर्देशेषु विरुध्यते द्रवाणां द्विगुणं मानं तत्कार्यं कुडवादिषु आर्द्रेष्वपि न सर्वेषु सद्यस्तेषूद्घृतेषु च द्विगुणं मानमिच्छन्ति विशेषो ऽत्र च कल्प्यते शुष्काणि विनियुज्यन्ते दशमूलादिकानि हि तेष्वेव द्विगुणं मानं न सर्वेषूद्घृतेषु हि आर्द्राणामेव येषां तु प्रसिद्धिमुपकल्पयेत् वासाघृते वृषघृते तैले साहचरे तथा आर्द्राणां द्विगुणं मानमेवमादिषु नेष्यते आर्द्राणामेव तेषां हि प्रयोगः शस्यते यतः शतावरीमूलतुलाश्चतस्रो याः प्रकीर्तिताः नै तत्र द्विगुणं मानं भिषग्भिः कैश्चिदाश्रितम् वद्यबुद्धिविकासार्थमिदमन्यत् प्रकाश्यते क्वाथ्यानामौषधानां हि प्रमाणं यत्र नोदितम् चतुर्गुणं च निर्दिष्टमन्यत् क्षीरादिकं द्रवम् कषायो ऽप्यौषधानां हि तत्र कार्यश्चतुर्गुणः उदाहरणमत्रेष्टं महाकल्याणकं घृतम् एवमेवौषधानां हि प्रमाणं यत्र नोदितम् द्विगुणं चापि निर्दिष्टमन्यत् क्षीरादिकं द्रवम् कषायो ऽप्यौषधानां हि द्विगुणस्तत्र युज्यते वासादिकं ज्वरे प्रोक्तमत्रोदाहरणं स्मृतम् निर्दिष्टं क्षीरमन्यद्वा द्रवं यत्र चतुर्गुणम् क्वाथौषधानां मानं च प्रोक्तं नोक्तं जलस्य तु तत्रोषधिवशादेव सङ्ख्या क्वाथस्य गम्यते चतुर्गुणोदका तत्र परिभाषा यदीष्यते ततो द्रव्यसमस्तत्र कषायः परिकल्प्यते यदा तु परिभाषेष्टा या षोडशगुणोदका चतुर्थशेषः क्वाथः स्यात्ततो द्रव्याच्चतुर्गुणः अत्र साहचरं तैलमुदाहरणामिष्यते यत्रौषधं कषायो ऽपि द्रवं क्षीरादिकं त्रयम् प्रमाणं तु तथा नोक्तं स्नेहस्योक्तं न वा भवेत् तुल्यं क्वाथेन दातव्यं तत्र क्षीरादिकं द्रवम् कर्तव्यं च तथा तत् स्याद्यथा स्नेहाच्चतुर्गुणम् गौल्मिको मिश्रकस्नेह उदाहरणमत्र हि एवं वै द्विगुणे स्नेहात् त्रिगुणे च प्रकीर्तिते क्षीरादिके द्रवे कार्यं कषायग्रहणं तथा यथा कषायसहितं द्रवं स्यात्तच्चतुर्गुणम् अत्रोदाहरणं तत् स्याद्यथास्नेहाच्चतुर्गुणः कषायः पठ्यते यत्र प्रमाणं चास्य नोदितम् चतुर्गुणं वाप्यधिकं प्रोक्तं क्षीरादिकं द्रवम् तत्रापि च प्रयोक्तव्यं स्नेहात् क्वाथं चतुर्गुणम् पञ्चमूलकषायेण पिण्याकं बहुवार्षिकम् पठ्यते वातरोगे तदुदाहरणमत्र हि बहूनि यत्र पठ्यन्ते क्वचित् स्नेहे द्रवाणि हि बहूनामपि तेषां च परिमाणं न पठ्यते सर्वेषां समुदायः स्यात्तत्र स्नेहाच्चतुर्गुणः स्नेहपाकविधिं केचिदेवं समनुचक्षते बहुष्वेकैकमिच्छन्ति केचित्तत्र समं द्रवम् इत्येवं मतभेदात्तु यथा क्वाथविधौ तथा चतुर्गुणोदकः पक्षो यदा तत्र समाश्रितः बहुद्रव्यं किल स्नेहो वीर्यवाञ्छतपाकवत् अनयैवोपपत्या तु समुदायं चतुर्गुणम् नेच्छन्ति केचित् प्रत्येकमाहुः स्नेहसमं द्रवम् ग्रहणीरौगिके स्नेहे पञ्चमूलाभयादिके शुक्तेन मातुलुङ्गस्य स्वरसेनैवमादितः उदाहरणमत्रास्ति यो वाप्यन्यो बहुद्रवः श्लोकैरेषोणुतैलस्य कथ्यते पाकसंविधिः यस्य साधयितुं तैलं यावन्मात्रमभीप्सितम् तत्रौषधानि तावन्ति दत्वा तोयं चतुर्गुणम् कषायार्थं विपच्यन्ते यः कषायश्चतुर्गुणः यावन्मात्रस्य तैलस्य दद्यात् पादावशेषितम् यावन्मात्रमसौ तैलात् कषायो नावतार्यते चतुर्गुणो ऽत्र किं तर्हि पाक्याद्दशगुणः कृतः चतुर्गुणेन तोयेन प्राप्तानि परिभाषया क्वाथ्यानि यानि तान्यत्र पाक्याः शतगुणे जले क्वाथ्यन्ते परिभाषा तु शास्त्रवाक्येन बाधिता इत्येवमणुतैलस्य कर्तव्यं सम्प्रसाधनम् गद्योक्तो यः पुनः श्लोकैरर्थः समनुगीयते तद्व्यक्तिव्यवसायार्थं द्विरुक्तिः सा न गर्ह्यते प्रागुक्तो ऽपि मयार्थो यः श्लोकैस्तस्मात् प्रकाशितः ]", text: "himavadvindhyaśailābhyāṃ prāyo vyāptā vasundharā saumyaṃ pathyaṃ ca tatrādyamāgneyaṃ vaindhyamauṣadham paribhāṣāḥ pravakṣyante cikitsāyāṃ susaṃśritāḥ dravyāṇi ṣoḍaśaguṇe salile kvāthayet bhiṣak caturthaśeṣaḥ pūtastu kaṣāyo grāhya iṣyate atha kvāthyeṣu teṣūktaṃ toyādanyat drava bhavet taccāmbuvat prayoktavyaṃ tat ṣoḍaśaguṇaṃ tataḥ dravaṃ yattatra paṭhitaṃ kṣīraṃ vā dadhimastu vā mūtraṃ takraṃ surāmaṇḍaṃ yadi vāpyamlakāñjikam jalavat ṣoḍaśaguṇaṃ tat syāt pādāvaśeṣitam anirdiṣṭe pramāṇe tu kvāthyānāṃ ca dravasya ca kaṣāyapākakalpo 'yaṃ kṛṣṇātreyeṇa varṇitaḥ kartavyaṃ sati nirdeśe yathānirdiṣṭameva hi asyāstu paribhāṣāyāḥ ṣaḍaṅgādāvasambhavāt tatra prasiddhimāśritya bheṣajeṣu jaleṣu ca tathā vidheyā bhāgāḥ syurvyādhyādisadṛśā yathā tasmādardhapalaṃ vāpi karṣannayamathāpi vā dravyāṇāṃ syāt palaṃ vāpi dviprasthamudakasya tu tatodhikaṃ vā kartavyamūhāpohaviśāradaiḥ hīnaṃ vāpi tataḥ kāryamevaṃ yūṣe ca pānake māṃsaudanāsavāriṣṭapeyāsu ca vitarkayet snehādisādhanāyokto niryūho yatra tatra hi tatrāpi ṣoḍaśaguṇaḥ pakṣoyaṃ parigṛhyate dravyaṃ snehasamaṃ kvāthyamatra pakṣe prayujyate kaṣāya eva cettatra dravārthaṃ kevalo bhavet tathānyadapi tatroktaṃ dravaṃ kṣīrādikaṃ bhavet tatonurūpaṃ saṅkhyāya dravyaṃ toyena sādhayet dravyaṃ snehasamaṃ kvāthyamanyatrāpi drave sati na tatra yujyate tasmādanurūpeṇa kalpayet anyetu bhiṣajaḥprāhuḥ kvāthyānyaṣṭaguṇe 'mbhasi kvāthyaṃ tu bhavati snehādatra dviguṇamauṣadham kaṣāyeṇaiva cet sādhyaḥ satyanyasmin drave tathā sādhayedanurūpeṇa kecidevaṃ pracakṣate caturguṇena toyena kvāthayedauṣadhāni tu ṛṣīṇāṃ suśrutādīnāṃ sarveṣāṃ matamīdṛśam etāvāṃstu viśeṣo 'tra śeṣamātrāpi pūrvavat kvāthyaṃ tu bheṣajaṃ snehādatra pakṣe caturguṇam palavyapekṣayā dravyādatha toyaṃ caturguṇam prasthavyapekṣayā dravyādyadā toyaṃ caturguṇam kriyate dviguṇaṃ kvāthyaṃ tataḥ snehāt prayujyate dravāṇāṃ dviguṇaṃ prasthaṃ śuṣkāt prasthādyato mataḥ prasiddhistu cikitsāyāṃ dvidhā hi bhiṣajāmiha palavyapeksayāpyasti tathā prasthavyapekṣayā suśrutasya tu yaḥ pūrvamupanyastaścirantanaḥ pāṭhaḥ palavyapekṣāyāṃ jñāpakaṃ tadudāhṛtam ityevaṃ trividhaḥ proktaḥ kaṣāyagrahaṇaṃ prati evamanyatra sarveṣāṃ kalkāt snehaścaturguṇaḥ caturguṇaṃ dravaṃ snehādyatra yat paṭhyate dravam anukte tu drave deyaṃ jalameva caturguṇam kalkakalpastu carake kaṣāyāṇāṃ na kīrtitaḥ snehapākavidhistūkta evaṃ dṛḍhabalena tu carako 'rdhakṛte śāstre brahmabhūyaṃ gato yataḥ kaṣāyasya tu peyasya yadi vā kalkacūrṇayoḥ mātrā dṛḍhabalenāpi tatreti paribhāṣitā carakoktairmayā vākyairanumānāt prasādhitā anuktāpi yathā mātrā pañcādvakṣyāmyahaṃ tathā eṣāṃ kaṣāyakalpānāṃ pravibhāgo vidhīyate kaṣāyakalpe trividhe yaścaturguṇitodakaḥ kaṣāyakalpaḥ sneheṣu sādhyeṣveva samāśritaḥ vaidyaiḥ prāyeṇa na tathā yaḥ ṣoḍaśaguṇodakaḥ caturguṇodake pakṣe snehāddravyaṃ caturguṇam aṣṭāviṃśaṃ palaśataṃ kvāthyadravyasya jāyate snehaprasthe vipaktavye śuṣkaṃ tacca bhavedyadi ārdraṃ ceduddhṛtaṃ sadyastataḥ palaśatadvayam snehaprasthe bhavetsādhye ṣaṭpañcāśat palādhikam evaṃ bahutvāt dravyasya yaścaturguṇitodakaḥ sakalpo 'bhimatastatra snehaḥ syādvīryavattaraḥ sahasrapākāḥ snehāstu śatapākāśca kīrtitāḥ subhāvitaṃ svalpamapi dravyaṃ tadbahukarmakṛt tasmādbahutaraṃ dravyaṃ yatra pakṣe prayujyate snehapākeṣu saḥ śreyānityeṣa tu mayāśritaḥ snehapākavidhāveva prayogastasya yujyate pācanāḥ śamanīyāśca ye kaṣāyā jvarādiṣu udīritāḥ punasteṣu kaṣāyeṣūpakalpyate caturguṇādaka peyaṃ kaṣāyasya palaṃ bhavet tasmāddravyapalaṃ vaidyāḥ pācaneṣu prayuñjate mātrāṃ tu vaidyāḥ kvāthasya pāyayanti catuṣpalām kriyamāṇaḥ prasiddho 'yaṃ pāramparyāgato vidhiḥ vādhituṃ śakyate naiva jñāpakaṃ cātra vidyate palaṃ vatsakabījasya śrapayitvā rasaṃ pibet ācāryacarakeṇaivamatisāre tu bhāṣitam paṭolādye kaṣāye ca kvāthyadravyapalaṃ kṛtam caturguṇena toyena paceddravyapale sati caturbhāgāvaśeṣaṃ tu peyaṃ kvāthapalaṃ bhavet śāstre kuṣṭhe ca mātrā sā mahatī samprakāśitā catuṣpalā kaṣāyasya mātrā yā bhiṣajāṃ matā pale caturguṇajale sā mātrā na prasidhyati evaṃ sati ca sādhyaṃ syādbheṣajānāṃ catuṣpalam catuṣpalasya dravyasya kvathitasya caturguṇe toye caturthaśeṣasya peyaḥ kvāthaścatuṣpalaḥ bhaṭṭāraharicandreṇa kharaṇāde prakīrtitā pātavyā ṣaṭpalā mātrā tasya dravyapalāni ṣaṭ kvāthāni saṃprayujyante jalaṃ dravyāccaturguṇam paṭolādye ca tenāpi kvāthyadravyapalaṃ kṛtam kharaṇādakṛtā mātrā peyā tenaiva ṣaṭpalā parasparaviruddhaṃ tattasyāpyetat prayujyate aprasiddho vidhiścāyaṃ kaṣāyasya jvarādiṣu na ṣaṭpalāni kvāthyante na ca toyaṃ caturguṇam caturguṇodakā tasmāt paribhāṣā na yujyate jvarādīnāṃ kaṣāyeṣu sneheṣveva hi sā matā kṛṣṇātreyamuniproktā yā ṣoḍaśaguṇodakā jvarādiṣu kaṣāyāṇāṃ grahaṇaṃ kriyate tayā caturguṇodakā yāpi paribhāṣopadiśyate tatrāpi hi viśeṣo 'yamanyaḥ kaiścidupāśritaḥ sneheṣu palanirdeśo yeṣu na vidyate prasthavyapekṣayā cātra saṅkhyeyamudakauṣadham palavyapekṣayā cāpi samācāro dvidhā api pūrvaṃ prasthavyapekṣā yā proktā vijñāpake sati dravyāṇāṃ palanirdeśo yatrokto miśrake tathā palavyapekṣayaivātra toyamevaṃ caturguṇam pradeśāntaranirdeśāccarake 'pyanumīyate kaṣāyamātrā pātavyā yadyapyaparibhāṣitā svarṇakṣīryādike yoge pāṇḍurogacikitsite pātavyā kathitā mātrā gomūtreṇa catuṣpalā rohiṇīkaṭukādīnāṃ pittagulmacikitsite ghṛtaṃ muktvā kaṣāyasya proktā mātrā catuṣpalā ato 'numānāccarake siddhā mātrā catuṣpalā dravyāṇāṃ ca palaṃ kvāthyaṃ paṭolādye prakīrtitam palaṃ vatsakabījasya nirdiṣṭaṃ cātisārike tat ṣoḍaśaguṇe toye yadi na kvāthyate tataḥ caturguṇodake toye peyaṃ kvāthapalaṃ bhavet ityetat ṣoḍaśaguṇaṃ toyaṃ yatra prayujyate eṣaiva carakasyāpi paribhāṣānumīyate pātavyeṣu kaṣāyeṣu mustaparpaṭakādiṣu viśeṣaḥ kathyate 'nyo 'pi māne śuṣkadravāśraye śuṣkadravyāśrayaṃ mānaṃ nirdiśya yadudāhṛtam draveṣu dviguṇaṃ mānaṃ sadyaścaivoddhṛteṣu ca dviguṇaṃ mānamityetadārabhya kuḍavāditi śuṣkāṇāṃ ca dravāṇāṃ ca samaṃ tu kuḍavādadhaḥ tulāyāmapi naiveṣṭā dviguṇā mānakalpanā tulāpalaśataṃ caiva tacchruṣkadravayormatam palaṃ caturguṇaṃ ceṣṭaṃ prasiddhajñāpakādikam sahācaratulāyāstu rase tailāḍhakaṃ pacet yaduktaṃ śatamevātra palānāṃ parigṛhyate catuḥsuvarṇametacca palaṃ nāṣṭasuvarṇakam dravyasya dviguṇatve syāt palamaṣṭasuvarṇakam naivāñjalau na prasṛte na pale na palādadhaḥ dravāṇāmauṣadhānāṃ hi dviguṇaṃ mānamiṣyate dviguṇatve draveṣu syāt palamaṣṭasuvaṇakam tenaiṣāṃ dviguṇatvena kriyāmārgo virudhyate kuḍavādyāsu saṃjñāsu dravāṇāṃ dviguṇo vidhiḥ vidyate jñāpakaṃ cātra carakācāryadarśitam spaṣṭārthameva paṭhitamidaṃ kuṣṭhacikitsite salilāḍhake 'ṣṭabhāge śeṣe pūto raso grāhyaḥ te ca kaṣāyāṣṭapale catuṣpalaṃ sarpiṣaśca paktavyam yāvatsyādaṣṭapalaṃ śeṣaṃ peyaṃ tataḥ koṣṇamiti aṣṭabhāgāvaśeṣe tu palānāmaṣṭakadvayam palasya dviguṇe māne kriyamāṇe na yujyate dviguṇe hi pale tat syādekameva palāṣṭakam catuṣpalaṃ ca dātavyaṃ yat proktaṃ saha sarpisā palasya dviguṇe māne tadapyaṣṭapalaṃ bhavet catuḥsuvarṇaṃ hi palaṃ śuṣkāṇāmiṣyate yataḥ dviguṇatvāt dravāṇāṃ hi tat syādaṣṭasuvarṇakam nirūhamātrānirdeśa evaṃ sati ca bādhyate prasṛtārdhaṃ samārabhya dvādaśa prasṛtāḥ param eṣā mātrā dviguṇitā dviguṇe prasṛte bhavet nirūhamātrā śāstroktā dvādaśaprasṛtāstathā catvāriṃśat palāni syuraṣṭābhiradhikāni ca vyādhyādiṣu tu madhyeṣu kvāthasyāñjaliriṣyate atra suśrutanidaśe kvātho 'yaṃ dviguṇo bhavet svarasāt kvathitācchītāt kaṣāyāt ṣaṭpalaṃ pibet yaduktaṃ kharaṇādena taddvādaśapalaṃ bhavet paittike paṭhyate gulme sarpiṣaśca catuṣpalam pibet saṃmūrchitaṃ tena gulmaḥ śāmyati paittikaḥ catuṣpalaṃ ghṛtasyedaṃ mātrāpyaṣṭapalaṃ bhavet svarṇakṣīryādike yoge gomūtrāñjaliriṣyate añjalerdviguṇatvāddhi mātrā sāṣṭapalā bhavet gaulmike trāyamāṇādye ghṛte ca paripaṭhyate rasasyāmalakekṣūṇāṃ kṣīrasya ca ghṛtasya ca palāni pṛthagaṣṭāṣṭau kṛtvā samyagvipācayet aṣṭau pratyekametāni syuḥ ṣoḍaśa palāni tu tasmādevaṃprakāreṣu nirdeśeṣu virudhyate dravāṇāṃ dviguṇaṃ mānaṃ tatkāryaṃ kuḍavādiṣu ārdreṣvapi na sarveṣu sadyasteṣūdghṛteṣu ca dviguṇaṃ mānamicchanti viśeṣo 'tra ca kalpyate śuṣkāṇi viniyujyante daśamūlādikāni hi teṣveva dviguṇaṃ mānaṃ na sarveṣūdghṛteṣu hi ārdrāṇāmeva yeṣāṃ tu prasiddhimupakalpayet vāsāghṛte vṛṣaghṛte taile sāhacare tathā ārdrāṇāṃ dviguṇaṃ mānamevamādiṣu neṣyate ārdrāṇāmeva teṣāṃ hi prayogaḥ śasyate yataḥ śatāvarīmūlatulāścatasro yāḥ prakīrtitāḥ nai tatra dviguṇaṃ mānaṃ bhiṣagbhiḥ kaiścidāśritam vadyabuddhivikāsārthamidamanyat prakāśyate kvāthyānāmauṣadhānāṃ hi pramāṇaṃ yatra noditam caturguṇaṃ ca nirdiṣṭamanyat kṣīrādikaṃ dravam kaṣāyo 'pyauṣadhānāṃ hi tatra kāryaścaturguṇaḥ udāharaṇamatreṣṭaṃ mahākalyāṇakaṃ ghṛtam evamevauṣadhānāṃ hi pramāṇaṃ yatra noditam dviguṇaṃ cāpi nirdiṣṭamanyat kṣīrādikaṃ dravam kaṣāyo 'pyauṣadhānāṃ hi dviguṇastatra yujyate vāsādikaṃ jvare proktamatrodāharaṇaṃ smṛtam nirdiṣṭaṃ kṣīramanyadvā dravaṃ yatra caturguṇam kvāthauṣadhānāṃ mānaṃ ca proktaṃ noktaṃ jalasya tu tatroṣadhivaśādeva saṅkhyā kvāthasya gamyate caturguṇodakā tatra paribhāṣā yadīṣyate tato dravyasamastatra kaṣāyaḥ parikalpyate yadā tu paribhāṣeṣṭā yā ṣoḍaśaguṇodakā caturthaśeṣaḥ kvāthaḥ syāttato dravyāccaturguṇaḥ atra sāhacaraṃ tailamudāharaṇāmiṣyate yatrauṣadhaṃ kaṣāyo 'pi dravaṃ kṣīrādikaṃ trayam pramāṇaṃ tu tathā noktaṃ snehasyoktaṃ na vā bhavet tulyaṃ kvāthena dātavyaṃ tatra kṣīrādikaṃ dravam kartavyaṃ ca tathā tat syādyathā snehāccaturguṇam gaulmiko miśrakasneha udāharaṇamatra hi evaṃ vai dviguṇe snehāt triguṇe ca prakīrtite kṣīrādike drave kāryaṃ kaṣāyagrahaṇaṃ tathā yathā kaṣāyasahitaṃ dravaṃ syāttaccaturguṇam atrodāharaṇaṃ tat syādyathāsnehāccaturguṇaḥ kaṣāyaḥ paṭhyate yatra pramāṇaṃ cāsya noditam caturguṇaṃ vāpyadhikaṃ proktaṃ kṣīrādikaṃ dravam tatrāpi ca prayoktavyaṃ snehāt kvāthaṃ caturguṇam pañcamūlakaṣāyeṇa piṇyākaṃ bahuvārṣikam paṭhyate vātaroge tadudāharaṇamatra hi bahūni yatra paṭhyante kvacit snehe dravāṇi hi bahūnāmapi teṣāṃ ca parimāṇaṃ na paṭhyate sarveṣāṃ samudāyaḥ syāttatra snehāccaturguṇaḥ snehapākavidhiṃ kecidevaṃ samanucakṣate bahuṣvekaikamicchanti kecittatra samaṃ dravam ityevaṃ matabhedāttu yathā kvāthavidhau tathā caturguṇodakaḥ pakṣo yadā tatra samāśritaḥ bahudravyaṃ kila sneho vīryavāñchatapākavat anayaivopapatyā tu samudāyaṃ caturguṇam necchanti kecit pratyekamāhuḥ snehasamaṃ dravam grahaṇīraugike snehe pañcamūlābhayādike śuktena mātuluṅgasya svarasenaivamāditaḥ udāharaṇamatrāsti yo vāpyanyo bahudravaḥ ślokaireṣoṇutailasya kathyate pākasaṃvidhiḥ yasya sādhayituṃ tailaṃ yāvanmātramabhīpsitam tatrauṣadhāni tāvanti datvā toyaṃ caturguṇam kaṣāyārthaṃ vipacyante yaḥ kaṣāyaścaturguṇaḥ yāvanmātrasya tailasya dadyāt pādāvaśeṣitam yāvanmātramasau tailāt kaṣāyo nāvatāryate caturguṇo 'tra kiṃ tarhi pākyāddaśaguṇaḥ kṛtaḥ caturguṇena toyena prāptāni paribhāṣayā kvāthyāni yāni tānyatra pākyāḥ śataguṇe jale kvāthyante paribhāṣā tu śāstravākyena bādhitā ityevamaṇutailasya kartavyaṃ samprasādhanam gadyokto yaḥ punaḥ ślokairarthaḥ samanugīyate tadvyaktivyavasāyārthaṃ dviruktiḥ sā na garhyate prāgukto 'pi mayārtho yaḥ ślokaistasmāt prakāśitaḥ ]" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 1,
    lang: "sa",
    content: [
      { type: "heading", heading: "Акши рога — болезни глаз — обзор" },
      { type: "text", text: "Глава 1 Уттара стханы — «Акши рога» — посвящена специализированному разделу: болезни глаз — обзор. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो बालोपचरणीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bālopacaraṇīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अथ खलु जातमात्रमेव बालमुल्बात् सैन्धवसर्पिषा मार्जयेत्", text: "atha khalu jātamātrameva bālamulbāt saindhavasarpiṣā mārjayet" },
      { type: "verse", number: "3", sanskrit: "ततो ऽस्यातिप्रबलमोहज्वरपरीतसर्वगात्रस्य क्रोशितुमपि रुजानुरूपमसमर्थस्यानवस्थिताशेषदेहधातोरसम्भाव्ययौवनाद्यवस्थस्य क्रकचस्पर्शमिव करवसनशयनसंसर्गं मन्यमानस्याविकल्पितमङ्गानि विक्षिपतः पुनरिव मरणमनुभवतो लीयमानसंज्ञस्यातिसम्बाधयोनिपुटावपीडितप्राणप्रत्यानयनाय बलातैलेन परिषेकं कुर्यात् कर्णमूले चाश्मनोः सङ्घट्टनम्", text: "tato 'syātiprabalamohajvaraparītasarvagātrasya krośitumapi rujānurūpamasamarthasyānavasthitāśeṣadehadhātorasambhāvyayauvanādyavasthasya krakacasparśamiva karavasanaśayanasaṃsargaṃ manyamānasyāvikalpitamaṅgāni vikṣipataḥ punariva maraṇamanubhavato līyamānasaṃjñasyātisambādhayonipuṭāvapīḍitaprāṇapratyānayanāya balātailena pariṣekaṃ kuryāt karṇamūle cāśmanoḥ saṅghaṭṭanam" },
      { type: "verse", number: "4", sanskrit: "यदि वाचेष्ट एव स्यात्ततः कृष्णकपालिकया शूर्पेण चैनमभिनिष्पुनीयात् दक्षिणकर्णमूले च मन्त्रस्योच्चारयेत्", text: "yadi vāceṣṭa eva syāttataḥ kṛṣṇakapālikayā śūrpeṇa cainamabhiniṣpunīyāt dakṣiṇakarṇamūle ca mantrasyoccārayet" },
      { type: "verse", number: "5", sanskrit: "अङ्गादङ्गात् सम्भवसि हृदयादभिजायसे आत्मा वै पुत्रनामासि स जीव शरदां शतम्", text: "aṅgādaṅgāt sambhavasi hṛdayādabhijāyase ātmā vai putranāmāsi sa jīva śaradāṃ śatam" },
      { type: "verse", number: "6", sanskrit: "शतायुः शतवर्षो ऽसि दीर्घमायुरवाप्नुहि नक्षत्राणि दिशो रात्रिरहश्च त्वाभिरक्षतु", text: "śatāyuḥ śatavarṣo 'si dīrghamāyuravāpnuhi nakṣatrāṇi diśo rātrirahaśca tvābhirakṣatu" },
      { type: "verse", number: "7", sanskrit: "प्रत्यागतप्राणस्य च प्रकृतिभूतस्य नाभिनालं नालाभिबन्धनाच्चतुरङ्गुलस्योर्ध्वं क्षौमसूत्रेण बध्वा तीक्ष्णेन शस्त्रेण वर्धयेत् ग्रीवायां चैनमासज्जेत् नाभिं च कुष्ठतैलेन सेचयेत्", text: "pratyāgataprāṇasya ca prakṛtibhūtasya nābhinālaṃ nālābhibandhanāccaturaṅgulasyordhvaṃ kṣaumasūtreṇa badhvā tīkṣṇena śastreṇa vardhayet grīvāyāṃ cainamāsajjet nābhiṃ ca kuṣṭhatailena secayet" },
      { type: "verse", number: "8", sanskrit: "ततः क्षीरवृक्षकषायेण सर्वगन्धोदकेन वा तप्ततपनीयरजतनिर्वापणकवोष्णेन कपित्थपत्रकषायेण वा तद्विधेन स्नापयेत्", text: "tataḥ kṣīravṛkṣakaṣāyeṇa sarvagandhodakena vā taptatapanīyarajatanirvāpaṇakavoṣṇena kapitthapatrakaṣāyeṇa vā tadvidhena snāpayet" },
      { type: "verse", number: "9", sanskrit: "ततो ऽस्य सुपरिलिखितनखया सुप्रक्षालितोपवानया कार्पासपिच्ववगुण्ठितया दक्षिणप्रदेशिन्या जिह्वौष्ठकण्ठमनुसुखं प्रमृज्यात् तालु चोन्नाम्य स्नेहपिचुनोपरिष्टादवगुण्ठयेत्", text: "tato 'sya suparilikhitanakhayā suprakṣālitopavānayā kārpāsapicvavaguṇṭhitayā dakṣiṇapradeśinyā jihvauṣṭhakaṇṭhamanusukhaṃ pramṛjyāt tālu connāmya snehapicunopariṣṭādavaguṇṭhayet" },
      { type: "verse", number: "10", sanskrit: "ततश्चैन्द्रीब्राह्मीशङ्खपुष्पीवचाकल्कं मधुघृतोपेतं हरेणुमात्रं कुशाग्राभिमन्त्रितं सौवर्णेनाश्वत्थपत्रेण मेधायुर्बलजननं प्राशयेत् तद्वत् ब्राह्मीबलानन्ताशतावर्यन्यतमचूर्णं वा", text: "tataścaindrībrāhmīśaṅkhapuṣpīvacākalkaṃ madhughṛtopetaṃ hareṇumātraṃ kuśāgrābhimantritaṃ sauvarṇenāśvatthapatreṇa medhāyurbalajananaṃ prāśayet tadvat brāhmībalānantāśatāvaryanyatamacūrṇaṃ vā" },
      { type: "verse", number: "11", sanskrit: "ततः सैन्धवोपहितेन सर्पिषा गभादकानि वामयेत् तथास्योरःकण्ठविशुध्या लाघवमभिलाषश्च जायते", text: "tataḥ saindhavopahitena sarpiṣā gabhādakāni vāmayet tathāsyoraḥkaṇṭhaviśudhyā lāghavamabhilāṣaśca jāyate" },
      { type: "verse", number: "12", sanskrit: "अथास्य जातकर्म प्राजापत्येन विधिना कुर्यात् अपि च", text: "athāsya jātakarma prājāpatyena vidhinā kuryāt api ca" },
      { type: "verse", number: "13", sanskrit: "सिराणां हृदयस्थानां विवृतत्वात् प्रसूतितः तृतीये ऽह्नि चतुर्थे वा स्त्रीणां स्तन्यं प्रवर्तते", text: "sirāṇāṃ hṛdayasthānāṃ vivṛtatvāt prasūtitaḥ tṛtīye 'hni caturthe vā strīṇāṃ stanyaṃ pravartate" },
      { type: "verse", number: "14", sanskrit: "तस्मात् प्रथमे ऽहन्यनन्तामिश्रिते मधुसर्पिषी मन्त्रपूते त्रिकालं प्राशयेत् द्वितीये लक्ष्मणासिद्धं सर्पिस्तृतीये च", text: "tasmāt prathame 'hanyanantāmiśrite madhusarpiṣī mantrapūte trikālaṃ prāśayet dvitīye lakṣmaṇāsiddhaṃ sarpistṛtīye ca" },
      { type: "verse", number: "15", sanskrit: "ततः प्राङ्निवारितस्तन्यस्य स्वपाणितलसम्मितं सर्पिर्द्विकालं दापयेदनन्तरं च स्तन्यमिष्टतः", text: "tataḥ prāṅnivāritastanyasya svapāṇitalasammitaṃ sarpirdvikālaṃ dāpayedanantaraṃ ca stanyamiṣṭataḥ" },
      { type: "verse", number: "16", sanskrit: "अहरहश्चास्य श्रोत्रशृङ्गाटकं स्नेहाप्लुतेन प्लोतेन प्रच्छादयेत्", text: "aharahaścāsya śrotraśṛṅgāṭakaṃ snehāplutena plotena pracchādayet" },
      { type: "verse", number: "17", sanskrit: "प्राक्शिरसं चैनं क्षौमनिचये संवेशयेदुच्छीर्षके चास्याभिमन्त्रितमुदकुम्भं स्थापयेत् द्वारपक्षयोश्च", text: "prākśirasaṃ cainaṃ kṣaumanicaye saṃveśayeducchīrṣake cāsyābhimantritamudakumbhaṃ sthāpayet dvārapakṣayośca" },
      { type: "verse", number: "18", sanskrit: "आदारीविदारीबदरीखदिरनिम्बपीलुपरूषकशाखाभिरेनं वीजयेत् ताभिश्च समन्ततः सूत्तिकागारं परिवारयेत् सर्षपातसीकणकणिकाश्चान्तर्बहिः प्रकिरेत् सायं प्रातश्च बलिम्", text: "ādārīvidārībadarīkhadiranimbapīluparūṣakaśākhābhirenaṃ vījayet tābhiśca samantataḥ sūttikāgāraṃ parivārayet sarṣapātasīkaṇakaṇikāścāntarbahiḥ prakiret sāyaṃ prātaśca balim" },
      { type: "verse", number: "19", sanskrit: "व्रणोक्तैश्च गुग्गुल्वादिभिर्धूपं कुर्वीत तथा ब्राह्मणोथर्ववेदविद्दशाहं शान्तिकर्म कुर्यात् मायूरीं महामायूरीमार्यारत्नकेतुधारिणीं चोभयकालं वाचयेत्", text: "vraṇoktaiśca guggulvādibhirdhūpaṃ kurvīta tathā brāhmaṇotharvavedaviddaśāhaṃ śāntikarma kuryāt māyūrīṃ mahāmāyūrīmāryāratnaketudhāriṇīṃ cobhayakālaṃ vācayet" },
      { type: "verse", number: "20", sanskrit: "हिङ्गुवचातुरुष्करक्षोघ्नैः पोटलिकामुत्तरदेहल्यामासज्जेत् कुमारस्य च सह मात्रा कण्ठे उच्छीर्षके च तद्वदार्यापर्णशबरीमार्यापराजितां च गोरोचनाभिलिखिताम्", text: "hiṅguvacāturuṣkarakṣoghnaiḥ poṭalikāmuttaradehalyāmāsajjet kumārasya ca saha mātrā kaṇṭhe ucchīrṣake ca tadvadāryāparṇaśabarīmāryāparājitāṃ ca gorocanābhilikhitām" },
      { type: "verse", number: "21", sanskrit: "द्वारे च देहलीमनुतिर्यङ्मुसलं निधापयेत् कणकण्डकतिन्दुकेन्धनाग्निं नक्तं दिवं च जागृयात् तथानुरक्ताः स्त्रियः सुहृदश्च प्रहृष्टजनसम्पूर्णं च तद्वेश्म कार्यम्", text: "dvāre ca dehalīmanutiryaṅmusalaṃ nidhāpayet kaṇakaṇḍakatindukendhanāgniṃ naktaṃ divaṃ ca jāgṛyāt tathānuraktāḥ striyaḥ suhṛdaśca prahṛṣṭajanasampūrṇaṃ ca tadveśma kāryam" },
      { type: "verse", number: "22", sanskrit: "अथास्य समानवर्णा मध्यमवयाः शुचिरलोलुपा निभृतानातुरा जीवद्वत्सा वत्सला दक्षिणा ब्रह्मचारिण्यव्यङ्गा बहुक्षीरा शुक्लाम्बराचरा दीर्घद्रस्वादिदेहदोषाष्टकरहिता अलम्बोर्ध्वचुचूकातिपीनहनिस्तनदोषमुक्ता युक्तचूचुका धात्री स्यात्तस्या एव स्तन्यं पिबेत्", text: "athāsya samānavarṇā madhyamavayāḥ śuciralolupā nibhṛtānāturā jīvadvatsā vatsalā dakṣiṇā brahmacāriṇyavyaṅgā bahukṣīrā śuklāmbarācarā dīrghadrasvādidehadoṣāṣṭakarahitā alambordhvacucūkātipīnahanistanadoṣamuktā yuktacūcukā dhātrī syāttasyā eva stanyaṃ pibet" },
      { type: "verse", number: "23", sanskrit: "तच्चोदकपात्रे दुह्यमानमेकतां यदुदकेन सह गच्छति वक्ष्यमाणदोषरहितं च तच्छुद्धमारोग्यबलजननम्", text: "taccodakapātre duhyamānamekatāṃ yadudakena saha gacchati vakṣyamāṇadoṣarahitaṃ ca tacchuddhamārogyabalajananam" },
      { type: "verse", number: "24", sanskrit: "अथ धात्री स्नातानुलिप्ता नित्यमहतवासाः सुमनाः प्रजास्थापनौषधीः शिरसा बिभ्राणा प्राङ्मुखी स्तनं प्राग्दक्षिणं धौतमीषत्परिस्रुतं पाययेत्", text: "atha dhātrī snātānuliptā nityamahatavāsāḥ sumanāḥ prajāsthāpanauṣadhīḥ śirasā bibhrāṇā prāṅmukhī stanaṃ prāgdakṣiṇaṃ dhautamīṣatparisrutaṃ pāyayet" },
      { type: "verse", number: "25", sanskrit: "नानास्तन्यस्य ह्यसात्म्यत्वान्नानाविधा व्यापदो भवन्ति अपरिस्रुते चातिस्तन्यपूर्णस्तनपानेनोत्स्नेहनात् कासश्वासज्वरच्छर्दिषां सम्भवः", text: "nānāstanyasya hyasātmyatvānnānāvidhā vyāpado bhavanti aparisrute cātistanyapūrṇastanapānenotsnehanāt kāsaśvāsajvaracchardiṣāṃ sambhavaḥ" },
      { type: "verse", number: "26", sanskrit: "रुक्षान्नपानकर्शनक्रोधशोककामादिभिः स्तन्यनाशः स्तन्यजननानि तु मद्यानि शीधुवर्ज्यान्यानूपमांसानि द्रवाः स्वाद्वम्ललवणप्रायाश्चाहाराः क्षीरिण्यश्चौषधयः क्षीरपानमनायासः सौमनस्यं च", text: "rukṣānnapānakarśanakrodhaśokakāmādibhiḥ stanyanāśaḥ stanyajananāni tu madyāni śīdhuvarjyānyānūpamāṃsāni dravāḥ svādvamlalavaṇaprāyāścāhārāḥ kṣīriṇyaścauṣadhayaḥ kṣīrapānamanāyāsaḥ saumanasyaṃ ca" },
      { type: "verse", number: "27", sanskrit: "न तु क्षुधितशोकार्तश्रान्तक्रुद्धप्रदुष्टधातुंगर्भिणीविरुद्धाहारभुक्तानां स्तन्यं पाययेन्नाजीर्णौषधं च बालमिति भवति चात्र", text: "na tu kṣudhitaśokārtaśrāntakruddhapraduṣṭadhātuṃgarbhiṇīviruddhāhārabhuktānāṃ stanyaṃ pāyayennājīrṇauṣadhaṃ ca bālamiti bhavati cātra" },
      { type: "verse", number: "28", sanskrit: "षष्टीं निशां विशेषेण कृतरक्षाबलिक्रियाः जागृयुर्बान्धवास्तस्य दधतः परमां मुदम्", text: "ṣaṣṭīṃ niśāṃ viśeṣeṇa kṛtarakṣābalikriyāḥ jāgṛyurbāndhavāstasya dadhataḥ paramāṃ mudam" },
      { type: "verse", number: "29", sanskrit: "दशमे द्वादशे वाह्नि गोत्राचारैः शुभैः शुभे सूता स्नानोत्सवं कुर्यात् पितापत्यस्य नाम च", text: "daśame dvādaśe vāhni gotrācāraiḥ śubhaiḥ śubhe sūtā snānotsavaṃ kuryāt pitāpatyasya nāma ca" },
      { type: "verse", number: "30", sanskrit: "दिने शततमे वाख्यां पूर्णे संवत्सरे ऽथवा बिभ्रतो ऽङ्गैर्मनोह्वालरोचनागरुचन्दनम्", text: "dine śatatame vākhyāṃ pūrṇe saṃvatsare 'thavā bibhrato 'ṅgairmanohvālarocanāgarucandanam" },
      { type: "verse", number: "31", sanskrit: "पूज्यं त्रिपुरुषानूकमादौ घोषवदक्षरम् अवृद्धं कृतमूष्मान्तमनरातिप्रतिष्ठितम्", text: "pūjyaṃ tripuruṣānūkamādau ghoṣavadakṣaram avṛddhaṃ kṛtamūṣmāntamanarātipratiṣṭhitam" },
      { type: "verse", number: "32", sanskrit: "नक्षत्रदेवतायुक्तं तदेव तु न केवलम् मङ्गल्यमन्तरन्तस्थं न दुष्टं न च तद्धितम्", text: "nakṣatradevatāyuktaṃ tadeva tu na kevalam maṅgalyamantarantasthaṃ na duṣṭaṃ na ca taddhitam" },
      { type: "verse", number: "33", sanskrit: "पुंसो विसर्जनीयान्तं समवर्णं स्त्रियाः पुनः विषमाक्षरमक्रूरं विस्पष्टार्थं मनोरमम् सुखोद्यं दीर्घवर्णान्तमाशीर्वादाभिधानवत्", text: "puṃso visarjanīyāntaṃ samavarṇaṃ striyāḥ punaḥ viṣamākṣaramakrūraṃ vispaṣṭārthaṃ manoramam sukhodyaṃ dīrghavarṇāntamāśīrvādābhidhānavat" },
      { type: "verse", number: "34", sanskrit: "ततः प्रकृतिभेदोक्तरूपैरायुःपरीक्षणम् प्रागुदक्शिरसःकुर्यात् बालस्यज्ञानवान्भिषक्", text: "tataḥ prakṛtibhedoktarūpairāyuḥparīkṣaṇam prāgudakśirasaḥkuryāt bālasyajñānavānbhiṣak" },
      { type: "verse", number: "35", sanskrit: "प्रशस्तवास्तुशरणं सज्जोपकरणं शुचि निर्वातं च प्रवातं च वृद्धस्त्रीवैद्यसेवितम्", text: "praśastavāstuśaraṇaṃ sajjopakaraṇaṃ śuci nirvātaṃ ca pravātaṃ ca vṛddhastrīvaidyasevitam" },
      { type: "verse", number: "36", sanskrit: "निर्मत्कुणाखुमशकमतमस्कं च शस्यते शुचिधौतोपवानानि निर्वलीनि मृदूनि च", text: "nirmatkuṇākhumaśakamatamaskaṃ ca śasyate śucidhautopavānāni nirvalīni mṛdūni ca" },
      { type: "verse", number: "37", sanskrit: "शय्यास्तरणवासांसि रक्षोघ्नैर्धूपितानि च काको ऽविशस्तः शस्तश्च धूपने त्रिवृतान्वितः वचाज्यकुष्ठश्रीवेष्टसर्षपैर्धूपयेत् सदा", text: "śayyāstaraṇavāsāṃsi rakṣoghnairdhūpitāni ca kāko 'viśastaḥ śastaśca dhūpane trivṛtānvitaḥ vacājyakuṣṭhaśrīveṣṭasarṣapairdhūpayet sadā" },
      { type: "verse", number: "38", sanskrit: "बोधयेत् सहसा सुप्तं नो न चैनं समुत्क्षिपेत् तथाह्यस्य समुत्रासो वेगरोधश्च जायते", text: "bodhayet sahasā suptaṃ no na cainaṃ samutkṣipet tathāhyasya samutrāso vegarodhaśca jāyate" },
      { type: "verse", number: "39", sanskrit: "माक्षिकामलकव्योषबृहतीमूलसैन्धवैः लालापनोदरुच्यर्थं मुखमन्तः परामृशेत्", text: "mākṣikāmalakavyoṣabṛhatīmūlasaindhavaiḥ lālāpanodarucyarthaṃ mukhamantaḥ parāmṛśet" },
      { type: "verse", number: "40", sanskrit: "जीवत्खड्गादिशृङ्गेषु समासक्ताञ्छुभान् मणीन् धारयेद्दश चैन्द्र्यादीञ्जीवकर्षभकावपि", text: "jīvatkhaḍgādiśṛṅgeṣu samāsaktāñchubhān maṇīn dhārayeddaśa caindryādīñjīvakarṣabhakāvapi" },
      { type: "verse", number: "41", sanskrit: "हस्ताभ्यां ग्रीवया मूर्ध्ना विशेषात् सततं वचाम् आयुर्मेधास्मृतिस्वास्थ्यकरीं रक्षोभिरक्षणीम्", text: "hastābhyāṃ grīvayā mūrdhnā viśeṣāt satataṃ vacām āyurmedhāsmṛtisvāsthyakarīṃ rakṣobhirakṣaṇīm" },
      { type: "verse", number: "42", sanskrit: "स्तन्यदोषात् गदास्तस्य यथोक्तं तत् पिबेद्यतः पीनो ऽतिकन्धरास्तम्भं कुर्यादूर्ध्वाक्षमूर्ध्वगः", text: "stanyadoṣāt gadāstasya yathoktaṃ tat pibedyataḥ pīno 'tikandharāstambhaṃ kuryādūrdhvākṣamūrdhvagaḥ" },
      { type: "verse", number: "43", sanskrit: "उच्छ्वासरोधात् लंबो ऽतिस्तनो जीवितसंशयम् न गर्भिण्याः पिबेत् स्तन्यं पारिगर्भिककृद्धि तत्", text: "ucchvāsarodhāt laṃbo 'tistano jīvitasaṃśayam na garbhiṇyāḥ pibet stanyaṃ pārigarbhikakṛddhi tat" },
      { type: "verse", number: "44", sanskrit: "स्तन्याभावे पयश्छागं गव्यं वा तद्गुणं पिबेत् मूलैःसिद्धं बृहत्याद्यैः स्थिराभ्यां वा सितायुतम्", text: "stanyābhāve payaśchāgaṃ gavyaṃ vā tadguṇaṃ pibet mūlaiḥsiddhaṃ bṛhatyādyaiḥ sthirābhyāṃ vā sitāyutam" },
      { type: "verse", number: "45", sanskrit: "चतुर्थे सूतिकागारादग्निस्कन्दपुरोगमान् मासे निष्क्रामयेद्देवान् नमस्कर्तुं स्वलङ्कृतम्", text: "caturthe sūtikāgārādagniskandapurogamān māse niṣkrāmayeddevān namaskartuṃ svalaṅkṛtam" },
      { type: "verse", number: "46", sanskrit: "पञ्चमे मासि पुण्ये ऽह्नि धरण्यामुपवेशयेत् द्विकिष्कुमात्रं लिप्तायां बलिं दत्वा चतुर्दिशम्", text: "pañcame māsi puṇye 'hni dharaṇyāmupaveśayet dvikiṣkumātraṃ liptāyāṃ baliṃ datvā caturdiśam" },
      { type: "verse", number: "47", sanskrit: "धरण्यशेषभूतानां माता त्वमसि कामधुक् अजरा चाप्रमेया च सर्वभूतनमस्कृता", text: "dharaṇyaśeṣabhūtānāṃ mātā tvamasi kāmadhuk ajarā cāprameyā ca sarvabhūtanamaskṛtā" },
      { type: "verse", number: "48", sanskrit: "चराचराणां लोकानां प्रतिष्ठास्यव्ययासि च कुमारं पाहि मातेव ब्रह्मा तदनुमन्यताम्", text: "carācarāṇāṃ lokānāṃ pratiṣṭhāsyavyayāsi ca kumāraṃ pāhi māteva brahmā tadanumanyatām" },
      { type: "verse", number: "49", sanskrit: "स्वाहेति मन्त्रेणानेन प्रत्यहं च ततः परम् साश्रयं सावलम्बं च कट्यादीन् मर्दयेदनु", text: "svāheti mantreṇānena pratyahaṃ ca tataḥ param sāśrayaṃ sāvalambaṃ ca kaṭyādīn mardayedanu" },
      { type: "verse", number: "50", sanskrit: "षष्ठे ऽन्नप्राशनं मासि क्रमात्तच्च प्रयोजयेत् चिरान्निषेवमाणो ऽन्नं बालो नातुर्यमश्नुते", text: "ṣaṣṭhe 'nnaprāśanaṃ māsi kramāttacca prayojayet cirānniṣevamāṇo 'nnaṃ bālo nāturyamaśnute" },
      { type: "verse", number: "51", sanskrit: "भजेद्यथा यथाचान्नं स्तन्यं त्याज्यं तथा तथा षट्सप्ताष्टममासेषु नीरुजस्य शुभे ऽहनि कर्णौ हिमागमे विघ्येद्धात्र्यङ्कस्थस्य सान्त्वयन्", text: "bhajedyathā yathācānnaṃ stanyaṃ tyājyaṃ tathā tathā ṣaṭsaptāṣṭamamāseṣu nīrujasya śubhe 'hani karṇau himāgame vighyeddhātryaṅkasthasya sāntvayan" },
      { type: "verse", number: "52", sanskrit: "प्राग्दक्षिणं कुमारस्य भिषग्वामं तु योषितः दक्षिणेन दधत् सूचीं पालीमन्येन पाणिना", text: "prāgdakṣiṇaṃ kumārasya bhiṣagvāmaṃ tu yoṣitaḥ dakṣiṇena dadhat sūcīṃ pālīmanyena pāṇinā" },
      { type: "verse", number: "53", sanskrit: "मध्यतः कर्णपीठस्य किञ्चित् गण्डाशयं प्रति जरायुमात्रप्रच्छन्ने रविरश्म्यवभासिते", text: "madhyataḥ karṇapīṭhasya kiñcit gaṇḍāśayaṃ prati jarāyumātrapracchanne raviraśmyavabhāsite" },
      { type: "verse", number: "54", sanskrit: "धृतस्य निश्चलं सम्यगलक्तकरसाङ्किते विध्येद्दैवकृते छिद्रे सकृदेवर्जु लाघवात्", text: "dhṛtasya niścalaṃ samyagalaktakarasāṅkite vidhyeddaivakṛte chidre sakṛdevarju lāghavāt" },
      { type: "verse", number: "55", sanskrit: "नोर्ध्वं न पार्श्वतो नाधः सिरास्तत्र हि संश्रिताः", text: "nordhvaṃ na pārśvato nādhaḥ sirāstatra hi saṃśritāḥ" },
      { type: "verse", number: "56", sanskrit: "कालिकामर्मरीरक्तास्तद्व्यधाद्रागरुग्ज्वराः सशोफदाहसंरम्भमन्यास्तम्भापतानकाः तेषां यथामयं कुर्याद्विभज्याशु चिकित्सितम्", text: "kālikāmarmarīraktāstadvyadhādrāgarugjvarāḥ saśophadāhasaṃrambhamanyāstambhāpatānakāḥ teṣāṃ yathāmayaṃ kuryādvibhajyāśu cikitsitam" },
      { type: "verse", number: "57", sanskrit: "स्थानव्यधान्न रुधिरं न रुग्रागादिसम्भवः स्नेहाक्तं सूच्यनुस्यूतं सूत्र चानु निधापयेत् आमतैलेन सिञ्चेच्च बहलां तद्वदारया", text: "sthānavyadhānna rudhiraṃ na rugrāgādisambhavaḥ snehāktaṃ sūcyanusyūtaṃ sūtra cānu nidhāpayet āmatailena siñcecca bahalāṃ tadvadārayā" },
      { type: "verse", number: "58", sanskrit: "विध्येत् पालीं हितभुजः सञ्चार्याथ स्थवीयसी वर्ति स्त्र्यहात्ततो रूढं वर्धयेत शनैः शनैः स्वेदितोद्वर्तिंतं कर्णमभ्यक्तं बृंहणैः पुनः", text: "vidhyet pālīṃ hitabhujaḥ sañcāryātha sthavīyasī varti stryahāttato rūḍhaṃ vardhayeta śanaiḥ śanaiḥ sveditodvartiṃtaṃ karṇamabhyaktaṃ bṛṃhaṇaiḥ punaḥ" },
      { type: "verse", number: "59", sanskrit: "नाजीण न मलोद्रेके न चात्युष्णे ऽपि वर्धयेत् सदा च युञ्ज्यादभ्यङ्गान्कर्णपालीगदोदितान्", text: "nājīṇa na malodreke na cātyuṣṇe 'pi vardhayet sadā ca yuñjyādabhyaṅgānkarṇapālīgadoditān" },
      { type: "verse", number: "60", sanskrit: "पुष्टिनीरुक्त्वजननानिति संवर्धिते दृढे कलधौतावबद्धानि कर्णे रत्नानि निक्षिपेत्", text: "puṣṭinīruktvajananāniti saṃvardhite dṛḍhe kaladhautāvabaddhāni karṇe ratnāni nikṣipet" },
      { type: "verse", number: "61", sanskrit: "भिन्द्यादवृद्धौ स्त्रीणान्तु पालीमन्तरपाङ्गतः नैव चापाङ्गयोर्बाह्यां व्यापदः स्युस्ततो ध्रुवाः", text: "bhindyādavṛddhau strīṇāntu pālīmantarapāṅgataḥ naiva cāpāṅgayorbāhyāṃ vyāpadaḥ syustato dhruvāḥ" },
      { type: "verse", number: "62", sanskrit: "जिह्मसूचीव्यधाद्वर्तिगाढत्वादथवा मलैः जाते महति संरम्भे वर्तिमाश्वपनीय तत्", text: "jihmasūcīvyadhādvartigāḍhatvādathavā malaiḥ jāte mahati saṃrambhe vartimāśvapanīya tat" },
      { type: "verse", number: "63", sanskrit: "यवैरण्डजटायष्टीमञ्जिष्ठज्यैः प्रलेपयेत् सुरूढं च पुनर्विध्यत् त्वरया तु विवर्धनात्", text: "yavairaṇḍajaṭāyaṣṭīmañjiṣṭhajyaiḥ pralepayet surūḍhaṃ ca punarvidhyat tvarayā tu vivardhanāt" },
      { type: "verse", number: "64", sanskrit: "छिद्येत पाली शुद्धस्य शुद्धास्रां सन्दधीत ताम् कर्णामयनिषेधोक्तसन्धानविधिना भिषक्", text: "chidyeta pālī śuddhasya śuddhāsrāṃ sandadhīta tām karṇāmayaniṣedhoktasandhānavidhinā bhiṣak" },
      { type: "verse", number: "65", sanskrit: "वर्षं स्ववसतेर्बाह्यं कुमारस्य न दर्शयेत् दीपमातपमग्निं च रूपमन्यच्च भासुरम्", text: "varṣaṃ svavasaterbāhyaṃ kumārasya na darśayet dīpamātapamagniṃ ca rūpamanyacca bhāsuram" },
      { type: "verse", number: "66", sanskrit: "अथैनं जातदशनं क्रमशो ऽपनयेत् स्तनात् पूर्वोक्तं योजयेत् क्षीरमन्नं च लघु बृंहणम्", text: "athainaṃ jātadaśanaṃ kramaśo 'panayet stanāt pūrvoktaṃ yojayet kṣīramannaṃ ca laghu bṛṃhaṇam" },
      { type: "verse", number: "67", sanskrit: "कुर्यादपस्तनं स्नेहसङ्क्रान्त्या स्तनलेपनैः बीभत्सैर्यावकासेककृत्रिमक्षतदर्शनैः", text: "kuryādapastanaṃ snehasaṅkrāntyā stanalepanaiḥ bībhatsairyāvakāsekakṛtrimakṣatadarśanaiḥ" },
      { type: "verse", number: "68", sanskrit: "प्रियालमज्जमधुकमधुलाजसितोपलैः अपस्तन्यस्य संयोज्यः प्रीणनो मोदकः शिशोः", text: "priyālamajjamadhukamadhulājasitopalaiḥ apastanyasya saṃyojyaḥ prīṇano modakaḥ śiśoḥ" },
      { type: "verse", number: "69", sanskrit: "दीपनो बालबिल्वैलाशर्करालाजसक्तुभिः सङ्ग्राही धातकीपुष्पशर्करालाजतर्पणैः", text: "dīpano bālabilvailāśarkarālājasaktubhiḥ saṅgrāhī dhātakīpuṣpaśarkarālājatarpaṇaiḥ" },
      { type: "verse", number: "70", sanskrit: "बुभुक्षा चेत् प्रबलतामपस्तन्यस्य गच्छति अत्यग्निजिद्धितं तस्य विधानं पारिगर्भिकम्", text: "bubhukṣā cet prabalatāmapastanyasya gacchati atyagnijiddhitaṃ tasya vidhānaṃ pārigarbhikam" },
      { type: "verse", number: "71", sanskrit: "अभियुक्तः सदाचारो नातिस्थूलो न लोलुपः कुमारधारः कतव्यस्तत्राद्यो बालचित्तवित्", text: "abhiyuktaḥ sadācāro nātisthūlo na lolupaḥ kumāradhāraḥ katavyastatrādyo bālacittavit" },
      { type: "verse", number: "72", sanskrit: "अघार्मिकं दुराचारः स्थूलो विकटगामिनम् करोति लोलुपो बालं घस्मरत्वेन रोगिणम्", text: "aghārmikaṃ durācāraḥ sthūlo vikaṭagāminam karoti lolupo bālaṃ ghasmaratvena rogiṇam" },
      { type: "verse", number: "73", sanskrit: "रोगांश्चास्य जयेत् सौम्यैर्भेषजैरविषादकैः अन्यत्रात्ययिकाद्व्याधेर्विरेकं सुतरां त्यजेत्", text: "rogāṃścāsya jayet saumyairbheṣajairaviṣādakaiḥ anyatrātyayikādvyādhervirekaṃ sutarāṃ tyajet" },
      { type: "verse", number: "74", sanskrit: "त्रासयेन्नाविधेयं च त्रस्तं गृह्वन्ति हि ग्रहाः वस्त्रपातात् परस्पर्शात् पालयेल्लङ्घनाच्च तम्", text: "trāsayennāvidheyaṃ ca trastaṃ gṛhvanti hi grahāḥ vastrapātāt parasparśāt pālayellaṅghanācca tam" },
      { type: "verse", number: "75", sanskrit: "क्रीडाभूमिः समा कार्या निश्शस्त्रोपलशर्करा वेल्लोषणकणाम्भोभिः सिक्ता निम्बोदकेन वा", text: "krīḍābhūmiḥ samā kāryā niśśastropalaśarkarā velloṣaṇakaṇāmbhobhiḥ siktā nimbodakena vā" },
      { type: "verse", number: "76", sanskrit: "जातुषं घोषवच्चित्रमत्रासं रमणं बृहत् अतीक्ष्णाग्रं गवाश्वादिमङ्गल्यमथ वा फलम्", text: "jātuṣaṃ ghoṣavaccitramatrāsaṃ ramaṇaṃ bṛhat atīkṣṇāgraṃ gavāśvādimaṅgalyamatha vā phalam" },
      { type: "verse", number: "77", sanskrit: "शक्तिमन्तं यथावर्णं विद्यामध्यापयेत्ततः अनुशिष्यात् सदा चैनं धर्माय विनयाय च", text: "śaktimantaṃ yathāvarṇaṃ vidyāmadhyāpayettataḥ anuśiṣyāt sadā cainaṃ dharmāya vinayāya ca" },
      { type: "verse", number: "78", sanskrit: "यथा नेन्द्रियदुष्टाश्वैर्द्रियते यौवनागमे अभ्यङ्गोद्वर्तनं स्नानं प्रत्यहं च समाचरेत् सहदेवास्थिराकौन्तीकुमुदोत्पलचन्दनैः", text: "yathā nendriyaduṣṭāśvairdriyate yauvanāgame abhyaṅgodvartanaṃ snānaṃ pratyahaṃ ca samācaret sahadevāsthirākauntīkumudotpalacandanaiḥ" },
      { type: "verse", number: "79", sanskrit: "बृहतीफलतर्कारीसर्षपाकुष्ठसैन्धवैः अश्वगन्धाबलैरण्डतिलापामार्गतण्डुलैः", text: "bṛhatīphalatarkārīsarṣapākuṣṭhasaindhavaiḥ aśvagandhābalairaṇḍatilāpāmārgataṇḍulaiḥ" },
      { type: "verse", number: "80", sanskrit: "सात्मगुप्ताफलैस्तैलं साजक्षीरं विपाचितम् रक्षोघ्नः पुष्टिदो ऽभ्यङ्गस्तद्वदुद्वर्तनं च तैः", text: "sātmaguptāphalaistailaṃ sājakṣīraṃ vipācitam rakṣoghnaḥ puṣṭido 'bhyaṅgastadvadudvartanaṃ ca taiḥ" },
      { type: "verse", number: "81", sanskrit: "दधिमाक्षिकसंयुक्तैस्त्रिगुणीकृतचिक्कसैः मूर्वामूलद्विरजनीयवैश्चोद्वर्तनं हितम्", text: "dadhimākṣikasaṃyuktaistriguṇīkṛtacikkasaiḥ mūrvāmūladvirajanīyavaiścodvartanaṃ hitam" },
      { type: "verse", number: "82", sanskrit: "कुलत्थचूर्णमेकं वा वाजिगन्धारजो ऽपि वा स्नाने सर्वौषधीकल्को जीवनीयाम्बु चेष्यते", text: "kulatthacūrṇamekaṃ vā vājigandhārajo 'pi vā snāne sarvauṣadhīkalko jīvanīyāmbu ceṣyate" },
      { type: "verse", number: "83", sanskrit: "आरग्वधादिनिर्यूहे शृतं शीतवसन्तयोः वत्सकादिप्रतीवापं कुमारं प्राशयेत् घृतम्", text: "āragvadhādiniryūhe śṛtaṃ śītavasantayoḥ vatsakādipratīvāpaṃ kumāraṃ prāśayet ghṛtam" },
      { type: "verse", number: "84", sanskrit: "ग्रीष्मे वातातपस्वेदैर्बालः क्लाम्यत्यतो हिमम् प्रातरेव पिबेद्दुग्धं जीवनीयगणैः शृतम्", text: "grīṣme vātātapasvedairbālaḥ klāmyatyato himam prātareva pibeddugdhaṃ jīvanīyagaṇaiḥ śṛtam" },
      { type: "verse", number: "85", sanskrit: "सिताघृताढ्यान् सक्तूंश्च लिह्यान्नत्वेव पीतकम् नात्यम्बुपायी लिह्याद्वा घृतसात्म्यो घृतं शृतम्", text: "sitāghṛtāḍhyān saktūṃśca lihyānnatveva pītakam nātyambupāyī lihyādvā ghṛtasātmyo ghṛtaṃ śṛtam" },
      { type: "verse", number: "86", sanskrit: "काकोलीशर्करामेदातुगायष्ट्याह्वजीवकैः कटुन्नटेन मूर्धानं लिम्पेदन्यैश्च शीतलैः", text: "kākolīśarkarāmedātugāyaṣṭyāhvajīvakaiḥ kaṭunnaṭena mūrdhānaṃ limpedanyaiśca śītalaiḥ" },
      { type: "verse", number: "87", sanskrit: "रास्नासरलवर्षाभूहिङ्गुसैन्धवदारुभिः सर्पिर्विदार्यादिजले साधितं लेहयेच्छिशुम्", text: "rāsnāsaralavarṣābhūhiṅgusaindhavadārubhiḥ sarpirvidāryādijale sādhitaṃ lehayecchiśum" },
      { type: "verse", number: "88", sanskrit: "प्रपौण्डरीकं मधुकं सूप्यपर्ण्यौ दुरालभा प्रियालमज्जाकाकोलीविदारीकट्फलामृताः", text: "prapauṇḍarīkaṃ madhukaṃ sūpyaparṇyau durālabhā priyālamajjākākolīvidārīkaṭphalāmṛtāḥ" },
      { type: "verse", number: "89", sanskrit: "द्राक्षाजशृङ्गी दुग्धीका क्षीरशुक्ला हयाह्वया शृङ्गीमधूककुसुममेदर्षभकजीवकम्", text: "drākṣājaśṛṅgī dugdhīkā kṣīraśuklā hayāhvayā śṛṅgīmadhūkakusumamedarṣabhakajīvakam" },
      { type: "verse", number: "90", sanskrit: "एभिः क्षीरघृतं सिद्धं लिह्यात् बालो घनात्यये ब्राह्मीसिद्धार्थकवचासारिवाकुष्ठसैन्धवैः", text: "ebhiḥ kṣīraghṛtaṃ siddhaṃ lihyāt bālo ghanātyaye brāhmīsiddhārthakavacāsārivākuṣṭhasaindhavaiḥ" },
      { type: "verse", number: "91", sanskrit: "सकणैः साधितं पीतं वाङ्मेधास्मृतिकृत् घृतम् आयुष्यं पाप्मरक्षोघ्नं भूतोन्मादनिबर्हणम्", text: "sakaṇaiḥ sādhitaṃ pītaṃ vāṅmedhāsmṛtikṛt ghṛtam āyuṣyaṃ pāpmarakṣoghnaṃ bhūtonmādanibarhaṇam" },
      { type: "verse", number: "92", sanskrit: "त्रिफला लक्ष्मणानन्ता समङ्गा सारिवा वचा ब्राह्मी पाठा द्विबृहती द्विस्थिरा द्विपुनर्नवम्", text: "triphalā lakṣmaṇānantā samaṅgā sārivā vacā brāhmī pāṭhā dvibṛhatī dvisthirā dvipunarnavam" },
      { type: "verse", number: "93", sanskrit: "सहदेवा रवेर्वल्ली पयस्या गिरिकर्णिका तोयकुम्भे पचेदेतत् पलांशं पादशेषितम्", text: "sahadevā ravervallī payasyā girikarṇikā toyakumbhe pacedetat palāṃśaṃ pādaśeṣitam" },
      { type: "verse", number: "94", sanskrit: "तेन कौन्तीवचाकुष्ठकृष्णासर्षपसैन्धवैः नीरुक्सरूपवत्सायाः संयुक्तं पयसा च गोः", text: "tena kauntīvacākuṣṭhakṛṣṇāsarṣapasaindhavaiḥ nīruksarūpavatsāyāḥ saṃyuktaṃ payasā ca goḥ" },
      { type: "verse", number: "95", sanskrit: "पुष्ययोगे घृतप्रस्थं सहेमशकलं शृतम् पानाभ्यञ्जनतो मेधास्मृत्यायुःपुष्टिबुद्धिदम्", text: "puṣyayoge ghṛtaprasthaṃ sahemaśakalaṃ śṛtam pānābhyañjanato medhāsmṛtyāyuḥpuṣṭibuddhidam" },
      { type: "verse", number: "96", sanskrit: "रक्षोघ्नं च विषघ्नं च सारस्वतमिदं घृतम् लीढं वा सघृतक्षौद्रं वचाहेमरजो ऽल्पशः संवत्सरं परं मेध्यं रक्षोघ्नं वाग्विवर्धनम्", text: "rakṣoghnaṃ ca viṣaghnaṃ ca sārasvatamidaṃ ghṛtam līḍhaṃ vā saghṛtakṣaudraṃ vacāhemarajo 'lpaśaḥ saṃvatsaraṃ paraṃ medhyaṃ rakṣoghnaṃ vāgvivardhanam" },
      { type: "verse", number: "97", sanskrit: "वयस्था पिप्पली कुष्ठं हरिद्रा सारिवा वचा मांसी कैडर्यमित्येतच्चूर्णं ब्राह्मीरजःसमम्", text: "vayasthā pippalī kuṣṭhaṃ haridrā sārivā vacā māṃsī kaiḍaryamityetaccūrṇaṃ brāhmīrajaḥsamam" },
      { type: "verse", number: "98", sanskrit: "लीढ्वाज्येन शिशुर्वर्षं भवत्यपलितो ऽव्यथः बलवान् श्रुतसम्पन्नः शतायुः स्थिरयौवनः प्रातः प्रातरिमं लेहं धात्रीं चास्यावलेहयेत्", text: "līḍhvājyena śiśurvarṣaṃ bhavatyapalito 'vyathaḥ balavān śrutasampannaḥ śatāyuḥ sthirayauvanaḥ prātaḥ prātarimaṃ lehaṃ dhātrīṃ cāsyāvalehayet" },
      { type: "verse", number: "99", sanskrit: "ब्राह्मीवद्योजयेद्दूर्वां मूर्वां ब्रह्मसुवर्चलाम् लक्ष्मणां श्वेततर्कारीमव्यण्डां गौरसर्षपाम्", text: "brāhmīvadyojayeddūrvāṃ mūrvāṃ brahmasuvarcalām lakṣmaṇāṃ śvetatarkārīmavyaṇḍāṃ gaurasarṣapām" },
      { type: "verse", number: "100", sanskrit: "सहस्रवीर्यां फलिनीं पक्वं च बृंहतीफलम् रोहिषं चेत्यमीप्राशाः पृथग्द्वादश कीर्तिताः", text: "sahasravīryāṃ phalinīṃ pakvaṃ ca bṛṃhatīphalam rohiṣaṃ cetyamīprāśāḥ pṛthagdvādaśa kīrtitāḥ" },
      { type: "verse", number: "101", sanskrit: "महताप्युपयोक्तव्या नरेण नियतात्मना नित्यं मृद्भक्षणाद्रक्षेत्तया स्युर्नियतं गदाः", text: "mahatāpyupayoktavyā nareṇa niyatātmanā nityaṃ mṛdbhakṣaṇādrakṣettayā syurniyataṃ gadāḥ" },
      { type: "verse", number: "102", sanskrit: "पाण्डुत्वश्वयथुश्वासकासातीसारजन्तवः छर्दिंमूर्छाग्निसदनस्तन्यद्वेषाङ्गरुग्भ्रमाः", text: "pāṇḍutvaśvayathuśvāsakāsātīsārajantavaḥ chardiṃmūrchāgnisadanastanyadveṣāṅgarugbhramāḥ" },
      { type: "verse", number: "103", sanskrit: "भक्षयेद्दन्तपवनं नास्थिरद्विजब्बन्धनः तस्य तत्घट्टनात् क्रुद्धः कुर्याद्दन्तामयान्मरुत्", text: "bhakṣayeddantapavanaṃ nāsthiradvijabbandhanaḥ tasya tatghaṭṭanāt kruddhaḥ kuryāddantāmayānmarut" },
      { type: "verse", number: "104", sanskrit: "शूरैरायुधिभिर्गुप्तमधृष्यं नगरं परैः यथा शिशोर्वपुस्तद्वद्यथोक्तैर्विधिभिर्ग्रहैः", text: "śūrairāyudhibhirguptamadhṛṣyaṃ nagaraṃ paraiḥ yathā śiśorvapustadvadyathoktairvidhibhirgrahaiḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 2,
    lang: "sa",
    content: [
      { type: "heading", heading: "Тимира рога — катаракта" },
      { type: "text", text: "Глава 2 Уттара стханы — «Тимира рога» — посвящена специализированному разделу: катаракта. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो बालामयप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bālāmayapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "त्रिविधो हि बालः प्रागुक्तस्तत्र क्षीरपस्य क्षीरमदुष्टं प्रयुञ्जीत अन्नादस्य हितमन्नम् उभयवृत्तेरुभयम्", text: "trividho hi bālaḥ prāguktastatra kṣīrapasya kṣīramaduṣṭaṃ prayuñjīta annādasya hitamannam ubhayavṛtterubhayam" },
      { type: "verse", number: "3", sanskrit: "क्षीरं हि यथोक्तैर्दोषकोपनैराहारविहारैर्धात्र्या व्यापन्नं विविधामयोदयाय बालस्य प्रकल्पते", text: "kṣīraṃ hi yathoktairdoṣakopanairāhāravihārairdhātryā vyāpannaṃ vividhāmayodayāya bālasya prakalpate" },
      { type: "verse", number: "4", sanskrit: "तत्र श्यावारुणवर्णं तिक्तकषायानुरसं विशदं रूक्षमलक्ष्यगन्धं फेनिलमतृप्तिकरमाध्मानमूत्रवर्चोविबन्धकृत् कर्शनमप्सु विसर्पति विच्छिन्नं च प्लवते वातदुष्टम्", text: "tatra śyāvāruṇavarṇaṃ tiktakaṣāyānurasaṃ viśadaṃ rūkṣamalakṣyagandhaṃ phenilamatṛptikaramādhmānamūtravarcovibandhakṛt karśanamapsu visarpati vicchinnaṃ ca plavate vātaduṣṭam" },
      { type: "verse", number: "5", sanskrit: "कृष्णनीलताम्रावभासं तिक्ताम्लकटुकानुरसं कुणपरुधिरगन्धि भृशोष्णमप्सु पीतराजिमद्विदाहकरं च पित्तदुष्टम्", text: "kṛṣṇanīlatāmrāvabhāsaṃ tiktāmlakaṭukānurasaṃ kuṇaparudhiragandhi bhṛśoṣṇamapsu pītarājimadvidāhakaraṃ ca pittaduṣṭam" },
      { type: "verse", number: "6", sanskrit: "अत्यर्थशुक्लमधुरं लवणानुरसं घृततैलवसामज्जगन्धि पिच्छिलं बहलं तन्तुमत् गुरु सलिले ऽवसीदति निद्राबहुलं च श्लेष्मदुष्टम्", text: "atyarthaśuklamadhuraṃ lavaṇānurasaṃ ghṛtatailavasāmajjagandhi picchilaṃ bahalaṃ tantumat guru salile 'vasīdati nidrābahulaṃ ca śleṣmaduṣṭam" },
      { type: "verse", number: "7", sanskrit: "तदुपयुज्यमानं यथास्वलिङ्गान् व्याधीनभिनिर्वर्तयति", text: "tadupayujyamānaṃ yathāsvaliṅgān vyādhīnabhinirvartayati" },
      { type: "verse", number: "8", sanskrit: "स यं प्रदेशमभीक्ष्णं स्पृशति स्पर्शं च न क्षमते तत्र रुजमुपलक्षयेत्", text: "sa yaṃ pradeśamabhīkṣṇaṃ spṛśati sparśaṃ ca na kṣamate tatra rujamupalakṣayet" },
      { type: "verse", number: "9", sanskrit: "निमीलिताक्षतया मूर्ध्नि रुजम् जिह्वौष्ठदंशश्वासमुष्टिवन्धोर्ध्वेक्षणैर्हृदये विण्मूत्रच्छर्द्याध्मानान्त्रकूजनस्तनदंशवेष्टनपृष्ठविनमनजठरोन्नमनैर्जठरे मूत्रसङ्गतृण्मूर्च्छोत्रासदिग्वीक्षणखल्लीहस्तपादस्तम्भकुब्जीभवनकेशलुञ्चनैर्बस्तौ गुह्ये च सर्वत्र च स्वभा वातिरिक्तरोदनेन मुखविकूणनेन च", text: "nimīlitākṣatayā mūrdhni rujam jihvauṣṭhadaṃśaśvāsamuṣṭivandhordhvekṣaṇairhṛdaye viṇmūtracchardyādhmānāntrakūjanastanadaṃśaveṣṭanapṛṣṭhavinamanajaṭharonnamanairjaṭhare mūtrasaṅgatṛṇmūrcchotrāsadigvīkṣaṇakhallīhastapādastambhakubjībhavanakeśaluñcanairbastau guhye ca sarvatra ca svabhā vātiriktarodanena mukhavikūṇanena ca" },
      { type: "verse", number: "10", sanskrit: "अथ यथामयं यथादोषं च धात्र्याः शमनशोधनानि प्रयुञ्जीत", text: "atha yathāmayaṃ yathādoṣaṃ ca dhātryāḥ śamanaśodhanāni prayuñjīta" },
      { type: "verse", number: "11", sanskrit: "तत्र वातदूषिते स्तन्ये देवदारुसरलकटुरोहिणीवचाकुष्ठपाठाभार्ङ्गीमागधिकावृश्चिकालीचित्रकाजमोदशुण्ठीमरीचानां क्वाथं दशमूलक्वाथं वा त्रिरात्रं पाययित्वा वातव्याधिविहितानां सर्पिषामन्यतमं निगदमदिरानुपानं दद्याद्वातहरद्रव्यसिद्धं वा ततः स्निग्धां मृदु विरेच्य बस्तिकर्मणोपचरेत् वातघ्नैश्चाभ्यङ्गस्वेदोपदेहोन्मर्दनैः सरलरास्नाजमोदादेवदारुचूर्णं सर्पिषा बालमवलेहयेत् एवंविधैरेव च विपक्वं सशर्करं सर्पिः", text: "tatra vātadūṣite stanye devadārusaralakaṭurohiṇīvacākuṣṭhapāṭhābhārṅgīmāgadhikāvṛścikālīcitrakājamodaśuṇṭhīmarīcānāṃ kvāthaṃ daśamūlakvāthaṃ vā trirātraṃ pāyayitvā vātavyādhivihitānāṃ sarpiṣāmanyatamaṃ nigadamadirānupānaṃ dadyādvātaharadravyasiddhaṃ vā tataḥ snigdhāṃ mṛdu virecya bastikarmaṇopacaret vātaghnaiścābhyaṅgasvedopadehonmardanaiḥ saralarāsnājamodādevadārucūrṇaṃ sarpiṣā bālamavalehayet evaṃvidhaireva ca vipakvaṃ saśarkaraṃ sarpiḥ" },
      { type: "verse", number: "12", sanskrit: "अपि च तिक्तानुरसं स्तन्यं मुद्गमाषपलाशाभ्यां काकोलीयुगलेन च शोधयेत् प्रियङ्गुधातकीपुष्पपद्मकदेवदारुक्षौद्रैर्वा कषायानुरसं हिङ्गुसैन्धववता घृतेन फेनिलं विच्छिन्नं प्लवमानं च बिल्वाग्निमन्थशृतेन पयसा हविषा च सूप्यपर्णी काकोलीबृहत्यवल्गुजफलैर्वा", text: "api ca tiktānurasaṃ stanyaṃ mudgamāṣapalāśābhyāṃ kākolīyugalena ca śodhayet priyaṅgudhātakīpuṣpapadmakadevadārukṣaudrairvā kaṣāyānurasaṃ hiṅgusaindhavavatā ghṛtena phenilaṃ vicchinnaṃ plavamānaṃ ca bilvāgnimanthaśṛtena payasā haviṣā ca sūpyaparṇī kākolībṛhatyavalgujaphalairvā" },
      { type: "verse", number: "13", sanskrit: "पित्ते ऽमृतापटोलपत्रसारिवाशतावरीनिम्बचन्दनक्वाथं धात्री बालश्च पिबेत् त्रिफलाभूनिम्बकटुकामुस्तक्वाथं वा जीवकर्षभकद्विकाकोलीमधुककट्फलकर्कटशृङ्गीक्वाथं वा सक्षौद्रं पटोलादिं पद्मकादिं वा सारिवादिं न्यग्रोधादिं वा एभिरेव च द्रव्यैः सर्पीषि पित्तघ्नानि च विरेचनानि शीतांश्चाभ्यङ्गप्रदेहसेकान् कुर्यात्", text: "pitte 'mṛtāpaṭolapatrasārivāśatāvarīnimbacandanakvāthaṃ dhātrī bālaśca pibet triphalābhūnimbakaṭukāmustakvāthaṃ vā jīvakarṣabhakadvikākolīmadhukakaṭphalakarkaṭaśṛṅgīkvāthaṃ vā sakṣaudraṃ paṭolādiṃ padmakādiṃ vā sārivādiṃ nyagrodhādiṃ vā ebhireva ca dravyaiḥ sarpīṣi pittaghnāni ca virecanāni śītāṃścābhyaṅgapradehasekān kuryāt" },
      { type: "verse", number: "14", sanskrit: "अपि च ताम्रावभासं पयो हृदयमुद्वेष्टयति तत्प्रियङ्गुमुस्ताशाबरलोद्ध्रैः शोधयेत् अम्लानुरसमम्लपित्तकरम् तत् द्राक्षामधुकपयस्याश्रीपर्णीभिः कटुकानुरसं छर्द्यतीसारकासश्वासकरम् तत् काकोलीविदारीभ्यां मधुपर्ण्या च भृशोष्णमनामदाहज्वरकरं विरेचनं च तच्चन्दनोत्पलकमलैः", text: "api ca tāmrāvabhāsaṃ payo hṛdayamudveṣṭayati tatpriyaṅgumustāśābaraloddhraiḥ śodhayet amlānurasamamlapittakaram tat drākṣāmadhukapayasyāśrīparṇībhiḥ kaṭukānurasaṃ chardyatīsārakāsaśvāsakaram tat kākolīvidārībhyāṃ madhuparṇyā ca bhṛśoṣṇamanāmadāhajvarakaraṃ virecanaṃ ca taccandanotpalakamalaiḥ" },
      { type: "verse", number: "15", sanskrit: "कफे तु सैन्धवपिप्पलीयुक्तं सर्पिर्बालं पाययेत् सैन्धवमधुकसंसृष्टं वा मदनपुष्पकल्केन च सक्षौद्रेण स्तनं बालस्य चोष्ठमालिम्पेत् तेन सुखं वमति धात्रीं तु तीक्ष्णैर्वामयेत् ततः कृतसंसर्जनां पञ्चमूलघनवचातिविषाक्वाथं पाययेत् तगरसुरदारुसुरेन्द्रयवपृथ्वीकावृश्चिकालीक्वाथं वा आरग्वधादिं मुस्तादिं वा रूक्षोष्णांश्च नस्यधूमगण्डूषप्रदेहपरिषेकान् शीलयेत् अविरुद्धं चान्नपानं योजयेत्", text: "kaphe tu saindhavapippalīyuktaṃ sarpirbālaṃ pāyayet saindhavamadhukasaṃsṛṣṭaṃ vā madanapuṣpakalkena ca sakṣaudreṇa stanaṃ bālasya coṣṭhamālimpet tena sukhaṃ vamati dhātrīṃ tu tīkṣṇairvāmayet tataḥ kṛtasaṃsarjanāṃ pañcamūlaghanavacātiviṣākvāthaṃ pāyayet tagarasuradārusurendrayavapṛthvīkāvṛścikālīkvāthaṃ vā āragvadhādiṃ mustādiṃ vā rūkṣoṣṇāṃśca nasyadhūmagaṇḍūṣapradehapariṣekān śīlayet aviruddhaṃ cānnapānaṃ yojayet" },
      { type: "verse", number: "16", sanskrit: "अपि च लवणानुरसं विसर्पकोठकण्डूकरम् तत् पिचुमन्दपटोलीक्षीरीवृक्षैः शोधयेत् तन्तुमद्दौर्बल्यश्वासकासकरम् तत् पिप्पलीनागरचूर्णेन समधुघृतेन गुरु सदनात्मकं प्रतिश्यायसिङ्घाणकक्षीरालसककरम् तत् पाठाव्योषकल्केन पञ्चकोलचूर्णेन वा क्षौद्रघृताप्लुतेन दोषोपक्रमणीयं चेक्षेत", text: "api ca lavaṇānurasaṃ visarpakoṭhakaṇḍūkaram tat picumandapaṭolīkṣīrīvṛkṣaiḥ śodhayet tantumaddaurbalyaśvāsakāsakaram tat pippalīnāgaracūrṇena samadhughṛtena guru sadanātmakaṃ pratiśyāyasiṅghāṇakakṣīrālasakakaram tat pāṭhāvyoṣakalkena pañcakolacūrṇena vā kṣaudraghṛtāplutena doṣopakramaṇīyaṃ cekṣeta" },
      { type: "verse", number: "17", sanskrit: "यदा पुनर्धात्री सन्निपातप्रकोपनान्यासेवेत तदस्यास्त्रयो मला युगपद्वक्षो ऽभिप्रपन्नाः क्षीरवहा रसायनीः समनुसृत्य सङ्गीर्णलिङ्गं स्तन्यमावहन्ति तच्चेदविज्ञानात् सततमप्रत्यवेक्षणात् प्रमादाद्वा मातुः कुमारः पिबति ततः स तेन सलिलोपममच्छं विच्छिन्नमामं दुर्गन्धि नानावर्णवेदनं फेनिलमतिसार्यते पीतश्वेतमूत्रताविष्टम्भतृष्णाज्वरच्छर्दिविजृम्भिकाशुष्कोद्गारारुचिभ्रमाङ्गभङ्गविक्षेपकूजनघ्राणाक्षिमुखपाकदृष्ट्युपप्लवस्वरसादादयश्चास्य प्रादुर्भवन्ति तं क्षीरालसकमत्ययं चाचक्षते", text: "yadā punardhātrī sannipātaprakopanānyāseveta tadasyāstrayo malā yugapadvakṣo 'bhiprapannāḥ kṣīravahā rasāyanīḥ samanusṛtya saṅgīrṇaliṅgaṃ stanyamāvahanti taccedavijñānāt satatamapratyavekṣaṇāt pramādādvā mātuḥ kumāraḥ pibati tataḥ sa tena salilopamamacchaṃ vicchinnamāmaṃ durgandhi nānāvarṇavedanaṃ phenilamatisāryate pītaśvetamūtratāviṣṭambhatṛṣṇājvaracchardivijṛmbhikāśuṣkodgārārucibhramāṅgabhaṅgavikṣepakūjanaghrāṇākṣimukhapākadṛṣṭyupaplavasvarasādādayaścāsya prādurbhavanti taṃ kṣīrālasakamatyayaṃ cācakṣate" },
      { type: "verse", number: "18", sanskrit: "तत्र धात्रीं बालं च पूर्वमेवाशु वामयेत् विहितसंसर्गयोश्च मुस्तापाठातिविषाकुष्ठकटुकानां क्वाथं पानाय दद्यात् रास्नाजमोदाप्रियङ्गुभद्रदारूणां वा पाठातेजोवतीपुनर्नववृश्चिकालीनां वा भूनिम्बामृताकुटजफलसारिवाणां वा वचाहरिद्रादिगणयोर्वा पाठादिमहाकषायस्य वा जम्ब्वाम्रतिन्दुककपित्थपत्राणां वा बिल्वभङ्गस्य वा अनुबन्धे च यथाव्याधि प्रतिकुर्वीत", text: "tatra dhātrīṃ bālaṃ ca pūrvamevāśu vāmayet vihitasaṃsargayośca mustāpāṭhātiviṣākuṣṭhakaṭukānāṃ kvāthaṃ pānāya dadyāt rāsnājamodāpriyaṅgubhadradārūṇāṃ vā pāṭhātejovatīpunarnavavṛścikālīnāṃ vā bhūnimbāmṛtākuṭajaphalasārivāṇāṃ vā vacāharidrādigaṇayorvā pāṭhādimahākaṣāyasya vā jambvāmratindukakapitthapatrāṇāṃ vā bilvabhaṅgasya vā anubandhe ca yathāvyādhi pratikurvīta" },
      { type: "verse", number: "19", sanskrit: "दन्तोद्भेदश्च सर्वरोगायतनम् विशेषेण तु तन्मूला ज्वरशिरोभितापतृष्णाभ्रमाभिष्यन्दकुकूणकपोथकीवमथुकासश्वासातीसारविसर्पाः", text: "dantodbhedaśca sarvarogāyatanam viśeṣeṇa tu tanmūlā jvaraśirobhitāpatṛṣṇābhramābhiṣyandakukūṇakapothakīvamathukāsaśvāsātīsāravisarpāḥ" },
      { type: "verse", number: "20", sanskrit: "स दीर्घायुषो ऽष्टमान्मासात् परतो वा प्रवर्तते इतरेषां तु चतुर्थात् तेह्यतिबाल्ये दन्तोत्पादवेदनयातिपीडिता न सम्यक् सम्पूर्णधातुबला भवन्ति", text: "sa dīrghāyuṣo 'ṣṭamānmāsāt parato vā pravartate itareṣāṃ tu caturthāt tehyatibālye dantotpādavedanayātipīḍitā na samyak sampūrṇadhātubalā bhavanti" },
      { type: "verse", number: "21", sanskrit: "तत्रास्थिमज्जानौ दन्तोत्पत्तिहेतू तदा च तयोरसम्पूर्णवीर्यत्वात् पुनः कालान्तरेण दन्तानां पतनमापूर्यमाणधातुत्वाच्च पुनरुत्थानमत एव च वृद्धानां न पुनर्दन्तोत्पत्तिः", text: "tatrāsthimajjānau dantotpattihetū tadā ca tayorasampūrṇavīryatvāt punaḥ kālāntareṇa dantānāṃ patanamāpūryamāṇadhātutvācca punarutthānamata eva ca vṛddhānāṃ na punardantotpattiḥ" },
      { type: "verse", number: "22", sanskrit: "बलान्निपतितानां तु सहसा तदधिष्ठानगतधातुबीजभ्रंशात् सन्ततिव्युच्छेदाच्छोणितातिप्रवृत्याभिघाताच्च निस्सारितत्वात् सिराणां पुनरनुत्पादः एतेन रोगच्युता अपि प्रायशो व्याख्याताः", text: "balānnipatitānāṃ tu sahasā tadadhiṣṭhānagatadhātubījabhraṃśāt santativyucchedācchoṇitātipravṛtyābhighātācca nissāritatvāt sirāṇāṃ punaranutpādaḥ etena rogacyutā api prāyaśo vyākhyātāḥ" },
      { type: "verse", number: "23", sanskrit: "तौ तु धातू कालक्रमेण पच्यमानौ यदा दन्ताशयमनुप्रपद्येते तदास्य किञ्चिदुत्सेधेनोर्ध्वाधोदन्तमांससङ्घट्टनादङ्गहर्षो जायते तद्गतेन च श्लेष्मणा कण्डूस्तया चूचुकं दश्यते यद्यदालभते तत्तदास्यमानयति मारुतश्चास्य दन्तमूलेषु मूर्छति ततः स कफानुविद्धो ऽस्थिमज्जस्थितः सर्वतो विसरन् सह पित्तेन धातून् मलांश्च दूषयन् विविधान्यथोदितानुपद्रवानभिनिर्वर्तयति", text: "tau tu dhātū kālakrameṇa pacyamānau yadā dantāśayamanuprapadyete tadāsya kiñcidutsedhenordhvādhodantamāṃsasaṅghaṭṭanādaṅgaharṣo jāyate tadgatena ca śleṣmaṇā kaṇḍūstayā cūcukaṃ daśyate yadyadālabhate tattadāsyamānayati mārutaścāsya dantamūleṣu mūrchati tataḥ sa kaphānuviddho 'sthimajjasthitaḥ sarvato visaran saha pittena dhātūn malāṃśca dūṣayan vividhānyathoditānupadravānabhinirvartayati" },
      { type: "verse", number: "24", sanskrit: "यदा पुनर्दन्तमांसाश्रयी केवलो विकृतः प्रबलो ऽनिलः सपित्तो वास्थिमज्जानौ शोषयति तदा द्विजानामसम्भव एवेति भवन्ति चात्र", text: "yadā punardantamāṃsāśrayī kevalo vikṛtaḥ prabalo 'nilaḥ sapitto vāsthimajjānau śoṣayati tadā dvijānāmasambhava eveti bhavanti cātra" },
      { type: "verse", number: "25", sanskrit: "पृष्ठभङ्गे बिडालानां बर्हिणां च शिखोद्गमे दन्तोद्भेदे च बालानां न हि किञ्चिन्न दूयते", text: "pṛṣṭhabhaṅge biḍālānāṃ barhiṇāṃ ca śikhodgame dantodbhede ca bālānāṃ na hi kiñcinna dūyate" },
      { type: "verse", number: "26", sanskrit: "यथादोषं यथारोगं यथोद्रेकं यथाबलम् विभज्य देशकालादींस्तत्र योज्यं भिषग्जितम्", text: "yathādoṣaṃ yathārogaṃ yathodrekaṃ yathābalam vibhajya deśakālādīṃstatra yojyaṃ bhiṣagjitam" },
      { type: "verse", number: "27", sanskrit: "त एव दोषा दूष्याश्च ज्वराद्या व्याधयश्च यत् अतस्तदेव भैषज्यं मात्रा त्वस्य कनीयसी सौकुमार्याल्पकायत्वात् सर्वान्नानुपसेवनात्", text: "ta eva doṣā dūṣyāśca jvarādyā vyādhayaśca yat atastadeva bhaiṣajyaṃ mātrā tvasya kanīyasī saukumāryālpakāyatvāt sarvānnānupasevanāt" },
      { type: "verse", number: "28", sanskrit: "स्निग्धा एव सदा बाला घृतक्षीरनिषेवणात् सद्यस्तान् वमनं तस्मात् पाययेन्मतिमान्मृदु", text: "snigdhā eva sadā bālā ghṛtakṣīraniṣevaṇāt sadyastān vamanaṃ tasmāt pāyayenmatimānmṛdu" },
      { type: "verse", number: "29", sanskrit: "बस्तिं साध्ये विरेकेण मर्शेन प्रतिमर्शनम् युञ्ज्याद्विरेचनादींस्तु धात्र्या एव यथोचितान्", text: "bastiṃ sādhye virekeṇa marśena pratimarśanam yuñjyādvirecanādīṃstu dhātryā eva yathocitān" },
      { type: "verse", number: "30", sanskrit: "मूर्वाव्योषवराकोलजम्बूत्वग्दारुसर्षपाः सपाठा मधुना लीढाः स्तन्यदोषहराः परम्", text: "mūrvāvyoṣavarākolajambūtvagdārusarṣapāḥ sapāṭhā madhunā līḍhāḥ stanyadoṣaharāḥ param" },
      { type: "verse", number: "31", sanskrit: "इक्षुमूलकशेर्वाख्ययष्ट्याह्वैस्तनु शुध्यति सान्द्रं तु क्षौद्रकाश्मर्यगुडूचीतण्डुलाम्बुभिः", text: "ikṣumūlakaśervākhyayaṣṭyāhvaistanu śudhyati sāndraṃ tu kṣaudrakāśmaryaguḍūcītaṇḍulāmbubhiḥ" },
      { type: "verse", number: "32", sanskrit: "शृतैर्वा सुरसश्वेतसर्षपाबृहतीद्वयैः ग्रथितं पद्मकोशीरफलिनीश्वेतचन्दनैः", text: "śṛtairvā surasaśvetasarṣapābṛhatīdvayaiḥ grathitaṃ padmakośīraphalinīśvetacandanaiḥ" },
      { type: "verse", number: "33", sanskrit: "दन्तपालीं समधुना चूर्णेन प्रतिसारयेत् पिप्पल्या धातकीपुष्पधात्रीफलकृतेन वा", text: "dantapālīṃ samadhunā cūrṇena pratisārayet pippalyā dhātakīpuṣpadhātrīphalakṛtena vā" },
      { type: "verse", number: "34", sanskrit: "वाध्रीणसकपोतोत्थरजस्तद्वच्च योजितम् लावतित्तिरिवल्लूररजः पुष्परसद्रुतम्", text: "vādhrīṇasakapotottharajastadvacca yojitam lāvatittirivallūrarajaḥ puṣparasadrutam" },
      { type: "verse", number: "35", sanskrit: "द्रुतं करोति बालानां दन्तकेसरवन्मुखम् वचाद्विबृहतीपाठाकटुकातिविषाघनैः मधुरैश्च घृतं सिद्धं सिद्धं दशनजन्मनि", text: "drutaṃ karoti bālānāṃ dantakesaravanmukham vacādvibṛhatīpāṭhākaṭukātiviṣāghanaiḥ madhuraiśca ghṛtaṃ siddhaṃ siddhaṃ daśanajanmani" },
      { type: "verse", number: "36", sanskrit: "भद्रदारु घनं यष्टी समङ्गा ससितोपला वातज्वरपरीताङ्गः पिबेदन्तरपानकम्", text: "bhadradāru ghanaṃ yaṣṭī samaṅgā sasitopalā vātajvaraparītāṅgaḥ pibedantarapānakam" },
      { type: "verse", number: "37", sanskrit: "सुराह्वघनयष्ट्याह्वपयस्यांशुमतीद्वयम् नागरं मरिचं भार्ङ्गी वृश्चिकाली शतावरी", text: "surāhvaghanayaṣṭyāhvapayasyāṃśumatīdvayam nāgaraṃ maricaṃ bhārṅgī vṛścikālī śatāvarī" },
      { type: "verse", number: "38", sanskrit: "घृतं तत्क्वाथदुग्धाभ्यां सिद्धं हन्त्यनिलज्वरम् बालस्य पानाभ्यङ्गाभ्यामेभिश्चोन्मर्दनं हितम्", text: "ghṛtaṃ tatkvāthadugdhābhyāṃ siddhaṃ hantyanilajvaram bālasya pānābhyaṅgābhyāmebhiśconmardanaṃ hitam" },
      { type: "verse", number: "39", sanskrit: "हरिद्राकुष्ठषङ्ग्रन्थाशतपुष्पाहरेणुभिः भार्ङ्ग्येलासुषवीरास्नावर्षाभूनतसर्षपैः", text: "haridrākuṣṭhaṣaṅgranthāśatapuṣpāhareṇubhiḥ bhārṅgyelāsuṣavīrāsnāvarṣābhūnatasarṣapaiḥ" },
      { type: "verse", number: "40", sanskrit: "अक्षांशैः साम्बुसौवीरैर्मस्तुपिष्टैर्मरुज्ज्वरे तैलप्रस्थं सुरामण्डतुल्यमभ्यञ्जनं पचेत्", text: "akṣāṃśaiḥ sāmbusauvīrairmastupiṣṭairmarujjvare tailaprasthaṃ surāmaṇḍatulyamabhyañjanaṃ pacet" },
      { type: "verse", number: "41", sanskrit: "लाजनीलोत्पलकणामधुकाञ्जनशर्करम् पित्तज्वरमतीसारं मधुलीढं निवर्तयेत्", text: "lājanīlotpalakaṇāmadhukāñjanaśarkaram pittajvaramatīsāraṃ madhulīḍhaṃ nivartayet" },
      { type: "verse", number: "42", sanskrit: "लाजद्विपिप्पलीक्वाथः शर्करामधुसंयुतः पीतो ज्वरमतीसारं तृष्णां छर्दिं च नाशयेत्", text: "lājadvipippalīkvāthaḥ śarkarāmadhusaṃyutaḥ pīto jvaramatīsāraṃ tṛṣṇāṃ chardiṃ ca nāśayet" },
      { type: "verse", number: "43", sanskrit: "आमातिसारे रक्ते च कल्कितां गजपिप्पलीम् पाययेच्छर्करोपेतां चूर्णं वा देवदारुजम्", text: "āmātisāre rakte ca kalkitāṃ gajapippalīm pāyayeccharkaropetāṃ cūrṇaṃ vā devadārujam" },
      { type: "verse", number: "44", sanskrit: "शिरोभितापे सघृतैः शिरः शीतैः प्रलेपयेत् पत्रैः कपित्थचाङ्गेरीबदरीकाकमाचिजैः", text: "śirobhitāpe saghṛtaiḥ śiraḥ śītaiḥ pralepayet patraiḥ kapitthacāṅgerībadarīkākamācijaiḥ" },
      { type: "verse", number: "45", sanskrit: "शिरोरुक्च्छर्द्यतीसारनाशनं मूर्धलेपनम् गवादनीं दाडिमं च तृड्वान् कोष्णाम्भसा पिबेत्", text: "śirorukcchardyatīsāranāśanaṃ mūrdhalepanam gavādanīṃ dāḍimaṃ ca tṛḍvān koṣṇāmbhasā pibet" },
      { type: "verse", number: "46", sanskrit: "कुर्यात् कुकूणपोथक्योर्यथोक्तं स्वं स्वमौषधम् मनश्शिलाशङ्खनाभिः पिप्पल्यो मधुयष्टिका", text: "kuryāt kukūṇapothakyoryathoktaṃ svaṃ svamauṣadham manaśśilāśaṅkhanābhiḥ pippalyo madhuyaṣṭikā" },
      { type: "verse", number: "47", sanskrit: "क्षौद्रेण घृष्टा गुलिका शिशोः सर्वाक्षिरोगजित् पिप्पलीतण्डुलैर्मुद्गैः सुमनःकोरकैर्यवैः नीलोत्पलस्य पत्रैश्च श्रेष्ठा वर्तिः शतोन्मितैः", text: "kṣaudreṇa ghṛṣṭā gulikā śiśoḥ sarvākṣirogajit pippalītaṇḍulairmudgaiḥ sumanaḥkorakairyavaiḥ nīlotpalasya patraiśca śreṣṭhā vartiḥ śatonmitaiḥ" },
      { type: "verse", number: "48", sanskrit: "प्रियङ्ग्वञ्जनमुस्तानां चूर्णस्तण्डुलवारिणा तृष्णातीसारवमथून् हन्ति पीतः समाक्षिकः", text: "priyaṅgvañjanamustānāṃ cūrṇastaṇḍulavāriṇā tṛṣṇātīsāravamathūn hanti pītaḥ samākṣikaḥ" },
      { type: "verse", number: "49", sanskrit: "पटोलनिम्बकुटजसप्तपर्णं सदीप्यकम् देवदारुविडङ्गानि सरलो माक्षिकं घृतम्", text: "paṭolanimbakuṭajasaptaparṇaṃ sadīpyakam devadāruviḍaṅgāni saralo mākṣikaṃ ghṛtam" },
      { type: "verse", number: "50", sanskrit: "लीढं ज्वरमतीसारं कासं पाण्ड्वामयं वमिम् हन्याच्च मातृकादोषान् रोगानन्यांश्च तद्विधान्", text: "līḍhaṃ jvaramatīsāraṃ kāsaṃ pāṇḍvāmayaṃ vamim hanyācca mātṛkādoṣān rogānanyāṃśca tadvidhān" },
      { type: "verse", number: "51", sanskrit: "मधुकव्योषषड्ग्रन्थाग्रन्थिकास्पृष्टरोदिकाः क्षीरिणां च प्रवालानि पाठा च विपचेत् घृतम् तत् पीतं समधु श्लेष्मज्वरघ्नं दीपनं परम्", text: "madhukavyoṣaṣaḍgranthāgranthikāspṛṣṭarodikāḥ kṣīriṇāṃ ca pravālāni pāṭhā ca vipacet ghṛtam tat pītaṃ samadhu śleṣmajvaraghnaṃ dīpanaṃ param" },
      { type: "verse", number: "52", sanskrit: "रास्नैलानततर्कारीमधुशिग्रुसुराह्वयैः सबिल्वकुष्ठवरणरेणुकामिसिभिः कृतः", text: "rāsnailānatatarkārīmadhuśigrusurāhvayaiḥ sabilvakuṣṭhavaraṇareṇukāmisibhiḥ kṛtaḥ" },
      { type: "verse", number: "53", sanskrit: "श्लेष्मज्वरहरो लेपस्तैलमभ्यञ्जनं च तैः मण्डलानि तु साज्येन गजमूत्रेण लेपयेत्", text: "śleṣmajvaraharo lepastailamabhyañjanaṃ ca taiḥ maṇḍalāni tu sājyena gajamūtreṇa lepayet" },
      { type: "verse", number: "54", sanskrit: "रजनी दारु सरलश्रेयसी बृहतीद्वयम् पृश्निपर्णी शताह्वा च लीढं माक्षिकसर्पिषा ग्रहणीदीपनं श्रेष्ठं मारुतस्यानुलोमनम्", text: "rajanī dāru saralaśreyasī bṛhatīdvayam pṛśniparṇī śatāhvā ca līḍhaṃ mākṣikasarpiṣā grahaṇīdīpanaṃ śreṣṭhaṃ mārutasyānulomanam" },
      { type: "verse", number: "55", sanskrit: "अतीसारज्वरश्वासकामलापाण्डुकासजित् बालस्य सर्वरोगेषु पूजितं बलवर्णदम्", text: "atīsārajvaraśvāsakāmalāpāṇḍukāsajit bālasya sarvarogeṣu pūjitaṃ balavarṇadam" },
      { type: "verse", number: "56", sanskrit: "बिल्वपेशीगजकणाधातकीलोध्रवालकम् हन्ति लीढमतीसारं शिशोः क्षौद्रद्रुतं द्रुतम्", text: "bilvapeśīgajakaṇādhātakīlodhravālakam hanti līḍhamatīsāraṃ śiśoḥ kṣaudradrutaṃ drutam" },
      { type: "verse", number: "57", sanskrit: "त्रिफलाधातकीपुष्पपद्मबिल्वशलाटुभिः सक्ट्वङ्गैर्घृतं सिद्धमुदरामयनाशनम्", text: "triphalādhātakīpuṣpapadmabilvaśalāṭubhiḥ sakṭvaṅgairghṛtaṃ siddhamudarāmayanāśanam" },
      { type: "verse", number: "58", sanskrit: "पथ्यासौवर्चलक्षारवेल्लव्योषाग्निहिङ्गुभिः तिक्तया च घृतं सिद्धं समक्षीरं व्यपोहति शूलानाहगुदभ्रंशश्वासकासविलम्बिकाः", text: "pathyāsauvarcalakṣāravellavyoṣāgnihiṅgubhiḥ tiktayā ca ghṛtaṃ siddhaṃ samakṣīraṃ vyapohati śūlānāhagudabhraṃśaśvāsakāsavilambikāḥ" },
      { type: "verse", number: "59", sanskrit: "समङ्गाधातकीलोध्रकुटन्नटबलाद्वयैः महासहाक्षुद्रसहामुद्गबिल्वशलाटुभिः", text: "samaṅgādhātakīlodhrakuṭannaṭabalādvayaiḥ mahāsahākṣudrasahāmudgabilvaśalāṭubhiḥ" },
      { type: "verse", number: "60", sanskrit: "सकार्पासीफलैस्तोये साधितैः साधितं घृतम् क्षारमस्तुयुतं हन्ति शीघ्रं दन्तोद्भवोद्भवान् विविधानामयानेतद्वृद्धकाश्यपनिर्मितम्", text: "sakārpāsīphalaistoye sādhitaiḥ sādhitaṃ ghṛtam kṣāramastuyutaṃ hanti śīghraṃ dantodbhavodbhavān vividhānāmayānetadvṛddhakāśyapanirmitam" },
      { type: "verse", number: "61", sanskrit: "दन्तोद्भेदोत्थरोगेषु न बालमतियन्त्रयेत् स्वयमाप्युपशाम्यन्ति जातदन्तस्य यत् गदाः", text: "dantodbhedottharogeṣu na bālamatiyantrayet svayamāpyupaśāmyanti jātadantasya yat gadāḥ" },
      { type: "verse", number: "62", sanskrit: "यावन्मासस्य यो जातस्तावद्वर्षस्य स द्विजः पतति प्रायशो ऽष्टानां तेषां पूर्वेषु सम्भवः", text: "yāvanmāsasya yo jātastāvadvarṣasya sa dvijaḥ patati prāyaśo 'ṣṭānāṃ teṣāṃ pūrveṣu sambhavaḥ" },
      { type: "verse", number: "63", sanskrit: "अत्यहःस्वप्नशीताम्बुश्लैष्मिकस्तन्यसेविनः शिशोः कफेन रुद्धेषु स्रोतस्सु रसवाहिषु", text: "atyahaḥsvapnaśītāmbuślaiṣmikastanyasevinaḥ śiśoḥ kaphena ruddheṣu srotassu rasavāhiṣu" },
      { type: "verse", number: "64", sanskrit: "अरोचकः प्रतिश्यायो ज्वरः कासश्च जायते कुमारः शुष्यति ततः स्निग्धशुक्लमुखेक्षणः", text: "arocakaḥ pratiśyāyo jvaraḥ kāsaśca jāyate kumāraḥ śuṣyati tataḥ snigdhaśuklamukhekṣaṇaḥ" },
      { type: "verse", number: "65", sanskrit: "सैन्धवव्योषशाअर्ङ्गेष्टअपाठागिरिकदम्बकान् शुष्यतो मधुसर्पिर्भ्यामरुच्यादिषु योजयेत्", text: "saindhavavyoṣaśāarṅgeṣṭAapāṭhāgirikadambakān śuṣyato madhusarpirbhyāmarucyādiṣu yojayet" },
      { type: "verse", number: "66", sanskrit: "अशोकरोहिणीयुक्तं पञ्चकोलं च चूर्णितम् बदरीधातकीधात्रीचूर्णं वा सर्पिषा द्रुतम्", text: "aśokarohiṇīyuktaṃ pañcakolaṃ ca cūrṇitam badarīdhātakīdhātrīcūrṇaṃ vā sarpiṣā drutam" },
      { type: "verse", number: "67", sanskrit: "अश्वलिण्डरसक्षौद्रयुक्तां वा मधुयष्टिकाम् द्विवार्ताकीफलरसं केवलं वाश्वविड्रसम्", text: "aśvaliṇḍarasakṣaudrayuktāṃ vā madhuyaṣṭikām dvivārtākīphalarasaṃ kevalaṃ vāśvaviḍrasam" },
      { type: "verse", number: "68", sanskrit: "मधुना वा घनव्योषपाठा मूर्वा शतावरी सपयस्या पृथक्पर्णी घृतं वा माक्षिकान्वितम् स्थिरामरतरुव्योषद्विपुनर्नवसाधितम्", text: "madhunā vā ghanavyoṣapāṭhā mūrvā śatāvarī sapayasyā pṛthakparṇī ghṛtaṃ vā mākṣikānvitam sthirāmarataruvyoṣadvipunarnavasādhitam" },
      { type: "verse", number: "69", sanskrit: "स्थिरावचाद्विबृहतीकाकोलीपिप्पलीनतैः निचुलोत्पलवर्षाभूभार्ङ्गीमुस्तैश्च कार्षिकैः", text: "sthirāvacādvibṛhatīkākolīpippalīnataiḥ niculotpalavarṣābhūbhārṅgīmustaiśca kārṣikaiḥ" },
      { type: "verse", number: "70", sanskrit: "सिद्धं प्रस्थार्धमाज्यस्य स्रोतसां शोधनं परम् सिंह्यश्वगन्धासुरसकणागर्भं च तद्गुणम्", text: "siddhaṃ prasthārdhamājyasya srotasāṃ śodhanaṃ param siṃhyaśvagandhāsurasakaṇāgarbhaṃ ca tadguṇam" },
      { type: "verse", number: "71", sanskrit: "यष्ट्याह्वपिप्पलीलोध्रपद्मकोत्पलचन्दनैः तालीससारिवाभ्यां च साधितं शोषजित् घृतम्", text: "yaṣṭyāhvapippalīlodhrapadmakotpalacandanaiḥ tālīsasārivābhyāṃ ca sādhitaṃ śoṣajit ghṛtam" },
      { type: "verse", number: "72", sanskrit: "रास्नामधूलिकाभार्ङ्गीपिप्पलीदेवदारुभिः अश्वगन्धाद्विकाकोली शृङ्ग्यर्षभकजीवैकः", text: "rāsnāmadhūlikābhārṅgīpippalīdevadārubhiḥ aśvagandhādvikākolī śṛṅgyarṣabhakajīvaikaḥ" },
      { type: "verse", number: "73", sanskrit: "सूप्यपर्णीविडङ्गैश्च कल्कितैः साधितं घृतम् शशोत्तमाङ्गनिर्यूहे शुष्यतः पुष्टिकृत् परम्", text: "sūpyaparṇīviḍaṅgaiśca kalkitaiḥ sādhitaṃ ghṛtam śaśottamāṅganiryūhe śuṣyataḥ puṣṭikṛt param" },
      { type: "verse", number: "74", sanskrit: "वचावयस्थातगरकायस्थाचोरकैः शृतम् बस्तमूत्रसुराभ्यां च तैलमभ्यञ्जने हितम्", text: "vacāvayasthātagarakāyasthācorakaiḥ śṛtam bastamūtrasurābhyāṃ ca tailamabhyañjane hitam" },
      { type: "verse", number: "75", sanskrit: "द्वे बले तुम्बुरुच्छल्ली वचा गिरिकदम्बकः सुरापिष्टः प्रदेहः स्यादधःकाये विशुष्यताम्", text: "dve bale tumburucchallī vacā girikadambakaḥ surāpiṣṭaḥ pradehaḥ syādadhaḥkāye viśuṣyatām" },
      { type: "verse", number: "76", sanskrit: "सिंहस्कन्दीसिंहवल्लीकरमर्दीत्रिकण्टकैः भङ्गैः क्वाथः कुमाराणां शुष्यतां परिषेचनम्", text: "siṃhaskandīsiṃhavallīkaramardītrikaṇṭakaiḥ bhaṅgaiḥ kvāthaḥ kumārāṇāṃ śuṣyatāṃ pariṣecanam" },
      { type: "verse", number: "77", sanskrit: "साशोकरोहिणीं कृष्णां मध्वाज्येन लिहन्जयेत् शिशुः शोषं शरीरस्य ससितच्छागदुग्धभुक्", text: "sāśokarohiṇīṃ kṛṣṇāṃ madhvājyena lihanjayet śiśuḥ śoṣaṃ śarīrasya sasitacchāgadugdhabhuk" },
      { type: "verse", number: "78", sanskrit: "शुष्ककासे कुमारस्य धात्र्याः स्तन्यविशोधनः माषयूषः प्रयोक्तव्यः सकृष्णो घृतभर्जितः", text: "śuṣkakāse kumārasya dhātryāḥ stanyaviśodhanaḥ māṣayūṣaḥ prayoktavyaḥ sakṛṣṇo ghṛtabharjitaḥ" },
      { type: "verse", number: "79", sanskrit: "मधुनातिविषाशृङ्गीपिप्पलीर्लेहयेच्छिशुम् एकांवातिविषां कासज्वरच्छर्दिरुपद्रुतम्", text: "madhunātiviṣāśṛṅgīpippalīrlehayecchiśum ekāṃvātiviṣāṃ kāsajvaracchardirupadrutam" },
      { type: "verse", number: "80", sanskrit: "कासतृट्च्छर्द्यतीसारैरर्दितं लाजतर्पणम् लाजतालीसपत्रं वा बीजानि कमलस्य वा", text: "kāsatṛṭcchardyatīsārairarditaṃ lājatarpaṇam lājatālīsapatraṃ vā bījāni kamalasya vā" },
      { type: "verse", number: "81", sanskrit: "लोध्रप्रियङ्गुकल्कं वा पाययेत्तण्डुलाम्भसा शर्करामधुसंयुक्तं लाजकुस्तुम्बरीरजः", text: "lodhrapriyaṅgukalkaṃ vā pāyayettaṇḍulāmbhasā śarkarāmadhusaṃyuktaṃ lājakustumbarīrajaḥ" },
      { type: "verse", number: "82", sanskrit: "बृहतीफलमूलत्वक्पिप्पलीग्रन्थिकैः कृतः तवक्षीरीयुतैः क्वाथो मधुना हन्ति शीलितः", text: "bṛhatīphalamūlatvakpippalīgranthikaiḥ kṛtaḥ tavakṣīrīyutaiḥ kvātho madhunā hanti śīlitaḥ" },
      { type: "verse", number: "83", sanskrit: "छर्दिमूर्छाज्वरश्वासकासातीसारपीनसान् पञ्चकोलद्विवार्ताकीमूलभार्ङ्गीतुगाह्वयाः", text: "chardimūrchājvaraśvāsakāsātīsārapīnasān pañcakoladvivārtākīmūlabhārṅgītugāhvayāḥ" },
      { type: "verse", number: "84", sanskrit: "क्षौद्राज्यलीढाः श्वसनकासपीनसरुक्च्छिदः श्यामातिमुक्तातर्कारीकुसुमक्वाथसाधितम् यष्टीगर्भं घृतं तृष्णाहिध्माश्वासास्रपित्तनुत्", text: "kṣaudrājyalīḍhāḥ śvasanakāsapīnasarukcchidaḥ śyāmātimuktātarkārīkusumakvāthasādhitam yaṣṭīgarbhaṃ ghṛtaṃ tṛṣṇāhidhmāśvāsāsrapittanut" },
      { type: "verse", number: "85", sanskrit: "पीतं पीतं वमति यः स्तन्यं तं मधुसर्पिषा द्विवार्ताकीफलरसं पञ्चकोलं च लेहयेत्", text: "pītaṃ pītaṃ vamati yaḥ stanyaṃ taṃ madhusarpiṣā dvivārtākīphalarasaṃ pañcakolaṃ ca lehayet" },
      { type: "verse", number: "86", sanskrit: "पिप्पलीपञ्चलवणं कृमिजित् पारिभद्रकम् तद्वल्लिह्यात्तथा व्योषं मषीं वा रोमचर्मणाम् लाभतःशल्यकश्वाविड्गोधर्ष्यशिखिजन्मनाम्", text: "pippalīpañcalavaṇaṃ kṛmijit pāribhadrakam tadvallihyāttathā vyoṣaṃ maṣīṃ vā romacarmaṇām lābhataḥśalyakaśvāviḍgodharṣyaśikhijanmanām" },
      { type: "verse", number: "87", sanskrit: "खदिरार्जुनतालीसकुष्ठचन्दनजे रसे सक्षीरं साधितं सर्पिर्वमथुं विनियच्छति", text: "khadirārjunatālīsakuṣṭhacandanaje rase sakṣīraṃ sādhitaṃ sarpirvamathuṃ viniyacchati" },
      { type: "verse", number: "88", sanskrit: "क्षीरीप्रवालमधुकदर्भमूलबिसोत्पलैः तृष्णादाहज्वरहरः कषायः ससितामधुः", text: "kṣīrīpravālamadhukadarbhamūlabisotpalaiḥ tṛṣṇādāhajvaraharaḥ kaṣāyaḥ sasitāmadhuḥ" },
      { type: "verse", number: "89", sanskrit: "शर्करादाडिमकणानागकेसरजीवकम् लिहन् कुमारः क्षौद्रेण तृट्च्छर्दिभ्यां विमुच्याते", text: "śarkarādāḍimakaṇānāgakesarajīvakam lihan kumāraḥ kṣaudreṇa tṛṭcchardibhyāṃ vimucyāte" },
      { type: "verse", number: "90", sanskrit: "लाजैः सचन्दनोशीरयष्टीमधुकपद्मकैः लिप्तो धौतः स्तनः पीतो भ्रमतृड्दाहमोहहा", text: "lājaiḥ sacandanośīrayaṣṭīmadhukapadmakaiḥ lipto dhautaḥ stanaḥ pīto bhramatṛḍdāhamohahā" },
      { type: "verse", number: "91", sanskrit: "अस्नेहलवणं पीत्वा संस्कृतं लावजं रसम् सशर्करं विजयते बालो लङ्घनजान् गदान्", text: "asnehalavaṇaṃ pītvā saṃskṛtaṃ lāvajaṃ rasam saśarkaraṃ vijayate bālo laṅghanajān gadān" },
      { type: "verse", number: "92", sanskrit: "विसर्पस्तु शिशोः प्राणनाशनो बस्तिशीर्षजः पद्मवर्णो महापद्मनामा दोषत्रयोद्भवः", text: "visarpastu śiśoḥ prāṇanāśano bastiśīrṣajaḥ padmavarṇo mahāpadmanāmā doṣatrayodbhavaḥ" },
      { type: "verse", number: "93", sanskrit: "शाखाभ्यां हृदयं याति हृदयाद्वा गुदं व्रजेत् सदन्तो जायते यस्तु दन्ताः प्राग्यस्य चोत्तराः", text: "śākhābhyāṃ hṛdayaṃ yāti hṛdayādvā gudaṃ vrajet sadanto jāyate yastu dantāḥ prāgyasya cottarāḥ" },
      { type: "verse", number: "94", sanskrit: "कुर्वीत तस्मिन्नुत्पाते शान्तिं तं च द्विजतये दद्यात् सदक्षिणं बालं नैगमेषं च पूजयेत्", text: "kurvīta tasminnutpāte śāntiṃ taṃ ca dvijataye dadyāt sadakṣiṇaṃ bālaṃ naigameṣaṃ ca pūjayet" },
      { type: "verse", number: "95", sanskrit: "वत्सस्य मधुलाजानामापूर्यप्राङ्मुखो मुखम् चुम्बेत्कुमारस्त्रीन् वारान् प्रायश्चित्तमिदं परम्", text: "vatsasya madhulājānāmāpūryaprāṅmukho mukham cumbetkumārastrīn vārān prāyaścittamidaṃ param" },
      { type: "verse", number: "96", sanskrit: "नावमारोहयेत् बालं स्नातं स्कन्धं गजस्य वा भोजयेत् ब्राह्मणांश्चात्र पायसं मधुसर्पिषा", text: "nāvamārohayet bālaṃ snātaṃ skandhaṃ gajasya vā bhojayet brāhmaṇāṃścātra pāyasaṃ madhusarpiṣā" },
      { type: "verse", number: "97", sanskrit: "मातुः कुमारो गर्भिण्याः स्तन्यं प्रायो ऽपिबन्नपि कासाग्निसादवमथुतन्द्राकार्श्यारुचिभ्रमैः", text: "mātuḥ kumāro garbhiṇyāḥ stanyaṃ prāyo 'pibannapi kāsāgnisādavamathutandrākārśyārucibhramaiḥ" },
      { type: "verse", number: "98", sanskrit: "युज्यते कोष्ठवृध्या च तमाहुः पारिगर्भिकम् रोगं परिभवाख्यं च युञ्ज्यात्तत्राग्निदीपनम्", text: "yujyate koṣṭhavṛdhyā ca tamāhuḥ pārigarbhikam rogaṃ paribhavākhyaṃ ca yuñjyāttatrāgnidīpanam" },
      { type: "verse", number: "99", sanskrit: "पिप्पलीपिप्पलीमूलकटुकादेवदारुभिः क्षारद्वयबिडाजाजीबिल्वमध्याग्निदीप्यकैः", text: "pippalīpippalīmūlakaṭukādevadārubhiḥ kṣāradvayabiḍājājībilvamadhyāgnidīpyakaiḥ" },
      { type: "verse", number: "100", sanskrit: "दधिसौवीरकसुरामण्डैश्च विपचेत् घृतम् हन्ति प्रयुक्तं तत् काले रोगान् पारिभवाश्रयान्", text: "dadhisauvīrakasurāmaṇḍaiśca vipacet ghṛtam hanti prayuktaṃ tat kāle rogān pāribhavāśrayān" },
      { type: "verse", number: "101", sanskrit: "अन्नेनोपहितं स्तन्यं पिबतो विहितात् परम् इमानेव गदान् कुर्यात् कुर्यात्तेष्वेतदेव च", text: "annenopahitaṃ stanyaṃ pibato vihitāt param imāneva gadān kuryāt kuryātteṣvetadeva ca" },
      { type: "verse", number: "102", sanskrit: "पीतं पीतं च यः स्तन्यं सवातमतिसर्यते तस्याप्येतत् परं पथ्यं दीपनं बलवर्णकृत्", text: "pītaṃ pītaṃ ca yaḥ stanyaṃ savātamatisaryate tasyāpyetat paraṃ pathyaṃ dīpanaṃ balavarṇakṛt" },
      { type: "verse", number: "103", sanskrit: "अत्युद्रिक्तक्षुधं बालं परिभूतं तु लेहयेत् विदारीयवगोधूमकणाचूर्णं घृताप्लुतम्", text: "atyudriktakṣudhaṃ bālaṃ paribhūtaṃ tu lehayet vidārīyavagodhūmakaṇācūrṇaṃ ghṛtāplutam" },
      { type: "verse", number: "104", sanskrit: "पाययेदनु च क्षीरं शृतं समधुशर्करम् अक्षमज्जाद्विकाकोलीयष्टीमधुकमोरटैः", text: "pāyayedanu ca kṣīraṃ śṛtaṃ samadhuśarkaram akṣamajjādvikākolīyaṣṭīmadhukamoraṭaiḥ" },
      { type: "verse", number: "105", sanskrit: "श्रपयेत् क्षीरमाज्यं वा बीजैरिक्षुरकस्य च तत् प्रयोज्यं गुरु स्निग्धं यच्चात्यग्नौ पुरेरितम्", text: "śrapayet kṣīramājyaṃ vā bījairikṣurakasya ca tat prayojyaṃ guru snigdhaṃ yaccātyagnau pureritam" },
      { type: "verse", number: "106", sanskrit: "श्ववायसबिडालानामुच्छिष्टेन जलेन च स्नापयेत्तं नचेदेवं क्षुत्तस्य प्रशमं वरजेत्", text: "śvavāyasabiḍālānāmucchiṣṭena jalena ca snāpayettaṃ nacedevaṃ kṣuttasya praśamaṃ varajet" },
      { type: "verse", number: "107", sanskrit: "क्षीरिपादपमूलस्थं विधिना स्नापितं ततः वस्त्ररत्नाद्यलङ्कारैः कुमारं भूषयेत् सितैः", text: "kṣīripādapamūlasthaṃ vidhinā snāpitaṃ tataḥ vastraratnādyalaṅkāraiḥ kumāraṃ bhūṣayet sitaiḥ" },
      { type: "verse", number: "108", sanskrit: "वृक्षं चानु ततः कुर्यात् भूषणव्यत्ययं तयोः एतदायुःप्रदं धन्यं स्नपनं सर्वरोगजित्", text: "vṛkṣaṃ cānu tataḥ kuryāt bhūṣaṇavyatyayaṃ tayoḥ etadāyuḥpradaṃ dhanyaṃ snapanaṃ sarvarogajit" },
      { type: "verse", number: "109", sanskrit: "जटीभूतकचाक्ष्यादिपक्ष्माणमतिलोलुपम् गोमूत्रगन्धिं स्नपयेतीर्थे गव्यशकृद्रसैः", text: "jaṭībhūtakacākṣyādipakṣmāṇamatilolupam gomūtragandhiṃ snapayetīrthe gavyaśakṛdrasaiḥ" },
      { type: "verse", number: "110", sanskrit: "वचापुष्पशिलाकुष्ठवयस्थाहिङ्गुकट्फलैः सबस्तमूत्रमदिरैस्तैलमभ्यञ्जनं पचेत्", text: "vacāpuṣpaśilākuṣṭhavayasthāhiṅgukaṭphalaiḥ sabastamūtramadiraistailamabhyañjanaṃ pacet" },
      { type: "verse", number: "111", sanskrit: "बलाविदारीत्रिकटुककुष्ठोशीरकुचन्दनैः सिद्धं पीतं हविर्हन्ति तं विकारमशेषतः", text: "balāvidārītrikaṭukakuṣṭhośīrakucandanaiḥ siddhaṃ pītaṃ havirhanti taṃ vikāramaśeṣataḥ" },
      { type: "verse", number: "112", sanskrit: "शिरः पृष्ठं ततो मुष्कौ ततः पादौ च यो रुजेत् हस्ताभ्यामुत्थितो वायुः सपर्वानुप्लवः स्मृतः", text: "śiraḥ pṛṣṭhaṃ tato muṣkau tataḥ pādau ca yo rujet hastābhyāmutthito vāyuḥ saparvānuplavaḥ smṛtaḥ" },
      { type: "verse", number: "113", sanskrit: "गौरीवचासदापुष्पीहयगन्धाकटुत्रयैः सक्ट्फलद्विवार्ताकीवयस्थाहिङ्गुरोहिषैः", text: "gaurīvacāsadāpuṣpīhayagandhākaṭutrayaiḥ sakṭphaladvivārtākīvayasthāhiṅgurohiṣaiḥ" },
      { type: "verse", number: "114", sanskrit: "बस्तमूत्रसुरायुक्तैः साधितं तस्य योजयेत् तैलमभ्यञ्जने शेषं वातव्याधिवदाचरेत्", text: "bastamūtrasurāyuktaiḥ sādhitaṃ tasya yojayet tailamabhyañjane śeṣaṃ vātavyādhivadācaret" },
      { type: "verse", number: "115", sanskrit: "तालुमांसे कफः क्रुद्धः कुरुते तालुकण्टकम् तेन तालुप्रदेशस्य निम्नता मूर्ध्नि जायते", text: "tālumāṃse kaphaḥ kruddhaḥ kurute tālukaṇṭakam tena tālupradeśasya nimnatā mūrdhni jāyate" },
      { type: "verse", number: "116", sanskrit: "ताल्पातः स्तनद्वेषः कृच्छ्रात् पानं शकृद्द्रवम् तृडास्यकण्ड्वक्षिरुजा ग्रीवादुर्धरता वमिः", text: "tālpātaḥ stanadveṣaḥ kṛcchrāt pānaṃ śakṛddravam tṛḍāsyakaṇḍvakṣirujā grīvādurdharatā vamiḥ" },
      { type: "verse", number: "117", sanskrit: "तत्रोत्क्षिप्य यवक्षारक्षौद्राभ्यां प्रतिसारयेत् तालु तद्वत् कृअणाशुण्ठीगोशकृद्रससैन्धवैः", text: "tatrotkṣipya yavakṣārakṣaudrābhyāṃ pratisārayet tālu tadvat kṛaṇāśuṇṭhīgośakṛdrasasaindhavaiḥ" },
      { type: "verse", number: "118", sanskrit: "शृङ्गिवेरनिशाकुष्ठं कल्कितं वटपल्लवैः बध्वा गोशकृता लिप्तं कुकूले स्वेदयेत्ततः", text: "śṛṅgiveraniśākuṣṭhaṃ kalkitaṃ vaṭapallavaiḥ badhvā gośakṛtā liptaṃ kukūle svedayettataḥ" },
      { type: "verse", number: "119", sanskrit: "रसेन लिम्पेत्ताल्वास्यं नेत्रे च परिषेचयेत् हरीतकीवचाकुष्ठकल्कं माक्षिकसंयुतम् पीत्वा कुमारः स्तन्येन मुच्यते तालुकण्टकात्", text: "rasena limpettālvāsyaṃ netre ca pariṣecayet harītakīvacākuṣṭhakalkaṃ mākṣikasaṃyutam pītvā kumāraḥ stanyena mucyate tālukaṇṭakāt" },
      { type: "verse", number: "120", sanskrit: "मस्तुलुङ्गक्षयाद्यस्य वायुस्ताल्वस्थि नामयेत् तस्य तृड्दैन्ययुक्तस्य सर्पिर्मधुरकैः शृतम् पानाभ्यञ्जनयोर्योज्यमुद्वेगश्चहिमाम्बुना", text: "mastuluṅgakṣayādyasya vāyustālvasthi nāmayet tasya tṛḍdainyayuktasya sarpirmadhurakaiḥ śṛtam pānābhyañjanayoryojyamudvegaścahimāmbunā" },
      { type: "verse", number: "121", sanskrit: "मलोपलेपात् स्वेदाद्वा गुदे रक्तकफोद्भवः ताम्रो व्रणो ऽन्तः कण्डूमान् जायते भूर्युपद्रवः", text: "malopalepāt svedādvā gude raktakaphodbhavaḥ tāmro vraṇo 'ntaḥ kaṇḍūmān jāyate bhūryupadravaḥ" },
      { type: "verse", number: "122", sanskrit: "केचित्तं मातृकादोषं वदन्त्यन्ये तु पौतनम् पृष्ठारुर्गुदकुट्टं च केचिच्च तमनामकम्", text: "kecittaṃ mātṛkādoṣaṃ vadantyanye tu pautanam pṛṣṭhārurgudakuṭṭaṃ ca kecicca tamanāmakam" },
      { type: "verse", number: "123", sanskrit: "तत्र धात्र्याः पयः शोध्यं पित्तश्लेष्महरौषधैः सितशीतं च शीताम्बुयुक्तमन्तरपानकम्", text: "tatra dhātryāḥ payaḥ śodhyaṃ pittaśleṣmaharauṣadhaiḥ sitaśītaṃ ca śītāmbuyuktamantarapānakam" },
      { type: "verse", number: "124", sanskrit: "सक्षौद्रतार्क्ष्यशैलेन व्रणं तेन च लेपयेत् त्रिफलाबदरीप्लक्षत्वक्वाथपरिषेचितम्", text: "sakṣaudratārkṣyaśailena vraṇaṃ tena ca lepayet triphalābadarīplakṣatvakvāthapariṣecitam" },
      { type: "verse", number: "125", sanskrit: "कासीसरोचनातुत्थमनोह्वालरसाञ्जनैः लेपयेदम्लपिष्टैर्वा चूर्णितैर्वावचूर्णयेत्", text: "kāsīsarocanātutthamanohvālarasāñjanaiḥ lepayedamlapiṣṭairvā cūrṇitairvāvacūrṇayet" },
      { type: "verse", number: "126", sanskrit: "सुश्लक्ष्णैरस्थवा यष्टीशङ्खसौवीरकाञ्जनैः सारिवाशङ्खनाभिभ्यामसनस्य त्वचाथ वा", text: "suślakṣṇairasthavā yaṣṭīśaṅkhasauvīrakāñjanaiḥ sārivāśaṅkhanābhibhyāmasanasya tvacātha vā" },
      { type: "verse", number: "127", sanskrit: "रागकण्डूत्कटे कुर्याद्रक्तस्रावं जलौकसा सर्वं च पित्तव्रणजिच्छस्यते गुदकुट्टके", text: "rāgakaṇḍūtkaṭe kuryādraktasrāvaṃ jalaukasā sarvaṃ ca pittavraṇajicchasyate gudakuṭṭake" },
      { type: "verse", number: "128", sanskrit: "अनामस्थौल्यपित्तास्रकण्डूगण्डगलामये उदरात्युन्नतौ चेष्टं तार्क्ष्यमन्तरपानकम्", text: "anāmasthaulyapittāsrakaṇḍūgaṇḍagalāmaye udarātyunnatau ceṣṭaṃ tārkṣyamantarapānakam" },
      { type: "verse", number: "129", sanskrit: "गृह्णाति सूतिकागारे न स्तनं चेत् स्पृशेत्ततः पथ्याधात्रीफलकणैर्जिह्वां सघृतमाक्षिकैः", text: "gṛhṇāti sūtikāgāre na stanaṃ cet spṛśettataḥ pathyādhātrīphalakaṇairjihvāṃ saghṛtamākṣikaiḥ" },
      { type: "verse", number: "130", sanskrit: "पिप्पलीत्रिफलाचूर्णं घृतक्षौद्रपरिप्लुतम् रुदते त्रस्यते वापि लेहं दद्यात् सुखावहम्", text: "pippalītriphalācūrṇaṃ ghṛtakṣaudrapariplutam rudate trasyate vāpi lehaṃ dadyāt sukhāvaham" },
      { type: "verse", number: "131", sanskrit: "प्रदीप्ताङ्गाररजसा प्रशान्तेनावचूर्णयेत् पञ्चमे ऽह्न्यपातन्नालं लेपयेद्वा गुडाम्भसा", text: "pradīptāṅgārarajasā praśāntenāvacūrṇayet pañcame 'hnyapātannālaṃ lepayedvā guḍāmbhasā" },
      { type: "verse", number: "132", sanskrit: "सान्द्रेण भूमौ घृष्टेन नालपाते ऽपि चोन्नताम् नाभिं छागेन शकृता दग्धेनान्तर्विचूर्णयेत्", text: "sāndreṇa bhūmau ghṛṣṭena nālapāte 'pi connatām nābhiṃ chāgena śakṛtā dagdhenāntarvicūrṇayet" },
      { type: "verse", number: "133", sanskrit: "अश्वगन्धाज्जनाजाविविड्यष्टीमधुकादिभिः रोपयेच्चूर्णितैर्नाभिं स्नेहयुक्तैरनुन्नताम्", text: "aśvagandhājjanājāviviḍyaṣṭīmadhukādibhiḥ ropayeccūrṇitairnābhiṃ snehayuktairanunnatām" },
      { type: "verse", number: "134", sanskrit: "यष्टीलोध्रनिशाश्यामाकल्कपक्वेन सेचयेत् नाभिं पाके तु तैलेन तच्चूर्णेश्चावचूर्णयेत्", text: "yaṣṭīlodhraniśāśyāmākalkapakvena secayet nābhiṃ pāke tu tailena taccūrṇeścāvacūrṇayet" },
      { type: "verse", number: "135", sanskrit: "वातेनाध्मापितां नाभिं सरुजां तुण्डिसंज्ञिताम् मारुतघ्नैः प्रशम्येत् स्नेहस्वेदोपनाहनैः", text: "vātenādhmāpitāṃ nābhiṃ sarujāṃ tuṇḍisaṃjñitām mārutaghnaiḥ praśamyet snehasvedopanāhanaiḥ" },
      { type: "verse", number: "136", sanskrit: "असम्यक्कल्पनान्नाभेः स्याद्विनामो विजृम्भिका वातपित्तहरं कर्म तत्रान्तर्बहिराचरेत्", text: "asamyakkalpanānnābheḥ syādvināmo vijṛmbhikā vātapittaharaṃ karma tatrāntarbahirācaret" },
      { type: "verse", number: "137", sanskrit: "गर्भाम्भसामवमनाच्श्लेष्मणः कण्ठगस्य वा सम्पर्काद्धृदये दुष्टो मार्गानावृणुते रसः", text: "garbhāmbhasāmavamanācśleṣmaṇaḥ kaṇṭhagasya vā samparkāddhṛdaye duṣṭo mārgānāvṛṇute rasaḥ" },
      { type: "verse", number: "138", sanskrit: "बद्धमुष्टिस्ततो मुह्यन्रोगैर्बालो ऽभिभूयते हृद्रोगाक्षेपकश्वासकासच्छर्दिज्वरादिभिः उल्बकं सहजं व्याधिमम्बुपूर्णं च तं वदेत्", text: "baddhamuṣṭistato muhyanrogairbālo 'bhibhūyate hṛdrogākṣepakaśvāsakāsacchardijvarādibhiḥ ulbakaṃ sahajaṃ vyādhimambupūrṇaṃ ca taṃ vadet" },
      { type: "verse", number: "139", sanskrit: "स्रोतोविशोधनं प्रातस्तस्मिन्नन्तरपानकम् विदध्याच्छागलं मूत्रं स्नानाभ्यङ्गौ च वर्जयेत्", text: "srotoviśodhanaṃ prātastasminnantarapānakam vidadhyācchāgalaṃ mūtraṃ snānābhyaṅgau ca varjayet" },
      { type: "verse", number: "140", sanskrit: "बिल्वादिमूलबृहतीपञ्चकोलं पलांशकम् धन्वमांसपलान्यष्टौ शशमूर्ध्नः पलाष्टकम्", text: "bilvādimūlabṛhatīpañcakolaṃ palāṃśakam dhanvamāṃsapalānyaṣṭau śaśamūrdhnaḥ palāṣṭakam" },
      { type: "verse", number: "141", sanskrit: "साधयेत् षोडशगुणे सलिले ऽष्टांशशेषितम् तेन क्वाथेन कर्षांशैर्घृतप्रस्थं विपाचयेत्", text: "sādhayet ṣoḍaśaguṇe salile 'ṣṭāṃśaśeṣitam tena kvāthena karṣāṃśairghṛtaprasthaṃ vipācayet" },
      { type: "verse", number: "142", sanskrit: "छगलीमूत्रमदिरादधिक्षीरसमांशकम् विडङ्गसैन्धवाजाजीचविकादेवदारुभिः", text: "chagalīmūtramadirādadhikṣīrasamāṃśakam viḍaṅgasaindhavājājīcavikādevadārubhiḥ" },
      { type: "verse", number: "143", sanskrit: "सहिंस्राहिङ्गुलशुनैः सव्योषैः श्लक्ष्णकल्कितैः तत् पानाद्धन्ति सहजगुल्महिध्मानिलामयान् पाण्डुरोगं च वातोत्थं स्वस्थवृत्ते च पुष्टिदम्", text: "sahiṃsrāhiṅgulaśunaiḥ savyoṣaiḥ ślakṣṇakalkitaiḥ tat pānāddhanti sahajagulmahidhmānilāmayān pāṇḍurogaṃ ca vātotthaṃ svasthavṛtte ca puṣṭidam" },
      { type: "verse", number: "144", sanskrit: "परिदग्धच्छविं बालं दिह्याद्दूर्वातिलोत्पलैः शमीपत्रशिरीषत्वक्सारिवामधुकाभयैः", text: "paridagdhacchaviṃ bālaṃ dihyāddūrvātilotpalaiḥ śamīpatraśirīṣatvaksārivāmadhukābhayaiḥ" },
      { type: "verse", number: "145", sanskrit: "मूर्वाधात्रीनिशाचूर्णं मूत्रेण मधुमत् पिबेत् पाण्डुरोगी शृतं सर्पिर्वराभृङ्गरसेन वा", text: "mūrvādhātrīniśācūrṇaṃ mūtreṇa madhumat pibet pāṇḍurogī śṛtaṃ sarpirvarābhṛṅgarasena vā" },
      { type: "verse", number: "146", sanskrit: "पाठावेल्लद्विरजनीमुस्ताभार्ङ्गीपुनर्नवैः सबिल्वत्र्यूषणैः सर्पिर्वृश्चिकालीयुतैः शृतम् लिहानो मात्रया रोगैर्मुच्यते मृत्तिकोद्भवैः", text: "pāṭhāvelladvirajanīmustābhārṅgīpunarnavaiḥ sabilvatryūṣaṇaiḥ sarpirvṛścikālīyutaiḥ śṛtam lihāno mātrayā rogairmucyate mṛttikodbhavaiḥ" },
      { type: "verse", number: "147", sanskrit: "व्याधेर्यद्यस्य भैषज्यं स्तस्तेन प्रलेपितः स्थितो मुहूर्तं धौतो ऽनु पीतस्तं तं जयेत् गदम्", text: "vyādheryadyasya bhaiṣajyaṃ stastena pralepitaḥ sthito muhūrtaṃ dhauto 'nu pītastaṃ taṃ jayet gadam" },
      { type: "verse", number: "148", sanskrit: "ग्रहैरपि हि जायन्ते प्रच्छन्नैर्व्याधयः शिशोः कर्म शस्तमतस्तेषु दैवयुक्त्याश्रयं सदा", text: "grahairapi hi jāyante pracchannairvyādhayaḥ śiśoḥ karma śastamatasteṣu daivayuktyāśrayaṃ sadā" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 3,
    lang: "sa",
    content: [
      { type: "heading", heading: "Акши крия — глазные процедуры" },
      { type: "text", text: "Глава 3 Уттара стханы — «Акши крия» — посвящена специализированному разделу: глазные процедуры. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो बालग्रहविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bālagrahavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "पुरा गुहस्य रक्षार्थं निर्मिताः शूलपाणिना मनुष्यविग्रहाः पञ्च सप्त स्त्रीविग्रहा ग्रहाः", text: "purā guhasya rakṣārthaṃ nirmitāḥ śūlapāṇinā manuṣyavigrahāḥ pañca sapta strīvigrahā grahāḥ" },
      { type: "verse", number: "3", sanskrit: "स्कन्दो विशाखो मेषास्यः श्वग्रहः पितृसंज्ञितः शकुनिः पूतना शीतपूतनादृष्टिपूतना मुखमण्डितिका तद्वद्रेवती शुष्करेवती", text: "skando viśākho meṣāsyaḥ śvagrahaḥ pitṛsaṃjñitaḥ śakuniḥ pūtanā śītapūtanādṛṣṭipūtanā mukhamaṇḍitikā tadvadrevatī śuṣkarevatī" },
      { type: "verse", number: "4", sanskrit: "ते कामरूपिणः स्कन्दमुपचेरुः समाहिताः स्कन्दस्य बालधारत्वात्तेषां स्कन्दो ऽग्रणीरभूत्", text: "te kāmarūpiṇaḥ skandamupaceruḥ samāhitāḥ skandasya bāladhāratvātteṣāṃ skando 'graṇīrabhūt" },
      { type: "verse", number: "5", sanskrit: "स्कन्दे ऽथ यौवनं प्राप्ते सेनापत्यं च तान् ग्रहान् रौद्रान् रुद्रो ऽनुजग्राह प्रह्वान् वृत्त्यभिलाषिणः", text: "skande 'tha yauvanaṃ prāpte senāpatyaṃ ca tān grahān raudrān rudro 'nujagrāha prahvān vṛttyabhilāṣiṇaḥ" },
      { type: "verse", number: "6", sanskrit: "न तिथिष्वप्यतिथयो देवताः पितरो ऽपि वा येषु वेश्मसु पूज्यन्ते निवृत्ताचारवर्त्मसु", text: "na tithiṣvapyatithayo devatāḥ pitaro 'pi vā yeṣu veśmasu pūjyante nivṛttācāravartmasu" },
      { type: "verse", number: "7", sanskrit: "उत्सन्नबलिहोमेषु भिन्नकांस्योपभोजिषु हरध्वं तेषु बालानामारोग्यं धारि शर्म च", text: "utsannabalihomeṣu bhinnakāṃsyopabhojiṣu haradhvaṃ teṣu bālānāmārogyaṃ dhāri śarma ca" },
      { type: "verse", number: "8", sanskrit: "शूलिनेति नियुक्तास्ते बलिपूजाभिकाङ्क्षिणः क्रुद्धान् भीतान् विमनसः शून्यस्थानैकचारिणः", text: "śūlineti niyuktāste balipūjābhikāṅkṣiṇaḥ kruddhān bhītān vimanasaḥ śūnyasthānaikacāriṇaḥ" },
      { type: "verse", number: "9", sanskrit: "परोपभुक्तकुसुमवस्त्राभरणधारिणः बालान्कश्मलधात्रीकान्सन्ध्यासु रुदतो ऽशुचीन्", text: "paropabhuktakusumavastrābharaṇadhāriṇaḥ bālānkaśmaladhātrīkānsandhyāsu rudato 'śucīn" },
      { type: "verse", number: "10", sanskrit: "ऋक्षोलूकबिडालादिरूपैरन्यैस्तथाद्भुतैः सन्त्रासयन्तःशयितान्कदाचिज्जाग्रतो ऽपि वा प्रायः पर्वसु गृह्णन्ति ग्रहाश्छिद्रप्रहारिणः", text: "ṛkṣolūkabiḍālādirūpairanyaistathādbhutaiḥ santrāsayantaḥśayitānkadācijjāgrato 'pi vā prāyaḥ parvasu gṛhṇanti grahāśchidraprahāriṇaḥ" },
      { type: "verse", number: "11", sanskrit: "आविशन्तश्च लक्ष्यन्ते केवलं शास्त्रचक्षुषा शुद्धेन देहं बालानां गन्धर्वा इव योषिताम्", text: "āviśantaśca lakṣyante kevalaṃ śāstracakṣuṣā śuddhena dehaṃ bālānāṃ gandharvā iva yoṣitām" },
      { type: "verse", number: "12", sanskrit: "तेषां ग्रहिष्यतां रूपं प्रततं रोदनं ज्वरः", text: "teṣāṃ grahiṣyatāṃ rūpaṃ pratataṃ rodanaṃ jvaraḥ" },
      { type: "verse", number: "13", sanskrit: "सामान्यं रूपमुत्रासजृम्भाभ्रूक्षेपदीनताः फेनस्रावोर्ध्वद्ष्ट्योष्ठदन्तदंशप्रजागराः", text: "sāmānyaṃ rūpamutrāsajṛmbhābhrūkṣepadīnatāḥ phenasrāvordhvadṣṭyoṣṭhadantadaṃśaprajāgarāḥ" },
      { type: "verse", number: "14", sanskrit: "रोदनं कूजनं स्तन्यविद्वेषः स्वरवैकृतम् नखैरकस्मात् परितः स्वधात्र्यङ्गविलेखनम्", text: "rodanaṃ kūjanaṃ stanyavidveṣaḥ svaravaikṛtam nakhairakasmāt paritaḥ svadhātryaṅgavilekhanam" },
      { type: "verse", number: "15", sanskrit: "तत्रैकनयनस्रावी शिरो विक्षिपते मुहुः हतैकपक्षः स्तब्धाङ्गः सस्वेदो नतकन्धरः", text: "tatraikanayanasrāvī śiro vikṣipate muhuḥ hataikapakṣaḥ stabdhāṅgaḥ sasvedo natakandharaḥ" },
      { type: "verse", number: "16", sanskrit: "दन्तखादी स्तनद्वेषी त्रस्यन्रोदिति विस्वरम् वक्रवक्त्रो वमन्लालां भृशमूर्ध्वं निरीक्षते", text: "dantakhādī stanadveṣī trasyanroditi visvaram vakravaktro vamanlālāṃ bhṛśamūrdhvaṃ nirīkṣate" },
      { type: "verse", number: "17", sanskrit: "वसास्रगन्धिरुद्विग्रो बद्धमुष्टिशकृच्छिशुः चलितैकाक्षिगण्डभ्रूः संरक्तोभयलोचनः स्कन्दार्तस्तेन वैकल्यं मरणं वा भवेद्ध्रुवम्", text: "vasāsragandhirudvigro baddhamuṣṭiśakṛcchiśuḥ calitaikākṣigaṇḍabhrūḥ saṃraktobhayalocanaḥ skandārtastena vaikalyaṃ maraṇaṃ vā bhaveddhruvam" },
      { type: "verse", number: "18", sanskrit: "संज्ञानाशो मुहुः केशलुञ्चनं कन्धरानतिः विनम्य जृम्भमाणस्य शकृन्मूत्रप्रवर्तनम्", text: "saṃjñānāśo muhuḥ keśaluñcanaṃ kandharānatiḥ vinamya jṛmbhamāṇasya śakṛnmūtrapravartanam" },
      { type: "verse", number: "19", sanskrit: "फेनोद्वमनमूर्ध्वेक्षा हस्तभ्रूपादनर्तनम् स्तनस्वजिह्वासन्दंशसंरम्भज्वरजागराः पूयशोणितगन्धश्च स्कन्दापस्मारलक्षणम्", text: "phenodvamanamūrdhvekṣā hastabhrūpādanartanam stanasvajihvāsandaṃśasaṃrambhajvarajāgarāḥ pūyaśoṇitagandhaśca skandāpasmāralakṣaṇam" },
      { type: "verse", number: "20", sanskrit: "आध्मानं पाणिपादस्य स्पन्दन फेननिर्वमिः तृण्मुष्टिबन्धातीसारस्वरदैन्यविवर्णताः", text: "ādhmānaṃ pāṇipādasya spandana phenanirvamiḥ tṛṇmuṣṭibandhātīsārasvaradainyavivarṇatāḥ" },
      { type: "verse", number: "21", sanskrit: "कूजनं स्तननं छर्दिः कासहिध्माप्रजागराः औष्ठदंशांससङ्कोचस्तम्भबस्ताभगन्धताः", text: "kūjanaṃ stananaṃ chardiḥ kāsahidhmāprajāgarāḥ auṣṭhadaṃśāṃsasaṅkocastambhabastābhagandhatāḥ" },
      { type: "verse", number: "22", sanskrit: "ऊर्ध्वं निरीक्ष्य हसनं मध्ये विनमनं ज्वरः मूर्छैकनेत्रशोफश्च नैगमेषग्रहाकृतिः", text: "ūrdhvaṃ nirīkṣya hasanaṃ madhye vinamanaṃ jvaraḥ mūrchaikanetraśophaśca naigameṣagrahākṛtiḥ" },
      { type: "verse", number: "23", sanskrit: "कम्पो हृषितरोमत्वं स्वेदश्चक्षुर्निमीलनम् बहिरायामनं जिह्वादंशो ऽन्तःकण्ठकूजनम् धावनं विट्सगन्धत्वं क्रोशनं च श्ववच्छुनि", text: "kampo hṛṣitaromatvaṃ svedaścakṣurnimīlanam bahirāyāmanaṃ jihvādaṃśo 'ntaḥkaṇṭhakūjanam dhāvanaṃ viṭsagandhatvaṃ krośanaṃ ca śvavacchuni" },
      { type: "verse", number: "24", sanskrit: "रोमहर्षो मुहुस्त्रासः सहसा रोदनं ज्वरः कासातिसारवमथुजृम्भातृट्च्छवगन्धिताः", text: "romaharṣo muhustrāsaḥ sahasā rodanaṃ jvaraḥ kāsātisāravamathujṛmbhātṛṭcchavagandhitāḥ" },
      { type: "verse", number: "25", sanskrit: "अङ्गेष्वाक्षेपविक्षेपशोषस्तम्भविवर्णताः मुष्टिबन्धः स्रुतिश्चाक्ष्णोर्बालस्य स्युः पितृग्रहे", text: "aṅgeṣvākṣepavikṣepaśoṣastambhavivarṇatāḥ muṣṭibandhaḥ srutiścākṣṇorbālasya syuḥ pitṛgrahe" },
      { type: "verse", number: "26", sanskrit: "स्रस्ताग्गत्वमतीसारो जिह्वातालुगले व्रणाः स्फोटाःसदाहरुक्पाकाःसन्धिषु स्युः पुनःपुनः", text: "srastāggatvamatīsāro jihvātālugale vraṇāḥ sphoṭāḥsadāharukpākāḥsandhiṣu syuḥ punaḥpunaḥ" },
      { type: "verse", number: "27", sanskrit: "निश्यह्नि प्रविलीयन्ते पाको वक्त्रे गुदे ऽपिवा भयं शकुनिगन्धत्वं ज्वरश्च शकुनिग्रहे", text: "niśyahni pravilīyante pāko vaktre gude 'pivā bhayaṃ śakunigandhatvaṃ jvaraśca śakunigrahe" },
      { type: "verse", number: "28", sanskrit: "पूतनायां वमिः कम्पस्तन्द्रा रात्रौ प्रजागरः हिध्माध्मानं शकृद्भेदः पिपासा मूत्रनिग्रहः स्रस्तहृष्टाङ्गरोमत्वं काकवत् पूतिगन्धिता", text: "pūtanāyāṃ vamiḥ kampastandrā rātrau prajāgaraḥ hidhmādhmānaṃ śakṛdbhedaḥ pipāsā mūtranigrahaḥ srastahṛṣṭāṅgaromatvaṃ kākavat pūtigandhitā" },
      { type: "verse", number: "29", sanskrit: "शीतपूतनया कम्पो रोदनं तिर्यगीक्षणम् तृष्णान्त्रकूजो ऽतीसारो वसावद्विस्रगन्धिता पार्श्वस्यैकस्य शीतत्वमुष्णत्वमपरस्य च", text: "śītapūtanayā kampo rodanaṃ tiryagīkṣaṇam tṛṣṇāntrakūjo 'tīsāro vasāvadvisragandhitā pārśvasyaikasya śītatvamuṣṇatvamaparasya ca" },
      { type: "verse", number: "30", sanskrit: "अन्धपूतनया च्छर्दिर्ज्वरः कासो ऽल्पनिद्रता वर्चसो भेदवैवर्ण्यदौर्गन्ध्यान्यङ्गशोषणम्", text: "andhapūtanayā cchardirjvaraḥ kāso 'lpanidratā varcaso bhedavaivarṇyadaurgandhyānyaṅgaśoṣaṇam" },
      { type: "verse", number: "31", sanskrit: "दृष्टिसादो ऽक्षिरुक्कण्डूः पोथकीजन्म शूनता हिध्मोद्वेगः स्तनद्वेषवैवर्ण्यस्वरतीक्ष्णताः वेपथुर्मत्स्यगन्धित्वमथवा साम्लगन्धिता", text: "dṛṣṭisādo 'kṣirukkaṇḍūḥ pothakījanma śūnatā hidhmodvegaḥ stanadveṣavaivarṇyasvaratīkṣṇatāḥ vepathurmatsyagandhitvamathavā sāmlagandhitā" },
      { type: "verse", number: "32", sanskrit: "मुखमण्डितया पाणिपादास्यरमणीयता सिराभिरसिताभाभिराचितोदरता ज्वरः अरोचको ऽङ्गग्लपनं गोमूत्रसमगन्धिता", text: "mukhamaṇḍitayā pāṇipādāsyaramaṇīyatā sirābhirasitābhābhirācitodaratā jvaraḥ arocako 'ṅgaglapanaṃ gomūtrasamagandhitā" },
      { type: "verse", number: "33", sanskrit: "रेवत्यां श्यावनीलत्वं कर्णनासाक्षिमर्दनम् कासहिध्माक्षिविक्षेपवक्त्रवक्रत्वरक्तताः", text: "revatyāṃ śyāvanīlatvaṃ karṇanāsākṣimardanam kāsahidhmākṣivikṣepavaktravakratvaraktatāḥ" },
      { type: "verse", number: "34", sanskrit: "बस्तगन्धो ज्वरः शोषः पुरीषं हरितं द्रवम् जायते शुष्करेवत्यां क्रमात् सर्वाङ्गसङ्क्षयः", text: "bastagandho jvaraḥ śoṣaḥ purīṣaṃ haritaṃ dravam jāyate śuṣkarevatyāṃ kramāt sarvāṅgasaṅkṣayaḥ" },
      { type: "verse", number: "35", sanskrit: "केशशातो ऽन्नविद्वेषः स्वरदैन्यं विवर्णता नानावर्णपुरीषत्वमुदरे ग्रन्थयः सिराः रोदनं गृद्ध्रगन्धित्वं दीर्घकालानुवर्तनम्", text: "keśaśāto 'nnavidveṣaḥ svaradainyaṃ vivarṇatā nānāvarṇapurīṣatvamudare granthayaḥ sirāḥ rodanaṃ gṛddhragandhitvaṃ dīrghakālānuvartanam" },
      { type: "verse", number: "36", sanskrit: "उदरे ग्रन्थयो वृत्ता यस्य नानाविधं शकृत् जिह्वाया निम्नतामध्ये श्यावं तालु च तं त्यजेत्", text: "udare granthayo vṛttā yasya nānāvidhaṃ śakṛt jihvāyā nimnatāmadhye śyāvaṃ tālu ca taṃ tyajet" },
      { type: "verse", number: "37", sanskrit: "भुञ्जानो ऽन्नं बहुविधं यो बालः परिहीयते तृष्णागृहीतः क्षामाक्षो हन्ति तं शुष्करेवती", text: "bhuñjāno 'nnaṃ bahuvidhaṃ yo bālaḥ parihīyate tṛṣṇāgṛhītaḥ kṣāmākṣo hanti taṃ śuṣkarevatī" },
      { type: "verse", number: "38", sanskrit: "हिंसारत्यर्चनाकाङ्क्षा ग्रहग्रहणकारणम्", text: "hiṃsāratyarcanākāṅkṣā grahagrahaṇakāraṇam" },
      { type: "verse", number: "39", sanskrit: "तत्र हिंसात्मके बालो महान् वा स्रुतनासिकः क्षतजिह्वः क्वणन् बाढमसुखी सास्रलोचनः", text: "tatra hiṃsātmake bālo mahān vā srutanāsikaḥ kṣatajihvaḥ kvaṇan bāḍhamasukhī sāsralocanaḥ" },
      { type: "verse", number: "40", sanskrit: "दुर्वर्णो हीनवचनः पूतिगन्धिश्च जायते क्षामो मूत्रपुरीषं स्वं मृद्नाति न जुगुप्सते", text: "durvarṇo hīnavacanaḥ pūtigandhiśca jāyate kṣāmo mūtrapurīṣaṃ svaṃ mṛdnāti na jugupsate" },
      { type: "verse", number: "41", sanskrit: "हस्तौ चोद्यम्य संरब्धो हन्त्यात्मानं तथापरम् तद्वच्च शस्त्रकाष्ठाद्यैरग्निं वा दीप्तमाविशेत्", text: "hastau codyamya saṃrabdho hantyātmānaṃ tathāparam tadvacca śastrakāṣṭhādyairagniṃ vā dīptamāviśet" },
      { type: "verse", number: "42", sanskrit: "अप्सु मज्जेत् पतेत् कूपे कुर्यादन्यच्च तद्विधम् तृट्दाहमोहान् पूयस्य छर्दनं च प्रवर्तयेत् रकं च सर्वमार्गेभ्यो ऽरिष्टोत्पत्तिं च तं त्यजेत्", text: "apsu majjet patet kūpe kuryādanyacca tadvidham tṛṭdāhamohān pūyasya chardanaṃ ca pravartayet rakaṃ ca sarvamārgebhyo 'riṣṭotpattiṃ ca taṃ tyajet" },
      { type: "verse", number: "43", sanskrit: "रहःस्त्रीरतिसंल्लापगन्धस्रग्भूषणप्रियः हृष्टः शान्तश्च दुःसाधो रतिकामेन पीडितः", text: "rahaḥstrīratisaṃllāpagandhasragbhūṣaṇapriyaḥ hṛṣṭaḥ śāntaśca duḥsādho ratikāmena pīḍitaḥ" },
      { type: "verse", number: "44", sanskrit: "दीनः परिमृशन् वक्त्रं शुष्कौष्ठगलतालुकः शङ्कितं वीक्षते रौति ध्यायत्यायाति भीतताम्", text: "dīnaḥ parimṛśan vaktraṃ śuṣkauṣṭhagalatālukaḥ śaṅkitaṃ vīkṣate rauti dhyāyatyāyāti bhītatām" },
      { type: "verse", number: "45", sanskrit: "अन्नमन्नाभिलाषे ऽपि दत्तं नाति बुभुक्षते गृहीतं बलिकामेन तं विद्यात् सुखसाधनम्", text: "annamannābhilāṣe 'pi dattaṃ nāti bubhukṣate gṛhītaṃ balikāmena taṃ vidyāt sukhasādhanam" },
      { type: "verse", number: "46", sanskrit: "हन्तुकामं जयेद्धोमैः सिद्धमन्त्रप्रवर्तितैः इतरौ तु यथाकामं रतिबल्यादिदानतः", text: "hantukāmaṃ jayeddhomaiḥ siddhamantrapravartitaiḥ itarau tu yathākāmaṃ ratibalyādidānataḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 4,
    lang: "sa",
    content: [
      { type: "heading", heading: "Карна рога — болезни ушей — обзор" },
      { type: "text", text: "Глава 4 Уттара стханы — «Карна рога» — посвящена специализированному разделу: болезни ушей — обзор. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो बालग्रहप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bālagrahapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "ग्रहेषु साध्येषु शिशुं विविक्ते शरणे स्थितम् त्रिरह्ना मृष्टसंसिक्ते सदा सन्निहितानले", text: "graheṣu sādhyeṣu śiśuṃ vivikte śaraṇe sthitam trirahnā mṛṣṭasaṃsikte sadā sannihitānale" },
      { type: "verse", number: "3", sanskrit: "विकीर्णभूतिकुसुमबीजपत्रान्नसर्षपे रक्षोघ्नतैलज्वलितप्रदीपहतपाप्मनि", text: "vikīrṇabhūtikusumabījapatrānnasarṣape rakṣoghnatailajvalitapradīpahatapāpmani" },
      { type: "verse", number: "4", sanskrit: "व्यवायमद्यपिशितनिवृत्तपरिचारके पुराणसर्पिषाभ्यक्तं परिषिक्तं सुखाम्बुना", text: "vyavāyamadyapiśitanivṛttaparicārake purāṇasarpiṣābhyaktaṃ pariṣiktaṃ sukhāmbunā" },
      { type: "verse", number: "5", sanskrit: "साधितेन बलानिम्बवैजयन्तीनृपद्रुमैः पारिभद्रककट्वङ्गजम्बूवरणकत्तृणैः", text: "sādhitena balānimbavaijayantīnṛpadrumaiḥ pāribhadrakakaṭvaṅgajambūvaraṇakattṛṇaiḥ" },
      { type: "verse", number: "6", sanskrit: "कपोतवङ्कापामार्गपाटलीमधुशिग्रुभिः काकजङ्घामहाश्वेताकपित्थक्षीरिपादपैः", text: "kapotavaṅkāpāmārgapāṭalīmadhuśigrubhiḥ kākajaṅghāmahāśvetākapitthakṣīripādapaiḥ" },
      { type: "verse", number: "7", sanskrit: "सकदम्बकरञ्जैश्च धूपं स्नातस्य चाचरेत् द्वीपिव्याघ्राहिसिंहर्क्षचर्मभिर्घृतमिश्रितैः", text: "sakadambakarañjaiśca dhūpaṃ snātasya cācaret dvīpivyāghrāhisiṃharkṣacarmabhirghṛtamiśritaiḥ" },
      { type: "verse", number: "8", sanskrit: "पूतीदशाङ्गसिद्धार्थवचाभल्लातदीप्यकैः सकुष्ठैः सघृतैर्धूपः सर्वग्रहविमोक्षणः", text: "pūtīdaśāṅgasiddhārthavacābhallātadīpyakaiḥ sakuṣṭhaiḥ saghṛtairdhūpaḥ sarvagrahavimokṣaṇaḥ" },
      { type: "verse", number: "9", sanskrit: "सर्षपा निम्बपत्राणि मूलमश्वखुराद्वचा भूर्जपत्रं घृतं धूपः सर्वग्रहनिबर्हणः", text: "sarṣapā nimbapatrāṇi mūlamaśvakhurādvacā bhūrjapatraṃ ghṛtaṃ dhūpaḥ sarvagrahanibarhaṇaḥ" },
      { type: "verse", number: "10", sanskrit: "अनन्ताम्रास्थितगरं मरिचं मधुरो गणः शृगालविन्ना मुस्ता च कल्कितैस्तैर्घृतं पचेत् दशमूलरसक्षीरयुक्तं तद् ग्रहजित् परम्", text: "anantāmrāsthitagaraṃ maricaṃ madhuro gaṇaḥ śṛgālavinnā mustā ca kalkitaistairghṛtaṃ pacet daśamūlarasakṣīrayuktaṃ tad grahajit param" },
      { type: "verse", number: "11", sanskrit: "रास्नाद्व्यंशुमतीवढ्रपञ्चमूलबलाघनात् क्वाथे सर्पिः पचेत् पिष्टैः सारिवाव्योषचित्रकैः", text: "rāsnādvyaṃśumatīvaḍhrapañcamūlabalāghanāt kvāthe sarpiḥ pacet piṣṭaiḥ sārivāvyoṣacitrakaiḥ" },
      { type: "verse", number: "12", sanskrit: "पाठाविडङ्गमधुकपयस्याहिङ्गुदारुभिः सग्रन्थिकैः सेन्द्रयवैः शिशोस्तत् सततं हितम् सर्वरोगग्रहहरं दीपनं बलवर्णदम्", text: "pāṭhāviḍaṅgamadhukapayasyāhiṅgudārubhiḥ sagranthikaiḥ sendrayavaiḥ śiśostat satataṃ hitam sarvarogagrahaharaṃ dīpanaṃ balavarṇadam" },
      { type: "verse", number: "13", sanskrit: "सारिवासुरभिब्राह्मशिङ्खिनीकुष्ठसर्षपैः वचाश्वगन्धासुरसायुक्तैः सर्पिर्विपाचयेत्", text: "sārivāsurabhibrāhmaśiṅkhinīkuṣṭhasarṣapaiḥ vacāśvagandhāsurasāyuktaiḥ sarpirvipācayet" },
      { type: "verse", number: "14", sanskrit: "तन्नाशयेद् ग्रहान् सर्वान् पानेनाभ्यञ्जनेन च योजयेद् भूतविद्यायां यान्युक्तानि घृतानि च", text: "tannāśayed grahān sarvān pānenābhyañjanena ca yojayed bhūtavidyāyāṃ yānyuktāni ghṛtāni ca" },
      { type: "verse", number: "15", sanskrit: "हस्तमात्रं शुचौ देशे गोमयेनोपलेपयेत् तत्राक्षतानां चोक्षाणां स्थाप्यं पात्रं सदक्षिणम्", text: "hastamātraṃ śucau deśe gomayenopalepayet tatrākṣatānāṃ cokṣāṇāṃ sthāpyaṃ pātraṃ sadakṣiṇam" },
      { type: "verse", number: "16", sanskrit: "निर्धूमश्चानलस्तोयं गुग्गुलुः सर्पिराहुतिः शुक्लं पुष्पं बलिर्धूपो दूर्वा श्वेताश्च सर्षपाः", text: "nirdhūmaścānalastoyaṃ gugguluḥ sarpirāhutiḥ śuklaṃ puṣpaṃ balirdhūpo dūrvā śvetāśca sarṣapāḥ" },
      { type: "verse", number: "17", sanskrit: "प्राङ्मुखो ऽथ शुचिर्वैद्यस्त्रिवर्णामथवा सिताम् उपविष्टः प्रतिसरां गृहीत्वा वेष्टयेत्तया", text: "prāṅmukho 'tha śucirvaidyastrivarṇāmathavā sitām upaviṣṭaḥ pratisarāṃ gṛhītvā veṣṭayettayā" },
      { type: "verse", number: "18", sanskrit: "भूर्जे रोचनया विद्यां लिखितामपराजिताम् विधिना साधितां भूतैः सर्वैरप्यपराजिताम्", text: "bhūrje rocanayā vidyāṃ likhitāmaparājitām vidhinā sādhitāṃ bhūtaiḥ sarvairapyaparājitām" },
      { type: "verse", number: "19", sanskrit: "लक्ष्मणादिपरीवारां नित्यानुस्मृतिसेविताम् लक्ष्मणा सहदेवाख्या नागदन्ती कटम्भरा", text: "lakṣmaṇādiparīvārāṃ nityānusmṛtisevitām lakṣmaṇā sahadevākhyā nāgadantī kaṭambharā" },
      { type: "verse", number: "20", sanskrit: "मर्कटी कर्कटी लम्बा बृहती कण्टकारिका खरनासा मृगोर्वारुर्महाश्वेता शतावरी", text: "markaṭī karkaṭī lambā bṛhatī kaṇṭakārikā kharanāsā mṛgorvārurmahāśvetā śatāvarī" },
      { type: "verse", number: "21", sanskrit: "उदङ्मुखस्य बालस्य बध्नीयात्तां ततो गले तदभावे दृढं क्षौमसूत्रं मन्त्रमिदं जपन्", text: "udaṅmukhasya bālasya badhnīyāttāṃ tato gale tadabhāve dṛḍhaṃ kṣaumasūtraṃ mantramidaṃ japan" },
      { type: "verse", number: "22", sanskrit: "बध्नाम्यहं प्रतिसरां नमस्कृत्वा स्वयम्भुवे बालानां रक्षणार्थाय शिवां पूर्वर्षिनिर्मिताम्", text: "badhnāmyahaṃ pratisarāṃ namaskṛtvā svayambhuve bālānāṃ rakṣaṇārthāya śivāṃ pūrvarṣinirmitām" },
      { type: "verse", number: "23", sanskrit: "इन्द्रो ऽनुमन्यतां तुभ्यं ये च तस्यानुचारिणः वज्राशनिधरा भूता मेघवृन्दानुसारिणः", text: "indro 'numanyatāṃ tubhyaṃ ye ca tasyānucāriṇaḥ vajrāśanidharā bhūtā meghavṛndānusāriṇaḥ" },
      { type: "verse", number: "24", sanskrit: "ऐरावतस्कन्धगतं ये ऽनुयान्ति पुरन्दरम् यमो वैवस्वतो राजा ये च तस्यानुचारिणः", text: "airāvataskandhagataṃ ye 'nuyānti purandaram yamo vaivasvato rājā ye ca tasyānucāriṇaḥ" },
      { type: "verse", number: "25", sanskrit: "मेषसूकरसिंहोष्ट्रखरवाजिसमाननाः काला कालायसैःपाशैःस्तब्धाक्षा भ्रुकुटीमुखाः", text: "meṣasūkarasiṃhoṣṭrakharavājisamānanāḥ kālā kālāyasaiḥpāśaiḥstabdhākṣā bhrukuṭīmukhāḥ" },
      { type: "verse", number: "26", sanskrit: "शक्तिमुद्गरहस्ताश्च खड्गपाशधराश्च ये पाशभृद्वरुणो राजा तोयभूः सागरालयः", text: "śaktimudgarahastāśca khaḍgapāśadharāśca ye pāśabhṛdvaruṇo rājā toyabhūḥ sāgarālayaḥ" },
      { type: "verse", number: "27", sanskrit: "शारदाभ्रघनाकारा ये च तस्यानुचारिणः महोर्मिमन्तं वेगेन क्षोभयन्ति सरित्पतिम्", text: "śāradābhraghanākārā ye ca tasyānucāriṇaḥ mahormimantaṃ vegena kṣobhayanti saritpatim" },
      { type: "verse", number: "28", sanskrit: "धनाधिपो वैश्रवणः सर्वयक्षाधिपो विभुः नानाकाराश्च ये भूतास्तस्यैवानुचराः सदा", text: "dhanādhipo vaiśravaṇaḥ sarvayakṣādhipo vibhuḥ nānākārāśca ye bhūtāstasyaivānucarāḥ sadā" },
      { type: "verse", number: "29", sanskrit: "आदित्या वसवो रुद्रा मरुतश्चाश्विनावपि एते सर्वे ऽनुमन्यन्तामिमां प्रतिसरक्रियाम्", text: "ādityā vasavo rudrā marutaścāśvināvapi ete sarve 'numanyantāmimāṃ pratisarakriyām" },
      { type: "verse", number: "30", sanskrit: "दीर्घमायुररोगं च तव दास्यन्ति स्वस्ति ते स्वस्ति ते भगवान् ब्राह्मा स्वस्ति नारदपर्वतौ", text: "dīrghamāyurarogaṃ ca tava dāsyanti svasti te svasti te bhagavān brāhmā svasti nāradaparvatau" },
      { type: "verse", number: "31", sanskrit: "स्वस्ति वेदाश्च यज्ञाश्च अग्नीषोमौ च स्वस्ति ते स्वस्ति ते श्रीर्धृतिःकीर्तिर्लक्ष्मीर्मेधा क्षमा द्युतिः", text: "svasti vedāśca yajñāśca agnīṣomau ca svasti te svasti te śrīrdhṛtiḥkīrtirlakṣmīrmedhā kṣamā dyutiḥ" },
      { type: "verse", number: "32", sanskrit: "स्वस्ति तुष्टिश्च पुष्टिश्च वपुर्द्रीर्बुद्धिरेव च स्वस्ति रुद्रो विशाखश्च स्कन्दः शक्तिधरश्च ते", text: "svasti tuṣṭiśca puṣṭiśca vapurdrīrbuddhireva ca svasti rudro viśākhaśca skandaḥ śaktidharaśca te" },
      { type: "verse", number: "33", sanskrit: "स्वस्ति धाता विधाता च सुपर्णश्च महाबलः स्वस्ति देवाश्च यक्षाश्च मा च ते पापमागमत्", text: "svasti dhātā vidhātā ca suparṇaśca mahābalaḥ svasti devāśca yakṣāśca mā ca te pāpamāgamat" },
      { type: "verse", number: "34", sanskrit: "दुर्व्यादृतानि दुस्वप्नं मनसा चिन्तितानि च दुष्टादीनां भयकृतो वाचः प्रतिहता मया", text: "durvyādṛtāni dusvapnaṃ manasā cintitāni ca duṣṭādīnāṃ bhayakṛto vācaḥ pratihatā mayā" },
      { type: "verse", number: "35", sanskrit: "रक्षा प्रतिसरा तुभ्यं बद्धेयं पापघातिनी निर्वृतस्त्वं निरुद्वेगो जीव वर्षशतं सुखी", text: "rakṣā pratisarā tubhyaṃ baddheyaṃ pāpaghātinī nirvṛtastvaṃ nirudvego jīva varṣaśataṃ sukhī" },
      { type: "verse", number: "36", sanskrit: "अपूपपूपसंयावस्वस्तिकालोपिकादयः पायसो मिश्रकः सिद्धो गुडपूरो हरिद्रकः", text: "apūpapūpasaṃyāvasvastikālopikādayaḥ pāyaso miśrakaḥ siddho guḍapūro haridrakaḥ" },
      { type: "verse", number: "37", sanskrit: "कृसरो यावकः क्षौद्रं पललं लवणं हविः दधिकुल्माषनिष्पावो रक्तो भूतौदनः पयः", text: "kṛsaro yāvakaḥ kṣaudraṃ palalaṃ lavaṇaṃ haviḥ dadhikulmāṣaniṣpāvo rakto bhūtaudanaḥ payaḥ" },
      { type: "verse", number: "38", sanskrit: "पक्वाममांसरुधिरमत्स्यसक्तु सुरासवाः गन्धं माल्यं फलं हेम धूपः सपुरकुन्दुरुः", text: "pakvāmamāṃsarudhiramatsyasaktu surāsavāḥ gandhaṃ mālyaṃ phalaṃ hema dhūpaḥ sapurakunduruḥ" },
      { type: "verse", number: "39", sanskrit: "सुरसार्जकनिर्गुण्डीकुसुमं च सपल्लवम् बलिः सुशस्तैर्देयः स्याद् भवनस्य चतुर्दिशम्", text: "surasārjakanirguṇḍīkusumaṃ ca sapallavam baliḥ suśastairdeyaḥ syād bhavanasya caturdiśam" },
      { type: "verse", number: "40", sanskrit: "चतुष्कचैत्यत्रिपथदेवायतनगोपुरे रेखावृक्षोदपाने च सन्ध्ययोर्दीपवान् निशि", text: "catuṣkacaityatripathadevāyatanagopure rekhāvṛkṣodapāne ca sandhyayordīpavān niśi" },
      { type: "verse", number: "41", sanskrit: "अथापतितगोवर्चः प्रलिप्ते दर्भसंस्तृते वृत्ते वा चतुरस्रे वा मण्डले कुसुमोज्वले", text: "athāpatitagovarcaḥ pralipte darbhasaṃstṛte vṛtte vā caturasre vā maṇḍale kusumojvale" },
      { type: "verse", number: "42", sanskrit: "नानाग्रहपरीवारं भिषग्भूतपतिं लिखेत् तं प्रति प्राङ्मुखो विद्यां पठन्नुपहरेत् बलिम्", text: "nānāgrahaparīvāraṃ bhiṣagbhūtapatiṃ likhet taṃ prati prāṅmukho vidyāṃ paṭhannupaharet balim" },
      { type: "verse", number: "43", sanskrit: "नमोविमारकस्य नमः कुमारङ्गाय नमः सप्तानां मातृऋणाम् नमः स्कन्दाय एष परिग्रहमन्त्रः मातृऋणामावाहनं च हिलिहिलिनिमापटलिनि स्वाहा अनेन सप्तकृत्वः परिजपितेन पानीयचलुकेनात्माभ्युक्षयितव्यः एवमात्मरक्षा कृता भवति", text: "namovimārakasya namaḥ kumāraṅgāya namaḥ saptānāṃ mātṛṛṇām namaḥ skandāya eṣa parigrahamantraḥ mātṛṛṇāmāvāhanaṃ ca hilihilinimāpaṭalini svāhā anena saptakṛtvaḥ parijapitena pānīyacalukenātmābhyukṣayitavyaḥ evamātmarakṣā kṛtā bhavati" },
      { type: "verse", number: "44", sanskrit: "ग्रहाणां सन्निधानाय बलेश्च प्रतिपत्तये सत्यसाधनसंयुक्तमिमं मन्त्रं पठेदनु", text: "grahāṇāṃ sannidhānāya baleśca pratipattaye satyasādhanasaṃyuktamimaṃ mantraṃ paṭhedanu" },
      { type: "verse", number: "45", sanskrit: "प्रजापतौ च यत् सत्यं यत् सत्यममरेश्वरे धर्मराजे च यत् सत्यं यच्च सत्यं तपस्विषु", text: "prajāpatau ca yat satyaṃ yat satyamamareśvare dharmarāje ca yat satyaṃ yacca satyaṃ tapasviṣu" },
      { type: "verse", number: "46", sanskrit: "धनाधिते च यत् सत्यं यच्च सत्यं जलाधिते यत् सत्यमग्निहोत्रेषु सत्यं यच्छ्रोत्रियेषु च", text: "dhanādhite ca yat satyaṃ yacca satyaṃ jalādhite yat satyamagnihotreṣu satyaṃ yacchrotriyeṣu ca" },
      { type: "verse", number: "47", sanskrit: "पतिव्रतासु यत्सत्यमीश्वरे च महात्मनि एतैस्तु सत्यसमयैर्गुह्यकाः सत्यवादिनः", text: "pativratāsu yatsatyamīśvare ca mahātmani etaistu satyasamayairguhyakāḥ satyavādinaḥ" },
      { type: "verse", number: "48", sanskrit: "दर्शयध्वं स्वरूपाणि सत्यं रक्षत सर्वतः आमन्त्रिता मया सौम्याः सौम्यरूपाः प्रतीच्छता", text: "darśayadhvaṃ svarūpāṇi satyaṃ rakṣata sarvataḥ āmantritā mayā saumyāḥ saumyarūpāḥ pratīcchatā" },
      { type: "verse", number: "49", sanskrit: "बलिं चोपहृतं सर्वं सर्वे कौमारका ग्रहाः दर्शयध्वं स्वरूपाणि बलिश्च प्रतिगृह्यताम्", text: "baliṃ copahṛtaṃ sarvaṃ sarve kaumārakā grahāḥ darśayadhvaṃ svarūpāṇi baliśca pratigṛhyatām" },
      { type: "verse", number: "50", sanskrit: "ततश्चानु पठेदेनां कुलविद्यां समाहितः औला नीला खला काला नकुला ग्रहकारिका", text: "tataścānu paṭhedenāṃ kulavidyāṃ samāhitaḥ aulā nīlā khalā kālā nakulā grahakārikā" },
      { type: "verse", number: "51", sanskrit: "सेना सुसेना माता च महासेना यशस्विनी कृतमालाक्षतशिरा एतास्तु ग्रहमातरः", text: "senā susenā mātā ca mahāsenā yaśasvinī kṛtamālākṣataśirā etāstu grahamātaraḥ" },
      { type: "verse", number: "52", sanskrit: "कुमारवचनाच्छीघ्रं प्रमुञ्चन्तु शिशुन्त्विमम् कालकल्पा ज्वलच्छक्तिः किङ्किणीजालभूषिता", text: "kumāravacanācchīghraṃ pramuñcantu śiśuntvimam kālakalpā jvalacchaktiḥ kiṅkiṇījālabhūṣitā" },
      { type: "verse", number: "53", sanskrit: "कुमारवचनाद्दूती सम्प्राप्ता मुच्यतां शिशुः पताका कुक्कुटः छत्रं घण्टाबर्हधरः शिखी", text: "kumāravacanāddūtī samprāptā mucyatāṃ śiśuḥ patākā kukkuṭaḥ chatraṃ ghaṇṭābarhadharaḥ śikhī" },
      { type: "verse", number: "54", sanskrit: "शरस्तम्भश्च ते मुद्रा मुच्यतां मातरः शिशुः गन्धं धूपं च माल्यं च कुमारस्ते प्रयच्छति", text: "śarastambhaśca te mudrā mucyatāṃ mātaraḥ śiśuḥ gandhaṃ dhūpaṃ ca mālyaṃ ca kumāraste prayacchati" },
      { type: "verse", number: "55", sanskrit: "न स्थातव्यं तदाघ्राय स्वां गतिं गच्छ मा चिरम् धात्र्यः सर्वाः कुमारस्य सङ्गता गन्धमादने", text: "na sthātavyaṃ tadāghrāya svāṃ gatiṃ gaccha mā ciram dhātryaḥ sarvāḥ kumārasya saṅgatā gandhamādane" },
      { type: "verse", number: "56", sanskrit: "रक्तध्वजपताकस्य रक्तांशुकनिवासिनः कुमारस्यालयं तत्र यात बालं विमुञ्चत", text: "raktadhvajapatākasya raktāṃśukanivāsinaḥ kumārasyālayaṃ tatra yāta bālaṃ vimuñcata" },
      { type: "verse", number: "57", sanskrit: "षम्मुखो द्वादशाक्षो वै तस्मिन् काले वृतो वरम् वीरः कुमाराधिपतिस्तव पुत्रो ऽभिषिच्यताम्", text: "ṣammukho dvādaśākṣo vai tasmin kāle vṛto varam vīraḥ kumārādhipatistava putro 'bhiṣicyatām" },
      { type: "verse", number: "58", sanskrit: "ब्राह्मणो ब्राह्मणानान्तु सर्ववेदविदां वरः यक्षराक्षसनागानां गन्धर्वासुरयोरपि", text: "brāhmaṇo brāhmaṇānāntu sarvavedavidāṃ varaḥ yakṣarākṣasanāgānāṃ gandharvāsurayorapi" },
      { type: "verse", number: "59", sanskrit: "पिशाचभूतसङ्घानां व्याधीनां च स ईश्वरः आज्ञापयति वः स्कन्दो गम्यतां गन्धमादनम्", text: "piśācabhūtasaṅghānāṃ vyādhīnāṃ ca sa īśvaraḥ ājñāpayati vaḥ skando gamyatāṃ gandhamādanam" },
      { type: "verse", number: "60", sanskrit: "ग्रहो यः कोपयेदाज्ञां कुमारस्य यशस्विनः स्थानात् च्युतः स वै क्षिप्रं बाह्यः परिषदो भवेत्", text: "graho yaḥ kopayedājñāṃ kumārasya yaśasvinaḥ sthānāt cyutaḥ sa vai kṣipraṃ bāhyaḥ pariṣado bhavet" },
      { type: "verse", number: "61", sanskrit: "बलेरनन्तरं कुर्याद्धोममभ्यर्च्य पावकम् पुष्पैर्भक्ष्यैश्च विविधैश्चरुणा लोहितैस्तथा", text: "baleranantaraṃ kuryāddhomamabhyarcya pāvakam puṣpairbhakṣyaiśca vividhaiścaruṇā lohitaistathā" },
      { type: "verse", number: "62", sanskrit: "गन्धैर्गुग्गुलुधूपैश्च समिधः खदिरादथ शतमष्टोत्तरं हव्यमथवा चन्दनद्रुमात्", text: "gandhairgugguludhūpaiśca samidhaḥ khadirādatha śatamaṣṭottaraṃ havyamathavā candanadrumāt" },
      { type: "verse", number: "63", sanskrit: "अग्निदण्डं प्रवक्ष्यामि सर्वग्रहविमोक्षणम् ब्रह्मण्यन्त्वनलं देवं हव्यकव्यप्रतीच्छकम्", text: "agnidaṇḍaṃ pravakṣyāmi sarvagrahavimokṣaṇam brahmaṇyantvanalaṃ devaṃ havyakavyapratīcchakam" },
      { type: "verse", number: "64", sanskrit: "देवानां प्राङ्मुखं स्वस्तिस्वाहापहरतिद्रुतम् सहस्रविद्यो दहनः पावकः सर्वभक्षणः", text: "devānāṃ prāṅmukhaṃ svastisvāhāpaharatidrutam sahasravidyo dahanaḥ pāvakaḥ sarvabhakṣaṇaḥ" },
      { type: "verse", number: "65", sanskrit: "त्वं हि यज्ञश्च यूपश्च त्वं हि धर्मवतां गतिः हिरण्यरेता देवस्त्वं त्वं हि वेदविदां गतिः", text: "tvaṃ hi yajñaśca yūpaśca tvaṃ hi dharmavatāṃ gatiḥ hiraṇyaretā devastvaṃ tvaṃ hi vedavidāṃ gatiḥ" },
      { type: "verse", number: "66", sanskrit: "दुर्वृत्तानां विनाशाय त्वं समुत्पादितः सुरैः दहसङ्ग्रहदेवत्वमिदं दुष्टस्य निग्रहम्", text: "durvṛttānāṃ vināśāya tvaṃ samutpāditaḥ suraiḥ dahasaṅgrahadevatvamidaṃ duṣṭasya nigraham" },
      { type: "verse", number: "67", sanskrit: "अग्नये स्वाहा महाग्नये स्वाहा त्वं हि शान्तिकरो वह्निस्त्वं मारुतहरोदनः हरिप्रधानगतिरासीदिमं निगृह्य गुह्यकमुत्सादय तेजसा त्वं मम वश्यं च तं कुरु दुष्टग्रहनिवारणं सर्वोपद्रवेषु च", text: "agnaye svāhā mahāgnaye svāhā tvaṃ hi śāntikaro vahnistvaṃ mārutaharodanaḥ haripradhānagatirāsīdimaṃ nigṛhya guhyakamutsādaya tejasā tvaṃ mama vaśyaṃ ca taṃ kuru duṣṭagrahanivāraṇaṃ sarvopadraveṣu ca" },
      { type: "verse", number: "68", sanskrit: "त्वया कृतेन होमेन शीघ्रं शान्तिः प्रजायते आयाहि वह्ने देवानां त्वं हि वक्त्रं पुरातनम् तेन सत्येन देवेश इमं साधय मे ग्रहम्", text: "tvayā kṛtena homena śīghraṃ śāntiḥ prajāyate āyāhi vahne devānāṃ tvaṃ hi vaktraṃ purātanam tena satyena deveśa imaṃ sādhaya me graham" },
      { type: "verse", number: "69", sanskrit: "नमो ऽस्तुते हव्यवाहन दण्डं प्रदर्शय दह दह दर्श दर्श तेज तेज मोटय मोटय अपस्मारमुद्घाटय कुमार पिशाचरेवतीरोदनत्रासन वित्रासन कम्पन उत्कम्पन विजृम्भण देवयक्षगन्धर्वभूतनागराक्षससन्तजन दण्डनाविधूसारयभगवन्नग्निदण्ड अग्निवीर्य नमस्तेजसास्वेनत्यक्तमुत्सादय स्वाहा भूर्भुवस्स्वः स्वाहा दीप्ततेजसे स्वाहा हव्यवाहनाय स्वाहा यमाय स्वाहा नश्यन्त्यनेन होमेन समस्ता बालकग्रहाः", text: "namo 'stute havyavāhana daṇḍaṃ pradarśaya daha daha darśa darśa teja teja moṭaya moṭaya apasmāramudghāṭaya kumāra piśācarevatīrodanatrāsana vitrāsana kampana utkampana vijṛmbhaṇa devayakṣagandharvabhūtanāgarākṣasasantajana daṇḍanāvidhūsārayabhagavannagnidaṇḍa agnivīrya namastejasāsvenatyaktamutsādaya svāhā bhūrbhuvassvaḥ svāhā dīptatejase svāhā havyavāhanāya svāhā yamāya svāhā naśyantyanena homena samastā bālakagrahāḥ" },
      { type: "verse", number: "70", sanskrit: "तत्राग्नावरुणे ताम्रे तप्तहेमसमार्चिषि तारावैदूर्यसदृशे शशिविद्युत्समप्रभे", text: "tatrāgnāvaruṇe tāmre taptahemasamārciṣi tārāvaidūryasadṛśe śaśividyutsamaprabhe" },
      { type: "verse", number: "71", sanskrit: "घृतमण्डाभवर्णे वा गन्धेन च घृतोपमे केतकोत्पलदध्याभे द्रुवमारोग्यमादिशेत् अनारोग्यं तु नीले ऽग्नौ कपिले भस्मनिष्प्रभे", text: "ghṛtamaṇḍābhavarṇe vā gandhena ca ghṛtopame ketakotpaladadhyābhe druvamārogyamādiśet anārogyaṃ tu nīle 'gnau kapile bhasmaniṣprabhe" },
      { type: "verse", number: "72", sanskrit: "कृष्णे कपोते दुर्गन्धे मत्स्यपूयास्रगन्धिके वचालशुनगन्धाभे विस्रे कर्दमगन्धिके", text: "kṛṣṇe kapote durgandhe matsyapūyāsragandhike vacālaśunagandhābhe visre kardamagandhike" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 5,
    lang: "sa",
    content: [
      { type: "heading", heading: "Карна крия — процедуры для ушей" },
      { type: "text", text: "Глава 5 Уттара стханы — «Карна крия» — посвящена специализированному разделу: процедуры для ушей. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः स्नपनाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ snapanādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सरित्सङ्गमगोतीर्थगजेन्द्रस्कन्धगोकुले चतुष्पथे च स्नपयेद् बालं सस्तन्यमातरम् श्मशाने दीर्घरोगार्तं मृतापत्यां च योषितम्", text: "saritsaṅgamagotīrthagajendraskandhagokule catuṣpathe ca snapayed bālaṃ sastanyamātaram śmaśāne dīrgharogārtaṃ mṛtāpatyāṃ ca yoṣitam" },
      { type: "verse", number: "3", sanskrit: "दूर्वाक्षीरिद्रुमवती प्रागुदक्प्रवणा मही स्निग्धनीरुजपुष्पाढ्यपादपा स्नपने शुभा", text: "dūrvākṣīridrumavatī prāgudakpravaṇā mahī snigdhanīrujapuṣpāḍhyapādapā snapane śubhā" },
      { type: "verse", number: "4", sanskrit: "रेवतीश्रवणस्वातीप्राजापत्योत्तरैन्दवे पुष्ये मूले च बालस्य स्नानं पर्वदिनेषु च", text: "revatīśravaṇasvātīprājāpatyottaraindave puṣye mūle ca bālasya snānaṃ parvadineṣu ca" },
      { type: "verse", number: "5", sanskrit: "चतुर्हस्ताष्टहस्तं वा द्वात्रिंशद्धस्तमेव वा नल्वमात्रप्रमाणं वा त्रिवर्णं मण्डलं लिखेत्", text: "caturhastāṣṭahastaṃ vā dvātriṃśaddhastameva vā nalvamātrapramāṇaṃ vā trivarṇaṃ maṇḍalaṃ likhet" },
      { type: "verse", number: "6", sanskrit: "गोचर्मचापेषुमितस्त्रिविधो नल्व उच्यते चतुरस्रं चतुर्द्वारं पताकाभिरलङ्कृतम् आकीर्णं परितो दूर्वासिद्धार्थकयवाङ्कुरैः", text: "gocarmacāpeṣumitastrividho nalva ucyate caturasraṃ caturdvāraṃ patākābhiralaṅkṛtam ākīrṇaṃ parito dūrvāsiddhārthakayavāṅkuraiḥ" },
      { type: "verse", number: "7", sanskrit: "क्रमात् प्राच्यादिषु लिखेद् गजारूढं पुरन्दरम् धर्मराजं महिषगं चक्राह्वस्थमपां पतिम्", text: "kramāt prācyādiṣu likhed gajārūḍhaṃ purandaram dharmarājaṃ mahiṣagaṃ cakrāhvasthamapāṃ patim" },
      { type: "verse", number: "8", sanskrit: "धनदं च गदापाणिं यमस्थानमतीत्य च मातृस्थानं लिखेत्तस्मिन् सवृषं नन्दिकेश्वरम् सवध्वनुचरं चादौ मृन्मयं च विनायकम्", text: "dhanadaṃ ca gadāpāṇiṃ yamasthānamatītya ca mātṛsthānaṃ likhettasmin savṛṣaṃ nandikeśvaram savadhvanucaraṃ cādau mṛnmayaṃ ca vināyakam" },
      { type: "verse", number: "9", sanskrit: "अतीत्य वरुणावासं सहस्रारं निवेशयेत् विष्णुप्रहरणं चक्रं सर्वविघ्ननिवारणम्", text: "atītya varuṇāvāsaṃ sahasrāraṃ niveśayet viṣṇupraharaṇaṃ cakraṃ sarvavighnanivāraṇam" },
      { type: "verse", number: "10", sanskrit: "सुरयक्षेशयोर्मध्ये पद्महस्तालयां श्रियम् नन्द्यावर्ताङ्कुशादर्शमत्स्यस्वस्तिकतोरणम्", text: "surayakṣeśayormadhye padmahastālayāṃ śriyam nandyāvartāṅkuśādarśamatsyasvastikatoraṇam" },
      { type: "verse", number: "11", sanskrit: "शङ्खं च दक्षिणावर्तं श्रीवत्सं माल्यदाम च इन्द्रादीनां परीवारमैशान्यादि विदिक्षुच", text: "śaṅkhaṃ ca dakṣiṇāvartaṃ śrīvatsaṃ mālyadāma ca indrādīnāṃ parīvāramaiśānyādi vidikṣuca" },
      { type: "verse", number: "12", sanskrit: "लम्बोदरी लम्बभुजा लम्बकर्णी च राक्षसी इन्द्रद्वारे निवेश्याः स्युर्यमद्वारे प्रलम्बिनी लम्बकेश्यप्पतिद्वारे कौबेरे लम्बनासिका", text: "lambodarī lambabhujā lambakarṇī ca rākṣasī indradvāre niveśyāḥ syuryamadvāre pralambinī lambakeśyappatidvāre kaubere lambanāsikā" },
      { type: "verse", number: "13", sanskrit: "षट्कीलानायसान्कुर्यात्सप्त त्रैलोहिकान् भिषक् द्वौ चात्र खादिरौ शङ्कू चन्दनाम्बुसमुक्षितौ", text: "ṣaṭkīlānāyasānkuryātsapta trailohikān bhiṣak dvau cātra khādirau śaṅkū candanāmbusamukṣitau" },
      { type: "verse", number: "14", sanskrit: "अष्टौ घटाः षोडश वा द्वात्रिंशद्विगुणा अपि स्वस्तिकाङ्काः प्रवालाभा रङ्गैरश्लेषकैः कृताः", text: "aṣṭau ghaṭāḥ ṣoḍaśa vā dvātriṃśadviguṇā api svastikāṅkāḥ pravālābhā raṅgairaśleṣakaiḥ kṛtāḥ" },
      { type: "verse", number: "15", sanskrit: "यथार्हौषधसंयुक्तशुचितोयप्रपूरिताः क्षीरिवृक्षपलाशाब्जगन्धमाल्योपशोभिताः मण्डलस्य चतुर्द्वारे कर्तव्याः सुनिवेशिताः", text: "yathārhauṣadhasaṃyuktaśucitoyaprapūritāḥ kṣīrivṛkṣapalāśābjagandhamālyopaśobhitāḥ maṇḍalasya caturdvāre kartavyāḥ suniveśitāḥ" },
      { type: "verse", number: "16", sanskrit: "पूर्वेषु प्रक्षिपेद्धेम ततश्च मणिमौक्तिकम् अपरेष्वौषधीबीजानुदक्ष्वक्षतसर्षपान्", text: "pūrveṣu prakṣipeddhema tataśca maṇimauktikam apareṣvauṣadhībījānudakṣvakṣatasarṣapān" },
      { type: "verse", number: "17", sanskrit: "मृदः पवित्रा रक्षोघ्नीराहरेत सुरालयात् हस्तिशालाश्वशालाभ्यां शृङ्गाटकचतुष्पथात्", text: "mṛdaḥ pavitrā rakṣoghnīrāhareta surālayāt hastiśālāśvaśālābhyāṃ śṛṅgāṭakacatuṣpathāt" },
      { type: "verse", number: "18", sanskrit: "वल्मीकाग्रान्नदीतीराद्वेश्याकोशनृपालयात् गुप्तिद्वारात् समुद्राच्च समिद्धं चाग्निमाहरेत्", text: "valmīkāgrānnadītīrādveśyākośanṛpālayāt guptidvārāt samudrācca samiddhaṃ cāgnimāharet" },
      { type: "verse", number: "19", sanskrit: "समिधः क्षीरिवृक्षाणां गन्धमाल्यं घृतं मधु अक्षतांस्तण्डुलानलाजान्पञ्चवर्णौदनंतिलान्", text: "samidhaḥ kṣīrivṛkṣāṇāṃ gandhamālyaṃ ghṛtaṃ madhu akṣatāṃstaṇḍulānalājānpañcavarṇaudanaṃtilān" },
      { type: "verse", number: "20", sanskrit: "ततो मध्यस्थिते पद्मे सह धात्र्योपवेशयेत् बालमौदुम्बरे पीठे पालाशे वाप्युदङ्मुखम् आस्तृते हरितैर्दर्भैर्न तु प्राच्यादिदिङ्मुखम्", text: "tato madhyasthite padme saha dhātryopaveśayet bālamaudumbare pīṭhe pālāśe vāpyudaṅmukham āstṛte haritairdarbhairna tu prācyādidiṅmukham" },
      { type: "verse", number: "21", sanskrit: "उदाहरिष्यते मन्त्रो यः स्कन्दबलिकर्मणि जुहुयात्तेन तत्राग्निमुदीच्यां स्थापितं दिशि", text: "udāhariṣyate mantro yaḥ skandabalikarmaṇi juhuyāttena tatrāgnimudīcyāṃ sthāpitaṃ diśi" },
      { type: "verse", number: "22", sanskrit: "त्रिरात्रोपोषितो वैद्यः शुक्लवासा जितेन्द्रियः सर्षपाक्षतयुक्ताभिर्मृद्भिर्गात्राणि मार्जयन्", text: "trirātropoṣito vaidyaḥ śuklavāsā jitendriyaḥ sarṣapākṣatayuktābhirmṛdbhirgātrāṇi mārjayan" },
      { type: "verse", number: "23", sanskrit: "यथोदिताभिःस्नपयेत्घटैःप्राच्यादिदिक्स्थितैः क्रमात् प्रदक्षिणोत्क्षिप्तैः तत्र मन्त्रं प्रयोजयेत्", text: "yathoditābhiḥsnapayetghaṭaiḥprācyādidiksthitaiḥ kramāt pradakṣiṇotkṣiptaiḥ tatra mantraṃ prayojayet" },
      { type: "verse", number: "24", sanskrit: "अमृतात् पूर्वमुत्पन्नमिमं ते कलशं शुभम् ददातु भगवानिन्द्रो विजयं नाम नामतः", text: "amṛtāt pūrvamutpannamimaṃ te kalaśaṃ śubham dadātu bhagavānindro vijayaṃ nāma nāmataḥ" },
      { type: "verse", number: "25", sanskrit: "रक्तपीताम्बरधरैर्भूतैर्बहुभिरन्वितः राक्षसोरगगन्धर्वपिशाचैश्चानुसेवितः", text: "raktapītāmbaradharairbhūtairbahubhiranvitaḥ rākṣasoragagandharvapiśācaiścānusevitaḥ" },
      { type: "verse", number: "26", sanskrit: "वज्रघण्टाशनिधरैर्मेघैश्च विविधस्वनैः देवसङ्घैः परिवृतो गजेन्द्रस्कन्धसंश्रितः", text: "vajraghaṇṭāśanidharairmeghaiśca vividhasvanaiḥ devasaṅghaiḥ parivṛto gajendraskandhasaṃśritaḥ" },
      { type: "verse", number: "27", sanskrit: "एभिः सार्धं महानिन्द्रः स्नपनं तेनुमन्यताम् पूर्वद्वारे स्थितं दिव्यं वज्रमिन्द्राज्ञया शुभम्", text: "ebhiḥ sārdhaṃ mahānindraḥ snapanaṃ tenumanyatām pūrvadvāre sthitaṃ divyaṃ vajramindrājñayā śubham" },
      { type: "verse", number: "28", sanskrit: "तव सर्वाणि पापानि निहन्ता चापराजितः इन्द्राय नमः स्वाहा इन्द्राण्यै नमः स्वाहा अपराजिताय स्वाहा मेघाधिपतये स्वाहा देवाधिपतये स्वाहा शतक्रतवे स्वाहा", text: "tava sarvāṇi pāpāni nihantā cāparājitaḥ indrāya namaḥ svāhā indrāṇyai namaḥ svāhā aparājitāya svāhā meghādhipataye svāhā devādhipataye svāhā śatakratave svāhā" },
      { type: "verse", number: "29", sanskrit: "द्वितीयं कलशं पुण्यमादित्यसदृशप्रभम् यमो ददातु भगवान् वैजयन्तं तु नामतः", text: "dvitīyaṃ kalaśaṃ puṇyamādityasadṛśaprabham yamo dadātu bhagavān vaijayantaṃ tu nāmataḥ" },
      { type: "verse", number: "30", sanskrit: "कृष्णाञ्जननिभिर्घोरैः कृष्णाम्बरधरैस्तथा वृतः करालैर्विकृतै राक्षसैरुग्रविक्रमैः", text: "kṛṣṇāñjananibhirghoraiḥ kṛṣṇāmbaradharaistathā vṛtaḥ karālairvikṛtai rākṣasairugravikramaiḥ" },
      { type: "verse", number: "31", sanskrit: "श्मशानारण्यनिलयैर्मृतवस्त्रान्त्रभूषणैः त्वगस्थिमज्जमांसादैः प्रेतैर्बहुभिरावृतः", text: "śmaśānāraṇyanilayairmṛtavastrāntrabhūṣaṇaiḥ tvagasthimajjamāṃsādaiḥ pretairbahubhirāvṛtaḥ" },
      { type: "verse", number: "32", sanskrit: "धर्मराजो यमः श्रीमान् सत्यसन्धो महातपाः दिव्यं महिषमारुह्य स्नपनं तेनुमन्यताम्", text: "dharmarājo yamaḥ śrīmān satyasandho mahātapāḥ divyaṃ mahiṣamāruhya snapanaṃ tenumanyatām" },
      { type: "verse", number: "33", sanskrit: "दक्षिणद्वारसंस्थस्ते यमदण्डः प्रतापवान् दुःस्वप्नं दुष्कृतं पापं सर्वमद्य हनिष्यति", text: "dakṣiṇadvārasaṃsthaste yamadaṇḍaḥ pratāpavān duḥsvapnaṃ duṣkṛtaṃ pāpaṃ sarvamadya haniṣyati" },
      { type: "verse", number: "34", sanskrit: "यमाय नमः स्वाहा यमदण्डाय नमः स्वाहा महिषवाहनाय स्वाहा प्रेताधिपतये स्वाहा धर्माधिपतये स्वाहा वैजयन्ताय स्वाहा", text: "yamāya namaḥ svāhā yamadaṇḍāya namaḥ svāhā mahiṣavāhanāya svāhā pretādhipataye svāhā dharmādhipataye svāhā vaijayantāya svāhā" },
      { type: "verse", number: "35", sanskrit: "जयन्तं जयवृध्यर्धं तृतीयं कलशं शुभम् ददातु मधुराजस्ते भगवान् वरुणः स्वयम्", text: "jayantaṃ jayavṛdhyardhaṃ tṛtīyaṃ kalaśaṃ śubham dadātu madhurājaste bhagavān varuṇaḥ svayam" },
      { type: "verse", number: "36", sanskrit: "श्वेतमाल्याम्बरधरैः श्वेतगन्धानुलेपनैः गन्धर्वैः पन्नगेन्द्रैश्च भगवाननुशोभितः", text: "śvetamālyāmbaradharaiḥ śvetagandhānulepanaiḥ gandharvaiḥ pannagendraiśca bhagavānanuśobhitaḥ" },
      { type: "verse", number: "37", sanskrit: "तीर्थकूपनदीवृक्षनिष्कुटोद्यानवासिभिः प्रबलैः कापिलैर्मुण्डैर्विकटैर्वामनैस्तथा", text: "tīrthakūpanadīvṛkṣaniṣkuṭodyānavāsibhiḥ prabalaiḥ kāpilairmuṇḍairvikaṭairvāmanaistathā" },
      { type: "verse", number: "38", sanskrit: "वृतः परिषदैर्भूतैः पाशमुद्गरपाणिभिः एभिः सहाद्य भगवान् वरुणस्त्वाभिषिञ्चतु", text: "vṛtaḥ pariṣadairbhūtaiḥ pāśamudgarapāṇibhiḥ ebhiḥ sahādya bhagavān varuṇastvābhiṣiñcatu" },
      { type: "verse", number: "39", sanskrit: "वरुणस्य महापाशोप्यपरद्वारमाश्रितः तव पापं निहन्त्वाशु सर्वविघ्ननिवारणः", text: "varuṇasya mahāpāśopyaparadvāramāśritaḥ tava pāpaṃ nihantvāśu sarvavighnanivāraṇaḥ" },
      { type: "verse", number: "40", sanskrit: "वरुणाय नमः स्वाहा श्वेताम्बरधराय स्वाहा मकरवाहनाय स्वाहा जयन्ताय स्वाहा", text: "varuṇāya namaḥ svāhā śvetāmbaradharāya svāhā makaravāhanāya svāhā jayantāya svāhā" },
      { type: "verse", number: "41", sanskrit: "चतुर्थं कलशं पुण्यं प्रधानमपराजितम् धनेश्वरो महाबाहुः प्रयच्छत्वलकाधिपः", text: "caturthaṃ kalaśaṃ puṇyaṃ pradhānamaparājitam dhaneśvaro mahābāhuḥ prayacchatvalakādhipaḥ" },
      { type: "verse", number: "42", sanskrit: "चित्रमाल्याम्बरधरौश्चित्रगन्धानुलेपनैः चित्रमद्यमदोन्मत्तैर्यक्षैः समुपसेवितः", text: "citramālyāmbaradharauścitragandhānulepanaiḥ citramadyamadonmattairyakṣaiḥ samupasevitaḥ" },
      { type: "verse", number: "43", sanskrit: "मुदितोद्गीतगन्धैर्वैः सेवितश्चाप्सरोगणैः स ते वैश्रवणः श्रीमान् स्नपनन्त्वनुमन्यताम्", text: "muditodgītagandhairvaiḥ sevitaścāpsarogaṇaiḥ sa te vaiśravaṇaḥ śrīmān snapanantvanumanyatām" },
      { type: "verse", number: "44", sanskrit: "सर्वव्याधिहरा दीप्ता द्वारमुत्तरमाश्रिता गदा ते नाशयत्वद्य सर्वपापं दिशो दश", text: "sarvavyādhiharā dīptā dvāramuttaramāśritā gadā te nāśayatvadya sarvapāpaṃ diśo daśa" },
      { type: "verse", number: "45", sanskrit: "धनाधिपतये स्वाहा गदापाणये स्वाहा अपराजिताय स्वाहा चित्राम्बरधराय स्वाहा", text: "dhanādhipataye svāhā gadāpāṇaye svāhā aparājitāya svāhā citrāmbaradharāya svāhā" },
      { type: "verse", number: "46", sanskrit: "आपः पवित्रं लोकेस्मिन्नापो वै परमं शुचिः आपो वै देवताः सर्वा आपस्त्वामभिषिच्यताम् ब्रह्माब्रह्मर्षिभिः सार्धं भगवांस्त्वाभिषिञ्च तु", text: "āpaḥ pavitraṃ lokesminnāpo vai paramaṃ śuciḥ āpo vai devatāḥ sarvā āpastvāmabhiṣicyatām brahmābrahmarṣibhiḥ sārdhaṃ bhagavāṃstvābhiṣiñca tu" },
      { type: "verse", number: "47", sanskrit: "स्वाहा साङ्गोपाङ्गास्तथा वेदाः कीर्तिर्लक्ष्मीः सरस्वती बाला दाक्षायणी सीता सावित्री सरमा द्युतिः आकाशगङ्गा गङ्गाद्या महानद्यो महोदधिः", text: "svāhā sāṅgopāṅgāstathā vedāḥ kīrtirlakṣmīḥ sarasvatī bālā dākṣāyaṇī sītā sāvitrī saramā dyutiḥ ākāśagaṅgā gaṅgādyā mahānadyo mahodadhiḥ" },
      { type: "verse", number: "48", sanskrit: "नदीनां सङ्गमास्तीर्था निर्झराः सागरास्तथा मेरुर्महेन्द्रो हिमवान् जगच्च स्थावरत्रयम्", text: "nadīnāṃ saṅgamāstīrthā nirjharāḥ sāgarāstathā merurmahendro himavān jagacca sthāvaratrayam" },
      { type: "verse", number: "49", sanskrit: "स्कन्दादयो ग्रहाश्चैव तोषिता बलिकर्मणा अद्य त्वामभिषिञ्चन्तु नीरुजो भव दारक", text: "skandādayo grahāścaiva toṣitā balikarmaṇā adya tvāmabhiṣiñcantu nīrujo bhava dāraka" },
      { type: "verse", number: "50", sanskrit: "नमो भगवते पितामहाय ॐ मं ॐ मं ल्मि ल्मि लिभुक् लिभुक् लिपिभवनेभ्यः स्वाहा", text: "namo bhagavate pitāmahāya oṃ maṃ oṃ maṃ lmi lmi libhuk libhuk lipibhavanebhyaḥ svāhā" },
      { type: "verse", number: "51", sanskrit: "नमो भगवते रुद्राय हिलिमिलि मेल्लि मेल्लि वेल्लि वेल्लि म्मिलिम्मिलि स्वाहा", text: "namo bhagavate rudrāya hilimili melli melli velli velli mmilimmili svāhā" },
      { type: "verse", number: "52", sanskrit: "राक्षसाच पलायन्तु भूताश्च त्रस्तमानसाः मृताशना महाजिह्वास्तथा विघ्नविनायकाः", text: "rākṣasāca palāyantu bhūtāśca trastamānasāḥ mṛtāśanā mahājihvāstathā vighnavināyakāḥ" },
      { type: "verse", number: "53", sanskrit: "नमो भगवते कुमाराय पिलि पिलि खिल्लि खिल्लि खिणि खिणि स्वाहा", text: "namo bhagavate kumārāya pili pili khilli khilli khiṇi khiṇi svāhā" },
      { type: "verse", number: "54", sanskrit: "पुष्करं पुष्करारण्यं नैमिषं च तथा गया प्रभासं प्रवरं तीर्थं तथा पिण्डारकाह्वयम् तीर्थान्येतानि सर्वाणि अभिषिञ्चन्तु स्वस्ति ते", text: "puṣkaraṃ puṣkarāraṇyaṃ naimiṣaṃ ca tathā gayā prabhāsaṃ pravaraṃ tīrthaṃ tathā piṇḍārakāhvayam tīrthānyetāni sarvāṇi abhiṣiñcantu svasti te" },
      { type: "verse", number: "55", sanskrit: "नमो भगवतीभ्यो महायोगीश्वरीभ्यो निमिनिमि मेनुमेनु तुरुतुरु स्वाहा", text: "namo bhagavatībhyo mahāyogīśvarībhyo niminimi menumenu turuturu svāhā" },
      { type: "verse", number: "56", sanskrit: "याश्च जातापहारिण्यो राक्षस्यो विकृताननाः अपि ता निहताः सर्वा याश्चान्याः पापचिन्तकाः", text: "yāśca jātāpahāriṇyo rākṣasyo vikṛtānanāḥ api tā nihatāḥ sarvā yāścānyāḥ pāpacintakāḥ" },
      { type: "verse", number: "57", sanskrit: "सतीनां कपिलानां च सिद्धानां चैव तेजसा तेजसा चर्षिविप्राणां मयाद्य स्नपितो भवान्", text: "satīnāṃ kapilānāṃ ca siddhānāṃ caiva tejasā tejasā carṣiviprāṇāṃ mayādya snapito bhavān" },
      { type: "verse", number: "58", sanskrit: "प्रभुर्मृत्युरलक्ष्मीश्च कालरात्रिश्च सारथिः लम्बा च लोहशङ्कुश्च पूतना कूटपूतना अशुभं यच्च ते किञ्चित् सर्वं प्रतिहतं मया", text: "prabhurmṛtyuralakṣmīśca kālarātriśca sārathiḥ lambā ca lohaśaṅkuśca pūtanā kūṭapūtanā aśubhaṃ yacca te kiñcit sarvaṃ pratihataṃ mayā" },
      { type: "verse", number: "59", sanskrit: "आदित्या वसवो रुद्रा अश्विनावौषधीगणाः गावोन्तरिक्षं सन्ध्ये च नक्षत्रग्रहवत्सराः", text: "ādityā vasavo rudrā aśvināvauṣadhīgaṇāḥ gāvontarikṣaṃ sandhye ca nakṣatragrahavatsarāḥ" },
      { type: "verse", number: "60", sanskrit: "विश्वावसुश्च हाहा च नारदस्तुम्बुरुस्तथा धन्वन्तरिरगस्त्यश्च सुस्नातं प्रदिशन्तु ते", text: "viśvāvasuśca hāhā ca nāradastumburustathā dhanvantariragastyaśca susnātaṃ pradiśantu te" },
      { type: "verse", number: "61", sanskrit: "स्नातो द्विजभिषग्भृत्यान्यथाविभवमर्चयेत् मांसव्यवायाहःस्वप्नान् पञ्चरात्रं विवर्जयेत्", text: "snāto dvijabhiṣagbhṛtyānyathāvibhavamarcayet māṃsavyavāyāhaḥsvapnān pañcarātraṃ vivarjayet" },
      { type: "verse", number: "62", sanskrit: "स्नपनं पाप्मजित् पुण्यं नीरुजामपि पुष्टिकृत् रोगिणां सर्वरोगघ्नं वन्ध्यानामपि पुत्रदम्", text: "snapanaṃ pāpmajit puṇyaṃ nīrujāmapi puṣṭikṛt rogiṇāṃ sarvarogaghnaṃ vandhyānāmapi putradam" },
      { type: "verse", number: "63", sanskrit: "विधिना विधिहीनन्तु सवैद्यं हन्ति बालकम् नैतदश्रद्दधानाय योज्यं नानुपसीदते", text: "vidhinā vidhihīnantu savaidyaṃ hanti bālakam naitadaśraddadhānāya yojyaṃ nānupasīdate" },
      { type: "verse", number: "64", sanskrit: "पूतीकरञ्जत्वक्पत्रं क्षीरिभ्यो बर्बरादपि तुम्बीविशालारलुकशमीबिल्वकपित्थतः", text: "pūtīkarañjatvakpatraṃ kṣīribhyo barbarādapi tumbīviśālāralukaśamībilvakapitthataḥ" },
      { type: "verse", number: "65", sanskrit: "स्थाल्यामुत्क्वाथ्य तत्तोयं बालानां स्नपनं शिवम् रात्रौ प्रसुप्तलोकायां पुष्टिदं सर्वरोगजित्", text: "sthālyāmutkvāthya tattoyaṃ bālānāṃ snapanaṃ śivam rātrau prasuptalokāyāṃ puṣṭidaṃ sarvarogajit" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 6,
    lang: "sa",
    content: [
      { type: "heading", heading: "Наса рога — болезни носа — обзор" },
      { type: "text", text: "Глава 6 Уттара стханы — «Наса рога» — посвящена специализированному разделу: болезни носа — обзор. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः प्रत्येकग्रहप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ pratyekagrahapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "स्कन्दग्रहे गुग्गुल्वेलवालुकमनश्शिलाहरितालमञ्जिष्ठोशीररास्नागरुदेवदारुश्रीवेष्टकहरेणूगिरिकदम्बकचन्दनैः श्लक्ष्णपिष्टैः प्रदेहो वातहरवृक्षपत्रक्वाथेन कवोष्णेन परिषेकस्तेषामेव च मूलक्वाथे सर्वगन्धसुरामण्डकैडर्यावापवत्तैलं विपक्वमभ्यङ्गः", text: "skandagrahe guggulvelavālukamanaśśilāharitālamañjiṣṭhośīrarāsnāgarudevadāruśrīveṣṭakahareṇūgirikadambakacandanaiḥ ślakṣṇapiṣṭaiḥ pradeho vātaharavṛkṣapatrakvāthena kavoṣṇena pariṣekasteṣāmeva ca mūlakvāthe sarvagandhasurāmaṇḍakaiḍaryāvāpavattailaṃ vipakvamabhyaṅgaḥ" },
      { type: "verse", number: "3", sanskrit: "बृंहतीद्वयद्विपुर्ननवरेणुकोपकुल्यामुस्तखदिरवचाशङ्खनाभिसरलसर्पसुगन्धासुराह्वकल्कविपक्वंवा", text: "bṛṃhatīdvayadvipurnanavareṇukopakulyāmustakhadiravacāśaṅkhanābhisaralasarpasugandhāsurāhvakalkavipakvaṃvā" },
      { type: "verse", number: "4", sanskrit: "क्षीरिवृक्षकषायेण क्षीरेण च सिद्धमर्धपलिकैश्च पिष्टैः सारिवाद्विकाकोलीद्विबलांशुमतीद्वयहस्तिकर्णपर्णैर्घृतप्रस्थं पानम्", text: "kṣīrivṛkṣakaṣāyeṇa kṣīreṇa ca siddhamardhapalikaiśca piṣṭaiḥ sārivādvikākolīdvibalāṃśumatīdvayahastikarṇaparṇairghṛtaprasthaṃ pānam" },
      { type: "verse", number: "5", sanskrit: "रास्नादेवदार्वन्यतरकल्केन वा सक्षीरं साधितं सर्पिः", text: "rāsnādevadārvanyatarakalkena vā sakṣīraṃ sādhitaṃ sarpiḥ" },
      { type: "verse", number: "6", sanskrit: "वचाकाकादनीसर्पकञ्चुकसर्षपैरुष्ट्राजाव्यश्वगोरोमभिश्च सघृतैर्धूपैः सिद्धार्थकसर्जरसकुष्ठहिङ्गुगुग्गुलुभिर्वा", text: "vacākākādanīsarpakañcukasarṣapairuṣṭrājāvyaśvagoromabhiśca saghṛtairdhūpaiḥ siddhārthakasarjarasakuṣṭhahiṅguguggulubhirvā" },
      { type: "verse", number: "7", sanskrit: "सोमवल्लीन्द्रवल्लीशमीबिल्ववृन्दाकमृगादिनीमूलानि सूत्रेण ग्रथितानि कण्ठेन शिरसा वा धारयेत्", text: "somavallīndravallīśamībilvavṛndākamṛgādinīmūlāni sūtreṇa grathitāni kaṇṭhena śirasā vā dhārayet" },
      { type: "verse", number: "8", sanskrit: "रक्तमाल्यानुलेपनवस्त्रपताकामणिबीजैर्विविधैश्च भक्ष्यैः सदधिघृतमधुलाजकुल्माषमांसमत्स्यसुरासवं समयूरकुक्कुटं सघण्टाकं सशूर्पव्यजनं च कुमारग्रहे रक्तौदनेन बलिमुपोषितो निवेदयेत्", text: "raktamālyānulepanavastrapatākāmaṇibījairvividhaiśca bhakṣyaiḥ sadadhighṛtamadhulājakulmāṣamāṃsamatsyasurāsavaṃ samayūrakukkuṭaṃ saghaṇṭākaṃ saśūrpavyajanaṃ ca kumāragrahe raktaudanena balimupoṣito nivedayet" },
      { type: "verse", number: "9", sanskrit: "तत्र च रात्रावग्निं ज्वालयित्वा मन्त्रमिमं पठन् मधुसर्पिषा जुहुयात्", text: "tatra ca rātrāvagniṃ jvālayitvā mantramimaṃ paṭhan madhusarpiṣā juhuyāt" },
      { type: "verse", number: "10", sanskrit: "अग्नये कृत्तिकाभ्यश्च स्वाहा स्वाहेति चान्ततः नमः स्कन्दाय देवाय ग्रहाधिपतये नमः", text: "agnaye kṛttikābhyaśca svāhā svāheti cāntataḥ namaḥ skandāya devāya grahādhipataye namaḥ" },
      { type: "verse", number: "11", sanskrit: "शिरसा त्वाभिवन्देहं प्रतिगृह्णीष्व मे बलिम् नीरुजो निर्विकारश्च शिशुर्भवतु सर्वदा", text: "śirasā tvābhivandehaṃ pratigṛhṇīṣva me balim nīrujo nirvikāraśca śiśurbhavatu sarvadā" },
      { type: "verse", number: "12", sanskrit: "सर्वेष्वेव ग्रहेषु त्रिकालमग्निं पूजयेत्तर्पयेच्च विशेषतः स्कन्दग्रहे त्रिरात्रं च रात्रौ रात्रौ गायत्र्यभिमन्त्रितोदकेन चत्वरे धात्रीकुमारयोः स्नपनमाचरेत्", text: "sarveṣveva graheṣu trikālamagniṃ pūjayettarpayecca viśeṣataḥ skandagrahe trirātraṃ ca rātrau rātrau gāyatryabhimantritodakena catvare dhātrīkumārayoḥ snapanamācaret" },
      { type: "verse", number: "13", sanskrit: "त्रिकालं च मन्त्रेणानेन बालमपमार्जयेत् प्रतिसरां च बध्नीयात्", text: "trikālaṃ ca mantreṇānena bālamapamārjayet pratisarāṃ ca badhnīyāt" },
      { type: "verse", number: "14", sanskrit: "तपसां तेजसां चैव यशसां वपुषां तथा विधाता यो ऽव्ययो देवः स ते स्कन्दः प्रसीदतु", text: "tapasāṃ tejasāṃ caiva yaśasāṃ vapuṣāṃ tathā vidhātā yo 'vyayo devaḥ sa te skandaḥ prasīdatu" },
      { type: "verse", number: "15", sanskrit: "ग्रहसेनापतिर्देवो देवसेनापतिर्विभुः देवसेनारिपुहरः पातु त्वा भगवान् गुहः", text: "grahasenāpatirdevo devasenāpatirvibhuḥ devasenāripuharaḥ pātu tvā bhagavān guhaḥ" },
      { type: "verse", number: "16", sanskrit: "देवदेवस्य महतः पावकस्य च यः सुतः गङ्गोमाकृत्तिकानां च स ते शर्म प्रयच्छुतु", text: "devadevasya mahataḥ pāvakasya ca yaḥ sutaḥ gaṅgomākṛttikānāṃ ca sa te śarma prayacchutu" },
      { type: "verse", number: "17", sanskrit: "रक्तमाल्याम्बरः श्रीमान् रक्तचन्दनभूषितः रक्तादित्यवपुर्देवः पातु त्वा क्रौञ्चसूदन इति", text: "raktamālyāmbaraḥ śrīmān raktacandanabhūṣitaḥ raktādityavapurdevaḥ pātu tvā krauñcasūdana iti" },
      { type: "verse", number: "18", sanskrit: "विशाखे स्कन्दग्रहोक्तो वचाकुष्ठान्वितः प्रदेहो गोलोमीबिल्वशिरीषमुस्तसुरसादिक्वाथेन परिषेकः सर्पसुगन्धादेवदारुकुष्ठमुस्ताकल्केन सगोमूत्रबस्तमूत्रेण सिद्धं तैलमभ्यङ्गः", text: "viśākhe skandagrahokto vacākuṣṭhānvitaḥ pradeho golomībilvaśirīṣamustasurasādikvāthena pariṣekaḥ sarpasugandhādevadārukuṣṭhamustākalkena sagomūtrabastamūtreṇa siddhaṃ tailamabhyaṅgaḥ" },
      { type: "verse", number: "19", sanskrit: "क्षीरिवृक्षकषायेण जीवनीयगर्भं सपयस्कं सर्पिः सिद्धं पानम् जीवकर्षभक्षीरिणीबृहतीहरिद्रांशुमतीद्वयमधुकैर्वा विदारीद्वयतवक्षीरीमृद्वीकामधुकरास्नानीलोत्पलकन्दवचाव्योषैर्वा", text: "kṣīrivṛkṣakaṣāyeṇa jīvanīyagarbhaṃ sapayaskaṃ sarpiḥ siddhaṃ pānam jīvakarṣabhakṣīriṇībṛhatīharidrāṃśumatīdvayamadhukairvā vidārīdvayatavakṣīrīmṛdvīkāmadhukarāsnānīlotpalakandavacāvyoṣairvā" },
      { type: "verse", number: "20", sanskrit: "गृद्ध्रोलूकपुरीषवृषभरोमकेशहस्तिनखैर्घृताक्तैर्धूपः अनन्ताकुक्कुटीमर्कटीबिम्बीसमङ्गाश्वेतगिरिकर्णीकाः पूर्वोक्तानि च पूर्ववद्धारयेत्", text: "gṛddhrolūkapurīṣavṛṣabharomakeśahastinakhairghṛtāktairdhūpaḥ anantākukkuṭīmarkaṭībimbīsamaṅgāśvetagirikarṇīkāḥ pūrvoktāni ca pūrvavaddhārayet" },
      { type: "verse", number: "21", sanskrit: "पक्वाममांसरुधिरदधिवारुणीयुक्तो वटवृक्षे बलिश्चतुष्पथे स्नानम् मन्त्रश्च", text: "pakvāmamāṃsarudhiradadhivāruṇīyukto vaṭavṛkṣe baliścatuṣpathe snānam mantraśca" },
      { type: "verse", number: "22", sanskrit: "स्कन्दापस्मारसंज्ञो यः स्कन्दस्य दयितः सखा विशाखसंज्ञः स शिशोः शिवोस्तु विकृताननः", text: "skandāpasmārasaṃjño yaḥ skandasya dayitaḥ sakhā viśākhasaṃjñaḥ sa śiśoḥ śivostu vikṛtānanaḥ" },
      { type: "verse", number: "23", sanskrit: "नैगमेषे विशाखोक्तः प्रदेहोग्निमन्थवरुणनलरोहिषपूतीकपारिभद्रकैः परिषेको धान्याम्लेन सबीजेन गुग्गुल्वश्वगन्धासर्षपोशीरश्वेताकुष्ठशताह्वाविपक्वं तैलमभ्यङ्गः", text: "naigameṣe viśākhoktaḥ pradehognimanthavaruṇanalarohiṣapūtīkapāribhadrakaiḥ pariṣeko dhānyāmlena sabījena guggulvaśvagandhāsarṣapośīraśvetākuṣṭhaśatāhvāvipakvaṃ tailamabhyaṅgaḥ" },
      { type: "verse", number: "24", sanskrit: "दशमूलक्वाथे मधुरस्कन्धगर्भं सक्षीरं सर्पिः पानम् सर्पगन्धाबस्तनखरोमभिर्धूपः सर्पगन्धाबस्तगन्धातुम्बीमृगोर्वारुशतावरीसहदेवापुनर्नवबीजानि धारयेत्", text: "daśamūlakvāthe madhuraskandhagarbhaṃ sakṣīraṃ sarpiḥ pānam sarpagandhābastanakharomabhirdhūpaḥ sarpagandhābastagandhātumbīmṛgorvāruśatāvarīsahadevāpunarnavabījāni dhārayet" },
      { type: "verse", number: "25", sanskrit: "विचित्रमाल्यफलशुक्लविलेपनौदनदधिघृतगुडक्षीरैर्महापथे क्षीरिद्रुमे वा बलिः नदीतीरे स्नानम् मन्त्रश्च", text: "vicitramālyaphalaśuklavilepanaudanadadhighṛtaguḍakṣīrairmahāpathe kṣīridrume vā baliḥ nadītīre snānam mantraśca" },
      { type: "verse", number: "26", sanskrit: "अजाननश्चलाक्षिभ्रूः कामरूपी महायशाः बालं बालहितो देवो नैगमेषो ऽभिरक्षतु", text: "ajānanaścalākṣibhrūḥ kāmarūpī mahāyaśāḥ bālaṃ bālahito devo naigameṣo 'bhirakṣatu" },
      { type: "verse", number: "27", sanskrit: "स्वाहा श्वग्रहे गवाक्षीब्रह्मदत्ताबृहतीद्वयसारिवाद्द्रीवेरकुष्ठभूमिकदम्बसुरसमञ्जरीकरवीरपुष्पैः प्रदेहः मयूरो लूकाश्वमहिषीपुरीषरोमभिश्च बिल्वैरण्डनक्तमालारलुकपत्रक्वाथः परिषेकः", text: "svāhā śvagrahe gavākṣībrahmadattābṛhatīdvayasārivāddrīverakuṣṭhabhūmikadambasurasamañjarīkaravīrapuṣpaiḥ pradehaḥ mayūro lūkāśvamahiṣīpurīṣaromabhiśca bilvairaṇḍanaktamālāralukapatrakvāthaḥ pariṣekaḥ" },
      { type: "verse", number: "28", sanskrit: "वयस्थाशतावरीसारिवापयस्यैरण्डसहदेवात्रिकटुककल्कक्षीरसिद्धं तैलमभ्यङ्गः तथैव च घृतं पानम् गोबस्तमूत्रभावितशुष्कमत्स्यचूर्णो निशीथे धूपः", text: "vayasthāśatāvarīsārivāpayasyairaṇḍasahadevātrikaṭukakalkakṣīrasiddhaṃ tailamabhyaṅgaḥ tathaiva ca ghṛtaṃ pānam gobastamūtrabhāvitaśuṣkamatsyacūrṇo niśīthe dhūpaḥ" },
      { type: "verse", number: "29", sanskrit: "वचावयस्थाब्राह्मीजटिलागोलोमीलम्बापूतनाकेशीगिरिकदम्बकेकैषीकासहदेवीर्धारयेत्", text: "vacāvayasthābrāhmījaṭilāgolomīlambāpūtanākeśīgirikadambakekaiṣīkāsahadevīrdhārayet" },
      { type: "verse", number: "30", sanskrit: "सघृतसुरामांसदधिरुधिरपललश्चत्वरे बलिः सङ्करकूटे स्नानम् मन्त्रश्च", text: "saghṛtasurāmāṃsadadhirudhirapalalaścatvare baliḥ saṅkarakūṭe snānam mantraśca" },
      { type: "verse", number: "31", sanskrit: "रक्षार्थं कार्तिकेयस्य कृत्तिकोमाग्निशूलिभिः योसौ श्वविग्रहः सृष्टः स देवस्त्वाभिरक्षतु", text: "rakṣārthaṃ kārtikeyasya kṛttikomāgniśūlibhiḥ yosau śvavigrahaḥ sṛṣṭaḥ sa devastvābhirakṣatu" },
      { type: "verse", number: "32", sanskrit: "स्वाहा पितृग्रहे पूर्वोक्तः प्रदेहो वचावयस्थाजीवन्तीधातकीप्रियङ्गुगुग्गुलुरास्नामनश्शिलालैर्वा वचादिभिरेव सिद्धं तैलमभ्यङ्गः", text: "svāhā pitṛgrahe pūrvoktaḥ pradeho vacāvayasthājīvantīdhātakīpriyaṅguguggulurāsnāmanaśśilālairvā vacādibhireva siddhaṃ tailamabhyaṅgaḥ" },
      { type: "verse", number: "33", sanskrit: "बिल्वकपित्थकरञ्जतर्कारीसुरसपाटलीवरणपारिभद्रकपारिजातमातुलुङ्गपत्रक्वाथेन रात्रौ परिषेको बिल्वादिभिरेव च तैलं सुराबस्तमूत्रयुक्तं साधितमभ्यङ्गः", text: "bilvakapitthakarañjatarkārīsurasapāṭalīvaraṇapāribhadrakapārijātamātuluṅgapatrakvāthena rātrau pariṣeko bilvādibhireva ca tailaṃ surābastamūtrayuktaṃ sādhitamabhyaṅgaḥ" },
      { type: "verse", number: "34", sanskrit: "त्रिफलांशुमतीद्वयपयस्यामधुककल्केन दशमूलनिर्यूहे सक्षीरं सर्पिः पक्वं पानम् देवदारुभार्ङ्गीविडङ्ग चन्दनकाकोलीद्वयजीवकर्षभकैर्वा सक्षारैः", text: "triphalāṃśumatīdvayapayasyāmadhukakalkena daśamūlaniryūhe sakṣīraṃ sarpiḥ pakvaṃ pānam devadārubhārṅgīviḍaṅga candanakākolīdvayajīvakarṣabhakairvā sakṣāraiḥ" },
      { type: "verse", number: "35", sanskrit: "लक्ष्मीपुरकुष्ठगोलोमीजटिलोग्रगन्धाभिः सिद्धं तैलं नावनम् एभिरेव च सुरापिष्टैर्लेपः", text: "lakṣmīpurakuṣṭhagolomījaṭilogragandhābhiḥ siddhaṃ tailaṃ nāvanam ebhireva ca surāpiṣṭairlepaḥ" },
      { type: "verse", number: "36", sanskrit: "गृद्ध्रोलूकवानररोमाणि सघृतानि तत्पुरीषं वा सुप्तजने धूपो वचादिभिर्वा प्रदेहोक्तैः पूर्वोक्तो वा पूर्वोक्ता एव च धारयेत्", text: "gṛddhrolūkavānararomāṇi saghṛtāni tatpurīṣaṃ vā suptajane dhūpo vacādibhirvā pradehoktaiḥ pūrvokto vā pūrvoktā eva ca dhārayet" },
      { type: "verse", number: "37", sanskrit: "सुरासवगुडापूपपिष्टतिलकृतभक्षो वृक्षमूले सवृषभः काञ्चनाक्षियुगयुक्तः स्वयं पित्रा कुमारस्य निर्वापणीयो बलिः क्षीरिवृक्षसमीपे स्नानम् मन्त्रश्व", text: "surāsavaguḍāpūpapiṣṭatilakṛtabhakṣo vṛkṣamūle savṛṣabhaḥ kāñcanākṣiyugayuktaḥ svayaṃ pitrā kumārasya nirvāpaṇīyo baliḥ kṣīrivṛkṣasamīpe snānam mantraśva" },
      { type: "verse", number: "38", sanskrit: "यः पिता सर्वबालानां ग्रहाणां पूजितो वरः वृक्षमूले कृतावासः स त्वां पातु पिता सदा स्वाहा", text: "yaḥ pitā sarvabālānāṃ grahāṇāṃ pūjito varaḥ vṛkṣamūle kṛtāvāsaḥ sa tvāṃ pātu pitā sadā svāhā" },
      { type: "verse", number: "39", sanskrit: "शकुन्यां मधुकद्रीबेरोशीरसारिवापद्मकोत्पलमञ्जिष्टालोद्ध्रप्रियङ्गुगैरिकैः प्रदेहः सुरामूत्रपिष्टैर्वा लोध्रयष्टीमधुकमञ्जिष्ठाहरीतकीदेवदारुभिर्व्रणोक्ताश्च प्रदेहाः वेतसाम्लकपित्थैः सपञ्चमूलैर्वा शुक्तिशङ्खशम्बूकभस्ममञ्जिष्ठाभयामधुकैस्तैलं पक्वं व्रणरोपणम्", text: "śakunyāṃ madhukadrīberośīrasārivāpadmakotpalamañjiṣṭāloddhrapriyaṅgugairikaiḥ pradehaḥ surāmūtrapiṣṭairvā lodhrayaṣṭīmadhukamañjiṣṭhāharītakīdevadārubhirvraṇoktāśca pradehāḥ vetasāmlakapitthaiḥ sapañcamūlairvā śuktiśaṅkhaśambūkabhasmamañjiṣṭhābhayāmadhukaistailaṃ pakvaṃ vraṇaropaṇam" },
      { type: "verse", number: "40", sanskrit: "क्षीरितरुभिः परिषेको मार्कवमूलकामलकीत्वक्पत्रप्रियङ्गुमनश्शिलालैलाद्वययष्टीक्रमुकलोध्रधातकीसारिवाञ्जनोत्पलपतङ्गसमङ्गाद्विहरिद्रामांसीमञ्जिष्ठाचन्दनपद्मकसुवर्णगौरिकैस्तैलं सपयस्कं पक्वमभ्यङ्गो ग्रहहा व्रणरोपणश्च", text: "kṣīritarubhiḥ pariṣeko mārkavamūlakāmalakītvakpatrapriyaṅgumanaśśilālailādvayayaṣṭīkramukalodhradhātakīsārivāñjanotpalapataṅgasamaṅgādviharidrāmāṃsīmañjiṣṭhācandanapadmakasuvarṇagaurikaistailaṃ sapayaskaṃ pakvamabhyaṅgo grahahā vraṇaropaṇaśca" },
      { type: "verse", number: "41", sanskrit: "अर्जुनफललोध्रमधुकोदुम्बरवचाचूर्णं क्षौद्रयुक्तो मुखपाके मुखोद्घर्षः विशाखोक्तं सापः पानम् स्कन्दोक्तो धूपः काकपिच्छेन वा गोबालोग्रगन्धारक्षोघ्नघृतमयूरचन्द्रकैर्वा", text: "arjunaphalalodhramadhukodumbaravacācūrṇaṃ kṣaudrayukto mukhapāke mukhodgharṣaḥ viśākhoktaṃ sāpaḥ pānam skandokto dhūpaḥ kākapicchena vā gobālogragandhārakṣoghnaghṛtamayūracandrakairvā" },
      { type: "verse", number: "42", sanskrit: "कटम्भराकुक्कुटीमर्कटीलम्बासहदेवीह्रीबेरोशीराणि धारयेत् नागदन्ती लक्ष्मणाबृहतीद्वयमृगोर्वारुशतावरीसहदेव्यो वा", text: "kaṭambharākukkuṭīmarkaṭīlambāsahadevīhrīberośīrāṇi dhārayet nāgadantī lakṣmaṇābṛhatīdvayamṛgorvāruśatāvarīsahadevyo vā" },
      { type: "verse", number: "43", sanskrit: "तिलतण्डुलमत्स्यमनशिशलाहरितालसम्पृक्तस्तिलपिष्टकृतशकुनिकैः करञ्जे बलिर्निष्कुटे स्नानम् मन्त्रश्च", text: "tilataṇḍulamatsyamanaśiśalāharitālasampṛktastilapiṣṭakṛtaśakunikaiḥ karañje balirniṣkuṭe snānam mantraśca" },
      { type: "verse", number: "44", sanskrit: "अन्तरिक्षचरा देवी सर्वालङ्कारभूषिता अयोमुखी तीक्ष्णतुण्डा शकुनी ते प्रसीदतु", text: "antarikṣacarā devī sarvālaṅkārabhūṣitā ayomukhī tīkṣṇatuṇḍā śakunī te prasīdatu" },
      { type: "verse", number: "45", sanskrit: "दुर्दर्शना महाकाया पिङ्गाक्षी भैरवस्वरा लम्बोदरी शङ्कुकर्णी शकुनी ते प्रसीदतु", text: "durdarśanā mahākāyā piṅgākṣī bhairavasvarā lambodarī śaṅkukarṇī śakunī te prasīdatu" },
      { type: "verse", number: "46", sanskrit: "पूतनायां हिङ्गुवचागिरिकदम्बकुष्ठैलाद्वयसुराह्वैः प्रदेहः कपित्थशिरीषन्यग्रोधबिल्वैरण्डबकुलधव वंशाग्निमन्थपत्रक्वाथः सर्वगन्धोदकयुक्तः परिषेको वरणकट्वङ्गास्फोतकपोतवङ्कापारिभद्रदैर्वा", text: "pūtanāyāṃ hiṅguvacāgirikadambakuṣṭhailādvayasurāhvaiḥ pradehaḥ kapitthaśirīṣanyagrodhabilvairaṇḍabakuladhava vaṃśāgnimanthapatrakvāthaḥ sarvagandhodakayuktaḥ pariṣeko varaṇakaṭvaṅgāsphotakapotavaṅkāpāribhadradairvā" },
      { type: "verse", number: "47", sanskrit: "कुष्ठसर्जरसवचागोलोमीवयस्थामनश्शिलालैस्तैलं साधितमभ्यङ्गः मधुरौषधैः साधितं सर्पिः पानम् एलाद्वयकुष्ठवचाहिङ्गुदेवदारुगिरिकदम्बकैर्धूपः बिम्बीगुञ्जाकाकादनीनद्रवारुणीचित्रपला धारयेत्", text: "kuṣṭhasarjarasavacāgolomīvayasthāmanaśśilālaistailaṃ sādhitamabhyaṅgaḥ madhurauṣadhaiḥ sādhitaṃ sarpiḥ pānam elādvayakuṣṭhavacāhiṅgudevadārugirikadambakairdhūpaḥ bimbīguñjākākādanīnadravāruṇīcitrapalā dhārayet" },
      { type: "verse", number: "48", sanskrit: "विचित्रमाल्यमत्स्योदनकृसरपललवान् बलिः सङ्करकूटे तद्वच्छरावसम्पुटस्थः शून्यग्रहे चतुर्दिशं प्रक्षेप्यः तत्र चोच्छिष्टेन स्रपनम् मन्त्रश्च", text: "vicitramālyamatsyodanakṛsarapalalavān baliḥ saṅkarakūṭe tadvaccharāvasampuṭasthaḥ śūnyagrahe caturdiśaṃ prakṣepyaḥ tatra cocchiṣṭena srapanam mantraśca" },
      { type: "verse", number: "49", sanskrit: "मलिनाम्बरसंवीता मलिना रूक्षमूर्धजा शून्यागाराश्रया देवी दारकं पातु पूतना", text: "malināmbarasaṃvītā malinā rūkṣamūrdhajā śūnyāgārāśrayā devī dārakaṃ pātu pūtanā" },
      { type: "verse", number: "50", sanskrit: "दुर्दर्शना महाकाया कराला मेघकालिका भिन्नागाराश्रया देवी दारकं पातु पूतना", text: "durdarśanā mahākāyā karālā meghakālikā bhinnāgārāśrayā devī dārakaṃ pātu pūtanā" },
      { type: "verse", number: "51", sanskrit: "शीतपूतनायां पूतनोक्तः प्रदेहो धारणीयानि च वरणकपित्थतुलसीपाशिकावंशीबिल्वपाटलीनन्दीभल्लातकपत्रनिर्यूहेण परिषेकः", text: "śītapūtanāyāṃ pūtanoktaḥ pradeho dhāraṇīyāni ca varaṇakapitthatulasīpāśikāvaṃśībilvapāṭalīnandībhallātakapatraniryūheṇa pariṣekaḥ" },
      { type: "verse", number: "52", sanskrit: "मुस्तामरदारुकुष्ठसर्पगन्धैर्गोबस्तमूत्रयुक्तं तैलं विपक्वमभ्यङ्गः काश्मर्यपृश्निपर्णीलोध्रमधुकैर्मधुरवर्गेण च समक्षीरं सर्पिः शृतं प्राश्यमानं शीतपूतनां छर्दिहिध्माकासश्वासांश्च शमयति", text: "mustāmaradārukuṣṭhasarpagandhairgobastamūtrayuktaṃ tailaṃ vipakvamabhyaṅgaḥ kāśmaryapṛśniparṇīlodhramadhukairmadhuravargeṇa ca samakṣīraṃ sarpiḥ śṛtaṃ prāśyamānaṃ śītapūtanāṃ chardihidhmākāsaśvāsāṃśca śamayati" },
      { type: "verse", number: "53", sanskrit: "सातिसारायां तु खदिरपलाशसर्जार्जुनरोहिणीत्वक्क्वाथेन तुल्यपयः सर्पिः गृध्रोलूकविड्बस्तगन्धाहिनिर्मोकनिम्बपत्रैर्धूपः जीर्णगोचर्मसर्षपभिक्षुसङ्घाटीसर्पकञ्चुकैर्वा", text: "sātisārāyāṃ tu khadirapalāśasarjārjunarohiṇītvakkvāthena tulyapayaḥ sarpiḥ gṛdhrolūkaviḍbastagandhāhinirmokanimbapatrairdhūpaḥ jīrṇagocarmasarṣapabhikṣusaṅghāṭīsarpakañcukairvā" },
      { type: "verse", number: "54", sanskrit: "मुद्गौदनप्रायो जलाशयसमीपे बलिस्तत्रैव च स्नानम् मन्त्रश्च", text: "mudgaudanaprāyo jalāśayasamīpe balistatraiva ca snānam mantraśca" },
      { type: "verse", number: "55", sanskrit: "मुद्गौदनाशना देवी सुराशोणितपायिनी जलाशयालयरता पातु त्वा शीतपूतना", text: "mudgaudanāśanā devī surāśoṇitapāyinī jalāśayālayaratā pātu tvā śītapūtanā" },
      { type: "verse", number: "56", sanskrit: "अन्धपूतनायां सर्वगन्धैः सशिरोवक्त्रस्य प्रदेहः वरुणास्फोतपारिभद्रकवृक्षादनीनागबलागैरिकशतावरीभिः परिषेकः हरितालमनश्शिलाकुष्ठसर्जरससुरासौवीरकसंस्कृतं तैलमभ्यङ्गः", text: "andhapūtanāyāṃ sarvagandhaiḥ saśirovaktrasya pradehaḥ varuṇāsphotapāribhadrakavṛkṣādanīnāgabalāgairikaśatāvarībhiḥ pariṣekaḥ haritālamanaśśilākuṣṭhasarjarasasurāsauvīrakasaṃskṛtaṃ tailamabhyaṅgaḥ" },
      { type: "verse", number: "57", sanskrit: "स्यन्दनस्योनाककाश्मर्यखदिरकुष्ठैर्मधुरवर्गेण च क्षीरिवृक्षकषाये सक्षीरं शृतं घृतं मधुयुक्तं चक्षुःकामोपसृष्टानां प्राशः छर्दिकासातीसारवतां तु तदेव पिप्पलीपिप्पलीमूलसालपर्णीबृहतीकल्कोपेतम्", text: "syandanasyonākakāśmaryakhadirakuṣṭhairmadhuravargeṇa ca kṣīrivṛkṣakaṣāye sakṣīraṃ śṛtaṃ ghṛtaṃ madhuyuktaṃ cakṣuḥkāmopasṛṣṭānāṃ prāśaḥ chardikāsātīsāravatāṃ tu tadeva pippalīpippalīmūlasālaparṇībṛhatīkalkopetam" },
      { type: "verse", number: "58", sanskrit: "रक्षोघ्ररुष्करसर्जरसमधुभिर्धूपः जीर्णाभिक्षुसङ्घाटीकृकवाकुपुरीषाहित्वक्केशचर्मभिर्वा", text: "rakṣoghraruṣkarasarjarasamadhubhirdhūpaḥ jīrṇābhikṣusaṅghāṭīkṛkavākupurīṣāhitvakkeśacarmabhirvā" },
      { type: "verse", number: "59", sanskrit: "अनन्ता कुक्कुटी मर्कटी बिम्बीर्धारयेत् तुम्बी चित्रफलामृगोर्वारुजालिनीकाकादनीर्वा", text: "anantā kukkuṭī markaṭī bimbīrdhārayet tumbī citraphalāmṛgorvārujālinīkākādanīrvā" },
      { type: "verse", number: "60", sanskrit: "पक्वाममांसशोणितैश्चतुष्पथे बलिर्गृहे स्नानम् मन्त्रश्च", text: "pakvāmamāṃsaśoṇitaiścatuṣpathe balirgṛhe snānam mantraśca" },
      { type: "verse", number: "61", sanskrit: "कराला पिङ्गला मुण्डा कषायाम्बरवासिनी देवी बालमिमं प्रीता पालयत्वन्धपूतना", text: "karālā piṅgalā muṇḍā kaṣāyāmbaravāsinī devī bālamimaṃ prītā pālayatvandhapūtanā" },
      { type: "verse", number: "62", sanskrit: "मुखमण्डितिकायां वारुण्या श्लक्ष्णपिष्टैः सर्वगन्धैर्लेपः बिल्वैरण्डकपित्थाग्निमन्थवंशीकुबेराक्षीपत्रक्वाथेन परिषेकस्तेषामेव च स्वरसेन मधुकवाजिगन्धागर्भमैकध्यं तैलं वसा च पक्वमभ्यङ्गः", text: "mukhamaṇḍitikāyāṃ vāruṇyā ślakṣṇapiṣṭaiḥ sarvagandhairlepaḥ bilvairaṇḍakapitthāgnimanthavaṃśīkuberākṣīpatrakvāthena pariṣekasteṣāmeva ca svarasena madhukavājigandhāgarbhamaikadhyaṃ tailaṃ vasā ca pakvamabhyaṅgaḥ" },
      { type: "verse", number: "63", sanskrit: "ह्रस्वपञ्चमूलमधुरवर्गसिद्धं घृतं समधुशर्करं प्राशः पाठाकेतकसूचीनिम्बफलपिप्पलीविडङ्गहरीतकीभस्मवचाचोरकचूर्णो वा मधुसर्पिर्भ्याम् ऋक्षरोममषीपाठामरिचपिप्पलीचूर्णो वा देवदारुभस्मयुक्तो मूर्वाव्योषमुस्तरास्नागिरिकदम्बकाश्वगन्धाचूर्णो वाशोकरोहिणीचूर्णो वा एभिरेव च विपक्वमाजं घृतं पयो वा पिबेत्", text: "hrasvapañcamūlamadhuravargasiddhaṃ ghṛtaṃ samadhuśarkaraṃ prāśaḥ pāṭhāketakasūcīnimbaphalapippalīviḍaṅgaharītakībhasmavacācorakacūrṇo vā madhusarpirbhyām ṛkṣaromamaṣīpāṭhāmaricapippalīcūrṇo vā devadārubhasmayukto mūrvāvyoṣamustarāsnāgirikadambakāśvagandhācūrṇo vāśokarohiṇīcūrṇo vā ebhireva ca vipakvamājaṃ ghṛtaṃ payo vā pibet" },
      { type: "verse", number: "64", sanskrit: "एभिरेव च योगैर्धूपोपदेहाभ्यङ्गनस्यतैलाक्षिपूरणपरिषेकान् कुर्यात् यवकुष्ठसर्जरसैर्धूपः सर्पचाषकीररल्लकजिह्वा धारयेत् मातुश्चास्य श्लेष्महरमौषधं पाने स्तनोद्वर्तने च युञ्ज्यात्", text: "ebhireva ca yogairdhūpopadehābhyaṅganasyatailākṣipūraṇapariṣekān kuryāt yavakuṣṭhasarjarasairdhūpaḥ sarpacāṣakīrarallakajihvā dhārayet mātuścāsya śleṣmaharamauṣadhaṃ pāne stanodvartane ca yuñjyāt" },
      { type: "verse", number: "65", sanskrit: "विविधगन्धधूपमाल्याञ्जनपारदमनश्शिलायुक्तो गोष्ठमध्ये बलिर्गवां मध्ये स्नानम् मन्त्रश्च", text: "vividhagandhadhūpamālyāñjanapāradamanaśśilāyukto goṣṭhamadhye balirgavāṃ madhye snānam mantraśca" },
      { type: "verse", number: "66", sanskrit: "अलङ्कृता रूपवती सुभगा कामरूपिणी गोष्ठमध्यालयरता पातु त्वा मुखमण्डिता", text: "alaṅkṛtā rūpavatī subhagā kāmarūpiṇī goṣṭhamadhyālayaratā pātu tvā mukhamaṇḍitā" },
      { type: "verse", number: "67", sanskrit: "रेवत्यां सर्वगन्धैः कुलत्थमाषचूर्णेन च प्रदेहः अश्वगन्धाजशृङ्गीसारिवाद्विपुनर्नवद्विसहाविदारीभिः परिषेकः", text: "revatyāṃ sarvagandhaiḥ kulatthamāṣacūrṇena ca pradehaḥ aśvagandhājaśṛṅgīsārivādvipunarnavadvisahāvidārībhiḥ pariṣekaḥ" },
      { type: "verse", number: "68", sanskrit: "कुष्ठसर्जरससांधितं तैलमभ्यङ्गः धवाश्वकर्णधातकीककुभतिन्दुकैर्जीवनीयैश्च पिष्टैर्घृतं शृतं प्राशः यवयवफलोलूकगृध्रशकृद्भिः सघृतैर्धूपः वरणारिष्टसिन्दुकान्वितश्चाविकमूत्रेण कण्डको लेपः", text: "kuṣṭhasarjarasasāṃdhitaṃ tailamabhyaṅgaḥ dhavāśvakarṇadhātakīkakubhatindukairjīvanīyaiśca piṣṭairghṛtaṃ śṛtaṃ prāśaḥ yavayavaphalolūkagṛdhraśakṛdbhiḥ saghṛtairdhūpaḥ varaṇāriṣṭasindukānvitaścāvikamūtreṇa kaṇḍako lepaḥ" },
      { type: "verse", number: "69", sanskrit: "शुक्लमाल्यविलेपनलाजौदनपायसैर्गोतीर्थे बलिः नदीसङ्गमे क्षीरिवृक्षसमीपे वा स्नपनम् मन्त्रश्च", text: "śuklamālyavilepanalājaudanapāyasairgotīrthe baliḥ nadīsaṅgame kṣīrivṛkṣasamīpe vā snapanam mantraśca" },
      { type: "verse", number: "70", sanskrit: "नानावस्त्रधरादेवी चित्रमाल्यानुलेपना चलत्कुण्डलिनी श्यामा रेवती ते प्रसीदतु", text: "nānāvastradharādevī citramālyānulepanā calatkuṇḍalinī śyāmā revatī te prasīdatu" },
      { type: "verse", number: "71", sanskrit: "शुष्करेवत्यां धूपवर्ज्यः स्कन्दग्रहोक्तो विधिः वचाश्वगन्धाहिङ्गुलाजसिद्धार्थकैरुद्वर्तनम् सर्षपतैलं वचासिद्धं नेत्रपूरणम्", text: "śuṣkarevatyāṃ dhūpavarjyaḥ skandagrahokto vidhiḥ vacāśvagandhāhiṅgulājasiddhārthakairudvartanam sarṣapatailaṃ vacāsiddhaṃ netrapūraṇam" },
      { type: "verse", number: "72", sanskrit: "काकगृध्रगर्दभशकृद्भिर्लेपः कुलीरकपालशल्यकशुक्तिमेषशृङ्गहयखरजाहकहस्तिनखनकुलरोमभिर्धूपः सर्वग्रहघ्नः", text: "kākagṛdhragardabhaśakṛdbhirlepaḥ kulīrakapālaśalyakaśuktimeṣaśṛṅgahayakharajāhakahastinakhanakularomabhirdhūpaḥ sarvagrahaghnaḥ" },
      { type: "verse", number: "73", sanskrit: "कुल्माषैर्मद्येन शुष्कमांसेन च शुष्कवृक्षे बलिः तत्रैव च स्नानम् मन्त्रश्च", text: "kulmāṣairmadyena śuṣkamāṃsena ca śuṣkavṛkṣe baliḥ tatraiva ca snānam mantraśca" },
      { type: "verse", number: "74", sanskrit: "उपासते या सततं देव्यो विविधभूषणाः लम्बा कराला विनता तथैव बहुपुत्रिका रेवती शुष्कनामा च सा ते देवी प्रसीदतु इति", text: "upāsate yā satataṃ devyo vividhabhūṣaṇāḥ lambā karālā vinatā tathaiva bahuputrikā revatī śuṣkanāmā ca sā te devī prasīdatu iti" },
      { type: "verse", number: "75", sanskrit: "भवति चात्र अनुबन्धान्यथाकृच्छ्रं ग्रहापायेप्युपद्रवान् बालामयनिषेधोक्तभेषजैः समुपाचरेत्", text: "bhavati cātra anubandhānyathākṛcchraṃ grahāpāyepyupadravān bālāmayaniṣedhoktabheṣajaiḥ samupācaret" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 7,
    lang: "sa",
    content: [
      { type: "heading", heading: "Наса крия — процедуры для носа" },
      { type: "text", text: "Глава 7 Уттара стханы — «Наса крия» — посвящена специализированному разделу: процедуры для носа. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो भूतविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bhūtavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अष्टादश भूताधिपतयः तद्यथा सुरासुरगन्धर्वोरगयक्षब्रह्मराक्षसराक्षसपिशाचप्रेतकूष्माण्डकाखोर्दमौकिरणवेतालपितरः ऋषिगुरुवृद्धसिद्धाश्च ते पुनः पृथक् कोटिपरिवाराः तेषामपि चापरिसङ्ख्येयः परिवार इत्यनन्तो भूतलोकः", text: "aṣṭādaśa bhūtādhipatayaḥ tadyathā surāsuragandharvoragayakṣabrahmarākṣasarākṣasapiśācapretakūṣmāṇḍakākhordamaukiraṇavetālapitaraḥ ṛṣiguruvṛddhasiddhāśca te punaḥ pṛthak koṭiparivārāḥ teṣāmapi cāparisaṅkhyeyaḥ parivāra ityananto bhūtalokaḥ" },
      { type: "verse", number: "3", sanskrit: "सर्वो ऽपि च प्रायेणाहारकामा निशार्धविचारिणो भयानका मांसासृग्वसाशिनः", text: "sarvo 'pi ca prāyeṇāhārakāmā niśārdhavicāriṇo bhayānakā māṃsāsṛgvasāśinaḥ" },
      { type: "verse", number: "4", sanskrit: "अपि च सुरासुरादिसंवाससंसर्गात्तच्छीलाचारकर्मतया च तत्संज्ञां लभन्ते", text: "api ca surāsurādisaṃvāsasaṃsargāttacchīlācārakarmatayā ca tatsaṃjñāṃ labhante" },
      { type: "verse", number: "5", sanskrit: "तेषां पुनरनुप्रवेशे कारणं सद्यः पूर्वकृतो वा विशेषेण प्रज्ञापराधः", text: "teṣāṃ punaranupraveśe kāraṇaṃ sadyaḥ pūrvakṛto vā viśeṣeṇa prajñāparādhaḥ" },
      { type: "verse", number: "6", sanskrit: "तेन हि कामक्रोधलोभमोहादिजनितेन प्रलुप्तधमभिन्नव्रताचारशौचो मलीमसः पूज्यानतिक्रामन्नात्मानमुपहन्ति", text: "tena hi kāmakrodhalobhamohādijanitena praluptadhamabhinnavratācāraśauco malīmasaḥ pūjyānatikrāmannātmānamupahanti" },
      { type: "verse", number: "7", sanskrit: "ततस्तमात्महनमवतारगवेषिणो देवादिग्रहा अप्यनुघ्नन्ति तद्वदुन्मादापस्मारोपप्लुतचित्तं तथा ज्वराद्यामयोपहतमपि विशेषतश्च व्रणिनः पूयासृक्स्नेहगन्धेन", text: "tatastamātmahanamavatāragaveṣiṇo devādigrahā apyanughnanti tadvadunmādāpasmāropaplutacittaṃ tathā jvarādyāmayopahatamapi viśeṣataśca vraṇinaḥ pūyāsṛksnehagandhena" },
      { type: "verse", number: "8", sanskrit: "एवंविधांस्तु पुरुषानेष्वाघातकालेष्वभिगच्छन्ति", text: "evaṃvidhāṃstu puruṣāneṣvāghātakāleṣvabhigacchanti" },
      { type: "verse", number: "9", sanskrit: "तद्यथा पापस्य कर्मणः समारम्भे पूर्वकृतस्य वा परिणामकाले एकस्य वा शून्यगृहनिवासे चतुष्पथाधिष्ठाने वा सन्ध्यावेलायामप्रयतभावे वा पक्षसन्धिषु वा मिथुनीभावे रजस्वलाभिगमने वा विगुणे वाध्यापनहोमबलिमङ्गलप्रयोगे नियमब्रह्मचर्यव्रतभङ्गे वा महाहवे वा देशपुरकुलविनाशे वा महाग्रहोपगमने वा स्त्रिया वा प्रजननकाले विविधभूताशुचिसंस्पर्शे वा वमनविरेचनरुधिरस्रावे वा अशुचेरप्रयतस्य वा चैत्यदेवायतनाभिगमने वा मांसमधुगुडतिलमद्योच्छिष्टे वा दिग्वाससि वा निशि नगरचतुष्पथोपवनश्मशानाभिगमने वा द्विजगुरुसुरयतिपूज्यव्यतिक्रमे वा", text: "tadyathā pāpasya karmaṇaḥ samārambhe pūrvakṛtasya vā pariṇāmakāle ekasya vā śūnyagṛhanivāse catuṣpathādhiṣṭhāne vā sandhyāvelāyāmaprayatabhāve vā pakṣasandhiṣu vā mithunībhāve rajasvalābhigamane vā viguṇe vādhyāpanahomabalimaṅgalaprayoge niyamabrahmacaryavratabhaṅge vā mahāhave vā deśapurakulavināśe vā mahāgrahopagamane vā striyā vā prajananakāle vividhabhūtāśucisaṃsparśe vā vamanavirecanarudhirasrāve vā aśuceraprayatasya vā caityadevāyatanābhigamane vā māṃsamadhuguḍatilamadyocchiṣṭe vā digvāsasi vā niśi nagaracatuṣpathopavanaśmaśānābhigamane vā dvijagurusurayatipūjyavyatikrame vā" },
      { type: "verse", number: "10", sanskrit: "तत्रावलोकयन्तो जनयन्ति मनोविकारं सुरासुरग्रहाः स्पृशन्तो गन्धर्वाः समाविशन्तो भुजगाः यक्षाश्चात्मगन्धमाघ्रापयन्तः राक्षसा वाहयन्तोधिरुह्य तथैव पिशाचाद्याः दर्शयन्तः पितरोभिशपन्त ऋषिगुरुवृद्धसिद्धाः", text: "tatrāvalokayanto janayanti manovikāraṃ surāsuragrahāḥ spṛśanto gandharvāḥ samāviśanto bhujagāḥ yakṣāścātmagandhamāghrāpayantaḥ rākṣasā vāhayantodhiruhya tathaiva piśācādyāḥ darśayantaḥ pitarobhiśapanta ṛṣiguruvṛddhasiddhāḥ" },
      { type: "verse", number: "11", sanskrit: "तत्र शीलवन्तं चोक्षाचारं शुक्लाम्बरधरं तपःस्वाध्यायपरं प्रायः शुक्लप्रतिपदित्रयोदश्यां चतुर्दश्यां पौर्णमास्यां वा देवा गृह्णन्ति क्रोधनं कदर्यमात्मसम्भाविनं कुलरूपगर्वितं कृष्णद्वादश्यां कृष्णत्रयोदश्यां सन्ध्ययोश्चासुराः प्रियनृत्तगीतवादित्रगन्धमाल्याम्बरं परदाररतं चोक्षाचारं प्रायश्चतुर्थ्यामष्टभ्यां द्वादश्यां चतुर्दश्यां च गन्धर्वाः स्वप्नशीलं चपलमनिमित्रक्रोधनमर्थसिद्धं ब्राह्मणं प्रायः पञ्चभ्यां सन्ध्ययोर्मध्याह्ने च नागाः सत्वबलरूपगन्धर्वधनशौर्ययुक्तं माल्यानुलेपनहास्यप्रियमतिव्याकरणं प्रायः शुक्लसप्तम्यामेकादश्यां च यक्षाः", text: "tatra śīlavantaṃ cokṣācāraṃ śuklāmbaradharaṃ tapaḥsvādhyāyaparaṃ prāyaḥ śuklapratipaditrayodaśyāṃ caturdaśyāṃ paurṇamāsyāṃ vā devā gṛhṇanti krodhanaṃ kadaryamātmasambhāvinaṃ kularūpagarvitaṃ kṛṣṇadvādaśyāṃ kṛṣṇatrayodaśyāṃ sandhyayoścāsurāḥ priyanṛttagītavāditragandhamālyāmbaraṃ paradārarataṃ cokṣācāraṃ prāyaścaturthyāmaṣṭabhyāṃ dvādaśyāṃ caturdaśyāṃ ca gandharvāḥ svapnaśīlaṃ capalamanimitrakrodhanamarthasiddhaṃ brāhmaṇaṃ prāyaḥ pañcabhyāṃ sandhyayormadhyāhne ca nāgāḥ satvabalarūpagandharvadhanaśauryayuktaṃ mālyānulepanahāsyapriyamativyākaraṇaṃ prāyaḥ śuklasaptamyāmekādaśyāṃ ca yakṣāḥ" },
      { type: "verse", number: "12", sanskrit: "स्वाध्यायतपोव्रतचर्यादेवयतिगुरुपूजारतं भ्रष्टशौचं वा ब्राह्मणमब्राह्मणं वा ब्रह्मवादिनं शूरं मानिनं देवागारसलिलक्रीडनप्रियं च स्खलितब्रह्मचर्यं प्रायः शुक्लपञ्चम्यामष्टम्यां पूर्णचन्द्रदर्शने सन्ध्यासु च ब्रह्मराक्षसाः", text: "svādhyāyatapovratacaryādevayatigurupūjārataṃ bhraṣṭaśaucaṃ vā brāhmaṇamabrāhmaṇaṃ vā brahmavādinaṃ śūraṃ māninaṃ devāgārasalilakrīḍanapriyaṃ ca skhalitabrahmacaryaṃ prāyaḥ śuklapañcamyāmaṣṭamyāṃ pūrṇacandradarśane sandhyāsu ca brahmarākṣasāḥ" },
      { type: "verse", number: "13", sanskrit: "हीनसत्वं पिशुनं स्तेनं लुब्धं शठं प्रायो द्वितीयातृतीयाष्टमीषु राक्षसपिशाचादयः कलिपानप्रियमसूयावन्तं परुषभाषिणं बह्वाशिनं च कृष्णनवमीद्वादश्योर्निशि च राक्षसाः", text: "hīnasatvaṃ piśunaṃ stenaṃ lubdhaṃ śaṭhaṃ prāyo dvitīyātṛtīyāṣṭamīṣu rākṣasapiśācādayaḥ kalipānapriyamasūyāvantaṃ paruṣabhāṣiṇaṃ bahvāśinaṃ ca kṛṣṇanavamīdvādaśyorniśi ca rākṣasāḥ" },
      { type: "verse", number: "14", sanskrit: "आत्मश्लाघिनं कूटसाक्ष्यप्रदं परोपतापिनं च चतुर्दश्यां पिशाचादयः", text: "ātmaślāghinaṃ kūṭasākṣyapradaṃ paropatāpinaṃ ca caturdaśyāṃ piśācādayaḥ" },
      { type: "verse", number: "15", sanskrit: "मातापितृगुरुवृद्धसिद्धाचार्योपसेविनं प्रायो दशम्याममावास्यां च पितरः तद्विधमेव च प्रायः षष्ठ्यां नवम्यां च गुरुवृद्धसिद्धाः तथैव च स्नानशुचिविविक्तसेविनं धर्मशास्त्रश्रुतिकाव्यकुशलमृषयः", text: "mātāpitṛguruvṛddhasiddhācāryopasevinaṃ prāyo daśamyāmamāvāsyāṃ ca pitaraḥ tadvidhameva ca prāyaḥ ṣaṣṭhyāṃ navamyāṃ ca guruvṛddhasiddhāḥ tathaiva ca snānaśuciviviktasevinaṃ dharmaśāstraśrutikāvyakuśalamṛṣayaḥ" },
      { type: "verse", number: "16", sanskrit: "तेषां तु ग्रहीष्यतां पूर्वरूपाणि भवन्ति तद्यथा देवगोब्राह्मणतपस्विनां हिंसारुचित्वं नृशसाभिप्रायता कोपनत्वमरतिरोजोवर्णच्छायाबलवपुषां चोपतप्तिः स्वप्ने देवादिभिर्भत्सनं प्रवर्तनं च", text: "teṣāṃ tu grahīṣyatāṃ pūrvarūpāṇi bhavanti tadyathā devagobrāhmaṇatapasvināṃ hiṃsārucitvaṃ nṛśasābhiprāyatā kopanatvamaratirojovarṇacchāyābalavapuṣāṃ copataptiḥ svapne devādibhirbhatsanaṃ pravartanaṃ ca" },
      { type: "verse", number: "17", sanskrit: "तत्र सौम्यदृष्टिं गम्भीरमप्रधृष्यमकोपनं शुचिमनिद्रं भोजनानभिलाषिणमल्पस्वेदमूत्रपुरीषवाचं संस्कृतवादिनं देवद्विजगुरुभक्तं शुक्लमाल्याम्बरसरित्पुलिनशैलोच्चभवनदधिक्षीरसुरभिप्रियं चिरादक्षिणी निमीलयन्तं वरप्रदातारं शुभगन्धं वर्चस्विनं फुल्लपद्मोपममुखं देवग्रहेण गृहीतं विद्यात्", text: "tatra saumyadṛṣṭiṃ gambhīramapradhṛṣyamakopanaṃ śucimanidraṃ bhojanānabhilāṣiṇamalpasvedamūtrapurīṣavācaṃ saṃskṛtavādinaṃ devadvijagurubhaktaṃ śuklamālyāmbarasaritpulinaśailoccabhavanadadhikṣīrasurabhipriyaṃ cirādakṣiṇī nimīlayantaṃ varapradātāraṃ śubhagandhaṃ varcasvinaṃ phullapadmopamamukhaṃ devagraheṇa gṛhītaṃ vidyāt" },
      { type: "verse", number: "18", sanskrit: "तत्रापि गोवृषमिव नदन्तं दीप्तमुखनयनमादीप्तेन स्वरेण सर्वमाभाषमाणमीश्वरेण मेधस्तनितविद्युद्वृष्टीर्वाचा विसृजन्तमिन्द्रेण धनानि वाचा प्रयच्छन्तमाच्छिन्दन्तं च धनदेन सुरासवसमगन्धं काष्ठतृणरज्ज्वादि सर्वं पाशमभिमन्यमानं वरुणेन", text: "tatrāpi govṛṣamiva nadantaṃ dīptamukhanayanamādīptena svareṇa sarvamābhāṣamāṇamīśvareṇa medhastanitavidyudvṛṣṭīrvācā visṛjantamindreṇa dhanāni vācā prayacchantamācchindantaṃ ca dhanadena surāsavasamagandhaṃ kāṣṭhatṛṇarajjvādi sarvaṃ pāśamabhimanyamānaṃ varuṇena" },
      { type: "verse", number: "19", sanskrit: "जिह्मदृष्टिं दुष्टात्मानं क्रोधनमतृप्तं सस्वेदगात्रं देवब्राह्मणगुरुद्वेषिणं निर्भयमभिमानिनं शूरं व्यवसायिनं रुद्रो ऽहमिन्द्रोहमुपेन्द्रो ऽहं स्कन्दो ऽहं विशाखो ऽहमित्यादि भाषमाणं विकृतवाचमसकृद्धसन्तं सुरामिषरुचिं दन्तैर्नखैश्च परान् हिंसन्तमसुरेण", text: "jihmadṛṣṭiṃ duṣṭātmānaṃ krodhanamatṛptaṃ sasvedagātraṃ devabrāhmaṇagurudveṣiṇaṃ nirbhayamabhimāninaṃ śūraṃ vyavasāyinaṃ rudro 'hamindrohamupendro 'haṃ skando 'haṃ viśākho 'hamityādi bhāṣamāṇaṃ vikṛtavācamasakṛddhasantaṃ surāmiṣaruciṃ dantairnakhaiśca parān hiṃsantamasureṇa" },
      { type: "verse", number: "20", sanskrit: "स्वाचारं हृष्टात्मानं शुभगन्धमल्पव्यवहारं नृत्यन्तं गायन्तं मुखवाद्यानि कुर्वन्तं प्रियोद्यानपुलिनरक्तवस्त्रस्नानमाल्यानुलेपनधूपान्नपानहासलीलाशृङ्गारकथागान्धर्वं गन्धर्वेण तत्रापि शिरो धुनानं कलहं कुर्वन्तं संरम्भेण जागरूकं पठन्तं हसन्तं हसनेन", text: "svācāraṃ hṛṣṭātmānaṃ śubhagandhamalpavyavahāraṃ nṛtyantaṃ gāyantaṃ mukhavādyāni kurvantaṃ priyodyānapulinaraktavastrasnānamālyānulepanadhūpānnapānahāsalīlāśṛṅgārakathāgāndharvaṃ gandharveṇa tatrāpi śiro dhunānaṃ kalahaṃ kurvantaṃ saṃrambheṇa jāgarūkaṃ paṭhantaṃ hasantaṃ hasanena" },
      { type: "verse", number: "21", sanskrit: "क्रोधनमनिशं विश्वसन्तं भ्रमन्तमातपत्रात् त्रस्यन्तं रक्ताक्षं स्तब्धदृष्टिं जिह्वां लोलयन्तं सृक्विण्यौ लिहानमधोमुखशायिनं चलं वक्रगामिनं बिलमवलोक्य सर्पवदूर्ध्वं प्रसरन्तं जलौघघनदुन्दुभिस्वनैर्हृष्यन्तं क्षीरघृतगुडमधुस्नानमाल्यप्रियं गात्राणि कम्पयन्तं दन्तैः खादन्तं जले ऽवतीर्णमुत्तरणमनिच्छन्तमुरगेण", text: "krodhanamaniśaṃ viśvasantaṃ bhramantamātapatrāt trasyantaṃ raktākṣaṃ stabdhadṛṣṭiṃ jihvāṃ lolayantaṃ sṛkviṇyau lihānamadhomukhaśāyinaṃ calaṃ vakragāminaṃ bilamavalokya sarpavadūrdhvaṃ prasarantaṃ jalaughaghanadundubhisvanairhṛṣyantaṃ kṣīraghṛtaguḍamadhusnānamālyapriyaṃ gātrāṇi kampayantaṃ dantaiḥ khādantaṃ jale 'vatīrṇamuttaraṇamanicchantamurageṇa" },
      { type: "verse", number: "22", sanskrit: "असकृत् स्वप्नरोदनहासनृत्यगीतपाठकथान्नपानस्नानमाल्यधूपगन्धरक्तवस्त्ररतिं रक्तत्रस्तविप्लुताक्षं द्रुतं सगर्वं मत्तमिव गच्छन्तं वस्त्रान्तमुत्कर्षयन्तं चलिताग्रहस्तं बहुभाषिणं स्त्रीलोलुपं मद्यामिषप्रियं सन्नह्य शस्त्रं मृगयमाणमतिबलमव्यथं हृष्टं तुष्टमल्परोषं किं कस्मै ददामीति वादिनं शुभगन्धं वर्चस्विनं द्विजातिवैद्यपरिभाविनं रहस्यभाषिणं यक्षेण", text: "asakṛt svapnarodanahāsanṛtyagītapāṭhakathānnapānasnānamālyadhūpagandharaktavastraratiṃ raktatrastaviplutākṣaṃ drutaṃ sagarvaṃ mattamiva gacchantaṃ vastrāntamutkarṣayantaṃ calitāgrahastaṃ bahubhāṣiṇaṃ strīlolupaṃ madyāmiṣapriyaṃ sannahya śastraṃ mṛgayamāṇamatibalamavyathaṃ hṛṣṭaṃ tuṣṭamalparoṣaṃ kiṃ kasmai dadāmīti vādinaṃ śubhagandhaṃ varcasvinaṃ dvijātivaidyaparibhāvinaṃ rahasyabhāṣiṇaṃ yakṣeṇa" },
      { type: "verse", number: "23", sanskrit: "तत्रापि हृषितरोमाणमूर्ध्वेक्षणं प्रहृष्टनयनं चण्डं परुषं महानिनादं मणिवरेण रहोहसितनृत्यगीतान्याचरन्तमाकीर्णे मौनमासेवमानं विकटेन", text: "tatrāpi hṛṣitaromāṇamūrdhvekṣaṇaṃ prahṛṣṭanayanaṃ caṇḍaṃ paruṣaṃ mahāninādaṃ maṇivareṇa rahohasitanṛtyagītānyācarantamākīrṇe maunamāsevamānaṃ vikaṭena" },
      { type: "verse", number: "24", sanskrit: "हासनृत्तप्रियमाक्रोशिनं प्रधाविनं देवद्विजभिषग्द्वेषिणं मन्त्रवेदशास्त्राभिधायिनं काष्ठशस्त्रादिभिश्चात्मानमाघ्नन्तं छिद्रप्रहारिणं वैद्यरन्ध्रान्वेषिणं भोःशब्दवादिनं परुषं रौद्रचेष्टं शीघ्रगामिनं ब्रह्मराक्षसेन तत्रापि विकृतस्वरं भाषयन्तमुत्रासयन्तं ब्रह्मवादिनं संस्कृतभाषिणं बहुशस्तोयं याचन्तं यज्ञसेनेन", text: "hāsanṛttapriyamākrośinaṃ pradhāvinaṃ devadvijabhiṣagdveṣiṇaṃ mantravedaśāstrābhidhāyinaṃ kāṣṭhaśastrādibhiścātmānamāghnantaṃ chidraprahāriṇaṃ vaidyarandhrānveṣiṇaṃ bhoḥśabdavādinaṃ paruṣaṃ raudraceṣṭaṃ śīghragāminaṃ brahmarākṣasena tatrāpi vikṛtasvaraṃ bhāṣayantamutrāsayantaṃ brahmavādinaṃ saṃskṛtabhāṣiṇaṃ bahuśastoyaṃ yācantaṃ yajñasenena" },
      { type: "verse", number: "25", sanskrit: "सक्रोधदृष्टिं भ्रुकुटिमुद्वहन्तं भैरवास्यं त्वरितमभिधावन्तं रुवन्तं ससंभ्रमं प्रहरन्तं नष्टनिद्रं निशाविचारिणमन्नद्वेषिणमनाहारमप्यतिबलिनमन्नकाले हसन्तं निर्लज्जं शूरं रोषणमप्रियवादिनमशुचिं स्रीमद्यमांसरक्तमाल्यप्रियं रक्तमामिषं वा दृष्ट्वोष्ठौ परिलिहन्तं दीनं शङ्कितं धावन्तमकस्माद्रुदन्तं हसन्तं गायन्तं नृत्यन्तं निरर्थकं परिभाषमाणं राक्षसेन तत्रापि परुषच्छविं भूमिं ताडयन्तमकस्माद्रुदन्तं विशाखेन भिन्नगद्गदकण्ठमङ्गानि भञ्जयन्तं जिह्वां परिलिहानमक्षमालया जपमानं शौचमभीक्ष्णं कुर्वाणं सङ्गमेन मेघविद्युदुदयायासते क्रुध्यन्तं जलवृष्टिं समन्तान्मन्यमानं शकटनिष्पीडिनं विद्युन्मालिना आममांसपललमूलकापूपपरमान्नयाचिनं रूक्षच्छविं विरूपाक्षेण", text: "sakrodhadṛṣṭiṃ bhrukuṭimudvahantaṃ bhairavāsyaṃ tvaritamabhidhāvantaṃ ruvantaṃ sasaṃbhramaṃ praharantaṃ naṣṭanidraṃ niśāvicāriṇamannadveṣiṇamanāhāramapyatibalinamannakāle hasantaṃ nirlajjaṃ śūraṃ roṣaṇamapriyavādinamaśuciṃ srīmadyamāṃsaraktamālyapriyaṃ raktamāmiṣaṃ vā dṛṣṭvoṣṭhau parilihantaṃ dīnaṃ śaṅkitaṃ dhāvantamakasmādrudantaṃ hasantaṃ gāyantaṃ nṛtyantaṃ nirarthakaṃ paribhāṣamāṇaṃ rākṣasena tatrāpi paruṣacchaviṃ bhūmiṃ tāḍayantamakasmādrudantaṃ viśākhena bhinnagadgadakaṇṭhamaṅgāni bhañjayantaṃ jihvāṃ parilihānamakṣamālayā japamānaṃ śaucamabhīkṣṇaṃ kurvāṇaṃ saṅgamena meghavidyududayāyāsate krudhyantaṃ jalavṛṣṭiṃ samantānmanyamānaṃ śakaṭaniṣpīḍinaṃ vidyunmālinā āmamāṃsapalalamūlakāpūpaparamānnayācinaṃ rūkṣacchaviṃ virūpākṣeṇa" },
      { type: "verse", number: "26", sanskrit: "अस्वस्थचित्तं नैकत्र तिष्ठन्तं परिधाविनं दयितनृत्यगीतहासोच्छिष्टमद्यमांसशून्यनिवासरतिं पुरस्तादभिघ्नन्तं निर्भत्सनाद्दीनशङ्कितवदनं नखैरात्मवपुषि लिखन्तं नष्टस्मृतिं बद्धाबद्धभाषिणमकस्माद्रुदन्तं दुःखान्यावेदयमानमुध्वस्तरूक्षदेहस्वरं दुर्गन्धमशुचिं नग्नं मलिनं रथ्याचैलतृणाभरणं सङ्करकूटकाष्ठाश्वारोहिणं लोलं बह्वाशिनं पिशाचेन तत्रापि भोजनं दृष्ट्वा हसन्तं विस्वरं क्रोशन्तं नित्यभीतं कश्मलेन सर्वगात्राणि स्पन्दयन्तं मुहुर्मुहुर्धावन्तं भीषयमाणं कुशेन वैद्यं दृष्ट्वा कुप्यन्तं भ्रमद्भोजिनं बह्वाशिनं भस्मगुण्ठनशयनं स्त्रियो मार्गे रुन्धानं मूत्रपुरीषविमर्दिनं निस्तेजसा प्रेताकृतिचेष्टागन्धं तृणच्छेदिनं भीतमाहारद्वेषिणं प्रेतेन", text: "asvasthacittaṃ naikatra tiṣṭhantaṃ paridhāvinaṃ dayitanṛtyagītahāsocchiṣṭamadyamāṃsaśūnyanivāsaratiṃ purastādabhighnantaṃ nirbhatsanāddīnaśaṅkitavadanaṃ nakhairātmavapuṣi likhantaṃ naṣṭasmṛtiṃ baddhābaddhabhāṣiṇamakasmādrudantaṃ duḥkhānyāvedayamānamudhvastarūkṣadehasvaraṃ durgandhamaśuciṃ nagnaṃ malinaṃ rathyācailatṛṇābharaṇaṃ saṅkarakūṭakāṣṭhāśvārohiṇaṃ lolaṃ bahvāśinaṃ piśācena tatrāpi bhojanaṃ dṛṣṭvā hasantaṃ visvaraṃ krośantaṃ nityabhītaṃ kaśmalena sarvagātrāṇi spandayantaṃ muhurmuhurdhāvantaṃ bhīṣayamāṇaṃ kuśena vaidyaṃ dṛṣṭvā kupyantaṃ bhramadbhojinaṃ bahvāśinaṃ bhasmaguṇṭhanaśayanaṃ striyo mārge rundhānaṃ mūtrapurīṣavimardinaṃ nistejasā pretākṛticeṣṭāgandhaṃ tṛṇacchedinaṃ bhītamāhāradveṣiṇaṃ pretena" },
      { type: "verse", number: "27", sanskrit: "बहुप्रलापमुग्रवाक्यं विलम्बितगतिं कृष्णवदनं शूनप्रलम्बवृषणं कूष्माण्डेन", text: "bahupralāpamugravākyaṃ vilambitagatiṃ kṛṣṇavadanaṃ śūnapralambavṛṣaṇaṃ kūṣmāṇḍena" },
      { type: "verse", number: "28", sanskrit: "नग्नं धावन्तमकस्मादश्मकाष्ठादि गृहीत्वा भ्रमन्तं तृणचीरमाल्यनिवसनमुत्रस्तदृष्टिं परुषाभिधायिनं श्मशानशून्यैकवृक्षरथ्यानिषेविणं तिलान्नमद्यामिषसक्तदृष्टिं काखोर्देन", text: "nagnaṃ dhāvantamakasmādaśmakāṣṭhādi gṛhītvā bhramantaṃ tṛṇacīramālyanivasanamutrastadṛṣṭiṃ paruṣābhidhāyinaṃ śmaśānaśūnyaikavṛkṣarathyāniṣeviṇaṃ tilānnamadyāmiṣasaktadṛṣṭiṃ kākhordena" },
      { type: "verse", number: "29", sanskrit: "उग्रवादिनं रक्तत्रस्तनेत्रमन्नाभिलाषिणमुदकं प्रार्थयमानं मौकिरणेन", text: "ugravādinaṃ raktatrastanetramannābhilāṣiṇamudakaṃ prārthayamānaṃ maukiraṇena" },
      { type: "verse", number: "30", sanskrit: "सत्यवादिनं परिवेपिनं धूपगन्धमाल्यरतिमतिनिद्रालुं वेतालेन", text: "satyavādinaṃ parivepinaṃ dhūpagandhamālyaratimatinidrāluṃ vetālena" },
      { type: "verse", number: "31", sanskrit: "अप्रसन्नदृष्टिं चलन्नेत्रपक्ष्माणं शङ्कितेक्षणं दीनवदनं संशुष्कतालुं निद्रालुं प्रतिहतवाचमपसव्यवस्त्रमल्पाग्निमरोचकिनं तिलगुडपायसमांसरुचिं च पितृग्रहेण", text: "aprasannadṛṣṭiṃ calannetrapakṣmāṇaṃ śaṅkitekṣaṇaṃ dīnavadanaṃ saṃśuṣkatāluṃ nidrāluṃ pratihatavācamapasavyavastramalpāgnimarocakinaṃ tilaguḍapāyasamāṃsaruciṃ ca pitṛgraheṇa" },
      { type: "verse", number: "32", sanskrit: "ऋषिगुरुवृद्धसिद्धानामाभिशापानुध्यानानुरूपविहारव्याहाराहारं तद्ग्रहेण गृहीतं विद्यादिति भवति चात्र", text: "ṛṣiguruvṛddhasiddhānāmābhiśāpānudhyānānurūpavihāravyāhārāhāraṃ tadgraheṇa gṛhītaṃ vidyāditi bhavati cātra" },
      { type: "verse", number: "33", sanskrit: "लक्षयेत् ज्ञानविज्ञानवाक्चेष्टाबलपौरुषम् पुरुषे ऽपौरुषं यत्र तत्र भूतग्रहं वदेत्", text: "lakṣayet jñānavijñānavākceṣṭābalapauruṣam puruṣe 'pauruṣaṃ yatra tatra bhūtagrahaṃ vadet" },
      { type: "verse", number: "34", sanskrit: "कुमारवृन्दानुगतं नग्नमुद्धतमूर्धजम् अस्वस्थमनसं दैर्घ्यकालिकं सग्रहं त्यजेत्", text: "kumāravṛndānugataṃ nagnamuddhatamūrdhajam asvasthamanasaṃ dairghyakālikaṃ sagrahaṃ tyajet" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 8,
    lang: "sa",
    content: [
      { type: "heading", heading: "Широ рога — болезни головы — обзор" },
      { type: "text", text: "Глава 8 Уттара стханы — «Широ рога» — посвящена специализированному разделу: болезни головы — обзор. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो भूतप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bhūtapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "भूतं जयेदहिंसेच्छुं जपहोमबलिव्रतैः तपःशीलसमाधानज्ञानदानदयादिभिः", text: "bhūtaṃ jayedahiṃsecchuṃ japahomabalivrataiḥ tapaḥśīlasamādhānajñānadānadayādibhiḥ" },
      { type: "verse", number: "3", sanskrit: "हिङ्गुव्योषालनैपालीलशुनार्कजटाजटाः अजलोमीसगोलोमी भूतकेशी वचा लता", text: "hiṅguvyoṣālanaipālīlaśunārkajaṭājaṭāḥ ajalomīsagolomī bhūtakeśī vacā latā" },
      { type: "verse", number: "4", sanskrit: "कुक्कुटीसर्पगन्धाख्यातिलाः काणविकाणिके वज्रप्रोक्ता वयस्था च शृङ्गी मोहनवल्यपि", text: "kukkuṭīsarpagandhākhyātilāḥ kāṇavikāṇike vajraproktā vayasthā ca śṛṅgī mohanavalyapi" },
      { type: "verse", number: "5", sanskrit: "स्रोतोजाञ्जनरक्षोघ्नं रक्षोघ्नं चान्यदौषधम् खराश्वश्वाविडुष्ट्रर्क्षगोधानकुलशल्यकात्", text: "srotojāñjanarakṣoghnaṃ rakṣoghnaṃ cānyadauṣadham kharāśvaśvāviḍuṣṭrarkṣagodhānakulaśalyakāt" },
      { type: "verse", number: "6", sanskrit: "द्वीपिमार्जारगोसिंहव्याघ्रसामुद्रसत्वतः चर्मपित्तद्विजनखा वर्गे ऽस्मिन् साधयेत् घृतम्", text: "dvīpimārjāragosiṃhavyāghrasāmudrasatvataḥ carmapittadvijanakhā varge 'smin sādhayet ghṛtam" },
      { type: "verse", number: "7", sanskrit: "पुराणमथवा तैलं नवं तत्पाननस्ययोः अभ्यङ्गे च प्रयोक्तव्यमेषां चूर्णं च धूपने", text: "purāṇamathavā tailaṃ navaṃ tatpānanasyayoḥ abhyaṅge ca prayoktavyameṣāṃ cūrṇaṃ ca dhūpane" },
      { type: "verse", number: "8", sanskrit: "एभिश्च गुलिकां युञ्ज्यादञ्जने सावपीडने प्रलेपे कल्कमेतेषां क्वाथं च परिषेचने प्रयोगो ऽयं ग्रहोन्मादान् सापस्मारान् शमं नयेत्", text: "ebhiśca gulikāṃ yuñjyādañjane sāvapīḍane pralepe kalkameteṣāṃ kvāthaṃ ca pariṣecane prayogo 'yaṃ grahonmādān sāpasmārān śamaṃ nayet" },
      { type: "verse", number: "9", sanskrit: "गजाह्वापिप्पलीमूलव्योषामलकसर्षपान् गोधानकुलमार्जारशशपित्तप्रपेषितान् नावनाभ्यङ्गसेकेषु विदधीत ग्रहापहान्", text: "gajāhvāpippalīmūlavyoṣāmalakasarṣapān godhānakulamārjāraśaśapittaprapeṣitān nāvanābhyaṅgasekeṣu vidadhīta grahāpahān" },
      { type: "verse", number: "10", sanskrit: "अश्वश्वाश्वतरोलूककङ्कगृध्नशृगालजा विट्खरोष्ट्रवराहाच्च तया तैलं विपाचितम् पिष्टया बस्तमूत्रेण नावनादिषु पूजितम्", text: "aśvaśvāśvatarolūkakaṅkagṛdhnaśṛgālajā viṭkharoṣṭravarāhācca tayā tailaṃ vipācitam piṣṭayā bastamūtreṇa nāvanādiṣu pūjitam" },
      { type: "verse", number: "11", sanskrit: "शिरीषपुष्पं लशुनं शुण्ठीं सिद्धार्थकं वचाम् मञ्जिष्ठां द्वे निशे कृष्णां बस्तमूत्रेण पेषयेत् छायाशुष्का कृता वर्तिः मत्स्यपित्तद्रुताञ्जनम्", text: "śirīṣapuṣpaṃ laśunaṃ śuṇṭhīṃ siddhārthakaṃ vacām mañjiṣṭhāṃ dve niśe kṛṣṇāṃ bastamūtreṇa peṣayet chāyāśuṣkā kṛtā vartiḥ matsyapittadrutāñjanam" },
      { type: "verse", number: "12", sanskrit: "नक्तमालफलं व्योषं बिल्वस्योनाकयोर्जटा हरिद्रे च कृता वर्तिः पूर्ववन्नयनाञ्जनम् वयस्था हिङ्गु कटुका षड्ग्रन्था सैन्धवं तथा", text: "naktamālaphalaṃ vyoṣaṃ bilvasyonākayorjaṭā haridre ca kṛtā vartiḥ pūrvavannayanāñjanam vayasthā hiṅgu kaṭukā ṣaḍgranthā saindhavaṃ tathā" },
      { type: "verse", number: "13", sanskrit: "सिद्धार्थकवचाहिङ्गुप्रियङ्गुरजनीद्वयम् मञ्जिष्ठाश्वेतकटभीवराश्वेताद्रिकर्णिकाः", text: "siddhārthakavacāhiṅgupriyaṅgurajanīdvayam mañjiṣṭhāśvetakaṭabhīvarāśvetādrikarṇikāḥ" },
      { type: "verse", number: "14", sanskrit: "निम्बस्य पत्रं बजिं तु नक्तमालशिरीषयोः सुराह्वं त्र्यूषणं सर्पिर्गोमूत्रे तैश्चतुर्गुणे", text: "nimbasya patraṃ bajiṃ tu naktamālaśirīṣayoḥ surāhvaṃ tryūṣaṇaṃ sarpirgomūtre taiścaturguṇe" },
      { type: "verse", number: "15", sanskrit: "सिद्धं सिद्धार्थकं नाम पाने नस्ये च योजितम् ग्रहान् सर्वान् निहन्त्याशु विशेषादासुरान् ग्रहान्", text: "siddhaṃ siddhārthakaṃ nāma pāne nasye ca yojitam grahān sarvān nihantyāśu viśeṣādāsurān grahān" },
      { type: "verse", number: "16", sanskrit: "कृत्यालक्ष्मीविषोन्मादज्वरापस्मारपाप्मजित् एभिरेवौषधैर्बस्तवारिणा कल्पितो ऽगदः", text: "kṛtyālakṣmīviṣonmādajvarāpasmārapāpmajit ebhirevauṣadhairbastavāriṇā kalpito 'gadaḥ" },
      { type: "verse", number: "17", sanskrit: "पाननस्याञ्जनालेपस्नानोद्घर्षणयोजितः गुणैः पूर्ववदुद्दिष्टो राजद्वारे च सिद्धिकृत्", text: "pānanasyāñjanālepasnānodgharṣaṇayojitaḥ guṇaiḥ pūrvavaduddiṣṭo rājadvāre ca siddhikṛt" },
      { type: "verse", number: "18", sanskrit: "सिद्धार्थकव्योषवचाश्वगन्धा निशाद्वयं हिङ्गुपलाण्डुकन्दम् बीजं करञ्जात् कुसुमं शिरीषात् फलं च वल्कं च कपित्थवृक्षात्", text: "siddhārthakavyoṣavacāśvagandhā niśādvayaṃ hiṅgupalāṇḍukandam bījaṃ karañjāt kusumaṃ śirīṣāt phalaṃ ca valkaṃ ca kapitthavṛkṣāt" },
      { type: "verse", number: "19", sanskrit: "समाणिमन्थं सनतं सकुष्ठं स्योनाकमूलं किणिही सिता च बस्तस्य मूत्रेण सुभावितं तत् पित्तेन गव्येन गुडान् विदध्यात्", text: "samāṇimanthaṃ sanataṃ sakuṣṭhaṃ syonākamūlaṃ kiṇihī sitā ca bastasya mūtreṇa subhāvitaṃ tat pittena gavyena guḍān vidadhyāt" },
      { type: "verse", number: "20", sanskrit: "दुष्टग्रहोन्मादतमोनिशान्धानुद्बन्धकान् वारिनिमग्रदेहान् दिग्धाहतान् दर्पितसर्पदष्टां स्तेसाधयन्त्यञ्जननस्यलेपैः", text: "duṣṭagrahonmādatamoniśāndhānudbandhakān vārinimagradehān digdhāhatān darpitasarpadaṣṭāṃ stesādhayantyañjananasyalepaiḥ" },
      { type: "verse", number: "21", sanskrit: "कार्पासास्थिमयूरपत्रबृहतीनिर्माल्यपिण्डीतक त्वग्वांशीबृषदंशविट् तुषवचाकेशाहिनिर्मोचनैः नागेन्द्रद्विजशृङ्गहिङ्गुमरिचैस्तुल्यैः कृतं धूपनं स्कन्दोन्मादपिशाचराक्षससुरावेशग्रहघ्नं परम्", text: "kārpāsāsthimayūrapatrabṛhatīnirmālyapiṇḍītaka tvagvāṃśībṛṣadaṃśaviṭ tuṣavacākeśāhinirmocanaiḥ nāgendradvijaśṛṅgahiṅgumaricaistulyaiḥ kṛtaṃ dhūpanaṃ skandonmādapiśācarākṣasasurāveśagrahaghnaṃ param" },
      { type: "verse", number: "22", sanskrit: "त्रिकटुकदलकुंकुमग्रन्घिकक्षारसिंही निशादारुसिद्धार्थयुग्माम्बुशक्राह्वयैः सितलशुनफलत्रयोशीरतिक्तावचा तुत्थयष्टीबलालोहितैलाशिलापद्मकैः", text: "trikaṭukadalakuṃkumagranghikakṣārasiṃhī niśādārusiddhārthayugmāmbuśakrāhvayaiḥ sitalaśunaphalatrayośīratiktāvacā tutthayaṣṭībalālohitailāśilāpadmakaiḥ" },
      { type: "verse", number: "23", sanskrit: "विषातार्क्ष्यशैलैः सचव्यामयैः कल्कितैः घृतमनवमशेषमूत्रांशासिद्धं मतं भूतरावाह्वयं पानतस्तद्ग्रहघ्नं परम्", text: "viṣātārkṣyaśailaiḥ sacavyāmayaiḥ kalkitaiḥ ghṛtamanavamaśeṣamūtrāṃśāsiddhaṃ mataṃ bhūtarāvāhvayaṃ pānatastadgrahaghnaṃ param" },
      { type: "verse", number: "24", sanskrit: "नतमधुककरञ्जलाक्षापटोलीसमङ्गावचा पाटलीहिंगुसिद्धार्थसिंहीनिशायुग्लतारोहिणैः", text: "natamadhukakarañjalākṣāpaṭolīsamaṅgāvacā pāṭalīhiṃgusiddhārthasiṃhīniśāyuglatārohiṇaiḥ" },
      { type: "verse", number: "25", sanskrit: "बदरकटुफलत्रिकाकाण्डदारुक्रिमिघ्नाजगन्धामरा ङ्कोलकोशातकीशिग्रुनिम्बाम्बुदेन्द्राह्वयैः", text: "badarakaṭuphalatrikākāṇḍadārukrimighnājagandhāmarā ṅkolakośātakīśigrunimbāmbudendrāhvayaiḥ" },
      { type: "verse", number: "26", sanskrit: "गदशुकत्रुपुष्पबीजोग्रयष्ट्यद्रिकर्णीनिकुम्भाग्नि बिल्वैःसभैःकल्कितैर्मूत्रवर्गेण सिद्धं घृतम्", text: "gadaśukatrupuṣpabījograyaṣṭyadrikarṇīnikumbhāgni bilvaiḥsabhaiḥkalkitairmūtravargeṇa siddhaṃ ghṛtam" },
      { type: "verse", number: "27", sanskrit: "विधिविनिर्हितमाशु सर्वैःक्रमैर्योजितं हन्तिसर्वग्रहोन्मादकुष्ठज्वरांस्तन्महाभूतरावं स्मृतम्", text: "vidhivinirhitamāśu sarvaiḥkramairyojitaṃ hantisarvagrahonmādakuṣṭhajvarāṃstanmahābhūtarāvaṃ smṛtam" },
      { type: "verse", number: "28", sanskrit: "ग्रहा गृह्णन्ति ये येषु तेषां तेषु विशेषतः दिनेषु बलिहोमादीन् प्रयुञ्जीत चिकित्सकः", text: "grahā gṛhṇanti ye yeṣu teṣāṃ teṣu viśeṣataḥ dineṣu balihomādīn prayuñjīta cikitsakaḥ" },
      { type: "verse", number: "29", sanskrit: "स्नानवस्त्रवसामांसमद्यक्षीरगुडादि च रोचते यद्यदा येभ्यस्तत्तेषामाहरेत्तदा", text: "snānavastravasāmāṃsamadyakṣīraguḍādi ca rocate yadyadā yebhyastatteṣāmāharettadā" },
      { type: "verse", number: "30", sanskrit: "रत्नानि गन्धमाल्यानि बीजानि मधुसर्पिषी भक्ष्याश्च सर्वे सर्वेषां सामान्यो विधिरित्ययम्", text: "ratnāni gandhamālyāni bījāni madhusarpiṣī bhakṣyāśca sarve sarveṣāṃ sāmānyo vidhirityayam" },
      { type: "verse", number: "31", sanskrit: "सुरषिर्गुरुवृद्धेभ्यः सिद्धेभ्यश्च सुरालये दिश्युत्तरस्यां तत्रापि देवायोपहरेत् बलिन्", text: "suraṣirguruvṛddhebhyaḥ siddhebhyaśca surālaye diśyuttarasyāṃ tatrāpi devāyopaharet balin" },
      { type: "verse", number: "32", sanskrit: "पश्चिमायां यथाकालं दैत्यभूताय चत्वरे गन्धर्वाय गवां मार्गे सवस्त्राभरणं बलिम्", text: "paścimāyāṃ yathākālaṃ daityabhūtāya catvare gandharvāya gavāṃ mārge savastrābharaṇaṃ balim" },
      { type: "verse", number: "33", sanskrit: "पितृनागग्रहे नद्यां नागेभ्यः पूर्वदक्षिणे यक्षाय यक्षायतने सरितोर्वा समागमे", text: "pitṛnāgagrahe nadyāṃ nāgebhyaḥ pūrvadakṣiṇe yakṣāya yakṣāyatane saritorvā samāgame" },
      { type: "verse", number: "34", sanskrit: "चतुष्पथे राक्षसयोर्भीमेषु गहनेषु वा रक्षसां दक्षिणस्यां तु पूर्वस्यां ब्रह्मरक्षसाम् शून्यालये पिशाचाय पश्चिमां दिशमास्थिते", text: "catuṣpathe rākṣasayorbhīmeṣu gahaneṣu vā rakṣasāṃ dakṣiṇasyāṃ tu pūrvasyāṃ brahmarakṣasām śūnyālaye piśācāya paścimāṃ diśamāsthite" },
      { type: "verse", number: "35", sanskrit: "शुचिशुक्लानि माल्यानि गन्धाः क्षैरेयमोदनम् दधिच्छत्रं च धवलं देवानां बलिरिष्यते", text: "śuciśuklāni mālyāni gandhāḥ kṣaireyamodanam dadhicchatraṃ ca dhavalaṃ devānāṃ baliriṣyate" },
      { type: "verse", number: "36", sanskrit: "हिङ्गुसर्षपषड्ग्रन्थाव्योषैरर्धपलोन्मितैः चतुर्गुणे गवां मूत्रे घृतप्रस्थं विपाचयेत् तत्पाननावनाभ्यङ्गैर्देवग्रहविमोक्षणम्", text: "hiṅgusarṣapaṣaḍgranthāvyoṣairardhapalonmitaiḥ caturguṇe gavāṃ mūtre ghṛtaprasthaṃ vipācayet tatpānanāvanābhyaṅgairdevagrahavimokṣaṇam" },
      { type: "verse", number: "37", sanskrit: "नस्याञ्जनं वचाहिङ्गुलशुनं बस्तवारिणा", text: "nasyāñjanaṃ vacāhiṅgulaśunaṃ bastavāriṇā" },
      { type: "verse", number: "38", sanskrit: "दैत्ये बलिर्बहुफलः सोशीरकमलोत्पलः", text: "daitye balirbahuphalaḥ sośīrakamalotpalaḥ" },
      { type: "verse", number: "39", sanskrit: "नागानांसुमनोलाजगुडापूपगुडौदनैः परमान्नमधुक्षीरकृष्णमृन्नागकेसरैः वचापद्मपुरोशीररक्तोत्पलदलैर्बलिः", text: "nāgānāṃsumanolājaguḍāpūpaguḍaudanaiḥ paramānnamadhukṣīrakṛṣṇamṛnnāgakesaraiḥ vacāpadmapurośīraraktotpaladalairbaliḥ" },
      { type: "verse", number: "40", sanskrit: "श्वेतपत्रं च लोध्रं च तगरं नागसर्षपाः शीतेन वारिणा पिष्टं नावनाञ्जनयोर्हितम्", text: "śvetapatraṃ ca lodhraṃ ca tagaraṃ nāgasarṣapāḥ śītena vāriṇā piṣṭaṃ nāvanāñjanayorhitam" },
      { type: "verse", number: "41", sanskrit: "यक्षाणां क्षीरदध्याज्यमिश्रकौदनगुग्गुलु देवदारूत्पलं पद्ममुशीरं वस्त्रकाञ्चनम्", text: "yakṣāṇāṃ kṣīradadhyājyamiśrakaudanaguggulu devadārūtpalaṃ padmamuśīraṃ vastrakāñcanam" },
      { type: "verse", number: "42", sanskrit: "हिरण्यं च बलिर्योज्यो मूत्राज्यक्षीरमेकतः सिद्धं समोन्मितं पाननावनाभ्यञ्जने हितम्", text: "hiraṇyaṃ ca baliryojyo mūtrājyakṣīramekataḥ siddhaṃ samonmitaṃ pānanāvanābhyañjane hitam" },
      { type: "verse", number: "43", sanskrit: "हरीतकी हरिद्रे द्वे लशुनो मरिचं वचा निम्बपत्रं च बस्ताम्बुकल्कितं नावनाञ्जनम्", text: "harītakī haridre dve laśuno maricaṃ vacā nimbapatraṃ ca bastāmbukalkitaṃ nāvanāñjanam" },
      { type: "verse", number: "44", sanskrit: "ब्रह्मरक्षोबलिः सिद्धं यवानां पूर्णमाढकम् तोयस्य कुम्भः पललं छत्रं वस्त्रं विलेपनम्", text: "brahmarakṣobaliḥ siddhaṃ yavānāṃ pūrṇamāḍhakam toyasya kumbhaḥ palalaṃ chatraṃ vastraṃ vilepanam" },
      { type: "verse", number: "45", sanskrit: "गायत्रीविंशतिपलक्वाथे ऽर्धपलिकैः पचेत् त्र्यूषणत्रिफलाहिङ्गुषड्ग्रन्थामिसिसर्षपैः", text: "gāyatrīviṃśatipalakvāthe 'rdhapalikaiḥ pacet tryūṣaṇatriphalāhiṅguṣaḍgranthāmisisarṣapaiḥ" },
      { type: "verse", number: "46", sanskrit: "सनिम्बपत्रलशुनैः कुडवान् सप्त सर्पिषः गोमूत्रे त्रिगुणे पाननस्याभ्यङ्गेषु तद्धितम्", text: "sanimbapatralaśunaiḥ kuḍavān sapta sarpiṣaḥ gomūtre triguṇe pānanasyābhyaṅgeṣu taddhitam" },
      { type: "verse", number: "47", sanskrit: "रक्षसां पललं शुक्लं कुसुमं मिश्रकौदनम् बलिः पक्वाममांसानि निष्पावा रुधिरोक्षिताः", text: "rakṣasāṃ palalaṃ śuklaṃ kusumaṃ miśrakaudanam baliḥ pakvāmamāṃsāni niṣpāvā rudhirokṣitāḥ" },
      { type: "verse", number: "48", sanskrit: "नक्तमालशिरीषत्वङ्मूलपुष्पफलानि च तद्वच्च कृष्णपाटल्या बिल्वमूलं कटुत्रिकम्", text: "naktamālaśirīṣatvaṅmūlapuṣpaphalāni ca tadvacca kṛṣṇapāṭalyā bilvamūlaṃ kaṭutrikam" },
      { type: "verse", number: "49", sanskrit: "हिङ्ग्विन्द्रयवसिद्धार्थलशुनामलकीफलम् नावनाञ्जनयोर्योज्यो बस्तमूत्रद्रुतो ऽगदः", text: "hiṅgvindrayavasiddhārthalaśunāmalakīphalam nāvanāñjanayoryojyo bastamūtradruto 'gadaḥ" },
      { type: "verse", number: "50", sanskrit: "एभिरेव घृतं सिद्धं गवां मूत्रे चतुर्गुणे रक्षोग्रहान् वारयते पानाभ्यञ्जननावनैः", text: "ebhireva ghṛtaṃ siddhaṃ gavāṃ mūtre caturguṇe rakṣograhān vārayate pānābhyañjananāvanaiḥ" },
      { type: "verse", number: "51", sanskrit: "पिशाचानां बलिः सीधुः पिण्याकः पललं दधि मूलकं लवणं सर्पिः सभूतौदनयावकम्", text: "piśācānāṃ baliḥ sīdhuḥ piṇyākaḥ palalaṃ dadhi mūlakaṃ lavaṇaṃ sarpiḥ sabhūtaudanayāvakam" },
      { type: "verse", number: "52", sanskrit: "हरिद्राद्वयमञ्जिष्ठामिसिसैन्धवनागरम् हिङ्गुप्रियङ्गुत्रिकटुरसोनत्रिफलावचाः", text: "haridrādvayamañjiṣṭhāmisisaindhavanāgaram hiṅgupriyaṅgutrikaṭurasonatriphalāvacāḥ" },
      { type: "verse", number: "53", sanskrit: "पाटलीश्वेतकटभीशिरीषकुसुमैर्घृतम् गोमूत्रपादिकं सिद्धं पानाभ्यञ्जनयोर्हितम्", text: "pāṭalīśvetakaṭabhīśirīṣakusumairghṛtam gomūtrapādikaṃ siddhaṃ pānābhyañjanayorhitam" },
      { type: "verse", number: "54", sanskrit: "बस्ताम्बुपिष्टैस्तैरेव योज्यमञ्जननावनम्", text: "bastāmbupiṣṭaistaireva yojyamañjananāvanam" },
      { type: "verse", number: "55", sanskrit: "देवर्षिपितृगन्धर्वे तीक्ष्णं नस्यादि वर्जयेत् सर्पिष्पानादि मृद्वस्मिन् भैषज्यमवचारयेत्", text: "devarṣipitṛgandharve tīkṣṇaṃ nasyādi varjayet sarpiṣpānādi mṛdvasmin bhaiṣajyamavacārayet" },
      { type: "verse", number: "56", sanskrit: "ऋते पिशाचात् सर्वेषु प्रतिकूलं च नाचरेत् सवैद्यमातुरं घ्नन्ति क्रुद्धास्ते हि महौजसः", text: "ṛte piśācāt sarveṣu pratikūlaṃ ca nācaret savaidyamāturaṃ ghnanti kruddhāste hi mahaujasaḥ" },
      { type: "verse", number: "57", sanskrit: "ईश्वरं द्वादशभुजं नाथमार्यावलोकितम् सर्वव्याधिचिकित्सां च जपन्सर्वग्रहान्जयेत् तथोन्मादानपस्मारानन्यं वा चित्तविप्लवम्", text: "īśvaraṃ dvādaśabhujaṃ nāthamāryāvalokitam sarvavyādhicikitsāṃ ca japansarvagrahānjayet tathonmādānapasmārānanyaṃ vā cittaviplavam" },
      { type: "verse", number: "58", sanskrit: "महाविद्यां च मायूरीं शुचिस्तं श्रावयेत् सदा", text: "mahāvidyāṃ ca māyūrīṃ śucistaṃ śrāvayet sadā" },
      { type: "verse", number: "59", sanskrit: "भूतेशं पूजयेत् स्थाणुं प्रमथाख्यांश्च तद्गणान् जपन् सिद्धांश्च तन्मन्त्रान् ग्रहान् सर्वानपोहति", text: "bhūteśaṃ pūjayet sthāṇuṃ pramathākhyāṃśca tadgaṇān japan siddhāṃśca tanmantrān grahān sarvānapohati" },
      { type: "verse", number: "60", sanskrit: "यच्चानन्तरयोः किञ्चिद्वक्ष्यते ऽध्याययोर्हितम् यच्चोक्तमिह तत् सर्वं प्रयुञ्जीत परस्परम्", text: "yaccānantarayoḥ kiñcidvakṣyate 'dhyāyayorhitam yaccoktamiha tat sarvaṃ prayuñjīta parasparam" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 9,
    lang: "sa",
    content: [
      { type: "heading", heading: "Широ крия — процедуры для головы" },
      { type: "text", text: "Глава 9 Уттара стханы — «Широ крия» — посвящена специализированному разделу: процедуры для головы. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथात उन्मादप्रतिषेधं नामाध्यायं व्याख्यास्यमः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāta unmādapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyamaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "षडुन्मादा भवन्ति वातपित्तकफसन्निपाताधिविषनिमित्ताः तत्रोन्मादो नाम य उन्मार्गगैः शारीरमानसैर्दोषैर्मनसो मदः", text: "ṣaḍunmādā bhavanti vātapittakaphasannipātādhiviṣanimittāḥ tatronmādo nāma ya unmārgagaiḥ śārīramānasairdoṣairmanaso madaḥ" },
      { type: "verse", number: "3", sanskrit: "तेषां पुनरुन्मार्गगत्वे हेतुः शमलं विकृतोपहितमहितमनुचितमन्नपानविधिनिरपेक्षमाहारजातमत्युपक्षीणदेहानां व्यवायव्याधिवेगसमुद्गमे विषमशरीरचेष्टोपसेवा देवद्विजगुरूल्लङ्घनं वा रागद्वेषजनिताभिराधिभिर्मनोविघातो विषोपविषगरोपयोगो वा", text: "teṣāṃ punarunmārgagatve hetuḥ śamalaṃ vikṛtopahitamahitamanucitamannapānavidhinirapekṣamāhārajātamatyupakṣīṇadehānāṃ vyavāyavyādhivegasamudgame viṣamaśarīraceṣṭopasevā devadvijagurūllaṅghanaṃ vā rāgadveṣajanitābhirādhibhirmanovighāto viṣopaviṣagaropayogo vā" },
      { type: "verse", number: "4", sanskrit: "एभिर्हीनसत्वस्य मनस्युपहते बुद्धौ प्रचलितायामत्युदीर्णत्वाद्दोषाः प्रकुपिता हृदयमुपसृत्य मनोवहानि स्रोतांस्यावृत्य जनयन्त्युन्मादम्", text: "ebhirhīnasatvasya manasyupahate buddhau pracalitāyāmatyudīrṇatvāddoṣāḥ prakupitā hṛdayamupasṛtya manovahāni srotāṃsyāvṛtya janayantyunmādam" },
      { type: "verse", number: "5", sanskrit: "तत्र शिरसः शून्यता चक्षुषोरस्वस्थत्वं स्वनः कर्णयोरुच्छ्वासाधिक्यमास्यसंस्रवणमन्नानभिलाषो ऽरोचको ऽविपाको हृदयग्रहो ऽस्थाने ध्यानायाससम्मोहोद्वेगाः सततं रोमहर्षो ज्वरो ऽभीक्ष्णमुन्मत्तचित्तत्वमुदर्दित्वमर्दिताकृतिकरणं व्याधेः स्वप्ने च दर्शनमभीक्ष्णं भ्रान्तचित्तचलितानवस्थितानामप्रशस्तानां रूपाणां तिलपीडकवच्चक्राधिरोहणं वातकुण्डलिकाभिरुन्मथनं निमज्जनं कलुषाणामम्भसामावर्तेषु चक्षुषोश्चापसर्पणामिति दोषनिमित्तानामुन्मादानां पूर्वरूपाणि ततो ऽनन्तरमुन्मादाभिनिर्वृत्तिरेव", text: "tatra śirasaḥ śūnyatā cakṣuṣorasvasthatvaṃ svanaḥ karṇayorucchvāsādhikyamāsyasaṃsravaṇamannānabhilāṣo 'rocako 'vipāko hṛdayagraho 'sthāne dhyānāyāsasammohodvegāḥ satataṃ romaharṣo jvaro 'bhīkṣṇamunmattacittatvamudarditvamarditākṛtikaraṇaṃ vyādheḥ svapne ca darśanamabhīkṣṇaṃ bhrāntacittacalitānavasthitānāmapraśastānāṃ rūpāṇāṃ tilapīḍakavaccakrādhirohaṇaṃ vātakuṇḍalikābhirunmathanaṃ nimajjanaṃ kaluṣāṇāmambhasāmāvarteṣu cakṣuṣoścāpasarpaṇāmiti doṣanimittānāmunmādānāṃ pūrvarūpāṇi tato 'nantaramunmādābhinirvṛttireva" },
      { type: "verse", number: "6", sanskrit: "सामान्यलिङ्गं मनोबुद्धिस्मृत्यादिसम्प्रमोषः", text: "sāmānyaliṅgaṃ manobuddhismṛtyādisampramoṣaḥ" },
      { type: "verse", number: "7", sanskrit: "ततश्च देहो हतसारथिरिव रथो ऽकर्णधार इव चाप्सु प्लवः सुखदुःखाचारधर्माधर्मप्रलुप्तो ऽकस्माद् भ्रमति", text: "tataśca deho hatasārathiriva ratho 'karṇadhāra iva cāpsu plavaḥ sukhaduḥkhācāradharmādharmapralupto 'kasmād bhramati" },
      { type: "verse", number: "8", sanskrit: "तत्रवातादस्थानस्मितहसितनृत्तगीतवादित्रवागङ्गविक्षेपवाग्भेदभ्रू विक्षेपरोदनक्रोशनास्फोटनानि पर्यटनमजस्रमास्यात् फेनागमो यानमयानैरलङ्करणमनलङ्कारिकैर्द्रव्यैर्लोभो ऽभ्यवहार्येषु लब्धेषु चावमानस्तीव्रं मात्सर्यं कार्श्यं पारुष्यमुत्पिण्डितारुणाक्षता जीर्णे ऽन्ने चातिबलवत्वम्", text: "tatravātādasthānasmitahasitanṛttagītavāditravāgaṅgavikṣepavāgbhedabhrū vikṣeparodanakrośanāsphoṭanāni paryaṭanamajasramāsyāt phenāgamo yānamayānairalaṅkaraṇamanalaṅkārikairdravyairlobho 'bhyavahāryeṣu labdheṣu cāvamānastīvraṃ mātsaryaṃ kārśyaṃ pāruṣyamutpiṇḍitāruṇākṣatā jīrṇe 'nne cātibalavatvam" },
      { type: "verse", number: "9", sanskrit: "पित्तात् क्रोधः सन्तर्जनमकस्मान्मुष्टिलोष्टकाष्ठशस्त्रैरभिद्रवणं नग्नता प्रच्छायशिशिराभिरातिरुदकाभिलाषः सन्तापः पीतावस्रंसनमनिमित्तमनलज्वलनोपशङ्काह्नि तारकादर्शनं ताम्रहरितहारिद्रसंरब्धाक्षत्वं च", text: "pittāt krodhaḥ santarjanamakasmānmuṣṭiloṣṭakāṣṭhaśastrairabhidravaṇaṃ nagnatā pracchāyaśiśirābhirātirudakābhilāṣaḥ santāpaḥ pītāvasraṃsanamanimittamanalajvalanopaśaṅkāhni tārakādarśanaṃ tāmraharitahāridrasaṃrabdhākṣatvaṃ ca" },
      { type: "verse", number: "10", sanskrit: "कफादल्पवाक्चेष्टाहारत्वमरोचको वमथुरुष्णसेवा लालासिङ्घणकस्रवणं रहः कामता स्त्रीप्रियत्वं निद्राबीभत्सत्वं शौचद्वेषः श्वयथुरास्ये शुक्लस्तिमितमलाविलाक्षता भुक्ते रात्रौ च बलवत्वमिति भवति चात्र", text: "kaphādalpavākceṣṭāhāratvamarocako vamathuruṣṇasevā lālāsiṅghaṇakasravaṇaṃ rahaḥ kāmatā strīpriyatvaṃ nidrābībhatsatvaṃ śaucadveṣaḥ śvayathurāsye śuklastimitamalāvilākṣatā bhukte rātrau ca balavatvamiti bhavati cātra" },
      { type: "verse", number: "11", sanskrit: "सर्वायतनसंस्थानसन्निपाते तदात्मकम् उन्मादं दारुणं विद्यात्तं भिषक् परिवर्जयेत्", text: "sarvāyatanasaṃsthānasannipāte tadātmakam unmādaṃ dāruṇaṃ vidyāttaṃ bhiṣak parivarjayet" },
      { type: "verse", number: "12", sanskrit: "धनकान्तादिनाशेन दुःसहेनाभिषङ्गवान् पाण्डुर्दीनो मुहुर्मुह्यन् हाहेति परिदेवते", text: "dhanakāntādināśena duḥsahenābhiṣaṅgavān pāṇḍurdīno muhurmuhyan hāheti paridevate" },
      { type: "verse", number: "13", sanskrit: "रोदित्यकस्मात् स्मयते तद्गुणान् बहुमन्यते शोकक्लिष्टमना ध्यायन् जागरूको विचेष्टते", text: "rodityakasmāt smayate tadguṇān bahumanyate śokakliṣṭamanā dhyāyan jāgarūko viceṣṭate" },
      { type: "verse", number: "14", sanskrit: "विषेण श्याववदनो नष्टच्छायो ऽबलेन्द्रियः वेगान्तरे ऽपि सम्भ्रान्तो रक्ताक्षस्तं विवर्जयेत्", text: "viṣeṇa śyāvavadano naṣṭacchāyo 'balendriyaḥ vegāntare 'pi sambhrānto raktākṣastaṃ vivarjayet" },
      { type: "verse", number: "15", sanskrit: "अथानिलज उन्मादे स्नेहपानं प्रयोजयेत् पूर्वमावृतमार्गे तु सस्नेहं मृदुशोधनम्", text: "athānilaja unmāde snehapānaṃ prayojayet pūrvamāvṛtamārge tu sasnehaṃ mṛduśodhanam" },
      { type: "verse", number: "16", sanskrit: "कफपित्तोद्भवे ऽप्यादौ वमनं सविरेचनम् स्निग्धास्विन्नस्य बस्तींश्च शिरसश्च विरेचनम् तथास्य शुद्धदेहस्य प्रसादं लभते मनः", text: "kaphapittodbhave 'pyādau vamanaṃ savirecanam snigdhāsvinnasya bastīṃśca śirasaśca virecanam tathāsya śuddhadehasya prasādaṃ labhate manaḥ" },
      { type: "verse", number: "17", sanskrit: "स्नेहकाले च वातोत्थे तैलं शरीषमिष्यते महाकल्याणकं पैत्ते पञ्चगव्यं कफोद्भवे", text: "snehakāle ca vātotthe tailaṃ śarīṣamiṣyate mahākalyāṇakaṃ paitte pañcagavyaṃ kaphodbhave" },
      { type: "verse", number: "18", sanskrit: "इथमप्यनुवृत्तौ तु तीक्ष्णं नावनमञ्जनम् हर्षणाश्वासनोत्रासभयताडनतर्जनम्", text: "ithamapyanuvṛttau tu tīkṣṇaṃ nāvanamañjanam harṣaṇāśvāsanotrāsabhayatāḍanatarjanam" },
      { type: "verse", number: "19", sanskrit: "अभ्यङ्गोद्वर्तनालेपधूपान् पानं च सर्पिषः युञ्ज्यात्तांनि हि शुद्धस्य नयन्ति प्रकृतिं मनः", text: "abhyaṅgodvartanālepadhūpān pānaṃ ca sarpiṣaḥ yuñjyāttāṃni hi śuddhasya nayanti prakṛtiṃ manaḥ" },
      { type: "verse", number: "20", sanskrit: "हिङ्गुसौवर्चलव्योषैर्द्विपलांशैर्घृताढकम् सिद्धं समूत्रमुन्मादभूतापस्मारनुत् परम्", text: "hiṅgusauvarcalavyoṣairdvipalāṃśairghṛtāḍhakam siddhaṃ samūtramunmādabhūtāpasmāranut param" },
      { type: "verse", number: "21", sanskrit: "द्वौ प्रस्थौ स्वरसात्ब्रह्म्या घृतप्रस्थं च साधितम् व्योषश्यामात्रिवृद्बिम्बीशङ्खपुष्पीनृपद्रुमैः", text: "dvau prasthau svarasātbrahmyā ghṛtaprasthaṃ ca sādhitam vyoṣaśyāmātrivṛdbimbīśaṅkhapuṣpīnṛpadrumaiḥ" },
      { type: "verse", number: "22", sanskrit: "ससप्तलाकृमिहरैः कल्कितैरक्षसम्मितैः पलवृध्या प्रयुञ्जीत परं मात्राचतुष्पलम्", text: "sasaptalākṛmiharaiḥ kalkitairakṣasammitaiḥ palavṛdhyā prayuñjīta paraṃ mātrācatuṣpalam" },
      { type: "verse", number: "23", sanskrit: "उन्मादकुष्ठापस्मारहरं वन्ध्यासुतप्रदम् वाक्स्वरस्मृतिमेधाकृद्धन्यं ब्राह्मीघृतं स्मृतम्", text: "unmādakuṣṭhāpasmāraharaṃ vandhyāsutapradam vāksvarasmṛtimedhākṛddhanyaṃ brāhmīghṛtaṃ smṛtam" },
      { type: "verse", number: "24", sanskrit: "वराविशालावढ्रैलादेवदार्वेलवालुकैः द्विसारिवाद्विरजनीद्विस्थिराफलिनीनतैः", text: "varāviśālāvaḍhrailādevadārvelavālukaiḥ dvisārivādvirajanīdvisthirāphalinīnataiḥ" },
      { type: "verse", number: "25", sanskrit: "बृहतीकुष्ठमञ्जिष्ठानागकेसरदाडिमैः वेल्लतालीसपत्रैलामालतीमुकुलोत्पलैः", text: "bṛhatīkuṣṭhamañjiṣṭhānāgakesaradāḍimaiḥ vellatālīsapatrailāmālatīmukulotpalaiḥ" },
      { type: "verse", number: "26", sanskrit: "सदन्तीपद्मकहिमैः कर्षांशैः सर्पिषः पचेत् प्रस्थं भूतग्रहोन्मादकासापस्मारसूदनम्", text: "sadantīpadmakahimaiḥ karṣāṃśaiḥ sarpiṣaḥ pacet prasthaṃ bhūtagrahonmādakāsāpasmārasūdanam" },
      { type: "verse", number: "27", sanskrit: "पाण्डुकण्डूविषे शोषे मेहे मोहे ज्वरे गरे अरेतस्यल्परजसि दैवोपहतचेतसि", text: "pāṇḍukaṇḍūviṣe śoṣe mehe mohe jvare gare aretasyalparajasi daivopahatacetasi" },
      { type: "verse", number: "28", sanskrit: "अमेधसि स्खलद्वाचि स्मृतिकामे ऽल्पपावके बल्यं मङ्गल्यमायुष्यं कान्तिसौभाग्यपुष्टिदम् कल्याणकामिदं सर्पिः श्रेष्ठं पुंसवनषे च", text: "amedhasi skhaladvāci smṛtikāme 'lpapāvake balyaṃ maṅgalyamāyuṣyaṃ kāntisaubhāgyapuṣṭidam kalyāṇakāmidaṃ sarpiḥ śreṣṭhaṃ puṃsavanaṣe ca" },
      { type: "verse", number: "29", sanskrit: "एभ्यो द्विसारिवादीनि जले पक्त्वैकविंशतिम् जले तस्मिन् पचेत् सर्पिर्गृष्टिक्षीरचतुर्गुणम्", text: "ebhyo dvisārivādīni jale paktvaikaviṃśatim jale tasmin pacet sarpirgṛṣṭikṣīracaturguṇam" },
      { type: "verse", number: "30", sanskrit: "वीराद्विमेदाकाकोलीकपिकच्छूविषाणिभिः सूप्यपर्णीयुतैरेतन्महाकल्याणकं परम् बृंहणं सन्निपातघ्नं पूर्वस्मादधिकं गुणैः", text: "vīrādvimedākākolīkapikacchūviṣāṇibhiḥ sūpyaparṇīyutairetanmahākalyāṇakaṃ param bṛṃhaṇaṃ sannipātaghnaṃ pūrvasmādadhikaṃ guṇaiḥ" },
      { type: "verse", number: "31", sanskrit: "जटिला पूतना केशी चारटी मर्कटी वचा त्रायमाणा जया वीरा चोरकः कटुरोहिणी", text: "jaṭilā pūtanā keśī cāraṭī markaṭī vacā trāyamāṇā jayā vīrā corakaḥ kaṭurohiṇī" },
      { type: "verse", number: "32", sanskrit: "कायस्था सूकरी छत्रा सातिच्छत्रा पलङ्कषा महापुरुषदन्ता च वयस्था नाकुलीद्वयम्", text: "kāyasthā sūkarī chatrā sāticchatrā palaṅkaṣā mahāpuruṣadantā ca vayasthā nākulīdvayam" },
      { type: "verse", number: "33", sanskrit: "कटम्भरा वृश्चिकाली शालिपर्णी च तैर्घृतम् सिद्धं चातुर्थिकोन्मादग्रहापस्मारनाशनम्", text: "kaṭambharā vṛścikālī śāliparṇī ca tairghṛtam siddhaṃ cāturthikonmādagrahāpasmāranāśanam" },
      { type: "verse", number: "34", sanskrit: "महापैशाचकं नाम घृतमेतद्यथामृतम् बुद्धिमेधास्मृतिकरं बालानां चाङ्गवर्धनम्", text: "mahāpaiśācakaṃ nāma ghṛtametadyathāmṛtam buddhimedhāsmṛtikaraṃ bālānāṃ cāṅgavardhanam" },
      { type: "verse", number: "35", sanskrit: "लशुनानां शतं त्रिंशदभयात्र्यूषणात् पलम् गव्यचर्ममषीप्रस्थो द्व्याढकं क्षीरमूत्रयोः", text: "laśunānāṃ śataṃ triṃśadabhayātryūṣaṇāt palam gavyacarmamaṣīprastho dvyāḍhakaṃ kṣīramūtrayoḥ" },
      { type: "verse", number: "36", sanskrit: "पुराणसर्पिषःप्रस्थमेभिः सिद्धं प्रयोजयेत् हिङ्गुचूर्णपलं शीते दत्वा च मधुमानिकाम्", text: "purāṇasarpiṣaḥprasthamebhiḥ siddhaṃ prayojayet hiṅgucūrṇapalaṃ śīte datvā ca madhumānikām" },
      { type: "verse", number: "37", sanskrit: "तद्दोषगन्तुसम्भूतानुन्मादान् विषमज्वरान् अपस्मारांश्च हन्त्याशु पानाभ्यञ्जननावनैः", text: "taddoṣagantusambhūtānunmādān viṣamajvarān apasmārāṃśca hantyāśu pānābhyañjananāvanaiḥ" },
      { type: "verse", number: "38", sanskrit: "केवलं सिद्धमेभिर्वा घृतमुत्तममात्रया पुराणं पाययित्वैनं श्वभ्रे रुन्ध्यात् गृहे ऽथवा", text: "kevalaṃ siddhamebhirvā ghṛtamuttamamātrayā purāṇaṃ pāyayitvainaṃ śvabhre rundhyāt gṛhe 'thavā" },
      { type: "verse", number: "39", sanskrit: "एतानौषधवर्गान्वा विधेयत्वमगच्छति अञ्जनोद्वर्तनालेपनावनादिषु योजयेत्", text: "etānauṣadhavargānvā vidheyatvamagacchati añjanodvartanālepanāvanādiṣu yojayet" },
      { type: "verse", number: "40", sanskrit: "अश्वगन्धाजगन्धोग्रगन्धालशुनसर्षपैः रास्नाकायस्थगोलोमीयुक्तैस्तैलं विपाचितम्", text: "aśvagandhājagandhogragandhālaśunasarṣapaiḥ rāsnākāyasthagolomīyuktaistailaṃ vipācitam" },
      { type: "verse", number: "41", sanskrit: "गोमूत्रसदृशं पाननस्याभ्यङ्गानुवासैनैः सर्वोन्मादग्रहालक्ष्मीपाप्मापस्मारनाशनम्", text: "gomūtrasadṛśaṃ pānanasyābhyaṅgānuvāsainaiḥ sarvonmādagrahālakṣmīpāpmāpasmāranāśanam" },
      { type: "verse", number: "42", sanskrit: "शिरीषो मधुकं हिङ्गु लशुनस्तगरं वचा कुष्ठं च बस्तमूत्रेण पिष्टं स्यान्नावनाञ्जनम्", text: "śirīṣo madhukaṃ hiṅgu laśunastagaraṃ vacā kuṣṭhaṃ ca bastamūtreṇa piṣṭaṃ syānnāvanāñjanam" },
      { type: "verse", number: "43", sanskrit: "तद्वद्व्योषं हरिद्रे द्वे मञ्जिष्ठाहिङ्गुसर्षपाः शिरीषबीजं चोन्मादग्रहापस्मारनाशनम्", text: "tadvadvyoṣaṃ haridre dve mañjiṣṭhāhiṅgusarṣapāḥ śirīṣabījaṃ conmādagrahāpasmāranāśanam" },
      { type: "verse", number: "44", sanskrit: "ब्राह्मीमैन्द्रीं विडङ्गानि व्योषं हिङ्गुजटां मुरम् रास्नां विषघ्नां लशुनं विशल्यां सुरसं वचाम्", text: "brāhmīmaindrīṃ viḍaṅgāni vyoṣaṃ hiṅgujaṭāṃ muram rāsnāṃ viṣaghnāṃ laśunaṃ viśalyāṃ surasaṃ vacām" },
      { type: "verse", number: "45", sanskrit: "ज्योतिष्मतीं नागविन्नामनन्तां सहरीतकीम् काम्लीं च हस्तिमूत्रेण पिष्ट्वा छायाविशोषिता वर्तिनस्याञ्जनालेपधूपैरुन्मादसूदनी", text: "jyotiṣmatīṃ nāgavinnāmanantāṃ saharītakīm kāmlīṃ ca hastimūtreṇa piṣṭvā chāyāviśoṣitā vartinasyāñjanālepadhūpairunmādasūdanī" },
      { type: "verse", number: "46", sanskrit: "पिष्ट्वा फलान्यपामार्गाद्धिङ्गुलं हिङ्गुपत्रिकाम् वर्तिर्गोक्रोष्टुपित्तेन मरिचार्धांशकाञ्जनम् उन्मादभूतापस्मारे नृषु गोषु च गोचरे", text: "piṣṭvā phalānyapāmārgāddhiṅgulaṃ hiṅgupatrikām vartirgokroṣṭupittena maricārdhāṃśakāñjanam unmādabhūtāpasmāre nṛṣu goṣu ca gocare" },
      { type: "verse", number: "47", sanskrit: "अवपीडाश्च विविधाः सर्षपस्नेहसंयुताः कटुतैलेन चाभ्यङ्गो ध्मापयेच्चास्य तद्रजः", text: "avapīḍāśca vividhāḥ sarṣapasnehasaṃyutāḥ kaṭutailena cābhyaṅgo dhmāpayeccāsya tadrajaḥ" },
      { type: "verse", number: "48", sanskrit: "सहिङ्गुतीक्ष्णधूमश्च सूत्रस्थानोदितो हितः शृगालशल्यकोलूकजतुकावृकबस्तजैः", text: "sahiṅgutīkṣṇadhūmaśca sūtrasthānodito hitaḥ śṛgālaśalyakolūkajatukāvṛkabastajaiḥ" },
      { type: "verse", number: "49", sanskrit: "मूत्रपित्तशकृल्लोमनखचर्मभिराचरेत् धूपधूमाञ्जनाभ्यङ्गप्रदेहपरिषेचनम्", text: "mūtrapittaśakṛllomanakhacarmabhirācaret dhūpadhūmāñjanābhyaṅgapradehapariṣecanam" },
      { type: "verse", number: "50", sanskrit: "धूपयेत् सततं चैनं श्वगोमत्स्यैः सुपूतिभिः वातश्लेष्मात्मके प्रायः पैत्तिके तु प्रशस्यते", text: "dhūpayet satataṃ cainaṃ śvagomatsyaiḥ supūtibhiḥ vātaśleṣmātmake prāyaḥ paittike tu praśasyate" },
      { type: "verse", number: "51", sanskrit: "तिक्तकं जीवनीयं च सर्पिः स्नेहश्च मिश्रकः", text: "tiktakaṃ jīvanīyaṃ ca sarpiḥ snehaśca miśrakaḥ" },
      { type: "verse", number: "52", sanskrit: "शीतानि चान्नपानानि मधुराणि लघूनि च विध्येत् सिरां यथोक्तां वा तृप्तं मेद्यामिषस्य वा निवाते शाययेदेवं मुच्यते मतिविभ्रमात्", text: "śītāni cānnapānāni madhurāṇi laghūni ca vidhyet sirāṃ yathoktāṃ vā tṛptaṃ medyāmiṣasya vā nivāte śāyayedevaṃ mucyate mativibhramāt" },
      { type: "verse", number: "53", sanskrit: "प्रक्षिप्यासलिले कूपे शोषयेद्वा बुभुक्षया आश्वासयेत् सुहृत्तं वा वाक्यैर्धर्मार्थसंहितैः", text: "prakṣipyāsalile kūpe śoṣayedvā bubhukṣayā āśvāsayet suhṛttaṃ vā vākyairdharmārthasaṃhitaiḥ" },
      { type: "verse", number: "54", sanskrit: "ब्रूयादिष्टविनाशं वा दर्शयेदद्भुतानि वा बद्धं सर्षपतैलाक्तं न्यस्तं चोत्तानमातपे", text: "brūyādiṣṭavināśaṃ vā darśayedadbhutāni vā baddhaṃ sarṣapatailāktaṃ nyastaṃ cottānamātape" },
      { type: "verse", number: "55", sanskrit: "कपिकच्छ्वाथवा तप्तैर्लोहतैलजलैः स्पृशेत् कशाभिस्ताडयित्वा वा बध्वा श्वभ्रे विनिक्षिपेत्", text: "kapikacchvāthavā taptairlohatailajalaiḥ spṛśet kaśābhistāḍayitvā vā badhvā śvabhre vinikṣipet" },
      { type: "verse", number: "56", sanskrit: "अथवा वीतशस्त्राश्मजने सन्तमसे गृहे सर्पेणोद्घृतदंष्ट्रेण दान्तैः सिंहैर्गजैश्च तम् त्रासयेच्छस्त्रहस्तैर्वा किरातारातितस्करैः", text: "athavā vītaśastrāśmajane santamase gṛhe sarpeṇodghṛtadaṃṣṭreṇa dāntaiḥ siṃhairgajaiśca tam trāsayecchastrahastairvā kirātārātitaskaraiḥ" },
      { type: "verse", number: "57", sanskrit: "अथवा राजपुरुषा बहिर्नीत्वा सुसंयतम् भीषयेयुर्वधेनैनं तर्जयन्तो नृपाज्ञया", text: "athavā rājapuruṣā bahirnītvā susaṃyatam bhīṣayeyurvadhenainaṃ tarjayanto nṛpājñayā" },
      { type: "verse", number: "58", sanskrit: "देहदुःखभयेभ्यो हि परं प्राणभयं मतम् तेन याति शमं तस्य सर्वतो विप्लुतं मनः सिद्धा क्रिया प्रयोज्येयं देशकालाद्यपेक्षया", text: "dehaduḥkhabhayebhyo hi paraṃ prāṇabhayaṃ matam tena yāti śamaṃ tasya sarvato viplutaṃ manaḥ siddhā kriyā prayojyeyaṃ deśakālādyapekṣayā" },
      { type: "verse", number: "59", sanskrit: "इष्टद्रव्यविनाशात्तु मनो यस्योपहन्यते तस्य तत्सदृशप्राप्तिसान्त्वाश्वासैः प्रसादयेत्", text: "iṣṭadravyavināśāttu mano yasyopahanyate tasya tatsadṛśaprāptisāntvāśvāsaiḥ prasādayet" },
      { type: "verse", number: "60", sanskrit: "कामशोकभयक्रोधहर्षेर्ष्यालोभसम्भवान् परस्परप्रतिद्वन्द्वैरेभिरेव शमं नयेत्", text: "kāmaśokabhayakrodhaharṣerṣyālobhasambhavān parasparapratidvandvairebhireva śamaṃ nayet" },
      { type: "verse", number: "61", sanskrit: "भूतानुबन्धमीक्षेत प्रोक्तलिङ्गाधिकाकृतिम् यद्युन्मादे ततः कुर्यात् भूतनिर्दिष्टमौषधम्", text: "bhūtānubandhamīkṣeta proktaliṅgādhikākṛtim yadyunmāde tataḥ kuryāt bhūtanirdiṣṭamauṣadham" },
      { type: "verse", number: "62", sanskrit: "बलिं च दद्यात् पललं यावकं सक्तुपिण्डिकाम् स्निग्धं मधुरमाहारं तण्डुलान् रुधिरोक्षितान्", text: "baliṃ ca dadyāt palalaṃ yāvakaṃ saktupiṇḍikām snigdhaṃ madhuramāhāraṃ taṇḍulān rudhirokṣitān" },
      { type: "verse", number: "63", sanskrit: "पक्वामकानिमांसानि सुरां मैरेयमासवम् अतिमुक्तस्य पुष्पाणि जात्याः सहचरस्य च चतुष्पथे गवां तीर्थे नदीनां सङ्गमेषु च", text: "pakvāmakānimāṃsāni surāṃ maireyamāsavam atimuktasya puṣpāṇi jātyāḥ sahacarasya ca catuṣpathe gavāṃ tīrthe nadīnāṃ saṅgameṣu ca" },
      { type: "verse", number: "64", sanskrit: "निवृत्तामिषमद्यो यो हिताशी प्रयतः शुचिः निजागन्तुभिरुन्मादैः सत्ववान् न स युज्यते", text: "nivṛttāmiṣamadyo yo hitāśī prayataḥ śuciḥ nijāgantubhirunmādaiḥ satvavān na sa yujyate" },
      { type: "verse", number: "65", sanskrit: "प्रसादश्चेन्द्रियार्थानां बुध्यात्ममनसां तथा धातूनां प्रकृतिस्थत्वं विगतोन्मादलक्षणम्", text: "prasādaścendriyārthānāṃ budhyātmamanasāṃ tathā dhātūnāṃ prakṛtisthatvaṃ vigatonmādalakṣaṇam" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 10,
    lang: "sa",
    content: [
      { type: "heading", heading: "Мукха рога — болезни рта — обзор" },
      { type: "text", text: "Глава 10 Уттара стханы — «Мукха рога» — посвящена специализированному разделу: болезни рта — обзор. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो ऽपस्मारप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto 'pasmārapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "स्मृत्यपायो ह्यपस्मारः स धीसत्त्वाभिसम्प्लवात् जायते ऽभिहते चित्ते चिन्ताशोकभयादिभिः", text: "smṛtyapāyo hyapasmāraḥ sa dhīsattvābhisamplavāt jāyate 'bhihate citte cintāśokabhayādibhiḥ" },
      { type: "verse", number: "3", sanskrit: "उन्मादवत् प्रकुपितैश्चित्तदेहगतैर्मलैः हते सत्त्वे हृदि व्याप्ते संज्ञावाहिषु खेषु च", text: "unmādavat prakupitaiścittadehagatairmalaiḥ hate sattve hṛdi vyāpte saṃjñāvāhiṣu kheṣu ca" },
      { type: "verse", number: "4", sanskrit: "तमो विशन् मूढमतिर्बीभत्साः कुरुते क्रियाः दन्तान्खादन्वमन्फेनं हस्तौ पादौ च विक्षिपन्", text: "tamo viśan mūḍhamatirbībhatsāḥ kurute kriyāḥ dantānkhādanvamanphenaṃ hastau pādau ca vikṣipan" },
      { type: "verse", number: "5", sanskrit: "पश्यन्नसन्ति रूपाणि प्रस्खलन् पतति क्षितौ विजिह्माक्षिभ्रुवो दोषवेगे ऽतीते विबुध्यते", text: "paśyannasanti rūpāṇi praskhalan patati kṣitau vijihmākṣibhruvo doṣavege 'tīte vibudhyate" },
      { type: "verse", number: "6", sanskrit: "कालान्तरेण स पुनश्चैवमेव विचेष्टते अपस्मारश्चतुर्भेदो वाताद्यैर्निचयेन च", text: "kālāntareṇa sa punaścaivameva viceṣṭate apasmāraścaturbhedo vātādyairnicayena ca" },
      { type: "verse", number: "7", sanskrit: "रूपमुत्पत्स्यमाने ऽस्मिन् हृत्कम्पः शून्यता भ्रमः तमसो दर्शनं ध्यानं भ्रूव्युदासो ऽक्षिवैकृतम्", text: "rūpamutpatsyamāne 'smin hṛtkampaḥ śūnyatā bhramaḥ tamaso darśanaṃ dhyānaṃ bhrūvyudāso 'kṣivaikṛtam" },
      { type: "verse", number: "8", sanskrit: "अशब्दश्रवणं स्वेदो लालासिङ्घाणकस्रुतिः अविपाको ऽरुचिर्मूर्छा कुक्ष्याटोपो बलक्षयः", text: "aśabdaśravaṇaṃ svedo lālāsiṅghāṇakasrutiḥ avipāko 'rucirmūrchā kukṣyāṭopo balakṣayaḥ" },
      { type: "verse", number: "9", sanskrit: "निद्रानाशो ऽङ्गमर्दस्तृट् स्वप्ने गानं सनर्तनम् पानं तैलस्य मद्यस्य तयोरेव च मेहनम्", text: "nidrānāśo 'ṅgamardastṛṭ svapne gānaṃ sanartanam pānaṃ tailasya madyasya tayoreva ca mehanam" },
      { type: "verse", number: "10", sanskrit: "तत्र वातात् स्फुरत्सक्थिः प्रततं च मुहुर्मुहुः अपस्मरति संज्ञां च लभते विस्वरं रुदन्", text: "tatra vātāt sphuratsakthiḥ pratataṃ ca muhurmuhuḥ apasmarati saṃjñāṃ ca labhate visvaraṃ rudan" },
      { type: "verse", number: "11", sanskrit: "उत्पिण्डिताक्षः श्वसिति फेनं वमति कम्पते आविध्यति शिरो दन्तान् दशत्याध्मातकन्धरः", text: "utpiṇḍitākṣaḥ śvasiti phenaṃ vamati kampate āvidhyati śiro dantān daśatyādhmātakandharaḥ" },
      { type: "verse", number: "12", sanskrit: "परितो विक्षिपत्यङ्गं विषमं विनताङ्गुलिः रूक्षश्यावारुणाक्षित्वङ्नखास्यः कृष्णमीक्षते चपलं परुषं रूपं विरूपं विकृताननम्", text: "parito vikṣipatyaṅgaṃ viṣamaṃ vinatāṅguliḥ rūkṣaśyāvāruṇākṣitvaṅnakhāsyaḥ kṛṣṇamīkṣate capalaṃ paruṣaṃ rūpaṃ virūpaṃ vikṛtānanam" },
      { type: "verse", number: "13", sanskrit: "अपस्मरति पित्तेन मुहुः संज्ञां च विन्दति पीतफेनाक्षिवक्त्रत्वगास्फालयति मेदिनीम् भैरवादीप्तरुषितरूपदर्शी तृषान्वितः", text: "apasmarati pittena muhuḥ saṃjñāṃ ca vindati pītaphenākṣivaktratvagāsphālayati medinīm bhairavādīptaruṣitarūpadarśī tṛṣānvitaḥ" },
      { type: "verse", number: "14", sanskrit: "कफाच्चिरेण ग्रहणं चिरेणैव विबोधनम् शुक्लाभरूपदर्शित्वं सर्वलिङ्गं तु वर्जयेत्", text: "kaphāccireṇa grahaṇaṃ cireṇaiva vibodhanam śuklābharūpadarśitvaṃ sarvaliṅgaṃ tu varjayet" },
      { type: "verse", number: "15", sanskrit: "अथावृतानां धीचित्तहृद्खानां प्राक्प्रबोधनम् तीक्ष्णैः कुर्यादपस्मारे कर्मभिर्वमनादिभिः", text: "athāvṛtānāṃ dhīcittahṛdkhānāṃ prākprabodhanam tīkṣṇaiḥ kuryādapasmāre karmabhirvamanādibhiḥ" },
      { type: "verse", number: "16", sanskrit: "वातिकं बस्तिभूयिष्ठैः पैत्तं प्रायो विरेचनैः श्लैष्मिकं वमनप्रायैरपस्मारमुपाचरेत्", text: "vātikaṃ bastibhūyiṣṭhaiḥ paittaṃ prāyo virecanaiḥ ślaiṣmikaṃ vamanaprāyairapasmāramupācaret" },
      { type: "verse", number: "17", sanskrit: "वमनं मदनं लम्बा विशालारिष्टकौटजम् रेको मूत्रत्रिवृच्छ्यामा द्रवन्ती सप्तला स्नुही", text: "vamanaṃ madanaṃ lambā viśālāriṣṭakauṭajam reko mūtratrivṛcchyāmā dravantī saptalā snuhī" },
      { type: "verse", number: "18", sanskrit: "दशमूलबलारास्नासरलामरदारुभिः यवकोलकुलत्थैश्च समूत्रक्षारसैन्धवैः आस्थापनं प्रयुञ्जीत हिङ्गुस्नेहसमन्वितैः", text: "daśamūlabalārāsnāsaralāmaradārubhiḥ yavakolakulatthaiśca samūtrakṣārasaindhavaiḥ āsthāpanaṃ prayuñjīta hiṅgusnehasamanvitaiḥ" },
      { type: "verse", number: "19", sanskrit: "एभिरन्यैश्च वातघ्नैः कटुतैलं प्रसाधितम् वातापस्मारशमनं नस्याभ्यङ्गानुवासनैः", text: "ebhiranyaiśca vātaghnaiḥ kaṭutailaṃ prasādhitam vātāpasmāraśamanaṃ nasyābhyaṅgānuvāsanaiḥ" },
      { type: "verse", number: "20", sanskrit: "सर्वतः सुविशुद्धस्य सम्यगाश्वासितस्य च अपस्मारविमोक्षार्थं योगान् संशमनान् शृणु", text: "sarvataḥ suviśuddhasya samyagāśvāsitasya ca apasmāravimokṣārthaṃ yogān saṃśamanān śṛṇu" },
      { type: "verse", number: "21", sanskrit: "गोमयस्वरसक्षीरदधिमूत्रैः शृतं हविः अपस्मारज्वरोन्मादकामलान्तकरं पिबेत्", text: "gomayasvarasakṣīradadhimūtraiḥ śṛtaṃ haviḥ apasmārajvaronmādakāmalāntakaraṃ pibet" },
      { type: "verse", number: "22", sanskrit: "द्विपञ्चमूलत्रिफलाद्विनिशाकुटजत्वचः सप्तपर्णमपामार्गं नीलिनीं कटुरोहिणीम्", text: "dvipañcamūlatriphalādviniśākuṭajatvacaḥ saptaparṇamapāmārgaṃ nīlinīṃ kaṭurohiṇīm" },
      { type: "verse", number: "23", sanskrit: "शम्याकपुष्करजटाफल्गुमूलदुरालभाः द्विपलाःसलिलद्रोणे पक्त्वा पादावशेषिते", text: "śamyākapuṣkarajaṭāphalgumūladurālabhāḥ dvipalāḥsaliladroṇe paktvā pādāvaśeṣite" },
      { type: "verse", number: "24", sanskrit: "भार्ङ्गीपाठाढकीकुम्भनिकुम्भव्योषरोहिषैः मूर्वाभूतीकाभूनिम्बश्रेयसीसारिवाद्वयैः", text: "bhārṅgīpāṭhāḍhakīkumbhanikumbhavyoṣarohiṣaiḥ mūrvābhūtīkābhūnimbaśreyasīsārivādvayaiḥ" },
      { type: "verse", number: "25", sanskrit: "मदयन्त्यग्निनिचुलैरक्षांशैः सर्पिषः पचेत् प्रस्थं तद्वद्द्रवैः पूर्वैः पञ्चगव्यमिदं महत्", text: "madayantyagniniculairakṣāṃśaiḥ sarpiṣaḥ pacet prasthaṃ tadvaddravaiḥ pūrvaiḥ pañcagavyamidaṃ mahat" },
      { type: "verse", number: "26", sanskrit: "ज्वरापस्मारजठरभगन्दरहरं परम् शोफार्शः कामलापाण्डुगुल्मकासग्रहापहम्", text: "jvarāpasmārajaṭharabhagandaraharaṃ param śophārśaḥ kāmalāpāṇḍugulmakāsagrahāpaham" },
      { type: "verse", number: "27", sanskrit: "शिरीषपुष्पपत्रत्वक्सारमूलतुलाद्वयम् वरणैरण्डशम्याकदशमूलाटरूषकम्", text: "śirīṣapuṣpapatratvaksāramūlatulādvayam varaṇairaṇḍaśamyākadaśamūlāṭarūṣakam" },
      { type: "verse", number: "28", sanskrit: "शतावरीबलारास्नासुषवीपारिभद्रकम् मुरुङ्गीं वञ्चुलं दन्तीं ककुभं सपुनर्नवम्", text: "śatāvarībalārāsnāsuṣavīpāribhadrakam muruṅgīṃ vañculaṃ dantīṃ kakubhaṃ sapunarnavam" },
      { type: "verse", number: "29", sanskrit: "रोहिषस्य जटां पुष्पं करघाटमयूरकम् शतार्धांशं पृथग्द्राक्षालाक्षामिसिवरायवान्", text: "rohiṣasya jaṭāṃ puṣpaṃ karaghāṭamayūrakam śatārdhāṃśaṃ pṛthagdrākṣālākṣāmisivarāyavān" },
      { type: "verse", number: "30", sanskrit: "सकोलान् सकुलत्थांश्च पृथगर्धाढकोन्मितान् द्विशतं पिशितात् गव्यात् छागाद्वा तत्पचेदपाम्", text: "sakolān sakulatthāṃśca pṛthagardhāḍhakonmitān dviśataṃ piśitāt gavyāt chāgādvā tatpacedapām" },
      { type: "verse", number: "31", sanskrit: "द्रोणैर्द्वात्रिंशताष्टांशशेषेण च विपाचयेत् तैलद्रोणं दधिवहे श्लक्ष्णपिष्टैश्च पालिकैः", text: "droṇairdvātriṃśatāṣṭāṃśaśeṣeṇa ca vipācayet tailadroṇaṃ dadhivahe ślakṣṇapiṣṭaiśca pālikaiḥ" },
      { type: "verse", number: "32", sanskrit: "पाठासमङ्गासुषवीद्विनिशाचन्दनद्वयैः एलाजलोत्पलबलाश्वदंष्ट्रासारिवाघनैः", text: "pāṭhāsamaṅgāsuṣavīdviniśācandanadvayaiḥ elājalotpalabalāśvadaṃṣṭrāsārivāghanaiḥ" },
      { type: "verse", number: "33", sanskrit: "मञ्जिष्ठाकुष्ठमधुकलोध्ररास्नाकुटन्नटैः शठीशिरीषकुसुमनतनागामराह्वयैः", text: "mañjiṣṭhākuṣṭhamadhukalodhrarāsnākuṭannaṭaiḥ śaṭhīśirīṣakusumanatanāgāmarāhvayaiḥ" },
      { type: "verse", number: "34", sanskrit: "वराङ्गजोङ्गपत्तङ्गविडङ्गैः सप्रियङ्गुभिः मुरुड्गीपत्रनलदसेव्यकुन्दनखद्वयैः", text: "varāṅgajoṅgapattaṅgaviḍaṅgaiḥ sapriyaṅgubhiḥ muruḍgīpatranaladasevyakundanakhadvayaiḥ" },
      { type: "verse", number: "35", sanskrit: "तिलपर्ण्या च तत्पानबस्त्यभ्यञ्जननावनैः अपस्मारग्रहोन्मादान् सशोषविषमज्वरान्", text: "tilaparṇyā ca tatpānabastyabhyañjananāvanaiḥ apasmāragrahonmādān saśoṣaviṣamajvarān" },
      { type: "verse", number: "36", sanskrit: "योनिशुक्रामयान् गुल्मं प्रमेहं पाण्डुतां मदम् वातशोणितवीसर्पपक्षाघातार्दितादिकान्", text: "yoniśukrāmayān gulmaṃ pramehaṃ pāṇḍutāṃ madam vātaśoṇitavīsarpapakṣāghātārditādikān" },
      { type: "verse", number: "37", sanskrit: "सर्वान् मारुतजान्रोगान्विशेषाद्विषवातजान् निहन्ति कार्मणं कृत्यां मूलदंष्ट्राविषं गरम् रसायनानां प्रवरं मेध्यं वाजीकरं परम्", text: "sarvān mārutajānrogānviśeṣādviṣavātajān nihanti kārmaṇaṃ kṛtyāṃ mūladaṃṣṭrāviṣaṃ garam rasāyanānāṃ pravaraṃ medhyaṃ vājīkaraṃ param" },
      { type: "verse", number: "38", sanskrit: "ब्राह्मीरसवचाकुष्ठशङ्खपुष्पीशृतं घृतम् पुराणं मेध्यमुन्मादालक्ष्म्यपस्मारपाप्मजित्", text: "brāhmīrasavacākuṣṭhaśaṅkhapuṣpīśṛtaṃ ghṛtam purāṇaṃ medhyamunmādālakṣmyapasmārapāpmajit" },
      { type: "verse", number: "39", sanskrit: "तैलप्रस्थं घृतप्रस्थं जीवनीयैः पलोन्मितैः क्षीरद्रोणे पचेत् सिद्धमपस्मारविमोक्षणम्", text: "tailaprasthaṃ ghṛtaprasthaṃ jīvanīyaiḥ palonmitaiḥ kṣīradroṇe pacet siddhamapasmāravimokṣaṇam" },
      { type: "verse", number: "40", sanskrit: "कंसे क्षीरेक्षुरसयोः काश्मर्ये ऽष्टगुणे रसे कार्षिकैर्जीवनीयैश्च सर्पिःप्रस्थं विपाचयेत् वातपित्तोद्भवं क्षिप्रमपस्मारं निहन्ति तत्", text: "kaṃse kṣīrekṣurasayoḥ kāśmarye 'ṣṭaguṇe rase kārṣikairjīvanīyaiśca sarpiḥprasthaṃ vipācayet vātapittodbhavaṃ kṣipramapasmāraṃ nihanti tat" },
      { type: "verse", number: "41", sanskrit: "तद्वत् काशाविदारीक्षुकुशक्वाथशृतं पयः", text: "tadvat kāśāvidārīkṣukuśakvāthaśṛtaṃ payaḥ" },
      { type: "verse", number: "42", sanskrit: "मधुकद्विपले कल्के द्रोणे चामलकीरसात् सिद्धं सिद्धो घृतप्रस्थः पित्तापस्मारभेषजम्", text: "madhukadvipale kalke droṇe cāmalakīrasāt siddhaṃ siddho ghṛtaprasthaḥ pittāpasmārabheṣajam" },
      { type: "verse", number: "43", sanskrit: "कूष्माण्डस्वरसे सर्पिरष्टादशगुणे शृतम् यष्टीकल्कमपस्मारहरं धीवाक्स्वरप्रदम्", text: "kūṣmāṇḍasvarase sarpiraṣṭādaśaguṇe śṛtam yaṣṭīkalkamapasmāraharaṃ dhīvāksvarapradam" },
      { type: "verse", number: "44", sanskrit: "कपिलानां गवां पित्तं नावनं परमं हितम् श्वशृगालविडालानां सिंहादीनां च पूजितम्", text: "kapilānāṃ gavāṃ pittaṃ nāvanaṃ paramaṃ hitam śvaśṛgālaviḍālānāṃ siṃhādīnāṃ ca pūjitam" },
      { type: "verse", number: "45", sanskrit: "गोधानकुलनागानां पृषतर्क्षगवामपि पित्तेषु साधितं तैलं नस्ये ऽभ्यङ्गे च शस्यते", text: "godhānakulanāgānāṃ pṛṣatarkṣagavāmapi pitteṣu sādhitaṃ tailaṃ nasye 'bhyaṅge ca śasyate" },
      { type: "verse", number: "46", sanskrit: "त्रिफलाव्योषपीतद्रुयवक्षारफणिज्जकैः श्र्याह्वापामार्गकारञ्जबीजैस्तैलं प्रसाधितम् बस्तमूत्रे हितं नस्यं चूर्णं वाध्मापयेत् भिषक्", text: "triphalāvyoṣapītadruyavakṣāraphaṇijjakaiḥ śryāhvāpāmārgakārañjabījaistailaṃ prasādhitam bastamūtre hitaṃ nasyaṃ cūrṇaṃ vādhmāpayet bhiṣak" },
      { type: "verse", number: "47", sanskrit: "वृश्चिकालीबलाकुष्ठभाङ्र्जीलवणपञ्चकम् कायस्थां शारदां मुद्गमुशीरं जलदं यवान्", text: "vṛścikālībalākuṣṭhabhāṅrjīlavaṇapañcakam kāyasthāṃ śāradāṃ mudgamuśīraṃ jaladaṃ yavān" },
      { type: "verse", number: "48", sanskrit: "व्योषं च बस्तमूत्रेण पिष्ट्वा वर्तीं प्रकल्पयेत् अपस्मारगरोन्मादसर्पदष्टविषाशिते", text: "vyoṣaṃ ca bastamūtreṇa piṣṭvā vartīṃ prakalpayet apasmāragaronmādasarpadaṣṭaviṣāśite" },
      { type: "verse", number: "49", sanskrit: "मुस्तावयस्थात्रिफलाकायस्थाहिङ्गुशाद्वलैः व्योषमाषयवैर्मूत्रैर्बस्तमेषर्षभोद्भवैः", text: "mustāvayasthātriphalākāyasthāhiṅguśādvalaiḥ vyoṣamāṣayavairmūtrairbastameṣarṣabhodbhavaiḥ" },
      { type: "verse", number: "50", sanskrit: "हन्ति वर्तिरपस्मारकिलासविषमज्वरान् पुष्योद्घृतं शुनः पित्तमपस्मारघ्नमञ्जनम् तदेव सर्पिषा युक्तं धूपनं परमं हितम्", text: "hanti vartirapasmārakilāsaviṣamajvarān puṣyodghṛtaṃ śunaḥ pittamapasmāraghnamañjanam tadeva sarpiṣā yuktaṃ dhūpanaṃ paramaṃ hitam" },
      { type: "verse", number: "51", sanskrit: "कटभीनिम्बकट्वङ्गमधुशिग्रुत्वचां रसे सिद्धं मूत्रसमं तैलमभ्यङ्गार्थं प्रशस्यते", text: "kaṭabhīnimbakaṭvaṅgamadhuśigrutvacāṃ rase siddhaṃ mūtrasamaṃ tailamabhyaṅgārthaṃ praśasyate" },
      { type: "verse", number: "52", sanskrit: "पलङ्कषावचापथ्यावृश्चिकाल्यर्कसर्षपैः जटिलापूतनाकेशीनाकुलीहिङ्गुचोरकैः", text: "palaṅkaṣāvacāpathyāvṛścikālyarkasarṣapaiḥ jaṭilāpūtanākeśīnākulīhiṅgucorakaiḥ" },
      { type: "verse", number: "53", sanskrit: "लशुनातिरसाच्छत्राकुष्ठैर्विड्भिश्च पक्षिणाम् मांसाशिनां यथालाभं बस्तमूत्रे विपाचितम् तैलमभ्यञ्जनं कार्यं तैश्च धूपनलेपनम्", text: "laśunātirasācchatrākuṣṭhairviḍbhiśca pakṣiṇām māṃsāśināṃ yathālābhaṃ bastamūtre vipācitam tailamabhyañjanaṃ kāryaṃ taiśca dhūpanalepanam" },
      { type: "verse", number: "54", sanskrit: "नकुलोलूकमार्जारगृध्रकीटाहिकाकजैः तुण्डैः पक्षैः पुरीषैश्च धूपमस्य प्रयोजयेत्", text: "nakulolūkamārjāragṛdhrakīṭāhikākajaiḥ tuṇḍaiḥ pakṣaiḥ purīṣaiśca dhūpamasya prayojayet" },
      { type: "verse", number: "55", sanskrit: "काकोलीशिग्रुलवणहिङ्गुशिवाटिकाः कैडर्यं चन्दनं कृष्णां काकनासां ससर्षपाम्", text: "kākolīśigrulavaṇahiṅguśivāṭikāḥ kaiḍaryaṃ candanaṃ kṛṣṇāṃ kākanāsāṃ sasarṣapām" },
      { type: "verse", number: "56", sanskrit: "शुनः स्कन्धाक्षिनखरान् पर्शुकांश्चेति पेषयेत् बस्तमूत्रेण पुष्यर्क्षे तैर्दिह्याद्धूपयेच्च तैः", text: "śunaḥ skandhākṣinakharān parśukāṃśceti peṣayet bastamūtreṇa puṣyarkṣe tairdihyāddhūpayecca taiḥ" },
      { type: "verse", number: "57", sanskrit: "गोपुच्छलोमभिर्दग्धैरथवा बस्तरोमभिः खरास्थिभिर्हस्तिनखैस्तद्वद्वा मूत्रकल्कितैः उद्वर्तनं सदा कुर्याच्छृतैश्च परिषेचनम्", text: "gopucchalomabhirdagdhairathavā bastaromabhiḥ kharāsthibhirhastinakhaistadvadvā mūtrakalkitaiḥ udvartanaṃ sadā kuryācchṛtaiśca pariṣecanam" },
      { type: "verse", number: "58", sanskrit: "आभिः क्रियाभिः सिद्धाभिर्हृदयं सम्प्रभुच्यते स्रोतांसि चास्य शुध्यन्ति स्मृतिं संज्ञां च विन्दति", text: "ābhiḥ kriyābhiḥ siddhābhirhṛdayaṃ samprabhucyate srotāṃsi cāsya śudhyanti smṛtiṃ saṃjñāṃ ca vindati" },
      { type: "verse", number: "59", sanskrit: "भूतानुबन्धेपस्मारे दोषलिङ्गाधिकाकृतौ युञ्ज्याद्यथास्वं भूतोक्तां क्रियां दैवव्यपाश्रयाम्", text: "bhūtānubandhepasmāre doṣaliṅgādhikākṛtau yuñjyādyathāsvaṃ bhūtoktāṃ kriyāṃ daivavyapāśrayām" },
      { type: "verse", number: "60", sanskrit: "शीलयेत्तैललशुनं पयसा वा शतावरीम् ब्राह्मीरसं कुष्ठरसं वचां वा मधुसंयुताम्", text: "śīlayettailalaśunaṃ payasā vā śatāvarīm brāhmīrasaṃ kuṣṭharasaṃ vacāṃ vā madhusaṃyutām" },
      { type: "verse", number: "61", sanskrit: "समं क्रुद्धैरपस्मारो दोषैः शारीरमानसैः यज्जायते यतश्चैष महामर्मसमाश्रयः", text: "samaṃ kruddhairapasmāro doṣaiḥ śārīramānasaiḥ yajjāyate yataścaiṣa mahāmarmasamāśrayaḥ" },
      { type: "verse", number: "62", sanskrit: "तस्माद्रसायनैरेनं दुश्चिकित्स्यमुपाचरेत् तदार्तं चाग्नितोयादेर्विषमात् पालयेत् सदा", text: "tasmādrasāyanairenaṃ duścikitsyamupācaret tadārtaṃ cāgnitoyāderviṣamāt pālayet sadā" },
      { type: "verse", number: "63", sanskrit: "मुक्तं मनोविकारेण त्वमित्थं कृतवानिति न ब्रूयाद्विषयैरिष्टैः क्लिष्टं चेतो ऽस्य बृंहयेत्", text: "muktaṃ manovikāreṇa tvamitthaṃ kṛtavāniti na brūyādviṣayairiṣṭaiḥ kliṣṭaṃ ceto 'sya bṛṃhayet" },
      { type: "verse", number: "64", sanskrit: "ग्रहोपश्लिष्टदेहानां विभ्रान्तस्मृतिचेतसाम् महास्नेहं प्रशंसन्ति पानाभ्यञ्जनबस्तिषु", text: "grahopaśliṣṭadehānāṃ vibhrāntasmṛticetasām mahāsnehaṃ praśaṃsanti pānābhyañjanabastiṣu" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 11,
    lang: "sa",
    content: [
      { type: "heading", heading: "Данта рога — болезни зубов" },
      { type: "text", text: "Глава 11 Уттара стханы — «Данта рога» — посвящена специализированному разделу: болезни зубов. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो वर्त्मरोगविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vartmarogavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सर्वरोगनिदानोक्तैरहितैः कुपिता मलाः अचक्षुष्यैर्विशेषेण प्रायः पित्तानुसारिणः", text: "sarvaroganidānoktairahitaiḥ kupitā malāḥ acakṣuṣyairviśeṣeṇa prāyaḥ pittānusāriṇaḥ" },
      { type: "verse", number: "3", sanskrit: "सिराभिरूर्ध्वं प्रसृता नेत्रावयवमाश्रिताः वर्त्मसन्धिं सितं कृष्णं दृष्टिं वा सर्वमक्षि वा", text: "sirābhirūrdhvaṃ prasṛtā netrāvayavamāśritāḥ vartmasandhiṃ sitaṃ kṛṣṇaṃ dṛṣṭiṃ vā sarvamakṣi vā" },
      { type: "verse", number: "4", sanskrit: "रोगान् कुर्युः चलस्तत्र प्राप्य वर्त्माश्रयाः सिराः सुप्तोत्थितस्य कुरुते वर्त्मस्तम्भं सवेदनम्", text: "rogān kuryuḥ calastatra prāpya vartmāśrayāḥ sirāḥ suptotthitasya kurute vartmastambhaṃ savedanam" },
      { type: "verse", number: "5", sanskrit: "पांसुपूर्णाभनेत्रत्वं कृच्छ्रोन्मीलनमश्रु च विमर्दनात् स्याच्च शमः कृच्छ्रोन्मीलं वदन्ति तमू", text: "pāṃsupūrṇābhanetratvaṃ kṛcchronmīlanamaśru ca vimardanāt syācca śamaḥ kṛcchronmīlaṃ vadanti tamū" },
      { type: "verse", number: "6", sanskrit: "चालयन्वर्त्मनी वायुर्निमेषोन्मेषणं मुहुः करोत्यरुङ्निमेषो ऽसौ वर्त्म यत्तु निमील्यते", text: "cālayanvartmanī vāyurnimeṣonmeṣaṇaṃ muhuḥ karotyaruṅnimeṣo 'sau vartma yattu nimīlyate" },
      { type: "verse", number: "7", sanskrit: "विमुक्तसन्धि निश्चेष्टं हीनं वातहतं हि तत्", text: "vimuktasandhi niśceṣṭaṃ hīnaṃ vātahataṃ hi tat" },
      { type: "verse", number: "8", sanskrit: "कृष्णाः पित्तेन बह्व्योन्तर्वर्त्म कुम्भीकबीजवत् आध्मायन्ते पुनर्भिन्नाः पिटकाः कुम्भिसंज्ञिकाः", text: "kṛṣṇāḥ pittena bahvyontarvartma kumbhīkabījavat ādhmāyante punarbhinnāḥ piṭakāḥ kumbhisaṃjñikāḥ" },
      { type: "verse", number: "9", sanskrit: "सदाहक्लेदनिस्तोदं रक्ताभं स्पर्शनाक्षमम् पित्तेन जायते वर्त्म पित्तोत्क्लिष्टमुशन्ति तत्", text: "sadāhakledanistodaṃ raktābhaṃ sparśanākṣamam pittena jāyate vartma pittotkliṣṭamuśanti tat" },
      { type: "verse", number: "10", sanskrit: "करोति कण्डूं दाहं च पित्तं पक्ष्मान्तमाश्रितम् पक्ष्मणां शतनं चानु पक्ष्मशातं वदन्ति तम्", text: "karoti kaṇḍūṃ dāhaṃ ca pittaṃ pakṣmāntamāśritam pakṣmaṇāṃ śatanaṃ cānu pakṣmaśātaṃ vadanti tam" },
      { type: "verse", number: "11", sanskrit: "पोथक्यः पिटकाः श्वेताः सर्षपाभा घनाः क्कफात् शोफोपदेहरुक्कण्डूपिच्छिलास्रसमन्विताः", text: "pothakyaḥ piṭakāḥ śvetāḥ sarṣapābhā ghanāḥ kkaphāt śophopadeharukkaṇḍūpicchilāsrasamanvitāḥ" },
      { type: "verse", number: "12", sanskrit: "कफोत्क्लिष्टं भवेद्वर्त्म स्तम्भक्लेदोपदेहवत्", text: "kaphotkliṣṭaṃ bhavedvartma stambhakledopadehavat" },
      { type: "verse", number: "13", sanskrit: "ग्रन्थिः पाण्डुररुक्पाकः कण्डूमान्कठिनःकफात् कोलमात्रः स लगणः किञ्चिदल्पस्ततो ऽथवा", text: "granthiḥ pāṇḍurarukpākaḥ kaṇḍūmānkaṭhinaḥkaphāt kolamātraḥ sa lagaṇaḥ kiñcidalpastato 'thavā" },
      { type: "verse", number: "14", sanskrit: "रक्ता रक्तेन पिटका तत्तुल्यपिटकाचिता", text: "raktā raktena piṭakā tattulyapiṭakācitā" },
      { type: "verse", number: "15", sanskrit: "उत्सङ्गाख्या तथोत्क्लिष्टं राजिमत् स्पर्शनाक्षमम्", text: "utsaṅgākhyā tathotkliṣṭaṃ rājimat sparśanākṣamam" },
      { type: "verse", number: "16", sanskrit: "अर्शो ऽधिमांसं वर्त्मान्तः स्तब्धं स्निग्धं सदाहरुक् रक्तं रक्तेन तत्स्रावि च्छिन्नं च्छिन्नं च वर्धते", text: "arśo 'dhimāṃsaṃ vartmāntaḥ stabdhaṃ snigdhaṃ sadāharuk raktaṃ raktena tatsrāvi cchinnaṃ cchinnaṃ ca vardhate" },
      { type: "verse", number: "17", sanskrit: "मध्ये वा वर्त्मनो ऽन्ते वा कण्डूषारुग्वती स्थिरा मुद्गमात्रासृजा ताम्रा पिटकाञ्जननामिका", text: "madhye vā vartmano 'nte vā kaṇḍūṣārugvatī sthirā mudgamātrāsṛjā tāmrā piṭAkāñjananāmikā" },
      { type: "verse", number: "18", sanskrit: "दोषैर्वर्त्म बहिः शूनं यदन्तः सूक्ष्मखाचितम् सस्रावमन्तरुदकं बिसाभं बिसवर्त्म तत्", text: "doṣairvartma bahiḥ śūnaṃ yadantaḥ sūkṣmakhācitam sasrāvamantarudakaṃ bisābhaṃ bisavartma tat" },
      { type: "verse", number: "19", sanskrit: "यद्वर्त्मोत्क्लिष्टमुत्क्लिष्टमकस्मान्म्लानतामियात् रक्तदोषत्रयोत्क्लेशात् भवत्युत्क्लिष्टवर्त्म तत्", text: "yadvartmotkliṣṭamutkliṣṭamakasmānmlānatāmiyāt raktadoṣatrayotkleśāt bhavatyutkliṣṭavartma tat" },
      { type: "verse", number: "20", sanskrit: "श्याववर्त्म मलैः सास्रैः श्यावं रुक्क्लेदशोफवत्", text: "śyāvavartma malaiḥ sāsraiḥ śyāvaṃ rukkledaśophavat" },
      { type: "verse", number: "21", sanskrit: "श्लिष्टाख्यं वर्त्मनी श्लिष्टे कण्डूश्वयथुरागिणी", text: "śliṣṭākhyaṃ vartmanī śliṣṭe kaṇḍūśvayathurāgiṇī" },
      { type: "verse", number: "22", sanskrit: "वर्त्मान्तः पिटका रूक्षाः कर्कशाः सिकतोपमाः", text: "vartmāntaḥ piṭakā rūkṣāḥ karkaśāḥ sikatopamāḥ" },
      { type: "verse", number: "23", sanskrit: "सिकतावर्त्मकृष्णं तु कर्दमं कर्दमोपमम्", text: "sikatāvartmakṛṣṇaṃ tu kardamaṃ kardamopamam" },
      { type: "verse", number: "24", sanskrit: "बहलं बहलैर्मांसैः सवर्णैश्चीयते समैः", text: "bahalaṃ bahalairmāṃsaiḥ savarṇaiścīyate samaiḥ" },
      { type: "verse", number: "25", sanskrit: "कुकूणकः शिशोरेव दन्तोत्पत्तिनिमित्तजः स्यात्तेन शिशुरुच्छूनताम्राक्षो वीक्षणाक्षमः सवर्त्मशूलपैच्छिल्यकर्णनासाक्षिमर्दनः", text: "kukūṇakaḥ śiśoreva dantotpattinimittajaḥ syāttena śiśurucchūnatāmrākṣo vīkṣaṇākṣamaḥ savartmaśūlapaicchilyakarṇanāsākṣimardanaḥ" },
      { type: "verse", number: "26", sanskrit: "पक्ष्मोपरोधे सङ्कोचो वर्त्मनोर्जायते ततः खरतान्तर्मुखत्वं च रोम्णामन्यानि वा पुनः", text: "pakṣmoparodhe saṅkoco vartmanorjāyate tataḥ kharatāntarmukhatvaṃ ca romṇāmanyāni vā punaḥ" },
      { type: "verse", number: "27", sanskrit: "कण्टकैरिव तीक्ष्णाग्रैर्घृष्टं तैरक्षि शूयते ऊष्यते चानिलादिद्विडल्पाहं शान्तिरुद्धृतैः", text: "kaṇṭakairiva tīkṣṇāgrairghṛṣṭaṃ tairakṣi śūyate ūṣyate cānilādidviḍalpāhaṃ śāntiruddhṛtaiḥ" },
      { type: "verse", number: "28", sanskrit: "कनीनके बहिर्वर्त्म कठिनो ग्रन्थिरुन्नतः ताम्रः पक्वोस्रपूयस्रुदलज्याध्मायते मुहुः", text: "kanīnake bahirvartma kaṭhino granthirunnataḥ tāmraḥ pakvosrapūyasrudalajyādhmāyate muhuḥ" },
      { type: "verse", number: "29", sanskrit: "वर्त्मान्तर्मांसपिण्डाभः श्वयथुर्ग्रथितो ऽरुजः सास्रैः स्यादर्बुदो दोषैर्विषमो बाह्यतश्चलः", text: "vartmāntarmāṃsapiṇḍābhaḥ śvayathurgrathito 'rujaḥ sāsraiḥ syādarbudo doṣairviṣamo bāhyataścalaḥ" },
      { type: "verse", number: "30", sanskrit: "चतुर्विंशतिरित्येते व्याधयो वर्त्मसंश्रयाः", text: "caturviṃśatirityete vyādhayo vartmasaṃśrayāḥ" },
      { type: "verse", number: "31", sanskrit: "आद्यो ऽत्रभेषजैः साध्यो द्वौ ततोर्शश्च वर्जयेत् पक्ष्मोपरोधो याप्यः स्याच्छेषाञ्छस्त्रौषधैर्जयेत्", text: "ādyo 'trabheṣajaiḥ sādhyo dvau tatorśaśca varjayet pakṣmoparodho yāpyaḥ syāccheṣāñchastrauṣadhairjayet" },
      { type: "verse", number: "32", sanskrit: "कुट्टयेत् पक्ष्माशतनं छिन्द्यात्तेष्वपि चार्बुदम् भिन्द्याल्लगणकुम्भीकाबिसोत्सङ्गाञ्जनालजीः", text: "kuṭṭayet pakṣmāśatanaṃ chindyātteṣvapi cārbudam bhindyāllagaṇakumbhīkābisotsaṅgāñjanālajīḥ" },
      { type: "verse", number: "33", sanskrit: "पोथकीश्यावसिकताश्लिष्टोत्क्लिष्टचतुष्टयम् सकर्दमं सबहलं विलिखेत् सुकुकूणकम्", text: "pothakīśyāvasikatāśliṣṭotkliṣṭacatuṣṭayam sakardamaṃ sabahalaṃ vilikhet sukukūṇakam" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 12,
    lang: "sa",
    content: [
      { type: "heading", heading: "Оштха рога — болезни губ" },
      { type: "text", text: "Глава 12 Уттара стханы — «Оштха рога» — посвящена специализированному разделу: болезни губ. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो वर्त्मरोगप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vartmarogapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "कृछ्रबोधे पुराणं घृतं द्राक्षाकल्कक्वाथसिद्धं शर्करावचूर्णितं रात्रौ पाययेत् स्निग्धांश्च नस्यधूमाञ्जनतर्पणपुटपाकान् प्रयोजयेत् वातहरद्रव्यकल्पितांश्च बस्तीन् क्षीरस्विन्नैरेरण्डपल्लवैः स्वेदं च वर्त्मनाम्", text: "kṛchrabodhe purāṇaṃ ghṛtaṃ drākṣākalkakvāthasiddhaṃ śarkarāvacūrṇitaṃ rātrau pāyayet snigdhāṃśca nasyadhūmāñjanatarpaṇapuṭapākān prayojayet vātaharadravyakalpitāṃśca bastīn kṣīrasvinnaireraṇḍapallavaiḥ svedaṃ ca vartmanām" },
      { type: "verse", number: "3", sanskrit: "एवमशान्तौ मुद्गमात्रान्तरैः पदैरग्निना त्वग्दाहं बिन्दुभिराचरेत् १अस्.उत्त्.१२.४ कुम्भीकापिटकासु वर्त्म लिखित्वा सैन्धवेनानुप्रतिसार्य पटोलामलकमधुकक्वाथेन सेचयेत् घृतेन च", text: "evamaśāntau mudgamātrāntaraiḥ padairagninā tvagdāhaṃ bindubhirācaret 1AS.Utt.12.4 kumbhīkāpiṭakāsu vartma likhitvā saindhavenānupratisārya paṭolāmalakamadhukakvāthena secayet ghṛtena ca" },
      { type: "verse", number: "5", sanskrit: "पित्तरक्तोक्लिष्टयोर्मधुरौषधसिद्धेन सर्पिषा स्निग्धस्य सिरां विध्येत् विरेचयेच्चैनं त्रिवृत्क्वाथवता त्रिफलाकल्केन त्रिफलाक्वाथयुक्तेन वा ब्राह्मीचूर्णेन चन्दनोशीरमधुकमृद्वीकापुनर्नवबृहतीमूलसिद्धं तैलं नावयेत् लिखिते च वर्त्मनि स्रुतरक्ते यष्ट्याह्वनिर्यूहेण प्रक्षालनम् चन्दनशृतं पयः परिषेकः शीतस्निग्धाश्च शिरोवक्त्रलेपाः", text: "pittaraktokliṣṭayormadhurauṣadhasiddhena sarpiṣā snigdhasya sirāṃ vidhyet virecayeccainaṃ trivṛtkvāthavatā triphalākalkena triphalākvāthayuktena vā brāhmīcūrṇena candanośīramadhukamṛdvīkāpunarnavabṛhatīmūlasiddhaṃ tailaṃ nāvayet likhite ca vartmani srutarakte yaṣṭyāhvaniryūheṇa prakṣālanam candanaśṛtaṃ payaḥ pariṣekaḥ śītasnigdhāśca śirovaktralepāḥ" },
      { type: "verse", number: "6", sanskrit: "पक्ष्मशाते रोमकूपान् सूच्यग्रेण कुट्टयेज्जलौकोभिर्वा ग्राहयेत् पयसेक्षुरसेन वा वमनम् स्वादुशीतस्कन्धसाधितं सर्पिर्नावनम् काकजङ्घा रोहित मत्स्यमांसं च काकशोणितभावितमन्तर्धूमं दग्धं चूर्णाञ्जनं कुर्यात्", text: "pakṣmaśāte romakūpān sūcyagreṇa kuṭṭAyejjalaukobhirvā grāhayet payasekṣurasena vā vamanam svāduśītaskandhasādhitaṃ sarpirnāvanam kākajaṅghā rohita matsyamāṃsaṃ ca kākaśoṇitabhāvitamantardhūmaṃ dagdhaṃ cūrṇāñjanaṃ kuryāt" },
      { type: "verse", number: "7", sanskrit: "सञ्चूर्ण्य पुष्पकासीसं भावयेत् सुरसारसैः ताम्रे दशाहं परमं पक्ष्मशाते तदञ्जनम्", text: "sañcūrṇya puṣpakāsīsaṃ bhāvayet surasārasaiḥ tāmre daśāhaṃ paramaṃ pakṣmaśāte tadañjanam" },
      { type: "verse", number: "8", sanskrit: "पोथकीर्विलिख्य शुण्ठीसैन्धवमागधिकाचूर्णैः प्रतिसार्य प्रक्षाल्य चोष्णाम्भसा खदिरसाराढकीशिग्रुपत्रकषायेण सेचयेत् ततश्चाम्रजम्बूप्रवालक्वाथेनाश्च्योतनम् त्रिफलाखदिरसारोदकेन वा मधुसंयुक्तेन विडङ्गलाक्षादार्वीत्वग्गैरिकालमनोह्वाचूर्णः क्षौद्रान्वितो ऽञ्जनम्", text: "pothakīrvilikhya śuṇṭhīsaindhavamāgadhikācūrṇaiḥ pratisārya prakṣālya coṣṇāmbhasā khadirasārāḍhakīśigrupatrakaṣāyeṇa secayet tataścāmrajambūpravālakvāthenāścyotanam triphalākhadirasārodakena vā madhusaṃyuktena viḍaṅgalākṣādārvītvaggairikālamanohvācūrṇaḥ kṣaudrānvito 'ñjanam" },
      { type: "verse", number: "9", sanskrit: "एवमप्यनुपशमे जलौकसो योजयेत् पुनः पुनर्वा लेखयेत् परिषेकं च त्रिफलामधुकद्विहरिद्राकषायेण मधुयुक्तेन कुर्यात् मुस्तशर्कराकपित्थपत्राम्बुना वा", text: "evamapyanupaśame jalaukaso yojayet punaḥ punarvā lekhayet pariṣekaṃ ca triphalāmadhukadviharidrākaṣāyeṇa madhuyuktena kuryāt mustaśarkarākapitthapatrāmbunā vā" },
      { type: "verse", number: "10", sanskrit: "कफोत्क्लिष्टं वर्त्म लिखित्वा सैन्धवकासीसपिप्पलीमनश्शिलारसाञ्जनचूर्णैर्मधुमद्भिः प्रतिसारयेत् कफघ्नानि च वमनधूमनावनाञ्जनान्याहारविधिश्च वर्त्मापक्लेदे कासीसलवणसुमनोमुकुलरसाञ्जनैर्वर्तिरञ्जनम्", text: "kaphotkliṣṭaṃ vartma likhitvā saindhavakāsīsapippalīmanaśśilārasāñjanacūrṇairmadhumadbhiḥ pratisārayet kaphaghnāni ca vamanadhūmanāvanāñjanānyāhāravidhiśca vartmāpaklede kāsīsalavaṇasumanomukularasāñjanairvartirañjanam" },
      { type: "verse", number: "11", sanskrit: "लगणं कफोत्क्लिष्टवत् साधयेत् अशाम्यत्यग्निना दाहो वमनं विरेचनं च पिप्पलीमधुकनिम्बज्योतिष्मतीदेवदारुविडङ्गप्रियङ्गुत्रिफलाकुष्ठशताह्वासैधवैः सिद्धं तैलं नावयेत् तीक्ष्णावपीडाञ्जनकवलांश्च विदध्यादुष्णोपचारं च", text: "lagaṇaṃ kaphotkliṣṭavat sādhayet aśāmyatyagninā dāho vamanaṃ virecanaṃ ca pippalīmadhukanimbajyotiṣmatīdevadāruviḍaṅgapriyaṅgutriphalākuṣṭhaśatāhvāsaidhavaiḥ siddhaṃ tailaṃ nāvayet tīkṣṇāvapīḍāñjanakavalāṃśca vidadhyāduṣṇopacāraṃ ca" },
      { type: "verse", number: "12", sanskrit: "उत्सङ्गपिटकामञ्जननामिकां च भित्वा निष्पीड्य चोल्लिखितां तगरैलासैन्धवनेपालीचूर्णेन सक्षौद्रेण प्रतिसारयेत् हरिद्रामधुकपटोललोध्रः समाक्षिकः परिषेकः", text: "utsaṅgapiṭakāmañjananāmikāṃ ca bhitvā niṣpīḍya collikhitāṃ tagarailāsaindhavanepālīcūrṇena sakṣaudreṇa pratisārayet haridrāmadhukapaṭolalodhraḥ samākṣikaḥ pariṣekaḥ" },
      { type: "verse", number: "13", sanskrit: "बिसवर्त्मादिषु बहलवर्त्मान्तेषु सैधवं प्रतिसारणम् बिसश्लिष्टवर्त्मनोस्तथानुपशमे ऽग्निना क्षारेण वा दहनम्", text: "bisavartmādiṣu bahalavartmānteṣu saidhavaṃ pratisāraṇam bisaśliṣṭavartmanostathānupaśame 'gninā kṣāreṇa vā dahanam" },
      { type: "verse", number: "14", sanskrit: "कुकूणके निम्बपत्रत्रिफलाखदिरमूलकल्कविपक्वं सर्पिर्धात्रीं पाययित्वा सैन्धवसर्षपोपकुल्यायष्ट्याह्ववतोष्णाम्भसा वामयेत् पिप्पलीद्राक्षाभयानिर्यूहेण विरेचयेत् स्तनौ चास्या मागधिकामुस्ताद्विरजनःकल्केनालिप्योद्वर्तयेत् धूपयेच्च सघृतैः सिद्धार्थकः पाययेच्चैनां पटोलमुस्तमृद्वीकागुडूचीत्रिफलाकषायम्", text: "kukūṇake nimbapatratriphalākhadiramūlakalkavipakvaṃ sarpirdhātrīṃ pāyayitvā saindhavasarṣapopakulyāyaṣṭyāhvavatoṣṇāmbhasā vāmayet pippalīdrākṣābhayāniryūheṇa virecayet stanau cāsyā māgadhikāmustādvirajanaḥkalkenālipyodvartayet dhūpayecca saghṛtaiḥ siddhārthakaḥ pāyayeccaināṃ paṭolamustamṛdvīkāguḍūcītriphalākaṣāyam" },
      { type: "verse", number: "15", sanskrit: "बालस्य वर्त्मनी लिखित्वा मधुसैन्धवरसाञ्जनैः प्रतिसार्यामलक्यश्मन्तकजम्बूपल्लवक्वाथेन प्रक्षालयेत् जलौकोभिर्वा ग्राहयेत् वेदनायां तु कुष्ठगुडूचीकल्कोदकेन सगुडक्षौद्रेण परिषेको मूर्धानं चास्यकटुतैलेनाभ्यज्य पाठाकल्केन प्रलिप्यार्जुनबिल्वनिर्गुण्डीमार्कवतर्कारीसैर्यककार्पासीमालतीपत्रनिर्यूहेण सेचयेत्", text: "bālasya vartmanī likhitvā madhusaindhavarasāñjanaiḥ pratisāryāmalakyaśmantakajambūpallavakvāthena prakṣālayet jalaukobhirvā grāhayet vedanāyāṃ tu kuṣṭhaguḍūcīkalkodakena saguḍakṣaudreṇa pariṣeko mūrdhānaṃ cāsyakaṭutailenābhyajya pāṭhākalkena pralipyārjunabilvanirguṇḍīmārkavatarkārīsairyakakārpāsīmālatīpatraniryūheṇa secayet" },
      { type: "verse", number: "16", sanskrit: "मरिचविडङ्गहरिद्राकल्कसिद्धं तैलं प्रतिमर्शः मूर्वाताम्ररजसी स्तन्यपिष्टे पिण्डाञ्जनम् शङ्खमनश्शिलासैन्धवरसाञ्जनक्षौद्रैर्वा रसक्रिया लोहशिवाटिकामृदः कपाले ऽनेकशः प्रतप्ताः स्तन्येननिर्वापिताः श्लक्ष्णचूर्णमञ्जनम् लाक्षावेल्लमनश्शिलालगैरिकदार्वीत्वग्भिर्वा पुनः पुनश्च धात्रीं वमनविरेचनैरुपपादयेत्", text: "maricaviḍaṅgaharidrākalkasiddhaṃ tailaṃ pratimarśaḥ mūrvātāmrarajasī stanyapiṣṭe piṇḍāñjanam śaṅkhamanaśśilāsaindhavarasāñjanakṣaudrairvā rasakriyā lohaśivāṭikāmṛdaḥ kapāle 'nekaśaḥ prataptāḥ stanyenanirvāpitāḥ ślakṣṇacūrṇamañjanam lākṣāvellamanaśśilālagairikadārvītvagbhirvā punaḥ punaśca dhātrīṃ vamanavirecanairupapādayet" },
      { type: "verse", number: "17", sanskrit: "पक्ष्मोपरोधे समुपचितं वर्त्म लेखनेनोत्क्लिष्टं रक्तं विस्रावणेन सशोफं शिरोविरेककवलवमनैर्यापयेत्", text: "pakṣmoparodhe samupacitaṃ vartma lekhanenotkliṣṭaṃ raktaṃ visrāvaṇena saśophaṃ śirovirekakavalavamanairyāpayet" },
      { type: "verse", number: "18", sanskrit: "प्रवृद्धेषु तु रोमसु विशुद्धदेहस्य सहिष्णोर्भ्रुवोधस्ताद्द्वौ भागौ पक्ष्मान्तात् भागमेकं समुत्सृज्य यवमात्रं तदाकृति तिर्यक् छेदयेदार्द्रवाससा च रक्तं गृह्णीयात्", text: "pravṛddheṣu tu romasu viśuddhadehasya sahiṣṇorbhruvodhastāddvau bhāgau pakṣmāntāt bhāgamekaṃ samutsṛjya yavamātraṃ tadākṛti tiryak chedayedārdravāsasā ca raktaṃ gṛhṇīyāt" },
      { type: "verse", number: "19", sanskrit: "तत्स्तनुभूते रक्ते क्षौमसूत्रेण बालेन वा धनुर्वक्रया सूच्या मुद्गमात्रान्तरैः पदैः सीव्येत् ततो ऽस्य ललाटे पट्टं बध्वा तत्सीवनसूत्रं तत्र सूचीपदैर्नातिगाढश्लथमासज्जेत् शतधौतघृतेन चास्य सक्षौद्रेण कवलिकां दद्यात्", text: "tatstanubhūte rakte kṣaumasūtreṇa bālena vā dhanurvakrayā sūcyā mudgamātrāntaraiḥ padaiḥ sīvyet tato 'sya lalāṭe paṭṭaṃ badhvā tatsīvanasūtraṃ tatra sūcīpadairnātigāḍhaślathamāsajjet śatadhautaghṛtena cāsya sakṣaudreṇa kavalikāṃ dadyāt" },
      { type: "verse", number: "20", sanskrit: "न चैतत् बध्नीयात् व्रणवेदनायां वस्त्रबद्धेन यष्टीमधुकचूर्णेन संस्कृतं सर्पिः परिषेको वटादिक्वषायाश्च सक्षीराः पञ्चमे षष्ठे वाहनि स्थिरीभूतेषु शस्त्रपदेषु सीवनसूत्रमवलम्बकाच्छित्वापनयेत् व्रणं च स्वर्णगैरिकरजसावचूर्णयेत् तीक्ष्णनस्याञ्जनानि चावचारयेत्", text: "na caitat badhnīyāt vraṇavedanāyāṃ vastrabaddhena yaṣṭīmadhukacūrṇena saṃskṛtaṃ sarpiḥ pariṣeko vaṭādikvaṣāyāśca sakṣīrāḥ pañcame ṣaṣṭhe vāhani sthirībhūteṣu śastrapadeṣu sīvanasūtramavalambakācchitvāpanayet vraṇaṃ ca svarṇagairikarajasāvacūrṇayet tīkṣṇanasyāñjanāni cāvacārayet" },
      { type: "verse", number: "21", sanskrit: "अत्युत्क्षिप्ते तु सूत्रे श्वयथुः स्यात् तत्र मृदुः स्वेदः स्नैहिकं च नस्यम्", text: "atyutkṣipte tu sūtre śvayathuḥ syāt tatra mṛduḥ svedaḥ snaihikaṃ ca nasyam" },
      { type: "verse", number: "22", sanskrit: "निर्भुज्य वा वर्त्मदोषोपहतां वलीं विलिख्य तुम्बुरुवक्रकुशाभयाबीजान्यतमकल्केन प्रतिसारयेत् क्षारेण वा दहेत्तप्रया वा शलाकया", text: "nirbhujya vā vartmadoṣopahatāṃ valīṃ vilikhya tumburuvakrakuśābhayābījānyatamakalkena pratisārayet kṣāreṇa vā dahettaprayā vā śalākayā" },
      { type: "verse", number: "23", sanskrit: "उपपक्ष्माणि तु लाक्षारसेन लक्षयित्वा सन्दंशेनोद्धृत्य तनुसूच्यग्रेणाग्निवर्णेन रोमकूपान् दहेत् ततश्च पूर्ववत् परिषेको नावनं च", text: "upapakṣmāṇi tu lākṣārasena lakṣayitvā sandaṃśenoddhṛtya tanusūcyagreṇāgnivarṇena romakūpān dahet tataśca pūrvavat pariṣeko nāvanaṃ ca" },
      { type: "verse", number: "24", sanskrit: "बाह्यालजेर्भिन्नालिखितस्य क्षारेणाग्निना वा दाहो व्रणवच्चोपचारः अर्बुदस्य च स्विन्नस्यामूलच्छिन्नस्य लिखितप्रतिसारितस्य चेति भवन्ति चात्र", text: "bāhyālajerbhinnālikhitasya kṣāreṇāgninā vā dāho vraṇavaccopacāraḥ arbudasya ca svinnasyāmūlacchinnasya likhitapratisāritasya ceti bhavanti cātra" },
      { type: "verse", number: "25", sanskrit: "निवाते ऽधिष्ठितस्याप्तैः शुद्धस्योत्तानशायिनः बहिः कोष्णाम्बुतप्तेन स्वेदितं वर्त्म वाससा", text: "nivāte 'dhiṣṭhitasyāptaiḥ śuddhasyottānaśāyinaḥ bahiḥ koṣṇāmbutaptena sveditaṃ vartma vāsasā" },
      { type: "verse", number: "26", sanskrit: "निर्भुज्य वस्त्रान्तरितं वामाङ्गुष्ठाङ्गुलीधृतम् न स्रंसते चलति वा वर्त्मैवं सर्वतस्ततः", text: "nirbhujya vastrāntaritaṃ vāmāṅguṣṭhāṅgulīdhṛtam na sraṃsate calati vā vartmaivaṃ sarvatastataḥ" },
      { type: "verse", number: "27", sanskrit: "मण्डलाग्रेण तत्तिर्यक् कृत्वा शस्त्रपदाङ्कितम् लिखेत्तेनैव पत्रैवा शाकशेफालिकादिजैः फेनेन तोयराशेर्वा पिचुना प्रमृजन्नसृक्", text: "maṇḍalāgreṇa tattiryak kṛtvā śastrapadāṅkitam likhettenaiva patraivā śākaśephālikādijaiḥ phenena toyarāśervā picunā pramṛjannasṛk" },
      { type: "verse", number: "28", sanskrit: "स्थिते रक्ते सुलिखितं सक्षौद्रैः प्रतिसारयेत् यथास्वमुक्तैरनु च प्रक्षाल्योष्णेन वारिणा", text: "sthite rakte sulikhitaṃ sakṣaudraiḥ pratisārayet yathāsvamuktairanu ca prakṣālyoṣṇena vāriṇā" },
      { type: "verse", number: "29", sanskrit: "घृतेन सिक्तमभ्यक्तं बध्नीयान्मधुसर्पिषा ऊर्ध्वाधःकर्णयोर्दत्वा पिण्डीं च यवसक्तुभिः", text: "ghṛtena siktamabhyaktaṃ badhnīyānmadhusarpiṣā ūrdhvādhaḥkarṇayordatvā piṇḍīṃ ca yavasaktubhiḥ" },
      { type: "verse", number: "30", sanskrit: "तृतीये ऽहनि मुक्तस्य परिषेकं यथायथम् कुर्याच्चतुर्थे नस्यादीन् मुञ्चेदेवाह्नि पञ्चमे", text: "tṛtīye 'hani muktasya pariṣekaṃ yathāyatham kuryāccaturthe nasyādīn muñcedevāhni pañcame" },
      { type: "verse", number: "31", sanskrit: "समं नखनिभं शोफकण्डूघर्षाद्यपीडितम् विद्यात् सुलिखितं वर्त्म लिखेद्भूयो विपर्यये", text: "samaṃ nakhanibhaṃ śophakaṇḍūgharṣādyapīḍitam vidyāt sulikhitaṃ vartma likhedbhūyo viparyaye" },
      { type: "verse", number: "32", sanskrit: "रुक्पक्ष्मवर्त्मशतनस्रंसनान्यतिलेखनात् स्नेहस्वेदादिकस्तस्मिन्निष्टो वातहरः क्रमः", text: "rukpakṣmavartmaśatanasraṃsanānyatilekhanāt snehasvedādikastasminniṣṭo vātaharaḥ kramaḥ" },
      { type: "verse", number: "33", sanskrit: "अभ्यज्य नवनीतेन श्वेतलोध्रं प्रलेपयेत् एरण्डमूलकल्केन पुटपाकं पचेत्ततः", text: "abhyajya navanītena śvetalodhraṃ pralepayet eraṇḍamūlakalkena puṭapākaṃ pacettataḥ" },
      { type: "verse", number: "34", sanskrit: "स्विन्नं प्रक्षालितं शुष्कं चूर्णितं पोट्टलीकृतम् स्त्रियाः क्षीरे छगल्या वा मृदितं नेत्रसेचनम्", text: "svinnaṃ prakṣālitaṃ śuṣkaṃ cūrṇitaṃ poṭṭalīkṛtam striyāḥ kṣīre chagalyā vā mṛditaṃ netrasecanam" },
      { type: "verse", number: "35", sanskrit: "शालितण्डुलकल्केन लिप्तं तद्वत् परिष्कृतम् कुर्यान्नेत्रे ऽतिलिखिते मृदितं दधिमस्तुना केवलेनापि वा सेकं मस्तुना जाङ्गलाशिनः", text: "śālitaṇḍulakalkena liptaṃ tadvat pariṣkṛtam kuryānnetre 'tilikhite mṛditaṃ dadhimastunā kevalenāpi vā sekaṃ mastunā jāṅgalāśinaḥ" },
      { type: "verse", number: "36", sanskrit: "मेद्यांस्तु व्रीहिवक्त्रेण विभिद्य कठिनोन्नतान् निष्पीडयेदनु विधिः शेषः स्यातत्र पूर्ववत्", text: "medyāṃstu vrīhivaktreṇa vibhidya kaṭhinonnatān niṣpīḍayedanu vidhiḥ śeṣaḥ syātatra pūrvavat" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 13,
    lang: "sa",
    content: [
      { type: "heading", heading: "Джихва рога — болезни языка" },
      { type: "text", text: "Глава 13 Уттара стханы — «Джихва рога» — посвящена специализированному разделу: болезни языка. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः सन्धिसितासितरोगविज्ञानीयं नामा ध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ sandhisitāsitarogavijñānīyaṃ nāmā dhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "वायुः क्रुद्धः सिराः प्राप्य जलाभं जलवाहिनीः अश्रु स्रावयते वर्त्मशुक्लसन्धेः कनीनकात् तेन नेत्रमरुग्रागशोफं स्यात् स जलास्रवः", text: "vāyuḥ kruddhaḥ sirāḥ prāpya jalābhaṃ jalavāhinīḥ aśru srāvayate vartmaśuklasandheḥ kanīnakāt tena netramarugrāgaśophaṃ syāt sa jalāsravaḥ" },
      { type: "verse", number: "3", sanskrit: "कफात् कफास्रवे श्वेतं पिच्छिलं बहलं स्रवेत्", text: "kaphāt kaphāsrave śvetaṃ picchilaṃ bahalaṃ sravet" },
      { type: "verse", number: "4", sanskrit: "कफेन शोफस्तीक्ष्णाग्रः क्षारबुद्बुदकोपमः पृथुमूलश्चलः स्निग्धः सवर्णो मृदुपिच्छिलः महानपाकः कण्डूमानुपनाहः स नीरुजः", text: "kaphena śophastīkṣṇāgraḥ kṣārabudbudakopamaḥ pṛthumūlaścalaḥ snigdhaḥ savarṇo mṛdupicchilaḥ mahānapākaḥ kaṇḍūmānupanāhaḥ sa nīrujaḥ" },
      { type: "verse", number: "5", sanskrit: "रक्ताद्रक्तास्रवे ताम्रं बहूष्णं चाश्रु संस्रवेत्", text: "raktādraktāsrave tāmraṃ bahūṣṇaṃ cāśru saṃsravet" },
      { type: "verse", number: "6", sanskrit: "वर्त्मसन्ध्याश्रया शुक्ले पिटका दाहशूलिनी ताम्रा मुद्गोपमा भिन्ना रक्तं स्रवति पर्वणी", text: "vartmasandhyāśrayā śukle piṭakā dāhaśūlinī tāmrā mudgopamā bhinnā raktaṃ sravati parvaṇī" },
      { type: "verse", number: "7", sanskrit: "पूयास्रावे मलाः सास्रा वर्त्मसन्धेः कनीनकात् स्रावयन्ति मुहुः पूयं सासृक् त्वङ्मांसपाकतः", text: "pūyāsrāve malāḥ sāsrā vartmasandheḥ kanīnakāt srāvayanti muhuḥ pūyaṃ sāsṛk tvaṅmāṃsapākataḥ" },
      { type: "verse", number: "8", sanskrit: "पूयालसो व्रणः सूक्ष्मः शोफसंरम्भपूर्वकः कनीनसन्धावाध्मायी पूयास्रावी सवेदनः", text: "pūyālaso vraṇaḥ sūkṣmaḥ śophasaṃrambhapūrvakaḥ kanīnasandhāvādhmāyī pūyāsrāvī savedanaḥ" },
      { type: "verse", number: "9", sanskrit: "कनीनस्यान्तरलजी शोफो रुक्तोददाहवान्", text: "kanīnasyāntaralajī śopho ruktodadāhavān" },
      { type: "verse", number: "10", sanskrit: "अपाङ्गे वा कनीने वा कण्डूषापक्ष्मपोटवान् पूयास्रावी कृमिग्रन्थिः ग्रन्थिः कृमियुतो ऽर्तिमान्", text: "apāṅge vā kanīne vā kaṇḍūṣāpakṣmapoṭavān pūyāsrāvī kṛmigranthiḥ granthiḥ kṛmiyuto 'rtimān" },
      { type: "verse", number: "11", sanskrit: "उपनाहकृमिग्रन्थिपूयालसकपर्वणीः शस्त्रेण साधयेत् पञ्च सालजीनास्रवांस्त्यजेत्", text: "upanāhakṛmigranthipūyālasakaparvaṇīḥ śastreṇa sādhayet pañca sālajīnāsravāṃstyajet" },
      { type: "verse", number: "12", sanskrit: "पित्तं कुर्यात् सिते बिन्दूनसितश्यावपीतकान् मलाक्तादर्शतुल्यं वा सर्वं शुक्लमदाहरुक् रोगो ऽयं शुक्तिकासंज्ञः सशकृद्भेदतृड्ज्वरः", text: "pittaṃ kuryāt site bindūnasitaśyāvapītakān malāktādarśatulyaṃ vā sarvaṃ śuklamadāharuk rogo 'yaṃ śuktikāsaṃjñaḥ saśakṛdbhedatṛḍjvaraḥ" },
      { type: "verse", number: "13", sanskrit: "कफाच्छुक्ले समं श्वेतं चिरवृध्यधिमांसकम्", text: "kaphācchukle samaṃ śvetaṃ ciravṛdhyadhimāṃsakam" },
      { type: "verse", number: "14", sanskrit: "शुक्लार्मशोफस्त्वरुजः सवर्णो बहलो मृदुः गुरुः स्निग्धोम्बुबिन्द्वाभो बलासग्रथितः स्मृतः", text: "śuklārmaśophastvarujaḥ savarṇo bahalo mṛduḥ guruḥ snigdhombubindvābho balāsagrathitaḥ smṛtaḥ" },
      { type: "verse", number: "15", sanskrit: "बिन्दुभिः पिष्टधवलैरुत्सन्नैः पिष्टकं वदेत्", text: "bindubhiḥ piṣṭadhavalairutsannaiḥ piṣṭakaṃ vadet" },
      { type: "verse", number: "16", sanskrit: "रक्तराजीततं शुक्लमूष्यते यत् सवेदनम् सशोफाश्रूपदेहं च सिरोत्पातः स शोणितात्", text: "raktarājītataṃ śuklamūṣyate yat savedanam saśophāśrūpadehaṃ ca sirotpātaḥ sa śoṇitāt" },
      { type: "verse", number: "17", sanskrit: "उपेक्षितः सिरोत्पातो राजीस्ता एव वर्धयन् कुर्यात् सास्रं सिराहर्षं तेनाक्ष्युद्वीक्षणाक्षमम्", text: "upekṣitaḥ sirotpāto rājīstā eva vardhayan kuryāt sāsraṃ sirāharṣaṃ tenākṣyudvīkṣaṇākṣamam" },
      { type: "verse", number: "18", sanskrit: "सिराजालं सिराजालं बृहद्रक्तं घनोन्नतम्", text: "sirājālaṃ sirājālaṃ bṛhadraktaṃ ghanonnatam" },
      { type: "verse", number: "19", sanskrit: "शोणितार्म समं श्लक्ष्णं पद्माभमाधिमांसकम्", text: "śoṇitārma samaṃ ślakṣṇaṃ padmābhamādhimāṃsakam" },
      { type: "verse", number: "20", sanskrit: "नीरुक्श्लक्ष्णोर्जुनो बिन्दुः शशलोहितलोहितः", text: "nīrukślakṣṇorjuno binduḥ śaśalohitalohitaḥ" },
      { type: "verse", number: "21", sanskrit: "मृद्वाशुवृध्यरुङ्मांसं प्रस्तारि श्यावलोहितम्", text: "mṛdvāśuvṛdhyaruṅmāṃsaṃ prastāri śyāvalohitam" },
      { type: "verse", number: "22", sanskrit: "प्रस्तार्यर्म मलैः सास्रैः स्नावर्म स्नावसन्निभम्", text: "prastāryarma malaiḥ sāsraiḥ snāvarma snāvasannibham" },
      { type: "verse", number: "23", sanskrit: "शुष्कासृक्पिण्डवच्छ्यावं यन्मांसं बहलं पृथु", text: "śuṣkāsṛkpiṇḍavacchyāvaṃ yanmāṃsaṃ bahalaṃ pṛthu" },
      { type: "verse", number: "24", sanskrit: "अधिमांसार्म तत् दाहघर्षवत्यः सिरावृताः कृष्णासन्नाः सिरासंज्ञाः पिटकाः सर्षपोपमाः", text: "adhimāṃsārma tat dāhagharṣavatyaḥ sirāvṛtāḥ kṛṣṇāsannāḥ sirāsaṃjñāḥ piṭakāḥ sarṣapopamāḥ" },
      { type: "verse", number: "25", sanskrit: "शुक्तिहर्षसिरोत्पातपिष्टकग्रथितार्जुनम् साधयेदौषधैः षट्कं शेषं शस्त्रेण सप्तकम्", text: "śuktiharṣasirotpātapiṣṭakagrathitārjunam sādhayedauṣadhaiḥ ṣaṭkaṃ śeṣaṃ śastreṇa saptakam" },
      { type: "verse", number: "26", sanskrit: "नवोत्थं तदपि द्रव्यैरर्मोक्तं यत्तु पञ्चधा तच्छेद्यमसितप्राप्तं मांसस्नावसिरावृतम् चर्मोद्दालवदुच्छ्रायि दृष्टिप्राप्तं तु वर्जयेत्", text: "navotthaṃ tadapi dravyairarmoktaṃ yattu pañcadhā tacchedyamasitaprāptaṃ māṃsasnāvasirāvṛtam carmoddālavaducchrāyi dṛṣṭiprāptaṃ tu varjayet" },
      { type: "verse", number: "27", sanskrit: "पित्तं कृष्णे ऽथवा दृष्टौ शुक्लं तोदाश्रुरागवत् छित्वा त्वचं जनयति तेन स्यात्कृष्णमण्डलम्", text: "pittaṃ kṛṣṇe 'thavā dṛṣṭau śuklaṃ todāśrurāgavat chitvā tvacaṃ janayati tena syātkṛṣṇamaṇḍalam" },
      { type: "verse", number: "28", sanskrit: "पक्वजम्बूनिभं किञ्चिन्निम्नं च क्षतशुक्रकम् तत् कृच्छ्रसाध्यं याप्यं तु द्वितीयपटलव्यधात्", text: "pakvajambūnibhaṃ kiñcinnimnaṃ ca kṣataśukrakam tat kṛcchrasādhyaṃ yāpyaṃ tu dvitīyapaṭalavyadhāt" },
      { type: "verse", number: "29", sanskrit: "तत्र तोदादिबाहुल्यं सूचीविद्धाभकृष्णता तृतीयपटलच्छेदादसाध्यं निचितं व्रणैः", text: "tatra todādibāhulyaṃ sūcīviddhābhakṛṣṇatā tṛtīyapaṭalacchedādasādhyaṃ nicitaṃ vraṇaiḥ" },
      { type: "verse", number: "30", sanskrit: "शङ्खशुक्लं कफात्साध्यं नातिरुक् शुद्धशुक्रकम्", text: "śaṅkhaśuklaṃ kaphātsādhyaṃ nātiruk śuddhaśukrakam" },
      { type: "verse", number: "31", sanskrit: "आताम्रपिच्छिलास्रस्रुदातास्रपिटकातिरुक् अजाविट्सदृशोच्छ्रायकार्ष्ण्या वर्ज्यासृजाजका", text: "ātāmrapicchilāsrasrudātāsrapiṭakātiruk ajāviṭsadṛśocchrāyakārṣṇyā varjyāsṛjājakā" },
      { type: "verse", number: "32", sanskrit: "सिराशुक्रं मलैः सास्रैस्तज्जुष्टं कृष्णमण्डलम् सतोददाहताम्राभिः सिराभिरवतन्यते अनिमित्तोष्णशीताच्छघनास्रस्रुच्च तत्त्यजेत्", text: "sirāśukraṃ malaiḥ sāsraistajjuṣṭaṃ kṛṣṇamaṇḍalam satodadāhatāmrābhiḥ sirābhiravatanyate animittoṣṇaśītācchaghanāsrasrucca tattyajet" },
      { type: "verse", number: "33", sanskrit: "दोषैः सास्रैः सदृक्कृष्णं नीयते शुक्लरूपताम् धवलास्रोपलिप्ताभं निष्पावार्धदलाकृति", text: "doṣaiḥ sāsraiḥ sadṛkkṛṣṇaṃ nīyate śuklarūpatām dhavalāsropaliptābhaṃ niṣpāvārdhadalākṛti" },
      { type: "verse", number: "34", sanskrit: "अतितीव्ररुजारागदाहश्वयथुपीडितम् पाकात्ययेन तच्छुक्रं वर्जयेत्तीव्रवेदनम्", text: "atitīvrarujārāgadāhaśvayathupīḍitam pākātyayena tacchukraṃ varjayettīvravedanam" },
      { type: "verse", number: "35", sanskrit: "यस्य वा लिङ्गनाशो ऽन्तःश्यावं यद्वा सलोहितम् अत्युत्सेधावगाढं वा सास्रनाडीव्रणावृतम्", text: "yasya vā liṅganāśo 'ntaḥśyāvaṃ yadvā salohitam atyutsedhāvagāḍhaṃ vā sāsranāḍīvraṇāvṛtam" },
      { type: "verse", number: "36", sanskrit: "पुराणं विषमं मध्ये विच्छिन्नं यच्च शुक्रकम् पञ्चेत्युक्ता गदाः कृष्णे साध्यासाध्यविभागतः", text: "purāṇaṃ viṣamaṃ madhye vicchinnaṃ yacca śukrakam pañcetyuktā gadāḥ kṛṣṇe sādhyāsādhyavibhāgataḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 14,
    lang: "sa",
    content: [
      { type: "heading", heading: "Тала рога — болезни нёба" },
      { type: "text", text: "Глава 14 Уттара стханы — «Тала рога» — посвящена специализированному разделу: болезни нёба. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः सन्धिसितासितरोगप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ sandhisitāsitarogapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "उपनाहं भिषक् स्विन्नं व्रीहिमुखेन भित्वा मण्डलाग्रेण समन्ताल्लेखयेत् ततः सैधवपिप्पलीचूर्णेन सक्षौद्रेण प्रतिसारयेत् पूर्ववच्च बध्नीयात् पटोलपत्रामलकक्वाथेनाश्च्योतयेत्", text: "upanāhaṃ bhiṣak svinnaṃ vrīhimukhena bhitvā maṇḍalāgreṇa samantāllekhayet tataḥ saidhavapippalīcūrṇena sakṣaudreṇa pratisārayet pūrvavacca badhnīyāt paṭolapatrāmalakakvāthenāścyotayet" },
      { type: "verse", number: "3", sanskrit: "पर्वणामुत्तरसन्धित्रिभागे बडिशेनावलम्ब्य वृद्धिपत्रेणार्धमात्रे छिन्द्यात् अन्यथाश्रुनाडी स्यात् मधुसैन्धवप्रतिसारितां चार्मवच्चिकित्सेत्", text: "parvaṇāmuttarasandhitribhāge baḍiśenāvalambya vṛddhipatreṇārdhamātre chindyāt anyathāśrunāḍī syāt madhusaindhavapratisāritāṃ cārmavaccikitset" },
      { type: "verse", number: "4", sanskrit: "पूयालसे सिरां विध्येत्ततस्तमुपनाहयेदक्षिपाकोक्तं चक्षेत सैन्धवार्द्रककासीसायस्ताम्रैः सुसूक्ष्मैः सक्षौद्रैरञ्जनम्", text: "pūyālase sirāṃ vidhyettatastamupanāhayedakṣipākoktaṃ cakṣeta saindhavārdrakakāsīsāyastāmraiḥ susūkṣmaiḥ sakṣaudrairañjanam" },
      { type: "verse", number: "5", sanskrit: "कृमिग्रन्थिं करीषेण स्विन्नं भित्वा विलिख्य च कासीससैन्धवत्रिफलामाक्षिकैः प्रतिसारयेत्", text: "kṛmigranthiṃ karīṣeṇa svinnaṃ bhitvā vilikhya ca kāsīsasaindhavatriphalāmākṣikaiḥ pratisārayet" },
      { type: "verse", number: "6", sanskrit: "शुक्तिकां पित्ताभिष्यन्दवत् साधयेत्", text: "śuktikāṃ pittābhiṣyandavat sādhayet" },
      { type: "verse", number: "7", sanskrit: "बलासग्रथितं पिष्टकं च सिराव्यधवर्जं कफाभिष्यन्दवत्", text: "balāsagrathitaṃ piṣṭakaṃ ca sirāvyadhavarjaṃ kaphābhiṣyandavat" },
      { type: "verse", number: "8", sanskrit: "विशेषतस्तिलनालान् यवनालान् वा हरितशलाकानर्धमासमजाक्षीरेण भावयित्वा शोषयित्वा च दाहयेत् ततस्तद्भस्म क्षारकल्पेन परिस्राव्यादर्वीप्रलेपाद्विपचेत् रसक्रियेयं बलासग्रथितशोफोपदेहहरा अयमेव च कल्पः फणिज्जाअर्जकास्फोतबिल्वकपित्थनिर्गुण्ड्येरण्डकुमुदोत्पलजातीकुसुमेषु पृथक् कार्यः", text: "viśeṣatastilanālān yavanālān vā haritaśalākānardhamāsamajākṣīreṇa bhāvayitvā śoṣayitvā ca dāhayet tatastadbhasma kṣārakalpena parisrāvyādarvīpralepādvipacet rasakriyeyaṃ balāsagrathitaśophopadehaharā ayameva ca kalpaḥ phaṇijjāarjakāsphotabilvakapitthanirguṇḍyeraṇḍakumudotpalajātīkusumeṣu pṛthak kāryaḥ" },
      { type: "verse", number: "9", sanskrit: "सैन्धवालमरिचकट्फलशङ्खसमुद्रफेनैर्वर्तिः पिष्टके ऽञ्जनम् शुण्ठीशिग्रुफलपिप्पलीसैन्धवचूर्णो बीजपूरकरसाप्लुतो ऽञ्जनं पिष्टकमपहरति तद्वत्त्रिकटुककट्फलचूर्णो बलासग्रथितं च", text: "saindhavālamaricakaṭphalaśaṅkhasamudraphenairvartiḥ piṣṭake 'ñjanam śuṇṭhīśigruphalapippalīsaindhavacūrṇo bījapūrakarasāpluto 'ñjanaṃ piṣṭakamapaharati tadvattrikaṭukakaṭphalacūrṇo balāsagrathitaṃ ca" },
      { type: "verse", number: "10", sanskrit: "बृहतीफलं पिप्पलीतण्डुलपूरितं पुटपाकेन पचेत् तैस्तण्डुलैश्चूर्णाञ्जनं बलासग्रथितपिष्टकघ्नम् अत्यर्थशोफे हरितालसैन्धवशुण्ठीदेवदारुपुनर्नवैर्बिडालकः", text: "bṛhatīphalaṃ pippalītaṇḍulapūritaṃ puṭapākena pacet taistaṇḍulaiścūrṇāñjanaṃ balāsagrathitapiṣṭakaghnam atyarthaśophe haritālasaindhavaśuṇṭhīdevadārupunarnavairbiḍālakaḥ" },
      { type: "verse", number: "11", sanskrit: "सिरोत्पातहर्षजालार्जुनेषु रक्ताभिष्यन्दवत् प्रतिकुर्यात् विशेषेण सिराहर्षे स्वर्णगैरिको मधुयुक्तो ऽञ्जनम् स्तन्यान्वितं वा कासीसं क्षौद्रद्रुतं वा कासीससैन्धवमर्जुने मातुलुङ्गरसेन सशर्करेणाश्च्योतनं मस्तुना वा", text: "sirotpātaharṣajālārjuneṣu raktābhiṣyandavat pratikuryāt viśeṣeṇa sirāharṣe svarṇagairiko madhuyukto 'ñjanam stanyānvitaṃ vā kāsīsaṃ kṣaudradrutaṃ vā kāsīsasaindhavamarjune mātuluṅgarasena saśarkareṇāścyotanaṃ mastunā vā" },
      { type: "verse", number: "12", sanskrit: "शङ्खनाभिर्माक्षिकेण युक्ता सितया वा समुद्रफेनकोञ्जनम् स्फटिककुङ्कुमशङ्खनाभिमधुयष्टिका वा क्षौद्रार्द्रास्तद्वद्वा रसाञ्जनं कासीसं वा", text: "śaṅkhanābhirmākṣikeṇa yuktā sitayā vā samudraphenakoñjanam sphaṭikakuṅkumaśaṅkhanābhimadhuyaṣṭikā vā kṣaudrārdrāstadvadvā rasāñjanaṃ kāsīsaṃ vā" },
      { type: "verse", number: "13", sanskrit: "अर्म तु पञ्चविधमपि यत्तनुरक्तं धूमाविलं दधिनिभं वा तच्छुक्रवत् कायशिरोविरेकलेखनाञ्जनैरुपाचरेत्", text: "arma tu pañcavidhamapi yattanuraktaṃ dhūmāvilaṃ dadhinibhaṃ vā tacchukravat kāyaśirovirekalekhanāñjanairupācaret" },
      { type: "verse", number: "14", sanskrit: "अथेतरस्मिन् स्निग्धस्यातुरस्य पेयाविलेपिजाङ्गलरसान्यतमाशितस्य कृतस्वस्त्ययनस्य सुखशयनगतस्योत्तानदेहस्य किञ्चिदवाक्शिरसः सुखोष्णाम्बुप्लुततान्तवस्विन्ननयनस्य सैन्धवेन सबीजपूरकरसेनाञ्जयित्वाङ्गुष्ठकेन निमीलितमक्षि विमृद्गीयादाबलासग्रथितरूपोत्पत्तेः इत्थं च संरोषिताक्षस्य प्रचलिते ऽर्माधिमांसके निश्चलं परिचारकः शिरोधारयेत्", text: "athetarasmin snigdhasyāturasya peyāvilepijāṅgalarasānyatamāśitasya kṛtasvastyayanasya sukhaśayanagatasyottānadehasya kiñcidavākśirasaḥ sukhoṣṇāmbuplutatāntavasvinnanayanasya saindhavena sabījapūrakarasenāñjayitvāṅguṣṭhakena nimīlitamakṣi vimṛdgīyādābalāsagrathitarūpotpatteḥ itthaṃ ca saṃroṣitākṣasya pracalite 'rmādhimāṃsake niścalaṃ paricārakaḥ śirodhārayet" },
      { type: "verse", number: "15", sanskrit: "अन्यश्च वामदक्षिणान्यतरपार्श्वे ऽनुकूलं स्थितो दृढवस्त्रगर्भाभ्यामङ्गुष्ठाभ्यां वर्त्मनी निक्षिपेत् अथ वैद्यः कनीनकात् प्रवृद्धे ऽर्मण्यपाङ्गमक्षिमाणस्य यत्र यत्र वली जायते तत्र तत्रार्म बडिशेन मुचुट्या वा नात्यायतं गृहीत्वा किञ्चिदुन्नम्य कृष्णशुक्लमण्डलाभ्यां सर्वतः सूच्यग्रेण मोक्षयित्वा किञ्चिदाञ्छेत् अथ तीक्ष्णेन मण्डलाग्रेण वृद्धिपत्रेण वा विलिख्य कनीनकं चोपानीय कनीनकसममेव चतुर्भागशेषं छिन्द्यात् वर्जयेच्च कनीनकं सिराश्चाश्रुवहाः तथा हि नाक्षि व्यापद्यते", text: "anyaśca vāmadakṣiṇānyatarapārśve 'nukūlaṃ sthito dṛḍhavastragarbhābhyāmaṅguṣṭhābhyāṃ vartmanī nikṣipet atha vaidyaḥ kanīnakāt pravṛddhe 'rmaṇyapāṅgamakṣimāṇasya yatra yatra valī jāyate tatra tatrārma baḍiśena mucuṭyā vā nātyāyataṃ gṛhītvā kiñcidunnamya kṛṣṇaśuklamaṇḍalābhyāṃ sarvataḥ sūcyagreṇa mokṣayitvā kiñcidāñchet atha tīkṣṇena maṇḍalāgreṇa vṛddhipatreṇa vā vilikhya kanīnakaṃ copānīya kanīnakasamameva caturbhāgaśeṣaṃ chindyāt varjayecca kanīnakaṃ sirāścāśruvahāḥ tathā hi nākṣi vyāpadyate" },
      { type: "verse", number: "16", sanskrit: "यत्तु जालवदर्म व्यापि तदेषिण्या यावत्कनीनकमनुसरन्नुन्मोच्योन्नमय्य पूर्ववत् छिन्द्यात् तद्वदपाङ्गात् प्रवृद्धे कनीनकमीक्षमाणस्य यावदपाङ्गं चोपनीयापाङ्गसममेव तथा यावद्वर्जयेदपाङ्गं सिराश्चेत्यादि ततः प्लोतेन रक्तं विशोध्य सम्यक् छिन्नमवेक्ष्य सैन्धवचूर्णेन पुनः पुनः प्रतिसारयेद्यवनालभस्मना वा प्लोतशुद्धं च पुनर्मधुना ततः शीताम्बु परिषिक्तं सर्पिषा सुखोष्णेन परिषिच्य मधुघृताक्तं पूर्ववत् बध्नीयात् मूर्ध्नि पादयोश्चास्मै शतधौतघृतं शीतांश्च प्रदेहान् दद्यात्", text: "yattu jālavadarma vyāpi tadeṣiṇyā yāvatkanīnakamanusarannunmocyonnamayya pūrvavat chindyāt tadvadapāṅgāt pravṛddhe kanīnakamīkṣamāṇasya yāvadapāṅgaṃ copanīyāpāṅgasamameva tathā yāvadvarjayedapāṅgaṃ sirāścetyādi tataḥ plotena raktaṃ viśodhya samyak chinnamavekṣya saindhavacūrṇena punaḥ punaḥ pratisārayedyavanālabhasmanā vā plotaśuddhaṃ ca punarmadhunā tataḥ śītāmbu pariṣiktaṃ sarpiṣā sukhoṣṇena pariṣicya madhughṛtāktaṃ pūrvavat badhnīyāt mūrdhni pādayoścāsmai śatadhautaghṛtaṃ śītāṃśca pradehān dadyāt" },
      { type: "verse", number: "17", sanskrit: "स्नेहोक्तं चाचारमादिशेत् द्वितीये चाह्नि सायं प्रातर्मधुकसर्पिषा कोष्णेन शिरस्तथावबद्धमेव चाक्षि सिञ्चेत् पञ्चाहं चोष्णोदकानुपानं सर्पिः पीत्वा जीर्णे पथ्यमश्नीयात्", text: "snehoktaṃ cācāramādiśet dvitīye cāhni sāyaṃ prātarmadhukasarpiṣā koṣṇena śirastathāvabaddhameva cākṣi siñcet pañcāhaṃ coṣṇodakānupānaṃ sarpiḥ pītvā jīrṇe pathyamaśnīyāt" },
      { type: "verse", number: "18", sanskrit: "तृतीये दिवसे विमुच्य करञ्जबीजसिद्धेन क्षीरेणाक्षि स्वेदयेत् लोध्रमधुककिंशुकपटोलद्विहरिद्राकोरण्डमुकुलक्वाथेन मधुमिश्रेणाश्च्योतयेत् सप्तमे ऽहनि सर्वथा मुञ्चेत् आतपाकाशदर्शनं च परिहरेत्", text: "tṛtīye divase vimucya karañjabījasiddhena kṣīreṇākṣi svedayet lodhramadhukakiṃśukapaṭoladviharidrākoraṇḍamukulakvāthena madhumiśreṇāścyotayet saptame 'hani sarvathā muñcet ātapākāśadarśanaṃ ca pariharet" },
      { type: "verse", number: "19", sanskrit: "सशोफे तु नेत्रे धूमः शिरोविरेचनं च अनुपशान्तरागे सिराविस्रावणम् सास्रावे नस्यम्", text: "saśophe tu netre dhūmaḥ śirovirecanaṃ ca anupaśāntarāge sirāvisrāvaṇam sāsrāve nasyam" },
      { type: "verse", number: "20", sanskrit: "तिलान् सुलिखितान् मधुककाकोलीसुनिषण्णकपञ्चमूलशर्कराश्रुतशीते पयसि सप्ताहं भावितांस्तेनैव पयसा पीडयेत् मधुकशताह्वासारिवानन्तागरुकाकोलीहरेणुकैलावालुकचूर्णं च पीड्यमानेषु षोडशभागेन प्रक्षिपेत् तत्तैलमेभिरेवौषधैः पयसा चाष्टगुणेन सिद्धं नावनादश्रुरागघ्नं दृष्टिप्रसादनं च कृष्णगते तु व्रणे व्रणशुक्रवत् क्रिया अर्मशेषे च लेखनाञ्जनानि", text: "tilān sulikhitān madhukakākolīsuniṣaṇṇakapañcamūlaśarkarāśrutaśīte payasi saptāhaṃ bhāvitāṃstenaiva payasā pīḍayet madhukaśatāhvāsārivānantāgarukākolīhareṇukailāvālukacūrṇaṃ ca pīḍyamāneṣu ṣoḍaśabhāgena prakṣipet tattailamebhirevauṣadhaiḥ payasā cāṣṭaguṇena siddhaṃ nāvanādaśrurāgaghnaṃ dṛṣṭiprasādanaṃ ca kṛṣṇagate tu vraṇe vraṇaśukravat kriyā armaśeṣe ca lekhanāñjanāni" },
      { type: "verse", number: "21", sanskrit: "तत्र सम्यक्छिन्ने वर्णविशुद्धिः स्वस्थता च हीनच्छेदात् पुनर्वृद्धी रागाश्रुपातप्रकाशदर्शनाक्षमत्वादि च अतिच्छेदादक्षिपाकस्तम्भस्फुरणास्रस्रुतितिमिरसंरम्भविबद्धवर्त्मानि तेषु यथास्वं दोषोद्रेकात् प्रतिकुर्यात् नागरमनश्शिलालैलासैन्धवशर्कराभिरर्धकर्षांशाभिर्युक्तं रसाञ्जनार्धपलं क्षौद्रद्रुतमञ्जनादर्मशेषश्लेष्मतिमिरपिल्लामयघ्रम्", text: "tatra samyakchinne varṇaviśuddhiḥ svasthatā ca hīnacchedāt punarvṛddhī rāgāśrupātaprakāśadarśanākṣamatvādi ca aticchedādakṣipākastambhasphuraṇāsrasrutitimirasaṃrambhavibaddhavartmāni teṣu yathāsvaṃ doṣodrekāt pratikuryāt nāgaramanaśśilālailāsaindhavaśarkarābhirardhakarṣāṃśābhiryuktaṃ rasāñjanārdhapalaṃ kṣaudradrutamañjanādarmaśeṣaśleṣmatimirapillāmayaghram" },
      { type: "verse", number: "22", sanskrit: "सिराजाले सिरा यास्तु स्थूलाः कठिनाश्चता बडिशेन गृहीत्वा मण्डलाग्रेणोल्लिखेत्", text: "sirājāle sirā yāstu sthūlāḥ kaṭhināścatā baḍiśena gṛhītvā maṇḍalāgreṇollikhet" },
      { type: "verse", number: "23", sanskrit: "सिरापिटकाः सूच्यग्रेणावलम्बिताः कृष्णमनुपघ्नन् छिन्द्यात् सूक्ष्मास्त्ववलिखेत् अर्मवच्चैतयोः शेषमाचरेत्", text: "sirāpiṭakāḥ sūcyagreṇāvalambitāḥ kṛṣṇamanupaghnan chindyāt sūkṣmāstvavalikhet armavaccaitayoḥ śeṣamācaret" },
      { type: "verse", number: "24", sanskrit: "शुक्रकेषु यथास्वदोषानुसारेण त्रिफलाघृतपानरक्तमोक्षविरेचनाश्च्योतनमुखालेपनस्यतर्पणपुट पाकान् प्रयुञ्जीत", text: "śukrakeṣu yathāsvadoṣānusāreṇa triphalāghṛtapānaraktamokṣavirecanāścyotanamukhālepanasyatarpaṇapuṭa pākān prayuñjīta" },
      { type: "verse", number: "25", sanskrit: "तत्र व्रणशुक्रे त्रिवृन्निर्यूहेण त्रिर्विपक्वं सर्पिः पाययेत् सिरां च विध्येत् दुष्टशेषं च पिण्डितमक्षिगमसृक् जलौकोभिरपहरेत् मधुककाकोलीमृद्वीकोत्पलविदारीक्वाथेन मञ्जिष्ठाक्षीरकाकोलीमधुकक्वथिताजक्षीरेण वा सशर्करेणाश्च्योतयेत् शीतैश्चास्य शिरोवक्त्रं दिह्यात् सिञ्चेच्च एवमप्यनुबद्धवेदनं शताह्वायष्ट्याह्ववता घृतमण्डेनानुवासयेत्", text: "tatra vraṇaśukre trivṛnniryūheṇa trirvipakvaṃ sarpiḥ pāyayet sirāṃ ca vidhyet duṣṭaśeṣaṃ ca piṇḍitamakṣigamasṛk jalaukobhirapaharet madhukakākolīmṛdvīkotpalavidārīkvāthena mañjiṣṭhākṣīrakākolīmadhukakvathitājakṣīreṇa vā saśarkareṇāścyotayet śītaiścāsya śirovaktraṃ dihyāt siñcecca evamapyanubaddhavedanaṃ śatāhvāyaṣṭyāhvavatā ghṛtamaṇḍenānuvāsayet" },
      { type: "verse", number: "26", sanskrit: "अश्रुरागरुजाशान्तिं यदा यस्योपलक्षयेत् तदातदाञ्जनैः शुक्रं लेखनीयैरुपाचरेत्", text: "aśrurāgarujāśāntiṃ yadā yasyopalakṣayet tadātadāñjanaiḥ śukraṃ lekhanīyairupācaret" },
      { type: "verse", number: "27", sanskrit: "वैडूर्यस्फटिकशङ्खमुक्ताविद्रुमरूप्यायस्त्रपुत्ताम्रसीसालमनश्शिलाकुक्कुटाण्डत्वक्समुद्रफेनरसाञ्जनसैन्धवैरजापयःपिष्टैर्वर्तयश्छ्यायाशुष्काः क्षौद्रघृष्टाः प्रातः सायं च प्रयुक्ता व्रणशुक्रनुदः करिवराहगोगर्दभाश्वाजोष्ट्रदशनाःशङ्खमुक्तासमुद्रफेनाश्च मरिच चतुर्थांशयुता जलपिष्टा वर्तयः क्षतशुक्रहराः लाक्षासुवर्णगैरिकचन्दनजातीमुकुलैर्वर्तिरसृकूपित्तप्रसादनी व्रणशुक्रहरा च", text: "vaiḍūryasphaṭikaśaṅkhamuktāvidrumarūpyāyastraputtāmrasīsālamanaśśilākukkuṭāṇḍatvaksamudraphenarasāñjanasaindhavairajāpayaḥpiṣṭairvartayaśchyāyāśuṣkāḥ kṣaudraghṛṣṭāḥ prātaḥ sāyaṃ ca prayuktā vraṇaśukranudaḥ karivarāhagogardabhāśvājoṣṭradaśanāḥśaṅkhamuktāsamudraphenāśca marica caturthāṃśayutā jalapiṣṭā vartayaḥ kṣataśukraharāḥ lākṣāsuvarṇagairikacandanajātīmukulairvartirasṛkūpittaprasādanī vraṇaśukraharā ca" },
      { type: "verse", number: "28", sanskrit: "निम्नं च शुक्रं सरुजमुन्नमयेत् स्नेहपाननस्यजाङ्गलरसैः नीरुजं तर्पणपुटपाकाभ्याम्", text: "nimnaṃ ca śukraṃ sarujamunnamayet snehapānanasyajāṅgalarasaiḥ nīrujaṃ tarpaṇapuṭapākābhyām" },
      { type: "verse", number: "29", sanskrit: "तत्र तर्पणं मृगविष्किरपिशितं काश्मर्यसुनिषण्णोत्पलमृणालशृङ्गाटकशेरुद्राक्षाक्षीरविदारीजीवनीयांश्च क्षीरेण पाचयेत् तस्मान्नवनीतमुद्धृत्य चन्दनमधुशर्करानन्तानीलोत्पलकल्कैरष्टगुणेन च पयसा विपक्वं पूर्ववद्योजयेत्", text: "tatra tarpaṇaṃ mṛgaviṣkirapiśitaṃ kāśmaryasuniṣaṇṇotpalamṛṇālaśṛṅgāṭakaśerudrākṣākṣīravidārījīvanīyāṃśca kṣīreṇa pācayet tasmānnavanītamuddhṛtya candanamadhuśarkarānantānīlotpalakalkairaṣṭaguṇena ca payasā vipakvaṃ pūrvavadyojayet" },
      { type: "verse", number: "30", sanskrit: "पुटपाकं च कुक्कुटमुद्धृतान्त्रं वेशवारीकृत्य चन्दनसारिवामधुकशर्करानन्तानीलोत्पलप्रपौण्डरीक जीवनीयकल्कैः समधुघृतैः संसृज्य प्रागिव कल्पयेत् द्वित्वक्छिन्नमेवं यापयेत्", text: "puṭapākaṃ ca kukkuṭamuddhṛtāntraṃ veśavārīkṛtya candanasārivāmadhukaśarkarānantānīlotpalaprapauṇḍarīka jīvanīyakalkaiḥ samadhughṛtaiḥ saṃsṛjya prāgiva kalpayet dvitvakchinnamevaṃ yāpayet" },
      { type: "verse", number: "31", sanskrit: "शुद्धशुक्रे हरिद्रामधुकसारिवालोध्रनिर्यूहेणाश्च्योतनम् लोध्रचूर्णेण वा तान्तवबद्धेनोष्णाम्बुमृदितेन शुद्धकोष्ठस्य च दन्तीज्योतिष्मतीकल्को ऽवपीडकः शिरोविरेचनद्रव्यविपक्वं वा तैलं मर्शः प्रतिमर्शो वा", text: "śuddhaśukre haridrāmadhukasārivālodhraniryūheṇāścyotanam lodhracūrṇeṇa vā tāntavabaddhenoṣṇāmbumṛditena śuddhakoṣṭhasya ca dantījyotiṣmatīkalko 'vapīḍakaḥ śirovirecanadravyavipakvaṃ vā tailaṃ marśaḥ pratimarśo vā" },
      { type: "verse", number: "32", sanskrit: "शुण्ठीसैन्धवमधुयष्टिकाबृहतीमूलताम्ररजोभिरामलकरसपिष्टैस्ताम्रपात्रं प्रलेपयेत् तच्च सघृतैर्यवैरामलकपत्रैश्च बहुशो धूपयेत् वर्तिरेषा महानीला मधुतोयघृष्टा शुद्धशुक्रं नाशयति पूर्वोक्ता च दन्तवर्तिः अशाम्यति तु शुक्रे सर्वत्र पुनः पुनर्यथोक्तमेव पर्यायेण योजयेत् अन्तरान्तरा च रक्तं विस्रावयेत् अभिष्यन्दप्रतिषेधं चेक्षेत", text: "śuṇṭhīsaindhavamadhuyaṣṭikābṛhatīmūlatāmrarajobhirāmalakarasapiṣṭaistāmrapātraṃ pralepayet tacca saghṛtairyavairāmalakapatraiśca bahuśo dhūpayet vartireṣā mahānīlā madhutoyaghṛṣṭā śuddhaśukraṃ nāśayati pūrvoktā ca dantavartiḥ aśāmyati tu śukre sarvatra punaḥ punaryathoktameva paryāyeṇa yojayet antarāntarā ca raktaṃ visrāvayet abhiṣyandapratiṣedhaṃ cekṣeta" },
      { type: "verse", number: "33", sanskrit: "अथोत्सादनार्थं शुद्धशुक्रे सम्प्रहर्षणानि दद्यात् त्रिफलारसेन त्र्यहं भावितेन सैन्धवेनाञ्जयेत् तद्वत् पिप्पलीभिर्वा मरिचपिप्पलीशिरीषबीजबलासग्रथितोक्तक्षाराञ्जनैर्वा", text: "athotsādanārthaṃ śuddhaśukre sampraharṣaṇāni dadyāt triphalārasena tryahaṃ bhāvitena saindhavenāñjayet tadvat pippalībhirvā maricapippalīśirīṣabījabalāsagrathitoktakṣārāñjanairvā" },
      { type: "verse", number: "34", sanskrit: "सम्प्रहर्षणाद्रागाश्रुवेदनासु सन्धावाञ्जनानि युञ्ज्यात् शङ्खं ताम्रे स्तन्येन घृष्टं सघृतैर्यवैः शमीपत्रैश्च धूपयेत् अनेन सन्धावाञ्जनेनाञ्जयेत् तद्वत् सुवर्णं रूप्यमयो व घृष्टं सघृतैर्बदरीपत्रैर्धूपितमञ्जनम् शङ्खो निस्तुषाश्च हरितमुद्गाः पिष्टा वर्तिश्रूर्णो वा मधुयुक्तो ऽञ्जनं शुक्रघर्षणम् मधूकसारश्च मधुना बिभीतकास्थिमज्जा वा", text: "sampraharṣaṇādrāgāśruvedanāsu sandhāvāñjanāni yuñjyāt śaṅkhaṃ tāmre stanyena ghṛṣṭaṃ saghṛtairyavaiḥ śamīpatraiśca dhūpayet anena sandhāvāñjanenāñjayet tadvat suvarṇaṃ rūpyamayo va ghṛṣṭaṃ saghṛtairbadarīpatrairdhūpitamañjanam śaṅkho nistuṣāśca haritamudgāḥ piṣṭā vartiśrūrṇo vā madhuyukto 'ñjanaṃ śukragharṣaṇam madhūkasāraśca madhunā bibhītakāsthimajjā vā" },
      { type: "verse", number: "35", sanskrit: "मसूरा निस्तुषाः स्तन्यपिष्टास्तरुणदर्भाङ्कुरा घृतमाजं गोक्षीरं शरश्चायसे ताम्रेण घृष्टं प्रत्यञ्जनं वेदनाघ्नम् यवगोधूमजीवनीयमांसीचूर्णेन सघृतशर्करोत्कारिका स्वेदोपनाहे प्रणीता वेदनामपनयति शुक्रं चोत्सादयति तद्वदानूपमांसवेशवारो वसापयः सर्पिर्विमिश्रः सिद्धः", text: "masūrā nistuṣāḥ stanyapiṣṭāstaruṇadarbhāṅkurā ghṛtamājaṃ gokṣīraṃ śaraścāyase tāmreṇa ghṛṣṭaṃ pratyañjanaṃ vedanāghnam yavagodhūmajīvanīyamāṃsīcūrṇena saghṛtaśarkarotkārikā svedopanāhe praṇītā vedanāmapanayati śukraṃ cotsādayati tadvadānūpamāṃsaveśavāro vasāpayaḥ sarpirvimiśraḥ siddhaḥ" },
      { type: "verse", number: "36", sanskrit: "अथैवमुपनाहप्रचलितस्याञ्जनम् गोखराश्वोष्ट्रदन्ताः समुद्रफेनः शङ्खश्चार्जुनकषायपिष्टा वर्तिर्लेखनी समुद्रफेनशङ्खखर्परशुकास्थिखरनागाश्वगोबालास्तिन्दुककषायपिष्टा वा", text: "athaivamupanāhapracalitasyāñjanam gokharāśvoṣṭradantāḥ samudraphenaḥ śaṅkhaścārjunakaṣāyapiṣṭā vartirlekhanī samudraphenaśaṅkhakharparaśukāsthikharanāgāśvagobālāstindukakaṣāyapiṣṭā vā" },
      { type: "verse", number: "37", sanskrit: "प्रत्यञ्जनं च तरुणबदरखदिरतिन्दुकास्थ्नामन्तर्धूमदग्धानां चूर्णम् उत्सन्नं वा सशल्यं वा शुक्रं बालादिभिर्लिखेत् पुटपाकेन वा बलासग्रथितोक्तक्षाररसक्रियया वा", text: "pratyañjanaṃ ca taruṇabadarakhadiratindukāsthnāmantardhūmadagdhānāṃ cūrṇam utsannaṃ vā saśalyaṃ vā śukraṃ bālādibhirlikhet puṭapākena vā balāsagrathitoktakṣārarasakriyayā vā" },
      { type: "verse", number: "38", sanskrit: "सिराशुक्रे त्वदृष्टिघ्ने तरुणे व्रणशुक्रवत् कुर्यात्", text: "sirāśukre tvadṛṣṭighne taruṇe vraṇaśukravat kuryāt" },
      { type: "verse", number: "39", sanskrit: "अञ्जनं चास्य प्रपौण्डरीकमधुकहरिद्रालोहरजोञ्जनबृहतीक्षीरकाकोलीरजापयःपिष्टा यवैर्घृतयुक्तैरामलकीपत्रैश्च पर्यायेण धूपिता वर्तिः", text: "añjanaṃ cāsya prapauṇḍarīkamadhukaharidrāloharajoñjanabṛhatīkṣīrakākolīrajāpayaḥpiṣṭā yavairghṛtayuktairāmalakīpatraiśca paryāyeṇa dhūpitā vartiḥ" },
      { type: "verse", number: "40", sanskrit: "अप्रशान्तमेव मर्मवत् साधयेत् समाक्षिकं तु रसाञ्जनं प्रतिसारणम् सप्तमे दिवसे कुक्कुटाण्डकपालस्फटिकचन्दनमनश्शिलालैरश्ववराहदशनैश्च वर्तिं कृत्वाञ्जयेत् उदधिकफशङ्खचन्दनैरजापयःपिष्टैर्वर्तिर्मधुघृष्टा प्रत्यंजनं सिराशुक्रजित् अनुपशमे पश्यति चातुरे किञ्चिदिदमेवासकृत् कुर्वीत", text: "apraśāntameva marmavat sādhayet samākṣikaṃ tu rasāñjanaṃ pratisāraṇam saptame divase kukkuṭāṇḍakapālasphaṭikacandanamanaśśilālairaśvavarāhadaśanaiśca vartiṃ kṛtvāñjayet udadhikaphaśaṅkhacandanairajāpayaḥpiṣṭairvartirmadhughṛṣṭā pratyaṃjanaṃ sirāśukrajit anupaśame paśyati cāture kiñcididamevāsakṛt kurvīta" },
      { type: "verse", number: "41", sanskrit: "अजकामदृष्ट्युपघातिनीं कृष्णान्तजामस्रविस्रावणैर्मधुरविरेचनैः क्षीरबस्तिभिञ्च साधयेत् सिराशुक्रवच्च शस्त्रकर्मादिविधिनेति भवति चात्र", text: "ajakāmadṛṣṭyupaghātinīṃ kṛṣṇāntajāmasravisrāvaṇairmadhuravirecanaiḥ kṣīrabastibhiñca sādhayet sirāśukravacca śastrakarmādividhineti bhavati cātra" },
      { type: "verse", number: "42", sanskrit: "अजकायामसाध्यायां शुक्रे ऽन्यत्र च तद्विधे वेदनोपशमं स्नेहपानासृक्स्रावणादिभिः कुर्यात् बीभत्सतां जेतुं शुक्रत्वोत्सेधसाधनम्", text: "ajakāyāmasādhyāyāṃ śukre 'nyatra ca tadvidhe vedanopaśamaṃ snehapānāsṛksrāvaṇādibhiḥ kuryāt bībhatsatāṃ jetuṃ śukratvotsedhasādhanam" },
      { type: "verse", number: "43", sanskrit: "नारिकेलास्थिभल्लाततालवंशकरीरजम् भस्माद्भिः स्रावयेत्ताभिर्भावयेत् करभास्थिजम्", text: "nārikelāsthibhallātatālavaṃśakarīrajam bhasmādbhiḥ srāvayettābhirbhāvayet karabhāsthijam" },
      { type: "verse", number: "44", sanskrit: "चूर्णं शुक्रेष्वासाध्येषु तद्वैवर्ण्यघ्रमञ्जनम् साध्येषु साधनायालमिदमेव च शीलितम्", text: "cūrṇaṃ śukreṣvāsādhyeṣu tadvaivarṇyaghramañjanam sādhyeṣu sādhanāyālamidameva ca śīlitam" },
      { type: "verse", number: "45", sanskrit: "अजकां पार्श्वतो विध्वा सूच्या विस्राव्य चोदकम् समं प्रपीड्याङ्गुष्ठेन वसार्द्रेणानु पूरयेत्", text: "ajakāṃ pārśvato vidhvā sūcyā visrāvya codakam samaṃ prapīḍyāṅguṣṭhena vasārdreṇānu pūrayet" },
      { type: "verse", number: "46", sanskrit: "व्रणं गोमांसचूर्णेन बद्धं बद्धं विमुच्य च सप्तरात्राद्व्रणे रूढे कृष्णभांगे समे स्थिते", text: "vraṇaṃ gomāṃsacūrṇena baddhaṃ baddhaṃ vimucya ca saptarātrādvraṇe rūḍhe kṛṣṇabhāṃge same sthite" },
      { type: "verse", number: "47", sanskrit: "स्नेहाञ्जनं च कर्तव्यं नस्यं च क्षीरसर्पिषा तथापि पुनराध्माते भेदच्छेदादिकां क्रियाम् युक्त्या कुर्याद्यथा नातिच्छेदेन स्यान्निमज्जनम्", text: "snehāñjanaṃ ca kartavyaṃ nasyaṃ ca kṣīrasarpiṣā tathāpi punarādhmāte bhedacchedādikāṃ kriyām yuktyā kuryādyathā nāticchedena syānnimajjanam" },
      { type: "verse", number: "48", sanskrit: "नित्यं च शुक्रेषु शृतं यथास्वं पाने च मर्शे च घृतं विदध्यात् न हीयते लब्धबला तथान्तस्तीक्ष्णाञ्जनैर्दृक् प्रततं प्रयुक्तैः", text: "nityaṃ ca śukreṣu śṛtaṃ yathāsvaṃ pāne ca marśe ca ghṛtaṃ vidadhyāt na hīyate labdhabalā tathāntastīkṣṇāñjanairdṛk pratataṃ prayuktaiḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 15,
    lang: "sa",
    content: [
      { type: "heading", heading: "Гала рога — болезни горла" },
      { type: "text", text: "Глава 15 Уттара стханы — «Гала рога» — посвящена специализированному разделу: болезни горла. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो दृष्टिरोगविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto dṛṣṭirogavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सिरानुसारिणि मले प्रथमं पटलं श्रिते अव्यक्तमीक्षते रूपं व्यक्तमप्यनिमित्ततः", text: "sirānusāriṇi male prathamaṃ paṭalaṃ śrite avyaktamīkṣate rūpaṃ vyaktamapyanimittataḥ" },
      { type: "verse", number: "3", sanskrit: "प्राप्ते द्वितीयं पटलमभूतमपि पश्यति भूतं तु यत्नादासन्नं दूरे सूक्ष्मञ्च नेक्षते", text: "prāpte dvitīyaṃ paṭalamabhūtamapi paśyati bhūtaṃ tu yatnādāsannaṃ dūre sūkṣmañca nekṣate" },
      { type: "verse", number: "4", sanskrit: "दूरान्तिकस्थं रूपञ्च विपर्यासेन मन्यते दोषे मण्डलसंस्थाने मण्डलानीव पश्यति", text: "dūrāntikasthaṃ rūpañca viparyāsena manyate doṣe maṇḍalasaṃsthāne maṇḍalānīva paśyati" },
      { type: "verse", number: "5", sanskrit: "द्विधैकं दृष्टिमध्यस्थे बहुधा बहुधा स्थिते दृष्टेरभ्यन्तरगते द्रस्ववढ्रविपर्ययम्", text: "dvidhaikaṃ dṛṣṭimadhyasthe bahudhā bahudhā sthite dṛṣṭerabhyantaragate drasvavaḍhraviparyayam" },
      { type: "verse", number: "6", sanskrit: "नान्तिकस्थमधस्संस्थे दूरगं नोपरिस्थिते पार्श्वे पश्येन्न पार्श्वस्थे तिमिराख्योयमामयः", text: "nāntikasthamadhassaṃsthe dūragaṃ noparisthite pārśve paśyenna pārśvasthe timirākhyoyamāmayaḥ" },
      { type: "verse", number: "7", sanskrit: "प्राप्तोति काचतां दोषे तृतीयपटलाश्रिते तेनोर्ध्वमीक्षते नाधस्तनुचैलावृतोपमम् यथावर्णञ्च रज्येत दृष्टिर्हीयेत च क्रमात्", text: "prāptoti kācatāṃ doṣe tṛtīyapaṭalāśrite tenordhvamīkṣate nādhastanucailāvṛtopamam yathāvarṇañca rajyeta dṛṣṭirhīyeta ca kramāt" },
      { type: "verse", number: "8", sanskrit: "तथाप्युपेक्षमाणस्य चतुर्थं पटलं गतः लिङ्गनाशं मलः कुर्वन् छादयेद्दृष्टिमण्डलम्", text: "tathāpyupekṣamāṇasya caturthaṃ paṭalaṃ gataḥ liṅganāśaṃ malaḥ kurvan chādayeddṛṣṭimaṇḍalam" },
      { type: "verse", number: "9", sanskrit: "तत्र वातेन तिमिरे व्याविद्धमिव पश्यति चलाविलारुणाभासं प्रसन्नञ्चेक्षते मुहुः", text: "tatra vātena timire vyāviddhamiva paśyati calāvilāruṇābhāsaṃ prasannañcekṣate muhuḥ" },
      { type: "verse", number: "10", sanskrit: "जालानि केशान् मशकान्नश्मींश्चोपोक्षितेत्र च काचीभूते दृगरुणा पश्यत्यास्यमनासिकम्", text: "jālāni keśān maśakānnaśmīṃścopokṣitetra ca kācībhūte dṛgaruṇā paśyatyāsyamanāsikam" },
      { type: "verse", number: "11", sanskrit: "चन्द्रदीपाद्यनेकत्वं वक्रमृज्वपि मन्यते वृद्धः काचो दृशं कुर्याद्रजो धूमावृतामिव", text: "candradīpādyanekatvaṃ vakramṛjvapi manyate vṛddhaḥ kāco dṛśaṃ kuryādrajo dhūmāvṛtāmiva" },
      { type: "verse", number: "12", sanskrit: "स्पष्टारुणाभां विस्तीर्णां सूक्ष्मां वा हतदर्शनाम् सलिङ्गनाशो वाते तु सङ्कोचयति दृक्सिराः दृङ्मण्डलं विशत्यन्तर्गम्भीरा दृगसौ स्मृता", text: "spaṣṭāruṇābhāṃ vistīrṇāṃ sūkṣmāṃ vā hatadarśanām saliṅganāśo vāte tu saṅkocayati dṛksirāḥ dṛṅmaṇḍalaṃ viśatyantargambhīrā dṛgasau smṛtā" },
      { type: "verse", number: "13", sanskrit: "पित्तजे तिमिरे विद्युत्खद्योतोद्योतदीपितम् शिखितित्तिरिपत्राभं प्रायो नीलञ्च पश्यति", text: "pittaje timire vidyutkhadyotodyotadīpitam śikhitittiripatrābhaṃ prāyo nīlañca paśyati" },
      { type: "verse", number: "14", sanskrit: "काचे दृक्कांस्यनीलाभा तादृगेव च पश्यति अर्केन्दुपरिवेषाग्निमरीचीन्द्रधनूंषि च", text: "kāce dṛkkāṃsyanīlābhā tādṛgeva ca paśyati arkendupariveṣāgnimarīcīndradhanūṃṣi ca" },
      { type: "verse", number: "15", sanskrit: "भृङ्गनीला निरालोका दृक्स्निग्धा लिङ्गनाशतः दृष्टिः पित्तेन द्रस्वाख्या सा द्रस्वा द्रस्वदर्शिनी भवेत् पित्तविदग्धाख्या पीता पीताभदर्शना", text: "bhṛṅganīlā nirālokā dṛksnigdhā liṅganāśataḥ dṛṣṭiḥ pittena drasvākhyā sā drasvā drasvadarśinī bhavet pittavidagdhākhyā pītā pītābhadarśanā" },
      { type: "verse", number: "16", sanskrit: "कफेन तिमिरे प्रायः स्निग्धं श्वेतञ्च पश्यति शङ्खेन्दुकुन्दकुसुमैः कुमुदैरिव चाचितम्", text: "kaphena timire prāyaḥ snigdhaṃ śvetañca paśyati śaṅkhendukundakusumaiḥ kumudairiva cācitam" },
      { type: "verse", number: "17", sanskrit: "काचे तु निष्प्रभेन्द्वर्कप्रदीपाद्यैरिवाचितम् सिताभासा च दृष्टिस्स्याल्लिङ्गनाशे तु दृश्यते", text: "kāce tu niṣprabhendvarkapradīpādyairivācitam sitābhāsā ca dṛṣṭissyālliṅganāśe tu dṛśyate" },
      { type: "verse", number: "18", sanskrit: "मूर्तः कफो दृष्टिगतः स्निग्धो दर्शननाशनः बिन्दुर्जलस्येव चलः पद्मिनीपुटसंश्रितः", text: "mūrtaḥ kapho dṛṣṭigataḥ snigdho darśananāśanaḥ bindurjalasyeva calaḥ padminīpuṭasaṃśritaḥ" },
      { type: "verse", number: "19", sanskrit: "उष्णे सङ्कोचमायाति च्छायायां परिसर्पति शङ्खकुन्देदुकुमुदस्फटिकोपमशुक्लिमा", text: "uṣṇe saṅkocamāyāti cchāyāyāṃ parisarpati śaṅkhakundedukumudasphaṭikopamaśuklimā" },
      { type: "verse", number: "20", sanskrit: "रक्तेन तिमिरे रक्तं तमोभूतञ्च पश्यति काचेन रक्ता कृष्णा वा दृष्टिस्तादृक् च पश्यति लिङ्गनाशेपि दृक् तादृङ्निष्प्रभा हतदर्शना", text: "raktena timire raktaṃ tamobhūtañca paśyati kācena raktā kṛṣṇā vā dṛṣṭistādṛk ca paśyati liṅganāśepi dṛk tādṛṅniṣprabhā hatadarśanā" },
      { type: "verse", number: "21", sanskrit: "संसर्गसन्निपातेषु विद्यात् सङ्कीर्णलक्षणान् तिमिरादीनकस्माच्च तैः स्याद्व्यक्ताकुलेक्षणः तिमिरे शेषयोर्दृष्टौ चित्रो रागः प्रजायते", text: "saṃsargasannipāteṣu vidyāt saṅkīrṇalakṣaṇān timirādīnakasmācca taiḥ syādvyaktākulekṣaṇaḥ timire śeṣayordṛṣṭau citro rāgaḥ prajāyate" },
      { type: "verse", number: "22", sanskrit: "द्योतते नकुलस्येव यस्य दृङ्निचिता मलैः नकुलान्धःस तत्राह्नि चित्रं पश्यति नो निशि", text: "dyotate nakulasyeva yasya dṛṅnicitā malaiḥ nakulāndhaḥsa tatrāhni citraṃ paśyati no niśi" },
      { type: "verse", number: "23", sanskrit: "अर्के ऽस्तमस्तकन्यस्तगभस्तौ स्तम्भमागताः स्थगयन्ति दृशं दोषा दोषान्धः स गदोपरः", text: "arke 'stamastakanyastagabhastau stambhamāgatāḥ sthagayanti dṛśaṃ doṣā doṣāndhaḥ sa gadoparaḥ" },
      { type: "verse", number: "24", sanskrit: "दिवाकरकरस्पृष्टा भ्रष्टा दृष्टिपथान्मलाः विलीनलीना यच्छन्ति व्यक्तमत्राह्नि दर्शनम्", text: "divākarakaraspṛṣṭā bhraṣṭā dṛṣṭipathānmalāḥ vilīnalīnā yacchanti vyaktamatrāhni darśanam" },
      { type: "verse", number: "25", sanskrit: "उष्णतप्तस्य सहसा शीतवारिनिमज्जनात् त्रिदोषरक्तसंपृक्तो यात्यूष्मोर्ध्वं ततोक्षिणी दाहोषे मलिनं शुक्रमहन्याविलदर्शनम्", text: "uṣṇataptasya sahasā śītavārinimajjanāt tridoṣaraktasaṃpṛkto yātyūṣmordhvaṃ tatokṣiṇī dāhoṣe malinaṃ śukramahanyāviladarśanam" },
      { type: "verse", number: "26", sanskrit: "रात्रावान्ध्यं च जायेत विदग्धोष्णेन सा स्मृता", text: "rātrāvāndhyaṃ ca jāyeta vidagdhoṣṇena sā smṛtā" },
      { type: "verse", number: "27", sanskrit: "भृशमम्लाशनाद्दोषैस्सास्रैर्या दृष्टिराचिता सक्लेदकण्डूः कलुषा विदग्धाम्लेन सा स्मृता", text: "bhṛśamamlāśanāddoṣaissāsrairyā dṛṣṭirācitā sakledakaṇḍūḥ kaluṣā vidagdhāmlena sā smṛtā" },
      { type: "verse", number: "28", sanskrit: "शोकज्वरशिरोरोगसन्तप्तस्यानिलादयः धूमाविलां धूमदृशं दृशं कुर्युः स धूमरः", text: "śokajvaraśirorogasantaptasyānilādayaḥ dhūmāvilāṃ dhūmadṛśaṃ dṛśaṃ kuryuḥ sa dhūmaraḥ" },
      { type: "verse", number: "29", sanskrit: "सहसैवाल्पसत्वस्य पश्यतो रूपमद्भुतम् भास्वरं भास्करादिं वा वाताद्या नयनाश्रिताः", text: "sahasaivālpasatvasya paśyato rūpamadbhutam bhāsvaraṃ bhāskarādiṃ vā vātādyā nayanāśritāḥ" },
      { type: "verse", number: "30", sanskrit: "कुर्वन्ति तेजः संशोष्य दृष्टिं मुषितदर्शनाम् वैडूर्यवर्णां स्तिमितां प्रकृतिस्थामिवाव्यथाम् औपसर्गिक इत्येष लिङ्गनाशः अत्र वर्जयेत्", text: "kurvanti tejaḥ saṃśoṣya dṛṣṭiṃ muṣitadarśanām vaiḍūryavarṇāṃ stimitāṃ prakṛtisthāmivāvyathām aupasargika ityeṣa liṅganāśaḥ atra varjayet" },
      { type: "verse", number: "31", sanskrit: "विना कफाल्लिङ्गनाशान् गम्भीरां द्रस्वजामपि", text: "vinā kaphālliṅganāśān gambhīrāṃ drasvajāmapi" },
      { type: "verse", number: "32", sanskrit: "षट्काचा नकुलान्धश्च याप्याश्शेषांस्तु साधयेत् द्वादशेति गदा दृष्टौ निर्दिष्टाः सप्तविंशतिः", text: "ṣaṭkācā nakulāndhaśca yāpyāśśeṣāṃstu sādhayet dvādaśeti gadā dṛṣṭau nirdiṣṭāḥ saptaviṃśatiḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 16,
    lang: "sa",
    content: [
      { type: "heading", heading: "Мукха крия — процедуры для рта" },
      { type: "text", text: "Глава 16 Уттара стханы — «Мукха крия» — посвящена специализированному разделу: процедуры для рта. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातस्तिमिरप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātastimirapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "तिमिरं काचतां याति काचो ऽप्यान्ध्यमुपेक्षया नेत्ररोगेष्वतो घोरं तिमिरं साधयेत् द्रुतम्", text: "timiraṃ kācatāṃ yāti kāco 'pyāndhyamupekṣayā netrarogeṣvato ghoraṃ timiraṃ sādhayet drutam" },
      { type: "verse", number: "3", sanskrit: "तुलां पचेत जीवन्त्या द्रोणे ऽपां पादशेषिते तत्क्वाथे द्विगुणक्षीरं घृतप्रस्थं विपाचयेत्", text: "tulāṃ paceta jīvantyā droṇe 'pāṃ pādaśeṣite tatkvāthe dviguṇakṣīraṃ ghṛtaprasthaṃ vipācayet" },
      { type: "verse", number: "4", sanskrit: "प्रपौण्डरीककाकोलीपिप्पलीलोध्रसैन्धवैः शताह्वामधुकद्राक्षा सितादारुफलत्रयैः कार्षिकैर्निशि तत्पीतं तिमिरापहरं परम्", text: "prapauṇḍarīkakākolīpippalīlodhrasaindhavaiḥ śatāhvāmadhukadrākṣā sitādāruphalatrayaiḥ kārṣikairniśi tatpītaṃ timirāpaharaṃ param" },
      { type: "verse", number: "5", sanskrit: "द्राक्षाचन्दनमञ्जिष्ठाकाकोलीद्वयजीवकैः सिताशतावरीमेदापुण्ड्राह्वमधुकोत्पलैः", text: "drākṣācandanamañjiṣṭhākākolīdvayajīvakaiḥ sitāśatāvarīmedāpuṇḍrāhvamadhukotpalaiḥ" },
      { type: "verse", number: "6", sanskrit: "पचेज्जीर्णघृतपस्थं समक्षीरं पिचून्मितैः हन्ति तच्छ्रुक्रतिमिररक्तराजीशिरोरुजः", text: "pacejjīrṇaghṛtapasthaṃ samakṣīraṃ picūnmitaiḥ hanti tacchrukratimiraraktarājīśirorujaḥ" },
      { type: "verse", number: "7", sanskrit: "पटोलनिम्बकटुकादार्वीसेव्यवरावृषम् सधन्वयासत्रायन्तीपर्पटं पालिकं पृथक्", text: "paṭolanimbakaṭukādārvīsevyavarāvṛṣam sadhanvayāsatrāyantīparpaṭaṃ pālikaṃ pṛthak" },
      { type: "verse", number: "8", sanskrit: "प्रस्थमामलकानां च क्वाथयेदर्मणे ऽम्भसः तदाढकेर्धपलिकैः पिष्टैः प्रस्थं घृतात् पचेत्", text: "prasthamāmalakānāṃ ca kvāthayedarmaṇe 'mbhasaḥ tadāḍhakerdhapalikaiḥ piṣṭaiḥ prasthaṃ ghṛtāt pacet" },
      { type: "verse", number: "9", sanskrit: "मुस्तभूनिम्बयष्ट्याह्वकुटयोदीच्यचन्दनैः सव्योषचव्यैस्तत्सर्पिर्घ्राणकर्णाक्षिरोगजित्", text: "mustabhūnimbayaṣṭyāhvakuṭayodīcyacandanaiḥ savyoṣacavyaistatsarpirghrāṇakarṇākṣirogajit" },
      { type: "verse", number: "10", sanskrit: "विद्रधिज्वरदुष्टारुर्विसर्पापचिकुष्ठनुत् विशेषाच्छ्रुक्रतिमिरनक्तान्ध्योष्णाम्लदाहहृत्", text: "vidradhijvaraduṣṭārurvisarpāpacikuṣṭhanut viśeṣācchrukratimiranaktāndhyoṣṇāmladāhahṛt" },
      { type: "verse", number: "11", sanskrit: "त्रिफलाष्टपलं क्वाथ्यं पादशेषं जलाढके तेन तुल्यपयस्केन त्रिफलापलकल्कवान्", text: "triphalāṣṭapalaṃ kvāthyaṃ pādaśeṣaṃ jalāḍhake tena tulyapayaskena triphalāpalakalkavān" },
      { type: "verse", number: "12", sanskrit: "अर्धप्रस्थो घृतात्सिद्धः सितया माक्षिकेण वा युक्तं पिबेत्तत्तिमिरी तद्युक्तं वा वरारसम्", text: "ardhaprastho ghṛtātsiddhaḥ sitayā mākṣikeṇa vā yuktaṃ pibettattimirī tadyuktaṃ vā varārasam" },
      { type: "verse", number: "13", sanskrit: "यष्टीमधुद्विकाकोलीव्याघ्रीकृष्णामृतोत्पलैः पालिकैः ससिताद्राक्षैर्घृतप्रस्थं पचेत् समैः", text: "yaṣṭīmadhudvikākolīvyāghrīkṛṣṇāmṛtotpalaiḥ pālikaiḥ sasitādrākṣairghṛtaprasthaṃ pacet samaiḥ" },
      { type: "verse", number: "14", sanskrit: "अजाक्षीरवरावासामार्कवस्वरसैः पृथक् महात्रैफलमित्येतत् परं दृष्टिविकारजित्", text: "ajākṣīravarāvāsāmārkavasvarasaiḥ pṛthak mahātraiphalamityetat paraṃ dṛṣṭivikārajit" },
      { type: "verse", number: "15", sanskrit: "त्रैफलेनाथ हविषा लिहानस्त्रिफलां निशि यष्टीमधुकसंयुक्तां मधुना च परिप्लुताम्", text: "traiphalenātha haviṣā lihānastriphalāṃ niśi yaṣṭīmadhukasaṃyuktāṃ madhunā ca pariplutām" },
      { type: "verse", number: "16", sanskrit: "मासमेकं हिताहारः पिबन्नामलकोदकम् सौपर्णं लभते चक्षुरित्याह भगवान् निमिः", text: "māsamekaṃ hitāhāraḥ pibannāmalakodakam sauparṇaṃ labhate cakṣurityāha bhagavān nimiḥ" },
      { type: "verse", number: "17", sanskrit: "गव्यं घृतं लोहरजो भाजने बादरे स्थितम् त्रिफलाचूर्णसहितं पीतं तिमिरनाशनम्", text: "gavyaṃ ghṛtaṃ loharajo bhājane bādare sthitam triphalācūrṇasahitaṃ pītaṃ timiranāśanam" },
      { type: "verse", number: "18", sanskrit: "पुराणं च सिताभीरुयष्टीमधुकचूर्णवत् निषिक्तमग्निवर्णैर्वा जीर्णं सर्पिरयोगुडैः", text: "purāṇaṃ ca sitābhīruyaṣṭīmadhukacūrṇavat niṣiktamagnivarṇairvā jīrṇaṃ sarpirayoguḍaiḥ" },
      { type: "verse", number: "19", sanskrit: "हेमरूप्यायसैश्चूर्णैर्युक्तां वा त्रिफलां पृथक् घृतक्षौद्रान्वितामद्यात् केवलां वा विचूर्णिताम्", text: "hemarūpyāyasaiścūrṇairyuktāṃ vā triphalāṃ pṛthak ghṛtakṣaudrānvitāmadyāt kevalāṃ vā vicūrṇitām" },
      { type: "verse", number: "20", sanskrit: "ताप्यायस्त्रिफलाचूर्णं मधुजीर्णघृतद्रुतम् लोहपात्रे स्थितं मासं माषराशौ च भक्षयेत्", text: "tāpyāyastriphalācūrṇaṃ madhujīrṇaghṛtadrutam lohapātre sthitaṃ māsaṃ māṣarāśau ca bhakṣayet" },
      { type: "verse", number: "21", sanskrit: "सक्तून् वाद्यात्ससर्पिष्कांस्त्रिफलाचूर्णसंयुतान् भुञ्जीत वा सुसिद्धेन सूपेनामलकैः सह", text: "saktūn vādyātsasarpiṣkāṃstriphalācūrṇasaṃyutān bhuñjīta vā susiddhena sūpenāmalakaiḥ saha" },
      { type: "verse", number: "22", sanskrit: "प्रातर्भक्तस्य वा पूर्वमद्यात् पथ्यां पृथक् पृथक् मृद्वीकाशर्कराक्षौद्रैः सततं तिमिरातुरः", text: "prātarbhaktasya vā pūrvamadyāt pathyāṃ pṛthak pṛthak mṛdvīkāśarkarākṣaudraiḥ satataṃ timirāturaḥ" },
      { type: "verse", number: "23", sanskrit: "क्वाथोसनात् भृङ्गरसस्तैलं कालतिलोद्भवम् लोहपात्रे तदेकत्र साधितं नावनं हितम्", text: "kvāthosanāt bhṛṅgarasastailaṃ kālatilodbhavam lohapātre tadekatra sādhitaṃ nāvanaṃ hitam" },
      { type: "verse", number: "24", sanskrit: "स्रोतोजांशांश्चतुष्षष्टिं हेमायोरूप्यताम्रकैः युक्तान् प्रत्येकमेकांशैरन्धमूषोदरस्थितान्", text: "srotojāṃśāṃścatuṣṣaṣṭiṃ hemāyorūpyatāmrakaiḥ yuktān pratyekamekāṃśairandhamūṣodarasthitān" },
      { type: "verse", number: "25", sanskrit: "ध्मापयित्वा समावृत्तं ततस्तच्च निषेचयेत् रसस्कन्धकषायेण सप्तकृत्वः पृत्थक् पृथक्", text: "dhmāpayitvā samāvṛttaṃ tatastacca niṣecayet rasaskandhakaṣāyeṇa saptakṛtvaḥ pṛtthak pṛthak" },
      { type: "verse", number: "26", sanskrit: "वैडूर्यमुक्ताशङ्खानां त्रिभिर्भागैर्युतं ततः चूर्णाञ्जनं प्रयुञ्जीत तत्सर्वतिमिरापहम्", text: "vaiḍūryamuktāśaṅkhānāṃ tribhirbhāgairyutaṃ tataḥ cūrṇāñjanaṃ prayuñjīta tatsarvatimirāpaham" },
      { type: "verse", number: "27", sanskrit: "निर्दग्धं बदराङ्गारैस्तुत्थं चेत्थं निषेचितम् क्रमादजापयः सर्पिः क्षौद्रैस्तस्मात् पलद्वयम्", text: "nirdagdhaṃ badarāṅgāraistutthaṃ cetthaṃ niṣecitam kramādajāpayaḥ sarpiḥ kṣaudraistasmāt paladvayam" },
      { type: "verse", number: "28", sanskrit: "कार्षिकैस्ताप्यमरिचस्रोतोजकटुकानतैः पटुलोध्रशिलापथ्याकणैलाञ्जनफेनकैः", text: "kārṣikaistāpyamaricasrotojakaṭukānataiḥ paṭulodhraśilāpathyākaṇailāñjanaphenakaiḥ" },
      { type: "verse", number: "29", sanskrit: "युक्तं पलेन यष्ट्याश्च मूषान्तर्ध्मातचूर्णितम् हन्ति काचार्मनक्तान्ध्यरक्तराजीः सुशीलितः चूर्णो विशेषात्तिमिरं भास्करो भास्करो यथा", text: "yuktaṃ palena yaṣṭyāśca mūṣāntardhmātacūrṇitam hanti kācārmanaktāndhyaraktarājīḥ suśīlitaḥ cūrṇo viśeṣāttimiraṃ bhāskaro bhāskaro yathā" },
      { type: "verse", number: "30", sanskrit: "मनोह्वासैन्ध्हवव्योषशङ्खनाभीरसाञ्जनम् कतकं चन्दनं फेनो विडङ्गानि सितोपला", text: "manohvāsaindhhavavyoṣaśaṅkhanābhīrasāñjanam katakaṃ candanaṃ pheno viḍaṅgāni sitopalā" },
      { type: "verse", number: "31", sanskrit: "कुक्कुटाण्डकपालं च जलपिष्टा सुखावती हन्त्येषा मधुना घृष्टा काचतैमिर्यशुक्लकान्", text: "kukkuṭāṇḍakapālaṃ ca jalapiṣṭā sukhāvatī hantyeṣā madhunā ghṛṣṭā kācataimiryaśuklakān" },
      { type: "verse", number: "32", sanskrit: "त्रिफलाकुक्कुटाण्डत्वक्कासीसमयसो रजः नीलोत्पलं विडङ्गानि फेनं च सरितां पतेः", text: "triphalākukkuṭāṇḍatvakkāsīsamayaso rajaḥ nīlotpalaṃ viḍaṅgāni phenaṃ ca saritāṃ pateḥ" },
      { type: "verse", number: "33", sanskrit: "आजेन पयसा पिष्ट्वा लेपयेत्ताम्रभाजनम् सप्तरात्रे गते भूयः पिष्टं क्षीरेण वर्तयेत् एषा दृष्टिप्रदा वर्तिरपि स्याद्भिन्नचक्षुषः", text: "ājena payasā piṣṭvā lepayettāmrabhājanam saptarātre gate bhūyaḥ piṣṭaṃ kṣīreṇa vartayet eṣā dṛṣṭipradā vartirapi syādbhinnacakṣuṣaḥ" },
      { type: "verse", number: "34", sanskrit: "अञ्जनं कृष्णसर्पास्ये निहितं कुशवेष्टिते ततस्ततः समुद्वृत्य मासात् सञ्चूर्णयेत् सह", text: "añjanaṃ kṛṣṇasarpāsye nihitaṃ kuśaveṣṭite tatastataḥ samudvṛtya māsāt sañcūrṇayet saha" },
      { type: "verse", number: "35", sanskrit: "सुमनःक्षारकैः शुष्कैरर्धांशैः सैन्धवेन च प्रयोजयेद्रागवति तिमिरे तद्वराञ्जनम्", text: "sumanaḥkṣārakaiḥ śuṣkairardhāṃśaiḥ saindhavena ca prayojayedrāgavati timire tadvarāñjanam" },
      { type: "verse", number: "36", sanskrit: "पयसा त्रयमेतच्च चूर्णयित्वा सुभावितम्", text: "payasā trayametacca cūrṇayitvā subhāvitam" },
      { type: "verse", number: "37", sanskrit: "सामान्यं साधनं त्वेतत्प्रतिदोषमतः शृणु", text: "sāmānyaṃ sādhanaṃ tvetatpratidoṣamataḥ śṛṇu" },
      { type: "verse", number: "38", sanskrit: "वातजे तिमिरे तत्र दशमूलाम्भसा घृतम् क्षीरे चतुर्गुणे श्रेष्ठाकल्कपक्वं पिबेत्ततः", text: "vātaje timire tatra daśamūlāmbhasā ghṛtam kṣīre caturguṇe śreṣṭhākalkapakvaṃ pibettataḥ" },
      { type: "verse", number: "39", sanskrit: "त्रिफलापञ्चमूलानां कषायं क्षीरसंयुतम् एरण्डतैलसंयुक्तं योजयेत विरेचनम्", text: "triphalāpañcamūlānāṃ kaṣāyaṃ kṣīrasaṃyutam eraṇḍatailasaṃyuktaṃ yojayeta virecanam" },
      { type: "verse", number: "40", sanskrit: "शङ्खिनीतिल्वकश्यामादन्तीर्निष्काथ्य वा जले त्रिवृत्कल्कप्रतीवापं तेन पक्वं घृतं पिबेत्", text: "śaṅkhinītilvakaśyāmādantīrniṣkāthya vā jale trivṛtkalkapratīvāpaṃ tena pakvaṃ ghṛtaṃ pibet" },
      { type: "verse", number: "41", sanskrit: "प्रपौण्डरीकबृहतीबलानलदसैन्धवैः दारुबिल्वाडकीकृष्णा हरिद्द्रामधुयष्टिभिः सिद्धं चतुर्गुणक्षीरं तैलं नस्तो निषेचयेत्", text: "prapauṇḍarīkabṛhatībalānaladasaindhavaiḥ dārubilvāḍakīkṛṣṇā hariddrāmadhuyaṣṭibhiḥ siddhaṃ caturguṇakṣīraṃ tailaṃ nasto niṣecayet" },
      { type: "verse", number: "42", sanskrit: "सितैरण्डजटासिंहीफलदारुनिशानतैः शताह्वाबिल्वमूलैश्च तैलं पक्वं पयो ऽन्वितम् नस्यं सर्वोर्ध्वजत्रूत्थवातश्लेष्मामयार्तिषु", text: "sitairaṇḍajaṭāsiṃhīphaladāruniśānataiḥ śatāhvābilvamūlaiśca tailaṃ pakvaṃ payo 'nvitam nasyaṃ sarvordhvajatrūtthavātaśleṣmāmayārtiṣu" },
      { type: "verse", number: "43", sanskrit: "वसाञ्जने च वैयाघ्री वाराही वा प्रशस्यते गृध्राहिकुक्कुटोत्था वा मधुकेनान्विता पृथक्", text: "vasāñjane ca vaiyāghrī vārāhī vā praśasyate gṛdhrāhikukkuṭotthā vā madhukenānvitā pṛthak" },
      { type: "verse", number: "44", sanskrit: "प्रत्यञ्जनं च स्रोतोजं रसक्षीरघृतैः क्रमात् निषिक्तं पूर्ववद्योज्यं तिमिरघ्नमनुत्तमम्", text: "pratyañjanaṃ ca srotojaṃ rasakṣīraghṛtaiḥ kramāt niṣiktaṃ pūrvavadyojyaṃ timiraghnamanuttamam" },
      { type: "verse", number: "45", sanskrit: "नचेदेवं शमं याति ततस्तर्पणमाचरेत्", text: "nacedevaṃ śamaṃ yāti tatastarpaṇamācaret" },
      { type: "verse", number: "46", sanskrit: "शताह्वाकुष्ठनलदकाकोलीद्वययष्टिभिः प्रपौण्डरीकसरलपिप्पलीदेवदारुभिः सर्पिरष्टगुणक्षीरं पक्वं तर्पणमुत्तमम्", text: "śatāhvākuṣṭhanaladakākolīdvayayaṣṭibhiḥ prapauṇḍarīkasaralapippalīdevadārubhiḥ sarpiraṣṭaguṇakṣīraṃ pakvaṃ tarpaṇamuttamam" },
      { type: "verse", number: "47", sanskrit: "प्रसादनं स्नेहनं च पुटपाकं प्रयोजयेत्", text: "prasādanaṃ snehanaṃ ca puṭapākaṃ prayojayet" },
      { type: "verse", number: "48", sanskrit: "वातपीनसवच्चात्र निरूहं सानुवासनम्", text: "vātapīnasavaccātra nirūhaṃ sānuvāsanam" },
      { type: "verse", number: "49", sanskrit: "पित्तजे तिमिरे सर्पिर्जीवनीयफलत्रयैः विपाचितं पाययित्वा स्निग्धस्य व्यधयेत्सिराम् शर्करैलात्रिवृच्चूर्णैर्मधुयुक्तैर्विरेचयेत्", text: "pittaje timire sarpirjīvanīyaphalatrayaiḥ vipācitaṃ pāyayitvā snigdhasya vyadhayetsirām śarkarailātrivṛccūrṇairmadhuyuktairvirecayet" },
      { type: "verse", number: "50", sanskrit: "मञ्जिष्ठालोध्रमधुकसारिवाचन्दनैः शृतम् जलं सशर्करास्तन्यं नेत्रसेके प्रशस्यते", text: "mañjiṣṭhālodhramadhukasārivācandanaiḥ śṛtam jalaṃ saśarkarāstanyaṃ netraseke praśasyate" },
      { type: "verse", number: "51", sanskrit: "स्तन्यं वा पद्मकोशीरक्षीरिवृक्षाङ्कुरैः शृतम् तप्तैर्निर्वापितं सर्पिरसकृल्लोहपिण्डकैः", text: "stanyaṃ vā padmakośīrakṣīrivṛkṣāṅkuraiḥ śṛtam taptairnirvāpitaṃ sarpirasakṛllohapiṇḍakaiḥ" },
      { type: "verse", number: "52", sanskrit: "विमर्दितसिताद्राक्षं हिमं तच्चाक्षिसेचनम् शीतानालेपसेकादीन् मुखे मूर्ध्नि च शीलयेत्", text: "vimarditasitādrākṣaṃ himaṃ taccākṣisecanam śītānālepasekādīn mukhe mūrdhni ca śīlayet" },
      { type: "verse", number: "53", sanskrit: "सारिवापद्मकोशीरमुस्ताशाबरचन्दनैः वर्तिः शस्ताञ्जने चूर्णस्तथा पद्मोत्पलाञ्जनैः सनागपुष्पकर्पूरयष्ट्याह्वस्वर्णगौरिकैः", text: "sārivāpadmakośīramustāśābaracandanaiḥ vartiḥ śastāñjane cūrṇastathā padmotpalāñjanaiḥ sanāgapuṣpakarpūrayaṣṭyāhvasvarṇagaurikaiḥ" },
      { type: "verse", number: "54", sanskrit: "लोध्रमूर्वाप्रपुण्ड्राह्वमांसीयष्ट्याह्वचन्दनैः सोशीरैः साधितं सर्पिः सक्षीरं तर्पणं हितम्", text: "lodhramūrvāprapuṇḍrāhvamāṃsīyaṣṭyāhvacandanaiḥ sośīraiḥ sādhitaṃ sarpiḥ sakṣīraṃ tarpaṇaṃ hitam" },
      { type: "verse", number: "55", sanskrit: "एभिरेवौषधैश्छागे पक्वे यकृति तद्रसे पूर्ववत् पुटपाकश्च कार्यस्तिमिरनाशनः", text: "ebhirevauṣadhaiśchāge pakve yakṛti tadrase pūrvavat puṭapākaśca kāryastimiranāśanaḥ" },
      { type: "verse", number: "56", sanskrit: "श्लेष्मोद्भवे ऽमृताक्वाथवराकणशृतं घृतम् विध्येत् सिरां पीतवतो दद्याच्चानु विरेचनम् क्वाथं पूगाभयाशुण्ठीकृष्णाकुम्भनिकुम्भजम्", text: "śleṣmodbhave 'mṛtākvāthavarākaṇaśṛtaṃ ghṛtam vidhyet sirāṃ pītavato dadyāccānu virecanam kvāthaṃ pūgābhayāśuṇṭhīkṛṣṇākumbhanikumbhajam" },
      { type: "verse", number: "57", sanskrit: "करञ्जकट्फलवचात्रिफलापञ्चकोलकैः सदार्वीकैः पयो युक्तं सिद्धं तैलं च नावनम्", text: "karañjakaṭphalavacātriphalāpañcakolakaiḥ sadārvīkaiḥ payo yuktaṃ siddhaṃ tailaṃ ca nāvanam" },
      { type: "verse", number: "58", sanskrit: "शङ्खप्रियङ्गुनैपालीकटुत्रिकफत्रिकैः दृग्वैमल्याय विमला वर्तिः स्यात् कोकिला पुनः", text: "śaṅkhapriyaṅgunaipālīkaṭutrikaphatrikaiḥ dṛgvaimalyāya vimalā vartiḥ syāt kokilā punaḥ" },
      { type: "verse", number: "59", sanskrit: "कृष्णलोहरजोव्योषसैन्धवत्रिफलाञ्जनैः पीताख्या द्विनिशाकुष्ठनतपत्रकणोषणैः", text: "kṛṣṇaloharajovyoṣasaindhavatriphalāñjanaiḥ pītākhyā dviniśākuṣṭhanatapatrakaṇoṣaṇaiḥ" },
      { type: "verse", number: "60", sanskrit: "पत्रपीतावराव्योषशिलालनतसैन्धवैः", text: "patrapītāvarāvyoṣaśilālanatasaindhavaiḥ" },
      { type: "verse", number: "61", sanskrit: "मनोह्वाशङ्खसिन्धूत्थमरिचैस्तिमिरं जयेत् वर्तिः प्रगाढमप्याशु शुक्रपिल्लामयार्म च", text: "manohvāśaṅkhasindhūtthamaricaistimiraṃ jayet vartiḥ pragāḍhamapyāśu śukrapillāmayārma ca" },
      { type: "verse", number: "62", sanskrit: "तालीसपाठाकिणिहीवेल्लमांसीनिशाभयैः पिष्टैः क्षीरिद्रुमक्वाथे घृतं सिद्धं च तर्पणम्", text: "tālīsapāṭhākiṇihīvellamāṃsīniśābhayaiḥ piṣṭaiḥ kṣīridrumakvāthe ghṛtaṃ siddhaṃ ca tarpaṇam" },
      { type: "verse", number: "63", sanskrit: "पुटपाकं च पिशितैर्जाङ्गलैः सैन्धवान्वितैः सपिप्पलीमधुघृतैः कल्कितैः प्रागिवाचरेत्", text: "puṭapākaṃ ca piśitairjāṅgalaiḥ saindhavānvitaiḥ sapippalīmadhughṛtaiḥ kalkitaiḥ prāgivācaret" },
      { type: "verse", number: "64", sanskrit: "शिग्रुपत्रैर्जलस्विन्नैः कार्यः स्वेदश्च मात्रया", text: "śigrupatrairjalasvinnaiḥ kāryaḥ svedaśca mātrayā" },
      { type: "verse", number: "65", sanskrit: "रक्तजे पित्तवत् कार्यं सन्निपाते यथोल्बणम्", text: "raktaje pittavat kāryaṃ sannipāte yatholbaṇam" },
      { type: "verse", number: "66", sanskrit: "व्याघ्रर्ष्यगोशिखिवसा यवक्वाथपयोयुता दूर्वामधुककल्केन विपक्वा तर्पणे हिता", text: "vyāghrarṣyagośikhivasā yavakvāthapayoyutā dūrvāmadhukakalkena vipakvā tarpaṇe hitā" },
      { type: "verse", number: "67", sanskrit: "यष्ट्यनन्ताद्विबृहतीपिप्पलीलवणद्वयैः सलोहचन्दनैः पक्वं यकृता शल्यकस्य च मृगगोधाशशानां च पुटपाकं प्रकल्पयेत्", text: "yaṣṭyanantādvibṛhatīpippalīlavaṇadvayaiḥ salohacandanaiḥ pakvaṃ yakṛtā śalyakasya ca mṛgagodhāśaśānāṃ ca puṭapākaṃ prakalpayet" },
      { type: "verse", number: "68", sanskrit: "दद्यादुशीरनिर्यूहे चूर्णितं कणसैन्धवम् तत्स्रुतं सघृतं भूयः पचेत् क्षौद्रं क्षिपेद्धने शीते चास्मिन् हितमिदं सर्वजे तिमिरे ऽञ्जनम्", text: "dadyāduśīraniryūhe cūrṇitaṃ kaṇasaindhavam tatsrutaṃ saghṛtaṃ bhūyaḥ pacet kṣaudraṃ kṣipeddhane śīte cāsmin hitamidaṃ sarvaje timire 'ñjanam" },
      { type: "verse", number: "69", sanskrit: "कुष्ठं वा शर्करोपेतमान्तरिक्षेण वारिणा निष्काथ्यं सर्पिःक्षौद्राभ्यां संसृष्टं प्रागिवाञ्जनम्", text: "kuṣṭhaṃ vā śarkaropetamāntarikṣeṇa vāriṇā niṣkāthyaṃ sarpiḥkṣaudrābhyāṃ saṃsṛṣṭaṃ prāgivāñjanam" },
      { type: "verse", number: "70", sanskrit: "स्रोतो ऽञ्जनं ससौवीरं वेष्टयित्वाजमेदसा वटपत्रैरनु तथा दर्भैः कृष्णमृदानु च गोमयानलपक्वं तत् प्रशस्तं चूर्णमञ्जनम्", text: "sroto 'ñjanaṃ sasauvīraṃ veṣṭayitvājamedasā vaṭapatrairanu tathā darbhaiḥ kṛṣṇamṛdānu ca gomayānalapakvaṃ tat praśastaṃ cūrṇamañjanam" },
      { type: "verse", number: "71", sanskrit: "उरभ्रशल्यकश्वाविण्मार्जारशिखिजन्ममिः वसाभिर्विधिनानेन योगा योज्याः पृथक् पृथक्", text: "urabhraśalyakaśvāviṇmārjāraśikhijanmamiḥ vasābhirvidhinānena yogā yojyāḥ pṛthak pṛthak" },
      { type: "verse", number: "72", sanskrit: "वटप्ररोहमधुकदूर्वालोध्रतिलोत्पलैः वयोम्बुपिष्टैः सघृतैः शिरो वक्त्रं च लेपयेत्", text: "vaṭaprarohamadhukadūrvālodhratilotpalaiḥ vayombupiṣṭaiḥ saghṛtaiḥ śiro vaktraṃ ca lepayet" },
      { type: "verse", number: "73", sanskrit: "कुर्याच्छिरः परीषेकमेभिरेव पयःशृतैः", text: "kuryācchiraḥ parīṣekamebhireva payaḥśṛtaiḥ" },
      { type: "verse", number: "74", sanskrit: "सन्निपाते यदुदितं दोषोद्रेकं विभज्य तत् संसर्गे ऽपि प्रयुञ्जीत काचे तिमिरवत् क्रिया", text: "sannipāte yaduditaṃ doṣodrekaṃ vibhajya tat saṃsarge 'pi prayuñjīta kāce timiravat kriyā" },
      { type: "verse", number: "75", sanskrit: "न तु तत्र सिरां विध्येत् दृक्स्थिता यन्त्रपीडनात् कुर्युरान्ध्यं मला दद्यात् स्रव्ये त्वस्रे जलौकसः", text: "na tu tatra sirāṃ vidhyet dṛksthitā yantrapīḍanāt kuryurāndhyaṃ malā dadyāt sravye tvasre jalaukasaḥ" },
      { type: "verse", number: "76", sanskrit: "धूमराख्याम्लपित्तोष्णविदाहे जीर्णसर्पिषा स्निग्धं विरेचयेच्छीतैश्शीतैर्दिह्या च सर्वतः", text: "dhūmarākhyāmlapittoṣṇavidāhe jīrṇasarpiṣā snigdhaṃ virecayecchītaiśśītairdihyā ca sarvataḥ" },
      { type: "verse", number: "77", sanskrit: "गोशकृद्रसदुग्धाज्यैर्विपक्वं शस्यते ऽञ्जनम् स्वर्णगौरिकतालीसचूर्णावापा रसक्रिया", text: "gośakṛdrasadugdhājyairvipakvaṃ śasyate 'ñjanam svarṇagaurikatālīsacūrṇāvāpā rasakriyā" },
      { type: "verse", number: "78", sanskrit: "पुराणगुडकासीसपिप्पलीकट्फलाद्रजः भावितं त्रिफलाम्भोभिः शुष्कं गोविड्रसाप्लुतम् निशान्ध्वतिमिरे सद्यो गुटिका हन्ति तत्कृता", text: "purāṇaguḍakāsīsapippalīkaṭphalādrajaḥ bhāvitaṃ triphalāmbhobhiḥ śuṣkaṃ goviḍrasāplutam niśāndhvatimire sadyo guṭikā hanti tatkṛtā" },
      { type: "verse", number: "79", sanskrit: "दध्ना विघृष्टं मरिचं रात्र्यन्धांजनमुत्तमम् भृष्टं घृतं कुम्भयोनेः पत्रैः पाने च पूजितम्", text: "dadhnā vighṛṣṭaṃ maricaṃ rātryandhāṃjanamuttamam bhṛṣṭaṃ ghṛtaṃ kumbhayoneḥ patraiḥ pāne ca pūjitam" },
      { type: "verse", number: "80", sanskrit: "कारञ्जिकोत्पलस्वर्णगौरिकाम्भोजकेसरैः गोविड्रसेन पिष्टेयं वर्तिर्नक्तान्ध्यनाशिनी", text: "kārañjikotpalasvarṇagaurikāmbhojakesaraiḥ goviḍrasena piṣṭeyaṃ vartirnaktāndhyanāśinī" },
      { type: "verse", number: "81", sanskrit: "क्षौद्रजातीरसाभ्यां वा द्विहरिद्रारसाञ्जनैः अजामूत्रेण वा कौन्तीकृष्णास्त्रोतोजसैन्धवैः", text: "kṣaudrajātīrasābhyāṃ vā dviharidrārasāñjanaiḥ ajāmūtreṇa vā kauntīkṛṣṇāstrotojasaindhavaiḥ" },
      { type: "verse", number: "82", sanskrit: "गोशकृद्रसपिष्टैर्वा द्विनिशापिप्पलीयुतैः कालानुसारीतालीसपत्रयष्ट्याह्वनागरैः", text: "gośakṛdrasapiṣṭairvā dviniśāpippalīyutaiḥ kālānusārītālīsapatrayaṣṭyāhvanāgaraiḥ" },
      { type: "verse", number: "83", sanskrit: "कणा वा कापिले पित्ते मासार्धं परिभाविता यकृत्पित्तेषु वा गोधाशशर्ष्यरुरुबर्हिणाम्", text: "kaṇā vā kāpile pitte māsārdhaṃ paribhāvitā yakṛtpitteṣu vā godhāśaśarṣyarurubarhiṇām" },
      { type: "verse", number: "84", sanskrit: "खादेच्च प्लीहयकृती माहिषे तैलसर्पिषा घृते सिद्धानि जीवन्त्याः पल्लवानि च भक्षयेत् तथातिमुक्तकैरण्डसोहलाभीरुजानि च", text: "khādecca plīhayakṛtī māhiṣe tailasarpiṣā ghṛte siddhāni jīvantyāḥ pallavāni ca bhakṣayet tathātimuktakairaṇḍasohalābhīrujāni ca" },
      { type: "verse", number: "85", sanskrit: "व्रणवच्चाक्षिरोगेषु भोज्याभोज्यानि निर्दिशेत्", text: "vraṇavaccākṣirogeṣu bhojyābhojyāni nirdiśet" },
      { type: "verse", number: "86", sanskrit: "अविधारितवेगस्य भजतो ऽञ्जननावनम् त्यजतः क्रोधशोकौ च तिमिरं नाश्नुते ऽन्तरम्", text: "avidhāritavegasya bhajato 'ñjananāvanam tyajataḥ krodhaśokau ca timiraṃ nāśnute 'ntaram" },
      { type: "verse", number: "87", sanskrit: "त्रिफलामश्नतो रात्रौ संस्कृतं पिबतो घृतम् भुक्त्वा चापिबतस्तोयं तिमिरं लघु शाम्यति", text: "triphalāmaśnato rātrau saṃskṛtaṃ pibato ghṛtam bhuktvā cāpibatastoyaṃ timiraṃ laghu śāmyati" },
      { type: "verse", number: "88", sanskrit: "सुषभव्यं सुकन्यां च स्कन्दं च्यवनमश्विनौ पडेतान् यः स्मरेन्नित्यं तस्य चक्षुर्न हीयते", text: "suṣabhavyaṃ sukanyāṃ ca skandaṃ cyavanamaśvinau paḍetān yaḥ smarennityaṃ tasya cakṣurna hīyate" },
      { type: "verse", number: "89", sanskrit: "चिन्ताभिघातभीशोकरौक्ष्यामोत्कुटिकासनात् विरेकनस्यवमनपुटपाकादिविभ्रमात्", text: "cintābhighātabhīśokaraukṣyāmotkuṭikāsanāt virekanasyavamanapuṭapākādivibhramāt" },
      { type: "verse", number: "90", sanskrit: "विदग्धाहारवमनात् क्षुत्तृष्णादिविधारणात् अक्षिरोगावसानाच्च पश्येत्तिमिररोगिवत्", text: "vidagdhāhāravamanāt kṣuttṛṣṇādividhāraṇāt akṣirogāvasānācca paśyettimirarogivat" },
      { type: "verse", number: "91", sanskrit: "सूर्योपरागानलविद्युदादिविलोकनेनोपहतेक्षणस्य सन्तर्पणं स्निग्धहिमादि योज्यं तथाञ्जनं हेम घृतेन घृष्टम्", text: "sūryoparāgānalavidyudādivilokanenopahatekṣaṇasya santarpaṇaṃ snigdhahimādi yojyaṃ tathāñjanaṃ hema ghṛtena ghṛṣṭam" },
      { type: "verse", number: "92", sanskrit: "चक्षूरक्षायां सर्वकालं मनुष्यैर्यत्नः कर्तव्यो जीविते यावदिच्छा व्यार्थो लोको ऽयं तुल्यरात्रिन्दिवानां पुंसामन्धानां विद्यामाने ऽपि वित्ते", text: "cakṣūrakṣāyāṃ sarvakālaṃ manuṣyairyatnaḥ kartavyo jīvite yāvadicchā vyārtho loko 'yaṃ tulyarātrindivānāṃ puṃsāmandhānāṃ vidyāmāne 'pi vitte" },
      { type: "verse", number: "93", sanskrit: "त्रिफलारुधिरस्रुतिर्विशुद्धिर्मनसो निर्वृतिरञ्जनं सनस्यम् शकुनाशनता सपादपूजा घृतपानं च सदैव नेत्ररक्षा", text: "triphalārudhirasrutirviśuddhirmanaso nirvṛtirañjanaṃ sanasyam śakunāśanatā sapādapūjā ghṛtapānaṃ ca sadaiva netrarakṣā" },
      { type: "verse", number: "94", sanskrit: "अहितादशनात् सदा निवृत्तिर्भृशभास्वच्चलसूक्ष्मवीक्षणाच्च मुनिना निमिनोपदिष्टमेतत् परमं रक्षणमीक्षणस्य पुंसाम्", text: "ahitādaśanāt sadā nivṛttirbhṛśabhāsvaccalasūkṣmavīkṣaṇācca muninā niminopadiṣṭametat paramaṃ rakṣaṇamīkṣaṇasya puṃsām" },
      { type: "verse", number: "95", sanskrit: "तमालतृटिकुङ्कुमान्यसितमुत्पलं पिप्पली सिताञ्जनमयोरजो मरिचकाकमाचीत्वचः सयष्टिमधुकाञ्जनान्युदधिफेनमक्ष्यामयेष्वनुत्तममतो ऽञ्जनं विमलमाशु तैमिर्यहृत्", text: "tamālatṛṭikuṅkumānyasitamutpalaṃ pippalī sitāñjanamayorajo maricakākamācītvacaḥ sayaṣṭimadhukāñjanānyudadhiphenamakṣyāmayeṣvanuttamamato 'ñjanaṃ vimalamāśu taimiryahṛt" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 17,
    lang: "sa",
    content: [
      { type: "heading", heading: "Шваса каса рога — одышка и кашель" },
      { type: "text", text: "Глава 17 Уттара стханы — «Шваса каса рога» — посвящена специализированному разделу: одышка и кашель. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो लिङ्गनाशप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयोमहर्षयः", text: "athāto liṅganāśapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayomaharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "लिङ्गनाशे नीलिका पटलमान्ध्यमिति पर्यायाः सः श्लैष्मिक एव प्राक् साध्यो ऽभिहितः तस्य पुनः षडुपद्रवाः आवर्तकी शर्करा राजीमती छिन्नांशुका चन्द्रकी छत्रकी चेति", text: "liṅganāśe nīlikā paṭalamāndhyamiti paryāyāḥ saḥ ślaiṣmika eva prāk sādhyo 'bhihitaḥ tasya punaḥ ṣaḍupadravāḥ āvartakī śarkarā rājīmatī chinnāṃśukā candrakī chatrakī ceti" },
      { type: "verse", number: "3", sanskrit: "तत्र श्वेतारुणावर्तवदनवस्थिता दृष्टिरावर्तकी अर्कक्षीरलेशेनेव कूर्चिकापिण्डेनेव चाचिता शर्करा शालिशूकाभराज्यावृता राजीमती छिन्नविषमदग्धाभा सरुक् छिन्नांशुका कांस्यसमच्छाया चन्द्रकसंस्थाना चन्द्रकी नैकवर्णा छत्रनिभा छत्रकी ता न विध्येत् अपि च", text: "tatra śvetāruṇāvartavadanavasthitā dṛṣṭirāvartakī arkakṣīraleśeneva kūrcikāpiṇḍeneva cācitā śarkarā śāliśūkābharājyāvṛtā rājīmatī chinnaviṣamadagdhābhā saruk chinnāṃśukā kāṃsyasamacchāyā candrakasaṃsthānā candrakī naikavarṇā chatranibhā chatrakī tā na vidhyet api ca" },
      { type: "verse", number: "4", sanskrit: "न विध्येदसिरार्हाणां न तृट्पीनसकासिनाम् नाजीर्णभीरुवमितशिरःकर्णाक्षिशूलिनाम् नात्युष्णशीतवाताभ्रे नासम्पूर्णां च नीलिकाम्", text: "na vidhyedasirārhāṇāṃ na tṛṭpīnasakāsinām nājīrṇabhīruvamitaśiraḥkarṇākṣiśūlinām nātyuṣṇaśītavātābhre nāsampūrṇāṃ ca nīlikām" },
      { type: "verse", number: "5", sanskrit: "असञ्जाता हि विषमा दधिमस्तुतनुश्च सा शलाकयावघृष्टापि पुनरूर्ध्वं प्रपद्यते करोति वेदनां तीव्रां दृष्टिं च स्थगयेत् पुनः", text: "asañjātā hi viṣamā dadhimastutanuśca sā śalākayāvaghṛṣṭāpi punarūrdhvaṃ prapadyate karoti vedanāṃ tīvrāṃ dṛṣṭiṃ ca sthagayet punaḥ" },
      { type: "verse", number: "6", sanskrit: "सा च सम्पूर्यते शीघ्रं श्लेष्मलर्वातपित्तलैः चिरात्सोपद्रवा च स्यान्निष्प्रेक्ष्यात्वर्हति व्यधम्", text: "sā ca sampūryate śīghraṃ śleṣmalarvātapittalaiḥ cirātsopadravā ca syānniṣprekṣyātvarhati vyadham" },
      { type: "verse", number: "7", sanskrit: "अथ स्निग्धस्य विरिक्तस्य घृतैः सम्भोजितस्य निशि रसेन प्रीणितोत्तमाङ्गस्याभुक्तवतः सज्जोपकरणस्य विमले ऽहनि साधके च कृतस्वस्त्ययनस्य विहितादित्यविदेहाधिपतिप्रणामस्य पूर्वाह्णे निवातप्रकाशदेशस्थस्य प्रत्यादित्यमास्तरणेन लब्धमार्दवायां भामौ प्रसारितचरणयुग्ममुपविष्टस्य क्षितितलगतसमतलोभयपाणेः पृष्ठतः सुखोपविष्टेन परिचारकेण हस्ताभ्यां निश्चलमवलम्बितशिरसः किश्चिदुत्तानास्यस्य स्वां नासामितरच्चेक्षणमीक्षमाणस्यातुरस्य जङ्घयोरुपरिष्टान्नात्युच्छ्रितासननिविष्टो भिषग् दक्षिणहस्तानुलोममक्षि मुखबाष्पस्विन्नं निमीलितमीषदङ्गुष्ठोदरविमृदिततारकतया परिप्लुतदोषं सव्याङ्गुष्ठप्रदेशिनीभ्यामुन्मील्य दक्षिणमध्यमाप्रदेशिन्यङ्गुष्ठैर्निष्कम्पं गृहीतया शलाकया कृष्णभागाद्भागद्वयस्यापाङ्गादेकभागस्य च सङ्गमे दृष्टेरार्जवं नात्यूर्ध्वमधो वा नेत्रसहजन्मनि सन्धौ विध्येत्", text: "atha snigdhasya viriktasya ghṛtaiḥ sambhojitasya niśi rasena prīṇitottamāṅgasyābhuktavataḥ sajjopakaraṇasya vimale 'hani sādhake ca kṛtasvastyayanasya vihitādityavidehādhipatipraṇāmasya pūrvāhṇe nivātaprakāśadeśasthasya pratyādityamāstaraṇena labdhamārdavāyāṃ bhāmau prasāritacaraṇayugmamupaviṣṭasya kṣititalagatasamatalobhayapāṇeḥ pṛṣṭhataḥ sukhopaviṣṭena paricārakeṇa hastābhyāṃ niścalamavalambitaśirasaḥ kiściduttānāsyasya svāṃ nāsāmitaraccekṣaṇamīkṣamāṇasyāturasya jaṅghayorupariṣṭānnātyucchritāsananiviṣṭo bhiṣag dakṣiṇahastānulomamakṣi mukhabāṣpasvinnaṃ nimīlitamīṣadaṅguṣṭhodaravimṛditatārakatayā pariplutadoṣaṃ savyāṅguṣṭhapradeśinībhyāmunmīlya dakṣiṇamadhyamāpradeśinyaṅguṣṭhairniṣkampaṃ gṛhītayā śalākayā kṛṣṇabhāgādbhāgadvayasyāpāṅgādekabhāgasya ca saṅgame dṛṣṭerārjavaṃ nātyūrdhvamadho vā netrasahajanmani sandhau vidhyet" },
      { type: "verse", number: "8", sanskrit: "एवमेव दक्षिणं दक्षिणाङ्गुष्ठप्रदेशिन्युन्मीलितमितरेण करेणैव चातुरस्य दक्षिणपार्श्वे स्थित्वा", text: "evameva dakṣiṇaṃ dakṣiṇāṅguṣṭhapradeśinyunmīlitamitareṇa kareṇaiva cāturasya dakṣiṇapārśve sthitvā" },
      { type: "verse", number: "9", sanskrit: "अथ शब्दवदवेदनं साम्बुबिन्दुस्रुति च सम्यग्विद्धं विद्यात् प्रविष्टमात्रां च शलाकां धारयेत् रागाश्रुवेदनानुत्पादनार्थं च स्तन्येन सेचयेत् ततः पुनरातुरमाश्वास्य भ्रमयन् शलाकामा दृष्टिमध्यात् प्रवेशयेत्", text: "atha śabdavadavedanaṃ sāmbubindusruti ca samyagviddhaṃ vidyāt praviṣṭamātrāṃ ca śalākāṃ dhārayet rāgāśruvedanānutpādanārthaṃ ca stanyena secayet tataḥ punarāturamāśvāsya bhramayan śalākāmā dṛṣṭimadhyāt praveśayet" },
      { type: "verse", number: "10", sanskrit: "अधश्चास्यावलिकयतो लिङ्गनाशमद्रुतमविलम्बितमनुसुखमधोमुखमपनयेदुच्छिङ्खयेच्चैनम् तथा हि दृक् स्रस्तकफस्य विशुध्यति विशुद्धदृष्टेश्चाङ्गुलिं तन्तून् ज्ञातीन् सन्ततींश्च दर्शयेत् प्रेक्षमाणस्य चानिमीलितान्नेत्राच्छन्नैः शनैः भ्रमयन्नेव शलाकामपकर्षेत् अथ व्यपगतदोषस्य यथावत् पश्यतः सुखोष्णघृताप्लुतं पिचुमीक्षणस्योपरि दत्वा बध्नीयात् ततो निवातमागारमनुप्रवेश्य संवेश्य च सोपधाने मृदुशयने शयानं दक्षिणे ऽक्षिणि विद्धे वामेन पार्श्वेन वामे दक्षिणेनोभयस्मिन्नुत्तानमनुकूलाभिः कथाभिरुपाचरेत् यथाशक्ति चैनमुपवासयेत् उद्गारक्षवथुकासनिष्ठीवनोत्क्षेपणानि त्र्यहं परिहरेत् स्नानाम्बुपानदन्तधावनाधोमुखावस्थानानिसप्ताहम्", text: "adhaścāsyāvalikayato liṅganāśamadrutamavilambitamanusukhamadhomukhamapanayeducchiṅkhayeccainam tathā hi dṛk srastakaphasya viśudhyati viśuddhadṛṣṭeścāṅguliṃ tantūn jñātīn santatīṃśca darśayet prekṣamāṇasya cānimīlitānnetrācchannaiḥ śanaiḥ bhramayanneva śalākāmapakarṣet atha vyapagatadoṣasya yathāvat paśyataḥ sukhoṣṇaghṛtāplutaṃ picumīkṣaṇasyopari datvā badhnīyāt tato nivātamāgāramanupraveśya saṃveśya ca sopadhāne mṛduśayane śayānaṃ dakṣiṇe 'kṣiṇi viddhe vāmena pārśvena vāme dakṣiṇenobhayasminnuttānamanukūlābhiḥ kathābhirupācaret yathāśakti cainamupavāsayet udgārakṣavathukāsaniṣṭhīvanotkṣepaṇāni tryahaṃ pariharet snānāmbupānadantadhāvanādhomukhāvasthānānisaptāham" },
      { type: "verse", number: "11", sanskrit: "स्नेहविधिं चेक्षेत मूर्ध्नि पादयोश्च घृताभ्यङ्गमाचरेत् तृतीये चाह्नि मुक्त्वाक्षि परिषेचयेदेरण्डपल्लवशृतेन दुग्धोष्णेन दुग्धेन जीवनीयैर्वा सिद्धेन पयसा हविषा वा तद्वल्लघुना पञ्चमूलेन ततः पूर्ववद् बध्नीयात्", text: "snehavidhiṃ cekṣeta mūrdhni pādayośca ghṛtābhyaṅgamācaret tṛtīye cāhni muktvākṣi pariṣecayederaṇḍapallavaśṛtena dugdhoṣṇena dugdhena jīvanīyairvā siddhena payasā haviṣā vā tadvallaghunā pañcamūlena tataḥ pūrvavad badhnīyāt" },
      { type: "verse", number: "12", sanskrit: "ततः प्रभृत्येवमेव प्रत्यहमासप्ताहम् सप्तमे तु दिवसे सर्वथा मोक्षयेत् दशमे वा भोजयेच्चैनं व्योषामलकयुक्तं द्रवमीषत्स्नेहलवणं वाट्यमुष्णोदकद्वितीयं विलेपीं वा एवमाचरतो रुजारागादयो नानुवर्तन्ते", text: "tataḥ prabhṛtyevameva pratyahamāsaptāham saptame tu divase sarvathā mokṣayet daśame vā bhojayeccainaṃ vyoṣāmalakayuktaṃ dravamīṣatsnehalavaṇaṃ vāṭyamuṣṇodakadvitīyaṃ vilepīṃ vā evamācarato rujārāgādayo nānuvartante" },
      { type: "verse", number: "13", sanskrit: "तदनुवृत्तौ तु यष्टीमधुकलोध्रमृद्वीकासैन्धवैः सिद्धेन ससितेनाजपयसा नयनमाश्च्योतयेत् मधुककुष्ठोत्पलद्राक्षालाक्षाशर्कराभिर्वा पृश्निपर्णीमुस्तमधुकशतावरीपंद्मकसैन्धवैर्वा", text: "tadanuvṛttau tu yaṣṭīmadhukalodhramṛdvīkāsaindhavaiḥ siddhena sasitenājapayasā nayanamāścyotayet madhukakuṣṭhotpaladrākṣālākṣāśarkarābhirvā pṛśniparṇīmustamadhukaśatāvarīpaṃdmakasaindhavairvā" },
      { type: "verse", number: "14", sanskrit: "शिरोवक्त्रलेपं च सारिवागैरिकयवदूर्वाघृतैः कुर्यात् मातुलुङ्गरसाप्लुतैर्वा मृदुभृष्टैस्तिलैः ससर्षपैः अजाक्षीरद्रुतैर्वा मृदुभृष्टैस्तिलैः ससर्षपैः अजाक्षीरद्रुतैर्वा पयस्यासारिवापत्रमञ्जिष्ठायष्ट्याह्वैर्हिमः सुखोष्णो वा लेपः तद्वद्देवदारुनागरमद्मकैर्वा", text: "śirovaktralepaṃ ca sārivāgairikayavadūrvāghṛtaiḥ kuryāt mātuluṅgarasāplutairvā mṛdubhṛṣṭaistilaiḥ sasarṣapaiḥ ajākṣīradrutairvā mṛdubhṛṣṭaistilaiḥ sasarṣapaiḥ ajākṣīradrutairvā payasyāsārivāpatramañjiṣṭhāyaṣṭyāhvairhimaḥ sukhoṣṇo vā lepaḥ tadvaddevadārunāgaramadmakairvā" },
      { type: "verse", number: "15", sanskrit: "जाङ्गलरसेन च जीवनीयक्वाथवता भोजयेत् वातहरवर्गसिद्धेन च पयसा पद्मकादिगर्भसिद्धं सर्पिः पाननावनसेकेषु विदध्यात् तथानुपशमे सिरां विध्येत् अधिमन्थसाधनं चेक्षेत", text: "jāṅgalarasena ca jīvanīyakvāthavatā bhojayet vātaharavargasiddhena ca payasā padmakādigarbhasiddhaṃ sarpiḥ pānanāvanasekeṣu vidadhyāt tathānupaśame sirāṃ vidhyet adhimanthasādhanaṃ cekṣeta" },
      { type: "verse", number: "16", sanskrit: "यथोक्ताचारातिक्रमात्तु व्यधः पाकमुपयाति अभिष्यन्दाधिमन्थादयः स्युर्व्यधदोषाच्च तान्यथास्वमुपत्रमेत", text: "yathoktācārātikramāttu vyadhaḥ pākamupayāti abhiṣyandādhimanthādayaḥ syurvyadhadoṣācca tānyathāsvamupatrameta" },
      { type: "verse", number: "17", sanskrit: "व्यधदोषाः पुनरध ऊर्ध्वं कृष्णासन्नमपाङ्गासन्नं सिराव्यधश्च", text: "vyadhadoṣāḥ punaradha ūrdhvaṃ kṛṣṇāsannamapāṅgāsannaṃ sirāvyadhaśca" },
      { type: "verse", number: "18", sanskrit: "तत्राधोव्यधादत्यर्थशूलास्रस्रुतिरागाः शलाकायांश्चोपलेपो बहलपिच्छिलः कृष्णां वलिभिरुपचीयते नयनं स्रवति तद्वर्जयेत्", text: "tatrādhovyadhādatyarthaśūlāsrasrutirāgāḥ śalākāyāṃścopalepo bahalapicchilaḥ kṛṣṇāṃ valibhirupacīyate nayanaṃ sravati tadvarjayet" },
      { type: "verse", number: "19", sanskrit: "ऊर्ध्वव्यधादतिमात्ररुक् तत्रात्युष्णघृतपरिषेको वातहरं च कर्म", text: "ūrdhvavyadhādatimātraruk tatrātyuṣṇaghṛtapariṣeko vātaharaṃ ca karma" },
      { type: "verse", number: "20", sanskrit: "कृष्णासन्नव्यधान्नसुखमपनीयते पटलम् कृष्णे च रुजा दृष्टिरपि च रक्तावच्छादिता कृष्णमण्डलाभा भवति तत्र सर्पिस्सेकविरेकरक्तमोक्षैः सिद्धिः", text: "kṛṣṇāsannavyadhānnasukhamapanīyate paṭalam kṛṣṇe ca rujā dṛṣṭirapi ca raktāvacchāditā kṛṣṇamaṇḍalābhā bhavati tatra sarpissekavirekaraktamokṣaiḥ siddhiḥ" },
      { type: "verse", number: "21", sanskrit: "अपाङ्गासन्नव्यधाच्छोफशूलतोदभेदाः सास्राः स्रुतयः तत्र घृतसेकोपवासौ भ्रुवोरन्तरे च दाहः", text: "apāṅgāsannavyadhācchophaśūlatodabhedāḥ sāsrāḥ srutayaḥ tatra ghṛtasekopavāsau bhruvorantare ca dāhaḥ" },
      { type: "verse", number: "22", sanskrit: "सिराव्यधाद्रक्तागमो विविधाश्च वेदनाः तत्र स्तन्यमधुकविपक्वेन सर्पिषा परिषेको ऽपाङ्गे वा दाहः", text: "sirāvyadhādraktāgamo vividhāśca vedanāḥ tatra stanyamadhukavipakvena sarpiṣā pariṣeko 'pāṅge vā dāhaḥ" },
      { type: "verse", number: "23", sanskrit: "सिराजालवति तु नेत्रे प्राक् सिराजालमपनयेत् ततो लब्धबलं स्निग्धं च विध्येत्", text: "sirājālavati tu netre prāk sirājālamapanayet tato labdhabalaṃ snigdhaṃ ca vidhyet" },
      { type: "verse", number: "24", sanskrit: "अथ शलाकाभ्रमणदोषाः क्षोभणमूर्ध्वमधो ऽत्यर्थदृष्टिघट्टनमतिदृष्टिप्रेरणं च शलाकाक्षोभणाद्धिस्पन्दनतोदभेदपरिमन्थाः तस्मिन्यष्टीमधुकपोट्टल्या घृतमृदितया सेको जलौकसश्च ऊर्ध्वप्रणयनाद्रागो ऽतिवेदना च तत्रोपवासो घृतसेकश्च स्पर्शसुखः अधोनयनाच्छूलं रक्तागमश्च तत्र क्षोभणवत् सिद्धिः अत्यर्थदृष्टिघट्टनाद्दृष्ट्याकुलता तत्र सर्पिर्मण्डोनुवासनं नावनं च अतीत्य दृष्टिं शलाकायाः प्रेरणाद्रक्तस्रवणं रक्ताभरूपदर्शनं च तत्र सर्पिस्सेकोपवासजलौकसः", text: "atha śalākābhramaṇadoṣāḥ kṣobhaṇamūrdhvamadho 'tyarthadṛṣṭighaṭṭanamatidṛṣṭipreraṇaṃ ca śalākākṣobhaṇāddhispandanatodabhedaparimanthāḥ tasminyaṣṭīmadhukapoṭṭalyā ghṛtamṛditayā seko jalaukasaśca ūrdhvapraṇayanādrāgo 'tivedanā ca tatropavāso ghṛtasekaśca sparśasukhaḥ adhonayanācchūlaṃ raktāgamaśca tatra kṣobhaṇavat siddhiḥ atyarthadṛṣṭighaṭṭanāddṛṣṭyākulatā tatra sarpirmaṇḍonuvāsanaṃ nāvanaṃ ca atītya dṛṣṭiṃ śalākāyāḥ preraṇādraktasravaṇaṃ raktābharūpadarśanaṃ ca tatra sarpissekopavāsajalaukasaḥ" },
      { type: "verse", number: "25", sanskrit: "लिङ्गनाशदोषास्तु स्फुटनमवगलनं विस्तरणमुत्प्लवनं लीनता च तत्र शलाकया स्पृष्टो लिङ्गनाशो यः स्फुटति तमेरण्डपत्रस्विन्नं खण्डशः शोधयेत् ततः कृष्णासैन्धवमधुभिरवपीडनम् अवगलति तु शलाकामपनीय स्तन्यसेकं दद्यादवपीडनं च शुण्ठीगुडं जलौकसश्च विस्तीर्यमाणे सुखोष्णाम्बुप्लुतेन वाससा स्वेदो घृतमण्डश्च प्रतिमर्शः तद्वदुत्प्लवमाने वित्रासनं शीताम्भसा प्रततं चोच्छिङ्खनं च", text: "liṅganāśadoṣāstu sphuṭanamavagalanaṃ vistaraṇamutplavanaṃ līnatā ca tatra śalākayā spṛṣṭo liṅganāśo yaḥ sphuṭati tameraṇḍapatrasvinnaṃ khaṇḍaśaḥ śodhayet tataḥ kṛṣṇāsaindhavamadhubhiravapīḍanam avagalati tu śalākāmapanīya stanyasekaṃ dadyādavapīḍanaṃ ca śuṇṭhīguḍaṃ jalaukasaśca vistīryamāṇe sukhoṣṇāmbuplutena vāsasā svedo ghṛtamaṇḍaśca pratimarśaḥ tadvadutplavamāne vitrāsanaṃ śītāmbhasā pratataṃ cocchiṅkhanaṃ ca" },
      { type: "verse", number: "26", sanskrit: "स्थिरे चले च दोषे पत्रभङ्गस्वेदः तथाप्यनपगच्छति शलाकापगमने वा पुनरुत्प्लवने स्नेहपाननस्यादिभिरुपपाद्य पुनर्विध्येत् एवमपि पुनरुत्प्लवने भ्रुवोरन्तरे दाहः", text: "sthire cale ca doṣe patrabhaṅgasvedaḥ tathāpyanapagacchati śalākāpagamane vā punarutplavane snehapānanasyādibhirupapādya punarvidhyet evamapi punarutplavane bhruvorantare dāhaḥ" },
      { type: "verse", number: "27", sanskrit: "यस्त्वपकृष्यमाणो दृष्टिमण्डले लीयते तत्र क्षीरेण नाडीस्वेदं दद्यात् शताह्वामधुकचूर्णसंसृष्टं च घृतं प्रतिमर्श इति भवति चात्र", text: "yastvapakṛṣyamāṇo dṛṣṭimaṇḍale līyate tatra kṣīreṇa nāḍīsvedaṃ dadyāt śatāhvāmadhukacūrṇasaṃsṛṣṭaṃ ca ghṛtaṃ pratimarśa iti bhavati cātra" },
      { type: "verse", number: "28", sanskrit: "स्वेददाहप्रतीमर्शान् सद्योविद्धे तु सेचनम्", text: "svedadāhapratīmarśān sadyoviddhe tu secanam" },
      { type: "verse", number: "29", sanskrit: "अवपीडं तृतीये ऽह्नि युञ्ज्यात्तद्वज्जलौकसः सप्ताहान्ते सिरामोक्षं विरेकं बस्तिकर्म च", text: "avapīḍaṃ tṛtīye 'hni yuñjyāttadvajjalaukasaḥ saptāhānte sirāmokṣaṃ virekaṃ bastikarma ca" },
      { type: "verse", number: "30", sanskrit: "यन्त्रणामनुरुध्येत दृष्टेरा स्थैर्यलाभतः रूपाणि सूक्ष्मदीप्तानि सहसा नावलोकयेत्", text: "yantraṇāmanurudhyeta dṛṣṭerā sthairyalābhataḥ rūpāṇi sūkṣmadīptāni sahasā nāvalokayet" },
      { type: "verse", number: "31", sanskrit: "कुर्याच्छ्लाकास्थूलाग्रा विशालव्रणतां तनुः पटलोत्प्लवनं तीक्ष्णा क्षतमन्तः खरारुजः कण्ठा च विषमाश्रूणि द्रस्वा दीर्घा च दुर्ग्रहा", text: "kuryācchlākāsthūlāgrā viśālavraṇatāṃ tanuḥ paṭalotplavanaṃ tīkṣṇā kṣatamantaḥ kharārujaḥ kaṇṭhā ca viṣamāśrūṇi drasvā dīrghā ca durgrahā" },
      { type: "verse", number: "32", sanskrit: "आढकीमूलमरिचहरितालरसाञ्जनैः विद्धे ऽक्ष्णि सगुडा वर्तिर्योज्या दिव्याम्बुपेषिता", text: "āḍhakīmūlamaricaharitālarasāñjanaiḥ viddhe 'kṣṇi saguḍā vartiryojyā divyāmbupeṣitā" },
      { type: "verse", number: "33", sanskrit: "जातीशिरीषधवमेषविषाणषुष्पवैडूर्यमौक्तिकफलं पयसा सुपिष्टम् आजेन ताम्रममुना प्रतनुप्रदिग्धं सप्ताहतः पुनरिदं पयसैव पिष्टम्", text: "jātīśirīṣadhavameṣaviṣāṇaṣuṣpavaiḍūryamauktikaphalaṃ payasā supiṣṭam ājena tāmramamunā pratanupradigdhaṃ saptāhataḥ punaridaṃ payasaiva piṣṭam" },
      { type: "verse", number: "34", sanskrit: "पिण्डाञ्जनं हितमनातपशुष्कमक्ष्णि विद्धे प्रसादजननं बलकृच्च दृष्टेः स्रोतोजविद्रुमशिलाप्पतिफेनतीक्ष्णैरस्यैव तुल्यमुदितं गुणकल्पनाभिः", text: "piṇḍāñjanaṃ hitamanātapaśuṣkamakṣṇi viddhe prasādajananaṃ balakṛcca dṛṣṭeḥ srotojavidrumaśilāppatiphenatīkṣṇairasyaiva tulyamuditaṃ guṇakalpanābhiḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 18,
    lang: "sa",
    content: [
      { type: "heading", heading: "Рактапитта рога — кровотечения" },
      { type: "text", text: "Глава 18 Уттара стханы — «Рактапитта рога» — посвящена специализированному разделу: кровотечения. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः सर्वगाक्षिरोगविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ sarvagākṣirogavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "वातेन नेत्रे ऽभिष्यण्णे नासानाहो ऽल्पशोफता शङ्खाक्षिभ्रूललाटास्यतोदस्फुरणभेदनम्", text: "vātena netre 'bhiṣyaṇṇe nāsānāho 'lpaśophatā śaṅkhākṣibhrūlalāṭāsyatodasphuraṇabhedanam" },
      { type: "verse", number: "3", sanskrit: "शुष्काल्पा दूषिका शीतमल्पं चाश्रु चला रुजः निमेषोन्मेषणं कृच्छ्राज्जन्तूनामिव सर्पणम्", text: "śuṣkālpā dūṣikā śītamalpaṃ cāśru calā rujaḥ nimeṣonmeṣaṇaṃ kṛcchrājjantūnāmiva sarpaṇam" },
      { type: "verse", number: "4", sanskrit: "अक्ष्याध्मातमिवाभाति सूक्ष्मैश्शल्यैरिवाचितम् स्निग्धोष्णैश्चोपशमनम् सोभिष्यन्द उपेक्षितः", text: "akṣyādhmātamivābhāti sūkṣmaiśśalyairivācitam snigdhoṣṇaiścopaśamanam sobhiṣyanda upekṣitaḥ" },
      { type: "verse", number: "5", sanskrit: "अधिमन्थो भवेत्तत्र कर्णयोर्नदनं भ्रमः अरण्येव च मथ्यन्ते ललाटाक्षिभ्रुवादयः", text: "adhimantho bhavettatra karṇayornadanaṃ bhramaḥ araṇyeva ca mathyante lalāṭākṣibhruvādayaḥ" },
      { type: "verse", number: "6", sanskrit: "हताधिमन्थः सोपि स्यात् प्रमादात्तेन वेदनाः अनेकरूपा जायन्ते व्रणो दृष्टौ च दृष्टिहा", text: "hatādhimanthaḥ sopi syāt pramādāttena vedanāḥ anekarūpā jāyante vraṇo dṛṣṭau ca dṛṣṭihā" },
      { type: "verse", number: "7", sanskrit: "मन्याक्षिशङ्खतो वायुरन्यतो वा प्रवर्तयेत् व्यथां तीव्रामपैच्छिल्यरागशोफं विलोचनम् सङ्गोचयति पर्यश्रु सोन्यतोवातसंज्ञितः", text: "manyākṣiśaṅkhato vāyuranyato vā pravartayet vyathāṃ tīvrāmapaicchilyarāgaśophaṃ vilocanam saṅgocayati paryaśru sonyatovātasaṃjñitaḥ" },
      { type: "verse", number: "8", sanskrit: "तद्वज्जिह्मं भवेन्नेत्रमूनं वा वातपर्यये", text: "tadvajjihmaṃ bhavennetramūnaṃ vā vātaparyaye" },
      { type: "verse", number: "9", sanskrit: "दाहो धूमायनं शोफः श्यावता वर्त्मनोर्बहिः अन्तःक्लेदो ऽश्रु पीतोष्णं रागः पीताभदर्शनम् क्षारोक्षितक्षताक्षित्वं पित्ताभिष्यन्दलक्षणम्", text: "dāho dhūmāyanaṃ śophaḥ śyāvatā vartmanorbahiḥ antaḥkledo 'śru pītoṣṇaṃ rāgaḥ pītābhadarśanam kṣārokṣitakṣatākṣitvaṃ pittābhiṣyandalakṣaṇam" },
      { type: "verse", number: "10", sanskrit: "ज्वलदङ्गारकीर्णाभं यकृत्पिण्डसमप्रभम् अधिमन्थे भवेन्नेत्रम् स्यन्दे तु कफसम्भवे", text: "jvaladaṅgārakīrṇābhaṃ yakṛtpiṇḍasamaprabham adhimanthe bhavennetram syande tu kaphasambhave" },
      { type: "verse", number: "11", sanskrit: "अधिमन्थे भवेन्नेत्रम् स्यन्दे तु कफसम्भवे जाड्यं शोफो महान् कण्डूर्निद्रान्नानभिनन्दनम् सान्द्रस्निग्धबहुश्वेतपिच्छावद्दूषिकाश्रुता", text: "adhimanthe bhavennetram syande tu kaphasambhave jāḍyaṃ śopho mahān kaṇḍūrnidrānnānabhinandanam sāndrasnigdhabahuśvetapicchāvaddūṣikāśrutā" },
      { type: "verse", number: "12", sanskrit: "अधिमन्थे नतं कृष्णमुन्नतं शुक्लमण्डलम् प्रसेको नासिकाध्मानं पांसुपूर्णमिवेक्षणम्", text: "adhimanthe nataṃ kṛṣṇamunnataṃ śuklamaṇḍalam praseko nāsikādhmānaṃ pāṃsupūrṇamivekṣaṇam" },
      { type: "verse", number: "13", sanskrit: "रक्ताश्रुराजीदूषीका रक्तमण्डलदर्शनम् रक्तस्यन्देन नयनं सपित्तस्यन्दलक्षणम्", text: "raktāśrurājīdūṣīkā raktamaṇḍaladarśanam raktasyandena nayanaṃ sapittasyandalakṣaṇam" },
      { type: "verse", number: "14", sanskrit: "मन्थे ऽक्षिताम्रपर्यन्तमुत्पाटनसमानरुक् रागेण बन्धूकनिभं ताम्यति श्पर्शनाक्षमम् असृङ्निमग्नारिष्टाभं कृष्णमग्न्याभदर्शनम्", text: "manthe 'kṣitāmraparyantamutpāṭanasamānaruk rāgeṇa bandhūkanibhaṃ tāmyati śparśanākṣamam asṛṅnimagnāriṣṭābhaṃ kṛṣṇamagnyābhadarśanam" },
      { type: "verse", number: "15", sanskrit: "अधिमन्था यथास्वं च सर्वे स्यन्दाधिकव्यथाः शङ्खदन्तकफोलेषु कपाले चातिरुक्कराः", text: "adhimanthā yathāsvaṃ ca sarve syandādhikavyathāḥ śaṅkhadantakapholeṣu kapāle cātirukkarāḥ" },
      { type: "verse", number: "16", sanskrit: "वातपित्तातुरं घर्षतोदभेदोपदेहवत् रूक्षदारुणवर्त्माक्षिकृच्छ्रोन्मीलनिमीलनम्", text: "vātapittāturaṃ gharṣatodabhedopadehavat rūkṣadāruṇavartmākṣikṛcchronmīlanimīlanam" },
      { type: "verse", number: "17", sanskrit: "विकूणनविशुष्कत्वशीतेच्छाशूलपाकवत् उक्तः शुष्काक्षिपाको ऽयम् सशोफः स्यात्त्रिभिर्मलैः", text: "vikūṇanaviśuṣkatvaśītecchāśūlapākavat uktaḥ śuṣkākṣipāko 'yam saśophaḥ syāttribhirmalaiḥ" },
      { type: "verse", number: "18", sanskrit: "सरक्तैस्तत्र शोफो ऽतिरुग्दाहष्ठीवनादिमान्", text: "saraktaistatra śopho 'tirugdāhaṣṭhīvanādimān" },
      { type: "verse", number: "19", sanskrit: "अश्रूष्णशीतविशदपिच्छिलाच्छघनं मुहुः", text: "aśrūṣṇaśītaviśadapicchilācchaghanaṃ muhuḥ" },
      { type: "verse", number: "20", sanskrit: "अल्पशोफो ऽल्पशोफस्तु पाको ऽन्यैर्लक्षणैस्तथा", text: "alpaśopho 'lpaśophastu pāko 'nyairlakṣaṇaistathā" },
      { type: "verse", number: "21", sanskrit: "अक्षिपाकात्यये शोफः संरम्भः कलुषाश्रुता कफोपदिग्धमसितं सितं प्रक्लेदरागवत् दाहो दर्शनसंरोधो वेदनाश्चानवस्थिताः", text: "akṣipākātyaye śophaḥ saṃrambhaḥ kaluṣāśrutā kaphopadigdhamasitaṃ sitaṃ prakledarāgavat dāho darśanasaṃrodho vedanāścānavasthitāḥ" },
      { type: "verse", number: "22", sanskrit: "अन्नसारो ऽम्लतां नीतः पित्तरक्तोल्बणैर्मलैः सिराभिर्नेत्रमारूढः करोति श्यावलोहितम्", text: "annasāro 'mlatāṃ nītaḥ pittaraktolbaṇairmalaiḥ sirābhirnetramārūḍhaḥ karoti śyāvalohitam" },
      { type: "verse", number: "23", sanskrit: "सशोफदाहपाकाश्रु भृशं चाविलदर्शनम् अम्लोषितो ऽयमित्युक्ता गदाः षोडश सर्वगाः", text: "saśophadāhapākāśru bhṛśaṃ cāviladarśanam amloṣito 'yamityuktā gadāḥ ṣoḍaśa sarvagāḥ" },
      { type: "verse", number: "24", sanskrit: "हताधिमन्थमेतेषु साक्षिपाकात्ययं त्यजेत्", text: "hatādhimanthameteṣu sākṣipākātyayaṃ tyajet" },
      { type: "verse", number: "25", sanskrit: "वातोद्भूतः पञ्चरात्रेण दृष्टिं सप्ताहेन श्लेष्मजातो ऽधिमन्थः रक्तोत्पन्नो हन्ति तद्वत्त्रिरात्रान्मिथ्याचारात् पैत्तिकः सद्य एव", text: "vātodbhūtaḥ pañcarātreṇa dṛṣṭiṃ saptāhena śleṣmajāto 'dhimanthaḥ raktotpanno hanti tadvattrirātrānmithyācārāt paittikaḥ sadya eva" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 19,
    lang: "sa",
    content: [
      { type: "heading", heading: "Мурча рога — обмороки" },
      { type: "text", text: "Глава 19 Уттара стханы — «Мурча рога» — посвящена специализированному разделу: обмороки. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो ऽभिष्यन्दप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयोमहर्षयः", text: "athāto 'bhiṣyandapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayomaharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अथ खलु सर्वगाक्षिरोगाणां पूर्वरूप एव शिरोविरेककवलधूमोपवासानासेवेतान्यत्र मारुतोद्रेकात्", text: "atha khalu sarvagākṣirogāṇāṃ pūrvarūpa eva śirovirekakavaladhūmopavāsānāsevetānyatra mārutodrekāt" },
      { type: "verse", number: "3", sanskrit: "सर्वत्र तु चन्दनमरिचपत्रैलास्वर्णगैरिकतगररसाञ्जनलवणयष्ट्याह्वैर्बिडालकं कुर्यात्", text: "sarvatra tu candanamaricapatrailāsvarṇagairikatagararasāñjanalavaṇayaṣṭyāhvairbiḍālakaṃ kuryāt" },
      { type: "verse", number: "4", sanskrit: "तथा दार्वीतुत्थहरीतकीभिर्वातपित्ते कफे तु हरीतकीनागररसाञ्जनस्वर्णगैरिकैः", text: "tathā dārvītutthaharītakībhirvātapitte kaphe tu harītakīnāgararasāñjanasvarṇagairikaiḥ" },
      { type: "verse", number: "5", sanskrit: "अपि च कुष्ठामिसिपिप्पलीचन्दनोत्पलैर्बिडालको वेदनाघ्नः मुस्तागरुचन्दनैः क्षौद्रयुतैः शूलदाहरागघ्नः सन्धवागरुत्रिजातकत्रिकटुकस्वर्णगैरिककुष्ठतगरशैलेयकैः शूलश्वयथुदाहरागनुत्", text: "api ca kuṣṭhāmisipippalīcandanotpalairbiḍālako vedanāghnaḥ mustāgarucandanaiḥ kṣaudrayutaiḥ śūladāharāgaghnaḥ sandhavāgarutrijātakatrikaṭukasvarṇagairikakuṣṭhatagaraśaileyakaiḥ śūlaśvayathudāharāganut" },
      { type: "verse", number: "6", sanskrit: "शिग्रुफलमनोह्वाशाबरलोध्रैः क्रमाच्चतुर्गुणप्रवृद्धैः श्लक्ष्णरजोभिः सूक्ष्मतान्तवस्थैर्नयनमवचूर्णयेत्", text: "śigruphalamanohvāśābaralodhraiḥ kramāccaturguṇapravṛddhaiḥ ślakṣṇarajobhiḥ sūkṣmatāntavasthairnayanamavacūrṇayet" },
      { type: "verse", number: "7", sanskrit: "श्वेतलोध्रत्वचं बहिर्विलिखितां निम्बपत्रकल्केन प्रदिग्धां पुटपाके विपक्वामर्धपलोन्मितां मरिचचतुष्टययुक्तां श्लक्ष्णरजीकृतां वस्त्रबद्धामक्ष्ण्यवकिरेत् एतदवगुण्ठनं शूलदाहाश्रुश्वयथुकण्डूषापाकक्लेदोपदेहहरम् तयैव च पोट्टलिकयाश्च्योतनकाले ऽवन्तिसोमाप्लुतयाश्च्योतयेत्", text: "śvetalodhratvacaṃ bahirvilikhitāṃ nimbapatrakalkena pradigdhāṃ puṭapāke vipakvāmardhapalonmitāṃ maricacatuṣṭayayuktāṃ ślakṣṇarajīkṛtāṃ vastrabaddhāmakṣṇyavakiret etadavaguṇṭhanaṃ śūladāhāśruśvayathukaṇḍūṣāpākakledopadehaharam tayaiva ca poṭṭalikayāścyotanakāle 'vantisomāplutayāścyotayet" },
      { type: "verse", number: "8", sanskrit: "पूर्ववद्वा लोध्रवल्कलकल्कमुपस्कृतं तन्मात्रमेव मरिचद्वयेन मनश्शिलापादेनाष्टांशकैश्च यष्टीमधुकशतपुष्पाञ्जनैर्युक्तं प्रकल्पयेत् अपि च", text: "pūrvavadvā lodhravalkalakalkamupaskṛtaṃ tanmātrameva maricadvayena manaśśilāpādenāṣṭāṃśakaiśca yaṣṭīmadhukaśatapuṣpāñjanairyuktaṃ prakalpayet api ca" },
      { type: "verse", number: "9", sanskrit: "आरण्याश्छगणरसे पटावबद्धाः सुस्विन्ना नखवितुषीकृताः कुलत्थाः तच्चूर्णं सकृचूदवर्णनान्निशीथे नेत्राणां विधमति सद्य एव कोपम्", text: "āraṇyāśchagaṇarase paṭāvabaddhāḥ susvinnā nakhavituṣīkṛtāḥ kulatthāḥ taccūrṇaṃ sakṛcūdavarṇanānniśīthe netrāṇāṃ vidhamati sadya eva kopam" },
      { type: "verse", number: "10", sanskrit: "अथ दारुहरिद्रापलमुदकार्धप्रस्थेनाष्टांशशेषं क्वथितं माक्षिकयुक्तमाश्च्योतनं कुर्वीत", text: "atha dāruharidrāpalamudakārdhaprasthenāṣṭāṃśaśeṣaṃ kvathitaṃ mākṣikayuktamāścyotanaṃ kurvīta" },
      { type: "verse", number: "11", sanskrit: "एवं चानुपशमे वाताभिष्यन्दिनमादावेव जाङ्गलरसैर्भेजयित्वा दशमूलरास्नात्रिफलाक्वाथेन जीवनीयकल्केन च पयोयुतं सिद्धमितरद्वा पुराणसर्पिः पाययेत्", text: "evaṃ cānupaśame vātābhiṣyandinamādāveva jāṅgalarasairbhejayitvā daśamūlarāsnātriphalākvāthena jīvanīyakalkena ca payoyutaṃ siddhamitaradvā purāṇasarpiḥ pāyayet" },
      { type: "verse", number: "12", sanskrit: "आश्च्योतनं चास्यैरण्डमूलपल्लवैः शृतमजाक्षीरं कुर्यात् सालपर्णीपृश्निपर्णीद्विबृहतीमधुकोरुपूगैर्वा तद्वत्तगरद्रीबेरशार्ङ्गेष्ठोदुम्बरमधुकपिप्पलीबृहतीद्वयैरण्डमूलैर्वा", text: "āścyotanaṃ cāsyairaṇḍamūlapallavaiḥ śṛtamajākṣīraṃ kuryāt sālaparṇīpṛśniparṇīdvibṛhatīmadhukorupūgairvā tadvattagaradrīberaśārṅgeṣṭhodumbaramadhukapippalībṛhatīdvayairaṇḍamūlairvā" },
      { type: "verse", number: "13", sanskrit: "अंशुमतीद्वयबृहतीकण्टकारिकाभिर्वा तान्तवावबद्धाभिः सुरामद्यधान्याम्लान्यतमाप्लुताभिरानूपमांसाम्लक्वाथेन वा", text: "aṃśumatīdvayabṛhatīkaṇṭakārikābhirvā tāntavāvabaddhābhiḥ surāmadyadhānyāmlānyatamāplutābhirānūpamāṃsāmlakvāthena vā" },
      { type: "verse", number: "14", sanskrit: "तैरेव च मांसैर्वेशवारीकृतस्विन्नैर्महास्नेहवद्भिर्यवचूर्णलवणप्रगाढामुत्कारिकां कृत्वा ललाटगण्डादीन् स्वेदयेत्", text: "taireva ca māṃsairveśavārīkṛtasvinnairmahāsnehavadbhiryavacūrṇalavaṇapragāḍhāmutkārikāṃ kṛtvā lalāṭagaṇḍādīn svedayet" },
      { type: "verse", number: "15", sanskrit: "अथवा रास्नाभीरुदशमूलबलाकोलकुलत्थयवानामजाक्षीरस्विन्नानां बाष्पेण रास्नादिभिरेव सिद्धं तैलं सर्पिर्वा नावनम् एवंविधैरेव नाडीस्वेदं कुर्यात्", text: "athavā rāsnābhīrudaśamūlabalākolakulatthayavānāmajākṣīrasvinnānāṃ bāṣpeṇa rāsnādibhireva siddhaṃ tailaṃ sarpirvā nāvanam evaṃvidhaireva nāḍīsvedaṃ kuryāt" },
      { type: "verse", number: "16", sanskrit: "सरलसुरभिघनदेवदारुहिंस्राकरञ्जफलबिल्वसर्षपैश्च सभृष्टतिलैः पयसा पिष्टैः सुखोष्णैर्मुखालेपो ऽक्षिवेदनास्तम्भप्रशमनः", text: "saralasurabhighanadevadāruhiṃsrākarañjaphalabilvasarṣapaiśca sabhṛṣṭatilaiḥ payasā piṣṭaiḥ sukhoṣṇairmukhālepo 'kṣivedanāstambhapraśamanaḥ" },
      { type: "verse", number: "17", sanskrit: "एवमस्यानुपशान्तरुजः सिरां मोक्षयेत् स्नेहस्वेदविष्यन्दं हि वातदुष्टमसृङ्निर्द्रियमाणं नानिलप्रकोपाय पुनश्च स्निग्धाय तिल्वकेन संयुक्तं वा तिल्वककषायानुपानं सर्पिर्विरेचनं दद्यात् शुद्धं च वातप्रतिश्यायवदास्थापयेदनुवासयेच्च", text: "evamasyānupaśāntarujaḥ sirāṃ mokṣayet snehasvedaviṣyandaṃ hi vātaduṣṭamasṛṅnirdriyamāṇaṃ nānilaprakopāya punaśca snigdhāya tilvakena saṃyuktaṃ vā tilvakakaṣāyānupānaṃ sarpirvirecanaṃ dadyāt śuddhaṃ ca vātapratiśyāyavadāsthāpayedanuvāsayecca" },
      { type: "verse", number: "18", sanskrit: "अथ तिलान् निस्तुषान् बिल्वफलक्वाथेन भावयेन्निशि दिवा शोषयेदेवं पञ्चाहम् तेभ्यस्तैलं गृहीत्वा वराहमेदोयुक्तं बिल्वमूलमधुयष्टिकाकल्केन पयसा च पचेत् तेन नस्यं शिरोबस्तिं च कुर्यात् सर्वगन्धनिर्यूहेण वा मधुकगर्भं सक्षीरं तैलम् स्नैहिकं च धूमं पिबेत्", text: "atha tilān nistuṣān bilvaphalakvāthena bhāvayenniśi divā śoṣayedevaṃ pañcāham tebhyastailaṃ gṛhītvā varāhamedoyuktaṃ bilvamūlamadhuyaṣṭikākalkena payasā ca pacet tena nasyaṃ śirobastiṃ ca kuryāt sarvagandhaniryūheṇa vā madhukagarbhaṃ sakṣīraṃ tailam snaihikaṃ ca dhūmaṃ pibet" },
      { type: "verse", number: "19", sanskrit: "उपशान्तरुजो ऽस्य च तर्पणम् काश्मर्यमधुकः कुमुदोत्पलोरुपूगकुष्ठबृहतीतमालमांसीसारिवाप्रपौण्डरीकदर्भमूलकशेरुकाभिः पयः साधयेत् तत्तर्पणनस्याभ्यङ्गेषु विदध्यात्", text: "upaśāntarujo 'sya ca tarpaṇam kāśmaryamadhukaḥ kumudotpalorupūgakuṣṭhabṛhatītamālamāṃsīsārivāprapauṇḍarīkadarbhamūlakaśerukābhiḥ payaḥ sādhayet tattarpaṇanasyābhyaṅgeṣu vidadhyāt" },
      { type: "verse", number: "20", sanskrit: "कृष्णसर्पशिरो वा क्षीरे क्वाथयेत् ततः स्नेहमुद्धृत्य चन्दनोशीरशर्करोत्पलकल्केन क्षीरवता पक्वं तर्पणम् अथवा पञ्चमूलजीवनीयकुक्कुटमांसैःपयो विपचेत् ततो नवनीतं घनानन्तासारिवोशीरचन्दनैः सपयस्कैः साधयेत्", text: "kṛṣṇasarpaśiro vā kṣīre kvāthayet tataḥ snehamuddhṛtya candanośīraśarkarotpalakalkena kṣīravatā pakvaṃ tarpaṇam athavā pañcamūlajīvanīyakukkuṭamāṃsaiḥpayo vipacet tato navanītaṃ ghanānantāsārivośīracandanaiḥ sapayaskaiḥ sādhayet" },
      { type: "verse", number: "21", sanskrit: "पुटपाकं च छागोरभ्रवराहाणामन्यतमस्य यकृत् पिप्पलीसैन्धवमधुघृतोपेतं कुर्यात् अञ्जनं चास्य दृक्प्रसादनार्थम्", text: "puṭapākaṃ ca chāgorabhravarāhāṇāmanyatamasya yakṛt pippalīsaindhavamadhughṛtopetaṃ kuryāt añjanaṃ cāsya dṛkprasādanārtham" },
      { type: "verse", number: "22", sanskrit: "कृष्णतिलान् निस्तुषान् कृत्वा स्तन्येन सप्ताहं भावयेच्छोषयेच्च तच्चूर्णं सितोपलासमं कृत्वा मधुकार्धभागेन सैन्धवांशेन कृष्णसर्पशिरसश्चान्तर्धूमदग्धस्य भागेन संसृष्टं दिव्योदकपिष्टां गुटिकां कारयेत्", text: "kṛṣṇatilān nistuṣān kṛtvā stanyena saptāhaṃ bhāvayecchoṣayecca taccūrṇaṃ sitopalāsamaṃ kṛtvā madhukārdhabhāgena saindhavāṃśena kṛṣṇasarpaśirasaścāntardhūmadagdhasya bhāgena saṃsṛṣṭaṃ divyodakapiṣṭāṃ guṭikāṃ kārayet" },
      { type: "verse", number: "23", sanskrit: "गोधासर्पवसायामाजमेदसि च सैन्धवपिप्पलीचूर्णं रसाञ्जनं चावपेत् एषा मासं स्थिता रसक्रिया दृष्टिप्रसादनी रुजाहरा च", text: "godhāsarpavasāyāmājamedasi ca saindhavapippalīcūrṇaṃ rasāñjanaṃ cāvapet eṣā māsaṃ sthitā rasakriyā dṛṣṭiprasādanī rujāharā ca" },
      { type: "verse", number: "24", sanskrit: "उद्धृतसरेण गव्येन दध्नाम्लेन राजतं भाजनमालिम्पेत् नीलीभूतं च तद्विशुष्कं मस्तुना वर्तयः कृताः छायाविशोषिता वाताक्षिरोगं जयन्ति मागधिकाकण्टकारिकाद्वयमूलत्वङ्मधुकसितासैन्धवताम्ररजांस्यजाक्षीरेण पिष्ट्वा ताम्रपात्रमालेपयेत् सप्ताहात् सप्ताहादपनीय पुनस्तथैव पिष्ट्वा लेपयेत् सप्तभिः सप्तरात्रैर्गुटिका कृताः परं वाताक्षिरोगवेदनारागशोफतिमिरकाचनक्तान्ध्यतापाधिमन्थाभिघातहराः", text: "uddhṛtasareṇa gavyena dadhnāmlena rājataṃ bhājanamālimpet nīlībhūtaṃ ca tadviśuṣkaṃ mastunā vartayaḥ kṛtāḥ chāyāviśoṣitā vātākṣirogaṃ jayanti māgadhikākaṇṭakārikādvayamūlatvaṅmadhukasitāsaindhavatāmrarajāṃsyajākṣīreṇa piṣṭvā tāmrapātramālepayet saptāhāt saptāhādapanīya punastathaiva piṣṭvā lepayet saptabhiḥ saptarātrairguṭikā kṛtāḥ paraṃ vātākṣirogavedanārāgaśophatimirakācanaktāndhyatāpādhimanthābhighātaharāḥ" },
      { type: "verse", number: "25", sanskrit: "प्रत्यञ्जनं चात्र स्फटिकशङ्खनाभिमधुकगैरिकैरिक्षुरसपिष्टैर्वर्त्तिः", text: "pratyañjanaṃ cātra sphaṭikaśaṅkhanābhimadhukagairikairikṣurasapiṣṭairvarttiḥ" },
      { type: "verse", number: "26", sanskrit: "अयमेव च सर्वो विधिरधिमन्धादिष्वपि प्रयोज्यः", text: "ayameva ca sarvo vidhiradhimandhādiṣvapi prayojyaḥ" },
      { type: "verse", number: "27", sanskrit: "विशेषतस्त्वधिमन्थे सहचरस्फूर्जातककतकबीजबिल्ववृक्षादनीनिर्यूहेण सपयस्कं सर्पिः सिद्धं पिबेत्", text: "viśeṣatastvadhimanthe sahacarasphūrjātakakatakabījabilvavṛkṣādanīniryūheṇa sapayaskaṃ sarpiḥ siddhaṃ pibet" },
      { type: "verse", number: "28", sanskrit: "सर्पिषानुपशमे तैलं वसां मज्जानं पूर्वोक्तविधिवद्व्यत्यासेन कुर्यात् सर्वथानुपशान्तावुपरिभ्रुवोर्यथोक्तो दाहः", text: "sarpiṣānupaśame tailaṃ vasāṃ majjānaṃ pūrvoktavidhivadvyatyāsena kuryāt sarvathānupaśāntāvuparibhruvoryathokto dāhaḥ" },
      { type: "verse", number: "29", sanskrit: "पित्ताभिष्यन्दाधिमन्थयोः शर्करावचूर्णितं सर्पिः पानम् तिक्तकानामन्यतमं वा", text: "pittābhiṣyandādhimanthayoḥ śarkarāvacūrṇitaṃ sarpiḥ pānam tiktakānāmanyatamaṃ vā" },
      { type: "verse", number: "30", sanskrit: "प्रपौण्डरीकामलकद्विबृहतीदर्भदशमूलशतावरीतालीसपत्रमञ्जिष्ठानीलोत्पलक्वाथः सितास्तन्येनाश्च्योतनम् मधुककटङ्कटेरीनिर्यूहो वा सक्षौद्रश्चन्दनमधुकलोध्रमञ्जिष्ठास्वर्णगैरिकक्वाथस्तीव्रशूलदाहहरः", text: "prapauṇḍarīkāmalakadvibṛhatīdarbhadaśamūlaśatāvarītālīsapatramañjiṣṭhānīlotpalakvāthaḥ sitāstanyenāścyotanam madhukakaṭaṅkaṭerīniryūho vā sakṣaudraścandanamadhukalodhramañjiṣṭhāsvarṇagairikakvāthastīvraśūladāhaharaḥ" },
      { type: "verse", number: "31", sanskrit: "लोध्रदार्वीमधुकप्रपौण्डरीकान्यापोथ्य नन्तकेन बध्नीयात् तेन क्षौद्रसलिलाप्लुतेन सेको वेदनाघ्नः तेनैव च सशर्करस्त्रीस्तन्ये च्छागदुग्धे वा दाहरागघ्नः", text: "lodhradārvīmadhukaprapauṇḍarīkānyāpothya nantakena badhnīyāt tena kṣaudrasalilāplutena seko vedanāghnaḥ tenaiva ca saśarkarastrīstanye cchāgadugdhe vā dāharāgaghnaḥ" },
      { type: "verse", number: "32", sanskrit: "श्वेतलोध्रं मधुकं च समं घृतेन भर्जयित्वा चूर्णयेत् ततः पोट्टलिकावबद्धं स्तन्येन तोयेन वा मृदितमाशु शूलदाहरागशोफानपोहति चन्दननलिनकुमुदनलदादिभिर्वा क्षीरसंस्कृतैः तैश्च शिरोवक्त्रप्रलेपपरिषेकाः", text: "śvetalodhraṃ madhukaṃ ca samaṃ ghṛtena bharjayitvā cūrṇayet tataḥ poṭṭalikāvabaddhaṃ stanyena toyena vā mṛditamāśu śūladāharāgaśophānapohati candananalinakumudanaladādibhirvā kṣīrasaṃskṛtaiḥ taiśca śirovaktrapralepapariṣekāḥ" },
      { type: "verse", number: "33", sanskrit: "एवमसिद्धौ सिराव्यधः पुनः स्निग्धस्य च त्रिफलाकाश्मर्यक्वाथशर्करात्रिवृच्चूर्णौर्विरेकः", text: "evamasiddhau sirāvyadhaḥ punaḥ snigdhasya ca triphalākāśmaryakvāthaśarkarātrivṛccūrṇaurvirekaḥ" },
      { type: "verse", number: "34", sanskrit: "शङ्खमधुकसैन्धवबृहतीमूलत्वचः पयसाजेन पिष्ट्वा ताम्रपात्रं परलेपयेत् पुनः सप्ताहादेवं सप्तभिः सप्तरात्रैर्गुटिकाः कुर्यात् ताः स्तन्यघृष्टाः पित्तामयेष्वञ्जनाद्रुजमपहरन्ति", text: "śaṅkhamadhukasaindhavabṛhatīmūlatvacaḥ payasājena piṣṭvā tāmrapātraṃ paralepayet punaḥ saptāhādevaṃ saptabhiḥ saptarātrairguṭikāḥ kuryāt tāḥ stanyaghṛṣṭāḥ pittāmayeṣvañjanādrujamapaharanti" },
      { type: "verse", number: "35", sanskrit: "सुवर्णगैरिकं निशां देव्येम्भासि स्थितमहः शोषयेत् सप्ताह मेवमेव च सुशीतेन मधुरवर्गकषायेण भावयेदेतच्चूर्णाञ्जनं दाहरागघ्नम्", text: "suvarṇagairikaṃ niśāṃ devyembhāsi sthitamahaḥ śoṣayet saptāha mevameva ca suśītena madhuravargakaṣāyeṇa bhāvayedetaccūrṇāñjanaṃ dāharāgaghnam" },
      { type: "verse", number: "36", sanskrit: "पञ्चाशद्दार्वीपलानि पलिकानि च सारिवामधुककाकोलीद्विनिशामृद्वीकाकाश्मर्यसुनिषण्णकमञ्जिष्ठालोध्रोशीरचन्दानि जलद्रोणेष्टभागावशेषं पचेत् परिस्रुतं च पुनरादर्वीलेपादवतार्य च सितोपलासमांशं मधुघृतद्विपलं प्रक्षिपेत् रसक्रियेयं मधुरा सर्वाक्षिरोगेषु हिता", text: "pañcāśaddārvīpalāni palikāni ca sārivāmadhukakākolīdviniśāmṛdvīkākāśmaryasuniṣaṇṇakamañjiṣṭhālodhrośīracandāni jaladroṇeṣṭabhāgāvaśeṣaṃ pacet parisrutaṃ ca punarādarvīlepādavatārya ca sitopalāsamāṃśaṃ madhughṛtadvipalaṃ prakṣipet rasakriyeyaṃ madhurā sarvākṣirogeṣu hitā" },
      { type: "verse", number: "37", sanskrit: "काश्मर्यस्वरसपिष्टः सारिवाशर्कराकल्को नस्यमिक्षुरसपिष्टं वा यष्ट्याह्वम् क्षतशुक्रोक्तं चात्र तर्पणं पुटपाकश्च", text: "kāśmaryasvarasapiṣṭaḥ sārivāśarkarākalko nasyamikṣurasapiṣṭaṃ vā yaṣṭyāhvam kṣataśukroktaṃ cātra tarpaṇaṃ puṭapākaśca" },
      { type: "verse", number: "38", sanskrit: "श्लेष्माभिष्यन्देधिमन्थे च त्र्यहमुपवासस्तीक्ष्णानि धूमकवलनावनानि शार्ङ्गेष्ठाकुष्ठतगरमुरुङ्गीव्योषैलादारुभिर्बिडालकः", text: "śleṣmābhiṣyandedhimanthe ca tryahamupavāsastīkṣṇāni dhūmakavalanāvanāni śārṅgeṣṭhākuṣṭhatagaramuruṅgīvyoṣailādārubhirbiḍālakaḥ" },
      { type: "verse", number: "39", sanskrit: "तिल्वकबृहतीनिदिग्धिकालोध्रारग्वधमूलत्वग्भिर्गोमूत्रक्वथितैराश्च्योतनं शोफोपदेहकण्डूघ्नम्", text: "tilvakabṛhatīnidigdhikālodhrāragvadhamūlatvagbhirgomūtrakvathitairāścyotanaṃ śophopadehakaṇḍūghnam" },
      { type: "verse", number: "40", sanskrit: "निम्बपत्रकल्कदिग्धं वा लोध्रमङ्गारस्वेदितं चूर्णितं तान्तवावबद्धमुष्णाम्बुमृदितम् तद्वदेवाभयामलकोपकुल्यापाटलीचूर्णानि शिग्रुपल्लवरसो वा मधुमिश्रः मधुशिग्रुपाटलीबिल्वमूलशुण्ठीक्वाथो वा", text: "nimbapatrakalkadigdhaṃ vā lodhramaṅgārasveditaṃ cūrṇitaṃ tāntavāvabaddhamuṣṇāmbumṛditam tadvadevābhayāmalakopakulyāpāṭalīcūrṇāni śigrupallavaraso vā madhumiśraḥ madhuśigrupāṭalībilvamūlaśuṇṭhīkvātho vā" },
      { type: "verse", number: "41", sanskrit: "निम्बपटोलजातिपत्रलोध्रद्वयमहौषधैः खण्डशः कल्पितैर्वस्त्रबद्धैः सक्षौद्रैर्गौडे सीधौ वा परिप्लुतैः सेकः परं श्लेष्मशूलध्रः", text: "nimbapaṭolajātipatralodhradvayamahauṣadhaiḥ khaṇḍaśaḥ kalpitairvastrabaddhaiḥ sakṣaudrairgauḍe sīdhau vā pariplutaiḥ sekaḥ paraṃ śleṣmaśūladhraḥ" },
      { type: "verse", number: "42", sanskrit: "रोहिषपूतीककरञ्जकपित्थास्फोतपीलुबिल्वपत्रशिग्रुसुरसार्कनिम्बपत्रैर्गोमूत्रक्वथितैः स्वेदः", text: "rohiṣapūtīkakarañjakapitthāsphotapīlubilvapatraśigrusurasārkanimbapatrairgomūtrakvathitaiḥ svedaḥ" },
      { type: "verse", number: "43", sanskrit: "तथापि शोफघर्षानुबन्धे यवमदनभूर्जशमीपत्रैः सघृतैर्घृतेनैव वा नाड्याक्षि धूपयेत् लघ्वशितं च द्वितीयेह्नि प्रातर्व्योषविपक्वं यवक्षारावचूर्णितं सर्पिः पाययेत् ततः सिराव्यधो विरेकश्च", text: "tathāpi śophagharṣānubandhe yavamadanabhūrjaśamīpatraiḥ saghṛtairghṛtenaiva vā nāḍyākṣi dhūpayet laghvaśitaṃ ca dvitīyehni prātarvyoṣavipakvaṃ yavakṣārāvacūrṇitaṃ sarpiḥ pāyayet tataḥ sirāvyadho virekaśca" },
      { type: "verse", number: "44", sanskrit: "बृहतीत्वक्शुण्ठीताम्रकांस्यरजांसि दधिमस्तुना पिष्ट्वा तास्रपात्रे प्रलेपयेत् तथैव च सप्ताहे सप्तसप्ताहे च गते वर्तयः कार्याः मरिचहरिद्राभयाञ्जनैर्वा जलपिष्टा वर्तिः त्रिकटुकत्रिफलाविडङ्गसारहरिद्राभिर्वा", text: "bṛhatītvakśuṇṭhītāmrakāṃsyarajāṃsi dadhimastunā piṣṭvā tāsrapātre pralepayet tathaiva ca saptāhe saptasaptāhe ca gate vartayaḥ kāryāḥ maricaharidrābhayāñjanairvā jalapiṣṭā vartiḥ trikaṭukatriphalāviḍaṅgasāraharidrābhirvā" },
      { type: "verse", number: "45", sanskrit: "हरीतकी तुत्थं च समभागं तुत्थादष्टांशेन मरिचमेषा वर्तिः कुमारी सर्वश्लेष्माक्षिरोगघ्नी", text: "harītakī tutthaṃ ca samabhāgaṃ tutthādaṣṭāṃśena maricameṣā vartiḥ kumārī sarvaśleṣmākṣirogaghnī" },
      { type: "verse", number: "46", sanskrit: "विडङ्गचूर्णो वा वारुण्या भावितः शङ्खो बीजपूररसेन मधुकं त्रिफलारसेन पृथगैकध्यं वा चूर्णाञ्जनं वा पिण्डो वा पोथकीबहलकफोत्क्लेशाभिष्यन्दानपहरति", text: "viḍaṅgacūrṇo vā vāruṇyā bhāvitaḥ śaṅkho bījapūrarasena madhukaṃ triphalārasena pṛthagaikadhyaṃ vā cūrṇāñjanaṃ vā piṇḍo vā pothakībahalakaphotkleśābhiṣyandānapaharati" },
      { type: "verse", number: "47", sanskrit: "स्वर्णगैरिकसैन्धवमनश्शिलालाक्षानतकरञ्जिकासुरसशङ्खव्योषतालीसकुष्ठकलिङ्गकदेवदारुनलदजातीमुकुलरसाञ्जनैः सुरामण्डपिष्टैर्वर्त्तिः सर्वश्लेष्माक्षिरोगविकारहरा", text: "svarṇagairikasaindhavamanaśśilālākṣānatakarañjikāsurasaśaṅkhavyoṣatālīsakuṣṭhakaliṅgakadevadārunaladajātīmukularasāñjanaiḥ surāmaṇḍapiṣṭairvarttiḥ sarvaśleṣmākṣirogavikāraharā" },
      { type: "verse", number: "48", sanskrit: "पुष्पकासीसचूर्णं ताम्रसमुद्गे सुरसपत्रस्वरसेन सप्ताहं भावयेत् तच्चूर्णाञ्जनं वर्त्मोपचयपक्ष्मशातघ्नम्", text: "puṣpakāsīsacūrṇaṃ tāmrasamudge surasapatrasvarasena saptāhaṃ bhāvayet taccūrṇāñjanaṃ vartmopacayapakṣmaśātaghnam" },
      { type: "verse", number: "49", sanskrit: "सैन्धवव्योषवराविडङ्गलोध्रप्रपौण्डरीकमधुकतुत्थकतार्क्ष्यशैलताम्रचूर्णैः छागपयःपिष्टैर्मार्कवस्वरसपरिपीतैर्वर्त्तिः काण्डचित्राख्या सर्वाक्षिरोगान् जयति", text: "saindhavavyoṣavarāviḍaṅgalodhraprapauṇḍarīkamadhukatutthakatārkṣyaśailatāmracūrṇaiḥ chāgapayaḥpiṣṭairmārkavasvarasaparipītairvarttiḥ kāṇḍacitrākhyā sarvākṣirogān jayati" },
      { type: "verse", number: "50", sanskrit: "कण्ड्वां मनश्शिलासैन्धवश्वेतमरिचैर्मातुलुङ्गरसपिष्टैर्वर्त्तिः सशोफायां नागरदेवदारुसैन्धवजातिक्षारकैः सुरामण्डपिष्टैः", text: "kaṇḍvāṃ manaśśilāsaindhavaśvetamaricairmātuluṅgarasapiṣṭairvarttiḥ saśophāyāṃ nāgaradevadārusaindhavajātikṣārakaiḥ surāmaṇḍapiṣṭaiḥ" },
      { type: "verse", number: "51", sanskrit: "नक्तमाललशुनशिग्रुशिग्रुकबीजैर्वा रसक्रिया तर्पणं च", text: "naktamālalaśunaśigruśigrukabījairvā rasakriyā tarpaṇaṃ ca" },
      { type: "verse", number: "52", sanskrit: "यकृदाजमगरुप्रियङ्गुनलददेवदारुयुतं पयसि क्वाथयेत्तस्मिन् शीते खजमथिते यन्नवनीतं तदेभिरेवौषधैर्विपक्वम् पुटपाकश्च कुष्ठतगरदार्वीसर्वगन्धैराजेन यकृता सह पिष्टैर्मधुघृतयुतैः", text: "yakṛdājamagarupriyaṅgunaladadevadāruyutaṃ payasi kvāthayettasmin śīte khajamathite yannavanītaṃ tadebhirevauṣadhairvipakvam puṭapākaśca kuṣṭhatagaradārvīsarvagandhairājena yakṛtā saha piṣṭairmadhughṛtayutaiḥ" },
      { type: "verse", number: "53", sanskrit: "रक्तजं पुनरभिष्यन्दमधिमन्थं च पित्तवदुपत्रमेत् स्तन्येक्षुरसशर्करोदकान्यतमेन वाश्च्योतयेत् पुनःपुनश्चास्य रुधिरमवसेचयेत् सिराव्यधेन जलौकोभिश्च तीव्रवेदनायां महतीं घृतमात्रां पाययेत्", text: "raktajaṃ punarabhiṣyandamadhimanthaṃ ca pittavadupatramet stanyekṣurasaśarkarodakānyatamena vāścyotayet punaḥpunaścāsya rudhiramavasecayet sirāvyadhena jalaukobhiśca tīvravedanāyāṃ mahatīṃ ghṛtamātrāṃ pāyayet" },
      { type: "verse", number: "54", sanskrit: "आढकीकुर्यटपाटलीश्रीपर्णीविदुलार्जुनबृहतीचम्पकमालतीमूलानि खर्जूररसपिष्टानि गुटिकाञ्जनम्", text: "āḍhakīkuryaṭapāṭalīśrīparṇīvidulārjunabṛhatīcampakamālatīmūlāni kharjūrarasapiṣṭāni guṭikāñjanam" },
      { type: "verse", number: "55", sanskrit: "केशैर्जलार्द्रैः कांस्यमुद्घर्षयेत् तान् कांस्यमलदिग्धानन्तर्धूमं दग्ध्वा तत् भस्म त्रिफलाक्वाथे सुरसास्वरसे क्षीरे च छागे पञ्चाहं भावयेत् एतच्चूर्णं स्रोतोजतुल्यं प्रत्यञ्जनम्", text: "keśairjalārdraiḥ kāṃsyamudgharṣayet tān kāṃsyamaladigdhānantardhūmaṃ dagdhvā tat bhasma triphalākvāthe surasāsvarase kṣīre ca chāge pañcāhaṃ bhāvayet etaccūrṇaṃ srotojatulyaṃ pratyañjanam" },
      { type: "verse", number: "56", sanskrit: "कृष्णसर्पं पयसि क्वाथयेत्ततः पूतशीतमथितात् स्नेहमुपोषिताय कृकवाकवे दद्यात् तस्य यत् पुरीषं तत् स्नेहाञ्जनम्", text: "kṛṣṇasarpaṃ payasi kvāthayettataḥ pūtaśītamathitāt snehamupoṣitāya kṛkavākave dadyāt tasya yat purīṣaṃ tat snehāñjanam" },
      { type: "verse", number: "57", sanskrit: "कृष्णसर्पमुखमञ्जनसर्पिषोः पूर्णं दर्भवेष्टितं मृदवलिप्तमधोमुखं गोमयेनाग्निनादग्ध्वा ततोञ्जनमादाय पत्रनलदनीलोत्पलतुल्यं चूर्णीकृतं परं दृक्प्रसादजननमञ्जनम्", text: "kṛṣṇasarpamukhamañjanasarpiṣoḥ pūrṇaṃ darbhaveṣṭitaṃ mṛdavaliptamadhomukhaṃ gomayenāgninādagdhvā tatoñjanamādāya patranaladanīlotpalatulyaṃ cūrṇīkṛtaṃ paraṃ dṛkprasādajananamañjanam" },
      { type: "verse", number: "58", sanskrit: "घृतमण्डश्च शर्करामधुकनीलोत्पलैर्मानुषीदुग्धयुक्तैः सिद्धो नस्यमिति भवति चात्र", text: "ghṛtamaṇḍaśca śarkarāmadhukanīlotpalairmānuṣīdugdhayuktaiḥ siddho nasyamiti bhavati cātra" },
      { type: "verse", number: "59", sanskrit: "सर्वेक्षिरोगा यत् प्रायो जायन्ते स्यन्दपूर्वकाः यतश्च रक्तं सन्दूष्य तानतस्त्वरया जयेत्", text: "sarvekṣirogā yat prāyo jāyante syandapūrvakāḥ yataśca raktaṃ sandūṣya tānatastvarayā jayet" },
      { type: "verse", number: "60", sanskrit: "सर्वोर्ध्वजत्रुगस्रोतस्यन्दनात् स्यन्द उच्यते तत्स्थानां तद्वदङ्गानामधिमन्थो ऽतिमन्थनात्", text: "sarvordhvajatrugasrotasyandanāt syanda ucyate tatsthānāṃ tadvadaṅgānāmadhimantho 'timanthanāt" },
      { type: "verse", number: "61", sanskrit: "वाते ऽक्षिसेकस्सैरण्डबृहतीमधुशिग्रुणा सिद्धेन पञ्चमूलेन ससितैः पित्तरक्तयोः", text: "vāte 'kṣisekassairaṇḍabṛhatīmadhuśigruṇā siddhena pañcamūlena sasitaiḥ pittaraktayoḥ" },
      { type: "verse", number: "62", sanskrit: "दार्वीलाक्षोत्पलद्राक्षामञ्जिष्ठामधुकद्वयैः श्लेष्मणि त्रिफलाशुण्ठीनिम्बलोध्राटरूषकैः समस्तैस्सन्निपातोत्थे कुर्यात् स्यन्दे ऽक्षिसेचनम्", text: "dārvīlākṣotpaladrākṣāmañjiṣṭhāmadhukadvayaiḥ śleṣmaṇi triphalāśuṇṭhīnimbalodhrāṭarūṣakaiḥ samastaissannipātotthe kuryāt syande 'kṣisecanam" },
      { type: "verse", number: "63", sanskrit: "तुत्थव्योषाभयालोध्रयष्ट्याह्वैस्ताम्रसंस्थितैः धान्याम्लपिष्टैः सेकोयं सर्वाभिष्यन्दरुक्प्रणुत्", text: "tutthavyoṣābhayālodhrayaṣṭyāhvaistāmrasaṃsthitaiḥ dhānyāmlapiṣṭaiḥ sekoyaṃ sarvābhiṣyandarukpraṇut" },
      { type: "verse", number: "64", sanskrit: "तद्वतुत्थाभयालोध्रयष्टीमधुरसाञ्जनैः शताह्वार्द्धांशसंयुक्तैः सेकः सर्वाक्षिशूलजित्", text: "tadvatutthābhayālodhrayaṣṭīmadhurasāñjanaiḥ śatāhvārddhāṃśasaṃyuktaiḥ sekaḥ sarvākṣiśūlajit" },
      { type: "verse", number: "65", sanskrit: "पुष्पाञ्जनसिताक्षौद्रैस्ताम्रसंस्थैस्तिलाम्भसा सेचनं हन्ति रुग्रागदाहश्वयथुघर्षणम्", text: "puṣpāñjanasitākṣaudraistāmrasaṃsthaistilāmbhasā secanaṃ hanti rugrāgadāhaśvayathugharṣaṇam" },
      { type: "verse", number: "66", sanskrit: "द्विनिशात्रिफलामुस्तैः प्रमदादुग्धकल्कितैः सेकः सशर्कराक्षौद्रैरभिघातरुजापहः", text: "dviniśātriphalāmustaiḥ pramadādugdhakalkitaiḥ sekaḥ saśarkarākṣaudrairabhighātarujāpahaḥ" },
      { type: "verse", number: "67", sanskrit: "निषिक्तं तुत्थकं वारान् गोर्जले पञ्चविंशतिम् स्तन्ये वा छागदुग्धे वा सद्यःकोपे तदञ्जनम्", text: "niṣiktaṃ tutthakaṃ vārān gorjale pañcaviṃśatim stanye vā chāgadugdhe vā sadyaḥkope tadañjanam" },
      { type: "verse", number: "68", sanskrit: "बदरीदलयष्ट्याह्वतुत्थधात्रीफलैः समैः पुटअन्तर्बादराग्नीद्धैर्दृगुत्कोपघ्नमञ्जनम्", text: "badarīdalayaṣṭyāhvatutthadhātrīphalaiḥ samaiḥ puṭAantarbādarāgnīddhairdṛgutkopaghnamañjanam" },
      { type: "verse", number: "69", sanskrit: "बृहत्यैरण्डमूलत्वक्शिग्रुमूलैः ससैन्धवैः वर्त्तिराजपयःपिष्टैस्सर्ववाताक्षिरोगजित्", text: "bṛhatyairaṇḍamūlatvakśigrumūlaiḥ sasaindhavaiḥ varttirājapayaḥpiṣṭaissarvavātākṣirogajit" },
      { type: "verse", number: "70", sanskrit: "सुमनःक्षारकाः शङ्खस्त्रिफला मधुकं बला पित्तरक्तापहा वर्त्तिः पिष्टा दिव्येन वारिणा", text: "sumanaḥkṣārakāḥ śaṅkhastriphalā madhukaṃ balā pittaraktāpahā varttiḥ piṣṭā divyena vāriṇā" },
      { type: "verse", number: "71", sanskrit: "सैन्धवं त्रिफला व्योषं शङ्खनाभिस्समुद्रजः फेनः शैलेयकं सर्जो वर्त्तिः श्लेष्माक्षिरोगजित्", text: "saindhavaṃ triphalā vyoṣaṃ śaṅkhanābhissamudrajaḥ phenaḥ śaileyakaṃ sarjo varttiḥ śleṣmākṣirogajit" },
      { type: "verse", number: "72", sanskrit: "शङ्खविद्रुमवैडूर्यलोहिताक्षप्लवास्थिभिः स्रोतोजश्वेतमरिचैर्वर्त्तिः सर्वाक्षिरोगजित्", text: "śaṅkhavidrumavaiḍūryalohitākṣaplavāsthibhiḥ srotojaśvetamaricairvarttiḥ sarvākṣirogajit" },
      { type: "verse", number: "73", sanskrit: "पिप्पल्यः किंशुकरसो वसा सर्पस्य सैधवम् घृतं च जीर्णं सर्वाक्षिविकारघ्नी रसक्रिया", text: "pippalyaḥ kiṃśukaraso vasā sarpasya saidhavam ghṛtaṃ ca jīrṇaṃ sarvākṣivikāraghnī rasakriyā" },
      { type: "verse", number: "74", sanskrit: "कृष्णसर्पवसा क्षौद्रं रसो धात्र्या रसक्रिया शस्ता सर्वाक्षिरोगेषु काचार्मपटलेषु च", text: "kṛṣṇasarpavasā kṣaudraṃ raso dhātryā rasakriyā śastā sarvākṣirogeṣu kācārmapaṭaleṣu ca" },
      { type: "verse", number: "75", sanskrit: "रसाञ्जनं शृङ्गवेरमभया तुत्थकं शुभम् यथोत्तरं द्विगुणितैस्तैर्वर्त्तिरपराजिता", text: "rasāñjanaṃ śṛṅgaveramabhayā tutthakaṃ śubham yathottaraṃ dviguṇitaistairvarttiraparājitā" },
      { type: "verse", number: "76", sanskrit: "ऋते वातादभिष्यन्दात्तिमिराणि कुकूणकम् पोथकीपिटकाः पिल्लानर्माणि च नियच्छति", text: "ṛte vātādabhiṣyandāttimirāṇi kukūṇakam pothakīpiṭakāḥ pillānarmāṇi ca niyacchati" },
      { type: "verse", number: "77", sanskrit: "ताम्रे मस्तुसमुद्घृष्टं तुत्थकं श्यावतां गतम् सर्वाभिष्यन्दशुक्लार्मसिराजालजिदञ्जनम्", text: "tāmre mastusamudghṛṣṭaṃ tutthakaṃ śyāvatāṃ gatam sarvābhiṣyandaśuklārmasirājālajidañjanam" },
      { type: "verse", number: "78", sanskrit: "मरिचवरलवणभागो भागौ द्वौ कणसमुद्रफेनाभ्याम् सौवीरभागनवकं चित्रायां चूर्णितं कफामयजित्", text: "maricavaralavaṇabhāgo bhāgau dvau kaṇasamudraphenābhyām sauvīrabhāganavakaṃ citrāyāṃ cūrṇitaṃ kaphāmayajit" },
      { type: "verse", number: "79", sanskrit: "मरिचामलकजलोद्भवतुत्थाञ्जनताप्यधातुभिः क्रमवृद्धैः षण्माक्षिक इति योगस्तिमिरार्मक्लेदकाचकण्डूघ्रः", text: "maricāmalakajalodbhavatutthāñjanatāpyadhātubhiḥ kramavṛddhaiḥ ṣaṇmākṣika iti yogastimirārmakledakācakaṇḍūghraḥ" },
      { type: "verse", number: "80", sanskrit: "पिप्पलीं सतगरोत्पलपत्रा वर्त्तयेत् समधुकां सहरिद्रां एतया सततमञ्जयितव्यं यः सुपर्णसममिच्छति चक्षुः", text: "pippalīṃ satagarotpalapatrā varttayet samadhukāṃ saharidrāṃ etayā satatamañjayitavyaṃ yaḥ suparṇasamamicchati cakṣuḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 20,
    lang: "sa",
    content: [
      { type: "heading", heading: "Тришна рога — жажда" },
      { type: "text", text: "Глава 20 Уттара стханы — «Тришна рога» — посвящена специализированному разделу: жажда. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः अक्षिपाकपिल्लप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ akṣipākapillapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "शुष्काक्षिपाके वाताभिष्यन्दविहितं सर्पिः पिबेत् कुलीररसक्षीरसिद्धं वा", text: "śuṣkākṣipāke vātābhiṣyandavihitaṃ sarpiḥ pibet kulīrarasakṣīrasiddhaṃ vā" },
      { type: "verse", number: "3", sanskrit: "दार्वीप्रपौण्डरीकयोः क्वाथ आश्च्योतनमक्षिपाकघ्नम् मञ्जिष्ठामधुककालानुसारीसारिवालोध्रलाक्षाप्रपौण्डरीकाणामक्षिपाकरक्तराजीघ्नम् मृद्वीकाचन्दनकल्कस्तण्डुलाम्बुपरिस्रुतो मधुमानश्रुदाहहरः लोध्रकोरण्डकपुष्पक्वाथो वेदनाहरः", text: "dārvīprapauṇḍarīkayoḥ kvātha āścyotanamakṣipākaghnam mañjiṣṭhāmadhukakālānusārīsārivālodhralākṣāprapauṇḍarīkāṇāmakṣipākaraktarājīghnam mṛdvīkācandanakalkastaṇḍulāmbuparisruto madhumānaśrudāhaharaḥ lodhrakoraṇḍakapuṣpakvātho vedanāharaḥ" },
      { type: "verse", number: "4", sanskrit: "अणुतैलं नस्यम् सारिवाविदारीबलामधुकोत्पलद्राक्षाटरूषकजीवकचन्दनैर्जाङ्गलरसक्षीरोपेतं तैलं साधितं नावनात् सर्वोर्ध्वजत्रुजान् गदान् वातपित्तोत्तरान् निहन्ति", text: "aṇutailaṃ nasyam sārivāvidārībalāmadhukotpaladrākṣāṭarūṣakajīvakacandanairjāṅgalarasakṣīropetaṃ tailaṃ sādhitaṃ nāvanāt sarvordhvajatrujān gadān vātapittottarān nihanti" },
      { type: "verse", number: "5", sanskrit: "स्न्गिधाश्चात्र तर्पणपुटपाकाः वातपित्तान्यतरोद्रेकतश्च यथास्वमभिष्यन्दविधिः", text: "sngidhāścātra tarpaṇapuṭapākāḥ vātapittānyatarodrekataśca yathāsvamabhiṣyandavidhiḥ" },
      { type: "verse", number: "6", sanskrit: "आदर्शमण्डले घृताक्तकेशान् घृष्ट्वान्तर्धूमं दहेत् सा मषी घृतपिष्टायसभाजनस्थिताक्षिपाकमञ्जना दपहरति", text: "ādarśamaṇḍale ghṛtāktakeśān ghṛṣṭvāntardhūmaṃ dahet sā maṣī ghṛtapiṣṭāyasabhājanasthitākṣipākamañjanā dapaharati" },
      { type: "verse", number: "7", sanskrit: "मञ्जिष्ठाफलत्रिककटङ्कटेरीनिष्क्वाथे लोहस्रोतोञ्जनचूर्णमापिण्डीभावात् पचेत् एतच्चूर्णाञ्जनमभयं दाहोषारागाश्रुहरम्", text: "mañjiṣṭhāphalatrikakaṭaṅkaṭerīniṣkvāthe lohasrotoñjanacūrṇamāpiṇḍībhāvāt pacet etaccūrṇāñjanamabhayaṃ dāhoṣārāgāśruharam" },
      { type: "verse", number: "8", sanskrit: "ताम्ररजस्सैर्यकपुष्पपुण्ड्राह्वमधुककालानुसारीसारिवाः छागेन पयसा पिष्टाः पिण्डाञ्जनम्", text: "tāmrarajassairyakapuṣpapuṇḍrāhvamadhukakālānusārīsārivāḥ chāgena payasā piṣṭāḥ piṇḍāñjanam" },
      { type: "verse", number: "9", sanskrit: "आनूषवसा शुण्ठीसैन्धवचूर्णान्विता स्नेहाञ्जनम् एवमप्यशान्तौ मधुकसिद्धः शताह्वाचूर्णयुक्तो घृतमण्डस्तथा पयो वा बस्तिः", text: "ānūṣavasā śuṇṭhīsaindhavacūrṇānvitā snehāñjanam evamapyaśāntau madhukasiddhaḥ śatāhvācūrṇayukto ghṛtamaṇḍastathā payo vā bastiḥ" },
      { type: "verse", number: "10", sanskrit: "सशोफाल्पशोफयोस्तु स्निग्धस्विन्नस्यानु सिराविध्येत्", text: "saśophālpaśophayostu snigdhasvinnasyānu sirāvidhyet" },
      { type: "verse", number: "11", sanskrit: "द्राक्षाभयाक्वाथस्त्रिवृत्कल्कवान् सघृतो विरेकः विरिक्तस्य यथादोषोदयमास्थापनम्", text: "drākṣābhayākvāthastrivṛtkalkavān saghṛto virekaḥ viriktasya yathādoṣodayamāsthāpanam" },
      { type: "verse", number: "12", sanskrit: "ततः पिण्डस्विन्नशिरसः सर्षपतैलेन सैन्धवयुतेन वा सर्पिषा फणिज्जकयुक्तेन वा अणुतैलेन शिंरोविरेकः विरिक्तशिरसो ऽनुवासनं क्षीरसर्पिषा धूमपानं च", text: "tataḥ piṇḍasvinnaśirasaḥ sarṣapatailena saindhavayutena vā sarpiṣā phaṇijjakayuktena vā aṇutailena śiṃrovirekaḥ viriktaśiraso 'nuvāsanaṃ kṣīrasarpiṣā dhūmapānaṃ ca" },
      { type: "verse", number: "13", sanskrit: "शिरोनेत्रं चास्य सुनिषण्णकपत्तूरैरण्डपत्रैः क्षीराम्बुस्विन्नैः संस्वेदयेत्", text: "śironetraṃ cāsya suniṣaṇṇakapattūrairaṇḍapatraiḥ kṣīrāmbusvinnaiḥ saṃsvedayet" },
      { type: "verse", number: "14", sanskrit: "घृतभृष्टं लोध्रचूर्णं सूक्ष्मवासस्थमुष्णोदकविमृदितमाश्च्योतनम् शुष्काक्षिपाकोक्तं च वेदनाघ्नम्", text: "ghṛtabhṛṣṭaṃ lodhracūrṇaṃ sūkṣmavāsasthamuṣṇodakavimṛditamāścyotanam śuṣkākṣipākoktaṃ ca vedanāghnam" },
      { type: "verse", number: "15", sanskrit: "एवमशान्तवेदनं सन्धावैरुपक्रमेत्", text: "evamaśāntavedanaṃ sandhāvairupakramet" },
      { type: "verse", number: "16", sanskrit: "शशशिरःकपालं सैन्धवं कांस्ये स्तन्यघृष्टं सन्धावो वेदनाघ्नः तद्वत्ताम्रं च लोहे गोमूत्रघृष्टं घृतधूपितम्", text: "śaśaśiraḥkapālaṃ saindhavaṃ kāṃsye stanyaghṛṣṭaṃ sandhāvo vedanāghnaḥ tadvattāmraṃ ca lohe gomūtraghṛṣṭaṃ ghṛtadhūpitam" },
      { type: "verse", number: "17", sanskrit: "शिग्रुपल्लवरसश्च ताम्रघृष्टो घृतधूपितः शङ्खं ताम्रे स्तन्येन घृष्टं घृताभ्यक्तयवशमीपत्रधूपितं घर्षवेदनाघ्नम्", text: "śigrupallavarasaśca tāmraghṛṣṭo ghṛtadhūpitaḥ śaṅkhaṃ tāmre stanyena ghṛṣṭaṃ ghṛtābhyaktayavaśamīpatradhūpitaṃ gharṣavedanāghnam" },
      { type: "verse", number: "18", sanskrit: "उदुम्बरफलं लोहे स्तन्यघृष्टं घृताभ्यक्तशमीपत्रधूपितं शूलरागाश्रुघर्षघ्नम् दधिसरः पिप्पलीसैन्धवयुक्तस्ताम्रे घृष्टश्शोफघर्षाश्रुवेदनाघ्नः", text: "udumbaraphalaṃ lohe stanyaghṛṣṭaṃ ghṛtābhyaktaśamīpatradhūpitaṃ śūlarāgāśrugharṣaghnam dadhisaraḥ pippalīsaindhavayuktastāmre ghṛṣṭaśśophagharṣāśruvedanāghnaḥ" },
      { type: "verse", number: "19", sanskrit: "मृत्कपालं कांस्ये तिलोदकघृष्टं घृताक्तनिम्बपत्रधूपितं शोफकण्डूघर्षाश्रुशूलरागघ्नम्", text: "mṛtkapālaṃ kāṃsye tilodakaghṛṣṭaṃ ghṛtāktanimbapatradhūpitaṃ śophakaṇḍūgharṣāśruśūlarāgaghnam" },
      { type: "verse", number: "20", sanskrit: "सन्धावाञ्जितं चाक्षि स्तन्येनानुसिञ्चेत् त्रिःपरं च तैर्न्नाञ्जयेत् अथाञ्जनानि", text: "sandhāvāñjitaṃ cākṣi stanyenānusiñcet triḥparaṃ ca tairnnāñjayet athāñjanāni" },
      { type: "verse", number: "21", sanskrit: "मधुकबृहतीत्वक्ताम्ररजांस्यजाक्षीरपिष्टानि शम्यामलकपत्रैर्घृताप्लुतैरनेकशो धूपितानि पिण्डाञ्जनं शोफवेदनाघ्नम्", text: "madhukabṛhatītvaktāmrarajāṃsyajākṣīrapiṣṭāni śamyāmalakapatrairghṛtāplutairanekaśo dhūpitāni piṇḍāñjanaṃ śophavedanāghnam" },
      { type: "verse", number: "22", sanskrit: "तालीसपत्रपिप्पलीलोहर्रजोञ्जनकासीसतगरजातीमुकुलसैन्धवैर्गोमूत्रपिष्टैस्ताम्रमालिप्तं सप्तरात्रं स्थापयित्वा पुनस्तद्वदेवपिष्टैर्गुटिकाः कार्यास्ताः स्तन्यघृष्टाः स्तम्भश्वयथुहर्षघर्षाश्रुकण्डूघ्न्यः", text: "tālīsapatrapippalīloharrajoñjanakāsīsatagarajātīmukulasaindhavairgomūtrapiṣṭaistāmramāliptaṃ saptarātraṃ sthāpayitvā punastadvadevapiṣṭairguṭikāḥ kāryāstāḥ stanyaghṛṣṭāḥ stambhaśvayathuharṣagharṣāśrukaṇḍūghnyaḥ" },
      { type: "verse", number: "23", sanskrit: "अबद्धास्थिसहकारमांसं विगतत्वचं समताम्रचूर्णमीषत् सैन्धवोपेतं गव्येन दध्ना पिष्ट्वा ताम्रमालेपयेत् शुष्कं शुष्कं तथैव च पिष्ट्वा पुनर्लेपयेत् एतत् सप्तभिः सप्ताहैः पिण्डाञ्जनं कृतं सर्वाक्षिपाकाश्रुघर्षशोफरागवर्त्मोपचयघ्नम् अश्मन्तकाम्लवेतसपरूषककोलदाडिमैः कृता रसक्रिया सशोफाल्पशोफपूयालसान् नाशयति इत्थमपि शोफानुवृत्तौ पुनरस्रावसेकः शिरोविरेकश्च", text: "abaddhāsthisahakāramāṃsaṃ vigatatvacaṃ samatāmracūrṇamīṣat saindhavopetaṃ gavyena dadhnā piṣṭvā tāmramālepayet śuṣkaṃ śuṣkaṃ tathaiva ca piṣṭvā punarlepayet etat saptabhiḥ saptāhaiḥ piṇḍāñjanaṃ kṛtaṃ sarvākṣipākāśrugharṣaśopharāgavartmopacayaghnam aśmantakāmlavetasaparūṣakakoladāḍimaiḥ kṛtā rasakriyā saśophālpaśophapūyālasān nāśayati itthamapi śophānuvṛttau punarasrāvasekaḥ śirovirekaśca" },
      { type: "verse", number: "24", sanskrit: "अम्लोषितं पित्ताभिष्यन्दवदुपाचरेत् पिल्लसाधनं चेक्षेत", text: "amloṣitaṃ pittābhiṣyandavadupācaret pillasādhanaṃ cekṣeta" },
      { type: "verse", number: "25", sanskrit: "पित्तकफरक्तनिचयोत्क्लिष्टवर्त्मपोथकीबिसाख्यकुकूणकपक्ष्मोपरोधपूयालसशुष्काक्षिपाकाल्पशोफाम्लोषिता वातवर्ज्याश्चस्यन्दाधिमन्था इत्यष्टादशदीर्घकालानुबन्धिनो रोगाः पिल्लसंज्ञाः", text: "pittakapharaktanicayotkliṣṭavartmapothakībisākhyakukūṇakapakṣmoparodhapūyālasaśuṣkākṣipākālpaśophāmloṣitā vātavarjyāścasyandādhimanthā ityaṣṭādaśadīrghakālānubandhino rogāḥ pillasaṃjñāḥ" },
      { type: "verse", number: "26", sanskrit: "एषां क्रिया यथास्वमुपदिष्टैव पुनश्च पिल्लीभूतानां सामान्येनोपदिश्यते", text: "eṣāṃ kriyā yathāsvamupadiṣṭaiva punaśca pillībhūtānāṃ sāmānyenopadiśyate" },
      { type: "verse", number: "27", sanskrit: "अथ पिल्लाक्षिरोगिणं स्नेहयित्वा वामयेत् कृतक्रमस्य सिराव्यधस्ततो विरेकः कृतविरेकस्य वर्त्मनी लिखेत् सकृल्लेखनादशुद्धौ पुनर्लेखयेत् जलौकोभिश्च ग्राहयेत्", text: "atha pillākṣirogiṇaṃ snehayitvā vāmayet kṛtakramasya sirāvyadhastato virekaḥ kṛtavirekasya vartmanī likhet sakṛllekhanādaśuddhau punarlekhayet jalaukobhiśca grāhayet" },
      { type: "verse", number: "28", sanskrit: "प्रियङ्गुलोध्रपद्मकेसरचन्दनमधुककल्केन समाक्षिकेण बिडालकः तुवरिकाफलत्रिकरोचनाक्वाथेन मधुमता सायं प्रातः सदा प्रक्षालनमञ्जनान्ते च कषायवृक्षपल्लवकषायेण", text: "priyaṅgulodhrapadmakesaracandanamadhukakalkena samākṣikeṇa biḍālakaḥ tuvarikāphalatrikarocanākvāthena madhumatā sāyaṃ prātaḥ sadā prakṣālanamañjanānte ca kaṣāyavṛkṣapallavakaṣāyeṇa" },
      { type: "verse", number: "29", sanskrit: "तैरेव च पत्रैरुष्णाप्रियतायामन्तरान्तरा स्वेदः", text: "taireva ca patrairuṣṇāpriyatāyāmantarāntarā svedaḥ" },
      { type: "verse", number: "30", sanskrit: "तुत्थकपलं विंशतिश्च श्वेतमरिचानि धान्याम्ल पिष्टानि तत्पलैस्त्रिंशता ताम्रपात्रे समालोडितानि बहुवर्णामपि पिल्लानां परममाश्च्योतनम्", text: "tutthakapalaṃ viṃśatiśca śvetamaricāni dhānyāmla piṣṭāni tatpalaistriṃśatā tāmrapātre samāloḍitāni bahuvarṇāmapi pillānāṃ paramamāścyotanam" },
      { type: "verse", number: "31", sanskrit: "अञ्जनं चास्याम्रधातकीपुष्पतिलपर्णीकल्केन च वर्त्तिः हरीतक्याढकीश्चाष्टगुणेम्भास्यष्टभागावशेषं क्वाथयेत् पुनश्च परिस्राव्यादर्वीप्रलेपाद्रसक्रियेयं पिल्लाक्षिरोपणी पलाशशाखास्वरसे क्वाथ्यमाने बृहत्युशीररजोदद्यात् तत्घनीभूतं शीतमञ्जनम् सुरसारसपिष्टैर्वा वचलदेवदारुभिः गोपित्तपिष्टाभ्यां वा व्योषरसाञ्जनाभ्याम्", text: "añjanaṃ cāsyāmradhātakīpuṣpatilaparṇīkalkena ca varttiḥ harītakyāḍhakīścāṣṭaguṇembhāsyaṣṭabhāgāvaśeṣaṃ kvāthayet punaśca parisrāvyādarvīpralepādrasakriyeyaṃ pillākṣiropaṇī palāśaśākhāsvarase kvāthyamāne bṛhatyuśīrarajodadyāt tatghanībhūtaṃ śītamañjanam surasārasapiṣṭairvā vacaladevadārubhiḥ gopittapiṣṭābhyāṃ vā vyoṣarasāñjanābhyām" },
      { type: "verse", number: "32", sanskrit: "हरितालसौवीरकाञ्जनसमांशं वा ताम्रचूर्णमञ्जनम् परिपेलवकासीसहरिद्राद्वयसर्षपप्रियङ्गुतगरपिप्पलीकल्केन ताम्रभाजनमन्तर्लेपयित्वा सौवीरककुम्भेधोमुखं सप्ताहं वासयेत् ततो गुटिकाश्चूर्णं वा कुर्यात्", text: "haritālasauvīrakāñjanasamāṃśaṃ vā tāmracūrṇamañjanam paripelavakāsīsaharidrādvayasarṣapapriyaṅgutagarapippalīkalkena tāmrabhājanamantarlepayitvā sauvīrakakumbhedhomukhaṃ saptāhaṃ vāsayet tato guṭikāścūrṇaṃ vā kuryāt" },
      { type: "verse", number: "33", sanskrit: "तुत्थगैरिकचूर्णं छगलीपयःपिष्टं गुटिका प्रत्यञ्जनम् चूर्ण एव वा दिव्योदकभावितः स एव वा तदाप्लुतो नेत्राश्च्योतनमिति भवति चात्र", text: "tutthagairikacūrṇaṃ chagalīpayaḥpiṣṭaṃ guṭikā pratyañjanam cūrṇa eva vā divyodakabhāvitaḥ sa eva vā tadāpluto netrāścyotanamiti bhavati cātra" },
      { type: "verse", number: "34", sanskrit: "वर्त्मावलेखं बहुशस्तद्वच्छोणितमोक्षणम् पुनः पुनर्विरेकं च पिल्लरोगातुरो भजेत्", text: "vartmāvalekhaṃ bahuśastadvacchoṇitamokṣaṇam punaḥ punarvirekaṃ ca pillarogāturo bhajet" },
      { type: "verse", number: "35", sanskrit: "पूयालसेत्वशान्तेन्ते दाहः सूक्ष्मशलाकया", text: "pūyālasetvaśāntente dāhaḥ sūkṣmaśalākayā" },
      { type: "verse", number: "36", sanskrit: "चतुर्नवतिरित्यक्ष्णोर्हेतुलक्षणसाधनैः परस्परमसङ्कीर्णाःकार्त्स्न्येन गदिता गदाः", text: "caturnavatirityakṣṇorhetulakṣaṇasādhanaiḥ parasparamasaṅkīrṇāḥkārtsnyena gaditā gadāḥ" },
      { type: "verse", number: "37", sanskrit: "सर्वदा च निषेवेत स्वस्थोपि नयनप्रियः पुराणयवगोधूमशालिषष्टिककोद्रवान्", text: "sarvadā ca niṣeveta svasthopi nayanapriyaḥ purāṇayavagodhūmaśāliṣaṣṭikakodravān" },
      { type: "verse", number: "38", sanskrit: "मुद्गादीन्कफपित्तघ्नान् भूरिसर्पिःपरिप्लुतान् शाकं चैवंविधं मांसं जाङ्गलं दाडिमं सिताम्", text: "mudgādīnkaphapittaghnān bhūrisarpiḥpariplutān śākaṃ caivaṃvidhaṃ māṃsaṃ jāṅgalaṃ dāḍimaṃ sitām" },
      { type: "verse", number: "39", sanskrit: "सैन्धवं त्रिफलां द्राक्षां वारि पाने च नाभसम् आतपत्रं पदत्राणं विधिवद्दोषशोधनम्", text: "saindhavaṃ triphalāṃ drākṣāṃ vāri pāne ca nābhasam ātapatraṃ padatrāṇaṃ vidhivaddoṣaśodhanam" },
      { type: "verse", number: "40", sanskrit: "वर्जयेद्वेगसंरोधमजीर्णाध्यशनानि च क्रोधशोकदिवास्वप्नरात्रिजागरणातपान् विदाहविष्टम्भकरं यच्चेहाहारभेषजम्", text: "varjayedvegasaṃrodhamajīrṇādhyaśanāni ca krodhaśokadivāsvapnarātrijāgaraṇātapān vidāhaviṣṭambhakaraṃ yaccehāhārabheṣajam" },
      { type: "verse", number: "41", sanskrit: "द्वे पादमध्ये पृथुसन्निवेशे सिरे गते ते बहुधा च नेत्रे ताम्रङ्क्षणोद्वर्तनलेपनादीन् पादप्रयुक्तान् नयनं नयन्ति", text: "dve pādamadhye pṛthusanniveśe sire gate te bahudhā ca netre tāmraṅkṣaṇodvartanalepanādīn pādaprayuktān nayanaṃ nayanti" },
      { type: "verse", number: "42", sanskrit: "मलोष्णसङ्घट्टनपीडनाद्यैस्ता दूष्यन्ते नयनानि दुष्टाः भजेत् सदा दृष्टिहितानि तस्मादुपानदभ्यञ्जनधावनानि", text: "maloṣṇasaṅghaṭṭanapīḍanādyaistā dūṣyante nayanāni duṣṭāḥ bhajet sadā dṛṣṭihitāni tasmādupānadabhyañjanadhāvanāni" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 21,
    lang: "sa",
    content: [
      { type: "heading", heading: "Хикка рога — икота" },
      { type: "text", text: "Глава 21 Уттара стханы — «Хикка рога» — посвящена специализированному разделу: икота. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः कर्णरोगविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ karṇarogavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "प्रतिश्यायजलक्रीडाकर्णकण्डूयनैर्मरुत् मिथ्यायोगेन शब्दस्य कुपितोन्यैश्च कोपनैः", text: "pratiśyāyajalakrīḍākarṇakaṇḍūyanairmarut mithyāyogena śabdasya kupitonyaiśca kopanaiḥ" },
      { type: "verse", number: "3", sanskrit: "प्राप्य श्रोत्रसिराः कुर्याच्छूलं स्रोतसि वेगवत् अर्धावभेदकं स्तम्भं शिशिरानभिनन्दनम्", text: "prāpya śrotrasirāḥ kuryācchūlaṃ srotasi vegavat ardhāvabhedakaṃ stambhaṃ śiśirānabhinandanam" },
      { type: "verse", number: "4", sanskrit: "चिराच्च पाकः पक्वं तु लसीकामल्पशः स्रवेत् श्रोत्रं शून्यमकस्माच्च स्यात् सञ्चारविचारवत्", text: "cirācca pākaḥ pakvaṃ tu lasīkāmalpaśaḥ sravet śrotraṃ śūnyamakasmācca syāt sañcāravicāravat" },
      { type: "verse", number: "5", sanskrit: "शूलं पित्तात् सदाहोषा शीतेच्छाश्वथथुज्वरम् आशुपाकं प्रपक्वं च सपीतलसिकास्रुति सा लसीकास्पृशोद्यद्यत्तत्पाकमुपैति च", text: "śūlaṃ pittāt sadāhoṣā śītecchāśvathathujvaram āśupākaṃ prapakvaṃ ca sapītalasikāsruti sā lasīkāspṛśodyadyattatpākamupaiti ca" },
      { type: "verse", number: "6", sanskrit: "कफाच्छिरोहनुग्रीवागौरवं मन्दता रुजः कण्डूःश्वयथुरुष्णेच्छा पाकाच्छ्वेतघनस्रुतिः", text: "kaphācchirohanugrīvāgauravaṃ mandatā rujaḥ kaṇḍūḥśvayathuruṣṇecchā pākācchvetaghanasrutiḥ" },
      { type: "verse", number: "7", sanskrit: "करोति श्रवणे शूलमभिघातादिदूषितम् रक्तं पित्तसमानार्ति किञ्चिद्वाधिकलक्षणम्", text: "karoti śravaṇe śūlamabhighātādidūṣitam raktaṃ pittasamānārti kiñcidvādhikalakṣaṇam" },
      { type: "verse", number: "8", sanskrit: "शूलं समुदितैर्दोषैः सशोफज्वरतीव्ररुक् पर्यायादुष्णशीतेच्छं जायते श्रुतिजाड्यवत् पक्वं सितासितारक्तघनपूयप्रवाहि च", text: "śūlaṃ samuditairdoṣaiḥ saśophajvaratīvraruk paryāyāduṣṇaśītecchaṃ jāyate śrutijāḍyavat pakvaṃ sitāsitāraktaghanapūyapravāhi ca" },
      { type: "verse", number: "9", sanskrit: "शब्दवाहिसिरासंस्थे शृणोति पवने मुहुः नादानकस्माद्विविधान् कर्णनादं वदन्ति तम्", text: "śabdavāhisirāsaṃsthe śṛṇoti pavane muhuḥ nādānakasmādvividhān karṇanādaṃ vadanti tam" },
      { type: "verse", number: "10", sanskrit: "श्लेष्मणानुगतो वायुर्नादो वा समुपेक्षितः उच्चैः कृच्छ्राच्छ्रुतिं कुर्यात् बधिरत्वं क्रमेण च", text: "śleṣmaṇānugato vāyurnādo vā samupekṣitaḥ uccaiḥ kṛcchrācchrutiṃ kuryāt badhiratvaṃ krameṇa ca" },
      { type: "verse", number: "11", sanskrit: "वोतन शोषितः श्लेष्मा स्रोतो लिम्पेत्ततो भवेत् रुग् गौरवं पिधानं च स प्रतीनाहसंज्ञितः", text: "votana śoṣitaḥ śleṣmā sroto limpettato bhavet rug gauravaṃ pidhānaṃ ca sa pratīnāhasaṃjñitaḥ" },
      { type: "verse", number: "12", sanskrit: "कण्डूशोफौ कफाच्छ्रुत्रे स्थिरौ तत्संज्ञया स्मृतौ", text: "kaṇḍūśophau kaphācchrutre sthirau tatsaṃjñayā smṛtau" },
      { type: "verse", number: "13", sanskrit: "कफो विदग्धः पित्तेन सरुजं नीरुजं तथा घनपूतिबहुक्लेदं कुरुते पूतिकर्णकम्", text: "kapho vidagdhaḥ pittena sarujaṃ nīrujaṃ tathā ghanapūtibahukledaṃ kurute pūtikarṇakam" },
      { type: "verse", number: "14", sanskrit: "वातादिदूषितं श्रोत्रं मांसासृक्लेदजा रुजम् खादन्तो जन्तवः कुर्युस्तीव्रां स कृमिकर्णकः", text: "vātādidūṣitaṃ śrotraṃ māṃsāsṛkledajā rujam khādanto jantavaḥ kuryustīvrāṃ sa kṛmikarṇakaḥ" },
      { type: "verse", number: "15", sanskrit: "श्रोत्रकण्डूयनाज्जाते क्षते स्यात् पूर्वलक्षणः विद्रधिः पूर्ववच्चान्यः शोफोर्शोर्बुदमीरितम्", text: "śrotrakaṇḍūyanājjāte kṣate syāt pūrvalakṣaṇaḥ vidradhiḥ pūrvavaccānyaḥ śophorśorbudamīritam" },
      { type: "verse", number: "16", sanskrit: "तेषु रुक्पूतिकर्णत्वं बधिरत्वं क्रमेण च", text: "teṣu rukpūtikarṇatvaṃ badhiratvaṃ krameṇa ca" },
      { type: "verse", number: "17", sanskrit: "गर्भे ऽनिलात् सङ्कुचिता शष्कुली कूचिकर्णकः", text: "garbhe 'nilāt saṅkucitā śaṣkulī kūcikarṇakaḥ" },
      { type: "verse", number: "18", sanskrit: "एको नीरुगनेको वा गर्भे मांसाङ्कुरः स्थिरः पिप्पलीपिप्पलीमानः सन्निपाताद्विदारिका", text: "eko nīruganeko vā garbhe māṃsāṅkuraḥ sthiraḥ pippalīpippalīmānaḥ sannipātādvidārikā" },
      { type: "verse", number: "19", sanskrit: "सर्वणः सरुजः स्तब्धः श्वयघुः स उपेक्षितः", text: "sarvaṇaḥ sarujaḥ stabdhaḥ śvayaghuḥ sa upekṣitaḥ" },
      { type: "verse", number: "20", sanskrit: "कटुतैलनिभं पक्वः स्रवेत् कृच्छ्रेण रोहति सङ्कोचयति रूढा च सा ध्रुवं कर्णशष्कुलीम्", text: "kaṭutailanibhaṃ pakvaḥ sravet kṛcchreṇa rohati saṅkocayati rūḍhā ca sā dhruvaṃ karṇaśaṣkulīm" },
      { type: "verse", number: "21", sanskrit: "सिरास्थः कुरुते वायुः पालीशोषं तदाह्वयम्", text: "sirāsthaḥ kurute vāyuḥ pālīśoṣaṃ tadāhvayam" },
      { type: "verse", number: "22", sanskrit: "कृशा दृढा च तन्त्रीवत् पाली वातेन तन्त्रिका", text: "kṛśā dṛḍhā ca tantrīvat pālī vātena tantrikā" },
      { type: "verse", number: "23", sanskrit: "सुकुमारे चिरोत्सर्गात् सहसैव प्रवर्धिते कर्णे शोफः सरुक्पाल्यामरुणः परिपोटवान्", text: "sukumāre cirotsargāt sahasaiva pravardhite karṇe śophaḥ sarukpālyāmaruṇaḥ paripoṭavān" },
      { type: "verse", number: "24", sanskrit: "परिपोटश्चपवनात् उत्पातः पित्तशोणितात्", text: "paripoṭaścapavanāt utpātaḥ pittaśoṇitāt" },
      { type: "verse", number: "25", sanskrit: "गुर्वाभरणभाराद्यैः श्यावो रुग्दाहपाकवान् श्वयथुः स्फोटपिटकारागोषाक्लेदसंयुतः", text: "gurvābharaṇabhārādyaiḥ śyāvo rugdāhapākavān śvayathuḥ sphoṭapiṭakārāgoṣākledasaṃyutaḥ" },
      { type: "verse", number: "26", sanskrit: "पाल्यां शोफोनिलकफात् सर्वतो निर्व्यथः स्थिरः स्तब्धः सवर्णः कण्डूमानुन्मन्थो गल्लिरश्च सः", text: "pālyāṃ śophonilakaphāt sarvato nirvyathaḥ sthiraḥ stabdhaḥ savarṇaḥ kaṇḍūmānunmantho galliraśca saḥ" },
      { type: "verse", number: "27", sanskrit: "दुर्विद्धे वर्धिते कर्णे सकण्डूदाहपाकरुक् श्वयथुः सन्निपातोत्थः स नाम्रा दुःखवर्धनः", text: "durviddhe vardhite karṇe sakaṇḍūdāhapākaruk śvayathuḥ sannipātotthaḥ sa nāmrā duḥkhavardhanaḥ" },
      { type: "verse", number: "28", sanskrit: "कफासृक्कृमिजाः सूक्ष्माः सकण्डूक्लेदवेदनाः लिह्याख्याः पिटकास्ता हि लिह्युः पालीमुपेक्षिताः", text: "kaphāsṛkkṛmijāḥ sūkṣmāḥ sakaṇḍūkledavedanāḥ lihyākhyāḥ piṭakāstā hi lihyuḥ pālīmupekṣitāḥ" },
      { type: "verse", number: "29", sanskrit: "पिप्पली सर्वजं शूलं विदारी कूचिकर्णकः एषामसाध्या याप्यैका तन्त्रिकान्यांस्तु साधयेत्", text: "pippalī sarvajaṃ śūlaṃ vidārī kūcikarṇakaḥ eṣāmasādhyā yāpyaikā tantrikānyāṃstu sādhayet" },
      { type: "verse", number: "30", sanskrit: "पञ्चविंशतिरित्युक्ताः कर्णरोगा विभागतः कर्णरोगप्रतिषेधः", text: "pañcaviṃśatirityuktāḥ karṇarogā vibhāgataḥ karṇarogapratiṣedhaḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 22,
    lang: "sa",
    content: [
      { type: "heading", heading: "Хрид рога — болезни сердца" },
      { type: "text", text: "Глава 22 Уттара стханы — «Хрид рога» — посвящена специализированному разделу: болезни сердца. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः कर्णरोगमप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति हस्माहुरात्रेयादयोमहर्षयः", text: "athātaḥ karṇarogamapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti hasmāhurātreyādayomaharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "वातजे कर्णशूले रात्रौ रात्रौ रसभोजनोत्तरं वातहरद्रव्यसिद्धं सर्पिः पिबोन्निरन्नो वा पयोनुपानम्", text: "vātaje karṇaśūle rātrau rātrau rasabhojanottaraṃ vātaharadravyasiddhaṃ sarpiḥ pibonniranno vā payonupānam" },
      { type: "verse", number: "3", sanskrit: "ततो दशमूलसिद्धे छागे पयसि गोशृङ्गनिहिते ऽग्निवर्णान् पाषाणान् सन्दंशेन गृहीत्वावपेत् तेनोष्मणा नाडीस्वेदेन च स्वभ्यक्तं स्वेदयेत् बिल्वयवकोलकुलत्थमाषार्कशिग्रुपत्रैर्वा सानूपमांसैः क्वथितैः", text: "tato daśamūlasiddhe chāge payasi gośṛṅganihite 'gnivarṇān pāṣāṇān sandaṃśena gṛhītvāvapet tenoṣmaṇā nāḍīsvedena ca svabhyaktaṃ svedayet bilvayavakolakulatthamāṣārkaśigrupatrairvā sānūpamāṃsaiḥ kvathitaiḥ" },
      { type: "verse", number: "4", sanskrit: "स्विन्नं च पूरयेत् कुष्ठरास्नामधुकवंशावलेखशुण्ठीशिखिचन्द्रकमाषसरलपयोविपक्वेन तैलेन जीवकमधुककुष्ठमण्डूकीदेवदारुमहौषधकल्काष्टगुणक्षीरिसिद्धेन वा", text: "svinnaṃ ca pūrayet kuṣṭharāsnāmadhukavaṃśāvalekhaśuṇṭhīśikhicandrakamāṣasaralapayovipakvena tailena jīvakamadhukakuṣṭhamaṇḍūkīdevadārumahauṣadhakalkāṣṭaguṇakṣīrisiddhena vā" },
      { type: "verse", number: "5", sanskrit: "मयूरनालकुलत्थागरुमाषदेवदारुकल्कक्षारशुक्ताम्लसाधिताभ्यां वा तैलवसाभ्याम् मधुकक्षीरकाकोलीमाषशतावरीकल्कसर्वगन्धोदकक्षीरविपक्वया वा वराहवसया", text: "mayūranālakulatthāgarumāṣadevadārukalkakṣāraśuktāmlasādhitābhyāṃ vā tailavasābhyām madhukakṣīrakākolīmāṣaśatāvarīkalkasarvagandhodakakṣīravipakvayā vā varāhavasayā" },
      { type: "verse", number: "6", sanskrit: "रास्नामधुककाकोलीदेवदारुकल्कपयोविपाचितया वा शिंशुमारवसया मांसीकुष्ठमेदासरलसुरभिमधुकक्षीरविपक्वया वा गोधावसया", text: "rāsnāmadhukakākolīdevadārukalkapayovipācitayā vā śiṃśumāravasayā māṃsīkuṣṭhamedāsaralasurabhimadhukakṣīravipakvayā vā godhāvasayā" },
      { type: "verse", number: "7", sanskrit: "जीवकशताह्वामधुकमांसीक्षीरसिद्धां कुक्कुटमयूरवसां कर्णपूरणनस्याभ्यङ्गेषु विदध्यात् मधुकक्षीरकाकोलीकल्केन चतुर्गुणशिग्रुह्रस्वपञ्चमूलकैरण्डपत्ररसमष्टगुणक्षीरसाधितं तैलं वा", text: "jīvakaśatāhvāmadhukamāṃsīkṣīrasiddhāṃ kukkuṭamayūravasāṃ karṇapūraṇanasyābhyaṅgeṣu vidadhyāt madhukakṣīrakākolīkalkena caturguṇaśigruhrasvapañcamūlakairaṇḍapatrarasamaṣṭaguṇakṣīrasādhitaṃ tailaṃ vā" },
      { type: "verse", number: "8", sanskrit: "घृततैलवसाभ्यक्तानि तरुणान्यश्वत्थपत्राणि पुटपाक्स्विन्नानि प्रपीड्य तद्रसेन कर्णं पूरयेत्", text: "ghṛtatailavasābhyaktāni taruṇānyaśvatthapatrāṇi puṭapāksvinnāni prapīḍya tadrasena karṇaṃ pūrayet" },
      { type: "verse", number: "9", sanskrit: "तद्वच्च तैललवणाभ्यक्तान्यर्कोरुपूगमूलकारलुकबिल्वमहावृक्षान्यतमपत्राणि", text: "tadvacca tailalavaṇābhyaktānyarkorupūgamūlakāralukabilvamahāvṛkṣānyatamapatrāṇi" },
      { type: "verse", number: "10", sanskrit: "महापञ्चमूलसरलागरुदेवदार्व्यन्यतमकाष्ठमष्टादशाङ्गुलं त्रिभागे क्षौमेणावेष्ट्य तैलेन सिक्त्वाग्रे प्रदीपयेत् ततो दह्यमानाद्यः स्नेहः पतति स सद्यः कर्णरुजमपहरति", text: "mahāpañcamūlasaralāgarudevadārvyanyatamakāṣṭhamaṣṭādaśāṅgulaṃ tribhāge kṣaumeṇāveṣṭya tailena siktvāgre pradīpayet tato dahyamānādyaḥ snehaḥ patati sa sadyaḥ karṇarujamapaharati" },
      { type: "verse", number: "11", sanskrit: "मधूच्छिष्टकैडर्यमधुशिग्रुफलवचायवनलदैलागुग्गुलुभिः श्लक्ष्णपिष्टैः क्षौमवस्त्रं धूमवर्त्तिप्रमाणपरिणाहं लेपयेत्ततः सूत्रेणावेष्ट्य डुण्डुकनालेन धूमं पातुं दद्यात्", text: "madhūcchiṣṭakaiḍaryamadhuśigruphalavacāyavanaladailāguggulubhiḥ ślakṣṇapiṣṭaiḥ kṣaumavastraṃ dhūmavarttipramāṇapariṇāhaṃ lepayettataḥ sūtreṇāveṣṭya ḍuṇḍukanālena dhūmaṃ pātuṃ dadyāt" },
      { type: "verse", number: "12", sanskrit: "डुण्डुकनालमेववानेन कल्केनाभ्यज्य विशोषयित्वा धूमं विदध्यात्", text: "ḍuṇḍukanālamevavānena kalkenābhyajya viśoṣayitvā dhūmaṃ vidadhyāt" },
      { type: "verse", number: "13", sanskrit: "श्रेयसीदेवदारुकाकोलीकुष्ठनिचुलबीजैः क्षीरपिष्टैस्तिलयुतैः कर्णं बहिर्लेपयेत् सर्वधान्यस्नेहगोक्षीरसिद्धामुत्कारिकामेरण्डपत्रावच्छादिते कर्णे स्वेदार्थं प्रणयेत् पुनः पुनश्च नाडीस्वेदान् पिण्डस्वेदांश्च वातव्याधिप्रतिश्यायार्दिताविधानं च सनिरूहानुवासनं कुर्यात्", text: "śreyasīdevadārukākolīkuṣṭhaniculabījaiḥ kṣīrapiṣṭaistilayutaiḥ karṇaṃ bahirlepayet sarvadhānyasnehagokṣīrasiddhāmutkārikāmeraṇḍapatrāvacchādite karṇe svedārthaṃ praṇayet punaḥ punaśca nāḍīsvedān piṇḍasvedāṃśca vātavyādhipratiśyāyārditāvidhānaṃ ca sanirūhānuvāsanaṃ kuryāt" },
      { type: "verse", number: "14", sanskrit: "परिहार्याणि च परिहरेद्विशेषतः प्रवातं शीताम्बुपानं शिरःस्नानं च", text: "parihāryāṇi ca pariharedviśeṣataḥ pravātaṃ śītāmbupānaṃ śiraḥsnānaṃ ca" },
      { type: "verse", number: "15", sanskrit: "पित्तजे तु शूले प्रातः शर्करायुतं सर्पिः पाययेत् ततः स्निग्धं विरेचयेत् द्राक्षामधुकसिद्धं स्तन्यं कर्णपूरणं प्रयुञ्जीत माक्षिकं वा मधुकपद्मककल्कस्तन्य्सिद्धं वा सर्पिः सितामधुकखर्जूरमृद्वीकाभिर्वा सक्षीरेक्षुरसं प्रियालकतैलं पाचितमभ्यङ्गनस्यकर्णपूरणैः शूलदाहघ्नम्", text: "pittaje tu śūle prātaḥ śarkarāyutaṃ sarpiḥ pāyayet tataḥ snigdhaṃ virecayet drākṣāmadhukasiddhaṃ stanyaṃ karṇapūraṇaṃ prayuñjīta mākṣikaṃ vā madhukapadmakakalkastanysiddhaṃ vā sarpiḥ sitāmadhukakharjūramṛdvīkābhirvā sakṣīrekṣurasaṃ priyālakatailaṃ pācitamabhyaṅganasyakarṇapūraṇaiḥ śūladāhaghnam" },
      { type: "verse", number: "16", sanskrit: "मधुककुडवं षोडशगुणेनाम्भसाष्टावशेषं साधयित्वा तेन तैलार्द्धकुडवमष्टगुणक्षीरं यष्टीसधुकोशीरसारिवाकाकोलीजीवकानन्तामृणालमञ्जिष्ठालोध्रचन्दनबिसगर्भं पचेत् तच्च पूर्ववत् प्रणयेत्", text: "madhukakuḍavaṃ ṣoḍaśaguṇenāmbhasāṣṭāvaśeṣaṃ sādhayitvā tena tailārddhakuḍavamaṣṭaguṇakṣīraṃ yaṣṭīsadhukośīrasārivākākolījīvakānantāmṛṇālamañjiṣṭhālodhracandanabisagarbhaṃ pacet tacca pūrvavat praṇayet" },
      { type: "verse", number: "17", sanskrit: "एषामेव च कल्केन सघृतेन कर्ण परितो लेपयेत् स्वेदयेच्च तथा क्षीरसर्पिर्नस्यं शिरोभ्यङ्गश्च एवमप्यनुपशमे तु पुनर्विरेकः", text: "eṣāmeva ca kalkena saghṛtena karṇa parito lepayet svedayecca tathā kṣīrasarpirnasyaṃ śirobhyaṅgaśca evamapyanupaśame tu punarvirekaḥ" },
      { type: "verse", number: "18", sanskrit: "कफजे पिप्पलीविपक्वं घृतमथवा सक्षौद्रं पाययित्वा तं वामयेत् ततस्तीक्ष्णं धूमं पाययेत्", text: "kaphaje pippalīvipakvaṃ ghṛtamathavā sakṣaudraṃ pāyayitvā taṃ vāmayet tatastīkṣṇaṃ dhūmaṃ pāyayet" },
      { type: "verse", number: "19", sanskrit: "कर्णं चास्य पूरयेत् सरलदेवदारुहिंस्रापटोलपत्रसुरससिद्धेन तैलेन देवदारुपिप्पलीमालतीपत्रक्वाथहरिद्राकुष्ठत्रिफलैलाक्वाथकल्कसिद्धेन वा रसाञ्जनमार्कववैजयन्तीशिग्रुलशुनार्द्रकमूलकदलीनां वा पृथक् समस्तानां वा रसेन मधुना वा रक्षोघ्नतैलेन वा तथा शूलशोफगौरवाणि प्रशाम्यन्ति", text: "karṇaṃ cāsya pūrayet saraladevadāruhiṃsrāpaṭolapatrasurasasiddhena tailena devadārupippalīmālatīpatrakvāthaharidrākuṣṭhatriphalailākvāthakalkasiddhena vā rasāñjanamārkavavaijayantīśigrulaśunārdrakamūlakadalīnāṃ vā pṛthak samastānāṃ vā rasena madhunā vā rakṣoghnatailena vā tathā śūlaśophagauravāṇi praśāmyanti" },
      { type: "verse", number: "20", sanskrit: "धान्याम्लक्वथितदशमूलबाष्पेण नाडीस्वेदमाचरेत् स्विन्नं कुशाम्रत्रिवृन्नलदशुण्ठीमुस्तसाधितेन तैलेन पूरयेत् कफघ्नांश्च गण्डूषान् धारयेत्", text: "dhānyāmlakvathitadaśamūlabāṣpeṇa nāḍīsvedamācaret svinnaṃ kuśāmratrivṛnnaladaśuṇṭhīmustasādhitena tailena pūrayet kaphaghnāṃśca gaṇḍūṣān dhārayet" },
      { type: "verse", number: "21", sanskrit: "रक्तजे पैत्तिकवत् सिद्धिः सिराव्यधश्च", text: "raktaje paittikavat siddhiḥ sirāvyadhaśca" },
      { type: "verse", number: "22", sanskrit: "पक्वेषु कर्णशूलेषु पूयप्रवाहिषु यथास्वं धूमनस्यगण्डूषवमनान्याचरेत्", text: "pakveṣu karṇaśūleṣu pūyapravāhiṣu yathāsvaṃ dhūmanasyagaṇḍūṣavamanānyācaret" },
      { type: "verse", number: "23", sanskrit: "उपदिग्धं च स्रोतः सायंप्रातः पिचुवर्तिभिः प्रमृज्य यवागरुमदनैः सघृतैर्गुग्गुलुना वा धूपयित्वा मधुना पूरयेत्", text: "upadigdhaṃ ca srotaḥ sāyaṃprātaḥ picuvartibhiḥ pramṛjya yavāgarumadanaiḥ saghṛtairguggulunā vā dhūpayitvā madhunā pūrayet" },
      { type: "verse", number: "24", sanskrit: "पलाशधवतिनिशककुभसर्जत्वक्क्वाथ रसक्रियया स्वभ्यक्तां पिचुवर्तिं स्रोतसि दद्यात् बदरीसल्लकीजम्बूधातकीवटप्लक्षोदुम्बरक्वाथेनैवमेव च रसक्रियया हरिद्राधातकीत्रिफलाजम्बूसल्लकीकिंशुकक्वाथेन च तथा सौराष्ट्रिकापद्मकधातकीसमङ्गाश्वत्थधवलोध्ररसाञ्जनक्वाथेन", text: "palāśadhavatiniśakakubhasarjatvakkvātha rasakriyayā svabhyaktāṃ picuvartiṃ srotasi dadyāt badarīsallakījambūdhātakīvaṭaplakṣodumbarakvāthenaivameva ca rasakriyayā haridrādhātakītriphalājambūsallakīkiṃśukakvāthena ca tathā saurāṣṭrikāpadmakadhātakīsamaṅgāśvatthadhavalodhrarasāñjanakvāthena" },
      { type: "verse", number: "25", sanskrit: "एभिरेवौषधैः सूक्ष्मचूर्णीकृतैः स्रोतसो ऽवकिरणमेवं क्लेदशूलगौरवाणि शाम्यन्ति एषामेव च कषायेण सक्षौद्रेण कपित्थस्वरसेन वा प्रक्षालनम् तथा सुरसादिवर्गः प्रक्षालनावचूर्णनयोः प्रयोज्यः", text: "ebhirevauṣadhaiḥ sūkṣmacūrṇīkṛtaiḥ srotaso 'vakiraṇamevaṃ kledaśūlagauravāṇi śāmyanti eṣāmeva ca kaṣāyeṇa sakṣaudreṇa kapitthasvarasena vā prakṣālanam tathā surasādivargaḥ prakṣālanāvacūrṇanayoḥ prayojyaḥ" },
      { type: "verse", number: "26", sanskrit: "नादबाधिर्ययोर्वातशूलोक्तः सर्वो विधिः श्लेष्मानुबन्धे तु प्राक्श्लेष्माणमपहरेद्वमननावनाभ्यां तीक्ष्णधूमैश्च", text: "nādabādhiryayorvātaśūloktaḥ sarvo vidhiḥ śleṣmānubandhe tu prākśleṣmāṇamapaharedvamananāvanābhyāṃ tīkṣṇadhūmaiśca" },
      { type: "verse", number: "27", sanskrit: "बाधिर्यं च बालवृद्धक्षीणकासशोषिणां चिरोत्थितं च वर्जयेत्", text: "bādhiryaṃ ca bālavṛddhakṣīṇakāsaśoṣiṇāṃ cirotthitaṃ ca varjayet" },
      { type: "verse", number: "28", sanskrit: "इतरत्तु स्नेहस्वेदनस्यशिरोबस्तिबस्तिकर्मप्रभृतिभिर्दोषानुबन्धमवेक्ष्य साधयेत्", text: "itarattu snehasvedanasyaśirobastibastikarmaprabhṛtibhirdoṣānubandhamavekṣya sādhayet" },
      { type: "verse", number: "29", sanskrit: "तत्र प्रागेव पुराणसर्पिषा वा वातहरतैलेन वा स्निग्धं स्नेहेनैव विरेचयेत् कृतसंसर्जनस्य पुनः स्निग्धस्य शोणितमपहरेत् कर्णासन्नं जलौकोभिस्ततो बस्तिकर्ममूर्धतैलनस्यधूमान् कर्णपूरणं च शीलयेत्", text: "tatra prāgeva purāṇasarpiṣā vā vātaharatailena vā snigdhaṃ snehenaiva virecayet kṛtasaṃsarjanasya punaḥ snigdhasya śoṇitamapaharet karṇāsannaṃ jalaukobhistato bastikarmamūrdhatailanasyadhūmān karṇapūraṇaṃ ca śīlayet" },
      { type: "verse", number: "30", sanskrit: "तरुणबिल्वफलानि गोमूत्रेण क्वाथयेत्तेन क्वाथेन सितामधुकबीजकबीजकल्केन च पयोयुक्तं तैलं पाचयेत् तत्तैलमुष्णं शीते बिल्वक्वाथे प्रक्षिप्य मन्थयेत् यावत् पिण्डीभूतमुद्धृत्य चैतत्पुनरन्यत्र बिल्वोदके मन्थयेत् ततश्चोद्धृत्याष्टगुणे पयसि मधुकगन्धचन्दनगर्भं साधितमाशु कर्णपूरणात् बाधिर्यं नाशयति", text: "taruṇabilvaphalāni gomūtreṇa kvāthayettena kvāthena sitāmadhukabījakabījakalkena ca payoyuktaṃ tailaṃ pācayet tattailamuṣṇaṃ śīte bilvakvāthe prakṣipya manthayet yāvat piṇḍībhūtamuddhṛtya caitatpunaranyatra bilvodake manthayet tataścoddhṛtyāṣṭaguṇe payasi madhukagandhacandanagarbhaṃ sādhitamāśu karṇapūraṇāt bādhiryaṃ nāśayati" },
      { type: "verse", number: "31", sanskrit: "तिलान् नवप्रलूनान् वस्त्रबद्धान् वहन्तीष्वप्सु रात्रिमुषितान् दिवा शोषयेत् पञ्चरात्रम् एवं गते पञ्चरात्रे मधुयष्टिकाक्षीरकाकोलीमहापञ्चमूलदेवदारुशताह्वाजीवकक्वथिते पयसि पञ्चाहमेवं वासयेच्छोषयेच्च ततोनेनैव क्षीरेणैषामेव च द्रव्याणां चूर्णमात्रया युक्तान् प्रपीडयेत् तत्तैलं नीलोत्पलानन्ताचन्दनागरुमधुकजीवककाकोलीसुनिषण्णकमूलकल्कैरष्टगुणेन पयसा पचेत् एतन्नस्ये कर्णपूरणे शिरसि चाभ्यञ्जने प्रणीतमाशु शूलनादबाधिर्याणि सर्ववातविकारांश्च पित्तानुबन्धानपोहति भग्नास्थिसन्धानजननं च", text: "tilān navapralūnān vastrabaddhān vahantīṣvapsu rātrimuṣitān divā śoṣayet pañcarātram evaṃ gate pañcarātre madhuyaṣṭikākṣīrakākolīmahāpañcamūladevadāruśatāhvājīvakakvathite payasi pañcāhamevaṃ vāsayecchoṣayecca tatonenaiva kṣīreṇaiṣāmeva ca dravyāṇāṃ cūrṇamātrayā yuktān prapīḍayet tattailaṃ nīlotpalānantācandanāgarumadhukajīvakakākolīsuniṣaṇṇakamūlakalkairaṣṭaguṇena payasā pacet etannasye karṇapūraṇe śirasi cābhyañjane praṇītamāśu śūlanādabādhiryāṇi sarvavātavikārāṃśca pittānubandhānapohati bhagnāsthisandhānajananaṃ ca" },
      { type: "verse", number: "32", sanskrit: "शुष्कमूलकभस्मक्षारद्वयहिङ्गुशुण्ठीमिसिवचाकुष्ठमरदारुसौभाञ्जनभूर्जग्रन्थिमुस्तालवणत्रयैः सोद्भिदैस्तैलं शुक्तकदलीबीजपूरकरससंयुक्तं सिद्धं शूलनादबाधिर्यकण्डूशोफक्लेदोपदेहकृमिपूतिकर्णेषु", text: "śuṣkamūlakabhasmakṣāradvayahiṅguśuṇṭhīmisivacākuṣṭhamaradārusaubhāñjanabhūrjagranthimustālavaṇatrayaiḥ sodbhidaistailaṃ śuktakadalībījapūrakarasasaṃyuktaṃ siddhaṃ śūlanādabādhiryakaṇḍūśophakledopadehakṛmipūtikarṇeṣu" },
      { type: "verse", number: "33", sanskrit: "अथ कर्णौ सुप्ताविव भवतस्तत्समीपे यथोक्तां सिरां मोक्षयेत् सश्वयथुपरिस्रावे मन्दश्रुतेर्वमनमाचरेत्", text: "atha karṇau suptāviva bhavatastatsamīpe yathoktāṃ sirāṃ mokṣayet saśvayathuparisrāve mandaśrutervamanamācaret" },
      { type: "verse", number: "34", sanskrit: "प्रतीनाहे स्नेहस्वेदक्लिन्नं कर्णं कर्णशोधनेन विशोध्य तैलस्य पूरयेन्मातुलुङ्गरसस्य वा सशुक्तक्षौद्रसैन्धवस्य", text: "pratīnāhe snehasvedaklinnaṃ karṇaṃ karṇaśodhanena viśodhya tailasya pūrayenmātuluṅgarasasya vā saśuktakṣaudrasaindhavasya" },
      { type: "verse", number: "35", sanskrit: "शोध्यमाने वेदना रक्तागमो वा यदि भवेत्ततो घृतमण्डेन पूरयेन्नस्यं च शीलयेत् मलपूर्णेप्येष एव विधिः", text: "śodhyamāne vedanā raktāgamo vā yadi bhavettato ghṛtamaṇḍena pūrayennasyaṃ ca śīlayet malapūrṇepyeṣa eva vidhiḥ" },
      { type: "verse", number: "36", sanskrit: "कण्ड्वां तीक्ष्णनस्यधूमादीन् कफघ्नान्वितरेत् रूक्षतिक्तकटुश्चाहारः शोफेप्येवमेव विधिः कटुतीक्ष्णोष्णाश्च प्रदेहपरिषेकाः", text: "kaṇḍvāṃ tīkṣṇanasyadhūmādīn kaphaghnānvitaret rūkṣatiktakaṭuścāhāraḥ śophepyevameva vidhiḥ kaṭutīkṣṇoṣṇāśca pradehapariṣekāḥ" },
      { type: "verse", number: "37", sanskrit: "पूतिकर्णे कर्णस्रावोक्तो विधिः कृमिकर्णे च विशेषतश्चात्र कृमिघ्नः तथा सर्षपतैलेन पूरणम् हरितालचूर्णवता गोमूत्रेण वा वार्ताकबीजेन धूपनम्", text: "pūtikarṇe karṇasrāvokto vidhiḥ kṛmikarṇe ca viśeṣataścātra kṛmighnaḥ tathā sarṣapatailena pūraṇam haritālacūrṇavatā gomūtreṇa vā vārtākabījena dhūpanam" },
      { type: "verse", number: "38", sanskrit: "कर्णविद्रधिं वमनपूर्वं विद्रधिवदामं पक्वं च चिकित्सेत् क्षतविद्रधिं पित्तकर्णशूलवदर्शांसि नासार्शोवदर्बुदानि च", text: "karṇavidradhiṃ vamanapūrvaṃ vidradhivadāmaṃ pakvaṃ ca cikitset kṣatavidradhiṃ pittakarṇaśūlavadarśāṃsi nāsārśovadarbudāni ca" },
      { type: "verse", number: "39", sanskrit: "विदारिकामामां कर्णविद्रधिवद्यथादोषोदयं च साधयेत्", text: "vidārikāmāmāṃ karṇavidradhivadyathādoṣodayaṃ ca sādhayet" },
      { type: "verse", number: "40", sanskrit: "पालीशोषे वातशूलवन्नस्यमालेपं स्वेदंच कुर्यात् स्विन्नमुद्वर्त्तयेत्तिलप्रियालबीजमधुकयवाश्वगन्ध्हाकल्केन", text: "pālīśoṣe vātaśūlavannasyamālepaṃ svedaṃca kuryāt svinnamudvarttayettilapriyālabījamadhukayavāśvagandhhākalkena" },
      { type: "verse", number: "41", sanskrit: "उद्वर्तितं च मधुकपयस्याशतपुष्पाश्वगन्धाकल्काष्टगुणवाजिगन्धाबृहत्यभीरुक्वाथक्षीरसाधितेन तैलेनाभ्यज्यात् शतावर्यश्वगन्धैरण्डपयस्याजीवकक्षीरसिद्धेन वा", text: "udvartitaṃ ca madhukapayasyāśatapuṣpāśvagandhākalkāṣṭaguṇavājigandhābṛhatyabhīrukvāthakṣīrasādhitena tailenābhyajyāt śatāvaryaśvagandhairaṇḍApayasyājīvakakṣīrasiddhena vā" },
      { type: "verse", number: "42", sanskrit: "गोधाप्रतुदविष्किरानूपौदकमांसवसामज्जानं सर्पिस्सर्षपतैलं च यथालाभं सङ्गृह्यार्कालर्कबलातिबलानन्ताविदारिगन्धाजलशूकमधुरवर्गप्रतीवापं विपचेदयमभ्यङ्गः पाल्याः परं मांसजननः", text: "godhāpratudaviṣkirānūpaudakamāṃsavasāmajjānaṃ sarpissarṣapatailaṃ ca yathālābhaṃ saṅgṛhyārkālarkabalātibalānantāvidārigandhājalaśūkamadhuravargapratīvāpaṃ vipacedayamabhyaṅgaḥ pālyāḥ paraṃ māṃsajananaḥ" },
      { type: "verse", number: "43", sanskrit: "एवमपि तु या क्षीयते पाली तस्या यद्दुष्टं तच्छित्वा विधिवत् सन्धाय यथोक्तेन क्रमेणोपचरेत्", text: "evamapi tu yā kṣīyate pālī tasyā yadduṣṭaṃ tacchitvā vidhivat sandhāya yathoktena krameṇopacaret" },
      { type: "verse", number: "44", sanskrit: "तन्त्रिकामपि चैवमेव नस्याभ्यङ्गादिभिर्यापयेत्", text: "tantrikāmapi caivameva nasyābhyaṅgādibhiryāpayet" },
      { type: "verse", number: "45", sanskrit: "परिपोटकेप्ययमेव विधिः तथा मधुकखरमञ्जरीसैन्धवाश्वगन्धादेवदारुमूलकावल्गुजफलमूलमधूच्छिष्टैः सक्षीरैर्महास्नेहः सिद्धोभ्यङ्गः तिलमधुकप्रपौण्डरीकसिद्धार्थकघृतक्षीरकृतयोत्कारिकयोपनाहः", text: "paripoṭakepyayameva vidhiḥ tathā madhukakharamañjarīsaindhavāśvagandhādevadārumūlakāvalgujaphalamūlamadhūcchiṣṭaiḥ sakṣīrairmahāsnehaḥ siddhobhyaṅgaḥ tilamadhukaprapauṇḍarīkasiddhārthakaghṛtakṣīrakṛtayotkārikayopanāhaḥ" },
      { type: "verse", number: "46", sanskrit: "उत्पाते जलौकोभिरपनीतरक्ते शीतैः प्रदेहः तिलमधुकसारिवोत्पललोध्रकदम्बबलाम्रजम्बूपल्लवैस्सधान्याम्लं तैलं साधितमभ्यङ्गः तथा क्षीरसर्पिर्विसर्पोक्तानि च घृतानि", text: "utpāte jalaukobhirapanītarakte śītaiḥ pradehaḥ tilamadhukasārivotpalalodhrakadambabalāmrajambūpallavaissadhānyāmlaṃ tailaṃ sādhitamabhyaṅgaḥ tathā kṣīrasarpirvisarpoktāni ca ghṛtāni" },
      { type: "verse", number: "47", sanskrit: "उन्मन्थे तीक्ष्णैः शिरोविरेकः तिलसर्षपलोध्रहरिद्राद्वयैरुद्वर्तितायाः कर्णपाल्यास्तालीसतमालैलाकट्फलरसाञ्जनैर्लेपः तालपत्र्यश्वगन्धार्कसैन्धवावल्गुजबीजसुरसलाङ्गलिकाभिर्गोधाकुलीरवसायुक्तं तैलं विपक्वमभ्यञ्जनम् तैलमेव वा पटोलकटुरोहिणीरसाञ्जनीशरीषैः", text: "unmanthe tīkṣṇaiḥ śirovirekaḥ tilasarṣapalodhraharidrādvayairudvartitāyāḥ karṇapālyāstālīsatamālailākaṭphalarasāñjanairlepaḥ tālapatryaśvagandhārkasaindhavāvalgujabījasurasalāṅgalikābhirgodhākulīravasāyuktaṃ tailaṃ vipakvamabhyañjanam tailameva vā paṭolakaṭurohiṇīrasāñjanīśarīṣaiḥ" },
      { type: "verse", number: "48", sanskrit: "दुःखवर्द्धने जम्ब्वाम्राश्मन्तकपत्रक्वाथपरिषिक्तां कर्णपालीं तैलेनाभ्यज्य यष्टीमधुकहरिद्राप्रपौण्डरीकमञ्जिष्ठाचूर्णेनावचूर्णयेत् लाक्षाविडङ्गपक्वेन तैलेनाभ्यञ्जयेत्", text: "duḥkhavarddhane jambvāmrāśmantakapatrakvāthapariṣiktāṃ karṇapālīṃ tailenābhyajya yaṣṭīmadhukaharidrāprapauṇḍarīkamañjiṣṭhācūrṇenāvacūrṇayet lākṣāviḍaṅgapakvena tailenābhyañjayet" },
      { type: "verse", number: "49", sanskrit: "लेहिकापिटकासु कर्णपालीं बहुशो गामयापण्डस्विन्नामुरभ्रीमूत्रपिष्टैः कृमिघ्नैरालिम्पेत् कुटजकरञ्जेङ्गुदबीजारग्वधत्वग्भिर्वा एभिरेव च सर्वैस्समरिचनिम्बपत्रमधूच्छिष्टैस्सर्षपतैलं सिद्धं लेहिकाव्रणघ्नो ऽभ्यङ्गः परिदहने जलजाभिरसृक् स्रावयेत् शीतैश्च प्रदिह्यात्", text: "lehikāpiṭakāsu karṇapālīṃ bahuśo gāmayāpaṇḍasvinnāmurabhrīmūtrapiṣṭaiḥ kṛmighnairālimpet kuṭajakarañjeṅgudabījāragvadhatvagbhirvā ebhireva ca sarvaissamaricanimbapatramadhūcchiṣṭaissarṣapatailaṃ siddhaṃ lehikāvraṇaghno 'bhyaṅgaḥ paridahane jalajābhirasṛk srāvayet śītaiśca pradihyāt" },
      { type: "verse", number: "50", sanskrit: "सर्वेषु च पालीरोगेषु स्नेहस्वेदशोधनाभ्यङ्गप्रदेहनस्यास्रविस्रवणानि यथार्हं प्रयुञ्जीत प्रकोपकारणानि च परिहरेत्", text: "sarveṣu ca pālīrogeṣu snehasvedaśodhanābhyaṅgapradehanasyāsravisravaṇāni yathārhaṃ prayuñjīta prakopakāraṇāni ca pariharet" },
      { type: "verse", number: "51", sanskrit: "उत्पच्यमानायां तु पाल्यां सर्जरसापामार्गपटोलनिम्बनिचुलत्वग्भिरालेपः उत्पुटन्त्यां शिग्रुशम्याकपूतीकगोवराहपित्तगोधावसासपिर्भिः श्यावायां गौरीसुगन्धाश्यामानन्तातण्डुलीयकमूलैः कण्डूमत्यां पाठानन्तातार्क्ष्यशैलेयमाक्षिकैः दह्यमानायां क्षीरिवृक्षजीवनीयकल्कमधुघृतैः व्रणितायां क्षौद्रजीवनीयैः कृशायां गोधावराहवसाभिः ग्रथितायां ग्रन्थिं पाटयित्वा विलिख्य च कृष्णासैन्धवमधुभिः प्रतिसारयेत् स्नाववत्यां मधुमधुकमधूकमधुपर्णीभिर्लेपः एभिरेव च यथास्वं स्नेहानभ्यङ्गार्थं प्रकल्पयेत्", text: "utpacyamānāyāṃ tu pālyāṃ sarjarasāpāmārgapaṭolanimbaniculatvagbhirālepaḥ utpuṭantyāṃ śigruśamyākapūtīkagovarāhapittagodhāvasāsapirbhiḥ śyāvāyāṃ gaurīsugandhāśyāmānantātaṇḍulīyakamūlaiḥ kaṇḍūmatyāṃ pāṭhānantātārkṣyaśaileyamākṣikaiḥ dahyamānāyāṃ kṣīrivṛkṣajīvanīyakalkamadhughṛtaiḥ vraṇitāyāṃ kṣaudrajīvanīyaiḥ kṛśāyāṃ godhāvarāhavasābhiḥ grathitāyāṃ granthiṃ pāṭayitvā vilikhya ca kṛṣṇāsaindhavamadhubhiḥ pratisārayet snāvavatyāṃ madhumadhukamadhūkamadhuparṇībhirlepaḥ ebhireva ca yathāsvaṃ snehānabhyaṅgārthaṃ prakalpayet" },
      { type: "verse", number: "52", sanskrit: "अथ रोगतो बलाद्वा विच्छिन्नं कर्णमनुसन्दध्यात्", text: "atha rogato balādvā vicchinnaṃ karṇamanusandadhyāt" },
      { type: "verse", number: "53", sanskrit: "समासतस्तु पञ्चदश कर्णसन्धयः प्रायो नामानुगतसंस्थानस्थानविशेषतया सम्भवन्ति", text: "samāsatastu pañcadaśa karṇasandhayaḥ prāyo nāmānugatasaṃsthānasthānaviśeṣatayā sambhavanti" },
      { type: "verse", number: "54", sanskrit: "तद्यथा पृथुलायतसमोभयपालीश्चक्रनेभिः", text: "tadyathā pṛthulāyatasamobhayapālīścakranebhiḥ" },
      { type: "verse", number: "55", sanskrit: "वृत्तायतसमोभयपालिरुत्पलभेदकः", text: "vṛttāyatasamobhayapālirutpalabhedakaḥ" },
      { type: "verse", number: "56", sanskrit: "अभ्यन्तरदीर्घपालिः कवाटः", text: "abhyantaradīrghapāliḥ kavāṭaḥ" },
      { type: "verse", number: "57", sanskrit: "विपरीतोर्द्धकवाटः", text: "viparītorddhakavāṭaḥ" },
      { type: "verse", number: "58", sanskrit: "ह्रस्ववृत्तसमोभयपालिर्वल्लूरकः", text: "hrasvavṛttasamobhayapālirvallūrakaḥ" },
      { type: "verse", number: "59", sanskrit: "अणुस्थूलसमविषमपालिर्व्यायोजिमः", text: "aṇusthūlasamaviṣamapālirvyāyojimaḥ" },
      { type: "verse", number: "60", sanskrit: "बाह्यपालिर्गण्डाधारः", text: "bāhyapālirgaṇḍādhāraḥ" },
      { type: "verse", number: "61", sanskrit: "अतोविपरीतस्त्वासङ्गिमः", text: "atoviparītastvāsaṅgimaḥ" },
      { type: "verse", number: "62", sanskrit: "अपालिराहार्यः स एव मांसलपीठो निर्वेधिमः", text: "apālirāhāryaḥ sa eva māṃsalapīṭho nirvedhimaḥ" },
      { type: "verse", number: "63", sanskrit: "शुष्कशष्कुलिरुत्सन्नपालिः", text: "śuṣkaśaṣkulirutsannapāliḥ" },
      { type: "verse", number: "64", sanskrit: "इतराल्पपालिः सङ्क्षिप्तः", text: "itarālpapāliḥ saṅkṣiptaḥ" },
      { type: "verse", number: "65", sanskrit: "अनधिष्ठानपालिः पर्यन्तयोश्च क्षीणमांसो हीनः", text: "anadhiṣṭhānapāliḥ paryantayośca kṣīṇamāṃso hīnaḥ" },
      { type: "verse", number: "66", sanskrit: "तनुविषमपालवाल्लः", text: "tanuviṣamapālavāllaḥ" },
      { type: "verse", number: "67", sanskrit: "ग्रथितनिर्मांसस्तब्धसिरावृतसूक्ष्मपालिर्यष्टी", text: "grathitanirmāṃsastabdhasirāvṛtasūkṣmapāliryaṣṭī" },
      { type: "verse", number: "68", sanskrit: "निर्मांससङ्क्षिप्ताग्राशोणितपालिः काकौष्ठ इति", text: "nirmāṃsasaṅkṣiptāgrāśoṇitapāliḥ kākauṣṭha iti" },
      { type: "verse", number: "69", sanskrit: "एषामाद्या दश सिध्यन्ति न त्वितरे", text: "eṣāmādyā daśa sidhyanti na tvitare" },
      { type: "verse", number: "70", sanskrit: "तत्र बाह्यायां पाल्यां दीर्घायामाभ्यन्तरः सन्धिः तथेतरायां बाह्यः समः समयोश्च", text: "tatra bāhyāyāṃ pālyāṃ dīrghāyāmābhyantaraḥ sandhiḥ tathetarāyāṃ bāhyaḥ samaḥ samayośca" },
      { type: "verse", number: "71", sanskrit: "अण्वादिविषमयोस्तु परस्परविपर्ययौ", text: "aṇvādiviṣamayostu parasparaviparyayau" },
      { type: "verse", number: "72", sanskrit: "या त्वेकैव पाली स्थूला पृथ्वी स्थिरा च स्यात् तां द्विधा पाटयित्वोपरि छित्वा सन्दध्यात्", text: "yā tvekaiva pālī sthūlā pṛthvī sthirā ca syāt tāṃ dvidhā pāṭayitvopari chitvā sandadhyāt" },
      { type: "verse", number: "73", sanskrit: "गण्डोत्कृत्तेन वा सशोणितेन सानुबन्धेन मांसेन पालीं कल्पयेत् यस्य पालीद्वयमपि नास्ति तस्याप्येष एव विधिः अथवा समानवयोदोषादेः सञ्चार्य कर्णपीठं समं मध्य निवेश्य वर्द्धयेत्", text: "gaṇḍotkṛttena vā saśoṇitena sānubandhena māṃsena pālīṃ kalpayet yasya pālīdvayamapi nāsti tasyāpyeṣa eva vidhiḥ athavā samānavayodoṣādeḥ sañcārya karṇapīṭhaṃ samaṃ madhya niveśya varddhayet" },
      { type: "verse", number: "74", sanskrit: "सन्धानविधिः पुनरातुरे ग्रथितकेशान्ते बन्धनमुपघारिते छेद्यभेद्यलेख्यैरुपपन्नैरुपपाद्य कर्णं शोणितमवेक्षेत दुष्टमदुष्टं वेति", text: "sandhānavidhiḥ punarāture grathitakeśānte bandhanamupaghārite chedyabhedyalekhyairupapannairupapādya karṇaṃ śoṇitamavekṣeta duṣṭamaduṣṭaṃ veti" },
      { type: "verse", number: "75", sanskrit: "ततो वातदुष्टे धान्याम्लोष्णोदकाभ्यां पित्तदुष्टे क्षीरशीतोदकाभ्यां श्लेष्मदुष्टे वारुणीसलिलाभ्यां प्रक्षाल्य पुनश्चावलिख्यानुन्नतमहीनविषमं सन्धिं निवेश्य ततो मधुघृताभ्यामभ्यज्य पिचुप्लोतयोरन्यतरेणावगुण्ठ्य सूत्रेण नातिगाढमशिथिलं च बध्वा सिराव्यथोक्तेन कपालस्य वा चूर्णेनावकीर्याचारिकमुपदिशेत्", text: "tato vātaduṣṭe dhānyāmloṣṇodakābhyāṃ pittaduṣṭe kṣīraśītodakābhyāṃ śleṣmaduṣṭe vāruṇīsalilābhyāṃ prakṣālya punaścāvalikhyānunnatamahīnaviṣamaṃ sandhiṃ niveśya tato madhughṛtābhyāmabhyajya picuplotayoranyatareṇāvaguṇṭhya sūtreṇa nātigāḍhamaśithilaṃ ca badhvā sirāvyathoktena kapālasya vā cūrṇenāvakīryācārikamupadiśet" },
      { type: "verse", number: "76", sanskrit: "सन्धिमश्लिष्यन्तं क्षौमसूत्रेण सीव्येत् अतिक्षीणपालिकं वा शोणिताक्तेन पिचुना वेष्टयेत् व्रणवच्चैनमुपाचरेत् त्र्यहाच्चतुरहाद्वा सलिलेन परिषिच्य पिचुं सूत्रं चापनयेत् न चाशुद्धरक्तमतिप्रवृत्तरक्तं क्षीणरक्तं वा कर्णं सन्दध्यात्", text: "sandhimaśliṣyantaṃ kṣaumasūtreṇa sīvyet atikṣīṇapālikaṃ vā śoṇitāktena picunā veṣṭayet vraṇavaccainamupācaret tryahāccaturahādvā salilena pariṣicya picuṃ sūtraṃ cāpanayet na cāśuddharaktamatipravṛttaraktaṃ kṣīṇaraktaṃ vā karṇaṃ sandadhyāt" },
      { type: "verse", number: "77", sanskrit: "तस्य हि स्वयमपि सन्धिर्विश्लिष्यते आध्मायते श्यावतामुपैति पच्यते शुष्यति चिराद्रोहति रूढोप्याभरणं न क्षमते सशोफकण्डूसन्तापो ग्रन्थिमांश्च भवति तत्र च यथास्वं प्रतिकुर्वीत दुष्टरक्ते च रक्तमवसेचयेत् क्षीणरक्तं स्नेहपाननस्यमांसरसाशनाभ्यङ्गैर्बृंहयेत्", text: "tasya hi svayamapi sandhirviśliṣyate ādhmāyate śyāvatāmupaiti pacyate śuṣyati cirādrohati rūḍhopyābharaṇaṃ na kṣamate saśophakaṇḍūsantāpo granthimāṃśca bhavati tatra ca yathāsvaṃ pratikurvīta duṣṭarakte ca raktamavasecayet kṣīṇaraktaṃ snehapānanasyamāṃsarasāśanābhyaṅgairbṛṃhayet" },
      { type: "verse", number: "78", sanskrit: "सर्वत्र चैवमपि सोपद्रवसन्धौ सन्धिं विमुच्य पूर्वापचारोपस्थापितस्मृतिः सम्यक्सन्दधीतेति भवति चात्र", text: "sarvatra caivamapi sopadravasandhau sandhiṃ vimucya pūrvāpacāropasthāpitasmṛtiḥ samyaksandadhīteti bhavati cātra" },
      { type: "verse", number: "79", sanskrit: "न कर्णे शोफरागादियुक्ते सन्धानमाचरेत् न घस्मरस्य नात्युष्णे नाविशुद्धतनोरपि", text: "na karṇe śopharāgādiyukte sandhānamācaret na ghasmarasya nātyuṣṇe nāviśuddhatanorapi" },
      { type: "verse", number: "80", sanskrit: "सुरूढं जातरोमाणं श्लिष्टसन्धिं समं स्थिरम् सुवर्ष्माणमरोगं च शनैः कर्णं विवर्द्धयेत्", text: "surūḍhaṃ jātaromāṇaṃ śliṣṭasandhiṃ samaṃ sthiram suvarṣmāṇamarogaṃ ca śanaiḥ karṇaṃ vivarddhayet" },
      { type: "verse", number: "81", sanskrit: "अन्यथा दाहरुक्तोदशोफाः स्युस्तत्र कारयेत् शीतान्प्रदेहसेकादीन् शुद्धिं च क्लेदनाशिनीम्", text: "anyathā dāharuktodaśophāḥ syustatra kārayet śītānpradehasekādīn śuddhiṃ ca kledanāśinīm" },
      { type: "verse", number: "82", sanskrit: "स्नेहावानूपजौ तैलं सर्पिर्लाक्षारसं समम् साधयेन्मधुरस्कन्धहयगन्धामयूरकैः", text: "snehāvānūpajau tailaṃ sarpirlākṣārasaṃ samam sādhayenmadhuraskandhahayagandhāmayūrakaiḥ" },
      { type: "verse", number: "83", sanskrit: "पिष्टैर्दशगुणक्षीरे तत्परं कर्णवर्द्धनम् कठिनाः सरुजः क्षामाः पाल्यः स्वेदितमर्द्दिताः अभ्यक्तास्तेन जायन्ते मृदवो नीरुजः स्थिराः", text: "piṣṭairdaśaguṇakṣīre tatparaṃ karṇavarddhanam kaṭhināḥ sarujaḥ kṣāmāḥ pālyaḥ sveditamardditāḥ abhyaktāstena jāyante mṛdavo nīrujaḥ sthirāḥ" },
      { type: "verse", number: "84", sanskrit: "बृहत्यौ कच्छुरां वारिशूकमर्कजटां घृतम् माक्षिकं शङ्खिनीं तैलं सप्ताहं ताम्रभाजने थापयेत् तत्परं कर्णमालेपात् पोषयेत् कृशम्", text: "bṛhatyau kacchurāṃ vāriśūkamarkajaṭāṃ ghṛtam mākṣikaṃ śaṅkhinīṃ tailaṃ saptāhaṃ tāmrabhājane thāpayet tatparaṃ karṇamālepāt poṣayet kṛśam" },
      { type: "verse", number: "85", sanskrit: "चर्मचटिका जलौको हयबन्धा शबरकन्दकं तुल्यम् माहिषनवनीतयुतं कपित्थगं कर्णवर्धनं साक्षात् कुर्याच्चाभ्यञ्जनालेपान् पलिशोषे प्रकीर्तितान्", text: "carmacaṭikā jalauko hayabandhā śabarakandakaṃ tulyam māhiṣanavanītayutaṃ kapitthagaṃ karṇavardhanaṃ sākṣāt kuryāccābhyañjanālepān paliśoṣe prakīrtitān" },
      { type: "verse", number: "86", sanskrit: "अथ कुर्याद्वयस्थस्य च्छिन्नां शुद्धस्य नासिकाम् छिन्द्यान्नासासमं पत्रं तत्तुल्यं च कपोलतः", text: "atha kuryādvayasthasya cchinnāṃ śuddhasya nāsikām chindyānnāsāsamaṃ patraṃ tattulyaṃ ca kapolataḥ" },
      { type: "verse", number: "87", sanskrit: "त्वङ्मांसं नासिकासन्ने रक्षस्तत्तनुतां नयेत् सीव्येत् गण्डं ततः सूच्या सीवन्या पिचुयुक्तया", text: "tvaṅmāṃsaṃ nāsikāsanne rakṣastattanutāṃ nayet sīvyet gaṇḍaṃ tataḥ sūcyā sīvanyā picuyuktayā" },
      { type: "verse", number: "88", sanskrit: "नासाच्छेदेथ लिखिते परिवर्त्योपरि त्वचम् कपोलवध्रं सन्दध्यात् सीव्येन्नासां च यत्नतः", text: "nāsācchedetha likhite parivartyopari tvacam kapolavadhraṃ sandadhyāt sīvyennāsāṃ ca yatnataḥ" },
      { type: "verse", number: "89", sanskrit: "नाडीभ्यामुत्क्षिपेदन्तः सुखोच्छ्वासप्रवृत्तये आमतैलेन सिक्त्वानु पतङ्गमधुकाञ्जनैः", text: "nāḍībhyāmutkṣipedantaḥ sukhocchvāsapravṛttaye āmatailena siktvānu pataṅgamadhukāñjanaiḥ" },
      { type: "verse", number: "90", sanskrit: "शोणितस्थापनैश्चान्यैः सुश्लक्ष्णैरवचूर्णयेत् ततो मधुघृताभ्यक्तं बध्वाचारिकमादिशेत्", text: "śoṇitasthāpanaiścānyaiḥ suślakṣṇairavacūrṇayet tato madhughṛtābhyaktaṃ badhvācārikamādiśet" },
      { type: "verse", number: "91", sanskrit: "ज्ञात्वावस्थान्तरं कुर्यात् सद्योव्रणविधिं ततः छिन्द्याद्रूढेधिकं मांसं नासोपान्ताच्च चर्म तत् सीव्येत्ततश्च सुश्लक्ष्णं हीनं संवर्धयेत् पुनः", text: "jñātvāvasthāntaraṃ kuryāt sadyovraṇavidhiṃ tataḥ chindyādrūḍhedhikaṃ māṃsaṃ nāsopāntācca carma tat sīvyettataśca suślakṣṇaṃ hīnaṃ saṃvardhayet punaḥ" },
      { type: "verse", number: "92", sanskrit: "निवेशिते यथान्यासं सद्यःच्छिन्नेप्ययं विधिः", text: "niveśite yathānyāsaṃ sadyaḥcchinnepyayaṃ vidhiḥ" },
      { type: "verse", number: "93", sanskrit: "नाडीयोगाद्विनौष्ठस्य नासासन्धानवद्विधिः", text: "nāḍīyogādvinauṣṭhasya nāsāsandhānavadvidhiḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 23,
    lang: "sa",
    content: [
      { type: "heading", heading: "Унмада рога — психические расстройства" },
      { type: "text", text: "Глава 23 Уттара стханы — «Унмада рога» — посвящена специализированному разделу: психические расстройства. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो नासारोगविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto nāsārogavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अवश्यायानिलरजोभाष्यातिस्वप्नजागरैः नीचात्युच्चोपधानेन पीतेनान्येन वारिणा", text: "avaśyāyānilarajobhāṣyātisvapnajāgaraiḥ nīcātyuccopadhānena pītenānyena vāriṇā" },
      { type: "verse", number: "3", sanskrit: "अत्यम्बुपानरमणच्छर्दिबाष्पग्रहादिभिः क्रुद्धा वातोल्बणा दोषा नासायां स्त्यानतां गताः जनयन्ति प्रतिश्यायं वर्धमानं क्षयप्रदम्", text: "atyambupānaramaṇacchardibāṣpagrahādibhiḥ kruddhā vātolbaṇā doṣā nāsāyāṃ styānatāṃ gatāḥ janayanti pratiśyāyaṃ vardhamānaṃ kṣayapradam" },
      { type: "verse", number: "4", sanskrit: "तत्र वातात् प्रतिश्याये मुखशोषो भृशं क्षवः घ्राणोपरोधनिस्तोददन्तशङ्खशिरोव्यथाः", text: "tatra vātāt pratiśyāye mukhaśoṣo bhṛśaṃ kṣavaḥ ghrāṇoparodhanistodadantaśaṅkhaśirovyathāḥ" },
      { type: "verse", number: "5", sanskrit: "कीटका इव सर्पन्ति मन्यते परितो भ्रुवौ स्वरसादश्चिरात् पाकः शिशिराच्छकफस्रुतिः", text: "kīṭakā iva sarpanti manyate parito bhruvau svarasādaścirāt pākaḥ śiśirācchakaphasrutiḥ" },
      { type: "verse", number: "6", sanskrit: "पित्तात्तृष्णाज्वरघ्राणापिटकासम्भवभ्रमाः नासाग्रपाको रूक्षोष्णताम्रपीतकफस्रुतिः", text: "pittāttṛṣṇājvaraghrāṇāpiṭakāsambhavabhramāḥ nāsāgrapāko rūkṣoṣṇatāmrapītakaphasrutiḥ" },
      { type: "verse", number: "7", sanskrit: "कफात् कासोरुचिः श्वासो वमथुर्गात्रगौरवम् माधुर्यं वदने कण्डूः स्निग्धशुक्लकफस्रुतिः", text: "kaphāt kāsoruciḥ śvāso vamathurgātragauravam mādhuryaṃ vadane kaṇḍūḥ snigdhaśuklakaphasrutiḥ" },
      { type: "verse", number: "8", sanskrit: "सर्वजो लक्षणैः सर्वैरकस्माद्वृद्धिशान्तिमान्", text: "sarvajo lakṣaṇaiḥ sarvairakasmādvṛddhiśāntimān" },
      { type: "verse", number: "9", sanskrit: "दुष्टं नासासिराः प्राप्य प्रतिश्यायं करोत्यसृक् उरसः सुप्तता ताम्रनेत्रत्वं श्वासपूतिता कण्डूः श्रोत्राक्षिनासासु पित्तोक्तं चात्र लक्षणम्", text: "duṣṭaṃ nāsāsirāḥ prāpya pratiśyāyaṃ karotyasṛk urasaḥ suptatā tāmranetratvaṃ śvāsapūtitā kaṇḍūḥ śrotrākṣināsāsu pittoktaṃ cātra lakṣaṇam" },
      { type: "verse", number: "10", sanskrit: "सर्व एव प्रतिश्याया दुष्टता यान्त्युपेक्षिताः यथोक्तोपद्रवाधिक्यात् स सर्वेन्द्रियतापनः", text: "sarva eva pratiśyāyā duṣṭatā yāntyupekṣitāḥ yathoktopadravādhikyāt sa sarvendriyatāpanaḥ" },
      { type: "verse", number: "11", sanskrit: "साग्निसादज्वरश्वासकासोरःपार्श्ववेदनः कुप्यत्यकस्माद् बहुशो मुखदौर्गन्ध्यशोषकृत्", text: "sāgnisādajvaraśvāsakāsoraḥpārśvavedanaḥ kupyatyakasmād bahuśo mukhadaurgandhyaśoṣakṛt" },
      { type: "verse", number: "12", sanskrit: "नासिकाक्लेदसंशोषशुद्धिरोधकरो मुहुः पूयोपमासितारक्तग्रथितश्लेष्मसंस्रुतिः मूर्च्छन्ति चात्र कृमयो दीर्घस्निग्धसिताणवः", text: "nāsikākledasaṃśoṣaśuddhirodhakaro muhuḥ pūyopamāsitāraktagrathitaśleṣmasaṃsrutiḥ mūrcchanti cātra kṛmayo dīrghasnigdhasitāṇavaḥ" },
      { type: "verse", number: "13", sanskrit: "पक्वलिङ्गानि तेष्वङ्गलाघवं क्षवथोः शमः श्लेष्मा सुचिक्कणः पीतो ज्ञानं च रसगन्धयोः", text: "pakvaliṅgāni teṣvaṅgalāghavaṃ kṣavathoḥ śamaḥ śleṣmā sucikkaṇaḥ pīto jñānaṃ ca rasagandhayoḥ" },
      { type: "verse", number: "14", sanskrit: "तीक्ष्णाग्राणोपयोगार्करश्मिसूत्रतृणादिभिः वातकोपिभिरन्यैर्वा नासिकातरुणास्थनि", text: "tīkṣṇāgrāṇopayogārkaraśmisūtratṛṇādibhiḥ vātakopibhiranyairvā nāsikātaruṇāsthani" },
      { type: "verse", number: "15", sanskrit: "विघट्टिते ऽनिलः क्रुद्धो रुद्धः शृङ्गाटकं व्रजम् निवृत्तः कुरुते ऽत्यर्थं क्षवथुं स भृशक्षवः", text: "vighaṭṭite 'nilaḥ kruddho ruddhaḥ śṛṅgāṭakaṃ vrajam nivṛttaḥ kurute 'tyarthaṃ kṣavathuṃ sa bhṛśakṣavaḥ" },
      { type: "verse", number: "16", sanskrit: "शोषयन् नासिकास्रोतः कफं च कुरुते ऽनिलः शूकपूर्णाभनासात्वं कृच्छ्रादुच्छ्वसनं ततः स्मृतो ऽसौ नासिकाशोषः नासानाहे तु जायते", text: "śoṣayan nāsikāsrotaḥ kaphaṃ ca kurute 'nilaḥ śūkapūrṇābhanāsātvaṃ kṛcchrāducchvasanaṃ tataḥ smṛto 'sau nāsikāśoṣaḥ nāsānāhe tu jāyate" },
      { type: "verse", number: "17", sanskrit: "नद्धत्वमिव नासायाः श्लेष्मरुद्धेन वायुना निश्वासोच्छ्वाससंरोधात् स्रोतसी संवृते इव", text: "naddhatvamiva nāsāyāḥ śleṣmaruddhena vāyunā niśvāsocchvāsasaṃrodhāt srotasī saṃvṛte iva" },
      { type: "verse", number: "18", sanskrit: "पचेन्नासापुटे पित्तं त्वङ्मांसं दाहशूलवत् स घ्राणपाकः स्रावस्तु तत्संज्ञः श्लेष्मसम्भवः", text: "pacennāsāpuṭe pittaṃ tvaṅmāṃsaṃ dāhaśūlavat sa ghrāṇapākaḥ srāvastu tatsaṃjñaḥ śleṣmasambhavaḥ" },
      { type: "verse", number: "19", sanskrit: "अच्छो जलोपमो ऽजस्रं विशेषान्निशि जायते", text: "accho jalopamo 'jasraṃ viśeṣānniśi jāyate" },
      { type: "verse", number: "20", sanskrit: "कफः प्रवृद्धो नासायां रुध्वा स्रोतांस्यवीनसम् कुर्यात् सघुर्घुरश्वासं पीनसाधिकवेदनम्", text: "kaphaḥ pravṛddho nāsāyāṃ rudhvā srotāṃsyavīnasam kuryāt saghurghuraśvāsaṃ pīnasādhikavedanam" },
      { type: "verse", number: "21", sanskrit: "अवेरिव स्रवत्यस्य प्रक्लिन्ना तेन नासिका अजस्रं पिच्छिलं शीतं पक्वं सिङ्घाणकं घनम्", text: "averiva sravatyasya praklinnā tena nāsikā ajasraṃ picchilaṃ śītaṃ pakvaṃ siṅghāṇakaṃ ghanam" },
      { type: "verse", number: "22", sanskrit: "रक्तेन नासा दग्धेव बाह्यान्तः स्पर्शनासहा भवेद्धूमोपमोच्छ्वासा सा दीर्प्तिदहतीव च", text: "raktena nāsā dagdheva bāhyāntaḥ sparśanāsahā bhaveddhūmopamocchvāsā sā dīrptidahatīva ca" },
      { type: "verse", number: "23", sanskrit: "तालुमूले मलैर्दुष्टे मारुतो मुखनासिकात् श्लेष्मा च पूतिर्निर्गच्छेत् पूतिनासं वदन्ति", text: "tālumūle malairduṣṭe māruto mukhanāsikāt śleṣmā ca pūtirnirgacchet pūtināsaṃ vadanti" },
      { type: "verse", number: "24", sanskrit: "निचयादभिघाताद्वा पूयासृङ्नासिका स्रवेत् तत्पूयरक्तमाख्यातं शिरोदाहरुजाकरम्", text: "nicayādabhighātādvā pūyāsṛṅnāsikā sravet tatpūyaraktamākhyātaṃ śirodāharujākaram" },
      { type: "verse", number: "25", sanskrit: "पित्तश्लेष्मावरुद्धोन्तर्नासायां शोषयेन्मरुत् कफं स शुष्कः पुटतां प्राप्नोति पुटकं तु तत्", text: "pittaśleṣmāvaruddhontarnāsāyāṃ śoṣayenmarut kaphaṃ sa śuṣkaḥ puṭatāṃ prāpnoti puṭakaṃ tu tat" },
      { type: "verse", number: "26", sanskrit: "अर्शोर्बुदानि विभजेद्दोषलिङ्गैर्यथायथम्", text: "arśorbudāni vibhajeddoṣaliṅgairyathāyatham" },
      { type: "verse", number: "27", sanskrit: "सर्वेषु कृच्छ्रोच्छ्वसनं पीनसं प्रततं क्षुतम् सानुनासिकवादित्वं पूतिनासः शिरोव्यथा अष्टादशानामित्येषां यापयेद्दुष्टपीनसम्", text: "sarveṣu kṛcchrocchvasanaṃ pīnasaṃ pratataṃ kṣutam sānunāsikavāditvaṃ pūtināsaḥ śirovyathā aṣṭādaśānāmityeṣāṃ yāpayedduṣṭapīnasam" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 24,
    lang: "sa",
    content: [
      { type: "heading", heading: "Бхута видья — психиатрия с духовным компонентом" },
      { type: "text", text: "Глава 24 Уттара стханы — «Бхута видья» — посвящена специализированному разделу: психиатрия с духовным компонентом. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो नासारोगप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto nāsārogapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सर्वेष्वादौ पीनसेषु स्नेहस्वेदवमनधूमगण्डूषस्निग्धोष्णभोजननिवातशयनासनानि सेवेत", text: "sarveṣvādau pīnaseṣu snehasvedavamanadhūmagaṇḍūṣasnigdhoṣṇabhojananivātaśayanāsanāni seveta" },
      { type: "verse", number: "3", sanskrit: "पाचनार्थं च गुडार्द्रकक्षीरत्रिकटुकाजमांसमद्याम्लभोजनानि", text: "pācanārthaṃ ca guḍārdrakakṣīratrikaṭukājamāṃsamadyāmlabhojanāni" },
      { type: "verse", number: "4", sanskrit: "रोहिषाजाजीवचाचोरकोपकुञ्चिकातर्कारीचातुर्जातकरजो वस्त्रावबद्धं मुहुर्मुहुरुपजिघ्नेत् घृताक्तसक्तून् मल्लकसम्पुटे कृत्वा धूमं च पिबेत्", text: "rohiṣājājīvacācorakopakuñcikātarkārīcāturjātakarajo vastrāvabaddhaṃ muhurmuhurupajighnet ghṛtāktasaktūn mallakasampuṭe kṛtvā dhūmaṃ ca pibet" },
      { type: "verse", number: "5", sanskrit: "पक्वे तु शिरोविरेचनमवपीडं च युञ्ज्यात्", text: "pakve tu śirovirecanamavapīḍaṃ ca yuñjyāt" },
      { type: "verse", number: "6", sanskrit: "निदानोक्तानि च वर्जयेत् विशेषेण शीताम्बुस्नानपानात्युच्चोपधानानुपधानक्रोधशोकान्", text: "nidānoktāni ca varjayet viśeṣeṇa śītāmbusnānapānātyuccopadhānānupadhānakrodhaśokān" },
      { type: "verse", number: "7", sanskrit: "अथ वातप्रतिश्याये पूर्वमेव वातहरद्रव्यविपक्वं ससैन्धवं प्रातः सर्पिः पिबेन्महाषट्पलं वा", text: "atha vātapratiśyāye pūrvameva vātaharadravyavipakvaṃ sasaindhavaṃ prātaḥ sarpiḥ pibenmahāṣaṭpalaṃ vā" },
      { type: "verse", number: "8", sanskrit: "दशमूलकुलत्थकोलयवशुष्कमूलकव्योषलवणपञ्चकैः सदधि धान्याम्लं सर्पिः सिद्धमाहारे पाने च प्रणीतं प्रतिश्याययक्ष्माकासश्वासग्रहणीगुल्मविबन्धघ्नम्", text: "daśamūlakulatthakolayavaśuṣkamūlakavyoṣalavaṇapañcakaiḥ sadadhi dhānyāmlaṃ sarpiḥ siddhamāhāre pāne ca praṇītaṃ pratiśyāyayakṣmākāsaśvāsagrahaṇīgulmavibandhaghnam" },
      { type: "verse", number: "9", sanskrit: "जीर्णस्नेहं जाङ्गलरसेन व्योषदाडिमसैन्धववता बालमूलकरसेन सर्वधान्ययूषेण वा भोजयेत् नागरं वा पयसा पिबेत्", text: "jīrṇasnehaṃ jāṅgalarasena vyoṣadāḍimasaindhavavatā bālamūlakarasena sarvadhānyayūṣeṇa vā bhojayet nāgaraṃ vā payasā pibet" },
      { type: "verse", number: "10", sanskrit: "कृष्णादशमूलशुण्ठीयवैरण्डमूलक्काथासिद्धेन पयसोत्तमाङ्गं स्वेदयेत् तदेव च पानभोजनयोर्विदध्यात् अर्दितोक्तांश्च स्वेदान् एवमपरिपच्यमाने पुनः पुनर्नाडीस्वेदं वातहरं चास्थापनमनुवासनं शिरोबस्तिं च", text: "kṛṣṇādaśamūlaśuṇṭhīyavairaṇḍamūlakkāthāsiddhena payasottamāṅgaṃ svedayet tadeva ca pānabhojanayorvidadhyāt arditoktāṃśca svedān evamaparipacyamāne punaḥ punarnāḍīsvedaṃ vātaharaṃ cāsthāpanamanuvāsanaṃ śirobastiṃ ca" },
      { type: "verse", number: "11", sanskrit: "पक्वे तु तैलं क्षवकचूर्णयुक्तं ससैन्धवं सर्पिर्वा शिरोविरेचनम्", text: "pakve tu tailaṃ kṣavakacūrṇayuktaṃ sasaindhavaṃ sarpirvā śirovirecanam" },
      { type: "verse", number: "12", sanskrit: "पित्तप्रतिश्याये पद्मकोशीरपटोलसारिवाविदारीशतावरीक्षीरिद्रुमशुङ्गशठीकर्कटाख्यादुरालभानामर्द्धढकमष्टगुणेम्भासि विपाच्य पादावशेषे मधुकमृद्वीकाचन्दनशृङ्गाटककशेरुकश्वेतपाकान्यक्षमात्राणि दत्वा घृतप्रस्थं पयसा सह साधयेत् तत् प्रातः पानाय युञ्ज्यात् जीर्णे सुखोष्णतोयपरिषिक्तं ससैन्धवेन रसेन भोजयेत् सुस्निग्धं विरेचयेत् द्राक्षापटोलश्रीपर्णीमूर्वात्रिवृत्क्वाथेन त्रिवृत्पथ्यापूगफलचूर्णान्वितेन", text: "pittapratiśyāye padmakośīrapaṭolasārivāvidārīśatāvarīkṣīridrumaśuṅgaśaṭhīkarkaṭākhyādurālabhānāmarddhaḍhakamaṣṭaguṇembhāsi vipācya pādāvaśeṣe madhukamṛdvīkācandanaśṛṅgāṭakakaśerukaśvetapākānyakṣamātrāṇi datvā ghṛtaprasthaṃ payasā saha sādhayet tat prātaḥ pānāya yuñjyāt jīrṇe sukhoṣṇatoyapariṣiktaṃ sasaindhavena rasena bhojayet susnigdhaṃ virecayet drākṣāpaṭolaśrīparṇīmūrvātrivṛtkvāthena trivṛtpathyāpūgaphalacūrṇānvitena" },
      { type: "verse", number: "13", sanskrit: "विरिक्तभुक्तस्य शीतैः शिरोवक्त्रलेपपरिषेककवलग्रहान् वितरेत्", text: "viriktabhuktasya śītaiḥ śirovaktralepapariṣekakavalagrahān vitaret" },
      { type: "verse", number: "14", sanskrit: "व्यजनपवनविधूयमानश्च नीलशाद्वलोपवनशिशिरकरकिरणधारागृहाणि सेवेत", text: "vyajanapavanavidhūyamānaśca nīlaśādvalopavanaśiśirakarakiraṇadhārāgṛhāṇi seveta" },
      { type: "verse", number: "15", sanskrit: "तत्र च पक्वे दोषे शिरोविरेकं पुराणघृतेन ससैन्धवेन घृतमण्डेन वा कट्फलान्वितेन कुर्यात् विशुद्धस्रोतसश्च जाङ्गलरसेन क्षीरेण वा शीतेन भोजनम्", text: "tatra ca pakve doṣe śirovirekaṃ purāṇaghṛtena sasaindhavena ghṛtamaṇḍena vā kaṭphalānvitena kuryāt viśuddhasrotasaśca jāṅgalarasena kṣīreṇa vā śītena bhojanam" },
      { type: "verse", number: "16", sanskrit: "कफजे तु यवक्षारावचूर्णितमुष्णोदकानुपानं घृतं पाययेत् जीर्णे च तिलमाषपललवतीं यवागूम् ततो वामनीयौषधक्वाथसिद्धया ससर्पिष्कया सैन्धवमाषचूर्णप्रगाढया पेययोष्णाम्भसा च वामयेत्", text: "kaphaje tu yavakṣārāvacūrṇitamuṣṇodakānupānaṃ ghṛtaṃ pāyayet jīrṇe ca tilamāṣapalalavatīṃ yavāgūm tato vāmanīyauṣadhakvāthasiddhayā sasarpiṣkayā saindhavamāṣacūrṇapragāḍhayā peyayoṣṇāmbhasā ca vāmayet" },
      { type: "verse", number: "17", sanskrit: "ततस्तीक्ष्णधूमकवलयवान्नचणकप्रायाहारनाडीस्वदेरुपाचरेत् अरुचिगौरवयोस्तु विशोधयेत्", text: "tatastīkṣṇadhūmakavalayavānnacaṇakaprāyāhāranāḍīsvaderupācaret arucigauravayostu viśodhayet" },
      { type: "verse", number: "18", sanskrit: "पक्वे क्षवकविडङ्गसैन्धवादीभिर्नस्यम् तैलाप्लुतो नागरचूर्णानुविद्धो मुद्ग आहारो यथासात्म्यं च रूक्षतीक्ष्णोष्णम्", text: "pakve kṣavakaviḍaṅgasaindhavādībhirnasyam tailāpluto nāgaracūrṇānuviddho mudga āhāro yathāsātmyaṃ ca rūkṣatīkṣṇoṣṇam" },
      { type: "verse", number: "19", sanskrit: "शुद्धघ्राणपथस्य देवदारुसरलकाकोलीजीवकमधुकपिप्पल्यनन्ताक्षीरविपक्वं तैलं नस्यम्", text: "śuddhaghrāṇapathasya devadārusaralakākolījīvakamadhukapippalyanantākṣīravipakvaṃ tailaṃ nasyam" },
      { type: "verse", number: "20", sanskrit: "सान्निपातिके दोषबलतः प्रतिकुर्यात् रसाञ्जनातिविषामुस्तभद्रदारुसाधितं चात्र तैलं नावनम्", text: "sānnipātike doṣabalataḥ pratikuryāt rasāñjanātiviṣāmustabhadradārusādhitaṃ cātra tailaṃ nāvanam" },
      { type: "verse", number: "21", sanskrit: "रक्तजे पैत्तिको रक्तपित्तोक्तश्च विधिः", text: "raktaje paittiko raktapittoktaśca vidhiḥ" },
      { type: "verse", number: "22", sanskrit: "दुष्टप्रतिश्याये व्योषचित्रकयवक्षारबीजकविडङ्गपूतीकरञ्जत्वग्लवणत्रयैर्मांसरसप्रतीवापविपक्वं सक्षौद्रं सर्पिः पाययेत् जीर्णे घृते जाङ्गलरसेन तलोपसेकं भोजयेत् स्निग्धं च कफप्रतिश्यायवदुपाचरेत्", text: "duṣṭapratiśyāye vyoṣacitrakayavakṣārabījakaviḍaṅgapūtīkarañjatvaglavaṇatrayairmāṃsarasapratīvāpavipakvaṃ sakṣaudraṃ sarpiḥ pāyayet jīrṇe ghṛte jāṅgalarasena talopasekaṃ bhojayet snigdhaṃ ca kaphapratiśyāyavadupācaret" },
      { type: "verse", number: "23", sanskrit: "पक्वे ऽवपीडं व्योषेन्द्रयवविडङ्गसारजीरकसैन्धवैर्बस्तमूत्रपिष्टैर्दद्यात् विशुद्धघ्राणस्रोतसं च पुनरुपस्नेह्य विरेचयेत् भृष्टान्यवान् भूस्तृणकाम्रातकजीरकत्रिवृतायुक्तान् गोमूत्रेण क्वाथयेत् तं क्वाथमभयानागरमरिचक्रमुकसैन्धवयावशूकचूर्णयुक्तं सबीजपूरकरसं पाययेत् कोष्णोदकं चानुकण्ठयेत्", text: "pakve 'vapīḍaṃ vyoṣendrayavaviḍaṅgasārajīrakasaindhavairbastamūtrapiṣṭairdadyāt viśuddhaghrāṇasrotasaṃ ca punarupasnehya virecayet bhṛṣṭānyavān bhūstṛṇakāmrātakajīrakatrivṛtāyuktān gomūtreṇa kvāthayet taṃ kvāthamabhayānāgaramaricakramukasaindhavayāvaśūkacūrṇayuktaṃ sabījapūrakarasaṃ pāyayet koṣṇodakaṃ cānukaṇṭhayet" },
      { type: "verse", number: "24", sanskrit: "विरिक्तं च काले मुस्तहरिद्रानागरयवक्षारपूतीकरञ्जरेणुकाभिरजाविगोत्रदधिभिश्च सिद्धं सर्पिरुपयोजयेत् तीक्ष्णानि च निरूहानुवासनानि अरिष्टांश्च पानार्थम्", text: "viriktaṃ ca kāle mustaharidrānāgarayavakṣārapūtīkarañjareṇukābhirajāvigotradadhibhiśca siddhaṃ sarpirupayojayet tīkṣṇāni ca nirūhānuvāsanāni ariṣṭāṃśca pānārtham" },
      { type: "verse", number: "25", sanskrit: "एवमप्यशान्तौ हिङ्गुक्षारामरदारुविपक्वं घृतं मांसरसानुपानं पिबेत्", text: "evamapyaśāntau hiṅgukṣārāmaradāruvipakvaṃ ghṛtaṃ māṃsarasānupānaṃ pibet" },
      { type: "verse", number: "26", sanskrit: "कोशाम्रपल्लवमूर्वा तर्कारीङ्गुदीफलफणिज्जकमहापञ्चमूलकण्टकारिकासारिवोरुपूगहिंस्रानिम्बशिग्रुफलरक्षोघ्नकृमिघ्नदन्ती पूतिकरञ्जपिप्पलीवार्ताकबीजाहिमारकमूलत्वक्पत्रपुष्पफलैरजामूत्रपिष्टैरजाश्वशकृद्रसयुक्तैर्धूमवर्तिं कृत्वा घृताभ्यक्तां पातुं प्रयच्छेत्", text: "kośāmrapallavamūrvā tarkārīṅgudīphalaphaṇijjakamahāpañcamūlakaṇṭakārikāsārivorupūgahiṃsrānimbaśigruphalarakṣoghnakṛmighnadantī pūtikarañjapippalīvārtākabījāhimārakamūlatvakpatrapuṣpaphalairajāmūtrapiṣṭairajāśvaśakṛdrasayuktairdhūmavartiṃ kṛtvā ghṛtābhyaktāṃ pātuṃ prayacchet" },
      { type: "verse", number: "27", sanskrit: "पिप्पलीवर्धमानं चोपयुञ्जीत कृमिघ्नैश्च योगैर्यापयेत्", text: "pippalīvardhamānaṃ copayuñjīta kṛmighnaiśca yogairyāpayet" },
      { type: "verse", number: "28", sanskrit: "भृशक्षवथौ पुटके च निम्बकट्फलकुष्ठमरिचचूर्णैः क्लेदनाय प्रधमनम् पिप्पलीकुष्ठशुण्ठीविडङ्गमृद्वीकाकषायकल्कविपक्वं तैलं घृतं वा नावनम्", text: "bhṛśakṣavathau puṭake ca nimbakaṭphalakuṣṭhamaricacūrṇaiḥ kledanāya pradhamanam pippalīkuṣṭhaśuṇṭhīviḍaṅgamṛdvīkākaṣāyakalkavipakvaṃ tailaṃ ghṛtaṃ vā nāvanam" },
      { type: "verse", number: "29", sanskrit: "नासाशोषे बलातैलं पाने शिरोबस्तौ च स्निग्धस्य स्वेदः क्षीरसर्पिर्नस्यं मधुरवर्गसाधितं वा तैलम् स्नेहिको धूमः तथा नासानाहे ऽपि एवमनुपशमे शिरोविरेकः", text: "nāsāśoṣe balātailaṃ pāne śirobastau ca snigdhasya svedaḥ kṣīrasarpirnasyaṃ madhuravargasādhitaṃ vā tailam snehiko dhūmaḥ tathā nāsānāhe 'pi evamanupaśame śirovirekaḥ" },
      { type: "verse", number: "30", sanskrit: "नासापाके दीप्तौ च जालौकोभिरस्रविस्रावणम् शीतैरूर्ध्वाधोविरेकलेपसेकाः नासास्रावे तीक्ष्णं नस्यं धूमश्च", text: "nāsāpāke dīptau ca jālaukobhirasravisrāvaṇam śītairūrdhvādhovirekalepasekāḥ nāsāsrāve tīkṣṇaṃ nasyaṃ dhūmaśca" },
      { type: "verse", number: "31", sanskrit: "अवीनसे पूतिनासे च गुडमरिचहिङ्गुशिवाटिकाविडङ्गैरजामूत्रपिष्टैर्नस्यम् कफप्रतिश्यायवच्च स्नेहस्वेदवमनानि", text: "avīnase pūtināse ca guḍamaricahiṅguśivāṭikāviḍaṅgairajāmūtrapiṣṭairnasyam kaphapratiśyāyavacca snehasvedavamanāni" },
      { type: "verse", number: "32", sanskrit: "वमितवतो निर्गुण्डीशिग्रुतर्कारीफणिज्जकक्षवकसुरसार्जकपत्रस्वरसेन सार्षपं पीलुजं वा तैलं विपाच्य नस्यं विदध्यात्", text: "vamitavato nirguṇḍīśigrutarkārīphaṇijjakakṣavakasurasārjakapatrasvarasena sārṣapaṃ pīlujaṃ vā tailaṃ vipācya nasyaṃ vidadhyāt" },
      { type: "verse", number: "33", sanskrit: "लाक्षाविडङ्गपिप्पलीलवङ्गक्षवकनिशाकुष्ठवचाकरञ्जिकाकल्कैर्वा तिलतैलम् शिग्रुबृहतीदन्तीमूलबिल्वव्योषसुरससैन्धवैर्वा", text: "lākṣāviḍaṅgapippalīlavaṅgakṣavakaniśākuṣṭhavacākarañjikākalkairvā tilatailam śigrubṛhatīdantīmūlabilvavyoṣasurasasaindhavairvā" },
      { type: "verse", number: "34", sanskrit: "उत्पन्नमात्रं पूयरक्तं रक्तप्रतिश्यायवच्चिकित्सेत् प्रवृद्धं नाडीव्रणवत् कृतवमनस्य चास्य नस्यधूमौ प्रयोजयेत्", text: "utpannamātraṃ pūyaraktaṃ raktapratiśyāyavaccikitset pravṛddhaṃ nāḍīvraṇavat kṛtavamanasya cāsya nasyadhūmau prayojayet" },
      { type: "verse", number: "35", sanskrit: "अर्शांसि विधिवत् क्षारेणाग्निना वा दहेत् स्थूलानि तु शस्त्रेण स्पृष्ट्वा दाहानन्तरं शीतां क्रियां योजयेत्", text: "arśāṃsi vidhivat kṣāreṇāgninā vā dahet sthūlāni tu śastreṇa spṛṣṭvā dāhānantaraṃ śītāṃ kriyāṃ yojayet" },
      { type: "verse", number: "36", sanskrit: "वर्तिं च नासायां कुम्भनिकुम्भाग्निकसैन्धवपिप्पलीमनश्शिलालकल्कमधुघृतप्रदिग्धाम्", text: "vartiṃ ca nāsāyāṃ kumbhanikumbhāgnikasaindhavapippalīmanaśśilālakalkamadhughṛtapradigdhām" },
      { type: "verse", number: "37", sanskrit: "तुवरिकाबिभीतकहरिद्रालोध्रप्रियङ्गुकरञ्जिकाकल्कगुडोदकविपक्वं तैलं नावनम् करञ्जकलोध्रोत्पलमधुकतिन्दुकास्थित्रिफलाखदिरसारविपक्वं", text: "tuvarikābibhītakaharidrālodhrapriyaṅgukarañjikākalkaguḍodakavipakvaṃ tailaṃ nāvanam karañjakalodhrotpalamadhukatindukāsthitriphalākhadirasāravipakvaṃ" },
      { type: "verse", number: "38", sanskrit: "यथादोषं च स्नेहवमनविरेकादीन् प्रणिदध्यात्", text: "yathādoṣaṃ ca snehavamanavirekādīn praṇidadhyāt" },
      { type: "verse", number: "39", sanskrit: "अर्बुदं बडिशेन गृहीत्वा मण्डलाग्रेण मूले समं छिन्द्यात् छिन्नं चोच्छिङ्खयेत् चलप्रमृष्टं च व्रणं शलाकया दहेत्तैलेन वा अग्निदग्धं म्रङ्क्षयेत्ततः शिशिरैः प्रदेहैः", text: "arbudaṃ baḍiśena gṛhītvā maṇḍalāgreṇa mūle samaṃ chindyāt chinnaṃ cocchiṅkhayet calapramṛṣṭaṃ ca vraṇaṃ śalākayā dahettailena vā agnidagdhaṃ mraṅkṣayettataḥ śiśiraiḥ pradehaiḥ" },
      { type: "verse", number: "40", sanskrit: "उपरूढव्रणस्य लोध्रावापं तीक्ष्णोष्णलवणद्रव्यगोमूत्रयुक्तं सार्षपं कारञ्जं वा तैलं नावनम् पित्तजे रक्तजे वार्बुदे गोदन्तसैन्धवालकासीसकांस्यनीलैरम्बुपिष्टैरालेपः ततश्च शीताः प्रदेहसेकाः शीतैरेव च साधितानि घृतान्यभ्यङ्गनस्यपानानि", text: "uparūḍhavraṇasya lodhrāvāpaṃ tīkṣṇoṣṇalavaṇadravyagomūtrayuktaṃ sārṣapaṃ kārañjaṃ vā tailaṃ nāvanam pittaje raktaje vārbude godantasaindhavālakāsīsakāṃsyanīlairambupiṣṭairālepaḥ tataśca śītāḥ pradehasekāḥ śītaireva ca sādhitāni ghṛtānyabhyaṅganasyapānāni" },
      { type: "verse", number: "41", sanskrit: "मांसमेदः सन्निपातार्शोर्बुदानि चैवं साधयेदिति भवति चात्र", text: "māṃsamedaḥ sannipātārśorbudāni caivaṃ sādhayediti bhavati cātra" },
      { type: "verse", number: "42", sanskrit: "उपसंहरति हीनच्छेदात् पुनर्बृद्धिरतिच्छेदात् स्वरक्षयः गन्धाज्ञानं च वीसर्पो मूर्च्छा छिन्द्यादतः समम्", text: "upasaṃharati hīnacchedāt punarbṛddhiraticchedāt svarakṣayaḥ gandhājñānaṃ ca vīsarpo mūrcchā chindyādataḥ samam" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 25,
    lang: "sa",
    content: [
      { type: "heading", heading: "Бала граха — детские духовные болезни" },
      { type: "text", text: "Глава 25 Уттара стханы — «Бала граха» — посвящена специализированному разделу: детские духовные болезни. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो मुखरोगविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto mukharogavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "मात्स्यमहिषवाराहपिशितामकमूलकम् माषसूपदधिक्षीरशुक्तेक्षुरसफाणितम्", text: "mātsyamahiṣavārāhapiśitāmakamūlakam māṣasūpadadhikṣīraśuktekṣurasaphāṇitam" },
      { type: "verse", number: "3", sanskrit: "अवाक्शय्यां च भजतो द्विषतो दन्तधावनम् धूमच्छर्दनगण्डूषानुचितं च सिराव्यधम् क्रुद्धाः श्लेष्मोल्बणा दोषाः कुर्वन्त्यन्तर्मुखं गदान्", text: "avākśayyāṃ ca bhajato dviṣato dantadhāvanam dhūmacchardanagaṇḍūṣānucitaṃ ca sirāvyadham kruddhāḥ śleṣmolbaṇā doṣāḥ kurvantyantarmukhaṃ gadān" },
      { type: "verse", number: "4", sanskrit: "तत्र खण्डौष्ठ इत्युक्तो वातेनौष्ठो द्विधाकृतः", text: "tatra khaṇḍauṣṭha ityukto vātenauṣṭho dvidhākṛtaḥ" },
      { type: "verse", number: "5", sanskrit: "ओष्ठकोपे तु पवनात् स्तब्धावोष्ठौ महारुजौ दाल्येते परिपाट्येते परुषासितकर्कशौ", text: "oṣṭhakope tu pavanāt stabdhāvoṣṭhau mahārujau dālyete paripāṭyete paruṣāsitakarkaśau" },
      { type: "verse", number: "6", sanskrit: "पित्तात्तीक्ष्णासहौ पीतौ सर्षपाकृतिभिश्चितौ पिटकाभिर्बहुक्लेदावाशुपाकौ #", text: "pittāttīkṣṇāsahau pītau sarṣapākṛtibhiścitau piṭakābhirbahukledāvāśupākau #" },
      { type: "verse", number: "7", sanskrit: "कफात् पुनः शीतासहौ गुरू शूनौ सवर्णपिटकाचितौ", text: "kaphāt punaḥ śītāsahau gurū śūnau savarṇapiṭakācitau" },
      { type: "verse", number: "8", sanskrit: "सन्निपातादनेकाभौ दुर्गन्धास्रावपिच्छिलौ अकस्मान्म्लानसंशूनरुजौ विषमपाकिनौ", text: "sannipātādanekābhau durgandhāsrāvapicchilau akasmānmlānasaṃśūnarujau viṣamapākinau" },
      { type: "verse", number: "9", sanskrit: "रक्तोपसृष्टौ रुधिरं स्रवतः शोणितप्रभौ खर्जूरसदृशं चात्र क्षीणे रक्तेर्बुदं भवेत्", text: "raktopasṛṣṭau rudhiraṃ sravataḥ śoṇitaprabhau kharjūrasadṛśaṃ cātra kṣīṇe rakterbudaṃ bhavet" },
      { type: "verse", number: "10", sanskrit: "मांसपिण्डोपमौ मांसात् स्यातां मूर्च्छत्कृमी क्रमात्", text: "māṃsapiṇḍopamau māṃsāt syātāṃ mūrcchatkṛmī kramāt" },
      { type: "verse", number: "11", sanskrit: "तैलाभश्वयथुक्लेदौ सकण्ड्वौ मेदसा मृदू", text: "tailābhaśvayathukledau sakaṇḍvau medasā mṛdū" },
      { type: "verse", number: "12", sanskrit: "क्षतजाववदीर्येते पाट्येते चासकृत् पुनः ग्रथितौ च पुनः स्यातां कण्डूलौ दशनच्छदौ", text: "kṣatajāvavadīryete pāṭyete cāsakṛt punaḥ grathitau ca punaḥ syātāṃ kaṇḍūlau daśanacchadau" },
      { type: "verse", number: "13", sanskrit: "जलबुद्बुदवद्वातकफादोष्ठे जलार्बुदम्", text: "jalabudbudavadvātakaphādoṣṭhe jalārbudam" },
      { type: "verse", number: "14", sanskrit: "गण्डालजी स्थिरः शोफो गण्डे दाहरुजान्वितः", text: "gaṇḍālajī sthiraḥ śopho gaṇḍe dāharujānvitaḥ" },
      { type: "verse", number: "15", sanskrit: "वातादुष्णासहादन्ताः शीतस्पर्शाधिकव्यथाः दाल्यन्त इव शूलेन शीताख्यो दालनश्च सः", text: "vātāduṣṇāsahādantāḥ śītasparśādhikavyathāḥ dālyanta iva śūlena śītākhyo dālanaśca saḥ" },
      { type: "verse", number: "16", sanskrit: "दन्तहर्षे प्रवाताम्लशीतभक्षाक्षमा द्विजाः भवन्त्यम्लाशनेनैव सरुजश्चलिता इव", text: "dantaharṣe pravātāmlaśītabhakṣākṣamā dvijāḥ bhavantyamlāśanenaiva sarujaścalitā iva" },
      { type: "verse", number: "17", sanskrit: "दन्तभेदे द्विजास्तोदभेदरुक्स्फुटनान्विताः चालश्वलद्भिर्दशनैर्भक्षणादधिकव्यथैः", text: "dantabhede dvijāstodabhedaruksphuṭanānvitāḥ cālaśvaladbhirdaśanairbhakṣaṇādadhikavyathaiḥ" },
      { type: "verse", number: "18", sanskrit: "करालस्तु करालानां दशनानां समुद्भवः", text: "karālastu karālānāṃ daśanānāṃ samudbhavaḥ" },
      { type: "verse", number: "19", sanskrit: "दन्तोधिकोधिदन्ताख्यः स चोक्तः खलवर्द्धनः जायमाने ऽतिरुग्दन्ते जाते तत्र तु शाम्यति", text: "dantodhikodhidantākhyaḥ sa coktaḥ khalavarddhanaḥ jāyamāne 'tirugdante jāte tatra tu śāmyati" },
      { type: "verse", number: "20", sanskrit: "अधावनान्मलो दन्ते कफो वा वातशोषितः पूतिगन्धिः स्थिरीभूतः शर्करा #", text: "adhāvanānmalo dante kapho vā vātaśoṣitaḥ pūtigandhiḥ sthirībhūtaḥ śarkarā #" },
      { type: "verse", number: "21", sanskrit: "साप्युपेक्षिता शातयत्यणुशो दन्तकपालानि कपालिका", text: "sāpyupekṣitā śātayatyaṇuśo dantakapālāni kapālikā" },
      { type: "verse", number: "22", sanskrit: "श्यावः श्यावत्वमायातो रक्तपित्तानिलैर्द्विजः", text: "śyāvaḥ śyāvatvamāyāto raktapittānilairdvijaḥ" },
      { type: "verse", number: "23", sanskrit: "समूलं दन्तमाश्रित्य दोषैरुल्बणमारुतैः शोषिते मज्ज्ञि सुषिरे दन्तेन्नमलपूरिते", text: "samūlaṃ dantamāśritya doṣairulbaṇamārutaiḥ śoṣite majjñi suṣire dantennamalapūrite" },
      { type: "verse", number: "24", sanskrit: "पूतित्वात् कृमयः सूक्ष्मा जायन्ते जायते ततः अहेतुतीव्रार्तिशमः ससंरम्भोसितश्चलः प्रलूनः पूयरक्तस्रुत् स चोक्तः कृमिदन्तकः", text: "pūtitvāt kṛmayaḥ sūkṣmā jāyante jāyate tataḥ ahetutīvrārtiśamaḥ sasaṃrambhositaścalaḥ pralūnaḥ pūyaraktasrut sa coktaḥ kṛmidantakaḥ" },
      { type: "verse", number: "25", sanskrit: "श्लेष्मरक्तेन पूतीनि वहन्त्यस्रमहेतुकम् शीर्यन्ते दन्तमांसानि मृदुक्लिन्नासितानि च शीतादोसौ #", text: "śleṣmaraktena pūtīni vahantyasramahetukam śīryante dantamāṃsāni mṛduklinnāsitāni ca śītādosau #" },
      { type: "verse", number: "26", sanskrit: "उपकुशः पाकः पित्तासृगुद्भवः दन्तमांसानि दह्यन्ते रक्तान्युत्सेधवन्त्यतः", text: "upakuśaḥ pākaḥ pittāsṛgudbhavaḥ dantamāṃsāni dahyante raktānyutsedhavantyataḥ" },
      { type: "verse", number: "27", sanskrit: "कण्डूमन्ति स्रवन्त्यस्रमाध्मायन्तेसृजिस्थिते चला मन्दरुजो दन्ताः पूतिवक्त्रं च जायते", text: "kaṇḍūmanti sravantyasramādhmāyantesṛjisthite calā mandarujo dantāḥ pūtivaktraṃ ca jāyate" },
      { type: "verse", number: "28", sanskrit: "दन्तयोस्त्रिषु वा शोफो बदरस्थिनिभो घनः कफास्रात्तीव्ररुक् शीघ्रं पच्यते दन्तपुप्पुटः", text: "dantayostriṣu vā śopho badarasthinibho ghanaḥ kaphāsrāttīvraruk śīghraṃ pacyate dantapuppuṭaḥ" },
      { type: "verse", number: "29", sanskrit: "दन्तमांसे मलैः सास्रैर्बाह्यान्तः श्वयथुर्गुरुः सरुग्दाहः स्रवेत् भिन्नः पूयास्रं दन्तविद्रधिः", text: "dantamāṃse malaiḥ sāsrairbāhyāntaḥ śvayathurguruḥ sarugdāhaḥ sravet bhinnaḥ pūyāsraṃ dantavidradhiḥ" },
      { type: "verse", number: "30", sanskrit: "श्वयथुर्दन्तमूलेषु रुजावान्रक्तपित्तजः लालास्रावी स सुषिरो दन्तमांसप्रशातनः", text: "śvayathurdantamūleṣu rujāvānraktapittajaḥ lālāsrāvī sa suṣiro dantamāṃsapraśātanaḥ" },
      { type: "verse", number: "31", sanskrit: "स सन्निपातज्वरवान् सपूयरुधिरस्रुतिः महासुषिर इत्युक्तो विशीर्णद्विजबन्धनः", text: "sa sannipātajvaravān sapūyarudhirasrutiḥ mahāsuṣira ityukto viśīrṇadvijabandhanaḥ" },
      { type: "verse", number: "32", sanskrit: "दन्तान्ते कीलवच्छोफो हनुकर्णरुजाकरः प्रतिहन्त्यभ्यवहृतिं श्लेष्मणा सोधिमांसकः", text: "dantānte kīlavacchopho hanukarṇarujākaraḥ pratihantyabhyavahṛtiṃ śleṣmaṇā sodhimāṃsakaḥ" },
      { type: "verse", number: "33", sanskrit: "घृष्टेषु दन्तमांसेषु संरम्भो जायते महान् यस्मिंश्चलन्ति दन्ताश्च स विदर्भोभिघातजः", text: "ghṛṣṭeṣu dantamāṃseṣu saṃrambho jāyate mahān yasmiṃścalanti dantāśca sa vidarbhobhighātajaḥ" },
      { type: "verse", number: "34", sanskrit: "दन्तमांसाश्रितान्रोगान् यः साध्यानप्युपेक्षते अन्तस्तस्यास्रवन् दोषः सूक्ष्मां सञ्जनयेद्गतिम् पूयं मुहुः सा स्रवति त्वङ्मांसास्थिप्रभेदिनी", text: "dantamāṃsāśritānrogān yaḥ sādhyānapyupekṣate antastasyāsravan doṣaḥ sūkṣmāṃ sañjanayedgatim pūyaṃ muhuḥ sā sravati tvaṅmāṃsāsthiprabhedinī" },
      { type: "verse", number: "35", sanskrit: "ताः पुनः पञ्च विज्ञेया लक्षणैः स्वैर्यथोदितैः", text: "tāḥ punaḥ pañca vijñeyā lakṣaṇaiḥ svairyathoditaiḥ" },
      { type: "verse", number: "36", sanskrit: "शाकपत्रखरास्रस्ता स्फुटिता वातदूषिता जिह्वा पित्तात् सदाहोषा रक्तैर्मांसाङ्कुरैश्चिता शाल्मलीकण्टकाभैस्तु कफेन बहला गुरुः", text: "śākapatrakharāsrastā sphuṭitā vātadūṣitā jihvā pittāt sadāhoṣā raktairmāṃsāṅkuraiścitā śālmalīkaṇṭakābhaistu kaphena bahalā guruḥ" },
      { type: "verse", number: "37", sanskrit: "कफपित्तादधः शोफो जिह्वास्तम्भकृदुन्नतः मत्स्यगन्धिर्भवेत् पक्वः सोलसो मांसशातनः", text: "kaphapittādadhaḥ śopho jihvāstambhakṛdunnataḥ matsyagandhirbhavet pakvaḥ solaso māṃsaśātanaḥ" },
      { type: "verse", number: "38", sanskrit: "प्रबन्धने ऽधो जिह्वायाः शोफो जिह्वाग्रसन्निभः साङ्कुरः कफपित्तास्रैर्लालोषास्तम्भवान् खरः अधिजिह्वः सरुक्कण्डूवाक्याहारविघातकृत्", text: "prabandhane 'dho jihvāyāḥ śopho jihvāgrasannibhaḥ sāṅkuraḥ kaphapittāsrairlāloṣāstambhavān kharaḥ adhijihvaḥ sarukkaṇḍūvākyāhāravighātakṛt" },
      { type: "verse", number: "39", sanskrit: "तादृगेवोपजिह्वस्तु जिह्वाया उपरि स्थितः", text: "tādṛgevopajihvastu jihvāyā upari sthitaḥ" },
      { type: "verse", number: "40", sanskrit: "तालुमांसेनिलाद्दुष्टे पिटकाः सरुजाः खराः बह्व्यो घनास्रावयुतास्तास्तालुपिटकाः स्मृताः", text: "tālumāṃsenilādduṣṭe piṭakāḥ sarujāḥ kharāḥ bahvyo ghanāsrāvayutāstāstālupiṭakāḥ smṛtāḥ" },
      { type: "verse", number: "41", sanskrit: "तालुमूले कफात्सास्रान्मत्स्यबस्तिनिभो मृदुः प्रलम्बः पिच्छिलः शोफो नासयाहारमीरयन् कण्ठोपरोधतृट्कासवमिकृत् गलशुण्डिका", text: "tālumūle kaphātsāsrānmatsyabastinibho mṛduḥ pralambaḥ picchilaḥ śopho nāsayāhāramīrayan kaṇṭhoparodhatṛṭkāsavamikṛt galaśuṇḍikā" },
      { type: "verse", number: "42", sanskrit: "तालुमध्ये निरुङ्मांसं संहतं तालुसंहतिः", text: "tālumadhye niruṅmāṃsaṃ saṃhataṃ tālusaṃhatiḥ" },
      { type: "verse", number: "43", sanskrit: "पद्माकृतिस्तालुमध्ये रक्ताच्छ्वयथुरर्बुदम्", text: "padmākṛtistālumadhye raktācchvayathurarbudam" },
      { type: "verse", number: "44", sanskrit: "कच्छपः कच्छपाकारश्चिरवृद्धिः कफादरुक्", text: "kacchapaḥ kacchapākāraściravṛddhiḥ kaphādaruk" },
      { type: "verse", number: "45", sanskrit: "कोलाभः श्लेष्ममेदोभ्यां पुप्पुटो नीरुजः स्थिरः", text: "kolābhaḥ śleṣmamedobhyāṃ puppuṭo nīrujaḥ sthiraḥ" },
      { type: "verse", number: "46", sanskrit: "पित्तेन पाकः पाकाख्यः पूयास्रावी महारुजः", text: "pittena pākaḥ pākākhyaḥ pūyāsrāvī mahārujaḥ" },
      { type: "verse", number: "47", sanskrit: "वातपित्तज्वरायासैस्तालुशोषस्तदाह्वयः", text: "vātapittajvarāyāsaistāluśoṣastadāhvayaḥ" },
      { type: "verse", number: "48", sanskrit: "जिह्वाप्रबन्धजाः कण्ठे दारुणा मार्गरोधिनः मांसाङ्कुराः शीघ्रचया रोहिणी शीघ्रकारिणी", text: "jihvāprabandhajāḥ kaṇṭhe dāruṇā mārgarodhinaḥ māṃsāṅkurāḥ śīghracayā rohiṇī śīghrakāriṇī" },
      { type: "verse", number: "49", sanskrit: "कण्ठास्यशोषकृद्वातात् सा हनुश्रोत्ररुक्करी पित्ताज्ज्वरोषातृण्मोहकण्ठधूमायनान्विता", text: "kaṇṭhāsyaśoṣakṛdvātāt sā hanuśrotrarukkarī pittājjvaroṣātṛṇmohakaṇṭhadhūmāyanānvitā" },
      { type: "verse", number: "50", sanskrit: "क्षिप्रजा क्षिप्रपाकातिरागिणी स्पर्शनासहा कफेन पिच्छिला पाण्डुरसृजा स्फोटकाचिता", text: "kṣiprajā kṣiprapākātirāgiṇī sparśanāsahā kaphena picchilā pāṇḍurasṛjā sphoṭakācitā" },
      { type: "verse", number: "51", sanskrit: "तप्ताङ्गारनिभा कर्णरुक्वरी पित्तजाकृतिः गम्भीरपाका निचयात् सर्वलिङ्गसमन्विता", text: "taptāṅgāranibhā karṇarukvarī pittajākṛtiḥ gambhīrapākā nicayāt sarvaliṅgasamanvitā" },
      { type: "verse", number: "52", sanskrit: "दोषैः कफोल्बणैः शोफः कोलवत् ग्रथितोन्नतः शूककण्टकवत् कण्ठे शालूको मार्गरोधनः", text: "doṣaiḥ kapholbaṇaiḥ śophaḥ kolavat grathitonnataḥ śūkakaṇṭakavat kaṇṭhe śālūko mārgarodhanaḥ" },
      { type: "verse", number: "53", sanskrit: "वृन्दो वृत्तोन्नतो दाहज्वरकृत् गलपार्श्वगः", text: "vṛndo vṛttonnato dāhajvarakṛt galapārśvagaḥ" },
      { type: "verse", number: "54", sanskrit: "हनुसन्ध्याश्रितः कण्ठे कार्पासीफलसन्निभः पिच्छिलो मन्दरुक्शोफः कठिनस्तुण्डिकेरिका", text: "hanusandhyāśritaḥ kaṇṭhe kārpāsīphalasannibhaḥ picchilo mandarukśophaḥ kaṭhinastuṇḍikerikā" },
      { type: "verse", number: "55", sanskrit: "बाह्यान्तःश्ववथुर्घोरो गलमार्गार्गलोपमः गलौघो मूर्द्धगुरुतातन्द्रालालाज्वरप्रदः", text: "bāhyāntaḥśvavathurghoro galamārgārgalopamaḥ galaugho mūrddhagurutātandrālālājvarapradaḥ" },
      { type: "verse", number: "56", sanskrit: "वलयं नातिरुक्शोफस्तद्वदेवायतोन्नतः", text: "valayaṃ nātirukśophastadvadevāyatonnataḥ" },
      { type: "verse", number: "57", sanskrit: "मांसकीलो गले दोषैरेकोनेकोथवाल्परुक् कृच्छ्रोछ्वासोभ्यवहृतिः पृथुमूलो गिलायुकः", text: "māṃsakīlo gale doṣairekonekothavālparuk kṛcchrochvāsobhyavahṛtiḥ pṛthumūlo gilāyukaḥ" },
      { type: "verse", number: "58", sanskrit: "भूरिमांसाकुङ्रवृता तीव्रतृङ्ज्वरमूर्द्धरुक् शतघ्नी निचिता वर्तिः शतघ्नीवातिरुक्करी", text: "bhūrimāṃsākuṅravṛtā tīvratṛṅjvaramūrddharuk śataghnī nicitā vartiḥ śataghnīvātirukkarī" },
      { type: "verse", number: "59", sanskrit: "व्याप्तसर्वगलः शीघ्रजन्मपाको महारुजः पूतिपूयनिभास्नावी श्वयथुर्गलविद्रधिः", text: "vyāptasarvagalaḥ śīghrajanmapāko mahārujaḥ pūtipūyanibhāsnāvī śvayathurgalavidradhiḥ" },
      { type: "verse", number: "60", sanskrit: "जिह्वावसाने कण्ठादावपाकं श्वयथुं मलाः जनयन्ति स्थिरं रक्तं नीरुजं तद्गलार्बुदम्", text: "jihvāvasāne kaṇṭhādāvapākaṃ śvayathuṃ malāḥ janayanti sthiraṃ raktaṃ nīrujaṃ tadgalārbudam" },
      { type: "verse", number: "61", sanskrit: "पवनश्लेष्ममेदोभिर्गलगण्डो भवेत् बहिः वर्द्धमानः स कालेन मुष्कवल्लम्बते निरुक्", text: "pavanaśleṣmamedobhirgalagaṇḍo bhavet bahiḥ varddhamānaḥ sa kālena muṣkavallambate niruk" },
      { type: "verse", number: "62", sanskrit: "कृष्णारुणो वा तोदाढ्यः स वातात् कृष्णराजिमान् वृद्धस्तालुगले शोषं कुर्याच्च विरसास्यताम्", text: "kṛṣṇāruṇo vā todāḍhyaḥ sa vātāt kṛṣṇarājimān vṛddhastālugale śoṣaṃ kuryācca virasāsyatām" },
      { type: "verse", number: "63", sanskrit: "स्थिरः सवर्णः कण्डूमान् शीतस्पर्शो गुरुः कफात् वृद्धस्तालुगले लेपं कुर्याच्च मधुरास्यताम्", text: "sthiraḥ savarṇaḥ kaṇḍūmān śītasparśo guruḥ kaphāt vṛddhastālugale lepaṃ kuryācca madhurāsyatām" },
      { type: "verse", number: "64", sanskrit: "मेदसा श्लेष्मवद्धानिवृध्योः सोनुविधीयते देहं वृद्धस्य कुरुते गले शब्दं स्वरे ऽल्पता", text: "medasā śleṣmavaddhānivṛdhyoḥ sonuvidhīyate dehaṃ vṛddhasya kurute gale śabdaṃ svare 'lpatā" },
      { type: "verse", number: "65", sanskrit: "श्लेष्मरुद्धानिलगतिः शुष्ककण्ठो हतस्वरः ताम्यन् प्रसक्तं श्वसिति येन स स्वरहानिलात्", text: "śleṣmaruddhānilagatiḥ śuṣkakaṇṭho hatasvaraḥ tāmyan prasaktaṃ śvasiti yena sa svarahānilāt" },
      { type: "verse", number: "66", sanskrit: "करोति वदनस्यान्तर्व्रणान् सर्वसरो ऽनिलः सञ्चारिणो ऽरुणान्रूक्षानो ष्ठौ ताम्रौ चलत्वचौ", text: "karoti vadanasyāntarvraṇān sarvasaro 'nilaḥ sañcāriṇo 'ruṇānrūkṣāno ṣṭhau tāmrau calatvacau" },
      { type: "verse", number: "67", sanskrit: "जिह्वा शीतासहा गुर्वी स्फुटिता कण्टकाचिता विवृणोति च कृच्छ्रेण मुखं पाको मुखस्य सः", text: "jihvā śītāsahā gurvī sphuṭitā kaṇṭakācitā vivṛṇoti ca kṛcchreṇa mukhaṃ pāko mukhasya saḥ" },
      { type: "verse", number: "68", sanskrit: "अधः प्रतिहतो वायुरर्शोगुल्मकफादिभिः यात्यूर्ध्वं वक्त्रदौर्गन्ध्यं कुर्वन्नूर्ध्वगुदस्तु सः", text: "adhaḥ pratihato vāyurarśogulmakaphādibhiḥ yātyūrdhvaṃ vaktradaurgandhyaṃ kurvannūrdhvagudastu saḥ" },
      { type: "verse", number: "69", sanskrit: "मुखस्य पित्तजे पाके दाहोषे तिक्तवक्त्रता क्षारोक्षितक्षतसमा व्रणास्तद्वच्च रक्तजे", text: "mukhasya pittaje pāke dāhoṣe tiktavaktratā kṣārokṣitakṣatasamā vraṇāstadvacca raktaje" },
      { type: "verse", number: "70", sanskrit: "क्वफजे मधुरास्यत्वं कण्डूमत्पिच्छिला व्रणाः", text: "kvaphaje madhurāsyatvaṃ kaṇḍūmatpicchilā vraṇāḥ" },
      { type: "verse", number: "71", sanskrit: "अन्तः कपोलमाश्रित्य श्यावपाण्डु कफोर्बुदम् कुर्यात्तत् घट्टितं छिन्नं मृदितं च विवर्धते", text: "antaḥ kapolamāśritya śyāvapāṇḍu kaphorbudam kuryāttat ghaṭṭitaṃ chinnaṃ mṛditaṃ ca vivardhate" },
      { type: "verse", number: "72", sanskrit: "मुखपाको भवेत् सास्रैः सर्वैः सर्वाकृतिर्मलैः", text: "mukhapāko bhavet sāsraiḥ sarvaiḥ sarvākṛtirmalaiḥ" },
      { type: "verse", number: "73", sanskrit: "पूत्यास्यता च तैरेव दन्तकाष्ठादिविद्विषः", text: "pūtyāsyatā ca taireva dantakāṣṭhādividviṣaḥ" },
      { type: "verse", number: "74", sanskrit: "औष्ठे गण्डे द्विजे मूले जिह्वायां तालुके गले वक्त्रे सर्वत्र चेत्युक्ता पञ्चसप्ततिरामयाः", text: "auṣṭhe gaṇḍe dvije mūle jihvāyāṃ tāluke gale vaktre sarvatra cetyuktā pañcasaptatirāmayāḥ" },
      { type: "verse", number: "75", sanskrit: "एकादशैको दश च त्रयोदश तथा च षट् अष्टावष्टादशाष्टौ च क्रमात् तेष्वनुपक्रमाः", text: "ekādaśaiko daśa ca trayodaśa tathā ca ṣaṭ aṣṭāvaṣṭādaśāṣṭau ca kramāt teṣvanupakramāḥ" },
      { type: "verse", number: "76", sanskrit: "करालो मांसरक्तोष्ठावर्बुदानि जलाद्विना कच्छपस्तालुपिटका गलौघः सुषिरो महान्", text: "karālo māṃsaraktoṣṭhāvarbudāni jalādvinā kacchapastālupiṭakā galaughaḥ suṣiro mahān" },
      { type: "verse", number: "77", sanskrit: "स्वरघ्नोर्ध्वगुदश्यावशतघ्नीवलयालसाः नाड्योष्ठकोपौ निचयाद्रक्तात् सर्वैश्च रोहिणी", text: "svaraghnordhvagudaśyāvaśataghnīvalayālasāḥ nāḍyoṣṭhakopau nicayādraktāt sarvaiśca rohiṇī" },
      { type: "verse", number: "78", sanskrit: "दशने स्वरभ्रंशी कृच्छ्रोच्छवासो ऽतिवत्सरः याप्यस्तु हर्षो भेदश्च शेषान् शस्त्रौषधैर्जयेत्", text: "daśane svarabhraṃśī kṛcchrocchavāso 'tivatsaraḥ yāpyastu harṣo bhedaśca śeṣān śastrauṣadhairjayet" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 26,
    lang: "sa",
    content: [
      { type: "heading", heading: "Кумара рога — детские болезни" },
      { type: "text", text: "Глава 26 Уттара стханы — «Кумара рога» — посвящена специализированному разделу: детские болезни. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो मुखरोगप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto mukharogapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "स्निग्धस्विन्नस्य खण्डौष्ठस्यौष्ठान्तौ विलिख्य सुश्लिष्टौ क्षौमसूत्रेण सीव्येत् शतधौतघृताभ्यक्तां चास्मै कबलिकां व्रणस्योपरि दद्यात् प्रक्लिन्नं च व्रणं व्रणचिकित्सया साधयेत्", text: "snigdhasvinnasya khaṇḍauṣṭhasyauṣṭhāntau vilikhya suśliṣṭau kṣaumasūtreṇa sīvyet śatadhautaghṛtābhyaktāṃ cāsmai kabalikāṃ vraṇasyopari dadyāt praklinnaṃ ca vraṇaṃ vraṇacikitsayā sādhayet" },
      { type: "verse", number: "3", sanskrit: "ज्योतिष्मतीलोध्रमधुकपटोलोत्पलकाकमाचीश्रावणीसारिवाभिस्तैलं विपक्वमभ्यञ्जनाच्छोधनरोपणम् तथा वातहरमधुरौषधसिद्धं तैलं नस्यम्", text: "jyotiṣmatīlodhramadhukapaṭolotpalakākamācīśrāvaṇīsārivābhistailaṃ vipakvamabhyañjanācchodhanaropaṇam tathā vātaharamadhurauṣadhasiddhaṃ tailaṃ nasyam" },
      { type: "verse", number: "4", sanskrit: "वातज औष्ठकोपे देवदारुगुग्गुलुसर्जरसमधूच्छिष्टसिद्धेन महास्नेहेनाभ्यङ्गः तेनैव समधुकचूर्णेन प्रतिसारणाम् तदभ्यक्तेन पिचुना प्रच्छादनम् एरण्डपल्लवैः क्षीरक्वथितैर्नाडीस्वेदः खण्डौष्ठोक्तं नावनं शिरो ऽभ्यङ्गश्च", text: "vātaja auṣṭhakope devadāruguggulusarjarasamadhūcchiṣṭasiddhena mahāsnehenābhyaṅgaḥ tenaiva samadhukacūrṇena pratisāraṇām tadabhyaktena picunā pracchādanam eraṇḍapallavaiḥ kṣīrakvathitairnāḍīsvedaḥ khaṇḍauṣṭhoktaṃ nāvanaṃ śiro 'bhyaṅgaśca" },
      { type: "verse", number: "5", sanskrit: "पित्तोत्थे ऽभिघातजे च जालौकोभिर्विस्रावणम् पत्तङ्गयष्टीछिन्नरुहाविपक्वं सर्पिरभ्यङ्गः मधुमधुकलोध्रसर्जरसैः प्रतिसारणम् पित्तविद्रधिवच्च चिकित्सा", text: "pittotthe 'bhighātaje ca jālaukobhirvisrāvaṇam pattaṅgayaṣṭīchinnaruhāvipakvaṃ sarpirabhyaṅgaḥ madhumadhukalodhrasarjarasaiḥ pratisāraṇam pittavidradhivacca cikitsā" },
      { type: "verse", number: "6", sanskrit: "रक्तजेप्यचिरोत्थिते पैत्तिकवत् प्रतिकुर्यात् कफजे जलौकोभिः शाकादिपत्रैर्वा रक्तं विस्राव्य व्योषपाठायवक्षारस्वर्जिकाक्षारैः सक्षौद्रैः प्रतिसारयेत् कुष्ठतगरदन्तीश्यामाबिडहरितालविडङ्गैर्वा स्वेदनस्यधूमकवलांश्च कफघ्नानवचारयेत्", text: "raktajepyacirotthite paittikavat pratikuryāt kaphaje jalaukobhiḥ śākādipatrairvā raktaṃ visrāvya vyoṣapāṭhāyavakṣārasvarjikākṣāraiḥ sakṣaudraiḥ pratisārayet kuṣṭhatagaradantīśyāmābiḍaharitālaviḍaṅgairvā svedanasyadhūmakavalāṃśca kaphaghnānavacārayet" },
      { type: "verse", number: "7", sanskrit: "मेदोजे दन्तच्छदं स्वेदयित्वा वृद्धिपत्रेण विपाट्य शुद्धमेदसमग्निनानुपचरेत् कफजोक्तैश्च प्रतिसारणम् जलार्बुदोक्तं तैलं रोपणम्", text: "medoje dantacchadaṃ svedayitvā vṛddhipatreṇa vipāṭya śuddhamedasamagninānupacaret kaphajoktaiśca pratisāraṇam jalārbudoktaṃ tailaṃ ropaṇam" },
      { type: "verse", number: "8", sanskrit: "जलार्बुदं भित्वा विशोध्य त्रिकटुकटुकातेजोवतीयवक्षारस्वर्जिकासैन्धवकासीसचूर्णैः सक्षौद्रैः प्रतिसारयेत् अवगाढमतिवृद्धं वा क्षारेणाग्निना वा दहेत् हरिद्रालोध्रमधुकमालतीहरेणुतगरैर्विपक्वं तैलं रोपणम्", text: "jalārbudaṃ bhitvā viśodhya trikaṭukaṭukātejovatīyavakṣārasvarjikāsaindhavakāsīsacūrṇaiḥ sakṣaudraiḥ pratisārayet avagāḍhamativṛddhaṃ vā kṣāreṇāgninā vā dahet haridrālodhramadhukamālatīhareṇutagarairvipakvaṃ tailaṃ ropaṇam" },
      { type: "verse", number: "9", sanskrit: "गण्डालजीमपक्वां शोफवद्विदग्धामुपनाह्य पक्वां विदार्य व्रणवत् साधयेत्", text: "gaṇḍālajīmapakvāṃ śophavadvidagdhāmupanāhya pakvāṃ vidārya vraṇavat sādhayet" },
      { type: "verse", number: "10", sanskrit: "शीतदन्तस्योष्णामुबुस्विन्नस्य व्रीहिमुखेन पालीं लिखित्वा पिचुतैलेन दहेत् प्रतिसारयेच्च प्रियङ्गुजम्ब्वस्थिदाडिमत्वक्त्रिफलारसाञ्जनसैन्धवशुण्ठीमुस्तचूर्णैः समधुघृतैः क्षीरिवृक्षकषायो गण्डूषः अणुतैलं नस्यम्", text: "śītadantasyoṣṇāmubusvinnasya vrīhimukhena pālīṃ likhitvā picutailena dahet pratisārayecca priyaṅgujambvasthidāḍimatvaktriphalārasāñjanasaindhavaśuṇṭhīmustacūrṇaiḥ samadhughṛtaiḥ kṣīrivṛkṣakaṣāyo gaṇḍūṣaḥ aṇutailaṃ nasyam" },
      { type: "verse", number: "11", sanskrit: "दन्तहर्षे भेदे च वातहरसिद्धं तैलमेलाकुष्ठपाटलीस्वग्विपक्वो मज्जा वा गण्डूषः स्निग्धाश्च नस्यादयः", text: "dantaharṣe bhede ca vātaharasiddhaṃ tailamelākuṣṭhapāṭalīsvagvipakvo majjā vā gaṇḍūṣaḥ snigdhāśca nasyādayaḥ" },
      { type: "verse", number: "12", sanskrit: "दन्तचाले दशमूलक्वाथेन तैलसर्पिर्वसाक्षौद्रैश्च कवलः पिप्पलीसैन्धवतुत्थलोध्रपतङ्गस्रोतोजमुस्तात्रिफलाः प्रतिसारणम् नियतं च स्नैहिकधूमपायी स्निग्धमधुराहारो विस्रावणपरः स्यात् चन्दनपद्मकमधुकविदारीकशेरुकनीलोत्पलमृद्वीकाजीवकर्षभकशर्कराणां प्रत्येकं पलेन क्षीरेण च मांसरसद्विगुणेन तैलप्रस्थं विपाचयेत् एतन्नस्यगण्डूषप्रयोगात् परं दशननयनश्रवणबलकरम्", text: "dantacāle daśamūlakvāthena tailasarpirvasākṣaudraiśca kavalaḥ pippalīsaindhavatutthalodhrapataṅgasrotojamustātriphalāḥ pratisāraṇam niyataṃ ca snaihikadhūmapāyī snigdhamadhurāhāro visrāvaṇaparaḥ syāt candanapadmakamadhukavidārīkaśerukanīlotpalamṛdvīkājīvakarṣabhakaśarkarāṇāṃ pratyekaṃ palena kṣīreṇa ca māṃsarasadviguṇena tailaprasthaṃ vipācayet etannasyagaṇḍūṣaprayogāt paraṃ daśananayanaśravaṇabalakaram" },
      { type: "verse", number: "13", sanskrit: "अधिदन्तकं क्षारेणालिप्य जर्जरं विज्ञाय कृमिदन्तकविधिनोत्पाड्य तद्वदेवोपचरेत् अनवस्थितशोणितं च दग्ध्वा व्रणवदुपक्रमेत", text: "adhidantakaṃ kṣāreṇālipya jarjaraṃ vijñāya kṛmidantakavidhinotpāḍya tadvadevopacaret anavasthitaśoṇitaṃ ca dagdhvā vraṇavadupakrameta" },
      { type: "verse", number: "14", sanskrit: "दन्तशर्करां दन्तमूलान्यपीडयन् दन्तलेखनेन विलिख्य क्षारतैलेनावसेचयेत् मूषाकूर्पपाटलीत्वक्चूर्णेन प्रतिसारणम् सदा च दन्तधावनादीन् सेवेत दन्तहर्षोक्तं च कुर्यात्", text: "dantaśarkarāṃ dantamūlānyapīḍayan dantalekhanena vilikhya kṣāratailenāvasecayet mūṣākūrpapāṭalītvakcūrṇena pratisāraṇam sadā ca dantadhāvanādīn seveta dantaharṣoktaṃ ca kuryāt" },
      { type: "verse", number: "15", sanskrit: "कपालिकायामेतदेव विशेषतः शीलयेत्", text: "kapālikāyāmetadeva viśeṣataḥ śīlayet" },
      { type: "verse", number: "16", sanskrit: "कृमिदन्तके सुषिरं गुडेन मधूच्छिष्टेन सर्पिष वापूरयित्वा तप्तया कुब्जशलाकया दहेत् सप्तच्छर्दाकक्षीरं वा पूरणम् सर्षपकरञ्जतैलं", text: "kṛmidantake suṣiraṃ guḍena madhūcchiṣṭena sarpiṣa vāpūrayitvā taptayā kubjaśalākayā dahet saptacchardākakṣīraṃ vā pūraṇam sarṣapakarañjatailaṃ" },
      { type: "verse", number: "17", sanskrit: "हिङ्गुविडङ्गस्वर्जिकाकट्फलकासीसकुष्ठचूर्णस्तान्तवबद्धो दन्तस्योपरि तिष्ठन् रुजमपहरति कुन्दुरुष्कचूर्णो वा एभिरेव च सिद्धं तैलं गण्डूषः दृढगूढमूलमांसे सरुजे विस्रावणम् भग्नस्फुटितविवर्णसुप्तचलस्य सरुजस्य च", text: "hiṅguviḍaṅgasvarjikākaṭphalakāsīsakuṣṭhacūrṇastāntavabaddho dantasyopari tiṣṭhan rujamapaharati kunduruṣkacūrṇo vā ebhireva ca siddhaṃ tailaṃ gaṇḍūṣaḥ dṛḍhagūḍhamūlamāṃse saruje visrāvaṇam bhagnasphuṭitavivarṇasuptacalasya sarujasya ca" },
      { type: "verse", number: "18", sanskrit: "एवमनुपशमे सन्दंशयन्त्रेण दन्तमायतं गृहीत्वा विचाल्य शस्रेण पार्श्वेभ्यो मोक्षयित्वोद्धरेत् दन्तनिर्घातनेनोत्पीड्य मुद्गरेणाश्मना वा निर्घातयेत् न तूत्तरं दन्तम्", text: "evamanupaśame sandaṃśayantreṇa dantamāyataṃ gṛhītvā vicālya śasreṇa pārśvebhyo mokṣayitvoddharet dantanirghātanenotpīḍya mudgareṇāśmanā vā nirghātayet na tūttaraṃ dantam" },
      { type: "verse", number: "19", sanskrit: "तस्योद्धरणाच्छोणितात्ययस्ततश्चेन्द्रियभ्रंशो वात व्याधिर्वा", text: "tasyoddharaṇācchoṇitātyayastataścendriyabhraṃśo vāta vyādhirvā" },
      { type: "verse", number: "20", sanskrit: "प्रक्षालितमुखश्च समधुकचूर्णं तैलं मधु वा गण्डूषं धारयेत्", text: "prakṣālitamukhaśca samadhukacūrṇaṃ tailaṃ madhu vā gaṇḍūṣaṃ dhārayet" },
      { type: "verse", number: "21", sanskrit: "विदारीमधुकशृङ्गाटककशेरुकाभिस्तैलं दशगुणे पयसि सिद्धं नस्यम्", text: "vidārīmadhukaśṛṅgāṭakakaśerukābhistailaṃ daśaguṇe payasi siddhaṃ nasyam" },
      { type: "verse", number: "22", sanskrit: "उत्तरदन्तोद्धरणेप्ययमेव प्रतीकारः शीतोपचारश्च सुतराम्", text: "uttaradantoddharaṇepyayameva pratīkāraḥ śītopacāraśca sutarām" },
      { type: "verse", number: "23", sanskrit: "शीतादे शोणितं विस्राव्य रसाञ्जनमुस्तत्रिफलार्जुनत्वक्प्रियङ्गुमहौषधकषायं गण्डूषं धारयेत् एभिरेव च सक्षौद्रैः प्रतिसारणं मधुरवर्गसिद्धं तैलं नस्यम् तेजोवतीव्योषहरिद्राद्वयकुष्ठपाठाकटुरोहिणीलोध्रसमङ्गामुस्तैः प्रतिसारणं सर्वदन्तमांसामयेषु कण्डूश्वयथुवेदनारक्तस्रुतिहरम् तथा व्याषयवक्षारमनश्शिलासैन्धवदार्वीत्वग्भिः एभिरेवाषैर्धगुटिका सर्वमुखरोगहरा", text: "śītāde śoṇitaṃ visrāvya rasāñjanamustatriphalārjunatvakpriyaṅgumahauṣadhakaṣāyaṃ gaṇḍūṣaṃ dhārayet ebhireva ca sakṣaudraiḥ pratisāraṇaṃ madhuravargasiddhaṃ tailaṃ nasyam tejovatīvyoṣaharidrādvayakuṣṭhapāṭhākaṭurohiṇīlodhrasamaṅgāmustaiḥ pratisāraṇaṃ sarvadantamāṃsāmayeṣu kaṇḍūśvayathuvedanāraktasrutiharam tathā vyāṣayavakṣāramanaśśilāsaindhavadārvītvagbhiḥ ebhirevāṣairdhaguṭikā sarvamukharogaharā" },
      { type: "verse", number: "24", sanskrit: "उपकुशे सुखोष्णाम्बुस्विन्नान्युत्सन्नानि दन्तमांसान्यवलिखेन्मण्डलाग्रेण शाकादिपत्रैर्वा ततः सुखोष्णो घृतमण्डस्तैलं वा गण्डूषः मरिचकुष्ठमधुकप्रियङ्गुलाक्षापतङ्गगैरिकरसाञ्जनशुण्ठीसैन्धवैर्मधुघृतमण्डयुक्तैः प्रतिसारणम् पृथक्पर्णीविडङ्गविदारीमधुकपयस्यासुरदारुविपक्वं तैलं गण्डूषो नस्यं च मधुरवर्गसिद्धमेव वा सर्पिः पुनः पुनश्च रुधिरावसेकः", text: "upakuśe sukhoṣṇāmbusvinnānyutsannāni dantamāṃsānyavalikhenmaṇḍalāgreṇa śākādipatrairvā tataḥ sukhoṣṇo ghṛtamaṇḍastailaṃ vā gaṇḍūṣaḥ maricakuṣṭhamadhukapriyaṅgulākṣāpataṅgagairikarasāñjanaśuṇṭhīsaindhavairmadhughṛtamaṇḍayuktaiḥ pratisāraṇam pṛthakparṇīviḍaṅgavidārīmadhukapayasyāsuradāruvipakvaṃ tailaṃ gaṇḍūṣo nasyaṃ ca madhuravargasiddhameva vā sarpiḥ punaḥ punaśca rudhirāvasekaḥ" },
      { type: "verse", number: "25", sanskrit: "दन्तपुप्पुटके स्विन्नछिन्नभिन्नविलिखिते स्वर्जिकामधुकशुण्ठीसैन्धवैः प्रतिसारणम्", text: "dantapuppuṭake svinnachinnabhinnavilikhite svarjikāmadhukaśuṇṭhīsaindhavaiḥ pratisāraṇam" },
      { type: "verse", number: "26", sanskrit: "दन्तविद्रधौ तिक्तकटुकषायोष्णैः समूत्रैः कबलो लेपश्च वृश्चिकालीकुष्ठकटुकायवक्षारैः प्रतिसारणम् तं च पाकतो रूक्षशीतैरन्तर्बहिः प्रयुक्तैर्वारयेत् पक्वे तु पाटनमवगाढे दाहः त्रिफलासुमनोरिष्ठक्वाथो गण्डूषः यष्टीमधुकसिद्धः सर्पिर्मण्डो नस्यम्", text: "dantavidradhau tiktakaṭukaṣāyoṣṇaiḥ samūtraiḥ kabalo lepaśca vṛścikālīkuṣṭhakaṭukāyavakṣāraiḥ pratisāraṇam taṃ ca pākato rūkṣaśītairantarbahiḥ prayuktairvārayet pakve tu pāṭanamavagāḍhe dāhaḥ triphalāsumanoriṣṭhakvātho gaṇḍūṣaḥ yaṣṭīmadhukasiddhaḥ sarpirmaṇḍo nasyam" },
      { type: "verse", number: "27", sanskrit: "सुषिरे छिन्नलिखिते लोध्रमुस्तत्रिफलाकिंशुकपतङ्गतार्क्ष्यशैलशतपुष्पाकट्फलैरवघर्षः तेषामेव क्वाथो गण्डूषः क्षीरिवृक्षकिंशुकामलकानां वा गैरिकोत्पलमधूकसारिवाचन्दनप्रपौण्डकशर्करानन्तालोध्रागरुसिद्धं तैलं नावनम्", text: "suṣire chinnalikhite lodhramustatriphalākiṃśukapataṅgatārkṣyaśailaśatapuṣpākaṭphalairavagharṣaḥ teṣāmeva kvātho gaṇḍūṣaḥ kṣīrivṛkṣakiṃśukāmalakānāṃ vā gairikotpalamadhūkasārivācandanaprapauṇḍakaśarkarānantālodhrāgarusiddhaṃ tailaṃ nāvanam" },
      { type: "verse", number: "28", sanskrit: "अधिमांसकमचिरोत्थितं स्रावयेत् विवृद्धन्तु बडिशेन मचुट्या वा गृहीत्वा मण्डलाग्रेण छित्वा तीक्ष्णैः प्रतिसारयेत् कटुतीक्ष्णैः कवलस्तैलं वा यवक्षारावचूर्णितम्", text: "adhimāṃsakamacirotthitaṃ srāvayet vivṛddhantu baḍiśena macuṭyā vā gṛhītvā maṇḍalāgreṇa chitvā tīkṣṇaiḥ pratisārayet kaṭutīkṣṇaiḥ kavalastailaṃ vā yavakṣārāvacūrṇitam" },
      { type: "verse", number: "29", sanskrit: "विदर्भे दन्तमूलानि शस्त्रेण विशोध्य क्षारं प्रयुज्य घृतमण्डं गण्डूषे दद्यात् लोध्रपतङ्गमञ्जिष्ठामधुकचूर्णः प्रतिसारणम् काकोलीयष्टीमधुशर्कराविपक्वं तैलं नावनम्", text: "vidarbhe dantamūlāni śastreṇa viśodhya kṣāraṃ prayujya ghṛtamaṇḍaṃ gaṇḍūṣe dadyāt lodhrapataṅgamañjiṣṭhāmadhukacūrṇaḥ pratisāraṇam kākolīyaṣṭīmadhuśarkarāvipakvaṃ tailaṃ nāvanam" },
      { type: "verse", number: "30", sanskrit: "दन्तनाडीमेषयित्वा संवृतां शस्त्रेण विवृतयित्वा तदाश्रितं दन्तमशेषमुद्धृत्य शलाकया दहेत् कुब्जामवगाढामनेकगतिं वा गुडमधुसिक्थान्यतमपूर्णाम् ततः क्षीरिवृक्षकषायेण गण्डूषं धारयेत् तत्सिद्धेन वा तैलेन", text: "dantanāḍīmeṣayitvā saṃvṛtāṃ śastreṇa vivṛtayitvā tadāśritaṃ dantamaśeṣamuddhṛtya śalākayā dahet kubjāmavagāḍhāmanekagatiṃ vā guḍamadhusikthānyatamapūrṇām tataḥ kṣīrivṛkṣakaṣāyeṇa gaṇḍūṣaṃ dhārayet tatsiddhena vā tailena" },
      { type: "verse", number: "31", sanskrit: "दन्तीखदिरसारमदनस्वादुकण्टकक्वाथे लोध्रवालकोशीरदेवदारुमञ्जिष्ठामधुककल्कविपक्वं तैलं सर्षपतैलं वा नाडीशोधनरोपणम्", text: "dantīkhadirasāramadanasvādukaṇṭakakvāthe lodhravālakośīradevadārumañjiṣṭhāmadhukakalkavipakvaṃ tailaṃ sarṣapatailaṃ vā nāḍīśodhanaropaṇam" },
      { type: "verse", number: "32", sanskrit: "प्रपौण्डरीकहरिद्राद्वयमधुकमधूच्छिष्टलोध्रकटुकीशर्करापद्मकचन्दनमूर्वोपोदकावास्तुकतण्डुलीयकमञ्जिष्ठाम्लीकाकपित्थपत्रैर्वा", text: "prapauṇḍarīkaharidrādvayamadhukamadhūcchiṣṭalodhrakaṭukīśarkarāpadmakacandanamūrvopodakāvāstukataṇḍulīyakamañjiṣṭhāmlīkākapitthapatrairvā" },
      { type: "verse", number: "33", sanskrit: "नस्यं च विडङ्गमधुकमुस्तनिर्गुण्डीखदिरमञ्जिष्ठोशीरसुरतरुसिद्धं तैलं धूमासृक्स्रावणनावनानि शीलयेत् नाडीसाधनं चेक्षेत", text: "nasyaṃ ca viḍaṅgamadhukamustanirguṇḍīkhadiramañjiṣṭhośīrasuratarusiddhaṃ tailaṃ dhūmāsṛksrāvaṇanāvanāni śīlayet nāḍīsādhanaṃ cekṣeta" },
      { type: "verse", number: "34", sanskrit: "वातजेषु जिह्वाकण्टकेषु वातौष्ठकोपोक्तो विधिः पित्तजेषु विघृष्टस्रुतरुधिरेषु स्वादुभिर्द्रव्यैरवघर्षणगण्डूषनावनानि कुर्यात् तद्वत् कफजेषु तीक्ष्णैः", text: "vātajeṣu jihvākaṇṭakeṣu vātauṣṭhakopokto vidhiḥ pittajeṣu vighṛṣṭasrutarudhireṣu svādubhirdravyairavagharṣaṇagaṇḍūṣanāvanāni kuryāt tadvat kaphajeṣu tīkṣṇaiḥ" },
      { type: "verse", number: "35", sanskrit: "जिह्वालसे नवोत्थिते तीक्ष्णाः प्रतिसारणादयः न चात्र शस्त्रमवचारयेत् सिरां तु विध्येत्", text: "jihvālase navotthite tīkṣṇāḥ pratisāraṇādayaḥ na cātra śastramavacārayet sirāṃ tu vidhyet" },
      { type: "verse", number: "36", sanskrit: "अधिजिह्वामुन्नम्य बडिशेन गृहीत्वा मण्डलाग्रेण छिद्यात् तीक्ष्णाश्च नस्यादयः उपजिह्वां शाकपत्रेणाङ्गुलिशस्त्रेण वा विस्राव्य यवक्षारेण प्रतिसारयेत्", text: "adhijihvāmunnamya baḍiśena gṛhītvā maṇḍalāgreṇa chidyāt tīkṣṇāśca nasyādayaḥ upajihvāṃ śākapatreṇāṅguliśastreṇa vā visrāvya yavakṣāreṇa pratisārayet" },
      { type: "verse", number: "37", sanskrit: "गलशुण्डिकां कफघ्नैरुपाचरेत् वृद्धायां तूर्वारुबीजनिभमसिराततमग्रमुपरिजिव्हायानिविष्टं बडिशेन मुचुट्या वा वस्त्रवेष्टिताभ्यां वामाङ्गुष्ठप्रदेशिनीभ्यां गृहीत्वा मण्डलाग्रेण नात्यग्रे नातिमूले छिन्द्यात् अग्रच्छेदादनुपशमः शोफो लालादिवृद्धिर्वा अतिच्छेदाच्छोणितक्षयेण मरणम् सम्यक्च्छिन्नायां पूर्ववत् प्रतिसारणादयः", text: "galaśuṇḍikāṃ kaphaghnairupācaret vṛddhāyāṃ tūrvārubījanibhamasirātatamagramuparijivhāyāniviṣṭaṃ baḍiśena mucuṭyā vā vastraveṣṭitābhyāṃ vāmāṅguṣṭhapradeśinībhyāṃ gṛhītvā maṇḍalāgreṇa nātyagre nātimūle chindyāt agracchedādanupaśamaḥ śopho lālādivṛddhirvā aticchedācchoṇitakṣayeṇa maraṇam samyakcchinnāyāṃ pūrvavat pratisāraṇādayaḥ" },
      { type: "verse", number: "38", sanskrit: "तालुसङ्घाते पुप्पुटे कच्छपे च नवे विधिरयम् शस्त्रकर्मणि तु विशेषः अत्र हि विलेखनम्", text: "tālusaṅghāte puppuṭe kacchape ca nave vidhirayam śastrakarmaṇi tu viśeṣaḥ atra hi vilekhanam" },
      { type: "verse", number: "39", sanskrit: "तालुपाके त्वपक्वस्य श्वय्थोः कासीसरसाञ्जनक्षौद्रैः प्रतिसारणम् मधुरकषायैः शीतैर्गण्डूषः पक्वस्य मण्डलाग्रेणाष्टापदवत् भेदनम् तीक्ष्णैरवघर्षणम् पटोलारिष्टजातीकरवीरगुडूचीवृषकटुकाहरिद्राद्वयवेत्राग्रकण्टकारिकाक्वाथः कवलो मधु तैलं च", text: "tālupāke tvapakvasya śvaythoḥ kāsīsarasāñjanakṣaudraiḥ pratisāraṇam madhurakaṣāyaiḥ śītairgaṇḍūṣaḥ pakvasya maṇḍalāgreṇāṣṭāpadavat bhedanam tīkṣṇairavagharṣaṇam paṭolāriṣṭajātīkaravīraguḍūcīvṛṣakaṭukāharidrādvayavetrāgrakaṇṭakārikākvāthaḥ kavalo madhu tailaṃ ca" },
      { type: "verse", number: "40", sanskrit: "तालुशोषे मधुकपिप्पलीनागरसिद्धं सर्पिरुत्तरं भक्तिकं सतृष्णः पिबेत् अम्लैश्चास्य गण्डूषः पयस्यामधूकमधूलिकाविपक्वं क्षीरसर्पिर्नस्यम् स्निग्धो धूमः तृष्णाघ्नमन्नपानम्", text: "tāluśoṣe madhukapippalīnāgarasiddhaṃ sarpiruttaraṃ bhaktikaṃ satṛṣṇaḥ pibet amlaiścāsya gaṇḍūṣaḥ payasyāmadhūkamadhūlikāvipakvaṃ kṣīrasarpirnasyam snigdho dhūmaḥ tṛṣṇāghnamannapānam" },
      { type: "verse", number: "41", sanskrit: "कण्ठरोगेषु तु ज्वराद्यनुपद्रुतेषु कटुनीक्ष्णैर्नस्यावघर्षणगण्डूषादयः सिराव्यधो रसाञ्जनेन्द्रयवदार्वीनिम्बक्वाथः पानम् व्योषयवक्षारदार्वीरसाञ्जनतेजोवतीपाठानिम्बत्वक्त्रिफलाचित्रकैः शुक्तगोमूत्रक्वथितैः कवलो गुटिका वा प्रतिसारणम् तालीसपत्रगृहधूमपञ्चकोलकैलामरिचपलाशमुष्ककक्षारयवक्षारैर्यवक्वाथेन गुटिकाः कृताः सर्वकण्ठरोगेष्वमृतोपमाः", text: "kaṇṭharogeṣu tu jvarādyanupadruteṣu kaṭunīkṣṇairnasyāvagharṣaṇagaṇḍūṣādayaḥ sirāvyadho rasāñjanendrayavadārvīnimbakvāthaḥ pānam vyoṣayavakṣāradārvīrasāñjanatejovatīpāṭhānimbatvaktriphalācitrakaiḥ śuktagomūtrakvathitaiḥ kavalo guṭikā vā pratisāraṇam tālīsapatragṛhadhūmapañcakolakailāmaricapalāśamuṣkakakṣārayavakṣārairyavakvāthena guṭikāḥ kṛtāḥ sarvakaṇṭharogeṣvamṛtopamāḥ" },
      { type: "verse", number: "42", sanskrit: "अथ वातरोहिणीकामन्तर्बहिः स्विन्नामङ्गुलिशस्त्रकेण मधुलवणगर्भेण वा नखेन विस्राव्य तीक्ष्णैः प्रतिसारयेत् महापञ्चमूलक्वाथो गण्डूषः एलापुनर्नवसिंहीकपित्थकल्कपयोविपक्वं तैलं गण्डूषो नावनं च", text: "atha vātarohiṇīkāmantarbahiḥ svinnāmaṅguliśastrakeṇa madhulavaṇagarbheṇa vā nakhena visrāvya tīkṣṇaiḥ pratisārayet mahāpañcamūlakvātho gaṇḍūṣaḥ elāpunarnavasiṃhīkapitthakalkapayovipakvaṃ tailaṃ gaṇḍūṣo nāvanaṃ ca" },
      { type: "verse", number: "43", sanskrit: "पित्तजामप्येवं विस्राव्य पतङ्गशर्करालोध्रप्रियङ्गुभिः प्रतिसारयेत् एषामेव कषायो गण्डूषः द्राक्षापरूषकोशीरमधुकचन्दनक्वाथो वा त्रिफलातिल्वकश्यामाश्रीपर्णीत्वङ्मधुयष्टिकाभिर्दशगुणे पयसि सिद्धं सर्पिर्नस्यकवलभोजनेषु", text: "pittajāmapyevaṃ visrāvya pataṅgaśarkarālodhrapriyaṅgubhiḥ pratisārayet eṣāmeva kaṣāyo gaṇḍūṣaḥ drākṣāparūṣakośīramadhukacandanakvātho vā triphalātilvakaśyāmāśrīparṇītvaṅmadhuyaṣṭikābhirdaśaguṇe payasi siddhaṃ sarpirnasyakavalabhojaneṣu" },
      { type: "verse", number: "44", sanskrit: "रक्तजामप्येवं प्रत्याख्यायोपक्रमेत्", text: "raktajāmapyevaṃ pratyākhyāyopakramet" },
      { type: "verse", number: "45", sanskrit: "श्लैष्मिकीं स्वेदयित्वा विलिख्य कटुकवर्गेणागारधूमत्रिफलासैन्धवयुक्तेन प्रतिसारयेत् तद्विधाश्च गण्डूषाः निम्बजात्यपामार्गविडङ्गविपक्वं तैलं नस्यम्", text: "ślaiṣmikīṃ svedayitvā vilikhya kaṭukavargeṇāgāradhūmatriphalāsaindhavayuktena pratisārayet tadvidhāśca gaṇḍūṣāḥ nimbajātyapāmārgaviḍaṅgavipakvaṃ tailaṃ nasyam" },
      { type: "verse", number: "46", sanskrit: "शालूकवृन्दतुण्डिकेरीगिलायुष्वप्येष एव विधिः", text: "śālūkavṛndatuṇḍikerīgilāyuṣvapyeṣa eva vidhiḥ" },
      { type: "verse", number: "47", sanskrit: "गलविद्रधौ विस्रावितायां लोध्रवरारसाञ्जनपतङ्गगैरिकरोचनापिप्पलीसैन्धवचूर्णैरवघर्षणम् एभिरेव क्वथितैर्गण्डूषः किराततिक्तकलोध्रदार्वी शतपुष्पानिम्बपत्रकुष्ठैलागुडूचीचित्रकतगरमुस्ताक्वाथ कल्कविपक्वं तैलं नावनम्", text: "galavidradhau visrāvitāyāṃ lodhravarārasāñjanapataṅgagairikarocanāpippalīsaindhavacūrṇairavagharṣaṇam ebhireva kvathitairgaṇḍūṣaḥ kirātatiktakalodhradārvī śatapuṣpānimbapatrakuṣṭhailāguḍūcīcitrakatagaramustākvātha kalkavipakvaṃ tailaṃ nāvanam" },
      { type: "verse", number: "48", sanskrit: "गलगण्डमनिलजं स्वेदयित्वा विस्रावयेत् रूढव्रण च तिलप्रियाललट्वामूलकशणातसीबीजैरुपनाहयेत् तिल्वकाग्निमन्थपुनर्नवकालामृतासौभाञ्जनक गजपिप्पल्येकैषिकार्कमूलकरघाटकपुष्पैः सुराम्लपिष्टैः पुनः पुनर्लेपयेत् निम्बगुडूचीकुटजहंसपादीकृष्णाबलाद्वयदेवदारुसिद्धं च तैलं पाययेत्", text: "galagaṇḍamanilajaṃ svedayitvā visrāvayet rūḍhavraṇa ca tilapriyālalaṭvāmūlakaśaṇātasībījairupanāhayet tilvakāgnimanthapunarnavakālāmṛtāsaubhāñjanaka gajapippalyekaiṣikārkamūlakaraghāṭakapuṣpaiḥ surāmlapiṣṭaiḥ punaḥ punarlepayet nimbaguḍūcīkuṭajahaṃsapādīkṛṣṇābalādvayadevadārusiddhaṃ ca tailaṃ pāyayet" },
      { type: "verse", number: "49", sanskrit: "श्लैष्मिकेप्ययमेव विधिः तीक्ष्णतराश्च स्वेदप्रलेपादयः विशल्यातिविषाविषाणिकाशुकनासाजगन्धागुञ्जाफलकटुकालाबुभिः पलाशक्षारम्बुपिष्टैः सुखोष्णो लेपः वत्सकादिना पञ्चलवणयुक्तेन सिद्धं तैलं पानम् तीक्ष्णांश्च वमनादीन् शीलयेत् पर्यायतश्च स्वेदं शोणितावसेचनं च तथानुपशमे पाचयित्वा व्रणवदुभावप्युपाचरेत् यवान्नमुद्गादियूषांच व्योषोत्कटान् पानभोजनयोर्विदध्यात्", text: "ślaiṣmikepyayameva vidhiḥ tīkṣṇatarāśca svedapralepādayaḥ viśalyātiviṣāviṣāṇikāśukanāsājagandhāguñjāphalakaṭukālābubhiḥ palāśakṣārambupiṣṭaiḥ sukhoṣṇo lepaḥ vatsakādinā pañcalavaṇayuktena siddhaṃ tailaṃ pānam tīkṣṇāṃśca vamanādīn śīlayet paryāyataśca svedaṃ śoṇitāvasecanaṃ ca tathānupaśame pācayitvā vraṇavadubhāvapyupācaret yavānnamudgādiyūṣāṃca vyoṣotkaṭān pānabhojanayorvidadhyāt" },
      { type: "verse", number: "50", sanskrit: "मेदाज स्विन्नस्य सिरां विध्येत् पूर्वोक्ताः प्रलेपाः प्रातः प्रातश्चासनादिसाररजो गोमूत्रेण पिबेत् एवमप्यशान्तौ शस्त्रेण विदार्य मेदो विशोध्य सीव्येत् दाहयोग्यं वा वसाघृतक्षौद्रान्यतमेन यथावद्दहेत् रोचनाकासीसतुत्थकचूर्णितं तैलं व्रणशोधनरोपणम् असनादिसारगोपुरीषभस्मयुक्तं वा", text: "medāja svinnasya sirāṃ vidhyet pūrvoktāḥ pralepāḥ prātaḥ prātaścāsanādisārarajo gomūtreṇa pibet evamapyaśāntau śastreṇa vidārya medo viśodhya sīvyet dāhayogyaṃ vā vasāghṛtakṣaudrānyatamena yathāvaddahet rocanākāsīsatutthakacūrṇitaṃ tailaṃ vraṇaśodhanaropaṇam asanādisāragopurīṣabhasmayuktaṃ vā" },
      { type: "verse", number: "51", sanskrit: "मुखपाकेषु सामान्यतस्त्रिफलाक्वाथो मधुमानन्ये च तिक्तकटुककषाया मुखधावनाः मृद्वीकापाठाजातीमातुलुङ्गार्जुनपत्रजीवकपल्लवानामनभ्यवहरता चर्वणम्", text: "mukhapākeṣu sāmānyatastriphalākvātho madhumānanye ca tiktakaṭukakaṣāyā mukhadhāvanāḥ mṛdvīkāpāṭhājātīmātuluṅgārjunapatrajīvakapallavānāmanabhyavaharatā carvaṇam" },
      { type: "verse", number: "52", sanskrit: "दारुहरिद्रार्धतुलां विंशतिगुणे ऽम्भसि श्रपयित्वा तं क्वाथं सगैरिकमादर्वीप्रलेपात् साधितं क्षौद्रयुक्तं घृतभाजने निदध्यात् एतन्निष्ठीवनं सर्वमुखामयनाडीघ्नम् अयमेव च पृथक्कल्पो यष्टीमधुकपटोलीनिम्बाटरूषकजातीलोध्रारिमेदत्रिफलाजम्बूखदिरत्वचाम्", text: "dāruharidrārdhatulāṃ viṃśatiguṇe 'mbhasi śrapayitvā taṃ kvāthaṃ sagairikamādarvīpralepāt sādhitaṃ kṣaudrayuktaṃ ghṛtabhājane nidadhyāt etanniṣṭhīvanaṃ sarvamukhāmayanāḍīghnam ayameva ca pṛthakkalpo yaṣṭīmadhukapaṭolīnimbāṭarūṣakajātīlodhrārimedatriphalājambūkhadiratvacām" },
      { type: "verse", number: "53", sanskrit: "यवक्षारभागाः सप्त सुवर्णगैरिकात् भागद्वयं मूर्वाकटुकातिविषामलकानामेको भागस्तत् सर्वं कुतलक्षारोदकपिष्टं गुटिकाः कृत्वा खादेन्निष्ठीवेच्च", text: "yavakṣārabhāgāḥ sapta suvarṇagairikāt bhāgadvayaṃ mūrvākaṭukātiviṣāmalakānāmeko bhāgastat sarvaṃ kutalakṣārodakapiṣṭaṃ guṭikāḥ kṛtvā khādenniṣṭhīvecca" },
      { type: "verse", number: "54", sanskrit: "खदिरसारतुलामरिमेदतुलाद्वयं च तोयवहे ऽष्टभागावशेषं क्वाथयेदवतारितं परिस्रुतं च पुनराघनीभावात् घनीभूते शीते च कार्षिकाणि श्लक्ष्णीकृतानि प्रक्षिपेच्चन्दनपद्मकोशीरवालकमञ्जिष्ठाधातकीमुस्तप्रपौण्डरीकमधुकत्रिफलाचातुर्जातकलाक्षानलदतार्क्ष्यशैललोध्रद्विरजनीसमङ्गापाठाकट्फलैलेयपतङ्गागरुगैरिकाञ्जनानि पालिकांश्च जातीफललवङ्गकङ्कोलकेबुकान् कर्प्पूरार्द्धकुडवं च ता गुटिका वदनस्थाः सर्वान् मुखरोगान् जयन्ति सौरभं सौमनस्यं रुचिं च जनयन्ति", text: "khadirasāratulāmarimedatulādvayaṃ ca toyavahe 'ṣṭabhāgāvaśeṣaṃ kvāthayedavatāritaṃ parisrutaṃ ca punarāghanībhāvāt ghanībhūte śīte ca kārṣikāṇi ślakṣṇīkṛtāni prakṣipeccandanapadmakośīravālakamañjiṣṭhādhātakīmustaprapauṇḍarīkamadhukatriphalācāturjātakalākṣānaladatārkṣyaśailalodhradvirajanīsamaṅgāpāṭhākaṭphalaileyapataṅgāgarugairikāñjanāni pālikāṃśca jātīphalalavaṅgakaṅkolakebukān karppūrārddhakuḍavaṃ ca tā guṭikā vadanasthāḥ sarvān mukharogān jayanti saurabhaṃ saumanasyaṃ ruciṃ ca janayanti" },
      { type: "verse", number: "55", sanskrit: "एषामेव च कल्ककषायैस्तैलं साधितं कवले नियुञ्ज्यात्", text: "eṣāmeva ca kalkakaṣāyaistailaṃ sādhitaṃ kavale niyuñjyāt" },
      { type: "verse", number: "56", sanskrit: "तत्र वातजे मुखपाके दशमूलकाकोलीरास्नामधुकसारिवाक्वाथेन कुष्ठकल्केन च सिद्धं तैलं नस्यं गण्डूषश्च स्नैहिको धूमः पिप्पल्येलालवणोत्तमैः प्रतिसारयेत्", text: "tatra vātaje mukhapāke daśamūlakākolīrāsnāmadhukasārivākvāthena kuṣṭhakalkena ca siddhaṃ tailaṃ nasyaṃ gaṇḍūṣaśca snaihiko dhūmaḥ pippalyelālavaṇottamaiḥ pratisārayet" },
      { type: "verse", number: "57", sanskrit: "पैत्तिके क्षीरेक्षुरसद्राक्षाशर्करोदकैर्गण्डूषः मधुरद्रव्यसिद्धं पयः पानं कवलो नस्यं च पद्मकसमङ्गामञ्जिष्ठालोध्रधातकीविपक्वः सर्पिर्मण्डो नावनम् मदयन्तिकापतैर्निष्ठीवनं च", text: "paittike kṣīrekṣurasadrākṣāśarkarodakairgaṇḍūṣaḥ madhuradravyasiddhaṃ payaḥ pānaṃ kavalo nasyaṃ ca padmakasamaṅgāmañjiṣṭhālodhradhātakīvipakvaḥ sarpirmaṇḍo nāvanam madayantikāpatairniṣṭhīvanaṃ ca" },
      { type: "verse", number: "58", sanskrit: "कफजे कटुकक्षारलवणैः प्रतिसारणम् स्थिरासु तु पिटकासु प्राक्शाकादिपत्रेण लेखनम् मुष्ककपलाशामलकीक्षारगोमूत्रैर्गण्डूषः तद्विपक्वं च तैलम् निर्गुण्डीफणिज्जकार्जकसुरसपत्रैर्निष्टीवनम् देवदारुपाठातिविषादन्तीन्द्रयवकटुकागोमूत्रेण कल्कताः क्वथिता वा पीताः सर्वकफामयान् निघ्नन्ति", text: "kaphaje kaṭukakṣāralavaṇaiḥ pratisāraṇam sthirāsu tu piṭakāsu prākśākādipatreṇa lekhanam muṣkakapalāśāmalakīkṣāragomūtrairgaṇḍūṣaḥ tadvipakvaṃ ca tailam nirguṇḍīphaṇijjakārjakasurasapatrairniṣṭīvanam devadārupāṭhātiviṣādantīndrayavakaṭukāgomūtreṇa kalkatāḥ kvathitā vā pītāḥ sarvakaphāmayān nighnanti" },
      { type: "verse", number: "59", sanskrit: "रक्तजे पित्तवत् सिद्धिः सर्वजे यथादोषोदयम् रोचनाकासीससौराष्ट्रिकारसाञ्जनानि मोचरसो मधु चैकतो विपक्वं लोहभाजनस्थं कल्कं विशुष्कं चुर्णीकृतं मधुना व्रणलेपं कुर्यात्", text: "raktaje pittavat siddhiḥ sarvaje yathādoṣodayam rocanākāsīsasaurāṣṭrikārasāñjanāni mocaraso madhu caikato vipakvaṃ lohabhājanasthaṃ kalkaṃ viśuṣkaṃ curṇīkṛtaṃ madhunā vraṇalepaṃ kuryāt" },
      { type: "verse", number: "60", sanskrit: "अथ सर्वसरमर्बुदमचिरोत्थितमवृद्धं मण्डलाग्रेण छित्वा मुष्ककभस्मना मधुमिश्रेण प्रतिसारयेत् स्वर्जिकाशुण्ठीचूर्णेन वा मधुतैलं निम्बगुडूचीक्वाथश्च गण्डूषः यवान्नभोजी तीक्ष्णानि कवलाभ्यङ्गनस्यान्याचरेत्", text: "atha sarvasaramarbudamacirotthitamavṛddhaṃ maṇḍalāgreṇa chitvā muṣkakabhasmanā madhumiśreṇa pratisārayet svarjikāśuṇṭhīcūrṇena vā madhutailaṃ nimbaguḍūcīkvāthaśca gaṇḍūṣaḥ yavānnabhojī tīkṣṇāni kavalābhyaṅganasyānyācaret" },
      { type: "verse", number: "61", sanskrit: "पूतिमुखं स्निग्धस्विन्नं वामयित्वा शिरोविरेकैरुपाचरेत् ततः स्वर्जिकाहिङ्गुगृहधूममनश्शिलैलाशुण्ठीविडङ्गतेजोवतीभिर्गुटिकाः कृत्वा मधुद्रुता मुखपरिशोधनार्थं दद्यात् समङ्गाधातकीपद्मलोध्रप्रियङ्गुचूर्णैः सलिलमवचूर्णितं मुखधावनम् शीतादोपकुशोक्तं च कुर्यात् नस्यधूमकवलांश्च शीलयेत् भवति चात्र", text: "pūtimukhaṃ snigdhasvinnaṃ vāmayitvā śirovirekairupācaret tataḥ svarjikāhiṅgugṛhadhūmamanaśśilailāśuṇṭhīviḍaṅgatejovatībhirguṭikāḥ kṛtvā madhudrutā mukhapariśodhanārthaṃ dadyāt samaṅgādhātakīpadmalodhrapriyaṅgucūrṇaiḥ salilamavacūrṇitaṃ mukhadhāvanam śītādopakuśoktaṃ ca kuryāt nasyadhūmakavalāṃśca śīlayet bhavati cātra" },
      { type: "verse", number: "62", sanskrit: "मुखदन्तमूलगलजाः प्रायो रोगाः कफास्रभूयिष्ठाः तस्मात्तेषामसकृद्रुधिरं विस्रावयेद्दुष्टम्", text: "mukhadantamūlagalajāḥ prāyo rogāḥ kaphāsrabhūyiṣṭhāḥ tasmātteṣāmasakṛdrudhiraṃ visrāvayedduṣṭam" },
      { type: "verse", number: "63", sanskrit: "कायशिरसोर्विरेको वमनं कवलग्रहाः कटुकतिक्ताः प्रायः शस्तं तेषां कफरक्तहरं तथा कर्म", text: "kāyaśirasorvireko vamanaṃ kavalagrahāḥ kaṭukatiktāḥ prāyaḥ śastaṃ teṣāṃ kapharaktaharaṃ tathā karma" },
      { type: "verse", number: "64", sanskrit: "यवतृणधान्यं भक्तं विदलैःक्षारोषितैरपस्नेहाः यूषा भक्ष्याश्च हिता यच्चान्यच्छ्लेष्मनाशाय", text: "yavatṛṇadhānyaṃ bhaktaṃ vidalaiḥkṣāroṣitairapasnehāḥ yūṣā bhakṣyāśca hitā yaccānyacchleṣmanāśāya" },
      { type: "verse", number: "65", sanskrit: "प्राणानिलपथसंस्थाः श्वसितमपि निरुन्धते प्रमादवतः कण्ठामयाश्चिकित्सितमतो द्रुतं तेषु कुर्वीत", text: "prāṇānilapathasaṃsthāḥ śvasitamapi nirundhate pramādavataḥ kaṇṭhāmayāścikitsitamato drutaṃ teṣu kurvīta" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 27,
    lang: "sa",
    content: [
      { type: "heading", heading: "Бала рога чикитса — лечение детских болезней" },
      { type: "text", text: "Глава 27 Уттара стханы — «Бала рога чикитса» — посвящена специализированному разделу: лечение детских болезней. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः शिरोरोगविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ śirorogavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "धूमातपतुषाराम्बुक्रीडातिस्वप्नजागरैः उत्स्वेदाधिपुरोवातबाष्पनिग्रहरोदनैः", text: "dhūmātapatuṣārāmbukrīḍātisvapnajāgaraiḥ utsvedādhipurovātabāṣpanigraharodanaiḥ" },
      { type: "verse", number: "3", sanskrit: "अत्यम्बुमद्यपानेन कृमिभिर्वेगधारणैः उपधानमृजाभ्यङ्गद्वेषाधः प्रततेक्षणैः", text: "atyambumadyapānena kṛmibhirvegadhāraṇaiḥ upadhānamṛjābhyaṅgadveṣādhaḥ pratatekṣaṇaiḥ" },
      { type: "verse", number: "4", sanskrit: "असात्म्यगन्धदुष्टामभाष्याद्यैश्च शिरोगताः जनयन्त्यामयान् दोषाः #", text: "asātmyagandhaduṣṭāmabhāṣyādyaiśca śirogatāḥ janayantyāmayān doṣāḥ #" },
      { type: "verse", number: "5", sanskrit: "तत्र मारुतकोपतः निस्तुद्येते भृशं शङ्खौ घाटा सम्भिद्यते तथा भ्रुवोर्मध्यं ललाटं च पततीवातिवेदनम्", text: "tatra mārutakopataḥ nistudyete bhṛśaṃ śaṅkhau ghāṭā sambhidyate tathā bhruvormadhyaṃ lalāṭaṃ ca patatīvātivedanam" },
      { type: "verse", number: "6", sanskrit: "बाध्येते स्वनतः श्रोत्रे निष्कृष्येत इवाक्षिणी घूर्णतीव शिरः सर्वं सन्धिभ्य इव मुच्यते", text: "bādhyete svanataḥ śrotre niṣkṛṣyeta ivākṣiṇī ghūrṇatīva śiraḥ sarvaṃ sandhibhya iva mucyate" },
      { type: "verse", number: "7", sanskrit: "स्फुरत्यति सिराजालं कन्धराहनुसङ्ग्रहः प्रकाशासहता घ्राणस्रावो ऽकस्माद्व्यथाशमौ", text: "sphuratyati sirājālaṃ kandharāhanusaṅgrahaḥ prakāśāsahatā ghrāṇasrāvo 'kasmādvyathāśamau" },
      { type: "verse", number: "8", sanskrit: "मार्दवं मर्दनस्नेहस्वेदबन्धैश्च जायते शिरस्तापो ऽयम् #", text: "mārdavaṃ mardanasnehasvedabandhaiśca jāyate śirastāpo 'yam #" },
      { type: "verse", number: "9", sanskrit: "अर्धे तु मूर्ध्नः सो ऽर्धावभेदकः पक्षात् कुप्यति मासाद्वा स्वयमेवोपशाम्यति अतिवृद्धस्तु नयनं श्रवणं वा विनाशयेत्", text: "ardhe tu mūrdhnaḥ so 'rdhāvabhedakaḥ pakṣāt kupyati māsādvā svayamevopaśāmyati ativṛddhastu nayanaṃ śravaṇaṃ vā vināśayet" },
      { type: "verse", number: "10", sanskrit: "शिरोभितापे पित्तोत्थे शिरोधूमायनं ज्वरः स्वेदो ऽक्षिदहनं मूर्च्छा निशि शीतैश्च मार्दवम्", text: "śirobhitāpe pittotthe śirodhūmāyanaṃ jvaraḥ svedo 'kṣidahanaṃ mūrcchā niśi śītaiśca mārdavam" },
      { type: "verse", number: "11", sanskrit: "अरुचिः कफजे मूर्ध्नो गुरुस्तिमितशीतता सिरानिष्पन्दतालस्यं रुङ्मन्दाह्न्यधिका निशि तन्द्रा शूनाक्षिकूटत्वं कर्णकण्डूयनं वमिः", text: "aruciḥ kaphaje mūrdhno gurustimitaśītatā sirāniṣpandatālasyaṃ ruṅmandāhnyadhikā niśi tandrā śūnākṣikūṭatvaṃ karṇakaṇḍūyanaṃ vamiḥ" },
      { type: "verse", number: "12", sanskrit: "रक्तात्पित्ताधिकरुजः सर्वैः स्यात् सर्वलक्षणः सङ्कीर्णैर्भोजनैर्मूर्ध्नि क्लेदिते रुधिरामिषे कोपिते सन्निपाते च जायन्ते मूर्ध्नि जन्तवः", text: "raktātpittādhikarujaḥ sarvaiḥ syāt sarvalakṣaṇaḥ saṅkīrṇairbhojanairmūrdhni kledite rudhirāmiṣe kopite sannipāte ca jāyante mūrdhni jantavaḥ" },
      { type: "verse", number: "13", sanskrit: "शिरसस्ते पिबन्तो ऽस्रं घोराः कुर्वन्ति वेदनाः चित्तविभ्रंशजननीर्ज्वरः कासो बलक्षयः", text: "śirasaste pibanto 'sraṃ ghorāḥ kurvanti vedanāḥ cittavibhraṃśajananīrjvaraḥ kāso balakṣayaḥ" },
      { type: "verse", number: "14", sanskrit: "रौक्ष्यशोफव्यथच्छेददाहस्फुरणपूतिताः कपाले तालुशिरसोः कण्डूः शोफः प्रमीलकः ताम्राच्छसिङ्घाणकता कर्णनादश्च जन्तुजे", text: "raukṣyaśophavyathacchedadāhasphuraṇapūtitāḥ kapāle tāluśirasoḥ kaṇḍūḥ śophaḥ pramīlakaḥ tāmrācchasiṅghāṇakatā karṇanādaśca jantuje" },
      { type: "verse", number: "15", sanskrit: "वातोल्बणाः शिरःकम्पं तत्संज्ञं कुर्वते मलाः", text: "vātolbaṇāḥ śiraḥkampaṃ tatsaṃjñaṃ kurvate malāḥ" },
      { type: "verse", number: "16", sanskrit: "पित्तप्रधानैर्वाताद्यैः शङ्खे शोफः सशोणितैः तीव्रदाहरुजारागप्रलापज्वरतृङ्भ्रमाः", text: "pittapradhānairvātādyaiḥ śaṅkhe śophaḥ saśoṇitaiḥ tīvradāharujārāgapralāpajvaratṛṅbhramāḥ" },
      { type: "verse", number: "17", sanskrit: "तिक्तास्यः पीतवदनः क्षिप्रकारी स शङ्खकः त्रिरात्राज्जीवितं हन्ति सिध्यत्यप्याशु साधितः", text: "tiktāsyaḥ pītavadanaḥ kṣiprakārī sa śaṅkhakaḥ trirātrājjīvitaṃ hanti sidhyatyapyāśu sādhitaḥ" },
      { type: "verse", number: "18", sanskrit: "पित्तानुबन्धः शङ्खाक्षिभ्रूललाटेषु मारुतः रुजां सस्पन्दनां कुर्यादनुसूर्योदयोदयाम्", text: "pittānubandhaḥ śaṅkhākṣibhrūlalāṭeṣu mārutaḥ rujāṃ saspandanāṃ kuryādanusūryodayodayām" },
      { type: "verse", number: "19", sanskrit: "आमाध्याह्नं विवर्द्धिष्णुः क्षुद्वतः सा विशेषतः अव्यवस्थितशीतोष्णसुखा शाम्यत्यतः प्रम सूर्यावर्तः सः #", text: "āmādhyāhnaṃ vivarddhiṣṇuḥ kṣudvataḥ sā viśeṣataḥ avyavasthitaśītoṣṇasukhā śāmyatyataḥ prama sūryāvartaḥ saḥ #" },
      { type: "verse", number: "20", sanskrit: "इत्युक्ता दश रोगाः शिरोगताः", text: "ityuktā daśa rogāḥ śirogatāḥ" },
      { type: "verse", number: "21", sanskrit: "शिरस्येव च वक्ष्यन्ते कपाले व्याधयो नव", text: "śirasyeva ca vakṣyante kapāle vyādhayo nava" },
      { type: "verse", number: "22", sanskrit: "कपाले पवने दुष्टे गर्भस्थस्यापि जायते सवर्णो नीरुजः शोफस्तं विद्यादुपशीर्षकम्", text: "kapāle pavane duṣṭe garbhasthasyāpi jāyate savarṇo nīrujaḥ śophastaṃ vidyādupaśīrṣakam" },
      { type: "verse", number: "23", sanskrit: "यथादोषोदयं ब्रूयात् पिटकार्बुदविद्रधीन्", text: "yathādoṣodayaṃ brūyāt piṭakārbudavidradhīn" },
      { type: "verse", number: "24", sanskrit: "कपाले क्लेदबहुलाः पित्तासृक्श्लेष्मजन्तुभिः कङ्गुसिद्धार्थकनिभाः पिटकाः स्युररूंषिकाः", text: "kapāle kledabahulāḥ pittāsṛkśleṣmajantubhiḥ kaṅgusiddhārthakanibhāḥ piṭakāḥ syurarūṃṣikāḥ" },
      { type: "verse", number: "25", sanskrit: "कण्डूकेशच्युतिस्वापरौक्ष्यकृत् स्फुटनं त्वचः सुसूक्ष्मं कफवाताभ्यां विद्याद्दारणकं तु तत्", text: "kaṇḍūkeśacyutisvāparaukṣyakṛt sphuṭanaṃ tvacaḥ susūkṣmaṃ kaphavātābhyāṃ vidyāddāraṇakaṃ tu tat" },
      { type: "verse", number: "26", sanskrit: "रोमकूपानुगं पित्तं वातेन सह मूर्च्छितम् प्रच्यावयति रोमाणि ततः श्लेष्मा सशोणितः", text: "romakūpānugaṃ pittaṃ vātena saha mūrcchitam pracyāvayati romāṇi tataḥ śleṣmā saśoṇitaḥ" },
      { type: "verse", number: "27", sanskrit: "रोमकूपान् रुणध्द्यस्य तेनान्येषामसम्भवः तदिन्द्रलुप्तं रुज्जा च प्राहुश्चाचेति चापरे", text: "romakūpān ruṇadhdyasya tenānyeṣāmasambhavaḥ tadindraluptaṃ rujjā ca prāhuścāceti cāpare" },
      { type: "verse", number: "28", sanskrit: "खलतेरपि जन्मैवं शातनं तत्र तु क्रमात्", text: "khalaterapi janmaivaṃ śātanaṃ tatra tu kramāt" },
      { type: "verse", number: "29", sanskrit: "सा वातादग्निदग्धाभा पित्तात्स्वेदसिरावृता कफात् घनत्वग्वर्णांश्च यथास्वं निर्दिशेत्त्वचि", text: "sā vātādagnidagdhābhā pittātsvedasirāvṛtā kaphāt ghanatvagvarṇāṃśca yathāsvaṃ nirdiśettvaci" },
      { type: "verse", number: "30", sanskrit: "दोषैः सर्वाकृतिः सर्वैरसाध्या सा नखप्रभा दग्धाग्निनेव निर्लोमा सदाहा या च जायते", text: "doṣaiḥ sarvākṛtiḥ sarvairasādhyā sā nakhaprabhā dagdhāgnineva nirlomā sadāhā yā ca jāyate" },
      { type: "verse", number: "31", sanskrit: "शोकश्रमक्रोधकृतः शरीरोष्मा शिरोगतः केशान् सदोषः पचति पालितं सम्भवत्यतः", text: "śokaśramakrodhakṛtaḥ śarīroṣmā śirogataḥ keśān sadoṣaḥ pacati pālitaṃ sambhavatyataḥ" },
      { type: "verse", number: "32", sanskrit: "तद्वातात् स्फुटितं श्यावं खरं रूक्षं ज्वलत्प्रभम् पित्तात् सदाहं पीताभं कफात्स्निग्धं विवृद्धिमत्", text: "tadvātāt sphuṭitaṃ śyāvaṃ kharaṃ rūkṣaṃ jvalatprabham pittāt sadāhaṃ pītābhaṃ kaphātsnigdhaṃ vivṛddhimat" },
      { type: "verse", number: "33", sanskrit: "स्थूलं सुशुक्लं सर्वेस्तु विद्याद्व्यामिश्रलक्षणम् शिरोरुजोद्भवं चान्यद्विवर्णं स्पर्शनासहम्", text: "sthūlaṃ suśuklaṃ sarvestu vidyādvyāmiśralakṣaṇam śirorujodbhavaṃ cānyadvivarṇaṃ sparśanāsaham" },
      { type: "verse", number: "34", sanskrit: "असाध्या सन्निपातेन खलतिः पलितानि च शरीरपरिणामोत्थान्यपेक्षन्ते रसायनम्", text: "asādhyā sannipātena khalatiḥ palitāni ca śarīrapariṇāmotthānyapekṣante rasāyanam" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 28,
    lang: "sa",
    content: [
      { type: "heading", heading: "Кшира дай видхи — правила кормления детей" },
      { type: "text", text: "Глава 28 Уттара стханы — «Кшира дай видхи» — посвящена специализированному разделу: правила кормления детей. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः शिरोरोगप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ śirorogapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "वातजे शिरोभितापे वातव्याधिविहितं कुर्यात् निवातस्थं च नक्तमभ्यक्तशिरसं सर्पिः पयोनुपानं तैलं वा पाययेत् माषान् वा ससर्पिष्कानुष्णपयोनुपानान् भक्षयेत् तद्वद्वा मुद्गान्", text: "vātaje śirobhitāpe vātavyādhivihitaṃ kuryāt nivātasthaṃ ca naktamabhyaktaśirasaṃ sarpiḥ payonupānaṃ tailaṃ vā pāyayet māṣān vā sasarpiṣkānuṣṇapayonupānān bhakṣayet tadvadvā mudgān" },
      { type: "verse", number: "3", sanskrit: "आनूपपिशितवेशवारेण यवतिलमुद्गमाषकुलत्थकुष्ठदारुहरिद्रातसीसैन्धवर्वा महास्नेहवतीमुत्कारिकां दत्वा शिरो वेष्टयेत् ततः प्रत्यूषे दशमूलसिद्धेन पयसा कवोष्णेन परिषेकं कुर्यात् तत्सिद्धैश्च पायसैः पिण्डस्वेदं लेपं वा", text: "ānūpapiśitaveśavāreṇa yavatilamudgamāṣakulatthakuṣṭhadāruharidrātasīsaindhavarvā mahāsnehavatīmutkārikāṃ datvā śiro veṣṭayet tataḥ pratyūṣe daśamūlasiddhena payasā kavoṣṇena pariṣekaṃ kuryāt tatsiddhaiśca pāyasaiḥ piṇḍasvedaṃ lepaṃ vā" },
      { type: "verse", number: "4", sanskrit: "कूर्ममहिषवराहकुक्कुटशल्लकीनां वसा ससैन्धवा नस्यं शिरःकर्णपूरणं च तथैव च पञ्चमूलबलासारिवाद्वयक्वाथे मधुकजीवकर्षभकपुनर्नवगर्भं सपयः सर्पिस्तैलं चैकतो विपक्वम्", text: "kūrmamahiṣavarāhakukkuṭaśallakīnāṃ vasā sasaindhavā nasyaṃ śiraḥkarṇapūraṇaṃ ca tathaiva ca pañcamūlabalāsārivādvayakvāthe madhukajīvakarṣabhakapunarnavagarbhaṃ sapayaḥ sarpistailaṃ caikato vipakvam" },
      { type: "verse", number: "5", sanskrit: "कार्पासमज्जत्वङ्मुस्तासुमनःकोरकाण्युष्णाम्बुपिष्टानि नावनं सर्वशिरोरुजाघ्नम् तद्वत् त्वक्पत्रशर्कराशिग्रुकरञ्जबीजानि तथा चन्दनोत्पलतगरकुष्ठैः सघृतैर्लेपः देवदारुकुष्ठचोरकयष्टीमधुककमलनीलोत्पलैलाप्रपौण्डरीकैश्च", text: "kārpāsamajjatvaṅmustāsumanaḥkorakāṇyuṣṇāmbupiṣṭāni nāvanaṃ sarvaśirorujāghnam tadvat tvakpatraśarkarāśigrukarañjabījāni tathā candanotpalatagarakuṣṭhaiḥ saghṛtairlepaḥ devadārukuṣṭhacorakayaṣṭīmadhukakamalanīlotpalailāprapauṇḍarīkaiśca" },
      { type: "verse", number: "6", sanskrit: "कुङ्कुमशर्करासंस्कृतमाज्यं रक्तपित्तानुबन्धे मर्शः न चात्र रक्तमवसेचयेद्वातोद्रेकभयात् स्नैहिकं धूमं पिबेत् शिरोबस्तिं च शीलयेत् बस्तिकर्म चाचरेत्", text: "kuṅkumaśarkarāsaṃskṛtamājyaṃ raktapittānubandhe marśaḥ na cātra raktamavasecayedvātodrekabhayāt snaihikaṃ dhūmaṃ pibet śirobastiṃ ca śīlayet bastikarma cācaret" },
      { type: "verse", number: "7", sanskrit: "एवमसिद्धौ वातजे श्लेष्मजे च यथोक्तो दाहः", text: "evamasiddhau vātaje śleṣmaje ca yathokto dāhaḥ" },
      { type: "verse", number: "8", sanskrit: "अर्धावभेदकेप्ययमेव विधिः निर्गुण्डीपत्ररसश्च सघृतमण्डसैन्धवो नस्यम् शिरीषमूलफलानि वा सारिवोत्पलकुष्ठवचामधुकपिप्पलीभिः सतैलाम्लो लेपः अशाम्यति दोषानुबन्धमवेक्ष्य प्रतिकुर्वीत", text: "ardhāvabhedakepyayameva vidhiḥ nirguṇḍīpatrarasaśca saghṛtamaṇḍasaindhavo nasyam śirīṣamūlaphalāni vā sārivotpalakuṣṭhavacāmadhukapippalībhiḥ satailāmlo lepaḥ aśāmyati doṣānubandhamavekṣya pratikurvīta" },
      { type: "verse", number: "9", sanskrit: "सूर्यावर्तेत्वयमेव विधिः विशेषतस्तु सिरामोक्षः", text: "sūryāvartetvayameva vidhiḥ viśeṣatastu sirāmokṣaḥ" },
      { type: "verse", number: "10", sanskrit: "पित्तजे रक्तजे च शिरोभितापे स्निग्धस्य सिरां विध्येत् कायं च विरेचयेत् सुशीतैः शतधौतघृतान्वितैः शिरो वक्त्रं सिञ्चेत् प्रदिह्याच्च", text: "pittaje raktaje ca śirobhitāpe snigdhasya sirāṃ vidhyet kāyaṃ ca virecayet suśītaiḥ śatadhautaghṛtānvitaiḥ śiro vaktraṃ siñcet pradihyācca" },
      { type: "verse", number: "11", sanskrit: "चन्दनसारिवामधुकदूर्वोत्पलप्रपौण्डरीकमञ्जिष्ठाविदारीभिः सक्षीरं सर्पिर्विपाचितं नावनं शिरोबस्तिश्च जीवनीयविपक्वात् पयसो नवनीतमुद्धृत्य जीवनीयक्वाथकल्काभ्यां पाचितं पानभोजननस्याभ्यङ्गबस्तिषु प्रणीतं पित्तरक्तजान् सर्वान्विकारान् साधयति जीवनीयगर्भं षोडशगुणे पयसि सिद्धमाज्यं वा", text: "candanasārivāmadhukadūrvotpalaprapauṇḍarīkamañjiṣṭhāvidārībhiḥ sakṣīraṃ sarpirvipācitaṃ nāvanaṃ śirobastiśca jīvanīyavipakvāt payaso navanītamuddhṛtya jīvanīyakvāthakalkābhyāṃ pācitaṃ pānabhojananasyābhyaṅgabastiṣu praṇītaṃ pittaraktajān sarvānvikārān sādhayati jīvanīyagarbhaṃ ṣoḍaśaguṇe payasi siddhamājyaṃ vā" },
      { type: "verse", number: "12", sanskrit: "क्षीरेक्षुजाङ्गलरसखर्जूरद्राक्षाकशेरुकमृणालसिद्धः सर्पिर्मण्डो ऽनुवासनम् अञ्जनादिवर्गशृतं क्षीरमास्थापनम्", text: "kṣīrekṣujāṅgalarasakharjūradrākṣākaśerukamṛṇālasiddhaḥ sarpirmaṇḍo 'nuvāsanam añjanādivargaśṛtaṃ kṣīramāsthāpanam" },
      { type: "verse", number: "13", sanskrit: "शङ्खकं प्रत्याख्यायैवमेवोपचरेत् विसर्पवच्च विशेषतस्तु कृष्णतिलशतावरीनीलोत्पलमूर्वापुनर्नवैर्लेपः", text: "śaṅkhakaṃ pratyākhyāyaivamevopacaret visarpavacca viśeṣatastu kṛṣṇatilaśatāvarīnīlotpalamūrvāpunarnavairlepaḥ" },
      { type: "verse", number: "14", sanskrit: "कफजे शिरोभितापे लङ्घयेत् पुराणसर्पिस्निग्धं वा वामयेत् स्वेदः पिण्डेन रूक्षेण शिग्रुनिम्बैरण्डक्वाथेन वा नाडीस्वेदः", text: "kaphaje śirobhitāpe laṅghayet purāṇasarpisnigdhaṃ vā vāmayet svedaḥ piṇḍena rūkṣeṇa śigrunimbairaṇḍakvāthena vā nāḍīsvedaḥ" },
      { type: "verse", number: "15", sanskrit: "देवकाष्ठकुष्ठशार्ङ्गेष्टासरलरोहिषैः सलवणैः सुखोष्णैरालेपः यवचूर्णमधुकचन्दनहरिद्राकुष्ठप्रियङ्गुशतपुष्पासुरदारुभिस्तैलाजक्षीरयुक्तैः ससैन्धवैरुपनाहः", text: "devakāṣṭhakuṣṭhaśārṅgeṣṭāsaralarohiṣaiḥ salavaṇaiḥ sukhoṣṇairālepaḥ yavacūrṇamadhukacandanaharidrākuṣṭhapriyaṅguśatapuṣpāsuradārubhistailājakṣīrayuktaiḥ sasaindhavairupanāhaḥ" },
      { type: "verse", number: "16", sanskrit: "विडङ्गतैलं नस्यं सार्षपं वा तदेव वा व्योषसिद्धम् मधूकसारकल्को वा मधुयुतस्त्वग्वा मेषशृङ्ग्या इङ्गुदस्य वा एभिरेव च धूमवर्तिः", text: "viḍaṅgatailaṃ nasyaṃ sārṣapaṃ vā tadeva vā vyoṣasiddham madhūkasārakalko vā madhuyutastvagvā meṣaśṛṅgyā iṅgudasya vā ebhireva ca dhūmavartiḥ" },
      { type: "verse", number: "17", sanskrit: "शिरोविरेचनद्रव्यैर्वा सूत्रस्थानौक्तैः प्रधमनम् तैरेव च पक्वं तैलं मर्शः प्रतिमर्शो वा", text: "śirovirecanadravyairvā sūtrasthānauktaiḥ pradhamanam taireva ca pakvaṃ tailaṃ marśaḥ pratimarśo vā" },
      { type: "verse", number: "18", sanskrit: "शिरोविरेचनान्ते कर्णनादोक्तं स्नेहनस्यम् तीक्ष्णाः कवलाः मनश्शिलानलदतुत्थकासीसचूर्णः ससर्पिष्को धूमः नलदचूर्णस्य च मुहुर्मुहुराघ्राणनम्", text: "śirovirecanānte karṇanādoktaṃ snehanasyam tīkṣṇāḥ kavalāḥ manaśśilānaladatutthakāsīsacūrṇaḥ sasarpiṣko dhūmaḥ naladacūrṇasya ca muhurmuhurāghrāṇanam" },
      { type: "verse", number: "19", sanskrit: "सन्निपाते व्यामिश्रो विधिः", text: "sannipāte vyāmiśro vidhiḥ" },
      { type: "verse", number: "20", sanskrit: "कृमिजे दुरालभासुरदारुरोहिषपूतीकत्रिफलाकट्फलवचात्रिकटुकैरजामूत्र्युक्तं सर्पिः पक्वं पानम् उपस्निग्धस्विन्नस्य देवदारुपूतीककटभीसर्षपविडङ्गतिलकण्टकविपक्वेन तैलेन शिरः कर्णौ चाभ्यज्य स्वेदयेत्", text: "kṛmije durālabhāsuradārurohiṣapūtīkatriphalākaṭphalavacātrikaṭukairajāmūtryuktaṃ sarpiḥ pakvaṃ pānam upasnigdhasvinnasya devadārupūtīkakaṭabhīsarṣapaviḍaṅgatilakaṇṭakavipakvena tailena śiraḥ karṇau cābhyajya svedayet" },
      { type: "verse", number: "21", sanskrit: "ततः कृमिमूर्च्छनार्थमसृङ्नस्तोवसेचयेत् ततो रुधिरगन्धमदेन प्राविसृताः सप्तच्छदस्य त्वग्रसेन पुष्परसेन वानन्तरनिषिक्तेन कृमयः पतन्ति", text: "tataḥ kṛmimūrcchanārthamasṛṅnastovasecayet tato rudhiragandhamadena prāvisṛtāḥ saptacchadasya tvagrasena puṣparasena vānantaraniṣiktena kṛmayaḥ patanti" },
      { type: "verse", number: "22", sanskrit: "सरलदेवदारुकट्फलसर्षपापामार्गक्षवककटुकालाबुसुरसबीजपिप्पलीतण्डुलचूर्णंस्तत्पक्वं वा तैलं सद्यः कृमीन् निरस्यति विडङ्गतण्डुला वाजिमूत्रपिष्टाः शिरीषबीजानि वा छागमूत्रपिष्टानि पुष्करमध्यबीजानि वा", text: "saraladevadārukaṭphalasarṣapāpāmārgakṣavakakaṭukālābusurasabījapippalītaṇḍulacūrṇaṃstatpakvaṃ vā tailaṃ sadyaḥ kṛmīn nirasyati viḍaṅgataṇḍulā vājimūtrapiṣṭāḥ śirīṣabījāni vā chāgamūtrapiṣṭāni puṣkaramadhyabījāni vā" },
      { type: "verse", number: "23", sanskrit: "गोमांसेन छागमांसेन वा वसापिष्टेन यवागूं कृत्वा शिरो विलेपयेत् ततो निम्बार्कवंशसुरसकुटजकरञ्जकरवीरपत्रक्वाथेन सेचयेत् अजामूत्रेण वा कवोष्णेन पूतिमत्स्ययुताश्च धूमाः", text: "gomāṃsena chāgamāṃsena vā vasāpiṣṭena yavāgūṃ kṛtvā śiro vilepayet tato nimbārkavaṃśasurasakuṭajakarañjakaravīrapatrakvāthena secayet ajāmūtreṇa vā kavoṣṇena pūtimatsyayutāśca dhūmāḥ" },
      { type: "verse", number: "24", sanskrit: "एवं कृमिष्वपगतेषु तेजोवतीपूतीकबिम्बीसुरसनक्तमालविडङ्गहरीतकीसर्षपार्ककरवीरमूलमालतीदेवदारुक्षवकमुस्तफणिज्जकपिप्पलीशतपुष्पामधूकशणनिम्बसारकल्कैरजामूत्रयुतैः सार्षपं तैलमैङ्गुदं पैलुकं वा विपक्वं युक्त्या नावनम्", text: "evaṃ kṛmiṣvapagateṣu tejovatīpūtīkabimbīsurasanaktamālaviḍaṅgaharītakīsarṣapārkakaravīramūlamālatīdevadārukṣavakamustaphaṇijjakapippalīśatapuṣpāmadhūkaśaṇanimbasārakalkairajāmūtrayutaiḥ sārṣapaṃ tailamaiṅgudaṃ pailukaṃ vā vipakvaṃ yuktyā nāvanam" },
      { type: "verse", number: "25", sanskrit: "न तु जातुरुधिरमवसेचयेत् जन्तुभिः पीतशोणिते हि शिरसि पुनरस्रावसेकादकाण्डे मृत्युः स्यात् कृमिचिकित्सितं चेक्षेत्", text: "na tu jāturudhiramavasecayet jantubhiḥ pītaśoṇite hi śirasi punarasrāvasekādakāṇḍe mṛtyuḥ syāt kṛmicikitsitaṃ cekṣet" },
      { type: "verse", number: "26", sanskrit: "शिरः कम्पमक्षीणस्यान्यव्याध्यनुपद्रुतस्य दाहवर्ज्यं मारुतविधानेनोपक्रमेत", text: "śiraḥ kampamakṣīṇasyānyavyādhyanupadrutasya dāhavarjyaṃ mārutavidhānenopakrameta" },
      { type: "verse", number: "27", sanskrit: "उपशीर्षके जन्मोत्तरकालजाते नवोत्थिते वातव्याधिविहितान् स्नेहान् पाननावनाभ्यञ्जनेषु योजयेत् अभ्यक्तं च स्वेदयित्वोपनाहयेद्यथा विदाहो न भवति विदाहे विद्रधिवत् कर्म", text: "upaśīrṣake janmottarakālajāte navotthite vātavyādhivihitān snehān pānanāvanābhyañjaneṣu yojayet abhyaktaṃ ca svedayitvopanāhayedyathā vidāho na bhavati vidāhe vidradhivat karma" },
      { type: "verse", number: "28", sanskrit: "पिटकार्बुदविद्रधिषु यथास्वमाचरेत् व्रणीभूतासु पिटकासु निम्बनिशामधुकधात्रीफलैर्विपक्वं तैलं शोधनरोपणम्", text: "piṭakārbudavidradhiṣu yathāsvamācaret vraṇībhūtāsu piṭakāsu nimbaniśāmadhukadhātrīphalairvipakvaṃ tailaṃ śodhanaropaṇam" },
      { type: "verse", number: "29", sanskrit: "मूर्वाचन्दनसारिवाधातकीकान्तालोध्रमधुकसमङ्गापद्मकेसरशतपर्वकंमूलैर्विद्रधिषु एभिरेव च सिद्धं सर्पिर्नस्यम् रूढं तु विद्रधौ यदि त्वक् सुप्तेव भवति ततो वामयेत् उपस्निग्धं च विरेचयेत्", text: "mūrvācandanasārivādhātakīkāntālodhramadhukasamaṅgāpadmakesaraśataparvakaṃmūlairvidradhiṣu ebhireva ca siddhaṃ sarpirnasyam rūḍhaṃ tu vidradhau yadi tvak supteva bhavati tato vāmayet upasnigdhaṃ ca virecayet" },
      { type: "verse", number: "30", sanskrit: "अरूंषिकासु जलौकोपहृतशोणितं शिरः क्षुरामृष्टं वा निम्बोदकेन परिषिच्याश्वशकृद्रसेन लवणप्रगाढेन लेपयेत् किञ्चित् कालं स्थितं चोष्णोदकाम्लकाञ्जिकान्यतरधौतं विडङ्गव्योषलाक्षागारधूममनोह्वालवचारसाञ्जनहरिद्राद्वयैरालिम्पेत् तिलमष्या वा स्नुहीक्षीरयुक्तया मधुकोत्पलतिलैरण्डमार्कवपत्रैर्वा शिग्रुमूलकसर्षपबीजैर्वा गोमूत्रपिष्टैः वालकामलकनागरमूलकसर्षपबीजैर्वा क्षीरपिष्टैः शिरीषत्वग्यष्टीमधुकाभ्यां वा पुराणपिण्याककुक्कुटपुरीषाभ्यां वा", text: "arūṃṣikāsu jalaukopahṛtaśoṇitaṃ śiraḥ kṣurāmṛṣṭaṃ vā nimbodakena pariṣicyāśvaśakṛdrasena lavaṇapragāḍhena lepayet kiñcit kālaṃ sthitaṃ coṣṇodakāmlakāñjikānyataradhautaṃ viḍaṅgavyoṣalākṣāgāradhūmamanohvālavacārasāñjanaharidrādvayairālimpet tilamaṣyā vā snuhīkṣīrayuktayā madhukotpalatilairaṇḍamārkavapatrairvā śigrumūlakasarṣapabījairvā gomūtrapiṣṭaiḥ vālakāmalakanāgaramūlakasarṣapabījairvā kṣīrapiṣṭaiḥ śirīṣatvagyaṣṭīmadhukābhyāṃ vā purāṇapiṇyākakukkuṭapurīṣābhyāṃ vā" },
      { type: "verse", number: "31", sanskrit: "कपालभृष्टकुष्ठचूर्णं तैलयुक्तं कण्डूक्लेददाहस्वेदवेदनाघ्नम् तथा चाचोक्तं चित्रकादितैलमभ्यञ्जनम् दन्तीपाठाकोशातकीचित्रकातिविषामहालाङ्गलकीसिद्धं तैलं व्रणाभ्यङ्गः", text: "kapālabhṛṣṭakuṣṭhacūrṇaṃ tailayuktaṃ kaṇḍūkledadāhasvedavedanāghnam tathā cācoktaṃ citrakāditailamabhyañjanam dantīpāṭhākośātakīcitrakātiviṣāmahālāṅgalakīsiddhaṃ tailaṃ vraṇābhyaṅgaḥ" },
      { type: "verse", number: "32", sanskrit: "मनश्शिलैलाहरितालपिप्पलीकुष्ठकासीसहरिद्राकरञ्जमुस्तातगरविडङ्गंचित्रकसिद्धार्थककरवीरमूलचूर्णगर्भं तैलमादित्यपाकं व्रणरोपणम् एवमनुपशमे वमनधूमकायशिरोविरेकान् कुर्यात्", text: "manaśśilailāharitālapippalīkuṣṭhakāsīsaharidrākarañjamustātagaraviḍaṅgaṃcitrakasiddhārthakakaravīramūlacūrṇagarbhaṃ tailamādityapākaṃ vraṇaropaṇam evamanupaśame vamanadhūmakāyaśirovirekān kuryāt" },
      { type: "verse", number: "33", sanskrit: "दारणके ललाटे सिरां विध्येत् अभ्यङ्गस्नाननावनानि च शीलयेत् प्रियालबीजमधुककुष्ठमाषसर्षपैः सक्षौद्रैर्लेपः कोद्रवतृणक्षाराम्भः प्रक्षालनम्", text: "dāraṇake lalāṭe sirāṃ vidhyet abhyaṅgasnānanāvanāni ca śīlayet priyālabījamadhukakuṣṭhamāṣasarṣapaiḥ sakṣaudrairlepaḥ kodravatṛṇakṣārāmbhaḥ prakṣālanam" },
      { type: "verse", number: "34", sanskrit: "इन्द्रलुप्ते यथासन्नं सिरां विध्वा तुत्थकासीसमनश्शिलामरिचैर्लेपयेत् भद्रदारुकुटन्नटाभ्यां वा चित्रककरवीरनक्तमालमालतीसिद्धेन वा तैलेनाभ्यज्यात्", text: "indralupte yathāsannaṃ sirāṃ vidhvā tutthakāsīsamanaśśilāmaricairlepayet bhadradārukuṭannaṭābhyāṃ vā citrakakaravīranaktamālamālatīsiddhena vā tailenābhyajyāt" },
      { type: "verse", number: "35", sanskrit: "अवगाढपदं वा सूचीकूर्चकेन प्रच्छाय भूयोभूयः प्रदिह्यात् कपोतपङ्कामूलेन लाङ्गीलकामूलेन वा महिषीक्षीरपिष्टेन", text: "avagāḍhapadaṃ vā sūcīkūrcakena pracchāya bhūyobhūyaḥ pradihyāt kapotapaṅkāmūlena lāṅgīlakāmūlena vā mahiṣīkṣīrapiṣṭena" },
      { type: "verse", number: "36", sanskrit: "घृष्टलिप्तमेरण्डपत्रावच्छादितं रात्रिमुषितं माहिषनवनीतेन लिम्पेत् मार्कवपत्रसहचरपुष्पपक्वं वा वार्ताकफलैस्तैलं पक्वं क्षौद्राञ्जनयुक्तमालेपः सक्षौद्रो वा क्षुद्रवार्ताकरसः जलशूलो वा पलाशक्षारसान्द्रः", text: "ghṛṣṭaliptameraṇḍapatrāvacchāditaṃ rātrimuṣitaṃ māhiṣanavanītena limpet mārkavapatrasahacarapuṣpapakvaṃ vā vārtākaphalaistailaṃ pakvaṃ kṣaudrāñjanayuktamālepaḥ sakṣaudro vā kṣudravārtākarasaḥ jalaśūlo vā palāśakṣārasāndraḥ" },
      { type: "verse", number: "37", sanskrit: "गोशकृता वा घृष्टमिन्द्रलुप्तमरुष्कररसेनावलिप्यान्तर्धूमदग्धकूर्ममष्यावचूर्णयेत् कूर्मकपालभस्मना वा सुरसारसाक्तेन प्रदिह्यात् हस्तिदन्तमष्या वा तैलान्वितया पूतीकरञ्जप्रत्राणि वा ससैन्धवानि लेपः पिप्पल्यञ्जनरसाञ्जनबाकुचिकाफललोहरजांसि वा गोमूत्रपिष्टानि खलतिविहितानि चाचरेत् सलिलसेकमारोमोद्गमात् परिहरेत्", text: "gośakṛtā vā ghṛṣṭamindraluptamaruṣkararasenāvalipyāntardhūmadagdhakūrmamaṣyāvacūrṇayet kūrmakapālabhasmanā vā surasārasāktena pradihyāt hastidantamaṣyā vā tailānvitayā pūtīkarañjapratrāṇi vā sasaindhavāni lepaḥ pippalyañjanarasāñjanabākucikāphalaloharajāṃsi vā gomūtrapiṣṭāni khalativihitāni cācaret salilasekamāromodgamāt pariharet" },
      { type: "verse", number: "38", sanskrit: "खलताविन्द्रलुप्तोक्तः क्रमो यथादोषं च संशुद्धिः", text: "khalatāvindraluptoktaḥ kramo yathādoṣaṃ ca saṃśuddhiḥ" },
      { type: "verse", number: "39", sanskrit: "त्रिफलार्जुनसैर्यकत्वक्पुष्पकृष्णपिण्डीतकफलमूलनीलोत्पललोहचूर्णकासीसजम्वूमार्कवमञ्जिष्ठामेषशृङ्गीखदिररजः सकर्दममर्दितोक्ताणुतैलयुक्तमसन सारसमुद्गके न्यस्तं कर्दमे मासं निखातं स्थितमुद्धृतं सूचीकूर्चप्रच्छितायाः खलतेर्लेपः परं रोमसञ्जननः", text: "triphalārjunasairyakatvakpuṣpakṛṣṇapiṇḍītakaphalamūlanīlotpalalohacūrṇakāsīsajamvūmārkavamañjiṣṭhāmeṣaśṛṅgīkhadirarajaḥ sakardamamarditoktāṇutailayuktamasana sārasamudgake nyastaṃ kardame māsaṃ nikhātaṃ sthitamuddhṛtaṃ sūcīkūrcapracchitāyāḥ khalaterlepaḥ paraṃ romasañjananaḥ" },
      { type: "verse", number: "40", sanskrit: "रक्ताग्निमन्थपुष्पकिंशुकनलदमूलमधुकहस्तिदन्तभस्मान्यविक्षीरपिष्टानि लेपः", text: "raktāgnimanthapuṣpakiṃśukanaladamūlamadhukahastidantabhasmānyavikṣīrapiṣṭāni lepaḥ" },
      { type: "verse", number: "41", sanskrit: "जम्बूद्वयत्वक्पत्रमधुकभृङ्गरजास्त्रिफलाश्लेष्मातकमञ्जिष्ठाफणिज्जकबलाद्राक्षाजशृङ्गीचपलातिविषाकट्फलकल्केन क्षीरिवृक्षक्काथेन च तिलतैलमक्षतैलं चैकध्यं साधयेत् तन्नस्ये ऽभ्यङ्गे च नियुञ्ज्यात् एवमेव मधुरवर्गकल्केन", text: "jambūdvayatvakpatramadhukabhṛṅgarajāstriphalāśleṣmātakamañjiṣṭhāphaṇijjakabalādrākṣājaśṛṅgīcapalātiviṣākaṭphalakalkena kṣīrivṛkṣakkāthena ca tilatailamakṣatailaṃ caikadhyaṃ sādhayet tannasye 'bhyaṅge ca niyuñjyāt evameva madhuravargakalkena" },
      { type: "verse", number: "42", sanskrit: "खलतिपलितयोश्च प्रयोगान् परस्परं विदध्यात्", text: "khalatipalitayośca prayogān parasparaṃ vidadhyāt" },
      { type: "verse", number: "43", sanskrit: "अकालपलितेषु वातादीनवेक्ष्य स्नेहस्वेदसंशो धनास्रविस्रावणानि कुर्यात् ततोस्यार्दितप्रोक्तमणुतैलं नस्यमभ्यञ्जनं च", text: "akālapaliteṣu vātādīnavekṣya snehasvedasaṃśo dhanāsravisrāvaṇāni kuryāt tatosyārditaproktamaṇutailaṃ nasyamabhyañjanaṃ ca" },
      { type: "verse", number: "44", sanskrit: "मधुकामलकमाक्षिकैः केशमूलानि लिम्पेत् तिलामलकक्षौद्रतैलैर्वा तुत्थकाम्रजम्ब्वस्थिकासीसकिट्टशर्कराभिर्वा सैर्यकपुष्पनीलिनीत्रिफलाभृङ्गरजोभिर्वा कृष्णाजमूत्रपिष्टैः", text: "madhukāmalakamākṣikaiḥ keśamūlāni limpet tilāmalakakṣaudratailairvā tutthakāmrajambvasthikāsīsakiṭṭaśarkarābhirvā sairyakapuṣpanīlinītriphalābhṛṅgarajobhirvā kṛṣṇājamūtrapiṣṭaiḥ" },
      { type: "verse", number: "45", sanskrit: "असनपुष्पपत्रमये पात्रे बहिरामलकीकल्कप्रदिग्धे निहितमक्षतैलं षण्मासं व्रीहिपल्ले स्थितमभ्यङ्गान्नावनाच्च पलितं जयति अयमेव कल्पः सैरीयकेपि", text: "asanapuṣpapatramaye pātre bahirāmalakīkalkapradigdhe nihitamakṣatailaṃ ṣaṇmāsaṃ vrīhipalle sthitamabhyaṅgānnāvanācca palitaṃ jayati ayameva kalpaḥ sairīyakepi" },
      { type: "verse", number: "46", sanskrit: "कपिकच्छूफलमूलगर्भमक्षतैलं सिद्धमयःपात्रे पूर्ववत् स्थितं समानं पूर्वेण", text: "kapikacchūphalamūlagarbhamakṣatailaṃ siddhamayaḥpātre pūrvavat sthitaṃ samānaṃ pūrveṇa" },
      { type: "verse", number: "47", sanskrit: "रामतरणीमूलपलद्वयं यष्टीमधुकपलं सारिवार्धपलमेकत्रजर्जरीकृतमक्षतैलपलैर्दशभिराप्लुतं लोहभाजने दशाहं दिवसकरकरप्रतप्तं नावनात् पलितघ्नं सर्वेन्द्रियदार्ढ्यावहं च", text: "rāmataraṇīmūlapaladvayaṃ yaṣṭīmadhukapalaṃ sārivārdhapalamekatrajarjarīkṛtamakṣatailapalairdaśabhirāplutaṃ lohabhājane daśāhaṃ divasakarakaraprataptaṃ nāvanāt palitaghnaṃ sarvendriyadārḍhyāvahaṃ ca" },
      { type: "verse", number: "48", sanskrit: "कृष्णातिलतिलपर्णीत्रिफलामधुककासीसपद्मककर्दममांसीमार्कवमसनपत्रस्वरसपिष्टं त्रिरात्रमयः पात्रे स्थापयेत् ततः पूर्वोक्तरसद्रुतेन पद्मिनीकर्दमप्रलिप्तप्तधौतान् केशान् कपालं च लेपयेत् ततः पद्मिनीकर्दमैः प्रच्छाद्य कौशेयेन वेष्टयेत् तृतीये चाह्नि प्रक्षाल्यैवमेव कुर्यात् एवमलिकुलनीलाः केशाः शिरो विभूषयन्ति भवति चात्र", text: "kṛṣṇātilatilaparṇītriphalāmadhukakāsīsapadmakakardamamāṃsīmārkavamasanapatrasvarasapiṣṭaṃ trirātramayaḥ pātre sthāpayet tataḥ pūrvoktarasadrutena padminīkardamapraliptaptadhautān keśān kapālaṃ ca lepayet tataḥ padminīkardamaiḥ pracchādya kauśeyena veṣṭayet tṛtīye cāhni prakṣālyaivameva kuryāt evamalikulanīlāḥ keśāḥ śiro vibhūṣayanti bhavati cātra" },
      { type: "verse", number: "49", sanskrit: "खलतौ पलिते वल्यां हरिल्लोम्नि च शोधितम् नस्यवक्त्रशिरोभ्यङ्गप्रदेहैः समुपाचरेत्", text: "khalatau palite valyāṃ harillomni ca śodhitam nasyavaktraśirobhyaṅgapradehaiḥ samupācaret" },
      { type: "verse", number: "50", sanskrit: "सिद्धं तैले बृहत्याद्यैर्जीवनीयैश्च नावनम्", text: "siddhaṃ taile bṛhatyādyairjīvanīyaiśca nāvanam" },
      { type: "verse", number: "51", sanskrit: "क्षीरात्साहचरात् भृङ्गरजसः सौरसाद्रसात् प्रस्थस्तैलस्य कुडवो यष्टीमधुपलान्वितः", text: "kṣīrātsāhacarāt bhṛṅgarajasaḥ saurasādrasāt prasthastailasya kuḍavo yaṣṭīmadhupalānvitaḥ" },
      { type: "verse", number: "52", sanskrit: "सिद्धश्शैलासने भाण्डे शृङ्गे मेषस्य वा स्थितः नस्यं स्यात् #", text: "siddhaśśailāsane bhāṇḍe śṛṅge meṣasya vā sthitaḥ nasyaṃ syāt #" },
      { type: "verse", number: "53", sanskrit: "क्षीरपिष्टौ वा दुग्धिकाकरवीरकौ उत्पाट्य पलितं देयावाशये पलितापहौ", text: "kṣīrapiṣṭau vā dugdhikākaravīrakau utpāṭya palitaṃ deyāvāśaye palitāpahau" },
      { type: "verse", number: "54", sanskrit: "आदित्यवल्या मूलानि कृष्णसैरेयकस्य च फलं कृष्णशणात्पत्रं सुरसाद्यष्टिमार्कवम्", text: "ādityavalyā mūlāni kṛṣṇasaireyakasya ca phalaṃ kṛṣṇaśaṇātpatraṃ surasādyaṣṭimārkavam" },
      { type: "verse", number: "55", sanskrit: "सुराह्वं काकमाची च पृथग्दशपलांशिकम् प्रपौण्डरीकमञ्जिष्ठालोध्रकृष्णागरूत्पलम्", text: "surāhvaṃ kākamācī ca pṛthagdaśapalāṃśikam prapauṇḍarīkamañjiṣṭhālodhrakṛṣṇāgarūtpalam" },
      { type: "verse", number: "56", sanskrit: "आम्रास्थिकर्दमःकृष्णो मृणाली रक्तचन्दनम् नीलीभल्लातकास्थीनि काससिं मदयन्तिका", text: "āmrāsthikardamaḥkṛṣṇo mṛṇālī raktacandanam nīlībhallātakāsthīni kāsasiṃ madayantikā" },
      { type: "verse", number: "57", sanskrit: "सोमराज्यसनं शस्त्रं कृष्णं पिण्डीतचित्रकौ पुष्पाण्यर्जुनकाश्मर्या आमजम्बूफलाज्जनम्", text: "somarājyasanaṃ śastraṃ kṛṣṇaṃ piṇḍītacitrakau puṣpāṇyarjunakāśmaryā āmajambūphalājjanam" },
      { type: "verse", number: "58", sanskrit: "प्रत्येकं पञ्चपलिकं पिष्टं सत्रिफलाकणम् अक्षतैलाढकं तेन पचेद्धात्रीरसार्मणे", text: "pratyekaṃ pañcapalikaṃ piṣṭaṃ satriphalākaṇam akṣatailāḍhakaṃ tena paceddhātrīrasārmaṇe" },
      { type: "verse", number: "59", sanskrit: "कुर्यादादित्यपाकं वा यावच्छुष्को भवेद्रसः लोहपात्रे ततः पूतं महानीलं प्रयोजितम्", text: "kuryādādityapākaṃ vā yāvacchuṣko bhavedrasaḥ lohapātre tataḥ pūtaṃ mahānīlaṃ prayojitam" },
      { type: "verse", number: "60", sanskrit: "तत्पाने नावने ऽभ्यङ्गे शुद्धस्य नियतात्मनः सर्वजत्रूर्ध्वरोगघ्नं पलितघ्नं विशेषतः एभिरेव च भैषज्यैः शिरो वक्त्रं च लेपयेत्", text: "tatpāne nāvane 'bhyaṅge śuddhasya niyatātmanaḥ sarvajatrūrdhvarogaghnaṃ palitaghnaṃ viśeṣataḥ ebhireva ca bhaiṣajyaiḥ śiro vaktraṃ ca lepayet" },
      { type: "verse", number: "61", sanskrit: "क्षीरं प्रियालं यष्ट्याह्वं जीवनीयो गणस्तिलाः कृष्णाः प्रलेपो वक्त्रस्य हरिल्लोमवलीहितः", text: "kṣīraṃ priyālaṃ yaṣṭyāhvaṃ jīvanīyo gaṇastilāḥ kṛṣṇāḥ pralepo vaktrasya harillomavalīhitaḥ" },
      { type: "verse", number: "62", sanskrit: "तिलाः सामलकाः पद्मकिञ्जिल्को मधुकं मधु बृंहयेद्रञ्जयेच्चैतत् केशान् मूर्ध्नः प्रलेपनात्", text: "tilāḥ sāmalakāḥ padmakiñjilko madhukaṃ madhu bṛṃhayedrañjayeccaitat keśān mūrdhnaḥ pralepanāt" },
      { type: "verse", number: "63", sanskrit: "पचेत् सैन्धवशुक्ताम्लैरयश्चूर्णं सतण्डुलम् तेनालिप्तं शिरः शुद्धमस्निग्धमुषितं निशाम् तत्प्रातस्त्रिफलौधातं स्यात्कृष्णस्निग्धमूर्द्धजम्", text: "pacet saindhavaśuktāmlairayaścūrṇaṃ sataṇḍulam tenāliptaṃ śiraḥ śuddhamasnigdhamuṣitaṃ niśām tatprātastriphalaudhātaṃ syātkṛṣṇasnigdhamūrddhajam" },
      { type: "verse", number: "64", sanskrit: "अयश्चूर्णो ऽम्लपिष्टश्च रागः सत्रिफलो वरः", text: "ayaścūrṇo 'mlapiṣṭaśca rāgaḥ satriphalo varaḥ" },
      { type: "verse", number: "65", sanskrit: "कन्यायास्तिलनिम्बवीजमधुकश्रेष्ठावचामार्कवात् चूर्णछागलगव्यमाहिषपलस्नेहेन सम्प्लावितम् पात्रे स्थापितमायसे क्षितितले मासं निधायोद्धृतं पालित्यं खलतिं च दर्पणनिभां हन्त्येतदभ्यञ्जनात्", text: "kanyāyāstilanimbavījamadhukaśreṣṭhāvacāmārkavāt cūrṇachāgalagavyamāhiṣapalasnehena samplāvitam pātre sthāpitamāyase kṣititale māsaṃ nidhāyoddhṛtaṃ pālityaṃ khalatiṃ ca darpaṇanibhāṃ hantyetadabhyañjanāt" },
      { type: "verse", number: "66", sanskrit: "बीजैःश्लेष्मातकस्य व्यपगमिततुषैःकाञ्जिकश्लक्ष्णपिष्टैर्यल्लिप्ताल्लोहदण्डाद्दिनकरकिरणैस्तापितात् प्रच्यवेत तत्तैलं केशकार्ष्ण्यं जनयति परमं नावनाभ्यञ्जनाभ्यां मूर्द्धघ्राणाक्षिदन्तश्रवणगलरुजं हन्ति निश्शेषतश्च", text: "bījaiḥśleṣmātakasya vyapagamitatuṣaiḥkāñjikaślakṣṇapiṣṭairyalliptāllohadaṇḍāddinakarakiraṇaistāpitāt pracyaveta tattailaṃ keśakārṣṇyaṃ janayati paramaṃ nāvanābhyañjanābhyāṃ mūrddhaghrāṇākṣidantaśravaṇagalarujaṃ hanti niśśeṣataśca" },
      { type: "verse", number: "67", sanskrit: "बलामधूकमधुकविदारीचन्दनोत्पलैः जीवकर्षभकद्राक्षाशर्कराभिश्च साधितः", text: "balāmadhūkamadhukavidārīcandanotpalaiḥ jīvakarṣabhakadrākṣāśarkarābhiśca sādhitaḥ" },
      { type: "verse", number: "68", sanskrit: "प्रस्थस्तैलस्य सक्षीरो जाङ्गलार्धतुलारसे नस्यं सर्वोर्ध्वजत्रूत्थवातपित्तामयापहम्", text: "prasthastailasya sakṣīro jāṅgalārdhatulārase nasyaṃ sarvordhvajatrūtthavātapittāmayāpaham" },
      { type: "verse", number: "69", sanskrit: "मयूरं पक्षपित्तान्त्रपादविट्तुण्डवर्जितम् दशमूलबलारास्नामधुकैस्त्रिफलैर्युतम्", text: "mayūraṃ pakṣapittāntrapādaviṭtuṇḍavarjitam daśamūlabalārāsnāmadhukaistriphalairyutam" },
      { type: "verse", number: "70", sanskrit: "जले पक्त्वा घृतप्रस्थं तस्मिन् क्षीरसमं पचेत् कल्कितैर्मधुरद्रव्यैः सर्वजत्रूर्ध्वरोगनित् तदभ्यासीकृतं पानबस्त्यभ्यञ्जननावनैः", text: "jale paktvā ghṛtaprasthaṃ tasmin kṣīrasamaṃ pacet kalkitairmadhuradravyaiḥ sarvajatrūrdhvaroganit tadabhyāsīkṛtaṃ pānabastyabhyañjananāvanaiḥ" },
      { type: "verse", number: "71", sanskrit: "एतेनैवकषायेण घृतप्रस्थं विपाचयेत् चतुर्गुणेनपयसा कल्कैरेभिश्च कार्षिकैः", text: "etenaivakaṣāyeṇa ghṛtaprasthaṃ vipācayet caturguṇenapayasā kalkairebhiśca kārṣikaiḥ" },
      { type: "verse", number: "72", sanskrit: "जीवन्तीत्रिफलामेदामृद्वीकर्द्धिपरूपकैः समङ्गाचविकाभार्ङ्गीकाश्मरीकर्कटाह्वयैः", text: "jīvantītriphalāmedāmṛdvīkarddhiparūpakaiḥ samaṅgācavikābhārṅgīkāśmarīkarkaṭāhvayaiḥ" },
      { type: "verse", number: "73", sanskrit: "आत्मगुप्तामहामेदातालखर्जूरमस्तकैः मृणालबिसखर्जूरयष्टीमधुकजीवकैः", text: "ātmaguptāmahāmedātālakharjūramastakaiḥ mṛṇālabisakharjūrayaṣṭīmadhukajīvakaiḥ" },
      { type: "verse", number: "74", sanskrit: "शतावरीविदारीक्षुबृहतीसारिबायुगैः मूर्वाश्वदंष्ट्रर्षभकशृङ्गाटककशेरुकैः", text: "śatāvarīvidārīkṣubṛhatīsāribāyugaiḥ mūrvāśvadaṃṣṭrarṣabhakaśṛṅgāṭakakaśerukaiḥ" },
      { type: "verse", number: "75", sanskrit: "रास्नास्थिरातामलकीसूक्ष्मैलाशठिपौष्करैः पुनर्नवातवक्षीरीकाकोलीधन्वयासकैः", text: "rāsnāsthirātāmalakīsūkṣmailāśaṭhipauṣkaraiḥ punarnavātavakṣīrīkākolīdhanvayāsakaiḥ" },
      { type: "verse", number: "76", sanskrit: "मधुकाक्षोडवाताममुञ्जाताभिषुकैरपि महामाधूरमित्येतन्मायूरादधिकं गुणैः", text: "madhukākṣoḍavātāmamuñjātābhiṣukairapi mahāmādhūramityetanmāyūrādadhikaṃ guṇaiḥ" },
      { type: "verse", number: "77", sanskrit: "धात्विन्द्रियस्वरभ्रंशश्वासकासार्दितापहम् योन्यसृक्शुक्रदोषेषु शस्तं वन्ध्यासुतप्रदम्", text: "dhātvindriyasvarabhraṃśaśvāsakāsārditāpaham yonyasṛkśukradoṣeṣu śastaṃ vandhyāsutapradam" },
      { type: "verse", number: "78", sanskrit: "आखुभिः कुक्कुटैर्हंसैः शशैश्चेति प्रकल्पयेत्", text: "ākhubhiḥ kukkuṭairhaṃsaiḥ śaśaiśceti prakalpayet" },
      { type: "verse", number: "79", sanskrit: "जत्रूर्ध्वजानां व्याधीनामेकत्रिंशच्छतद्वयम् परस्परमसङ्कीर्णं विस्तरेण प्रकाशितम्", text: "jatrūrdhvajānāṃ vyādhīnāmekatriṃśacchatadvayam parasparamasaṅkīrṇaṃ vistareṇa prakāśitam" },
      { type: "verse", number: "80", sanskrit: "ऊर्ध्वमूलमधःशाखमृषयः पुरुषं विदुः मूलप्रहारिणस्तस्माद्रोगान् शीघ्रतरं जयेत्", text: "ūrdhvamūlamadhaḥśākhamṛṣayaḥ puruṣaṃ viduḥ mūlaprahāriṇastasmādrogān śīghrataraṃ jayet" },
      { type: "verse", number: "81", sanskrit: "सर्वेन्द्रियाणि येनास्मिन् प्राणा येन च संश्रिताः तेन तस्योत्तमाग्गस्य रक्षायामादृतो भवेत्", text: "sarvendriyāṇi yenāsmin prāṇā yena ca saṃśritāḥ tena tasyottamāggasya rakṣāyāmādṛto bhavet" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 29,
    lang: "sa",
    content: [
      { type: "heading", heading: "Агада тантра — токсикология — введение" },
      { type: "text", text: "Глава 29 Уттара стханы — «Агада тантра» — посвящена специализированному разделу: токсикология — введение. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो व्रणविभक्तिपरिज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्त्रेयादयो महर्षयः", text: "athāto vraṇavibhaktiparijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurāttreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "यावदायुर्वृणीते विवृणोति वा शरीरमितिव्रणः", text: "yāvadāyurvṛṇīte vivṛṇoti vā śarīramitivraṇaḥ" },
      { type: "verse", number: "3", sanskrit: "स च द्विविधो निज आगन्तुश्च तत्र निजो दोषसमुत्थः आगन्तुः शस्त्रानुशस्त्रोपललगुडनखदशनविषाणविषारुष्करादिनिमित्तः सो ऽपि पुनर्वातादिभिरधिष्ठितो निजतां लभते", text: "sa ca dvividho nija āgantuśca tatra nijo doṣasamutthaḥ āgantuḥ śastrānuśastropalalaguḍanakhadaśanaviṣāṇaviṣāruṣkarādinimittaḥ so 'pi punarvātādibhiradhiṣṭhito nijatāṃ labhate" },
      { type: "verse", number: "4", sanskrit: "पुनश्च द्वेधा व्रणो दुष्टः शुद्धश्च तत्रदोषदूषितो दुष्टः", text: "punaśca dvedhā vraṇo duṣṭaḥ śuddhaśca tatradoṣadūṣito duṣṭaḥ" },
      { type: "verse", number: "5", sanskrit: "तस्य सामान्यलिङ्गमतिसंवृतविवृतत्वमतिमृदुकठिनतात्युत्सादावसादावतिशीतोष्णभावोतिरक्तकृष्णपाण्डुता पूतीमांससिरास्नायुप्रतिच्छन्नत्वं पुतीपूयास्रावः सोत्सङ्गिता दाहपाककण्डूश्वयथुवेदनासंरम्भपिटकोपद्रवोपद्रुतत्वं दीर्घकालानुबन्धश्च", text: "tasya sāmānyaliṅgamatisaṃvṛtavivṛtatvamatimṛdukaṭhinatātyutsādāvasādāvatiśītoṣṇabhāvotiraktakṛṣṇapāṇḍutā pūtīmāṃsasirāsnāyupraticchannatvaṃ putīpūyāsrāvaḥ sotsaṅgitā dāhapākakaṇḍūśvayathuvedanāsaṃrambhapiṭakopadravopadrutatvaṃ dīrghakālānubandhaśca" },
      { type: "verse", number: "6", sanskrit: "विशेषतस्तु पञ्चदशधा भिद्यते", text: "viśeṣatastu pañcadaśadhā bhidyate" },
      { type: "verse", number: "7", sanskrit: "तत्र श्यावो ऽरुणः कृष्णो भस्मास्थिकपोतगलान्यतमवर्णो वा दधिमस्तुक्षाराम्बुमांसधावनपुलाकोदकनिभाल्पस्रावो रूक्षश्चटचटायमानशीलो ऽकस्माद्विविधशूलस्फुरणायामतोदभेदस्वापबहुलो निर्मांसश्च वातात्", text: "tatra śyāvo 'ruṇaḥ kṛṣṇo bhasmāsthikapotagalānyatamavarṇo vā dadhimastukṣārāmbumāṃsadhāvanapulākodakanibhālpasrāvo rūkṣaścaṭacaṭāyamānaśīlo 'kasmādvividhaśūlasphuraṇāyāmatodabhedasvāpabahulo nirmāṃsaśca vātāt" },
      { type: "verse", number: "8", sanskrit: "क्षिप्रजः पीतनीलहरितकृष्णकपिलपिङ्गलो गोमूत्रभस्मशङ्खकिंशुकोदकमार्द्वीकतैलाभोष्णभूरिक्लेदो दाहोषाज्वररागपाकावदरणधूमायनान्वितः क्षारोक्षितक्षतोपमवेदनः पिटकाजुष्टश्च पित्तात्", text: "kṣiprajaḥ pītanīlaharitakṛṣṇakapilapiṅgalo gomūtrabhasmaśaṅkhakiṃśukodakamārdvīkatailābhoṣṇabhūrikledo dāhoṣājvararāgapākāvadaraṇadhūmāyanānvitaḥ kṣārokṣitakṣatopamavedanaḥ piṭakājuṣṭaśca pittāt" },
      { type: "verse", number: "9", sanskrit: "स्निग्धः स्थूलौष्ठाः पाण्डुश्चण्डकण्डूर्नवनीतवसामज्जपिष्टतिलनारिकेलाम्बुसदृशश्वेतशीतबहलपिच्छिलक्लेदः स्वापस्तम्भस्तैमित्यगौरवोपदेहयुक्तः सिरास्नायुजालावततो मन्दवेदनः कठिनश्च कफात्", text: "snigdhaḥ sthūlauṣṭhāḥ pāṇḍuścaṇḍakaṇḍūrnavanītavasāmajjapiṣṭatilanārikelāmbusadṛśaśvetaśītabahalapicchilakledaḥ svāpastambhastaimityagauravopadehayuktaḥ sirāsnāyujālāvatato mandavedanaḥ kaṭhinaśca kaphāt" },
      { type: "verse", number: "10", sanskrit: "प्रवालरक्तः कृष्णस्फोटपिटकाजालोपचितो वाजिस्थानगान्धिः सरक्तपूयस्रावी पित्तलिङ्गश्च रक्तात्", text: "pravālaraktaḥ kṛṣṇasphoṭapiṭakājālopacito vājisthānagāndhiḥ saraktapūyasrāvī pittaliṅgaśca raktāt" },
      { type: "verse", number: "11", sanskrit: "यथास्वलिङ्गसङ्करे द्वाभ्यां त्रिभिः सर्वैश्च दुष्टं विद्यात् अपि च घृतमण्डाभो मत्स्यधावनगन्धिर्मुदुर्विंसर्पी कृष्णपूयश्च पित्तरक्ताभ्याम्", text: "yathāsvaliṅgasaṅkare dvābhyāṃ tribhiḥ sarvaiśca duṣṭaṃ vidyāt api ca ghṛtamaṇḍābho matsyadhāvanagandhirmudurviṃsarpī kṛṣṇapūyaśca pittaraktābhyām" },
      { type: "verse", number: "12", sanskrit: "वातादिभिरेव च व्रणस्यानधिष्ठानं शुद्धिः तत्र यथोक्तदुष्टलिङ्गाभावात् संरम्भरहितत्वं जिह्वावर्णता श्लक्ष्णत्वं नीरुजत्वं निरास्रावता श्यावपर्यन्तत्वं समौष्ठमध्यता किञ्चिदुन्नतमध्यता वा", text: "vātādibhireva ca vraṇasyānadhiṣṭhānaṃ śuddhiḥ tatra yathoktaduṣṭaliṅgābhāvāt saṃrambharahitatvaṃ jihvāvarṇatā ślakṣṇatvaṃ nīrujatvaṃ nirāsrāvatā śyāvaparyantatvaṃ samauṣṭhamadhyatā kiñcidunnatamadhyatā vā" },
      { type: "verse", number: "13", sanskrit: "त्वङ्मांससिरास्नायुसन्ध्यस्थिकोष्ठमर्माण्यष्टौ व्रणाशयाः आशयविशेषाच्चास्रावविशेषः", text: "tvaṅmāṃsasirāsnāyusandhyasthikoṣṭhamarmāṇyaṣṭau vraṇāśayāḥ āśayaviśeṣāccāsrāvaviśeṣaḥ" },
      { type: "verse", number: "14", sanskrit: "तत्र घृष्टासु वा त्वक्षु स्फोटेषु वा भिन्नेषु सलिलप्रकाशो भवत्यास्रावः किञ्चिद्विस्रः पीतावभासश्च", text: "tatra ghṛṣṭāsu vā tvakṣu sphoṭeṣu vā bhinneṣu salilaprakāśo bhavatyāsrāvaḥ kiñcidvisraḥ pītāvabhāsaśca" },
      { type: "verse", number: "15", sanskrit: "मांसगतः सर्पिःप्रकाशो बहलः पिच्छिलश्च", text: "māṃsagataḥ sarpiḥprakāśo bahalaḥ picchilaśca" },
      { type: "verse", number: "16", sanskrit: "सिरागतस्तु सद्यश्छिन्नासु सिरासु रक्तातिप्रवृत्तिः पक्वासु च तोयनाडीभिरिवाम्भसः पूयस्यागमनम् स च तनुर्विच्छिन्नः पिच्छिलो ऽवलम्बी श्यावश्च", text: "sirāgatastu sadyaśchinnāsu sirāsu raktātipravṛttiḥ pakvāsu ca toyanāḍībhirivāmbhasaḥ pūyasyāgamanam sa ca tanurvicchinnaḥ picchilo 'valambī śyāvaśca" },
      { type: "verse", number: "17", sanskrit: "स्नावगतः स्निघ्दो घनः सिङ्घाणकप्रतिमः सरक्तश्च", text: "snāvagataḥ snighdo ghanaḥ siṅghāṇakapratimaḥ saraktaśca" },
      { type: "verse", number: "18", sanskrit: "सन्धिगतः समन्तात् प्रपीड्यमानो न प्रवर्तते तथाकुञ्चनप्रसारणोन्नमननमनप्रवाहणेषु स्रवति पिच्छिलो ऽवलम्बी स फेनरुधिरोन्मिश्रश्च", text: "sandhigataḥ samantāt prapīḍyamāno na pravartate tathākuñcanaprasāraṇonnamananamanapravāhaṇeṣu sravati picchilo 'valambī sa phenarudhironmiśraśca" },
      { type: "verse", number: "19", sanskrit: "अस्थि त्वभिहतं स्फुटितं भिन्नं दोषावदारितं वा दोषभक्षितत्वान्निस्सारं भवति आस्रावश्चात्र मज्जमिश्रः सरुधिरः स्निग्धश्च", text: "asthi tvabhihataṃ sphuṭitaṃ bhinnaṃ doṣāvadāritaṃ vā doṣabhakṣitatvānnissāraṃ bhavati āsrāvaścātra majjamiśraḥ sarudhiraḥ snigdhaśca" },
      { type: "verse", number: "20", sanskrit: "कोष्ठश्रितस्तु व्रणो मूत्र्पुरीषरुधिरपूयोदकानि स्रवति", text: "koṣṭhaśritastu vraṇo mūtrpurīṣarudhirapūyodakāni sravati" },
      { type: "verse", number: "21", sanskrit: "मर्मगतस्तु नोच्यते त्वगादिष्वेवावरुद्धत्वात्", text: "marmagatastu nocyate tvagādiṣvevāvaruddhatvāt" },
      { type: "verse", number: "22", sanskrit: "तेषु यथापूर्वं सुखसाध्यत्वम् तथायतश्चतुरस्रो वृत्तस्त्रिपुटकश्च व्रणः शोषास्तु विकृताकृतयो दुरुपचाराः ते च प्रायशो भवन्त्यागन्तवः स्वयं विदीर्णाश्च दोषजा न तु वैद्यकृताः", text: "teṣu yathāpūrvaṃ sukhasādhyatvam tathāyataścaturasro vṛttastripuṭakaśca vraṇaḥ śoṣāstu vikṛtākṛtayo durupacārāḥ te ca prāyaśo bhavantyāgantavaḥ svayaṃ vidīrṇāśca doṣajā na tu vaidyakṛtāḥ" },
      { type: "verse", number: "23", sanskrit: "वयस्थानां दृढानां प्राणवतां सत्ववतामात्मवतां दीप्ताग्नीनां च व्रणाः सुचिकित्स्याः", text: "vayasthānāṃ dṛḍhānāṃ prāṇavatāṃ satvavatāmātmavatāṃ dīptāgnīnāṃ ca vraṇāḥ sucikitsyāḥ" },
      { type: "verse", number: "24", sanskrit: "तत्र वयस्थानां प्रत्यग्रधातुत्वादाशुव्रणसंरोहो भवति दृढानां स्थिरबहुमांसत्वाच्छस्त्रमवचार्यमाणं सिरास्नाय्वादीन् न प्राप्नोति प्राणवतां वेदनाहारविहारयन्त्रणादिभिर्न ग्लानिः सत्ववतां दारुणैरपि क्रियाविशेषैर्न व्यथा भवति आत्मवतां सुनियमिताहारविहारादिभिरुपदेशैर्नान्यथा भवति दीप्ताग्नीनाम् प्रक्लिन्नदेहत्वात् प्रकृतितश्चाप्रक्लेदिशरीराणां तद्वधयोश्च देशकालयोरास्रावदैर्गन्ध्याभावादाशु विशुद्धेन मांसेनानुपद्रवमापूरणम्", text: "tatra vayasthānāṃ pratyagradhātutvādāśuvraṇasaṃroho bhavati dṛḍhānāṃ sthirabahumāṃsatvācchastramavacāryamāṇaṃ sirāsnāyvādīn na prāpnoti prāṇavatāṃ vedanāhāravihārayantraṇādibhirna glāniḥ satvavatāṃ dāruṇairapi kriyāviśeṣairna vyathā bhavati ātmavatāṃ suniyamitāhāravihārādibhirupadeśairnānyathā bhavati dīptāgnīnām praklinnadehatvāt prakṛtitaścāpraklediśarīrāṇāṃ tadvadhayośca deśakālayorāsrāvadairgandhyābhāvādāśu viśuddhena māṃsenānupadravamāpūraṇam" },
      { type: "verse", number: "25", sanskrit: "एत एव गुणा वृद्धकृशाल्पप्राणभीरुमन्दाग्निप्रक्लेदिदेहदेशकालेषु विपरीताः शिष्योपनयनीयं चेक्षेत", text: "eta eva guṇā vṛddhakṛśālpaprāṇabhīrumandāgniprakledidehadeśakāleṣu viparītāḥ śiṣyopanayanīyaṃ cekṣeta" },
      { type: "verse", number: "26", sanskrit: "तथा स्फिक्पायुप्रजननललाटगण्डौष्ठपृष्ठकर्णफलकोशोदरजत्रुमुखाभ्यन्तरस्थाः सुखरोपणीयाः विपरीतास्त्त्वक्षिदन्तनासापाङ्गश्रोत्रनाभिजठरसेवनीनितम्बपार्श्वकुक्षिवक्षःकक्षास्तनसन्धिभागगताः सफेनपूयरक्तानिलवाहिनोन्तःशल्याश्चाधोभागाच्चोर्ध्वभागनिर्वमना रोमान्तोपनखमर्मजङ्घास्थिघ्राणाश्रिताश्च भग्न्दरश्चान्तर्मुखः सेवनीकट्यस्थिसंश्रितः अपि च", text: "tathā sphikpāyuprajananalalāṭagaṇḍauṣṭhapṛṣṭhakarṇaphalakośodarajatrumukhābhyantarasthāḥ sukharopaṇīyāḥ viparītāsttvakṣidantanāsāpāṅgaśrotranābhijaṭharasevanīnitambapārśvakukṣivakṣaḥkakṣāstanasandhibhāgagatāḥ saphenapūyaraktānilavāhinontaḥśalyāścādhobhāgāccordhvabhāganirvamanā romāntopanakhamarmajaṅghāsthighrāṇāśritāśca bhagndaraścāntarmukhaḥ sevanīkaṭyasthisaṃśritaḥ api ca" },
      { type: "verse", number: "27", sanskrit: "कुष्ठिनां विषजुष्टानां शोषिणां मधुमेहिनाम् व्रणाः कृच्छ्रेण सिध्यन्ति येषां च स्युर्व्रणे व्रणाः", text: "kuṣṭhināṃ viṣajuṣṭānāṃ śoṣiṇāṃ madhumehinām vraṇāḥ kṛcchreṇa sidhyanti yeṣāṃ ca syurvraṇe vraṇāḥ" },
      { type: "verse", number: "28", sanskrit: "याप्यास्त्ववपाटिका निरुद्धमणिरुद्धगुदव्रणग्रन्थिप्रभृतयः सर्वास्थिक्षतं च", text: "yāpyāstvavapāṭikā niruddhamaṇiruddhagudavraṇagranthiprabhṛtayaḥ sarvāsthikṣataṃ ca" },
      { type: "verse", number: "29", sanskrit: "असाध्याः पुनर्मांसपिण्डवदुद्गताः प्रसेकिनोन्तःपूया वेदनावन्तश्च पायुवदुद्वृत्तौष्ठाः कठिना गोशृङ्गवदुन्नतमांसप्ररोहा दुष्टशोणितास्राविणस्तनुपिच्छिलास्रावस्राविणो वा मध्योन्नताः समवसन्नसुषिरपर्यन्ताः शणतूलवत्स्नायुजालवन्तो दुर्दर्शना मेदोमज्जवसामस्तुलुङ्गस्राविणश्च दोषसमुत्थाः पीतासितामूत्रपुरीषवातवाहिनश्च कोष्ठस्थाः रक्तशयजाश्च क्षारोदकसमास्रावाः पक्वाशयजाश्च पुलाकोदकमिव स्रवन्तः क्षीणमांसानां च सर्वतोगतयस्त्वणुमुखमांसबुद्बुदवन्तः सशब्दवातवाहिनश्च शिरःकठस्था विसर्पज्वरपिपासारोचकाविपाककासश्वासातीसारच्छर्दियुक्ताः भिन्नो च शिरःकपाले यत्र मस्तुलुङ्गदर्शनं त्रिदोषलिङ्गप्रादुभावो वा स्यादिति भवति चात्र", text: "asādhyāḥ punarmāṃsapiṇḍavadudgatāḥ prasekinontaḥpūyā vedanāvantaśca pāyuvadudvṛttauṣṭhāḥ kaṭhinā gośṛṅgavadunnatamāṃsaprarohā duṣṭaśoṇitāsrāviṇastanupicchilāsrāvasrāviṇo vā madhyonnatāḥ samavasannasuṣiraparyantāḥ śaṇatūlavatsnāyujālavanto durdarśanā medomajjavasāmastuluṅgasrāviṇaśca doṣasamutthāḥ pītāsitāmūtrapurīṣavātavāhinaśca koṣṭhasthāḥ raktaśayajāśca kṣārodakasamāsrāvāḥ pakvāśayajāśca pulākodakamiva sravantaḥ kṣīṇamāṃsānāṃ ca sarvatogatayastvaṇumukhamāṃsabudbudavantaḥ saśabdavātavāhinaśca śiraḥkaṭhasthā visarpajvarapipāsārocakāvipākakāsaśvāsātīsāracchardiyuktāḥ bhinno ca śiraḥkapāle yatra mastuluṅgadarśanaṃ tridoṣaliṅgaprādubhāvo vā syāditi bhavati cātra" },
      { type: "verse", number: "30", sanskrit: "स्नायुक्लेदात् सिराच्छेदात् गाम्भीर्यात् कृमिभक्षणात् अस्थिभेदात् सशल्यत्वात् सविषत्वादतर्किंतात्", text: "snāyukledāt sirācchedāt gāmbhīryāt kṛmibhakṣaṇāt asthibhedāt saśalyatvāt saviṣatvādatarkiṃtāt" },
      { type: "verse", number: "31", sanskrit: "मिथ्याबन्धादतिस्नेहाद्रौक्ष्याद्रोमादिघट्टनात् क्षोभादशुद्धकोष्ठत्वात् सौहित्यादतिकर्शनात्", text: "mithyābandhādatisnehādraukṣyādromādighaṭṭanāt kṣobhādaśuddhakoṣṭhatvāt sauhityādatikarśanāt" },
      { type: "verse", number: "32", sanskrit: "मद्यपानाद्दिवास्वप्नाद्व्यायामाद्रात्रिजागरात् व्रणो मिथ्योपचाराच्च नैव साध्योपि सिध्यति", text: "madyapānāddivāsvapnādvyāyāmādrātrijāgarāt vraṇo mithyopacārācca naiva sādhyopi sidhyati" },
      { type: "verse", number: "33", sanskrit: "कपोतवर्णप्रतिमा यस्यान्ताः क्लेदवर्जिताः स्थिराश्च पिटकावन्तो रोहतीति तमादिशेत्", text: "kapotavarṇapratimā yasyāntāḥ kledavarjitāḥ sthirāśca piṭakāvanto rohatīti tamādiśet" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 30,
    lang: "sa",
    content: [
      { type: "heading", heading: "Дамш тра виша — яды укусов" },
      { type: "text", text: "Глава 30 Уттара стханы — «Дамш тра виша» — посвящена специализированному разделу: яды укусов. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो व्रणप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto vraṇapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "व्रणस्य शोफावस्थायां शस्त्रकर्मविधौ श्वयथुचिकित्सिते च साधनमुद्दिष्टम् तत्रापतर्पणमेवादौ प्रधानतमम् अपि च", text: "vraṇasya śophāvasthāyāṃ śastrakarmavidhau śvayathucikitsite ca sādhanamuddiṣṭam tatrāpatarpaṇamevādau pradhānatamam api ca" },
      { type: "verse", number: "3", sanskrit: "दोषोच्छ्रायोपशान्त्यर्थमुपदिष्टं यथायथम् अवेक्ष्य देहप्राणादीन् कर्तव्यमपतर्पणम्", text: "doṣocchrāyopaśāntyarthamupadiṣṭaṃ yathāyatham avekṣya dehaprāṇādīn kartavyamapatarpaṇam" },
      { type: "verse", number: "4", sanskrit: "रागसंरम्भरहिताः परिम्लाना हृताश्रयाः सद्यः शाम्यन्ति शुद्धानां व्रणाः शोफाश्च देहिनाम्", text: "rāgasaṃrambharahitāḥ parimlānā hṛtāśrayāḥ sadyaḥ śāmyanti śuddhānāṃ vraṇāḥ śophāśca dehinām" },
      { type: "verse", number: "5", sanskrit: "लेपाभ्यङ्गपरीषेकान् यथोक्तांश्च प्रयोजयेत् यथाम्बुभिः सिच्यमानः शान्तिमग्निर्नियच्छति दोषाग्निरेवं सहसा प्रलेपाद्यैः प्रयोजितैः", text: "lepābhyaṅgaparīṣekān yathoktāṃśca prayojayet yathāmbubhiḥ sicyamānaḥ śāntimagnirniyacchati doṣāgnirevaṃ sahasā pralepādyaiḥ prayojitaiḥ" },
      { type: "verse", number: "6", sanskrit: "प्रतिलोममेव चानुलिपेन्नानुलोमम् तथाह्यौषधं सम्यगवतिष्ठते अनुप्रविशति च रोमकूपान् न तु शुष्यदुपेक्षितव्यमन्यत्रपीडयितव्यात् शुष्कं हि दाहोषारागश्यावत्वशूलानि वर्धयति", text: "pratilomameva cānulipennānulomam tathāhyauṣadhaṃ samyagavatiṣṭhate anupraviśati ca romakūpān na tu śuṣyadupekṣitavyamanyatrapīḍayitavyāt śuṣkaṃ hi dāhoṣārāgaśyāvatvaśūlāni vardhayati" },
      { type: "verse", number: "7", sanskrit: "यस्तु शीतस्तनुर्मुहुर्मुहुश्च प्रयुज्यते स प्रदेहो रक्तपित्तत्वचां प्रसादकृत् प्रलेपस्तूष्णः शीतो वा बहलश्च तथा वातश्लेष्मप्रशमनस्तस्योपयोगः क्षताक्षतेषु यस्तु क्षतेषूपयुज्यते स भूयः कल्क इति संज्ञां लभते", text: "yastu śītastanurmuhurmuhuśca prayujyate sa pradeho raktapittatvacāṃ prasādakṛt pralepastūṣṇaḥ śīto vā bahalaśca tathā vātaśleṣmapraśamanastasyopayogaḥ kṣatākṣateṣu yastu kṣateṣūpayujyate sa bhūyaḥ kalka iti saṃjñāṃ labhate" },
      { type: "verse", number: "8", sanskrit: "दशविधश्च समासादालेपः तद्यथा स्नैहिको निर्वापणः प्रसादनः स्तम्भनो विलायनः पाचनः पीडनः शोधनो रोपणः सवर्णीकरणश्च", text: "daśavidhaśca samāsādālepaḥ tadyathā snaihiko nirvāpaṇaḥ prasādanaḥ stambhano vilāyanaḥ pācanaḥ pīḍanaḥ śodhano ropaṇaḥ savarṇīkaraṇaśca" },
      { type: "verse", number: "9", sanskrit: "तत्र वाते स्निग्धद्रव्यैः स्नेहाढ्यैः स्नेहेनैव वा स्नैहिकः पित्ते पित्तप्राये च शोफे विषाग्निक्षारदग्धे च शीतैर्निर्वापणः स एव चान्तर्दुष्टे रक्ते प्रसादनः स एव च पुनरस्रातिप्रवृत्तौ स्तम्भनसंज्ञः श्लेष्ममेदोभूयिष्ठे शीतैश्चाविदग्धे पिष्टलब्धे ग्रथिते वा रूक्षैर्विलायनः तैरेव च विदग्धे पाचनः सूक्ष्मास्ये व्रणे रूक्षैः पिच्छिलैश्च पीडनः अशुद्धे यथास्वमुपदिष्टैः शोधनः शुद्धे रोपणः रूढे च सवर्णीकरणः नामभिरेवचैषां स्वरूपमाख्यातम्", text: "tatra vāte snigdhadravyaiḥ snehāḍhyaiḥ snehenaiva vā snaihikaḥ pitte pittaprāye ca śophe viṣāgnikṣāradagdhe ca śītairnirvāpaṇaḥ sa eva cāntarduṣṭe rakte prasādanaḥ sa eva ca punarasrātipravṛttau stambhanasaṃjñaḥ śleṣmamedobhūyiṣṭhe śītaiścāvidagdhe piṣṭalabdhe grathite vā rūkṣairvilāyanaḥ taireva ca vidagdhe pācanaḥ sūkṣmāsye vraṇe rūkṣaiḥ picchilaiśca pīḍanaḥ aśuddhe yathāsvamupadiṣṭaiḥ śodhanaḥ śuddhe ropaṇaḥ rūḍhe ca savarṇīkaraṇaḥ nāmabhirevacaiṣāṃ svarūpamākhyātam" },
      { type: "verse", number: "10", sanskrit: "न च प्रदेहं रात्रौ प्रयुञ्जीत माभूच्छैत्यपिहितस्योष्मणो बहिरनिस्सरणाद्विकारपरिवृद्धिः", text: "na ca pradehaṃ rātrau prayuñjīta mābhūcchaityapihitasyoṣmaṇo bahiranissaraṇādvikāraparivṛddhiḥ" },
      { type: "verse", number: "11", sanskrit: "पुष्कलावतस्तु पठति", text: "puṣkalāvatastu paṭhati" },
      { type: "verse", number: "12", sanskrit: "तमसा पिहितोह्यूष्मा रोमकूपैरनावृतैः लेपांद्विनैव निर्याति रात्रौ नालेपयेदतः", text: "tamasā pihitohyūṣmā romakūpairanāvṛtaiḥ lepāṃdvinaiva niryāti rātrau nālepayedataḥ" },
      { type: "verse", number: "13", sanskrit: "न च पर्युषितं लेपं दद्यात् भूयस्तमेव वा व्यम्लः पर्युषितो हि स्यात् भ्रष्टवीर्यस्तथेतरः", text: "na ca paryuṣitaṃ lepaṃ dadyāt bhūyastameva vā vyamlaḥ paryuṣito hi syāt bhraṣṭavīryastathetaraḥ" },
      { type: "verse", number: "14", sanskrit: "शोफे व्रणे च कठिने विवर्णे वेदनान्विते सविषे च विशेषेण जलजाद्यैर्हरेदसृक् वेदनायाःप्रशान्त्यर्थं पाकस्याप्राप्तयेपि च", text: "śophe vraṇe ca kaṭhine vivarṇe vedanānvite saviṣe ca viśeṣeṇa jalajādyairharedasṛk vedanāyāḥpraśāntyarthaṃ pākasyāprāptayepi ca" },
      { type: "verse", number: "15", sanskrit: "निर्वापणान् पुनश्चात्र न्यग्रोधाद्यैः सुशीतलान् कुर्यात् प्रदेहसेकादीन् सघृतक्षीरशर्करान्", text: "nirvāpaṇān punaścātra nyagrodhādyaiḥ suśītalān kuryāt pradehasekādīn saghṛtakṣīraśarkarān" },
      { type: "verse", number: "16", sanskrit: "न्यग्रोधोदुम्बराश्वत्थप्लक्षवेतसवल्कलैः प्रदेहो भूरिसर्पिर्भिः शोफनिर्वापणः परम् प्रदेहः ससितस्तद्वत् सक्तवो मधुकं घृतम्", text: "nyagrodhodumbarāśvatthaplakṣavetasavalkalaiḥ pradeho bhūrisarpirbhiḥ śophanirvāpaṇaḥ param pradehaḥ sasitastadvat saktavo madhukaṃ ghṛtam" },
      { type: "verse", number: "17", sanskrit: "वातोल्बणानां स्तब्धानां कठिनानां महारुजाम् स्रुतासृजां च शोफानां व्रणानामपि चेदृशाम्", text: "vātolbaṇānāṃ stabdhānāṃ kaṭhinānāṃ mahārujām srutāsṛjāṃ ca śophānāṃ vraṇānāmapi cedṛśām" },
      { type: "verse", number: "18", sanskrit: "ग्राम्यानूपौदकामिषवेशवारकृसरापायसोत्कारिकाभिः स्वेदो योज्यः", text: "grāmyānūpaudakāmiṣaveśavārakṛsarāpāyasotkārikābhiḥ svedo yojyaḥ" },
      { type: "verse", number: "19", sanskrit: "सदाहशूलांस्तु तिलानतसीश्च भृष्ट्वा पयसि निर्वाप्य तेनैव क्षीरेण पिष्ट्वा प्रलेपयेत्", text: "sadāhaśūlāṃstu tilānatasīśca bhṛṣṭvā payasi nirvāpya tenaiva kṣīreṇa piṣṭvā pralepayet" },
      { type: "verse", number: "20", sanskrit: "बलामधुकपृश्निपर्णीच्छिन्नरुहाभीरुजीवन्तीशर्करामदनक्षीरमहास्नेहसिद्धोत्कारिका कवोष्णा शूलदाहहरा", text: "balāmadhukapṛśniparṇīcchinnaruhābhīrujīvantīśarkarāmadanakṣīramahāsnehasiddhotkārikā kavoṣṇā śūladāhaharā" },
      { type: "verse", number: "21", sanskrit: "तद्वन्मधुकयवचूर्णतैलसर्पिर्भिः कोष्ण आलेपः तथा सतिलो मुद्गपायसमुपनाहः", text: "tadvanmadhukayavacūrṇatailasarpirbhiḥ koṣṇa ālepaḥ tathā satilo mudgapāyasamupanāhaḥ" },
      { type: "verse", number: "22", sanskrit: "दशमूलसिद्धेन सुखोष्णेनाम्भसा पयसा वा घृततैलाभ्यां वा परिषेकः शोफे व्रणे वा दाहशूलघ्नः", text: "daśamūlasiddhena sukhoṣṇenāmbhasā payasā vā ghṛtatailābhyāṃ vā pariṣekaḥ śophe vraṇe vā dāhaśūlaghnaḥ" },
      { type: "verse", number: "23", sanskrit: "स्थिराणां मन्दवेदनानां शोफानां विम्लापनं कार्यम्", text: "sthirāṇāṃ mandavedanānāṃ śophānāṃ vimlāpanaṃ kāryam" },
      { type: "verse", number: "24", sanskrit: "अभ्यज्य स्वेदयित्वा च वेणुनाड्या ततः शनैः विम्लापनार्थं मृद्गीयात्तलेनाङ्गुष्ठकेन वा", text: "abhyajya svedayitvā ca veṇunāḍyā tataḥ śanaiḥ vimlāpanārthaṃ mṛdgīyāttalenāṅguṣṭhakena vā" },
      { type: "verse", number: "25", sanskrit: "तथास्फोतपत्रमसूरकल्केनालेपः सुसिद्धपिष्टैः सघृतैर्मुद्गयवगोधूमैर्वा", text: "tathāsphotapatramasūrakalkenālepaḥ susiddhapiṣṭaiḥ saghṛtairmudgayavagodhūmairvā" },
      { type: "verse", number: "26", sanskrit: "विलीयते स चेन्नैवं ततस्तमुपनाहयेत् आवदग्धस्तथा शान्तिं विदग्धः पाकमश्नुते", text: "vilīyate sa cennaivaṃ tatastamupanāhayet āvadagdhastathā śāntiṃ vidagdhaḥ pākamaśnute" },
      { type: "verse", number: "27", sanskrit: "शिग्रुशणफलचित्रककिण्वनिष्पावसर्षपतिलातसीसक्तुकोलगृहधूमैरम्लपिष्टैः सुखोष्णैः स्निग्धैः सलवणैरुत्कारिकां कृत्वा तथा प्रलिप्यैरण्डपत्रेणावच्छाद्यबध्नीयात्", text: "śigruśaṇaphalacitrakakiṇvaniṣpāvasarṣapatilātasīsaktukolagṛhadhūmairamlapiṣṭaiḥ sukhoṣṇaiḥ snigdhaiḥ salavaṇairutkārikāṃ kṛtvā tathā pralipyairaṇḍapatreṇāvacchādyabadhnīyāt" },
      { type: "verse", number: "28", sanskrit: "पाकाभिमुखे च शोफे यथेष्टमातुरं भोजयेत् पाचनार्थं पाकवेदनाशस्त्रकर्मसहनार्थं च", text: "pākābhimukhe ca śophe yatheṣṭamāturaṃ bhojayet pācanārthaṃ pākavedanāśastrakarmasahanārthaṃ ca" },
      { type: "verse", number: "29", sanskrit: "पक्वे तु यथोक्तेन विधिना शस्त्रमवचारयेत् सुपक्वे पिण्डिते शोफे पीडनैरुपपीडिते दारणं दारणाअर्हस्य दोषपाकोद्धते हितम्", text: "pakve tu yathoktena vidhinā śastramavacārayet supakve piṇḍite śophe pīḍanairupapīḍite dāraṇaṃ dāraṇāarhasya doṣapākoddhate hitam" },
      { type: "verse", number: "30", sanskrit: "चित्रकचिरबिल्वदन्तीकरवीरमूलकपोतपङ्कगृध्रपुरीषैर्गुग्गुल्वतसीस्नुहीक्षीरपलाशक्षारसुवर्णक्षीरीदक्षशकृन्मुकूलकैर्वा क्षारौषधैर्वा क्षारेण वा", text: "citrakacirabilvadantīkaravīramūlakapotapaṅkagṛdhrapurīṣairguggulvatasīsnuhīkṣīrapalāśakṣārasuvarṇakṣīrīdakṣaśakṛnmukūlakairvā kṣārauṣadhairvā kṣāreṇa vā" },
      { type: "verse", number: "31", sanskrit: "पूयगर्भानणुद्वारान् सोत्सङ्गान् मर्मगानपि निःस्रेहैः पीडनद्रव्यैः समन्तात्प्रतिपीडयेत्", text: "pūyagarbhānaṇudvārān sotsaṅgān marmagānapi niḥsrehaiḥ pīḍanadravyaiḥ samantātpratipīḍayet" },
      { type: "verse", number: "32", sanskrit: "शुष्यन्तं समुपेक्षेत प्रलेपं पीडनं प्रति न मुखे चैनमालिम्पेत्तथा दोषः प्रसिच्यते", text: "śuṣyantaṃ samupekṣeta pralepaṃ pīḍanaṃ prati na mukhe cainamālimpettathā doṣaḥ prasicyate" },
      { type: "verse", number: "33", sanskrit: "कलाययवगोधूममुद्गमाषहरेणवः द्रव्याणां पिच्छिलानां च त्वङ्मूलानि प्रपीडने", text: "kalāyayavagodhūmamudgamāṣahareṇavaḥ dravyāṇāṃ picchilānāṃ ca tvaṅmūlāni prapīḍane" },
      { type: "verse", number: "34", sanskrit: "विवर्णान् पिच्छिलान् पूतिगन्धीन् क्लेदरुजावतः व्रणानशुद्धान् विज्ञाय शोधनैरोभिराचरेत्", text: "vivarṇān picchilān pūtigandhīn kledarujāvataḥ vraṇānaśuddhān vijñāya śodhanairobhirācaret" },
      { type: "verse", number: "35", sanskrit: "शङ्खिन्यङ्कोलसुमनःकरवीरसुवर्चलाः त्रिफला खदिरो दार्वी कोलपत्रं पलङ्कषा प्रक्षालने कषायाणि वर्गश्चारग्वधादिकः", text: "śaṅkhinyaṅkolasumanaḥkaravīrasuvarcalāḥ triphalā khadiro dārvī kolapatraṃ palaṅkaṣā prakṣālane kaṣāyāṇi vargaścāragvadhādikaḥ" },
      { type: "verse", number: "36", sanskrit: "पटोलीतिलयष्ट्याह्वत्रिवृद्दन्तीनिशाद्वयम् निम्बपत्राणि चालेपः सपटुर्व्रणशोधनः", text: "paṭolītilayaṣṭyāhvatrivṛddantīniśādvayam nimbapatrāṇi cālepaḥ sapaṭurvraṇaśodhanaḥ" },
      { type: "verse", number: "37", sanskrit: "अजगन्धाजशृङ्गी च गवाक्षी लाङ्गली निशा पूतीकश्चित्रकः पाठा पटोलीवेल्लरेणुकाः", text: "ajagandhājaśṛṅgī ca gavākṣī lāṅgalī niśā pūtīkaścitrakaḥ pāṭhā paṭolīvellareṇukāḥ" },
      { type: "verse", number: "38", sanskrit: "कटुत्रयं यवक्षारो लवणानि सुराष्ट्रजा निकुम्भकुम्भकासीसहरितालमनश्शिलाः कल्काज्यतैलरसजाचूर्णवर्तिषु भेषजम्", text: "kaṭutrayaṃ yavakṣāro lavaṇāni surāṣṭrajā nikumbhakumbhakāsīsaharitālamanaśśilāḥ kalkājyatailarasajācūrṇavartiṣu bheṣajam" },
      { type: "verse", number: "39", sanskrit: "तत्र गम्भीरेषु पित्तात्मकेषु दाहपाकवत्सु व्रणेष्वतीक्ष्णोष्णैरेभिः कार्पासीफलमिश्रं कल्कं घृतं च साधयित्वा योजयेत्", text: "tatra gambhīreṣu pittātmakeṣu dāhapākavatsu vraṇeṣvatīkṣṇoṣṇairebhiḥ kārpāsīphalamiśraṃ kalkaṃ ghṛtaṃ ca sādhayitvā yojayet" },
      { type: "verse", number: "40", sanskrit: "उत्सन्नमांसेष्वल्पस्रावेषु रूक्षेषु तिलापामार्गबृहतीद्वययुक्तैः पूर्वोक्तैः पूतीकादिभिः सर्षपं तैलं च", text: "utsannamāṃseṣvalpasrāveṣu rūkṣeṣu tilāpāmārgabṛhatīdvayayuktaiḥ pūrvoktaiḥ pūtīkādibhiḥ sarṣapaṃ tailaṃ ca" },
      { type: "verse", number: "41", sanskrit: "प्रचलप्रदेशजेषु क्लेदबहुलेषूत्सन्नस्थिरमांसेषु तैलेन चासिध्यत्सु रसक्रियां कुर्यात् यथोक्तानां संशोधनौषधानां कषाये पुनः परिस्राव्याधिशृते मनश्शिलातुवरीकासीसचूर्णप्रतीवापसिद्धां च मातुलुङ्गरसोपेतां सक्षौद्रां युञ्जीत", text: "pracalapradeśajeṣu kledabahuleṣūtsannasthiramāṃseṣu tailena cāsidhyatsu rasakriyāṃ kuryāt yathoktānāṃ saṃśodhanauṣadhānāṃ kaṣāye punaḥ parisrāvyādhiśṛte manaśśilātuvarīkāsīsacūrṇapratīvāpasiddhāṃ ca mātuluṅgarasopetāṃ sakṣaudrāṃ yuñjīta" },
      { type: "verse", number: "42", sanskrit: "मेदोयुक्तेषु गम्भीरेषु क्लेदिषु कल्कैश्चासिध्यस्सु", text: "medoyukteṣu gambhīreṣu klediṣu kalkaiścāsidhyassu" },
      { type: "verse", number: "43", sanskrit: "वचायां सैन्धवे किण्वे कासीसे रजनीद्वये शोधनाग्र्येषु चान्येषु चूर्णं कुर्वीत शोधनम्", text: "vacāyāṃ saindhave kiṇve kāsīse rajanīdvaye śodhanāgryeṣu cānyeṣu cūrṇaṃ kurvīta śodhanam" },
      { type: "verse", number: "44", sanskrit: "अन्तःशल्यानणुद्वारान् गम्भीरान् मांससंश्रितान् सन्धिमर्मनिविष्टांश्च शोधयेद्वर्तिभिर्व्रणान्", text: "antaḥśalyānaṇudvārān gambhīrān māṃsasaṃśritān sandhimarmaniviṣṭāṃśca śodhayedvartibhirvraṇān" },
      { type: "verse", number: "45", sanskrit: "वाताभिभूतान् सास्रावान् धूपयेदुग्रवेदनान् श्रीवेष्टकसर्जरससालदेववारुशिंशपाखदिरासनकैडर्यसारयवमधूच्छिष्टभूर्जपत्रपक्षौमसर्पिर्भिः", text: "vātābhibhūtān sāsrāvān dhūpayedugravedanān śrīveṣṭakasarjarasasāladevavāruśiṃśapākhadirāsanakaiḍaryasārayavamadhūcchiṣṭabhūrjapatrapakṣaumasarpirbhiḥ" },
      { type: "verse", number: "46", sanskrit: "निर्वापयेत् भृशं शीतैः पित्तरक्तविषोल्बणान्", text: "nirvāpayet bhṛśaṃ śītaiḥ pittaraktaviṣolbaṇān" },
      { type: "verse", number: "47", sanskrit: "शुष्काल्पमांसे गम्भीरे व्रण उत्सादनं हितम्", text: "śuṣkālpamāṃse gambhīre vraṇa utsādanaṃ hitam" },
      { type: "verse", number: "48", sanskrit: "अश्वगन्धापामार्गतालपत्रीसुवर्चलाबलातिबलानन्ताधातकीकुसुमसमङ्गाभिः पद्मकादिवर्गेण न्यग्रोधादिना च कल्कस्तथा सर्पींष्यभ्यञ्जनार्थे", text: "aśvagandhāpāmārgatālapatrīsuvarcalābalātibalānantādhātakīkusumasamaṅgābhiḥ padmakādivargeṇa nyagrodhādinā ca kalkastathā sarpīṃṣyabhyañjanārthe" },
      { type: "verse", number: "49", sanskrit: "अद्यान्मांसादमांसानि विधिनोपहितानि च मांसं मांसादमांसेन वर्धते शुद्धचेतसः", text: "adyānmāṃsādamāṃsāni vidhinopahitāni ca māṃsaṃ māṃsādamāṃsena vardhate śuddhacetasaḥ" },
      { type: "verse", number: "50", sanskrit: "उत्सन्नमृदुमांसानां व्रणानामवसादनम्", text: "utsannamṛdumāṃsānāṃ vraṇānāmavasādanam" },
      { type: "verse", number: "51", sanskrit: "मन्थदन्तीशिरीषकरञ्जफलभूर्जग्रन्थिकुक्कुटाण्डत्वक्कपोतकलविङ्कपुरीषनेपालीहरितालचूर्णानि सक्षौद्राणि", text: "manthadantīśirīṣakarañjaphalabhūrjagranthikukkuṭāṇḍAtvakkapotakalaviṅkapurīṣanepālīharitālacūrṇāni sakṣaudrāṇi" },
      { type: "verse", number: "52", sanskrit: "सरुजे कठिने स्तब्धे रूक्षे शुष्यति च व्रणे", text: "saruje kaṭhine stabdhe rūkṣe śuṣyati ca vraṇe" },
      { type: "verse", number: "53", sanskrit: "मार्दवजननार्थं व्रणाविरोधि वातघ्नसिद्धस्य सर्पिषः पानम् तद्विधैरेव च सिद्धं तैलमभ्यङ्गः पूर्वोक्ताश्च स्वेदाः तथा सर्पिर्मज्जवसाभिर्धूपाः सुस्निग्धसक्तुसैन्धवकिण्वतिलपिष्टकृसरपायसानूपवेशवाराःकिञ्चिदुष्णा बहुशः प्रलेपाः", text: "mārdavajananārthaṃ vraṇāvirodhi vātaghnasiddhasya sarpiṣaḥ pānam tadvidhaireva ca siddhaṃ tailamabhyaṅgaḥ pūrvoktāśca svedāḥ tathā sarpirmajjavasābhirdhūpāḥ susnigdhasaktusaindhavakiṇvatilapiṣṭakṛsarapāyasānūpaveśavārāḥkiñciduṣṇā bahuśaḥ pralepāḥ" },
      { type: "verse", number: "54", sanskrit: "पित्तविद्रधिवीसर्पशोफकुष्ठघृतानि च सर्वव्रणेषु योज्यानि पानसेकप्रलेपने", text: "pittavidradhivīsarpaśophakuṣṭhaghṛtāni ca sarvavraṇeṣu yojyāni pānasekapralepane" },
      { type: "verse", number: "55", sanskrit: "अतिमृदुमांसेषु व्रणेषु दारुणीकरणार्थं त्रिफलालोध्राम्रसर्जजम्बूप्रियङ्ग्वशोकवल्कलानि सौराष्ट्रीकासीसरोचनावचूर्णनम् सारैर्गन्धैश्च धूपः", text: "atimṛdumāṃseṣu vraṇeṣu dāruṇīkaraṇārthaṃ triphalālodhrāmrasarjajambūpriyaṅgvaśokavalkalāni saurāṣṭrīkāsīsarocanāvacūrṇanam sārairgandhaiśca dhūpaḥ" },
      { type: "verse", number: "56", sanskrit: "उत्सन्नमांसान् कठिनान् कण्डूयुक्तांश्चिरोत्थितान् व्रणान् सुदुःखशोध्यांश्च शोधयेत् क्षारकर्मणा", text: "utsannamāṃsān kaṭhinān kaṇḍūyuktāṃścirotthitān vraṇān suduḥkhaśodhyāṃśca śodhayet kṣārakarmaṇā" },
      { type: "verse", number: "57", sanskrit: "स्रवन्तो ऽश्मरिजा मूत्रं चान्ये रक्तवाहिनः छिन्नाश्च सन्धयो येषां यथोक्तैर्ये च साधनैः साध्यमाना न सिध्यन्ति शोध्याःस्युस्ते ऽग्निकर्मणा", text: "sravanto 'śmarijā mūtraṃ cānye raktavāhinaḥ chinnāśca sandhayo yeṣāṃ yathoktairye ca sādhanaiḥ sādhyamānā na sidhyanti śodhyāḥsyuste 'gnikarmaṇā" },
      { type: "verse", number: "58", sanskrit: "व्रणानामथ शुद्धानां रोपणानि प्रयोजयेत् असनादिन्यग्रोधादिवर्गधवसल्लकीकुटजत्वचो मञ्जिष्ठासमङ्गामृताश्वगन्धारग्वधधातकीपुष्पाणि पद्मकादिश्च प्रक्षालनादिषु सप्तसु प्रयोज्या इति भवन्ति चात्र", text: "vraṇānāmatha śuddhānāṃ ropaṇāni prayojayet asanādinyagrodhādivargadhavasallakīkuṭajatvaco mañjiṣṭhāsamaṅgāmṛtāśvagandhāragvadhadhātakīpuṣpāṇi padmakādiśca prakṣālanādiṣu saptasu prayojyā iti bhavanti cātra" },
      { type: "verse", number: "59", sanskrit: "उत्सन्नदुष्टपिशिते सङ्क्लिष्टध्यामशोणिते व्रणे प्रच्छर्दनं शस्तं कफदुष्टे विशेषतः", text: "utsannaduṣṭapiśite saṅkliṣṭadhyāmaśoṇite vraṇe pracchardanaṃ śastaṃ kaphaduṣṭe viśeṣataḥ" },
      { type: "verse", number: "60", sanskrit: "विरेचनं पित्तदुष्टे दीर्घकालानुबन्धिनि रूक्षे सवेदने बस्तिरधःकाये विशेषतः", text: "virecanaṃ pittaduṣṭe dīrghakālānubandhini rūkṣe savedane bastiradhaḥkāye viśeṣataḥ" },
      { type: "verse", number: "61", sanskrit: "जत्रूर्ध्वजे च श्वयथौ कण्ड्वाढ्ये तीक्ष्णनावनम् तज्ज एवानिलाढ्ये तु श्वयथौ स्नेहनावनम्", text: "jatrūrdhvaje ca śvayathau kaṇḍvāḍhye tīkṣṇanāvanam tajja evānilāḍhye tu śvayathau snehanāvanam" },
      { type: "verse", number: "62", sanskrit: "तथा सशोफरुक्स्रावे धूमो वातकफोल्बणे रुजादिमति वक्त्रस्थे यथास्वं कवलो हितः", text: "tathā saśopharuksrāve dhūmo vātakapholbaṇe rujādimati vaktrasthe yathāsvaṃ kavalo hitaḥ" },
      { type: "verse", number: "63", sanskrit: "द्वावाद्यौ पञ्चमूलाख्यौ गणो यश्चानिलापहः ते व्रणे वातिके योज्याः कषायादिषु सप्प्तसु", text: "dvāvādyau pañcamūlākhyau gaṇo yaścānilāpahaḥ te vraṇe vātike yojyāḥ kaṣāyādiṣu sapptasu" },
      { type: "verse", number: "64", sanskrit: "न्यग्रोधपद्मकाद्यौ तु पैत्ते वर्गश्च पित्तजित् आरग्वधादिः श्लेष्मघ्रः कफे मिश्रास्तु मिश्रजे", text: "nyagrodhapadmakādyau tu paitte vargaśca pittajit āragvadhādiḥ śleṣmaghraḥ kaphe miśrāstu miśraje" },
      { type: "verse", number: "65", sanskrit: "पिष्टोम्लैर्वातिके लेपस्तैलसर्पिर्वसायुतः घनः कोष्णश्च पैत्ते तु पयःपिष्टो घृतान्वितः", text: "piṣṭomlairvātike lepastailasarpirvasāyutaḥ ghanaḥ koṣṇaśca paitte tu payaḥpiṣṭo ghṛtānvitaḥ" },
      { type: "verse", number: "66", sanskrit: "तनुवस्त्रान्तरः शश्वदुष्णो गोमूत्रपेषितः रूक्षस्तैलेन वा स्निग्धो बहलः कफजे हितः", text: "tanuvastrāntaraḥ śaśvaduṣṇo gomūtrapeṣitaḥ rūkṣastailena vā snigdho bahalaḥ kaphaje hitaḥ" },
      { type: "verse", number: "67", sanskrit: "अपेतपूतिमांसानां मांसस्थानामरोहताम् कल्कं संरोहणं कुर्यात्तिलानां मधुकान्वितम् स्निग्धोष्णतिक्तमधुरकषायत्वैः स सर्वजित्", text: "apetapūtimāṃsānāṃ māṃsasthānāmarohatām kalkaṃ saṃrohaṇaṃ kuryāttilānāṃ madhukānvitam snigdhoṣṇatiktamadhurakaṣāyatvaiḥ sa sarvajit" },
      { type: "verse", number: "68", sanskrit: "स क्षौद्रनिम्बपत्राभ्यां युक्तः संशोधनः परम् पूर्वाभ्यां सर्पिषा चासौ युक्तः स्यादाशु रोपणः तिलवद्यवकल्कं तु केचिदिच्छन्ति तद्विदः", text: "sa kṣaudranimbapatrābhyāṃ yuktaḥ saṃśodhanaḥ param pūrvābhyāṃ sarpiṣā cāsau yuktaḥ syādāśu ropaṇaḥ tilavadyavakalkaṃ tu kecidicchanti tadvidaḥ" },
      { type: "verse", number: "69", sanskrit: "सास्रपित्तविषागन्तुगम्भीरान् सोष्मणो व्रणान् क्षीररोपणभैषज्यशृतेनाज्येन रोपयेत् रोपणौषधसिद्धेन तैलेन कफवातजान्", text: "sāsrapittaviṣāgantugambhīrān soṣmaṇo vraṇān kṣīraropaṇabhaiṣajyaśṛtenājyena ropayet ropaṇauṣadhasiddhena tailena kaphavātajān" },
      { type: "verse", number: "70", sanskrit: "अबध्यानां चलस्थानां शुद्धानां वा प्रदुष्यताम् यथास्वं रोपणैः कुर्याद्रसजां सनिशाद्वयैः", text: "abadhyānāṃ calasthānāṃ śuddhānāṃ vā praduṣyatām yathāsvaṃ ropaṇaiḥ kuryādrasajāṃ saniśādvayaiḥ" },
      { type: "verse", number: "71", sanskrit: "समानां स्थिरमांसानां त्वक्स्थानां चूर्ण इष्यते नीरुजामवगाढानां शुद्धानां वर्तयो हिताः", text: "samānāṃ sthiramāṃsānāṃ tvaksthānāṃ cūrṇa iṣyate nīrujāmavagāḍhānāṃ śuddhānāṃ vartayo hitāḥ" },
      { type: "verse", number: "72", sanskrit: "समङ्गामोचसरलसोमवल्काः सचन्दनाः पद्मकादिश्च कल्कोयं परमं रोपणो ऽथवा पुण्ड्राह्वतिलजीवन्तीगोजिह्वाधातकीबलाः", text: "samaṅgāmocasaralasomavalkāḥ sacandanāḥ padmakādiśca kalkoyaṃ paramaṃ ropaṇo 'thavā puṇḍrāhvatilajīvantīgojihvādhātakībalāḥ" },
      { type: "verse", number: "73", sanskrit: "प्रप्रौण्डरीकमधुककाकोलीद्वयचन्दनःइ साधितं तैलमाज्यं वा तद्वत् कम्पिल्लकेन वा दूर्वारसेन वा दार्व्यास्त्वचा वा व्रणरोपणम्", text: "praprauṇḍarīkamadhukakākolīdvayacandanaḥi sādhitaṃ tailamājyaṃ vā tadvat kampillakena vā dūrvārasena vā dārvyāstvacā vā vraṇaropaṇam" },
      { type: "verse", number: "74", sanskrit: "पटोलनिम्बपत्राणि लोध्रमुस्ताप्रियङ्गवः सूक्ष्मैलाधातकीसर्ज्जखदिरागरुचन्दनम्", text: "paṭolanimbapatrāṇi lodhramustāpriyaṅgavaḥ sūkṣmailādhātakīsarjjakhadirāgarucandanam" },
      { type: "verse", number: "75", sanskrit: "कम्पिल्लकं विडङ्गानि वत्सकं त्रिफला बला कल्कैरेभिर्घृतं सिद्धं तैलं वा रोपणं परम्", text: "kampillakaṃ viḍaṅgāni vatsakaṃ triphalā balā kalkairebhirghṛtaṃ siddhaṃ tailaṃ vā ropaṇaṃ param" },
      { type: "verse", number: "76", sanskrit: "पद्मकं पद्मकिञ्जल्कं दार्वी मूर्वा तिलोत्पलम् मेदा समङ्गा यष्ट्याह्वं प्रलेपो वर्णसाधनः", text: "padmakaṃ padmakiñjalkaṃ dārvī mūrvā tilotpalam medā samaṅgā yaṣṭyāhvaṃ pralepo varṇasādhanaḥ" },
      { type: "verse", number: "77", sanskrit: "ककुभोदुम्बराश्वत्थजम्बूकट्फललोध्रजैः त्वचमाशु निगृह्णन्ति त्वक्चूर्णैश्चूर्णिता व्रणाः", text: "kakubhodumbarāśvatthajambūkaṭphalalodhrajaiḥ tvacamāśu nigṛhṇanti tvakcūrṇaiścūrṇitā vraṇāḥ" },
      { type: "verse", number: "78", sanskrit: "लाक्षामनोह्वामञ्जिष्ठाहरितालनिशाद्वयैः प्रलेपः सघृतक्षौद्रस्त्वग्विशुद्धिकरः परम्", text: "lākṣāmanohvāmañjiṣṭhāharitālaniśādvayaiḥ pralepaḥ saghṛtakṣaudrastvagviśuddhikaraḥ param" },
      { type: "verse", number: "79", sanskrit: "ध्यामकाश्वत्थनिचुलमूलं लाक्षालगैरिकम् सहेमश्चामृतासङ्गःकासीसं चेति वर्णकृत्", text: "dhyāmakāśvatthaniculamūlaṃ lākṣālagairikam sahemaścāmṛtāsaṅgaḥkāsīsaṃ ceti varṇakṛt" },
      { type: "verse", number: "80", sanskrit: "कालेयकलताम्रास्थिहेमकालारसोत्तमैः लेपः सगोमयरसः सवर्णकरणः परम्", text: "kāleyakalatāmrāsthihemakālārasottamaiḥ lepaḥ sagomayarasaḥ savarṇakaraṇaḥ param" },
      { type: "verse", number: "81", sanskrit: "अयोरजःसकासीसं त्रिफलाकुसुमानि च प्रलेपः कुरुते कार्ष्ण्यं सद्य एव नवत्वचि", text: "ayorajaḥsakāsīsaṃ triphalākusumāni ca pralepaḥ kurute kārṣṇyaṃ sadya eva navatvaci" },
      { type: "verse", number: "82", sanskrit: "दग्धयानूपसत्वानां श्लक्ष्णचूर्णितया त्वचा भल्लाततैलप्लुतया शुक्लमालेपयेद्व्रणम्", text: "dagdhayānūpasatvānāṃ ślakṣṇacūrṇitayā tvacā bhallātatailaplutayā śuklamālepayedvraṇam" },
      { type: "verse", number: "83", sanskrit: "सप्तरात्रिस्थतं क्षीरे छागले रोहिणीफलम् तैनेव पिष्ट्वा सुश्लक्ष्णं कृष्णमालेपयेद्व्रणम्", text: "saptarātristhataṃ kṣīre chāgale rohiṇīphalam taineva piṣṭvā suślakṣṇaṃ kṛṣṇamālepayedvraṇam" },
      { type: "verse", number: "84", sanskrit: "नवं कपालिकामूलं वैदुलं सस्थिराह्वयम् कासीसं मधुकं लेपो व्रणे कृष्णे मधुद्रुतः", text: "navaṃ kapālikāmūlaṃ vaidulaṃ sasthirāhvayam kāsīsaṃ madhukaṃ lepo vraṇe kṛṣṇe madhudrutaḥ" },
      { type: "verse", number: "85", sanskrit: "कपित्थान्मांसमुध्दृत्य मूत्रस्याज्यस्य पूरणम् क्षिपेच्चात्र मनोह्वालवंशनिर्लेखरोचनाः", text: "kapitthānmāṃsamudhdṛtya mūtrasyājyasya pūraṇam kṣipeccātra manohvālavaṃśanirlekharocanāḥ" },
      { type: "verse", number: "86", sanskrit: "कासीसं प्रपुनाटञ्च मासं न्यस्तं ततो भुवि अधो ऽर्जुनस्य तच्छुक्लव्रणालेपः सवर्णकृत्", text: "kāsīsaṃ prapunāṭañca māsaṃ nyastaṃ tato bhuvi adho 'rjunasya tacchuklavraṇālepaḥ savarṇakṛt" },
      { type: "verse", number: "87", sanskrit: "दग्धो वारणदन्तो ऽन्तर्धूमं तैलं रसाञ्जनम् रोमसञ्जननो लेपस्तद्वत्तैलपरिप्लुता चतुष्पान्नखरोमास्थित्वक्शृङ्गखुरजा मषी", text: "dagdho vāraṇadanto 'ntardhūmaṃ tailaṃ rasāñjanam romasañjanano lepastadvattailapariplutā catuṣpānnakharomāsthitvakśṛṅgakhurajā maṣī" },
      { type: "verse", number: "88", sanskrit: "जीर्णशाल्योदनं स्निग्धमल्पमुष्णोदकोत्तरम् भुञ्जानो जाङ्गलैर्मांसैः शीघ्रं व्रणमपोहति", text: "jīrṇaśālyodanaṃ snigdhamalpamuṣṇodakottaram bhuñjāno jāṅgalairmāṃsaiḥ śīghraṃ vraṇamapohati" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 31,
    lang: "sa",
    content: [
      { type: "heading", heading: "Стхавара виша — растительные яды" },
      { type: "text", text: "Глава 31 Уттара стханы — «Стхавара виша» — посвящена специализированному разделу: растительные яды. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः सद्योव्रणप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ sadyovraṇapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "आगन्तोर्व्रणस्य प्रागुपदिष्टः सम्भवः तत्र तत्र यथायथं प्रतीकारश्च विविधाभिघातजनितैस्तु सुबह्वाकृतिभिरपि सद्योव्रणैरधिष्ठितमङ्गं समासात् त्रिविधं भवति छिन्नं विद्धं पिच्चितं च त्रिविधमपि चैतत्त्वगादिक्षणनात् क्षतमित्युच्यते", text: "āgantorvraṇasya prāgupadiṣṭaḥ sambhavaḥ tatra tatra yathāyathaṃ pratīkāraśca vividhābhighātajanitaistu subahvākṛtibhirapi sadyovraṇairadhiṣṭhitamaṅgaṃ samāsāt trividhaṃ bhavati chinnaṃ viddhaṃ piccitaṃ ca trividhamapi caitattvagādikṣaṇanāt kṣatamityucyate" },
      { type: "verse", number: "3", sanskrit: "तत्र छिन्नं पञ्चधा भिद्यते तद्यथा त्वक्छेदे घृष्टम् किञ्चिन्मांसस्याप्यवकृत्तम् तस्यैवावगाढस्य विशेषेण विशालमायतं च विच्छिन्नम् किञ्चिच्छेषेष्वस्थिस्नाय्वादिषु विलम्बितम् अशेषाङ्गछेदे पातितम्", text: "tatra chinnaṃ pañcadhā bhidyate tadyathā tvakchede ghṛṣṭam kiñcinmāṃsasyāpyavakṛttam tasyaivāvagāḍhasya viśeṣeṇa viśālamāyataṃ ca vicchinnam kiñciccheṣeṣvasthisnāyvādiṣu vilambitam aśeṣāṅgachede pātitam" },
      { type: "verse", number: "4", sanskrit: "विद्धं त्वष्टविधम् तत्र मांसमनुप्राप्ते शल्ये ऽनुविद्धम् द्वितीये पार्श्वे त्वचमुन्नाम्योत्तुण्डितम् किञ्चिन्निस्सृते ऽतिविद्धम् सर्वथा निस्सृते निर्विद्धम् एतदेव चतुर्विधं कोष्ठे पृथुमुखैर्वा प्रहरणैः कुन्तादिभिर्विद्धमनुभिन्नं भिन्नोत्तुण्डितमतिभिन्नं निर्भिन्नमिति च संज्ञां लभते", text: "viddhaṃ tvaṣṭavidham tatra māṃsamanuprāpte śalye 'nuviddham dvitīye pārśve tvacamunnāmyottuṇḍitam kiñcinnissṛte 'tividdham sarvathā nissṛte nirviddham etadeva caturvidhaṃ koṣṭhe pṛthumukhairvā praharaṇaiḥ kuntādibhirviddhamanubhinnaṃ bhinnottuṇḍitamatibhinnaṃ nirbhinnamiti ca saṃjñāṃ labhate" },
      { type: "verse", number: "5", sanskrit: "यत् पुनः प्रहारेण पीडनेन वा गात्रमस्थियुक्तमसृङ्मज्जप्लुतं पृथुतामापद्यते तत् पिच्चितम् तत् द्विविधम् सव्रणमव्रणं च तत्र सव्रणमुक्तम् अव्रणं पुनर्भङ्गेषूपदेक्ष्यते भवति चात्र", text: "yat punaḥ prahāreṇa pīḍanena vā gātramasthiyuktamasṛṅmajjaplutaṃ pṛthutāmāpadyate tat piccitam tat dvividham savraṇamavraṇaṃ ca tatra savraṇamuktam avraṇaṃ punarbhaṅgeṣūpadekṣyate bhavati cātra" },
      { type: "verse", number: "6", sanskrit: "सद्यः सद्योव्रणं सिञ्चेद्यष्टीमधुकसर्पिषा तीव्रव्यथं कवोष्णेन बलातैलेन वा पुनः", text: "sadyaḥ sadyovraṇaṃ siñcedyaṣṭīmadhukasarpiṣā tīvravyathaṃ kavoṣṇena balātailena vā punaḥ" },
      { type: "verse", number: "7", sanskrit: "क्षतोष्माणो निग्रहार्थं तत्कालविसृतस्य च कषायशीतमधुरस्निग्धा लेपादयो हिताः", text: "kṣatoṣmāṇo nigrahārthaṃ tatkālavisṛtasya ca kaṣāyaśītamadhurasnigdhā lepādayo hitāḥ" },
      { type: "verse", number: "8", sanskrit: "सद्योव्रणेष्वायतेषु सन्धानार्थं विशेषतः मधुसर्पिःप्रयुञ्जीत पित्तघ्नीश्च हिमाः क्रियाः", text: "sadyovraṇeṣvāyateṣu sandhānārthaṃ viśeṣataḥ madhusarpiḥprayuñjīta pittaghnīśca himāḥ kriyāḥ" },
      { type: "verse", number: "9", sanskrit: "ससंरम्भेषु कर्तव्यमूर्ध्वं चाधश्च शोधनम् उपवासो हितं भक्तं प्रततं रक्तमोक्षणम्", text: "sasaṃrambheṣu kartavyamūrdhvaṃ cādhaśca śodhanam upavāso hitaṃ bhaktaṃ pratataṃ raktamokṣaṇam" },
      { type: "verse", number: "10", sanskrit: "घृष्टपिच्चितयोरेष सुतरामिष्यते विधिः तयोर्ह्यल्पं स्रवत्यस्रं पाकस्तेनाशु जायते", text: "ghṛṣṭapiccitayoreṣa sutarāmiṣyate vidhiḥ tayorhyalpaṃ sravatyasraṃ pākastenāśu jāyate" },
      { type: "verse", number: "11", sanskrit: "अत्यर्थमस्रं स्रवति प्रायशो ऽन्यत्र विक्षते ततो रक्तक्षयाद्ग्वायौ कुपिते ऽतिरुजाकरे", text: "atyarthamasraṃ sravati prāyaśo 'nyatra vikṣate tato raktakṣayādgvāyau kupite 'tirujākare" },
      { type: "verse", number: "12", sanskrit: "स्नेहपानपरीषेकस्वेदलेपोपनाहनम् स्नेहबस्तिं च कुर्वीत वातघ्नौषधसाधितम्", text: "snehapānaparīṣekasvedalepopanāhanam snehabastiṃ ca kurvīta vātaghnauṣadhasādhitam" },
      { type: "verse", number: "13", sanskrit: "इति साप्ताहिकः प्रोक्तः सद्योव्रणहितो विधिः सप्ताहात् गतवेगे तु पूर्वोक्तं विधिमाच्रेत्", text: "iti sāptāhikaḥ proktaḥ sadyovraṇahito vidhiḥ saptāhāt gatavege tu pūrvoktaṃ vidhimācret" },
      { type: "verse", number: "14", sanskrit: "क्षालनाभ्यङ्गलेपेषु तस्मिन् दुष्टे प्रयोजयेत् आरग्द्वधादिकं वर्गं सुरसादिं च शोधनम्", text: "kṣālanābhyaṅgalepeṣu tasmin duṣṭe prayojayet āragdvadhādikaṃ vargaṃ surasādiṃ ca śodhanam" },
      { type: "verse", number: "15", sanskrit: "कल्कस्त्रिवृत्तिलैरण्डपत्रैर्योज्यः ससैन्धवैः वातिके पैत्तिके कुम्भयष्ट्याह्वरजनीतिलैः श्लैष्मिके तिलतेजोह्वानिकुम्भस्वर्जिकाग्निकैः", text: "kalkastrivṛttilairaṇḍapatrairyojyaḥ sasaindhavaiḥ vātike paittike kumbhayaṣṭyāhvarajanītilaiḥ ślaiṣmike tilatejohvānikumbhasvarjikāgnikaiḥ" },
      { type: "verse", number: "16", sanskrit: "एष दुष्टव्रणविधिः कुष्ठमेहव्रणेष्वपि", text: "eṣa duṣṭavraṇavidhiḥ kuṣṭhamehavraṇeṣvapi" },
      { type: "verse", number: "17", sanskrit: "प्रायः सामान्यकर्मेदं वक्ष्यते तु पृथक् पृथक्", text: "prāyaḥ sāmānyakarmedaṃ vakṣyate tu pṛthak pṛthak" },
      { type: "verse", number: "18", sanskrit: "घृष्टे रुजं निगृह्याशु वर्णे चूर्णानि निक्षिपेत् कल्कादीन्यवकृत्ते तु विच्छिन्नप्रविलम्बिनोः सीवनं विधिनोक्तेन बन्धनं चानुपीडनम्", text: "ghṛṣṭe rujaṃ nigṛhyāśu varṇe cūrṇāni nikṣipet kalkādīnyavakṛtte tu vicchinnapravilambinoḥ sīvanaṃ vidhinoktena bandhanaṃ cānupīḍanam" },
      { type: "verse", number: "19", sanskrit: "असाध्यं स्फुटितं नेत्रमुदीर्णं लम्बते तु यत् सन्निवेश्य यथास्थानमव्याविद्धसिरं भिषक्", text: "asādhyaṃ sphuṭitaṃ netramudīrṇaṃ lambate tu yat sanniveśya yathāsthānamavyāviddhasiraṃ bhiṣak" },
      { type: "verse", number: "20", sanskrit: "पीडयेत् पाणिना पद्मपत्रव्यवहितेन तत् ततो ऽस्य सेचने नस्ये तर्पणे च हितं हविः", text: "pīḍayet pāṇinā padmapatravyavahitena tat tato 'sya secane nasye tarpaṇe ca hitaṃ haviḥ" },
      { type: "verse", number: "21", sanskrit: "विपक्वमाजं यष्ट्याह्वजीवकर्षभकोत्पलैः सपयस्कैः परं तद्धि सर्वनेत्राभिघातजित्", text: "vipakvamājaṃ yaṣṭyāhvajīvakarṣabhakotpalaiḥ sapayaskaiḥ paraṃ taddhi sarvanetrābhighātajit" },
      { type: "verse", number: "22", sanskrit: "गलपीडावसन्नेक्ष्णि वमनो ऽत्कासनक्षवाः प्राणायामो ऽथवा कार्यः क्रिया च क्षतनेत्रवत्", text: "galapīḍāvasannekṣṇi vamano 'tkāsanakṣavāḥ prāṇāyāmo 'thavā kāryaḥ kriyā ca kṣatanetravat" },
      { type: "verse", number: "23", sanskrit: "कर्णे स्थानातुच्युते स्यूते स्रोतस्तैलेन पूरयेत्", text: "karṇe sthānātucyute syūte srotastailena pūrayet" },
      { type: "verse", number: "24", sanskrit: "कृकाटिकायां छिन्नायां निर्गच्छत्यपि मारुते समं निवेश्य बध्नीयात् स्यूत्व शीघ्रं निरन्तरम्", text: "kṛkāṭikāyāṃ chinnāyāṃ nirgacchatyapi mārute samaṃ niveśya badhnīyāt syūtva śīghraṃ nirantaram" },
      { type: "verse", number: "25", sanskrit: "आजेन सर्पिषा चात्र परिषेकः प्रशस्यते उत्तानोन्नानि भुञ्जीत शयीत च सुयन्त्रितः", text: "ājena sarpiṣā cātra pariṣekaḥ praśasyate uttānonnāni bhuñjīta śayīta ca suyantritaḥ" },
      { type: "verse", number: "26", sanskrit: "घातं शाखासु तिर्यक्स्थं गात्रे सम्यङ्निवेशिते स्यूत्वा वेल्लितबन्धेन बध्नीयात् घनवाससा चर्मणा गोष्फणाबन्धः कार्यश्चासङ्गते व्रणे", text: "ghātaṃ śākhāsu tiryaksthaṃ gātre samyaṅniveśite syūtvā vellitabandhena badhnīyāt ghanavāsasā carmaṇā goṣphaṇābandhaḥ kāryaścāsaṅgate vraṇe" },
      { type: "verse", number: "27", sanskrit: "पादौ विलम्बिमुष्कस्य प्रोक्ष्य नेत्रे च वारिणा प्रवेश्य वृषणौ सीव्येत् सीवन्या तुन्नसंज्ञया", text: "pādau vilambimuṣkasya prokṣya netre ca vāriṇā praveśya vṛṣaṇau sīvyet sīvanyā tunnasaṃjñayā" },
      { type: "verse", number: "28", sanskrit: "कार्यश्च गोष्फणाबन्धः कट्यामावेश्य पट्टकम् स्नेहसेकं न कुर्वीत तेन क्लिद्यति हि व्रणः", text: "kāryaśca goṣphaṇābandhaḥ kaṭyāmāveśya paṭṭakam snehasekaṃ na kurvīta tena klidyati hi vraṇaḥ" },
      { type: "verse", number: "29", sanskrit: "कालानुसार्यगुर्वेलाजातीचन्दनपर्पटैः शिलादार्व्यमृतातुत्थैः सिद्धं तैलं च रोपणम्", text: "kālānusāryagurvelājātīcandanaparpaṭaiḥ śilādārvyamṛtātutthaiḥ siddhaṃ tailaṃ ca ropaṇam" },
      { type: "verse", number: "30", sanskrit: "छिन्नां निश्शेषतः शाखां दग्ध्वा तेइलेन युक्तितः बध्नीयात् कोशबन्धेन ततो व्रणवदाचरेत्", text: "chinnāṃ niśśeṣataḥ śākhāṃ dagdhvā teilena yuktitaḥ badhnīyāt kośabandhena tato vraṇavadācaret" },
      { type: "verse", number: "31", sanskrit: "कार्यः शल्याहृते विद्धे क्रमो भङ्गात्तु पिच्चिते", text: "kāryaḥ śalyāhṛte viddhe kramo bhaṅgāttu piccite" },
      { type: "verse", number: "32", sanskrit: "शिरसो ऽपहृते शल्ये बालवर्तिं प्रवेशयेत् मस्तुलुङ्गस्रुतेः क्रुद्धो हन्यादेनं चलो ऽन्यथा व्रणे रोहति चैकेइकं शनैरपनयेत् कचम्", text: "śiraso 'pahṛte śalye bālavartiṃ praveśayet mastuluṅgasruteḥ kruddho hanyādenaṃ calo 'nyathā vraṇe rohati caikeikaṃ śanairapanayet kacam" },
      { type: "verse", number: "33", sanskrit: "मस्तुलुङ्गस्त्रुतौ खादेन्मस्तिष्कानन्यजीवजान् शल्ये हृतेङ्गादन्यस्मात् स्नेहवर्तिं निधापयेत्", text: "mastuluṅgastrutau khādenmastiṣkānanyajīvajān śalye hṛteṅgādanyasmāt snehavartiṃ nidhāpayet" },
      { type: "verse", number: "34", sanskrit: "दूरावगाढाः सूक्ष्मास्या ये व्रणाः स्रुतशोणिताः सेचयेच्चक्रतैलेन सूक्ष्मनेत्रार्पितेन तान्", text: "dūrāvagāḍhāḥ sūkṣmāsyā ye vraṇāḥ srutaśoṇitāḥ secayeccakratailena sūkṣmanetrārpitena tān" },
      { type: "verse", number: "35", sanskrit: "भिन्ने कोष्ठे ऽसृजा पूर्णे मूर्च्छा हृत्पार्श्ववेदनाः ज्वरो दाहस्तृडाध्मानं भक्तस्यानभिनन्दनम्", text: "bhinne koṣṭhe 'sṛjā pūrṇe mūrcchā hṛtpārśvavedanāḥ jvaro dāhastṛḍādhmānaṃ bhaktasyānabhinandanam" },
      { type: "verse", number: "36", sanskrit: "सङ्गो विण्मूत्रमरुतां श्वासः स्वेदोक्षिरक्तता लोहगन्धित्वमास्ये ऽस्य स्यात् गात्रे च विगन्धिता", text: "saṅgo viṇmūtramarutāṃ śvāsaḥ svedokṣiraktatā lohagandhitvamāsye 'sya syāt gātre ca vigandhitā" },
      { type: "verse", number: "37", sanskrit: "आमाशयस्थे रुधिरे रुधिरं छर्दयत्यपि आध्मानेनातिमात्रेण शूलेन च विशस्यते", text: "āmāśayasthe rudhire rudhiraṃ chardayatyapi ādhmānenātimātreṇa śūlena ca viśasyate" },
      { type: "verse", number: "38", sanskrit: "पक्वाशयस्थे रुधिरे सशूलं गौरवं भवेत् नाभेरधस्ताच्छीतत्वं खेभ्यो रक्तस्य चागमः", text: "pakvāśayasthe rudhire saśūlaṃ gauravaṃ bhavet nābheradhastācchītatvaṃ khebhyo raktasya cāgamaḥ" },
      { type: "verse", number: "39", sanskrit: "अभिन्नोप्याशयः सूक्ष्मैः स्रोतोभिरभिपूर्यते असृजा स्यन्दमानेन पार्श्वैर्मूत्रेण बस्तिवत्", text: "abhinnopyāśayaḥ sūkṣmaiḥ srotobhirabhipūryate asṛjā syandamānena pārśvairmūtreṇa bastivat" },
      { type: "verse", number: "40", sanskrit: "तत्रान्तर्लोहितं शीतपादोच्छ्वासकराननम् रक्ताक्षं पण्डुवदनमानद्धं च विवर्जयेत्", text: "tatrāntarlohitaṃ śītapādocchvāsakarānanam raktākṣaṃ paṇḍuvadanamānaddhaṃ ca vivarjayet" },
      { type: "verse", number: "41", sanskrit: "आमाशयस्थे वमनं हितं पक्वाशयाश्रिते विरेचनं निरूहश्च निःस्नेहोष्णैर्विशोधनैः", text: "āmāśayasthe vamanaṃ hitaṃ pakvāśayāśrite virecanaṃ nirūhaśca niḥsnehoṣṇairviśodhanaiḥ" },
      { type: "verse", number: "42", sanskrit: "यवकोलकुलत्थानां रसैः स्नेहविवर्जितैः भुञ्जीतान्नंयवागूं वा पिबेत् सैन्धवसंयुताम्", text: "yavakolakulatthānāṃ rasaiḥ snehavivarjitaiḥ bhuñjītānnaṃyavāgūṃ vā pibet saindhavasaṃyutām" },
      { type: "verse", number: "43", sanskrit: "अतिनिस्सृतरक्तस्तु भिन्नकोष्ठः पिबेदसृक्", text: "atinissṛtaraktastu bhinnakoṣṭhaḥ pibedasṛk" },
      { type: "verse", number: "44", sanskrit: "क्लिष्टच्छिन्नान्त्रभेदेन कोष्ठभेदो द्विधा स्मृतः मूर्च्छादयो ऽल्पाः प्रथमे द्वितीयेत्वतिबाधकाः क्लिष्टान्त्रः संशये देही छिन्नान्त्रो नैव जीवति", text: "kliṣṭacchinnāntrabhedena koṣṭhabhedo dvidhā smṛtaḥ mūrcchādayo 'lpāḥ prathame dvitīyetvatibādhakāḥ kliṣṭāntraḥ saṃśaye dehī chinnāntro naiva jīvati" },
      { type: "verse", number: "45", sanskrit: "यथास्वं मार्गमापन्ना यस्य विण्मूत्रमारुताः व्युपद्रवः सभिन्ने ऽपि कोष्ठे जीवत्यसंशयम्", text: "yathāsvaṃ mārgamāpannā yasya viṇmūtramārutāḥ vyupadravaḥ sabhinne 'pi koṣṭhe jīvatyasaṃśayam" },
      { type: "verse", number: "46", sanskrit: "अभिन्नमान्त्रं निष्क्रान्तं प्रवेश्यं नत्वतोन्यथा उलुङ्गिलशिरोग्रस्तं तदप्येके वदन्ति तु", text: "abhinnamāntraṃ niṣkrāntaṃ praveśyaṃ natvatonyathā uluṅgilaśirograstaṃ tadapyeke vadanti tu" },
      { type: "verse", number: "47", sanskrit: "प्रक्षाल्य पयसा दिग्धं तृण शोणित पांसुभिः प्रवेशयेत् क्लृप्तनखो घृतेनाक्तं शनैः शनैः क्षीरेणार्द्रीकृतं शुष्कं भूरिसर्पिः परिप्लुतम्", text: "prakṣālya payasā digdhaṃ tṛṇa śoṇita pāṃsubhiḥ praveśayet klṛptanakho ghṛtenāktaṃ śanaiḥ śanaiḥ kṣīreṇārdrīkṛtaṃ śuṣkaṃ bhūrisarpiḥ pariplutam" },
      { type: "verse", number: "48", sanskrit: "अङ्गुल्या प्रमृशेत् कण्ठं जलेनोद्वेजयेच्च तम् तथान्त्राणि विशन्त्यन्तस्तत्कालं पीडयेत च", text: "aṅgulyā pramṛśet kaṇṭhaṃ jalenodvejayecca tam tathāntrāṇi viśantyantastatkālaṃ pīḍayeta ca" },
      { type: "verse", number: "49", sanskrit: "व्रणसौक्ष्म्यात् बहुत्वाद्वा कोष्ठमान्त्रमनाविशत् तत्प्रमाणेन जठरं पाटयित्वा प्रवेशयेत्", text: "vraṇasaukṣmyāt bahutvādvā koṣṭhamāntramanāviśat tatpramāṇena jaṭharaṃ pāṭayitvā praveśayet" },
      { type: "verse", number: "50", sanskrit: "यथास्थानस्थिते सम्यगान्त्रे सीव्येदनु व्रणम् स्थानादपेतमादत्ते जीवितं गुपितं च तत्", text: "yathāsthānasthite samyagāntre sīvyedanu vraṇam sthānādapetamādatte jīvitaṃ gupitaṃ ca tat" },
      { type: "verse", number: "51", sanskrit: "वेष्टयित्वानुपट्टेन घृतेन परिषेचयेत् पाययेत ततः कोष्णं चित्रातैलयुतं पयः मृदुक्रियार्थं शकृतो वायोश्चाधः प्रवृत्तये", text: "veṣṭayitvānupaṭṭena ghṛtena pariṣecayet pāyayeta tataḥ koṣṇaṃ citrātailayutaṃ payaḥ mṛdukriyārthaṃ śakṛto vāyoścādhaḥ pravṛttaye" },
      { type: "verse", number: "52", sanskrit: "त्वगश्वकर्णककुभबदरीसल्लकीधवात् तत्कल्कसाधितं तैलं प्रधानं व्रणरोपणम्", text: "tvagaśvakarṇakakubhabadarīsallakīdhavāt tatkalkasādhitaṃ tailaṃ pradhānaṃ vraṇaropaṇam" },
      { type: "verse", number: "53", sanskrit: "अनुवर्तेत वर्षं च यथोक्तां व्रणयन्त्रणाम्", text: "anuvarteta varṣaṃ ca yathoktāṃ vraṇayantraṇām" },
      { type: "verse", number: "54", sanskrit: "उदरान्मेदसो वर्तिं निर्गतां भस्मना मृदा अवकीर्य कषायैर्वा श्लक्ष्णैर्मूले ततः समम्", text: "udarānmedaso vartiṃ nirgatāṃ bhasmanā mṛdā avakīrya kaṣāyairvā ślakṣṇairmūle tataḥ samam" },
      { type: "verse", number: "55", sanskrit: "दृढं च बध्वा सूत्रेण वर्द्धयेत् कुशलो भिषक् तीक्ष्णेनाग्निप्रतप्तेन शस्त्रेण सकृदेव तु", text: "dṛḍhaṃ ca badhvā sūtreṇa varddhayet kuśalo bhiṣak tīkṣṇenāgniprataptena śastreṇa sakṛdeva tu" },
      { type: "verse", number: "56", sanskrit: "स्यादत्यथा रुगाटोपो मृत्युर्वा छिद्यमानया", text: "syādatyathā rugāṭopo mṛtyurvā chidyamānayā" },
      { type: "verse", number: "57", sanskrit: "सक्षौद्रे च व्रणे बद्धे सुजीर्णेन्ने घृतं पिबेत् क्षीरं वा शर्कराचित्रालाक्षागोक्षुरकैः शृतम् रुग्दाहजित् सयष्ट्याह्वैः परं पूर्वोदितो विधिः", text: "sakṣaudre ca vraṇe baddhe sujīrṇenne ghṛtaṃ pibet kṣīraṃ vā śarkarācitrālākṣāgokṣurakaiḥ śṛtam rugdāhajit sayaṣṭyāhvaiḥ paraṃ pūrvodito vidhiḥ" },
      { type: "verse", number: "58", sanskrit: "मेदोग्रन्थ्युदितं चात्र तैलमभ्यञ्जने हितम्", text: "medogranthyuditaṃ cātra tailamabhyañjane hitam" },
      { type: "verse", number: "59", sanskrit: "तालीसं पद्मकं मांसी हरेण्वगरुचन्दनम् हरिद्रे पद्मबीजानि सोशीरं मधुकं च तैः पक्वं सद्योव्रणेषूक्तं तैलं रोपणमुत्तमम्", text: "tālīsaṃ padmakaṃ māṃsī hareṇvagarucandanam haridre padmabījāni sośīraṃ madhukaṃ ca taiḥ pakvaṃ sadyovraṇeṣūktaṃ tailaṃ ropaṇamuttamam" },
      { type: "verse", number: "60", sanskrit: "मूढप्रहाराभिहते पतिते विषमोच्चकैः कार्यं वातास्रजित्तृप्तिमर्दनाभ्यङ्गसेचनम्", text: "mūḍhaprahārābhihate patite viṣamoccakaiḥ kāryaṃ vātāsrajittṛptimardanābhyaṅgasecanam" },
      { type: "verse", number: "61", sanskrit: "विश्लिष्टदेहं मथितं क्षीणं मर्महतं हतम् वासयेत्तैलपूर्णायां द्रोण्यां मांसरसाशिनम्", text: "viśliṣṭadehaṃ mathitaṃ kṣīṇaṃ marmahataṃ hatam vāsayettailapūrṇāyāṃ droṇyāṃ māṃsarasāśinam" },
      { type: "verse", number: "62", sanskrit: "प्रहर्तृयत्नायुधघातगात्रैः सद्योव्रणाः काममनन्तरूपाः तथापि न त्रित्वमतिक्रमन्ते चयादिभेदैरिव मारुताद्याः", text: "prahartṛyatnāyudhaghātagātraiḥ sadyovraṇāḥ kāmamanantarūpāḥ tathāpi na tritvamatikramante cayādibhedairiva mārutādyāḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 32,
    lang: "sa",
    content: [
      { type: "heading", heading: "Джангама виша — животные яды" },
      { type: "text", text: "Глава 32 Уттара стханы — «Джангама виша» — посвящена специализированному разделу: животные яды. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो भङ्गप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bhaṅgapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "पतनपीडनप्रहाराक्षेपणव्यालदंशनप्रभृतिभिरभिघातविशेषैरनेकविधमस्थिभङ्गमुपदिशन्ति", text: "patanapīḍanaprahārākṣepaṇavyāladaṃśanaprabhṛtibhirabhighātaviśeṣairanekavidhamasthibhaṅgamupadiśanti" },
      { type: "verse", number: "3", sanskrit: "तत्तुभङ्गजातं द्व्यधिष्ठानं सन्धावसन्धौ च तत्र सन्धिमुक्तं षड्विधमुत्पिष्टं विश्लिष्टमवक्षिप्तमतिक्षिप्तं तिर्यक्क्षिप्तं विवर्तितमिति", text: "tattubhaṅgajātaṃ dvyadhiṣṭhānaṃ sandhāvasandhau ca tatra sandhimuktaṃ ṣaḍvidhamutpiṣṭaṃ viśliṣṭamavakṣiptamatikṣiptaṃ tiryakkṣiptaṃ vivartitamiti" },
      { type: "verse", number: "4", sanskrit: "तस्य सामान्यलक्षणं प्रसारणाकुञ्चन विवर्तनाक्षेपणाशक्तिरुग्ररुजता स्पर्शासहिष्णुत्वं च", text: "tasya sāmānyalakṣaṇaṃ prasāraṇākuñcana vivartanākṣepaṇāśaktirugrarujatā sparśāsahiṣṇutvaṃ ca" },
      { type: "verse", number: "5", sanskrit: "अथोत्पिष्टे स्वस्थान एव सन्धावुभयतः शोफो वेदना विशेषतश्च रात्रौ भवति विश्लिष्टेल्पशोफो वेदनासातत्यं सन्धिविक्रिया च अवक्षिप्ते सन्धिविश्लेषस्तीव्रा च रुक् अतिक्षिप्ते द्वयोरपि सन्ध्यस्थ्नोरतिक्रान्तता वेदना च तिर्यक् क्षिप्तेत्वेकस्यास्थ्नः पार्श्वतो गमनमत्यर्थं वेदना च विवर्तिते सन्धिपार्श्वगमनाद्विषमाङ्गता वेदना च", text: "athotpiṣṭe svasthāna eva sandhāvubhayataḥ śopho vedanā viśeṣataśca rātrau bhavati viśliṣṭelpaśopho vedanāsātatyaṃ sandhivikriyā ca avakṣipte sandhiviśleṣastīvrā ca ruk atikṣipte dvayorapi sandhyasthnoratikrāntatā vedanā ca tiryak kṣiptetvekasyāsthnaḥ pārśvato gamanamatyarthaṃ vedanā ca vivartite sandhipārśvagamanādviṣamāṅgatā vedanā ca" },
      { type: "verse", number: "6", sanskrit: "असन्धिभग्नं पुनर्द्वादशविधम् तद्यथा कर्कटकं वक्रं स्थुटितं वेल्लितमस्थिच्छल्लिकाश्वकर्णं पिच्चितं दारितं चूर्णितमतिपातितं शेषितं मज्जानुगतमिति", text: "asandhibhagnaṃ punardvādaśavidham tadyathā karkaṭakaṃ vakraṃ sthuṭitaṃ vellitamasthicchallikāśvakarṇaṃ piccitaṃ dāritaṃ cūrṇitamatipātitaṃ śeṣitaṃ majjānugatamiti" },
      { type: "verse", number: "7", sanskrit: "श्वयथुबाहुल्यं स्पन्दनं विवर्तनं स्पर्शासहिष्णुता च पीड्यमाने शब्दः स्रस्ताङ्गता वेदनातिप्रवृत्तिः सर्वासु चावस्थासु शर्म न लभत इति साधारणमसन्धिभग्नरूपम्", text: "śvayathubāhulyaṃ spandanaṃ vivartanaṃ sparśāsahiṣṇutā ca pīḍyamāne śabdaḥ srastāṅgatā vedanātipravṛttiḥ sarvāsu cāvasthāsu śarma na labhata iti sādhāraṇamasandhibhagnarūpam" },
      { type: "verse", number: "8", sanskrit: "वैशेषिकं तु संव्यूढमुभयतोस्थिमध्यभग्नं ग्रन्थिरिवोन्नतं कर्कटकानुकारि कर्कटकम्", text: "vaiśeṣikaṃ tu saṃvyūḍhamubhayatosthimadhyabhagnaṃ granthirivonnataṃ karkaṭakānukāri karkaṭakam" },
      { type: "verse", number: "9", sanskrit: "आभुग्नमविमुक्तमस्थि वक्रम् शूकपूर्णमिवाध्मातं विपुलैकदारि स्फुटितम्", text: "ābhugnamavimuktamasthi vakram śūkapūrṇamivādhmātaṃ vipulaikadāri sphuṭitam" },
      { type: "verse", number: "10", sanskrit: "द्विधाभूतं वेल्लते प्रकम्पमानं वेल्लितकम्", text: "dvidhābhūtaṃ vellate prakampamānaṃ vellitakam" },
      { type: "verse", number: "11", sanskrit: "पार्श्वतो ऽस्थि हीनमुद्गतमस्थिच्छल्लिका", text: "pārśvato 'sthi hīnamudgatamasthicchallikā" },
      { type: "verse", number: "12", sanskrit: "अश्वकर्णवदुद्गतमश्वकर्णम्", text: "aśvakarṇavadudgatamaśvakarṇam" },
      { type: "verse", number: "13", sanskrit: "पृथुतां गतमनल्पशोफं पिच्चितम्", text: "pṛthutāṃ gatamanalpaśophaṃ piccitam" },
      { type: "verse", number: "14", sanskrit: "अणुबहुविदारि वेदनावच्च दारितम्", text: "aṇubahuvidāri vedanāvacca dāritam" },
      { type: "verse", number: "15", sanskrit: "स्पृश्यमानं शब्दवच्चूर्णितम्", text: "spṛśyamānaṃ śabdavaccūrṇitam" },
      { type: "verse", number: "16", sanskrit: "अस्थ्यवयवोस्थिमध्यमनुप्रविशन्नतिपातितम्", text: "asthyavayavosthimadhyamanupraviśannatipātitam" },
      { type: "verse", number: "17", sanskrit: "अन्यतरपार्श्वावशिष्टं शेषितम्", text: "anyatarapārśvāvaśiṣṭaṃ śeṣitam" },
      { type: "verse", number: "18", sanskrit: "क्षतं भग्नमुन्नम्यमानं मज्ञि मज्जति मज्जानुगतम्", text: "kṣataṃ bhagnamunnamyamānaṃ majñi majjati majjānugatam" },
      { type: "verse", number: "19", sanskrit: "एषामन्त्यानि पञ्च कृच्छ्रसाध्यानि कृशातिबालवृद्धासहानामत्याशिनां वातात्मकानां कुष्ठिनामुपद्रववतां च", text: "eṣāmantyāni pañca kṛcchrasādhyāni kṛśātibālavṛddhāsahānāmatyāśināṃ vātātmakānāṃ kuṣṭhināmupadravavatāṃ ca" },
      { type: "verse", number: "20", sanskrit: "असाध्यं तु भिन्नं कटीकपालं सन्धिमुक्तं वा जघनमुत्पिष्टं कूर्परो विवर्तितस्तथा ललाटं चूर्णितमसंश्लिष्टकपालं च शिरः शंखपृष्ठस्तनान्तरभङ्गं चेति भवन्ति चात्र", text: "asādhyaṃ tu bhinnaṃ kaṭīkapālaṃ sandhimuktaṃ vā jaghanamutpiṣṭaṃ kūrparo vivartitastathā lalāṭaṃ cūrṇitamasaṃśliṣṭakapālaṃ ca śiraḥ śaṃkhapṛṣṭhastanāntarabhaṅgaṃ ceti bhavanti cātra" },
      { type: "verse", number: "21", sanskrit: "अथावनतमुन्नाम्यमुन्नतं चावपीडयेत् आञ्छेदधिक्षिप्तमधोगतं चोपरि वर्तयेत् आञ्छनोत्पडिनोन्नामचर्मसङ्क्षेपबन्धनैः", text: "athāvanatamunnāmyamunnataṃ cāvapīḍayet āñchedadhikṣiptamadhogataṃ copari vartayet āñchanotpaḍinonnāmacarmasaṅkṣepabandhanaiḥ" },
      { type: "verse", number: "22", sanskrit: "सन्धीन् शरीरगान् सर्वांश्चलानप्यचलानपि इत्येतैः स्थापनोपायैः सम्यक्संस्थाप्य निश्चलम् पट्टैः प्रभूतसर्पिर्भिर्वेष्टयित्वा सुखैस्ततः", text: "sandhīn śarīragān sarvāṃścalānapyacalānapi ityetaiḥ sthāpanopāyaiḥ samyaksaṃsthāpya niścalam paṭṭaiḥ prabhūtasarpirbhirveṣṭayitvā sukhaistataḥ" },
      { type: "verse", number: "23", sanskrit: "कदम्बोदुम्बराश्वथसर्जार्जुनपलाशजैः वंशोद्भवैर्वा पृथुभिस्तनुभिः सुनिवेशितैः", text: "kadambodumbarāśvathasarjārjunapalāśajaiḥ vaṃśodbhavairvā pṛthubhistanubhiḥ suniveśitaiḥ" },
      { type: "verse", number: "24", sanskrit: "सुश्लक्ष्णैः सप्रतिष्टम्भैर्वल्कलैः शकलैरपि कुशाह्वयैः समं बन्धं पट्टस्योपरि योजयेत्", text: "suślakṣṇaiḥ sapratiṣṭambhairvalkalaiḥ śakalairapi kuśāhvayaiḥ samaṃ bandhaṃ paṭṭasyopari yojayet" },
      { type: "verse", number: "25", sanskrit: "शिथिलेन हि हि बन्धेन सन्धिस्थैर्यं न जायते गाढेनातिरुजादाहपाकश्वयथुसम्भवः", text: "śithilena hi hi bandhena sandhisthairyaṃ na jāyate gāḍhenātirujādāhapākaśvayathusambhavaḥ" },
      { type: "verse", number: "26", sanskrit: "त्र्यहात्त्र्यहादृतौ घर्मे सप्ताहन्मोक्षयेद्धिमे साधारणे तु पञ्चाहात् भङ्गदोषवशेन वा", text: "tryahāttryahādṛtau gharme saptāhanmokṣayeddhime sādhāraṇe tu pañcāhāt bhaṅgadoṣavaśena vā" },
      { type: "verse", number: "27", sanskrit: "न्यग्रोधादिकषायेण ततः शीतेन सेचयेत् तं पञ्चमूलपक्वेन पयसा तु सवेदनम्", text: "nyagrodhādikaṣāyeṇa tataḥ śītena secayet taṃ pañcamūlapakvena payasā tu savedanam" },
      { type: "verse", number: "28", sanskrit: "सुखोष्णं चावचार्यं स्याच्चक्रतैलं विजानता विभज्य देशं कालं च वातघ्नौषधसंयुतम्", text: "sukhoṣṇaṃ cāvacāryaṃ syāccakratailaṃ vijānatā vibhajya deśaṃ kālaṃ ca vātaghnauṣadhasaṃyutam" },
      { type: "verse", number: "29", sanskrit: "प्रततं लेपसेकांश्च विदध्यात् भृशशीतलान् गृष्टिक्षीरं ससर्पिष्कं मधुरौषधसाधितम् प्रातः प्रातः पिबेत् भग्नः शीतलं लाक्षयायुतम्", text: "pratataṃ lepasekāṃśca vidadhyāt bhṛśaśītalān gṛṣṭikṣīraṃ sasarpiṣkaṃ madhurauṣadhasādhitam prātaḥ prātaḥ pibet bhagnaḥ śītalaṃ lākṣayāyutam" },
      { type: "verse", number: "30", sanskrit: "सव्रणस्य तु भग्नस्य व्रणो मधुघृतोत्तरैः कषायैः प्रतिसार्यो ऽथ शेषो भङ्गोदितः क्रमः", text: "savraṇasya tu bhagnasya vraṇo madhughṛtottaraiḥ kaṣāyaiḥ pratisāryo 'tha śeṣo bhaṅgoditaḥ kramaḥ" },
      { type: "verse", number: "31", sanskrit: "लम्बानि व्रणमांसानि प्रलिप्य मधुसर्पिषा सन्दधीत व्रणान् वैद्यो बन्धनैश्चोपपादयेत्", text: "lambāni vraṇamāṃsāni pralipya madhusarpiṣā sandadhīta vraṇān vaidyo bandhanaiścopapādayet" },
      { type: "verse", number: "32", sanskrit: "तान्समान्सुस्थितान्ज्ञात्वा फलिनीलोध्रकट्फलैः समङ्गाधातकीयुक्तैश्चूर्णितैरवचूर्णयेत्", text: "tānsamānsusthitānjñātvā phalinīlodhrakaṭphalaiḥ samaṅgādhātakīyuktaiścūrṇitairavacūrṇayet" },
      { type: "verse", number: "33", sanskrit: "पञ्चवल्कलचूर्णैर्वा मधुशुक्तसमन्वितैः धातकीलोध्रचूर्णैर्वा रोहन्त्याशु तथा व्रणाः", text: "pañcavalkalacūrṇairvā madhuśuktasamanvitaiḥ dhātakīlodhracūrṇairvā rohantyāśu tathā vraṇāḥ" },
      { type: "verse", number: "34", sanskrit: "विश्लिष्टोत्पिष्टयोः सन्धिमेवमेवाविघट्टयन् उपाचरेद्यथास्वं च विसर्पादीनुपद्रवान्", text: "viśliṣṭotpiṣṭayoḥ sandhimevamevāvighaṭṭayan upācaredyathāsvaṃ ca visarpādīnupadravān" },
      { type: "verse", number: "35", sanskrit: "इति भङ्ग उपक्रान्तः स्थिरधातोरृतौ हिमे मांसलस्याल्पदोषस्य सुसाधो दारुणो ऽन्यथा", text: "iti bhaṅga upakrāntaḥ sthiradhātorṛtau hime māṃsalasyālpadoṣasya susādho dāruṇo 'nyathā" },
      { type: "verse", number: "36", sanskrit: "पूर्वमध्यान्तवयसामेकद्वित्रिगुणैः क्रमात् मासैः स्थैर्यं भवेत् सन्धेर्यथोक्तं भजतां विधिम्", text: "pūrvamadhyāntavayasāmekadvitriguṇaiḥ kramāt māsaiḥ sthairyaṃ bhavet sandheryathoktaṃ bhajatāṃ vidhim" },
      { type: "verse", number: "37", sanskrit: "सामान्यं साधनमिदं विशेषो वक्ष्यतेत्वतः", text: "sāmānyaṃ sādhanamidaṃ viśeṣo vakṣyatetvataḥ" },
      { type: "verse", number: "38", sanskrit: "नखसन्धिं समुत्पिष्टं रक्तानुगतमारया अवमथ्य स्रुते रक्ते शालिपिष्टेन लेपयेत्", text: "nakhasandhiṃ samutpiṣṭaṃ raktānugatamārayā avamathya srute rakte śālipiṣṭena lepayet" },
      { type: "verse", number: "39", sanskrit: "भग्नान् सन्धिविमुक्तांश्च कृत्वा पूर्ववदङ्गुलीन् तनुनावेष्ट्य पट्टेन घृतसेकं प्रदापयेत्", text: "bhagnān sandhivimuktāṃśca kṛtvā pūrvavadaṅgulīn tanunāveṣṭya paṭṭena ghṛtasekaṃ pradāpayet" },
      { type: "verse", number: "40", sanskrit: "चक्रयोगेन मतिमानाञ्छेदूर्वास्थि निर्गतम्", text: "cakrayogena matimānāñchedūrvāsthi nirgatam" },
      { type: "verse", number: "41", sanskrit: "आञ्च्छेदूर्ध्वमधस्ताच्च कटीभग्नं चिकित्सकः", text: "āñcchedūrdhvamadhastācca kaṭībhagnaṃ cikitsakaḥ" },
      { type: "verse", number: "42", sanskrit: "मुसलेनोत्क्षिपेत् कक्षमंससन्धौ विसङ्गते स्थानस्थितं च बध्नीयात् स्वस्तिकेन समाहितः", text: "musalenotkṣipet kakṣamaṃsasandhau visaṅgate sthānasthitaṃ ca badhnīyāt svastikena samāhitaḥ" },
      { type: "verse", number: "43", sanskrit: "कौर्परं तु भिषक्सधिमंगुष्ठेनानुमार्जयेत् अनुमृज्य ततः सन्धिं पीडयेत् कूर्पराच्च्युतम् प्रसार्याकुञ्चयेच्चैनं स्नेहसकं च कारयेत्", text: "kaurparaṃ tu bhiṣaksadhimaṃguṣṭhenānumārjayet anumṛjya tataḥ sandhiṃ pīḍayet kūrparāccyutam prasāryākuñcayeccainaṃ snehasakaṃ ca kārayet" },
      { type: "verse", number: "44", sanskrit: "मणिबन्धे च जानौ च गुल्फे चैषः क्रियाक्रमः", text: "maṇibandhe ca jānau ca gulphe caiṣaḥ kriyākramaḥ" },
      { type: "verse", number: "45", sanskrit: "उभे तले समे कृत्वा तलभग्नस्य दोहिनः बध्नीयादामतैलेन परिषेकं च कारयेत्", text: "ubhe tale same kṛtvā talabhagnasya dohinaḥ badhnīyādāmatailena pariṣekaṃ ca kārayet" },
      { type: "verse", number: "46", sanskrit: "प्राग्गोमयमयं पिण्डं धारयेन्मृन्मयं ततः हस्ते जातबले कार्यं क्रमात् पाषाणधारणम्", text: "prāggomayamayaṃ piṇḍaṃ dhārayenmṛnmayaṃ tataḥ haste jātabale kāryaṃ kramāt pāṣāṇadhāraṇam" },
      { type: "verse", number: "47", sanskrit: "सन्नमुन्नामयेत् स्विन्नमक्षकं मुसलेन तु तथोन्नतं पीडयेत बध्नीयान्निबिडं ततः", text: "sannamunnāmayet svinnamakṣakaṃ musalena tu tathonnataṃ pīḍayeta badhnīyānnibiḍaṃ tataḥ" },
      { type: "verse", number: "48", sanskrit: "ऊरुवच्च विधातव्यं बाहुभङ्गे प्रसाधनम्", text: "ūruvacca vidhātavyaṃ bāhubhaṅge prasādhanam" },
      { type: "verse", number: "49", sanskrit: "ग्रीवायां तु विवृत्तायां प्रविष्टायामधोपि वा अवटावथ हन्वोश्च प्रगृह्योन्नमयेच्छिरः समं कुशाभिर्बध्नीयादुत्तानं शाययेच्च तम्", text: "grīvāyāṃ tu vivṛttāyāṃ praviṣṭāyāmadhopi vā avaṭāvatha hanvośca pragṛhyonnamayecchiraḥ samaṃ kuśābhirbadhnīyāduttānaṃ śāyayecca tam" },
      { type: "verse", number: "50", sanskrit: "हन्वस्थिनी समानीय हनुसन्धौ विसङ्गते स्वेदयित्वा स्थितेसम्यक् पञ्चाङ्गीबन्धमाचरेत् घृतं वातघ्नमधुरैः सिद्धं नस्यं च पूजितम्", text: "hanvasthinī samānīya hanusandhau visaṅgate svedayitvā sthitesamyak pañcāṅgībandhamācaret ghṛtaṃ vātaghnamadhuraiḥ siddhaṃ nasyaṃ ca pūjitam" },
      { type: "verse", number: "51", sanskrit: "दन्तानभग्नांश्चलितान् सरक्तानवपीडयेत् वयस्थस्याम्बुभिः शीतैः परिषिच्य प्रलेपयेत्", text: "dantānabhagnāṃścalitān saraktānavapīḍayet vayasthasyāmbubhiḥ śītaiḥ pariṣicya pralepayet" },
      { type: "verse", number: "52", sanskrit: "बहिर्निर्वापणैरन्तः सन्धानीयैरुपाचरेत् लाद्वयशृते क्षीरे पद्मकादिशृतं घृतम्", text: "bahirnirvāpaṇairantaḥ sandhānīyairupācaret lādvayaśṛte kṣīre padmakādiśṛtaṃ ghṛtam" },
      { type: "verse", number: "53", sanskrit: "नस्यगण्डूषयोर्योज्यं चलद्विजहितानि च कल्कितैस्तद्धितैश्चास्य दन्तमांसानि लेपयेत् त्रीन्मासान्मृदु भुञ्जीत रसान्नं कठिनांस्त्यजेत्", text: "nasyagaṇḍūṣayoryojyaṃ caladvijahitāni ca kalkitaistaddhitaiścāsya dantamāṃsāni lepayet trīnmāsānmṛdu bhuñjīta rasānnaṃ kaṭhināṃstyajet" },
      { type: "verse", number: "54", sanskrit: "नासां विवृत्तां सन्नं वा ऋजूकृत्य शलाकया प्रत्येकं नस्ततो नाडीं द्विमुखीं सम्प्रवेशयेत् ततः पट्टेन संवेष्त्य घृतसेकं प्रदापयेत्", text: "nāsāṃ vivṛttāṃ sannaṃ vā ṛjūkṛtya śalākayā pratyekaṃ nastato nāḍīṃ dvimukhīṃ sampraveśayet tataḥ paṭṭena saṃveṣtya ghṛtasekaṃ pradāpayet" },
      { type: "verse", number: "55", sanskrit: "भग्नं कर्णं घृताभ्यक्तं न्यस्य बन्धेन योजयेत् सद्यःक्षतविधानं च ततः पश्चात् समाचरेत्", text: "bhagnaṃ karṇaṃ ghṛtābhyaktaṃ nyasya bandhena yojayet sadyaḥkṣatavidhānaṃ ca tataḥ paścāt samācaret" },
      { type: "verse", number: "56", sanskrit: "कटीजङ्घोरुभग्नानां कवाटशयनं हितम् यन्त्रणार्थं ततः कीलाः पञ्च कार्या निबन्धनाः जङ्गो रुपार्श्वयोर्द्वौ द्वौ तल एकश्च कीलकः", text: "kaṭījaṅghorubhagnānāṃ kavāṭaśayanaṃ hitam yantraṇārthaṃ tataḥ kīlāḥ pañca kāryā nibandhanāḥ jaṅgo rupārśvayordvau dvau tala ekaśca kīlakaḥ" },
      { type: "verse", number: "57", sanskrit: "श्रोण्यां वा पृष्ट्वंशे वा वक्षस्यक्षकयोस्तथा विमोक्षे भग्नसन्धीनां विधिमेनं समाचरेत्", text: "śroṇyāṃ vā pṛṣṭvaṃśe vā vakṣasyakṣakayostathā vimokṣe bhagnasandhīnāṃ vidhimenaṃ samācaret" },
      { type: "verse", number: "58", sanskrit: "सन्धींश्चिरविमुक्तांस्तु स्निग्धस्विन्नान् मृदूकृतान् ऊक्तैर्विधानैर्बुध्या च यथास्वं स्थानमानयेत्", text: "sandhīṃściravimuktāṃstu snigdhasvinnān mṛdūkṛtān ūktairvidhānairbudhyā ca yathāsvaṃ sthānamānayet" },
      { type: "verse", number: "59", sanskrit: "असन्धिभग्ने रूढे तु विषमोल्बणसाधिते आपोथ्य भग्नं यमयेत्तत्तो भग्नवदाचरेत्", text: "asandhibhagne rūḍhe tu viṣamolbaṇasādhite āpothya bhagnaṃ yamayettatto bhagnavadācaret" },
      { type: "verse", number: "60", sanskrit: "भङ्गो नैति यथा पाकं प्रयतेत तथा भिषक् पक्वमांससिरास्नायुः सन्धिः श्लेषं न गच्छति", text: "bhaṅgo naiti yathā pākaṃ prayateta tathā bhiṣak pakvamāṃsasirāsnāyuḥ sandhiḥ śleṣaṃ na gacchati" },
      { type: "verse", number: "61", sanskrit: "वातव्याधिविनिर्दिष्टान् स्नेहान् भग्नस्य योजयेत् चतुष्प्रयोगान् बल्यांश्च बस्तिकर्म च शीलयेत्", text: "vātavyādhivinirdiṣṭān snehān bhagnasya yojayet catuṣprayogān balyāṃśca bastikarma ca śīlayet" },
      { type: "verse", number: "62", sanskrit: "शालिक्षीररसाज्याद्यैः पौष्टिकैरविदाहिभिः मात्रयोपचरेत् भग्नं सन्धिसंश्लेषकारिभिः", text: "śālikṣīrarasājyādyaiḥ pauṣṭikairavidāhibhiḥ mātrayopacaret bhagnaṃ sandhisaṃśleṣakāribhiḥ" },
      { type: "verse", number: "63", sanskrit: "ग्लानिर्न शस्यते तस्य सन्धिविश्लेषकृद्धि सा", text: "glānirna śasyate tasya sandhiviśleṣakṛddhi sā" },
      { type: "verse", number: "64", sanskrit: "लवणं कटुकं क्षारमम्लं मैथुनमातपम् व्यायामं च न सेवेत भग्नो रूक्षं च भेषजम्", text: "lavaṇaṃ kaṭukaṃ kṣāramamlaṃ maithunamātapam vyāyāmaṃ ca na seveta bhagno rūkṣaṃ ca bheṣajam" },
      { type: "verse", number: "65", sanskrit: "सम्यग्यमितमप्यस्थि दुर्न्यासाद्दुर्निबन्धनात् सङ्क्षोभादपि यत् गच्छेद्विक्रियां तद्विवर्जयेत् आदितो यच्च दुर्जातमस्थि सन्धिरथापि वा", text: "samyagyamitamapyasthi durnyāsāddurnibandhanāt saṅkṣobhādapi yat gacchedvikriyāṃ tadvivarjayet ādito yacca durjātamasthi sandhirathāpi vā" },
      { type: "verse", number: "66", sanskrit: "तरुणास्थीनि भुज्यन्ते भज्यन्ते नलकानि तु कपालानि विभिद्यन्ते स्फुटन्त्यन्यानि भूयसा", text: "taruṇāsthīni bhujyante bhajyante nalakāni tu kapālāni vibhidyante sphuṭantyanyāni bhūyasā" },
      { type: "verse", number: "67", sanskrit: "अनुल्बणमनाविद्धं स्वस्थाने पर्यवस्थितम् अवेदनं च चेष्टायां भग्नं विद्यात् सुसाधितम्", text: "anulbaṇamanāviddhaṃ svasthāne paryavasthitam avedanaṃ ca ceṣṭāyāṃ bhagnaṃ vidyāt susādhitam" },
      { type: "verse", number: "68", sanskrit: "कृष्णास्तिलान्विरजसो दृढवस्त्रबद्धान् सप्तक्षपा बहति वारिणि वासयेत् संशोषयेदनुदिनं प्रतिसार्य चैनान् क्षीरे तथैव मधुकक्वथिते च तोये", text: "kṛṣṇāstilānvirajaso dṛḍhavastrabaddhān saptakṣapā bahati vāriṇi vāsayet saṃśoṣayedanudinaṃ pratisārya cainān kṣīre tathaiva madhukakvathite ca toye" },
      { type: "verse", number: "69", sanskrit: "पुनरपि पीतपयस्कांस्तान् पूर्ववदेव शोषितान् बाढम् विगततुषानरजस्कान् संचूर्ण्य विचूर्णितैर्युञ्ज्यात्", text: "punarapi pītapayaskāṃstān pūrvavadeva śoṣitān bāḍham vigatatuṣānarajaskān saṃcūrṇya vicūrṇitairyuñjyāt" },
      { type: "verse", number: "70", sanskrit: "नलदवालकलोहितयष्टिका नखमिसिप्लवकुष्ठबलात्रयैः अगरुकुङ्कुमचन्दनसारिवा सरलसर्जरसामरदारुभिः", text: "naladavālakalohitayaṣṭikā nakhamisiplavakuṣṭhabalātrayaiḥ agarukuṅkumacandanasārivā saralasarjarasāmaradārubhiḥ" },
      { type: "verse", number: "71", sanskrit: "पद्मकादिगणोपेतैस्तिलपिष्टं ततश्च तत् समस्तगन्धभैषज्यसिद्धदुग्धेन पीडयेत्", text: "padmakādigaṇopetaistilapiṣṭaṃ tataśca tat samastagandhabhaiṣajyasiddhadugdhena pīḍayet" },
      { type: "verse", number: "72", sanskrit: "शैलेयरास्नाशुमतीकशेरुकालानुसारीनतपत्रलोध्रैः सक्षीरशुक्लैः सपयः सदूर्वैस्तैलं पचेत्तन्नलदादिबिश्च", text: "śaileyarāsnāśumatīkaśerukālānusārīnatapatralodhraiḥ sakṣīraśuklaiḥ sapayaḥ sadūrvaistailaṃ pacettannaladādibiśca" },
      { type: "verse", number: "73", sanskrit: "गन्धतैलमिदमुत्तममस्थिस्थैर्यकृज्जयति चाशु विकारान् वातपित्तजनितानतिवीर्यं व्यापिनो ऽपिविविधैरुपयोगैः", text: "gandhatailamidamuttamamasthisthairyakṛjjayati cāśu vikārān vātapittajanitānativīryaṃ vyāpino 'pivividhairupayogaiḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 33,
    lang: "sa",
    content: [
      { type: "heading", heading: "Гара виша — искусственные яды" },
      { type: "text", text: "Глава 33 Уттара стханы — «Гара виша» — посвящена специализированному разделу: искусственные яды. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो भगन्दरप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto bhagandarapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "हस्त्यश्वपृष्ठगमनकठिनोत्कटकासनैः अर्शोनिदानाभिहितैरपरैश्च निषेवितैः", text: "hastyaśvapṛṣṭhagamanakaṭhinotkaṭakāsanaiḥ arśonidānābhihitairaparaiśca niṣevitaiḥ" },
      { type: "verse", number: "3", sanskrit: "अनिष्टदिष्टपाकेन सद्यो वा साधुगर्हणैः प्रायेण पिटकापूर्वो योङ्गुले द्व्यङ्गुलेपि", text: "aniṣṭadiṣṭapākena sadyo vā sādhugarhaṇaiḥ prāyeṇa piṭakāpūrvo yoṅgule dvyaṅgulepi" },
      { type: "verse", number: "4", sanskrit: "पायोर्व्रणो ऽन्तर्बाह्यो वा दुष्टासृङ्मांसगो भवेत् बस्तिमूत्राशयाभ्याशगतत्वात् स्यन्दनात्मकः", text: "pāyorvraṇo 'ntarbāhyo vā duṣṭāsṛṅmāṃsago bhavet bastimūtrāśayābhyāśagatatvāt syandanātmakaḥ" },
      { type: "verse", number: "5", sanskrit: "भगबस्तिगुदान्तेषु दीर्यमाणेषु भूरिभिः वातं मूत्रं शकृच्छुक्रं खैः सूक्ष्मैर्वहति क्रमात्", text: "bhagabastigudānteṣu dīryamāṇeṣu bhūribhiḥ vātaṃ mūtraṃ śakṛcchukraṃ khaiḥ sūkṣmairvahati kramāt" },
      { type: "verse", number: "6", sanskrit: "दोषैः पृथग्युतैः सर्वैरागन्तुः सो ऽष्टमः स्मृतः", text: "doṣaiḥ pṛthagyutaiḥ sarvairāgantuḥ so 'ṣṭamaḥ smṛtaḥ" },
      { type: "verse", number: "7", sanskrit: "अपक्वं पिटकामाहुः पाकप्राप्तं भगन्दरम्", text: "apakvaṃ piṭakāmāhuḥ pākaprāptaṃ bhagandaram" },
      { type: "verse", number: "8", sanskrit: "गूढमूलां ससंरम्भां रूदाढ्यां रूढकोपिनीम् भगन्दरकरीं विद्यात् पिटकां नत्वतोन्यथा", text: "gūḍhamūlāṃ sasaṃrambhāṃ rūdāḍhyāṃ rūḍhakopinīm bhagandarakarīṃ vidyāt piṭakāṃ natvatonyathā" },
      { type: "verse", number: "9", sanskrit: "तत्र श्यावारुणा तोदभेदस्फुरणरुक्वरी पिटका मारुतात् #", text: "tatra śyāvāruṇā todabhedasphuraṇarukvarī piṭakā mārutāt #" },
      { type: "verse", number: "10", sanskrit: "पित्तादुष्ट्रग्रीवावदुच्छ्रिता रागिणी तनुरूष्माढ्या ज्वरधूमायनान्विता", text: "pittāduṣṭragrīvāvaducchritā rāgiṇī tanurūṣmāḍhyā jvaradhūmāyanānvitā" },
      { type: "verse", number: "11", sanskrit: "स्थिरा स्निग्धा महामूला पाण्डुःकण्डूमती कफात्", text: "sthirā snigdhā mahāmūlā pāṇḍuḥkaṇḍūmatī kaphāt" },
      { type: "verse", number: "12", sanskrit: "श्यावाताम्रा सदाहोषा घोररुग्वातपित्तजा", text: "śyāvātāmrā sadāhoṣā ghorarugvātapittajā" },
      { type: "verse", number: "13", sanskrit: "पाण्डुरा किञ्चिदाश्यावा कृच्छ्रपाका कफानिलात्", text: "pāṇḍurā kiñcidāśyāvā kṛcchrapākā kaphānilāt" },
      { type: "verse", number: "14", sanskrit: "पादाङ्गुष्ठसमा सर्वैर्दोषैर्नानाविधव्यथा शूलारोचकतृङ्दाहज्वरच्छार्दिरुपद्रुता", text: "pādāṅguṣṭhasamā sarvairdoṣairnānāvidhavyathā śūlārocakatṛṅdāhajvaracchārdirupadrutā" },
      { type: "verse", number: "15", sanskrit: "व्रणतां यान्ति ताः पक्वाः प्रमादात् तत्र वातजा चीयते ऽणुमुखैश्छिद्रैः शतपोनकवत् क्रमात् अच्छं स्रवद्भिरास्रावमजस्रं फेनसंयुतम्", text: "vraṇatāṃ yānti tāḥ pakvāḥ pramādāt tatra vātajā cīyate 'ṇumukhaiśchidraiḥ śataponakavat kramāt acchaṃ sravadbhirāsrāvamajasraṃ phenasaṃyutam" },
      { type: "verse", number: "16", sanskrit: "शतपोनकसंज्ञो ऽयं उष्ट्रग्रीवस्तु पित्तजः", text: "śataponakasaṃjño 'yaṃ uṣṭragrīvastu pittajaḥ" },
      { type: "verse", number: "17", sanskrit: "बहुपिच्छापरिस्रावी परिस्रावी कफोद्भवः", text: "bahupicchāparisrāvī parisrāvī kaphodbhavaḥ" },
      { type: "verse", number: "18", sanskrit: "वातपित्तात् परिक्षेपी परिक्षिप्य गुदं गतिः जायते परितस्तत्र प्राकारं परिखेव च", text: "vātapittāt parikṣepī parikṣipya gudaṃ gatiḥ jāyate paritastatra prākāraṃ parikheva ca" },
      { type: "verse", number: "19", sanskrit: "ऋजुर्वातकफादृज्व्या गुदो गत्यावदीर्यते", text: "ṛjurvātakaphādṛjvyā gudo gatyāvadīryate" },
      { type: "verse", number: "20", sanskrit: "कफपित्ते तु पूर्वोत्थं दुर्नामाश्रित्य कुप्यतः अर्शोमूले ततः शोफः कण्डूदाहादिमान् भवेत्", text: "kaphapitte tu pūrvotthaṃ durnāmāśritya kupyataḥ arśomūle tataḥ śophaḥ kaṇḍūdāhādimān bhavet" },
      { type: "verse", number: "21", sanskrit: "स शीघ्रं पक्वभिन्नोस्य क्लेदयन् मूलमर्शसः स्रवत्यजस्रं गतिभिरयमर्शोभगन्दरः", text: "sa śīghraṃ pakvabhinnosya kledayan mūlamarśasaḥ sravatyajasraṃ gatibhirayamarśobhagandaraḥ" },
      { type: "verse", number: "22", sanskrit: "सर्वजः शम्बुकावर्तः शम्बुकावर्तसन्निभः गतयो दारयन्त्यस्मिन् रुग्वेगैर्दारुणैर्गुदम्", text: "sarvajaḥ śambukāvartaḥ śambukāvartasannibhaḥ gatayo dārayantyasmin rugvegairdāruṇairgudam" },
      { type: "verse", number: "23", sanskrit: "अस्थिलेशो ऽभ्यवहृतो मांसगृध्या यदा गुदम् क्षिणोति तिर्यङ्निर्गच्छन्नुन्मार्गं च ततो गतिः", text: "asthileśo 'bhyavahṛto māṃsagṛdhyā yadā gudam kṣiṇoti tiryaṅnirgacchannunmārgaṃ ca tato gatiḥ" },
      { type: "verse", number: "24", sanskrit: "स्यात्तदा पूयदीर्णायां मांसकोथेन तत्र च जायन्ते कृमयस्ते ऽस्य खादन्तः परितो गुदम् विदारयन्ति न चिरादुन्मार्गी क्षतजश्च सः", text: "syāttadā pūyadīrṇāyāṃ māṃsakothena tatra ca jāyante kṛmayaste 'sya khādantaḥ parito gudam vidārayanti na cirādunmārgī kṣatajaśca saḥ" },
      { type: "verse", number: "25", sanskrit: "तेषु रुग्दाहकण्ड्वादीन् विद्याद्व्रणविभक्तितः", text: "teṣu rugdāhakaṇḍvādīn vidyādvraṇavibhaktitaḥ" },
      { type: "verse", number: "26", sanskrit: "षट् कृच्छ्रसाधनास्तेषां निचयक्षतजौ त्यजेत् प्रवाहिणीं बलीं प्राप्तं सेवनीं वा समाश्रितम्", text: "ṣaṭ kṛcchrasādhanāsteṣāṃ nicayakṣatajau tyajet pravāhiṇīṃ balīṃ prāptaṃ sevanīṃ vā samāśritam" },
      { type: "verse", number: "27", sanskrit: "अथ भगन्दारिणमपक्वपिटकं पाकपरिहाराथमपतर्पणेन व्रणप्रतिषेधविहितेन शीघ्रमुपाचरेत्", text: "atha bhagandāriṇamapakvapiṭakaṃ pākaparihārāthamapatarpaṇena vraṇapratiṣedhavihitena śīghramupācaret" },
      { type: "verse", number: "28", sanskrit: "पक्वपिटकं पुनरुपस्निग्धमर्कादिक्वाथशुद्धं स्वभ्यक्तमवगाहस्विन्नं भुक्तवन्तं शयनस्थमर्शसमिव यन्त्रयित्वा पराचीनमर्वाचीनं बहिर्मुखमन्तर्मुखं वा भगन्दरं सम्यगीक्षेत", text: "pakvapiṭakaṃ punarupasnigdhamarkādikvāthaśuddhaṃ svabhyaktamavagāhasvinnaṃ bhuktavantaṃ śayanasthamarśasamiva yantrayitvā parācīnamarvācīnaṃ bahirmukhamantarmukhaṃ vā bhagandaraṃ samyagīkṣeta" },
      { type: "verse", number: "29", sanskrit: "ततो ऽन्तर्मुखे यन्त्रं प्राणिधाय प्रवाहणप्रविष्टं भगन्दरमभिसमीक्ष्य सम्यगेषित्वा शस्त्रेण पाटयेत् बहिर्मुखेत्वेषाणीं प्रणिधाय साशयमुद्धरेच्छस्त्रेणानन्तरं चो ऽभयमप्यग्निना क्षारेण चोपत्रमेत उष्ठग्रीवं तु क्षारेणैव", text: "tato 'ntarmukhe yantraṃ prāṇidhāya pravāhaṇapraviṣṭaṃ bhagandaramabhisamīkṣya samyageṣitvā śastreṇa pāṭayet bahirmukhetveṣāṇīṃ praṇidhāya sāśayamuddharecchastreṇānantaraṃ co 'bhayamapyagninā kṣāreṇa copatrameta uṣṭhagrīvaṃ tu kṣāreṇaiva" },
      { type: "verse", number: "30", sanskrit: "ततो निर्वापणशोधनरोपणैर्यथाकालं साधयोदिति सामान्यो विधिः", text: "tato nirvāpaṇaśodhanaropaṇairyathākālaṃ sādhayoditi sāmānyo vidhiḥ" },
      { type: "verse", number: "31", sanskrit: "अथ शतपोनके नाडीरेकान्तरिताः पाटयित्वा रोपयेत् रूढासु चेतराश्चिकित्सेत् अन्यथा तु विवृत्तं व्रणं गुदस्रोतोविदारणाद्वातविण्मूत्राण्यनुप्रपद्यन्ते ततश्चोन्मार्गगो वायुराध्मानाटोपपायुशूलादीनुपजनयति तत्र स्नेहाभ्यक्तगुदस्य स्निग्धान् पिण्डनाडीकुम्भीस्वेदान् प्रयुञ्जीतावगाहं वा स्विन्नं च वच हिंगुकुष्ठव्योषलवणपञ्चकाजमोदान् सर्पिर्मद्याकाञ्जिककुलत्थयूषान्यतमेन पाययेत् व्रणं चास्य मधुकतैलेनोष्णेन सिञ्चेत् गुदं च बलातैलादिभिर्वातघ्नैः अनेन विधिना वाय्वादयः स्वमार्गमापतन्ति तत्कृताश्च विकारा निवर्तन्ते", text: "atha śataponake nāḍīrekāntaritāḥ pāṭayitvā ropayet rūḍhāsu cetarāścikitset anyathā tu vivṛttaṃ vraṇaṃ gudasrotovidāraṇādvātaviṇmūtrāṇyanuprapadyante tataśconmārgago vāyurādhmānāṭopapāyuśūlādīnupajanayati tatra snehābhyaktagudasya snigdhān piṇḍanāḍīkumbhīsvedān prayuñjītāvagāhaṃ vā svinnaṃ ca vaca hiṃgukuṣṭhavyoṣalavaṇapañcakājamodān sarpirmadyākāñjikakulatthayūṣānyatamena pāyayet vraṇaṃ cāsya madhukatailenoṣṇena siñcet gudaṃ ca balātailādibhirvātaghnaiḥ anena vidhinā vāyvādayaḥ svamārgamāpatanti tatkṛtāśca vikārā nivartante" },
      { type: "verse", number: "32", sanskrit: "एवमेव च परिक्षेपिण्यामपि क्रमात् गतिं नाडीविहितेन क्षारसूत्रेण द्विशस्त्रिशोवावदारयेत् सकृदेवह्यवदरणादसाध्यता याप्यता वा स्यात्", text: "evameva ca parikṣepiṇyāmapi kramāt gatiṃ nāḍīvihitena kṣārasūtreṇa dviśastriśovāvadārayet sakṛdevahyavadaraṇādasādhyatā yāpyatā vā syāt" },
      { type: "verse", number: "33", sanskrit: "अर्शोभगन्दरे पूर्वमर्शांसि च्छिन्द्यात् ततो गत्यनुसारेण भगन्दरम्", text: "arśobhagandare pūrvamarśāṃsi cchindyāt tato gatyanusāreṇa bhagandaram" },
      { type: "verse", number: "34", sanskrit: "उन्मार्गिणं तु प्रत्याख्यायोपाचरेत् अनिस्सृतं च शल्यमाहरेत् तथा कृमिघ्नं क्रममालेपाभ्यवहारयोः कुर्वीत वेदनायां तु पूर्वोक्ताः स्वेदाः वचादिपाचनं च साल्वलप्रदिग्धं वा व्रणं कदलीमृगलोपाकाजिनकौशेयाविकैरुपनाहयेदिति भवति चात्र", text: "unmārgiṇaṃ tu pratyākhyāyopācaret anissṛtaṃ ca śalyamāharet tathā kṛmighnaṃ kramamālepābhyavahārayoḥ kurvīta vedanāyāṃ tu pūrvoktāḥ svedāḥ vacādipācanaṃ ca sālvalapradigdhaṃ vā vraṇaṃ kadalīmṛgalopākājinakauśeyāvikairupanāhayediti bhavati cātra" },
      { type: "verse", number: "35", sanskrit: "भगन्दरे बहुच्छिद्रे छेदानालोच्य योजयेत् गोतीर्थं सर्वतोमद्रमर्धलाङ्गललाङ्गलौ", text: "bhagandare bahucchidre chedānālocya yojayet gotīrthaṃ sarvatomadramardhalāṅgalalāṅgalau" },
      { type: "verse", number: "36", sanskrit: "पार्श्वागतेनशस्त्रेण छेदो गोतीर्थको मतः सर्वतः सर्वतोभद्रः पार्श्वच्छेदोर्धलाङ्गलः", text: "pārśvāgatenaśastreṇa chedo gotīrthako mataḥ sarvataḥ sarvatobhadraḥ pārśvacchedordhalāṅgalaḥ" },
      { type: "verse", number: "37", sanskrit: "पार्श्वद्वये लाङ्गलकः समस्तांश्चाग्निना दहेत् आस्रावमार्गान् निश्शेषं नैवं विकुरुते पुनः", text: "pārśvadvaye lāṅgalakaḥ samastāṃścāgninā dahet āsrāvamārgān niśśeṣaṃ naivaṃ vikurute punaḥ" },
      { type: "verse", number: "38", sanskrit: "यतेत् कोष्ठशुध्यै च भिषक् तस्यान्तरान्तरा", text: "yatet koṣṭhaśudhyai ca bhiṣak tasyāntarāntarā" },
      { type: "verse", number: "39", sanskrit: "आर्द्रकस्य रसे सिद्धं कल्के वा पाययेत् घृतम् भगन्दरे मारुतजे पक्वापक्वे विरेचयेत्", text: "ārdrakasya rase siddhaṃ kalke vā pāyayet ghṛtam bhagandare mārutaje pakvāpakve virecayet" },
      { type: "verse", number: "40", sanskrit: "ज्योतिष्मतीलाङ्गलिकाश्यामादन्तीत्रिवृत्तिलाः कुष्ठं शतह्वा गोलोमी तिल्वको गिरिकर्णिका हेमक्षीरी च वर्गोयं लेपाद्यैर्व्रणशोधनः", text: "jyotiṣmatīlāṅgalikāśyāmādantītrivṛttilāḥ kuṣṭhaṃ śatahvā golomī tilvako girikarṇikā hemakṣīrī ca vargoyaṃ lepādyairvraṇaśodhanaḥ" },
      { type: "verse", number: "41", sanskrit: "तिलकुम्भवरादन्ती तुत्थसिन्धूत्थमाक्षिकम् सकृष्णरोचनाकुष्ठं शोधनं मांसकृत् पुनः", text: "tilakumbhavarādantī tutthasindhūtthamākṣikam sakṛṣṇarocanākuṣṭhaṃ śodhanaṃ māṃsakṛt punaḥ" },
      { type: "verse", number: "42", sanskrit: "मञ्जिष्ठासैन्धवक्षौद्रनागदन्तीत्रिवृत्तिलाः रसाञ्जनद्विरजनीतेजोह्वानिम्बपल्लवाः", text: "mañjiṣṭhāsaindhavakṣaudranāgadantītrivṛttilāḥ rasāñjanadvirajanītejohvānimbapallavāḥ" },
      { type: "verse", number: "43", sanskrit: "निकुम्भकुम्भरक्ताह्वकल्को नाडीव्रणापहः", text: "nikumbhakumbharaktāhvakalko nāḍīvraṇāpahaḥ" },
      { type: "verse", number: "44", sanskrit: "सुधाशेलुत्रिवृत्पाठामलयूहयमारकैः ज्योतिष्मतीलाङ्गलिका स्वर्जिकार्कवचाग्निकैः विष्यन्दनाख्यं विपचेत्तैलं शोधनरोपणम्", text: "sudhāśelutrivṛtpāṭhāmalayūhayamārakaiḥ jyotiṣmatīlāṅgalikā svarjikārkavacāgnikaiḥ viṣyandanākhyaṃ vipacettailaṃ śodhanaropaṇam" },
      { type: "verse", number: "45", sanskrit: "त्रिवृद्दन्तीहरिद्रार्कमूललोहाश्वमारकैः विडङ्गसारत्रिफलास्नुगर्कक्षीरमाक्षिकैः तैलं समदनैः सिद्धं भगन्दरनिर्वहणम्", text: "trivṛddantīharidrārkamūlalohāśvamārakaiḥ viḍaṅgasāratriphalāsnugarkakṣīramākṣikaiḥ tailaṃ samadanaiḥ siddhaṃ bhagandaranirvahaṇam" },
      { type: "verse", number: "46", sanskrit: "सैन्धवार्कत्रिवृत्पाठासमङ्गपूतिकाग्निकैः समातुलुङ्गच्छदनैस्तैलंशोधनरोपणम्", text: "saindhavārkatrivṛtpāṭhāsamaṅgapūtikāgnikaiḥ samātuluṅgacchadanaistailaṃśodhanaropaṇam" },
      { type: "verse", number: "47", sanskrit: "मधुतैलयुता विडङ्गसारत्रिफलामागधिकोषणाश्च लीढा कृमिकुष्ठभगन्दरप्रमेहक्षतनाडीव्रणरोपणाभवन्ति", text: "madhutailayutā viḍaṅgasāratriphalāmāgadhikoṣaṇāśca līḍhā kṛmikuṣṭhabhagandarapramehakṣatanāḍīvraṇaropaṇābhavanti" },
      { type: "verse", number: "48", sanskrit: "अमृतात्रुटिवेल्लवत्सकं कलिपथ्यामलका निगुग्गुलुः क्रमवृद्धमिदं मधुप्लुतं पिटकास्थौल्यभगन्दरान् जयेत्", text: "amṛtātruṭivellavatsakaṃ kalipathyāmalakā nigugguluḥ kramavṛddhamidaṃ madhuplutaṃ piṭakāsthaulyabhagandarān jayet" },
      { type: "verse", number: "49", sanskrit: "गुग्गुलुपञ्चपलं पलिकांशा मागधिका त्रिफला च पृथक् स्यात् त्वक्त्रुटिकर्षयुतं मधुलीढं कुष्ठभगन्दरगुल्मगतिघ्नम्", text: "guggulupañcapalaṃ palikāṃśā māgadhikā triphalā ca pṛthak syāt tvaktruṭikarṣayutaṃ madhulīḍhaṃ kuṣṭhabhagandaragulmagatighnam" },
      { type: "verse", number: "50", sanskrit: "शृङ्गवेररजोयुक्तं तदेव च सुभावितम् क्वाथेन दशमूलस्य विशेषाद्वातरोगजित्", text: "śṛṅgaverarajoyuktaṃ tadeva ca subhāvitam kvāthena daśamūlasya viśeṣādvātarogajit" },
      { type: "verse", number: "51", sanskrit: "उत्तमा खदिरसारजं रजः शीलयन्नसनवारिभावितम् हन्ति तुल्यमहिषाक्षमाक्षिकं कुष्ठमेहपिटकाभगन्दरान्", text: "uttamā khadirasārajaṃ rajaḥ śīlayannasanavāribhāvitam hanti tulyamahiṣākṣamākṣikaṃ kuṣṭhamehapiṭakābhagandarān" },
      { type: "verse", number: "52", sanskrit: "भगन्दरेष्वेष विशेष उक्तः शेषाणि तु व्यञ्जनसाधनानि व्रणाधिकारात् परिशीलनाच्च सम्यग्विदित्वौपयिकं विदध्यात्", text: "bhagandareṣveṣa viśeṣa uktaḥ śeṣāṇi tu vyañjanasādhanāni vraṇādhikārāt pariśīlanācca samyagviditvaupayikaṃ vidadhyāt" },
      { type: "verse", number: "53", sanskrit: "अश्वपृष्ठगमनं चलरोधं मद्यमैथुनमजीर्णमसात्म्यम् साहसानि विविधानि च रुढे वत्सरं परिहरेदधिकं वा", text: "aśvapṛṣṭhagamanaṃ calarodhaṃ madyamaithunamajīrṇamasātmyam sāhasāni vividhāni ca ruḍhe vatsaraṃ pariharedadhikaṃ vā" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 34,
    lang: "sa",
    content: [
      { type: "heading", heading: "Виша чикитса — лечение отравлений" },
      { type: "text", text: "Глава 34 Уттара стханы — «Виша чикитса» — посвящена специализированному разделу: лечение отравлений. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो ग्रन्थ्यर्बुदश्लीपदापचीनाडीविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto granthyarbudaślīpadāpacīnāḍīvijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "कफप्रधानाः कुर्वन्ति मेदोमांसास्रगामलाः वृत्तोन्नतं यं श्वयथुं स ग्रन्थिर्ग्रथनात् स्मृतः", text: "kaphapradhānāḥ kurvanti medomāṃsāsragāmalāḥ vṛttonnataṃ yaṃ śvayathuṃ sa granthirgrathanāt smṛtaḥ" },
      { type: "verse", number: "3", sanskrit: "दोषासृङ्मांसमेदोस्थिसिराव्रणभवा नव तत्रवातादायामतोदभेदान्वितो ऽसितः", text: "doṣāsṛṅmāṃsamedosthisirāvraṇabhavā nava tatravātādāyāmatodabhedānvito 'sitaḥ" },
      { type: "verse", number: "4", sanskrit: "स्थानात् स्थानान्तरगतिरकस्माद्धानिवृद्धिमान् मृदुर्बस्तिरिवानद्धो विभिन्नोच्छं स्रवत्यसृक्", text: "sthānāt sthānāntaragatirakasmāddhānivṛddhimān mṛdurbastirivānaddho vibhinnocchaṃ sravatyasṛk" },
      { type: "verse", number: "5", sanskrit: "पित्तात् सदाहपीताभो रक्तो वा पच्यते द्रुतम् भिन्नो ऽस्रमुष्णं स्रवति श्लेष्मणा नीरुजो घनः शीतः सवर्णः कण्डूमान् पक्वः पूयं स्रवेत् घनम्", text: "pittāt sadāhapītābho rakto vā pacyate drutam bhinno 'sramuṣṇaṃ sravati śleṣmaṇā nīrujo ghanaḥ śītaḥ savarṇaḥ kaṇḍūmān pakvaḥ pūyaṃ sravet ghanam" },
      { type: "verse", number: "6", sanskrit: "दोषैर्दुष्टेसृजि ग्रन्थिर्भवेन्मूर्च्छत्सु जन्तुषु सिरामांसं च संश्रित्य सस्वापः पैत्तलक्षणः", text: "doṣairduṣṭesṛji granthirbhavenmūrcchatsu jantuṣu sirāmāṃsaṃ ca saṃśritya sasvāpaḥ paittalakṣaṇaḥ" },
      { type: "verse", number: "7", sanskrit: "मांसलैर्दूषितं मांसमाहारैर्ग्रन्थिमावहेत् स्निग्धं महान्तं कठिनं सिरानद्धं कफाकृतिम्", text: "māṃsalairdūṣitaṃ māṃsamāhārairgranthimāvahet snigdhaṃ mahāntaṃ kaṭhinaṃ sirānaddhaṃ kaphākṛtim" },
      { type: "verse", number: "8", sanskrit: "प्रवृद्धं सेदुरैर्मेदो नीतं मांसे ऽथ वा त्वचि वायुना कुरुते ग्रन्थिं भृशं स्निग्धं मृदुं चलम्", text: "pravṛddhaṃ sedurairmedo nītaṃ māṃse 'tha vā tvaci vāyunā kurute granthiṃ bhṛśaṃ snigdhaṃ mṛduṃ calam" },
      { type: "verse", number: "9", sanskrit: "श्लेष्मतुल्याकृतिं देहक्षयवृद्धिक्षयोदयम् स विभिन्नो घनं मेदस्ताम्रासितसितं स्रवेत्", text: "śleṣmatulyākṛtiṃ dehakṣayavṛddhikṣayodayam sa vibhinno ghanaṃ medastāmrāsitasitaṃ sravet" },
      { type: "verse", number: "10", sanskrit: "आस्थिभङ्गाभिघाताभ्यामुन्नतावनतं तु यत् सोस्थिग्रन्थिः पदातेस्तु सहसाम्भोवगाहनात्", text: "āsthibhaṅgābhighātābhyāmunnatāvanataṃ tu yat sosthigranthiḥ padātestu sahasāmbhovagāhanāt" },
      { type: "verse", number: "11", sanskrit: "व्यायामाद्वा प्रतान्तस्य सिराजालं सशोणितम् वायुः सम्पीड्य सङ्कोच्य वक्रीकृत्य विशोष्य च निस्फुरं नीरुजं ग्रन्थिं कुरुते स सिराह्वयः", text: "vyāyāmādvā pratāntasya sirājālaṃ saśoṇitam vāyuḥ sampīḍya saṅkocya vakrīkṛtya viśoṣya ca nisphuraṃ nīrujaṃ granthiṃ kurute sa sirāhvayaḥ" },
      { type: "verse", number: "12", sanskrit: "अरूढे रूढमात्रे वा व्रणे सर्वरसाशिनः सार्द्रे वा बन्धरहिते गात्रे ऽश्माभिहते ऽथ वा", text: "arūḍhe rūḍhamātre vā vraṇe sarvarasāśinaḥ sārdre vā bandharahite gātre 'śmābhihate 'tha vā" },
      { type: "verse", number: "13", sanskrit: "वातो ऽस्रमस्रुतं दुष्टं संशोष्य ग्रथितं व्रणम् कुर्यात् सदाहः कण्डूमान् व्रणग्रन्थिरयं स्मृतः", text: "vāto 'sramasrutaṃ duṣṭaṃ saṃśoṣya grathitaṃ vraṇam kuryāt sadāhaḥ kaṇḍūmān vraṇagranthirayaṃ smṛtaḥ" },
      { type: "verse", number: "14", sanskrit: "साध्या दोषास्रमेदोजा न तु स्थूलखराश्चलाः मर्मकण्ठोदरस्थाश्च महत्तुग्रन्थितोर्बुदम्", text: "sādhyā doṣāsramedojā na tu sthūlakharāścalāḥ marmakaṇṭhodarasthāśca mahattugranthitorbudam" },
      { type: "verse", number: "15", sanskrit: "तल्लक्षणं च मेदोन्तैः षोढा दोषादिभिस्तु तत् प्रायो मेदःकफाढ्यत्वात् स्थिरत्वाच्च न पच्यते", text: "tallakṣaṇaṃ ca medontaiḥ ṣoḍhā doṣādibhistu tat prāyo medaḥkaphāḍhyatvāt sthiratvācca na pacyate" },
      { type: "verse", number: "16", sanskrit: "सिरास्थं शोणितं दोषः सङ्कोच्यानुप्रपीड्य च पाचयेच्च तदानद्धं सास्रावं मांसपिण्डितम्", text: "sirāsthaṃ śoṇitaṃ doṣaḥ saṅkocyānuprapīḍya ca pācayecca tadānaddhaṃ sāsrāvaṃ māṃsapiṇḍitam" },
      { type: "verse", number: "17", sanskrit: "मांसाङ्क्कुरैश्चितं याति वृद्धिं चाशु स्रवेत्ततः अजस्रं दुष्टरुधिरं भूरि तच्छोणितर्बुदम्", text: "māṃsāṅkkuraiścitaṃ yāti vṛddhiṃ cāśu sravettataḥ ajasraṃ duṣṭarudhiraṃ bhūri tacchoṇitarbudam" },
      { type: "verse", number: "18", sanskrit: "तेष्वसृङ्मांसजे वर्ज्ये चत्वार्यन्यानि साधयेत्", text: "teṣvasṛṅmāṃsaje varjye catvāryanyāni sādhayet" },
      { type: "verse", number: "19", sanskrit: "प्रस्थिता वङ्क्षणोर्वादिमधःकायं कफोल्बणाः दोषा मांसास्रगाः पादौ कालेनाश्रित्य कुर्वते शनैः शनैर्घनं शोफं श्लीपदं तं प्रचक्षते", text: "prasthitā vaṅkṣaṇorvādimadhaḥkāyaṃ kapholbaṇāḥ doṣā māṃsāsragāḥ pādau kālenāśritya kurvate śanaiḥ śanairghanaṃ śophaṃ ślīpadaṃ taṃ pracakṣate" },
      { type: "verse", number: "20", sanskrit: "परिपोटयुतं कृष्णमनिमित्तरुजं खरम् रूक्षं च वातात् पित्तात्तु पीतं दाहज्वरान्वितम्", text: "paripoṭayutaṃ kṛṣṇamanimittarujaṃ kharam rūkṣaṃ ca vātāt pittāttu pītaṃ dāhajvarānvitam" },
      { type: "verse", number: "21", sanskrit: "कफात् गुरुस्निग्धमरुक्चितं मांसाङ्कुरैर्बृहत्", text: "kaphāt gurusnigdhamarukcitaṃ māṃsāṅkurairbṛhat" },
      { type: "verse", number: "22", sanskrit: "तत्त्यजे द्वत्सरातीतं सुमहत्सपरिस्रुति", text: "tattyaje dvatsarātītaṃ sumahatsaparisruti" },
      { type: "verse", number: "23", sanskrit: "पाणिनासौष्ठकर्णेषु वदन्त्यन्ये तु पादवत् श्लीपदं जायते तच्च देशे ऽनूपे भृशं भ्रमात्", text: "pāṇināsauṣṭhakarṇeṣu vadantyanye tu pādavat ślīpadaṃ jāyate tacca deśe 'nūpe bhṛśaṃ bhramāt" },
      { type: "verse", number: "24", sanskrit: "मेदस्थाः कण्ठमन्याक्षकक्षवङ्क्षणगा मलाः सवर्णान् कठिनान् स्निग्धान् वार्ताकामलकाकृतीन्", text: "medasthāḥ kaṇṭhamanyākṣakakṣavaṅkṣaṇagā malāḥ savarṇān kaṭhinān snigdhān vārtākāmalakākṛtīn" },
      { type: "verse", number: "25", sanskrit: "अवगाढान् बहून् गण्डांश्चिरपाकांश्च कुर्वते पच्यन्तेल्परुजस्तेन्ये स्रवन्त्यन्येतिकण्डुराः नश्यन्त्यन्ये भवन्त्यन्ये दीर्घकालानुबन्धिनः", text: "avagāḍhān bahūn gaṇḍāṃścirapākāṃśca kurvate pacyantelparujastenye sravantyanyetikaṇḍurāḥ naśyantyanye bhavantyanye dīrghakālānubandhinaḥ" },
      { type: "verse", number: "26", sanskrit: "गण्डमालापची चेयं दूर्वेव क्षयवृद्धिभाक् तां त्यजेत् सज्वरच्छर्दिपार्श्वरुक्कासपीनसाम्", text: "gaṇḍamālāpacī ceyaṃ dūrveva kṣayavṛddhibhāk tāṃ tyajet sajvaracchardipārśvarukkāsapīnasām" },
      { type: "verse", number: "27", sanskrit: "अभेदात् पक्वशोफस्य व्रणे चापथ्यसेविनः अनुप्रविश्य मांसादीन् दूरं पूयोभिधावति", text: "abhedāt pakvaśophasya vraṇe cāpathyasevinaḥ anupraviśya māṃsādīn dūraṃ pūyobhidhāvati" },
      { type: "verse", number: "28", sanskrit: "गतिः सा दूरगमनान्नाडी नाडीव संस्रुतेः नाड्येकानृजुरन्येषां सैवानेकगतिर्गतिः", text: "gatiḥ sā dūragamanānnāḍī nāḍīva saṃsruteḥ nāḍyekānṛjuranyeṣāṃ saivānekagatirgatiḥ" },
      { type: "verse", number: "29", sanskrit: "सा दोषैःपृथगेकस्थैः शल्यहेतुश्च पञ्चमी", text: "sā doṣaiḥpṛthagekasthaiḥ śalyahetuśca pañcamī" },
      { type: "verse", number: "30", sanskrit: "वातात् सरुक्सूक्ष्ममुखी विवर्णा फेनिलोद्वमा स्रवत्यभ्यधिकं रात्रौ पित्तात्तृङ्ज्वरदाहकृत् पीतोष्णपूतिपूयस्रुग्दिवा चाति निषिञ्चति", text: "vātāt saruksūkṣmamukhī vivarṇā phenilodvamā sravatyabhyadhikaṃ rātrau pittāttṛṅjvaradāhakṛt pītoṣṇapūtipūyasrugdivā cāti niṣiñcati" },
      { type: "verse", number: "31", sanskrit: "घनपिच्छिलसंस्रावा कण्डूला कठिना कफात् निशि चाभ्यधिकक्लेदा सर्वैः सर्वाकृतिं त्यजेत्", text: "ghanapicchilasaṃsrāvā kaṇḍūlā kaṭhinā kaphāt niśi cābhyadhikakledā sarvaiḥ sarvākṛtiṃ tyajet" },
      { type: "verse", number: "32", sanskrit: "अन्तःस्थितं शल्यमनाहृतं तु करोति नाडीं वहते च सास्य फेनानुविद्धं तनुमल्पमुष्णं सास्र च पूयं सरुजं च नित्यम्", text: "antaḥsthitaṃ śalyamanāhṛtaṃ tu karoti nāḍīṃ vahate ca sāsya phenānuviddhaṃ tanumalpamuṣṇaṃ sāsra ca pūyaṃ sarujaṃ ca nityam" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 35,
    lang: "sa",
    content: [
      { type: "heading", heading: "Виша лакшана — признаки отравлений" },
      { type: "text", text: "Глава 35 Уттара стханы — «Виша лакшана» — посвящена специализированному разделу: признаки отравлений. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो ग्रन्थ्यादिप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto granthyādipratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सर्वेष्वेव पूर्वं ग्रन्थिषु बृहतीद्वयपिप्पलीचित्रकसाधितेन पुराणसपिंषा स्निग्धं वामयेत् विरेचयेच्च कृतसंसर्जनस्यचोत्तमाङ्गगतेषु ग्रन्थिषु लाक्षाद्विरजनीविडङ्गशुण्ठीपूतीदारुभिः शिरो विरेचयेत् धूमकवलगण्डूषांश्च स सेवेत", text: "sarveṣveva pūrvaṃ granthiṣu bṛhatīdvayapippalīcitrakasādhitena purāṇasapiṃṣā snigdhaṃ vāmayet virecayecca kṛtasaṃsarjanasyacottamāṅgagateṣu granthiṣu lākṣādvirajanīviḍaṅgaśuṇṭhīpūtīdārubhiḥ śiro virecayet dhūmakavalagaṇḍūṣāṃśca sa seveta" },
      { type: "verse", number: "3", sanskrit: "अङ्कोलमधुकमातुलुङ्गहिंस्रापूतीदारुबिल्वमूलसरलकुष्ठवचावरुणत्वक्कालातिविषाजगन्धाभिर्लेपः श्यामासुरदारु समङ्गाकोशातकीपुनर्नवसर्षपैर्वा", text: "aṅkolamadhukamātuluṅgahiṃsrāpūtīdārubilvamūlasaralakuṣṭhavacāvaruṇatvakkālātiviṣājagandhābhirlepaḥ śyāmāsuradāru samaṅgākośātakīpunarnavasarṣapairvā" },
      { type: "verse", number: "4", sanskrit: "सशोफरुक्स्तम्भे चोपनाहो यवसक्तुमधुककुष्ठशतपुष्पोदवदारुभिर्घृतयुक्तैः गोजाविखरोष्ट्राश्वहस्तिमूषीकमांसैर्वा वेशवारीकृतैर्वसातैलवद्भिः", text: "saśopharukstambhe copanāho yavasaktumadhukakuṣṭhaśatapuṣpodavadārubhirghṛtayuktaiḥ gojāvikharoṣṭrāśvahastimūṣīkamāṃsairvā veśavārīkṛtairvasātailavadbhiḥ" },
      { type: "verse", number: "5", sanskrit: "पलाशवृन्ताग्निमन्थत्वक्कल्केन मांसपिण्डैर्वा बहुशः स्विन्नमङ्गुष्ठेन वेणुपर्वणा वा शनैश्शनैः पुनः पुनर्विमर्दयेत् यथायथं च शोफवत् क्रियां प्रयुञ्जीत", text: "palāśavṛntāgnimanthatvakkalkena māṃsapiṇḍairvā bahuśaḥ svinnamaṅguṣṭhena veṇuparvaṇā vā śanaiśśanaiḥ punaḥ punarvimardayet yathāyathaṃ ca śophavat kriyāṃ prayuñjīta" },
      { type: "verse", number: "6", sanskrit: "अथ वातजे ग्रन्थौ दशमूलसिद्धं महास्नेहं पिबेत् अमृतानिम्बबीजभार्ङ्गीस्योनाकबाणतालपत्रीकृष्णगन्धागरुभिः क्षीरपिष्टैः सुखोष्णैर्लेपः विविधाश्च वातव्याधिविहिताः स्नेहस्वेदोपनाहाः तथानुपशमे सिराव्यधः", text: "atha vātaje granthau daśamūlasiddhaṃ mahāsnehaṃ pibet amṛtānimbabījabhārṅgīsyonākabāṇatālapatrīkṛṣṇagandhāgarubhiḥ kṣīrapiṣṭaiḥ sukhoṣṇairlepaḥ vividhāśca vātavyādhivihitāḥ snehasvedopanāhāḥ tathānupaśame sirāvyadhaḥ" },
      { type: "verse", number: "7", sanskrit: "पक्वं तु विदार्य निरस्तपूयं कृत्वार्कादिवर्गाम्भसा प्रक्षाल्य तिलकल्केन सचित्रकसैन्धवेनालेपयेत् तैलं च रोपणं रास्नासरलोशीरविडङ्गमधुकक्षीरसंस्कृतं कुर्यात्", text: "pakvaṃ tu vidārya nirastapūyaṃ kṛtvārkādivargāmbhasā prakṣālya tilakalkena sacitrakasaindhavenālepayet tailaṃ ca ropaṇaṃ rāsnāsaralośīraviḍaṅgamadhukakṣīrasaṃskṛtaṃ kuryāt" },
      { type: "verse", number: "8", sanskrit: "पित्तजे रक्तजे च जलौकसो न्यग्रोधादिः प्रदेहपरिषेकयोः पद्मकादिः पाने च द्राक्षेक्षुरसयुक्ता हरीतकी विरेकः पक्वे पाटिते च पित्तव्रणोक्तो विधिः", text: "pittaje raktaje ca jalaukaso nyagrodhādiḥ pradehapariṣekayoḥ padmakādiḥ pāne ca drākṣekṣurasayuktā harītakī virekaḥ pakve pāṭite ca pittavraṇokto vidhiḥ" },
      { type: "verse", number: "9", sanskrit: "कफजमन्तश्शुद्धस्य भृशं स्वेदयेद्विम्लापयेच्च काकादनीविकङ्कतकाकनन्दिकारग्वधेङ्गुदमूलमदनफलभार्ङ्गीकरञ्जैर्लेपयेत् नागरविडङ्गैलावालुकचव्यपलाशवृन्तचित्रकैर्वा भल्लातसैन्धवाजगन्धासर्षषैर्वा", text: "kaphajamantaśśuddhasya bhṛśaṃ svedayedvimlāpayecca kākādanīvikaṅkatakākanandikāragvadheṅgudamūlamadanaphalabhārṅgīkarañjairlepayet nāgaraviḍaṅgailāvālukacavyapalāśavṛntacitrakairvā bhallātasaindhavājagandhāsarṣaṣairvā" },
      { type: "verse", number: "10", sanskrit: "एवमप्यपच्यमानममर्मस्थं विदार्य स्थितरक्तं निश्शेषमग्निना दहेत् सशेषो हि पुनरापूर्यते ततो निर्वापितं क्षारक्षौद्रगुडोत्तरैरालेपैस्संशुद्धं रोपयेत्", text: "evamapyapacyamānamamarmasthaṃ vidārya sthitaraktaṃ niśśeṣamagninā dahet saśeṣo hi punarāpūryate tato nirvāpitaṃ kṣārakṣaudraguḍottarairālepaissaṃśuddhaṃ ropayet" },
      { type: "verse", number: "11", sanskrit: "मांसव्रणग्रन्थींश्चैवमेव यापयेत् मेदोजेप्ययमेव विधिः अपि च मेदोग्रन्थिं तिलकल्कदिग्धं द्विगुणपटान्तरितं तप्तेन फालेन दर्व्या वा जतुलिप्तया बहुशः प्रमृज्यात् शस्त्रं चावचार्य पूर्ववन्मेदो दहेत् सुपक्वं वा विपाट्य मूत्रप्रक्षालितं क्षौद्रसैन्धवसुवर्चिकाकाञ्चनक्षीरीहरितालमिश्रैः क्षीरबकप्रगाढैस्तिलैरालेपयेत्", text: "māṃsavraṇagranthīṃścaivameva yāpayet medojepyayameva vidhiḥ api ca medogranthiṃ tilakalkadigdhaṃ dviguṇapaṭāntaritaṃ taptena phālena darvyā vā jatuliptayā bahuśaḥ pramṛjyāt śastraṃ cāvacārya pūrvavanmedo dahet supakvaṃ vā vipāṭya mūtraprakṣālitaṃ kṣaudrasaindhavasuvarcikākāñcanakṣīrīharitālamiśraiḥ kṣīrabakapragāḍhaistilairālepayet" },
      { type: "verse", number: "12", sanskrit: "गुञ्जाद्विकरञ्जतापसवृक्षवंशावलेखमूत्रसिद्धं तैलमभ्यङ्गः सम्यक्शुद्धं चैनं रोपयेत्", text: "guñjādvikarañjatāpasavṛkṣavaṃśāvalekhamūtrasiddhaṃ tailamabhyaṅgaḥ samyakśuddhaṃ cainaṃ ropayet" },
      { type: "verse", number: "13", sanskrit: "सिराग्रन्थौ त्वभिनवे तैलं साहचरं पिबेत् उपनाहञ्च वातहरैर्बस्तिकर्म च कुर्यात् सिराव्यधञ्च", text: "sirāgranthau tvabhinave tailaṃ sāhacaraṃ pibet upanāhañca vātaharairbastikarma ca kuryāt sirāvyadhañca" },
      { type: "verse", number: "14", sanskrit: "वातार्बुदमैरण्डप्रियालनारिकेलमज्जोर्वारुकार्कोरुबीजोत्कारिकयोपनाहयेत् आनूपामिषवेशवारैर्वा नाडीस्वेदञ्च कुर्यात् बहुशश्चात्रशृङ्गेण रुधिरमवसेचयेत् वातहरवर्गक्काथपयोम्लसिद्धं त्रिवृतं पिबेत्", text: "vātārbudamairaṇḍapriyālanārikelamajjorvārukārkorubījotkārikayopanāhayet ānūpāmiṣaveśavārairvā nāḍīsvedañca kuryāt bahuśaścātraśṛṅgeṇa rudhiramavasecayet vātaharavargakkāthapayomlasiddhaṃ trivṛtaṃ pibet" },
      { type: "verse", number: "15", sanskrit: "पित्तोत्थे मृदून् स्वेदोपनाहान् कायविरेचनञ्च प्रयोजयेत् शाककाकोदुम्बरिकापत्रघृष्टे च प्रियङ्गुपतङ्गसर्जरसार्जुनलोध्रमधुमधुकैर्लेपः श्यामाग्रिकर्णिकाञ्जनक्लीतनकनखद्राक्षासप्तलान्यतमरससाधितं सर्पिः पीतं पित्तार्बुदश्लीपदोदरघ्नम्", text: "pittotthe mṛdūn svedopanāhān kāyavirecanañca prayojayet śākakākodumbarikāpatraghṛṣṭe ca priyaṅgupataṅgasarjarasārjunalodhramadhumadhukairlepaḥ śyāmāgrikarṇikāñjanaklītanakanakhadrākṣāsaptalānyatamarasasādhitaṃ sarpiḥ pītaṃ pittārbudaślīpadodaraghnam" },
      { type: "verse", number: "16", sanskrit: "श्लेष्मजे तूर्ध्वमधश्च हृतदोषस्य स्रुतरक्तस्य च वमनविरेचनद्रव्यैः प्रलेपः काकादनीशुकबर्हाग्निजिह्वामूलदक्षकपोतगृध्रपुरीषकाशमूलैर्वा पलाशक्षीरपिष्टैः पिण्याककुलत्थनिष्पावैर्मांसप्रगाढैर्दधिपिष्टैर्लेपयेत् लेपास्वादलोभेन च निलीयमाना मक्षिकाः स मुपेक्षेत तद्विमुक्तैः कृमिभिरितरैर्वा भक्ष्यमाणञ्च ततः कृमिभक्षितावशेषं शाकादिपत्रैर्विलिख्याग्निनाप्रतिसारयत् अल्पमूलं वा त्रपुतास्रायःसीसपट्टकवेष्टितम् पुनः पुनश्च क्षारान् कालापेक्षया योजयेत् जात्यास्फोतकरवीरपल्लवांश्च व्रणशोधनाय कल्कादौ तैलञ्चात्र पाठाविडङ्गभार्ङ्गी त्रिफलाकषायसिद्धमभ्यञ्जनम्", text: "śleṣmaje tūrdhvamadhaśca hṛtadoṣasya srutaraktasya ca vamanavirecanadravyaiḥ pralepaḥ kākādanīśukabarhāgnijihvāmūladakṣakapotagṛdhrapurīṣakāśamūlairvā palāśakṣīrapiṣṭaiḥ piṇyākakulatthaniṣpāvairmāṃsapragāḍhairdadhipiṣṭairlepayet lepāsvādalobhena ca nilīyamānā makṣikāḥ sa mupekṣeta tadvimuktaiḥ kṛmibhiritarairvā bhakṣyamāṇañca tataḥ kṛmibhakṣitāvaśeṣaṃ śākādipatrairvilikhyāgnināpratisārayat alpamūlaṃ vā traputāsrāyaḥsīsapaṭṭakaveṣṭitam punaḥ punaśca kṣārān kālāpekṣayā yojayet jātyāsphotakaravīrapallavāṃśca vraṇaśodhanāya kalkādau tailañcātra pāṭhāviḍaṅgabhārṅgī triphalākaṣāyasiddhamabhyañjanam" },
      { type: "verse", number: "17", sanskrit: "मेदोर्बुदं स्विन्नभिन्नं सुशोधितमेदस्कमुपशान्तरक्तस्रावं सद्यःस्सीव्येत् ततो गृहधूमलोध्रमनश्शिलाहरिद्रापतङ्गचूर्णैर्मधुमाद्भिः प्रतिसारयेत् करञ्जतैलञ्चाभ्यञ्जनार्थे नियुञ्जीत सर्वार्बुदानि च यदृच्छया पर्यागतानि सुपरिशोधितानि रोपयेत् अपि च", text: "medorbudaṃ svinnabhinnaṃ suśodhitamedaskamupaśāntaraktasrāvaṃ sadyaḥssīvyet tato gṛhadhūmalodhramanaśśilāharidrāpataṅgacūrṇairmadhumādbhiḥ pratisārayet karañjatailañcābhyañjanārthe niyuñjīta sarvārbudāni ca yadṛcchayā paryāgatāni supariśodhitāni ropayet api ca" },
      { type: "verse", number: "18", sanskrit: "सशेषदोषाणि तु योर्बुदानि करोति तस्याशु पुनर्भवन्ति तस्मादशेषोद्धरणं प्रशस्तं क्षारेण शस्त्रेण तथाग्निना वा", text: "saśeṣadoṣāṇi tu yorbudāni karoti tasyāśu punarbhavanti tasmādaśeṣoddharaṇaṃ praśastaṃ kṣāreṇa śastreṇa tathāgninā vā" },
      { type: "verse", number: "19", sanskrit: "श्लीपदे तु वातात्मके स्नेहस्वेदोपनाहान् प्रयुज्य गुल्फस्योपरिष्टाद्व्यङ्गुले सिरां विध्येत् एरण्डतैलञ्च गोमूत्रेण मासं पिबेत् जीर्णे नागरक्वथितेन पयसा पुराणधान्यान्यश्नीयात् त्रिवृतञ्च पाययेत् बस्तिश्च प्रयुञ्जीत एवमप्यशाम्यत्याग्निना दहेत्", text: "ślīpade tu vātātmake snehasvedopanāhān prayujya gulphasyopariṣṭādvyaṅgule sirāṃ vidhyet eraṇḍatailañca gomūtreṇa māsaṃ pibet jīrṇe nāgarakvathitena payasā purāṇadhānyānyaśnīyāt trivṛtañca pāyayet bastiśca prayuñjīta evamapyaśāmyatyāgninā dahet" },
      { type: "verse", number: "20", sanskrit: "पैत्तिके मृदुरुपनाहो गुल्फस्याधः सिरामोक्षः पित्तार्बुदोक्ताः स्नेहविरेकाः पित्तघ्नाश्च लेपाः श्लैष्मिके त्वङ्गुष्ठे सिरां मुञ्चेत् सक्षौद्रांश्च कफघ्नान् कषायानभीक्ष्णं पाययेत् यथाबलं वा हरीतकी वर्धमानाः", text: "paittike mṛdurupanāho gulphasyādhaḥ sirāmokṣaḥ pittārbudoktāḥ snehavirekāḥ pittaghnāśca lepāḥ ślaiṣmike tvaṅguṣṭhe sirāṃ muñcet sakṣaudrāṃśca kaphaghnān kaṣāyānabhīkṣṇaṃ pāyayet yathābalaṃ vā harītakī vardhamānāḥ" },
      { type: "verse", number: "21", sanskrit: "श्लैष्मिके त्वङ्गुष्ठे सिरां मुञ्चेत् सक्षौद्रांश्च कफघ्नान् कषायानभीक्ष्णं पाययेत् यथाबलं वा हरीतकी वर्धमानाः", text: "ślaiṣmike tvaṅguṣṭhe sirāṃ muñcet sakṣaudrāṃśca kaphaghnān kaṣāyānabhīkṣṇaṃ pāyayet yathābalaṃ vā harītakī vardhamānāḥ" },
      { type: "verse", number: "22", sanskrit: "आदारीकाकजंघाकाकादनीशुकनासाकदम्बपुष्पबृहतीद्वयमन्तर्धूमं दग्ध्वा गोमूत्रेण बहुशः परिस्रावयेत् ततस्तत् क्षारोदकं क्षारकल्पेन विपचेत् दद्याच्चात्र परतीवापं फल्गुशुकाख्या मदनफलरसं एष क्षारो मधुराहारेणाभ्यस्तः श्लीपदापचीग्रहणीदोषारोचकान् सर्वविषाणि च नियच्छति", text: "ādārīkākajaṃghākākādanīśukanāsākadambapuṣpabṛhatīdvayamantardhūmaṃ dagdhvā gomūtreṇa bahuśaḥ parisrāvayet tatastat kṣārodakaṃ kṣārakalpena vipacet dadyāccātra paratīvāpaṃ phalguśukākhyā madanaphalarasaṃ eṣa kṣāro madhurāhāreṇābhyastaḥ ślīpadāpacīgrahaṇīdoṣārocakān sarvaviṣāṇi ca niyacchati" },
      { type: "verse", number: "23", sanskrit: "तैलं वा पिबेद्विडङ्गार्कमरिचचित्रकशुण्ठीदेवदार्वेलावालुकलवणपञ्चकैस्सिद्धम् आलेपयेच्च नागरामृताविडङ्गकटुकाभद्रदारुभिर्मूत्रपिष्टैरूरुस्तम्भोक्तैश्च भेषजैर्यवान्नं च शीलयेत्", text: "tailaṃ vā pibedviḍaṅgārkamaricacitrakaśuṇṭhīdevadārvelāvālukalavaṇapañcakaissiddham ālepayecca nāgarāmṛtāviḍaṅgakaṭukābhadradārubhirmūtrapiṣṭairūrustambhoktaiśca bheṣajairyavānnaṃ ca śīlayet" },
      { type: "verse", number: "24", sanskrit: "मण्डमालायां कुम्भनिकुम्भद्रवन्तीजीमूतककोशातकीफलविपक्वं घृतमुभयानुलोमनं पिबेत् शार्ङ्गेष्टामूलं वा तक्रपिष्टम् वमनार्थं सुखोदकेन वा जातीबर्हिष्ठनिर्गुण्डीजीमूतकोत्तुण्डकीमूलत्वक्चूर्णम् सिरा चास्य विध्येत्", text: "maṇḍamālāyāṃ kumbhanikumbhadravantījīmūtakakośātakīphalavipakvaṃ ghṛtamubhayānulomanaṃ pibet śārṅgeṣṭāmūlaṃ vā takrapiṣṭam vamanārthaṃ sukhodakena vā jātībarhiṣṭhanirguṇḍījīmūtakottuṇḍakīmūlatvakcūrṇam sirā cāsya vidhyet" },
      { type: "verse", number: "25", sanskrit: "सशेषदोषं तु कौष्ठिकं नवकं पाययेत् रसाञ्जनं गोमूत्रतण्डुलोदकान्यतरेण तदेव च नावयेत् मधूकसारं वा शिग्रुफलानि वा निम्बकरञ्जकरवीरसिद्धं वा तैलं वैरेचनिकञ्च धूमं पिबेत्", text: "saśeṣadoṣaṃ tu kauṣṭhikaṃ navakaṃ pāyayet rasāñjanaṃ gomūtrataṇḍulodakānyatareṇa tadeva ca nāvayet madhūkasāraṃ vā śigruphalāni vā nimbakarañjakaravīrasiddhaṃ vā tailaṃ vairecanikañca dhūmaṃ pibet" },
      { type: "verse", number: "26", sanskrit: "अपक्वांश्च गण्डान्नाकुलीसैन्धवनागरैर्लेपयेत् गुञ्जाकरवीरार्कश्यामासिद्धार्थकैरजामूत्रयुक्तैर्दशकृत्वा विपक्वं तैलं लवणपञ्चकपिप्पलीमरिचचूर्णो पेतमभ्यङ्गात्सर्वावस्थानपच्यर्शोर्बुदनाडीदुष्टव्रणवल्मीकानपोहति", text: "apakvāṃśca gaṇḍānnākulīsaindhavanāgarairlepayet guñjākaravīrārkaśyāmāsiddhārthakairajāmūtrayuktairdaśakṛtvā vipakvaṃ tailaṃ lavaṇapañcakapippalīmaricacūrṇo petamabhyaṅgātsarvāvasthānapacyarśorbudanāḍīduṣṭavraṇavalmīkānapohati" },
      { type: "verse", number: "27", sanskrit: "सौवर्चलसैन्धवौद्भिददन्तीभल्लातकचित्रककल्केन सिद्धं तैलमभ्यङ्गो ऽपच्याम् तण्डूलीयकस्वरसेन वा सनिर्गुण्डीरसं वा तैलं साधितमभ्यङ्गपाननावनैर्गण्डमालानाडीव्रणकुष्ठानिलार्तिहरम्", text: "sauvarcalasaindhavaudbhidadantībhallātakacitrakakalkena siddhaṃ tailamabhyaṅgo 'pacyām taṇḍūlīyakasvarasena vā sanirguṇḍīrasaṃ vā tailaṃ sādhitamabhyaṅgapānanāvanairgaṇḍamālānāḍīvraṇakuṣṭhānilārtiharam" },
      { type: "verse", number: "28", sanskrit: "काकादनीनलिकाग्निजिह्वावन्ध्याकर्कोटकीविशालापाठोत्तुण्डकीजीमूतकोशातकीबीजैरर्द्धपलांशौर्विषकर्षयुक्तैर्निर्गुण्डीस्वरसोपेतं करञ्जतैलप्रस्थं विपचेत्तत्पूर्ववदेवप्रयुक्तं परमपचीघ्नम्", text: "kākādanīnalikāgnijihvāvandhyākarkoṭakīviśālāpāṭhottuṇḍakījīmūtakośātakībījairarddhapalāṃśaurviṣakarṣayuktairnirguṇḍīsvarasopetaṃ karañjatailaprasthaṃ vipacettatpūrvavadevaprayuktaṃ paramapacīghnam" },
      { type: "verse", number: "29", sanskrit: "अमर्मजांश्च गण्डानपक्वानेवोद्भृत्याग्निना क्षारेण वा प्रसाधयेत् सर्षपवृक्षादनी क्वाथैर्व्रणक्षालनम् तिलकुन्तलक्षअरपिष्टस्तिलकल्कः सुखोष्णो लेपः काककृकलासगोधाहिनिर्मोककूर्माणामन्यतमस्यान्तर्धूमदग्धस्य मषीङ्गुदतैलप्लुताभ्यङ्गः मांसीसर्जरसकार्पासीफलसैन्धवैः स्तन्यपिष्टैस्तैलं विपक्वमभ्यङ्गो व्रणकाठिन्यघ्नः सर्पाजगरवसे तैलं च समं त्रयमेतदपचीघ्नम् श्लीपदोक्तानि च तैलानि प्रयोजयेत्", text: "amarmajāṃśca gaṇḍānapakvānevodbhṛtyāgninā kṣāreṇa vā prasādhayet sarṣapavṛkṣādanī kvāthairvraṇakṣālanam tilakuntalakṣAarapiṣṭastilakalkaḥ sukhoṣṇo lepaḥ kākakṛkalāsagodhāhinirmokakūrmāṇāmanyatamasyāntardhūmadagdhasya maṣīṅgudatailaplutābhyaṅgaḥ māṃsīsarjarasakārpāsīphalasaindhavaiḥ stanyapiṣṭaistailaṃ vipakvamabhyaṅgo vraṇakāṭhinyaghnaḥ sarpājagaravase tailaṃ ca samaṃ trayametadapacīghnam ślīpadoktāni ca tailāni prayojayet" },
      { type: "verse", number: "30", sanskrit: "एवमनुपशमे वामपार्श्वजायां दक्षिणजङ्घापृष्ठमध्यादिन्द्रबस्तेरधः ऊर्ध्वं वा शस्त्रेणाक्षिमात्रं व्रणं कृत्वा मत्स्याण्डजालनिभं मेदोपनीयाग्निना दहेत् अनेनेतरपार्श्वजाव्याख्याता एवमुभयपार्श्वजायामुब्भयतः यवमुद्गप्रायं च गण्डमालासु भोजनम्", text: "evamanupaśame vāmapārśvajāyāṃ dakṣiṇajaṅghāpṛṣṭhamadhyādindrabasteradhaḥ ūrdhvaṃ vā śastreṇākṣimātraṃ vraṇaṃ kṛtvā matsyāṇḍajālanibhaṃ medopanīyāgninā dahet anenetarapārśvajāvyākhyātā evamubhayapārśvajāyāmubbhayataḥ yavamudgaprāyaṃ ca gaṇḍamālāsu bhojanam" },
      { type: "verse", number: "31", sanskrit: "नाडीमनिलजामुपनाह्य पूयगतिमस्या निश्शेषमोषित्वावदारयेच्छस्त्रेण ततस्तिलापामार्गफलकल्केन ससैन्धवेन पूरयित्वा बध्नीयात्", text: "nāḍīmanilajāmupanāhya pūyagatimasyā niśśeṣamoṣitvāvadārayecchastreṇa tatastilāpāmārgaphalakalkena sasaindhavena pūrayitvā badhnīyāt" },
      { type: "verse", number: "32", sanskrit: "पित्तजां सघृतक्षीरया पद्मकादिकृतयो ऽल्कारिकयो ऽपनाहिताम् विदारितां च तिलनागदन्तीमञ्जिष्ठाकल्केन पूरयेत् श्यामात्रिभण्डीत्रिफलातिल्वकहरिद्राद्वयकल्कक्षीरसंस्कृतं सर्पिरभ्यङ्गः परं नाडीनिबर्हणम्", text: "pittajāṃ saghṛtakṣīrayā padmakādikṛtayo 'lkārikayo 'panāhitām vidāritāṃ ca tilanāgadantīmañjiṣṭhākalkena pūrayet śyāmātribhaṇḍītriphalātilvakaharidrādvayakalkakṣīrasaṃskṛtaṃ sarpirabhyaṅgaḥ paraṃ nāḍīnibarhaṇam" },
      { type: "verse", number: "33", sanskrit: "श्लेष्मजां सक्तुकुलत्थकिण्वसर्षपैरुपनाह्य विदार्य च निम्बतिलसैन्धवसौराष्ट्रीनिकुम्भैर्लेपयेत् दन्तीचित्रकस्वर्जिकासैन्धवतालीसनलदपूतीकापामार्गफलैस्तैलं समूत्रं पाचितमभ्यङ्गः", text: "śleṣmajāṃ saktukulatthakiṇvasarṣapairupanāhya vidārya ca nimbatilasaindhavasaurāṣṭrīnikumbhairlepayet dantīcitrakasvarjikāsaindhavatālīsanaladapūtīkāpāmārgaphalaistailaṃ samūtraṃ pācitamabhyaṅgaḥ" },
      { type: "verse", number: "34", sanskrit: "शल्यहेतुकीं पाटयित्वा सर्वशः शल्यं विशोध्य मधुघृततिलकल्कप्रतिच्छन्नां बध्नीयात् बिल्वकपित्थकुम्भीखर्जूरवनस्पतिशलाटुक्वाथे प्रियङ्गुमुस्तोरुपूगशकुनसुगन्धिकालोध्रमोचरसधातकीपुष्पगर्भं तैलं प्रसाधितं साधयत्याशु शल्यजां गतिम्", text: "śalyahetukīṃ pāṭayitvā sarvaśaḥ śalyaṃ viśodhya madhughṛtatilakalkapraticchannāṃ badhnīyāt bilvakapitthakumbhīkharjūravanaspatiśalāṭukvāthe priyaṅgumustorupūgaśakunasugandhikālodhramocarasadhātakīpuṣpagarbhaṃ tailaṃ prasādhitaṃ sādhayatyāśu śalyajāṃ gatim" },
      { type: "verse", number: "35", sanskrit: "अशस्त्रकृत्यां नाड्यां भेदिन्यैषिण्यान्ते समुद्भिद्य क्षाराक्तं सूत्रं प्रवेशयेत् तदसन्निधानेत्वितरयैषिण्या च तेनानवदीर्णायां तदनुस्यूतमन्यदन्यत् क्षारसूत्रं सञ्चारयेदा गतिभेदादयमनपायो ऽभ्युपायः सूक्ष्मानेकगतिषु भगन्दरेषु मूलेषु च छिद्रितेषु ग्रन्थ्यर्बुदेष्विति भवति चात्र", text: "aśastrakṛtyāṃ nāḍyāṃ bhedinyaiṣiṇyānte samudbhidya kṣārāktaṃ sūtraṃ praveśayet tadasannidhānetvitarayaiṣiṇyā ca tenānavadīrṇāyāṃ tadanusyūtamanyadanyat kṣārasūtraṃ sañcārayedā gatibhedādayamanapāyo 'bhyupāyaḥ sūkṣmānekagatiṣu bhagandareṣu mūleṣu ca chidriteṣu granthyarbudeṣviti bhavati cātra" },
      { type: "verse", number: "36", sanskrit: "व्रणेषु दुष्टसूक्ष्मास्यगम्भीरादिषु साधनम् या वर्त्यो यानि तैलानि तन्नाडीष्वपि कल्पयेत्", text: "vraṇeṣu duṣṭasūkṣmāsyagambhīrādiṣu sādhanam yā vartyo yāni tailāni tannāḍīṣvapi kalpayet" },
      { type: "verse", number: "37", sanskrit: "विभीतकाम्रास्थिवटप्रवाल हरेणुकाशाल्मलिबीजयुक्ता वराहविष्ठा च मषी सुदग्धा तैलप्लुता सर्वगतीर्निहन्ति", text: "vibhītakāmrāsthivaṭapravāla hareṇukāśālmalibījayuktā varāhaviṣṭhā ca maṣī sudagdhā tailaplutā sarvagatīrnihanti" },
      { type: "verse", number: "38", sanskrit: "धत्तूरकं मदनकोद्रवजञ्च बीजं कोशातकी शुकनसा मृगभोजनी च अङ्कोलजञ्च कुसुमं परिकल्प्य चूर्णं लाक्षोदकापहृतदोषगतौ प्रयोज्यम्", text: "dhattūrakaṃ madanakodravajañca bījaṃ kośātakī śukanasā mṛgabhojanī ca aṅkolajañca kusumaṃ parikalpya cūrṇaṃ lākṣodakāpahṛtadoṣagatau prayojyam" },
      { type: "verse", number: "39", sanskrit: "मिश्रितं तेन तैलञ्च परमं गतिरोपणम् सौवहेषु च कन्देषु कृतं वज्राह्वयेषु च", text: "miśritaṃ tena tailañca paramaṃ gatiropaṇam sauvaheṣu ca kandeṣu kṛtaṃ vajrāhvayeṣu ca" },
      { type: "verse", number: "40", sanskrit: "भल्लातकार्कमरिचैर्लवणोत्तमेन सिद्धं विडङ्गरजनीद्वयचित्रकैश्च तैलं समार्कवरसैर्विनिहन्ति कृच्छ्रां नाडीं कफानिलकृतामपचीव्रणांश्च", text: "bhallātakārkamaricairlavaṇottamena siddhaṃ viḍaṅgarajanīdvayacitrakaiśca tailaṃ samārkavarasairvinihanti kṛcchrāṃ nāḍīṃ kaphānilakṛtāmapacīvraṇāṃśca" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 36,
    lang: "sa",
    content: [
      { type: "heading", heading: "Виша агада — противоядия" },
      { type: "text", text: "Глава 36 Уттара стханы — «Виша агада» — посвящена специализированному разделу: противоядия. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः क्षुद्ररोगविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ kṣudrarogavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "स्निग्धाः सवर्णा ग्रथिता नीरुजा मुद्गसन्निभाः पिटकाः कफवाताभ्यां बालानामजगल्लिका", text: "snigdhāḥ savarṇā grathitā nīrujā mudgasannibhāḥ piṭakāḥ kaphavātābhyāṃ bālānāmajagallikā" },
      { type: "verse", number: "3", sanskrit: "यवप्रख्या यवप्रख्या ताभ्यां मांसाश्रिता घना अवक्त्रा त्वलजी वृत्ताः स्तोकपूया घनोन्नताः ग्रन्थयः पञ्च वा षड्वा कच्छपी कच्छपोन्नताः", text: "yavaprakhyā yavaprakhyā tābhyāṃ māṃsāśritā ghanā avaktrā tvalajī vṛttāḥ stokapūyā ghanonnatāḥ granthayaḥ pañca vā ṣaḍvā kacchapī kacchaponnatāḥ" },
      { type: "verse", number: "4", sanskrit: "कर्णस्योर्ध्वं समन्ताद्वा पिटका कठिनोग्ररुक् शालूकाभा पनसिका शोफस्त्वल्परुजः स्थिरः हनुसन्धिसमुद्भूतस्ताभ्यां पाषाणगर्दभः", text: "karṇasyordhvaṃ samantādvā piṭakā kaṭhinograruk śālūkābhā panasikā śophastvalparujaḥ sthiraḥ hanusandhisamudbhūtastābhyāṃ pāṣāṇagardabhaḥ" },
      { type: "verse", number: "5", sanskrit: "शाल्मलीकण्टकाकाराः पिटकाः सरुजो घनाः मेदोगर्भा मुखे शूनां ताभ्यां च मुखदूषिका", text: "śālmalīkaṇṭakākārāḥ piṭakāḥ sarujo ghanāḥ medogarbhā mukhe śūnāṃ tābhyāṃ ca mukhadūṣikā" },
      { type: "verse", number: "6", sanskrit: "ते पद्मकण्टका ज्ञेया यैः पद्ममिव कण्टकैः चीयते नीरुजैः श्वेतैः शरीरं कफवातजैः", text: "te padmakaṇṭakā jñeyā yaiḥ padmamiva kaṇṭakaiḥ cīyate nīrujaiḥ śvetaiḥ śarīraṃ kaphavātajaiḥ" },
      { type: "verse", number: "7", sanskrit: "पित्तेन पिटका वृत्ता पक्वोदुम्बरसन्निभा महादाहज्वरकरी विवृता विवृतानना", text: "pittena piṭakā vṛttā pakvodumbarasannibhā mahādāhajvarakarī vivṛtā vivṛtānanā" },
      { type: "verse", number: "8", sanskrit: "गात्रेष्वन्तश्च वक्त्रस्य दाहज्वररुजान्विताः मसूरमात्रास्तद्वर्णास्तत्संज्ञाः पिटका घनाः", text: "gātreṣvantaśca vaktrasya dāhajvararujānvitāḥ masūramātrāstadvarṇāstatsaṃjñāḥ piṭakā ghanāḥ" },
      { type: "verse", number: "9", sanskrit: "ततः कष्टतराः स्फोटा विस्फोटाख्या महारुजाः", text: "tataḥ kaṣṭatarāḥ sphoṭā visphoṭākhyā mahārujāḥ" },
      { type: "verse", number: "10", sanskrit: "या पद्मकर्णिकाकारा पिटका पिटकाचिता सा विद्धा वातपित्ताभ्यां ताभ्यामेव च गर्दभी", text: "yā padmakarṇikākārā piṭakā piṭakācitā sā viddhā vātapittābhyāṃ tābhyāmeva ca gardabhī" },
      { type: "verse", number: "11", sanskrit: "मण्डला विपुलोत्सन्ना सरागपिटकाचिता", text: "maṇḍalā vipulotsannā sarāgapiṭakācitā" },
      { type: "verse", number: "12", sanskrit: "कक्ष्येति कक्षासन्नेषु प्रायो देशेषु सानिलात् पित्तात् भवन्ति पिटकाः सूक्ष्मा लाजोपमा घनाः तादृशी महतीत्वेका गन्धनामेति कीर्तिता", text: "kakṣyeti kakṣāsanneṣu prāyo deśeṣu sānilāt pittāt bhavanti piṭakāḥ sūkṣmā lājopamā ghanāḥ tādṛśī mahatītvekā gandhanāmeti kīrtitā" },
      { type: "verse", number: "13", sanskrit: "घर्मस्वेदपरीतेङ्गे पिटकाः सरुजो घनाः राजिकावर्णसंस्थानप्रमाणा राजिकाह्वयाः", text: "gharmasvedaparīteṅge piṭakāḥ sarujo ghanāḥ rājikāvarṇasaṃsthānapramāṇā rājikāhvayāḥ" },
      { type: "verse", number: "14", sanskrit: "दोषैः पित्तोल्बणैर्मन्दैर्विसर्पति विसर्पवत् शोफो ऽपाकस्तनुस्ताम्रो ज्वरकृज्जालगर्दभः", text: "doṣaiḥ pittolbaṇairmandairvisarpati visarpavat śopho 'pākastanustāmro jvarakṛjjālagardabhaḥ" },
      { type: "verse", number: "15", sanskrit: "मलैः पित्तोल्बणैः स्फोटा ज्वरिणो मांसदारणाः कक्ष्याभागेषु जायन्ते येग्न्याभाः साग्निरोहिणी पञ्चाहात् सप्तरात्राद्वा पक्षाद्वा हन्ति जीवितम्", text: "malaiḥ pittolbaṇaiḥ sphoṭā jvariṇo māṃsadāraṇāḥ kakṣyābhāgeṣu jāyante yegnyābhāḥ sāgnirohiṇī pañcāhāt saptarātrādvā pakṣādvā hanti jīvitam" },
      { type: "verse", number: "16", sanskrit: "त्रिलिङ्गा पिटका वृत्ता जत्रूर्ध्वमिरिवेल्लिका", text: "triliṅgā piṭakā vṛttā jatrūrdhvamirivellikā" },
      { type: "verse", number: "17", sanskrit: "विदारीकन्दकठिना विदारी कक्षवङ्क्षणे", text: "vidārīkandakaṭhinā vidārī kakṣavaṅkṣaṇe" },
      { type: "verse", number: "18", sanskrit: "मेदोनिलकफैर्ग्रन्थिः स्नायुमांससिराश्रयैः भिन्नो वसाज्यमध्वाभं स्रवेत्तत्रोल्वणोनिलः", text: "medonilakaphairgranthiḥ snāyumāṃsasirāśrayaiḥ bhinno vasājyamadhvābhaṃ sravettatrolvaṇonilaḥ" },
      { type: "verse", number: "19", sanskrit: "मांमं विशोष्य ग्रन्थितां शर्करामुपपादयेत् दुर्गन्धिं रुधिरं क्लिन्नं नानावर्णं ततो मलाः तां स्रावयन्ति निचितां विद्यात्तच्छर्करार्बुदम्", text: "māṃmaṃ viśoṣya granthitāṃ śarkarāmupapādayet durgandhiṃ rudhiraṃ klinnaṃ nānāvarṇaṃ tato malāḥ tāṃ srāvayanti nicitāṃ vidyāttaccharkarārbudam" },
      { type: "verse", number: "20", sanskrit: "पाणिपादतले सन्धौ जत्रूर्ध्वंवोपचीयते वल्मीकवच्छनैर्ग्रन्थिस्तद्वत्बह्वणुभिर्मुखैः रुग्दाहकण्डूक्लेदाढ्यैर्वल्मीकोसौ समस्तजः", text: "pāṇipādatale sandhau jatrūrdhvaṃvopacīyate valmīkavacchanairgranthistadvatbahvaṇubhirmukhaiḥ rugdāhakaṇḍūkledāḍhyairvalmīkosau samastajaḥ" },
      { type: "verse", number: "21", sanskrit: "शर्करोन्मथिते पादे क्षते वा कण्टकादिभिः ग्रन्थिःकीलवदुत्सन्नो जायते कदरं तु तत्", text: "śarkaronmathite pāde kṣate vā kaṇṭakādibhiḥ granthiḥkīlavadutsanno jāyate kadaraṃ tu tat" },
      { type: "verse", number: "22", sanskrit: "वेगसन्धारणाद्वायुरपानो ऽपानसंश्रयम् अणूकरोति बाह्यान्तर्मार्गमस्य ततः शकृत् कृच्छ्रान्निर्गच्छति व्याधिरयं रुद्धगुदो मतः", text: "vegasandhāraṇādvāyurapāno 'pānasaṃśrayam aṇūkaroti bāhyāntarmārgamasya tataḥ śakṛt kṛcchrānnirgacchati vyādhirayaṃ ruddhagudo mataḥ" },
      { type: "verse", number: "23", sanskrit: "कुर्यात् पित्तानिलं पाकं नखमांसे सरुग्ज्वरम् चिप्पमक्षतरोगं च विद्यादुपनखं च तम्", text: "kuryāt pittānilaṃ pākaṃ nakhamāṃse sarugjvaram cippamakṣatarogaṃ ca vidyādupanakhaṃ ca tam" },
      { type: "verse", number: "24", sanskrit: "कृष्णोभिघाताद्रूक्षश्च खरश्च कुनखो नखः दुष्टकर्दमसंस्पर्शात् कण्डूक्लेदान्वितान्तराः अङ्गुल्यो ऽलसमित्याहुः तिलामांस्तिलकालकान्", text: "kṛṣṇobhighātādrūkṣaśca kharaśca kunakho nakhaḥ duṣṭakardamasaṃsparśāt kaṇḍūkledānvitāntarāḥ aṅgulyo 'lasamityāhuḥ tilāmāṃstilakālakān" },
      { type: "verse", number: "25", sanskrit: "कृष्णानवेदनांस्त्वक्स्थान् मषांस्तानेव चोन्नतान् मषेभ्यस्तून्नततरान् चर्मकीलान् सितासितान् तथाविधो जतुमणिः सरुजो लोहितस्तु सः", text: "kṛṣṇānavedanāṃstvaksthān maṣāṃstāneva connatān maṣebhyastūnnatatarān carmakīlān sitāsitān tathāvidho jatumaṇiḥ sarujo lohitastu saḥ" },
      { type: "verse", number: "26", sanskrit: "कृष्णं सितं वा सहजं मण्डलं लाञ्छनं समम्", text: "kṛṣṇaṃ sitaṃ vā sahajaṃ maṇḍalaṃ lāñchanaṃ samam" },
      { type: "verse", number: "27", sanskrit: "शोकक्रोधादिकुपिताद्वातपित्तान्मुखे तनु श्यामलं मण्डलं व्यङ्गं वक्त्रादन्यत्र नीलिका", text: "śokakrodhādikupitādvātapittānmukhe tanu śyāmalaṃ maṇḍalaṃ vyaṅgaṃ vaktrādanyatra nīlikā" },
      { type: "verse", number: "28", sanskrit: "परुषं परुषस्पर्शं व्यङ्गं श्यावं च मारुतात् पित्तात्ताम्रान्तमानीलं श्वेतान्तं कण्डुमत्कफात् रक्ताद्रक्तान्तमाताम्रं सेषं चिमिचिमायते", text: "paruṣaṃ paruṣasparśaṃ vyaṅgaṃ śyāvaṃ ca mārutāt pittāttāmrāntamānīlaṃ śvetāntaṃ kaṇḍumatkaphāt raktādraktāntamātāmraṃ seṣaṃ cimicimāyate" },
      { type: "verse", number: "29", sanskrit: "वायुनोदीरितः श्लेष्मा त्वचं प्राप्य विशुष्यति ततस्त्वग्जायते पाण्डुः क्रमेण च विचेतना अल्पकण्डूरविक्लेदा सा प्रसुप्तिः प्रसुप्तितः", text: "vāyunodīritaḥ śleṣmā tvacaṃ prāpya viśuṣyati tatastvagjāyate pāṇḍuḥ krameṇa ca vicetanā alpakaṇḍūravikledā sā prasuptiḥ prasuptitaḥ" },
      { type: "verse", number: "30", sanskrit: "असम्यग्वमनोदीर्णपित्तश्लेष्मान्ननिग्रहैः मण्डलान्यतिकण्डूनि रागवन्ति बहूनि च उत्कोठः सोनुबन्धस्तु कोठ इत्यभिधीयते", text: "asamyagvamanodīrṇapittaśleṣmānnanigrahaiḥ maṇḍalānyatikaṇḍūni rāgavanti bahūni ca utkoṭhaḥ sonubandhastu koṭha ityabhidhīyate" },
      { type: "verse", number: "31", sanskrit: "प्रोक्ताः षड्त्रिंशदित्येते क्षुद्ररोगा विभागशः यान् विज्ञाय न सम्मुह्येच्चिकित्सायां चिकित्सकः", text: "proktāḥ ṣaḍtriṃśadityete kṣudrarogā vibhāgaśaḥ yān vijñāya na sammuhyeccikitsāyāṃ cikitsakaḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 37,
    lang: "sa",
    content: [
      { type: "heading", heading: "Крими рога — паразитозы" },
      { type: "text", text: "Глава 37 Уттара стханы — «Крими рога» — посвящена специализированному разделу: паразитозы. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः क्षुद्ररोगप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ kṣudrarogapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "अजगल्लिकामपक्वां जलौकोभिर्ग्राहयेत् यवक्षारशुक्तिसौराष्ट्रीकल्कैश्च लेपयेत्", text: "ajagallikāmapakvāṃ jalaukobhirgrāhayet yavakṣāraśuktisaurāṣṭrīkalkaiśca lepayet" },
      { type: "verse", number: "3", sanskrit: "यवप्रख्यादीन् पाषाणगर्दभान्तान् स्वेदयित्वा सुरदारुकुष्ठमनश्शिलालैर्लेपयेत्", text: "yavaprakhyādīn pāṣāṇagardabhāntān svedayitvā suradārukuṣṭhamanaśśilālairlepayet" },
      { type: "verse", number: "4", sanskrit: "पक्वांस्तु सहाजगल्लिकया व्रणवदुपाचरेत्", text: "pakvāṃstu sahājagallikayā vraṇavadupācaret" },
      { type: "verse", number: "5", sanskrit: "मुखदूषिकां लोध्रतुवरिकाभ्यां वा प्रदिह्यात् वटपत्रनारिकेलशुक्तिभ्यां वा सैन्धववचाक्षिभेषजसिद्धार्थकैर्वा एवमशान्तौ छर्दयेत् ललाटे च सिरां विध्येत्", text: "mukhadūṣikāṃ lodhratuvarikābhyāṃ vā pradihyāt vaṭapatranārikelaśuktibhyāṃ vā saindhavavacākṣibheṣajasiddhārthakairvā evamaśāntau chardayet lalāṭe ca sirāṃ vidhyet" },
      { type: "verse", number: "6", sanskrit: "पद्मकण्टकेषु निम्बाम्बुवान्तं निम्बोदकसिद्धं सर्पिः सक्षौद्रं पाययेत् निम्बारग्वधकषायेण चोद्वर्तनम्", text: "padmakaṇṭakeṣu nimbāmbuvāntaṃ nimbodakasiddhaṃ sarpiḥ sakṣaudraṃ pāyayet nimbāragvadhakaṣāyeṇa codvartanam" },
      { type: "verse", number: "7", sanskrit: "विवृतादीन् जालगर्दभान्तनिरिवेल्लिकां च पित्तविसर्पवच्चिकित्सेत्", text: "vivṛtādīn jālagardabhāntanirivellikāṃ ca pittavisarpavaccikitset" },
      { type: "verse", number: "8", sanskrit: "विशेषतो राजिकामपाकशर्करामूर्वाकण्टकशर्कराभिः क्षीरपिष्टअभिर्लेपयेत् अभीक्ष्णं च मृजाशीलनम् जालगर्दभे धात्रीफलान्युपयुञ्जीत", text: "viśeṣato rājikāmapākaśarkarāmūrvākaṇṭakaśarkarābhiḥ kṣīrapiṣṭAabhirlepayet abhīkṣṇaṃ ca mṛjāśīlanam jālagardabhe dhātrīphalānyupayuñjīta" },
      { type: "verse", number: "9", sanskrit: "अग्निरोहिणीमपि प्रत्याख्याय पित्तविसर्पदुपाचरेत् पक्वां तु मधुरवर्गसिद्धेन सर्पिषां रोपयेत्", text: "agnirohiṇīmapi pratyākhyāya pittavisarpadupācaret pakvāṃ tu madhuravargasiddhena sarpiṣāṃ ropayet" },
      { type: "verse", number: "10", sanskrit: "विदारिकां जलवासिनीभिर्ग्राहयित्वा बिल्वमूलनगवृत्तिकवर्षाभ्वजकर्णपलाशकल्केन प्रलिम्पेत् अनुपशाम्यन्तीं त्वभ्यज्य स्वेदयित्वा विम्लापयेत् पक्वां शस्त्रेण विदार्य निम्बतिलपटोलकल्केन प्रच्छाद्य बध्नीयात् क्षीरिवृक्षकदरखदिरकषायो व्रणप्रक्षालनम् शुद्धां मधुरकषायसंस्कृतेन तैलेन रोपयेत्", text: "vidārikāṃ jalavāsinībhirgrāhayitvā bilvamūlanagavṛttikavarṣābhvajakarṇapalāśakalkena pralimpet anupaśāmyantīṃ tvabhyajya svedayitvā vimlāpayet pakvāṃ śastreṇa vidārya nimbatilapaṭolakalkena pracchādya badhnīyāt kṣīrivṛkṣakadarakhadirakaṣāyo vraṇaprakṣālanam śuddhāṃ madhurakaṣāyasaṃskṛtena tailena ropayet" },
      { type: "verse", number: "11", sanskrit: "शर्करार्बुदं मेदोर्बुदवदुपाचरेत्", text: "śarkarārbudaṃ medorbudavadupācaret" },
      { type: "verse", number: "12", sanskrit: "बल्मीकं हस्तस्य पादस्य चोपरिष्टान्मर्मणि वा जातं प्रवृद्धमतिबहुच्छिद्रावृतं सशोफं च वर्जयेत्", text: "balmīkaṃ hastasya pādasya copariṣṭānmarmaṇi vā jātaṃ pravṛddhamatibahucchidrāvṛtaṃ saśophaṃ ca varjayet" },
      { type: "verse", number: "13", sanskrit: "अतोन्यथा तु प्राक् कृतशुद्धेः शोणितमपहरेत् सक्तुपलललवणगुडूच्यारेवतश्यामादन्तीकुलत्थिकामूर्लेलैपयेत्", text: "atonyathā tu prāk kṛtaśuddheḥ śoṇitamapaharet saktupalalalavaṇaguḍūcyārevataśyāmādantīkulatthikāmūrlelaipayet" },
      { type: "verse", number: "14", sanskrit: "पक्वे तु सर्वां गतिं दुष्टमांसानि च शस्त्रेण सम्यक्शोधयित्वाग्निना क्षारेण वा दहेत्", text: "pakve tu sarvāṃ gatiṃ duṣṭamāṃsāni ca śastreṇa samyakśodhayitvāgninā kṣāreṇa vā dahet" },
      { type: "verse", number: "15", sanskrit: "सुशुद्धे तु व्रणे भल्लातकमनश्शिलालैलाकालानुसार्यगरुचन्दनैर्निम्बतैलं रोपणार्थं श्रपयेत्", text: "suśuddhe tu vraṇe bhallātakamanaśśilālailākālānusāryagarucandanairnimbatailaṃ ropaṇārthaṃ śrapayet" },
      { type: "verse", number: "16", sanskrit: "कदरं शस्त्रेणोत्कृत्य स्नेहेन दहेत्", text: "kadaraṃ śastreṇotkṛtya snehena dahet" },
      { type: "verse", number: "17", sanskrit: "रुद्धगुदे निरुद्धमणिवच्चिकित्सा", text: "ruddhagude niruddhamaṇivaccikitsā" },
      { type: "verse", number: "18", sanskrit: "चिप्पं शोणितावसेकसंशोधनैरुपाचरेत् व्यपगतोष्माणञ्चैनमुष्णाम्बुना परिषिच्य यथायोगं शस्त्रेण परिकर्त्यापनयेत्", text: "cippaṃ śoṇitāvasekasaṃśodhanairupācaret vyapagatoṣmāṇañcainamuṣṇāmbunā pariṣicya yathāyogaṃ śastreṇa parikartyāpanayet" },
      { type: "verse", number: "19", sanskrit: "ततो रसाञ्जनरोचनानेपालीतेजोह्वाकल्कैरम्लपिष्टैः शोधयित्वा कालेयकागरुहरिद्रारसाञ्जनसिद्धेनतैलेन रोपयेत् मधुरकषायसिद्धेन वा अल्पावशिष्टं च सर्जरसचूर्णेन पूरयेत्", text: "tato rasāñjanarocanānepālītejohvākalkairamlapiṣṭaiḥ śodhayitvā kāleyakāgaruharidrārasāñjanasiddhenatailena ropayet madhurakaṣāyasiddhena vā alpāvaśiṣṭaṃ ca sarjarasacūrṇena pūrayet" },
      { type: "verse", number: "20", sanskrit: "कुनखमपि प्रदुष्टमेवमेवोपक्रमेत्", text: "kunakhamapi praduṣṭamevamevopakramet" },
      { type: "verse", number: "21", sanskrit: "अलसेत्वम्लकाञ्जिकावसिक्तौ चरणौ निम्बतिलपटोलीकासीसरोचनाकल्केनाकल्केनालेपयेत् निदिग्धिकारससिद्धेन सर्षपतैलेनाभ्यज्य रोचनाकासीसमनश्शिलाचूर्णैः प्रतिसारयेत्", text: "alasetvamlakāñjikāvasiktau caraṇau nimbatilapaṭolīkāsīsarocanākalkenākalkenālepayet nidigdhikārasasiddhena sarṣapatailenābhyajya rocanākāsīsamanaśśilācūrṇaiḥ pratisārayet" },
      { type: "verse", number: "22", sanskrit: "तिलकालकान् मषांश्च सूर्यकान्तेनाग्निना वा दहेत् क्षारेण वा चर्मकलिं जतुमणिं च तद्वच्छस्त्रेणोत्कृत्य", text: "tilakālakān maṣāṃśca sūryakāntenāgninā vā dahet kṣāreṇa vā carmakaliṃ jatumaṇiṃ ca tadvacchastreṇotkṛtya" },
      { type: "verse", number: "23", sanskrit: "लाञ्च्छनव्यङ्गनीलिकासु यथासन्नां सिरां विध्येत् क्षीरीवृक्षवल्ककल्कैश्च क्षीरपिष्टैर्लेपयेत् बलातिबलामधुकहरिद्राभिर्वा मधुकागरुपयस्याकालीयकैर्वा तरुणकपित्थतिन्दुकरजनीभिर्वा अम्लिकामूलेन वा सूकरदंष्ट्रया वा मधुघृतयुक्तया", text: "lāñcchanavyaṅganīlikāsu yathāsannāṃ sirāṃ vidhyet kṣīrīvṛkṣavalkakalkaiśca kṣīrapiṣṭairlepayet balātibalāmadhukaharidrābhirvā madhukāgarupayasyākālīyakairvā taruṇakapitthatindukarajanībhirvā amlikāmūlena vā sūkaradaṃṣṭrayā vā madhughṛtayuktayā" },
      { type: "verse", number: "24", sanskrit: "विशेषेण व्यङ्गेष्वसृक्स्रावपूर्वमर्जुनपरिपोटैर्लेपः क्षौद्रेण वा पिष्टा मञ्जिष्ठा अजाक्षीरेणवार्द्रदाडिमत्वक् तेनैव वा बालामलकं गोमूत्रेण सप्ताहं स्थितम् दधिमण्डेन वा कालेयकलोध्रोत्पलकिञ्जल्कम् नवनीतेन वा श्वेताश्वखुरजमषी", text: "viśeṣeṇa vyaṅgeṣvasṛksrāvapūrvamarjunaparipoṭairlepaḥ kṣaudreṇa vā piṣṭā mañjiṣṭhā ajākṣīreṇavārdradāḍimatvak tenaiva vā bālāmalakaṃ gomūtreṇa saptāhaṃ sthitam dadhimaṇḍena vā kāleyakalodhrotpalakiñjalkam navanītena vā śvetāśvakhurajamaṣī" },
      { type: "verse", number: "25", sanskrit: "तत्रापि वातजेषु देवदारुदुरालभाबृहतीमञ्जिष्ठामूर्वापामार्गत्रायन्तीत्रायमाणाशुकनसाबलाविदारीयवबदरकुलत्थबिल्वोत्पलशतावरीदर्भमूलक्वाथे शृङ्गीविडङ्गगर्भं घृतं विपक्वमधोभक्तं पानमभ्यङ्गं नावनं च सायं योजयेत्", text: "tatrāpi vātajeṣu devadārudurālabhābṛhatīmañjiṣṭhāmūrvāpāmārgatrāyantītrāyamāṇāśukanasābalāvidārīyavabadarakulatthabilvotpalaśatāvarīdarbhamūlakvāthe śṛṅgīviḍaṅgagarbhaṃ ghṛtaṃ vipakvamadhobhaktaṃ pānamabhyaṅgaṃ nāvanaṃ ca sāyaṃ yojayet" },
      { type: "verse", number: "26", sanskrit: "प्रलेपं च न्यग्रोधदेवदारुहरीतकीपूतीकरञ्जमदनफलचूर्णैर्घृतयुक्तैः बदरमज्जाकोद्रवलाजचूर्णेन वा सघृतेन श्वेतचमरास्थितालपत्रीस्तन्यमधुघृतैर्वा", text: "pralepaṃ ca nyagrodhadevadāruharītakīpūtīkarañjamadanaphalacūrṇairghṛtayuktaiḥ badaramajjākodravalājacūrṇena vā saghṛtena śvetacamarāsthitālapatrīstanyamadhughṛtairvā" },
      { type: "verse", number: "27", sanskrit: "पैत्तेषु बलामधुकमागधिकाक्षीरकाकोलीस्वगुप्ताफलकाकमाचीतुगाह्वाभिः सपयः सर्पिः सिद्धं पूर्ववत् प्रयोजयेत्", text: "paitteṣu balāmadhukamāgadhikākṣīrakākolīsvaguptāphalakākamācītugāhvābhiḥ sapayaḥ sarpiḥ siddhaṃ pūrvavat prayojayet" },
      { type: "verse", number: "28", sanskrit: "मृद्वीकाश्वेतपाकीखर्जूरपरूषकसौवीरबदरद्विमेदापुनर्नवकशेरुकाप्रवालविद्रुममृणालैर्वा सक्षीरैः", text: "mṛdvīkāśvetapākīkharjūraparūṣakasauvīrabadaradvimedāpunarnavakaśerukāpravālavidrumamṛṇālairvā sakṣīraiḥ" },
      { type: "verse", number: "29", sanskrit: "उपस्निग्धं चैनमिक्षुरसेनोभयतो विरेचयेत्", text: "upasnigdhaṃ cainamikṣurasenobhayato virecayet" },
      { type: "verse", number: "30", sanskrit: "कृतरुधिरावसेचनानेतांश्च व्यङ्गान् मधुकसारिवाबलाचन्दनलोध्रोत्पलैर्घृतयुक्तैरालेपयेत् प्रपौण्डरीकमधुकपद्मकनीलोत्पलसारिवाकदलीमूलप्रवालसुवर्णगैरिकैर्वा शीतमधुरमन्नपानं प्रवातमहःस्वप्नं सौमनस्यं च सेवेत", text: "kṛtarudhirāvasecanānetāṃśca vyaṅgān madhukasārivābalācandanalodhrotpalairghṛtayuktairālepayet prapauṇḍarīkamadhukapadmakanīlotpalasārivākadalīmūlapravālasuvarṇagairikairvā śītamadhuramannapānaṃ pravātamahaḥsvapnaṃ saumanasyaṃ ca seveta" },
      { type: "verse", number: "31", sanskrit: "कफजेषु दशमूलदेवदारुहरीतकीश्वदंष्ट्रामलकीक्वाथे मुस्तकुष्ठहरिद्रामरतरुकल्कैस्तद्वत् साधितं सर्पिस्तद्वदेवोपयुञ्जीत", text: "kaphajeṣu daśamūladevadāruharītakīśvadaṃṣṭrāmalakīkvāthe mustakuṣṭhaharidrāmaratarukalkaistadvat sādhitaṃ sarpistadvadevopayuñjīta" },
      { type: "verse", number: "32", sanskrit: "तुत्थरोचनालोध्रप्रियङ्गुकालेयकैः समधुघृतैर्लेपः देवदारुसरलबलाशिग्रुमूलैर्वा मनश्शिलातुत्थरसाञ्जनैर्वा मृदुना वा क्षारेण दशमात्राः प्रलेपः", text: "tuttharocanālodhrapriyaṅgukāleyakaiḥ samadhughṛtairlepaḥ devadārusaralabalāśigrumūlairvā manaśśilātuttharasāñjanairvā mṛdunā vā kṣāreṇa daśamātrāḥ pralepaḥ" },
      { type: "verse", number: "33", sanskrit: "रक्तजेषु क्षीरसर्पिःस्निग्धस्य सिरां विस्रावयेत् वमनविरेचने च पित्तवत् कुर्यात् आलेपश्चास्य चन्दनमधुककल्केन घृतवता सर्जरसनीलोत्पलशङ्खवेतसकदलीमूलमूर्वामधुककल्केन वा", text: "raktajeṣu kṣīrasarpiḥsnigdhasya sirāṃ visrāvayet vamanavirecane ca pittavat kuryāt ālepaścāsya candanamadhukakalkena ghṛtavatā sarjarasanīlotpalaśaṅkhavetasakadalīmūlamūrvāmadhukakalkena vā" },
      { type: "verse", number: "34", sanskrit: "प्रसुप्तौ वातकुष्ठोक्तक्रमो ऽन्ते चाग्निना दाहः", text: "prasuptau vātakuṣṭhoktakramo 'nte cāgninā dāhaḥ" },
      { type: "verse", number: "35", sanskrit: "उत्कोठे पित्तश्लेष्महरो विधिः सक्षारलवणं च तैलमभ्यङ्गः कोठे कुष्ठचिकित्सितमीक्षेत", text: "utkoṭhe pittaśleṣmaharo vidhiḥ sakṣāralavaṇaṃ ca tailamabhyaṅgaḥ koṭhe kuṣṭhacikitsitamīkṣeta" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 38,
    lang: "sa",
    content: [
      { type: "heading", heading: "Расаяна тантра — омоложение — введение" },
      { type: "text", text: "Глава 38 Уттара стханы — «Расаяна тантра» — посвящена специализированному разделу: омоложение — введение. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो गुह्यरोगविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto guhyarogavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "स्त्रीव्यवायनिवृत्तस्य सहसा भजतोथवा दोषाध्युषितसङ्कीर्णमलिनाणुरजःपथाम्", text: "strīvyavāyanivṛttasya sahasā bhajatothavā doṣādhyuṣitasaṅkīrṇamalināṇurajaḥpathām" },
      { type: "verse", number: "3", sanskrit: "अन्ययोनिमनिच्छन्तीमगम्यां नवसूतिकाम् तृषितं स्पृशतस्तोयं रतान्तेष्वपि नैव वा", text: "anyayonimanicchantīmagamyāṃ navasūtikām tṛṣitaṃ spṛśatastoyaṃ ratānteṣvapi naiva vā" },
      { type: "verse", number: "4", sanskrit: "विवर्धयिषया तीक्ष्णान् प्रलेपादीन् प्रयच्छतः मुष्टिदन्तनखोत्पीडाविषवच्छूकपातनैः", text: "vivardhayiṣayā tīkṣṇān pralepādīn prayacchataḥ muṣṭidantanakhotpīḍāviṣavacchūkapātanaiḥ" },
      { type: "verse", number: "5", sanskrit: "वेगनिग्रहदीर्घातिखरशष्पविघट्टनैः दोषा दुष्टा गता गुह्यं त्रयोविंशतिमामयान्", text: "veganigrahadīrghātikharaśaṣpavighaṭṭanaiḥ doṣā duṣṭā gatā guhyaṃ trayoviṃśatimāmayān" },
      { type: "verse", number: "6", sanskrit: "जनयन्त्युपदंशादीन् उपदंशो ऽत्र पञ्चधा पृथग्दोषैः सरुधिरैः समस्तैश्च अत्र मारुतात् मेढ्रशोफो रुजश्चित्राः स्तम्भस्त्वक्परिपोटनम्", text: "janayantyupadaṃśādīn upadaṃśo 'tra pañcadhā pṛthagdoṣaiḥ sarudhiraiḥ samastaiśca atra mārutāt meḍhraśopho rujaścitrāḥ stambhastvakparipoṭanam" },
      { type: "verse", number: "7", sanskrit: "पक्वोदुम्बरसङ्काशं पित्तेन श्वयथुर्ज्वरः", text: "pakvodumbarasaṅkāśaṃ pittena śvayathurjvaraḥ" },
      { type: "verse", number: "8", sanskrit: "श्लेष्मणा कठिनः स्निग्धः कण्डूमाञ्छीतलो गुरुः", text: "śleṣmaṇā kaṭhinaḥ snigdhaḥ kaṇḍūmāñchītalo guruḥ" },
      { type: "verse", number: "9", sanskrit: "शोणितेनासितस्फोटसम्भवोस्रस्रुतिर्ज्वरः", text: "śoṇitenāsitasphoṭasambhavosrasrutirjvaraḥ" },
      { type: "verse", number: "10", sanskrit: "तीव्रारुगाशुपचनं दरणं कृमिसम्भवः", text: "tīvrārugāśupacanaṃ daraṇaṃ kṛmisambhavaḥ" },
      { type: "verse", number: "11", sanskrit: "याप्यो रक्तोद्भवस्तेषां मृत्यवे सन्निपातजः", text: "yāpyo raktodbhavasteṣāṃ mṛtyave sannipātajaḥ" },
      { type: "verse", number: "12", sanskrit: "जायन्ते कुपितैर्दोषैर्गुह्यासृक्पिशिताश्रयैः अन्तर्बहिर्वा मेढ्रस्य कण्डूला मांसकीलकाः", text: "jāyante kupitairdoṣairguhyāsṛkpiśitāśrayaiḥ antarbahirvā meḍhrasya kaṇḍūlā māṃsakīlakāḥ" },
      { type: "verse", number: "13", sanskrit: "पिच्छिलास्रस्रवा योनौ तद्वच्च छत्रसन्निभाः तेर्शांस्युपेक्षया घ्नन्ति मेढ्रपुंस्त्वभगातर्वम्", text: "picchilāsrasravā yonau tadvacca chatrasannibhāḥ terśāṃsyupekṣayā ghnanti meḍhrapuṃstvabhagātarvam" },
      { type: "verse", number: "14", sanskrit: "गुह्यस्य बहिरन्तर्वा पिटकाः कफरक्तजाः सर्षपामानसंस्थाना घनाः सर्षपिकाः स्मृताः", text: "guhyasya bahirantarvā piṭakāḥ kapharaktajāḥ sarṣapāmānasaṃsthānā ghanāḥ sarṣapikāḥ smṛtāḥ" },
      { type: "verse", number: "15", sanskrit: "पिटका बहवो दीर्घा दीर्यन्ते मध्यतश्च याः सो ऽवमन्थः कफासृग्भ्यां वेदनारोमहर्षवान्", text: "piṭakā bahavo dīrghā dīryante madhyataśca yāḥ so 'vamanthaḥ kaphāsṛgbhyāṃ vedanāromaharṣavān" },
      { type: "verse", number: "16", sanskrit: "कुम्भीका रक्तपित्तोत्था जाम्बवास्थिनिभाशुजा", text: "kumbhīkā raktapittotthā jāmbavāsthinibhāśujā" },
      { type: "verse", number: "17", sanskrit: "अलजीं मेहवद्विद्यात् उत्तमां रक्तपित्तजाम् पिटकां माषमुद्गाभाम् पिटका पिटकाचिता कर्णिका पुष्करस्येव ज्ञेया पुष्करिकेति सा", text: "alajīṃ mehavadvidyāt uttamāṃ raktapittajām piṭakāṃ māṣamudgābhām piṭakā piṭakācitā karṇikā puṣkarasyeva jñeyā puṣkariketi sā" },
      { type: "verse", number: "18", sanskrit: "पाणिभ्यां भृशसंव्यूढे संव्यूढपिटका भवेत्", text: "pāṇibhyāṃ bhṛśasaṃvyūḍhe saṃvyūḍhapiṭakā bhavet" },
      { type: "verse", number: "19", sanskrit: "मृदितं मृदितं वस्तु संरब्धं वातकोपतः", text: "mṛditaṃ mṛditaṃ vastu saṃrabdhaṃ vātakopataḥ" },
      { type: "verse", number: "20", sanskrit: "विषमा कठिना भुग्ना वायुनाष्ठीलिका स्मृता", text: "viṣamā kaṭhinā bhugnā vāyunāṣṭhīlikā smṛtā" },
      { type: "verse", number: "21", sanskrit: "विमर्दनादिदुष्टेन वायुना चर्म मेढ्रजम् निवर्तते सरुग्दाहं क्वचित् पाकं च गच्छति", text: "vimardanādiduṣṭena vāyunā carma meḍhrajam nivartate sarugdāhaṃ kvacit pākaṃ ca gacchati" },
      { type: "verse", number: "22", sanskrit: "पिण्डितं कुथितं चर्म तत्प्रलम्बमधोमणेः निवृत्तसंज्ञं सकफं कण्डूकाठिन्यवत्तु तत्", text: "piṇḍitaṃ kuthitaṃ carma tatpralambamadhomaṇeḥ nivṛttasaṃjñaṃ sakaphaṃ kaṇḍūkāṭhinyavattu tat" },
      { type: "verse", number: "23", sanskrit: "दुरूढं स्फुटितं चर्म निर्दिष्टमवपाटिका", text: "durūḍhaṃ sphuṭitaṃ carma nirdiṣṭamavapāṭikā" },
      { type: "verse", number: "24", sanskrit: "वातेन दूषितं चर्म मणौ सक्तं रुणद्धि चेत् स्रोतो मूत्रं ततोभ्येति मन्दधारमेवदनम् मणेर्विकासरोधश्च स निरुद्धमणिर्गदः", text: "vātena dūṣitaṃ carma maṇau saktaṃ ruṇaddhi cet sroto mūtraṃ tatobhyeti mandadhāramevadanam maṇervikāsarodhaśca sa niruddhamaṇirgadaḥ" },
      { type: "verse", number: "25", sanskrit: "लिङ्गं शूकैरिवाकीर्णं ग्रथिताख्यं कफोद्भवम्", text: "liṅgaṃ śūkairivākīrṇaṃ grathitākhyaṃ kaphodbhavam" },
      { type: "verse", number: "26", sanskrit: "शूकदूषितरक्तोत्था स्पर्शहानिस्तदाह्वया", text: "śūkadūṣitaraktotthā sparśahānistadāhvayā" },
      { type: "verse", number: "27", sanskrit: "छिद्रैरणुमुखैर्यत्तु मेहनं सर्वतश्चितम् वातशोणितकोपेन तं विद्याच्छतपोनकम्", text: "chidrairaṇumukhairyattu mehanaṃ sarvataścitam vātaśoṇitakopena taṃ vidyācchataponakam" },
      { type: "verse", number: "28", sanskrit: "पित्तासृग्भ्यां त्वचः पाकस्त्वक्पाको ज्वरदाहवान्", text: "pittāsṛgbhyāṃ tvacaḥ pākastvakpāko jvaradāhavān" },
      { type: "verse", number: "29", sanskrit: "मांस्पाकः सर्वजः सर्ववेदनो मांसशातनः", text: "māṃspākaḥ sarvajaḥ sarvavedano māṃsaśātanaḥ" },
      { type: "verse", number: "30", sanskrit: "सरागैरसितैः स्फोटैर्वेदनाभिश्च पीडितम् मेहनं वेदना चोग्रा तं विद्यादसृगर्बुदम्", text: "sarāgairasitaiḥ sphoṭairvedanābhiśca pīḍitam mehanaṃ vedanā cogrā taṃ vidyādasṛgarbudam" },
      { type: "verse", number: "31", sanskrit: "मांसार्बुदं प्रागुदितं विद्रधिश्च त्रिदोषजः", text: "māṃsārbudaṃ prāguditaṃ vidradhiśca tridoṣajaḥ" },
      { type: "verse", number: "32", sanskrit: "कृष्णानि भूत्वा मांसानि विशीर्यन्ते समन्ततः पक्वानि सन्निपातेन तान् विद्यात्तिलकालकान्", text: "kṛṣṇāni bhūtvā māṃsāni viśīryante samantataḥ pakvāni sannipātena tān vidyāttilakālakān" },
      { type: "verse", number: "33", sanskrit: "मांसोत्थमर्बुदं पाकं विद्रधिं तिलकालकान् चतुरो वर्जयेदोषां शेषान् शीघ्रमुपाचरेत्", text: "māṃsotthamarbudaṃ pākaṃ vidradhiṃ tilakālakān caturo varjayedoṣāṃ śeṣān śīghramupācaret" },
      { type: "verse", number: "34", sanskrit: "विंशतिर्व्यापदो योनेर्जायन्ते दुष्टभोजनात् विषमस्थाङ्गशयनभृशमैथुनसेवनैः दुष्टार्तवादपद्रव्यैर्बीजदोषेण दैवतः", text: "viṃśatirvyāpado yonerjāyante duṣṭabhojanāt viṣamasthāṅgaśayanabhṛśamaithunasevanaiḥ duṣṭārtavādapadravyairbījadoṣeṇa daivataḥ" },
      { type: "verse", number: "35", sanskrit: "योनौ क्रुद्धो ऽनिलः कुर्याद्रुक्तोदायामसुप्तताः पिपीलिकासृप्तिमिव स्तम्भं कर्कशतां स्वनम्", text: "yonau kruddho 'nilaḥ kuryādruktodāyāmasuptatāḥ pipīlikāsṛptimiva stambhaṃ karkaśatāṃ svanam" },
      { type: "verse", number: "36", sanskrit: "फेनिलारुणकृष्णाल्पतनुरूक्षार्तवस्रुतिम् भ्रंशं वङ्क्षणपार्श्वादौ व्यथां गुल्मं क्रमेण च तांस्तांश्च स्वान् गदान् व्यापद्वातिकी नाम सा स्मृता", text: "phenilāruṇakṛṣṇālpatanurūkṣārtavasrutim bhraṃśaṃ vaṅkṣaṇapārśvādau vyathāṃ gulmaṃ krameṇa ca tāṃstāṃśca svān gadān vyāpadvātikī nāma sā smṛtā" },
      { type: "verse", number: "37", sanskrit: "सैवातिचरणा शोफसंयुक्तातिव्यवायतः", text: "saivāticaraṇā śophasaṃyuktātivyavāyataḥ" },
      { type: "verse", number: "38", sanskrit: "मैथुनादतिबालायाः पृष्ठजङ्घोरुवङ्क्षणम् रुजन् सन्दूषयेद्योनिं वायुः प्राक्चरणेति सः", text: "maithunādatibālāyāḥ pṛṣṭhajaṅghoruvaṅkṣaṇam rujan sandūṣayedyoniṃ vāyuḥ prākcaraṇeti saḥ" },
      { type: "verse", number: "39", sanskrit: "वेगोदावर्तनाद्योनिं प्रपीडयति मारुतः सा फेनिलं रजः कृच्छ्रादुदावृत्तं विमुञ्चति", text: "vegodāvartanādyoniṃ prapīḍayati mārutaḥ sā phenilaṃ rajaḥ kṛcchrādudāvṛttaṃ vimuñcati" },
      { type: "verse", number: "40", sanskrit: "इयं व्यापदुदावृत्ता जातघ्नी तु यदानिलः जातं जातं सुतं हन्ति रौक्ष्याद्दुष्टार्तवोद्भवम्", text: "iyaṃ vyāpadudāvṛttā jātaghnī tu yadānilaḥ jātaṃ jātaṃ sutaṃ hanti raukṣyādduṣṭārtavodbhavam" },
      { type: "verse", number: "41", sanskrit: "अत्याशिताया विषमं स्थितायाः सुरते मरुत् अन्नेनोत्पीडितो योनेः स्थितः स्रोतसि वक्रयेत् सास्थिमांसं मुखं तीव्ररुजमन्तर्मुखीति सा", text: "atyāśitāyā viṣamaṃ sthitāyāḥ surate marut annenotpīḍito yoneḥ sthitaḥ srotasi vakrayet sāsthimāṃsaṃ mukhaṃ tīvrarujamantarmukhīti sā" },
      { type: "verse", number: "42", sanskrit: "वातलाहारसेविन्यां जनन्यां कुपितोनिलः स्त्रिया योनिमणुद्वारां कुर्यात् सूचिमुखीति सा", text: "vātalāhārasevinyāṃ jananyāṃ kupitonilaḥ striyā yonimaṇudvārāṃ kuryāt sūcimukhīti sā" },
      { type: "verse", number: "43", sanskrit: "वेगरोधादृतौ वायुर्दुष्टो विण्मूत्रसङ्ग्रहम् करोति योनिशोषं च शुष्काख्या सातिवेदना", text: "vegarodhādṛtau vāyurduṣṭo viṇmūtrasaṅgraham karoti yoniśoṣaṃ ca śuṣkākhyā sātivedanā" },
      { type: "verse", number: "44", sanskrit: "षडहात् सप्तरात्राद्वा शुक्रं गर्भाशयान्मरुत् वमेत् सरुङ्नीरुजो वा यस्यां सा वामिनी मता", text: "ṣaḍahāt saptarātrādvā śukraṃ garbhāśayānmarut vamet saruṅnīrujo vā yasyāṃ sā vāminī matā" },
      { type: "verse", number: "45", sanskrit: "योनौ वातोपतप्तायां स्त्रीगर्भे बीजदोषतः नृद्वेषिण्यस्तनी च स्यात् षण्डसंज्ञानुपत्रमा", text: "yonau vātopataptāyāṃ strīgarbhe bījadoṣataḥ nṛdveṣiṇyastanī ca syāt ṣaṇḍasaṃjñānupatramā" },
      { type: "verse", number: "46", sanskrit: "दुष्टो विष्टभ्य योन्यास्यं गर्भकोष्ठं च मारुतः कुरुते विवृतां स्रस्तां वातिकीमिव दुःखिताम् उत्सन्नमांसां तामाहुर्महायोनिं महारुजम्", text: "duṣṭo viṣṭabhya yonyāsyaṃ garbhakoṣṭhaṃ ca mārutaḥ kurute vivṛtāṃ srastāṃ vātikīmiva duḥkhitām utsannamāṃsāṃ tāmāhurmahāyoniṃ mahārujam" },
      { type: "verse", number: "47", sanskrit: "यथास्वैर्दूषणैर्दुष्टं पित्तं योनिसमाश्रितम् करोति दाहपाकोषापूतिगन्धज्वरान्विताम् भृशोष्णभूरिकुणपनीलपीतासितार्तवाम्", text: "yathāsvairdūṣaṇairduṣṭaṃ pittaṃ yonisamāśritam karoti dāhapākoṣāpūtigandhajvarānvitām bhṛśoṣṇabhūrikuṇapanīlapītāsitārtavām" },
      { type: "verse", number: "48", sanskrit: "सा व्यापत् पैत्तिकी रक्तयोन्याख्यासृगतिस्रुतेः", text: "sā vyāpat paittikī raktayonyākhyāsṛgatisruteḥ" },
      { type: "verse", number: "49", sanskrit: "कफोभिष्यन्दिभिः क्रुद्धः कुर्याद्योनिमवेदनाम् शतिलां कण्डुलां पाण्डु पिच्छिलां तद्विधस्रुतिम् सा व्यापच्छ्लैष्मिकी #", text: "kaphobhiṣyandibhiḥ kruddhaḥ kuryādyonimavedanām śatilāṃ kaṇḍulāṃ pāṇḍu picchilāṃ tadvidhasrutim sā vyāpacchlaiṣmikī #" },
      { type: "verse", number: "50", sanskrit: "वातपित्ताभ्यां क्षीयते रजः सदाहकार्श्यवैवर्ण्यं यस्यां सा लोहितक्षया", text: "vātapittābhyāṃ kṣīyate rajaḥ sadāhakārśyavaivarṇyaṃ yasyāṃ sā lohitakṣayā" },
      { type: "verse", number: "51", sanskrit: "पित्तलाया नृसंवासे क्षवथूद्गारधारणात् पित्तयुक्तेन मरुता योनिर्भवति दूषिता", text: "pittalāyā nṛsaṃvāse kṣavathūdgāradhāraṇāt pittayuktena marutā yonirbhavati dūṣitā" },
      { type: "verse", number: "52", sanskrit: "शूना स्पर्शासहा सर्पिर्नीलपीतास्रवाहिनी बस्तिकुक्षिगुरुत्वातिसारारोचककारिणी श्रेणिवङ्क्षणरुक्तोदज्वरकृत्सा परिप्लुता", text: "śūnā sparśāsahā sarpirnīlapītāsravāhinī bastikukṣigurutvātisārārocakakāriṇī śreṇivaṅkṣaṇaruktodajvarakṛtsā pariplutā" },
      { type: "verse", number: "53", sanskrit: "वातश्लेष्मामयव्याप्ता श्वेतपिच्छिलवाहिनी", text: "vātaśleṣmāmayavyāptā śvetapicchilavāhinī" },
      { type: "verse", number: "54", sanskrit: "उपप्लुता स्मृता योनिः विप्लताख्या त्वधावनात् सञ्जातजन्तुः कण्डूला कण्ड्वा चातिरतिप्रिया", text: "upaplutā smṛtā yoniḥ viplatākhyā tvadhāvanāt sañjātajantuḥ kaṇḍūlā kaṇḍvā cātiratipriyā" },
      { type: "verse", number: "55", sanskrit: "अकालवाहनाद्वायुः श्लेष्मरक्तविमूर्च्छितः कर्णिकां जनयेद्योनौ रजोमार्गनिरोधिनीम्", text: "akālavāhanādvāyuḥ śleṣmaraktavimūrcchitaḥ karṇikāṃ janayedyonau rajomārganirodhinīm" },
      { type: "verse", number: "56", sanskrit: "सा कर्णिनी त्रिभिर्दोषैर्योनिगर्भाशयाश्रितैः यथास्वोपद्रवकरैर्व्यापत् सा सान्निपातिकी", text: "sā karṇinī tribhirdoṣairyonigarbhāśayāśritaiḥ yathāsvopadravakarairvyāpat sā sānnipātikī" },
      { type: "verse", number: "57", sanskrit: "इति योनिगदा नारी यैः शुक्रं न प्रतीच्छति ततो गर्भं न नृह्णणाति रोगांश्चाप्नोति दारुणान् असृग्दरार्शोगुल्मादीनाबाधांश्चानिलादिभिः", text: "iti yonigadā nārī yaiḥ śukraṃ na pratīcchati tato garbhaṃ na nṛhṇaṇāti rogāṃścāpnoti dāruṇān asṛgdarārśogulmādīnābādhāṃścānilādibhiḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 39,
    lang: "sa",
    content: [
      { type: "heading", heading: "Расаяна адхьяя — методы омоложения" },
      { type: "text", text: "Глава 39 Уттара стханы — «Расаяна адхьяя» — посвящена специализированному разделу: методы омоложения. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो गुह्यरोगप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto guhyarogapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "उपदंशेषूत्पन्नमात्रेषु पाकपरिहारार्थं मेढ्रमध्ये सिरां विध्येत् उभयतश्चास्य विधिवद्दोषानपहरेद्विशेषतो विरेचनेन तदयोग्यस्य त्वत्युच्छ्रितानास्थापनेन", text: "upadaṃśeṣūtpannamātreṣu pākaparihārārthaṃ meḍhramadhye sirāṃ vidhyet ubhayataścāsya vidhivaddoṣānapaharedviśeṣato virecanena tadayogyasya tvatyucchritānāsthāpanena" },
      { type: "verse", number: "3", sanskrit: "यथादोषं चालेपसेकादीनविरतं विदध्यात् एवं सद्य एव रुक्तोदशोफरागसंरम्भा निवर्तन्ते", text: "yathādoṣaṃ cālepasekādīnavirataṃ vidadhyāt evaṃ sadya eva ruktodaśopharāgasaṃrambhā nivartante" },
      { type: "verse", number: "4", sanskrit: "पक्वेषु तु तु शस्त्रमवचारयेत् सघृतक्षौद्रशर्करेण तिलकल्केनालेपयेत् अपि च", text: "pakveṣu tu tu śastramavacārayet saghṛtakṣaudraśarkareṇa tilakalkenālepayet api ca" },
      { type: "verse", number: "5", sanskrit: "जम्ब्वाम्रसुमनोनीपश्वेतकाम्बोजिकाङ्कुरान् सल्लकीबदरीबिल्वपलाशतिनिशोद्भवाः", text: "jambvāmrasumanonīpaśvetakāmbojikāṅkurān sallakībadarībilvapalāśatiniśodbhavāḥ" },
      { type: "verse", number: "6", sanskrit: "त्वचः क्षीरिद्रुमाणां च त्रिफलां च पचेज्जले स क्वाथः क्षालनं तेन पक्वं तैलं च रोपणम् गोजीविडङ्गमधुकसर्वगन्धैश्च पेषितैः", text: "tvacaḥ kṣīridrumāṇāṃ ca triphalāṃ ca pacejjale sa kvāthaḥ kṣālanaṃ tena pakvaṃ tailaṃ ca ropaṇam gojīviḍaṅgamadhukasarvagandhaiśca peṣitaiḥ" },
      { type: "verse", number: "7", sanskrit: "तुत्थगौरिकलोध्रैलामनोह्वालरसाञ्जनैः हरेणुपुष्पकासीससौराष्ट्रीलवणोत्तमैः लेपः क्षौद्रद्रुतैः सूक्ष्मैरुपदंशव्रणापहः", text: "tutthagaurikalodhrailāmanohvālarasāñjanaiḥ hareṇupuṣpakāsīsasaurāṣṭrīlavaṇottamaiḥ lepaḥ kṣaudradrutaiḥ sūkṣmairupadaṃśavraṇāpahaḥ" },
      { type: "verse", number: "8", sanskrit: "दार्वीत्वक्शङ्खतार्क्ष्योत्थलाक्षागोक्षीरविड्रसैः सक्षौद्रतैलसर्पिर्भिर्लेपः श्रेष्ठो व्रणे ऽथवा लाक्षाद्राक्षातसीक्षौद्रैः क्षौद्रशैलेयतार्क्ष्यजैः", text: "dārvītvakśaṅkhatārkṣyotthalākṣāgokṣīraviḍrasaiḥ sakṣaudratailasarpirbhirlepaḥ śreṣṭho vraṇe 'thavā lākṣādrākṣātasīkṣaudraiḥ kṣaudraśaileyatārkṣyajaiḥ" },
      { type: "verse", number: "9", sanskrit: "कपाले त्रिफलादग्धा सघृता रोपणी परम्", text: "kapāle triphalādagdhā saghṛtā ropaṇī param" },
      { type: "verse", number: "10", sanskrit: "सामान्यं साधनमिदं वातिकं तु प्रलेपयेत् अपक्वं कुष्ठयष्ट्याह्वसुरदारुपुनर्नवैः", text: "sāmānyaṃ sādhanamidaṃ vātikaṃ tu pralepayet apakvaṃ kuṣṭhayaṣṭyāhvasuradārupunarnavaiḥ" },
      { type: "verse", number: "11", sanskrit: "स्निग्धोष्णैर्लोहसरलरास्नापुण्ड्राह्वसंयुतैः अथवा निचुलैरण्डबीजगोधूमचिक्कसैः", text: "snigdhoṣṇairlohasaralarāsnāpuṇḍrāhvasaṃyutaiḥ athavā niculairaṇḍabījagodhūmacikkasaiḥ" },
      { type: "verse", number: "12", sanskrit: "गैरिकाञ्जनमञ्जिष्ठामधुकोशीरपद्मकैः सचन्दनोत्पलैः शीतैर्घृताढ्यैः पित्तसम्भवम्", text: "gairikāñjanamañjiṣṭhāmadhukośīrapadmakaiḥ sacandanotpalaiḥ śītairghṛtāḍhyaiḥ pittasambhavam" },
      { type: "verse", number: "13", sanskrit: "पद्मोत्पलमृणालैर्वा ससर्जार्जुनवेतसैः सेचयेच्च घृतक्षीरशर्करेक्षुमधूदकैः", text: "padmotpalamṛṇālairvā sasarjārjunavetasaiḥ secayecca ghṛtakṣīraśarkarekṣumadhūdakaiḥ" },
      { type: "verse", number: "14", sanskrit: "धवसालाश्वकर्णाजकर्णत्वग्भिः कफोत्थितम् सुरापिष्टाभिरुष्णाभिः सतैलाभिः प्रलेपयेत्", text: "dhavasālāśvakarṇājakarṇatvagbhiḥ kaphotthitam surāpiṣṭābhiruṣṇābhiḥ satailābhiḥ pralepayet" },
      { type: "verse", number: "15", sanskrit: "रजन्यतिविषामुस्तसरलामरदारुभिः सपत्रपाठापत्तूरैरथवा श्लेष्मसम्भवम्", text: "rajanyativiṣāmustasaralāmaradārubhiḥ sapatrapāṭhāpattūrairathavā śleṣmasambhavam" },
      { type: "verse", number: "16", sanskrit: "न च याति यथा पाकं प्रयतेत तथा भृशम् पक्वैः स्नायुसिरामांसैः प्रायो नश्यति हि ध्वजः", text: "na ca yāti yathā pākaṃ prayateta tathā bhṛśam pakvaiḥ snāyusirāmāṃsaiḥ prāyo naśyati hi dhvajaḥ" },
      { type: "verse", number: "17", sanskrit: "उपदंशद्वये शिष्टे प्रत्याख्यायाचरेत् क्रियाम्", text: "upadaṃśadvaye śiṣṭe pratyākhyāyācaret kriyām" },
      { type: "verse", number: "18", sanskrit: "अर्शांसि यथायोगं शुद्धदेहस्य शस्त्रक्षाराग्निभिः साधयेत् उपदंशोक्ता चात्र रसक्रिया लेपः", text: "arśāṃsi yathāyogaṃ śuddhadehasya śastrakṣārāgnibhiḥ sādhayet upadaṃśoktā cātra rasakriyā lepaḥ" },
      { type: "verse", number: "19", sanskrit: "सर्षपिकां विलिख्य कषायैरवचूर्णयेत् तैरेव च तैलं व्रणरोपणं कुर्यात्", text: "sarṣapikāṃ vilikhya kaṣāyairavacūrṇayet taireva ca tailaṃ vraṇaropaṇaṃ kuryāt" },
      { type: "verse", number: "20", sanskrit: "अवमन्थे जलौकसो योजयेत् पक्वभिन्नं धवतिन्दुकसल्लकीपतङ्गसर्जकृतेन तैलेन रोपयेत्", text: "avamanthe jalaukaso yojayet pakvabhinnaṃ dhavatindukasallakīpataṅgasarjakṛtena tailena ropayet" },
      { type: "verse", number: "21", sanskrit: "तद्वत् कुम्भीकामुपचरेत् लोध्रतिन्दुकत्रिफलाकृतस्तु लेपस्तैलं च रोपणम्", text: "tadvat kumbhīkāmupacaret lodhratindukatriphalākṛtastu lepastailaṃ ca ropaṇam" },
      { type: "verse", number: "22", sanskrit: "अलजीं स्रुतरक्तां कषायैरवचूर्णयेत् तेष्वेव च तैलं व्रणरोपणार्थं कुर्वीत", text: "alajīṃ srutaraktāṃ kaṣāyairavacūrṇayet teṣveva ca tailaṃ vraṇaropaṇārthaṃ kurvīta" },
      { type: "verse", number: "23", sanskrit: "उत्तमां पिटकां शस्त्रेण च्छित्वा कषायचूर्णप्रदेहैर्मधुमाद्भिरुपाचरेत्", text: "uttamāṃ piṭakāṃ śastreṇa cchitvā kaṣāyacūrṇapradehairmadhumādbhirupācaret" },
      { type: "verse", number: "24", sanskrit: "पुष्करिकासंव्यूढास्पर्शहानित्वक्पाकेषु पित्तविसर्पोक्तो विधिः", text: "puṣkarikāsaṃvyūḍhāsparśahānitvakpākeṣu pittavisarpokto vidhiḥ" },
      { type: "verse", number: "25", sanskrit: "मृदितं कोष्णेन बलातैलेन परिषेचयेत् मधुरद्रव्यकल्कैश्च सुखोष्णैर्घृतस्निग्धैरुपनाहयेत्", text: "mṛditaṃ koṣṇena balātailena pariṣecayet madhuradravyakalkaiśca sukhoṣṇairghṛtasnigdhairupanāhayet" },
      { type: "verse", number: "26", sanskrit: "अष्ठीलिकां जलौकोभिर्ग्राहयेत् तथानुपशमे श्लेष्मग्रन्थिमिव शस्त्रेणोद्धरेत्", text: "aṣṭhīlikāṃ jalaukobhirgrāhayet tathānupaśame śleṣmagranthimiva śastreṇoddharet" },
      { type: "verse", number: "27", sanskrit: "निवृत्तं सर्पिषाभ्यज्य स्वेदयेत् स्विन्नमुपनाहयेत्त्रिरात्रं पञ्चरात्रं वा साल्वलेन ततो भूयः स्वेदयित्वा घृतेनाभ्यज्य शनैः शनैश्चर्म समानयन् मणिमवपीडयेत् पीडयित्वा च पुनरुपनाहयेत् स्निग्धोष्णं चान्नपानम्", text: "nivṛttaṃ sarpiṣābhyajya svedayet svinnamupanāhayettrirātraṃ pañcarātraṃ vā sālvalena tato bhūyaḥ svedayitvā ghṛtenābhyajya śanaiḥ śanaiścarma samānayan maṇimavapīḍayet pīḍayitvā ca punarupanāhayet snigdhoṣṇaṃ cānnapānam" },
      { type: "verse", number: "28", sanskrit: "अवपाटिकायामप्ययं विधिः", text: "avapāṭikāyāmapyayaṃ vidhiḥ" },
      { type: "verse", number: "29", sanskrit: "निरुद्धमणौ सुवर्णादिकृतां दारुजां वा जतुसृतां नाडीमुभयतोद्वारां स्नेहाभ्यक्तां स्रोतसि प्रणिधाय सूकरशिंशुमारयोर्वसयामज्ज्ञा वा परिषेचयेत् चक्रतैलेन वा वातहरसिद्धेन वा त्रिवृतेन तृतीये तृतीये चाहनि नाडीं पीनतरां विदध्यात् एवमस्य स्रोतोद्वारं विवर्धयेत् स्निग्धं चाहारं भोजयेत् एवमनुपशान्तौ शस्त्रेण सेवनीं परिहृत्य दारयित्वा सद्यःक्षतवदुपाचरेत्", text: "niruddhamaṇau suvarṇādikṛtāṃ dārujāṃ vā jatusṛtāṃ nāḍīmubhayatodvārāṃ snehābhyaktāṃ srotasi praṇidhāya sūkaraśiṃśumārayorvasayāmajjñā vā pariṣecayet cakratailena vā vātaharasiddhena vā trivṛtena tṛtīye tṛtīye cāhani nāḍīṃ pīnatarāṃ vidadhyāt evamasya srotodvāraṃ vivardhayet snigdhaṃ cāhāraṃ bhojayet evamanupaśāntau śastreṇa sevanīṃ parihṛtya dārayitvā sadyaḥkṣatavadupācaret" },
      { type: "verse", number: "30", sanskrit: "ग्रथितं नाडीस्वेदेन स्वेदयित्वा स्निग्धोष्णैरुपनाहयेत् शतपोनकं लिखित्वा कषायचूर्णैः सक्षौद्रैर्लेपयेत् विदार्यादिसिद्धेन च तैलेन रोपयेत् शर्करार्बुदे रक्तविद्रधिवत् साधनम्", text: "grathitaṃ nāḍīsvedena svedayitvā snigdhoṣṇairupanāhayet śataponakaṃ likhitvā kaṣāyacūrṇaiḥ sakṣaudrairlepayet vidāryādisiddhena ca tailena ropayet śarkarārbude raktavidradhivat sādhanam" },
      { type: "verse", number: "31", sanskrit: "सर्वेषु च यथास्वमन्तःशुद्धिं कषायलेपघृततैलरसक्रियाचूर्णशोधनरोपणान् विदध्यात्", text: "sarveṣu ca yathāsvamantaḥśuddhiṃ kaṣāyalepaghṛtatailarasakriyācūrṇaśodhanaropaṇān vidadhyāt" },
      { type: "verse", number: "32", sanskrit: "योनिव्यापदि तु वातिक्यां लवणतैलाक्तां योनिं पिण्डनाडीकुम्भीप्रभृप्रभृतिभिः स्वेदयेत् ततः सुखोष्णाम्बुपरिषिक्तसर्वगात्रां जाङ्गलरसैर्भोजयेत्", text: "yonivyāpadi tu vātikyāṃ lavaṇatailāktāṃ yoniṃ piṇḍanāḍīkumbhīprabhṛprabhṛtibhiḥ svedayet tataḥ sukhoṣṇāmbupariṣiktasarvagātrāṃ jāṅgalarasairbhojayet" },
      { type: "verse", number: "33", sanskrit: "बलाद्रोणद्वयनिर्यूहे पयस्यासालपर्णीमागधिकाशतावरीकाकनासाश्रावणीशर्कराजीवनीयगर्भं क्षीरचतुर्गुणं घृततैलाढकं साधयेत् तत्पानात् सर्वान् वातपित्तविकारानपोहति गर्भजननं च", text: "balādroṇadvayaniryūhe payasyāsālaparṇīmāgadhikāśatāvarīkākanāsāśrāvaṇīśarkarājīvanīyagarbhaṃ kṣīracaturguṇaṃ ghṛtatailāḍhakaṃ sādhayet tatpānāt sarvān vātapittavikārānapohati garbhajananaṃ ca" },
      { type: "verse", number: "34", sanskrit: "शतावरीत्रिफलागुडूचीकाश्मर्यमृद्वीकाकासमर्दकपरूषकहरिद्राद्वयसहचरशुकनासापुनर्नवैः कार्षिकैर्घृतप्रस्थः सिद्धः पीतो वातजान् योनिरोगानपोहति गर्भजननश्च", text: "śatāvarītriphalāguḍūcīkāśmaryamṛdvīkākāsamardakaparūṣakaharidrādvayasahacaraśukanāsāpunarnavaiḥ kārṣikairghṛtaprasthaḥ siddhaḥ pīto vātajān yonirogānapohati garbhajananaśca" },
      { type: "verse", number: "35", sanskrit: "सैन्धववचोपकुञ्चिकापिप्पलीवृषकयवक्षाराजमोदाजाजीसितोपलाचित्रकचूर्णो मदिरालुलितः सर्पिषा संयावीकृत्य भक्षितो योनिपार्श्वबास्तिवेदनार्शोगुल्महृद्रोगहरः", text: "saindhavavacopakuñcikāpippalīvṛṣakayavakṣārājamodājājīsitopalācitrakacūrṇo madirālulitaḥ sarpiṣā saṃyāvīkṛtya bhakṣito yonipārśvabāstivedanārśogulmahṛdrogaharaḥ" },
      { type: "verse", number: "36", sanskrit: "शूले वृषकरास्नागोक्षुरकशृतं पयः पिबेत् वृषकमातुलुङ्गमूलमदयन्तिकासैन्धवपिप्पलीकृष्णजीरककल्कं वा मद्येन तेनैवचार्जकमूलं बिल्वयुक्तं वा पिप्पली युक्तं वा सौवर्चलोपकुञ्चिकापिप्पलीर्वा मद्येनावन्तिसोमेन वा", text: "śūle vṛṣakarāsnāgokṣurakaśṛtaṃ payaḥ pibet vṛṣakamātuluṅgamūlamadayantikāsaindhavapippalīkṛṣṇajīrakakalkaṃ vā madyena tenaivacārjakamūlaṃ bilvayuktaṃ vā pippalī yuktaṃ vā sauvarcalopakuñcikāpippalīrvā madyenāvantisomena vā" },
      { type: "verse", number: "37", sanskrit: "दन्तीत्रिफलगुडूचीक्वाथः सुखोष्णो योनेः परिषेकः", text: "dantītriphalaguḍūcīkvāthaḥ sukhoṣṇo yoneḥ pariṣekaḥ" },
      { type: "verse", number: "38", sanskrit: "कुष्ठतगरदेवदारुवार्ताकिनीसैन्धवैः साधितं तैलं पिचुना धारयेत्", text: "kuṣṭhatagaradevadāruvārtākinīsaindhavaiḥ sādhitaṃ tailaṃ picunā dhārayet" },
      { type: "verse", number: "39", sanskrit: "रास्नामालतीच्छिन्नरुहामधुकबलाव्याघ्रीदेवदारुचित्रकयूथिकामूलैः कर्षांशैस्तैलप्रस्थः समूत्रो द्विगुणपयसा विपक्वः पिचुना प्रणीतो ऽनिलार्तिहरः", text: "rāsnāmālatīcchinnaruhāmadhukabalāvyāghrīdevadārucitrakayūthikāmūlaiḥ karṣāṃśaistailaprasthaḥ samūtro dviguṇapayasā vipakvaḥ picunā praṇīto 'nilārtiharaḥ" },
      { type: "verse", number: "40", sanskrit: "बस्तिकर्म चाभीष्णं स्वेदं च प्रयोजयेद्विशेषतो वातहरैः सुकुमारबलातैलशिरीषतैलैः शतपाकसहस्र पाकैश्चानुवासनमुत्तरबस्तिं च एष क्रमो विशेषेण योनेर्वेदनाकार्कश्यस्तम्भस्रंसस्पर्शाहानिघ्नश्च", text: "bastikarma cābhīṣṇaṃ svedaṃ ca prayojayedviśeṣato vātaharaiḥ sukumārabalātailaśirīṣatailaiḥ śatapākasahasra pākaiścānuvāsanamuttarabastiṃ ca eṣa kramo viśeṣeṇa yonervedanākārkaśyastambhasraṃsasparśāhānighnaśca" },
      { type: "verse", number: "41", sanskrit: "अतिचरणादिषु सर्वास्वनिलजास्वयमेव क्रमः", text: "aticaraṇādiṣu sarvāsvanilajāsvayameva kramaḥ" },
      { type: "verse", number: "42", sanskrit: "धारयेच्चातिचरणाय यवगोधूमकिण्वकुष्ठशतपुष्पाश्र्याह्वीप्रयड्गुबलाखुकर्णीकल्ककृतामुत्कारिकाम्", text: "dhārayeccāticaraṇāya yavagodhūmakiṇvakuṣṭhaśatapuṣpāśryāhvīprayaḍgubalākhukarṇīkalkakṛtāmutkārikām" },
      { type: "verse", number: "43", sanskrit: "प्राक्चरणाशुष्काविप्लुताकर्णिनीषुतैलमुत्तरबस्तिं दद्यात्", text: "prākcaraṇāśuṣkāviplutākarṇinīṣutailamuttarabastiṃ dadyāt" },
      { type: "verse", number: "44", sanskrit: "धारयेच्च विप्लुतायां गोमत्स्यान्यतरपित्तेनैकविंशतिकृत्वो भावितान् क्षौमनक्तकान् किण्वं वा माक्षिकयुक्तमेवमस्याः स्रोतांसि विशुध्यन्ति कण्डूक्लेदशोफाश्च निवर्तन्ते", text: "dhārayecca viplutāyāṃ gomatsyānyatarapittenaikaviṃśatikṛtvo bhāvitān kṣaumanaktakān kiṇvaṃ vā mākṣikayuktamevamasyāḥ srotāṃsi viśudhyanti kaṇḍūkledaśophāśca nivartante" },
      { type: "verse", number: "45", sanskrit: "कर्णिन्यां तु कुष्ठार्कपल्लवपिप्पलीसैन्धवैर्बस्तमूत्रपिष्टैर्वर्तिं कृत्वा धारयेत् श्लेष्महरं च सर्वं कुर्यात्", text: "karṇinyāṃ tu kuṣṭhārkapallavapippalīsaindhavairbastamūtrapiṣṭairvartiṃ kṛtvā dhārayet śleṣmaharaṃ ca sarvaṃ kuryāt" },
      { type: "verse", number: "46", sanskrit: "उदावृत्तायामानूपमांसरसाः क्षीरं स्वेदो दशमूलत्रिवृताक्वाथकल्कासिद्धश्च स्नेहः पानानुवासनोत्तरबस्तिषु योनिस्रंसे च महायोनिप्रभृतिष्वेष एव विधिः", text: "udāvṛttāyāmānūpamāṃsarasāḥ kṣīraṃ svedo daśamūlatrivṛtākvāthakalkāsiddhaśca snehaḥ pānānuvāsanottarabastiṣu yonisraṃse ca mahāyoniprabhṛtiṣveṣa eva vidhiḥ" },
      { type: "verse", number: "47", sanskrit: "जातघ्नीरक्तयोनिरक्तक्षयासु कुटजकाश्मर्यक्वाथसिद्धं सर्पिरुत्तरबस्तौ दद्यात् अथवा मृगाजाविवराहरुधिराम्लदधिमधुघृतानीति भवति चात्र", text: "jātaghnīraktayoniraktakṣayāsu kuṭAjakāśmaryakvāthasiddhaṃ sarpiruttarabastau dadyāt athavā mṛgājāvivarāharudhirāmladadhimadhughṛtānīti bhavati cātra" },
      { type: "verse", number: "48", sanskrit: "स्नेहन स्वेदबस्त्यादि वातलास्वनिलापहम् कारयेद्रक्तपित्तघ्नं शीतं पित्तकृतासु च", text: "snehana svedabastyādi vātalāsvanilāpaham kārayedraktapittaghnaṃ śītaṃ pittakṛtāsu ca" },
      { type: "verse", number: "49", sanskrit: "श्लेष्मलासु च रूक्षोष्णं कर्म कुर्याद्यथायथम् सन्निपाते विमिश्रं तु संसृष्टासु च कारयेत्", text: "śleṣmalāsu ca rūkṣoṣṇaṃ karma kuryādyathāyatham sannipāte vimiśraṃ tu saṃsṛṣṭāsu ca kārayet" },
      { type: "verse", number: "50", sanskrit: "स्निग्धस्विन्नां तथा योनिं दुःस्थितां स्थापयेत् समाम् पाणिना नमयेत् जिह्मां संवृतां प्रथयेत् पुनः", text: "snigdhasvinnāṃ tathā yoniṃ duḥsthitāṃ sthāpayet samām pāṇinā namayet jihmāṃ saṃvṛtāṃ prathayet punaḥ" },
      { type: "verse", number: "51", sanskrit: "प्रवेशयेन्निस्सृतां च विवृतां परिवर्तयेत् स्थानापवृत्ता योनिर्हि शल्यभूता स्त्रिया मता", text: "praveśayennissṛtāṃ ca vivṛtāṃ parivartayet sthānāpavṛttā yonirhi śalyabhūtā striyā matā" },
      { type: "verse", number: "52", sanskrit: "सर्वां व्यापन्नयोनिं च कर्मभिर्वमनादिभिः मृदुभिः पञ्चभिर्नारीं स्निग्धस्विन्नामुपाचरेत्", text: "sarvāṃ vyāpannayoniṃ ca karmabhirvamanādibhiḥ mṛdubhiḥ pañcabhirnārīṃ snigdhasvinnāmupācaret" },
      { type: "verse", number: "53", sanskrit: "सर्वतः सुविशुद्धायाः शेषं कर्म विधीयते बस्त्यभ्यङ्गपरीषेकप्रलेपपिचुधारणम्", text: "sarvataḥ suviśuddhāyāḥ śeṣaṃ karma vidhīyate bastyabhyaṅgaparīṣekapralepapicudhāraṇam" },
      { type: "verse", number: "54", sanskrit: "हिंस्राकल्कं समीरार्तौ कोष्णमभ्यज्य धारयेत् पञ्चवल्कस्य पित्तार्तौ श्यामादीनां कफातुरा", text: "hiṃsrākalkaṃ samīrārtau koṣṇamabhyajya dhārayet pañcavalkasya pittārtau śyāmādīnāṃ kaphāturā" },
      { type: "verse", number: "55", sanskrit: "वामिन्याप्लुतयोश्चैव स्वेदयित्वा प्रयोजयेत् तर्पणं स्नेहपिचुभिर्भोजनं चानिलापहम्", text: "vāminyāplutayoścaiva svedayitvā prayojayet tarpaṇaṃ snehapicubhirbhojanaṃ cānilāpaham" },
      { type: "verse", number: "56", sanskrit: "सल्लकीजिङ्गिणीजम्बूधवत्वक्पञ्चवल्कलैः कषायैः साधितात् स्नेहात् पर्युपप्लुतयोः पिचुम्", text: "sallakījiṅgiṇījambūdhavatvakpañcavalkalaiḥ kaṣāyaiḥ sādhitāt snehāt paryupaplutayoḥ picum" },
      { type: "verse", number: "57", sanskrit: "कुलीरसूकरवसा सर्पिर्भिर्मधुरैः शृतैः पूरयित्वा महायोनिं बध्नीयात् क्षौमनक्तकैः", text: "kulīrasūkaravasā sarpirbhirmadhuraiḥ śṛtaiḥ pūrayitvā mahāyoniṃ badhnīyāt kṣaumanaktakaiḥ" },
      { type: "verse", number: "58", sanskrit: "प्रस्रस्तां सर्पिषाभ्यज्य क्षीरस्विन्नां प्रवेशयेत् बध्नीयाद्वेशवारस्य पिण्डेनामूत्रकालतः", text: "prasrastāṃ sarpiṣābhyajya kṣīrasvinnāṃ praveśayet badhnīyādveśavārasya piṇḍenāmūtrakālataḥ" },
      { type: "verse", number: "59", sanskrit: "यच्च वातविकाराणां कर्मोक्तं तच्च कारयेत् सर्वव्यापत्सु मतिमान्महायोन्यां विशेषतः", text: "yacca vātavikārāṇāṃ karmoktaṃ tacca kārayet sarvavyāpatsu matimānmahāyonyāṃ viśeṣataḥ" },
      { type: "verse", number: "60", sanskrit: "नहि वातादृते योनिर्वनितानां प्रदुष्यति अतो जित्वा तमन्यस्य कुर्याद्दोषस्य भेषजम्", text: "nahi vātādṛte yonirvanitānāṃ praduṣyati ato jitvā tamanyasya kuryāddoṣasya bheṣajam" },
      { type: "verse", number: "61", sanskrit: "पित्तलानां तु योनीनां सेकाभ्यङ्गपिचुक्रियाः शीताः पित्तजितः कार्याः स्नेहनार्थं घृतानि च", text: "pittalānāṃ tu yonīnāṃ sekābhyaṅgapicukriyāḥ śītāḥ pittajitaḥ kāryāḥ snehanārthaṃ ghṛtāni ca" },
      { type: "verse", number: "62", sanskrit: "शतावरीमूलतुलाचतुष्कात् क्षुण्णपीडितात् रसेन क्षीरतुल्येन पाचयेत घृताढकम्", text: "śatāvarīmūlatulācatuṣkāt kṣuṇṇapīḍitāt rasena kṣīratulyena pācayeta ghṛtāḍhakam" },
      { type: "verse", number: "63", sanskrit: "जीवनीयैः शतावर्या मृद्वीकाभिः परूषकैः पिष्टैः प्रियालैश्चाक्षांशैर्मधुकार्द्धपलान्वितैः", text: "jīvanīyaiḥ śatāvaryā mṛdvīkābhiḥ parūṣakaiḥ piṣṭaiḥ priyālaiścākṣāṃśairmadhukārddhapalānvitaiḥ" },
      { type: "verse", number: "64", sanskrit: "सिद्धशीते तु मधुनः पिप्पल्याश्च पलाष्टकम् शर्कराया दशपलं क्षिपेल्लिह्यात् पिचुं ततः", text: "siddhaśīte tu madhunaḥ pippalyāśca palāṣṭakam śarkarāyā daśapalaṃ kṣipellihyāt picuṃ tataḥ" },
      { type: "verse", number: "65", sanskrit: "योन्यसृक्शुक्रदोषघ्नं वृष्यं पुंसवनं परम् क्षतं क्षयमसृक्पित्तं कासं श्वासं हलीमकम्", text: "yonyasṛkśukradoṣaghnaṃ vṛṣyaṃ puṃsavanaṃ param kṣataṃ kṣayamasṛkpittaṃ kāsaṃ śvāsaṃ halīmakam" },
      { type: "verse", number: "66", sanskrit: "कामिलां वातरुधिरं विसर्पं हृच्छिरोग्रहम् अपस्मारार्दितायाममदोन्मादांश्च नाशयेत्", text: "kāmilāṃ vātarudhiraṃ visarpaṃ hṛcchirograham apasmārārditāyāmamadonmādāṃśca nāśayet" },
      { type: "verse", number: "67", sanskrit: "एवमेव पयस्सर्पिर्जीवनीयोपसाधितम् गर्भदं पित्तजानां च रोगाणां परमं हितम्", text: "evameva payassarpirjīvanīyopasādhitam garbhadaṃ pittajānāṃ ca rogāṇāṃ paramaṃ hitam" },
      { type: "verse", number: "68", sanskrit: "रक्तयोन्यामसृग्वर्णैरनुबन्धमवेक्ष्य च यथादोषोदयं युञ्ज्याद्रक्तस्थापनमौषधम्", text: "raktayonyāmasṛgvarṇairanubandhamavekṣya ca yathādoṣodayaṃ yuñjyādraktasthāpanamauṣadham" },
      { type: "verse", number: "69", sanskrit: "तिलचूर्णं दधि घृतं फाणितं सौकरी वसा क्षौद्रयुक्तं जयेत् पीतं वातोत्तरमसृग्दरम्", text: "tilacūrṇaṃ dadhi ghṛtaṃ phāṇitaṃ saukarī vasā kṣaudrayuktaṃ jayet pītaṃ vātottaramasṛgdaram" },
      { type: "verse", number: "70", sanskrit: "वराहस्य रसो मेध्यः सकौलत्थश्च तद्गुणः पत्रकल्को घृते भृष्टो राजादनकपित्थयोः शर्कराक्षौद्रयष्ट्याह्वनागरैश्च युतं दधि", text: "varāhasya raso medhyaḥ sakaulatthaśca tadguṇaḥ patrakalko ghṛte bhṛṣṭo rājādanakapitthayoḥ śarkarākṣaudrayaṣṭyāhvanāgaraiśca yutaṃ dadhi" },
      { type: "verse", number: "71", sanskrit: "पयस्योत्पलशालूकबिसकालीयवारिजम् सपयश्शर्कराक्षौद्रं रक्ते पित्तोत्तरे पिबेत्", text: "payasyotpalaśālūkabisakālīyavārijam sapayaśśarkarākṣaudraṃ rakte pittottare pibet" },
      { type: "verse", number: "72", sanskrit: "तण्डुलीयकमूलं वा सक्षौद्रं तण्डुलाम्भसा सतार्क्ष्यशैलं लाक्षां वा छागेन पयसा पिबेत् वासाघृतं महातिक्तं रक्तपित्तहितञ्च यत्", text: "taṇḍulīyakamūlaṃ vā sakṣaudraṃ taṇḍulāmbhasā satārkṣyaśailaṃ lākṣāṃ vā chāgena payasā pibet vāsāghṛtaṃ mahātiktaṃ raktapittahitañca yat" },
      { type: "verse", number: "73", sanskrit: "मधुकं त्रिफलां लोध्रं मुस्तं सौराष्ट्रिकां मधु मद्यैर्निमगुडूच्यौ च कफजे ऽसृग्दरे पिबेत्", text: "madhukaṃ triphalāṃ lodhraṃ mustaṃ saurāṣṭrikāṃ madhu madyairnimaguḍūcyau ca kaphaje 'sṛgdare pibet" },
      { type: "verse", number: "74", sanskrit: "पाठां जम्ब्वाम्रयोरस्थि शिलोद्भेदं रसाञ्जनम् अम्बष्ठां शाल्मलीपिच्छां समङ्गां वत्सकत्वचम्", text: "pāṭhāṃ jambvāmrayorasthi śilodbhedaṃ rasāñjanam ambaṣṭhāṃ śālmalīpicchāṃ samaṅgāṃ vatsakatvacam" },
      { type: "verse", number: "75", sanskrit: "बाल्हीकबिल्वातिविषालोध्रतोयदगैरिकम् शुण्ठीमधूकमाचीकरक्तचन्दनकट्फलम्", text: "bālhīkabilvātiviṣālodhratoyadagairikam śuṇṭhīmadhūkamācīkaraktacandanakaṭphalam" },
      { type: "verse", number: "76", sanskrit: "कट्वङ्गवत्सकानन्ताधातकीमधुकार्जुनम् पुष्ये गृहीत्वा सञ्चूर्ण्य सक्षौद्रं तण्डुलाम्बुना", text: "kaṭvaṅgavatsakānantādhātakīmadhukārjunam puṣye gṛhītvā sañcūrṇya sakṣaudraṃ taṇḍulāmbunā" },
      { type: "verse", number: "77", sanskrit: "पिबेदर्शस्वतीसारे रक्तं यच्चोपवेश्यते दोषा जन्तुकृता ये च बालानां तांश्च नाशयेत्", text: "pibedarśasvatīsāre raktaṃ yaccopaveśyate doṣā jantukṛtā ye ca bālānāṃ tāṃśca nāśayet" },
      { type: "verse", number: "78", sanskrit: "योनिदोषं रजोदोषं श्यावश्वेतारुणासितम् चूर्णं पुष्यानुगं नाम हितमात्रेयपूजितम्", text: "yonidoṣaṃ rajodoṣaṃ śyāvaśvetāruṇāsitam cūrṇaṃ puṣyānugaṃ nāma hitamātreyapūjitam" },
      { type: "verse", number: "79", sanskrit: "सर्वेषु गर्भस्रावोक्तं प्रदरेषु प्रशस्यते", text: "sarveṣu garbhasrāvoktaṃ pradareṣu praśasyate" },
      { type: "verse", number: "80", sanskrit: "रक्तक्षयायां क्षीरं च जीवनीयशृतं पिबेत्", text: "raktakṣayāyāṃ kṣīraṃ ca jīvanīyaśṛtaṃ pibet" },
      { type: "verse", number: "81", sanskrit: "योन्यां बलासदुष्टायां वर्तिः संशोधने हिता वाराहे बहुशः पित्ते भावितैर्नक्तकैः कृता", text: "yonyāṃ balāsaduṣṭāyāṃ vartiḥ saṃśodhane hitā vārāhe bahuśaḥ pitte bhāvitairnaktakaiḥ kṛtā" },
      { type: "verse", number: "82", sanskrit: "भावितं पयसार्कस्य माषचूर्णं ससैन्धवम् वर्तिः कृता क्षणं धार्या सेक्तव्यानुसुखाम्बुना", text: "bhāvitaṃ payasārkasya māṣacūrṇaṃ sasaindhavam vartiḥ kṛtā kṣaṇaṃ dhāryā sektavyānusukhāmbunā" },
      { type: "verse", number: "83", sanskrit: "पिप्पलीमाषमरिचशताह्वाकुष्ठसैन्धवैः प्रदेशिन्यङ्गुलीतुल्या वर्तिर्योनिविशोधनी", text: "pippalīmāṣamaricaśatāhvākuṣṭhasaindhavaiḥ pradeśinyaṅgulītulyā vartiryoniviśodhanī" },
      { type: "verse", number: "84", sanskrit: "उदुम्बरशलाटूनां द्रोणं द्रोणेम्भसः पचेत् सपञ्चवल्कतिलकमालतीनिम्बपल्लवे", text: "udumbaraśalāṭūnāṃ droṇaṃ droṇembhasaḥ pacet sapañcavalkatilakamālatīnimbapallave" },
      { type: "verse", number: "85", sanskrit: "निशास्थिते जले तस्मिंस्तैलप्रस्थं विपाचयेत् पलाशशाल्मलीलाक्षाधवनिर्यासवल्कलैः", text: "niśāsthite jale tasmiṃstailaprasthaṃ vipācayet palāśaśālmalīlākṣādhavaniryāsavalkalaiḥ" },
      { type: "verse", number: "86", sanskrit: "पिष्टैर्युक्तं ततःस्नेहपिचुं योनौ निधापयेत् सशक्ररैः कषायैश्च शीतैः कुर्वीत सेचनम्", text: "piṣṭairyuktaṃ tataḥsnehapicuṃ yonau nidhāpayet saśakraraiḥ kaṣāyaiśca śītaiḥ kurvīta secanam" },
      { type: "verse", number: "87", sanskrit: "पिच्छिला विवृता योनिश्चिरदुष्टा तु दारुणा सप्ताहाच्छुध्यति क्षिप्रमपत्यं च समश्नुते", text: "picchilā vivṛtā yoniściraduṣṭā tu dāruṇā saptāhācchudhyati kṣipramapatyaṃ ca samaśnute" },
      { type: "verse", number: "88", sanskrit: "उदुम्बरस्य दुग्धेन षट्कृत्वो भावितात्तिलात् तैलं क्वाथेन तस्यैव कार्यं धार्यं च पूर्ववत्", text: "udumbarasya dugdhena ṣaṭkṛtvo bhāvitāttilāt tailaṃ kvāthena tasyaiva kāryaṃ dhāryaṃ ca pūrvavat" },
      { type: "verse", number: "89", sanskrit: "धातक्यामलकीपत्रस्रोतोजमधुकोत्पलैः जम्ब्वाम्रसारकासीसलोध्रकट्फलतिन्दुकैः", text: "dhātakyāmalakīpatrasrotojamadhukotpalaiḥ jambvāmrasārakāsīsalodhrakaṭphalatindukaiḥ" },
      { type: "verse", number: "90", sanskrit: "सौराष्ट्रिकादाडिमत्वगुदुम्बरशलाटुभिः अक्षमात्रैरजामूत्रे क्षीरे च द्विगुणे पचेत्", text: "saurāṣṭrikādāḍimatvagudumbaraśalāṭubhiḥ akṣamātrairajāmūtre kṣīre ca dviguṇe pacet" },
      { type: "verse", number: "91", sanskrit: "तैलप्रस्थं तदभ्यङ्गपिचुबस्तिषु योजयेत् शूनोत्तानोन्नता स्तब्धा पिच्छिला स्राविणी तथा विप्लुतोपप्लुता योनिः सिध्येत् सस्फोटशूलिनी", text: "tailaprasthaṃ tadabhyaṅgapicubastiṣu yojayet śūnottānonnatā stabdhā picchilā srāviṇī tathā viplutopaplutā yoniḥ sidhyet sasphoṭaśūlinī" },
      { type: "verse", number: "92", sanskrit: "अर्कनिम्बाम्रकोशाम्रबिल्वबूकधवोद्बवैः करीरजिङ्गिणीनम्बूकरञ्जार्जुनशिग्रुजैः", text: "arkanimbāmrakośāmrabilvabūkadhavodbavaiḥ karīrajiṅgiṇīnambūkarañjārjunaśigrujaiḥ" },
      { type: "verse", number: "93", sanskrit: "पलाशसिध्रकोत्थैश्च कषायैर्धावनं परम् शुक्तसीधुमधून्मिश्रैर्योनेः स्रावनिवारणम्", text: "palāśasidhrakotthaiśca kaṣāyairdhāvanaṃ param śuktasīdhumadhūnmiśrairyoneḥ srāvanivāraṇam" },
      { type: "verse", number: "94", sanskrit: "कुर्यात् सतक्रगोमूत्रशुक्तैर्वा त्रिफलारसैः", text: "kuryāt satakragomūtraśuktairvā triphalārasaiḥ" },
      { type: "verse", number: "95", sanskrit: "यवान्नमभयारिष्टं सीधु तैलं च शीलयेत् पिप्पल्ययोरजःपथ्याप्रयोगांश्चसमाक्षिकान्", text: "yavānnamabhayāriṣṭaṃ sīdhu tailaṃ ca śīlayet pippalyayorajaḥpathyāprayogāṃścasamākṣikān" },
      { type: "verse", number: "96", sanskrit: "रोहीतकजटाकल्कं पाण्डुरे ऽसृग्दरे पिबेत् धात्रीमज्ज्ञोथवा कल्कं सितामाक्षिकसंयुतम्", text: "rohītakajaṭākalkaṃ pāṇḍure 'sṛgdare pibet dhātrīmajjñothavā kalkaṃ sitāmākṣikasaṃyutam" },
      { type: "verse", number: "97", sanskrit: "मधुनामलकीचूर्णं रसं वा प्राशयेत् सिते सलोध्रवल्केन वटत्वक्कषायेण धावयेत्", text: "madhunāmalakīcūrṇaṃ rasaṃ vā prāśayet site salodhravalkena vaṭatvakkaṣāyeṇa dhāvayet" },
      { type: "verse", number: "98", sanskrit: "आस्रावे क्षौमपट्टान् वा भावितांस्तेन धारयेत् प्लक्षत्वक्चूर्णपिण्डं वा धारयेन्मधुना कृतम्", text: "āsrāve kṣaumapaṭṭān vā bhāvitāṃstena dhārayet plakṣatvakcūrṇapiṇḍaṃ vā dhārayenmadhunā kṛtam" },
      { type: "verse", number: "99", sanskrit: "योन्या स्नेहाक्तया लोध्रप्रियङ्गुमधुकस्य वा धार्या मधुकृता वर्तिः कषायाणां च भूरिशः", text: "yonyā snehāktayā lodhrapriyaṅgumadhukasya vā dhāryā madhukṛtā vartiḥ kaṣāyāṇāṃ ca bhūriśaḥ" },
      { type: "verse", number: "100", sanskrit: "स्रावच्छेदार्थमभ्यक्तां धूपयेद्वा धृताप्लुतैः सरलागुग्गुलुयवैः सतैलैः कटुमत्स्यकैः", text: "srāvacchedārthamabhyaktāṃ dhūpayedvā dhṛtāplutaiḥ saralāgugguluyavaiḥ satailaiḥ kaṭumatsyakaiḥ" },
      { type: "verse", number: "101", sanskrit: "कासीसं त्रिफला काङ्क्षी साम्रजम्ब्वस्थि घातकी पैच्छिल्ये क्षौद्रसंयुक्तश्चूर्णो वैशद्यकारकः", text: "kāsīsaṃ triphalā kāṅkṣī sāmrajambvasthi ghātakī paicchilye kṣaudrasaṃyuktaścūrṇo vaiśadyakārakaḥ" },
      { type: "verse", number: "102", sanskrit: "पलाशधातकीजम्बूसमङ्गामोचसर्जजः दुर्गन्धे पिच्छिले क्लेदे स्तम्भनश्चूर्ण इष्यते आरग्वधादिवर्गस्य कषायः परिषेचनम्", text: "palāśadhātakījambūsamaṅgāmocasarjajaḥ durgandhe picchile klede stambhanaścūrṇa iṣyate āragvadhādivargasya kaṣāyaḥ pariṣecanam" },
      { type: "verse", number: "103", sanskrit: "स्तब्धानां कर्कशानां च कार्यं मादर्वकारकम् धारणं वेशवारस्य कृसरा पायसस्य वा", text: "stabdhānāṃ karkaśānāṃ ca kāryaṃ mādarvakārakam dhāraṇaṃ veśavārasya kṛsarā pāyasasya vā" },
      { type: "verse", number: "104", sanskrit: "दुर्गन्धानां कषायः स्यात्तैलं वा कल्क एव वा चूर्णो वा सर्वगन्धानां पूतिगन्धापकर्षणः", text: "durgandhānāṃ kaṣāyaḥ syāttailaṃ vā kalka eva vā cūrṇo vā sarvagandhānāṃ pūtigandhāpakarṣaṇaḥ" },
      { type: "verse", number: "105", sanskrit: "श्लेष्मलानां कटुप्रायाः समूत्रा बस्तयो हिताः पित्ते समधुकक्षीरा वाते तैलाम्लसंयुताः सन्निपातसमुत्थायाः कर्म साधारणं हितम्", text: "śleṣmalānāṃ kaṭuprāyāḥ samūtrā bastayo hitāḥ pitte samadhukakṣīrā vāte tailāmlasaṃyutāḥ sannipātasamutthāyāḥ karma sādhāraṇaṃ hitam" },
      { type: "verse", number: "106", sanskrit: "एवं योनिषु शुद्धासु गर्भं विन्दन्ति योषितः अदुष्टे प्राकृते बीजे बीजोपक्रमणे सति", text: "evaṃ yoniṣu śuddhāsu garbhaṃ vindanti yoṣitaḥ aduṣṭe prākṛte bīje bījopakramaṇe sati" },
      { type: "verse", number: "107", sanskrit: "पञ्चकर्मविशुद्धस्य पुरुषस्यापि चेन्द्रियम् परीक्ष्य वर्णैर्दोषाणां दुष्टं तद्घ्नैरुपाचरेत्", text: "pañcakarmaviśuddhasya puruṣasyāpi cendriyam parīkṣya varṇairdoṣāṇāṃ duṣṭaṃ tadghnairupācaret" },
      { type: "verse", number: "108", sanskrit: "मञ्जिष्ठाकुष्ठतगरत्रिफलाशर्करावचाः द्वे निशे मधुकं मेदा दीप्यकः कटुरोहिणी", text: "mañjiṣṭhākuṣṭhatagaratriphalāśarkarāvacāḥ dve niśe madhukaṃ medā dīpyakaḥ kaṭurohiṇī" },
      { type: "verse", number: "109", sanskrit: "पयस्या हिङ्गुकाकोली वाजिगन्धा शतावरी पिष्ट्वाक्षांशं घृतप्रस्थं पचेत् क्षीरचतुर्गुणम्", text: "payasyā hiṅgukākolī vājigandhā śatāvarī piṣṭvākṣāṃśaṃ ghṛtaprasthaṃ pacet kṣīracaturguṇam" },
      { type: "verse", number: "110", sanskrit: "योनिशुक्रप्रदोषेषु तत्सर्वेषु प्रशस्यते आयुष्यं पौष्टिकं मेध्यं धन्यं पुंसवनं परम्", text: "yoniśukrapradoṣeṣu tatsarveṣu praśasyate āyuṣyaṃ pauṣṭikaṃ medhyaṃ dhanyaṃ puṃsavanaṃ param" },
      { type: "verse", number: "111", sanskrit: "फलसर्पिरिति ख्यातं पुष्पे पीतं फलाय यत् म्रियमाणप्रजानां च गर्भिणीनां च पूजितम् एतत्परं च बालानां ग्रहघ्नं देहवर्द्धनम्", text: "phalasarpiriti khyātaṃ puṣpe pītaṃ phalāya yat mriyamāṇaprajānāṃ ca garbhiṇīnāṃ ca pūjitam etatparaṃ ca bālānāṃ grahaghnaṃ dehavarddhanam" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 40,
    lang: "sa",
    content: [
      { type: "heading", heading: "Кутипрашика — расаяна в изоляции" },
      { type: "text", text: "Глава 40 Уттара стханы — «Кутипрашика» — посвящена специализированному разделу: расаяна в изоляции. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो विषप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto viṣapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "पुरा खल्वमृतार्थं सुरासुरैः सलिलनिधेर्विमथ्यमानात् क्रोध इव रूपवान् सत्वं समुद्वभूव कृष्णमनलनयनमूर्ध्वप्रदीप्तकेशं दंष्ट्राकरालं भैरवारावरूपम् तद्दर्शनादेव यतो देवदानवाश्च विषण्णास्तस्मात्तद्विषसंज्ञामवाप", text: "purā khalvamṛtārthaṃ surāsuraiḥ salilanidhervimathyamānāt krodha iva rūpavān satvaṃ samudvabhūva kṛṣṇamanalanayanamūrdhvapradīptakeśaṃ daṃṣṭrākarālaṃ bhairavārāvarūpam taddarśanādeva yato devadānavāśca viṣaṇṇāstasmāttadviṣasaṃjñāmavāpa" },
      { type: "verse", number: "3", sanskrit: "तत् सहसैव सर्वभूतानि निर्दग्धुकाममुपयोगविशेषैर्विषममृततां विनयमानो ब्रह्मानुनीयौषधिषु न्यस्तवान्", text: "tat sahasaiva sarvabhūtāni nirdagdhukāmamupayogaviśeṣairviṣamamṛtatāṃ vinayamāno brahmānunīyauṣadhiṣu nyastavān" },
      { type: "verse", number: "4", sanskrit: "ततस्तत् स्थावरासु मूर्तिष्वधिवसनात् स्थावरमित्युच्यते", text: "tatastat sthāvarāsu mūrtiṣvadhivasanāt sthāvaramityucyate" },
      { type: "verse", number: "5", sanskrit: "जङ्गमं पुनः पृथिव्या भारावतारार्थमुरगादिरूपेण विष्णुर्निर्ममे", text: "jaṅgamaṃ punaḥ pṛthivyā bhārāvatārārthamuragādirūpeṇa viṣṇurnirmame" },
      { type: "verse", number: "6", sanskrit: "तयोः स्थावरं मूलपत्रपुष्पफलत्वक्सारनिर्यासक्षीरधातुकन्दभेदाद्दशाधिष्ठानम्", text: "tayoḥ sthāvaraṃ mūlapatrapuṣpaphalatvaksāraniryāsakṣīradhātukandabhedāddaśādhiṣṭhānam" },
      { type: "verse", number: "7", sanskrit: "तत्र मूलविषाणि क्लीतनकाश्वमारकगुञ्जासुगन्धकगर्गककर्करकरघाटकादीनि पत्रविषं कालपत्रिका लम्बा वरदकरम्भार्कादीनाम् पुष्पविषं वल्लीरेणुककरम्भ महाकरम्भादीनाम् फलं कुमुद्वतीरेणुकाकरम्भमहाकरम्भमदनकतुवरकादीनाम् त्वक्सारनिर्यासाः करककरघाटककरम्भमहाकरम्भनाराचकादीनाम् क्षीरं कुमुद्वती दन्ती स्नुह्यर्कजालिनी व्यालादीनाम् धातवो हरितालफेनाश्मभस्मरक्तप्रभृतयः कन्दजानि तु हालाहलकालकूटवत्सनाभशृङ्गीसाषर्पजालककर्दमकवैराटकमुस्तकमुष्ककसाक्तुकक्रौञ्चकवालकमहाविषपुण्डरीकगालवमूलकमर्कटकर्कटककरवीरकेन्द्रायुधसङ्कोचकलाङ्गलकतैलपेय कुशपुष्पके तु पुष्पकरोहिषाञ्जनाभकादीनि", text: "tatra mūlaviṣāṇi klītanakāśvamārakaguñjāsugandhakagargakakarkarakaraghāṭakādīni patraviṣaṃ kālapatrikā lambā varadakarambhārkādīnām puṣpaviṣaṃ vallīreṇukakarambha mahākarambhādīnām phalaṃ kumudvatīreṇukākarambhamahākarambhamadanakatuvarakādīnām tvaksāraniryāsāḥ karakakaraghāṭakakarambhamahākarambhanārācakādīnām kṣīraṃ kumudvatī dantī snuhyarkajālinī vyālādīnām dhātavo haritālaphenāśmabhasmaraktaprabhṛtayaḥ kandajāni tu hālāhalakālakūṭavatsanābhaśṛṅgīsāṣarpajālakakardamakavairāṭakamustakamuṣkakasāktukakrauñcakavālakamahāviṣapuṇḍarīkagālavamūlakamarkaṭakarkaṭakakaravīrakendrāyudhasaṅkocakalāṅgalakatailapeya kuśapuṣpake tu puṣpakarohiṣāñjanābhakādīni" },
      { type: "verse", number: "8", sanskrit: "तत्र मूलविषैरुपयुक्तैरुद्वेष्टनप्रलापमोहाः प्रजायन्ते पत्रविषैर्जृम्भोद्वेष्टनश्वासाः पुष्पविषैश्छर्द्याध्मानमोहाः फलविषैर्दाहमुष्कशोफौ त्वक्सारनिर्यासविषैः प्रसेकास्यदौर्गन्ध्यपारुष्यशिरोवेदनाः क्षीरविषैर्जिह्वागौरवं शकृत्भेदश्च धातुविषैस्तालुदाहमूर्च्छाहृदयपीडाः सर्वमेव च स्थावरं ज्वरहिध्मादन्तहर्षहनुस्तम्भगलग्रहफेनवमनारुचिश्वासमूर्च्छाः करोति विशेषेण कन्दजम् तद्ध्यतितीक्ष्णत्वादाशुकारितरम् इतरत्तु प्रायः कालान्तरप्राणहरम्", text: "tatra mūlaviṣairupayuktairudveṣṭanapralāpamohāḥ prajāyante patraviṣairjṛmbhodveṣṭanaśvāsāḥ puṣpaviṣaiśchardyādhmānamohāḥ phalaviṣairdāhamuṣkaśophau tvaksāraniryāsaviṣaiḥ prasekāsyadaurgandhyapāruṣyaśirovedanāḥ kṣīraviṣairjihvāgauravaṃ śakṛtbhedaśca dhātuviṣaistāludāhamūrcchāhṛdayapīḍāḥ sarvameva ca sthāvaraṃ jvarahidhmādantaharṣahanustambhagalagrahaphenavamanāruciśvāsamūrcchāḥ karoti viśeṣeṇa kandajam taddhyatitīkṣṇatvādāśukāritaram itarattu prāyaḥ kālāntaraprāṇaharam" },
      { type: "verse", number: "9", sanskrit: "सर्वमपि चैतन्मौलमित्युच्यते मूलाश्रयत्वात् पत्रादीनाम्", text: "sarvamapi caitanmaulamityucyate mūlāśrayatvāt patrādīnām" },
      { type: "verse", number: "10", sanskrit: "जङ्गमस्य त्वाश्रयाः षोदश दृष्टिनिश्वासस्पर्शदंष्ट्रामुखनखास्थिमूत्रपुरीषशुक्रार्तवलालाशूकपित्तशोणितशवानि तानि पुनः सर्पकीटकणभाद्याश्रितानि तत्कृतान्यथास्वमामयान् साधनं चोत्तरत्र वक्ष्यति", text: "jaṅgamasya tvāśrayāḥ ṣodaśa dṛṣṭiniśvāsasparśadaṃṣṭrāmukhanakhāsthimūtrapurīṣaśukrārtavalālāśūkapittaśoṇitaśavāni tāni punaḥ sarpakīṭakaṇabhādyāśritāni tatkṛtānyathāsvamāmayān sādhanaṃ cottaratra vakṣyati" },
      { type: "verse", number: "11", sanskrit: "सर्वं च प्रायशो जङ्गमं निद्रातन्द्राक्लमदाहरोमहर्षशोफपाकातिसारान् करोति", text: "sarvaṃ ca prāyaśo jaṅgamaṃ nidrātandrāklamadāharomaharṣaśophapākātisārān karoti" },
      { type: "verse", number: "12", sanskrit: "द्विविधमपिचैतद्विषं तीक्ष्णोष्णरूक्षविशदसूक्ष्मव्यवाय्याशुकारिविकाशिलघ्वव्यक्तरसत्वैर्दशभिर्गुणैर्युक्तमपाकि च", text: "dvividhamapicaitadviṣaṃ tīkṣṇoṣṇarūkṣaviśadasūkṣmavyavāyyāśukārivikāśilaghvavyaktarasatvairdaśabhirguṇairyuktamapāki ca" },
      { type: "verse", number: "13", sanskrit: "तत्र तैक्ष्ण्यौष्ण्यात् पित्तं रक्तं च प्रकोपयति रौक्ष्याद्वायुम् वैशद्यादसक्तवेगं प्रसरति सौक्ष्म्याद्व्यवायित्वाच्च दोषधातुमलादीन् समस्तान् शरीरावयवाननुप्रविशति आशुकारित्वादाशु व्यापादयति विकाशित्वान्मर्मच्छेदेन मतिं व्यामोहयति लाघवाद्दुर्निर्हरमव्यक्तरसत्वाच्छ्लेष्मप्रकोपणमन्नरसांश्च सर्वाननुवर्तते अत एव च प्रयत्नेनान्नानि विषतो रक्षेदित्युक्तम् अपाकित्वाज्जरां नो याति तेनाभ्यवहृतमवश्यं मारयति मन्त्रौषधबलेन चोपशमितमपि प्रत्ययमासाद्य पुनः प्रकृप्यतीति भवति चात्र", text: "tatra taikṣṇyauṣṇyāt pittaṃ raktaṃ ca prakopayati raukṣyādvāyum vaiśadyādasaktavegaṃ prasarati saukṣmyādvyavāyitvācca doṣadhātumalādīn samastān śarīrāvayavānanupraviśati āśukāritvādāśu vyāpādayati vikāśitvānmarmacchedena matiṃ vyāmohayati lāghavāddurnirharamavyaktarasatvācchleṣmaprakopaṇamannarasāṃśca sarvānanuvartate ata eva ca prayatnenānnāni viṣato rakṣedityuktam apākitvājjarāṃ no yāti tenābhyavahṛtamavaśyaṃ mārayati mantrauṣadhabalena copaśamitamapi pratyayamāsādya punaḥ prakṛpyatīti bhavati cātra" },
      { type: "verse", number: "14", sanskrit: "स्थावरं जङ्गमं चेति विषं प्रोक्तमकृत्रिमम्", text: "sthāvaraṃ jaṅgamaṃ ceti viṣaṃ proktamakṛtrimam" },
      { type: "verse", number: "15", sanskrit: "कृत्रिमं गरसंज्ञं तु क्रियते विविधौषधैः हन्ति योगवशेनाशु चिराच्चिरतराच्च तत् शोफपाण्डूदरोन्माददुर्नामादीन्करोति वा", text: "kṛtrimaṃ garasaṃjñaṃ tu kriyate vividhauṣadhaiḥ hanti yogavaśenāśu cirācciratarācca tat śophapāṇḍūdaronmādadurnāmādīnkaroti vā" },
      { type: "verse", number: "16", sanskrit: "अपि चैतद्विषं सर्वं तीक्ष्णाद्यैरन्वितं गुणैः वातपित्तोत्तरं नृऋणां सद्यो हरति जीवितम्", text: "api caitadviṣaṃ sarvaṃ tīkṣṇādyairanvitaṃ guṇaiḥ vātapittottaraṃ nṛṛṇāṃ sadyo harati jīvitam" },
      { type: "verse", number: "17", sanskrit: "विषं हि देहं सम्प्राप्य प्राग्दूषयति शोणितम् कफपित्तानिलांश्चानु समदोषं सहाशयान् ततो हृदयमास्थाय देहोच्छेदाय कल्पते", text: "viṣaṃ hi dehaṃ samprāpya prāgdūṣayati śoṇitam kaphapittānilāṃścānu samadoṣaṃ sahāśayān tato hṛdayamāsthāya dehocchedāya kalpate" },
      { type: "verse", number: "18", sanskrit: "शरीरं दूषिते रक्ते सर्वं चिमिचिमायते कोठः समण्डलः स्वेदो रोमहर्षश्च जायते", text: "śarīraṃ dūṣite rakte sarvaṃ cimicimāyate koṭhaḥ samaṇḍalaḥ svedo romaharṣaśca jāyate" },
      { type: "verse", number: "19", sanskrit: "क्षुद्रकीटा इवाङ्गेषु विसर्पन्तीति मन्यते विनामयति गात्राणि जृम्भते शिशिरप्रियः", text: "kṣudrakīṭā ivāṅgeṣu visarpantīti manyate vināmayati gātrāṇi jṛmbhate śiśirapriyaḥ" },
      { type: "verse", number: "20", sanskrit: "व्यापिनस्तस्य दुष्टस्य द्रुतस्य विषतेजसा वातादयो वशं यान्ति बलिनोप्यबला इव", text: "vyāpinastasya duṣṭasya drutasya viṣatejasā vātādayo vaśaṃ yānti balinopyabalā iva" },
      { type: "verse", number: "21", sanskrit: "विषं यद्दोषभूयिष्ठं तं दोषं प्राक् प्रपद्यते आशये यस्य यस्यैव ततस्तदवतिष्ठते तज्जान् विकारान् कुरुते यान् सर्वेषूपदेक्ष्यति", text: "viṣaṃ yaddoṣabhūyiṣṭhaṃ taṃ doṣaṃ prāk prapadyate āśaye yasya yasyaiva tatastadavatiṣṭhate tajjān vikārān kurute yān sarveṣūpadekṣyati" },
      { type: "verse", number: "22", sanskrit: "वाताशयस्थं कुरुते तथा श्लेष्मामयानपि पित्तश्लेष्माशयगतं तद्वत् पित्तकफोद्भवान्", text: "vātāśayasthaṃ kurute tathā śleṣmāmayānapi pittaśleṣmāśayagataṃ tadvat pittakaphodbhavān" },
      { type: "verse", number: "23", sanskrit: "तत्रापि चोत्तमाङ्गस्थे सकोठं शूयते शिरः विशेषादक्षिकूटौष्ठनासास्यं हृष्टदन्तता ताल्शोषो रुजा मूर्ध्नि वक्त्रे चिमिचिमायनम्", text: "tatrāpi cottamāṅgasthe sakoṭhaṃ śūyate śiraḥ viśeṣādakṣikūṭauṣṭhanāsāsyaṃ hṛṣṭadantatā tālśoṣo rujā mūrdhni vaktre cimicimāyanam" },
      { type: "verse", number: "24", sanskrit: "अर्थेषु चक्षुरादीनामप्रवृत्तिर्हनुग्रहः इत्यन्यापि च विषं स्थितमङ्गे ऽभिलक्षयेत्", text: "artheṣu cakṣurādīnāmapravṛttirhanugrahaḥ ityanyāpi ca viṣaṃ sthitamaṅge 'bhilakṣayet" },
      { type: "verse", number: "25", sanskrit: "व्याप्यैवं सकलं देहमुपरुध्य च वाहिनीः विषं विषमिव क्षिप्रं प्राणानस्य निरस्यति", text: "vyāpyaivaṃ sakalaṃ dehamuparudhya ca vāhinīḥ viṣaṃ viṣamiva kṣipraṃ prāṇānasya nirasyati" },
      { type: "verse", number: "26", sanskrit: "पीतं मृतस्य हृदये जग्धदिग्धाभिविद्धयोः दंशे तिष्ठति भूयिष्ठं सर्वतः पिण्डितं विषम् नाद्यादतो विशेषेण तेषां मांसं तदाश्रयम्", text: "pītaṃ mṛtasya hṛdaye jagdhadigdhābhividdhayoḥ daṃśe tiṣṭhati bhūyiṣṭhaṃ sarvataḥ piṇḍitaṃ viṣam nādyādato viśeṣeṇa teṣāṃ māṃsaṃ tadāśrayam" },
      { type: "verse", number: "27", sanskrit: "यथास्वं भक्षिते पीडा यथास्वं च क्रियाक्रमः", text: "yathāsvaṃ bhakṣite pīḍā yathāsvaṃ ca kriyākramaḥ" },
      { type: "verse", number: "28", sanskrit: "सप्त वेगान् विषस्याहुरष्टावितिपुनर्वसुः (चृ.ष्ष् ५.४.३९ च्ष् ६.२३.७)", text: "sapta vegān viṣasyāhuraṣṭāvitipunarvasuḥ (cṛ.ṣṣ 5.4.39 Cṣ 6.23.7)" },
      { type: "verse", number: "29", sanskrit: "दुष्यति प्रथमे वेगे रसश्छर्द्दिप्रसेककृत् द्वितीयेस्रं चिमिचिमाजृम्भावेपथुकारि तत्", text: "duṣyati prathame vege rasaścharddiprasekakṛt dvitīyesraṃ cimicimājṛmbhāvepathukāri tat" },
      { type: "verse", number: "30", sanskrit: "तृतीये पिशितं कण्डूकोठमण्डलशोफदम् दोषाश्चाश्चतुर्थे तेषु स्युर्यथायथमुपद्रवाः", text: "tṛtīye piśitaṃ kaṇḍūkoṭhamaṇḍalaśophadam doṣāścāścaturthe teṣu syuryathāyathamupadravāḥ" },
      { type: "verse", number: "31", sanskrit: "पञ्चमे दर्शनभ्रान्तिः षष्ठे हिध्मासमुद्भवः सप्तमे स्कन्धभङ्गोस्य जायते मृत्युरष्टमे", text: "pañcame darśanabhrāntiḥ ṣaṣṭhe hidhmāsamudbhavaḥ saptame skandhabhaṅgosya jāyate mṛtyuraṣṭame" },
      { type: "verse", number: "32", sanskrit: "दुष्यति प्रथमे रक्तं द्वितीये श्वयथूद्भवः तृतीयेङ्गे चिमिचिमा चतुर्थे ज्वरमूर्च्छना", text: "duṣyati prathame raktaṃ dvitīye śvayathūdbhavaḥ tṛtīyeṅge cimicimā caturthe jvaramūrcchanā" },
      { type: "verse", number: "33", sanskrit: "पञ्चमे पाण्डुजिह्वास्य शोषः षष्ठे हृदि व्यथा सप्तमे मरणं वेग इति गग्नजितो मतम्", text: "pañcame pāṇḍujihvāsya śoṣaḥ ṣaṣṭhe hṛdi vyathā saptame maraṇaṃ vega iti gagnajito matam" },
      { type: "verse", number: "34", sanskrit: "मूर्च्छा हृदि परं पीडा शिरोरुगपतन्त्रकः हिध्मा च दारुणो मर्मच्छेदो जीवितसंशयः सप्तेति वेगा मूर्च्छाद्या विदेहपतिना स्मृताः", text: "mūrcchā hṛdi paraṃ pīḍā śirorugapatantrakaḥ hidhmā ca dāruṇo marmacchedo jīvitasaṃśayaḥ sapteti vegā mūrcchādyā videhapatinā smṛtāḥ" },
      { type: "verse", number: "35", sanskrit: "रक्तमांसवसास्नायु तथास्थ्याद्यास्त्रयः क्रमात् आश्रयाः सप्त सप्तानामित्यालम्बायनो ऽब्रवीत्", text: "raktamāṃsavasāsnāyu tathāsthyādyāstrayaḥ kramāt āśrayāḥ sapta saptānāmityālambāyano 'bravīt" },
      { type: "verse", number: "36", sanskrit: "वेगान् धन्वन्तरिस्तद्वत् सर्पदष्टस्य मन्यते स्नाववर्जं तु तत्स्थाने दोषानिच्छति कोष्ठगान्", text: "vegān dhanvantaristadvat sarpadaṣṭasya manyate snāvavarjaṃ tu tatsthāne doṣānicchati koṣṭhagān" },
      { type: "verse", number: "37", sanskrit: "धात्वन्तरेषु याः सप्त कलाः पूर्वं प्रकीर्त्तिताः अतीत्य तासामेकैकां वेगं प्रकुरुते विषम्", text: "dhātvantareṣu yāḥ sapta kalāḥ pūrvaṃ prakīrttitāḥ atītya tāsāmekaikāṃ vegaṃ prakurute viṣam" },
      { type: "verse", number: "38", sanskrit: "तत्कालकल्पं कालेन कलामभ्येति यावता ऊह्यमानं समीरेण तावद्वेगान्तरं स्मृतम्", text: "tatkālakalpaṃ kālena kalāmabhyeti yāvatā ūhyamānaṃ samīreṇa tāvadvegāntaraṃ smṛtam" },
      { type: "verse", number: "39", sanskrit: "मुनिना येन यत्तूक्तं तत्सर्वमिह दर्शितम्", text: "muninā yena yattūktaṃ tatsarvamiha darśitam" },
      { type: "verse", number: "40", sanskrit: "जीर्णं विषघ्नौषधिभिर्हतं वा दवाग्निवातातपशोषितं वा स्वभावतो वा न गुणैः सुयुक्तं दूषीविषाख्यां विषमभ्युपैति", text: "jīrṇaṃ viṣaghnauṣadhibhirhataṃ vā davāgnivātātapaśoṣitaṃ vā svabhāvato vā na guṇaiḥ suyuktaṃ dūṣīviṣākhyāṃ viṣamabhyupaiti" },
      { type: "verse", number: "41", sanskrit: "वीर्याल्पभावादविभाव्यमेतत् कफावृतं वर्षगणानुबन्धि", text: "vīryālpabhāvādavibhāvyametat kaphāvṛtaṃ varṣagaṇānubandhi" },
      { type: "verse", number: "42", sanskrit: "तेनादिर्तो भिन्नपुरीषवर्णो दुष्टास्ररोगी तृडरोचकार्तः मूर्च्छन् वमन् गद्गदवाग्विमुह्यन् भवेच्च दूष्योदरलिङ्गजुष्टः", text: "tenādirto bhinnapurīṣavarṇo duṣṭāsrarogī tṛḍarocakārtaḥ mūrcchan vaman gadgadavāgvimuhyan bhavecca dūṣyodaraliṅgajuṣṭaḥ" },
      { type: "verse", number: "43", sanskrit: "आमाशयस्थे कफवातरोगी पित्ताशस्थे ऽनिलपित्तरोगी भवेन्नरो ध्वस्थीशरोरुहाङ्गो विलूनपक्षः स यथा विहङ्गः स्थितं रसादिष्वथवा विचित्रान् करोति धातुप्रभवान्विकारान्", text: "āmāśayasthe kaphavātarogī pittāśasthe 'nilapittarogī bhavennaro dhvasthīśaroruhāṅgo vilūnapakṣaḥ sa yathā vihaṅgaḥ sthitaṃ rasādiṣvathavā vicitrān karoti dhātuprabhavānvikārān" },
      { type: "verse", number: "44", sanskrit: "प्राग्वाताजीर्णशीताभ्रदिवास्वप्नाहिताशनैः दुष्टं दूषयते धातूनतो दूषीविषं स्मृतम्", text: "prāgvātājīrṇaśītābhradivāsvapnāhitāśanaiḥ duṣṭaṃ dūṣayate dhātūnato dūṣīviṣaṃ smṛtam" },
      { type: "verse", number: "45", sanskrit: "स्थावरस्योपयुक्तस्य पूर्वे वेगे ऽथ जायते जिह्वायाः श्यावता स्तम्भो मूर्च्छा त्रासः क्लमो वमिः", text: "sthāvarasyopayuktasya pūrve vege 'tha jāyate jihvāyāḥ śyāvatā stambho mūrcchā trāsaḥ klamo vamiḥ" },
      { type: "verse", number: "46", sanskrit: "द्वितीये वेपथुः स्वेदो कण्ठे च वेदनाः विषं चामाशयं प्राप्तं कुरुते हृदि वेदनाम्", text: "dvitīye vepathuḥ svedo kaṇṭhe ca vedanāḥ viṣaṃ cāmāśayaṃ prāptaṃ kurute hṛdi vedanām" },
      { type: "verse", number: "47", sanskrit: "तालुशोषस्तृतीये तु शूलं चामाशये भृशम् दुर्बले हरिते शूने जायेते चास्य लोचने", text: "tāluśoṣastṛtīye tu śūlaṃ cāmāśaye bhṛśam durbale harite śūne jāyete cāsya locane" },
      { type: "verse", number: "48", sanskrit: "पक्वाशयगते तोदहिध्माकासान्त्रकूजनम् चतुर्थे जायते वेगे शिरसश्चातिगौरवम्", text: "pakvāśayagate todahidhmākāsāntrakūjanam caturthe jāyate vege śirasaścātigauravam" },
      { type: "verse", number: "49", sanskrit: "कफप्रसेको वैवर्ण्यं पर्वभेदश्च पञ्चमे सर्वदोषप्रकोपश्च पक्वाधाने च वेदना", text: "kaphapraseko vaivarṇyaṃ parvabhedaśca pañcame sarvadoṣaprakopaśca pakvādhāne ca vedanā" },
      { type: "verse", number: "50", sanskrit: "षष्ठे संज्ञाप्रणाशश्च सुभृशं चातिसार्यते स्कन्धपृष्ठकटीभङ्गो भवेन्मृत्युश्च सप्तमे", text: "ṣaṣṭhe saṃjñāpraṇāśaśca subhṛśaṃ cātisāryate skandhapṛṣṭhakaṭībhaṅgo bhavenmṛtyuśca saptame" },
      { type: "verse", number: "51", sanskrit: "प्रथमे विषवेगेथ वान्तं शीताम्बुसेचितम् सर्पिर्मधुभ्यां संयुक्तमगदं पाययेद्द्रुतम्", text: "prathame viṣavegetha vāntaṃ śītāmbusecitam sarpirmadhubhyāṃ saṃyuktamagadaṃ pāyayeddrutam" },
      { type: "verse", number: "52", sanskrit: "द्वितीये पूर्ववद्वान्तं विरिक्तं चानु पाययेत् तृतीये ऽगदपानं च हितं नस्यं तथाञ्जनम्", text: "dvitīye pūrvavadvāntaṃ viriktaṃ cānu pāyayet tṛtīye 'gadapānaṃ ca hitaṃ nasyaṃ tathāñjanam" },
      { type: "verse", number: "53", sanskrit: "चतुर्थे स्नेहसंयुक्तमगदं प्रतिभोजयेत् पञ्चमे मधुकक्वाथमाक्षिकाभ्यां युतं हितम्", text: "caturthe snehasaṃyuktamagadaṃ pratibhojayet pañcame madhukakvāthamākṣikābhyāṃ yutaṃ hitam" },
      { type: "verse", number: "54", sanskrit: "षष्ठे ऽतिसारवत् सिद्धिरवपीडस्तु सप्तमे मूर्ध्नि काकपदं कृत्वा सासृग्वा पिशितं क्षिपेत्", text: "ṣaṣṭhe 'tisāravat siddhiravapīḍastu saptame mūrdhni kākapadaṃ kṛtvā sāsṛgvā piśitaṃ kṣipet" },
      { type: "verse", number: "55", sanskrit: "कोशातक्यग्निकः पाठा सूर्यवल्यमृताभयाः शेलुः शिरीषः किणिही हरिद्रे क्षुद्रसाह्वया पुनर्नवे त्रिकटुकं बृहत्यौ सारिवे बले", text: "kośātakyagnikaḥ pāṭhā sūryavalyamṛtābhayāḥ śeluḥ śirīṣaḥ kiṇihī haridre kṣudrasāhvayā punarnave trikaṭukaṃ bṛhatyau sārive bale" },
      { type: "verse", number: "56", sanskrit: "एषां यवागूं निर्यूहे शीतां सघृतमाक्षिकाम् युञ्ज्याद्वेगान्तरे सर्वविषघ्नीं कृतकर्मणः", text: "eṣāṃ yavāgūṃ niryūhe śītāṃ saghṛtamākṣikām yuñjyādvegāntare sarvaviṣaghnīṃ kṛtakarmaṇaḥ" },
      { type: "verse", number: "57", sanskrit: "तद्वन्मधूकमधुकपद्मकेसरचन्दनैः", text: "tadvanmadhūkamadhukapadmakesaracandanaiḥ" },
      { type: "verse", number: "58", sanskrit: "अगदान् वक्ष्यते चातः सिद्धान् पूर्वर्षिनिर्मितान् सर्वेषु सर्वावस्थेषु ये विषेषु परं हिताः", text: "agadān vakṣyate cātaḥ siddhān pūrvarṣinirmitān sarveṣu sarvāvastheṣu ye viṣeṣu paraṃ hitāḥ" },
      { type: "verse", number: "59", sanskrit: "चन्दनं कुङ्कुमं कुष्ठं काङ्क्षी लाक्षा प्रियङ्गवः मुस्तस्थौणेयशैलेयरोचनामदनप्लवम्", text: "candanaṃ kuṅkumaṃ kuṣṭhaṃ kāṅkṣī lākṣā priyaṅgavaḥ mustasthauṇeyaśaileyarocanāmadanaplavam" },
      { type: "verse", number: "60", sanskrit: "श्रोवेष्टकीवडैङ्गलाविशालालमनश्शिलाः सुरसप्रसवस्पृक्कारजनीद्वयवालकम्", text: "śroveṣṭakīvaḍaiṅgalāviśālālamanaśśilāḥ surasaprasavaspṛkkārajanīdvayavālakam" },
      { type: "verse", number: "61", sanskrit: "हिङ्गुसिद्धार्थकाः पद्मचारिणी पद्मकेसरम् जात्याःपुष्पं प्रवालश्च पुष्पमर्कशिरीषयोः", text: "hiṅgusiddhārthakāḥ padmacāriṇī padmakesaram jātyāḥpuṣpaṃ pravālaśca puṣpamarkaśirīṣayoḥ" },
      { type: "verse", number: "62", sanskrit: "द्विरोध्रबृहती कौन्ती मधुकं गन्धनाकुली मुद्गपर्णीकणाश्यामा ध्यामकं नलदं नतम्", text: "dvirodhrabṛhatī kauntī madhukaṃ gandhanākulī mudgaparṇīkaṇāśyāmā dhyāmakaṃ naladaṃ natam" },
      { type: "verse", number: "63", sanskrit: "सिन्दुवारकशम्याकदेवदारुमयूरकम् पुष्ये समाहृतैः पिष्टैर्योज्यस्तैरगदोत्तमः", text: "sinduvārakaśamyākadevadārumayūrakam puṣye samāhṛtaiḥ piṣṭairyojyastairagadottamaḥ" },
      { type: "verse", number: "64", sanskrit: "सञ्जीवनःप्रागमृताद्विहितो ऽयं स्वयम्भुवा पाननस्याञ्जनाघ्राणधूमालेपनधारणैः", text: "sañjīvanaḥprāgamṛtādvihito 'yaṃ svayambhuvā pānanasyāñjanāghrāṇadhūmālepanadhāraṇaiḥ" },
      { type: "verse", number: "65", sanskrit: "जीवनो विषसुप्तानां राजद्वारे जयावहः धन्यो धान्यधनायुःश्रीक्षेमपुष्टिसुखप्रदः", text: "jīvano viṣasuptānāṃ rājadvāre jayāvahaḥ dhanyo dhānyadhanāyuḥśrīkṣemapuṣṭisukhapradaḥ" },
      { type: "verse", number: "66", sanskrit: "गृहे स्थितो विषालक्ष्मीमन्त्रज्वरगरग्रहान् कृत्याकार्मणकाखोर्दव्यालजन्तुसरीसृपान्", text: "gṛhe sthito viṣālakṣmīmantrajvaragaragrahān kṛtyākārmaṇakākhordavyālajantusarīsṛpān" },
      { type: "verse", number: "67", sanskrit: "स्वप्नोपघातदुःस्वप्नतोयाग्निरिपुतस्करान् निहन्त्यकालमरणमरकाशनिविग्रहान्", text: "svapnopaghātaduḥsvapnatoyāgniriputaskarān nihantyakālamaraṇamarakāśanivigrahān" },
      { type: "verse", number: "68", sanskrit: "चन्दनं वालकं मुस्तं ध्यामकं कटुका नतम् दाडिमं कुङ्कुमं शुण्ठी कपित्थं वत्सकात्फलम्", text: "candanaṃ vālakaṃ mustaṃ dhyāmakaṃ kaṭukā natam dāḍimaṃ kuṅkumaṃ śuṇṭhī kapitthaṃ vatsakātphalam" },
      { type: "verse", number: "69", sanskrit: "करञ्जबीजं मरिचमुत्पलं कमलं दलम् नलमूलमपामार्गं करवीरकमञ्जनम्", text: "karañjabījaṃ maricamutpalaṃ kamalaṃ dalam nalamūlamapāmārgaṃ karavīrakamañjanam" },
      { type: "verse", number: "70", sanskrit: "लाक्षामालत्यहिच्छत्रनागपुष्पाम्लवेतसम् विशालारोचनाश्यामा शङ्खपुष्पीप्रियङ्गुका", text: "lākṣāmālatyahicchatranāgapuṣpāmlavetasam viśālārocanāśyāmā śaṅkhapuṣpīpriyaṅgukā" },
      { type: "verse", number: "71", sanskrit: "अजाजी सारिवाकुष्ठमजमोजः कुरण्डकः वयस्था सिन्दुवारैला कायस्था चारटी वचा", text: "ajājī sārivākuṣṭhamajamojaḥ kuraṇḍakaḥ vayasthā sinduvārailā kāyasthā cāraṭī vacā" },
      { type: "verse", number: "72", sanskrit: "कर्कटी पूतना केशी श्वेता च गिरिकर्णिका गोलोमी सिंहलोमी च वर्षाभूर्गजपिप्पली अगदो यापनाख्योयं पूर्वेण सदृशो गुणैः", text: "karkaṭī pūtanā keśī śvetā ca girikarṇikā golomī siṃhalomī ca varṣābhūrgajapippalī agado yāpanākhyoyaṃ pūrveṇa sadṛśo guṇaiḥ" },
      { type: "verse", number: "73", sanskrit: "श्रीवेष्टकं हरिद्रे द्वे कोविदारं मनःशिलाम् पिप्पलीं पाटलीं पद्मां श्वेतां च गिरिकर्णिकाम् मञ्जिष्ठां बृहतीं वक्रं यष्टी मरिचकेसरम्", text: "śrīveṣṭakaṃ haridre dve kovidāraṃ manaḥśilām pippalīṃ pāṭalīṃ padmāṃ śvetāṃ ca girikarṇikām mañjiṣṭhāṃ bṛhatīṃ vakraṃ yaṣṭī maricakesaram" },
      { type: "verse", number: "74", sanskrit: "फलीनीं किणिहीं चेति गवां पित्तेन भावयेत् सूर्योदयो हन्ति विषं तमः सूर्योदयो यथा", text: "phalīnīṃ kiṇihīṃ ceti gavāṃ pittena bhāvayet sūryodayo hanti viṣaṃ tamaḥ sūryodayo yathā" },
      { type: "verse", number: "75", sanskrit: "निम्बपत्रं गृहाद्धूमं फाणितं बृहतीफलम् गोपित्तयुक्तमगदः परमं मृतजीवनः", text: "nimbapatraṃ gṛhāddhūmaṃ phāṇitaṃ bṛhatīphalam gopittayuktamagadaḥ paramaṃ mṛtajīvanaḥ" },
      { type: "verse", number: "76", sanskrit: "गोपित्तकुष्ठसुरसं मधुकद्विनिशं तथा विशालारजनीकुष्ठश्वपित्तव्योषतुम्बुरु", text: "gopittakuṣṭhasurasaṃ madhukadviniśaṃ tathā viśālārajanīkuṣṭhaśvapittavyoṣatumburu" },
      { type: "verse", number: "77", sanskrit: "वचाशिरीषपञ्चाङ्गी मृतसञ्जीवनो गदः पञ्चाङ्गानि शिरीषस्य श्वपित्तं च वरो ऽगदः", text: "vacāśirīṣapañcāṅgī mṛtasañjīvano gadaḥ pañcāṅgāni śirīṣasya śvapittaṃ ca varo 'gadaḥ" },
      { type: "verse", number: "78", sanskrit: "प्रियङ्गु तगरं लाक्षा मञ्जिष्ठा मधुकं मधु हरिद्राचेत्ययं श्रेष्ठः कौटिल्यदयितो ऽगदः", text: "priyaṅgu tagaraṃ lākṣā mañjiṣṭhā madhukaṃ madhu haridrācetyayaṃ śreṣṭhaḥ kauṭilyadayito 'gadaḥ" },
      { type: "verse", number: "79", sanskrit: "विसंज्ञानां विषैर्घोरैः प्रहाअरैर्नष्टचेतसाम् उद्बन्धानां जलौघे च मृतानां चेतनावहः", text: "visaṃjñānāṃ viṣairghoraiḥ prahāarairnaṣṭacetasām udbandhānāṃ jalaughe ca mṛtānāṃ cetanāvahaḥ" },
      { type: "verse", number: "80", sanskrit: "शिरीषफलकाकाण्डसुरसाग्रपुनर्नवैः कक्ष्यावायसिसंयुक्तैरगदः पूर्ववत् गुणैः", text: "śirīṣaphalakākāṇḍasurasāgrapunarnavaiḥ kakṣyāvāyasisaṃyuktairagadaḥ pūrvavat guṇaiḥ" },
      { type: "verse", number: "81", sanskrit: "कटुकालाबुमूलानि गवां पित्तेन कल्कयेत् ब्राह्मो धार्योयमगदः सर्वकर्मसु पूजितः", text: "kaṭukālābumūlāni gavāṃ pittena kalkayet brāhmo dhāryoyamagadaḥ sarvakarmasu pūjitaḥ" },
      { type: "verse", number: "82", sanskrit: "अगारधूमस्रिवृता गोपित्तं त्र्यूषणं वचा प्राजापत्योयमगदः सर्वरक्षोविषापहः", text: "agāradhūmasrivṛtā gopittaṃ tryūṣaṇaṃ vacā prājāpatyoyamagadaḥ sarvarakṣoviṣāpahaḥ" },
      { type: "verse", number: "83", sanskrit: "श्वेतापुष्करतुल्यांशैर्जीवन्त्याः कुसुमैः कृतः रुक्मपिष्टो मणिर्द्धार्यश्चाणक्येष्टो विषापहः", text: "śvetāpuṣkaratulyāṃśairjīvantyāḥ kusumaiḥ kṛtaḥ rukmapiṣṭo maṇirddhāryaścāṇakyeṣṭo viṣāpahaḥ" },
      { type: "verse", number: "84", sanskrit: "मांसीत्वक्पत्रसुरसमनोह्वाशीतकुङ्कुमम् निशाव्याघ्रन्नखं शुण्ठी दशाङ्गो ऽयं विषापहः उत्पातगण्डपिटकादिग्धविद्धविषापहः", text: "māṃsītvakpatrasurasamanohvāśītakuṅkumam niśāvyāghrannakhaṃ śuṇṭhī daśāṅgo 'yaṃ viṣāpahaḥ utpātagaṇḍapiṭakādigdhaviddhaviṣāpahaḥ" },
      { type: "verse", number: "85", sanskrit: "उदुम्बरत्वग्जम्ब्वस्थिमधुकोत्पलगैरिकैः चन्दनोशीरनलद नागकेसरपद्मकैः विशेषाद्विषविस्फोटविसर्पज्वरदाहहा", text: "udumbaratvagjambvasthimadhukotpalagairikaiḥ candanośīranalada nāgakesarapadmakaiḥ viśeṣādviṣavisphoṭavisarpajvaradāhahā" },
      { type: "verse", number: "86", sanskrit: "शिरीषोदुम्बरप्लक्षन्यग्रोधाश्वत्थवल्कलैः सघृतो दाहतृष्णास्रविषवीसर्पपित्तहा", text: "śirīṣodumbaraplakṣanyagrodhāśvatthavalkalaiḥ saghṛto dāhatṛṣṇāsraviṣavīsarpapittahā" },
      { type: "verse", number: "87", sanskrit: "गजपिप्पलिकासीसक्षारयष्टीमयूरकम् रक्ता नतं वचा दन्ती शिवः शिवकृतो ऽगदः", text: "gajapippalikāsīsakṣārayaṣṭīmayūrakam raktā nataṃ vacā dantī śivaḥ śivakṛto 'gadaḥ" },
      { type: "verse", number: "88", sanskrit: "सुराला पावकी सोमा भोगवत्यमृता नतम् आढकी किणिही सोमराजी चौशनसो ऽगदः", text: "surālā pāvakī somā bhogavatyamṛtā natam āḍhakī kiṇihī somarājī cauśanaso 'gadaḥ" },
      { type: "verse", number: "89", sanskrit: "श्लेष्मातकार्ककुसुमं तण्डुलीयो मयूरकः सुरसा मञ्जरी काकमाची पाने ऽगदो वरः", text: "śleṣmātakārkakusumaṃ taṇḍulīyo mayūrakaḥ surasā mañjarī kākamācī pāne 'gado varaḥ" },
      { type: "verse", number: "90", sanskrit: "दध्याज्यक्षौद्रलवणं पीतं मूलविषापहम् हरिद्रासैन्धवक्षौद्रघृतं संसृज्य पाययेत् आर्तान् मूलविषैर्घोरैर्दिग्धविद्धान् विशेषतः", text: "dadhyājyakṣaudralavaṇaṃ pītaṃ mūlaviṣāpaham haridrāsaindhavakṣaudraghṛtaṃ saṃsṛjya pāyayet ārtān mūlaviṣairghorairdigdhaviddhān viśeṣataḥ" },
      { type: "verse", number: "91", sanskrit: "हरिद्रान्तर्बहिःशस्ता विषदोषातुरे परम्", text: "haridrāntarbahiḥśastā viṣadoṣāture param" },
      { type: "verse", number: "92", sanskrit: "निशाश्वमारसुरसकरञ्ञव्योषदारुभिः अञ्जनं बस्तमूत्रेण पिष्टैर्नेत्रोपरोधजित्", text: "niśāśvamārasurasakaraññavyoṣadārubhiḥ añjanaṃ bastamūtreṇa piṣṭairnetroparodhajit" },
      { type: "verse", number: "93", sanskrit: "कर्णाक्षिनासिकाकण्ठजिह्वारोगेषु नावनम् बीजपूरार्यबृहतीफलज्योतिष्मतीकृतम्", text: "karṇākṣināsikākaṇṭhajihvārogeṣu nāvanam bījapūrāryabṛhatīphalajyotiṣmatīkṛtam" },
      { type: "verse", number: "94", sanskrit: "श्वेता वचा हिङ्ग्वमृता सुगन्धा कुष्ठसैन्धवम् शिरीषपुष्पद्विनिशाव्योषटुण्टुकसर्षपाः", text: "śvetā vacā hiṅgvamṛtā sugandhā kuṣṭhasaindhavam śirīṣapuṣpadviniśāvyoṣaṭuṇṭukasarṣapāḥ" },
      { type: "verse", number: "95", sanskrit: "कपित्थमध्यं लशुनं करञ्जो वंशलेखनम् पिष्ट्वा गोबस्तमूत्रेण तत्पित्तेनैव भावयेत्", text: "kapitthamadhyaṃ laśunaṃ karañjo vaṃśalekhanam piṣṭvā gobastamūtreṇa tatpittenaiva bhāvayet" },
      { type: "verse", number: "96", sanskrit: "दिनानि सप्त व्यत्यासाद्विनिहन्ति ततोञ्जनात् विषं शिरस्थं मूर्द्धार्तिज्वरजीर्णविषूचिकाः", text: "dināni sapta vyatyāsādvinihanti tatoñjanāt viṣaṃ śirasthaṃ mūrddhārtijvarajīrṇaviṣūcikāḥ" },
      { type: "verse", number: "97", sanskrit: "अपस्मारग्रहोन्मादपाण्डुमेहमदात्ययान् शुष्कनेत्रामयशिरोरोगपैल्लगलार्बुदान्", text: "apasmāragrahonmādapāṇḍumehamadātyayān śuṣkanetrāmayaśirorogapaillagalārbudān" },
      { type: "verse", number: "98", sanskrit: "काचान्धकारपटलकण्डूदौर्बल्ययक्ष्मणः लेपात् पीतक्षतालीढदष्टदिग्धविषं जयेत्", text: "kācāndhakārapaṭalakaṇḍūdaurbalyayakṣmaṇaḥ lepāt pītakṣatālīḍhadaṣṭadigdhaviṣaṃ jayet" },
      { type: "verse", number: "99", sanskrit: "श्वित्रं कृच्छ्राणि कुष्ठानि दुष्टनाडी महाव्रणान् आनाहार्शो गुदे लेपाल्ललाटे दुष्टपीनसम्", text: "śvitraṃ kṛcchrāṇi kuṣṭhāni duṣṭanāḍī mahāvraṇān ānāhārśo gude lepāllalāṭe duṣṭapīnasam" },
      { type: "verse", number: "100", sanskrit: "योनिलेपेन नारीणां मूढगर्भानुलोमनः उन्मूलयत्येष विषं गन्धहस्तीव काननम्", text: "yonilepena nārīṇāṃ mūḍhagarbhānulomanaḥ unmūlayatyeṣa viṣaṃ gandhahastīva kānanam" },
      { type: "verse", number: "101", sanskrit: "विडङ्गपाठा त्रिफलाजमोदा हिङ्ग्वग्निवक्रं लवणस्यवर्गः व्योषान्वितं स्थावरजङ्गमानां जेता विषाणामगदो ऽजिताख्यः", text: "viḍaṅgapāṭhā triphalājamodā hiṅgvagnivakraṃ lavaṇasyavargaḥ vyoṣānvitaṃ sthāvarajaṅgamānāṃ jetā viṣāṇāmagado 'jitākhyaḥ" },
      { type: "verse", number: "102", sanskrit: "मनोह्वा रोचना चण्डा त्वगेलासितसर्षपैः स्पृक्काहिंगुलकाश्मीरकान्ताभिःकल्कितो ऽगदः विषघ्नो बालसूर्योयं श्रीरक्षाविजयर्द्धिदः", text: "manohvā rocanā caṇḍā tvagelāsitasarṣapaiḥ spṛkkāhiṃgulakāśmīrakāntābhiḥkalkito 'gadaḥ viṣaghno bālasūryoyaṃ śrīrakṣāvijayarddhidaḥ" },
      { type: "verse", number: "103", sanskrit: "अजगन्धा सगोमूत्रा गृहधूमः सुगुग्गुलुः एष माहेश्वरो योगो न क्वचित् प्रतिहन्यते", text: "ajagandhā sagomūtrā gṛhadhūmaḥ sugugguluḥ eṣa māheśvaro yogo na kvacit pratihanyate" },
      { type: "verse", number: "104", sanskrit: "विषदिग्धेन विद्धस्तु प्रताम्यति मुहुर्मुहुः विवर्णभावं भजते विषादं चाशु गच्छति", text: "viṣadigdhena viddhastu pratāmyati muhurmuhuḥ vivarṇabhāvaṃ bhajate viṣādaṃ cāśu gacchati" },
      { type: "verse", number: "105", sanskrit: "कीटैरिवावृतं चास्य गात्रं चिमिचिमायते श्रोणिपृष्ठशिरःस्कन्धसन्धयः स्युः सवेदनाः", text: "kīṭairivāvṛtaṃ cāsya gātraṃ cimicimāyate śroṇipṛṣṭhaśiraḥskandhasandhayaḥ syuḥ savedanāḥ" },
      { type: "verse", number: "106", sanskrit: "कृष्णदुष्टास्रविस्रावी तृण्मूर्च्छाज्वरदाहवान् दृष्टिकालुष्यवमथुश्वासकासकरः क्षणात्", text: "kṛṣṇaduṣṭāsravisrāvī tṛṇmūrcchājvaradāhavān dṛṣṭikāluṣyavamathuśvāsakāsakaraḥ kṣaṇāt" },
      { type: "verse", number: "107", sanskrit: "शूयते पच्यते सद्यो गत्वा मांसं च कृष्णताम् प्रक्लिन्नं शीर्यते ऽभीक्ष्णं सपिच्छिलपरिस्रवम्", text: "śūyate pacyate sadyo gatvā māṃsaṃ ca kṛṣṇatām praklinnaṃ śīryate 'bhīkṣṇaṃ sapicchilaparisravam" },
      { type: "verse", number: "108", sanskrit: "कुर्यादमर्मविद्धस्य हृदयावरणं द्रुतम् शल्यमाकृष्य तप्तेन लोहेनानु दहेद्व्रणम्", text: "kuryādamarmaviddhasya hṛdayāvaraṇaṃ drutam śalyamākṛṣya taptena lohenānu dahedvraṇam" },
      { type: "verse", number: "109", sanskrit: "अथवा मुष्ककश्वेतासोमत्वक्ताम्रवल्लितः शिरीषात् गृध्रनख्याश्च क्षारेण प्रतिसारयेत् शुकनासाप्रतिविषाव्याघ्रीमूलैश्च लेपयेत्", text: "athavā muṣkakaśvetāsomatvaktāmravallitaḥ śirīṣāt gṛdhranakhyāśca kṣāreṇa pratisārayet śukanāsāprativiṣāvyāghrīmūlaiśca lepayet" },
      { type: "verse", number: "110", sanskrit: "पीतदष्टचिकित्सां च कुर्यात्तस्य यथार्हतः व्रणे तु पूतिपिशिते क्रिया पित्तविसर्पवत्", text: "pītadaṣṭacikitsāṃ ca kuryāttasya yathārhataḥ vraṇe tu pūtipiśite kriyā pittavisarpavat" },
      { type: "verse", number: "111", sanskrit: "सौभाग्यार्थं स्त्रियो भर्त्रे राज्ञे वारातिचोदिताः गरमाहारसम्पृक्तं यच्छन्त्यासन्नवर्तिनः", text: "saubhāgyārthaṃ striyo bhartre rājñe vārāticoditāḥ garamāhārasampṛktaṃ yacchantyāsannavartinaḥ" },
      { type: "verse", number: "112", sanskrit: "नानाप्राण्यङ्गशमलविरुद्धौषधिभस्मनाम् विषाणां चाल्पवीर्याणां योगो गर इति स्मृतः", text: "nānāprāṇyaṅgaśamalaviruddhauṣadhibhasmanām viṣāṇāṃ cālpavīryāṇāṃ yogo gara iti smṛtaḥ" },
      { type: "verse", number: "113", sanskrit: "तेन पाण्डुः कृशोल्पाग्निः कासश्वासज्वरार्दितः वायुना प्रतिलोमेन स्वप्नचिन्तापरायणः", text: "tena pāṇḍuḥ kṛśolpāgniḥ kāsaśvāsajvarārditaḥ vāyunā pratilomena svapnacintāparāyaṇaḥ" },
      { type: "verse", number: "114", sanskrit: "महोदरयकृत्प्लीहो दीनवाग्दुर्बलो ऽलसः शोफवान् सतताध्मातः शुष्कपादकरः क्षयी", text: "mahodarayakṛtplīho dīnavāgdurbalo 'lasaḥ śophavān satatādhmātaḥ śuṣkapādakaraḥ kṣayī" },
      { type: "verse", number: "115", sanskrit: "स्वप्ने गोमायुमार्जारनकुलव्यालवानरान् प्रायः पश्यति शुष्कांश्च वनस्पतिजलाशयान्", text: "svapne gomāyumārjāranakulavyālavānarān prāyaḥ paśyati śuṣkāṃśca vanaspatijalāśayān" },
      { type: "verse", number: "116", sanskrit: "मन्यते कृष्णमात्मानं गौरो गौरं च कालकः विकर्णनासानयनं पश्येत्तद्विहतेन्द्रियः", text: "manyate kṛṣṇamātmānaṃ gauro gauraṃ ca kālakaḥ vikarṇanāsānayanaṃ paśyettadvihatendriyaḥ" },
      { type: "verse", number: "117", sanskrit: "एतैरन्यैश्च बहुभिः क्लिष्टो घोरैरुद्रवैः गरार्तो नाशमाप्नोति कश्चित्सद्यो ऽचिकित्सितः", text: "etairanyaiśca bahubhiḥ kliṣṭo ghorairudravaiḥ garārto nāśamāpnoti kaścitsadyo 'cikitsitaḥ" },
      { type: "verse", number: "118", sanskrit: "गरार्तो वान्तवान् भुक्त्वा तत्पथ्यं पानभोजनम् शुद्धहृच्छीलयेद्धेम सूत्रस्थानविधेः स्मरन्", text: "garārto vāntavān bhuktvā tatpathyaṃ pānabhojanam śuddhahṛcchīlayeddhema sūtrasthānavidheḥ smaran" },
      { type: "verse", number: "119", sanskrit: "शर्कराक्षौद्रसंयुक्तश्चूर्णस्ताप्यसुवर्णयोः लेहः प्रशमयत्युग्रं सर्वं योगकृतं विषम्", text: "śarkarākṣaudrasaṃyuktaścūrṇastāpyasuvarṇayoḥ lehaḥ praśamayatyugraṃ sarvaṃ yogakṛtaṃ viṣam" },
      { type: "verse", number: "120", sanskrit: "मूर्वामृतानतकणापटोलीचव्यचित्रकान् वचामुस्तविडङ्गानि तक्रकोष्णाम्बुमस्तुभिः पिबेद्रसेन चाम्लेन गरोपहतपावकः", text: "mūrvāmṛtānatakaṇāpaṭolīcavyacitrakān vacāmustaviḍaṅgāni takrakoṣṇāmbumastubhiḥ pibedrasena cāmlena garopahatapāvakaḥ" },
      { type: "verse", number: "121", sanskrit: "पारावतामिषशठीपुष्कराह्वशृतं हिमम् गरतृष्णारुजाकासश्वासहिध्माज्वरापहम्", text: "pārāvatāmiṣaśaṭhīpuṣkarāhvaśṛtaṃ himam garatṛṣṇārujākāsaśvāsahidhmājvarāpaham" },
      { type: "verse", number: "122", sanskrit: "वायसी श्वासकासघ्नी भृष्टाज्यत्रिफलारसे भार्ङ्गीनागरनिर्यूहः शिशिरश्च समाक्षिकः", text: "vāyasī śvāsakāsaghnī bhṛṣṭājyatriphalārase bhārṅgīnāgaraniryūhaḥ śiśiraśca samākṣikaḥ" },
      { type: "verse", number: "123", sanskrit: "हरेणुचन्दनश्यामानलदं श्लक्ष्णपेषितम् विलेपनं प्रयोक्तव्यं गरेणोपहतत्वचः", text: "hareṇucandanaśyāmānaladaṃ ślakṣṇapeṣitam vilepanaṃ prayoktavyaṃ gareṇopahatatvacaḥ" },
      { type: "verse", number: "124", sanskrit: "मञ्जिष्ठा किणिहीनिम्बरजन्यश्वत्थचन्दनैः प्रघर्षणं कृशानां तु गरेण क्षपितौजसाम्", text: "mañjiṣṭhā kiṇihīnimbarajanyaśvatthacandanaiḥ pragharṣaṇaṃ kṛśānāṃ tu gareṇa kṣapitaujasām" },
      { type: "verse", number: "125", sanskrit: "पथ्यं परममुद्दिष्टं शीलनं क्षीरसर्पिषोः", text: "pathyaṃ paramamuddiṣṭaṃ śīlanaṃ kṣīrasarpiṣoḥ" },
      { type: "verse", number: "126", sanskrit: "वृषनिम्बपटोलीनां क्वाथेन् विपचेत् घृतम् अभयागार्भिणं श्रेष्ठं तत् गरस्य निबर्हणम्", text: "vṛṣanimbapaṭolīnāṃ kvāthen vipacet ghṛtam abhayāgārbhiṇaṃ śreṣṭhaṃ tat garasya nibarhaṇam" },
      { type: "verse", number: "127", sanskrit: "हरिद्रां नाकुलीं जातीं पृथक्पिष्ट्वा विपाचयेत् घृतत्रयं विषार्तानामेतदारोग्यदं परम्", text: "haridrāṃ nākulīṃ jātīṃ pṛthakpiṣṭvā vipācayet ghṛtatrayaṃ viṣārtānāmetadārogyadaṃ param" },
      { type: "verse", number: "128", sanskrit: "तण्डुलीयकमूलेन गृहधूमेन चैकतः क्षीरेण च घृतं सिद्धं समस्तविषरोगजित्", text: "taṇḍulīyakamūlena gṛhadhūmena caikataḥ kṣīreṇa ca ghṛtaṃ siddhaṃ samastaviṣarogajit" },
      { type: "verse", number: "129", sanskrit: "नागदन्ती त्रिवृद्दन्ती द्रवन्ती स्नुक्पयः पलैः साधितं माहिषं सर्पिः सगोमूत्राढकं हितम् सर्पकीटविषार्तानां गरार्तानां च शान्तये", text: "nāgadantī trivṛddantī dravantī snukpayaḥ palaiḥ sādhitaṃ māhiṣaṃ sarpiḥ sagomūtrāḍhakaṃ hitam sarpakīṭaviṣārtānāṃ garārtānāṃ ca śāntaye" },
      { type: "verse", number: "130", sanskrit: "मधुकं तगरं कुष्ठभद्रदारुहरेणवः मञ्जिष्ठैलैलवालूनि नागपुष्पोत्पलं प्लवम्", text: "madhukaṃ tagaraṃ kuṣṭhabhadradāruhareṇavaḥ mañjiṣṭhailailavālūni nāgapuṣpotpalaṃ plavam" },
      { type: "verse", number: "131", sanskrit: "विडङ्गं चन्दनं पत्रं प्रियङ्गुर्ध्यामकं बला अंशुमत्यौ हरिद्रे द्वे बृहत्यौ सारिवाद्वयम्", text: "viḍaṅgaṃ candanaṃ patraṃ priyaṅgurdhyāmakaṃ balā aṃśumatyau haridre dve bṛhatyau sārivādvayam" },
      { type: "verse", number: "132", sanskrit: "एषां कल्कैर्घृतं सिद्धमजेयं नाम विश्रुतम् विषाणि हन्ति सर्वाणि शीघ्रमेव प्रयोजितम्", text: "eṣāṃ kalkairghṛtaṃ siddhamajeyaṃ nāma viśrutam viṣāṇi hanti sarvāṇi śīghrameva prayojitam" },
      { type: "verse", number: "133", sanskrit: "श्वेते कपोते बीजानि प्रत्यक्पुषीशिरीषयोः गोमूत्रपिष्टैस्तैः सर्पिः सिद्धं बिषहरं परम् अमृतं नाम विख्यातमपि सञ्जीवयेन्मृतम्", text: "śvete kapote bījāni pratyakpuṣīśirīṣayoḥ gomūtrapiṣṭaistaiḥ sarpiḥ siddhaṃ biṣaharaṃ param amṛtaṃ nāma vikhyātamapi sañjīvayenmṛtam" },
      { type: "verse", number: "134", sanskrit: "शिरीषत्वक् त्रिकटुकं विदारी चन्दनोत्पलम् द्वे बले सारिवास्फोतबृहतीनिम्बपल्लवाः", text: "śirīṣatvak trikaṭukaṃ vidārī candanotpalam dve bale sārivāsphotabṛhatīnimbapallavāḥ" },
      { type: "verse", number: "135", sanskrit: "बन्धुजीवाढकीमूर्वावासासुरसवत्सकाः पाठाङ्कोलाश्वगन्धार्कमूलयष्ट्याह्वपद्मकम्", text: "bandhujīvāḍhakīmūrvāvāsāsurasavatsakāḥ pāṭhāṅkolāśvagandhārkamūlayaṣṭyāhvapadmakam" },
      { type: "verse", number: "136", sanskrit: "विशाला बृहती लाक्षा कोविदारशतावरीः कटभीदन्त्यपामार्ग पृश्निपर्णी रसाञ्जनम्", text: "viśālā bṛhatī lākṣā kovidāraśatāvarīḥ kaṭabhīdantyapāmārga pṛśniparṇī rasāñjanam" },
      { type: "verse", number: "137", sanskrit: "श्वेतौ बाणाश्वखुरकौ कुष्ठदारुप्रियङ्गुकाः सारं मधूकात्रिफलां करञ्जस्यफलं वचाम्", text: "śvetau bāṇāśvakhurakau kuṣṭhadārupriyaṅgukāḥ sāraṃ madhūkātriphalāṃ karañjasyaphalaṃ vacām" },
      { type: "verse", number: "138", sanskrit: "रजन्यौ लोध्रमक्षांशं पिष्ट्वा साध्यं घृताढकम् तुल्याम्बुछागगोमूत्रत्र्याढके तद्विषापहम्", text: "rajanyau lodhramakṣāṃśaṃ piṣṭvā sādhyaṃ ghṛtāḍhakam tulyāmbuchāgagomūtratryāḍhake tadviṣāpaham" },
      { type: "verse", number: "139", sanskrit: "अपस्मारक्षयोन्मादभूतग्रहगरोदरान् पाण्डुरोगकृमिप्लीहगुल्मोरुस्तम्भकार्मलाः", text: "apasmārakṣayonmādabhūtagrahagarodarān pāṇḍurogakṛmiplīhagulmorustambhakārmalāḥ" },
      { type: "verse", number: "140", sanskrit: "हनुस्तम्भग्रहादींश्च पानाभ्यञ्जननावनैः हन्ति सञ्जीवयति च विषोद्बन्धमृतान् नरान्", text: "hanustambhagrahādīṃśca pānābhyañjananāvanaiḥ hanti sañjīvayati ca viṣodbandhamṛtān narān" },
      { type: "verse", number: "141", sanskrit: "भक्षिते हरिताले तु हृदि दाहोरसाग्रहः आनाहोम्लस्य वमनं पीतहारिद्रविट्स्रुतिः तथा मण्डलिसर्पोक्ता विकारास्तच्च भेषजम्", text: "bhakṣite haritāle tu hṛdi dāhorasāgrahaḥ ānāhomlasya vamanaṃ pītahāridraviṭsrutiḥ tathā maṇḍalisarpoktā vikārāstacca bheṣajam" },
      { type: "verse", number: "142", sanskrit: "विभज्य योजयेत् ऊर्ध्वमधः संशोधितं च तम् अङ्कोलजालिनीबीजशुकनासाप्रियङ्गुकाः लोध्रध्यामकतालीसनतयष्ट्याह्वगुग्गुलुः", text: "vibhajya yojayet ūrdhvamadhaḥ saṃśodhitaṃ ca tam aṅkolajālinībījaśukanāsāpriyaṅgukāḥ lodhradhyāmakatālīsanatayaṣṭyāhvagugguluḥ" },
      { type: "verse", number: "143", sanskrit: "हीबेरं भद्रकाष्ठं च लेहयेन्मधुसर्पिषा दद्यान्नकुलगोपित्तयुक्तं नस्येञ्जने च तत्", text: "hīberaṃ bhadrakāṣṭhaṃ ca lehayenmadhusarpiṣā dadyānnakulagopittayuktaṃ nasyeñjane ca tat" },
      { type: "verse", number: "144", sanskrit: "धुर्धूरकोपयोगेन सर्वं पश्यति पीतकम् कम्पलालामदच्छर्दिस्मृतिभ्रंशभ्रमान्वितः तं वामयेत मधुरैः पाययेद्वा सितापयः", text: "dhurdhūrakopayogena sarvaṃ paśyati pītakam kampalālāmadacchardismṛtibhraṃśabhramānvitaḥ taṃ vāmayeta madhuraiḥ pāyayedvā sitāpayaḥ" },
      { type: "verse", number: "145", sanskrit: "कोरदूषैर्मदनकैः प्रायो धुर्धूरवत् गदाः उन्मादोक्षिविनाशश्च तत्रापि वमनं हितम् कूष्माण्डकं च सगुडं बहुशस्तत्र भक्षयेत्", text: "koradūṣairmadanakaiḥ prāyo dhurdhūravat gadāḥ unmādokṣivināśaśca tatrāpi vamanaṃ hitam kūṣmāṇḍakaṃ ca saguḍaṃ bahuśastatra bhakṣayet" },
      { type: "verse", number: "146", sanskrit: "नानाप्रकारैः संयोगैः कोद्रवा मदहेतवः तान्विभज्य यथादोषं चिकित्सेदविरोधिभिः", text: "nānāprakāraiḥ saṃyogaiḥ kodravā madahetavaḥ tānvibhajya yathādoṣaṃ cikitsedavirodhibhiḥ" },
      { type: "verse", number: "147", sanskrit: "दूंषीविषार्तं सुस्विन्नमूर्ध्वं चाधश्च शोधितम् दूषीविषारिमगदं लेहयेन्मधुनाप्लुतम्", text: "dūṃṣīviṣārtaṃ susvinnamūrdhvaṃ cādhaśca śodhitam dūṣīviṣārimagadaṃ lehayenmadhunāplutam" },
      { type: "verse", number: "148", sanskrit: "पिप्पल्योध्यामकं मांसी लोध्रमेला सुवर्चिका कुटन्नटं नतं कुष्ठं यष्टी चन्दनगैरिकम् दूषीविषारिर्नाम्नायं नचान्यत्रापि वार्यते", text: "pippalyodhyāmakaṃ māṃsī lodhramelā suvarcikā kuṭannaṭaṃ nataṃ kuṣṭhaṃ yaṣṭī candanagairikam dūṣīviṣārirnāmnāyaṃ nacānyatrāpi vāryate" },
      { type: "verse", number: "149", sanskrit: "हरीतकी सलवणा मागधी मरिचानि च एतद्दूषीविषार्तानां काश्यपोक्तं विरेचनम्", text: "harītakī salavaṇā māgadhī maricāni ca etaddūṣīviṣārtānāṃ kāśyapoktaṃ virecanam" },
      { type: "verse", number: "150", sanskrit: "युञ्ज्याद्वा विषरोगेषु रेके व्योषादिकं भिषक्", text: "yuñjyādvā viṣarogeṣu reke vyoṣādikaṃ bhiṣak" },
      { type: "verse", number: "151", sanskrit: "तरुणस्य पलाशस्य स्रुतं क्षारोदकं पचेत् क्वाथे तत्र प्रतीवापं प्रक्षिपेच्छ्रलक्ष्णचूर्णितम्", text: "taruṇasya palāśasya srutaṃ kṣārodakaṃ pacet kvāthe tatra pratīvāpaṃ prakṣipecchralakṣṇacūrṇitam" },
      { type: "verse", number: "152", sanskrit: "व्योषं शिरीषकुसुमं मधुकं सारिवे मिसिम् कुष्ठं वेल्लनिशे लाक्षां शुक्लां सुरसमञ्जरीम्", text: "vyoṣaṃ śirīṣakusumaṃ madhukaṃ sārive misim kuṣṭhaṃ vellaniśe lākṣāṃ śuklāṃ surasamañjarīm" },
      { type: "verse", number: "153", sanskrit: "सिन्धूत्थं रक्तमृन्मांसीं रेणुकां हिङ्गुबाल्हिकम् दर्वीप्रलेपि तज्जातं गोविषाणे निधापयेत्", text: "sindhūtthaṃ raktamṛnmāṃsīṃ reṇukāṃ hiṅgubālhikam darvīpralepi tajjātaṃ goviṣāṇe nidhāpayet" },
      { type: "verse", number: "154", sanskrit: "क्षयगुल्मोदरार्शांसि मेहं मन्दाग्नितां ज्वरम् त्वग्दोषकासापस्मारग्रहोन्मादभगन्दरान्", text: "kṣayagulmodarārśāṃsi mehaṃ mandāgnitāṃ jvaram tvagdoṣakāsāpasmāragrahonmādabhagandarān" },
      { type: "verse", number: "155", sanskrit: "पाण्डुं कण्ठस्वरगदान् प्लीहानं श्वयथुं कृमीन् कोलमात्रमतः खादन् जयेत् सर्वविषाणि च", text: "pāṇḍuṃ kaṇṭhasvaragadān plīhānaṃ śvayathuṃ kṛmīn kolamātramataḥ khādan jayet sarvaviṣāṇi ca" },
      { type: "verse", number: "156", sanskrit: "विषं तेजोमयं मन्त्रैः सत्यब्रह्मतपोमयैः यथा निवार्यते शीघ्रं प्रयुक्तैर्न तथौषधैः", text: "viṣaṃ tejomayaṃ mantraiḥ satyabrahmatapomayaiḥ yathā nivāryate śīghraṃ prayuktairna tathauṣadhaiḥ" },
      { type: "verse", number: "157", sanskrit: "न तु सर्वमनुष्याणां सन्ति भेषजसम्पदः अज्ञातरोगसद्भावे योग्यता चातिदुर्लभा", text: "na tu sarvamanuṣyāṇāṃ santi bheṣajasampadaḥ ajñātarogasadbhāve yogyatā cātidurlabhā" },
      { type: "verse", number: "158", sanskrit: "प्रकुप्यति विषं भूयः केवलैश्चौषधैर्जितम् अवाप्तौ सिद्धमन्त्राणां यतेतातश्चिकित्सकः", text: "prakupyati viṣaṃ bhūyaḥ kevalaiścauṣadhairjitam avāptau siddhamantrāṇāṃ yatetātaścikitsakaḥ" },
      { type: "verse", number: "159", sanskrit: "ते ऽपि च व्रतहीनस्य हीना वा स्वरवर्णतः यस्मान्न सिद्धिमायान्ति तस्माद्योज्यो ऽगदक्रमः", text: "te 'pi ca vratahīnasya hīnā vā svaravarṇataḥ yasmānna siddhimāyānti tasmādyojyo 'gadakramaḥ" },
      { type: "verse", number: "160", sanskrit: "विषप्रकृतिकालान्नदोषदूष्यादिसङ्गमे विषसङ्कटमुद्दिष्टं शतस्यैकोत्र जीवति", text: "viṣaprakṛtikālānnadoṣadūṣyādisaṅgame viṣasaṅkaṭamuddiṣṭaṃ śatasyaikotra jīvati" },
      { type: "verse", number: "161", sanskrit: "क्षुत्तृष्णाघर्म्मदौर्बल्यक्रोधशोकभयश्रमैः अजीर्णवर्चोद्रवता पित्तमारुतवृद्धिभिः", text: "kṣuttṛṣṇāgharmmadaurbalyakrodhaśokabhayaśramaiḥ ajīrṇavarcodravatā pittamārutavṛddhibhiḥ" },
      { type: "verse", number: "162", sanskrit: "तिलपुष्पफलाध्राणभूबाष्पघनगर्जितैः हस्तिमूषिकवादित्रनिस्वनैर्विषसङ्कटैः पुरोवातोत्पलामोदमदनैर्बर्धते विषम्", text: "tilapuṣpaphalādhrāṇabhūbāṣpaghanagarjitaiḥ hastimūṣikavāditranisvanairviṣasaṅkaṭaiḥ purovātotpalāmodamadanairbardhate viṣam" },
      { type: "verse", number: "163", sanskrit: "वर्षासु चाम्बुयोनित्वात् सङ्क्लेदं गुडवद्गतम् विसर्पति घनापाये तदगस्त्यो हिनास्ति च प्रयाति मन्दवीर्यत्वं विषं तस्मात् घनात्यये", text: "varṣāsu cāmbuyonitvāt saṅkledaṃ guḍavadgatam visarpati ghanāpāye tadagastyo hināsti ca prayāti mandavīryatvaṃ viṣaṃ tasmāt ghanātyaye" },
      { type: "verse", number: "164", sanskrit: "इति प्रकृतिसात्म्यर्तुस्थानवेगबलाबलम् आलोच्य निपुणं बुध्या कर्मानन्तरमाचरेत्", text: "iti prakṛtisātmyartusthānavegabalābalam ālocya nipuṇaṃ budhyā karmānantaramācaret" },
      { type: "verse", number: "165", sanskrit: "श्लैष्मिकं वमनैरुष्णरूक्षतीक्ष्णैः प्रलेपनैः कषायकटुतिक्तैश्च भोजनैः शमयेद्विषम्", text: "ślaiṣmikaṃ vamanairuṣṇarūkṣatīkṣṇaiḥ pralepanaiḥ kaṣāyakaṭutiktaiśca bhojanaiḥ śamayedviṣam" },
      { type: "verse", number: "166", sanskrit: "पैत्तिकं स्रंसनैः सेकप्रदेहैर्भृशशीतलैः कषायतिक्तमधुरैर्घृतयुक्तैश्च भोजनैः", text: "paittikaṃ sraṃsanaiḥ sekapradehairbhṛśaśītalaiḥ kaṣāyatiktamadhurairghṛtayuktaiśca bhojanaiḥ" },
      { type: "verse", number: "167", sanskrit: "वातात्मकंजयेत्स्वादुस्निग्धाम्ललवणान्वितैः सघृतैर्भोजनालेपैस्तथैव पिशिताशनैः", text: "vātātmakaṃjayetsvādusnigdhāmlalavaṇānvitaiḥ saghṛtairbhojanālepaistathaiva piśitāśanaiḥ" },
      { type: "verse", number: "168", sanskrit: "नाघृतं स्रंसनं शस्तं प्रलेपो भोज्यमौषधम् सर्वेषु सर्वावस्थासु विषेषु न घृतोपमम् विद्यते भेषजं किञ्चिद्विशेषात् प्रबलानिले", text: "nāghṛtaṃ sraṃsanaṃ śastaṃ pralepo bhojyamauṣadham sarveṣu sarvāvasthāsu viṣeṣu na ghṛtopamam vidyate bheṣajaṃ kiñcidviśeṣāt prabalānile" },
      { type: "verse", number: "169", sanskrit: "रक्तगे स्रावयेद्रक्तं पित्तवच्च क्रियाक्रमः दूषीविषे पुनस्तत्स्थे पञ्चकर्माणि चाचरेत्", text: "raktage srāvayedraktaṃ pittavacca kriyākramaḥ dūṣīviṣe punastatsthe pañcakarmāṇi cācaret" },
      { type: "verse", number: "170", sanskrit: "गण्डूषैः कवलैः प्राशैस्तीक्ष्णैः प्रधमनाञ्जनैः शिरोगतं प्रशमयेद्विषसङ्क्रमणैस्तथा", text: "gaṇḍūṣaiḥ kavalaiḥ prāśaistīkṣṇaiḥ pradhamanāñjanaiḥ śirogataṃ praśamayedviṣasaṅkramaṇaistathā" },
      { type: "verse", number: "171", sanskrit: "विषदुष्टकफस्रोतोरुद्धवायुर्मृतोपमः यःस्यादसाध्यलिङ्गैश्च रहितस्तस्य योजयेत्", text: "viṣaduṣṭakaphasrotoruddhavāyurmṛtopamaḥ yaḥsyādasādhyaliṅgaiśca rahitastasya yojayet" },
      { type: "verse", number: "172", sanskrit: "मूर्ध्निं काकपदं कृत्वा कल्कं चर्मकसोद्भवम् ध्मापनं चास्य कटभीजालिनी कटुकैर्हितम्", text: "mūrdhniṃ kākapadaṃ kṛtvā kalkaṃ carmakasodbhavam dhmāpanaṃ cāsya kaṭabhījālinī kaṭukairhitam" },
      { type: "verse", number: "173", sanskrit: "आशये यस्य दोषस्य विषं तिष्ठति तं पुनः आश्रयाश्रयिणोर्विद्वानविरोधेन साधयेत्", text: "āśaye yasya doṣasya viṣaṃ tiṣṭhati taṃ punaḥ āśrayāśrayiṇorvidvānavirodhena sādhayet" },
      { type: "verse", number: "174", sanskrit: "क्षारागदः कफस्थानस्थिते स्वेदः सिराव्यधः पित्ते क्षौद्रपयोम्लाज्यपानसेकावगाहनम् स्वेदो वाताशये दध्ना पानं च नतकुष्ठयोः", text: "kṣārāgadaḥ kaphasthānasthite svedaḥ sirāvyadhaḥ pitte kṣaudrapayomlājyapānasekāvagāhanam svedo vātāśaye dadhnā pānaṃ ca natakuṣṭhayoḥ" },
      { type: "verse", number: "175", sanskrit: "क्षीरेणागदगर्मेण मदनस्य फलेन च आस्थापनं प्रयुञ्जीत वाताशयगते विषे", text: "kṣīreṇāgadagarmeṇa madanasya phalena ca āsthāpanaṃ prayuñjīta vātāśayagate viṣe" },
      { type: "verse", number: "176", sanskrit: "पचेद्यष्टीमधुक्वाथे तैलं क्षीरचतुर्गुणम् त्रिफला सर्पवेताली शतपुष्पेन्दुराजिभिः", text: "pacedyaṣṭīmadhukvāthe tailaṃ kṣīracaturguṇam triphalā sarpavetālī śatapuṣpendurājibhiḥ" },
      { type: "verse", number: "177", sanskrit: "अनन्तया च तत्पाननावनाभ्यङ्गबस्तिषु भोजने च प्रणिहितं हन्ति वाताशयाद्विषम्", text: "anantayā ca tatpānanāvanābhyaṅgabastiṣu bhojane ca praṇihitaṃ hanti vātāśayādviṣam" },
      { type: "verse", number: "178", sanskrit: "वलया सोमराज्या वा पचेत् पाटलयाथवा घृतमण्डसमं तैलमानुवासनिकं परम्", text: "valayā somarājyā vā pacet pāṭalayāthavā ghṛtamaṇḍasamaṃ tailamānuvāsanikaṃ param" },
      { type: "verse", number: "179", sanskrit: "विषोपद्रवपथ्यं च वीक्ष्य युञ्ज्याद्यथामयम्", text: "viṣopadravapathyaṃ ca vīkṣya yuñjyādyathāmayam" },
      { type: "verse", number: "180", sanskrit: "अयत्नाच्छ्लेष्मगं साध्यं यत्नात्पित्ताशयाश्रितम् सुदुस्साधमसाध्यं वा वाताशयगतं विषम्", text: "ayatnācchleṣmagaṃ sādhyaṃ yatnātpittāśayāśritam sudussādhamasādhyaṃ vā vātāśayagataṃ viṣam" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 41,
    lang: "sa",
    content: [
      { type: "heading", heading: "Вататапика расаяна — расаяна под открытым небом" },
      { type: "text", text: "Глава 41 Уттара стханы — «Вататапика расаяна» — посвящена специализированному разделу: расаяна под открытым небом. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः सर्पविषविज्ञानीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ sarpaviṣavijñānīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "दिव्यभौमविभागेन द्विविधाः पन्नगाः स्मृताः वासुकिस्तक्षकोनन्तः सगरः सागरालयः", text: "divyabhaumavibhāgena dvividhāḥ pannagāḥ smṛtāḥ vāsukistakṣakonantaḥ sagaraḥ sāgarālayaḥ" },
      { type: "verse", number: "3", sanskrit: "तथा नन्दोपनन्दाद्याः समिद्धाग्निसमप्रभाः दिव्या गर्जन्ति वर्षन्ति द्योतन्ते द्योतयन्ति ते", text: "tathā nandopanandādyāḥ samiddhāgnisamaprabhāḥ divyā garjanti varṣanti dyotante dyotayanti te" },
      { type: "verse", number: "4", sanskrit: "धारयन्ति जगत्कृत्स्नं कुर्युःक्रुद्धाश्च भस्मसात् दृङ्निश्वासैर्नमस्तेभ्यो नतेष्वस्ति चिकित्सितम्", text: "dhārayanti jagatkṛtsnaṃ kuryuḥkruddhāśca bhasmasāt dṛṅniśvāsairnamastebhyo nateṣvasti cikitsitam" },
      { type: "verse", number: "5", sanskrit: "दर्वीकरा मण्डलिनो राजीमन्तश्च पन्नगाः त्रिधा समासतो भौमा भिद्यन्ते तेत्वनेकधा व्यासतो योनिभेदेन नोच्यन्ते ऽनुपयोगतः", text: "darvīkarā maṇḍalino rājīmantaśca pannagāḥ tridhā samāsato bhaumā bhidyante tetvanekadhā vyāsato yonibhedena nocyante 'nupayogataḥ" },
      { type: "verse", number: "6", sanskrit: "विशेषाद्रूक्षकटुकमम्लोष्णं स्वादु शीतलम् विषं दर्वीकरादीनां क्रमाद्वातादिकोपनम्", text: "viśeṣādrūkṣakaṭukamamloṣṇaṃ svādu śītalam viṣaṃ darvīkarādīnāṃ kramādvātādikopanam" },
      { type: "verse", number: "7", sanskrit: "तारुण्यमध्यवृद्धत्वे वृष्टिशीतातपेषु च विषोल्बणा भवन्त्येते व्यन्तरा ऋतुसन्धिषु", text: "tāruṇyamadhyavṛddhatve vṛṣṭiśītātapeṣu ca viṣolbaṇā bhavantyete vyantarā ṛtusandhiṣu" },
      { type: "verse", number: "8", sanskrit: "रथाङ्गलाङ्गलच्छत्रस्वस्तिकाङ्कुशधारिणः फणिनः शीघ्रगतयः सर्पा दर्वीकराः स्मृताः", text: "rathāṅgalāṅgalacchatrasvastikāṅkuśadhāriṇaḥ phaṇinaḥ śīghragatayaḥ sarpā darvīkarāḥ smṛtāḥ" },
      { type: "verse", number: "9", sanskrit: "ज्ञेया मण्डलिनो ऽभोगा मण्डलैर्विविधैश्चिताः प्रांशवो मन्दगमनाः राजीमन्तस्तु राजिभिः स्निग्धा विचित्रवर्णाभिस्तिर्यगूर्ध्वं च चित्रिताः", text: "jñeyā maṇḍalino 'bhogā maṇḍalairvividhaiścitāḥ prāṃśavo mandagamanāḥ rājīmantastu rājibhiḥ snigdhā vicitravarṇābhistiryagūrdhvaṃ ca citritāḥ" },
      { type: "verse", number: "10", sanskrit: "गोधासुतस्तु गौधेरो विषे दर्वीकरैः समः", text: "godhāsutastu gaudhero viṣe darvīkaraiḥ samaḥ" },
      { type: "verse", number: "11", sanskrit: "चतुष्पात् व्यन्तरान् विद्योदतेषामेव सङ्करात् व्यामिश्रलक्षणास्ते हि सन्निपातप्रकोपणाः", text: "catuṣpāt vyantarān vidyodateṣāmeva saṅkarāt vyāmiśralakṣaṇāste hi sannipātaprakopaṇāḥ" },
      { type: "verse", number: "12", sanskrit: "दिव्यकोजगरः सर्पः पताको वृक्षशायिकः शकली पुष्पकः क्षीरी लासिनी सारसाहिकः", text: "divyakojagaraḥ sarpaḥ patāko vṛkṣaśāyikaḥ śakalī puṣpakaḥ kṣīrī lāsinī sārasāhikaḥ" },
      { type: "verse", number: "13", sanskrit: "वर्षाहिको ज्योतिरथः शुकवक्त्रो बलाहकः गजभक्षःप्लवोद्वाही निर्विषाः षोडशाहयः", text: "varṣāhiko jyotirathaḥ śukavaktro balāhakaḥ gajabhakṣaḥplavodvāhī nirviṣāḥ ṣoḍaśāhayaḥ" },
      { type: "verse", number: "14", sanskrit: "प्रायेणर्तुमती मासं ज्येष्ठं तिष्ठति पन्नगी आषाढे सर्पसंयोगादण्डानां मासि कार्तिके", text: "prāyeṇartumatī māsaṃ jyeṣṭhaṃ tiṣṭhati pannagī āṣāḍhe sarpasaṃyogādaṇḍānāṃ māsi kārtike" },
      { type: "verse", number: "15", sanskrit: "द्वेशते विंशती द्वे च सा सूते तत्र जायते कर्केतनसवर्णे ऽण्डे समुद्भिन्ने भुजङ्गमः", text: "dveśate viṃśatī dve ca sā sūte tatra jāyate karketanasavarṇe 'ṇḍe samudbhinne bhujaṅgamaḥ" },
      { type: "verse", number: "16", sanskrit: "दीर्घलोहितराजीभिश्चित्रे योषिन्नपुंसकम् शिरीषपुष्पसदृशे दंष्ट्राः सर्पस्य सप्तमे चतस्रः सम्भवन्त्यह्नि विषं तासु चतुर्दशे", text: "dīrghalohitarājībhiścitre yoṣinnapuṃsakam śirīṣapuṣpasadṛśe daṃṣṭrāḥ sarpasya saptame catasraḥ sambhavantyahni viṣaṃ tāsu caturdaśe" },
      { type: "verse", number: "17", sanskrit: "वामाधरासिता पीता तदूर्ध्वा दक्षिणात्वधः रक्ता श्यावोत्तरैकद्वित्रिचतुर्विषबिन्दुकाः", text: "vāmādharāsitā pītā tadūrdhvā dakṣiṇātvadhaḥ raktā śyāvottaraikadvitricaturviṣabindukāḥ" },
      { type: "verse", number: "18", sanskrit: "ताः क्रमान्मुद्गमात्रोत्रबिन्दुः एष हि भोगिनाम् विषे विकल्पो नान्येषां विद्यांद्दष्ट्रास्तथापराः चत्वारिंशद् भुजङ्गस्य विर्विषाश्चतुरुत्तराः", text: "tāḥ kramānmudgamātrotrabinduḥ eṣa hi bhoginām viṣe vikalpo nānyeṣāṃ vidyāṃddaṣṭrāstathāparāḥ catvāriṃśad bhujaṅgasya virviṣāścaturuttarāḥ" },
      { type: "verse", number: "19", sanskrit: "आयुर्वर्षशतं विंशं पञ्चवर्षशतायुषः गोनसा घर्मतप्तानां गवां नासासमुद्भवाः", text: "āyurvarṣaśataṃ viṃśaṃ pañcavarṣaśatāyuṣaḥ gonasā gharmataptānāṃ gavāṃ nāsāsamudbhavāḥ" },
      { type: "verse", number: "20", sanskrit: "तत्रोर्ध्वदृङ्महाकायनेत्रजिह्वाशिरःस्वरः व्यक्तभोगः पुनान्धीरः स्त्री स्यात्तस्माद्विपर्यये", text: "tatrordhvadṛṅmahākāyanetrajihvāśiraḥsvaraḥ vyaktabhogaḥ punāndhīraḥ strī syāttasmādviparyaye" },
      { type: "verse", number: "21", sanskrit: "आयता चपला क्लीबः सुकुमारो जडाकृतिः मन्दवेगस्वनक्रोधः सिताभस्तिर्यशीर्षकः", text: "āyatā capalā klībaḥ sukumāro jaḍākṛtiḥ mandavegasvanakrodhaḥ sitābhastiryaśīrṣakaḥ" },
      { type: "verse", number: "22", sanskrit: "दिनत्रियामासन्ध्यासु प्रबलास्ते यथाक्रमम् तदैव चापराध्यन्ति सर्वदैव तु पन्नगी", text: "dinatriyāmāsandhyāsu prabalāste yathākramam tadaiva cāparādhyanti sarvadaiva tu pannagī" },
      { type: "verse", number: "23", sanskrit: "ब्राह्मणाः क्रोधना नीलकपिलाः श्वेतलोहिताः रक्तास्याः पिङ्गनयना मेध्यदेशविचारिणः", text: "brāhmaṇāḥ krodhanā nīlakapilāḥ śvetalohitāḥ raktāsyāḥ piṅganayanā medhyadeśavicāriṇaḥ" },
      { type: "verse", number: "24", sanskrit: "भोगे यज्ञोपवीतादिद्विजचिह्नोपचिह्निताः बिल्वपुष्पहिमोशीरपद्मगुग्गुलुगन्धयः", text: "bhoge yajñopavītādidvijacihnopacihnitāḥ bilvapuṣpahimośīrapadmaguggulugandhayaḥ" },
      { type: "verse", number: "25", sanskrit: "क्षत्रिया मानिनो धीरा रक्ताक्षा भृशकोपनाः पक्वजाम्बवखर्जूरद्राक्षाभिन्नाञ्जनप्रभाः", text: "kṣatriyā mānino dhīrā raktākṣā bhṛśakopanāḥ pakvajāmbavakharjūradrākṣābhinnāñjanaprabhāḥ" },
      { type: "verse", number: "26", sanskrit: "भोगेर्द्ध चन्द्रश्रीवत्सशङ्खचक्रहलाङ्किताः जातीचम्पकपुन्नागपत्रजोङ्गकगन्धयः", text: "bhogerddha candraśrīvatsaśaṅkhacakrahalāṅkitāḥ jātīcampakapunnāgapatrajoṅgakagandhayaḥ" },
      { type: "verse", number: "27", sanskrit: "वैश्याः पारावताभासा वज्रगोमेदकप्रभाः बिन्दुमण्डलचित्राङ्गा धूम्रपाटललोहिताः बस्तकुष्ठविकक्षीरसर्पिषां गन्धतः समाः", text: "vaiśyāḥ pārāvatābhāsā vajragomedakaprabhāḥ bindumaṇḍalacitrāṅgā dhūmrapāṭalalohitāḥ bastakuṣṭhavikakṣīrasarpiṣāṃ gandhataḥ samāḥ" },
      { type: "verse", number: "28", sanskrit: "शूद्राः सवर्णा गोधूममहिषद्विपकर्दमैः बिन्दुरेखाचिता रूक्षाः सुराशोणितगन्धयः", text: "śūdrāḥ savarṇā godhūmamahiṣadvipakardamaiḥ bindurekhācitā rūkṣāḥ surāśoṇitagandhayaḥ" },
      { type: "verse", number: "29", sanskrit: "पूर्वमध्यापराह्णेषु चरन्ति ब्राह्मणादयः अस्तंगते रवौ शूद्राः दशन्ति ब्राह्मणाः पुरः संस्थिता दक्षिणे पार्श्वे क्षत्रिया वामतो विशः", text: "pūrvamadhyāparāhṇeṣu caranti brāhmaṇādayaḥ astaṃgate ravau śūdrāḥ daśanti brāhmaṇāḥ puraḥ saṃsthitā dakṣiṇe pārśve kṣatriyā vāmato viśaḥ" },
      { type: "verse", number: "30", sanskrit: "शूद्रास्तु पृष्ठतो विप्रास्त्रीनप्यनिलपूर्वकान् कोपयन्ति क्रमाद्दोषांस्त्रींस्त्रयः क्षत्रियादयः", text: "śūdrāstu pṛṣṭhato viprāstrīnapyanilapūrvakān kopayanti kramāddoṣāṃstrīṃstrayaḥ kṣatriyādayaḥ" },
      { type: "verse", number: "31", sanskrit: "दंशगन्धोङ्गगन्धेन ज्ञेयस्तेषां यथायथम्", text: "daṃśagandhoṅgagandhena jñeyasteṣāṃ yathāyatham" },
      { type: "verse", number: "32", sanskrit: "वायुमूषिकमण्डूकसर्वभक्षाः क्रमेण ते", text: "vāyumūṣikamaṇḍūkasarvabhakṣāḥ krameṇa te" },
      { type: "verse", number: "33", sanskrit: "आहारार्थं भयात् पादस्पर्शादतिविषात् क्रुधः पापवृत्ततया वैराद्देवर्षियमचोदनात् दशन्ति सर्पास्तेषूक्तं विषाधिक्यं यथोत्तरम्", text: "āhārārthaṃ bhayāt pādasparśādativiṣāt krudhaḥ pāpavṛttatayā vairāddevarṣiyamacodanāt daśanti sarpāsteṣūktaṃ viṣādhikyaṃ yathottaram" },
      { type: "verse", number: "34", sanskrit: "आविष्टात् कारणं ज्ञात्वा प्रतिकुर्याद्यथायथम्", text: "āviṣṭāt kāraṇaṃ jñātvā pratikuryādyathāyatham" },
      { type: "verse", number: "35", sanskrit: "व्यन्तरः पापशीलत्वान्मार्गमावृत्य तिष्ठति", text: "vyantaraḥ pāpaśīlatvānmārgamāvṛtya tiṣṭhati" },
      { type: "verse", number: "36", sanskrit: "यत्र लालापरिक्लेदमात्रं गात्रे प्रदृश्यते न तु दंष्ट्राकृतं दंशं तत्तुण्डाहतमादिशेत्", text: "yatra lālāparikledamātraṃ gātre pradṛśyate na tu daṃṣṭrākṛtaṃ daṃśaṃ tattuṇḍāhatamādiśet" },
      { type: "verse", number: "37", sanskrit: "एकं दंष्ट्रापदं द्वे वा व्यालीढाख्यमशोणितम् दंष्ट्रापदे सरक्ते द्वे व्यालुप्तं त्रीणि तानि तु", text: "ekaṃ daṃṣṭrāpadaṃ dve vā vyālīḍhākhyamaśoṇitam daṃṣṭrāpade sarakte dve vyāluptaṃ trīṇi tāni tu" },
      { type: "verse", number: "38", sanskrit: "मांसच्छेदादविच्छिन्नरक्तवाहीनि दष्टकम् दंष्ट्रापदानि चत्वारि तद्वद्दष्टनिपीडितम्", text: "māṃsacchedādavicchinnaraktavāhīni daṣṭakam daṃṣṭrāpadāni catvāri tadvaddaṣṭanipīḍitam" },
      { type: "verse", number: "39", sanskrit: "निर्विषं द्वयमत्राद्यमसाध्यं पश्चिमं वदेत्", text: "nirviṣaṃ dvayamatrādyamasādhyaṃ paścimaṃ vadet" },
      { type: "verse", number: "40", sanskrit: "विषं नाहेयमप्राप्य रक्तं दूषयते वपुः रक्तमण्वपि तु प्राप्तं वर्धते तैलबिन्दुवत्", text: "viṣaṃ nāheyamaprāpya raktaṃ dūṣayate vapuḥ raktamaṇvapi tu prāptaṃ vardhate tailabinduvat" },
      { type: "verse", number: "41", sanskrit: "भीरोः सर्पाङ्गसंस्पर्शाद् भयेन कुपितोनिलः कदाचित् कुरुते शोफं सर्पाङ्गाभिहतं तु तत्", text: "bhīroḥ sarpāṅgasaṃsparśād bhayena kupitonilaḥ kadācit kurute śophaṃ sarpāṅgābhihataṃ tu tat" },
      { type: "verse", number: "42", sanskrit: "दुर्गान्धकारे विद्धस्य केनचिद्दष्टशङ्कया विषोद्वेगो ज्वरश्छर्द्दिर्मूर्च्छा दाहोपि वा भवेत् ग्लानिर्मोहोतिसारो वा तच्छङ्काविषमुच्यते", text: "durgāndhakāre viddhasya kenaciddaṣṭaśaṅkayā viṣodvego jvaraścharddirmūrcchā dāhopi vā bhavet glānirmohotisāro vā tacchaṅkāviṣamucyate" },
      { type: "verse", number: "43", sanskrit: "दंआस्तु सविषः सर्वः सशोफो वेदनान्वितः तुद्यते ग्रथितः किञ्चित् कण्डूमान् दह्यते भृशम् निर्विषो विपरीतोस्मात् #", text: "daṃāstu saviṣaḥ sarvaḥ saśopho vedanānvitaḥ tudyate grathitaḥ kiñcit kaṇḍūmān dahyate bhṛśam nirviṣo viparītosmāt #" },
      { type: "verse", number: "44", sanskrit: "तत्र दंशः फणावताम् कूर्मपृष्ठोन्नतो रूक्षः सूक्ष्मदंष्ट्रापदान्वितः", text: "tatra daṃśaḥ phaṇāvatām kūrmapṛṣṭhonnato rūkṣaḥ sūkṣmadaṃṣṭrāpadānvitaḥ" },
      { type: "verse", number: "45", sanskrit: "विकाराः श्यावता वक्त्रनखमूत्राक्षिविट्त्वचाम् शीतज्वरः सन्धिरुजा निद्रानाशो विजृम्भिका", text: "vikārāḥ śyāvatā vaktranakhamūtrākṣiviṭtvacām śītajvaraḥ sandhirujā nidrānāśo vijṛmbhikā" },
      { type: "verse", number: "46", sanskrit: "मन्यास्तभ्भःसिराध्मानं पृष्ठकट्यस्थिवाग्ग्रहाः शिरोगुरुत्वमरुचिः कासश्वासौ हनुग्रहः", text: "manyāstabhbhaḥsirādhmānaṃ pṛṣṭhakaṭyasthivāggrahāḥ śirogurutvamaruciḥ kāsaśvāsau hanugrahaḥ" },
      { type: "verse", number: "47", sanskrit: "शूलमुद्वेष्टनं कोष्ठे शोषरोधौ मलाश्रयौ सन्दिग्धवाक्त्वं नैश्चेष्ट्यं मृतस्येव विसंज्ञता", text: "śūlamudveṣṭanaṃ koṣṭhe śoṣarodhau malāśrayau sandigdhavāktvaṃ naiśceṣṭyaṃ mṛtasyeva visaṃjñatā" },
      { type: "verse", number: "48", sanskrit: "फेनलालोद्गमौ हिध्मा कण्ठे घुरुघुरायणम् शुष्कोद्गारो मुहुस्ते ते वातजाश्चापरे गदाः", text: "phenalālodgamau hidhmā kaṇṭhe ghurughurāyaṇam śuṣkodgāro muhuste te vātajāścāpare gadāḥ" },
      { type: "verse", number: "49", sanskrit: "दंशो मण्डलिनां सोष्मा सशोषः पीतलोहितः पृथुर्विसर्पदाहोषाक्लेदकोथैर्विशीर्यते", text: "daṃśo maṇḍalināṃ soṣmā saśoṣaḥ pītalohitaḥ pṛthurvisarpadāhoṣākledakothairviśīryate" },
      { type: "verse", number: "50", sanskrit: "विकारा वक्त्रदन्तादिपीतता तृट्श्रमो भ्रमः दाहो मूर्च्छा ज्वरस्तिक्तवक्त्रत्वं पीतदर्शनम्", text: "vikārā vaktradantādipītatā tṛṭśramo bhramaḥ dāho mūrcchā jvarastiktavaktratvaṃ pītadarśanam" },
      { type: "verse", number: "51", sanskrit: "रक्तागमनमूर्ध्वाधःशीतेच्छा धूमको मदः आशुसर्वाङ्गविसृतिर्गदास्ते ते च पित्तजाः", text: "raktāgamanamūrdhvādhaḥśītecchā dhūmako madaḥ āśusarvāṅgavisṛtirgadāste te ca pittajāḥ" },
      { type: "verse", number: "52", sanskrit: "दंशो राजीमतां स्निग्धःस्थिरपिच्छिलशोफकृत् सान्द्रास्रःशिशिरः पाण्डुस्तद्विकाराःशिरोव्यथा", text: "daṃśo rājīmatāṃ snigdhaḥsthirapicchilaśophakṛt sāndrāsraḥśiśiraḥ pāṇḍustadvikārāḥśirovyathā" },
      { type: "verse", number: "53", sanskrit: "अरुचिश्छर्दिरालस्यं हृल्लासो मधुरास्यता कण्ठे घुरुघुरः पाको कण्डूरक्ष्णोर्हिमो ज्वरः", text: "aruciśchardirālasyaṃ hṛllāso madhurāsyatā kaṇṭhe ghurughuraḥ pāko kaṇḍūrakṣṇorhimo jvaraḥ" },
      { type: "verse", number: "54", sanskrit: "कृच्छ्रादुच्छ्रवसनं निद्रा कासः श्वेतनखादिता स्तम्भो गुरुत्वं चाङ्गानां नासिकाक्षिमुखस्रुतिः रोमहर्षस्तमश्वासो रोगाश्चान्ये कफोद्भवाः", text: "kṛcchrāducchravasanaṃ nidrā kāsaḥ śvetanakhāditā stambho gurutvaṃ cāṅgānāṃ nāsikākṣimukhasrutiḥ romaharṣastamaśvāso rogāścānye kaphodbhavāḥ" },
      { type: "verse", number: "55", sanskrit: "व्यन्तरे मिश्रलिङ्गत्वं दष्टः पुंसोर्ध्वमीक्षते प्रक्षिपेद्दक्षिणं पादं पूर्वकायसमुद्यतः", text: "vyantare miśraliṅgatvaṃ daṣṭaḥ puṃsordhvamīkṣate prakṣipeddakṣiṇaṃ pādaṃ pūrvakāyasamudyataḥ" },
      { type: "verse", number: "56", sanskrit: "धीरोल्पवेगः शर्वर्यां विपरीतस्तु योषिता हीनस्वरोतिसारार्तः कम्पते त्रस्यते ज्वरी", text: "dhīrolpavegaḥ śarvaryāṃ viparītastu yoṣitā hīnasvarotisārārtaḥ kampate trasyate jvarī" },
      { type: "verse", number: "57", sanskrit: "नपुंसकेन तिर्यग्दृगधीरः प्रियमैथुनः बहुवादी च वृद्धेन चिरान्मन्दाश्च वेदनाः", text: "napuṃsakena tiryagdṛgadhīraḥ priyamaithunaḥ bahuvādī ca vṛddhena cirānmandāśca vedanāḥ" },
      { type: "verse", number: "58", sanskrit: "बालेन शीघ्रं तीक्ष्णाश्च कुमारेणाक्ष्णि दक्षिणे रोगी कुमार्या वामे तु गर्भिण्या कृष्णजिह्वदृक्", text: "bālena śīghraṃ tīkṣṇāśca kumāreṇākṣṇi dakṣiṇe rogī kumāryā vāme tu garbhiṇyā kṛṣṇajihvadṛk" },
      { type: "verse", number: "59", sanskrit: "जृम्भा क्रोधोपजिह्वार्तः स शूनोष्ठः सिताननः गुरूदरः शिरोरोगी सूतादष्टस्तु मेहति शोणितं कृच्छ्रशूलार्तः सूचीभिरिव भिद्यते", text: "jṛmbhā krodhopajihvārtaḥ sa śūnoṣṭhaḥ sitānanaḥ gurūdaraḥ śirorogī sūtādaṣṭastu mehati śoṇitaṃ kṛcchraśūlārtaḥ sūcībhiriva bhidyate" },
      { type: "verse", number: "60", sanskrit: "वेगानां रक्तमांसाद्याः सप्तोक्ताः पूर्वमाश्रयाः", text: "vegānāṃ raktamāṃsādyāḥ saptoktāḥ pūrvamāśrayāḥ" },
      { type: "verse", number: "61", sanskrit: "दर्वीकृताथ दष्टस्य दुष्टं श्यावीभवत्यसृक् श्यावता तेन वक्त्रादौ सर्पन्तीव च कीटकाः", text: "darvīkṛtātha daṣṭasya duṣṭaṃ śyāvībhavatyasṛk śyāvatā tena vaktrādau sarpantīva ca kīṭakāḥ" },
      { type: "verse", number: "62", sanskrit: "द्वितीये ग्रन्थयो वेगे तृतीये मूर्द्धगौरवम् दृग्रोधो दंशविक्लेदश्चतुर्थे ष्ठीवनं वमिः", text: "dvitīye granthayo vege tṛtīye mūrddhagauravam dṛgrodho daṃśavikledaścaturthe ṣṭhīvanaṃ vamiḥ" },
      { type: "verse", number: "63", sanskrit: "सन्धिविश्लेषणं तन्द्रा पञ्चमे पर्वभेदनम् दाहो हिध्मा च षष्ठे तु हृत्पीडा गात्रगौरवम्", text: "sandhiviśleṣaṇaṃ tandrā pañcame parvabhedanam dāho hidhmā ca ṣaṣṭhe tu hṛtpīḍā gātragauravam" },
      { type: "verse", number: "64", sanskrit: "मूर्च्छाविपाको ऽतीसारः प्राप्य शुक्रन्तु सप्तमे स्कन्धपृष्ठकटीभङ्गः सर्वचेष्टानिवर्तनम्", text: "mūrcchāvipāko 'tīsāraḥ prāpya śukrantu saptame skandhapṛṣṭhakaṭībhaṅgaḥ sarvaceṣṭānivartanam" },
      { type: "verse", number: "65", sanskrit: "अथ मण्डलिदष्टस्य दुष्टं पीतीभवत्यसृक् तेन पीताङ्गता दाहो द्वितीये श्वयथूद्भवः", text: "atha maṇḍalidaṣṭasya duṣṭaṃ pītībhavatyasṛk tena pītāṅgatā dāho dvitīye śvayathūdbhavaḥ" },
      { type: "verse", number: "66", sanskrit: "तृतीये दंशविक्लेदः स्वेदस्तृष्णा च जायेते चतुर्थे ज्वर्यते दाहः पञ्चमे सर्वगात्रगः", text: "tṛtīye daṃśavikledaḥ svedastṛṣṇā ca jāyete caturthe jvaryate dāhaḥ pañcame sarvagātragaḥ" },
      { type: "verse", number: "67", sanskrit: "दज्टस्य राजिलैर्दुष्टं पाण्डुतां याति शोणितम् पाण्डुता तेन गात्राणां द्वितीये गुरुताति च", text: "dajṭasya rājilairduṣṭaṃ pāṇḍutāṃ yāti śoṇitam pāṇḍutā tena gātrāṇāṃ dvitīye gurutāti ca" },
      { type: "verse", number: "68", sanskrit: "तृतीये दंशविक्लेदनासिकाक्षिमुखस्रवाः चतुर्थे गरिमा मूर्ध्नो मन्यास्तम्भश्च पञ्चमे वाक्यसङ्गो ज्वरः शीतः शेषयोः पूर्ववद्वदेत्", text: "tṛtīye daṃśavikledanāsikākṣimukhasravāḥ caturthe garimā mūrdhno manyāstambhaśca pañcame vākyasaṅgo jvaraḥ śītaḥ śeṣayoḥ pūrvavadvadet" },
      { type: "verse", number: "69", sanskrit: "कुर्यात् पञ्चसु वेगेषु चिकित्सां न ततः परम्", text: "kuryāt pañcasu vegeṣu cikitsāṃ na tataḥ param" },
      { type: "verse", number: "70", sanskrit: "जलप्लुता रतिक्षीणा भीता नकुलनिर्जिताः शीतवातातपव्याधिक्षुत्तृष्णाश्रमपीडिताः", text: "jalaplutā ratikṣīṇā bhītā nakulanirjitāḥ śītavātātapavyādhikṣuttṛṣṇāśramapīḍitāḥ" },
      { type: "verse", number: "71", sanskrit: "तूर्णं देशान्तरायातां विमुक्तविषकञ्चुकाः कुशौषधीकण्टकवद्ये चरन्ति च काननम् देशं च विद्याध्युषितं सर्पास्तेल्पविषा मताः", text: "tūrṇaṃ deśāntarāyātāṃ vimuktaviṣakañcukāḥ kuśauṣadhīkaṇṭakavadye caranti ca kānanam deśaṃ ca vidyādhyuṣitaṃ sarpāstelpaviṣā matāḥ" },
      { type: "verse", number: "72", sanskrit: "श्मशानचैत्यवल्मीकयज्ञाश्रयसुरालये चतुष्पथे जलस्थाने जीर्णोद्यानेषु कोटरे", text: "śmaśānacaityavalmīkayajñāśrayasurālaye catuṣpathe jalasthāne jīrṇodyāneṣu koṭare" },
      { type: "verse", number: "73", sanskrit: "क्षीरिद्रुमे निम्बतरौ निर्झरे गिरिगह्वरे चक्रवज्रगदाकुन्तत्रिशूलाङ्कजटाधराः", text: "kṣīridrume nimbatarau nirjhare girigahvare cakravajragadākuntatriśūlāṅkajaṭādharāḥ" },
      { type: "verse", number: "74", sanskrit: "रक्तास्यनयना ये च ते स्युराशीविषोपमाः न तेषां कालनियमो न च वेगेष्वनुक्रमः", text: "raktāsyanayanā ye ca te syurāśīviṣopamāḥ na teṣāṃ kālaniyamo na ca vegeṣvanukramaḥ" },
      { type: "verse", number: "75", sanskrit: "मन्त्रतन्त्रबलान्नापि प्रसह्य विनिवर्तनम् उपहारनमस्कारजपशान्तिपरायणः कश्चिज्जीवति तैर्दष्टो विरूपो विकलो ऽपि वा", text: "mantratantrabalānnāpi prasahya vinivartanam upahāranamaskārajapaśāntiparāyaṇaḥ kaścijjīvati tairdaṣṭo virūpo vikalo 'pi vā" },
      { type: "verse", number: "76", sanskrit: "श्मशानचितिचैत्यादौ पञ्चमीपक्षसन्धिषु अष्टमीनवमीसन्ध्यामध्यरात्रिदिनेषु च", text: "śmaśānaciticaityādau pañcamīpakṣasandhiṣu aṣṭamīnavamīsandhyāmadhyarātridineṣu ca" },
      { type: "verse", number: "77", sanskrit: "याम्याग्नेयमघाश्लेषाविशाखापूर्वनैरृते नैरृताख्ये मुहूर्ते च दष्टं मर्मसु च त्यजेत्", text: "yāmyāgneyamaghāśleṣāviśākhāpūrvanairṛte nairṛtākhye muhūrte ca daṣṭaṃ marmasu ca tyajet" },
      { type: "verse", number: "78", sanskrit: "दष्टमात्रे सितास्याक्षः शीर्यमाणशिरोरुहः स्तब्धजिह्वो मुहुर्मूर्च्छन् शीतोच्छ्वासो न जीवति", text: "daṣṭamātre sitāsyākṣaḥ śīryamāṇaśiroruhaḥ stabdhajihvo muhurmūrcchan śītocchvāso na jīvati" },
      { type: "verse", number: "79", sanskrit: "हिध्मा श्वासो वमिः कासो दष्टमात्रस्य देहिनः जायते युगपद्यस्य स हृच्छूली न जीवति", text: "hidhmā śvāso vamiḥ kāso daṣṭamātrasya dehinaḥ jāyate yugapadyasya sa hṛcchūlī na jīvati" },
      { type: "verse", number: "80", sanskrit: "वेपथुर्वेदनास्तीव्रा ग्रीवाभङ्गोक्षिरक्तता मूर्च्छा गलग्रहश्छर्दिः प्रेतराजस्यकिङ्कराः", text: "vepathurvedanāstīvrā grīvābhaṅgokṣiraktatā mūrcchā galagrahaśchardiḥ pretarājasyakiṅkarāḥ" },
      { type: "verse", number: "81", sanskrit: "जाम्बवप्रतिमो दंशः कूर्मपृष्ठवदुन्नतः रक्तं खेभ्यः समस्तेभ्यो वर्तते न तु दंशतः", text: "jāmbavapratimo daṃśaḥ kūrmapṛṣṭhavadunnataḥ raktaṃ khebhyaḥ samastebhyo vartate na tu daṃśataḥ" },
      { type: "verse", number: "82", sanskrit: "रोम्णां न शीतलैर्हर्षः श्वयथुर्लोहितासितः हृष्टमेहनता वक्रवक्त्रत्वं यस्य तं त्यजेत्", text: "romṇāṃ na śītalairharṣaḥ śvayathurlohitāsitaḥ hṛṣṭamehanatā vakravaktratvaṃ yasya taṃ tyajet" },
      { type: "verse", number: "83", sanskrit: "फेनं वमति निस्संज्ञः श्यावपादकराननः नासावसादो भङ्गोङ्गे विड्भेदः श्लथसन्धिता", text: "phenaṃ vamati nissaṃjñaḥ śyāvapādakarānanaḥ nāsāvasādo bhaṅgoṅge viḍbhedaḥ ślathasandhitā" },
      { type: "verse", number: "84", sanskrit: "विषपीतस्य दष्टस्य दिग्धेनाभिहतस्य च भवन्त्येतानि रूपाणि सम्प्राप्ते जीवितक्षये", text: "viṣapītasya daṣṭasya digdhenābhihatasya ca bhavantyetāni rūpāṇi samprāpte jīvitakṣaye" },
      { type: "verse", number: "85", sanskrit: "न नस्यैश्चेतना तीक्ष्णैर्न क्षतात् क्षतजागमः दण्डाहतस्य नो राजिः प्रयातस्य यमान्तिकम्", text: "na nasyaiścetanā tīkṣṇairna kṣatāt kṣatajāgamaḥ daṇḍāhatasya no rājiḥ prayātasya yamāntikam" },
      { type: "verse", number: "86", sanskrit: "अतोन्यथा तु त्वरया प्रदीप्तागारवद् भिषक् रक्षन् कण्ठगतान् प्राणान् विषमाशु शमं नयेत्", text: "atonyathā tu tvarayā pradīptāgāravad bhiṣak rakṣan kaṇṭhagatān prāṇān viṣamāśu śamaṃ nayet" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 42,
    lang: "sa",
    content: [
      { type: "heading", heading: "Вришья тантра — мужское здоровье — введение" },
      { type: "text", text: "Глава 42 Уттара стханы — «Вришья тантра» — посвящена специализированному разделу: мужское здоровье — введение. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः सर्पविषप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयोमहर्षयः", text: "athātaḥ sarpaviṣapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayomaharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "मात्राशतं विषं स्थित्वा दंशे दष्टस्य देहिनः देहं प्रक्रमते धातून् रुधिरादीन् प्रदूषयत्", text: "mātrāśataṃ viṣaṃ sthitvā daṃśe daṣṭasya dehinaḥ dehaṃ prakramate dhātūn rudhirādīn pradūṣayat" },
      { type: "verse", number: "3", sanskrit: "एतस्मिन्नन्तरे कर्म दंशस्योत्कर्तनादिकम् कुर्याच्छीघ्रं यथा देहे विषवल्ली न रोहति", text: "etasminnantare karma daṃśasyotkartanādikam kuryācchīghraṃ yathā dehe viṣavallī na rohati" },
      { type: "verse", number: "4", sanskrit: "दष्टमात्रो दशेदाशु तमेव पवनाशिनम् लोष्टं महीं वा दशनैश्छित्वा वानु ससम्भ्रमम्", text: "daṣṭamātro daśedāśu tameva pavanāśinam loṣṭaṃ mahīṃ vā daśanaiśchitvā vānu sasambhramam" },
      { type: "verse", number: "5", sanskrit: "निष्ठीवेन समालिम्पेद्दंशं कर्णमलेन वा दंशस्योपरि बध्नीयादरिष्टां चतुरङ्गुले क्षौमादिभिर्वेणिकया सिद्धैर्मन्त्रैश्च मन्त्रवित्", text: "niṣṭhīvena samālimpeddaṃśaṃ karṇamalena vā daṃśasyopari badhnīyādariṣṭāṃ caturaṅgule kṣaumādibhirveṇikayā siddhairmantraiśca mantravit" },
      { type: "verse", number: "6", sanskrit: "बन्धो देशानुसारेण नातिगाढश्लथो हितः दंशपूतित्वशोफादीन् कुरुते ह्यतिपीडितः अशक्तः शिथिलो रोध्दुं विषं देशान्तरं व्रजत्", text: "bandho deśānusāreṇa nātigāḍhaślatho hitaḥ daṃśapūtitvaśophādīn kurute hyatipīḍitaḥ aśaktaḥ śithilo rodhduṃ viṣaṃ deśāntaraṃ vrajat" },
      { type: "verse", number: "7", sanskrit: "अम्बुवत् सेतुबन्धेन बन्धेन स्तभ्यते विषम् न वहन्ति सिराश्चास्य विषं बन्धाभिपीडिताः", text: "ambuvat setubandhena bandhena stabhyate viṣam na vahanti sirāścāsya viṣaṃ bandhābhipīḍitāḥ" },
      { type: "verse", number: "8", sanskrit: "निष्पीड्य चोद्धरेद्दंशं मर्मसन्ध्यगतं तथा न जायते विषावेगो बीजनाशादिवाङ्कुरः मर्मगे प्राप्नुयान्मृत्युं सन्धिस्थे विकलाङ्गताम्", text: "niṣpīḍya coddhareddaṃśaṃ marmasandhyagataṃ tathā na jāyate viṣāvego bījanāśādivāṅkuraḥ marmage prāpnuyānmṛtyuṃ sandhisthe vikalāṅgatām" },
      { type: "verse", number: "9", sanskrit: "दंशं मण्डलिनां मुक्त्वा पित्तलत्वादथापरम् प्रतप्तैर्हेमलोहाद्यैर्दहेदाशूल्मुकेन वा करोति भस्मसात् सद्यो वह्निः कि नाम न क्षणात्", text: "daṃśaṃ maṇḍalināṃ muktvā pittalatvādathāparam prataptairhemalohādyairdahedāśūlmukena vā karoti bhasmasāt sadyo vahniḥ ki nāma na kṣaṇāt" },
      { type: "verse", number: "10", sanskrit: "आचूषेत् पूर्णवक्त्रो वा मृद्भस्मागदगोमयैः प्रच्छायान्तररिष्टायां मांसलं तु विशेषतः", text: "ācūṣet pūrṇavaktro vā mṛdbhasmāgadagomayaiḥ pracchāyāntarariṣṭāyāṃ māṃsalaṃ tu viśeṣataḥ" },
      { type: "verse", number: "11", sanskrit: "अङ्गं सहैव दंशेन लेपयेदगदैर्मुहुः चन्दनोशीरयुक्तेन सलिलेन च सेचयेत्", text: "aṅgaṃ sahaiva daṃśena lepayedagadairmuhuḥ candanośīrayuktena salilena ca secayet" },
      { type: "verse", number: "12", sanskrit: "विषे प्रविसृते विध्येत् सिरां सा परमा क्रिया", text: "viṣe pravisṛte vidhyet sirāṃ sā paramā kriyā" },
      { type: "verse", number: "13", sanskrit: "रक्ते निर्द्द्रियमाणे हि कृत्स्नं निर्द्द्रियते विषम् दुष्टे हि व्याप्नुयादङ्गं ध्रुवं मृत्युर्भवत्यतः", text: "rakte nirddriyamāṇe hi kṛtsnaṃ nirddriyate viṣam duṣṭe hi vyāpnuyādaṅgaṃ dhruvaṃ mṛtyurbhavatyataḥ" },
      { type: "verse", number: "14", sanskrit: "सिराव्यधोदितैरस्रमप्रवृत्तं प्रवर्तयेत् स्तम्भयेदतिवृत्तं च तैरेव प्राणरक्षया", text: "sirāvyadhoditairasramapravṛttaṃ pravartayet stambhayedativṛttaṃ ca taireva prāṇarakṣayā" },
      { type: "verse", number: "15", sanskrit: "दुर्गन्धं सविषं रक्तमग्नौ चटचटायते यथादोषं विशुद्धं च पूर्ववल्लक्षयेदसृक्", text: "durgandhaṃ saviṣaṃ raktamagnau caṭacaṭāyate yathādoṣaṃ viśuddhaṃ ca pūrvavallakṣayedasṛk" },
      { type: "verse", number: "16", sanskrit: "सिरास्वदृश्यमानासु योज्याः शृङ्गजलौकसः", text: "sirāsvadṛśyamānāsu yojyāḥ śṛṅgajalaukasaḥ" },
      { type: "verse", number: "17", sanskrit: "शोणितं स्रुतशेषं च प्रविलीनं विषोष्मणा लेपसेकैः सुबहुशः स्तम्भयेद् भृशशीतलैः", text: "śoṇitaṃ srutaśeṣaṃ ca pravilīnaṃ viṣoṣmaṇā lepasekaiḥ subahuśaḥ stambhayed bhṛśaśītalaiḥ" },
      { type: "verse", number: "18", sanskrit: "अस्कन्ने विषवेगाद्धि मूर्च्छायमदहृद्द्रवाः भवन्ति तान् जयेच्छीतैर्वीजेच्चारोमहर्षतः", text: "askanne viṣavegāddhi mūrcchāyamadahṛddravāḥ bhavanti tān jayecchītairvījeccāromaharṣataḥ" },
      { type: "verse", number: "19", sanskrit: "विषं कर्षति तीक्ष्णत्वाद्धृदयं तस्य गुप्तये पिबेद् घृतं घृतक्षौद्रमगदं वा घृताप्लुतम्", text: "viṣaṃ karṣati tīkṣṇatvāddhṛdayaṃ tasya guptaye pibed ghṛtaṃ ghṛtakṣaudramagadaṃ vā ghṛtāplutam" },
      { type: "verse", number: "20", sanskrit: "मज्जानं गोमयरसं भस्माम्भः कृष्णमृज्जलम् ऐकध्यं पञ्चगव्यं वा दधि गैरिकवारि वा", text: "majjānaṃ gomayarasaṃ bhasmāmbhaḥ kṛṣṇamṛjjalam aikadhyaṃ pañcagavyaṃ vā dadhi gairikavāri vā" },
      { type: "verse", number: "21", sanskrit: "खादेद्वा कोविदारार्कशिरीषकटभीच्छदान् छागमेषवराहासृक्शिशुस्थविरयोषितः", text: "khādedvā kovidārārkaśirīṣakaṭabhīcchadān chāgameṣavarāhāsṛkśiśusthavirayoṣitaḥ" },
      { type: "verse", number: "22", sanskrit: "पिबेयुर्गर्भिणी शीतमधुरान् पयसा गदान् तथा मूर्च्छादयो न स्युर्विषं चाश्वेतिनानिलम्", text: "pibeyurgarbhiṇī śītamadhurān payasā gadān tathā mūrcchādayo na syurviṣaṃ cāśvetinānilam" },
      { type: "verse", number: "23", sanskrit: "हृदयावरणेनास्य श्लेष्मा हृद्युपचीयते प्रवृत्तगौरवोत्क्लेशहृल्लासं वामयेत्ततः", text: "hṛdayāvaraṇenāsya śleṣmā hṛdyupacīyate pravṛttagauravotkleśahṛllāsaṃ vāmayettataḥ" },
      { type: "verse", number: "24", sanskrit: "द्रवैः काञ्जिककौलत्थतैलमद्यादिवर्जितैः वमनैर्विषहृद्भिश्च नैवं व्याप्नोति तद्वपुः", text: "dravaiḥ kāñjikakaulatthatailamadyādivarjitaiḥ vamanairviṣahṛdbhiśca naivaṃ vyāpnoti tadvapuḥ" },
      { type: "verse", number: "25", sanskrit: "भुजङ्गदोषप्रकृतिस्थानवेगविशेषतः सुसूक्ष्मं सम्यगालोच्य विशिष्टां चाचरेत्क्रियाम्", text: "bhujaṅgadoṣaprakṛtisthānavegaviśeṣataḥ susūkṣmaṃ samyagālocya viśiṣṭāṃ cācaretkriyām" },
      { type: "verse", number: "26", sanskrit: "सिन्दुवारकमूलानि रसेन स्वेन पेषयेत् मधुयुक्तोयमगदः पानं दर्वीकृतां विषे", text: "sinduvārakamūlāni rasena svena peṣayet madhuyuktoyamagadaḥ pānaṃ darvīkṛtāṃ viṣe" },
      { type: "verse", number: "27", sanskrit: "सिन्दुवारकमूलानि श्वेता च गिरिकर्णिका पानं दर्वीकरैर्दष्टे नस्यं मधु सपाकलम्", text: "sinduvārakamūlāni śvetā ca girikarṇikā pānaṃ darvīkarairdaṣṭe nasyaṃ madhu sapākalam" },
      { type: "verse", number: "28", sanskrit: "कृष्णसर्पेण दष्टस्य लिम्पेद्दंशं हृते ऽसृजि चारटीनाकुलीभ्यां वा तीक्ष्णमूलविषेण वा", text: "kṛṣṇasarpeṇa daṣṭasya limpeddaṃśaṃ hṛte 'sṛji cāraṭīnākulībhyāṃ vā tīkṣṇamūlaviṣeṇa vā" },
      { type: "verse", number: "29", sanskrit: "पानं च क्षौद्रमञ्जिष्ठागृहधूमयुतं घृतम्", text: "pānaṃ ca kṣaudramañjiṣṭhāgṛhadhūmayutaṃ ghṛtam" },
      { type: "verse", number: "30", sanskrit: "तण्डुलीयककाश्मर्यकिणिहीगिरिकर्णिकाः मातुलुङ्गी सिता शेलुः पाननस्याञ्जने हितः अगदः फणिनां घोरे विषे राजीमतामपि", text: "taṇḍulīyakakāśmaryakiṇihīgirikarṇikāḥ mātuluṅgī sitā śeluḥ pānanasyāñjane hitaḥ agadaḥ phaṇināṃ ghore viṣe rājīmatāmapi" },
      { type: "verse", number: "31", sanskrit: "समाः सुगन्धामृद्वीकाश्वेताख्यागजकर्णिकाः अर्द्धांशं सौरसं पत्रं कपित्थं बिल्वदाडिमम् सक्षौद्रो मण्डलिविषे विशेषादगदो हितः", text: "samāḥ sugandhāmṛdvīkāśvetākhyāgajakarṇikāḥ arddhāṃśaṃ saurasaṃ patraṃ kapitthaṃ bilvadāḍimam sakṣaudro maṇḍaliviṣe viśeṣādagado hitaḥ" },
      { type: "verse", number: "32", sanskrit: "पञ्चवल्कवरायष्टी नागपुष्पैलवालुकम् जीवकर्षभकौ शीतं सिता पद्मकमुत्पलम्", text: "pañcavalkavarāyaṣṭī nāgapuṣpailavālukam jīvakarṣabhakau śītaṃ sitā padmakamutpalam" },
      { type: "verse", number: "33", sanskrit: "सक्षौद्रो हिमवान् नाम हन्ति मण्डलिनां विषम् लेपाच्छ्वयथुवीसर्पविस्फोटज्वरदाहहा", text: "sakṣaudro himavān nāma hanti maṇḍalināṃ viṣam lepācchvayathuvīsarpavisphoṭajvaradāhahā" },
      { type: "verse", number: "34", sanskrit: "काश्मर्यं वटशृङ्गाणि जीवकर्षभकौ सिताम् मञ्जिष्ठां मधुकं चेति दष्टो मण्डलिना पिबेत्", text: "kāśmaryaṃ vaṭaśṛṅgāṇi jīvakarṣabhakau sitām mañjiṣṭhāṃ madhukaṃ ceti daṣṭo maṇḍalinā pibet" },
      { type: "verse", number: "35", sanskrit: "वंशत्वग्बीजकटुका पाटलीबीजनागरम् शिरीषबीजातिविषे मूलं गावेधुकं वचाम् पिष्टो गोवारिणाष्टाङ्गो हन्ति गोनसजं विषम्", text: "vaṃśatvagbījakaṭukā pāṭalībījanāgaram śirīṣabījātiviṣe mūlaṃ gāvedhukaṃ vacām piṣṭo govāriṇāṣṭāṅgo hanti gonasajaṃ viṣam" },
      { type: "verse", number: "36", sanskrit: "कटुकातिविषाकुष्ठगृहधूमहरेणुकाः सक्षौद्रव्योषतगरा घ्नन्ति राजमितां विषम्", text: "kaṭukātiviṣākuṣṭhagṛhadhūmahareṇukāḥ sakṣaudravyoṣAtagarā ghnanti rājamitāṃ viṣam" },
      { type: "verse", number: "37", sanskrit: "निखनेत्काण्डचित्राया दंशं यामद्वयं भुवि उद्धृत्य प्रच्छितं सर्पिर्द्धान्यमृद्भ्यां प्रलेपयेत्", text: "nikhanetkāṇḍacitrāyā daṃśaṃ yāmadvayaṃ bhuvi uddhṛtya pracchitaṃ sarpirddhānyamṛdbhyāṃ pralepayet" },
      { type: "verse", number: "38", sanskrit: "पिबेत् पुराणं च घृतं वराचूर्णावचूर्णितम् जीर्णे विरिक्तो भुञ्जीत यवान्नं सूपसंस्कृतम्", text: "pibet purāṇaṃ ca ghṛtaṃ varācūrṇāvacūrṇitam jīrṇe virikto bhuñjīta yavānnaṃ sūpasaṃskṛtam" },
      { type: "verse", number: "39", sanskrit: "करवीरार्ककुसुममूललाङ्गलिका कणाः कल्कयेदारनालेन पाठामरिचसंयुताः एष व्यन्तरदष्टानामगदः सार्वकार्मिकः", text: "karavīrārkakusumamūlalāṅgalikā kaṇāḥ kalkayedāranālena pāṭhāmaricasaṃyutāḥ eṣa vyantaradaṣṭānāmagadaḥ sārvakārmikaḥ" },
      { type: "verse", number: "40", sanskrit: "शिरीषपुष्पस्वरसे सप्ताहं मरिचं सितम् भावितं सर्पदष्टानां पाननस्याञ्जने हितम्", text: "śirīṣapuṣpasvarase saptāhaṃ maricaṃ sitam bhāvitaṃ sarpadaṣṭānāṃ pānanasyāñjane hitam" },
      { type: "verse", number: "41", sanskrit: "द्विपलं वक्रकुष्ठाभ्यां घृतक्षौद्रं चतुष्पलम् अपि तक्षकदष्टानां पानमेतत् सुखप्रदम्", text: "dvipalaṃ vakrakuṣṭhābhyāṃ ghṛtakṣaudraṃ catuṣpalam api takṣakadaṣṭānāṃ pānametat sukhapradam" },
      { type: "verse", number: "42", sanskrit: "गृहधूमं हरिद्रे द्वे समूलं तण्डुलीयकम् अपि वासुकिना दष्टः पिबेन्मधुघृताप्लुतम्", text: "gṛhadhūmaṃ haridre dve samūlaṃ taṇḍulīyakam api vāsukinā daṣṭaḥ pibenmadhughṛtāplutam" },
      { type: "verse", number: "43", sanskrit: "रक्तं मांसं च गोधायाः शुष्कं चूर्णीकृतं हितम् विषे रसगते पानं कपित्थरससंयुतम्", text: "raktaṃ māṃsaṃ ca godhāyāḥ śuṣkaṃ cūrṇīkṛtaṃ hitam viṣe rasagate pānaṃ kapittharasasaṃyutam" },
      { type: "verse", number: "44", sanskrit: "शेलुमूलत्वगग्राणि बादरोदुम्बराणि च कटभ्याश्च पिबेद्रक्तगते मांसगते पुनः", text: "śelumūlatvagagrāṇi bādarodumbarāṇi ca kaṭabhyāśca pibedraktagate māṃsagate punaḥ" },
      { type: "verse", number: "45", sanskrit: "सक्षौद्रं खादिरारिष्टकौटजं मूलमम्भसा सर्वेष्वपि बलायुग्मं मधुकं मदनं नतम्", text: "sakṣaudraṃ khādirāriṣṭakauṭajaṃ mūlamambhasā sarveṣvapi balāyugmaṃ madhukaṃ madanaṃ natam" },
      { type: "verse", number: "46", sanskrit: "शिरोगते विषे मूलं नस्यकर्मणि योजयेत् बन्धुजीवस्य भाङ्र्ग्याश्च सुरसस्यासितस्य च", text: "śirogate viṣe mūlaṃ nasyakarmaṇi yojayet bandhujīvasya bhāṅrgyāśca surasasyāsitasya ca" },
      { type: "verse", number: "47", sanskrit: "अथवा पिप्पलीहिङ्गुवृश्चिकालीमनश्शिलाः शिरीषबीजापामार्गलवणं चेतनाकरम् कल्कश्रूर्णोथवा कृष्णाक्षवकातिविषोषणात्", text: "athavā pippalīhiṅguvṛścikālīmanaśśilāḥ śirīṣabījāpāmārgalavaṇaṃ cetanākaram kalkaśrūrṇothavā kṛṣṇākṣavakātiviṣoṣaṇāt" },
      { type: "verse", number: "48", sanskrit: "पिप्पली मरिचक्षारवचासैन्धवशिग्रुकाः पिष्टा रोहितपित्तेन घ्नन्त्यक्षिगतमञ्जनात्", text: "pippalī maricakṣāravacāsaindhavaśigrukāḥ piṣṭā rohitapittena ghnantyakṣigatamañjanāt" },
      { type: "verse", number: "49", sanskrit: "चन्दनं मधुकं मांसी पिप्पलीमरिचोत्पलम् सैन्धवं चाञ्जनं श्रेष्ठं गवां पित्तेन कल्कितम्", text: "candanaṃ madhukaṃ māṃsī pippalīmaricotpalam saindhavaṃ cāñjanaṃ śreṣṭhaṃ gavāṃ pittena kalkitam" },
      { type: "verse", number: "50", sanskrit: "नक्तमालफलं व्योषं बिल्बमूलं निशाद्वयम् पुष्पं च सौरासं पिष्टमञ्जनं बस्तवारिणा भोजवैतरणोद्दिष्टं विषसुप्तप्रबोधनम्", text: "naktamālaphalaṃ vyoṣaṃ bilbamūlaṃ niśādvayam puṣpaṃ ca saurāsaṃ piṣṭamañjanaṃ bastavāriṇā bhojavaitaraṇoddiṣṭaṃ viṣasuptaprabodhanam" },
      { type: "verse", number: "51", sanskrit: "वारिगुञ्जाफलोशीरं नेत्रयोर्विषदुष्टयोः अञ्जनं वारिणा पिष्टं गारुडं गरुडोपमम्", text: "vāriguñjāphalośīraṃ netrayorviṣaduṣṭayoḥ añjanaṃ vāriṇā piṣṭaṃ gāruḍaṃ garuḍopamam" },
      { type: "verse", number: "52", sanskrit: "समुद्रफेनं मरिचं कणासौवीरकाञ्जम् चूर्णाञ्जनं ससिन्धूत्थं विषोपहतचक्षुषाम्", text: "samudraphenaṃ maricaṃ kaṇāsauvīrakāñjam cūrṇāñjanaṃ sasindhūtthaṃ viṣopahatacakṣuṣām" },
      { type: "verse", number: "53", sanskrit: "कपित्थमांसं ससिताक्षौद्रं कण्ठगते विषे लिह्यादामाशयगते ताभ्यां चूर्णपलं नतात्", text: "kapitthamāṃsaṃ sasitākṣaudraṃ kaṇṭhagate viṣe lihyādāmāśayagate tābhyāṃ cūrṇapalaṃ natāt" },
      { type: "verse", number: "54", sanskrit: "विषे पक्वाशयगते मञ्जिष्ठारजनीद्वयम् पिप्पलीं च समं पिष्ट्वा गव्यपित्तेन पाययेत्", text: "viṣe pakvāśayagate mañjiṣṭhārajanīdvayam pippalīṃ ca samaṃ piṣṭvā gavyapittena pāyayet" },
      { type: "verse", number: "55", sanskrit: "पिप्पलीनागरक्षारं नवनीतेन मूर्च्छितम् प्रवृद्धे कण्ठगे दद्याच्छ्लेष्मणि प्रतिसारणम्", text: "pippalīnāgarakṣāraṃ navanītena mūrcchitam pravṛddhe kaṇṭhage dadyācchleṣmaṇi pratisāraṇam" },
      { type: "verse", number: "56", sanskrit: "जयेत् सङ्क्रामणैराशु विषं शिरसि संश्रितम् दद्यादधस्ताद्दष्टस्य मूर्ध्नि काकपदे कृते", text: "jayet saṅkrāmaṇairāśu viṣaṃ śirasi saṃśritam dadyādadhastāddaṣṭasya mūrdhni kākapade kṛte" },
      { type: "verse", number: "57", sanskrit: "काकदक्षशिखिच्छागगव्यमाहिषकौक्कुटम् बिल्वप्रमाणं मांसास्नमूर्ध्वदष्टस्य पादयोः विषं सङ्क्रमते तत्र निहन्याच्छीघ्रमन्यथा", text: "kākadakṣaśikhicchāgagavyamāhiṣakaukkuṭam bilvapramāṇaṃ māṃsāsnamūrdhvadaṣṭasya pādayoḥ viṣaṃ saṅkramate tatra nihanyācchīghramanyathā" },
      { type: "verse", number: "58", sanskrit: "तीक्ष्णनस्याञ्जनान्ते च भूरिमात्रं पिबेत् घृतम् विषं हि नेत्रं रूक्षस्य तीक्ष्णैर्हन्ति समीरितम्", text: "tīkṣṇanasyāñjanānte ca bhūrimātraṃ pibet ghṛtam viṣaṃ hi netraṃ rūkṣasya tīkṣṇairhanti samīritam" },
      { type: "verse", number: "59", sanskrit: "वामयेत ततश्चैनं विषशेषोपशान्तये श्लेष्मलं श्लेष्मलैर्दष्टं नाभेरूर्ध्वं विशेषतः", text: "vāmayeta tataścainaṃ viṣaśeṣopaśāntaye śleṣmalaṃ śleṣmalairdaṣṭaṃ nābherūrdhvaṃ viśeṣataḥ" },
      { type: "verse", number: "60", sanskrit: "धामार्गवः शक्रयवाः सर्षपा मदनं मधु सैन्धवं वमनं कोष्णं विषे श्लेष्माश्रयश्रिते", text: "dhāmārgavaḥ śakrayavāḥ sarṣapā madanaṃ madhu saindhavaṃ vamanaṃ koṣṇaṃ viṣe śleṣmāśrayaśrite" },
      { type: "verse", number: "61", sanskrit: "सुरसं सर्पवेतालीमीश्वरां गौरसर्षपम् पटोलनिम्बपत्रं च पिबेत् सक्षौद्रसैन्धवम्", text: "surasaṃ sarpavetālīmīśvarāṃ gaurasarṣapam paṭolanimbapatraṃ ca pibet sakṣaudrasaindhavam" },
      { type: "verse", number: "62", sanskrit: "शुकाह्वाजालिनीदन्तीमदनेक्ष्वाकुकौटजम् काला लाङ्गलिका तिक्ता वमनं तण्डुलांबुना", text: "śukāhvājālinīdantīmadanekṣvākukauṭajam kālā lāṅgalikā tiktā vamanaṃ taṇḍulāṃbunā" },
      { type: "verse", number: "63", sanskrit: "पैत्तिकं पैत्तिकैर्दष्टमधो नाभेर्विशेषतः विषे पित्ताशयगते पाययेत विरेचनम्", text: "paittikaṃ paittikairdaṣṭamadho nābherviśeṣataḥ viṣe pittāśayagate pāyayeta virecanam" },
      { type: "verse", number: "64", sanskrit: "सनीलीफलदां दन्तीं पयसा मस्तुनाथवा श्लक्ष्णचूर्णीकृतं कुम्भं क्वाथेन त्रैफलेन वा क्षीरेण वा त्रिवृच्छ्यामासुरसानीलिनीरजः", text: "sanīlīphaladāṃ dantīṃ payasā mastunāthavā ślakṣṇacūrṇīkṛtaṃ kumbhaṃ kvāthena traiphalena vā kṣīreṇa vā trivṛcchyāmāsurasānīlinīrajaḥ" },
      { type: "verse", number: "65", sanskrit: "पिण्डीतकफलं व्योषं त्रिवृद्वेल्लं हरीतकी विरेचनं कफप्राये लवणं मूत्रसम्प्लुतम्", text: "piṇḍītakaphalaṃ vyoṣaṃ trivṛdvellaṃ harītakī virecanaṃ kaphaprāye lavaṇaṃ mūtrasamplutam" },
      { type: "verse", number: "66", sanskrit: "घृताप्लुतं सलवणं मारुते नीलिनीफलम्", text: "ghṛtāplutaṃ salavaṇaṃ mārute nīlinīphalam" },
      { type: "verse", number: "67", sanskrit: "शयानः शयने छिद्रे विरेच्यो विषपीडितः मुहुरुत्तिष्ठतो ह्यस्य विषं दूषयतेनिलम् पिबेद्वान्तो विरिक्तो वा यवागूं विषनाशिनीम्", text: "śayānaḥ śayane chidre virecyo viṣapīḍitaḥ muhuruttiṣṭhato hyasya viṣaṃ dūṣayatenilam pibedvānto virikto vā yavāgūṃ viṣanāśinīm" },
      { type: "verse", number: "68", sanskrit: "विषे वाताशयगते सर्पिषः पानमिष्यते आद्यपश्चिमयोर्यच्च प्रोक्तं विषनिषेधयोः", text: "viṣe vātāśayagate sarpiṣaḥ pānamiṣyate ādyapaścimayoryacca proktaṃ viṣaniṣedhayoḥ" },
      { type: "verse", number: "69", sanskrit: "अथ दर्वीकृतां वेगे पूर्वे विस्राव्य शोणितम् अगदं मधुसर्पिर्भ्यां संयुक्तं त्वरितं पिबेत्", text: "atha darvīkṛtāṃ vege pūrve visrāvya śoṇitam agadaṃ madhusarpirbhyāṃ saṃyuktaṃ tvaritaṃ pibet" },
      { type: "verse", number: "70", sanskrit: "द्वितीये वमनं कृत्वा तद्वदेवागदं पिबेत् विषापहे प्रयुञ्जीत तृतीयेञ्जननावने", text: "dvitīye vamanaṃ kṛtvā tadvadevāgadaṃ pibet viṣāpahe prayuñjīta tṛtīyeñjananāvane" },
      { type: "verse", number: "71", sanskrit: "पिबेच्चतुर्थे पूर्वोक्तां यवागूं वमने कृते षष्ठपञ्चमयोः शीतैर्दिग्धसिक्तमभीक्ष्णशः", text: "pibeccaturthe pūrvoktāṃ yavāgūṃ vamane kṛte ṣaṣṭhapañcamayoḥ śītairdigdhasiktamabhīkṣṇaśaḥ" },
      { type: "verse", number: "72", sanskrit: "पाययेद्वमनं तीक्ष्णं यगागूं यथोदिताम् अगदं सप्तमे तीक्ष्णं युञ्ज्यादञ्जननस्ययोः", text: "pāyayedvamanaṃ tīkṣṇaṃ yagāgūṃ yathoditām agadaṃ saptame tīkṣṇaṃ yuñjyādañjananasyayoḥ" },
      { type: "verse", number: "73", sanskrit: "कृत्वावगाढं शस्त्रेण मूर्ध्नि काकपदं ततः मांसं सरुधिरं तस्य चर्म वा तत्र निक्षिपेत्", text: "kṛtvāvagāḍhaṃ śastreṇa mūrdhni kākapadaṃ tataḥ māṃsaṃ sarudhiraṃ tasya carma vā tatra nikṣipet" },
      { type: "verse", number: "74", sanskrit: "तृतीये वामितः पेयां वेगे मण्डलिनां पिबेत् अतीक्ष्णमगदं षष्ठे गणं वा पद्मकादिकम्", text: "tṛtīye vāmitaḥ peyāṃ vege maṇḍalināṃ pibet atīkṣṇamagadaṃ ṣaṣṭhe gaṇaṃ vā padmakādikam" },
      { type: "verse", number: "75", sanskrit: "आद्येवगाढं प्रच्छाय वेगे दष्टस्य राजिलैः अलाबुना हरेद्रक्तं पूर्ववच्चाअगदं पिबेत्", text: "ādyevagāḍhaṃ pracchāya vege daṣṭasya rājilaiḥ alābunā haredraktaṃ pūrvavaccāagadaṃ pibet" },
      { type: "verse", number: "76", sanskrit: "षष्ठे वेगेञ्जनं तीक्ष्णमवपीडं च योजयेत् अनुक्तेषु च वेगेषु क्रियां दर्वीकरोदिताम्", text: "ṣaṣṭhe vegeñjanaṃ tīkṣṇamavapīḍaṃ ca yojayet anukteṣu ca vegeṣu kriyāṃ darvīkaroditām" },
      { type: "verse", number: "77", sanskrit: "गर्भिणीबालवृद्धेषु मृदु विध्येत् सिराञ्च न", text: "garbhiṇībālavṛddheṣu mṛdu vidhyet sirāñca na" },
      { type: "verse", number: "78", sanskrit: "त्वङ्मनोह्वा निशे वक्रं रसः शार्दूलजो नखः तमालः केसरं शीतं पीतं तण्डुलवारिणा हन्ति सर्वविषाण्येतद्वज्रं वज्रमिवासुरान्", text: "tvaṅmanohvā niśe vakraṃ rasaḥ śārdūlajo nakhaḥ tamālaḥ kesaraṃ śītaṃ pītaṃ taṇḍulavāriṇā hanti sarvaviṣāṇyetadvajraṃ vajramivāsurān" },
      { type: "verse", number: "79", sanskrit: "प्रपौण्डरीकं कटुका देवदारुसुवर्चिका कालानुसारी स्थौणेयशैलेयघनपद्मकम्", text: "prapauṇḍarīkaṃ kaṭukā devadārusuvarcikā kālānusārī sthauṇeyaśaileyaghanapadmakam" },
      { type: "verse", number: "80", sanskrit: "कुटन्नेटलापुन्नागनतकुष्ठीप्रयङ्गुकम् लोध्रगुग्गुलुतालीसपिप्पलीस्वर्णगैरिकम्", text: "kuṭanneṭalāpunnāganatakuṣṭhīprayaṅgukam lodhraguggulutālīsapippalīsvarṇagairikam" },
      { type: "verse", number: "81", sanskrit: "सिन्दुवारः सितः शुण्ठी ध्यामकं लवणोत्तमम् श्लक्ष्णचूर्णीकृतं शृङ्गे निदध्यान्माक्षिकद्रुतम्", text: "sinduvāraḥ sitaḥ śuṇṭhī dhyāmakaṃ lavaṇottamam ślakṣṇacūrṇīkṛtaṃ śṛṅge nidadhyānmākṣikadrutam" },
      { type: "verse", number: "82", sanskrit: "तार्क्ष्यस्तार्क्ष्योपमः पाननावनाभ्यञ्जनाञ्जनैः अगदस्तक्षकस्यापि विषवेगं निवर्तयेत्", text: "tārkṣyastārkṣyopamaḥ pānanāvanābhyañjanāñjanaiḥ agadastakṣakasyāpi viṣavegaṃ nivartayet" },
      { type: "verse", number: "83", sanskrit: "लोध्रं शिरीषषुष्पाणि समङ्गा हिङ्गु रेणुकाः कणोषणैलानेपाली वचा यष्टी मधूत्पलम्", text: "lodhraṃ śirīṣaṣuṣpāṇi samaṅgā hiṅgu reṇukāḥ kaṇoṣaṇailānepālī vacā yaṣṭī madhūtpalam" },
      { type: "verse", number: "84", sanskrit: "सिन्दुवारकमन्दारमूलं बीजं करञ्जजम् ज्योतिष्मती नतं कुष्ठं श्वेता च गिरिकर्णिका", text: "sinduvārakamandāramūlaṃ bījaṃ karañjajam jyotiṣmatī nataṃ kuṣṭhaṃ śvetā ca girikarṇikā" },
      { type: "verse", number: "85", sanskrit: "चूर्णितः कन्यया क्षौद्रगोपित्ताभ्यां च वर्तितः अगदो हन्ति सर्पाखुकणभं च सृगालजम्", text: "cūrṇitaḥ kanyayā kṣaudragopittābhyāṃ ca vartitaḥ agado hanti sarpākhukaṇabhaṃ ca sṛgālajam" },
      { type: "verse", number: "86", sanskrit: "बिडालकाण्डचित्रोत्थं विषं भूतग्रहं ज्वरम् अपस्मारग्रहोन्मादगुल्माजीर्णं विषूचिकाम्", text: "biḍālakāṇḍacitrotthaṃ viṣaṃ bhūtagrahaṃ jvaram apasmāragrahonmādagulmājīrṇaṃ viṣūcikām" },
      { type: "verse", number: "87", sanskrit: "बिल्वस्य मूलं सुरसस्य पुष्पं फलं करञ्जस्य नतं सुराह्वम् फलत्रयं व्योषनिशाद्वयं च बस्तस्य मूत्रेण सुसूक्ष्मपिष्टम्", text: "bilvasya mūlaṃ surasasya puṣpaṃ phalaṃ karañjasya nataṃ surāhvam phalatrayaṃ vyoṣaniśādvayaṃ ca bastasya mūtreṇa susūkṣmapiṣṭam" },
      { type: "verse", number: "88", sanskrit: "भुजङ्गलूतोन्दुरुवृश्चिकाद्यैर्विषूचिकाजीर्णगाज्वरैश्च आर्त्तान् नरान् भूतविधर्षितांश्च स्वस्थीकरोत्यञ्जनपाननस्यैः", text: "bhujaṅgalūtonduruvṛścikādyairviṣūcikājīrṇagājvaraiśca ārttān narān bhūtavidharṣitāṃśca svasthīkarotyañjanapānanasyaiḥ" },
      { type: "verse", number: "89", sanskrit: "त्रिवृद्विशल्या मधुकं निशे लवणपञ्चकम् मंजिष्ठा त्र्यूषणं तद्वत् कल्कयेत् स महागदः", text: "trivṛdviśalyā madhukaṃ niśe lavaṇapañcakam maṃjiṣṭhā tryūṣaṇaṃ tadvat kalkayet sa mahāgadaḥ" },
      { type: "verse", number: "90", sanskrit: "मांसीहरेणुत्रिफला मुरुङ्गी मधुयष्टिका मंजिष्टा पद्मकाशोककुष्ठतालीसचन्दनम्", text: "māṃsīhareṇutriphalā muruṅgī madhuyaṣṭikā maṃjiṣṭā padmakāśokakuṣṭhatālīsacandanam" },
      { type: "verse", number: "91", sanskrit: "सुगन्धिकैला किणिही त्वक्पटोली मृगादिनी भार्ङ्गी विडङ्गं पालिन्दी पाठा क्रोष्टुकमेखला", text: "sugandhikailā kiṇihī tvakpaṭolī mṛgādinī bhārṅgī viḍaṅgaṃ pālindī pāṭhā kroṣṭukamekhalā" },
      { type: "verse", number: "92", sanskrit: "पुष्पमारुष्करं पत्रं सौरसं क्रमुकं पुरम् पित्तं नकुलमार्जारगोधाशल्यकसूकरात्", text: "puṣpamāruṣkaraṃ patraṃ saurasaṃ kramukaṃ puram pittaṃ nakulamārjāragodhāśalyakasūkarāt" },
      { type: "verse", number: "93", sanskrit: "पृषताच्चित्रपत्राच्च गोशृङ्गे पूर्ववत् स्थितः यत्र गेहे न तत्राहिकीटादिभ्यो भयोद्भवः", text: "pṛṣatāccitrapatrācca gośṛṅge pūrvavat sthitaḥ yatra gehe na tatrāhikīṭādibhyo bhayodbhavaḥ" },
      { type: "verse", number: "94", sanskrit: "एतेन भेरीपटहाः पताकाश्च प्रलेपिताः आर्षभेण विषं घ्नन्ति स्पर्शश्रवणदर्शनैः", text: "etena bherīpaṭahāḥ patākāśca pralepitāḥ ārṣabheṇa viṣaṃ ghnanti sparśaśravaṇadarśanaiḥ" },
      { type: "verse", number: "95", sanskrit: "प्रलेपाद्यैश्च निश्शेषं दंशादप्युद्धरेद्विषम् भूयो वेगाय जायेत शेषं दूषीविषाय वा", text: "pralepādyaiśca niśśeṣaṃ daṃśādapyuddharedviṣam bhūyo vegāya jāyeta śeṣaṃ dūṣīviṣāya vā" },
      { type: "verse", number: "96", sanskrit: "विषापायेनिलं क्रुद्धं स्नेहादिभिरुपाचरेत् तैलमद्यकुलत्थाम्लवर्ज्यैः पवननाशनैः", text: "viṣāpāyenilaṃ kruddhaṃ snehādibhirupācaret tailamadyakulatthāmlavarjyaiḥ pavananāśanaiḥ" },
      { type: "verse", number: "97", sanskrit: "पित्तं पित्तज्वरहरैः कषायस्नेहबस्तिभिः", text: "pittaṃ pittajvaraharaiḥ kaṣāyasnehabastibhiḥ" },
      { type: "verse", number: "98", sanskrit: "समाक्षिकेण वर्गेण कफमारग्वधादिना", text: "samākṣikeṇa vargeṇa kaphamāragvadhādinā" },
      { type: "verse", number: "99", sanskrit: "सिता वैगन्धिको द्राक्षा पयस्या मधुकं मधु पानं समन्त्रपूताम्बुप्रोक्षणं सान्त्वहर्षणम् सर्पाङ्गाभिहते युञ्ज्यात्तथा शङ्काविषार्दिते", text: "sitā vaigandhiko drākṣā payasyā madhukaṃ madhu pānaṃ samantrapūtāmbuprokṣaṇaṃ sāntvaharṣaṇam sarpāṅgābhihate yuñjyāttathā śaṅkāviṣārdite" },
      { type: "verse", number: "100", sanskrit: "पूतनोप्रतकूष्माण्डपिशाचाद्या नरद्विषः हन्युरौषधवीर्याणि रक्षाकर्मण्यवारिताः तस्माद्रक्षां प्रयुञ्जीत रक्षोगणनिवारिणीम्", text: "pūtanopratakūṣmāṇḍapiśācādyā naradviṣaḥ hanyurauṣadhavīryāṇi rakṣākarmaṇyavāritāḥ tasmādrakṣāṃ prayuñjīta rakṣogaṇanivāriṇīm" },
      { type: "verse", number: "101", sanskrit: "गोमयेन सुसम्मृष्टे धूपागरुसुधूपिते गन्धमाल्योपहाराद्यैर्गृहे पूजितदैवते", text: "gomayena susammṛṣṭe dhūpāgarusudhūpite gandhamālyopahārādyairgṛhe pūjitadaivate" },
      { type: "verse", number: "102", sanskrit: "सूत्रकारान् समभ्यर्च्य शङ्करास्तिककाश्यपान् सन्तर्प्य हव्यकव्याभ्यां समिद्धाननलद्विजान्", text: "sūtrakārān samabhyarcya śaṅkarāstikakāśyapān santarpya havyakavyābhyāṃ samiddhānanaladvijān" },
      { type: "verse", number: "103", sanskrit: "प्राङ्मुखायोपविष्टाय विषार्ताय चिकित्सकः उत्तराभिमुखो युञ्ज्याद्विद्यां मन्त्राणि भेषजम्", text: "prāṅmukhāyopaviṣṭāya viṣārtāya cikitsakaḥ uttarābhimukho yuñjyādvidyāṃ mantrāṇi bheṣajam" },
      { type: "verse", number: "104", sanskrit: "समप्रमाणैर्हरितैर्दर्भैः प्रागभिमन्त्रितैः अच्छिन्नाग्रैः समूलैश्च कुर्यात्तस्यापमार्जनम्", text: "samapramāṇairharitairdarbhaiḥ prāgabhimantritaiḥ acchinnāgraiḥ samūlaiśca kuryāttasyāpamārjanam" },
      { type: "verse", number: "105", sanskrit: "ब्राह्माद्यै रगदैरेनं नित्यमेवानुलेपयेत् सञ्जीवनादीन् पानादौ दंशलेपे च योजयेत्", text: "brāhmādyai ragadairenaṃ nityamevānulepayet sañjīvanādīn pānādau daṃśalepe ca yojayet" },
      { type: "verse", number: "106", sanskrit: "पूर्णकुम्भं सकुसुमं सर्षपान् छागलं पयः शस्त्रं दूर्वां मधु घृतं कुर्याद्दष्टस्य मूर्द्धतः एवं शाम्यति सप्ताहाद्विषमात्मवतः सतः", text: "pūrṇakumbhaṃ sakusumaṃ sarṣapān chāgalaṃ payaḥ śastraṃ dūrvāṃ madhu ghṛtaṃ kuryāddaṣṭasya mūrddhataḥ evaṃ śāmyati saptāhādviṣamātmavataḥ sataḥ" },
      { type: "verse", number: "107", sanskrit: "कर्केतनं मरकतं वज्रं वारणमौक्तिकम् वैडूर्यं गर्दभमणिं पिचुकां विषमुष्टिकाम्", text: "karketanaṃ marakataṃ vajraṃ vāraṇamauktikam vaiḍūryaṃ gardabhamaṇiṃ picukāṃ viṣamuṣṭikām" },
      { type: "verse", number: "108", sanskrit: "हिमवद्गिरिसम्भूतां सोमराजीं पुनर्नवाम् तथा द्रोणं महाद्रोणं मानसीं सर्पजं मणिम् विषाणि विषशान्त्यर्थं वीर्यवन्ति च धारयेत्", text: "himavadgirisambhūtāṃ somarājīṃ punarnavām tathā droṇaṃ mahādroṇaṃ mānasīṃ sarpajaṃ maṇim viṣāṇi viṣaśāntyarthaṃ vīryavanti ca dhārayet" },
      { type: "verse", number: "109", sanskrit: "छत्री झर्झरपाणिश्च चरेद्रात्रौ विशेषतः तच्छायाशब्दवित्रस्ताः प्रणश्यन्तिभुजङ्गमाः", text: "chatrī jharjharapāṇiśca caredrātrau viśeṣataḥ tacchāyāśabdavitrastāḥ praṇaśyantibhujaṅgamāḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 43,
    lang: "sa",
    content: [
      { type: "heading", heading: "Ваджикарана адхьяя — афродизиакальная терапия" },
      { type: "text", text: "Глава 43 Уттара стханы — «Ваджикарана адхьяя» — посвящена специализированному разделу: афродизиакальная терапия. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः कीटविषप्रतिषेधं नामाध्यायं व्याख्यास्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ kīṭaviṣapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "सर्पाणामेव विण्मूत्रशुक्राण्डशवकोथजाः दोषैर्व्यस्तैः समस्तैश्च युक्ताः कीटाश्चतुर्विधाः", text: "sarpāṇāmeva viṇmūtraśukrāṇḍaśavakothajāḥ doṣairvyastaiḥ samastaiśca yuktāḥ kīṭāścaturvidhāḥ" },
      { type: "verse", number: "3", sanskrit: "कुम्भीनसस्तुण्डिकेरी शृङ्गी शतकुलीरकः उच्चिटिङ्गोग्निनामा च चिच्चिटाङ्गो मयूरकः अहिजोरभ्रकाबर्तशारिकामुखवैदलाः", text: "kumbhīnasastuṇḍikerī śṛṅgī śatakulīrakaḥ ucciṭiṅgognināmā ca cicciṭāṅgo mayūrakaḥ ahijorabhrakābartaśārikāmukhavaidalāḥ" },
      { type: "verse", number: "4", sanskrit: "शरावकुर्दौ परुषश्चित्रशीर्षो हि जारकः अष्टादशेति वायव्याः कीटा वातप्रकोपनाः", text: "śarāvakurdau paruṣaścitraśīrṣo hi jārakaḥ aṣṭādaśeti vāyavyāḥ kīṭā vātaprakopanāḥ" },
      { type: "verse", number: "5", sanskrit: "कौण्डिन्यकः कणभको वरटी पत्रवृश्चिकः विनासिका ब्राह्मणिका विन्दुलो भ्रमरस्तथा", text: "kauṇḍinyakaḥ kaṇabhako varaṭī patravṛścikaḥ vināsikā brāhmaṇikā vindulo bhramarastathā" },
      { type: "verse", number: "6", sanskrit: "बाह्यकी पिच्चिटः कुम्भी वर्चःकीटोरिमेदकः दुन्दुभिः पद्मकीटश्च मकरः शतपादकः", text: "bāhyakī picciṭaḥ kumbhī varcaḥkīṭorimedakaḥ dundubhiḥ padmakīṭaśca makaraḥ śatapādakaḥ" },
      { type: "verse", number: "7", sanskrit: "पञ्चालः पाकमत्स्यश्च सूक्ष्मतुण्डोथ गर्दभिः क्लीतः कृमिशरारी च यश्चाप्युत्क्लेशकः स्मृतः चतुर्विंशतिराग्रेयाः कीटाः पित्तविकारदाः", text: "pañcālaḥ pākamatsyaśca sūkṣmatuṇḍotha gardabhiḥ klītaḥ kṛmiśarārī ca yaścāpyutkleśakaḥ smṛtaḥ caturviṃśatirāgreyāḥ kīṭāḥ pittavikāradāḥ" },
      { type: "verse", number: "8", sanskrit: "विश्वम्भरः पञ्चशुष्कः पञ्चकृष्णोथ कोकिलः स्थैर्यकः प्रचलाकश्च वटभः किटिभो जटी", text: "viśvambharaḥ pañcaśuṣkaḥ pañcakṛṣṇotha kokilaḥ sthairyakaḥ pracalākaśca vaṭabhaḥ kiṭibho jaṭī" },
      { type: "verse", number: "9", sanskrit: "सूचीमुखः कृष्णगोधा दभ्रः काषायवासिकः त्रयोदशैते निर्दिष्टाः सौम्याः श्लेष्मप्रकोपणाः", text: "sūcīmukhaḥ kṛṣṇagodhā dabhraḥ kāṣāyavāsikaḥ trayodaśaite nirdiṣṭāḥ saumyāḥ śleṣmaprakopaṇāḥ" },
      { type: "verse", number: "10", sanskrit: "तुङ्गनासश्चिपिलकस्तालको वाहकस्तथा कोष्ठागारी कृमिकरो यश्च मण्डलपुच्छकः", text: "tuṅganāsaścipilakastālako vāhakastathā koṣṭhāgārī kṛmikaro yaśca maṇḍalapucchakaḥ" },
      { type: "verse", number: "11", sanskrit: "तुण्डनाभः सर्षपको मद्गुलिः शम्बुकस्तथा अग्निकीटश्च सङ्कीर्णा द्वादश प्राणनाशनाः", text: "tuṇḍanābhaḥ sarṣapako madguliḥ śambukastathā agnikīṭaśca saṅkīrṇā dvādaśa prāṇanāśanāḥ" },
      { type: "verse", number: "12", sanskrit: "दष्टस्यकीटैर्वायव्यैर्दंशस्तोदरुजोल्बणः आग्नेयैरल्पसंस्रावो दाहरागविसर्पवान् पक्कपीलुफलप्रख्यः खर्जूरसदृशोथ वा", text: "daṣṭasyakīṭairvāyavyairdaṃśastodarujolbaṇaḥ āgneyairalpasaṃsrāvo dāharāgavisarpavān pakkapīluphalaprakhyaḥ kharjūrasadṛśotha vā" },
      { type: "verse", number: "13", sanskrit: "कफाधिकैर्मन्दरुजः पक्कोदुम्बरसन्निभः स्रावाढ्यःसर्वलिङ्गस्तुदंशः स्यात्सान्निपातिकैः", text: "kaphādhikairmandarujaḥ pakkodumbarasannibhaḥ srāvāḍhyaḥsarvaliṅgastudaṃśaḥ syātsānnipātikaiḥ" },
      { type: "verse", number: "14", sanskrit: "वेगाश्च सर्पवच्छोफो वर्द्धिष्णुर्विस्ररक्तता शिरोक्षिगौरवं मूर्च्छा भ्रमः श्वासोतिवेदना", text: "vegāśca sarpavacchopho varddhiṣṇurvisraraktatā śirokṣigauravaṃ mūrcchā bhramaḥ śvāsotivedanā" },
      { type: "verse", number: "15", sanskrit: "सर्वेषां कर्णिका शोफो ज्वरः कण्डूररोचकः", text: "sarveṣāṃ karṇikā śopho jvaraḥ kaṇḍūrarocakaḥ" },
      { type: "verse", number: "16", sanskrit: "वातिकः पक्षवातेन स्पर्शाद्दशति पैत्तिकः मुखेन श्लैष्मिकः कीटः सर्वथा सान्निपातिकः", text: "vātikaḥ pakṣavātena sparśāddaśati paittikaḥ mukhena ślaiṣmikaḥ kīṭaḥ sarvathā sānnipātikaḥ" },
      { type: "verse", number: "17", sanskrit: "दष्टस्य कणभैः शोफो विसर्पो वमथुर्ज्वरः दंशश्च कर्णिकाकारः श्यावरक्तो विशीर्यते", text: "daṣṭasya kaṇabhaiḥ śopho visarpo vamathurjvaraḥ daṃśaśca karṇikākāraḥ śyāvarakto viśīryate" },
      { type: "verse", number: "18", sanskrit: "त्रिकण्टकैस्तु दष्टस्य नानावर्णोथ वा सितः दंशो भवेच्छ्वयथुमान् मोहो भेदश्च वर्चसः", text: "trikaṇṭakaistu daṣṭasya nānāvarṇotha vā sitaḥ daṃśo bhavecchvayathumān moho bhedaśca varcasaḥ" },
      { type: "verse", number: "19", sanskrit: "कृकलासेर्द्धचन्द्राभः स्राववात् भृशलोहितः दंशो रक्तैश्चितः स्फोटैः सशूलैर्दम्भवोद्भवः", text: "kṛkalāserddhacandrābhaḥ srāvavāt bhṛśalohitaḥ daṃśo raktaiścitaḥ sphoṭaiḥ saśūlairdambhavodbhavaḥ" },
      { type: "verse", number: "20", sanskrit: "एकदंष्ट्रार्पितः पीतः कण्डूमान् दार्दुरः सरुक् दंशो दष्टः सतृण्निद्रो मूर्च्छावान् हरितं वमेत्", text: "ekadaṃṣṭrārpitaḥ pītaḥ kaṇḍūmān dārduraḥ saruk daṃśo daṣṭaḥ satṛṇnidro mūrcchāvān haritaṃ vamet" },
      { type: "verse", number: "21", sanskrit: "मात्स्यो दंशः सरुग्दाहः प्रागेवोक्तो जलौकसाम् विश्वम्भरकृतो दंशः शोफकण्डूरुजान्वितः कफोद्वममतीसारं कुरुते कोठजन्म च", text: "mātsyo daṃśaḥ sarugdāhaḥ prāgevokto jalaukasām viśvambharakṛto daṃśaḥ śophakaṇḍūrujānvitaḥ kaphodvamamatīsāraṃ kurute koṭhajanma ca" },
      { type: "verse", number: "22", sanskrit: "पीतः शतपदीदंशः स्वेदरुग्रागशोफवान् अतसीपुष्पवर्णो वा पिटकावान् भ्रमग्रदः", text: "pītaḥ śatapadīdaṃśaḥ svedarugrāgaśophavān atasīpuṣpavarṇo vā piṭakāvān bhramagradaḥ" },
      { type: "verse", number: "23", sanskrit: "गृहगोधिकया स्घेदतोदश्वयथुदाहवान् क्लेदी च दंशो दष्टस्य हृस्पीडा ग्रन्थिसम्भवः", text: "gṛhagodhikayā sghedatodaśvayathudāhavān kledī ca daṃśo daṣṭasya hṛspīḍā granthisambhavaḥ" },
      { type: "verse", number: "24", sanskrit: "कण्डूमान् मशकैरीषच्छ्वयथुर्मन्दवेदनः असाध्यकीटसदृशमसाध्यमशकक्षतम्", text: "kaṇḍūmān maśakairīṣacchvayathurmandavedanaḥ asādhyakīṭasadṛśamasādhyamaśakakṣatam" },
      { type: "verse", number: "25", sanskrit: "प्रायेण मक्षिका नेत्रे दशन्ति श्वयथूल्वणः तद्दंशो दाहकण्डूमांस्तासां तु स्थालिकां त्यजेत् तदृष्टे पिटका श्यावा स्राविणी भूर्युपद्रवा", text: "prāyeṇa makṣikā netre daśanti śvayathūlvaṇaḥ taddaṃśo dāhakaṇḍūmāṃstāsāṃ tu sthālikāṃ tyajet tadṛṣṭe piṭakā śyāvā srāviṇī bhūryupadravā" },
      { type: "verse", number: "26", sanskrit: "रुग्वान् पिपीलिकादंशो वह्निनेव च दह्यते", text: "rugvān pipīlikādaṃśo vahnineva ca dahyate" },
      { type: "verse", number: "27", sanskrit: "जलबिन्दुनिभैः स्फोटैर्दाहकण्डूरुजान्वितैः यत् गात्रमाचितं सोष्म तद्विद्यादवमूत्रितम्", text: "jalabindunibhaiḥ sphoṭairdāhakaṇḍūrujānvitaiḥ yat gātramācitaṃ soṣma tadvidyādavamūtritam" },
      { type: "verse", number: "28", sanskrit: "वृश्चिकस्य विषं तीक्ष्णमादौ दहति वह्निवत् ऊर्ध्वमारोहति क्षिप्रं दंशे पश्चात्तु तिष्ठति दंशः सद्योतिरुक् श्यावस्तुद्यते स्फुटतीव च", text: "vṛścikasya viṣaṃ tīkṣṇamādau dahati vahnivat ūrdhvamārohati kṣipraṃ daṃśe paścāttu tiṣṭhati daṃśaḥ sadyotiruk śyāvastudyate sphuṭatīva ca" },
      { type: "verse", number: "29", sanskrit: "ते गवादिशकृत्कोथद्दिग्धदष्टादिकोथतः सर्पकोथाच्च सम्भूता मन्दमध्यमहाविषाः", text: "te gavādiśakṛtkothaddigdhadaṣṭādikothataḥ sarpakothācca sambhūtā mandamadhyamahāviṣāḥ" },
      { type: "verse", number: "30", sanskrit: "मन्दाः पीताः सिताः श्यावा रुक्षाः कर्बुरमेचकाः रोमशा बहुपर्वाणो लोहिताः पाण्डुरोदराः", text: "mandāḥ pītāḥ sitāḥ śyāvā rukṣāḥ karburamecakāḥ romaśā bahuparvāṇo lohitāḥ pāṇḍurodarāḥ" },
      { type: "verse", number: "31", sanskrit: "धूम्रोदरास्त्रिपर्वाणो मध्यास्तु कपिलारुणाः", text: "dhūmrodarāstriparvāṇo madhyāstu kapilāruṇāḥ" },
      { type: "verse", number: "32", sanskrit: "पिशङ्गाः शबलाश्चित्राः शोणिताभा महाविषाः", text: "piśaṅgāḥ śabalāścitrāḥ śoṇitābhā mahāviṣāḥ" },
      { type: "verse", number: "33", sanskrit: "अग्न्याभा द्व्येकपर्याणो रक्तासितसितोदराः", text: "agnyābhā dvyekaparyāṇo raktāsitasitodarāḥ" },
      { type: "verse", number: "34", sanskrit: "तैर्दष्टः शूनरसनः स्तब्धगात्रो रुजार्दितः खर्वमन् शोणितं कृष्णमिन्द्रियार्थनसंविदन्", text: "tairdaṣṭaḥ śūnarasanaḥ stabdhagātro rujārditaḥ kharvaman śoṇitaṃ kṛṣṇamindriyārthanasaṃvidan" },
      { type: "verse", number: "35", sanskrit: "स्विद्यन् मूर्च्छन् विशुष्कास्यो विह्णलो वेदनातुरः विशीर्यमाणमांसश्च प्रायशो विजहात्यसून्", text: "svidyan mūrcchan viśuṣkāsyo vihṇalo vedanāturaḥ viśīryamāṇamāṃsaśca prāyaśo vijahātyasūn" },
      { type: "verse", number: "36", sanskrit: "उच्चिटिङ्गस्तु वक्त्रेण दशत्यभ्यधिकव्यथः", text: "ucciṭiṅgastu vaktreṇa daśatyabhyadhikavyathaḥ" },
      { type: "verse", number: "37", sanskrit: "साध्यतो वृश्चिकात् स्तम्भं शेफसो हृष्टरोमताम् करोति सेकमङ्गानां दंशः शीताम्बुनेव च", text: "sādhyato vṛścikāt stambhaṃ śephaso hṛṣṭaromatām karoti sekamaṅgānāṃ daṃśaḥ śītāmbuneva ca" },
      { type: "verse", number: "38", sanskrit: "उष्ट्रवर्णतया प्रोक्तः स एव ह्युष्ट्रधूमकः रात्रिको रात्रिचाराच्च पृथक् तु कणभादिषु विकारसाधनाभेदात् भेदाः सन्तोपि नोदिताः", text: "uṣṭravarṇatayā proktaḥ sa eva hyuṣṭradhūmakaḥ rātriko rātricārācca pṛthak tu kaṇabhādiṣu vikārasādhanābhedāt bhedāḥ santopi noditāḥ" },
      { type: "verse", number: "39", sanskrit: "वातपित्तोत्तराः कीटा श्लैष्मिकाः कणभोन्दुराः प्रायो वातोल्बणविषा वश्चिकाः सोष्ट्रधूमकाः", text: "vātapittottarāḥ kīṭā ślaiṣmikāḥ kaṇabhondurāḥ prāyo vātolbaṇaviṣā vaścikāḥ soṣṭradhūmakāḥ" },
      { type: "verse", number: "40", sanskrit: "यत्र यस्यैव दोषस्य लिङ्गाधिक्यं प्रतर्कयेत् तत्र तस्यौषधैः कुर्याद्विपरीतगुणैः क्रियाम्", text: "yatra yasyaiva doṣasya liṅgādhikyaṃ pratarkayet tatra tasyauṣadhaiḥ kuryādviparītaguṇaiḥ kriyām" },
      { type: "verse", number: "41", sanskrit: "हृत्पीडोर्ध्वानिलः स्तम्भाः सिरायामोस्थि पर्वरुक् घूर्णनोद्वेष्टनं गात्रश्यावता वातिके विषे", text: "hṛtpīḍordhvānilaḥ stambhāḥ sirāyāmosthi parvaruk ghūrṇanodveṣṭanaṃ gātraśyāvatā vātike viṣe" },
      { type: "verse", number: "42", sanskrit: "संज्ञानाशोष्णनिश्वासौ हृदाहः कटुकास्यता मांसावदरणं शोफो रक्तपित्तं च पैत्तिके", text: "saṃjñānāśoṣṇaniśvāsau hṛdāhaḥ kaṭukāsyatā māṃsāvadaraṇaṃ śopho raktapittaṃ ca paittike" },
      { type: "verse", number: "43", sanskrit: "छर्द्यरोचकहृल्लासप्रसेकोत्क्लेशपीनसैः सशैत्यमुखमाधुर्यैर्विद्याच्छ्रलेष्माधिकंविषम्", text: "chardyarocakahṛllāsaprasekotkleśapīnasaiḥ saśaityamukhamādhuryairvidyācchraleṣmādhikaṃviṣam" },
      { type: "verse", number: "44", sanskrit: "पिण्याकेन व्रणालेपस्तैलाभ्यङ्गश्च वातिके स्वेदो नाडीपुलाकाद्यैर्बृंहणश्च विधिर्हितः", text: "piṇyākena vraṇālepastailābhyaṅgaśca vātike svedo nāḍīpulākādyairbṛṃhaṇaśca vidhirhitaḥ" },
      { type: "verse", number: "45", sanskrit: "पैत्तिकं स्तम्भयेत् सेकैः प्रदेहैश्चातिशीतलैः", text: "paittikaṃ stambhayet sekaiḥ pradehaiścātiśītalaiḥ" },
      { type: "verse", number: "46", sanskrit: "लेखनच्छेदनस्वेदवमनैः श्लैष्मिकं जयेत्", text: "lekhanacchedanasvedavamanaiḥ ślaiṣmikaṃ jayet" },
      { type: "verse", number: "47", sanskrit: "कीटानां त्रिप्रकाराणां त्रैविध्येन क्रिया हिता", text: "kīṭānāṃ triprakārāṇāṃ traividhyena kriyā hitā" },
      { type: "verse", number: "48", sanskrit: "स्स्वेदालेपनसेकांस्तु कोष्णान् प्रायोवचारयेत् अन्यत्र मूर्च्छिताद्दंशपाकतः कोथतोपि वा", text: "ssvedālepanasekāṃstu koṣṇān prāyovacārayet anyatra mūrcchitāddaṃśapākataḥ kothatopi vā" },
      { type: "verse", number: "49", sanskrit: "नृकेशाः सर्षपाः पीता गुडो जीर्णश्च धूपनम् विषदंशस्य सर्वस्य काश्यपः परमब्रवीत्", text: "nṛkeśāḥ sarṣapāḥ pītā guḍo jīrṇaśca dhūpanam viṣadaṃśasya sarvasya kāśyapaḥ paramabravīt" },
      { type: "verse", number: "50", sanskrit: "विषघ्नं च विधिं सर्वं कुर्यात् संशोधनानि च", text: "viṣaghnaṃ ca vidhiṃ sarvaṃ kuryāt saṃśodhanāni ca" },
      { type: "verse", number: "51", sanskrit: "साधयेत् सर्पवद्दष्टान् विषोग्रैः कीटवृश्चिकैः", text: "sādhayet sarpavaddaṣṭān viṣograiḥ kīṭavṛścikaiḥ" },
      { type: "verse", number: "52", sanskrit: "तण्डुलीयकतुल्यांशां त्रिवृतां सर्पिषा पिबेन् याति कीटविषैः कम्पं न कैलास इवानिलैः", text: "taṇḍulīyakatulyāṃśāṃ trivṛtāṃ sarpiṣā piben yāti kīṭaviṣaiḥ kampaṃ na kailāsa ivānilaiḥ" },
      { type: "verse", number: "53", sanskrit: "क्षीरिवृक्षत्वगालेपः शुद्धे कीटविषापहः मुक्तालेपो वरः शोफतोददाहज्वरप्रणुत्", text: "kṣīrivṛkṣatvagālepaḥ śuddhe kīṭaviṣāpahaḥ muktālepo varaḥ śophatodadāhajvarapraṇut" },
      { type: "verse", number: "54", sanskrit: "वचा हिङ्गुविडङ्गानि सैन्धवं गजपिप्पली पाठाप्रतिविषाव्योषं काश्ययेन विनिर्मितम् दशाङ्गमगदं पीत्वा सर्वकीटविषं जयेत्", text: "vacā hiṅguviḍaṅgāni saindhavaṃ gajapippalī pāṭhāprativiṣāvyoṣaṃ kāśyayena vinirmitam daśāṅgamagadaṃ pītvā sarvakīṭaviṣaṃ jayet" },
      { type: "verse", number: "55", sanskrit: "ऐकध्यं कीटविषजिन्महास्नेहं पयो मधु शिखिकुक्कुटजैः पिच्छैः सतैललवणोत्तमैः धूपो हन्ति कृतः शीघ्रं कीटवृश्चिकजं विषम्", text: "aikadhyaṃ kīṭaviṣajinmahāsnehaṃ payo madhu śikhikukkuṭajaiḥ picchaiḥ satailalavaṇottamaiḥ dhūpo hanti kṛtaḥ śīghraṃ kīṭavṛścikajaṃ viṣam" },
      { type: "verse", number: "56", sanskrit: "विषे कणभजे कुर्यादुन्दुरोक्तमुपक्रमम् शिरीषबीजं मण्डूके लेपः स्नुक्क्षीरकल्कितम् मधु त्रिकटुकं श्वेतपिण्डामूलं च मत्स्यजे", text: "viṣe kaṇabhaje kuryādunduroktamupakramam śirīṣabījaṃ maṇḍūke lepaḥ snukkṣīrakalkitam madhu trikaṭukaṃ śvetapiṇḍāmūlaṃ ca matsyaje" },
      { type: "verse", number: "57", sanskrit: "वचां वंशत्वचं पाठां नतं सुरसमञ्जरीम् द्वे बले नाकुलीं कुष्ठं शिरीषं रजनीद्वयम्", text: "vacāṃ vaṃśatvacaṃ pāṭhāṃ nataṃ surasamañjarīm dve bale nākulīṃ kuṣṭhaṃ śirīṣaṃ rajanīdvayam" },
      { type: "verse", number: "58", sanskrit: "गुहामतिगुहां श्वेतामजगन्धां शिलाजतु कत्तृणं कटभीक्षारं गृहधूमं भनश्शिलाम्", text: "guhāmatiguhāṃ śvetāmajagandhāṃ śilājatu kattṛṇaṃ kaṭabhīkṣāraṃ gṛhadhūmaṃ bhanaśśilām" },
      { type: "verse", number: "59", sanskrit: "रोहीतकं च पित्तेन कल्कयेत् स वरो ऽगदः विश्वम्भरादिष्वालेपनावनाञ्जनपानतः", text: "rohītakaṃ ca pittena kalkayet sa varo 'gadaḥ viśvambharādiṣvālepanāvanāñjanapānataḥ" },
      { type: "verse", number: "60", sanskrit: "स्वर्जिकाजशकृत्क्षारः सुरसः साक्षिपीडकः मदिरामण्डसंयुक्तो हितः शतपदीविषे", text: "svarjikājaśakṛtkṣāraḥ surasaḥ sākṣipīḍakaḥ madirāmaṇḍasaṃyukto hitaḥ śatapadīviṣe" },
      { type: "verse", number: "61", sanskrit: "कपित्थमक्षिपीडोर्कबीजं त्रिकटुकान्वितम् करञ्जो द्वे हरिद्रे च गृहगोधीविषापहः", text: "kapitthamakṣipīḍorkabījaṃ trikaṭukānvitam karañjo dve haridre ca gṛhagodhīviṣāpahaḥ" },
      { type: "verse", number: "62", sanskrit: "काकाण्डयुक्तः सर्वेषां विषाणां तण्डुलीयकः प्रशस्तो बर्हिणोण्डेन तद्वद्वायसपीलुकः", text: "kākāṇḍayuktaḥ sarveṣāṃ viṣāṇāṃ taṇḍulīyakaḥ praśasto barhiṇoṇḍena tadvadvāyasapīlukaḥ" },
      { type: "verse", number: "63", sanskrit: "तगरं नागरं नागकेसरं मरिचानि च प्रयुक्तं पानलेपाभ्यां मक्षिकाविषनाशनम्", text: "tagaraṃ nāgaraṃ nāgakesaraṃ maricāni ca prayuktaṃ pānalepābhyāṃ makṣikāviṣanāśanam" },
      { type: "verse", number: "64", sanskrit: "सितासिते च लवणे मरिचं च सनागरम् फणिज्जकरसोपेतं वरटीनां विषापहम्", text: "sitāsite ca lavaṇe maricaṃ ca sanāgaram phaṇijjakarasopetaṃ varaṭīnāṃ viṣāpaham" },
      { type: "verse", number: "65", sanskrit: "सद्यो वृश्चिकजं दंशं चक्रतैलेन सेचयेत् विदारिगन्धासिद्धेन कवोष्णेनेतरेण वा", text: "sadyo vṛścikajaṃ daṃśaṃ cakratailena secayet vidārigandhāsiddhena kavoṣṇenetareṇa vā" },
      { type: "verse", number: "66", sanskrit: "लवणोत्तमयुक्तेन सर्पिषा वा पुनः पुनः सिञ्चेत्कोष्णारनालेन सक्षीरलवणेन वा उपनाहो घृते भृष्टः कल्कोजाज्याः ससैन्धवः", text: "lavaṇottamayuktena sarpiṣā vā punaḥ punaḥ siñcetkoṣṇāranālena sakṣīralavaṇena vā upanāho ghṛte bhṛṣṭaḥ kalkojājyāḥ sasaindhavaḥ" },
      { type: "verse", number: "67", sanskrit: "आदंशं स्वेदितं चूर्णैः प्रच्छाय प्रतिसारयेत् रजनीसैन्धवव्योषशिरीषफलपुष्पजैः", text: "ādaṃśaṃ sveditaṃ cūrṇaiḥ pracchāya pratisārayet rajanīsaindhavavyoṣaśirīṣaphalapuṣpajaiḥ" },
      { type: "verse", number: "68", sanskrit: "मातुलुङ्गाम्लगोमूत्रपिष्टं च सुरसाग्रजम् लेपः सुखोष्णश्च हितः पिण्याको गोमयोपि वा", text: "mātuluṅgāmlagomūtrapiṣṭaṃ ca surasāgrajam lepaḥ sukhoṣṇaśca hitaḥ piṇyāko gomayopi vā" },
      { type: "verse", number: "69", sanskrit: "पाने सर्पिर्मधुयुतं क्षीरं वा भूरिशर्करम् गुडोदकं वा सुहिमं चातुर्जातकवासितम्", text: "pāne sarpirmadhuyutaṃ kṣīraṃ vā bhūriśarkaram guḍodakaṃ vā suhimaṃ cāturjātakavāsitam" },
      { type: "verse", number: "70", sanskrit: "पलाशबीजं शूलघ्नो लेपोर्कक्षीरभावितम् पारावतशकुत्पथ्या तगरं विश्वभेषजम् बीज पूररसोन्मिश्रं वरो ऽयं वृश्चिकागदः", text: "palāśabījaṃ śūlaghno leporkakṣīrabhāvitam pārāvataśakutpathyā tagaraṃ viśvabheṣajam bīja pūrarasonmiśraṃ varo 'yaṃ vṛścikāgadaḥ" },
      { type: "verse", number: "71", sanskrit: "मनोह्ना सैन्धवं हिङ्गु मालतीपल्लवानि च गोशकृद्रसपिष्टेयं गुटिका वृश्चिकार्दिते", text: "manohnā saindhavaṃ hiṅgu mālatīpallavāni ca gośakṛdrasapiṣṭeyaṃ guṭikā vṛścikārdite" },
      { type: "verse", number: "72", sanskrit: "लशुनो मरिचं हिङ्गु सुरसं विश्वभेषजम् अर्कक्षीरेण गुटिका वृश्चिकार्दितशङ्करी", text: "laśuno maricaṃ hiṅgu surasaṃ viśvabheṣajam arkakṣīreṇa guṭikā vṛścikārditaśaṅkarī" },
      { type: "verse", number: "73", sanskrit: "सशैवलोष्ट्रदंष्ट्रा च हन्ति वृश्चिकजं विषम्", text: "saśaivaloṣṭradaṃṣṭrā ca hanti vṛścikajaṃ viṣam" },
      { type: "verse", number: "74", sanskrit: "हिङ्गुना हरितालेन मातुलुङ्गरसेन च लेपाञ्जनाभ्यां गुटिका परमं वृश्चिकापहा", text: "hiṅgunā haritālena mātuluṅgarasena ca lepāñjanābhyāṃ guṭikā paramaṃ vṛścikāpahā" },
      { type: "verse", number: "75", sanskrit: "करञ्जार्जुनशेलूनां कटभ्याः कुटजस्य च शिरीषस्य च पुष्पाणि मस्तुना दंशलेपनम्", text: "karañjārjunaśelūnāṃ kaṭabhyāḥ kuṭajasya ca śirīṣasya ca puṣpāṇi mastunā daṃśalepanam" },
      { type: "verse", number: "76", sanskrit: "पिप्पलीं मरिचं यष्टिं श्वेतां सुरसमञ्जरीम् सहदेवामपामार्गं तण्डुलीयं च कल्कयेत् कुतलक्षारतोयेन लेपो ऽलिविषनाशनः", text: "pippalīṃ maricaṃ yaṣṭiṃ śvetāṃ surasamañjarīm sahadevāmapāmārgaṃ taṇḍulīyaṃ ca kalkayet kutalakṣāratoyena lepo 'liviṣanāśanaḥ" },
      { type: "verse", number: "77", sanskrit: "यो मुह्यति प्रश्वसिति प्रलपत्युग्रवेदनः तस्य पथ्यानिशाकृष्णामञ्जिष्ठातिविषोषणम् सालाबुवृन्तं वार्ताकरसपिष्टं प्रलेपनम्", text: "yo muhyati praśvasiti pralapatyugravedanaḥ tasya pathyāniśākṛṣṇāmañjiṣṭhātiviṣoṣaṇam sālābuvṛntaṃ vārtākarasapiṣṭaṃ pralepanam" },
      { type: "verse", number: "78", sanskrit: "आदंशे यस्य कण्डूःस्यात् कोथः कोठं च दारुणम् तस्य लेपस्त्रिकटुकं यवक्षारोक्षिपीडकः", text: "ādaṃśe yasya kaṇḍūḥsyāt kothaḥ koṭhaṃ ca dāruṇam tasya lepastrikaṭukaṃ yavakṣārokṣipīḍakaḥ" },
      { type: "verse", number: "79", sanskrit: "पारावतशकृत्कान्तास्वर्ज्जिकाग्निहरेणवः रसेन मातुलुङ्गस्य क्षीरेणार्कस्यवा द्रुताः", text: "pārāvataśakṛtkāntāsvarjjikāgnihareṇavaḥ rasena mātuluṅgasya kṣīreṇārkasyavā drutāḥ" },
      { type: "verse", number: "80", sanskrit: "हृदयं पीड्यते यस्य मूर्च्छा चिमिचिमायनम् दन्तौष्ठदंशो रोम्णां च हर्षस्तस्य निवर्तते वेगो विषस्य पञ्चाहान्नैव वा क्रियया विना", text: "hṛdayaṃ pīḍyate yasya mūrcchā cimicimāyanam dantauṣṭhadaṃśo romṇāṃ ca harṣastasya nivartate vego viṣasya pañcāhānnaiva vā kriyayā vinā" },
      { type: "verse", number: "81", sanskrit: "तत्र कुर्वीत दंशस्य लेपनं मस्तुकल्कितैः श्वेतपाटल्यतिविषाहरिद्राहरिणीनतैः बिल्वमूलयवक्षारसूक्ष्ममागधिकायुतैः", text: "tatra kurvīta daṃśasya lepanaṃ mastukalkitaiḥ śvetapāṭalyativiṣāharidrāhariṇīnataiḥ bilvamūlayavakṣārasūkṣmamāgadhikāyutaiḥ" },
      { type: "verse", number: "82", sanskrit: "उत्कृत्यत इवादंशः शूनः क्लिन्नो हतच्छविः जम्बूफलनिभं रक्तं कूजन् वमति वेष्टते", text: "utkṛtyata ivādaṃśaḥ śūnaḥ klinno hatacchaviḥ jambūphalanibhaṃ raktaṃ kūjan vamati veṣṭate" },
      { type: "verse", number: "83", sanskrit: "इन्द्रियार्थं न जानाति प्रस्विद्यति च यो मुहुः स्वर्जिकाकुष्ठतगरनाकुलीपीलुपिप्पलीः बृहतीं चाच्छसुरया तस्य पिष्ट्वा विलेपनम्", text: "indriyārthaṃ na jānāti prasvidyati ca yo muhuḥ svarjikākuṣṭhatagaranākulīpīlupippalīḥ bṛhatīṃ cācchasurayā tasya piṣṭvā vilepanam" },
      { type: "verse", number: "84", sanskrit: "सर्वत्र चोग्रालिविषे पाययेन्मधुसर्पिषी विध्येत् सिरां विदध्याच्च वमनाञ्जननावनम् उष्णस्निग्धाम्लमधुरं भोजनं चानिलापहम्", text: "sarvatra cogrāliviṣe pāyayenmadhusarpiṣī vidhyet sirāṃ vidadhyācca vamanāñjananāvanam uṣṇasnigdhāmlamadhuraṃ bhojanaṃ cānilāpaham" },
      { type: "verse", number: "85", sanskrit: "नागरं गृहकपोतपुरीषं बीजपूरकरसो हरितालम् सैन्धवं च विनिहन्त्यगदो ऽयं लेपतो ऽलिकुलजं विषमाशु", text: "nāgaraṃ gṛhakapotapurīṣaṃ bījapūrakaraso haritālam saindhavaṃ ca vinihantyagado 'yaṃ lepato 'likulajaṃ viṣamāśu" },
      { type: "verse", number: "86", sanskrit: "अन्ते वृश्चिकदष्टानां समुदीर्णे भृशं विषे विषेणालेपयेद्दंशं स्थावरेण यथोचितम्", text: "ante vṛścikadaṣṭānāṃ samudīrṇe bhṛśaṃ viṣe viṣeṇālepayeddaṃśaṃ sthāvareṇa yathocitam" },
      { type: "verse", number: "87", sanskrit: "क्रियेयमुच्चिटिङ्गेपि प्रतिलोमं च पांसुभिः उद्वर्तनं सुखाम्लोष्णैस्तथा प्रच्छादनं घनैः", text: "kriyeyamucciṭiṅgepi pratilomaṃ ca pāṃsubhiḥ udvartanaṃ sukhāmloṣṇaistathā pracchādanaṃ ghanaiḥ" },
      { type: "verse", number: "88", sanskrit: "कुटजस्य फलं कुष्ठं मालती फलिनी नतम् तिक्तेक्ष्वाकुश्च पिष्टानि पानप्नध्द्मनादिभिः", text: "kuṭajasya phalaṃ kuṣṭhaṃ mālatī phalinī natam tiktekṣvākuśca piṣṭāni pānapnadhdmanādibhiḥ" },
      { type: "verse", number: "89", sanskrit: "वृश्चिकोन्दुरुलूतानां सर्पाणां च विषापहम् समानममृतेनेदं गरशेषं च नाशयेत्", text: "vṛścikondurulūtānāṃ sarpāṇāṃ ca viṣāpaham samānamamṛtenedaṃ garaśeṣaṃ ca nāśayet" },
      { type: "verse", number: "90", sanskrit: "अर्कस्य दुग्धेन शिरीषबीजं त्रिर्भावितं पिप्पलिचूर्णमिश्रम् एषो ऽगदो हन्ति विषाणि कीटभुजङ्गलूतोन्दुरुवृश्चिकानाम्", text: "arkasya dugdhena śirīṣabījaṃ trirbhāvitaṃ pippalicūrṇamiśram eṣo 'gado hanti viṣāṇi kīṭabhujaṅgalūtonduruvṛścikānām" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 44,
    lang: "sa",
    content: [
      { type: "heading", heading: "Дхату санграха — о тканях тела" },
      { type: "text", text: "Глава 44 Уттара стханы — «Дхату санграха» — посвящена специализированному разделу: о тканях тела. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो लूताप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto lūtāpratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "विश्वामित्राय रुष्टस्य वसिष्ठस्य ललाटजाः स्वेदलेशाः स्मृता लूता लूने ये पतितास्तृणे", text: "viśvāmitrāya ruṣṭasya vasiṣṭhasya lalāṭajāḥ svedaleśāḥ smṛtā lūtā lūne ye patitāstṛṇe" },
      { type: "verse", number: "3", sanskrit: "खाण्डवे दह्यमानानामसुराणां शरीरतः ये स्फुलिङ्गा विनिश्चेरुस्ते लूता इति केचन", text: "khāṇḍave dahyamānānāmasurāṇāṃ śarīrataḥ ye sphuliṅgā viniśceruste lūtā iti kecana" },
      { type: "verse", number: "4", sanskrit: "अन्ये वदन्ति भुक्तस्य दुष्टस्यान्नस्य मूर्च्छनात् सम्भवन्ति विषस्फोटा ये लूताः कीटलक्षणम् यथास्वं धारयन्तस्ते लूताः कीटाश्च संज्ञिताः", text: "anye vadanti bhuktasya duṣṭasyānnasya mūrcchanāt sambhavanti viṣasphoṭā ye lūtāḥ kīṭalakṣaṇam yathāsvaṃ dhārayantaste lūtāḥ kīṭāśca saṃjñitāḥ" },
      { type: "verse", number: "5", sanskrit: "तत्र घोरतमा लूता भिद्यन्ते ता अपि त्रिधा तक्ष्णिमध्यावरत्वेन घ्नन्ति वाश्वचिकित्सिताः सप्ताहेन दशाहेन पक्षेण च परं क्रमात्", text: "tatra ghoratamā lūtā bhidyante tā api tridhā takṣṇimadhyāvaratvena ghnanti vāśvacikitsitāḥ saptāhena daśāhena pakṣeṇa ca paraṃ kramāt" },
      { type: "verse", number: "6", sanskrit: "कपिलाग्निमुखी पीता पद्मा मूत्रा सितासिता आग्नेय्यः स्वेदजाः सप्त लूताः पित्तविकारदाः", text: "kapilāgnimukhī pītā padmā mūtrā sitāsitā āgneyyaḥ svedajāḥ sapta lūtāḥ pittavikāradāḥ" },
      { type: "verse", number: "7", sanskrit: "पाण्डुरा रक्तपदिका भृङ्गा पिङ्गा त्रिमण्डला पूतिर्वीराण्डजाःसप्त सौम्याः श्लेष्मविकारदाः", text: "pāṇḍurā raktapadikā bhṛṅgā piṅgā trimaṇḍalā pūtirvīrāṇḍajāḥsapta saumyāḥ śleṣmavikāradāḥ" },
      { type: "verse", number: "8", sanskrit: "कुमुदालविषा रक्ता श्चित्रा सन्ता निमेचका कसना चोद्भिदाः सप्त वायव्या वायुरोगदाः", text: "kumudālaviṣā raktā ścitrā santā nimecakā kasanā codbhidāḥ sapta vāyavyā vāyurogadāḥ" },
      { type: "verse", number: "9", sanskrit: "काकाण्ड्येणपदी लाजा वैदेही जालिनी तथा मालागुणा सुवर्णा च मिश्राः सप्तोपपादिकाः", text: "kākāṇḍyeṇapadī lājā vaidehī jālinī tathā mālāguṇā suvarṇā ca miśrāḥ saptopapādikāḥ" },
      { type: "verse", number: "10", sanskrit: "व्याप्नुवन्त्याशु गात्राणि ज्वलत्पावकसन्निभाः सन्निपातकृतो ऽसाध्याः साध्याः कृच्छ्रेणचेतराः", text: "vyāpnuvantyāśu gātrāṇi jvalatpāvakasannibhāḥ sannipātakṛto 'sādhyāḥ sādhyāḥ kṛcchreṇacetarāḥ" },
      { type: "verse", number: "11", sanskrit: "ता दशन्ति सिते पक्षे ऽसिते सन्धौ सदैव च", text: "tā daśanti site pakṣe 'site sandhau sadaiva ca" },
      { type: "verse", number: "12", sanskrit: "दंशः सामान्यतस्तासां दद्रुमण्डलसन्निभः सितो ऽसितो ऽरुणःपीतःश्यावो वा मृदुरुन्नतः", text: "daṃśaḥ sāmānyatastāsāṃ dadrumaṇḍalasannibhaḥ sito 'sito 'ruṇaḥpītaḥśyāvo vā mṛdurunnataḥ" },
      { type: "verse", number: "13", sanskrit: "मध्ये कृष्णो ऽथवा श्यावः पर्यन्ते जालकावृतः विसर्पवाञ्छोफयुतस्तप्यते बहुवेदनः", text: "madhye kṛṣṇo 'thavā śyāvaḥ paryante jālakāvṛtaḥ visarpavāñchophayutastapyate bahuvedanaḥ" },
      { type: "verse", number: "14", sanskrit: "ज्वराशुपाकविक्लेदकोथावदरणान्वितः क्लेदेन यत्स्पृशत्यङ्गं तत्रापि कुरुते व्रणम्", text: "jvarāśupākavikledakothāvadaraṇānvitaḥ kledena yatspṛśatyaṅgaṃ tatrāpi kurute vraṇam" },
      { type: "verse", number: "15", sanskrit: "श्वासदंष्ट्राशकृन्मूत्रशुक्रलालानखार्तवैः अष्टाभिरुद्वमन्त्येता विषं वक्त्राद्विशेषतः", text: "śvāsadaṃṣṭrāśakṛnmūtraśukralālānakhārtavaiḥ aṣṭābhirudvamantyetā viṣaṃ vaktrādviśeṣataḥ" },
      { type: "verse", number: "16", sanskrit: "श्वासेन दंशः सहसा शूयते ज्वरदाहवान् दंष्ट्राकृतस्तूग्रतरो विवर्णः कठितः स्थिरः", text: "śvāsena daṃśaḥ sahasā śūyate jvaradāhavān daṃṣṭrākṛtastūgrataro vivarṇaḥ kaṭhitaḥ sthiraḥ" },
      { type: "verse", number: "17", sanskrit: "गम्भीरशोफवस्तोदवेदनादाहसंयुतः दुर्गन्धी शकृता दाहकण्डूचिमिचिमान्वितः", text: "gambhīraśophavastodavedanādāhasaṃyutaḥ durgandhī śakṛtā dāhakaṇḍūcimicimānvitaḥ" },
      { type: "verse", number: "18", sanskrit: "पच्यते चाशु पक्वश्च पाण्डुः पीलुफलोपमः मूत्रेण रक्तपर्यन्तो मध्ये कृष्णो विशीर्यते", text: "pacyate cāśu pakvaśca pāṇḍuḥ pīluphalopamaḥ mūtreṇa raktaparyanto madhye kṛṣṇo viśīryate" },
      { type: "verse", number: "19", sanskrit: "आवर्तसदृशः शूनः पूतिः सर्पति दह्यते शुक्रेण ग्रन्थिसंस्थानः कठिनस्तीव्रवेदनः", text: "āvartasadṛśaḥ śūnaḥ pūtiḥ sarpati dahyate śukreṇa granthisaṃsthānaḥ kaṭhinastīvravedanaḥ" },
      { type: "verse", number: "20", sanskrit: "अल्पमूलोल्परुक्वोठो लालया कण्डुरो मृदुः नखेन चोषपिटकाकण्डूधूमायनान्वितः किंशुकोदरवर्णस्तु रजसा चञ्चुमालवान्", text: "alpamūlolparukvoṭho lālayā kaṇḍuro mṛduḥ nakhena coṣapiṭakākaṇḍūdhūmāyanānvitaḥ kiṃśukodaravarṇastu rajasā cañcumālavān" },
      { type: "verse", number: "21", sanskrit: "लूता नाभेर्दशन्त्यूर्ध्वमूर्ध्वं चाधश्च कीटकाः तद्दूषितं च वस्त्रादि देहे पृक्तं विकारकृत्", text: "lūtā nābherdaśantyūrdhvamūrdhvaṃ cādhaśca kīṭakāḥ taddūṣitaṃ ca vastrādi dehe pṛktaṃ vikārakṛt" },
      { type: "verse", number: "22", sanskrit: "दिनार्धं लक्ष्यते नैव दंशो लूताविषोद्भवः", text: "dinārdhaṃ lakṣyate naiva daṃśo lūtāviṣodbhavaḥ" },
      { type: "verse", number: "23", sanskrit: "सूचीव्यधवदाभाति ततोसौ प्रथमे ऽहनि अव्यक्तवर्णः प्रचलः किञ्चित् कण्डूरुजान्वितः", text: "sūcīvyadhavadābhāti tatosau prathame 'hani avyaktavarṇaḥ pracalaḥ kiñcit kaṇḍūrujānvitaḥ" },
      { type: "verse", number: "24", sanskrit: "द्वितीये ऽत्युन्नतोन्तेषु पिटकैरिव चाचितः व्यक्तवर्णो नतो मध्ये कण्डूमान् ग्रन्थिसन्निभः", text: "dvitīye 'tyunnatonteṣu piṭakairiva cācitaḥ vyaktavarṇo nato madhye kaṇḍūmān granthisannibhaḥ" },
      { type: "verse", number: "25", sanskrit: "तृतीये सज्वरो रोमहर्षकृद्रक्तमण्डलः शरावरूपस्तोदाढ्यो रोमकूपेषु सास्रवः", text: "tṛtīye sajvaro romaharṣakṛdraktamaṇḍalaḥ śarāvarūpastodāḍhyo romakūpeṣu sāsravaḥ" },
      { type: "verse", number: "26", sanskrit: "महांश्चतुर्थे श्वयथुस्तापश्वासभ्रमप्रदः", text: "mahāṃścaturthe śvayathustāpaśvāsabhramapradaḥ" },
      { type: "verse", number: "27", sanskrit: "विकारान् कुरुते तांस्तान् पञ्चमे विषकोपजान् षष्ठे व्याप्नोति मर्माणि सप्तमे हन्ति जीवित", text: "vikārān kurute tāṃstān pañcame viṣakopajān ṣaṣṭhe vyāpnoti marmāṇi saptame hanti jīvita" },
      { type: "verse", number: "28", sanskrit: "विषमित्यतितीक्ष्णानामितरे विभजेदतः", text: "viṣamityatitīkṣṇānāmitare vibhajedataḥ" },
      { type: "verse", number: "29", sanskrit: "विषं शाम्यति सर्वासामेकविंशतिरात्रतः", text: "viṣaṃ śāmyati sarvāsāmekaviṃśatirātrataḥ" },
      { type: "verse", number: "30", sanskrit: "दंशः पित्तात्मको दाहतृट्स्फोटज्वरदाहवान् सशोफः कठिनः पाण्डुः कण्डूमान् श्लैष्मिकोल्परुक् वातिकः परुषः श्यावः पर्वभेदादिरुक्करः", text: "daṃśaḥ pittātmako dāhatṛṭsphoṭajvaradāhavān saśophaḥ kaṭhinaḥ pāṇḍuḥ kaṇḍūmān ślaiṣmikolparuk vātikaḥ paruṣaḥ śyāvaḥ parvabhedādirukkaraḥ" },
      { type: "verse", number: "31", sanskrit: "सर्पज्ञानोदितैर्लिङ्गैर्द्दोषोद्रेकं च लक्षयेत्", text: "sarpajñānoditairliṅgairddoṣodrekaṃ ca lakṣayet" },
      { type: "verse", number: "32", sanskrit: "त्रिदोषाः प्रायशः सर्वा लूताः पित्तकफाधिकाः", text: "tridoṣāḥ prāyaśaḥ sarvā lūtāḥ pittakaphādhikāḥ" },
      { type: "verse", number: "33", sanskrit: "प्राणान्तिकीषु हृन्मोहश्वासहिध्माशिरोग्रहाः श्वेतासिताः पीतरक्ताः पिटकाः श्वयथूद्भवः", text: "prāṇāntikīṣu hṛnmohaśvāsahidhmāśirograhāḥ śvetāsitāḥ pītaraktāḥ piṭakāḥ śvayathūdbhavaḥ" },
      { type: "verse", number: "34", sanskrit: "वेपुथुर्वमथुर्दाहस्तृडान्ध्यं वक्रनासता श्यावोष्ठवक्त्रदन्तत्वं पृष्ठग्रीवावभञ्जनम् पक्वजम्बूसवर्णं च दंशात् स्रवति शोणितम्", text: "veputhurvamathurdāhastṛḍāndhyaṃ vakranāsatā śyāvoṣṭhavaktradantatvaṃ pṛṣṭhagrīvāvabhañjanam pakvajambūsavarṇaṃ ca daṃśāt sravati śoṇitam" },
      { type: "verse", number: "35", sanskrit: "अथाशु लूतादष्टस्य शस्त्रेणादंशमुद्धरेत् दहेत् जांबवोष्ठाद्यैर्न तु पित्तोत्तरं दहेत्", text: "athāśu lūtādaṣṭasya śastreṇādaṃśamuddharet dahet jāṃbavoṣṭhādyairna tu pittottaraṃ dahet" },
      { type: "verse", number: "36", sanskrit: "कर्कशं भिन्नरोमाणं मर्मसन्ध्यादिसांश्रितम् प्रसृतं सर्वतो दंशं न छिन्दीत दहेत् वा", text: "karkaśaṃ bhinnaromāṇaṃ marmasandhyādisāṃśritam prasṛtaṃ sarvato daṃśaṃ na chindīta dahet vā" },
      { type: "verse", number: "37", sanskrit: "लेपयेद्दग्धमगदैर्मधुसैन्धवसंयुतैः सुशीतैः सेचयेच्चानु कषायैः क्षीरिवृक्षजैः", text: "lepayeddagdhamagadairmadhusaindhavasaṃyutaiḥ suśītaiḥ secayeccānu kaṣāyaiḥ kṣīrivṛkṣajaiḥ" },
      { type: "verse", number: "38", sanskrit: "सर्वतोपहरेद्रक्तं शृङ्गाद्यैः सिरयापि वा स्रुते रक्ते परीषेको घृतक्षीरादिभिर्हितः", text: "sarvatopaharedraktaṃ śṛṅgādyaiḥ sirayāpi vā srute rakte parīṣeko ghṛtakṣīrādibhirhitaḥ" },
      { type: "verse", number: "39", sanskrit: "प्रपौण्डरीकद्द्रीबेरसारिवोशीरजीवकाः लोध्रचन्दनजीवन्तीमञ्जिष्ठासर्जवञ्जुलाः", text: "prapauṇḍarīkaddrīberasārivośīrajīvakāḥ lodhracandanajīvantīmañjiṣṭhāsarjavañjulāḥ" },
      { type: "verse", number: "40", sanskrit: "मृणालबिसशैवालकुमुदोत्पलगैरिकाः न्यग्रोधोदुम्बराश्वत्थनिचुलप्लक्षवेतसाः", text: "mṛṇālabisaśaivālakumudotpalagairikāḥ nyagrodhodumbarāśvatthaniculaplakṣavetasāḥ" },
      { type: "verse", number: "41", sanskrit: "समङ्गापाटलीगुन्द्राकाकोलीशतपर्विकाः शिरीषधातकीमूर्वाविदारीपद्मकिंशुकाः", text: "samaṅgāpāṭalīgundrākākolīśataparvikāḥ śirīṣadhātakīmūrvāvidārīpadmakiṃśukāḥ" },
      { type: "verse", number: "42", sanskrit: "शृङ्गाटकं कोशवतीवायसीसोमराजयः मधुकांशुमतीमूर्वा यथालाभं समाहृताः शस्तः पर्युषितो लेपः सघृतः पैत्तिके वर्णे", text: "śṛṅgāṭakaṃ kośavatīvāyasīsomarājayaḥ madhukāṃśumatīmūrvā yathālābhaṃ samāhṛtāḥ śastaḥ paryuṣito lepaḥ saghṛtaḥ paittike varṇe" },
      { type: "verse", number: "43", sanskrit: "श्यामाद्वयनिशामुस्तानखरास्नामहासहाः वासापत्तङ्गसुवहानाकुलीगिरिकर्णिकाः", text: "śyāmādvayaniśāmustānakharāsnāmahāsahāḥ vāsāpattaṅgasuvahānākulīgirikarṇikāḥ" },
      { type: "verse", number: "44", sanskrit: "सर्पगन्धायवफलानिर्गुण्ड्यश्मन्तकस्थिराः शुकाख्या महिषक्रान्ता कुष्ठेन्द्रयवकुङ्कुमम्", text: "sarpagandhāyavaphalānirguṇḍyaśmantakasthirāḥ śukākhyā mahiṣakrāntā kuṣṭhendrayavakuṅkumam" },
      { type: "verse", number: "45", sanskrit: "करवीरागरुनतं सुगन्धा सिन्दुवारकम् आस्फोटगुन्द्रा च हिता प्रलेपः श्लैष्मिके विषे", text: "karavīrāgarunataṃ sugandhā sinduvārakam āsphoṭagundrā ca hitā pralepaḥ ślaiṣmike viṣe" },
      { type: "verse", number: "46", sanskrit: "बिम्बीविदुलबन्धूककोविदारपलाशकाः सुवहारिष्टकब्राह्मीगुडूचीविश्वसैर्यकाः", text: "bimbīvidulabandhūkakovidārapalāśakāḥ suvahāriṣṭakabrāhmīguḍūcīviśvasairyakāḥ" },
      { type: "verse", number: "47", sanskrit: "सिद्धार्थका देवदारु विडङ्गानीन्द्रवारुणी शतावरीलाङ्गलिकीराजवृक्षपुनर्नवाः", text: "siddhārthakā devadāru viḍaṅgānīndravāruṇī śatāvarīlāṅgalikīrājavṛkṣapunarnavāḥ" },
      { type: "verse", number: "48", sanskrit: "जीवन्ती वायसी भार्ङ्गी कतकेन्द्रयवार्जुनाः मिसिव्याघ्रपदीसिंहपुच्छीमण्डलपर्णिकाः", text: "jīvantī vāyasī bhārṅgī katakendrayavārjunāḥ misivyāghrapadīsiṃhapucchīmaṇḍalaparṇikāḥ" },
      { type: "verse", number: "49", sanskrit: "श्वदंष्ट्रा कोलबृहती रेवती श्वेतपुष्पिका प्रपुन्नाटः कुरवकः प्रलेपो वातिके विषे", text: "śvadaṃṣṭrā kolabṛhatī revatī śvetapuṣpikā prapunnāṭaḥ kuravakaḥ pralepo vātike viṣe" },
      { type: "verse", number: "50", sanskrit: "सर्वत्रैव च शस्यन्ते बोधिश्लेष्मातकाक्षकाः", text: "sarvatraiva ca śasyante bodhiśleṣmātakākṣakāḥ" },
      { type: "verse", number: "51", sanskrit: "उदीर्णदोषान् बलिनो विषे महति वाभयेन् काकण्डकीकोशवती लोध्रेन्द्रयवसैन्धवैः", text: "udīrṇadoṣān balino viṣe mahati vābhayen kākaṇḍakīkośavatī lodhrendrayavasaindhavaiḥ" },
      { type: "verse", number: "52", sanskrit: "पटोलपत्रमरिचकरघाटप्रियङ्गुभिः कृष्णाशुकनसानीपनिम्बसप्ताह्वयष्टिभिः", text: "paṭolapatramaricakaraghāṭapriyaṅgubhiḥ kṛṣṇāśukanasānīpanimbasaptāhvayaṣṭibhiḥ" },
      { type: "verse", number: "53", sanskrit: "विरेचयेच्च त्रिफलात्रिवृत्त्रिकटुसैन्धवैः सदन्तीपूगमृद्वीका विडङ्गैरथवा पचेत् एभिः पलार्धिकैः प्रस्थं समब्राह्मीरसं घृतात्", text: "virecayecca triphalātrivṛttrikaṭusaindhavaiḥ sadantīpūgamṛdvīkā viḍaṅgairathavā pacet ebhiḥ palārdhikaiḥ prasthaṃ samabrāhmīrasaṃ ghṛtāt" },
      { type: "verse", number: "54", sanskrit: "पञ्चमूलशृतं क्षीरं तोयं वा शोधनौषधैः यथास्वं कल्कितैर्युक्तं पृथग्दद्याद्विरेचनम्", text: "pañcamūlaśṛtaṃ kṣīraṃ toyaṃ vā śodhanauṣadhaiḥ yathāsvaṃ kalkitairyuktaṃ pṛthagdadyādvirecanam" },
      { type: "verse", number: "55", sanskrit: "पिप्पलीपिप्पलीमूलशुण्ठीन्द्रयवसैन्धवैः पाठाजमोदायष्ट्याह्वमुस्तासर्षपदारुभिः", text: "pippalīpippalīmūlaśuṇṭhīndrayavasaindhavaiḥ pāṭhājamodāyaṣṭyāhvamustāsarṣapadārubhiḥ" },
      { type: "verse", number: "56", sanskrit: "लघुना पञ्चमूलेन सरलेन च साधिता पेया संसर्जने योज्या सघृता विषनाशिनी", text: "laghunā pañcamūlena saralena ca sādhitā peyā saṃsarjane yojyā saghṛtā viṣanāśinī" },
      { type: "verse", number: "57", sanskrit: "आध्मानहिध्माश्वासेषु पृष्ठग्रीवावभञ्जने सङ्कोचस्तम्भकम्पेषु शूलेष्वर्धावभेदके", text: "ādhmānahidhmāśvāseṣu pṛṣṭhagrīvāvabhañjane saṅkocastambhakampeṣu śūleṣvardhāvabhedake" },
      { type: "verse", number: "58", sanskrit: "वातरोगेषु चान्येषु पर्वभेदार्दितादिषु एरण्डविल्वसरलचिरिविल्वार्कपाटलीः", text: "vātarogeṣu cānyeṣu parvabhedārditādiṣu eraṇḍavilvasaralacirivilvārkapāṭalīḥ" },
      { type: "verse", number: "59", sanskrit: "शिग्रुपाठा कुशवृषं विदुलं च जले पचेत् कनीयः पश्चमूलं च तस्मिन् मण्डं पचेत् घृतात्", text: "śigrupāṭhā kuśavṛṣaṃ vidulaṃ ca jale pacet kanīyaḥ paścamūlaṃ ca tasmin maṇḍaṃ pacet ghṛtāt" },
      { type: "verse", number: "60", sanskrit: "द्विगुणे तुल्यगोक्षीरे पिष्टैर्यष्टीनिशानतैः सुराह्ववेल्लसरलशताह्वालोध्रगैरिकैः", text: "dviguṇe tulyagokṣīre piṣṭairyaṣṭīniśānataiḥ surāhvavellasaralaśatāhvālodhragairikaiḥ" },
      { type: "verse", number: "61", sanskrit: "पयस्याकुष्ठागाङ्गेयीकृष्णामदनसैन्धवैः बस्तौ प्रत्यागतेश्नीयात् पञ्चमूलान्वितैः रसैः", text: "payasyākuṣṭhāgāṅgeyīkṛṣṇāmadanasaindhavaiḥ bastau pratyāgateśnīyāt pañcamūlānvitaiḥ rasaiḥ" },
      { type: "verse", number: "62", sanskrit: "नावनं गौरवे शोफे लालास्रावे हनुग्रहे गिरिकर्णी फलसरो बन्धूकं किणिही सिता", text: "nāvanaṃ gaurave śophe lālāsrāve hanugrahe girikarṇī phalasaro bandhūkaṃ kiṇihī sitā" },
      { type: "verse", number: "63", sanskrit: "षड्ग्रन्थालशुनव्योषबृहतीवेल्लसैन्धवम् अपामार्गफलं भार्ङ्गी नाकुली सर्पगन्धिका", text: "ṣaḍgranthālaśunavyoṣabṛhatīvellasaindhavam apāmārgaphalaṃ bhārṅgī nākulī sarpagandhikā" },
      { type: "verse", number: "64", sanskrit: "श्यामा यवफला बीजं फणिज्जकशिरीषयोः वार्ताकरसपिष्टानि नस्यं विषहरं परम्", text: "śyāmā yavaphalā bījaṃ phaṇijjakaśirīṣayoḥ vārtākarasapiṣṭāni nasyaṃ viṣaharaṃ param" },
      { type: "verse", number: "65", sanskrit: "विरिक्तशिरसश्चास्य सर्पिर्मण्डोनु नावनम्", text: "viriktaśirasaścāsya sarpirmaṇḍonu nāvanam" },
      { type: "verse", number: "66", sanskrit: "नेत्रोपरोधश्वयथुकण्डूनिद्रासमागमे वचामनोह्वात्रिकटुत्रिफलालोध्रगैरिकाः", text: "netroparodhaśvayathukaṇḍūnidrāsamāgame vacāmanohvātrikaṭutriphalālodhragairikāḥ" },
      { type: "verse", number: "67", sanskrit: "शङ्खो नीलोत्पलं ताम्रं हेम प्रवालकम् जीवन्ती लशुनं कुष्ठं कतकं मार्कवं नतम्", text: "śaṅkho nīlotpalaṃ tāmraṃ hema pravālakam jīvantī laśunaṃ kuṣṭhaṃ katakaṃ mārkavaṃ natam" },
      { type: "verse", number: "68", sanskrit: "प्रपैण्डरीकं मधुकं करञ्जफलसैन्धवम् निशे फणिज्जकं तुत्थं स्रोतोञ्जनरसाञ्जने मेषशृङ्गयाश्च कुसुमं पिष्टं गोवारिणाञ्जनम्", text: "prapaiṇḍarīkaṃ madhukaṃ karañjaphalasaindhavam niśe phaṇijjakaṃ tutthaṃ srotoñjanarasāñjane meṣaśṛṅgayāśca kusumaṃ piṣṭaṃ govāriṇāñjanam" },
      { type: "verse", number: "69", sanskrit: "सुरसप्रसवव्योषविल्वमूलसुराह्वयम् हरिद्रा छागलीमूत्रं लूताकीटघ्नमञ्जनम्", text: "surasaprasavavyoṣavilvamūlasurāhvayam haridrā chāgalīmūtraṃ lūtākīṭaghnamañjanam" },
      { type: "verse", number: "70", sanskrit: "शिरीषपद्मकोशीरपाटलीसिन्दुवारकम् क्षीरिशुङ्गनतोदीच्यसारिवाकुष्ठचन्दनम्", text: "śirīṣapadmakośīrapāṭalīsinduvārakam kṣīriśuṅganatodīcyasārivākuṣṭhacandanam" },
      { type: "verse", number: "71", sanskrit: "शेलुस्वरसपिष्टोयमगदो नावनेञ्जने पाने प्रलेपे सेके च लूतासु परमं हितः", text: "śelusvarasapiṣṭoyamagado nāvaneñjane pāne pralepe seke ca lūtāsu paramaṃ hitaḥ" },
      { type: "verse", number: "72", sanskrit: "पयस्या मधुमृद्वीकाश्वदंष्ट्राक्षीरमोरटाः गोजीविदारीयष्ट्याह्वमधुकानि च तद्गुणः", text: "payasyā madhumṛdvīkāśvadaṃṣṭrākṣīramoraṭāḥ gojīvidārīyaṣṭyāhvamadhukāni ca tadguṇaḥ" },
      { type: "verse", number: "73", sanskrit: "तथा शिरीषकुसुमं चन्द्रलेखोद्भवं फलम् सुराला कटभी जातिः श्वेता च गिरिकर्णिका", text: "tathā śirīṣakusumaṃ candralekhodbhavaṃ phalam surālā kaṭabhī jātiḥ śvetā ca girikarṇikā" },
      { type: "verse", number: "74", sanskrit: "तद्वच्च युञ्ज्यात्तगरकुष्ठनागबलाबलाः", text: "tadvacca yuñjyāttagarakuṣṭhanāgabalābalāḥ" },
      { type: "verse", number: "75", sanskrit: "हरिद्रायुगलं नागदन्ती लोध्रं च शाबरम् शिरीषपुष्पं तगरं सहदेवा शतावरी", text: "haridrāyugalaṃ nāgadantī lodhraṃ ca śābaram śirīṣapuṣpaṃ tagaraṃ sahadevā śatāvarī" },
      { type: "verse", number: "76", sanskrit: "पुनर्नवा नागबला सर्पगन्धा कुटन्नटम् गवादनी दन्तशठसोमवल्केन्दुराजयः विषेषु सर्वेष्वगदः सक्षौद्रः सर्वकर्मकृत्", text: "punarnavā nāgabalā sarpagandhā kuṭannaṭam gavādanī dantaśaṭhasomavalkendurājayaḥ viṣeṣu sarveṣvagadaḥ sakṣaudraḥ sarvakarmakṛt" },
      { type: "verse", number: "77", sanskrit: "सर्पाक्षी चन्दनं वक्रं मृगाक्षी गन्धनाकुली एला महासुगन्धा च बस्तमूत्रेण कल्कितः लेपे पाने च लूतासु नानेन सदृशोगदः", text: "sarpākṣī candanaṃ vakraṃ mṛgākṣī gandhanākulī elā mahāsugandhā ca bastamūtreṇa kalkitaḥ lepe pāne ca lūtāsu nānena sadṛśogadaḥ" },
      { type: "verse", number: "78", sanskrit: "कटभीमूलतगरसमङ्गोदवदारुभिः बृहतीद्वयगाङ्गेयीरोचनाचन्दनैर्घृतम्", text: "kaṭabhīmūlatagarasamaṅgodavadārubhiḥ bṛhatīdvayagāṅgeyīrocanācandanairghṛtam" },
      { type: "verse", number: "79", sanskrit: "सिद्धं चतुर्गुणक्षीरं पानाभ्यञ्जनयोर्हितम् लूताकणभकीटानां विषे परमदारुणे", text: "siddhaṃ caturguṇakṣīraṃ pānābhyañjanayorhitam lūtākaṇabhakīṭānāṃ viṣe paramadāruṇe" },
      { type: "verse", number: "80", sanskrit: "निवृत्ते दाहशोफादौ कर्णिकां पातयेद्व्रणात्", text: "nivṛtte dāhaśophādau karṇikāṃ pātayedvraṇāt" },
      { type: "verse", number: "81", sanskrit: "कुसुम्भपुष्पं गोदन्तः स्वर्णक्षीरी कपोतविट् त्रिवृता सैन्धवं दन्ती कर्णिकापातनं तथा", text: "kusumbhapuṣpaṃ godantaḥ svarṇakṣīrī kapotaviṭ trivṛtā saindhavaṃ dantī karṇikāpātanaṃ tathā" },
      { type: "verse", number: "82", sanskrit: "हरिद्रा गुग्गुलुः किण्वं वंशलेखः कपोतविड् तद्वच्च सैन्धवं कुष्ठं दन्तीकटुकदौग्धिकम् राजक्रोशातकीमूलं किण्वो वा मथितोद्भवः", text: "haridrā gugguluḥ kiṇvaṃ vaṃśalekhaḥ kapotaviḍ tadvacca saindhavaṃ kuṣṭhaṃ dantīkaṭukadaugdhikam rājakrośātakīmūlaṃ kiṇvo vā mathitodbhavaḥ" },
      { type: "verse", number: "83", sanskrit: "कर्णिकापातसमये बृंहयेत विषापहैः", text: "karṇikāpātasamaye bṛṃhayeta viṣāpahaiḥ" },
      { type: "verse", number: "84", sanskrit: "ऋतुकाले च लूतानां यावन्तः शुक्रविन्दवः देहे पतन्ति तावत्यो जायन्ते कर्णिकाः समम्", text: "ṛtukāle ca lūtānāṃ yāvantaḥ śukravindavaḥ dehe patanti tāvatyo jāyante karṇikāḥ samam" },
      { type: "verse", number: "85", sanskrit: "गोदन्तदन्ती त्रिवृता हरिद्रे सैन्धवं तिलाः मधुकं निम्बपत्राणि घृतं च व्रणशोधनम्", text: "godantadantī trivṛtā haridre saindhavaṃ tilāḥ madhukaṃ nimbapatrāṇi ghṛtaṃ ca vraṇaśodhanam" },
      { type: "verse", number: "86", sanskrit: "कान्ताविडङ्गखदिरनिम्बकम्पिल्लकाम्बुदैः सर्जैलाधातकीलोहैः सिद्धं सर्पिर्व्रणापहम्", text: "kāntāviḍaṅgakhadiranimbakampillakāmbudaiḥ sarjailādhātakīlohaiḥ siddhaṃ sarpirvraṇāpaham" },
      { type: "verse", number: "87", sanskrit: "शिरीषकटभीशेलुक्षीरिवृक्षार्जुनत्वचः कल्कचूर्णपरीषेकैः कीटलूताव्रणापहाः", text: "śirīṣakaṭabhīśelukṣīrivṛkṣārjunatvacaḥ kalkacūrṇaparīṣekaiḥ kīṭalūtāvraṇāpahāḥ" },
      { type: "verse", number: "88", sanskrit: "शताह्वालोध्रकासीसदार्वीजम्ब्वस्थिरोचनाः हरीतकी पूगफलं चूर्णोयं व्रणरोपणः", text: "śatāhvālodhrakāsīsadārvījambvasthirocanāḥ harītakī pūgaphalaṃ cūrṇoyaṃ vraṇaropaṇaḥ" },
      { type: "verse", number: "89", sanskrit: "लाक्षा रजन्यौ मञ्जिष्ठा हरितालं मनश्शिला सर्पिर्मधु च लेपोयं त्वग्विशुद्धिकरः परम्", text: "lākṣā rajanyau mañjiṣṭhā haritālaṃ manaśśilā sarpirmadhu ca lepoyaṃ tvagviśuddhikaraḥ param" },
      { type: "verse", number: "90", sanskrit: "रोमसञ्जननं कुर्याद्यदुक्तं व्रणसाधने", text: "romasañjananaṃ kuryādyaduktaṃ vraṇasādhane" },
      { type: "verse", number: "91", sanskrit: "स्नेहकार्यमशेषं च सर्पिषैव समाचरेत् विषस्य वृद्धये तैलमग्नेरिव तृणोलपम्", text: "snehakāryamaśeṣaṃ ca sarpiṣaiva samācaret viṣasya vṛddhaye tailamagneriva tṛṇolapam" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 45,
    lang: "sa",
    content: [
      { type: "heading", heading: "Малтта санграха — об отходах тела" },
      { type: "text", text: "Глава 45 Уттара стханы — «Малтта санграха» — посвящена специализированному разделу: об отходах тела. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातः प्रत्येकलूताप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athātaḥ pratyekalūtāpratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "आदंशे पिटका ताम्रा भवेत् कपिलया स्थिरा लसीका रोमकूपेषु दाहो ऽक्ष्णो मूर्ध्नि गौरवम्", text: "ādaṃśe piṭakā tāmrā bhavet kapilayā sthirā lasīkā romakūpeṣu dāho 'kṣṇo mūrdhni gauravam" },
      { type: "verse", number: "3", sanskrit: "पाननस्याञ्जनालेपसेकेष्वत्र प्रयोजयेत् निशापद्मककुष्ठैलाकरञ्जककुभत्वचः", text: "pānanasyāñjanālepasekeṣvatra prayojayet niśāpadmakakuṣṭhailākarañjakakubhatvacaḥ" },
      { type: "verse", number: "4", sanskrit: "स्थिरार्कपर्ण्यपामार्गब्राह्मीज्वलननाकुलीः अथवा कुष्ठपत्तङ्गनखजोङ्गककुङ्कुमम्", text: "sthirārkaparṇyapāmārgabrāhmījvalananākulīḥ athavā kuṣṭhapattaṅganakhajoṅgakakuṅkumam" },
      { type: "verse", number: "5", sanskrit: "अग्निमुख्यातिरुक्स्फोटः सम्भवत्यग्निदग्धवत् अग्निज्वालासमानेन प्रस्विद्यति विषोष्मणा", text: "agnimukhyātiruksphoṭaḥ sambhavatyagnidagdhavat agnijvālāsamānena prasvidyati viṣoṣmaṇā" },
      { type: "verse", number: "6", sanskrit: "तृड्दाहकम्पमूर्च्छावान् पित्तास्रमतिसार्यते योजयेत् पूर्ववत्तत्र प्रत्याख्याय त्वरान्वितः", text: "tṛḍdāhakampamūrcchāvān pittāsramatisāryate yojayet pūrvavattatra pratyākhyāya tvarānvitaḥ" },
      { type: "verse", number: "7", sanskrit: "कुष्ठलामज्जकोशीरमधूकं मधुकं मधु लाभतः शीतवीर्याणि तालीसं गोपकन्यकाम्", text: "kuṣṭhalāmajjakośīramadhūkaṃ madhukaṃ madhu lābhataḥ śītavīryāṇi tālīsaṃ gopakanyakām" },
      { type: "verse", number: "8", sanskrit: "पीतया पीतविण्मूत्रदंशक्लेदाक्षिदर्शनम् मूर्च्छाच्छर्दिंशिरोदुःखज्वरारोचकशूलवान्", text: "pītayā pītaviṇmūtradaṃśakledākṣidarśanam mūrcchācchardiṃśiroduḥkhajvarārocakaśūlavān" },
      { type: "verse", number: "9", sanskrit: "तत्रेष्टाः कटभोशीरमुञ्जावञ्जुलपद्मकाः वंशकाशार्जुनकुशाः शिरीषकिणिहीत्वचः अथवा वन्यबाल्हीककुष्ठकेसरजोङ्गफम्", text: "tatreṣṭāḥ kaṭabhośīramuñjāvañjulapadmakāḥ vaṃśakāśārjunakuśāḥ śirīṣakiṇihītvacaḥ athavā vanyabālhīkakuṣṭhakesarajoṅgapham" },
      { type: "verse", number: "10", sanskrit: "पद्माभः पद्मया स्फोटो भिन्नो ऽभिन्नः पुनर्भवेत् क्लिद्यत्याशु स्रवत्युष्णं क्लेदं स्पर्शे ऽतिरुक्करः", text: "padmābhaḥ padmayā sphoṭo bhinno 'bhinnaḥ punarbhavet klidyatyāśu sravatyuṣṇaṃ kledaṃ sparśe 'tirukkaraḥ" },
      { type: "verse", number: "11", sanskrit: "तत्र पद्मोत्पलान्नालो हिमवेतसवञ्जुलाः समृणालाः सकुमुदाः सक्षौद्रघृतशर्कराः", text: "tatra padmotpalānnālo himavetasavañjulāḥ samṛṇālāḥ sakumudāḥ sakṣaudraghṛtaśarkarāḥ" },
      { type: "verse", number: "12", sanskrit: "पूतिर्मूत्रविषादंशो विसर्पी कृष्णशोणितः श्वासकासज्वरच्छर्दिंमूर्छादाहभ्रमान्वितः", text: "pūtirmūtraviṣādaṃśo visarpī kṛṣṇaśoṇitaḥ śvāsakāsajvaracchardiṃmūrchādāhabhramānvitaḥ" },
      { type: "verse", number: "13", sanskrit: "मनश्शिलालमधुकमधूकोत्पलचन्दनम् कुष्ठालामज्जकोशीरपद्मकं तत्र भेषजम्", text: "manaśśilālamadhukamadhūkotpalacandanam kuṣṭhālāmajjakośīrapadmakaṃ tatra bheṣajam" },
      { type: "verse", number: "14", sanskrit: "आदंशे श्वेतया श्वेता पिटका भृशकण्डुला दाहमूर्छाज्वररुजाविसर्पक्लेदकारिणी", text: "ādaṃśe śvetayā śvetā piṭakā bhṛśakaṇḍulā dāhamūrchājvararujāvisarpakledakāriṇī" },
      { type: "verse", number: "15", sanskrit: "तत्रेष्टाः शीतरास्नैलाहरेणुनलवञ्जुलाः कुष्ठमांसीनतोशीरकान्ताध्यामकपद्मकाः", text: "tatreṣṭāḥ śītarāsnailāhareṇunalavañjulāḥ kuṣṭhamāṃsīnatośīrakāntādhyāmakapadmakāḥ" },
      { type: "verse", number: "16", sanskrit: "आदंशः कृष्णया कृष्णो विङ्गन्धिः क्लेदशोफवान् उत्थाप्यते कृष्णमसृग्दुष्टं तत्र च भेषजम् महासुगन्धा सर्पक्षी वक्रैला गन्धनाकुली", text: "ādaṃśaḥ kṛṣṇayā kṛṣṇo viṅgandhiḥ kledaśophavān utthāpyate kṛṣṇamasṛgduṣṭaṃ tatra ca bheṣajam mahāsugandhā sarpakṣī vakrailā gandhanākulī" },
      { type: "verse", number: "17", sanskrit: "शूनः पाण्डूरया दंशः शोफो वक्त्रस्य गौरवम् ज्वरो विघूर्णनं जृम्भा शिरोरुक् तत्र भेषजम् मूलं वारुणपुष्पाया रोचना गोशकृद्रसः", text: "śūnaḥ pāṇḍūrayā daṃśaḥ śopho vaktrasya gauravam jvaro vighūrṇanaṃ jṛmbhā śiroruk tatra bheṣajam mūlaṃ vāruṇapuṣpāyā rocanā gośakṛdrasaḥ" },
      { type: "verse", number: "18", sanskrit: "आपाण्डुपिटको दंशः शोफवान् रक्तपादया अस्रस्रुत्तत्र नलदसेव्योदीच्यहिमं मधु", text: "āpāṇḍupiṭako daṃśaḥ śophavān raktapādayā asrasruttatra naladasevyodīcyahimaṃ madhu" },
      { type: "verse", number: "19", sanskrit: "भृङ्गाभो भृङ्गया दंशः पिटका दाहरुक्करी कोठैश्च चीयते गात्रं तत्र शस्तं भिषग्जितम् अङ्कोलसारः फलिनी गवां पित्तं मिसिर्गदः", text: "bhṛṅgābho bhṛṅgayā daṃśaḥ piṭakā dāharukkarī koṭhaiśca cīyate gātraṃ tatra śastaṃ bhiṣagjitam aṅkolasāraḥ phalinī gavāṃ pittaṃ misirgadaḥ" },
      { type: "verse", number: "20", sanskrit: "पिङ्गया वह्निदग्धाभो दंशः स्फोटो बहुस्रुतिः तीब्रशोफज्वररुजाहृत्पीडादाहतृङ्युतः", text: "piṅgayā vahnidagdhābho daṃśaḥ sphoṭo bahusrutiḥ tībraśophajvararujāhṛtpīḍādāhatṛṅyutaḥ" },
      { type: "verse", number: "21", sanskrit: "तत्रागदः सिता गुन्द्रा मल्लिका मधुकोत्पलम् जीवंकः क्षीरिणां शुङ्गा द्विहिमं नागकेसरम्", text: "tatrāgadaḥ sitā gundrā mallikā madhukotpalam jīvaṃkaḥ kṣīriṇāṃ śuṅgā dvihimaṃ nāgakesaram" },
      { type: "verse", number: "22", sanskrit: "त्रिमण्डलाया बहलो दंशः कृष्णं स्रवत्यसृक् अरुचिर्नेत्रयोर्दाहः कलुषस्रुतिदृष्टिता", text: "trimaṇḍalāyā bahalo daṃśaḥ kṛṣṇaṃ sravatyasṛk arucirnetrayordāhaḥ kaluṣasrutidṛṣṭitā" },
      { type: "verse", number: "23", sanskrit: "विविधैर्मण्डलैश्चास्य शरीरमुपचीयते तत्रार्कमूलद्विनिशासुरालापृश्निपर्णिकाः दधित्थनाकुलीब्राह्मीज्योतिष्मत्यो हितो ऽगदः", text: "vividhairmaṇḍalaiścāsya śarīramupacīyate tatrārkamūladviniśāsurālāpṛśniparṇikāḥ dadhitthanākulībrāhmījyotiṣmatyo hito 'gadaḥ" },
      { type: "verse", number: "24", sanskrit: "आदंशः पूतिगन्धाया विसर्पक्लेददाहवान् अलजीसन्निभो रुग्वान् विबद्धपिटकाचितः", text: "ādaṃśaḥ pūtigandhāyā visarpakledadāhavān alajīsannibho rugvān vibaddhapiṭakācitaḥ" },
      { type: "verse", number: "25", sanskrit: "भार्ङ्गीनिदिग्धिकानिम्बपाटलीसिन्दुवारकम् दूर्वा हरिद्रे वासा च पूतिगन्धाविषापहम्", text: "bhārṅgīnidigdhikānimbapāṭalīsinduvārakam dūrvā haridre vāsā ca pūtigandhāviṣāpaham" },
      { type: "verse", number: "26", sanskrit: "चित्रमण्डलवान् दंशः पिटकाजालकावृतः वीराया मूर्धरुक् शीतज्वरान्नद्वेषसंयुतः", text: "citramaṇḍalavān daṃśaḥ piṭakājālakāvṛtaḥ vīrāyā mūrdharuk śītajvarānnadveṣasaṃyutaḥ" },
      { type: "verse", number: "27", sanskrit: "हरिद्रे नलदं कुष्ठमेला सुरसमञ्जरी तगरं च श्वपित्तेन पिष्टं वीराविषापहम्", text: "haridre naladaṃ kuṣṭhamelā surasamañjarī tagaraṃ ca śvapittena piṣṭaṃ vīrāviṣāpaham" },
      { type: "verse", number: "28", sanskrit: "दंशः कुमुदया दाहस्फोटस्फुरणतोदवान् पिच्छिलक्लेदविस्रावी सश्वासस्सगलग्रहः प्रत्याख्यायात्र कुर्वीत सामान्योक्तं क्रियाक्रमम्", text: "daṃśaḥ kumudayā dāhasphoṭasphuraṇatodavān picchilakledavisrāvī saśvāsassagalagrahaḥ pratyākhyāyātra kurvīta sāmānyoktaṃ kriyākramam" },
      { type: "verse", number: "29", sanskrit: "भवन्त्यलविषादंशे पीतलोहितमण्डलाः पिटकाः सर्षपप्रख्यास्तालुशोषो रुजा ज्वरः", text: "bhavantyalaviṣādaṃśe pītalohitamaṇḍalāḥ piṭakāḥ sarṣapaprakhyāstāluśoṣo rujā jvaraḥ" },
      { type: "verse", number: "30", sanskrit: "छर्दिर्दाहः शिरःकम्पस्तत्र सेव्यः समाक्षिकः सकासीसकह्रीबेरः सपिप्पलिवटाङ्कुरः", text: "chardirdāhaḥ śiraḥkampastatra sevyaḥ samākṣikaḥ sakāsīsakahrīberaḥ sapippalivaṭāṅkuraḥ" },
      { type: "verse", number: "31", sanskrit: "रक्तान्तो रक्तया दंशः सपाण्डुपिटकाज्वरः श्वेतोतिसारः श्वसनं दाहः क्लेदः सशोणितः शस्तं शेल्वर्जुनाम्रातात्त्वङ्मूलं सिन्दुवारतः", text: "raktānto raktayā daṃśaḥ sapāṇḍupiṭakājvaraḥ śvetotisāraḥ śvasanaṃ dāhaḥ kledaḥ saśoṇitaḥ śastaṃ śelvarjunāmrātāttvaṅmūlaṃ sinduvārataḥ" },
      { type: "verse", number: "32", sanskrit: "आदंशे चित्रया रक्ता पिटका विसृता स्थिरा पर्वभेदशिरस्तापज्वरशोफा विसर्पिणी", text: "ādaṃśe citrayā raktā piṭakā visṛtā sthirā parvabhedaśirastāpajvaraśophā visarpiṇī" },
      { type: "verse", number: "33", sanskrit: "भिन्ना कृष्णत्वमभ्येति पीतास्रावा महाव्रणा तत्रेष्टाः कुष्ठनलदशिरीषनलरेणुकाः", text: "bhinnā kṛṣṇatvamabhyeti pītāsrāvā mahāvraṇā tatreṣṭāḥ kuṣṭhanaladaśirīṣanalareṇukāḥ" },
      { type: "verse", number: "34", sanskrit: "दंशे च सन्तानिकया शूलमाकुलताश्रुणः प्रदराक्षेपकौ तत्र केसरं क्षीरिणां त्वचः आम्रस्य सिन्दुवारस्य मूलमश्मन्तकस्य च", text: "daṃśe ca santānikayā śūlamākulatāśruṇaḥ pradarākṣepakau tatra kesaraṃ kṣīriṇāṃ tvacaḥ āmrasya sinduvārasya mūlamaśmantakasya ca" },
      { type: "verse", number: "35", sanskrit: "पिटका मेचका दंशमध्ये जतुकणोपमा ज्वरः शोफोत्र वारुण्यां रोचना रजनीद्वयम्", text: "piṭakā mecakā daṃśamadhye jatukaṇopamā jvaraḥ śophotra vāruṇyāṃ rocanā rajanīdvayam" },
      { type: "verse", number: "36", sanskrit: "राजीमान् कसनादंशः शिरोरुक् श्वासकासवान् शीतपिच्छिलरक्तस्रुद्रक्तोकं तत्र मेषजम्", text: "rājīmān kasanādaṃśaḥ śiroruk śvāsakāsavān śītapicchilaraktasrudraktokaṃ tatra meṣajam" },
      { type: "verse", number: "37", sanskrit: "पाण्डुरक्तो ऽतिरुग्दंशः काकाण्ड्याः स्मृतिमोषकृत् हिध्मा श्वसनतृण्मूर्च्छा निद्राक्षेपकहृद्गदाः", text: "pāṇḍurakto 'tirugdaṃśaḥ kākāṇḍyāḥ smṛtimoṣakṛt hidhmā śvasanatṛṇmūrcchā nidrākṣepakahṛdgadāḥ" },
      { type: "verse", number: "38", sanskrit: "रक्तान्तर्स्त्वेणपादाया दंशः कृष्णतिलाकृतिः दाहमोहाग्निवीसर्पतृङ्वमिश्वासकासवान्", text: "raktāntarstveṇapādāyā daṃśaḥ kṛṣṇatilākṛtiḥ dāhamohāgnivīsarpatṛṅvamiśvāsakāsavān" },
      { type: "verse", number: "39", sanskrit: "पूतिः श्यावोतिरुक् सासृगादंशो लाजवर्णया शीतज्वरसमुत्थानो दाहमूर्छातिसारवान्", text: "pūtiḥ śyāvotiruk sāsṛgādaṃśo lājavarṇayā śītajvarasamutthāno dāhamūrchātisāravān" },
      { type: "verse", number: "40", sanskrit: "अग्निदग्धनिभो दंशो वैदेह्या भृशवेदनः गम्भीरः सज्वरस्तीक्ष्णमोहो हृदयपीडनम्", text: "agnidagdhanibho daṃśo vaidehyā bhṛśavedanaḥ gambhīraḥ sajvarastīkṣṇamoho hṛdayapīḍanam" },
      { type: "verse", number: "41", sanskrit: "ऊर्ध्वराजीचितो दंशो जालिन्यास्तीव्रशोफरुक् उदीर्णतृङ्भ्रमश्वासस्तम्भमोहविदीर्यते", text: "ūrdhvarājīcito daṃśo jālinyāstīvraśopharuk udīrṇatṛṅbhramaśvāsastambhamohavidīryate" },
      { type: "verse", number: "42", sanskrit: "रक्तो मालागुणादंशो धूमगन्धिः सपीव्ररुक् दीर्यते पार्श्वतस्तैस्तैः संरब्धैर्मण्डलैर्युतः", text: "rakto mālāguṇādaṃśo dhūmagandhiḥ sapīvraruk dīryate pārśvatastaistaiḥ saṃrabdhairmaṇḍalairyutaḥ" },
      { type: "verse", number: "43", sanskrit: "अन्तर्दाहो बहिः शैत्यमाध्मानं मूत्रकृच्छ्रता मूर्च्छाप्रलापातीसारज्वराः प्राणान्तकारिणः", text: "antardāho bahiḥ śaityamādhmānaṃ mūtrakṛcchratā mūrcchāpralāpātīsārajvarāḥ prāṇāntakāriṇaḥ" },
      { type: "verse", number: "44", sanskrit: "ध्मातः सौवर्णिकादंशः स्यन्दते मत्स्यगन्धिकः शिरोक्षिरुग्ज्वरः कासस्तृणा शोफो वमिर्भ्रमः", text: "dhmātaḥ sauvarṇikādaṃśaḥ syandate matsyagandhikaḥ śirokṣirugjvaraḥ kāsastṛṇā śopho vamirbhramaḥ" },
      { type: "verse", number: "45", sanskrit: "आसाध्यानामपि हितं प्रत्याख्यायाशु योजयेत् दोषोच्छ्रायविशेषेण छेददाहादिवर्जितम्", text: "āsādhyānāmapi hitaṃ pratyākhyāyāśu yojayet doṣocchrāyaviśeṣeṇa chedadāhādivarjitam" },
      { type: "verse", number: "46", sanskrit: "कपिला तत्र नासायामग्निर्दशति जत्रुणि पीता तु गण्डयोः पद्मा दक्षिणांसेथ कक्षयोः", text: "kapilā tatra nāsāyāmagnirdaśati jatruṇi pītā tu gaṇḍayoḥ padmā dakṣiṇāṃsetha kakṣayoḥ" },
      { type: "verse", number: "47", sanskrit: "लूता मूत्रविषा श्वेता चिबुके कालिकाक्षिणि पाण्डुरा दक्षिणस्कन्धे करयो रक्तपादिका", text: "lūtā mūtraviṣā śvetā cibuke kālikākṣiṇi pāṇḍurā dakṣiṇaskandhe karayo raktapādikā" },
      { type: "verse", number: "48", sanskrit: "वामपार्श्वे दशेत् भृङ्गा वामांसे पिङ्गला दशेत् त्रिमण्डलोदरे पूतिः पृष्ठे वीरा तु दक्षिणे", text: "vāmapārśve daśet bhṛṅgā vāmāṃse piṅgalā daśet trimaṇḍalodare pūtiḥ pṛṣṭhe vīrā tu dakṣiṇe" },
      { type: "verse", number: "49", sanskrit: "बाहौ नाभ्यां कुमुदिका वामस्कन्धे ऽलसंज्ञिता कण्ठे रक्ता ललाटे तु चित्रा सन्तानिकौष्ठयोः", text: "bāhau nābhyāṃ kumudikā vāmaskandhe 'lasaṃjñitā kaṇṭhe raktā lalāṭe tu citrā santānikauṣṭhayoḥ" },
      { type: "verse", number: "50", sanskrit: "मेचका मूर्ध्नि कसनाद्धस्तयोः कक्षमूलयोः काकाण्ड्येणी तु हृदये लाजवर्णा स्तनान्तरे", text: "mecakā mūrdhni kasanāddhastayoḥ kakṣamūlayoḥ kākāṇḍyeṇī tu hṛdaye lājavarṇā stanāntare" },
      { type: "verse", number: "51", sanskrit: "बाहुसन्धिषु वैदेही लूतापाङ्गे तु जालिनी मालागुणाख्या ग्रीवायां सौवर्णी कर्णमूलयोः", text: "bāhusandhiṣu vaidehī lūtāpāṅge tu jālinī mālāguṇākhyā grīvāyāṃ sauvarṇī karṇamūlayoḥ" },
      { type: "verse", number: "52", sanskrit: "इति क्षेत्राणि नियतान्यत्युदीर्णविषाः पुनः परक्षेत्रेपि वर्तन्ते राजानोतिबला इव", text: "iti kṣetrāṇi niyatānyatyudīrṇaviṣāḥ punaḥ parakṣetrepi vartante rājānotibalā iva" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 46,
    lang: "sa",
    content: [
      { type: "heading", heading: "Гуна санграха — о качествах" },
      { type: "text", text: "Глава 46 Уттара стханы — «Гуна санграха» — посвящена специализированному разделу: о качествах. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो मूषिकालर्कप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto mūṣikālarkapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "लालनश्चपलः पुत्रो हसिरश्चिकिरो ऽजिनः कषायदन्तः कुलकः कोकिलः कपिलो ऽसितः", text: "lālanaścapalaḥ putro hasiraścikiro 'jinaḥ kaṣāyadantaḥ kulakaḥ kokilaḥ kapilo 'sitaḥ" },
      { type: "verse", number: "3", sanskrit: "अरुणः शबलः श्वेतः कपोतः पलितोन्दुरुः चुच्छुन्दारो रसालाख्यो दशाष्टौ चेति मूषिकाः", text: "aruṇaḥ śabalaḥ śvetaḥ kapotaḥ palitonduruḥ cucchundāro rasālākhyo daśāṣṭau ceti mūṣikāḥ" },
      { type: "verse", number: "4", sanskrit: "यस्मिन्नङ्गे पतत्येषां शुक्रमङ्गैः स्पृशन्ति वा यच्छुक्रदिग्धैस्तत्रास्रे दूषिते पाण्डुतां गते", text: "yasminnaṅge patatyeṣāṃ śukramaṅgaiḥ spṛśanti vā yacchukradigdhaistatrāsre dūṣite pāṇḍutāṃ gate" },
      { type: "verse", number: "5", sanskrit: "ग्रन्थयः श्वयथुः कोठो मण्डलानि भ्रमोरुचिः शीतज्वररोतिरुक्सादो वेपथुः पर्वभेदनम्", text: "granthayaḥ śvayathuḥ koṭho maṇḍalāni bhramoruciḥ śītajvararotiruksādo vepathuḥ parvabhedanam" },
      { type: "verse", number: "6", sanskrit: "रोमहर्षः स्नुतिर्मूर्च्छा दीर्घकालानुबन्धनम् श्लेष्मानुविद्धबह्वाखुपोतकछर्दनं सकृत्", text: "romaharṣaḥ snutirmūrcchā dīrghakālānubandhanam śleṣmānuviddhabahvākhupotakachardanaṃ sakṛt" },
      { type: "verse", number: "7", sanskrit: "व्यवाय्याखुविषं कृच्छ्रं भूयो भूयश्च कुप्यति", text: "vyavāyyākhuviṣaṃ kṛcchraṃ bhūyo bhūyaśca kupyati" },
      { type: "verse", number: "8", sanskrit: "मूर्च्छाङ्गशोफवैवर्ण्यक्लेदशब्दाश्रुतिज्वराः शिरोगुरुत्वं लालासृक्छर्दिश्चासाध्यलक्षणम्", text: "mūrcchāṅgaśophavaivarṇyakledaśabdāśrutijvarāḥ śirogurutvaṃ lālāsṛkchardiścāsādhyalakṣaṇam" },
      { type: "verse", number: "9", sanskrit: "शूनबस्तिं विवर्णौष्ठमाख्वाभैर्ग्रन्थिभिश्चितम् चुच्छुन्दुरुसगन्धं च वर्जयेदाखुदूषितम्", text: "śūnabastiṃ vivarṇauṣṭhamākhvābhairgranthibhiścitam cucchundurusagandhaṃ ca varjayedākhudūṣitam" },
      { type: "verse", number: "10", sanskrit: "शुनः श्लेष्मोल्बणा दोषाः संज्ञां संज्ञावहाश्रिताः मुष्णन्तः कुर्वते क्षोभं धातूनामतिदारुणम्", text: "śunaḥ śleṣmolbaṇā doṣāḥ saṃjñāṃ saṃjñāvahāśritāḥ muṣṇantaḥ kurvate kṣobhaṃ dhātūnāmatidāruṇam" },
      { type: "verse", number: "11", sanskrit: "लालावानन्धबधिरः सर्वतः सोभिधावति स्रस्तपुच्छहनुस्कन्धः शिरोदुःखी नताननः", text: "lālāvānandhabadhiraḥ sarvataḥ sobhidhāvati srastapucchahanuskandhaḥ śiroduḥkhī natānanaḥ" },
      { type: "verse", number: "12", sanskrit: "दंशस्तेन विदष्टस्य सुप्तः कृष्णं क्षरत्यसृक् हृच्छिरोरुग्ज्वरस्तम्भतृष्णामूर्छोद्भवो ऽनु च", text: "daṃśastena vidaṣṭasya suptaḥ kṛṣṇaṃ kṣaratyasṛk hṛcchirorugjvarastambhatṛṣṇāmūrchodbhavo 'nu ca" },
      { type: "verse", number: "13", sanskrit: "अनेनान्येपि बोद्धव्या व्याला दंष्ट्राप्रहारिणः सृगालाश्वतराश्वर्क्षद्वीपिव्याघ्रवृकादयः", text: "anenānyepi boddhavyā vyālā daṃṣṭrāprahāriṇaḥ sṛgālāśvatarāśvarkṣadvīpivyāghravṛkādayaḥ" },
      { type: "verse", number: "14", sanskrit: "कण्डूनिस्तोदवैवर्ण्यसुप्तिक्लेदज्वरभ्रमाः विदाहरागरुक्पाकशोफग्रन्थि विकुञ्चनम्", text: "kaṇḍūnistodavaivarṇyasuptikledajvarabhramāḥ vidāharāgarukpākaśophagranthi vikuñcanam" },
      { type: "verse", number: "15", sanskrit: "दंशावदरणं स्फोटाः कर्णिका मण्डलानि च सर्वत्र सविषे लिङ्गं विपरीतं तु निर्विषे", text: "daṃśāvadaraṇaṃ sphoṭāḥ karṇikā maṇḍalāni ca sarvatra saviṣe liṅgaṃ viparītaṃ tu nirviṣe" },
      { type: "verse", number: "16", sanskrit: "दष्टो येन तु तच्चेष्टारुतं कुर्वन् विनश्यति पश्यंस्तमेव चाकस्मादादर्शसलिलादिषु", text: "daṣṭo yena tu tacceṣṭārutaṃ kurvan vinaśyati paśyaṃstameva cākasmādādarśasalilādiṣu" },
      { type: "verse", number: "17", sanskrit: "जलदर्शनसंस्पर्शशब्देभ्यो यश्च सन्त्रसेत् अदष्टमपि तं जह्याज्जलसन्त्रासरोगिणम्", text: "jaladarśanasaṃsparśaśabdebhyo yaśca santraset adaṣṭamapi taṃ jahyājjalasantrāsarogiṇam" },
      { type: "verse", number: "18", sanskrit: "आखुना दष्टमात्रस्य दंशं काण्डेन दाहयेत् दर्पणेनाथवा तीव्ररुजा स्यात् कर्णिकान्यथा", text: "ākhunā daṣṭamātrasya daṃśaṃ kāṇḍena dāhayet darpaṇenāthavā tīvrarujā syāt karṇikānyathā" },
      { type: "verse", number: "19", sanskrit: "दग्धं विस्रावयेद्दंशं प्रच्छितं च प्रलेपयेत् शिरीषरजनीवक्रकुङ्कुमामृतवल्लिभिः", text: "dagdhaṃ visrāvayeddaṃśaṃ pracchitaṃ ca pralepayet śirīṣarajanīvakrakuṅkumāmṛtavallibhiḥ" },
      { type: "verse", number: "20", sanskrit: "अगारधूममञ्जिष्ठा रजनी लवणोत्तमैः लेपो जयत्याखुविषं कर्णिकायाश्च पातनः", text: "agāradhūmamañjiṣṭhā rajanī lavaṇottamaiḥ lepo jayatyākhuviṣaṃ karṇikāyāśca pātanaḥ" },
      { type: "verse", number: "21", sanskrit: "ततोम्लैः क्षालयित्वा तु तोयैरनु च लेपयेत् पालिन्दी श्वेतकटभी बिल्वमूलगुडूचिभिः अन्यैश्च विषशोफघ्नैः सिरां वा मोक्षयेत् द्रुतम्", text: "tatomlaiḥ kṣālayitvā tu toyairanu ca lepayet pālindī śvetakaṭabhī bilvamūlaguḍūcibhiḥ anyaiśca viṣaśophaghnaiḥ sirāṃ vā mokṣayet drutam" },
      { type: "verse", number: "22", sanskrit: "छर्दनं जालिनीकाथैः शुकाख्याङ्कोलयोरपि कोशवत्याः शुकाख्यायाः फलं जीमूतकस्य च मदनस्य च सञ्चूर्ण्य दध्ना पीत्वा विषं वमेत्", text: "chardanaṃ jālinīkāthaiḥ śukākhyāṅkolayorapi kośavatyāḥ śukākhyāyāḥ phalaṃ jīmūtakasya ca madanasya ca sañcūrṇya dadhnā pītvā viṣaṃ vamet" },
      { type: "verse", number: "23", sanskrit: "वचामदनजीमूतकुष्ठं वा मूत्रपेषितम् पूर्वकल्पेन पातव्यं सर्वोन्दुरुविषापहम्", text: "vacāmadanajīmūtakuṣṭhaṃ vā mūtrapeṣitam pūrvakalpena pātavyaṃ sarvonduruviṣāpaham" },
      { type: "verse", number: "24", sanskrit: "निष्पावाः कदलीमूलं बन्धुजीवफलानि च सुवर्चलारामठकं स्वर्जिकातिविषाद्वयम् श्यामाद्रिकर्णिकामूलमूर्धचैंवमनत्रयम्", text: "niṣpāvāḥ kadalīmūlaṃ bandhujīvaphalāni ca suvarcalārāmaṭhakaṃ svarjikātiviṣādvayam śyāmādrikarṇikāmūlamūrdhacaiṃvamanatrayam" },
      { type: "verse", number: "25", sanskrit: "वान्तस्य शुद्धे हृदये शूलं हिध्मारुचिर्वमिः उष्णोद्गारानुबन्धो वा स्याच्चेत्तत्रैतदौषधम्", text: "vāntasya śuddhe hṛdaye śūlaṃ hidhmārucirvamiḥ uṣṇodgārānubandho vā syāccettatraitadauṣadham" },
      { type: "verse", number: "26", sanskrit: "जीरकं त्र्यूषणं कुष्ठं तुङ्गाख्यं नागकेसरम् रजन्यौ सैन्धवं सेव्यं यष्टीमधुसुवर्चलाम्", text: "jīrakaṃ tryūṣaṇaṃ kuṣṭhaṃ tuṅgākhyaṃ nāgakesaram rajanyau saindhavaṃ sevyaṃ yaṣṭīmadhusuvarcalām" },
      { type: "verse", number: "27", sanskrit: "मधुरं च गणं पिष्ट्वा बीजपूरकपित्थयोः रसेन षाडवं कुर्यान्मधुमत्स्यण्डिकान्वितम् गन्धवर्णरसोपेतः स पीतो विषदोषजित्", text: "madhuraṃ ca gaṇaṃ piṣṭvā bījapūrakapitthayoḥ rasena ṣāḍavaṃ kuryānmadhumatsyaṇḍikānvitam gandhavarṇarasopetaḥ sa pīto viṣadoṣajit" },
      { type: "verse", number: "28", sanskrit: "द्विपिप्पलीद्व्यंशुमतीक्वाथे पेया च तद्गुणा", text: "dvipippalīdvyaṃśumatīkvāthe peyā ca tadguṇā" },
      { type: "verse", number: "29", sanskrit: "विरेचने त्रिवृन्नीलीत्रिफलाकल्क इष्यते शिरोविरेचने सारः शिरीषस्य फलानि च", text: "virecane trivṛnnīlītriphalākalka iṣyate śirovirecane sāraḥ śirīṣasya phalāni ca" },
      { type: "verse", number: "30", sanskrit: "अञ्जने गोमयरसो व्योषसूक्ष्मरजोन्वितः कपित्थगोमयरसो मधुमानवलेहने", text: "añjane gomayaraso vyoṣasūkṣmarajonvitaḥ kapitthagomayaraso madhumānavalehane" },
      { type: "verse", number: "31", sanskrit: "तण्डुलीयकमूलेन सिद्धं पाने हितं घृतम् द्विनिशा कटभी रक्ता यष्ट्याह्वैर्वामृतान्वितैः आस्फोतमूलसिद्धं वा पञ्चकापित्थमेव वा", text: "taṇḍulīyakamūlena siddhaṃ pāne hitaṃ ghṛtam dviniśā kaṭabhī raktā yaṣṭyāhvairvāmṛtānvitaiḥ āsphotamūlasiddhaṃ vā pañcakāpitthameva vā" },
      { type: "verse", number: "32", sanskrit: "अधोभागे विशुद्धस्य शूलं नाभ्यां भवेद्यदि पुरीषं वा विबध्येत गुदे स्याद्वा विकर्तिका", text: "adhobhāge viśuddhasya śūlaṃ nābhyāṃ bhavedyadi purīṣaṃ vā vibadhyeta gude syādvā vikartikā" },
      { type: "verse", number: "33", sanskrit: "तत्र पेयां पिबेच्छीतां शर्करामधुसंयुताम् पिप्पली पिप्पलीमूलसारिवा कटुकाह्वयैः शृतैः सिद्धां सह बलासमङ्गाविश्वभेषजैः", text: "tatra peyāṃ pibecchītāṃ śarkarāmadhusaṃyutām pippalī pippalīmūlasārivā kaṭukāhvayaiḥ śṛtaiḥ siddhāṃ saha balāsamaṅgāviśvabheṣajaiḥ" },
      { type: "verse", number: "34", sanskrit: "नलदध्यामकव्योषलोध्रचित्रकदीप्यकम् कुतलक्षारतोयेन पिष्टं माक्षिकसर्पिषा", text: "naladadhyāmakavyoṣalodhracitrakadīpyakam kutalakṣāratoyena piṣṭaṃ mākṣikasarpiṣā" },
      { type: "verse", number: "35", sanskrit: "दध्ना वा प्राशयेत् क्षौद्रं यवक्षारपयोदधि फणितं तैलमाज्यं च विषघ्नं पीतमेकतः", text: "dadhnā vā prāśayet kṣaudraṃ yavakṣārapayodadhi phaṇitaṃ tailamājyaṃ ca viṣaghnaṃ pītamekataḥ" },
      { type: "verse", number: "36", sanskrit: "सिन्दुवारं नतं शिग्रु बिल्वमूलं पुनर्नवम् वचा श्वदंष्ट्रा जीमूतमेषां क्वाथं समाक्षिकम् पिबेच्छाल्योदनं दध्ना भुञ्जानो मूषिकार्दितः", text: "sinduvāraṃ nataṃ śigru bilvamūlaṃ punarnavam vacā śvadaṃṣṭrā jīmūtameṣāṃ kvāthaṃ samākṣikam pibecchālyodanaṃ dadhnā bhuñjāno mūṣikārditaḥ" },
      { type: "verse", number: "37", sanskrit: "तक्रेण शरपुङ्खाया बीजं सञ्चूर्ण्य वा पिबेत् अङ्कोलमूलवल्को वा बस्तमूत्रेण कल्कितः पानलेपनयोर्युक्तः सर्वोन्दुरुविषापहः", text: "takreṇa śarapuṅkhāyā bījaṃ sañcūrṇya vā pibet aṅkolamūlavalko vā bastamūtreṇa kalkitaḥ pānalepanayoryuktaḥ sarvonduruviṣāpahaḥ" },
      { type: "verse", number: "38", sanskrit: "पयः पयस्यया युक्तं सितया मधुकेन च", text: "payaḥ payasyayā yuktaṃ sitayā madhukena ca" },
      { type: "verse", number: "39", sanskrit: "किराततिक्तममृतां समङ्गां ककुभत्वचम् बाणं पलाशं काश्मर्यं पयस्यां तण्डुलीयकम्", text: "kirātatiktamamṛtāṃ samaṅgāṃ kakubhatvacam bāṇaṃ palāśaṃ kāśmaryaṃ payasyāṃ taṇḍulīyakam" },
      { type: "verse", number: "40", sanskrit: "आखुविन्नां महानिम्बं सप्तपर्णं मधूलिकाम् कपित्थं राजवृक्षं वा पिबेदन्यतमं ज्वरी", text: "ākhuvinnāṃ mahānimbaṃ saptaparṇaṃ madhūlikām kapitthaṃ rājavṛkṣaṃ vā pibedanyatamaṃ jvarī" },
      { type: "verse", number: "41", sanskrit: "स्थिरां मन्दरुजां प्रच्छेत् कर्णिकां पातयेत वा श्यामा लाङ्गलिका दन्ती किणिही गिरिकर्णिका", text: "sthirāṃ mandarujāṃ pracchet karṇikāṃ pātayeta vā śyāmā lāṅgalikā dantī kiṇihī girikarṇikā" },
      { type: "verse", number: "42", sanskrit: "आखुवृक्षो महावृक्षस्त्रिवृदञ्जनकी स्नुही कर्णिकापातनं कल्कमेकैकं तिलकल्कवत्", text: "ākhuvṛkṣo mahāvṛkṣastrivṛdañjanakī snuhī karṇikāpātanaṃ kalkamekaikaṃ tilakalkavat" },
      { type: "verse", number: "43", sanskrit: "क्षीरिप्रवालमञ्जिष्ठाबलादार्वीहयाह्वयाः रोपण्यः कल्कितास्तैलं घृतं वा साधितं तथा द्विनिशा तिलयष्ट्याह्वतगरोशीरपद्मकैः", text: "kṣīripravālamañjiṣṭhābalādārvīhayāhvayāḥ ropaṇyaḥ kalkitāstailaṃ ghṛtaṃ vā sādhitaṃ tathā dviniśā tilayaṣṭyāhvatagarośīrapadmakaiḥ" },
      { type: "verse", number: "44", sanskrit: "सामान्येनेति निर्दिष्टा क्रियाखूनां विशेषतः", text: "sāmānyeneti nirdiṣṭā kriyākhūnāṃ viśeṣataḥ" },
      { type: "verse", number: "45", sanskrit: "लालनेन वमिर्मूर्च्छा लालास्रावश्च जायते लिह्यात् समाक्षिकं तत्र चूर्णितं तण्डुलीयकम्", text: "lālanena vamirmūrcchā lālāsrāvaśca jāyate lihyāt samākṣikaṃ tatra cūrṇitaṃ taṇḍulīyakam" },
      { type: "verse", number: "46", sanskrit: "चपलेन वमिर्मूर्च्छा तृड्वा तत्रावलेहयेत् सदारुमुस्तां त्रिफलां पुत्रकेण तु पाण्डुता", text: "capalena vamirmūrcchā tṛḍvā tatrāvalehayet sadārumustāṃ triphalāṃ putrakeṇa tu pāṇḍutā" },
      { type: "verse", number: "47", sanskrit: "सादोङ्गे सर्वतश्चाखुसदृशग्रन्थिसम्भवः शिरीषबीजं कुष्ठं च मधुना तत्र लेहयेत्", text: "sādoṅge sarvataścākhusadṛśagranthisambhavaḥ śirīṣabījaṃ kuṣṭhaṃ ca madhunā tatra lehayet" },
      { type: "verse", number: "48", sanskrit: "हसिरेणान्नविद्वेषो जृम्भणं रोमहर्षणम् आरग्वधदिनिर्यूहं सुवान्तं तत्र पाययेत्", text: "hasireṇānnavidveṣo jṛmbhaṇaṃ romaharṣaṇam āragvadhadiniryūhaṃ suvāntaṃ tatra pāyayet" },
      { type: "verse", number: "49", sanskrit: "चिकिरेण शिरोदुःखं शोफो हिध्मा वमिर्भ्रमः वान्तोत्र जालिनीक्वाथैः सारमङ्कोलजं पिबेत्", text: "cikireṇa śiroduḥkhaṃ śopho hidhmā vamirbhramaḥ vāntotra jālinīkvāthaiḥ sāramaṅkolajaṃ pibet" },
      { type: "verse", number: "50", sanskrit: "अजिनेनाङ्गकृष्णत्वं मूर्च्छा छर्दिश्च हृद्ग्रहः मधुना तत्र मञ्जिष्ठां लिह्यात् स्नुक्क्षीरकल्किताम्", text: "ajinenāṅgakṛṣṇatvaṃ mūrcchā chardiśca hṛdgrahaḥ madhunā tatra mañjiṣṭhāṃ lihyāt snukkṣīrakalkitām" },
      { type: "verse", number: "51", sanskrit: "निद्रा कषायदन्तेन हृच्छोषः कृशताति च शिरीषसारत्वग्बीजं तत्र क्षौद्रेण लेहयेत्", text: "nidrā kaṣāyadantena hṛcchoṣaḥ kṛśatāti ca śirīṣasāratvagbījaṃ tatra kṣaudreṇa lehayet" },
      { type: "verse", number: "52", sanskrit: "कुलकेन रुजास्रावौ राजयो दंशमण्डले स सिन्दुवारकौ तत्र सहौ लिह्यान्मधुप्लुतौ", text: "kulakena rujāsrāvau rājayo daṃśamaṇḍale sa sinduvārakau tatra sahau lihyānmadhuplutau" },
      { type: "verse", number: "53", sanskrit: "ग्रन्थयः कोकिलेनोग्रा ज्वरो दाहश्च दारुणः नीलीपुनर्नवाक्वाथे सिद्धं तत्र पिबेत् घृतम्", text: "granthayaḥ kokilenogrā jvaro dāhaśca dāruṇaḥ nīlīpunarnavākvāthe siddhaṃ tatra pibet ghṛtam" },
      { type: "verse", number: "54", sanskrit: "कपिलेन व्रणे कोथो ज्वरो ग्रन्थिर्भ्रमः सतृट् लेहयेन्मधुना श्वेतां श्वेतां चात्र पुनर्नवाम्", text: "kapilena vraṇe kotho jvaro granthirbhramaḥ satṛṭ lehayenmadhunā śvetāṃ śvetāṃ cātra punarnavām" },
      { type: "verse", number: "55", sanskrit: "रक्तं कृष्णेन वमति विशेषाद् दुर्दिने पिबेत् तत्र किंशुकभस्माम्बु शिरीषफलवालकम्", text: "raktaṃ kṛṣṇena vamati viśeṣād durdine pibet tatra kiṃśukabhasmāmbu śirīṣaphalavālakam" },
      { type: "verse", number: "56", sanskrit: "अरुणाद्याः पृथग्दोषसन्निपातास्रसम्भवान् जनयन्ति क्रमाद्रोगान् सर्वे च ग्रन्थिकर्णिकाः", text: "aruṇādyāḥ pṛthagdoṣasannipātāsrasambhavān janayanti kramādrogān sarve ca granthikarṇikāḥ" },
      { type: "verse", number: "57", sanskrit: "करञ्जारग्वधव्योषबृहत्यंशुमतीद्वयात् क्वाथे दधिपयः सर्पिः पृथक्प्रस्थोन्मितं पचेत्", text: "karañjāragvadhavyoṣabṛhatyaṃśumatīdvayāt kvāthe dadhipayaḥ sarpiḥ pṛthakprasthonmitaṃ pacet" },
      { type: "verse", number: "58", sanskrit: "कपित्थदाडिमवरी विशालात्रिसुगन्धिकाः त्रिवृतामृत्तिका वक्रगुडूचीश्चात्रकल्किताः", text: "kapitthadāḍimavarī viśālātrisugandhikāḥ trivṛtāmṛttikā vakraguḍūcīścātrakalkitāḥ" },
      { type: "verse", number: "59", sanskrit: "क्षिपेत्तदरुणादीनां पञ्चानां विषनाशनम् काकादनी काकमाची स्वरसेन शृतं घृतम्", text: "kṣipettadaruṇādīnāṃ pañcānāṃ viṣanāśanam kākādanī kākamācī svarasena śṛtaṃ ghṛtam" },
      { type: "verse", number: "60", sanskrit: "क्लमश्चुच्छुन्दरेणोग्रो ग्रीवास्तम्भो विषूचिका यवनालर्षभक्षारं बृहत्यौ वात्र पाययेत्", text: "klamaścucchundareṇogro grīvāstambho viṣūcikā yavanālarṣabhakṣāraṃ bṛhatyau vātra pāyayet" },
      { type: "verse", number: "61", sanskrit: "ग्रीवास्तम्भो रसालेन वेदना दंशमण्डले लिह्यान्महागदं तत्र घृतमाक्षिकसंयुतम्", text: "grīvāstambho rasālena vedanā daṃśamaṇḍale lihyānmahāgadaṃ tatra ghṛtamākṣikasaṃyutam" },
      { type: "verse", number: "62", sanskrit: "सशेषं मूषिकविषं प्रकुप्यत्यभ्रदर्शने यथायथं वा लाकेषु दोषाणां वृद्धिहेतुषु", text: "saśeṣaṃ mūṣikaviṣaṃ prakupyatyabhradarśane yathāyathaṃ vā lākeṣu doṣāṇāṃ vṛddhihetuṣu" },
      { type: "verse", number: "63", sanskrit: "तत्र सर्वे यथावस्थं प्रयोज्याः स्युरुपक्रमाः यथास्वं ये च निर्दिष्टास्तथा दूषीविषापहाः", text: "tatra sarve yathāvasthaṃ prayojyāḥ syurupakramāḥ yathāsvaṃ ye ca nirdiṣṭāstathā dūṣīviṣāpahāḥ" },
      { type: "verse", number: "64", sanskrit: "दंशत्वलर्कदष्टस्य दग्धमुष्णेन सर्पिषा प्रदिह्यादगदैस्तैस्तैः पुराणं च घृतं पिबेत् व्रणस्योपरि निष्पीड्यः प्रत्यक्पुष्पीरसोथवा", text: "daṃśatvalarkadaṣṭasya dagdhamuṣṇena sarpiṣā pradihyādagadaistaistaiḥ purāṇaṃ ca ghṛtaṃ pibet vraṇasyopari niṣpīḍyaḥ pratyakpuṣpīrasothavā" },
      { type: "verse", number: "65", sanskrit: "तिलगुग्गुलुदूर्वाणां दाडिमस्य गुडस्य च कल्को मुहुर्मुहुर्लेपः श्वदंशविषजित्परम्", text: "tilagugguludūrvāṇāṃ dāḍimasya guḍasya ca kalko muhurmuhurlepaḥ śvadaṃśaviṣajitparam" },
      { type: "verse", number: "66", sanskrit: "नलमूलं जले पिष्टं पानलेपनयोर्हितम् मातुलुङ्गच्छदैर्दंशं बध्नीयाद्दन्तचर्वितैः", text: "nalamūlaṃ jale piṣṭaṃ pānalepanayorhitam mātuluṅgacchadairdaṃśaṃ badhnīyāddantacarvitaiḥ" },
      { type: "verse", number: "67", sanskrit: "अर्कक्षीरयुतं चास्य योज्यमाशु विरेचनम्", text: "arkakṣīrayutaṃ cāsya yojyamāśu virecanam" },
      { type: "verse", number: "68", sanskrit: "पिबेत् पुनर्नवां श्वेतां धुर्धूरकफलान्विताम्", text: "pibet punarnavāṃ śvetāṃ dhurdhūrakaphalānvitām" },
      { type: "verse", number: "69", sanskrit: "फलं धुर्धूरकान्मूलं काकोदुम्बरिकोद्भवम् शीधुना श्वविषं हन्ति पीतं वा तण्डुलाम्बुना", text: "phalaṃ dhurdhūrakānmūlaṃ kākodumbarikodbhavam śīdhunā śvaviṣaṃ hanti pītaṃ vā taṇḍulāmbunā" },
      { type: "verse", number: "70", sanskrit: "ऐकध्यं पललं तैलं रूपिकायाः पयो गुडः भिनत्ति विषमालर्कं घनवृन्दमिवानिलः", text: "aikadhyaṃ palalaṃ tailaṃ rūpikāyāḥ payo guḍaḥ bhinatti viṣamālarkaṃ ghanavṛndamivānilaḥ" },
      { type: "verse", number: "71", sanskrit: "लशुनोषणवैदेही वरा गोपित्तकल्किताः पाननस्याञ्जनालेपैः श्वदष्टस्यौषधं परम्", text: "laśunoṣaṇavaidehī varā gopittakalkitāḥ pānanasyāñjanālepaiḥ śvadaṣṭasyauṣadhaṃ param" },
      { type: "verse", number: "72", sanskrit: "जलवेतसपत्रत्वङ्मूलं क्षुण्णं पचेज्जले स क्वाथः शीतलः पीतः परं श्वविषभेषजम्", text: "jalavetasapatratvaṅmūlaṃ kṣuṇṇaṃ pacejjale sa kvāthaḥ śītalaḥ pītaḥ paraṃ śvaviṣabheṣajam" },
      { type: "verse", number: "73", sanskrit: "तत्सिद्धं च घृतं पाननस्याभ्यञ्जनलेपनम् जलत्रासे समस्ते च विषे तत् गरुडोपमम्", text: "tatsiddhaṃ ca ghṛtaṃ pānanasyābhyañjanalepanam jalatrāse samaste ca viṣe tat garuḍopamam" },
      { type: "verse", number: "74", sanskrit: "यवमाषकुलत्थानां पञ्चमूलस्य चाम्भसि क्षीरद्विगुणिते सर्पिः साधयेच्छ्लक्ष्णकल्कितैः", text: "yavamāṣakulatthānāṃ pañcamūlasya cāmbhasi kṣīradviguṇite sarpiḥ sādhayecchlakṣṇakalkitaiḥ" },
      { type: "verse", number: "75", sanskrit: "अश्वगन्धासहाकुष्ठबृहतीरजनीद्वयैः विदारीनतकट्वङ्ग पयस्यासिन्दुवारकैः", text: "aśvagandhāsahākuṣṭhabṛhatīrajanīdvayaiḥ vidārīnatakaṭvaṅga payasyāsinduvārakaiḥ" },
      { type: "verse", number: "76", sanskrit: "सर्पगन्धानखाभीरुशर्करारक्तचन्दनैः श्वसंष्ट्रोपद्रवान् सर्वान् पानाभ्यङ्गैर्निहन्तितत्", text: "sarpagandhānakhābhīruśarkarāraktacandanaiḥ śvasaṃṣṭropadravān sarvān pānābhyaṅgairnihantitat" },
      { type: "verse", number: "77", sanskrit: "हृद्विदाहे प्रसेके च विरेकवमने भृशम् विषदोषहरे योज्ये शुद्धे संसर्जनक्रमः", text: "hṛdvidāhe praseke ca virekavamane bhṛśam viṣadoṣahare yojye śuddhe saṃsarjanakramaḥ" },
      { type: "verse", number: "78", sanskrit: "दद्यात् संशोधनं तीक्ष्णमवश्यं विषनाशनम् अशुद्धस्य निरूढेपि व्रणे कुप्यति तद्विषम्", text: "dadyāt saṃśodhanaṃ tīkṣṇamavaśyaṃ viṣanāśanam aśuddhasya nirūḍhepi vraṇe kupyati tadviṣam" },
      { type: "verse", number: "79", sanskrit: "सरत्रबीजौषधिभिः कुम्भैः शीताम्बुपूरितैः अष्टोत्तरशतं वारान् सिद्धमन्त्राभिमन्त्रितै", text: "saratrabījauṣadhibhiḥ kumbhaiḥ śītāmbupūritaiḥ aṣṭottaraśataṃ vārān siddhamantrābhimantritai" },
      { type: "verse", number: "80", sanskrit: "अष्टोत्तरशतोन्मानैः पुष्पमालावगुण्ठितैः गोचर्ममात्रके लिप्ते ज्वलिताग्नौ कुशास्तृते स्थण्डिले सरितस्तीरे स्नानं वास्य चतुष्पथे", text: "aṣṭottaraśatonmānaiḥ puṣpamālāvaguṇṭhitaiḥ gocarmamātrake lipte jvalitāgnau kuśāstṛte sthaṇḍile saritastīre snānaṃ vāsya catuṣpathe" },
      { type: "verse", number: "81", sanskrit: "अलर्काधिपते यक्ष सारमेयगणाधिप अलर्कजुष्टमेतं मे निर्विषं कुरु मा चिरात् स्वाहेतिमन्त्रोलर्कार्त्ते सर्वकर्मसु शस्यते", text: "alarkādhipate yakṣa sārameyagaṇādhipa alarkajuṣṭametaṃ me nirviṣaṃ kuru mā cirāt svāhetimantrolarkārtte sarvakarmasu śasyate" },
      { type: "verse", number: "82", sanskrit: "चतुष्पाद्भिद्विपाद्भिर्वा नखदन्तपरिक्षतम् शूयते पच्यते रागज्वरस्रावरुजान्वितम्", text: "catuṣpādbhidvipādbhirvā nakhadantaparikṣatam śūyate pacyate rāgajvarasrāvarujānvitam" },
      { type: "verse", number: "83", sanskrit: "सोमवल्कोश्वकर्णश्च गोजिह्वा हंसपादिका रजन्यौ गैरिकं लेपो नखदन्तविषापहः", text: "somavalkośvakarṇaśca gojihvā haṃsapādikā rajanyau gairikaṃ lepo nakhadantaviṣāpahaḥ" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 47,
    lang: "sa",
    content: [
      { type: "heading", heading: "Вирья санграха — о потенции веществ" },
      { type: "text", text: "Глава 47 Уттара стханы — «Вирья санграха» — посвящена специализированному разделу: о потенции веществ. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो विषोपद्रवप्रतिषेधं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः", text: "athāto viṣopadravapratiṣedhaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "ज्वरकासवमिश्वासहिध्मा तृष्णातिमूर्च्छनम् विशोभेदो ऽतिकाठिन्यमानाहो बस्तिमूर्द्धरुक्", text: "jvarakāsavamiśvāsahidhmā tṛṣṇātimūrcchanam viśobhedo 'tikāṭhinyamānāho bastimūrddharuk" },
      { type: "verse", number: "3", sanskrit: "श्वयथुः पूतिदंशत्वं रक्तस्रावो विषानिलः इति षोडश निर्दिष्टा विषार्तानामुपद्रवाः गच्छन्त्युपोक्षिता नाशं यैर्जुष्टा विषरोगिणः", text: "śvayathuḥ pūtidaṃśatvaṃ raktasrāvo viṣānilaḥ iti ṣoḍaśa nirdiṣṭā viṣārtānāmupadravāḥ gacchantyupokṣitā nāśaṃ yairjuṣṭā viṣarogiṇaḥ" },
      { type: "verse", number: "4", sanskrit: "राजवृक्षफलोशीरकाश्मर्यघनपद्मकात् क्वाथः सशर्कराक्षौद्रो विषज्वरहरः परम्", text: "rājavṛkṣaphalośīrakāśmaryaghanapadmakāt kvāthaḥ saśarkarākṣaudro viṣajvaraharaḥ param" },
      { type: "verse", number: "5", sanskrit: "पीता तण्डुलतोयेन कटुका ससितोपला विषज्वरहराजाजी जीवकर्षभकोत्पलम्", text: "pītā taṇḍulatoyena kaṭukā sasitopalā viṣajvaraharājājī jīvakarṣabhakotpalam" },
      { type: "verse", number: "6", sanskrit: "कोलमज्जसिताधान्यभार्ङ्गीयष्ट्याह्वकेसरम् विषज्वरवमिश्वासकासतृष्णानिबर्हणम्", text: "kolamajjasitādhānyabhārṅgīyaṣṭyāhvakesaram viṣajvaravamiśvāsakāsatṛṣṇānibarhaṇam" },
      { type: "verse", number: "7", sanskrit: "त्रिफलारग्वधव्याघ्रीक्वाथो ज्वरविबन्धजित् बालबिल्ववचामुस्ता कषायः सपुनर्नवः ज्वराग्निसादश्वयथून्निहन्ति विषसम्भवान्", text: "triphalāragvadhavyāghrīkvātho jvaravibandhajit bālabilvavacāmustā kaṣāyaḥ sapunarnavaḥ jvarāgnisādaśvayathūnnihanti viṣasambhavān" },
      { type: "verse", number: "8", sanskrit: "वैदेहिकारामठकं कपित्थरससैन्धवम् ससितामाक्षिकं लीढं श्वासकासज्वरापहम्", text: "vaidehikārāmaṭhakaṃ kapittharasasaindhavam sasitāmākṣikaṃ līḍhaṃ śvāsakāsajvarāpaham" },
      { type: "verse", number: "9", sanskrit: "सद्राक्षानागरां कृष्णामथवा सवराघनाम् लीढ्वाज्यमधुना कासान्मुच्यते विषसम्भवात्", text: "sadrākṣānāgarāṃ kṛṣṇāmathavā savarāghanām līḍhvājyamadhunā kāsānmucyate viṣasambhavāt" },
      { type: "verse", number: "10", sanskrit: "सपाठाञ्जनमञ्जिष्ठाद्विनिशामधुकां तथा यष्ट्याह्वमम्भसा पीत्वा मरिचैरवचूर्णितम्", text: "sapāṭhāñjanamañjiṣṭhādviniśāmadhukāṃ tathā yaṣṭyāhvamambhasā pītvā maricairavacūrṇitam" },
      { type: "verse", number: "11", sanskrit: "विषवम्यां पिबेत् क्वाथं विल्बमूलाद्रजो ऽथवा धात्रीषरूपकद्राक्षा मधुकं पयसा द्रुतम्", text: "viṣavamyāṃ pibet kvāthaṃ vilbamūlādrajo 'thavā dhātrīṣarūpakadrākṣā madhukaṃ payasā drutam" },
      { type: "verse", number: "12", sanskrit: "वेल्लाग्र्याञ्जनसोशीरयष्ट्यैलाकणकेसरम् लिह्यान्मरिचकुम्भीं वा घृतपुष्परसद्रुताम्", text: "vellāgryāñjanasośīrayaṣṭyailākaṇakesaram lihyānmaricakumbhīṃ vā ghṛtapuṣparasadrutām" },
      { type: "verse", number: "13", sanskrit: "क्षीरिवृक्षाङ्कुरक्षौद्रसितास्तृड्वमथुच्छिदः", text: "kṣīrivṛkṣāṅkurakṣaudrasitāstṛḍvamathucchidaḥ" },
      { type: "verse", number: "14", sanskrit: "जीर्णशाल्योदनं क्षौद्रं क्षीरं चन्दनसाधितम् शीतान्भोनुपिबेत् भुक्त्वा विषच्छर्दिमपोहति", text: "jīrṇaśālyodanaṃ kṣaudraṃ kṣīraṃ candanasādhitam śītānbhonupibet bhuktvā viṣacchardimapohati" },
      { type: "verse", number: "15", sanskrit: "तैलगोविड्रसक्षौद्रैलिह्यात् कृष्णाप्रियङ्गुके", text: "tailagoviḍrasakṣaudrailihyāt kṛṣṇāpriyaṅguke" },
      { type: "verse", number: "16", sanskrit: "श्वासी क्षौद्रेण वा द्राक्षाशृङ्गीमागधिकासिताः गुडनागरवैदेहीविजयामलकानि वा", text: "śvāsī kṣaudreṇa vā drākṣāśṛṅgīmāgadhikāsitāḥ guḍanāgaravaidehīvijayāmalakāni vā" },
      { type: "verse", number: "17", sanskrit: "हिध्मायां शङ्खकनककटुकास्वर्णगैरिकम् वेल्लशुण्ठीकणोशीररजनीद्वितयानि वा", text: "hidhmāyāṃ śaṅkhakanakakaṭukāsvarṇagairikam vellaśuṇṭhīkaṇośīrarajanīdvitayāni vā" },
      { type: "verse", number: "18", sanskrit: "लिह्याद्वा व्योषमृद्वीकां बीजपूररसेन वा सक्षौद्रं वालकरजः क्वाथं वा सगुडं पिबेत्", text: "lihyādvā vyoṣamṛdvīkāṃ bījapūrarasena vā sakṣaudraṃ vālakarajaḥ kvāthaṃ vā saguḍaṃ pibet" },
      { type: "verse", number: "19", sanskrit: "विश्वभेषजगायत्रीहरिद्रामरदारुजम् दन्तीन्द्रवारुणीद्वीपीकल्कं सौवीरकेण वा", text: "viśvabheṣajagāyatrīharidrāmaradārujam dantīndravāruṇīdvīpīkalkaṃ sauvīrakeṇa vā" },
      { type: "verse", number: "20", sanskrit: "तृण्मूर्च्छयोरशिरसो लेपसेका हिमा हिताः अम्भोजनालकुसुमचन्दनोशरीमौक्तिकैः वैहायससितातोयक्षीराज्येक्षुरसाप्लुतैः", text: "tṛṇmūrcchayoraśiraso lepasekā himā hitāḥ ambhojanālakusumacandanośarīmauktikaiḥ vaihāyasasitātoyakṣīrājyekṣurasāplutaiḥ" },
      { type: "verse", number: "21", sanskrit: "वीजनं तालवृन्तेन शीते सिकतिले स्थितिः", text: "vījanaṃ tālavṛntena śīte sikatile sthitiḥ" },
      { type: "verse", number: "22", sanskrit: "कमलोत्पलकिञ्जल्कपटलावृतवारिषु विषतृड्दाहमूर्च्छाघ्नं सरसीष्ववगाहनम्", text: "kamalotpalakiñjalkapaṭalāvṛtavāriṣu viṣatṛḍdāhamūrcchāghnaṃ sarasīṣvavagāhanam" },
      { type: "verse", number: "23", sanskrit: "विषवेगसमुत्थायां तृष्णायां लाजतर्पणम् शर्करादाडिमक्षौद्रसलिलाप्लावितं पिबेत् वटवेतसजम्ब्वाम्रसेव्यतोयं च शीतलम्", text: "viṣavegasamutthāyāṃ tṛṣṇāyāṃ lājatarpaṇam śarkarādāḍimakṣaudrasalilāplāvitaṃ pibet vaṭavetasajambvāmrasevyatoyaṃ ca śītalam" },
      { type: "verse", number: "24", sanskrit: "भूनिम्बमुस्तकटुकात्रायन्तीन्द्रयवान् समान् द्वौ भागौ चित्रकादष्टौ कुटजाद्वारिणा पिबेत् विषातिसारोदावर्तकासश्वासज्वरापहम्", text: "bhūnimbamustakaṭukātrāyantīndrayavān samān dvau bhāgau citrakādaṣṭau kuṭajādvāriṇā pibet viṣātisārodāvartakāsaśvāsajvarāpaham" },
      { type: "verse", number: "25", sanskrit: "लोध्रमोचरसाम्बष्ठाधातकीस्तण्डुलाम्बुना समाक्षिकाः पिबेत्तद्वन्नागरातिविषाभयाः", text: "lodhramocarasāmbaṣṭhādhātakīstaṇḍulāmbunā samākṣikāḥ pibettadvannāgarātiviṣābhayāḥ" },
      { type: "verse", number: "26", sanskrit: "सधातकीः सकुटजाः साञ्जनाः श्लक्ष्णचूर्णिताः पाठानागरचूर्णं वा दध्ना युक्तं समाक्षिकम्", text: "sadhātakīḥ sakuṭajāḥ sāñjanāḥ ślakṣṇacūrṇitāḥ pāṭhānāgaracūrṇaṃ vā dadhnā yuktaṃ samākṣikam" },
      { type: "verse", number: "27", sanskrit: "बस्तिरुग्वर्तनाहेषु फलवर्तिं प्रयोजयेत् सारग्वधां सत्रिवृतां सोपकुल्यां हरीतकीम् पिबेत् घृतेन सक्षौद्रां बस्तिशूलादिनाशिनीम्", text: "bastirugvartanāheṣu phalavartiṃ prayojayet sāragvadhāṃ satrivṛtāṃ sopakulyāṃ harītakīm pibet ghṛtena sakṣaudrāṃ bastiśūlādināśinīm" },
      { type: "verse", number: "28", sanskrit: "गृहधूमनतश्यामा नीलिनी तण्डुलीयकैः सिद्धं वाज्यं तथासिद्धं वरा क्वाथत्रिवृद्युतम्", text: "gṛhadhūmanataśyāmā nīlinī taṇḍulīyakaiḥ siddhaṃ vājyaṃ tathāsiddhaṃ varā kvāthatrivṛdyutam" },
      { type: "verse", number: "29", sanskrit: "काकोली क्षीरिवृक्षत्वग्द्राक्षायष्ट्याह्वशर्कराः नस्यं विषशिरोरुघ्नं संयोज्यं शीतवारिणा", text: "kākolī kṣīrivṛkṣatvagdrākṣāyaṣṭyāhvaśarkarāḥ nasyaṃ viṣaśirorughnaṃ saṃyojyaṃ śītavāriṇā" },
      { type: "verse", number: "30", sanskrit: "श्वयथौ शुद्धकोष्ठस्य पयः पाने हितं शृतम् विश्वभेषजवैदेहीकटुकादेवदारुभिः सुरसाम्लकल्कैर्वा छागं वा पिप्पलीशृतम्", text: "śvayathau śuddhakoṣṭhasya payaḥ pāne hitaṃ śṛtam viśvabheṣajavaidehīkaṭukādevadārubhiḥ surasāmlakalkairvā chāgaṃ vā pippalīśṛtam" },
      { type: "verse", number: "31", sanskrit: "त्रिफलायाः कषायेण त्रिवृता भाविता त्र्यहम् आलोड्य सर्पिषा पीता विषश्वयथुनाशिनी", text: "triphalāyāḥ kaṣāyeṇa trivṛtā bhāvitā tryaham āloḍya sarpiṣā pītā viṣaśvayathunāśinī" },
      { type: "verse", number: "32", sanskrit: "मधुवेल्लवराव्योषसुराह्वोशीरपद्मकैः विषश्वयथुजिल्लेपस्तथा स्वादुकषायकैः", text: "madhuvellavarāvyoṣasurāhvośīrapadmakaiḥ viṣaśvayathujillepastathā svādukaṣāyakaiḥ" },
      { type: "verse", number: "33", sanskrit: "शिरीषपुष्पाहिशिरोनतकुष्ठैर्घृतान्वितः धूपो ऽगदः श्वयथुजित् समस्तविषनाशनः", text: "śirīṣapuṣpāhiśironatakuṣṭhairghṛtānvitaḥ dhūpo 'gadaḥ śvayathujit samastaviṣanāśanaḥ" },
      { type: "verse", number: "34", sanskrit: "अल्पेनाप्यपचारेण दंशः पूतित्वमश्नुते प्रायो न सहते तीक्ष्णमुष्णं वा भेषजं विषम्", text: "alpenāpyapacāreṇa daṃśaḥ pūtitvamaśnute prāyo na sahate tīkṣṇamuṣṇaṃ vā bheṣajaṃ viṣam" },
      { type: "verse", number: "35", sanskrit: "मधुरस्निग्धशीतानि युञ्यात्तस्माद्विषव्रणे सेकालेपांश्च सक्षीरैः कषायैः क्षीरिवृक्षजैः", text: "madhurasnigdhaśītāni yuñyāttasmādviṣavraṇe sekālepāṃśca sakṣīraiḥ kaṣāyaiḥ kṣīrivṛkṣajaiḥ" },
      { type: "verse", number: "36", sanskrit: "न्यग्रोधशुङ्गमधुकतिलसर्षपसैन्धवम् साभया निम्बपत्राज्यं दंशपूतित्वनाशनम् कर्णिकापातनं श्रेष्ठं विषव्रणविनाशनम्", text: "nyagrodhaśuṅgamadhukatilasarṣapasaindhavam sābhayā nimbapatrājyaṃ daṃśapūtitvanāśanam karṇikāpātanaṃ śreṣṭhaṃ viṣavraṇavināśanam" },
      { type: "verse", number: "37", sanskrit: "रक्ते स्रवत्यतिभृशं घृतं समरिचं पिबेत् तण्डुलीयकमूलेन सितया वा समन्वितम्", text: "rakte sravatyatibhṛśaṃ ghṛtaṃ samaricaṃ pibet taṇḍulīyakamūlena sitayā vā samanvitam" },
      { type: "verse", number: "38", sanskrit: "दंशं प्रलेपयेच्चास्य दार्व्या सुश्लक्ष्णपिष्टया सितोपलाक्षौद्रघृतच्छागदुग्धानि नावनम्", text: "daṃśaṃ pralepayeccāsya dārvyā suślakṣṇapiṣṭayā sitopalākṣaudraghṛtacchāgadugdhāni nāvanam" },
      { type: "verse", number: "39", sanskrit: "शमीकल्कं पिबेच्छ्लक्ष्णमङ्गं लिम्पोद्विशालया नावने हेमं शुक्ला च ततः शाम्यति शोणितम्", text: "śamīkalkaṃ pibecchlakṣṇamaṅgaṃ limpodviśālayā nāvane hemaṃ śuklā ca tataḥ śāmyati śoṇitam" },
      { type: "verse", number: "40", sanskrit: "क्द्शस्यातिस्रुते रक्ते रूक्षैरत्यर्थसेवितैः विषस्य च स्वभावेन मातरिश्वा प्रकुप्यति", text: "kdśasyātisrute rakte rūkṣairatyarthasevitaiḥ viṣasya ca svabhāvena mātariśvā prakupyati" },
      { type: "verse", number: "41", sanskrit: "उन्मादाक्षेपकमनोभ्रंशापस्मृतयस्ततः तत्रेष्टं स्नेहनं बस्तिनस्यप्रधमानाञ्जनम्", text: "unmādākṣepakamanobhraṃśāpasmṛtayastataḥ tatreṣṭaṃ snehanaṃ bastinasyapradhamānāñjanam" },
      { type: "verse", number: "42", sanskrit: "नागदन्त्यभयाकुष्ठपिप्पलीवृषकट्फलम् भल्लातकास्थिकटुकाबिल्वप्रतिविषाग्निकाः सक्षीरं तैर्घृतं सिद्धं विषवातविकारजित्", text: "nāgadantyabhayākuṣṭhapippalīvṛṣakaṭphalam bhallātakāsthikaṭukābilvaprativiṣāgnikāḥ sakṣīraṃ tairghṛtaṃ siddhaṃ viṣavātavikārajit" },
      { type: "verse", number: "43", sanskrit: "पिबेदेरण्डतैलं वा छागमांसरसान्वितम् ऐकध्यं घृततैलं वा मेध्यमांसरसाशनः", text: "pibederaṇḍatailaṃ vā chāgamāṃsarasānvitam aikadhyaṃ ghṛtatailaṃ vā medhyamāṃsarasāśanaḥ" },
      { type: "verse", number: "44", sanskrit: "कार्पासमूलं मरिचं हरिद्रे नलदं नलम् पिप्पलीं स्वर्जिकां कुष्ठं जलेनालोड्य पाययेत् उन्मत्तं विषवातेन तथापस्मारिणं नरम्", text: "kārpāsamūlaṃ maricaṃ haridre naladaṃ nalam pippalīṃ svarjikāṃ kuṣṭhaṃ jalenāloḍya pāyayet unmattaṃ viṣavātena tathāpasmāriṇaṃ naram" },
      { type: "verse", number: "45", sanskrit: "वचाहंसपदीव्योषदधित्थं हस्तिपिप्पलीम् देवदारुबलाबिल्वकृमिजित् कुष्ठटुण्टुकम्", text: "vacāhaṃsapadīvyoṣadadhitthaṃ hastipippalīm devadārubalābilvakṛmijit kuṣṭhaṭuṇṭukam" },
      { type: "verse", number: "46", sanskrit: "लोध्राखुकर्ण्यतिविषाः क्षीरं सर्पिश्च पाययेत् निहन्ति पानाभ्यङ्गाभ्यां घृतं सर्वविषाणि तत्", text: "lodhrākhukarṇyativiṣāḥ kṣīraṃ sarpiśca pāyayet nihanti pānābhyaṅgābhyāṃ ghṛtaṃ sarvaviṣāṇi tat" },
      { type: "verse", number: "47", sanskrit: "प्रतिकुर्याद्यथास्वं च रोगेष्वेवं परेषु च दोषानुबन्धमालोच्य विषतन्त्राविरोधतः", text: "pratikuryādyathāsvaṃ ca rogeṣvevaṃ pareṣu ca doṣānubandhamālocya viṣatantrāvirodhataḥ" },
      { type: "verse", number: "48", sanskrit: "दृश्यशब्दागदैरस्य विषशेषं निवर्तयेत् अल्पमप्यवशिष्टं हि व्याधये मरणाय वा", text: "dṛśyaśabdāgadairasya viṣaśeṣaṃ nivartayet alpamapyavaśiṣṭaṃ hi vyādhaye maraṇāya vā" },
      { type: "verse", number: "49", sanskrit: "धवाश्वकर्णतिनिशकरघाटकपीतनान् पलाशाम्रातककुभपारिभद्रकतिल्वकान्", text: "dhavāśvakarṇatiniśakaraghāṭakapītanān palāśāmrātakakubhapāribhadrakatilvakān" },
      { type: "verse", number: "50", sanskrit: "कपित्थकुटजाङ्कोलप्रग्रहामलकीभुजान् शमीश्लेष्मातकाश्मन्तगोजीयमलकण्टकान्", text: "kapitthakuṭajāṅkolapragrahāmalakībhujān śamīśleṣmātakāśmantagojīyamalakaṇṭakān" },
      { type: "verse", number: "51", sanskrit: "चिरिविल्वार्ककट्वङ्गसमङ्गामधुशिग्रुकान् गोपघोण्टाहिमारौ च भस्मीकृत्याम्भसा गवाम्", text: "cirivilvārkakaṭvaṅgasamaṅgāmadhuśigrukān gopaghoṇṭāhimārau ca bhasmīkṛtyāmbhasā gavām" },
      { type: "verse", number: "52", sanskrit: "क्षारकल्पेनविस्राव्य पचेत् क्षिप्त्वावचूर्णितान् पिप्पलीद्वयकोशास्रसप्तपर्णैलवालुकान्", text: "kṣārakalpenavisrāvya pacet kṣiptvāvacūrṇitān pippalīdvayakośāsrasaptaparṇailavālukān" },
      { type: "verse", number: "53", sanskrit: "वराङ्गचोचमञ्जिष्ठाकुष्ठवञ्जुलटुण्टुकान् विडङ्गातिविषानन्तासर्षपतण्डुलीयकान्", text: "varāṅgacocamañjiṣṭhākuṣṭhavañjulaṭuṇṭukān viḍaṅgātiviṣānantāsarṣapataṇḍulīyakān" },
      { type: "verse", number: "54", sanskrit: "सुराह्वसरलप्लक्षगृहधूमकरञ्जकान् नागदन्ती सुतश्रेणी निचुलं वरुणं वचाम्", text: "surāhvasaralaplakṣagṛhadhūmakarañjakān nāgadantī sutaśreṇī niculaṃ varuṇaṃ vacām" },
      { type: "verse", number: "55", sanskrit: "वर्द्धमानमयो बिल्वं क्षारवत्पाकमागतम् तत् लोहकुम्भे निहितं कार्यं सन्निहितं सदा", text: "varddhamānamayo bilvaṃ kṣāravatpākamāgatam tat lohakumbhe nihitaṃ kāryaṃ sannihitaṃ sadā" },
      { type: "verse", number: "56", sanskrit: "तेन दुन्दुभिमालिम्बेत् पताकास्तरणानि च दर्शनश्रवणस्पर्शैर्निर्विषं तानि कुर्वते", text: "tena dundubhimālimbet patākāstaraṇāni ca darśanaśravaṇasparśairnirviṣaṃ tāni kurvate" },
      { type: "verse", number: "57", sanskrit: "पानात् क्षारागदश्चैष विषं स्थावरजङ्गमम् शूलगुल्मोदराजर्णिश्वासकासाश्मशर्कराः", text: "pānāt kṣārāgadaścaiṣa viṣaṃ sthāvarajaṅgamam śūlagulmodarājarṇiśvāsakāsāśmaśarkarāḥ" },
      { type: "verse", number: "58", sanskrit: "शोफार्शोग्रहणीदोषानरुचिं च नियच्छति अपि तक्षकतुल्यानां सर्पाणां दर्पनाशनः", text: "śophārśograhaṇīdoṣānaruciṃ ca niyacchati api takṣakatulyānāṃ sarpāṇāṃ darpanāśanaḥ" },
      { type: "verse", number: "59", sanskrit: "श्रीवेष्टकमनोह्वालं ससर्जरसवालकम् कर्षांशं नागपुष्पस्य प्रकुञ्चं त्रुटिविंशकम्", text: "śrīveṣṭakamanohvālaṃ sasarjarasavālakam karṣāṃśaṃ nāgapuṣpasya prakuñcaṃ truṭiviṃśakam" },
      { type: "verse", number: "60", sanskrit: "हरेणवश्चतुःषष्टिः कुटन्नटचतुष्टयम् शताह्वां षोडशैतानि पुष्ये सम्भृत्य पेषयेत्", text: "hareṇavaścatuḥṣaṣṭiḥ kuṭannaṭacatuṣṭayam śatāhvāṃ ṣoḍaśaitāni puṣye sambhṛtya peṣayet" },
      { type: "verse", number: "61", sanskrit: "आश्लेषासु गवां मध्ये शस्त्रमन्त्राभिरक्षितम् कुमार्या स्नातया तत्र मन्त्रोयं विष्णुनिर्मितः", text: "āśleṣāsu gavāṃ madhye śastramantrābhirakṣitam kumāryā snātayā tatra mantroyaṃ viṣṇunirmitaḥ" },
      { type: "verse", number: "62", sanskrit: "माता मे विजयानाम जयो नाम पिता मम अजय्यस्य च पुत्रोसौ विजये च जयामि वः", text: "mātā me vijayānāma jayo nāma pitā mama ajayyasya ca putrosau vijaye ca jayāmi vaḥ" },
      { type: "verse", number: "63", sanskrit: "सुगन्धाख्योयमगदो नित्यं देहविलेपनात् अभङ्गकरणो युद्धे विवादे च जयावहः", text: "sugandhākhyoyamagado nityaṃ dehavilepanāt abhaṅgakaraṇo yuddhe vivāde ca jayāvahaḥ" },
      { type: "verse", number: "64", sanskrit: "अमुना लेपिताश्छत्रदुन्दुभिध्वजतोरणाः दृष्टस्पृष्टश्रुता घ्नन्ति विषं स्थावरजङ्गमम् भूतबालग्रहोन्मादान् गेहस्थोपि निवारयेत्", text: "amunā lepitāśchatradundubhidhvajatoraṇāḥ dṛṣṭaspṛṣṭaśrutā ghnanti viṣaṃ sthāvarajaṅgamam bhūtabālagrahonmādān gehasthopi nivārayet" },
      { type: "verse", number: "65", sanskrit: "प्रपौण्डरीकसरलदेवदारुकुटन्नटम् जटाशताह्वातिविषातिलपर्णीसुगन्धिका", text: "prapauṇḍarīkasaraladevadārukuṭannaṭam jaṭāśatāhvātiviṣātilaparṇīsugandhikā" },
      { type: "verse", number: "66", sanskrit: "नीलीयिवफलाभार्ङ्गीमधुयष्ट्यैलवालुकम् तोयतोयदकालीयतगरध्यामकत्वचः", text: "nīlīyivaphalābhārṅgīmadhuyaṣṭyailavālukam toyatoyadakālīyatagaradhyāmakatvacaḥ" },
      { type: "verse", number: "67", sanskrit: "नखपद्मकपुन्नागपत्रकालानुसारिवाः तालीसपत्रं मरिचं जोङ्गकं चन्दनद्वयम्", text: "nakhapadmakapunnāgapatrakālānusārivāḥ tālīsapatraṃ maricaṃ joṅgakaṃ candanadvayam" },
      { type: "verse", number: "68", sanskrit: "द्व्येलाद्विसेव्यद्विता द्विनिशा नलदद्वयम् लाक्षाशीतशिवव्योषफलिनीधान्यगैरिकम्", text: "dvyelādvisevyadvitā dviniśā naladadvayam lākṣāśītaśivavyoṣaphalinīdhānyagairikam" },
      { type: "verse", number: "69", sanskrit: "शैलेयकशिलापुष्पग्रन्थिला चोरकाभयाः अर्कस्थौणेयपृथ्वीका कटुका चन्द्रराजयः", text: "śaileyakaśilāpuṣpagranthilā corakābhayāḥ arkasthauṇeyapṛthvīkā kaṭukā candrarājayaḥ" },
      { type: "verse", number: "70", sanskrit: "कलिङ्गकः सर्जरसः कुष्ठं लवणपञ्चकम् श्रीपर्णिकाश्मरीशेलुशिंशपा सिन्दुवारजः", text: "kaliṅgakaḥ sarjarasaḥ kuṣṭhaṃ lavaṇapañcakam śrīparṇikāśmarīśeluśiṃśapā sinduvārajaḥ" },
      { type: "verse", number: "71", sanskrit: "चम्पकाशोकसुरससुमनस्तिल्वकोद्भवाः पाटल्यास्तृणशूल्याश्च प्रसवाः कुमुदोत्पलम्", text: "campakāśokasurasasumanastilvakodbhavāḥ pāṭalyāstṛṇaśūlyāśca prasavāḥ kumudotpalam" },
      { type: "verse", number: "72", sanskrit: "तिनिशार्जुनशम्याकधवपुष्पं सपङ्कजम् पञ्चाशीतेरिदं चूर्णं समूत्रघृतमाक्षिकम्", text: "tiniśārjunaśamyākadhavapuṣpaṃ sapaṅkajam pañcāśīteridaṃ cūrṇaṃ samūtraghṛtamākṣikam" },
      { type: "verse", number: "73", sanskrit: "निधापयेत् गवां शृङ्गे मनुष्यं पुनराहरेत् (मनुष्यं तेन जीवयेत्) भग्नस्कन्धं विवृत्ताक्षं मृत्योर्दंष्ट्रान्तरं गतम्", text: "nidhāpayet gavāṃ śṛṅge manuṣyaṃ punarāharet (manuṣyaṃ tena jīvayet) bhagnaskandhaṃ vivṛttākṣaṃ mṛtyordaṃṣṭrāntaraṃ gatam" },
      { type: "verse", number: "74", sanskrit: "महासुगन्धो नाम्नायमतिवीर्योतितेजसा वारयत्यतिदुर्वारं विषाग्निं वासुकेरपि", text: "mahāsugandho nāmnāyamativīryotitejasā vārayatyatidurvāraṃ viṣāgniṃ vāsukerapi" },
      { type: "verse", number: "75", sanskrit: "नृपोनेनानुलिप्ताङ्गो भवेत् सर्वजनप्रियः तेजस्वितां च लभते राजकस्यापि मध्यगः", text: "nṛponenānuliptāṅgo bhavet sarvajanapriyaḥ tejasvitāṃ ca labhate rājakasyāpi madhyagaḥ" },
      { type: "verse", number: "76", sanskrit: "शीतमेव च कुर्वीत विधानं विषरोगिणाम् मुक्त्वा कीटविषं तद्धि शीतेनातिप्रबर्द्धते", text: "śītameva ca kurvīta vidhānaṃ viṣarogiṇām muktvā kīṭaviṣaṃ taddhi śītenātiprabarddhate" },
      { type: "verse", number: "77", sanskrit: "शालयः षष्टिका जीर्णाः कोरदूषाः प्रियङ्गवः मुद्गो हरेणुस्तुवरी पटोलं वेत्रपल्लवाः", text: "śālayaḥ ṣaṣṭikā jīrṇāḥ koradūṣāḥ priyaṅgavaḥ mudgo hareṇustuvarī paṭolaṃ vetrapallavāḥ" },
      { type: "verse", number: "78", sanskrit: "तण्डुलीयकजीवन्ती वार्ताकं सुनिषण्णकः जाङ्गलं दाडिमं धात्री कपित्थं सैन्धवं सिता", text: "taṇḍulīyakajīvantī vārtākaṃ suniṣaṇṇakaḥ jāṅgalaṃ dāḍimaṃ dhātrī kapitthaṃ saindhavaṃ sitā" },
      { type: "verse", number: "79", sanskrit: "अविदाहियदन्यच्च विज्ञायान्नस्वरूपतः तत्तद्दद्याद्विषार्तेभ्यः कार्या व्यञ्जनसंस्कृतिः कषायैर्विषहन्तृऋणां घृनैः कल्याणकादिभिः", text: "avidāhiyadanyacca vijñāyānnasvarūpataḥ tattaddadyādviṣārtebhyaḥ kāryā vyañjanasaṃskṛtiḥ kaṣāyairviṣahantṛṛṇāṃ ghṛnaiḥ kalyāṇakādibhiḥ" },
      { type: "verse", number: "80", sanskrit: "दिव्यसारसकूपोत्थमन्यद्वा शृतशीतलम् मध्वामलकयुक्तं वा विषार्त्तः सलिलं पिबेत् नदीतटाकजं त्याज्यं विशेषेण घनागमे", text: "divyasārasakūpotthamanyadvā śṛtaśītalam madhvāmalakayuktaṃ vā viṣārttaḥ salilaṃ pibet nadītaṭākajaṃ tyājyaṃ viśeṣeṇa ghanāgame" },
      { type: "verse", number: "81", sanskrit: "शुक्लवस्त्रोदरायातैः सुकृताः सक्तवो यवैः तक्रेण सघृताः पीताः परमं विषनाशनाः", text: "śuklavastrodarāyātaiḥ sukṛtāḥ saktavo yavaiḥ takreṇa saghṛtāḥ pītāḥ paramaṃ viṣanāśanāḥ" },
      { type: "verse", number: "82", sanskrit: "तिलमद्यकुलत्थक्षुत्क्रुद्भयायासमैथुनम् वर्जयेद्विषमुक्तोपि दिवास्वप्नं विशेषतः", text: "tilamadyakulatthakṣutkrudbhayāyāsamaithunam varjayedviṣamuktopi divāsvapnaṃ viśeṣataḥ" },
      { type: "verse", number: "83", sanskrit: "प्रशान्तदोषं प्रकृतिस्थधातु माहारकामं सममूत्रविट्कम् प्रसन्नवर्णेन्द्रियचित्तचेष्टं वैद्योवगच्छेदविषं मनुष्यम्", text: "praśāntadoṣaṃ prakṛtisthadhātu māhārakāmaṃ samamūtraviṭkam prasannavarṇendriyacittaceṣṭaṃ vaidyovagacchedaviṣaṃ manuṣyam" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 48,
    lang: "sa",
    content: [
      { type: "heading", heading: "Випака санграха — о постпищеварительном эффекте" },
      { type: "text", text: "Глава 48 Уттара стханы — «Випака санграха» — посвящена специализированному разделу: о постпищеварительном эффекте. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो विषोपयोगीयं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः विषे प्रतिविषं योज्यं मन्त्रतन्त्रैरसिध्यति अतीते पञ्चमे वेगे सप्तमस्यानतिक्रमे प्रभोनिर्वद्ये प्रयतो नैव वाख्याय कस्यचित्", text: "athāto viṣopayogīyaṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ viṣe prativiṣaṃ yojyaṃ mantratantrairasidhyati atīte pañcame vege saptamasyānatikrame prabhonirvadye prayato naiva vākhyāya kasyacit" },
      { type: "verse", number: "2", sanskrit: "सिद्धमन्त्रधरः कृत्वा धरणीबन्धमादितः नहि मन्त्रसहायस्य विषं यात्यविधेयताम्", text: "siddhamantradharaḥ kṛtvā dharaṇībandhamāditaḥ nahi mantrasahāyasya viṣaṃ yātyavidheyatām" },
      { type: "verse", number: "3", sanskrit: "श्लेष्मतुल्यगुणं प्रायः स्थिरमूर्ध्वगमं विषम् प्रायः पित्तगुणैर्युक्तमधोगामि च जङ्गमम्", text: "śleṣmatulyaguṇaṃ prāyaḥ sthiramūrdhvagamaṃ viṣam prāyaḥ pittaguṇairyuktamadhogāmi ca jaṅgamam" },
      { type: "verse", number: "4", sanskrit: "गुणैरिति विपर्यस्तैर्निहतस्ते परस्परम् युञ्ज्यान्मूलविषं तस्माद्दष्टानां पानलेपयोः", text: "guṇairiti viparyastairnihataste parasparam yuñjyānmūlaviṣaṃ tasmāddaṣṭānāṃ pānalepayoḥ" },
      { type: "verse", number: "5", sanskrit: "विषपीतं च कुशलो दंशयेत् पवनाशिभिः न विषप्रतिमं किञ्चिन्निर्विषीकरणं विषे", text: "viṣapītaṃ ca kuśalo daṃśayet pavanāśibhiḥ na viṣapratimaṃ kiñcinnirviṣīkaraṇaṃ viṣe" },
      { type: "verse", number: "6", sanskrit: "चतुर्भिः षड्भिरष्टाभिर्हीनमध्योत्तमां यवैः मात्रां विषस्य मौलस्य प्रयुञ्जीत यथायथम्", text: "caturbhiḥ ṣaḍbhiraṣṭābhirhīnamadhyottamāṃ yavaiḥ mātrāṃ viṣasya maulasya prayuñjīta yathāyatham" },
      { type: "verse", number: "7", sanskrit: "दष्टस्य द्वौ यवौ कीटैस्तिलमात्रं तु वृश्चिकैः नैव स्वसृक्स्थे पाने तु लूतादष्टस्य नेष्यते", text: "daṣṭasya dvau yavau kīṭaistilamātraṃ tu vṛścikaiḥ naiva svasṛksthe pāne tu lūtādaṣṭasya neṣyate" },
      { type: "verse", number: "8", sanskrit: "सविषे युक्तममृतं विषमेवाविषे विषम् अबले चातिबलवद्व्यापन्नं च प्रयोगतः", text: "saviṣe yuktamamṛtaṃ viṣamevāviṣe viṣam abale cātibalavadvyāpannaṃ ca prayogataḥ" },
      { type: "verse", number: "9", sanskrit: "सविषाविषशङ्कायामगदानुपयोजयेत् अविरुद्धान् प्रयुक्तो हि निर्विषस्यागदो गदः", text: "saviṣāviṣaśaṅkāyāmagadānupayojayet aviruddhān prayukto hi nirviṣasyāgado gadaḥ" },
      { type: "verse", number: "10", sanskrit: "तद्वच्च सविषत्यापि क्रियाकालातिपाततः जानीयाद्विषसद्भावं भिषक्तस्मात् प्रयत्नतः", text: "tadvacca saviṣatyāpi kriyākālātipātataḥ jānīyādviṣasadbhāvaṃ bhiṣaktasmāt prayatnataḥ" },
      { type: "verse", number: "11", sanskrit: "साक्तुकं मुस्तकं शृङ्गी वालकं सर्षपाह्वयम् वत्स्स्नाभं च कर्मण्यं विषं स्निग्धं घनं गुरु नजात्वन्यत् प्रयोक्तव्यं कालकूटं विशेषतः", text: "sāktukaṃ mustakaṃ śṛṅgī vālakaṃ sarṣapāhvayam vatssnābhaṃ ca karmaṇyaṃ viṣaṃ snigdhaṃ ghanaṃ guru najātvanyat prayoktavyaṃ kālakūṭaṃ viśeṣataḥ" },
      { type: "verse", number: "12", sanskrit: "विषे ऽवचारिते तीक्ष्णे पेयं घृतमनन्तरम् सभार्ङ्गीदधिधूमोत्थसारिवातण्डुलीयकम्", text: "viṣe 'vacārite tīkṣṇe peyaṃ ghṛtamanantaram sabhārṅgīdadhidhūmotthasārivātaṇḍulīyakam" },
      { type: "verse", number: "13", sanskrit: "अगारधूममञ्जिष्ठायष्ट्याह्वैर्वा समन्वितम् लिह्याद्वा मधुसर्पिर्भ्यां चूर्णितामर्जुनत्वचम्", text: "agāradhūmamañjiṣṭhāyaṣṭyāhvairvā samanvitam lihyādvā madhusarpirbhyāṃ cūrṇitāmarjunatvacam" },
      { type: "verse", number: "14", sanskrit: "क्षीरक्षौद्रघृतैर्युक्तं पीतं हन्ति विषं विषम्", text: "kṣīrakṣaudraghṛtairyuktaṃ pītaṃ hanti viṣaṃ viṣam" },
      { type: "verse", number: "15", sanskrit: "ससिन्दुवारतगरं मृतसञ्जीवनं विषम्", text: "sasinduvāratagaraṃ mṛtasañjīvanaṃ viṣam" },
      { type: "verse", number: "16", sanskrit: "शिरीषकुसुमं वक्रं विषमाखुविषापहम् देवदारुनतंमांसी द्रामिलीबाकुचीविषम् कुष्ठं च पानलेपाभ्यां समस्तविषशाशनम्", text: "śirīṣakusumaṃ vakraṃ viṣamākhuviṣāpaham devadārunataṃmāṃsī drāmilībākucīviṣam kuṣṭhaṃ ca pānalepābhyāṃ samastaviṣaśāśanam" },
      { type: "verse", number: "17", sanskrit: "मनश्शिलाज्जनालैला सिन्दुवारामराह्वयम् सरक्ताकुंकुमविषं ध्मानं निस्संज्ञबोधनम्", text: "manaśśilājjanālailā sinduvārāmarāhvayam saraktākuṃkumaviṣaṃ dhmānaṃ nissaṃjñabodhanam" },
      { type: "verse", number: "18", sanskrit: "दाहे विषोद्भवे लेपः सक्तुक्षीरघृतैर्हितः", text: "dāhe viṣodbhave lepaḥ saktukṣīraghṛtairhitaḥ" },
      { type: "verse", number: "19", sanskrit: "यस्तु संरोषितो भोगी धूमं वक्त्राद्विमुञ्ज्चति दण्डाग्रे पिशितं बध्वा बहुशस्तेन दंशयेत्", text: "yastu saṃroṣito bhogī dhūmaṃ vaktrādvimuñjcati daṇḍāgre piśitaṃ badhvā bahuśastena daṃśayet" },
      { type: "verse", number: "20", sanskrit: "अशक्यमगदैरन्यैर्विषपीतं चिकित्सकः पाययेन्मांसचूर्णं तं ज्ञात्वा विषबलाबलम्", text: "aśakyamagadairanyairviṣapītaṃ cikitsakaḥ pāyayenmāṃsacūrṇaṃ taṃ jñātvā viṣabalābalam" },
      { type: "verse", number: "21", sanskrit: "अन्येष्वपि च रोगेषु शेषोपायपरिक्षये विषं युञ्जीत नित्यं च रसायनगवेषिणः", text: "anyeṣvapi ca rogeṣu śeṣopāyaparikṣaye viṣaṃ yuñjīta nityaṃ ca rasāyanagaveṣiṇaḥ" },
      { type: "verse", number: "22", sanskrit: "घृतोपस्कृतदेहस्य विशुद्धस्य हिताशिनः सात्विकस्योदिते भानौ योज्यं शीतवसन्तयोः", text: "ghṛtopaskṛtadehasya viśuddhasya hitāśinaḥ sātvikasyodite bhānau yojyaṃ śītavasantayoḥ" },
      { type: "verse", number: "23", sanskrit: "ग्रीष्मेप्यात्ययिके व्याधौ न च वर्षासु दुर्दिने", text: "grīṣmepyātyayike vyādhau na ca varṣāsu durdine" },
      { type: "verse", number: "24", sanskrit: "न क्रोधने न पित्तार्ते न क्लीबे राजनि द्विजे क्षुत्तृष्णाश्रमघर्माध्वव्याध्यन्तरनिपीडिते गर्भिणीबालवृद्धेषु न रूक्षेषु न मर्मसु", text: "na krodhane na pittārte na klībe rājani dvije kṣuttṛṣṇāśramagharmādhvavyādhyantaranipīḍite garbhiṇībālavṛddheṣu na rūkṣeṣu na marmasu" },
      { type: "verse", number: "25", sanskrit: "अभ्यस्तेपि विषे यत्नाद्वर्जनीयान् विवर्जयेत् कट्वम्लतैललवणदिवास्वप्नातपानलान् रूक्षमन्नं विशेषेण भयं वाजीर्णतः सदा", text: "abhyastepi viṣe yatnādvarjanīyān vivarjayet kaṭvamlatailalavaṇadivāsvapnātapānalān rūkṣamannaṃ viśeṣeṇa bhayaṃ vājīrṇataḥ sadā" },
      { type: "verse", number: "26", sanskrit: "दृग्विभ्रमं कर्णरुजामन्यांश्चानिलजान् गदान् विषं रूक्षाशिनः कुर्यान्मृत्युमेव त्वजीर्णतः", text: "dṛgvibhramaṃ karṇarujāmanyāṃścānilajān gadān viṣaṃ rūkṣāśinaḥ kuryānmṛtyumeva tvajīrṇataḥ" },
      { type: "verse", number: "27", sanskrit: "अलं गोमूत्रसंयुक्तमातपे शोषयेत् त्र्यहम् विषं बृंहणमेतद्धि विषस्यादौ प्रशस्यते", text: "alaṃ gomūtrasaṃyuktamātape śoṣayet tryaham viṣaṃ bṛṃhaṇametaddhi viṣasyādau praśasyate" },
      { type: "verse", number: "28", sanskrit: "तत् पिबेन्मस्तुना वातज्वरे क्षीरेण पैत्तिके युक्तं मूत्रेण कफजे सर्वजे त्रिफलाम्भसा", text: "tat pibenmastunā vātajvare kṣīreṇa paittike yuktaṃ mūtreṇa kaphaje sarvaje triphalāmbhasā" },
      { type: "verse", number: "29", sanskrit: "लोध्रचन्दनषड्ग्रन्थाशर्कराघृतमाक्षिकैः क्षीरेण च विषं युक्तं जीर्णज्वरहरं परम्", text: "lodhracandanaṣaḍgranthāśarkarāghṛtamākṣikaiḥ kṣīreṇa ca viṣaṃ yuktaṃ jīrṇajvaraharaṃ param" },
      { type: "verse", number: "30", sanskrit: "निकुम्भकुम्भत्रिफलासर्पिर्मधुविषैःकृतः निहन्ति मोदको जीर्णज्वरमेहत्वगामयान् शिखिकर्किरसोपेतं विषमज्वरजिद्विषम्", text: "nikumbhakumbhatriphalāsarpirmadhuviṣaiḥkṛtaḥ nihanti modako jīrṇajvaramehatvagāmayān śikhikarkirasopetaṃ viṣamajvarajidviṣam" },
      { type: "verse", number: "31", sanskrit: "विषं यष्ट्याह्वयं रास्नासेव्यमुत्पलकन्दकम् तण्डुलोदकपीतानि रक्तपित्तस्य भेषजम्", text: "viṣaṃ yaṣṭyāhvayaṃ rāsnāsevyamutpalakandakam taṇḍulodakapītāni raktapittasya bheṣajam" },
      { type: "verse", number: "32", sanskrit: "विषं रसाञ्जनं भार्ङ्गी वृश्चिकाली महासहा सवेदने सपाके च व्रणे दुष्टे प्रलेपनम्", text: "viṣaṃ rasāñjanaṃ bhārṅgī vṛścikālī mahāsahā savedane sapāke ca vraṇe duṣṭe pralepanam" },
      { type: "verse", number: "33", sanskrit: "सिताविषक्षीरतरुप्रवाला मधुना द्रुताः श्वासहिध्मापहा लीढाश्छर्दिध्न्यस्तु विषान्विताः क्षौद्रोशीरमधुक्षाररजनीकुटजत्वचः", text: "sitāviṣakṣīratarupravālā madhunā drutāḥ śvāsahidhmāpahā līḍhāśchardidhnyastu viṣānvitāḥ kṣaudrośīramadhukṣārarajanīkuṭajatvacaḥ" },
      { type: "verse", number: "34", sanskrit: "विजयापिप्पलीमूलपिप्पलीद्वयचित्रकैः पुष्कराह्वशठीद्राक्षायवानीक्षारदीप्यकैः", text: "vijayāpippalīmūlapippalīdvayacitrakaiḥ puṣkarāhvaśaṭhīdrākṣāyavānīkṣāradīpyakaiḥ" },
      { type: "verse", number: "35", sanskrit: "सितायष्टीद्विबृहतीसैन्धवैः पालिकैः पचेत् सविषार्द्धपलैः प्रस्थं घृतात्तज्जीर्णभुक्पिबेत्", text: "sitāyaṣṭīdvibṛhatīsaindhavaiḥ pālikaiḥ pacet saviṣārddhapalaiḥ prasthaṃ ghṛtāttajjīrṇabhukpibet" },
      { type: "verse", number: "36", sanskrit: "दुर्नाममेहगुल्मार्मतिमिरक्रिमिपाण्डुताः गलग्रहग्रहोन्मादकुष्ठानि च नियच्छति", text: "durnāmamehagulmārmatimirakrimipāṇḍutāḥ galagrahagrahonmādakuṣṭhāni ca niyacchati" },
      { type: "verse", number: "37", sanskrit: "कृच्छ्रघ्ना विषपथ्याग्निदन्तीद्राक्षानिशाविषाः शिलाजतु विषं मूत्रमुदावर्ताश्मरीहरम्", text: "kṛcchraghnā viṣapathyāgnidantīdrākṣāniśāviṣāḥ śilājatu viṣaṃ mūtramudāvartāśmarīharam" },
      { type: "verse", number: "38", sanskrit: "गोमूत्रक्षारसिन्धूत्थं विषं पाषाणभेदकम् वज्रवद्दारयत्येतदेकतः पीतमश्मरीम्", text: "gomūtrakṣārasindhūtthaṃ viṣaṃ pāṣāṇabhedakam vajravaddārayatyetadekataḥ pītamaśmarīm" },
      { type: "verse", number: "39", sanskrit: "समूला पिप्पली मूत्रं विषं शूलहरं तथा विषद्रवन्तीमधुकद्राक्षारास्नाशठी कणाः", text: "samūlā pippalī mūtraṃ viṣaṃ śūlaharaṃ tathā viṣadravantīmadhukadrākṣārāsnāśaṭhī kaṇāḥ" },
      { type: "verse", number: "40", sanskrit: "एरण्डतैलं त्रिफला गोमूत्रं चित्रको विषम् सर्पिषा सहितं पीतं वाताण्डत्वमपोहति", text: "eraṇḍatailaṃ triphalā gomūtraṃ citrako viṣam sarpiṣā sahitaṃ pītaṃ vātāṇḍatvamapohati" },
      { type: "verse", number: "41", sanskrit: "त्रिफला स्वर्जिकाक्षारो विषं गुल्मप्रभेदनम् विषवेल्लमिसिक्षीरं गुल्मप्लीहनिबर्हणम्", text: "triphalā svarjikākṣāro viṣaṃ gulmaprabhedanam viṣavellamisikṣīraṃ gulmaplīhanibarhaṇam" },
      { type: "verse", number: "42", sanskrit: "प्लीहोदरघ्नं पयसा शताह्वा क्रिमिजिद्विषम्", text: "plīhodaraghnaṃ payasā śatāhvā krimijidviṣam" },
      { type: "verse", number: "43", sanskrit: "वायसीमूलनिष्क्काथपीतं कुष्ठहरं विषम्", text: "vāyasīmūlaniṣkkāthapītaṃ kuṣṭhaharaṃ viṣam" },
      { type: "verse", number: "44", sanskrit: "वायस्याराजवृक्षत्वक्त्रायन्तीबाकुचीफलात् प्लीहघ्नेभकणाभ्यां च विषं क्वाथेन कुष्ठजित्", text: "vāyasyārājavṛkṣatvaktrāyantībākucīphalāt plīhaghnebhakaṇābhyāṃ ca viṣaṃ kvāthena kuṣṭhajit" },
      { type: "verse", number: "45", sanskrit: "अवल्गुजैडगजयोर्बीजं क्षारद्वयं विषम् लेपः ससैन्धवः पिष्टो वारिणा कुष्ठनाशनः", text: "avalgujaiḍagajayorbījaṃ kṣāradvayaṃ viṣam lepaḥ sasaindhavaḥ piṣṭo vāriṇā kuṣṭhanāśanaḥ" },
      { type: "verse", number: "46", sanskrit: "चित्रकार्कजटाहस्तिपिप्पलीबाकुचीविषैः गोमूत्रपिष्टैरन्योन्योमनोह्वास्नुक्पयोविषैः", text: "citrakārkajaṭāhastipippalībākucīviṣaiḥ gomūtrapiṣṭairanyonyomanohvāsnukpayoviṣaiḥ" },
      { type: "verse", number: "47", sanskrit: "सचन्द्रलेखैडगजकरञ्जफलसैन्धवैः सव्योषस्वर्जिकाक्षारयवक्षारनिशाद्वयैः अगारधूमसहितैर्बस्तमूत्रेण कल्कितैः भल्लातकाग्निशम्याकविषैर्गोमूत्रपेषितैः लेपो विचर्चिकाददुशतारुःकिटिभापहः शम्याकपत्रत्वङ्मूलं विषं तक्रं च तद्गुणम्", text: "sacandralekhaiḍagajakarañjaphalasaindhavaiḥ savyoṣasvarjikākṣārayavakṣāraniśādvayaiḥ agāradhūmasahitairbastamūtreṇa kalkitaiḥ bhallātakāgniśamyākaviṣairgomūtrapeṣitaiḥ lepo vicarcikādaduśatāruḥkiṭibhāpahaḥ śamyākapatratvaṅmūlaṃ viṣaṃ takraṃ ca tadguṇam" },
      { type: "verse", number: "48", sanskrit: "विषभल्लातकद्वीपिगुञ्जानिम्बफलैर्जयेत् लेपोम्लपिष्टैः श्वित्राणि पुण्डरीकं च दारुणम्", text: "viṣabhallātakadvīpiguñjānimbaphalairjayet lepomlapiṣṭaiḥ śvitrāṇi puṇḍarīkaṃ ca dāruṇam" },
      { type: "verse", number: "49", sanskrit: "वक्रकुष्ठरसद्वीपिस्पृक्कापत्रैलवालुकम् पिष्टं खदिरतोयेन त्रिरात्रमुषितं पिबेत्", text: "vakrakuṣṭharasadvīpispṛkkāpatrailavālukam piṣṭaṃ khadiratoyena trirātramuṣitaṃ pibet" },
      { type: "verse", number: "50", sanskrit: "श्वित्री विषेण संसृष्टं ततः स्फोटान् किलासजान् कण्टकेन विभिद्यानु लेपैर्लिम्पेत कौष्ठिकैः", text: "śvitrī viṣeṇa saṃsṛṣṭaṃ tataḥ sphoṭān kilāsajān kaṇṭakena vibhidyānu lepairlimpeta kauṣṭhikaiḥ" },
      { type: "verse", number: "51", sanskrit: "अथवा करवीरार्कमूलबाकुचिकाविषैः बताम्बुपिष्टैः सद्वीपिद्विपपिप्पल्यरुष्करैः", text: "athavā karavīrārkamūlabākucikāviṣaiḥ batāmbupiṣṭaiḥ sadvīpidvipapippalyaruṣkaraiḥ" },
      { type: "verse", number: "52", sanskrit: "लाक्षासुराह्वामञ्जिष्ठाकुष्ठपद्मकसारिवाः गुञ्जाफलं कुरबको लाङ्गली वज्रकन्दकः", text: "lākṣāsurāhvāmañjiṣṭhākuṣṭhapadmakasārivāḥ guñjāphalaṃ kurabako lāṅgalī vajrakandakaḥ" },
      { type: "verse", number: "53", sanskrit: "वाराहीकन्दकास्फोता सप्ताह्वगिरिकर्णिकाः अर्काश्वमारयोर्मूलं नागपुष्पं नतं निशे", text: "vārāhīkandakāsphotā saptāhvagirikarṇikāḥ arkāśvamārayormūlaṃ nāgapuṣpaṃ nataṃ niśe" },
      { type: "verse", number: "54", sanskrit: "दन्ती विषं सातिविषं पिप्पली मरिचानि च तैस्तैल्ं कटुतैलं वा श्वित्रस्याभ्यञ्जनं पचेत् सवर्णीकरणं श्रेष्ठमास्तिकस्य वचो यथा", text: "dantī viṣaṃ sātiviṣaṃ pippalī maricāni ca taistailṃ kaṭutailaṃ vā śvitrasyābhyañjanaṃ pacet savarṇīkaraṇaṃ śreṣṭhamāstikasya vaco yathā" },
      { type: "verse", number: "55", sanskrit: "वीरा लाङ्गलिकी दन्ती विषपाषाणभेदकैः प्रयोज्यो मूढगर्भाणां प्रलेपो गर्भमोचनः", text: "vīrā lāṅgalikī dantī viṣapāṣāṇabhedakaiḥ prayojyo mūḍhagarbhāṇāṃ pralepo garbhamocanaḥ" },
      { type: "verse", number: "56", sanskrit: "स्वरसं बीजपूरस्य वचां ब्राह्मीरसं घृतम् बन्ध्या पिबन्ती सविषं सुपुत्रैः परिवार्यते", text: "svarasaṃ bījapūrasya vacāṃ brāhmīrasaṃ ghṛtam bandhyā pibantī saviṣaṃ suputraiḥ parivāryate" },
      { type: "verse", number: "57", sanskrit: "नष्टशुक्रः पयो द्राक्षाकपिकच्छु वचा विषम्", text: "naṣṭaśukraḥ payo drākṣākapikacchu vacā viṣam" },
      { type: "verse", number: "58", sanskrit: "विषं सर्पिः सिता क्षौद्रं तिमिरापहमञ्जनम् विषं चैकमजाक्षीरकल्कितं घृतधूपितम्", text: "viṣaṃ sarpiḥ sitā kṣaudraṃ timirāpahamañjanam viṣaṃ caikamajākṣīrakalkitaṃ ghṛtadhūpitam" },
      { type: "verse", number: "59", sanskrit: "विषं धात्रीफलरसैरसकृत् परिभावितम् अञ्जनं शङ्खसहितं प्रगाढतिमिरप्रणुत्", text: "viṣaṃ dhātrīphalarasairasakṛt paribhāvitam añjanaṃ śaṅkhasahitaṃ pragāḍhatimirapraṇut" },
      { type: "verse", number: "60", sanskrit: "विषमिन्द्रायुधं स्तन्ये घृष्टं काचजिदञ्जनम् बीजपूररसे घृष्टं विषं तद्वत्सितायुतम् विषं मागधिका द्वे च निशे काचघ्रमञ्जनम्", text: "viṣamindrāyudhaṃ stanye ghṛṣṭaṃ kācajidañjanam bījapūrarase ghṛṣṭaṃ viṣaṃ tadvatsitāyutam viṣaṃ māgadhikā dve ca niśe kācaghramañjanam" },
      { type: "verse", number: "61", sanskrit: "शुक्लार्मजिद्विषं कृष्णायुक्तं गोमूत्रभावितम्", text: "śuklārmajidviṣaṃ kṛṣṇāyuktaṃ gomūtrabhāvitam" },
      { type: "verse", number: "62", sanskrit: "समुद्रफेनस्फटिककुरुविन्दसुधाञ्जनम् कूर्मपृष्ठं च तुल्यानि तेभ्योर्द्धांशा मनश्शिला", text: "samudraphenasphaṭikakuruvindasudhāñjanam kūrmapṛṣṭhaṃ ca tulyāni tebhyorddhāṃśā manaśśilā" },
      { type: "verse", number: "63", sanskrit: "अर्द्धहीनानि मरिचसैन्धवायोरजांसि च अतो यथोत्तरं दद्यादयसा च समं विषम् रसक्रियेयं मधुना शुक्लपिल्लार्मकाचहृत्", text: "arddhahīnāni maricasaindhavāyorajāṃsi ca ato yathottaraṃ dadyādayasā ca samaṃ viṣam rasakriyeyaṃ madhunā śuklapillārmakācahṛt" },
      { type: "verse", number: "64", sanskrit: "अभीक्ष्णं शीततोयेन सिञ्ज्चेन्नेत्रे विषाञ्जिते", text: "abhīkṣṇaṃ śītatoyena siñjcennetre viṣāñjite" },
      { type: "verse", number: "65", sanskrit: "रसोनकन्दमरिचविषसर्षपसैन्धवैः पिल्लेक्षि लिखितं पूर्वं सुरसारसपेषितैः", text: "rasonakandamaricaviṣasarṣapasaindhavaiḥ pillekṣi likhitaṃ pūrvaṃ surasārasapeṣitaiḥ" },
      { type: "verse", number: "66", sanskrit: "पूरयेत् सर्पिषा चानु सर्पिरेव च पाययेत् मधूकसारमधुकविषक्षीरजलैर्घृतम् पक्वं सन्तर्पणं श्रेष्ठं रात्र्यन्धत्वे चिरोत्थिते", text: "pūrayet sarpiṣā cānu sarpireva ca pāyayet madhūkasāramadhukaviṣakṣīrajalairghṛtam pakvaṃ santarpaṇaṃ śreṣṭhaṃ rātryandhatve cirotthite" },
      { type: "verse", number: "67", sanskrit: "नस्यं शिरोरुक्शमनं प्रत्यक्पुष्पी सिता विषम् अथवा घृतयष्ट्याह्वशर्करा विषसंयुताः", text: "nasyaṃ śirorukśamanaṃ pratyakpuṣpī sitā viṣam athavā ghṛtayaṣṭyāhvaśarkarā viṣasaṃyutāḥ" },
      { type: "verse", number: "68", sanskrit: "शुण्ठी पथ्या विषं पाठा द्रवन्ती पूतिनासजित्", text: "śuṇṭhī pathyā viṣaṃ pāṭhā dravantī pūtināsajit" },
      { type: "verse", number: "69", sanskrit: "कटुतैलं विषं नस्यं पलितारूंषिकापहम्", text: "kaṭutailaṃ viṣaṃ nasyaṃ palitārūṃṣikāpaham" },
      { type: "verse", number: "70", sanskrit: "स्वर्जिकाक्षारसिन्धूत्थशुक्तयुक्तं विषं परम् कर्णयोः पूरणं तीव्रकर्णशूलनिबर्हणम्", text: "svarjikākṣārasindhūtthaśuktayuktaṃ viṣaṃ param karṇayoḥ pūraṇaṃ tīvrakarṇaśūlanibarhaṇam" },
      { type: "verse", number: "71", sanskrit: "प्रपौण्डरीकमञ्जिष्ठाविषसिन्धुसमुद्भवैः निहन्ति साधितं तैलं गण्डूषेण मुखामयान्", text: "prapauṇḍarīkamañjiṣṭhāviṣasindhusamudbhavaiḥ nihanti sādhitaṃ tailaṃ gaṇḍūṣeṇa mukhāmayān" },
      { type: "verse", number: "72", sanskrit: "देवदारु विषं सर्पिर्गोमूत्रं कण्टकारिका वाचःस्खलनतां हन्ति पीतमित्याह काश्यपः", text: "devadāru viṣaṃ sarpirgomūtraṃ kaṇṭakārikā vācaḥskhalanatāṃ hanti pītamityāha kāśyapaḥ" },
      { type: "verse", number: "73", sanskrit: "शत्रुप्रयुक्ताद्विषतो गराद्वा लूताभुजङ्गाखुगणाज्जरायाः अकालमृत्योर्ग्रहपाप्मतो वा विषाशिनो नास्ति भयं नरस्य", text: "śatruprayuktādviṣato garādvā lūtābhujaṅgākhugaṇājjarāyāḥ akālamṛtyorgrahapāpmato vā viṣāśino nāsti bhayaṃ narasya" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 49,
    lang: "sa",
    content: [
      { type: "heading", heading: "Карма санграха — о действии препаратов" },
      { type: "text", text: "Глава 49 Уттара стханы — «Карма санграха» — посвящена специализированному разделу: о действии препаратов. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो रसायनविधिं नामाध्यायं व्याख्यास्यामः इति ह स्माहुरात्रेयादयो महर्षयः दीर्घमायुः स्मृतिं मेधामारोग्य्ंअ तरुणं वयः प्रभा वर्णस्वरौदार्यं देहेन्द्रियबलोदयम्", text: "athāto rasāyanavidhiṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhurātreyādayo maharṣayaḥ dīrghamāyuḥ smṛtiṃ medhāmārogyṃa taruṇaṃ vayaḥ prabhā varṇasvaraudāryaṃ dehendriyabalodayam" },
      { type: "verse", number: "2", sanskrit: "वाक्सिद्धिं वृषतां कान्तिमवाप्नोति रसायनात् लाभोपायो हि शस्यानां रसादीनां रसायनम्", text: "vāksiddhiṃ vṛṣatāṃ kāntimavāpnoti rasāyanāt lābhopāyo hi śasyānāṃ rasādīnāṃ rasāyanam" },
      { type: "verse", number: "3", sanskrit: "पूर्वे वयसि मध्ये वा तत्प्रयोज्यं जितात्मनः स्निग्धस्य स्रुतरक्तस्य विशुद्धस्य च सर्वथा", text: "pūrve vayasi madhye vā tatprayojyaṃ jitātmanaḥ snigdhasya srutaraktasya viśuddhasya ca sarvathā" },
      { type: "verse", number: "4", sanskrit: "अविशुद्धे शरीरे हि युक्तो रासायनो विधिः न भाति मलसंसृष्टे वस्त्रे राग इवार्पितः", text: "aviśuddhe śarīre hi yukto rāsāyano vidhiḥ na bhāti malasaṃsṛṣṭe vastre rāga ivārpitaḥ" },
      { type: "verse", number: "5", sanskrit: "युक्तं संस्कारहीनस्य सम्यगप्यप्रमादिनः यथैव पौरुषं तद्वन्नसिध्यति रसायनम्", text: "yuktaṃ saṃskārahīnasya samyagapyapramādinaḥ yathaiva pauruṣaṃ tadvannasidhyati rasāyanam" },
      { type: "verse", number: "6", sanskrit: "सर्वे च दोषा भवन्ति ग्राम्यादाहारादम्ललवणकटुकक्षारविरुद्वासात्म्यरूक्षाभिष्यन्दिक्लिन्नगुरुपूतिपुर्युषितनवधान्यशुष्कशाकाममांसतिलकुलत्थदधिशुक्तकाञ्जिकपिष्टान्नविरूढकनिषेविणां दिवास्वप्नस्त्रीमद्यनित्यानां विषमातिमात्रव्यायामायामसङ्क्षोभितवपुषां क्रोधलोभभयशोकायासबहुलाना पापकर्मणामसमञ्जसाहारविहारनिर्हारनिरतानाम्", text: "sarve ca doṣā bhavanti grāmyādāhārādamlalavaṇakaṭukakṣāravirudvāsātmyarūkṣābhiṣyandiklinnagurupūtipuryuṣitanavadhānyaśuṣkaśākāmamāṃsatilakulatthadadhiśuktakāñjikapiṣṭānnavirūḍhakaniṣeviṇāṃ divāsvapnastrīmadyanityānāṃ viṣamātimātravyāyāmāyāmasaṅkṣobhitavapuṣāṃ krodhalobhabhayaśokāyāsabahulānā pāpakarmaṇāmasamañjasāhāravihāranirhāraniratānām" },
      { type: "verse", number: "7", sanskrit: "अतो निमित्तं ह्यविशुद्धः सञ्जायते रसो विदह्यते रक्तं शिथिलीभवन्ति मांसानि विष्यन्दते मेदो दूष्यन्ते दोषा विमुच्यन्ते सन्धयो न सन्धीयन्तेस्थिषु मज्जानो नाप्यायते शुक्रं नौजो न बलं न वीर्यम्", text: "ato nimittaṃ hyaviśuddhaḥ sañjāyate raso vidahyate raktaṃ śithilībhavanti māṃsāni viṣyandate medo dūṣyante doṣā vimucyante sandhayo na sandhīyantesthiṣu majjāno nāpyāyate śukraṃ naujo na balaṃ na vīryam" },
      { type: "verse", number: "8", sanskrit: "ततः स एवंभूतो ग्लायति सीदति निद्रातन्द्रालस्यसमन्वितः खिद्यते निर्विद्यते निरुत्साहो ऽसमर्थः शारीरमानसानां विशिष्टानां चेष्टानां भ्रष्टच्छायो नष्टस्मृतिरल्पबुद्धिरसम्पाद्यमानाभिलषितार्थो ऽहर्निशमनिशमनिशं निश्वसन्नधिष्ठानभूतो रोगाणां नोपात्तमपि सर्वमायुरवाप्नोति", text: "tataḥ sa evaṃbhūto glāyati sīdati nidrātandrālasyasamanvitaḥ khidyate nirvidyate nirutsāho 'samarthaḥ śārīramānasānāṃ viśiṣṭānāṃ ceṣṭānāṃ bhraṣṭacchāyo naṣṭasmṛtiralpabuddhirasampādyamānābhilaṣitārtho 'harniśamaniśamaniśaṃ niśvasannadhiṣṭhānabhūto rogāṇāṃ nopāttamapi sarvamāyuravāpnoti" },
      { type: "verse", number: "9", sanskrit: "तस्मात् बुद्धिमानपास्य यथोक्तानाहारादिदोषान् निर्वाह्य च पूर्वोपचितान् रसायनं विधिविहितमुपसेवेत", text: "tasmāt buddhimānapāsya yathoktānāhārādidoṣān nirvāhya ca pūrvopacitān rasāyanaṃ vidhivihitamupaseveta" },
      { type: "verse", number: "10", sanskrit: "तत्तु द्विविधं कुटीप्रावेशिकं वातातपिकं च तत्र वीर्यप्रभावप्रयोगपरिहारगुरुत्वात् कुटीप्रावेशिकं महाफलतरम्", text: "tattu dvividhaṃ kuṭīprāveśikaṃ vātātapikaṃ ca tatra vīryaprabhāvaprayogaparihāragurutvāt kuṭīprāveśikaṃ mahāphalataram" },
      { type: "verse", number: "11", sanskrit: "तस्य विधिः क्षेमसुभिक्षधार्मिकशद्दधानजननृपवैद्यविप्रे सुलभमहौषधिघृतक्षीरपथ्यभोजनोपकरणे ग्रमे नगरे वा पूर्वोत्तरस्यांदिशि प्रागुदक्प्रवणे सुविभक्तविहारोद्देशे देशे दृढघनसुमृष्टभित्तिमुत्सेधविस्तारसम्पन्नां सूक्ष्मलोचनां त्रिगर्भामृतुसुखां निर्वातां प्रवातैकदेशां प्राग्द्वारामुदग्द्वारां वा शमीविल्वक्षीरिवृक्षपरिगृहीतामनिष्टेन्द्रियार्थवातातपरजोधूमस्वेदक्लेददंशमशकसरीसृपव्यालबालस्त्रीदासान्तावसायिनामगम्यां सन्निहितसद्वैद्यपरिचारकोपकरणां कुटीं कारयेत्", text: "tasya vidhiḥ kṣemasubhikṣadhārmikaśaddadhānajananṛpavaidyavipre sulabhamahauṣadhighṛtakṣīrapathyabhojanopakaraṇe grame nagare vā pūrvottarasyāṃdiśi prāgudakpravaṇe suvibhaktavihāroddeśe deśe dṛḍhaghanasumṛṣṭabhittimutsedhavistārasampannāṃ sūkṣmalocanāṃ trigarbhāmṛtusukhāṃ nirvātāṃ pravātaikadeśāṃ prāgdvārāmudagdvārāṃ vā śamīvilvakṣīrivṛkṣaparigṛhītāmaniṣṭendriyārthavātātaparajodhūmasvedakledadaṃśamaśakasarīsṛpavyālabālastrīdāsāntāvasāyināmagamyāṃ sannihitasadvaidyaparicārakopakaraṇāṃ kuṭīṃ kārayet" },
      { type: "verse", number: "12", sanskrit: "तस्यां रसायनार्थी शरदि वसन्ते वा शुक्लपक्षे प्रशस्ते अहनि पूजयित्वा यथार्हं देवगुरुविप्रान् प्रणम्य ब्रह्मदक्षाश्विप्रभृतीन् परिमृश्य सुवर्णघृतमधुसिद्धार्थकप्रियङ्गुरोचनाः प्रदक्षिणीकृत्य गोब्राह्मणाननु प्रविशेत्", text: "tasyāṃ rasāyanārthī śaradi vasante vā śuklapakṣe praśaste ahani pūjayitvā yathārhaṃ devaguruviprān praṇamya brahmadakṣāśviprabhṛtīn parimṛśya suvarṇaghṛtamadhusiddhārthakapriyaṅgurocanāḥ pradakṣiṇīkṛtya gobrāhmaṇānanu praviśet" },
      { type: "verse", number: "13", sanskrit: "तत्र संशोधनैः शुद्धः सुखी जातबलः पुनः ब्रह्मचारी धृतियुतः श्रद्दधानो जितेन्द्रियः", text: "tatra saṃśodhanaiḥ śuddhaḥ sukhī jātabalaḥ punaḥ brahmacārī dhṛtiyutaḥ śraddadhāno jitendriyaḥ" },
      { type: "verse", number: "14", sanskrit: "दानशीलदयासत्यव्रतधर्मपरायणः देवतानुस्मृतौ युक्तो युक्तस्वप्नप्रजागरः प्रियौषधः पेशलबागारभेत रसायनम्", text: "dānaśīladayāsatyavratadharmaparāyaṇaḥ devatānusmṛtau yukto yuktasvapnaprajāgaraḥ priyauṣadhaḥ peśalabāgārabheta rasāyanam" },
      { type: "verse", number: "15", sanskrit: "हरीतकीमामलकं सैन्धवं नागरं वचाम् हरिद्रां पिप्पलीं वेल्लं गुडं चोष्णाम्बुना पिबेत् स्निग्धस्विन्नो नरः पूर्वं तेन साधु विरिच्यते", text: "harītakīmāmalakaṃ saindhavaṃ nāgaraṃ vacām haridrāṃ pippalīṃ vellaṃ guḍaṃ coṣṇāmbunā pibet snigdhasvinno naraḥ pūrvaṃ tena sādhu viricyate" },
      { type: "verse", number: "16", sanskrit: "ततः शुद्धशरीराय कृतसंसर्जनाय च त्रिरात्रं पञ्चरात्रं वा सप्ताहं वा घृतान्वितम् दद्याद्यावकमाशुद्धेः पुराणशकृतो ऽथवा", text: "tataḥ śuddhaśarīrāya kṛtasaṃsarjanāya ca trirātraṃ pañcarātraṃ vā saptāhaṃ vā ghṛtānvitam dadyādyāvakamāśuddheḥ purāṇaśakṛto 'thavā" },
      { type: "verse", number: "17", sanskrit: "इत्थं संस्कृतकोष्ठस्य रसायनमुपाहरेत् यस्य यद्यौगिकं पश्येत् सर्वमालोच्य सात्म्यवित्", text: "itthaṃ saṃskṛtakoṣṭhasya rasāyanamupāharet yasya yadyaugikaṃ paśyet sarvamālocya sātmyavit" },
      { type: "verse", number: "18", sanskrit: "हरणात् सर्वरोगाणां यासावुक्ता हरीतकी पथ्यत्वात् सर्वधातूनां पथ्या शिवतया शिवा", text: "haraṇāt sarvarogāṇāṃ yāsāvuktā harītakī pathyatvāt sarvadhātūnāṃ pathyā śivatayā śivā" },
      { type: "verse", number: "19", sanskrit: "यस्माद्विजयते व्याधीन् समग्रान्विजया ततः अभयं सर्वरोगेभ्यो भवत्यायुश्च शाश्वतम् यतः शीलयतामेनां तेनेयमभया स्मृता", text: "yasmādvijayate vyādhīn samagrānvijayā tataḥ abhayaṃ sarvarogebhyo bhavatyāyuśca śāśvatam yataḥ śīlayatāmenāṃ teneyamabhayā smṛtā" },
      { type: "verse", number: "20", sanskrit: "नवा वृत्ता घना स्निग्धा गुर्वी मज्जति चाप्सु या बालस्य सा प्रयोक्तव्या नवनीतसमन्विता", text: "navā vṛttā ghanā snigdhā gurvī majjati cāpsu yā bālasya sā prayoktavyā navanītasamanvitā" },
      { type: "verse", number: "21", sanskrit: "वाते ससर्पिर्लवणा पित्ते सगुडशर्करा कफे सपिप्पलीक्षौद्रा सर्वदा सा प्रशस्यते", text: "vāte sasarpirlavaṇā pitte saguḍaśarkarā kaphe sapippalīkṣaudrā sarvadā sā praśasyate" },
      { type: "verse", number: "22", sanskrit: "अथ हरीतकीनां हिमवच्छैलसम्भवानां कालजातानामापूर्णरसवीर्याणामनामयानां द्विशस्त्रिशो वा शकलितानामनस्थ्नामाढकं चतुर्गुणेन पयसा संस्वेद्य मृदुभूतमवतार्य शीतं सर्पिर्मध्वाढकाभ्यां संसृज्य सुगुप्तं स्थापयेत् ततस्त्रिरात्रादूर्ध्वमाहारानुपरोधिनीं मात्रां प्रत्यहमुपयोजयेत् जीएणे शालिषष्टिकं पयसा भुञ्जीत प्रयोगान्ते च तावन्तमेव कालम् अस्य प्रयोगाद्वर्षशतमजरो निर्वलीखलतिपलितामयः श्रुतिस्मृतिसम्पन्नः समिद्धानलश्च पुरुषो भवति", text: "atha harītakīnāṃ himavacchailasambhavānāṃ kālajātānāmāpūrṇarasavīryāṇāmanāmayānāṃ dviśastriśo vā śakalitānāmanasthnāmāḍhakaṃ caturguṇena payasā saṃsvedya mṛdubhūtamavatārya śītaṃ sarpirmadhvāḍhakābhyāṃ saṃsṛjya suguptaṃ sthāpayet tatastrirātrādūrdhvamāhārānuparodhinīṃ mātrāṃ pratyahamupayojayet jīeṇe śāliṣaṣṭikaṃ payasā bhuñjīta prayogānte ca tāvantameva kālam asya prayogādvarṣaśatamajaro nirvalīkhalatipalitāmayaḥ śrutismṛtisampannaḥ samiddhānalaśca puruṣo bhavati" },
      { type: "verse", number: "23", sanskrit: "बृहच्छरीरं गिरिसारसारं स्वरो घनौघस्तनितानुकारी भवत्यपत्यं विपुलं स्थिरं च समश्नतो योगमिमं प्रयत्नात्", text: "bṛhaccharīraṃ girisārasāraṃ svaro ghanaughastanitānukārī bhavatyapatyaṃ vipulaṃ sthiraṃ ca samaśnato yogamimaṃ prayatnāt" },
      { type: "verse", number: "24", sanskrit: "पथ्यासहस्त्रं त्रिगुणधात्रीफलसमन्वितम् पञ्चानां पञ्चमूलानां सार्द्धं पलशतद्वयम्", text: "pathyāsahastraṃ triguṇadhātrīphalasamanvitam pañcānāṃ pañcamūlānāṃ sārddhaṃ palaśatadvayam" },
      { type: "verse", number: "25", sanskrit: "जले दशगुणे पक्त्वा दशभागस्थिते रसे आपोथ्य कृत्वा व्यस्थीनि विजयामलकान्यथा", text: "jale daśaguṇe paktvā daśabhāgasthite rase āpothya kṛtvā vyasthīni vijayāmalakānyathā" },
      { type: "verse", number: "26", sanskrit: "विनीय तस्मिन् निर्यूहे योजयेत् कुडवांशकम् त्वगेलामुस्तरजनीपिप्पल्यगरुचन्दनम्", text: "vinīya tasmin niryūhe yojayet kuḍavāṃśakam tvagelāmustarajanīpippalyagarucandanam" },
      { type: "verse", number: "27", sanskrit: "मण्डूकपर्णीकनकशङ्खपुष्पीवचाप्लवम् यष्ट्याह्वयं विडङ्गं च चूर्णितं तुलयाधिकम्", text: "maṇḍūkaparṇīkanakaśaṅkhapuṣpīvacāplavam yaṣṭyāhvayaṃ viḍaṅgaṃ ca cūrṇitaṃ tulayādhikam" },
      { type: "verse", number: "28", sanskrit: "सितोपलार्द्धभारं च प्रात्राणि त्रीणि सर्पिषः द्वे च तैलात् पचेत् सर्वं तदग्नौ लेहतां गतम्", text: "sitopalārddhabhāraṃ ca prātrāṇi trīṇi sarpiṣaḥ dve ca tailāt pacet sarvaṃ tadagnau lehatāṃ gatam" },
      { type: "verse", number: "29", sanskrit: "अवतीर्णं हिमं युञ्ज्याद्विंशैः क्षौद्रशतैस्त्रिभिः ततः खजेन मथितं निदध्यात् घृतभाजने", text: "avatīrṇaṃ himaṃ yuñjyādviṃśaiḥ kṣaudraśataistribhiḥ tataḥ khajena mathitaṃ nidadhyāt ghṛtabhājane" },
      { type: "verse", number: "30", sanskrit: "एतद्रसायनं ब्राह्मं समं पूर्वेण सर्वथा वैखानसा बालखिल्याः प्राश्य प्राप्ता नवं वयः आरोग्यममितंचायुर्वीततन्द्राश्रमक्लमाः", text: "etadrasāyanaṃ brāhmaṃ samaṃ pūrveṇa sarvathā vaikhānasā bālakhilyāḥ prāśya prāptā navaṃ vayaḥ ārogyamamitaṃcāyurvītatandrāśramaklamāḥ" },
      { type: "verse", number: "31", sanskrit: "अभयामलकविभीतकपञ्चात्मकपञ्चमूलनिर्यूहे वल्लीपलाशकरसे द्विगुणे क्षीरेष्टगुणे च विपचेत्", text: "abhayāmalakavibhītakapañcātmakapañcamūlaniryūhe vallīpalāśakarase dviguṇe kṣīreṣṭaguṇe ca vipacet" },
      { type: "verse", number: "32", sanskrit: "घृतस्यकुम्भं मधुकं मधूकं काकोलियुग्मं च बलां स्वगुप्ताम् सक्षीरशुक्लामृषभं सजीवं सुखाम्बुपस्तच्चपिबेत् गुणाढ्यम्", text: "ghṛtasyakumbhaṃ madhukaṃ madhūkaṃ kākoliyugmaṃ ca balāṃ svaguptām sakṣīraśuklāmṛṣabhaṃ sajīvaṃ sukhāmbupastaccapibet guṇāḍhyam" },
      { type: "verse", number: "33", sanskrit: "आमलकसहस्त्रं पिष्टस्वेदनविधानेन क्षीरोष्मणा सुस्विन्नमनातपशुष्कमनस्थि चूर्णयेत् तदामलकसहस्रस्वरसपरिपीतं स्थिराजीवन्तीपुनर्नवानागबलामण्डूकपर्णीब्रह्मसुवर्चलाभीरुशङ्खपुष्पीवचापिप्पलीविडङ्गस्वगुप्तामृतागरुचन्दनमधुकमधूकपुष्पपद्मोत्पलनवमालिकायुवतियूथिकाचूर्णाष्टभागसम्पृक्तं पुनर्नागबलापलसहस्रस्वरसपरिपीतं छायोपशोषितं द्विगुणितसर्पिषा क्षौद्रेण क्षुद्रगुडाकृति कृत्वा घृतभाजनस्थं भस्मराशेरधः स्थापयेदन्तर्भूमेः पक्षमथर्ववेदवित्कृतरक्षं पक्षात्यये चोद्धृत्य कनकरजतताम्रप्रवालकालायश्चूर्णाष्टभागसंयुक्तमर्द्धकर्षाभिवृद्ध्या यथाग्नि प्रातः प्रयोजयेदिति समानं पूर्वेण", text: "āmalakasahastraṃ piṣṭasvedanavidhānena kṣīroṣmaṇā susvinnamanātapaśuṣkamanasthi cūrṇayet tadāmalakasahasrasvarasaparipītaṃ sthirājīvantīpunarnavānāgabalāmaṇḍūkaparṇībrahmasuvarcalābhīruśaṅkhapuṣpīvacāpippalīviḍaṅgasvaguptāmṛtāgarucandanamadhukamadhūkapuṣpapadmotpalanavamālikāyuvatiyūthikācūrṇāṣṭabhāgasampṛktaṃ punarnāgabalāpalasahasrasvarasaparipītaṃ chāyopaśoṣitaṃ dviguṇitasarpiṣā kṣaudreṇa kṣudraguḍākṛti kṛtvā ghṛtabhājanasthaṃ bhasmarāśeradhaḥ sthāpayedantarbhūmeḥ pakṣamatharvavedavitkṛtarakṣaṃ pakṣātyaye coddhṛtya kanakarajatatāmrapravālakālāyaścūrṇāṣṭabhāgasaṃyuktamarddhakarṣābhivṛddhyā yathāgni prātaḥ prayojayediti samānaṃ pūrveṇa" },
      { type: "verse", number: "34", sanskrit: "आमलकसहस्रमार्द्रपलाशद्रोण्यां सापिधानायां बाष्पमनुद्वमन्त्यामारण्यगोमयाग्निभिरुपस्वेदयेत् तानि सुस्विन्नशीतान्युद्धृत्य निष्कुलीकृतान्यापोथ्य पिप्पली विडङ्गतण्डुलानां पृथगाढकेनाध्यर्द्धेन शर्करायाः षड्भिर्मधुघृततैलानां संयोज्य घृतकुम्भे स्थापयेद्विंशतिरात्रं परं चोपयोजयेदिति समानं पूर्वेण", text: "āmalakasahasramārdrapalāśadroṇyāṃ sāpidhānāyāṃ bāṣpamanudvamantyāmāraṇyagomayāgnibhirupasvedayet tāni susvinnaśītānyuddhṛtya niṣkulīkṛtānyāpothya pippalī viḍaṅgataṇḍulānāṃ pṛthagāḍhakenādhyarddhena śarkarāyāḥ ṣaḍbhirmadhughṛtatailānāṃ saṃyojya ghṛtakumbhe sthāpayedviṃśatirātraṃ paraṃ copayojayediti samānaṃ pūrveṇa" },
      { type: "verse", number: "35", sanskrit: "अभयामलकसहस्रं पिप्पलीसहस्रयुक्तं तरुणपलाशक्षारोदकेनाप्लाव्य शुचौ भाण्डे स्थापयेत् ततोनुगतक्षारमनातपशुष्कमास्थिरहितं चूर्णयित्वा सितोपलापादेन चतुर्गुणाभ्यां च मधुघृताभ्यां संयोज्य घृतभाजने षण्मासानन्तर्भूमेः स्थापयित्वा परतो यथाग्निबलमुपयुञ्जीतेति समानं पूर्वेण", text: "abhayāmalakasahasraṃ pippalīsahasrayuktaṃ taruṇapalāśakṣārodakenāplāvya śucau bhāṇḍe sthāpayet tatonugatakṣāramanātapaśuṣkamāsthirahitaṃ cūrṇayitvā sitopalāpādena caturguṇābhyāṃ ca madhughṛtābhyāṃ saṃyojya ghṛtabhājane ṣaṇmāsānantarbhūmeḥ sthāpayitvā parato yathāgnibalamupayuñjīteti samānaṃ pūrveṇa" },
      { type: "verse", number: "36", sanskrit: "आमलकचूर्णाढकमेकविंशतिरात्रमामलकस्वरसभावितं मधुघृताढकाभ्यां पिप्पलीचूर्णाष्टभागेन शर्कराचतुर्भागेन च संसृष्टं घृतभाजनस्थं प्रावृषि भस्मराशौ निदध्यात् तच्छरदि चोपयोजयेदिति समानं पूर्वेण", text: "āmalakacūrṇāḍhakamekaviṃśatirātramāmalakasvarasabhāvitaṃ madhughṛtāḍhakābhyāṃ pippalīcūrṇāṣṭabhāgena śarkarācaturbhāgena ca saṃsṛṣṭaṃ ghṛtabhājanasthaṃ prāvṛṣi bhasmarāśau nidadhyāt taccharadi copayojayediti samānaṃ pūrveṇa" },
      { type: "verse", number: "37", sanskrit: "विडङ्गतण्डुलानामाढकमाढकं पिप्पलीतण्डुलानामध्यर्द्धं सितोपलानां मधुघृततैलाढकैः षड्भिरेकीकृतं घृतभाजनस्थं प्रावृषि भस्मराशावितिसमानं पूर्वेण", text: "viḍaṅgataṇḍulānāmāḍhakamāḍhakaṃ pippalītaṇḍulānāmadhyarddhaṃ sitopalānāṃ madhughṛtatailāḍhakaiḥ ṣaḍbhirekīkṛtaṃ ghṛtabhājanasthaṃ prāvṛṣi bhasmarāśāvitisamānaṃ pūrveṇa" },
      { type: "verse", number: "38", sanskrit: "अभयामलकबिभीतकानां द्विशस्त्रिशो वा संयोजितानां पलाशत्वगवनद्धानां मृदावलिप्तानां कुकूलस्विन्नानां निरस्थीकृतानां पलसहस्त्रमुलूखले सङ्क्षुद्य दधिभधुघृततैलपललशर्करासम्पृक्तं भक्षयेदनन्नभुग्यथोक्तेन विधिना प्रयोगान्ते ततो द्विगुणं कालं यवागूयूषक्षीरघृतषष्टिकान्नमाहारोभ्यञ्जनं सर्पिरुद्वर्तनं यवचूर्णमिति समानं पूर्वेणाभ्यधिकफलं वा", text: "abhayāmalakabibhītakānāṃ dviśastriśo vā saṃyojitānāṃ palāśatvagavanaddhānāṃ mṛdāvaliptānāṃ kukūlasvinnānāṃ nirasthīkṛtānāṃ palasahastramulūkhale saṅkṣudya dadhibhadhughṛtatailapalalaśarkarāsampṛktaṃ bhakṣayedanannabhugyathoktena vidhinā prayogānte tato dviguṇaṃ kālaṃ yavāgūyūṣakṣīraghṛtaṣaṣṭikānnamāhārobhyañjanaṃ sarpirudvartanaṃ yavacūrṇamiti samānaṃ pūrveṇābhyadhikaphalaṃ vā" },
      { type: "verse", number: "39", sanskrit: "दशमूलबलामुस्तजीवकर्षभकोत्पलम् पर्णिन्यौ पिप्पली शृङ्गी मेदा तामलकी त्रुटिः", text: "daśamūlabalāmustajīvakarṣabhakotpalam parṇinyau pippalī śṛṅgī medā tāmalakī truṭiḥ" },
      { type: "verse", number: "40", sanskrit: "जीवन्ती जोङ्गकं द्राक्षा पौष्करं चन्दनं शठी पुनर्नवद्विकाकोली काकनासामृताद्वयम्", text: "jīvantī joṅgakaṃ drākṣā pauṣkaraṃ candanaṃ śaṭhī punarnavadvikākolī kākanāsāmṛtādvayam" },
      { type: "verse", number: "41", sanskrit: "विदारी वृषमूलं च तदैकध्यं पलेन्मितम् जलद्रोणे पचेत् पञ्च धात्रीफलशतानि च", text: "vidārī vṛṣamūlaṃ ca tadaikadhyaṃ palenmitam jaladroṇe pacet pañca dhātrīphalaśatāni ca" },
      { type: "verse", number: "42", sanskrit: "पादशेषं रसं तस्माद्व्यस्थीन्यामलकानि च गृहीत्वा भर्जयेत्तैलघृताद्वादशभिःपलैः", text: "pādaśeṣaṃ rasaṃ tasmādvyasthīnyāmalakāni ca gṛhītvā bharjayettailaghṛtādvādaśabhiḥpalaiḥ" },
      { type: "verse", number: "43", sanskrit: "मत्स्यण्डिकातुलार्धेन युक्तं तल्लेहवत् पचेत् स्नेहार्द्धं मधुनः शीते तुगाक्षीर्याश्चतुष्पलम्", text: "matsyaṇḍikātulārdhena yuktaṃ tallehavat pacet snehārddhaṃ madhunaḥ śīte tugākṣīryāścatuṣpalam" },
      { type: "verse", number: "44", sanskrit: "पिप्पल्या द्वे पले दद्याचतुर्जातं कणार्धिकम् अतोवलेहयेन्मात्रां कुटीस्थं पथ्यभोजिनम्", text: "pippalyā dve pale dadyācaturjātaṃ kaṇārdhikam atovalehayenmātrāṃ kuṭīsthaṃ pathyabhojinam" },
      { type: "verse", number: "45", sanskrit: "इत्येष च्यवनप्राशो यं प्राश्य चय्वनो मुनिः जराजर्जरितोप्यासीन्नारीनयननन्दनः", text: "ityeṣa cyavanaprāśo yaṃ prāśya cayvano muniḥ jarājarjaritopyāsīnnārīnayananandanaḥ" },
      { type: "verse", number: "46", sanskrit: "कासं श्वासं ज्वरं शोषं हृद्रोगं वातशोणितम् मूत्रशुक्राश्रयान्तोषान् वैस्वर्यं च व्यपोहति बालवृद्धक्षतक्षीणकृशानामङ्गवर्द्धनः", text: "kāsaṃ śvāsaṃ jvaraṃ śoṣaṃ hṛdrogaṃ vātaśoṇitam mūtraśukrāśrayāntoṣān vaisvaryaṃ ca vyapohati bālavṛddhakṣatakṣīṇakṛśānāmaṅgavarddhanaḥ" },
      { type: "verse", number: "47", sanskrit: "मेधां स्मृतिं कान्तिमनामयत्वमायुःप्रकर्षं पवनानुलोम्यम् स्त्रीषु प्रहर्पं बलमिन्द्रियाणामग्नेश्च कुर्याद्विधिनोपयुक्तः", text: "medhāṃ smṛtiṃ kāntimanāmayatvamāyuḥprakarṣaṃ pavanānulomyam strīṣu praharpaṃ balamindriyāṇāmagneśca kuryādvidhinopayuktaḥ" },
      { type: "verse", number: "48", sanskrit: "मधुकेन तवक्षीर्या पिपल्या सिन्धुजन्मना पृथग्लोहैः सुवर्णेन वचया मधुसर्पिषा", text: "madhukena tavakṣīryā pipalyā sindhujanmanā pṛthaglohaiḥ suvarṇena vacayā madhusarpiṣā" },
      { type: "verse", number: "49", sanskrit: "सितया वा समायुक्ता समायुक्ता रसायनम् त्रिफला सर्वरोगघ्नी मेधायुःस्मृतिबुद्धिदा", text: "sitayā vā samāyuktā samāyuktā rasāyanam triphalā sarvarogaghnī medhāyuḥsmṛtibuddhidā" },
      { type: "verse", number: "50", sanskrit: "त्रैफलेनायसीं पात्रीं कल्केनालेपयेन्नवाम् तमहोरात्रिकं लेपं पिबेत् क्षौद्रोदकाप्लुतम्", text: "traiphalenāyasīṃ pātrīṃ kalkenālepayennavām tamahorātrikaṃ lepaṃ pibet kṣaudrodakāplutam" },
      { type: "verse", number: "51", sanskrit: "प्रभूतस्नेहशमनं जीर्णे तत्र प्रशस्यते जीवत्यरुग्जरस्तस्य समाभ्यासात्समाः शतम्", text: "prabhūtasnehaśamanaṃ jīrṇe tatra praśasyate jīvatyarugjarastasya samābhyāsātsamāḥ śatam" },
      { type: "verse", number: "52", sanskrit: "वर्षं खादेत् प्राणदां प्रातरेकामश्नन्नन्नात् पूर्वमक्षद्वयं च साज्यक्षौद्रं भोजनान्ते चतुष्कं धात्रीकानां तद्वयःस्थापने ऽलम्", text: "varṣaṃ khādet prāṇadāṃ prātarekāmaśnannannāt pūrvamakṣadvayaṃ ca sājyakṣaudraṃ bhojanānte catuṣkaṃ dhātrīkānāṃ tadvayaḥsthāpane 'lam" },
      { type: "verse", number: "53", sanskrit: "अथायसानि चतुरङ्गुलदीर्घविस्तृतानि तिलोत्सेधानि पत्राणि कारयेत् तन्न्यग्निवर्णानि कृत्वामलकस्वरसे निर्वापयेदेकविंशतिकृत्वः तेषां तादृशानां पलशतमायस्यां स्थाल्यां प्रक्षिप्यामलकस्वरसोत्तरं कृत्वा सुपिहितं भस्महितं भस्मराशौ निखनेत् मासि मासि चोद्दृत्यायसेन दण्डेन घट्टयेत् शुष्यत्यामलकस्वरसं पूर्ववदावपेत् एवं तानि लोहपत्राणि संवत्सरात् द्रवीभवन्ति ततश्चोत्तरकालं कृत्वा वमनविरेचनं स्निग्धतनुरेव केवलं समन्ततोङ्गुष्ठपर्वमात्रमुखेनायसेन स्रुवेणायस एव भाजने तस्मात् कल्कीकृतात् स्रुवमेकं गृहीत्वा मधुधृताभ्यां पृथक् स्रुवेण संयोज्य प्राश्नीयात् जीर्णे क्षीररसयूषाणामन्यतमेन सर्पिर्मिश्रं नवं षष्टिकौदनमश्नीयात् अनेन विधिना वर्षमुपयुज्य वर्षमेव चान्यदप्युद्दिष्टाहारो यन्त्रितात्मा कुटीं समधिवसेत् ततः सर्वोपतापान् जित्वा व्याधिजरामरणशस्त्राग्नितोयविषाणामगम्यः सर्वभावेष्वतीन्दिर्यो वर्षसहस्रद्वयं जीवति", text: "athāyasāni caturaṅguladīrghavistṛtāni tilotsedhāni patrāṇi kārayet tannyagnivarṇāni kṛtvāmalakasvarase nirvāpayedekaviṃśatikṛtvaḥ teṣāṃ tādṛśānāṃ palaśatamāyasyāṃ sthālyāṃ prakṣipyāmalakasvarasottaraṃ kṛtvā supihitaṃ bhasmahitaṃ bhasmarāśau nikhanet māsi māsi coddṛtyāyasena daṇḍena ghaṭṭayet śuṣyatyāmalakasvarasaṃ pūrvavadāvapet evaṃ tāni lohapatrāṇi saṃvatsarāt dravībhavanti tataścottarakālaṃ kṛtvā vamanavirecanaṃ snigdhatanureva kevalaṃ samantatoṅguṣṭhaparvamātramukhenāyasena sruveṇāyasa eva bhājane tasmāt kalkīkṛtāt sruvamekaṃ gṛhītvā madhudhṛtābhyāṃ pṛthak sruveṇa saṃyojya prāśnīyāt jīrṇe kṣīrarasayūṣāṇāmanyatamena sarpirmiśraṃ navaṃ ṣaṣṭikaudanamaśnīyāt anena vidhinā varṣamupayujya varṣameva cānyadapyuddiṣṭāhāro yantritātmā kuṭīṃ samadhivaset tataḥ sarvopatāpān jitvā vyādhijarāmaraṇaśastrāgnitoyaviṣāṇāmagamyaḥ sarvabhāveṣvatīndiryo varṣasahasradvayaṃ jīvati" },
      { type: "verse", number: "54", sanskrit: "वाजिवेगो गजप्राणो भवेच्च स्मृतिबुद्धिमान् वाग्मी वृषः श्रुतधरो महाभोगो महाधनः", text: "vājivego gajaprāṇo bhavecca smṛtibuddhimān vāgmī vṛṣaḥ śrutadharo mahābhogo mahādhanaḥ" },
      { type: "verse", number: "55", sanskrit: "ताम्ररूप्यसुवर्णानामयमेव पृथग्विधिः द्विगुणं तद्गुणोत्कर्षं जानीयादुत्तरोत्तरम्", text: "tāmrarūpyasuvarṇānāmayameva pṛthagvidhiḥ dviguṇaṃ tadguṇotkarṣaṃ jānīyāduttarottaram" },
      { type: "verse", number: "56", sanskrit: "हेमधात्रीफलक्षौद्रं गायत्रीपरिमन्त्रितम् लिहन्ननुपिबन् क्षीरं दृप्टरिष्टोपि जीवति", text: "hemadhātrīphalakṣaudraṃ gāyatrīparimantritam lihannanupiban kṣīraṃ dṛpṭariṣṭopi jīvati" },
      { type: "verse", number: "57", sanskrit: "सुवर्णं पद्मबीजानि मधु लाजाः प्रियङ्गवः क्षीरेण पीतं परममलक्ष्मीविनिवारणम्", text: "suvarṇaṃ padmabījāni madhu lājāḥ priyaṅgavaḥ kṣīreṇa pītaṃ paramamalakṣmīvinivāraṇam" },
      { type: "verse", number: "58", sanskrit: "सपद्मबीजामलकाभयाक्षं सर्पिर्मधुभ्यां कनकं लिहन्तः दीर्घायुषो मन्दजरोपतापाः सरीसृपाणां च भवन्त्यगम्याः", text: "sapadmabījāmalakābhayākṣaṃ sarpirmadhubhyāṃ kanakaṃ lihantaḥ dīrghāyuṣo mandajaropatāpāḥ sarīsṛpāṇāṃ ca bhavantyagamyāḥ" },
      { type: "verse", number: "59", sanskrit: "मधुमागधिकाविडङ्गसारत्रिफला हेम घृतं सितां च खादन् जरसानवलीढदेहकान्तिः समधातुश्च समाः शतं च जीवेत्", text: "madhumāgadhikāviḍaṅgasāratriphalā hema ghṛtaṃ sitāṃ ca khādan jarasānavalīḍhadehakāntiḥ samadhātuśca samāḥ śataṃ ca jīvet" },
      { type: "verse", number: "60", sanskrit: "हेमबिल्ववचार्सीपरैकध्यमुपयोजितम् मेध्यमायुष्यमारोग्यकान्तिसौभाग्यपुष्टिदम्", text: "hemabilvavacārsīparaikadhyamupayojitam medhyamāyuṣyamārogyakāntisaubhāgyapuṣṭidam" },
      { type: "verse", number: "61", sanskrit: "शतावरीघृतं लीढं ससुवर्णं समाक्षिकम् करोति चिरजीवित्वं राजानं च वशानुगम्", text: "śatāvarīghṛtaṃ līḍhaṃ sasuvarṇaṃ samākṣikam karoti cirajīvitvaṃ rājānaṃ ca vaśānugam" },
      { type: "verse", number: "62", sanskrit: "आयुष्कामः शङ्खपुष्प्यासमेतं मेधाकामः काञ्चनं सोग्रगन्धम् लक्ष्मीकामः पद्मकिञ्जल्कयुक्तं युक्तं खादेत् कामकामो विदार्या", text: "āyuṣkāmaḥ śaṅkhapuṣpyāsametaṃ medhākāmaḥ kāñcanaṃ sogragandham lakṣmīkāmaḥ padmakiñjalkayuktaṃ yuktaṃ khādet kāmakāmo vidāryā" },
      { type: "verse", number: "63", sanskrit: "मण्डूकपर्ण्याः स्वरसं यथाग्नि क्षीरेण यष्टीमधुकस्यचूर्णम् रसं गुडूच्याः सहमूलपुष्प्याः कल्कं प्रयुञ्जीत च शङ्खपुष्प्याः", text: "maṇḍūkaparṇyāḥ svarasaṃ yathāgni kṣīreṇa yaṣṭīmadhukasyacūrṇam rasaṃ guḍūcyāḥ sahamūlapuṣpyāḥ kalkaṃ prayuñjīta ca śaṅkhapuṣpyāḥ" },
      { type: "verse", number: "64", sanskrit: "आयुःप्रदान्यामयनाशनानि बलाग्निवर्णस्वरवर्द्धनानि मेध्यानि चैतानि रसायनानि मेध्या विशेषेण तु शङ्खपुष्पी", text: "āyuḥpradānyāmayanāśanāni balāgnivarṇasvaravarddhanāni medhyāni caitāni rasāyanāni medhyā viśeṣeṇa tu śaṅkhapuṣpī" },
      { type: "verse", number: "65", sanskrit: "नलदं कटुरोहिणी पयस्या मधुकं चन्दनसारिवोग्रगन्धाः त्रिफला कटुकत्रयं हरिद्रे सपटोलं लवणं च तैः सुपिष्टैः", text: "naladaṃ kaṭurohiṇī payasyā madhukaṃ candanasārivogragandhāḥ triphalā kaṭukatrayaṃ haridre sapaṭolaṃ lavaṇaṃ ca taiḥ supiṣṭaiḥ" },
      { type: "verse", number: "66", sanskrit: "त्रिगुणेन रसेन शङ्खपुष्प्याः सपयस्कं घृतनल्वणं विपक्वम् उपयुज्य भवेज्जडोपि वाग्मी श्रुतधारी प्रतिभानवानरोगः", text: "triguṇena rasena śaṅkhapuṣpyāḥ sapayaskaṃ ghṛtanalvaṇaṃ vipakvam upayujya bhavejjaḍopi vāgmī śrutadhārī pratibhānavānarogaḥ" },
      { type: "verse", number: "67", sanskrit: "पेष्यैर्मृणालविसकेसरपत्रबीजैः सिद्धं सहेमशकलं पयसा च सर्पिः पञ्चारविन्दमिति तत्प्रथितं पृथिव्यां प्रभ्रष्टपौरुषबलप्रतिभैर्निषेव्यम्", text: "peṣyairmṛṇālavisakesarapatrabījaiḥ siddhaṃ sahemaśakalaṃ payasā ca sarpiḥ pañcāravindamiti tatprathitaṃ pṛthivyāṃ prabhraṣṭapauruṣabalapratibhairniṣevyam" },
      { type: "verse", number: "68", sanskrit: "यन्नालकन्ददलकेसरवद्विपकं नीलोत्पलस्यतदपि प्रथितं पृथिव्याम् सर्पिश्चतुष्कुवलयं सहिरण्यपत्रं मेध्यं गवामपि भवेत् किमुमानुषाणाम्", text: "yannālakandadalakesaravadvipakaṃ nīlotpalasyatadapi prathitaṃ pṛthivyām sarpiścatuṣkuvalayaṃ sahiraṇyapatraṃ medhyaṃ gavāmapi bhavet kimumānuṣāṇām" },
      { type: "verse", number: "69", sanskrit: "ब्राह्मीवचासैन्धवशङ्खपुष्पी मत्स्याक्षकब्रह्मसुवर्चलैन्द्रयः वैदेहिका च त्रियवाः पृथक्स्युर्यवौ सुवर्णस्य तिलो विषस्य", text: "brāhmīvacāsaindhavaśaṅkhapuṣpī matsyākṣakabrahmasuvarcalaindrayaḥ vaidehikā ca triyavāḥ pṛthaksyuryavau suvarṇasya tilo viṣasya" },
      { type: "verse", number: "70", sanskrit: "सर्पिषश्च पलमेकत एत द्योजयेत् परिणते च घृताढ्याम् भोजनं समधु वत्सरमेवं शीलयन्नधिकधीस्मृतिमेधाः", text: "sarpiṣaśca palamekata eta dyojayet pariṇate ca ghṛtāḍhyām bhojanaṃ samadhu vatsaramevaṃ śīlayannadhikadhīsmṛtimedhāḥ" },
      { type: "verse", number: "71", sanskrit: "अतिक्रान्तजराव्याधितन्द्रालस्यश्रमक्लमः जीवत्यब्दशतं पूर्णं श्रीतेजःकान्तिदीप्तिमान्", text: "atikrāntajarāvyādhitandrālasyaśramaklamaḥ jīvatyabdaśataṃ pūrṇaṃ śrītejaḥkāntidīptimān" },
      { type: "verse", number: "72", sanskrit: "विशेषतः कुष्ठकिलासगुल्म विषज्वरोन्मादगरोदराणि अथर्वमन्त्रादिकृताश्च कृत्याः शाम्यन्त्यनेनातिबलाश्च वाताः", text: "viśeṣataḥ kuṣṭhakilāsagulma viṣajvaronmādagarodarāṇi atharvamantrādikṛtāśca kṛtyāḥ śāmyantyanenātibalāśca vātāḥ" },
      { type: "verse", number: "73", sanskrit: "यथोक्तगुणायां भूमौ जातामबालामजीर्णां शीर्णपुराणपर्णामसञ्जातान्यपर्णां तपे तपस्ये वा मासे यथोक्तेन विधिना पुष्ययुक्ते चन्द्रमसि सुमुहुर्ते नागबलां समूलामुद्धरेत् तस्या मूलानां त्वक्पिण्डमाम्रमात्रमक्षमात्रं वा श्लक्ष्णपिष्टमवचूर्णितं वा पयसा पिबेन्मधुघृताभ्यां वा लिह्यात् जीर्णे क्षीरवृत्तिरेव स्यात् क्षीरेणैव वा ससर्षिष्कं शालिषष्टिकमश्नीयात् एवं संवत्सरप्रयोगाद्वर्षशतमजर इत्यादि समानं पूर्वेण", text: "yathoktaguṇāyāṃ bhūmau jātāmabālāmajīrṇāṃ śīrṇapurāṇaparṇāmasañjātānyaparṇāṃ tape tapasye vā māse yathoktena vidhinā puṣyayukte candramasi sumuhurte nāgabalāṃ samūlāmuddharet tasyā mūlānāṃ tvakpiṇḍamāmramātramakṣamātraṃ vā ślakṣṇapiṣṭamavacūrṇitaṃ vā payasā pibenmadhughṛtābhyāṃ vā lihyāt jīrṇe kṣīravṛttireva syāt kṣīreṇaiva vā sasarṣiṣkaṃ śāliṣaṣṭikamaśnīyāt evaṃ saṃvatsaraprayogādvarṣaśatamajara ityādi samānaṃ pūrveṇa" },
      { type: "verse", number: "74", sanskrit: "बलातिबलाचन्दनागरुधवतिनिशखदिरकदरशाकशिंशपासनसुरसापुनर्नवानन्ताश्च वयःस्थापनोक्ता दशौषधयः सविदारीश्वदंष्ट्राश्वगन्धावाराहीशतावर्यो नागबलया व्याख्याताः", text: "balātibalācandanāgarudhavatiniśakhadirakadaraśākaśiṃśapāsanasurasāpunarnavānantāśca vayaḥsthāpanoktā daśauṣadhayaḥ savidārīśvadaṃṣṭrāśvagandhāvārāhīśatāvaryo nāgabalayā vyākhyātāḥ" },
      { type: "verse", number: "75", sanskrit: "तत्र सारवृक्षाणां सर्वेषां स्वरसार्थी कुष्ठचिकित्सिते खदिरकल्पमीक्षेत आर्द्रवृक्षासम्भवे तु सारशकलानिद्व्यङ्गुलत्र्यङ्गुलानि तनूनि चतुर्गुणेम्भ्स्या प्लाव्यातपे त्रिरात्रं स्थापयेत् ततस्तान्युद्धृत्यान्यानि तत्र क्षिपेत् त्रिरात्राच्च पुनरन्यान्येवं नवरात्रेण त्रिःप्रक्षेपणोद्धारेण च स्वरसः परिकल्पितो भवति", text: "tatra sāravṛkṣāṇāṃ sarveṣāṃ svarasārthī kuṣṭhacikitsite khadirakalpamīkṣeta ārdravṛkṣāsambhave tu sāraśakalānidvyaṅgulatryaṅgulāni tanūni caturguṇembhsyā plāvyātape trirātraṃ sthāpayet tatastānyuddhṛtyānyāni tatra kṣipet trirātrācca punaranyānyevaṃ navarātreṇa triḥprakṣepaṇoddhāreṇa ca svarasaḥ parikalpito bhavati" },
      { type: "verse", number: "76", sanskrit: "फलानां पुनर्वीरुदौषधीनां च यन्त्रेणोलूखलेन वा सङ्क्षुद्य निष्पीड्य स्वरसं गृह्णीयात्", text: "phalānāṃ punarvīrudauṣadhīnāṃ ca yantreṇolūkhalena vā saṅkṣudya niṣpīḍya svarasaṃ gṛhṇīyāt" },
      { type: "verse", number: "77", sanskrit: "परिशुष्काणां तु चूर्णिकृतानामाढकमाढकमुदकस्याहोरात्रस्थितं विमृदितपूतं स्वरसवत् प्रयोज्यम् तुवरकभल्लातकादीनां पुनः पृथगेवोपदेशः", text: "pariśuṣkāṇāṃ tu cūrṇikṛtānāmāḍhakamāḍhakamudakasyāhorātrasthitaṃ vimṛditapūtaṃ svarasavat prayojyam tuvarakabhallātakādīnāṃ punaḥ pṛthagevopadeśaḥ" },
      { type: "verse", number: "78", sanskrit: "वृक्षास्तुवरका नाम पश्चिमार्णवतीरजाः वीचीतरङ्गविक्षोभमारुतोद्धूतपल्लवाः", text: "vṛkṣāstuvarakā nāma paścimārṇavatīrajāḥ vīcītaraṅgavikṣobhamārutoddhūtapallavāḥ" },
      { type: "verse", number: "79", sanskrit: "तेभ्यः फलान्याददीत सुपक्वान्यम्बुदागमे मज्ञः फलेम्यश्चादाय शोषयित्वावचूर्ण्यं च", text: "tebhyaḥ phalānyādadīta supakvānyambudāgame majñaḥ phalemyaścādāya śoṣayitvāvacūrṇyaṃ ca" },
      { type: "verse", number: "80", sanskrit: "तिलवत्पीडयेद्रोण्यां क्वाथयेद्वा कुसुम्भवत् तत्तैलं सम्भृतं भूयः पचेदासलिलक्षयात्", text: "tilavatpīḍayedroṇyāṃ kvāthayedvā kusumbhavat tattailaṃ sambhṛtaṃ bhūyaḥ pacedāsalilakṣayāt" },
      { type: "verse", number: "81", sanskrit: "अवतार्य करीषे च पक्षमात्रं निधापयेत् स्निग्धस्वैन्नो हृतमलः पक्षादुद्धृत्य यत्नवान्", text: "avatārya karīṣe ca pakṣamātraṃ nidhāpayet snigdhasvainno hṛtamalaḥ pakṣāduddhṛtya yatnavān" },
      { type: "verse", number: "82", sanskrit: "चतुर्थभक्तान्तरितः प्रातः पाणितलं पिबेत् मन्त्रेणानेन एतस्य तैलस्य दिवसे शुभे", text: "caturthabhaktāntaritaḥ prātaḥ pāṇitalaṃ pibet mantreṇānena etasya tailasya divase śubhe" },
      { type: "verse", number: "83", sanskrit: "मज्जसार महावीर्य सर्वान् धातून् विशोधय शङ्खचक्रगदापाणिस्त्वामाज्ञापयते ऽच्युतः", text: "majjasāra mahāvīrya sarvān dhātūn viśodhaya śaṅkhacakragadāpāṇistvāmājñāpayate 'cyutaḥ" },
      { type: "verse", number: "84", sanskrit: "तेनास्योर्ध्वमधस्ताच्च दोषा यान्त्यसकृत्ततः सायमस्नेहलवणां यवागूं शीतलां पिबेत्", text: "tenāsyordhvamadhastācca doṣā yāntyasakṛttataḥ sāyamasnehalavaṇāṃ yavāgūṃ śītalāṃ pibet" },
      { type: "verse", number: "85", sanskrit: "पञ्चाहानि पिबेत्तैलमित्थं वर्ज्यानि वर्जयेत् पक्षं मुद्गरसान्नाशी सर्वकुष्ठैर्विमुच्यते", text: "pañcāhāni pibettailamitthaṃ varjyāni varjayet pakṣaṃ mudgarasānnāśī sarvakuṣṭhairvimucyate" },
      { type: "verse", number: "86", sanskrit: "तदेवखदिरक्वाथे त्रिगुणे साधु साधितम् निहितं पूर्ववत् पक्षं पिबेन्मासं सुयन्त्रितः", text: "tadevakhadirakvāthe triguṇe sādhu sādhitam nihitaṃ pūrvavat pakṣaṃ pibenmāsaṃ suyantritaḥ" },
      { type: "verse", number: "87", sanskrit: "तेनाभ्यक्तशरीरश्च कुर्वन्नाहारमीरितम् भिन्नस्वरं रक्तनेत्रं शीर्णाङ्गं कृमिभक्षितम् अनेनाशु प्रयोगेण साधयेत् कुष्ठिनं नरम्", text: "tenābhyaktaśarīraśca kurvannāhāramīritam bhinnasvaraṃ raktanetraṃ śīrṇāṅgaṃ kṛmibhakṣitam anenāśu prayogeṇa sādhayet kuṣṭhinaṃ naram" },
      { type: "verse", number: "88", sanskrit: "सर्पिर्मधुयुतं पीतं तदेव खदिराद्विना पक्षं मांसरसाहारं करोति द्विशतायुषम्", text: "sarpirmadhuyutaṃ pītaṃ tadeva khadirādvinā pakṣaṃ māṃsarasāhāraṃ karoti dviśatāyuṣam" },
      { type: "verse", number: "89", sanskrit: "तदेव नस्ये पञ्चाशद्दिवसानुपयोजितम् वलीपलितनिर्मुक्तस्थिरस्मृतिकचद्विजम्", text: "tadeva nasye pañcāśaddivasānupayojitam valīpalitanirmuktasthirasmṛtikacadvijam" },
      { type: "verse", number: "90", sanskrit: "वपुष्मन्तं श्रुतधरं करोति त्रिशतायुषम् अन्त्र्धूमं तस्य मज्जा सुदग्धः क्षिप्तस्तैले सैन्धवं चाग्निवर्णम् तुल्यं हन्यादर्मनक्तान्ध्यकाचान् नीलीरोगं तैमिरं चाञ्जनेन", text: "vapuṣmantaṃ śrutadharaṃ karoti triśatāyuṣam antrdhūmaṃ tasya majjā sudagdhaḥ kṣiptastaile saindhavaṃ cāgnivarṇam tulyaṃ hanyādarmanaktāndhyakācān nīlīrogaṃ taimiraṃ cāñjanena" },
      { type: "verse", number: "91", sanskrit: "एकान्तरं तौवरकञ्च तैलं पिबेद्धिताशी नियमेन मासम् प्रभिन्नकोष्ठो गलिताङ्गदेशस्त्वचं त्यजेत् सर्पैवाशु जीर्णम्", text: "ekāntaraṃ tauvarakañca tailaṃ pibeddhitāśī niyamena māsam prabhinnakoṣṭho galitāṅgadeśastvacaṃ tyajet sarpaivāśu jīrṇam" },
      { type: "verse", number: "92", sanskrit: "साधयेत् षोडशगुणे सलिले तुवराढकम् अष्टांशशेषे विस्राव्य सङ्क्षुद्योलूखले ततः", text: "sādhayet ṣoḍaśaguṇe salile tuvarāḍhakam aṣṭāṃśaśeṣe visrāvya saṅkṣudyolūkhale tataḥ" },
      { type: "verse", number: "93", sanskrit: "शुष्कारग्वधवल्कपादरजसा व्यामिश्रित कल्कितं तस्य क्वाथजलैरुदुम्बरसमान् छायाविशुष्कान् गुडान्", text: "śuṣkāragvadhavalkapādarajasā vyāmiśrita kalkitaṃ tasya kvāthajalairudumbarasamān chāyāviśuṣkān guḍān" },
      { type: "verse", number: "94", sanskrit: "कुर्यादेकतमं च सार्द्धमथवा गोवारिणालोडितं कुष्ठी तद्दिवसास्थितो निरशनः सूर्ये गते ऽस्तं पिबेत्", text: "kuryādekatamaṃ ca sārddhamathavā govāriṇāloḍitaṃ kuṣṭhī taddivasāsthito niraśanaḥ sūrye gate 'staṃ pibet" },
      { type: "verse", number: "95", sanskrit: "तावदेव च तथैव च भूयः पाययेत्तमरुणोदयकाले अप्यजीर्णमविचिन्त्य वमिं वा भेषजं पुरुषदोषबलज्ञः", text: "tāvadeva ca tathaiva ca bhūyaḥ pāyayettamaruṇodayakāle apyajīrṇamavicintya vamiṃ vā bheṣajaṃ puruṣadoṣabalajñaḥ" },
      { type: "verse", number: "96", sanskrit: "मध्याह्ने ऽद्यात् भूरिनिष्पावतैलं कङ्गूकूरं शिग्रुकन्दोपदंशम् दध्नायुक्तं स्वल्पसिन्धूत्थचूर्णं गव्येनानु स्तोकतक्राम्बुपायी", text: "madhyāhne 'dyāt bhūriniṣpāvatailaṃ kaṅgūkūraṃ śigrukandopadaṃśam dadhnāyuktaṃ svalpasindhūtthacūrṇaṃ gavyenānu stokatakrāmbupāyī" },
      { type: "verse", number: "97", sanskrit: "तैलाक्तगात्रो दिवसान्तरं च कङ्ग्विष्टिकाचूर्णकृतप्रघर्षः स्नायात् सुखाम्भोभिरमद्यमांस स्त्रीसङ्गतिः स्यात्त्रिगुणं च योगात्", text: "tailāktagātro divasāntaraṃ ca kaṅgviṣṭikācūrṇakṛtapragharṣaḥ snāyāt sukhāmbhobhiramadyamāṃsa strīsaṅgatiḥ syāttriguṇaṃ ca yogāt" },
      { type: "verse", number: "98", sanskrit: "उपयुज्य योगमखिलं प्रतिदिनमेव द्विकालमभियुक्तः कुष्ठी कुष्ठमपोहति विशीर्णकर्णौष्ठनासमपि", text: "upayujya yogamakhilaṃ pratidinameva dvikālamabhiyuktaḥ kuṣṭhī kuṣṭhamapohati viśīrṇakarṇauṣṭhanāsamapi" },
      { type: "verse", number: "99", sanskrit: "अथ भल्लातकान्यनुपहतान्यनामयान्यापूर्णरसप्र्पमाणवीर्याणि पक्रजाम्बवप्रकाशानि शुचौ शुक्रे वा मासे सङ्गृह्य यवपल्ले माषपल्ले वा निधापयेत् तानि चतुर्मासस्थितानि सहे सहस्ये वा मासे प्रयोक्तुमारभेत शीतस्निग्धमधुरोपस्कृतशरीरः पूर्वं दशभल्लातकान्यापोथ्याष्टगुणेनाम्भसा साधु साधयेत् तेषां रसमष्टभागावशिष्टमनुष्णं सपयस्कं सर्पिर्गण्डूषाभ्यक्तोष्ठतालुजिह्वः प्रातः पिबेत् एवमेतानी दशभल्लातकान्येकैकोत्कर्षापकर्षेण त्रिंशत्प्रयोज्यानि विधिनानेन सहस्रप्रयोगस्त्रिगुणश्च कालो घृतक्षीराभ्यां शालिषष्टिकमशनमेवं विशेषाद्विगतकुष्ठदुर्नामकृमिप्रमेहमेदोदोषो वर्षशतमजर इत्यादि समानं पूर्वेण", text: "atha bhallātakānyanupahatānyanāmayānyāpūrṇarasaprpamāṇavīryāṇi pakrajāmbavaprakāśāni śucau śukre vā māse saṅgṛhya yavapalle māṣapalle vā nidhāpayet tāni caturmāsasthitāni sahe sahasye vā māse prayoktumārabheta śītasnigdhamadhuropaskṛtaśarīraḥ pūrvaṃ daśabhallātakānyāpothyāṣṭaguṇenāmbhasā sādhu sādhayet teṣāṃ rasamaṣṭabhāgāvaśiṣṭamanuṣṇaṃ sapayaskaṃ sarpirgaṇḍūṣābhyaktoṣṭhatālujihvaḥ prātaḥ pibet evametānī daśabhallātakānyekaikotkarṣāpakarṣeṇa triṃśatprayojyāni vidhinānena sahasraprayogastriguṇaśca kālo ghṛtakṣīrābhyāṃ śāliṣaṣṭikamaśanamevaṃ viśeṣādvigatakuṣṭhadurnāmakṛmipramehamedodoṣo varṣaśatamajara ityādi samānaṃ pūrveṇa" },
      { type: "verse", number: "100", sanskrit: "पूर्वमेकैकभल्लातकक्वाथं सपयस्कं पिबेदेकैकं च भल्लातकमभिवर्द्धयेद्यावत् पञ्च ततः पञ्च पञ्चवर्धयेद्यावत् सप्ततिः प्राप्य च सप्ततिमपकर्षयेत् भूयः पञ्च पञ्च यावत् पञ्च पञ्चभ्यश्चैकैकं यावदेकम् विधिनानेनसहस्रं प्रयोग इत्यादि समानं पूर्वेण", text: "pūrvamekaikabhallātakakvāthaṃ sapayaskaṃ pibedekaikaṃ ca bhallātakamabhivarddhayedyāvat pañca tataḥ pañca pañcavardhayedyāvat saptatiḥ prāpya ca saptatimapakarṣayet bhūyaḥ pañca pañca yāvat pañca pañcabhyaścaikaikaṃ yāvadekam vidhinānenasahasraṃ prayoga ityādi samānaṃ pūrveṇa" },
      { type: "verse", number: "101", sanskrit: "सप्ततिवच्च शतमुपयुञ्जीत तथा च सहस्रद्वयन् प्रयोग इत्यादि समानं पूर्वेण द्विगुणस्त्वायुषः कालः", text: "saptativacca śatamupayuñjīta tathā ca sahasradvayan prayoga ityādi samānaṃ pūrveṇa dviguṇastvāyuṣaḥ kālaḥ" },
      { type: "verse", number: "102", sanskrit: "भल्लातकानां जर्जरीकृतानां पिष्टस्वेदनं पूरयित्वा भूमावाकाण्ठनिखातस्य स्नेहभावितस्य दृढस्योपरिकुम्भस्यारोप्योडुपेनापिधायकृष्णभृदावलिप्तं गोमयाग्निनोपस्वेदयेत् तेषां यः स्वरसः कुम्भं प्रपद्यते तमष्टभागमधुसंयुक्तं द्विगुणितघृतमद्यात् त्रिगुणश्च कालो घृतक्षीराभ्यामित्यादि समानं पूर्वेण", text: "bhallātakānāṃ jarjarīkṛtānāṃ piṣṭasvedanaṃ pūrayitvā bhūmāvākāṇṭhanikhātasya snehabhāvitasya dṛḍhasyoparikumbhasyāropyoḍupenāpidhāyakṛṣṇabhṛdāvaliptaṃ gomayāgninopasvedayet teṣāṃ yaḥ svarasaḥ kumbhaṃ prapadyate tamaṣṭabhāgamadhusaṃyuktaṃ dviguṇitaghṛtamadyāt triguṇaśca kālo ghṛtakṣīrābhyāmityādi samānaṃ pūrveṇa" },
      { type: "verse", number: "103", sanskrit: "अनेनैव विधिना भल्लातकस्य रसं गृहीत्वा केवलमेव मासमेकं प्रयुञ्जीत त्रिगुणश्च काल इत्यादि समानं पूर्वेण मासि मासि वर्षशतमायुषोभिवृद्धिः एवं दशमासानुपयुज्य वर्षसहस्रमायुर्भवति", text: "anenaiva vidhinā bhallātakasya rasaṃ gṛhītvā kevalameva māsamekaṃ prayuñjīta triguṇaśca kāla ityādi samānaṃ pūrveṇa māsi māsi varṣaśatamāyuṣobhivṛddhiḥ evaṃ daśamāsānupayujya varṣasahasramāyurbhavati" },
      { type: "verse", number: "104", sanskrit: "भल्लातकतैलपात्रं सपयस्कं मधुकाक्षमात्रेण शतपाकमुपयुञ्जीत त्रिगुणश्चकाल इत्यादि समानं पूर्वेण", text: "bhallātakatailapātraṃ sapayaskaṃ madhukākṣamātreṇa śatapākamupayuñjīta triguṇaścakāla ityādi samānaṃ pūrveṇa" },
      { type: "verse", number: "105", sanskrit: "भल्लातकतैलं कृष्णतिलतैलं सर्पिरामलकरसो ऽसनादिसारकषाय इत्येषां द्रोणं द्रोणं त्रिफलात्रिकटुकविडङ्गसारचित्रकहरिद्राद्वयत्रिवृद्दन्तीन्द्रयवयष्टीमधुकविषातिविषारसाञ्जनप्रियङ्गूनां पालिकाभागास्तदैकध्यं स्नेहपाकविधिना विपाच्यावतार्य परिपूयचानुगुप्तं निदध्यात् तत उपस्कृतशरीरः प्रातः प्रातः पाणिशुक्तिमात्रं क्षौद्रेण प्रतिसंसृज्योपयुञ्जीत जीर्णे मुद्वामलकयूषेणालवणेन सर्पिष्मता खदिरोदकसिद्धं मृदुमोदनमश्नीयात् खदिरोदकेनोदककार्याणीत्येवमतो द्रोणमुपयुज्य विगतकुष्ठदुर्नामेत्यादि समानं पूर्वेण", text: "bhallātakatailaṃ kṛṣṇatilatailaṃ sarpirāmalakaraso 'sanādisārakaṣāya ityeṣāṃ droṇaṃ droṇaṃ triphalātrikaṭukaviḍaṅgasāracitrakaharidrādvayatrivṛddantīndrayavayaṣṭīmadhukaviṣātiviṣārasāñjanapriyaṅgūnāṃ pālikābhāgāstadaikadhyaṃ snehapākavidhinā vipācyāvatārya paripūyacānuguptaṃ nidadhyāt tata upaskṛtaśarīraḥ prātaḥ prātaḥ pāṇiśuktimātraṃ kṣaudreṇa pratisaṃsṛjyopayuñjīta jīrṇe mudvāmalakayūṣeṇālavaṇena sarpiṣmatā khadirodakasiddhaṃ mṛdumodanamaśnīyāt khadirodakenodakakāryāṇītyevamato droṇamupayujya vigatakuṣṭhadurnāmetyādi samānaṃ pūrveṇa" },
      { type: "verse", number: "106", sanskrit: "पुष्टानि पाकेनपरिच्युतानि भल्लातकान्याढकसम्मितानि घृष्ट्वेष्टिकाचूर्णकणैर्जलेन प्रक्षाल्य संशोष्य च मारुतेन", text: "puṣṭāni pākenaparicyutāni bhallātakānyāḍhakasammitāni ghṛṣṭveṣṭikācūrṇakaṇairjalena prakṣālya saṃśoṣya ca mārutena" },
      { type: "verse", number: "107", sanskrit: "जर्जराणि विपचेज्जलकुम्भे पादशेषधृतगालितशीतम् तद्रसं पुनरपि श्रपयेत क्षीरकुम्भसहितं चरणस्थे", text: "jarjarāṇi vipacejjalakumbhe pādaśeṣadhṛtagālitaśītam tadrasaṃ punarapi śrapayeta kṣīrakumbhasahitaṃ caraṇasthe" },
      { type: "verse", number: "108", sanskrit: "सर्पिः पक्वं तेन तुल्यप्रमाणं युञ्ज्यात् स्वेच्छं शर्कराया रजोभिः एकीभूतं तत्खजक्षोभणेन स्थाप्यं धान्ये सप्तरात्रं सुगुप्तम्", text: "sarpiḥ pakvaṃ tena tulyapramāṇaṃ yuñjyāt svecchaṃ śarkarāyā rajobhiḥ ekībhūtaṃ tatkhajakṣobhaṇena sthāpyaṃ dhānye saptarātraṃ suguptam" },
      { type: "verse", number: "109", sanskrit: "तममृतरसपाकं यः प्रगे प्राशमश्नन्ननु पिबति यथेष्टं वारि दुग्धं रसं वा स्मृतिमतिबलमेधासत्वसारैरुपेतः कनकनिकषगौरः सोश्नुते दीर्घमायुः", text: "tamamṛtarasapākaṃ yaḥ prage prāśamaśnannanu pibati yatheṣṭaṃ vāri dugdhaṃ rasaṃ vā smṛtimatibalamedhāsatvasārairupetaḥ kanakanikaṣagauraḥ sośnute dīrghamāyuḥ" },
      { type: "verse", number: "110", sanskrit: "द्रोणे ऽम्भसो व्रणकृतां त्रिशताद्विपक्वात् क्वाथाढके पलसमैस्तिलतैलपात्रम् तिक्ताविषाद्वयवरा गिरिजन्मतार्क्ष्यैः सिद्धं परं निखिलकुष्ठनिषूदनाय", text: "droṇe 'mbhaso vraṇakṛtāṃ triśatādvipakvāt kvāthāḍhake palasamaistilatailapātram tiktāviṣādvayavarā girijanmatārkṣyaiḥ siddhaṃ paraṃ nikhilakuṣṭhaniṣūdanāya" },
      { type: "verse", number: "111", sanskrit: "सहामलकशुक्तिभिर्दधिसरेण तैलेन वा गुडेन पयसा घृतेन यवसक्तुभिर्वा सह तिलेन सह माक्षिकेण पललेन सूपेन वा वपुष्करमरुष्करं परममेध्यमायुष्करम्", text: "sahāmalakaśuktibhirdadhisareṇa tailena vā guḍena payasā ghṛtena yavasaktubhirvā saha tilena saha mākṣikeṇa palalena sūpena vā vapuṣkaramaruṣkaraṃ paramamedhyamāyuṣkaram" },
      { type: "verse", number: "112", sanskrit: "भल्लातकानि तीक्ष्ष्णानि पाकीन्यग्निसमानि च भवन्य्तमृतकल्पानि प्रयुक्तानि यथाविधि", text: "bhallātakāni tīkṣṣṇāni pākīnyagnisamāni ca bhavanytamṛtakalpāni prayuktāni yathāvidhi" },
      { type: "verse", number: "113", sanskrit: "कफजो न स रोगास्ति न विबन्धोस्तिकश्चन यं न भल्लातकं हन्याच्छीघ्रमग्निबलप्रदम्", text: "kaphajo na sa rogāsti na vibandhostikaścana yaṃ na bhallātakaṃ hanyācchīghramagnibalapradam" },
      { type: "verse", number: "114", sanskrit: "वातातपविधानेपि विशेषेण विवर्जयेत् कुलत्थदधिशुक्तानि तैलाभ्यङ्गाग्निसेवनम्", text: "vātātapavidhānepi viśeṣeṇa vivarjayet kulatthadadhiśuktāni tailābhyaṅgāgnisevanam" },
      { type: "verse", number: "115", sanskrit: "पञ्चाष्टौ सप्त दश वा पिप्पलीर्मधुसर्पिषा रसायनगुणान्वेषी समामेकां प्रयोजयेत्", text: "pañcāṣṭau sapta daśa vā pippalīrmadhusarpiṣā rasāyanaguṇānveṣī samāmekāṃ prayojayet" },
      { type: "verse", number: "116", sanskrit: "तिस्रस्तिस्रस्तु पूर्वाह्ने भुक्त्वाग्रे भोजनस्य च पिप्पल्यः किंशुकक्षारभाविता घृतभर्जिताः प्रयोज्या मधुसम्मिश्रा रसायनगुणौषिणा", text: "tisrastisrastu pūrvāhne bhuktvāgre bhojanasya ca pippalyaḥ kiṃśukakṣārabhāvitā ghṛtabharjitāḥ prayojyā madhusammiśrā rasāyanaguṇauṣiṇā" },
      { type: "verse", number: "117", sanskrit: "क्रमवृध्या दशाहानि दशपैप्पलिकं दिनम् वर्धयेत् पयसा सार्द्धं तथैवापनयेत् पुनः", text: "kramavṛdhyā daśāhāni daśapaippalikaṃ dinam vardhayet payasā sārddhaṃ tathaivāpanayet punaḥ" },
      { type: "verse", number: "118", sanskrit: "जीर्णौषधश्च भुञ्जीत षष्टिकं क्षीरसर्पिषा पिप्पलीनां सहस्रस्य प्रयोगोयं रसायनम्", text: "jīrṇauṣadhaśca bhuñjīta ṣaṣṭikaṃ kṣīrasarpiṣā pippalīnāṃ sahasrasya prayogoyaṃ rasāyanam" },
      { type: "verse", number: "119", sanskrit: "पिष्टास्ता बलिभिः पेयाः शृता मध्यबलैर्नरैः शीतीकृता द्रस्वबलैर्योज्या दोषामयान् प्रति", text: "piṣṭāstā balibhiḥ peyāḥ śṛtā madhyabalairnaraiḥ śītīkṛtā drasvabalairyojyā doṣāmayān prati" },
      { type: "verse", number: "120", sanskrit: "तद्वच छागदुग्धेन द्वे सहस्रे प्रयोजयेत्", text: "tadvaca chāgadugdhena dve sahasre prayojayet" },
      { type: "verse", number: "121", sanskrit: "एभिः प्रयोगैः पिप्पल्यः कासश्वासगलग्रहान् यक्ष्ममेहग्रहण्यर्शः पाण्डुत्वविषमज्वरान् घ्नन्ति शोफं वमिं हिध्मां प्लीहानं वातशोणितम्", text: "ebhiḥ prayogaiḥ pippalyaḥ kāsaśvāsagalagrahān yakṣmamehagrahaṇyarśaḥ pāṇḍutvaviṣamajvarān ghnanti śophaṃ vamiṃ hidhmāṃ plīhānaṃ vātaśoṇitam" },
      { type: "verse", number: "122", sanskrit: "विडङ्गचूर्णं यष्टीमधुकचूर्णयुक्तं शीततोयेन समाशमुपयुञ्जीत जीर्णे मुद्गयूषेणालवणेन सघृतमोदनमश्नीयात् तेन विशेषाद्विगतकृमिदुर्नामकुष्ठप्रमेहमेदोदोषो वर्षशतमजर इत्यादि समानं पूर्वेण विडङ्गचूर्णं क्षौद्रभल्लातकक्वाथाभ्यां मध्वामलकरसाभ्यां गुडूचीक्वाथेन च एतांश्चतुरो योगान् मासमुपयुञ्जीतेति समानं पूर्वेण सर्वेषु च मासिमासि वर्षशतमायुषो ऽभिवृद्धिः", text: "viḍaṅgacūrṇaṃ yaṣṭīmadhukacūrṇayuktaṃ śītatoyena samāśamupayuñjīta jīrṇe mudgayūṣeṇālavaṇena saghṛtamodanamaśnīyāt tena viśeṣādvigatakṛmidurnāmakuṣṭhapramehamedodoṣo varṣaśatamajara ityādi samānaṃ pūrveṇa viḍaṅgacūrṇaṃ kṣaudrabhallātakakvāthābhyāṃ madhvāmalakarasābhyāṃ guḍūcīkvāthena ca etāṃścaturo yogān māsamupayuñjīteti samānaṃ pūrveṇa sarveṣu ca māsimāsi varṣaśatamāyuṣo 'bhivṛddhiḥ" },
      { type: "verse", number: "123", sanskrit: "अलम्बुषां स्वेन रसेन भावितां पृथग्घृतक्षीरमधूष्णवारिभिः पिबेत्तथा काञ्जिकतक्रमस्तुभिर्भगन्दरोरुग्रहगुल्मकासवान्", text: "alambuṣāṃ svena rasena bhāvitāṃ pṛthagghṛtakṣīramadhūṣṇavāribhiḥ pibettathā kāñjikatakramastubhirbhagandarorugrahagulmakāsavān" },
      { type: "verse", number: "124", sanskrit: "उष्णा विपाके कटुका कषायमधुरा रसे अत्यन्तदीपनी मेध्या वातश्लेष्महरा च सा", text: "uṣṇā vipāke kaṭukā kaṣāyamadhurā rase atyantadīpanī medhyā vātaśleṣmaharā ca sā" },
      { type: "verse", number: "125", sanskrit: "वर्षोपयोगात् कुरुते नरं वर्षशतायुषम् दृढेन्द्रियानलबलं निर्वलीपलितामयम्", text: "varṣopayogāt kurute naraṃ varṣaśatāyuṣam dṛḍhendriyānalabalaṃ nirvalīpalitāmayam" },
      { type: "verse", number: "126", sanskrit: "श्वेतावल्गुजफलान्यातपशुष्काणी चूर्णयित्वा तत्तुल्यगुडेन सङ्क्षुद्य घृतकुम्भे धान्यराशौ सप्त्परात्रं निदध्यात् ततो ऽनुदिते भास्वति यथाबलं मात्रां सुखोदकानुपानामुपयोजयेत् जीर्णे सुखाम्बुपरिषितः शालिषष्टिकौदनं सशर्करेण पयसाश्नीयात् तस्य मासप्रयोगाद्विशेषेण विगतकुष्ठो ग्रहणधारणवान् वर्षशतमजर इत्यादि समानं पूर्वेण प्रयोगतश्चोर्ध्वं द्विगुणं परिहारः", text: "śvetāvalgujaphalānyātapaśuṣkāṇī cūrṇayitvā tattulyaguḍena saṅkṣudya ghṛtakumbhe dhānyarāśau saptparātraṃ nidadhyāt tato 'nudite bhāsvati yathābalaṃ mātrāṃ sukhodakānupānāmupayojayet jīrṇe sukhāmbupariṣitaḥ śāliṣaṣṭikaudanaṃ saśarkareṇa payasāśnīyāt tasya māsaprayogādviśeṣeṇa vigatakuṣṭho grahaṇadhāraṇavān varṣaśatamajara ityādi samānaṃ pūrveṇa prayogataścordhvaṃ dviguṇaṃ parihāraḥ" },
      { type: "verse", number: "127", sanskrit: "वाकुचिकाकर्षचूर्णं सुखाम्बुना पिबेत् पीत्वा चातपे निर्वातोष्णे वा गर्भगृहे तिष्ठेदपराह्णे तद्वदेव स्रानमशनं च यूषरसाभ्यां वा तस्य त्रिसप्तरात्रप्रयोगाद्विगतकुष्ठ इत्यादि समानं पूर्वेण", text: "vākucikākarṣacūrṇaṃ sukhāmbunā pibet pītvā cātape nirvātoṣṇe vā garbhagṛhe tiṣṭhedaparāhṇe tadvadeva srānamaśanaṃ ca yūṣarasābhyāṃ vā tasya trisaptarātraprayogādvigatakuṣṭha ityādi samānaṃ pūrveṇa" },
      { type: "verse", number: "128", sanskrit: "त्वग्रोमकेशदशनान् नखांश्चमुक्त्वा पुनर्नवान् लभते स्वरवर्णबलोत्साहं नवं वयो नष्टपलितं च", text: "tvagromakeśadaśanān nakhāṃścamuktvā punarnavān labhate svaravarṇabalotsāhaṃ navaṃ vayo naṣṭapalitaṃ ca" },
      { type: "verse", number: "129", sanskrit: "पलानि दश बाकुच्या दशैव च फलत्रयात् सप्त क्रिमिघ्नादयसस्त्रीणि द्वे गिरिसम्भवात्", text: "palāni daśa bākucyā daśaiva ca phalatrayāt sapta krimighnādayasastrīṇi dve girisambhavāt" },
      { type: "verse", number: "130", sanskrit: "पुरपुष्करमूलाभ्यामाहरेत पलं पलम् सूक्ष्मैलार्धपलं व्योषघनकेसरकुङ्कुमम्", text: "purapuṣkaramūlābhyāmāhareta palaṃ palam sūkṣmailārdhapalaṃ vyoṣaghanakesarakuṅkumam" },
      { type: "verse", number: "131", sanskrit: "लोध्रत्वक्पत्रयष्ट्याह्वचित्रकं कार्षिकं पृथक् शतंभल्लातकानां च सर्वं खण्डसमांसकम्", text: "lodhratvakpatrayaṣṭyāhvacitrakaṃ kārṣikaṃ pṛthak śataṃbhallātakānāṃ ca sarvaṃ khaṇḍasamāṃsakam" },
      { type: "verse", number: "132", sanskrit: "चूर्णयेदथ तन्मात्रां भक्षयेत् पालिकीं पराम् यथेष्टचेष्टो लभते वर्षाद्रासायनान् गुणान्", text: "cūrṇayedatha tanmātrāṃ bhakṣayet pālikīṃ parām yatheṣṭaceṣṭo labhate varṣādrāsāyanān guṇān" },
      { type: "verse", number: "133", sanskrit: "सर्वरोगान् विजयते त्वग्विकारान् विशेषतः अर्शोभगन्दरश्वासकासपाण्ड्वामयक्रिमीन्", text: "sarvarogān vijayate tvagvikārān viśeṣataḥ arśobhagandaraśvāsakāsapāṇḍvāmayakrimīn" },
      { type: "verse", number: "134", sanskrit: "गुल्मप्लीहाश्मरीवर्धमप्रमेहारुचिपीनसान् मन्दानलत्वं कृशतां शोफग्रन्थ्यर्बुदानपि", text: "gulmaplīhāśmarīvardhamapramehārucipīnasān mandānalatvaṃ kṛśatāṃ śophagranthyarbudānapi" },
      { type: "verse", number: "135", sanskrit: "वाकुचिकाफलानि गोमूत्रे सप्तरात्रं वासयेत् ततो निस्तुषीकृत्य छायायां विशोषयित्वा सुसूक्ष्मं च सञ्चूर्ण्य त्र्यहं त्र्यहं क्रमशो भावयेत्त्रिफलाक्वथेन कारवल्लीवासाब्राह्मीगुडूचीभृङ्गराजस्वरसैः पृथक्पृथक् खदिरासनराजवृक्षपिचुमन्दक्वाथैः", text: "vākucikāphalāni gomūtre saptarātraṃ vāsayet tato nistuṣīkṛtya chāyāyāṃ viśoṣayitvā susūkṣmaṃ ca sañcūrṇya tryahaṃ tryahaṃ kramaśo bhāvayettriphalākvathena kāravallīvāsābrāhmīguḍūcībhṛṅgarājasvarasaiḥ pṛthakpṛthak khadirāsanarājavṛkṣapicumandakvāthaiḥ" },
      { type: "verse", number: "136", sanskrit: "तस्य पीतः प्रतिदिनं धात्रीफलरसाप्लुतः कर्षः सर्वामयान् हन्ति त्वग्विकारान्विशेषतः", text: "tasya pītaḥ pratidinaṃ dhātrīphalarasāplutaḥ karṣaḥ sarvāmayān hanti tvagvikārānviśeṣataḥ" },
      { type: "verse", number: "137", sanskrit: "असनखदिरयूषैर्भावितां सोमराजीं मधुघृतशिखिपथ्यालोहचूर्णैरुपेताम् शरदमवलिहानः पारिणामान् विकारां स्त्यजति मितहिताशी तद्वदाहारजातान्", text: "asanakhadirayūṣairbhāvitāṃ somarājīṃ madhughṛtaśikhipathyālohacūrṇairupetām śaradamavalihānaḥ pāriṇāmān vikārāṃ styajati mitahitāśī tadvadāhārajātān" },
      { type: "verse", number: "138", sanskrit: "तीव्रेण कुष्ठेन परीतमूर्त्तिर्यःसोमराजीं नियमेन खादेत् संवत्सरं कृष्णतिलद्वितीयां ससोमराजीं वपुषातिशेते", text: "tīvreṇa kuṣṭhena parītamūrttiryaḥsomarājīṃ niyamena khādet saṃvatsaraṃ kṛṣṇatiladvitīyāṃ sasomarājīṃ vapuṣātiśete" },
      { type: "verse", number: "139", sanskrit: "ये सोमराज्या वितुषीकृतायाश्चूर्णैरुपेतात् पयसः सुजातात् उद्धृत्य सारं मधुना लिहन्ति तक्रं तदेवानु पिबन्ति चान्ते", text: "ye somarājyā vituṣīkṛtāyāścūrṇairupetāt payasaḥ sujātāt uddhṛtya sāraṃ madhunā lihanti takraṃ tadevānu pibanti cānte" },
      { type: "verse", number: "140", sanskrit: "ते कुष्ठिनः पक्ष्मदरिद्रनेत्रा विशीर्णकर्णाङ्गुलिनासिका वा विहायवैरूप्यमपास्य रूपं पुनः प्ररूढा इव भान्ति वृक्षाः", text: "te kuṣṭhinaḥ pakṣmadaridranetrā viśīrṇakarṇāṅgulināsikā vā vihāyavairūpyamapāsya rūpaṃ punaḥ prarūḍhā iva bhānti vṛkṣāḥ" },
      { type: "verse", number: "141", sanskrit: "खदिराम्भसा पिबेद्वा रविसेवी तां तया यवागूं वा गायत्रीजलसिद्धां कुष्ठी तत्तोयकार्यकरः", text: "khadirāmbhasā pibedvā ravisevī tāṃ tayā yavāgūṃ vā gāyatrījalasiddhāṃ kuṣṭhī tattoyakāryakaraḥ" },
      { type: "verse", number: "142", sanskrit: "गजलिण्डक्षारयुता तत्क्षारपायिनो विलेपिभुजः श्वित्राणि सोमराजी प्रसह्य हन्यात् प्रलेपाच्च", text: "gajaliṇḍakṣārayutā tatkṣārapāyino vilepibhujaḥ śvitrāṇi somarājī prasahya hanyāt pralepācca" },
      { type: "verse", number: "143", sanskrit: "गोमूत्रे सप्तरात्रं शशिशकलफलं वासितं लोलयित्वा कुर्याच्छायाविशुष्कं पृथगिति च फलं प्रापुनाटं च शुष्कम्", text: "gomūtre saptarātraṃ śaśiśakalaphalaṃ vāsitaṃ lolayitvā kuryācchāyāviśuṣkaṃ pṛthagiti ca phalaṃ prāpunāṭaṃ ca śuṣkam" },
      { type: "verse", number: "144", sanskrit: "अंशस्ताभ्यां तथांशः कृमिरिपुदहन स्फोटकृद्भ्यः स चूर्णो गोमूत्रेणोपयुक्तः प्रमितहितभुजः श्चित्रमाश्वेव हन्ति", text: "aṃśastābhyāṃ tathāṃśaḥ kṛmiripudahana sphoṭakṛdbhyaḥ sa cūrṇo gomūtreṇopayuktaḥ pramitahitabhujaḥ ścitramāśveva hanti" },
      { type: "verse", number: "145", sanskrit: "इक्षुरगोक्षुरसिंही व्याघ्री पञ्चांगुलाम्बुना पीता उपलमघनं घनं वा रसाशिनां हन्ति बाकुचिका", text: "ikṣuragokṣurasiṃhī vyāghrī pañcāṃgulāmbunā pītā upalamaghanaṃ ghanaṃ vā rasāśināṃ hanti bākucikā" },
      { type: "verse", number: "146", sanskrit: "उष्णोदकेन पिष्टा पीता च घृतान्विता जयेत् गुल्मम् लघुपञ्चमूलसिद्धां पेयामुपयोजयेज्जीर्णे", text: "uṣṇodakena piṣṭā pītā ca ghṛtānvitā jayet gulmam laghupañcamūlasiddhāṃ peyāmupayojayejjīrṇe" },
      { type: "verse", number: "147", sanskrit: "कट्वङ्गकुटजयूषैरर्शींसि भगन्दरं च नाशयति मेहान् मद्यैर्निगदैर्निषोविता बाकुची प्रबलान्", text: "kaṭvaṅgakuṭajayūṣairarśīṃsi bhagandaraṃ ca nāśayati mehān madyairnigadairniṣovitā bākucī prabalān" },
      { type: "verse", number: "148", sanskrit: "विष्किररसेन पीता दशमूलरसेन वा गुडूच्या वा अपतन्त्रकं निहन्यादायामं वा रसान्नभुजः", text: "viṣkirarasena pītā daśamūlarasena vā guḍūcyā vā apatantrakaṃ nihanyādāyāmaṃ vā rasānnabhujaḥ" },
      { type: "verse", number: "149", sanskrit: "जठरेषु पिबेन्मूत्रैर्जलोदरे त्रैवृतेन यूषेण शोफे पाण्डुव्याधाववल्गुजं शीघ्वरिष्टाभ्याम्", text: "jaṭhareṣu pibenmūtrairjalodare traivṛtena yūṣeṇa śophe pāṇḍuvyādhāvavalgujaṃ śīghvariṣṭābhyām" },
      { type: "verse", number: "150", sanskrit: "इक्षुरकादिक्वाथैर्वर्ध्मनि मूत्रेण वा गवां शस्तः धारोष्णेन तु पयसा युक्तः शोफज्वरौ हन्ति", text: "ikṣurakādikvāthairvardhmani mūtreṇa vā gavāṃ śastaḥ dhāroṣṇena tu payasā yuktaḥ śophajvarau hanti" },
      { type: "verse", number: "151", sanskrit: "उष्णाम्बुना प्रयोज्यो लूताकीटाखुसर्पदष्टेषु कृमिहरचतुरङ्गुलयोः क्वाथः कोष्णः कृमिणकोष्हेषु", text: "uṣṇāmbunā prayojyo lūtākīṭākhusarpadaṣṭeṣu kṛmiharacaturaṅgulayoḥ kvāthaḥ koṣṇaḥ kṛmiṇakoṣheṣu" },
      { type: "verse", number: "152", sanskrit: "लेखामिन्दोः सघृतां सुखाम्बुना पुत्रिणी भवति पीत्वा पुष्षोदयेश्वगन्धाशृतेन पयसा च भुञ्जाना", text: "lekhāmindoḥ saghṛtāṃ sukhāmbunā putriṇī bhavati pītvā puṣṣodayeśvagandhāśṛtena payasā ca bhuñjānā" },
      { type: "verse", number: "153", sanskrit: "वन्ध्यापि सप्ताहमिमंप्रयोगं करोति या हर्षयती सुगन्धिः प्रियंवदा सद्व्रतशौचयुक्ता सूते सुतान् सा नियमात् गुणाढ्यान्", text: "vandhyāpi saptāhamimaṃprayogaṃ karoti yā harṣayatī sugandhiḥ priyaṃvadā sadvrataśaucayuktā sūte sutān sā niyamāt guṇāḍhyān" },
      { type: "verse", number: "154", sanskrit: "स्निग्धैरुष्णैर्मधुरैर्हरति गदान्वातजान् युता पैत्तान् तिक्तकमधुरकषायैः कफजांस्त्रिफलारसमधुभ्यां च", text: "snigdhairuṣṇairmadhurairharati gadānvātajān yutā paittān tiktakamadhurakaṣāyaiḥ kaphajāṃstriphalārasamadhubhyāṃ ca" },
      { type: "verse", number: "155", sanskrit: "इति शमनी धन्येयं विषगरभूतोपसर्गपाप्मघ्नी गेहे स्थितापि रेखा चान्द्रमसी किमुत कोष्ठस्था", text: "iti śamanī dhanyeyaṃ viṣagarabhūtopasargapāpmaghnī gehe sthitāpi rekhā cāndramasī kimuta koṣṭhasthā" },
      { type: "verse", number: "156", sanskrit: "मनुष्यमप्यागतमृत्युशासनं प्रणष्टबुद्धीन्द्रियमल्पचेतसम् अवल्गुजो मोक्षयते महाभयाच्छ्रियं च मेधां च ददाति पुप्कलाम्", text: "manuṣyamapyāgatamṛtyuśāsanaṃ praṇaṣṭabuddhīndriyamalpacetasam avalgujo mokṣayate mahābhayācchriyaṃ ca medhāṃ ca dadāti pupkalām" },
      { type: "verse", number: "157", sanskrit: "हैमवत्या वचायाः पिण्डमामलकमात्रं पयसालोड्य पिबेज्जीर्णे पयस्सर्पिरोदन इत्याहारः एवं सप्तरात्रेण मेधावी भवति सप्तभिः सप्तरात्रैः श्रुतधरो वर्षशतमजर इत्यादि समानं पूर्वेण", text: "haimavatyā vacāyāḥ piṇḍamāmalakamātraṃ payasāloḍya pibejjīrṇe payassarpirodana ityāhāraḥ evaṃ saptarātreṇa medhāvī bhavati saptabhiḥ saptarātraiḥ śrutadharo varṣaśatamajara ityādi samānaṃ pūrveṇa" },
      { type: "verse", number: "158", sanskrit: "इतरस्या अपि वचाया द्विपलक्वाथं पिबेत् जीर्णे पयः सर्पिरित्यादि समानं पूर्वेण तच्चूर्णं वा क्षौद्रसर्पिभ्यां यथाबलमवलिह्यात् जीर्णे पयः सर्पिरित्यादि समानं पूर्वेण", text: "itarasyā api vacāyā dvipalakvāthaṃ pibet jīrṇe payaḥ sarpirityādi samānaṃ pūrveṇa taccūrṇaṃ vā kṣaudrasarpibhyāṃ yathābalamavalihyāt jīrṇe payaḥ sarpirityādi samānaṃ pūrveṇa" },
      { type: "verse", number: "159", sanskrit: "वचाकल्कशतपाकं घृतद्रोणमुपयुज्य विशेषात् ग्रहोन्मादापस्मारगलगण्डगण्डमालाश्लीपदस्वरभेदविमुक्तः सर्वार्थेषु सिद्धिमान् वर्षशतायुर्भवति", text: "vacākalkaśatapākaṃ ghṛtadroṇamupayujya viśeṣāt grahonmādāpasmāragalagaṇḍagaṇḍamālāślīpadasvarabhedavimuktaḥ sarvārtheṣu siddhimān varṣaśatāyurbhavati" },
      { type: "verse", number: "160", sanskrit: "शीतवातहिमदग्धतनूनां स्तब्धभग्रकुटिलव्यधितास्थ्नाम् भेषजस्य पवनोपहतानां वक्ष्यते विधिरतो लशुनस्य", text: "śītavātahimadagdhatanūnāṃ stabdhabhagrakuṭilavyadhitāsthnām bheṣajasya pavanopahatānāṃ vakṣyate vidhirato laśunasya" },
      { type: "verse", number: "161", sanskrit: "राहोरमृतचौर्येण लूनाद्ये पतिता गलात् अमृतस्य कणा भूमौ ते रसोनत्वमागताः", text: "rāhoramṛtacauryeṇa lūnādye patitā galāt amṛtasya kaṇā bhūmau te rasonatvamāgatāḥ" },
      { type: "verse", number: "162", sanskrit: "द्विजानाश्नन्ति तमतो दैत्यदेहसुमुद्भवम् साक्षादमृतसम्भूतेर्ग्रामणीः स रसायनम्", text: "dvijānāśnanti tamato daityadehasumudbhavam sākṣādamṛtasambhūtergrāmaṇīḥ sa rasāyanam" },
      { type: "verse", number: "163", sanskrit: "शीलयेल्लशुनं शीते वसन्ते च कफोल्बणः घनोदयेपि वातार्त्तः सदा वा ग्रीष्मलीलया रक्तपित्तभवारोगा जायन्ते रक्तपित्तिनः", text: "śīlayellaśunaṃ śīte vasante ca kapholbaṇaḥ ghanodayepi vātārttaḥ sadā vā grīṣmalīlayā raktapittabhavārogā jāyante raktapittinaḥ" },
      { type: "verse", number: "164", sanskrit: "मासः परोस्य रसकल्कनिषेवणाय स्वच्छन्दमप्युपदिशन्ति विमर्दकैस्तु षण्मासमन्यविधिना न तु शस्तमाहुः पक्षप्रयोगमपि हीनतरं रसोने", text: "māsaḥ parosya rasakalkaniṣevaṇāya svacchandamapyupadiśanti vimardakaistu ṣaṇmāsamanyavidhinā na tu śastamāhuḥ pakṣaprayogamapi hīnataraṃ rasone" },
      { type: "verse", number: "165", sanskrit: "स्रिग्धशुद्धतनु शीतमधुरोपस्कृताशयः तदुत्तंसावतंसाभ्यां चर्चितानुचराजिरः", text: "srigdhaśuddhatanu śītamadhuropaskṛtāśayaḥ taduttaṃsāvataṃsābhyāṃ carcitānucarājiraḥ" },
      { type: "verse", number: "166", sanskrit: "तस्य कन्दान् वसन्तान्ते हिमवच्छकदेशजान् अपनीतत्वचो रात्रौ निमयेन्मदिरादिभिः", text: "tasya kandān vasantānte himavacchakadeśajān apanītatvaco rātrau nimayenmadirādibhiḥ" },
      { type: "verse", number: "167", sanskrit: "तत्कल्कस्वरसं प्रातः शुचितान्तवपीडितम् मदिरायाः सुरूढायास्त्रिभागेन समन्वितम्", text: "tatkalkasvarasaṃ prātaḥ śucitāntavapīḍitam madirāyāḥ surūḍhāyāstribhāgena samanvitam" },
      { type: "verse", number: "168", sanskrit: "मद्यस्यान्यस्य तक्रस्य मस्तुनः कञ्जिकस्य वा तत्काल एव वा युक्तं युक्तमालोच्य मात्रया", text: "madyasyānyasya takrasya mastunaḥ kañjikasya vā tatkāla eva vā yuktaṃ yuktamālocya mātrayā" },
      { type: "verse", number: "169", sanskrit: "तैलसर्पिर्वसामज्जक्षीरमासरसैः पृथक् क्वाथेन वा यथाव्याधि रसं केवलमेव वा", text: "tailasarpirvasāmajjakṣīramāsarasaiḥ pṛthak kvāthena vā yathāvyādhi rasaṃ kevalameva vā" },
      { type: "verse", number: "170", sanskrit: "पिबेत् गण्डूषमात्र प्राक्कण्ठनाडीविशुद्धये प्रततं स्वेदनंचानु वेदनायां प्रशस्यते", text: "pibet gaṇḍūṣamātra prākkaṇṭhanāḍīviśuddhaye pratataṃ svedanaṃcānu vedanāyāṃ praśasyate" },
      { type: "verse", number: "171", sanskrit: "शीताम्बुसेकः सहसा वमिमूर्च्छाययोर्मुखे शेषं पिबेत् क्लमापाये स्थिरतां गत ओजसि", text: "śītāmbusekaḥ sahasā vamimūrcchāyayormukhe śeṣaṃ pibet klamāpāye sthiratāṃ gata ojasi" },
      { type: "verse", number: "172", sanskrit: "विदाहपरिहाराय परं शीतानुलेपनः धारयेत्साम्बुकणिका मुक्ताकर्पूरमालिकाः", text: "vidāhaparihārāya paraṃ śītānulepanaḥ dhārayetsāmbukaṇikā muktākarpūramālikāḥ" },
      { type: "verse", number: "173", sanskrit: "सहिमसलिलगर्भाश्चन्द्रशुभ्रामृणालीः कुवलयदलमाला हारयष्टीश्च लोलाः स्तनतटविनिविष्टाश्चारुगात्र्यो दधानास्तनुसरसविलिता गाढमेनं स्वजेरन्", text: "sahimasalilagarbhāścandraśubhrāmṛṇālīḥ kuvalayadalamālā hārayaṣṭīśca lolāḥ stanataṭaviniviṣṭāścārugātryo dadhānāstanusarasavilitā gāḍhamenaṃ svajeran" },
      { type: "verse", number: "174", sanskrit: "नलिनीदलतालवृन्तवातैः प्रगलद्वारिलवैर्जलार्द्रया च दयिताकरपल्लवैश्च शीतैर् शुनस्वेदकृतं क्लमं हरेयुः", text: "nalinīdalatālavṛntavātaiḥ pragaladvārilavairjalārdrayā ca dayitākarapallavaiśca śītair śunasvedakṛtaṃ klamaṃ hareyuḥ" },
      { type: "verse", number: "175", sanskrit: "कुडवोस्यपरा मात्रा तदर्द्धं केवलस्य तु पलं पिष्टस्य तन्मज्ज्ञः सभक्तं प्राक्च शीलयेत्", text: "kuḍavosyaparā mātrā tadarddhaṃ kevalasya tu palaṃ piṣṭasya tanmajjñaḥ sabhaktaṃ prākca śīlayet" },
      { type: "verse", number: "176", sanskrit: "रसोग्निकल्पो मृदुनौजसा हि संयुज्यमानः सहसैव तस्य दाहातिसारारतिचित्तनाशान् कुर्यादतस्तं त्वरितो न युञ्ज्यात्", text: "rasognikalpo mṛdunaujasā hi saṃyujyamānaḥ sahasaiva tasya dāhātisārāraticittanāśān kuryādatastaṃ tvarito na yuñjyāt" },
      { type: "verse", number: "177", sanskrit: "जीर्णशाल्योद्दनं जीर्णे शङ्खकृन्देन्दुपाण्डुरम् भुञ्जीत यूषैः पयसा रसैर्वा धन्वचारिणाम्", text: "jīrṇaśālyoddanaṃ jīrṇe śaṅkhakṛndendupāṇḍuram bhuñjīta yūṣaiḥ payasā rasairvā dhanvacāriṇām" },
      { type: "verse", number: "178", sanskrit: "दीप्ताग्निर्मण्डकान् खादेत् सर्पिप्र्मण्डोपसेचनान् अखण्डमण्डलेन्द्वाभानिण्डरीखण्डमण्डितान्", text: "dīptāgnirmaṇḍakān khādet sarpiprmaṇḍopasecanān akhaṇḍamaṇḍalendvābhāniṇḍarīkhaṇḍamaṇḍitān" },
      { type: "verse", number: "179", sanskrit: "राजिकाशुक्तसम्पर्कविनिवर्तितगौरवैः पिष्टकाचूर्णधवलैर्वध्रैः सौकरकैर्युतान्", text: "rājikāśuktasamparkavinivartitagauravaiḥ piṣṭakācūrṇadhavalairvadhraiḥ saukarakairyutān" },
      { type: "verse", number: "180", sanskrit: "मद्यमेकं पिबेत्तत्तु तृट्प्रबन्धे जलान्वितम् गन्धमत्तक्वणदलि प्रियावक्त्रेन्दुबोधितम्", text: "madyamekaṃ pibettattu tṛṭprabandhe jalānvitam gandhamattakvaṇadali priyāvaktrendubodhitam" },
      { type: "verse", number: "181", sanskrit: "अमद्यपो यस्तु फलाम्बुतुक्रमवन्तिसोमं च सुगन्धि शीतम् सौवीरकं जाङ्गलजं रसं वा तुषोदक्वं वा परिसिक्थिकां वा", text: "amadyapo yastu phalāmbutukramavantisomaṃ ca sugandhi śītam sauvīrakaṃ jāṅgalajaṃ rasaṃ vā tuṣodakvaṃ vā parisikthikāṃ vā" },
      { type: "verse", number: "182", sanskrit: "तत्कल्कं वा समघृतं घृतपात्रे खजाहतम् स्थितं दशाहादश्नीयात्तद्वद्वा वसया समम्", text: "tatkalkaṃ vā samaghṛtaṃ ghṛtapātre khajāhatam sthitaṃ daśāhādaśnīyāttadvadvā vasayā samam" },
      { type: "verse", number: "183", sanskrit: "सद्यः पिष्टं सर्पिषा संयुतं वा निर्यासेन स्वेन युक्तं च कामम् युञ्जीतैनं पूर्वकैरेव पानैः कोष्णाम्भोभिर्वैष कल्पोतिवीर्यः", text: "sadyaḥ piṣṭaṃ sarpiṣā saṃyutaṃ vā niryāsena svena yuktaṃ ca kāmam yuñjītainaṃ pūrvakaireva pānaiḥ koṣṇāmbhobhirvaiṣa kalpotivīryaḥ" },
      { type: "verse", number: "184", sanskrit: "रसोनकल्कः सदृशाजसर्पिः षण्मासमुर्व्यामुषितो निहन्ति अभ्यङ्गपानाञ्जननस्ययुक्तो मनोविकारान् विषमज्वरं च", text: "rasonakalkaḥ sadṛśājasarpiḥ ṣaṇmāsamurvyāmuṣito nihanti abhyaṅgapānāñjananasyayukto manovikārān viṣamajvaraṃ ca" },
      { type: "verse", number: "185", sanskrit: "समतैलं सशुक्तं वा यवराशौ समास्थितम् वातरोगान् जयेत् खादन् घृतमांसोत्तराशनः", text: "samatailaṃ saśuktaṃ vā yavarāśau samāsthitam vātarogān jayet khādan ghṛtamāṃsottarāśanaḥ" },
      { type: "verse", number: "186", sanskrit: "तैलसर्पिर्गुडसिताः पृथक्कुर्यात्तुलान्मिताः द्वे तुले लशुनाच्छ्रुद्धात् त्र्यूषणात् कुडयत्रयम्", text: "tailasarpirguḍasitāḥ pṛthakkuryāttulānmitāḥ dve tule laśunācchruddhāt tryūṣaṇāt kuḍayatrayam" },
      { type: "verse", number: "187", sanskrit: "पलं त्वचश्च तच्श्लक्ष्णं निहितं घृतभाजने द्वे समे यवमध्यस्थं पूर्वस्मादधिकं गुणैः", text: "palaṃ tvacaśca tacślakṣṇaṃ nihitaṃ ghṛtabhājane dve same yavamadhyasthaṃ pūrvasmādadhikaṃ guṇaiḥ" },
      { type: "verse", number: "188", sanskrit: "क्षुण्णां क्षिपेत् कन्दतुलां तक्रस्य पलविंशतौ गते च सप्तरात्रे तु तुलार्द्धमसितात्तिलात्", text: "kṣuṇṇāṃ kṣipet kandatulāṃ takrasya palaviṃśatau gate ca saptarātre tu tulārddhamasitāttilāt" },
      { type: "verse", number: "189", sanskrit: "धौतक्षुण्णात् पृथक्क्षौद्रघृतशुण्ठीचतुष्पलम् अजाजीचव्यधान्याग्निद्विकृष्णाग्रन्थिदीप्यकान्", text: "dhautakṣuṇṇāt pṛthakkṣaudraghṛtaśuṇṭhīcatuṣpalam ajājīcavyadhānyāgnidvikṛṣṇāgranthidīpyakān" },
      { type: "verse", number: "190", sanskrit: "पलोन्मितांश्चतुर्जातात् पलमेकं सुचूर्णितम् पृथक्पलाष्टकं तैलात्घृतात्क्षुण्णाच्चसर्षपात्", text: "palonmitāṃścaturjātāt palamekaṃ sucūrṇitam pṛthakpalāṣṭakaṃ tailātghṛtātkṣuṇṇāccasarṣapāt" },
      { type: "verse", number: "191", sanskrit: "पटूनि पञ्च क्षारौ द्वौ दद्यात्तत्राक्षमानतः एकादशाहं तद्धान्ये स्थितमश्नन् प्रगे प्रगे गुणान्रासायनान्सर्वान् स प्राप्नोति निरामयः", text: "paṭūni pañca kṣārau dvau dadyāttatrākṣamānataḥ ekādaśāhaṃ taddhānye sthitamaśnan prage prage guṇānrāsāyanānsarvān sa prāpnoti nirāmayaḥ" },
      { type: "verse", number: "192", sanskrit: "द्विपश्चमूलनिष्क्वाथे नल्वणे लशुनाढकम् पिष्टं पर्युषितं वर्षं हन्ति वातकफामयान्", text: "dvipaścamūlaniṣkvāthe nalvaṇe laśunāḍhakam piṣṭaṃ paryuṣitaṃ varṣaṃ hanti vātakaphāmayān" },
      { type: "verse", number: "193", sanskrit: "तत्कन्दकल्कस्वरसे घृततैलं पृथक्पचेत् शीलयेच्च यथासात्म्यं दारुणानलपीडितः", text: "tatkandakalkasvarase ghṛtatailaṃ pṛthakpacet śīlayecca yathāsātmyaṃ dāruṇānalapīḍitaḥ" },
      { type: "verse", number: "194", sanskrit: "नवनीतसमांशं वा खोदत्तत्कल्कमर्दिती", text: "navanītasamāṃśaṃ vā khodattatkalkamarditī" },
      { type: "verse", number: "195", sanskrit: "विकञ्चुकप्राज्यरसोनगर्भान् सशूल्यमांसान् विविधोपदंशान् निमर्दकान् वा घृतशुक्तयुक्तान् प्रकाममद्याल्लघुतुच्छमश्नन्", text: "vikañcukaprājyarasonagarbhān saśūlyamāṃsān vividhopadaṃśān nimardakān vā ghṛtaśuktayuktān prakāmamadyāllaghutucchamaśnan" },
      { type: "verse", number: "196", sanskrit: "कुस्तुम्बरी जीरकभृष्टमुद्गसौवर्चलश्लक्ष्णरजोवकीर्णैः रसोनकन्दाङ्कुरपत्रचित्रैः सव्यञ्जनैर्नैकरसानुयातैः", text: "kustumbarī jīrakabhṛṣṭamudgasauvarcalaślakṣṇarajovakīrṇaiḥ rasonakandāṅkurapatracitraiḥ savyañjanairnaikarasānuyātaiḥ" },
      { type: "verse", number: "197", sanskrit: "तत्कन्दसिद्धान् क्रमशो यूषक्षीररसान् पिबेत् कफपित्तानिलाशङ्की यथास्वौषधसंस्कृतान्", text: "tatkandasiddhān kramaśo yūṣakṣīrarasān pibet kaphapittānilāśaṅkī yathāsvauṣadhasaṃskṛtān" },
      { type: "verse", number: "198", sanskrit: "कृशोश्वगन्धोद्भवचूर्णकीर्णं सन्नस्वरो यष्टिमधूपधानम् तैलेन गुल्मी खदिरेण कुष्ठी खादेत् कृमिघ्नैः कृमिमान् रसोनम्", text: "kṛśośvagandhodbhavacūrṇakīrṇaṃ sannasvaro yaṣṭimadhūpadhānam tailena gulmī khadireṇa kuṣṭhī khādet kṛmighnaiḥ kṛmimān rasonam" },
      { type: "verse", number: "199", sanskrit: "मांसादमांसैर्यक्ष्माणमर्शांसि कुटजत्वचा हन्ति स श्रेष्ठया मेहकासश्वासविलम्बिकाः", text: "māṃsādamāṃsairyakṣmāṇamarśāṃsi kuṭajatvacā hanti sa śreṣṭhayā mehakāsaśvāsavilambikāḥ" },
      { type: "verse", number: "200", sanskrit: "अन्नस्वरूपविज्ञानात् स्वरूपमुपलभ्य च यथायथं प्रयोगोस्य कार्यस्तं तं गदं प्रति", text: "annasvarūpavijñānāt svarūpamupalabhya ca yathāyathaṃ prayogosya kāryastaṃ taṃ gadaṃ prati" },
      { type: "verse", number: "201", sanskrit: "लशुनस्वरसात् प्रस्थान्द्वात्रिंशत्तिलतैलतः द्वावपेतमलात् किण्वादष्टौपिष्टाच्चषड्यवात्", text: "laśunasvarasāt prasthāndvātriṃśattilatailataḥ dvāvapetamalāt kiṇvādaṣṭaupiṣṭāccaṣaḍyavāt" },
      { type: "verse", number: "202", sanskrit: "मेषशृङ्गीभवात् क्वाथाद्रोणं पूताच्च शीतलात् स्नेहपात्रे तदैकध्यं निदध्याच्च शुचौ दृढे", text: "meṣaśṛṅgībhavāt kvāthādroṇaṃ pūtācca śītalāt snehapātre tadaikadhyaṃ nidadhyācca śucau dṛḍhe" },
      { type: "verse", number: "203", sanskrit: "क्रमात्तत्र पुनर्दद्यात् पिष्टं प्रस्थचतुष्टयम् पक्षात्परमियं पेया सुरा वातविकारिभिः", text: "kramāttatra punardadyāt piṣṭaṃ prasthacatuṣṭayam pakṣātparamiyaṃ peyā surā vātavikāribhiḥ" },
      { type: "verse", number: "204", sanskrit: "त्रिरात्रमुषितां धेनुं लशुनं खादयेत्ततः क्षीरदध्याज्यमथितं ब्राह्मणस्यापि शस्यते", text: "trirātramuṣitāṃ dhenuṃ laśunaṃ khādayettataḥ kṣīradadhyājyamathitaṃ brāhmaṇasyāpi śasyate" },
      { type: "verse", number: "205", sanskrit: "पित्तरक्तविनिर्मुक्तसमस्तावरणावृते शुद्धे वा विद्यते वायौ न द्रव्यं लशुनात्परम्", text: "pittaraktavinirmuktasamastāvaraṇāvṛte śuddhe vā vidyate vāyau na dravyaṃ laśunātparam" },
      { type: "verse", number: "206", sanskrit: "सुखात्मनां विशेषेण प्रयोज्यो लशुनासवः नारदेनोद्धवस्यैष वातभग्नस्य कल्पितः", text: "sukhātmanāṃ viśeṣeṇa prayojyo laśunāsavaḥ nāradenoddhavasyaiṣa vātabhagnasya kalpitaḥ" },
      { type: "verse", number: "207", sanskrit: "आमाम्बुपानेक्षुविकारमत्स्ययानाध्ववातातपभाष्यचिन्ताः स्वप्नं दिवा जागरणं निशासु पिष्टं व्यवायं दधि चात्र नेच्छेत्", text: "āmāmbupānekṣuvikāramatsyayānādhvavātātapabhāṣyacintāḥ svapnaṃ divā jāgaraṇaṃ niśāsu piṣṭaṃ vyavāyaṃ dadhi cātra necchet" },
      { type: "verse", number: "208", sanskrit: "स्नेहकल्पविधानेन स्नेहयुक्तं प्रयोजयेत् लशुनं स्नेहसंयोगात् गरीयान् जायते हि सः", text: "snehakalpavidhānena snehayuktaṃ prayojayet laśunaṃ snehasaṃyogāt garīyān jāyate hi saḥ" },
      { type: "verse", number: "209", sanskrit: "पित्तकोपभयादन्ते युञ्ज्यान्मृदुविएचनम् रसायनगुणानेवं परिपूर्णान् समश्नुते", text: "pittakopabhayādante yuñjyānmṛduviecanam rasāyanaguṇānevaṃ paripūrṇān samaśnute" },
      { type: "verse", number: "210", sanskrit: "प्रियाम्बुगुडदुग्धस्य मांसमद्याम्लविद्विषः अतितिक्षोरजीर्णं च रसोनो व्यापदे ध्रुवम्", text: "priyāmbuguḍadugdhasya māṃsamadyāmlavidviṣaḥ atitikṣorajīrṇaṃ ca rasono vyāpade dhruvam" },
      { type: "verse", number: "211", sanskrit: "पाण्डूदरोरक्षतशोफतृष्णापानात्ययच्छर्दिविषव्रणेषु पैत्ते विकारेक्षिगदेतिसारे क्षामे शरीरे च स वर्जनीयः", text: "pāṇḍūdarorakṣataśophatṛṣṇāpānātyayacchardiviṣavraṇeṣu paitte vikārekṣigadetisāre kṣāme śarīre ca sa varjanīyaḥ" },
      { type: "verse", number: "212", sanskrit: "शीलित एष करोति दुरापं वह्निशरीरबलं सममेव वङ्मतिरूपगुणाढ्यसुतेप्सोः स्त्रीपुरुषस्य च बीजविशुद्धिम्", text: "śīlita eṣa karoti durāpaṃ vahniśarīrabalaṃ samameva vaṅmatirūpaguṇāḍhyasutepsoḥ strīpuruṣasya ca bījaviśuddhim" },
      { type: "verse", number: "213", sanskrit: "अमृतकणसमुत्थं यो रसोनं रसोनं विधियुतमितिखादेच्छीतकाले सदैव स नयति शतजीवी स्त्रीसहायो जरान्तं कनकरुचिरवर्णो नीरुजस्तुष्टिजुष्टः", text: "amṛtakaṇasamutthaṃ yo rasonaṃ rasonaṃ vidhiyutamitikhādecchītakāle sadaiva sa nayati śatajīvī strīsahāyo jarāntaṃ kanakaruciravarṇo nīrujastuṣṭijuṣṭaḥ" },
      { type: "verse", number: "214", sanskrit: "रसोनानन्तरं वायोः पलाण्डुः परमौषधम् साक्षादिवस्थितं यत्र शकाधिपतिजीवितम्", text: "rasonānantaraṃ vāyoḥ palāṇḍuḥ paramauṣadham sākṣādivasthitaṃ yatra śakādhipatijīvitam" },
      { type: "verse", number: "215", sanskrit: "यस्योपयोगेन शकाङ्गनानां लावण्यसारादिविनिर्मितानाम् कपोलकान्त्या विजितः शशाङ्को रसातलं गच्छति निर्विदेव", text: "yasyopayogena śakāṅganānāṃ lāvaṇyasārādivinirmitānām kapolakāntyā vijitaḥ śaśāṅko rasātalaṃ gacchati nirvideva" },
      { type: "verse", number: "216", sanskrit: "स्निग्धाङ्गत्वं गौरता कान्तिमत्ता वनेर्दीप्तिर्वर्ष्मपुष्टिर्वृषत्वम् सम्प्राप्यन्ते यन्त्रणोद्वेगमुक्तैः र्यस्याभ्यासाद्धारि दीर्घं सुखं च", text: "snigdhāṅgatvaṃ gauratā kāntimattā vanerdīptirvarṣmapuṣṭirvṛṣatvam samprāpyante yantraṇodvegamuktaiḥ ryasyābhyāsāddhāri dīrghaṃ sukhaṃ ca" },
      { type: "verse", number: "217", sanskrit: "अप्याहारे शीलितो दीर्घारात्रं बल्यश्चक्षुष्यस्तर्पणः स्थैर्यकारी तैस्तैर्योगैर्योजितोयं पलाण्डुस्तांस्तानातङ्कान् मेहिनामुच्छिनत्ति", text: "apyāhāre śīlito dīrghārātraṃ balyaścakṣuṣyastarpaṇaḥ sthairyakārī taistairyogairyojitoyaṃ palāṇḍustāṃstānātaṅkān mehināmucchinatti" },
      { type: "verse", number: "218", sanskrit: "रसं रसोनवत्तस्य पीत्वाश्नीयात्तथैव च सबीजपूरस्वरसमदिरामधुशीधुपः", text: "rasaṃ rasonavattasya pītvāśnīyāttathaiva ca sabījapūrasvarasamadirāmadhuśīdhupaḥ" },
      { type: "verse", number: "219", sanskrit: "मरकतमणिनीलं नालमस्यातिबालं परिणतशशिगौरं यच्च बीजं सुपिष्टम् ससुरससुमुखाभ्यां प्राज्यमांसं सशुक्तं मृदुधवलसुवृत्तैर्मण्डकैरात्तमूर्तिम्", text: "marakatamaṇinīlaṃ nālamasyātibālaṃ pariṇataśaśigauraṃ yacca bījaṃ supiṣṭam sasurasasumukhābhyāṃ prājyamāṃsaṃ saśuktaṃ mṛdudhavalasuvṛttairmaṇḍakairāttamūrtim" },
      { type: "verse", number: "220", sanskrit: "वहुशःशोभितं शुभ्रैः शशाङ्कशकलोपमैः घारिकेण्डरिकावल्लैः क्षीरोदावयवैरिव", text: "vahuśaḥśobhitaṃ śubhraiḥ śaśāṅkaśakalopamaiḥ ghārikeṇḍarikāvallaiḥ kṣīrodāvayavairiva" },
      { type: "verse", number: "221", sanskrit: "यवमुद्गमाषगोधूम बहुविध विकारकल्पितान् भक्ष्यान् काम्बलिकरागषाडवसट्टकखलकान् सफलसारान्", text: "yavamudgamāṣagodhūma bahuvidha vikārakalpitān bhakṣyān kāmbalikarāgaṣāḍavasaṭṭakakhalakān saphalasārān" },
      { type: "verse", number: "222", sanskrit: "पटुसुरभिमधुरगन्धान् धवलाक्षकधवलबहुलरसान् खर्जूरदाडिमसिताद्राक्षापानानुपोभ्यस्येत्", text: "paṭusurabhimadhuragandhān dhavalākṣakadhavalabahularasān kharjūradāḍimasitādrākṣāpānānupobhyasyet" },
      { type: "verse", number: "223", sanskrit: "लभते बलवर्णौजोवीर्यस्वरसौमनस्यतेजांसि क्षीणशकृद्रुधिरोपि च रसोनवत्तद्रसं पीत्वा", text: "labhate balavarṇaujovīryasvarasaumanasyatejāṃsi kṣīṇaśakṛdrudhiropi ca rasonavattadrasaṃ pītvā" },
      { type: "verse", number: "224", sanskrit: "सुरासुरैःक्षीरसमुद्रमन्थे गतास्तटान् ये ऽमृतविप्रुषः पुरा बबूव तेभ्यः किल कुक्कुटी यया व्रजन्ति देवत्वमिवाद्य मानुषाः", text: "surāsuraiḥkṣīrasamudramanthe gatāstaṭān ye 'mṛtavipruṣaḥ purā babūva tebhyaḥ kila kukkuṭī yayā vrajanti devatvamivādya mānuṣāḥ" },
      { type: "verse", number: "225", sanskrit: "कुक्कुटाण्डनिभैः कन्दैः किञ्चित् कटुकपिच्छिलैः स्निग्धैर्मरकतच्छायैः खर्जूरसदृशैच्छदैः", text: "kukkuṭāṇḍanibhaiḥ kandaiḥ kiñcit kaṭukapicchilaiḥ snigdhairmarakatacchāyaiḥ kharjūrasadṛśaicchadaiḥ" },
      { type: "verse", number: "226", sanskrit: "निस्विलरोगहरापि विशेषतो जयति दारुणमप्यनिलामयम् गुदजगुल्मतमोविषनाशिनी जनयति स्थिरतां वपुषः पराम्", text: "nisvilarogaharāpi viśeṣato jayati dāruṇamapyanilāmayam gudajagulmatamoviṣanāśinī janayati sthiratāṃ vapuṣaḥ parām" },
      { type: "verse", number: "227", sanskrit: "कुटीं प्रविश्यतत्कन्दान् भक्षयेत्घृतभर्जितान् पयोनुपानं धारोष्णं तत्रेष्टमसनाम्बु वा", text: "kuṭīṃ praviśyatatkandān bhakṣayetghṛtabharjitān payonupānaṃ dhāroṣṇaṃ tatreṣṭamasanāmbu vā" },
      { type: "verse", number: "228", sanskrit: "तन्मात्रवृत्तिस्तुभवेद्दशाहं विंशत्यहं स्वादुभुगप्रमादी जत्रूर्ध्वकोष्ठत्रिकसन्धिवातपाण्डवामयार्शस्तिमिराणि जित्वा", text: "tanmātravṛttistubhaveddaśāhaṃ viṃśatyahaṃ svādubhugapramādī jatrūrdhvakoṣṭhatrikasandhivātapāṇḍavāmayārśastimirāṇi jitvā" },
      { type: "verse", number: "229", sanskrit: "वलीपलितनिर्मुक्तः स्थिरकेशद्विजश्रुतिः मेधामतिस्मृतियुतो जीवेद्वर्षशतद्वयम्", text: "valīpalitanirmuktaḥ sthirakeśadvijaśrutiḥ medhāmatismṛtiyuto jīvedvarṣaśatadvayam" },
      { type: "verse", number: "230", sanskrit: "आपूर्यमाणचन्द्रप्रतिपदमारभ्यवर्धयेत्कन्दम् एकैकं घृतभृष्टं प्राग्भक्तं पथ्यभुक्खादेत्", text: "āpūryamāṇacandrapratipadamārabhyavardhayetkandam ekaikaṃ ghṛtabhṛṣṭaṃ prāgbhaktaṃ pathyabhukkhādet" },
      { type: "verse", number: "231", sanskrit: "भुञ्जीताल्पतरं दिनार्दितमृषिः पक्षक्षये भक्षयन् क्षीरं बीजकवारि तक्रमथवा पीत्वा स्थितिं कल्पयेत् मांसं प्राश्य तथा नखद्विजकचः शीर्णोत्थितैः कान्तिमान् जीवत्यब्दशतत्रयं धृतिमतिस्मृत्यादिभिर्भूषितः", text: "bhuñjītālpataraṃ dinārditamṛṣiḥ pakṣakṣaye bhakṣayan kṣīraṃ bījakavāri takramathavā pītvā sthitiṃ kalpayet māṃsaṃ prāśya tathā nakhadvijakacaḥ śīrṇotthitaiḥ kāntimān jīvatyabdaśatatrayaṃ dhṛtimatismṛtyādibhirbhūṣitaḥ" },
      { type: "verse", number: "232", sanskrit: "क्षीरेण कन्दचूर्णं पिबन्यवागूं च परिणते मासम् लवणस्नेहविनां दृढदृग्जीवेच्छरद्द्विशतम्", text: "kṣīreṇa kandacūrṇaṃ pibanyavāgūṃ ca pariṇate māsam lavaṇasnehavināṃ dṛḍhadṛgjīveccharaddviśatam" },
      { type: "verse", number: "233", sanskrit: "तिमिरं क्षौद्रघृताभ्यां पथ्यभुजस्तद्रजो जयेन्मासात् कन्दत्रयं च भृष्टं घृतेश्नतो भक्षितं वातान्", text: "timiraṃ kṣaudraghṛtābhyāṃ pathyabhujastadrajo jayenmāsāt kandatrayaṃ ca bhṛṣṭaṃ ghṛteśnato bhakṣitaṃ vātān" },
      { type: "verse", number: "234", sanskrit: "तत्कन्दसूक्ष्मरजसा त्रिभागगोधूमचूर्णमिश्रेण पयसा पक्त्वा खादेत् घृतपूरानान्त्रवृद्धिहरान्", text: "tatkandasūkṣmarajasā tribhāgagodhūmacūrṇamiśreṇa payasā paktvā khādet ghṛtapūrānāntravṛddhiharān" },
      { type: "verse", number: "235", sanskrit: "त्रीन् कन्दकांश्च निशि भक्षयताज्यभृष्टान् धात्रीफलाम्बु ससितं चह्गलीपयो वा पेयं दृगामयजयाय निषेवितव्या कामं च रोगशममात्रफलार्थिभिः सा", text: "trīn kandakāṃśca niśi bhakṣayatājyabhṛṣṭān dhātrīphalāmbu sasitaṃ cahgalīpayo vā peyaṃ dṛgāmayajayāya niṣevitavyā kāmaṃ ca rogaśamamātraphalārthibhiḥ sā" },
      { type: "verse", number: "236", sanskrit: "क्षीरान्विता मूलकतुल्यकन्दा सप्ताष्टपत्रासितरक्तकाण्डा विभर्त्ति या पल्लवमब्दशब्दात् सा कञ्चुकी श्वेतवपुर्वरेण्या", text: "kṣīrānvitā mūlakatulyakandā saptāṣṭapatrāsitaraktakāṇḍā vibhartti yā pallavamabdaśabdāt sā kañcukī śvetavapurvareṇyā" },
      { type: "verse", number: "237", sanskrit: "आषाढे कार्तिके वात्तं तत्कन्दं शीतलं स्थितम् अङ्गुष्ठपर्वद्वयसं पिष्टं क्षीरपलाष्टके", text: "āṣāḍhe kārtike vāttaṃ tatkandaṃ śītalaṃ sthitam aṅguṣṭhaparvadvayasaṃ piṣṭaṃ kṣīrapalāṣṭake" },
      { type: "verse", number: "238", sanskrit: "कुटीप्रवेशस्तं पीत्वा क्षीरमेव पिबेदनु क्षीरमेव च जीर्णेपि पेयां वा स्नेहभर्जिताम्", text: "kuṭīpraveśastaṃ pītvā kṣīrameva pibedanu kṣīrameva ca jīrṇepi peyāṃ vā snehabharjitām" },
      { type: "verse", number: "239", sanskrit: "किञ्चिदुष्णामलवणां स्पृशेदुष्णाम्बु नो हिमम् एकेन सप्तरात्रेण कुष्ठान्येवं नियच्छति", text: "kiñciduṣṇāmalavaṇāṃ spṛśeduṣṇāmbu no himam ekena saptarātreṇa kuṣṭhānyevaṃ niyacchati" },
      { type: "verse", number: "240", sanskrit: "सर्वव्याधीन् द्वितीयेन तृतीयेन तु सर्पवत् त्यक्त्वा त्वचं ततो जीर्णां केशदन्तनखानपि धीमेधारूपवान् जीवेत् पञ्चवर्षशतानि च", text: "sarvavyādhīn dvitīyena tṛtīyena tu sarpavat tyaktvā tvacaṃ tato jīrṇāṃ keśadantanakhānapi dhīmedhārūpavān jīvet pañcavarṣaśatāni ca" },
      { type: "verse", number: "241", sanskrit: "कञ्चुकीकन्दचूर्णं वा स्वेन क्षीरेण भावितम् गोक्षीरकुडवे न्यतं कर्षं खण्डपलान्वितम् पीतं सर्वाभयान् हन्ति नखकेशस्थितानपि", text: "kañcukīkandacūrṇaṃ vā svena kṣīreṇa bhāvitam gokṣīrakuḍave nyataṃ karṣaṃ khaṇḍapalānvitam pītaṃ sarvābhayān hanti nakhakeśasthitānapi" },
      { type: "verse", number: "242", sanskrit: "पीततत्स्वरसं चूर्णं तस्या मधुघृतान्वितम् खादन्हिताशी सप्ताहं त्वग्दोषांस्तिमिरं जयेत्", text: "pītatatsvarasaṃ cūrṇaṃ tasyā madhughṛtānvitam khādanhitāśī saptāhaṃ tvagdoṣāṃstimiraṃ jayet" },
      { type: "verse", number: "243", sanskrit: "विडङ्गताप्यत्रिफलालोहकञ्चुकिजं रजः सप्तरात्रत्रयं लिह्यान्मधुना संयतेन्द्रियः", text: "viḍaṅgatāpyatriphalālohakañcukijaṃ rajaḥ saptarātratrayaṃ lihyānmadhunā saṃyatendriyaḥ" },
      { type: "verse", number: "244", sanskrit: "क्षीरेण भोजनं जीर्णे शालेर्लाबरसेन वा तथास्य काचत्यिमिरे सुकृच्छ्राः शिरसो गदाः", text: "kṣīreṇa bhojanaṃ jīrṇe śālerlābarasena vā tathāsya kācatyimire sukṛcchrāḥ śiraso gadāḥ" },
      { type: "verse", number: "245", sanskrit: "मेधाविनः प्रणश्यन्ति गात्रं सुप्तं च बुध्यते एष सप्तामृतश्चूर्णः सर्वव्याधिषु पूजितः", text: "medhāvinaḥ praṇaśyanti gātraṃ suptaṃ ca budhyate eṣa saptāmṛtaścūrṇaḥ sarvavyādhiṣu pūjitaḥ" },
      { type: "verse", number: "246", sanskrit: "पलं चूर्णस्य कञ्चुक्याः क्षीरप्रस्थे समावपेत् स्नेहं दध्नस्ततो लिह्याज्जितात्मा ससितामधु", text: "palaṃ cūrṇasya kañcukyāḥ kṣīraprasthe samāvapet snehaṃ dadhnastato lihyājjitātmā sasitāmadhu" },
      { type: "verse", number: "247", sanskrit: "शालेरन्नं पयः पानं मासमेवं प्रयोजयेत् चतुर्गुणः परीहारः शोषशाब्दसमद्युतिः शतानि पञ्च वर्षाणां जीवेद्देव इवोर्जितः", text: "śālerannaṃ payaḥ pānaṃ māsamevaṃ prayojayet caturguṇaḥ parīhāraḥ śoṣaśābdasamadyutiḥ śatāni pañca varṣāṇāṃ jīveddeva ivorjitaḥ" },
      { type: "verse", number: "248", sanskrit: "पचेत् पलानि द्रोणेपां कञ्चुक्याः पञ्चविंशतिः अष्टांशशिष्टे तु घृतात् प्रस्थं क्षीरसमं पचेत्", text: "pacet palāni droṇepāṃ kañcukyāḥ pañcaviṃśatiḥ aṣṭāṃśaśiṣṭe tu ghṛtāt prasthaṃ kṣīrasamaṃ pacet" },
      { type: "verse", number: "249", sanskrit: "शङ्खपुष्पीवचाकुष्ठत्रिवृतामरदारुभिः वरायष्टीसिताद्राक्षामहिषाक्षैः पलांशिकैः", text: "śaṅkhapuṣpīvacākuṣṭhatrivṛtāmaradārubhiḥ varāyaṣṭīsitādrākṣāmahiṣākṣaiḥ palāṃśikaiḥ" },
      { type: "verse", number: "250", sanskrit: "युक्तैः कमलकिञ्जल्कत्रिपलेन हिमे ऽत्र च क्षौद्राच्चतुष्पलं दद्यादेतन्मर्त्यामृताह्वयम् चक्षुष्यं बृंहणं मेध्यं वर्ण्यं वर्षशतप्रदम्", text: "yuktaiḥ kamalakiñjalkatripalena hime 'tra ca kṣaudrāccatuṣpalaṃ dadyādetanmartyāmṛtāhvayam cakṣuṣyaṃ bṛṃhaṇaṃ medhyaṃ varṇyaṃ varṣaśatapradam" },
      { type: "verse", number: "251", sanskrit: "पचेत्पलानि कञ्चुक्यास्त्रीणि लोहात्सुचूर्णितात् पलाशबीजाच्चत्वारि दश द्वे च फलत्रयात्", text: "pacetpalāni kañcukyāstrīṇi lohātsucūrṇitāt palāśabījāccatvāri daśa dve ca phalatrayāt" },
      { type: "verse", number: "252", sanskrit: "अष्टादश शतावर्या बीजकस्यैकाविंशतिः जीवन्त्याः षोडशैकध्यं पौर्णमास्यां विपाचयेत्", text: "aṣṭādaśa śatāvaryā bījakasyaikāviṃśatiḥ jīvantyāḥ ṣoḍaśaikadhyaṃ paurṇamāsyāṃ vipācayet" },
      { type: "verse", number: "253", sanskrit: "वहे ऽपां पादशेषे च पृथगर्द्धाढकेन च पचेत् काञ्जिकमस्तुभ्यां घृतप्रस्थं पिचून्मितैः", text: "vahe 'pāṃ pādaśeṣe ca pṛthagarddhāḍhakena ca pacet kāñjikamastubhyāṃ ghṛtaprasthaṃ picūnmitaiḥ" },
      { type: "verse", number: "254", sanskrit: "शताह्वारुष्करवचाकुष्ठैलाबिडहिङ्गुभिः सौवर्चलान्वितैः पद्मकेसराच्च त्रिभिः पलैः", text: "śatāhvāruṣkaravacākuṣṭhailābiḍahiṅgubhiḥ sauvarcalānvitaiḥ padmakesarācca tribhiḥ palaiḥ" },
      { type: "verse", number: "255", sanskrit: "पञ्चभिः पद्मबीजानां पद्मद्वादशकेन च एतत् सोमामृतं पीत्वा यस्सोमो ऽद्यापि राजते", text: "pañcabhiḥ padmabījānāṃ padmadvādaśakena ca etat somāmṛtaṃ pītvā yassomo 'dyāpi rājate" },
      { type: "verse", number: "256", sanskrit: "इदमुपयुज्य सर्पिरतिवीर्यमुदारगुणं भवति सुवाक्सुधीः सुदृढसुबलः सुभगः ग्रहमरकोपसर्गविषभीतिभिरधृष्यवपुर्विजितजराज्वरो नयति वर्षशतद्वितयम्", text: "idamupayujya sarpirativīryamudāraguṇaṃ bhavati suvāksudhīḥ sudṛḍhasubalaḥ subhagaḥ grahamarakopasargaviṣabhītibhiradhṛṣyavapurvijitajarājvaro nayati varṣaśatadvitayam" },
      { type: "verse", number: "257", sanskrit: "दानवेन्द्र विजितान् पुरा सुरान् भ्रष्टकान्तिधृतिधर्यतेजसः वीक्ष्य विष्णुरमृतं किलासृजत् गुग्गुलुं बलवपुर्जयप्रदम्", text: "dānavendra vijitān purā surān bhraṣṭakāntidhṛtidharyatejasaḥ vīkṣya viṣṇuramṛtaṃ kilāsṛjat gugguluṃ balavapurjayapradam" },
      { type: "verse", number: "258", sanskrit: "अद्याप्यतः सुरगणाः किल धूपमुख्यान् हित्वा वरागरुतुरुष्कहिमेन्दुदर्पान् निर्दह्यमानवपुष्षो ऽपि शिखां पिबन्तो गन्धेन यस्य मुदिता दधति प्रसादम्", text: "adyāpyataḥ suragaṇāḥ kila dhūpamukhyān hitvā varāgaruturuṣkahimendudarpān nirdahyamānavapuṣṣo 'pi śikhāṃ pibanto gandhena yasya muditā dadhati prasādam" },
      { type: "verse", number: "259", sanskrit: "स योगवाही स शिवः स सार्वः सर्वर्तुसेव्यः सुखशीलनीयः हन्ता जरापाप्ममलामयानां कर्ताग्निमेधास्मृतिपाटवानाम्", text: "sa yogavāhī sa śivaḥ sa sārvaḥ sarvartusevyaḥ sukhaśīlanīyaḥ hantā jarāpāpmamalāmayānāṃ kartāgnimedhāsmṛtipāṭavānām" },
      { type: "verse", number: "260", sanskrit: "गन्धोत्कटः स दाहे स्निग्धद्रवपिच्छिलो विगतशल्यः महिषाक्षः पुष्पराग स्फटिकासितनीरदच्छायः", text: "gandhotkaṭaḥ sa dāhe snigdhadravapicchilo vigataśalyaḥ mahiṣākṣaḥ puṣparāga sphaṭikāsitanīradacchāyaḥ" },
      { type: "verse", number: "261", sanskrit: "यः पद्मरागरागो यः कनकच्छेदपाटलो यो वा जयतीन्द्रनीलममलं भग्नोप्यन्तिकान्तिमत्वेन", text: "yaḥ padmarāgarāgo yaḥ kanakacchedapāṭalo yo vā jayatīndranīlamamalaṃ bhagnopyantikāntimatvena" },
      { type: "verse", number: "262", sanskrit: "आत्रेयमुनिगीतश्च मन्त्रोयं कर्मसिद्धिकृत् भगवान् पुण्डरीकाक्षो देवाश्च सपुरन्दराः", text: "ātreyamunigītaśca mantroyaṃ karmasiddhikṛt bhagavān puṇḍarīkākṣo devāśca sapurandarāḥ" },
      { type: "verse", number: "263", sanskrit: "जरामरणदुःखेभ्यो यथा तेग्युत्थिताः सुराः उपयोक्तुस्तथैवास्य भव त्वं हि महाबल", text: "jarāmaraṇaduḥkhebhyo yathā tegyutthitāḥ surāḥ upayoktustathaivāsya bhava tvaṃ hi mahābala" },
      { type: "verse", number: "264", sanskrit: "पञ्चमूलस्य महतः क्वाथेन हितभोजिना गुग्गुलुः शीलितो हन्ति सर्वान् वातकफामयान्", text: "pañcamūlasya mahataḥ kvāthena hitabhojinā gugguluḥ śīlito hanti sarvān vātakaphāmayān" },
      { type: "verse", number: "265", sanskrit: "लघीयसोपि तद्वच्च सुखोष्णेन जलेन वा मस्तुधान्याम्लमद्यैर्वा वचादेः सलिलेन वा", text: "laghīyasopi tadvacca sukhoṣṇena jalena vā mastudhānyāmlamadyairvā vacādeḥ salilena vā" },
      { type: "verse", number: "266", sanskrit: "वरणादेस्तु बाधिर्यदन्तकर्णशिरोरुजः स्वरभेदोदरश्वासवर्ध्मान्तर्गुल्मविद्रधीन्", text: "varaṇādestu bādhiryadantakarṇaśirorujaḥ svarabhedodaraśvāsavardhmāntargulmavidradhīn" },
      { type: "verse", number: "267", sanskrit: "वातपित्तास्ररोगेषु बृंहणार्थिनि चेष्यते क्वाथेन वाजिगन्धाया जीवनीयगणस्य वा", text: "vātapittāsrarogeṣu bṛṃhaṇārthini ceṣyate kvāthena vājigandhāyā jīvanīyagaṇasya vā" },
      { type: "verse", number: "268", sanskrit: "क्वाथेनोत्पलमृद्वीकारक्तचन्दनजन्मना वातपित्तं निहन्त्येष पद्मकादिगणस्य वा", text: "kvāthenotpalamṛdvīkāraktacandanajanmanā vātapittaṃ nihantyeṣa padmakādigaṇasya vā" },
      { type: "verse", number: "269", sanskrit: "चव्यकुष्ठविडङ्गानां यान्या नागरस्य वा प्रसारिण्याश्च तोयेन गुग्गुलुः कफवातजित्", text: "cavyakuṣṭhaviḍaṅgānāṃ yānyā nāgarasya vā prasāriṇyāśca toyena gugguluḥ kaphavātajit" },
      { type: "verse", number: "270", sanskrit: "त्र्यूषणाग्निघनवेल्लवराभिर्भक्षयन् समघृतं महिषाक्षम् आशु हन्ति कफमारुतमेदोदोषजान् बलवतोपि विकारान्", text: "tryūṣaṇāgnighanavellavarābhirbhakṣayan samaghṛtaṃ mahiṣākṣam āśu hanti kaphamārutamedodoṣajān balavatopi vikārān" },
      { type: "verse", number: "271", sanskrit: "पटोलनिम्बत्रिफलागुडूची गायत्रिरात्रिद्वयबीजकानाम् क्वाथैः पृथक्पथ्यपरस्य हन्ति मासेन घोरान् कफपित्तरोगान्", text: "paṭolanimbatriphalāguḍūcī gāyatrirātridvayabījakānām kvāthaiḥ pṛthakpathyaparasya hanti māsena ghorān kaphapittarogān" },
      { type: "verse", number: "272", sanskrit: "विशेषाच्छोफवीसर्पदुष्टव्रणभगन्दरान् शुक्रार्तवमनोदोषप्रमेहश्वित्रपाण्डुताः", text: "viśeṣācchophavīsarpaduṣṭavraṇabhagandarān śukrārtavamanodoṣapramehaśvitrapāṇḍutāḥ" },
      { type: "verse", number: "273", sanskrit: "पटोलारिष्टीर्नयूहपिष्टस्तुल्यरसाञ्जनः गलगोगापचीव्यङ्गग्रन्थिस्थौल्यकृमिप्रणुत्", text: "paṭolāriṣṭīrnayūhapiṣṭastulyarasāñjanaḥ galagogāpacīvyaṅgagranthisthaulyakṛmipraṇut" },
      { type: "verse", number: "274", sanskrit: "शिलाजतुसमःपीतः पयसा वातशोणितम् निवर्तयत्यतिबलं क्षीरमांसघृताशिनः", text: "śilājatusamaḥpītaḥ payasā vātaśoṇitam nivartayatyatibalaṃ kṣīramāṃsaghṛtāśinaḥ" },
      { type: "verse", number: "275", sanskrit: "रसेन पयसा मूत्रैर्वातपित्तकफापहः ब्राह्मीमण्डूकशङ्खानां पृथङ्मेधादिकृद्रसैः", text: "rasena payasā mūtrairvātapittakaphāpahaḥ brāhmīmaṇḍūkaśaṅkhānāṃ pṛthaṅmedhādikṛdrasaiḥ" },
      { type: "verse", number: "276", sanskrit: "मागधिकाग्निकलिङ्गबिडगैर्बिल्वधृतैः सवरापलषट्कैः गुग्गुलुना सदृशेन समेतैः क्षौद्रयुतैः सकलामयनाशः", text: "māgadhikāgnikaliṅgabiḍagairbilvadhṛtaiḥ savarāpalaṣaṭkaiḥ guggulunā sadṛśena sametaiḥ kṣaudrayutaiḥ sakalāmayanāśaḥ" },
      { type: "verse", number: "277", sanskrit: "पिबेत् पलशतं योस्य विधिना नियतो यतिः नाकालमृत्योर्न व्याधेर्न तस्य जरसो भयम्", text: "pibet palaśataṃ yosya vidhinā niyato yatiḥ nākālamṛtyorna vyādherna tasya jaraso bhayam" },
      { type: "verse", number: "278", sanskrit: "कल्पयेदौषधैः स्वै स्वैर्व्याधिषु व्याधिनाशनैः", text: "kalpayedauṣadhaiḥ svai svairvyādhiṣu vyādhināśanaiḥ" },
      { type: "verse", number: "279", sanskrit: "शिलाजतुविधानं च गुग्गुलोः सर्वमिष्यते", text: "śilājatuvidhānaṃ ca gugguloḥ sarvamiṣyate" },
      { type: "verse", number: "280", sanskrit: "गुणनिधिरपिकुर्यात् सोतिमात्रोपयुक्तस्तिमिरवदनशोषक्लबिताकार्श्यमोहान् शमलशिथिलभावं देहरौक्ष्यं च तस्माद्रजनिचरनिषेवीस्य्यान्न रोगेष्वमीषु", text: "guṇanidhirapikuryāt sotimātropayuktastimiravadanaśoṣaklabitākārśyamohān śamalaśithilabhāvaṃ deharaukṣyaṃ ca tasmādrajanicaraniṣevīsyyānna rogeṣvamīṣu" },
      { type: "verse", number: "281", sanskrit: "ग्रीष्मेर्कतप्ता गिरयो जतुतुल्यं वमन्ति यत् हेमादिषट्धातुरसं प्रोच्यते तच्छिलाजतु", text: "grīṣmerkataptā girayo jatutulyaṃ vamanti yat hemādiṣaṭdhāturasaṃ procyate tacchilājatu" },
      { type: "verse", number: "282", sanskrit: "सर्वदोषप्रशमनं सर्वरोगविनाशनम् शिलाभ्यो यस्य यज्जातं धातोस्तत्तद्गुणं वदेत्", text: "sarvadoṣapraśamanaṃ sarvarogavināśanam śilābhyo yasya yajjātaṃ dhātostattadguṇaṃ vadet" },
      { type: "verse", number: "283", sanskrit: "सर्वं च तिक्तकटुकं नात्युष्णं कटु पाकतः छेदनं च विशेषेण लौहं तत्र प्रशस्यते", text: "sarvaṃ ca tiktakaṭukaṃ nātyuṣṇaṃ kaṭu pākataḥ chedanaṃ ca viśeṣeṇa lauhaṃ tatra praśasyate" },
      { type: "verse", number: "284", sanskrit: "गोमूत्रगन्धि कृष्णं गुग्गुल्वाभं विशर्करं मृत्स्नम् स्निग्धमनम्लकषायं म्दृउ गुरु च शिलाजतु श्रेष्ठम्", text: "gomūtragandhi kṛṣṇaṃ guggulvābhaṃ viśarkaraṃ mṛtsnam snigdhamanamlakaṣāyaṃ mdṛu guru ca śilājatu śreṣṭham" },
      { type: "verse", number: "285", sanskrit: "रास्नादशमूलबला पुनर्नवैरण्डशुण्ठिमधुकानाम् क्वाथेन भावितं तद्विशेषतो वातरोगघ्नम्", text: "rāsnādaśamūlabalā punarnavairaṇḍaśuṇṭhimadhukānām kvāthena bhāvitaṃ tadviśeṣato vātarogaghnam" },
      { type: "verse", number: "286", sanskrit: "द्राक्षाभीरुपटोलत्रायन्तिगुडूचिजीवनीयानाम् निर्यूहेण सुभिन्नं शस्तं पित्तामये सुतराम्", text: "drākṣābhīrupaṭolatrāyantiguḍūcijīvanīyānām niryūheṇa subhinnaṃ śastaṃ pittāmaye sutarām" },
      { type: "verse", number: "287", sanskrit: "क्रिमिजिद्वचाफलत्रय करञ्जघनमुख्यपञ्चमूलानाम् सहपञ्चकोलकानां क्वाथेन कफामये भाव्यम्", text: "krimijidvacāphalatraya karañjaghanamukhyapañcamūlānām sahapañcakolakānāṃ kvāthena kaphāmaye bhāvyam" },
      { type: "verse", number: "288", sanskrit: "लघुपञ्चमूलशुण्ठी द्राक्षाकाश्मर्यवाजिगन्धानाम् सगुडूचिशरबलानां रसेन पित्तानिलगदेषु", text: "laghupañcamūlaśuṇṭhī drākṣākāśmaryavājigandhānām saguḍūciśarabalānāṃ rasena pittānilagadeṣu" },
      { type: "verse", number: "289", sanskrit: "घनकुष्ठवचात्रिफला सुरदारुविडङ्गपञ्चकोलानाम् रजनीमरिचातिविषा युक्तानां वातकफजेषु", text: "ghanakuṣṭhavacātriphalā suradāruviḍaṅgapañcakolānām rajanīmaricātiviṣā yuktānāṃ vātakaphajeṣu" },
      { type: "verse", number: "290", sanskrit: "पाठापटोलनिम्बत्रिफलाघनकुटजसप्तपर्णानाम् त्रायन्त्यमृतातिविषासहितानां पित्तकफजेषु", text: "pāṭhāpaṭolanimbatriphalāghanakuṭajasaptaparṇānām trāyantyamṛtātiviṣāsahitānāṃ pittakaphajeṣu" },
      { type: "verse", number: "291", sanskrit: "निचये ऽपिदोषबलतो योगानेतान् विकल्प्य युज्जीत विविधगणसङ्ग्रहोक्तैस्तैस्तैश्च गणैर्गिरेस्सारम्", text: "nicaye 'pidoṣabalato yogānetān vikalpya yujjīta vividhagaṇasaṅgrahoktaistaistaiśca gaṇairgiressāram" },
      { type: "verse", number: "292", sanskrit: "व्याधिव्याधितसात्म्यं समनुसरन् भावयेदयः पात्रे प्राक्केवलजलधौतं शुष्कं क्वाथैस्ततो भाव्यम्", text: "vyādhivyādhitasātmyaṃ samanusaran bhāvayedayaḥ pātre prākkevalajaladhautaṃ śuṣkaṃ kvāthaistato bhāvyam" },
      { type: "verse", number: "293", sanskrit: "समगिरिजमष्टगुणिते निष्क्काथ्यं भावनौषधं तोये तन्निर्यूहे ऽष्टांशे पूतोष्णे प्रक्षिपेत् गिरिजम्", text: "samagirijamaṣṭaguṇite niṣkkāthyaṃ bhāvanauṣadhaṃ toye tanniryūhe 'ṣṭāṃśe pūtoṣṇe prakṣipet girijam" },
      { type: "verse", number: "294", sanskrit: "तत् समरसतां यातं संशुष्कं प्रक्षिपेद्रसे भूयः स्वैस्वैरेवं क्वाथैर्भाव्यं वारान् भवेत् सप्त", text: "tat samarasatāṃ yātaṃ saṃśuṣkaṃ prakṣipedrase bhūyaḥ svaisvairevaṃ kvāthairbhāvyaṃ vārān bhavet sapta" },
      { type: "verse", number: "295", sanskrit: "अथ स्निग्धस्य शुद्धस्य घृतं तिक्तकसाधितम् त्र्यहं युञ्जीत गिरिजमेकैकेन तथा त्र्यहम्", text: "atha snigdhasya śuddhasya ghṛtaṃ tiktakasādhitam tryahaṃ yuñjīta girijamekaikena tathā tryaham" },
      { type: "verse", number: "296", sanskrit: "फलत्रयस्य यूषेण पटोल्या मधुकस्य च योगयोग्यं ततस्तस्य कालापेक्षं प्रयोजयेत्", text: "phalatrayasya yūṣeṇa paṭolyā madhukasya ca yogayogyaṃ tatastasya kālāpekṣaṃ prayojayet" },
      { type: "verse", number: "297", sanskrit: "शिलाजमेवं देहस्य भवत्यत्युपकारकम् गुणान् समग्रान् कुरुते सहसा व्यापदश्च न", text: "śilājamevaṃ dehasya bhavatyatyupakārakam guṇān samagrān kurute sahasā vyāpadaśca na" },
      { type: "verse", number: "298", sanskrit: "एकत्रिसप्तसप्ताहं कर्षमर्द्धपलं पलम् हीनमध्योत्तमो योगः शिलाजस्य क्रमान्मतः", text: "ekatrisaptasaptāhaṃ karṣamarddhapalaṃ palam hīnamadhyottamo yogaḥ śilājasya kramānmataḥ" },
      { type: "verse", number: "299", sanskrit: "संस्कृतं संस्कृते देहे प्रयुक्तं गिरिजाह्वयम् युक्तं व्यस्तैः समस्तैर्वा ताम्रायोरूप्यहेमभिः", text: "saṃskṛtaṃ saṃskṛte dehe prayuktaṃ girijāhvayam yuktaṃ vyastaiḥ samastairvā tāmrāyorūpyahemabhiḥ" },
      { type: "verse", number: "300", sanskrit: "क्षीरेणालोडितं कुर्याच्छीघ्रं रासायनं फलम् हन्याद्रोगानशेषांश्च जीर्णे हितमिताशिनः", text: "kṣīreṇāloḍitaṃ kuryācchīghraṃ rāsāyanaṃ phalam hanyādrogānaśeṣāṃśca jīrṇe hitamitāśinaḥ" },
      { type: "verse", number: "301", sanskrit: "व्यायामातपमारुतचेतःसन्तापगुरुविदाह्यादि उपयोगादपि परतो द्विगुणं परिवर्जयेत् कालम्", text: "vyāyāmātapamārutacetaḥsantāpaguruvidāhyādi upayogādapi parato dviguṇaṃ parivarjayet kālam" },
      { type: "verse", number: "302", sanskrit: "कुलत्थान् काकमाचीं च कपोतांश्च सदा त्यजेत् पिबेन्माहेन्द्रमुदकं कौपं प्रास्रवणाम्बु वा", text: "kulatthān kākamācīṃ ca kapotāṃśca sadā tyajet pibenmāhendramudakaṃ kaupaṃ prāsravaṇāmbu vā" },
      { type: "verse", number: "303", sanskrit: "ज्वरी ज्वरघ्नाम्बुदपर्पटादेः क्वाथेन रक्ती मधुयष्टिकायाः शोषी सरैः क्रव्यभुगामिषोत्थैर्मायुरमांसैः पयसा च कार्श्ये", text: "jvarī jvaraghnāmbudaparpaṭādeḥ kvāthena raktī madhuyaṣṭikāyāḥ śoṣī saraiḥ kravyabhugāmiṣotthairmāyuramāṃsaiḥ payasā ca kārśye" },
      { type: "verse", number: "304", sanskrit: "मध्वम्बुना मेदसि सम्प्रवृद्धे क्षीरेण पयाकुलबुद्धिसत्वः पाण्ड्वामयार्त्तावुदरे सशोफे पिबेच्छिलाजं महिषीजलेन", text: "madhvambunā medasi sampravṛddhe kṣīreṇa payākulabuddhisatvaḥ pāṇḍvāmayārttāvudare saśophe pibecchilājaṃ mahiṣījalena" },
      { type: "verse", number: "305", sanskrit: "अश्म वीरतराद्येन कुष्ठं खदिरवारिणा विषं विषघ्नैरगदैर्हन्त्येवं तद्यथामयम्", text: "aśma vīratarādyena kuṣṭhaṃ khadiravāriṇā viṣaṃ viṣaghnairagadairhantyevaṃ tadyathāmayam" },
      { type: "verse", number: "306", sanskrit: "शैलजत्रिकटुक्षौद्रक्षौद्रधातून् निषेवते क्षीरौदनाशी यो जीर्णे यक्ष्मणा न स बाध्यते", text: "śailajatrikaṭukṣaudrakṣaudradhātūn niṣevate kṣīraudanāśī yo jīrṇe yakṣmaṇā na sa bādhyate" },
      { type: "verse", number: "307", sanskrit: "सुभावितात्सारगणैस्तुलां पीत्वा शिलोद्भवात् सारांबुनैव भुञ्जानः शालिं जाङ्गलजै रसैः", text: "subhāvitātsāragaṇaistulāṃ pītvā śilodbhavāt sārāṃbunaiva bhuñjānaḥ śāliṃ jāṅgalajai rasaiḥ" },
      { type: "verse", number: "308", sanskrit: "व्यपोह्य मधुमेहाख्यमन्तकं रोगसङ्करम् वपुर्वर्णबलोपेतः शतं जीवत्यनामयः", text: "vyapohya madhumehākhyamantakaṃ rogasaṅkaram vapurvarṇabalopetaḥ śataṃ jīvatyanāmayaḥ" },
      { type: "verse", number: "309", sanskrit: "शिलाह्वात् षोडशपलं त्रिस्त्रिरेकत्र भावयेत् वराया दशमूलस्य गुडूच्याः कर्कशस्य च", text: "śilāhvāt ṣoḍaśapalaṃ tristrirekatra bhāvayet varāyā daśamūlasya guḍūcyāḥ karkaśasya ca" },
      { type: "verse", number: "310", sanskrit: "बलाया मधुयष्ट्याश्च रसे गव्ये च वारिणि क्षीरे सकृत्क्रमेणैवं सप्तकृत्वस्तथा पुनः", text: "balāyā madhuyaṣṭyāśca rase gavye ca vāriṇi kṣīre sakṛtkrameṇaivaṃ saptakṛtvastathā punaḥ" },
      { type: "verse", number: "311", sanskrit: "काकोलियुग्मघनपुष्करवह्निरास्ना मेदायुगर्द्धिचविकागजपिप्पलीनाम् पाठाद्विजीवकनिकुम्भविदारियुग्म वीरावरीमधुफलांशुमतीद्वयानाम्", text: "kākoliyugmaghanapuṣkaravahnirāsnā medāyugarddhicavikāgajapippalīnām pāṭhādvijīvakanikumbhavidāriyugma vīrāvarīmadhuphalāṃśumatīdvayānām" },
      { type: "verse", number: "312", sanskrit: "पलिकानामब्द्रोणे सिद्धानां पादशेषिते क्वाथे भावितमित्थं गिरिजं द्विपलैश्चूर्णीकृतैर्युञ्ज्यात्", text: "palikānāmabdroṇe siddhānāṃ pādaśeṣite kvāthe bhāvitamitthaṃ girijaṃ dvipalaiścūrṇīkṛtairyuñjyāt" },
      { type: "verse", number: "313", sanskrit: "कर्कटशृङ्गीधात्रीव्योषैस्तालीसपत्रकुडबेन चूर्णपलेन विदार्यास्त्वक्षीर्याः कर्षयुग्मेन", text: "karkaṭaśṛṅgīdhātrīvyoṣaistālīsapatrakuḍabena cūrṇapalena vidāryāstvakṣīryāḥ karṣayugmena" },
      { type: "verse", number: "314", sanskrit: "द्विपलेन चतुर्जातात्तैल घृतक्षौद्रशर्कराभिश्च द्विपलाद्द्विगुणाभिः कार्या गुटिकास्ततोक्षसमाः", text: "dvipalena caturjātāttaila ghṛtakṣaudraśarkarābhiśca dvipalāddviguṇābhiḥ kāryā guṭikāstatokṣasamāḥ" },
      { type: "verse", number: "315", sanskrit: "ताः शुष्का नवकुम्भे जातीपुष्पाधिवासिते स्थाप्याः तासामेकां खादेत् प्रतिदिनमनुपानमत्रेष्टम्", text: "tāḥ śuṣkā navakumbhe jātīpuṣpādhivāsite sthāpyāḥ tāsāmekāṃ khādet pratidinamanupānamatreṣṭam" },
      { type: "verse", number: "316", sanskrit: "क्षीररसदाडिमाम्भो मार्द्वीकसुरासवान्यतमम् जीर्णेन्नं लघु भोज्यं यूषपयःपिशितनिर्यूहैः", text: "kṣīrarasadāḍimāmbho mārdvīkasurāsavānyatamam jīrṇennaṃ laghu bhojyaṃ yūṣapayaḥpiśitaniryūhaiḥ" },
      { type: "verse", number: "317", sanskrit: "सप्ताहमात्रमेवं सर्वान्नीनः क्रमात् भवेत् परतः भक्तस्यान्ते प्राग्वा गुटिका न विरुध्यते सैषा", text: "saptāhamātramevaṃ sarvānnīnaḥ kramāt bhavet parataḥ bhaktasyānte prāgvā guṭikā na virudhyate saiṣā" },
      { type: "verse", number: "318", sanskrit: "निरपाया भूरिफला परिहारसुखोपयोजिता जयति प्रबलमपि वातशोणितमूरुस्तम्भं ज्वरं दीर्घम्", text: "nirapāyā bhūriphalā parihārasukhopayojitā jayati prabalamapi vātaśoṇitamūrustambhaṃ jvaraṃ dīrgham" },
      { type: "verse", number: "319", sanskrit: "भगमूत्रशुक्रदोषप्लीहयकृद्रक्तपाण्डुहृद्रोगान् वर्ध्मवमिगुल्मपीनसहिध्माकासारुचिश्वासान्", text: "bhagamūtraśukradoṣaplīhayakṛdraktapāṇḍuhṛdrogān vardhmavamigulmapīnasahidhmākāsāruciśvāsān" },
      { type: "verse", number: "320", sanskrit: "विद्रधिमुदरं कुष्ठं श्वित्रं जाड्यं क्षयं मदं मूर्च्छाम् उन्मादमपस्मारं मुखनेत्रशिरोगदांस्तांतान्", text: "vidradhimudaraṃ kuṣṭhaṃ śvitraṃ jāḍyaṃ kṣayaṃ madaṃ mūrcchām unmādamapasmāraṃ mukhanetraśirogadāṃstāṃtān" },
      { type: "verse", number: "321", sanskrit: "आनाहमतीसारं हलीमकं कामलाग्रहणिरोगान् ग्रन्थ्यर्बुदान् सपिटकान् भगन्दरं गण्डमालां च", text: "ānāhamatīsāraṃ halīmakaṃ kāmalāgrahaṇirogān granthyarbudān sapiṭakān bhagandaraṃ gaṇḍamālāṃ ca" },
      { type: "verse", number: "322", sanskrit: "अतिकार्श्यमतिस्थौल्यं स्वेदमथश्लीपदं गुदे कीलान् दंष्ट्राविषं समूलं गरप्रयोगान् सुघोरांश्च", text: "atikārśyamatisthaulyaṃ svedamathaślīpadaṃ gude kīlān daṃṣṭrāviṣaṃ samūlaṃ garaprayogān sughorāṃśca" },
      { type: "verse", number: "323", sanskrit: "अभिचारमरातिकृतं दुःस्वप्नं भौतिकीं तथा बाधाम् पाप्मालक्ष्मीं चेयं गुटिका शमयेच्छिवा नाम्ना", text: "abhicāramarātikṛtaṃ duḥsvapnaṃ bhautikīṃ tathā bādhām pāpmālakṣmīṃ ceyaṃ guṭikā śamayecchivā nāmnā" },
      { type: "verse", number: "324", sanskrit: "वृष्यायुष्या धन्या कान्तियशःश्रीविबोधिनी मेध्या कुरुते नृपवल्लभतां जयं विवादे च वक्त्रस्था", text: "vṛṣyāyuṣyā dhanyā kāntiyaśaḥśrīvibodhinī medhyā kurute nṛpavallabhatāṃ jayaṃ vivāde ca vaktrasthā" },
      { type: "verse", number: "325", sanskrit: "जितखलतिवलीपलिता जीवयति सुखं शतद्वयं शरदाम् वर्षद्वयप्रयोगाद्वर्षशतचतुष्टयं जीवेत्", text: "jitakhalativalīpalitā jīvayati sukhaṃ śatadvayaṃ śaradām varṣadvayaprayogādvarṣaśatacatuṣṭayaṃ jīvet" },
      { type: "verse", number: "326", sanskrit: "न सोस्तिरोगो भुवि साध्यरूपो जत्वश्मजं यं न जयेत् प्रसह्य तत्कालयोगैर्विधिवत्प्रयुक्तैः स्वस्थस्य चोर्जां विपुलां दधाति", text: "na sostirogo bhuvi sādhyarūpo jatvaśmajaṃ yaṃ na jayet prasahya tatkālayogairvidhivatprayuktaiḥ svasthasya corjāṃ vipulāṃ dadhāti" },
      { type: "verse", number: "327", sanskrit: "अमरमन्दिरमन्दरसम्भवाच्छतपलं गिरिजादुपयोजय यदि जरामयदुःखविवर्जितां सुचिरमिच्छसि जीवितसन्ततिम्", text: "amaramandiramandarasambhavācchatapalaṃ girijādupayojaya yadi jarāmayaduḥkhavivarjitāṃ suciramicchasi jīvitasantatim" },
      { type: "verse", number: "328", sanskrit: "दशगुणमुपयुङ्क्ते यः शतं शैलजाताल्लघुहितमितभोजी वर्जयन् वर्जनीयान् सततसमनुषक्तान् वर्जितान् वैद्यवृन्दैर्विधमति सगदौघान् नेक्षते चायुषोन्तम्", text: "daśaguṇamupayuṅkte yaḥ śataṃ śailajātāllaghuhitamitabhojī varjayan varjanīyān satatasamanuṣaktān varjitān vaidyavṛndairvidhamati sagadaughān nekṣate cāyuṣontam" },
      { type: "verse", number: "329", sanskrit: "समुद्वभूवामृतमन्थनोत्थः स्वेदः शिलाभ्यो ऽमृतवान् गिरेः प्राक् यो मन्दरस्यात्मभुवा हिताय न्यस्तः स शैलेषु शिलाजरूपी", text: "samudvabhūvāmṛtamanthanotthaḥ svedaḥ śilābhyo 'mṛtavān gireḥ prāk yo mandarasyātmabhuvā hitāya nyastaḥ sa śaileṣu śilājarūpī" },
      { type: "verse", number: "330", sanskrit: "सुवर्णशैलप्रभवो विष्णुना काञ्चनो रसः तापी किरातचीनेषु यवनेषु च निर्मितः", text: "suvarṇaśailaprabhavo viṣṇunā kāñcano rasaḥ tāpī kirātacīneṣu yavaneṣu ca nirmitaḥ" },
      { type: "verse", number: "331", sanskrit: "ताप्यां सूर्यांशुसन्तप्तो माधवे मासि दृश्यते मधुरः काञ्चनाभासः साम्लो रजतसन्निभः", text: "tāpyāṃ sūryāṃśusantapto mādhave māsi dṛśyate madhuraḥ kāñcanābhāsaḥ sāmlo rajatasannibhaḥ" },
      { type: "verse", number: "332", sanskrit: "किंचित् कषाय उभयः शीतः पाके कटुर्लघुः शिलानिर्यासवच्चात्र कुलत्थादीन् परित्यजेत्", text: "kiṃcit kaṣāya ubhayaḥ śītaḥ pāke kaṭurlaghuḥ śilāniryāsavaccātra kulatthādīn parityajet" },
      { type: "verse", number: "333", sanskrit: "न तन्निषेवी जरसाभिभृयते न पन्नगैर्नापि गरैर्न वृश्चिकैः न पाण्डुमेहज्वरशोफयक्ष्मभिर्न कण्ठनेत्रश्रवणत्वगामयैः", text: "na tanniṣevī jarasābhibhṛyate na pannagairnāpi garairna vṛścikaiḥ na pāṇḍumehajvaraśophayakṣmabhirna kaṇṭhanetraśravaṇatvagāmayaiḥ" },
      { type: "verse", number: "334", sanskrit: "सोदश्वित्को माक्षिकधातुः सघृतो वा सक्षौद्रो वा क्षौद्रघृताभ्यां सहितो वा साम्भस्को वा तैलयुतो वा विनिहन्ता त्वग्दोषाणां सर्वविषाणां सगराणाम्", text: "sodaśvitko mākṣikadhātuḥ saghṛto vā sakṣaudro vā kṣaudraghṛtābhyāṃ sahito vā sāmbhasko vā tailayuto vā vinihantā tvagdoṣāṇāṃ sarvaviṣāṇāṃ sagarāṇām" },
      { type: "verse", number: "335", sanskrit: "अक्षद्राक्षायोमलमुस्तामलकानां सव्योषाणां पर्वतनिर्यासयुतानाम् दत्वा तुल्यं माक्षिकधातुं मधुमिश्रं लिह्यात्पाण्डुव्याध्यभिभूतः शिवमिच्छन्", text: "akṣadrākṣāyomalamustāmalakānāṃ savyoṣāṇāṃ parvataniryāsayutānām datvā tulyaṃ mākṣikadhātuṃ madhumiśraṃ lihyātpāṇḍuvyādhyabhibhūtaḥ śivamicchan" },
      { type: "verse", number: "336", sanskrit: "अंशः शुण्ठ्या लोहमलांशो बदरांशः पिप्पल्यंशो माक्षिकधातुर्द्विगुणांशः क्षौद्रं कामं कृष्णतिलानामपि चांशः श्रेष्ठा पिण्डी पाण्डुविकारश्वयथुघ्नी", text: "aṃśaḥ śuṇṭhyā lohamalāṃśo badarāṃśaḥ pippalyaṃśo mākṣikadhāturdviguṇāṃśaḥ kṣaudraṃ kāmaṃ kṛṣṇatilānāmapi cāṃśaḥ śreṣṭhā piṇḍī pāṇḍuvikāraśvayathughnī" },
      { type: "verse", number: "337", sanskrit: "सायश्चूर्णं माक्षिकधातुं मधुमिश्रं व्योषोपेतं पर्वतनिर्याससमेतम् क्षीराहारो यो ऽवलिहानः प्रयतात्मा कृत्युद्वारं शोषमपोहत्यचिरेण", text: "sāyaścūrṇaṃ mākṣikadhātuṃ madhumiśraṃ vyoṣopetaṃ parvataniryāsasametam kṣīrāhāro yo 'valihānaḥ prayatātmā kṛtyudvāraṃ śoṣamapohatyacireṇa" },
      { type: "verse", number: "338", sanskrit: "लोहं सर्पिर्माक्षिकधातुर्मधुमात्रा धात्रीचूर्णं के सरमम्बुप्रभवानाम् योगः कुर्यादेष सिताभागविमिश्रश्चक्षुर्घ्राणश्रोत्ररसज्ञानविबोधम्", text: "lohaṃ sarpirmākṣikadhāturmadhumātrā dhātrīcūrṇaṃ ke saramambuprabhavānām yogaḥ kuryādeṣa sitābhāgavimiśraścakṣurghrāṇaśrotrarasajñānavibodham" },
      { type: "verse", number: "339", sanskrit: "कृत्यैकस्थं माक्षिकधातुं त्रिफलां च भ्राष्ट्रे पक्त्वा ये सहविष्कं विलिहन्ति पथ्यादास्तान् वार्धकदोषा न भजन्ते मातुर्दोषाः स्तन्यनिवृत्तानिव वालान्", text: "kṛtyaikasthaṃ mākṣikadhātuṃ triphalāṃ ca bhrāṣṭre paktvā ye sahaviṣkaṃ vilihanti pathyādāstān vārdhakadoṣā na bhajante māturdoṣāḥ stanyanivṛttāniva vālān" },
      { type: "verse", number: "340", sanskrit: "समश्नतो माक्षिकधातुचूर्णं सर्पिर्मधुभ्यां त्रिफलारजश्च शनैः शनैर्याति जरा विनाशं प्रत्यन्तवासादिव लोकयात्रा", text: "samaśnato mākṣikadhātucūrṇaṃ sarpirmadhubhyāṃ triphalārajaśca śanaiḥ śanairyāti jarā vināśaṃ pratyantavāsādiva lokayātrā" },
      { type: "verse", number: "341", sanskrit: "त्रिकोणकाण्डा सुबहुप्रताना फलेषु पीता कुसुमेषु रक्ता पत्रैःसदुग्धैर्मृदुरोमवद्भिस्ताम्बूलतुल्यैर्घनकन्दमूला", text: "trikoṇakāṇḍā subahupratānā phaleṣu pītā kusumeṣu raktā patraiḥsadugdhairmṛduromavadbhistāmbūlatulyairghanakandamūlā" },
      { type: "verse", number: "342", sanskrit: "पवनविवस्वदंशुवनितादिषुकामचरा विविधमनःशरीरगदवृन्दनिवृत्तिकरी भुवि परमौषधिर्महिषवल्लरीति प्रथिता क्वचिदपि वृद्धदारक इयत्वपि वेल्लरिका", text: "pavanavivasvadaṃśuvanitādiṣukāmacarā vividhamanaḥśarīragadavṛndanivṛttikarī bhuvi paramauṣadhirmahiṣavallarīti prathitā kvacidapi vṛddhadāraka iyatvapi vellarikā" },
      { type: "verse", number: "343", sanskrit: "वसन्ते सङ्गृहीतानां शोषितानामनातपे वृद्धदारकमूलानां तुलां संचूर्ण्यं सर्पिषा", text: "vasante saṅgṛhītānāṃ śoṣitānāmanātape vṛddhadārakamūlānāṃ tulāṃ saṃcūrṇyaṃ sarpiṣā" },
      { type: "verse", number: "344", sanskrit: "आप्लाव्य घृतपात्रस्थां धान्ये पक्षमुपेक्षिताम् लिह्यादनु पिवेत्क्षीरं जीर्णे क्षीरघृताशनः", text: "āplāvya ghṛtapātrasthāṃ dhānye pakṣamupekṣitām lihyādanu pivetkṣīraṃ jīrṇe kṣīraghṛtāśanaḥ" },
      { type: "verse", number: "345", sanskrit: "तत्प्रयोगाज्जराजीणा वृद्धा दारकतामियात् भग्नास्थिर्गद्गदः पङ्गुः कृशो ह्रस्वोन्यरूपताम्", text: "tatprayogājjarājīṇā vṛddhā dārakatāmiyāt bhagnāsthirgadgadaḥ paṅguḥ kṛśo hrasvonyarūpatām" },
      { type: "verse", number: "346", sanskrit: "निरस्ताशेषदोषोत्थनखभेदाद्युपद्रवः अपस्मारग्रहोन्मादपाप्मालक्ष्मीविवर्जितः दीप्ताग्निर्बलवान् वाग्मी जीवेद्वर्षशतानि षट्", text: "nirastāśeṣadoṣotthanakhabhedādyupadravaḥ apasmāragrahonmādapāpmālakṣmīvivarjitaḥ dīptāgnirbalavān vāgmī jīvedvarṣaśatāni ṣaṭ" },
      { type: "verse", number: "347", sanskrit: "चूर्णितैरश्वगन्धायाः संयुतं त्रिंशता पलैः तत्तुल्यं दारकं प्राश्य पयसा सर्पिषाथवा", text: "cūrṇitairaśvagandhāyāḥ saṃyutaṃ triṃśatā palaiḥ tattulyaṃ dārakaṃ prāśya payasā sarpiṣāthavā" },
      { type: "verse", number: "348", sanskrit: "जीर्णो पूर्ववदश्नीयाद्यो जीवेत् स समाः शतम् वाजिवेगो गजप्राणः सुरूपो भास्करद्युतिः", text: "jīrṇo pūrvavadaśnīyādyo jīvet sa samāḥ śatam vājivego gajaprāṇaḥ surūpo bhāskaradyutiḥ" },
      { type: "verse", number: "349", sanskrit: "अश्वगन्धेन संयोज्यौ वरीगोक्षुरकौ पृथक्", text: "aśvagandhena saṃyojyau varīgokṣurakau pṛthak" },
      { type: "verse", number: "350", sanskrit: "यो लिह्यात् सर्पिषा चूर्णं वृद्धदारकमूलजम् सप्ताहं यूषभक्ताशी स्यात् स किन्नरतुल्यवाक्", text: "yo lihyāt sarpiṣā cūrṇaṃ vṛddhadārakamūlajam saptāhaṃ yūṣabhaktāśī syāt sa kinnaratulyavāk" },
      { type: "verse", number: "351", sanskrit: "स्वरसेन शतावर्या सप्ताहं भावितं च तत् लिहानः पूर्ववन्मासं शतं जीवेन्महामतिः", text: "svarasena śatāvaryā saptāhaṃ bhāvitaṃ ca tat lihānaḥ pūrvavanmāsaṃ śataṃ jīvenmahāmatiḥ" },
      { type: "verse", number: "352", sanskrit: "लिह्याद्वा मधुसर्पिर्भ्यां धात्रीस्वरसभावितम् क्षीरेण वा पिबन्मासं शतं जीवेदरुक्सुधीः", text: "lihyādvā madhusarpirbhyāṃ dhātrīsvarasabhāvitam kṣīreṇa vā pibanmāsaṃ śataṃ jīvedaruksudhīḥ" },
      { type: "verse", number: "353", sanskrit: "वृद्धदारकमूलानां रसं क्षीरेण यः पिबेत् तत्कल्कसिद्धं सर्पिर्वा सजीवेन्नीरुजः शतम्", text: "vṛddhadārakamūlānāṃ rasaṃ kṣīreṇa yaḥ pibet tatkalkasiddhaṃ sarpirvā sajīvennīrujaḥ śatam" },
      { type: "verse", number: "354", sanskrit: "पीतं वेल्लरिकामूलं गोमूत्रेण सहोषितम् कुष्ठगुल्मोदरगरश्लीपदार्शोपचीर्जयेत्", text: "pītaṃ vellarikāmūlaṃ gomūtreṇa sahoṣitam kuṣṭhagulmodaragaraślīpadārśopacīrjayet" },
      { type: "verse", number: "355", sanskrit: "पिप्पली त्रिफला दार्वी महौषधपुनर्नवाः पृथग्दशपलाः सर्वैस्तुल्यांशो वृद्धदारकः", text: "pippalī triphalā dārvī mahauṣadhapunarnavāḥ pṛthagdaśapalāḥ sarvaistulyāṃśo vṛddhadārakaḥ" },
      { type: "verse", number: "356", sanskrit: "धान्याम्लपीतस्तच्चूर्णो जीर्णे स्वच्छन्दभोजनः श्लीपदाममरुद्वर्ध्मगुल्मोदरगरान् हरेत्", text: "dhānyāmlapītastaccūrṇo jīrṇe svacchandabhojanaḥ ślīpadāmamarudvardhmagulmodaragarān haret" },
      { type: "verse", number: "357", sanskrit: "शौण्डी विश्ववराद्वीपिवेल्लमुस्ताः समांशकाः तुल्यवेल्लरिकामूलाः साज्यक्षौद्रास्तथागुणाः", text: "śauṇḍī viśvavarādvīpivellamustāḥ samāṃśakāḥ tulyavellarikāmūlāḥ sājyakṣaudrāstathāguṇāḥ" },
      { type: "verse", number: "358", sanskrit: "तत्फलात् स्वरसं कर्षं लिहंस्तुल्याज्यमाक्षिकम् गव्यं पिबेदनु पयो माहिषं वा यथेष्टभुक्", text: "tatphalāt svarasaṃ karṣaṃ lihaṃstulyājyamākṣikam gavyaṃ pibedanu payo māhiṣaṃ vā yatheṣṭabhuk" },
      { type: "verse", number: "359", sanskrit: "पञ्चाहेन जयेत् कासान् सप्ताहेन त्वगामयान् महाकुष्ठानि मासेन भवेन्मासद्वयेन तु पञ्चवर्षशतायुष्को धीमेधाबलरूपवान्", text: "pañcāhena jayet kāsān saptāhena tvagāmayān mahākuṣṭhāni māsena bhavenmāsadvayena tu pañcavarṣaśatāyuṣko dhīmedhābalarūpavān" },
      { type: "verse", number: "360", sanskrit: "वेल्लरीफलमूलानां पिप्पल्याश्च समं रजः वेल्लरीफलमूलोत्थस्वरसेनैव भावयेत्", text: "vellarīphalamūlānāṃ pippalyāśca samaṃ rajaḥ vellarīphalamūlotthasvarasenaiva bhāvayet" },
      { type: "verse", number: "361", sanskrit: "अमृताया रसेनानु ततः शुष्कं घृताप्लुतम् निखनेत् घृतकुम्भस्थं करीषे बहुसञ्चये", text: "amṛtāyā rasenānu tataḥ śuṣkaṃ ghṛtāplutam nikhanet ghṛtakumbhasthaṃ karīṣe bahusañcaye" },
      { type: "verse", number: "362", sanskrit: "मासादुद्धृत्य तं लेहं यो वर्षमुपयोजयेत् सहस्रायुः स जरसा सहसा नाभिभूयते", text: "māsāduddhṛtya taṃ lehaṃ yo varṣamupayojayet sahasrāyuḥ sa jarasā sahasā nābhibhūyate" },
      { type: "verse", number: "363", sanskrit: "कुष्ठचूर्णतुलां क्षौद्रघृतस्य द्वितुलान्विताम् धान्यराशौ दिनशतं निहितामुपयोजयेत्", text: "kuṣṭhacūrṇatulāṃ kṣaudraghṛtasya dvitulānvitām dhānyarāśau dinaśataṃ nihitāmupayojayet" },
      { type: "verse", number: "364", sanskrit: "सुगन्धिकायो दृक्श्रोत्रस्वरवर्णेष्वतीन्द्रियः गतव्याधिजरो जीवेत् सप्तवर्षशतानि ना", text: "sugandhikāyo dṛkśrotrasvaravarṇeṣvatīndriyaḥ gatavyādhijaro jīvet saptavarṣaśatāni nā" },
      { type: "verse", number: "365", sanskrit: "कुटीप्रवेशः क्षणिनां परिच्छदवतां हितः अतोन्यथा तु ये तेषां सौर्यमारुतिको विधिः", text: "kuṭīpraveśaḥ kṣaṇināṃ paricchadavatāṃ hitaḥ atonyathā tu ye teṣāṃ sauryamārutiko vidhiḥ" },
      { type: "verse", number: "366", sanskrit: "वातातपसहा योगा वक्ष्यन्ते ऽतो विशेषतः सुखोपचारा भ्रंशे ऽपि ये न देहस्य बाधकाः", text: "vātātapasahā yogā vakṣyante 'to viśeṣataḥ sukhopacārā bhraṃśe 'pi ye na dehasya bādhakāḥ" },
      { type: "verse", number: "367", sanskrit: "शीतोदकं पयः क्षौद्रं घृतमेकैकशो द्विशः त्रिशः समस्तमथवा प्राक्पीतं स्थापयेद्वयः", text: "śītodakaṃ payaḥ kṣaudraṃ ghṛtamekaikaśo dviśaḥ triśaḥ samastamathavā prākpītaṃ sthāpayedvayaḥ" },
      { type: "verse", number: "368", sanskrit: "हरीतकीमागधिकाक्षधात्रीश्चूर्णीकृता लोहरजोविमिश्राः सर्पिर्मधुभ्यामदतः शरीरं कालाग्रदूती न जरा दुनोति", text: "harītakīmāgadhikākṣadhātrīścūrṇīkṛtā loharajovimiśrāḥ sarpirmadhubhyāmadataḥ śarīraṃ kālāgradūtī na jarā dunoti" },
      { type: "verse", number: "369", sanskrit: "हरीतकीमागधिकाविडङ्गशशाङ्कलेखामलकच्छवीनाम् सितोपलौतपघृतान्वितानां रोगा न लेढारमभिद्रवन्ति", text: "harītakīmāgadhikāviḍaṅgaśaśāṅkalekhāmalakacchavīnām sitopalautapaghṛtānvitānāṃ rogā na leḍhāramabhidravanti" },
      { type: "verse", number: "370", sanskrit: "त्रिफलामसनोदकेन पिष्टां रजनीं पर्युषितामयः कपाले मधुना मधुरां लिहन् हिनस्ति स्थविमानं जरसं गदांश्च सर्वान्", text: "triphalāmasanodakena piṣṭāṃ rajanīṃ paryuṣitāmayaḥ kapāle madhunā madhurāṃ lihan hinasti sthavimānaṃ jarasaṃ gadāṃśca sarvān" },
      { type: "verse", number: "371", sanskrit: "खदिरासनयूषभावितायास्त्रिफलाया घृतमाक्षिकप्लुतायाः नियमेन नरा निषेवितारो यदि जीवन्त्यजराः किमत्र चित्रम्", text: "khadirāsanayūṣabhāvitāyāstriphalāyā ghṛtamākṣikaplutāyāḥ niyamena narā niṣevitāro yadi jīvantyajarāḥ kimatra citram" },
      { type: "verse", number: "372", sanskrit: "असनस्वरसेन भावितानामभयानां सविडङ्गतण्डुलानाम् मधुलोहरजोघृताप्लुतानां न हि लेढारमभिद्रवन्ति रोगाः", text: "asanasvarasena bhāvitānāmabhayānāṃ saviḍaṅgataṇḍulānām madhuloharajoghṛtāplutānāṃ na hi leḍhāramabhidravanti rogāḥ" },
      { type: "verse", number: "373", sanskrit: "बीजकम्य रसमङ्गुलिहार्यं शर्करामधुघृतं त्रिफलां च शीलयत्सु पुरुषेषु जरत्तास्वागतापि विनिवर्त्तत एव", text: "bījakamya rasamaṅgulihāryaṃ śarkarāmadhughṛtaṃ triphalāṃ ca śīlayatsu puruṣeṣu jarattāsvāgatāpi vinivarttata eva" },
      { type: "verse", number: "374", sanskrit: "दर्वीप्रलेपास्रिफलाकषायः सितोपला तैलमधुप्रगाढः सपिप्पलीनागरलोहरेणुस्तनोः सपत्नीं जरसं निहन्ति", text: "darvīpralepāsriphalākaṣāyaḥ sitopalā tailamadhupragāḍhaḥ sapippalīnāgaralohareṇustanoḥ sapatnīṃ jarasaṃ nihanti" },
      { type: "verse", number: "375", sanskrit: "फलत्रयत्र्यूषणचूर्णयुक्तां द्राक्षां ससर्पिर्मधुशर्करां च क्षीरानुपानं पुरुषा लिहन्तो जीवन्ति निर्धूतजराविकाराः", text: "phalatrayatryūṣaṇacūrṇayuktāṃ drākṣāṃ sasarpirmadhuśarkarāṃ ca kṣīrānupānaṃ puruṣā lihanto jīvanti nirdhūtajarāvikārāḥ" },
      { type: "verse", number: "376", sanskrit: "हरीतकीं सर्पिषि सम्प्रताप्य समश्नतस्तत् पिबतो घृतं च भवेच्चिरस्थायि बलं शरीरे सक्द्त्कृतं साधु यथा कृतज्ञे", text: "harītakīṃ sarpiṣi sampratāpya samaśnatastat pibato ghṛtaṃ ca bhaveccirasthāyi balaṃ śarīre sakdtkṛtaṃ sādhu yathā kṛtajñe" },
      { type: "verse", number: "377", sanskrit: "आराच्चितानां कलशं पुराणं धात्रीफलानां मधुनश्च पूर्णम् संवत्सरार्द्धं निहितं यवेषु निषेवमाणो जरसं निहन्ति", text: "ārāccitānāṃ kalaśaṃ purāṇaṃ dhātrīphalānāṃ madhunaśca pūrṇam saṃvatsarārddhaṃ nihitaṃ yaveṣu niṣevamāṇo jarasaṃ nihanti" },
      { type: "verse", number: "378", sanskrit: "धात्रीकृमिघ्नासनसारचूर्णं सतैलसर्पिर्मधुलोहरेणु निषेवमाणस्य भवेन्नरस्य तारुण्यलावण्यमपि प्रणष्टम्", text: "dhātrīkṛmighnāsanasāracūrṇaṃ satailasarpirmadhulohareṇu niṣevamāṇasya bhavennarasya tāruṇyalāvaṇyamapi praṇaṣṭam" },
      { type: "verse", number: "379", sanskrit: "नवामलकशुक्तयो मधु घृतं रजश्चायसं चतुष्टयमयोघटस्थमिति चूर्णितं वत्सरम्", text: "navāmalakaśuktayo madhu ghṛtaṃ rajaścāyasaṃ catuṣṭayamayoghaṭasthamiti cūrṇitaṃ vatsaram" },
      { type: "verse", number: "380", sanskrit: "क्रमेण लिहतः पयोनुपिबतश्च पथ्याशिनश्चिरं भवति जीवितं क्षयमुपैति पृथवीजरा", text: "krameṇa lihataḥ payonupibataśca pathyāśinaściraṃ bhavati jīvitaṃ kṣayamupaiti pṛthavījarā" },
      { type: "verse", number: "381", sanskrit: "चूर्णं श्वदंष्ट्रामलकामृतानां लिहन् ससर्पिर्मधुभागयुक्तम् वृषस्थिरःशान्तविकारदुःखः समाः शतं जीवति कृष्णकेशः", text: "cūrṇaṃ śvadaṃṣṭrāmalakāmṛtānāṃ lihan sasarpirmadhubhāgayuktam vṛṣasthiraḥśāntavikāraduḥkhaḥ samāḥ śataṃ jīvati kṛṣṇakeśaḥ" },
      { type: "verse", number: "382", sanskrit: "विडङ्गसारं मधुकं च पिष्टं भल्लातकक्वाथमधुप्रगाढम् अर्शांसि जन्तूंश्च जयत्युदीर्णान् वह्निं च सन्धुक्षयति क्षणेन", text: "viḍaṅgasāraṃ madhukaṃ ca piṣṭaṃ bhallātakakvāthamadhupragāḍham arśāṃsi jantūṃśca jayatyudīrṇān vahniṃ ca sandhukṣayati kṣaṇena" },
      { type: "verse", number: "383", sanskrit: "विडङ्गभल्लातकचित्रकाणां गुडोत्तराणामभयान्वितानाम् तैलेन चूर्णानि निषेवमाणान् शरीरिणो नोपतपन्ति रोगाः", text: "viḍaṅgabhallātakacitrakāṇāṃ guḍottarāṇāmabhayānvitānām tailena cūrṇāni niṣevamāṇān śarīriṇo nopatapanti rogāḥ" },
      { type: "verse", number: "384", sanskrit: "विडङ्गभल्लातकनागराणि ये ऽश्नन्ति सर्पिर्मधुसंयुतानि जरानदीं रोगतरङ्गिणीं ते लावण्ययुक्ताः पुरुषास्तरन्ति", text: "viḍaṅgabhallātakanāgarāṇi ye 'śnanti sarpirmadhusaṃyutāni jarānadīṃ rogataraṅgiṇīṃ te lāvaṇyayuktāḥ puruṣāstaranti" },
      { type: "verse", number: "385", sanskrit: "विडङ्गकल्कं स्वरसेन धात्र्याः क्षौद्रेण युक्तं च पिबेन्नरो यः द्राक्षारसक्षौद्रपरिप्लुतं वा विजित्य रोगान् स भवेच्छतायुः", text: "viḍaṅgakalkaṃ svarasena dhātryāḥ kṣaudreṇa yuktaṃ ca pibennaro yaḥ drākṣārasakṣaudrapariplutaṃ vā vijitya rogān sa bhavecchatāyuḥ" },
      { type: "verse", number: "386", sanskrit: "चूर्णं समं मागधिकाकणानां विडङ्गचूर्णेन सचित्रकेण निषेवमाणो मधुतैलमिश्रं वयःपरीणामजले न मज्जेत्", text: "cūrṇaṃ samaṃ māgadhikākaṇānāṃ viḍaṅgacūrṇena sacitrakeṇa niṣevamāṇo madhutailamiśraṃ vayaḥparīṇāmajale na majjet" },
      { type: "verse", number: "387", sanskrit: "पुनर्नवस्यार्द्धपलं पलं वा पिष्टं पिबेद्यः पयसार्द्धामासम् मासद्वयं तत्त्रिगुणं समां वा जीर्णोपि भूयः सपुनर्नवः स्यात्", text: "punarnavasyārddhapalaṃ palaṃ vā piṣṭaṃ pibedyaḥ payasārddhāmāsam māsadvayaṃ tattriguṇaṃ samāṃ vā jīrṇopi bhūyaḥ sapunarnavaḥ syāt" },
      { type: "verse", number: "388", sanskrit: "मूर्वाबृहत्यंशुमतीबलानामुशीरपाठासनसारिवाणाम् कालानुसार्यागरुचन्दनानां वदन्ति पौनर्नवमेव कल्पम्", text: "mūrvābṛhatyaṃśumatībalānāmuśīrapāṭhāsanasārivāṇām kālānusāryāgarucandanānāṃ vadanti paunarnavameva kalpam" },
      { type: "verse", number: "389", sanskrit: "शतवरीकल्ककषायसिद्धं ये सर्पिरश्नन्ति सिताद्वितीयम् तान् जीविताध्वानमभिप्रपन्नान् न विप्रलुम्पन्ति विकारचोराः", text: "śatavarīkalkakaṣāyasiddhaṃ ye sarpiraśnanti sitādvitīyam tān jīvitādhvānamabhiprapannān na vipralumpanti vikāracorāḥ" },
      { type: "verse", number: "390", sanskrit: "पीताश्वगन्धा पयसार्द्धमासं घृतेन तैलेन सुखाम्बुना वा कृशस्य पुष्टिं वपुषो विधत्ते बालस्य सस्यस्य यथा सुवृष्टिः", text: "pītāśvagandhā payasārddhamāsaṃ ghṛtena tailena sukhāmbunā vā kṛśasya puṣṭiṃ vapuṣo vidhatte bālasya sasyasya yathā suvṛṣṭiḥ" },
      { type: "verse", number: "391", sanskrit: "दिने दिने कृष्णतिलप्रकुञ्चं समश्नतः शीतजलानुपानम् पोषः शरीरस्य भवत्यनल्पो दृढीभवन्त्यामरणाच्च दन्ताः", text: "dine dine kṛṣṇatilaprakuñcaṃ samaśnataḥ śītajalānupānam poṣaḥ śarīrasya bhavatyanalpo dṛḍhībhavantyāmaraṇācca dantāḥ" },
      { type: "verse", number: "392", sanskrit: "शिलाजतुक्षौद्रविडङ्गसर्पिर्लोहाभयापारदताप्यभक्षः आपूर्यते दुर्बलदेहधातुस्त्रिपञ्चरात्रेण यथा शशाङ्कः", text: "śilājatukṣaudraviḍaṅgasarpirlohābhayāpāradatāpyabhakṣaḥ āpūryate durbaladehadhātustripañcarātreṇa yathā śaśāṅkaḥ" },
      { type: "verse", number: "393", sanskrit: "मधु मधुरसा लाजा भार्ङ्गी मधूकशतावरी कमलकुसुमत्वक्षीरीभिः समं जतु पार्वतम् प्रचुरहविषा लेहं लीढ्वा समृद्धसितोपलं शिथिलजरसो मन्दातका भवन्ति चिरायुषः", text: "madhu madhurasā lājā bhārṅgī madhūkaśatāvarī kamalakusumatvakṣīrībhiḥ samaṃ jatu pārvatam pracurahaviṣā lehaṃ līḍhvā samṛddhasitopalaṃ śithilajaraso mandātakā bhavanti cirāyuṣaḥ" },
      { type: "verse", number: "394", sanskrit: "गायत्रीशिखिशिंशपासनशिवा वेल्लाक्षकारुष्करान् पिष्ट्वाष्टौ दशषट्गुणेम्भसि दृतान् खण्डैः सहायोमयैः पात्रे लोहकृते त्र्यहं रविकरैरालोडयन् पाचयेदग्नौ चानु मृदौ सलोहशकलं पादस्थितं तत् पचेत्", text: "gāyatrīśikhiśiṃśapāsanaśivā vellākṣakāruṣkarān piṣṭvāṣṭau daśaṣaṭguṇembhasi dṛtān khaṇḍaiḥ sahāyomayaiḥ pātre lohakṛte tryahaṃ ravikarairāloḍayan pācayedagnau cānu mṛdau salohaśakalaṃ pādasthitaṃ tat pacet" },
      { type: "verse", number: "395", sanskrit: "पूतस्यांशः क्षीरतोंशस्तथांशौ भार्ङ्गान्निर्यासात् पिबर्यास्त्रयोंशाः अंशाश्चत्वारस्तत्र हय्यङ्गवीनादेकीकृत्यैतत् साधयेत् कृष्णलौहे", text: "pūtasyāṃśaḥ kṣīratoṃśastathāṃśau bhārṅgānniryāsāt pibaryāstrayoṃśāḥ aṃśāścatvārastatra hayyaṅgavīnādekīkṛtyaitat sādhayet kṛṣṇalauhe" },
      { type: "verse", number: "396", sanskrit: "विमलया सितया मधुनाथवा युतमयुक्तमिदं यदि वा घृतम् स्वरुचिभोजनपानविचेष्टितो भवति ना पलशः परिशीलयन्", text: "vimalayā sitayā madhunāthavā yutamayuktamidaṃ yadi vā ghṛtam svarucibhojanapānaviceṣṭito bhavati nā palaśaḥ pariśīlayan" },
      { type: "verse", number: "397", sanskrit: "श्रीमान् निर्धूतपाप्मा वनमहिषबलो वाजिवेगः स्थिराङ्गो केशैर्भृङ्गाङ्गनीलैर्मधुसुरभिमुखो नैकयोषिन्निषेवी वाङ्मेधाधीसमृद्धः सुपटुहुतवहो मासमात्रोपयोगाद्धत्तेसौ नारसिंहं वपुरनलशिखातप्तचामीकराभम्", text: "śrīmān nirdhūtapāpmā vanamahiṣabalo vājivegaḥ sthirāṅgo keśairbhṛṅgāṅganīlairmadhusurabhimukho naikayoṣinniṣevī vāṅmedhādhīsamṛddhaḥ supaṭuhutavaho māsamātropayogāddhattesau nārasiṃhaṃ vapuranalaśikhātaptacāmīkarābham" },
      { type: "verse", number: "398", sanskrit: "हविरिदमतिप्रभावं स्वमिव वपुर्निर्मितं नृसिंहेन नश्यन्ति यतो भीता व्याध्याधिजरासुरा दूरात्", text: "haviridamatiprabhāvaṃ svamiva vapurnirmitaṃ nṛsiṃhena naśyanti yato bhītā vyādhyādhijarāsurā dūrāt" },
      { type: "verse", number: "399", sanskrit: "भृङ्गप्रवालानमुनैवभृष्टान् घृतेन यः खादति यन्त्रितात्मा विशुद्धकोष्ठो ऽसनसारासिद्धदुग्धानुपस्तत्कृतभोजनार्थः", text: "bhṛṅgapravālānamunaivabhṛṣṭān ghṛtena yaḥ khādati yantritātmā viśuddhakoṣṭho 'sanasārāsiddhadugdhānupastatkṛtabhojanārthaḥ" },
      { type: "verse", number: "400", sanskrit: "मासोपयोगात् स सुखी जीवत्यब्दशत त्रयम् गृह्णाति सकृदप्युक्तमविलुप्तस्मृतीन्दिर्यः", text: "māsopayogāt sa sukhī jīvatyabdaśata trayam gṛhṇāti sakṛdapyuktamaviluptasmṛtīndiryaḥ" },
      { type: "verse", number: "401", sanskrit: "अनेनैव च कल्पेन यस्तैलमुपयोजयेत् तानेवाप्नोति स गुणान् कृष्णकेशश्च जायते", text: "anenaiva ca kalpena yastailamupayojayet tānevāpnoti sa guṇān kṛṣṇakeśaśca jāyate" },
      { type: "verse", number: "402", sanskrit: "काश्मर्याणां तुलां मासं स्थितां मधुघृतोक्षिताम् उपयुज्य पयोन्नाशी चिरं जीवति कान्तिमान्", text: "kāśmaryāṇāṃ tulāṃ māsaṃ sthitāṃ madhughṛtokṣitām upayujya payonnāśī ciraṃ jīvati kāntimān" },
      { type: "verse", number: "403", sanskrit: "उक्तानि शक्यानि फलान्वितानि युगानुरूपाणि रसायनानि महानुशंसान्यपि चापराणि प्राप्त्यादिकष्टानि न कीर्त्तितानि", text: "uktāni śakyāni phalānvitāni yugānurūpāṇi rasāyanāni mahānuśaṃsānyapi cāparāṇi prāptyādikaṣṭāni na kīrttitāni" },
      { type: "verse", number: "404", sanskrit: "अमानुषाणामतिविस्मयानां सत्कर्मणां यद्यपि तानि हेतुः समूलकाषं तु कषन्ति देहं भ्रंशाद्विधेस्तेन विवर्जितानि", text: "amānuṣāṇāmativismayānāṃ satkarmaṇāṃ yadyapi tāni hetuḥ samūlakāṣaṃ tu kaṣanti dehaṃ bhraṃśādvidhestena vivarjitāni" },
      { type: "verse", number: "405", sanskrit: "युगस्वभावाद्यदि चौषधीनां क्रियासु शक्तिः परिकल्प्यते ऽल्पा आयुर्बलादिष्वपि सा तथेति यत्नान्निषेव्याणि रसायनानि", text: "yugasvabhāvādyadi cauṣadhīnāṃ kriyāsu śaktiḥ parikalpyate 'lpā āyurbalādiṣvapi sā tatheti yatnānniṣevyāṇi rasāyanāni" },
      { type: "verse", number: "406", sanskrit: "न चौषधीनामपि सर्वथैव प्रभावहानिः परिकल्पनीया फलं प्रयात्यूर्ध्वमधस्त्रिवृत्तु प्रत्यक्षतः कस्य न सिद्धमेतत्", text: "na cauṣadhīnāmapi sarvathaiva prabhāvahāniḥ parikalpanīyā phalaṃ prayātyūrdhvamadhastrivṛttu pratyakṣataḥ kasya na siddhametat" },
      { type: "verse", number: "407", sanskrit: "अदेशकालोपहितान्यसात्म्यान्यत्युष्णतीक्ष्णानि यथौषधानि नाशं नयन्ते सहसैव देहं सम्यक्प्रयुक्तानि तथैव वृद्धिम्", text: "adeśakālopahitānyasātmyānyatyuṣṇatīkṣṇāni yathauṣadhāni nāśaṃ nayante sahasaiva dehaṃ samyakprayuktāni tathaiva vṛddhim" },
      { type: "verse", number: "408", sanskrit: "जित्वा तस्मादिन्द्रियादीन् सुदुष्टान् कालोपेतः श्वद्दधानो यथावत् आयुःप्रज्ञातेजसां यद्विवृध्यै वीर्योपेतं शीलयेदौषधं तत्", text: "jitvā tasmādindriyādīn suduṣṭān kālopetaḥ śvaddadhāno yathāvat āyuḥprajñātejasāṃ yadvivṛdhyai vīryopetaṃ śīlayedauṣadhaṃ tat" },
      { type: "verse", number: "409", sanskrit: "उत्साहवीरैरपि सर्वकालं नरैरगम्यानि तपोदरिद्रैः महार्णवानामिव दुस्तराणां पाराण्यपाराणि रसायनानाम्", text: "utsāhavīrairapi sarvakālaṃ narairagamyāni tapodaridraiḥ mahārṇavānāmiva dustarāṇāṃ pārāṇyapārāṇi rasāyanānām" },
      { type: "verse", number: "410", sanskrit: "रसायनानामुपयोगसम्पदा कृतप्रसादैर्मलदोषधातुभिः स्थिरं शरीरं क्रियते शरीरिणां कुलं यथा सत्पुरुषैरधिष्ठितम्", text: "rasāyanānāmupayogasampadā kṛtaprasādairmaladoṣadhātubhiḥ sthiraṃ śarīraṃ kriyate śarīriṇāṃ kulaṃ yathā satpuruṣairadhiṣṭhitam" },
      { type: "verse", number: "411", sanskrit: "दान्तेन्द्रियेण शास्त्रार्थं यथावदनुतिष्ठाता कियद्वा दीर्घदर्शित्वं नेन्द्रत्वमपि दुर्लभम्", text: "dāntendriyeṇa śāstrārthaṃ yathāvadanutiṣṭhātā kiyadvā dīrghadarśitvaṃ nendratvamapi durlabham" },
      { type: "verse", number: "412", sanskrit: "रसायनविधिभ्रंशाज्जायेरन् व्याधयो यदि यथास्वमौषधं तेषां कार्यं मुक्त्वा रसायनम्", text: "rasāyanavidhibhraṃśājjāyeran vyādhayo yadi yathāsvamauṣadhaṃ teṣāṃ kāryaṃ muktvā rasāyanam" },
      { type: "verse", number: "413", sanskrit: "अध्याक्रान्ता ये ऽम्लपटुक्षारकटूष्णैर्द्रव्यैस्तीक्ष्णैः सन्निहिता तेषु जरत्ता सन्धुक्ष्योग्निस्तैरुपजाते च विवर्ज्या योगास्तेग्नौ धातुसमृद्धेः स हि मूलम्", text: "adhyākrāntā ye 'mlapaṭukṣārakaṭūṣṇairdravyaistīkṣṇaiḥ sannihitā teṣu jarattā sandhukṣyognistairupajāte ca vivarjyā yogāstegnau dhātusamṛddheḥ sa hi mūlam" },
      { type: "verse", number: "414", sanskrit: "आयुर्योगाः साध्वपि युक्ता मृदुवह्नौ नैरर्थक्यं यान्ति कृतघ्ने ऽप्युपकाराः दीप्ते वह्नौ ते तु गुणौघैरपि तुच्छा विस्तीर्यन्ते पात्रनिसृष्टा इव भोगाः", text: "āyuryogāḥ sādhvapi yuktā mṛduvahnau nairarthakyaṃ yānti kṛtaghne 'pyupakārāḥ dīpte vahnau te tu guṇaughairapi tucchā vistīryante pātranisṛṣṭā iva bhogāḥ" },
      { type: "verse", number: "415", sanskrit: "सत्यवादिनमक्रोधमध्यात्मप्रवणेन्द्रियम् शान्तं सद्वृत्तनिरतं विद्यान्नित्यरसायनम्", text: "satyavādinamakrodhamadhyātmapravaṇendriyam śāntaṃ sadvṛttanirataṃ vidyānnityarasāyanam" },
      { type: "verse", number: "416", sanskrit: "गुणैरोभिः समुदितः सेवते यो रसायनम् सनिर्वृतात्मा दीर्घायुः परत्रेह च मोदते", text: "guṇairobhiḥ samuditaḥ sevate yo rasāyanam sanirvṛtātmā dīrghāyuḥ paratreha ca modate" },
      { type: "verse", number: "417", sanskrit: "शास्त्रानुसारिणी चर्या चित्तज्ञाः पार्श्ववर्त्तिनः बुद्धिरस्खलितार्थेषु परिपूर्णं रसायनम्", text: "śāstrānusāriṇī caryā cittajñāḥ pārśvavarttinaḥ buddhiraskhalitārtheṣu paripūrṇaṃ rasāyanam" },
      { type: "verse", number: "418", sanskrit: "गवामृजुत्वेन कृतानुकारैरनन्यवागाशयदेहचेष्टैः स्थिरेन्द्रियायुर्ज्वलनैः सुशीलैः सुवृद्ध गोपैः समधिष्ठितेषु", text: "gavāmṛjutvena kṛtānukārairananyavāgāśayadehaceṣṭaiḥ sthirendriyāyurjvalanaiḥ suśīlaiḥ suvṛddha gopaiḥ samadhiṣṭhiteṣu" },
      { type: "verse", number: "419", sanskrit: "प्राज्याज्यदुग्धौषधिपादपेषु हुम्भारवैर्वल्गितवत्सकेषु मठप्रवेशेन विनापि सिद्धिं व्रजन्ति गोष्ठेषु रसायनानि", text: "prājyājyadugdhauṣadhipādapeṣu humbhāravairvalgitavatsakeṣu maṭhapraveśena vināpi siddhiṃ vrajanti goṣṭheṣu rasāyanāni" },
    ],
  },
  {
    sthana: "Уттара стхана",
    number: 50,
    lang: "sa",
    content: [
      { type: "heading", heading: "Дравья санграха — сводный каталог веществ" },
      { type: "text", text: "Глава 50 Уттара стханы — «Дравья санграха» — посвящена специализированному разделу: сводный каталог веществ. Это наиболее обширная часть Астанга-санграхи." },
      { type: "verse", number: "1", sanskrit: "अथातो वाजीकरणविधिं नामाध्यायं व्याख्यास्यामः इति ह स्माहु रात्रेयादयो महर्षयः", text: "athāto vājīkaraṇavidhiṃ nāmādhyāyaṃ vyākhyāsyāmaḥ iti ha smāhu rātreyādayo maharṣayaḥ" },
      { type: "verse", number: "2", sanskrit: "वाजीकरणमन्विच्छेत् सततं विषयी पुमान् तुष्टिः पुष्टिरपत्यं च गुणवत्तत्र संश्रितम् अपत्यसन्तानकरं यत्सद्यः सम्प्रहर्षणम्", text: "vājīkaraṇamanvicchet satataṃ viṣayī pumān tuṣṭiḥ puṣṭirapatyaṃ ca guṇavattatra saṃśritam apatyasantānakaraṃ yatsadyaḥ sampraharṣaṇam" },
      { type: "verse", number: "3", sanskrit: "वाजीवातिबलो येन यात्यप्रतिहतो ऽङ्गनाः भवत्यतिप्रियः स्त्रीणां येन येनोपचीयते तद्वाजीकरणं तद्धि देहस्यौजस्करं परम्", text: "vājīvātibalo yena yātyapratihato 'ṅganāḥ bhavatyatipriyaḥ strīṇāṃ yena yenopacīyate tadvājīkaraṇaṃ taddhi dehasyaujaskaraṃ param" },
      { type: "verse", number: "4", sanskrit: "सारो हि जीवलोकस्य स्त्री स्त्रीगुणसमन्विता स्त्रियः साद्ध्व्यः प्रसुवते नरान् गुणमयानिव", text: "sāro hi jīvalokasya strī strīguṇasamanvitā striyaḥ sāddhvyaḥ prasuvate narān guṇamayāniva" },
      { type: "verse", number: "5", sanskrit: "गोत्रवृद्धिकराह्येता गृहिण्यो गृहदेवताः गृहं हि जीनमेताभिर्न श्रीमदपि शोभते", text: "gotravṛddhikarāhyetā gṛhiṇyo gṛhadevatāḥ gṛhaṃ hi jīnametābhirna śrīmadapi śobhate" },
      { type: "verse", number: "6", sanskrit: "न तु ता अपि शोभन्ते जरसानुगता इव पुंयोगेन विना स्त्रीणां स हि संवननं परम्", text: "na tu tā api śobhante jarasānugatā iva puṃyogena vinā strīṇāṃ sa hi saṃvananaṃ param" },
      { type: "verse", number: "7", sanskrit: "वाजीकरणनित्यस्य कामं कामं सिषेविषोः न शरीरमवाप्नोति न वा रतिरतिः क्षयम्", text: "vājīkaraṇanityasya kāmaṃ kāmaṃ siṣeviṣoḥ na śarīramavāpnoti na vā ratiratiḥ kṣayam" },
      { type: "verse", number: "8", sanskrit: "अच्छायः पूतिकुसुमः फलेन रहितो द्रुमः यथैकश्चैकशाखश्च निरपत्यस्तथा नरः", text: "acchāyaḥ pūtikusumaḥ phalena rahito drumaḥ yathaikaścaikaśākhaśca nirapatyastathā naraḥ" },
      { type: "verse", number: "9", sanskrit: "अदृष्टपुत्रपौत्रस्य कुलतन्त्वन्तवर्त्तिनः संसारसुखबाह्यस्य कीदृशं नाम जीवितम्", text: "adṛṣṭaputrapautrasya kulatantvantavarttinaḥ saṃsārasukhabāhyasya kīdṛśaṃ nāma jīvitam" },
      { type: "verse", number: "10", sanskrit: "असम्बन्धोह्यपुत्रस्य नित्यमेव परः परः सीदत्यस्यावसाने च गृहं सुस्थेप्यनायकम् अतो वाजीकरा योगा निषेव्याः शुक्रवर्द्धनाः", text: "asambandhohyaputrasya nityameva paraḥ paraḥ sīdatyasyāvasāne ca gṛhaṃ susthepyanāyakam ato vājīkarā yogā niṣevyāḥ śukravarddhanāḥ" },
      { type: "verse", number: "11", sanskrit: "कल्यस्योदग्रवयसो वाजीकरणसेविनः सर्वेष्वृतुष्वहरहर्व्यवायो न निवार्यते", text: "kalyasyodagravayaso vājīkaraṇasevinaḥ sarveṣvṛtuṣvaharaharvyavāyo na nivāryate" },
      { type: "verse", number: "12", sanskrit: "चिन्ताजराभ्यां शुक्रं तु व्याधिभिः कर्मकर्शनात् क्षयं गच्छत्यनशनात् स्त्रीणां चातिनिषेवणात्", text: "cintājarābhyāṃ śukraṃ tu vyādhibhiḥ karmakarśanāt kṣayaṃ gacchatyanaśanāt strīṇāṃ cātiniṣevaṇāt" },
      { type: "verse", number: "13", sanskrit: "शुक्रक्षयात् भयाच्छोकादविस्रम्भादसेवनात् अतिहर्षादतिस्थौल्यान्मलोपचयतः श्रमात्", text: "śukrakṣayāt bhayācchokādavisrambhādasevanāt atiharṣādatisthaulyānmalopacayataḥ śramāt" },
      { type: "verse", number: "14", sanskrit: "स्त्रीणामकौशलाद्दोषदर्शनादभिचारतः मेढ्रामयात् सुमहतः क्रोधतो ऽधर्मकीर्त्तनात् तृप्तस्यापि स्त्रियो गन्तुं न शक्तिरुपजायते", text: "strīṇāmakauśalāddoṣadarśanādabhicārataḥ meḍhrāmayāt sumahataḥ krodhato 'dharmakīrttanāt tṛptasyāpi striyo gantuṃ na śaktirupajāyate" },
      { type: "verse", number: "15", sanskrit: "नहि जातबलाः सर्वे नराश्चापत्यभागिनः बृहच्छरीरा बलिनः केचिन्नारीषु दुर्बलाः", text: "nahi jātabalāḥ sarve narāścāpatyabhāginaḥ bṛhaccharīrā balinaḥ kecinnārīṣu durbalāḥ" },
      { type: "verse", number: "16", sanskrit: "सन्ति चाल्पाश्रयाः स्त्रीषु बलवन्तो बहुप्रजाः नराश्चटकवत्केचिद्व्रजन्ति बहुशः स्त्रियः", text: "santi cālpāśrayāḥ strīṣu balavanto bahuprajāḥ narāścaṭakavatkecidvrajanti bahuśaḥ striyaḥ" },
      { type: "verse", number: "17", sanskrit: "गजवच्चप्रसिञ्चन्ति केचिन्न बहुगामिनः केचित्प्रयत्नैर्वाह्यन्ते वृषाः केचित्स्वभावतः", text: "gajavaccaprasiñcanti kecinna bahugāminaḥ kecitprayatnairvāhyante vṛṣāḥ kecitsvabhāvataḥ" },
      { type: "verse", number: "18", sanskrit: "तस्मात्प्रयोगान् वक्ष्यामि दुर्बलानां बलप्रदान् सुखोपभोगान् बलिनां भूयश्च बलवर्द्धनान्", text: "tasmātprayogān vakṣyāmi durbalānāṃ balapradān sukhopabhogān balināṃ bhūyaśca balavarddhanān" },
      { type: "verse", number: "19", sanskrit: "अथ स्निग्धविशुद्धानां निरूहान् सानुवासनान् घृततैलरसक्षीरशर्कराक्षौद्रसंयुतान्", text: "atha snigdhaviśuddhānāṃ nirūhān sānuvāsanān ghṛtatailarasakṣīraśarkarākṣaudrasaṃyutān" },
      { type: "verse", number: "20", sanskrit: "योगविद्योजयेत् पूर्वं क्षीरमांसरसाशिनाम् ततो वाजीकरान्योगान् शुक्रापत्यबलप्रदान्", text: "yogavidyojayet pūrvaṃ kṣīramāṃsarasāśinām tato vājīkarānyogān śukrāpatyabalapradān" },
      { type: "verse", number: "21", sanskrit: "शरेक्षुकुशकाशानां विदार्या वीरणस्य च मूलानि कण्टकार्याश्च जीवकर्षभकौ बलाम्", text: "śarekṣukuśakāśānāṃ vidāryā vīraṇasya ca mūlāni kaṇṭakāryāśca jīvakarṣabhakau balām" },
      { type: "verse", number: "22", sanskrit: "मेदे द्वे द्वे च काकोल्यौ सूप्यपर्ण्यौ शतावरीम् अश्वगन्धामतिबलामात्मगुप्तां पुनर्नवाम्", text: "mede dve dve ca kākolyau sūpyaparṇyau śatāvarīm aśvagandhāmatibalāmātmaguptāṃ punarnavām" },
      { type: "verse", number: "23", sanskrit: "वीरां पयस्यां जीवन्तीमृद्धिं रास्नां त्रिकण्टकम् मधुकं शालिपर्णीं च भागांस्त्रिपलिकान् पृथक्", text: "vīrāṃ payasyāṃ jīvantīmṛddhiṃ rāsnāṃ trikaṇṭakam madhukaṃ śāliparṇīṃ ca bhāgāṃstripalikān pṛthak" },
      { type: "verse", number: "24", sanskrit: "माषाणामाढकं चैतत् द्विद्रोणे साधयेदपाम् रसेनाढकशेषेण पचेत्तेन घृताढकम्", text: "māṣāṇāmāḍhakaṃ caitat dvidroṇe sādhayedapām rasenāḍhakaśeṣeṇa pacettena ghṛtāḍhakam" },
      { type: "verse", number: "25", sanskrit: "दत्वा विदारीधात्रीक्षुरसानामाढकाढकम् घृताच्चतुर्गुणं क्षीरं पेष्याणीमानि चावपेत्", text: "datvā vidārīdhātrīkṣurasānāmāḍhakāḍhakam ghṛtāccaturguṇaṃ kṣīraṃ peṣyāṇīmāni cāvapet" },
      { type: "verse", number: "26", sanskrit: "वीरां स्वगुप्तां काकोल्यौ यष्टीं फल्गु द्विपिप्पलीम् द्राक्षां विदारीं खर्जूरं मधुकानि शतावरीम्", text: "vīrāṃ svaguptāṃ kākolyau yaṣṭīṃ phalgu dvipippalīm drākṣāṃ vidārīṃ kharjūraṃ madhukāni śatāvarīm" },
      { type: "verse", number: "27", sanskrit: "तत्सिद्धपूतं चूर्णस्य पृथक्प्रस्थेन योजयेत् शर्करायास्तुगायाश्च पिप्पल्याः कुडवेन च", text: "tatsiddhapūtaṃ cūrṇasya pṛthakprasthena yojayet śarkarāyāstugāyāśca pippalyāḥ kuḍavena ca" },
      { type: "verse", number: "28", sanskrit: "मरिचस्य प्रकुञ्चेन पृथगर्द्धपलोन्मितैः त्वगेलाकेसरैः श्लक्ष्णैः क्षौद्रद्विकुडवेन च", text: "maricasya prakuñcena pṛthagarddhapalonmitaiḥ tvagelākesaraiḥ ślakṣṇaiḥ kṣaudradvikuḍavena ca" },
      { type: "verse", number: "29", sanskrit: "पलमात्रं ततः खादेत् प्रत्यहं रसदुग्धमुक् तेनारोहति वाजीव कुलिङ्गैव हृष्यति", text: "palamātraṃ tataḥ khādet pratyahaṃ rasadugdhamuk tenārohati vājīva kuliṅgaiva hṛṣyati" },
      { type: "verse", number: "30", sanskrit: "माषात्मगुप्ताबीजानामाढकं प्रसृतोन्मितम् मेदाश्वगन्धर्द्धिवरी वीरा यष्टी द्विजीवकम्", text: "māṣātmaguptābījānāmāḍhakaṃ prasṛtonmitam medāśvagandharddhivarī vīrā yaṣṭī dvijīvakam" },
      { type: "verse", number: "31", sanskrit: "शूर्पे ऽपां विपचेत्तेन पादशेषेण पाचयेत् विदारीक्षुरसप्रस्थद्वयेन सदृशेन च", text: "śūrpe 'pāṃ vipacettena pādaśeṣeṇa pācayet vidārīkṣurasaprasthadvayena sadṛśena ca" },
      { type: "verse", number: "32", sanskrit: "सर्वैः क्षीरेण हविषो नवात् प्रस्थं शृते ऽत्र च सिताक्षौद्रसिताख्यानां पृथग्दद्याच्चतुष्पलम्", text: "sarvaiḥ kṣīreṇa haviṣo navāt prasthaṃ śṛte 'tra ca sitākṣaudrasitākhyānāṃ pṛthagdadyāccatuṣpalam" },
      { type: "verse", number: "33", sanskrit: "पलं कणात् पुरोभक्तं लिहंस्तत्पलपूर्वकम् तरुणीष्ववतृप्तासु प्रसभं रासभायते", text: "palaṃ kaṇāt purobhaktaṃ lihaṃstatpalapūrvakam taruṇīṣvavatṛptāsu prasabhaṃ rāsabhāyate" },
      { type: "verse", number: "34", sanskrit: "मेदादिभिश्च कर्षांशैः शृतं बाष्कयणं पयः सशर्कराक्षौद्रघृतं शुक्रवृद्धिकरं परम्", text: "medādibhiśca karṣāṃśaiḥ śṛtaṃ bāṣkayaṇaṃ payaḥ saśarkarākṣaudraghṛtaṃ śukravṛddhikaraṃ param" },
      { type: "verse", number: "35", sanskrit: "पयसा पायसस्तेन माषकण्डूकरीफलैः वृष्यो वेगकरः सिद्धः सघृतक्षौद्रशर्करः", text: "payasā pāyasastena māṣakaṇḍūkarīphalaiḥ vṛṣyo vegakaraḥ siddhaḥ saghṛtakṣaudraśarkaraḥ" },
      { type: "verse", number: "36", sanskrit: "श्वदंष्ट्राया विदार्याश्च रसे क्षीरचतुर्गुणे घृताढ्यः साधितो वृष्यो माषषष्टिकपायसः", text: "śvadaṃṣṭrāyā vidāryāśca rase kṣīracaturguṇe ghṛtāḍhyaḥ sādhito vṛṣyo māṣaṣaṣṭikapāyasaḥ" },
      { type: "verse", number: "37", sanskrit: "मधूलिका माषपर्णी सिता शृङ्गाटकं यवाः स्वगुप्तामूलयष्ट्याह्वविदारीक्षुरकाः समाः", text: "madhūlikā māṣaparṇī sitā śṛṅgāṭakaṃ yavāḥ svaguptāmūlayaṣṭyāhvavidārīkṣurakāḥ samāḥ" },
      { type: "verse", number: "38", sanskrit: "सप्रियालाः कृतं चूर्णं पृथङ्मध्वाज्यषड्गुणम् पादाभ्यामस्पृशन्भूमिं लिहन्काल्यमतः पिचुम् लभते वलमुत्साहं स्त्रीश्च याति कुलिङ्गवत्", text: "sapriyālāḥ kṛtaṃ cūrṇaṃ pṛthaṅmadhvājyaṣaḍguṇam pādābhyāmaspṛśanbhūmiṃ lihankālyamataḥ picum labhate valamutsāhaṃ strīśca yāti kuliṅgavat" },
      { type: "verse", number: "39", sanskrit: "स्वगुप्ता क्षीरकाकोली विदारी जीवकद्वयम् तिलाः सलुञ्चिता भृष्टाः शर्कराज्यमधुप्लुतम् तच्चूर्णं प्रसृतं लीढ्वा गच्छति प्रमदाशतम्", text: "svaguptā kṣīrakākolī vidārī jīvakadvayam tilāḥ saluñcitā bhṛṣṭāḥ śarkarājyamadhuplutam taccūrṇaṃ prasṛtaṃ līḍhvā gacchati pramadāśatam" },
      { type: "verse", number: "40", sanskrit: "प्रसृतं माषचूर्णस्य धात्रीस्वरसभावितम् विदारीरजसो वापि लिहन् मधुघृतद्रुतम् क्षीरानुपश्चटकवद्दशकृत्वो व्रजेत् स्त्रियः", text: "prasṛtaṃ māṣacūrṇasya dhātrīsvarasabhāvitam vidārīrajaso vāpi lihan madhughṛtadrutam kṣīrānupaścaṭakavaddaśakṛtvo vrajet striyaḥ" },
      { type: "verse", number: "41", sanskrit: "चूर्ण विदार्या बहुशः स्वरसेनैव भावितम् क्षौद्रसर्पिर्युतं लीढ्वा प्रमदा दश गच्छति", text: "cūrṇa vidāryā bahuśaḥ svarasenaiva bhāvitam kṣaudrasarpiryutaṃ līḍhvā pramadā daśa gacchati" },
      { type: "verse", number: "42", sanskrit: "कृष्णा धात्रीफलरजः स्वरसेनैवभावितम् शर्करामधुसर्पिर्भिर्लीढ्वा यो ऽनु पयः पिबेत् स नरो ऽशीतिवर्षोपि युवेव परिहृष्यति", text: "kṛṣṇā dhātrīphalarajaḥ svarasenaivabhāvitam śarkarāmadhusarpirbhirlīḍhvā yo 'nu payaḥ pibet sa naro 'śītivarṣopi yuveva parihṛṣyati" },
      { type: "verse", number: "43", sanskrit: "कर्षं मधुकचूर्णस्य घृतक्षौद्रसमन्वितम् पयोनुपानं यो लिह्यान्नित्यवेगः स ना भवेत्", text: "karṣaṃ madhukacūrṇasya ghṛtakṣaudrasamanvitam payonupānaṃ yo lihyānnityavegaḥ sa nā bhavet" },
      { type: "verse", number: "44", sanskrit: "कुलीरशृङ्ग्या यः कल्कमालोड्य पयसा पिबेत् सिताघृतपयोन्नाशी स नारीषु वृषायते", text: "kulīraśṛṅgyā yaḥ kalkamāloḍya payasā pibet sitāghṛtapayonnāśī sa nārīṣu vṛṣāyate" },
      { type: "verse", number: "45", sanskrit: "धान्यमाषरसः क्षीरं क्षौद्रमिक्षुरसो घृतम् द्विमेदाजीवकयुगक्वाथश्चैकत्र योजितः पीतः करोति पुरुषं प्रमदाशतगामिनम्", text: "dhānyamāṣarasaḥ kṣīraṃ kṣaudramikṣuraso ghṛtam dvimedājīvakayugakvāthaścaikatra yojitaḥ pītaḥ karoti puruṣaṃ pramadāśatagāminam" },
      { type: "verse", number: "46", sanskrit: "भल्लातकैश्चतुर्भिस्तु दुग्धस्यार्द्धाढकं पचेत् पीतं करोति वृषतां सुजीर्णस्यापि देहिनः", text: "bhallātakaiścaturbhistu dugdhasyārddhāḍhakaṃ pacet pītaṃ karoti vṛṣatāṃ sujīrṇasyāpi dehinaḥ" },
      { type: "verse", number: "47", sanskrit: "स्वयङ्गुप्तेक्षुरकयोर्बीजचूर्णं सशर्करम् धारोष्णेन नरः पीत्वा पयसा रासभायते उच्चटाचूर्णमप्येवं शतावर्याश्च योजयेत्", text: "svayaṅguptekṣurakayorbījacūrṇaṃ saśarkaram dhāroṣṇena naraḥ pītvā payasā rāsabhāyate uccaṭācūrṇamapyevaṃ śatāvaryāśca yojayet" },
      { type: "verse", number: "48", sanskrit: "सूप्यपर्णी द्विकाकोली जीवकर्षभकैः शृतम् लघुना पञ्चमूलेन द्विकाकोलीयुतेन वा पयो ऽतिवृष्यमभ्यस्य वृद्धो ऽपि तरुणायते", text: "sūpyaparṇī dvikākolī jīvakarṣabhakaiḥ śṛtam laghunā pañcamūlena dvikākolīyutena vā payo 'tivṛṣyamabhyasya vṛddho 'pi taruṇāyate" },
      { type: "verse", number: "49", sanskrit: "क्षीरिणी च श्वदंष्ट्रा च फाणितं शर्करा मधु गृष्टिक्षीरं नवं सर्पिरेतत् पुंसवनं परम्", text: "kṣīriṇī ca śvadaṃṣṭrā ca phāṇitaṃ śarkarā madhu gṛṣṭikṣīraṃ navaṃ sarpiretat puṃsavanaṃ param" },
      { type: "verse", number: "50", sanskrit: "अश्वत्थफलमूलत्वक्शृङ्गसिद्धं पयो नरः पीत्वा सशर्करं शीतं कुलिङ्ग इव हृष्यति", text: "aśvatthaphalamūlatvakśṛṅgasiddhaṃ payo naraḥ pītvā saśarkaraṃ śītaṃ kuliṅga iva hṛṣyati" },
      { type: "verse", number: "51", sanskrit: "पयः पयस्यया सिद्धं शुक्रकृत्साज्यमाक्षिकम्", text: "payaḥ payasyayā siddhaṃ śukrakṛtsājyamākṣikam" },
      { type: "verse", number: "52", sanskrit: "शतावरीकत्करसे पयो दशगुणं घृतम् शृतं सपिप्पलीक्षौद्रशर्करं वृष्यमुत्तमम्", text: "śatāvarīkatkarase payo daśaguṇaṃ ghṛtam śṛtaṃ sapippalīkṣaudraśarkaraṃ vṛṣyamuttamam" },
      { type: "verse", number: "53", sanskrit: "शतावरीरसप्रस्थं क्षीरप्रस्थचतुष्टयम् प्रस्थं घृतस्य शुक्त्यंशं द्राक्षामांसीपरूषकम्", text: "śatāvarīrasaprasthaṃ kṣīraprasthacatuṣṭayam prasthaṃ ghṛtasya śuktyaṃśaṃ drākṣāmāṃsīparūṣakam" },
      { type: "verse", number: "54", sanskrit: "जीवकर्षभयष्ट्याह्वबलामेदाकशेरुकम् प्रियालबीजं काकोलीयुग्मं चैकत्र पाचयेत्", text: "jīvakarṣabhayaṣṭyāhvabalāmedākaśerukam priyālabījaṃ kākolīyugmaṃ caikatra pācayet" },
      { type: "verse", number: "55", sanskrit: "पक्वपूते क्षिपेच्चास्मिन् कुडवांशां सितोपलाम् गृष्टिक्षीरानुपः प्राश्य तन्नारीषु वृषायते विजयेत च वातास्रं पित्तास्रोरःक्षतक्षयान्", text: "pakvapūte kṣipeccāsmin kuḍavāṃśāṃ sitopalām gṛṣṭikṣīrānupaḥ prāśya tannārīṣu vṛṣāyate vijayeta ca vātāsraṃ pittāsroraḥkṣatakṣayān" },
      { type: "verse", number: "56", sanskrit: "जीवकक्षीरकाकोलीस्थिराहंसपदीघनः शठीक्षुगण्डिकायष्टीमृणालैः कर्षिकैः पचेत्", text: "jīvakakṣīrakākolīsthirāhaṃsapadīghanaḥ śaṭhīkṣugaṇḍikāyaṣṭīmṛṇālaiḥ karṣikaiḥ pacet" },
      { type: "verse", number: "57", sanskrit: "घृतप्रस्थं दशगुणे क्षीरे तत् बलपुष्टिकृत् वन्ध्यानां पुत्रजननं शुक्रवर्द्धनशोधनम्", text: "ghṛtaprasthaṃ daśaguṇe kṣīre tat balapuṣṭikṛt vandhyānāṃ putrajananaṃ śukravarddhanaśodhanam" },
      { type: "verse", number: "58", sanskrit: "जलाढके स्वयंगुप्तामूलात् पञ्चपलं पचेत् पादशेषे च संचूर्ण्य कुडवांशाः पृथक् क्षिपेत्", text: "jalāḍhake svayaṃguptāmūlāt pañcapalaṃ pacet pādaśeṣe ca saṃcūrṇya kuḍavāṃśāḥ pṛthak kṣipet" },
      { type: "verse", number: "59", sanskrit: "स्वगुप्तामूलगोधूममाषेक्षुरकपिप्पलीः सप्रियालफलक्षौद्राः प्रस्थार्द्धं नवसर्पिषः", text: "svaguptāmūlagodhūmamāṣekṣurakapippalīḥ sapriyālaphalakṣaudrāḥ prasthārddhaṃ navasarpiṣaḥ" },
      { type: "verse", number: "60", sanskrit: "सितोपलातुलापादं कुर्यात्तान् मोदकांस्ततः मोदकं भक्षयित्वैकं षष्टिं व्रजति योषिताम्", text: "sitopalātulāpādaṃ kuryāttān modakāṃstataḥ modakaṃ bhakṣayitvaikaṃ ṣaṣṭiṃ vrajati yoṣitām" },
      { type: "verse", number: "61", sanskrit: "पलांशान् बृहतीव्याघ्रीपृश्निपर्णीत्रिकण्टकान् द्व्याढकेनाम्भसा पक्त्वा पादशेषे रसे स्थिते", text: "palāṃśān bṛhatīvyāghrīpṛśniparṇītrikaṇṭakān dvyāḍhakenāmbhasā paktvā pādaśeṣe rase sthite" },
      { type: "verse", number: "62", sanskrit: "पलानि क्षीरकाकोल्याः पञ्च मागधिकापलम् स्वगुप्ताफलमूलानां माषाणामिक्षुरस्य च", text: "palāni kṣīrakākolyāḥ pañca māgadhikāpalam svaguptāphalamūlānāṃ māṣāṇāmikṣurasya ca" },
      { type: "verse", number: "63", sanskrit: "विदार्या मधुनश्चात्र कुडवं कुडवं क्षिपेत् पृथक् द्वौ मुद्गतिलयोर्घृते शष्कुलिकास्ततः पचेदेकां ततः प्राश्य शतं व्रजति योषिताम्", text: "vidāryā madhunaścātra kuḍavaṃ kuḍavaṃ kṣipet pṛthak dvau mudgatilayorghṛte śaṣkulikāstataḥ pacedekāṃ tataḥ prāśya śataṃ vrajati yoṣitām" },
      { type: "verse", number: "64", sanskrit: "स्वगुप्तामूलचूर्णेन द्रुतेन पयसा कृताः घृते सशर्कराक्षौद्रा भक्ष्या वेगशतप्रदाः", text: "svaguptāmūlacūrṇena drutena payasā kṛtāḥ ghṛte saśarkarākṣaudrā bhakṣyā vegaśatapradāḥ" },
      { type: "verse", number: "65", sanskrit: "माषात्मगुप्तागोधूमशालिषष्टिकपैष्टिकान् शर्कराया विदार्याश्च चूर्णानीक्षुरकस्य च", text: "māṣātmaguptāgodhūmaśāliṣaṣṭikapaiṣṭikān śarkarāyā vidāryāśca cūrṇānīkṣurakasya ca" },
      { type: "verse", number: "66", sanskrit: "संयोज्य क्षीरसर्पिर्भ्यां घृते पूपलिकाः पचेत् पयोनुपानास्ताः शीघ्रं कुर्वन्ति वृषतां परम्", text: "saṃyojya kṣīrasarpirbhyāṃ ghṛte pūpalikāḥ pacet payonupānāstāḥ śīghraṃ kurvanti vṛṣatāṃ param" },
      { type: "verse", number: "67", sanskrit: "चूर्णं माषात्तिलाच्छालेर्विदार्याश्च ससैन्धवम् रसेन पुण्ड्रकस्येक्षोः प्लुतं वाराहमेदसि पक्त्वा शष्कुलिक्राः खादन्नारोहेत् षष्टिमङ्गनाः", text: "cūrṇaṃ māṣāttilācchālervidāryāśca sasaindhavam rasena puṇḍrakasyekṣoḥ plutaṃ vārāhamedasi paktvā śaṣkulikrāḥ khādannārohet ṣaṣṭimaṅganāḥ" },
      { type: "verse", number: "68", sanskrit: "मुखप्रियाणां स्निग्धानां फलानां मधुरात्मनाम् फलानामात्मगुप्तायाः शालेर्माषात्तिलात् घृतात्", text: "mukhapriyāṇāṃ snigdhānāṃ phalānāṃ madhurātmanām phalānāmātmaguptāyāḥ śālermāṣāttilāt ghṛtāt" },
      { type: "verse", number: "69", sanskrit: "मुद्गात् गोधूमतश्चापि कुडवं कुडवं पृथक् चूर्णितैर्निस्तुषैस्तैस्तु क्षीरेणालोड्य मर्दितैः पक्वां पूपलिकां खादन् स्त्रीषु हृष्यति वाजिवत्", text: "mudgāt godhūmataścāpi kuḍavaṃ kuḍavaṃ pṛthak cūrṇitairnistuṣaistaistu kṣīreṇāloḍya marditaiḥ pakvāṃ pūpalikāṃ khādan strīṣu hṛṣyati vājivat" },
      { type: "verse", number: "70", sanskrit: "शर्करामाषगोधूमतुगाक्षीरीपयोघृतैः पक्वामुत्कारिकां खादेत् कृकवाकुरसानुपः", text: "śarkarāmāṣagodhūmatugākṣīrīpayoghṛtaiḥ pakvāmutkārikāṃ khādet kṛkavākurasānupaḥ" },
      { type: "verse", number: "71", sanskrit: "मायुरं तैत्तिरं हांसमेवमेव रसं पिबेत् अनेनाश्व इवोदीर्णो बली लिङ्गं समर्पयेत्", text: "māyuraṃ taittiraṃ hāṃsamevameva rasaṃ pibet anenāśva ivodīrṇo balī liṅgaṃ samarpayet" },
      { type: "verse", number: "72", sanskrit: "पिष्ट्वा वराहमांसानि दत्वा मरिचसैन्धवे कोलवद्गुटिकाः कृत्वा तप्ते सर्पिषि वर्त्तयेत्", text: "piṣṭvā varāhamāṃsāni datvā maricasaindhave kolavadguṭikāḥ kṛtvā tapte sarpiṣi varttayet" },
      { type: "verse", number: "73", sanskrit: "वर्त्तनस्तम्भितास्ताश्च प्रक्षेप्याः कौक्कुटे रसे घृताढ्ये गन्धपिशुने दधिदाडिमसारिके", text: "varttanastambhitāstāśca prakṣepyāḥ kaukkuṭe rase ghṛtāḍhye gandhapiśune dadhidāḍimasārike" },
      { type: "verse", number: "74", sanskrit: "यथा न भिन्द्याद्गुटिकास्तथा तं साधयेद्रसम् तं पिबन्भक्षयंस्ताश्च बली बालेयवद्व्रजेत् मांसानि बलयुक्तानि तथान्यान्यपि कल्पयेत्", text: "yathā na bhindyādguṭikāstathā taṃ sādhayedrasam taṃ pibanbhakṣayaṃstāśca balī bāleyavadvrajet māṃsāni balayuktāni tathānyānyapi kalpayet" },
      { type: "verse", number: "75", sanskrit: "माषानंकुरितान्शुद्धान् निस्तुषान्साजहाफलान् घृताढ्ये माहिषरसे दधिदाडिमसारिके", text: "māṣānaṃkuritānśuddhān nistuṣānsājahāphalān ghṛtāḍhye māhiṣarase dadhidāḍimasārike" },
      { type: "verse", number: "76", sanskrit: "प्रक्षिप्य साधयेद्युक्त्या धान्यजीरकनागरैः पीतो भुक्तश्च स रसः कुरुते शुक्रमक्षयम्", text: "prakṣipya sādhayedyuktyā dhānyajīrakanāgaraiḥ pīto bhuktaśca sa rasaḥ kurute śukramakṣayam" },
      { type: "verse", number: "77", sanskrit: "हंसबर्हिणदक्षाण्डान् भृष्टांस्तप्तेन सर्पिषा सुरानुपानान् यः खादेत् स तृप्तस्तर्प्पयेत्स्त्रियः", text: "haṃsabarhiṇadakṣāṇḍān bhṛṣṭāṃstaptena sarpiṣā surānupānān yaḥ khādet sa tṛptastarppayetstriyaḥ" },
      { type: "verse", number: "78", sanskrit: "आर्द्राणि मत्स्यमांसानिशफरीर्वा सुभर्जिताः तप्ते सर्पिषि यः खादेत् स गच्छेत् स्त्रीषु न क्षयम्", text: "ārdrāṇi matsyamāṃsāniśapharīrvā subharjitāḥ tapte sarpiṣi yaḥ khādet sa gacchet strīṣu na kṣayam" },
      { type: "verse", number: "79", sanskrit: "घृतभृष्टान् रसे छागे रोहितान् फलसारिके अनुपीतरसान् सिद्धानपत्यार्थी प्रयोजयेत्", text: "ghṛtabhṛṣṭān rase chāge rohitān phalasārike anupītarasān siddhānapatyārthī prayojayet" },
      { type: "verse", number: "80", sanskrit: "घृतं माषान् सबस्ताण्डान् फलाम्ले माहिषे रसे स्वादौ वा साधयेत् पूतं तद्रसं भर्जयेत् घृते", text: "ghṛtaṃ māṣān sabastāṇḍān phalāmle māhiṣe rase svādau vā sādhayet pūtaṃ tadrasaṃ bharjayet ghṛte" },
      { type: "verse", number: "81", sanskrit: "ईषल्लवणितं युक्तं धान्यजीरकनागरैः पीतः स वृष्यो बल्यश्च बृंहणश्च परं रसः", text: "īṣallavaṇitaṃ yuktaṃ dhānyajīrakanāgaraiḥ pītaḥ sa vṛṣyo balyaśca bṛṃhaṇaśca paraṃ rasaḥ" },
      { type: "verse", number: "82", sanskrit: "चटकांस्तैत्तिरे तद्वत्तित्तिरीन् कौक्कुटे रसे कल्पयेच्छिखिनो हांसे हंसान् वा शिखिजे रसे", text: "caṭakāṃstaittire tadvattittirīn kaukkuṭe rase kalpayecchikhino hāṃse haṃsān vā śikhije rase" },
      { type: "verse", number: "83", sanskrit: "तृप्तिं चटकमांसानां गत्वा योनु पयः पिबेत् प्रभूतकालसंरुद्धाः सन्तर्पयति योषितः", text: "tṛptiṃ caṭakamāṃsānāṃ gatvā yonu payaḥ pibet prabhūtakālasaṃruddhāḥ santarpayati yoṣitaḥ" },
      { type: "verse", number: "84", sanskrit: "घृताढ्यं कुक्वुटं शूल्यं शीतं खादेत् समाक्षिकम् पिबेच्चानन्तरं क्षीरं य इच्छेच्छुक्रमक्षयम्", text: "ghṛtāḍhyaṃ kukvuṭaṃ śūlyaṃ śītaṃ khādet samākṣikam pibeccānantaraṃ kṣīraṃ ya icchecchukramakṣayam" },
      { type: "verse", number: "85", sanskrit: "पिप्पलीलवणैर्युक्तौ बस्ताण्डौ क्षीरसर्पिषा साधितौ भक्षयेद्यस्तु स गच्छेत् प्रमदाशतम्", text: "pippalīlavaṇairyuktau bastāṇḍau kṣīrasarpiṣā sādhitau bhakṣayedyastu sa gacchet pramadāśatam" },
      { type: "verse", number: "86", sanskrit: "बस्ताण्डसिद्धे गोदुग्धे भावितानसकृत्तिलान् यः खादेत्ससितान् गच्छेत् स स्त्राशतमपूववत्", text: "bastāṇḍasiddhe godugdhe bhāvitānasakṛttilān yaḥ khādetsasitān gacchet sa strāśatamapūvavat" },
      { type: "verse", number: "87", sanskrit: "भुक्त्वा यो माषसूपेन घृताड्यं षष्टिकौदनम् पयः पिबति जागर्ति कृत्स्नां रात्रिं स वेगवान्", text: "bhuktvā yo māṣasūpena ghṛtāḍyaṃ ṣaṣṭikaudanam payaḥ pibati jāgarti kṛtsnāṃ rātriṃ sa vegavān" },
      { type: "verse", number: "88", sanskrit: "आत्मगुप्ताफलं माषान् खर्जूराणि शतावरीम् शृङ्गाटकानि मृद्वीका पचेत्तत् प्रसृतोन्मितम्", text: "ātmaguptāphalaṃ māṣān kharjūrāṇi śatāvarīm śṛṅgāṭakāni mṛdvīkā pacettat prasṛtonmitam" },
      { type: "verse", number: "89", sanskrit: "क्षीरप्रस्थं जलप्रस्थमेतत् क्षीरावशेषितम् शुचिना वाससा पूतं योजयेत् प्रसृतैस्त्रिभिः", text: "kṣīraprasthaṃ jalaprasthametat kṣīrāvaśeṣitam śucinā vāsasā pūtaṃ yojayet prasṛtaistribhiḥ" },
      { type: "verse", number: "90", sanskrit: "शर्करायास्तुगाक्षीर्याः सर्पिषो ऽभिनवस्य च तत्पिबेत् क्षौद्रसंयुक्तं भुञ्जानः षष्टिकौदनम् तथा जरापरीतोपि पुत्रैः स परिवार्यते", text: "śarkarāyāstugākṣīryāḥ sarpiṣo 'bhinavasya ca tatpibet kṣaudrasaṃyuktaṃ bhuñjānaḥ ṣaṣṭikaudanam tathā jarāparītopi putraiḥ sa parivāryate" },
      { type: "verse", number: "91", sanskrit: "द्राक्षाखर्जरखर्जूरीमस्तकान्यजहाफलम् पयस्याभीरुमाषांश्च मधुकानि च साधयेत्", text: "drākṣākharjarakharjūrīmastakānyajahāphalam payasyābhīrumāṣāṃśca madhukāni ca sādhayet" },
      { type: "verse", number: "92", sanskrit: "तोयाढके पलांशानि पादशेषेण तेन च क्षीरप्रस्थं पचेत् क्षीरशेषेणाद्यात् घृतान्वितम् षष्टिकान्नं सिताज्येन योगो ऽयं शुक्रकृत् परम्", text: "toyāḍhake palāṃśāni pādaśeṣeṇa tena ca kṣīraprasthaṃ pacet kṣīraśeṣeṇādyāt ghṛtānvitam ṣaṣṭikānnaṃ sitājyena yogo 'yaṃ śukrakṛt param" },
      { type: "verse", number: "93", sanskrit: "जीवकर्षभकौ मेदा जीवन्ती श्रावणीद्वयम् खर्जूरं मधुकं द्राक्षां विदारीं विश्वभेषजम्", text: "jīvakarṣabhakau medā jīvantī śrāvaṇīdvayam kharjūraṃ madhukaṃ drākṣāṃ vidārīṃ viśvabheṣajam" },
      { type: "verse", number: "94", sanskrit: "शृङ्गाटकानि चपला नवं सर्पिःपयो जलम् घृतावशेषितं सिद्धं शर्करामाक्षिकान्वितम्", text: "śṛṅgāṭakāni capalā navaṃ sarpiḥpayo jalam ghṛtāvaśeṣitaṃ siddhaṃ śarkarāmākṣikānvitam" },
      { type: "verse", number: "95", sanskrit: "षष्टिकौदनसंयुक्तमुपयोज्यं यथाबलम् तद्वृष्यं बलकृद्वर्ण्यं कण्ठ्यं देहस्य बृंहणम्", text: "ṣaṣṭikaudanasaṃyuktamupayojyaṃ yathābalam tadvṛṣyaṃ balakṛdvarṇyaṃ kaṇṭhyaṃ dehasya bṛṃhaṇam" },
      { type: "verse", number: "96", sanskrit: "गृष्टिर्बष्कयणी नीरुगूर्ध्वशृङ्गी चतुःस्तनी सान्द्रस्वादुबहुक्षीरा रूपशीलसमन्विता", text: "gṛṣṭirbaṣkayaṇī nīrugūrdhvaśṛṅgī catuḥstanī sāndrasvādubahukṣīrā rūpaśīlasamanvitā" },
      { type: "verse", number: "97", sanskrit: "इक्षुभिर्माषपर्णेन या सुपुष्टार्जुनेन वा तत्क्षीरं ससिताक्षौद्रघृतं पुत्र्यं रतिप्रदम्", text: "ikṣubhirmāṣaparṇena yā supuṣṭārjunena vā tatkṣīraṃ sasitākṣaudraghṛtaṃ putryaṃ ratipradam" },
      { type: "verse", number: "98", sanskrit: "शुक्रलैर्जीवनीयाख्यैर्बृंहणैर्बलवर्द्धनैः वयसः स्थापनैश्चेतत् पयः सिद्धं पृथक्पृथक्", text: "śukralairjīvanīyākhyairbṛṃhaṇairbalavarddhanaiḥ vayasaḥ sthāpanaiścetat payaḥ siddhaṃ pṛthakpṛthak" },
      { type: "verse", number: "99", sanskrit: "युक्तं गोधूमचूर्णेन सघृतक्षौद्रशर्करम् पर्यायेणोपयोक्तव्यमिच्छता शुक्रमक्षयम्", text: "yuktaṃ godhūmacūrṇena saghṛtakṣaudraśarkaram paryāyeṇopayoktavyamicchatā śukramakṣayam" },
      { type: "verse", number: "100", sanskrit: "मेदां पयस्यां जीवन्तीं विदारीं कण्टकारिकाम् माषान् श्वदंष्ट्रां क्षीरीकां गोधूमान् शालिषष्टिकान्", text: "medāṃ payasyāṃ jīvantīṃ vidārīṃ kaṇṭakārikām māṣān śvadaṃṣṭrāṃ kṣīrīkāṃ godhūmān śāliṣaṣṭikān" },
      { type: "verse", number: "101", sanskrit: "तत्क्षीरेर्द्धोदके सिद्धान् कार्षिकानाढकोन्मिते विसर्जयेत्पयश्शेषं तत्पूतं क्षौद्रसर्पिषा सितया च युतं पीत्वा वृद्धोपि तरुणायते", text: "tatkṣīrerddhodake siddhān kārṣikānāḍhakonmite visarjayetpayaśśeṣaṃ tatpūtaṃ kṣaudrasarpiṣā sitayā ca yutaṃ pītvā vṛddhopi taruṇāyate" },
      { type: "verse", number: "102", sanskrit: "मण्डलैर्जातरूपस्य सुतप्तैस्तत्पयः शृतम् सिद्धं पुंसवनं वृष्यं ससिताघृतमाक्षिकम् रूप्यायस्ताम्नसीसानामयमेव पृथग्विधिः", text: "maṇḍalairjātarūpasya sutaptaistatpayaḥ śṛtam siddhaṃ puṃsavanaṃ vṛṣyaṃ sasitāghṛtamākṣikam rūpyāyastāmnasīsānāmayameva pṛthagvidhiḥ" },
      { type: "verse", number: "103", sanskrit: "चूर्णिताः पिप्पलीस्त्रिंशत् प्रकुञ्चे तैलसर्पिषोः भृष्टाः सशर्कराक्षौद्राः क्षीरेणालोडिताः पिबेत् अश्नंश्च षष्टिकं क्षीरसर्पिर्भ्यां वाजिवद्भवेत्", text: "cūrṇitāḥ pippalīstriṃśat prakuñce tailasarpiṣoḥ bhṛṣṭāḥ saśarkarākṣaudrāḥ kṣīreṇāloḍitāḥ pibet aśnaṃśca ṣaṣṭikaṃ kṣīrasarpirbhyāṃ vājivadbhavet" },
      { type: "verse", number: "104", sanskrit: "चन्द्रांशुशुभ्रं पयसा घृताढ्यं षष्टिकौदनम् शर्करामधुसंयुक्तं भुञ्जानो ना वृषायते", text: "candrāṃśuśubhraṃ payasā ghṛtāḍhyaṃ ṣaṣṭikaudanam śarkarāmadhusaṃyuktaṃ bhuñjāno nā vṛṣāyate" },
      { type: "verse", number: "105", sanskrit: "दध्नः सरेण सघृतो भक्षितः षष्टिकौदनः सैलातुगोषणक्षौद्रः शर्कराढ्येन शुक्रकृत्", text: "dadhnaḥ sareṇa saghṛto bhakṣitaḥ ṣaṣṭikaudanaḥ sailātugoṣaṇakṣaudraḥ śarkarāḍhyena śukrakṛt" },
      { type: "verse", number: "106", sanskrit: "अध्यण्डामार्षभींचैव स्वयड्गुप्ताफलानि च पादलेपं नरः कृत्वा निशि वेगैर्न हीयते", text: "adhyaṇḍāmārṣabhīṃcaiva svayaḍguptāphalāni ca pādalepaṃ naraḥ kṛtvā niśi vegairna hīyate" },
      { type: "verse", number: "107", sanskrit: "वर्षाभूमूलमृद्वीकास्वयङ्गुप्ताफलानि च सिद्धश्चरणलेपोयं भुवं पद्भ्यां तु न स्पृशेत्", text: "varṣābhūmūlamṛdvīkāsvayaṅguptāphalāni ca siddhaścaraṇalepoyaṃ bhuvaṃ padbhyāṃ tu na spṛśet" },
      { type: "verse", number: "108", sanskrit: "घृतक्षीराशनो नित्यं निर्व्याधिर्नित्यगो युवा सङ्कल्पप्रवणो इत्यं नरः स्त्रीषु वृषायते", text: "ghṛtakṣīrāśano nityaṃ nirvyādhirnityago yuvā saṅkalpapravaṇo ityaṃ naraḥ strīṣu vṛṣāyate" },
      { type: "verse", number: "109", sanskrit: "आत्मगुप्ताफलं माषा गोधूमः शालिषष्टिकम् इक्षुरिक्षुरकः क्षीरं क्षौद्रं द्राक्षा सितोपला", text: "ātmaguptāphalaṃ māṣā godhūmaḥ śāliṣaṣṭikam ikṣurikṣurakaḥ kṣīraṃ kṣaudraṃ drākṣā sitopalā" },
      { type: "verse", number: "110", sanskrit: "उच्चटा शरमूलानि विदारी सशतावरी जीवनीयानि स्वर्जूरं मोचचोचफलानि च", text: "uccaṭā śaramūlāni vidārī saśatāvarī jīvanīyāni svarjūraṃ mocacocaphalāni ca" },
      { type: "verse", number: "111", sanskrit: "एभिर्भक्ष्याणि पेयानि लेह्यानि च घृतानि च नित्यमासेवमानस्य स्त्रीषु हर्षो विवर्द्धते", text: "ebhirbhakṣyāṇi peyāni lehyāni ca ghṛtāni ca nityamāsevamānasya strīṣu harṣo vivarddhate" },
      { type: "verse", number: "112", sanskrit: "जीवनीयघृतक्षीरमधुतैलसितारसैः रसक्षीराशिनः क्षिप्रं वृषं कुर्वन्ति बस्तयः", text: "jīvanīyaghṛtakṣīramadhutailasitārasaiḥ rasakṣīrāśinaḥ kṣipraṃ vṛṣaṃ kurvanti bastayaḥ" },
      { type: "verse", number: "113", sanskrit: "सिद्धबस्तिविकल्पोक्तान् बलशुक्रसुतप्रदान् युञ्जीत बस्तीन् पुत्रार्थी पुत्रकामोदितं च यत्", text: "siddhabastivikalpoktān balaśukrasutapradān yuñjīta bastīn putrārthī putrakāmoditaṃ ca yat" },
      { type: "verse", number: "114", sanskrit: "यत्किञ्चिन्मधुरं स्निग्धं बृंहणं बलवर्द्धनम् मनसो हर्षणं यच्च तत्सव वृष्यमुच्यते", text: "yatkiñcinmadhuraṃ snigdhaṃ bṛṃhaṇaṃ balavarddhanam manaso harṣaṇaṃ yacca tatsava vṛṣyamucyate" },
      { type: "verse", number: "115", sanskrit: "द्रव्यैरेवंविधैस्तस्मात् भावितः प्रमदां व्रजेत् आत्मवेगेन चोदीर्णः स्रीगुणैश्च प्रहर्षितः", text: "dravyairevaṃvidhaistasmāt bhāvitaḥ pramadāṃ vrajet ātmavegena codīrṇaḥ srīguṇaiśca praharṣitaḥ" },
      { type: "verse", number: "116", sanskrit: "इष्टाह्येकैकशोप्यर्था हर्षप्रीतिकराः परम् किं पुनः स्त्रीशरीरे ये सङ्घघातेन प्रतिष्ठिताः", text: "iṣṭāhyekaikaśopyarthā harṣaprītikarāḥ param kiṃ punaḥ strīśarīre ye saṅghaghātena pratiṣṭhitāḥ" },
      { type: "verse", number: "117", sanskrit: "रुचिभेदेन लोकस्य दैवयोगाञ्च योषिताम् तं तं प्राप्य विवर्द्धन्ते नरं रूपादयो गुणाः", text: "rucibhedena lokasya daivayogāñca yoṣitām taṃ taṃ prāpya vivarddhante naraṃ rūpādayo guṇāḥ" },
      { type: "verse", number: "118", sanskrit: "तस्माद्या यस्य हृदयं विशतीव वराङ्गना तुल्यस्वभावा या हारिमृजारूपगुणान्विता", text: "tasmādyā yasya hṛdayaṃ viśatīva varāṅganā tulyasvabhāvā yā hārimṛjārūpaguṇānvitā" },
      { type: "verse", number: "119", sanskrit: "पाशभूतैर्वहन्त्यङ्गैर्लावण्यमिव मूर्तिमत् आलपन्त्यमृतेनेव या गात्राणि निषिञ्चति", text: "pāśabhūtairvahantyaṅgairlāvaṇyamiva mūrtimat ālapantyamṛteneva yā gātrāṇi niṣiñcati" },
      { type: "verse", number: "120", sanskrit: "पिबन्तीव च पश्यन्ती स्पृशन्ती लिम्पतीव या नित्यमुत्सवभूता या या समानमनःशया", text: "pibantīva ca paśyantī spṛśantī limpatīva yā nityamutsavabhūtā yā yā samānamanaḥśayā" },
      { type: "verse", number: "121", sanskrit: "नयत्युत्सुकतां चेतो नित्यं सन्निहितापि या यया वियुक्तो निःस्त्रीकमरतिर्मन्यते जगत्", text: "nayatyutsukatāṃ ceto nityaṃ sannihitāpi yā yayā viyukto niḥstrīkamaratirmanyate jagat" },
      { type: "verse", number: "122", sanskrit: "प्रगल्भा रीतसङ्ग्रामे स्वस्था लज्जामयी च या बहुशोपि च यां गत्वा तत्पूर्वमिव गच्छति", text: "pragalbhā rītasaṅgrāme svasthā lajjāmayī ca yā bahuśopi ca yāṃ gatvā tatpūrvamiva gacchati" },
      { type: "verse", number: "123", sanskrit: "चरितैर्निर्विकारा या विकारैरिव निर्मिता कान्तानुवृत्तिपरमा सा स्त्री वृष्ट्यतमा मता", text: "caritairnirvikārā yā vikārairiva nirmitā kāntānuvṛttiparamā sā strī vṛṣṭyatamā matā" },
      { type: "verse", number: "124", sanskrit: "अभ्यञ्जनोद्वर्तनसेकगन्धस्रक्चित्रवस्त्राभरणप्रकाराः सुगन्धिपुष्पोत्कररेणुकीर्णा मृदुर्मनोज्ञा विपुला च शय्या", text: "abhyañjanodvartanasekagandhasrakcitravastrābharaṇaprakārāḥ sugandhipuṣpotkarareṇukīrṇā mṛdurmanojñā vipulā ca śayyā" },
      { type: "verse", number: "125", sanskrit: "प्राज्ञाः कलाज्ञा वशगा विनीताः प्रियंवदाः प्रीतिकरा वयस्याः विस्रम्भसत्वप्रकृतिक्रियैक्याच्छरीरमात्रेण पृथक्त्वभूताः", text: "prājñāḥ kalājñā vaśagā vinītāḥ priyaṃvadāḥ prītikarā vayasyāḥ visrambhasatvaprakṛtikriyaikyāccharīramātreṇa pṛthaktvabhūtāḥ" },
      { type: "verse", number: "126", sanskrit: "कान्ता वनान्ताः परपुष्टघुष्टा रम्याः स्रवन्त्यः सततं स्रवन्त्यः मद्यं मदामोदकरं विशेषाध्दृद्या प्रसन्ना सुरभिः प्रसन्ना", text: "kāntā vanāntāḥ parapuṣṭaghuṣṭā ramyāḥ sravantyaḥ satataṃ sravantyaḥ madyaṃ madāmodakaraṃ viśeṣādhdṛdyā prasannā surabhiḥ prasannā" },
      { type: "verse", number: "127", sanskrit: "शकाङ्गनागण्डतलाभिपाण्डुताम्बुलपत्रं परिवारशोभि प्रसाधनं स्त्रीमुखपङ्कजानां यदायुधं मूर्तमिवात्मजस्य", text: "śakāṅganāgaṇḍatalābhipāṇḍutāmbulapatraṃ parivāraśobhi prasādhanaṃ strīmukhapaṅkajānāṃ yadāyudhaṃ mūrtamivātmajasya" },
      { type: "verse", number: "128", sanskrit: "हिमाचलोद्धूनितदुग्धसिन्धुसमुद्भवत्फेनचयावदातम् सौधं सुधाशुभ्रतराः कराश्च चन्द्रस्य कुर्वन्ति परं वृषत्वम्", text: "himācaloddhūnitadugdhasindhusamudbhavatphenacayāvadātam saudhaṃ sudhāśubhratarāḥ karāśca candrasya kurvanti paraṃ vṛṣatvam" },
      { type: "verse", number: "129", sanskrit: "बन्धेन पूर्वोपहितेन पुंसः खिन्नस्य वृत्तिः करणान्तरेण संवाहनं स्पर्शसुखैः करैश्च करोत्यपूर्वामिव मन्मथेच्छाम्", text: "bandhena pūrvopahitena puṃsaḥ khinnasya vṛttiḥ karaṇāntareṇa saṃvāhanaṃ sparśasukhaiḥ karaiśca karotyapūrvāmiva manmathecchām" },
      { type: "verse", number: "130", sanskrit: "प्रायोगिकाधिकरणोदिताचित्रचेष्टासंशीलनोद्भवदनल्परसार्द्रचित्तः वृष्योपयोगपरिबृंहितदेहधातुर्नारीमनांसि वशमानयति प्रसह्य", text: "prāyogikādhikaraṇoditācitraceṣṭāsaṃśīlanodbhavadanalparasārdracittaḥ vṛṣyopayogaparibṛṃhitadehadhāturnārīmanāṃsi vaśamānayati prasahya" },
      { type: "verse", number: "131", sanskrit: "तस्मान्नित्यं स्त्रीषु वाञ्छन् प्रियत्वं वृष्यैर्योगैर्जातकामो ऽपि कामी सत्व्ंअ सात्म्यं देशकालौ च बुध्वा चातुष्षष्टे चेष्टिते व्याप्रियेत", text: "tasmānnityaṃ strīṣu vāñchan priyatvaṃ vṛṣyairyogairjātakāmo 'pi kāmī satvṃa sātmyaṃ deśakālau ca budhvā cātuṣṣaṣṭe ceṣṭite vyāpriyeta" },
      { type: "verse", number: "132", sanskrit: "वलयस्वनसङ्कुलमुष्टिरवद्विगुणीकृतमेखलिकानिनदः चलनूपुरशब्दयुतो ऽपि मुहुः शममावहते न रतातिशयः", text: "valayasvanasaṅkulamuṣṭiravadviguṇīkṛtamekhalikāninadaḥ calanūpuraśabdayuto 'pi muhuḥ śamamāvahate na ratātiśayaḥ" },
      { type: "verse", number: "133", sanskrit: "सर्वार्थसिद्धिः प्रथमोनुरागः शृङ्गारगान्धर्वकथाविशेषाः सीत्कारगर्भं हसितं सहावं छिन्नाक्षरं विभ्रमवच्च गीतम्", text: "sarvārthasiddhiḥ prathamonurāgaḥ śṛṅgāragāndharvakathāviśeṣāḥ sītkāragarbhaṃ hasitaṃ sahāvaṃ chinnākṣaraṃ vibhramavacca gītam" },
      { type: "verse", number: "134", sanskrit: "सव्याजसन्दीर्शतचारुगात्रं वृत्तं प्रियाणामवलोकितं च चूताङ्कुरं पुष्पफलं यथर्तु विद्युत्वदुद्योतितगर्जितानि", text: "savyājasandīrśatacārugātraṃ vṛttaṃ priyāṇāmavalokitaṃ ca cūtāṅkuraṃ puṣpaphalaṃ yathartu vidyutvadudyotitagarjitāni" },
      { type: "verse", number: "135", sanskrit: "विहङ्गभृङ्गस्तनितानुयातं स्त्रीकूजितं भूषणशिञ्जितानि काले यथास्वं वपुषश्च शुद्धिः सङ्कल्पयोनेर्धुरमुद्वहन्ति", text: "vihaṅgabhṛṅgastanitānuyātaṃ strīkūjitaṃ bhūṣaṇaśiñjitāni kāle yathāsvaṃ vapuṣaśca śuddhiḥ saṅkalpayonerdhuramudvahanti" },
      { type: "verse", number: "136", sanskrit: "स्रोतस्सु शुद्वेष्वमले शरीरे वृष्यं यदाद्यं मितमत्ति काले वृषायते तेन परं मनुष्यस्तद्बृंहणं देहबलप्रदं च", text: "srotassu śudveṣvamale śarīre vṛṣyaṃ yadādyaṃ mitamatti kāle vṛṣāyate tena paraṃ manuṣyastadbṛṃhaṇaṃ dehabalapradaṃ ca" },
      { type: "verse", number: "137", sanskrit: "तस्मात् पुरा शोधनमेव कार्यं बलानुरूपं न च वृष्ययोगाः सिध्यन्ति देहे कलुषे प्रयुक्ताः क्लिष्टे यथा वाससि रागयोगाः", text: "tasmāt purā śodhanameva kāryaṃ balānurūpaṃ na ca vṛṣyayogāḥ sidhyanti dehe kaluṣe prayuktāḥ kliṣṭe yathā vāsasi rāgayogāḥ" },
      { type: "verse", number: "138", sanskrit: "उपदिष्टे विचित्रे ऽस्मिन् वक्तव्यार्थानुरोधतः कर्तव्यमेवकर्तव्यं प्राणाबाधे ऽपि नेतरत्", text: "upadiṣṭe vicitre 'smin vaktavyārthānurodhataḥ kartavyamevakartavyaṃ prāṇābādhe 'pi netarat" },
      { type: "verse", number: "139", sanskrit: "एतत् स्वरूपं शास्त्रस्य यद्व्यापित्वेन वर्ण्यते स्पृशति न्यूनतादोषो महानव्यापिनि ध्रुवम्", text: "etat svarūpaṃ śāstrasya yadvyāpitvena varṇyate spṛśati nyūnatādoṣo mahānavyāpini dhruvam" },
      { type: "verse", number: "140", sanskrit: "वीर्यहीनैरसम्पूर्णैः प्रयोगैरपि भूषितम् अर्थानतन्त्रयत्तन्त्रं तन्त्रतामाप्नुयात् कथम्", text: "vīryahīnairasampūrṇaiḥ prayogairapi bhūṣitam arthānatantrayattantraṃ tantratāmāpnuyāt katham" },
      { type: "verse", number: "141", sanskrit: "हंसबर्हिणदक्षाण्डा यद्यप्यत्यर्थशुक्रलाः मुनयः सदया ब्रूयुस्तान्योगेष्वन्यथा कथम्", text: "haṃsabarhiṇadakṣāṇḍā yadyapyatyarthaśukralāḥ munayaḥ sadayā brūyustānyogeṣvanyathā katham" },
      { type: "verse", number: "142", sanskrit: "कथं वा सर्वएवैते योगा रागाग्निदीपनाः क्लिष्टसङ्कल्पजननाः प्रोक्ताः संसारवर्द्धनाः", text: "kathaṃ vā sarvaevaite yogā rāgāgnidīpanāḥ kliṣṭasaṅkalpajananāḥ proktāḥ saṃsāravarddhanāḥ" },
      { type: "verse", number: "143", sanskrit: "त्रिकालदर्शिभिर्दिव्यैः सत्वदोषषिवर्जितैः पूर्वाचार्यैः कृतं वर्त्म को लङ्घयित्मुमर्हति", text: "trikāladarśibhirdivyaiḥ satvadoṣaṣivarjitaiḥ pūrvācāryaiḥ kṛtaṃ vartma ko laṅghayitmumarhati" },
      { type: "verse", number: "144", sanskrit: "प्रक्रान्ते सर्वथा सर्वमुक्तं भवति सूदितम् नाहि लेशाभिधानेन लभ्यः सर्वार्थसङ्ग्रहः", text: "prakrānte sarvathā sarvamuktaṃ bhavati sūditam nāhi leśābhidhānena labhyaḥ sarvārthasaṅgrahaḥ" },
      { type: "verse", number: "145", sanskrit: "तथा च गर्दभीक्षीरं मांसमश्वस्य हस्तिनाम् मद्दासागरतोयं च प्रोक्तं निरुपयोग्यपि", text: "tathā ca gardabhīkṣīraṃ māṃsamaśvasya hastinām maddāsāgaratoyaṃ ca proktaṃ nirupayogyapi" },
      { type: "verse", number: "146", sanskrit: "अद्यत्वे ऽपि विशेषेण भूरितन्त्रार्थसङ्ग्रहात् सङ्ग्रहाद्यन्नबुध्येत तज्ज्ञानमतिदुर्लभम्", text: "adyatve 'pi viśeṣeṇa bhūritantrārthasaṅgrahāt saṅgrahādyannabudhyeta tajjñānamatidurlabham" },
      { type: "verse", number: "147", sanskrit: "यथा प्रतिज्ञातमिति क्रमेण वेदोयमष्टाङ्गनिधेर्निबद्धः अभ्यस्यतो मार्गमिवार्यसत्यं सञ्जायते स्वार्थपरार्थसिद्धिः", text: "yathā pratijñātamiti krameṇa vedoyamaṣṭāṅganidhernibaddhaḥ abhyasyato mārgamivāryasatyaṃ sañjāyate svārthaparārthasiddhiḥ" },
      { type: "verse", number: "148", sanskrit: "पितामहमुखोद्गीर्णमित्यायुर्वेदवाङ्मयम् जीवितारोग्यधर्मार्थसुखगौरवकीर्त्तिकृत्", text: "pitāmahamukhodgīrṇamityāyurvedavāṅmayam jīvitārogyadharmārthasukhagauravakīrttikṛt" },
      { type: "verse", number: "149", sanskrit: "अलङ्कृतं युक्तिपदैः सद्रत्नैरिव काञ्चनम् षट्त्रिंशतार्थदुर्गेषु भिषजां सङ्क्रमैरिव", text: "alaṅkṛtaṃ yuktipadaiḥ sadratnairiva kāñcanam ṣaṭtriṃśatārthadurgeṣu bhiṣajāṃ saṅkramairiva" },
      { type: "verse", number: "150", sanskrit: "तत्राधिकरणं योगो हेत्वर्थोर्थः पदस्य च प्रदेशोद्देशनिर्देशवाक्यशेषाः प्रयोजनम्", text: "tatrādhikaraṇaṃ yogo hetvarthorthaḥ padasya ca pradeśoddeśanirdeśavākyaśeṣāḥ prayojanam" },
      { type: "verse", number: "151", sanskrit: "उपदेशापदेशातिदेशार्थापत्तिनिर्णयाः प्रसङ्गैकान्तनैकान्ताः सापवर्गो विपर्ययः", text: "upadeśāpadeśātideśārthāpattinirṇayāḥ prasaṅgaikāntanaikāntāḥ sāpavargo viparyayaḥ" },
      { type: "verse", number: "152", sanskrit: "पूर्वपक्षविधानानुमतव्याख्यानसंशयाः अतीतानागतापेक्षा स्वसंज्ञोह्य समुच्चयाः", text: "pūrvapakṣavidhānānumatavyākhyānasaṃśayāḥ atītānāgatāpekṣā svasaṃjñohya samuccayāḥ" },
      { type: "verse", number: "153", sanskrit: "निदर्शनं निर्वचनं नियोगो ऽथ विकल्पनम् प्रत्युत्सारस्तथोद्धारः सम्भवस्तन्त्रयुक्तयः", text: "nidarśanaṃ nirvacanaṃ niyogo 'tha vikalpanam pratyutsārastathoddhāraḥ sambhavastantrayuktayaḥ" },
      { type: "verse", number: "154", sanskrit: "सरसः सुप्तपद्मस्य रविदीधितयो यथा यथा गृहस्य दीपाभास्तथा तन्त्रस्य युक्तयः", text: "sarasaḥ suptapadmasya ravidīdhitayo yathā yathā gṛhasya dīpābhāstathā tantrasya yuktayaḥ" },
      { type: "verse", number: "155", sanskrit: "अधीयानो ऽपि तन्त्राणि तन्त्रयुक्त्यविचक्षणः नाधिगच्छति तन्त्रार्थमर्थं भाग्यक्षये यथा", text: "adhīyāno 'pi tantrāṇi tantrayuktyavicakṣaṇaḥ nādhigacchati tantrārthamarthaṃ bhāgyakṣaye yathā" },
      { type: "verse", number: "156", sanskrit: "वाक्यार्थयोजनोदता युक्तयस्त्विष्टसिद्धिदाः असद्वादिप्रयुक्तानां वाक्यानां प्रतिषेधकाः", text: "vākyārthayojanodatā yuktayastviṣṭasiddhidāḥ asadvādiprayuktānāṃ vākyānāṃ pratiṣedhakāḥ" },
      { type: "verse", number: "157", sanskrit: "लीनव्यत्यासलेशोक्तिगदितानां प्रकाशकाः वाक्यन्यायोदधेः सारं गृहीत्वैवं व्यवस्थिताः", text: "līnavyatyāsaleśoktigaditānāṃ prakāśakāḥ vākyanyāyodadheḥ sāraṃ gṛhītvaivaṃ vyavasthitāḥ" },
      { type: "verse", number: "158", sanskrit: "एतदागमसिद्धत्वात् प्रत्यक्षफलदर्शनात् प्रयोज्यं मन्त्रवत्तन्त्रं तन्त्रज्ञानविशारदैः", text: "etadāgamasiddhatvāt pratyakṣaphaladarśanāt prayojyaṃ mantravattantraṃ tantrajñānaviśāradaiḥ" },
      { type: "verse", number: "159", sanskrit: "पित्तामहेन लोकस्य स्मृत्वा तदिदमव्ययम् अकालमृत्युरक्षार्थमलौहं वर्म निर्मितम्", text: "pittāmahena lokasya smṛtvā tadidamavyayam akālamṛtyurakṣārthamalauhaṃ varma nirmitam" },
      { type: "verse", number: "160", sanskrit: "सुज्ञातमेतदमृतं स्वस्थास्वस्थसुखास्पदम् यथेप्सितफलाशेषपुरुषार्थप्रसाधनम्", text: "sujñātametadamṛtaṃ svasthāsvasthasukhāspadam yathepsitaphalāśeṣapuruṣārthaprasādhanam" },
      { type: "verse", number: "161", sanskrit: "इदं शास्त्रमदृष्टीनामेवमालोककार्यपि मण्डलं भास्करस्येव न प्रकाशाय जायते", text: "idaṃ śāstramadṛṣṭīnāmevamālokakāryapi maṇḍalaṃ bhāskarasyeva na prakāśāya jāyate" },
      { type: "verse", number: "162", sanskrit: "ध्रुवं वैद्येषु कल्याणमायुर्वेदानुसारिषु इतरेष्वितरच्छत्रविषज्वलनकर्मसु", text: "dhruvaṃ vaidyeṣu kalyāṇamāyurvedānusāriṣu itareṣvitaracchatraviṣajvalanakarmasu" },
      { type: "verse", number: "163", sanskrit: "कुर्यात् प्रयुक्तं शस्त्रादि सशेषमपि रोगिणम् न त्वेवं भेषजं मोहादनालोचितयोजितम्", text: "kuryāt prayuktaṃ śastrādi saśeṣamapi rogiṇam na tvevaṃ bheṣajaṃ mohādanālocitayojitam" },
      { type: "verse", number: "164", sanskrit: "सदा दोषौषधादीनि वीक्ष्य द्वादश तत्वतः कुर्याच्चिकित्सितं प्राज्ञो न योगैरेव केवलैः", text: "sadā doṣauṣadhādīni vīkṣya dvādaśa tatvataḥ kuryāccikitsitaṃ prājño na yogaireva kevalaiḥ" },
      { type: "verse", number: "165", sanskrit: "मात्रादि सम्यगज्ञात्वा यदृच्छाप्रतिपादितः हिनस्ति व्याधितं योगो घृतमाक्षिकयोरिव", text: "mātrādi samyagajñātvā yadṛcchāpratipāditaḥ hinasti vyādhitaṃ yogo ghṛtamākṣikayoriva" },
      { type: "verse", number: "166", sanskrit: "दृष्ट्वा विषेष्यमृततां घृतादौ मारणात्मताम् शास्त्रतत्वं न विज्ञाय स दुरात्मा चिकित्सति", text: "dṛṣṭvā viṣeṣyamṛtatāṃ ghṛtādau māraṇātmatām śāstratatvaṃ na vijñāya sa durātmā cikitsati" },
      { type: "verse", number: "167", sanskrit: "सुगीतश्चैष कस्यापि महाश्लोको महात्मनः वैद्याश्चाश्रुतशास्त्रार्था मूर्खाश्च प्रभाविष्णवः अकालमृत्यवो ह्येते विचरन्ति महीतले", text: "sugītaścaiṣa kasyāpi mahāśloko mahātmanaḥ vaidyāścāśrutaśāstrārthā mūrkhāśca prabhāviṣṇavaḥ akālamṛtyavo hyete vicaranti mahītale" },
      { type: "verse", number: "168", sanskrit: "लोभयन्त्यातुरं मूढा ये चित्रैः कर्मकौशलैः तेभ्यो रक्षेत्सदात्मानमात्मा यस्मात् सुदुर्लभः", text: "lobhayantyāturaṃ mūḍhā ye citraiḥ karmakauśalaiḥ tebhyo rakṣetsadātmānamātmā yasmāt sudurlabhaḥ" },
      { type: "verse", number: "169", sanskrit: "ते ध्रुणाक्षरवत्कञ्चिदुत्तार्य नियतायुषम् घ्नन्ति वैद्याभिमानेन शतान्यनियतायुषाम्", text: "te dhruṇākṣaravatkañciduttārya niyatāyuṣam ghnanti vaidyābhimānena śatānyaniyatāyuṣām" },
      { type: "verse", number: "170", sanskrit: "रोगार्तस्य विषण्णस्य यत्नलभ्यसुखायुषः अवैद्यो निर्घृणःक्रूरो यः करोति भिषग्जितम्", text: "rogārtasya viṣaṇṇasya yatnalabhyasukhāyuṣaḥ avaidyo nirghṛṇaḥkrūro yaḥ karoti bhiṣagjitam" },
      { type: "verse", number: "171", sanskrit: "पापस्य मृत्युदूतस्य दुर्मतेस्त्यक्तधर्मणः नरो नरकपाती स्यात्तस्य सम्भाषणादपि", text: "pāpasya mṛtyudūtasya durmatestyaktadharmaṇaḥ naro narakapātī syāttasya sambhāṣaṇādapi" },
      { type: "verse", number: "172", sanskrit: "अतन्त्रीकृततन्त्रार्थः शास्त्रमात्रोपजीविनः राज्ञां प्रमादाद्राष्ट्राणि चरन्ति व्याधवृत्तयः", text: "atantrīkṛtatantrārthaḥ śāstramātropajīvinaḥ rājñāṃ pramādādrāṣṭrāṇi caranti vyādhavṛttayaḥ" },
      { type: "verse", number: "173", sanskrit: "तान् कालपाशसदृशान् वर्जयेच्छास्त्रदूषकान् सेवेत शमविज्ञानज्ञानपूर्णान् भिषक्तमान्", text: "tān kālapāśasadṛśān varjayecchāstradūṣakān seveta śamavijñānajñānapūrṇān bhiṣaktamān" },
      { type: "verse", number: "174", sanskrit: "अन्नपानानि पथ्यानि व्याधिनिर्घातमौषधम् रसायनानि वृष्याणि प्राप्यन्ते वैद्यसंश्रयात्", text: "annapānāni pathyāni vyādhinirghātamauṣadham rasāyanāni vṛṣyāṇi prāpyante vaidyasaṃśrayāt" },
      { type: "verse", number: "175", sanskrit: "अराजका यथा देशा भर्तृहीना यथा गृहाः आतुराद्यास्तथा पादाः शोच्या वैद्यानधिष्ठिताः", text: "arājakā yathā deśā bhartṛhīnā yathā gṛhāḥ āturādyāstathā pādāḥ śocyā vaidyānadhiṣṭhitāḥ" },
      { type: "verse", number: "176", sanskrit: "प्राणाचार्यं बुधस्तस्माद्दयालुं विजितेन्द्रियम् अश्विनाविव देवेन्द्रः पूजयेदादृतः सदा", text: "prāṇācāryaṃ budhastasmāddayāluṃ vijitendriyam aśvināviva devendraḥ pūjayedādṛtaḥ sadā" },
      { type: "verse", number: "177", sanskrit: "यज्ञस्य हि शिरश्छिन्नमश्विभ्यां सन्धितं पुनः पातिता दशनाः पूष्णो भगस्य च विलोचने", text: "yajñasya hi śiraśchinnamaśvibhyāṃ sandhitaṃ punaḥ pātitā daśanāḥ pūṣṇo bhagasya ca vilocane" },
      { type: "verse", number: "178", sanskrit: "राजयक्ष्मार्दितश्चन्द्रस्ताभ्यामेव चिकित्सितः सोमान्निपतितो वज्री भुजस्तम्भे च दारुणे", text: "rājayakṣmārditaścandrastābhyāmeva cikitsitaḥ somānnipatito vajrī bhujastambhe ca dāruṇe" },
      { type: "verse", number: "179", sanskrit: "भार्गवश्चवनः कामी वृद्धः सन् विकृतिं गतः वीर्यवर्णबलोपेतः कृतस्ताभ्यां पुनर्युवा", text: "bhārgavaścavanaḥ kāmī vṛddhaḥ san vikṛtiṃ gataḥ vīryavarṇabalopetaḥ kṛtastābhyāṃ punaryuvā" },
      { type: "verse", number: "180", sanskrit: "एभिश्चान्यैश्च बहुभिः कर्माभीर्भिषगुत्तमौ बभूवतुर्भृशं पूज्याविन्द्रादीनां महात्मनाम्", text: "ebhiścānyaiśca bahubhiḥ karmābhīrbhiṣaguttamau babhūvaturbhṛśaṃ pūjyāvindrādīnāṃ mahātmanām" },
      { type: "verse", number: "181", sanskrit: "अश्विभ्यां सहितः सोमं प्रातः पिबति वासवः सौत्रामण्यां च भगवानश्विभ्यां सह मोदते", text: "aśvibhyāṃ sahitaḥ somaṃ prātaḥ pibati vāsavaḥ sautrāmaṇyāṃ ca bhagavānaśvibhyāṃ saha modate" },
      { type: "verse", number: "182", sanskrit: "अश्विनोः कल्प्यते भागो यज्ञेषु ब्राह्मणैरपि अश्विनावग्निरिन्द्रश्च वेदेषु सुतरां स्तुताः", text: "aśvinoḥ kalpyate bhāgo yajñeṣu brāhmaṇairapi aśvināvagnirindraśca vedeṣu sutarāṃ stutāḥ" },
      { type: "verse", number: "183", sanskrit: "वैद्यवित्यश्विनौ तस्मात् पूज्येते विबुधैरपि अजरैरमरैर्नित्यं सुखितैरेवमादृतैः", text: "vaidyavityaśvinau tasmāt pūjyete vibudhairapi ajarairamarairnityaṃ sukhitairevamādṛtaiḥ" },
      { type: "verse", number: "184", sanskrit: "व्याधिमृत्युजराग्रस्तैर्दुःखप्रायैः सुखार्थिभिः किं पुनर्भिषजो मर्त्यैः पूज्याः स्युर्नातिशक्तितः", text: "vyādhimṛtyujarāgrastairduḥkhaprāyaiḥ sukhārthibhiḥ kiṃ punarbhiṣajo martyaiḥ pūjyāḥ syurnātiśaktitaḥ" },
      { type: "verse", number: "185", sanskrit: "शीलवान् मतिमान् युक्तो द्विजातिर्वेदपारगः प्राणिभिः पितृवत्पूज्यः प्राणाचार्यः स हि स्मृतः", text: "śīlavān matimān yukto dvijātirvedapāragaḥ prāṇibhiḥ pitṛvatpūjyaḥ prāṇācāryaḥ sa hi smṛtaḥ" },
      { type: "verse", number: "186", sanskrit: "विद्यासमाप्तौ भिषजां द्वितीया जातिरुच्यते न वैद्यो वैद्यशब्दं हि लभते पूर्वजन्मना", text: "vidyāsamāptau bhiṣajāṃ dvitīyā jātirucyate na vaidyo vaidyaśabdaṃ hi labhate pūrvajanmanā" },
      { type: "verse", number: "187", sanskrit: "विद्यासमाप्तावाष वा ब्रह्मं वा भिषजं ध्रुवम् तस्वमाविशति ज्ञानात्तेन वैद्यो द्विजः स्मृतः", text: "vidyāsamāptāvāṣa vā brahmaṃ vā bhiṣajaṃ dhruvam tasvamāviśati jñānāttena vaidyo dvijaḥ smṛtaḥ" },
      { type: "verse", number: "188", sanskrit: "नावध्यायेन्न चाक्रोशेदहितं न समाचरेत् प्राणाचार्यं बुधः कच्छिदिच्छन्नायुरनश्वरम्", text: "nāvadhyāyenna cākrośedahitaṃ na samācaret prāṇācāryaṃ budhaḥ kacchidicchannāyuranaśvaram" },
      { type: "verse", number: "189", sanskrit: "भिषगप्यातुरान् सर्वान् स्वसुतानिव यत्नवान् आबाधेभ्यो ऽभिसंरक्षेत् ज्ञानं धर्मनुस्मरन्", text: "bhiṣagapyāturān sarvān svasutāniva yatnavān ābādhebhyo 'bhisaṃrakṣet jñānaṃ dharmanusmaran" },
      { type: "verse", number: "190", sanskrit: "कुर्वते ये तु वृत्यर्थं चिकित्सापण्यविक्रयम् ते हित्वा काञ्चनं राशिं पांसुराशिमुपासते", text: "kurvate ye tu vṛtyarthaṃ cikitsāpaṇyavikrayam te hitvā kāñcanaṃ rāśiṃ pāṃsurāśimupāsate" },
      { type: "verse", number: "191", sanskrit: "रोगाख्यान्दारुणान्पाशानन्तकान्तिककर्षिणः यश्छित्वा यच्छति प्राणान्दाता नास्त्येव तत्समः", text: "rogākhyāndāruṇānpāśānantakāntikakarṣiṇaḥ yaśchitvā yacchati prāṇāndātā nāstyeva tatsamaḥ" },
      { type: "verse", number: "192", sanskrit: "न जीवितप्रदानाद्धि दानमन्यद्विशिष्यते तस्मादुपाचरेत् स्वेन स्वेन निःस्वतपस्विनः", text: "na jīvitapradānāddhi dānamanyadviśiṣyate tasmādupācaret svena svena niḥsvatapasvinaḥ" },
      { type: "verse", number: "193", sanskrit: "सत्वार्थमीहमानस्य वैद्यस्यैवं महामतेः वर्तन्ते सन्निधानेन नियतं सिद्धिदेवताः", text: "satvārthamīhamānasya vaidyasyaivaṃ mahāmateḥ vartante sannidhānena niyataṃ siddhidevatāḥ" },
      { type: "verse", number: "194", sanskrit: "क्वचिद्धर्मः क्वचिन्मित्रं क्वचिदर्थः क्वचिद्यशः कर्माभ्यासः क्वचिच्चेति चिकित्सा नास्ति निष्फला", text: "kvaciddharmaḥ kvacinmitraṃ kvacidarthaḥ kvacidyaśaḥ karmābhyāsaḥ kvacicceti cikitsā nāsti niṣphalā" },
      { type: "verse", number: "195", sanskrit: "नित्यमादरवान् वैद्यस्तस्मादार्तानुपाचरेत् प्राणान्सहात्मनः कीर्त्या निहन्त्येषामनादरात", text: "nityamādaravān vaidyastasmādārtānupācaret prāṇānsahātmanaḥ kīrtyā nihantyeṣāmanādarāta" },
      { type: "verse", number: "196", sanskrit: "सर्वत्र मैत्री करुणातुरेषु निरामदेहेषु नृषु प्रमोदः मनस्युपेक्षापकृतिं व्रजत्सु वैद्यस्य सद्वृत्तमलं तनोति", text: "sarvatra maitrī karuṇātureṣu nirāmadeheṣu nṛṣu pramodaḥ manasyupekṣāpakṛtiṃ vrajatsu vaidyasya sadvṛttamalaṃ tanoti" },
      { type: "verse", number: "197", sanskrit: "सामिषेणापि चित्तेन जीवितोच्छेदकारिणः यो निहन्त्यामयान् वैद्यः सोपि केनोपमीयताम्", text: "sāmiṣeṇāpi cittena jīvitocchedakāriṇaḥ yo nihantyāmayān vaidyaḥ sopi kenopamīyatām" },
      { type: "verse", number: "198", sanskrit: "किमुत निरामिषेण मनसा करुणामृदुना कृपणविशिष्टयोः सदृशमादरमुद्वहता अतिगुरु बोधिसत्वचरितं सततं विदधच्छमयति रोगजालमपि योतिविरोधि मिथः", text: "kimuta nirāmiṣeṇa manasā karuṇāmṛdunā kṛpaṇaviśiṣṭayoḥ sadṛśamādaramudvahatā atiguru bodhisatvacaritaṃ satataṃ vidadhacchamayati rogajālamapi yotivirodhi mithaḥ" },
      { type: "verse", number: "199", sanskrit: "दाहः शूलं तृडाध्मानं क्षुत्क्षामत्वमरोचकम् कः प्राकृतो जयेद्रोगान् नित्यमन्योन्यरोधिनः", text: "dāhaḥ śūlaṃ tṛḍādhmānaṃ kṣutkṣāmatvamarocakam kaḥ prākṛto jayedrogān nityamanyonyarodhinaḥ" },
      { type: "verse", number: "200", sanskrit: "मारुतामग्रहोन्भादमदान् सुसदृशाकृतीन् को जानीयाच्चिकित्सेद्वादूरभित्नक्रियाक्रमान्", text: "mārutāmagrahonbhādamadān susadṛśākṛtīn ko jānīyāccikitsedvādūrabhitnakriyākramān" },
      { type: "verse", number: "201", sanskrit: "प्राणाचार्थं वेदपारं प्रयातं बुध्या युक्तं पूजयेन्नित्यमस्मात् यस्मिन्यस्य प्राणयात्रा निबद्धा तस्मै यच्छन् को धनानां धनायेत्", text: "prāṇācārthaṃ vedapāraṃ prayātaṃ budhyā yuktaṃ pūjayennityamasmāt yasminyasya prāṇayātrā nibaddhā tasmai yacchan ko dhanānāṃ dhanāyet" },
      { type: "verse", number: "202", sanskrit: "आयुर्वेदं श्लोकलक्षेण पूव ब्रह्माम्नासीदग्निवेशादयस्तु कृत्स्नज्ञेयप्राप्तसाराः स्वतन्त्रास्तस्यैकैकं नैकधाङ्गं वितेनुः", text: "āyurvedaṃ ślokalakṣeṇa pūva brahmāmnāsīdagniveśādayastu kṛtsnajñeyaprāptasārāḥ svatantrāstasyaikaikaṃ naikadhāṅgaṃ vitenuḥ" },
      { type: "verse", number: "203", sanskrit: "भिषग्वरो वाग्भट इत्यभून्मे पितामहो नामधरो ऽस्मि यस्य सुतोभवत्तस्य च सिंहगुप्तस्तस्याप्यहं सिन्धुषु लब्धजन्मा", text: "bhiṣagvaro vāgbhaṭa ityabhūnme pitāmaho nāmadharo 'smi yasya sutobhavattasya ca siṃhaguptastasyāpyahaṃ sindhuṣu labdhajanmā" },
      { type: "verse", number: "204", sanskrit: "समधिगम्य गुरोरवलोकितात् गुरुतराच्च पितुः प्रतिभा मया सुबहुभेषजशास्त्रविलोचनात् सुविहितो ऽङ्गविभागविनिर्णयः", text: "samadhigamya guroravalokitāt gurutarācca pituḥ pratibhā mayā subahubheṣajaśāstravilocanāt suvihito 'ṅgavibhāgavinirṇayaḥ" },
      { type: "verse", number: "205", sanskrit: "पूर्वोक्तमेव वदता किमिवोदितं स्याच्छ्रद्धालुतुष्टिजननं न भवत्यपूर्वम् सङ्क्षिप्तसंशयितविस्तृतविप्रकीर्णः कृत्स्नोर्थराशिरिति साधु स एव दृष्टः", text: "pūrvoktameva vadatā kimivoditaṃ syācchraddhālutuṣṭijananaṃ na bhavatyapūrvam saṅkṣiptasaṃśayitavistṛtaviprakīrṇaḥ kṛtsnortharāśiriti sādhu sa eva dṛṣṭaḥ" },
      { type: "verse", number: "206", sanskrit: "आयुर्वेदोदधेः पारमपारस्य प्रयाति कः विश्वव्याध्यौषधिज्ञानसारस्त्वेष समुच्चितः", text: "āyurvedodadheḥ pāramapārasya prayāti kaḥ viśvavyādhyauṣadhijñānasārastveṣa samuccitaḥ" },
      { type: "verse", number: "207", sanskrit: "स्मृत्वेदमुदितं पूर्वं श्रुत्वेदानीं द्वयोः पुनः स्मर्त्तुः श्रोतुश्च सुतरां श्रद्धातुं कस्य युज्यते", text: "smṛtvedamuditaṃ pūrvaṃ śrutvedānīṃ dvayoḥ punaḥ smarttuḥ śrotuśca sutarāṃ śraddhātuṃ kasya yujyate" },
      { type: "verse", number: "208", sanskrit: "अथवा श्रुतमप्येतत् स्मर्तुरेव क्रमागतम् अभिधातृविशेषेण किं तथापि प्रयोजनम्", text: "athavā śrutamapyetat smartureva kramāgatam abhidhātṛviśeṣeṇa kiṃ tathāpi prayojanam" },
      { type: "verse", number: "209", sanskrit: "ऊर्ध्वमेति मदनं त्रिवृताधो वस्तुमात्रक इति प्रतिपाद्ये मद्विधो यदि वदेदथवात्रिः कथ्यतां क इव कर्मणि भेदः", text: "ūrdhvameti madanaṃ trivṛtādho vastumātraka iti pratipādye madvidho yadi vadedathavātriḥ kathyatāṃ ka iva karmaṇi bhedaḥ" },
      { type: "verse", number: "210", sanskrit: "साध्वसाध्विति विवेकवियुक्तो लोकपङ्क्तिकृतभक्तिविशेषः बालिशो भवति नो खलु विद्वान् सूक्त एव रमते मतिरस्य", text: "sādhvasādhviti vivekaviyukto lokapaṅktikṛtabhaktiviśeṣaḥ bāliśo bhavati no khalu vidvān sūkta eva ramate matirasya" },
      { type: "verse", number: "211", sanskrit: "इति मुनिवचनानां जीवितोपाश्रयाणामभिलषितसमृद्धौ कल्पवृक्षोपमानाम् यदुदितमिह पुण्यं कुर्वतो मेनुवादं भवतु विगतरोगो निर्वृतस्तेन लोकः", text: "iti munivacanānāṃ jīvitopāśrayāṇāmabhilaṣitasamṛddhau kalpavṛkṣopamānām yaduditamiha puṇyaṃ kurvato menuvādaṃ bhavatu vigatarogo nirvṛtastena lokaḥ" },
    ],
  },
];
